INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1995472,68,15,2,27,'Mikmaslılar: 122'),
(1995473,68,15,2,28,'Beytel ve Ay kentlerinden olanlar: 223'),
(1995474,68,15,2,29,'Nevolular: 52'),
