(1995856,68,16,7,28,'Beytazmavetliler: 42'),
(1995857,68,16,7,29,'Kiryat-Yearimliler, Kefiralılar ve Beerotlular: 743'),
(1995858,68,16,7,30,'Ramalılar ve Gevalılar: 621'),
(1995859,68,16,7,31,'Mikmaslılar: 122'),
(1995860,68,16,7,32,'Beytel ve Ay kentlerinden olanlar: 123'),
