INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1995872,68,16,7,44,'Ezgiciler: Asafoğulları: 148'),
(1995873,68,16,7,45,'Tapınak kapı nöbetçileri: Şallumoğulları, Ateroğulları, Talmonoğulları, Akkuvoğulları, Hatitaoğulları, Şovayoğulları: 138'),
(1995874,68,16,7,46,'Tapınak görevlileri: Sihaoğulları, Hasufaoğulları, Tabbaotoğulları,'),
(1995875,68,16,7,47,'Kerosoğulları, Siaoğulları, Padonoğulları,'),
(1995876,68,16,7,48,'Levanaoğulları, Hagavaoğulları, Şalmayoğulları,'),
(1995877,68,16,7,49,'Hananoğulları, Giddeloğulları, Gaharoğulları,'),
(1995878,68,16,7,50,'Reayaoğulları, Resinoğulları, Nekodaoğulları,'),
(1995879,68,16,7,51,'Gazzamoğulları, Uzzaoğulları, Paseahoğulları,'),
(1995880,68,16,7,52,'Besayoğulları, Meunimoğulları, Nefişesimoğulları,'),
(1995881,68,16,7,53,'Bakbukoğulları, Hakufaoğulları, Harhuroğulları,'),
(1995882,68,16,7,54,'Baslitoğulları, Mehidaoğulları, Harşaoğulları,'),
(1995883,68,16,7,55,'Barkosoğulları, Siseraoğulları, Temahoğulları,'),
(1995884,68,16,7,56,'Nesiahoğulları, Hatifaoğulları.'),
(1995885,68,16,7,57,'Süleymanın kullarının soyu: Sotayoğulları, Soferetoğulları, Peridaoğulları,'),
(1995886,68,16,7,58,'Yalaoğulları, Darkonoğulları, Giddeloğulları,'),
(1995887,68,16,7,59,'Şefatyaoğulları, Hattiloğulları, Pokeret-Hassevayimoğulları, Amonoğulları.'),
(1995888,68,16,7,60,'Tapınak görevlileriyle Süleymanın kullarının soyundan olanlar: 392'),
(1995889,68,16,7,61,'Tel-Melah, Tel-Harşa, Keruv, Addon ve İmmerden dönen, ancak hangi aileden olduklarını ve soylarının İsrailden geldiğini kanıtlayamayanlar şunlardır:'),
(1995890,68,16,7,62,'Delayaoğulları, Toviyaoğulları, Nekodaoğulları: 642'),
(1995891,68,16,7,63,'Kâhinlerin soyundan: Hovayaoğulları, Hakkosoğulları ve Gilatlı Barzillayın kızlarından biriyle evlenip kayınbabasının adını alan Barzillayın oğulları.'),
(1995892,68,16,7,64,'Bunlar soy kütüklerini aradılar. Ama yazılı bir kayıt bulamayınca, kâhinlik görevi ellerinden alındı.'),
(1995893,68,16,7,65,'Vali, Urim ile Tummimi kullanan bir kâhin çıkıncaya dek en kutsal yiyeceklerden yememelerini buyurdu.'),
(1995894,68,16,7,66,'Bütün halk toplam 42 360 kişiydi.'),
(1995895,68,16,7,67,'Ayrıca 7 337 erkek ve kadın köle, kadınlı erkekli 245 ezgici, 736 at, 245 katır, 435 deve, 6 720 eşek vardı.'),
(1995896,68,16,7,70,'Bazı aile başları onarım işi için bağışta bulundu: Vali hazineye 1 000 darik altın, 50 çanak, 530 kâhin mintanı bağışladı.'),
(1995897,68,16,7,71,'Bazı aile başları da iş için hazineye 20 000 darikfı altın, 2 200 mina gümüş verdiler.'),
(1995898,68,16,7,72,'Halkın geri kalanı ise, toplam 20 000 darikfı altın, 2 000 mina gümüş ve 67 kâhin mintanı verdi.'),
(1995899,68,16,7,73,'Kâhinler, Levililer, tapınak görevlileri ve kapı nöbetçileri, ezgiciler, sıradan insanlar ve bütün İsrailliler kentlerine yerleştiler.'),
(1995900,68,16,8,1,'İsrailliler kentlerine yerleştikten sonra, yedinci ay tek vücut halinde Su Kapısının karşısındaki alanda toplandılar. Bilgin Ezraya RABbin Musa aracılığıyla İsrail halkına verdiği buyrukları içeren Yasa Kitabını getirmesini söylediler.'),
(1995901,68,16,8,2,'Yedinci ayın birinci günü Kâhin Ezra Yasa Kitabını halkın toplandığı yere getirdi. Dinleyip anlayabilecek kadın erkek herkes oradaydı.'),
(1995902,68,16,8,3,'Ezra Su Kapısının karşısındaki alanda kadınların, erkeklerin ve anlayabilecek yaştaki çocukların önünde, sabahtan öğlene kadar Yasa Kitabını okudu. Herkes dikkatle dinledi.'),
(1995903,68,16,8,4,'Bilgin Ezra toplantı için hazırlanmış ahşap bir zemin üzerinde duruyordu. Sağında Mattitya, Şema, Anaya, Uriya, Hilkiya ve Maaseya vardı. Solunda ise Pedaya, Mişael, Malkiya, Haşum, Haşbaddana, Zekeriya ve Meşullam duruyordu.'),
(1995904,68,16,8,5,'Ezra halkın gözü önünde kitabı açtı. Halktan daha yüksek bir yerde duruyordu. Kitabı açar açmaz herkes ayağa kalktı.'),
(1995905,68,16,8,6,'Ezra yüce Tanrıya, RABbe övgüler sundu. Bütün halk ellerini kaldırarak, ‹‹Amin! Amin!›› diye karşılık verdi. Hep birlikte eğilip yere kapanarak RABbe tapındılar.'),
(1995906,68,16,8,7,'Levililerden Yeşu, Bani, Şerevya, Yamin, Akkuv, Şabbetay, Hodiya, Maaseya, Kelita, Azarya, Yozavat, Hanan ve Pelaya ayakta duran halka yasayı anlattılar.'),
(1995907,68,16,8,8,'Tanrının Yasa Kitabını okuyup açıkladılar, herkesin anlamasını sağlayacak biçimde yorumladılar.'),
(1995908,68,16,8,9,'Vali Nehemya, Kâhin ve Bilgin Ezra ve halka öğretmenlik yapan Levililer, ‹‹Bugün Tanrınız RAB için kutsal bir gündür. Yas tutup ağlamayın›› dediler. Çünkü bütün halk Kutsal Yasayı dinlerken ağlıyordu.'),
(1995909,68,16,8,10,'Nehemya da, ‹‹Gidin, yağlı yiyip tatlı için›› dedi, ‹‹Hazırlığı olmayanlara da bir pay gönderin. Çünkü bugün Rabbimiz için kutsal bir gündür. Üzülmeyin. RABbin verdiği sevinç sizi güçlü kılar.››'),
(1995910,68,16,8,11,'Levililer, ‹‹Sakin olun, bugün kutsal bir gündür, üzülmeyin›› diyerek halkı yatıştırdılar.'),
(1995911,68,16,8,12,'Böylece herkes yiyip içmek, yiyeceklerini başkalarıyla paylaşmak ve büyük şenlik yapmak üzere evinin yolunu tuttu. Çünkü kendilerine okunanları anlamışlardı.'),
(1995912,68,16,8,13,'Ertesi gün bütün aile başları, kâhinler ve Levililer Kutsal Yasanın buyruklarını öğrenmek için Bilgin Ezranın çevresine toplandılar.'),
(1995913,68,16,8,14,'Yasada RABbin Musa aracılığıyla verdiği şu buyruğu buldular: Yedinci ayda kutlanan bayramda İsrailliler çardaklarda oturmalı.'),
(1995914,68,16,8,15,'Bütün kentlerde ve Yeruşalimde şu duyuru yapılsın: ‹‹Dağlara çıkın; yasada yazılana uygun olarak, çardak yapmak üzere zeytin, iğde, mersin ve hurma dalları, sık yapraklı ağaç dalları getirin.››'),
(1995915,68,16,8,16,'Böylece halk dalları getirip damlarında, evlerinin ve Tanrı Tapınağının avlularında, Su Kapısı ve Efrayim Kapısı alanlarında çardaklar yaptı.'),
(1995916,68,16,8,17,'Sürgünden dönen herkes yaptığı çardakta oturdu. İsrailliler Nun oğlu Yeşunun döneminden beri böyle bir kutlama yapmamışlardı. Herkes büyük sevinç içindeydi.'),
(1995917,68,16,8,18,'Ezra ilk günden son güne kadar, her gün Tanrı''nın Yasa Kitabı''nı okudu. Yedi gün bayram yaptılar. Sekizinci gün kural uyarınca kutsal toplantı yapıldı.'),
(1995918,68,16,9,1,'Aynı ayın yirmi dördüncü günü İsrailliler toplandı. Hepsi oruç tutmuş, çul kuşanmış, başına toprak serpmişti.'),
(1995919,68,16,9,2,'İsrail soyundan gelenler bütün yabancılardan ayrılmıştı. Günahlarını ve atalarının yaptığı kötülükleri ayakta itiraf ettiler.'),
(1995920,68,16,9,3,'Oldukları yerde durup günün dörtte biri boyunca Tanrıları RABbin Yasa Kitabını okudular. Günün öbür dörtte birindeyse günahlarını itiraf ederek Tanrıları RABbe tapındılar.'),
(1995921,68,16,9,4,'Levililere yüksekçe bir yer ayrılmıştı. Yeşu, Bani, Kadmiel, Şevanya, Bunni, Şerevya, Bani ve Kenani orada oturuyordu. Ayağa kalkıp yüksek sesle Tanrıları RABbe yakardılar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1995922,68,16,9,5,'Levililerden Yeşu, Kadmiel, Bani, Haşavneya, Şerevya, Hodiya, Şevanya ve Petahya halka, ‹‹Ayağa kalkın!›› dediler, ‹‹Başlangıçtan sonsuza kadar var olan Tanrınız RABbe övgüler olsun. ‹Ya Rab senin kutsal adın öyle yücedir ki, bizim yüceltmelerimiz, övgülerimiz yetersiz kalır.› ››'),
(1995923,68,16,9,6,'Halk şöyle dua etti: ‹‹Tek RAB sensin. Gökleri, göklerin göklerini, bütün gök cisimlerini, yeryüzünü ve içindeki her şeyi, denizleri ve içlerindeki her şeyi sen yarattın. Hepsine sen can verdin. Bütün gök cisimleri sana tapınır.'),
(1995924,68,16,9,7,'‹‹Ya RAB, Avramı seçen, onu Kildanilerin Ur Kentinden çıkaran, ona İbrahim adını veren Tanrı sensin.'),
(1995925,68,16,9,8,'Onu kendine yürekten bağlı buldun ve onunla bir antlaşma yaptın. Kenanlı, Hitit, Amorlu, Perizli, Yevus ve Girgaş topraklarını onun soyuna vereceğim deyip sözünü tuttun. Çünkü sen doğrusun.'),
(1995926,68,16,9,9,'‹‹Atalarımızın Mısırda çektiklerini gördün, Kızıldenizde yakarışlarını işittin.'),
(1995927,68,16,9,10,'Firavuna, görevlilerine ve ülkesinin halkına karşı mucizeler, harikalar yarattın. Çünkü atalarımızı nasıl ezdiklerini biliyordun. Bugün olduğu gibi ün kazandın.'),
(1995928,68,16,9,11,'Denizi yararak atalarımıza yol açtın. Denizin ortasından, kuru topraktan geçip gittiler. Onları kovalayanları ise bir taş gibi azgın derin sulara fırlattın.'),
(1995929,68,16,9,12,'Gündüzün bir bulut sütunuyla, geceleyin yollarına ışık tutmak için bir ateş sütunuyla atalarımıza yol gösterdin.'),
(1995930,68,16,9,13,'‹‹Sina Dağına indin, onlarla göklerden konuştun. Onlara doğru ilkeler, adil yasalar, iyi kurallar, buyruklar verdin.'),
(1995931,68,16,9,14,'Kutsal Şabat Gününü bildirdin. Kulun Musa aracılığıyla buyruklar, kurallar, yasalar verdin.'),
(1995932,68,16,9,15,'Acıktıklarında gökten ekmek verdin, susadıklarında kayadan su çıkardın. Onlara vermeye ant içtiğin ülkeye girmelerini, orayı mülk edinmelerini buyurdun.'),
(1995933,68,16,9,16,'‹‹Ama atalarımız gurura kapıldı; dikbaşlılık edip buyruklarına uymadılar.'),
(1995934,68,16,9,17,'Söz dinlemek istemediler, aralarında yaptığın harikaları unuttular. Dikbaşlılık ettiler, eski kölelik yaşamlarına dönmek için kendilerine bir önder bularak başkaldırdılar. Ama sen bağışlayan, iyilik yapan, acıyan, tez öfkelenmeyen, sevgisi engin bir Tanrısın. Onları terk etmedin.'),
(1995935,68,16,9,18,'Kendilerine buzağı biçiminde dökme bir put yaptılar, ‹Sizi Mısırdan çıkaran Tanrınız budur!› diyerek seni çok aşağıladılar.'),
(1995936,68,16,9,19,'Yine de, yüce merhametinden ötürü onları çölde bırakmadın. Gündüzün yol göstermek için bulut sütununu, geceleyin yollarına ışık tutmak için ateş sütununu önlerinden eksik etmedin.'),
(1995937,68,16,9,20,'Onları eğitmek için iyi Ruhunu verdin. Ağızlarından manı eksiltmedin. Susadıklarında onlara su verdin.'),
(1995938,68,16,9,21,'Kırk yıl onları çölde besledin. Hiç eksikleri olmadı. Ne giysileri eskidi, ne de ayakları şişti.'),
(1995939,68,16,9,22,'‹‹Onlara ülkeler, uluslar verdin, aralarında bölüştürdün. Heşbon Kralı Sihonun, Başan Kralı Ogun ülkesini mülk edindiler.'),
(1995940,68,16,9,23,'Onlara gökteki yıldızlar kadar çocuk verdin. Onları, mülk edinmek üzere atalarına söz verdiğin ülkeye getirdin.'),
(1995941,68,16,9,24,'Çocukları Kenan ülkesini ele geçirip mülk edindiler. Ülke halkının onlara boyun eğmesini sağladın. Krallarını ve ülkedeki halkları istediklerini yapsınlar diye ellerine teslim ettin.'),
(1995942,68,16,9,25,'Surlu kentler, verimli topraklar ele geçirdiler. Güzel eşyalarla dolu evlere, kazılmış sarnıçlara, bağlara, zeytinliklere, çok sayıda meyve ağacına sahip oldular. Yediler, doydular, beslendiler ve onlara yaptığın büyük iyiliklere sevindiler.'),
(1995943,68,16,9,26,'‹‹Ama halkın söz dinlemedi, sana başkaldırdı. Yasana sırt çevirdiler, sana dönmeleri için kendilerini uyaran peygamberleri öldürdüler. Seni çok aşağıladılar.'),
(1995944,68,16,9,27,'Bu yüzden onları düşmanlarının eline teslim ettin. Düşmanları onları ezdi. Sıkıntıya düşünce sana feryat ettiler. Onları göklerden duydun, yüce merhametinden ötürü kurtarıcılar gönderdin. Bunlar halkı düşmanlarının elinden kurtardı.'),
(1995945,68,16,9,28,'‹‹Ne var ki İsrail halkı rahata kavuşunca yine senin gözünde kötü olanı yaptı. Bu yüzden onları düşmanlarının eline terk ettin. Düşmanları onlara egemen oldu. Yine sana yönelip feryat ettiler. Onları göklerden duydun ve merhametinden ötürü defalarca kurtardın.'),
(1995946,68,16,9,29,'‹‹Onları Kutsal Yasana dönmeleri için uyardınsa da, gurura kapılarak buyruklarına karşı geldiler. Kurallarını çiğneyip günah işlediler. Oysa kim kurallarına bağlı kalırsa yaşam bulur. İnatla sana sırt çevirdiler, dinlemek istemediler.'),
(1995947,68,16,9,30,'Yıllarca onlara katlandın. Ruhunla, peygamberlerin aracılığıyla onları uyardın. Ama kulak asmadılar. Bunun üzerine onları çeşitli ülke halklarının ellerine teslim ettin.'),
(1995948,68,16,9,31,'Yüce merhametinden ötürü yok olmalarına izin vermedin. Onları terk etmedin. Çünkü sen iyilik yapan, acıyan bir Tanrısın.'),
(1995949,68,16,9,32,'‹‹Ey Tanrımız! Sen antlaşmana bağlı kalırsın. Güçlü, görkemli, yüce bir Tanrısın. Asur krallarının döneminden bugüne kadar krallarımız, önderlerimiz, kâhinlerimiz, peygamberlerimiz, atalarımız ve bütün halk acı çekti. Çektiklerimizi küçümseme.'),
(1995950,68,16,9,33,'Başımıza gelen bütün olaylarda sen hep adil davrandın, doğru olanı yaptın, bizse kötülük yaptık.'),
(1995951,68,16,9,34,'Krallarımız, önderlerimiz, kâhinlerimiz, atalarımız yasana göre yaşamadılar. Verdiğin buyrukları, yaptığın uyarıları dinlemediler.'),
(1995952,68,16,9,35,'Ülkelerinde onlara sağladığın bolluk içinde, önlerine serdiğin geniş, verimli topraklarda sana kulluk etmediler, kötülüklerinden dönmediler.'),
(1995953,68,16,9,36,'‹‹Bak, bugün köleyiz. Meyvelerini, iyi ürünlerini yesinler diye atalarımıza verdiğin ülkede köle olduk.'),
(1995954,68,16,9,37,'Günahlarımız yüzünden ürünlerimizin çoğunu başımıza getirdiğin krallara veriyoruz. Bizi de, hayvanlarımızı da istedikleri gibi kullanıyorlar. Büyük sıkıntı içindeyiz.››'),
(1995955,68,16,9,38,'‹‹Bütün bu olanlardan ötürü biz İsrail halkı olarak kesin bir yazılı antlaşma yapıyoruz. Önderlerimiz, Levililerimiz ve kâhinlerimiz de antlaşmayı mühürlüyor.››'),
(1995956,68,16,10,1,'Antlaşmayı mühürleyenler şunlardı:'),
(1995957,68,16,10,2,'Kâhinler: Seraya, Azarya, Yeremya,'),
(1995958,68,16,10,3,'Paşhur, Amarya, Malkiya,'),
(1995959,68,16,10,4,'Hattuş, Şevanya, Malluk,'),
(1995960,68,16,10,5,'Harim, Meremot, Ovadya,'),
(1995961,68,16,10,6,'Daniel, Ginneton, Baruk,'),
(1995962,68,16,10,7,'Meşullam, Aviya, Miyamin,'),
(1995963,68,16,10,8,'Maazya, Bilgay, Şemaya.'),
(1995964,68,16,10,9,'Levililer: Azanya oğlu Yeşu, Henadat oğullarından Binnuy, Kadmiel;'),
(1995965,68,16,10,10,'arkadaşları Şevanya, Hodiya, Kelita, Pelaya, Hanan,'),
(1995966,68,16,10,11,'Mika, Rehov, Haşavya,'),
(1995967,68,16,10,12,'Zakkur, Şerevya, Şevanya,'),
(1995968,68,16,10,13,'Hodiya, Bani, Beninu.'),
(1995969,68,16,10,14,'Halk önderleri: Paroş, Pahat-Moav, Elam, Zattu, Bani,'),
(1995970,68,16,10,15,'Bunni, Azgat, Bevay,'),
(1995971,68,16,10,16,'Adoniya, Bigvay, Adin,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1995972,68,16,10,17,'Ater, Hizkiya, Azzur,'),
(1995973,68,16,10,18,'Hodiya, Haşum, Besay,'),
(1995974,68,16,10,19,'Harif, Anatot, Nevay,'),
(1995975,68,16,10,20,'Magpiaş, Meşullam, Hezir,'),
(1995976,68,16,10,21,'Meşezavel, Sadok, Yaddua,'),
(1995977,68,16,10,22,'Pelatya, Hanan, Anaya,'),
(1995978,68,16,10,23,'Hoşea, Hananya, Haşşuv,'),
(1995979,68,16,10,24,'Halloheş, Pilha, Şovek,'),
(1995980,68,16,10,25,'Rehum, Haşavna, Maaseya,'),
(1995981,68,16,10,26,'Ahiya, Hanan, Anan,'),
(1995982,68,16,10,27,'Malluk, Harim, Baana.'),
(1995983,68,16,10,28,'‹‹Halkın geri kalanı, kâhinler, Levililer, tapınak görevlileri ve kapı nöbetçileri, ezgiciler, Tanrının Yasası uğruna çevre halklardan ayrılmış olan herkes, karıları ve anlayıp kavrayacak yaştaki oğullarıyla, kızlarıyla birlikte'),
(1995984,68,16,10,29,'soylu kardeşlerine katıldılar. Tanrının, kulu Musa aracılığıyla verdiği yasaya göre yaşamak, Egemenimiz RABbin bütün buyruklarına, ilkelerine, kurallarına uymak üzere ant içtiler, uymayacaklara lanet okudular.'),
(1995985,68,16,10,30,'‹‹Çevremizdeki halklara kız verip kız almayacağız.'),
(1995986,68,16,10,31,'‹‹Çevre halklardan Şabat Günü ya da kutsal bir gün eşya veya tahıl satmak isteyen olursa almayacağız. Yedi yılda bir toprağı sürmeyeceğiz ve bütün alacaklarımızı sileceğiz.'),
(1995987,68,16,10,32,'‹‹Tanrımızın Tapınağının giderlerini karşılamak üzere hepimiz sorumluluk alıyoruz. Her yıl şekelin üçte birini vereceğiz. Bu para adak ekmekleri, günlük tahıl sunusu ve yakmalık sunular, Şabat günleri, Yeni Aylar ve öbür bayramlarda sunulan kurbanlar, kutsal sunular, İsrailin günahlarını bağışlatacak sunular ve Tanrımızın Tapınağının öteki işleri için harcanacak.'),
(1995988,68,16,10,34,'‹‹Kâhinler, Levililer ve halk hep birlikte kura çektik. Aileler her yıl Kutsal Yasaya uygun olarak Tanrımız RABbin sunağında yakılmak üzere belirli zamanlarda odun getirecek.'),
(1995989,68,16,10,35,'‹‹Ayrıca her yıl toprağımızın ve meyve ağaçlarımızın ilk ürününü RABbin Tapınağına götüreceğiz.'),
(1995990,68,16,10,36,'‹‹Yasaya uygun olarak, ilk doğan oğullarımızı, hayvanlarımızı, ilk doğan sığırlarımızı ve davarlarımızı Tanrımızın Tapınağına, tapınakta hizmet eden kâhinlere götüreceğiz.'),
(1995991,68,16,10,37,'‹‹Hamurlu yiyeceklerimizin, kaldırdığımız ürünlerin, bütün ağaçlarımızın meyvelerinin, yeni şarabımızın, zeytinyağımızın ilkini Tanrımızın Tapınağının depolarına getirip kâhinlere vereceğiz. Toprağımızın ondalığını Levililere vereceğiz, çünkü çalıştığımız bütün kentlerde ondalıkları onlar topluyor.'),
(1995992,68,16,10,38,'Levililer ondalıkları toplarken Harun soyundan bir kâhin yanlarında bulunacak. Levililer topladıkları ondalığın onda birini Tanrımızın Tapınağındaki depolara, hazine odalarına bırakacak.'),
(1995993,68,16,10,39,'İsrail halkıyla Levililer, buğdaydan, yeni şaraptan, zeytinyağından verilen armağanları, tapınak eşyalarının, kâhinlerin, tapınak kapı nöbetçilerinin ve ezgicilerin bulunduğu odalara koyacaklar. ‹‹Artık Tanrımız''ın Tapınağı''nı göz ardı etmeyeceğiz.››'),
(1995994,68,16,11,1,'Halkın önderleri Yeruşalime yerleşti. Geri kalanlar aralarında kura çektiler. Her on kişiden biri kutsal kente, Yeruşalime yerleşecek, öteki dokuz kişiyse kendi kentlerinde kalacaklardı.'),
(1995995,68,16,11,2,'Halk Yeruşalimde yaşamaya gönüllü olanların hepsini kutladı.'),
(1995996,68,16,11,3,'Yeruşalime yerleşen bölge önderleri şunlardır: -Ancak bazı İsrailliler, kâhinler, Levililer, tapınak görevlileri, Süleymanın kullarının soyundan gelenler Yahuda kentlerine, her biri kendi kentindeki kendi mülküne yerleşti.'),
(1995997,68,16,11,4,'Yahuda ve Benyamin halkından bazılarıysa Yeruşalimde kaldı.- Yahuda soyundan gelenler: Peres soyundan Mahalalel oğlu Şefatya oğlu Amarya oğlu Zekeriya oğlu Uzziya oğlu Ataya,'),
(1995998,68,16,11,5,'Şela soyundan Zekeriya oğlu Yoyariv oğlu Adaya oğlu Hazaya oğlu Kol-Hoze oğlu Baruk oğlu Maaseya.'),
(1995999,68,16,11,6,'Peresoğullarından Yeruşalime 468 yiğit yerleşti.'),
(1996000,68,16,11,7,'Benyamin soyundan gelenler: Yeşaya oğlu İtiel oğlu Maaseya oğlu Kolaya oğlu Pedaya oğlu Yoet oğlu Meşullam oğlu Sallu.'),
(1996001,68,16,11,8,'Onu Gabbay ve Sallay izledi; toplam 928 yiğit.'),
(1996002,68,16,11,9,'Zikri oğlu Yoel onlara önderlik ediyordu, Hassenua oğlu Yahuda ise kentte vali yardımcısıydı.'),
(1996003,68,16,11,10,'Kâhinler: Yoyariv oğlu Yedaya, Yakin,'),
(1996004,68,16,11,11,'Ahituv oğlu Merayot oğlu Sadok oğlu Meşullam oğlu Hilkiya oğlu tapınak baş görevlisi Seraya'),
(1996005,68,16,11,12,'ve tapınağa hizmet eden kardeşleri; toplam 822 kişi. Malkiya oğlu Paşhur oğlu Zekeriya oğlu Amsi oğlu Pelalya oğlu Yeroham oğlu Adaya'),
(1996006,68,16,11,13,'ve aile başları olan kardeşleri; toplam 242 kişi. İmmer oğlu Meşillemot oğlu Ahzay oğlu Azarel oğlu Amaşsay ve'),
(1996007,68,16,11,14,'kardeşlerinden oluşan 128 cesur yiğit. Haggedolim oğlu Zavdiel onlara önderlik ediyordu.'),
(1996008,68,16,11,15,'Levililer: Bunni oğlu Haşavya oğlu Azrikam oğlu Haşşuv oğlu Şemaya.'),
(1996009,68,16,11,16,'Levililerin önderlerinden Şabbetayla Yozavat Tanrı Tapınağının dış işlerini yönetiyordu.'),
(1996010,68,16,11,17,'Asaf oğlu Zavdi oğlu Mika oğlu Mattanya şükran duasını okuyan tapınak korosunu yönetiyordu. Kardeşlerinden Bakbukya ise ikinci derecede görevliydi. Ayrıca Yedutun oğlu Galal oğlu Şammua oğlu Avda vardı.'),
(1996011,68,16,11,18,'Kutsal kentte yaşayan Levililer 284 kişiydi.'),
(1996012,68,16,11,19,'Tapınak kapı nöbetçileri: Kapılarda Akkuv, Talmon ve kardeşleri nöbet tutardı. Toplam 172 kişiydiler.'),
(1996013,68,16,11,20,'İsraillilerin geri kalanı, kâhinlerle Levililer ise Yahudanın öbür kentlerine dağılmıştı. Herkes kendi mülküne yerleşmişti.'),
(1996014,68,16,11,21,'Tapınak görevlileri Ofelde yaşıyordu. Önderleri Siha ile Gişpa idi.'),
(1996015,68,16,11,22,'Tanrının Tapınağında ezgi söyleyenlere Asaf soyundan gelenler önderlik ediyordu. Bu soydan Mika oğlu Mattanya oğlu Haşavya oğlu Bani oğlu Uzzi Yeruşalimde, Levililerin başında bulunuyordu.'),
(1996016,68,16,11,23,'Pers Kralının ezgicilerle ilgili buyruğu vardı. Düzenli olarak her gün ücretlerini alacaklardı.'),
(1996017,68,16,11,24,'Yahuda oğlu Zerahın soyundan Meşezavel oğlu Petahya İsrail halkının genel temsilcisi olarak Pers Kralına yardımcı oluyordu.'),
(1996018,68,16,11,25,'Kırsal bölgelerde, köylerde yaşayanlara gelince: Bazı Yahudalılar Kiryat-Arba ve köylerinde, bazıları Divon ve köylerinde, bazıları Yekavseel ve köylerinde,'),
(1996019,68,16,11,26,'bazıları Yeşuada, Moladada, Beytpelette,'),
(1996020,68,16,11,27,'Hasar-Şualda, Beer-Şeva ve köylerinde,'),
(1996021,68,16,11,28,'bazıları Ziklakta, Mekona ve köylerinde,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996022,68,16,11,29,'bazıları Eyn-Rimmonda, Sorada, Yarmutta,'),
(1996023,68,16,11,30,'Zanoahta, Adullam ve köylerinde, bazıları Lakiş ve çevresinde, bazıları da Azeka ve köylerinde yaşıyordu. Yahudalıların yaşadığı bu yerler Beer-Şeva ile Hinnom Vadisi arasındaki toprakları kapsıyordu.'),
(1996024,68,16,11,31,'Benyamin soyundan olanlar Gevada, Mikmasta, Ayada, Beytel ve köylerinde,'),
(1996025,68,16,11,32,'Anatotta, Novda, Ananyada,'),
(1996026,68,16,11,33,'Hasorda, Ramada, Gittayimde,'),
(1996027,68,16,11,34,'Haditte, Sevoimde, Nevallatta,'),
(1996028,68,16,11,35,'Lodda, Onoda ve Esnaf Vadisinde yaşıyordu.'),
(1996029,68,16,11,36,'Bölükler halinde Yahuda''dan gelen bazı Levililer de Benyamin''e yerleşti.'),
(1996030,68,16,12,1,'Şealtiel oğlu Zerubbabil ve Yeşu ile birlikte sürgünden dönen kâhinlerle Levililer şunlardır: Kâhinler: Seraya, Yeremya, Ezra,'),
(1996031,68,16,12,2,'Amarya, Malluk, Hattuş,'),
(1996032,68,16,12,3,'Şekanya, Rehum, Meremot,'),
(1996033,68,16,12,4,'İddo, Ginneton, Aviya,'),
(1996034,68,16,12,5,'Miyamin, Maadya, Bilga,'),
(1996035,68,16,12,6,'Şemaya, Yoyariv, Yedaya,'),
(1996036,68,16,12,7,'Sallu, Amok, Hilkiya, Yedaya. Bunlar Yeşunun döneminde kâhinlere ve öbür kardeşlerine önderlik ediyorlardı.'),
(1996037,68,16,12,8,'Levililer: Yeşu, Binnuy, Kadmiel, Şerevya, Yahuda ve şükran ezgileri sorumlusu Mattanya ile kardeşleri.'),
(1996038,68,16,12,9,'Öbür kardeşleri Bakbukya ile Unni ezgiler söylenirken onların karşısında dururdu.'),
(1996039,68,16,12,10,'Yeşu Yoyakimin babasıydı. Yoyakim Elyaşivin babası, Elyaşiv Yoyadanın babası,'),
(1996040,68,16,12,11,'Yoyada Yonatanın babası, Yonatan Yadduanın babasıydı.'),
(1996041,68,16,12,12,'Yoyakimin döneminde, kâhin ailelerinin başları şunlardı: Seraya ailesinin başında Meraya, Yeremyanın Hananya,'),
(1996042,68,16,12,13,'Ezranın Meşullam, Amaryanın Yehohanan,'),
(1996043,68,16,12,14,'Melikunun Yonatan, Şevanyanın Yusuf,'),
(1996044,68,16,12,15,'Harimin Adna, Merayotun Helkay,'),
(1996045,68,16,12,16,'İddonun Zekeriya, Ginnetonun Meşullam,'),
(1996046,68,16,12,17,'Aviyanın Zikri, Minyaminin, Moadyanın Piltay,'),
(1996047,68,16,12,18,'Bilganın Şammua, Şemayanın Yehonatan,'),
(1996048,68,16,12,19,'Yoyarivin Mattenay, Yedayanın Uzzi,'),
(1996049,68,16,12,20,'Sallayın Kallay, Amokun Ever,'),
(1996050,68,16,12,21,'Hilkiyanın Haşavya, Yedayanın Netanel.'),
(1996051,68,16,12,22,'Levililerden Elyaşiv, Yoyada, Yohanan ve Yadduanın yaşadığı günlerde, Pers Kralı Dariusun döneminde, Levili aile başlarının ve kâhinlerin kaydı tutuldu.'),
(1996052,68,16,12,23,'Levili aile başlarının listesi Elyaşiv oğlu Yohananın yaşadığı döneme kadar tarihler kitabına yazıldı.'),
(1996053,68,16,12,24,'Levili önderlerden Haşavya, Şerevya ve Kadmiel oğlu Yeşu bir yanda, kardeşleri öbür yanda durur, Tanrı adamı Davutun buyruğu uyarınca karşılıklı övgüler ve şükürler sunarlardı.'),
(1996054,68,16,12,25,'Mattanya, Bakbukya, Ovadya, Meşullam, Talmon ve Akkuv kapılarda nöbet tutarak kapılara yakın ambarları korumakla görevliydiler.'),
(1996055,68,16,12,26,'Yosadak oğlu Yeşu oğlu Yoyakimin ve Vali Nehemya ile Kâhin ve Bilgin Ezranın yaşadığı dönemde bu insanlar görev yaptı.'),
(1996056,68,16,12,27,'Yeruşalim surları Tanrıya adanacağı zaman, nerede bir Levili varsa aranıp bulundu ve Yeruşalime getirildi. Çünkü surları sevinçle, şükranla, ezgilerle, zil, çenk ve lirlerle adamak istiyorlardı.'),
(1996057,68,16,12,28,'Ezgiciler Yeruşalim çevresindeki bölgelerden, Netofalıların köylerinden, Beytgilgaldan, Geva ve Azmavet çevresinden toplandı. Yeruşalim çevresinde köyler kurmuşlardı.'),
(1996058,68,16,12,30,'Kâhinlerle Levililer önce kendilerini, sonra halkı, kapıları ve surları paklama görevini yerine getirdiler.'),
(1996059,68,16,12,31,'Yahudalı önderleri surların üzerine çıkardım. Şükrederek yürüsünler diye iki büyük gruba ayırdım. Birinci grup sağdan Gübre Kapısına doğru yürüdü.'),
(1996060,68,16,12,32,'Arkalarından Hoşaya ve Yahudalı önderlerin yarısı,'),
(1996061,68,16,12,33,'Azarya, Ezra, Meşullam,'),
(1996062,68,16,12,34,'Yahuda, Benyamin, Şemaya, Yeremya'),
(1996063,68,16,12,35,'ve borazan çalan bazı kâhinler izliyordu. Asaf oğlu Zakkur oğlu Mikaya oğlu Mattanya oğlu Şemaya oğlu Yonatan oğlu Zekeriya'),
(1996064,68,16,12,36,'ve kardeşleri Şemaya, Azarel, Milalay, Gilalay, Maay, Netanel, Yahuda ve Hanani Tanrı adamı Davut gibi çalgılarıyla yürüyorlardı. Bilgin Ezra onlara öncülük ediyordu.'),
(1996065,68,16,12,37,'Pınar Kapısından Davut Kentinin merdivenlerinden dosdoğru surlara çıktılar; Davutun sarayının üst tarafından geçerek doğuya doğru, Su Kapısına kadar yürüdüler.'),
(1996066,68,16,12,38,'Şükürler sunarak yürüyen öbür grupsa surların üzerinde sola doğru ilerliyordu. Halkın yarısıyla birlikte ben de onları izledim. Fırınlar Kulesinden geçip Geniş Duvara kadar yürüdük.'),
(1996067,68,16,12,39,'Efrayim Kapısını, Eski Kapıyı, Balık Kapısını, Hananel Kulesini, Hammea Kulesini geçip Koyun Kapısına kadar gittik. Muhafızlar Kapısında durduk.'),
(1996068,68,16,12,40,'Şükürler sunarak yürüyen bu iki grup Tanrı Tapınağında durdu. Görevlilerin yarısıyla birlikte ben de durdum.'),
(1996069,68,16,12,41,'Benim grubumda borazan çalan şu kâhinler vardı: Elyakim, Maaseya, Minyamin, Mikaya, Elyoenay, Zekeriya, Hananya.'),
(1996070,68,16,12,42,'Ayrıca Maaseya, Şemaya, Elazar, Uzzi, Yehohanan, Malkiya, Elam, Ezer. Ezgiciler Yizrahyanın öncülüğünde yüksek sesle ezgiler söylediler.'),
(1996071,68,16,12,43,'O gün pek çok kurban kesildi. Halk coşku içindeydi, çünkü Tanrı onlara büyük sevinç vermişti. Kadınlarla çocuklar da bu sevince katıldılar. Yeruşalimden gelen sevinç sesleri uzaklardan duyulabiliyordu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996072,68,16,12,44,'Bu arada bağışların, ilk ürünlerin ve ondalıkların konacağı ambarları gözetecek bazı kişiler görevlendirildi. Bunlar Kutsal Yasanın kâhinler ve Levililer için öngördüğü yardımları kentlerin çevresindeki kırsal bölgelerden toplayıp ambarlara getirmekle sorumluydu. Yahudalılar kâhinlerle Levililerin hizmetinden hoşnuttu.'),
(1996073,68,16,12,45,'Çünkü onlar Tanrılarının hizmetini ve paklama görevini yerine getiriyorlardı. Ezgicilerle kapı nöbetçileri de Davutla oğlu Süleymanın buyruğuna uygun olarak sorumluluklarını yerine getirdiler.'),
(1996074,68,16,12,46,'Çünkü eskiden, Davutun ve Asafın yaşadığı yıllarda, ezgicileri yönetenler vardı. Tanrıya övgü ve şükür ezgileri söylenirdi.'),
(1996075,68,16,12,47,'Zerubbabil''in ve Nehemya''nın yaşadığı dönemde bütün İsrail halkı bağışlarıyla ezgicilerin ve kapı nöbetçilerinin ücretlerini gününde karşıladı. Levililer''in hakkını ayırdılar, Levililer de Harun soyundan gelenlerin hakkını ayırdı.'),
(1996076,68,16,13,1,'O gün Musanın Kitabı halka okundu. Kitapta Ammonlularla Moavlıların sonsuza dek Tanrının topluluğuna giremeyeceği yazılıydı.'),
(1996077,68,16,13,2,'Çünkü onlar İsrail halkına ekmek ve su vermemekle kalmamış, İsraillilere lanet okuması için Balama da para vermişlerdi. Ancak Tanrımız laneti kutsamaya çevirmişti.'),
(1996078,68,16,13,3,'İsrail halkı bu yasayı duyunca, bütün yabancıları ayrı tutmaya başladı.'),
(1996079,68,16,13,4,'Tanrımızın Tapınağının ambarlarına Kâhin Elyaşiv bakıyordu. Elyaşiv Toviyanın akrabasıydı.'),
(1996080,68,16,13,5,'Bu yüzden ona büyük bir oda vermişti. Eskiden bu odaya tahıl sunuları, günnük, tapınak eşyaları, ayrıca Kutsal Yasa uyarınca Levililere, ezgicilere, tapınak kapı nöbetçilerine verilen buğdayın, yeni şarabın, zeytinyağının ondalıkları ve kâhinlere verilen bağışlar konulurdu.'),
(1996081,68,16,13,6,'Ama bütün bunlar olup biterken ben Yeruşalimde değildim. Babil Kralı Artahşastanın krallığının otuz ikinci yılında, onun yanına gitmiştim. Bir süre sonra yine izin istedim'),
(1996082,68,16,13,7,'ve Yeruşalime döndüm. O zaman Elyaşivin yaptığı kötülüğü öğrendim. Tanrı Tapınağının avlusunda Toviyaya oda vermişti.'),
(1996083,68,16,13,8,'Buna çok canım sıkıldı. Toviyanın bütün eşyalarını odadan attım.'),
(1996084,68,16,13,9,'Odaları temizlemeleri için buyruk verdim. Tanrı Tapınağının eşyalarını, tahıl sunularını, günnüğü yine oraya koydurdum.'),
(1996085,68,16,13,10,'Ayrıca öğrendim ki, Levililerin alacakları verilmemiş. Hizmeti yürüten Levililerle ezgiciler tarlalarına geri dönmüşler.'),
(1996086,68,16,13,11,'Görevlileri azarladım. ‹‹Tanrının Tapınağı neden ihmal edilmiş?›› diye sordum. Sonra bütün gidenleri toplayıp işlerinin başına koydum.'),
(1996087,68,16,13,12,'Bütün Yahuda halkı buğdayın, yeni şarabın, zeytinyağının ondalığını yine ambarlara getirmeye başladı.'),
(1996088,68,16,13,13,'Bu kez ambarların başına Kâhin Şelemyayı, Bilgin Sadoku ve Levililerden Pedayayı koydum. Mattanya oğlu Zakkur oğlu Hanan onların yardımcısıydı. Bunlar güvenilir insanlardı. Görevleri kardeşlerinin paylarını bölüştürmekti.'),
(1996089,68,16,13,14,'Ey Tanrım, beni anımsa. Tapınağın için ve oradaki hizmetler için yaptığım iyi işleri hiçe sayma.'),
(1996090,68,16,13,15,'O günlerde Yahudada bazı adamların Şabat Günü üzüm sıktıklarını gördüm. Bazıları da demet demet tahıllarını eşeklere yüklüyor, şarap, üzüm, incir ve çeşitli yüklerle birlikte Şabat Günü Yeruşalime getiriyorlardı. Şabat Günü bunları sattıkları için onları azarladım.'),
(1996091,68,16,13,16,'Yeruşalimde yaşayan Surlular balık ve çeşitli mallar getirip Şabat Günü kentte Yahudalılara satıyorlardı.'),
(1996092,68,16,13,17,'Yahudalı soyluları azarlayarak, ‹‹Yaptığınız kötülüğe bakın!›› dedim, ‹‹Şabat Gününü hiçe sayıyorsunuz.'),
(1996093,68,16,13,18,'Atalarınız da aynı şeyi yapmadı mı? Bu yüzden Tanrımız başımıza ve bu kente bela yağdırmadı mı? Siz Şabat Gününü hiçe sayarak Tanrının öfkesini İsraile karşı alevlendiriyorsunuz.››'),
(1996094,68,16,13,19,'Şabattan önceki akşam Yeruşalim kapılarına gölge düşünce, kapıların kapatılması ve Şabat sona erinceye kadar açılmaması için buyruk verdim. Şabat Günü kente yük sokulmasın diye bazı adamlarımı kapılara yerleştirdim.'),
(1996095,68,16,13,20,'Tüccarlarla çeşitli eşya satıcıları bir iki kez geceyi Yeruşalimin dışında geçirdiler.'),
(1996096,68,16,13,21,'Onları uyardım: ‹‹Niçin surun dibinde geceliyorsunuz? Bir daha yaparsanız size karşı zor kullanacağım.›› Bir daha Şabat Günü gelmediler.'),
(1996097,68,16,13,22,'Şabat Gününün kutsallığını korumak için Levililere kendilerini paklasınlar ve gidip kapılarda nöbet tutsunlar diye buyruk verdim. Ey Tanrım, bunun için de beni anımsa ve yüce sevgin uyarınca bana merhamet et.'),
(1996098,68,16,13,23,'Ayrıca o günlerde Aşdotlu, Ammonlu, Moavlı kadınlarla evlenmiş Yahudiler gördüm.'),
(1996099,68,16,13,24,'Çocuklarının yarısı Aşdot dilini ya da öbür halkların dilini konuşuyor, Yahudi dilini bilmiyorlardı.'),
(1996100,68,16,13,25,'Adamları azarladım, lanet okudum. Bazılarını dövüp saçlarını yoldum. Tanrının adıyla onlara ant içirdim ve, ‹‹Yabancılara kız verip kız almayacaksınız›› dedim,'),
(1996101,68,16,13,26,'‹‹Kral Süleyman bu yabancı kadınlar yüzünden günaha girmedi mi? Onca ulusun kralları arasında Süleyman gibisi yoktu. Tanrı onu öyle sevdi ki, bütün İsraile kral yaptı. Ama yabancı kadınlar onu bile günaha sürükledi.'),
(1996102,68,16,13,27,'Şimdi de siz yabancı kadınlarla evlenerek Tanrımıza ihanet ediyorsunuz. Yaptığınız bu büyük kötülüğe göz mü yumalım?››'),
(1996103,68,16,13,28,'Başkâhin Elyaşiv oğlu Yoyadanın oğullarından biri Horonlu Sanballatın kızıyla evliydi. Bu yüzden onu yanımdan kovdum.'),
(1996104,68,16,13,29,'Ey Tanrım, onları anımsa; çünkü kâhinliği lekelediler, kâhinlerle ve Levililerle yaptığın antlaşmayı bozdular.'),
(1996105,68,16,13,30,'Halkı bütün yabancılardan arındırdım. Kâhinlerle Levililere görevlerini tek tek bildirdim.'),
(1996106,68,16,13,31,'Belirli zamanlarda yakılmak için armağan edilen odunları, getirilen ilk ürünleri düzene koydum. Ey Tanrım, bütün bunları iyiliğim için anımsa.'),
(1996107,68,17,1,1,'Ahaşveroş Hoddudan Kûşa uzanan bölgedeki yüz yirmi yedi ilin kralıydı.'),
(1996108,68,17,1,2,'O sırada ülkeyi Sus Kalesindeki tahtından yönetiyordu.'),
(1996109,68,17,1,3,'Krallığının üçüncü yılında bütün önderlerinin ve görevlilerinin onuruna bir şölen verdi. Pers ve Med ordu komutanları, ileri gelenler ve il valileri de oradaydı.'),
(1996110,68,17,1,4,'Ahaşveroş tam yüz seksen gün süren şenliklerle krallığının sonsuz zenginliğini, büyüklüğünün görkemini ve yüceliğini gösterdi.'),
(1996111,68,17,1,5,'Bunun ardından, sarayının avlusunda küçük büyük ayırmadan, Sus Kalesinde bulunan bütün halka yedi gün süren bir şölen verdi.'),
(1996112,68,17,1,6,'Mermer sütunlar üzerindeki gümüş çemberlere mor ve beyaz renkli iplikten yapılmış sicimlerle bağlanmış beyaz ve lacivert kumaşlar asılmıştı. Somaki, mermer, sedef ve pahalı taşlar döşenmiş avluya altın ve gümüş sedirler yerleştirilmişti.'),
(1996113,68,17,1,7,'Sarayın en iyi şarabı kralın cömertliğine yaraşır biçimde bol bol ve her biri değişik altın kupalar içinde sunuluyordu.'),
(1996114,68,17,1,8,'Kralın buyruğu uyarınca, konuklar içki içmeye zorlanmadı. Kral saray hizmetkârlarına konukların dileklerini yerine getirmeleri için buyruk vermişti.'),
(1996115,68,17,1,9,'O sırada Kraliçe Vaşti de Kral Ahaşveroşun sarayındaki kadınlara bir şölen veriyordu.'),
(1996116,68,17,1,10,'Yedinci gün, şarabın etkisiyle keyiflenen Kral Ahaşveroş, hizmetindeki yedi haremağasına -Mehuman, Bizta, Harvona, Bigta, Avagta, Zetar ve Karkasa- Kraliçe Vaştiyi başında tacıyla huzuruna getirmelerini buyurdu. Kraliçe Vaşti güzeldi. Kral halka ve önderlere onun ne kadar güzel olduğunu göstermek istiyordu.'),
(1996117,68,17,1,12,'Ama Kraliçe Vaşti haremağalarının kraldan getirdiği buyruğu reddedip gitmedi. Bunun üzerine kral çok kızdı, öfkesinden küplere bindi.'),
(1996118,68,17,1,13,'Kral yasaları bilen bilge kişilerle görüştü. Çünkü kralın, yasaları ve adaleti bilen kişilere danışması gelenektendi.'),
(1996119,68,17,1,14,'Kendisine en yakın olan Karşena, Şetar, Admata, Tarşiş, Meres, Marsena ve Memukan onunla yüzyüze görüşebiliyorlardı. Pers ve Med İmparatorluğunun bu yedi önderi krallığın en üst yöneticileriydi.'),
(1996120,68,17,1,15,'Kral Ahaşveroş onlara, ‹‹Kralın haremağaları aracılığıyla gönderdiği buyruğa uymayan Kraliçe Vaştiye yasaya göre ne yapmalı?›› diye sordu.'),
(1996121,68,17,1,16,'Memukan, kralın ve önderlerin önünde şu yanıtı verdi: ‹‹Kraliçe Vaşti yalnız krala karşı değil, bütün önderlere ve kralın bütün illerindeki halklara karşı suç işledi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996122,68,17,1,17,'Bütün kadınlar, kraliçenin davranışıyla ilgili haberi duyunca, ‹Kral Ahaşveroş Kraliçe Vaştinin huzuruna getirilmesini buyurdu, ama kraliçe gitmedi› diyerek kocalarını küçümsemeye başlayacaklar.'),
(1996123,68,17,1,18,'Bugün kraliçenin davranışını öğrenen Pers ve Medli soylu kadınlar da kralın soylu adamlarına aynı biçimde davranacak. Bu da alabildiğine kadınların küçümsemesine, erkeklerin de öfkelenmesine yol açacak.'),
(1996124,68,17,1,19,'Kral uygun görüyorsa ferman çıkarsın; bu ferman Perslerle Medlerin değişmeyen yasalarına eklensin. Buna göre Vaşti bir daha Kral Ahaşveroşun huzuruna çıkmasın ve kral ondan daha iyi birini kraliçeliğe seçsin.'),
(1996125,68,17,1,20,'Kralın fermanı büyük krallığının dört bir yanına ulaşınca, ister soylu ister halktan olsun, bütün kadınlar kocalarına saygı gösterecektir.››'),
(1996126,68,17,1,21,'Bu sözler kralın ve önderlerinin hoşuna gitti. Kral, Memukanın önerisine uyarak,'),
(1996127,68,17,1,22,'krallığın bütün illerine yazılı buyruklar gönderdi. Her ile kendi işaretleriyle ve her halka kendi diliyle yazıldı. Her erkeğin kendi evinin egemeni olduğu her dilde vurgulandı.'),
(1996128,68,17,2,1,'Bu olaylardan sonra öfkesi dinen Kral Ahaşveroş, Vaştiyi, yaptıklarını ve ona karşı alınan kararı anımsadı.'),
(1996129,68,17,2,2,'Kralın özel hizmetkârları, ‹‹Kral için genç, güzel, el değmemiş kızlar aransın›› dediler,'),
(1996130,68,17,2,3,'‹‹Kral, egemen olduğu bütün illerde görevliler atasın. Bu görevliler bütün genç, güzel, el değmemiş kızları toplayıp Sus Kalesindeki hareme getirsinler, kralın kızlardan sorumlu haremağası Hegaya teslim etsinler. Güzelleşmeleri için ne gerekiyorsa verilsin.'),
(1996131,68,17,2,4,'Sonunda kralın hoşuna giden kız, Vaştinin yerine kraliçe olsun.›› Kral bu öneriyi beğendi ve söyleneni yaptı.'),
(1996132,68,17,2,5,'Sus Kalesinde Mordekay adında bir Yahudi vardı. Benyamin oymağından olan Mordekay, Kiş oğlu Şimi oğlu Yairin oğluydu.'),
(1996133,68,17,2,6,'Kiş, Babil Kralı Nebukadnessarın Yahuda Kralı Yehoyakin ile birlikte Yeruşalimden sürgün ettiği kişilerden biriydi.'),
(1996134,68,17,2,7,'Mordekayın Hadassa adında bir amca kızı vardı. Annesiyle babasını yitiren Hadassayı Mordekay evlat edinip büyütmüştü. Hadassanın öbür adı Esterdi; endamı ve yüzü güzeldi.'),
(1996135,68,17,2,8,'Kralın buyruğu ve fermanı yayınlandıktan sonra çok sayıda genç kız Sus Kalesine getirilip harem sorumlusu Hegaya teslim edildi. Saraya getirilen kızlar arasında Ester de vardı.'),
(1996136,68,17,2,9,'Hegay Esteri beğendi ve ona ayrıcalık tanıdı. En iyi biçimde beslenip güzelleşmesi için ne gerekiyorsa hemen sağladı; ayrıca kralın sarayından seçilen yedi hizmetçiyi buyruğuna verdi. Sonra onu hizmetçileriyle birlikte haremin en güzel bölümüne yerleştirdi.'),
(1996137,68,17,2,10,'Ester halkını da, soyunu da açıklamadı. Çünkü Mordekay bunları açıklamasını yasaklamıştı.'),
(1996138,68,17,2,11,'Mordekay, Esterin nasıl olduğunu ve ona nasıl davranıldığını öğrenmek için her gün haremin avlusunun önünde gezinip dururdu.'),
(1996139,68,17,2,12,'Her genç kız sırası geldiğinde Kral Ahaşveroşun huzuruna çıkacaktı. Ama kızlarla ilgili kurallar uyarınca, önce on iki ay süren güzellik bakımını tamamlaması gerekiyordu. Altı ay süreyle her kıza mür yağı sürülüyor, altı ay da kremler, losyonlar uygulanıyordu.'),
(1996140,68,17,2,13,'Kralın yanına girme sırası gelen genç kız, haremden her istediğini alıp birlikte saraya götürürdü.'),
(1996141,68,17,2,14,'Akşam kralın yanına giren kız, ertesi sabah ikinci hareme, cariyelerden sorumlu haremağası Şaaşgazın yönetimindeki hareme dönerdi. Yalnız kralın beğendiği, adıyla çağırdığı kız yeniden onun yanına girebilirdi.'),
(1996142,68,17,2,15,'Kralın yanına girme sırası Mordekayın evlat edindiği Estere -Mordekayın amcası Avihayilin kızına- gelince, Ester, kralın kızlardan sorumlu haremağası Hegayın kendisine önerdiklerinden başka bir şey istemedi. Kendisini gören herkesin beğenisini kazandı.'),
(1996143,68,17,2,16,'Ahaşveroşun krallığının yedinci yılında, Tevet diye adlandırılan onuncu ayda, Ester saraya, kralın yanına götürüldü.'),
(1996144,68,17,2,17,'Kral Esteri öbür kızlardan daha çok sevdi, en çok ondan hoşlandı, en çok ona ayrıcalık tanıdı. Kraliçelik tacını ona giydirip Vaştinin yerine kraliçe yaptı.'),
(1996145,68,17,2,18,'Ardından Esterin onuruna büyük bir şölen verdi. Bu şölende bütün önderler ve görevliler hazır bulundu. Kral bütün illerde bayram ilan etti ve krallara yaraşır cömertlikle armağanlar dağıttı.'),
(1996146,68,17,2,19,'Kızlar ikinci kez toplandıklarında Mordekay, kralın kapı görevlilerinden biri olmuştu.'),
(1996147,68,17,2,20,'Ester, Mordekayın verdiği buyruk uyarınca, soyunu ve halkını henüz açıklamamıştı; kendisini büyüttüğü günlerde olduğu gibi, Mordekayın sözünü dinlemeye devam etti.'),
(1996148,68,17,2,21,'Mordekay kralın kapı görevlisiyken, kapı nöbetçilerinden ikisi, Bigtan ve Tereş, Kral Ahaşveroşa öfkelendiler; onu öldürmek için fırsat kollamaya başladılar.'),
(1996149,68,17,2,22,'Durumu öğrenen Mordekay bunu Kraliçe Estere iletti; o da Mordekay adına krala bildirdi.'),
(1996150,68,17,2,23,'Durum araştırıldı; doğru olduğu anlaşılınca da iki adam darağacına asıldı ve olay kralın önünde tarih kayıtlarına geçirildi.'),
(1996151,68,17,3,1,'Bu olaylardan sonra Kral Ahaşveroş, Agaklı Hammedatanın oğlu Hamanı yüksek bir göreve atayıp onurlandırdı. Onu bütün önderlerden daha yetkili kıldı.'),
(1996152,68,17,3,2,'Kralın buyruğu üzerine saray kapısında çalışan herkes Hamanın önünde eğilip yere kapanırdı. Ama Mordekay ne eğildi, ne de yere kapandı.'),
(1996153,68,17,3,3,'Kralın kapı görevlileri Mordekaya, ‹‹Kralın buyruğuna neden karşı geliyorsun?›› diye sordular.'),
(1996154,68,17,3,4,'Görevliler ona bu soruyu her gün sordularsa da Mordekay onlara kulak asmadı. Bunun üzerine durumu Hamana bildirdiler. Çünkü Mordekay onlara kendisinin Yahudi olduğunu söylemişti ve böyle davranmaya devam edip etmeyeceğini görmek istiyorlardı.'),
(1996155,68,17,3,5,'Haman, Mordekayın eğilip yere kapanmadığını görünce öfkeden kudurdu.'),
(1996156,68,17,3,6,'Yalnız onu öldürmeyi düşünmekle kalmadı, onun hangi halktan geldiğini bildiği için bütün halkını, Ahaşveroşun egemenliğinde yaşayan bütün Yahudileri ortadan kaldırmaya karar verdi.'),
(1996157,68,17,3,7,'Bu işe en uygun ayı ve günü belirlemek için Ahaşveroşun krallığının on ikinci yılında, birinci ay olan Nisanfç ayında Hamanın önünde pur, yani kura çekildi. Kura, on ikinci ay olan Adar ayına düştü. kapsardı.'),
(1996158,68,17,3,8,'Haman Kral Ahaşveroşa şöyle dedi: ‹‹Krallığının bütün illerinde, öbür halkların arasına dağılmış, onlardan ayrı yaşayan bir halk var. Yasaları bütün öbür halklarınkinden farklı; kendileri de kralın yasalarına uymazlar. Onları kendi hallerine bırakmak kralın çıkarlarına uygun düşmez.'),
(1996159,68,17,3,9,'Kral uygun görüyorsa, yok edilmeleri için yazılı bir buyruk verilsin. Ben de hazineye ödenmek üzere kralın memurlarına on bin talant gümüş vereceğim.››'),
(1996160,68,17,3,10,'Bunun üzerine kral mühür yüzüğünü parmağından çıkartıp Agaklı Hammedatanın oğlu Yahudi düşmanı Hamana verdi.'),
(1996161,68,17,3,11,'Ona, ‹‹Para sende kalsın; o halka da ne istersen yap›› dedi.'),
(1996162,68,17,3,12,'Birinci ayın on üçüncü günü kralın yazmanları çağrıldı ve Hamanın buyruğu her ile kendi işaretleriyle ve her halka kendi diliyle yazılarak satraplara, il valilerine ve bütün halk önderlerine gönderildi. Buyruk Kral Ahaşveroşun adını ve yüzüğünün mührünü taşıyordu.'),
(1996163,68,17,3,13,'Krallığın bütün illerine ulaklar aracılığıyla mektuplar gönderildi. Bu mektuplar, on ikinci ay olan Adar ayının on üçüncü günü, genç, yaşlı, kadın, çocuk, bütün Yahudilerin bir günde öldürülüp yok edilmesini, kökünün kurutulup mal mülklerinin de yağmalanmasını buyuruyordu.'),
(1996164,68,17,3,14,'Bu fermanın metni her ilde yasa olarak duyurulacak ve bütün halklara bildirilecekti. Öyle ki, herkes belirlenen gün için hazır olsun.'),
(1996165,68,17,3,15,'Ulaklar kralın buyruğuyla hemen yola çıktılar. Ferman Sus Kalesi''nde de duyuruldu. Sus halkı şaşkınlık içindeyken kral ile Haman oturmuş içki içiyorlardı.'),
(1996166,68,17,4,1,'Mordekay olup bitenleri öğrenince giysilerini yırttı, çula sarınıp başından aşağı kül döktü, yüksek sesle ve acıyla feryat ederek kent merkezine geldi.'),
(1996167,68,17,4,2,'Varıp sarayın kapısında durdu. Çünkü çula sarınmış hiç kimse bu kapıdan içeri giremezdi.'),
(1996168,68,17,4,3,'Kralın buyruğunun ve fermanının ulaştığı her ilde Yahudiler büyük yas tuttular, ağlayıp feryat ettiler, oruç tuttular. Birçoğu da çula sarınıp kül içinde yattı.'),
(1996169,68,17,4,4,'Hizmetçileriyle haremağaları gelip Mordekayın durumunu anlatınca, Kraliçe Ester çok sarsıldı. Çulunu çıkartıp giyinmesi için Mordekaya giysiler gönderdi, ama Mordekay bunları kabul etmedi.'),
(1996170,68,17,4,5,'Bunun üzerine Ester kralın kendi hizmetine atadığı haremağalarından biri olan Hatakı çağırttı; Mordekaydan ne olup bittiğini ve nedenini öğrenmesini buyurdu.'),
(1996171,68,17,4,6,'Hatak saray kapısının açıldığı kent meydanına, Mordekayın yanına gitti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996172,68,17,4,7,'Mordekay başına gelen her şeyi ona anlattı. Yahudilerin yok edilmesi için Hamanın saray hazinesine vaat ettiği paranın miktarını bile tam tamına ona bildirdi.'),
(1996173,68,17,4,8,'Estere gösterip açıklaması için Susta yayımlanan, Yahudilerin kökünün kurutulmasını isteyen fermanın bir kopyasını da ona verdi. Esterin krala çıkmasını, ondan merhamet dileyip kendi halkı için yalvarmasını istedi.'),
(1996174,68,17,4,9,'Hatak geri dönüp Mordekayın söylediklerini Estere bildirdi.'),
(1996175,68,17,4,10,'Ester Mordekaya şu haberi götürmesini buyurdu:'),
(1996176,68,17,4,11,'‹‹Kralın bütün adamları ve illerinde yaşayan halk biliyor ki, çağrılmadan sarayın iç avlusuna girip kralın yanına yaklaşan her erkek ya da kadın için tek bir ceza vardır. Kral altın asasını uzatıp canlarını bağışlamadıkça bu kişiler ölüme çarptırılır. Ben de otuz gündür kralın huzuruna çağrılmış değilim.››'),
(1996177,68,17,4,12,'Esterin bu sözleri kendisine iletilince,'),
(1996178,68,17,4,13,'Mordekay ona şu yanıtı götürmelerini istedi: ‹‹Sarayda yaşadığın için bütün Yahudiler içinde kurtulacak tek kişinin sen olacağını sanma.'),
(1996179,68,17,4,14,'Şu anda susarsan, Yahudilere yardım ve kurtuluş başka yerden gelecektir; ama sen ve babanın ev halkı yok olacaksınız. Kim bilir, belki de böyle bir gün için kraliçe oldun.››'),
(1996180,68,17,4,15,'Bunun üzerine Ester Mordekaya şu yanıtı gönderdi:'),
(1996181,68,17,4,16,'‹‹Git, Sustaki bütün Yahudileri topla; benim için oruç tutun; üç gün, üç gece hiçbir şey yemeyin, içmeyin. Hizmetçilerimle ben de sizin gibi oruç tutacağız. Ardından, kurala aykırı olduğu halde kralın huzuruna çıkacağım; ölürsem ölürüm.››'),
(1996182,68,17,4,17,'Mordekay oradan ayrıldı ve Ester''in söylediği her şeyi yaptı.'),
(1996183,68,17,5,1,'Üçüncü gün Ester kraliçe giysilerini kuşanıp sarayın iç avlusunda, taht odasının önünde durdu. Kral bu odanın giriş kapısının karşısındaki tahtında oturuyordu.'),
(1996184,68,17,5,2,'Avluda bekleyen Kraliçe Esteri görünce onu hoşgörüyle karşılayıp elindeki altın asayı ona doğru uzattı. Ester yaklaşıp asanın ucuna dokundu.'),
(1996185,68,17,5,3,'Kral ona, ‹‹Ne istiyorsun Kraliçe Ester, dileğin ne?›› diye sordu. ‹‹Krallığın yarısını bile istesen sana verilecektir.››'),
(1996186,68,17,5,4,'Ester, ‹‹Kral uygun görüyorsa, bugün kendisi için vereceğim şölene Hamanla birlikte gelsin›› diye karşılık verdi.'),
(1996187,68,17,5,5,'Kral adamlarına, ‹‹Esterin isteğini yerine getirmek için Hamanı hemen çağırın›› dedi. Böylece kralla Haman Esterin verdiği şölene gittiler.'),
(1996188,68,17,5,6,'Şarap içerlerken kral yine Estere sordu: ‹‹Söyle, ne istiyorsun? Ne istersen verilecek. Dileğin nedir? Krallığın yarısını bile istesen sana bağışlanacak.››'),
(1996189,68,17,5,7,'Ester, ‹‹İsteğim ve dileğim şu›› diye yanıtladı,'),
(1996190,68,17,5,8,'‹‹Kral benden hoşnutsa, istediğimi vermek, dileğimi yerine getirmek istiyorsa, kral ve Haman yarın kendileri için vereceğim şölene gelsinler, o zaman kralın sorusunu yanıtlarım.››'),
(1996191,68,17,5,9,'Haman o gün şölenden mutlu ve sevinçli ayrıldı. Ama Mordekayı sarayın kapısında görünce ve onun ayağa kalkmadığını, kendisine saygı göstermediğini farkedince öfkeden kudurdu.'),
(1996192,68,17,5,10,'Yine de kendini tuttu ve evine gitti. Sonra dostlarını ve eşi Zereşi çağırttı.'),
(1996193,68,17,5,11,'Onlara sonsuz zenginliğinden, çok sayıdaki oğullarından, kralın, kendisini nasıl onurlandırdığından, öbür önderlerinden ve görevlilerinden üstün tuttuğundan söz etti.'),
(1996194,68,17,5,12,'‹‹Üstelik, Kraliçe Ester, verdiği şölene kralın yanısıra yalnız beni çağırdı›› diye ekledi, ‹‹Yarınki şölene de kralla birlikte beni davet etti.'),
(1996195,68,17,5,13,'Ne var ki, o Yahudi Mordekayı sarayın kapısında otururken gördükçe bunlardan hiçbirinin gözümde değeri kalmıyor.››'),
(1996196,68,17,5,14,'Karısı Zereş ve bütün dostları Haman''a şöyle dediler: ‹‹Elli arşın yüksekliğinde bir darağacı kurulsun. Sabah olunca kraldan Mordekay''ı oraya astırmasını iste. Sonra da sevinç içinde kralla birlikte şölene gidersin.›› Haman öneriyi beğendi ve darağacını hemen kurdurdu.'),
(1996197,68,17,6,1,'O gece kralın uykusu kaçtı; tarih kayıtlarının getirilip kendisine okunmasını buyurdu.'),
(1996198,68,17,6,2,'Kayıtlar Kral Ahaşveroşu öldürmeyi tasarlamış olan iki görevliden söz ediyordu. Kapı nöbetçisi olarak görev yapmış olan Bigtan ve Tereş adındaki bu iki adamı Mordekay ele vermişti.'),
(1996199,68,17,6,3,'Kral, ‹‹Bu yaptıklarından dolayı Mordekay nasıl onurlandırıldı, ona ne ödül verildi?›› diye sordu. Hizmetkârlar, ‹‹Onun için hiçbir şey yapılmadı›› diye yanıtladılar.'),
(1996200,68,17,6,4,'Kral, ‹‹Avluda kim var?›› diye sordu. O sırada Haman sarayın dış avlusuna yeni girmişti. Kraldan, hazırlattığı darağacına Mordekayın asılmasını isteyecekti.'),
(1996201,68,17,6,5,'Hizmetkârlar krala, ‹‹Haman avluda bekliyor›› dediler. Kral, ‹‹Buraya gelsin›› dedi.'),
(1996202,68,17,6,6,'Haman içeri girince kral ona, ‹‹Kralın onurlandırmak istediği biri için ne yapılmalı?›› diye sordu. ‹‹Kral benden başka kimi onurlandırmak isteyebilir ki?›› diye düşünen Haman şu yanıtı verdi: ‹‹Kral onurlandırmak istediği kişi için kendi giydiği bir kral giysisini ve üzerine bindiği sorguçlu atı getirtir,'),
(1996203,68,17,6,9,'giysiyi ve atı en üst yöneticilerinden birine verir; o da kralın onurlandırmak istediği kişiyi giydirip atın üstünde kent meydanında gezdirir. Önden giderek, ‹Kralın onurlandırmak istediği kişiye böyle davranılır› diye bağırır.››'),
(1996204,68,17,6,10,'Kral Hamana, ‹‹Hemen git›› dedi, ‹‹Giysiyle atı al ve söylediklerini kralın kapı görevlisi Yahudi Mordekay için yap. Söylediklerinin hiçbirinde kusur etme.››'),
(1996205,68,17,6,11,'Böylece Haman giysiyi ve atı aldı, Mordekayı giydirip atın üstünde kent meydanında gezdirmeye başladı. Önden giderek, ‹‹Kralın onurlandırmak istediği kişiye böyle davranılır›› diye bağırıyordu.'),
(1996206,68,17,6,12,'Sonra Mordekay saray kapısına döndü. Haman ise utanç içinde başını örterek çabucak evine gitti.'),
(1996207,68,17,6,13,'Başına gelenleri karısı Zereşe ve bütün dostlarına anlattı. Karısı Zereş ve danışmanları ona şöyle dediler: ‹‹Önünde gerilemeye başladığın Mordekay Yahudi soyundansa, ona gücün yetmeyecek, önünde yok olup gideceksin.››'),
(1996208,68,17,6,14,'Onlar daha konuşurken, kralın haremağaları gelip Haman''ı apar topar Ester''in vereceği şölene götürdüler.'),
(1996209,68,17,7,1,'Böylece kral ve Haman, Kraliçe Esterin şölenine gittiler.'),
(1996210,68,17,7,2,'O gün şarap içerlerken kral Estere yine sordu: ‹‹İsteğin nedir, Kraliçe Ester? Ne istersen verilecek. Dileğin nedir? Krallığın yarısını bile istesen sana bağışlanacak.››'),
(1996211,68,17,7,3,'Kraliçe Ester şöyle yanıtladı: ‹‹Ey kralım, eğer benden hoşnutsan ve uygun görüyorsan, isteğim canımı bağışlaman, dileğim de halkımı esirgemendir.'),
(1996212,68,17,7,4,'Çünkü ben ve halkım öldürülüp yok edilmek, yeryüzünden silinmek üzere satıldık. Eğer köle ve cariye olarak satılmış olsaydık sesimi çıkartmazdım; böyle bir sorun için kralı rahatsız etmek uygun olmazdı.››'),
(1996213,68,17,7,5,'Kral Ahaşveroş Kraliçe Estere, ‹‹Böyle bir şeyi yapmaya cüret eden kim, nerede bu adam?›› diye sordu.'),
(1996214,68,17,7,6,'Ester, ‹‹Düşmanımız, hasmımız, işte bu kötü Hamandır!›› dedi. Haman kralla kraliçenin önünde dehşete kapıldı.'),
(1996215,68,17,7,7,'Kral öfkeyle içki masasından kalkıp sarayın bahçesine çıktı. Haman ise Kraliçe Esterden canını bağışlamasını istemek için içerde kaldı. Çünkü kralın kendisini yok etmeye kararlı olduğunu anlamıştı.'),
(1996216,68,17,7,8,'Kral sarayın bahçesinden şölen salonuna dönünce, Hamanı Esterin uzandığı sedire kapanmış olarak gördü ve, ‹‹Bu adam sarayda, gözümün önünde kraliçeye bile el uzatmaya mı kalkıyor?›› diye bağırdı. Kral sözlerini bitirir bitirmez Hamanın yüzünü örttüler.'),
(1996217,68,17,7,9,'Krala hizmet eden haremağalarından biri olan Harvona şöyle dedi: ‹‹Bakın, kralı uyarıp hayatını kurtaran Mordekay için Hamanın hazırlattığı elli arşın yüksekliğindeki darağacı Hamanın evinin önünde hazır duruyor.›› Kral, ‹‹Haman o darağacına asılsın!›› diye buyurdu.'),
(1996218,68,17,7,10,'Böylece Haman Mordekay için hazırlattığı darağacına asıldı; kralın öfkesi de yatıştı.'),
(1996219,68,17,8,1,'O gün Kral Ahaşveroş Yahudi düşmanı Hamanın malını mülkünü Kraliçe Estere verdi. Esterin Mordekaya yakınlığını açıklaması üzerine Mordekay kralın huzuruna kabul edildi.'),
(1996220,68,17,8,2,'Kral, Hamandan geri almış olduğu mühür yüzüğünü parmağından çıkarıp Mordekaya verdi. Ester de onu Hamanın malının mülkünün yöneticisi atadı.'),
(1996221,68,17,8,3,'Ester yine kralla görüştü. Ağlayarak onun ayaklarına kapandı. Agaklı Hamanın Yahudilere karşı kurduğu düzene ve kötü tasarıya engel olması için yalvardı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996222,68,17,8,4,'Kral altın asasını Estere doğru uzatınca Ester ayağa kalkıp kralın önünde durdu'),
(1996223,68,17,8,5,'ve şöyle dedi: ‹‹Kral benden hoşnutsa ve uygun görüyorsa, benden hoşlanıyorsa ve dileğimi uygun buluyorsa, Agaklı Hammedata oğlu Hamanın krallığın bütün illerinde yaşayan Yahudilerin yok edilmesini buyurmak için yazdırdığı mektupları yazılı olarak geçersiz kılsın.'),
(1996224,68,17,8,6,'Halkımın felakete uğradığını görmeye nasıl dayanırım? Soydaşlarımın öldürülmesine tanık olmaya nasıl dayanırım?››'),
(1996225,68,17,8,7,'Kral Ahaşveroş, Kraliçe Estere ve Yahudi Mordekaya, ‹‹Bakın›› dedi, ‹‹Hamanın malını mülkünü Estere verdim ve Yahudileri yok etmeyi tasarladığı için Hamanı darağacına astırdım.'),
(1996226,68,17,8,8,'Ama kral adına yazılmış ve onun yüzüğüyle mühürlenmiş yazıyı kimse geçersiz kılamaz. Bunun için, uygun gördüğünüz biçimde kral adına Yahudi sorunu konusunda şimdi siz yazın ve kralın yüzüğüyle mühürleyin.››'),
(1996227,68,17,8,9,'Bunun üzerine üçüncü ay olan Sivan ayının yirmi üçüncü günü kralın yazmanları çağrıldı. Mordekayın buyurduğu her şey, Hoddudan Kûşa dek uzanan bölgedeki yüz yirmi yedi ilde yaşayan Yahudilere, satraplara, vali ve önderlere yazıldı. Her il için kendi işaretleri, her halk için kendi dili kullanıldı. Yahudilere de kendi alfabelerinde ve kendi dillerinde yazıldı.'),
(1996228,68,17,8,10,'Mordekay Kral Ahaşveroş adına yazdırdığı mektupları kralın yüzüğüyle mühürledi ve kralın hizmetinde kullanılmak üzere yetiştirilen atlara binmiş ulaklarla her yere gönderdi.'),
(1996229,68,17,8,11,'Kral mektuplarda Yahudilere bütün kentlerde toplanma ve kendilerini koruma hakkını veriyordu. Ayrıca kendilerine, çocuklarına ve kadınlarına saldırabilecek herhangi bir düşman halkın ya da ilin silahlı güçlerini öldürüp yok etmelerine, kökünü kurutmalarına ve mallarını mülklerini yağmalamalarına izin veriyordu.'),
(1996230,68,17,8,12,'Bu izin Kral Ahaşveroşun bütün illerinde tek bir gün -on ikinci ayın, yani Adar ayının on üçüncü günü- geçerli olacaktı.'),
(1996231,68,17,8,13,'Bütün halklara duyurulan bu fermanın metni her ilde yasa yerine geçecekti. Böylece Yahudiler belirlenen gün düşmanlarından öç almaya hazır olacaklardı.'),
(1996232,68,17,8,14,'Kralın hizmetindeki atlara binen ulaklar, kralın buyruğuna uyarak hemen dörtnala yola koyuldular. Ferman Sus Kalesinde de okundu.'),
(1996233,68,17,8,15,'Mordekay, lacivert ve beyaz bir krallık giysisiyle, başında büyük bir altın taç ve sırtında ince ketenden mor bir pelerinle kralın huzurundan ayrıldı. Sus Kenti sevinç çığlıklarıyla yankılandı.'),
(1996234,68,17,8,16,'Yahudiler için aydınlık ve sevinç, mutluluk ve onur dolu günler başlamıştı.'),
(1996235,68,17,8,17,'Kralın buyruğu ve fermanı ulaştığı her ilde ve her kentte Yahudiler arasında sevinç ve mutluluğa yol açtı. Şölenler düzenlendi, bir bayram havası doğdu. Ülkedeki halklardan çok sayıda kişi Yahudi oldu; çünkü Yahudi korkusu hepsini sarmıştı.'),
(1996236,68,17,9,1,'Kralın buyruğu ve fermanı, on ikinci ay olan Adar ayının on üçüncü günü yerine getirilecekti. Yahudi düşmanları o gün Yahudileri alt etmeyi ummuşlardı, ama tam tersi oldu; Yahudiler kendilerinden nefret edenleri alt ettiler.'),
(1996237,68,17,9,2,'Yahudiler kendilerini yok etmeyi tasarlayanlara saldırmak üzere Kral Ahaşveroşun bütün illerindeki kentlerde bir araya geldiler. Hiç kimse onlara karşı koyamadı. Çünkü Yahudi korkusu bütün halkları sarmıştı.'),
(1996238,68,17,9,3,'İl önderleri, satraplar, valiler ve kralın memurları, Mordekaydan korktukları için Yahudileri desteklediler.'),
(1996239,68,17,9,4,'Mordekay sarayda güçlü biriydi artık; ünü bütün illere ulaşmıştı. Gücü gittikçe artıyordu.'),
(1996240,68,17,9,5,'Yahudiler bütün düşmanlarını kılıçtan geçirdiler, öldürdüler, yok ettiler. Kendilerinden nefret edenlere dilediklerini yaptılar.'),
(1996241,68,17,9,6,'Sus Kalesinde beş yüz kişiyi öldürüp yok ettiler.'),
(1996242,68,17,9,7,'Yahudi düşmanı Hammedata oğlu Hamanın on oğlunu -Parşandata, Dalfon, Aspata, Porata, Adalya, Aridata, Parmaşta, Arisay, Ariday ve Vayzatayı- öldürdüler. Ama yağmaya girişmediler.'),
(1996243,68,17,9,11,'Sus Kalesinde öldürülenlerin sayısı aynı gün krala bildirildi.'),
(1996244,68,17,9,12,'O da Kraliçe Estere, ‹‹Yahudiler Sus Kalesinde Hamanın on oğlu dahil beş yüz kişiyi öldürüp yok etmişler›› dedi, ‹‹Kim bilir, öbür illerimde neler yapmışlardır? İstediğin nedir, sana vereyim; başka dileğin var mı, yerine getirilecektir.››'),
(1996245,68,17,9,13,'Ester, ‹‹Eğer kral uygun görüyorsa, Sustaki Yahudiler bugünkü fermanını yarın da uygulasınlar›› dedi, ‹‹Hamanın on oğlunun cesetleri de darağacına asılsın.››'),
(1996246,68,17,9,14,'Kral bu isteklerin yerine getirilmesini buyurdu. Susta ferman çıkarıldı ve Hamanın on oğlu asıldı.'),
(1996247,68,17,9,15,'Sustaki Yahudiler Adar ayının on dördüncü günü yeniden toplanarak kentte üç yüz kişi daha öldürdüler; ama yağmaya girişmediler.'),
(1996248,68,17,9,16,'Krallığın illerinde yaşayan öbür Yahudiler de canlarını korumak ve düşmanlarından kurtulmak için bir araya geldiler. Kendilerinden nefret edenlerden yetmiş beş bin kişiyi öldürdüler, ama yağmaya girişmediler.'),
(1996249,68,17,9,17,'Bütün bunlar Adar ayının on üçüncü günü oldu. Yahudiler on dördüncü gün dinlendiler ve o günü şölen ve eğlence günü ilan ettiler.'),
(1996250,68,17,9,18,'Sustaki Yahudiler ise kendilerini savunmak için on üçüncü ve on dördüncü günler bir araya geldiler. On beşinci gün de dinlendiler. O günü şölen ve eğlence günü ilan ettiler.'),
(1996251,68,17,9,19,'Taşradaki kentlerde yaşayan Yahudiler işte bu nedenle Adar ayının on dördüncü gününü şölen ve eğlence günü olarak kutlarlar ve birbirlerine yemek sunarlar.'),
(1996252,68,17,9,20,'Mordekay bu olayları kayda geçirdi. Ardından Kral Ahaşveroşun uzak, yakın bütün illerinde yaşayan Yahudilere mektuplar gönderdi.'),
(1996253,68,17,9,21,'Her yıl Adar ayının on dördüncü ve on beşinci günlerini kutlamalarını buyurdu.'),
(1996254,68,17,9,22,'Çünkü o günler, Yahudilerin düşmanlarından kurtulduğu günlerdir. O ay kederlerinin sevince, yaslarının mutluluğa dönüştüğü aydır. Mordekay o günlerde şölenler düzenleyip eğlenmelerini, birbirlerine yemek sunmalarını, yoksullara armağanlar vermelerini buyurdu.'),
(1996255,68,17,9,23,'Böylece Yahudiler, Mordekayın buyruğunu kabul ederek başlattıkları kutlamaları sürdürdüler.'),
(1996256,68,17,9,24,'Çünkü bütün Yahudilerin düşmanı Agaklı Hammedata oğlu Haman onları yok etmek için düzen kurmuştu. Onları ezip yok etmek için pur, yani kura çekmişti.'),
(1996257,68,17,9,25,'Ama kral durumu öğrenince, Hamanın Yahudilere karşı kurduğu düzen geri tepti; kral, Hamanın ve oğullarının darağacına asılmaları için yazılı buyruklar verdi.'),
(1996258,68,17,9,26,'Pur sözcüğünden ötürü bu günlere Purim adı verildi. Böylece Yahudiler, Mordekayın mektubunda yazılı olanlardan, görüp geçirdiklerinden ve başlarına gelenlerden ötürü bu iki günü buyrulduğu biçimde ve günlerde her yıl kutlamayı kabul ettiler. Bu gelenek kendileri için, soylarından olanlar ve onlara katılan herkes için geçerli olacaktı.'),
(1996259,68,17,9,28,'Böylece bu günler her ilde, her kentte ve her ailede kuşaktan kuşağa anımsanacak ve kutlanacaktı. Purim günleri Yahudiler için son bulmayacak ve bu günlerin anısı kuşaklar boyu sürecekti.'),
(1996260,68,17,9,29,'Avihayilin kızı Kraliçe Ester ve Yahudi Mordekay Purimle ilgili bu ikinci mektubu tam yetkiyle yazıp uygulamaya koydular.'),
(1996261,68,17,9,30,'Mordekay, Ahaşveroşun egemenliği altındaki yüz yirmi yedi ilde yaşayan Yahudilere esenlik ve güvenlik dilekleriyle dolu mektuplar gönderdi.'),
(1996262,68,17,9,31,'Kraliçe Esterle birlikte daha önce kararlaştırdıkları gibi, Purim günlerini belirlenen tarihte kutlamalarını buyuruyordu. Bu kutlamalara kendilerinin de, soylarından gelenlerin de katılmalarını, oruç tutmada ve ağıt yakmada belirlenen kurallara uymalarını istedi.'),
(1996263,68,17,9,32,'Purim''e ilişkin bu düzenlemeler Ester''in buyruğuyla onaylandı ve kayda geçirildi.'),
(1996264,68,17,10,1,'Kral Ahaşveroş ülkeyi en uzak kıyılarına dek haraca bağlamıştı.'),
(1996265,68,17,10,2,'Büyüklüğü, kahramanlıkları ve Mordekayı her bakımdan nasıl onurlandırdığı Pers ve Med krallarının tarihinde yazılıdır.'),
(1996266,68,17,10,3,'Yahudi Mordekay, Kral Ahaşveroş''tan sonra ikinci adam olmuştu. Yahudi soydaşları arasında saygı gören ve çoğunluk tarafından sevilen biriydi. Çünkü halkının iyiliğini düşünüyor, bütün soydaşlarının esenliği için çaba gösteriyordu.'),
(1996267,68,18,1,1,'Ûs ülkesinde Eyüp adında bir adam yaşardı. Kusursuz, doğru bir adamdı. Tanrıdan korkar, kötülükten kaçınırdı.'),
(1996268,68,18,1,2,'Yedi oğlu, üç kızı vardı.'),
(1996269,68,18,1,3,'Yedi bin koyuna, üç bin deveye, beş yüz çift öküze, beş yüz çift eşeğe ve pek çok köleye sahipti. Doğudaki insanların en zengini oydu.'),
(1996270,68,18,1,4,'Oğulları sırayla evlerinde şölen verir, birlikte yiyip içmek için üç kızkardeşlerini de çağırırlardı.'),
(1996271,68,18,1,5,'Bu şölen dönemi bitince Eyüp onları çağırtıp kutsardı. Sabah erkenden kalkar, ‹‹Çocuklarım günah işlemiş, içlerinden Tanrıya sövmüş olabilirler›› diyerek her biri için yakmalık sunu sunardı. Eyüp hep böyle yapardı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996272,68,18,1,6,'Bir gün ilahi varlıklar RABbin huzuruna çıkmak için geldiklerinde, Şeytan da onlarla geldi.'),
(1996273,68,18,1,7,'RAB Şeytana, ‹‹Nereden geliyorsun?›› dedi. Şeytan, ‹‹Dünyada gezip dolaşmaktan›› diye yanıtladı.'),
(1996274,68,18,1,8,'RAB, ‹‹Kulum Eyüpe bakıp da düşündün mü?›› dedi, ‹‹Çünkü dünyada onun gibisi yoktur. Kusursuz, doğru bir adamdır. Tanrıdan korkar, kötülükten kaçınır.››'),
(1996275,68,18,1,9,'Şeytan, ‹‹Eyüp Tanrıdan boşuna mı korkuyor?›› diye yanıtladı.'),
(1996276,68,18,1,10,'‹‹Onu, ev halkını, sahip olduğu her şeyi sen çitle çevirip korumadın mı? Elleriyle yaptığı her şeyi bereketli kıldın. Sürüleri bütün ülkeye yayıldı.'),
(1996277,68,18,1,11,'Ama elini uzatır da sahip olduğu her şeyi yok edersen, yüzüne karşı sövecektir.››'),
(1996278,68,18,1,12,'RAB Şeytana, ‹‹Peki›› dedi, ‹‹Sahip olduğu her şeyi senin eline bırakıyorum, yalnız kendisine dokunma.›› Böylece Şeytan RABbin huzurundan ayrıldı.'),
(1996279,68,18,1,13,'Bir gün Eyüpün oğullarıyla kızları ağabeylerinin evinde yemek yiyip şarap içerken'),
(1996280,68,18,1,14,'bir ulak gelip Eyüpe şöyle dedi: ‹‹Öküzler çift sürüyor, eşekler onların yanında otluyordu.'),
(1996281,68,18,1,15,'Sabalılar baskın yaptı, hepsini alıp götürdü. Uşakları kılıçtan geçirdiler. Yalnız ben kaçıp kurtuldum sana durumu bildirmek için.››'),
(1996282,68,18,1,16,'O daha sözünü bitirmeden başka bir ulak gelip, ‹‹Tanrı ateş yağdırdı›› dedi, ‹‹Koyunlarla uşakları yakıp küle çevirdi. Yalnızca ben kaçıp kurtuldum durumu sana bildirmek için.››'),
(1996283,68,18,1,17,'O daha sözünü bitirmeden başka bir ulak gelip, ‹‹Kildaniler üç bölük halinde develere saldırdı›› dedi, ‹‹Hepsini alıp götürdüler, uşakları kılıçtan geçirdiler. Yalnızca ben kurtuldum durumu sana bildirmek için.››'),
(1996284,68,18,1,18,'O daha sözünü bitirmeden başka bir ulak gelip, ‹‹Oğullarınla kızların ağabeylerinin evinde yemek yiyip şarap içerken'),
(1996285,68,18,1,19,'ansızın çölden şiddetli bir rüzgar esti›› dedi, ‹‹Evin dört köşesine çarptı; ev gençlerin üzerine yıkıldı, hepsi öldü. Yalnız ben kurtuldum durumu sana bildirmek için.››'),
(1996286,68,18,1,20,'Bunun üzerine Eyüp kalktı, kaftanını yırtıp saçını sakalını kesti, yere kapanıp tapındı.'),
(1996287,68,18,1,21,'Dedi ki, ‹‹Bu dünyaya çıplak geldim, çıplak gideceğim. 2 RAB verdi, RAB aldı, 2 RABbin adına övgüler olsun!››'),
(1996288,68,18,1,22,'Bütün bu olaylara karşın Eyüp günah işlemedi ve Tanrı''yı suçlamadı.'),
(1996289,68,18,2,1,'Başka bir gün ilahi varlıklar RABbin huzuruna çıkmak için geldiklerinde Şeytan da RABbin huzuruna çıkmak için onlarla gelmişti.'),
(1996290,68,18,2,2,'RAB Şeytana, ‹‹Nereden geliyorsun?›› dedi. Şeytan, ‹‹Dünyada gezip dolaşmaktan›› diye yanıtladı.'),
(1996291,68,18,2,3,'RAB, ‹‹Kulum Eyüpe bakıp da düşündün mü?›› dedi, ‹‹Çünkü dünyada onun gibisi yoktur. Kusursuz, doğru bir adamdır. Tanrıdan korkar, kötülükten kaçınır. Onu boş yere yok etmek için beni kışkırttın, ama o doğruluğunu hâlâ sürdürüyor.››'),
(1996292,68,18,2,4,'‹‹Cana can!›› diye yanıtladı Şeytan, ‹‹İnsan canı için her şeyini verir.'),
(1996293,68,18,2,5,'Elini uzat da, onun etine, kemiğine dokun, yüzüne karşı sövecektir.››'),
(1996294,68,18,2,6,'RAB, ‹‹Peki›› dedi, ‹‹Onu senin eline bırakıyorum. Yalnız canına dokunma.››'),
(1996295,68,18,2,7,'Böylece Şeytan RABbin huzurundan ayrıldı. Eyüpün bedeninde tepeden tırnağa kadar kötü çıbanlar çıkardı.'),
(1996296,68,18,2,8,'Eyüp çıbanlarını kaşımak için bir çömlek parçası aldı. Kül içinde oturuyordu.'),
(1996297,68,18,2,9,'Karısı, ‹‹Hâlâ doğruluğunu sürdürüyor musun?›› dedi, ‹‹Tanrıya söv de öl bari!››'),
(1996298,68,18,2,10,'Eyüp, ‹‹Aptal kadınlar gibi konuşuyorsun›› diye karşılık verdi, ‹‹Nasıl olur? Tanrıdan gelen iyiliği kabul edelim de kötülüğü kabul etmeyelim mi?›› Bütün bu olaylara karşın Eyüpün ağzından günah sayılabilecek bir söz çıkmadı.'),
(1996299,68,18,2,11,'Eyüpün üç dostu -Temanlı Elifaz, Şuahlı Bildat, Naamalı Sofar- Eyüpün başına gelen bunca kötülüğü duyunca kalkıp bir araya geldiler. Acısını paylaşmak, onu avutmak için yanına gitmek üzere anlaştılar.'),
(1996300,68,18,2,12,'Uzaktan onu tanıyamadılar; yüksek sesle ağlayıp kaftanlarını yırtarak başlarına toprak saçtılar.'),
(1996301,68,18,2,13,'Yedi gün yedi gece onunla birlikte yere oturdular. Kimse ağzını açmadı, çünkü ne denli acı çektiğini görüyorlardı.'),
(1996302,68,18,3,1,'Sonunda Eyüp ağzını açtı ve doğduğu güne lanet edip şöyle dedi:'),
(1996303,68,18,3,3,'‹‹Doğduğum gün yok olsun, 2 ‹Bir oğul doğdu› denen gece yok olsun!'),
(1996304,68,18,3,4,'Karanlığa bürünsün o gün, 2 Yüce Tanrı onunla ilgilenmesin, 2 Üzerine ışık doğmasın.'),
(1996305,68,18,3,5,'Karanlık ve ölüm gölgesi sahip çıksın o güne, 2 Bulut çöksün üzerine; 2 Işığını karanlık söndürsün.'),
(1996306,68,18,3,6,'Zifiri karanlık yutsun o geceyi, 2 Yılın günleri arasında sayılmasın, 2 Aylardan hiçbirine girmesin.'),
(1996307,68,18,3,7,'Kısır olsun o gece, 2 Sevinç sesi duyulmasın içinde.'),
(1996308,68,18,3,8,'Günleri lanetleyenler, 2 Livyatanı uyandırmaya hazır olanlar, 2 O günü lanetlesin.'),
(1996309,68,18,3,9,'Akşamının yıldızları kararsın, 2 Boş yere aydınlığı beklesin, 2 Tan atışını görmesin.'),
(1996310,68,18,3,10,'Çünkü sıkıntı yüzü görmemem için 2 Anamın rahminin kapılarını üstüme kapamadı.'),
(1996311,68,18,3,11,'‹‹Neden doğarken ölmedim, 2 Rahimden çıkarken son soluğumu vermedim?'),
(1996312,68,18,3,12,'Neden beni dizler, 2 Emeyim diye memeler karşıladı?'),
(1996313,68,18,3,13,'Çünkü şimdi huzur içinde yatmış, 2 Uyuyup dinlenmiş olurdum;'),
(1996314,68,18,3,14,'Yaptırdıkları kentler şimdi viran olan 2 Dünya kralları ve danışmanlarıyla birlikte,'),
(1996315,68,18,3,15,'Evlerini gümüşle dolduran 2 Altın sahibi önderlerle birlikte.'),
(1996316,68,18,3,16,'Neden düşük bir çocuk gibi, 2 Gün yüzü görmemiş yavrular gibi toprağa gömülmedim?'),
(1996317,68,18,3,17,'Orada kötüler kargaşayı bırakır, 2 Yorgunlar rahat eder.'),
(1996318,68,18,3,18,'Tutsaklar huzur içinde yaşar, 2 Angaryacının sesini duymazlar.'),
(1996319,68,18,3,19,'Küçük de büyük de oradadır, 2 Köle efendisinden özgürdür.'),
(1996320,68,18,3,20,'‹‹Niçin sıkıntı çekenlere ışık, 2 Acı içindekilere yaşam verilir?'),
(1996321,68,18,3,21,'Oysa onlar gelmeyen ölümü özler, 2 Onu define arar gibi ararlar;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996322,68,18,3,22,'Mezara kavuşunca 2 Neşeden coşar, sevinç bulurlar.'),
(1996323,68,18,3,23,'Neden yaşam verilir nereye gideceğini bilmeyen insana, 2 Çevresini Tanrının çitle çevirdiği kişiye?'),
(1996324,68,18,3,24,'Çünkü iniltim ekmekten önce geliyor, 2 Su gibi dökülmekte feryadım.'),
(1996325,68,18,3,25,'Korktuğum, 2 Çekindiğim başıma geldi.'),
(1996326,68,18,3,26,'Huzur yok, sükûnet yok, rahat yok, 2 Yalnız kargaşa var.››'),
(1996327,68,18,4,1,'Temanlı Elifaz şöyle yanıtladı:'),
(1996328,68,18,4,2,'‹‹Biri sana bir şey söylemeye çalışsa gücenir misin? 2 Kim konuşmadan durabilir?'),
(1996329,68,18,4,3,'Evet, pek çoklarına sen ders verdin, 2 Zayıf elleri güçlendirdin,'),
(1996330,68,18,4,4,'Tökezleyeni senin sözlerin ayakta tuttu, 2 Titreyen dizleri sen pekiştirdin.'),
(1996331,68,18,4,5,'Ama şimdi senin başına gelince gücüne gidiyor, 2 Sana dokununca yılgınlığa düşüyorsun.'),
(1996332,68,18,4,6,'Senin güvendiğin Tanrıdan korkun değil mi, 2 Umudun kusursuz yaşamında değil mi?'),
(1996333,68,18,4,7,'‹‹Düşün biraz: Hangi suçsuz yok oldu, 2 Nerede doğrular yıkıma uğradı?'),
(1996334,68,18,4,8,'Benim gördüğüm kadarıyla, fesat sürenler, 2 Kötülük tohumu ekenler ektiklerini biçiyor.'),
(1996335,68,18,4,9,'Tanrının soluğuyla yok oluyor, 2 Öfkesinin rüzgarıyla tükeniyorlar.'),
(1996336,68,18,4,10,'Aslanın kükremesi, homurtusu kesildi, 2 Dişleri kırıldı genç aslanların.'),
(1996337,68,18,4,11,'Aslan av bulamadığı için yok oluyor, 2 Dişi aslanın yavruları dağılıyor.'),
(1996338,68,18,4,12,'‹‹Bir söz gizlice erişti bana, 2 Fısıltısı kulağıma ulaştı.'),
(1996339,68,18,4,13,'Gece rüyaların doğurduğu düşünceler içinde, 2 İnsanları ağır uyku bastığı zaman,'),
(1996340,68,18,4,14,'Beni dehşet ve titreme aldı, 2 Bütün kemiklerimi sarstı.'),
(1996341,68,18,4,15,'Önümden bir ruh geçti, 2 Tüylerim ürperdi.'),
(1996342,68,18,4,16,'Durdu, ama ne olduğunu seçemedim. 2 Bir suret duruyordu gözümün önünde, 2 Çıt çıkmazken bir ses duydum:'),
(1996343,68,18,4,17,'‹Tanrı karşısında insan doğru olabilir mi? 2 Kendisini yaratanın karşısında temiz çıkabilir mi?'),
(1996344,68,18,4,18,'Bakın, Tanrı kullarına güvenmez, 2 Meleklerinde hata bulur da,'),
(1996345,68,18,4,19,'Çamur evlerde oturanlara, 2 Mayası toprak olanlara, 2 Güveden kolay ezilenlere mi güvenir?'),
(1996346,68,18,4,20,'Ömürleri sabahtan akşama varmaz, 2 Kimse farkına varmadan sonsuza dek yok olurlar.'),
(1996347,68,18,4,21,'İçlerindeki çadır ipleri çekilince, 2 Bilgelikten yoksun olarak ölüp giderler.›'),
(1996348,68,18,5,1,'‹‹Haydi çağır, seni yanıtlayan çıkacak mı? 2 Meleklerin hangisine yöneleceksin?'),
(1996349,68,18,5,2,'Aptalı üzüntü öldürür, 2 Budalayı kıskançlık bitirir.'),
(1996350,68,18,5,3,'Ben aptalın kök saldığını görünce, 2 Hemen yurduna lanet ettim.'),
(1996351,68,18,5,4,'Çocukları güvenlikten uzak, 2 Mahkeme kapısında ezilir, 2 Savunan çıkmaz.'),
(1996352,68,18,5,5,'Ürününü açlar yer, 2 Dikenler arasındakini bile toplarlar; 2 Mallarını susamışlar yutmak ister. ‹‹Tuzak››.'),
(1996353,68,18,5,6,'Çünkü dert topraktan çıkmaz, 2 Sıkıntı yerden bitmez.'),
(1996354,68,18,5,7,'Havaya uçuşan kıvılcımlar gibi 2 Sıkıntı çekmek için doğar insan.'),
(1996355,68,18,5,8,'‹‹Oysa ben Tanrıya yönelir, 2 Davamı Ona bırakırdım.'),
(1996356,68,18,5,9,'Anlayamadığımız büyük işler, 2 Sayısız şaşılası işler yapan Odur.'),
(1996357,68,18,5,10,'Yeryüzüne yağmur yağdırır, 2 Tarlalara sular gönderir.'),
(1996358,68,18,5,11,'Düşkünleri yükseltir, 2 Yaslıları esenliğe çıkarır.'),
(1996359,68,18,5,12,'Kurnazların oyununu bozar, 2 Düzenlerini gerçekleştiremesinler diye.'),
(1996360,68,18,5,13,'Bilgeleri kurnazlıklarında yakalar, 2 Düzenbazların oyunu son bulur.'),
(1996361,68,18,5,14,'Gündüz karanlığa toslar, 2 Öğlen, geceymiş gibi el yordamıyla ararlar.'),
(1996362,68,18,5,15,'Yoksulu onların kılıç gibi ağzından 2 Ve güçlünün elinden O kurtarır.'),
(1996363,68,18,5,16,'Yoksul umutlanır, 2 Haksızlık ağzını kapar.'),
(1996364,68,18,5,17,'‹‹İşte, ne mutlu Tanrının eğittiği insana! 2 Bu yüzden Her Şeye Gücü Yetenin yola getirişini küçümseme.'),
(1996365,68,18,5,18,'Çünkü O hem yaralar hem sarar, 2 O incitir, ama elleri sağaltır.'),
(1996366,68,18,5,19,'Altı kez sıkıntıya düşsen seni kurtarır, 2 Yedinci kez de sana zarar vermez.'),
(1996367,68,18,5,20,'Kıtlıkta ölümden, 2 Savaşta kılıçtan seni O koruyacak.'),
(1996368,68,18,5,21,'Kamçılayan dillerden uzak kalacak, 2 Yıkım gelince korkmayacaksın.'),
(1996369,68,18,5,22,'Yıkıma, açlığa gülüp geçecek, 2 Yabanıl hayvanlardan ürkmeyeceksin.'),
(1996370,68,18,5,23,'Çünkü tarladaki taşlarla anlaşacaksın, 2 Yabanıl hayvanlar seninle barışacak.'),
(1996371,68,18,5,24,'Çadırının güvenlik içinde olduğunu bilecek, 2 Yurdunu yoklayınca eksik bulmayacaksın.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996372,68,18,5,25,'Çocuklarının çoğalacağını bileceksin, 2 Soyun ot gibi bitecek.'),
(1996373,68,18,5,26,'Zamanında toplanan demetler gibi, 2 Mezara dinç gireceksin.'),
(1996374,68,18,5,27,'‹‹İşte araştırdık, doğrudur, 2 Onun için bunu dinle ve belle.››'),
(1996375,68,18,6,1,'Eyüp şöyle yanıtladı:'),
(1996376,68,18,6,2,'‹‹Keşke üzüntüm tartılabilse, 2 Acım teraziye konabilseydi!'),
(1996377,68,18,6,3,'Denizlerin kumundan ağır gelirdi, 2 Bu yüzden abuk sabuk konuştum.'),
(1996378,68,18,6,4,'Çünkü Her Şeye Gücü Yetenin okları içimde, 2 Ruhum onların zehirini içiyor, 2 Tanrının dehşetleri karşıma dizildi.'),
(1996379,68,18,6,5,'Otu olan yaban eşeği anırır mı, 2 Yemi olan öküz böğürür mü?'),
(1996380,68,18,6,6,'Tatsız bir şey tuzsuz yenir mi, 2 Yumurta akında tat bulunur mu?'),
(1996381,68,18,6,7,'Böyle yiyeceklere dokunmak istemiyorum, 2 Beni hasta ediyorlar.'),
(1996382,68,18,6,8,'‹‹Keşke dileğim yerine gelse, 2 Tanrı özlediğimi bana verse!'),
(1996383,68,18,6,9,'Kerem edip beni ezse, 2 Elini çabuk tutup yaşam bağımı kesse!'),
(1996384,68,18,6,10,'Yine avunur, 2 Amansız derdime karşın sevinirdim, 2 Çünkü Kutsal Olanın sözlerini yadsımadım.'),
(1996385,68,18,6,11,'Gücüm nedir ki, bekleyeyim? 2 Sonum nedir ki, sabredeyim?'),
(1996386,68,18,6,12,'Taş kadar güçlü müyüm, 2 Etim tunçtan mı?'),
(1996387,68,18,6,13,'Çaresiz kalınca 2 Kendimi kurtaracak gücüm mü olur?'),
(1996388,68,18,6,14,'‹‹Kederli insana dost sevgisi gerekir, 2 Her Şeye Gücü Yetenden korkmaktan vaz geçse bile.'),
(1996389,68,18,6,15,'Kardeşlerim kuru bir dere gibi beni aldattı; 2 Hani gürül gürül akan dereler vardır,'),
(1996390,68,18,6,16,'Eriyen buzlarla taşan, 2 Kar sularıyla beslenen,'),
(1996391,68,18,6,17,'Ama kurak mevsimde akmayan, 2 Sıcakta yataklarında tükenen dereler... 2 İşte öyle aldattılar beni.'),
(1996392,68,18,6,18,'O dereler için kervanlar yolundan sapar, 2 Çöle çıkıp yok olurlar. 2 Temanın kervanları su arar, 2 Sabadan gelen yolcular umutla bakar.'),
(1996393,68,18,6,20,'Ama oraya varınca umut bağladıkları için utanır, 2 Hayal kırıklığına uğrarlar.'),
(1996394,68,18,6,21,'Artık siz de bir hiç oldunuz, 2 Dehşete kapılıp korkuyorsunuz.'),
(1996395,68,18,6,22,'‹Benim için bir şey verin› 2 Ya da, ‹Rüşvet verip 2 Beni düşmanın elinden kurtarın, 2 Acımasızların elinden alın› dedim mi?'),
(1996396,68,18,6,24,'‹‹Bana öğretin, susayım, 2 Yanlışımı gösterin.'),
(1996397,68,18,6,25,'Doğru söz acıdır! 2 Ama tartışmalarınız neyi kanıtlıyor?'),
(1996398,68,18,6,26,'Sözlerimi düzeltmek mi istiyorsunuz? 2 Çaresizin sözlerini boş laf mı sayıyorsunuz?'),
(1996399,68,18,6,27,'Öksüzün üzerine kura çeker, 2 Arkadaşınızın üzerine pazarlık ederdiniz.'),
(1996400,68,18,6,28,'‹‹Şimdi lütfedip bana bakın, 2 Yüzünüze karşı yalan söyleyecek değilim ya.'),
(1996401,68,18,6,29,'Bırakın artık, haksızlık etmeyin, 2 Bir daha düşünün, davamda haklıyım.'),
(1996402,68,18,6,30,'Ağzımdan haksız bir söz çıkıyor mu, 2 Damağım kötü niyeti ayırt edemiyor mu?'),
(1996403,68,18,7,1,'‹‹Yeryüzünde insan yaşamı savaşı andırmıyor mu, 2 Günleri gündelikçinin günlerinden farklı mı?'),
(1996404,68,18,7,2,'Gölgeyi özleyen köle, 2 Ücretini bekleyen gündelikçi gibi,'),
(1996405,68,18,7,3,'Miras olarak bana boş aylar verildi, 2 Payıma sıkıntılı geceler düştü.'),
(1996406,68,18,7,4,'Yatarken, ‹Ne zaman kalkacağım› diye düşünüyorum, 2 Ama gece uzadıkça uzuyor, 2 Gün doğana dek dönüp duruyorum.'),
(1996407,68,18,7,5,'Bedenimi kurt, kabuk kaplamış, 2 Çatlayan derimden irin akıyor.'),
(1996408,68,18,7,6,'‹‹Günlerim dokumacının mekiğinden hızlı, 2 Umutsuz tükenmekte.'),
(1996409,68,18,7,7,'Ey Tanrı, yaşamımın bir soluk olduğunu anımsa, 2 Gözüm bir daha mutluluk yüzü görmeyecek.'),
(1996410,68,18,7,8,'Şu anda bana bakan gözler bir daha beni görmeyecek, 2 Senin gözlerin üzerimde olacak, 2 Ama ben yok olacağım.'),
(1996411,68,18,7,9,'Bir bulutun dağılıp gitmesi gibi, 2 Ölüler diyarına inen bir daha çıkmaz.'),
(1996412,68,18,7,10,'Bir daha evine dönmez, 2 Bulunduğu yer artık onu tanımaz.'),
(1996413,68,18,7,11,'‹‹Bu yüzden sessiz kalmayacak, 2 İçimdeki sıkıntıyı dile getireceğim; 2 Canımın acısıyla yakınacağım.'),
(1996414,68,18,7,12,'Ben deniz ya da deniz canavarı mıyım ki, 2 Başıma bekçi koydun?'),
(1996415,68,18,7,13,'Yatağım beni rahatlatır, 2 Döşeğim acılarımı dindirir diye düşündüğümde,'),
(1996416,68,18,7,14,'Beni düşlerle korkutuyor, 2 Görümlerle yıldırıyorsun.'),
(1996417,68,18,7,15,'Öyle ki, boğulmayı, 2 Ölmeyi şu yaşama yeğliyorum.'),
(1996418,68,18,7,16,'Yaşamımdan tiksiniyor, 2 Sonsuza dek yaşamak istemiyorum; 2 Çek elini benden, çünkü günlerimin anlamı kalmadı.'),
(1996419,68,18,7,17,'‹‹İnsan ne ki, onu büyütesin, 2 Üzerinde kafa yorasın,'),
(1996420,68,18,7,18,'Her sabah onu yoklayasın, 2 Her an onu sınayasın?'),
(1996421,68,18,7,19,'Gözünü üzerimden hiç ayırmayacak mısın, 2 Tükürüğümü yutacak kadar bile beni rahat bırakmayacak mısın?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996422,68,18,7,20,'Günah işledimse, ne yaptım sana, 2 Ey insan gözcüsü? 2 Niçin beni kendine hedef seçtin? 2 Sana yük mü oldum?'),
(1996423,68,18,7,21,'Niçin isyanımı bağışlamaz, 2 Suçumu affetmezsin? 2 Çünkü yakında toprağa gireceğim, 2 Beni çok arayacaksın, ama ben artık olmayacağım.››'),
(1996424,68,18,8,1,'Şuahlı Bildat şöyle yanıtladı:'),
(1996425,68,18,8,2,'‹‹Ne zamana dek böyle konuşacaksın? 2 Sözlerin sert rüzgar gibi.'),
(1996426,68,18,8,3,'Tanrı adaleti saptırır mı, 2 Her Şeye Gücü Yeten doğru olanı çarpıtır mı?'),
(1996427,68,18,8,4,'Oğulların ona karşı günah işlediyse, 2 İsyanlarının cezasını vermiştir.'),
(1996428,68,18,8,5,'Ama sen gayretle Tanrıyı arar, 2 Her Şeye Gücü Yetene yalvarırsan,'),
(1996429,68,18,8,6,'Temiz ve doğruysan, 2 O şimdi bile senin için kolları sıvayıp 2 Seni hak ettiğin yere geri getirecektir.'),
(1996430,68,18,8,7,'Başlangıcın küçük olsa da, 2 Sonun büyük olacak.'),
(1996431,68,18,8,8,'‹‹Lütfen, önceki kuşaklara sor, 2 Atalarının neler öğrendiğini iyice araştır.'),
(1996432,68,18,8,9,'Çünkü biz daha dün doğduk, bir şey bilmeyiz, 2 Yeryüzündeki günlerimiz sadece bir gölge.'),
(1996433,68,18,8,10,'Onlar sana anlatıp öğretmeyecek, 2 İçlerindeki sözleri dile getirmeyecek mi?'),
(1996434,68,18,8,11,'‹‹Bataklık olmayan yerde kamış biter mi? 2 Susuz yerde saz büyür mü?'),
(1996435,68,18,8,12,'Henüz yeşilken, kesilmeden, 2 Otlardan önce kururlar.'),
(1996436,68,18,8,13,'Tanrıyı unutan herkesin sonu böyledir, 2 Tanrısız insanın umudu böyle yok olur.'),
(1996437,68,18,8,14,'Onun güvendiği şey kırılır, 2 Dayanağı ise bir örümcek ağıdır.'),
(1996438,68,18,8,15,'Örümcek ağına yaslanır, ama ağ çöker, 2 Ona tutunur, ama ağ taşımaz.'),
(1996439,68,18,8,16,'Tanrısızlar güneşte iyi sulanmış bitkiyi andırır, 2 Dalları bahçenin üzerinden aşar;'),
(1996440,68,18,8,17,'Kökleri taş yığınına sarılır, 2 Çakılların arasında yer aranır.'),
(1996441,68,18,8,18,'Ama yerinden sökülürse, 2 Yeri, ‹Seni hiç görmedim› diyerek onu yadsır.'),
(1996442,68,18,8,19,'İşte sevinci böyle son bulur, 2 Yerinde başka bitkiler biter.'),
(1996443,68,18,8,20,'‹‹Tanrı kusursuz insanı reddetmez, 2 Kötülük edenlerin elinden tutmaz.'),
(1996444,68,18,8,21,'O senin ağzını yine gülüşle, 2 Dudaklarını sevinç haykırışıyla dolduracaktır.'),
(1996445,68,18,8,22,'Düşmanlarını utanç kaplayacak, 2 Kötülerin çadırı yok olacaktır.››'),
(1996446,68,18,9,1,'Eyüp şöyle yanıtladı:'),
(1996447,68,18,9,2,'‹‹Biliyorum, gerçekten öyledir, 2 Ama Tanrının önünde insan nasıl haklı çıkabilir?'),
(1996448,68,18,9,3,'Biri Onunla tartışmak istese, 2 Binde bir bile Ona yanıt veremez.'),
(1996449,68,18,9,4,'Onun bilgisi derin, gücü eşsizdir, 2 Kim Ona direndi de ayakta kaldı?'),
(1996450,68,18,9,5,'O dağları yerinden oynatır da, 2 Dağlar farkına varmaz, 2 Öfkeyle altüst eder onları.'),
(1996451,68,18,9,6,'Dünyayı yerinden oynatır, 2 Direklerini titretir.'),
(1996452,68,18,9,7,'Güneşe buyruk verir, doğmaz güneş, 2 Yıldızları mühürler.'),
(1996453,68,18,9,8,'Odur tek başına gökleri geren, 2 Denizin dalgaları üzerinde yürüyen.'),
(1996454,68,18,9,9,'Büyük Ayıyı, Oryonu, Ülkeri, 2 Güney takımyıldızlarını yaratan Odur.'),
(1996455,68,18,9,10,'Anlayamadığımız büyük işler, 2 Sayısız şaşılası işler yapan Odur.'),
(1996456,68,18,9,11,'İşte, yanımdan geçer, Onu göremem, 2 Geçip gider, farkına bile varmam.'),
(1996457,68,18,9,12,'Evet, O avını kaparsa, kim Onu durdurabilir? 2 Kim Ona, ‹Ne yapıyorsun› diyebilir?'),
(1996458,68,18,9,13,'Tanrı öfkesini dizginlemez, 2 Rahavın yardımcıları bile 2 Onun ayağına kapanır. güçlerini simgeleyen bir deniz canavarı.'),
(1996459,68,18,9,14,'‹‹Nerde kaldı ki, ben Ona yanıt vereyim, 2 Onunla tartışmak için söz bulayım?'),
(1996460,68,18,9,15,'Haklı olsam da Ona yanıt veremez, 2 Merhamet etmesi için yargıcıma yalvarırdım ancak.'),
(1996461,68,18,9,16,'Onu çağırsam, O da bana yanıt verseydi, 2 Yine de inanmazdım sesime kulak verdiğine.'),
(1996462,68,18,9,17,'O beni kasırgayla eziyor, 2 Nedensiz yaralarımı çoğaltıyor.'),
(1996463,68,18,9,18,'Soluk almama izin vermiyor, 2 Ancak beni acıya doyuruyor.'),
(1996464,68,18,9,19,'Sorun güç sorunuysa, O güçlüdür! 2 Adalet sorunuysa, kim Onu mahkemeye çağırabilir?'),
(1996465,68,18,9,20,'Suçsuz olsam ağzım beni suçlar, 2 Kusursuz olsam beni suçlu çıkarır.'),
(1996466,68,18,9,21,'‹‹Kusursuz olsam da kendime aldırdığım yok, 2 Yaşamımı hor görüyorum.'),
(1996467,68,18,9,22,'Hepsi bir, bu yüzden diyorum ki, 2 ‹O suçluyu da suçsuzu da yok ediyor.›'),
(1996468,68,18,9,23,'Kırbaç ansızın ölüm saçınca, 2 O suçsuzların sıkıntısıyla eğlenir.'),
(1996469,68,18,9,24,'Dünya kötülerin eline verilmiş, 2 Yargıçların gözünü kapayan Odur. 2 O değilse, kimdir?'),
(1996470,68,18,9,25,'‹‹Günlerim koşucudan çabuk, 2 İyilik görmeden geçmekte.'),
(1996471,68,18,9,26,'Kamış sandal gibi kayıp gidiyor, 2 Avının üstüne süzülen kartal gibi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996472,68,18,9,27,'‹Acılarımı unutayım, 2 Üzgün çehremi değiştirip gülümseyeyim› desem,'),
(1996473,68,18,9,28,'Bütün dertlerimden yılarım, 2 Çünkü beni suçsuz saymayacağını biliyorum.'),
(1996474,68,18,9,29,'Madem suçlanacağım, 2 Neden boş yere uğraşayım?'),
(1996475,68,18,9,30,'Sabun otuyla yıkansam, 2 Ellerimi kül suyuyla temizlesem,'),
(1996476,68,18,9,31,'Beni yine pisliğe batırırsın, 2 Giysilerim bile benden tiksinir.'),
(1996477,68,18,9,32,'O benim gibi bir insan değil ki, 2 Ona yanıt vereyim, 2 Birlikte mahkemeye gideyim.'),
(1996478,68,18,9,33,'Keşke aramızda bir hakem olsa da, 2 Elini ikimizin üstüne koysa!'),
(1996479,68,18,9,34,'Tanrı sopasını üzerimden kaldırsın, 2 Dehşeti beni yıldırmasın.'),
(1996480,68,18,9,35,'O zaman konuşur, O''ndan korkmazdım, 2 Ama bu durumda bir şey yapamam.'),
(1996481,68,18,10,1,'‹‹Yaşamımdan usandım, 2 Özgürce yakınacak, 2 İçimdeki acıyla konuşacağım.'),
(1996482,68,18,10,2,'Tanrıya: Beni suçlama diyeceğim, 2 Ama söyle, niçin benimle çekişiyorsun.'),
(1996483,68,18,10,3,'Hoşuna mı gidiyor gaddarlık etmek, 2 Kendi ellerinin emeğini reddedip 2 Kötülerin tasarılarını onaylamak?'),
(1996484,68,18,10,4,'Sende insan gözü mü var? 2 İnsanın gördüğü gibi mi görüyorsun?'),
(1996485,68,18,10,5,'Günlerin ölümlü birinin günleri gibi, 2 Yılların insanın yılları gibi mi ki,'),
(1996486,68,18,10,6,'Suçumu arıyor, 2 Günahımı araştırıyorsun?'),
(1996487,68,18,10,7,'Kötü olmadığımı, 2 Senin elinden beni kimsenin kurtaramayacağını biliyorsun.'),
(1996488,68,18,10,8,'‹‹Senin ellerin bana biçim verdi, beni yarattı, 2 Şimdi dönüp beni yok mu edeceksin?'),
(1996489,68,18,10,9,'Lütfen anımsa, balçık gibi bana sen biçim verdin, 2 Beni yine toprağa mı döndüreceksin?'),
(1996490,68,18,10,10,'Beni süt gibi dökmedin mi, 2 Peynir gibi katılaştırmadın mı?'),
(1996491,68,18,10,11,'Bana et ve deri giydirdin, 2 Beni kemiklerle, sinirlerle ördün.'),
(1996492,68,18,10,12,'Bana yaşam verdin, sevgi gösterdin, 2 İlgin ruhumu korudu.'),
(1996493,68,18,10,13,'‹‹Ama bunları yüreğinde gizledin, 2 Biliyorum aklındakini:'),
(1996494,68,18,10,14,'Günah işleseydim, beni gözlerdin, 2 Suçumu cezasız bırakmazdın.'),
(1996495,68,18,10,15,'Suçluysam, vay başıma! 2 Suçsuzken bile başımı kaldıramıyorum, 2 Çünkü utanç doluyum, çaresizim.'),
(1996496,68,18,10,16,'Başımı kaldırsam, aslan gibi beni avlar, 2 Şaşılası gücünü yine gösterirsin üstümde.'),
(1996497,68,18,10,17,'Bana karşı yeni tanıklar çıkarır, 2 Öfkeni artırırsın. 2 Orduların dalga dalga üzerime geliyor.'),
(1996498,68,18,10,18,'‹‹Niçin doğmama izin verdin? 2 Keşke ölseydim, hiçbir göz beni görmeden!'),
(1996499,68,18,10,19,'Hiç var olmamış olurdum, 2 Rahimden mezara taşınırdım.'),
(1996500,68,18,10,20,'Birkaç günlük ömrüm kalmadı mı? 2 Beni rahat bırak da biraz yüzüm gülsün;'),
(1996501,68,18,10,21,'Dönüşü olmayan yere gitmeden önce, 2 Karanlık ve ölüm gölgesi diyarına,'),
(1996502,68,18,10,22,'Zifiri karanlık diyarına, 2 Ölüm gölgesi, kargaşa diyarına, 2 Aydınlığın karanlığı andırdığı yere.››'),
(1996503,68,18,11,1,'Naamalı Sofar şöyle yanıtladı:'),
(1996504,68,18,11,2,'‹‹Bunca söz yanıtsız mı kalsın? 2 Çok konuşan haklı mı sayılsın?'),
(1996505,68,18,11,3,'Saçmalıkların karşısında sussun mu insanlar? 2 Sen alay edince kimse seni utandırmasın mı?'),
(1996506,68,18,11,4,'Tanrıya, ‹İnancım arıdır› diyorsun, 2 ‹Senin gözünde temizim.›'),
(1996507,68,18,11,5,'Ama keşke Tanrı konuşsa, 2 Sana karşı ağzını açsa da,'),
(1996508,68,18,11,6,'Bilgeliğin sırlarını bildirse! 2 Çünkü bilgelik çok yönlüdür. 2 Bil ki, Tanrı günahlarından bazılarını unuttu bile.'),
(1996509,68,18,11,7,'‹‹Tanrının derin sırlarını anlayabilir misin? 2 Her Şeye Gücü Yetenin sınırlarına ulaşabilir misin?'),
(1996510,68,18,11,8,'Onlar gökler kadar yüksektir, ne yapabilirsin? 2 Ölüler diyarından derindir, nasıl anlayabilirsin?'),
(1996511,68,18,11,9,'Ölçüleri yeryüzünden uzun, 2 Denizden geniştir.'),
(1996512,68,18,11,10,'‹‹Gelip seni hapsetse, mahkemeye çağırsa, 2 Kim Ona engel olabilir?'),
(1996513,68,18,11,11,'Çünkü O yalancıları tanır, 2 Kötülüğü görür de dikkate almaz mı?'),
(1996514,68,18,11,12,'Ne zaman yaban eşeği insan doğurursa, 2 Aptal da o zaman sağduyulu olur.'),
(1996515,68,18,11,13,'‹‹Ona yüreğini adar, 2 Ellerini açarsan,'),
(1996516,68,18,11,14,'İşlediğin günahı kendinden uzaklaştırır, 2 Çadırında haksızlığa yer vermezsen,'),
(1996517,68,18,11,15,'Utanmadan başını kaldırır, 2 Sağlam ve korkusuz olabilirsin.'),
(1996518,68,18,11,16,'Sıkıntılarını unutur, 2 Akıp gitmiş sular gibi anarsın onları.'),
(1996519,68,18,11,17,'Yaşamın öğlen güneşinden daha parlak olur, 2 Karanlık sabaha döner.'),
(1996520,68,18,11,18,'Güven duyarsın, çünkü umudun olur, 2 Çevrene bakıp güvenlik içinde yatarsın.'),
(1996521,68,18,11,19,'Uzanırsın, korkutan olmaz, 2 Birçokları senden lütuf diler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996522,68,18,11,20,'Ama kötülerin gözlerinin feri sönecek, 2 Kaçacak yer bulamayacaklar, 2 Tek umutları son soluklarını vermek olacak.››'),
(1996523,68,18,12,1,'Eyüp şöyle yanıtladı:'),
(1996524,68,18,12,2,'‹‹Kendinizi birşey sandığınız belli, 2 Ama bilgelik de sizinle birlikte ölecek!'),
(1996525,68,18,12,3,'Sizin kadar benim de aklım var, 2 Sizden aşağı kalmam. 2 Kim bilmez bunları?'),
(1996526,68,18,12,4,'‹‹Gülünç oldum dostlarıma, 2 Ben ki, Tanrıya yakarırdım, yanıtlardı beni. 2 Doğru ve kusursuz adam gülünç oldu.'),
(1996527,68,18,12,5,'Kaygısızlar felaketi küçümser, 2 Ayağı kayanı umursamaz.'),
(1996528,68,18,12,6,'Soyguncuların çadırlarında rahatlık var, 2 Tanrıyı gazaba getirenler güvenlik içinde, 2 Tanrıya değil, kendi bileklerine güveniyorlar.'),
(1996529,68,18,12,7,'‹‹Ama şimdi sor hayvanlara, sana öğretsinler, 2 Gökte uçan kuşlara sor, sana anlatsınlar,'),
(1996530,68,18,12,8,'Toprağa söyle, sana öğretsin, 2 Denizdeki balıklara sor, sana bilgi versinler.'),
(1996531,68,18,12,9,'Hangisi bilmez 2 Bunu RABbin yaptığını?'),
(1996532,68,18,12,10,'Her yaratığın canı, 2 Bütün insanlığın soluğu Onun elindedir.'),
(1996533,68,18,12,11,'Damağın yemeği tattığı gibi 2 Kulak da sözleri denemez mi?'),
(1996534,68,18,12,12,'Bilgelik yaşlılarda, 2 Akıl uzun yaşamdadır.'),
(1996535,68,18,12,13,'‹‹Bilgelik ve güç Tanrıya özgüdür, 2 Ondadır öğüt ve akıl.'),
(1996536,68,18,12,14,'Onun yıktığı onarılamaz, 2 Onun hapsettiği kişi özgür olamaz.'),
(1996537,68,18,12,15,'Suları tutarsa, kuraklık olur, 2 Salıverirse dünyayı sel götürür.'),
(1996538,68,18,12,16,'Güç ve zafer Ona aittir, 2 Aldanan da aldatan da Onundur.'),
(1996539,68,18,12,17,'Danışmanları çaresiz kılar, 2 Yargıçları çıldırtır.'),
(1996540,68,18,12,18,'Kralların bağladığı bağı çözer, 2 Bellerine kuşak bağlar.'),
(1996541,68,18,12,19,'Kâhinleri çaresiz kılar, 2 Koltuklarında yıllananları devirir.'),
(1996542,68,18,12,20,'Güvenilir danışmanları susturur, 2 Yaşlıların aklını alır.'),
(1996543,68,18,12,21,'Rezalet saçar soylular üzerine, 2 Güçlülerin kuşağını gevşetir.'),
(1996544,68,18,12,22,'Karanlıkların derin sırlarını açar, 2 Ölüm gölgesini aydınlığa çıkarır.'),
(1996545,68,18,12,23,'Ulusları büyütür, ulusları yok eder, 2 Ulusları genişletir, ulusları sürgün eder.'),
(1996546,68,18,12,24,'Dünya önderlerinin aklını başından alır, 2 Yolu izi belirsiz bir çölde dolaştırır onları.'),
(1996547,68,18,12,25,'Karanlıkta el yordamıyla yürür, ışık yüzü görmezler; 2 Sarhoş gibi dolaştırır onları.'),
(1996548,68,18,13,1,'‹‹İşte, gözlerim her şeyi gördü, 2 Kulağım duydu, anladı.'),
(1996549,68,18,13,2,'Sizin bildiğinizi ben de biliyorum, 2 Sizden aşağı kalmam.'),
(1996550,68,18,13,3,'Ama ben Her Şeye Gücü Yetenle konuşmak, 2 Davamı Tanrıyla tartışmak istiyorum.'),
(1996551,68,18,13,4,'Sizlerse yalan düzüyorsunuz, 2 Hepiniz değersiz hekimlersiniz.'),
(1996552,68,18,13,5,'Keşke büsbütün sussanız! 2 Sizin için bilgelik olurdu bu.'),
(1996553,68,18,13,6,'Şimdi davamı dinleyin, 2 Yakınmama kulak verin.'),
(1996554,68,18,13,7,'Tanrı adına haksızlık mı edeceksiniz? 2 Onun adına yalan mı söyleyeceksiniz?'),
(1996555,68,18,13,8,'Onun tarafını mı tutacaksınız? 2 Tanrının davasını mı savunacaksınız?'),
(1996556,68,18,13,9,'Sizi sorguya çekerse, iyi mi olur? 2 İnsanları aldattığınız gibi Onu da mı aldatacaksınız?'),
(1996557,68,18,13,10,'Gizlice Onun tarafını tutarsanız, 2 Kuşkusuz sizi azarlar.'),
(1996558,68,18,13,11,'Onun görkemi sizi yıldırmaz mı? 2 Dehşeti üzerinize düşmez mi?'),
(1996559,68,18,13,12,'Anlattıklarınız kül kadar değersizdir, 2 Savunduklarınızsa çamurdan farksız.'),
(1996560,68,18,13,13,'‹‹Susun, bırakın ben konuşayım, 2 Başıma ne gelirse gelsin.'),
(1996561,68,18,13,14,'Hayatım tehlikeye girecekse girsin, 2 Canım zora düşecekse düşsün.'),
(1996562,68,18,13,15,'Beni öldürecek, umudum kalmadıfç, 2 Hiç olmazsa yürüdüğüm yolun doğruluğunu yüzüne karşı savunayım. bile Ona güvenim sarsılmaz.››'),
(1996563,68,18,13,16,'Aslında bu benim kurtuluşum olacak, 2 Çünkü tanrısız bir adam Onun karşısına çıkamaz.'),
(1996564,68,18,13,17,'Sözlerimi iyi dinleyin, 2 Kulaklarınızdan çıkmasın söyleyeceklerim.'),
(1996565,68,18,13,18,'İşte davamı hazırladım, 2 Haklı çıkacağımı biliyorum.'),
(1996566,68,18,13,19,'Kim suçlayacak beni? 2 Biri varsa susar, son soluğumu veririm.'),
(1996567,68,18,13,20,'‹‹Yalnız şu iki şeyi lütfet, Tanrım, 2 O zaman kendimi senden gizlemeyeceğim:'),
(1996568,68,18,13,21,'Elini üstümden çek 2 Ve dehşetinle beni yıldırma.'),
(1996569,68,18,13,22,'Sonra beni çağır, yanıtlayayım, 2 Ya da bırak ben konuşayım, sen yanıtla.'),
(1996570,68,18,13,23,'Suçlarım, günahlarım ne kadar? 2 Bana suçumu, günahımı göster.'),
(1996571,68,18,13,24,'Niçin yüzünü gizliyorsun, 2 Beni düşman gibi görüyorsun? çağrıştırıyor, bu yolla bir söz sanatı yapılmış.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996572,68,18,13,25,'Rüzgarın sürüklediği yaprağa dönmüşüm, 2 Beni mi korkutacaksın? 2 Kuru samanı mı kovalayacaksın?'),
(1996573,68,18,13,26,'Çünkü hakkımda acı şeyler yazıyor, 2 Gençliğimde işlediğim günahları bana miras veriyorsun.'),
(1996574,68,18,13,27,'Ayaklarımı tomruğa vuruyor, 2 Yollarımı gözetliyor, 2 İzimi sürüyorsun.'),
(1996575,68,18,13,28,'‹‹Oysa insan telef olmuş, çürük bir şey, 2 Güve yemiş giysi gibidir.'),
(1996576,68,18,14,1,'‹‹İnsanı kadın doğurur, 2 Günleri sayılı ve sıkıntı doludur.'),
(1996577,68,18,14,2,'Çiçek gibi açıp solar, 2 Gölge gibi gelip geçer.'),
(1996578,68,18,14,3,'Gözlerini böyle birine mi dikiyorsun, 2 Yargılamak için önüne çağırıyorsun?'),
(1996579,68,18,14,4,'Kim temizi kirliden çıkarabilir? 2 Hiç kimse!'),
(1996580,68,18,14,5,'Madem insanın günleri belirlenmiş, 2 Aylarının sayısı saptanmış, 2 Sınır koymuşsun, öteye geçemez;'),
(1996581,68,18,14,6,'Gözünü ondan ayır da, 2 Çalışma saatini dolduran gündelikçi gibi rahat etsin.'),
(1996582,68,18,14,7,'‹‹Oysa bir ağaç için umut vardır, 2 Kesilse, yeniden sürgün verir, 2 Eksilmez filizleri.'),
(1996583,68,18,14,8,'Kökü yerde kocasa, 2 Kütüğü toprakta ölse bile,'),
(1996584,68,18,14,9,'Su kokusu alır almaz filizlenir, 2 Bir fidan gibi dal budak salar.'),
(1996585,68,18,14,10,'İnsan ise ölüp yok olur, 2 Son soluğunu verir ve her şey biter.'),
(1996586,68,18,14,11,'Suyu akıp giden göl 2 Ya da kuruyan ırmak nasıl çöle dönerse,'),
(1996587,68,18,14,12,'İnsan da öyle, yatar, bir daha kalkmaz, 2 Gökler yok oluncaya dek uyanmaz, 2 Uyandırılmaz.'),
(1996588,68,18,14,13,'‹‹Keşke beni ölüler diyarına gizlesen, 2 Öfken geçinceye dek saklasan, 2 Bana bir süre versen de, beni sonra anımsasan.'),
(1996589,68,18,14,14,'İnsan ölür de dirilir mi? 2 Başka biri nöbetimi devralıncaya dek 2 Savaş boyunca umutla beklerdim.'),
(1996590,68,18,14,15,'Sen çağırırdın, ben yanıtlardım, 2 Ellerinle yaptığın yaratığı özlerdin.'),
(1996591,68,18,14,16,'O zaman adımlarımı sayar, 2 Günahımın hesabını tutmazdın.'),
(1996592,68,18,14,17,'İsyanımı torbaya koyup mühürler, 2 Suçumu örterdin.'),
(1996593,68,18,14,18,'‹‹Ama dağın yıkılıp çöktüğü, 2 Kayanın yerinden taşındığı,'),
(1996594,68,18,14,19,'Suyun taşı aşındırdığı, 2 Selin toprağı sürükleyip götürdüğü gibi, 2 İnsanın umudunu yok ediyorsun.'),
(1996595,68,18,14,20,'Onu hep yenersin, yok olup gider, 2 Çehresini değiştirir, uzağa gönderirsin.'),
(1996596,68,18,14,21,'Oğulları saygı görür, onun haberi olmaz, 2 Aşağılanırlar, anlamaz.'),
(1996597,68,18,14,22,'Ancak kendi canının acısını duyar, 2 Yalnız kendisi için yas tutar.››'),
(1996598,68,18,15,1,'Temanlı Elifaz şöyle yanıtladı:'),
(1996599,68,18,15,2,'‹‹Bilge kişi boş sözlerle yanıtlar mı, 2 Karnını doğu rüzgarıyla doldurur mu?'),
(1996600,68,18,15,3,'Boş sözlerle tartışır, 2 Yararsız söylevler verir mi?'),
(1996601,68,18,15,4,'Tanrı korkusunu bile ortadan kaldırıyor, 2 Tanrının huzurunda düşünmeyi engelliyorsun.'),
(1996602,68,18,15,5,'Çünkü suçun ağzını kışkırtıyor, 2 Hilekârların diliyle konuşuyorsun.'),
(1996603,68,18,15,6,'Kendi ağzın seni suçluyor, ben değil, 2 Dudakların sana karşı tanıklık ediyor.'),
(1996604,68,18,15,7,'‹‹İlk doğan insan sen misin? 2 Yoksa dağlardan önce mi var oldun?'),
(1996605,68,18,15,8,'Tanrının sırrını mı dinledin de, 2 Yalnız kendini bilge görüyorsun?'),
(1996606,68,18,15,9,'Senin bildiğin ne ki, biz bilmeyelim? 2 Senin anladığın ne ki, bizde olmasın?'),
(1996607,68,18,15,10,'Bizde ak saçlı da yaşlı da var, 2 Babandan bile yaşlı.'),
(1996608,68,18,15,11,'Az mı geliyor Tanrının avutması sana, 2 Söylediği yumuşak sözler?'),
(1996609,68,18,15,12,'Niçin yüreğin seni sürüklüyor, 2 Gözlerin parıldıyor,'),
(1996610,68,18,15,13,'Tanrıya öfkeni gösteriyorsun, 2 Ağzından böyle sözler dökülüyor?'),
(1996611,68,18,15,14,'‹‹İnsan gerçekten temiz olabilir mi? 2 Kadından doğan biri doğru olabilir mi?'),
(1996612,68,18,15,15,'Tanrı meleklerine güvenmiyorsa, 2 Gökler bile Onun gözünde temiz değilse,'),
(1996613,68,18,15,16,'Haksızlığı su gibi içen 2 İğrenç, bozuk insana mı güvenecek?'),
(1996614,68,18,15,17,'‹‹Dinle beni, sana açıklayayım, 2 Gördüğümü anlatayım,'),
(1996615,68,18,15,18,'Bilgelerin atalarından öğrenip bildirdiği, 2 Gizlemediği gerçekleri;'),
(1996616,68,18,15,19,'O atalar ki, ülke yalnız onlara verilmişti, 2 Aralarına henüz yabancı girmemişti.'),
(1996617,68,18,15,20,'Kötü insan yaşamı boyunca kıvranır, 2 Zorbaya ayrılan yıllar sayılıdır.'),
(1996618,68,18,15,21,'Dehşet sesleri kulağından eksilmez, 2 Esenlik içindeyken soyguncunun saldırısına uğrar.'),
(1996619,68,18,15,22,'Karanlıktan kurtulabileceğine inanmaz, 2 Kılıç onu gözler.'),
(1996620,68,18,15,23,'‹Nerede?› diyerek ekmek ardınca dolaşır, 2 Karanlık günün yanıbaşında olduğunu bilir.'),
(1996621,68,18,15,24,'Acı ve sıkıntı onu yıldırır, 2 Savaşa hazır bir kral gibi onu yener.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996622,68,18,15,25,'Çünkü Tanrıya el kaldırmış, 2 Her Şeye Gücü Yetene meydan okumuş,'),
(1996623,68,18,15,26,'Kalın, yumrulu kalkanıyla 2 Ona inatla saldırmıştı.'),
(1996624,68,18,15,27,'‹‹Yüzü semirdiği, 2 Göbeği yağ bağladığı halde,'),
(1996625,68,18,15,28,'Yıkılmış kentlerde, 2 Taş yığınına dönmüş oturulmaz evlerde oturacak,'),
(1996626,68,18,15,29,'Zengin olmayacak, serveti tükenecek, 2 Malları ülkeye yayılmayacaktır.'),
(1996627,68,18,15,30,'Karanlıktan kaçamayacak, 2 Filizlerini alev kurutacak, 2 Tanrının ağzından çıkan solukla yok olacaktır.'),
(1996628,68,18,15,31,'Boş şeye güvenerek kendini aldatmasın, 2 Çünkü ödülü boşluk olacaktır.'),
(1996629,68,18,15,32,'Gününden önce işi tamamlanacak, 2 Dalı yeşermeyecektir.'),
(1996630,68,18,15,33,'Asma gibi koruğunu dökecek, 2 Zeytin ağacı gibi çiçeğini dağıtacaktır.'),
(1996631,68,18,15,34,'Çünkü tanrısızlar sürüsü kısır olur, 2 Rüşvetçilerin çadırlarını ateş yakıp yok eder.'),
(1996632,68,18,15,35,'Fesada gebe kalıp kötülük doğururlar, 2 İçleri yalan doludur.››'),
(1996633,68,18,16,1,'Eyüp şöyle yanıtladı:'),
(1996634,68,18,16,2,'‹‹Buna benzer çok şey duydum, 2 Oysa siz avutmuyor, sıkıntı veriyorsunuz.'),
(1996635,68,18,16,3,'Boş sözleriniz hiç sona ermeyecek mi? 2 Nedir derdiniz, boyuna karşılık veriyorsunuz?'),
(1996636,68,18,16,4,'Yerimde siz olsaydınız, 2 Ben de sizin gibi konuşabilirdim; 2 Size karşı güzel sözler dizer, 2 Başımı sallayabilirdim.'),
(1996637,68,18,16,5,'Ağzımdan çıkan sözlerle yüreklendirir, 2 Dudaklarımdan dökülen avutucu sözlerle yatıştırırdım sizi.'),
(1996638,68,18,16,6,'‹‹Konuşsam bile acım dinmez, 2 Sussam ne değişir?'),
(1996639,68,18,16,7,'Ey Tanrı, beni tükettin, 2 Bütün ev halkımı dağıttın.'),
(1996640,68,18,16,8,'Beni sıkıp buruşturdun, bana karşı tanık oldu bu; 2 Zayıflığım kalkmış tanıklık ediyor bana karşı.'),
(1996641,68,18,16,9,'Tanrı öfkeyle saldırıp parçalıyor beni, 2 Dişlerini gıcırdatıyor bana, 2 Düşmanım gözlerini üzerime dikiyor.'),
(1996642,68,18,16,10,'İnsanlar bana dudak büküyor, 2 Aşağılayarak tokat atıyor, 2 Birleşiyorlar bana karşı.'),
(1996643,68,18,16,11,'Tanrı haksızlara teslim ediyor beni, 2 Kötülerin kucağına atıyor.'),
(1996644,68,18,16,12,'Ben rahat yaşıyordum, ama Tanrı paraladı beni, 2 Boynumdan tutup yere çaldı. 2 Beni hedef yaptı kendine.'),
(1996645,68,18,16,13,'Okçuları beni kuşatıyor, 2 Acımadan böbreklerimi deşiyor, 2 Ödümü yerlere döküyor.'),
(1996646,68,18,16,14,'Bedenimde gedik üstüne gedik açıyor, 2 Dev gibi üzerime saldırıyor.'),
(1996647,68,18,16,15,'‹‹Giymek için çul diktim, 2 Gururumu ayak altına aldım.'),
(1996648,68,18,16,16,'Ağlamaktan yüzüm kızardı, 2 Gözlerimin altı morardı.'),
(1996649,68,18,16,17,'Yine de ellerim şiddetten uzak, 2 Duam içtendir.'),
(1996650,68,18,16,18,'‹‹Ey toprak, kanımı örtme, 2 Feryadım asla dinmesin.'),
(1996651,68,18,16,19,'Daha şimdiden tanığım göklerde, 2 Beni savunan yücelerdedir.'),
(1996652,68,18,16,20,'Dostlarım benimle eğleniyor, 2 Gözlerim Tanrıya yaş döküyor;'),
(1996653,68,18,16,21,'Tanrı kendisiyle insan arasında 2 İnsanoğluyla komşusu arasında hak arasın diye.'),
(1996654,68,18,16,22,'‹‹Çünkü birkaç yıl sonra, 2 Dönüşü olmayan yolculuğa çıkacağım.'),
(1996655,68,18,17,1,'‹‹Yaşama gücüm tükendi, günlerim kısaldı, 2 Mezar gözlüyor beni.'),
(1996656,68,18,17,2,'Çevremi alaycılar kuşatmış, 2 Gözümü onların aşağılamasıyla açıp kapıyorum.'),
(1996657,68,18,17,3,'‹‹Ey Tanrı, kefilim ol kendine karşı, 2 Başka kim var bana güvence verecek?'),
(1996658,68,18,17,4,'Çünkü onların aklını anlayışa kapadın, 2 Bu yüzden onları zafere kavuşturmayacaksın.'),
(1996659,68,18,17,5,'Para için dostlarını satan adamın 2 Çocuklarının gözünün feri söner.'),
(1996660,68,18,17,6,'‹‹Tanrı beni insanların diline düşürdü, 2 Yüzüme tükürmekteler.'),
(1996661,68,18,17,7,'Kederden gözümün feri söndü, 2 Kollarım bacaklarım çırpı gibi.'),
(1996662,68,18,17,8,'Dürüst insanlar buna şaşıyor, 2 Suçsuzlar tanrısızlara saldırıyor.'),
(1996663,68,18,17,9,'Doğrular kendi yolunu tutuyor, 2 Elleri temiz olanlar gittikçe güçleniyor.'),
(1996664,68,18,17,10,'‹‹Ama siz, hepiniz gelin yine deneyin! 2 Aranızda bir bilge bulamayacağım.'),
(1996665,68,18,17,11,'Günlerim geçti, tasarılarım, 2 Dileklerim suya düştü.'),
(1996666,68,18,17,12,'Bu insanlar geceyi gündüze çeviriyorlar, 2 Karanlığa ‹Işık yakındır› diyorlar.'),
(1996667,68,18,17,13,'Ölüler diyarını evim diye gözlüyorsam, 2 Yatağımı karanlığa seriyorsam,'),
(1996668,68,18,17,14,'Çukura ‹Babam›, 2 Kurda ‹Annem, kızkardeşim› diyorsam,'),
(1996669,68,18,17,15,'Umudum nerede? 2 Kim benim için umut görebilir?'),
(1996670,68,18,17,16,'Umut benimle ölüler diyarına mı inecek? 2 Toprağa birlikte mi gireceğiz?››'),
(1996671,68,18,18,1,'Şuahlı Bildat şöyle yanıtladı:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996672,68,18,18,2,'‹‹Ne zaman bitecek bu sözler? 2 Biraz anlayışlı olun da konuşalım.'),
(1996673,68,18,18,3,'Niçin hayvan yerine konuyoruz, 2 Gözünüzde aptal sayılıyoruz?'),
(1996674,68,18,18,4,'Sen kendini öfkenle paralıyorsun, 2 Senin uğruna dünyadan vaz mı geçilecek? 2 Kayalar yerini mi değiştirecek?'),
(1996675,68,18,18,5,'‹‹Evet, kötünün ışığı sönecek, 2 Ateşinin alevi parlamayacak.'),
(1996676,68,18,18,6,'Çadırındaki ışık karanlığa dönecek, 2 Yanındaki kandil sönecek.'),
(1996677,68,18,18,7,'Adımlarının gücü zayıflayacak, 2 Kurduğu düzene kendi düşecek.'),
(1996678,68,18,18,8,'Ayakları onu ağa götürecek, 2 Kendi ayağıyla tuzağa basacak.'),
(1996679,68,18,18,9,'Topuğu kapana girecek, 2 Tuzak onu kapacak.'),
(1996680,68,18,18,10,'Toprağa gizlenmiş bir ilmek, 2 Yoluna koyulmuş bir kapan bekliyor onu.'),
(1996681,68,18,18,11,'Dehşet saracak onu her yandan, 2 Her adımında onu kovalayacak.'),
(1996682,68,18,18,12,'Gücünü kıtlık kemirecek, 2 Tökezleyince, felaket yanında bitiverecek.'),
(1996683,68,18,18,13,'Derisini hastalık yiyecek, 2 Kollarıyla bacaklarını ölüm yutacak.'),
(1996684,68,18,18,14,'Güvenli çadırından atılacak, 2 Dehşet kralının önüne sürüklenecek.'),
(1996685,68,18,18,15,'Çadırında ateş oturacak, 2 Yurdunun üzerine kükürt saçılacak.'),
(1996686,68,18,18,16,'Kökleri dipten kuruyacak, 2 Dalları üstten solacak.'),
(1996687,68,18,18,17,'Ülkede anısı yok olacak, 2 Adı dünyadan silinecek.'),
(1996688,68,18,18,18,'Işıktan karanlığa sürülecek, 2 Dünyadan kovulacak.'),
(1996689,68,18,18,19,'Ne çocuğu ne torunu kalacak halkı arasında, 2 Yaşadığı yerde kimsesi kalmayacak.'),
(1996690,68,18,18,20,'Batıdakiler onun yıkımına şaşacak, 2 Doğudakiler dehşet içinde bakacak.'),
(1996691,68,18,18,21,'Evet, kötülerin yaşamı işte böyle son bulur, 2 Tanrı''yı tanımayanların varacağı yer budur.››'),
(1996692,68,18,19,1,'Eyüp şöyle yanıtladı:'),
(1996693,68,18,19,2,'‹‹Ne zamana dek beni üzecek, 2 Sözlerinizle ezeceksiniz?'),
(1996694,68,18,19,3,'On kez oldu beni aşağılıyor, 2 Hiç utanmadan saldırıyorsunuz.'),
(1996695,68,18,19,4,'Yanlış yola sapmışsam, 2 Bu benim suçum.'),
(1996696,68,18,19,5,'Kendinizi gerçekten benden üstün görüyor, 2 Utancımı bana karşı kullanıyorsanız,'),
(1996697,68,18,19,6,'Bilin ki, Tanrı bana haksızlık yaptı, 2 Beni ağıyla kuşattı.'),
(1996698,68,18,19,7,'‹‹İşte, ‹Zorbalık bu!› diye haykırıyorum, ama yanıt yok, 2 Yardım için bağırıyorum, ama adalet yok.'),
(1996699,68,18,19,8,'Yoluma set çekti, geçemiyorum, 2 Yollarımı karanlığa boğdu.'),
(1996700,68,18,19,9,'Üzerimden onurumu soydu, 2 Başımdaki tacı kaldırdı.'),
(1996701,68,18,19,10,'Her yandan yıktı beni, tükendim, 2 Umudumu bir ağaç gibi kökünden söktü.'),
(1996702,68,18,19,11,'Öfkesi bana karşı alev alev yanıyor, 2 Beni hasım sayıyor.'),
(1996703,68,18,19,12,'Orduları üstüme üstüme geliyor, 2 Bana karşı rampalar yapıyor, 2 Çadırımın çevresinde ordugah kuruyorlar.'),
(1996704,68,18,19,13,'‹‹Kardeşlerimi benden uzaklaştırdı, 2 Tanıdıklarım bana büsbütün yabancılaştı.'),
(1996705,68,18,19,14,'Akrabalarım uğramaz oldu, 2 Yakın dostlarım beni unuttu.'),
(1996706,68,18,19,15,'Evimdeki konuklarla hizmetçiler 2 Beni yabancı sayıyor, 2 Garip oldum gözlerinde.'),
(1996707,68,18,19,16,'Kölemi çağırıyorum, yanıtlamıyor, 2 Dil döksem bile.'),
(1996708,68,18,19,17,'Soluğum karımı tiksindiriyor, 2 Kardeşlerim benden iğreniyor.'),
(1996709,68,18,19,18,'Çocuklar bile beni küçümsüyor, 2 Ayağa kalksam benimle eğleniyorlar.'),
(1996710,68,18,19,19,'Bütün yakın dostlarım benden iğreniyor, 2 Sevdiklerim yüz çeviriyor.'),
(1996711,68,18,19,20,'Bir deri bir kemiğe döndüm, 2 Ölümün eşiğine geldim.'),
(1996712,68,18,19,21,'‹‹Ey dostlarım, acıyın bana, siz acıyın, 2 Çünkü Tanrının eli vurdu bana.'),
(1996713,68,18,19,22,'Neden Tanrı gibi siz de beni kovalıyor, 2 Etime doymuyorsunuz?'),
(1996714,68,18,19,23,'‹‹Keşke şimdi sözlerim yazılsa, 2 Kitaba geçseydi,'),
(1996715,68,18,19,24,'Demir kalemle, kurşunla 2 Sonsuza dek kalsın diye kayaya kazılsaydı!'),
(1996716,68,18,19,25,'Oysa ben kurtarıcımın yaşadığını, 2 Sonunda yeryüzüne geleceğini biliyorum.'),
(1996717,68,18,19,26,'Derim yok olduktan sonra, 2 Yeni bedenimle Tanrıyı göreceğim.'),
(1996718,68,18,19,27,'Onu kendim göreceğim, 2 Kendi gözlerimle, başkası değil. 2 Yüreğim bayılıyor bağrımda!'),
(1996719,68,18,19,28,'Eğer, ‹Sıkıntının kökü onda olduğu için 2 Onu kovalım› diyorsanız,'),
(1996720,68,18,19,29,'Kılıçtan korkmalısınız, 2 Çünkü kılıç cezası öfkeli olur, 2 O zaman adaletin var olduğunu göreceksiniz.››'),
(1996721,68,18,20,1,'Naamalı Sofar şöyle yanıtladı:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996722,68,18,20,2,'‹‹Sıkıntılı düşüncelerim beni yanıt vermeye zorluyor, 2 Bu yüzden çok heyecanlıyım.'),
(1996723,68,18,20,3,'Beni utandıran bir azar işitiyorum, 2 Anlayışım yanıt vermemi gerektiriyor.'),
(1996724,68,18,20,4,'‹‹Bilmiyor musun eskiden beri, 2 İnsan dünyaya geldiğinden beri,'),
(1996725,68,18,20,5,'Kötünün zafer çığlığı kısadır, 2 Tanrısızın sevinciyse bir anlıktır.'),
(1996726,68,18,20,6,'Boyu göklere erişse, 2 Başı bulutlara değse bile,'),
(1996727,68,18,20,7,'Sonsuza dek yok olacak, kendi pisliği gibi; 2 Onu görmüş olanlar, ‹Nerede o?› diyecekler.'),
(1996728,68,18,20,8,'Düş gibi uçacak, bir daha bulunamayacak, 2 Gece görümü gibi yok olacak.'),
(1996729,68,18,20,9,'Kendisini görmüş olan gözler bir daha onu görmeyecek, 2 Yaşadığı yerde artık görünmeyecektir.'),
(1996730,68,18,20,10,'Çocukları yoksulların lütfunu dileyecek, 2 Malını kendi eliyle geri verecektir.'),
(1996731,68,18,20,11,'Kemiklerini dolduran gençlik ateşi 2 Kendisiyle birlikte toprakta yatacak.'),
(1996732,68,18,20,12,'‹‹Kötülük ağzında tatlı gözükse, 2 Onu dilinin altına gizlese bile,'),
(1996733,68,18,20,13,'Tutsa, bırakmasa, 2 Damağının altına saklasa bile,'),
(1996734,68,18,20,14,'Yediği yiyecek midesinde ekşiyecek, 2 İçinde kobra zehirine dönüşecek.'),
(1996735,68,18,20,15,'Yuttuğu servetleri kusacak, 2 Tanrı onları midesinden çıkaracak.'),
(1996736,68,18,20,16,'Kobra zehiri emecek, 2 Engereğin zehir dişi onu öldürecek.'),
(1996737,68,18,20,17,'Akarsuların, bal ve ayran akan derelerin 2 Sefasını süremeyecek.'),
(1996738,68,18,20,18,'Zahmetle kazandığını 2 Yemeden geri verecek, 2 Elde ettiği kazancın tadını çıkaramayacak.'),
(1996739,68,18,20,19,'Çünkü yoksulları ezip yüzüstü bıraktı, 2 Kendi yapmadığı evi zorla aldı.'),
(1996740,68,18,20,20,'‹‹Hırsı yüzünden rahat nedir bilmedi, 2 Serveti onu kurtaramayacak.'),
(1996741,68,18,20,21,'Yediğinden artakalan olmadı, 2 Bu yüzden bolluğu uzun sürmeyecek.'),
(1996742,68,18,20,22,'Varlık içinde yokluk çekecek, 2 Sıkıntı tepesine binecek.'),
(1996743,68,18,20,23,'Karnını tıka basa doyurduğunda, 2 Tanrı kızgın öfkesini ondan çıkaracak, 2 Üzerine gazap yağdıracak.'),
(1996744,68,18,20,24,'Demir silahtan kaçacak olsa, 2 Tunç ok onu delip geçecek.'),
(1996745,68,18,20,25,'Çekilince ok sırtından, 2 Parıldayan ucu ödünden çıkacak, 2 Dehşet çökecek üzerine.'),
(1996746,68,18,20,26,'Koyu karanlık onun hazinelerini gözlüyor. 2 Körüklenmemiş ateş onu yiyip bitirecek, 2 Çadırında artakalanı tüketecek.'),
(1996747,68,18,20,27,'Suçunu gökler açığa çıkaracak, 2 Yeryüzü ona karşı ayaklanacak.'),
(1996748,68,18,20,28,'Varlığını seller, 2 Azgın sular götürecek Tanrının öfkelendiği gün.'),
(1996749,68,18,20,29,'Budur kötünün Tanrı''dan aldığı pay, 2 Budur Tanrı''nın ona verdiği miras.››'),
(1996750,68,18,21,1,'Eyüp şöyle yanıtladı:'),
(1996751,68,18,21,2,'‹‹Sözümü dikkatle dinleyin, 2 Bana verdiğiniz avuntu bu olsun.'),
(1996752,68,18,21,3,'Bırakın ben de konuşayım, 2 Ben konuştuktan sonra alay edin.'),
(1996753,68,18,21,4,'‹‹Yakınmam insana mı karşı? 2 Niçin sabırsızlanmayayım?'),
(1996754,68,18,21,5,'Bana bakın da şaşın, 2 Elinizi ağzınıza koyun.'),
(1996755,68,18,21,6,'Bunu düşündükçe içimi korku sarıyor, 2 Bedenimi titreme alıyor.'),
(1996756,68,18,21,7,'Kötüler niçin yaşıyor, 2 Yaşlandıkça güçleri artıyor?'),
(1996757,68,18,21,8,'Çocukları sapasağlam çevrelerinde, 2 Soyları gözlerinin önünde.'),
(1996758,68,18,21,9,'Evleri güvenlik içinde, korkudan uzak, 2 Tanrının sopası onlara dokunmuyor.'),
(1996759,68,18,21,10,'Boğalarının çiftleşmesi hiç boşa çıkmaz, 2 İnekleri hep doğurur, hiç düşük yapmaz.'),
(1996760,68,18,21,11,'Çocuklarını sürü gibi salıverirler, 2 Yavruları oynaşır.'),
(1996761,68,18,21,12,'Tef ve lir eşliğinde şarkı söyler, 2 Ney sesiyle eğlenirler.'),
(1996762,68,18,21,13,'Ömürlerini bolluk içinde geçirir, 2 Esenlik içinde ölüler diyarına inerler.'),
(1996763,68,18,21,14,'Tanrıya, ‹Bizden uzak dur!› derler, 2 ‹Yolunu öğrenmek istemiyoruz.'),
(1996764,68,18,21,15,'Her Şeye Gücü Yeten kim ki, Ona kulluk edelim? 2 Ne kazancımız olur Ona dua etsek?›'),
(1996765,68,18,21,16,'Ama zenginlikleri kendi ellerinde değil. 2 Kötülerin öğüdü benden uzak olsun.'),
(1996766,68,18,21,17,'‹‹Kaç kez kötülerin kandili söndü, 2 Başlarına felaket geldi, 2 Tanrı öfkelendiğinde paylarına düşen kederi verdi?'),
(1996767,68,18,21,18,'Kaç kez rüzgarın sürüklediği saman gibi, 2 Kasırganın uçurduğu saman çöpü gibi oldular?'),
(1996768,68,18,21,19,'‹Tanrı babaların cezasını çocuklarına çektirir› diyorsunuz, 2 Kendilerine çektirsin de bilsinler nasıl olduğunu.'),
(1996769,68,18,21,20,'Yıkımlarını kendi gözleriyle görsünler, 2 Her Şeye Gücü Yetenin gazabını içsinler.'),
(1996770,68,18,21,21,'Çünkü sayılı ayları sona erince 2 Geride bıraktıkları aileleri için niye kaygı çeksinler?'),
(1996771,68,18,21,22,'‹‹En yüksektekileri bile yargılayan Tanrıya 2 Kim akıl öğretebilir?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996772,68,18,21,23,'Biri gücünün doruğunda ölür, 2 Büsbütün rahat ve kaygısız.'),
(1996773,68,18,21,24,'Bedeni iyi beslenmiş, 2 İlikleri dolu.'),
(1996774,68,18,21,25,'Ötekiyse acı içinde ölür, 2 İyilik nedir hiç tatmamıştır.'),
(1996775,68,18,21,26,'Toprakta birlikte yatarlar, 2 Üzerlerini kurt kaplar.'),
(1996776,68,18,21,27,'‹‹Bakın, düşüncelerinizi, 2 Bana zarar vermek için kurduğunuz düzenleri biliyorum.'),
(1996777,68,18,21,28,'‹Büyük adamın evi nerede?› diyorsunuz, 2 ‹Kötülerin çadırları nerede?›'),
(1996778,68,18,21,29,'Yolculara hiç sormadınız mı? 2 Anlattıklarına kulak asmadınız mı?'),
(1996779,68,18,21,30,'Felaket günü kötü insan esirgenir, 2 Gazap günü ona kurtuluş yolu gösterilir.'),
(1996780,68,18,21,31,'Kim davranışını onun yüzüne vurur? 2 Kim yaptığının karşılığını ona ödetir?'),
(1996781,68,18,21,32,'Mezarlığa taşınır, 2 Kabri başında nöbet tutulur.'),
(1996782,68,18,21,33,'Vadi toprağı tatlı gelir ona, 2 Herkes ardından gider, 2 Önüsıra gidenlerse sayısızdır.'),
(1996783,68,18,21,34,'‹‹Boş laflarla beni nasıl avutursunuz? 2 Yanıtlarınızdan çıkan tek sonuç yalandır.››'),
(1996784,68,18,22,1,'Temanlı Elifaz şöyle yanıtladı:'),
(1996785,68,18,22,2,'‹‹İnsan Tanrıya yararlı olabilir mi? 2 Bilge kişinin bile Ona yararı dokunabilir mi?'),
(1996786,68,18,22,3,'Doğruluğun Her Şeye Gücü Yetene ne zevk verebilir, 2 Kusursuz yaşamın Ona ne kazanç sağlayabilir?'),
(1996787,68,18,22,4,'Seni azarlaması, dava etmesi 2 Ondan korktuğun için mi?'),
(1996788,68,18,22,5,'Kötülüğün büyük, 2 Günahların sonsuz değil mi?'),
(1996789,68,18,22,6,'Çünkü kardeşlerinden nedensiz rehin alıyor, 2 Onları soyuyordun.'),
(1996790,68,18,22,7,'Yorguna su içirmedin, 2 Açtan ekmeği esirgedin;'),
(1996791,68,18,22,8,'Ülkeye bileğinle sahip oldun, 2 Saygın biri olarak orada yaşadın.'),
(1996792,68,18,22,9,'Dul kadınları eli boş çevirdin, 2 Öksüzlerin kolunu kanadını kırdın.'),
(1996793,68,18,22,10,'Bu yüzden her yanın tuzaklarla çevrili, 2 Ansızın gelen korkuyla yılıyorsun,'),
(1996794,68,18,22,11,'Her şey kararıyor, göremez oluyorsun, 2 Seller altına alıyor seni.'),
(1996795,68,18,22,12,'‹‹Tanrı göklerin yükseklerinde değil mi? 2 Yıldızlara bak, ne kadar yüksekteler!'),
(1996796,68,18,22,13,'Sen ise, ‹Tanrı ne bilir?› diyorsun, 2 ‹Zifiri karanlığın içinden yargılayabilir mi?'),
(1996797,68,18,22,14,'Koyu bulutlar Ona engeldir, göremez, 2 Gökkubbenin üzerinde dolaşır.›'),
(1996798,68,18,22,15,'Kötülerin yürüdüğü 2 Eski yolu mu tutacaksın?'),
(1996799,68,18,22,16,'Onlar ki, vakitleri gelmeden çekilip alındılar, 2 Temellerini sel bastı.'),
(1996800,68,18,22,17,'Tanrıya, ‹Bizden uzak dur!› dediler, 2 ‹Her Şeye Gücü Yeten bize ne yapabilir?›'),
(1996801,68,18,22,18,'Ama onların evlerini iyilikle dolduran Oydu. 2 Bunun için kötülerin öğüdü benden uzak olsun.'),
(1996802,68,18,22,19,'‹‹Doğrular onların yıkımını görüp sevinir, 2 Suçsuzlar şöyle diyerek eğlenir:'),
(1996803,68,18,22,20,'‹Düşmanlarımız yok edildi, 2 Malları yanıp kül oldu.›'),
(1996804,68,18,22,21,'‹‹Tanrıyla dost ol, barış ki, 2 Bolluğa eresin.'),
(1996805,68,18,22,22,'Ağzından çıkan öğretiyi benimse, 2 Sözlerini yüreğinde tut.'),
(1996806,68,18,22,23,'Her Şeye Gücü Yetene dönersen, eski haline kavuşursun. 2 Kötülüğü çadırından uzak tutar,'),
(1996807,68,18,22,24,'Altınını yere, 2 Ofir altınını vadideki çakılların arasına atarsan,'),
(1996808,68,18,22,25,'Her Şeye Gücü Yeten senin altının, 2 Değerli gümüşün olur.'),
(1996809,68,18,22,26,'O zaman Her Şeye Gücü Yetenden zevk alır, 2 Yüzünü Tanrıya kaldırırsın.'),
(1996810,68,18,22,27,'Ona dua edersin, dinler seni, 2 Adaklarını yerine getirirsin.'),
(1996811,68,18,22,28,'Neye karar verirsen yapılır, 2 Yollarını ışık aydınlatır.'),
(1996812,68,18,22,29,'İnsanlar seni alçaltınca, güvenini yitirme, 2 Çünkü Tanrı alçakgönüllüleri kurtarır.'),
(1996813,68,18,22,30,'O suçsuz olmayanı bile kurtarır, 2 Senin ellerinin temizliği sayesinde kurtulur suçlu.››'),
(1996814,68,18,23,1,'Eyüp şöyle yanıtladı:'),
(1996815,68,18,23,2,'‹‹Bugün de acı acı yakınacağım, 2 İniltime karşın Tanrının üzerimdeki eli ağırdır.'),
(1996816,68,18,23,3,'Keşke Onu nerede bulacağımı bilseydim, 2 Tahtına varabilseydim!'),
(1996817,68,18,23,4,'Davamı önünde dile getirir, 2 Kanıtlarımı art arda sıralardım.'),
(1996818,68,18,23,5,'Bana vereceği yanıtı öğrenir, 2 Ne diyeceğini anlardım.'),
(1996819,68,18,23,6,'Eşsiz gücüyle bana karşı mı çıkardı? 2 Hayır, yalnızca dinlerdi beni.'),
(1996820,68,18,23,7,'Haklı kişi davasını oraya, Onun önüne getirebilirdi, 2 Ben de yargılanmaktan sonsuza dek kurtulurdum.'),
(1996821,68,18,23,8,'‹‹Doğuya gitsem orada değil, 2 Batıya gitsem Onu bulamıyorum.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996822,68,18,23,9,'Kuzeyde iş görse Onu seçemiyorum, 2 Güneye dönse Onu göremiyorum.'),
(1996823,68,18,23,10,'Ama O tuttuğum yolu biliyor, 2 Beni sınadığında altın gibi çıkacağım.'),
(1996824,68,18,23,11,'Adımlarını yakından izledim, 2 Sapmadan yolunu tuttum.'),
(1996825,68,18,23,12,'Ağzından çıkan buyruklardan ayrılmadım, 2 Günlük ekmeğimden çok ağzından çıkan sözlere değer verdim.'),
(1996826,68,18,23,13,'‹‹O tek başınadır, kim Onu caydırabilir? 2 Canı ne isterse onu yapar.'),
(1996827,68,18,23,14,'Benimle ilgili kararını yerine getirir, 2 Daha nice tasarısı vardır.'),
(1996828,68,18,23,15,'Bu yüzden dehşete düşerim huzurunda, 2 Düşündükçe korkarım Ondan.'),
(1996829,68,18,23,16,'Tanrı cesaretimi kırdı, 2 Her Şeye Gücü Yeten beni yıldırdı.'),
(1996830,68,18,23,17,'Karanlık beni susturamadı, 2 Yüzümü örten koyu karanlık.'),
(1996831,68,18,24,1,'‹‹Niçin Her Şeye Gücü Yeten yargı için vakit saptamıyor? 2 Neden Onu tanıyanlar bu günleri görmesin?'),
(1996832,68,18,24,2,'İnsanlar sınır taşlarını kaldırıyor, 2 Çaldıkları sürüleri otlatıyorlar.'),
(1996833,68,18,24,3,'Öksüzlerin eşeğini kovuyor, 2 Dul kadının öküzünü rehin alıyorlar.'),
(1996834,68,18,24,4,'Yoksulları yoldan saptırıyor, 2 Ülkenin düşkünlerini gizlenmeye zorluyorlar.'),
(1996835,68,18,24,5,'Bakın, yoksullar çöldeki yaban eşekleri gibi 2 Yiyecek bulmak için erkenden işe çıkıyorlar, 2 Çocuklarına yiyeceği kırlar sağlıyor.'),
(1996836,68,18,24,6,'Yemlerini tarlalardan topluyor, 2 Kötülerin bağındaki artıkları eşeliyorlar.'),
(1996837,68,18,24,7,'Geceyi giysisiz, çıplak geçiriyorlar, 2 Örtünecek şeyleri yok soğukta.'),
(1996838,68,18,24,8,'Dağlara yağan sağanaktan ıslanıyor, 2 Sığınakları olmadığı için kayalara sarılıyorlar.'),
(1996839,68,18,24,9,'Öksüz memeden uzaklaştırılıyor, 2 Düşkünün bebeği rehin alınıyor.'),
(1996840,68,18,24,10,'Giysisiz, çıplak dolaşıyor, 2 Aç karnına demet taşıyorlar.'),
(1996841,68,18,24,11,'Teraslar arasında zeytin eziyor, 2 Susuzluktan kavrulurken 2 Şarap için üzüm sıkıyorlar.'),
(1996842,68,18,24,12,'Kentlerden insan iniltileri yükseliyor, 2 Yaralı canlar feryat ediyor, 2 Ama Tanrı haksızlığı önemsemiyor.'),
(1996843,68,18,24,13,'‹‹Bunlar ışığa başkaldıranlardır; 2 Onun yolunu tanımaz, 2 İzinde yürümezler.'),
(1996844,68,18,24,14,'Gün kararınca katil kalkar, 2 Düşkünü, yoksulu öldürür, 2 Hırsız gibi sıvışır geceleyin.'),
(1996845,68,18,24,15,'Zina edenin gözü alaca karanlıktadır, 2 ‹Beni kimse görmez› diye düşünür, 2 Yüzünü örtüyle gizler.'),
(1996846,68,18,24,16,'Hırsızlar karanlıkta evleri deler, 2 Gündüz gizlenir, ışık nedir bilmezler.'),
(1996847,68,18,24,17,'Çünkü zifiri karanlık, sabahıdır onların, 2 Karanlığın dehşetiyle dostturlar.'),
(1996848,68,18,24,18,'‹‹Diyorsunuz ki, ‹Suyun üstündeki köpüktür onlar, 2 Lanetlidir ülkedeki payları, 2 Kimse bağlara gitmez.'),
(1996849,68,18,24,19,'Kuraklık ve sıcağın eriyen karı alıp götürdüğü gibi 2 Ölüler diyarı da günahlıları alıp götürür.'),
(1996850,68,18,24,20,'Rahim onları unutacak, 2 Kurtlara yem olacak, 2 Bir daha anılmayacaklar. 2 Haksızlık bir ağaç gibi kırılacak.'),
(1996851,68,18,24,21,'Onlar çocuğu olmayan kısır kadınları yolar, 2 Dul kadına iyilik etmezler.'),
(1996852,68,18,24,22,'Tanrı, gücüyle zorbaları yok eder, 2 Harekete geçince zorbaların yaşama umudu kalmaz.'),
(1996853,68,18,24,23,'Tanrı onlara güven verir, Ona güvenirler, 2 Ama gözü yürüdükleri yoldadır.'),
(1996854,68,18,24,24,'Kısa süre yükselir, sonra yok olurlar, 2 Düşerler, tıpkı ötekiler gibi alınıp götürülür, 2 Başak başı gibi kesilirler.›'),
(1996855,68,18,24,25,'‹‹Böyle değilse, kim beni yalancı çıkarabilir, 2 Söylediklerimin boş olduğunu gösterebilir?››'),
(1996856,68,18,25,1,'Şuahlı Bildat şöyle yanıtladı:'),
(1996857,68,18,25,2,'‹‹Egemenlik ve heybet Tanrıya özgüdür, 2 Yüce göklerde düzen kuran Odur.'),
(1996858,68,18,25,3,'Orduları sayılabilir mi? 2 Işığı kimin üzerine doğmaz?'),
(1996859,68,18,25,4,'İnsan Tanrının önünde nasıl doğru olabilir? 2 Kadından doğan biri nasıl temiz olabilir?'),
(1996860,68,18,25,5,'Onun gözünde ay parlak, 2 Yıldızlar temiz değilse,'),
(1996861,68,18,25,6,'Nerede kaldı bir kurtçuk olan insan, 2 Bir böcek olan insanoğlu!››'),
(1996862,68,18,26,1,'Eyüp şöyle yanıtladı:'),
(1996863,68,18,26,2,'‹‹Çaresize nasıl yardım ettin! 2 Güçsüz pazıyı nasıl kurtardın!'),
(1996864,68,18,26,3,'Bilge olmayana ne öğütler verdin! 2 Sağlam bilgiyi pek güzel öğrettin!'),
(1996865,68,18,26,4,'Bu sözleri kime söyledin? 2 Senin ağzından konuşan ruh kimin?'),
(1996866,68,18,26,5,'‹‹Suların ve sularda yaşayanların altında 2 Ölüler titriyor.'),
(1996867,68,18,26,6,'Tanrının önünde ölüler diyarı çıplaktır, 2 Yıkım diyarı örtüsüz.'),
(1996868,68,18,26,7,'O boşluğun üzerine kuzey göklerini yayar, 2 Hiçliğin üzerine dünyayı asar.'),
(1996869,68,18,26,8,'Bulutların içine suları sarar, 2 Bulutlar yırtılmaz onların ağırlığı altında.'),
(1996870,68,18,26,9,'Dolunayın yüzünü örter, 2 Üstüne bulutlarını serper.'),
(1996871,68,18,26,10,'Suların yüzeyine sınır çizer 2 Işıkla karanlığın ayrıldığı yerde.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996872,68,18,26,11,'Göklerin direkleri sarsılır, 2 Şaşkına dönerler O azarlayınca.'),
(1996873,68,18,26,12,'Gücüyle denizi çalkalar, 2 Ustaca Rahavı vurur. güçlerini simgeleyen bir deniz canavarı.'),
(1996874,68,18,26,13,'Gökler Onun soluğuyla açılır, 2 Onun eli parçalar kaçan yılanı.'),
(1996875,68,18,26,14,'Bunlar yaptıklarının küçücük parçaları, 2 O''ndan duyduğumuz hafif bir fısıltıdır. 2 Gürleyen gücünü kim anlayabilir?››fı sözleridir.'),
(1996876,68,18,27,1,'Eyüp anlatmaya devam etti:'),
(1996877,68,18,27,2,'‹‹Hakkımı elimden alan Tanrının varlığı hakkı için, 2 Bana acı çektiren Her Şeye Gücü Yetenin hakkı için,'),
(1996878,68,18,27,3,'İçimde yaşam belirtisi olduğu sürece, 2 Tanrının soluğu burnumda olduğu sürece,'),
(1996879,68,18,27,4,'Ağzımdan kötü söz çıkmayacak, 2 Dilimden yalan dökülmeyecek.'),
(1996880,68,18,27,5,'Size asla hak vermeyecek, 2 Son soluğumu verene dek suçsuz olduğumu söyleyeceğim.'),
(1996881,68,18,27,6,'Doğruluğuma sarılacak, onu bırakmayacağım, 2 Yaşadığım sürece vicdanım beni suçlamayacak.'),
(1996882,68,18,27,7,'‹‹Düşmanlarım kötüler gibi, 2 Bana saldıranlar haksızlar gibi cezalandırılsın.'),
(1996883,68,18,27,8,'Tanrısız insanın umudu nedir 2 Tanrı onu yok ettiğinde, canını aldığında?'),
(1996884,68,18,27,9,'Başına sıkıntı geldiğinde, 2 Tanrı feryadını duyar mı?'),
(1996885,68,18,27,10,'Her Şeye Gücü Yetenden zevk alır mı? 2 Her zaman Tanrıya yakarır mı?'),
(1996886,68,18,27,11,'‹‹Tanrının gücünü size öğreteceğim, 2 Her Şeye Gücü Yetenin tasarısını gizlemeyeceğim.'),
(1996887,68,18,27,12,'Aslında siz, hepiniz gördünüz bunu, 2 Öyleyse ne diye boş boş konuşuyorsunuz?'),
(1996888,68,18,27,13,'‹‹Kötünün Tanrıdan alacağı pay, 2 Zorbanın Her Şeye Gücü Yetenden alacağı miras şudur:'),
(1996889,68,18,27,14,'Çocukları ne kadar çok olursa olsun, kılıçla öldürülecek, 2 Soyu yeterince ekmek bulamayacaktır.'),
(1996890,68,18,27,15,'Sağ kalanlar hastalıktan ölüp gömülecek, 2 Dul karıları ağlamayacaktır.'),
(1996891,68,18,27,16,'Kötü insan kum gibi gümüş yığsa, 2 Yığınla giysi biriktirse,'),
(1996892,68,18,27,17,'Onun biriktirdiğini doğru insan giyecek, 2 Gümüşü suçsuz paylaşacak.'),
(1996893,68,18,27,18,'Evini güve kozası gibi inşa eder, 2 Bekçinin kurduğu çardak gibi.'),
(1996894,68,18,27,19,'Zengin olarak yatar, ama bu öyle sürmez, 2 Gözlerini açtığında hepsi yok olup gitmiştir.'),
(1996895,68,18,27,20,'Dehşet onu sel gibi basar, 2 Kasırga gece kapar götürür.'),
(1996896,68,18,27,21,'Doğu rüzgarı onu uçurup götürür, 2 Yerinden silip süpürür.'),
(1996897,68,18,27,22,'Acımasızca üzerine eser, 2 Elinden kaçmaya çalışırken.'),
(1996898,68,18,27,23,'Onunla alay ederek el çırpar, 2 Yerinden ıslık çalar.›› sözleridir.'),
(1996899,68,18,28,1,'Gümüş maden ocağından elde edilir, 2 Altını arıtmak için de bir yer vardır.'),
(1996900,68,18,28,2,'Demir topraktan çıkarılır, 2 Bakırsa taştan.'),
(1996901,68,18,28,3,'İnsan karanlığa son verir, 2 Koyu karanlığın, ölüm gölgesinin taşlarını 2 Son sınırına kadar araştırır.'),
(1996902,68,18,28,4,'Maden kuyusunu insanların oturduğu yerden uzakta açar, 2 İnsan ayağının unuttuğu yerlerde, 2 Herkesten uzak iplere sarılıp sallanır.'),
(1996903,68,18,28,5,'Ekmek topraktan çıkar, 2 Toprağın altı ise yanmış, altüst olmuştur.'),
(1996904,68,18,28,6,'Kayalarından laciverttaşı çıkar, 2 Yüzeyi altın tozunu andırır.'),
(1996905,68,18,28,7,'Yırtıcı kuş yolu bilmez, 2 Doğanın gözü onu görmemiştir.'),
(1996906,68,18,28,8,'Güçlü hayvanlar oraya ayak basmamış, 2 Aslan oradan geçmemiştir.'),
(1996907,68,18,28,9,'Madenci elini çakmak taşına uzatır, 2 Dağları kökünden altüst eder.'),
(1996908,68,18,28,10,'Kayaların içinden tüneller açar, 2 Gözleri değerli ne varsa görür.'),
(1996909,68,18,28,11,'Irmakların kaynağını tıkar, 2 Gizli olanı ışığa çıkarır.'),
(1996910,68,18,28,12,'Ama bilgelik nerede bulunur? 2 Aklın yeri neresi?'),
(1996911,68,18,28,13,'İnsan onun değerini bilmez, 2 Yaşayanlar diyarında ona rastlanmaz.'),
(1996912,68,18,28,14,'Engin, ‹‹Bende değil›› der, 2 Deniz, ‹‹Yanımda değil.››'),
(1996913,68,18,28,15,'Onun bedeli saf altınla ödenmez, 2 Değeri gümüşle ölçülmez.'),
(1996914,68,18,28,16,'Ona Ofir altınıyla, değerli oniksle, 2 Laciverttaşıyla değer biçilmez.'),
(1996915,68,18,28,17,'Ne altın ne cam onunla karşılaştırılabilir, 2 Saf altın kaplara değişilmez.'),
(1996916,68,18,28,18,'Yanında mercanla billurun sözü edilmez, 2 Bilgeliğin değeri mücevherden üstündür.'),
(1996917,68,18,28,19,'Kûş topazı onunla denk sayılmaz, 2 Saf altınla ona değer biçilmez.'),
(1996918,68,18,28,20,'Öyleyse bilgelik nereden geliyor? 2 Aklın yeri neresi?'),
(1996919,68,18,28,21,'O bütün canlıların gözünden uzaktır, 2 Gökte uçan kuşlardan bile saklıdır.'),
(1996920,68,18,28,22,'Yıkımla Ölüm: 2 ‹‹Kulaklarımız ancak fısıltısını duydu›› der.'),
(1996921,68,18,28,23,'Onun yolunu Tanrı anlar, 2 Yerini bilen Odur.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996922,68,18,28,24,'Çünkü O yeryüzünün uçlarına kadar bakar, 2 Göklerin altındaki her şeyi görür.'),
(1996923,68,18,28,25,'Rüzgara güç verdiği, 2 Suları ölçtüğü,'),
(1996924,68,18,28,26,'Yağmura kural koyduğu, 2 Yıldırıma yol açtığı zaman,'),
(1996925,68,18,28,27,'Bilgeliği görüp değerini biçti, 2 Onu onaylayıp araştırdı.'),
(1996926,68,18,28,28,'İnsana, ‹‹İşte Rab korkusu, bilgelik budur›› dedi, 2 ‹‹Kötülükten kaçınmak akıllılıktır.››'),
(1996927,68,18,29,1,'Eyüp yine anlatmaya başladı:'),
(1996928,68,18,29,2,'‹‹Keşke geçen aylar geri gelseydi, 2 Tanrının beni kolladığı,'),
(1996929,68,18,29,3,'Kandilinin başımın üstünde parladığı, 2 Işığıyla karanlıkta yürüdüğüm günler,'),
(1996930,68,18,29,4,'Keşke olgunluk günlerim geri gelseydi, 2 Tanrının çadırımı dostça koruduğu,'),
(1996931,68,18,29,5,'Her Şeye Gücü Yetenin henüz benimle olduğu, 2 Çocuklarımın çevremde bulunduğu,'),
(1996932,68,18,29,6,'Yollarımın sütle yıkandığı, 2 Yanımdaki kayanın zeytinyağı akıttığı günler!'),
(1996933,68,18,29,7,'‹‹Kent kapısına gidip 2 Kürsümü meydana koyduğumda,'),
(1996934,68,18,29,8,'Gençler beni görüp gizlenir, 2 Yaşlılar kalkıp ayakta dururlardı;'),
(1996935,68,18,29,9,'Önderler konuşmaktan çekinir, 2 Elleriyle ağızlarını kaparlardı;'),
(1996936,68,18,29,10,'Soyluların sesi kesilir, 2 Dilleri damaklarına yapışırdı.'),
(1996937,68,18,29,11,'Beni duyan kutlar, 2 Beni gören överdi;'),
(1996938,68,18,29,12,'Çünkü yardım isteyen yoksulu, 2 Desteği olmayan öksüzü kurtarırdım.'),
(1996939,68,18,29,13,'Ölmekte olanın hayır duasını alır, 2 Dul kadının yüreğini sevinçten coştururdum.'),
(1996940,68,18,29,14,'Doğruluğu giysi gibi giyindim, 2 Adalet kaftanım ve sarığımdı sanki.'),
(1996941,68,18,29,15,'Körlere göz, 2 Topallara ayaktım.'),
(1996942,68,18,29,16,'Yoksullara babalık eder, 2 Garibin davasını üstlenirdim.'),
(1996943,68,18,29,17,'Haksızın çenesini kırar, 2 Avını dişlerinin arasından kapardım.'),
(1996944,68,18,29,18,'‹‹ ‹Son soluğumu yuvamda vereceğim› diye düşünüyordum, 2 ‹Günlerim kum taneleri kadar çok.'),
(1996945,68,18,29,19,'Köküm sulara erişecek, 2 Çiy geceyi dallarımda geçirecek.'),
(1996946,68,18,29,20,'Aldığım övgüler tazelenecek, 2 Elimdeki yay yenilenecek.›'),
(1996947,68,18,29,21,'‹‹İnsanlar beni saygıyla dinler, 2 Öğüdümü sessizce beklerlerdi.'),
(1996948,68,18,29,22,'Ben konuştuktan sonra onlar konuşmazdı, 2 Sözlerim üzerlerine damlardı.'),
(1996949,68,18,29,23,'Yağmuru beklercesine beni bekler, 2 Son yağmurları içercesine sözlerimi içerlerdi.'),
(1996950,68,18,29,24,'Kendilerine gülümsediğimde gözlerine inanmazlardı, 2 Güler yüzlülüğüm onlara cesaret verirdi.'),
(1996951,68,18,29,25,'Onların yolunu ben seçer, başlarında dururdum, 2 Askerlerinin ortasında kral gibi otururdum, 2 Yaslıları avutan biri gibiydim.'),
(1996952,68,18,30,1,'‹‹Ama şimdi, yaşı benden küçük olanlar 2 Benimle alay etmekte, 2 Oysa babalarını sürümün köpeklerinin 2 Yanına koymaya tenezzül etmezdim.'),
(1996953,68,18,30,2,'Çünkü güçleri tükenmişti, 2 Bileklerinin gücü ne işime yarardı?'),
(1996954,68,18,30,3,'Yoksulluktan, açlıktan bitkindiler, 2 Akşam çölde, ıssız çorak yerlerde kök kemiriyorlardı.'),
(1996955,68,18,30,4,'Çalılıklarda karapazı topluyor, 2 Retem kökü yiyorlardı.'),
(1996956,68,18,30,5,'Toplumdan kovuluyorlardı, 2 İnsanlar hırsızmışlar gibi onlara bağırıyordu.'),
(1996957,68,18,30,6,'Korkunç vadilerde, yerdeki deliklerde, 2 Kaya kovuklarında yaşıyorlardı.'),
(1996958,68,18,30,7,'Çalıların arasında anırır, 2 Çalı altında birbirine sokulurlardı.'),
(1996959,68,18,30,8,'Aptalların, adı sanı belirsiz insanların çocuklarıydılar, 2 Ülkeden kovulmuşlardı.'),
(1996960,68,18,30,9,'‹‹Şimdiyse destan oldum dillerine, 2 Ağızlarına doladılar beni.'),
(1996961,68,18,30,10,'Benden tiksiniyor, uzak duruyorlar, 2 Yüzüme tükürmekten çekinmiyorlar.'),
(1996962,68,18,30,11,'Tanrı ipimi çözüp beni alçalttığı için 2 Dizginsiz davranmaya başladılar bana.'),
(1996963,68,18,30,12,'Sağımdaki ayak takımı üzerime yürüyor, 2 Ayaklarımı kaydırıyor, 2 Bana karşı rampalar kuruyorlar.'),
(1996964,68,18,30,13,'Yolumu kesiyor, 2 Kimseden yardım görmeden 2 Beni yok etmeye çalışıyorlar.'),
(1996965,68,18,30,14,'Koca bir gedikten girer gibi ilerliyor, 2 Yıkıntılar arasından üzerime yuvarlanıyorlar.'),
(1996966,68,18,30,15,'Dehşet çöktü üzerime, 2 Onurum rüzgara kapılmış gibi uçtu, 2 Mutluluğum bulut gibi geçip gitti.'),
(1996967,68,18,30,16,'‹‹Şimdi tükeniyorum, 2 Acı günler beni ele geçirdi.'),
(1996968,68,18,30,17,'Geceleri kemiklerim sızlıyor, 2 Beni kemiren acılar hiç durmuyor.'),
(1996969,68,18,30,18,'Tanrının şiddeti 2 Üzerimdeki giysiye dönüştü, 2 Gömleğimin yakası gibi beni sıkıyor.'),
(1996970,68,18,30,19,'Beni çamura fırlattı, 2 Toza, küle döndüm.'),
(1996971,68,18,30,20,'‹‹Sana yakarıyorum, ama yanıt vermiyorsun, 2 Ayağa kalktığımda gözünü bana dikiyorsun.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1996972,68,18,30,21,'Bana acımasız davranıyor, 2 Bileğinin gücüyle beni eziyorsun.'),
(1996973,68,18,30,22,'Beni kaldırıp rüzgara bindiriyorsun, 2 Fırtınanın içinde darma duman ediyorsun.'),
(1996974,68,18,30,23,'Biliyorum, beni ölüme, 2 Bütün canlıların toplanacağı yere götüreceksin.'),
(1996975,68,18,30,24,'‹‹Kuşkusuz düşenin dostu olmaz, 2 Felakete uğrayıp yardım istediğinde.'),
(1996976,68,18,30,25,'Sıkıntıya düşenler için ağlamaz mıydım? 2 Yoksullar için üzülmez miydim?'),
(1996977,68,18,30,26,'Ama ben iyilik beklerken kötülük geldi, 2 Işık umarken karanlık geldi.'),
(1996978,68,18,30,27,'İçim kaynıyor, rahatım yok, 2 Önümde acı günler var.'),
(1996979,68,18,30,28,'Yaslı yaslı dolaşıyorum, güneş yok, 2 Topluluk içinde kalkıp feryat ediyorum.'),
(1996980,68,18,30,29,'Çakallarla kardeş, 2 Baykuşlarla arkadaş oldum.'),
(1996981,68,18,30,30,'Derim karardı, soyuluyor, 2 Kemiklerim ateşten yanıyor.'),
(1996982,68,18,30,31,'Lirimin sesi yas feryadına, 2 Neyimin sesi ağlayanların sesine döndü.'),
(1996983,68,18,31,1,'‹‹Gözlerimle antlaşma yaptım 2 Şehvetle bir kıza bakmamak için.'),
(1996984,68,18,31,2,'Çünkü insanın yukarıdan, Tanrıdan payı nedir, 2 Yücelerden, Her Şeye Gücü Yetenden mirası ne?'),
(1996985,68,18,31,3,'Kötüler için felaket, 2 Haksızlık yapanlar için bela değil mi?'),
(1996986,68,18,31,4,'Yürüdüğüm yolları görmüyor mu, 2 Attığım her adımı saymıyor mu?'),
(1996987,68,18,31,5,'‹‹Eğer yalan yolunda yürüdümse, 2 Ayağım hileye seğirttiyse,'),
(1996988,68,18,31,6,'-Tanrı beni doğru teraziyle tartsın, 2 Kusursuz olduğumu görsün-'),
(1996989,68,18,31,7,'Adımım yoldan saptıysa, 2 Yüreğim gözümü izlediyse, 2 Ellerim pisliğe bulaştıysa,'),
(1996990,68,18,31,8,'Ektiğimi başkaları yesin, 2 Ekinlerim kökünden sökülsün.'),
(1996991,68,18,31,9,'‹‹Eğer gönlümü bir kadına kaptırdıysam, 2 Komşumun kapısında pusuya yattıysam,'),
(1996992,68,18,31,10,'Karım başkasının buğdayını öğütsün, 2 Onunla başka erkekler yatsın.'),
(1996993,68,18,31,11,'Çünkü bu utanç verici, 2 Yargılanması gereken bir suç olurdu.'),
(1996994,68,18,31,12,'Yıkım diyarına dek yakan bir ateştir o, 2 Bütün ürünümü kökünden kavururdu.'),
(1996995,68,18,31,13,'‹‹Benimle ters düştüklerinde 2 Kölemin ve hizmetçimin hakkını yemişsem,'),
(1996996,68,18,31,14,'Tanrı yargıladığında ne yaparım? 2 Hesap sorduğunda ne yanıt veririm?'),
(1996997,68,18,31,15,'Beni ana karnında yaratan onu da yaratmadı mı? 2 Rahimde bize biçim veren O değil mi?'),
(1996998,68,18,31,16,'‹‹Eğer yoksulların dileğini geri çevirdimse, 2 Dul kadının umudunu kırdımsa,'),
(1996999,68,18,31,17,'Ekmeğimi yalnız yedim, 2 Öksüzle paylaşmadımsa,'),
(1997000,68,18,31,18,'Gençliğimden beri öksüzü baba gibi büyütmedimse, 2 Doğduğumdan beri dul kadına yol göstermedimse,'),
(1997001,68,18,31,19,'Giysisi olmadığı için can çekişen birini 2 Ya da örtüsü olmayan bir yoksulu gördüm de,'),
(1997002,68,18,31,20,'Koyunlarımın yünüyle ısıtmadıysam, 2 O da içinden beni kutsamadıysa,'),
(1997003,68,18,31,21,'Mahkemede sözümün geçtiğini bilerek 2 Öksüze el kaldırdımsa,'),
(1997004,68,18,31,22,'Kolum omuzumdan düşsün, 2 Kol kemiğim kırılsın.'),
(1997005,68,18,31,23,'Çünkü Tanrıdan gelecek beladan korkarım, 2 Onun görkeminden ötürü böyle bir şey yapamam.'),
(1997006,68,18,31,24,'‹‹Eğer umudumu altına bağladımsa, 2 Saf altına, ‹Güvencim sensin› dedimse,'),
(1997007,68,18,31,25,'Servetim çok, 2 Varlığımı bileğimle kazandım diye sevindimse,'),
(1997008,68,18,31,26,'Işıldayan güneşe, 2 Parıldayarak hareket eden aya bakıp da,'),
(1997009,68,18,31,27,'İçimden ayartıldımsa, 2 Elim onlara taptığımı gösteren bir öpücük yolladıysa,'),
(1997010,68,18,31,28,'Bu da yargılanacak bir suç olurdu, 2 Çünkü yücelerdeki Tanrıyı yadsımış olurdum.'),
(1997011,68,18,31,29,'‹‹Eğer düşmanımın yıkımına sevindim, 2 Başına kötülük geldi diye keyiflendimse,'),
(1997012,68,18,31,30,'-Kimsenin canına lanet ederek 2 Ağzımın günah işlemesine izin vermedim-'),
(1997013,68,18,31,31,'Evimdeki insanlar, ‹Eyüpün verdiği etle 2 Karnını doyurmayan var mı?› diye sormadıysa,'),
(1997014,68,18,31,32,'-Hiçbir yabancı geceyi sokakta geçirmezdi, 2 Çünkü kapım her zaman yolculara açıktı-'),
(1997015,68,18,31,33,'Kalabalıktan çok korktuğum, 2 Boyların aşağılamasından yıldığım, 2 Susup dışarı çıkmadığım için 2 Suçumu bağrımda gizleyip 2 Adem gibi isyanımı örttümse,'),
(1997016,68,18,31,35,'-‹‹Keşke beni dinleyen biri olsa! 2 İşte savunmamı imzalıyorum, 2 Her Şeye Gücü Yeten bana yanıt versin! 2 Hasmımın yazdığı tomar elimde olsa,'),
(1997017,68,18,31,36,'Kuşkusuz onu omuzumda taşır, 2 Taç gibi başıma koyardım.'),
(1997018,68,18,31,37,'Attığım her adımı ona bildirir, 2 Kendisine bir önder gibi yaklaşırdım.-'),
(1997019,68,18,31,38,'‹‹Toprağım bana feryat ediyorsa, 2 Sabanın açtığı yarıklar bir ağızdan ağlıyorsa,'),
(1997020,68,18,31,39,'Ürününü para ödemeden yedimse 2 Ya da üzerinde oturanların kalbini kırdımsa,'),
(1997021,68,18,31,40,'Orada buğday yerine diken, 2 Arpa yerine delice bitsin.›› Eyüp''ün konuşması sona erdi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997022,68,18,32,1,'Böylece bu üç kişi Eyüpe yanıt vermekten vaz geçti, çünkü Eyüp kendi doğruluğundan emindi.'),
(1997023,68,18,32,2,'Ram ailesinden Bûzlu Barakel oğlu Elihu Eyüpe çok öfkelendi. Çünkü Eyüp kendini Tanrıdan haklı görüyordu.'),
(1997024,68,18,32,3,'Elihu Eyüpün üç arkadaşına da öfkelendi, çünkü Eyüpü suçlamalarına karşın sağlam bir yanıt bulamamışlardı.'),
(1997025,68,18,32,4,'Elihu Eyüple konuşmak için sırasını beklemişti, çünkü ötekiler yaşça kendisinden büyüktü.'),
(1997026,68,18,32,5,'Bu üç kişinin başka bir şey söyleyemeyeceğini görünce öfkesi alevlendi. ‹‹Tanrıyı››.'),
(1997027,68,18,32,6,'Bûzlu Barakel oğlu Elihu şöyle konuştu: ‹‹Ben yaşça küçüğüm, sizse yaşlısınız. 2 Bu yüzden çekindim, bildiğimi söylemekten korktum.'),
(1997028,68,18,32,7,'‹Çok gün görenler konuşsun› dedim, 2 ‹Çok yıl yaşayanlar bilgeliği öğretsin.›'),
(1997029,68,18,32,8,'Oysa insana ruh, 2 Her Şeye Gücü Yetenin soluğu akıl verir.'),
(1997030,68,18,32,9,'Akıl yaşta değil baştadır. 2 Adaleti anlamak yaşa bakmaz.'),
(1997031,68,18,32,10,'‹‹Bu yüzden, ‹Beni dinleyin› diyorum, 2 Ben de bildiğimi söyleyeyim.'),
(1997032,68,18,32,11,'Siz konuşurken ben bekledim, 2 Siz ne diyeceğinizi araştırırken 2 Düşüncelerinizi dinledim.'),
(1997033,68,18,32,12,'Bütün dikkatimi size çevirdim. 2 Ama hiçbiriniz Eyüpün haksızlığını kanıtlayamadı, 2 Onun söylediklerine karşılık veremedi.'),
(1997034,68,18,32,13,'‹Biz bilgeliğe eriştik, 2 Bırakın Tanrı onu haksız çıkarsın, insan değil› demeyin.'),
(1997035,68,18,32,14,'Ama Eyüpün sözlerinin hedefi ben değildim, 2 Bu yüzden onu sizin sözlerinizle yanıtlamayacağım.'),
(1997036,68,18,32,15,'‹‹Onlar yıldı, yanıt veremiyorlar artık, 2 Söyleyecek şeyleri kalmadı.'),
(1997037,68,18,32,16,'Onlar konuşmuyor diye ben beklemeli miyim, 2 Duruyor, yanıt vermiyorlar diye?'),
(1997038,68,18,32,17,'Benim de söyleyecek sözüm var, 2 Ben de bildiğimi söyleyeceğim.'),
(1997039,68,18,32,18,'Çünkü içim dolu, 2 İçimdeki ruh beni zorluyor.'),
(1997040,68,18,32,19,'İçim açılmamış şarap gibi, 2 Yeni şarap tulumları gibi patlamak üzere.'),
(1997041,68,18,32,20,'Konuşup rahatlamalıyım, 2 Ağzımı açıp yanıtlamalıyım.'),
(1997042,68,18,32,21,'Kimseye ayrıcalık göstermeyecek, 2 Kimseye yaltaklanmayacağım.'),
(1997043,68,18,32,22,'Çünkü yaltaklanmayı bilsem, 2 Yaratıcım beni hemen yok ederdi.'),
(1997044,68,18,33,1,'‹‹Ama şimdi lütfen sözümü dinle, Eyüp, 2 Söyleyeceğim her şeye kulak ver.'),
(1997045,68,18,33,2,'Ağzımı açtım açacağım, 2 Söyleyeceklerim dilimin ucunda.'),
(1997046,68,18,33,3,'Sözlerim temiz bir yürekten çıkıyor, 2 Dudaklarım bildiklerini içtenlikle söylüyor.'),
(1997047,68,18,33,4,'Beni Tanrının Ruhu yarattı, 2 Her Şeye Gücü Yetenin soluğu yaşam veriyor bana.'),
(1997048,68,18,33,5,'Elinden gelirse beni yanıtla, 2 Kendini hazırla, karşımda dur.'),
(1997049,68,18,33,6,'Tanrının önünde ben de tıpkı senin gibiyim, 2 Ben de balçıktan yaratıldım.'),
(1997050,68,18,33,7,'Onun için dehşetim seni yıldırmasın, 2 Baskım sana ağır gelmesin.'),
(1997051,68,18,33,8,'‹‹Sesin hâlâ kulaklarımda, 2 Şöyle demiştin:'),
(1997052,68,18,33,9,'‹Ben kusursuz ve günahsızım, 2 Temiz ve suçsuzum.'),
(1997053,68,18,33,10,'Yine de Tanrı bana karşı bahane arıyor, 2 Beni düşman görüyor.'),
(1997054,68,18,33,11,'Ayaklarımı tomruğa vuruyor, 2 Yollarımı gözetliyor.›'),
(1997055,68,18,33,12,'‹‹Ama sana şunu söyleyeyim, 2 Bu konuda haksızsın. 2 Çünkü Tanrı insandan büyüktür.'),
(1997056,68,18,33,13,'İnsanın hiçbir sözünü yanıtlamıyor diye 2 Niçin Onunla çekişiyorsun?'),
(1997057,68,18,33,14,'Çünkü insan anlamasa da, 2 Tanrı şu ya da bu yolla konuşur.'),
(1997058,68,18,33,15,'Rüyada, geceleyin görümde, 2 İnsanları ağır uyku basınca, 2 Yatakta yatarlarken,'),
(1997059,68,18,33,16,'Kulaklarına konuşur, 2 Uyarısıyla onları korkutur;'),
(1997060,68,18,33,17,'Onları yaptıkları kötülükten döndürmek, 2 Gururdan uzak tutmak,'),
(1997061,68,18,33,18,'Canlarını çukurdan, 2 Hayatlarını ölümden kurtarmak için.'),
(1997062,68,18,33,19,'İnsan yatağında acılarla, 2 Kemiklerinde dinmez sızılarla yola getirilir.'),
(1997063,68,18,33,20,'Öyle ki, içi yemek kaldırmaz, 2 En lezzetli yiyecekten tiksinir.'),
(1997064,68,18,33,21,'Eti erir, görünmez olur, 2 Gözükmeyen kemikleri ortaya çıkar.'),
(1997065,68,18,33,22,'Canı çukura, 2 Hayatı ölüm meleklerine yaklaşır.'),
(1997066,68,18,33,23,'‹‹Yine de insana doğruyu bildirmek için 2 Yanında bir melek, bin melekten biri 2 Arabulucu olarak bulunursa,'),
(1997067,68,18,33,24,'Ona lütfeder de, 2 ‹Onu ölüm çukuruna inmekten kurtar, 2 Ben fidyeyi buldum› derse,'),
(1997068,68,18,33,25,'Eti çocuk eti gibi yenilenir, 2 Gençlik günlerine döner.'),
(1997069,68,18,33,26,'Dua ettiğinde Tanrı ondan hoşnut kalır, 2 O da Tanrının yüzünü görüp sevinir. 2 Tanrı onun durumunu düzeltir.'),
(1997070,68,18,33,27,'Sonra insanların önünde türkü çağırır: 2 ‹Günah işleyip doğru yoldan saptım, 2 Ama Tanrı hak ettiğim cezayı vermedi bana,'),
(1997071,68,18,33,28,'Canımı çukura inmekten O kurtardı, 2 Işığı görmek için yaşayacağım.›');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997072,68,18,33,29,'‹‹İşte, insanın canını çukurdan çıkarmak, 2 Onu yaşam ışığıyla aydınlatmak için 2 Tanrı bütün bunları iki kez, 2 Hatta üç kez yapar.'),
(1997073,68,18,33,31,'‹‹İyi dinle, Eyüp, kulak ver, 2 Sen sus, ben konuşacağım.'),
(1997074,68,18,33,32,'Söyleyeceğin bir şey varsa söyle, 2 Çünkü seni haklı çıkarmak isterim.'),
(1997075,68,18,33,33,'Yoksa, beni dinle, 2 Sus da sana bilgelik öğreteyim.››'),
(1997076,68,18,34,1,'Elihu konuşmasına şöyle devam etti:'),
(1997077,68,18,34,2,'‹‹Ey bilgeler, sözlerimi dinleyin, 2 Kulak verin bana, ey bilgi sahipleri.'),
(1997078,68,18,34,3,'Çünkü damak nasıl yemeği tadarsa, 2 Kulak da sözleri sınar.'),
(1997079,68,18,34,4,'Gelin, doğruyu seçelim, 2 İyiyi birlikte öğrenelim.'),
(1997080,68,18,34,5,'‹‹Çünkü Eyüp, ‹Ben suçsuzum› diyor, 2 ‹Tanrı hakkımı elimden aldı.'),
(1997081,68,18,34,6,'Haklı olduğum halde yalancı sayılıyorum, 2 Suçsuz olduğum halde okunla yaraladın beni.›'),
(1997082,68,18,34,7,'Eyüp gibisi var mı? 2 Alayı su gibi içiyor!'),
(1997083,68,18,34,8,'Kötülük yapanlarla dostluk edip geziyor, 2 Kötülerle aynı yolda yürüyor.'),
(1997084,68,18,34,9,'Çünkü, ‹Tanrıyı hoşnut etmeye çalışmak 2 İnsana yarar getirmez› diyor.'),
(1997085,68,18,34,10,'‹‹Bu yüzden, ey sağduyulu insanlar, beni dinleyin! 2 Tanrı kötülük yapar mı, 2 Her Şeye Gücü Yeten haksızlık eder mi? Asla!'),
(1997086,68,18,34,11,'Çünkü O herkese yaptığının karşılığını öder, 2 Hak ettiğini başına getirir.'),
(1997087,68,18,34,12,'Tanrı kesinlikle kötülük etmez, 2 Her Şeye Gücü Yeten adaleti saptırmaz.'),
(1997088,68,18,34,13,'Kim yeryüzünü Ona emanet etti? 2 Kim Onu bütün dünyanın başına atadı?'),
(1997089,68,18,34,14,'Eğer niyet eder de 2 Ruhunu ve soluğunu geri çekerse,'),
(1997090,68,18,34,15,'Bütün insanlık bir anda yok olur, 2 İnsan yine toprağa döner.'),
(1997091,68,18,34,16,'‹‹Aklın varsa dinle, 2 Kulak ver sözlerime.'),
(1997092,68,18,34,17,'Adaletten nefret eden hiç hüküm sürebilir mi? 2 Adil ve güçlü olanı suçlayacak mısın?'),
(1997093,68,18,34,18,'Krallara, ‹Değersizsiniz›, 2 Soylulara, ‹Kötüsünüz› diyen,'),
(1997094,68,18,34,19,'Önderlere ayrıcalık tanımayan, 2 Zengini yoksuldan çok önemsemeyen O değil mi? 2 Çünkü hepsi Onun ellerinin işidir.'),
(1997095,68,18,34,20,'Gece yarısı bir anda ölürler, 2 Herkes sarsılır, ölüp gider, 2 Güçlüler de insan eli değmeden alınıp götürülür.'),
(1997096,68,18,34,21,'‹‹Tanrının gözleri insanların yolundan ayrılmaz, 2 Attıkları her adımı görür.'),
(1997097,68,18,34,22,'Kötülük yapanların gizlenebileceği 2 Ne karanlık bir yer vardır, ne de ölüm gölgesi.'),
(1997098,68,18,34,23,'Yargılanmak için önüne gelsinler diye, 2 Tanrı insanları sorgulamaya pek gerek duymaz.'),
(1997099,68,18,34,24,'Araştırmadan güçlü insanları kırar, 2 Onların yerine başkalarını diker.'),
(1997100,68,18,34,25,'Çünkü ne yaptıklarını bilir, 2 Gece onları deviriverir, ezilirler.'),
(1997101,68,18,34,26,'Herkesin gözü önünde 2 Kötülükleri yüzünden onları cezalandırır;'),
(1997102,68,18,34,27,'Artık Onun ardından gitmedikleri, 2 Yollarının hiçbirini dikkate almadıkları için.'),
(1997103,68,18,34,28,'Yoksulun feryadını Ona duyurdular; 2 Düşkünlerin feryadını işitti.'),
(1997104,68,18,34,29,'Ama Tanrı sessiz kalırsa kim Onu suçlayabilir? 2 Yüzünü gizlerse kim Onu görebilir? 2 Bir ulusa karşı da bir insana karşı da O hep aynıdır,'),
(1997105,68,18,34,30,'Tanrısız insan krallık etmesin, 2 Halka tuzak kurmasın diye.'),
(1997106,68,18,34,31,'‹‹Kimse Tanrıya, 2 ‹Suçluyum, artık kötülük yapmayacağım› dedi mi,'),
(1997107,68,18,34,32,'‹Göremediğimi sen bana öğret, 2 Haksızlık ettimse, bir daha etmem?›'),
(1997108,68,18,34,33,'Onu reddettiğin halde, 2 Senin keyfince mi seni ödüllendirmeli? 2 Çünkü karar verecek olan sensin, ben değil, 2 Öyleyse anlat bana bildiğini.'),
(1997109,68,18,34,34,'‹‹Sağduyulu insanlar, 2 Beni dinleyen bilgeler diyecekler ki,'),
(1997110,68,18,34,35,'‹Eyüp bilgisizce konuşuyor, 2 Sözlerinin değeri yok.›'),
(1997111,68,18,34,36,'Kötü biri gibi yanıtladığı için 2 Keşke Eyüpün sınanması sonsuza dek sürse!'),
(1997112,68,18,34,37,'Çünkü günahına isyan da ekliyor, 2 Önümüzde alay edercesine el çırpıyor, 2 Tanrı''ya karşı konuştukça konuşuyor.››'),
(1997113,68,18,35,1,'Elihu konuşmasına şöyle devam etti:'),
(1997114,68,18,35,2,'‹‹ ‹Tanrının önünde haklıyım› diyorsun. 2 Doğru buluyor musun bunu?'),
(1997115,68,18,35,3,'Ama hâlâ, ‹Günah işlemezsem 2 Yararım ne, kazancım ne?› diye soruyorsun.'),
(1997116,68,18,35,4,'‹‹Ben yanıtlayayım seni 2 Ve arkadaşlarını.'),
(1997117,68,18,35,5,'Göklere bak da gör, 2 Üzerinde yükselen bulutlara göz gezdir.'),
(1997118,68,18,35,6,'Günah işlersen, Tanrıya ne zararı olur? 2 İsyanların çoksa ne olur Ona?'),
(1997119,68,18,35,7,'Doğruysan, Ona verdiğin nedir, 2 Ya da ne alır O senin elinden?'),
(1997120,68,18,35,8,'Kötülüğün ancak senin gibi birine zarar verir, 2 Doğruluğun ise yalnız insanoğlu içindir.'),
(1997121,68,18,35,9,'‹‹İnsanlar ağır baskı altında feryat ediyor, 2 Güçlülere karşı yardım istiyor.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997122,68,18,35,10,'Ama kimse, ‹Nerede Yaratıcım Tanrı?› demiyor; 2 O Tanrı ki, gece bize ezgiler verir,'),
(1997123,68,18,35,11,'Yeryüzündeki hayvanlardan çok bize öğretir 2 Ve bizi gökteki kuşlardan daha bilge kılar.'),
(1997124,68,18,35,12,'Kötülerin gururu yüzünden insanlar feryat ediyor, 2 Ama yanıtlayan yok.'),
(1997125,68,18,35,13,'Gerçek şu ki, Tanrı boş feryadı dinlemez, 2 Her Şeye Gücü Yeten bunu önemsemez.'),
(1997126,68,18,35,14,'Onu görmediğini söylediğin zaman bile 2 Davan Onun önündedir, bekle;'),
(1997127,68,18,35,15,'Madem bu öfkeyle şimdi cezalandırmadı, 2 İsyana da pek aldırmaz diyorsun.'),
(1997128,68,18,35,16,'Bu yüzden Eyüp ağzını boş yere açıyor, 2 Bilgisizce konuştukça konuşuyor.››'),
(1997129,68,18,36,1,'Elihu konuşmasına şöyle devam etti:'),
(1997130,68,18,36,2,'‹‹Biraz bekle, sana açıklayayım, 2 Çünkü Tanrı için söylenecek daha çok söz var.'),
(1997131,68,18,36,3,'Bilgimi geniş kaynaklardan toplayacağım, 2 Yaratıcıma hak vereceğim.'),
(1997132,68,18,36,4,'Kuşkusuz söylediğim hiçbir şey yalan değil, 2 Karşında bilgide yetkin biri var.'),
(1997133,68,18,36,5,'‹‹Tanrı güçlüdür, ama kimseyi hor görmez, 2 Güçlü ve amacında kararlı.'),
(1997134,68,18,36,6,'Kötüleri yaşatmaz, 2 Ezilenin hakkını verir.'),
(1997135,68,18,36,7,'Gözlerini doğru kişiden ayırmaz, 2 Onu krallarla birlikte tahta oturtur, 2 Sonsuza dek yükseltir.'),
(1997136,68,18,36,8,'Ama insanlar zincire vurulur, 2 Baskı altında tutulurlarsa,'),
(1997137,68,18,36,9,'Onlara yaptıklarını, 2 Gurura kapılıp isyan ettiklerini bildirir.'),
(1997138,68,18,36,10,'Öğüdünü dinletir, 2 Kötülükten dönmelerini buyurur.'),
(1997139,68,18,36,11,'Eğer dinler ve Ona kulluk ederlerse, 2 Kalan günlerini bolluk, 2 Yıllarını rahatlık içinde geçirirler.'),
(1997140,68,18,36,12,'Ama dinlemezlerse ölür, 2 Ders almadan yok olurlar.'),
(1997141,68,18,36,13,'‹‹Tanrısızlar öfkelerini içlerinde gizler, 2 Kendilerini bağladığında Tanrıdan yardım istemezler.'),
(1997142,68,18,36,14,'Genç yaşta ölüp giderler, 2 Yaşamları putperest tapınaklarında fuhşu iş edinmiş erkekler arasında sona erer.'),
(1997143,68,18,36,15,'Ama Tanrı acı çekenleri acı çektikleri için kurtarır, 2 Düşkünlere kendini dinletir.'),
(1997144,68,18,36,16,'‹‹Evet, seni sıkıntıdan çeker çıkarırdı; 2 Darlığın olmadığı geniş bir yere, 2 Zengin yiyeceklerle bezenmiş bir sofraya.'),
(1997145,68,18,36,17,'Oysa şimdi kötülerin hak ettiği cezayı çekiyorsun, 2 Yargı ve adalet yakalamış seni.'),
(1997146,68,18,36,18,'Dikkat et, para seni baştan çıkarmasın, 2 Büyük bir rüşvet seni saptırmasın.'),
(1997147,68,18,36,19,'Zenginliğin ya da bütün gücün yeter mi 2 Sıkıntı çekmeni önlemeye?'),
(1997148,68,18,36,20,'Halkların yeryüzünden 2 Yok edildiği geceyi özleme.'),
(1997149,68,18,36,21,'Dikkat et, kötülüğe dönme, 2 Çünkü sen onu düşkünlüğe yeğledin.'),
(1997150,68,18,36,22,'‹‹İşte Tanrı gücüyle yükselir, 2 Onun gibi öğretmen var mı?'),
(1997151,68,18,36,23,'Kim Ona ne yapması gerektiğini söyleyebilir? 2 Kim Ona, ‹Haksızlık ettin› diyebilir?'),
(1997152,68,18,36,24,'Onun işlerini yüceltmelisin, anımsa bunu, 2 İnsanların ezgilerle övdüğü işlerini.'),
(1997153,68,18,36,25,'Bütün insanlar bunları görmüştür, 2 Herkes onları uzaktan izler.'),
(1997154,68,18,36,26,'Evet, Tanrı öyle büyüktür ki, Onu anlayamayız, 2 Varlığının süresi hesaplanamaz.'),
(1997155,68,18,36,27,'‹‹Su damlalarını yukarı çeker, 2 Buharından yağmur damlatır.'),
(1997156,68,18,36,28,'Bulutlar nemini döker, 2 İnsanların üzerine bol yağmur yağdırır.'),
(1997157,68,18,36,29,'Bulutları nasıl yaydığını, 2 Göksel konutundan nasıl gürlediğini kim anlayabilir?'),
(1997158,68,18,36,30,'Şimşekleri çevresine nasıl yaydığına, 2 Denizin dibine dek nasıl ulaştırdığına bakın.'),
(1997159,68,18,36,31,'Tanrı halkları böyle yönetir, 2 Bol yiyecek sağlar.'),
(1997160,68,18,36,32,'Şimşeği elleriyle tutar, 2 Hedefine vurmasını buyurur.'),
(1997161,68,18,36,33,'O''nun gürleyişi fırtınayı haber verir, 2 Sığırlar bile fırtına kopacağını bildirir.'),
(1997162,68,18,37,1,'‹‹Yüreğim titrer buna, 2 Yerinden oynar.'),
(1997163,68,18,37,2,'Dinleyin, gürleyen sesini dinleyin, 2 Ağzından çıkan sesi!'),
(1997164,68,18,37,3,'Şimşeğini göğün altındaki her yere, 2 Yeryüzünün dört bucağına salar.'),
(1997165,68,18,37,4,'Ardından bir ses gümbürder, 2 Görkemli sesiyle gürler. 2 Sesi duyulunca şimşekleri alıkoymaz.'),
(1997166,68,18,37,5,'Tanrının sesi şaşılacak biçimde gürler, 2 O, anlayışımızın ötesinde büyük işler yapar.'),
(1997167,68,18,37,6,'Çünkü kara, ‹Yere düş› der, 2 Sağanağa, ‹Bütün şiddetinle boşal.›'),
(1997168,68,18,37,7,'Yarattığı bütün insanlar ne yaptığını bilsin diye, 2 Herkese işini bıraktırır.'),
(1997169,68,18,37,8,'Hayvanlar kovuklarına girer, 2 İnlerinde otururlar.'),
(1997170,68,18,37,9,'Kasırga yuvasından kopar, 2 Soğuk saçılan rüzgarlardan.'),
(1997171,68,18,37,10,'Tanrının soluğu suları dondurur, 2 Geniş sular buz tutar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997172,68,18,37,11,'Bulutlara nem yükler, 2 Şimşeğini her yana yayar.'),
(1997173,68,18,37,12,'Yeryüzünde ne buyurursa yapmak üzere 2 Bulutlar Onun istediği yönde döner durur.'),
(1997174,68,18,37,13,'Ya insanları cezalandırmak 2 Ya da yeryüzünü sulayıp sevgisini göstermek için 2 Yağmur gönderir.'),
(1997175,68,18,37,14,'‹‹Dinle, Eyüp, 2 Dur da düşün Tanrının şaşılası işlerini.'),
(1997176,68,18,37,15,'Tanrının bulutları nasıl düzenlediğini, 2 Şimşeğini nasıl çaktırdığını biliyor musun?'),
(1997177,68,18,37,16,'Bulutların dengesini, 2 Bilgisi kusursuz olanın şaşılası işlerini biliyor musun?'),
(1997178,68,18,37,17,'Dünyanın soluğu kesildiğinde 2 Güneyin kavurucu rüzgarı altında 2 Giysilerin seni terletmez mi?'),
(1997179,68,18,37,18,'Dökme tunç bir ayna kadar sert olan gökkubbeyi 2 Onunla birlikte yayabilir misin?'),
(1997180,68,18,37,19,'‹‹Ona ne söyleyeceğimizi öğret bize, 2 Çünkü karanlık yüzünden sözümüze düzen veremiyoruz.'),
(1997181,68,18,37,20,'Konuşmak istediğim Ona söylenebilir mi? 2 Kimse yutulmak ister mi?'),
(1997182,68,18,37,21,'Rüzgar geçip göğü temizlediğinde 2 Gökte parıldayan ışığa kimse bakamaz.'),
(1997183,68,18,37,22,'Altın parıltısı geliyor kuzeyden, 2 Tanrı korkunç görkeme bürünmüş.'),
(1997184,68,18,37,23,'Her Şeye Gücü Yetene biz ulaşamayız. 2 Gücü yücedir, 2 Adaleti ve eşsiz doğruluğuyla kimseyi ezmez.'),
(1997185,68,18,37,24,'Bu yüzden insanlar O''na saygı duyar, 2 Çünkü O, bilgeleri dikkate almaz.››'),
(1997186,68,18,38,1,'RAB kasırganın içinden Eyüpü şöyle yanıtladı:'),
(1997187,68,18,38,2,'‹‹Bilgisizce sözlerle 2 Tasarımı karartan bu adam kim?'),
(1997188,68,18,38,3,'Şimdi erkek gibi kuşağını beline vur da, 2 Ben sorayım, sen anlat.'),
(1997189,68,18,38,4,'‹‹Ben dünyanın temelini atarken sen neredeydin? 2 Anlıyorsan söyle.'),
(1997190,68,18,38,5,'Kim saptadı onun ölçülerini? Kuşkusuz biliyorsun! 2 Kim çekti ipi üzerine?'),
(1997191,68,18,38,6,'Neyin üstüne yapıldı temelleri? 2 Kim koydu köşe taşını,'),
(1997192,68,18,38,7,'Sabah yıldızları birlikte şarkı söylerken, 2 İlahi varlıklar sevinçle çığrışırken?'),
(1997193,68,18,38,8,'‹‹Denizin ardından kapıları kim kapadı, 2 Ana rahminden fışkırdığı zaman;'),
(1997194,68,18,38,9,'Ona bulutları giysi, 2 Koyu karanlığı kundak yaptığım,'),
(1997195,68,18,38,10,'Sınırını koyduğum, 2 Kapılarıyla sürgülerini yerleştirdiğim,'),
(1997196,68,18,38,11,'‹Buraya kadar gelip öteye geçmeyeceksin, 2 Gururlu dalgaların şurada duracak› dediğim zaman?'),
(1997197,68,18,38,12,'‹‹Sen ömründe sabaha buyruk verdin mi, 2 Şafağa yerini gösterdin mi;'),
(1997198,68,18,38,13,'Yeryüzünün uçlarını tutsun, 2 Oradaki kötüler silkilip atılsın diye?'),
(1997199,68,18,38,14,'Mühür basılan balçık gibi biçim değiştirir yeryüzü, 2 Giysi kıvrımları gibi göze çarpar.'),
(1997200,68,18,38,15,'Kötülerin ışıkları alınır, 2 Kalkan kolları kırılır.'),
(1997201,68,18,38,16,'‹‹Denizin kaynaklarına vardın mı, 2 Gezdin mi enginin diplerinde?'),
(1997202,68,18,38,17,'Ölüm kapıları sana gösterildi mi? 2 Gördün mü ölüm gölgesinin kapılarını?'),
(1997203,68,18,38,18,'Dünyanın genişliğini kavradın mı? 2 Anlat bana, bütün bunları biliyorsan.'),
(1997204,68,18,38,19,'‹‹Işığın bulunduğu yerin yolu nerede? 2 Ya karanlık, onun yeri neresi?'),
(1997205,68,18,38,20,'Onları yerlerine götürebilir misin? 2 Evlerinin yolunu biliyor musun?'),
(1997206,68,18,38,21,'Bilmediğin şey yok zaten, 2 Çünkü onlarla aynı zamanda doğmuştun! 2 O kadar yaşlısın!'),
(1997207,68,18,38,22,'‹‹Karın ambarlarına girdin mi, 2 Dolunun ambarlarını gördün mü?'),
(1997208,68,18,38,23,'Ben onları sıkıntılı günler için, 2 Kavga ve savaş günleri için saklıyorum.'),
(1997209,68,18,38,24,'Nerede ışığın dağıtıldığı, 2 Doğu rüzgarının yeryüzüne saçıldığı yere giden yol?'),
(1997210,68,18,38,25,'Kim sellere kanal, 2 Yıldırımlara yol açtı;'),
(1997211,68,18,38,26,'Kimsenin yaşamadığı toprakları, 2 İnsanın bulunmadığı çölü sulasın diye;'),
(1997212,68,18,38,27,'Kurak ve ıssız yeri doyursun, 2 Ot bitirsin diye?'),
(1997213,68,18,38,28,'Yağmurun babası var mı? 2 Çiy damlalarını kim yarattı?'),
(1997214,68,18,38,29,'Buz kimin rahminden çıktı? 2 Göklerden düşen kırağıyı kim doğurdu,'),
(1997215,68,18,38,30,'Sular taş gibi katılaşıp 2 Enginin yüzü donunca?'),
(1997216,68,18,38,31,'‹‹Ülker yıldızlarını bağlayabilir misin? 2 Oryonun bağlarını çözebilir misin?'),
(1997217,68,18,38,32,'Mevsimlerinde çıkartabilir misin takımyıldızları? 2 Büyük ve Küçük Ayıya yol gösterebilir misin?'),
(1997218,68,18,38,33,'Biliyor musun göklerin yasalarını? 2 Tanrının yönetimini yeryüzünde kurabilir misin?'),
(1997219,68,18,38,34,'‹‹Başına bol yağmur yağsın diye 2 Bulutlara sesini duyurabilir misin?'),
(1997220,68,18,38,35,'Varıp da, ‹Buradayız› desinler diye, 2 Şimşekleri gönderebilir misin?'),
(1997221,68,18,38,36,'Kim mısırturnasına bilgelik, 2 Horoza anlayış verdi? sezdikleri sanılırdı. Bu iki sözcük ‹‹yüreğimiz›› ve ‹‹aklımız›› anlamına da gelebilir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997222,68,18,38,37,'Kimin bulutları sayacak bilgisi var? 2 Kim göklerin tulumlarını boşaltabilir,'),
(1997223,68,18,38,38,'Toprak sertleşip 2 Parçaları birbirine yapışınca?'),
(1997224,68,18,38,39,'‹‹Dişi aslanlar için sen avlanabilir misin, 2 Genç aslanların karnını doyurabilir misin,'),
(1997225,68,18,38,40,'İnlerine sindikleri, 2 Çalılıkta pusuya yattıkları zaman?'),
(1997226,68,18,38,41,'Kuzguna yiyeceğini kim sağlıyor, 2 Yavruları Tanrı''ya feryat edip 2 Açlıktan kıvrandığı zaman?'),
(1997227,68,18,39,1,'‹‹Dağ keçilerinin ne zaman doğurduğunu biliyor musun? 2 Geyiklerin yavruladığı zamanı sen mi gözlüyorsun?'),
(1997228,68,18,39,2,'Sen mi sayıyorsun doğuruncaya dek geçirdikleri ayları? 2 Doğurdukları zamanı biliyor musun?'),
(1997229,68,18,39,3,'Çöküp yavrularını doğurur, 2 Kurtulurlar sancılarından.'),
(1997230,68,18,39,4,'Güçlenir, kırda büyür yavrular, 2 Gider, bir daha dönmezler.'),
(1997231,68,18,39,5,'‹‹Kim yaban eşeğini başı boş gönderdi, 2 Kim bağlarını çözdü?'),
(1997232,68,18,39,6,'Yurt olarak ona bozkırı, 2 Barınak olarak tuzlayı verdim.'),
(1997233,68,18,39,7,'Kentteki kargaşaya güler o, 2 Sürücünün bağırdığını duymaz.'),
(1997234,68,18,39,8,'Otlamak için tepeleri dolaşır, 2 Yeşillik arar.'),
(1997235,68,18,39,9,'‹‹Yaban öküzü sana kulluk etmek ister mi? 2 Geceyi senin yemliğinin yanında geçirir mi?'),
(1997236,68,18,39,10,'Sabanla yarık açsın diye ona bağ vurabilir misin? 2 Arkanda, ovalarda tırmık çeker mi?'),
(1997237,68,18,39,11,'Çok güçlü diye ona bel bağlayabilir misin? 2 Ağır işini ona bırakabilir misin?'),
(1997238,68,18,39,12,'Ekinini getireceğine, 2 Buğdayını harman yerinde toplayacağına güvenir misin?'),
(1997239,68,18,39,13,'‹‹Devekuşunun kanatları sevinçle dalgalanır, 2 Ama leyleğin kanatları ve tüyleriyle kıyaslanamaz.'),
(1997240,68,18,39,14,'Devekuşu yumurtalarını yere bırakır, 2 Onları kumda ısıtır,'),
(1997241,68,18,39,15,'Ayak altında ezilebileceklerini, 2 Yabanıl hayvanlarca çiğnenebileceklerini düşünmez.'),
(1997242,68,18,39,16,'Yavrularına sert davranır, kendinin değilmiş gibi, 2 Çektiği zahmetin boşa gideceğine üzülmez.'),
(1997243,68,18,39,17,'Çünkü Tanrı ona bilgelik bağışlamamış, 2 Anlayıştan pay vermemiştir.'),
(1997244,68,18,39,18,'Yine de koşmak için kabarınca 2 Ata ve binicisine güler.'),
(1997245,68,18,39,19,'‹‹Sen mi ata güç verdin, 2 Dalgalanan yeleyi boynuna giydirdin?'),
(1997246,68,18,39,20,'Sen misin onu çekirge gibi sıçratan, 2 Gururlu kişnemesiyle korku saçtıran?'),
(1997247,68,18,39,21,'Ayakları toprağı şiddetle eşer, 2 Gücünden ötürü sevinçle coşar, 2 Savaşçının üstüne yürür.'),
(1997248,68,18,39,22,'Korkuya güler, hiçbir şeyden yılmaz, 2 Kılıç önünde geri adım atmaz.'),
(1997249,68,18,39,23,'Ok kılıfı, parıldayan mızrak ve pala 2 Üzerinde takırdar atın.'),
(1997250,68,18,39,24,'Coşku ve heyecanla uzaklıkları yutar, 2 Boru çalınca duramaz yerinde.'),
(1997251,68,18,39,25,'Boru çaldıkça, ‹Hi!› diye kişner, 2 Savaş kokusunu, komutanların gürleyen sesini, 2 Savaş çığlıklarını uzaklardan duyar.'),
(1997252,68,18,39,26,'‹‹Atmaca senin bilgeliğinle mi süzülüyor, 2 Kanatlarını güneye doğru açıyor?'),
(1997253,68,18,39,27,'Kartal senin buyruğunla mı yükseliyor, 2 Yuvasını yükseklere kuruyor?'),
(1997254,68,18,39,28,'Uçurum kenarlarında konaklıyor, 2 Sivri kayalar onun kalesi.'),
(1997255,68,18,39,29,'Oradan gözetliyor yiyeceğini, 2 Gözleri avını uzaktan seçiyor.'),
(1997256,68,18,39,30,'Onun yavruları kanla beslenir, 2 Leşler neredeyse, o da oradadır.››'),
(1997257,68,18,40,1,'RAB Eyüpe şöyle dedi:'),
(1997258,68,18,40,2,'‹‹Her Şeye Gücü Yetenle çatışan Onu yola getirebilir mi? 2 Tanrıyı suçlayan yanıtlasın.››'),
(1997259,68,18,40,3,'O zaman Eyüp RABbi şöyle yanıtladı:'),
(1997260,68,18,40,4,'‹‹Bak, ben değersiz biriyim, 2 Sana nasıl yanıt verebilirim? 2 Ağzımı elimle kapıyorum.'),
(1997261,68,18,40,5,'Bir kez konuştum, yanıt almadım, 2 İkinci kez konuşamam artık.››'),
(1997262,68,18,40,6,'RAB kasırganın içinden Eyüpü şöyle yanıtladı:'),
(1997263,68,18,40,7,'‹‹Şimdi erkek gibi kuşağını beline vur da, 2 Ben sorayım, sen anlat.'),
(1997264,68,18,40,8,'‹‹Adaletimi boşa mı çıkaracaksın? 2 Kendini haklı çıkarmak için beni mi suçlayacaksın?'),
(1997265,68,18,40,9,'Sende Tanrının bileği gibi bilek var mı? 2 Sesin Onunki gibi gürleyebilir mi?'),
(1997266,68,18,40,10,'Öyleyse şan ve şerefe bürün, 2 Görkem ve yücelik kuşan.'),
(1997267,68,18,40,11,'Gazabının ateşini saç, 2 Gururluya bakıp onu alçalt.'),
(1997268,68,18,40,12,'Gururluya bakıp onu çökert, 2 Kötüleri bulundukları yerde ez.'),
(1997269,68,18,40,13,'Hepsini birlikte toprağa göm, 2 Mezarda yüzlerini kefenle sar.'),
(1997270,68,18,40,14,'O zaman sağ kolunun seni kurtarabileceğini 2 Ben de kabul ederim.'),
(1997271,68,18,40,15,'‹‹Seninle birlikte yarattığım Behemota bak, 2 Sığır gibi ot yiyor. bilinmiyor. Su aygırı, fil, timsah ya da soyu tükenmiş bir hayvan olduğu sanılıyor.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997272,68,18,40,16,'Bak, ne güç var belinde, 2 Karnının kasları ne güçlü!'),
(1997273,68,18,40,17,'Kuyruğunu sedir ağacı gibi sallıyor, 2 Sımsıkıdır uyluk lifleri.'),
(1997274,68,18,40,18,'Kemikleri tunç borular, 2 Kaburgaları demir çubuklar gibidir.'),
(1997275,68,18,40,19,'Tanrının yapıtları arasında ilk sırayı alır, 2 Yalnız Yaratıcısı ona kılıçla yaklaşır.'),
(1997276,68,18,40,20,'Tepeler ürünlerini ona getirir, 2 Bütün yabanıl hayvanlar yanında oynaşır.'),
(1997277,68,18,40,21,'Hünnap çalıları altında, 2 Kamışlarla örtülü bir bataklıkta yatar.'),
(1997278,68,18,40,22,'Hünnaplar onu gölgelerinde saklar, 2 Vadideki kavaklar kuşatır.'),
(1997279,68,18,40,23,'Irmak coşsa bile o ürkmez, 2 Güvenlik içindedir, 2 Şeria Irmağı boğazına dayansa bile.'),
(1997280,68,18,40,24,'Gözleri açıkken kim onu tutabilir, 2 Kim kancayla burnunu delebilir?'),
(1997281,68,18,41,1,'‹‹Livyatanı çengelle çekebilir misin, 2 Dilini halatla bağlayabilir misin? olarak bilinmiyor. Timsah ya da soyu tükenmiş bir hayvan olduğu sanılıyor.'),
(1997282,68,18,41,2,'Burnuna sazdan ip takabilir misin, 2 Kancayla çenesini delebilir misin?'),
(1997283,68,18,41,3,'Yalvarıp yakarır mı sana, 2 Tatlı tatlı konuşur mu?'),
(1997284,68,18,41,4,'Seninle antlaşma yapar mı, 2 Onu ömür boyu köle edesin diye?'),
(1997285,68,18,41,5,'Kuşla oynar gibi onunla oynayabilir misin, 2 Hizmetçilerin eğlensin diye ona tasma takabilir misin?'),
(1997286,68,18,41,6,'Balıkçılar onun üzerine pazarlık eder mi? 2 Tüccarlar aralarında onu böler mi?'),
(1997287,68,18,41,7,'Derisini zıpkınlarla, 2 Başını mızraklarla doldurabilir misin?'),
(1997288,68,18,41,8,'Elini üzerine koy da, çıkacak çıngarı gör, 2 Bir daha yapmayacaksın bunu.'),
(1997289,68,18,41,9,'Onu yakalamak için umutlanma, 2 Görünüşü bile insanın ödünü patlatır.'),
(1997290,68,18,41,10,'Onu uyandıracak kadar yürekli adam yoktur. 2 Öyleyse benim karşımda kim durabilir?'),
(1997291,68,18,41,11,'Kim benden hesap vermemi isteyebilir? 2 Göklerin altında ne varsa bana aittir.'),
(1997292,68,18,41,12,'‹‹Onun kolları, bacakları, 2 Zorlu gücü, güzel yapısı hakkında 2 Konuşmadan edemeyeceğim.'),
(1997293,68,18,41,13,'Onun giysisinin önünü kim açabilir? 2 Kim onun iki katlı zırhını delebilir? (bkz. Septuaginta), Masoretik metin ‹‹Kim çift gem takmak için ona yaklaşabilir?››'),
(1997294,68,18,41,14,'Ağzının kapılarını açmaya kim yeltenebilir, 2 Dehşet verici dişleri karşısında?'),
(1997295,68,18,41,15,'Sımsıkı kenetlenmiştir 2 Sırtındakifö sıra sıra pullar, Masoretik metin ‹‹Gurur duyduğu››.'),
(1997296,68,18,41,16,'Öyle yakındır ki birbirine 2 Aralarından hava bile geçmez.'),
(1997297,68,18,41,17,'Birbirlerine geçmişler, 2 Yapışmış, ayrılmazlar.'),
(1997298,68,18,41,18,'Aksırması ışık saçar, 2 Gözleri şafak gibi parıldar.'),
(1997299,68,18,41,19,'Ağzından alevler fışkırır, 2 Kıvılcımlar saçılır.'),
(1997300,68,18,41,20,'Kaynayan kazandan, 2 Yanan sazdan çıkan duman gibi 2 Burnundan duman tüter.'),
(1997301,68,18,41,21,'Soluğu kömürleri tutuşturur, 2 Alev çıkar ağzından.'),
(1997302,68,18,41,22,'Boynu güçlüdür, 2 Dehşet önü sıra gider.'),
(1997303,68,18,41,23,'Etinin katmerleri birbirine yapışmış, 2 Sertleşmiş üzerinde, kımıldamazlar.'),
(1997304,68,18,41,24,'Göğsü taş gibi serttir, 2 Değirmenin alt taşı gibi sert.'),
(1997305,68,18,41,25,'Ayağa kalktı mı güçlüler dehşete düşer, 2 Çıkardığı gürültüden ödleri patlar.'),
(1997306,68,18,41,26,'Üzerine gidildi mi ne kılıç işler, 2 Ne mızrak, ne cirit, ne de kargı.'),
(1997307,68,18,41,27,'Demir saman gibi gelir ona, 2 Tunç çürük odun gibi.'),
(1997308,68,18,41,28,'Oklar onu kaçırmaz, 2 Anız gibi gelir ona sapan taşları.'),
(1997309,68,18,41,29,'Anız sayılır onun için topuzlar, 2 Vınlayan palaya güler.'),
(1997310,68,18,41,30,'Keskin çömlek parçaları gibidir karnının altı, 2 Döven gibi uzanır çamura.'),
(1997311,68,18,41,31,'Derin suları kaynayan kazan gibi fokurdatır, 2 Denizi merhem çömleği gibi karıştırır.'),
(1997312,68,18,41,32,'Ardında parlak bir iz bırakır, 2 İnsan enginin saçları ağarmış sanır.'),
(1997313,68,18,41,33,'Yeryüzünde bir eşi daha yoktur, 2 Korkusuz bir yaratıktır.'),
(1997314,68,18,41,34,'Kendini büyük gören her varlığı aşağılar, 2 Gururlu her varlığın kralı odur.››'),
(1997315,68,18,42,1,'O zaman Eyüp RABbi şöyle yanıtladı:'),
(1997316,68,18,42,2,'‹‹Senin her şeyi yapabileceğini biliyorum, 2 Hiçbir amacına engel olunmaz.'),
(1997317,68,18,42,3,'‹Tasarımı bilgisizce karartan bu adam kim?› diye sordun. 2 Kuşkusuz anlamadığım şeyleri konuştum, 2 Beni aşan, bilmediğim şaşılası işleri.'),
(1997318,68,18,42,4,'‹‹ ‹Dinle de konuşayım› dedin, 2 ‹Ben sorayım, sen anlat.›'),
(1997319,68,18,42,5,'Kulaktan duymaydı bildiklerim senin hakkında, 2 Şimdiyse gözlerimle gördüm seni.'),
(1997320,68,18,42,6,'Bu yüzden kendimi hor görüyor, 2 Toz ve kül içinde tövbe ediyorum.››'),
(1997321,68,18,42,7,'RAB Eyüple konuştuktan sonra, Temanlı Elifaza: ‹‹Sana ve iki dostuna karşı öfkem alevlendi›› dedi, ‹‹Çünkü kulum Eyüp gibi hakkımda doğruyu konuşmadınız.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997322,68,18,42,8,'Şimdi yedi boğa, yedi koç alıp kulum Eyüpün yanına gidin, kendiniz için yakmalık sunu sunun. Kulum Eyüp sizin için dua etsin. Çünkü onun duasını kabul eder, aptallığınızın karşılığını vermem. Kulum Eyüp gibi hakkımda doğruyu konuşmadınız.››'),
(1997323,68,18,42,9,'Temanlı Elifaz, Şuahlı Bildat, Naamalı Sofar gidip RABbin söylediğini yaptılar. RAB de Eyüpün duasını kabul etti.'),
(1997324,68,18,42,10,'Eyüp dostları için dua ettikten sonra, RAB onu eski gönencine kavuşturup ona önceki varlığının iki katını verdi.'),
(1997325,68,18,42,11,'Bütün erkek ve kız kardeşleri, eski tanıdıklarının hepsi Eyüpün yanına gelip evinde onunla birlikte yemek yediler. Acısını paylaşıp RABbin başına getirmiş olduğu felaketlerden ötürü onu avuttular. Her biri ona bir parça gümüş, bir de altın halka verdi.'),
(1997326,68,18,42,12,'RAB Eyüpün sonunu başından bereketli kıldı. On dört bin koyuna, altı bin deveye, bin çift öküze, bin eşeğe sahip oldu.'),
(1997327,68,18,42,13,'Yedi oğlu, üç kızı oldu.'),
(1997328,68,18,42,14,'İlk kızının adını Yemima, ikincisinin Kesia, üçüncüsünün Keren-Happuk koydu.'),
(1997329,68,18,42,15,'Ülkenin hiçbir yerinde Eyüpün kızları kadar güzel kızlar yoktu. Babaları, kardeşlerinin yanısıra onlara da miras verdi. ağırlığı ve değeri bilinmeyen bir para birimiydi.'),
(1997330,68,18,42,16,'Bundan sonra Eyüp yüz kırk yıl daha yaşadı, oğullarını, dört göbek torunlarını gördü.'),
(1997331,68,18,42,17,'Kocayıp yaşama doyarak öldü.'),
(1997332,68,19,1,1,'Ne mutlu o insana ki, kötülerin öğüdüyle yürümez, 2 Günahkârların yolunda durmaz, 2 Alaycıların arasında oturmaz.'),
(1997333,68,19,1,2,'Ancak zevkini RABbin Yasasından alır 2 Ve gece gündüz onun üzerinde derin derin düşünür.'),
(1997334,68,19,1,3,'Böylesi akarsu kıyılarına dikilmiş ağaca benzer, 2 Meyvesini mevsiminde verir, 2 Yaprağı hiç solmaz. 2 Yaptığı her işi başarır.'),
(1997335,68,19,1,4,'Kötüler böyle değil, 2 Rüzgarın savurduğu saman çöpüne benzerler.'),
(1997336,68,19,1,5,'Bu yüzden yargılanınca aklanamaz, 2 Doğrular topluluğunda yer bulamaz günahkârlar.'),
(1997337,68,19,1,6,'Çünkü RAB doğruların yolunu gözetir, 2 Kötülerin yolu ise ölüme götürür.'),
(1997338,68,19,2,1,'Nedir uluslar arasındaki bu kargaşa, 2 Neden boş düzenler kurar bu halklar?'),
(1997339,68,19,2,2,'Dünyanın kralları saf bağlıyor, 2 Hükümdarlar birleşiyor 2 RABbe ve meshettiği krala karşı.'),
(1997340,68,19,2,3,'‹‹Koparalım onların kayışlarını›› diyorlar, 2 ‹‹Atalım üzerimizden bağlarını.››'),
(1997341,68,19,2,4,'Göklerde oturan Rab gülüyor, 2 Onlarla eğleniyor.'),
(1997342,68,19,2,5,'Sonra öfkeyle uyarıyor onları, 2 Gazabıyla dehşete düşürüyor'),
(1997343,68,19,2,6,'Ve, ‹‹Ben kralımı 2 Kutsal dağım Siyona oturttum›› diyor.'),
(1997344,68,19,2,7,'RABbin bildirisini ilan edeceğim: 2 Bana, ‹‹Sen benim oğlumsun›› dedi, 2 ‹‹Bugün ben sana baba oldum.'),
(1997345,68,19,2,8,'Dile benden, miras olarak sana ulusları, 2 Mülk olarak yeryüzünün dört bucağını vereyim.'),
(1997346,68,19,2,9,'Demir çomakla kıracaksın onları, 2 Çömlek gibi parçalayacaksın.›› ‹‹Güdeceksin››.'),
(1997347,68,19,2,10,'Ey krallar, akıllı olun! 2 Ey dünya önderleri, ders alın!'),
(1997348,68,19,2,11,'RABbe korkuyla hizmet edin, 2 Titreyerek sevinin.'),
(1997349,68,19,2,12,'Oğulu öpün ki öfkelenmesin, 2 Yoksa izlediğiniz yolda mahvolursunuz. 2 Çünkü öfkesi bir anda alevleniverir. 2 Ne mutlu O''na sığınanlara!'),
(1997350,68,19,3,1,'Ya RAB, düşmanlarım ne kadar çoğaldı, 2 Hele bana karşı ayaklananlar!'),
(1997351,68,19,3,2,'Birçoğu benim için: 2 ‹‹Tanrı katında ona kurtuluş yok!›› diyor. |iSela sanılıyor.'),
(1997352,68,19,3,3,'Ama sen, ya RAB, çevremde kalkansın, 2 Onurum, başımı yukarı kaldıran sensin.'),
(1997353,68,19,3,4,'RABbe seslenirim, 2 Yanıtlar beni kutsal dağından. |iSela'),
(1997354,68,19,3,5,'Yatar uyurum, 2 Uyanır kalkarım, RAB destektir bana.'),
(1997355,68,19,3,6,'Korkum yok 2 Çevremi saran binlerce düşmandan.'),
(1997356,68,19,3,7,'Ya RAB, kalk, ey Tanrım, kurtar beni! 2 Vur bütün düşmanlarımın çenesine, 2 Kır kötülerin dişlerini.'),
(1997357,68,19,3,8,'Kurtuluş RAB''dedir, 2 Halkının üzerinde olsun bereketin! |iSela'),
(1997358,68,19,4,1,'Sana seslenince yanıtla beni, 2 Ey adil Tanrım! 2 Ferahlat beni sıkıntıya düştüğümde, 2 Lütfet bana, kulak ver duama.'),
(1997359,68,19,4,2,'Ey insanlar, ne zamana dek 2 Onurumu utanca çevireceksiniz? 2 Ne zamana dek boş şeylere gönül verecek, 2 Yalan peşinde koşacaksınız? |iSela'),
(1997360,68,19,4,3,'Bilin ki, RAB sadık kulunu kendine ayırmıştır, 2 Ne zaman seslensem, duyar beni.'),
(1997361,68,19,4,4,'Öfkelenebilirsiniz, ama günah işlemeyin; 2 İyi düşünün yatağınızda, susun. |iSela'),
(1997362,68,19,4,5,'Doğruluk kurbanları sunun RABbe, 2 Ona güvenin.'),
(1997363,68,19,4,6,'‹‹Kim bize iyilik yapacak?›› diyen çok. 2 Ya RAB, yüzünün ışığıyla bizi aydınlat!'),
(1997364,68,19,4,7,'Öyle bir sevinç verdin ki bana, 2 Onların bol tahıl ve yeni şaraptan aldığı sevinçten fazla.'),
(1997365,68,19,4,8,'Esenlik içinde yatar uyurum, 2 Çünkü yalnız sen, ya RAB, 2 Güvenlik içinde tutarsın beni.'),
(1997366,68,19,5,1,'Sözlerime kulak ver, ya RAB, 2 İniltilerimi işit.'),
(1997367,68,19,5,2,'Feryadımı dinle, ey Kralım ve Tanrım! 2 Duam sanadır.'),
(1997368,68,19,5,3,'Sabah sesimi duyarsın, ya RAB, 2 Her sabah sana duamı sunar, umutla beklerim.'),
(1997369,68,19,5,4,'Çünkü sen kötülükten hoşlanan Tanrı değilsin, 2 Kötülük senin yanında barınmaz.'),
(1997370,68,19,5,5,'Böbürlenenler önünde duramaz, 2 Bütün suç işleyenlerden nefret duyar,'),
(1997371,68,19,5,6,'Yalan söyleyenleri yok edersin; 2 Ya RAB, sen eli kanlılardan, 2 Aldatıcılardan tiksinirsin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997372,68,19,5,7,'Bense bol sevgin sayesinde 2 Kutsal tapınağına gireceğim; 2 Oraya doğru saygıyla eğileceğim.'),
(1997373,68,19,5,8,'Yol göster bana doğruluğunla, ya RAB, 2 Düşmanlarıma karşı! 2 Yolunu önümde düzle.'),
(1997374,68,19,5,9,'Çünkü onların sözüne güvenilmez, 2 Yürekleri yıkım dolu. 2 Ağızları açık birer mezardır, 2 Yaltaklanır dururlar.'),
(1997375,68,19,5,10,'Ey Tanrı, onları suçlu çıkar! 2 Kurdukları düzen yıkımlarına yol açsın. 2 Kov onları sayısız isyanları yüzünden. 2 Çünkü sana karşı ayaklandılar.'),
(1997376,68,19,5,11,'Sevinsin sana sığınan herkes, 2 Sevinç çığlıkları atsın sürekli, 2 Kanat ger üzerlerine; 2 Sevinçle coşsun adını sevenler sende.'),
(1997377,68,19,5,12,'Çünkü sen doğru kişiyi kutsarsın, ya RAB, 2 Çevresini kalkan gibi lütfunla sararsın.'),
(1997378,68,19,6,1,'Ya RAB, öfkeyle azarlama beni, 2 Gazapla yola getirme. kesin olarak bilinmiyor.'),
(1997379,68,19,6,2,'Lütfet bana, ya RAB, bitkinim; 2 Şifa ver bana, ya RAB, kemiklerim sızlıyor,'),
(1997380,68,19,6,3,'Çok acı çekiyorum. 2 Ah, ya RAB! 2 Ne zamana dek sürecek bu?'),
(1997381,68,19,6,4,'Gel, ya RAB, kurtar beni, 2 Yardım et sevginden dolayı.'),
(1997382,68,19,6,5,'Çünkü ölüler arasında kimse seni anmaz, 2 Kim şükür sunar sana ölüler diyarından?'),
(1997383,68,19,6,6,'İnleye inleye bittim, 2 Döşeğim su içinde bütün gece ağlamaktan, 2 Yatağım sırılsıklam gözyaşlarımdan.'),
(1997384,68,19,6,7,'Kederden gözlerimin feri sönüyor, 2 Zayıflıyor gözlerim düşmanlarım yüzünden.'),
(1997385,68,19,6,8,'Ey kötülük yapanlar, 2 Uzak durun benden, 2 Çünkü RAB ağlayışımı işitti.'),
(1997386,68,19,6,9,'Yalvarışımı duydu, 2 Duamı kabul etti.'),
(1997387,68,19,6,10,'Bütün düşmanlarım utanacak, 2 Hepsini dehşet saracak, 2 Ansızın geri dönecekler utanç içinde.'),
(1997388,68,19,7,1,'Sana sığınıyorum, ya RAB Tanrım! 2 Peşime düşenlerden kurtar beni, 2 Özgür kıl.'),
(1997389,68,19,7,2,'Yoksa aslan gibi parçalayacaklar beni, 2 Kurtaracak biri yok diye, 2 Lime lime edecekler etimi.'),
(1997390,68,19,7,3,'Ya RAB Tanrım, eğer şunu yaptıysam: 2 Birine haksızlık ettiysem,'),
(1997391,68,19,7,4,'Dostuma ihanet ettiysem, 2 Düşmanımı nedensiz soyduysam,'),
(1997392,68,19,7,5,'Ardıma düşsün düşman, 2 Yakalasın beni, 2 Canımı yerde çiğnesin, 2 Ayak altına alsın onurumu. |iSela'),
(1997393,68,19,7,6,'Öfkeyle kalk, ya RAB! 2 Düşmanlarımın gazabına karşı çık! 2 Benim için uyan! 2 Buyur, adalet olsun.'),
(1997394,68,19,7,7,'Uluslar topluluğu çevreni sarsın, 2 Onları yüce katından yönet.'),
(1997395,68,19,7,8,'RAB halkları yargılar; 2 Beni de yargıla, ya RAB, 2 Doğruluğuma, dürüstlüğüme göre.'),
(1997396,68,19,7,9,'Ey adil Tanrım! 2 Kötülerin kötülüğü son bulsun, 2 Doğrular güvene kavuşsun, 2 Sen ki akılları, gönülleri sınarsın.'),
(1997397,68,19,7,10,'Tanrı kalkan gibi yanıbaşımda, 2 Temiz yüreklileri O kurtarır.'),
(1997398,68,19,7,11,'Tanrı adil bir yargıçtır, 2 Öyle bir Tanrı ki, her gün öfke saçar.'),
(1997399,68,19,7,12,'Kötüler yola gelmezse, 2 Tanrı kılıcını biler, 2 Yayını gerip hedefine kurar.'),
(1997400,68,19,7,13,'Hazır bekler ölümcül silahları, 2 Alevli okları.'),
(1997401,68,19,7,14,'İşte kötü insan kötülük sancıları çekiyor, 2 Fesada gebe kalmış, 2 Yalan doğuruyor.'),
(1997402,68,19,7,15,'Bir kuyu açıp kazıyor, 2 Kazdığı kuyuya kendisi düşüyor.'),
(1997403,68,19,7,16,'Kötülüğü kendi başına gelecek, 2 Zorbalığı kendi tepesine inecek.'),
(1997404,68,19,7,17,'Şükredeyim doğruluğu için RAB''be, 2 Yüce RAB''bin adını ilahilerle öveyim.'),
(1997405,68,19,8,1,'Ey Egemenimiz RAB, 2 Ne yüce adın var yeryüzünün tümünde! 2 Gökyüzünü görkeminle kapladın. okunan bir ilahi olabilir.'),
(1997406,68,19,8,2,'Çocukların, hatta emziktekilerin sesiyle 2 Set çektin hasımlarına, 2 Düşmanı, öç alanı yok etmek için.'),
(1997407,68,19,8,3,'Seyrederken ellerinin eseri olan gökleri, 2 Oraya koyduğun ayı ve yıldızları,'),
(1997408,68,19,8,4,'Soruyorum kendi kendime: 2 ‹‹İnsan ne ki, onu anasın, 2 Ya da insanoğlu ne ki, ona ilgi gösteresin?››'),
(1997409,68,19,8,5,'Nerdeyse bir tanrı yaptın onu, 2 Başına yücelik ve onur tacını koydun. (tanrılardan) pek aşağı yaratmadın›› (bkz. Yar.1:26-28; İbr.2:6-8).'),
(1997410,68,19,8,6,'Ellerinin yapıtları üzerine onu egemen kıldın, 2 Her şeyi ayaklarının altına serdin;'),
(1997411,68,19,8,7,'Davarları, sığırları, 2 Yabanıl hayvanları,'),
(1997412,68,19,8,8,'Gökteki kuşları, denizdeki balıkları, 2 Denizde kıpırdaşan bütün canlıları.'),
(1997413,68,19,8,9,'Ey Egemenimiz RAB, 2 Ne yüce adın var yeryüzünün tümünde!'),
(1997414,68,19,9,1,'Ya RAB, bütün yüreğimle sana şükredeceğim, 2 Yaptığın harikaların hepsini anlatacağım. yazılır.'),
(1997415,68,19,9,2,'Sende sevinç bulacak, coşacağım, 2 Adını ilahilerle öveceğim, ey Yüceler Yücesi!'),
(1997416,68,19,9,3,'Düşmanlarım geri çekilirken, 2 Sendeleyip ölüyorlar senin önünde.'),
(1997417,68,19,9,4,'Çünkü hakkımı, davamı sen savundun, 2 Adil yargıç olarak tahta oturdun.'),
(1997418,68,19,9,5,'Ulusları azarladın, kötüleri yok ettin, 2 Sonsuza dek adlarını sildin.'),
(1997419,68,19,9,6,'Yok olup gitti düşmanlar sonsuza dek, 2 Kökünden söktün kentlerini, 2 Anıları bile silinip gitti.'),
(1997420,68,19,9,7,'Oysa RAB sonsuza dek egemenlik sürer, 2 Yargı için kurmuştur tahtını;'),
(1997421,68,19,9,8,'O yönetir doğrulukla dünyayı, 2 O yargılar adaletle halkları.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997422,68,19,9,9,'RAB ezilenler için bir sığınak, 2 Sıkıntılı günlerde bir kaledir.'),
(1997423,68,19,9,10,'Seni tanıyanlar sana güvenir, 2 Çünkü sana yönelenleri hiç terk etmedin, ya RAB.'),
(1997424,68,19,9,11,'Siyonda oturan RABbi ilahilerle övün! 2 Yaptıklarını halklar arasında duyurun!'),
(1997425,68,19,9,12,'Çünkü dökülen kanın hesabını soran anımsar, 2 Ezilenlerin feryadını unutmaz.'),
(1997426,68,19,9,13,'Acı bana, ya RAB! 2 Ey beni ölümün eşiğinden kurtaran, 2 Benden nefret edenler yüzünden çektiğim sıkıntıya bak!'),
(1997427,68,19,9,14,'Öyle ki, övgüye değer işlerini anlatayım, 2 Siyon Kentinin kapılarında 2 Sağladığın kurtuluşla sevineyim.'),
(1997428,68,19,9,15,'Uluslar kendi kazdıkları kuyuya düştü, 2 Ayakları gizledikleri ağa takıldı.'),
(1997429,68,19,9,16,'Adil yargılarıyla RAB kendini gösterdi, 2 Kötüler kendi kurdukları tuzağa düştü. |iHigayon |isela terimi.'),
(1997430,68,19,9,17,'Kötüler ölüler diyarına gidecek, 2 Tanrıyı unutan bütün uluslar...'),
(1997431,68,19,9,18,'Ama yoksul büsbütün unutulmayacak, 2 Mazlumun umudu sonsuza dek kırılmayacak.'),
(1997432,68,19,9,19,'Kalk, ya RAB! İnsan galip çıkmasın, 2 Huzurunda yargılansın uluslar!'),
(1997433,68,19,9,20,'Onlara dehşet saç, ya RAB! 2 Sadece insan olduklarını bilsin uluslar. |iSela'),
(1997434,68,19,10,1,'Ya RAB, neden uzak duruyorsun, 2 Sıkıntılı günlerde kendini gizliyorsun?'),
(1997435,68,19,10,2,'Kötüler gururla mazlumları avlıyor, 2 Mazlumlar kötülerin kurduğu tuzağa düşüyor.'),
(1997436,68,19,10,3,'Kötü insan içindeki isteklerle övünür, 2 Açgözlü insan RABbe lanet okur, Onu hor görür.'),
(1997437,68,19,10,4,'Kendini beğenmiş kötü insan Tanrıya yönelmez, 2 Hep, ‹‹Tanrı yok!›› diye düşünür.'),
(1997438,68,19,10,5,'Kötülerin yolları her zaman başarıya götürür. 2 Öyle yücedir ki senin yargıların, 2 Kötüler anlayamaz, düşmanına burun kıvırır.'),
(1997439,68,19,10,6,'İçinden, ‹‹Ben sarsılmam›› der, 2 ‹‹Hiçbir zaman sıkıntıya düşmem.››'),
(1997440,68,19,10,7,'Ağzı lanet, hile ve zulüm dolu, 2 Dilinin altında kötülük ve fesat saklı.'),
(1997441,68,19,10,8,'Köylerin çevresinde pusu kurar, 2 Masumu gizli yerlerde öldürür, 2 Çaresizi sinsice gözler.'),
(1997442,68,19,10,9,'Gizli yerlerde pusuya yatar 2 Çalılıktaki aslan gibi, 2 Kapmak için mazlumu bekler 2 Ve ağına düşürüp yakalar.'),
(1997443,68,19,10,10,'Kurbanları çaresiz çöker, 2 Saldıranın üstün gücü altında ezilir.'),
(1997444,68,19,10,11,'Kötü insan içinden, ‹‹Tanrı unuttu›› der, 2 ‹‹Örttü yüzünü, asla göremez.››'),
(1997445,68,19,10,12,'Kalk, ya RAB, kaldır elini, ey Tanrı! 2 Mazlumları unutma!'),
(1997446,68,19,10,13,'Neden kötü insan seni hor görsün, 2 İçinden, ‹‹Tanrı hesap sormaz›› desin?'),
(1997447,68,19,10,14,'Oysa sen sıkıntı ve acı çekenleri görürsün, 2 Yardım etmek için onları izlersin; 2 Çaresizler sana dayanır, 2 Öksüzün yardımcısı sensin.'),
(1997448,68,19,10,15,'Kötünün, haksızın kolunu kır, 2 Sormadık hesap kalmasın yaptığı kötülükten.'),
(1997449,68,19,10,16,'RAB sonsuza dek kral kalacak, 2 Uluslar Onun ülkesinden temizlenecek.'),
(1997450,68,19,10,17,'Mazlumların dileğini duyarsın, ya RAB, 2 Yüreklendirirsin onları, 2 Kulağın hep üzerlerinde;'),
(1997451,68,19,10,18,'Öksüze, düşküne hakkını vermek için, 2 Bir daha dehşet saçmasın ölümlü insan.'),
(1997452,68,19,11,1,'Ben RABbe sığınırım, 2 Nasıl dersiniz bana, 2 ‹‹Kuş gibi kaç dağlara.'),
(1997453,68,19,11,2,'Bak, kötüler yaylarını geriyor, 2 Temiz yürekli insanları 2 Karanlıkta vurmak için 2 Oklarını kirişine koyuyor.'),
(1997454,68,19,11,3,'Temeller yıkılırsa, 2 Ne yapabilir doğru insan?››'),
(1997455,68,19,11,4,'RAB kutsal tapınağındadır, 2 Onun tahtı göklerdedir, 2 Bütün insanları görür, 2 Herkesi sınar.'),
(1997456,68,19,11,5,'RAB doğru insanı sınar, 2 Kötüden, zorbalığı sevenden tiksinir.'),
(1997457,68,19,11,6,'Kötülerin üzerine kızgın korlar ve kükürt yağdıracak, 2 Paylarına düşen kâse kavurucu rüzgar olacak.'),
(1997458,68,19,11,7,'Çünkü RAB doğrudur, doğruları sever; 2 Dürüst insanlar O''nun yüzünü görecek. kesin olarak bilinmiyor.'),
(1997459,68,19,12,1,'Kurtar beni, ya RAB, sadık kulun kalmadı, 2 Güvenilir insanlar yok oldu.'),
(1997460,68,19,12,2,'Herkes birbirine yalan söylüyor, 2 Dalkavukluk, ikiyüzlülük ediyor.'),
(1997461,68,19,12,3,'Sustursun RAB dalkavukların ağzını, 2 Büyüklenen dilleri.'),
(1997462,68,19,12,4,'Onlar ki, ‹‹Dilimizle kazanırız, 2 Dudaklarımız emrimizde, 2 Kim bize efendilik edebilir?›› derler.'),
(1997463,68,19,12,5,'‹‹Şimdi kalkacağım›› diyor RAB, 2 ‹‹Çünkü mazlumlar eziliyor, 2 Yoksullar inliyor, 2 Özledikleri kurtuluşu vereceğim onlara.››'),
(1997464,68,19,12,6,'RABbin sözleri pak sözlerdir; 2 Toprak ocakta eritilmiş, 2 Yedi kez arıtılmış gümüşe benzer.'),
(1997465,68,19,12,7,'Sen onları koru, ya RAB, 2 Bu kötü kuşaktan hep uzak tut!'),
(1997466,68,19,12,8,'İnsanlar arasında alçaklık rağbet görünce, 2 Kötüler her yanda dolaşır oldu.'),
(1997467,68,19,13,1,'Ne zamana dek, ya RAB, 2 Sonsuza dek mi beni unutacaksın? 2 Ne zamana dek yüzünü benden gizleyeceksin?'),
(1997468,68,19,13,2,'Ne zamana dek içimde tasa, 2 Yüreğimde hep keder olacak? 2 Ne zamana dek düşmanım bana üstün çıkacak?'),
(1997469,68,19,13,3,'Gör halimi, ya RAB, yanıtla Tanrım, 2 Gözlerimi aç, ölüm uykusuna dalmayayım.'),
(1997470,68,19,13,4,'Düşmanlarım, ‹‹Onu yendik!›› demesin, 2 Sarsıldığımda hasımlarım sevinmesin.'),
(1997471,68,19,13,5,'Ben senin sevgine güveniyorum, 2 Yüreğim kurtarışınla coşsun.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997472,68,19,13,6,'Ezgiler söyleyeceğim sana, ya RAB, 2 Çünkü iyilik ettin bana.'),
(1997473,68,19,14,1,'Akılsız içinden, ‹‹Tanrı yok!›› der. 2 İnsanlar bozuldu, iğrençlik aldı yürüdü, 2 İyilik eden yok.'),
(1997474,68,19,14,2,'RAB göklerden bakar oldu insanlara, 2 Akıllı, Tanrıyı arayan biri var mı diye.'),
(1997475,68,19,14,3,'Hepsi saptı, 2 Tümü yozlaştı, 2 İyilik eden yok, 2 Bir kişi bile!'),
(1997476,68,19,14,4,'Suç işleyenlerin hiçbiri görmüyor mu? 2 Halkımı ekmek yer gibi yiyor, 2 RABbe yakarmıyorlar.'),
(1997477,68,19,14,5,'Dehşete düşecekler yeryüzünde, 2 Çünkü Tanrı doğruların yanındadır.'),
(1997478,68,19,14,6,'Mazlumun tasarılarını boşa çıkarırdınız, 2 Ama RAB onun sığınağıdır.'),
(1997479,68,19,14,7,'Keşke İsrail''in kurtuluşu Siyon''dan gelse! 2 RAB halkını eski gönencine kavuşturunca, 2 Yakup soyu sevinecek, İsrail halkı coşacak.'),
(1997480,68,19,15,1,'Ya RAB, çadırına kim konuk olabilir? 2 Kutsal dağında kim oturabilir?'),
(1997481,68,19,15,2,'Kusursuz yaşam süren, adil davranan, 2 Yürekten gerçeği söyleyen.'),
(1997482,68,19,15,3,'İftira etmez, 2 Dostuna zarar vermez, 2 Komşusuna kara çalmaz böylesi.'),
(1997483,68,19,15,4,'Aşağılık insanları hor görür, 2 Ama RABden korkanlara saygı duyar. 2 Kendi zararına ant içse bile, dönmez andından.'),
(1997484,68,19,15,5,'Parasını faize vermez, 2 Suçsuza karşı rüşvet almaz. 2 Böyle yaşayan asla sarsılmayacak.'),
(1997485,68,19,16,1,'Koru beni, ey Tanrı, 2 Çünkü sana sığınıyorum.'),
(1997486,68,19,16,2,'RABbe dedim ki, ‹‹Efendim sensin. 2 Senden öte mutluluk yok benim için.››'),
(1997487,68,19,16,3,'Ülkedeki kutsallara gelince, 2 Soyludur onlar, biricik zevkim onlardır.'),
(1997488,68,19,16,4,'Başka ilahların ardınca koşanların derdi artacak. 2 Onların kan sunularını dökmeyeceğim, 2 Adlarını ağzıma almayacağım.'),
(1997489,68,19,16,5,'Benim payıma, 2 Benim kâseme düşen sensin, ya RAB; 2 Yaşamım senin ellerinde.'),
(1997490,68,19,16,6,'Payıma ne güzel yerler düştü, 2 Ne harika bir mirasım var!'),
(1997491,68,19,16,7,'Övgüler sunarım bana öğüt veren RABbe, 2 Geceleri bile vicdanım uyarır beni.'),
(1997492,68,19,16,8,'Gözümü RABden ayırmam, 2 Sağımda durduğu için sarsılmam.'),
(1997493,68,19,16,9,'Bu nedenle içim sevinç dolu, yüreğim coşuyor, 2 Bedenim güven içinde.'),
(1997494,68,19,16,10,'Çünkü sen beni ölüler diyarına terk etmezsin, 2 Sadık kulunun çürümesine izin vermezsin. kulunun ölüm çukurunu görmesine izin vermezsin.››'),
(1997495,68,19,16,11,'Yaşam yolunu bana bildirirsin. 2 Bol sevinç vardır senin huzurunda, 2 Sağ elinden mutluluk eksilmez.'),
(1997496,68,19,17,1,'Haklı davamı dinle, ya RAB, 2 Feryadımı işit! 2 Hilesiz dudaklardan çıkan duama kulak ver!'),
(1997497,68,19,17,2,'Haklı çıkar beni, 2 Çünkü sen gerçeği görürsün.'),
(1997498,68,19,17,3,'Yüreğimi yokladın, 2 Gece denedin, 2 Sınadın beni, 2 Kötü bir şey bulmadın; 2 Kararlıyım, ağzımdan kötü söz çıkmaz,'),
(1997499,68,19,17,4,'Başkalarının yaptıklarına gelince, 2 Ben senin sözlerine uyarak 2 Şiddet yollarından kaçındım.'),
(1997500,68,19,17,5,'Sıkı adımlarla senin yollarını tuttum, 2 Kaymadı ayaklarım.'),
(1997501,68,19,17,6,'Sana yakarıyorum, ey Tanrı, 2 Çünkü beni yanıtlarsın; 2 Kulak ver bana, dinle söylediklerimi!'),
(1997502,68,19,17,7,'Göster harika sevgini, 2 Ey sana sığınanları saldırganlardan sağ eliyle kurtaran!'),
(1997503,68,19,17,8,'Koru beni gözbebeği gibi; 2 Kanatlarının gölgesine gizle'),
(1997504,68,19,17,9,'Kötülerin saldırısından, 2 Çevremi saran ölümcül düşmanlarımdan.'),
(1997505,68,19,17,10,'Yürekleri yağ bağlamış, 2 Ağızları büyük laflar ediyor.'),
(1997506,68,19,17,11,'İzimi buldular, üzerime geliyorlar, 2 Yere vurmak için gözetliyorlar.'),
(1997507,68,19,17,12,'Tıpkı parçalamak için sabırsızlanan bir aslan, 2 Pusuya yatan genç bir aslan gibi.'),
(1997508,68,19,17,13,'Kalk, ya RAB, kes önlerini, eğ başlarını! 2 Kılıcınla kurtar canımı kötülerden,'),
(1997509,68,19,17,14,'Elinle bu insanlardan, ya RAB, 2 Yaşam payı bu dünyada olan insanlardan. 2 Varsın karınları vereceğin cezalara doysun, 2 Çocukları da yiyip doysun, 2 Artanı torunlarına kalsın!'),
(1997510,68,19,17,15,'Ama ben doğruluk sayesinde yüzünü göreceğim senin, 2 Uyanınca suretini görmeye doyacağım.'),
(1997511,68,19,18,1,'Seni seviyorum, gücüm sensin, ya RAB!'),
(1997512,68,19,18,2,'RAB benim kayam, sığınağım, kurtarıcımdır, 2 Tanrım, kayam, sığınacak yerimdir, 2 Kalkanım, güçlü kurtarıcım, korunağımdır!'),
(1997513,68,19,18,3,'Övgüye değer RABbe seslenir, 2 Kurtulurum düşmanlarımdan.'),
(1997514,68,19,18,4,'Ölüm iplerine dolanmıştım, 2 Yıkım selleri basmıştı beni,'),
(1997515,68,19,18,5,'Ölüler diyarının bağları sarmıştı, 2 Ölüm tuzakları çıkmıştı karşıma.'),
(1997516,68,19,18,6,'Sıkıntı içinde RABbe yakardım, 2 Yardıma çağırdım Tanrımı. 2 Tapınağından sesimi duydu, 2 Haykırışım kulaklarına ulaştı.'),
(1997517,68,19,18,7,'O zaman yeryüzü sarsılıp sallandı, 2 Titreyip sarsıldı dağların temelleri, 2 Çünkü RAB öfkelenmişti.'),
(1997518,68,19,18,8,'Burnundan duman yükseldi, 2 Ağzından kavurucu ateş 2 Ve korlar fışkırdı.'),
(1997519,68,19,18,9,'Kara buluta basarak 2 Gökleri yarıp indi.'),
(1997520,68,19,18,10,'Bir Keruva binip uçtu, 2 Rüzgar kanatlar takarak hızla geldi.'),
(1997521,68,19,18,11,'Karanlığı örtündü, 2 Kara bulutları kendine çardak yaptı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997522,68,19,18,12,'Varlığının parıltısından, 2 Bulutlardan dolu ve korlar savruluyordu.'),
(1997523,68,19,18,13,'RAB göklerden gürledi, 2 Duyurdu sesini Yüceler Yücesi, 2 Dolu ve alevli korlarla.'),
(1997524,68,19,18,14,'Savurup oklarını düşmanlarını dağıttı, 2 Şimşek çaktırarak onları şaşkına çevirdi.'),
(1997525,68,19,18,15,'Denizin dibi göründü, 2 Yeryüzünün temelleri açığa çıktı, ya RAB, 2 Senin azarlamandan, 2 Burnundan çıkan güçlü soluktan.'),
(1997526,68,19,18,16,'RAB yukarıdan elini uzatıp tuttu, 2 Çıkardı beni derin sulardan.'),
(1997527,68,19,18,17,'Beni zorlu düşmanımdan, 2 Benden nefret edenlerden kurtardı, 2 Çünkü onlar benden güçlüydü.'),
(1997528,68,19,18,18,'Felaket günümde karşıma dikildiler, 2 Ama RAB bana destek oldu.'),
(1997529,68,19,18,19,'Beni huzura kavuşturdu, 2 Kurtardı, çünkü benden hoşnut kaldı.'),
(1997530,68,19,18,20,'RAB doğruluğumun karşılığını verdi, 2 Beni temiz ellerime göre ödüllendirdi.'),
(1997531,68,19,18,21,'Çünkü RABbin yolunda yürüdüm, 2 Tanrımdan uzaklaşarak kötülük yapmadım.'),
(1997532,68,19,18,22,'Onun bütün ilkelerini göz önünde tuttum, 2 Kurallarından ayrılmadım.'),
(1997533,68,19,18,23,'Onun gözünde kusursuzdum, 2 Suç işlemekten sakındım.'),
(1997534,68,19,18,24,'Bu yüzden RAB beni doğruluğuma 2 Ve gözünde pak olan ellerime göre ödüllendirdi.'),
(1997535,68,19,18,25,'Sadık kuluna sadakat gösterir, 2 Kusursuz olana kusursuz davranırsın.'),
(1997536,68,19,18,26,'Pak olanla pak olur, 2 Eğriye eğri davranırsın.'),
(1997537,68,19,18,27,'Alçakgönüllüleri kurtarır, 2 Gururluların başını eğersin.'),
(1997538,68,19,18,28,'Işığımın kaynağı sensin, ya RAB, Tanrım! 2 Karanlığımı aydınlatırsın.'),
(1997539,68,19,18,29,'Desteğinle akıncılara saldırır, 2 Seninle surları aşarım, Tanrım.'),
(1997540,68,19,18,30,'Tanrının yolu kusursuzdur, 2 RABbin sözü arıdır. 2 O kendisine sığınan herkesin kalkanıdır.'),
(1997541,68,19,18,31,'Var mı RABden başka tanrı? 2 Tanrımızdan başka kaya var mı?'),
(1997542,68,19,18,32,'Tanrı beni güçle donatır, 2 Yolumu kusursuz kılar.'),
(1997543,68,19,18,33,'Ayaklar verdi bana, geyiklerinki gibi, 2 Doruklarda tutar beni.'),
(1997544,68,19,18,34,'Bana savaşmayı öğretti, 2 Kollarımla tunç bir yayı gereyim diye.'),
(1997545,68,19,18,35,'Bana zafer kalkanını bağışlarsın, 2 Sağ elin destekler, 2 Alçakgönüllülüğün yüceltir beni.'),
(1997546,68,19,18,36,'Bastığım yerleri genişletirsin, 2 Burkulmaz bileklerim.'),
(1997547,68,19,18,37,'Kovalayıp yetiştim düşmanlarıma, 2 Hepsi yok olmadan geri dönmedim.'),
(1997548,68,19,18,38,'Ezdim onları, kalkamaz oldular, 2 Ayaklarımın altına serildiler.'),
(1997549,68,19,18,39,'Savaş için beni güçle donattın, 2 Bana başkaldıranları önümde yere serdin.'),
(1997550,68,19,18,40,'Düşmanlarımı kaçmak zorunda bıraktın, 2 Benden nefret edenleri yok ettim.'),
(1997551,68,19,18,41,'Feryat ettiler, ama kurtaran çıkmadı; 2 RABbi çağırdılar, ama O yanıt vermedi.'),
(1997552,68,19,18,42,'Ezdim onları, rüzgarın savurduğu toza döndüler, 2 Sokak çamuru gibi savurup attım.'),
(1997553,68,19,18,43,'Halkımın çekişmelerinden beni kurtardın, 2 Ulusların önderi yaptın, 2 Tanımadığım halklar bana kulluk ediyor.'),
(1997554,68,19,18,44,'Duyar duymaz sözümü dinlediler, 2 Yabancılar bana yaltaklandılar.'),
(1997555,68,19,18,45,'Yabancıların betleri benizleri attı, 2 Titreyerek çıktılar kalelerinden.'),
(1997556,68,19,18,46,'RAB yaşıyor! Kayama övgüler olsun! 2 Yücelsin kurtarıcım Tanrı!'),
(1997557,68,19,18,47,'Odur öcümü alan, 2 Halkları bana bağımlı kılan.'),
(1997558,68,19,18,48,'Düşmanlarımdan kurtarır, 2 Başkaldıranlardan üstün kılar beni, 2 Zorbaların elinden alır.'),
(1997559,68,19,18,49,'Bunun için uluslar arasında sana şükredeceğim, ya RAB, 2 Adını ilahilerle öveceğim.'),
(1997560,68,19,18,50,'RAB kralını büyük zaferlere ulaştırır, 2 Meshettiği krala, Davut''a ve soyuna 2 Sonsuza dek sevgi gösterir.'),
(1997561,68,19,19,1,'Gökler Tanrının görkemini açıklamakta, 2 Gökkubbe ellerinin eserini duyurmakta.'),
(1997562,68,19,19,2,'Gün güne söz söyler, 2 Gece geceye bilgi verir.'),
(1997563,68,19,19,3,'Ne söz geçer orada, ne de konuşma, 2 Sesleri duyulmaz.'),
(1997564,68,19,19,4,'Ama sesleri yeryüzünü dolaşır, 2 Sözleri dünyanın dört bucağına ulaşır. Güneş için göklerde çadır kurdu Tanrı.'),
(1997565,68,19,19,5,'Gerdekten çıkan güveye benzer güneş, 2 Koşuya çıkacak atlet gibi sevinir.'),
(1997566,68,19,19,6,'Göğün bir ucundan çıkar, 2 Öbür ucuna döner, 2 Hiçbir şey gizlenmez sıcaklığından.'),
(1997567,68,19,19,7,'RABbin yasası yetkindir, cana can katar, 2 RABbin buyrukları güvenilirdir, 2 Saf adama bilgelik verir,'),
(1997568,68,19,19,8,'RABbin kuralları doğrudur, yüreği sevindirir, 2 RABbin buyrukları arıdır, gözleri aydınlatır.'),
(1997569,68,19,19,9,'RAB korkusu paktır, sonsuza dek kalır, 2 RABbin ilkeleri gerçek, tamamen adildir.'),
(1997570,68,19,19,10,'Onlara altından, bol miktarda saf altından çok istek duyulur, 2 Onlar baldan, süzme petek balından tatlıdır.'),
(1997571,68,19,19,11,'Uyarırlar kulunu, 2 Onlara uyanların ödülü büyüktür.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997572,68,19,19,12,'Kim yanlışlarını görebilir? 2 Bağışla göremediğim kusurlarımı,'),
(1997573,68,19,19,13,'Bilerek işlenen günahlardan koru kulunu, 2 İzin verme bana egemen olmalarına! 2 O zaman büyük isyandan uzak, 2 Kusursuz olurum.'),
(1997574,68,19,19,14,'Ağzımdan çıkan sözler, 2 Yüreğimdeki düşünceler, 2 Kabul görsün senin önünde, 2 Ya RAB, kayam, kurtarıcım benim! ‹‹Goel›› sözcüğü ‹‹Yakın akraba›› anlamına gelir (bkz. Rut 2:20).'),
(1997575,68,19,20,1,'Sıkıntılı gününde RAB seni yanıtlasın, 2 Yakupun Tanrısının adı seni korusun!'),
(1997576,68,19,20,2,'Yardım göndersin sana kutsal yerden, 2 Siyondan destek versin.'),
(1997577,68,19,20,3,'Bütün tahıl sunularını anımsasın, 2 Yakmalık sunularını kabul etsin! |iSela'),
(1997578,68,19,20,4,'Gönlünce versin sana, 2 Bütün tasarılarını gerçekleştirsin!'),
(1997579,68,19,20,5,'O zaman zaferini sevinç çığlıklarıyla kutlayacağız, 2 Tanrımızın adıyla sancaklarımızı dikeceğiz. 2 RAB senin bütün dileklerini yerine getirsin.'),
(1997580,68,19,20,6,'Şimdi anladım ki, RAB meshettiği kralı kurtarıyor, 2 Sağ elinin kurtarıcı gücüyle 2 Kutsal göklerinden ona yanıt veriyor.'),
(1997581,68,19,20,7,'Bazıları savaş arabalarına, 2 Bazıları atlarına güvenir, 2 Bizse Tanrımız RABbin adına güveniriz.'),
(1997582,68,19,20,8,'Onlar çöküyor, düşüyorlar; 2 Bizse kalkıyor, dimdik duruyoruz.'),
(1997583,68,19,20,9,'Ya RAB, kralı kurtar! 2 Yanıtla bizi sana yakardığımız gün!'),
(1997584,68,19,21,1,'Ya RAB, kral seviniyor gösterdiğin güce. 2 Sevinçten coşuyor verdiğin zaferle!'),
(1997585,68,19,21,2,'Gönlünün istediğini verdin, 2 Ağzından çıkan dileği geri çevirmedin. |iSela'),
(1997586,68,19,21,3,'Onu güzel armağanlarla karşıladın, 2 Başına saf altından taç koydun.'),
(1997587,68,19,21,4,'Senden yaşam istedi, verdin ona: 2 Uzun, sonsuz bir ömür.'),
(1997588,68,19,21,5,'Sağladığın zaferle büyük yüceliğe erişti, 2 Onu görkem ve büyüklükle donattın.'),
(1997589,68,19,21,6,'Üzerine sürekli bereket yağdırdın, 2 Varlığınla onu sevince boğdun.'),
(1997590,68,19,21,7,'Çünkü kral RABbe güvenir, 2 Yüceler Yücesinin sevgisi sayesinde sarsılmaz.'),
(1997591,68,19,21,8,'Elin bütün düşmanlarına erişecek, 2 Sağ elin senden nefret edenlere uzanacak.'),
(1997592,68,19,21,9,'Öfkelendiğin an, ya RAB, 2 Kızgın fırına döndüreceksin onları; 2 Gazapla yutacak, 2 Ateşle tüketeceksin.'),
(1997593,68,19,21,10,'Yok edeceksin çocuklarını yeryüzünden, 2 Soylarını insanlar arasından.'),
(1997594,68,19,21,11,'Düzenler kursalar sana, 2 Aldatmaya çalışsalar, 2 Yine de başarılı olamazlar.'),
(1997595,68,19,21,12,'Çünkü sırtlarını döndüreceksin, 2 Yayını yüzlerine doğru gerince.'),
(1997596,68,19,21,13,'Yüceliğini göster, ya RAB, gücünle! 2 Ezgiler söyleyip ilahilerle öveceğiz kudretini.'),
(1997597,68,19,22,1,'Tanrım, Tanrım, beni neden terk ettin? 2 Niçin bana yardım etmekten, 2 Haykırışıma kulak vermekten uzak duruyorsun?'),
(1997598,68,19,22,2,'Ey Tanrım, gündüz sesleniyorum, yanıt vermiyorsun, 2 Gece sesleniyorum, yine rahat yok bana.'),
(1997599,68,19,22,3,'Oysa sen kutsalsın, 2 İsrailin övgüleri üzerine taht kuran sensin.'),
(1997600,68,19,22,4,'Sana güvendiler atalarımız, 2 Sana dayandılar, onları kurtardın.'),
(1997601,68,19,22,5,'Sana yakarıp kurtuldular, 2 Sana güvendiler, aldanmadılar.'),
(1997602,68,19,22,6,'Ama ben insan değil, toprak kurduyum, 2 İnsanlar beni küçümsüyor, halk hor görüyor.'),
(1997603,68,19,22,7,'Beni gören herkes alay ediyor, 2 Sırıtıp baş sallayarak diyorlar ki,'),
(1997604,68,19,22,8,'‹‹Sırtını RABbe dayadı, kurtarsın bakalım onu, 2 Madem onu seviyor, yardım etsin!››'),
(1997605,68,19,22,9,'Oysa beni ana rahminden çıkaran, 2 Ana kucağındayken sana güvenmeyi öğreten sensin.'),
(1997606,68,19,22,10,'Doğuşumdan beri sana teslim edildim, 2 Ana rahminden beri Tanrım sensin.'),
(1997607,68,19,22,11,'Benden uzak durma! Çünkü sıkıntı yanıbaşımda, 2 Yardım edecek kimse yok.'),
(1997608,68,19,22,12,'Boğalar kuşatıyor beni, 2 Azgın Başan boğaları sarıyor çevremi.'),
(1997609,68,19,22,13,'Kükreyerek avını parçalayan aslanlar gibi 2 Ağızlarını açıyorlar bana.'),
(1997610,68,19,22,14,'Su gibi dökülüyorum, 2 Bütün kemiklerim oynaklarından çıkıyor; 2 Yüreğim balmumu gibi içimde eriyor.'),
(1997611,68,19,22,15,'Gücüm çömlek parçası gibi kurudu, 2 Dilim damağıma yapışıyor; 2 Beni ölüm toprağına yatırdın.'),
(1997612,68,19,22,16,'Köpekler kuşatıyor beni, 2 Kötüler sürüsü çevremi sarıyor, 2 Ellerimi, ayaklarımı deliyorlar.'),
(1997613,68,19,22,17,'Bütün kemiklerimi sayar oldum, 2 Gözlerini dikmiş, bana bakıyorlar.'),
(1997614,68,19,22,18,'Giysilerimi aralarında paylaşıyor, 2 Elbisem için kura çekiyorlar.'),
(1997615,68,19,22,19,'Ama sen, ya RAB, uzak durma; 2 Ey gücüm benim, yardımıma koş!'),
(1997616,68,19,22,20,'Canımı kılıçtan, 2 Biricik hayatımı köpeğin pençesinden kurtar!'),
(1997617,68,19,22,21,'Kurtar beni aslanın ağzından, 2 Yaban öküzlerinin boynuzundan. 2 Yanıt ver bana!'),
(1997618,68,19,22,22,'Adını kardeşlerime duyurayım, 2 Topluluğun ortasında sana övgüler sunayım:'),
(1997619,68,19,22,23,'Ey sizler, RABden korkanlar, Ona övgüler sunun! 2 Ey Yakup soyu, Onu yüceltin! 2 Ey İsrail soyu, Ona saygı gösterin!'),
(1997620,68,19,22,24,'Çünkü O mazlumun çektiği sıkıntıyı hafife almadı, 2 Ondan tiksinmedi, yüz çevirmedi; 2 Kendisini yardıma çağırdığında ona kulak verdi.'),
(1997621,68,19,22,25,'Övgü konum sen olacaksın büyük toplulukta, 2 Senden korkanların önünde yerine getireceğim adaklarımı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997622,68,19,22,26,'Yoksullar yiyip doyacak, 2 RABbe yönelenler Ona övgü sunacak. 2 Sonsuza dek ömrünüz tükenmesin!'),
(1997623,68,19,22,27,'Yeryüzünün dört bucağı anımsayıp RABbe dönecek, 2 Ulusların bütün soyları Onun önünde yere kapanacak.'),
(1997624,68,19,22,28,'Çünkü egemenlik RABbindir, 2 Ulusları O yönetir.'),
(1997625,68,19,22,29,'Yeryüzündeki bütün zenginler doyacak 2 Ve Onun önünde yere kapanacak, 2 Toprağa gidenler, 2 Ölümlerine engel olamayanlar, 2 Eğilecekler Onun önünde.'),
(1997626,68,19,22,30,'Gelecek kuşaklar Ona kulluk edecek, 2 Rab yeni kuşaklara anlatılacak.'),
(1997627,68,19,22,31,'O''nun kurtarışını, 2 ‹‹Rab yaptı bunları›› diyerek, 2 Henüz doğmamış bir halka duyuracaklar.'),
(1997628,68,19,23,1,'RAB çobanımdır, 2 Eksiğim olmaz.'),
(1997629,68,19,23,2,'Beni yemyeşil çayırlarda yatırır, 2 Sakin suların kıyısına götürür.'),
(1997630,68,19,23,3,'İçimi tazeler, 2 Adı uğruna bana doğru yollarda öncülük eder.'),
(1997631,68,19,23,4,'Karanlık ölüm vadisinden geçsem bile, 2 Kötülükten korkmam. 2 Çünkü sen benimlesin. 2 Çomağın, değneğin güven verir bana.'),
(1997632,68,19,23,5,'Düşmanlarımın önünde bana sofra kurarsın, 2 Başıma yağ sürersin, 2 Kâsem taşıyor.'),
(1997633,68,19,23,6,'Ömrüm boyunca yalnız iyilik ve sevgi izleyecek beni, 2 Hep RAB''bin evinde oturacağım.'),
(1997634,68,19,24,1,'RABbindir yeryüzü ve içindeki her şey, 2 Dünya ve üzerinde yaşayanlar;'),
(1997635,68,19,24,2,'Çünkü Odur denizler üzerinde onu kuran, 2 Sular üzerinde durduran.'),
(1997636,68,19,24,3,'RABbin dağına kim çıkabilir, 2 Kutsal yerinde kim durabilir?'),
(1997637,68,19,24,4,'Elleri pak, yüreği temiz olan, 2 Gönlünü putlara kaptırmayan, 2 Yalan yere ant içmeyen.'),
(1997638,68,19,24,5,'RAB kutsar böylesini, 2 Kurtarıcısı Tanrı aklar.'),
(1997639,68,19,24,6,'Ona yönelenler, 2 Yakupun Tanrısının yüzünü arayanlar 2 İşte böyledir. |iSela'),
(1997640,68,19,24,7,'Kaldırın başınızı, ey kapılar! 2 Açılın, ey eski kapılar! 2 Yüce Kral girsin içeri!'),
(1997641,68,19,24,8,'Kimdir bu Yüce Kral? 2 O RABdir, güçlü ve yiğit, 2 Savaşta yiğit olan RAB.'),
(1997642,68,19,24,9,'Kaldırın başınızı, ey kapılar! 2 Açılın, ey eski kapılar! 2 Yüce Kral girsin içeri!'),
(1997643,68,19,24,10,'Kimdir bu Yüce Kral? 2 Her Şeye Egemen 2 RAB''dir bu Yüce Kral! |iSela'),
(1997644,68,19,25,1,'Ya RAB, bütün varlığımla sana yaklaşıyorum,'),
(1997645,68,19,25,2,'Ey Tanrım, sana güveniyorum, utandırma beni, 2 Düşmanlarım zafer kahkahası atmasın!'),
(1997646,68,19,25,3,'Sana umut bağlayan hiç kimse utanca düşmez; 2 Nedensiz hainlik edenler utanır.'),
(1997647,68,19,25,4,'Ya RAB, yollarını bana öğret, 2 Yönlerini bildir.'),
(1997648,68,19,25,5,'Bana gerçek yolunda öncülük et, eğit beni; 2 Çünkü beni kurtaran Tanrı sensin. 2 Bütün gün umudum sende.'),
(1997649,68,19,25,6,'Ya RAB, sevecenliğini ve sevgini anımsa; 2 Çünkü onlar öncesizlikten beri aynıdır.'),
(1997650,68,19,25,7,'Gençlik günahlarımı, isyanlarımı anımsama, 2 Sevgine göre anımsa beni, 2 Çünkü sen iyisin, ya RAB.'),
(1997651,68,19,25,8,'RAB iyi ve doğrudur, 2 Onun için günahkârlara yol gösterir.'),
(1997652,68,19,25,9,'Alçakgönüllülere adalet yolunda öncülük eder, 2 Kendi yolunu öğretir onlara.'),
(1997653,68,19,25,10,'RABbin bütün yolları sevgi ve sadakate dayanır 2 Antlaşmasındaki buyruklara uyanlar için.'),
(1997654,68,19,25,11,'Ya RAB, adın uğruna 2 Suçumu bağışla, çünkü suçum büyük.'),
(1997655,68,19,25,12,'Kim RABden korkarsa, 2 RAB ona seçeceği yolu gösterir.'),
(1997656,68,19,25,13,'Gönenç içinde yaşayacak o insan, 2 Soyu ülkeyi sahiplenecek.'),
(1997657,68,19,25,14,'RAB kendisinden korkanlarla paylaşır sırrını, 2 Onlara açıklar antlaşmasını.'),
(1997658,68,19,25,15,'Gözlerim hep RABdedir, 2 Çünkü ayaklarımı ağdan O çıkarır.'),
(1997659,68,19,25,16,'Halime bak, lütfet bana; 2 Çünkü garip ve mazlumum.'),
(1997660,68,19,25,17,'Yüreğimdeki sıkıntılar artıyor, 2 Kurtar beni dertlerimden!'),
(1997661,68,19,25,18,'Üzüntüme, acılarıma bak, 2 Bütün günahlarımı bağışla!'),
(1997662,68,19,25,19,'Düşmanlarıma bak, ne kadar çoğaldılar, 2 Nasıl da benden nefret ediyorlar!'),
(1997663,68,19,25,20,'Canımı koru, kurtar beni! 2 Hayal kırıklığına uğratma, çünkü sana sığınıyorum!'),
(1997664,68,19,25,21,'Dürüstlük, doğruluk korusun beni, 2 Çünkü umudum sendedir.'),
(1997665,68,19,25,22,'Ey Tanrı, kurtar İsrail''i 2 Bütün sıkıntılarından!'),
(1997666,68,19,26,1,'Beni haklı çıkar, ya RAB, 2 Çünkü dürüst bir yaşam sürdüm; 2 Sarsılmadan RABbe güvendim.'),
(1997667,68,19,26,2,'Dene beni, ya RAB, sına; 2 Duygularımı, düşüncelerimi yokla.'),
(1997668,68,19,26,3,'Çünkü sevgini hep göz önünde tutuyor, 2 Senin gerçeğini yaşıyorum ben.'),
(1997669,68,19,26,4,'Yalancılarla oturmam, 2 İkiyüzlülerin suyuna gitmem.'),
(1997670,68,19,26,5,'Kötülük yapanlar topluluğundan nefret ederim, 2 Fesatçıların arasına girmem.'),
(1997671,68,19,26,6,'Suçsuzluğumu göstermek için ellerimi yıkar, 2 Sunağının çevresinde dönerim, ya RAB,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997672,68,19,26,7,'Yüksek sesle şükranımı duyurmak 2 Ve bütün harikalarını anlatmak için.'),
(1997673,68,19,26,8,'Severim, ya RAB, yaşadığın evi, 2 Görkeminin bulunduğu yeri.'),
(1997674,68,19,26,9,'Günahkârların, 2 Eli kanlı adamların yanısıra canımı alma.'),
(1997675,68,19,26,10,'Onların elleri kötülük aletidir, 2 Sağ elleri rüşvet doludur.'),
(1997676,68,19,26,11,'Ama ben dürüst yaşarım, 2 Kurtar beni, lütfet bana!'),
(1997677,68,19,26,12,'Ayağım emin yerde duruyor. 2 Topluluk içinde sana övgüler sunacağım, ya RAB.'),
(1997678,68,19,27,1,'RAB benim ışığım, kurtuluşumdur, 2 Kimseden korkmam. 2 RAB yaşamımın kalesidir, 2 Kimseden yılmam.'),
(1997679,68,19,27,2,'Hasımlarım, düşmanlarım olan kötüler, 2 Beni yutmak için üzerime gelirken 2 Tökezleyip düşerler.'),
(1997680,68,19,27,3,'Karşımda bir ordu konaklasa, 2 Kılım kıpırdamaz, 2 Bana karşı savaş açılsa, 2 Yine güvenimi yitirmem.'),
(1997681,68,19,27,4,'RABden tek dileğim, tek isteğim şu: 2 RABbin güzelliğini seyretmek, 2 Tapınağında Ona hayran olmak için 2 Ömrümün bütün günlerini Onun evinde geçirmek.'),
(1997682,68,19,27,5,'Çünkü O kötü günde beni çardağında gizleyecek, 2 Çadırının emin yerinde saklayacak, 2 Yüksek bir kaya üzerine çıkaracak beni.'),
(1997683,68,19,27,6,'O zaman çevremi saran düşmanlarıma karşı 2 Başım yukarı kalkacak, 2 Sevinçle haykırarak kurbanlar sunacağım Onun çadırında, 2 Onu ezgilerle, ilahilerle öveceğim.'),
(1997684,68,19,27,7,'Sana yakarıyorum, ya RAB, kulak ver sesime, 2 Lütfet, yanıtla beni!'),
(1997685,68,19,27,8,'Ya RAB, içimden bir ses duydum: 2 ‹‹Yüzümü ara!›› dedin, 2 İşte yüzünü arıyorum.'),
(1997686,68,19,27,9,'Yüzünü benden gizleme, 2 Kulunu öfkeyle geri çevirme! 2 Bana hep yardımcı oldun; 2 Bırakma, terk etme beni, 2 Ey beni kurtaran Tanrı!'),
(1997687,68,19,27,10,'Annemle babam beni terk etseler bile, 2 RAB beni kabul eder.'),
(1997688,68,19,27,11,'Ya RAB, yolunu öğret bana, 2 Düşmanlarıma karşı 2 Düz yolda bana öncülük et.'),
(1997689,68,19,27,12,'Beni hasımlarımın keyfine bırakma, 2 Çünkü yalancı tanıklar dikiliyor karşıma, 2 Ağızları şiddet saçıyor.'),
(1997690,68,19,27,13,'Yaşam diyarında 2 RABbin iyiliğini göreceğimden kuşkum yok.'),
(1997691,68,19,27,14,'Umudunu RAB''be bağla, 2 Güçlü ve yürekli ol; 2 Umudunu RAB''be bağla!'),
(1997692,68,19,28,1,'Ya RAB, sana yakarıyorum, 2 Kayam benim, kulak tıkama sesime; 2 Çünkü sen sessiz kalırsan, 2 Ölüm çukuruna inen ölülere dönerim ben.'),
(1997693,68,19,28,2,'Seni yardıma çağırdığımda, 2 Ellerimi kutsal konutuna doğru açtığımda, 2 Kulak ver yalvarışlarıma.'),
(1997694,68,19,28,3,'Beni kötülerle, haksızlık yapanlarla 2 Aynı kefeye koyup cezalandırma. 2 Onlar komşularıyla dostça konuşur, 2 Ama yüreklerinde kötülük beslerler.'),
(1997695,68,19,28,4,'Eylemlerine, yaptıkları kötülüklere göre onları yanıtla; 2 Yaptıklarının, hak ettiklerinin karşılığını ver.'),
(1997696,68,19,28,5,'Onlar RABbin yaptıklarına, 2 Ellerinin eserine önem vermezler; 2 Bu yüzden RAB onları yıkacak, 2 Bir daha ayağa kaldırmayacak.'),
(1997697,68,19,28,6,'RABbe övgüler olsun! 2 Çünkü yalvarışımı duydu.'),
(1997698,68,19,28,7,'RAB benim gücüm, kalkanımdır, 2 Ona yürekten güveniyor ve yardım görüyorum. 2 Yüreğim coşuyor, 2 Ezgilerimle Ona şükrediyorum.'),
(1997699,68,19,28,8,'RAB halkının gücüdür, 2 Meshettiği kralın zafer kalesidir.'),
(1997700,68,19,28,9,'Halkını kurtar, kendi halkını kutsa; 2 Çobanlık et onlara, sürekli destek ol!'),
(1997701,68,19,29,1,'Ey ilahi varlıklar, RABbi övün, 2 RABbin gücünü, yüceliğini övün,'),
(1997702,68,19,29,2,'RABbin görkemini adına yaraşır biçimde övün, 2 Kutsal giysiler içinde RABbe tapının!'),
(1997703,68,19,29,3,'RABbin sesi sulara hükmediyor, 2 Yüce Tanrı gürlüyor, 2 RAB engin sulara hükmediyor.'),
(1997704,68,19,29,4,'RABbin sesi güçlüdür, 2 RABbin sesi görkemlidir.'),
(1997705,68,19,29,5,'RABbin sesi sedir ağaçlarını kırar, 2 Lübnan sedirlerini parçalar.'),
(1997706,68,19,29,6,'Lübnanı buzağı gibi, 2 Siryon Dağını yabanıl öküz yavrusu gibi sıçratır.'),
(1997707,68,19,29,7,'RABbin sesi şimşek gibi çakar,'),
(1997708,68,19,29,8,'RABbin sesi çölü titretir, 2 RAB Kadeş Çölünü sarsar.'),
(1997709,68,19,29,9,'RABbin sesi geyikleri doğurtur, 2 Ormanları çıplak bırakır. 2 Onun tapınağında herkes ‹‹Yücesin!›› diye haykırır. eğer››.'),
(1997710,68,19,29,10,'RAB tufan üstünde taht kurdu, 2 O sonsuza dek kral kalacak.'),
(1997711,68,19,29,11,'RAB halkına güç verir, 2 Halkını esenlikle kutsar!'),
(1997712,68,19,30,1,'Seni yüceltmek istiyorum, ya RAB, 2 Çünkü beni kurtardın, 2 Düşmanlarımı bana güldürmedin.'),
(1997713,68,19,30,2,'Ya RAB Tanrım, 2 Sana yakardım, bana şifa verdin.'),
(1997714,68,19,30,3,'Ya RAB, beni ölüler diyarından çıkardın, 2 Yaşam verdin bana, ölüm çukuruna düşürmedin.'),
(1997715,68,19,30,4,'Ey RABbin sadık kulları, Onu ilahilerle övün, 2 Kutsallığını anarak Ona şükredin.'),
(1997716,68,19,30,5,'Çünkü öfkesi bir an sürer, 2 Lütfu ise bir ömür; 2 Gözyaşlarınız belki bir gece akar, 2 Ama sabahla sevinç doğar.'),
(1997717,68,19,30,6,'Huzur duyunca dedim ki, 2 ‹‹Asla sarsılmayacağım!››'),
(1997718,68,19,30,7,'Ya RAB, lütfunla beni güçlü bir dağ gibi 2 Sarsılmaz kıldın; 2 Ama sen yüzünü gizleyince, 2 Dehşete düştüm.'),
(1997719,68,19,30,8,'Ya RAB, sana sesleniyorum, 2 Rabbe yalvarıyorum:'),
(1997720,68,19,30,9,'‹‹Ne yararı olur senin için dökülen kanımın, 2 Ölüm çukuruna inersem? 2 Toprak sana övgüler sunar mı, 2 Senin sadakatini ilan eder mi?'),
(1997721,68,19,30,10,'Dinle, ya RAB, acı bana; 2 Yardımcım ol, ya RAB!››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997722,68,19,30,11,'Yasımı şenliğe döndürdün, 2 Çulumu çıkarıp beni sevinçle kuşattın.'),
(1997723,68,19,30,12,'Öyle ki, gönlüm seni ilahilerle övsün, susmasın! 2 Ya RAB Tanrım, sana sürekli şükredeceğim.'),
(1997724,68,19,31,1,'Ya RAB, sana sığınıyorum. 2 Utandırma beni hiçbir zaman! 2 Adaletinle kurtar beni!'),
(1997725,68,19,31,2,'Kulak ver bana, 2 Çabuk yetiş, kurtar beni; 2 Bir kaya ol bana sığınmam için, 2 Güçlü bir kale ol kurtulmam için!'),
(1997726,68,19,31,3,'Madem kayam ve kalem sensin, 2 Öncülük et, yol göster bana 2 Kendi adın uğruna.'),
(1997727,68,19,31,4,'Bana kurdukları tuzaktan uzak tut beni, 2 Çünkü sığınağım sensin.'),
(1997728,68,19,31,5,'Ruhumu ellerine bırakıyorum, 2 Ya RAB, sadık Tanrı, kurtar beni.'),
(1997729,68,19,31,6,'Değersiz putlara bel bağlayanlardan tiksinirim, 2 RABbe güvenirim ben.'),
(1997730,68,19,31,7,'Sadakatinden ötürü sevinip coşacağım, 2 Çünkü düşkün halimi görüyor, 2 Çektiğim sıkıntıları biliyorsun,'),
(1997731,68,19,31,8,'Beni düşman eline düşürmedin, 2 Bastığım yerleri genişlettin.'),
(1997732,68,19,31,9,'Acı bana, ya RAB, sıkıntıdayım, 2 Üzüntü gözümü, canımı, içimi kemiriyor.'),
(1997733,68,19,31,10,'Ömrüm acıyla, 2 Yıllarım iniltiyle tükeniyor, 2 Suçumdan ötürü gücüm zayıflıyor, 2 Kemiklerim eriyor.'),
(1997734,68,19,31,11,'Düşmanlarım yüzünden rezil oldum, 2 Özellikle komşularıma. 2 Tanıdıklarıma dehşet salar oldum; 2 Beni sokakta görenler benden kaçar oldu.'),
(1997735,68,19,31,12,'Gönülden çıkmış bir ölü gibi unutuldum, 2 Kırılmış bir çömleğe döndüm.'),
(1997736,68,19,31,13,'Birçoğunun fısıldaştığını duyuyorum, 2 Her yer dehşet içinde, 2 Bana karşı anlaştılar, 2 Canımı almak için düzen kurdular.'),
(1997737,68,19,31,14,'Ama ben sana güveniyorum, ya RAB, 2 ‹‹Tanrım sensin!›› diyorum.'),
(1997738,68,19,31,15,'Hayatım senin elinde, 2 Kurtar beni düşmanlarımın pençesinden, 2 Ardıma düşenlerden.'),
(1997739,68,19,31,16,'Yüzün kulunu aydınlatsın, 2 Sevgi göster, kurtar beni!'),
(1997740,68,19,31,17,'Utandırma beni, ya RAB, sana sesleniyorum; 2 Kötüler utansın, ölüler diyarında sesleri kesilsin.'),
(1997741,68,19,31,18,'Sussun o yalancı dudaklar; 2 Doğru insana karşı 2 Gururla, tepeden bakarak, 2 Küçümseyerek konuşan dudaklar.'),
(1997742,68,19,31,19,'İyiliğin ne büyüktür, ya RAB, 2 Onu senden korkanlar için saklarsın, 2 Herkesin gözü önünde, 2 Sana sığınanlara iyi davranırsın.'),
(1997743,68,19,31,20,'İnsanların düzenlerine karşı, 2 Koruyucu huzurunla üzerlerine kanat gerersin; 2 Saldırgan dillere karşı 2 Onları çardağında gizlersin.'),
(1997744,68,19,31,21,'RABbe övgüler olsun, 2 Kuşatılmış bir kentte 2 Sevgisini bana harika biçimde gösterdi.'),
(1997745,68,19,31,22,'Telaş içinde demiştim ki, 2 ‹‹Huzurundan atıldım!›› 2 Ama yardıma çağırınca seni, 2 Yalvarışımı işittin.'),
(1997746,68,19,31,23,'RABbi sevin, ey Onun sadık kulları! 2 RAB kendisine bağlı olanları korur, 2 Büyüklenenlerin ise tümüyle hakkından gelir.'),
(1997747,68,19,31,24,'Ey RAB''be umut bağlayanlar, 2 Güçlü ve yürekli olun!'),
(1997748,68,19,32,1,'Ne mutlu isyanı bağışlanan, 2 Günahı örtülen insana! edebiyat terimi. ‹‹Didaktik şiir›› anlamına gelebilir.'),
(1997749,68,19,32,2,'Suçu RAB tarafından sayılmayan, 2 Ruhunda hile bulunmayan insana ne mutlu!'),
(1997750,68,19,32,3,'Sustuğum sürece 2 Kemiklerim eridi, 2 Gün boyu inlemekten.'),
(1997751,68,19,32,4,'Çünkü gece gündüz 2 Elin üzerimde ağırlaştı. 2 Dermanım tükendi yaz sıcağında gibi. |iSela'),
(1997752,68,19,32,5,'Günahımı açıkladım sana, 2 Suçumu gizlemedim. 2 ‹‹RABbe isyanımı itiraf edeceğim›› deyince, 2 Günahımı, suçumu bağışladın. |iSela'),
(1997753,68,19,32,6,'Bu nedenle her sadık kulun 2 Ulaşılır olduğun zaman sana dua etsin. 2 Engin sular taşsa bile ona erişemez.'),
(1997754,68,19,32,7,'Sığınağım sensin, 2 Beni sıkıntıdan korur, 2 Çevremi kurtuluş ilahileriyle kuşatırsın. |iSela'),
(1997755,68,19,32,8,'Eğiteceğim seni, gideceğin yolu göstereceğim, 2 Öğüt vereceğim sana, 2 Gözüm sendedir.'),
(1997756,68,19,32,9,'At ya da katır gibi anlayışsız olmayın; 2 Onları idare etmek için gem ve dizgin gerekir, 2 Yoksa sana yaklaşmazlar.'),
(1997757,68,19,32,10,'Kötülerin acısı çoktur, 2 Ama RABbe güvenenleri Onun sevgisi kuşatır.'),
(1997758,68,19,32,11,'Ey doğru insanlar, sevinç kaynağınız RAB olsun, coşun; 2 Ey yüreği temiz olanlar, 2 Hepiniz sevinç çığlıkları atın!'),
(1997759,68,19,33,1,'Ey doğru insanlar, RABbe sevinçle haykırın! 2 Dürüstlere Onu övmek yaraşır.'),
(1997760,68,19,33,2,'Lir çalarak RABbe şükredin, 2 On telli çenk eşliğinde Onu ilahilerle övün.'),
(1997761,68,19,33,3,'Ona yeni bir ezgi söyleyin, 2 Sevinç çığlıklarıyla sazınızı konuşturun.'),
(1997762,68,19,33,4,'Çünkü RABbin sözü doğrudur, 2 Her işi sadakatle yapar.'),
(1997763,68,19,33,5,'Doğruluğu, adaleti sever, 2 RABbin sevgisi yeryüzünü doldurur.'),
(1997764,68,19,33,6,'Gökler RABbin sözüyle, 2 Gök cisimleri ağzından çıkan solukla yaratıldı.'),
(1997765,68,19,33,7,'Deniz sularını bir araya toplar, 2 Engin suları ambarlara depolar.'),
(1997766,68,19,33,8,'Bütün yeryüzü RABden korksun, 2 Dünyada yaşayan herkes Ona saygı duysun.'),
(1997767,68,19,33,9,'Çünkü O söyleyince, her şey var oldu; 2 O buyurunca, her şey belirdi.'),
(1997768,68,19,33,10,'RAB ulusların planlarını bozar, 2 Halkların tasarılarını boşa çıkarır.'),
(1997769,68,19,33,11,'Ama RABbin planları sonsuza dek sürer, 2 Yüreğindeki tasarılar kuşaklar boyunca değişmez.'),
(1997770,68,19,33,12,'Ne mutlu Tanrısı RAB olan ulusa, 2 Kendisi için seçtiği halka!'),
(1997771,68,19,33,13,'RAB göklerden bakar, 2 Bütün insanları görür.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997772,68,19,33,14,'Oturduğu yerden, 2 Yeryüzünde yaşayan herkesi gözler.'),
(1997773,68,19,33,15,'Herkesin yüreğini yaratan, 2 Yaptıkları her şeyi tartan Odur.'),
(1997774,68,19,33,16,'Ne büyük ordularıyla zafer kazanan kral var, 2 Ne de büyük gücüyle kurtulan yiğit.'),
(1997775,68,19,33,17,'Zafer için at boş bir umuttur, 2 Büyük gücüne karşın kimseyi kurtaramaz.'),
(1997776,68,19,33,18,'Ama RABbin gözü kendisinden korkanların, 2 Sevgisine umut bağlayanların üzerindedir;'),
(1997777,68,19,33,19,'Böylece onları ölümden kurtarır, 2 Kıtlıkta yaşamalarını sağlar.'),
(1997778,68,19,33,20,'Umudumuz RABdedir, 2 Yardımcımız, kalkanımız Odur.'),
(1997779,68,19,33,21,'Onda sevinç bulur yüreğimiz, 2 Çünkü Onun kutsal adına güveniriz.'),
(1997780,68,19,33,22,'Madem umudumuz sende, 2 Sevgin üzerimizde olsun, ya RAB!'),
(1997781,68,19,34,1,'Her zaman RABbe övgüler sunacağım, 2 Övgüsü dilimden düşmeyecek.'),
(1997782,68,19,34,2,'RABle övünürüm, 2 Mazlumlar işitip sevinsin!'),
(1997783,68,19,34,3,'Benimle birlikte RABbin büyüklüğünü duyurun, 2 Adını birlikte yüceltelim.'),
(1997784,68,19,34,4,'RABbe yöneldim, yanıt verdi bana, 2 Bütün korkularımdan kurtardı beni.'),
(1997785,68,19,34,5,'Ona bakanların yüzü ışıl ışıl parlar, 2 Yüzleri utançtan kızarmaz.'),
(1997786,68,19,34,6,'Bu mazlum yakardı, RAB duydu, 2 Bütün sıkıntılarından kurtardı onu.'),
(1997787,68,19,34,7,'RABbin meleği Ondan korkanların çevresine ordugah kurar, 2 Kurtarır onları.'),
(1997788,68,19,34,8,'Tadın da görün, RAB ne iyidir, 2 Ne mutlu Ona sığınan adama!'),
(1997789,68,19,34,9,'RABden korkun, ey Onun kutsalları, 2 Çünkü Ondan korkanın eksiği olmaz.'),
(1997790,68,19,34,10,'Genç aslanlar bile aç ve muhtaç olur; 2 Ama RABbe yönelenlerden hiçbir iyilik esirgenmez.'),
(1997791,68,19,34,11,'Gelin, ey çocuklar, dinleyin beni: 2 Size RAB korkusunu öğreteyim.'),
(1997792,68,19,34,12,'Kim yaşamdan zevk almak, 2 İyi günler görmek istiyorsa,'),
(1997793,68,19,34,13,'Dilini kötülükten, 2 Dudaklarını yalandan uzak tutsun.'),
(1997794,68,19,34,14,'Kötülükten sakının, iyilik yapın; 2 Esenliği amaçlayın, ardınca gidin.'),
(1997795,68,19,34,15,'RABbin gözleri doğru kişilerin üzerindedir, 2 Kulakları onların yakarışına açıktır.'),
(1997796,68,19,34,16,'RAB kötülük yapanlara karşıdır, 2 Onların anısını yeryüzünden siler.'),
(1997797,68,19,34,17,'Doğrular yakarır, RAB duyar; 2 Bütün sıkıntılarından kurtarır onları.'),
(1997798,68,19,34,18,'RAB gönlü kırıklara yakındır, 2 Ruhu ezginleri kurtarır.'),
(1997799,68,19,34,19,'Doğrunun dertleri çoktur, 2 Ama RAB hepsinden kurtarır onu.'),
(1997800,68,19,34,20,'Bütün kemiklerini korur, 2 Hiçbiri kırılmaz.'),
(1997801,68,19,34,21,'Kötü insanın sonu kötülükle biter, 2 Cezasını bulur doğrulardan nefret edenler.'),
(1997802,68,19,34,22,'RAB kullarını kurtarır, 2 O''na sığınanların hiçbiri ceza görmez.'),
(1997803,68,19,35,1,'Ya RAB, benimle uğraşanlarla sen uğraş, 2 Benimle savaşanlarla sen savaş!'),
(1997804,68,19,35,2,'Al küçük kalkanla büyük kalkanı, 2 Yardımıma koş!'),
(1997805,68,19,35,3,'Kaldır mızrağını, kargını beni kovalayanlara, 2 ‹‹Seni ben kurtarırım›› de bana!'),
(1997806,68,19,35,4,'Canıma kastedenler utanıp rezil olsun! 2 Utançla geri çekilsin bana kötülük düşünenler!'),
(1997807,68,19,35,5,'Rüzgarın sürüklediği saman çöpüne dönsünler, 2 RABbin meleği artlarına düşsün!'),
(1997808,68,19,35,6,'Karanlık ve kaygan olsun yolları, 2 RABbin meleği kovalasın onları!'),
(1997809,68,19,35,7,'Madem neden yokken bana gizli ağlar kurdular, 2 Nedensiz çukur kazdılar,'),
(1997810,68,19,35,8,'Başlarına habersiz felaket gelsin, 2 Gizledikleri ağa kendileri tutulsun, 2 Felakete uğrasınlar.'),
(1997811,68,19,35,9,'O zaman RABde sevinç bulacağım, 2 Beni kurtardığı için coşacağım.'),
(1997812,68,19,35,10,'Bütün varlığımla şöyle diyeceğim: 2 ‹‹Senin gibisi var mı, ya RAB, 2 Mazlumu zorbanın elinden, 2 Mazlumu ve yoksulu soyguncudan kurtaran?››'),
(1997813,68,19,35,11,'Kötü niyetli tanıklar türüyor, 2 Bilmediğim konuları soruyorlar.'),
(1997814,68,19,35,12,'İyiliğime karşı kötülük ediyor, 2 Yalnızlığa itiyorlar beni.'),
(1997815,68,19,35,13,'Oysa onlar hastalanınca ben çula sarınır, 2 Oruç tutup alçakgönüllü olurdum. 2 Duam yanıtsız kalınca, 2 Bir dost, bir kardeş yitirmiş gibi dolaşırdım. 2 Kederden belim bükülürdü, 2 Annesi için yas tutan biri gibi.'),
(1997816,68,19,35,15,'Ama ben sendeleyince toplanıp sevindiler, 2 Toplandı bana karşı tanımadığım alçaklar, 2 Durmadan didiklediler beni.'),
(1997817,68,19,35,16,'Tanrıtanımaz, alaycı soytarılar gibi, 2 Diş gıcırdattılar bana.'),
(1997818,68,19,35,17,'Ne zamana dek seyirci kalacaksın, ya Rab? 2 Kurtar canımı bunların saldırısından, 2 Hayatımı bu genç aslanlardan!'),
(1997819,68,19,35,18,'Büyük toplantıda sana şükürler sunacağım, 2 Kalabalığın ortasında sana övgüler dizeceğim.'),
(1997820,68,19,35,19,'Sevinmesin boş yere bana düşman olanlar, 2 Göz kırpmasınlar birbirlerine 2 Nedensiz benden nefret edenler.'),
(1997821,68,19,35,20,'Çünkü barış sözünü etmez onlar, 2 Kurnazca düzen kurarlar ülkenin sakin insanlarına.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997822,68,19,35,21,'Beni suçlamak için ağızlarını ardına kadar açtılar: 2 ‹‹Oh! Oh!›› diyorlar, ‹‹İşte kendi gözümüzle gördük yaptıklarını!››'),
(1997823,68,19,35,22,'Olup biteni sen de gördün, ya RAB, sessiz kalma, 2 Ya Rab, benden uzak durma!'),
(1997824,68,19,35,23,'Uyan, kalk savun beni, 2 Uğraş hakkım için, ey Tanrım ve Rabbim!'),
(1997825,68,19,35,24,'Adaletin uyarınca haklı çıkar beni, ya RAB, Tanrım benim! 2 Gülmesinler halime!'),
(1997826,68,19,35,25,'Demesinler içlerinden: 2 ‹‹Oh! İşte buydu dileğimiz!››, 2 Konuşmasınlar ardımdan: 2 ‹‹Yedik başını!›› diye.'),
(1997827,68,19,35,26,'Utansın kötü halime sevinenler, 2 Kızarsın yüzleri hepsinin; 2 Gururla karşıma dikilenler 2 Utanca, rezalete bürünsün.'),
(1997828,68,19,35,27,'Benim haklı çıkmamı isteyenler, 2 Sevinç çığlıkları atıp coşsunlar; 2 Şöyle desinler sürekli: 2 ‹‹Kulunun esenliğinden hoşlanan RAB yücelsin!››'),
(1997829,68,19,35,28,'O zaman gün boyu adaletin, 2 Övgülerin dilimden düşmeyecek.'),
(1997830,68,19,36,1,'Günah fısıldar kötü insana, 2 Yüreğinin dibinden: 2 Tanrı korkusu yoktur onda.'),
(1997831,68,19,36,2,'Kendini öyle beğenmiş ki, 2 Suçunu görmez, ondan tiksinmez.'),
(1997832,68,19,36,3,'Ağzından kötülük ve yalan akar, 2 Akıllanmaktan, iyilik yapmaktan vazgeçmiş.'),
(1997833,68,19,36,4,'Yatağında bile fesat düşünür, 2 Olumsuz yolda direnir, reddetmez kötülüğü.'),
(1997834,68,19,36,5,'Ya RAB, sevgin göklere, 2 Sadakatin gökyüzüne erişir.'),
(1997835,68,19,36,6,'Doğruluğun ulu dağlara benzer, 2 Adaletin uçsuz bucaksız enginlere. 2 İnsanı da, hayvanı da koruyan sensin, ya RAB.'),
(1997836,68,19,36,7,'Sevgin ne değerli, ey Tanrı! 2 Kanatlarının gölgesine sığınır insanoğlu.'),
(1997837,68,19,36,8,'Evindeki bolluğa doyarlar, 2 Zevklerinin ırmağından içirirsin onlara.'),
(1997838,68,19,36,9,'Çünkü yaşam kaynağı sensin, 2 Senin ışığınla aydınlanırız.'),
(1997839,68,19,36,10,'Sürekli göster 2 Seni tanıyanlara sevgini, 2 Yüreği temiz olanlara doğruluğunu.'),
(1997840,68,19,36,11,'Gururlunun ayağı bana varmasın, 2 Kötülerin eli beni kovmasın.'),
(1997841,68,19,36,12,'Kötülük yapanlar oracıkta düştüler, 2 Yıkıldılar, kalkamazlar artık.'),
(1997842,68,19,37,1,'Kötülük edenlere kızıp üzülme, 2 Suç işleyenlere özenme!'),
(1997843,68,19,37,2,'Çünkü onlar ot gibi hemen solacak, 2 Yeşil bitki gibi kuruyup gidecek.'),
(1997844,68,19,37,3,'Sen RABbe güven, iyilik yap, 2 Ülkede otur, sadakatle çalış.'),
(1997845,68,19,37,4,'RABden zevk al, 2 O senin içindeki istekleri yerine getirecektir.'),
(1997846,68,19,37,5,'Her şeyi RABbe bırak, 2 Ona güven, O gerekeni yapar.'),
(1997847,68,19,37,6,'O senin doğruluğunu ışık gibi, 2 Hakkını öğle güneşi gibi 2 Aydınlığa çıkarır.'),
(1997848,68,19,37,7,'RABbin önünde sakin dur, sabırla bekle; 2 Kızıp üzülme işi yolunda olanlara, 2 Kötü amaçlarına kavuşanlara.'),
(1997849,68,19,37,8,'Kızmaktan kaçın, bırak öfkeyi, 2 Üzülme, yalnız kötülüğe sürükler bu seni.'),
(1997850,68,19,37,9,'Çünkü kötülerin kökü kazınacak, 2 Ama RABbe umut bağlayanlar ülkeyi miras alacak.'),
(1997851,68,19,37,10,'Yakında kötünün sonu gelecek, 2 Yerini arasan da bulunmayacak.'),
(1997852,68,19,37,11,'Ama alçakgönüllüler ülkeyi miras alacak, 2 Derin bir huzurun zevkini tadacak.'),
(1997853,68,19,37,12,'Kötü insan doğru insana düzen kurar, 2 Diş gıcırdatır.'),
(1997854,68,19,37,13,'Ama Rab kötüye güler, 2 Çünkü bilir onun sonunun geldiğini.'),
(1997855,68,19,37,14,'Kılıç çekti kötüler, yaylarını gerdi, 2 Mazlumu, yoksulu yıkmak, 2 Doğru yolda olanları öldürmek için.'),
(1997856,68,19,37,15,'Ama kılıçları kendi yüreklerine saplanacak, 2 Yayları kırılacak.'),
(1997857,68,19,37,16,'Doğrunun azıcık varlığı, 2 Pek çok kötünün servetinden iyidir.'),
(1997858,68,19,37,17,'Çünkü kötülerin gücü kırılacak, 2 Ama doğrulara RAB destek olacak.'),
(1997859,68,19,37,18,'RAB yetkinlerin her gününü gözetir, 2 Onların mirası sonsuza dek sürecek.'),
(1997860,68,19,37,19,'Kötü günde utanmayacaklar, 2 Kıtlıkta karınları doyacak.'),
(1997861,68,19,37,20,'Ama kötüler yıkıma uğrayacak; 2 RABbin düşmanları kır çiçekleri gibi kuruyup gidecek, 2 Duman gibi dağılıp yok olacak.'),
(1997862,68,19,37,21,'Kötüler ödünç alır, geri vermez; 2 Doğrularsa cömertçe verir.'),
(1997863,68,19,37,22,'RABbin kutsadığı insanlar ülkeyi miras alacak, 2 Lanetlediği insanların kökü kazınacak.'),
(1997864,68,19,37,23,'RAB insana sağlam adım attırır, 2 İnsanın yolundan hoşnut olursa.'),
(1997865,68,19,37,24,'Düşse bile yıkılmaz insan, 2 Çünkü elinden tutan RABdir.'),
(1997866,68,19,37,25,'Gençtim, ömrüm tükendi, 2 Ama hiç görmedim doğru insanın terk edildiğini, 2 Soyunun ekmek dilendiğini.'),
(1997867,68,19,37,26,'O hep cömertçe ödünç verir, 2 Soyu kutsanır.'),
(1997868,68,19,37,27,'Kötülükten kaç, iyilik yap; 2 Sonsuz yaşama kavuşursun.'),
(1997869,68,19,37,28,'Çünkü RAB doğruyu sever, 2 Sadık kullarını terk etmez. 2 Onlar sonsuza dek korunacak, 2 Kötülerinse kökü kazınacak.'),
(1997870,68,19,37,29,'Doğrular ülkeyi miras alacak, 2 Orada sonsuza dek yaşayacak.'),
(1997871,68,19,37,30,'Doğrunun ağzından bilgelik akar, 2 Dilinden adalet damlar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997872,68,19,37,31,'Tanrısının yasası yüreğindedir, 2 Ayakları kaymaz.'),
(1997873,68,19,37,32,'Kötü, doğruya pusu kurar, 2 Onu öldürmeye çalışır.'),
(1997874,68,19,37,33,'Ama RAB onu kötünün eline düşürmez, 2 Yargılanırken mahkûm etmez.'),
(1997875,68,19,37,34,'RABbe umut bağla, Onun yolunu tut, 2 Ülkeyi miras almak üzere seni yükseltecektir. 2 Kötülerin kökünün kazındığını göreceksin.'),
(1997876,68,19,37,35,'Kötü ve acımasız adamı gördüm, 2 İlk dikildiği toprakta yeşeren ağaç gibi 2 Dal budak salıyordu;'),
(1997877,68,19,37,36,'Geçip gitti, yok oldu, 2 Aradım, bulunmaz oldu.'),
(1997878,68,19,37,37,'Yetkin adamı gözle, doğru adama bak, 2 Çünkü yarınlar barışseverindir.'),
(1997879,68,19,37,38,'Ama başkaldıranların hepsi yok olacak, 2 Kötülerin kökü kazınacak.'),
(1997880,68,19,37,39,'Doğruların kurtuluşu RABden gelir, 2 Sıkıntılı günde onlara kale olur.'),
(1997881,68,19,37,40,'RAB onlara yardım eder, kurtarır onları, 2 Kötülerin elinden alıp özgür kılar, 2 Çünkü kendisine sığınırlar.'),
(1997882,68,19,38,1,'Ya RAB, öfkelenip azarlama beni, 2 Gazapla yola getirme!'),
(1997883,68,19,38,2,'Okların içime saplandı, 2 Elin üzerime indi.'),
(1997884,68,19,38,3,'Öfken yüzünden sağlığım bozuldu, 2 Günahım yüzünden rahatım kaçtı.'),
(1997885,68,19,38,4,'Çünkü suçlarım başımdan aştı, 2 Taşınmaz bir yük gibi sırtımda ağırlaştı.'),
(1997886,68,19,38,5,'Akılsızlığım yüzünden 2 Yaralarım iğrenç, irinli.'),
(1997887,68,19,38,6,'Eğildim, iki büklüm oldum, 2 Gün boyu yaslı dolaşıyorum.'),
(1997888,68,19,38,7,'Çünkü belim ateş içinde, 2 Sağlığım bozuk.'),
(1997889,68,19,38,8,'Tükendim, ezildim alabildiğine, 2 İnliyorum yüreğimin acısından.'),
(1997890,68,19,38,9,'Ya Rab, bütün özlemlerimi bilirsin, 2 İniltilerim senden gizli değil.'),
(1997891,68,19,38,10,'Yüreğim çarpıyor, gücüm tükeniyor, 2 Gözlerimin feri bile söndü.'),
(1997892,68,19,38,11,'Eşim dostum kaçar oldu derdimden, 2 Yakınlarım uzak duruyor benden.'),
(1997893,68,19,38,12,'Canıma susayanlar bana tuzak kuruyor, 2 Zararımı isteyenler kuyumu kazıyor, 2 Gün boyu hileler düşünüyorlar.'),
(1997894,68,19,38,13,'Ama ben bir sağır gibi duymuyorum, 2 Bir dilsiz gibi ağzımı açmıyorum;'),
(1997895,68,19,38,14,'Duymaz, 2 Ağzında yanıt bulunmaz bir adama döndüm.'),
(1997896,68,19,38,15,'Umudum sende, ya RAB, 2 Sen yanıtlayacaksın, ya Rab, Tanrım benim!'),
(1997897,68,19,38,16,'Çünkü dua ediyorum: ‹‹Halime sevinmesinler, 2 Ayağım kayınca böbürlenmesinler!››'),
(1997898,68,19,38,17,'Düşmek üzereyim, 2 Acım hep içimde.'),
(1997899,68,19,38,18,'Suçumu itiraf ediyorum, 2 Günahım yüzünden kaygılanıyorum.'),
(1997900,68,19,38,19,'Ama düşmanlarım güçlü ve dinç, 2 Yok yere benden nefret edenler çok.'),
(1997901,68,19,38,20,'İyiliğe karşı kötülük yapanlar bana karşı çıkar, 2 İyiliğin peşinde olduğum için.'),
(1997902,68,19,38,21,'Beni terk etme, ya RAB! 2 Ey Tanrım, benden uzak durma!'),
(1997903,68,19,38,22,'Yardımıma koş, 2 Ya Rab, kurtuluşum benim!'),
(1997904,68,19,39,1,'Karar verdim: ‹‹Adımlarıma dikkat edeceğim, 2 Dilimi günahtan sakınacağım; 2 Karşımda kötü biri oldukça, 2 Ağzıma gem vuracağım.››'),
(1997905,68,19,39,2,'Dilimi tutup sustum, 2 Hep kaçındım konuşmaktan, yararı olsa bile. 2 Acım alevlendi,'),
(1997906,68,19,39,3,'Yüreğim tutuştu içimde, 2 Ateş aldı derin derin düşünürken, 2 Şu sözler döküldü dilimden:'),
(1997907,68,19,39,4,'‹‹Bildir bana, ya RAB, sonumu, 2 Sayılı günlerimi; 2 Bileyim ömrümün ne kadar kısa olduğunu!'),
(1997908,68,19,39,5,'Yalnız bir karış ömür verdin bana, 2 Hiç kalır hayatım senin önünde. 2 Her insan bir soluktur sadece, 2 En güçlü çağında bile. |iSela'),
(1997909,68,19,39,6,'‹‹Bir gölge gibi dolaşır insan, 2 Boş yere çırpınır, 2 Mal biriktirir, kime kalacağını bilmeden.'),
(1997910,68,19,39,7,'‹‹Ne bekleyebilirim şimdi, ya Rab? 2 Umudum sende.'),
(1997911,68,19,39,8,'Kurtar beni bütün isyanlarımdan, 2 Aptalların hakaretine izin verme.'),
(1997912,68,19,39,9,'Sustum, açmayacağım ağzımı; 2 Çünkü sensin bunu yapan.'),
(1997913,68,19,39,10,'Uzaklaştır üzerimden yumruklarını, 2 Tokadının altında mahvoldum.'),
(1997914,68,19,39,11,'Sen insanı suçundan ötürü 2 Azarlayarak yola getirirsin, 2 Güve gibi tüketirsin sevdiği şeyleri. 2 Her insan bir soluktur sadece. |iSela'),
(1997915,68,19,39,12,'‹‹Duamı işit, ya RAB, 2 Kulak ver yakarışıma, 2 Gözyaşlarıma kayıtsız kalma! 2 Çünkü ben bir garibim senin yanında, 2 Bir yabancı, atalarım gibi.'),
(1997916,68,19,39,13,'Uzaklaştır üzerimden bakışlarını, 2 Göçüp yok olmadan mutlu olayım!››'),
(1997917,68,19,40,1,'RABbi sabırla bekledim; 2 Bana yönelip yakarışımı duydu.'),
(1997918,68,19,40,2,'Ölüm çukurundan, 2 Balçıktan çıkardı beni, 2 Ayaklarımı kaya üzerinde tuttu, 2 Kaymayayım diye.'),
(1997919,68,19,40,3,'Ağzıma yeni bir ezgi, 2 Tanrımıza bir övgü ilahisi koydu. 2 Çokları görüp korkacak 2 Ve RABbe güvenecekler.'),
(1997920,68,19,40,4,'Ne mutlu RABbe güvenen insana, 2 Gururluya, yalana sapana ilgi duymayana.'),
(1997921,68,19,40,5,'Ya RAB, Tanrım, 2 Harikaların, düşüncelerin ne çoktur bizim için; 2 Sana eş koşulmaz! 2 Duyurmak, anlatmak istesem yaptıklarını, 2 Saymakla bitmez.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997922,68,19,40,6,'Kurbandan, sunudan hoşnut olmadın, 2 Ama kulaklarımı açtın. 2 Yakmalık sunu, günah sunusu da istemedin.'),
(1997923,68,19,40,7,'O zaman şöyle dedim: ‹‹İşte geldim; 2 Kutsal Yazı tomarında benim için yazılmıştır. 2 Ey Tanrım, senin isteğini yapmaktan zevk alırım ben, 2 Yasan yüreğimin derinliğindedir.››'),
(1997924,68,19,40,9,'Büyük toplantıda müjdelerim senin zaferini, 2 Sözümü esirgemem, 2 Ya RAB, bildiğin gibi!'),
(1997925,68,19,40,10,'Zaferini içimde gizlemem, 2 Bağlılığını ve kurtarışını duyururum, 2 Sevgini, sadakatini saklamam büyük topluluktan.'),
(1997926,68,19,40,11,'Ya RAB, esirgeme sevecenliğini benden! 2 Sevgin, sadakatin hep korusun beni!'),
(1997927,68,19,40,12,'Sayısız belalar çevremi sardı, 2 Suçlarım bana yetişti, önümü göremiyorum; 2 Başımdaki saçlardan daha çoklar, 2 Çaresiz kaldım.'),
(1997928,68,19,40,13,'Ne olur, ya RAB, kurtar beni! 2 Yardımıma koş, ya RAB!'),
(1997929,68,19,40,14,'Utansın canımı almaya çalışanlar, 2 Yüzleri kızarsın! 2 Geri dönsün zararımı isteyenler, 2 Rezil olsunlar!'),
(1997930,68,19,40,15,'Bana, ‹‹Oh! Oh!›› çekenler 2 Dehşete düşsün utançlarından!'),
(1997931,68,19,40,16,'Sende neşe ve sevinç bulsun 2 Bütün sana yönelenler! 2 ‹‹RAB yücedir!›› desin hep 2 Senin kurtarışını özleyenler!'),
(1997932,68,19,40,17,'Bense mazlum ve yoksulum, 2 Düşün beni, ya Rab. 2 Yardımcım ve kurtarıcım sensin, 2 Geç kalma, ey Tanrım!'),
(1997933,68,19,41,1,'Ne mutlu yoksulu düşünene! 2 RAB kurtarır onu kötü günde.'),
(1997934,68,19,41,2,'Korur RAB, yaşatır onu, 2 Ülkede mutlu kılar, 2 Terk etmez düşmanlarının eline.'),
(1997935,68,19,41,3,'Destek olur RAB ona 2 Yatağa düşünce; 2 Hastalandığında sağlığa kavuşturur onu.'),
(1997936,68,19,41,4,'‹‹Acı bana, ya RAB!›› dedim, 2 ‹‹Şifa ver bana, çünkü sana karşı günah işledim!››'),
(1997937,68,19,41,5,'Kötü konuşuyor düşmanlarım ardımdan: 2 ‹‹Ne zaman ölecek adı batası?›› diyorlar.'),
(1997938,68,19,41,6,'Biri beni görmeye geldi mi, boş laf ediyor, 2 Fesat topluyor içinde, 2 Sonra dışarı çıkıp fesadı yayıyor.'),
(1997939,68,19,41,7,'Benden nefret edenlerin hepsi 2 Fısıldaşıyor aralarında bana karşı, 2 Zararımı düşünüyorlar,'),
(1997940,68,19,41,8,'‹‹Başına öyle kötü bir şey geldi ki›› diyorlar, 2 ‹‹Yatağından kalkamaz artık.››'),
(1997941,68,19,41,9,'Ekmeğimi yiyen, güvendiğim yakın dostum bile 2 İhanet etti bana.'),
(1997942,68,19,41,10,'Bari sen acı bana, ya RAB, kaldır beni. 2 Bunların hakkından geleyim.'),
(1997943,68,19,41,11,'Düşmanım zafer çığlığı atmazsa, 2 O zaman anlarım benden hoşnut kaldığını.'),
(1997944,68,19,41,12,'Dürüstlüğümden ötürü bana destek olur, 2 Sonsuza dek beni huzurunda tutarsın.'),
(1997945,68,19,41,13,'Öncesizlikten sonsuza dek, 2 Övgüler olsun İsrail''in Tanrısı RAB''be! 2 Amin! Amin!'),
(1997946,68,19,42,1,'Geyik akarsuları nasıl özlerse, 2 Canım da seni öyle özler, ey Tanrı! yazılır.'),
(1997947,68,19,42,2,'Canım Tanrıya, yaşayan Tanrıya susadı; 2 Ne zaman görmeye gideceğim Tanrının yüzünü?'),
(1997948,68,19,42,3,'Gözyaşlarım ekmeğim oldu gece gündüz, 2 Gün boyu, ‹‹Nerede senin Tanrın?›› dedikleri için.'),
(1997949,68,19,42,4,'Anımsayınca içim içimi yiyor, 2 Nasıl toplulukla birlikte yürür, 2 Tanrının evine kadar alaya öncülük ederdim, 2 Sevinç ve şükran sesleri arasında, 2 Bayram eden bir kalabalıkla birlikte.'),
(1997950,68,19,42,5,'Neden üzgünsün, ey gönlüm, 2 Neden içim huzursuz? 2 Tanrıya umut bağla, 2 Çünkü Ona yine övgüler sunacağım; 2 O benim kurtarıcım ve Tanrımdır.'),
(1997951,68,19,42,6,'Gönlüm üzgün, 2 Bu yüzden seni anımsıyorum, ey Tanrım. 2 Şeria yöresinde, Hermon ve Misar dağlarında 2 Çağlayanların gümbürdeyince, 2 Enginler birbirine sesleniyor, 2 Bütün dalgaların, sellerin üzerimden geçiyor.'),
(1997952,68,19,42,8,'Gündüz RAB sevgisini gösterir, 2 Gece ilahi söyler, dua ederim 2 Yaşamımın Tanrısına.'),
(1997953,68,19,42,9,'Kayam olan Tanrıma diyorum ki, 2 ‹‹Neden beni unuttun? 2 Niçin düşmanlarımın baskısı altında 2 Yaslı gezeyim?››'),
(1997954,68,19,42,10,'Gün boyu hasımlarım: ‹‹Nerede senin Tanrın?›› diyerek 2 Bana sataştıkça, 2 Kemiklerim kırılıyor sanki.'),
(1997955,68,19,42,11,'Neden üzgünsün, ey gönlüm, 2 Neden içim huzursuz? 2 Tanrı''ya umut bağla, 2 Çünkü O''na yine övgüler sunacağım; 2 O benim kurtarıcım ve Tanrım''dır.'),
(1997956,68,19,43,1,'Hakkımı ara, ey Tanrı, 2 Savun beni vefasız ulusa karşı, 2 Kurtar hileci, haksız insandan.'),
(1997957,68,19,43,2,'Çünkü sen Tanrım, kalemsin; 2 Neden beni reddettin? 2 Niçin düşmanlarımın baskısı altında 2 Yaslı gezeyim?'),
(1997958,68,19,43,3,'Gönder ışığını, gerçeğini, 2 Yol göstersinler bana, 2 Senin kutsal dağına, konutuna götürsünler beni.'),
(1997959,68,19,43,4,'O zaman Tanrının sunağına, 2 Neşe, sevinç kaynağım Tanrıya gideceğim 2 Ve sana, ey Tanrı, Tanrım benim, 2 Lirle şükredeceğim.'),
(1997960,68,19,43,5,'Neden üzgünsün, ey gönlüm, 2 Neden içim huzursuz? 2 Tanrı''ya umut bağla, 2 Çünkü O''na yine övgüler sunacağım; 2 O benim kurtarıcım ve Tanrım''dır.'),
(1997961,68,19,44,1,'Ey Tanrı, kulaklarımızla duyduk, 2 Atalarımız anlattı bize, 2 Neler yaptığını onların gününde, eski günlerde.'),
(1997962,68,19,44,2,'Elinle ulusları kovdun, 2 Ama atalarımıza yer verdin; 2 Halkları kırdın, 2 Ama atalarımızın yayılmasını sağladın.'),
(1997963,68,19,44,3,'Onlar ülkeyi kılıçla kazanmadılar, 2 Kendi bilekleriyle zafere ulaşmadılar. 2 Senin sağ elin, bileğin, yüzünün ışığı sayesinde oldu bu; 2 Çünkü sen onları sevdin.'),
(1997964,68,19,44,4,'Ey Tanrı, kralım sensin, 2 Buyruk ver de Yakup soyu kazansın!'),
(1997965,68,19,44,5,'Senin sayende düşmanlarımızı püskürteceğiz, 2 Senin adınla karşıtlarımızı ezeceğiz.'),
(1997966,68,19,44,6,'Çünkü ben yayıma güvenmem, 2 Kılıcım da beni kurtarmaz;'),
(1997967,68,19,44,7,'Ancak sensin bizi düşmanlarımızdan kurtaran, 2 Bizden nefret edenleri utanca boğan.'),
(1997968,68,19,44,8,'Her gün Tanrıyla övünür, 2 Sonsuza dek adına şükran sunarız. |iSela'),
(1997969,68,19,44,9,'Ne var ki, reddettin bizi, aşağıladın, 2 Artık ordularımızla savaşa çıkmıyorsun.'),
(1997970,68,19,44,10,'Düşman karşısında bizi gerilettin, 2 Bizden tiksinenler bizi soydu.'),
(1997971,68,19,44,11,'Kasaplık koyuna çevirdin bizi, 2 Ulusların arasına dağıttın.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1997972,68,19,44,12,'Yok pahasına sattın halkını, 2 Üstelik satıştan hiçbir şey kazanmadan.'),
(1997973,68,19,44,13,'Bizi komşularımızın yüzkarası, 2 Çevremizdekilerin eğlencesi, alay konusu ettin.'),
(1997974,68,19,44,14,'Ulusların diline düşürdün bizi, 2 Gülüyor halklar halimize.'),
(1997975,68,19,44,15,'Rezilliğim gün boyu karşımda, 2 Utancımdan yerin dibine geçtim'),
(1997976,68,19,44,16,'Hakaret ve sövgü duya duya, 2 Öç almak isteyen düşman karşısında.'),
(1997977,68,19,44,17,'Bütün bunlar başımıza geldi, 2 Yine de seni unutmadık, 2 Antlaşmana ihanet etmedik,'),
(1997978,68,19,44,18,'Döneklik etmedik, 2 Adımlarımız senin yolundan sapmadı.'),
(1997979,68,19,44,19,'Oysa sen bizi ezdin, ülkemizi çakalların uğrağı ettin, 2 Üstümüzü koyu karanlıkla örttün.'),
(1997980,68,19,44,20,'Eğer Tanrımızın adını unutsaydık, 2 Yabancı bir ilaha ellerimizi açsaydık,'),
(1997981,68,19,44,21,'Tanrı bunu ortaya çıkarmaz mıydı? 2 Çünkü O yürekteki gizleri bilir.'),
(1997982,68,19,44,22,'Senin uğruna her gün öldürülüyoruz, 2 Kasaplık koyun sayılıyoruz.'),
(1997983,68,19,44,23,'Uyan, ya Rab! Niçin uyuyorsun? 2 Kalk! Sonsuza dek terk etme bizi!'),
(1997984,68,19,44,24,'Niçin yüzünü gizliyorsun? 2 Neden mazlum halimizi, üzerimizdeki baskıyı unutuyorsun?'),
(1997985,68,19,44,25,'Çünkü yere serildik, 2 Bedenimiz toprağa yapıştı.'),
(1997986,68,19,44,26,'Kalk, yardım et bize! 2 Kurtar bizi sevgin uğruna!'),
(1997987,68,19,45,1,'Yüreğimden güzel sözler taşıyor, 2 Kral için söylüyorum şiirlerimi, 2 Dilim usta bir yazarın kalemi gibi olsun.'),
(1997988,68,19,45,2,'Sen insanların en güzelisin, 2 Lütuf saçılmış dudaklarına. 2 Çünkü Tanrı seni sonsuza dek kutsamış.'),
(1997989,68,19,45,3,'Ey yiğit savaşçı, kuşan kılıcını beline, 2 Görkemine, yüceliğine bürün.'),
(1997990,68,19,45,4,'At sırtında görkeminle, zaferle ilerle, 2 Gerçek ve adalet uğruna 2 Sağ elin korkunç işler göstersin. ‹‹Gerçek ve alçakgönüllülük, adalet uğruna››.'),
(1997991,68,19,45,5,'Okların sivridir, 2 Kral düşmanlarının yüreğine saplanır, 2 Halklar ayaklarının altına serilir.'),
(1997992,68,19,45,6,'Ey Tanrı, tahtın sonsuzluklar boyunca kalıcıdırfö, 2 Krallığının asası adalet asasıdır. da ‹‹Tanrının sana armağan ettiği krallık sonsuzluklar boyunca kalıcıdır››.'),
(1997993,68,19,45,7,'Doğruluğu sever, kötülükten nefret edersin. 2 Bunun için Tanrı, senin Tanrın, 2 Seni sevinç yağıyla 2 Arkadaşlarından daha çok meshetti.'),
(1997994,68,19,45,8,'Giysilerinin tümü mür, öd, tarçın kokuyor; 2 Fildişi saraylardan gelen çalgı sesleri seni eğlendiriyor!'),
(1997995,68,19,45,9,'Kral kızları senin saygın kadınların arasında, 2 Kraliçe, Ofir altınları içinde senin sağında duruyor.'),
(1997996,68,19,45,10,'Dinle, ey kral kızı, bak, kulak ver, 2 Halkını, baba evini unut.'),
(1997997,68,19,45,11,'Kral senin güzelliğine vuruldu, 2 Efendin olduğu için önünde eğil.'),
(1997998,68,19,45,12,'Sur halkı armağan getirecek, 2 Halkın zenginleri lütfunu kazanmak isteyecek.'),
(1997999,68,19,45,13,'Kral kızı odasında ışıl ışıl parıldıyor, 2 Giysisi altınla dokunmuş.'),
(1998000,68,19,45,14,'İşlemeli giysiler içinde kralın önüne çıkarılacak, 2 Arkadaşları, ona eşlik eden kızlar sana getirilecek.'),
(1998001,68,19,45,15,'Sevinç ve coşkuyla götürülecek, 2 Kralın sarayına girecekler.'),
(1998002,68,19,45,16,'Atalarının yerini oğulların alacak, 2 Onları önder yapacaksın bütün ülkeye.'),
(1998003,68,19,45,17,'Adını kuşaklar boyunca yaşatacağım, 2 Böylece halklar sonsuza dek övecek seni.'),
(1998004,68,19,46,1,'Tanrı sığınağımız ve gücümüzdür, 2 Sıkıntıda hep yardıma hazırdır. bilinmeyen bir müzik terimi.'),
(1998005,68,19,46,2,'Bu yüzden korkmayız yeryüzü altüst olsa, 2 Dağlar denizlerin bağrına devrilse,'),
(1998006,68,19,46,3,'Sular kükreyip köpürse, 2 Kabaran deniz dağları titretse bile. |iSela'),
(1998007,68,19,46,4,'Bir ırmak var ki, suları sevinç getirir Tanrı kentine, 2 Yüceler Yücesinin kutsal konutuna.'),
(1998008,68,19,46,5,'Tanrı onun ortasındadır, 2 Sarsılmaz o kent. 2 Gün doğarken Tanrı ona yardım eder.'),
(1998009,68,19,46,6,'Uluslar kükrüyor, krallıklar sarsılıyor, 2 Tanrı gürleyince yeryüzü eriyip gidiyor.'),
(1998010,68,19,46,7,'Her Şeye Egemen RAB bizimledir, 2 Yakupun Tanrısı kalemizdir. |iSela'),
(1998011,68,19,46,8,'Gelin, görün RABbin yaptıklarını, 2 Yeryüzüne getirdiği yıkımları.'),
(1998012,68,19,46,9,'Savaşları durdurur yeryüzünün dört bucağında, 2 Yayları kırar, mızrakları parçalar, 2 Kalkanları yakar.'),
(1998013,68,19,46,10,'‹‹Sakin olun, bilin ki, Tanrı benim! 2 Uluslar arasında yüceleceğim, 2 Yeryüzünde yüceleceğim!››'),
(1998014,68,19,46,11,'Her Şeye Egemen RAB bizimledir, 2 Yakup''un Tanrısı kalemizdir. |iSela'),
(1998015,68,19,47,1,'Ey bütün uluslar, el çırpın! 2 Sevinç çığlıkları atın Tanrının onuruna!'),
(1998016,68,19,47,2,'Ne müthiştir yüce RAB, 2 Bütün dünyanın ulu Kralı.'),
(1998017,68,19,47,3,'Halkları altımıza, 2 Ulusları ayaklarımızın dibine serer.'),
(1998018,68,19,47,4,'Sevdiği Yakupun gururu olan mirasımızı 2 O seçti bizim için. |iSela'),
(1998019,68,19,47,5,'RAB Tanrı sevinç çığlıkları, 2 Boru sesleri arasında yükseldi.'),
(1998020,68,19,47,6,'Ezgiler sunun Tanrıya, ezgiler; 2 Ezgiler sunun Kralımıza, ezgiler!'),
(1998021,68,19,47,7,'Çünkü Tanrı bütün dünyanın kralıdır, 2 Maskil sunun! edebiyat terimi. ‹‹Didaktik şiir›› anlamına gelebilir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998022,68,19,47,8,'Tanrı kutsal tahtına oturmuş, 2 Krallık eder uluslara.'),
(1998023,68,19,47,9,'Ulusların önderleri 2 İbrahim''in Tanrısı''nın halkıyla bir araya gelmiş; 2 Çünkü Tanrı''ya aittir yeryüzü kralları. 2 O çok yücedir.'),
(1998024,68,19,48,1,'RAB büyüktür ve yalnız O övülmeye değer 2 Tanrımızın kentinde, kutsal dağında.'),
(1998025,68,19,48,2,'Yükselir zarafetle, 2 Bütün yeryüzünün sevinci Siyon Dağı, 2 Safonunfş doruğu, ulu Kralın kenti.'),
(1998026,68,19,48,3,'Tanrı onun kalelerinde 2 Sağlam kule olarak gösterdi kendini.'),
(1998027,68,19,48,4,'Krallar toplandı, 2 Birlikte Siyonun üzerine yürüdüler.'),
(1998028,68,19,48,5,'Ama onu görünce şaşkına döndüler, 2 Dehşete düşüp kaçtılar.'),
(1998029,68,19,48,6,'Doğum sancısı tutan kadın gibi, 2 Bir titreme aldı onları orada.'),
(1998030,68,19,48,7,'Doğu rüzgarının parçaladığı ticaret gemileri gibi 2 Yok ettin onları.'),
(1998031,68,19,48,8,'Her Şeye Egemen RABbin kentinde, 2 Tanrımızın kentinde, 2 Nasıl duyduksa, öyle gördük. 2 Tanrı onu sonsuza dek güvenlik içinde tutacak. |iSela'),
(1998032,68,19,48,9,'Ey Tanrı, tapınağında, 2 Ne kadar vefalı olduğunu düşünüyoruz.'),
(1998033,68,19,48,10,'Adın gibi, ey Tanrı, övgün de 2 Dünyanın dört bucağına varıyor. 2 Sağ elin zafer dolu.'),
(1998034,68,19,48,11,'Sevinsin Siyon Dağı, 2 Coşsun Yahuda beldeleri 2 Senin yargılarınla!'),
(1998035,68,19,48,12,'Siyonun çevresini gezip dolanın, 2 Kulelerini sayın,'),
(1998036,68,19,48,13,'Surlarına dikkatle bakın, 2 Kalelerini yoklayın ki, 2 Gelecek kuşağa anlatasınız:'),
(1998037,68,19,48,14,'Bu Tanrı sonsuza dek bizim Tanrımız olacak, 2 Bize hep yol gösterecektir.'),
(1998038,68,19,49,1,'Ey bütün halklar, dinleyin! 2 Kulak verin hepiniz, ey dünyada yaşayanlar,'),
(1998039,68,19,49,2,'Halk çocukları, bey çocukları, 2 Zenginler, yoksullar!'),
(1998040,68,19,49,3,'Bilgelik dökülecek ağzımdan, 2 Anlayış sağlayacak içimdeki düşünceler,'),
(1998041,68,19,49,4,'Kulak vereceğim özdeyişlere, 2 Lirle yorumlayacağım bilmecemi.'),
(1998042,68,19,49,5,'Niçin korkayım kötü günlerde 2 Niyeti bozuk düşmanlarım çevremi sarınca?'),
(1998043,68,19,49,6,'Onlar varlıklarına güvenir, 2 Büyük servetleriyle böbürlenirler.'),
(1998044,68,19,49,7,'Kimse kimsenin hayatının bedelini ödeyemez, 2 Tanrıya fidye veremez.'),
(1998045,68,19,49,8,'Çünkü hayatın fidyesi büyüktür, 2 Kimse ödemeye yeltenmemeli.'),
(1998046,68,19,49,9,'Böyle olmasa, 2 Sonsuza dek yaşar insan, 2 Mezar yüzü görmez.'),
(1998047,68,19,49,10,'Kuşkusuz herkes biliyor bilgelerin öldüğünü, 2 Aptallarla budalaların yok olduğunu. 2 Mallarını başkalarına bırakıyorlar.'),
(1998048,68,19,49,11,'Mezarları, sonsuza dek evleri, 2 Kuşaklar boyu konutları olacak, 2 Topraklarına kendi adlarını verseler bile. evleri, kuşaklar boyu konutları olacak››, Masoretik metin ‹‹ ‹Evlerimiz sonsuza dek kalacak› diye düşünüyorlar››.'),
(1998049,68,19,49,12,'Bütün gösterişine karşın geçicidir insan, 2 Ölüp giden hayvanlar gibi.'),
(1998050,68,19,49,13,'Budalaların yolu, 2 Onların sözünü onaylayanların sonu budur. |iSela'),
(1998051,68,19,49,14,'Sürü gibi ölüler diyarına sürülecekler, 2 Ölüm güdecek onları. 2 Tan ağarınca doğrular onlara egemen olacak, 2 Cesetleri çürüyecek, 2 Ölüler diyarı onlara konut olacak.'),
(1998052,68,19,49,15,'Ama Tanrı beni 2 Ölüler diyarının pençesinden kurtaracak 2 Ve yanına alacak. |iSela'),
(1998053,68,19,49,16,'Korkma biri zenginleşirse, 2 Evinin görkemi artarsa.'),
(1998054,68,19,49,17,'Çünkü ölünce hiçbir şey götüremez, 2 Görkemi onunla mezara gitmez.'),
(1998055,68,19,49,18,'Yaşarken kendini mutlu saysa bile, 2 Başarılı olunca övülse bile.'),
(1998056,68,19,49,19,'Atalarının kuşağına katılacak, 2 Onlar ki asla ışık yüzü görmeyecekler.'),
(1998057,68,19,49,20,'Bütün gösterişine karşın anlayışsızdır insan, 2 Ölüp giden hayvanlar gibi.'),
(1998058,68,19,50,1,'Güçlü olan Tanrı, RAB konuşuyor; 2 Güneşin doğduğu yerden battığı yere kadar 2 Yeryüzünün tümüne sesleniyor.'),
(1998059,68,19,50,2,'Güzelliğin doruğu Siyondan 2 Parıldıyor Tanrı.'),
(1998060,68,19,50,3,'Tanrımız geliyor, sessiz kalmayacak, 2 Önünde yanan ateş her şeyi kül ediyor, 2 Çevresinde şiddetli bir fırtına esiyor.'),
(1998061,68,19,50,4,'Halkını yargılamak için 2 Yere göğe sesleniyor:'),
(1998062,68,19,50,5,'‹‹Toplayın önüme sadık kullarımı, 2 Kurban keserek benimle antlaşma yapanları.››'),
(1998063,68,19,50,6,'Gökler Onun doğruluğunu duyuruyor, 2 Çünkü yargıç Tanrının kendisidir. |iSela'),
(1998064,68,19,50,7,'‹‹Ey halkım, dinle de konuşayım, 2 Ey İsrail, sana karşı tanıklık edeyim: 2 Ben Tanrıyım, senin Tanrınım!'),
(1998065,68,19,50,8,'Kurbanlarından ötürü seni azarlamıyorum, 2 Yakmalık sunuların sürekli önümde.'),
(1998066,68,19,50,9,'Ne evinden bir boğa, 2 Ne de ağıllarından bir teke alacağım.'),
(1998067,68,19,50,10,'Çünkü bütün orman yaratıkları, 2 Dağlardaki bütün hayvanlar benimdir.'),
(1998068,68,19,50,11,'Dağlardaki bütün kuşları korurum, 2 Kırlardaki bütün yabanıl hayvanlar benimdir.'),
(1998069,68,19,50,12,'Acıksam sana söylemezdim, 2 Çünkü bütün dünya ve içindekiler benimdir.'),
(1998070,68,19,50,13,'Ben boğa eti yer miyim? 2 Ya da keçi kanı içer miyim?'),
(1998071,68,19,50,14,'Tanrıya şükran kurbanı sun, 2 Yüceler Yücesine adadığın adakları yerine getir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998072,68,19,50,15,'Sıkıntılı gününde seslen bana, 2 Seni kurtarırım, sen de beni yüceltirsin.'),
(1998073,68,19,50,16,'Ama Tanrı kötüye şöyle diyor: 2 ‹‹Kurallarımı ezbere okumaya 2 Ya da antlaşmamı ağzına almaya ne hakkın var?'),
(1998074,68,19,50,17,'Çünkü yola getirilmekten nefret ediyor, 2 Sözlerimi arkana atıyorsun.'),
(1998075,68,19,50,18,'Hırsız görünce onunla dost oluyor, 2 Zina edenlere ortak oluyorsun.'),
(1998076,68,19,50,19,'Ağzını kötülük için kullanıyor, 2 Dilini yalana koşuyorsun.'),
(1998077,68,19,50,20,'Oturup kardeşine karşı konuşur, 2 Annenin oğluna kara çalarsın.'),
(1998078,68,19,50,21,'Sen bunları yaptın, ben sustum, 2 Beni kendin gibi sandın. 2 Seni azarlıyorum, 2 Suçlarını gözünün önüne seriyorum.'),
(1998079,68,19,50,22,'‹‹Dikkate alın bunu, ey Tanrıyı unutan sizler! 2 Yoksa parçalarım sizi, kurtaran olmaz.'),
(1998080,68,19,50,23,'Kim şükran kurbanı sunarsa beni yüceltir; 2 Yolunu düzeltene kurtarışımı göstereceğim.››'),
(1998081,68,19,51,1,'Ey Tanrı, lütfet bana, 2 Sevgin uğruna; 2 Sil isyanlarımı, 2 Sınırsız merhametin uğruna.'),
(1998082,68,19,51,2,'Tümüyle yıka beni suçumdan, 2 Arıt beni günahımdan.'),
(1998083,68,19,51,3,'Çünkü biliyorum isyanlarımı, 2 Günahım sürekli karşımda.'),
(1998084,68,19,51,4,'Sana karşı, yalnız sana karşı günah işledim, 2 Senin gözünde kötü olanı yaptım. 2 Öyle ki, konuşurken haklı, 2 Yargılarken adil olasın.'),
(1998085,68,19,51,5,'Nitekim suç içinde doğdum ben, 2 Günah içinde annem bana hamile kaldı.'),
(1998086,68,19,51,6,'Madem sen gönülde sadakat istiyorsun, 2 Bilgelik öğret bana yüreğimin derinliklerinde.'),
(1998087,68,19,51,7,'Beni mercanköşkotuyla arıt, paklanayım, 2 Yıka beni, kardan beyaz olayım.'),
(1998088,68,19,51,8,'Neşe, sevinç sesini duyur bana, 2 Bayram etsin ezdiğin kemikler.'),
(1998089,68,19,51,9,'Bakma günahlarıma, 2 Sil bütün suçlarımı.'),
(1998090,68,19,51,10,'Ey Tanrı, temiz bir yürek yarat, 2 Yeniden kararlı bir ruh var et içimde.'),
(1998091,68,19,51,11,'Beni huzurundan atma, 2 Kutsal Ruhunu benden alma.'),
(1998092,68,19,51,12,'Geri ver bana sağladığın kurtuluş sevincini, 2 Bana destek ol, istekli bir ruh ver.'),
(1998093,68,19,51,13,'Başkaldıranlara senin yollarını öğreteyim, 2 Günahkârlar geri dönsün sana.'),
(1998094,68,19,51,14,'Kurtar beni kan dökme suçundan, 2 Ey Tanrı, beni kurtaran Tanrı, 2 Dilim senin kurtarışını ilahilerle övsün.'),
(1998095,68,19,51,15,'Ya Rab, aç dudaklarımı, 2 Ağzım senin övgülerini duyursun.'),
(1998096,68,19,51,16,'Çünkü sen kurbandan hoşlanmazsın, 2 Yoksa sunardım sana, 2 Yakmalık sunudan hoşnut kalmazsın.'),
(1998097,68,19,51,17,'Senin kabul ettiğin kurban alçakgönüllü bir ruhtur, 2 Alçakgönüllü ve pişman bir yüreği hor görmezsin, ey Tanrı.'),
(1998098,68,19,51,18,'Lütfet, Siyona iyilik yap, 2 Yeruşalimin surlarını onar.'),
(1998099,68,19,51,19,'O zaman doğru sunulan kurbanlar, 2 Yakmalık sunular, tümüyle yakmalık sunular, 2 Seni hoşnut kılar; 2 O zaman sunağında boğalar sunulur.'),
(1998100,68,19,52,1,'Niçin kötülüğünle böbürlenirsin, ey kabadayı, 2 Tanrının sadık kullarına karşı 2 Bütün gün dilin yıkım tasarlar 2 Keskin ustura gibi, ey hilekâr.'),
(1998101,68,19,52,3,'İyilikten çok kötülüğü, 2 Doğru konuşmaktan çok yalanı seversin. |iSela'),
(1998102,68,19,52,4,'Seni hileli dil seni! 2 Her yıkıcı sözü seversin.'),
(1998103,68,19,52,5,'Ama Tanrı seni sonsuza dek yıkacak, 2 Seni kapıp çadırından fırlatacak, 2 Yaşam diyarından kökünü sökecek. |iSela'),
(1998104,68,19,52,6,'Doğrular bunu görünce korkacak, 2 Gülerek şöyle diyecekler:'),
(1998105,68,19,52,7,'‹‹İşte bu adam, Tanrıya sığınmak istemedi, 2 Servetinin bolluğuna güvendi, 2 Başkalarını yıkarak güçlendi!››'),
(1998106,68,19,52,8,'Ama ben Tanrının evinde yeşeren zeytin ağacı gibiyim, 2 Sonsuza dek Tanrının sevgisine güvenirim.'),
(1998107,68,19,52,9,'Sürekli sana şükrederim yaptıkların için, 2 Sadık kullarının önünde umut bağlarım, 2 Çünkü adın iyidir.'),
(1998108,68,19,53,1,'Akılsız içinden, ‹‹Tanrı yok!›› der. 2 İnsanlar bozuldu, iğrençlik aldı yürüdü, 2 İyilik eden yok. sazlar››.'),
(1998109,68,19,53,2,'Tanrı göklerden bakar oldu insanlara, 2 Akıllı, Tanrıya yönelen biri var mı diye.'),
(1998110,68,19,53,3,'Hepsi saptı, 2 Tümü yozlaştı, 2 İyilik eden yok, 2 Bir kişi bile!'),
(1998111,68,19,53,4,'Suç işleyenler görmüyor mu? 2 Halkımı ekmek yer gibi yiyor, 2 Tanrıya yakarmıyorlar.'),
(1998112,68,19,53,5,'Ama korkulmayacak yerde korkacaklar, 2 Çünkü Tanrı seni kuşatanların kemiklerini dağıtacak, 2 Onları reddettiği için hepsini utandıracak.'),
(1998113,68,19,53,6,'Keşke İsrail''in kurtuluşu Siyon''dan gelse! 2 Tanrı halkını eski gönencine kavuşturunca, 2 Yakup soyu sevinecek, İsrail halkı coşacak.'),
(1998114,68,19,54,1,'Ey Tanrı, beni adınla kurtar, 2 Gücünle akla beni!'),
(1998115,68,19,54,2,'Ey Tanrı, duamı dinle, 2 Kulak ver ağzımdan çıkan sözlere.'),
(1998116,68,19,54,3,'Çünkü küstahlar bana saldırıyor, 2 Zorbalar canımı almak istiyor, 2 Tanrıya aldırmıyorlar. |iSela'),
(1998117,68,19,54,4,'İşte Tanrı benim yardımcımdır, 2 Tek desteğim Rabdir.'),
(1998118,68,19,54,5,'Düşmanlarım yaptıkları kötülüğün cezasını bulsun, 2 Sadakatin uyarınca yok et onları.'),
(1998119,68,19,54,6,'Ya RAB, sana gönülden bir kurban sunacağım, 2 Adına şükredeceğim, çünkü adın iyidir.'),
(1998120,68,19,54,7,'Beni bütün sıkıntılarımdan kurtardın, 2 Gözlerim düşmanlarımın yok oluşunu gördü.'),
(1998121,68,19,55,1,'Ey Tanrı, kulak ver duama, 2 Sırt çevirme yalvarışıma!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998122,68,19,55,2,'Dikkatini çevir, yanıt ver bana. 2 Düşüncelerim beni rahatsız ediyor, şaşkınım'),
(1998123,68,19,55,3,'Düşman sesinden, kötünün baskısından; 2 Çünkü sıkıntıya sokuyorlar beni, 2 Öfkeyle üstüme üstüme geliyorlar.'),
(1998124,68,19,55,4,'Yüreğim sızlıyor içimde, 2 Ölüm dehşeti çöktü üzerime.'),
(1998125,68,19,55,5,'Korku ve titreme sardı beni, 2 Ürperti kapladı içimi.'),
(1998126,68,19,55,6,'‹‹Keşke güvercin gibi kanatlarım olsaydı!›› 2 Dedim kendi kendime, ‹‹Uçar, rahatlardım.'),
(1998127,68,19,55,7,'Uzaklara kaçar, 2 Çöllerde konaklardım. |iSela'),
(1998128,68,19,55,8,'Sert rüzgara, kasırgaya karşı 2 Hemen bir barınak bulurdum.››'),
(1998129,68,19,55,9,'Şaşkına çevir kötüleri, ya Rab, karışt��r dillerini, 2 Çünkü kentte şiddet ve çatışma görüyorum.'),
(1998130,68,19,55,10,'Gece gündüz kent surları üzerinde dolaşırlar, 2 Haksızlık, fesat dolu kentin içi.'),
(1998131,68,19,55,11,'Yıkıcılık kentin göbeğinde, 2 Zorbalık, hile eksilmez meydanından.'),
(1998132,68,19,55,12,'Beni aşağılayan bir düşman olsaydı, 2 Katlanabilirdim; 2 Bana küstahlık eden bir hasım olsaydı, 2 Gizlenebilirdim.'),
(1998133,68,19,55,13,'Ama sensin, bana denk, 2 Yoldaşım, yakın arkadaşım.'),
(1998134,68,19,55,14,'Birlikte tatlı tatlı yarenlik eder, 2 Toplulukla Tanrının evine giderdik.'),
(1998135,68,19,55,15,'Ölüm yakalasın düşmanlarımı ansızın, 2 Diri diri ölüler diyarına insinler; 2 Çünkü içleri ve evleri kötülük dolu.'),
(1998136,68,19,55,16,'Bense Tanrıya seslenirim, 2 RAB kurtarır beni.'),
(1998137,68,19,55,17,'Sabah, öğlen, akşam kederimden feryat ederim, 2 O işitir sesimi.'),
(1998138,68,19,55,18,'Bana karşı girişilen savaştan 2 Esenlikle kurtarır canımı, 2 Sayısı çok da olsa karşıtlarımın.'),
(1998139,68,19,55,19,'Öncesizlikten bu yana tahtında oturan Tanrı, 2 Duyacak ve ezecek onları. |iSela 2 Çünkü hiç değişmiyor 2 Ve Tanrıdan korkmuyorlar.'),
(1998140,68,19,55,20,'Yoldaşım dostlarına saldırarak 2 Yaptığı antlaşmayı bozdu.'),
(1998141,68,19,55,21,'Ağzından bal damlar, 2 Ama yüreğinde savaş var. 2 Sözleri yağdan yumuşak, 2 Ama yalın birer kılıçtır.'),
(1998142,68,19,55,22,'Yükünü RABbe bırak, 2 O sana destek olur. 2 Asla izin vermez 2 Doğru insanın sarsılmasına.'),
(1998143,68,19,55,23,'Ama sen, ey Tanrı, ölüm çukuruna atacaksın kötüleri, 2 Günlerinin yarısını görmeyecek katillerle hainler; 2 Bense sana güveniyorum.'),
(1998144,68,19,56,1,'Acı bana, ey Tanrı, 2 Çünkü ayak altında çiğniyor insanlar beni, 2 Gün boyu saldırıp eziyorlar.'),
(1998145,68,19,56,2,'Düşmanlarım ayak altında çiğniyor beni her gün, 2 Küstahça saldırıyor çoğu.'),
(1998146,68,19,56,3,'Sana güvenirim korktuğum zaman.'),
(1998147,68,19,56,4,'Tanrıya, sözünü övdüğüm Tanrıya 2 Güvenirim ben, korkmam. 2 İnsan bana ne yapabilir?'),
(1998148,68,19,56,5,'Gün boyu sözlerimi çarpıtıyorlar, 2 Hakkımda hep kötülük tasarlıyorlar.'),
(1998149,68,19,56,6,'Fesatlık için uğraşıyor, pusuya yatıyor, 2 Adımlarımı gözlüyor, canımı almak istiyorlar.'),
(1998150,68,19,56,7,'Kötülüklerinin cezasından kurtulacaklar mı? 2 Ey Tanrı, halkları öfkeyle yere çal!'),
(1998151,68,19,56,8,'Çektiğim acıları kaydettin, 2 Gözyaşlarımı tulumunda biriktirdin! 2 Bunlar defterinde yazılı değil mi?'),
(1998152,68,19,56,9,'Seslendiğim zaman, 2 Düşmanlarım geri çekilecek. Biliyorum, Tanrı benden yana.'),
(1998153,68,19,56,10,'Sözünü övdüğüm Tanrıya, 2 Sözünü övdüğüm RABbe,'),
(1998154,68,19,56,11,'Tanrıya güvenirim ben, korkmam; 2 İnsan bana ne yapabilir?'),
(1998155,68,19,56,12,'Ey Tanrı, sana adaklar adamıştım, 2 Şükran kurbanları sunmalıyım şimdi.'),
(1998156,68,19,56,13,'Çünkü canımı ölümden kurtardın, 2 Ayaklarımı tökezlemekten korudun; 2 İşte yaşam ışığında, Tanrı huzurunda yürüyorum.'),
(1998157,68,19,57,1,'Acı bana, ey Tanrı, acı, 2 Çünkü sana sığınıyorum; 2 Felaket geçinceye kadar, 2 Kanatlarının gölgesine sığınacağım.'),
(1998158,68,19,57,2,'Yüce Tanrıya, 2 Benim için her şeyi yapan Tanrıya sesleniyorum.'),
(1998159,68,19,57,3,'Gökten gönderip beni kurtaracak, 2 Beni ezmek isteyenleri azarlayacak, |iSela 2 Sevgisini, sadakatini gösterecektir.'),
(1998160,68,19,57,4,'Aslanların arasındayım, 2 Alev kusan insanlar arasında yatarım, 2 Mızrak gibi, ok gibi dişleri, 2 Keskin kılıç gibi dilleri.'),
(1998161,68,19,57,5,'Yüceliğini göster göklerin üstünde, ey Tanrı, 2 Görkemin bütün yeryüzünü kaplasın!'),
(1998162,68,19,57,6,'Ayaklarım için ağ serdiler, 2 Çöktüm; 2 Yoluma çukur kazdılar, 2 İçine kendileri düştüler. |iSela'),
(1998163,68,19,57,7,'Kararlıyım, ey Tanrı, kararlıyım, 2 Ezgiler, ilahiler söyleyeceğim.'),
(1998164,68,19,57,8,'Uyan, ey canım, 2 Uyan, ey lir, ey çenk, 2 Seheri ben uyandırayım!'),
(1998165,68,19,57,9,'Halkların arasında sana şükürler sunayım, ya Rab, 2 Ulusların arasında seni ilahilerle öveyim.'),
(1998166,68,19,57,10,'Çünkü sevgin göklere erişir, 2 Sadakatin gökyüzüne ulaşır.'),
(1998167,68,19,57,11,'Yüceliğini göster göklerin üstünde, ey Tanrı, 2 Görkemin bütün yeryüzünü kaplasın!'),
(1998168,68,19,58,1,'Ey yöneticilerfü, gerçekten adil mi karar verirsiniz? 2 Doğru mu yargılarsınız insanları?'),
(1998169,68,19,58,2,'Hayır! Hep haksızlık tasarlarsınız içinizde, 2 Zorbalık saçar elleriniz yeryüzüne.'),
(1998170,68,19,58,3,'Kötüler daha ana rahmindeyken yoldan çıkar, 2 Doğdu doğalı yalan söyleyerek sapar.'),
(1998171,68,19,58,4,'Zehirleri yılan zehiri gibidir. 2 Kulakları tıkalı bir kobrayı andırırlar,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998172,68,19,58,5,'Usta büyücülerin, 2 Afsuncuların sesini duymak istemeyen bir kobrayı.'),
(1998173,68,19,58,6,'Ey Tanrı, kır onların ağzında dişlerini, 2 Sök genç aslanların azı dişlerini, ya RAB!'),
(1998174,68,19,58,7,'Akıp giden su gibi yok olsunlar. 2 Yaylarını gerince oklarının ucu kırılsın.'),
(1998175,68,19,58,8,'Süründükçe eriyen sümüklüböceğe dönsünler. 2 Düşük çocuk gibi güneş yüzü görmesinler.'),
(1998176,68,19,58,9,'Kazanlarınız diken ateşini daha duymadan, 2 Yaşı da kurusu da kasırgayla savrulacak kötülerin.'),
(1998177,68,19,58,10,'Doğru adam alınan öcü görünce sevinecek 2 Ve ayaklarını kötünün kanında yıkayacak.'),
(1998178,68,19,58,11,'O zaman insanlar, ‹‹Gerçekten doğrulara ödül var›› diyecek, 2 ‹‹Gerçekten dünyayı yargılayan bir Tanrı var.››'),
(1998179,68,19,59,1,'Kurtar beni düşmanlarımdan, ey Tanrım, 2 Kalem ol hasımlarıma karşı.'),
(1998180,68,19,59,2,'Kurtar beni suç işleyenlerden, 2 Uzak tut kanlı katillerden.'),
(1998181,68,19,59,3,'Bak, canımı almak için pusu kuruyorlar, 2 Güçlüler bana karşı birleşiyorlar, 2 Oysa başkaldırmadım, günahım yok, ya RAB.'),
(1998182,68,19,59,4,'Suç işlemediğim halde, 2 Koşuşup hazırlanıyorlar. 2 Kalk bana yardım etmek için, halime bak!'),
(1998183,68,19,59,5,'Sen, ya RAB, Her Şeye Egemen Tanrı, 2 İsrailin Tanrısı, 2 Uyan bütün ulusları cezalandırmak için, 2 Acıma bu suçlu hainlere! |iSela'),
(1998184,68,19,59,6,'Akşam döner, köpek gibi hırlayıp 2 Sinsi sinsi kenti dolaşırlar.'),
(1998185,68,19,59,7,'Bak, neler dökülür ağızlarından, 2 Kılıç çıkar dudaklarından. 2 ‹‹Kim duyacak?›› derler.'),
(1998186,68,19,59,8,'Ama sen onlara gülersin, ya RAB, 2 Bütün uluslarla eğlenirsin.'),
(1998187,68,19,59,9,'Gücüm sensin, seni gözlüyorum, 2 Çünkü kalemsin, ey Tanrı.'),
(1998188,68,19,59,10,'Tanrım sevgisiyle karşılar beni, 2 Bana düşmanlarımın yıkımını gösterir.'),
(1998189,68,19,59,11,'Onları öldürme, yoksa halkım unutur, 2 Gücünle dağıt ve alçalt onları, 2 Ya Rab, kalkanımız bizim.'),
(1998190,68,19,59,12,'Ağızlarının günahı, dudaklarından çıkan söz yüzünden, 2 Gururlarının tuzağına düşsünler. 2 Okudukları lanet, söyledikleri yalan yüzünden'),
(1998191,68,19,59,13,'Yok et onları gazabınla, yok et, tükensinler; 2 Bilsinler ki, Tanrının egemenliği Yakup soyundan 2 Yeryüzünün ucuna kadar ulaşır. |iSela'),
(1998192,68,19,59,14,'Akşam döner, köpek gibi hırlayıp 2 Sinsi sinsi kenti dolaşırlar.'),
(1998193,68,19,59,15,'Yiyecek bulmak için gezerler, 2 Doymazlarsa ulurlar.'),
(1998194,68,19,59,16,'Bense gücün için sabah ezgiler söyleyecek, 2 Sevgini sevinçle dile getireceğim. 2 Çünkü sen bana kale, 2 Sıkıntılı günümde sığınak oldun.'),
(1998195,68,19,59,17,'Gücüm sensin, seni ilahilerle öveceğim, 2 Çünkü kalem, beni seven Tanrı sensin.'),
(1998196,68,19,60,1,'Bizi reddettin, parladın bize karşı, ey Tanrı, 2 Öfkelendin; eski halimize döndür bizi!'),
(1998197,68,19,60,2,'Salladın yeri, yarıklar açtın; 2 Onar çatlaklarını, çünkü yer sarsılıyor.'),
(1998198,68,19,60,3,'Halkına sıkıntı çektirdin, 2 Sersemletici bir şarap içirdin bize.'),
(1998199,68,19,60,4,'Sancak verdin senden korkanlara, 2 Okçulara karşı açsınlar diye. |iSela'),
(1998200,68,19,60,5,'Kurtar bizi sağ elinle, yardım et, 2 Sevdiklerin özgürlüğe kavuşsun diye!'),
(1998201,68,19,60,6,'Tanrı şöyle konuştu kutsal yerinde: 2 ‹‹Şekemi sevinçle bölüştürecek, 2 Sukkot Vadisini ölçeceğim.'),
(1998202,68,19,60,7,'Gilat benimdir, Manaşşe de benim, 2 Efrayim miğferim, 2 Yahuda asam.'),
(1998203,68,19,60,8,'Moav yıkanma leğenim, 2 Edomun üzerine çarığımı fırlatacağım, 2 Filiste zaferle haykıracağım.›› fırlatılması, bir yerin sahiplenilmesi anlamına geliyordu.'),
(1998204,68,19,60,9,'Kim beni surlu kente götürecek? 2 Kim bana Edoma kadar yol gösterecek?'),
(1998205,68,19,60,10,'Ey Tanrı, sen bizi reddetmedin mi? 2 Ordularımıza öncülük etmiyor musun artık?'),
(1998206,68,19,60,11,'Yardım et bize düşmana karşı, 2 Çünkü boştur insan yardımı.'),
(1998207,68,19,60,12,'Tanrı''yla zafer kazanırız, 2 O çiğner düşmanlarımızı.'),
(1998208,68,19,61,1,'Ey Tanrı, yakarışımı işit, 2 Duama kulak ver!'),
(1998209,68,19,61,2,'Sana seslenirim yeryüzünün öbür ucundan, 2 Yüreğime hüzün çökünce. Erişemeyeceğim yüksek bir kayaya çıkar beni,'),
(1998210,68,19,61,3,'Çünkü sen benim için sığınak, 2 Düşmana karşı güçlü bir kule oldun.'),
(1998211,68,19,61,4,'Çadırında sonsuza dek oturmak 2 Ve kanatlarının gölgesine sığınmak isterim. |iSela'),
(1998212,68,19,61,5,'Çünkü sen, ey Tanrı, adaklarımı duydun, 2 Adından korkanların mirasını bana verdin.'),
(1998213,68,19,61,6,'Kralın günlerine gün kat, 2 Yılları yüzyıllar olsun!'),
(1998214,68,19,61,7,'Tanrının huzurunda sonsuza dek tahtında otursun; 2 Onu sevgin ve sadakatinle koru!'),
(1998215,68,19,61,8,'O zaman adını hep ilahilerle öveceğim, 2 Her gün adaklarımı yerine getireceğim.'),
(1998216,68,19,62,1,'Canım yalnız Tanrıda huzur bulur, 2 Kurtuluşum Ondan gelir.'),
(1998217,68,19,62,2,'Tek kayam, kurtuluşum, 2 Kalem Odur, asla sarsılmam.'),
(1998218,68,19,62,3,'Birini ezmek için daha ne vakte kadar 2 Hep birlikte üstüne saldıracaksınız, 2 Eğri bir duvara, 2 Yerinden oynamış bir çite saldırır gibi?'),
(1998219,68,19,62,4,'Tek düşünceleri onu doruktan indirmektir. 2 Yalandan zevk alırlar. 2 Ağızlarıyla hayırdua ederken, 2 İçlerinden lanet okurlar. |iSela'),
(1998220,68,19,62,5,'Ey canım, yalnız Tanrıda huzur bul, 2 Çünkü umudum Ondadır.'),
(1998221,68,19,62,6,'Tek kayam, kurtuluşum, 2 Kalem Odur, sarsılmam.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998222,68,19,62,7,'Kurtuluşum ve onurum Tanrıya bağlıdır, 2 Güçlü kayam, sığınağım Odur.'),
(1998223,68,19,62,8,'Ey halkım, her zaman Ona güven, 2 İçini dök Ona, 2 Çünkü Tanrı sığınağımızdır. |iSela'),
(1998224,68,19,62,9,'Sıradan insan ancak bir soluk, 2 Soylu insansa bir yalandır. 2 Tartıya konduğunda ikisi birlikte soluktan hafiftir.'),
(1998225,68,19,62,10,'Zorbalığa güvenmeyin, yağma malla övünmeyin; 2 Varlığınız artsa bile, ona gönül bağlamayın.'),
(1998226,68,19,62,11,'Tanrı bir şey söyledi, 2 Ben iki şey duydum: 2 Güç Tanrınındır,'),
(1998227,68,19,62,12,'Sevgi de senin, ya Rab! 2 Çünkü sen herkese, yaptığının karşılığını verirsin.'),
(1998228,68,19,63,1,'Ey Tanrı, sensin benim Tanrım, 2 Seni çok özlüyorum, 2 Canım sana susamış, 2 Kurak, yorucu, susuz bir diyarda, 2 Bütün varlığımla seni arıyorum.'),
(1998229,68,19,63,2,'Kutsal yerde baktım sana, 2 Gücünü, görkemini görmek için.'),
(1998230,68,19,63,3,'Senin sevgin yaşamdan iyidir, 2 Bu yüzden dudaklarım seni yüceltir.'),
(1998231,68,19,63,4,'Ömrümce sana övgüler sunacağım, 2 Senin adınla ellerimi kaldıracağım.'),
(1998232,68,19,63,5,'Zengin yiyeceklere doyarcasına doyacağım sana, 2 Şakıyan dudaklarla ağzım sana övgüler sunacak.'),
(1998233,68,19,63,6,'Yatağıma uzanınca seni anarım, 2 Gece boyunca derin derin seni düşünürüm.'),
(1998234,68,19,63,7,'Çünkü sen bana yardımcı oldun, 2 Kanatlarının gölgesinde sevincimi dile getiririm.'),
(1998235,68,19,63,8,'Canım sana sımsıkı sarılır, 2 Sağ elin bana destek olur.'),
(1998236,68,19,63,9,'Ama canımı almak isteyenler, 2 Yerin derinliklerine inecek,'),
(1998237,68,19,63,10,'Kılıcın ağzına atılacak, 2 Çakallara yem olacak.'),
(1998238,68,19,63,11,'Kralsa Tanrı''da sevinç bulacak. 2 Tanrı''nın adıyla ant içenlerin hepsi övünecek, 2 Yalancıların ağzıysa kapanacak.'),
(1998239,68,19,64,1,'Ey Tanrı, kulak ver sesime yakındığım zaman, 2 Hayatımı düşman korkusundan koru.'),
(1998240,68,19,64,2,'Kötülerin gizli tasarılarından, 2 O suçlu güruhun şamatasından esirge beni.'),
(1998241,68,19,64,3,'Onlar dillerini kılıç gibi bilemiş, 2 Acı sözlerini ok gibi hedefe yöneltmişler,'),
(1998242,68,19,64,4,'Pusularından masum insanın üzerine atmak için. 2 Ansızın vururlar, hiç çekinmeden.'),
(1998243,68,19,64,5,'Birbirlerini kötülük yapmaya iter, 2 Gizli tuzaklar tasarlarken, 2 ‹‹Kim görecek?›› derler.'),
(1998244,68,19,64,6,'Haksızlık yapmayı düşünür, 2 ‹‹Kusursuz bir plan yaptık!›› derler. 2 İnsanın içi ve yüreği derin bir sırdır, bilinmez.'),
(1998245,68,19,64,7,'Ama Tanrı onlara ok atacak, 2 Ansızın yaralanacaklar.'),
(1998246,68,19,64,8,'Dilleri yüzünden yıkıma uğrayacaklar, 2 Hallerini gören herkes alayla baş sallayacak.'),
(1998247,68,19,64,9,'Bütün insanlar korkuya kapılacak, 2 Tanrının işini duyuracak, 2 Onun yaptıkları üzerinde düşünecekler.'),
(1998248,68,19,64,10,'Doğru insan RAB''de sevinç bulacak, 2 O''na sığınacak, 2 Bütün temiz yürekliler O''nu övecek.'),
(1998249,68,19,65,1,'Ey Tanrı, Siyonda seni övgü bekliyor, 2 Yerine getirilecek sana adanan adaklar. Masoretik metin ‹‹Senin için sessizlik övgü››.'),
(1998250,68,19,65,2,'Ey sen, duaları işiten, 2 Bütün insanlar sana gelecek.'),
(1998251,68,19,65,3,'Suçlarımızın altında ezildik, 2 Ama sen isyanlarımızı bağışlarsın.'),
(1998252,68,19,65,4,'Ne mutlu avlularında otursun diye 2 Seçip kendine yaklaştırdığın kişiye! 2 Evinin, kutsal tapınağının 2 Nimetlerine doyacağız.'),
(1998253,68,19,65,5,'Ey bizi kurtaran Tanrı, 2 Müthiş işler yaparak 2 Zaferle yanıtlarsın bizi. 2 Sen yeryüzünün dört bucağında, 2 Uzak denizlerdekilerin umudusun;'),
(1998254,68,19,65,6,'Kudret kuşanan, 2 Gücüyle dağları kuran,'),
(1998255,68,19,65,7,'Denizlerin kükremesini, 2 Dalgaların gümbürtüsünü, 2 Halkların kargaşasını yatıştıran sensin.'),
(1998256,68,19,65,8,'Dünyanın öbür ucunda yaşayanlar 2 Korkuya kapılır senin belirtilerin karşısında. 2 Doğudan batıya kadar insanlara 2 Sevinç çığlıkları attırırsın.'),
(1998257,68,19,65,9,'Toprağa bakar, çok verimli kılarsın, 2 Onu zenginliğe boğarsın. 2 Ey Tanrı, ırmakların suyla doludur, 2 İnsanlara tahıl sağlarsın, 2 Çünkü sen toprağı şöyle hazırlarsın:'),
(1998258,68,19,65,10,'Sabanın açtığı yarıkları bolca sular, 2 Sırtlarını düzlersin. 2 Yağmurla toprağı yumuşatır, 2 Ürünlerine bereket katarsın.'),
(1998259,68,19,65,11,'İyiliklerinle yılı taçlandırırsın, 2 Arabalarının geçtiği yollardan bolluk akar,'),
(1998260,68,19,65,12,'Otlaklar yeşillenir, 2 Tepeler sevince bürünür,'),
(1998261,68,19,65,13,'Çayırlar sürülerle bezenir, 2 Vadiler ekinle örtünür, 2 Sevinçten haykırır, ezgi söylerler.'),
(1998262,68,19,66,1,'Ey yeryüzündeki bütün insanlar, 2 Tanrıya sevinç çığlıkları atın!'),
(1998263,68,19,66,2,'Adının yüceliğine ilahiler söyleyin, 2 Ona görkemli övgüler sunun!'),
(1998264,68,19,66,3,'‹‹Ne müthiş işlerin var!›› deyin Tanrıya, 2 ‹‹Öyle büyük gücün var ki, 2 Düşmanların eğiliyor önünde.'),
(1998265,68,19,66,4,'Bütün yeryüzü sana tapınıyor, 2 İlahiler okuyor, adını ilahilerle övüyor.›› |iSela'),
(1998266,68,19,66,5,'Gelin, bakın Tanrının neler yaptığına! 2 Ne müthiş işler yaptı insanlar arasında:'),
(1998267,68,19,66,6,'Denizi karaya çevirdi, 2 Atalarımız yaya geçtiler ırmaktan. 2 Yaptığına sevindik orada.'),
(1998268,68,19,66,7,'Kudretiyle sonsuza dek egemenlik sürer, 2 Gözleri ulusları süzer; 2 Başkaldıranlar gurura kapılmasın! |iSela'),
(1998269,68,19,66,8,'Ey halklar, Tanrımıza şükredin, 2 Övgülerini duyurun.'),
(1998270,68,19,66,9,'Hayatımızı koruyan, 2 Ayaklarımızın kaymasına izin vermeyen Odur.'),
(1998271,68,19,66,10,'Sen bizi sınadın, ey Tanrı, 2 Gümüş arıtır gibi arıttın.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998272,68,19,66,11,'Ağa düşürdün bizi, 2 Sırtımıza ağır yük vurdun.'),
(1998273,68,19,66,12,'İnsanları başımıza çıkardın, 2 Ateşten, sudan geçtik. 2 Ama sonra bizi bolluğa kavuşturdun.'),
(1998274,68,19,66,13,'Yakmalık sunularla evine gireceğim, 2 Adaklarımı yerine getireceğim,'),
(1998275,68,19,66,14,'Sıkıntı içindeyken dudaklarımdan dökülen, 2 Ağzımdan çıkan adakları.'),
(1998276,68,19,66,15,'Yakılan koçların dumanıyla semiz hayvanlardan 2 Sana yakmalık sunular sunacağım, 2 Tekeler, sığırlar kurban edeceğim. |iSela'),
(1998277,68,19,66,16,'Gelin, dinleyin, ey sizler, Tanrıdan korkanlar, 2 Benim için neler yaptığını size anlatayım.'),
(1998278,68,19,66,17,'Ağzımla Ona yakardım, 2 Övgüsü dilimden düşmedi.'),
(1998279,68,19,66,18,'Yüreğimde kötülüğe yer verseydim, 2 Rab beni dinlemezdi.'),
(1998280,68,19,66,19,'Oysa Tanrı dinledi beni, 2 Kulak verdi duamın sesine.'),
(1998281,68,19,66,20,'Övgüler olsun Tanrı''ya, 2 Çünkü duamı geri çevirmedi, 2 Sevgisini benden esirgemedi.'),
(1998282,68,19,67,1,'Tanrı bize lütfetsin, bolluk versin, 2 Yüzünün ışığı üzerimize parlasın. |iSela'),
(1998283,68,19,67,2,'Öyle ki, yeryüzünde yolun, 2 Bütün uluslar arasında kurtarıcı gücün bilinsin.'),
(1998284,68,19,67,3,'Halklar sana şükretsin, ey Tanrı, 2 Bütün halklar sana şükretsin!'),
(1998285,68,19,67,4,'Uluslar sevinsin, sevinçten çığlık atsın, 2 Çünkü sen halkları adaletle yargılarsın, 2 Yeryüzündeki uluslara yol gösterirsin. |iSela'),
(1998286,68,19,67,5,'Halklar sana şükretsin, ey Tanrı, 2 Bütün halklar sana şükretsin!'),
(1998287,68,19,67,6,'Toprak ürününü verdi, 2 Tanrı, Tanrımız, bizi bolluğa kavuştursun.'),
(1998288,68,19,67,7,'Tanrı bize bolluk versin, 2 Dünyanın dört bucağındakiler O''ndan korksun!'),
(1998289,68,19,68,1,'Kalksın Tanrı, dağılsın düşmanları, 2 Kaçsın önünden Ondan nefret edenler!'),
(1998290,68,19,68,2,'Dağıtsın onları dağılan duman gibi; 2 Ateşin karşısında eriyen balmumu gibi 2 Yok olsun kötüler Tanrının önünde!'),
(1998291,68,19,68,3,'Ancak doğrular sevinsin, 2 Bayram etsinler Tanrının önünde, 2 Neşeyle coşsunlar.'),
(1998292,68,19,68,4,'Tanrıya ezgiler söyleyin, adını ilahilerle övün, 2 Çölleri geçecek biniciye yol hazırlayın; 2 Onun adı RABdir, bayram edin önünde! ‹‹Bulutlara binmiş olana ezgiler sunun››.'),
(1998293,68,19,68,5,'Kutsal konutundaki Tanrı, 2 Öksüzlerin babası, dul kadınların savunucusudur.'),
(1998294,68,19,68,6,'Tanrı kimsesizlere ev verir, 2 Tutsakları özgürlüğe ve gönence kavuşturur, 2 Ama başkaldıranlar kurak yerde oturur.'),
(1998295,68,19,68,7,'Ey Tanrı, sen halkına öncülük ettiğinde, 2 Çölde yürüdüğünde, |iSela'),
(1998296,68,19,68,8,'Yer sarsıldı, 2 Göklerden yağmur boşandı Tanrının önünde, 2 Sina Dağı sarsıldı 2 Tanrının, İsrailin Tanrısının önünde.'),
(1998297,68,19,68,9,'Bol yağmurlar yağdırdın, ey Tanrı, 2 Canlandırdın yorgun düşen yurdunu.'),
(1998298,68,19,68,10,'Halkın oraya yerleşti, 2 İyiliğinle mazlumların geçimini sağladın, ey Tanrı.'),
(1998299,68,19,68,11,'Rab buyruk verdi, 2 Büyük bir kadın topluluğu duyurdu müjdeyi:'),
(1998300,68,19,68,12,'‹‹Kaçıyor, kaçıyor orduların kralları! 2 Evi bekleyen kadınlar ganimeti paylaşıyor.'),
(1998301,68,19,68,13,'Ağılların arasında uyurken, 2 Kanatları gümüş, tüyleri pırıl pırıl altınla kaplı 2 Bir güvercine benzersiniz.››'),
(1998302,68,19,68,14,'Her Şeye Gücü Yeten, kralları dağıtırken, 2 Sanki Salmon Dağına kar yağıyordu.'),
(1998303,68,19,68,15,'Ey Başan Dağı, Tanrı Dağı! 2 Ey Başan Dağı, dorukları ulu dağ!'),
(1998304,68,19,68,16,'Ey ulu dağlar, niçin yan gözle bakıyorsunuz 2 Tanrının yerleşmek için seçtiği dağa? 2 Evet, RAB orada sonsuza dek oturacaktır.'),
(1998305,68,19,68,17,'Tanrının savaş arabaları sayısızdır, 2 Rab kutsallık içinde Sinadan geldi.'),
(1998306,68,19,68,18,'Sen yükseğe çıktın, tutsakları peşine taktın, 2 İnsanlardan, başkaldıranlardan bile armağanlar aldın, 2 Oraya yerleşmek için, ya RAB Tanrı.'),
(1998307,68,19,68,19,'Her gün yükümüzü taşıyan Rabbe, 2 Bizi kurtaran Tanrıya övgüler olsun. |iSela'),
(1998308,68,19,68,20,'Tanrımız kurtarıcı bir Tanrıdır, 2 Ölümden kurtarış yalnız Egemen RABbe özgüdür.'),
(1998309,68,19,68,21,'Kuşkusuz Tanrı düşmanlarının başını, 2 Suçlu yaşayanların kıllı kafasını ezer.'),
(1998310,68,19,68,22,'Rab, ‹‹Onları Başandan, 2 Denizin derinliklerinden geri getireceğim›› der,'),
(1998311,68,19,68,23,'‹‹Öyle ki, ayaklarını düşmanlarının kanına batırasın, 2 Köpeklerinin dili de onlardan payını alsın.››'),
(1998312,68,19,68,24,'Ey Tanrı, senin zafer alayını, 2 Tanrımın, Kralımın kutsal yere törenle gelişini gördüler:'),
(1998313,68,19,68,25,'Başta okuyucular, arkada çalgıcılar, 2 Ortada tef çalan genç kızlar.'),
(1998314,68,19,68,26,'‹‹Ey sizler, İsrail soyundan gelenler, 2 Toplantılarınızda Tanrıya, RABbe övgüler sunun!››'),
(1998315,68,19,68,27,'Önde en küçük oymak Benyamin, 2 Kalabalık halinde Yahuda önderleri, 2 Zevulun ve Naftali önderleri oradalar!'),
(1998316,68,19,68,28,'Ey Tanrı, Yeruşalimdeki tapınağından göster gücünü, 2 Bizim için kullandığın gücünü, ey Tanrı. 2 Krallar sana armağanlar sunacak.'),
(1998317,68,19,68,30,'Azarla kamışlar arasında yaşayan hayvanı, 2 Halkların buzağılarıyla boğalar sürüsünü, 2 Çiğne ayaklarınla gümüşe gönül verenleri, 2 Dağıt savaştan zevk alan halkları! boğalar›› ise irili ufaklı ulusları simgelemektedir.'),
(1998318,68,19,68,31,'Mısırdan elçiler gelecek, 2 Kûşlular ellerini Tanrıya doğru kaldırıverecek.'),
(1998319,68,19,68,32,'Ey yeryüzünün krallıkları, Tanrıya ezgiler söyleyin, 2 İlahilerle övün Rabbi, |iSela'),
(1998320,68,19,68,33,'Göklere, kadim göklere binmiş olanı. 2 İşte sesiyle, güçlü sesiyle gürlüyor!'),
(1998321,68,19,68,34,'Tanrının gücünü tanıyın; 2 Onun yüceliği İsrailin üzerinde, 2 Gücü göklerdedir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998322,68,19,68,35,'Ne heybetlisin, ey Tanrı, tapınağında! 2 İsrail''in Tanrısı''na, 2 Halkına güç, kudret veren Tanrı''ya övgüler olsun!'),
(1998323,68,19,69,1,'Kurtar beni, ey Tanrı, 2 Sular boyuma ulaştı.'),
(1998324,68,19,69,2,'Dipsiz batağa gömülüyorum, 2 Basacak yer yok. 2 Derin sulara battım, 2 Sellere kapıldım.'),
(1998325,68,19,69,3,'Tükendim feryat etmekten, 2 Boğazım kurudu; 2 Gözlerimin feri sönüyor 2 Tanrımı beklemekten.'),
(1998326,68,19,69,4,'Yok yere benden nefret edenler 2 Saçlarımdan daha çok. 2 Kalabalıktır canıma kasteden haksız düşmanlarım. 2 Çalmadığım malı nasıl geri verebilirim?'),
(1998327,68,19,69,5,'Akılsızlığımı biliyorsun, ey Tanrı, 2 Suçlarım senden gizli değil.'),
(1998328,68,19,69,6,'Ya Rab, Her Şeye Egemen RAB, 2 Utanmasın sana umut bağlayanlar benim yüzümden! 2 Ey İsrailin Tanrısı, 2 Benim yüzümden sana yönelenler rezil olmasın!'),
(1998329,68,19,69,7,'Senin uğruna hakarete katlandım, 2 Utanç kapladı yüzümü.'),
(1998330,68,19,69,8,'Kardeşlerime yabancı, 2 Annemin öz oğullarına uzak kaldım.'),
(1998331,68,19,69,9,'Çünkü evin için gösterdiğim gayret beni yiyip bitirdi, 2 Sana edilen hakaretlere ben uğradım.'),
(1998332,68,19,69,10,'Oruç tutup ağlayınca, 2 Yine hakarete uğradım.'),
(1998333,68,19,69,11,'Çula büründüğüm zaman 2 Alay konusu oldum.'),
(1998334,68,19,69,12,'Kent kapısında oturanlar beni çekiştiriyor, 2 Sarhoşların türküsü oldum.'),
(1998335,68,19,69,13,'Ama benim duam sanadır, ya RAB. 2 Ey Tanrı, sevginin bolluğuyla, 2 Güvenilir kurtarışınla uygun gördüğünde 2 Yanıtla beni.'),
(1998336,68,19,69,14,'Beni çamurdan kurtar, 2 İzin verme batmama; 2 Benden nefret edenlerden, 2 Derin sulardan kurtulayım.'),
(1998337,68,19,69,15,'Seller beni sürüklemesin, 2 Engin beni yutmasın, 2 Ölüm çukuru ağzını üstüme kapamasın.'),
(1998338,68,19,69,16,'Yanıt ver bana, ya RAB, 2 Çünkü sevgin iyidir. 2 Yüzünü çevir bana büyük merhametinle!'),
(1998339,68,19,69,17,'Kulundan yüzünü gizleme, 2 Çünkü sıkıntıdayım, hemen yanıtla beni!'),
(1998340,68,19,69,18,'Yaklaş bana, kurtar canımı, 2 Al başımdan düşmanlarımı.'),
(1998341,68,19,69,19,'Bana nasıl hakaret edildiğini, 2 Utandığımı, rezil olduğumu biliyorsun; 2 Düşmanlarımın hepsi senin önünde.'),
(1998342,68,19,69,20,'Hakaret kalbimi kırdı, dertliyim, 2 Acılarımı paylaşacak birini bekledim, çıkmadı, 2 Avutacak birini aradım, bulamadım.'),
(1998343,68,19,69,21,'Yiyeceğime zehir kattılar, 2 Sirke içirdiler susadığımda.'),
(1998344,68,19,69,22,'Önlerindeki sofra tuzak olsun onlara, 2 Yandaşları için kapan olsun!'),
(1998345,68,19,69,23,'Gözleri kararsın, göremesinler! 2 Bellerini hep bükük tut!'),
(1998346,68,19,69,24,'Gazabını yağdır üzerlerine, 2 Öfkenin ateşi yapışsın yakalarına!'),
(1998347,68,19,69,25,'Issız kalsın konakları, 2 Çadırlarında oturan olmasın!'),
(1998348,68,19,69,26,'Çünkü senin vurduğun insanlara zulmediyor, 2 Yaraladığın insanların acısını konuşuyorlar.'),
(1998349,68,19,69,27,'Ceza yağdır başlarına, 2 Senin tarafından aklanmasınlar!'),
(1998350,68,19,69,28,'Yaşam kitabından silinsin adları, 2 Doğrularla yan yana yazılmasınlar!'),
(1998351,68,19,69,29,'Bense ezilmiş ve kederliyim, 2 Senin kurtarışın, ey Tanrı, bana bir kale olsun!'),
(1998352,68,19,69,30,'Tanrının adını ezgilerle öveceğim, 2 Şükranlarımla Onu yücelteceğim.'),
(1998353,68,19,69,31,'RABbi bir öküzden, 2 Boynuzlu, tırnaklı bir boğadan 2 Daha çok hoşnut eder bu.'),
(1998354,68,19,69,32,'Mazlumlar bunu görünce sevinsin, 2 Ey Tanrıya yönelen sizler, yüreğiniz canlansın.'),
(1998355,68,19,69,33,'Çünkü RAB yoksulları işitir, 2 Kendi tutsak halkını hor görmez.'),
(1998356,68,19,69,34,'Ona övgüler sunun, ey yer, gök, 2 Denizler ve onlardaki bütün canlılar!'),
(1998357,68,19,69,35,'Çünkü Tanrı Siyonu kurtaracak, 2 Yahuda kentlerini onaracak; 2 Halk oraya yerleşip sahibi olacak.'),
(1998358,68,19,69,36,'Kullarının çocukları orayı miras alacak, 2 O''nun adını sevenler orada oturacak.'),
(1998359,68,19,70,1,'Ey Tanrı, kurtar beni! 2 Yardımıma koş, ya RAB!'),
(1998360,68,19,70,2,'Utansın canımı almaya çalışanlar, 2 Yüzleri kızarsın! 2 Geri dönsün zararımı isteyenler, 2 Rezil olsunlar!'),
(1998361,68,19,70,3,'Bana, ‹‹Oh! Oh!›› çekenler 2 Geri çekilsin utançlarından!'),
(1998362,68,19,70,4,'Sende neşe ve sevinç bulsun 2 Bütün sana yönelenler! 2 ‹‹Tanrı yücedir!›› desin hep 2 Senin kurtarışını özleyenler!'),
(1998363,68,19,70,5,'Bense, mazlum ve yoksulum, 2 Ey Tanrı, yardımıma koş! 2 Yardımcım ve kurtarıcım sensin, 2 Geç kalma, ya RAB!'),
(1998364,68,19,71,1,'Ya RAB, sana sığınıyorum, 2 Utandırma beni hiçbir zaman!'),
(1998365,68,19,71,2,'Adaletinle kurtar beni, tehlikeden uzaklaştır, 2 Kulak ver bana, kurtar beni!'),
(1998366,68,19,71,3,'Sığınacak kayam ol, 2 Her zaman başvurabileceğim; 2 Buyruk ver, kurtulayım, 2 Çünkü kayam ve kalem sensin.'),
(1998367,68,19,71,4,'Ey Tanrım, kurtar beni 2 Kötünün elinden, haksızın, gaddarın pençesinden!'),
(1998368,68,19,71,5,'Çünkü umudum sensin, ey Egemen RAB, 2 Gençliğimden beri dayanağım sensin.'),
(1998369,68,19,71,6,'Doğduğum günden beri sana güveniyorum, 2 Beni ana rahminden çıkaran sensin. 2 Övgülerim hep sanadır.'),
(1998370,68,19,71,7,'Birçokları için iyi bir örnek oldum, 2 Çünkü sen güçlü sığınağımsın.'),
(1998371,68,19,71,8,'Ağzımdan sana övgü eksilmez, 2 Gün boyu yüceliğini anarım.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998372,68,19,71,9,'Yaşlandığımda beni reddetme, 2 Gücüm tükendiğinde beni terk etme!'),
(1998373,68,19,71,10,'Çünkü düşmanlarım benden söz ediyor, 2 Beni öldürmek isteyenler birbirine danışıyor,'),
(1998374,68,19,71,11,'‹‹Tanrı onu terk etti›› diyorlar, 2 ‹‹Kovalayıp yakalayın, 2 Kurtaracak kimsesi yok!››'),
(1998375,68,19,71,12,'Ey Tanrı, benden uzak durma, 2 Tanrım, yardımıma koş!'),
(1998376,68,19,71,13,'Utansın, yok olsun beni suçlayanlar, 2 Utanca, rezalete bürünsün kötülüğümü isteyenler.'),
(1998377,68,19,71,14,'Ama ben her zaman umutluyum, 2 Sana övgü üstüne övgü dizeceğim.'),
(1998378,68,19,71,15,'Gün boyu senin zaferini, 2 Kurtarışını anlatacağım, 2 Ölçüsünü bilmesem de.'),
(1998379,68,19,71,16,'Ey Egemen RAB, gelip yiğitliklerini, 2 Senin, yalnız senin zaferini duyuracağım.'),
(1998380,68,19,71,17,'Ey Tanrı, çocukluğumdan beri beni sen yetiştirdin, 2 Senin harikalarını hâlâ anlatıyorum.'),
(1998381,68,19,71,18,'Yaşlanıp saçlarıma ak düşse bile 2 Terk etme beni, ey Tanrı, 2 Gücünü gelecek kuşağa, 2 Kudretini sonrakilere anlatana dek.'),
(1998382,68,19,71,19,'Ey Tanrı, doğruluğun göklere erişiyor, 2 Büyük işler yaptın, 2 Senin gibisi var mı, ey Tanrı?'),
(1998383,68,19,71,20,'Sen ki, bana birçok kötü sıkıntı gösterdin, 2 Bana yeniden yaşam verecek, 2 Beni toprağın derinliklerinden çıkaracaksın.'),
(1998384,68,19,71,21,'Saygınlığımı artıracak, 2 Yine beni avutacaksın.'),
(1998385,68,19,71,22,'Ben de seni, 2 Senin sadakatini çenkle öveceğim, ey Tanrım, 2 Lir çalarak seni ilahilerle öveceğim, 2 Ey İsrailin Kutsalı!'),
(1998386,68,19,71,23,'Seni ilahilerle överken, 2 Dudaklarımla, varlığımla sevincimi dile getireceğim, 2 Çünkü sen beni kurtardın.'),
(1998387,68,19,71,24,'Dilim gün boyu senin zaferinden söz edecek, 2 Çünkü kötülüğümü isteyenler 2 Utanıp rezil oldu.'),
(1998388,68,19,72,1,'Ey Tanrı, adaletini krala, 2 Doğruluğunu kral oğluna armağan et.'),
(1998389,68,19,72,2,'Senin halkını doğrulukla, 2 Mazlum kullarını adilce yargılasın!'),
(1998390,68,19,72,3,'Dağlar, tepeler, 2 Halka adilce gönenç getirsin!'),
(1998391,68,19,72,4,'Mazlumlara hakkını versin, 2 Yoksulların çocuklarını kurtarsın, 2 Zalimleriyse ezsin!'),
(1998392,68,19,72,5,'Güneş ve ay durdukça, 2 Kral kuşaklar boyunca yaşasın; metin ‹‹Kuşaklar boyunca senden korksunlar.››'),
(1998393,68,19,72,6,'Yeni biçilmiş çayıra düşen yağmur gibi, 2 Toprağı sulayan bereketli yağmurlar gibi olsun!'),
(1998394,68,19,72,7,'Onun günlerinde doğruluk serpilip gelişsin, 2 Ay ışıdığı sürece esenlik artsın!'),
(1998395,68,19,72,8,'Egemenlik sürsün denizden denize, 2 Fırattan yeryüzünün ucuna dek!'),
(1998396,68,19,72,9,'Çöl kabileleri diz çöksün önünde, 2 Düşmanları toz yalasın.'),
(1998397,68,19,72,10,'Tarşişin ve kıyı ülkelerinin kralları 2 Ona haraç getirsin, 2 Saba ve Seva kralları armağanlar sunsun!'),
(1998398,68,19,72,11,'Bütün krallar önünde yere kapansın, 2 Bütün uluslar ona kulluk etsin!'),
(1998399,68,19,72,12,'Çünkü yardım isteyen yoksulu, 2 Dayanağı olmayan düşkünü o kurtarır.'),
(1998400,68,19,72,13,'Yoksula, düşküne acır, 2 Düşkünlerin canını kurtarır.'),
(1998401,68,19,72,14,'Baskıdan, zorbalıktan özgür kılar onları, 2 Çünkü onun gözünde onların kanı değerlidir.'),
(1998402,68,19,72,15,'Yaşasın kral! 2 Ona Saba altını versinler; 2 Durmadan dua etsinler onun için, 2 Gün boyu onu övsünler!'),
(1998403,68,19,72,16,'Ülkede bol buğday olsun, 2 Dağ başlarında dalgalansın! 2 Başakları Lübnan gibi verimli olsun, 2 Kent halkı ot gibi serpilip çoğalsın!'),
(1998404,68,19,72,17,'Kralın adı sonsuza dek yaşasın, 2 Güneş durdukça adı var olsun, 2 Onun aracılığıyla insanlar kutsansın, 2 Bütün uluslar ‹‹Ne mutlu ona›› desin!'),
(1998405,68,19,72,18,'RAB Tanrıya, İsrailin Tanrısına övgüler olsun, 2 Harikalar yaratan yalnız Odur.'),
(1998406,68,19,72,19,'Yüce adına sonsuza dek övgüler olsun, 2 Bütün yeryüzü Onun yüceliğiyle dolsun! 2 Amin! Amin!'),
(1998407,68,19,72,20,'İşay oğlu Davut''un duaları burada bitiyor.'),
(1998408,68,19,73,1,'Tanrı gerçekten İsraile, 2 Yüreği temiz olanlara karşı iyidir.'),
(1998409,68,19,73,2,'Ama benim ayaklarım neredeyse tökezlemiş, 2 Adımlarım az kalsın kaymıştı.'),
(1998410,68,19,73,3,'Çünkü kötülerin gönencini gördükçe, 2 Küstahları kıskanıyordum.'),
(1998411,68,19,73,4,'Onlar acı nedir bilmezler, 2 Bedenleri sağlıklı ve semizdirfç. semizdir›› ya da ‹‹Ölürken acı çekmezler, bedenleri semizdir››.'),
(1998412,68,19,73,5,'Başkalarının derdini bilmez, 2 Onlar gibi çile çekmezler.'),
(1998413,68,19,73,6,'Bu yüzden gurur onların gerdanlığı, 2 Zorbalık onları örten bir giysi gibidir.'),
(1998414,68,19,73,7,'Şişmanlıktan gözleri dışarı fırlar, 2 İçleri kötülük kazanı gibi kaynar.'),
(1998415,68,19,73,8,'İnsanlarla eğlenir, kötü niyetle konuşur, 2 Tepeden bakar, baskıyla tehdit ederler.'),
(1998416,68,19,73,9,'Göklere karşı ağızlarını açarlar, 2 Boş sözleri yeryüzünü dolaşır.'),
(1998417,68,19,73,10,'Bu yüzden halk onlardan yana döner, 2 Sözlerini ağzı açık dinler.'),
(1998418,68,19,73,11,'Derler ki, ‹‹Tanrı nasıl bilir? 2 Bilgisi var mı Yüceler Yücesinin?››'),
(1998419,68,19,73,12,'İşte böyledir kötüler, 2 Hep tasasız, sürekli varlıklarını artırırlar.'),
(1998420,68,19,73,13,'Anlaşılan boş yere yüreğimi temiz tutmuşum, 2 Ellerimi yıkamışım suçsuzum diye.'),
(1998421,68,19,73,14,'Gün boyu içim içimi yiyor, 2 Her sabah azap çekiyorum.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998422,68,19,73,15,'‹‹Ben de onlar gibi konuşayım›› deseydim, 2 Senin çocuklarına ihanet etmiş olurdum.'),
(1998423,68,19,73,16,'Bunu anlamak için düşündüğümde, 2 Zor geldi bana,'),
(1998424,68,19,73,17,'Tanrının Tapınağına girene dek; 2 O zaman anladım sonlarının ne olacağını.'),
(1998425,68,19,73,18,'Gerçekten onları kaygan yere koyuyor, 2 Yıkıma sürüklüyorsun.'),
(1998426,68,19,73,19,'Nasıl da bir anda yok oluyor, 2 Siliniveriyorlar dehşet içinde!'),
(1998427,68,19,73,20,'Uyanan birisi için rüya nasılsa, 2 Sen de uyanınca, ya Rab, 2 Hor göreceksin onların görüntüsünü.'),
(1998428,68,19,73,21,'Kalbim kırıldığında, 2 İçim acı dolduğunda,'),
(1998429,68,19,73,22,'Akılsız ve bilgisizdim, 2 Karşında bir hayvan gibi.'),
(1998430,68,19,73,23,'Yine de sürekli seninleyim, 2 Sağ elimden tutarsın beni.'),
(1998431,68,19,73,24,'Öğütlerinle yol gösterir, 2 Beni sonunda yüceliğe eriştirirsin.'),
(1998432,68,19,73,25,'Senden başka kimim var göklerde? 2 İstemem senden başkasını yeryüzünde.'),
(1998433,68,19,73,26,'Bedenim ve yüreğim tükenebilir, 2 Ama Tanrı yüreğimde güç, 2 Bana düşen paydır sonsuza dek.'),
(1998434,68,19,73,27,'Kuşkusuz yok olacak senden uzak duranlar, 2 Ortadan kaldıracaksın sana vefasızlık edenleri.'),
(1998435,68,19,73,28,'Ama benim için en iyisi Tanrı''ya yakın olmaktır; 2 Bütün işlerini duyurayım diye 2 Sığınak yaptım Egemen RAB''bi kendime.'),
(1998436,68,19,74,1,'Ey Tanrı, neden bizi sonsuza dek reddettin? 2 Niçin otlağının koyunlarına karşı öfken tütmekte?'),
(1998437,68,19,74,2,'Anımsa geçmişte sahiplendiğin topluluğu, 2 Kendi halkın olsun diye kurtardığın oymağı 2 Ve üzerine konut kurduğun Siyon Dağını.'),
(1998438,68,19,74,3,'Yönelt adımlarını şu onarılmaz yıkıntılara doğru, 2 Düşman kutsal yerdeki her şeyi yıktı.'),
(1998439,68,19,74,4,'Düşmanların bizimle buluştuğun yerde kükredi, 2 Zafer simgesi olarak kendi bayraklarını dikti.'),
(1998440,68,19,74,5,'Gür bir ormana 2 Baltayla dalar gibiydiler.'),
(1998441,68,19,74,6,'Baltayla, balyozla kırdılar, 2 Bütün oymaları.'),
(1998442,68,19,74,7,'Ateşe verdiler tapınağını, 2 Yerle bir edip kutsallığını bozdular 2 Adının yaşadığı konutun.'),
(1998443,68,19,74,8,'İçlerinden, ‹‹Hepsini ezelim!›› dediler. 2 Ülkede Tanrıyla buluşma yerlerinin tümünü yaktılar.'),
(1998444,68,19,74,9,'Artık kutsal simgelerimizi görmüyoruz, 2 Peygamberler de yok oldu, 2 İçimizden kimse bilmiyor ne zamana dek...'),
(1998445,68,19,74,10,'Ey Tanrı, ne zamana dek düşman sana sövecek, 2 Hasmın senin adını hor görecek?'),
(1998446,68,19,74,11,'Niçin geri çekiyorsun elini? 2 Çıkar sağ elini bağrından, yok et onları!'),
(1998447,68,19,74,12,'Ama geçmişten bu yana kralım sensin, ey Tanrı, 2 Yeryüzünde kurtuluş sağladın.'),
(1998448,68,19,74,13,'Gücünle denizi yardın, 2 Canavarların kafasını sularda parçaladın.'),
(1998449,68,19,74,14,'Livyatanın başlarını ezdin, 2 Çölde yaşayanlara onu yem ettin.'),
(1998450,68,19,74,15,'Kaynaklar, dereler fışkırttın, 2 Sürekli akan ırmakları kuruttun.'),
(1998451,68,19,74,16,'Gün senindir, gece de senin, 2 Ay ve güneşi sen yerleştirdin, kastediyor.'),
(1998452,68,19,74,17,'Yeryüzünün bütün sınırlarını sen saptadın, 2 Yazı da kışı da yaratan sensin.'),
(1998453,68,19,74,18,'Anımsa, ya RAB, düşmanın sana nasıl sövdüğünü, 2 Akılsız bir halkın, adını nasıl hor gördüğünü.'),
(1998454,68,19,74,19,'Canavara teslim etme kumrunun canını, 2 Asla unutma düşkün kullarının yaşamını.'),
(1998455,68,19,74,20,'Yaptığın antlaşmayı gözönüne al, 2 Çünkü ülkenin her karanlık köşesi 2 Zorbaların inleriyle dolmuş.'),
(1998456,68,19,74,21,'Düşkünler boynu bükük geri çevrilmesin, 2 Mazlumlar, yoksullar adına övgüler dizsin.'),
(1998457,68,19,74,22,'Kalk, ey Tanrı, davanı savun! 2 Anımsa akılsızların gün boyu sana nasıl sövdüğünü!'),
(1998458,68,19,74,23,'Unutma hasımlarının yaygarasını, 2 Sana başkaldıranların durmadan yükselen patırtısını!'),
(1998459,68,19,75,1,'Sana şükrederiz, ey Tanrı, 2 Şükrederiz, çünkü sen yakınsın, 2 Harikaların bunu gösterir.'),
(1998460,68,19,75,2,'‹‹Belirlediğim zaman gelince, 2 Doğrulukla yargılayacağım›› diyor Tanrı,'),
(1998461,68,19,75,3,'‹‹Yeryüzü altüst olunca üzerindekilerle, 2 Ben pekiştireceğim onun direklerini. |iSela'),
(1998462,68,19,75,4,'Övünenlere, ‹Övünmeyin artık!› dedim; 2 Kötülere, ‹Kaldırmayın başınızı!'),
(1998463,68,19,75,5,'Kaldırmayın başınızı! 2 Tepeden konuşmayın!› ›› simgesidir).'),
(1998464,68,19,75,6,'Çünkü ne doğudan, ne batıdan, 2 Ne de çöldeki dağlardan doğar yargı.'),
(1998465,68,19,75,7,'Yargıç ancak Tanrıdır, 2 Birini alçaltır, birini yükseltir.'),
(1998466,68,19,75,8,'RAB elinde dolu bir kâse tutuyor, 2 Köpüklü, baharat karıştırılmış şarap döküyor; 2 Yeryüzünün bütün kötüleri 2 Tortusuna dek yalayıp onu içiyor.'),
(1998467,68,19,75,9,'Bense sürekli duyuracağım bunu, 2 Yakupun Tanrısını ilahilerle öveceğim:'),
(1998468,68,19,75,10,'‹‹Kıracağım kötülerin bütün gücünü, 2 Doğruların gücüyse yükseltilecek.››'),
(1998469,68,19,76,1,'Yahudada Tanrı bilinir, 2 İsrailde adı uludur;'),
(1998470,68,19,76,2,'Konutu Şalemdedir, 2 Yaşadığı yer Siyonda.'),
(1998471,68,19,76,3,'Orada kırdı alevli okları, 2 Kalkanı, kılıcı, savaş silahlarını. |iSela');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998472,68,19,76,4,'Işıl ışıl parıldıyorsun, 2 Avı bol dağlardan daha görkemli.'),
(1998473,68,19,76,5,'Yağmaya uğradı yiğitler, 2 Uykularına daldılar, 2 En güçlüleri bile elini kıpırdatamaz oldu.'),
(1998474,68,19,76,6,'Ey Yakupun Tanrısı, sen kükreyince, 2 Atlarla atlılar son uykularına daldılar.'),
(1998475,68,19,76,7,'Yalnız sensin korkulması gereken, 2 Öfkelenince kim durabilir karşında?'),
(1998476,68,19,76,8,'Yargını göklerden açıkladın, 2 Yeryüzü korkup sessizliğe büründü,'),
(1998477,68,19,76,9,'Ey Tanrı, sen yargılamaya, 2 Ülkedeki mazlumları kurtarmaya kalkınca. |iSela'),
(1998478,68,19,76,10,'İnsanların gazabı bile sana övgüler doğuruyor, 2 Gazabından kurtulanları çevrene topluyorsun.'),
(1998479,68,19,76,11,'Adaklar adayın Tanrınız RABbe, 2 Yerine getirin adaklarınızı, 2 Armağanlar sunun korkulması gereken Tanrıya, 2 Bütün çevresindekiler.'),
(1998480,68,19,76,12,'RAB önderlerin soluğunu keser, 2 Korku salar yeryüzü krallarına.'),
(1998481,68,19,77,1,'Yüksek sesle Tanrıya yakarıyorum, 2 Haykırıyorum beni duysun diye.'),
(1998482,68,19,77,2,'Sıkıntılı günümde Rabbe yönelir, 2 Gece hiç durmadan ellerimi açarım, 2 Gönlüm avunmaz bir türlü.'),
(1998483,68,19,77,3,'Tanrıyı anımsayınca inlerim, 2 Düşündükçe içim daralır. |iSela'),
(1998484,68,19,77,4,'Açık tutuyorsun göz kapaklarımı, 2 Sıkıntıdan konuşamıyorum.'),
(1998485,68,19,77,5,'Geçmiş günleri, 2 Yıllar öncesini düşünüyorum.'),
(1998486,68,19,77,6,'Gece ilahilerimi anacağım, 2 Kendi kendimle konuşacağım, 2 İnceden inceye soracağım:'),
(1998487,68,19,77,7,'‹‹Rab sonsuza dek mi bizi reddedecek? 2 Lütfunu bir daha göstermeyecek mi?'),
(1998488,68,19,77,8,'Sevgisi sonsuza dek mi yok oldu? 2 Sözü geçerli değil mi artık?'),
(1998489,68,19,77,9,'Tanrı unuttu mu acımayı? 2 Sevecenliğinin yerini öfke mi aldı?›› |iSela'),
(1998490,68,19,77,10,'Sonra kendi kendime, ‹‹İşte benim derdim bu!›› dedim, 2 ‹‹Yüceler Yücesi gücünü göstermiyor artık.››'),
(1998491,68,19,77,11,'RABbin işlerini anacağım, 2 Evet, geçmişteki harikalarını anacağım.'),
(1998492,68,19,77,12,'Yaptıkları üzerinde derin derin düşüneceğim, 2 Bütün işlerinin üzerinde dikkatle duracağım.'),
(1998493,68,19,77,13,'Ey Tanrı, yolun kutsaldır! 2 Hangi ilah Tanrı kadar uludur?'),
(1998494,68,19,77,14,'Harikalar yaratan Tanrı sensin, 2 Halklar arasında gücünü gösterdin.'),
(1998495,68,19,77,15,'Güçlü bileğinle kendi halkını, 2 Yakup ve Yusuf oğullarını kurtardın. |iSela'),
(1998496,68,19,77,16,'Sular seni görünce, ey Tanrı, 2 Sular seni görünce çalkalandı, 2 Enginler titredi.'),
(1998497,68,19,77,17,'Bulutlar suyunu boşalttı, 2 Gökler gürledi, 2 Her yanda okların uçuştu.'),
(1998498,68,19,77,18,'Kasırgada gürleyişin duyuldu, 2 Şimşekler dünyayı aydınlattı, 2 Yer titreyip sarsıldı.'),
(1998499,68,19,77,19,'Kendine denizde, 2 Derin sularda yollar açtın, 2 Ama ayak izlerin belli değildi.'),
(1998500,68,19,77,20,'Musa ve Harun''un eliyle 2 Halkını bir sürü gibi güttün.'),
(1998501,68,19,78,1,'Dinle, ey halkım, öğrettiklerimi, 2 Kulak ver ağzımdan çıkan sözlere.'),
(1998502,68,19,78,2,'Özdeyişlerle söze başlayacağım, 2 Eski sırları anlatacağım,'),
(1998503,68,19,78,3,'Duyduğumuzu, bildiğimizi, 2 Atalarımızın bize anlattığını.'),
(1998504,68,19,78,4,'Torunlarından bunları gizlemeyeceğiz; 2 RABbin övgüye değer işlerini, 2 Gücünü, yaptığı harikaları 2 Gelecek kuşağa duyuracağız.'),
(1998505,68,19,78,5,'RAB Yakup soyuna koşullar bildirdi, 2 İsraile yasa koydu. 2 Bunları çocuklarına öğretsinler diye 2 Atalarımıza buyruk verdi.'),
(1998506,68,19,78,6,'Öyle ki, gelecek kuşak, yeni doğacak çocuklar bilsinler, 2 Onlar da kendi çocuklarına anlatsınlar,'),
(1998507,68,19,78,7,'Tanrıya güven duysunlar, 2 Tanrının yaptıklarını unutmasınlar, 2 Onun buyruklarını yerine getirsinler;'),
(1998508,68,19,78,8,'Ataları gibi inatçı, başkaldırıcı, 2 Yüreği kararsız, 2 Tanrıya sadakatsiz bir kuşak olmasınlar.'),
(1998509,68,19,78,9,'Oklarla, yaylarla kuşanmış Efrayimoğulları 2 Savaş günü sırtlarını döndüler.'),
(1998510,68,19,78,10,'Tanrının antlaşmasına uymadılar, 2 Onun yasasına göre yaşamayı reddettiler.'),
(1998511,68,19,78,11,'Unuttular Onun işlerini, 2 Kendilerine gösterdiği harikaları.'),
(1998512,68,19,78,12,'Mısırda, Soan bölgesinde 2 Tanrı harikalar yapmıştı atalarının önünde.'),
(1998513,68,19,78,13,'Denizi yarıp geçirmişti onları, 2 Bir duvar gibi ayakta tutmuştu suları.'),
(1998514,68,19,78,14,'Gündüz bulutla, 2 Gece ateş ışığıyla onlara yol göstermişti.'),
(1998515,68,19,78,15,'Çölde kayaları yarmış, 2 Sanki dipsiz kaynaklardan 2 Onlara kana kana su içirmişti.'),
(1998516,68,19,78,16,'Kayadan akarsular fışkırtmış, 2 Suları ırmak gibi akıtmıştı.'),
(1998517,68,19,78,17,'Ama onlar çölde Yüceler Yücesine başkaldırarak 2 Günah işlemeye devam ettiler.'),
(1998518,68,19,78,18,'Canlarının çektiği yiyeceği isteyerek 2 İçlerinde Tanrıyı denediler.'),
(1998519,68,19,78,19,'‹‹Tanrı çölde sofra kurabilir mi?›› diyerek, 2 Tanrıya karşı konuştular.'),
(1998520,68,19,78,20,'‹‹Bak, kayaya vurunca sular fışkırdı, 2 Dereler taştı. 2 Peki, ekmek de verebilir mi, 2 Et sağlayabilir mi halkına?››'),
(1998521,68,19,78,21,'RAB bunu duyunca çok öfkelendi, 2 Yakupa ateş püskürdü, 2 Öfkesi tırmandı İsraile karşı;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998522,68,19,78,22,'Çünkü Tanrıya inanmıyorlardı, 2 Onun kurtarıcılığına güvenmiyorlardı.'),
(1998523,68,19,78,23,'Yine de RAB buyruk verdi bulutlara, 2 Kapaklarını açtı göklerin;'),
(1998524,68,19,78,24,'Man yağdırdı onları beslemek için, 2 Göksel tahıl verdi onlara.'),
(1998525,68,19,78,25,'Meleklerinfı ekmeğini yedi her biri, 2 Doyasıya yiyecek gönderdi onlara.'),
(1998526,68,19,78,26,'Doğu rüzgarını estirdi göklerde, 2 Gücüyle güney rüzgarına yol gösterdi.'),
(1998527,68,19,78,27,'Toz gibi et yağdırdı başlarına, 2 Deniz kumu kadar kuş;'),
(1998528,68,19,78,28,'Ordugahlarının ortasına, 2 Konakladıkları yerin çevresine düşürdü.'),
(1998529,68,19,78,29,'Yediler, tıka basa doydular, 2 İsteklerini yerine getirdi Tanrı.'),
(1998530,68,19,78,30,'Ancak onlar isteklerine doymadan, 2 Daha ağızları doluyken,'),
(1998531,68,19,78,31,'Tanrının öfkesi parladı üzerlerine. 2 En güçlülerini öldürdü, 2 Yere serdi İsrail yiğitlerini.'),
(1998532,68,19,78,32,'Yine de günah işlemeye devam ettiler, 2 Onun harikalarına inanmadılar.'),
(1998533,68,19,78,33,'Bu yüzden Tanrı onların günlerini boşluk, 2 Yıllarını dehşet içinde bitirdi.'),
(1998534,68,19,78,34,'Tanrı onları öldürdükçe Ona yönelmeye, 2 İstekle Onu yeniden aramaya başlıyorlardı.'),
(1998535,68,19,78,35,'Tanrının kayaları olduğunu, 2 Yüce Tanrının kurtarıcıları olduğunu anımsıyorlardı.'),
(1998536,68,19,78,36,'Oysa ağızlarıyla Ona yaltaklanıyor, 2 Dilleriyle yalan söylüyorlardı.'),
(1998537,68,19,78,37,'Ona yürekten bağlı değillerdi, 2 Antlaşmasına sadık kalmadılar.'),
(1998538,68,19,78,38,'Yine de Tanrı sevecendi, 2 Suçlarını bağışlıyor, onları yok etmiyordu; 2 Çok kez öfkesini tuttu, 2 Bütün gazabını göstermedi.'),
(1998539,68,19,78,39,'Onların yalnızca insan olduğunu anımsadı, 2 Geçip giden, dönmeyen bir rüzgar gibi.'),
(1998540,68,19,78,40,'Çölde kaç kez Ona başkaldırdılar, 2 Issız yerlerde Onu gücendirdiler!'),
(1998541,68,19,78,41,'Defalarca denediler Tanrıyı, 2 İncittiler İsrailin Kutsalını.'),
(1998542,68,19,78,42,'Anımsamadılar Onun güçlü elini, 2 Kendilerini düşmandan kurtardığı günü,'),
(1998543,68,19,78,43,'Mısırda gösterdiği belirtileri, 2 Soan bölgesinde yaptığı şaşılası işleri.'),
(1998544,68,19,78,44,'Mısırın kanallarını kana çevirdi, 2 Sularını içemediler.'),
(1998545,68,19,78,45,'Gönderdiği at sinekleri yedi halkı, 2 Gönderdiği kurbağalar yok etti ülkeyi.'),
(1998546,68,19,78,46,'Ekinlerini tırtıllara, 2 Emeklerinin ürününü çekirgelere verdi.'),
(1998547,68,19,78,47,'Asmalarını doluyla, 2 Yabanıl incir ağaçlarını iri dolu taneleriyle yok etti.'),
(1998548,68,19,78,48,'Büyükbaş hayvanlarını kırgına, 2 Küçükbaş hayvanlarını yıldırıma teslim etti.'),
(1998549,68,19,78,49,'Üzerlerine kızgın öfkesini, 2 Gazap, hışım, bela 2 Ve bir alay kötülük meleği gönderdi.'),
(1998550,68,19,78,50,'Yol verdi öfkesine, 2 Canlarını ölümden esirgemedi, 2 Onları salgın hastalığın pençesine düşürdü.'),
(1998551,68,19,78,51,'Mısırda bütün ilk doğanları, 2 Hamın çadırlarında bütün ilk çocukları vurdu.'),
(1998552,68,19,78,52,'Kendi halkını davar gibi götürdü, 2 Çölde onları bir sürü gibi güttü.'),
(1998553,68,19,78,53,'Onlara güvenlik içinde yol gösterdi, korkmadılar; 2 Düşmanlarınıysa deniz yuttu.'),
(1998554,68,19,78,54,'Böylece onları kendi kutsal topraklarının sınırına, 2 Sağ elinin kazandığı dağlık bölgeye getirdi.'),
(1998555,68,19,78,55,'Önlerinden ulusları kovdu, 2 Mülk olarak topraklarını 2 İsrail oymakları arasında bölüştürdü. 2 Halkını konutlarına yerleştirdi.'),
(1998556,68,19,78,56,'Ama onlar yüce Tanrıyı denediler, 2 Ona başkaldırdılar, 2 Koşullarına uymadılar.'),
(1998557,68,19,78,57,'Döneklik edip ataları gibi ihanet ettiler, 2 Güvenilmez bir yay gibi bozuk çıktılar.'),
(1998558,68,19,78,58,'Puta taptıkları yerlerle Onu kızdırdılar, 2 Putlarıyla Onu kıskandırdılar.'),
(1998559,68,19,78,59,'Tanrı bunları duyunca çok öfkelendi, 2 İsraili büsbütün reddetti.'),
(1998560,68,19,78,60,'İnsanlar arasında kurduğu çadırı, 2 Şilodaki konutunu terk etti.'),
(1998561,68,19,78,61,'Kudretini tutsaklığa, 2 Görkemini düşman eline teslim etti. Antlaşma Sandığını kastetmektedir.'),
(1998562,68,19,78,62,'Halkını kılıç önüne sürdü, 2 Öfkesini kendi halkından çıkardı.'),
(1998563,68,19,78,63,'Gençlerini ateş yuttu, 2 Kızlarına düğün türküsü söylenmez oldu.'),
(1998564,68,19,78,64,'Kâhinleri kılıç altında öldü, 2 Dul kadınları ağlayamadı.'),
(1998565,68,19,78,65,'O zaman Rab uykudan uyanır gibi, 2 Şarabın rehavetinden ayılan bir yiğit gibi oldu.'),
(1998566,68,19,78,66,'Düşmanlarını püskürttü, 2 Onları sonsuz utanca boğdu.'),
(1998567,68,19,78,67,'Tanrı Yusuf soyunu reddetti, 2 Efrayim oymağını seçmedi;'),
(1998568,68,19,78,68,'Ancak Yahuda oymağını, 2 Sevdiği Siyon Dağını seçti.'),
(1998569,68,19,78,69,'Tapınağını doruklar gibi, 2 Sonsuzluk için kurduğu yeryüzü gibi yaptı.'),
(1998570,68,19,78,70,'Kulu Davutu seçti, 2 Onu koyun ağılından aldı.'),
(1998571,68,19,78,71,'Halkı Yakupu, kendi halkı İsraili gütmek için, 2 Onu yavru kuzuların ardından getirdi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998572,68,19,78,72,'Böylece Davut onlara dürüstçe çobanlık etti, 2 Becerikli elleriyle onlara yol gösterdi.'),
(1998573,68,19,79,1,'Ey Tanrı, uluslar senin yurduna saldırdı, 2 Kutsal tapınağını kirletti, 2 Yeruşalimi taş yığınına çevirdi.'),
(1998574,68,19,79,2,'Kullarının ölülerini yem olarak yırtıcı kuşlara, 2 Sadık kullarının etini yabanıl hayvanlara verdiler.'),
(1998575,68,19,79,3,'Kanlarını su gibi akıttılar Yeruşalimin çevresine, 2 Onları gömecek kimse yok.'),
(1998576,68,19,79,4,'Komşularımıza yüzkarası, 2 Çevremizdekilere eğlence ve oyuncak olduk.'),
(1998577,68,19,79,5,'Ne zamana dek, ya RAB? 2 Sonsuza dek mi sürecek öfken, 2 Alev gibi yanan kıskançlığın?'),
(1998578,68,19,79,6,'Öfkeni seni tanımayan ulusların, 2 Adını anmayan ülkelerin üzerine dök.'),
(1998579,68,19,79,7,'Çünkü onlar Yakup soyunu yiyip bitirdiler, 2 Yurdunu viraneye çevirdiler.'),
(1998580,68,19,79,8,'Atalarımızın suçlarını artık önümüze sürme, 2 Sevecenliğini hemen göster bize, 2 Çünkü tükendikçe tükendik.'),
(1998581,68,19,79,9,'Yardım et bize yüce adın uğruna, ey bizi kurtaran Tanrı, 2 Kurtar bizi adın uğruna, bağışla günahlarımızı!'),
(1998582,68,19,79,10,'Niçin uluslar, ‹‹Nerede onların Tanrısı?›› diye konuşsun, 2 Kullarının dökülen kanının öcünü alacağını bilsinler, 2 Gözlerimizle bunu görelim!'),
(1998583,68,19,79,11,'Tutsakların iniltisi senin katına erişsin, 2 Koru büyük gücünle ölüme mahkûm olanları.'),
(1998584,68,19,79,12,'Komşularımızın sana ettikleri hakareti 2 Yedi kat iade et bağırlarına, ya Rab!'),
(1998585,68,19,79,13,'Bizler, kendi halkın, otlağının koyunları 2 Sonsuza dek şükredeceğiz sana, 2 Kuşaklar boyunca övgülerini dilimizden düşürmeyeceğiz.'),
(1998586,68,19,80,1,'Kulak ver, ey İsrailin çobanı, 2 Ey Yusufu bir sürü gibi güden, 2 Keruvlar arasında taht kuran, 2 Saç ışığını,'),
(1998587,68,19,80,2,'Efrayim, Benyamin, Manaşşe önünde 2 Uyandır gücünü, 2 Gel, kurtar bizi!'),
(1998588,68,19,80,3,'Bizi eski halimize kavuştur, ey Tanrı, 2 Yüzünün ışığıyla aydınlat, kurtulalım!'),
(1998589,68,19,80,4,'Ya RAB, Her Şeye Egemen Tanrı, 2 Ne zamana dek halkının dualarına ateş püsküreceksin?'),
(1998590,68,19,80,5,'Onlara ekmek yerine gözyaşı verdin, 2 Ölçekler dolusu gözyaşı içirdin.'),
(1998591,68,19,80,6,'Kavga nedeni ettin bizi komşularımıza, 2 Düşmanlarımız alay ediyor bizimle.'),
(1998592,68,19,80,7,'Bizi eski halimize kavuştur, 2 Ey Her Şeye Egemen Tanrı, 2 Yüzünün ışığıyla aydınlat, kurtulalım!'),
(1998593,68,19,80,8,'Mısırdan bir asma çubuğu getirdin, 2 Ulusları kovup onu diktin.'),
(1998594,68,19,80,9,'Onun için toprağı hazırladın, 2 Kök saldı, bütün ülkeye yayıldı.'),
(1998595,68,19,80,10,'Gölgesi dağları, 2 Dalları koca sedir ağaçlarını kapladı.'),
(1998596,68,19,80,11,'Sürgünleri Akdenize, 2 Filizleri Fırata dek uzandı.'),
(1998597,68,19,80,12,'Niçin yıktın bağın duvarlarını? 2 Yoldan geçen herkes üzümünü koparıyor,'),
(1998598,68,19,80,13,'Orman domuzları onu yoluyor, 2 Yabanıl hayvanlar onunla besleniyor.'),
(1998599,68,19,80,14,'Ey Her Şeye Egemen Tanrı, ne olur, dön bize! 2 Göklerden bak ve gör, 2 İlgilen bu asmayla.'),
(1998600,68,19,80,15,'İlgilen sağ elinin diktiği filizle, 2 Kendine seçtiğin oğulla!'),
(1998601,68,19,80,16,'Asman kesilmiş, yakılmış, 2 Öfkeli bakışların yok etsin düşmanlarını!'),
(1998602,68,19,80,17,'Elin, sağ kolun olan adamın üzerinde, 2 Kendine seçtiğin insanın üzerinde olsun!'),
(1998603,68,19,80,18,'O zaman senden asla ayrılmayacağız; 2 Yaşam ver bize, adını analım!'),
(1998604,68,19,80,19,'Ya RAB, ey Her Şeye Egemen Tanrı, 2 Bizi eski halimize kavuştur, 2 Yüzünün ışığıyla aydınlat, kurtulalım!'),
(1998605,68,19,81,1,'Sevincinizi dile getirin gücümüz olan Tanrıya, 2 Sevinç çığlıkları atın Yakupun Tanrısına!'),
(1998606,68,19,81,2,'Çalgıya başlayın, tef çalın, 2 Tatlı sesli lir ve çenk çınlatın.'),
(1998607,68,19,81,3,'Yeni Ayda, dolunayda, 2 Boru çalın bayram günümüzde.'),
(1998608,68,19,81,4,'Çünkü bu İsrail için bir kuraldır, 2 Yakupun Tanrısının ilkesidir.'),
(1998609,68,19,81,5,'Tanrı Mısıra karşı yürüdüğünde, 2 Yusuf soyuna koydu bu koşulu. Orada tanımadığım bir ses işittim:'),
(1998610,68,19,81,6,'‹‹Sırtındaki yükü kaldırdım, 2 Ellerin küfeden kurtuldu›› diyordu,'),
(1998611,68,19,81,7,'‹‹Sıkıntıya düşünce seslendin, seni kurtardım, 2 Gök gürlemesinin ardından sana yanıt verdim, 2 Meriva sularında seni sınadım. |iSela'),
(1998612,68,19,81,8,'‹‹Dinle, ey halkım, seni uyarıyorum; 2 Ey İsrail, keşke beni dinlesen!'),
(1998613,68,19,81,9,'Aranızda yabancı ilah olmasın, 2 Başka bir ilaha tapmayın!'),
(1998614,68,19,81,10,'Seni Mısırdan çıkaran 2 Tanrın RAB benim. 2 Ağzını iyice aç, doldurayım!'),
(1998615,68,19,81,11,'‹‹Ama halkım sesimi dinlemedi, 2 İsrail bana boyun eğmek istemedi.'),
(1998616,68,19,81,12,'Ben de onları inatçı yürekleriyle baş başa bıraktım, 2 Bildikleri gibi yaşasınlar diye.'),
(1998617,68,19,81,13,'Keşke halkım beni dinleseydi, 2 İsrail yollarımda yürüseydi!'),
(1998618,68,19,81,14,'Düşmanlarını hemen yere serer, 2 Hasımlarına el kaldırırdım!'),
(1998619,68,19,81,15,'Benden nefret edenler bana boyun eğerdi, 2 Bu böyle sonsuza dek sürerdi.'),
(1998620,68,19,81,16,'Oysa sizleri en iyi buğdayla besler, 2 Kayadan akan balla doyururdum.››'),
(1998621,68,19,82,1,'Tanrı yerini aldı tanrısal kurulda, 2 Yargısını açıklıyor ilahların ortasında:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998622,68,19,82,2,'‹‹Ne zamana dek haksız karar verecek, 2 Kötüleri kayıracaksınız? |iSela'),
(1998623,68,19,82,3,'Zayıfın, öksüzün davasını savunun, 2 Mazlumun, yoksulun hakkını arayın.'),
(1998624,68,19,82,4,'Zayıfı, düşkünü kurtarın, 2 Onları kötülerin elinden özgür kılın.››'),
(1998625,68,19,82,5,'Bilmiyor, anlamıyorlar, 2 Karanlıkta dolaşıyorlar. Yeryüzünün temelleri sarsılıyor.'),
(1998626,68,19,82,6,'‹‹ ‹Siz ilahlarsınız› diyorum, 2 ‹Yüceler Yücesinin oğullarısınız hepiniz!›'),
(1998627,68,19,82,7,'Yine de insanlar gibi öleceksiniz, 2 Sıradan bir önder gibi düşeceksiniz!››'),
(1998628,68,19,82,8,'Kalk, ey Tanrı, yargıla yeryüzünü! 2 Çünkü bütün uluslar senindir.'),
(1998629,68,19,83,1,'Ey Tanrı, susma, 2 Sessiz, hareketsiz kalma!'),
(1998630,68,19,83,2,'Bak, düşmanların kargaşa çıkarıyor, 2 Senden nefret edenler boy gösteriyor.'),
(1998631,68,19,83,3,'Halkına karşı kurnazlık peşindeler, 2 Koruduğun insanlara dolap çeviriyorlar.'),
(1998632,68,19,83,4,'‹‹Gelin, bu ulusun kökünü kazıyalım›› diyorlar, 2 ‹‹İsrailin adı bir daha anılmasın!››'),
(1998633,68,19,83,5,'Hepsi sözbirliği etmiş, düzen kuruyor, 2 Sana karşı anlaşmaya vardı:'),
(1998634,68,19,83,6,'Edomlular, İsmaililer, 2 Moavlılar, Hacerliler,'),
(1998635,68,19,83,7,'Geval, Ammon, Amalek, 2 Filist ve Sur halkı.'),
(1998636,68,19,83,8,'Asur da onlara katıldı, 2 Lutoğullarına güç verdiler. |iSela'),
(1998637,68,19,83,9,'Onlara Midyana, 2 Kişon Vadisinde Siseraya ve Yavine yaptığını yap:'),
(1998638,68,19,83,10,'Onlar Eyn-Dorda yok oldular, 2 Toprak için gübreye döndüler.'),
(1998639,68,19,83,11,'Onların soylularına Orev ve Zeeve yaptığını, 2 Beylerine Zevah ve Salmunnaya yaptığını yap.'),
(1998640,68,19,83,12,'Onlar: ‹‹Gelin, sahiplenelim 2 Tanrının otlaklarını›› demişlerdi.'),
(1998641,68,19,83,13,'Ey Tanrım, savrulan toza, 2 Rüzgarın sürüklediği saman çöpüne çevir onları!'),
(1998642,68,19,83,14,'Orman yangını gibi, 2 Dağları tutuşturan alev gibi,'),
(1998643,68,19,83,15,'Fırtınanla kovala, 2 Kasırganla dehşete düşür onları!'),
(1998644,68,19,83,16,'Utançla kapla yüzlerini, 2 Sana yönelsinler, ya RAB.'),
(1998645,68,19,83,17,'Sonsuza dek utanç ve dehşet içinde kalsınlar, 2 Rezil olup yok olsunlar.'),
(1998646,68,19,83,18,'Senin adın RAB''dir, 2 Anlasınlar yalnız senin yeryüzüne egemen en yüce Tanrı olduğunu.'),
(1998647,68,19,84,1,'Ey Her Şeye Egemen RAB, 2 Ne kadar severim konutunu!'),
(1998648,68,19,84,2,'Canım senin avlularını özlüyor, 2 İçim çekiyor, 2 Yüreğim, bütün varlığım 2 Sana, yaşayan Tanrıya sevinçle haykırıyor.'),
(1998649,68,19,84,3,'Kuşlar bile bir yuva, 2 Kırlangıç, yavrularını koyacak bir yer buldu 2 Senin sunaklarının yanında, 2 Ey Her Şeye Egemen RAB, Kralım ve Tanrım!'),
(1998650,68,19,84,4,'Ne mutlu senin evinde oturanlara, 2 Seni sürekli överler! |iSela'),
(1998651,68,19,84,5,'Ne mutlu gücünü senden alan insana! 2 Aklı hep Siyonu ziyaret etmekte.'),
(1998652,68,19,84,6,'Baka Vadisinden geçerken, 2 Pınar başına çevirirler orayı, 2 İlk yağmurlar orayı berekete boğar.'),
(1998653,68,19,84,7,'Gittikçe güçlenir, 2 Siyonda Tanrının huzuruna çıkarlar.'),
(1998654,68,19,84,8,'Ya RAB, Her Şeye Egemen Tanrı, duamı dinle, 2 Kulak ver, ey Yakupun Tanrısı! |iSela'),
(1998655,68,19,84,9,'Ey Tanrı, kalkanımıza bak, 2 Meshettiğin krala lütfet!'),
(1998656,68,19,84,10,'Senin avlularında bir gün, 2 Başka yerdeki bin günden iyidir; 2 Kötülerin çadırında yaşamaktansa, 2 Tanrımın evinin eşiğinde durmayı yeğlerim.'),
(1998657,68,19,84,11,'Çünkü RAB Tanrı bir güneş, bir kalkandır. 2 Lütuf ve yücelik sağlar; 2 Dürüstçe yaşayanlardan hiçbir iyiliği esirgemez.'),
(1998658,68,19,84,12,'Ey Her Şeye Egemen RAB, 2 Ne mutlu sana güvenen insana!'),
(1998659,68,19,85,1,'Ya RAB, ülkenden hoşnut kaldın, 2 Yakup soyunu eski gönencine kavuşturdun.'),
(1998660,68,19,85,2,'Halkının suçlarını bağışladın, 2 Bütün günahlarını yok saydın. |iSela'),
(1998661,68,19,85,3,'Bütün gazabını bir yana koydun, 2 Kızgın öfkenden vazgeçtin.'),
(1998662,68,19,85,4,'Ey bizi kurtaran Tanrı, bizi eski halimize getir, 2 Bize karşı öfkeni dindir!'),
(1998663,68,19,85,5,'Sonsuza dek mi öfkeleneceksin bize? 2 Kuşaktan kuşağa mı sürdüreceksin öfkeni?'),
(1998664,68,19,85,6,'Halkın sende sevinç bulsun diye 2 Bize yeniden yaşam vermeyecek misin?'),
(1998665,68,19,85,7,'Ya RAB, sevgini göster bize, 2 Kurtarışını bağışla!'),
(1998666,68,19,85,8,'Kulak vereceğim RAB Tanrının ne diyeceğine; 2 Halkına, sadık kullarına esenlik sözü verecek, 2 Yeter ki, bir daha akılsızlık etmesinler.'),
(1998667,68,19,85,9,'Evet, O kendisinden korkanları kurtarmak üzeredir, 2 Görkemi ülkemizde yaşasın diye.'),
(1998668,68,19,85,10,'Sevgiyle sadakat buluşacak, 2 Doğrulukla esenlik öpüşecek.'),
(1998669,68,19,85,11,'Sadakat yerden bitecek, 2 Doğruluk gökten bakacak.'),
(1998670,68,19,85,12,'Ve RAB iyi olan neyse, onu verecek, 2 Toprağımızdan ürün fışkıracak.'),
(1998671,68,19,85,13,'Doğruluk önüsıra yürüyecek, 2 Adımları için yol yapacak.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998672,68,19,86,1,'Kulak ver, ya RAB, yanıtla beni, 2 Çünkü mazlum ve yoksulum.'),
(1998673,68,19,86,2,'Koru canımı, çünkü senin sadık kulunum. 2 Ey Tanrım, kurtar sana güvenen kulunu!'),
(1998674,68,19,86,3,'Acı bana, ya Rab, 2 Çünkü gün boyu sana yakarıyorum.'),
(1998675,68,19,86,4,'Sevindir kulunu, ya Rab, 2 Çünkü dualarımı sana yükseltiyorum.'),
(1998676,68,19,86,5,'Sen iyi ve bağışlayıcısın, ya Rab, 2 Sana yakaran herkese bol sevgi gösterirsin.'),
(1998677,68,19,86,6,'Kulak ver duama, ya RAB, 2 Yalvarışlarımı dikkate al!'),
(1998678,68,19,86,7,'Sıkıntılı günümde sana yakarırım, 2 Çünkü yanıtlarsın beni.'),
(1998679,68,19,86,8,'İlahlar arasında senin gibisi yok, ya Rab, 2 Eşsizdir işlerin.'),
(1998680,68,19,86,9,'Yarattığın bütün uluslar gelip 2 Sana tapınacaklar, ya Rab, 2 Adını yüceltecekler.'),
(1998681,68,19,86,10,'Çünkü sen ulusun, harikalar yaratırsın, 2 Tek Tanrı sensin.'),
(1998682,68,19,86,11,'Ya RAB, yolunu bana öğret, 2 Senin gerçeğine göre yürüyeyim, 2 Kararlı kıl beni, yalnız senin adından korkayım.'),
(1998683,68,19,86,12,'Ya Rab Tanrım, bütün yüreğimle sana şükredeceğim, 2 Adını sonsuza dek yücelteceğim.'),
(1998684,68,19,86,13,'Çünkü bana sevgin büyüktür, 2 Canımı ölüler diyarının derinliklerinden sen kurtardın.'),
(1998685,68,19,86,14,'Ey Tanrı, küstahlar bana saldırıyor, 2 Zorbalar sürüsü, sana aldırmayanlar 2 Canımı almak istiyor,'),
(1998686,68,19,86,15,'Oysa sen, ya Rab, 2 Sevecen, lütfeden, tez öfkelenmeyen, 2 Sevgisi ve sadakati bol bir Tanrısın.'),
(1998687,68,19,86,16,'Yönel bana, acı halime, 2 Kuluna kendi gücünü ver, 2 Kurtar hizmetçinin oğlunu.'),
(1998688,68,19,86,17,'İyiliğinin bir belirtisini göster bana; 2 Benden nefret edenler görüp utansın; 2 Çünkü sen, ya RAB, bana yardım ettin, 2 Beni avuttun.'),
(1998689,68,19,87,1,'RAB Siyonu kutsal dağlar üzerine kurdu.'),
(1998690,68,19,87,2,'Siyonun kapılarını 2 Yakup soyunun bütün konutlarından daha çok sever.'),
(1998691,68,19,87,3,'Ey Tanrı kenti, senin için ne yüce sözler söylenir: |iSela'),
(1998692,68,19,87,4,'‹‹Beni tanıyanlar arasında 2 Rahav ve Babili anacağım, 2 Filisti, Suru, Kûşu da; 2 ‹Bu da Siyonda doğdu› diyeceğim.››'),
(1998693,68,19,87,5,'Evet, Siyon için şöyle denecek: 2 ‹‹Şu da orada doğmuş, bu da, 2 Yüceler Yücesi onu sarsılmaz kılacak.››'),
(1998694,68,19,87,6,'RAB halkları kaydederken, 2 ‹‹Bu da Siyonda doğmuş›› diye yazacak. |iSela'),
(1998695,68,19,87,7,'Okuyucular, kavalcılar, 2 ‹‹Bütün kaynaklarım sendedir!›› diyecek.'),
(1998696,68,19,88,1,'Ya RAB, beni kurtaran Tanrı, 2 Gece gündüz sana yakarıyorum.'),
(1998697,68,19,88,2,'Duam sana erişsin, 2 Kulak ver yakarışıma.'),
(1998698,68,19,88,3,'Çünkü sıkıntıya doydum, 2 Canım ölüler diyarına yaklaştı.'),
(1998699,68,19,88,4,'Ölüm çukuruna inenler arasında sayılıyorum, 2 Tükenmiş gibiyim;'),
(1998700,68,19,88,5,'Ölüler arasına atılmış, 2 Artık anımsamadığın, 2 İlginden yoksun, 2 Mezarda yatan cesetler gibiyim.'),
(1998701,68,19,88,6,'Beni çukurun dibine, 2 Karanlıklara, derinliklere attın.'),
(1998702,68,19,88,7,'Öfken üzerime çöktü, 2 Dalga dalga kızgınlığınla beni ezdin. |iSela'),
(1998703,68,19,88,8,'Yakınlarımı benden uzaklaştırdın, 2 İğrenç kıldın beni gözlerinde. 2 Kapalı kaldım, çıkamıyorum.'),
(1998704,68,19,88,9,'Üzüntüden gözlerimin feri sönüyor, 2 Her gün sana yakarıyorum, ya RAB, 2 Ellerimi sana açıyorum.'),
(1998705,68,19,88,10,'Harikalarını ölülere mi göstereceksin? 2 Ölüler mi kalkıp seni övecek? |iSela'),
(1998706,68,19,88,11,'Sevgin mezarda, 2 Sadakatin yıkım diyarında duyurulur mu?'),
(1998707,68,19,88,12,'Karanlıklarda harikaların, 2 Unutulmuşluk diyarında doğruluğun bilinir mi?'),
(1998708,68,19,88,13,'Ama ben, ya RAB, yardıma çağırıyorum seni, 2 Sabah duam sana varıyor.'),
(1998709,68,19,88,14,'Niçin beni reddediyorsun, ya RAB, 2 Neden yüzünü benden gizliyorsun?'),
(1998710,68,19,88,15,'Düşkünüm, gençliğimden beri ölümle burun burunayım, 2 Dehşetlerinin altında tükendim.'),
(1998711,68,19,88,16,'Şiddetli gazabın üzerimden geçti, 2 Saçtığın dehşet beni yedi bitirdi.'),
(1998712,68,19,88,17,'Bütün gün su gibi kuşattılar beni, 2 Çevremi tümüyle sardılar.'),
(1998713,68,19,88,18,'Eşi dostu benden uzaklaştırdın, 2 Tek dostum karanlık kaldı.'),
(1998714,68,19,89,1,'RABbin sevgisini sonsuza dek ezgilerle öveceğim, 2 Sadakatini bütün kuşaklara bildireceğim.'),
(1998715,68,19,89,2,'Sevgin sonsuza dek ayakta kalır diyeceğim, 2 Sadakatini gökler kadar kalıcı kıldın.'),
(1998716,68,19,89,3,'Dedin ki, ‹‹Seçtiğim adamla antlaşma yaptım, 2 Kulum Davuta şöyle ant içtim:'),
(1998717,68,19,89,4,'‹Soyunu sonsuza dek sürdüreceğim, 2 Tahtını kuşaklar boyunca sürekli kılacağım.› ›› |iSela'),
(1998718,68,19,89,5,'Ya RAB, gökler över harikalarını, 2 Kutsallar topluluğunda övülür sadakatin.'),
(1998719,68,19,89,6,'Çünkü göklerde RABbe kim eş koşulur? 2 Kim benzer RABbe ilahi varlıklar arasında?'),
(1998720,68,19,89,7,'Kutsallar topluluğunda Tanrı korku uyandırır, 2 Çevresindekilerin hepsinden ulu ve müthiştir.'),
(1998721,68,19,89,8,'Ya RAB, Her Şeye Egemen Tanrı, 2 Senin gibi güçlü RAB var mı? 2 Sadakatin çevreni sarar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998722,68,19,89,9,'Sen kudurmuş denizler üzerinde egemenlik sürer, 2 Dalgalar kabardıkça onları dindirirsin.'),
(1998723,68,19,89,10,'Sen Rahavı leş ezer gibi ezdin, 2 Güçlü kolunla düşmanlarını dağıttın. düşmanları kastediyor.'),
(1998724,68,19,89,11,'Gökler senindir, yeryüzü de senin; 2 Dünyanın ve içindeki her şeyin temelini sen attın.'),
(1998725,68,19,89,12,'Kuzeyi, güneyi sen yarattın, 2 Tavor ve Hermon dağları 2 Sana sevincini dile getiriyor.'),
(1998726,68,19,89,13,'Kolun güçlüdür, 2 Elin kudretli, sağ elin yüce.'),
(1998727,68,19,89,14,'Tahtın adalet ve doğruluk üzerine kurulu, 2 Sevgi ve sadakat önünsıra gider.'),
(1998728,68,19,89,15,'Ne mutlu sevinç çığlıkları atmasını bilen halka, ya RAB! 2 Yüzünün ışığında yürürler.'),
(1998729,68,19,89,16,'Gün boyu senin adınla sevinir, 2 Doğruluğunla yücelirler.'),
(1998730,68,19,89,17,'Çünkü sen onların gücü ve yüceliğisin, 2 Lütfun sayesinde gücümüz artar.'),
(1998731,68,19,89,18,'Kalkanımız RABbe, 2 Kralımız İsrailin Kutsalına aittir.'),
(1998732,68,19,89,19,'Geçmişte bir görüm aracılığıyla, 2 Sadık kullarına şöyle dedin: 2 ‹‹Bir yiğide yardım ettim, 2 Halkın içinden bir genci yükselttim.'),
(1998733,68,19,89,20,'Kulum Davutu buldum, 2 Kutsal yağımla onu meshettim.'),
(1998734,68,19,89,21,'Elim ona destek olacak, 2 Kolum güç verecek.'),
(1998735,68,19,89,22,'Düşman onu haraca bağlayamayacak, 2 Kötüler onu ezmeyecek.'),
(1998736,68,19,89,23,'Düşmanlarını onun önünde kıracağım, 2 Ondan nefret edenleri vuracağım.'),
(1998737,68,19,89,24,'Sadakatim, sevgim ona destek olacak, 2 Benim adımla gücü yükselecek.'),
(1998738,68,19,89,25,'Sağ elini denizin, 2 Irmakların üzerine egemen kılacağım.'),
(1998739,68,19,89,26,'‹Babam sensin› diye seslenecek bana, 2 ‹Tanrım, kurtuluşumun kayası.›'),
(1998740,68,19,89,27,'Ben de onu ilk oğlum, 2 Dünyadaki kralların en yücesi kılacağım.'),
(1998741,68,19,89,28,'Sonsuza dek ona sevgi göstereceğim, 2 Onunla yaptığım antlaşma hiç bozulmayacak.'),
(1998742,68,19,89,29,'Soyunu sonsuza dek, 2 Tahtını gökler durduğu sürece sürdüreceğim.'),
(1998743,68,19,89,30,'‹‹Çocukları yasamdan ayrılır, 2 İlkelerime göre yaşamazsa;'),
(1998744,68,19,89,31,'Kurallarımı bozar, 2 Buyruklarıma uymazsa,'),
(1998745,68,19,89,32,'İsyanlarını sopayla, 2 Suçlarını dayakla cezalandıracağım.'),
(1998746,68,19,89,33,'Ama onu sevmekten vazgeçmeyecek, 2 Sadakatime sırt çevirmeyeceğim.'),
(1998747,68,19,89,34,'Antlaşmamı bozmayacak, 2 Ağzımdan çıkan sözü değiştirmeyeceğim.'),
(1998748,68,19,89,35,'Bir kez kutsallığım üstüne ant içtim, 2 Davuta yalan söylemeyeceğim.'),
(1998749,68,19,89,36,'Onun soyu sonsuza dek sürecek, 2 Tahtı karşımda güneş gibi duracak,'),
(1998750,68,19,89,37,'Göklerde güvenilir bir tanık olan ay gibi 2 Sonsuza dek kalacak.›› |iSela'),
(1998751,68,19,89,38,'Ama sen reddettin, sırt çevirdin, 2 Çok öfkelendin meshettiğin krala.'),
(1998752,68,19,89,39,'Kulunla yaptığın antlaşmadan vazgeçtin, 2 Onun tacını yere atıp kirlettin.'),
(1998753,68,19,89,40,'Yıktın bütün surlarını, 2 Viran ettin kalelerini.'),
(1998754,68,19,89,41,'Yoldan geçen herkes onu yağmaladı, 2 Yüzkarası oldu komşularına.'),
(1998755,68,19,89,42,'Hasımlarının sağ elini onun üstüne kaldırdın, 2 Bütün düşmanlarını sevindirdin.'),
(1998756,68,19,89,43,'Kılıcının ağzını başka yöne çevirdin, 2 Savaşta ona yan çıkmadın.'),
(1998757,68,19,89,44,'Görkemine son verdin, 2 Tahtını yere çaldın.'),
(1998758,68,19,89,45,'Gençlik günlerini kısalttın, 2 Onu utanca boğdun. |iSela'),
(1998759,68,19,89,46,'Ne zamana dek, ya RAB? 2 Sonsuza dek mi gizleneceksin? 2 Ne zamana dek öfken alev alev yanacak?'),
(1998760,68,19,89,47,'Anımsa ömrümün ne çabuk geçtiğini, 2 Ne boş yaratmışsın insanoğlunu!'),
(1998761,68,19,89,48,'Var mı yaşayıp da ölümü görmeyen, 2 Ölüler diyarının pençesinden canını kurtaran? |iSela'),
(1998762,68,19,89,49,'Ya Rab, nerede o eski sevgin? 2 Davuta göstereceğine ant içtiğin o sadık sevgin!'),
(1998763,68,19,89,50,'Anımsa, ya Rab, kullarının nasıl rezil olduğunu, 2 Bütün halkların hakaretini bağrımda nasıl taşıdığımı, 2 Düşmanlarının hakaretini, ya RAB, 2 Meshettiğin kralın attığı adıma edilen hakaretleri.'),
(1998764,68,19,89,52,'Sonsuza dek övgüler olsun RAB''be! 2 Amin! Amin!'),
(1998765,68,19,90,1,'Ya Rab, barınak oldun bize 2 Kuşaklar boyunca.'),
(1998766,68,19,90,2,'Dağlar var olmadan, 2 Daha evreni ve dünyayı yaratmadan, 2 Öncesizlikten sonsuzluğa dek Tanrı sensin.'),
(1998767,68,19,90,3,'İnsanı toprağa döndürürsün, 2 ‹‹Ey insanoğulları, toprağa dönün!›› diyerek.'),
(1998768,68,19,90,4,'Çünkü senin gözünde bin yıl 2 Geçmiş bir gün, dün gibi, 2 Bir gece nöbeti gibidir.'),
(1998769,68,19,90,5,'İnsanları bir düş gibi siler, süpürürsün, 2 Sabah biten ot misali:'),
(1998770,68,19,90,6,'Sabah filizlenir, büyür, 2 Akşam solar, kurur.'),
(1998771,68,19,90,7,'Eriyip bitiyoruz senin öfkenden, 2 Kızgınlığından dehşete düşüyoruz.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998772,68,19,90,8,'Suçlarımızı önüne, 2 Gizli günahlarımızı yüzünün ışığına çıkardın.'),
(1998773,68,19,90,9,'Gazabından kısalıyor günlerimiz, 2 Bir soluk gibi tükeniyor yıllarımız.'),
(1998774,68,19,90,10,'Ömrümüz yetmiş yıl sürüyor, 2 Bilemedin seksen, o da sağlıklıysak; 2 En güzel yıllar da zahmetle, kederle geçiyor, 2 Çabucak bitiyor, uçup gidiyoruz.'),
(1998775,68,19,90,11,'Kim bilir gazabının gücünü? 2 Çünkü öfken sana duyulan korku kadar güçlüdür.'),
(1998776,68,19,90,12,'Bu yüzden günlerimizi saymayı bize öğret ki, 2 Bilgelik kazanalım.'),
(1998777,68,19,90,13,'Vazgeç, ya RAB! Öfken ne zamana dek sürecek? 2 Acı kullarına!'),
(1998778,68,19,90,14,'Sabah bizi sevginle doyur, 2 Ömrümüz boyunca sevinçle haykıralım.'),
(1998779,68,19,90,15,'Kaç gün bizi sıkıntıya soktunsa, 2 Kaç yıl çile çektirdinse, 2 O kadar sevindir bizi.'),
(1998780,68,19,90,16,'Yaptıkların kullarına, 2 Görkemin onların çocuklarına görünsün.'),
(1998781,68,19,90,17,'Tanrımız Rab bizden hoşnut kalsın. 2 Ellerimizin emeğini boşa çıkarma. 2 Evet, ellerimizin emeğini boşa çıkarma.'),
(1998782,68,19,91,1,'Yüceler Yücesinin barınağında oturan, 2 Her Şeye Gücü Yetenin gölgesinde barınır.'),
(1998783,68,19,91,2,'‹‹O benim sığınağım, kalemdir›› derim RAB için, 2 ‹‹Tanrımdır, Ona güvenirim.››'),
(1998784,68,19,91,3,'Çünkü O seni avcı tuzağından, 2 Ölümcül hastalıktan kurtarır.'),
(1998785,68,19,91,4,'Seni kanatlarının altına alır, 2 Onların altına sığınırsın. 2 Onun sadakati senin kalkanın, siperin olur.'),
(1998786,68,19,91,5,'Ne gecenin dehşetinden korkarsın, 2 Ne gündüz uçan oktan, 2 Ne karanlıkta dolaşan hastalıktan, 2 Ne de öğleyin yok eden kırgından.'),
(1998787,68,19,91,7,'Yanında bin kişi, 2 Sağında on bin kişi kırılsa bile, 2 Sana dokunmaz.'),
(1998788,68,19,91,8,'Sen yalnız kendi gözlerinle seyredecek, 2 Kötülerin cezasını göreceksin.'),
(1998789,68,19,91,9,'Sen RABbi kendine sığınak, 2 Yüceler Yücesini konut edindiğin için,'),
(1998790,68,19,91,10,'Başına kötülük gelmeyecek, 2 Çadırına felaket yaklaşmayacak.'),
(1998791,68,19,91,11,'Çünkü Tanrı meleklerine buyruk verecek, 2 Gideceğin her yerde seni korusunlar diye.'),
(1998792,68,19,91,12,'Elleri üzerinde taşıyacaklar seni, 2 Ayağın bir taşa çarpmasın diye.'),
(1998793,68,19,91,13,'Aslanın, kobranın üzerine basıp geçeceksin, 2 Genç aslanı, yılanı çiğneyeceksin.'),
(1998794,68,19,91,14,'‹‹Beni sevdiği için 2 Onu kurtaracağım›› diyor RAB, 2 ‹‹Beni iyi tanıdığı için 2 Ona kale olacağım.'),
(1998795,68,19,91,15,'Bana seslenince onu yanıtlayacağım, 2 Sıkıntıda onun yanında olacağım, 2 Kurtarıp yücelteceğim onu.'),
(1998796,68,19,91,16,'Onu uzun ömürle doyuracak, 2 Ona kurtarışımı göstereceğim.››'),
(1998797,68,19,92,1,'Ya RAB, sana şükretmek, 2 Ey Yüceler Yücesi, adını ilahilerle övmek, 2 Sabah sevgini, 2 Gece sadakatini, 2 On telli sazla, çenk ve lirle duyurmak ne güzel!'),
(1998798,68,19,92,4,'Çünkü yaptıklarınla beni sevindirdin, ya RAB, 2 Ellerinin işi karşısında sevinç ilahileri okuyorum.'),
(1998799,68,19,92,5,'Yaptıkların ne büyüktür, ya RAB, 2 Düşüncelerin ne derin!'),
(1998800,68,19,92,6,'Aptal insan bilemez, 2 Budala akıl erdiremez:'),
(1998801,68,19,92,7,'Kötüler mantar gibi bitse, 2 Suçlular pıtrak gibi açsa bile, 2 Bu onların sonsuza dek yok oluşu demektir.'),
(1998802,68,19,92,8,'Ama sen sonsuza dek yücesin, ya RAB.'),
(1998803,68,19,92,9,'Ya RAB, düşmanların kesinlikle, 2 Evet, kesinlikle yok olacak, 2 Suç işleyen herkes dağılacak.'),
(1998804,68,19,92,10,'Beni yaban öküzü kadar güçlü kıldın, 2 Taze zeytinyağını başıma döktün.'),
(1998805,68,19,92,11,'Gözlerim düşmanlarımın bozgununu gördü, 2 Kulaklarım bana saldıran kötülerin sonunu duydu.'),
(1998806,68,19,92,12,'Doğru insan hurma ağacı gibi serpilecek, 2 Lübnan sediri gibi yükselecek.'),
(1998807,68,19,92,13,'RABbin evinde dikilmiş, 2 Tanrımızın avlularında serpilecek.'),
(1998808,68,19,92,14,'Böyleleri yaşlanınca da meyve verecek, 2 Taptaze ve yeşil kalacaklar.'),
(1998809,68,19,92,15,'‹‹RAB doğrudur! Kayamdır benim! 2 O''nda haksızlık bulunmaz!›› diye duyuracaklar.'),
(1998810,68,19,93,1,'RAB egemenlik sürüyor, görkeme bürünmüş, 2 Kudret giyinip kuşanmış. 2 Dünya sağlam kurulmuş, sarsılmaz.'),
(1998811,68,19,93,2,'Ya RAB, tahtın öteden beri kurulmuş, 2 Varlığın öncesizliğe uzanır.'),
(1998812,68,19,93,3,'Denizler gürlüyor, ya RAB, 2 Denizler gümbür gümbür gürlüyor, 2 Denizler dalgalarını çınlatıyor.'),
(1998813,68,19,93,4,'Yücelerdeki RAB engin suların gürleyişinden, 2 Denizlerin azgın dalgalarından 2 Daha güçlüdür.'),
(1998814,68,19,93,5,'Koşulların hep geçerlidir; 2 Tapınağına kutsallık yaraşır 2 Sonsuza dek, ya RAB.'),
(1998815,68,19,94,1,'Ya RAB, öç alıcı Tanrı, 2 Saç ışığını, ey öç alıcı Tanrı!'),
(1998816,68,19,94,2,'Kalk, ey yeryüzünün yargıcı, 2 Küstahlara hak ettikleri cezayı ver!'),
(1998817,68,19,94,3,'Kötüler ne zamana dek, ya RAB, 2 Ne zamana dek sevinip coşacak?'),
(1998818,68,19,94,4,'Ağızlarından küstahlık dökülüyor, 2 Suç işleyen herkes övünüyor.'),
(1998819,68,19,94,5,'Halkını eziyorlar, ya RAB, 2 Kendi halkına eziyet ediyorlar.'),
(1998820,68,19,94,6,'Dulu, garibi boğazlıyor, 2 Öksüzleri öldürüyorlar.'),
(1998821,68,19,94,7,'‹‹RAB görmez›› diyorlar, 2 ‹‹Yakupun Tanrısı dikkat etmez.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998822,68,19,94,8,'Ey halkın içindeki budalalar, dikkat edin; 2 Ey aptallar, ne zaman akıllanacaksınız?'),
(1998823,68,19,94,9,'Kulağı yaratan işitmez mi? 2 Göze biçim veren görmez mi?'),
(1998824,68,19,94,10,'Ulusları yola getiren yargılamaz mı? 2 İnsanı eğiten bilmez mi?'),
(1998825,68,19,94,11,'RAB insanın düşüncelerinin 2 Boş olduğunu bilir.'),
(1998826,68,19,94,12,'Ne mutlu, ya RAB, yola getirdiğin, 2 Yasanı öğrettiğin insana!'),
(1998827,68,19,94,13,'Kötüler için çukur kazılıncaya dek, 2 Onu sıkıntılı günlerden kurtarıp rahatlatırsın.'),
(1998828,68,19,94,14,'Çünkü RAB halkını reddetmez, 2 Kendi halkını terk etmez.'),
(1998829,68,19,94,15,'Adalet yine doğruluk üzerine kurulacak, 2 Yüreği temiz olan herkes ona uyacak.'),
(1998830,68,19,94,16,'Kötülere karşı beni kim savunacak? 2 Kim benim için suçlulara karşı duracak?'),
(1998831,68,19,94,17,'RAB yardımcım olmasaydı, 2 Şimdiye dek sessizlik diyarına göçmüştüm bile.'),
(1998832,68,19,94,18,'‹‹Ayağım kayıyor›› dediğimde, 2 Sevgin ayakta tutar beni, ya RAB.'),
(1998833,68,19,94,19,'Kaygılar içimi sarınca, 2 Senin avutmaların gönlümü sevindirir.'),
(1998834,68,19,94,20,'Yasaya dayanarak haksızlık yapan koltuk sahibi 2 Seninle bağdaşır mı?'),
(1998835,68,19,94,21,'Onlar doğruya karşı birleşiyor, 2 Suçsuzu ölüme mahkûm ediyorlar.'),
(1998836,68,19,94,22,'Ama RAB bana kale oldu, 2 Tanrım sığındığım kaya oldu.'),
(1998837,68,19,94,23,'Tanrımız RAB yaptıkları kötülüğü 2 Kendi başlarına getirecek, 2 Kötülükleri yüzünden köklerini kurutacak, 2 Evet, köklerini kurutacak.'),
(1998838,68,19,95,1,'Gelin, RABbe sevinçle haykıralım, 2 Bizi kurtaran kayaya sevinç çığlıkları atalım,'),
(1998839,68,19,95,2,'Şükranla huzuruna çıkalım, 2 Ona sevinç ilahileri yükseltelim!'),
(1998840,68,19,95,3,'Çünkü RAB ulu Tanrıdır, 2 Bütün ilahların üstünde ulu kraldır.'),
(1998841,68,19,95,4,'Yerin derinlikleri Onun elindedir, 2 Dağların dorukları da Onun.'),
(1998842,68,19,95,5,'Deniz Onundur, çünkü O yarattı, 2 Karaya da Onun elleri biçim verdi.'),
(1998843,68,19,95,6,'Gelin, tapınalım, eğilelim, 2 Bizi yaratan RABbin önünde diz çökelim.'),
(1998844,68,19,95,7,'Çünkü O Tanrımızdır, 2 Bizse Onun otlağının halkı, 2 Elinin altındaki koyunlarız. Bugün sesini duyarsanız,'),
(1998845,68,19,95,8,'Merivada, o gün çölde, Massadafö olduğu gibi, 2 Yüreklerinizi nasırlaştırmayın.'),
(1998846,68,19,95,9,'Yaptıklarımı görmelerine karşın, 2 Atalarınız orada beni sınayıp denediler.'),
(1998847,68,19,95,10,'Kırk yıl o kuşaktan hep iğrendim, 2 ‹‹Yüreği kötü yola sapan bir halktır›› dedim, 2 ‹‹Yollarımı bilmiyorlar.››'),
(1998848,68,19,95,11,'Bu yüzden öfkeyle ant içtim: 2 ‹‹Huzur diyarıma asla girmeyecekler!›› Say.14:26-35; İbr.4:1-7).'),
(1998849,68,19,96,1,'Yeni bir ezgi söyleyin RABbe! 2 Ey bütün dünya, RABbe ezgiler söyleyin!'),
(1998850,68,19,96,2,'Ezgi söyleyin, RABbin adını övün, 2 Her gün duyurun kurtarışını!'),
(1998851,68,19,96,3,'Görkemini uluslara, 2 Harikalarını bütün halklara anlatın!'),
(1998852,68,19,96,4,'Çünkü RAB uludur, yalnız O övgüye değer, 2 İlahlardan çok Ondan korkulur.'),
(1998853,68,19,96,5,'Halkların bütün ilahları bir hiçtir, 2 Oysa gökleri yaratan RABdir.'),
(1998854,68,19,96,6,'Yücelik, ululuk Onun huzurundadır, 2 Güç ve güzellik Onun tapınağındadır.'),
(1998855,68,19,96,7,'Ey bütün halklar, RABbi övün, 2 RABbin gücünü, yüceliğini övün,'),
(1998856,68,19,96,8,'RABbin görkemini adına yaraşır biçimde övün, 2 Sunular getirip avlularına girin!'),
(1998857,68,19,96,9,'Kutsal giysiler içinde RABbe tapının! 2 Titreyin Onun önünde, ey bütün yeryüzündekiler!'),
(1998858,68,19,96,10,'Uluslara, ‹‹RAB egemenlik sürüyor›› deyin. 2 Dünya sağlam kurulmuş, sarsılmaz. 2 O halkları adaletle yargılar.'),
(1998859,68,19,96,11,'Sevinsin gökler, coşsun yeryüzü! 2 Gürlesin deniz içindekilerle birlikte!'),
(1998860,68,19,96,12,'Bayram etsin kırlar ve üzerindekiler! 2 O zaman RAB''bin önünde bütün orman ağaçları 2 Sevinçle haykıracak. 2 Çünkü O geliyor! 2 Yeryüzünü yargılamaya geliyor. 2 Dünyayı adaletle, 2 Halkları kendi gerçeğiyle yönetecek.'),
(1998861,68,19,97,1,'RAB egemenlik sürüyor, coşsun yeryüzü, 2 Bütün kıyı halkları sevinsin!'),
(1998862,68,19,97,2,'Bulut ve zifiri karanlık sarmış çevresini, 2 Doğruluk ve adalettir tahtının temeli.'),
(1998863,68,19,97,3,'Ateş yürüyor Onun önünde, 2 Düşmanlarını yakıyor çevrede.'),
(1998864,68,19,97,4,'Şimşekleri dünyayı aydınlatır, 2 Yeryüzü görüp titrer.'),
(1998865,68,19,97,5,'Dağlar balmumu gibi erir, 2 RABbin, bütün yeryüzünün Rabbi önünde.'),
(1998866,68,19,97,6,'Gökler Onun doğruluğunu duyurur, 2 Bütün halklar görkemini görür.'),
(1998867,68,19,97,7,'Utansın puta tapanlar, 2 Değersiz putlarla övünenler! 2 RABbe tapın, ey bütün ilahlar!'),
(1998868,68,19,97,8,'Siyon seviniyor yargılarını duyunca, ya RAB, 2 Yahuda kentleri coşuyor.'),
(1998869,68,19,97,9,'Çünkü sensin, ya RAB, bütün yeryüzünün en yücesi, 2 Bütün ilahların üstündesin, çok ulusun.'),
(1998870,68,19,97,10,'Ey sizler, RABbi sevenler, kötülükten tiksinin. 2 O sadık kullarının canını korur, 2 Onları kötülerin elinden kurtarır.'),
(1998871,68,19,97,11,'Doğrulara ışık, 2 Temiz yüreklilere sevinç saçar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998872,68,19,97,12,'Ey doğrular, RAB''de sevinç bulun, 2 Kutsallığını anarak O''na şükredin!'),
(1998873,68,19,98,1,'Yeni bir ezgi söyleyin RABbe. 2 Çünkü harikalar yaptı, 2 Zaferler kazandı sağ eli ve kutsal koluyla.'),
(1998874,68,19,98,2,'RAB ulusların gözü önüne serdi kurtarışını, 2 Zaferini bildirdi.'),
(1998875,68,19,98,3,'İsrail halkına sevgisini, 2 Sadakatini anımsadı; 2 Tanrımızın zaferini gördü dünyanın dört bucağı.'),
(1998876,68,19,98,4,'Sevinç çığlıkları yükseltin RABbe, ey yeryüzündekiler! 2 Sevinç ilahileriyle yeri göğü çınlatın!'),
(1998877,68,19,98,5,'Lirle ezgiler sunun RABbe, 2 Lir ve müzik eşliğinde!'),
(1998878,68,19,98,6,'Boru ve borazan eşliğinde 2 Sevinç çığlıkları atın Kral olan RABbin önünde.'),
(1998879,68,19,98,7,'Gürlesin deniz ve içindekiler, 2 Gürlesin yeryüzü ve üzerindekiler.'),
(1998880,68,19,98,8,'El çırpsın ırmaklar, 2 Sevinçle haykırsın dağlar 2 RAB''bin önünde! 2 Çünkü O geliyor 2 Yeryüzünü yönetmeye. 2 Dünyayı adaletle, 2 Halkları doğrulukla yönetecek.'),
(1998881,68,19,99,1,'RAB egemenlik sürüyor, titresin halklar! 2 Keruvlar arasında tahtına oturmuş, 2 Sarsılsın yeryüzü!'),
(1998882,68,19,99,2,'RAB Siyonda uludur, 2 Yücedir O, bütün halklara egemendir.'),
(1998883,68,19,99,3,'Övsünler büyük, müthiş adını! 2 O kutsaldır.'),
(1998884,68,19,99,4,'Ey adaleti seven güçlü kral, 2 Eşitliği sen sağladın, 2 Yakup soyunda doğru ve adil olanı sen yaptın.'),
(1998885,68,19,99,5,'Yüceltin Tanrımız RABbi, 2 Ayaklarının taburesi önünde tapının! 2 O kutsaldır.'),
(1998886,68,19,99,6,'Musayla Harun Onun kâhinlerindendi, 2 Samuel de Onu adıyla çağıranlar arasındaydı. 2 RABbe seslenirlerdi, 2 O da yanıtlardı.'),
(1998887,68,19,99,7,'Bulut sütunu içinden onlarla konuştu, 2 Uydular Onun buyruklarına, 2 Kendilerine verdiği kurallara.'),
(1998888,68,19,99,8,'Ya RAB Tanrımız, yanıt verdin onlara; 2 Bağışlayıcı bir Tanrı oldun, 2 Ama yaptıkları kötülüğü cezasız bırakmadın.'),
(1998889,68,19,99,9,'Tanrımız RAB''bi yüceltin, 2 Tapının O''na kutsal dağında! 2 Çünkü Tanrımız RAB kutsaldır.'),
(1998890,68,19,100,1,'Ey bütün dünya, RABbe sevinç çığlıkları yükseltin!'),
(1998891,68,19,100,2,'Ona neşeyle kulluk edin, 2 Sevinç ezgileriyle çıkın huzuruna!'),
(1998892,68,19,100,3,'Bilin ki RAB Tanrıdır. 2 Bizi yaratan Odur, biz de Onunuz, 2 Onun halkı, otlağının koyunlarıyız.'),
(1998893,68,19,100,4,'Kapılarına şükranla, 2 Avlularına övgüyle girin! 2 Şükredin Ona, adına övgüler sunun!'),
(1998894,68,19,100,5,'Çünkü RAB iyidir, 2 Sevgisi sonsuzdur. 2 Sadakati kuşaklar boyunca sürer.'),
(1998895,68,19,101,1,'Sevgini ve adaletini ezgilerle anacağım, 2 Seni ilahilerle öveceğim, ya RAB.'),
(1998896,68,19,101,2,'Dürüst davranmaya özen göstereceğim, 2 Ne zaman geleceksin bana? Temiz bir yaşam süreceğim evimde,'),
(1998897,68,19,101,3,'Önümde alçaklığa izin vermeyeceğim. 2 Tiksinirim döneklerin işinden, 2 Etkilemez beni.'),
(1998898,68,19,101,4,'Uzak olsun benden sapıklık, 2 Tanımak istemem kötülüğü.'),
(1998899,68,19,101,5,'Yok ederim dostunu gizlice çekiştireni, 2 Katlanamam tepeden bakan, gururlu insana.'),
(1998900,68,19,101,6,'Gözüm ülkenin sadık insanları üzerinde olacak, 2 Yanımda oturmalarını isterim; 2 Bana dürüst yaşayan kişi hizmet edecek.'),
(1998901,68,19,101,7,'Dolap çeviren evimde oturmayacak, 2 Yalan söyleyen gözümün önünde durmayacak.'),
(1998902,68,19,101,8,'Her sabah ülkedeki kötüleri yok ederek 2 Bütün haksızları RAB''bin kentinden söküp atacağım.'),
(1998903,68,19,102,1,'Ya RAB, duamı işit, 2 Yakarışım sana erişsin.'),
(1998904,68,19,102,2,'Sıkıntılı günümde yüzünü benden gizleme, 2 Kulak ver sesime, 2 Seslenince yanıt ver bana hemen.'),
(1998905,68,19,102,3,'Çünkü günlerim duman gibi yok oluyor, 2 Kemiklerim ateş gibi yanıyor.'),
(1998906,68,19,102,4,'Yüreğim kırgın yemiş ot gibi kurudu, 2 Ekmek yemeyi bile unuttum.'),
(1998907,68,19,102,5,'Bir deri bir kemiğe döndüm 2 Acı acı inlemekten.'),
(1998908,68,19,102,6,'Issız yerlerdeki ishakkuşunu andırıyorum, 2 Viranelerdeki kukumav gibiyim.'),
(1998909,68,19,102,7,'Gözüme uyku girmiyor, 2 Damda yalnız kalmış bir kuş gibiyim.'),
(1998910,68,19,102,8,'Düşmanlarım bütün gün bana hakaret ediyor, 2 Bana dil uzatanlar adımı lanet için kullanıyor.'),
(1998911,68,19,102,9,'Kızıp öfkelendiğin için 2 Külü ekmek gibi yiyor, 2 İçeceğime gözyaşı katıyorum. 2 Beni kaldırıp bir yana attın.'),
(1998912,68,19,102,11,'Günlerim akşam uzayan gölge gibi yitmekte, 2 Ot gibi sararmaktayım.'),
(1998913,68,19,102,12,'Ama sen, sonsuza dek tahtında oturursun, ya RAB, 2 Ünün kuşaklar boyu sürer.'),
(1998914,68,19,102,13,'Kalkıp Siyona sevecenlik göstereceksin, 2 Çünkü onu kayırmanın zamanıdır, beklenen zaman geldi.'),
(1998915,68,19,102,14,'Kulların onun taşlarından hoşlanır, 2 Tozunu bile severler.'),
(1998916,68,19,102,15,'Uluslar RABbin adından, 2 Yeryüzü kralları görkeminden korkacak.'),
(1998917,68,19,102,16,'Çünkü RAB Siyonu yeniden kuracak, 2 Görkem içinde görünecek.'),
(1998918,68,19,102,17,'Yoksulların duasına kulak verecek, 2 Yalvarışlarını asla hor görmeyecek.'),
(1998919,68,19,102,18,'Bunlar gelecek kuşak için yazılsın, 2 Öyle ki, henüz doğmamış insanlar 2 RABbe övgüler sunsun.'),
(1998920,68,19,102,19,'RAB yücelerdeki kutsal katından aşağı baktı, 2 Göklerden yeryüzünü gözetledi,'),
(1998921,68,19,102,20,'Tutsakların iniltisini duymak, 2 Ölüm mahkûmlarını kurtarmak için.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998922,68,19,102,21,'Böylece halklar ve krallıklar 2 RABbe tapınmak için toplanınca, 2 Onun adı Siyonda, 2 Övgüsü Yeruşalimde duyurulacak.'),
(1998923,68,19,102,23,'RAB gücümü kırdı yaşam yolunda, 2 Ömrümü kısalttı.'),
(1998924,68,19,102,24,'‹‹Ey Tanrım, ömrümün ortasında canımı alma!›› dedim. 2 ‹‹Senin yılların kuşaklar boyu sürer!'),
(1998925,68,19,102,25,'‹‹Çok önceden attın dünyanın temellerini, 2 Gökler de senin ellerinin yapıtıdır.'),
(1998926,68,19,102,26,'Onlar yok olacak, ama sen kalıcısın. 2 Hepsi bir giysi gibi eskiyecek. 2 Onları bir kaftan gibi değiştireceksin, 2 Geçip gidecekler.'),
(1998927,68,19,102,27,'Ama sen hep aynısın, 2 Yılların tükenmeyecek.'),
(1998928,68,19,102,28,'Gözetiminde yaşayacak kullarının çocukları, 2 Senin önünde duracak soyları.››'),
(1998929,68,19,103,1,'RABbe övgüler sun, ey gönlüm! 2 Onun kutsal adına övgüler sun, ey bütün varlığım!'),
(1998930,68,19,103,2,'RABbe övgüler sun, ey canım! 2 İyiliklerinin hiçbirini unutma!'),
(1998931,68,19,103,3,'Bütün suçlarını bağışlayan, 2 Bütün hastalıklarını iyileştiren,'),
(1998932,68,19,103,4,'Canını ölüm çukurundan kurtaran, 2 Sana sevgi ve sevecenlik tacı giydiren,'),
(1998933,68,19,103,5,'Yaşam boyu seni iyiliklerle doyuran Odur, 2 Bu nedenle gençliğin kartalınki gibi tazelenir.'),
(1998934,68,19,103,6,'RAB bütün düşkünlere 2 Hak ve adalet sağlar.'),
(1998935,68,19,103,7,'Kendi yöntemlerini Musaya, 2 İşlerini İsraillilere açıkladı.'),
(1998936,68,19,103,8,'RAB sevecen ve lütfedendir, 2 Tez öfkelenmez, sevgisi engindir.'),
(1998937,68,19,103,9,'Sürekli suçlamaz, 2 Öfkesini sonsuza dek sürdürmez.'),
(1998938,68,19,103,10,'Bize günahlarımıza göre davranmaz, 2 Suçlarımızın karşılığını vermez.'),
(1998939,68,19,103,11,'Çünkü gökler yeryüzünden ne kadar yüksekse, 2 Kendisinden korkanlara karşı sevgisi de o kadar büyüktür.'),
(1998940,68,19,103,12,'Doğu batıdan ne kadar uzaksa, 2 O kadar uzaklaştırdı bizden isyanlarımızı.'),
(1998941,68,19,103,13,'Bir baba çocuklarına nasıl sevecen davranırsa, 2 RAB de kendisinden korkanlara öyle sevecen davranır.'),
(1998942,68,19,103,14,'Çünkü mayamızı bilir, 2 Toprak olduğumuzu anımsar.'),
(1998943,68,19,103,15,'İnsana gelince, ota benzer ömrü, 2 Kır çiçeği gibi serpilir;'),
(1998944,68,19,103,16,'Rüzgar üzerine esince yok olur gider, 2 Bulunduğu yer onu tanımaz.'),
(1998945,68,19,103,17,'Ama RAB kendisinden korkanları sonsuza dek sever, 2 Antlaşmasına uyan 2 Ve buyruklarına uymayı anımsayan soylarına adil davranır.'),
(1998946,68,19,103,19,'RAB tahtını göklere kurmuştur, 2 Onun egemenliği her yeri kapsar.'),
(1998947,68,19,103,20,'RABbe övgüler sunun, ey sizler, Onun melekleri, 2 Onun sözünü dinleyen, 2 Söylediklerini yerine getiren güç sahipleri!'),
(1998948,68,19,103,21,'RABbe övgüler sunun, ey sizler, 2 Onun bütün göksel orduları, 2 İsteğini yerine getiren kulları!'),
(1998949,68,19,103,22,'RAB''be övgüler sunun, 2 Ey O''nun egemen olduğu yerlerdeki bütün yaratıklar! 2 RAB''be övgüler sun, ey gönlüm!'),
(1998950,68,19,104,1,'RABbe övgüler sun, ey gönlüm! 2 Ya RAB Tanrım, ne ulusun! 2 Görkem ve yücelik kuşanmışsın,'),
(1998951,68,19,104,2,'Bir kaftana bürünür gibi ışığa bürünmüşsün. 2 Gökleri bir çadır gibi geren,'),
(1998952,68,19,104,3,'Evini yukarıdaki sular üzerine kuran, 2 Bulutları kendine savaş arabası yapan, 2 Rüzgarın kanatları üzerinde gezen,'),
(1998953,68,19,104,4,'Rüzgarları kendine haberci, 2 Yıldırımları hizmetkâr eden sensin. eden sensin›› ya da ‹‹Meleklerini rüzgarlar, hizmetkârlarını ateş alevleri yapan sensin››.'),
(1998954,68,19,104,5,'Yeryüzünü temeller üzerine kurdun, 2 Asla sarsılmasın diye.'),
(1998955,68,19,104,6,'Engini ona bir giysi gibi giydirdin, 2 Sular dağların üzerinde durdu.'),
(1998956,68,19,104,7,'Sen kükreyince sular kaçtı, 2 Göğü gürletince hemen çekildi.'),
(1998957,68,19,104,8,'Dağları aşıp derelere aktı, 2 Onlar için belirlediğin yerlere doğru.'),
(1998958,68,19,104,9,'Bir sınır koydun önlerine, 2 Geçmesinler, gelip yeryüzünü bir daha kaplamasınlar diye.'),
(1998959,68,19,104,10,'Vadilerde fışkırttığın pınarlar, 2 Dağların arasından akar.'),
(1998960,68,19,104,11,'Bütün kır hayvanlarını suvarır, 2 Yaban eşeklerinin susuzluğunu giderirler.'),
(1998961,68,19,104,12,'Kuşlar yanlarında yuva kurar, 2 Dalların arasında ötüşürler.'),
(1998962,68,19,104,13,'Gökteki evinden dağları sularsın, 2 Yeryüzü işlerinin meyvesine doyar.'),
(1998963,68,19,104,14,'Hayvanlar için ot, 2 İnsanların yararı için bitkiler yetiştirirsin; 2 İnsanlar ekmeğini topraktan çıkarsın diye,'),
(1998964,68,19,104,15,'Yüreklerini sevindiren şarabı, 2 Yüzlerini güldüren zeytinyağını, 2 Güçlerini artıran ekmeği hep sen verirsin.'),
(1998965,68,19,104,16,'RABbin ağaçları, 2 Kendi diktiği Lübnan sedirleri suya doyar.'),
(1998966,68,19,104,17,'Kuşlar orada yuva yapar, 2 Leyleğin evi ise çamlardadır.'),
(1998967,68,19,104,18,'Yüksek dağlar dağ keçilerinin uğrağı, 2 Kayalar kaya tavşanlarının sığınağıdır.'),
(1998968,68,19,104,19,'Mevsimleri göstersin diye ayı, 2 Batacağı zamanı bilen güneşi yarattın.'),
(1998969,68,19,104,20,'Karartırsın ortalığı, gece olur, 2 Başlar kıpırdamaya orman hayvanları.'),
(1998970,68,19,104,21,'Genç aslan av peşinde kükrer, 2 Tanrıdan yiyecek ister.'),
(1998971,68,19,104,22,'Güneş doğunca 2 İnlerine çekilir, yatarlar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1998972,68,19,104,23,'İnsan işine gider, 2 Akşama dek çalışmak için.'),
(1998973,68,19,104,24,'Ya RAB, ne çok eserin var! 2 Hepsini bilgece yaptın; 2 Yeryüzü yarattıklarınla dolu.'),
(1998974,68,19,104,25,'İşte uçsuz bucaksız denizler, 2 İçinde kaynaşan sayısız canlılar, 2 Büyük küçük yaratıklar.'),
(1998975,68,19,104,26,'Orada gemiler dolaşır, 2 İçinde oynaşsın diye yarattığın Livyatan da orada.'),
(1998976,68,19,104,27,'Hepsi seni bekliyor, 2 Yiyeceklerini zamanında veresin diye.'),
(1998977,68,19,104,28,'Sen verince onlar toplar, 2 Sen elini açınca onlar iyiliğe doyar.'),
(1998978,68,19,104,29,'Yüzünü gizleyince dehşete kapılırlar, 2 Soluklarını kesince ölüp toprak olurlar.'),
(1998979,68,19,104,30,'Ruhunu gönderince var olurlar, 2 Yeryüzüne yeni yaşam verirsin.'),
(1998980,68,19,104,31,'RABbin görkemi sonsuza dek sürsün! 2 Sevinsin RAB yaptıklarıyla!'),
(1998981,68,19,104,32,'O bakınca yeryüzü titrer, 2 O dokununca dağlar tüter.'),
(1998982,68,19,104,33,'Ömrümce RABbe ezgiler söyleyecek, 2 Var oldukça Tanrımı ilahilerle öveceğim.'),
(1998983,68,19,104,34,'Düşüncem ona hoş görünsün, 2 Sevincim RAB olsun!'),
(1998984,68,19,104,35,'Tükensin dünyadaki günahlılar, 2 Yok olsun artık kötüler! 2 RAB''be övgüler sun, ey gönlüm! 2 RAB''be övgüler sunun!'),
(1998985,68,19,105,1,'RABbe şükredin, Onu adıyla çağırın, 2 Halklara duyurun yaptıklarını!'),
(1998986,68,19,105,2,'Onu ezgilerle, ilahilerle övün, 2 Bütün harikalarını anlatın!'),
(1998987,68,19,105,3,'Kutsal adıyla övünün, 2 Sevinsin RABbe yönelenler!'),
(1998988,68,19,105,4,'RABbe ve Onun gücüne bakın, 2 Durmadan Onun yüzünü arayın!'),
(1998989,68,19,105,5,'Ey sizler, kulu İbrahimin soyu, 2 Seçtiği Yakupoğulları, 2 Onun yaptığı harikaları, 2 Olağanüstü işlerini 2 Ve ağzından çıkan yargıları anımsayın!'),
(1998990,68,19,105,7,'Tanrımız RAB Odur, 2 Yargıları bütün yeryüzünü kapsar.'),
(1998991,68,19,105,8,'O antlaşmasını, 2 Bin kuşak için verdiği sözü, 2 İbrahimle yaptığı antlaşmayı, 2 İshak için içtiği andı sonsuza dek anımsar.'),
(1998992,68,19,105,10,'‹‹Hakkınıza düşen mülk olarak 2 Kenan ülkesini size vereceğim›› diyerek, 2 Bunu Yakup için bir kural, 2 İsraille sonsuza dek geçerli bir antlaşma yaptı.'),
(1998993,68,19,105,12,'O zaman bir avuç insandılar, 2 Sayıca az ve ülkeye yabancıydılar.'),
(1998994,68,19,105,13,'Bir ulustan öbürüne, 2 Bir ülkeden ötekine dolaşıp durdular.'),
(1998995,68,19,105,14,'RAB kimsenin onları ezmesine izin vermedi, 2 Onlar için kralları bile payladı:'),
(1998996,68,19,105,15,'‹‹Meshettiklerime dokunmayın, 2 Peygamberlerime kötülük etmeyin!›› dedi.'),
(1998997,68,19,105,16,'Ülkeye kıtlık gönderdi, 2 Bütün yiyeceklerini yok etti.'),
(1998998,68,19,105,17,'Önlerinden bir adam göndermişti, 2 Köle olarak satılan Yusuftu bu.'),
(1998999,68,19,105,18,'Zincir vurup incittiler ayaklarını, 2 Demir halka geçirdiler boynuna,'),
(1999000,68,19,105,19,'Söyledikleri gerçekleşinceye dek, 2 RABbin sözü onu sınadı.'),
(1999001,68,19,105,20,'Kral adam gönderip Yusufu salıverdi, 2 Halklara egemen olan onu özgür kıldı.'),
(1999002,68,19,105,21,'Onu kendi sarayının efendisi, 2 Bütün varlığının sorumlusu yaptı;'),
(1999003,68,19,105,22,'Önderlerini istediği gibi eğitsin, 2 İleri gelenlerine akıl versin diye.'),
(1999004,68,19,105,23,'O zaman İsrail Mısıra gitti, 2 Yakup Ham ülkesine yerleşti.'),
(1999005,68,19,105,24,'RAB halkını alabildiğine çoğalttı, 2 Düşmanlarından sayıca artırdı onları.'),
(1999006,68,19,105,25,'Sonunda tutumunu değiştirdi düşmanlarının: 2 Halkından tiksindiler, 2 Kullarına kurnazca davrandılar.'),
(1999007,68,19,105,26,'Kulu Musayı, 2 Seçtiği Harunu gönderdi aralarına.'),
(1999008,68,19,105,27,'Onlar gösterdiler RABbin belirtilerini, 2 Ham ülkesinde şaşılası işlerini.'),
(1999009,68,19,105,28,'Karanlık gönderip ülkeyi karanlığa bürüdü RAB, 2 Çünkü Mısırlılar Onun sözlerine karşı gelmişti.'),
(1999010,68,19,105,29,'Kana çevirdi sularını, 2 Öldürdü balıklarını.'),
(1999011,68,19,105,30,'Ülkede kurbağalar kaynaştı 2 Krallarının odalarına kadar.'),
(1999012,68,19,105,31,'RAB buyurunca sinek sürüleri, 2 Sivrisinekler üşüştü ülkenin her yanına.'),
(1999013,68,19,105,32,'Dolu yağdırdı yağmur yerine, 2 Şimşekler çaktırdı ülkelerinde.'),
(1999014,68,19,105,33,'Bağlarını, incir ağaçlarını vurdu, 2 Parçaladı ülkenin ağaçlarını.'),
(1999015,68,19,105,34,'O buyurunca çekirgeler, 2 Sayısız yavrular kaynadı.'),
(1999016,68,19,105,35,'Ülkenin bütün bitkilerini yediler, 2 Toprağın ürününü yiyip bitirdiler.'),
(1999017,68,19,105,36,'RAB ülkede ilk doğanların hepsini, 2 İlk çocuklarını öldürdü.'),
(1999018,68,19,105,37,'İsraillileri ülkeden altın ve gümüşle çıkardı, 2 Oymaklarından tek kişi bile tökezlemedi.'),
(1999019,68,19,105,38,'Onlar gidince Mısır sevindi, 2 Çünkü İsrail korkusu çökmüştü Mısırın üzerine.'),
(1999020,68,19,105,39,'RAB bulutu bir örtü gibi yaydı üzerlerine, 2 Gece ateş verdi yollarını aydınlatsın diye.'),
(1999021,68,19,105,40,'İstediler, bıldırcın gönderdi, 2 Göksel ekmekle doyurdu karınlarını.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999022,68,19,105,41,'Kayayı yardı, sular fışkırdı, 2 Çorak topraklarda bir ırmak gibi aktı.'),
(1999023,68,19,105,42,'Çünkü kutsal sözünü, 2 Kulu İbrahime verdiği sözü anımsadı.'),
(1999024,68,19,105,43,'Halkını sevinç içinde, 2 Seçtiklerini sevinç çığlıklarıyla ülkeden çıkardı.'),
(1999025,68,19,105,44,'Ulusların topraklarını verdi onlara. 2 Halkların emeğini miras aldılar;'),
(1999026,68,19,105,45,'Kurallarını yerine getirsinler, 2 Yasalarına uysunlar diye. 2 RAB''be övgüler sunun!'),
(1999027,68,19,106,1,'Övgüler sunun, RABbe! 2 RABbe şükredin, çünkü O iyidir, 2 Sevgisi sonsuzdur.'),
(1999028,68,19,106,2,'RABbin büyük işlerini kim anlatabilir, 2 Kim Ona yeterince övgü sunabilir?'),
(1999029,68,19,106,3,'Ne mutlu adalete uyanlara, 2 Sürekli doğru olanı yapanlara!'),
(1999030,68,19,106,4,'Ya RAB, halkına lütfettiğinde anımsa beni, 2 Onları kurtardığında ilgilen benimle.'),
(1999031,68,19,106,5,'Öyle ki, seçtiklerinin gönencini göreyim, 2 Ulusunun sevincini, 2 Kendi halkının kıvancını paylaşayım.'),
(1999032,68,19,106,6,'Atalarımız gibi biz de günah işledik, 2 Suç işledik, kötülük ettik.'),
(1999033,68,19,106,7,'Atalarımız Mısırdayken 2 Yaptığın harikaları anlamadı, 2 Çok kez gösterdiğin sevgiyi anımsamadı, 2 Denizde, Kızıldenizde başkaldırdılar.'),
(1999034,68,19,106,8,'Buna karşın RAB gücünü göstermek için, 2 Adı uğruna kurtardı onları.'),
(1999035,68,19,106,9,'Kızıldenizi azarladı, kurudu deniz, 2 Yürüdüler enginde Onun öncülüğünde, 2 Çölde yürür gibi.'),
(1999036,68,19,106,10,'Kendilerinden nefret edenlerin elinden aldı onları, 2 Düşmanlarının pençesinden kurtardı.'),
(1999037,68,19,106,11,'Sular yuttu hasımlarını, 2 Hiçbiri kurtulmadı.'),
(1999038,68,19,106,12,'O zaman atalarımız Onun sözlerine inandılar, 2 Ezgiler söyleyerek Onu övdüler.'),
(1999039,68,19,106,13,'Ne var ki, RABbin yaptıklarını çabucak unuttular, 2 Öğüt vermesini beklemediler.'),
(1999040,68,19,106,14,'Özlemle kıvrandılar çölde, 2 Tanrıyı denediler ıssız yerlerde.'),
(1999041,68,19,106,15,'Tanrı onlara istediklerini verdi, 2 Ama üzerlerine yıpratıcı bir hastalık gönderdi.'),
(1999042,68,19,106,16,'Onlar ordugahlarında Musayı, 2 RABbin kutsal kulu Harunu kıskanınca,'),
(1999043,68,19,106,17,'Yer yarıldı ve Datanı yuttu, 2 Aviramla yandaşlarının üzerine kapandı.'),
(1999044,68,19,106,18,'Ateş kavurdu onları izleyenleri, 2 Alev yaktı kötüleri.'),
(1999045,68,19,106,19,'Bir buzağı heykeli yaptılar Horevde, 2 Dökme bir puta tapındılar.'),
(1999046,68,19,106,20,'Tanrının yüceliğini, 2 Ot yiyen öküz putuna değiştirdiler.'),
(1999047,68,19,106,21,'Unuttular kendilerini kurtaran Tanrıyı, 2 Mısırda yaptığı büyük işleri,'),
(1999048,68,19,106,22,'Ham ülkesinde yarattığı harikaları, 2 Kızıldeniz kıyısında yaptığı müthiş işleri.'),
(1999049,68,19,106,23,'Bu yüzden onları yok edeceğini söyledi Tanrı, 2 Ama seçkin kulu Musa Onun önündeki gedikte durarak, 2 Yok edici öfkesinden vazgeçirdi Onu.'),
(1999050,68,19,106,24,'Ardından hor gördüler güzelim ülkeyi, 2 Tanrının verdiği söze inanmadılar.'),
(1999051,68,19,106,25,'Çadırlarında söylendiler, 2 Dinlemediler RABbin sesini.'),
(1999052,68,19,106,26,'Bu yüzden RAB elini kaldırdı 2 Ve çölde onları yere sereceğine, 2 Soylarını ulusların arasına saçacağına, 2 Onları öteki ülkelere dağıtacağına ant içti.'),
(1999053,68,19,106,28,'Sonra Baal-Peora bel bağladılar, 2 Ölülere sunulan kurbanları yediler.'),
(1999054,68,19,106,29,'Öfkelendirdiler RABbi yaptıklarıyla, 2 Salgın hastalık çıktı aralarında.'),
(1999055,68,19,106,30,'Ama Pinehas kalkıp araya girdi, 2 Felaketi önledi.'),
(1999056,68,19,106,31,'Bu doğruluk sayıldı ona, 2 Kuşaklar boyu, sonsuza dek sürecek bu.'),
(1999057,68,19,106,32,'Yine RABbi öfkelendirdiler Meriva suları yanında, 2 Musanın başına dert açıldı onlar yüzünden;'),
(1999058,68,19,106,33,'Çünkü onu sinirlendirdiler, 2 O da düşünmeden konuştu.'),
(1999059,68,19,106,34,'RABbin onlara buyurduğu gibi 2 Yok etmediler halkları,'),
(1999060,68,19,106,35,'Tersine öteki uluslara karıştılar, 2 Onların törelerini öğrendiler.'),
(1999061,68,19,106,36,'Putlarına taptılar, 2 Bu da onlara tuzak oldu.'),
(1999062,68,19,106,37,'Oğullarını, kızlarını 2 Cinlere kurban ettiler.'),
(1999063,68,19,106,38,'Kenan putlarına kurban olsun diye 2 Oğullarının, kızlarının kanını, 2 Suçsuzların kanını döktüler; 2 Ülke onların kanıyla kirlendi.'),
(1999064,68,19,106,39,'Böylece yaptıklarıyla kirli sayıldılar, 2 Vefasız duruma düştüler töreleriyle.'),
(1999065,68,19,106,40,'RABbin öfkesi parladı halkına karşı, 2 Tiksindi kendi halkından.'),
(1999066,68,19,106,41,'Onları ulusların eline teslim etti. 2 Onlardan nefret edenler onlara egemen oldu.'),
(1999067,68,19,106,42,'Düşmanları onları ezdi, 2 Boyun eğdirdi hepsine.'),
(1999068,68,19,106,43,'RAB onları birçok kez kurtardı, 2 Ama akılları fikirleri başkaldırmaktaydı 2 Ve alçaltıldılar suçları yüzünden.'),
(1999069,68,19,106,44,'RAB yine de ilgilendi sıkıntılarıyla 2 Yakarışlarını duyunca.'),
(1999070,68,19,106,45,'Antlaşmasını anımsadı onlar uğruna, 2 Eşsiz sevgisinden ötürü vazgeçti yapacaklarından.'),
(1999071,68,19,106,46,'Merhamet koydu onları tutsak alanların yüreğine.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999072,68,19,106,47,'Kurtar bizi, ey Tanrımız RAB, 2 Topla bizi ulusların arasından. 2 Kutsal adına şükredelim, 2 Yüceliğinle övünelim.'),
(1999073,68,19,106,48,'Öncesizlikten sonsuza dek, 2 İsrail''in Tanrısı RAB''be övgüler olsun! 2 Bütün halk, ‹‹Amin!›› desin. 2 RAB''be övgüler olsun!'),
(1999074,68,19,107,1,'RABbe şükredin, çünkü O iyidir, 2 Sevgisi sonsuzdur.'),
(1999075,68,19,107,2,'Böyle desin RABbin kurtardıkları, 2 Düşman pençesinden özgür kıldıkları,'),
(1999076,68,19,107,3,'Doğudan, batıdan, kuzeyden, güneydenfş, 2 Bütün ülkelerden topladıkları.'),
(1999077,68,19,107,4,'Issız çöllerde dolaştılar, 2 Yerleşecekleri kente giden bir yol bulamadılar.'),
(1999078,68,19,107,5,'Aç, susuz, 2 Sefil oldular.'),
(1999079,68,19,107,6,'O zaman sıkıntı içinde RABbe yakardılar, 2 RAB kurtardı onları dertlerinden.'),
(1999080,68,19,107,7,'Yerleşecekleri bir kente varıncaya dek, 2 Onlara doğru yolda öncülük etti.'),
(1999081,68,19,107,8,'Şükretsinler RABbe sevgisi için, 2 İnsanlar yararına yaptığı harikalar için.'),
(1999082,68,19,107,9,'Çünkü O susamış canın susuzluğunu giderir, 2 Aç canı iyiliklerle doyurur.'),
(1999083,68,19,107,10,'Zincire vurulmuş, acıyla kıvranan tutsaklar, 2 Karanlıkta, zifiri karanlıkta oturmuştu.'),
(1999084,68,19,107,11,'Çünkü Tanrının buyruklarına karşı çıkmışlardı, 2 Küçümsemişlerdi Yüceler Yücesinin öğüdünü.'),
(1999085,68,19,107,12,'Ağır işlerle hayatı onlara zehir etti, 2 Çöktüler, yardım eden olmadı.'),
(1999086,68,19,107,13,'O zaman sıkıntı içinde RABbe yakardılar, 2 RAB kurtardı onları dertlerinden;'),
(1999087,68,19,107,14,'Çıkardı karanlıktan, zifiri karanlıktan, 2 Kopardı zincirlerini.'),
(1999088,68,19,107,15,'Şükretsinler RABbe sevgisi için, 2 İnsanlar yararına yaptığı harikalar için!'),
(1999089,68,19,107,16,'Çünkü tunç kapıları kırdı, 2 Demir kapı kollarını parçaladı O.'),
(1999090,68,19,107,17,'Cezalarını buldu aptallar, 2 Suçları, isyanları yüzünden.'),
(1999091,68,19,107,18,'İğrenir olmuşlardı bütün yemeklerden, 2 Ölümün kapılarına yaklaşmışlardı.'),
(1999092,68,19,107,19,'O zaman sıkıntı içinde RABbe yakardılar, 2 RAB kurtardı onları dertlerinden.'),
(1999093,68,19,107,20,'Sözünü gönderip iyileştirdi onları, 2 Kurtardı ölüm çukurundan.'),
(1999094,68,19,107,21,'Şükretsinler RABbe sevgisi için, 2 İnsanlar yararına yaptığı harikalar için!'),
(1999095,68,19,107,22,'Şükran kurbanları sunsunlar 2 Ve sevinç çığlıklarıyla duyursunlar Onun yaptıklarını!'),
(1999096,68,19,107,23,'Gemilerle denize açılanlar, 2 Okyanuslarda iş yapanlar,'),
(1999097,68,19,107,24,'RABbin işlerini, 2 Derinliklerde yaptığı harikaları gördüler.'),
(1999098,68,19,107,25,'Çünkü O buyurunca şiddetli bir fırtına koptu, 2 Dalgalar şaha kalktı.'),
(1999099,68,19,107,26,'Göklere yükselip diplere indi gemiler, 2 Sıkıntıdan canları burunlarına geldi gemicilerin,'),
(1999100,68,19,107,27,'Sarhoş gibi sallanıp sendelediler, 2 Ustalıkları işe yaramadı.'),
(1999101,68,19,107,28,'O zaman sıkıntı içinde RABbe yakardılar, 2 RAB kurtardı onları dertlerinden.'),
(1999102,68,19,107,29,'Fırtınayı limanlığa çevirdi, 2 Yatıştı dalgalar;'),
(1999103,68,19,107,30,'Rahatlayınca sevindiler, 2 Diledikleri limana götürdü RAB onları.'),
(1999104,68,19,107,31,'Şükretsinler RABbe sevgisi için, 2 İnsanlar yararına yaptığı harikalar için!'),
(1999105,68,19,107,32,'Yüceltsinler Onu halk topluluğunda, 2 Övgüler sunsunlar ileri gelenlerin toplantısında.'),
(1999106,68,19,107,33,'Irmakları çöle çevirir, 2 Pınarları kurak toprağa,'),
(1999107,68,19,107,34,'Verimli toprağı çorak alana, 2 Orada yaşayanların kötülüğü yüzünden.'),
(1999108,68,19,107,35,'Çölü su birikintisine çevirir, 2 Kuru toprağı pınara.'),
(1999109,68,19,107,36,'Açları yerleştirir oraya; 2 Oturacak bir kent kursunlar,'),
(1999110,68,19,107,37,'Tarlalar ekip bağlar diksinler, 2 Bol ürün alsınlar diye.'),
(1999111,68,19,107,38,'RABbin kutsamasıyla, 2 Çoğaldılar alabildiğine, 2 Eksiltmedi hayvanlarını.'),
(1999112,68,19,107,39,'Sonra azaldılar, alçaldılar, 2 Baskı, sıkıntı ve acı yüzünden.'),
(1999113,68,19,107,40,'RAB rezalet saçtı soylular üzerine, 2 Yolu izi belirsiz bir çölde dolaştırdı onları.'),
(1999114,68,19,107,41,'Ama yoksulu sefaletten kurtardı, 2 Davar sürüsü gibi çoğalttı ailelerini.'),
(1999115,68,19,107,42,'Doğru insanlar görüp sevinecek, 2 Kötülerse ağzını kapayacak.'),
(1999116,68,19,107,43,'Aklı olan bunları göz önünde tutsun, 2 RAB''bin sevgisini dikkate alsın.'),
(1999117,68,19,108,1,'Kararlıyım, ey Tanrı, 2 Bütün varlığımla sana ezgiler, ilahiler söyleyeceğim!'),
(1999118,68,19,108,2,'Uyan, ey lir, ey çenk, 2 Seheri ben uyandırayım!'),
(1999119,68,19,108,3,'Halkların arasında sana şükürler sunayım, ya RAB, 2 Ulusların arasında seni ilahilerle öveyim.'),
(1999120,68,19,108,4,'Çünkü sevgin göklere erişir, 2 Sadakatin gökyüzüne ulaşır.'),
(1999121,68,19,108,5,'Yüceliğini göster göklerin üstünde, ey Tanrı, 2 Görkemin bütün yeryüzünü kaplasın!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999122,68,19,108,6,'Kurtar bizi sağ elinle, yardım et, 2 Sevdiklerin özgürlüğe kavuşsun diye!'),
(1999123,68,19,108,7,'Tanrı şöyle konuştu kutsal yerinde: 2 ‹‹Şekemi sevinçle bölüştürecek, 2 Sukkot Vadisini ölçeceğim.'),
(1999124,68,19,108,8,'Gilat benimdir, Manaşşe de benim, 2 Efrayim miğferim, 2 Yahuda asam.'),
(1999125,68,19,108,9,'Moav yıkanma leğenim, 2 Edomun üzerine çarığımı fırlatacağım, 2 Filiste zaferle haykıracağım.›› fırlatılması, bir yerin sahiplenilmesi anlamına geliyordu.'),
(1999126,68,19,108,10,'Kim beni surlu kente götürecek? 2 Kim bana Edoma kadar yol gösterecek?'),
(1999127,68,19,108,11,'Ey Tanrı, sen bizi reddetmedin mi? 2 Ordularımıza öncülük etmiyor musun artık?'),
(1999128,68,19,108,12,'Yardım et bize düşmana karşı, 2 Çünkü boştur insan yardımı.'),
(1999129,68,19,108,13,'Tanrı''yla zafer kazanırız, 2 O çiğner düşmanlarımızı.'),
(1999130,68,19,109,1,'Ey övgüler sunduğum Tanrı, 2 Sessiz kalma!'),
(1999131,68,19,109,2,'Çünkü kötüler, yalancılar 2 Bana karşı ağzını açtı, 2 Karalıyorlar beni.'),
(1999132,68,19,109,3,'Nefret dolu sözlerle beni kuşatıp 2 Yok yere bana savaş açtılar.'),
(1999133,68,19,109,4,'Sevgime karşılık bana düşman oldular, 2 Bense dua etmekteyim.'),
(1999134,68,19,109,5,'İyiliğime kötülük, 2 Sevgime nefretle karşılık verdiler.'),
(1999135,68,19,109,6,'Kötü bir adam koy düşmanın başına, 2 Sağında onu suçlayan biri dursun!'),
(1999136,68,19,109,7,'Yargılanınca suçlu çıksın, 2 Duası bile günah sayılsın!'),
(1999137,68,19,109,8,'Ömrü kısa olsun, 2 Görevini bir başkası üstlensin!'),
(1999138,68,19,109,9,'Çocukları öksüz, 2 Karısı dul kalsın!'),
(1999139,68,19,109,10,'Çocukları avare gezip dilensin, 2 Yıkık evlerinden uzakta yiyecek arasın!'),
(1999140,68,19,109,11,'Bütün malları tefecinin ağına düşsün, 2 Emeğini yabancılar yağmalasın!'),
(1999141,68,19,109,12,'Kimse ona sevgi göstermesin, 2 Öksüzlerine acıyan olmasın!'),
(1999142,68,19,109,13,'Soyu kurusun, 2 Bir kuşak sonra adı silinsin!'),
(1999143,68,19,109,14,'Atalarının suçları RABbin önünde anılsın, 2 Annesinin günahı silinmesin!'),
(1999144,68,19,109,15,'Günahları hep RABbin önünde dursun, 2 RAB anılarını yok etsin yeryüzünden!'),
(1999145,68,19,109,16,'Çünkü düşmanım sevgi göstermeyi düşünmedi, 2 Ölesiye baskı yaptı mazluma, yoksula, 2 Yüreği kırık insana.'),
(1999146,68,19,109,17,'Sevdiği lanet başına gelsin! 2 Madem kutsamaktan hoşlanmıyor, 2 Uzak olsun ondan kutsamak!'),
(1999147,68,19,109,18,'Laneti bir giysi gibi giydi, 2 Su gibi içine, yağ gibi kemiklerine işlesin lanet!'),
(1999148,68,19,109,19,'Bir giysi gibi onu örtünsün, 2 Bir kuşak gibi hep onu sarsın! düşmanlarının konuşmasıdır.'),
(1999149,68,19,109,20,'Düşmanlarıma, beni kötüleyenlere, 2 RAB böyle karşılık versin!'),
(1999150,68,19,109,21,'Ama sen, ey Egemen RAB, 2 Adın uğruna bana ilgi göster; 2 Kurtar beni, iyiliğin, sevgin uğruna!'),
(1999151,68,19,109,22,'Çünkü düşkün ve yoksulum, 2 Yüreğim yaralı içimde.'),
(1999152,68,19,109,23,'Batan güneş gibi geçip gidiyorum, 2 Çekirge gibi silkilip atılıyorum.'),
(1999153,68,19,109,24,'Dizlerim titriyor oruç tutmaktan; 2 Bir deri bir kemiğe döndüm.'),
(1999154,68,19,109,25,'Düşmanlarıma yüzkarası oldum; 2 Beni görünce kafalarını sallıyorlar!'),
(1999155,68,19,109,26,'Yardım et bana, ya RAB Tanrım; 2 Kurtar beni sevgin uğruna!'),
(1999156,68,19,109,27,'Bilsinler bu işte senin elin olduğunu, 2 Bunu senin yaptığını, ya RAB!'),
(1999157,68,19,109,28,'Varsın lanet etsin onlar, sen kutsa beni, 2 Bana saldıranlar utanacak, 2 Ben kulunsa sevineceğim.'),
(1999158,68,19,109,29,'Rezilliğe bürünsün beni suçlayanlar, 2 Kaftan giyer gibi utançlarıyla örtünsünler!'),
(1999159,68,19,109,30,'RABbe çok şükredeceğim, 2 Kalabalığın arasında Ona övgüler dizeceğim;'),
(1999160,68,19,109,31,'Çünkü O yoksulun sağında durur, 2 Onu yargılayanlardan kurtarmak için.'),
(1999161,68,19,110,1,'RAB efendime: 2 ‹‹Ben düşmanlarını ayaklarının altına serinceye dekfü 2 Sağımda otur›› diyor. ‹‹Ayaklarına tabure yapıncaya dek››.'),
(1999162,68,19,110,2,'RAB Siyondan uzatacak kudret asanı, 2 Düşmanlarının ortasında egemenlik sür!'),
(1999163,68,19,110,3,'Savaşacağın gün 2 Gönüllü gidecek askerlerin. 2 Seherin bağrından doğan çiy gibi 2 Kutsal giysiler içinde 2 Sana gelecek gençlerin.'),
(1999164,68,19,110,4,'RAB ant içti, kararından dönmez: 2 ‹‹Melkisedek düzeni uyarınca 2 Sonsuza dek kâhinsin sen!›› dedi.'),
(1999165,68,19,110,5,'Rab senin sağındadır, 2 Kralları ezecek öfkelendiği gün.'),
(1999166,68,19,110,6,'Ulusları yargılayacak, ortalığı cesetler dolduracak, 2 Dünyanın dört bucağında başları ezecek.'),
(1999167,68,19,110,7,'Yol kenarındaki dereden su içecek; 2 Bu yüzden başını dik tutacak.'),
(1999168,68,19,111,1,'Övgüler sunun RABbe! Doğru insanların toplantısında, 2 Topluluk içinde, 2 Bütün yüreğimle RABbe şükredeceğim.'),
(1999169,68,19,111,2,'RABbin işleri büyüktür, 2 Onlardan zevk alanlar hep onları düşünür.'),
(1999170,68,19,111,3,'Onun yaptıkları yüce ve görkemlidir, 2 Doğruluğu sonsuza dek sürer.'),
(1999171,68,19,111,4,'RAB unutulmayacak harikalar yaptı, 2 O sevecen ve lütfedendir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999172,68,19,111,5,'Kendisinden korkanları besler, 2 Antlaşmasını sonsuza dek anımsar.'),
(1999173,68,19,111,6,'Ulusların topraklarını kendi halkına vermekle 2 Gösterdi onlara işlerinin gücünü.'),
(1999174,68,19,111,7,'Yaptığı her işte sadık ve adildir, 2 Bütün koşulları güvenilirdir;'),
(1999175,68,19,111,8,'Sonsuza dek sürer, 2 Sadakat ve doğrulukla yapılır.'),
(1999176,68,19,111,9,'O halkının kurtuluşunu sağladı, 2 Antlaşmasını sonsuza dek geçerli kıldı. 2 Adı kutsal ve müthiştir.'),
(1999177,68,19,111,10,'Bilgeliğin temeli RAB korkusudur, 2 O''nun kurallarını yerine getiren herkes 2 Sağduyu sahibi olur. 2 O''na sonsuza dek övgü sunulur!'),
(1999178,68,19,112,1,'Övgüler sunun RABbe! Ne mutlu RABden korkan insana, 2 Onun buyruklarından büyük zevk alana!'),
(1999179,68,19,112,2,'Soyu yeryüzünde güç kazanacak, 2 Doğruların kuşağı kutsanacak.'),
(1999180,68,19,112,3,'Bolluk ve zenginlik eksilmez evinden, 2 Sonsuza dek sürer doğruluğu.'),
(1999181,68,19,112,4,'Karanlıkta ışık doğar dürüstler için, 2 Lütfeden, sevecen, doğru insanlar için.'),
(1999182,68,19,112,5,'Ne mutlu eli açık olan, ödünç veren, 2 İşlerini adaletle yürüten insana!'),
(1999183,68,19,112,6,'Asla sarsılmaz, 2 Sonsuza dek anılır doğru insan.'),
(1999184,68,19,112,7,'Kötü haberden korkmaz, 2 Yüreği sarsılmaz, RABbe güvenir.'),
(1999185,68,19,112,8,'Gözü pektir, korku nedir bilmez, 2 Sonunda düşmanlarının yenilgisini görür.'),
(1999186,68,19,112,9,'Armağanlar dağıttı, yoksullara verdi; 2 Doğruluğu sonsuza dek kalıcıdır, 2 Gücü ve saygınlığı artar.'),
(1999187,68,19,112,10,'Kötü kişi bunu görünce kudurur, 2 Dişlerini gıcırdatır, kendi kendini yer, bitirir. 2 Kötülerin dileği boşa çıkar.'),
(1999188,68,19,113,1,'Övgüler sunun RABbe! Övgüler sunun, ey RABbin kulları, 2 RABbin adına övgüler sunun!'),
(1999189,68,19,113,2,'Şimdiden sonsuza dek 2 RABbin adına şükürler olsun!'),
(1999190,68,19,113,3,'Güneşin doğduğu yerden battığı yere kadar 2 RABbin adına övgüler sunulmalı!'),
(1999191,68,19,113,4,'RAB bütün uluslara egemendir, 2 Görkemi gökleri aşar.'),
(1999192,68,19,113,5,'Var mı Tanrımız RAB gibi, 2 Yücelerde oturan,'),
(1999193,68,19,113,6,'Göklerde ve yeryüzünde olanlara 2 Bakmak için eğilen?'),
(1999194,68,19,113,7,'Dü��künü yerden kaldırır, 2 Yoksulu çöplükten çıkarır;'),
(1999195,68,19,113,8,'Soylularla, 2 Halkının soylularıyla birlikte oturtsun diye.'),
(1999196,68,19,113,9,'Kısır kadını evde oturtur, 2 Çocuk sahibi mutlu bir anne kılar. RAB''be övgüler sunun!'),
(1999197,68,19,114,1,'İsrail Mısırdan çıktığında, 2 Yakupun soyu yabancı dil konuşan bir halktan ayrıldığında,'),
(1999198,68,19,114,2,'Yahuda Rabbin kutsal yeri oldu, 2 İsrail de Onun krallığı.'),
(1999199,68,19,114,3,'Deniz olanı görüp geri çekildi, 2 Şeria Irmağı tersine aktı.'),
(1999200,68,19,114,4,'Dağlar koç gibi, 2 Tepeler kuzu gibi sıçradı.'),
(1999201,68,19,114,5,'Ey deniz, sana ne oldu da kaçtın? 2 Ey Şeria, neden tersine aktın?'),
(1999202,68,19,114,6,'Ey dağlar, niçin koç gibi, 2 Ey tepeler, niçin kuzu gibi sıçradınız?'),
(1999203,68,19,114,7,'Titre, ey yeryüzü, 2 Kayayı havuza, 2 Çakmaktaşını pınara çeviren Rab''bin önünde, 2 Yakup''un Tanrısı''nın huzurunda.'),
(1999204,68,19,115,1,'Bizi değil, ya RAB, bizi değil, 2 Sevgin ve sadakatin uğruna, 2 Kendi adını yücelt!'),
(1999205,68,19,115,2,'Niçin uluslar: 2 ‹‹Hani, nerede onların Tanrısı?›› desin.'),
(1999206,68,19,115,3,'Bizim Tanrımız göklerdedir, 2 Ne isterse yapar.'),
(1999207,68,19,115,4,'Oysa onların putları altın ve gümüşten yapılmış, 2 İnsan elinin eseridir.'),
(1999208,68,19,115,5,'Ağızları var, konuşmazlar, 2 Gözleri var, görmezler,'),
(1999209,68,19,115,6,'Kulakları var, duymazlar, 2 Burunları var, koku almazlar,'),
(1999210,68,19,115,7,'Elleri var, hissetmezler, 2 Ayakları var, yürümezler, 2 Boğazlarından ses çıkmaz.'),
(1999211,68,19,115,8,'Onları yapan, onlara güvenen herkes 2 Onlar gibi olacak!'),
(1999212,68,19,115,9,'Ey İsrail halkı, RABbe güven, 2 Odur yardımcınız ve kalkanınız!'),
(1999213,68,19,115,10,'Ey Harun soyu, RABbe güven, 2 Odur yardımcınız ve kalkanınız!'),
(1999214,68,19,115,11,'Ey RABden korkanlar, RABbe güvenin, 2 Odur yardımcınız ve kalkanınız!'),
(1999215,68,19,115,12,'RAB bizi anımsayıp kutsayacak, 2 İsrail halkını, 2 Harun soyunu kutsayacak.'),
(1999216,68,19,115,13,'Küçük, büyük, 2 Kendisinden korkan herkesi kutsayacak.'),
(1999217,68,19,115,14,'RAB sizi, 2 Sizi ve çocuklarınızı çoğaltsın!'),
(1999218,68,19,115,15,'Yeri göğü yaratan RAB 2 Sizleri kutsasın.'),
(1999219,68,19,115,16,'Göklerin öteleri RABbindir, 2 Ama yeryüzünü insanlara vermiştir.'),
(1999220,68,19,115,17,'Ölüler, sessizlik diyarına inenler, 2 RABbe övgüler sunmaz;'),
(1999221,68,19,115,18,'Biziz RAB''bi öven, 2 Şimdiden sonsuza dek. RAB''be övgüler sunun!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999222,68,19,116,1,'RABbi seviyorum, 2 Çünkü O feryadımı duyar.'),
(1999223,68,19,116,2,'Bana kulak verdiği için, 2 Yaşadığım sürece Ona sesleneceğim.'),
(1999224,68,19,116,3,'Ölüm iplerine dolaşmıştım, 2 Ölüler diyarının kâbusu yakama yapışmıştı, 2 Sıkıntıya, acıya gömülmüştüm.'),
(1999225,68,19,116,4,'O zaman RABbi adıyla çağırdım, 2 ‹‹Aman, ya RAB, kurtar canımı!›› dedim.'),
(1999226,68,19,116,5,'RAB lütufkâr ve adildir, 2 Sevecendir Tanrımız.'),
(1999227,68,19,116,6,'RAB saf insanları korur, 2 Tükendiğim zaman beni kurtardı.'),
(1999228,68,19,116,7,'Ey canım, yine huzura kavuş, 2 Çünkü RAB sana iyilik etti.'),
(1999229,68,19,116,8,'Sen, ya RAB, canımı ölümden, 2 Gözlerimi yaştan, 2 Ayaklarımı sürçmekten kurtardın.'),
(1999230,68,19,116,9,'Yaşayanların diyarında, 2 RABbin huzurunda yürüyeceğim.'),
(1999231,68,19,116,10,'İman ettim, 2 ‹‹Büyük acı çekiyorum›› dediğim zaman bile. bile›› ya da ‹‹İman ettim, bu nedenle konuştum. Büyük acı çekiyorum›› (bkz. 2Ko.4:13).'),
(1999232,68,19,116,11,'Şaşkınlık içinde, 2 ‹‹Bütün insanlar yalancı›› dedim.'),
(1999233,68,19,116,12,'Ne karşılık verebilirim RABbe, 2 Bana yaptığı onca iyilik için?'),
(1999234,68,19,116,13,'Kurtuluş sunusu olarak kadeh kaldırıp 2 RABbi adıyla çağıracağım.'),
(1999235,68,19,116,14,'Bütün halkının önünde, 2 RABbe adadıklarımı yerine getireceğim.'),
(1999236,68,19,116,15,'RABbin gözünde değerlidir 2 Sadık kullarının ölümü.'),
(1999237,68,19,116,16,'Ya RAB, ben gerçekten senin kulunum; 2 Kulun, hizmetçinin oğluyum, 2 Sen çözdün bağlarımı.'),
(1999238,68,19,116,17,'Ya RAB, seni adınla çağırıp 2 Şükran kurbanı sunacağım.'),
(1999239,68,19,116,18,'RABbe adadıklarımı yerine getireceğim 2 Bütün halkının önünde,'),
(1999240,68,19,116,19,'RAB''bin Tapınağı''nın avlularında, 2 Senin orta yerinde, ey Yeruşalim! RAB''be övgüler sunun!'),
(1999241,68,19,117,1,'Ey bütün uluslar, RABbe övgüler sunun! 2 Ey bütün halklar, Onu yüceltin!'),
(1999242,68,19,117,2,'Çünkü bize beslediği sevgi büyüktür, 2 RAB''bin sadakati sonsuza dek sürer. RAB''be övgüler sunun!'),
(1999243,68,19,118,1,'RABbe şükredin, çünkü O iyidir, 2 Sevgisi sonsuzdur.'),
(1999244,68,19,118,2,'‹‹Sonsuzdur sevgisi!›› desin İsrail halkı.'),
(1999245,68,19,118,3,'‹‹Sonsuzdur sevgisi!›› desin Harunun soyu.'),
(1999246,68,19,118,4,'‹‹Sonsuzdur sevgisi!›› desin RABden korkanlar.'),
(1999247,68,19,118,5,'Sıkıntı içinde RABbe seslendim; 2 Yanıtladı, rahata kavuşturdu beni.'),
(1999248,68,19,118,6,'RAB benden yana, korkmam; 2 İnsan bana ne yapabilir?'),
(1999249,68,19,118,7,'RAB benden yana, benim yardımcım, 2 Benden nefret edenlerin sonuna zaferle bakacağım.'),
(1999250,68,19,118,8,'RABbe sığınmak 2 İnsana güvenmekten iyidir.'),
(1999251,68,19,118,9,'RABbe sığınmak 2 Soylulara güvenmekten iyidir.'),
(1999252,68,19,118,10,'Bütün uluslar beni kuşattı, 2 RABbin adıyla püskürttüm onları.'),
(1999253,68,19,118,11,'Kuşattılar, sardılar beni, 2 RABbin adıyla püskürttüm onları.'),
(1999254,68,19,118,12,'Arılar gibi sardılar beni, 2 Ama diken ateşi gibi sönüverdiler; 2 RABbin adıyla püskürttüm onları.'),
(1999255,68,19,118,13,'İtilip kakıldım, düşmek üzereydim, 2 Ama RAB yardım etti bana. metin ‹‹Beni itip kaktın››.'),
(1999256,68,19,118,14,'RAB gücüm ve ezgimdir, 2 O kurtardı beni.'),
(1999257,68,19,118,15,'Sevinç ve zafer çığlıkları 2 Çınlıyor doğruların çadırlarında: 2 ‹‹RABbin sağ eli güçlü işler yapar!'),
(1999258,68,19,118,16,'RABbin sağ eli üstündür, 2 RABbin sağ eli güçlü işler yapar!››'),
(1999259,68,19,118,17,'Ölmeyecek, yaşayacağım, 2 RABbin yaptıklarını duyuracağım.'),
(1999260,68,19,118,18,'RAB beni şiddetle yola getirdi, 2 Ama ölüme terk etmedi.'),
(1999261,68,19,118,19,'Açın bana adalet kapılarını, 2 Girip RABbe şükredeyim.'),
(1999262,68,19,118,20,'İşte budur RABbin kapısı! 2 Doğrular girebilir oradan.'),
(1999263,68,19,118,21,'Sana şükrederim, çünkü bana yanıt verdin, 2 Kurtarıcım oldun.'),
(1999264,68,19,118,22,'Yapıcıların reddettiği taş, 2 Köşenin baş taşı oldu.'),
(1999265,68,19,118,23,'RABbin işidir bu, 2 Gözümüzde harika bir iş!'),
(1999266,68,19,118,24,'Bugün RABbin yarattığı gündür, 2 Onun için sevinip coşalım!'),
(1999267,68,19,118,25,'Ne olur, ya RAB, kurtar bizi, 2 Ne olur, başarılı kıl bizi!'),
(1999268,68,19,118,26,'Kutsansın RABbin adıyla gelen! 2 Kutsuyoruz sizi RABbin evinden.'),
(1999269,68,19,118,27,'RAB Tanrıdır, aydınlattı bizi. 2 İplerle bağlayın bayram kurbanını, 2 İlerleyin sunağın boynuzlarına kadar. dallarla bayramı kutlayın››.'),
(1999270,68,19,118,28,'Tanrım sensin, şükrederim sana, 2 Tanrım sensin, yüceltirim seni.'),
(1999271,68,19,118,29,'RAB''be şükredin, çünkü O iyidir, 2 Sevgisi sonsuzdur.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999272,68,19,119,1,'Ne mutlu yolları temiz olanlara, 2 RABbin yasasına göre yaşayanlara! 119. Mezmur akrostiş biçimde yazılmış bir şiirdir.'),
(1999273,68,19,119,2,'Ne mutlu Onun öğütlerine uyanlara, 2 Bütün yüreğiyle Ona yönelenlere!'),
(1999274,68,19,119,3,'Hiç haksızlık etmezler, 2 Onun yolunda yürürler.'),
(1999275,68,19,119,4,'Koyduğun koşullara 2 Dikkatle uyulmasını buyurdun.'),
(1999276,68,19,119,5,'Keşke kararlı olsam 2 Senin kurallarına uymakta!'),
(1999277,68,19,119,6,'Hiç utanmayacağım, 2 Bütün buyruklarını izledikçe.'),
(1999278,68,19,119,7,'Şükredeceğim sana temiz yürekle, 2 Adil hükümlerini öğrendikçe.'),
(1999279,68,19,119,8,'Kurallarını yerine getireceğim, 2 Bırakma beni hiçbir zaman!'),
(1999280,68,19,119,9,'Genç insan yolunu nasıl temiz tutar? 2 Senin sözünü tutmakla.'),
(1999281,68,19,119,10,'Bütün yüreğimle sana yöneliyorum, 2 İzin verme buyruklarından sapmama!'),
(1999282,68,19,119,11,'Aklımdan çıkarmam sözünü, 2 Sana karşı günah işlememek için.'),
(1999283,68,19,119,12,'Övgüler olsun sana, ya RAB, 2 Bana kurallarını öğret.'),
(1999284,68,19,119,13,'Ağzından çıkan bütün hükümleri 2 Dudaklarımla yineliyorum.'),
(1999285,68,19,119,14,'Sevinç duyuyorum öğütlerini izlerken, 2 Sanki benim oluyor bütün hazineler.'),
(1999286,68,19,119,15,'Koşullarını derin derin düşünüyorum, 2 Yollarını izlerken.'),
(1999287,68,19,119,16,'Zevk alıyorum kurallarından, 2 Sözünü unutmayacağım.'),
(1999288,68,19,119,17,'Ben kuluna iyilik et ki yaşayayım, 2 Sözüne uyayım.'),
(1999289,68,19,119,18,'Gözlerimi aç, 2 Yasandaki harikaları göreyim.'),
(1999290,68,19,119,19,'Garibim bu dünyada, 2 Buyruklarını benden gizleme!'),
(1999291,68,19,119,20,'İçim tükeniyor, 2 Her an hükümlerini özlemekten.'),
(1999292,68,19,119,21,'Buyruklarından sapan 2 Lanetli küstahları azarlarsın.'),
(1999293,68,19,119,22,'Uzaklaştır benden küçümsemeleri, hakaretleri, 2 Çünkü öğütlerini tutuyorum.'),
(1999294,68,19,119,23,'Önderler toplanıp beni kötüleseler bile, 2 Ben kulun senin kurallarını derin derin düşüneceğim.'),
(1999295,68,19,119,24,'Öğütlerin benim zevkimdir, 2 Bana akıl verirler.'),
(1999296,68,19,119,25,'Toza toprağa serildim, 2 Sözün uyarınca yaşam ver bana.'),
(1999297,68,19,119,26,'Yaptıklarımı açıkladım, beni yanıtladın; 2 Kurallarını öğret bana!'),
(1999298,68,19,119,27,'Koşullarını anlamamı sağla ki, 2 Harikalarının üzerinde düşüneyim.'),
(1999299,68,19,119,28,'İçim eriyor kederden, 2 Sözün uyarınca güçlendir beni!'),
(1999300,68,19,119,29,'Yalan yoldan uzaklaştır, 2 Yasan uyarınca lütfet bana.'),
(1999301,68,19,119,30,'Ben sadakat yolunu seçtim, 2 Hükümlerini uygun gördüm.'),
(1999302,68,19,119,31,'Öğütlerine dört elle sarıldım, ya RAB, 2 Utandırma beni!'),
(1999303,68,19,119,32,'İçime huzur verdiğin için 2 Buyrukların doğrultusunda koşacağım.'),
(1999304,68,19,119,33,'Kurallarını nasıl izleyeceğimi öğret bana, ya RAB, 2 Öyle ki, onları sonuna kadar izleyeyim.'),
(1999305,68,19,119,34,'Anlamamı sağla, yasana uyayım, 2 Bütün yüreğimle onu yerine getireyim.'),
(1999306,68,19,119,35,'Buyrukların doğrultusunda yol göster bana, 2 Çünkü yolundan zevk alırım.'),
(1999307,68,19,119,36,'Yüreğimi haksız kazanca değil, 2 Kendi öğütlerine yönelt.'),
(1999308,68,19,119,37,'Gözlerimi boş şeylerden çevir, 2 Beni kendi yolunda yaşat.'),
(1999309,68,19,119,38,'Senden korkulması için 2 Ben kuluna verdiğin sözü yerine getir.'),
(1999310,68,19,119,39,'Korktuğum hakaretten uzak tut beni, 2 Çünkü senin ilkelerin iyidir.'),
(1999311,68,19,119,40,'Çok özlüyorum senin koşullarını! 2 Beni doğruluğunun içinde yaşat!'),
(1999312,68,19,119,41,'Bana sevgini göster, ya RAB, 2 Sözün uyarınca kurtar beni!'),
(1999313,68,19,119,42,'O zaman beni aşağılayanlara 2 Gereken yanıtı verebilirim, 2 Çünkü senin sözüne güvenirim.'),
(1999314,68,19,119,43,'Gerçeğini ağzımdan düşürme, 2 Çünkü senin hükümlerine umut bağladım.'),
(1999315,68,19,119,44,'Yasana sürekli, 2 Sonsuza dek uyacağım.'),
(1999316,68,19,119,45,'Özgürce yürüyeceğim, 2 Çünkü senin koşullarına yöneldim ben.'),
(1999317,68,19,119,46,'Kralların önünde senin öğütlerinden söz edecek, 2 Utanç duymayacağım.'),
(1999318,68,19,119,47,'Senin buyruklarından zevk alıyor, 2 Onları seviyorum.'),
(1999319,68,19,119,48,'Saygı ve sevgi duyuyorum buyruklarına, 2 Derin derin düşünüyorum kurallarını.'),
(1999320,68,19,119,49,'Kuluna verdiğin sözü anımsa, 2 Bununla umut verdin bana.'),
(1999321,68,19,119,50,'Acı çektiğimde beni avutan budur, 2 Sözün bana yaşam verir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999322,68,19,119,51,'Çok eğlendiler küstahlar benimle, 2 Yine de yasandan şaşmadım.'),
(1999323,68,19,119,52,'Geçmişte verdiğin hükümleri anımsayınca, 2 Avundum, ya RAB.'),
(1999324,68,19,119,53,'Çileden çıkıyorum, 2 Yasanı terk eden kötüler yüzünden.'),
(1999325,68,19,119,54,'Senin kurallarındır ezgilerimin konusu, 2 Konuk olduğum bu dünyada.'),
(1999326,68,19,119,55,'Gece adını anarım, ya RAB, 2 Yasana uyarım.'),
(1999327,68,19,119,56,'Tek yaptığım, 2 Senin koşullarına uymak.'),
(1999328,68,19,119,57,'Benim payıma düşen sensin, ya RAB, 2 Sözlerini yerine getireceğim, dedim.'),
(1999329,68,19,119,58,'Bütün yüreğimle sana yakardım. 2 Lütfet bana, sözün uyarınca.'),
(1999330,68,19,119,59,'Tuttuğum yolları düşündüm, 2 Senin öğütlerine göre adım attım.'),
(1999331,68,19,119,60,'Buyruklarına uymak için 2 Elimi çabuk tuttum, oyalanmadım.'),
(1999332,68,19,119,61,'Kötülerin ipleri beni sardı, 2 Yasanı unutmadım.'),
(1999333,68,19,119,62,'Doğru hükümlerin için 2 Gece yarısı kalkıp sana şükrederim.'),
(1999334,68,19,119,63,'Dostuyum bütün senden korkanların, 2 Koşullarına uyanların.'),
(1999335,68,19,119,64,'Yeryüzü sevginle dolu, ya RAB, 2 Kurallarını öğret bana!'),
(1999336,68,19,119,65,'Ya RAB, iyilik ettin kuluna, 2 Sözünü tuttun.'),
(1999337,68,19,119,66,'Bana sağduyu ve bilgi ver, 2 Çünkü inanıyorum buyruklarına.'),
(1999338,68,19,119,67,'Acı çekmeden önce yoldan sapardım, 2 Ama şimdi sözüne uyuyorum.'),
(1999339,68,19,119,68,'Sen iyisin, iyilik edersin; 2 Bana kurallarını öğret.'),
(1999340,68,19,119,69,'Küstahlar yalanlarla beni lekeledi, 2 Ama ben bütün yüreğimle senin koşullarına uyarım.'),
(1999341,68,19,119,70,'Onların yüreği yağ bağladı, 2 Bense zevk alırım yasandan.'),
(1999342,68,19,119,71,'İyi oldu acı çekmem; 2 Çünkü kurallarını öğreniyorum.'),
(1999343,68,19,119,72,'Ağzından çıkan yasa benim için 2 Binlerce altın ve gümüşten daha değerlidir.'),
(1999344,68,19,119,73,'Senin ellerin beni yarattı, biçimlendirdi. 2 Anlamamı sağla ki buyruklarını öğreneyim.'),
(1999345,68,19,119,74,'Senden korkanlar beni görünce sevinsin, 2 Çünkü senin sözüne umut bağladım.'),
(1999346,68,19,119,75,'Biliyorum, ya RAB, hükümlerin adildir; 2 Bana acı çektirirken bile sadıksın.'),
(1999347,68,19,119,76,'Ben kuluna verdiğin söz uyarınca, 2 Sevgin beni avutsun.'),
(1999348,68,19,119,77,'Sevecenlik göster bana, yaşayayım, 2 Çünkü yasandan zevk alıyorum.'),
(1999349,68,19,119,78,'Utansın küstahlar beni yalan yere suçladıkları için. 2 Bense senin koşullarını düşünüyorum.'),
(1999350,68,19,119,79,'Bana dönsün senden korkanlar, 2 Öğütlerini bilenler.'),
(1999351,68,19,119,80,'Yüreğim kusursuz uysun kurallarına, 2 Öyle ki, utanç duymayayım.'),
(1999352,68,19,119,81,'İçim tükeniyor senin kurtarışını özlerken, 2 Senin sözüne umut bağladım ben.'),
(1999353,68,19,119,82,'Gözümün feri sönüyor söz verdiklerini beklemekten, 2 ‹‹Ne zaman avutacaksın beni?›› diye soruyorum.'),
(1999354,68,19,119,83,'Dumandan kararmış tuluma döndüm, 2 Yine de unutmuyorum kurallarını.'),
(1999355,68,19,119,84,'Daha ne kadar bekleyecek kulun? 2 Ne zaman yargılayacaksın bana zulmedenleri?'),
(1999356,68,19,119,85,'Çukur kazdılar benim için 2 Yasana uymayan küstahlar.'),
(1999357,68,19,119,86,'Bütün buyrukların güvenilirdir; 2 Haksız yere zulmediyorlar, yardım et bana!'),
(1999358,68,19,119,87,'Nerdeyse sileceklerdi beni yeryüzünden, 2 Ama ben senin koşullarından ayrılmadım.'),
(1999359,68,19,119,88,'Koru canımı sevgin uyarınca, 2 Tutayım ağzından çıkan öğütleri.'),
(1999360,68,19,119,89,'Ya RAB, sözün 2 Göklerde sonsuza dek duruyor.'),
(1999361,68,19,119,90,'Sadakatin kuşaklar boyu sürüyor, 2 Kurduğun yeryüzü sapasağlam duruyor.'),
(1999362,68,19,119,91,'Bugün hükümlerin uyarınca ayakta duran her şey 2 Sana kulluk ediyor.'),
(1999363,68,19,119,92,'Eğer yasan zevk kaynağım olmasaydı, 2 Çektiğim acılardan yok olurdum.'),
(1999364,68,19,119,93,'Koşullarını asla unutmayacağım, 2 Çünkü onlarla bana yaşam verdin.'),
(1999365,68,19,119,94,'Kurtar beni, çünkü seninim, 2 Senin koşullarına yöneldim.'),
(1999366,68,19,119,95,'Kötüler beni yok etmeyi beklerken, 2 Ben senin öğütlerini inceliyorum.'),
(1999367,68,19,119,96,'Kusursuz olan her şeyin bir sonu olduğunu gördüm, 2 Ama senin buyruğun sınır tanımaz.'),
(1999368,68,19,119,97,'Ne kadar severim yasanı! 2 Bütün gün düşünürüm onun üzerinde.'),
(1999369,68,19,119,98,'Buyrukların beni düşmanlarımdan bilge kılar, 2 Çünkü her zaman aklımdadır onlar.'),
(1999370,68,19,119,99,'Bütün öğretmenlerimden daha akıllıyım, 2 Çünkü öğütlerin üzerinde düşünüyorum.'),
(1999371,68,19,119,100,'Yaşlılardan daha bilgeyim, 2 Çünkü senin koşullarına uyuyorum.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999372,68,19,119,101,'Sakınırım her kötü yoldan, 2 Senin sözünü tutmak için.'),
(1999373,68,19,119,102,'Ayrılmam hükümlerinden, 2 Çünkü bana sen öğrettin.'),
(1999374,68,19,119,103,'Ne tatlı geliyor verdiğin sözler damağıma, 2 Baldan tatlı geliyor ağzıma!'),
(1999375,68,19,119,104,'Senin koşullarına uymakla bilgelik kazanıyorum, 2 Bu yüzden nefret ediyorum her yanlış yoldan.'),
(1999376,68,19,119,105,'Sözün adımlarım için çıra, 2 Yolum için ışıktır.'),
(1999377,68,19,119,106,'Adil hükümlerini izleyeceğime ant içtim, 2 Andımı tutacağım.'),
(1999378,68,19,119,107,'Çok sıkıntı çektim, ya RAB; 2 Koru hayatımı sözün uyarınca.'),
(1999379,68,19,119,108,'Ağzımdan çıkan içten övgüleri 2 Kabul et, ya RAB, 2 Bana hükümlerini öğret.'),
(1999380,68,19,119,109,'Hayatım her an tehlikede, 2 Yine de unutmam yasanı.'),
(1999381,68,19,119,110,'Kötüler tuzak kurdu bana, 2 Yine de sapmadım senin koşullarından.'),
(1999382,68,19,119,111,'Öğütlerin sonsuza dek mirasımdır, 2 Yüreğimin sevincidir onlar.'),
(1999383,68,19,119,112,'Kararlıyım 2 Sonuna kadar senin kurallarına uymaya.'),
(1999384,68,19,119,113,'Döneklerden tiksinir, 2 Senin yasanı severim.'),
(1999385,68,19,119,114,'Sığınağım ve kalkanım sensin, 2 Senin sözüne umut bağlarım.'),
(1999386,68,19,119,115,'Ey kötüler, benden uzak durun, 2 Tanrımın buyruklarını yerine getireyim.'),
(1999387,68,19,119,116,'Sözün uyarınca destek ol bana, yaşam bulayım; 2 Umudumu boşa çıkarma!'),
(1999388,68,19,119,117,'Sıkı tut beni, kurtulayım, 2 Her zaman kurallarını dikkate alayım.'),
(1999389,68,19,119,118,'Kurallarından sapan herkesi reddedersin, 2 Çünkü onların hileleri boştur.'),
(1999390,68,19,119,119,'Dünyadaki kötüleri cüruf gibi atarsın, 2 Bu yüzden severim senin öğütlerini.'),
(1999391,68,19,119,120,'Bedenim ürperiyor dehşetinden, 2 Korkuyorum hükümlerinden.'),
(1999392,68,19,119,121,'Adil ve doğru olanı yaptım, 2 Gaddarların eline bırakma beni!'),
(1999393,68,19,119,122,'Güven altına al kulunun mutluluğunu, 2 Baskı yapmasın bana küstahlar.'),
(1999394,68,19,119,123,'Gözümün feri sönüyor, 2 Beni kurtarmanı, 2 Adil sözünü yerine getirmeni beklemekten.'),
(1999395,68,19,119,124,'Kuluna sevgin uyarınca davran, 2 Bana kurallarını öğret.'),
(1999396,68,19,119,125,'Ben senin kulunum, bana akıl ver ki, 2 Öğütlerini anlayabileyim.'),
(1999397,68,19,119,126,'Ya RAB, harekete geçmenin zamanıdır, 2 Yasanı çiğniyorlar.'),
(1999398,68,19,119,127,'Bu yüzden senin buyruklarını, 2 Altından, saf altından daha çok seviyorum;'),
(1999399,68,19,119,128,'Koyduğun koşulların hepsini doğru buluyorum, 2 Her yanlış yoldan tiksiniyorum.'),
(1999400,68,19,119,129,'Harika öğütlerin var, 2 Bu yüzden onlara candan uyuyorum.'),
(1999401,68,19,119,130,'Sözlerinin açıklanışı aydınlık saçar, 2 Saf insanlara akıl verir.'),
(1999402,68,19,119,131,'Ağzım açık, soluk soluğayım, 2 Çünkü buyruklarını özlüyorum.'),
(1999403,68,19,119,132,'Bana lütufla bak, 2 Adını sevenlere her zaman yaptığın gibi.'),
(1999404,68,19,119,133,'Adımlarımı pekiştir verdiğin söz uyarınca, 2 Hiçbir suç bana egemen olmasın.'),
(1999405,68,19,119,134,'Kurtar beni insan baskısından, 2 Koşullarına uyabileyim.'),
(1999406,68,19,119,135,'Yüzün aydınlık saçsın kulunun üzerine, 2 Kurallarını öğret bana.'),
(1999407,68,19,119,136,'Oluk oluk yaş akıyor gözlerimden, 2 Çünkü uymuyorlar yasana.'),
(1999408,68,19,119,137,'Sen adilsin, ya RAB, 2 Hükümlerin doğrudur.'),
(1999409,68,19,119,138,'Buyurduğun öğütler doğru 2 Ve tam güvenilirdir.'),
(1999410,68,19,119,139,'Gayretim beni tüketti, 2 Çünkü düşmanlarım unuttu senin sözlerini.'),
(1999411,68,19,119,140,'Sözün çok güvenilirdir, 2 Kulun onu sever.'),
(1999412,68,19,119,141,'Önemsiz ve horlanan biriyim ben, 2 Ama koşullarını unutmuyorum.'),
(1999413,68,19,119,142,'Adaletin sonsuza dek doğrudur, 2 Yasan gerçektir.'),
(1999414,68,19,119,143,'Sıkıntıya, darlığa düştüm, 2 Ama buyrukların benim zevkimdir.'),
(1999415,68,19,119,144,'Öğütlerin sonsuza dek doğrudur; 2 Bana akıl ver ki, yaşayayım.'),
(1999416,68,19,119,145,'Bütün yüreğimle haykırıyorum, 2 Yanıtla beni, ya RAB! 2 Senin kurallarına uyacağım.'),
(1999417,68,19,119,146,'Sana sesleniyorum, 2 Kurtar beni, 2 Öğütlerine uyayım.'),
(1999418,68,19,119,147,'Gün doğmadan kalkıp yardım dilerim, 2 Senin sözüne umut bağladım.'),
(1999419,68,19,119,148,'Verdiğin söz üzerinde düşüneyim diye, 2 Gece boyunca uyku girmiyor gözüme.'),
(1999420,68,19,119,149,'Sevgin uyarınca sesime kulak ver, 2 Hükümlerin uyarınca, ya RAB, yaşam ver bana!'),
(1999421,68,19,119,150,'Yaklaşıyor kötülük ardınca koşanlar, 2 Yasandan uzaklaşıyorlar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999422,68,19,119,151,'Oysa sen yakınsın, ya RAB, 2 Bütün buyrukların gerçektir.'),
(1999423,68,19,119,152,'Çoktan beri anladım 2 Öğütlerini sonsuza dek verdiğini.'),
(1999424,68,19,119,153,'Çektiğim sıkıntıyı gör, kurtar beni, 2 Çünkü yasanı unutmadım.'),
(1999425,68,19,119,154,'Davamı savun, özgür kıl beni, 2 Sözün uyarınca koru canımı.'),
(1999426,68,19,119,155,'Kurtuluş kötülerden uzaktır, 2 Çünkü senin kurallarına yönelmiyorlar.'),
(1999427,68,19,119,156,'Çok sevecensin, ya RAB, 2 Hükümlerin uyarınca koru canımı.'),
(1999428,68,19,119,157,'Bana zulmedenler, düşmanlarım çok, 2 Yine de sapmadım senin öğütlerinden.'),
(1999429,68,19,119,158,'Tiksinerek bakıyorum hainlere, 2 Çünkü uymuyorlar senin sözüne.'),
(1999430,68,19,119,159,'Bak, ne kadar seviyorum koşullarını, 2 Sevgin uyarınca, ya RAB, koru canımı.'),
(1999431,68,19,119,160,'Sözlerinin temeli gerçektir, 2 Doğru hükümlerinin tümü sonsuza dek sürecektir.'),
(1999432,68,19,119,161,'Yok yere zulmediyor bana önderler, 2 Oysa yüreğim senin sözünle titrer.'),
(1999433,68,19,119,162,'Ganimet bulan biri gibi 2 Verdiğin sözlerde sevinç bulurum.'),
(1999434,68,19,119,163,'Tiksinir, iğrenirim yalandan, 2 Ama senin yasanı severim.'),
(1999435,68,19,119,164,'Doğru hükümlerin için 2 Seni günde yedi kez överim.'),
(1999436,68,19,119,165,'Yasanı sevenler büyük esenlik bulur, 2 Hiçbir şey sendeletmez onları.'),
(1999437,68,19,119,166,'Ya RAB, kurtarışına umut bağlar, 2 Buyruklarını yerine getiririm.'),
(1999438,68,19,119,167,'Öğütlerine candan uyar, 2 Onları çok severim.'),
(1999439,68,19,119,168,'Öğütlerini, koşullarını uygularım, 2 Çünkü bütün davranışlarımı görürsün sen.'),
(1999440,68,19,119,169,'Feryadım sana erişsin, ya RAB, 2 Sözün uyarınca akıl ver bana!'),
(1999441,68,19,119,170,'Yalvarışım sana ulaşsın; 2 Verdiğin söz uyarınca kurtar beni!'),
(1999442,68,19,119,171,'Dudaklarımdan övgüler aksın, 2 Çünkü bana kurallarını öğretiyorsun.'),
(1999443,68,19,119,172,'Dilimde sözün ezgilere dönüşsün, 2 Çünkü bütün buyrukların doğrudur.'),
(1999444,68,19,119,173,'Elin bana yardıma hazır olsun, 2 Çünkü senin koşullarını seçtim ben.'),
(1999445,68,19,119,174,'Kurtarışını özlüyorum, ya RAB, 2 Yasan zevk kaynağımdır.'),
(1999446,68,19,119,175,'Beni yaşat ki, sana övgüler sunayım, 2 Hükümlerin bana yardımcı olsun.'),
(1999447,68,19,119,176,'Kaybolmuş koyun gibi avare dolaşıyordum; 2 Kulunu ara, 2 Çünkü buyruklarını unutmadım ben.'),
(1999448,68,19,120,1,'Sıkıntıya düşünce RABbe seslendim; 2 Yanıtladı beni.'),
(1999449,68,19,120,2,'Ya RAB, kurtar canımı yalancı dudaklardan, 2 Aldatıcı dillerden! için Yeruşalime çıkarken söylenen ezgi.'),
(1999450,68,19,120,3,'Ey aldatıcı dil, 2 RAB ne verecek sana, 2 Daha ne verecek?'),
(1999451,68,19,120,4,'Yiğidin sivri oklarıyla 2 Retem çalısından alevli korlar!'),
(1999452,68,19,120,5,'Vay bana, Meşekte garip kaldım sanki, 2 Kedar çadırları arasında oturdum.'),
(1999453,68,19,120,6,'Fazla kaldım 2 Barıştan nefret edenler arasında.'),
(1999454,68,19,120,7,'Ben barış yanlısıyım, 2 Ama söze başladığımda, 2 Onlar savaşa kalkıyor!'),
(1999455,68,19,121,1,'Gözlerimi dağlara kaldırıyorum, 2 Nereden yardım gelecek?'),
(1999456,68,19,121,2,'Yeri göğü yaratan 2 RABden gelecek yardım.'),
(1999457,68,19,121,3,'O ayaklarının kaymasına izin vermez, 2 Seni koruyan uyuklamaz.'),
(1999458,68,19,121,4,'İsrailin koruyucusu ne uyur ne uyuklar.'),
(1999459,68,19,121,5,'Senin koruyucun RABdir, 2 O sağ yanında sana gölgedir.'),
(1999460,68,19,121,6,'Gündüz güneş, 2 Gece ay sana zarar vermez.'),
(1999461,68,19,121,7,'RAB her kötülükten seni korur, 2 Esirger canını.'),
(1999462,68,19,121,8,'Şimdiden sonsuza dek 2 RAB koruyacak gidişini, gelişini.'),
(1999463,68,19,122,1,'Bana: ‹‹RABbin evine gidelim›› dendikçe 2 Sevinirim.'),
(1999464,68,19,122,2,'Ayaklarımız senin kapılarında, 2 Ey Yeruşalim!'),
(1999465,68,19,122,3,'Bitişik nizamda kurulmuş bir kenttir 2 Yeruşalim!'),
(1999466,68,19,122,4,'Oymaklar çıkar oraya, RABbin oymakları, 2 İsraile verilen öğüt uyarınca, 2 RABbin adına şükretmek için.'),
(1999467,68,19,122,5,'Çünkü orada yargı tahtları, 2 Davut soyunun tahtları kurulmuştur.'),
(1999468,68,19,122,6,'Esenlik dileyin Yeruşalime: 2 ‹‹Huzur bulsun seni sevenler!'),
(1999469,68,19,122,7,'Surlarına esenlik, 2 Saraylarına huzur egemen olsun!››'),
(1999470,68,19,122,8,'Kardeşlerim, dostlarım için, 2 ‹‹Esenlik olsun sana!›› derim.'),
(1999471,68,19,122,9,'Tanrımız RAB''bin evi için 2 İyilik dilerim sana.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999472,68,19,123,1,'Gözlerimi sana kaldırıyorum, 2 Ey göklerde taht kuran!'),
(1999473,68,19,123,2,'Nasıl kulların gözleri efendilerinin, 2 Hizmetçinin gözleri hanımının eline bakarsa, 2 Bizim gözlerimiz de RAB Tanrımıza öyle bakar, 2 O bize acıyıncaya dek.'),
(1999474,68,19,123,3,'Acı bize, ya RAB, acı; 2 Gördüğümüz hakaret yeter de artar.'),
(1999475,68,19,123,4,'Rahat yaşayanların alayları, 2 Küstahların hakareti 2 Canımıza yetti.'),
(1999476,68,19,124,1,'RAB bizden yana olmasaydı, 2 Desin şimdi İsrail:'),
(1999477,68,19,124,2,'RAB bizden yana olmasaydı, 2 İnsanlar bize saldırdığında,'),
(1999478,68,19,124,3,'Diri diri yutarlardı bizi, 2 Öfkeleri bize karşı alevlenince.'),
(1999479,68,19,124,4,'Sular silip süpürürdü bizleri, 2 Seller geçerdi üzerimizden.'),
(1999480,68,19,124,5,'Kabaran sular 2 Aşardı başımızdan.'),
(1999481,68,19,124,6,'Övgüler olsun 2 Bizi onların ağzına yem etmeyen RABbe!'),
(1999482,68,19,124,7,'Bir kuş gibi 2 Kurtuldu canımız avcının tuzağından, 2 Kırıldı tuzak, kurtulduk.'),
(1999483,68,19,124,8,'Yeri göğü yaratan 2 RAB''bin adı yardımcımızdır.'),
(1999484,68,19,125,1,'RABbe güvenenler Siyon Dağına benzer, 2 Sarsılmaz, sonsuza dek durur.'),
(1999485,68,19,125,2,'Dağlar Yeruşalimi nasıl kuşatmışsa, 2 RAB de halkını öyle kuşatmıştır, 2 Şimdiden sonsuza dek.'),
(1999486,68,19,125,3,'Kalmayacak kötülerin asası, 2 Doğruların payına düşen toprakta, 2 Yoksa doğrular haksızlığa el uzatabilir.'),
(1999487,68,19,125,4,'İyilik et, ya RAB, 2 İyilere, yüreği temiz olanlara.'),
(1999488,68,19,125,5,'Ama kendi halkından eğri yollara sapanları, 2 RAB kötü uluslarla birlikte kovacak. İsrail''e esenlik olsun!'),
(1999489,68,19,126,1,'RAB sürgünleri Siyona geri getirince, 2 Rüya gibi geldi bize. Siyonu eski gönencine kavuşturunca››.'),
(1999490,68,19,126,2,'Ağzımız gülüşlerle, 2 Dilimiz sevinç çığlıklarıyla doldu. 2 ‹‹RAB onlar için büyük işler yaptı›› 2 Diye konuşuldu uluslar arasında.'),
(1999491,68,19,126,3,'RAB bizim için büyük işler yaptı, 2 Sevinç doldu içimiz.'),
(1999492,68,19,126,4,'Ya RAB, eski gönencimize kavuştur bizi, 2 Negevde suya kavuşan vadiler gibi.'),
(1999493,68,19,126,5,'Gözyaşları içinde ekenler, 2 Sevinç çığlıklarıyla biçecek;'),
(1999494,68,19,126,6,'Ağlayarak tohum çuvalını taşıyıp dolaşan, 2 Sevinç çığlıkları atarak demetlerle dönecek.'),
(1999495,68,19,127,1,'Evi RAB yapmazsa, 2 Yapıcılar boşuna didinir. 2 Kenti RAB korumazsa, 2 Bekçi boşuna bekler.'),
(1999496,68,19,127,2,'Boşuna erken kalkıp 2 Geç yatıyorsunuz. 2 Ey zahmetle kazanılan ekmeği yiyenler, 2 RAB sevdiklerinin rahat uyumasını sağlar.'),
(1999497,68,19,127,3,'Çocuklar RABbin verdiği bir armağandır, 2 Rahmin ürünü bir ödüldür.'),
(1999498,68,19,127,4,'Yiğidin elinde nasılsa oklar, 2 Öyledir gençlikte doğan çocuklar.'),
(1999499,68,19,127,5,'Ne mutlu ok kılıfı onlarla dolu insana! 2 Kent kapısında hasımlarıyla tartışırken 2 Utanç duymayacaklar. kapısında yapılırdı.'),
(1999500,68,19,128,1,'Ne mutlu RABden korkana, 2 Onun yolunda yürüyene!'),
(1999501,68,19,128,2,'Emeğinin ürününü yiyeceksin, 2 Mutlu ve başarılı olacaksın.'),
(1999502,68,19,128,3,'Eşin evinde verimli bir asma gibi olacak; 2 Çocukların zeytin filizleri gibi sofranın çevresinde.'),
(1999503,68,19,128,4,'İşte RABden korkan kişi 2 Böyle kutsanacak.'),
(1999504,68,19,128,5,'RAB seni Siyondan kutsasın! 2 Yeruşalimin gönencini göresin, 2 Bütün yaşamın boyunca!'),
(1999505,68,19,128,6,'Çocuklarının çocuklarını göresin! İsrail''e esenlik olsun!'),
(1999506,68,19,129,1,'Gençliğimden beri bana sık sık saldırdılar; 2 Şimdi söylesin İsrail:'),
(1999507,68,19,129,2,'‹‹Gençliğimden beri bana sık sık saldırdılar, 2 Ama yenemediler beni.'),
(1999508,68,19,129,3,'Çiftçiler saban sürdüler sırtımda, 2 Upuzun iz bıraktılar.››'),
(1999509,68,19,129,4,'Ama RAB adildir, 2 Kesti kötülerin bağlarını.'),
(1999510,68,19,129,5,'Siyondan nefret eden herkes 2 Utanç içinde geri çekilsin.'),
(1999511,68,19,129,6,'Damlardaki ota, 2 Büyümeden kuruyan ota dönsünler.'),
(1999512,68,19,129,7,'Orakçı avucunu, 2 Demetçi kucağını dolduramaz onunla.'),
(1999513,68,19,129,8,'Yoldan geçenler de, 2 ‹‹RAB sizi kutsasın, 2 RAB''bin adıyla sizi kutsarız›› demezler.'),
(1999514,68,19,130,1,'Derinliklerden sana sesleniyorum, ya RAB,'),
(1999515,68,19,130,2,'Sesimi işit, ya Rab, 2 Yalvarışıma iyi kulak ver!'),
(1999516,68,19,130,3,'Ya RAB, sen suçların hesabını tutsan, 2 Kim ayakta kalabilir, ya Rab?'),
(1999517,68,19,130,4,'Ama sen bağışlayıcısın, 2 Öyle ki senden korkulsun.'),
(1999518,68,19,130,5,'RABbi gözlüyorum, 2 Canım RABbi gözlüyor, 2 Umut bağlıyorum Onun sözüne.'),
(1999519,68,19,130,6,'Sabahı gözleyenlerden, 2 Evet, sabahı gözleyenlerden daha çok, 2 Canım Rabbi gözlüyor.'),
(1999520,68,19,130,7,'Ey İsrail, RABbe umut bağla! 2 Çünkü RABde sevgi, 2 Tam kurtuluş vardır.'),
(1999521,68,19,130,8,'İsrail''i bütün suçlarından 2 Fidyeyle O kurtaracaktır.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999522,68,19,131,1,'Ya RAB, yüreğimde gurur yok, 2 Gözüm yükseklerde değil. 2 Büyük işlerle, 2 Kendimi aşan harika işlerle uğraşmıyorum.'),
(1999523,68,19,131,2,'Tersine, ana kucağında sütten kesilmiş çocuk gibi, 2 Kendimi yatıştırıp huzur buldum, 2 Sütten kesilmiş çocuğa döndüm.'),
(1999524,68,19,131,3,'Ey İsrail, RAB''be umut bağla 2 Şimdiden sonsuza dek!'),
(1999525,68,19,132,1,'Ya RAB, Davutun hatırı için, 2 Çektiği bütün zorlukları, 2 Sana nasıl ant içtiğini, 2 Yakupun güçlü Tanrısına adak adadığını anımsa:'),
(1999526,68,19,132,3,'‹‹Evime gitmeyeceğim, 2 Yatağıma uzanmayacağım,'),
(1999527,68,19,132,4,'Gözlerime uyku girmeyecek, 2 Göz kapaklarım kapanmayacak,'),
(1999528,68,19,132,5,'RABbe bir yer, 2 Yakupun güçlü Tanrısına bir konut buluncaya dek.››'),
(1999529,68,19,132,6,'Antlaşma Sandığının Efratada olduğunu duyduk, 2 Onu Yaar kırlarında bulduk.'),
(1999530,68,19,132,7,'‹‹RABbin konutuna gidelim, 2 Ayağının taburesi önünde tapınalım›› dedik.'),
(1999531,68,19,132,8,'Çık, ya RAB, yaşayacağın yere, 2 Gücünü simgeleyen sandıkla birlikte.'),
(1999532,68,19,132,9,'Kâhinlerin doğruluğu kuşansın, 2 Sadık kulların sevinç çığlıkları atsın.'),
(1999533,68,19,132,10,'Kulun Davutun hatırı için, 2 Meshettiğin krala yüz çevirme.'),
(1999534,68,19,132,11,'RAB Davuta kesin ant içti, 2 Andından dönmez: 2 ‹‹Senin soyundan birini tahtına oturtacağım.'),
(1999535,68,19,132,12,'Eğer oğulların antlaşmama, 2 Vereceğim öğütlere uyarlarsa, 2 Onların oğulları da sonsuza dek 2 Senin tahtına oturacak.››'),
(1999536,68,19,132,13,'Çünkü RAB Siyonu seçti, 2 Onu konut edinmek istedi.'),
(1999537,68,19,132,14,'‹‹Sonsuza dek yaşayacağım yer budur›› dedi, 2 ‹‹Burada oturacağım, çünkü bunu kendim istedim.'),
(1999538,68,19,132,15,'Çok bereketli kılacağım erzağını, 2 Yiyecekle doyuracağım yoksullarını.'),
(1999539,68,19,132,16,'Kurtuluşla donatacağım kâhinlerini; 2 Hep sevinç ezgileri söyleyecek sadık kulları.'),
(1999540,68,19,132,17,'Burada Davut soyundan güçlü bir kral çıkaracağım, 2 Meshettiğim kralın soyunu 2 Işık olarak sürdüreceğim.'),
(1999541,68,19,132,18,'Düşmanlarını utanca bürüyeceğim, 2 Ama onun başındaki taç parıldayacak.››'),
(1999542,68,19,133,1,'Ne iyi, ne güzeldir, 2 Birlik içinde kardeşçe yaşamak!'),
(1999543,68,19,133,2,'Başa sürülen değerli yağ gibi, 2 Sakaldan, Harunun sakalından 2 Kaftanının yakasına dek inen yağ gibi.'),
(1999544,68,19,133,3,'Hermon Dağı''na yağan çiy 2 Siyon dağlarına yağıyor sanki. 2 Çünkü RAB orada bereketi, 2 Sonsuz yaşamı buyurdu.'),
(1999545,68,19,134,1,'Ey sizler, RABbin bütün kulları, 2 RABbin Tapınağında gece hizmet edenler, 2 Ona övgüler sunun!'),
(1999546,68,19,134,2,'Ellerinizi kutsal yere doğru kaldırıp 2 RABbe övgüler sunun!'),
(1999547,68,19,134,3,'Yeri göğü yaratan 2 RAB kutsasın sizi Siyon''dan.'),
(1999548,68,19,135,1,'RABbe övgüler sunun! 2 RABbin adına övgüler sunun, 2 Ey RABbin kulları! 2 Ey sizler, RABbin Tapınağında, 2 Tanrımızın Tapınağının avlularında hizmet edenler, 2 Övgüler sunun!'),
(1999549,68,19,135,3,'RABbe övgüler sunun, 2 Çünkü RAB iyidir. 2 Adını ilahilerle övün, 2 Çünkü hoştur bu.'),
(1999550,68,19,135,4,'RAB kendine Yakup soyunu, 2 Öz halkı olarak İsraili seçti.'),
(1999551,68,19,135,5,'Biliyorum, RAB büyüktür, 2 Rabbimiz bütün ilahlardan üstündür.'),
(1999552,68,19,135,6,'RAB ne isterse yapar, 2 Göklerde, yeryüzünde, 2 Denizlerde, bütün derinliklerde.'),
(1999553,68,19,135,7,'Yeryüzünün dört bucağından bulutlar yükseltir, 2 Yağmur için şimşek çaktırır, 2 Ambarlarından rüzgar estirir.'),
(1999554,68,19,135,8,'İnsanlardan hayvanlara dek 2 Mısırda ilk doğanları öldürdü.'),
(1999555,68,19,135,9,'Ey Mısır, senin orta yerinde, 2 Firavunla bütün görevlilerine 2 Belirtiler, şaşılası işler gösterdi.'),
(1999556,68,19,135,10,'Birçok ulusu bozguna uğrattı, 2 Güçlü kralları öldürdü:'),
(1999557,68,19,135,11,'Amorlu kral Sihonu, 2 Başan Kralı Ogu, 2 Bütün Kenan krallarını.'),
(1999558,68,19,135,12,'Topraklarını mülk, 2 Evet, mülk olarak halkı İsraile verdi.'),
(1999559,68,19,135,13,'Ya RAB, adın sonsuza dek sürecek, 2 Bütün kuşaklar seni anacak.'),
(1999560,68,19,135,14,'RAB halkını haklı çıkarır, 2 Kullarına acır.'),
(1999561,68,19,135,15,'Ulusların putları altın ve gümüşten yapılmış, 2 İnsan elinin eseridir.'),
(1999562,68,19,135,16,'Ağızları var, konuşmazlar, 2 Gözleri var, görmezler,'),
(1999563,68,19,135,17,'Kulakları var, duymazlar, 2 Soluk alıp vermezler.'),
(1999564,68,19,135,18,'Onları yapan, onlara güvenen herkes 2 Onlar gibi olacak!'),
(1999565,68,19,135,19,'Ey İsrail halkı, RABbe övgüler sun! 2 Ey Harun soyu, RABbe övgüler sun!'),
(1999566,68,19,135,20,'Ey Levi soyu, RABbe övgüler sun! 2 RABbe övgüler sunun, ey RABden korkanlar!'),
(1999567,68,19,135,21,'Yeruşalim''de oturan RAB''be 2 Siyon''dan övgüler sunulsun! RAB''be övgüler sunun!'),
(1999568,68,19,136,1,'Şükredin RABbe, çünkü O iyidir, 2 |iSevgisi sonsuzdur;'),
(1999569,68,19,136,2,'Şükredin tanrılar Tanrısına, 2 |iSevgisi sonsuzdur;'),
(1999570,68,19,136,3,'Şükredin rabler Rabbine, 2 |iSevgisi sonsuzdur;'),
(1999571,68,19,136,4,'Büyük harikalar yapan tek varlığa, 2 |iSevgisi sonsuzdur;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999572,68,19,136,5,'Gökleri bilgece yaratana, 2 |iSevgisi sonsuzdur;'),
(1999573,68,19,136,6,'Yeri sular üzerine yayana, 2 |iSevgisi sonsuzdur;'),
(1999574,68,19,136,7,'Büyük ışıklar yaratana, 2 |iSevgisi sonsuzdur;'),
(1999575,68,19,136,8,'Gündüze egemen olsun diye güneşi, 2 |iSevgisi sonsuzdur;'),
(1999576,68,19,136,9,'Geceye egemen olsun diye ayı ve yıldızları yaratana, 2 |iSevgisi sonsuzdur;'),
(1999577,68,19,136,10,'Mısırda ilk doğanları öldürene, 2 |iSevgisi sonsuzdur;'),
(1999578,68,19,136,11,'Güçlü eli, kudretli koluyla 2 |iSevgisi sonsuzdur; 2 İsraili Mısırdan çıkarana, 2 |iSevgisi sonsuzdur;'),
(1999579,68,19,136,13,'Kızıldenizi ikiye bölene, 2 |iSevgisi sonsuzdur;'),
(1999580,68,19,136,14,'İsraili ortasından geçirene, 2 |iSevgisi sonsuzdur;'),
(1999581,68,19,136,15,'Firavunla ordusunu Kızıldenize dökene, 2 |iSevgisi sonsuzdur;'),
(1999582,68,19,136,16,'Kendi halkını çölde yürütene, 2 |iSevgisi sonsuzdur;'),
(1999583,68,19,136,17,'Büyük kralları vurana, 2 |iSevgisi sonsuzdur;'),
(1999584,68,19,136,18,'Güçlü kralları öldürene, 2 |iSevgisi sonsuzdur;'),
(1999585,68,19,136,19,'Amorlu kral Sihonu, 2 |iSevgisi sonsuzdur;'),
(1999586,68,19,136,20,'Başan Kralı Ogu öldürene, 2 |iSevgisi sonsuzdur;'),
(1999587,68,19,136,21,'Topraklarını mülk olarak, 2 |iSevgisi sonsuzdur; 2 Kulu İsraile mülk verene, 2 |iSevgisi sonsuzdur;'),
(1999588,68,19,136,23,'Düşkün günlerimizde bizi anımsayana, 2 |iSevgisi sonsuzdur;'),
(1999589,68,19,136,24,'Düşmanlarımızdan bizi kurtarana, 2 |iSevgisi sonsuzdur;'),
(1999590,68,19,136,25,'Bütün canlılara yiyecek verene, 2 |iSevgisi sonsuzdur;'),
(1999591,68,19,136,26,'Şükredin Göklerin Tanrısı''na, 2 |iSevgisi sonsuzdur.'),
(1999592,68,19,137,1,'Babil ırmakları kıyısında oturup 2 Siyonu andıkça ağladık;'),
(1999593,68,19,137,2,'Çevredeki kavaklara 2 Lirlerimizi astık.'),
(1999594,68,19,137,3,'Çünkü orada bizi tutsak edenler bizden ezgiler, 2 Bize zulmedenler bizden şenlik istiyor, 2 ‹‹Siyon ezgilerinden birini okuyun bize!›› diyorlardı.'),
(1999595,68,19,137,4,'Nasıl okuyabiliriz RABbin ezgisini 2 El toprağında?'),
(1999596,68,19,137,5,'Ey Yeruşalim, seni unutursam, 2 Sağ elim kurusun.'),
(1999597,68,19,137,6,'Seni anmaz, 2 Yeruşalimi en büyük sevincimden üstün tutmazsam, 2 Dilim damağıma yapışsın!'),
(1999598,68,19,137,7,'Yeruşalimin düştüğü gün, 2 ‹‹Yıkın onu, yıkın temellerine kadar!›› 2 Diyen Edomluların tavrını anımsa, ya RAB.'),
(1999599,68,19,137,8,'Ey sen, yıkılası Babil kızı, 2 Bize yaptıklarını 2 Sana ödetecek olana ne mutlu!'),
(1999600,68,19,137,9,'Ne mutlu senin yavrularını tutup 2 Kayalarda parçalayacak insana!'),
(1999601,68,19,138,1,'Bütün yüreğimle sana şükrederim, ya RAB, 2 İlahlar önünde seni ilahilerle överim.'),
(1999602,68,19,138,2,'Kutsal tapınağına doğru eğilir, 2 Adına şükrederim, 2 Sevgin, sadakatin için. 2 Çünkü adını ve sözünü her şeyden üstün tuttun.'),
(1999603,68,19,138,3,'Seslendiğim gün bana yanıt verdin, 2 İçime güç koydun, beni yüreklendirdin.'),
(1999604,68,19,138,4,'Şükretsin sana, ya RAB, yeryüzü krallarının tümü, 2 Çünkü ağzından çıkan sözleri işittiler.'),
(1999605,68,19,138,5,'Yaptığın işleri ezgilerle övsünler, ya RAB, 2 Çünkü çok yücesin.'),
(1999606,68,19,138,6,'RAB yüksekse de, 2 Alçakgönüllüleri gözetir, 2 Küstahları uzaktan tanır.'),
(1999607,68,19,138,7,'Sıkıntıya düşersem, canımı korur, 2 Düşmanlarımın öfkesine karşı el kaldırırsın, 2 Sağ elin beni kurtarır.'),
(1999608,68,19,138,8,'Ya RAB, her şeyi yaparsın benim için. 2 Sevgin sonsuzdur, ya RAB, 2 Elinin eserini bırakma!'),
(1999609,68,19,139,1,'Ya RAB, sınayıp tanıdın beni.'),
(1999610,68,19,139,2,'Oturup kalkışımı bilirsin, 2 Niyetimi uzaktan anlarsın.'),
(1999611,68,19,139,3,'Gittiğim yolu, yattığım yeri inceden inceye elersin, 2 Bütün yaptıklarımdan haberin var.'),
(1999612,68,19,139,4,'Daha sözü ağzıma almadan, 2 Söyleyeceğim her şeyi bilirsin, ya RAB.'),
(1999613,68,19,139,5,'Beni çepeçevre kuşattın, 2 Elini üzerime koydun.'),
(1999614,68,19,139,6,'Kaldıramam böylesi bir bilgiyi, 2 Başa çıkamam, erişemem.'),
(1999615,68,19,139,7,'Nereye gidebilirim senin Ruhundan, 2 Nereye kaçabilirim huzurundan?'),
(1999616,68,19,139,8,'Göklere çıksam, oradasın, 2 Ölüler diyarına yatak sersem, yine oradasın.'),
(1999617,68,19,139,9,'Seherin kanatlarını alıp uçsam, 2 Denizin ötesine konsam,'),
(1999618,68,19,139,10,'Orada bile elin yol gösterir bana, 2 Sağ elin tutar beni.'),
(1999619,68,19,139,11,'Desem ki, ‹‹Karanlık beni kaplasın, 2 Çevremdeki aydınlık geceye dönsün.››'),
(1999620,68,19,139,12,'Karanlık bile karanlık sayılmaz senin için, 2 Gece, gündüz gibi ışıldar, 2 Karanlıkla aydınlık birdir senin için.'),
(1999621,68,19,139,13,'İç varlığımı sen yarattın, 2 Annemin rahminde beni sen ördün.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999622,68,19,139,14,'Sana övgüler sunarım, 2 Çünkü müthiş ve harika yaratılmışım. 2 Ne harika işlerin var! 2 Bunu çok iyi bilirim.'),
(1999623,68,19,139,15,'Gizli yerde yaratıldığımda, 2 Yerin derinliklerinde örüldüğümde, 2 Bedenim senden gizli değildi.'),
(1999624,68,19,139,16,'Henüz döl yatağındayken gözlerin gördü beni; 2 Bana ayrılan günlerin hiçbiri gelmeden, 2 Hepsi senin kitabına yazılmıştı.'),
(1999625,68,19,139,17,'Hakkımdaki düşüncelerin ne değerli, ey Tanrı, 2 Sayıları ne çok!'),
(1999626,68,19,139,18,'Kum tanelerinden fazladır saymaya kalksam. 2 Uyanıyorum, hâlâ seninleyim.'),
(1999627,68,19,139,19,'Ey Tanrı, keşke kötüleri öldürsen! 2 Ey eli kanlı insanlar, uzaklaşın benden!'),
(1999628,68,19,139,20,'Çünkü senin için kötü konuşuyorlar, 2 Adını kötüye kullanıyor düşmanların.'),
(1999629,68,19,139,21,'Ya RAB, nasıl tiksinmem senden tiksinenlerden? 2 Nasıl iğrenmem sana başkaldıranlardan?'),
(1999630,68,19,139,22,'Onlardan tümüyle nefret ediyor, 2 Onları düşman sayıyorum.'),
(1999631,68,19,139,23,'Ey Tanrı, yokla beni, tanı yüreğimi, 2 Sına beni, öğren kaygılarımı.'),
(1999632,68,19,139,24,'Bak, seni gücendiren bir yönüm var mı, 2 Öncülük et bana sonsuz yaşam yolunda!'),
(1999633,68,19,140,1,'Ya RAB, kurtar beni kötü insandan, 2 Koru beni zorbadan.'),
(1999634,68,19,140,2,'Onlar yüreklerinde kötülük tasarlar, 2 Savaşı sürekli körükler,'),
(1999635,68,19,140,3,'Yılan gibi dillerini bilerler, 2 Engerek zehiri var dudaklarının altında. |iSela'),
(1999636,68,19,140,4,'Ya RAB, sakın beni kötünün elinden, 2 Koru beni zorbadan; 2 Bana çelme takmayı tasarlıyorlar.'),
(1999637,68,19,140,5,'Küstahlar benim için tuzak kurdu, 2 Haydutlar ağ gerdi; 2 Yol kenarına kapan koydular benim için. |iSela'),
(1999638,68,19,140,6,'Sana diyorum, ya RAB: ‹‹Tanrım sensin.›› 2 Yalvarışıma kulak ver, ya RAB.'),
(1999639,68,19,140,7,'Ey Egemen RAB, güçlü kurtarıcım, 2 Savaş gününde başımı korudun.'),
(1999640,68,19,140,8,'Kötülerin dileklerini yerine getirme, ya RAB, 2 Tasarılarını ileri götürme! 2 Yoksa gurura kapılırlar. |iSela'),
(1999641,68,19,140,9,'Beni kuşatanların başını, 2 Dudaklarından dökülen fesat kaplasın.'),
(1999642,68,19,140,10,'Kızgın korlar yağsın üzerlerine! 2 Ateşe, dipsiz çukurlara atılsınlar, 2 Bir daha kalkamasınlar.'),
(1999643,68,19,140,11,'İftiracılara ülkede hayat kalmasın, 2 Felaket zorbaları amansızca avlasın.'),
(1999644,68,19,140,12,'Biliyorum, RAB mazlumun davasını savunur, 2 Yoksulları haklı çıkarır.'),
(1999645,68,19,140,13,'Kuşkusuz doğrular senin adına şükredecek, 2 Dürüstler senin huzurunda oturacak.'),
(1999646,68,19,141,1,'Seni çağırıyorum, ya RAB, yardımıma koş! 2 Sana yakarınca sesime kulak ver!'),
(1999647,68,19,141,2,'Duam önünde yükselen buhur gibi, 2 El açışım akşam sunusu gibi kabul görsün!'),
(1999648,68,19,141,3,'Ya RAB, ağzıma bekçi koy, 2 Dudaklarımın kapısını koru!'),
(1999649,68,19,141,4,'Yüreğim kötülüğe eğilim göstermesin, 2 Suç işleyenlerin fesadına bulaşmayayım; 2 Onların nefis yemeklerini tatmayayım.'),
(1999650,68,19,141,5,'Doğru insan bana vursa, iyilik sayılır, 2 Azarlasa, başa sürülen yağ gibidir, 2 Başım reddetmez onu. 2 Çünkü duam hep kötülere karşıdır.'),
(1999651,68,19,141,6,'Önderleri kayalardan aşağı atılınca, 2 Dinleyecekler tatlı sözlerimi.'),
(1999652,68,19,141,7,'Sabanla sürülüp yarılmış toprak gibi, 2 Saçılmış kemiklerimiz ölüler diyarının ağzına.'),
(1999653,68,19,141,8,'Ancak gözlerim sende, ey Egemen RAB, 2 Sana sığınıyorum, beni savunmasız bırakma!'),
(1999654,68,19,141,9,'Koru beni kurdukları tuzaktan, 2 Suç işleyenlerin kapanlarından.'),
(1999655,68,19,141,10,'Ben güvenlik içinde geçip giderken, 2 Kendi ağlarına düşsün kötüler.'),
(1999656,68,19,142,1,'Yüksek sesle yakarıyorum RABbe, 2 Yüksek sesle RABbe yalvarıyorum.'),
(1999657,68,19,142,2,'Önüne döküyorum yakınmalarımı, 2 Önünde anlatıyorum sıkıntılarımı.'),
(1999658,68,19,142,3,'Bunalıma düştüğümde, 2 Gideceğim yolu sen bilirsin. 2 Tuzak kurdular yürüdüğüm yola.'),
(1999659,68,19,142,4,'Sağıma bak da gör, 2 Kimse saymıyor beni, 2 Sığınacak yerim kalmadı, 2 Kimse aramıyor beni.'),
(1999660,68,19,142,5,'Sana haykırıyorum, ya RAB: 2 ‹‹Sığınağım, 2 Yaşadığımız bu dünyada nasibim sensin›› diyorum.'),
(1999661,68,19,142,6,'Haykırışıma kulak ver, 2 Çünkü çok çaresizim; 2 Kurtar beni ardıma düşenlerden, 2 Çünkü benden güçlüler.'),
(1999662,68,19,142,7,'Çıkar beni zindandan, 2 Adına şükredeyim. 2 O zaman doğrular çevremi saracak, 2 Bana iyilik ettiğin için.'),
(1999663,68,19,143,1,'Duamı işit, ya RAB, 2 Yalvarışlarıma kulak ver! 2 Sadakatinle, doğruluğunla yanıtla beni!'),
(1999664,68,19,143,2,'Kulunla yargıya girme, 2 Çünkü hiçbir canlı senin karşında aklanmaz.'),
(1999665,68,19,143,3,'Düşman beni kovalıyor, 2 Ezip yere seriyor. 2 Çoktan ölmüş olanlar gibi, 2 Beni karanlıklarda oturtuyor.'),
(1999666,68,19,143,4,'Bu yüzden bunalıma düştüm, 2 Yüreğim perişan.'),
(1999667,68,19,143,5,'Geçmiş günleri anıyor, 2 Bütün yaptıklarını derin derin düşünüyor, 2 Ellerinin işine bakıp dalıyorum.'),
(1999668,68,19,143,6,'Ellerimi sana açıyorum, 2 Canım kurak toprak gibi sana susamış. |iSela'),
(1999669,68,19,143,7,'Çabuk yanıtla beni, ya RAB, 2 Tükeniyorum. 2 Çevirme benden yüzünü, 2 Yoksa ölüm çukuruna inen ölülere dönerim.'),
(1999670,68,19,143,8,'Sabahları duyur bana sevgini, 2 Çünkü sana güveniyorum; 2 Bana gideceğim yolu bildir, 2 Çünkü duam sanadır.'),
(1999671,68,19,143,9,'Düşmanlarımdan kurtar beni, ya RAB; 2 Sana sığınıyorum.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999672,68,19,143,10,'Bana istemini yapmayı öğret, 2 Çünkü Tanrımsın benim. 2 Senin iyi Ruhun 2 Düz yolda bana öncülük etsin!'),
(1999673,68,19,143,11,'Ya RAB, adın uğruna yaşam ver bana, 2 Doğruluğunla kurtar beni sıkıntıdan.'),
(1999674,68,19,143,12,'Sevginden ötürü, 2 Öldür düşmanlarımı, 2 Yok et bütün hasımlarımı, 2 Çünkü senin kulunum ben.'),
(1999675,68,19,144,1,'Ellerime vuruşmayı, 2 Parmaklarıma savaşmayı öğreten 2 Kayam RABbe övgüler olsun!'),
(1999676,68,19,144,2,'Odur benim vefalı dostum, kalem, 2 Kurtarıcım, kulem, 2 Kalkanım, Ona sığınırım; 2 Odur halkları bana boyun eğdiren!'),
(1999677,68,19,144,3,'Ya RAB, insan ne ki, onu gözetesin, 2 İnsan soyu ne ki, onu düşünesin?'),
(1999678,68,19,144,4,'İnsan bir soluğu andırır, 2 Günleri geçici bir gölge gibidir.'),
(1999679,68,19,144,5,'Ya RAB, gökleri yar, aşağıya in, 2 Dokun dağlara, tütsünler.'),
(1999680,68,19,144,6,'Şimşek çaktır, dağıt düşmanı, 2 Savur oklarını, şaşkına çevir onları.'),
(1999681,68,19,144,7,'Yukarıdan elini uzat, kurtar beni; 2 Çıkar derin sulardan, 2 Al eloğlunun elinden.'),
(1999682,68,19,144,8,'Onların ağzı yalan saçar, 2 Sağ ellerini kaldırır, yalan yere ant içerler.'),
(1999683,68,19,144,9,'Ey Tanrı, sana yeni bir ezgi söyleyeyim, 2 Seni on telli çenkle, ilahilerle öveyim.'),
(1999684,68,19,144,10,'Sensin kralları zafere ulaştıran, 2 Kulun Davutu kötülük kılıcından kurtaran.'),
(1999685,68,19,144,11,'Kurtar beni, özgür kıl 2 Eloğlunun elinden. 2 Onların ağzı yalan saçar, 2 Sağ ellerini kaldırır, yalan yere ant içerler.'),
(1999686,68,19,144,12,'O zaman gençliğinde 2 Sağlıklı yetişen fidan gibi olacak oğullarımız, 2 Sarayın oymalı sütunları gibi olacak kızlarımız.'),
(1999687,68,19,144,13,'Her türlü ürünle dolup taşacak ambarlarımız; 2 Binlerce, on binlerce yavrulayacak 2 Çayırlarda davarlarımız.'),
(1999688,68,19,144,14,'Semiz olacak sığırlarımız; 2 Surlarımıza gedik açılmayacak, 2 İnsanlarımız sürgün edilmeyecek, 2 Meydanlarımızda feryat duyulmayacak!'),
(1999689,68,19,144,15,'Ne mutlu bunlara sahip olan halka! 2 Ne mutlu Tanrısı RAB olan halka!'),
(1999690,68,19,145,1,'Ey Tanrım, ey Kral, seni yücelteceğim, 2 Adını sonsuza dek öveceğim.'),
(1999691,68,19,145,2,'Seni her gün övecek, 2 Adını sonsuza dek yücelteceğim.'),
(1999692,68,19,145,3,'RAB büyüktür, yalnız O övgüye yaraşıktır, 2 Akıl ermez büyüklüğüne.'),
(1999693,68,19,145,4,'Yaptıkların kuşaktan kuşağa şükranla anılacak, 2 Güçlü işlerin duyurulacak.'),
(1999694,68,19,145,5,'Düşüneceğim harika işlerini, 2 İnsanlar büyüklüğünü, yüce görkemini konuşacak.'),
(1999695,68,19,145,6,'Yaptığın müthiş işlerin gücünden söz edecekler, 2 Ben de senin büyüklüğünü duyuracağım.'),
(1999696,68,19,145,7,'Eşsiz iyiliğinin anılarını kutlayacak, 2 Sevinç ezgileriyle övecekler doğruluğunu.'),
(1999697,68,19,145,8,'RAB lütufkâr ve sevecendir, 2 Tez öfkelenmez, sevgisi engindir.'),
(1999698,68,19,145,9,'RAB herkese iyi davranır, 2 Sevecenliği bütün yapıtlarını kapsar.'),
(1999699,68,19,145,10,'Bütün yapıtların sana şükreder, ya RAB, 2 Sadık kulların sana övgüler sunar.'),
(1999700,68,19,145,11,'Krallığının yüceliğini anlatır, 2 Kudretini konuşur;'),
(1999701,68,19,145,12,'Herkes senin gücünü, 2 Krallığının yüce görkemini bilsin diye.'),
(1999702,68,19,145,13,'Senin krallığın ebedi krallıktır, 2 Egemenliğin kuşaklar boyunca sürer. RAB verdiği bütün sözleri tutar, 2 Her davranışı sadıktır.'),
(1999703,68,19,145,14,'RAB her düşene destek olur, 2 İki büklüm olanları doğrultur.'),
(1999704,68,19,145,15,'Herkesin umudu sende, 2 Onlara yiyeceklerini zamanında veren sensin.'),
(1999705,68,19,145,16,'Elini açar, 2 Bütün canlıları doyurursun dilediklerince.'),
(1999706,68,19,145,17,'RAB bütün davranışlarında adil, 2 Yaptığı bütün işlerde sevecendir.'),
(1999707,68,19,145,18,'RAB kendisine yakaran, 2 İçtenlikle yakaran herkese yakındır.'),
(1999708,68,19,145,19,'Dileğini yerine getirir kendisinden korkanların, 2 Feryatlarını işitir, onları kurtarır.'),
(1999709,68,19,145,20,'RAB korur kendisini seven herkesi, 2 Yok eder kötülerin hepsini.'),
(1999710,68,19,145,21,'RAB''be övgüler sunsun ağzım! 2 Bütün canlılar O''nun kutsal adına, 2 Sonsuza dek övgüler dizsin.'),
(1999711,68,19,146,1,'RABbe övgüler sunun! 2 Ey gönlüm, RABbe övgüler sun.'),
(1999712,68,19,146,2,'Yaşadıkça RABbe övgüler sunacak, 2 Var oldukça Tanrıma ilahiler söyleyeceğim.'),
(1999713,68,19,146,3,'Önderlere, 2 Sizi kurtaramayacak insanlara güvenmeyin.'),
(1999714,68,19,146,4,'O son soluğunu verince toprağa döner, 2 O gün tasarıları da biter.'),
(1999715,68,19,146,5,'Ne mutlu yardımcısı Yakupun Tanrısı olan insana, 2 Umudu Tanrısı RABde olana!'),
(1999716,68,19,146,6,'Yeri göğü, 2 Denizi ve içindeki her şeyi yaratan, 2 Sonsuza dek sadık kalan,'),
(1999717,68,19,146,7,'Ezilenlerin hakkını alan, 2 Açlara yiyecek sağlayan Odur. RAB tutsakları özgür kılar,'),
(1999718,68,19,146,8,'Körlerin gözünü açar, 2 İki büklüm olanları doğrultur, 2 Doğruları sever.'),
(1999719,68,19,146,9,'RAB garipleri korur, 2 Öksüze, dul kadına yardım eder, 2 Kötülerin yolunuysa saptırır.'),
(1999720,68,19,146,10,'RAB Tanrın sonsuza dek, ey Siyon, 2 Kuşaklar boyunca egemenlik sürecek. RAB''be övgüler sunun!'),
(1999721,68,19,147,1,'RABbe övgüler sunun! 2 Ne güzel, ne hoş Tanrımızı ilahilerle övmek! 2 Ona övgü yaraşır.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999722,68,19,147,2,'RAB yeniden kuruyor Yeruşalimi, 2 Bir araya topluyor İsrailin sürgünlerini.'),
(1999723,68,19,147,3,'O kırık kalplileri iyileştirir, 2 Yaralarını sarar.'),
(1999724,68,19,147,4,'Yıldızların sayısını belirler, 2 Her birini adıyla çağırır.'),
(1999725,68,19,147,5,'Rabbimiz büyük ve çok güçlüdür, 2 Sınırsızdır anlayışı.'),
(1999726,68,19,147,6,'RAB mazlumlara yardım eder, 2 Kötüleri yere çalar.'),
(1999727,68,19,147,7,'RABbe şükran ezgileri okuyun, 2 Tanrımızı lirle, ilahilerle övün.'),
(1999728,68,19,147,8,'Odur gökleri bulutlarla kaplayan, 2 Yeryüzüne yağmur sağlayan, 2 Dağlarda ot bitiren.'),
(1999729,68,19,147,9,'O yiyecek sağlar hayvanlara, 2 Bağrışan kuzgun yavrularına.'),
(1999730,68,19,147,10,'Ne atın gücünden zevk alır, 2 Ne de insanın yiğitliğinden hoşlanır.'),
(1999731,68,19,147,11,'RAB kendisinden korkanlardan, 2 Sevgisine umut bağlayanlardan hoşlanır.'),
(1999732,68,19,147,12,'RABbi yücelt, ey Yeruşalim! 2 Tanrına övgüler sun, ey Siyon!'),
(1999733,68,19,147,13,'Çünkü senin kapılarının kol demirlerine güç katar, 2 İçindeki halkı kutsar.'),
(1999734,68,19,147,14,'Sınırlarını esenlik içinde tutar, 2 Seni en iyi buğdayla doyurur.'),
(1999735,68,19,147,15,'Yeryüzüne buyruğunu gönderir, 2 Sözü çarçabuk yayılır.'),
(1999736,68,19,147,16,'Yapağı gibi kar yağdırır, 2 Kırağıyı kül gibi saçar.'),
(1999737,68,19,147,17,'Aşağıya iri iri dolu savurur, 2 Kim dayanabilir soğuğuna?'),
(1999738,68,19,147,18,'Buyruk verir, eritir buzları, 2 Rüzgarını estirir, sular akmaya başlar.'),
(1999739,68,19,147,19,'Sözünü Yakup soyuna, 2 Kurallarını, ilkelerini İsraile bildirir.'),
(1999740,68,19,147,20,'Başka hiçbir ulus için yapmadı bunu, 2 Onlar O''nun ilkelerini bilmezler. RAB''be övgüler sunun!'),
(1999741,68,19,148,1,'RABbe övgüler sunun! 2 Göklerden RABbe övgüler sunun, 2 Yücelerde Ona övgüler sunun!'),
(1999742,68,19,148,2,'Ey bütün melekleri, Ona övgüler sunun, 2 Övgüler sunun Ona, ey bütün göksel orduları!'),
(1999743,68,19,148,3,'Ey güneş, ay, Ona övgüler sunun, 2 Övgüler sunun Ona, ey ışıldayan bütün yıldızlar!'),
(1999744,68,19,148,4,'Ey göklerin gökleri 2 Ve göklerin üstündeki sular, 2 Ona övgüler sunun!'),
(1999745,68,19,148,5,'RABbin adına övgüler sunsunlar, 2 Çünkü O buyruk verince, var oldular;'),
(1999746,68,19,148,6,'Bozulmayacak bir kural koyarak, 2 Onları sonsuza dek yerlerine oturttu.'),
(1999747,68,19,148,7,'Yeryüzünden RABbe övgüler sunun, 2 Ey deniz canavarları, bütün enginler,'),
(1999748,68,19,148,8,'Şimşek, dolu, kar, bulutlar, 2 Onun buyruğuna uyan fırtınalar,'),
(1999749,68,19,148,9,'Dağlar, bütün tepeler, 2 Meyve ağaçları, sedir ağaçları,'),
(1999750,68,19,148,10,'Yabanıl ve evcil hayvanlar, 2 Sürüngenler, uçan kuşlar,'),
(1999751,68,19,148,11,'Yeryüzünün kralları, bütün halklar, 2 Önderler, yeryüzünün bütün yöneticileri,'),
(1999752,68,19,148,12,'Delikanlılar, genç kızlar, 2 Yaşlılar, çocuklar!'),
(1999753,68,19,148,13,'RABbin adına övgüler sunsunlar, 2 Çünkü yalnız Onun adı yücedir. 2 Onun yüceliği yerin göğün üstündedir.'),
(1999754,68,19,148,14,'RAB kendi halkını güçlü kıldı, 2 Bütün sadık kullarına, 2 Kendisine yakın olan halka, 2 İsrailliler''e ün kazandırdı. RAB''be övgüler sunun!'),
(1999755,68,19,149,1,'RABbe övgüler sunun! 2 RABbe yeni bir ezgi söyleyin, 2 Sadık kullarının toplantısında 2 Onu ezgilerle övün!'),
(1999756,68,19,149,2,'İsrail Yaratıcısında sevinç bulsun, 2 Siyon halkı Krallarıyla coşsun!'),
(1999757,68,19,149,3,'Dans ederek övgüler sunsunlar Onun adına, 2 Tef ve lir çalarak Onu ilahilerle övsünler!'),
(1999758,68,19,149,4,'Çünkü RAB halkından hoşlanır, 2 Alçakgönüllüleri zafer tacıyla süsler.'),
(1999759,68,19,149,5,'Bu onurla mutlu olsun sadık kulları, 2 Sevinç ezgileri okusunlar yataklarında!'),
(1999760,68,19,149,6,'Ağızlarında Tanrıya yüce övgüler, 2 Ellerinde iki ağızlı kılıçla'),
(1999761,68,19,149,7,'Uluslardan öç alsınlar, 2 Halkları cezalandırsınlar,'),
(1999762,68,19,149,8,'Krallarını zincire, 2 Soylularını prangaya vursunlar!'),
(1999763,68,19,149,9,'Yazılan kararı onlara uygulasınlar! 2 Bütün sadık kulları için onurdur bu. RAB''be övgüler sunun!'),
(1999764,68,19,150,1,'RABbe övgüler sunun! Kutsal yerde Tanrıya övgüler sunun! 2 Gücünü gösteren göklerde övgüler sunun Ona!'),
(1999765,68,19,150,2,'Övgüler sunun Ona güçlü işleri için! 2 Övgüler sunun Ona eşsiz büyüklüğüne yaraşır biçimde!'),
(1999766,68,19,150,3,'Boru çalarak Ona övgüler sunun! 2 Çenkle ve lirle Ona övgüler sunun!'),
(1999767,68,19,150,4,'Tef ve dansla Ona övgüler sunun! 2 Saz ve neyle Ona övgüler sunun!'),
(1999768,68,19,150,5,'Zillerle Ona övgüler sunun! 2 Çınlayan zillerle Ona övgüler sunun!'),
(1999769,68,19,150,6,'Bütün canlı varlıklar RAB''be övgüler sunsun! RAB''be övgüler sunun!'),
(1999770,68,20,1,1,'Davut oğlu İsrail Kralı Süleymanın özdeyişleri:'),
(1999771,68,20,1,2,'Bu özdeyişler, bilgeliğe ve terbiyeye ulaşmak, 2 Akıllıca sözleri anlamak,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999772,68,20,1,3,'Başarıya götüren terbiyeyi edinip 2 Doğru, haklı ve adil olanı yapmak,'),
(1999773,68,20,1,4,'Saf kişiyi ihtiyatlı, 2 Genç adamı bilgili ve sağgörülü kılmak içindir.'),
(1999774,68,20,1,5,'Özdeyişlerle benzetmeleri, 2 Bilgelerin sözleriyle bilmecelerini anlamak için 2 Bilge kişi dinlesin ve kavrayışını artırsın, 2 Akıllı kişi yaşam hüneri kazansın.'),
(1999775,68,20,1,7,'RAB korkusudur bilginin temeli. 2 Ahmaklarsa bilgeliği ve terbiyeyi küçümser.'),
(1999776,68,20,1,8,'Oğlum, babanın uyarılarına kulak ver, 2 Annenin öğrettiklerinden ayrılma.'),
(1999777,68,20,1,9,'Çünkü bunlar başın için sevimli bir çelenk, 2 Boynun için gerdanlık olacaktır.'),
(1999778,68,20,1,10,'Oğlum, seni ayartmaya çalışan günahkârlara teslim olma.'),
(1999779,68,20,1,11,'Şöyle diyebilirler: 2 ‹‹Bizimle gel, 2 Adam öldürmek için pusuya yatalım, 2 Zevk uğruna masum kişileri tuzağa düşürelim.'),
(1999780,68,20,1,12,'Onları ölüler diyarı gibi diri diri, 2 Ölüm çukuruna inenler gibi 2 Bütünüyle yutalım.'),
(1999781,68,20,1,13,'Bir sürü değerli mal ele geçirir, 2 Evlerimizi ganimetle doldururuz.'),
(1999782,68,20,1,14,'Gel, sen de bize katıl, 2 Tek bir kesemiz olacak.››'),
(1999783,68,20,1,15,'Oğlum, böyleleriyle gitme, 2 Onların tuttuğu yoldan uzak dur.'),
(1999784,68,20,1,16,'Çünkü ayakları kötülüğe koşar, 2 Çekinmeden kan dökerler.'),
(1999785,68,20,1,17,'Kuşların gözü önünde ağ sermek boşunadır.'),
(1999786,68,20,1,18,'Başkasına pusu kuran kendi kurduğu pusuya düşer. 2 Yalnız kendi canıdır tuzağa düşürdüğü.'),
(1999787,68,20,1,19,'Haksız kazanca düşkün olanların sonu böyledir. 2 Bu düşkünlük onları canlarından eder.'),
(1999788,68,20,1,20,'Bilgelik dışarıda yüksek sesle haykırıyor, 2 Meydanlarda sesleniyor.'),
(1999789,68,20,1,21,'Kalabalık sokak başlarında bağırıyor, 2 Kentin giriş kapılarında sözlerini duyuruyor:'),
(1999790,68,20,1,22,'‹‹Ey budalalar, budalalığı ne zamana dek seveceksiniz? 2 Alaycılar ne zamana dek alay etmekten zevk alacak? 2 Akılsızlar ne zamana dek bilgiden nefret edecek?'),
(1999791,68,20,1,23,'Uyardığımda yola gelin, o zaman size yüreğimi açar, 2 Sözlerimi anlamanıza yardım ederim.'),
(1999792,68,20,1,24,'Ama sizi çağırdığım zaman beni reddettiniz. 2 Elimi uzattım, umursayan olmadı.'),
(1999793,68,20,1,25,'Duymazlıktan geldiniz bütün öğütlerimi, 2 Uyarılarımı duymak istemediniz.'),
(1999794,68,20,1,26,'Bu yüzden ben de felaketinize sevineceğim. 2 Belaya uğradığınızda, 2 Bela üzerinize bir fırtına gibi geldiğinde, 2 Bir kasırga gibi geldiğinde felaketiniz, 2 Sıkıntıya, kaygıya düştüğünüzde, 2 Sizinle alay edeceğim.'),
(1999795,68,20,1,28,'O zaman beni çağıracaksınız, 2 Ama yanıtlamayacağım. 2 Var gücünüzle arayacaksınız beni, 2 Ama bulamayacaksınız.'),
(1999796,68,20,1,29,'Çünkü bilgiden nefret ettiniz. 2 RABden korkmayı reddettiniz.'),
(1999797,68,20,1,30,'Öğütlerimi istemediniz, 2 Uyarılarımın tümünü küçümsediniz.'),
(1999798,68,20,1,31,'Bu nedenle tuttuğunuz yolun meyvesini yiyeceksiniz, 2 Kendi düzenbazlığınıza doyacaksınız.'),
(1999799,68,20,1,32,'Bön adamlar dönekliklerinin kurbanı olacak. 2 Akılsızlar kaygısızlıklarının içinde yok olup gidecek.'),
(1999800,68,20,1,33,'Ama beni dinleyen güvenlik içinde yaşayacak, 2 Kötülükten korkmayacak, huzur bulacak.››'),
(1999801,68,20,2,1,'Oğlum, bilgeliğe kulak verip 2 Yürekten akla yönelerek 2 Sözlerimi kabul eder, 2 Buyruklarımı aklında tutarsan,'),
(1999802,68,20,2,3,'Evet, aklı çağırır, 2 Ona gönülden seslenirsen,'),
(1999803,68,20,2,4,'Gümüş ararcasına onu ararsan, 2 Onu ararsan define arar gibi,'),
(1999804,68,20,2,5,'RAB korkusunu anlar 2 Ve Tanrıyı yakından tanırsın.'),
(1999805,68,20,2,6,'Çünkü bilgeliğin kaynağı RABdir. 2 Onun ağzından bilgi ve anlayış çıkar.'),
(1999806,68,20,2,7,'Doğru kişileri başarıya ulaştırır, 2 Kalkanıdır dürüst yaşayanların.'),
(1999807,68,20,2,8,'Adil olanların adımlarını korur, 2 Sadık kullarının yolunu gözetir.'),
(1999808,68,20,2,9,'O zaman anlarsın her iyi yolu, 2 Neyin doğru, haklı ve adil olduğunu.'),
(1999809,68,20,2,10,'Çünkü yüreğin bilgelikle dolacak, 2 Zevk alacaksın bilgiden.'),
(1999810,68,20,2,11,'Sağgörü sana bekçilik edecek 2 Ve akıl seni koruyacak.'),
(1999811,68,20,2,12,'Bunlar seni kötü yoldan, 2 Ahlaksızın sözlerinden kurtaracak.'),
(1999812,68,20,2,13,'Onlar ki karanlık yollarda yürümek için 2 Doğru yoldan ayrılırlar.'),
(1999813,68,20,2,14,'Kötülük yapmaktan hoşlanır, 2 Zevk alırlar kötülüğün aşırısından.'),
(1999814,68,20,2,15,'Yolları dolambaçlı, 2 Yaşayışları çarpıktır.'),
(1999815,68,20,2,16,'Bilgelik, gençken evlendiği eşini terk eden, 2 Tanrının önünde içtiği andı unutan ahlaksız kadından, 2 Sözleriyle yaltaklanan 2 Vefasız kadından seni kurtaracak.'),
(1999816,68,20,2,18,'O kadının evi insanı ölüme, 2 Yolları ölülere götürür.'),
(1999817,68,20,2,19,'Ona gidenlerden hiçbiri geri dönmez, 2 Yaşam yollarına erişmez.'),
(1999818,68,20,2,20,'Bu nedenle sen iyilerin yolunda yürü, 2 Doğruların izinden git.'),
(1999819,68,20,2,21,'Çünkü ülkede yaşayacak olan doğrulardır, 2 Dürüst kişilerdir orada kalacak olan.'),
(1999820,68,20,2,22,'Kötüler ülkeden sürülecek, 2 Hainler sökülüp atılacak.'),
(1999821,68,20,3,1,'Oğlum, unutma öğrettiklerimi, 2 Aklında tut buyruklarımı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999822,68,20,3,2,'Çünkü bunlar ömrünü uzatacak, 2 Yaşam yıllarını, esenliğini artıracaktır.'),
(1999823,68,20,3,3,'Sevgiyi, sadakati hiç yanından ayırma, 2 Bağla onları boynuna, 2 Yaz yüreğinin levhasına.'),
(1999824,68,20,3,4,'Böylece Tanrının ve insanların gözünde 2 Beğeni ve saygınlık kazanacaksın.'),
(1999825,68,20,3,5,'RABbe güven bütün yüreğinle, 2 Kendi aklına bel bağlama.'),
(1999826,68,20,3,6,'Yaptığın her işte RABbi an, 2 O senin yolunu düze çıkarır.'),
(1999827,68,20,3,7,'Kendini bilge biri olarak görme, 2 RABden kork, kötülükten uzak dur.'),
(1999828,68,20,3,8,'Böylece bedenin sağlık 2 Ve ferahlık bulur.'),
(1999829,68,20,3,9,'Servetinle ve ürününün turfandasıyla 2 RABbi onurlandır.'),
(1999830,68,20,3,10,'O zaman ambarların tıka basa dolar, 2 Teknelerin yeni şarapla dolup taşar.'),
(1999831,68,20,3,11,'Oğlum, RABbin terbiye edişini hafife alma, 2 Onun azarlamasından usanma.'),
(1999832,68,20,3,12,'Çünkü RAB, oğlundan hoşnut bir baba gibi, 2 Sevdiğini azarlar.'),
(1999833,68,20,3,13,'Bilgeliğe erişene, 2 Aklı bulana ne mutlu!'),
(1999834,68,20,3,14,'Gümüş kazanmaktansa onu kazanmak daha iyidir. 2 Onun yararı altından daha çoktur.'),
(1999835,68,20,3,15,'Daha değerlidir mücevherden, 2 Dileyeceğin hiçbir şey onunla kıyaslanamaz.'),
(1999836,68,20,3,16,'Sağ elinde uzun ömür, 2 Sol elinde zenginlik ve onur vardır.'),
(1999837,68,20,3,17,'Yolları sevinç yollarıdır, 2 Evet, bütün yolları esenliğe çıkarır.'),
(1999838,68,20,3,18,'Bilgelik yaşam ağacıdır ona sarılanlara, 2 Ne mutlu ona sımsıkı tutunanlara!'),
(1999839,68,20,3,19,'RAB dünyanın temelini bilgelikle attı, 2 Gökleri akıllıca yerleştirdi.'),
(1999840,68,20,3,20,'Bilgisiyle enginler yarıldı, 2 Bulutlar suyunu verdi.'),
(1999841,68,20,3,21,'Oğlum, sağlam öğüde, sağgörüye tutun. 2 Sakın gözünü ayırma onlardan.'),
(1999842,68,20,3,22,'Onlar sana yaşam verecek 2 Ve boynuna güzel bir süs olacak.'),
(1999843,68,20,3,23,'O zaman güvenlik içinde yol alırsın, 2 Sendelemeden.'),
(1999844,68,20,3,24,'Korkusuzca yatar, 2 Tatlı tatlı uyursun.'),
(1999845,68,20,3,25,'Beklenmedik felaketten, 2 Ya da kötülerin uğradığı yıkımdan korkma.'),
(1999846,68,20,3,26,'Çünkü senin güvencen RABdir, 2 Tuzağa düşmekten seni O koruyacaktır.'),
(1999847,68,20,3,27,'Elinden geldikçe, 2 İyiliğe hakkı olanlardan iyiliği esirgeme.'),
(1999848,68,20,3,28,'Elinde varken komşuna, 2 ‹‹Bugün git, yarın gel, o zaman veririm›› deme.'),
(1999849,68,20,3,29,'Sana güvenerek yanında yaşayan komşuna 2 Kötülük tasarlama.'),
(1999850,68,20,3,30,'Sana kötülük etmemiş biriyle 2 Yok yere çekişme.'),
(1999851,68,20,3,31,'Zorba kişiye imrenme, 2 Onun yollarından hiçbirini seçme.'),
(1999852,68,20,3,32,'Çünkü RAB sapkınlardan tiksinir, 2 Ama doğruların candan dostudur.'),
(1999853,68,20,3,33,'RAB kötülerin evini lanetler, 2 Doğruların oturduğu yeriyse kutsar.'),
(1999854,68,20,3,34,'RAB alaycılarla alay eder, 2 Ama alçakgönüllülere lütfeder.'),
(1999855,68,20,3,35,'Bilge kişiler onuru miras alacak, 2 Akılsızlara yalnız utanç kalacak.'),
(1999856,68,20,4,1,'Çocuklarım, babanızın uyarılarına kulak verin. 2 Dikkat edin ki anlayışlı olasınız.'),
(1999857,68,20,4,2,'Çünkü size iyi ders veriyorum, 2 Ayrılmayın öğrettiğimden.'),
(1999858,68,20,4,3,'Ben bir çocukken babamın evinde, 2 Annemin körpecik tek yavrusuyken,'),
(1999859,68,20,4,4,'Babam bana şunu öğretti: 2 ‹‹Söylediklerime yürekten sarıl, 2 Buyruklarımı yerine getir ki yaşayasın.'),
(1999860,68,20,4,5,'Bilgeliği ve aklı sahiplen, 2 Söylediklerimi unutma, onlardan sapma.'),
(1999861,68,20,4,6,'Bilgelikten ayrılma, o seni korur. 2 Sev onu, seni gözetir.'),
(1999862,68,20,4,7,'Bilgeliğe ilk adım onu sahiplenmektir. 2 Bütün servetine mal olsa da akla sahip çık.'),
(1999863,68,20,4,8,'Onu el üstünde tut, o da seni yüceltecek, 2 Ona sarılırsan seni onurlandıracak.'),
(1999864,68,20,4,9,'Başına zarif bir çelenk, 2 Görkemli bir taç giydirecektir.››'),
(1999865,68,20,4,10,'Dinle oğlum, sözlerimi benimse ki, 2 Uzasın ömrün.'),
(1999866,68,20,4,11,'Seni bilgelik yolunda eğitir, 2 Doğru yollara yöneltirim.'),
(1999867,68,20,4,12,'Ayakların takılmadan yürür, 2 Sürçmeden koşarsın.'),
(1999868,68,20,4,13,'Aldığın terbiyeye sarıl, bırakma, 2 Onu uygula, çünkü odur yaşamın.'),
(1999869,68,20,4,14,'Kötülerin yoluna ayak basma, 2 Yürüme alçakların yolunda,'),
(1999870,68,20,4,15,'O yoldan sakın, yakınından bile geçme, 2 Yönünü değiştirip geç.'),
(1999871,68,20,4,16,'Çünkü kötülük etmedikçe uyuyamaz onlar, 2 Uykuları kaçar saptırmadıkça birilerini.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999872,68,20,4,17,'Yedikleri ekmek kötülük, 2 İçtikleri şarap zorbalık ürünüdür.'),
(1999873,68,20,4,18,'Oysa doğruların yolu şafak ışığı gibidir, 2 Giderek öğle güneşinin parlaklığına erişir.'),
(1999874,68,20,4,19,'Kötülerin yoluysa zifiri karanlık gibidir, 2 Neden tökezlediklerini bilmezler.'),
(1999875,68,20,4,20,'Oğlum, sözlerime dikkat et, 2 Dediklerime kulak ver.'),
(1999876,68,20,4,21,'Aklından çıkmasın bunlar, 2 Onları yüreğinde sakla.'),
(1999877,68,20,4,22,'Çünkü onları bulan için yaşam, 2 Bedeni için şifadır bunlar.'),
(1999878,68,20,4,23,'Her şeyden önce de yüreğini koru, 2 Çünkü yaşam ondan kaynaklanır.'),
(1999879,68,20,4,24,'Yalan çıkmasın ağzından, 2 Uzak tut dudaklarını sapık sözlerden.'),
(1999880,68,20,4,25,'Gözlerin hep ileriye baksın, 2 Dosdoğru önüne!'),
(1999881,68,20,4,26,'Gideceğin yolu düzle, 2 O zaman bütün işlerin sağlam olur.'),
(1999882,68,20,4,27,'Sapma sağa sola, 2 Ayağını kötülükten uzak tut.'),
(1999883,68,20,5,1,'Oğlum, bilgeliğime dikkat et, 2 Akıllıca sözlerime kulak ver.'),
(1999884,68,20,5,2,'Böylelikle her zaman sağgörülü olur, 2 Dudaklarınla bilgiyi korursun.'),
(1999885,68,20,5,3,'Zina eden kadının bal damlar dudaklarından, 2 Ağzı daha yumuşaktır zeytinyağından.'),
(1999886,68,20,5,4,'Ama sonu pelinotu kadar acı, 2 İki ağızlı kılıç kadar keskindir.'),
(1999887,68,20,5,5,'Ayakları ölüme gider, 2 Adımları ölüler diyarına ulaşır.'),
(1999888,68,20,5,6,'Yaşama giden yolu hiç düşünmez, 2 Yolları dolaşıktır, ama farkında değil.'),
(1999889,68,20,5,7,'Oğlum, şimdi beni dinle, 2 Ağzımdan çıkan sözlerden ayrılma.'),
(1999890,68,20,5,8,'Öyle kadınlardan uzak dur, 2 Yaklaşma evinin kapısına.'),
(1999891,68,20,5,9,'Yoksa onurunu başkalarına, 2 Yıllarını bir gaddara kaptırırsın.'),
(1999892,68,20,5,10,'Varını yoğunu yer bitirir yabancılar, 2 Emeğin başka birinin evini bayındır kılar.'),
(1999893,68,20,5,11,'Ah çekip inlersin ömrünün son günlerinde, 2 Etinle bedenin tükendiğinde.'),
(1999894,68,20,5,12,'‹‹Eğitilmekten neden bu kadar nefret ettim, 2 Yüreğim uyarıları neden önemsemedi?›› dersin.'),
(1999895,68,20,5,13,'‹‹Öğretmenlerimin sözünü dinlemedim, 2 Beni eğitenlere kulak vermedim.'),
(1999896,68,20,5,14,'Halkın ve topluluğun arasında 2 Tam bir yıkımın eşiğine gelmişim.››'),
(1999897,68,20,5,15,'Suyu kendi sarnıcından, 2 Kendi kuyunun kaynağından iç.'),
(1999898,68,20,5,16,'Pınarların sokakları, 2 Akarsuların meydanları mı sulamalı?'),
(1999899,68,20,5,17,'Yalnız senin olsun onlar, 2 Paylaşma yabancılarla.'),
(1999900,68,20,5,18,'Çeşmen bereketli olsun 2 Ve gençken evlendiğin karınla mutlu ol.'),
(1999901,68,20,5,19,'Sevimli bir geyik, zarif bir ceylan gibi, 2 Hep seni doyursun memeleri. 2 Aşkıyla sürekli coş.'),
(1999902,68,20,5,20,'Oğlum, neden ahlaksız bir kadınla coşasın, 2 Neden başka birinin karısını koynuna alasın?'),
(1999903,68,20,5,21,'RAB insanın tuttuğu yolu gözler, 2 Attığı her adımı denetler.'),
(1999904,68,20,5,22,'Kötü kişiyi kendi suçları ele verecek, 2 Günahının kemendi kıskıvrak bağlayacak onu.'),
(1999905,68,20,5,23,'Aşırı ahmaklığı onu yoldan çıkaracak, 2 Terbiyeyi umursamadığı için ölecek.'),
(1999906,68,20,6,1,'Oğlum, eğer birine kefil oldunsa, 2 Onun borcunu yüklendinse,'),
(1999907,68,20,6,2,'Düştünse tuzağa kendi sözlerinle, 2 Ağzının sözleriyle yakalandınsa,'),
(1999908,68,20,6,3,'O kişinin eline düştün demektir. 2 Oğlum, şunu yap ve kendini kurtar: 2 Git, yere kapan onun önünde, 2 Ona yalvar yakar.'),
(1999909,68,20,6,4,'Gözlerine uyku girmesin, 2 Ağırlaşmasın göz kapakların.'),
(1999910,68,20,6,5,'Avcının elinden ceylan gibi, 2 Kuşbazın elinden kuş gibi kurtar kendini.'),
(1999911,68,20,6,6,'Ey tembel kişi, git, karıncalara bak, 2 Onların yaşamından bilgelik öğren.'),
(1999912,68,20,6,7,'Başkanları, önderleri ya da yöneticileri olmadığı halde,'),
(1999913,68,20,6,8,'Yazın erzaklarını biriktirirler, 2 Yiyeceklerini toplarlar biçim mevsiminde.'),
(1999914,68,20,6,9,'Ne zamana dek yatacaksın, ey tembel kişi? 2 Ne zaman kalkacaksın uykundan?'),
(1999915,68,20,6,10,'‹‹Biraz kestireyim, biraz uyuklayayım, 2 Ellerimi kavuşturup şöyle bir uyuyayım›› demeye kalmadan,'),
(1999916,68,20,6,11,'Yokluk bir haydut gibi, 2 Yoksulluk bir akıncı gibi gelir üzerine.'),
(1999917,68,20,6,12,'Ağzında yalanla dolaşan kişi, 2 Soysuz ve fesatçıdır.'),
(1999918,68,20,6,13,'Göz kırpar, bir sürü ayak oyunu, 2 El kol hareketleri yapar,'),
(1999919,68,20,6,14,'Ahlaksız yüreğinde kötülük tasarlar, 2 Çekişmeler yaratır durmadan.'),
(1999920,68,20,6,15,'Bu yüzden ansızın yıkıma uğrayacak, 2 Birdenbire çaresizce yok olacak.'),
(1999921,68,20,6,16,'RABbin nefret ettiği altı şey, 2 İğrendiği yedi şey vardır:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999922,68,20,6,17,'Gururlu gözler, 2 Yalancı dil, 2 Suçsuz kanı döken eller,'),
(1999923,68,20,6,18,'Düzenbaz yürek, 2 Kötülüğe seğirten ayaklar,'),
(1999924,68,20,6,19,'Yalan soluyan yalancı tanık 2 Ve kardeşler arasında çekişme yaratan kişi.'),
(1999925,68,20,6,20,'Oğlum, babanın buyruklarına uy, 2 Annenin öğrettiklerinden ayrılma.'),
(1999926,68,20,6,21,'Bunlar sürekli yüreğinin bağı olsun, 2 Tak onları boynuna.'),
(1999927,68,20,6,22,'Yolunda sana rehber olacak, 2 Seni koruyacaklar yattığın zaman; 2 Söyleşecekler seninle uyandığında.'),
(1999928,68,20,6,23,'Bu buyruklar sana çıra, 2 Öğretilenler ışıktır. 2 Eğitici uyarılar yaşam yolunu gösterir.'),
(1999929,68,20,6,24,'Seni kötü kadından, 2 Başka birinin karısının yaltaklanan dilinden 2 Koruyacak olan bunlardır.'),
(1999930,68,20,6,25,'Böyle kadınların güzelliği seni ayartmasın, 2 Bakışları seni tutsak etmesin.'),
(1999931,68,20,6,26,'Çünkü fahişe yüzünden insan bir lokma ekmeğe muhtaç kalır, 2 Başkasının karısıyla yatmak da kişinin canına mal olur. kalır›› ya da ‹‹Çünkü fahişenin ücreti ancak bir somun ekmektir››.'),
(1999932,68,20,6,27,'İnsan koynuna ateş alır da, 2 Giysisi yanmaz mı?'),
(1999933,68,20,6,28,'Korlar üzerinde yürür de, 2 Ayakları kavrulmaz mı?'),
(1999934,68,20,6,29,'Başkasının karısıyla yatan adamın durumu budur. 2 Böyle bir ilişkiye giren cezasız kalmaz.'),
(1999935,68,20,6,30,'Aç hırsız karnını doyurmak için çalıyorsa, 2 Kimse onu hor görmez.'),
(1999936,68,20,6,31,'Ama yakalanırsa, çaldığının yedi katını ödemek zorunda; 2 Varını yoğunu vermek anlamına gelse bile.'),
(1999937,68,20,6,32,'Zina eden adam sağduyudan yoksundur. 2 Yaptıklarıyla kendini yok eder.'),
(1999938,68,20,6,33,'Payına düşen dayak ve onursuzluktur, 2 Asla kurtulamaz utançtan.'),
(1999939,68,20,6,34,'Çünkü kıskançlık kocanın öfkesini azdırır, 2 Öç alırken acımasız olur.'),
(1999940,68,20,6,35,'Hiçbir fidye kabul etmez, 2 Gönlünü alamazsın armağanların çokluğuyla.'),
(1999941,68,20,7,1,'Oğlum, sözlerimi yerine getir, 2 Aklında tut buyruklarımı.'),
(1999942,68,20,7,2,'Buyruklarımı yerine getir ki, yaşayasın. 2 Öğrettiklerimi gözünün bebeği gibi koru.'),
(1999943,68,20,7,3,'Onları yüzük gibi parmaklarına geçir, 2 Yüreğinin levhasına yaz.'),
(1999944,68,20,7,4,'Bilgeliğe, ‹‹Sen kızkardeşimsin››, 2 Akla, ‹‹Akrabamsın›› de.'),
(1999945,68,20,7,5,'Zina eden kadından, 2 Yaltaklanan ahlaksız kadından seni koruyacak olan bunlardır.'),
(1999946,68,20,7,6,'Evimin penceresinden, 2 Kafesin ardından dışarıyı seyrederken,'),
(1999947,68,20,7,7,'Bir sürü toy gencin arasında, 2 Sağduyudan yoksun bir delikanlı çarptı gözüme.'),
(1999948,68,20,7,8,'Akşamüzeri, alaca karanlıkta, 2 Akşam karanlığı çökerken, 2 O kadının oturduğu sokağa saptığını, 2 Onun evine yöneldiğini gördüm.'),
(1999949,68,20,7,10,'Derken kadın onu karşıladı, 2 Fahişe kılığıyla sinsice.'),
(1999950,68,20,7,11,'Yaygaracı, dik başlı biriydi kadın. 2 Bir an bile durmaz evde.'),
(1999951,68,20,7,12,'Kâh sokakta, kâh meydanlardadır. 2 Sokak başlarında pusuya yatar.'),
(1999952,68,20,7,13,'Delikanlıyı tutup öptü, 2 Yüzü kızarmadan ona şöyle dedi:'),
(1999953,68,20,7,14,'‹‹Esenlik kurbanlarımı kesmek zorundaydım, 2 Adak sözümü bugün yerine getirdim.'),
(1999954,68,20,7,15,'Bunun için seni karşılamaya, seni aramaya çıktım, 2 İşte buldum seni!'),
(1999955,68,20,7,16,'Döşeğime Mısır ipliğinden dokunmuş 2 Renkli örtüler serdim.'),
(1999956,68,20,7,17,'Yatağıma mür, öd 2 Ve tarçın serptim.'),
(1999957,68,20,7,18,'Haydi gel, sabaha dek doya doya sevişelim, 2 Aşktan zevk alalım.'),
(1999958,68,20,7,19,'Kocam evde değil, 2 Uzun bir yolculuğa çıktı.'),
(1999959,68,20,7,20,'Yanına para torbasını aldı, 2 Dolunaydan önce eve dönmeyecek.››'),
(1999960,68,20,7,21,'Onu bir sürü çekici sözlerle baştan çıkardı, 2 Tatlı diliyle peşinden sürükledi.'),
(1999961,68,20,7,22,'Kesimevine götürülen öküz gibi 2 Hemen izledi onu delikanlı; 2 Tuzağa düşen geyik gibi,'),
(1999962,68,20,7,23,'Ciğerini bir ok delene kadar; 2 Kapana koşan bir kuş gibi, 2 Bunun yaşamına mal olacağını bilmeden.'),
(1999963,68,20,7,24,'Çocuklarım, şimdi dinleyin beni, 2 Kulak verin söylediklerime,'),
(1999964,68,20,7,25,'Sakın o kadına gönül vermeyin, 2 Onun yolundan gitmeyin.'),
(1999965,68,20,7,26,'Yere serdiği bir sürü kurbanı var, 2 Öldürdüğü kişilerin sayısı pek çok.'),
(1999966,68,20,7,27,'Ölüler diyarına giden yoldur onun evi, 2 Ölüm odalarına götürür.'),
(1999967,68,20,8,1,'Bilgelik çağırıyor, 2 Akıl sesini yükseltiyor.'),
(1999968,68,20,8,2,'Yol kenarındaki tepelerin başında, 2 Yolların birleştiği yerde duruyor o.'),
(1999969,68,20,8,3,'Kentin girişinde, kapıların yanında, 2 Sesini yükseltiyor:'),
(1999970,68,20,8,4,'‹‹Ey insanlar, size sesleniyorum, 2 Çağrım insan soyunadır!'),
(1999971,68,20,8,5,'Ey bön kişiler, ihtiyatlı olmayı öğrenin; 2 Sağduyulu olmayı öğrenin, ey akılsızlar!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1999972,68,20,8,6,'Söylediğim yetkin sözleri dinleyin, 2 Ağzımı doğruları söylemek için açarım.'),
(1999973,68,20,8,7,'Ağzım gerçeği duyurur, 2 Çünkü dudaklarım kötülükten iğrenir.'),
(1999974,68,20,8,8,'Ağzımdan çıkan her söz doğrudur, 2 Yoktur eğri ya da sapık olanı.'),
(1999975,68,20,8,9,'Apaçıktır hepsi anlayana, 2 Bilgiye erişen, doğruluğunu bilir onların.'),
(1999976,68,20,8,10,'Gümüş yerine terbiyeyi, 2 Saf altın yerine bilgiyi edinin.'),
(1999977,68,20,8,11,'Çünkü bilgelik mücevherden değerlidir, 2 Dilediğin hiçbir şey onunla kıyaslanamaz.'),
(1999978,68,20,8,12,'Ben bilgelik olarak ihtiyatı kendime konut edindim. 2 Bilgi ve sağgörü bendedir.'),
(1999979,68,20,8,13,'RABden korkmak kötülükten nefret etmek demektir. 2 Kibirden, küstahlıktan, 2 Kötü yoldan, sapık ağızdan nefret ederim.'),
(1999980,68,20,8,14,'Öğüt ve sağlam karar bana özgüdür. 2 Akıl ve güç kaynağı benim.'),
(1999981,68,20,8,15,'Krallar sayemde egemenlik sürer, 2 Hükümdarlar adil kurallar koyar.'),
(1999982,68,20,8,16,'Önderler, adaletle yöneten soylular 2 Sayemde yönetirler.'),
(1999983,68,20,8,17,'Beni sevenleri ben de severim, 2 Gayretle arayan beni bulur.'),
(1999984,68,20,8,18,'Zenginlik ve onur, 2 Kalıcı değerler ve bolluk bendedir.'),
(1999985,68,20,8,19,'Meyvem altından, saf altından, 2 Ürünüm seçme gümüşten daha iyidir.'),
(1999986,68,20,8,20,'Doğruluk yolunda, 2 Adaletin izinden yürürüm.'),
(1999987,68,20,8,21,'Böylelikle, beni sevenleri servet sahibi yapar, 2 Hazinelerini doldururum.'),
(1999988,68,20,8,22,'RAB yaratma işine başladığında 2 İlk beni yarattı,'),
(1999989,68,20,8,23,'Dünya var olmadan önce, 2 Ta başlangıçta, öncesizlikte yerimi aldım.'),
(1999990,68,20,8,24,'Enginler yokken, 2 Suları bol pınarlar yokken doğdum ben.'),
(1999991,68,20,8,25,'Dağlar daha oluşmadan, 2 Tepeler belirmeden, 2 RAB dünyayı, kırları 2 Ve dünyadaki toprağın zerresini yaratmadan doğdum.'),
(1999992,68,20,8,27,'RAB gökleri yerine koyduğunda oradaydım, 2 Engin denizleri ufukla çevirdiğinde,'),
(1999993,68,20,8,28,'Bulutları oluşturduğunda, 2 Denizin kaynaklarını güçlendirdiğinde,'),
(1999994,68,20,8,29,'Sular buyruğundan öte geçmesinler diye 2 Denize sınır çizdiğinde, 2 Dünyanın temellerini pekiştirdiğinde,'),
(1999995,68,20,8,30,'Baş mimar olarak Onun yanındaydım. 2 Gün be gün sevinçle dolup taştım, 2 Huzurunda hep coştum.'),
(1999996,68,20,8,31,'Onun dünyası mutluluğum, 2 İnsanları sevincimdi.'),
(1999997,68,20,8,32,'Çocuklarım, şimdi beni dinleyin: 2 Yolumu izleyenlere ne mutlu!'),
(1999998,68,20,8,33,'Uyarılarımı dinleyin ve bilge kişiler olun, 2 Görmezlikten gelmeyin onları.'),
(1999999,68,20,8,34,'Beni dinleyen, 2 Her gün kapımı gözleyen, 2 Kapımın eşiğinden ayrılmayan kişiye ne mutlu!'),
(2000000,68,20,8,35,'Çünkü beni bulan yaşam bulur 2 Ve RABbin beğenisini kazanır.'),
(2000001,68,20,8,36,'Beni gözardı edense kendine zarar verir, 2 Benden nefret eden, ölümü seviyor demektir.››'),
(2000002,68,20,9,1,'Bilgelik kendi evini yaptı, 2 Yedi direğini yonttu.'),
(2000003,68,20,9,2,'Hayvanlarını kesti, 2 Şarabını hazırlayıp sofrasını kurdu.'),
(2000004,68,20,9,3,'Kentin en yüksek noktalarına gönderdiği 2 Hizmetçileri aracılığıyla herkesi çağırıyor:'),
(2000005,68,20,9,4,'‹‹Kim safsa buraya gelsin›› diyor. 2 Sağduyudan yoksun olanlara da, 2 ‹‹Gelin, yiyeceklerimi yiyin, 2 Hazırladığım şaraptan için›› diyor.'),
(2000006,68,20,9,6,'‹‹Saflığı bırakın da yaşayın, 2 Aklın yolunu izleyin.'),
(2000007,68,20,9,7,'‹‹Alaycıyı paylayan aşağılanmayı hak eder, 2 Kötü kişiyi azarlayan hakarete uğrar.'),
(2000008,68,20,9,8,'Alaycıyı azarlama, yoksa senden nefret eder. 2 Bilge kişiyi azarlarsan, seni sever.'),
(2000009,68,20,9,9,'Bilge kişiyi eğitirsen 2 Daha bilge olur, 2 Doğru kişiye öğretirsen bilgisini artırır.'),
(2000010,68,20,9,10,'RAB korkusudur bilgeliğin temeli. 2 Akıl Kutsal Olanı tanımaktır.'),
(2000011,68,20,9,11,'Benim sayemde günlerin çoğalacak, 2 Ömrüne yıllar katılacak.'),
(2000012,68,20,9,12,'Bilgeysen, bilgeliğinin yararı sanadır, 2 Alaycı olursan acısını yalnız sen çekersin.››'),
(2000013,68,20,9,13,'Akılsız kadın yaygaracı 2 Ve saftır, hiçbir şey bilmez.'),
(2000014,68,20,9,14,'Evinin kapısında, 2 Kentin en yüksek yerinde bir iskemleye oturur; 2 Yoldan geçenleri, 2 Kendi yollarından gidenleri çağırmak için,'),
(2000015,68,20,9,16,'‹‹Kim safsa buraya gelsin›› der. 2 Sağduyudan yoksun olanlara da,'),
(2000016,68,20,9,17,'‹‹Çalıntı su tatlı, 2 Gizlice yenen yemek lezzetlidir›› der.'),
(2000017,68,20,9,18,'Ne var ki, evine girenler ölüme gittiklerini, 2 Ona konuk olanlar 2 Ölüler diyarının dibine indiklerini bilmezler.'),
(2000018,68,20,10,1,'Süleymanın özdeyişleri: 2 Bilge çocuk babasını sevindirir, 2 Akılsız çocuk annesini üzer.'),
(2000019,68,20,10,2,'Haksızca kazanılan servetin yararı yoktur, 2 Ama doğruluk ölümden kurtarır.'),
(2000020,68,20,10,3,'RAB doğru kişiyi aç komaz, 2 Ama kötülerin isteğini boşa çıkarır.'),
(2000021,68,20,10,4,'Tembel eller insanı yoksullaştırır, 2 Çalışkan el zengin eder.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000022,68,20,10,5,'Aklı başında evlat ürünü yazın toplar, 2 Hasatta uyuyansa ailesinin yüzkarasıdır.'),
(2000023,68,20,10,6,'Bereket doğru kişinin başına yağar, 2 Kötülerse zorbalıklarını sözle gizler.'),
(2000024,68,20,10,7,'Doğrular övgüyle, 2 Kötüler nefretle anılır.'),
(2000025,68,20,10,8,'Bilge kişi buyrukları kabul eder, 2 Çenesi düşük ahmaksa yıkıma uğrar.'),
(2000026,68,20,10,9,'Dürüst kişi güvenlik içinde yaşar, 2 Ama hileli yoldan giden açığa vurulacaktır.'),
(2000027,68,20,10,10,'Sinsice göz kırpan, acılara neden olur. 2 Çenesi düşük ahmak da yıkıma uğrar. (bkz.10:8), Septuaginta ‹‹Cesaretle azarlayan esenlik sağlar››.'),
(2000028,68,20,10,11,'Doğru kişinin ağzı yaşam pınarıdır, 2 Kötülerse zorbalıklarını sözle gizlerler.'),
(2000029,68,20,10,12,'Nefret çekişmeyi azdırır, 2 Sevgi her suçu bağışlar.'),
(2000030,68,20,10,13,'Akıllı kişinin dudaklarından bilgelik akar, 2 Ama sağduyudan yoksun olan sırtına kötek yer.'),
(2000031,68,20,10,14,'Bilge kişi bilgi biriktirir, 2 Ahmağın ağzıysa onu yıkıma yaklaştırır.'),
(2000032,68,20,10,15,'Zenginin serveti onun kalesidir, 2 Fakirin yoksulluğu ise onu yıkıma götürür.'),
(2000033,68,20,10,16,'Doğru kişinin ücreti yaşamdır, 2 Kötünün geliriyse kendisine cezadır.'),
(2000034,68,20,10,17,'Terbiyeye kulak veren yaşam yolunu bulur. 2 Uyarıları reddedense başkalarını yoldan saptırır.'),
(2000035,68,20,10,18,'Nefretini gizleyen kişinin dudakları yalancıdır. 2 İftira yayan akılsızdır.'),
(2000036,68,20,10,19,'Çok konuşanın günahı eksik olmaz, 2 Sağduyulu kişiyse dilini tutar.'),
(2000037,68,20,10,20,'Doğru kişinin dili saf gümüş gibidir, 2 Kötünün niyetleriyse değersizdir.'),
(2000038,68,20,10,21,'Doğru kişinin sözleri birçoklarını besler, 2 Ahmaklarsa sağduyu yoksunluğundan ölür.'),
(2000039,68,20,10,22,'RABbin bereketidir kişiyi zengin eden, 2 RAB buna dert katmaz.'),
(2000040,68,20,10,23,'Kötülük akılsızlar için eğlence gibidir. 2 Aklı başında olanlar içinse bilgelik aynı şeydir.'),
(2000041,68,20,10,24,'Kötü kişinin korktuğu başına gelir, 2 Doğru kişiyse dileğine erişir.'),
(2000042,68,20,10,25,'Kasırga gelince kötü kişiyi silip götürür; 2 Ama doğru kişi sonsuza dek ayakta kalır.'),
(2000043,68,20,10,26,'Dişler için sirke, 2 Gözler için duman neyse, 2 Tembel ulak da kendisini gönderen için öyledir.'),
(2000044,68,20,10,27,'RAB korkusu ömrü uzatır, 2 Kötülerin yıllarıysa kısadır.'),
(2000045,68,20,10,28,'Doğrunun umudu onu sevindirir, 2 Kötünün beklentileriyse boşa çıkar.'),
(2000046,68,20,10,29,'RABbin yolu dürüst için sığınak, 2 Fesatçı içinse yıkımdır.'),
(2000047,68,20,10,30,'Doğru kişi hiçbir zaman sarsılmaz, 2 Ama kötüler ülkede kalamaz.'),
(2000048,68,20,10,31,'Doğru kişinin ağzı bilgelik üretir, 2 Sapık dilse kesilir.'),
(2000049,68,20,10,32,'Doğru kişinin dudakları söylenecek sözü bilir, 2 Kötünün ağzındansa sapık sözler çıkar.'),
(2000050,68,20,11,1,'RAB hileli teraziden iğrenir, 2 Hilesiz tartıdansa hoşnut kalır.'),
(2000051,68,20,11,2,'Küstahlığın ardından utanç gelir, 2 Ama bilgelik alçakgönüllülerdedir.'),
(2000052,68,20,11,3,'Erdemlinin dürüstlüğü ona yol gösterir, 2 Hainin yalancılığıysa yıkıma götürür.'),
(2000053,68,20,11,4,'Gazap günü servet işe yaramaz, 2 Oysa doğruluk ölümden kurtarır.'),
(2000054,68,20,11,5,'Dürüst insanın doğruluğu onun yolunu düzler, 2 Kötü kişiyse kötülüğü yüzünden yıkılıp düşer.'),
(2000055,68,20,11,6,'Erdemlinin doğruluğu onu kurtarır, 2 Ama haini kendi hırsı ele verir.'),
(2000056,68,20,11,7,'Kötü kişi öldüğünde umutları yok olur, 2 Güvendiği güç de biter.'),
(2000057,68,20,11,8,'Doğru kişi sıkıntıdan kurtulur, 2 Onun yerine sıkıntıyı kötü kişi çeker.'),
(2000058,68,20,11,9,'Tanrısız kişi başkalarını ağzıyla yıkıma götürür, 2 Oysa doğrular bilgi sayesinde kurtulur.'),
(2000059,68,20,11,10,'Doğruların başarısına kent bayram eder, 2 Kötülerin ölümüne sevinç çığlıkları atılır.'),
(2000060,68,20,11,11,'Dürüstlerin kutsamasıyla kent gelişir, 2 Ama kötülerin ağzı kenti yerle bir eder.'),
(2000061,68,20,11,12,'Başkasını küçük gören sağduyudan yoksundur, 2 Akıllı kişiyse dilini tutar.'),
(2000062,68,20,11,13,'Dedikoducu sır saklayamaz, 2 Oysa güvenilir insan sırdaş olur.'),
(2000063,68,20,11,14,'Yol göstereni olmayan ulus düşer, 2 Danışmanı bol olan zafere gider.'),
(2000064,68,20,11,15,'Yabancıya kefil olan mutlaka zarar görür, 2 Kefaletten kaçınan güvenlik içinde yaşar.'),
(2000065,68,20,11,16,'Sevecen kadın onurfç, 2 Zorbalarsa yalnızca servet kazanır. geçiyor: ‹‹Ama doğruluktan nefret eden kadın onursuzluk tahtıdır. Tembeller servetten yoksun olur.››'),
(2000066,68,20,11,17,'İyilikseverin yararı kendinedir, 2 Gaddarsa kendi başına bela getirir.'),
(2000067,68,20,11,18,'Kötü kişinin kazancı aldatıcıdır, 2 Doğruluk ekenin ödülüyse güvenlidir.'),
(2000068,68,20,11,19,'Yürekten doğru olan yaşama kavuşur, 2 Kötülüğün ardından giden ölümünü hazırlar.'),
(2000069,68,20,11,20,'RAB sapık yürekliden iğrenir, 2 Dürüst yaşayandan hoşnut kalır.'),
(2000070,68,20,11,21,'Bilin ki, kötü kişi cezasız kalmaz, 2 Doğruların soyuysa kurtulur.'),
(2000071,68,20,11,22,'Sağduyudan yoksun kadının güzelliği, 2 Domuzun burnundaki altın halkaya benzer.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000072,68,20,11,23,'Doğruların isteği hep iyilikle sonuçlanır, 2 Kötülerin umutlarıysa gazapla.'),
(2000073,68,20,11,24,'Eliaçık olan daha çok kazanır, 2 Hak yiyenin sonuysa yoksulluktur.'),
(2000074,68,20,11,25,'Cömert olan bolluğa erecek, 2 Başkasına su verene su verilecek.'),
(2000075,68,20,11,26,'Halk buğday istifleyeni lanetler, 2 Ama buğday satanı kutsar.'),
(2000076,68,20,11,27,'İyiliği amaç edinen beğeni kazanır, 2 Kötülüğü amaç edinense kötülüğe uğrar.'),
(2000077,68,20,11,28,'Zenginliğine güvenen tepetaklak gidecek, 2 Oysa doğrular dalındaki yaprak gibi gelişecek.'),
(2000078,68,20,11,29,'Ailesine sıkıntı çektirenin mirası yeldir, 2 Ahmaklar da bilgelerin kulu olur.'),
(2000079,68,20,11,30,'Doğru kişinin işleri yaşam ağacının meyvesine benzer, 2 Bilge kişi insanları kazanır.'),
(2000080,68,20,11,31,'Bu dünyada doğru kişi bile cezalandırılırsa, 2 Kötülerle günahlıların cezalandırılacağı kesindir.'),
(2000081,68,20,12,1,'Terbiye edilmeyi seven bilgiyi de sever, 2 Azarlanmaktan nefret eden budaladır.'),
(2000082,68,20,12,2,'İyi kişi RABbin lütfuna erer, 2 Ama düzenbazı RAB mahkûm eder.'),
(2000083,68,20,12,3,'Kötülük kişiyi güvenliğe kavuşturmaz, 2 Ama doğruların kökü kazılamaz.'),
(2000084,68,20,12,4,'Erdemli kadın kocasının tacıdır, 2 Edepsiz kadınsa kocasını yer bitirir.'),
(2000085,68,20,12,5,'Doğruların tasarıları adil, 2 Kötülerin öğütleri aldatıcıdır.'),
(2000086,68,20,12,6,'Kötülerin sözleri ölüm tuzağıdır, 2 Doğruların konuşmasıysa onları kurtarır.'),
(2000087,68,20,12,7,'Kötüler yıkılıp yok olur, 2 Doğru kişinin evi ayakta kalır.'),
(2000088,68,20,12,8,'Kişi sağduyusu oranında övülür, 2 Çarpık düşünceliyse küçümsenir.'),
(2000089,68,20,12,9,'Köle sahibi olup aşağılanan 2 Büyüklük taslayıp ekmeğe muhtaç olandan yeğdir.'),
(2000090,68,20,12,10,'Doğru kişi hayvanıyla ilgilenir, 2 Ama kötünün sevecenliği bile zalimcedir.'),
(2000091,68,20,12,11,'Toprağını işleyenin ekmeği bol olur, 2 Hayal peşinde koşansa sağduyudan yoksundur.'),
(2000092,68,20,12,12,'Kötü kişi kötülerin ganimetini ister, 2 Ama doğru kişilerin kökü ürün verir.'),
(2000093,68,20,12,13,'Kötü kişinin günahlı sözleri kendisi için tuzaktır, 2 Ama doğru kişi sıkıntıyı atlatır.'),
(2000094,68,20,12,14,'İnsan ağzının ürünüyle iyiliğe doyar, 2 Elinin emeğine göre de karşılığını alır.'),
(2000095,68,20,12,15,'Ahmağın yolu kendi gözünde doğrudur, 2 Bilge kişiyse öğüde kulak verir.'),
(2000096,68,20,12,16,'Ahmak sinirlendiğini hemen belli eder, 2 Ama ihtiyatlı olan aşağılanmaya aldırmaz.'),
(2000097,68,20,12,17,'Dürüst tanık doğruyu söyler, 2 Yalancı tanıksa hile solur.'),
(2000098,68,20,12,18,'Düşünmeden söylenen sözler kılıç gibi keser, 2 Bilgelerin diliyse şifa verir.'),
(2000099,68,20,12,19,'Gerçek sözler sonsuza dek kalıcıdır, 2 Oysa yalanın ömrü bir anlıktır.'),
(2000100,68,20,12,20,'Kötülük tasarlayanın yüreği hileci, 2 Barışı öğütleyenin yüreğiyse sevinçlidir.'),
(2000101,68,20,12,21,'Doğru kişiye hiç zarar gelmez, 2 Kötünün başıysa beladan kurtulmaz.'),
(2000102,68,20,12,22,'RAB yalancı dudaklardan iğrenir, 2 Ama gerçeğe uyanlardan hoşnut kalır.'),
(2000103,68,20,12,23,'İhtiyatlı kişi bilgisini kendine saklar, 2 Oysa akılsızın yüreği ahmaklığını ilan eder.'),
(2000104,68,20,12,24,'Çalışkanların eli egemenlik sürer, 2 Tembellikse köleliğe götürür.'),
(2000105,68,20,12,25,'Kaygılı yürek insanı çökertir, 2 Ama güzel söz sevindirir.'),
(2000106,68,20,12,26,'Doğru kişi arkadaşına da yol gösterir, 2 Kötünün tuttuğu yolsa kendini saptırır.'),
(2000107,68,20,12,27,'Tembel kişi işini bitirmez, 2 Oysa çalışkan değerli bir servet kazanır.'),
(2000108,68,20,12,28,'Doğru yol yaşam kaynağıdır, 2 Bu yol ölümsüzlüğe götürür.'),
(2000109,68,20,13,1,'Bilge kişi terbiye edilmeyi sever, 2 Alaycı kişi azarlansa da aldırmaz.'),
(2000110,68,20,13,2,'İyi insan ağzından çıkan sözler için ödüllendirilir, 2 Ama hainlerin soluduğu zorbalıktır.'),
(2000111,68,20,13,3,'Dilini tutan canını korur, 2 Ama boşboğazın sonu yıkımdır.'),
(2000112,68,20,13,4,'Tembel canının çektiğini elde edemez, 2 Çalışkanın istekleriyse tümüyle yerine gelir.'),
(2000113,68,20,13,5,'Doğru kişi yalandan nefret eder, 2 Kötünün sözleriyse iğrençtir, yüzkarasıdır.'),
(2000114,68,20,13,6,'Doğruluk dürüst yaşayanı korur, 2 Kötülük günahkârı yıkar.'),
(2000115,68,20,13,7,'Kimi hiçbir şeyi yokken kendini zengin gösterir, 2 Kimi serveti çokken kendini yoksul gösterir.'),
(2000116,68,20,13,8,'Kişinin serveti gün gelir canına fidye olur, 2 Oysa yoksul kişi tehdide aldırmaz.'),
(2000117,68,20,13,9,'Doğruların ışığı parlak yanar, 2 Kötülerin çırası söner.'),
(2000118,68,20,13,10,'Kibirden ancak kavga çıkar, 2 Öğüt dinleyense bilgedir.'),
(2000119,68,20,13,11,'Havadan kazanılan para yok olur, 2 Azar azar biriktirenin serveti çok olur.'),
(2000120,68,20,13,12,'Ertelenen umut hayal kırıklığına uğratır, 2 Yerine gelen dilekse yaşam verir.'),
(2000121,68,20,13,13,'Uyarılara kulak asmayan bedelini öder, 2 Buyruklara saygılı olansa ödülünü alır.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000122,68,20,13,14,'Bilgelerin öğrettikleri yaşam kaynağıdır, 2 İnsanı ölüm tuzaklarından uzaklaştırır.'),
(2000123,68,20,13,15,'Sağduyulu davranış saygınlık kazandırır, 2 Hainlerin yoluysa yıkıma götürür. Masoretik metin ‹‹Sürer›› ya da ‹‹Çetindir››.'),
(2000124,68,20,13,16,'İhtiyatlı kişi işini bilerek yapar, 2 Akılsız kişiyse ahmaklığını sergiler.'),
(2000125,68,20,13,17,'Kötü ulak belaya düşer, 2 Güvenilir elçiyse şifa getirir.'),
(2000126,68,20,13,18,'Terbiye edilmeye yanaşmayanı 2 Yokluk ve utanç bekliyor, 2 Ama azara kulak veren onurlandırılır.'),
(2000127,68,20,13,19,'Yerine getirilen dilek mutluluk verir. 2 Akılsız kötülükten uzak kalamaz.'),
(2000128,68,20,13,20,'Bilgelerle oturup kalkan bilge olur, 2 Akılsızlarla dost olansa zarar görür.'),
(2000129,68,20,13,21,'Günahkârın peşini felaket bırakmaz, 2 Doğruların ödülüyse gönençtir.'),
(2000130,68,20,13,22,'İyi kişi torunlarına miras bırakır, 2 Günahkârın servetiyse doğru kişiye kalır.'),
(2000131,68,20,13,23,'Yoksulun tarlası bol ürün verebilir, 2 Ama haksızlık bunu alıp götürür.'),
(2000132,68,20,13,24,'Oğlundan değneği esirgeyen, onu sevmiyor demektir. 2 Seven baba özenle terbiye eder.'),
(2000133,68,20,13,25,'Doğru kişinin yeterince yiyeceği vardır, 2 Kötünün karnıysa aç kalır.'),
(2000134,68,20,14,1,'Bilge kadın evini yapar, 2 Ahmak kadın evini kendi eliyle yıkar.'),
(2000135,68,20,14,2,'Doğru yolda yürüyen, RABden korkar, 2 Yoldan sapan, RABbi hor görür.'),
(2000136,68,20,14,3,'Ahmağın sözleri sırtına kötektir, 2 Ama bilgenin dudakları kendisini korur.'),
(2000137,68,20,14,4,'Öküz yoksa yemlik boş kalır, 2 Çünkü bol ürünü sağlayan öküzün gücüdür.'),
(2000138,68,20,14,5,'Güvenilir tanık yalan söylemez, 2 Yalancı tanıksa yalan solur.'),
(2000139,68,20,14,6,'Alaycı bilgeliği arasa da bulamaz, 2 Akıllı içinse bilgi edinmek kolaydır.'),
(2000140,68,20,14,7,'Akılsız kişiden uzak dur, 2 Çünkü sana öğretecek bir şeyi yok.'),
(2000141,68,20,14,8,'İhtiyatlı kişinin bilgeliği, ne yapacağını bilmektir, 2 Akılsızların ahmaklığıysa aldanmaktır.'),
(2000142,68,20,14,9,'Ahmaklar suç sunusuyla alay eder, 2 Dürüstler ise iyi niyetlidir.'),
(2000143,68,20,14,10,'Yürek kendi acısını bilir, 2 Sevinciniyse kimse paylaşmaz.'),
(2000144,68,20,14,11,'Kötü kişinin evi yerle bir edilecek, 2 Doğru kişinin konutuysa bayındır olacak.'),
(2000145,68,20,14,12,'Öyle yol var ki, insana düz gibi görünür, 2 Ama sonu ölümdür.'),
(2000146,68,20,14,13,'Gülerken bile yürek sızlayabilir, 2 Sevinç bitince acı yine görünebilir.'),
(2000147,68,20,14,14,'Yüreği dönek olan tuttuğu yolun, 2 İyi kişi de yaptıklarının ödülünü alacaktır.'),
(2000148,68,20,14,15,'Saf kişi her söze inanır, 2 İhtiyatlı olansa attığı her adımı hesaplar.'),
(2000149,68,20,14,16,'Bilge kişi korktuğu için kötülükten uzaklaşır, 2 Akılsızsa büyüklük taslayıp kendine güvenir.'),
(2000150,68,20,14,17,'Çabuk öfkelenen ahmakça davranır, 2 Düzenbazdan herkes nefret eder.'),
(2000151,68,20,14,18,'Saf kişilerin mirası akılsızlıktır, 2 İhtiyatlı kişilerin tacı ise bilgidir.'),
(2000152,68,20,14,19,'Alçaklar iyilerin önünde, 2 Kötüler doğruların kapısında eğilirler.'),
(2000153,68,20,14,20,'Komşusu bile yoksulu sevmez, 2 Oysa zenginin dostu çoktur.'),
(2000154,68,20,14,21,'Komşuyu hor görmek günahtır, 2 Ne mutlu mazluma lütfedene!'),
(2000155,68,20,14,22,'Kötülük tasarlayan yolunu şaşırmaz mı? 2 Oysa iyilik tasarlayan sevgi ve sadakat kazanır.'),
(2000156,68,20,14,23,'Her emek kazanç getirir, 2 Ama boş lakırdı yoksulluğa götürür.'),
(2000157,68,20,14,24,'Bilgelerin tacı servetleridir, 2 Akılsızlarsa ahmaklıklarıyla tanınır. ‹‹Akılsızların çelengiyse ahmaklıktır››.'),
(2000158,68,20,14,25,'Dürüst tanık can kurtarır, 2 Yalancı tanık aldatıcıdır.'),
(2000159,68,20,14,26,'RABden korkan tam güvenliktedir, 2 RAB onun çocuklarına da sığınak olacaktır.'),
(2000160,68,20,14,27,'RAB korkusu yaşam kaynağıdır, 2 İnsanı ölüm tuzaklarından uzaklaştırır.'),
(2000161,68,20,14,28,'Kralın yüceliği halkının çokluğuna bağlıdır, 2 Halk yok olursa hükümdar da mahvolur.'),
(2000162,68,20,14,29,'Geç öfkelenen akıllıdır, 2 Çabuk sinirlenen ahmaklığını gösterir.'),
(2000163,68,20,14,30,'Huzurlu yürek bedenin yaşam kaynağıdır, 2 Hırs ise insanı için için yer bitirir.'),
(2000164,68,20,14,31,'Muhtacı ezen, Yaradanını hor görüyor demektir. 2 Yoksula acıyansa Yaradanı yüceltir.'),
(2000165,68,20,14,32,'Kötü kişi uğradığı felaketle yıkılır, 2 Doğru insanın ölümde bile sığınacak yeri var.'),
(2000166,68,20,14,33,'Bilgelik akıllı kişinin yüreğinde barınır, 2 Akılsızlar arasında bile kendini belli eder.'),
(2000167,68,20,14,34,'Doğruluk bir ulusu yüceltir, 2 Oysa günah herhangi bir halk için utançtır.'),
(2000168,68,20,14,35,'Kral sağduyulu kulunu beğenir, 2 Utanç getirene öfkelenir.'),
(2000169,68,20,15,1,'Yumuşak yanıt gazabı yatıştırır, 2 Oysa yaralayıcı söz öfkeyi alevlendirir.'),
(2000170,68,20,15,2,'Bilgenin dili bilgiyi iyi kullanır, 2 Akılsızın ağzındansa ahmaklık akar.'),
(2000171,68,20,15,3,'RABbin gözü her yerde olanı görür, 2 Kötüleri de iyileri de gözler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000172,68,20,15,4,'Okşayıcı dil yaşam verirfı, 2 Çarpık dilse ruhu yaralar.'),
(2000173,68,20,15,5,'Ahmak babasının uyarılarını küçümser, 2 İhtiyatlı kişi azara kulak verir.'),
(2000174,68,20,15,6,'Doğru kişinin evi büyük hazine gibidir, 2 Kötünün geliriyse sıkıntı kaynağıdır.'),
(2000175,68,20,15,7,'Bilgelerin dudakları bilgi yayar, 2 Ama akılsızların yüreği öyle değildir.'),
(2000176,68,20,15,8,'RAB kötülerin kurbanından iğrenir, 2 Ama doğruların duası Onu hoşnut eder.'),
(2000177,68,20,15,9,'RAB kötü kişinin yolundan iğrenir, 2 Doğruluğun ardından gideni sever.'),
(2000178,68,20,15,10,'Yoldan sapan şiddetle cezalandırılır 2 Ve azarlanmaktan nefret eden ölüme gider.'),
(2000179,68,20,15,11,'RAB, ölüm ve yıkım diyarında olup biteni bilir, 2 Nerde kaldı ki insanın yüreği!'),
(2000180,68,20,15,12,'Alaycı kişi azarlanmaktan hoşlanmaz, 2 Bilgelere gidip danışmaz.'),
(2000181,68,20,15,13,'Mutlu yürek yüzü neşelendirir, 2 Acılı yürek ruhu ezer.'),
(2000182,68,20,15,14,'Akıllı yürek bilgi arar, 2 Akılsızın ağzıysa ahmaklıkla beslenir.'),
(2000183,68,20,15,15,'Mazlumun bütün günleri sıkıntı doludur, 2 Mutlu bir yürekse sahibine sürekli ziyafettir.'),
(2000184,68,20,15,16,'Yoksul olup RABden korkmak, 2 Zengin olup kaygı içinde yaşamaktan yeğdir.'),
(2000185,68,20,15,17,'Sevgi dolu bir ortamdaki sebze yemeği, 2 Nefret dolu bir ortamdaki besili danadan yeğdir.'),
(2000186,68,20,15,18,'Huysuz kişi çekişme yaratır, 2 Sabırlı kişi kavgayı yatıştırır.'),
(2000187,68,20,15,19,'Tembelin yolu dikenli çit gibidir, 2 Doğrunun yoluysa ana caddeye benzer.'),
(2000188,68,20,15,20,'Bilge çocuk babasını sevindirir, 2 Akılsız çocuksa annesini küçümser.'),
(2000189,68,20,15,21,'Sağduyudan yoksun kişi ahmaklığıyla sevinir, 2 Ama akıllı insan dürüst bir yaşam sürer.'),
(2000190,68,20,15,22,'Karşılıklı danışılmazsa tasarılar boşa çıkar, 2 Danışmanların çokluğuyla başarıya ulaşılır.'),
(2000191,68,20,15,23,'Uygun yanıt sahibini mutlu eder, 2 Yerinde söylenen söz ne güzeldir!'),
(2000192,68,20,15,24,'Sağduyulu kişi yukarıya, yaşama giden yoldadır, 2 Bu da ölüler diyarına inmesini önler.'),
(2000193,68,20,15,25,'RAB kibirlinin evini yıkar, 2 Dul kadının sınırını korur.'),
(2000194,68,20,15,26,'RAB kötünün tasarılarından iğrenir, 2 Temiz düşüncelerden hoşnut kalır. temizdir››.'),
(2000195,68,20,15,27,'Kazanca düşkün kişi kendi evine sıkıntı verir, 2 Rüşvetten nefret edense rahat yaşar.'),
(2000196,68,20,15,28,'Doğru kişinin aklı yanıtını iyi tartar, 2 Kötünün ağzı kötülük saçar.'),
(2000197,68,20,15,29,'RAB kötülerden uzak durur, 2 Oysa doğruların duasını duyar.'),
(2000198,68,20,15,30,'Gülen gözler yüreği sevindirir, 2 İyi haber bedeni ferahlatır.'),
(2000199,68,20,15,31,'Yaşam veren uyarıları dinleyen, 2 Bilgeler arasında konaklar.'),
(2000200,68,20,15,32,'Terbiyeden kaçan kendine zarar verir, 2 Azara kulak verense sağduyu kazanır.'),
(2000201,68,20,15,33,'RAB korkusu bilgelik öğretir, 2 Alçakgönüllülük de onurun önkoşuludur.'),
(2000202,68,20,16,1,'İnsan aklıyla çok şey tasarlayabilir, 2 Ama dilin vereceği yanıt RABdendir.'),
(2000203,68,20,16,2,'İnsan her yaptığını temiz sanır, 2 Ama niyetlerini tartan RABdir.'),
(2000204,68,20,16,3,'Yapacağın işleri RABbe emanet et, 2 O zaman tasarıların gerçekleşir.'),
(2000205,68,20,16,4,'RAB her şeyi amacına uygun yapar, 2 Kötü kişinin yıkım gününü de O hazırlar.'),
(2000206,68,20,16,5,'RAB yüreği küstah olandan iğrenir, 2 Bilin ki, öyleleri cezasız kalmaz.'),
(2000207,68,20,16,6,'Sevgi ve bağlılık suçları bağışlatır, 2 RAB korkusu insanı kötülükten uzaklaştırır.'),
(2000208,68,20,16,7,'RAB kişinin yaşayışından hoşnutsa 2 Düşmanlarını bile onunla barıştırır.'),
(2000209,68,20,16,8,'Doğrulukla kazanılan az şey 2 Haksızlıkla kazanılan büyük gelirden iyidir.'),
(2000210,68,20,16,9,'Kişi yüreğinde gideceği yolu tasarlar, 2 Ama adımlarını RAB yönlendirir.'),
(2000211,68,20,16,10,'Tanrı buyruklarını kralın ağzıyla açıklar, 2 Bu nedenle kral adaleti çiğnememelidir.'),
(2000212,68,20,16,11,'Doğru terazi ve baskül RABbindir, 2 Bütün tartı ağırlıklarını O belirler.'),
(2000213,68,20,16,12,'Krallar kötülükten iğrenir, 2 Çünkü tahtın güvencesi adalettir.'),
(2000214,68,20,16,13,'Kral doğru söyleyenden hoşnut kalır, 2 Dürüst konuşanı sever.'),
(2000215,68,20,16,14,'Kralın öfkesi ölüm habercisidir, 2 Ama bilge kişi onu yatıştırır.'),
(2000216,68,20,16,15,'Kralın yüzü gülüyorsa, yaşam demektir. 2 Lütfu son yağmuru getiren bulut gibidir.'),
(2000217,68,20,16,16,'Bilgelik kazanmak altından daha değerlidir, 2 Akla sahip olmak da gümüşe yeğlenir.'),
(2000218,68,20,16,17,'Dürüstlerin tuttuğu yol kötülükten uzaklaştırır, 2 Yoluna dikkat eden, canını korur.'),
(2000219,68,20,16,18,'Gururun ardından yıkım, 2 Kibirli ruhun ardından da düşüş gelir.'),
(2000220,68,20,16,19,'Mazlumlar arasında alçakgönüllü biri olmak, 2 Kibirlilerle çapul malı paylaşmaktan iyidir.'),
(2000221,68,20,16,20,'Öğüde kulak veren başarıya ulaşır, 2 RABbe güvenen mutlu olur.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000222,68,20,16,21,'Bilge yüreklilere akıllı denir, 2 Tatlı söz ikna gücünü artırır.'),
(2000223,68,20,16,22,'Sağduyu, sahibine yaşam kaynağı, 2 Ahmaklıksa ahmaklara cezadır.'),
(2000224,68,20,16,23,'Bilgenin aklı diline yön verir, 2 Dudaklarının ikna gücünü artırır.'),
(2000225,68,20,16,24,'Hoş sözler petek balı gibidir, 2 Cana tatlı ve bedene şifadır.'),
(2000226,68,20,16,25,'Öyle yol var ki, insana düz gibi görünür, 2 Ama sonu ölümdür.'),
(2000227,68,20,16,26,'Emekçinin iştahıdır onu çalıştıran, 2 Çünkü açlığı onu kamçılar.'),
(2000228,68,20,16,27,'Alçaklar başkalarına kötülük tasarlar, 2 Konuşmaları kavurucu ateş gibidir.'),
(2000229,68,20,16,28,'Huysuz kişi çekişmeyi körükler, 2 Dedikoducu can dostları ayırır.'),
(2000230,68,20,16,29,'Zorba kişi başkalarını ayartır 2 Ve onları olumsuz yola yöneltir.'),
(2000231,68,20,16,30,'Göz kırpmak düzenbazlığa, 2 Sinsi gülücükler kötülüğe işarettir.'),
(2000232,68,20,16,31,'Ağarmış saçlar onur tacıdır, 2 Doğru yaşayışla kazanılır.'),
(2000233,68,20,16,32,'Sabırlı kişi yiğitten üstündür, 2 Kendini denetleyen de kentler fethedenden üstündür.'),
(2000234,68,20,16,33,'İnsan kura atar, 2 Ama her kararı RAB verir.'),
(2000235,68,20,17,1,'Huzur içinde kuru bir lokma, 2 Kavga ve ziyafet dolu evden iyidir.'),
(2000236,68,20,17,2,'Sağduyulu köle, 2 Ailesini utanca sokan oğula egemen olur 2 Ve kardeşlerle birlikte mirastan pay alır.'),
(2000237,68,20,17,3,'Altın ocakta, gümüş potada arıtılır, 2 Yüreği arıtansa RABdir.'),
(2000238,68,20,17,4,'Kötü kişi fesat yüklü dudakları dinler, 2 Yalancı da yıkıcı dile kulak verir.'),
(2000239,68,20,17,5,'Yoksulla alay eden, onu yaratanı hor görür. 2 Felakete sevinen cezasız kalmaz.'),
(2000240,68,20,17,6,'Torunlar yaşlıların tacıdır, 2 Çocukların övüncü anne babalarıdır.'),
(2000241,68,20,17,7,'Kurumlu sözler ahmağa nasıl yakışmazsa, 2 Soyluya da yalancı dudaklar hiç yakışmaz.'),
(2000242,68,20,17,8,'Sahibinin gözünde rüşvet bir tılsımdır. 2 Ne yapsa başarılı olur.'),
(2000243,68,20,17,9,'Sevgi isteyen kişi suçları bağışlar, 2 Olayı diline dolayansa can dostları ayırır.'),
(2000244,68,20,17,10,'Akıllı kişiyi azarlamak, 2 Akılsıza yüz darbe vurmaktan etkilidir.'),
(2000245,68,20,17,11,'Kötü kişi ancak başkaldırmaya eğilimlidir, 2 Ona gönderilecek ulak acımasız olacaktır.'),
(2000246,68,20,17,12,'Azgınlığı üstünde bir akılsızla karşılaşmak, 2 Yavrularından edilmiş dişi ayıyla karşılaşmaktan beterdir.'),
(2000247,68,20,17,13,'İyiliğin karşılığını kötülükle ödeyenin 2 Evinden kötülük eksik olmaz.'),
(2000248,68,20,17,14,'Kavganın başlangıcı su sızıntısına benzer, 2 Bir patlamaya yol açmadan çekişmeyi bırak.'),
(2000249,68,20,17,15,'Kötüyü aklayan da, doğruyu mahkûm eden de 2 RABbi tiksindirir.'),
(2000250,68,20,17,16,'Akılsız biri bilgelik satın almak için niye para harcasın? 2 Zaten sağduyudan yoksun!'),
(2000251,68,20,17,17,'Dost her zaman sever, 2 Kardeş sıkıntılı günde belli olur.'),
(2000252,68,20,17,18,'Sağduyudan yoksun kişi el sıkışıp 2 Başkasına kefil olur.'),
(2000253,68,20,17,19,'Başkaldırıyı seven kavgayı sever, 2 Kapısını yüksek yapan yıkımına davetiye çıkarır.'),
(2000254,68,20,17,20,'Sapık yürekli kişi iyilik beklememeli. 2 Diliyle aldatan da belaya düşer.'),
(2000255,68,20,17,21,'Akılsız kendisini doğurana derttir, 2 Ahmağın babası sevinç nedir bilmez.'),
(2000256,68,20,17,22,'İç ferahlığı sağlık getirir, 2 Ezik ruh ise bedeni yıpratır.'),
(2000257,68,20,17,23,'Kötü kişi adaleti saptırmak için 2 Gizlice rüşvet alır.'),
(2000258,68,20,17,24,'Akıllı kişi gözünü bilgelikten ayırmaz, 2 Akılsızın gözüyse hep sağda soldadır.'),
(2000259,68,20,17,25,'Akılsız çocuk babasına üzüntü, 2 Annesine acı verir.'),
(2000260,68,20,17,26,'Ne suçsuza ceza kesmek iyidir, 2 Ne de görevliyi dürüst davrandığı için dövmek...'),
(2000261,68,20,17,27,'Bilgili kişi az konuşur, 2 Akıllı kişi sakin ruhludur.'),
(2000262,68,20,17,28,'Çenesini tutup susan ahmak bile 2 Bilge ve akıllı sayılır.'),
(2000263,68,20,18,1,'Geçimsiz kişi kendi çıkarı peşindedir, 2 İyi öğüde hep karşı çıkar.'),
(2000264,68,20,18,2,'Akılsız kişi bir şey anlamaktan çok 2 Kendi düşüncelerini açmaktan hoşlanır.'),
(2000265,68,20,18,3,'Kötülüğü aşağılanma, 2 Ayıbı utanç izler.'),
(2000266,68,20,18,4,'Bilge kişinin ağzından çıkan sözler derin sular gibidir, 2 Bilgelik pınarı da coşkun bir akarsu.'),
(2000267,68,20,18,5,'Kötüyü kayırmak da, 2 Suçsuzdan adaleti esirgemek de iyi değildir.'),
(2000268,68,20,18,6,'Akılsızın dudakları çekişmeye yol açar, 2 Ağzı da dayağı davet eder.'),
(2000269,68,20,18,7,'Akılsızın ağzı kendisini mahveder, 2 Dudakları da canına tuzaktır.'),
(2000270,68,20,18,8,'Dedikodu tatlı lokma gibidir, 2 İnsanın ta içine işler.'),
(2000271,68,20,18,9,'İşini savsaklayan kişi 2 Yıkıcıya kardeştir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000272,68,20,18,10,'RABbin adı güçlü kuledir, 2 Ona sığınan doğru kişi için korunaktır.'),
(2000273,68,20,18,11,'Zengin servetini bir kale, 2 Aşılmaz bir sur sanır.'),
(2000274,68,20,18,12,'Yürekteki gururu düşüş, 2 Alçakgönüllülüğü ise onur izler.'),
(2000275,68,20,18,13,'Dinlemeden yanıt vermek 2 Ahmaklık ve utançtır.'),
(2000276,68,20,18,14,'İnsanın ruhu hastalıkta ona destektir. 2 Ama ezik ruh nasıl dayanabilir?'),
(2000277,68,20,18,15,'Akıllı kişi bilgiyi satın alır, 2 Bilgenin kulağı da bilgi peşindedir.'),
(2000278,68,20,18,16,'Armağan, verenin yolunu açar 2 Ve kendisini büyüklerin önüne çıkartır.'),
(2000279,68,20,18,17,'Duruşmada ilk konuşan haklı görünür, 2 Başkası çıkıp onu sorgulayana dek.'),
(2000280,68,20,18,18,'Kura çekişmeleri sona erdirir, 2 Güçlü rakipleri uzlaştırır.'),
(2000281,68,20,18,19,'Gücenmiş kardeş surlu kentten daha zor elde edilir. 2 Çekişme sürgülü kale kapısı gibidir.'),
(2000282,68,20,18,20,'İnsanın karnı ağzının meyvesiyle, 2 Dudaklarının ürünüyle doyar.'),
(2000283,68,20,18,21,'Dil ölüme de götürebilir, yaşama da; 2 Konuşmayı seven, dilin meyvesine katlanmak zorundadır.'),
(2000284,68,20,18,22,'İyi bir eş bulan iyilik bulur 2 Ve RABbin lütfuna erer.'),
(2000285,68,20,18,23,'Yoksul acınma dilenir, 2 Zenginin yanıtıysa serttir.'),
(2000286,68,20,18,24,'Yıkıma götüren dostlar vardır, 2 Ama öyle dost var ki, kardeşten yakındır insana. yıkıma gider››.'),
(2000287,68,20,19,1,'Dürüst yaşayan bir yoksul olmak, 2 Yalancı bir akılsız olmaktan yeğdir.'),
(2000288,68,20,19,2,'Bilgisiz heves işe yaramaz, 2 Acelecilik insanı yanılgıya düşürür.'),
(2000289,68,20,19,3,'İnsanın ahmaklığı yaşamını yıkar, 2 Yine de içinden RABbe öfkelenir.'),
(2000290,68,20,19,4,'Zenginlik dost üstüne dost kazandırır. 2 Oysa yoksulun dostu onu yüzüstü bırakır.'),
(2000291,68,20,19,5,'Yalancı tanık cezasız kalmaz, 2 Yalan soluyan kurtulamaz.'),
(2000292,68,20,19,6,'Birçokları önemli kişinin gözüne girmek 2 Ve eli açık olanın dostu olmak ister.'),
(2000293,68,20,19,7,'Yoksulun akrabaları bile onu sevmezse, 2 Dostlarının ondan uzak duracağı daha da kesindir. 2 Ne kadar yalvarsa ona yaklaşmazlar.'),
(2000294,68,20,19,8,'Sağduyulu olan canını sever, 2 Aklı izleyen bolluğa kavuşur.'),
(2000295,68,20,19,9,'Yalancı tanık cezasız kalmaz, 2 Yalan soluyan yok olur.'),
(2000296,68,20,19,10,'Akılsızın gösterişli bir yaşam sürmesi uygun değilse, 2 Kölelerin önderlere egemen olması 2 Hiç uygun değildir.'),
(2000297,68,20,19,11,'Sağduyulu kişi sabırlıdır, 2 Kusurları hoş görmesi ona onur kazandırır.'),
(2000298,68,20,19,12,'Kralın öfkesi genç aslanın kükreyişine benzer, 2 Lütfuysa otların üzerine düşen çiy gibidir.'),
(2000299,68,20,19,13,'Akılsız çocuk babasının başına beladır, 2 Dırdır eden kadın sürekli damlayan su gibidir.'),
(2000300,68,20,19,14,'Ev ve servet babadan mirastır, 2 Ama sağduyulu kadın RABbin armağanıdır.'),
(2000301,68,20,19,15,'Tembellik insanı uyuşukluğa iter, 2 Haylaz kişi de aç kalır.'),
(2000302,68,20,19,16,'Tanrı buyruğuna uyan canını korur, 2 Gitmesi gereken yolları umursamayan ölür.'),
(2000303,68,20,19,17,'Yoksula acıyan kişi RABbe ödünç vermiş olur, 2 Yaptığı iyilik için RAB onu ödüllendirir.'),
(2000304,68,20,19,18,'Henüz umut varken çocuğunu eğit, 2 Onun yıkımına neden olma.'),
(2000305,68,20,19,19,'Huysuz insan cezasını çekmelidir. 2 Onu bir kere kurtarsan da, hep aynı şeyi yapman gerekir.'),
(2000306,68,20,19,20,'Öğüde kulak ver, terbiyeyi kabul et ki, 2 Ömrünün kalan kısmı boyunca bilge olasın.'),
(2000307,68,20,19,21,'İnsan yüreğinde çok şey tasarlar, 2 Ama gerçekleşen, RABbin amacıdır.'),
(2000308,68,20,19,22,'İnsandan istenen vefadır, 2 Yoksul olmak yalancı olmaktan yeğdir.'),
(2000309,68,20,19,23,'RAB korkusu 2 Doygun ve dertsiz bir yaşama kavuşturur.'),
(2000310,68,20,19,24,'Tembel sahana daldırdığı elini 2 Ağzına geri götürmek bile istemez.'),
(2000311,68,20,19,25,'Alaycıyı döversen bön kişi ibret alır, 2 Akıllı kişiyi azarlarsan bilgisine bilgi katar.'),
(2000312,68,20,19,26,'Babasına saldıran, annesini kovan çocuk, 2 Ailesinin utancı ve yüzkarasıdır.'),
(2000313,68,20,19,27,'Oğlum, uyarılara kulağını tıkarsan, 2 Bilgi kaynağı sözlerden saparsın.'),
(2000314,68,20,19,28,'Niyeti bozuk tanık adaletle eğlenir, 2 Kötülerin ağzı fesatla beslenir.'),
(2000315,68,20,19,29,'Alaycılar için ceza, 2 Akılsızların sırtı için kötek hazırdır.'),
(2000316,68,20,20,1,'Şarap insanı alaycı, içki gürültücü yapar, 2 Onun etkisiyle yoldan sapan bilge değildir.'),
(2000317,68,20,20,2,'Kralın öfkesi genç aslanın kükreyişine benzer, 2 Onu kızdıran canından olur.'),
(2000318,68,20,20,3,'Kavgadan kaçınmak insan için onurdur, 2 Oysa her ahmak tartışmaya hazırdır.'),
(2000319,68,20,20,4,'Sonbaharda çift sürmeyen tembel, 2 Hasatta aradığını bulamaz.'),
(2000320,68,20,20,5,'İnsanın niyetleri derin bir kuyunun suları gibidir, 2 Akıllı kişi onları açığa çıkarır.'),
(2000321,68,20,20,6,'İnsanların çoğu, ‹‹Vefalıyım›› der. 2 Ama sadık birini kim bulabilir?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000322,68,20,20,7,'Doğru ve dürüst bir babaya 2 Sahip olan çocuklara ne mutlu!'),
(2000323,68,20,20,8,'Yargı kürsüsünde oturan kral, 2 Kötülüğü gözleriyle ayıklar.'),
(2000324,68,20,20,9,'Kim, ‹‹Yüreğimi pak kıldım, 2 Günahımdan arındım›› diyebilir?'),
(2000325,68,20,20,10,'RAB hileli tartıdan da, hileli ölçüden de tiksinir.'),
(2000326,68,20,20,11,'Çocuk bile eylemleriyle kendini belli eder, 2 Yaptıkları pak ve doğru mu, değil mi, anlaşılır.'),
(2000327,68,20,20,12,'İşiten kulağı da gören gözü de 2 RAB yaratmıştır.'),
(2000328,68,20,20,13,'Uykuyu seversen yoksullaşırsın, 2 Uyanık durursan ekmeğin bol olur.'),
(2000329,68,20,20,14,'Alıcı, ‹‹İşe yaramaz, işe yaramaz›› der, 2 Ama alıp gittikten sonra aldığıyla övünür.'),
(2000330,68,20,20,15,'Bol bol altının, mücevherin olabilir, 2 Ama bilgi akıtan dudaklar daha değerlidir.'),
(2000331,68,20,20,16,'Tanımadığı birine kefil olanın giysisini al; 2 Bir yabancı için yapıyorsa bunu, 2 Giysisini rehin tut.'),
(2000332,68,20,20,17,'Hileyle kazanılan yiyecek insana tatlı gelir, 2 Ama sonra ağza dolan çakıl gibidir.'),
(2000333,68,20,20,18,'Tasarılarını danışarak yap, 2 Yöntemlere uyarak savaş.'),
(2000334,68,20,20,19,'Dedikoducu sır saklayamaz, 2 Bu nedenle ağzı gevşek olanla arkadaşlık etme.'),
(2000335,68,20,20,20,'Annesine ya da babasına sövenin 2 Işığı zifiri karanlıkta s��necek.'),
(2000336,68,20,20,21,'Tez elde edilen mirasın 2 Sonu bereketli olmaz.'),
(2000337,68,20,20,22,'‹‹Bu kötülüğü sana ödeteceğim›› deme; 2 RABbi bekle, O seni kurtarır.'),
(2000338,68,20,20,23,'RAB hileli tartıdan tiksinir, 2 Hileli teraziden hoşlanmaz.'),
(2000339,68,20,20,24,'İnsanın adımlarını RAB yönlendirir; 2 Öyleyse insan tuttuğu yolu nasıl anlayabilir?'),
(2000340,68,20,20,25,'Düşünmeden adakta bulunmak 2 Sakıncalıdır.'),
(2000341,68,20,20,26,'Bilge kral kötüleri ayıklar, 2 Harman döver gibi cezalandırır.'),
(2000342,68,20,20,27,'İnsanın ruhu RABbin ışığıdır, 2 İç varlığın derinliklerine işler.'),
(2000343,68,20,20,28,'Sevgi ve sadakat kralın güvencesidir. 2 Onun tahtını sağlamlaştıran sevgidir.'),
(2000344,68,20,20,29,'Gençlerin görkemi güçleri, 2 Yaşlıların onuru ağarmış saçlardır.'),
(2000345,68,20,20,30,'Yaralayan darbeler kötülüğü temizler, 2 Kötek iç varlığın derinliklerini paklar.'),
(2000346,68,20,21,1,'Kralın yüreği RABbin elindedir, 2 Kanaldaki su gibi onu istediği yöne çevirir.'),
(2000347,68,20,21,2,'İnsan izlediği her yolun doğru olduğunu sanır, 2 Ama niyetlerini tartan RABdir.'),
(2000348,68,20,21,3,'RAB kendisine kurban sunulmasından çok, 2 Doğruluğun ve adaletin yerine getirilmesini ister.'),
(2000349,68,20,21,4,'Küstah bakışlar ve kibirli yürek 2 Kötülerin çırası ve günahıdır.'),
(2000350,68,20,21,5,'Çalışkanın tasarıları hep bollukla, 2 Her türlü acelecilik hep yoklukla sonuçlanır.'),
(2000351,68,20,21,6,'Yalan dolanla yapılan servet, 2 Sis gibi geçicidir ve ölüm tuzağıdır.'),
(2000352,68,20,21,7,'Kötülerin zorbalığı kendilerini süpürüp götürür, 2 Çünkü doğru olanı yapmaya yanaşmazlar.'),
(2000353,68,20,21,8,'Suçlunun yolu dolambaçlı, 2 Pak kişinin yaptıklarıysa dosdoğrudur.'),
(2000354,68,20,21,9,'Kavgacı kadınla aynı evde oturmaktansa, 2 Damın köşesinde oturmak yeğdir.'),
(2000355,68,20,21,10,'Kötünün can attığı kötülüktür, 2 Hiç kimseye acımaz.'),
(2000356,68,20,21,11,'Alaycı cezalandırılınca bön kişi akıllanır, 2 Bilge olan öğretilenden bilgi kazanır.'),
(2000357,68,20,21,12,'Adil Olan, kötünün evini dikkatle gözler 2 Ve kötüleri yıkıma uğratır.'),
(2000358,68,20,21,13,'Yoksulun feryadına kulağını tıkayanın 2 Feryadına yanıt verilmeyecektir.'),
(2000359,68,20,21,14,'Gizlice verilen armağan öfkeyi, 2 Koyna sokuşturulan rüşvet de kızgın gazabı yatıştırır.'),
(2000360,68,20,21,15,'Hak yerine gelince doğru kişi sevinir, 2 Fesatçı dehşete düşer.'),
(2000361,68,20,21,16,'Sağduyudan uzaklaşan, 2 Kendini ölüler arasında bulur.'),
(2000362,68,20,21,17,'Zevkine düşkün olan yoksullaşır, 2 Şaraba ve zeytinyağına düşkün kişi de zengin olmaz.'),
(2000363,68,20,21,18,'Kötü kişi doğru kişinin fidyesidir, 2 Hain de dürüstün.'),
(2000364,68,20,21,19,'Çölde yaşamak, 2 Can sıkıcı ve kavgacı kadınla yaşamaktan yeğdir.'),
(2000365,68,20,21,20,'Bilgenin evi değerli eşya ve zeytinyağıyla doludur, 2 Akılsızsa malını har vurup harman savurur.'),
(2000366,68,20,21,21,'Doğruluğun ve sevginin ardından koşan, 2 Yaşam, gönenç ve onur bulur.'),
(2000367,68,20,21,22,'Bilge kişi güçlülerin kentine saldırıp 2 Güvendikleri kaleyi yıkar.'),
(2000368,68,20,21,23,'Ağzını ve dilini tutan 2 Başını beladan korur.'),
(2000369,68,20,21,24,'Gururlu, küstah ve alaycı: 2 Bunlar kas kas kasılan insanın adlarıdır.'),
(2000370,68,20,21,25,'Tembelin isteği onu ölüme götürür, 2 Çünkü elleri çalışmaktan kaçınır;'),
(2000371,68,20,21,26,'Bütün gün isteklerini sıralar durur, 2 Oysa doğru kişi esirgemeden verir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000372,68,20,21,27,'Kötülerin sunduğu kurban iğrençtir, 2 Hele bunu kötü niyetle sunarlarsa.'),
(2000373,68,20,21,28,'Yalancı tanık yok olur, 2 Dinlemeyi bilenin tanıklığıysa inandırıcıdır.'),
(2000374,68,20,21,29,'Kötü kişi kendine güçlü bir görünüm verir, 2 Erdemli insansa tuttuğu yoldan emindir.'),
(2000375,68,20,21,30,'RABbe karşı başarılı olabilecek 2 Bilgelik, akıl ve tasarı yoktur.'),
(2000376,68,20,21,31,'At savaş günü için hazır tutulur, 2 Ama zafer sağlayan RAB''dir.'),
(2000377,68,20,22,1,'İyi ad büyük servetten, 2 Saygınlık gümüş ve altından yeğdir.'),
(2000378,68,20,22,2,'Zenginle yoksulun ortak yönü şu: 2 Her ikisini de RAB yarattı.'),
(2000379,68,20,22,3,'İhtiyatlı kişi tehlikeyi görünce saklanır, 2 Bönse öne atılır ve zarar görür.'),
(2000380,68,20,22,4,'Alçakgönüllülüğün ve RAB korkusunun ödülü, 2 Zenginlik, onur ve yaşamdır.'),
(2000381,68,20,22,5,'Kötünün yolu diken ve tuzakla doludur. 2 Canını korumak isteyen bunlardan uzak durur.'),
(2000382,68,20,22,6,'Çocuğu tutması gereken yola göre yetiştir, 2 Yaşlandığında o yoldan ayrılmaz.'),
(2000383,68,20,22,7,'Zengin yoksullara egemen olur, 2 Borç alan borç verenin kulu olur.'),
(2000384,68,20,22,8,'Fesat eken dert biçer, 2 Gazabının değneği yok olur.'),
(2000385,68,20,22,9,'Cömert olan kutsanır, 2 Çünkü yemeğini yoksullarla paylaşır.'),
(2000386,68,20,22,10,'Alaycıyı kov, kavga biter; 2 Çekişme ve aşağılamalar da sona erer.'),
(2000387,68,20,22,11,'Yürek temizliğini ve güzel sözleri seven, 2 Kralın dostluğunu kazanır.'),
(2000388,68,20,22,12,'RAB bilgiyi gözetip korur, 2 Hainin sözlerini ise altüst eder.'),
(2000389,68,20,22,13,'Tembel der ki, ‹‹Dışarda aslan var, 2 Sokağa çıksam beni parçalar.››'),
(2000390,68,20,22,14,'Sokak kadınının ağzı dipsiz çukur gibidir, 2 RABbin gazabına uğrayan oraya düşer.'),
(2000391,68,20,22,15,'Akılsızlık çocuğun öz yapısındadır, 2 Değnekle terbiye edilirse akılsızlıktan uzaklaşır.'),
(2000392,68,20,22,16,'Servetini büyütmek için yoksulu ezenle 2 Zengine armağan verenin sonu yoksulluktur.'),
(2000393,68,20,22,17,'Kulak ver, bilgelerin sözlerini dinle, 2 Öğrettiğimi zihnine işle.'),
(2000394,68,20,22,18,'Sözlerimi yüreğinde saklarsan mutlu olursun, 2 Onlar hep hazır olsun dudaklarında.'),
(2000395,68,20,22,19,'RABbe güvenmen için 2 Bugün bunları sana, evet sana da bildiriyorum.'),
(2000396,68,20,22,20,'Senin için otuz söz yazdım, 2 Bilgi ve öğüt sözleri...'),
(2000397,68,20,22,21,'Öyle ki, güvenilir, doğru sözleri bilesin, 2 Böylece seni gönderene güvenilir yanıt verebilesin.'),
(2000398,68,20,22,22,'Yoksulu, yoksul olduğu için soymaya kalkma, 2 Düşkünü mahkemede ezme. Masoretik metinde geçmemektedir.'),
(2000399,68,20,22,23,'Çünkü onların davasını RAB yüklenecek 2 Ve onları soyanların canını alacak.'),
(2000400,68,20,22,24,'Huysuz kişiyle arkadaşlık etme; 2 Tez öfkelenenle yola çıkma.'),
(2000401,68,20,22,25,'Yoksa onun yollarına alışır, 2 Kendini tuzağa düşmüş bulursun.'),
(2000402,68,20,22,26,'El sıkışıp 2 Başkasının borcuna kefil olmaktan kaçın.'),
(2000403,68,20,22,27,'Ödeyecek paran olmazsa, 2 Altındaki döşeğe bile el koyarlar.'),
(2000404,68,20,22,28,'Atalarının belirlediği 2 Eski sınır taşlarının yerini değiştirme.'),
(2000405,68,20,22,29,'İşinde usta birini görüyor musun? 2 Öylesi sıradan kişilere değil, 2 Krallara bile hizmet eder.'),
(2000406,68,20,23,1,'Bir önderle yemeğe oturduğunda 2 Önüne konulana dikkat et.'),
(2000407,68,20,23,2,'İştahına yenilecek olursan, 2 Daya bıçağı kendi boğazına.'),
(2000408,68,20,23,3,'Onun lezzetli yemeklerini çekmesin canın, 2 Böyle yemeğin ardında hile olabilir.'),
(2000409,68,20,23,4,'Zengin olmak için didinip durma, 2 Çıkar bunu aklından.'),
(2000410,68,20,23,5,'Servet göz açıp kapayana dek yok olur, 2 Kanatlanıp kartal gibi göklere uçar.'),
(2000411,68,20,23,6,'Cimrinin verdiği yemeği yeme, 2 Lezzetli yemeklerini çekmesin canın.'),
(2000412,68,20,23,7,'Çünkü yediğin her şeyin hesabını tutar, 2 ‹‹Ye, iç›› der sana, 2 Ama yüreği senden yana değildir.'),
(2000413,68,20,23,8,'Yediğin azıcık yemeği kusarsın, 2 Söylediğin güzel sözler de boşa gider.'),
(2000414,68,20,23,9,'Akılsıza öğüt vermeye kalkma, 2 Çünkü senin sözlerindeki sağduyuyu küçümser.'),
(2000415,68,20,23,10,'Eski sınır taşlarının yerini değiştirme, 2 Öksüzlerin toprağına el sürme.'),
(2000416,68,20,23,11,'Çünkü onların Velisi güçlüdür 2 Ve onların davasını sana karşı O yürütür. kurtarıcılığı vurguluyor.'),
(2000417,68,20,23,12,'Uyarıları zihnine işle, 2 Bilgi dolu sözlere kulak ver.'),
(2000418,68,20,23,13,'Çocuğunu terbiye etmekten geri kalma, 2 Onu değnekle dövsen de ölmez.'),
(2000419,68,20,23,14,'Onu değnekle döversen, 2 Canını ölüler diyarından kurtarırsın.'),
(2000420,68,20,23,15,'Oğlum, bilge yürekli olursan, 2 Benim yüreğim de sevinir.'),
(2000421,68,20,23,16,'Dudakların doğru konuştuğunda 2 Gönlüm de coşar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000422,68,20,23,17,'Günahkârlara imrenmektense, 2 Sürekli RAB korkusunda yaşa.'),
(2000423,68,20,23,18,'Böylece bir geleceğin olur 2 Ve umudun boşa çıkmaz.'),
(2000424,68,20,23,19,'Oğlum, dinle ve bilge ol, 2 Yüreğini doğru yolda tut.'),
(2000425,68,20,23,20,'Aşırı şarap içenlerle, 2 Ete düşkün oburlarla arkadaşlık etme.'),
(2000426,68,20,23,21,'Çünkü ayyaş ve obur kişi yoksullaşır, 2 Uyuşukluk da insana paçavra giydirir.'),
(2000427,68,20,23,22,'Sana yaşam veren babanın sözlerine kulak ver, 2 Yaşlandığı zaman anneni hor görme.'),
(2000428,68,20,23,23,'Gerçeği satın al ve satma; 2 Bilgeliği, terbiyeyi, aklı da.'),
(2000429,68,20,23,24,'Doğru kişinin babası coştukça coşar, 2 Bilgece davranan oğulun babası sevinir.'),
(2000430,68,20,23,25,'Annenle baban seninle coşsun, 2 Seni doğuran sevinsin.'),
(2000431,68,20,23,26,'Oğlum, beni yürekten dinle, 2 Gözünü gittiğim yoldan ayırma.'),
(2000432,68,20,23,27,'Çünkü fahişe derin bir çukur, 2 Ahlaksız kadın dar bir kuyudur.'),
(2000433,68,20,23,28,'Evet, soyguncu gibi pusuda bekler 2 Ve birçok erkeği yoldan çıkarır.'),
(2000434,68,20,23,29,'Ah çeken kim? Vah çeken kim? 2 Kimdir çekişip duran? 2 Yakınan kim? Boş yere yaralanan kim? 2 Gözleri kanlı olan kim?'),
(2000435,68,20,23,30,'İçmeye oturup kalkamayanlar, 2 Karışık şarapları denemeye gidenlerdir.'),
(2000436,68,20,23,31,'Şarabın kızıl rengine, 2 Kadehte ışımasına, 2 Boğazdan aşağı süzülüvermesine bakma.'),
(2000437,68,20,23,32,'Sonunda yılan gibi ısırır, 2 Engerek gibi sokar.'),
(2000438,68,20,23,33,'Gözlerin garip şeyler görür, 2 Aklından ahlaksızlıklar geçer.'),
(2000439,68,20,23,34,'Kendini kâh denizin ortasında, 2 Kâh gemi direğinin tepesinde yatıyor sanırsın.'),
(2000440,68,20,23,35,'‹‹Dövdüler beni ama incinmedim, 2 Vurdular ama farketmedim›› dersin, 2 ‹‹Yeniden içmek için ne zaman ayılacağım?››'),
(2000441,68,20,24,1,'Kötülere imrenme, 2 Onlarla birlikte olmayı isteme.'),
(2000442,68,20,24,2,'Çünkü yürekleri zorbalık tasarlar, 2 Dudakları belalardan söz eder.'),
(2000443,68,20,24,3,'Ev bilgelikle yapılır, 2 Akılla pekiştirilir.'),
(2000444,68,20,24,4,'Bilgi sayesinde odaları 2 Her türlü değerli, güzel eşyayla dolar.'),
(2000445,68,20,24,5,'Bilgelik güçten, 2 Bilgi kaba kuvvetten üstündür. üstündür›› (bkz. Septuaginta), Masoretik metin ‹‹Bilge güçlü olur, bilgi sahibi gücünü artırır.››'),
(2000446,68,20,24,6,'Savaşmak için yöntem, 2 Zafer kazanmak için birçok danışman gerekli.'),
(2000447,68,20,24,7,'Ahmak için bilgelik ulaşılamayacak kadar yüksektir, 2 Kent kurulunda ağzını açamaz.'),
(2000448,68,20,24,8,'Kötülük tasarlayan kişi 2 Düzenbaz olarak bilinecektir.'),
(2000449,68,20,24,9,'Ahmakça tasarılar günahtır, 2 Alaycı kişiden herkes iğrenir.'),
(2000450,68,20,24,10,'Sıkıntılı günde cesaretini yitirirsen, 2 Gücün kıt demektir.'),
(2000451,68,20,24,11,'Ölüm tehlikesi içinde olanları kurtar, 2 Ölmek üzere olanları esirge.'),
(2000452,68,20,24,12,'‹‹İşte bunu bilmiyordum›› desen de, 2 İnsanın yüreğindekini bilen sezmez mi? 2 Senin canını koruyan anlamaz mı? 2 Ödetmez mi herkese yaptığını?'),
(2000453,68,20,24,13,'Oğlum, bal ye, çünkü iyidir, 2 Süzme bal damağa tatlı gelir.'),
(2000454,68,20,24,14,'Bilgelik de canın için öyledir, bilmiş ol. 2 Bilgeliği bulursan bir geleceğin olur 2 Ve umudun boşa çıkmaz.'),
(2000455,68,20,24,15,'Ey kötü adam, doğru kişinin evine karşı pusuya yatma, 2 Konutunu yıkmaya kalkma.'),
(2000456,68,20,24,16,'Çünkü doğru kişi yedi kez düşse yine kalkar, 2 Ama kötüler felakette yıkılır.'),
(2000457,68,20,24,17,'Düşmanın düşüşüne keyiflenme, 2 Sendelemesine sevinme.'),
(2000458,68,20,24,18,'Yoksa RAB görür ve hoşnut kalmaz 2 Ve düşmanına duyduğu öfke yatışır.'),
(2000459,68,20,24,19,'Kötülük edenlere kızıp üzülme, 2 Onlara özenme.'),
(2000460,68,20,24,20,'Çünkü kötülerin geleceği yok, 2 Çırası sönecek onların.'),
(2000461,68,20,24,21,'Oğlum, RABbe ve krala saygı göster, 2 Onlara başkaldıranlarla arkadaşlık etme.'),
(2000462,68,20,24,22,'Çünkü onlar ansızın felakete uğrar, 2 İnsanın başına ne belalar getireceklerini kim bilir?'),
(2000463,68,20,24,23,'Şunlar da bilgelerin sözleridir: 2 Yargılarken yan tutmak iyi değildir.'),
(2000464,68,20,24,24,'Kötüye, ‹‹Suçsuzsun›› diyen yargıcı 2 Halklar lanetler, uluslar kınar.'),
(2000465,68,20,24,25,'Ne mutlu suçluyu mahkûm edene! 2 Herkes onu candan kutlar.'),
(2000466,68,20,24,26,'Dürüst yanıt 2 Gerçek dostluğun işaretidir. ‹‹Dürüst yanıt veren dudakları öper.››'),
(2000467,68,20,24,27,'İlkin dışardaki işini bitirip tarlanı hazırla, 2 Ondan sonra evini yap.'),
(2000468,68,20,24,28,'Başkalarına karşı nedensiz tanıklık etme 2 Ve dudaklarınla aldatma.'),
(2000469,68,20,24,29,'‹‹Bana yaptığını ben de ona yapacağım, 2 Ödeteceğim bana yaptığını›› deme.'),
(2000470,68,20,24,30,'Tembelin tarlasından, 2 Sağduyudan yoksun kişinin bağından geçtiğimde'),
(2000471,68,20,24,31,'Her yanı dikenlerin, otların 2 Kapladığını gördüm; 2 Taş duvar da yıkılmıştı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000472,68,20,24,32,'Gördüklerimi derin derin düşündüm, 2 Seyrettiklerimden ibret aldım.'),
(2000473,68,20,24,33,'‹‹Biraz kestireyim, biraz uyuklayayım, 2 Ellerimi kavuşturup şöyle bir uyuyayım›› demeye kalmadan,'),
(2000474,68,20,24,34,'Yokluk bir haydut gibi, 2 Yoksulluk bir akıncı gibi gelir üzerine.'),
(2000475,68,20,25,1,'Bundan sonrakiler de Süleymanın özdeyişleridir. 2 Bunları Yahuda Kralı Hizkiyanın adamları derledi.'),
(2000476,68,20,25,2,'Tanrıyı gizli tuttuğu şeyler için, 2 Krallarıysa açığa çıkardıkları için yüceltiriz.'),
(2000477,68,20,25,3,'Göğün yüksekliği, yerin derinliği gibi, 2 Kralların aklından geçen de kestirilemez.'),
(2000478,68,20,25,4,'Cürufu gümüşten ayırınca, 2 Kuyumcunun işleyeceği madde kalır.'),
(2000479,68,20,25,5,'Kötüleri kralın huzurundan uzaklaştırırsan 2 Kralın tahtı adaletle pekişir.'),
(2000480,68,20,25,6,'Kralın önünde kendini yüceltme, 2 Önemli kişiler arasında yer edinmeye çalışma.'),
(2000481,68,20,25,7,'Çünkü kralın seni bir soylunun önünde alaşağı etmesindense, 2 Sana, ‹‹Yukarıya gel›› demesi yeğdir.'),
(2000482,68,20,25,8,'Gördüklerinle hemencecik mahkemeye başvurma; 2 Çünkü başkası seni utandırabilir, 2 Sonra ne yapacağını bilemezsin.'),
(2000483,68,20,25,9,'Davanı doğrudan komşunla gör; 2 Başkasının sırrını açıklama.'),
(2000484,68,20,25,10,'Yoksa işiten seni utandırabilir 2 Ve bu kötü ün yakanı bırakmaz.'),
(2000485,68,20,25,11,'Yerinde söylenen söz, 2 Gümüş oymalardaki altın elmafö gibidir.'),
(2000486,68,20,25,12,'Altın küpe ya da altın bir süs neyse, 2 Dinleyen kulak için bilgenin azarlaması da öyledir.'),
(2000487,68,20,25,13,'Hasatta kar serinliği nasılsa, 2 Güvenilir ulak da kendisini gönderenler için öyledir. 2 Böyle biri efendilerinin canına can katar.'),
(2000488,68,20,25,14,'Yağmursuz bulut ve yel nasılsa, 2 Vermediği armağanla övünen kişi de öyledir.'),
(2000489,68,20,25,15,'Sabırla bir hükümdar bile ikna edilir, 2 Tatlı dil en güçlü direnci kırar.'),
(2000490,68,20,25,16,'Bal buldun mu yeteri kadar ye, 2 Fazla doyarsan kusarsın.'),
(2000491,68,20,25,17,'Başkalarının evine seyrek git, 2 Yoksa onları bezdirir, nefretini kazanırsın.'),
(2000492,68,20,25,18,'Başkasına karşı yalancı tanıklık eden 2 Topuz, kılıç ya da sivri ok gibidir.'),
(2000493,68,20,25,19,'Sıkıntılı günde haine güvenmek, 2 Çürük dişe ya da sakat ayağa güvenmek gibidir.'),
(2000494,68,20,25,20,'Dertli kişiye ezgi söylemek, 2 Soğuk günde giysilerini üzerinden almaya, 2 Ya da sodaya sirke katmaya benzer.'),
(2000495,68,20,25,21,'Düşmanın acıkmışsa doyur, 2 Susamışsa su ver.'),
(2000496,68,20,25,22,'Bunu yapmakla onu utanca boğarsın 2 Ve RAB seni ödüllendirir.'),
(2000497,68,20,25,23,'Kuzeyden esen rüzgar nasıl yağmur getirirse, 2 İftiracı dil de öfkeli bakışlara yol açar.'),
(2000498,68,20,25,24,'Kavgacı kadınla aynı evde oturmaktansa, 2 Damın köşesinde oturmak yeğdir.'),
(2000499,68,20,25,25,'Susamış kişi için soğuk su neyse, 2 Uzak ülkeden gelen iyi haber de öyledir.'),
(2000500,68,20,25,26,'Kötünün önünde pes eden doğru kişi, 2 Suyu bulanmış pınar, kirlenmiş kuyu gibidir.'),
(2000501,68,20,25,27,'Fazla bal yemek iyi değildir; 2 Hep yüceltilmeyi beklemek de...'),
(2000502,68,20,25,28,'Kendini denetleyemeyen kişi 2 Yıkılmış sursuz kent gibidir.'),
(2000503,68,20,26,1,'Yaz ortasında kar, hasatta yağmur uygun olmadığı gibi, 2 Akılsıza da onur yakışmaz.'),
(2000504,68,20,26,2,'Öteye beriye uçuşan serçe 2 Ve kırlangıç gibi, 2 Hak edilmemiş lanet de tutmaz.'),
(2000505,68,20,26,3,'Ata kırbaç, eşeğe gem, 2 Akılsızın sırtına da değnek gerek.'),
(2000506,68,20,26,4,'Akılsıza ahmaklığına göre karşılık verme, 2 Yoksa sen de onun düzeyine inersin.'),
(2000507,68,20,26,5,'Akılsıza ahmaklığına uygun karşılık ver, 2 Yoksa kendini bilge sanır.'),
(2000508,68,20,26,6,'Akılsızın eliyle haber gönderen, 2 Kendi ayaklarını kesen biri gibi, 2 Kendine zarar verir.'),
(2000509,68,20,26,7,'Akılsızın ağzında özdeyiş, 2 Kötürümün sarkan bacakları gibidir.'),
(2000510,68,20,26,8,'Akılsızı onurlandırmak, 2 Taşı sapana bağlamak gibidir.'),
(2000511,68,20,26,9,'Sarhoşun elindeki dikenli dal ne ise, 2 Akılsızın ağzında özdeyiş de odur.'),
(2000512,68,20,26,10,'Oklarını gelişigüzel fırlatan okçu neyse, 2 Yoldan geçen akılsızı ya da sarhoşu ücretle tutan da öyledir.'),
(2000513,68,20,26,11,'Ahmaklığını tekrarlayan akılsız, 2 Kusmuğuna dönen köpek gibidir.'),
(2000514,68,20,26,12,'Kendini bilge gören birini tanıyor musun? 2 Akılsız bile ondan daha umut vericidir.'),
(2000515,68,20,26,13,'Tembel, ‹‹Yolda aslan var, 2 Sokaklarda aslan dolaşıyor›› der.'),
(2000516,68,20,26,14,'Menteşeleri üzerinde dönen kapı gibi, 2 Tembel de yatağında döner durur.'),
(2000517,68,20,26,15,'Tembel elini sahana daldırır, 2 Yeniden ağzına götürmeye üşenir.'),
(2000518,68,20,26,16,'Tembel kendini, 2 Akıllıca yanıt veren yedi kişiden daha bilge sanır.'),
(2000519,68,20,26,17,'Kendini ilgilendirmeyen bir kavgaya bulaşan kişi, 2 Yoldan geçen köpeği kulaklarından tutana benzer.'),
(2000520,68,20,26,18,'Ateşli ve öldürücü oklar savuran bir deli neyse, 2 Komşusunu aldatıp, ‹‹Şaka yapıyordum›› 2 Diyen de öyledir.'),
(2000521,68,20,26,20,'Odun bitince ateş söner, 2 Dedikoducu yok olunca kavga diner.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000522,68,20,26,21,'Kor için kömür, ateş için odun neyse, 2 Çekişmeyi alevlendirmek için kavgacı da öyledir.'),
(2000523,68,20,26,22,'Dedikodu tatlı lokma gibidir, 2 İnsanın ta içine işler.'),
(2000524,68,20,26,23,'Okşayıcı dudaklarla kötü yürek, 2 Sırlanmış toprak kaba benzer.'),
(2000525,68,20,26,24,'Yüreği nefret dolu kişi sözleriyle niyetini gizlemeye çalışır, 2 Ama içi hile doludur.'),
(2000526,68,20,26,25,'Güzel sözlerine kanma, 2 Çünkü yüreğinde yedi iğrenç şey vardır.'),
(2000527,68,20,26,26,'Nefretini hileyle örtse bile, 2 Kötülüğü toplumun önünde ortaya çıkar.'),
(2000528,68,20,26,27,'Başkasının kuyusunu kazan içine kendi düşer, 2 Taşı yuvarlayan altında kalır.'),
(2000529,68,20,26,28,'Yalancı dil incittiği kişilerden nefret eder, 2 Yaltaklanan ağızdan yıkım gelir.'),
(2000530,68,20,27,1,'Yarınla övünme, 2 Çünkü ne getireceğini bilemezsin.'),
(2000531,68,20,27,2,'Seni kendi ağzın değil, başkaları övsün, 2 Kendi dudakların değil, yabancı övsün.'),
(2000532,68,20,27,3,'Taş ağırdır, kum bir yüktür, 2 Ama ahmağın kışkırtması ikisinden de ağırdır.'),
(2000533,68,20,27,4,'Öfke zalim, hiddet azgındır, 2 Ama kıskançlığa kim dayanabilir?'),
(2000534,68,20,27,5,'Açık bir azar, 2 Gizli tutulan sevgiden iyidir.'),
(2000535,68,20,27,6,'Düşmanın öpücükleri aldatıcıdır, 2 Ama dostun seni iyiliğin için yaralar.'),
(2000536,68,20,27,7,'Tok insanın canı balı bile çekmez, 2 Aç kişiye en acı şey tatlı gelir.'),
(2000537,68,20,27,8,'Yuvasından uzak kalan kuş nasılsa, 2 Yurdundan uzak kalan insan da öyledir.'),
(2000538,68,20,27,9,'Güzel koku ve buhur canı ferahlatır, 2 Dostun verdiği öğüt insana tatlı gelir.'),
(2000539,68,20,27,10,'Kendi dostunu da babanın dostunu da bırakma 2 Ve felakete uğradığın gün kardeşinin evine gitme; 2 Yakın komşun uzaktaki kardeşten yeğdir.'),
(2000540,68,20,27,11,'Oğlum, bilgece davran ki yüreğim sevinsin, 2 Beni ayıplayana yanıt vereyim.'),
(2000541,68,20,27,12,'İhtiyatlı kişi tehlikeyi görünce saklanır, 2 Bönse öne atılır ve zarar görür.'),
(2000542,68,20,27,13,'Tanımadığı birine kefil olanın giysisini al; 2 Bir yabancı için yapıyorsa bunu, 2 Giysisini rehin tut.'),
(2000543,68,20,27,14,'Sabah sabah komşuya verilen gürültülü bir selam 2 Küfür sayılır.'),
(2000544,68,20,27,15,'Kavgacı kadının dırdırı 2 Yağmurlu günde damlaların dinmeyen sesi gibidir.'),
(2000545,68,20,27,16,'Böyle bir kadını dizginlemeye kalkmak, 2 Rüzgarı ya da yağı avuçta tutmaya çalışmak gibidir.'),
(2000546,68,20,27,17,'Demir demiri biler, 2 İnsan da insanı...'),
(2000547,68,20,27,18,'İncir ağacını budayan meyvesini yer, 2 Efendisine hizmet eden onurlandırılır.'),
(2000548,68,20,27,19,'Su görüntümüzü nasıl yansıtıyorsa, 2 Yürek de insanın içini yansıtır.'),
(2000549,68,20,27,20,'Ölüm ve yıkım diyarı insana doymaz, 2 İnsanın gözü de hiç doymaz.'),
(2000550,68,20,27,21,'Altın ocakta, gümüş potada sınanır, 2 İnsansa aldığı övgüyle sınanır.'),
(2000551,68,20,27,22,'Ahmağı buğdayla birlikte dibekte tokmakla dövsen bile, 2 Ahmaklığından kurtulmaz.'),
(2000552,68,20,27,23,'Davarına iyi bak, 2 Sığırlarına dikkat et.'),
(2000553,68,20,27,24,'Çünkü zenginlik kalıcı değildir 2 Ve taç kuşaktan kuşağa geçmez.'),
(2000554,68,20,27,25,'Çayır biçilince, yeni çimen çıkınca, 2 Dağlardaki otlar toplanınca,'),
(2000555,68,20,27,26,'Kuzular seni giydirir, 2 Tekeler tarlanın bedeli olur.'),
(2000556,68,20,27,27,'Keçilerin sütü yalnız seni değil, 2 Ev halkını, hizmetçilerini de doyurmaya yeter.'),
(2000557,68,20,28,1,'Kötü kişi kendisini kovalayan olmasa bile kaçar, 2 Doğrularsa genç aslan gibi yüreklidir.'),
(2000558,68,20,28,2,'Ayaklanan ülke çok başlı olur, 2 Ama akıllı, bilgili kişi düzeni sağlar.'),
(2000559,68,20,28,3,'Yoksulu ezen yoksul, 2 Ürünü harap eden sağanak yağmur gibidir.'),
(2000560,68,20,28,4,'Yasayı terk eden kötüyü över, 2 Yerine getirense kötüye karşı çıkar.'),
(2000561,68,20,28,5,'Kötüler adaletten anlamaz, 2 RABbe yönelenlerse her yönüyle anlar.'),
(2000562,68,20,28,6,'Dürüst bir yoksul olmak, 2 Yolsuzlukla zengin olmaktan yeğdir.'),
(2000563,68,20,28,7,'Kutsal Yasayı yerine getiren çocuk akıllıdır, 2 Oburlarla arkadaşlık edense babasını utandırır.'),
(2000564,68,20,28,8,'Faiz ve tefecilikle malına mal katan kişi, 2 Bunu yoksullara acıyan için biriktirir.'),
(2000565,68,20,28,9,'Yasaya kulağını tıkayanın 2 Duası da iğrençtir.'),
(2000566,68,20,28,10,'Dürüst kişileri kötü yola saptıran 2 Kendi kazdığı çukura düşer. 2 İyiliği, özü sözü bir olanlar miras alacak.'),
(2000567,68,20,28,11,'Zengin kendini bilge sanır, 2 Ama akıllı yoksul onun içini okur.'),
(2000568,68,20,28,12,'Doğruların zaferi coşkuyla kutlanır, 2 Ama kötüler egemen olunca insan kaçacak yer arar.'),
(2000569,68,20,28,13,'Günahlarını gizleyen başarılı olmaz, 2 İtiraf edip bırakansa merhamet bulur.'),
(2000570,68,20,28,14,'Günahtan çekinen ne mutludur! 2 İnatçılık edense belaya düşer.'),
(2000571,68,20,28,15,'Yoksul halkı yöneten kötü kişi 2 Kükreyen aslan, saldırgan ayı gibidir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000572,68,20,28,16,'Gaddar önderin aklı kıttır; 2 Haksız kazançtan nefret edense uzun ömürlü olur.'),
(2000573,68,20,28,17,'Adam öldürmekten vicdan azabı çeken, mezara dek kaçacaktır; 2 Kimse ona yardım etmesin.'),
(2000574,68,20,28,18,'Alnı ak yaşayan kurtulur, 2 Yolsuzluk yapan ansızın yıkıma uğrar.'),
(2000575,68,20,28,19,'Toprağını işleyenin ekmeği bol olur, 2 Hayal peşinde koşansa yoksulluğa doyar.'),
(2000576,68,20,28,20,'Güvenilir kişi bolluğa erer, 2 Zengin olmaya can atansa beladan kurtulamaz.'),
(2000577,68,20,28,21,'Hatır gözetmek iyi değildir, 2 Çünkü insan bir lokma ekmek için bile suç işler.'),
(2000578,68,20,28,22,'Cimri servet peşinde koşar, 2 Yoksulluğa uğrayacağını düşünmez.'),
(2000579,68,20,28,23,'Başkasını azarlayan sonunda 2 Pohpohlayandan daha çok beğeni kazanır.'),
(2000580,68,20,28,24,'Annesini ya da babasını soymayı günah saymayan, 2 Haydutla birdir.'),
(2000581,68,20,28,25,'Açgözlü kavga çıkarır, 2 RABbe güvenense bolluk içinde yaşar.'),
(2000582,68,20,28,26,'Kendine güvenen akılsızdır, 2 Bilgece davranan güvenlikte olur.'),
(2000583,68,20,28,27,'Yoksula verenin eksiği olmaz, 2 Yoksulu görmezden gelense bir sürü lanete uğrar.'),
(2000584,68,20,28,28,'Kötüler egemen olunca insan kaçacak yer arar, 2 Ama kötüler yok olunca doğrular çoğalır.'),
(2000585,68,20,29,1,'Defalarca azarlandığı halde dikbaşlılık eden, 2 Ansızın yıkıma uğrayacak, çare yok.'),
(2000586,68,20,29,2,'Doğru kişiler çoğalınca halk sevinir, 2 Kötü kişi hükümdar olunca halk inler.'),
(2000587,68,20,29,3,'Bilgeliği seven babasını sevindirir, 2 Fahişelerle dostluk eden malını yitirir.'),
(2000588,68,20,29,4,'Adaletle yöneten kral ülkesini ayakta tutar, 2 Ağır vergiler koyansa çökertir.'),
(2000589,68,20,29,5,'Başkasını pohpohlayan kişi, 2 Ona tuzak kurar.'),
(2000590,68,20,29,6,'Kötünün başkaldırısı kendine tuzak olur, 2 Doğru kişiyse ezgi söyler ve sevinir.'),
(2000591,68,20,29,7,'Doğru kişi yoksulların hakkını verir, 2 Kötü kişi hak hukuk nedir bilmez.'),
(2000592,68,20,29,8,'Alaycı kişiler kentleri bile karıştırır, 2 Bilgelerse öfkeyi yatıştırır.'),
(2000593,68,20,29,9,'Bilge kişiyle davası olan ahmak 2 Kızar, alay eder ve rahat vermez.'),
(2000594,68,20,29,10,'Kana susamışlar dürüst kişiden nefret eder, 2 Doğrularsa onun canını korur.'),
(2000595,68,20,29,11,'Akılsız hep patlamaya hazırdır, 2 Bilgeyse öfkesini dizginler.'),
(2000596,68,20,29,12,'Hükümdar yalana kulak verirse, 2 Bütün görevlileri de kötü olur.'),
(2000597,68,20,29,13,'Zorbayla yoksulun ortak bir noktası var: 2 İkisinin de gözünü açan RABdir.'),
(2000598,68,20,29,14,'Yoksulları adaletle yöneten kralın 2 Tahtı hep güvenlikte olur.'),
(2000599,68,20,29,15,'Değnekle terbiye bilgelik kazandırır, 2 Kendi haline bırakılan çocuksa annesini utandırır.'),
(2000600,68,20,29,16,'Kötüler çoğalınca başkaldırı da çoğalır, 2 Ama doğrular onların düşüşünü görecektir.'),
(2000601,68,20,29,17,'Oğlunu terbiye et, o da sana huzur verecek 2 Ve gönlünü hoşnut edecektir.'),
(2000602,68,20,29,18,'Tanrısal esinden yoksun olan halk 2 Sınır tanımaz olur. 2 Ne mutlu Kutsal Yasayı yerine getirene!'),
(2000603,68,20,29,19,'Köle salt sözle terbiye edilemez, 2 Çünkü anlasa da kulak asmaz.'),
(2000604,68,20,29,20,'Sözünü tartmadan konuşan birini tanıyor musun? 2 Akılsızın durumu bile onunkinden daha umut vericidir.'),
(2000605,68,20,29,21,'Çocukluğundan beri kölesini şımartan, 2 Sonunda cezasını çeker.'),
(2000606,68,20,29,22,'Öfkeli kişi çekişme yaratır, 2 Huysuz kişinin başkaldırısı eksik olmaz.'),
(2000607,68,20,29,23,'Kibir insanı küçük düşürür, 2 Alçakgönüllülükse onur kazandırır.'),
(2000608,68,20,29,24,'Hırsızla ortak olanın düşmanı kendisidir, 2 Mahkemede yemin etse de bildiğini söylemez.'),
(2000609,68,20,29,25,'İnsandan korkmak tuzaktır, 2 Ama RABbe güvenen güvenlikte olur.'),
(2000610,68,20,29,26,'Hükümdarın gözüne girmek isteyen çoktur, 2 Ama RABdir insana adalet sağlayan.'),
(2000611,68,20,29,27,'Doğrular haksızlardan iğrenir, 2 Kötüler de dürüst yaşayanlardan.'),
(2000612,68,20,30,1,'Massalı Yake oğlu Agurun sözleri: 2 Bu adam şöyle diyor: 2 ‹‹Yoruldum, ey Tanrım, yoruldum ve tükendim. ve tükendim› ›› ya da ‹‹Bu adam İtiele, İtiele ve Ukkala şöyle diyor››.'),
(2000613,68,20,30,2,'Gerçekten ben insanların en cahiliyim, 2 Bende insan aklı yok.'),
(2000614,68,20,30,3,'Bilgeliği öğrenmedim, 2 Kutsal Olana ilişkin bilgiden de yoksunum.'),
(2000615,68,20,30,4,'Kim göklere çıkıp indi? 2 Kim yeli avuçlarında topladı? 2 Suları giysisiyle sarıp sarmalayan kim? 2 Kim belirledi dünyanın sınırlarını? 2 Adı nedir, oğlunun adı nedir, biliyorsan söyle!'),
(2000616,68,20,30,5,'Tanrının her sözü güvenilirdir, 2 O kendisine sığınan herkese kalkandır.'),
(2000617,68,20,30,6,'Onun sözüne bir şey katma, 2 Yoksa seni azarlar, yalancı çıkarsın.'),
(2000618,68,20,30,7,'Ey Tanrı, iki şey diledim senden: 2 Ben ölmeden bunları esirgeme benden.'),
(2000619,68,20,30,8,'Sahtekârlığı, yalanı benden uzak tut, 2 Bana ne yoksulluk ne de zenginlik ver; 2 Payıma düşen ekmeği ver, yeter.'),
(2000620,68,20,30,9,'Yoksa bolluktan, ‹Kimmiş RAB?› diye seni yadsır, 2 Ya da yoksulluktan çalar 2 Ve Tanrımın adını lekelemiş olurum.'),
(2000621,68,20,30,10,'‹‹Köleyi efendisine çekiştirme, 2 Yoksa sana lanet eder, sen de suçlu çıkarsın.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000622,68,20,30,11,'Öyleleri var ki, babalarına lanet eder, 2 Annelerine değer vermezler.'),
(2000623,68,20,30,12,'Öyleleri var ki, kendilerini tertemiz sanırlar, 2 Oysa kötülüklerinden arınmış değiller.'),
(2000624,68,20,30,13,'Öyleleri var ki, kendilerinden üstün kimse yok sanır, 2 Herkese tepeden bakarlar.'),
(2000625,68,20,30,14,'Öyleleri var ki, dişleri kılıç, çeneleri bıçaktır, 2 Mazlumlarla yoksulları yutup yeryüzünden yok ederler.'),
(2000626,68,20,30,15,'Sülüğün iki kızı vardır, adları ‹Ver, ver›dir. 2 Hiç doymayan üç şey, 2 ‹Yeter› demeyen dört şey vardır:'),
(2000627,68,20,30,16,'Ölüler diyarı, kısır rahim, 2 Suya doymayan toprak ve ‹Yeter› demeyen ateş.'),
(2000628,68,20,30,17,'Babasıyla alay edenin, annesinin sözünü hor görenin 2 Gözünü vadideki kargalar oyacak; 2 O akbabalara yem olacak.'),
(2000629,68,20,30,18,'Aklımın ermediği üç şey, 2 Anlamadığım dört şey var:'),
(2000630,68,20,30,19,'Kartalın gökyüzünde, 2 Yılanın kayada, 2 Geminin denizde izlediği yol 2 Ve erkeğin genç kızla tuttuğu yol.'),
(2000631,68,20,30,20,'Zina eden kadının yolu da şöyledir: 2 Yer, ağzını siler, 2 Sonra da, ‹Suç işlemedim› der.'),
(2000632,68,20,30,21,'Yeryüzü üç şeyin altında sarsılır; 2 Katlanamadığı dört şey vardır:'),
(2000633,68,20,30,22,'Kölenin kral olması, 2 Budalanın doyması,'),
(2000634,68,20,30,23,'Nefret edilen kadının evlenmesi 2 Ve hizmetçinin hanımının yerine geçmesi.'),
(2000635,68,20,30,24,'‹‹Dünyada dört küçük yaratık var ki, 2 Çok bilgece davranırlar:'),
(2000636,68,20,30,25,'Karıncalar güçlü olmayan bir topluluktur, 2 Ama yiyeceklerini yazdan biriktirirler.'),
(2000637,68,20,30,26,'Kaya tavşanları da güçsüz bir topluluktur, 2 Ama yuvalarını kaya kovuklarında yaparlar.'),
(2000638,68,20,30,27,'Çekirgelerin kralı yoktur, 2 Ama bölük bölük ilerlerler.'),
(2000639,68,20,30,28,'Kertenkele elle bile yakalanır, 2 Ama kral saraylarında bulunur.'),
(2000640,68,20,30,29,'‹‹Yürüyüşü gösterişli üç yaratık, 2 Davranışı gösterişli dört yaratık var:'),
(2000641,68,20,30,30,'Hayvanların en güçlüsü olan 2 Ve hiçbir şeyin önünde pes etmeyen aslan,'),
(2000642,68,20,30,31,'Tazıfş, teke 2 Ve ordusunun başındaki kral. sözcüğün anlamı tam bilinmiyor.'),
(2000643,68,20,30,32,'‹‹Eğer budala gibi kendini yücelttinse 2 Ya da kötülük tasarladınsa, 2 Dur ve düşün!'),
(2000644,68,20,30,33,'Çünkü nasıl sütü dövünce tereyağı, 2 Burnu sıkınca kan çıkarsa, 2 Öfkeyi kurcalayınca da kavga çıkar.››'),
(2000645,68,20,31,1,'Massa Kralı Lemuelin sözleri, 2 Annesinin ona öğrettikleri:'),
(2000646,68,20,31,2,'‹‹Oğlum, rahmimin ürünü, ne diyeyim? 2 Adaklarımın yanıtı oğlum, ne diyeyim?'),
(2000647,68,20,31,3,'Gücünü kadınlara, 2 Gençliğini kralları mahvedenlere kaptırma!'),
(2000648,68,20,31,4,'‹‹Şarap içmek krallara yakışmaz, ey Lemuel, 2 Krallara yakışmaz! 2 İçkiyi özlemek hükümdarlara yaraşmaz.'),
(2000649,68,20,31,5,'Çünkü içince kuralları unutur, 2 Mazlumun hakkını yerler.'),
(2000650,68,20,31,6,'İçkiyi çaresize, 2 Şarabı kaygı çekene verin.'),
(2000651,68,20,31,7,'İçsin ki yoksulluğunu unutsun, 2 Artık sefaletini anmasın.'),
(2000652,68,20,31,8,'Ağzını hakkını savunamayan için, 2 Kimsesizin davasını gütmek için aç.'),
(2000653,68,20,31,9,'Ağzını aç ve adaletle yargıla, 2 Mazlumun, yoksulun hakkını savun.››'),
(2000654,68,20,31,10,'Erdemli kadını kim bulabilir? 2 Onun değeri mücevherden çok üstündür. sırayla İbranice alfabenin değişik bir harfiyle başlar.'),
(2000655,68,20,31,11,'Kocası ona yürekten güvenir 2 Ve kazancı eksilmez.'),
(2000656,68,20,31,12,'Kadın ona kötülükle değil, 2 Yaşamı boyunca iyilikle karşılık verir.'),
(2000657,68,20,31,13,'Yün, keten bulur, 2 Zevkle elleriyle işler.'),
(2000658,68,20,31,14,'Ticaret gemileri gibidir, 2 Yiyeceğini uzaktan getirir.'),
(2000659,68,20,31,15,'Gün ağarmadan kalkar, 2 Ev halkına yiyecek, hizmetçilerine paylarını verir.'),
(2000660,68,20,31,16,'Bir tarlayı gözüne kestirip satın alır, 2 El emeğiyle kazandığı parayla bağ diker.'),
(2000661,68,20,31,17,'Giyinip kollarını sıvar, 2 Canla başla çalışır.'),
(2000662,68,20,31,18,'Ticaretinin kârlı olduğunu bilir, 2 Çırası gece boyunca yanar.'),
(2000663,68,20,31,19,'Eliyle örekeyi tutar, 2 Avucunda iği tutar.'),
(2000664,68,20,31,20,'Mazluma kollarını açar, 2 Yoksula elini uzatır.'),
(2000665,68,20,31,21,'Kar yağınca ev halkı için kaygılanmaz, 2 Çünkü hepsinin iki katfü giysisi vardır.'),
(2000666,68,20,31,22,'Yatak örtüleri dokur, 2 Kendi giysileri ince mor ketendendir.'),
(2000667,68,20,31,23,'Kocası ülkenin ileri gelenleriyle oturup kalkar, 2 Kent kurulunda iyi tanınır.'),
(2000668,68,20,31,24,'Kadın diktiği keten giysilerle 2 Ördüğü kuşakları tüccara satar.'),
(2000669,68,20,31,25,'Güç ve onurla kuşanmıştır, 2 Geleceğe güvenle bakar.'),
(2000670,68,20,31,26,'Ağzından bilgelik akar, 2 Dili iyilik öğütler.'),
(2000671,68,20,31,27,'Ev halkının işlerini yönetir, 2 Tembellik nedir bilmez.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000672,68,20,31,28,'Çocukları önünde ayağa kalkıp onu kutlar, 2 Kocası onu över.'),
(2000673,68,20,31,29,'‹‹Soylu işler yapan çok kadın var, 2 Ama sen hepsinden üstünsün›› der.'),
(2000674,68,20,31,30,'Çekicilik aldatıcı, güzellik boştur; 2 Ama RABbe saygılı kadın övülmeye layıktır.'),
(2000675,68,20,31,31,'Ellerinin hak ettiğini verin kendisine, 2 Yaptıkları için kent kurulunda övülsün.'),
(2000676,68,21,1,1,'Bunlar Yeruşalimde krallık yapan Davut oğlu Vaizin sözleridir:'),
(2000677,68,21,1,2,'‹‹Her şey boş, bomboş, bomboş!›› diyor Vaiz.'),
(2000678,68,21,1,3,'Ne kazancı var insanın 2 Güneşin altında harcadığı onca emekten?'),
(2000679,68,21,1,4,'Kuşaklar gelir, kuşaklar geçer, 2 Ama dünya sonsuza dek kalır.'),
(2000680,68,21,1,5,'Güneş doğar, güneş batar, 2 Hep doğduğu yere koşar.'),
(2000681,68,21,1,6,'Rüzgar güneye gider, kuzeye döner, 2 Döne döne eserek 2 Hep aynı yolu izler.'),
(2000682,68,21,1,7,'Bütün ırmaklar denize akar, 2 Yine de deniz dolmaz. 2 Irmaklar hep çıktıkları yere döner.'),
(2000683,68,21,1,8,'Her şey yorucu, 2 Sözcüklerle anlatılamayacak kadar. 2 Göz görmekle doymuyor, 2 Kulak işitmekle dolmuyor.'),
(2000684,68,21,1,9,'Önce ne olduysa, yine olacak. 2 Önce ne yapıldıysa, yine yapılacak. 2 Güneşin altında yeni bir şey yok.'),
(2000685,68,21,1,10,'Var mı kimsenin, ‹‹Bak bu yeni!›› diyebileceği bir şey? 2 Her şey çoktan, bizden yıllar önce de vardı.'),
(2000686,68,21,1,11,'Geçmiş kuşaklar anımsanmıyor, 2 Gelecek kuşaklar da kendilerinden sonra gelenlerce anımsanmayacak.'),
(2000687,68,21,1,12,'Ben Vaiz, Yeruşalimde İsrail kralıyken'),
(2000688,68,21,1,13,'kendimi göklerin altında yapılan her şeyi bilgece araştırıp incelemeye adadım. Tanrının uğraşsınlar diye insanlara verdiği çetin bir zahmettir bu.'),
(2000689,68,21,1,14,'Güneşin altında yapılan bütün işleri gördüm; hepsi boştur, rüzgarı kovalamaya kalkışmaktır!'),
(2000690,68,21,1,15,'Eğri olan doğrultulamaz, eksik olan sayılamaz.'),
(2000691,68,21,1,16,'Kendi kendime, ‹‹İşte, bilgeliğimi benden önce Yeruşalimde krallık yapan herkesten çok artırdım›› dedim, ‹‹Alabildiğine bilgi ve bilgelik edindim.››'),
(2000692,68,21,1,17,'Kendimi bilgi ve bilgeliği, deliliği ve akılsızlığı anlamaya adadım. Gördüm ki, bu da yalnızca rüzgarı kovalamaya kalkışmakmış.'),
(2000693,68,21,1,18,'Çünkü çok bilgelik çok keder doğurur, bilgi arttıkça acı da artar.'),
(2000694,68,21,2,1,'Kendi kendime, ‹‹Gel, zevki tat. İyi mi, değil mi, gör›› dedim. Ama gördüm ki, o da boş.'),
(2000695,68,21,2,2,'Gülmeye, ‹‹Delilik››, zevke, ‹‹Ne işe yarar?›› dedim.'),
(2000696,68,21,2,3,'İnsanların göklerin altında geçirdiği birkaç günlük ömürleri boyunca, yapacakları iyi bir şey olup olmadığını görünceye dek, bilgeliğimin önderliğinde, bedenimi şarapla nasıl canlandırayım, akılsızlığı nasıl ele alayım diye düşündüm durdum.'),
(2000697,68,21,2,4,'Büyük işlere girdim. Kendime evler inşa ettim, bağlar diktim.'),
(2000698,68,21,2,5,'Bahçeler, parklar yaptım, oralara türlü türlü meyve ağaçları diktim.'),
(2000699,68,21,2,6,'Dal budak salan orman ağaçlarını sulamak için havuzlar yaptım.'),
(2000700,68,21,2,7,'Kadın, erkek köleler satın aldım; evimde doğan kölelerim de vardı. Ayrıca benden önce Yeruşalimde yaşayan herkesten çok sığıra, davara sahip oldum.'),
(2000701,68,21,2,8,'Altın, gümüş biriktirdim; kralların, illerin hazinelerini topladım. Kadın, erkek şarkıcılar ve erkeklerin özlemi olan bir harem edindim.'),
(2000702,68,21,2,9,'Böylece büyük üne kavuştum, benden önce Yeruşalimde yaşayanların hepsini aştım. Bilgeliğimden de bir şey yitirmedim.'),
(2000703,68,21,2,10,'Gözümün dilediği hiçbir şeyi kendimden esirgemedim. 2 Gönlümü hiçbir zevkten alıkoymadım. 2 Yaptığım her işten zevk aldı gönlüm. 2 Bütün emeğimin ödülü bu oldu.'),
(2000704,68,21,2,11,'Yaptığım bütün işlere, 2 Çektiğim bütün emeklere bakınca, 2 Gördüm ki, hepsi boş ve rüzgarı kovalamaya kalkışmakmış. 2 Güneşin altında hiçbir kazanç yokmuş.'),
(2000705,68,21,2,12,'Sonra bilgelik, delilik, akılsızlık nedir diye baktım; 2 Çünkü kralın yerine geçecek kişi 2 Zaten yapılanın ötesinde ne yapabilir ki?'),
(2000706,68,21,2,13,'Işığın karanlıktan üstün olduğu gibi 2 Bilgeliğin de akılsızlıktan üstün olduğunu gördüm.'),
(2000707,68,21,2,14,'Bilge nereye gittiğini görür, 2 Ama akılsız karanlıkta yürür. 2 İkisinin de aynı sonu paylaştığını gördüm.'),
(2000708,68,21,2,15,'‹‹Akılsızın başına gelen, benim de başıma gelecek›› 2 Dedim kendi kendime, ‹‹Öyleyse kazancım ne bilgelikten?›› 2 ‹‹Bu da boş›› dedim içimden.'),
(2000709,68,21,2,16,'Çünkü akılsız gibi, bilge de uzun süre anılmaz, 2 Gelecekte ikisi de unutulur. 2 Nitekim bilge de akılsız gibi ölür!'),
(2000710,68,21,2,17,'Böylece hayattan nefret ettim. 2 Çünkü güneşin altında yapılan iş çetindi bence. 2 Her şey boş ve rüzgarı kovalamaya kalkışmakmış.'),
(2000711,68,21,2,18,'Güneşin altında harcadığım bütün emekten nefret ettim. Çünkü her şeyi benden sonra gelecek olana bırakmak zorundayım.'),
(2000712,68,21,2,19,'Kim bilir, bilge mi olacak, akılsız mı? Güneşin altında bilgeliğimi kullanarak harcadığım bütün emek üzerinde saltanat sürecek. Bu da boş.'),
(2000713,68,21,2,20,'Bu yüzden güneşin altında harcadığım onca emeğe üzülmeye başladım.'),
(2000714,68,21,2,21,'Çünkü biri bilgelik, bilgi ve beceriyle çalışır, sonunda her şeyini hiç emek vermemiş başka birine bırakmak zorunda kalır. Bu da boş ve büyük bir hüsrandır.'),
(2000715,68,21,2,22,'Çünkü ne kazancı var adamın, güneşin altında harcadığı bunca emekten, bunca kafa yormaktan?'),
(2000716,68,21,2,23,'Günler boyunca çektiği zahmet acı ve dert doğurur. Gece bile içi rahat etmez. Bu da boş.'),
(2000717,68,21,2,24,'İnsan için yemekten, içmekten ve yaptığı işten zevk almaktan daha iyi bir şey yoktur. Gördüm ki, bu da Tanrıdandır.'),
(2000718,68,21,2,25,'Onsuz kim yiyebilir, kim zevk alabilir?'),
(2000719,68,21,2,26,'Çünkü Tanrı bilgiyi, bilgeliği, sevinci hoşnut kaldığı insana verir. Günahkâra ise, yığma, biriktirme zahmeti verir; biriktirdiklerini Tanrı''nın hoşnut kaldığı insanlara bıraksın diye. Bu da boş ve rüzgarı kovalamaya kalkışmakmış.'),
(2000720,68,21,3,1,'Her şeyin mevsimi, göklerin altındaki her olayın zamanı vardır.'),
(2000721,68,21,3,2,'Doğmanın zamanı var, ölmenin zamanı var. 2 Dikmenin zamanı var, sökmenin zamanı var.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000722,68,21,3,3,'Öldürmenin zamanı var, şifa vermenin zamanı var. 2 Yıkmanın zamanı var, yapmanın zamanı var.'),
(2000723,68,21,3,4,'Ağlamanın zamanı var, gülmenin zamanı var. 2 Yas tutmanın zamanı var, oynamanın zamanı var.'),
(2000724,68,21,3,5,'Taş atmanın zamanı var, taş toplamanın zamanı var. 2 Kucaklaşmanın zamanı var, kucaklaşmamanın zamanı var.'),
(2000725,68,21,3,6,'Aramanın zamanı var, vazgeçmenin zamanı var. 2 Saklamanın zamanı var, atmanın zamanı var.'),
(2000726,68,21,3,7,'Yırtmanın zamanı var, dikmenin zamanı var. 2 Susmanın zamanı var, konuşmanın zamanı var.'),
(2000727,68,21,3,8,'Sevmenin zamanı var, nefret etmenin zamanı var. 2 Savaşın zamanı var, barışın zamanı var.'),
(2000728,68,21,3,9,'Çalışanın harcadığı emekten ne kazancı var?'),
(2000729,68,21,3,10,'Tanrının uğraşsınlar diye insanlara verdiği zahmeti gördüm.'),
(2000730,68,21,3,11,'O her şeyi zamanında güzel yaptı. İnsanların yüreğine sonsuzluk kavramını koydu. Yine de insan Tanrının yaptığı işi başından sonuna dek anlayamaz.'),
(2000731,68,21,3,12,'İnsan için yaşamı boyunca mutlu olmaktan, iyi yaşamaktan daha iyi bir şey olmadığını biliyorum.'),
(2000732,68,21,3,13,'Her insanın yiyip içmesi, yaptığı her işle doyuma ulaşması bir Tanrı armağanıdır.'),
(2000733,68,21,3,14,'Tanrının yaptığı her şeyin sonsuza dek süreceğini biliyorum. Ona ne bir şey eklenebilir ne de ondan bir şey çıkarılabilir. Tanrı insanların kendisine saygı duymaları için bunu yapıyor.'),
(2000734,68,21,3,15,'Şimdi ne oluyorsa, geçmişte de oldu, 2 Ne olacaksa, daha önce de olmuştur. 2 Tanrı geçmiş olayların hesabını soruyor.'),
(2000735,68,21,3,16,'Güneşin altında bir şey daha gördüm: 2 Adaletin ve doğruluğun yerini kötülük almış.'),
(2000736,68,21,3,17,'İçimden ‹‹Tanrı doğruyu da, kötüyü de yargılayacaktır›› dedim, 2 ‹‹Çünkü her olayın, her eylemin zamanını belirledi.››'),
(2000737,68,21,3,18,'İnsanlara gelince, ‹‹Tanrı hayvan olduklarını görsünler diye insanları sınıyor›› diye düşündüm.'),
(2000738,68,21,3,19,'Çünkü insanların başına gelen hayvanların da başına geliyor. Aynı sonu paylaşıyorlar. Biri nasıl ölüyorsa, öbürü de öyle ölüyor. Hepsi aynı soluğu taşıyor. İnsanın hayvandan üstünlüğü yoktur. Çünkü her şey boş.'),
(2000739,68,21,3,20,'İkisi de aynı yere gidiyor; topraktan gelmiş, toprağa dönüyor.'),
(2000740,68,21,3,21,'Kim biliyor insan ruhunun yukarıya çıktığını, hayvan ruhunun aşağıya, yeraltına indiğini?'),
(2000741,68,21,3,22,'Sonuçta insanın yaptığı işten zevk almasından daha iyi bir şey olmadığını gördüm. Çünkü onun payına düşen budur. Kendisinden sonra olacakları görmesi için kim onu geri getirebilir?'),
(2000742,68,21,4,1,'Güneşin altında yapılan baskılara bir daha baktım, 2 Ezilenlerin gözyaşlarını gördüm; 2 Avutanları yok, 2 Güç ezenlerden yana, 2 Avutanları yok.'),
(2000743,68,21,4,2,'Çoktan ölmüş ölüleri, 2 Hâlâ sağ olan yaşayanlardan daha mutlu gördüm.'),
(2000744,68,21,4,3,'Ama henüz doğmamış, 2 Güneşin altında yapılan kötülükleri görmemiş olan 2 İkisinden de mutludur.'),
(2000745,68,21,4,4,'Harcanan her emeğin, yapılan her ustaca işin ardında kıskançlık olduğunu gördüm. Bu da boş ve rüzgarı kovalamaya kalkışmakmış.'),
(2000746,68,21,4,5,'Akılsız ellerini kavuşturup kendi kendini yer.'),
(2000747,68,21,4,6,'Rahat kazanılan bir avuç dolusu 2 Zahmetle, rüzgarı kovalamaya kalkışarak kazanılan 2 İki avuç dolusundan daha iyidir.'),
(2000748,68,21,4,7,'Güneşin altında bir boş şey daha gördüm:'),
(2000749,68,21,4,8,'Yalnız bir adam vardı, 2 Oğlu da kardeşi de yoktu. 2 Çabaları dinmek nedir bilmezdi, 2 Gözü zenginliğe doymazdı. 2 ‹‹Kimin için çalışıyorum, 2 Neden kendimi zevkten yoksun bırakıyorum?›› diye sormazdı. 2 Bu da boş ve çetin bir zahmettir.'),
(2000750,68,21,4,9,'İki kişi bir kişiden iyidir, 2 Çünkü emeklerine iyi karşılık alırlar.'),
(2000751,68,21,4,10,'Biri düşerse, öteki kaldırır. 2 Ama yalnız olup da düşenin vay haline! 2 Onu kaldıran olmaz.'),
(2000752,68,21,4,11,'Ayrıca iki kişi birlikte yatarsa, birbirini ısıtır. 2 Ama tek başına yatan nasıl ısınabilir?'),
(2000753,68,21,4,12,'Yalnız biri yenik düşer, 2 Ama iki kişi direnebilir. 2 Üç kat iplik kolay kolay kopmaz.'),
(2000754,68,21,4,13,'Yoksul ama bilge bir genç artık öğüt almayı bilmeyen kocamış akılsız kraldan iyidir.'),
(2000755,68,21,4,14,'Çünkü genç, ülkesinde yoksulluk içinde doğsa bile cezaevinden krallığa yükselebilir.'),
(2000756,68,21,4,15,'Güneşin altında yaşayan herkesin kralın yerine geçen genci izlediğini gördüm.'),
(2000757,68,21,4,16,'Yeni kralın yönettiği halk sayısız olabilir. Yine de sonrakiler ondan hoşnut olmayabilir. Gerçekten bu da boş ve rüzgarı kovalamaya kalkışmaktır.'),
(2000758,68,21,5,1,'Tanrının evine gittiğinde davranışına dikkat et. Yaptıkları kötülüğün farkında olmayan akılsızlar gibi kurban sunmak için değil, dinlemek için yaklaş.'),
(2000759,68,21,5,2,'Ağzını çabuk açma, 2 Tanrının önünde hemen konuya girme, 2 Çünkü Tanrı gökte, sen yerdesin, 2 Bu yüzden, az konuş.'),
(2000760,68,21,5,3,'Çok tasa kötü düş, 2 Çok söz akılsızlık doğurur.'),
(2000761,68,21,5,4,'Tanrıya adak adayınca, yerine getirmekte gecikme. Çünkü O akılsızlardan hoşlanmaz. Adağını yerine getir!'),
(2000762,68,21,5,5,'Adamamak, adayıp da yerine getirmemekten iyidir.'),
(2000763,68,21,5,6,'Ağzının seni günaha sürüklemesine izin verme. Ulağın önünde: ‹‹Adağım yanlıştı›› deme. Tanrı niçin senin sözlerine öfkelensin, yaptığın işi yok etsin?'),
(2000764,68,21,5,7,'Çünkü çok düş kurmak hayalciliğe ve laf kalabalığına yol açar; Tanrıya saygı göster. anlamına gelebilir.'),
(2000765,68,21,5,8,'Bir yerde yoksullara baskı yapıldığını, adaletin ve doğruluğun çiğnendiğini görürsen şaşma; çünkü üstü gözeten daha üst biri var, onların da üstleri var.'),
(2000766,68,21,5,9,'Tarlaların sürülmesini isteyen bir kral ülke için her bakımdan yararlıdır.'),
(2000767,68,21,5,10,'Parayı seven paraya doymaz, 2 Zenginliği seven kazancıyla yetinmez. 2 Bu da boştur.'),
(2000768,68,21,5,11,'Mal çoğaldıkça yiyeni de çoğalır. 2 Sahibine ne yararı var, seyretmekten başka?'),
(2000769,68,21,5,12,'Az yesin, çok yesin işçi rahat uyur, 2 Ama zenginin malı zengini uyutmaz.'),
(2000770,68,21,5,13,'Güneşin altında acı bir kötülük gördüm: 2 Sahibinin zararına biriktirilen 2 Ve bir talihsizlikle yok olup giden servet. 2 Böyle bir servet sahibi baba olsa bile, 2 Oğluna bir şey bırakamaz.'),
(2000771,68,21,5,15,'Annesinin rahminden çıplak çıkar insan. 2 Dünyaya nasıl geldiyse öyle gider, 2 Emeğinden hiçbir şey götürmez elinde.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000772,68,21,5,16,'Dünyaya nasıl geldiyse öyle gider insan. 2 Bu da acı bir kötülüktür. 2 Ne kazancı var yel için zahmet çekmekten?'),
(2000773,68,21,5,17,'Ömrü boyunca büyük üzüntü, hastalık, öfke içinde 2 Karanlıkta yiyor.'),
(2000774,68,21,5,18,'Gördüm ki, iyi ve güzel olan şu: Tanrının insana verdiği birkaç günlük ömür boyunca yemek, içmek, güneşin altında harcadığı emekten zevk almak. Çünkü insanın payına düşen budur.'),
(2000775,68,21,5,19,'Üstelik Tanrı bir insana mal mülk veriyor, onu yemesi, ödülünü alması, yaptığı işten mutluluk duyması için ona güç veriyorsa, bu bir Tanrı armağanıdır.'),
(2000776,68,21,5,20,'Bu yüzden insan, geçen ömrünü pek düşünmez. Çünkü Tanrı onun yüreğini mutlulukla meşgul eder.'),
(2000777,68,21,6,1,'Güneşin altında insana ağır gelen bir kötülük gördüm:'),
(2000778,68,21,6,2,'Adam vardır, Tanrı kendisine mal, mülk, saygınlık verir, yerine gelmeyecek isteği yoktur. Ama Tanrı yemesine izin vermez; bir yabancı yer. Bu da boş ve acı bir derttir.'),
(2000779,68,21,6,3,'Bir adam yüz çocuk babası olup uzun yıllar yaşamış, ama uzun ömrüne karşılık, zenginliğin tadını çıkaramamış, bir mezara bile gömülmemişse, düşük çocuk ondan iyidir derim.'),
(2000780,68,21,6,4,'Çünkü düşük çocuk boş yere doğuyor, karanlık içinde geçip gidiyor, adı karanlığa gömülüyor.'),
(2000781,68,21,6,5,'Ne güneş yüzü görüyor, ne de bir şey tanıyor. Öbür adam iki kez biner yıl yaşasa bile mutluluk duymaz, düşük çocuk ondan rahattır. Hepsi aynı yere gitmiyor mu?'),
(2000782,68,21,6,7,'İnsan hep boğazı için çalışır, 2 Yine de doymaz.'),
(2000783,68,21,6,8,'Bilgenin akılsızdan ne üstünlüğü var? 2 Yoksul başkasına nasıl davranacağını bilmekle ne yarar sağlar?'),
(2000784,68,21,6,9,'Gözün gördüğü gönlün çektiğinden iyidir. 2 Bu da boş ve rüzgarı kovalamaya kalkışmaktır.'),
(2000785,68,21,6,10,'Ne varsa, adı çoktan konmuştur, 2 İnsanın da ne olduğu biliniyor. 2 Kimse kendinden güçlü olanla çekişemez.'),
(2000786,68,21,6,11,'Söz çoğaldıkça anlam azalır, 2 Bunun kime yararı olur?'),
(2000787,68,21,6,12,'Çünkü gölge gibi gelip geçen kısa ve boş ömründe insana neyin yararlı olduğunu kim bilebilir? Bir adama kendisinden sonra güneşin altında neler olacağını kim söyleyebilir?'),
(2000788,68,21,7,1,'İyi ad hoş kokulu yağdan, 2 Ölüm günü doğum gününden iyidir.'),
(2000789,68,21,7,2,'Yas evine gitmek, şölen evine gitmekten iyidir. 2 Çünkü her insanın sonu ölümdür, 2 Yaşayan herkes bunu aklında tutmalı.'),
(2000790,68,21,7,3,'Üzüntü gülmekten iyidir, 2 Çünkü yüz mahzun olunca yürek sevinir.'),
(2000791,68,21,7,4,'Bilge kişinin aklı yas evindedir, 2 Akılsızın aklıysa şenlik evinde.'),
(2000792,68,21,7,5,'Bilgenin azarını işitmek, 2 Akılsızın türküsünü işitmekten iyidir.'),
(2000793,68,21,7,6,'Çünkü akılsızın gülmesi, 2 Kazanın altındaki çalıların çatırtısı gibidir. 2 Bu da boştur.'),
(2000794,68,21,7,7,'Haksız kazanç bilgeyi delirtir, 2 Rüşvet karakteri bozar.'),
(2000795,68,21,7,8,'Bir olayın sonu başlangıcından iyidir. 2 Sabırlı kibirliden iyidir.'),
(2000796,68,21,7,9,'Çabuk öfkelenme, 2 Çünkü öfke akılsızların bağrında barınır.'),
(2000797,68,21,7,10,'‹‹Neden geçmiş günler bugünlerden iyiydi?›› diye sorma, 2 Çünkü bu bilgece bir soru değil.'),
(2000798,68,21,7,11,'Bilgelik miras kadar iyidir, 2 Güneşi gören herkes için yararlıdır.'),
(2000799,68,21,7,12,'Bilgelik siperdir, para da siper, 2 Bilginin yararı ise şudur: 2 Bilgelik ona sahip olan kişinin yaşamını korur.'),
(2000800,68,21,7,13,'Tanrının yaptığını düşün: 2 Onun eğrilttiğini kim doğrultabilir?'),
(2000801,68,21,7,14,'İyi günde mutlu ol, 2 Ama kötü günde dikkatle düşün; 2 Tanrı birini öbürü gibi yaptı ki, 2 İnsan kendisinden sonra neler olacağını bilmesin.'),
(2000802,68,21,7,15,'Boş ömrümde şunları gördüm: 2 Doğru insan doğruluğuna karşın ölüyor, 2 Kötü insanın ise, kötülüğüne karşın ömrü uzuyor.'),
(2000803,68,21,7,16,'Ne çok doğru ol ne de çok bilge. 2 Niçin kendini yok edesin?'),
(2000804,68,21,7,17,'Ne çok kötü ol ne de akılsız. 2 Niçin vaktinden önce ölesin?'),
(2000805,68,21,7,18,'Birini tutman iyidir, 2 Öbüründen de elini çekme. 2 Çünkü Tanrıya saygı duyan ikisini de başarır.'),
(2000806,68,21,7,19,'Bilgelik, bilge kişiyi kentteki on yöneticiden daha güçlü kılar.'),
(2000807,68,21,7,20,'Çünkü yeryüzünde hep iyilik yapan, 2 Hiç günah işlemeyen doğru insan yoktur.'),
(2000808,68,21,7,21,'İnsanların söylediği her söze aldırma, 2 Yoksa uşağının bile sana sövdüğünü duyabilirsin.'),
(2000809,68,21,7,22,'Çünkü sen de birçok kez 2 Başkalarına sövdüğünü pekâlâ biliyorsun.'),
(2000810,68,21,7,23,'Bütün bunları bilgelikle denedim: 2 ‹‹Bilge olacağım›› dedim. 2 Ama bu beni aşıyordu.'),
(2000811,68,21,7,24,'Bilgelik denen şey 2 Uzak ve çok derindir, onu kim bulabilir?'),
(2000812,68,21,7,25,'Böylece, bilgelik ve çözüm aramaya, incelemeye, kavramaya, 2 Kötülüğün akılsızlık, akılsızlığın delilik olduğunu anlamaya kafa yordum.'),
(2000813,68,21,7,26,'Kimi kadını ölümden acı buldum. 2 O kadın ki, kendisi tuzak, yüreği kapan, elleri zincirdir. 2 Tanrının hoşnut kaldığı insan ondan kaçar, 2 Günah işleyense ona tutsak olur.'),
(2000814,68,21,7,27,'Vaiz diyor ki, ‹‹Şunu gördüm: 2 Bir çözüm bulmak için 2 Bir şeyi öbürüne eklerken'),
(2000815,68,21,7,28,'-Araştırıp hâlâ bulamazken- 2 Binde bir adam buldum, 2 Ama aralarında bir kadın bulamadım.'),
(2000816,68,21,7,29,'Bulduğum tek şey: 2 Tanrı insanları doğru yarattı, 2 Oysa onlar hâlâ karmaşık çözümler arıyorlar.››'),
(2000817,68,21,8,1,'Bilge insan gibisi var mı? 2 Kim olup bitenlerin anlamını bilebilir? 2 Bilgelik insanın yüzünü aydınlatır, 2 Sert görünüşünü değiştirir.'),
(2000818,68,21,8,2,'Kralın buyruğuna uy, diyorum. Çünkü Tanrının önünde ant içtin.'),
(2000819,68,21,8,3,'Kralın huzurundan ayrılmak için acele etme. Kötülüğe bulaşma. Çünkü o dilediği her şeyi yapar.'),
(2000820,68,21,8,4,'Kralın sözünde güç vardır. Kim ona, ‹‹Ne yapıyorsun?›› diyebilir?'),
(2000821,68,21,8,5,'Onun buyruğuna uyan zarar görmez. 2 Bilge kişi bunun zamanını ve yolunu bilir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000822,68,21,8,6,'Çünkü her işin bir zamanı ve yolu vardır. 2 İnsanın derdi kendine yeter.'),
(2000823,68,21,8,7,'Kimse geleceği bilmez, 2 Kim kime geleceği bildirebilir?'),
(2000824,68,21,8,8,'Rüzgarı tutup ona egemen olmaya kimsenin gücü yetmediği gibi, 2 Ölüm gününe egemen olmaya da kimsenin gücü yetmez. 2 Savaştan kaçış olmadığı gibi, kötülük de sahibini kurtaramaz.'),
(2000825,68,21,8,9,'Bütün bunları gördüm ve güneşin altında yapılan her iş üzerinde kafa yordum. Gün gelir, insanın insana egemenliği kendine zarar verir.'),
(2000826,68,21,8,10,'Bir de kötülerin gömüldüğünü gördüm. Kutsal yere girip çıkar, kötülük yaptıkları kentte övülürlerdi. Bu da boş.'),
(2000827,68,21,8,11,'Suçlu çabuk yargılanmazsa, insanlar kötülük etmek için cesaret bulur.'),
(2000828,68,21,8,12,'Günahlı yüz kez kötülük edip uzun yaşasa bile, Tanrıdan korkanların, Onun önünde saygıyla duranların iyilik göreceğini biliyorum.'),
(2000829,68,21,8,13,'Oysa kötü, Tanrıdan korkmadığı için iyilik görmeyecek, gölge gibi olan ömrü uzamayacaktır.'),
(2000830,68,21,8,14,'Yeryüzünde boş bir şey daha var: Kötülerin hak ettiği doğruların, doğruların hak ettiğiyse kötülerin başına geliyor. Bu da boş, diyorum.'),
(2000831,68,21,8,15,'Mutluluğu övgüye değer buldum. Çünkü güneşin altında insan için yiyip içmekten, mutlu olmaktan daha iyi bir şey yoktur. Çünkü Tanrının güneşin altında kendisine verdiği ömür boyunca çektiği zahmetten insana kalacak olan budur.'),
(2000832,68,21,8,16,'Bilgeliği ve dünyada çekilen zahmeti anlamak için kafamı yorunca -öyleleri var ki, gece gündüz gözüne uyku girmez-'),
(2000833,68,21,8,17,'Tanrı''nın yaptığı her şeyi gördüm. İnsan güneşin altında olup bitenleri keşfedemez. Arayıp bulmak için ne kadar çaba harcarsa harcasın, yine de anlamını bulamaz. Bilge kişi anladığını söylese bile gerçekten kavrayamaz.'),
(2000834,68,21,9,1,'Böylece bütün bunları düşünüp taşındım ve şu sonuca vardım: Doğrular, bilgeler ve yaptıkları her şey Tanrının elindedir. Onları sevginin mi, nefretin mi beklediğini kimse bilmez.'),
(2000835,68,21,9,2,'Herkesin başına aynı şey geliyor. Doğrunun, iyinin, kötünün, temizin, kirlinin, kurban sunanla sunmayanın başına gelen şey aynı. İyi insana ne oluyorsa, günahlıya da oluyor; 2 Ant içene ne oluyorsa, ant içmekten korkana da aynısı oluyor.'),
(2000836,68,21,9,3,'Güneşin altında yapılan işlerin tümünün kötü yanı şu ki, herkesin başına aynı şey geliyor. Üstelik insanların içi kötülük doludur, yaşadıkları sürece içlerinde delilik vardır. Ardından ölüp gidiyorlar.'),
(2000837,68,21,9,4,'Yaşayanlar arasındaki herkes için umut vardır. Evet, sağ köpek ölü aslandan iyidir!'),
(2000838,68,21,9,5,'Çünkü yaşayanlar öleceğini biliyor, 2 Ama ölüler hiçbir şey bilmiyor. 2 Onlar için artık ödül yoktur, 2 Anıları bile unutulmuştur.'),
(2000839,68,21,9,6,'Sevgileri, nefretleri, 2 Kıskançlıkları çoktan bitmiştir. 2 Güneşin altında yapılanlardan 2 Bir daha payları olmayacaktır.'),
(2000840,68,21,9,7,'Git, sevinçle ekmeğini ye, neşeyle şarabını iç. Çünkü yaptıkların baştan beri Tanrının hoşuna gitti.'),
(2000841,68,21,9,8,'Giysilerin hep ak olsun. Başından zeytinyağı eksilmesin.'),
(2000842,68,21,9,9,'Güneşin altında Tanrının sana verdiği boş ömrün bütün günlerini, bütün anlamsız günlerini sevdiğin karınla güzel güzel yaşayarak geçir. Çünkü hayattan ve güneşin altında harcadığın emekten payına düşecek olan budur.'),
(2000843,68,21,9,10,'Çalışmak için eline ne geçerse, var gücünle çalış. Çünkü gitmekte olduğun ölüler diyarında iş, tasarı, bilgi ve bilgelik yoktur.'),
(2000844,68,21,9,11,'Güneşin altında bir şey daha gördüm: 2 Yarışı hızlı koşanlar, 2 Savaşı yiğitler, 2 Ekmeği bilgeler, 2 Serveti akıllılar, 2 Beğeniyi bilgililer kazanmaz. 2 Ama zaman ve şans hepsinin önüne çıkar.'),
(2000845,68,21,9,12,'Dahası insan kendi vaktini bilmez: 2 Balığın acımasız ağa, kuşun kapana düştüğü gibi, 2 İnsanlar da üzerlerine ansızın çöken kötü zamana yakalanırlar.'),
(2000846,68,21,9,13,'Güneşin altında bilgelik olarak şunu da gördüm, beni çok etkiledi:'),
(2000847,68,21,9,14,'Çok az insanın yaşadığı küçük bir kent vardı. Güçlü bir kral saldırıp onu kuşattı. Karşısına büyük rampalar kurdu.'),
(2000848,68,21,9,15,'Kentte yoksul ama bilge bir adam vardı. Bilgeliğiyle kenti kurtardı. Ne var ki, kimse bu yoksul adamı anmadı.'),
(2000849,68,21,9,16,'Bunun üzerine, ‹‹Bilgelik güçten iyidir›› dedim, ‹‹Ne yazık ki, yoksul insanın bilgeliği küçümseniyor, söyledikleri dikkate alınmıyor.››'),
(2000850,68,21,9,17,'Bilgenin sessizce söylediği sözler, 2 Akılsızlar arasındaki önderin bağırışından iyidir.'),
(2000851,68,21,9,18,'Bilgelik silahtan iyidir, 2 Ama bir deli çıkar, her şeyi berbat eder.'),
(2000852,68,21,10,1,'Ölü sinekler attarın ıtırını kokutur. 2 Biraz aptallık da bilgeliği ve saygınlığı bastırır.'),
(2000853,68,21,10,2,'Bilgenin yüreği hep doğruya eğilimlidir, 2 Akılsızın ise, hep yanlışa.'),
(2000854,68,21,10,3,'Yolda yürürken bile akılsızın aklı kıttır, 2 Akılsız olduğunu herkese gösterir.'),
(2000855,68,21,10,4,'Yöneticinin öfkesi sana karşı alevlenirse, 2 Yerinden ayrılma; 2 Çünkü serinkanlılık büyük yanlışları bastırır.'),
(2000856,68,21,10,5,'Güneşin altında gördüğüm bir haksızlık var, 2 Yöneticiden kaynaklanan bir yanlışı andırıyor:'),
(2000857,68,21,10,6,'Zenginler düşük makamlarda otururken, 2 Aptallar yüksek makamlara atanıyor.'),
(2000858,68,21,10,7,'Köleleri at sırtında, 2 Önderleri yerde köleler gibi yürürken gördüm.'),
(2000859,68,21,10,8,'Çukur kazan içine kendi düşer, 2 Duvarda gedik açanı yılan sokar.'),
(2000860,68,21,10,9,'Taş çıkaran taştan incinir, 2 Odun yaran tehlikeye girer.'),
(2000861,68,21,10,10,'Balta körse, ağzı bilenmemişse, 2 Daha çok güç gerektirir; 2 Ama bilgelik başarı doğurur.'),
(2000862,68,21,10,11,'Yılan büyü yapılmadan önce sokarsa, 2 Büyücünün yararı olmaz.'),
(2000863,68,21,10,12,'Bilgenin ağzından çıkan sözler benimsenir, 2 Oysa akılsız kendi ağzıyla yıkımına yol açar.'),
(2000864,68,21,10,13,'Sözünün başı aptallık, 2 Sonu zırdeliliktir.'),
(2000865,68,21,10,14,'Akılsız konuştukça konuşur. Kimse ne olacağını bilmez. 2 Kim ona kendisinden sonra ne olacağını bildirebilir?'),
(2000866,68,21,10,15,'Akılsızın emeği kendini öylesine yıpratır ki, 2 Kente bile nasıl gideceğini bilemez.'),
(2000867,68,21,10,16,'Kralın bir çocuksafç, 2 Önderlerin sabah şölen veriyorsa, vay sana, ey ülke!'),
(2000868,68,21,10,17,'Kralın soyluysa, 2 Önderlerin sarhoşluk için değil 2 Güçlenmek için vaktinde yemek yiyorsa, ne mutlu sana, ey ülke!'),
(2000869,68,21,10,18,'Tembellikten dam çöker, 2 Miskinlikten çatı akar.'),
(2000870,68,21,10,19,'Şölen eğlenmek için yapılır, 2 Şarap yaşama sevinç katar, 2 Paraysa her ihtiyacı karşılar.'),
(2000871,68,21,10,20,'İçinden bile krala sövme, 2 Yatak odanda zengine lanet etme, 2 Çünkü gökte uçan kuşlar haber taşır, 2 Kanatlı varlıklar söylediğini aktarır.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000872,68,21,11,1,'Ekmeğini suya at, 2 Çünkü günler sonra onu bulursun. alıp paranı ticarete yatırarak geçimini sağla›› ya da ‹‹İhtiyacı olanlara ver›› anlamına gelir.'),
(2000873,68,21,11,2,'Yedi, hatta sekiz kişiye pay ver, 2 Çünkü ülkenin başına ne felaket geleceğini bilemezsin.'),
(2000874,68,21,11,3,'Bulutlar su yüklüyse, 2 Yeryüzüne döker yağmurlarını. 2 Ağaç ister güneye ister kuzeye devrilsin, 2 Devrildiği yerde kalır.'),
(2000875,68,21,11,4,'Rüzgarı gözeten ekmez, 2 Bulutlara bakan biçmez.'),
(2000876,68,21,11,5,'Ana rahmindeki çocuğun nasıl ruh ve beden aldığını bilmediğin gibi, 2 Her şeyi yaratan Tanrının yaptıklarını da bilemezsin.'),
(2000877,68,21,11,6,'Tohumunu sabah ek, 2 Akşam da elin boş durmasın. 2 Çünkü bu mu iyi, şu mu, 2 Yoksa ikisi de aynı sonucu mu verecek, bilemezsin.'),
(2000878,68,21,11,7,'Işık tatlıdır, 2 Güneşi görmek güzeldir.'),
(2000879,68,21,11,8,'Evet, insan uzun yıllar yaşarsa, 2 Sevinçle yaşasın. 2 Ama karanlık günleri unutmasın, 2 Çünkü onlar da az değil. 2 Gelecek her şey boştur.'),
(2000880,68,21,11,9,'Ey delikanlı, gençliğinle sevin, 2 Bırak gençlik günlerinde yüreğin sevinç duysun. 2 Gönlünün isteklerini, gözünün gördüklerini izle, 2 Ama bil ki, bütün bunlar için Tanrı seni yargılayacaktır.'),
(2000881,68,21,11,10,'Öyleyse at tasayı yüreğinden, 2 Uzaklaştır derdi bedeninden. 2 Çünkü gençlik de dinçlik de boştur.'),
(2000882,68,21,12,1,'Bu yüzden zor günler gelmeden, 2 ‹‹Zevk almıyorum›› diyeceğin yıllar yaklaşmadan, 2 Güneş, ışık, ay ve yıldızlar kararmadan 2 Ve yağmurdan sonra bulutlar geri dönmeden, 2 Gençlik günlerinde seni yaratanı anımsa.'),
(2000883,68,21,12,3,'O gün, evi bekleyenler titreyecek, 2 Güçlüler eğilecek, 2 Öğütücüler azaldığı için duracak, 2 Pencereden bakanlar kararacak.'),
(2000884,68,21,12,4,'Değirmen sesi yavaşlayınca, 2 Sokağa açılan çift kapı kapanacak, 2 İnsanlar kuş sesiyle uyanacak, 2 Ama şarkıların sesini duyamayacaklar.'),
(2000885,68,21,12,5,'Dahası yüksek yerden, 2 Sokaktaki tehlikelerden korkacaklar; 2 Badem ağacı çiçek açacak, 2 Çekirge ağırlaşacak, 2 Tutku zayıflayacak. 2 Çünkü insan sonsuzluk evine gidecek, 2 Yas tutanlar sokakta dolaşacak. kuş gibi yükselecek››.'),
(2000886,68,21,12,6,'Gümüş tel kopmadan, 2 Altın tas kırılmadan, 2 Testi çeşmede parçalanmadan, 2 Kuyu makarası kırılmadan,'),
(2000887,68,21,12,7,'Toprak geldiği yere dönmeden, 2 Ruh onu veren Tanrıya dönmeden, 2 Seni yaratanı anımsa.'),
(2000888,68,21,12,8,'‹‹Her şey boş›› diyor Vaiz, ‹‹Bomboş!››'),
(2000889,68,21,12,9,'Vaiz yalnız bilge değildi, bildiklerini halka da öğretiyordu. Hesap etti, araştırdı ve birçok özdeyişi düzene soktu.'),
(2000890,68,21,12,10,'Güzel sözler bulmaya çalıştı. Yazdıkları gerçek ve doğrudur.'),
(2000891,68,21,12,11,'Bilgelerin sözleri üvendire gibidir, derledikleri özdeyişlerse, iyi çakılan çivi gibi; bir tek Çoban tarafından verilmişler.'),
(2000892,68,21,12,12,'Bunların dışındakilerden sakın, evladım. Çok kitap yazmanın sonu yoktur, fazla araştırma da bedeni yıpratır.'),
(2000893,68,21,12,13,'Her şey duyuldu, sonuç şu: 2 Tanrıya saygı göster, buyruklarını yerine getir, 2 Çünkü her insanın görevi budur.'),
(2000894,68,21,12,14,'Tanrı her işi, her gizli şeyi yargılayacaktır, 2 İster iyi ister kötü olsun.'),
(2000895,68,22,1,1,'Süleymanın Ezgiler Ezgisi.'),
(2000896,68,22,1,2,'Beni dudaklarıyla öptükçe öpsün! 2 Çünkü aşkın şaraptan daha tatlı.'),
(2000897,68,22,1,3,'Ne güzel kokuyor sürdüğün esans, 2 Dökülmüş esans sanki adın, 2 Kızlar bu yüzden seviyor seni.'),
(2000898,68,22,1,4,'Al götür beni, haydi koşalım! Kral beni odasına götürsün. Seninle coşup seviniriz, 2 Aşkını şaraptan çok överiz. Ne kadar haklılar seni sevmekte!'),
(2000899,68,22,1,5,'Esmerim ben, ama güzelim, 2 Ey Yeruşalim kızları! 2 Kedarın çadırları gibi, 2 Süleymanın çadır bezleri gibi kara.'),
(2000900,68,22,1,6,'Bakmayın esmer olduğuma, 2 Güneş kararttı beni. 2 Çünkü kızdılar bana erkek kardeşlerim, 2 Bağlara bakmakla görevlendirdiler. 2 Ama kendi bağıma bakmadım.'),
(2000901,68,22,1,7,'Ey sevgilim, söyle bana, sürünü nerede otlatıyorsun, 2 Öğleyin nerede yatırıyorsun? 2 Neden arkadaşlarının sürüleri yanında 2 Yüzünü örten bir kadın durumuna düşeyim? gösterirdi.'),
(2000902,68,22,1,8,'Ey güzeller güzeli, 2 Bilmiyorsan, 2 Sürünün izine çık, 2 Çobanların çadırları yanında 2 Oğlaklarını otlat.'),
(2000903,68,22,1,9,'Firavunun arabalarına koşulu kısrağa benzetiyorum seni, aşkım benim!'),
(2000904,68,22,1,10,'Yanakların süslerle, 2 Boynun gerdanlıklarla ne güzel!'),
(2000905,68,22,1,11,'Sana gümüş düğmelerle altın süsler yapacağız.'),
(2000906,68,22,1,12,'Kral divandayken, 2 Hintsümbülümün güzel kokusu yayıldı.'),
(2000907,68,22,1,13,'Memelerim arasında yatan 2 Mür dolu bir kesedir benim için sevgilim;'),
(2000908,68,22,1,14,'Eyn-Gedi bağlarında 2 Bir demet kına çiçeğidir benim için sevgilim.'),
(2000909,68,22,1,15,'Ah, ne güzelsin, aşkım, ah, ne güzel! 2 Gözlerin tıpkı birer güvercin!'),
(2000910,68,22,1,16,'Ne yakışıklısın, sevgilim, ah, ne çekici! 2 Yeşilliktir yatağımız.'),
(2000911,68,22,1,17,'Sedir ağaçlarıdır evimizin kirişleri, 2 Tavanımızın tahtaları ardıçlar.'),
(2000912,68,22,2,1,'Ben Şaron çiğdemiyim, 2 Vadilerin zambağıyım.'),
(2000913,68,22,2,2,'Dikenlerin arasında bir zambağa benzer 2 Kızların arasında aşkım.'),
(2000914,68,22,2,3,'Orman ağaçları arasında bir elma ağacına benzer 2 Delikanlıların arasında sevgilim. 2 Onun gölgesinde oturmaktan zevk alırım, 2 Tadı damağımda kalır meyvesinin.'),
(2000915,68,22,2,4,'Ziyafet evine götürdü beni, 2 Üzerimdeki sancağı aşktı.'),
(2000916,68,22,2,5,'Güçlendirin beni üzüm pestiliyle, 2 Canlandırın elmayla, 2 Çünkü aşk hastasıyım ben.'),
(2000917,68,22,2,6,'Sol eli başımın altında, 2 Sağ eli sarsın beni.'),
(2000918,68,22,2,7,'Dişi ceylanlar, 2 Yabanıl dişi geyikler üstüne 2 Ant içiriyorum size, ey Yeruşalim kızları! 2 Aşkımı ayıltmayasınız, uyandırmayasınız diye, 2 Gönlü hoş olana dek.'),
(2000919,68,22,2,8,'İşte! Sevgilimin sesi! 2 Dağların üzerinden sekerek, 2 Tepelerin üzerinden sıçrayarak geliyor.'),
(2000920,68,22,2,9,'Sevgilim ceylana benzer, sanki bir geyik yavrusu. 2 Bakın, duvarımızın ardında duruyor, 2 Pencerelerden bakıyor, 2 Kafeslerden seyrediyor.'),
(2000921,68,22,2,10,'Sevgilim şöyle dedi: 2 ‹‹Kalk, gel aşkım, güzelim.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000922,68,22,2,11,'Bak, kış geçti, 2 Yağmurların ardı kesildi,'),
(2000923,68,22,2,12,'Çiçekler açtı, 2 Şarkı mevsimi geldi, 2 Kumrular ötüşmeye başladı beldemizde.'),
(2000924,68,22,2,13,'İncir ağacı ilk meyvesini verdi, 2 Yeşeren asmalar mis gibi kokular saçmakta. 2 Kalk, gel aşkım, güzelim.››'),
(2000925,68,22,2,14,'Kaya kovuklarında, 2 Uçurum kenarlarında gizlenen güvercinim! 2 Boyunu bosunu göster bana, 2 Sesini duyur; 2 Çünkü sesin tatlı, boyun bosun güzeldir.'),
(2000926,68,22,2,15,'Yakalayın tilkileri bizim için, 2 Bağları bozan küçük tilkileri; 2 Çünkü bağlarımız yeşerdi.'),
(2000927,68,22,2,16,'Sevgilim benimdir, ben de onun, 2 Zambaklar arasında gezinirfç durur.'),
(2000928,68,22,2,17,'Ey sevgilim, gün serinleyip gölgeler uzayana dek, 2 Engebeli dağlar üzerinde bir ceylan gibi, 2 Geyik yavrusu gibi ol!'),
(2000929,68,22,3,1,'Gece boyunca yatağımda 2 Sevgilimi aradım, 2 Aradım, ama bulamadım.'),
(2000930,68,22,3,2,'‹‹Kalkıp kenti dolaşayım, 2 Sokaklarda, meydanlarda sevgilimi arayayım›› dedim, 2 Aradım, ama bulamadım.'),
(2000931,68,22,3,3,'Kenti dolaşan bekçiler buldu beni, 2 ‹‹Sevgilimi gördünüz mü?›› diye sordum.'),
(2000932,68,22,3,4,'Onlardan ayrılır ayrılmaz 2 Sevgilimi buldum. 2 Tuttum onu, bırakmadım; 2 Annemin evine, 2 Beni doğuran kadının odasına götürünceye dek.'),
(2000933,68,22,3,5,'Dişi ceylanlar, 2 Yabanıl dişi geyikler üstüne 2 Ant içiriyorum size, ey Yeruşalim kızları! 2 Aşkımı ayıltmayasınız, uyandırmayasınız diye, 2 Gönlü hoş olana dek.'),
(2000934,68,22,3,6,'Kimdir bu kırdan çıkan, 2 Bir duman sütunu gibi, 2 Tüccarın türlü türlü baharatıyla, 2 Mür ve günnükle tütsülenmiş?'),
(2000935,68,22,3,7,'İşte Süleymanın tahtırevanı! 2 İsrailli yiğitlerden 2 Altmış kişi eşlik ediyor ona.'),
(2000936,68,22,3,8,'Hepsi kılıç kuşanmış, eğitilmiş savaşçı. 2 Gecenin tehlikelerine karşı, 2 Hepsinin kılıcı belinde.'),
(2000937,68,22,3,9,'Kral Süleyman tahtırevanı 2 Lübnan ağaçlarından yaptı.'),
(2000938,68,22,3,10,'Direklerini gümüşten, 2 Tabanını altından yaptı. 2 Koltuğu mor kumaşla kaplıydı. 2 İçini sevgiyle döşemişti Yeruşalim kızları.'),
(2000939,68,22,3,11,'Dışarı çıkın, ey Siyon kızları! 2 Düğününde, mutlu gününde 2 Annesinin verdiği tacı giymiş Kral Süleyman''ı görün.'),
(2000940,68,22,4,1,'Ah, ne güzelsin, aşkım, ah, ne güzel! 2 Peçenin ardındaki gözlerin güvercinler gibi. 2 Siyah saçların Gilat Dağının yamaçlarından inen 2 Keçi sürüsü sanki.'),
(2000941,68,22,4,2,'Yeni kırkılıp yıkanmış, 2 Sudan çıkmış koyun sürüsü gibi dişlerin, 2 Hepsinin ikizi var. 2 Yavrusunu yitiren yok aralarında.'),
(2000942,68,22,4,3,'Al kurdele gibi dudakların, 2 Ağzın ne güzel! 2 Peçenin ardındaki yanakların 2 Nar parçası sanki.'),
(2000943,68,22,4,4,'Boynun Davutun kulesi gibi, 2 Kakma taşlarla yapılmış, 2 Üzerine bin kalkan asılmış, 2 Hepsi de birer yiğit kalkanı. sözcüğün anlamı kesin olarak bilinmiyor.'),
(2000944,68,22,4,5,'Sanki bir çift geyik yavrusu memelerin 2 Zambaklar arasında otlayan 2 İkiz ceylan yavrusu.'),
(2000945,68,22,4,6,'Gün serinleyip gölgeler uzayınca, 2 Mür dağına, 2 Günnük tepesine gideceğim.'),
(2000946,68,22,4,7,'Tepeden tırnağa güzelsin, aşkım, 2 Hiç kusurun yok.'),
(2000947,68,22,4,8,'Benimle gel Lübnandan, yavuklum, 2 Benimle gel Lübnandan! 2 Amana doruğundan, 2 Senir ve Hermon doruklarından, 2 Aslanların inlerinden, 2 Parsların dağlarından geç.'),
(2000948,68,22,4,9,'Çaldın gönlümü kızkardeşim, yavuklum, 2 Bir bakışınla, 2 Gerdanlığının tek zinciriyle çaldın gönlümü!'),
(2000949,68,22,4,10,'Aşkın ne güzel, kızkardeşim, yavuklum, 2 Şaraptan çok daha tatlı; 2 Esansının kokusu her türlü baharattan güzel!'),
(2000950,68,22,4,11,'Ey yavuklum, bal damlar dudaklarından, 2 Bal ve süt var dilinin altında, 2 Lübnanın kokusu geliyor giysilerinden!'),
(2000951,68,22,4,12,'Kapalı bahçesin sen, kızkardeşim, yavuklum, 2 Kapalı bir kaynak, mühürlü bir pınar.'),
(2000952,68,22,4,13,'Fidanların nar bahçesidir; 2 Seçme meyvelerle, 2 Kına ve hintsümbülüyle,'),
(2000953,68,22,4,14,'Hintsümbülü ve safranla, 2 Güzel kokulu kamış ve tarçınla, her türlü günnük ağacıyla, 2 Mür ve ödle, her türlü seçme baharatla.'),
(2000954,68,22,4,15,'Sen bir bahçe pınarısın, 2 Bir taze su kuyusu, 2 Lübnandan akan bir dere.'),
(2000955,68,22,4,16,'Uyan, ey kuzey rüzgarı, 2 Sen de gel, ey güney rüzgarı! 2 Bahçemde es de güzel kokusu saçılsın. 2 Sevgilim bahçesine gelsin, seçme meyvelerini yesin!'),
(2000956,68,22,5,1,'Bahçeme girdim, kızkardeşim, yavuklum, 2 Mürümü topladım baharatımla, 2 Gümecimi, balımı yedim, 2 Şarabımı, sütümü içtim. Yiyin, için, ey dostlar! 2 Mest olun aşktan, ey sevgililer!'),
(2000957,68,22,5,2,'Ben uyuyordum ama yüreğim uyanıktı. 2 Dinleyin! Sevgilim kapıyı vuruyor. 2 ‹‹Aç bana, kızkardeşim, aşkım, eşsiz güvercinim! 2 Sırılsıklam oldu başım çiyden, 2 Kaküllerim gecenin neminden.››'),
(2000958,68,22,5,3,'Entarimi çıkardım, 2 Yine giyinmeli miyim? 2 Ayaklarımı yıkadım, 2 Yine kirletmeli miyim?'),
(2000959,68,22,5,4,'Kapı deliğinden uzattı elini sevgilim, 2 Aşk duygularım kabardı onun için.'),
(2000960,68,22,5,5,'Kalktım, sevgilime kapıyı açayım diye, 2 Mür elimden damladı, 2 Parmaklarımdan aktı 2 Sürgü tokmakları üzerine.'),
(2000961,68,22,5,6,'Kapıyı açtım sevgilime, 2 Ama sevgilim yoktu, gitmişti! 2 Kendimden geçmişim o konuşurken. 2 Aradım onu, ama bulamadım, 2 Seslendim, ama yanıt vermedi.'),
(2000962,68,22,5,7,'Kenti dolaşan bekçiler buldu beni, 2 Dövüp yaraladılar. 2 Sur bekçileri alıp götürdü şalımı.'),
(2000963,68,22,5,8,'Size ant içiriyorum, ey Yeruşalim kızları! 2 Eğer sevgilimi bulursanız, 2 Söyleyin ona, aşk hastasıyım ben.'),
(2000964,68,22,5,9,'Farkı ne sevgilinin öbürlerinden, 2 Ey güzeller güzeli? 2 Farkı ne ki, bize böyle ant içiriyorsun?'),
(2000965,68,22,5,10,'Sevgilimin teni pembe-beyaz, ışıl ışıl yanıyor! 2 Göze çarpıyor on binler arasında.'),
(2000966,68,22,5,11,'Başı saf altın, 2 Kakülleri kıvır kıvır, kuzgun gibi siyah.'),
(2000967,68,22,5,12,'Akarsu kıyısındaki 2 Güvercinler gibi gözleri; 2 Sütle yıkanmış, 2 Yuvasındaki mücevher sanki.'),
(2000968,68,22,5,13,'Yanakları güzel kokulu tarhlar gibi, 2 Nefis kokular saçıyor. 2 Dudakları zambak gibi, 2 Mür yağı damlatıyor.'),
(2000969,68,22,5,14,'Elleri, üzerine sarı yakut kakılmış altın çubuklar, 2 Gövdesi laciverttaşıyla süslenmiş cilalı fildişi.'),
(2000970,68,22,5,15,'Mermer sütun bacakları 2 Saf altın ayaklıklar üzerine kurulmuş. 2 Boyu bosu Lübnan dağları gibi, 2 Lübnanın sedir ağaçları gibi eşsiz.'),
(2000971,68,22,5,16,'Ağzı çok tatlı, 2 Tepeden tırnağa güzel. 2 İşte böyledir sevgilim, böyledir yarim, ey Yeruşalim kızları!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2000972,68,22,6,1,'Nereye gitti sevgilin, 2 Ey güzeller güzeli, 2 Ne yana yöneldi? 2 Biz de onu arayalım seninle birlikte!'),
(2000973,68,22,6,2,'Bahçesine indi sevgilim, 2 Güzel kokulu tarhlara, 2 Bahçede gezinmek, zambak toplamak için.'),
(2000974,68,22,6,3,'Ben sevgilime aitim, sevgilim de bana, 2 Gezinip duruyor zambaklar arasında.'),
(2000975,68,22,6,4,'Sevgilim, Tirsa kadar güzelsin, 2 Yeruşalim kadar şirin, 2 Sancak açmış bir ordu kadar görkemli. ‹‹Hoş, güzel›› anlamına gelir.'),
(2000976,68,22,6,5,'Çevir gözlerini benden, 2 Çünkü şaşırtıyorlar beni. 2 Gilat Dağının yamaçlarından inen 2 Keçi sürüsünü andırıyor siyah saçların.'),
(2000977,68,22,6,6,'Yeni yıkanmış, sudan çıkmış dişi koyun sürüsü gibi dişlerin, 2 Hepsinin ikizi var; 2 Yavrusunu yitiren yok aralarında.'),
(2000978,68,22,6,7,'Peçenin ardındaki yanakların 2 Nar parçası sanki.'),
(2000979,68,22,6,8,'Altmış kraliçe, 2 Seksen cariye, 2 Sayısız bakire kız olabilir;'),
(2000980,68,22,6,9,'Ama bir tanedir benim eşsiz güvercinim, 2 Biricik kızıdır annesinin, 2 Gözbebeği kendisini doğuranın. 2 Kızlar sevgilimi görünce, ‹‹Ne mutlu ona!›› dediler. 2 Kraliçeler, cariyeler onu övdüler.'),
(2000981,68,22,6,10,'Kimdir bu kadın? 2 Şafak gibi beliren, 2 Ay kadar güzel, 2 Güneş kadar parlak, 2 Sancak açmış bir ordu kadar görkemli.'),
(2000982,68,22,6,11,'Ceviz bahçesine indim, 2 Yeşermiş vadiyi göreyim diye; 2 Asma tomurcuk verdi mi, 2 Narlar çiçek açtı mı bakayım diye.'),
(2000983,68,22,6,12,'Nasıl oldu farkına varmadan, 2 Tutkum bindirdi beni soylu halkımın savaş arabalarına.'),
(2000984,68,22,6,13,'Dön, geri dön, ey Şulamlı kız, 2 Dön, geri dön de seni seyredelim. Niçin Şulamlı kızı seyretmek istiyorsunuz, 2 Mahanayim oyununu seyredercesine? anlamına gelebilir.'),
(2000985,68,22,7,1,'Ne güzel sandaletli ayakların, 2 Ey soylu kız! 2 Mücevher gibi yuvarlak kalçaların, 2 Usta ellerin işi.'),
(2000986,68,22,7,2,'Karışık şarabın hiç eksilmediği 2 Yuvarlak bir tas gibi göbeğin. 2 Zambaklarla kuşanmış 2 Buğday yığını gibi karnın.'),
(2000987,68,22,7,3,'Sanki bir çift geyik yavrusu memelerin, 2 İkiz ceylan yavrusu.'),
(2000988,68,22,7,4,'Fildişi kule gibi boynun. 2 Bat-Rabim Kapısı yanındaki 2 Heşbon havuzları gibi gözlerin. 2 Şama bakan 2 Lübnan Kulesi gibi burnun.'),
(2000989,68,22,7,5,'Karmel Dağı gibi duruyor başın, 2 Pırıl pırıl mora çalar saçların. 2 Kaküllerine tutsak oldu kral.'),
(2000990,68,22,7,6,'Ne güzel, ne çekicidir aşk! 2 Zevkten zevke sürükler.'),
(2000991,68,22,7,7,'Hurma ağacına benziyor boyun, 2 Salkım salkım memelerin.'),
(2000992,68,22,7,8,'‹‹Çıkayım hurma ağacına›› dedim, 2 ‹‹Tutayım meyveli dallarını.›› 2 Üzüm salkımları gibi olsun memelerin, 2 Elma gibi koksun soluğun,'),
(2000993,68,22,7,9,'En iyi şarap gibi ağzın. Sevgilimin dudaklarına, dişlerine doğru kaysın. metin ‹‹Uyuyanların dudaklarına››.'),
(2000994,68,22,7,10,'Ben sevgilime aitim, 2 O da bana tutkun.'),
(2000995,68,22,7,11,'Gel, sevgilim, kıra çıkalım, 2 Köylerdefı geceleyelim.'),
(2000996,68,22,7,12,'Bağlara gidelim sabah erkenden, 2 Bakalım, asma tomurcuk verdi mi? 2 Dalları yeşerdi mi, 2 Narlar çiçek açtı mı, 2 Orada sevişeceğim seninle.'),
(2000997,68,22,7,13,'Mis gibi koku saçıyor adamotları, 2 Kapımızın yanıbaşında 2 Taze, kuru, 2 Her çeşit seçme meyve var. 2 Senin için sakladım onları, sevgilim.'),
(2000998,68,22,8,1,'Keşke kardeşim olsaydın, 2 Annemin memelerinden süt emmiş. 2 Dışarıda görünce öperdim seni, 2 Kimse de kınamazdı beni.'),
(2000999,68,22,8,2,'Önüne düşer, 2 Beni eğiten 2 Annemin evine götürürdüm seni; 2 Sana baharatlı şarapla 2 Kendi narlarımın suyundan içirirdim.'),
(2001000,68,22,8,3,'Sol eli başımın altında, 2 Sağ eli sarsın beni.'),
(2001001,68,22,8,4,'Ant içiriyorum size, ey Yeruşalim kızları! 2 Aşkımı ayıltmayasınız, uyandırmayasınız diye, 2 Gönlü hoş olana dek.'),
(2001002,68,22,8,5,'Kim bu, 2 Sevgilisine yaslanarak çölden çıkan? Elma ağacı altında uyandırdım seni, 2 Orada doğum sancıları çekti annen, 2 Orada doğum sancıları çekip doğurdu seni.'),
(2001003,68,22,8,6,'Beni yüreğinin üzerine bir mühür gibi, 2 Kolunun üzerine bir mühür gibi yerleştir. 2 Çünkü sevgi ölüm kadar güçlü, 2 Tutku ölüler diyarı kadar katıdır. 2 Alev alev yanar, 2 Yakıp bitiren ateş gibi.'),
(2001004,68,22,8,7,'Sevgiyi engin sular söndüremez, 2 Irmaklar süpürüp götüremez. 2 İnsan varını yoğunu sevgi uğruna verse bile, 2 Yine de hor görülür!'),
(2001005,68,22,8,8,'Küçük bir kızkardeşimiz var, 2 Daha memeleri çıkmadı. 2 Ne yapacağız kızkardeşimiz için, 2 Söz kesileceği gün?'),
(2001006,68,22,8,9,'Eğer o bir sursa, 2 Üzerine gümüş mazgallı siper yaparız; 2 Eğer bir kapıysa, 2 Sedir tahtalarıyla onu kaplarız.'),
(2001007,68,22,8,10,'Ben bir surum, memelerim de kuleler gibi, 2 Böylece hoşnut eden biri oldum onun gözünde.'),
(2001008,68,22,8,11,'Süleymanın bağı vardı Baal-Hamonda, 2 Kiraya verdi bağını; 2 Her biri bin gümüş öderdi ürünü için.'),
(2001009,68,22,8,12,'Benim bağım kendi emrimde, 2 Bin gümüş senin olsun, ey Süleyman, 2 İki yüz gümüş de ürününe bakan kiracıların.'),
(2001010,68,22,8,13,'Ey sen, bahçelerde oturan kadın, 2 Arkadaşlar kulak veriyor sesine, 2 Bana da duyur onu.'),
(2001011,68,22,8,14,'Koş, sevgilim, 2 Mis kokulu dağların üzerinde bir ceylan gibi, 2 Geyik yavrusu gibi ol!'),
(2001012,68,23,1,1,'Yahuda kralları Uzziya, Yotam, Ahaz ve Hizkiya zamanında Amots oğlu Yeşayanın Yahuda ve Yeruşalimle ilgili görümü:'),
(2001013,68,23,1,2,'Ey gökler dinleyin, ey yeryüzü kulak ver! 2 Çünkü RAB konuşuyor: 2 ‹‹Çocuklar yetiştirip büyüttüm, 2 Ama bana başkaldırdılar.'),
(2001014,68,23,1,3,'Öküz sahibini, eşek efendisinin yemliğini bilir, 2 Ama İsrail halkı bu kadarını bile bilmiyor, 2 Halkım anlamıyor.››'),
(2001015,68,23,1,4,'Günahlı ulusun, suç yüklü halkın, 2 Kötülük yapan soyun, 2 Baştan çıkmış çocukların vay haline! 2 RABbi terk ettiler, 2 İsrailin Kutsalını hor gördüler, 2 Ona sırt çevirdiler.'),
(2001016,68,23,1,5,'Neden bir daha dövülesiniz? 2 Neden vefasızlığı sürdürüyorsunuz? 2 Baş büsbütün hasta, yürek büsbütün yaralı.'),
(2001017,68,23,1,6,'Bedeniniz tepeden tırnağa sağlıksız, 2 Taze darbe izleriyle, yara bereyle dolu, 2 Temizlenmemiş, yağla yumuşatılmamış, sarılmamış.'),
(2001018,68,23,1,7,'Ülkeniz ıssız, kentleriniz ateşe verilmiş. 2 Yabancılar topraklarınızı 2 Gözünüzün önünde yiyip bitiriyor! 2 Sanki ülkenin kökünü kazımışlar.'),
(2001019,68,23,1,8,'Siyon kızı bağdaki çardak, 2 Salatalık bostanındaki kulübe gibi, 2 Kuşatılmış bir kent gibi kalakalmış.'),
(2001020,68,23,1,9,'Her Şeye Egemen RAB bazılarımızı 2 Sağ bırakmamış olsaydı, 2 Sodom gibi olur, Gomoraya benzerdik.'),
(2001021,68,23,1,10,'Ey Sodom yöneticileri, 2 RABbin söylediklerini dinleyin; 2 Ey Gomora halkı, 2 Tanrımızın yasasına kulak verin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001022,68,23,1,11,'‹‹Kurbanlarınızın sayısı çokmuş, 2 Bana ne?›› diyor RAB, 2 ‹‹Yakmalık koç sunularına, 2 Besili hayvanların yağına doydum. 2 Boğa, kuzu, teke kanı değil istediğim.'),
(2001023,68,23,1,12,'Huzuruma geldiğinizde 2 Avlularımı çiğnemenizi mi istedim sizden?'),
(2001024,68,23,1,13,'Anlamsız sunular getirmeyin artık. 2 Buhurdan iğreniyorum. 2 Kötülük dolu törenlere, 2 Yeni Ay, Şabat Günü kutlamalarına 2 Ve düzenlediğiniz toplantılara dayanamıyorum.'),
(2001025,68,23,1,14,'Yeni Ay törenlerinizden, bayramlarınızdan nefret ediyorum. 2 Bunlar bana yük oldu, 2 Onları taşımaktan yoruldum.'),
(2001026,68,23,1,15,'‹‹Ellerinizi açıp bana yakardığınızda 2 Gözlerimi sizden kaçıracağım. 2 Ne kadar çok dua ederseniz edin dinlemeyeceğim. 2 Elleriniz kan dolu.'),
(2001027,68,23,1,16,'Yıkanıp temizlenin, 2 Kötülük yaptığınızı gözüm görmesin, 2 Kötülük etmekten vazgeçin.'),
(2001028,68,23,1,17,'İyilik etmeyi öğrenin, 2 Adaleti gözetin, zorbayı yola getirin, 2 Öksüzün hakkını verin, 2 Dul kadını savunun.››'),
(2001029,68,23,1,18,'RAB diyor ki, 2 ‹‹Gelin, şimdi davamızı görelim. 2 Günahlarınız sizi kana boyamış bile olsa 2 Kar gibi ak pak olacaksınız. 2 Elleriniz kırmız böceği gibi kızıl olsa da 2 Yapağı gibi bembeyaz olacak.'),
(2001030,68,23,1,19,'İstekli olur, söz dinlerseniz, 2 Ülkenin en iyi ürünlerini yiyeceksiniz.'),
(2001031,68,23,1,20,'Ama direnip başkaldırırsanız, 2 Kılıç sizi yiyip bitirecek.›› 2 Bunu söyleyen RABdir.'),
(2001032,68,23,1,21,'Sadık kent nasıl da fahişe oldu! 2 Adaletle doluydu, doğruluğun barınağıydı, 2 Şimdiyse katillerle doldu.'),
(2001033,68,23,1,22,'Gümüşü cüruf oldu, 2 Şarabına su katıldı.'),
(2001034,68,23,1,23,'Yöneticileri asilerle hırsızların işbirlikçisi; 2 Hepsi rüşveti seviyor, 2 Armağan peşine düşmüş. 2 Öksüzün hakkını vermiyor, 2 Dul kadının davasını görmüyorlar.'),
(2001035,68,23,1,24,'Bu yüzden Rab, Her Şeye Egemen RAB, 2 İsrailin Güçlüsü şöyle diyor: 2 ‹‹Hasımlarımı cezalandırıp rahata kavuşacağım, 2 Düşmanlarımdan öç alacağım.'),
(2001036,68,23,1,25,'Sana karşı duracak, 2 Kül suyuyla arıtır gibi seni cüruftan arıtıp temizleyeceğim.'),
(2001037,68,23,1,26,'Eskiden, başlangıçta olduğu gibi, 2 Sana yöneticiler, danışmanlar yetiştireceğim. 2 Ondan sonra ‹Doğruluk Kenti›, 2 ‹Sadık Kent› diye adlandırılacaksın.››'),
(2001038,68,23,1,27,'Siyon adalet sayesinde, 2 Tövbe edenleri de doğruluk sayesinde kurtulacak.'),
(2001039,68,23,1,28,'Ama başkaldıranlarla günahlılar 2 Birlikte yıkıma uğrayacaklar. 2 RABbi terk edenler yok olacak.'),
(2001040,68,23,1,29,'‹‹Sevip altında tapındığınız yabanıl fıstık ağaçlarından utanacaksınız, 2 Putperest törenleriniz için seçtiğiniz bahçelerden ötürü yüzünüz kızaracak.'),
(2001041,68,23,1,30,'Yaprakları solmuş yabanıl fıstık ağacına, 2 Susuz bahçeye döneceksiniz.'),
(2001042,68,23,1,31,'Güçlü adamlarınız kıtık gibi, 2 Yaptıkları işler kıvılcım gibi olacak; 2 İkisi birlikte yanacak ve söndüren olmayacak.››'),
(2001043,68,23,2,1,'Amots oğlu Yeşayanın Yahuda ve Yeruşalimle ilgili görümü:'),
(2001044,68,23,2,2,'RABbin Tapınağının kurulduğu dağ, 2 Son günlerde dağların en yücesi, 2 Tepelerin en yükseği olacak. 2 Oraya akın edecek ulusların hepsi.'),
(2001045,68,23,2,3,'Birçok halk gelecek, 2 ‹‹Haydi, RABbin Dağına, 2 Yakupun Tanrısının Tapınağına çıkalım›› diyecekler, 2 ‹‹O bize kendi yolunu öğretsin, 2 Biz de Onun yolundan gidelim.›› 2 Çünkü yasa Siyondan, 2 RABbin sözü Yeruşalimden çıkacak.'),
(2001046,68,23,2,4,'RAB uluslar arasında yargıçlık edecek, 2 Birçok halkın arasındaki anlaşmazlıkları çözecek. 2 İnsanlar kılıçlarını çekiçle dövüp saban demiri, 2 Mızraklarını bağcı bıçağı yapacaklar. 2 Ulus ulusa kılıç kaldırmayacak, 2 Savaş eğitimi yapmayacaklar artık.'),
(2001047,68,23,2,5,'Ey Yakup soyu, gelin RABbin ışığında yürüyelim.'),
(2001048,68,23,2,6,'Ya RAB, halkını, Yakup soyunu terk ettin, 2 Çünkü yürekleri doğu kökenli inançlarla dolu. 2 Filistliler gibi falcılıkla uğraşıyor, 2 Yabancılarla el sıkışıyorlar.'),
(2001049,68,23,2,7,'Ülkeleri altınla, gümüşle dolu, 2 Hazinelerinin sonu yok, 2 Sayısız atları, savaş arabaları var.'),
(2001050,68,23,2,8,'Ülkeleri putlarla dolu; 2 Elleriyle yaptıkları, 2 Parmaklarıyla biçim verdikleri 2 Putların önünde eğiliyorlar.'),
(2001051,68,23,2,9,'Bu yüzden herkes alçaltılıp dize getirilecek. 2 Onları bağışlama, ya RAB!'),
(2001052,68,23,2,10,'RABbin dehşetinden, 2 Yüce görkeminden kaçmak için kayalıklara gidin, 2 Yerin altına saklanın.'),
(2001053,68,23,2,11,'İnsanın küstah bakışları alçaltılacak, 2 Gururu kırılacak. 2 O gün yalnız RAB yüceltilecek.'),
(2001054,68,23,2,12,'Çünkü Her Şeye Egemen RAB o gün 2 Kibirlileri, gururluları, kendini beğenmişleri alçaltacak;'),
(2001055,68,23,2,13,'Lübnanın bütün ulu, yüksek sedir ağaçlarını, 2 Başanın bütün meşelerini yok edecek;'),
(2001056,68,23,2,14,'Bütün ulu dağları, yüksek tepeleri,'),
(2001057,68,23,2,15,'Bütün yüksek kuleleri, güçlü surları 2 Yerle bir edecek;'),
(2001058,68,23,2,16,'Ticaret gemilerinin, güzel teknelerinin hepsini yok edecek.'),
(2001059,68,23,2,17,'İnsanların gururu, kibiri kırılacak, 2 O gün yalnız RAB yüceltilecek,'),
(2001060,68,23,2,18,'Putlar tümüyle ortadan kalkacak.'),
(2001061,68,23,2,19,'RAB kalkıp yeryüzünü sarsmaya başlayınca, 2 İnsanlar Onun dehşetinden 2 Ve yüce görkeminden kaçmak için 2 Kayalık mağaralara, yeraltı kovuklarına saklanacaklar.'),
(2001062,68,23,2,20,'O gün insanlar 2 Yeryüzünü sarsmak üzere harekete geçen RABbin dehşetinden 2 Ve yüce görkeminden kaçmak için 2 Tapmak amacıyla yaptıkları altın, gümüş putları 2 Köstebeklere, yarasalara atıp 2 Kaya kovuklarına, uçurumlardaki yarıklara saklanacaklar.'),
(2001063,68,23,2,22,'Ölümlü insana güvenmekten vazgeçin. 2 Onun ne değeri var ki?'),
(2001064,68,23,3,1,'Bakın, Rab, Her Şeye Egemen RAB, 2 Her türlü yardım ve desteği, 2 Yani ekmek ve suyu, 2 Yiğitlerle savaşçıları, 2 Yöneticilerle peygamberleri, 2 Falcılarla ileri gelenleri, 2 Takım komutanlarıyla soyluları, danışmanları, 2 Hünerli büyücülerle bilge muskacıları 2 Yeruşalimden ve Yahudadan çekip alacak.'),
(2001065,68,23,3,4,'Çocukları onlara yönetici atayacak, 2 Küçük çocuklar onlara egemen olacak.'),
(2001066,68,23,3,5,'İnsan insana, komşu komşuya haksızlık edecek. 2 Genç yaşlıya, 2 Sıradan adam onurlu kişiye 2 Hayasızca davranacak.'),
(2001067,68,23,3,6,'Ailede bir kardeş öbürüne sarılıp, 2 ‹‹Hiç olmazsa senin bir üstlüğün var, 2 Önderimiz ol! Bu yıkıntıları sen yönet›› diyecek.'),
(2001068,68,23,3,7,'O zaman adam şöyle yanıtlayacak: 2 ‹‹Ben yaranızı saramam. 2 Evimde ne yiyecek ne giyecek var. 2 Beni halkın önderi yapmayın.››'),
(2001069,68,23,3,8,'Yeruşalim sendeledi, Yahuda düştü. 2 Çünkü söyledikleri de yaptıkları da RABbe karşı; 2 Onun yüce varlığını aşağılıyor.'),
(2001070,68,23,3,9,'Yüzlerindeki ifade onlara karşı tanıklık ediyor. 2 Sodom gibi günahlarını açıkça söylüyor, gizlemiyorlar. 2 Vay onların haline! 2 Çünkü bu felaketi başlarına kendileri getirdiler.'),
(2001071,68,23,3,10,'Doğru kişiye iyilik göreceğini söyleyin. 2 Çünkü iyiliklerinin meyvesini yiyecek.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001072,68,23,3,11,'Vay kötülerin haline! 2 Kötülük görecek, yaptıklarının karşılığını alacaklar.'),
(2001073,68,23,3,12,'Çocuklar halkımı eziyor, 2 Kadınlar onu yönetiyor. 2 Ey halkım, sana yol gösterenler 2 Seni saptırıyor, yolunu şaşırtıyorlar. da ‹‹Yetkililer halkımı eziyor, tefeciler başa geçti››.'),
(2001074,68,23,3,13,'RAB davasını görmek için yerini aldı, 2 Halkları yargılamak için ayağa kalkıyor.'),
(2001075,68,23,3,14,'RAB halkının ileri gelenleri ve önderleriyle davasını görecek. 2 Rab, Her Şeye Egemen RAB onlara diyor ki, 2 ‹‹Bağları yiyip bitiren sizsiniz, 2 Evleriniz yoksullardan zorla aldığınız malla dolu. 2 Ne hakla halkımı eziyor, 2 Yoksulu sömürüyorsunuz?››'),
(2001076,68,23,3,16,'RAB şöyle diyor: ‹‹Siyon kızları kibirlidir, burunları bir karış havada, göz kırparak geziyor, ayaklarındaki halhalları şıngırdatarak kırıtıyorlar.'),
(2001077,68,23,3,17,'Bu yüzden onların başlarında yaralar çıkaracağım, mahrem yerlerini açacağım.››'),
(2001078,68,23,3,18,'O gün Rab güzel halhalları, alın çatkılarını, hilalleri, küpeleri, bilezikleri, peçeleri, başlıkları, ayak zincirlerini, kuşakları, koku şişelerini, muskaları, yüzükleri, burun halkalarını, bayramlık giysileri, pelerinleri, şalları, keseleri, el aynalarını, keten giysileri, baş sargılarını, tülbentleri ortadan kaldıracak.'),
(2001079,68,23,3,24,'O zaman güzel kokunun yerini pis koku, 2 Kuşağın yerini ip, 2 Lüleli saçın yerini kel kafa, 2 Süslü giysinin yerini çul, 2 Güzelliğin yerini dağlama izi alacak.'),
(2001080,68,23,3,25,'Erkekleri kılıçtan geçirilecek, 2 Yiğitleri savaşta yok olacak.'),
(2001081,68,23,3,26,'Siyon''un kapıları ah çekip yas tutacak; 2 Kent, yerde oturan, 2 Terk edilmiş bir kadın gibi olacak.'),
(2001082,68,23,4,1,'O gün yedi kadın bir erkeği tutup, ‹‹Kendi yemeğimizi de giysimizi de sağlarız; yeter ki senin adını alalım. Utancımızı gider!›› diyecekler.'),
(2001083,68,23,4,2,'O gün RABbin dalı, İsrail halkından sağ kalanların güzelliği ve görkemi olacak; ülkenin meyvesi de onların kıvancı ve övüncü olacak.'),
(2001084,68,23,4,3,'Siyonda, yani Yeruşalimde sağ kalanlara, ‹‹Yeruşalimde yaşıyor›› diye kaydedilenlere, ‹‹Kutsal›› denilecek.'),
(2001085,68,23,4,4,'Rab Siyon kızlarını pisliklerinden arındıracak. Yeruşalimde dökülen kanı adil ve ateşten bir ruhla temizleyecek.'),
(2001086,68,23,4,5,'Sonra RAB Siyon Dağının her yanını, orada toplananların üzerini gündüz bulutla, gece dumanla ve parlak alevle örtecek. Yüceliği onların üzerinde bir örtü olacak.'),
(2001087,68,23,4,6,'Bu, bir çardak, gündüzün sıcağına karşı gölge, yağmura, fırtınaya karşı sığınak ve korunak olacak.'),
(2001088,68,23,5,1,'Sevgilimin bağı için yaktığı ezgiyi sevgilim için okuyayım: 2 Toprağı verimli bir tepede 2 Sevgilimin bir bağı vardı.'),
(2001089,68,23,5,2,'Toprağı belleyip taşları ayıkladı, 2 Seçme asmalar dikip orta yere bir gözcü kulesi yaptı. 2 Üzüm sıkmak için bir çukur kazdı 2 Ve bağının üzüm vermesini bekledi. 2 Ama bağ yabanıl üzüm verdi.'),
(2001090,68,23,5,3,'Sevgilim diyor ki, ‹‹Ey Yeruşalimde yaşayanlar ve Yahuda halkı, lütfen benimle bağım arasında hakem olun!'),
(2001091,68,23,5,4,'Bağım için yapmadığım ne kaldı? Ben üzüm vermesini beklerken niçin yabanıl üzüm verdi?'),
(2001092,68,23,5,5,'Şimdi bağıma ne yapacağımı size söyleyeyim: Çitini söküp atacağım, varsın yiyip bitirsinler; duvarını yıkacağım, varsın çiğnesinler.'),
(2001093,68,23,5,6,'Viraneye çevireceğim onu; budanmayacak, çapalanmayacak; dikenli çalılar bitecek her yanında. Üzerine yağmur yağdırmasınlar diye bulutlara buyruk vereceğim.››'),
(2001094,68,23,5,7,'Her Şeye Egemen RABbin bağı İsrail halkı, 2 Hoşlandığı fidan da Yahuda halkıdır. 2 RAB adalet bekledi, 2 Zorbalık gördü; 2 Doğruluk bekledi, 2 Feryatlar duydu.'),
(2001095,68,23,5,8,'Evlerine ev, tarlalarına tarla katanların vay haline! 2 Oturacak yer kalmadı, 2 Ülkede bir tek siz oturuyorsunuz.'),
(2001096,68,23,5,9,'Her Şeye Egemen RABbin şöyle ant içtiğini duydum: 2 ‹‹Büyük ve gösterişli çok sayıda ev ıssız kalacak, 2 İçinde oturan olmayacak.'),
(2001097,68,23,5,10,'Çünkü on dönümlük bağ ancak bir bat şarap, 2 Bir homerfç tohum ancak bir efa tahıl üretecek.›› işleyebileceği alan›› anlamına gelir.'),
(2001098,68,23,5,11,'Sabah erkenden kalkıp içki peşinden koşanların, gece geç vakte kadar şarap içip kızışanların vay haline!'),
(2001099,68,23,5,12,'Onların şölenlerinde lir, çenk, tef ve kaval çalınır, şarap içilir. Ama RABbin yaptıklarına dikkat etmez, ellerinin yapıtına aldırmazlar.'),
(2001100,68,23,5,13,'Halkım bilgisizliği yüzünden sürgün edilecek; saygın kişileri kıtlıktan ölecek, kalabalıklar susuzluktan kırılacak.'),
(2001101,68,23,5,14,'Bu yüzden doymak bilmeyen ölüler diyarı ağzını ardına kadar açtı; Yeruşalimin soyluları, sıradan insanları ve gürültülü bir şekilde eğlenenleri oraya inecek.'),
(2001102,68,23,5,15,'Hepsi alçaltılacak; dize getirilecek, küstah bakışları alçaltılacak.'),
(2001103,68,23,5,16,'Ama Her Şeye Egemen RAB adaletinden ötürü yüceltilecek. Kutsal Tanrı doğruluğuyla kutsal olduğunu gösterecek.'),
(2001104,68,23,5,17,'Kuzular kendi otlaklarındaymış gibi otlayacak, zenginlerin ıssız kalan konutlarını yabancılar ele geçirecek.'),
(2001105,68,23,5,18,'Suçu yalanla örülmüş iplerle, günahı araba urganıyla çekenlerin vay haline!'),
(2001106,68,23,5,19,'Diyorlar ki, ‹‹Tanrı elini çabuk tutup işini hızlandırsın da görelim. İsrailin Kutsalı tasarladığını yapsın da görelim.››'),
(2001107,68,23,5,20,'Kötüye iyi, iyiye kötü diyenlerin, karanlığı ışık, ışığı karanlık yerine koyanların, acıya tatlı, tatlıya acı diyenlerin vay haline!'),
(2001108,68,23,5,21,'Kendilerini bilge görenlerin, akıllı sananların vay haline!'),
(2001109,68,23,5,22,'Şarap içmekte sınır tanımayanların, içkileri karıştırıp içmekten çekinmeyenlerin, rüşvet uğruna kötüyü haklı çıkaranların, haklıların hakkını elinden alanların vay haline!'),
(2001110,68,23,5,24,'Alev alev yanan ateş, samanı nasıl yiyip bitirirse, kuru ot alevin içinde nasıl birden tutuşup yok olursa, onlar da kökten çürüyüp gidecek, çiçekleri toz gibi havaya savrulacak. Çünkü Her Şeye Egemen RABbin yasasını reddettiler, İsrailin Kutsalının sözlerini küçümsediler.'),
(2001111,68,23,5,25,'Bu yüzden RABbin halkına karşı öfkesi alevlendi, elini kaldırıp onları vurdu. Dağlar titriyor, cesetler çöp gibi sokaklara serildi. Bütün bunlara karşın RABbin öfkesi dinmedi, eli hâlâ kalkmış durumda.'),
(2001112,68,23,5,26,'RAB uzaktaki ulusları bir sancak işaretiyle, dünyanın en uzağındakileri ıslık sesiyle çağıracak; hızla, hemen gelecekler.'),
(2001113,68,23,5,27,'Aralarında yorulan, sendeleyen olmayacak; uyuklamayacak, uyumayacaklar. Gevşek kemer, kopuk çarık bağı olmayacak.'),
(2001114,68,23,5,28,'Okları sivri, yayları kuruludur. Atlarının toynakları çakmaktaşı, arabalarının tekerlekleri kasırga gibidir.'),
(2001115,68,23,5,29,'Askerleri dişi aslan gibi, genç aslanlar gibi kükrüyor, homurdanarak avlarını kapıp götürüyorlar. Kimse avlarını pençelerinden kurtaramıyor.'),
(2001116,68,23,5,30,'O gün İsrail''e karşı denizin gürleyişi gibi gürleyecekler. Karaya bakan biri karanlık ve sıkıntı görecek. Işık karanlık bulutlarla kaplanacak.'),
(2001117,68,23,6,1,'Kral Uzziyanın öldüğü yıl yüce ve görkemli Rabbi gördüm; tahtta oturuyordu, giysisinin etekleri tapınağı dolduruyordu.'),
(2001118,68,23,6,2,'Üzerinde Seraflar duruyordu; her birinin altı kanadı vardı; ikisiyle yüzlerini, ikisiyle ayaklarını örtüyor, öbür ikisiyle de uçuyorlardı.'),
(2001119,68,23,6,3,'Birbirlerine şöyle sesleniyorlardı: ‹‹Her Şeye Egemen RAB 2 Kutsal, kutsal, kutsaldır. 2 Yüceliği bütün dünyayı dolduruyor.››'),
(2001120,68,23,6,4,'Serafların sesinden kapı söveleriyle eşikler sarsıldı, tapınak dumanla doldu.'),
(2001121,68,23,6,5,'‹‹Vay başıma! Mahvoldum›› dedim, ‹‹Çünkü dudakları kirli bir adamım, dudakları kirli bir halkın arasında yaşıyorum. Buna karşın Kralı, Her Şeye Egemen RABbi gözlerimle gördüm.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001122,68,23,6,6,'Seraflardan biri bana doğru uçtu, elinde sunaktan maşayla aldığı bir kor vardı;'),
(2001123,68,23,6,7,'onunla ağzıma dokunarak, ‹‹İşte bu kor dudaklarına değdi, suçun silindi, günahın bağışlandı›› dedi.'),
(2001124,68,23,6,8,'Sonra Rabbin sesini işittim: ‹‹Kimi göndereyim? Bizim için kim gidecek?›› diyordu. ‹‹Ben! Beni gönder›› dedim.'),
(2001125,68,23,6,9,'‹‹Git, bu halka şunu duyur›› dedi, ‹‹ ‹Duyacak duyacak, ama anlamayacaksınız, 2 Bakacak bakacak, ama görmeyeceksiniz!'),
(2001126,68,23,6,10,'Bu halkın yüreğini duygusuzlaştır, 2 Kulaklarını ağırlaştır, 2 Gözlerini kapat. 2 Öyle ki, gözleri görmesin, 2 Kulakları duymasın, yürekleri anlamasın 2 Ve bana dönüp şifa bulmasınlar.› ››'),
(2001127,68,23,6,11,'‹‹Ne vakte kadar, ya Rab?›› diye sordum. Rab yanıtladı: ‹‹Kentler viraneye dönüp kimsesiz kalıncaya, 2 Evler ıpıssız oluncaya, 2 Toprak büsbütün kıraçlaşıncaya kadar.'),
(2001128,68,23,6,12,'İnsanları çok uzaklara süreceğim, 2 Ülke bomboş kalacak,'),
(2001129,68,23,6,13,'Halkın onda biri kalsa da ülke mahvolacak. 2 Ama devrildiği zaman kütüğü kalan 2 Yabanıl fıstık ve meşe ağacı gibi, 2 Kutsal soy kütüğünden çıkacak.››'),
(2001130,68,23,7,1,'Uzziya oğlu Yotam oğlu Ahaz Yahuda Kralıyken, Aram Kralı Resinle Remalya oğlu İsrail Kralı Pekah Yeruşalime saldırdılar, ama ele geçiremediler.'),
(2001131,68,23,7,2,'Davutun torunları Aramın Efrayimlilerle güçbirliği ettiğini duydular. Ahazla halkının yürekleri rüzgarda sallanan orman ağaçları gibi titremeye başladı.'),
(2001132,68,23,7,3,'Bu arada RAB Yeşayaya şöyle seslendi: ‹‹Ahazı karşılamak için oğlun Şear-Yaşuvla birlikte Yukarı Havuzun su yolunun sonuna, Çırpıcı Tarlasına giden yola çık.'),
(2001133,68,23,7,4,'Ona de ki, ‹Dikkatli ve sakin ol, korkma! Şu tüten iki yanık odun parçasının -Aram Kralı Resinle Remalyanın oğlunun- öfkesinden korkma.'),
(2001134,68,23,7,5,'Aram, Efrayim ve Remalyanın oğlu sizin için kötü şeyler tasarlıyor. Diyorlar ki,'),
(2001135,68,23,7,6,'Haydi, Yahudaya saldıralım, halkı korkutup ülkeyi ele geçirelim, Tavealın oğlunu kral ilan edelim.'),
(2001136,68,23,7,7,'‹‹ ‹Buna karşılık Egemen RAB diyor ki, bu tasarı asla gerçekleşmeyecek.'),
(2001137,68,23,7,8,'Çünkü Şam sadece Aramın başkenti, Resin de sadece Şamın başıdır. Efrayime gelince, altmış beş yıl içinde paramparça edilip halk olmaktan çıkacak.'),
(2001138,68,23,7,9,'Samiriye sadece Efrayimin başkenti, Remalyanın oğlu da sadece Samiriyenin başıdır. Bana güvenmezseniz, güvenlikte olamazsınız.› ››'),
(2001139,68,23,7,10,'RAB Ahaza yine seslendi:'),
(2001140,68,23,7,11,'‹‹Tanrın RABden bir işaret iste; ölüler diyarı kadar derin, gökler kadar yüksek olsun.››'),
(2001141,68,23,7,12,'Ama Ahaz, ‹‹Hayır, istemem, RABbi sınamam›› dedi.'),
(2001142,68,23,7,13,'Bunun üzerine Yeşaya, ‹‹Dinleyin, ey Davutun torunları!›› dedi, ‹‹İnsanların sabrını taşırmanız yetmezmiş gibi şimdi de Tanrımın sabrını mı taşırıyorsunuz?'),
(2001143,68,23,7,14,'Bundan ötürü Rabbin kendisi size bir belirti verecek: İşte, kız gebe kalıp bir oğul doğuracak; adını İmmanuel koyacak.'),
(2001144,68,23,7,15,'Çocuk kötüyü reddedip iyiyi seçecek yaşa gelince tereyağı ve bal yiyecek.'),
(2001145,68,23,7,16,'Ama çocuk kötüyü reddedip iyiyi seçecek yaşa gelmeden, seni dehşete düşüren o iki kralın toprakları ıssız kalacak.'),
(2001146,68,23,7,17,'‹‹RAB seni, halkını ve babanın soyunu Efrayimin Yahudadan ayrıldığı günden bu yana görülmemiş bir felakete uğratacak; üzerinize Asur Kralını saldırtacak.'),
(2001147,68,23,7,18,'‹‹O gün RAB Mısır ırmaklarının ta uçlarından sinekleri, Asur topraklarından arıları ıslıkla çağıracak.'),
(2001148,68,23,7,19,'Akın akın gelip derin vadilerde, kaya kovuklarında, dikenli çalılıklarda, otlaklarda konaklayacaklar.'),
(2001149,68,23,7,20,'‹‹O gün Rab Fıratın ötesinden kiraladığı usturayla -Asur Kralıyla- sakalınızı, saçlarınızı, beden kıllarınızı tıraş edecek.'),
(2001150,68,23,7,21,'O günlerde bir inekle bir çift koyun besleyen'),
(2001151,68,23,7,22,'aldığı bol süt sayesinde tereyağı yiyecek. Ülkede kalan herkes bal ve tereyağıyla beslenecek.'),
(2001152,68,23,7,23,'‹‹O gün bin gümüş değerinde bin asmaya sahip olan her bağ dikenli çalılarla dolacak.'),
(2001153,68,23,7,24,'İnsanlar oralara okla, yayla gidecek. Çünkü ülkenin her yanı dikenli çalılarla kaplanacak.'),
(2001154,68,23,7,25,'Bir zamanlar çapalanıp ekin ekilen tepeler korkudan kimsenin giremeyeceği dikenliklere dönecek, sığırın gezindiği, davarın çiğnediği yerler olacak.››'),
(2001155,68,23,8,1,'RAB bana şöyle dedi: ‹‹Büyük bir levha alıp okunaklı harflerle üzerine, ‹Maher-Şalal-Haş-Baz› yaz.'),
(2001156,68,23,8,2,'Kâhin Uriya ile Yeverekya oğlu Zekeriyayı kendime güvenilir tanık seçiyorum.›› anlamına gelir.'),
(2001157,68,23,8,3,'Peygamber olan karım bundan bir süre sonra gebe kaldı ve bir erkek çocuk doğurdu. RAB bana, ‹‹Adını ‹Maher-Şalal-Haş-Baz› koy›› dedi,'),
(2001158,68,23,8,4,'‹‹Çocuk daha ‹Anne, baba› demesini öğrenmeden, Şamın serveti ve Samiriyenin ganimeti Asur Kralına götürülecek.››'),
(2001159,68,23,8,5,'RAB bana yine seslenip dedi ki,'),
(2001160,68,23,8,6,'‹‹Bu halk usul usul akan Şiloah sularını reddettiği, Resinle Remalyanın oğluyla mutlu olduğu için,'),
(2001161,68,23,8,7,'ben Rab, Fıratın kabaran güçlü sularını -bütün dehşetiyle Asur Kralını- üzerlerine salacağım. Yatağından taşan ırmak, kıyılarını su altında bırakacak.'),
(2001162,68,23,8,8,'Yahudayı kaplayan sular her şeyi silip süpürerek adam boyu yükselecek, ülkeni boydan boya dolduracak, ey İmmanuel!›› için››.'),
(2001163,68,23,8,9,'Ey halklar, yıkıma, bozguna uğrayacaksınız. Yeryüzünün en uç köşeleri, kulak verin. Savaşmaya, bozguna uğramaya hazırlanın. Evet, savaşa ve bozguna hazır olun.'),
(2001164,68,23,8,10,'İstediğinizi tasarlayın, hepsi boşa gidecek. İstediğiniz kadar konuşun, hiçbiri gerçekleşmeyecek. Çünkü Tanrı bizimledir.'),
(2001165,68,23,8,11,'RAB beni halkın tuttuğu yoldan gitmeme konusunda şiddetle uyararak şöyle dedi:'),
(2001166,68,23,8,12,'‹‹Onların entrika dediği her şeye 2 Siz entrika demeyin; 2 Onların korktuğundan korkmayın, yılmayın.'),
(2001167,68,23,8,13,'‹‹Her Şeye Egemen RABbi kutsal sayın. 2 Korkunuz, yılgınız Ondan olsun.'),
(2001168,68,23,8,14,'Tapınak O olacak. 2 İsrailin iki krallığı içinse 2 Sürçme taşı ve tökezleme kayası, 2 Yeruşalimde yaşayanlar için 2 Kapan ve tuzak olacak.'),
(2001169,68,23,8,15,'Birçokları sendeleyip düşecek, parçalanacak, 2 Tuzağa düşüp ele geçecek.››'),
(2001170,68,23,8,16,'Ya RAB, öğrencilerim arasında bildirimi koru, 2 Öğretimi mühürle!'),
(2001171,68,23,8,17,'Kendini Yakupun soyundan gizleyen RABbi özlemle bekliyorum, umudum Onda.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001172,68,23,8,18,'Ben ve RABbin bana verdiği çocuklar, Siyon Dağında oturan Her Şeye Egemen RABbin İsraildeki belirtileri ve işaretleriyiz.'),
(2001173,68,23,8,19,'Birileri size, ‹‹Fısıldaşıp mırıldanan medyumlarla ruh çağıranlara danışın›› dediğinde, ‹‹Halk kendi Tanrısına danışmaz mı; yaşayanlar için ölülere mi danışılır?›› deyin.'),
(2001174,68,23,8,20,'Tanrının öğretisine ve bildirisine dönmek gerek! Böyle düşünmezlerse, onlar için hiç şafak sökmeyecek.'),
(2001175,68,23,8,21,'Aç ve çaresiz, ülkede dolanıp duracaklar. Aç kalınca öfkelenip krallarına, Tanrılarına lanet edecekler. Yukarıya da'),
(2001176,68,23,8,22,'dünyaya da baksalar sıkıntıdan, karanlıktan, korkunç karanlıktan başka bir şey görmeyecekler. Kovulacakları yer koyu karanlıktır.'),
(2001177,68,23,9,1,'Bununla birlikte sıkıntı çekmiş olan ülke karanlıkta kalmayacak. Geçmişte Zevulun ve Naftali bölgelerini alçaltan Tanrı, gelecekte Şeria Irmağının ötesinde, Deniz Yolunda, ulusların yaşadığı Celileyi onurlandıracak.'),
(2001178,68,23,9,2,'Karanlıkta yürüyen halk 2 Büyük bir ışık görecek; 2 Ölümün gölgelediği diyarda 2 Yaşayanların üzerine ışık parlayacak.'),
(2001179,68,23,9,3,'Ya RAB, ulusu çoğaltacak, sevincini artıracaksın. 2 Ekin biçenlerin neşelendiği, 2 Ganimet paylaşanların coştuğu gibi, 2 Onlar da sevinecek senin önünde.'),
(2001180,68,23,9,4,'Çünkü onlara yük olan boyunduruğu, 2 Omuzlarını döven değneği, 2 Onlara eziyet edenlerin sopasını paramparça edeceksin; 2 Tıpkı Midyanlıları yenilgiye uğrattığın günkü gibi.'),
(2001181,68,23,9,5,'Savaşta giyilen çizmeleri 2 Ve kana bulanmış giysileri 2 Yakılacak, ateşe yem olacak.'),
(2001182,68,23,9,6,'Çünkü bize bir çocuk doğacak, 2 Bize bir oğul verilecek. 2 Yönetim onun omuzlarında olacak. 2 Onun adı Harika Öğütçüfı, Güçlü Tanrı, 2 Ebedi Baba, Esenlik Önderi olacak.'),
(2001183,68,23,9,7,'Davutun tahtı ve ülkesi üzerinde egemenlik sürecek. 2 Egemenliğinin ve esenliğinin büyümesi son bulmayacak. 2 Egemenliğini adaletle, doğrulukla kuracak 2 Ve sonsuza dek sürdürecek. 2 Her Şeye Egemen RABbin gayreti bunu sağlayacak.'),
(2001184,68,23,9,8,'Rab İsrail için, 2 Yakup soyu için yargısını bildirdi. 2 Bu yargı yerine gelecek.'),
(2001185,68,23,9,9,'Bütün halk, Efrayim ve Samiriyede yaşayanlar, 2 Rabbin bu yargısını duyacak. 2 Gururlu ve küstah olan bu halk diyor ki,'),
(2001186,68,23,9,10,'‹‹Kerpiç evler yıkıldı, 2 Ama yerlerine yontma taştan evler yapacağız. 2 Yabanıl incir ağaçları kesildi, 2 Ama yerlerine sedir ağaçları dikeceğiz.››'),
(2001187,68,23,9,11,'Bundan dolayı RAB, Resinin hasımlarını 2 Halka karşı güçlendirecek; 2 Düşmanlarını, doğudan Aramlıları, 2 Batıdan Filistlileri ayaklandıracak. 2 Bunlar ağızlarını ardına kadar açıp İsraili yutacaklar. 2 Bütün bunlara karşın RABbin öfkesi dinmedi, 2 Eli hâlâ kalkmış durumda.'),
(2001188,68,23,9,13,'Halk kendisini cezalandıran RABbe dönmeyecek, 2 Her Şeye Egemen RABbi aramayacak.'),
(2001189,68,23,9,14,'Bunun için RAB İsrailden başı da kuyruğu da 2 Hurma dalını da sazı da 2 Bir günde kesip atacak.'),
(2001190,68,23,9,15,'Baş ileri gelen saygın kişi, 2 Kuyruksa öğretisi sahte olan peygamberdir.'),
(2001191,68,23,9,16,'Çünkü bu halkı saptıranlar ona yol gösterenlerdir. 2 Onları izleyenler de yem oluyor.'),
(2001192,68,23,9,17,'Bu yüzden Rab onların gençleri için sevinç duymayacak, 2 Öksüzlerine, dul kadınlarına acımayacak. 2 Çünkü hepsi tanrısızdır, kötülük yaparlar. 2 Her ağız saçmalıyor. 2 Bütün bunlara karşın RABbin öfkesi dinmedi, 2 Eli hâlâ kalkmış durumda.'),
(2001193,68,23,9,18,'Kötülük dikenli çalıları yiyip bitiren ateş gibidir. 2 Ormandaki çalılığı tutuşturur, 2 Duman sütunları yükseltir.'),
(2001194,68,23,9,19,'Her Şeye Egemen RABbin öfkesi 2 Ülkeyi ateş gibi sardı. 2 Halk ateşe yem olacak, 2 Kardeş kardeşini esirgemeyecek.'),
(2001195,68,23,9,20,'İnsanlar şurada burada bulduklarını yiyecekler, 2 Ama aç kalacak, doymayacaklar. 2 Herkes çocuğunun etini yiyecek:'),
(2001196,68,23,9,21,'Manaşşe Efrayim''i, 2 Efrayim Manaşşe''yi yiyecek, 2 Sonra birlikte Yahuda''nın üzerine yürüyecekler. 2 Bütün bunlara karşın RAB''bin öfkesi dinmedi, 2 Eli hâlâ kalkmış durumda.'),
(2001197,68,23,10,1,'Yoksullardan adaleti esirgemek, 2 Halkımın düşkünlerinin hakkını elinden almak, 2 Dulları avlamak, 2 Öksüzlerin malını yağmalamak için 2 Haksız kararlar alanların, 2 Adil olmayan yasalar çıkaranların vay haline!'),
(2001198,68,23,10,3,'Yargı günü 2 Uzaklardan başınıza felaket geldiğinde ne yapacaksınız? 2 Yardım için kime koşacaksınız, 2 Servetinizi nereye saklayacaksınız?'),
(2001199,68,23,10,4,'Tutsaklar arasında bir köşeye sinmek 2 Ya da savaşta ölmekten başka çareniz kalmayacak. 2 Bütün bunlara karşın RABbin öfkesi dinmedi, 2 Eli hâlâ kalkmış durumda.'),
(2001200,68,23,10,5,'‹‹Vay haline Asur, öfkemin değneği! 2 Elindeki sopa benim gazabımdır.'),
(2001201,68,23,10,6,'Asuru tanrısız ulusa karşı salacağım; 2 Soyup yağma etmesi, 2 Sokaktaki çamur gibi onları çiğnemesi, 2 Öfkelendiğim halkın üzerine yürümesi için 2 Buyruk vereceğim.››'),
(2001202,68,23,10,7,'Ama Asur Kralı bundan da kötüsünü düşünüyor. 2 Birçok ulusun kökünü kazıyıp yok etmeyi tasarlıyor.'),
(2001203,68,23,10,8,'‹‹Komutanlarımın hepsi birer kral değil mi?›› diyor,'),
(2001204,68,23,10,9,'‹‹Kalnoyu, Karkamış gibi ele geçirmedim mi? 2 Hamanın sonu Arpatınki, 2 Samiriyenin sonu Şamınki gibi olmadı mı?'),
(2001205,68,23,10,10,'Putları Yeruşalim ve Samiriyeninkinden daha çok olan putperest ülkeleri nasıl ele geçirdimse,'),
(2001206,68,23,10,11,'Samiriyeye ve putlarına ne yaptımsa, 2 Yeruşalime ve putlarına da yapamaz mıyım?››'),
(2001207,68,23,10,12,'Rab Siyon Dağına ve Yeruşalime karşı tasarladıklarını yapıp bitirdikten sonra şöyle diyecek: 2 ‹‹Asur Kralını kibirli yüreği, 2 Övüngen bakışları yüzünden cezalandıracağım.'),
(2001208,68,23,10,13,'Çünkü, ‹Her şeyi bileğimin gücüyle, 2 Bilgeliğimle yaptım› diyor, 2 ‹Akıllıyım, ulusları ayıran sınırları yok ettim, 2 Hazinelerini yağmaladım, 2 Güçlü kralları tahtlarından indirdim.'),
(2001209,68,23,10,14,'Elimi yuvaya sokup kuş yumurtalarını toplar gibi 2 Ulusların varını yoğunu topladım. 2 Terk edilmiş yumurtaları nasıl toplarlarsa, 2 Ben de bütün ülkeleri öyle topladım. 2 Kanat çırpan, ağzını açan, 2 Sesini çıkaran olmadı.› ››'),
(2001210,68,23,10,15,'Balta kendisini kullanana karşı övünür mü? 2 Testere kendisini kullanana karşı büyüklenir mi? 2 Sanki değnek kendisini kaldıranı sallayabilir, 2 Sopa sahibini kaldırabilirmiş gibi...'),
(2001211,68,23,10,16,'Rab, Her Şeye Egemen RAB, 2 Asurun güçlü adamlarını 2 Yıpratıcı hastalıkla cezalandıracak. 2 Orduları alev alev yanacak.'),
(2001212,68,23,10,17,'İsrailin Işığı ateş, 2 İsrailin Kutsalı alev olacak; 2 Asurun dikenli çalılarını 2 Bir gün içinde yakıp bitirecek.'),
(2001213,68,23,10,18,'Görkemli ormanıyla verimli tarlaları, 2 Ölümcül bir hastalığa yakalanmış insan gibi 2 Tümüyle harap olacak.'),
(2001214,68,23,10,19,'Ormanda artakalan ağaçlar 2 Bir çocuğun bile sayabileceği kadar az olacak.'),
(2001215,68,23,10,20,'O gün İsrailin sağ kalanları, 2 Yakupun kaçıp kurtulan torunları, 2 Kendilerini yok etmek isteyene değil, 2 Artık içtenlikle RABbe, İsrailin Kutsalına dayanacaklar.'),
(2001216,68,23,10,21,'Geriye kalanlar, 2 Yakup soyundan sağ kalanlar, 2 Güçlü Tanrıya dönecekler.'),
(2001217,68,23,10,22,'Ey İsrail, halkın denizin kumu kadar çok olsa da, 2 Ancak pek azı dönecek. 2 Tümüyle adil bir yıkım kararlaştırıldı.'),
(2001218,68,23,10,23,'Rab, Her Şeye Egemen RAB, 2 Kararlaştırılan yıkımı bütün yeryüzünde gerçekleştirecek. sözcükleri genellikle ‹‹Sağ kalanlar dönecek›› diye çevrildi. Yeşaya bu sözcükleri ilk oğluna ad olarak verdi (bkz. 7:3).'),
(2001219,68,23,10,24,'Bu nedenle Rab, 2 Her Şeye Egemen RAB şöyle diyor: 2 ‹‹Ey sen, Siyonda yaşayan halkım, 2 Asurlular, Mısırlıların yaptığı gibi 2 Sana değnekle vurduklarında, 2 Sopalarını sana karşı kaldırdıklarında korkma.'),
(2001220,68,23,10,25,'Çünkü çok yakında gazabım sona erecek, 2 Öfkem Asurluların yıkımını sağlayacak.'),
(2001221,68,23,10,26,'Ben, Her Şeye Egemen RAB, 2 Midyanlıları Orev Kayasında alt ettiğim gibi, 2 Onları da kırbaçla alt edeceğim. 2 Değneğimi Mısıra karşı nasıl denizin üzerine uzattımsa, 2 Şimdi yine öyle yapacağım.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001222,68,23,10,27,'O gün Asurun yükü sırtınızdan, 2 Boyunduruğu boynunuzdan kalkacak; 2 Semirdiğiniz için boyunduruk kırılacak.››'),
(2001223,68,23,10,28,'Ayat Kentine saldırdılar, 2 Migrondan geçip ağırlıklarını Mikmasta bıraktılar.'),
(2001224,68,23,10,29,'Geçidi aşarak Gevada konakladılar. 2 Rama Kenti korkudan titredi, 2 Saulun kenti Givada yaşayan halk kaçıştı.'),
(2001225,68,23,10,30,'Ey Gallim halkı, sesini yükselt! 2 Ey Layşa halkı, dinle! 2 Zavallı Anatot halkı!'),
(2001226,68,23,10,31,'Madmena halkı kaçıyor, 2 Hagevimde yaşayanlar sığınacak yer arıyor.'),
(2001227,68,23,10,32,'Düşman bugün Novda duracak; 2 Siyon Kentinin kurulduğu dağa, 2 Yeruşalim Tepesine yumruk sallayacak.'),
(2001228,68,23,10,33,'Rab, Her Şeye Egemen RAB düşmanı 2 Dal gibi kesip korkunç güçle yere çalacak. 2 Uzun boyluları devirecek, 2 Gururluları alçaltacak.'),
(2001229,68,23,10,34,'Ormandaki çalılıkları baltayla keser gibi 2 Kesip devirecek onları. 2 Lübnan, Güçlü Olan''ın önünde diz çökecek.'),
(2001230,68,23,11,1,'İşayın kütüğünden yeni bir filiz çıkacak, 2 Kökünden bir fidan meyve verecek.'),
(2001231,68,23,11,2,'RABbin Ruhu, bilgelik ve anlayış ruhu, 2 Öğüt ve güç ruhu, bilgi ve RAB korkusu ruhu 2 Onun üzerinde olacak.'),
(2001232,68,23,11,3,'RAB korkusu hoşuna gidecek. 2 Gözüyle gördüğüne göre yargılamayacak, 2 Kulağıyla işittiğine göre karar vermeyecek.'),
(2001233,68,23,11,4,'Yoksulları adaletle yargılayacak, 2 Yeryüzünde ezilenler için dürüstçe karar verecek. 2 Dünyayı ağzının değneğiyle cezalandıracak, 2 Kötüleri soluğuyla öldürecek.'),
(2001234,68,23,11,5,'Davranışının temeli adalet ve sadakat olacak. ‹‹Adalet ve sadakat belindeki kuşaktır››.'),
(2001235,68,23,11,6,'Onun döneminde kurtla kuzu bir arada yaşayacak, 2 Parsla oğlak birlikte yatacak, 2 Buzağı, genç aslan ve besili sığır yanyana duracak, 2 Onları küçük bir çocuk güdecek.'),
(2001236,68,23,11,7,'İnekle ayı birlikte otlayacak, 2 Yavruları bir arada yatacak. 2 Aslan sığır gibi saman yiyecek.'),
(2001237,68,23,11,8,'Emzikteki bebek kobra deliği üzerinde oynayacak, 2 Sütten kesilmiş çocuk elini engerek kovuğuna sokacak.'),
(2001238,68,23,11,9,'Kutsal dağımın hiçbir yerinde 2 Kimse zarar vermeyecek, yok etmeyecek. 2 Çünkü sular denizi nasıl dolduruyorsa, 2 Dünya da RABbin bilgisiyle dolacak.'),
(2001239,68,23,11,10,'O gün İşayın kökü ortaya çıkacak, 2 Halklara sancak olacak, 2 Uluslar ona yönelecek. 2 Kaldığı yer görkemli olacak.'),
(2001240,68,23,11,11,'O gün Rab, Asurdan, 2 Mısır, Patros, Kûş, Elam, 2 Şinar, Hama ve deniz kıyılarından 2 Halkının sağ kalanlarını kurtarmak için 2 İkinci kez elini uzatacak.'),
(2001241,68,23,11,12,'Uluslar için sancak kaldıracak, 2 Sürgün İsraillileri toplayacak, 2 Dağılmış Yahudalıları 2 Dünyanın dört bucağından bir araya getirecek.'),
(2001242,68,23,11,13,'Efrayim halkının kıskançlığı yok olacak, 2 Yahudalıları sıkıştıranlar ortadan kalkacak. 2 Efrayim Yahudayı kıskanmayacak, 2 Yahuda Efrayimi sıkıştırmayacak.'),
(2001243,68,23,11,14,'Batıdaki Filistlilere saldırıp 2 Hep birlikte doğudakilerin her şeyini yağmalayacaklar. 2 Edom ve Moav halklarının topraklarına el koyacak, 2 Ammonlulara boyun eğdirecekler.'),
(2001244,68,23,11,15,'RAB Mısırın Süveyş Körfezini tümüyle kurutacak. 2 Elinin bir sallayışıyla estireceği kavurucu rüzgarla 2 Fıratı süpürüp yedi dereye bölecek. 2 Öyle ki, insanlar ırmak yatağından çarıkla geçebilsin.'),
(2001245,68,23,11,16,'RAB''bin Asur''da sağ kalan halkı için 2 Bir çıkış yolu olacak; 2 Tıpkı Mısır''dan çıktıkları gün 2 İsrailliler''in de bir çıkış yolu olduğu gibi.'),
(2001246,68,23,12,1,'İsrail halkı o gün, 2 ‹‹Ya RAB, sana şükrederiz›› diyecek, 2 ‹‹Bize öfkelenmiştin ama öfken dindi, 2 Bizi avuttun.'),
(2001247,68,23,12,2,'Tanrı kurtuluşumuzdur. 2 Ona güvenecek, yılmayacağız. 2 Çünkü RAB gücümüz ve ezgimizdir. 2 O kurtardı bizi.››'),
(2001248,68,23,12,3,'Kurtuluş pınarlarından sevinçle su alacaksınız.'),
(2001249,68,23,12,4,'O gün diyeceksiniz ki, 2 ‹‹RABbe şükredin, Onu adıyla çağırın, 2 Halklara duyurun yaptıklarını, 2 Adının yüce olduğunu duyurun!'),
(2001250,68,23,12,5,'RABbe ezgiler söyleyin, 2 Çünkü görkemli işler yaptı. 2 Bütün dünya bilsin bunu.'),
(2001251,68,23,12,6,'Ey Siyon halkı, sesini yükselt, sevinçle haykır! 2 Çünkü aranızda bulunan İsrail''in Kutsalı büyüktür.››'),
(2001252,68,23,13,1,'Amots oğlu Yeşayanın Babille ilgili bildirisi:'),
(2001253,68,23,13,2,'Çıplak dağın tepesine sancak dikin! 2 Savaşçıları yüksek sesle çağırıp 2 El sallayın ki 2 Soylulara ayrılan kapılardan içeri girsinler.'),
(2001254,68,23,13,3,'RAB seçtiklerine buyruk verdi, 2 Onun yüceliğiyle övünen yiğitleri 2 Öfkesinin gereğini yapmaya çağırdı.'),
(2001255,68,23,13,4,'Dağlardaki kalabalığın gürültüsünü dinleyin! 2 Büyük bir halkın sesini andırıyor. 2 Bir araya gelmiş ulusların 2 Ve krallıkların gümbürtüsünü dinleyin! 2 Her Şeye Egemen RAB bir orduyu savaşa hazırlıyor.'),
(2001256,68,23,13,5,'Öfkesinin araçlarıyla uzak bir ülkeden, 2 Dünyanın öbür ucundan 2 Bütün ülkeyi yerle bir etmek üzere geliyor.'),
(2001257,68,23,13,6,'Feryat edin! Çünkü RABbin günü yakındır. 2 Her Şeye Gücü Yetenin göndereceği yıkım gibi geliyor o gün.'),
(2001258,68,23,13,7,'Bu yüzden ellerde derman kalmayacak, 2 Her yürek eriyecek.'),
(2001259,68,23,13,8,'Herkesi dehşet saracak, 2 Hepsi acı ve ıstırap içinde boğulacak, 2 Doğuran kadın gibi kıvranacak, 2 Şaşkın şaşkın birbirlerine bakacaklar; 2 Yüzleri kızaracak.'),
(2001260,68,23,13,9,'İşte RABbin acımasız günü geliyor. 2 Ülkeyi viraneye çevirip 2 İçindeki günahkârları ortadan kaldıracağı 2 Gazap ve kızgın öfke dolu gün geliyor.'),
(2001261,68,23,13,10,'Gökteki yıldızlarla takımyıldızlar ışımayacak, 2 Doğan güneş kararacak, ay ışığını vermez olacak.'),
(2001262,68,23,13,11,'RAB diyor ki, ‹‹Kötülüğünden ötürü dünyayı, 2 Suçlarından ötürü kötüleri cezalandıracağım. 2 Kibirlilerin küstahlığını sona erdirecek, 2 Zalimlerin gururunu kıracağım.'),
(2001263,68,23,13,12,'İnsanı saf altından, 2 Ofir altınından daha ender kılacağım.'),
(2001264,68,23,13,13,'Ben, Her Şeye Egemen RAB, 2 Gazaba geldiğim, öfkemin alevlendiği gün 2 Gökleri titreteceğim, yer yerinden oynayacak.'),
(2001265,68,23,13,14,'‹‹Herkes kovalanan ceylan gibi, 2 Çobansız koyunlar gibi halkına dönecek, 2 Ülkesine kaçacak.'),
(2001266,68,23,13,15,'Yakalananın bedeni delik deşik edilecek, 2 Ele geçen kılıçtan geçirilecek.'),
(2001267,68,23,13,16,'Yavruları gözleri önünde parçalanacak, 2 Evleri yağmalanacak, 2 Kadınlarının ırzına geçilecek.'),
(2001268,68,23,13,17,'‹‹Gümüşe değer vermeyen, 2 Altını sevmeyen Medleri 2 Onlara karşı harekete geçireceğim.'),
(2001269,68,23,13,18,'Oklarıyla gençleri parçalayacak, 2 Bebeklere acımayacak, 2 Çocukları esirgemeyecekler.'),
(2001270,68,23,13,19,'Ben Tanrı, Sodom ve Gomorayı nasıl yerle bir ettimse, 2 Kildanilerin yüce gururu, 2 Krallıkların en güzeli olan Babili de yerle bir edeceğim.'),
(2001271,68,23,13,20,'Orada bir daha kimse yaşamayacak, 2 Kuşaklar boyu kimse oturmayacak, 2 Bedeviler çadır kurmayacak, 2 Çobanlar sürülerini dinlendirmeyecek.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001272,68,23,13,21,'Orası yabanıl hayvanlara barınak olacak, 2 Evler çakallarla dolacak, 2 Baykuşlar yuva yapacak, tekeler oynaşacak orada. (bkz. Lev.17:7).'),
(2001273,68,23,13,22,'Kalelerinde sırtlanlar, 2 Görkemli saraylarında çakallar uluyacak. 2 Babil''in sonu yaklaştı, günleri uzatılmayacak.››'),
(2001274,68,23,14,1,'Çünkü RAB Yakup soyuna acıyacak, 2 İsrail halkını yine seçip 2 Topraklarına yerleştirecek. 2 Yabancılar da Yakup soyuna katılıp onlara bağlanacak.'),
(2001275,68,23,14,2,'Uluslar İsrail halkını 2 Kendi topraklarına götürecekler. 2 İsrail halkı RABbin verdiği topraklarda onları 2 Erkek ve kadın köle olarak sahiplenecek. 2 Kendisini tutsak edenleri tutsak edecek, 2 Kendisini ezenlere egemen olacak.'),
(2001276,68,23,14,3,'RAB İsrail halkını acıdan, sıkıntıdan 2 Ve yaptığı ağır işlerden kurtardığı gün'),
(2001277,68,23,14,4,'Babil Kralını alaya alarak, 2 ‹‹Halkı ezenin nasıl da sonu geldi!›› diyecekler, 2 ‹‹Zorbalığı nasıl da sona erdi!››'),
(2001278,68,23,14,5,'RAB kötülerin değneğini, 2 Egemenlerin asasını kırdı.'),
(2001279,68,23,14,6,'O asa ki, halklara gazapla vurdukça vurdu, 2 Ulusları öfkeyle, dinmeyen zulümle yönetti.'),
(2001280,68,23,14,7,'Bütün dünya esenlik ve barış içinde 2 Sevinçle haykırıyor.'),
(2001281,68,23,14,8,'Lübnanın çam ve sedir ağaçları bile 2 Kralın yok oluşuna seviniyor. 2 ‹‹Onun ölümünden beri kimse bizi kesmeye gelmiyor›› diyorlar.'),
(2001282,68,23,14,9,'Toprağın altındaki ölüler diyarı 2 Babil Kralını karşılamak için sabırsızlanıyor. 2 Onun gelişi ölüleri, 2 Dünyanın eski önderlerini heyecanlandırıyor; 2 Ulusları yönetmiş kralları 2 Tahtlarından ayağa kaldırıyor.'),
(2001283,68,23,14,10,'Hepsi ona seslenip diyecekler ki, 2 ‹‹Sen de bizim gibi gücünü yitirdin, 2 Bize benzedin.››'),
(2001284,68,23,14,11,'Görkemin de çenklerinin sesi de 2 Ölüler diyarına indirildi. 2 Altında kurtlar kaynaşacak, 2 Üstünü kurtçuklar kaplayacak.'),
(2001285,68,23,14,12,'Ey parlak yıldızfö, seherin oğlu, 2 Göklerden nasıl da düştün! 2 Ey ulusları ezip geçen, 2 Nasıl da yere yıkıldın!'),
(2001286,68,23,14,13,'İçinden, ‹‹Göklere çıkacağım›› dedin, 2 ‹‹Tahtımı Tanrının yıldızlarından daha yükseğe koyacağım; 2 İlahların toplandığı dağda, 2 Safonun doruğunda oturacağım.'),
(2001287,68,23,14,14,'Bulutların üstüne çıkacak, 2 Kendimi Yüceler Yücesiyle eşit kılacağım.››'),
(2001288,68,23,14,15,'Ancak ölüler diyarına, 2 Ölüm çukurunun dibine 2 İndirilmiş bulunuyorsun.'),
(2001289,68,23,14,16,'Seni görenler bakıp bakıp şöyle düşünecekler: 2 ‹‹Dünyayı sarsan, ülkeleri titreten, 2 Yeryüzünü çöle çeviren, 2 Kentleri yerle bir eden, 2 Tutsakları evlerine salıvermeyen adam bu mu?››'),
(2001290,68,23,14,18,'Ulusların bütün kralları tek tek, 2 Görkemli mezarlarda yatıyor.'),
(2001291,68,23,14,19,'Ama sen reddedilen bir dal gibi 2 Mezarından dışarı atıldın; 2 Bedenleri kılıçla delinip 2 Ölüm çukurunun dibine atılmış ölülerle örtülüsün; 2 Ayak altında çiğnenen leş gibisin.'),
(2001292,68,23,14,20,'Ülkeni harap edip halkını katlettiğin için 2 Başkaları gibi gömülmeyeceksin. Kötülük yapan soy bir daha anılmayacak.'),
(2001293,68,23,14,21,'Atalarının suçundan ötürü 2 Babil Kralının oğullarını boğazlamak için yer hazırlayın. 2 Kalkıp dünyayı sahiplenmesinler, 2 Yeryüzünü kentlerle doldurmasınlar.'),
(2001294,68,23,14,22,'‹‹Babil halkına karşı harekete geçeceğim›› 2 Diyor Her Şeye Egemen RAB, 2 ‹‹Babilin adını, sağ kalanlarını, 2 Oğullarını, torunlarını dünyadan sileceğim.›› 2 Böyle diyor RAB.'),
(2001295,68,23,14,23,'‹‹Babili baykuş yuvasına, bataklığa çevirecek, 2 Yıkım süpürgesiyle süpüreceğim›› 2 Diyor Her Şeye Egemen RAB.'),
(2001296,68,23,14,24,'Her Şeye Egemen RAB ant içerek şöyle dedi: 2 ‹‹Düşündüğüm gibi olacak, 2 Tasarladığım gibi gerçekleşecek.'),
(2001297,68,23,14,25,'Asurluları kendi ülkemde ezecek, 2 Dağlarımda çiğneyeceğim. 2 Halkım Asurun boyunduruğundan, 2 Omuzlarındaki yükten kurtulacak.'),
(2001298,68,23,14,26,'İşte bütün dünya için belirlenen tasarı budur. 2 Bütün uluslara karşı elim kalkmış durumda.'),
(2001299,68,23,14,27,'Her Şeye Egemen RABbin tasarısını kim boşa çıkarabilir? 2 Kalkmış durumdaki elini kim indirebilir?››'),
(2001300,68,23,14,28,'Kral Ahazın öldüğü yıl gelen bildiri:'),
(2001301,68,23,14,29,'Ey Filistliler, sizi döven değnek kırıldı diye sevinmeyin. 2 Çünkü yılanın kökünden engerek türeyecek, 2 Onun ürünü uçan yılan olacak.'),
(2001302,68,23,14,30,'Yoksulların en yoksulu doyacak, 2 Düşkünler güvenlikte yatacak. 2 Ama sizin kökünüzü kıtlıkla kurutacağım, 2 Sağ kalanlarınız da ölecek.'),
(2001303,68,23,14,31,'Ulumaya başla ey kapı! Ey kent, feryat et! 2 Ey Filistliler, eridiniz baştan başa. 2 Kuzeyden toz duman yükseliyor, 2 Düşman askerleri sıra sıra geliyor.'),
(2001304,68,23,14,32,'O ulusun elçilerine ne yanıt verilecek? 2 ‹‹RAB Siyon''un temelini attı, 2 Halkının düşkünleri oraya sığınacak›› denecek.'),
(2001305,68,23,15,1,'Moavla ilgili bildiri: Moavın Ar Kenti bir gecede viraneye döndü, yok oldu, 2 Moavın Kîr Kenti bir gecede viraneye döndü, yok oldu.'),
(2001306,68,23,15,2,'Bu yüzden Divon halkı ağlamak için tapınağa, 2 Tapınma yerlerine çıktı. 2 Moav halkı, Nevo ve Medeva için feryat ediyor. 2 İnsanlar saçlarını sakallarını kesiyor.'),
(2001307,68,23,15,3,'Çul giyiyorlar sokaklarda, 2 Damlarda, meydanlarda herkes feryat ediyor, 2 Gözyaşları sel gibi.'),
(2001308,68,23,15,4,'Heşbon ve Elalenin haykırışları 2 Yahasa ulaşıyor. 2 Moav askerleri bu yüzden feryat ediyor, 2 Yürekleri korku içinde.'),
(2001309,68,23,15,5,'Yüreğim sızlıyor Moav için. 2 Kaçanlar Soara, Eglat-Şelişiyaya ulaştı, 2 Ağlaya ağlaya çıkıyorlar Luhit Yokuşundan, 2 Horonayim yolunda yıkımlarına ağıt yakıyorlar.'),
(2001310,68,23,15,6,'Nimrim suları kuruduğu için otlar sararıp soldu. 2 Taze ot kalmadı, yeşillik yok artık.'),
(2001311,68,23,15,7,'Bu yüzden halk kazanıp biriktirdiği ne varsa, 2 Kavak Vadisi üzerinden taşıyacak.'),
(2001312,68,23,15,8,'Haykırışları Moav topraklarında yankılanıyor, 2 Feryatları Eglayime, Beer-Elime dek ulaştı.'),
(2001313,68,23,15,9,'Çünkü Dimon suları kan dolu, 2 Ama başına daha beterini getireceğim. 2 Moav''dan kaçıp kurtulanların, 2 Ülkede sağ kalanların üzerine aslan salacağım.'),
(2001314,68,23,16,1,'Seladan çöl yoluyla Siyon Kentinin kurulduğu dağa, 2 Ülkenin hükümdarına kuzular gönderin.'),
(2001315,68,23,16,2,'Moavlı kızlar yuvalarından atılmış, 2 Öteye beriye uçuşan kuşlar gibi 2 Arnon Irmağının geçitlerinde dolaşıyor.'),
(2001316,68,23,16,3,'‹‹Bize öğüt ver, bir karar al, 2 Öğle sıcağında gece gibi gölge sal üstümüze. 2 Kovulanları sakla, kaçakları ele verme›› diyorlar.'),
(2001317,68,23,16,4,'‹‹Kovulanlarım seninle birlikte yaşasın. 2 Kırıp geçirenlere karşı 2 Biz Moavlılara sığınak ol.›› 2 Baskı ve yıkım son bulduğunda, 2 Ülkeyi çiğneyenler yok olduğunda, 2 Sevgiye dayanan bir yönetim kurulacak,'),
(2001318,68,23,16,5,'Davut soyundan biri sadakatle krallık yapacak. 2 Yargılarken adaleti arayacak, 2 Doğru olanı yapmakta tez davranacak.'),
(2001319,68,23,16,6,'Moavın ne denli gururlanıp büyüklendiğini, 2 Kendini ne denli beğendiğini, 2 Kibirlenip küstahlaştığını duyduk. 2 Övünmesi boşunadır.'),
(2001320,68,23,16,7,'Bu yüzden Moavlılar Moav için feryat edecek, 2 Hepsi feryat edecek. 2 Kîr-Heresetin üzüm pestillerini 2 Anımsayıp üzülecek, yas tutacaklar.'),
(2001321,68,23,16,8,'Çünkü Heşbonun tarlaları, 2 Sivmanın asmaları kurudu. 2 Ulusların beyleri onların seçkin dallarını kırdılar. 2 O dallar ki, Yazere erişir, çöle uzanırdı, 2 Filizleri yayılır, gölü aşardı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001322,68,23,16,9,'Bu yüzden Yazer için, 2 Sivmanın asmaları için acı acı ağlıyorum. 2 Sizleri gözyaşlarımla sulayacağım, 2 Ey Heşbon ve Elale! 2 Çünkü savaş çığlıkları yaz meyvelerinizin, 2 Biçtiğiniz ekinin üzerine düştü.'),
(2001323,68,23,16,10,'Meyve bahçelerindeki sevinç ve neşe yok oldu. 2 Bağlarda ne şarkı söyleyen olacak, 2 Ne sevinç çığlığı atan. 2 Üzüm sıkma çukurlarında çalışan kalmayacak, 2 Sevinç çığlıklarını susturdum.'),
(2001324,68,23,16,11,'Yüreğim bir lir gibi inliyor Moav için, 2 Kîr-Hereset için içim sızlıyor.'),
(2001325,68,23,16,12,'Moav halkı tapınma yerine çıkarak kendini yoruyor, 2 Dua etmek için tapınağa gidiyor, ama hepsi boşuna!'),
(2001326,68,23,16,13,'RABbin Moav için geçmişte söylediği budur.'),
(2001327,68,23,16,14,'RAB şimdi diyor ki, ‹‹Moav''ın övündükleri de kalabalık halkı da tam üç yıl sonra rezil olacak. Sağ kalan çok az sayıda kişiyse güçsüz olacak.››'),
(2001328,68,23,17,1,'Şamla ilgili bildiri: İşte Şam kent olmaktan çıkacak, 2 Enkaz yığınına dönecek.'),
(2001329,68,23,17,2,'Aroer kentleri terk edilecek, 2 Hayvan sürüleri orada yatacak, 2 Onları ürküten olmayacak.'),
(2001330,68,23,17,3,'Efrayimde surlu kent kalmayacak, 2 Şamın egemenliği yok olacak. 2 Sağ kalan Aramlıların onuru 2 İsrailin onuru gibi kırılacak. 2 Her Şeye Egemen RAB böyle diyor.'),
(2001331,68,23,17,4,'O gün Yakup soyunun görkemi sönecek, 2 Hepsi bir deri bir kemik kalacak.'),
(2001332,68,23,17,5,'İsrail, ekinin elle biçilip 2 Başakların devşirildiği bir tarla, 2 Refaim Vadisinde hasattan sonra 2 Başakların toplandığı bir tarla gibi olacak.'),
(2001333,68,23,17,6,'Çok az kişi kurtulacak. 2 Artakalanların sayısı, dövüldükten sonra tepesinde iki üç, 2 Dal uçlarında dört beş zeytin tanesi kalan 2 Zeytin ağacı gibi olacak. 2 İsrailin Tanrısı RAB böyle diyor.'),
(2001334,68,23,17,7,'O gün insanlar kendilerini yaratana bakacaklar, gözleri İsrailin Kutsalını görecek.'),
(2001335,68,23,17,8,'Elleriyle yaptıkları sunaklara, parmaklarıyla biçim verdikleri Aşera putlarına, buhur sunaklarına bakmayacaklar.'),
(2001336,68,23,17,9,'O gün İsrailin güçlü kentleri 2 İsraillilerden kaçan Amorlularla Hivlilerin 2 Terk ettiği kentler gibi ıssız olacak. ‹‹Orman ve dağ başı››.'),
(2001337,68,23,17,10,'Çünkü, ey İsrail, seni kurtaran Tanrıyı unuttun, 2 Sığındığın Kayayı anmaz oldun. 2 Bunun yerine, güzel fidanlar, ithal asmalar dikiyorsun. başka ulusların putları ya da başka uluslarla yapılan antlaşmalar kastediliyor.'),
(2001338,68,23,17,11,'Onlar diktiğin gün filizlenip 2 Ertesi sabah tomurcuklanabilir. 2 Ama hastalık ve dinmez acı gününde meyve vermeyecekler.'),
(2001339,68,23,17,12,'Eyvah, çok sayıda ulus kükrüyor, 2 Azgın deniz gibi gürlüyorlar. 2 Halklar güçlü sular gibi çağlıyor.'),
(2001340,68,23,17,13,'Halklar kabaran sular gibi çağlayabilir, 2 Ama Tanrı onları azarlayınca uzaklara kaçacaklar. 2 Rüzgarın önünde dağdaki saman ufağı gibi, 2 Kasırganın önünde diken yumağı gibi savrulacaklar.'),
(2001341,68,23,17,14,'Akşam dehşet saçıyorlardı, 2 Sabah olmadan yok olup gittiler. 2 Bizi yağmalayanların, bizi soyanların sonu budur.'),
(2001342,68,23,18,1,'Kûş ırmaklarının ötesinde, 2 Kanat vızıltılarının duyulduğu ülkenin vay haline!'),
(2001343,68,23,18,2,'O ülke ki, elçilerini 2 Sazdan kayıklarla Nil sularından gönderir. 2 Ey ayağına tez ulaklar, 2 Irmakların böldüğü ülkeye, 2 Her yana korku saçan halka, 2 Güçlü ve ezici ulusa, 2 O uzun boylu, pürüzsüz tenli ulusa gidin!'),
(2001344,68,23,18,3,'Ey sizler, dünyada yaşayan herkes, 2 Yeryüzünün ahalisi! 2 Sancak dağların tepesine dikilince dikkat edin. 2 Boru çalınınca dinleyin.'),
(2001345,68,23,18,4,'Çünkü RAB bana şöyle dedi: 2 ‹‹Gün ışığında duru sıcaklık gibi, 2 Hasat döneminin sıcaklığındaki 2 Çiy bulutu gibi durgun olacak 2 Ve bulunduğum yerden seyredeceğim.››'),
(2001346,68,23,18,5,'Bağbozumundan önce çiçekler düşüp 2 Üzümler olgunlaşmaya yüz tutunca, 2 Asmanın dalları bıçakla kesilecek, 2 Çubukları koparılıp atılacak.'),
(2001347,68,23,18,6,'Hepsi dağın yırtıcı kuşlarına, 2 Yerin yabanıl hayvanlarına terk edilecek. 2 Yazın yırtıcı kuşlara, 2 Kışın yabanıl hayvanlara yem olacaklar.'),
(2001348,68,23,18,7,'O zaman ırmakların böldüğü ülke, 2 Her yana korku saçan güçlü ve ezici halk, 2 O uzun boylu, pürüzsüz tenli ulus, 2 Her Şeye Egemen RAB''be armağanlar getirecek. 2 Her Şeye Egemen RAB''bin adını koyduğu 2 Siyon Dağı''na getirecekler armağanlarını.'),
(2001349,68,23,19,1,'Mısırla ilgili bildiri: İşte RAB hızla yol alan buluta binmiş Mısıra geliyor! 2 Mısır putları Onun önünde titriyor, 2 Mısırlıların yüreği hopluyor.'),
(2001350,68,23,19,2,'RAB diyor ki, 2 ‹‹Mısırlıları Mısırlılara karşı ayaklandıracağım; 2 Kardeş kardeşe, komşu komşuya, kent kente, 2 Ülke ülkeye karşı savaşacak.'),
(2001351,68,23,19,3,'Mısırlıların cesareti tükenecek, 2 Tasarılarını boşa çıkaracağım. 2 Yardım için putlara, ölülerin ruhlarına, 2 Medyumlarla ruh çağıranlara danışacaklar.'),
(2001352,68,23,19,4,'Mısırlıları acımasız bir efendiye teslim edeceğim, 2 Katı yürekli bir kral onlara egemen olacak.›› 2 Rab, Her Şeye Egemen RAB böyle diyor.'),
(2001353,68,23,19,5,'Nilin suları çekilecek, 2 Kuruyup çatlayacak yatağı.'),
(2001354,68,23,19,6,'Su kanalları kokacak, 2 Kuruyacak ırmağın kolları, 2 Kamışlarla sazlar solacak.'),
(2001355,68,23,19,7,'Nil kıyısında, ırmağın ağzındaki sazlar, 2 Nil boyunca ekili tarlalar kuruyacak, 2 Savrulup yok olacak.'),
(2001356,68,23,19,8,'Balıkçılar yas tutacak, 2 Nile olta atanların hepsi ağlayacak, 2 Suyun yüzüne ağ atanlar perişan olacak.'),
(2001357,68,23,19,9,'Taranmış keten işleyenler, 2 Beyaz bez dokuyanlar umutsuzluğa kapılacak.'),
(2001358,68,23,19,10,'Dokumacılar bunalacak, 2 Ücretliler sıkıntıya düşecek.'),
(2001359,68,23,19,11,'Soanfş Kentinin önderleri ne kadar akılsız! 2 Firavunun bilge danışmanları 2 Saçma sapan öğütler veriyorlar. 2 Nasıl olur da firavuna, 2 ‹‹Biz bilgelerin oğulları, 2 Eski zaman krallarının torunlarıyız›› diyorlar?'),
(2001360,68,23,19,12,'Ey firavun, hani nerede senin bilgelerin? 2 Her Şeye Egemen RAB Mısıra karşı neler tasarladı, 2 Bildirsinler bakalım sana eğer biliyorlarsa.'),
(2001361,68,23,19,13,'Soan Kentinin önderleri aptal olup çıktılar, 2 Nof önderleri aldandılar, 2 Mısır oymaklarının ileri gelenleri Mısırı saptırdılar.'),
(2001362,68,23,19,14,'RAB onların aklını karıştırdı; 2 Kendi kusmuğu içinde yalpalayan sarhoş nasılsa, 2 Mısırı da her alanda saptırdılar.'),
(2001363,68,23,19,15,'Mısırda kimsenin yapabileceği bir şey kalmadı; 2 Ne başın ne kuyruğun, ne hurma dalının ne de sazın.'),
(2001364,68,23,19,16,'O gün Mısırlılar kadın gibi olacaklar; Her Şeye Egemen RABbin kendilerine karşı kalkan elinin önünde titreyip dehşete kapılacaklar.'),
(2001365,68,23,19,17,'Yahuda Mısırı dehşete düşürecek. Yahuda dendi mi, Her Şeye Egemen RABbin Mısıra karşı tasarladıklarını anımsayan herkes dehşete kapılacak.'),
(2001366,68,23,19,18,'O gün Mısırda Kenan dilini konuşan beş kent olacak. Bu kentler Her Şeye Egemen RABbe bağlılık andı içecekler; içlerinden biri ‹Yıkım Kenti› diye adlandırılacak. Heliopolis anlamına gelebilir.'),
(2001367,68,23,19,19,'O gün Mısırın ortasında RAB için bir sunak, sınırında da bir sütun dikilecek.'),
(2001368,68,23,19,20,'Her Şeye Egemen RAB için Mısırda bir belirti ve tanık olacak bu. Halk kendine baskı yapanlardan ötürü RABbe yakarınca, RAB onları savunacak bir kurtarıcı gönderip özgür kılacak.'),
(2001369,68,23,19,21,'RAB kendini Mısırlılara tanıtacak, onlar da o gün RABbi tanıyacak, kurbanlarla, sunularla Ona tapınacaklar. RABbe adak adayacak ve adaklarını yerine getirecekler.'),
(2001370,68,23,19,22,'RAB Mısırlıları hastalıkla alabildiğine cezalandıracak, sonra iyileştirecek. RABbe yönelip yakaracaklar. RAB de onları iyileştirecek.'),
(2001371,68,23,19,23,'O gün Mısırla Asur arasında bir yol olacak. Asurlu Mısıra, Mısırlı Asura gidip gelecek. Mısırlılarla Asurlular birlikte tapınacaklar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001372,68,23,19,24,'O gün Mısır ve Asurun yanısıra İsrail üçüncü ülke olacak. Dünya bu üçü sayesinde kutsanacak.'),
(2001373,68,23,19,25,'Her Şeye Egemen RAB, ‹‹Halkım Mısır, ellerimin işi Asur ve mirasım İsrail kutsansın›› diyerek dünyayı kutsayacak.'),
(2001374,68,23,20,1,'Asur ordusunun başkomutanı, Asur Kralı Sargonun buyruğuyla gelerek Aşdota saldırıp kenti ele geçirdiği yıl RAB Amots oğlu Yeşaya aracılığıyla şöyle dedi: ‹‹Git, belindeki çulu çöz, ayağındaki çarığı çıkar.›› Yeşaya denileni yaptı, çıplak ve yalınayak dolaşmaya başladı.'),
(2001375,68,23,20,3,'RAB dedi ki, ‹‹Mısıra ve Kûşa belirti ve ibret olsun diye kulum Yeşaya nasıl üç yıl çıplak ve yalınayak dolaştıysa,'),
(2001376,68,23,20,4,'Asur Kralı da Mısıra utanç olsun diye Mısırlı tutsaklarla Kûşlu sürgünleri genç yaşlı demeden, çıplak ve yalınayak, mahrem yerleri açık yürütecek.'),
(2001377,68,23,20,5,'Kûşa bel bağlayan, Mısırla övünen halk hüsrana uğrayacak, utanç içinde kalacak.'),
(2001378,68,23,20,6,'Bu kıyı bölgesinde yaşayanlar o gün, ‹‹Asur Kralı''nın elinden kurtulmak için yardımına sığındığımız, bel bağladığımız ulusların başına gelene bakın!›› diyecekler, ‹‹Biz nasıl kurtulacağız?››'),
(2001379,68,23,21,1,'Deniz kıyısındaki çölle ilgili bildiri: Negevden fırtınalar nasıl üst üste gelirse, 2 Çölden, korkunç ülkeden bir istilacı öyle geliyor.'),
(2001380,68,23,21,2,'Korkunç bir görüm gördüm: 2 Hain hainlik etmede, 2 Harap eden harap etmede. 2 Ey Elam, saldır! 2 Ey Meday, onu kuşat! 2 Onun neden olduğu iniltileri sona erdireceğim.'),
(2001381,68,23,21,3,'Gördüklerimden ötürü belime ağrı saplandı, 2 Doğuran kadının ağrıları gibi ağrılar tuttu beni. 2 Duyduklarımdan sarsıldım, 2 Gördüklerimden dehşete düştüm.'),
(2001382,68,23,21,4,'Şaşkınım, titremeler sardı beni. 2 Özlediğim alaca karanlık bana korku veriyor artık.'),
(2001383,68,23,21,5,'Gördüğüm görümde sofrayı hazırlıyor, 2 Halıları seriyor, yiyip içiyorlar. 2 Kalkın, ey önderler, kalkanları yağlayın!'),
(2001384,68,23,21,6,'Rab bana dedi ki, 2 ‹‹Git, bir gözcü dik, gördüğünü bildirsin.'),
(2001385,68,23,21,7,'Savaş arabalarının, 2 Atlara, eşeklere, develere binmiş insanların 2 Çifter çifter geldiğini görünce dikkat kesilsin.››'),
(2001386,68,23,21,8,'Gözcüfü, ‹‹Ey efendim, 2 Her gün aralıksız gözcü kulesinde duruyor, 2 Her gece yerimde nöbet tutuyorum›› diye bağırdı,'),
(2001387,68,23,21,9,'‹‹Bak, savaş arabalarıyla atlılar 2 Çifter çifter geliyor!›› 2 Sonra, ‹‹Yıkıldı, Babil yıkıldı!›› diye haber verdi, 2 ‹‹Taptıkları bütün putlar yere çalınıp parçalandı!››'),
(2001388,68,23,21,10,'Ey halkım, harman yerinde 2 Buğday gibi dövülmüş olan halkım! 2 Her Şeye Egemen RABden, 2 İsrailin Tanrısından duyduklarımı 2 Size bildirdim.'),
(2001389,68,23,21,11,'Duma ile ilgili bildiri: Arabistanda bir yer olduğu sanılıyor. ‹‹Sessizlik›› anlamına gelir. ‹‹Edom›› sözcüğünü çağrıştırıyor. Biri Seirden bana sesleniyor: 2 ‹‹Ey gözcü, geceden geriye ne kaldı? 2 Geceden geriye ne kaldı?››'),
(2001390,68,23,21,12,'Yanıtım şöyle: ‹‹Sabah olmak üzere, 2 Ama yine gece olacak. 2 Soracaksanız sorun, yine gelin.››'),
(2001391,68,23,21,13,'Arabistanla ilgili bildiri: Arabistan çalılıklarında geceleyeceksiniz, 2 Ey Dedan kervanları!'),
(2001392,68,23,21,14,'Ey Temada oturanlar, 2 Su getirin, susamışları karşılayın, 2 Kaçıp kurtulana ekmek verin.'),
(2001393,68,23,21,15,'Çünkü onlar kılıçtan, yalın kılıçtan, 2 Gerilmiş yaydan, çetin çarpışmalardan kaçtılar.'),
(2001394,68,23,21,16,'Rab bana şöyle dedi: ‹‹Kedarın bütün övüncü tam bir yıl sonra sona erecek.'),
(2001395,68,23,21,17,'Okçulardan, Kedar savaşçılarından pek az sağ kalan olacak.›› Bunu söyleyen, İsrail''in Tanrısı RAB''dir.'),
(2001396,68,23,22,1,'Görüm Vadisiyle ilgili bildiri: Gürültü patırtı içinde eğlenen kent halkı, 2 Ne oldu size, neden hepiniz damlara çıktınız? 2 Ölenleriniz ne kılıçtan geçirildi, 2 Ne de savaşta öldü.'),
(2001397,68,23,22,3,'Önderleriniz hep birlikte kaçtılar, 2 Yaylarını kullanmadan tutsak alındılar. 2 Uzağa kaçtığınız halde ele geçenlerin hepsi tutsak edildi.'),
(2001398,68,23,22,4,'Bunun için dedim ki, 2 ‹‹Beni yalnız bırakın, acı acı ağlayayım. 2 Halkımın uğradığı yıkımdan ötürü 2 Beni avutmaya kalkmayın.››'),
(2001399,68,23,22,5,'Çünkü Rabbin, Her Şeye Egemen RABbin 2 Görüm Vadisinde kargaşa, bozgun 2 Ve dehşet saçacağı gün, 2 Duvarların yıkılacağı, 2 Dağlara feryat edileceği gün geliyor.'),
(2001400,68,23,22,6,'Elamlılar ok kılıflarını sırtlanıp savaş arabalarıyla, 2 Atlılarıyla geldiler. 2 Kîr halkı kalkanlarını açtı.'),
(2001401,68,23,22,7,'Verimli vadileriniz savaş arabalarıyla doldu, 2 Atlılar kent kapılarının karşısına dizildi.'),
(2001402,68,23,22,8,'RABbin Yahudayı savunmasız bıraktığı gün 2 Orman Sarayındaki silahlara güvendiniz.'),
(2001403,68,23,22,9,'Davut Kentinin duvarlarında 2 Çok sayıda gedik olduğunu gördünüz, 2 Aşağı Havuzda su depoladınız,'),
(2001404,68,23,22,10,'Yeruşalimdeki evleri saydınız, 2 Surları onarmak için evleri yıktınız.'),
(2001405,68,23,22,11,'Eski Havuzun suları için 2 İki surun arasında bir depo yaptınız. 2 Ama bunu çok önceden tasarlayıp 2 Gerçekleştirmiş olan Tanrıya güvenmediniz, 2 Onu umursamadınız.'),
(2001406,68,23,22,12,'Rab, Her Şeye Egemen RAB 2 O gün sizi ağlayıp yas tutmaya, 2 Saçlarınızı kesip çul kuşanmaya çağırdı.'),
(2001407,68,23,22,13,'Oysa siz keyif çatıp eğlendiniz, 2 ‹‹Yiyelim içelim, nasıl olsa yarın öleceğiz›› diyerek 2 Sığır, koyun kestiniz, 2 Et yiyip şarap içtiniz.'),
(2001408,68,23,22,14,'Her Şeye Egemen RAB bana, 2 ‹‹Siz ölene dek bu suçunuz bağışlanmayacak›› diye seslendi. 2 Rab, Her Şeye Egemen RAB böyle diyor.'),
(2001409,68,23,22,15,'Rab, Her Şeye Egemen RAB diyor ki, 2 ‹‹Haydi, o kâhyaya, 2 Sarayın sorumlusu Şevnaya git ve de ki,'),
(2001410,68,23,22,16,'‹Burada ne işin var? 2 Kimin var ki, kendine burada mezar kazdın, 2 Yüksekte kendine mezar, kayada konut oydun?'),
(2001411,68,23,22,17,'Ey güçlü kişi, 2 RAB seni tuttuğu gibi şiddetle savuracak.'),
(2001412,68,23,22,18,'Top gibi evirip çevirip 2 Geniş bir ülkeye fırlatacak. 2 Orada öleceksin, 2 Gurur duyduğun arabaların orada kalacak. 2 Efendinin evi için utanç nedenisin!'),
(2001413,68,23,22,19,'Seni görevden alacak, 2 Makamından alaşağı edeceğim.'),
(2001414,68,23,22,20,'‹‹ ‹O gün Hilkiya oğlu kulum Elyakimi çağırıp'),
(2001415,68,23,22,21,'Senin cüppeni ona giydireceğim. 2 Senin kuşağınla onu güçlendirip 2 Yetkini ona vereceğim. 2 Yeruşalimde yaşayanlara 2 Ve Yahuda halkına o babalık yapacak.'),
(2001416,68,23,22,22,'Davutun evinin anahtarını ona teslim edeceğim. 2 Açtığını kimse kapayamayacak, 2 Kapadığını kimse açamayacak.'),
(2001417,68,23,22,23,'Onu sağlam yere çakılmış çadır kazığı yapacağım, 2 Ailesi için onur kürsüsü olacak.'),
(2001418,68,23,22,24,'Ailenin ağırlığı -soyundan türeyen herkes- 2 Taslardan kâselere kadar her küçük kap ona asılacak.› ››'),
(2001419,68,23,22,25,'Her Şeye Egemen RAB diyor ki, ‹‹O gün sağlam yere çakılmış kazık yerinden çıkacak, kırılıp düşecek, ona asılan yük de yok olacak.›› Çünkü RAB böyle diyor.'),
(2001420,68,23,23,1,'Sur Kentiyle ilgili bildiri: Ey ticaret gemileri, feryat edin! 2 Çünkü Sur Kenti evleriyle, 2 Limanlarıyla birlikte yok oldu. 2 Kittimden size haber geldi.'),
(2001421,68,23,23,2,'Ey kıyı halkı ve denizcilerin zenginleştirdiği 2 Sayda tüccarları, susun!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001422,68,23,23,3,'Şihorun tahılı, Nilin ürünü 2 Denizleri aşar, Sura gelir sağlardı. 2 Ulusların kârı ona akardı.'),
(2001423,68,23,23,4,'Utan, ey Sayda, ey deniz kıyısındaki kale! 2 Çünkü deniz sana sesleniyor: 2 ‹‹Ne doğum ağrısı çektim, ne de doğurdum. 2 Ne delikanlılar büyüttüm, ne de kızlar.››'),
(2001424,68,23,23,5,'Surun haberi Mısıra ulaşınca, 2 Yüreği burkulacak insanların.'),
(2001425,68,23,23,6,'Tarşişe geçin, ey kıyıda oturanlar, 2 Feryat edin.'),
(2001426,68,23,23,7,'Uzak ülkeleri yurt edinmiş, 2 Eğlenceye düşkün halkınız, 2 Eski, tarihsel kentiniz bu mu?'),
(2001427,68,23,23,8,'Taçlar giydiren Sura karşı bu işi kim tasarladı? 2 O kent ki, tüccarları prenslerdi, 2 İş adamları dünyanın saygın kişileriydi.'),
(2001428,68,23,23,9,'Görkeminin sonucu olan gururunu kırmak, 2 Dünyaca ünlü bütün saygın kişilerini alçaltmak için 2 Her Şeye Egemen RAB tasarladı bunu.'),
(2001429,68,23,23,10,'Kendi topraklarını Nil gibi basıp geç, 2 Ey Tarşiş kızı, artık engel yok.'),
(2001430,68,23,23,11,'RAB denizin üzerine elini uzatıp ülkeleri titretti, 2 Kenan kalelerinin yıkılmasını buyurdu.'),
(2001431,68,23,23,12,'‹‹Eğlencen sona erdi, ey Sayda, erden kız!›› dedi, 2 ‹‹Kirletildin. 2 Kalk, Kittime geç, 2 Orada bile rahat yüzü görmeyeceksin.››'),
(2001432,68,23,23,13,'Kildan ülkesine bak! 2 O halk yok artık. 2 Asurlular onların ülkesini yabanıl hayvanlara verdi, 2 Kuşatma kuleleri diktiler, saraylarını soydular, 2 Ülkeyi viraneye çevirdiler.'),
(2001433,68,23,23,14,'Feryat edin, ey ticaret gemileri! 2 Çünkü sığınağınız harap oldu.'),
(2001434,68,23,23,15,'Bundan sonra Sur Kenti yetmiş yıl, bir kralın ömrü süresince unutulacak. Yetmiş yıl bitince, fahişe için bestelenen türküdeki gibi Sura şöyle denecek:'),
(2001435,68,23,23,16,'‹‹Bir lir al, dolaş kenti, 2 Ey sen, unutulmuş fahişe! 2 Güzel çal seni anımsamaları için, 2 Türkü üstüne türkü söyle.››'),
(2001436,68,23,23,17,'Yetmiş yıl geçince RAB Surla ilgilenecek, ama Sur para için yine fahişeliğe dönecek. Dünyanın bütün krallıklarıyla fahişelik edecek.'),
(2001437,68,23,23,18,'Kentin ticaretten ve fuhuştan kazandıkları RAB''be adanacak. Bunlar biriktirilmeyecek, hazineye konmayacak. Ticaretten kazandıklarını doyuncaya dek yesinler, güzel güzel giyinsinler diye RAB''bin önünde yaşayanlara verilecek.'),
(2001438,68,23,24,1,'İşte RAB yeryüzünü harap edip viraneye çevirecek, 2 Yeryüzünü altüst edecek, 2 Üzerinde yaşayanları darmadağın edecek.'),
(2001439,68,23,24,2,'Ayrım yapılmayacak; 2 Ne halkla kâhin arasında, 2 Ne köleyle efendi arasında, 2 Ne hizmetçiyle hanım arasında, 2 Ne alıcıyla satıcı arasında, 2 Ne ödünç alanla ödünç veren arasında, 2 Ne faizciyle borç alan arasında.'),
(2001440,68,23,24,3,'Dünya tümüyle yağmalanıp viraneye çevrilecek. 2 RAB böyle söyledi.'),
(2001441,68,23,24,4,'Dünya kuruyup büzülüyor, 2 Yeryüzü solup büzülüyor, 2 Dünyadaki soylular güçlerini yitiriyor.'),
(2001442,68,23,24,5,'Dünyada yaşayanlar onu kirletti. 2 Çünkü Tanrının yasalarını çiğnediler, 2 Kurallarını ayaklar altına aldılar, 2 Ebedi antlaşmayı bozdular.'),
(2001443,68,23,24,6,'Bu yüzden lanet dünyayı yiyip bitirdi, 2 Orada yaşayanlar suçlarının cezasını çekiyorlar. 2 Yaşayanlar bu nedenle yanıyor, pek azı kurtulacak.'),
(2001444,68,23,24,7,'Yeni şarabın sonu geldi, 2 Asmalar soldu, 2 Bir zamanlar sevinçli olanların hepsi inliyor.'),
(2001445,68,23,24,8,'Tefin coşkun sesi kesildi, 2 Eğlenenlerin gürültüsü durdu, 2 Lirin coşkun sesi kesildi.'),
(2001446,68,23,24,9,'Ezgi eşliğinde şarap içilmiyor artık, 2 İçkinin tadı içene acı geliyor.'),
(2001447,68,23,24,10,'Yıkılan kent perişan durumda, 2 Kimse girmesin diye her evin girişi kapandı.'),
(2001448,68,23,24,11,'İnsanlar şarap özlemiyle sokaklarda bağrışıyor, 2 Sevinçten eser kalmadı, 2 Dünyanın coşkusu yok oldu.'),
(2001449,68,23,24,12,'Kent viraneye döndü, 2 Kapıları paramparça oldu.'),
(2001450,68,23,24,13,'Çünkü zeytinler dökülsün diye dövülen ağaç nasılsa, 2 Bağbozumundan artakalan üzümler nasılsa, 2 Dünyadaki bütün uluslar da öyle olacak.'),
(2001451,68,23,24,14,'Sağ kalanlar seslerini yükseltip 2 Sevinç çığlıkları atacak, 2 Batıda yaşayanlar RABbin büyüklüğü karşısında 2 Hayranlıkla bağıracak.'),
(2001452,68,23,24,15,'Onun için, doğuda yaşayanlar RABbi yüceltin, 2 Deniz kıyısındakiler, 2 İsrailin Tanrısı RABbin adını yüceltin.'),
(2001453,68,23,24,16,'Dünyanın en uzak köşelerinden ezgiler işitiyoruz: 2 ‹‹Doğru Olana övgüler olsun!›› Ama ben, ‹‹Bittim, bittim! Vay halime!›› dedim, 2 ‹‹Hainler hainliklerini sürdürüyor. 2 Evet, hainler sürekli hainlik ediyorlar.››'),
(2001454,68,23,24,17,'Ey dünyada yaşayanlar, 2 Önünüzde dehşet, çukur ve tuzak var.'),
(2001455,68,23,24,18,'Dehşet haberinden kaçan çukura düşecek, 2 Çukurdan çıkan tuzağa yakalanacak. 2 Göklerin kapakları açılacak, 2 Dünyanın temelleri sarsılacak.'),
(2001456,68,23,24,19,'Yeryüzü büsbütün çatlayıp yarılacak, 2 Sarsıldıkça sarsılacak.'),
(2001457,68,23,24,20,'Dünya sarhoş gibi yalpalayacak, 2 Bir kulübe gibi sallanacak, 2 İsyanlarının ağırlığı altında çökecek 2 Ve bir daha kalkamayacak.'),
(2001458,68,23,24,21,'O gün RAB yukarıda, gökteki güçleri 2 Ve aşağıda, yeryüzündeki kralları cezalandıracak.'),
(2001459,68,23,24,22,'Zindana tıkılan tutsaklar gibi 2 Cezaevine kapatılacak 2 Ve uzun süre sonra cezalandırılacaklar.'),
(2001460,68,23,24,23,'Ayın yüzü kızaracak, güneş utanacak. 2 Çünkü Her Şeye Egemen RAB Siyon Dağı''nda, 2 Yeruşalim''de krallık edecek. 2 Halkın ileri gelenleri 2 O''nun yüceliğini görecek.'),
(2001461,68,23,25,1,'Ya RAB, sensin benim Tanrım, 2 Seni yüceltir, adını överim. 2 Çünkü sen eskiden beri tasarladığın harikaları 2 Tam bir sadakatle gerçekleştirdin.'),
(2001462,68,23,25,2,'Kenti bir taş yığınına, 2 Surlu kenti viraneye çevirdin. 2 Yabancıların kalesiydi, kent olmaktan çıktı. 2 Bir daha da onarılmayacak.'),
(2001463,68,23,25,3,'Bundan ötürü güçlü uluslar seni onurlandıracak, 2 Acımasız ulusların kentleri senden korkacak.'),
(2001464,68,23,25,4,'Çünkü onların öfkesi 2 Duvara çarpan sağanak gibi yükselince, 2 Sen yoksulun, sıkıntı içindeki düşkünün kalesi, 2 Sağanağa karşı sığınak, 2 Sıcağa karşı gölgelik oldun.'),
(2001465,68,23,25,5,'Yabancıların gürültüsünü çöl sıcağı gibi bastırırsın. 2 Bulutun gölgesi sıcağı nasıl kırarsa, 2 Bu acımasız adamların türküsü de öyle diniyor.'),
(2001466,68,23,25,6,'Her Şeye Egemen RAB bu dağda 2 Bütün uluslara yağlı yemeklerin 2 Ve dinlendirilmiş seçkin şarapların sunulduğu 2 Zengin bir şölen verecek.'),
(2001467,68,23,25,7,'Bütün halkların üzerindeki örtüyü, 2 Bütün ulusların üzerine örülmüş olan örtüyü 2 Bu dağda kaldıracak.'),
(2001468,68,23,25,8,'Ölümü sonsuza dek yutacak. 2 Egemen RAB bütün yüzlerden gözyaşlarını silecek. 2 Halkının utancını bütün yeryüzünden kaldıracak. 2 Çünkü RAB böyle diyor.'),
(2001469,68,23,25,9,'O gün diyecekler ki, 2 ‹‹İşte Tanrımız budur; 2 Ona umut bağlamıştık, bizi kurtardı, 2 RAB Odur, Ona umut bağlamıştık, 2 Onun kurtarışıyla sevinip coşalım.››'),
(2001470,68,23,25,10,'RABbin eli bu dağın üzerinde kalacak, 2 Ama Moav gübre çukurundaki saman gibi 2 Kendi yerinde çiğnenecek.'),
(2001471,68,23,25,11,'Oracıkta yüzmek isteyen biri gibi ellerini uzatacak, 2 Ama kurnazlığına karşın RAB onun gururunu kıracak.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001472,68,23,25,12,'RAB surlarındaki yüksek burçları 2 Devirip yıkacak, yerle bir edecek.'),
(2001473,68,23,26,1,'O gün Yahudada şu ilahi söylenecek: Güçlü bir kentimiz var. 2 Çünkü Tanrının kurtarışı 2 Kente sur ve duvar gibidir.'),
(2001474,68,23,26,2,'Açın kentin kapılarını, 2 Sadık kalan doğru ulus içeri girsin.'),
(2001475,68,23,26,3,'Sana güvendiği için 2 Düşüncelerinde sarsılmaz olanı 2 Tam bir esenlik içinde korursun.'),
(2001476,68,23,26,4,'RABbe sonsuza dek güvenin, 2 Çünkü RAB, evet RAB sonsuza dek kalıcı kayadır.'),
(2001477,68,23,26,5,'Yüksekte oturanı alçaltır, 2 Yüce kenti yıkar, 2 Yerle bir eder.'),
(2001478,68,23,26,6,'O kent ayak altında, 2 Mazlumların ayakları, 2 Yoksulların adımları altında çiğnenecek.'),
(2001479,68,23,26,7,'Doğru adamın yolu düzdür, 2 Ey Dürüst Olan, doğru adamın yolunu sen düzlersin.'),
(2001480,68,23,26,8,'Evet, ya RAB, ilkelerinin çizdiği yolda sana umut bağladık, 2 Adın ve ünündür yüreğimizin dileği,'),
(2001481,68,23,26,9,'Geceleri canım sana susar, 2 Evet, içimde ruhum seni özler; 2 Çünkü senin ilkelerin yeryüzünde oldukça, 2 Orada oturanlar doğruluğu öğrenir.'),
(2001482,68,23,26,10,'Kötüler lütfedilse bile doğruluğu öğrenmez. 2 Dürüstlüğün egemen olduğu diyarda haksızlık eder, 2 RABbin büyüklüğünü görmezler.'),
(2001483,68,23,26,11,'Ya RAB, elin yükseldi, ama görmüyorlar, 2 Halkın için gösterdiğin gayreti görüp utansınlar. 2 Evet, düşmanların için yaktığın ateş onları yiyip bitirecek.'),
(2001484,68,23,26,12,'Ya RAB, bizi esenliğe çıkaracak sensin, 2 Çünkü ne yaptıysak hepsi senin başarındır.'),
(2001485,68,23,26,13,'Ey Tanrımız RAB, senden başka efendiler bizi yönetti, 2 Ama yalnız sana, senin adına yakaracağız.'),
(2001486,68,23,26,14,'O efendiler öldü, artık yaşamıyorlar, 2 Dirilmeyecek onlar. 2 Çünkü onları cezalandırıp yok ettin, 2 Anılmalarına son verdin.'),
(2001487,68,23,26,15,'Ulusu çoğalttın, ya RAB, 2 Evet, ulusu çoğalttın ve yüceltildin. 2 Her yönde ülkenin sınırlarını genişlettin.'),
(2001488,68,23,26,16,'Ya RAB, sıkıntıdayken seni aradılar. 2 Onları terbiye ettiğinde sessizce yakararak içlerini döktüler.'),
(2001489,68,23,26,17,'Doğum vakti yaklaşan gebe kadın 2 Çektiği sancıdan ötürü nasıl kıvranır, feryat ederse, 2 Senin önünde biz de öyle olduk, ya RAB.'),
(2001490,68,23,26,18,'Gebe kaldık, kıvrandık, 2 Rüzgardan başka bir şey doğurmadık sanki. 2 Ne dünyaya kurtuluş sağlayabildik, 2 Ne de dünyada yaşayanları yaşama kavuşturabildik.'),
(2001491,68,23,26,19,'Ama senin ölülerin yaşayacak, 2 Bedenleri dirilecek. 2 Ey sizler, toprak altında yatanlar, 2 Uyanın, ezgiler söyleyin. 2 Çünkü senin çiyin sabah çiyine benzer, 2 Toprak ölülerini yaşama kavuşturacak.'),
(2001492,68,23,26,20,'Haydi halkım, iç odalarınıza girip 2 Ardınızdan kapılarınızı kapatın, 2 RABbin öfkesi geçene dek kısa süre gizlenin.'),
(2001493,68,23,26,21,'Çünkü dünyada yaşayanları 2 Suçlarından ötürü cezalandırmak için 2 RAB bulunduğu yerden geliyor. 2 Dünya üzerine dökülen kanı açığa vuracak, 2 Öldürülenleri artık saklamayacak.'),
(2001494,68,23,27,1,'O gün RAB Livyatanı, o kaçan yılanı, 2 Evet Livyatanı, o kıvrıla kıvrıla giden yılanı 2 Acımasız, kocaman, güçlü kılıcıyla cezalandıracak, 2 Denizdeki canavarı öldürecek.'),
(2001495,68,23,27,2,'O gün RAB, 2 ‹‹Sevdiğim bağ için ezgiler söyleyin›› diyecek,'),
(2001496,68,23,27,3,'‹‹Ben RAB, bağın koruyucusuyum, 2 Onu sürekli sularım. 2 Kimse zarar vermesin diye 2 Gece gündüz beklerim.'),
(2001497,68,23,27,4,'Kızgın değilim. 2 Keşke karşıma dikenli çalılar çıksa! 2 Onların üzerine yürür, 2 Tümünü ateşe verirdim.'),
(2001498,68,23,27,5,'Ya da koruyuculuğuma sarılsınlar, 2 Barışsınlar benimle, 2 Evet, benimle barışsınlar.››'),
(2001499,68,23,27,6,'Yakup soyu gelecekte kök salacak, 2 İsrail filizlenip çiçeklenecek, 2 Yeryüzünü meyvesiyle dolduracak.'),
(2001500,68,23,27,7,'RAB İsraillileri, kendilerini cezalandıranları cezalandırdığı gibi cezalandırdı mı? 2 Ya da İsraillileri başkalarını öldürdüğü gibi öldürdü mü?'),
(2001501,68,23,27,8,'RAB onları yargıladı, 2 Kovup sürgüne gönderdi. 2 Doğu rüzgarının estiği gün 2 Onları şiddetli soluğuyla savurdu.'),
(2001502,68,23,27,9,'Böylece Yakup soyunun suçu bağışlanacak. 2 Günahlarının kaldırılmasının sonucu şöyle olacak: 2 Sunağın taşlarını tebeşir taşı gibi un ufak ettiklerinde 2 Ne Aşera putu ne de buhur sunağı kalacak.'),
(2001503,68,23,27,10,'Surlu kent terk edildi, 2 Çöl kadar ıssız, sahipsiz bir yurt oldu. 2 Dana orada otlayıp uzanacak, 2 Filizlerini yiyip bitirecek.'),
(2001504,68,23,27,11,'Kuruyan dalları koparılacak, 2 Kadınlar gelip bunları yakacaklar. 2 Çünkü bu halk akıllı bir halk değil. 2 Bu yüzden onları yaratan kendilerine acımayacak, 2 Onlara biçim veren onları kayırmayacak.'),
(2001505,68,23,27,12,'Ey İsrailoğulları, o gün RAB gürül gürül akan Fırat ile Mısır Vadisi arasında harman döver gibi, sizi birer birer toplayacak.'),
(2001506,68,23,27,13,'Evet, o gün büyük bir boru çalınacak; Asur''da yitenlerle Mısır''a sürgün edilenler gelip kutsal dağda, Yeruşalim''de RAB''be tapınacaklar.'),
(2001507,68,23,28,1,'Vay haline verimli vadinin başındaki kentin, Efrayimli sarhoşların gurur tacının! Şaraba yenilmişlerin yüce ve görkemli tacı, solmakta olan çiçeği andırıyor.'),
(2001508,68,23,28,2,'Rabbin güçlü kudretli bir adamı var. Dolu fırtınası gibi, harap eden kasırga gibi, silip süpüren güçlü sel gibi o kenti şiddetle yere çalacak.'),
(2001509,68,23,28,3,'Efrayimli sarhoşların gurur tacı ayaklar altında çiğnenecek.'),
(2001510,68,23,28,4,'Verimli vadinin başındaki kent, yüce ve görkemli taç, artık solmakta olan çiçeği andıran kent, mevsiminden önce olgunlaşmış incir gibi görülür görülmez koparılıp yutulacak.'),
(2001511,68,23,28,5,'O gün Her Şeye Egemen RAB, halkından sağ kalanlar için yücelik tacı, güzellik çelengi olacak.'),
(2001512,68,23,28,6,'Yargı kürsüsünde oturanlar için adalet ruhu, kent kapılarında saldırıları geri püskürtenler için cesaret kaynağı olacak.'),
(2001513,68,23,28,7,'Kâhinlerle peygamberler bile şarabın ve içkinin etkisiyle yalpalayıp sendeliyor; içkinin etkisiyle yalpalayıp sendeliyorlar, şaraba yenik düşmüşler. Yanlış görümler görüyorlar, kararlarında tutarsızlar.'),
(2001514,68,23,28,8,'Sofralar kusmuk dolu, pisliğe bulaşmamış yer yok!'),
(2001515,68,23,28,9,'‹‹Kimi eğitmeye çalışıyor?›› diyorlar, ‹‹Kime iletiyor bildirisini? Sütten yeni kesilmiş, memeden yeni ayrılmış çocuklara mı?'),
(2001516,68,23,28,10,'Çünkü bütün söylediği buyruk üstüne buyruk, buyruk üstüne buyruk, kural üstüne kural, kural üstüne kural, biraz şurdan, biraz burdan...›› ‹‹Sav lasav, sav lasav, kav lakav, kav lakav, zeer şam, zeer şam!››'),
(2001517,68,23,28,11,'Öyle olsun, o zaman RAB bu halka yabancı dudaklarla, anlaşılmaz bir dille seslenecek.'),
(2001518,68,23,28,12,'Onlara, ‹‹Rahatlık budur, yorgunların rahat etmelerini sağlayın, huzur budur›› dedi, ama dinlemek istemediler.'),
(2001519,68,23,28,13,'Bu yüzden RABbin sözü onlar için ‹‹Buyruk üstüne buyruk, buyruk üstüne buyruk, kural üstüne kural, kural üstüne kural, biraz şurdan, biraz burdan››dır. Madem öyle, varsın sırtüstü düşüp yaralansınlar, kapana kısılıp tutsak olsunlar.'),
(2001520,68,23,28,14,'Bundan ötürü, ey alaycılar, Yeruşalimdeki bu halkı yöneten sizler, RABbin sözüne kulak verin.'),
(2001521,68,23,28,15,'Şöyle diyorsunuz: ‹‹Ölümle antlaşma yaptık, ölüler diyarıyla uyuştuk; öyle ki, büyük bela ülkeden geçerken bize zarar vermeyecek. Çünkü yalanları kendimize sığınak yaptık, hilenin ardına gizlendik.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001522,68,23,28,16,'Bu yüzden Egemen RAB diyor ki, ‹‹İşte Siyona sağlam temel olarak bir taş, denenmiş bir taş, değerli bir köşe taşı yerleştiriyorum. Ona güvenen yenilmeyecek.'),
(2001523,68,23,28,17,'Adaleti ölçü ipi, doğruluğu çekül yapacağım. Yalanlara dayanan sığınağı dolu süpürüp götürecek, gizlendiğiniz yerleri sel basacak.'),
(2001524,68,23,28,18,'Ölümle yaptığınız antlaşma yürürlükten kaldırılacak, ölüler diyarıyla uyuşmanız geçerli sayılmayacak. Büyük bela ülkeden geçerken sizi çiğneyecek.'),
(2001525,68,23,28,19,'Bu bela her geldiğinde sizi süpürüp götürecek. Her gün, gece gündüz gelecek. Bu bildiriyi anlayan dehşete kapılacak.'),
(2001526,68,23,28,20,'Yatak uzanamayacağınız kadar kısa, örtü sarınamayacağınız kadar dar olacak.'),
(2001527,68,23,28,21,'Çünkü RAB, Perasim Dağında olduğu gibi kalkacak, Givon Vadisinde olduğu gibi öfkelenecek. Ne kadar garip olsa da işini tamamlayacak, ne kadar tuhaf olsa da yapacağını yapacak.'),
(2001528,68,23,28,22,'Alay etmeyin artık, yoksa zincirleriniz daha da kalınlaşır. Çünkü bütün ülkenin kesin bir yıkıma uğrayacağını Rabden, Her Şeye Egemen RABden duydum.'),
(2001529,68,23,28,23,'Kulak verin, sesimi işitin, dikkat edin, ne söylediğimi dinleyin.'),
(2001530,68,23,28,24,'Çiftçi ekin ekmek için durmadan toprağı sürer mi, boyuna eşeleyip tırmıklar mı?'),
(2001531,68,23,28,25,'Toprağı düzledikten sonra çörekotunu, kimyonu serpmez mi? Buğdayı sıra sıra, arpayı ayırdığı yere, kızıl buğdayı da onun yanına ekmez mi?'),
(2001532,68,23,28,26,'Tanrısı ona uygun olanı gösterir, onu eğitir.'),
(2001533,68,23,28,27,'Çünkü çörekotu harmanda keskin aletle dövülmez, kimyonun üzerinden tekerlekle geçilmez. Çörekotu değnekle, kimyon çubukla dövülür.'),
(2001534,68,23,28,28,'Buğday ekmek yapmak için öğütülür, ama boyuna dövülmez. Harmanın üzerinden tekerlek ve atlar geçse de buğdayı ezmez.'),
(2001535,68,23,28,29,'Bu işteki bilgelik de Her Şeye Egemen RAB''den gelir. O''nun tasarıları harikadır, bilgelikte üstündür.'),
(2001536,68,23,29,1,'Ariel, Ariel, 2 Davutun ordugah kurduğu kent, vay haline! 2 Sen yıla yıl kat, bayramların süredursun. anlamına gelebilir. Yeruşalim Kentini simgeliyor.'),
(2001537,68,23,29,2,'Ama seni sıkıntıya sokacağım. 2 Feryat, figan edeceksin, 2 Benim için sunak ocağı gibi olacaksın.'),
(2001538,68,23,29,3,'Sana karşı çepeçevre ordugah kuracak, 2 Çevreni rampalarla, kulelerle kuşatacağım.'),
(2001539,68,23,29,4,'Alçaltılacaksın, yerin altından konuşacak, 2 Toz toprak içinden boğuk boğuk sesleneceksin. 2 Sesin ölü sesi gibi yerden, 2 Sözlerin fısıltı gibi toprağın içinden çıkacak.'),
(2001540,68,23,29,5,'Ama sayısız düşmanların ince toz, 2 Acımasız orduları savrulmuş saman ufağı gibi olacak. 2 Bir anda, ansızın,'),
(2001541,68,23,29,6,'Her Şeye Egemen RAB gök gürlemesiyle, 2 Depremle, büyük gümbürtü, kasırga ve fırtınayla, 2 Her şeyi yiyip bitiren ateş aleviyle seni cezalandıracak.'),
(2001542,68,23,29,7,'Sonra Ariele karşı savaşan çok sayıda ulus, 2 Ona ve kalesine saldıranların hepsi, 2 Onu sıkıntıya sokanlar bir rüya gibi, 2 Gece görülen görüm gibi yok olup gidecekler.'),
(2001543,68,23,29,8,'Rüyada yemek yediğini gören aç kişi, 2 Uyandığında hâlâ açtır; 2 Rüyada su içtiğini gören susuz kişi, 2 Uyandığında susuzluktan hâlâ baygındır. 2 İşte Siyon Dağına karşı savaşan 2 Kalabalık uluslar da böyle olacak.'),
(2001544,68,23,29,9,'Şaşırın, şaşkına dönün, 2 Kendinizi kör edin, görmez olun. 2 Şarap içmeden sarhoş olun, 2 İçki içmeden sendeleyin.'),
(2001545,68,23,29,10,'Çünkü RAB size uyuşukluk ruhu verdi; 2 Gözlerinizi mühürledi, ey peygamberler, 2 Başlarınızı örttü, ey biliciler.'),
(2001546,68,23,29,11,'Sizin için bütün görüm 2 Mühürlenmiş bir kitabın sözleri gibi oldu. 2 İnsanlar böyle bir kitabı 2 Okuma bilen birine verip, 2 ‹‹Rica etsek şunu okur musun?›› diye sorduklarında, 2 ‹‹Okuyamam, çünkü mühürlenmiş›› yanıtını alırlar.'),
(2001547,68,23,29,12,'Kitabı okuma bilmeyen birine verip, 2 ‹‹Rica etsek şunu okur musun?›› diye sorduklarında ise, 2 ‹‹Okuma bilmem›› yanıtını alırlar.'),
(2001548,68,23,29,13,'Rab diyor ki, ‹‹Bu halk bana yaklaşıp 2 Ağızlarıyla, dudaklarıyla beni sayar, 2 Ama yürekleri benden uzak. 2 Benden korkmaları da 2 İnsanlardan öğrendikleri buyrukların sonucudur.'),
(2001549,68,23,29,14,'Onun için ben de bu halkın arasında yine bir harika, 2 Evet, şaşılacak bir şey yapacağım. 2 Bilgelerin bilgeliği yok olacak, 2 Akıllının aklı duracak.››'),
(2001550,68,23,29,15,'Tasarılarını RABden gizlemeye uğraşanların vay haline! 2 Karanlıkta iş gören bu adamlar, 2 ‹‹Bizi kim görecek, kim tanıyacak?›› diye düşünürler.'),
(2001551,68,23,29,16,'Ne kadar ters düşünceler! 2 Çömlekçi balçıkla bir tutulur mu? 2 Yapı, kendini yapan için, 2 ‹‹Beni o yapmadı›› diyebilir mi? 2 Çömlek kendine biçim veren için, 2 ‹‹O bir şeyden anlamaz›› diyebilir mi?'),
(2001552,68,23,29,17,'Lübnan pek yakında meyve bahçesine, 2 Meyve bahçesi ormana dönmeyecek mi?'),
(2001553,68,23,29,18,'O gün sağırlar kitabın sözlerini işitecek, 2 Körler koyu karanlıkta görecek.'),
(2001554,68,23,29,19,'Düşkünlerin RABde buldukları sevinç artacak, 2 Yoksullar İsrailin Kutsalı sayesinde coşacak.'),
(2001555,68,23,29,20,'Çünkü acımasızlar yok olacak, alaycılar silinecek, 2 Kötülüğe fırsat kollayanların hepsi kesilip atılacak.'),
(2001556,68,23,29,21,'Onlar ki, insanı tek sözle davasında suçlu çıkarır, 2 Kent kapısında haksızı azarlayana tuzak kurar, 2 Yok yere haklının hakkını çiğnerler.'),
(2001557,68,23,29,22,'Bundan dolayı, İbrahimi kurtarmış olan RAB 2 Yakup soyuna diyor ki, 2 ‹‹Yakup soyu artık utanmayacak, 2 Yüzleri korkudan sararmayacak.'),
(2001558,68,23,29,23,'Elimin yapıtı olan çocuklarını 2 Aralarında gördüklerinde 2 Adımı kutsal sayacaklar; 2 Evet, Yakupun Kutsalını kutsal sayacak, 2 İsrailin Tanrısından korkacaklar.'),
(2001559,68,23,29,24,'Yoldan sapmış olanlar kavrayışa, 2 Yakınıp duranlar bilgiye kavuşacak.››'),
(2001560,68,23,30,1,'RAB, ‹‹Vay haline bu dikbaşlı soyun!›› diyor, 2 ‹‹Benim değil, kendi tasarılarını yerine getirip 2 Ruhuma aykırı anlaşmalar yaparak 2 Günah üstüne günah işliyorlar.'),
(2001561,68,23,30,2,'Bana danışmadan firavunun koruması altına girmek, 2 Mısırın gölgesine sığınmak için oraya gidiyorlar.'),
(2001562,68,23,30,3,'Ne var ki, firavunun koruması onlar için utanç, 2 Mısırın gölgesine sığınmaları onlar için rezillik olacak.'),
(2001563,68,23,30,4,'Önderleri Soanda olduğu, 2 Elçileri Hanese ulaştığı halde,'),
(2001564,68,23,30,5,'Kendilerine yararı olmayan bir halk yüzünden hepsi utanacak. 2 O halkın onlara ne yardımı ne de yararı olacak, 2 Ancak onları utandırıp rezil edecek.››'),
(2001565,68,23,30,6,'Negevdeki hayvanlara ilişkin bildiri: 2 ‹‹Elçiler erkek ve dişi aslanların, 2 Engereklerin, uçan yılanların yaşadığı 2 Çetin ve sıkıntılı bir bölgeden geçerler. 2 Servetlerini eşeklerin sırtına, 2 Hazinelerini develerin hörgücüne yükleyip 2 Kendilerine hiç yararı olmayan halka taşırlar.'),
(2001566,68,23,30,7,'Mısırın yardımı boş ve yararsızdır, 2 Bu yüzden Mısıra ‹Haylaz Rahavfç› adını verdim. ‹‹Fırtına›› ya da ‹‹Küstah›› anlamına gelir.'),
(2001567,68,23,30,8,'‹‹Şimdi git, söylediğimi onların önünde 2 Bir levhaya yazıp kitaba geçir ki, 2 Gelecekte kalıcı bir tanık olsun.'),
(2001568,68,23,30,9,'Çünkü o asi bir halk, yalancı bir soy, 2 RABbin yasasını duymak istemeyen bir soydur.'),
(2001569,68,23,30,10,'Bilicilere, ‹Artık görüm görmeyin›, 2 Görenlere, ‹Bizim için doğru şeyler görmeyin, 2 Bize güzel şeyler söyleyin, asılsız şeyler açıklayın› diyorlar,'),
(2001570,68,23,30,11,'‹Yoldan çekilin, yolu açın, 2 Bizi İsrailin Kutsalıyla yüzleştirmekten vazgeçin.› ››'),
(2001571,68,23,30,12,'Bu nedenle İsrailin Kutsalı diyor ki, 2 ‹‹Madem bu bildiriyi reddettiniz, 2 Baskıya ve hileye güvenip dayandınız;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001572,68,23,30,13,'Bu suçunuz yüksek bir surda 2 Sırt veren çatlağa benziyor. 2 Böyle bir sur birdenbire yıkılıverir.'),
(2001573,68,23,30,14,'O, toprak çömlek gibi parçalanacak. 2 Parçalanması öyle şiddetli olacak ki, 2 Ocaktan ateş almaya ya da sarnıçtan su çıkarmaya 2 Yetecek büyüklükte bir parça kalmayacak.››'),
(2001574,68,23,30,15,'Egemen RAB, İsrailin Kutsalı şöyle diyor: 2 ‹‹Bana dönün, huzur bulun, kurtulursunuz. 2 Kaygılanmayın, bana güvenin, güçlü olursunuz. 2 Ama bunu yapmak istemiyorsunuz.'),
(2001575,68,23,30,16,'‹Hayır, atlara binip kaçarız› diyorsunuz, 2 Bu yüzden kaçmak zorunda kalacaksınız. 2 ‹Hızlı atlara bineriz› diyorsunuz, 2 Bu yüzden sizi kovalayanlar da hızlı olacak.'),
(2001576,68,23,30,17,'Bir kişinin tehdidiyle bin kişi kaçacak, 2 Beş kişinin tehdidiyle hepiniz kaçacaksınız; 2 Dağ başında bir gönder, 2 Tepede bir sancak gibi kalana dek kaçacaksınız.'),
(2001577,68,23,30,18,'‹‹Yine de RAB size lütfetmeyi özlemle bekliyor, 2 Size merhamet göstermek için harekete geçiyor. 2 Çünkü RAB adil Tanrıdır. 2 Ne mutlu Onu özlemle bekleyenlere!››'),
(2001578,68,23,30,19,'‹‹Ey Yeruşalimde oturan Siyon halkı, 2 Artık ağlamayacaksın! 2 Feryat ettiğinde Rab sana nasıl da lütfedecek! 2 Feryadını duyar duymaz seni yanıtlayacak.'),
(2001579,68,23,30,20,'Rab ekmeği sıkıntıyla, 2 Suyu cefayla verse de, 2 Öğretmeniniz artık gizlenmeyecek, 2 Gözünüzle göreceksiniz onu. ‹‹Öğretmenlerinizi artık dışlamayacaksınız››.'),
(2001580,68,23,30,21,'Sağa ya da sola sapacağınız zaman, 2 Arkanızdan, ‹Yol budur, bu yoldan gidin› 2 Diyen sesini duyacaksınız.'),
(2001581,68,23,30,22,'Gümüş kaplı oyma putlarınızı, 2 Altın kaplama dökme putlarınızı 2 ‹Kirli› ilan edecek, 2 Kirli bir âdet bezi gibi atıp 2 ‹Defol› diyeceksiniz.'),
(2001582,68,23,30,23,'Rab toprağa ektiğiniz tohum için yağmur verecek, 2 Toprağın ürünü olan yiyecek bol ve zengin olacak. 2 O gün sığırlarınız geniş otlaklarda otlanacak.'),
(2001583,68,23,30,24,'Toprağı işleyen öküzlerle eşekler 2 Kürekle, yabayla savrulmuş, 2 Tuzlanmış yem yiyecekler.'),
(2001584,68,23,30,25,'Kalelerin düştüğü o büyük kıyım günü 2 Her yüksek dağda, her yüce tepede 2 Akarsular olacak.'),
(2001585,68,23,30,26,'RAB halkının kırıklarını sardığı, 2 Vuruşuyla açtığı yaraları iyileştirdiği gün, 2 Ay güneş gibi parlayacak, 2 Güneş yedi kat, yedi günün toplam parlaklığı kadar parlak olacak.››'),
(2001586,68,23,30,27,'Bakın, RABbin kendisi uzaktan geliyor, 2 Kızgın öfkeyle kara bulut içinde. 2 Dudakları gazap dolu, 2 Dili her şeyi yiyip bitiren ateş sanki.'),
(2001587,68,23,30,28,'Soluğu adam boynuna dek yükselmiş taşkın ırmak gibi. 2 Ulusları elekten geçirecek, değersizleri ayıracak, 2 Halkların ağzına yoldan saptıran bir gem takacak.'),
(2001588,68,23,30,29,'Ama sizler bayram gecesini kutlar gibi 2 Ezgiler söyleyeceksiniz. 2 RABbin dağına, İsrailin Kayasına 2 Kaval eşliğinde çıktığınız gibi 2 İçten sevineceksiniz.'),
(2001589,68,23,30,30,'RAB heybetli sesini işittirecek; 2 Kızgın öfkeyle, her şeyi yiyip bitiren ateş aleviyle, 2 Sağanak yağmurla, fırtına ve doluyla 2 Bileğinin gücünü gösterecek.'),
(2001590,68,23,30,31,'Asur RABbin sesiyle dehşete düşecek, 2 Onun değneğiyle vurulacak.'),
(2001591,68,23,30,32,'RABbin terbiye değneğiyle onlara indirdiği her darbeye 2 Tef ve lir eşlik edecek. 2 RAB silahlarını savura savura onlarla savaşacak.'),
(2001592,68,23,30,33,'Tofet çoktan hazırlandı, 2 Evet, kral için hazırlandı. 2 Geniş ve yüksektir odun yığını, 2 Ateşi, odunu boldur. 2 RAB kızgın kükürt selini andıran 2 Soluğuyla tutuşturacak onu.'),
(2001593,68,23,31,1,'Vay haline yardım bulmak için Mısıra inenlerin! 2 Atlara, çok sayıdaki savaş arabalarına, 2 Kalabalık atlılara güveniyorlar, 2 Ama İsrailin Kutsalına güvenmiyor, 2 RABbe yönelmiyorlar.'),
(2001594,68,23,31,2,'Oysa bilge olan RABdir. 2 Felaket getirebilir ve sözünü geri almaz. 2 Kötülük yapan soya, 2 Suç işleyenlerin yardımına karşı çıkar.'),
(2001595,68,23,31,3,'Mısırlılar Tanrı değil, insandır, 2 Atları da ruh değil, et ve kemiktir. 2 RABbin eli kalkınca yardım eden tökezler, 2 Yardım gören düşer, hep birlikte yok olurlar.'),
(2001596,68,23,31,4,'Çünkü RAB bana dedi ki, 2 ‹‹Avının başında homurdanan aslan 2 Bir araya çağrılan çobanlar topluluğunun 2 Bağırıp çağırmasından yılmadığı, gürültüsüne aldırmadığı gibi, 2 Her Şeye Egemen RAB de 2 Siyon Dağının doruğuna inip savaşacak.'),
(2001597,68,23,31,5,'Her Şeye Egemen RAB 2 Kanat açmış kuşlar gibi koruyacak Yeruşalimi. 2 Koruyup özgür kılacak, esirgeyip kurtaracak onu.››'),
(2001598,68,23,31,6,'Ey İsrailoğulları, 2 Bunca vefasızlık ettiğiniz RABbe dönün.'),
(2001599,68,23,31,7,'Çünkü hepiniz günahkâr ellerinizle yaptığınız 2 Altın ve gümüş putları o gün reddedip atacaksınız.'),
(2001600,68,23,31,8,'Asur kılıca yenik düşecek, 2 Ama insan kılıcına değil. 2 Halkı kılıçtan geçirilecek, 2 Ama bu insan kılıcı olmayacak. 2 Kimileri kaçıp kurtulacak, 2 Gençleri de angaryaya koşulacak.'),
(2001601,68,23,31,9,'Asur Kralı dehşet içinde kaçacak, 2 Önderleri sancağı görünce dehşete kapılacak. 2 Siyon''da ateşi, 2 Yeruşalim''de ocağı bulunan RAB söylüyor bunları.'),
(2001602,68,23,32,1,'İşte kral doğrulukla krallık yapacak, 2 Önderler adaletle yönetecek.'),
(2001603,68,23,32,2,'Her biri rüzgara karşı bir sığınak, 2 Fırtınaya karşı bir barınak, çölde akarsu, 2 Çorak yerde gölge salan 2 Büyük bir kaya gibi olacak.'),
(2001604,68,23,32,3,'Artık görenlerin gözleri kapanmayacak, 2 Dinleyenler kulak kesilecek.'),
(2001605,68,23,32,4,'Düşüncesizin aklı bilgiye erecek, 2 Kekeme açık seçik, akıcı konuşacak.'),
(2001606,68,23,32,5,'Artık budalaya soylu, 2 Alçağa saygın denmeyecek.'),
(2001607,68,23,32,6,'Çünkü budala saçmalıyor, 2 Aklı fikri hep kötülükte. 2 İşi gücü fesat işlemek, 2 RABbe ilişkin yanlış sözler söylemek, 2 Açları aç bırakmak, 2 Susamışlardan suyu esirgemek.'),
(2001608,68,23,32,7,'Alçağın yöntemleri kötüdür; 2 Yoksul davasında haklı olsa da 2 Onu yalanlarla yok etmek için 2 Kötü düzenler tasarlar.'),
(2001609,68,23,32,8,'Soylu kişiyse soylu şeyler tasarlar, 2 Yaptığı soylu işlerle ayakta kalır.'),
(2001610,68,23,32,9,'Ey tasasızca yaşayan kadınlar, 2 Kalkın, sesimi işitin; 2 Ey kaygısız kızlar, sözüme kulak verin!'),
(2001611,68,23,32,10,'Bir yıl kadar sonra sarsılacaksınız, 2 Ey kaygısız kadınlar. 2 Çünkü bağbozumu olmayacak, 2 Devşirecek meyve bulunmayacak.'),
(2001612,68,23,32,11,'Titreyin, ey tasasızca yaşayan kadınlar, 2 Sarsılın, ey kaygısızlar. 2 Giysilerinizi çıkarın, soyunup belinize çul kuşanın.'),
(2001613,68,23,32,12,'Güzel tarlalar, verimli asmalar, 2 Halkımın diken ve çalı bitmiş toprakları için, 2 Neşeli kentteki mutluluk dolu evler için göğsünüzü dövün.'),
(2001614,68,23,32,14,'Çünkü saray ıssız, 2 Kalabalık kent bomboş kalacak. 2 Ofel Mahallesiyle gözcü kulesi 2 Bir çayırlığa dönecek; 2 Yaban eşeklerinin keyifle gezindiği, 2 Sürülerin otladığı bir yer olacak.'),
(2001615,68,23,32,15,'Ta ki yukarıdan üzerimize ruh dökülene dek; 2 O zaman çöl meyve bahçesine, 2 Meyve bahçesi ormana dönecek.'),
(2001616,68,23,32,16,'O zaman adalet çöle dek yayılacak, 2 Doğruluk meyve bahçesinde yurt bulacak.'),
(2001617,68,23,32,17,'Doğruluğun ürünü esenlik, 2 Sonucu, sürekli huzur ve güven olacaktır.'),
(2001618,68,23,32,18,'Halkım esenlik dolu evlerde, 2 Güvenli ve rahat yerlerde yaşayacak.'),
(2001619,68,23,32,19,'Dolu ormanları harap etse, 2 Kent yerle bir olsa da,'),
(2001620,68,23,32,20,'Sulak yerde tohum eken, 2 Sığırını, eşeğini özgürce çayıra salan sizlere ne mutlu!'),
(2001621,68,23,33,1,'Vay sana, yıkıp yok eden 2 Ama kendisi yıkılmamış olan! 2 Vay sana, ihanete uğramamış hain! 2 Yıkıma son verir vermez sen de yıkılacaksın, 2 İhanetin sona erer ermez sen de ihanete uğrayacaksın.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001622,68,23,33,2,'Ya RAB, lütfet bize, 2 Çünkü sana umut bağladık, 2 Gün be gün gücümüz ol! 2 Sıkıntıya düştüğümüzde bizi kurtar.'),
(2001623,68,23,33,3,'Kükreyişinden halklar kaçışır, 2 Sen ayağa kalkınca uluslar darmadağın olur.'),
(2001624,68,23,33,4,'Çekirgeler tarlayı nasıl yağmalarsa, 2 Ganimetiniz de öyle yağmalanacak, ey uluslar. 2 Malınızın üzerine çekirge sürüsü gibi saldıracaklar.'),
(2001625,68,23,33,5,'Yükseklerde oturan RAB yücedir, 2 Siyonu adalet ve doğrulukla doldurur.'),
(2001626,68,23,33,6,'Yaşadığınız sürenin güvencesi Odur. 2 Bol bol kurtuluş, bilgi ve bilgelik sağlayacak. 2 Halkın hazinesi RAB korkusudur.'),
(2001627,68,23,33,7,'İşte, en yiğitleri sokaklarda feryat ediyor, 2 Barış elçileri acı acı ağlıyor.'),
(2001628,68,23,33,8,'Anayollar bomboş, 2 Yolculuk eden kimse kalmadı. 2 Düşman antlaşmayı bozdu, kentleri hor gördü, 2 İnsanları hiçe saydı.'),
(2001629,68,23,33,9,'Ülke yas tutuyor, zayıflıyor. 2 Lübnan utancından soldu, 2 Şaron Ovası çöle döndü, 2 Başan ve Karmelde ağaçlar yaprak döküyor.'),
(2001630,68,23,33,10,'RAB diyor ki, ‹‹Şimdi harekete geçeceğim, 2 Ne denli yüce ve üstün olduğumu göstereceğim.'),
(2001631,68,23,33,11,'Samana gebe kalıp anız doğuracaksınız, 2 Soluğunuz sizi yiyip bitiren bir ateş olacak.'),
(2001632,68,23,33,12,'Halklar yanıp kül olacak, 2 Kesilip yakılan dikenli çalı gibi olacak.'),
(2001633,68,23,33,13,'‹‹Ey uzaktakiler, ne yaptığımı işitin, 2 Ey yakındakiler, gücümü anlayın.››'),
(2001634,68,23,33,14,'Siyondaki günahkârlar dehşet içinde, 2 Tanrısızları titreme aldı. 2 ‹‹Her şeyi yiyip bitiren ateşin yanında 2 Hangimiz oturabilir? 2 Sonsuza dek sönmeyecek alevin yanında 2 Hangimiz yaşayabilir?›› diye soruyorlar.'),
(2001635,68,23,33,15,'Ama doğru yolda yürüyüp doğru dürüst konuşan, 2 Zorbalıkla edinilen kazancı reddeden, 2 Elini rüşvetten uzak tutan, 2 Kan dökenlerin telkinlerine kulak vermeyen, 2 Kötülük görmeye dayanamayan,'),
(2001636,68,23,33,16,'Yükseklerde oturacak; 2 Uçurumun başındaki kaleler onun korunağı olacak, 2 Ekmeği sağlanacak, hiç susuz kalmayacak.'),
(2001637,68,23,33,17,'Kralı bütün güzelliğiyle görecek, 2 Uçsuz bucaksız ülkeyi seyredeceksin.'),
(2001638,68,23,33,18,'‹‹Haracı tartıp kaydeden nerede, 2 Kulelerden sorumlu olan nerede?›› diyerek 2 Geçmişteki dehşetli günleri düşüneceksin.'),
(2001639,68,23,33,19,'Garip, anlaşılmaz bir yabancı dil konuşan 2 O küstah halkı artık görmeyeceksin.'),
(2001640,68,23,33,20,'Bayramlarımızın kenti olan Siyona bak! 2 Yeruşalimi bir esenlik yurdu, 2 Kazıkları asla yerinden sökülmeyen, 2 Gergi ipleri hiç kopmayan, 2 Sarsılmaz bir çadır olarak görecek gözlerin.'),
(2001641,68,23,33,21,'Heybetli RAB orada bizden yana olacak. 2 Orası geniş ırmakların, çayların yeri olacak. 2 Bunların üzerinden ne kürekli tekneler, 2 Ne de büyük gemiler geçecek.'),
(2001642,68,23,33,22,'Çünkü yargıcımız RABdir; 2 Yasamızı koyan RABdir, 2 Kralımız RABdir, bizi O kurtaracak.'),
(2001643,68,23,33,23,'Senin gemilerinin halatları gevşedi, 2 Direklerinin dibini pekiştirmediler, 2 Yelkenleri açmadılar. 2 O zaman büyük ganimet paylaşılacak, 2 Topallar bile yağmaya katılacak.'),
(2001644,68,23,33,24,'Siyon''da oturan hiç kimse ‹‹Hastayım›› demeyecek, 2 Orada yaşayan halkın suçu bağışlanacak.'),
(2001645,68,23,34,1,'Ey uluslar, işitmek için yaklaşın! 2 Ey halklar, kulak verin! 2 Dünya ve üzerindeki herkes, 2 Yeryüzü ve ondan türeyenlerin hepsi işitsin!'),
(2001646,68,23,34,2,'RAB bütün uluslara öfkelendi, 2 Onların ordularına karşı gazaba geldi. 2 Onları tümüyle mahvolmaya, 2 Boğazlanmaya teslim edecek.'),
(2001647,68,23,34,3,'Ölüleri dışarı atılacak, 2 Pis kokacak cesetleri; 2 Dağlar kanlarıyla sulanacak.'),
(2001648,68,23,34,4,'Bütün gök cisimleri küçülecek, 2 Gökler bir tomar gibi dürülecek; 2 Gök cisimleri, asma yaprağı, 2 İncir yaprağı gibi dökülecek.'),
(2001649,68,23,34,5,'‹‹Kılıcım göklerde kanıncaya kadar içti. 2 Şimdi de Edomun, 2 Tümüyle yıkmaya karar verdiğim halkın 2 Üzerine inecek›› diyor RAB.'),
(2001650,68,23,34,6,'RABbin kılıcı kana, 2 Kuzu ve teke kanına doydu; 2 Yağla, koç böbreklerinin yağıyla kaplandı. 2 Çünkü RABbin Bosrada bir kurbanı, 2 Edomda büyük bir kıyımı var.'),
(2001651,68,23,34,7,'Onlarla birlikte yaban öküzleri, 2 Körpe boğalarla güçlü boğalar da yere serilecek. 2 Toprakları kana doyacak, yağla sulanacak.'),
(2001652,68,23,34,8,'Çünkü RABbin bir öç günü, Siyonun davasını güdeceği bir karşılık yılı olacak.'),
(2001653,68,23,34,9,'Edom dereleri zifte, toprağı kükürde dönecek; ülkenin her yanı yanan zift olacak.'),
(2001654,68,23,34,10,'Zift gece gündüz sönmeyecek, dumanı hep tütecek. Ülke kuşaklar boyu ıssız kalacak, sonsuza dek oradan kimse geçmeyecek.'),
(2001655,68,23,34,11,'Baykuşların mülkü olacak orası, büyük baykuşlarla kargalar yaşayacak orada. RAB, Edomun üzerine kargaşa ipini, boşluk çekülünü gerecek.'),
(2001656,68,23,34,12,'Kral ilan edebilecekleri soylular kalmayacak, bütün önderlerinin sonu gelecek.'),
(2001657,68,23,34,13,'Saraylarında dikenler, kalelerinde ısırganlarla böğürtlenler bitecek. Orası çakalların barınağı, baykuşların yurdu olacak.'),
(2001658,68,23,34,14,'Yabanıl hayvanlarla sırtlanlar orada buluşacak, tekeler karşılıklı böğürecek. Lilitfı oraya yerleşip rahata kavuşacak.'),
(2001659,68,23,34,15,'Baykuşlar orada yuva kurup yumurtlayacak, kuluçkaya yatıp yavrularını kendi gölgelerinde toplayacak. Çaylaklar eşleşip orada toplanacaklar. Lev.17:7).'),
(2001660,68,23,34,16,'RABbin kitabını okuyup araştırın: Bunlardan hiçbiri eksik kalmayacak, eşten yoksun hiçbir hayvan olmayacak. Çünkü bu buyruk RABbin ağzından çıktı, Ruhu da onları toplayacak.'),
(2001661,68,23,34,17,'RAB onlar için kura çekti, ülkeyi ölçüp aralarında pay etti. Orayı sonsuza dek sahiplenip kuşaklar boyu orada yaşayacaklar.'),
(2001662,68,23,35,1,'Çöl ve kurak toprak sevinecek, 2 Bozkır coşup çiğdem gibi çiçeklenecek.'),
(2001663,68,23,35,2,'Her yanı çiçeklenip sevinçle coşacak, 2 Sevincini haykıracak. 2 Lübnanın yüceliği, 2 Karmel ve Şaronun görkemi ona verilecek. 2 İnsanlar RABbin yüceliğini, 2 Tanrımızın görkemini görecek.'),
(2001664,68,23,35,3,'Gevşek elleri güçlendirin, 2 Pekiştirin çözülen dizleri.'),
(2001665,68,23,35,4,'Yüreği kaygılı olanlara, 2 ‹‹Güçlü olun, korkmayın›› deyin, 2 ‹‹İşte Tanrınız geliyor! 2 Öç almaya, karşılık vermeye geliyor. 2 Sizi O kurtaracak.››'),
(2001666,68,23,35,5,'O zaman körlerin gözleri, 2 Sağırların kulakları açılacak;'),
(2001667,68,23,35,6,'Topallar geyik gibi sıçrayacak, 2 Sevinçle haykıracak dilsizlerin dili. 2 Çünkü çölde sular fışkıracak, 2 Irmaklar akacak bozkırda.'),
(2001668,68,23,35,7,'Kızgın kum havuza, 2 Susuz toprak pınara dönüşecek. 2 Çakalların yattığı yerlerde 2 Kamış, saz ve ot bitecek.'),
(2001669,68,23,35,8,'Orada bir yol, bir anayol olacak, 2 ‹‹Kutsal yol›› diye anılacak, 2 Murdar kişiler geçemeyecek oradan. 2 O yol kurtulmuş olanların yoludur. 2 O yolda yürüyenler, bön kişiler de olsa yoldan sapmayacak.'),
(2001670,68,23,35,9,'Aslan olmayacak orada, 2 Yırtıcı hayvan o yola çıkmayacak; 2 Orada bulunmayacaklar. 2 Ancak kurtulmuş olanlar yürüyecek o yolda.'),
(2001671,68,23,35,10,'RAB''bin kurtardıkları dönecek, 2 Sevinçle haykırarak Siyon''a varacaklar. 2 Yüzlerinde sonsuz sevinç olacak. 2 Onların olacak coşku ve sevinç, 2 Üzüntü ve inilti kaçacak.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001672,68,23,36,1,'Hizkiyanın krallığının on dördüncü yılında Asur Kralı Sanherib, Yahudanın surlu kentlerine saldırıp hepsini ele geçirdi.'),
(2001673,68,23,36,2,'Komutanını büyük bir orduyla Lakişten Yeruşalime, Kral Hizkiyaya gönderdi. Komutan Çırpıcı Tarlası yolunda, Yukarı Havuzun su yolunun yanında durdu.'),
(2001674,68,23,36,3,'Saray sorumlusu Hilkiya oğlu Elyakim, Yazman Şevna ve devlet tarihçisi Asaf oğlu Yoah onu karşılamaya çıktı.'),
(2001675,68,23,36,4,'Komutan onlara şöyle dedi: ‹‹Hizkiyaya söyleyin. ‹Büyük kral, Asur Kralı diyor ki: Güvendiğin şey ne, neye güveniyorsun?'),
(2001676,68,23,36,5,'Savaş tasarıların ve gücün boş laftan başka birşey değil diyorum. Kime güveniyorsun da bana karşı ayaklanıyorsun?'),
(2001677,68,23,36,6,'İşte sen şu kırık kamış değneğe, Mısıra güveniyorsun. Bu değnek kendisine yaslanan herkesin eline batar, deler. Firavun da kendisine güvenenler için böyledir.'),
(2001678,68,23,36,7,'Yoksa bana, Tanrımız RABbe güveniyoruz mu diyeceksiniz? Hizkiyanın Yahuda ve Yeruşalim halkına, yalnız bu sunağın önünde tapınacaksınız diyerek tapınma yerlerini, sunaklarını ortadan kaldırdığı Tanrı değil mi bu?›'),
(2001679,68,23,36,8,'‹‹Haydi, efendim Asur Kralıyla bahse giriş. Binicileri sağlayabilirsen sana iki bin at veririm.'),
(2001680,68,23,36,9,'Mısırın savaş arabalarıyla atlıları sağlayacağına güvensen bile, efendimin en küçük rütbeli komutanlarından birini yenemezsin!'),
(2001681,68,23,36,10,'Dahası var: RABbin buyruğu olmadan mı saldırıp ülkeyi yıkmak için yola çıktığımı sanıyorsun? RAB, ‹Git, o ülkeyi yık› dedi.››'),
(2001682,68,23,36,11,'Elyakim, Şevna ve Yoah, ‹‹Lütfen biz kullarınla Aramice konuş›› diye karşılık verdiler, ‹‹Çünkü biz bu dili anlarız. Yahudice konuşma. Surların üzerindeki halk bizi dinliyor.››'),
(2001683,68,23,36,12,'Komutan, ‹‹Efendim bu sözleri yalnız size ve efendinize söyleyeyim diye mi gönderdi beni?›› dedi, ‹‹Surların üzerinde oturan bu halka, sizin gibi dışkısını yemek, idrarını içmek zorunda kalacak olan herkese gönderdi.››'),
(2001684,68,23,36,13,'Sonra ayağa kalkıp Yahudi dilinde bağırdı: ‹‹Büyük kralın, Asur Kralının sözlerini dinleyin!'),
(2001685,68,23,36,14,'Kral diyor ki, ‹Hizkiya sizi aldatmasın, o sizi kurtaramaz.'),
(2001686,68,23,36,15,'RAB bizi mutlaka kurtaracak, bu kent Asur Kralının eline geçmeyecek diyen Hizkiyaya kanmayın, RABbe güvenmeyin.'),
(2001687,68,23,36,16,'Hizkiyayı dinlemeyin.› Çünkü Asur Kralı diyor ki, ‹Teslim olun, bana gelin. Böylece ben gelip sizi kendi ülkeniz gibi bir ülkeye -tahıl ve yeni şarap, ekmek ve üzüm dolu bir ülkeye- götürene kadar herkes kendi asmasından, kendi incir ağacından yiyecek, kendi sarnıcından içecek.'),
(2001688,68,23,36,18,'‹‹ ‹Hizkiya, RAB bizi kurtaracak diyerek sizi aldatmasın. Ulusların ilahları ülkelerini Asur Kralının elinden kurtarabildi mi?'),
(2001689,68,23,36,19,'Hani nerede Hamanın, Arpatın ilahları? Sefarvayimin ilahları nerede? Samiriyeyi elimden kurtarabildiler mi?'),
(2001690,68,23,36,20,'Bütün bu ülkelerin ilahlarından hangisi ülkesini elimden kurtardı ki, RAB Yeruşalimi elimden kurtarabilsin?› ›› halk (bkz. 2Kr.17:24,31; 18:34).'),
(2001691,68,23,36,21,'Herkes sustu, komutana tek sözle bile karşılık veren olmadı. Çünkü Kral Hizkiya, ‹‹Karşılık vermeyin›› diye buyurmuştu.'),
(2001692,68,23,36,22,'Sonra saray sorumlusu Hilkiya oğlu Elyakim, Yazman Şevna ve devlet tarihçisi Asaf oğlu Yoah giysilerini yırttılar ve gidip komutanın söylediklerini Hizkiya''ya bildirdiler.'),
(2001693,68,23,37,1,'Kral Hizkiya olanları duyunca giysilerini yırttı, çul kuşanıp RABbin Tapınağına girdi.'),
(2001694,68,23,37,2,'Saray sorumlusu Elyakimi, Yazman Şevnayı ve ileri gelen kâhinleri Amots oğlu Peygamber Yeşayaya gönderdi. Hepsi çul kuşanmıştı.'),
(2001695,68,23,37,3,'Yeşayaya şöyle dediler: ‹‹Hizkiya diyor ki, ‹Bugün sıkıntı, azar ve utanç günü. Çünkü çocukların doğum vakti geldi, ama doğuracak güç yok.'),
(2001696,68,23,37,4,'Yaşayan Tanrıyı aşağılamak için efendisi Asur Kralının gönderdiği komutanın söylediklerini belki Tanrın RAB duyar da duyduğu sözlerden ötürü onları cezalandırır. Bu nedenle sağ kalanlarımız için dua et.› ››'),
(2001697,68,23,37,5,'Yeşaya, Kral Hizkiyadan gelen görevlilere şöyle dedi: ‹‹Efendinize şunları söyleyin: ‹RAB diyor ki, Asur Kralının adamlarından benimle ilgili duyduğunuz küfürlerden korkma.'),
(2001698,68,23,37,7,'Onun içine öyle bir ruh koyacağım ki, bir haber üzerine kendi ülkesine dönecek. Orada onu kılıçla öldürteceğim.› ››'),
(2001699,68,23,37,8,'Komutan, Asur Kralının Lakişten ayrılıp Livnaya karşı savaştığını duydu. Krala danışmak için oraya gitti.'),
(2001700,68,23,37,9,'Kûş Kralı Tirhakanın kendisiyle savaşmak üzere yola çıktığını haber alan Asur Kralı, Hizkiyaya ulaklar göndererek şöyle dedi:'),
(2001701,68,23,37,10,'‹‹Yahuda Kralı Hizkiyaya deyin ki, ‹Güvendiğin Tanrın, Yeruşalim Asur Kralının eline teslim edilmeyecek diyerek seni aldatmasın.'),
(2001702,68,23,37,11,'Asur krallarının bütün ülkelere neler yaptığını, onları nasıl yerle bir ettiğini duymuşsundur. Sen kurtulacağını mı sanıyorsun?'),
(2001703,68,23,37,12,'Atalarımın yok ettiği ulusları -Gozanlıları, Harranlıları, Reseflileri, Telassarda yaşayan Edenlileri- ilahları kurtarabildi mi?'),
(2001704,68,23,37,13,'Hani nerede Hama ve Arpat kralları? Lair, Sefarvayim, Hena, İvva kralları nerede?› ››'),
(2001705,68,23,37,14,'Hizkiya mektubu ulakların elinden alıp okuduktan sonra RABbin Tapınağına çıktı. RABbin önünde mektubu yere yayarak'),
(2001706,68,23,37,15,'şöyle dua etti:'),
(2001707,68,23,37,16,'‹‹Ey Keruvlar arasında taht kuran İsrailin Tanrısı, Her Şeye Egemen RAB, bütün dünya krallıklarının tek Tanrısı sensin. Yeri, göğü sen yarattın.'),
(2001708,68,23,37,17,'Ya RAB, kulak ver de işit, gözlerini aç da gör, ya RAB; Sanheribin söylediklerini, yaşayan Tanrıyı nasıl aşağıladığını duy.'),
(2001709,68,23,37,18,'Ya RAB, gerçek şu ki, Asur kralları bütün ulusları ve ülkelerini viraneye çevirdiler.'),
(2001710,68,23,37,19,'İlahlarını yakıp yok ettiler. Çünkü onlar tanrı değil, insan eliyle biçimlendirilmiş tahta ve taşlardı.'),
(2001711,68,23,37,20,'Ya RAB Tanrımız, şimdi bizi Sanheribin elinden kurtar ki, bütün dünya krallıkları senin tek RAB olduğunu anlasın.››'),
(2001712,68,23,37,21,'Bunun üzerine Amots oğlu Yeşaya, Hizkiyaya şu haberi gönderdi: ‹‹İsrailin Tanrısı RAB şöyle diyor: ‹Asur Kralı Sanherible ilgili olarak bana yalvardığın için diyorum ki, ‹‹ ‹Erden kız Siyon seni hor görüyor, 2 Alay ediyor seninle. 2 Yeruşalim kızı ardından alayla baş sallıyor.'),
(2001713,68,23,37,23,'Sen kimi aşağıladın, kime küfrettin? 2 Kime sesini yükselttin? 2 İsrailin Kutsalına tepeden baktın!'),
(2001714,68,23,37,24,'Uşakların aracılığıyla Rabbi aşağıladın. 2 Bir sürü savaş arabamla dağların tepesine, 2 Lübnanın doruklarına çıktım, dedin. 2 Yüksek sedir ağaçlarını, seçme çamlarını kestim, 2 Lübnanın en uzak tepelerine, 2 Gür ormanlarına ulaştım.'),
(2001715,68,23,37,25,'Kuyular kazdım, sular içtim, 2 Mısırın bütün ırmaklarını ayağımın tabanıyla kuruttum, dedin.'),
(2001716,68,23,37,26,'‹‹ ‹Bütün bunları çoktan yaptığımı, 2 Çok önceden tasarladığımı duymadın mı? 2 Surlu kentleri enkaz yığınlarına çevirmeni 2 Şimdi ben gerçekleştirdim.'),
(2001717,68,23,37,27,'O kentlerde yaşayanların kolu kanadı kırıldı. 2 Yılgınlık ve utanç içindeydiler; 2 Kır otuna, körpe filizlere, 2 Damlarda büyümeden kavrulup giden ota döndüler.'),
(2001718,68,23,37,28,'Senin oturuşunu, kalkışını, 2 Ne zaman gidip geldiğini, 2 Bana nasıl öfkelendiğini biliyorum.'),
(2001719,68,23,37,29,'Bana duyduğun öfkeden, 2 Kulağıma erişen küstahlığından ötürü 2 Halkamı burnuna, gemimi ağzına takacak, 2 Seni geldiğin yoldan geri çevireceğim.'),
(2001720,68,23,37,30,'‹‹ ‹Senin için belirti şu olacak, ey Hizkiya: 2 Bu yıl kendiliğinden yetişeni yiyeceksiniz, 2 İkinci yıl ise ardından biteni. 2 Üçüncü yıl ekip biçin, 2 Bağlar dikip ürününü yiyin.'),
(2001721,68,23,37,31,'Yahudalıların kurtulup sağ kalanları 2 Yine aşağıya doğru kök salacak, 2 Yukarıya doğru meyve verecek.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001722,68,23,37,32,'Çünkü sağ kalanlar Yeruşalimden, 2 Kurtulanlar Siyon Dağından çıkacak. 2 Her Şeye Egemen RABbin gayretiyle olacak bu.›'),
(2001723,68,23,37,33,'‹‹Bundan dolayı RAB Asur Kralına ilişkin şöyle diyor: 2 ‹Bu kente girmeyecek, ok atmayacak. 2 Kente kalkanla yaklaşmayacak, 2 Karşısında rampa kurmayacak.'),
(2001724,68,23,37,34,'Geldiği yoldan dönecek ve kente girmeyecek› diyor RAB,'),
(2001725,68,23,37,35,'‹Kendim için ve kulum Davutun hatırı için 2 Bu kenti savunup kurtaracağım› diyor.››'),
(2001726,68,23,37,36,'RABbin meleği gidip Asur ordugahında yüz seksen beş bin kişiyi öldürdü. Ertesi sabah uyananlar salt cesetlerle karşılaştılar.'),
(2001727,68,23,37,37,'Bunun üzerine Asur Kralı Sanherib ordugahını bırakıp çekildi. Ninovaya döndü ve orada kaldı.'),
(2001728,68,23,37,38,'Bir gün ilahı Nisrok''un tapınağında tapınırken, oğullarından Adrammelek''le Şareser, onu kılıçla öldürüp Ararat ülkesine kaçtılar. Yerine oğlu Esarhaddon kral oldu.'),
(2001729,68,23,38,1,'O günlerde Hizkiya ölümcül bir hastalığa yakalandı. Amots oğlu Peygamber Yeşaya ona gidip şöyle dedi: ‹‹RAB diyor ki, ‹Ev işlerini düzene sok. Çünkü iyileşmeyecek, öleceksin.› ››'),
(2001730,68,23,38,2,'Hizkiya yüzünü duvara dönüp RABbe yalvardı:'),
(2001731,68,23,38,3,'‹‹Ya RAB, yürekten bir sadakatle önünde nasıl yaşadığımı, gözünde iyi olanı yaptığımı anımsa lütfen.›› Sonra acı acı ağlamaya başladı.'),
(2001732,68,23,38,4,'Bunun üzerine RAB Yeşayaya seslendi:'),
(2001733,68,23,38,5,'‹‹Git, Hizkiyaya şunu söyle: ‹Atan Davutun Tanrısı RAB diyor ki: Duanı işittim, gözyaşlarını gördüm. Bak, ömrünü on beş yıl daha uzatacağım.'),
(2001734,68,23,38,6,'Bu kenti savunacak, seni de kenti de Asur Kralının elinden kurtaracağım.'),
(2001735,68,23,38,7,'Sözümü gerçekleştireceğime ilişkin sana vereceğim belirti şu olacak:'),
(2001736,68,23,38,8,'RAB, batmakta olan güneşin Ahazın inşa ettiği basamakların üzerine düşen gölgesini on basamak kısaltacak.› ›› Böylece batmakta olan güneşin gölgesi on basamak kısaldı.'),
(2001737,68,23,38,9,'Yahuda Kralı Hizkiya hastalanıp iyileştikten sonra şunları yazdı:'),
(2001738,68,23,38,10,'‹‹Hayatımın baharında ölüler diyarının kapılarından geçip 2 Ömrümün geri kalan yıllarından yoksun mu kalmalıyım?›› demiştim,'),
(2001739,68,23,38,11,'‹‹Yaşayanlar diyarında RABbi, evet, RABbi bir daha görmeyeceğim, 2 Bu dünyada yaşayanlar gibi insan yüzü görmeyeceğim bir daha.'),
(2001740,68,23,38,12,'Evim bir çoban çadırı gibi bozuldu, alındı elimden. 2 Dokumacı gibi dürdüm yaşamımı, RAB tezgahtan beni kesti, 2 Bir gün içinde sonumu getiriverdi.'),
(2001741,68,23,38,13,'Sabırla bekledim sabaha kadar, 2 RAB bir aslan gibi kırdı bütün kemiklerimi, 2 Bir gün içinde sonumu getiriverdi.'),
(2001742,68,23,38,14,'Kırlangıç gibi, turna gibi acı acı öttüm, 2 Güvercin gibi inledim, gözlerim yoruldu yukarı bakmaktan. 2 Ya Rab, eziyet çekiyorum, 2 Yardım et bana.'),
(2001743,68,23,38,15,'‹‹Ne diyeyim? Bana seslenen de bunu yapan da Rabdir. 2 Tattığım bu acılardan sonra daha dikkatli yaşayacağım.'),
(2001744,68,23,38,16,'Ya Rab, insanlar bunlarla yaşarlar. 2 Canım da bunların sayesinde yaşıyor. 2 İyileştirdin, yaşattın beni!'),
(2001745,68,23,38,17,'Çektiğim bunca acı esenlik bulmam içindi. 2 Beni sevdiğin için yıkım çukuruna düşmekten alıkoydun, 2 Günahlarımı arkana attın.'),
(2001746,68,23,38,18,'Çünkü ölüler diyarı sana şükredemez, 2 Ölüm övgüler sunmaz sana. 2 Ölüm çukuruna inenler senin sadakatine umut bağlayamaz.'),
(2001747,68,23,38,19,'Diriler, yalnız diriler 2 Bugün benim yaptığım gibi sana şükreder; 2 Babalar senin sadakatini çocuklarına anlatır.'),
(2001748,68,23,38,20,'Beni kurtaracak olan RABdir. 2 Ömrümüz boyunca Onun tapınağında 2 Telli çalgılarımızı çalacağız.››'),
(2001749,68,23,38,21,'Yeşaya, ‹‹İncir pestili getirin, Hizkiyanın çıbanına koyun, iyileşir›› demişti.'),
(2001750,68,23,38,22,'Hizkiya da, ‹‹RAB''bin Tapınağı''na çıkacağıma ilişkin belirti nedir?›› diye sormuştu.'),
(2001751,68,23,39,1,'O sırada Hizkiyanın hastalanıp iyileştiğini duyan Baladan oğlu Babil Kralı Merodak-Baladan, ona mektuplarla birlikte bir armağan gönderdi.'),
(2001752,68,23,39,2,'Bunlar Hizkiyayı sevindirdi. O da deposundaki bütün değerli eşyaları -altını, gümüşü, baharatı, değerli yağı, silah deposunu ve hazine odalarındaki her şeyi- elçilere gösterdi. Sarayında da krallığında da onlara göstermediği hiçbir şey kalmadı.'),
(2001753,68,23,39,3,'Peygamber Yeşaya Kral Hizkiyaya gidip, ‹‹Bu adamlar sana ne dediler, nereden gelmişler?›› diye sordu. Hizkiya, ‹‹Uzak bir ülkeden, Babilden gelmişler›› diye karşılık verdi.'),
(2001754,68,23,39,4,'Yeşaya, ‹‹Sarayında ne gördüler?›› diye sordu. Hizkiya, ‹‹Sarayımdaki her şeyi gördüler, hazinelerimde onlara göstermediğim hiçbir şey kalmadı›› diye yanıtladı.'),
(2001755,68,23,39,5,'Bunun üzerine Yeşaya şöyle dedi: ‹‹Her Şeye Egemen RABbin sözüne kulak ver.'),
(2001756,68,23,39,6,'RAB diyor ki, ‹Gün gelecek, sarayındaki her şey, atalarının bugüne kadar bütün biriktirdikleri Babile taşınacak. Hiçbir şey kalmayacak.'),
(2001757,68,23,39,7,'Soyundan gelen bazı çocuklar alınıp götürülecek, Babil Kralının sarayında hadım edilecek.› ››'),
(2001758,68,23,39,8,'Hizkiya, ‹‹RAB''den ilettiğin bu söz iyi›› dedi. Çünkü, ‹‹Nasıl olsa yaşadığım sürece barış ve güvenlik olacak›› diye düşünüyordu.'),
(2001759,68,23,40,1,'‹‹Avutun halkımı›› diyor Tanrınız, 2 ‹‹Avutun!'),
(2001760,68,23,40,2,'Yeruşalim halkına dokunaklı sözler söyleyin. 2 Angaryanın bittiğini, 2 Suçlarının cezasını ödediklerini, 2 Günahlarının cezasını RABbin elinden 2 İki katıyla aldıklarını ilan edin.››'),
(2001761,68,23,40,3,'Şöyle haykırıyor bir ses: 2 ‹‹Çölde RABbin yolunu hazırlayın, 2 Bozkırda Tanrımız için düz bir yol açın. hazırlayın, bozkırda Tanrımız için düz bir yol açın› ›› ya da ‹‹Çölde haykıran, ‹RABbin yolunu hazırlayın, geçeceği patikaları düzleyin› diye sesleniyor››.'),
(2001762,68,23,40,4,'Her vadi yükseltilecek, 2 Her dağ, her tepe alçaltılacak. 2 Böylelikle engebeler düzleştirilecek, 2 Sarp yerler ovaya dönüştürülecek.'),
(2001763,68,23,40,5,'O zaman RABbin yüceliği görünecek, 2 Bütün insanlar hep birlikte onu görecek. 2 Bunu söyleyen RABdir.››'),
(2001764,68,23,40,6,'Ses, ‹‹Duyur›› diyor. 2 ‹‹Neyi duyurayım?›› diye soruyorum. 2 ‹‹İnsan soyu ota benzer, 2 Bütün vefası kır çiçeği gibidir. metin ‹‹Sordu››.'),
(2001765,68,23,40,7,'RABbin soluğu esince üzerlerine, 2 Ot kurur, çiçek solar. 2 Gerçekten de halk ottan farksızdır.'),
(2001766,68,23,40,8,'Ot kurur, çiçek solar, 2 Ama Tanrımızın sözü sonsuza dek durur.››'),
(2001767,68,23,40,9,'Ey Siyona müjde getiren, 2 Yüksek dağa çık! 2 Ey Yeruşalime müjde getiren, 2 Yükselt sesini, bağır, 2 Sesini yükselt, korkma. 2 Yahuda kentlerine, ‹‹İşte, Tanrınız!›› de. Ey Yeruşalime müjde getiren›› ya da ‹‹Ey müjde getiren Siyon halkı, yüksek dağa çık! Ey müjde getiren Yeruşalim halkı››.'),
(2001768,68,23,40,10,'İşte Egemen RAB gücüyle geliyor, 2 Kudretiyle egemenlik sürecek. 2 Ücreti kendisiyle birlikte, 2 Ödülü önündedir.'),
(2001769,68,23,40,11,'Sürüsünü çoban gibi güdecek, 2 Kollarına alacak kuzuları, 2 Bağrında taşıyacak; 2 Usul usul yol gösterecek emziklilere.'),
(2001770,68,23,40,12,'Kim denizleri avucuyla, 2 Gökleri karışıyla ölçebildi? 2 Yerin toprağını ölçeğe sığdıran, 2 Dağları kantarla, 2 Tepeleri teraziyle tartabilen var mı?'),
(2001771,68,23,40,13,'RABbin düşüncesine kim akıl erdirebildi? 2 Ona öğüt verip öğretebilen var mı?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001772,68,23,40,14,'Akıl almak, adalet yolunu öğrenmek için 2 RAB kime danıştı ki? 2 Ona bilgi veren, anlayış yolunu bildiren var mı?'),
(2001773,68,23,40,15,'RAB için uluslar kovada bir damla su, 2 Terazideki toz zerreciği gibidir. 2 Adaları ince toz gibi tartar.'),
(2001774,68,23,40,16,'Adakları yakmaya yetmez Lübnan ormanı, 2 Yakmalık sunu için az gelir hayvanları.'),
(2001775,68,23,40,17,'RABbin önünde bütün uluslar bir hiç gibidir, 2 Hiçten bile aşağı, değersiz sayılır.'),
(2001776,68,23,40,18,'Öyleyse Tanrıyı kime benzeteceksiniz? 2 Neyle karşılaştıracaksınız Onu?'),
(2001777,68,23,40,19,'Putu döküm işçisi yapar, 2 Kuyumcu altınla kaplar, 2 Gümüş zincirler döker.'),
(2001778,68,23,40,20,'Böyle bir sunuya gücü yetmeyen yoksul kişi 2 Çürümez bir ağaç parçası seçer. 2 Yerinden kımıldamaz bir put yapsın diye 2 Usta bir işçi arar.'),
(2001779,68,23,40,21,'Bilmiyor musunuz, duymadınız mı? 2 Başlangıçtan beri size bildirilmedi mi? 2 Dünyanın temelleri atılalı beri anlamadınız mı?'),
(2001780,68,23,40,22,'Gökkubbenin üstünde oturan RABdir, 2 Yeryüzünde yaşayanlarsa çekirge gibidir. 2 Gökleri perde gibi geren, 2 Oturmak için çadır gibi kuran Odur.'),
(2001781,68,23,40,23,'Odur önderleri bir hiç eden, 2 Dünyanın egemenlerini sıfıra indirgeyen.'),
(2001782,68,23,40,24,'O önderler ki, yeni dikilmiş, yeni ekilmiş ağaç gibi, 2 Gövdeleri yere yeni kök salmışken 2 RABbin soluğu onları kurutuverir, 2 Kasırga saman gibi savurur.'),
(2001783,68,23,40,25,'‹‹Beni kime benzeteceksiniz ki, 2 Eşitim olsun?›› diyor Kutsal Olan.'),
(2001784,68,23,40,26,'Başınızı kaldırıp göklere bakın. 2 Kim yarattı bütün bunları? 2 Yıldızları sırayla görünür kılıyor, 2 Her birini adıyla çağırıyor. 2 Büyük kudreti, üstün gücü sayesinde hepsi yerli yerinde duruyor.'),
(2001785,68,23,40,27,'Ey Yakup soyu, ey İsrail! 2 Neden, ‹‹RAB başıma gelenleri görmüyor, 2 Tanrı hakkımı gözetmiyor?›› diye yakınıyorsun?'),
(2001786,68,23,40,28,'Bilmiyor musun, duymadın mı? 2 Ebedi Tanrı, RAB, bütün dünyayı yaratan, 2 Ne yorulur ne de zayıflar, 2 Onun bilgisi kavranamaz.'),
(2001787,68,23,40,29,'Yorulanı güçlendirir, 2 Takati olmayanın kudretini artırır.'),
(2001788,68,23,40,30,'Gençler bile yorulup zayıf düşer, 2 Yiğitler tökezleyip düşerler.'),
(2001789,68,23,40,31,'RAB''be umut bağlayanlarsa taze güce kavuşur, 2 Kanat açıp yükselirler kartallar gibi. 2 Koşar ama zayıf düşmez, 2 Yürür ama yorulmazlar.'),
(2001790,68,23,41,1,'RAB diyor ki, ‹‹Susun karşımda, ey kıyı halkları! 2 Halklar güçlerini tazelesin, 2 Öne çıkıp konuşsunlar. 2 Yargı için bir araya gelelim.'),
(2001791,68,23,41,2,'‹‹Doğudan adaleti harekete geçiren, 2 Hizmete koşan kim? 2 Ulusları önüne katıyor, krallara baş eğdiriyor. 2 Kılıcıyla toz ediyor onları, 2 Yayıyla savrulan samana çeviriyor. simgeliyor (bkz. 45:1).'),
(2001792,68,23,41,3,'Kovalıyor onları, 2 Ayak basmadığı bir yoldan esenlikle geçiyor.'),
(2001793,68,23,41,4,'Bunları yapıp gerçekleştiren, 2 Kuşakları başlangıçtan beri çağıran kim? 2 Ben RAB, ilkim; sonuncularla da yine Ben olacağım.››'),
(2001794,68,23,41,5,'Kıyı halkları bunu görüp korktu. 2 Dünyanın dört bucağı titriyor. 2 Yaklaşıyor, geliyorlar.'),
(2001795,68,23,41,6,'Herkes komşusuna yardım ediyor, 2 Kardeşine, ‹‹Güçlü ol›› diyor.'),
(2001796,68,23,41,7,'Zanaatçı kuyumcuyu yüreklendiriyor, 2 Madeni çekiçle düzleyen, 2 ‹‹Lehim iyi oldu›› diyerek örse vuranı yüreklendiriyor. 2 Kımıldamasın diye putu yerine çiviliyor.'),
(2001797,68,23,41,8,'‹‹Ama sen, ey kulum İsrail, 2 Seçtiğim Yakup soyu, 2 Dostum İbrahimin torunları!'),
(2001798,68,23,41,9,'Sizleri dünyanın dört bucağından topladım, 2 En uzak yerlerden çağırdım. 2 Dedim ki, ‹Sen kulumsun, seni seçtim, 2 Seni reddetmedim.›'),
(2001799,68,23,41,10,'Korkma, çünkü ben seninleyim, 2 Yılma, çünkü Tanrın benim. 2 Seni güçlendireceğim, evet, sana yardım edeceğim; 2 Zafer kazanan sağ elimle sana destek olacağım.'),
(2001800,68,23,41,11,'‹‹Sana öfkelenenlerin hepsi utanacak, rezil olacak. 2 Sana karşı çıkanlar hiçe sayılıp yok olacak.'),
(2001801,68,23,41,12,'Seninle çekişenleri arasan da bulamayacaksın. 2 Seninle savaşanlar hiçten beter olacak.'),
(2001802,68,23,41,13,'Çünkü sağ elinden tutan, 2 ‹Korkma, sana yardım edeceğim› diyen Tanrın RAB benim.'),
(2001803,68,23,41,14,'‹‹Ey Yakup soyu, toprak kurdu, 2 Ey İsrail halkı, korkma! 2 Sana yardım edeceğim›› diyor RAB, 2 Seni kurtaran İsrailin Kutsalı.'),
(2001804,68,23,41,15,'‹‹İşte, seni dişli, keskin, yepyeni bir harman döveni yaptım. 2 Harman edip ufalayacaksın dağları, 2 Tepeleri samana çevireceksin.'),
(2001805,68,23,41,16,'Onları savurduğunda rüzgar alıp götürecek, 2 Darmadağın edecek hepsini kasırga. 2 Sense RABde sevinç bulacak, 2 İsrailin Kutsalıyla övüneceksin.'),
(2001806,68,23,41,17,'‹‹Düşkünlerle yoksullar su arıyor, ama yok. 2 Dilleri kurumuş susuzluktan. 2 Ben RAB, onları yanıtlayacağım, 2 Ben, İsrailin Tanrısı, onları bırakmayacağım.'),
(2001807,68,23,41,18,'Çıplak tepeler üzerinde ırmaklar, 2 Vadilerde su kaynakları yapacağım. 2 Çölü havuza, 2 Kurak toprağı pınara çevireceğim.'),
(2001808,68,23,41,19,'Çölü sedir, akasya, 2 Mersin ve iğde ağaçlarına kavuşturacağım. 2 Bozkıra çam, köknar 2 Ve selviyi bir arada dikeceğim.'),
(2001809,68,23,41,20,'Öyle ki, insanlar görüp bilsinler, 2 Hep birlikte düşünüp anlasınlar ki, 2 Bütün bunları RABbin eli yapmış, 2 İsrailin Kutsalı yaratmıştır.››'),
(2001810,68,23,41,21,'‹‹Davanızı sunun›› diyor RAB, 2 ‹‹Kanıtlarınızı ortaya koyun›› diyor Yakupun Kralı,'),
(2001811,68,23,41,22,'‹‹Putlarınızı getirin de olacakları bildirsinler bize. 2 Olup bitenleri bildirsinler ki düşünelim, 2 Sonuçlarını bilelim. 2 Ya da gelecekte olacakları duyursunlar bize.'),
(2001812,68,23,41,23,'Ey putlar, bundan sonra olacakları bize bildirin de, 2 İlah olduğunuzu bilelim! 2 Haydi bir iyilik ya da kötülük edin de, 2 Hepimiz korkup dehşete düşelim.'),
(2001813,68,23,41,24,'Siz de yaptıklarınız da hiçten betersiniz, 2 Sizi yeğleyen iğrençtir.'),
(2001814,68,23,41,25,'‹‹Kuzeyden birini harekete geçirdim, geliyor, 2 Gün doğusundan beni adımla çağıran biri. 2 Çömlekçinin balçığı çiğnediği gibi, 2 Önderleri çamur gibi çiğneyecek ayağıyla.'),
(2001815,68,23,41,26,'Hanginiz bunu başlangıçtan bildirdi ki, bilelim, 2 Kim önceden bildirdi ki, ‹Haklısın› diyelim? 2 Konuştuğunuzu bildiren de 2 Duyuran da 2 Duyan da olmadı hiç.'),
(2001816,68,23,41,27,'Siyona ilk, ‹İşte, geldiler› diyen benim. 2 Yeruşalime müjdeci gönderdim.'),
(2001817,68,23,41,28,'Bakıyorum, aralarında öğüt verebilecek kimse yok ki, 2 Onlara danışayım, onlar da yanıtlasınlar.'),
(2001818,68,23,41,29,'Hepsi bomboş, yaptıkları da bir hiç. 2 Halkın putları yalnızca yeldir, sıfırdır.››'),
(2001819,68,23,42,1,'‹‹İşte kendisine destek olduğum, 2 Gönlümün hoşnut olduğu seçtiğim kulum! 2 Ruhumu onun üzerine koydum. 2 Adaleti uluslara ulaştıracak.'),
(2001820,68,23,42,2,'Bağırıp çağırmayacak, 2 Sokakta sesini yükseltmeyecek.'),
(2001821,68,23,42,3,'Ezilmiş kamışı kırmayacak, 2 Tüten fitili söndürmeyecek. 2 Adaleti sadakatle ulaştıracak.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001822,68,23,42,4,'Yeryüzünde adaleti sağlayana dek 2 Umudunu, cesaretini yitirmeyecek. 2 Kıyı halkları onun yasasına umut bağlayacak.››'),
(2001823,68,23,42,5,'Gökleri yaratıp geren, 2 Yeryüzünü ve ürününü seren, 2 Dünyadaki insanlara soluk, 2 Orada yaşayanlara ruh veren RAB Tanrı diyor ki,'),
(2001824,68,23,42,6,'‹‹Ben, RAB, seni doğrulukla çağırdım, 2 Elinden tutacak, 2 Seni koruyacağım. 2 Seni halka antlaşma, 2 Uluslara ışık yapacağım.'),
(2001825,68,23,42,7,'Öyle ki, kör gözleri açasın, 2 Zindandaki tutsakları, 2 Cezaevi karanlığında yaşayanları özgür kılasın.'),
(2001826,68,23,42,8,'‹‹Ben RABbim, adım budur. 2 Onurumu bir başkasına, 2 Övgülerimi putlara bırakmam.'),
(2001827,68,23,42,9,'Bakın, önceden bildirdiklerim gerçekleşti. 2 Şimdi de yenilerini bildiriyorum; 2 Bunlar ortaya çıkmadan önce size duyuruyorum.››'),
(2001828,68,23,42,10,'Ey denizlere açılanlar ve denizlerdeki her şey, 2 Kıyılar ve kıyı halkları, 2 RABbe yeni bir ilahi söyleyin, 2 Dünyanın dört bucağından Onu ezgilerle övün.'),
(2001829,68,23,42,11,'Bozkır ve bozkırdaki kentler, 2 Kedar köylerinde yaşayan halk 2 Sesini yükseltsin. 2 Selada oturanlar sevinçle haykırsın, 2 Bağırsın dağların doruklarından.'),
(2001830,68,23,42,12,'Hepsi RABbi onurlandırsın, 2 Kıyı halkları Onu övsün.'),
(2001831,68,23,42,13,'Yiğit gibi çıkagelecek RAB, 2 Savaşçı gibi gayrete gelecek. 2 Bağırıp savaş çığlığı atacak, 2 Düşmanlarına üstünlüğünü gösterecek.'),
(2001832,68,23,42,14,'‹‹Uzun zamandır ses çıkarmadım, 2 Sustum, kendimi tuttum. 2 Ama şimdi feryat edeceğim doğuran kadın gibi, 2 Nefesim tutulacak, kesik kesik soluyacağım.'),
(2001833,68,23,42,15,'Harap edeceğim dağları, tepeleri, 2 Bütün yeşilliklerini kurutacağım. 2 Irmakları adalara çevirip havuzları kurutacağım.'),
(2001834,68,23,42,16,'Körlere bilmedikleri yolda rehberlik edeceğim, 2 Onlara kılavuz olacağım bilmedikleri yollarda, 2 Karanlığı önlerinde ışığa, 2 Engebeleri düzlüğe çevireceğim. 2 Yerine getireceğim sözler bunlardır. 2 Onlardan geri dönmem.'),
(2001835,68,23,42,17,'Oyma putlara güvenenler, 2 Dökme putlara, ‹İlahlarımız sizsiniz› diyenlerse 2 Geri döndürülüp büsbütün utandırılacaklar.››'),
(2001836,68,23,42,18,'‹‹Ey sağırlar, işitin, 2 Ey körler, bakın da görün!'),
(2001837,68,23,42,19,'Kulum kadar kör olan var mı? 2 Gönderdiğim ulak kadar sağır olan var mı? 2 Benimle barışık olan kadar, 2 RABbin kulu kadar kör olan kim var?'),
(2001838,68,23,42,20,'Pek çok şey gördünüz, ama aldırmıyorsunuz, 2 Kulaklarınız açık, ama işitmiyorsunuz.››'),
(2001839,68,23,42,21,'Kendi doğruluğu uğruna Kutsal Yasayı 2 Büyük ve yüce kılmak RABbi hoşnut etti.'),
(2001840,68,23,42,22,'Ama bu yağmalanmış, soyulmuş bir halktır. 2 Hepsi deliklere, cezaevlerine kapatılmışlardır. 2 Yağmalanmak için varlar, kurtaran yok. 2 Soyulmak içinler, ‹‹Geri verin›› diyen yok.'),
(2001841,68,23,42,23,'Hanginiz kulak verecek? 2 Gelecekte kim can kulağıyla dinleyecek?'),
(2001842,68,23,42,24,'Yakup soyunun soyulmasına, 2 İsrailin yağmalanmasına kim olur verdi? 2 Kendisine karşı günah işlediğimiz RAB değil mi? 2 Çünkü Onun yolunda yürümek istemediler, 2 Yasasına kulak asmadılar.'),
(2001843,68,23,42,25,'Bu yüzden kızgın öfkesini, 2 Savaşın şiddetini üzerlerine yağdırdı. 2 Ama ateş çemberi içinde olduklarını farketmediler, 2 Aldırmadılar kendilerini yakıp bitiren ateşe.'),
(2001844,68,23,43,1,'Ey Yakup soyu, seni yaratan, 2 Ey İsrail, sana biçim veren RAB şimdi şöyle diyor: 2 ‹‹Korkma, çünkü seni kurtardım, 2 Seni adınla çağırdım, sen benimsin.'),
(2001845,68,23,43,2,'Suların içinden geçerken seninle olacağım, 2 Irmakların içinden geçerken su boyunu aşmayacak. 2 Ateşin içinde yürürken yanmayacaksın, 2 Alevler seni yakmayacak.'),
(2001846,68,23,43,3,'Çünkü senin Tanrın, İsrailin Kutsalı, 2 Seni kurtaran RAB benim. 2 Fidyen olarak Mısırı, 2 Sana karşılık Kûş ve Seva diyarlarını verdim.'),
(2001847,68,23,43,4,'Gözümde değerli ve saygın olduğun, 2 Seni sevdiğim için, senin yerine insanlar, 2 Canın karşılığında halklar vereceğim.'),
(2001848,68,23,43,5,'Korkma, çünkü seninleyim, 2 Soyundan olanları doğudan getireceğim, 2 Sizleri de batıdan toplayacağım.'),
(2001849,68,23,43,6,'‹‹Kuzeye, ‹Ver›, güneye, ‹Alıkoyma; 2 Oğullarımı uzaktan, 2 Kızlarımı dünyanın dört bucağından getir› diyeceğim.'),
(2001850,68,23,43,7,'‹Yüceliğim için yaratıp biçim verdiğim, 2 Adımla çağrılan herkesi, 2 Evet, oluşturduğum herkesi getirin› diyeceğim.››'),
(2001851,68,23,43,8,'Gözleri olduğu halde kör, 2 Kulakları olduğu halde sağır olan halkı öne getir.'),
(2001852,68,23,43,9,'Bütün uluslar bir araya gelsin, halklar toplansın. 2 İçlerinden hangisi bunları bildirebilir, 2 Olup bitenleri bize duyurabilir? 2 Tanıklarını çağırıp haklı olduklarını kanıtlasınlar, 2 Ötekiler de duyup, ‹‹Doğrudur›› desinler.'),
(2001853,68,23,43,10,'‹‹Tanıklarım sizlersiniz›› diyor RAB, 2 ‹‹Seçtiğim kullar sizsiniz. 2 Öyle ki beni tanıyıp bana güvenesiniz, 2 Benim O olduğumu anlayasınız. 2 Benden önce bir tanrı olmadı, 2 Benden sonra da olmayacak.'),
(2001854,68,23,43,11,'‹‹Ben, yalnız ben RABbim, 2 Benden başka kurtarıcı yoktur.'),
(2001855,68,23,43,12,'Ben bildirdim, ben kurtardım, ben duyurdum, 2 Aranızdaki yabancı ilahlar değil. 2 Tanıklarım sizsiniz›› diyor RAB, 2 ‹‹Tanrı benim,'),
(2001856,68,23,43,13,'Gün gün olalı ben Oyum. 2 Elimden kimse kurtaramaz. 2 Ben yaparım, kim engel olabilir?››'),
(2001857,68,23,43,14,'Kurtarıcınız RAB, İsrailin Kutsalı diyor ki, 2 ‹‹Uğrunuza Babil üzerine bir ordu göndereceğim. 2 Övündükleri gemilerle kaçan bütün Kildanilere 2 Boyun eğdireceğim.'),
(2001858,68,23,43,15,'Kutsalınız, İsrailin Yaratıcısı, 2 Kralınız RAB benim.››'),
(2001859,68,23,43,16,'Denizde geçit, azgın sularda yol açan, 2 Atlarla savaş arabalarını, 2 Yiğit savaşçıları ve orduyu 2 Yola çıkaran RAB şöyle diyor: 2 ‹‹Onlar yattı, kalkamaz oldu, 2 Fitil gibi bastırılıp söndürüldüler.'),
(2001860,68,23,43,18,'‹‹Olup bitenlerin üzerinde durmayın, 2 Düşünmeyin eski olayları.'),
(2001861,68,23,43,19,'Bakın, yeni bir şey yapıyorum! 2 Olmaya başladı bile, farketmiyor musunuz? 2 Çölde yol, kurak topraklarda ırmaklar yapacağım.'),
(2001862,68,23,43,20,'Kır hayvanları, çakallarla baykuşlar beni yüceltecek. 2 Çünkü seçtiğim halkın içmesi için çölde su, 2 Kurak yerlerde ırmaklar sağladım.'),
(2001863,68,23,43,21,'Kendim için biçim verdiğim bu halk 2 Bana ait olan övgüleri ilan edecek.››'),
(2001864,68,23,43,22,'‹‹Ne var ki, ey Yakup soyu, 2 Yakardığın ben değildim, 2 Benden usandın, ey İsrail.'),
(2001865,68,23,43,23,'Yakmalık sunu için bana davar getirmediniz, 2 Kurbanlarınızla beni onurlandırmadınız. 2 Sizi sunularla uğraştırmadım, 2 Günnük isteyerek sizi usandırmadım.'),
(2001866,68,23,43,24,'Benim için güzel kokulu kamış satın almadınız, 2 Doyurmadınız beni kurbanlarınızın yağıyla. 2 Tersine, beni günahlarınızla uğraştırdınız, 2 Suçlarınızla usandırdınız.'),
(2001867,68,23,43,25,'Kendi uğruna suçlarınızı silen benim, evet benim, 2 Günahlarınızı anmaz oldum.'),
(2001868,68,23,43,26,'‹‹Geçmişi bana anımsatın, hesaplaşalım, 2 Haklı çıkmak için davanızı anlatın.'),
(2001869,68,23,43,27,'İlk atanız günah işledi, 2 Sözcüleriniz bana başkaldırdı.'),
(2001870,68,23,43,28,'Bu yüzden tapınak görevlilerini bayağılaştırdım; 2 Yakup soyunu bütünüyle yıkıma, 2 İsrail''i rezilliğe mahkûm ettim.››'),
(2001871,68,23,44,1,'‹‹Şimdi, ey kulum Yakup soyu, 2 Seçtiğim İsrail halkı, dinle!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001872,68,23,44,2,'Seni yaratan, rahimde sana biçim veren, 2 Sana yardım edecek olan RAB şöyle diyor: 2 ‹Korkma, ey kulum Yakup soyu, 2 Ey seçtiğim Yeşurun! verilen bir addır.'),
(2001873,68,23,44,3,'‹‹ ‹Susamış toprağı sulayacak, 2 Kurumuş toprakta dereler akıtacağım. 2 Çocuklarının üzerine Ruhumu dökecek, 2 Soyunu kutsayacağım.'),
(2001874,68,23,44,4,'Akarsu kıyısında otlar arasında yükselen 2 Kavaklar gibi boy atacaklar.›'),
(2001875,68,23,44,5,'‹‹Kimi, ‹Ben RABbe aitim› diyecek, 2 Kimi Yakup adını alacak, 2 Kimi de eline ‹RABbe ait› yazıp 2 İsrail adını benimseyecek.››'),
(2001876,68,23,44,6,'RAB, İsrailin Kralı ve Kurtarıcısı, 2 Her Şeye Egemen RAB diyor ki, 2 ‹‹İlk ve son benim, 2 Benden başka Tanrı yoktur.'),
(2001877,68,23,44,7,'Benim gibi olan var mı? Haber versin. 2 Ezeli halkımı var ettiğimden beri olup bitenleri, 2 Bundan sonra olacakları söyleyip sıralasın, 2 Evet, gelecek olayları bildirsin!'),
(2001878,68,23,44,8,'Yılmayın, korkmayın! 2 Size çok önceden beri söyleyip açıklamadım mı? 2 Tanıklarım sizsiniz. 2 Benden başka Tanrı var mı? 2 Hayır, başka Kaya yok; 2 Ben bir başkasını bilmiyorum.››'),
(2001879,68,23,44,9,'Putlara biçim verenlerin hepsi boş insanlardır. 2 Değer verdikleri nesneler hiçbir işe yaramaz. 2 Putların tanıkları onlardır; 2 Ne bir şey görür ne de bir şey bilirler. 2 Bunun sonucunda utanç içinde kalacaklar.'),
(2001880,68,23,44,10,'Kim yararsız ilaha biçim vermek, 2 Dökme put yapmak ister?'),
(2001881,68,23,44,11,'Bakın, bu putlarla uğraşanların hepsi utanacak. 2 Onları yapanlar salt insan. 2 Hepsi toplanıp yargılanmaya gelsin. 2 Dehşete düşecek, utanacaklar birlikte.'),
(2001882,68,23,44,12,'Demirci aletini alır, 2 Kömür ateşinde çalışır, 2 Çekiçle demire biçim verir. 2 Güçlü koluyla onu işler. 2 Acıkır, güçsüz kalır, su içmeyince tükenir.'),
(2001883,68,23,44,13,'Marangoz iple ölçü alır, 2 Tahtayı tebeşirle çizer. 2 Raspayla tahtayı biçimlendirir, 2 Pergelle işaretler, insan biçimi verir. 2 İnsan güzelliğinde, 2 Evde duracak bir put yapar.'),
(2001884,68,23,44,14,'İnsan kendisi için sedir ağaçları keser, 2 Palamut, meşe ağaçları alır. 2 Ormanda kendine bir ağaç seçer. 2 Bir çam diker, ama ağacı büyüten yağmurdur.'),
(2001885,68,23,44,15,'Sonra ağaç odun olarak kullanılır. 2 İnsan aldığı odunla hem ısınır, 2 Hem tutuşturup ekmek pişirir, 2 Hem de bir ilah yapıp tapınır. 2 Yaptığı putun önünde yere kapanır.'),
(2001886,68,23,44,16,'Odunun bir kısmını yakar, 2 Ateşinde et kızartıp karnını doyurur. 2 Isınınca bir oh çeker, 2 ‹‹Isındım, ateşin sıcaklığını duyuyorum›› der.'),
(2001887,68,23,44,17,'Artakalan odundan kendine bir ilah, 2 Oyma put yapar; 2 Önünde yere kapanıp ona tapınır, 2 ‹‹Beni kurtar, çünkü ilahım sensin›› diye yakarır.'),
(2001888,68,23,44,18,'Böyleleri anlamaz, bilmez. 2 Çünkü gözleri de zihinleri de öylesine kapalı ki, 2 Görmez, anlamazlar.'),
(2001889,68,23,44,19,'Durup düşünmez, bilmez, 2 Anlamazlar ki şöyle desinler: 2 ‹‹Odunun bir kısmını yakıp 2 Ateşinde ekmek pişirdim, et kızartıp yedim. 2 Artakalanından iğrenç bir şey mi yapayım? 2 Bir odun parçasının önünde yere mi kapanayım?››'),
(2001890,68,23,44,20,'Külle besleniyorlar. 2 Aldanan yürekleri onları saptırıyor. 2 Canlarını kurtaramaz, 2 ‹‹Sağ elimdeki şu nesne aldatıcı değil mi?›› diyemezler.'),
(2001891,68,23,44,21,'‹‹Ey Yakup soyu, ey İsrail, 2 Söylediklerimi anımsayın, çünkü kulumsunuz. 2 Size ben biçim verdim, kulumsunuz; 2 Seni unutmam, ey İsrail.'),
(2001892,68,23,44,22,'İsyanlarınızı bulut gibi, 2 Günahlarınızı sis gibi sildim. 2 Bana dönün, çünkü sizi kurtardım.››'),
(2001893,68,23,44,23,'Sevinçle haykırın, ey gökler, 2 Çünkü bunu RAB yaptı. 2 Haykırın, ey yerin derinlikleri. 2 Ey dağlar, ey orman, ormandaki her ağaç, 2 Sevinç çığlıklarına katılın. 2 Çünkü RAB Yakup soyunu kurtararak 2 İsrailde görkemini gösterdi.'),
(2001894,68,23,44,24,'Sizi kurtaran, 2 Size rahimde biçim veren RAB diyor ki, 2 ‹‹Her şeyi yaratan, 2 Gökleri yalnız başına geren, 2 Yeryüzünü tek başına seren, 2 Sahte peygamberlerin belirtilerini boşa çıkaran, 2 Falcılarla alay eden, 2 Bilgeleri geri çeviren, 2 Bilgilerini saçmalığa dönüştüren, 2 Kulunun sözlerini yerine getiren, 2 Ulaklarının peygamberlik sözlerini gerçekleştiren, 2 Yeruşalim için, ‹İçinde oturulacak›, 2 Yahuda kentleri için, ‹Yeniden kurulacak, 2 Yıkıntılarını onaracağım› diyen; 2 Engine, ‹Kuru! Sularını kurutacağım› diyen, 2 Koreş için, ‹O çobanımdır, 2 Her istediğimi yerine getirecek›, 2 Yeruşalim için, ‹Yeniden kurulacak›, 2 Tapınak için, ‹Temeli atılacak› diyen RAB benim.››'),
(2001895,68,23,45,1,'RAB meshettiği kişiye, 2 Sağ elinden tuttuğu Koreşe sesleniyor. 2 Uluslara onun önünde baş eğdirecek, 2 Kralları silahsızlandıracakfö, 2 Bir daha kapanmayacak kapılar açacak. 2 Ona şöyle diyor:'),
(2001896,68,23,45,2,'‹‹Senin önünsıra gidip 2 Dağları düzleyecek, 2 Tunç kapıları kırıp 2 Demir sürgülerini parçalayacağım.'),
(2001897,68,23,45,3,'Seni adınla çağıranın 2 Ben RAB, İsrailin Tanrısı olduğumu anlayasın diye 2 Karanlıkta kalmış hazineleri, 2 Gizli yerlerde saklı zenginlikleri sana vereceğim.'),
(2001898,68,23,45,4,'Sen beni tanımadığın halde 2 Kulum Yakup soyu ve seçtiğim İsrail uğruna 2 Seni adınla çağırıp onurlu bir unvan vereceğim.'),
(2001899,68,23,45,5,'RAB benim, başkası yok, 2 Benden başka Tanrı yok. 2 Beni tanımadığın halde seni güçlü kılacağım.'),
(2001900,68,23,45,6,'Öyle ki, doğudan batıya dek 2 Benden başkası olmadığını herkes bilsin. 2 RAB benim, başkası yok.'),
(2001901,68,23,45,7,'Işığı biçimlendiren, karanlığı yapan, 2 Esenliği ve felaketi yaratan, 2 Bütün bunları yapan RAB benim.'),
(2001902,68,23,45,8,'Ey gökler, yukarıdan doğruluk damlatın, 2 Ey bulutlar, doğruluk yağdırın. 2 Toprak yarılsın, kurtuluş meyvesi versin, 2 Onunla birlikte doğruluk yetiştirsin. 2 Bunları yaratan RAB benim.››'),
(2001903,68,23,45,9,'Kendine biçim verenle çekişenin vay haline! 2 Kil, topraktan yapılmış çömlek parçası, 2 Kendisine biçim verene, ‹‹Ne yapıyorsun? 2 Yarattığın nesnenin tutacağı yok›› diyebilir mi?'),
(2001904,68,23,45,10,'Babasına, ‹‹Dünyaya ne getirdin?›› 2 Ya da annesine, ‹‹Ne biçim şey doğurdun?›› 2 Diyenin vay haline!'),
(2001905,68,23,45,11,'İsrailin Kutsalı, 2 Ona biçim veren RAB diyor ki, 2 ‹‹Çocuklarımın geleceği hakkında beni sorgulayabilir, 2 Ellerimin yapıtları hakkında bana buyruk verebilir misiniz?'),
(2001906,68,23,45,12,'Dünyayı ben yaptım, 2 Üzerindeki insanı ben yarattım. 2 Benim ellerim gerdi gökleri, 2 Bütün gök cisimleri benim buyruğumda.'),
(2001907,68,23,45,13,'Koreşi doğrulukla harekete geçirecek, 2 Yollarını düzleyeceğim. 2 Kentimi o onaracak, 2 Sürgünlerimi ücret ya da ödül almadan o özgür kılacak.›› 2 Böyle diyor Her Şeye Egemen RAB.'),
(2001908,68,23,45,14,'RAB diyor ki, 2 ‹‹Mısırın ürettikleri, 2 Kûşun ticaret gelirleri 2 Ve uzun boylu Sevalılar size gelecek, sizin olacak. 2 Zincire vurulmuş olarak ardınızsıra yürüyecekler. 2 Önünüzde yere kapanıp yalvaracaklar: 2 ‹Tanrı yalnız sizinledir, 2 Başkası, başka Tanrı yok.› ››'),
(2001909,68,23,45,15,'Gerçekten sen kendini gizleyen bir Tanrısın, 2 Ey İsrailin Tanrısı, ey Kurtarıcı!'),
(2001910,68,23,45,16,'Put yapanların hepsi utandırılacak, rezil olacak. 2 Utanç içinde uzaklaşacaklar.'),
(2001911,68,23,45,17,'Ama İsrail RAB tarafından kurtarılacak, 2 Sonsuza dek sürecek kurtuluşu. 2 Çağlar boyunca utandırılmayacak, 2 Asla rezil olmayacak.'),
(2001912,68,23,45,18,'Çünkü gökleri yaratan RAB, 2 Dünyayı yaratıp biçimlendiren, pekiştiren, 2 Üzerinde yaşanmasın diye değil, yaşansın diye 2 Biçimlendiren RAB -Tanrı Odur- şöyle diyor: 2 ‹‹RAB benim, başkası yok.'),
(2001913,68,23,45,19,'Ben gizlide, 2 Karanlıklar ülkesinin bir köşesinde konuşmadım. 2 Yakup soyuna, ‹Beni olmayacak yerlerde arayın› demedim. 2 Doğru olanı söyleyen, adil olanı bildiren RAB benim.››'),
(2001914,68,23,45,20,'‹‹Ey sizler, uluslardan kaçıp kurtulanlar, 2 Toplanıp gelin, birlikte yaklaşın! 2 Tahtadan oyma putlar taşıyan, 2 Kurtaramayan ilahlara yakaranlar bilgisizdir.'),
(2001915,68,23,45,21,'Konuşun, davanızı sunun, 2 Birbirinize danışın. 2 Bunları çok önceden duyurup bildiren kim? 2 Ben RAB, bildirmedim mi? 2 Benden başka Tanrı yok, adil Tanrı ve Kurtarıcı benim. 2 Yok benden başkası.'),
(2001916,68,23,45,22,'‹‹Ey dünyanın dört bucağındakiler, 2 Bana dönün, kurtulursunuz. 2 Çünkü Tanrı benim, başkası yok.'),
(2001917,68,23,45,23,'Kendi üzerime ant içtim, 2 Ağzımdan çıkan söz doğrudur, boşa çıkmaz: 2 Her diz önümde çökecek, 2 Her dil bana ant içecek.'),
(2001918,68,23,45,24,'‹‹Benim için şöyle diyecekler: 2 ‹Doğruluk ve güç yalnız RABdedir›, 2 İnsanlar Ona gelecek. 2 RABbe öfkelenenlerin hepsi utandırılacak.'),
(2001919,68,23,45,25,'Ama bütün İsrail soyu 2 RAB tarafından aklanacak, 2 O''nunla övünecek.'),
(2001920,68,23,46,1,'‹‹İlah Bel diz çökmüş, ilah Nebo sinmiş, 2 Putları hayvanlara, öküzlere yüklenmiş gidiyor. 2 Taşınan bu nesneleriniz ağırlık, 2 Yorgun hayvana yük oldu.'),
(2001921,68,23,46,2,'Birlikte sinmiş, diz çökmüşler, 2 Putlarını yük olmaktan kurtaramıyorlar. 2 Sürgüne gidecek onlar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001922,68,23,46,3,'‹‹Ey Yakup soyu, İsrailin sağ kalanları, 2 Doğdunuz doğalı yüklendiğim, 2 Rahimden çıktınız çıkalı taşıdığım sizler, 2 Dinleyin beni:'),
(2001923,68,23,46,4,'Siz yaşlanıncaya dek ben Oyum; 2 Saçlarınız ağarıncaya dek 2 Ben yükleneceğim sizi. 2 Sizi ben yarattım, ben taşıyacağım, 2 Evet, sizi ben yüklenecek, ben kurtaracağım.'),
(2001924,68,23,46,5,'‹‹Beni kime benzetecek, 2 Kime denk tutacaksınız? 2 Kiminle karşılaştıracaksınız ki, benzer olalım?'),
(2001925,68,23,46,6,'Kimisi bol keseden harcadığı altından, 2 Terazide tarttığı gümüşten 2 Ücret karşılığında kuyumcuya ilah yaptırır, 2 Önünde yere kapanıp tapınır.'),
(2001926,68,23,46,7,'Onu omuzlayıp taşır, yerine koyar. 2 Öylece durur put, yerinden kımıldamaz. 2 Kendisine yakarana yanıt veremez, 2 Onu sıkıntısından kurtaramaz.'),
(2001927,68,23,46,8,'‹‹Bunu anımsayın, ey başkaldıranlar, 2 Adam olun, aklınızdan çıkarmayın!'),
(2001928,68,23,46,9,'Çok önceden beri olup bitenleri anımsayın. 2 Çünkü Tanrı benim, başkası yok. 2 Tanrı benim, benzerim yok.'),
(2001929,68,23,46,10,'Sonu ta başlangıçtan, 2 Henüz olmamış olayları çok önceden bildiren, 2 ‹Tasarım gerçekleşecek, 2 İstediğim her şeyi yapacağım› diyen benim.'),
(2001930,68,23,46,11,'Doğudan yırtıcı kuşu, 2 Uzak bir ülkeden 2 Tasarımı gerçekleştirecek adamı çağıran benim. 2 Evet, bunları söyledim, 2 Kesinlikle yerine getirecek, 2 Tasarladığımı yapacağım mutlaka.'),
(2001931,68,23,46,12,'‹‹Ey dikbaşlılar, doğruluktan uzak olanlar, 2 Dinleyin beni!'),
(2001932,68,23,46,13,'Zaferim yaklaştı, uzak değil; 2 Kurtarışım gecikmeyecek. 2 Güzelliğim olan İsrail için 2 Siyon''u kurtaracağım.››'),
(2001933,68,23,47,1,'‹‹Ey Babil, erden kız, 2 İn aşağı, toprağa otur. 2 Ey Kildani kızı, 2 Tahtın yok artık, yere otur. 2 Bundan böyle, ‹Nazik, narin› demeyecekler sana.'),
(2001934,68,23,47,2,'Bir çift değirmen taşı al da un öğüt, 2 Çıkar peçeni, kaldır eteğini. 2 Baldırını aç, ırmaklardan geç.'),
(2001935,68,23,47,3,'Çıplaklığın sergilenecek, mahrem yerlerin görünecek. 2 Öç alacağım, kimseyi esirgemeyeceğim.››'),
(2001936,68,23,47,4,'Bizim kurtarıcımız 2 İsrailin Kutsalıdır. 2 Onun adı ‹‹Her Şeye Egemen RABdir!››'),
(2001937,68,23,47,5,'RAB diyor ki, ‹‹Ey Kildani kızı, 2 Karanlığa çekilip sessizce otur. 2 Çünkü bundan böyle ‹Ülkeler kraliçesi› demeyecekler sana.'),
(2001938,68,23,47,6,'Halkıma öfkelenmiş, 2 Mirasım olduğu halde onu bayağılaştırıp 2 Eline teslim etmiştim. 2 Ama sen onlara acımadın, 2 Yaşlılara bile çok ağır bir boyunduruk yükledin.'),
(2001939,68,23,47,7,'‹Sonsuza dek kraliçe olacağım› diye düşünüyordun, 2 Bunları aklına getirmedin, sonuçlarını düşünmedin.'),
(2001940,68,23,47,8,'‹‹Ey şimdi güvenlikte yaşayan zevk düşkünü, 2 İçinden, ‹Kraliçe benim, başkası yok; 2 Hiç dul kalmayacak, 2 Evlat acısı görmeyeceğim› diyorsun. 2 Dinle şimdi:'),
(2001941,68,23,47,9,'Bir gün içinde ikisi birden başına gelecek: 2 Çok sayıda büyüye, etkili muskalarına karşın 2 Hem dul kalacak, 2 Hem evlat acısını alabildiğine yaşayacaksın.'),
(2001942,68,23,47,10,'‹‹Kötülüğüne güvendin, 2 ‹Beni gören yok› diye düşündün. 2 Bilgin ve bilgeliğin seni saptırdı. 2 İçinden, ‹Kraliçe benim, başkası yok› diyordun.'),
(2001943,68,23,47,11,'Ne var ki, felakete uğrayacaksın. 2 Onu durduracak büyü yok elinde, 2 Başına gelecek belayı önleyemeyeceksin. 2 Üzerine ansızın hiç beklemediğin bir yıkım gelecek.'),
(2001944,68,23,47,12,'Gençliğinden beri emek verdiğin 2 Muskalarına, çok sayıda büyüye devam et; 2 Belki yararını görür, 2 Kimilerini titretirsin.'),
(2001945,68,23,47,13,'Aldığın öğütlerin çokluğu 2 Seni tüketti. 2 Yıldız falcıların, yıldızbilimcilerin, 2 Ay başlarında ne olacağını bildirenlerin, 2 Şimdi kalksınlar da 2 Başına geleceklerden seni kurtarsınlar.'),
(2001946,68,23,47,14,'‹‹Bak, hepsi anızdan farksız, 2 Ateş yakacak onları. 2 Canlarını alevden kurtaramayacaklar. 2 Ne ısınmak için kor, 2 Ne de karşısında oturulacak ateş olacak.'),
(2001947,68,23,47,15,'Emek verdiğin adamlar böyle olacak. 2 Gençliğinden beri alışveriş ettiğin herkes 2 Kendi yoluna gidecek, 2 Seni kurtaran olmayacak.››'),
(2001948,68,23,48,1,'‹‹Dinle, ey Yakup soyu! 2 İsrail adıyla anılan, Yahuda soyundan gelen, 2 RABbin adıyla ant içen sizler, 2 İsrailin Tanrısına yakarır, 2 Ama bunu doğrulukla, içtenlikle yapmazsınız.'),
(2001949,68,23,48,2,'Kutsal kentli olduğunuzu, 2 İsrailin Tanrısına dayandığınızı ileri sürersiniz. 2 Onun adı Her Şeye Egemen RABdir.'),
(2001950,68,23,48,3,'Olup bitenleri çok önceden bildirdim, 2 Ağzımı açıp duyurdum. 2 Ansızın yaptım ve gerçekleştiler.'),
(2001951,68,23,48,4,'İnatçı olduğunuzu, 2 Tunç alınlı, demir boyunlu olduğunuzu bildiğim için'),
(2001952,68,23,48,5,'Bunları size çok önceden bildirdim, 2 Olmadan önce duyurdum. 2 Yoksa, ‹Bunları yapan putlarımızdır, 2 Olmalarını buyuran 2 Oyma ve dökme putlarımızdır› derdiniz.'),
(2001953,68,23,48,6,'Bunları duydunuz, hepsini inceleyin. 2 Peki, kabul etmeyecek misiniz? 2 Şimdiden size yeni şeyler, 2 Bilmediğiniz gizli şeyler açıklayacağım.'),
(2001954,68,23,48,7,'Bunlar şimdi yaratılıyor, 2 Geçmişte değil; 2 Bugüne kadar duymadınız, 2 Yoksa, ‹Bunları biliyorduk› derdiniz.'),
(2001955,68,23,48,8,'Ne duydunuz, ne de anladınız, 2 Öteden beri kulaklarınız tıkalı. 2 Ne denli hain olduğunuzu biliyorum, 2 Doğuştan isyankâr olduğunuz biliniyor.'),
(2001956,68,23,48,9,'Adım uğruna öfkemi geciktiriyorum. 2 Ünümden ötürü kendimi tutuyorum, 2 Yoksa sizi yok ederdim.'),
(2001957,68,23,48,10,'Bakın, gümüşü arıtır gibi olmasa da sizleri arıttım, 2 Sıkıntı ocağında denedim.'),
(2001958,68,23,48,11,'Bunu kendim için, evet, kendim için yapıyorum. 2 Adımı bayağılaştırmanızı nasıl hoş görebilirim? 2 Bana ait olan onuru başkasına vermem.››'),
(2001959,68,23,48,12,'‹‹Ey Yakup soyu, çağırdığım İsrail, beni dinle: 2 Ben Oyum; ilk Benim, son da Benim.'),
(2001960,68,23,48,13,'Yeryüzünün temelini elimle attım, 2 Gökleri sağ elim gerdi. 2 Onları çağırdığımda 2 Birlikte önümde dikilirler.'),
(2001961,68,23,48,14,'‹‹Toplanıp dinleyin hepiniz: 2 Putlardan hangisi bunları önceden bildirebildi? 2 RABbin sevdiği kişi 2 Onun Babile karşı tasarladığını yerine getirecek. 2 Gücünü Kildanilere karşı kullanacak.'),
(2001962,68,23,48,15,'Ben, evet, ben söyledim, onu ben çağırdım, 2 Onu getirdim, görevini başaracak.'),
(2001963,68,23,48,16,'‹‹Yaklaşın bana, dinleyin söyleyeceklerimi: 2 Başlangıçtan beri açıkça konuştum, 2 O zamandan bu yana oradayım.›› 2 Egemen RAB şimdi beni ve Ruhunu gönderiyor.'),
(2001964,68,23,48,17,'Sizleri kurtaran İsrailin Kutsalı RAB diyor ki, 2 ‹‹Yararlı olanı size öğreten, 2 Gitmeniz gereken yolda sizi yürüten 2 Tanrınız RAB benim.'),
(2001965,68,23,48,18,'‹‹Keşke buyruklarıma dikkat etseydiniz! 2 O zaman esenliğiniz ırmak gibi, 2 Doğruluğunuz denizin dalgaları gibi olurdu.'),
(2001966,68,23,48,19,'Soyunuz kum gibi, 2 Torunlarınız kum taneleri gibi olurdu. 2 Adları ne unutulur, 2 Ne de huzurumdan yok olurdu.››'),
(2001967,68,23,48,20,'Babilden çıkın, Kildanilerden kaçın, 2 Sevinç çığlıklarıyla ilan edin bunu, 2 Haberini duyurun, dünyanın dört bucağına yayın. 2 ‹‹RAB, kulu Yakupun soyunu kurtardı›› deyin.'),
(2001968,68,23,48,21,'Onları çöllerden geçirirken susuzluk çekmediler, 2 Onlar için sular akıttı kayadan, 2 Kayayı yardı, sular fışkırdı.'),
(2001969,68,23,48,22,'‹‹Kötülere esenlik yoktur›› diyor RAB.'),
(2001970,68,23,49,1,'Ey kıyı halkları, işitin beni, 2 Uzaktaki halklar, iyi dinleyin. 2 RAB beni ana rahmindeyken çağırdı, 2 Annemin karnındayken adımı koydu.'),
(2001971,68,23,49,2,'Ağzımı keskin kılıç yaptı, 2 Elinin gölgesinde gizledi beni. 2 Beni keskin bir ok yaptı, 2 Kendi ok kılıfına sakladı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2001972,68,23,49,3,'Bana, ‹‹Kulumsun, ey İsrail, 2 Görkemimi senin aracılığınla göstereceğim›› dedi.'),
(2001973,68,23,49,4,'Ama ben, ‹‹Boşuna emek verdim›› dedim, 2 ‹‹Gücümü boş yere, bir hiç için tükettim. 2 RAB yine de hakkımı savunur, 2 Tanrım yaptıklarımın karşılığını verir.››'),
(2001974,68,23,49,5,'Kulu olmam için, 2 Yakup soyunu kendisine geri getirmem, 2 İsraili önünde toplamam için 2 Rahimde beni biçimlendiren RAB şimdi şöyle diyor: 2 -Onun gözünde onurluyum, 2 Tanrım bana güç kaynağı oldu.-'),
(2001975,68,23,49,6,'‹‹Yakupun oymaklarını canlandırmak, 2 Sağ kalan İsraillileri geri getirmek için 2 Kulum olman yeterli değil. 2 Seni uluslara ışık yapacağım. 2 Öyle ki, kurtarışım yeryüzünün dört bucağına ulaşsın.››'),
(2001976,68,23,49,7,'İnsanların hor gördüğüne, 2 Ulusların iğrendiğine, 2 Egemenlerin kulu olana 2 İsrailin Kurtarıcısı ve Kutsalı RAB diyor ki, 2 ‹‹Seni seçmiş olan İsrailin Kutsalı sadık RABden ötürü 2 Krallar seni görünce ayağa kalkacak, 2 Önderler yere kapanacak.››'),
(2001977,68,23,49,8,'RAB şöyle diyor: 2 ‹‹Lütuf zamanında seni yanıtlayacağım, 2 Kurtuluş günü sana yardım edecek, 2 Seni koruyacağım. 2 Seni halka antlaşma olarak vereceğim. 2 Öyle ki, yıkık ülkeyi yeniden kurasın, 2 Mülk olarak yeni sahiplerine veresin.'),
(2001978,68,23,49,9,'Tutsaklara, ‹Çıkın›, 2 Karanlıktakilere, ‹Dışarı çıkın› diyeceksin. 2 Yol boyunca beslenecek, 2 Her çıplak tepede otlak bulacaklar.'),
(2001979,68,23,49,10,'Acıkmayacak, susamayacaklar, 2 Kavurucu sıcak ve güneş çarpmayacak onları. 2 Çünkü onlara merhamet eden kendilerine yol gösterecek 2 Ve onları pınarlara götürecek.'),
(2001980,68,23,49,11,'Bütün dağlarımı yola dönüştüreceğim, 2 Anayollarım yükseltilecek.'),
(2001981,68,23,49,12,'İşte halkım ta uzaklardan, 2 Kimi kuzeyden, kimi batıdan, kimi de Sinimden gelecek.››'),
(2001982,68,23,49,13,'Ey gökler, sevinçle haykırın, 2 Neşeyle coş, ey yeryüzü! 2 Ey dağlar, sevinç çığlıklarına katılın, 2 Çünkü RAB halkını avutacak, 2 Ezilene merhamet gösterecek.'),
(2001983,68,23,49,14,'Oysa Siyon, ‹‹RAB beni terk etti, 2 Rab beni unuttu›› diyordu.'),
(2001984,68,23,49,15,'Ama RAB, ‹‹Kadın emzikteki çocuğunu unutabilir mi?›› diyor, 2 ‹‹Rahminden çıkan çocuktan sevecenliği esirger mi? 2 Kadın unutabilir, 2 Ama ben seni asla unutmam.'),
(2001985,68,23,49,16,'Bak, adını avuçlarıma kazıdım, 2 Duvarlarını gözlüyorum sürekli.'),
(2001986,68,23,49,17,'Oğulların koşar adım geliyor, 2 Seni yıkıp viran edenlerse çıkıp gidecek.'),
(2001987,68,23,49,18,'Başını kaldır da çevrene bir bak: 2 Hepsi toplanmış sana geliyor. 2 Ben RAB, varlığım hakkı için diyorum ki, 2 Onların hepsi senin süsün olacak, 2 Bir gelin gibi takınacaksın onları.'),
(2001988,68,23,49,19,'‹‹Çünkü yıkılmış, viraneye dönmüştün, 2 Ülken yerle bir olmuştu. 2 Ama şimdi halkına dar geleceksin, 2 Seni harap etmiş olanlar senden uzak duracaklar.'),
(2001989,68,23,49,20,'Yitirdiğini sandığın çocuklarının sesini yine duyacaksın: 2 ‹Burası bize dar geliyor, 2 Yaşayacak bir yer ver bize› diyecekler.'),
(2001990,68,23,49,21,'O zaman içinden, 2 ‹Kim doğurdu bunları bana?› diyeceksin, 2 ‹Çocuklarımı yitirmiştim, doğuramıyordum. 2 Sürgüne gönderilmiş, dışlanmıştım. 2 Öyleyse bunları kim büyüttü? 2 Yapayalnız kalmıştım, 2 Nereden çıkıp geldi bunlar?› ››'),
(2001991,68,23,49,22,'Egemen RAB diyor ki, 2 ‹‹Bakın, uluslara elimle işaret verdiğimde, 2 Sancağımı yükselttiğimde halklara, 2 Senin oğullarını kucaklarında getirecek, 2 Kızlarını omuzlarında taşıyacaklar.'),
(2001992,68,23,49,23,'Krallar size babalık, 2 Prensesler sütannelik yapacak, 2 Yüzüstü yere kapanıp 2 Ayaklarının tozunu yalayacaklar. 2 O zaman benim RAB olduğumu anlayacaksın. 2 Bana umut bağlayan utandırılmayacak.››'),
(2001993,68,23,49,24,'Güçlünün ganimeti elinden alınabilir mi? 2 Zorbanın elindeki tutsak kurtulabilir mi? ‹‹Doğru olanın›› (bkz. 25. ayet).'),
(2001994,68,23,49,25,'Ama RAB diyor ki, 2 ‹‹Evet, güçlünün elindeki tutsaklar alınacak, 2 Zorbanın aldığı ganimet de kurtarılacak. 2 Seninle çekişenle ben çekişeceğim, 2 Senin çocuklarını ben kurtaracağım.'),
(2001995,68,23,49,26,'Sana zulmedenlere kendi etlerini yedireceğim, 2 Tatlı şarap içmiş gibi kendi kanlarıyla sarhoş olacaklar. 2 Böylece bütün insanlar bilecek ki 2 Seni kurtaran RAB benim; 2 Kurtarıcın, Yakup''un Güçlüsü benim.››'),
(2001996,68,23,50,1,'RAB şöyle diyor: 2 ‹‹Boşadığım annenizin boşanma belgesi nerede? 2 Hangi alacaklıma sattım sizi? 2 Suçlarınız yüzünden satıldınız, 2 Anneniz isyanlarınız yüzünden dışlandı.'),
(2001997,68,23,50,2,'Geldiğimde neden kimse yoktu, 2 Çağırdığımda niçin yanıt veren olmadı? 2 Sizi kurtaramayacak kadar kısa mı elim, 2 Ya da gücüm yok mu sizi özgür kılmaya? 2 Azarlayarak denizi kurutur, 2 Irmakları çöle çeviririm. 2 Su kalmayınca balıklar ölür ve kokar.'),
(2001998,68,23,50,3,'Göklere karalar giydirir, 2 Çul ederim onların örtüsünü.››'),
(2001999,68,23,50,4,'Yorgunlara sözle destek olmayı bileyim diye 2 Egemen RAB bana eğitilmişlerin dilini verdi. 2 Eğitilenler gibi dinleyeyim diye kulağımı uyandırır her sabah.'),
(2002000,68,23,50,5,'Egemen RAB kulağımı açtı, 2 Karşı koymadım, geri çekilmedim.'),
(2002001,68,23,50,6,'Bana vuranlara sırtımı açtım, 2 Yanaklarımı uzattım sakalımı yolanlara. 2 Aşağılamalardan, tükürükten yüzümü gizlemedim.'),
(2002002,68,23,50,7,'Egemen RAB bana yardım ettiği için 2 Utanç duymam. 2 Kararımdan dönmemfş, 2 Utandırılmayacağımı bilirim. ettim››.'),
(2002003,68,23,50,8,'Beni haklı çıkaran yakınımda. 2 Benden davacı olan kim, yüzleşelim, 2 Kimdir hasmım, karşıma çıksın.'),
(2002004,68,23,50,9,'Bana yardım eden Egemen RABdir, 2 Kim suçlu çıkaracak beni? 2 Onların hepsi giysi gibi eskiyecek, 2 Tümünü güve yiyip bitirecek.'),
(2002005,68,23,50,10,'Aranızda RABden korkan, 2 Kulunun sözünü dinleyen kim var? 2 Karanlıkta yürüyen, ışığı olmayan, 2 RABbin adına güvensin, Tanrısına dayansın.'),
(2002006,68,23,50,11,'Ama ateş yakan, 2 Alevli oklar kuşanan sizler, hepiniz, 2 Ateşinizin aydınlığında, 2 Tutuşturduğunuz alevli okların arasında yürüyün. 2 Benden alacağınız şudur: 2 Azap içinde yatacaksınız.'),
(2002007,68,23,51,1,'‹‹Doğruluğun ardından giden, 2 RABbe yönelen sizler, beni dinleyin: 2 Yontulduğunuz kayaya, 2 Çıkarıldığınız taş ocağına bakın.'),
(2002008,68,23,51,2,'Atanız İbrahime, sizi doğuran Saraya bakın. 2 Çağırdığımda tek kişiydi İbrahim, 2 Ama ben onu kutsayıp çoğalttım.››'),
(2002009,68,23,51,3,'RAB Siyonu ve bütün yıkıntılarını avutacak. 2 Siyon çölünü Adene, bozkırı RABbin bahçesine döndürecek. 2 Orada coşku, sevinç, 2 Şükran ve ezgi olacak.'),
(2002010,68,23,51,4,'‹‹Beni dinle, ey halkım, 2 Bana kulak ver, ey ulusum! 2 Yasa benden çıkacak, 2 Halklara ışık olarak adaletimi yerleştireceğim.'),
(2002011,68,23,51,5,'Zaferim yaklaştı, 2 Kurtarışım ortaya çıktı. 2 Halkları gücümle yöneteceğim. 2 Kıyı halkları bana umut bağladı, 2 Umutla gücümü bekliyorlar.'),
(2002012,68,23,51,6,'Başınızı kaldırıp göklere bakın, 2 Aşağıya, yeryüzüne bakın. 2 Çünkü bu gökler duman gibi dağılacak, 2 Giysi gibi eskiyecek yeryüzü; 2 Üzerinde yaşayanlar sinek gibi ölecek. 2 Ama benim kurtarışım sonsuz olacak, 2 Ardı kesilmeyecek zaferimin.'),
(2002013,68,23,51,7,'‹‹Ey sizler, doğru olanı bilenler, 2 Yasamı yüreğinde taşıyan halk, dinleyin beni! 2 İnsanların aşağılamalarından korkmayın, 2 Yılmayın sövgülerinden.'),
(2002014,68,23,51,8,'Güvenin yediği giysi gibi, 2 Kurtçuğun yediği yapağı gibi yitecekler. 2 Oysa zaferim sonsuza dek kalacak, 2 Kurtarışım kuşaklar boyu sürecek.››'),
(2002015,68,23,51,9,'Uyan, ey RABbin gücü, uyan, kudreti kuşan! 2 Eski günlerde, önceki kuşaklar döneminde olduğu gibi uyan! 2 Rahavı parçalayan, 2 Deniz canavarının bedenini deşen sen değil miydin?'),
(2002016,68,23,51,10,'Denizi, engin suların derinliklerini kurutan, 2 Kurtulanların geçmesi için 2 Denizin derinliklerini yola çeviren sen değil miydin?'),
(2002017,68,23,51,11,'RABbin kurtardıkları dönecek, 2 Sevinçle haykırarak Siyona varacaklar. 2 Yüzlerinde sonsuz sevinç olacak. 2 Onların olacak coşku ve sevinç, 2 Üzüntü ve inilti kaçacak.'),
(2002018,68,23,51,12,'RAB diyor ki, 2 ‹‹Sizi avutan benim, evet benim. 2 Siz kimsiniz ki, ölümlü insandan, 2 Ottan farksız insanoğlundan korkarsınız?'),
(2002019,68,23,51,13,'Sizi yaratan, gökleri geren, 2 Dünyanın temellerini atan RABbi 2 Nasıl olur da unutursunuz? 2 Sizi yok etmeye hazırlanan zalimin öfkesinden 2 Neden gün boyu yılıp duruyorsunuz? 2 Hani nerede zalimin gazabı?'),
(2002020,68,23,51,14,'Zincire vurulmuş tutsaklar 2 Çok yakında özgürlüğe kavuşacak. 2 Ölüm çukuruna inmeyecek, 2 Aç kalmayacaklar.'),
(2002021,68,23,51,15,'Tanrınız RAB benim. 2 Dalgalar gürlesin diye denizi çalkalayan benim.›› 2 Onun adı Her Şeye Egemen RABdir!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002022,68,23,51,16,'‹‹Sözlerimi ağzına koydum, 2 Seni elimin gölgesiyle örttüm; 2 Gökleri yerleştirmen, 2 Yeryüzünün temellerini atman 2 Ve Siyona, ‹Halkım sensin› demen için...››'),
(2002023,68,23,51,17,'Uyan, ey Yeruşalim, uyan, kalk ayağa! 2 Sen ki, RABbin gazap kâsesini Onun elinden içtin. 2 Tamamını içtin sersemleten kâsenin.'),
(2002024,68,23,51,18,'Doğurduğun bunca oğuldan sana yol gösteren yok, 2 Elinden tutan da yok büyüttüğün bunca oğuldan.'),
(2002025,68,23,51,19,'Başına çifte felaket geldi, kim başsağlığı dileyecek? 2 Yıkım ve kırım, kıtlık ve kılıç. 2 Nasıl avutayım seni?'),
(2002026,68,23,51,20,'Oğulların baygın, ağa düşmüş ahular gibi 2 Her sokak başında yatıyor. 2 RABbin öfkesine de 2 Tanrının azarlayışına da doymuşlar.'),
(2002027,68,23,51,21,'Bu nedenle, ey ezilmiş Yeruşalim, 2 Şarapsız sarhoş olmuş halk, şunu dinle!'),
(2002028,68,23,51,22,'Egemenin RAB, kendi halkını savunan Tanrın diyor ki, 2 ‹‹Seni sersemleten kâseyi, gazabımın kâsesini 2 Elinden aldım. 2 Bir daha asla içmeyeceksin ondan.'),
(2002029,68,23,51,23,'Onu sana eziyet edenlerin eline vereceğim; 2 Onlar ki sana, ‹Yere yat da 2 Üzerinden geçelim› dediklerinde, 2 Sırtını toprak, yol ettin.››'),
(2002030,68,23,52,1,'Uyan, ey Siyon, uyan, kudretini kuşan. 2 Ey Yeruşalim, kutsal kent, güzel giysilerini giy. 2 Çünkü sünnetsizlerle murdarlar 2 Kapılarından asla içeri girmeyecek artık.'),
(2002031,68,23,52,2,'Üzerindeki tozu silk! 2 Kalk, ey Yeruşalim, tahtına otur, 2 Boynundaki zinciri çöz, 2 Ey Siyon, tutsak kız.'),
(2002032,68,23,52,3,'RAB diyor ki, 2 ‹‹Karşılıksız satılmıştınız, 2 Parasız kurtulacaksınız.››'),
(2002033,68,23,52,4,'Egemen RAB diyor ki, 2 ‹‹Halkım gurbette yaşamak için önce Mısıra inmişti. 2 Şimdi de Asurlular onları ezdi.'),
(2002034,68,23,52,5,'Halkım boş yere alınıp götürüldü, 2 Benim burayla ne ilgim kaldı?›› diyor RAB, 2 ‹‹Yöneticileri feryat ediyor, 2 Adıma günboyu sövülüyor›› diyor RAB.'),
(2002035,68,23,52,6,'‹‹Bundan ötürü halkım adımı bilecek, 2 O gün, ‹İşte ben› diyenin ben olduğumu anlayacak.››'),
(2002036,68,23,52,7,'Dağları aşıp gelen müjdecinin ayakları ne güzeldir! 2 O müjdeci ki, esenlik duyuruyor. 2 İyilik müjdesi getiriyor, kurtuluş haberi veriyor. 2 Siyon halkına, ‹‹Tanrınız egemenlik sürüyor!›› diye ilan ediyor.'),
(2002037,68,23,52,8,'Dinleyin! Bekçileriniz seslerini yükseltiyor, 2 Hep birlikte sevinçle haykırıyorlar. 2 Çünkü RABbin Siyona dönüşünü gözleriyle görmekteler!'),
(2002038,68,23,52,9,'Ey Yeruşalim yıkıntıları, 2 Hep birlikte sevinçle haykırıp bağırın! 2 Çünkü RAB halkını avuttu, 2 Yeruşalimi kurtardı.'),
(2002039,68,23,52,10,'Bütün ulusların gözü önünde 2 Kutsal kolunu sıvadı, 2 Dünyanın dört bucağı 2 Tanrımızın kurtarışını görecek.'),
(2002040,68,23,52,11,'Çekilin, çekilin, oradan çıkın, 2 Murdara dokunmayın. 2 Oradan çıkıp temizlenin, 2 Ey RABbe tapınma araçlarını taşıyan sizler!'),
(2002041,68,23,52,12,'Aceleyle çıkmayacak, 2 Kaçıp gitmeyeceksiniz; 2 Çünkü RAB önünüzden gidecek, 2 İsrailin Tanrısı artçınız olacak.'),
(2002042,68,23,52,13,'Bakın, kulum başarılı olacak; 2 Üstün olacak, el üstünde tutulup alabildiğine yüceltilecek.'),
(2002043,68,23,52,14,'Birçokları onun karşısında dehşete düşüyor; 2 Biçimi, görünüşü öyle bozuldu ki, 2 İnsana benzer yanı kalmadı;'),
(2002044,68,23,52,15,'Pek çok ulus ona şaşacak, 2 Onun önünde kralların ağızları kapanacak. 2 Çünkü kendilerine anlatılmamış olanı görecek, 2 Duymadıklarını anlayacaklar.'),
(2002045,68,23,53,1,'Verdiğimiz habere kim inandı? 2 RABbin gücü kime açıklandı?'),
(2002046,68,23,53,2,'O RABbin önünde bir fidan gibi, 2 Kurak yerdeki kök gibi büyüdü. 2 Bakılacak biçimden, güzellikten yoksundu. 2 Gönlümüzü çeken bir görünüşü de yoktu.'),
(2002047,68,23,53,3,'İnsanlarca hor görüldü, 2 Yapayalnız bırakıldı. 2 Acılar adamıydı, hastalığı yakından tanıdı. 2 İnsanların yüz çevirdiği biri gibi hor görüldü, 2 Ona değer vermedik.'),
(2002048,68,23,53,4,'Aslında hastalıklarımızı o üstlendi, 2 Acılarımızı o yüklendi. 2 Bizse Tanrı tarafından cezalandırıldığını, 2 Vurulup ezildiğini sandık.'),
(2002049,68,23,53,5,'Oysa, bizim isyanlarımız yüzünden onun bedeni deşildi, 2 Bizim suçlarımız yüzünden o eziyet çekti. 2 Esenliğimiz için gerekli olan ceza 2 Ona verildi. 2 Bizler onun yaralarıyla şifa bulduk.'),
(2002050,68,23,53,6,'Hepimiz koyun gibi yoldan sapmıştık, 2 Her birimiz kendi yoluna döndü. 2 Yine de RAB hepimizin cezasını ona yükledi.'),
(2002051,68,23,53,7,'O baskı görüp eziyet çektiyse de 2 Ağzını açmadı. 2 Kesime götürülen kuzu gibi, 2 Kırkıcıların önünde sessizce duran koyun gibi 2 Açmadı ağzını.'),
(2002052,68,23,53,8,'Acımasızca yargılanıp ölüme götürüldü. 2 Halkımın isyanı ve hak ettiği ceza yüzünden 2 Yaşayanlar diyarından atıldı. 2 Onun kuşağından bunu düşünen oldu mu?'),
(2002053,68,23,53,9,'Şiddete başvurmadığı, 2 Ağzından hileli söz çıkmadığı halde, 2 Ona kötülerin yanında bir mezar verildi, 2 Ama öldüğünde zenginin yanındaydı.'),
(2002054,68,23,53,10,'Ne var ki, RAB onun ezilmesini uygun gördü, 2 Acı çekmesini istedi. 2 Canını suç sunusu olarak sunarsa 2 Soyundan gelenleri görecek ve günleri uzayacak. 2 RABbin istemi onun aracılığıyla gerçekleşecek.'),
(2002055,68,23,53,11,'Canını feda ettiği için 2 Gördükleriyle hoşnut olacak. 2 RABbin doğru kulu, kendisini kabul eden birçoklarını aklayacak. 2 Çünkü onların suçlarını o üstlendi.'),
(2002056,68,23,53,12,'Bundan dolayı ona ünlüler arasında bir pay vereceğim, 2 Ganimeti güçlülerle paylaşacak. 2 Çünkü canını feda etti, başkaldıranlarla bir sayıldı. 2 Pek çoklarının günahını o üzerine aldı, 2 Başkaldıranlar için de yalvardı.'),
(2002057,68,23,54,1,'‹‹Çocuk doğurmayan ey kısır kadın, 2 Sevinç çığlıkları at; 2 Ey doğum ağrısı nedir bilmeyen sen, 2 Sevinçle haykır, bağır. 2 Çünkü terk edilmiş kadının, 2 Evli kadından daha çok çocuğu olacaktır›› diyor RAB.'),
(2002058,68,23,54,2,'‹‹Çadırının alanını genişlet, 2 Perdelerini uzat, çekinme. 2 Gergi iplerini de uzat, kazıklarını sağlamlaştır.'),
(2002059,68,23,54,3,'Çünkü sağa sola yayılacaksın, 2 Soyundan gelenler ulusları mülk edinecek, 2 Issız kentlere yerleşecek.'),
(2002060,68,23,54,4,'‹‹Korkma, ayıplanmayacaksın, 2 Utanma, aşağılanmayacaksın. 2 Unutacaksın gençliğinde yaşadığın utancı, 2 Dulluk ayıbını artık anmayacaksın.'),
(2002061,68,23,54,5,'Çünkü kocan, seni yaratandır. 2 Onun adı Her Şeye Egemen RABdir, 2 İsrailin Kutsalıdır seni kurtaran. 2 Ona bütün dünyanın Tanrısı denir.››'),
(2002062,68,23,54,6,'Tanrın diyor ki, ‹‹RAB seni terk edilmiş, 2 Ruhu kederli bir kadın, 2 Genç yaşta evlenip sonra dışlanmış 2 Bir kadın olarak çağırıyor:'),
(2002063,68,23,54,7,'‹Bir an için seni terk ettim, 2 Ama büyük sevecenlikle geri getireceğim.'),
(2002064,68,23,54,8,'Bir anlık taşkın öfkeyle senden yüz çevirmiştim, 2 Ama sonsuz sadakatle sana sevecenlik göstereceğim.› ›› 2 Seni kurtaran RAB böyle diyor.'),
(2002065,68,23,54,9,'‹‹Bu benim için Nuh tufanı gibidir. 2 Nuh tufanının bir daha yeryüzünü 2 Kaplamayacağına nasıl ant içtimse, 2 Sana öfkelenmeyeceğime, 2 Seni azarlamayacağıma da ant içiyorum.'),
(2002066,68,23,54,10,'Dağlar yerinden kalksa, tepeler sarsılsa da 2 Sadakatim senin üzerinden kalkmaz, 2 Esenlik antlaşmam sarsılmaz›› 2 Diyor sana merhamet eden RAB.'),
(2002067,68,23,54,11,'‹‹Ey kasırgaya tutulmuş, 2 Avuntu bulmamış ezik kent! 2 Taşlarını koyu harçla yerine koyacak, 2 Temellerini laciverttaşıyla atacağım.'),
(2002068,68,23,54,12,'Kale burçlarını yakuttan, 2 Kapılarını mücevherden, 2 Surlarını değerli taşlardan yapacağım.'),
(2002069,68,23,54,13,'Bütün çocuklarını ben RAB eğiteceğim, 2 Esenlikleri tam olacak.'),
(2002070,68,23,54,14,'Doğrulukla güçlenecek, 2 Baskıdan uzak olacak, korkmayacaksın. 2 Dehşet senden uzak kalacak, sana yaklaşmayacak.'),
(2002071,68,23,54,15,'Sana saldıran olursa, benden olmadığını bil. 2 Sana saldıran herkes önünde yenilgiye uğrayacak.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002072,68,23,54,16,'‹‹İşte, kor halindeki ateşi üfleyen, 2 Amaca uygun silah yapan demirciyi ben yarattım. 2 Yok etsin diye yıkıcıyı da ben yarattım.'),
(2002073,68,23,54,17,'Ama sana karşı yapılan hiçbir silah işe yaramayacak, 2 Mahkemede seni suçlayan her dili 2 Suçlu çıkaracaksın. 2 RAB''be kulluk edenlerin mirası şudur: 2 Onların gönenci bendendir›› diyor RAB.'),
(2002074,68,23,55,1,'‹‹Ey susamış olanlar, sulara gelin, 2 Parası olmayanlar, gelin, satın alın, yiyin. 2 Gelin, şarabı ve sütü parasız, bedelsiz alın.'),
(2002075,68,23,55,2,'Paranızı neden ekmek olmayana, 2 Emeğinizi doyurmayana harcıyorsunuz? 2 Beni iyi dinleyin ki, iyi olanı yiyesiniz, 2 Bolluğun tadını çıkarasınız!'),
(2002076,68,23,55,3,'‹‹Kulak verin, bana gelin. 2 Dinleyin ki yaşayasınız. 2 Ben de sizinle sonsuz bir antlaşma, 2 Davuta söz verdiğim kalıcı iyilikleri içeren bir antlaşma yapayım.'),
(2002077,68,23,55,4,'Bakın, onu halklara tanık, 2 Önder ve komutan yaptım.'),
(2002078,68,23,55,5,'Tanımadığınız ulusları çağıracaksınız, 2 Sizi tanımayan uluslar koşa koşa size gelecek. 2 Tanrınız RABden, 2 İsrailin Kutsalından ötürü gelecekler. 2 Çünkü RAB sizleri yüceltecek.››'),
(2002079,68,23,55,6,'Bulma fırsatı varken RABbi arayın, 2 Yakındayken Ona yakarın.'),
(2002080,68,23,55,7,'Kötü kişi yolunu, 2 Fesatçı düşüncelerini bıraksın; 2 RABbe dönsün, merhamet bulur, 2 Tanrımıza dönsün, bol bol bağışlanır.'),
(2002081,68,23,55,8,'‹‹Çünkü benim düşüncelerim 2 Sizin düşünceleriniz değil, 2 Sizin yollarınız benim yollarım değil›› diyor RAB.'),
(2002082,68,23,55,9,'‹‹Çünkü gökler nasıl yeryüzünden yüksekse, 2 Yollarım da sizin yollarınızdan, 2 Düşüncelerim düşüncelerinizden yüksektir.'),
(2002083,68,23,55,10,'Gökten inen yağmur ve kar, 2 Toprağı sulamadan, yeri yeşertmeden, 2 Ekinciye tohum, yiyene ekmek vermeden 2 Nasıl göğe dönmezse,'),
(2002084,68,23,55,11,'Ağzımdan çıkan söz de öyle olacaktır. 2 Bana boş dönmeyecek, 2 İstemimi yerine getirecek, 2 Yapması için onu gönderdiğim işi başaracaktır.'),
(2002085,68,23,55,12,'Sevinçle çıkacak, 2 Esenlikle geri götürüleceksiniz. 2 Dağlar, tepeler önünüzde sevinçle çığıracak, 2 Kırdaki bütün ağaçlar alkış tutacak.'),
(2002086,68,23,55,13,'Dikenli çalı yerine çam, 2 Isırgan yerine mersin ağacı bitecek. 2 Bunlar bana ün getirecek, 2 Yok olmayan sonsuz bir belirti olacak.››'),
(2002087,68,23,56,1,'RAB şöyle diyor: 2 ‹‹Adil ve doğru olanı koruyup yerine getirin. 2 Çünkü doğruluğum gelmek, 2 Adaletim görünmek üzeredir.'),
(2002088,68,23,56,2,'Bunu yapan insana, 2 Buna sımsıkı sarılan insanoğluna ne mutlu! 2 Şabat Gününü tutar, bayağılaştırmaz, 2 Her türlü kötülükten sakınır.››'),
(2002089,68,23,56,3,'RABbe bağlanan hiçbir yabancı, 2 ‹‹Kuşkusuz RAB beni halkından ayıracak››, 2 Hiçbir hadım da, 2 ‹‹Ben kuru bir ağacım›› demesin.'),
(2002090,68,23,56,4,'Çünkü RAB diyor ki, 2 ‹‹Şabat günlerimi tutan, 2 Beni hoşnut edeni seçen, 2 Antlaşmama sımsıkı bağlı kalan hadıma'),
(2002091,68,23,56,5,'Evimde, evimin dört duvarı arasında 2 Oğullardan da kızlardan da daha iyi bir anıt ve ad vereceğim; 2 Yok edilemez, ebedi bir ad olacak bu.'),
(2002092,68,23,56,6,'‹‹RABbe hizmet etmek, 2 Onun adını sevmek, 2 Kulu olmak için Ona bağlanan yabancıları, 2 Şabat Gününü tutan, bayağılaştırmayan, 2 Antlaşmama sımsıkı bağlı kalan herkesi,'),
(2002093,68,23,56,7,'Kutsal dağıma getirip 2 Dua evimde sevindireceğim. 2 Yakmalık sunularıyla kurbanları 2 Sunağımda kabul edilecek, 2 Çünkü evime ‹Bütün ulusların dua evi› denecek.››'),
(2002094,68,23,56,8,'İsrailin sürgünlerini toplayan Egemen RAB diyor ki, 2 ‹‹Toplanmış olanlara katmak üzere 2 Daha başkalarını da toplayacağım.››'),
(2002095,68,23,56,9,'Ey bütün kır hayvanları, 2 Ormanda yaşayan bütün hayvanlar, 2 Yiyip bitirmek için gelin!'),
(2002096,68,23,56,10,'İsrailin bekçileri kördür, hepsi bilgisizdir. 2 Havlayamayan dilsiz köpekler gibidirler. 2 Uzanıp düş görürler, 2 Uykuyu pek severler!'),
(2002097,68,23,56,11,'Doymak bilmeyen azgın köpeklere benzerler, 2 Aklı kıt çobanlar bunlar! 2 Kendi yollarına döndüler, 2 Her biri yalnız kendi çıkarını düşünüyor.'),
(2002098,68,23,56,12,'Birbirlerine, ‹‹Haydi, şarap getirelim, 2 Bol bol içki içelim! 2 Yarın da bugün gibi geçecek, 2 Hatta çok daha iyi olacak›› diyorlar.'),
(2002099,68,23,57,1,'Doğru kişi ölüp gidiyor, 2 Kimsenin umurunda değil. 2 Sadık adamlar da göçüp gidiyor; 2 Kimse doğru kişinin göçüp gitmekle 2 Kötülükten kurtulduğunun farkında değil.'),
(2002100,68,23,57,2,'Doğru kişi esenliğe kavuşur, 2 Doğru yolda yürümüş olan mezarındafü rahat uyur.'),
(2002101,68,23,57,3,'Ama siz, ey falcı kadının çocukları, 2 Fahişelik ve zina edenlerin soyu, buraya gelin!'),
(2002102,68,23,57,4,'Siz kiminle alay ediyorsunuz? 2 Kime dudak büküyor, dil çıkarıyorsunuz? 2 Ağaçlar arasında, bol yapraklı her ağacın altında 2 Şehvetle yanıp tutuşan, 2 Vadilerde, kaya kovuklarında çocuklarını kurban eden, 2 İsyan torunları, yalan soyu değil misiniz siz?'),
(2002103,68,23,57,6,'Sizin payınız 2 Vadinin düzgün taşlarından yapılan putlardır, 2 Evet, sizin nasibiniz onlardır! 2 Onlara dökmelik sunular döktünüz, 2 Tahıl sunuları sundunuz. 2 Bütün bunlardan sonra sizi cezalandırmaktan çekineceğimi mi sanıyorsunuz?'),
(2002104,68,23,57,7,'Yatağınızı ulu, yüksek dağa serdiniz, 2 Oraya bile kurban kesmeye gidiyorsunuz.'),
(2002105,68,23,57,8,'Kapılarınızın, sövelerinizin arkasına 2 İğrenç simgeler koydunuz. 2 Beni bıraktınız, 2 Yataklarınızı ardına kadar açıp içine girdiniz, 2 Oynaşlarınızla anlaşıp birlikte yatmaya can atıyorsunuz. 2 Onların çıplaklığını seyrettiniz.'),
(2002106,68,23,57,9,'Çeşit çeşit hoş kokular sürünüp ilah Moleke yağ götürdünüz. 2 Elçilerinizi ta uzaklara gönderdiniz, 2 Ölüler diyarına dek alçalttınız kendinizi.'),
(2002107,68,23,57,10,'Uzun yolculuklar sizi yorduğu halde, 2 ‹‹Pes ettim›› demediniz. 2 Gücünüzü tazeleyip durdunuz, 2 Bu nedenle de tükenmediniz.'),
(2002108,68,23,57,11,'‹‹Sizi kaygılandıran, korkutan kim ki, 2 Bana ihanet ediyor, beni anmıyor, 2 Yüreğinizde bana yer vermiyorsunuz? 2 Benden korkmamanızın nedeni 2 Uzun zamandır suskun kalışım değil mi?'),
(2002109,68,23,57,12,'Sözde doğruluğunuzu da yaptıklarınızı da ilan edeceğim, 2 Bunların size yararı olmayacak.'),
(2002110,68,23,57,13,'Feryat ettiğinizde 2 Topladığınız putlar sizi kurtarsın bakalım! 2 Rüzgar hepsini silip süpürecek, 2 Bir soluk onları alıp götürecek. 2 Bana sığınansa ülkeyi mülk edinecek, 2 Kutsal dağımı miras alacak.››'),
(2002111,68,23,57,14,'RAB diyor ki, 2 ‹‹Toprak yığıp yol yapın, 2 Halkımın yolundaki engelleri kaldırın.››'),
(2002112,68,23,57,15,'Yüce ve görkemli Olan, 2 Sonsuzlukta yaşayan, adı Kutsal Olan diyor ki, 2 ‹‹Yüksek ve kutsal yerde yaşadığım halde, 2 Alçakgönüllülerle, ezilenlerle birlikteyim. 2 Yüreklerini sevindirmek için ezilenlerin yanındayım.'),
(2002113,68,23,57,16,'Çünkü sonsuza dek davacı ve öfkeli olacak değilim, 2 Öyle olsa, yarattığım canlarla ruhlar karşımda dayanamazdı.'),
(2002114,68,23,57,17,'Haksız kazanç suçuna öfkelenip halkı cezalandırdım, 2 Öfkeyle yüzümü çevirdim onlardan. 2 Ne var ki, inatla kendi yollarından gittiler.'),
(2002115,68,23,57,18,'‹‹Yaptıklarını gördüm, 2 Ama onları iyileştirip yol göstereceğim. 2 Karşılık olarak hem onları 2 Hem de aralarında yas tutanları avutacağım.'),
(2002116,68,23,57,19,'Dudaklardan övgü sözleri döktüreceğim. 2 Uzaktakine de yakındakine de 2 Tam esenlik olsun›› diyor RAB, 2 ‹‹Hepsini iyileştireceğim.››'),
(2002117,68,23,57,20,'Ama kötüler çalkalanan deniz gibidir, 2 O deniz ki, rahat duramaz, suları çamur ve pislik savurur.'),
(2002118,68,23,57,21,'‹‹Kötülere esenlik yoktur›› diyor Tanrım.'),
(2002119,68,23,58,1,'‹‹Avaz avaz bağırın, çekinmeyin, 2 Sesinizi boru sesi gibi yükseltin; 2 Halkıma isyanlarını, 2 Yakup soyuna günahlarını bildirin.'),
(2002120,68,23,58,2,'Bana her gün danışıyor, 2 Yollarımı öğrenmekten zevk duyuyorlarmış! 2 Doğru davranan, 2 Tanrısının buyruğundan ayrılmayan bir ulusmuş gibi... 2 Benden adil yargılar diliyor, 2 Bana yaklaşmaktan zevk alıyorlarmış. yakın olmamı istiyorlarmış››.'),
(2002121,68,23,58,3,'Diyorlar ki, ‹Oruç tuttuğumuzu neden görmüyor, 2 İsteklerimizi denetlediğimizi neden farketmiyorsun?› ‹‹Bakın, oruç tuttuğunuz gün keyfinize bakıyor, 2 İşçilerinizi eziyorsunuz.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002122,68,23,58,4,'Orucunuz kavgayla, çekişmeyle, 2 Şiddetli yumruklaşmayla bitiyor. 2 Bugünkü gibi oruç tutmakla 2 Sesinizi yükseklere duyuramazsınız.'),
(2002123,68,23,58,5,'İstediğim oruç bu mu sanıyorsunuz? 2 İnsanın isteklerini denetlemesi gereken gün böyle mi olmalı? 2 Kamış gibi baş eğip çul ve kül üzerine mi oturmalı? 2 Siz buna mı oruç, RABbi hoşnut eden gün diyorsunuz?'),
(2002124,68,23,58,6,'Benim istediğim oruç, 2 Haksız yere zincire, boyunduruğa vurulanları salıvermek, 2 Ezilenleri özgürlüğe kavuşturmak, 2 Her türlü boyunduruğu kırmak değil mi?'),
(2002125,68,23,58,7,'Yiyeceğinizi açla paylaşmak değil mi? 2 Barınaksız yoksulları evinize alır, 2 Çıplak gördüğünüzü giydirir, 2 Yakınlarınızdan yardımınızı esirgemezseniz,'),
(2002126,68,23,58,8,'Işığınız tan gibi ağaracak, 2 Çabucak şifa bulacaksınız. 2 Doğruluğunuz önünüzden gidecek, 2 RABbin yüceliği artçınız olacak.'),
(2002127,68,23,58,9,'O zaman yardım çağrılarınızı RAB yanıtlayacak, 2 Feryat ettiğinizde, ‹İşte buradayım› diyecek. ‹‹Eğer boyunduruğa, başkalarını suçlamaya, 2 Kötücül konuşmalara son verirseniz,'),
(2002128,68,23,58,10,'Açlar uğruna kendinizi feda eder, 2 Yoksulların gereksinimini karşılarsanız, 2 Işığınız karanlıkta parlayacak, 2 Karanlığınız öğlen gibi ışıyacak.'),
(2002129,68,23,58,11,'RAB her zaman size yol gösterecek, 2 Kurak topraklarda sizi doyurup güçlendirecek. 2 İyi sulanmış bahçe gibi, 2 Tükenmez su kaynağı gibi olacaksınız.'),
(2002130,68,23,58,12,'Halkınız eski yıkıntıları onaracak, 2 Geçmiş kuşakların temelleri üzerine 2 Yeni yapılar dikeceksiniz. 2 ‹Duvardaki gedikleri onaran, 2 Sokakları oturulacak hale getiren› denecek sizlere.'),
(2002131,68,23,58,13,'‹‹Kutsal günümde dilediğinizi yapmaz, Şabat Gününü çiğnemezseniz, 2 Şabat Gününe ‹Zevkli›, 2 RABbin kutsal gününe ‹Onurlu› derseniz, 2 Kendi yolunuzdan gitmez, 2 Keyfinize bakmayıp boş konulara dalmaz, 2 O günü yüceltirseniz,'),
(2002132,68,23,58,14,'RAB''den zevk alırsınız. 2 O zaman sizi yeryüzünün yüksek yerlerine çıkarır, 2 Atanız Yakup''un mirasıyla doyururum.›› 2 Bunu söyleyen RAB''dir.'),
(2002133,68,23,59,1,'Bakın, RABbin eli kurtaramayacak kadar kısa, 2 Kulağı duyamayacak kadar sağır değildir.'),
(2002134,68,23,59,2,'Ama suçlarınız sizi Tanrınızdan ayırdı. 2 Günahlarınızdan ötürü Onun yüzünü göremez, 2 Sesinizi işittiremez oldunuz.'),
(2002135,68,23,59,3,'Çünkü elleriniz kanla, 2 Parmaklarınız suçla kirlendi. 2 Dudaklarınız yalan söyledi, 2 Diliniz kötülük mırıldanıyor.'),
(2002136,68,23,59,4,'Adaletle dava açan, 2 Davasını dürüstçe savunan yok. 2 Boş laflara güveniyor, yalan söylüyorlar. 2 Fesada gebe kalıp kötülük doğuruyorlar.'),
(2002137,68,23,59,5,'Engerek yumurtaları üzerinde kuluçkaya yatıyor, 2 Örümcek ağı dokuyorlar. 2 Onların yumurtalarından yiyen ölür, 2 Kırılan yumurtadan engerek yavrusu çıkar.'),
(2002138,68,23,59,6,'Dokudukları ağdan giysi olmaz, 2 Elleriyle yaptıklarıyla örtünemezler. 2 Eylemleri kötü eylemlerdir, 2 Elleri zorbalığın araçlarıdır.'),
(2002139,68,23,59,7,'Ayakları kötülüğe koşar, 2 Çekinmeden suçsuz kanı dökerler. 2 Akılları fikirleri hep kötülükte, 2 Şiddet ve yıkım var yollarında.'),
(2002140,68,23,59,8,'Esenlik yolunu bilmezler, 2 İzledikleri yolda adalet yoktur. 2 Kendilerine çarpık yollar yaptılar, 2 O yoldan gidenlerin hiçbiri esenlik nedir bilmez.'),
(2002141,68,23,59,9,'Diyorlar ki, ‹‹Bu yüzden adalet bizden uzak, 2 Doğruluk bize erişemiyor. 2 Işık bekliyoruz, yalnız karanlık var; 2 Parıltı bekliyor, koyu karanlıkta yürüyoruz.'),
(2002142,68,23,59,10,'Kör gibi duvarı el yordamıyla arıyor, 2 Yolumuzu bulmaya çalışıyoruz. 2 Öğle vakti alaca karanlıktaymış gibi tökezliyoruz, 2 Güçlüler arasında ölüler gibiyiz.'),
(2002143,68,23,59,11,'Hepimiz ayı gibi homurdanıyor, 2 Güvercin gibi inim inim inliyoruz. 2 Adalet bekliyoruz, ortada yok; 2 Kurtuluş bekliyoruz, bizden uzak.'),
(2002144,68,23,59,12,'Çünkü sana çok kez başkaldırdık, 2 Günahlarımız bize karşı tanıklık ediyor, 2 İsyanlarımız hep yanıbaşımızda. 2 Suçlarımızı kabul ediyoruz.'),
(2002145,68,23,59,13,'Başkaldırıp RABbi yadsıdık, 2 Tanrımızı izlemez olduk. 2 Zorbalık, isyan dolu sözler söyledik, 2 Yüreğimizde tasarladığımız yalanları mırıldandık.'),
(2002146,68,23,59,14,'Adalet püskürtüldü, doğruluk bizden uzak duruyor. 2 Çünkü gerçek, kent meydanında sendeleyip düştü, 2 Dürüstlük aramıza giremez oldu.'),
(2002147,68,23,59,15,'Hiçbir yerde gerçek yok, 2 Kötülükten çekinen soyuluyor!›› RAB olanları gördü ve adaletin yokluğuna üzüldü.'),
(2002148,68,23,59,16,'Kimsenin olmadığını gördü, 2 Aracılık edecek birinin olmadığına şaştı. 2 Kendi gücüyle kurtuluş sağladı, 2 Doğruluğu Ona destek oldu.'),
(2002149,68,23,59,17,'Doğruluğu göğüslük gibi kuşandı, 2 Kurtuluş miğferini başına taktı, 2 Öç giysisini giydi, 2 Gayreti kaftan gibi sarındı.'),
(2002150,68,23,59,18,'Herkese yaptıklarının karşılığını verecek. 2 Düşmanlarına öfkeyle, 2 Hasımlarına ve kıyı halklarına cezayla karşılık verecek.'),
(2002151,68,23,59,19,'Böylece batıdan doğuya kadar insanlar 2 RABbin adından ve yüceliğinden korkacak. 2 Çünkü düşman azgın bir ırmak gibi geldiğinde, 2 RABbin Ruhu onu kaçırtacak. ‹‹Soluk›› anlamına da gelir.'),
(2002152,68,23,59,20,'RAB diyor ki, ‹‹Kurtarıcı Siyona, 2 Yakup soyundan olup başkaldırmaktan vazgeçenlere gelecek.'),
(2002153,68,23,59,21,'Bana gelince, onlarla yapacağım antlaşma şudur: 2 Üzerindeki Ruhum, ağzına koyduğum sözler 2 Şimdiden sonsuza dek senin, çocuklarının, 2 Torunlarının ağzından düşmeyecek.››'),
(2002154,68,23,60,1,'‹‹Kalk, parla; 2 Çünkü Işığın geliyor, 2 RABbin yüceliği üzerine doğuyor.'),
(2002155,68,23,60,2,'Dünyayı karanlık, halkları koyu karanlık örtüyor; 2 Oysa RAB senin üzerine doğacak, 2 Yüceliği üzerinde görünecek.'),
(2002156,68,23,60,3,'Uluslar senin Işığına, 2 Krallar üzerine doğan aydınlığa gelecek.'),
(2002157,68,23,60,4,'‹‹Başını kaldır da çevrene bir bak, 2 Hepsi toplanmış sana geliyor. 2 Oğulların uzaktan geliyor, 2 Kızların kucakta taşınıyor.'),
(2002158,68,23,60,5,'Bunu görünce yüzün parlayacak, 2 Yüreğin heyecandan hızlı hızlı çarpacak; 2 Çünkü denizin zenginlikleri senin olacak, 2 Ulusların serveti sana akacak.'),
(2002159,68,23,60,6,'‹‹Deve sürüleri, Midyanın ve Efanın deve yavruları 2 Senin topraklarını dolduracak. 2 Bütün Saba halkı geliyor, 2 Altın ve günnük getiriyor, 2 RABbin erdemlerini ilan ediyorlar.'),
(2002160,68,23,60,7,'Kedarın bütün sürüleri sana gelecek, 2 Nevayotun koçları senin buyruğunda olacak, 2 Sunağımın üzerinde kabul edilen sunular olarak sunulacak. 2 Böylece görkemli tapınağımı daha görkemli kılacağım.'),
(2002161,68,23,60,8,'‹‹Nedir bunlar, bulut gibi, 2 Yuvalarına yaklaşan güvercinler gibi süzülüp gelenler?'),
(2002162,68,23,60,9,'Bana umut bağlayan kıyı halklarının, 2 Ticaret gemileri öncülüğünde 2 Senin çocuklarını altınlarıyla, gümüşleriyle birlikte 2 Tanrın RABbin adı için, İsrailin Kutsalı için 2 Uzaktan getiren gemileridir bunlar. 2 RAB seni görkemli kıldı.'),
(2002163,68,23,60,10,'‹‹Yabancılar senin surlarını onaracak, 2 Kralları sana hizmet edecek. 2 Öfkelendiğimde seni cezalandırdıysam da, 2 Kabul ettiğimde sana merhamet göstereceğim.'),
(2002164,68,23,60,11,'Kapıların hep açık duracak, 2 Ulusların serveti ve zafer alayları ardında yürütülen yenik krallar 2 Gece gündüz açık kalan bu kapılardan girsin diye.'),
(2002165,68,23,60,12,'Çünkü sana kulluk etmeyen ulus ya da krallık yok olacak, 2 Evet, o uluslar tam bir yıkıma uğrayacak.'),
(2002166,68,23,60,13,'‹‹Lübnanın görkemi olan çam, köknar ve selvi ağaçları, 2 Tapınağımı süslemek için hep birlikte sana taşınacak. 2 Ayak bastığım yeri görkemli kılacağım.'),
(2002167,68,23,60,14,'Seni ezenlerin çocukları 2 Gelip önünde eğilecekler; 2 Seni hor görenlerin hepsi, 2 ‹RABbin kenti, İsrailin Kutsalının Siyonu› 2 Diyerek ayaklarına kapanacaklar.'),
(2002168,68,23,60,15,'‹‹Kimsenin uğramadığı, terk edilmiş, 2 Nefret edilen bir yer olduğun halde 2 Seni sonsuz bir övünç kaynağı, 2 Bütün kuşakların sevinci kılacağım.'),
(2002169,68,23,60,16,'Uluslar ve krallıklar 2 Bir anne gibi seni emzirecekler. 2 O zaman bileceksin ki, seni kurtaran RAB, 2 Seni fidyeyle kurtaran, Yakupun Güçlüsü benim.'),
(2002170,68,23,60,17,'Sana tunç yerine altın, 2 Demir yerine gümüş, ağaç yerine tunç, 2 Taş yerine demir getireceğim. 2 Barışı yöneticin, doğruluğu önderin yapacağım.'),
(2002171,68,23,60,18,'Ülkenden şiddet, sınır boylarından 2 Soygun ve yıkım haberleri duyulmayacak artık. 2 Surlarına Kurtuluş, kapılarına Övgü adını vereceksin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002172,68,23,60,19,'‹‹Gündüz ışığın güneş olmayacak artık, 2 Ay da aydınlatmayacak seni; 2 Çünkü RAB sonsuz ışığın, 2 Tanrın görkemin olacak.'),
(2002173,68,23,60,20,'Artık güneşin batmayacak, ayın çekilmeyecek, 2 Çünkü RAB sonsuz ışığın olacak, 2 Sona erecek yas günlerin.'),
(2002174,68,23,60,21,'Halkının hepsi doğru kişiler olacak; 2 El emeğim, görkemimi göstermek için diktiğim fidan, 2 Ülkeyi sonsuza dek mülk edinecek.'),
(2002175,68,23,60,22,'En küçük ailen bini bulacak, 2 Sayıca en az olanı koca bir ulus olacak. 2 Ben RAB, zamanı gelince bunu hızlandıracağım.››'),
(2002176,68,23,61,1,'Egemen RABbin Ruhu üzerimdedir. 2 Çünkü O beni yoksullara müjde iletmek için meshetti. 2 Yüreği ezik olanların yaralarını sarmak için, 2 Tutsaklara serbest bırakılacaklarını, 2 Zindanlarda bulunanlara kurtulacaklarını, 2 RABbin lütuf yılını, 2 Tanrımızın öç alacağı günü ilan etmek, 2 Yas tutanların hepsini avutmak, 2 Siyonda yas tutanlara yardım sağlamak 2 -Kül yerine çelenk, 2 Yas yerine sevinç yağı, 2 Çaresizlik ruhu yerine 2 Onlara övgü giysisini vermek- için 2 RAB beni gönderdi. 2 Öyle ki, RABbin görkemini yansıtmak için, 2 Onlara ‹‹RABbin diktiği doğruluk ağaçları›› densin.'),
(2002177,68,23,61,4,'O zaman eski yıkıntıları yeniden inşa edecek, 2 Çoktan viraneye dönmüş yerleri yeniden kuracak, 2 Kuşaklar boyu yıkık kalmış kentleri onaracaklar.'),
(2002178,68,23,61,5,'Yabancılar sürülerinizi güdecek, 2 Irgatınız, bağcınız olacaklar.'),
(2002179,68,23,61,6,'Sizlerse RABbin kâhinleri, 2 Tanrımızın görevlileri diye çağrılacaksınız. 2 Ulusların servetiyle beslenecek, 2 Zenginlikleriyle övüneceksiniz.'),
(2002180,68,23,61,7,'Utanç yerine iki kat onur bulacaksınız, 2 Aşağılanma yerine payınızla sevineceksiniz, 2 Böylece ülkenizde iki kat mülk edineceksiniz; 2 Sevinciniz sonsuz olacak.'),
(2002181,68,23,61,8,'‹‹Çünkü ben RAB adaleti severim, 2 Nefret ederim soygun ve haksızlıktan. 2 Sözümde durup hak ettiklerini verecek, 2 Onlarla ebedi bir antlaşma yapacağım. yakmalık sunulardan››.'),
(2002182,68,23,61,9,'Soylarından gelenler uluslar arasında, 2 Torunları halklar arasında tanınacak. 2 Onları gören herkes 2 RABbin kutsadığı soy olduklarını anlayacak.››'),
(2002183,68,23,61,10,'RABde büyük sevinç bulacağım, 2 Tanrımla yüreğim coşacak. 2 Çünkü çelenkle süslenmiş güvey gibi, 2 Takılarını kuşanmış gelin gibi, 2 Bana kurtuluş giysisini giydirdi, 2 Beni doğruluk kaftanıyla örttü.'),
(2002184,68,23,61,11,'Toprak filizlerini nasıl çıkartır, 2 Bahçe ekilen tohumları nasıl yetiştirirse, 2 Egemen RAB de doğruluk ve övgüyü 2 Bütün ulusların önünde öyle yetiştirecek.'),
(2002185,68,23,62,1,'Zaferi ışık gibi parlayıncaya, 2 Kurtuluşu meşale gibi yanıncaya dek 2 Siyon uğruna susmayacak, 2 Yeruşalim uğruna sessiz kalmayacağım.'),
(2002186,68,23,62,2,'Uluslar senin zaferini, 2 Bütün krallar görkemini görecek. 2 RABbin kendi ağzıyla belirlediği yeni bir adla anılacaksın.'),
(2002187,68,23,62,3,'RABbin elinde güzellik tacı, 2 Tanrının elinde krallık sarığı olacaksın.'),
(2002188,68,23,62,4,'Artık sana ‹‹Terk edilmiş››, 2 Ülkene ‹‹Virane›› denmeyecek; 2 Bunun yerine sana ‹‹Sevdiğim››, 2 Ülkene ‹‹Evli›› denecek. 2 Çünkü RAB seni seviyor, 2 Ülken de evli sayılacak.'),
(2002189,68,23,62,5,'Bir delikanlı bir kızla nasıl evlenirse, 2 Oğulların da seninle öyle evlenecek. 2 Güvey gelinle nasıl sevinirse, 2 Tanrın da seninle öyle sevinecek. veren seninle evlenecek››.'),
(2002190,68,23,62,6,'Ey Yeruşalim, surlarına bekçiler diktim, 2 Gece gündüz hiç susmayacaklar. 2 Ey RABbe sözünü anımsatanlar, Yeruşalimi pekiştirene, 2 Onu yeryüzünün övüncü kılana dek 2 Durup dinlenmeden RABbe yakarın, Ona rahat vermeyin.'),
(2002191,68,23,62,8,'RAB sağ elini, güçlü kolunu kaldırıp ant içti: 2 ‹‹Tahılını bir daha düşmanlarına yedirmeyeceğim, 2 Emek verdiğin yeni şarabı yabancılar içmeyecek.'),
(2002192,68,23,62,9,'Tahılı devşiren yiyecek 2 Ve RABbe övgüler sunacak. 2 Üzümü toplayan, 2 Şarabını kutsal avlularımda içecek.››'),
(2002193,68,23,62,10,'Geçin, geçin kent kapılarından! 2 Halkın yolunu açın! 2 Toprak yığıp yol yapın, 2 Taşları ayıklayın, uluslar için sancak dikin!'),
(2002194,68,23,62,11,'RAB çağrısını dünyanın dört bucağına duyurdu: 2 ‹‹Siyon kızına, ‹İşte kurtuluşun geliyor› deyin, 2 ‹Ücreti kendisiyle birlikte, ödülü önündedir.› ››'),
(2002195,68,23,62,12,'Siyon halkına, ‹‹RAB''bin fidyeyle kurtardığı kutsal halk›› diyecekler. 2 Ve sen Yeruşalim, 2 ‹‹Aranan, terk edilmemiş kent›› diye anılacaksın.'),
(2002196,68,23,63,1,'Edomdanfç, Bosradanfç 2 Al giysiler içinde bu gelen kim? 2 Göz kamaştırıcı giysiler içinde, 2 Büyük güçle yürüyen kim? 2 ‹‹O benim! Adaleti duyuran, 2 Kurtarmaya gücü olan.›› kentlerinden olan Bosra ise ‹‹Bağbozumu›› sözcüğünü çağrıştırıyor.'),
(2002197,68,23,63,2,'Giysilerin neden kırmızı? 2 Üstün başın neden çukurda üzüm çiğneyen biri gibi kızıla bulanmış?'),
(2002198,68,23,63,3,'‹‹Çukurda üzümü tek başıma çiğnedim, 2 Yanımda halklardan kimse yoktu. 2 Öfkeyle çiğnedim onları, 2 Gazapla ayaklarımın altına aldım. 2 Kanları giysilerime sıçradı, bütün elbisemi kirletti.'),
(2002199,68,23,63,4,'Çünkü öç alma günü yüreğimdeydi, 2 Halkımı kurtaracağım yıl gelmişti.'),
(2002200,68,23,63,5,'Baktım, yardım edecek kimse yoktu, 2 Destek verecek kimsenin olmayışına şaştım; 2 Gücüm kurtuluş sağladı, 2 Gazabım bana destek oldu.'),
(2002201,68,23,63,6,'Öfkeyle halkları çiğnedim, 2 Onları gazapla sarhoş ettim, 2 Yere akıttım kanlarını.››'),
(2002202,68,23,63,7,'Şefkati ve iyiliği uyarınca 2 Bizim için yaptıklarından, evet, 2 İsrail halkı için yaptığı bütün iyiliklerinden ötürü 2 RABbin iyiliklerini ve övülesi işlerini anacağım.'),
(2002203,68,23,63,8,'RAB dedi ki, ‹‹Onlar kuşkusuz benim halkım, 2 Beni aldatmayacak çocuklardır.›› 2 Böylece onların Kurtarıcısı oldu.'),
(2002204,68,23,63,9,'Sıkıntı çektiklerinde O da sıkıntı çekti. 2 Huzurundan çıkan melek onları kurtardı. 2 Sevgisi ve merhametinden ötürü onları kurtardı, 2 Geçmişte onları sürekli yüklenip taşıdı.'),
(2002205,68,23,63,10,'Ama başkaldırıp Onun Kutsal Ruhunu incittiler. 2 O da düşmanları olup onlara karşı savaştı.'),
(2002206,68,23,63,11,'Sonra halkı eski günleri, 2 Musanın dönemini anımsadı. 2 ‹‹Çobanlarıyla birlikte onları denizden geçiren, 2 Kutsal Ruhunu aralarına yerleştiren, 2 Görkemli gücüyle Musanın sağında yol alan, 2 Sonsuz onur kazanmak için önlerinde suları yaran, 2 Bir at nasıl tökezlemeden kırdan geçerse 2 Onları deniz yatağından öyle geçiren RAB nerede?›› 2 Diye sordular.'),
(2002207,68,23,63,14,'Ovaya götürülen sürü gibi 2 RABbin Ruhu onları rahata kavuşturdu. 2 İşte adını onurlandırmak için 2 Halkına böyle yol gösterdi.'),
(2002208,68,23,63,15,'Ya RAB, gökten bak, 2 Kutsal, görkemli ve yüce yerinden bizi gör! 2 Gayretin, gücün nerede? 2 Gönlündeki özlem ve merhameti 2 Bizden esirgedin.'),
(2002209,68,23,63,16,'Babamız sensin. 2 İbrahim bizi tanımasa da, 2 İsrail bizi kabul etmese de, 2 Babamızsın, ya RAB, 2 Ezelden beri adın ‹‹Kurtarıcımız››dır.'),
(2002210,68,23,63,17,'Ya RAB, neden bizi yolundan saptırıyor, 2 İnatçı kılıyor, 2 Senden korkmamızı engelliyorsun? 2 Kulların uğruna, 2 Mirasın olan oymakların uğruna geri dön.'),
(2002211,68,23,63,18,'Kutsal halkın kısa süre tapınağına sahip oldu, 2 Ama düşmanlarımız onu çiğnedi.'),
(2002212,68,23,63,19,'Öteden beri yönetmediğin, 2 Sana ait olmayan bir halk gibi olduk.'),
(2002213,68,23,64,1,'Ya RAB, adını düşmanlarına duyurmak için 2 Keşke gökleri yarıp insen! 2 Dağlar önünde sarsılsa! 2 Gelişin, ateşin çalıları tutuşturmasına, 2 Suyu kaynatmasına benzese! 2 Uluslar senin önünde titrese!'),
(2002214,68,23,64,3,'Beklemediğimiz olağanüstü işler yaparak 2 Yeryüzüne indin, dağlar önünde sarsıldı.'),
(2002215,68,23,64,4,'Çünkü kendisine umut bağlayanlar için 2 Etkin olan tek Tanrı sensin; 2 Senden başkasını hiçbir zaman hiç kimse işitmedi, 2 Hiçbir kulak duymadı, hiçbir göz görmedi.'),
(2002216,68,23,64,5,'Doğru olanı sevinçle yapanların, 2 Senin yollarından yürüyüp seni unutmayanların yardımına koşarsın. 2 Ama onlara karşı uzun süre günah işlediğimizde öfkelendin. 2 Nasıl kurtuluruz?'),
(2002217,68,23,64,6,'Hepimiz murdar olanlara benzedik, 2 Bütün doğru işlerimiz kirli âdet bezi gibi. 2 Yaprak gibi soluyoruz, 2 Suçlarımız rüzgar gibi sürükleyip götürüyor bizi.'),
(2002218,68,23,64,7,'Adınla seni çağıran, sana tutunmak için çaba gösteren yok; 2 Çünkü bizden yüz çevirdin, 2 Suçlarımız yüzünden bizi tükettin.'),
(2002219,68,23,64,8,'Yine de Babamız sensin, ya RAB, 2 Biz kiliz, sen çömlekçisin. 2 Hepimiz senin ellerinin eseriyiz.'),
(2002220,68,23,64,9,'Ya RAB, fazla öfkelenme, 2 Suçlarımızı sonsuza dek anma. 2 Lütfen bak bize, hepimiz senin halkınız.'),
(2002221,68,23,64,10,'Kutsal kentlerin çölleşti, 2 Siyon çöl oldu, 2 Yeruşalim viraneye döndü.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002222,68,23,64,11,'Atalarımızın sana övgü sunduğu 2 Kutsal ve görkemli tapınağımız yandı, 2 Değer verdiğimiz her yer yıkıntıya döndü.'),
(2002223,68,23,64,12,'Bunlara karşın, ya RAB, 2 Hâlâ kendini tutacak mısın, 2 Suskun kalıp bize alabildiğine eziyet çektirecek misin?'),
(2002224,68,23,65,1,'‹‹Beni sormayanlara göründüm, 2 Aramayanlar beni buldu. 2 Adımla anılmayan bir ulusa, 2 ‹Buradayım, buradayım› dedim.'),
(2002225,68,23,65,2,'Kötü yolda yürüyen, 2 Kendi tasarılarının ardınca giden 2 Asi bir halka 2 Bütün gün ellerimi uzatıp durdum.'),
(2002226,68,23,65,3,'O halk ki, bahçelerde kurban keserek, 2 Tuğlalar üzerinde buhur yakarak 2 Gözümün içine baka baka boyuna öfkelendirir beni.'),
(2002227,68,23,65,4,'Mezarlıkta oturur, 2 Gizli yerlerde geceler, 2 Domuz eti yerler; 2 Kaplarında haram et var.'),
(2002228,68,23,65,5,'Birbirlerine, ‹Uzak dur, yaklaşma› derler, 2 ‹Çünkü ben senden daha kutsalım.› 2 Böyleleri burnumda duman, 2 Bütün gün yanan ateştir.'),
(2002229,68,23,65,6,'‹‹Bakın, yanıt önümde yazılı duruyor. 2 Susmayacak, suçlarının karşılığını vereceğim. 2 Onların da atalarının da suçlarının cezasını 2 Başlarına getireceğim›› diyor RAB. 2 ‹‹Çünkü dağların üzerinde buhur yaktılar, 2 Tepelerin üzerinde beni aşağıladılar. 2 Bu nedenle eskiden yaptıklarının karşılığını 2 Başlarına getireceğim.››'),
(2002230,68,23,65,8,'RAB diyor ki, ‹‹Taneleri sulu salkımı görünce, 2 Halk, ‹Salkımı yok etmeyin, bereket onda› diyor. 2 Kullarımın hatırı için ben de öyle yapacağım, 2 Onların hepsini yok etmeyeceğim.'),
(2002231,68,23,65,9,'Yakup soyunu sürdürecek, 2 Dağlarımı miras alacak olanları 2 Yahuda soyuna bırakacağım. 2 Seçtiklerim oraları miras alacak, 2 Kullarım orada yaşayacak.'),
(2002232,68,23,65,10,'Şaron, bana yönelen halkımın sürülerine ağıl, 2 Akor Vadisi sığırlarına barınak olacak.'),
(2002233,68,23,65,11,'‹‹Ama sizler, RABbi terk edenler, 2 Kutsal dağımı unutanlar, 2 Talih ilahına sofra kuranlar, 2 Kısmet ilahına karışık şarap sunanlar,'),
(2002234,68,23,65,12,'Ben de sizi kılıca kısmet edeceğim, 2 Boğazlanmak üzere eğileceksiniz hepiniz. 2 Çünkü çağırdığımda yanıt vermediniz, 2 Konuştuğumda dinlemediniz; 2 Gözümde kötü olanı yaptınız, 2 Hoşlanmadığımı seçtiniz.››'),
(2002235,68,23,65,13,'Bu yüzden Egemen RAB diyor ki, 2 ‹‹Bakın, kullarım yemek yiyecek, 2 Ama siz aç kalacaksınız. 2 Kullarım içecek, 2 Ama siz susuz kalacaksınız. 2 Kullarım sevinecek, 2 Ama sizin yüzünüz kızaracak.'),
(2002236,68,23,65,14,'Kullarım mutluluk içinde ezgiler söyleyecek, 2 Ama siz yürek acısından feryat edecek, 2 Ezik bir ruhla haykıracaksınız.'),
(2002237,68,23,65,15,'Adınız seçtiklerimin ağzında ancak lanet olarak kalacak. 2 Egemen RAB sizi öldürecek, 2 Ama kullarına başka bir ad verecek.'),
(2002238,68,23,65,16,'Öyle ki, ülkede kim bereket istese 2 Sadık Tanrıdan isteyecek; 2 Ülkede kim ant içse, 2 Sadık Tanrı üzerine ant içecek. 2 Çünkü geçmiş sıkıntılar unutulup 2 Gözümden saklanacak.››'),
(2002239,68,23,65,17,'‹‹Çünkü bakın, yeni bir yeryüzü, 2 Yeni bir gök yaratmak üzereyim; 2 Geçmiştekiler anılmayacak, akla bile gelmeyecek.'),
(2002240,68,23,65,18,'Yaratacaklarımla sonsuza dek sevinip coşun; 2 Çünkü Yeruşalimi coşku, 2 Halkını sevinç kaynağı olarak yaratacağım.'),
(2002241,68,23,65,19,'Yeruşalim için sevinecek, 2 Halkım için coşacağım. 2 Orada ağlayış ve feryat duyulmayacak artık.'),
(2002242,68,23,65,20,'Orada birkaç gün yaşayıp ölen bebekler olmayacak, 2 Yaşını başını almadan kimse ölümü tatmayacak. 2 Yüz yaşında ölen genç, 2 Yüz yaşına basmayan kişi lanetli sayılacak.'),
(2002243,68,23,65,21,'Evler yapıp içlerinde yaşayacak, 2 Bağlar dikip meyvesini yiyecekler.'),
(2002244,68,23,65,22,'Yaptıkları evlerde başkası oturmayacak, 2 Diktikleri bağın meyvesini başkası yemeyecek. 2 Çünkü halkım ağaçlar gibi uzun yaşayacak, 2 Seçtiklerim, elleriyle ürettiklerinin tadını çıkaracaklar.'),
(2002245,68,23,65,23,'Emek vermeyecekler boş yere, 2 Felakete uğrayan çocuklar doğurmayacaklar. 2 Çünkü kendileri de çocukları da 2 RABbin kutsadığı soy olacak.'),
(2002246,68,23,65,24,'Onlar bana yakarmadan yanıt verecek, 2 Daha konuşurlarken işiteceğim onları.'),
(2002247,68,23,65,25,'Kurtla kuzu birlikte otlayacak, 2 Aslan sığır gibi saman yiyecek. 2 Yılanın yiyeceğiyse toprak olacak. 2 Kutsal dağımın hiçbir yerinde 2 Kimse zarar vermeyecek, yok etmeyecek.›› 2 Böyle diyor RAB.'),
(2002248,68,23,66,1,'RAB diyor ki, 2 ‹‹Gökler tahtım, 2 Yeryüzü ayaklarımın taburesidir. 2 Nerede benim için yapacağınız ev, 2 Neresi dinleneceğim yer?'),
(2002249,68,23,66,2,'Çünkü bütün bunları ellerim yaptı, 2 Hepsi böylece var oldu›› diyor RAB. ‹‹Ancak ben alçakgönüllüye, ruhu ezik olana, 2 Sözümden titreyen kişiye değer veririm.'),
(2002250,68,23,66,3,'Sığır boğazlayan, adam öldüren gibidir, 2 Davar kurban eden, köpek boynu kıran, 2 Tahıl sunusu getiren, domuz kanı sunan, 2 Anma sunusu olarak günnük yakan, putperest gibidir. 2 Evet, bunlar kendi yollarını seçtiler, 2 Yaptıkları iğrençliklerden hoşlanıyorlar.'),
(2002251,68,23,66,4,'Ben de onlar için yıkımı seçecek, 2 Korktuklarını başlarına getireceğim. 2 Çünkü çağırdığımda yanıt veren olmadı, 2 Konuştuğumda dinlemediler, 2 Gözümde kötü olanı yaptılar, 2 Hoşlanmadığımı seçtiler.››'),
(2002252,68,23,66,5,'RABbin sözünden titreyenler, 2 Kulak verin Onun söylediklerine: 2 ‹‹Sizden nefret eden, 2 Adımdan ötürü sizi dışlayan kardeşleriniz, 2 ‹RAB yüceltilsin de sevincinizi görelim!› diyorlar. 2 Utandırılacak olan onlardır.'),
(2002253,68,23,66,6,'Kentten gürültülü sesler, 2 Tapınaktan bir ses yükseliyor! 2 Düşmanlarına hak ettikleri karşılığı veren 2 RABbin sesidir bu.'),
(2002254,68,23,66,7,'‹‹Doğum sancısı çekmeden doğurdu, 2 Sancısı tutmadan bir erkek çocuk doğurdu.'),
(2002255,68,23,66,8,'Kim böyle bir şey duydu? 2 Kim böyle şeyler gördü? 2 Bir ülke bir günde doğar mı, 2 Bir anda doğar mı bir ulus? 2 Ama Siyon, ağrısı tutar tutmaz çocuklarını doğurdu.'),
(2002256,68,23,66,9,'Doğum anına dek getiririm de 2 Doğuracak gücü vermez miyim?›› diyor RAB. 2 ‹‹Doğuracak güç veren ben, rahmi kapatır mıyım?›› diyor Tanrın.'),
(2002257,68,23,66,10,'‹‹Yeruşalimle birlikte sevinin, 2 Onu sevenler, hepiniz onun için coşun, 2 Yeruşalim için yas tutanlar, onunla sevinçle coşun.'),
(2002258,68,23,66,11,'Öyle ki, onun avutucu memelerini emip doyasınız, 2 Kana kana içip 2 Onun yüce bolluğundan zevk alasınız.››'),
(2002259,68,23,66,12,'Çünkü RAB diyor ki, 2 ‹‹Bakın, esenliği bir ırmak gibi, 2 Ulusların servetini taşkın bir ırmak gibi ona akıtacağım. 2 Ondan beslenecek, kucakta taşınacak, 2 Dizleri üzerinde sallanacaksınız.'),
(2002260,68,23,66,13,'Çocuğunu avutan bir anne gibi avutacağım sizi, 2 Yeruşalimde avuntu bulacaksınız.'),
(2002261,68,23,66,14,'Bunları gördüğünüzde yüreğiniz sevinecek, 2 Bedenleriniz körpe ot gibi tazelenecek. 2 Herkes bilecek ki, RABbin koruyucu eli kullarının, 2 Gazabı ise düşmanlarının üzerindedir.››'),
(2002262,68,23,66,15,'Bakın, RAB ateşle geliyor, 2 Savaş arabaları kasırga gibi. 2 Şiddetli öfkesini, 2 Azarını alev alev dökmek üzere.'),
(2002263,68,23,66,16,'Çünkü O bütün insanlığı ateş ve kılıçla yargılayacak, 2 Pek çok kişiyi öldürecek.'),
(2002264,68,23,66,17,'‹‹Bahçelere girmek için kendilerini arıtıp kutsayanlar, domuz, fare ve öteki iğrenç hayvanların etini yiyenlerin ortasında duranı izleyenler hep birlikte yok olacaklar›› diyor RAB,'),
(2002265,68,23,66,18,'‹‹Çünkü ben onların eylemlerini de düşüncelerini de bilirim. Bütün ulusları ve dilleri bir araya toplayacağım an geliyor; gelip yüceliğimi görecekler.'),
(2002266,68,23,66,19,'‹‹Aralarına bir belirti koyacağım. Onlardan kaçıp kurtulanları uluslara, Tarşişe, Pûla, Luda -yay gerenlere- Tuvala, Yâvana, ünümü duymamış, yüceliğimi görmemiş uzak kıyı halklarına göndereceğim. Uluslar arasında yüceliğimi ilan edecekler.'),
(2002267,68,23,66,20,'İsrailoğulları tahıl sunularını pak kaplar içinde RABbin Tapınağına nasıl getiriyorsa, onlar da bütün kardeşlerinizi uluslardan atlarla, savaş arabalarıyla, at arabalarıyla, katırlarla, develerle kutsal dağıma, Yeruşalime, RABbe sunu olarak getirecekler.›› Böyle diyor RAB.'),
(2002268,68,23,66,21,'‹‹Onların arasından kimilerini kâhin ve Levili olarak seçeceğim›› diyor RAB.'),
(2002269,68,23,66,22,'‹‹Çünkü yaratacağım yeni yer ve gök önümde nasıl duracaksa, soyunuz ve adınız da öyle duracak›› diyor RAB.'),
(2002270,68,23,66,23,'‹‹Yeni Aydan Yeni Aya, Şabat Gününden Şabat Gününe bütün insanlar önüme gelip bana tapınacaklar›› diyor RAB.'),
(2002271,68,23,66,24,'‹‹Dışarı çıktıklarında bana başkaldırmış olanların cesetlerini görecekler. Öylelerini kemiren kurt ölmez, yakan ateş sönmez. Bütün insanlar onlardan iğrenecek.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002272,68,24,1,1,'Benyamin topraklarında Anatot Kentindeki kâhinlerden Hilkiya oğlu Yeremyanın sözleri.'),
(2002273,68,24,1,2,'RAB, Yahuda Kralı Amon oğlu Yoşiyanın krallığının on üçüncü yılında Yeremyaya seslendi.'),
(2002274,68,24,1,3,'RABbin Yeremyaya seslenişi Yahuda Kralı Yoşiya oğlu Yehoyakimin döneminden, Yahuda Kralı Yoşiya oğlu Sidkiyanın krallığının on birinci yılının beşinci ayına dek, yani Yeruşalim halkının sürgüne gönderilmesine dek sürdü.'),
(2002275,68,24,1,4,'RAB bana şöyle seslendi:'),
(2002276,68,24,1,5,'‹‹Ana rahminde sana biçim vermeden önce tanıdım seni. 2 Doğmadan önce seni ayırdım, 2 Uluslara peygamber atadım.››'),
(2002277,68,24,1,6,'Bunun üzerine, ‹‹Ah, Egemen RAB, konuşmayı bilmiyorum, çünkü gencim›› diye karşı çıktım.'),
(2002278,68,24,1,7,'RAB, ‹‹ ‹Gencim› deme›› dedi, ‹‹Seni göndereceğim herkese gidecek, sana buyuracağım her şeyi söyleyeceksin.'),
(2002279,68,24,1,8,'Onlardan korkma, çünkü seni kurtarmak için ben seninleyim.›› Böyle diyor RAB.'),
(2002280,68,24,1,9,'Sonra RAB elini uzatıp ağzıma dokundu, ‹‹İşte sözlerimi ağzına koydum›› dedi,'),
(2002281,68,24,1,10,'‹‹Bak, ulusların ve ülkelerin kökünden sökülmesi, yıkılıp yok olması, yerle bir edilmesi, kurulup dikilmesi için bugün sana yetki verdim.››'),
(2002282,68,24,1,11,'RAB, ‹‹Yeremya, ne görüyorsun?›› diye seslendi. ‹‹Bir badem dalı görüyorum›› diye yanıtladım.'),
(2002283,68,24,1,12,'RAB, ‹‹Doğru gördün›› dedi, ‹‹Çünkü sözümü yerine getirmek için gözlemekteyim.›› birbirini çağrıştırıyor.'),
(2002284,68,24,1,13,'RAB yine, ‹‹Ne görüyorsun?›› diye seslendi. ‹‹Kuzeyden bu yöne bakan, kaynayan bir kazan görüyorum›› diye yanıtladım.'),
(2002285,68,24,1,14,'RAB şöyle dedi: ‹‹Ülkede yaşayanların tümü üzerine 2 Kuzeyden felaket salıverilecek. birbirini çağrıştırıyor.'),
(2002286,68,24,1,15,'Çünkü kuzey krallıklarının bütün halklarını çağırıyorum›› diyor RAB. 2 ‹‹Kralları gelip Yeruşalim surlarında, 2 Bütün Yahuda kentlerinin karşısında, 2 Yeruşalimin kapı girişlerinde 2 Tahtlarını kuracaklar.'),
(2002287,68,24,1,16,'Yaptıkları kötülükten ötürü 2 Halkımın cezasını bildireceğim: 2 Beni bıraktılar, 2 Başka ilahlara buhur yakıp 2 Elleriyle yaptıklarına tapındılar.'),
(2002288,68,24,1,17,'‹‹Sen kalk, hazırlan! Sana buyuracağım her şeyi onlara söyle. Onlardan yılma! Yoksa onların önünde ben seni yıldırırım.'),
(2002289,68,24,1,18,'İşte, bütün ülkeye -Yahuda krallarına, önderlerine, kâhinlerine, ülke halkına- karşı bugün seni surlu bir kent, demir bir direk, tunç bir duvar kıldım.'),
(2002290,68,24,1,19,'Sana savaş açacak, ama seni yenemeyecekler. Çünkü seni kurtarmak için ben seninleyim.›› Böyle diyor RAB.'),
(2002291,68,24,2,1,'RAB bana şöyle seslendi:'),
(2002292,68,24,2,2,'‹‹Git, şunları Yeruşalim halkına duyur. RAB diyor ki, ‹‹ ‹Gençliğindeki bağlılığını, 2 Gelinliğindeki sevgini, 2 Çölde, ekilmemiş toprakta 2 Beni nasıl izlediğini anımsıyorum.'),
(2002293,68,24,2,3,'İsrail RAB için kutsal bir halk, 2 Hasadının ilk ürünüydü. 2 Onu yeren herkes suçlu sayılır, 2 Başına felaket gelirdi› ›› diyor RAB.'),
(2002294,68,24,2,4,'RABbin sözünü dinleyin, 2 Ey Yakup soyu, 2 İsrailin bütün boyları!'),
(2002295,68,24,2,5,'RAB diyor ki, 2 ‹‹Atalarınız bende ne haksızlık buldular da 2 Benden uzaklaştılar? 2 Değersiz putları izleyerek 2 Kendileri de değersiz oldular.'),
(2002296,68,24,2,6,'‹Mısırdan bizi çıkaran, 2 Çölde, çukurlarla dolu çorak toprakta, 2 Koyu karanlıkta kalan kurak toprakta, 2 Kimsenin geçmediği, 2 Kimsenin yaşamadığı toprakta 2 Bize yol gösteren RAB nerede?› diye sormadılar.'),
(2002297,68,24,2,7,'Meyvesini, en iyi ürününü yiyesiniz diye 2 Sizi verimli bir ülkeye getirdim. 2 Oysa siz gelir gelmez ülkemi kirlettiniz, 2 Mülkümü iğrenç bir yere çevirdiniz.'),
(2002298,68,24,2,8,'Kâhinler, ‹RAB nerede?› diye sormadılar, 2 Kutsal Yasa uzmanları beni tanımadılar, 2 Yöneticiler bana başkaldırdılar; 2 Peygamberler Baal adına peygamberlik edip 2 İşe yaramaz putların ardınca gittiler.'),
(2002299,68,24,2,9,'‹‹Bu yüzden sizden yine davacı olacağım›› diyor RAB, 2 ‹‹Torunlarınızdan da davacı olacağım.'),
(2002300,68,24,2,10,'Gidin de Kittim kıyılarına bakın! 2 Kedarfç ülkesine adam gönderip iyice inceleyin, 2 Hiç böyle bir şey oldu mu, olmadı mı görün. ülkeleri temsil ediyor.'),
(2002301,68,24,2,11,'Hiçbir ulus ilahlarını değiştirdi mi? 2 -Ki onlar zaten tanrı değildirler- 2 Ama benim halkım görkemini 2 İşe yaramaz putlara değişti. ‹‹Görkemimi››.'),
(2002302,68,24,2,12,'Ey gökler, şaşın buna, 2 Tir tir titreyin, şaşakalın›› diyor RAB.'),
(2002303,68,24,2,13,'‹‹Çünkü halkım iki kötülük yaptı: 2 Beni, diri suların pınarını bıraktı, 2 Kendilerine sarnıçlar, 2 Su tutmayan çatlak sarnıçlar kazdılar.'),
(2002304,68,24,2,14,'İsrail uşak mı? 2 Köle olarak mı doğdu? 2 Öyleyse neden gümbür gümbür kükreyen 2 Genç aslanlara av oldu? 2 Ülkeyi viraneye çevirdiler, 2 Kentler yerle bir edildi, kimsesiz bırakıldı!'),
(2002305,68,24,2,16,'Nof ve Tahpanhes halkı 2 Kafanı kırdı.'),
(2002306,68,24,2,17,'Seni yolda yürüten Tanrın RABbi bırakmakla 2 Başına bunları getirdin.'),
(2002307,68,24,2,18,'Şimdi Şihor suyundan içmek için 2 Mısıra gitmek size yarar sağlar mı? 2 Fırat suyundan içmek için 2 Asura gitmek size ne sağlar?'),
(2002308,68,24,2,19,'Seni kendi kötülüğün yola getirecek, 2 Dönekliğin seni paylayacak. 2 Tanrın RABbi bırakmanın, 2 Benden korkmamanın 2 Ne kadar kötü, ne kadar acı olduğunu gör de anla.›› 2 Her Şeye Egemen Egemen RAB böyle diyor.'),
(2002309,68,24,2,20,'‹‹Boyunduruğunu çok önce kırdın, 2 Bağlarını kopardın. 2 ‹Kulluk etmeyeceğim› dedin. 2 Gerçekten de her yüksek tepede, 2 Her bol yapraklı ağacın altında 2 Fahişe gibi yatıp kalktın.'),
(2002310,68,24,2,21,'Oysa ben seni en iyi cinsten 2 Seçme bir asma olarak dikmiştim. 2 Nasıl oldu da yozlaşıp yabanıl asmaya döndün?'),
(2002311,68,24,2,22,'Çamaşır sodasıyla yıkansan, 2 Bol kül suyu kullansan bile, 2 Suçun önümde yine leke gibi duruyor›› 2 Diyor Egemen RAB.'),
(2002312,68,24,2,23,'‹‹Öyleyken nasıl, ‹Ben kirlenmedim, 2 Baalları izlemedim› diyebilirsin? 2 Vadide nasıl davrandığına bak da 2 Ne yaptığını anla. 2 Sen orada burada dolaşan 2 Ayağı tez bir dişi devesin.'),
(2002313,68,24,2,24,'Kösnüyüp havayı koklayan 2 Kıra alışkın yaban eşeğisin. 2 Azgınken kim tutabilir onu? 2 Peşine düşenlerin yorulması gerekmez, 2 Çiftleşme zamanı gelince onu bulurlar.'),
(2002314,68,24,2,25,'Yalınayak koşmaktan sakın, 2 Susuzluktan boğazını koru. 2 Ama sen, ‹Boş ver! 2 Ben başka ilahları seviyorum, 2 Onları izleyeceğim› dedin.'),
(2002315,68,24,2,26,'‹‹Hırsız yakalandığında nasıl utanırsa, 2 İsrailin halkı, kralları, önderleri, 2 Kâhinleri, peygamberleri de öyle utanacak.'),
(2002316,68,24,2,27,'Onlar ağaca, ‹Babamsın›, 2 Taşa, ‹Bizi sen doğurdun› derler. 2 Çünkü bana yüzlerini değil, 2 Sırtlarını çevirdiler. 2 Ama felakete uğrayınca, 2 ‹Kalk da bizi kurtar› diye yakarırlar.'),
(2002317,68,24,2,28,'Hani nerede kendiniz için yaptığınız ilahlar? 2 Felakete uğradığınızda kurtarabiliyorlarsa, 2 Kalkıp gelsinler. 2 Kentlerinin sayısı kadar 2 İlahların var, ey Yahuda halkı.››'),
(2002318,68,24,2,29,'‹‹Neden bana dava açıyorsunuz? 2 Hepiniz bana başkaldırdınız›› diyor RAB.'),
(2002319,68,24,2,30,'‹‹Halkınızı boşuna cezalandırdım, yola gelmediler. 2 Kılıcınız yırtıcı aslan gibi öldürdü peygamberlerinizi.'),
(2002320,68,24,2,31,'‹‹Ey siz, bu kuşağın çocukları, 2 RABbin sözünü anlayın! 2 Ben İsrail için bir çöl, 2 Kapkaranlık bir ülke mi oldum? 2 Öyleyse halkım neden, ‹Başımıza buyruğuz, 2 Artık sana dönmeyeceğiz› diyor?'),
(2002321,68,24,2,32,'Erden kız takılarını, 2 Gelin çeyizini unutabilir mi? 2 Ama halkım sayısız günlerce unuttu beni.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002322,68,24,2,33,'Aşkı kovalamakta 2 Ne kadar beceriklisin! 2 Kötü kadınlara bile kendi yöntemlerini öğretebildin.'),
(2002323,68,24,2,34,'Eteğin suçsuz yoksulların kanıyla lekelenmiş, 2 Oysa ev soyarken yakalamadın onları. 2 Bütün bunlara karşın,'),
(2002324,68,24,2,35,'‹Ben suçsuzum, 2 Kuşkusuz RABbin bana öfkesi dindi› diyorsun. 2 Ama ‹Günah işlemedim› dediğin için 2 Yargılayacağım seni.'),
(2002325,68,24,2,36,'Neden boyuna döneklik yapıp duruyorsun? 2 Asurda düşkırıklığına uğradığın gibi, 2 Mısırda da düşkırıklığına uğrayacaksın.'),
(2002326,68,24,2,37,'Oradan da ellerin başında çıkacaksın, 2 Çünkü RAB senin güvendiklerini reddetti; 2 Onlardan yarar sağlamayacaksın.››'),
(2002327,68,24,3,1,'‹‹Diyelim ki, bir adam karısını boşar, 2 Kadın da onu bırakıp başka biriyle evlenir. 2 Adam bir daha o kadına döner mi? 2 Bu davranış ülkeyi büsbütün kirletmez mi? 2 Oysa sen pek çok oynaşla fahişelik ettin, 2 Yine bana mı dönmek istiyorsun?›› diyor RAB.'),
(2002328,68,24,3,2,'‹‹Çıplak tepelere bak da gör. 2 Sevişmediğin yer mi kaldı? 2 Çölde yaşayan bedevi gibi 2 Yol kenarlarında oynaşlarını bekleyip durdun. 2 Fahişeliğinle, kötülüklerinle ülkeyi kirlettin.'),
(2002329,68,24,3,3,'Bu yüzden yağmurların ardı kesildi, 2 Son yağmur yağmadı. 2 Yüzsüz bir fahişeye benzedin, 2 Utanç duymak istemedin.'),
(2002330,68,24,3,4,'‹Baba, gençliğimden beri 2 Benim dostumsun› diye az önce bana seslenmedin mi?'),
(2002331,68,24,3,5,'‹Sonsuza dek kızgın mı kalacaksın? 2 Öfken sonsuza dek mi sürecek?› 2 Evet, böyle konuşuyor, 2 Ama elinden gelen her kötülüğü yapıyorsun.››'),
(2002332,68,24,3,6,'Kral Yoşiya döneminde RAB bana, ‹‹Dönek İsrailin yaptığını gördün mü?›› dedi, ‹‹Her yüksek tepenin üzerine, her bol yapraklı ağacın altına gidip fahişelik etti.'),
(2002333,68,24,3,7,'Bütün bunları yaptıktan sonra bana geri döneceğini düşündüm, ama dönmedi. Hain kızkardeşi Yahuda da gördü bunları.'),
(2002334,68,24,3,8,'Fahişeliği yüzünden dönek İsraili boşayıp ona boşanma belgesini verdiğim halde, kızkardeşi hain Yahudanın hiç korkmadığını, gidip fahişelik ettiğini gördüm.'),
(2002335,68,24,3,9,'Hiç umursamadan fahişeliğiyle ülkeyi kirletti; taşla, ağaçla zina etti.'),
(2002336,68,24,3,10,'Bütün bunlara karşın, hain kızkardeşi Yahuda içtenlikle değil, göstermelik olarak bana döndü.›› Böyle diyor RAB.'),
(2002337,68,24,3,11,'RAB bana, ‹‹Dönek İsrail hain Yahudadan daha doğru olduğunu gösterdi›› dedi,'),
(2002338,68,24,3,12,'‹‹Git, bu sözleri kuzeye duyur. De ki, ‹‹ ‹Ey dönek İsrail, geri dön› diyor RAB. 2 ‹Size artık öfkeyle bakmayacağım, 2 Çünkü ben sevecenim› diyor RAB. 2 ‹Öfkemi sonsuza dek sürdürmem.'),
(2002339,68,24,3,13,'Ancak suçunu kabul et: 2 Tanrın RABbe başkaldırdın, 2 Her bol yapraklı ağacın altında 2 Sevgini yabancı ilahlarla paylaştın, 2 Beni dinlemedin.› ›› 2 Böyle diyor RAB.'),
(2002340,68,24,3,14,'‹‹Geri dön, ey dönek halk›› diyor RAB, ‹‹Çünkü kocan benim. Birinizi kentten, ikinizi bir boydan alıp Siyona geri getireceğim.'),
(2002341,68,24,3,15,'Size gönlüme göre çobanlar vereceğim; sizi bilgiyle, sağduyuyla güdecekler.'),
(2002342,68,24,3,16,'Ülkede büyüyüp sayıca çoğaldığınız günlerde›› diyor RAB, ‹‹Halk artık, ‹RABbin Antlaşma Sandığı› demeyecek. Sandık bir daha kimsenin aklına gelmeyecek; anımsanmayacak, özlenmeyecek, bir yenisi de yapılmayacak.'),
(2002343,68,24,3,17,'O zaman Yeruşalime, ‹RABbin Tahtı› diyecekler. RABbin adını onurlandırmak için bütün uluslar Yeruşalimde toplanacak. Bundan böyle kötü yüreklerinin inadı uyarınca davranmayacaklar.'),
(2002344,68,24,3,18,'O günlerde Yahuda halkıyla İsrail halkı kuzeyde bir ülkeden birlikte yürüyecek, atalarına mülk olarak vermiş olduğum ülkede bir araya gelecekler.'),
(2002345,68,24,3,19,'‹‹Ben RAB, demiştim ki, ‹Ne kadar isterdim 2 Seni çocuklarımdan saymayı; 2 Sana güzel ülkeyi, 2 Ulusların en güzel mülkünü vermeyi! 2 Bana baba diyeceğini, 2 Benden hiç ayrılmayacağını sandım.'),
(2002346,68,24,3,20,'Ama bir kadın kocasına nasıl ihanet ederse, 2 Sen de bana öyle ihanet ettin, ey İsrail halkı!› ›› 2 Böyle diyor RAB.'),
(2002347,68,24,3,21,'Çıplak tepelerde bir ses duyuluyor, 2 İsrail halkının ağlayışı ve yakarışı. 2 Çünkü doğru yoldan saptılar, 2 Tanrıları RABbi unuttular.'),
(2002348,68,24,3,22,'‹‹Geri dönün, ey dönek çocuklar, 2 Dönekliğinizi iyileştireyim.›› Halk, ‹‹İşte buradayız, sana geliyoruz!›› diyor, 2 ‹‹Çünkü Tanrımız RAB sensin.'),
(2002349,68,24,3,23,'Kuşkusuz dağlardan, 2 Tepelerden gelen tapınma sesleri aldatıcıdır. 2 Kuşkusuz İsrailin kurtuluşu Tanrımız RABdedir.'),
(2002350,68,24,3,24,'Gençliğimizden bu yana 2 Atalarımızın emeğinin ürününü, 2 Davarlarını, sığırlarını, 2 Oğullarını, kızlarını 2 Utanılası putlar yedi.'),
(2002351,68,24,3,25,'Utanç içinde yatalım, 2 Rezilliğimiz bizi örtsün! 2 Çünkü biz de atalarımız da 2 Gençliğimizden bu yana 2 Tanrımız RAB''be karşı günah işledik, 2 Tanrımız RAB''bin sesine kulak asmadık.››'),
(2002352,68,24,4,1,'‹‹Eğer geri dönersen, ey İsrail, 2 Eğer bana geri dönersen›› diyor RAB, 2 ‹‹İğrenç putlarını gözümün önünden uzaklaştırır, 2 Bir daha yoldan sapmazsan;'),
(2002353,68,24,4,2,'‹RABbin varlığı hakkı için› diyerek 2 Sadakatle, adaletle, doğrulukla ant içersen, 2 Uluslar Onun aracılığıyla kutsanacak, 2 Onunla övünecekler.››'),
(2002354,68,24,4,3,'RAB Yahuda ve Yeruşalim halkına şöyle diyor: 2 ‹‹İşletilmemiş toprağınızı sürün, 2 Dikenler arasına ekmeyin.'),
(2002355,68,24,4,4,'Ey sizler, Yahuda halkı ve Yeruşalimde yaşayanlar, 2 Kendinizi RABbe adayın, 2 Bunu engelleyen her şeyi yüreğinizden uzaklaştırın. 2 Yoksa yaptığınız kötülüklerden ötürü 2 Öfkem ateş gibi yağacak, 2 Her şeyi yiyip bitirecek 2 Ve söndüren olmayacak.›› yüreğinizden uzaklaştırın››: İbranice ‹‹Kendinizi de yüreğinizi de RAB için sünnet edin››.'),
(2002356,68,24,4,5,'‹‹Yahudada duyurun, 2 Yeruşalimde ilan edin, 2 ‹Ülkede boru çalın!› deyin, 2 ‹Toplanın› diye haykırın, 2 ‹Surlu kentlere kaçalım!›'),
(2002357,68,24,4,6,'Siyona giden yolu gösteren 2 Bir işaret koyun! 2 Güvenliğiniz için kaçın! 2 Durmayın! 2 Üzerinize kuzeyden felaket, 2 Büyük yıkım getirmek üzereyim.››'),
(2002358,68,24,4,7,'Aslan ininden çıktı, 2 Ulusları yok eden yola koyuldu. 2 Ülkenizi viran etmek için 2 Yerinden ayrıldı. 2 Kentleriniz yerle bir edilecek, 2 İçlerinde yaşayan kalmayacak.'),
(2002359,68,24,4,8,'Onun için çula sarının, 2 Dövünüp haykırın, 2 Çünkü RABbin kızgın öfkesi üzerimizden kalkmadı.'),
(2002360,68,24,4,9,'‹‹O gün›› diyor RAB, 2 ‹‹Kral da önderler de yılacak, 2 Kâhinler şaşkına dönecek, 2 Peygamberler donakalacak.››'),
(2002361,68,24,4,10,'O zaman, ‹‹Ah, Egemen RAB›› dedim, ‹‹ ‹Esenlikte olacaksınız› diyerek bu halkı da Yeruşalimi de tam anlamıyla aldattın. Çünkü kılıç boğazımıza dayandı.››'),
(2002362,68,24,4,11,'O zaman bu halka ve Yeruşalime, ‹‹Çöldeki çıplak tepelerden halkıma doğru sıcak bir rüzgar esiyor, ama harman savurmak ya da ayırmak için değil›› denecek,'),
(2002363,68,24,4,12,'‹‹Benden gelen bu rüzgar çok daha güçlü olacak. Şimdi bu halka yargılarımı bildiriyorum.››'),
(2002364,68,24,4,13,'İşte düşman bulut gibi ilerliyor; 2 Savaş arabaları kasırga sanki, 2 Atları kartallardan daha çevik. 2 Vay başımıza! Mahvolduk!'),
(2002365,68,24,4,14,'Ey Yeruşalim, yüreğini kötülükten arındır ki, 2 Kurtulasın. 2 Ne zamana dek yüreğinde kötü düşünceler barındıracaksın?'),
(2002366,68,24,4,15,'Dandan bir ses bildiriyor, 2 Efrayim dağlarından kötü haber duyuruyor!'),
(2002367,68,24,4,16,'‹‹Uluslara duyurun, 2 Yeruşalime bildirin: 2 ‹Uzak bir ülkeden gelen ordu çevresini kuşatacak, 2 Yahuda kentlerine karşı 2 Savaş naraları atacaklar.'),
(2002368,68,24,4,17,'Bir tarlayı koruyanlar gibi 2 Kuşatacaklar Yeruşalimi. 2 Çünkü Yeruşalim bana başkaldırdı› ›› diyor RAB.'),
(2002369,68,24,4,18,'‹‹Kendi davranışların, kendi yaptıkların 2 Başına gelmesine neden oldu bunların. 2 Cezan bu. 2 Ne acı! 2 Nasıl da yüreğine işliyor!››'),
(2002370,68,24,4,19,'Ah, içim, içim! 2 Acıdan kıvranıyorum. 2 Ah, yüreğim, yüreğim çarpıyor. 2 Sessiz duramıyorum! 2 Çünkü boru sesini, savaş naralarını işittim!'),
(2002371,68,24,4,20,'Felaket felaketi izliyor, 2 Bütün ülke viran oldu. 2 Bir anda çadırlarım, 2 Perdelerim yok oldu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002372,68,24,4,21,'Ne zamana dek düşman sancağını görmek, 2 Boru sesini duymak zorunda kalacağım?'),
(2002373,68,24,4,22,'‹‹Halkım akılsızdır, 2 Beni tanımıyor. 2 Aptal çocuklardır, 2 Akılları yok. 2 Kötülük etmeyi iyi bilir, 2 İyilik etmeyi bilmezler›› diyor RAB.'),
(2002374,68,24,4,23,'Ben Yeremya yere baktım, şekilsizdi, boştu, 2 Göğe baktım, ışık yoktu.'),
(2002375,68,24,4,24,'Dağlara baktım, titriyorlardı, 2 Bütün tepeler sarsılıyordu.'),
(2002376,68,24,4,25,'Baktım, insan yoktu, 2 Gökte uçan bütün kuşlar kaçmıştı.'),
(2002377,68,24,4,26,'Baktım, verimli toprak çöle dönmüş, 2 Bütün kentler yıkılmıştı. 2 Bütün bunlar RABbin yüzünden, 2 Onun kızgın öfkesi yüzünden olmuştu.'),
(2002378,68,24,4,27,'RAB diyor ki, 2 ‹‹Bütün ülke viran olacak, 2 Ama onu büsbütün yok etmeyeceğim.'),
(2002379,68,24,4,28,'Bu yüzden yeryüzü yasa gömülecek, 2 Gök kararacak; 2 Çünkü ben söyledim, ben tasarladım. 2 Fikrimi değiştirmeyecek, 2 Verdiğim karardan dönmeyeceğim.››'),
(2002380,68,24,4,29,'Her kentin halkı, 2 Atlılarla okçuların gürültüsünden kaçıyor. 2 Kimi çalılıklara giriyor, 2 Kimi kayalıklara tırmanıyor. 2 Bütün kentler terk edildi, 2 Oralarda kimse yaşamıyor.'),
(2002381,68,24,4,30,'Ey sen, viran olmuş kent, 2 Kırmızı giysiler giymekle, 2 Altın süsler bezenmekle, 2 Gözüne sürme çekmekle ne elde edeceksin? 2 Kendini böyle güzelleştirmen boşuna. 2 Oynaşların seni küçümsüyor, 2 Canını almak istiyorlar.'),
(2002382,68,24,4,31,'Sancı çeken kadının haykırışını, 2 İlk çocuğunu doğuran kadının çektiği acıyı, 2 Ellerini uzatmış, soluğu kesilmiş Siyon kızının, 2 ‹‹Eyvah! Katillerin karşısında bayılıyorum›› 2 Diye haykırdığını işitir gibi oldum.'),
(2002383,68,24,5,1,'‹‹Yeruşalim sokaklarında dolaşın, 2 Çevrenize bakıp düşünün, 2 Kent meydanlarını araştırın. 2 Eğer adil davranan, 2 Gerçeği arayan bir kişi bulursanız, 2 Bu kenti bağışlayacağım.'),
(2002384,68,24,5,2,'‹RABbin varlığı hakkı için› deseler de, 2 Aslında yalan yere ant içiyorlar.››'),
(2002385,68,24,5,3,'Ya RAB, gözlerin gerçeği arıyor. 2 Onları vurdun, ama incinmediler, 2 Onları yiyip bitirdin, 2 Ama yola gelmeyi reddettiler. 2 Yüzlerini kayadan çok sertleştirdiler, 2 Geri dönmek istemediler.'),
(2002386,68,24,5,4,'‹‹Bunlar sadece yoksul kişiler, 2 Akılsızlar›› dedim, 2 ‹‹Çünkü RABbin yolunu, 2 Tanrılarının buyruklarını bilmiyorlar.'),
(2002387,68,24,5,5,'Büyüklere gidip onlarla konuşayım. 2 RABbin yolunu, 2 Tanrılarının buyruklarını bilirler kuşkusuz.›› 2 Gelgelelim onlar da boyunduruğu kırmış, 2 Bağları koparmıştı.'),
(2002388,68,24,5,6,'Bu yüzden ormandan bir aslan çıkıp onlara saldıracak, 2 Çölden gelen bir kurt onları parça parça edecek, 2 Bir pars kentlerinin önünde pusu kuracak, 2 Oradan çıkan herkes parçalanacak. 2 Çünkü isyanları çok, 2 Döneklikleri sayısızdır.'),
(2002389,68,24,5,7,'‹‹Yaptıklarından ötürü neden bağışlayayım seni? 2 Çocukların beni terk etti, 2 Tanrı olmayan ilahların adıyla ant içtiler. 2 Onları doyurduğumda zina ettiler, 2 Fahişelerin evlerine doluştular.'),
(2002390,68,24,5,8,'Şehvet düşkünü, besili aygırlar! 2 Her biri komşusunun karısına kişniyor.'),
(2002391,68,24,5,9,'Bu yüzden onları cezalandırmayayım mı?›› diyor RAB, 2 ‹‹Böyle bir ulustan öcümü almayayım mı?'),
(2002392,68,24,5,10,'‹‹Bağlarını dolaşıp 2 Asmalarını kesin, 2 Ama büsbütün yok etmeyin. 2 Dallarını koparıp atın, 2 Çünkü onlar RABbe ait değil.'),
(2002393,68,24,5,11,'İsrail ve Yahuda halkı 2 Bana sürekli ihanet etti›› diyor RAB.'),
(2002394,68,24,5,12,'RAB için yalan söyleyerek, 2 ‹‹O bir şey yapmaz. 2 Felaket bize uğramayacak, 2 Kılıç da kıtlık da görmeyeceğiz›› dediler.'),
(2002395,68,24,5,13,'Peygamberler lafebesidir, 2 Tanrının sözü onlarda değil. 2 Onlara böyle yapılacak.'),
(2002396,68,24,5,14,'Bu yüzden, Her Şeye Egemen RAB Tanrı diyor ki, 2 ‹‹Madem böyle şeyler konuşuyorsunuz, 2 Ben de sözümü ağzınıza ateş, 2 Bu halkı da odun edeceğim; 2 Ateş onları yakıp yok edecek.'),
(2002397,68,24,5,15,'Ey İsrail halkı, 2 Uzaktan gelecek bir ulusu 2 Üzerinize saldırtacağım›› diyor RAB, 2 ‹‹Köklü, eski bir ulus; 2 Sen onların dilini bilmez, 2 Ne dediklerini anlamazsın.'),
(2002398,68,24,5,16,'Oklarının kılıfı açık bir mezar gibidir, 2 Hepsi birer yiğittir.'),
(2002399,68,24,5,17,'Ürününü, yiyeceklerini tüketecek, 2 Oğullarını, kızlarını öldürecekler; 2 Davarlarını, sığırlarını, 2 Asmalarının, incir ağaçlarının meyvesini yiyecek, 2 Güvendiğin surlu kentlerini 2 Kılıçla yerle bir edecekler.'),
(2002400,68,24,5,18,'‹‹Ama o günlerde bile sizi büsbütün yok etmeyeceğim›› diyor RAB.'),
(2002401,68,24,5,19,'‹‹ ‹Tanrımız RAB neden bize bütün bunları yaptı?› diye sorduklarında, şöyle yanıtlayacaksın: ‹Beni nasıl bıraktınız, ülkenizde yabancı ilahlara nasıl kulluk ettinizse, siz de kendinize ait olmayan bir ülkede yabancılara öyle kulluk edeceksiniz.›'),
(2002402,68,24,5,20,'‹‹Yakup soyuna bildirin, 2 Yahuda halkına duyurun:'),
(2002403,68,24,5,21,'Ey gözleri olan ama görmeyen, 2 Kulakları olan ama işitmeyen, 2 Sağduyudan yoksun akılsız halk, 2 Şunu dinle:'),
(2002404,68,24,5,22,'Benden korkman gerekmez mi?›› diyor RAB, 2 ‹‹Huzurumda titremen gerekmez mi? 2 Ben ki, sonsuza dek geçerli bir kuralla 2 Denize sınır olarak kumu koydum. 2 Deniz sınırı geçemez; 2 Dalgalar kabarsa da üstün gelemez, 2 Kükrese de sınırı aşamaz.'),
(2002405,68,24,5,23,'Ama bu halkın yüreği asi ve inatçı. 2 Sapmışlar, kendi yollarına gitmişler.'),
(2002406,68,24,5,24,'İçlerinden, 2 ‹İlk ve son yağmurları zamanında yağdıran, 2 Belli ürün biçme haftalarını bizim için koruyan 2 Tanrımız RABden korkalım› demiyorlar.'),
(2002407,68,24,5,25,'Bunları uzaklaştıran suçlarınızdı, 2 Bu iyilikten sizi yoksun bırakan günahlarınızdı.'),
(2002408,68,24,5,26,'‹‹Halkım arasında kötü kişiler var. 2 Kuş avlamak için pusuya yatanlar gibi 2 Tuzak kuruyor, insan yakalıyorlar.'),
(2002409,68,24,5,27,'Kuş dolu bir kafes nasılsa, 2 Onların evleri de hileyle dolu. 2 Bu sayede güçlenip zengin oldular,'),
(2002410,68,24,5,28,'Semirip parladılar, 2 Yaptıkları kötülüklerle sınırı aştılar. 2 Kazanabilecekleri halde öksüzün davasına bakmıyor, 2 Yoksulun hakkını savunmuyorlar.'),
(2002411,68,24,5,29,'Bu yüzden onları cezalandırmayayım mı?›› diyor RAB, 2 ‹‹Böyle bir ulustan öcümü almayayım mı?'),
(2002412,68,24,5,30,'‹‹Ülkede korkunç, dehşet verici bir şey oldu:'),
(2002413,68,24,5,31,'Peygamberler yalan peygamberlik ediyor, 2 Halkı başına buyruk kâhinler yönetiyor, 2 Halkım da bunu benimsiyor. 2 Ama bunun sonunda ne yapacaksınız?››'),
(2002414,68,24,6,1,'‹‹Güvenliğiniz için kaçın, ey Benyamin halkı! 2 Yeruşalimden kaçın! 2 Tekoada boru çalın! 2 Beythakkereme bir işaret koyun. 2 Çünkü kuzeyden bir felaket, 2 Büyük bir yıkım gelecek gibi görünüyor.'),
(2002415,68,24,6,2,'Siyon kızını, o güzel, narin kızı yok edeceğim.'),
(2002416,68,24,6,3,'Çobanlar sürüleriyle ona geliyor, 2 Çevresinde çadırlarını kuracaklar. 2 Herkes kendi sürüsünü otlatacak.››'),
(2002417,68,24,6,4,'‹‹Yeruşalime karşı savaş hazırlığı yapın! 2 Kalkın, öğleyin saldırıya geçelim! 2 Vay halimize, gün kararıyor! 2 Akşamın gölgeleri gitgide uzuyor.'),
(2002418,68,24,6,5,'Haydi, gece saldırıya geçelim, 2 Kentin kalelerini yerle bir edelim.››'),
(2002419,68,24,6,6,'Her Şeye Egemen RAB diyor ki, 2 ‹‹Ağaçları kesin, 2 Yeruşalime karşı kuşatma rampaları yapın. 2 Bu kent cezalandırılmalı, 2 İçinde zorbalıktan başka bir şey yok.'),
(2002420,68,24,6,7,'Kuyu suyunu nasıl taze tutuyorsa, 2 Yeruşalim de kötülüğünü öyle taze tutuyor. 2 Şiddet ve yıkım yankılanıyor orada, 2 Karşımda hep hastalık ve yaralar var.'),
(2002421,68,24,6,8,'Uyarılara kulak ver, ey Yeruşalim! 2 Yoksa seni bırakacağım, 2 Seni bir viraneye, 2 Oturulmaz bir ülkeye çevireceğim.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002422,68,24,6,9,'Her Şeye Egemen RAB diyor ki, 2 ‹‹Asmadan nasıl üzüm toplanırsa, 2 İsrail halkından geride kalanları da öyle toplayacaklar. 2 Üzüm toplayan biri gibi 2 Elini yine asma dallarına uzat.››'),
(2002423,68,24,6,10,'İşitsinler diye kiminle konuşayım, 2 Kimi uyarayım? 2 Kulakları tıkalı, işitemiyorlar. 2 RABbin sözünü aşağılıyor, 2 Ondan hoşlanmıyorlar.'),
(2002424,68,24,6,11,'Bu yüzden RABbin öfkesiyle doluyum, 2 Kendimi tutmaktan yoruldum. 2 ‹‹Sokaktaki çocukların, 2 Toplanan gençlerin üzerine boşalt öfkeni. 2 Nasıl olsa karı da koca da, 2 Yaşlı da yıllarca yaşamış olan da kurtulamayacak.'),
(2002425,68,24,6,12,'Evleri, tarlaları, karıları 2 Başkalarına verilecek, 2 Çünkü ülkede yaşayanlara karşı 2 Elimi kaldıracağım›› diyor RAB.'),
(2002426,68,24,6,13,'‹‹Küçük büyük herkes kazanç peşinde, 2 Peygamberler, kâhinler, hepsi halkı aldatıyor.'),
(2002427,68,24,6,14,'Esenlik yokken, 2 ‹Esenlik, esenlik› diyerek 2 Halkımın yarasını sözde iyileştirdiler.'),
(2002428,68,24,6,15,'Yaptıkları iğrençliklerden utandılar mı? 2 Hayır, ne utanması? 2 Kızarıp bozarmanın ne olduğunu bile bilmiyorlar. 2 Bu yüzden onlar da düşenlerin arasında yer alacak, 2 Onları cezalandırdığımda sendeleyip düşecekler›› diyor RAB.'),
(2002429,68,24,6,16,'RAB diyor ki, 2 ‹‹Yol kavşaklarında durup bakın, 2 Eski yolları sorun, 2 İyi yol nerede, öğrenin, 2 O yolda yürüyün, 2 Canlarınız rahata kavuşur. 2 Ama onlar, ‹O yolda yürümeyiz› dediler.'),
(2002430,68,24,6,17,'Size bekçiler atayıp, 2 ‹Boru sesini dinleyin› dedim, 2 Ama onlar, ‹Dinlemeyiz› dediler.'),
(2002431,68,24,6,18,'Bundan ötürü, ey uluslar, 2 Başlarına neler geleceğini işitin! 2 Sen de anla, ey topluluk!'),
(2002432,68,24,6,19,'Dinle, ey yeryüzü! 2 Bu halkın üzerine felaket, 2 Kendi kurduğu düzenin sonucunu getirmek üzereyim. 2 Çünkü sözlerime kulak asmadılar, 2 Kutsal Yasamı reddettiler.'),
(2002433,68,24,6,20,'Neden bana Sabadan günnük, 2 Uzak bir ülkeden güzel kokulu kamış getiriliyor? 2 Yakmalık sunularınızı kabul etmiyorum, 2 Kurbanlarınızdan hoşnut değilim.››'),
(2002434,68,24,6,21,'Bu yüzden RAB diyor ki, 2 ‹‹Bu halkın önüne tökezler koyacağım, 2 Babalar da oğullar da 2 Tökezleyip birlikte düşecek, 2 Komşu dostuyla birlikte yok olacak.››'),
(2002435,68,24,6,22,'RAB diyor ki, 2 ‹‹İşte kuzeyden bir ordu geliyor. 2 Dünyanın uçlarından 2 Büyük bir ulus harekete geçiyor.'),
(2002436,68,24,6,23,'Yay, pala kuşanmışlar, 2 Gaddar ve acımasızlar. 2 Atlara binmiş gelirken, 2 Kükreyen denizi andırıyor sesleri. 2 Savaşa hazır savaşçılar 2 Karşına dizilecekler, ey Siyon kızı!››'),
(2002437,68,24,6,24,'Haberlerini aldık, 2 Ellerimizde derman kalmadı. 2 Doğuran kadın gibi 2 Üzüntü, sancı sardı bizi.'),
(2002438,68,24,6,25,'Kırlara çıkmayın, 2 Yolda yürümeyin! 2 Düşmanın kılıcı orada, 2 Her yer dehşet içinde.'),
(2002439,68,24,6,26,'Ey halkım, çula sarın, 2 Kül içinde yuvarlan. 2 Biricik oğul için yas tutar gibi 2 Acı acı dövün. 2 Çünkü yok edici ansızın gelecek üzerimize.'),
(2002440,68,24,6,27,'‹‹Seni halkımı deneyesin diye atadım, 2 Öyle ki, onları tanıyıp yollarını sınayasın.'),
(2002441,68,24,6,28,'Hepsi de çok dikbaşlı, 2 Onu bunu çekiştirerek dolaşan insanlardır, 2 Tunç kadar, demir kadar katıdırlar. 2 Hepsi baştan çıkmıştır.'),
(2002442,68,24,6,29,'Körük üfürdükçe üfürüyor, 2 Kurşunu ateşte eritiyor, 2 Ama boşunadır yapılan işlem, 2 Çünkü kötüler arınmıyor.'),
(2002443,68,24,6,30,'Onlara gümüş artığı denecek, 2 Çünkü RAB onları reddetti.››'),
(2002444,68,24,7,1,'RAB Yeremyaya şöyle seslendi:'),
(2002445,68,24,7,2,'‹‹RABbin Tapınağının kapısında durup şu sözü duyur. De ki, ‹‹ ‹RABbin sözünü dinleyin, ey RABbe tapınmak için bu kapılardan giren Yahuda halkı!'),
(2002446,68,24,7,3,'İsrailin Tanrısı, Her Şeye Egemen RAB diyor ki: Yaşantınızı ve uygulamalarınızı düzeltin. O zaman burada kalmanızı sağlarımfı.'),
(2002447,68,24,7,4,'‹‹RABbin Tapınağı, RABbin Tapınağı, RABbin Tapınağı buradadır!›› gibi aldatıcı sözlere güvenmeyin.'),
(2002448,68,24,7,5,'Eğer yaşantınızı ve uygulamalarınızı gerçekten düzeltir, birbirinize karşı adil davranır,'),
(2002449,68,24,7,6,'yabancıya, öksüze, dula haksızlık etmez, burada suçsuz kanı akıtmaz, sizi yıkıma götüren başka ilahların ardınca gitmezseniz,'),
(2002450,68,24,7,7,'burada, sonsuza dek atalarınıza vermiş olduğum ülkede kalmanızı sağlarımfı.'),
(2002451,68,24,7,8,'Ne var ki, sizler işe yaramaz aldatıcı sözlere güveniyorsunuz.'),
(2002452,68,24,7,9,'‹‹ ‹Çalmak, adam öldürmek, zina etmek, yalan yere ant içmek, Baala buhur yakmak, tanımadığınız başka ilahların ardınca gitmek, bütün bu iğrençlikleri yapmak için mi bana ait olan tapınağa gelip önümde duruyor, güvenlikteyiz diyorsunuz?'),
(2002453,68,24,7,11,'Bana ait olan bu tapınak sizin için bir haydut ini mi oldu? Ama ben görüyorum neler yaptığınızı!› diyor RAB.'),
(2002454,68,24,7,12,'‹‹ ‹Daha önce adımı yerleştirmiş olduğum Şilodaki yerime gidin. Halkım İsrailin kötülüğü yüzünden ona ne yaptığımı görün.'),
(2002455,68,24,7,13,'Bütün bunları yaptınız, diyor RAB, size defalarca seslendim ama dinlemediniz; sizi çağırdım ama yanıt vermediniz.'),
(2002456,68,24,7,14,'Bu yüzden Şiloya ne yaptımsa, bana ait olan, güvendiğiniz bu tapınağa da -sizlere, atalarınıza vermiş olduğum bu yere de- aynısını yapacağım.'),
(2002457,68,24,7,15,'Kardeşlerinizi, bütün Efrayim soyunu nasıl attıysam, sizleri de öyle atacağım huzurumdan.›'),
(2002458,68,24,7,16,'‹‹Sana gelince, ey Yeremya, bu halk için yalvarma; onlar için ne yakar ne de dilekte bulun; bana yalvarıp yakarma, çünkü seni dinlemeyeceğim.'),
(2002459,68,24,7,17,'Onların Yahuda kentlerinde, Yeruşalim sokaklarında neler yaptıklarını görmüyor musun?'),
(2002460,68,24,7,18,'Çocuklar odun topluyor, babalar ateş yakıyor, kadınlar Gök Kraliçesine pide pişirmek için hamur yoğuruyor. Beni öfkelendirmek için başka ilahlara dökmelik sunular sunuyorlar.'),
(2002461,68,24,7,19,'İncittikleri ben miyim, diyor RAB. Hayır, kendilerini inciterek utanca boğuyorlar.'),
(2002462,68,24,7,20,'‹‹Bu yüzden Egemen RAB diyor ki, ‹Buranın üzerine, insanın, hayvanın, kırdaki ağaçların, toprağın ürününün üzerine kızgın öfkemi yağdıracağım. Yakıp yok edecek her şeyi, sönmeyecek.›'),
(2002463,68,24,7,21,'‹‹İsrailin Tanrısı, Her Şeye Egemen RAB diyor ki, ‹Yakmalık sunularınızı öbür kurbanlarınıza ekleyin de et yiyin.'),
(2002464,68,24,7,22,'Çünkü atalarınızı Mısırdan çıkardığımda, yakmalık sunularla kurbanlar hakkında onlara seslenip buyruk vermedim.'),
(2002465,68,24,7,23,'Onlara şunu buyurdum: Sözümü dinlerseniz, ben sizin Tanrınız, siz de benim halkım olursunuz. İyilik bulmanız için her konuda size buyurduğum yolda yürüyün.'),
(2002466,68,24,7,24,'Ne var ki, dinlemediler, kulak asmadılar; kendi isteklerinin, kötü yüreklerinin inadı doğrultusunda yürüdüler. İleri değil, geri gittiler.'),
(2002467,68,24,7,25,'Atalarınızın Mısırdan çıktığı günden bu yana, size her gün defalarca peygamber kullarımı gönderdim.'),
(2002468,68,24,7,26,'Ama beni dinlemediniz, kulak asmadınız. İnat ederek atalarınızdan daha çok kötülük yaptınız.›'),
(2002469,68,24,7,27,'‹‹Onlara bütün bunları söyleyeceksin ama seni dinlemeyecekler. Onları çağıracaksın ama yanıt vermeyecekler.'),
(2002470,68,24,7,28,'Bunun için onlara de ki, ‹Tanrısı RABbin sözünü dinlemeyen, ders almayan ulus işte budur. Bana bağlılıkları yok oldu, bağlılıktan söz etmez oldular.'),
(2002471,68,24,7,29,'‹‹ ‹Saçını kes ve at, ey Yeruşalim, 2 Çıplak tepeler üzerinde ağıt yak. 2 Çünkü RAB, öfkesine uğramış kuşağı 2 Reddedip terk etti.› ››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002472,68,24,7,30,'‹‹ ‹Yahuda halkı gözümde kötü olanı yaptı, diyor RAB. Bana ait olan bu tapınağa iğrenç putlarını yerleştirerek onu kirlettiler.'),
(2002473,68,24,7,31,'Oğullarını, kızlarını ateşte kurban etmek için Ben-Hinnom Vadisinde, Tofette puta tapılan yerler kurdular. Böyle bir şeyi ne buyurdum ne de aklımdan geçirdim.'),
(2002474,68,24,7,32,'Bundan ötürü oraya artık Tofet ya da Ben-Hinnom Vadisi değil, Kıyım Vadisi deneceği günler geliyor, diyor RAB. Tofette yer kalmayana dek gömecekler ölüleri.'),
(2002475,68,24,7,33,'Bu halkın ölüleri yırtıcı kuşlara, yabanıl hayvanlara yem olacak; onları korkutup kaçıran kimse olmayacak.'),
(2002476,68,24,7,34,'Yahuda kentlerinde, Yeruşalim sokaklarında sevinç ve neşe sesine, gelin güvey sesine son vereceğim; ülke viraneye dönecek.'),
(2002477,68,24,8,1,'‹‹ ‹O zaman, diyor RAB, Yahuda krallarıyla önderlerinin, kâhinlerin, peygamberlerin, Yeruşalimde yaşamış olanların kemikleri mezarlarından çıkarılacak.'),
(2002478,68,24,8,2,'Toplanmayacak, gömülmeyecek kemikler, toprağın üzerinde gübre gibi olacaklar. Yeruşalim halkının sevdiği, kulluk ettiği, izlediği, danıştığı, taptığı güneşin, ayın, gök cisimlerinin önüne serilecekler.'),
(2002479,68,24,8,3,'Bu kötü ulustan bütün sağ kalanlar, kendilerini sürdüğüm yerlerde yaşayanlar, ölümü yaşama yeğleyecekler. Her Şeye Egemen RAB böyle diyor.›'),
(2002480,68,24,8,4,'‹‹Onlara de ki, ‹RAB şöyle diyor: ‹‹ ‹İnsan yere düşer de kalkmaz mı, 2 Yoldan sapar da geri dönmez mi?'),
(2002481,68,24,8,5,'Öyleyse neden bu halk yoldan saptı? 2 Neden Yeruşalim sürekli döneklik ediyor? 2 Hileye yapışıyor, 2 Geri dönmeyi reddediyorlar.'),
(2002482,68,24,8,6,'Dikkatle dinledim, 2 Ama doğru söylemiyorlar. 2 Kimse, ne yaptım, diyerek kötülüğünden pişmanlık duymuyor. 2 Savaşta seğirten at gibi 2 Herkes kendi yoluna gidiyor.'),
(2002483,68,24,8,7,'Gökteki leylek bile 2 Belli mevsimlerini bilir. 2 Kumru da kırlangıç da turna da 2 Göç etme zamanını gözetir. 2 Oysa halkım buyruklarımı bilmez.'),
(2002484,68,24,8,8,'‹‹ ‹Nasıl, biz bilge kişileriz, 2 RABbin Yasası bizdedir, diyebiliyorsunuz? 2 İşte, bilginlerin yalancı kalemi 2 Yasayı yalana çevirmiş.'),
(2002485,68,24,8,9,'Bilgeler utandırıldı, 2 Yıldırılıp ele geçirildi. 2 RABbin sözünü reddettiler. 2 Nasıl bir bilgelikmiş onlarınki?'),
(2002486,68,24,8,10,'Bundan ötürü karılarını başkalarına, 2 Tarlalarını sahiplenecek yeni kişilere vereceğim. 2 Küçük büyük herkes kazanç peşinde, 2 Peygamberler, kâhinler, hepsi halkı aldatıyor.'),
(2002487,68,24,8,11,'Esenlik yokken, 2 Esenlik, esenlik, diyerek 2 Halkımın yarasını sözde iyileştirdiler.'),
(2002488,68,24,8,12,'Yaptıkları iğrençliklerden utandılar mı? 2 Hayır, ne utanması? 2 Kızarıp bozarmanın ne olduğunu bile bilmiyorlar. 2 Bu yüzden onlar da düşenlerin arasında yer alacak, 2 Cezalandırıldıklarında sendeleyip düşecekler› diyor RAB.'),
(2002489,68,24,8,13,'‹‹ ‹Onları büsbütün yok edeceğim, diyor RAB, 2 Ne asmada üzüm kalacak, 2 Ne incir ağacında incir. 2 Yaprakları solup kuruyacak. 2 Onlara ne verdiysem, 2 Ellerinden alınacak.› ››'),
(2002490,68,24,8,14,'‹‹Neden burada oturup duruyoruz? 2 Toplanalım da surlu kentlere kaçalım, 2 Orada ölelim! 2 Tanrımız RAB bizi ölüme terk etti, 2 Bize zehirli su içirdi. 2 Çünkü Ona karşı günah işledik.'),
(2002491,68,24,8,15,'Esenlik bekledik, iyilik gelmedi. 2 Şifa umduk, yılgınlık bulduk.'),
(2002492,68,24,8,16,'Düşman atlarının hırıltısı 2 Dan bölgesinden duyuluyor, 2 Aygırlarının kişnemesinden 2 Bütün ülke titriyor. 2 Ülkeyi ve içindeki her şeyi, 2 Kenti ve orada yaşayanları 2 Yok etmeye geliyorlar.››'),
(2002493,68,24,8,17,'‹‹Bakın, aranıza yılanlar, 2 Büyüden etkilenmeyen engerekler göndereceğim, 2 Sizi sokacaklar›› diyor RAB.'),
(2002494,68,24,8,18,'Üzüntüm avutulamaz, 2 Yüreğim baygın,'),
(2002495,68,24,8,19,'Ülkenin en uzak köşelerinden 2 Halkımın feryadını dinleyin: 2 ‹‹RAB Siyonda değil mi? 2 Kralı orada değil mi?›› 2 RAB, ‹‹Putlarıyla, 2 İşe yaramaz yabancı ilahlarıyla 2 Neden öfkelendiriyorlar beni?›› diyor.'),
(2002496,68,24,8,20,'‹‹Ürün biçme zamanı geçti, 2 Yaz sona erdi, 2 Biz ise kurtulmadık›› diye haykırıyorlar.'),
(2002497,68,24,8,21,'Halkımın yarasından ben de yaralandım. 2 Yasa büründüm, dehşete düştüm.'),
(2002498,68,24,8,22,'Gilat''ta merhem yok mu, 2 Hekim yok mu? 2 Öyleyse halkımın yarası neden iyi edilmedi?'),
(2002499,68,24,9,1,'Keşke başım bir pınar, 2 Gözlerim bir gözyaşı kaynağı olsa! 2 Halkımın öldürülenleri için 2 Ağlasam gece gündüz!'),
(2002500,68,24,9,2,'Keşke halkımı bırakabilmem, 2 Onlardan uzaklaşabilmem için 2 Çölde konaklayacak bir yerim olsa! 2 Hepsi zina ediyor, 2 Hain bir topluluk!'),
(2002501,68,24,9,3,'‹‹Yalan söylemek için ülkede 2 Dillerini yay gibi geriyor, 2 Güçlerini gerçek yolunda kullanmıyorlar. 2 Kötülük üstüne kötülük yapıyor, 2 Beni tanımıyorlar›› diyor RAB.'),
(2002502,68,24,9,4,'‹‹Herkes dostundan sakınsın, 2 Kardeşlerinizin hiçbirine güvenmeyin. 2 Çünkü her kardeş Yakup gibi aldatıcı, 2 Her dost iftiracıdır.'),
(2002503,68,24,9,5,'Dost dostu aldatıyor, 2 Kimse gerçeği söylemiyor. 2 Dillerine yalan söylemeyi öğrettiler, 2 Suç işleye işleye yorgun düştüler.'),
(2002504,68,24,9,6,'Sen, ey Yeremya, 2 Aldatıcılığın ortasında yaşıyorsun. 2 Aldatıcılıkları yüzünden 2 Beni tanımak istemiyorlar.›› 2 Böyle diyor RAB.'),
(2002505,68,24,9,7,'Bundan ötürü Her Şeye Egemen RAB diyor ki, 2 ‹‹İşte, onları arıtıp sınayacağım, 2 Halkımın günahı yüzünden 2 Başka ne yapabilirim ki?'),
(2002506,68,24,9,8,'Dilleri öldürücü bir ok, 2 Hep aldatıyor. 2 Komşusuna esenlik diliyor, 2 Ama içinden ona tuzak kuruyor.'),
(2002507,68,24,9,9,'Bu yüzden onları cezalandırmayayım mı?›› diyor RAB, 2 ‹‹Böyle bir ulustan öcümü almayayım mı?››'),
(2002508,68,24,9,10,'Dağlar için ağlayıp yas tutacağım, 2 Otlaklar için ağıt yakacağım. 2 Çöle dönüştüler, 2 Kimse geçmiyor oralardan. 2 Sığırların böğürmesi duyulmuyor, 2 Kuşlar, yabanıl hayvanlar kaçıp gitti.'),
(2002509,68,24,9,11,'‹‹Yeruşalimi taş yığını, 2 Çakalların barınağı haline getireceğim. 2 Yahuda kentlerini 2 Kimsenin yaşayamayacağı bir viraneye döndüreceğim.››'),
(2002510,68,24,9,12,'Hangi bilge kişi buna akıl erdirecek? RABbin seslendiği kişi kim ki, sözünü açıklayabilsin? Ülke neden yıkıldı? Neden kimsenin geçemediği bir çöle dönüştü?'),
(2002511,68,24,9,13,'RAB, ‹‹Kendilerine verdiğim yasayı bıraktılar, sözümü dinlemediler, yasamı izlemediler›› diyor,'),
(2002512,68,24,9,14,'‹‹Onun yerine yüreklerinin inadını, atalarının öğrettiği gibi Baalları izlediler.››'),
(2002513,68,24,9,15,'Bunun için İsrailin Tanrısı, Her Şeye Egemen RAB diyor ki, ‹‹Bu halka pelinotu yedirecek, zehirli su içireceğim.'),
(2002514,68,24,9,16,'Onları kendilerinin de atalarının da tanımadığı ulusların arasına dağıtacak, tümünü yok edene dek peşlerine kılıcı salacağım.››'),
(2002515,68,24,9,17,'Her Şeye Egemen RAB diyor ki, 2 ‹‹İyi düşünün! 2 Ağıt yakan kadınları çağırın gelsinler. 2 En iyilerini çağırın gelsinler.'),
(2002516,68,24,9,18,'Hemen gelip bizim için ağıt yaksınlar; 2 Gözlerimiz gözyaşı döksün, 2 Gözkapaklarımızdan sular aksın.'),
(2002517,68,24,9,19,'Siyondan ağlama sesi duyuluyor: 2 ‹Yıkıma uğradık! 2 Büyük utanç içindeyiz, 2 Çünkü ülkemizi terk ettik, 2 Evlerimiz yerle bir oldu.› ››'),
(2002518,68,24,9,20,'Ey kadınlar, RABbin sözünü dinleyin! 2 Ağzından çıkan her söze kulak verin. 2 Kızlarınıza yas tutmayı, 2 Komşunuza ağıt yakmayı öğretin.'),
(2002519,68,24,9,21,'Ölüm pencerelerimize tırmandı, 2 Kalelerimize girdi; 2 Sokakları çocuksuz, 2 Meydanları gençsiz bıraktı.'),
(2002520,68,24,9,22,'Onlara de ki, ‹‹RAB şöyle diyor: 2 ‹İnsan cesetleri gübre gibi, 2 Biçicinin ardındaki demetler gibi toprağa serilecek. 2 Onları toplayacak kimse olmayacak.› ››'),
(2002521,68,24,9,23,'RAB şöyle diyor: 2 ‹‹Bilge kişi bilgeliğiyle, 2 Güçlü kişi gücüyle, 2 Zengin kişi zenginliğiyle övünmesin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002522,68,24,9,24,'Dünyada iyilik yapanın, 2 Adaleti, doğruluğu sağlayanın 2 Ben RAB olduğumu anlamakla 2 Ve beni tanımakla övünsün övünen. 2 Çünkü ben bunlardan hoşlanırım›› diyor RAB.'),
(2002523,68,24,9,25,'‹‹Yalnız bedence sünnetli olanları cezalandıracağım günler geliyor›› diyor RAB.'),
(2002524,68,24,9,26,'‹‹Mısır''ı, Yahuda''yı, Edom''u, Ammon''u, Moav''ı, çölde yaşayan ve zülüflerini kesenlerin hepsini cezalandıracağım. Çünkü bütün bu uluslar gerçekte sünnetsiz, bütün İsrail halkı da yürekte sünnetsizdir.››'),
(2002525,68,24,10,1,'RABbin sana ne söylediğini dinle, ey İsrail halkı!'),
(2002526,68,24,10,2,'RAB şöyle diyor: 2 ‹‹Ulusların yolunu öğrenmeyin, 2 Gök belirtilerinden yılmayın; 2 Bu belirtilerden uluslar yılsa bile.'),
(2002527,68,24,10,3,'Ulusların töreleri yararsızdır. 2 Ormandan ağaç keserler, 2 Usta keskisiyle ona biçim verir.'),
(2002528,68,24,10,4,'Altınla, gümüşle süsler, 2 Çekiçle, çivilerle sağlamlaştırırlar; 2 Yerinden kımıldamasın diye.'),
(2002529,68,24,10,5,'Salatalık bostanındaki korkuluk gibidir putları, 2 Konuşamazlar; 2 Onları taşımak gerek, çünkü yürüyemezler. 2 Onlardan korkmayın, zarar veremezler; 2 İyilik de edemezler.››'),
(2002530,68,24,10,6,'Senin gibisi yok, ya RAB, 2 Sen büyüksün, 2 Adın da büyüktür gücün sayesinde.'),
(2002531,68,24,10,7,'Senden kim korkmaz, 2 Ey ulusların kralı? 2 Bu sana yakışır. 2 Ulusların bilgeleri arasında, 2 Bütün ülkelerinde 2 Senin gibisi yok.'),
(2002532,68,24,10,8,'Hepsi budala ve akılsız. 2 Yararsız putlardan ne öğrenilebilir ki? 2 Ağaçtan yapılmış onlar!'),
(2002533,68,24,10,9,'Tarşişten dövme gümüş, 2 Ufazdan altın getirilir. 2 Ustayla kuyumcunun yaptığı nesnenin üzerine 2 Lacivert, mor giydirilir, 2 Hepsi usta işidir.'),
(2002534,68,24,10,10,'Ama gerçek Tanrı RABdir. 2 O yaşayan Tanrıdır, 2 Sonsuza dek kral Odur. 2 O öfkelenince yeryüzü titrer, 2 Uluslar dayanamaz gazabına.'),
(2002535,68,24,10,11,'‹‹Onlara şunu diyeceksin, 2 ‹Yeri, göğü yaratmayan bu ilahlar, 2 Yerden de göğün altından da yok olacaklar.› ››'),
(2002536,68,24,10,12,'Gücüyle yeryüzünü yaratan, 2 Bilgeliğiyle dünyayı kuran, 2 Aklıyla gökleri yayan RABdir.'),
(2002537,68,24,10,13,'O gürleyince gökteki sular çağıldar, 2 Yeryüzünün dört bucağından bulutlar yükseltir, 2 Yağmur için şimşek çaktırır, 2 Ambarlarından rüzgar estirir.'),
(2002538,68,24,10,14,'Hepsi budala, bilgisiz, 2 Her kuyumcu yaptığı puttan utanacak. 2 O putlar yapmacıktır, 2 Soluk yoktur onlarda.'),
(2002539,68,24,10,15,'Yararsız, alay edilesi nesnelerdir, 2 Cezalandırılınca yok olacaklar.'),
(2002540,68,24,10,16,'Yakupun Payı onlara benzemez. 2 Her şeye biçim veren Odur, 2 Onun mirasıdır İsrail oymağı, 2 Her Şeye Egemen RABdir adı.'),
(2002541,68,24,10,17,'Kuşatma altında olan sizler, 2 Eşyalarınızı toplayın yerden.'),
(2002542,68,24,10,18,'RAB diyor ki, 2 ‹‹İşte bu kez bu ülkede yaşayanları 2 Fırlatıp atacağım; 2 Ele geçirilmeleri için 2 Onları sıkıştıracağım.››'),
(2002543,68,24,10,19,'Yaramdan ötürü vay başıma gelen! 2 Derdim iyileşmez! 2 Ama, ‹Dert benim derdim, 2 Dayanmalıyım› dedim.'),
(2002544,68,24,10,20,'Çadırım yıkıldı, ipleri koptu. 2 Çocuklarım benden ayrıldı, 2 Yok artık onlar. 2 Çadırımı kuracak, 2 Perdelerimi takacak kimse kalmadı.'),
(2002545,68,24,10,21,'Çobanlar budala, 2 RABbe danışmıyorlar. 2 Bu yüzden işleri yolunda gitmiyor, 2 Bütün sürüleri dağıldı.'),
(2002546,68,24,10,22,'Dinle! Haber geliyor! 2 Kuzey ülkesinden büyük patırtı geliyor! 2 Yahuda kentlerini viraneye çevirecek, 2 Çakallara barınak edecek.'),
(2002547,68,24,10,23,'İnsanın yaşamının kendi elinde olmadığını, 2 Adımlarına yön vermenin ona düşmediğini 2 Biliyorum, ya RAB.'),
(2002548,68,24,10,24,'Beni öfkenle değil, 2 Yalnız adaletinle yola getir, ya RAB, 2 Yoksa beni hiçe indirirsin.'),
(2002549,68,24,10,25,'Öfkeni seni tanımayan ulusların, 2 Adını anmayan toplulukların üzerine dök. 2 Çünkü onlar Yakup soyunu yiyip bitirdiler, 2 Onu tümüyle yok ettiler, 2 Yurdunu viraneye çevirdiler.'),
(2002550,68,24,11,1,'RAB Yeremyaya şöyle seslendi:'),
(2002551,68,24,11,2,'‹‹Bu antlaşmanın koşullarını dinle. Yahuda halkına ve Yeruşalimde yaşayanlara açıkla.'),
(2002552,68,24,11,3,'Onlara diyeceksin ki, ‹İsrailin Tanrısı RAB şöyle diyor: Bu antlaşmanın koşullarına uymayan lanet altındadır!'),
(2002553,68,24,11,4,'Atalarınızı Mısırdan, demir eritme ocağından çıkardığımda bu antlaşmaya bağlı kalmalarını buyurdum. Onlara dedim ki: Sözümü dinleyin, buyurduğum her şeyi yerine getirin. Böylece siz benim halkım olursunuz, ben de sizin Tanrınız olurum.'),
(2002554,68,24,11,5,'İşte o zaman süt ve bal akan ülkeyi -bugün sizin olan ülkeyi- atalarınıza vereceğime ilişkin içtiğim andı yerine getirmiş olacağım.› ›› ‹‹Amin, ya RAB›› diye karşılık verdim.'),
(2002555,68,24,11,6,'RAB şöyle dedi: ‹‹Söyleyeceğim her şeyi Yahuda kentlerinde, Yeruşalim sokaklarında duyur: ‹Bu antlaşmanın koşullarını dinleyin, onlara uyun.'),
(2002556,68,24,11,7,'Atalarınızı Mısırdan çıkardığım günden bu yana sözümü dinlemeleri için onları defalarca uyardım.'),
(2002557,68,24,11,8,'Ama dinlemediler, kulak asmadılar. Bunun yerine kötü yüreklerinin inadı uyarınca davrandılar. Ben de uymalarını buyurduğum, ama uymadıkları bu antlaşmada açıklanan bütün lanetleri başlarına getirdim.› ››'),
(2002558,68,24,11,9,'RAB bana dedi ki, ‹‹Yahuda halkıyla Yeruşalimde yaşayanlar bana düzen kuruyorlar.'),
(2002559,68,24,11,10,'Sözlerimi dinlemek istemeyen atalarının suçlarına döndüler. Başka ilahların ardınca gidip onlara taptılar. İsrail halkıyla Yahuda halkı, atalarıyla yaptığım antlaşmayı bozdu.'),
(2002560,68,24,11,11,'Bu yüzden RAB, ‹Kaçıp kurtulamayacakları bir yıkım getireceğim başlarına› diyor, ‹Bana yakarsalar da onları dinlemeyeceğim.'),
(2002561,68,24,11,12,'Yahuda kentlerinde oturan halk da Yeruşalimde yaşayanlar da gidip buhur yaktıkları ilahlara yalvaracaklar. Ama yıkım geldiğinde, bu ilahlar onlara yardım edemez.'),
(2002562,68,24,11,13,'Kentlerinin sayısı kadar ilahın var, ey Yahuda! O utanılası ilaha, Baala buhur yakmak için Yeruşalim sokaklarının sayısı kadar sunak kurdunuz.'),
(2002563,68,24,11,14,'‹‹Sana gelince, ey Yeremya, bu halk için yalvarma; ne yakar ne de dilekte bulun. Sıkıntılı zamanlarında beni çağırdıklarında onları dinlemeyeceğim.'),
(2002564,68,24,11,15,'‹‹Sevgilim kötü düzenler kuruyor, 2 Öyleyse tapınağımda işi ne? 2 Adaklar ve kutsanmış et uğrayacağın felaketi önleyebilir mi? 2 Felaket gelince sevinecek misin?››'),
(2002565,68,24,11,16,'RAB sana meyvesi ve biçimi güzel, 2 Yaprağı bol zeytin ağacı adını vermişti. 2 Ama güçlü fırtına koptuğunda 2 Ağacı tutuşturacak; 2 Dalları kırılacak.'),
(2002566,68,24,11,17,'Seni dikmiş olan Her Şeye Egemen RAB, 2 Başına felaket getirmeye karar verdi. 2 Çünkü İsrail ve Yahuda halkları 2 Kötülük yaptı, 2 Baala buhur yakarak beni öfkelendirdiler.'),
(2002567,68,24,11,18,'Benim için kurdukları düzeni RAB bana açıkladı. Haberim vardı, çünkü ne yaptıklarını bana gösterdi.'),
(2002568,68,24,11,19,'Kesime götürülen uysal bir kuzu gibiydim. Bana düzen kurduklarını anlamamıştım. Şöyle diyorlardı: ‹‹Ağacı da meyvesini de yok edelim, 2 Bir daha adı anılmasın diye 2 Onu yaşayanlar diyarından kesip atalım.››'),
(2002569,68,24,11,20,'Adaletle yargılayan, 2 Yüreği ve düşünceyi sınayan, 2 Her Şeye Egemen RAB, 2 Davamı senin eline bırakıyorum. 2 Onlardan alacağın öcü göreyim!'),
(2002570,68,24,11,21,'‹‹Seni öldürmek isteyen Anatot halkı için RAB diyor ki, ‹Onlar, RABbin adına peygamberlik etme, yoksa seni öldürürüz diyorlardı.›'),
(2002571,68,24,11,22,'Her Şeye Egemen RAB, ‹Onları cezalandıracağım› diyor, ‹Gençleri kılıçtan geçirilecek, oğullarıyla kızları kıtlıktan ölecek.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002572,68,24,11,23,'Sağ kalan olmayacak. Cezalandırılacakları yıl Anatot halkının başına felaket getireceğim.› ››'),
(2002573,68,24,12,1,'Davamı önüne getirsem, 2 Haklı çıkarsın, ya RAB. 2 Ama adalet konusunda 2 Seninle tartışmak istiyorum. 2 Neden kötülerin işi iyi gidiyor? 2 Neden hainler tasasızca yaşıyor?'),
(2002574,68,24,12,2,'Onları sen diktin, kök saldılar, 2 Büyüyüp ürün verdiler. 2 Adın ağızlarından düşmüyor, 2 Yürekleriyse senden uzak.'),
(2002575,68,24,12,3,'Beni tanırsın, ya RAB, 2 Beni görür, yüreğimin seninle olduğunu bilirsin. 2 Kasaplık koyun gibi ayır onları, 2 Kesim gününe hazırla!'),
(2002576,68,24,12,4,'İçinde yaşayanların kötülüğü yüzünden, 2 Ülke ne zamana dek yas tutacak, 2 Otlar ne zamana dek sararıp solacak? 2 Hayvanlarla kuşlar yok oldu. 2 Çünkü bu halk, 2 ‹‹O başımıza neler geleceğini görmüyor›› dedi.'),
(2002577,68,24,12,5,'‹‹Ey Yeremya, 2 İnsanlarla yarışa girip yoruldunsa, 2 Atlarla nasıl yarışacaksın? 2 Güvenli bir ülkede sendelersen, 2 Şeria çalılıklarıyla nasıl başa çıkacaksın?'),
(2002578,68,24,12,6,'Kardeşlerin, öz ailen bile sana ihanet etti, 2 Arkandan seslerini yükselttiler. 2 Yüzüne karşı olumlu konuşsalar bile onlara güvenme.'),
(2002579,68,24,12,7,'Evimi terk ettim, 2 Mirasımı reddettim, 2 Sevgilimi düşmanlarının eline verdim.'),
(2002580,68,24,12,8,'Mirasım karşımda 2 Ormandaki aslan gibi oldu; 2 Kükreyip üzerime saldırdı. 2 Bu yüzden ondan nefret ediyorum.'),
(2002581,68,24,12,9,'Mirasım sırtlan ya da yırtıcı kuş mu oldu karşımda? 2 Çevresindeki yırtıcı kuşlar saldırıyor ona. 2 Gidin, bütün yabanıl hayvanları toplayıp getirin, 2 Yiyip bitirsinler onu.'),
(2002582,68,24,12,10,'Pek çok çoban bağımı bozdu, 2 Tarlamı çiğnedi, 2 Güzelim tarlamı ıssız çöle döndürdü.'),
(2002583,68,24,12,11,'Onu viraneye çevirdiler, 2 Önümde viran olmuş ağlıyor; 2 Bütün ülke viran olmuş, 2 Yine de aldıran yok.'),
(2002584,68,24,12,12,'Çöldeki çıplak tepelere 2 Yıkıcılar geldi. 2 RABbin kılıcı ülkeyi 2 Bir uçtan bir uca yiyip bitiriyor. 2 Kimse kavuşmayacak esenliğe.'),
(2002585,68,24,12,13,'Halkım buğday ekip diken biçti, 2 Emek verip yarar görmedi. 2 RABbin kızgın öfkesi yüzünden 2 Ürününüzden utanacaksınız.››'),
(2002586,68,24,12,14,'RAB diyor ki, ‹‹Halkım İsraile verdiğim mülke el koyan bütün kötü komşularımı ülkelerinden söküp atacak, Yahuda halkını da atacağım.'),
(2002587,68,24,12,15,'Hepsini söküp attıktan sonra Yahudaya yine acıyacak, her birini kendi mülküne, kendi ülkesine geri getireceğim.'),
(2002588,68,24,12,16,'Halkıma Baalın adıyla ant içmeyi öğrettiler. Bunun gibi, halkımın yolunda yürümeyi ve ‹RABbin varlığı hakkı için› diyerek benim adımla ant içmeyi de iyice öğrenirlerse, halkımın arasında sağlam yerleri olacak.'),
(2002589,68,24,12,17,'Ama kulak asmayan her ulusu kökünden söküp atacak, yok edeceğim›› diyor RAB.'),
(2002590,68,24,13,1,'RAB bana, ‹‹Git, kendine keten bir kuşak satın alıp beline sar, ama suya sokma›› dedi.'),
(2002591,68,24,13,2,'RABbin buyruğu uyarınca bir kuşak satın alıp belime sardım.'),
(2002592,68,24,13,3,'RAB bana ikinci kez seslendi:'),
(2002593,68,24,13,4,'‹‹Satın aldığın belindeki kuşağı al, Perata git. Kuşağı orada bir kaya kovuğuna gizle.››'),
(2002594,68,24,13,5,'RABbin buyruğu uyarınca gidip kuşağı Perata yakın bir yere gizledim.'),
(2002595,68,24,13,6,'Uzun süre sonra RAB bana, ‹‹Kalk, Perata git, gizlemeni buyurduğum kuşağı al›› dedi.'),
(2002596,68,24,13,7,'Bunun üzerine Perata gittim, gizlediğim yeri kazıp kuşağı aldım. Ancak kuşak çürümüştü, hiçbir işe yaramazdı.'),
(2002597,68,24,13,8,'RAB bana şöyle seslendi:'),
(2002598,68,24,13,9,'‹‹RAB diyor ki, ‹İşte Yahudanın gururunu da Yeruşalimin büyük gururunu da böyle çürüteceğim.'),
(2002599,68,24,13,10,'Sözümü dinlemek istemeyen, yüreklerinin inadı uyarınca davranan, başka ilahları izleyip onlara kulluk eden, tapan bu kötü halk, bu işe yaramaz kuşak gibi olacak.'),
(2002600,68,24,13,11,'Kuşak insanın beline nasıl yapışırsa, ben de İsrail ve Yahuda halklarını kendime öyle yapıştırdım› diyor RAB, ‹Öyle ki, bana ün, övgü, onur getirecek bir halk olsunlar. Ama dinlemediler.› ››'),
(2002601,68,24,13,12,'‹‹Onlara de ki, ‹İsrailin Tanrısı RAB, Her tulum şarapla dolacak, diyor.› Eğer sana, ‹Her tulumun şarapla dolacağını bilmiyor muyuz sanki?› derlerse,'),
(2002602,68,24,13,13,'onlara de ki, ‹Bu ülkede yaşayan herkesi -Davutun tahtında oturan kralları, kâhinleri, peygamberleri, Yeruşalimde yaşayanların tümünü- sarhoş olana dek şarapla dolduracağım› diyor RAB.'),
(2002603,68,24,13,14,'‹Onları -babalarla çocukları- birbirlerine çarpacağım. Acımadan, esirgemeden, sevecenlik göstermeden hepsini yok edeceğim› diyor RAB.››'),
(2002604,68,24,13,15,'Dinleyin, kulak verin, 2 Gururlanmayın, 2 Çünkü RAB konuştu.'),
(2002605,68,24,13,16,'Karanlık basmadan, 2 Kararan dağlarda 2 Ayaklarınız tökezlemeden 2 Tanrınız RABbi onurlandırın. 2 Siz ışık beklerken, 2 RAB onu kopkoyu, zifiri karanlığa çevirecek.'),
(2002606,68,24,13,17,'Ama bu uyarıyı dinlemezseniz, 2 Gururunuz yüzünden ağlayacağım gizlice, 2 Gözlerim acı acı gözyaşı dökecek, 2 Gözyaşlarım sel gibi akacak. 2 Çünkü RABbin sürüsü sürgüne gönderilecek.'),
(2002607,68,24,13,18,'Krala ve ana kraliçeye söyle: 2 ‹‹Tahtlarınızdan inin, 2 Çünkü görkemli taçlarınız başınızdan düştü.››'),
(2002608,68,24,13,19,'Negevdeki kentler kapanacak, 2 Onları açan olmayacak. 2 Sürgüne gönderilecek Yahuda, 2 Tamamı sürgüne gönderilecek.'),
(2002609,68,24,13,20,'Gözlerinizi kaldırıp bakın, 2 Kuzeyden gelenleri görün. 2 Nerede sana emanet edilen sürü? 2 Övündüğün kuzular nerede?'),
(2002610,68,24,13,21,'Sana dost olması için yetiştirdiğin kişileri 2 RAB başına yönetici atayınca ne diyeceksin? 2 Doğuran kadının çektiği sancı gibi 2 Seni de ağrı tutmayacak mı?'),
(2002611,68,24,13,22,'‹‹Neden bütün bunlar başıma geldi?›› dersen, 2 Günahlarının çokluğu yüzünden eteklerin açıldı, 2 Tecavüze uğradın.'),
(2002612,68,24,13,23,'Kûşlu derisinin rengini, 2 Pars beneklerini değiştirebilir mi? 2 Kötülük etmeye alışmış olan sizler de iyilik edemezsiniz.'),
(2002613,68,24,13,24,'‹‹Çöl rüzgarının savurduğu saman çöpü gibi 2 Dağıtacağım sizleri.'),
(2002614,68,24,13,25,'Payın, sana ayırdığım pay bu olacak›› diyor RAB. 2 ‹‹Çünkü beni unuttun, 2 Sahte ilahlara güvendin.'),
(2002615,68,24,13,26,'Ayıbın ortaya çıksın diye 2 Eteklerini yüzüne dek kaldıracağım.'),
(2002616,68,24,13,27,'Kırdaki tepeler üzerinde 2 Yaptığın iğrençlikleri -zinalarını, 2 Çapkın çapkın kişneyişini, yüzsüz fahişeliklerini- gördüm. 2 Vay başına geleceklere, ey Yeruşalim! 2 Ne zamana dek böyle kirli kalacaksın?››'),
(2002617,68,24,14,1,'RAB kuraklığa ilişkin Yeremyaya şöyle seslendi:'),
(2002618,68,24,14,2,'‹‹Yahuda yas tutuyor, 2 Kentleri bitkin; 2 Halkı karalar giymiş, yerlere oturmuş, 2 Yeruşalimin haykırışı yükseliyor.'),
(2002619,68,24,14,3,'Soylular uşaklarını suya gönderiyorlar. 2 Sarnıçlara gidiyor, ama su bulamıyor, 2 Kapları boş dönüyorlar. 2 Aşağılanmış, utanç içinde, 2 Başlarını örtüyorlar.'),
(2002620,68,24,14,4,'Ülke yağmursuz, toprak çatlamış, 2 Irgatlar utanç içinde başlarını örtüyorlar.'),
(2002621,68,24,14,5,'Kırdaki geyik bile 2 Yeni doğmuş yavrusunu bırakıyor, 2 Çünkü ot yok.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002622,68,24,14,6,'Yaban eşekleri çıplak tepelerde durmuş, 2 Çakal gibi soluyorlar; 2 Gözlerinin feri sönmüş, 2 Çünkü otlak yok.››'),
(2002623,68,24,14,7,'Suçlarımız bize karşı tanıklık etse de, 2 Adın uğruna bir şeyler yap, ya RAB! 2 Pek çok döneklik ettik, 2 Sana karşı günah işledik.'),
(2002624,68,24,14,8,'Ey İsrailin Umudu, 2 Sıkıntı anlarındaki Kurtarıcısı! 2 Neden ülkede bir yabancı, 2 Ancak bir gece konaklayan yolcu gibisin?'),
(2002625,68,24,14,9,'Neden şaşırmış biri gibi, 2 Kurtarmaya gücü yetmeyen savaşçı gibisin? 2 Aramızdasın sen, ya RAB, 2 Seniniz, bırakma bizi!'),
(2002626,68,24,14,10,'Bu halk için RAB diyor ki, 2 ‹‹Gezip tozmayı pek sever, 2 Ayaklarını dolaşmaktan esirgemezler. 2 Bu yüzden RAB onlardan hoşnut değil, 2 Şimdi anımsayacak suçlarını, 2 Günahları için onları cezalandıracak.››'),
(2002627,68,24,14,11,'Sonra RAB bana, ‹‹Bu halkın iyiliği için yalvarma›› dedi,'),
(2002628,68,24,14,12,'‹‹Oruç tutsalar bile feryatlarına kulak vermeyeceğim. Yakmalık sunu, tahıl sunusu sunsalar bile kabul etmeyeceğim. Tersine, kılıçla, kıtlıkla, salgın hastalıkla yok edeceğim onları.››'),
(2002629,68,24,14,13,'Bunun üzerine, ‹‹Ah, Egemen RAB, peygamberler bu halka, ‹Kılıç yüzü görmeyecek, kıtlık çekmeyeceksiniz; burada size kalıcı esenlik sağlayacağım› diyorlar›› dedim.'),
(2002630,68,24,14,14,'RAB, ‹‹Peygamberler benim adımla yalan peygamberlik ediyorlar›› dedi, ‹‹Onları ne gönderdim, ne onlara buyruk verdim, ne de seslendim. Size uydurma görümlerden, falcılıktan, boş şeylerden, akıllarından geçen hayallerden söz ediyorlar.'),
(2002631,68,24,14,15,'Adımla konuşan peygamberler için ben RAB diyorum ki, onları göndermediğim halde, ‹Bu ülkede kılıç da kıtlık da olmayacak› diyorlar. Ama kendileri de kılıçla, kıtlıkla yok olacaklar.'),
(2002632,68,24,14,16,'Peygamberlik ettikleri halk da kıtlık ve kılıç yüzünden Yeruşalim sokaklarına atılacak. Onları da karılarını, oğullarını, kızlarını da gömecek kimse olmayacak. Yaptıkları kötülüğü kendi başlarına getireceğim.'),
(2002633,68,24,14,17,'‹‹Onlara de ki, ‹‹ ‹Gözlerim gece gündüz 2 Durmadan gözyaşı döksün, 2 Çünkü erden kızım, halkım 2 Ağır bir yara aldı, 2 Ezici bir darbe yedi.'),
(2002634,68,24,14,18,'Kıra çıksam, kılıçtan geçirilenleri, 2 Kente girsem, kıtlıktan kırılanları görüyorum. 2 Olup bitenden habersiz peygamberlerle kâhinlerse 2 Ülkeyi dolaşıp duruyorlar.› ››'),
(2002635,68,24,14,19,'Yahudayı büsbütün mü reddettin? 2 Siyondan tiksiniyor musun? 2 Neden şifa bulmayacak kadar yaraladın bizi? 2 Esenlik bekledik, iyilik gelmedi. 2 Şifa umduk, yılgınlık bulduk.'),
(2002636,68,24,14,20,'Yaptığımız kötülükleri, 2 Atalarımızın suçlarını biliyoruz, ya RAB; 2 Gerçekten sana karşı günah işledik.'),
(2002637,68,24,14,21,'Adın uğruna bizi küçümseme, 2 Görkemli tahtının hor görülmesine izin verme. 2 Bizimle yaptığın antlaşmayı anımsa, 2 Bozma onu.'),
(2002638,68,24,14,22,'Ulusların değersiz putlarından herhangi biri 2 Yağmur yağdırabilir mi? 2 Gökler kendiliğinden 2 Sağanak yağdırabilir mi? 2 Bunu yalnız sen yapabilirsin, 2 Ya RAB Tanrımız. 2 Umudumuz sende, 2 Çünkü bütün bunları yapan sensin.'),
(2002639,68,24,15,1,'RAB bana dedi ki, ‹‹Musayla Samuel önümde durup yalvarsalar bile, bu halka acımayacağım; kov onları önümden, gitsinler!'),
(2002640,68,24,15,2,'Sana, ‹Nereye gidelim?› diye sorarlarsa de ki, ‹RAB şöyle diyor: ‹‹ ‹Ölüm için ayrılanlar ölüme, 2 Kılıç için ayrılanlar kılıca, 2 Kıtlık için ayrılanlar kıtlığa, 2 Sürgün için ayrılanlar sürgüne.›'),
(2002641,68,24,15,3,'‹‹Onların başına dört tür yıkım getirmeye karar verdim›› diyor RAB, ‹‹Öldürmek için kılıcı, paralamak için köpekleri, yiyip bitirmek, yok etmek için yırtıcı kuşlarla yabanıl hayvanları salacağım üzerlerine.'),
(2002642,68,24,15,4,'Yahuda Kralı Hizkiya oğlu Manaşşenin Yeruşalimde yaptıkları yüzünden bütün yeryüzü krallıklarını dehşete düşüreceğim.'),
(2002643,68,24,15,5,'‹‹Kim acıyacak sana, ey Yeruşalim? 2 Kim yas tutacak senin için? 2 Hal hatır sormak için 2 Kim yolundan dönüp sana gelecek?'),
(2002644,68,24,15,6,'Sen beni reddettin›› diyor RAB, 2 ‹‹Gerisingeri gidiyorsun. 2 Ben de elimi sana karşı kaldıracak, 2 Seni yok edeceğim; 2 Merhamet ede ede yoruldum.'),
(2002645,68,24,15,7,'Ülkenin kapılarında, 2 Halkımı yabayla savuracak, 2 Çocuksuz bırakacak, yok edeceğim; 2 Çünkü yollarından dönmediler.'),
(2002646,68,24,15,8,'Dul kadınlarının sayısı denizin kumundan çok olacak. 2 Gençlerinin annelerine 2 Öğle vakti yok ediciyi göndereceğim; 2 Üzerlerine ansızın acı, dehşet salacağım.'),
(2002647,68,24,15,9,'Yedi çocuklu kadın 2 Bayılıp son soluğunu verecek; 2 Daha gündüzken güneşi batacak, 2 Utandırılıp alçaltılacak. 2 Sağ kalanları düşmanlarının önünde 2 Kılıca teslim edeceğim.›› 2 Böyle diyor RAB.'),
(2002648,68,24,15,10,'Vay başıma! 2 Herkesle çekişip davacı olayım diye 2 Doğurmuşsun beni, ey annem! 2 Ne ödünç aldım, ne de verdim, 2 Yine de herkes lanet okuyor bana.'),
(2002649,68,24,15,11,'RAB şöyle dedi: 2 ‹‹Kuşkun olmasın, iyilik için seni özgür kılacağım, 2 Yıkım ve sıkıntı zamanında 2 Düşmanlarını sana yalvartacağım.'),
(2002650,68,24,15,12,'‹‹Demiri, kuzeyden gelen demiri 2 Ya da tuncu kimse kırabilir mi?'),
(2002651,68,24,15,13,'Ülkende işlenen günahlar yüzünden 2 Servetini de hazinelerini de karşılıksız, 2 Çapul malı olarak vereceğim.'),
(2002652,68,24,15,14,'Bilmediğin bir ülkede 2 Düşmanlarına köle edeceğim seni. 2 Çünkü size karşı öfkem 2 Ateş gibi tutuşup yanacak.›› ‹‹Geçireceğim›› (bkz. 17:4).'),
(2002653,68,24,15,15,'Sen bilirsin, ya RAB, 2 Beni anımsa, beni kolla. 2 Bana eziyet edenlerden öcümü al. 2 Sabrınla beni canımdan etme, 2 Senin uğruna aşağılandığımı unutma.'),
(2002654,68,24,15,16,'Sözlerini bulur bulmaz yuttum, 2 Bana neşe, yüreğime sevinç oldu. 2 Çünkü seninim ben, 2 Ya RAB, Her Şeye Egemen Tanrı!'),
(2002655,68,24,15,17,'Eğlenenlerin arasında oturmadım, 2 Onlarla sevinip coşmadım. 2 Elin üzerimde olduğu için 2 Tek başıma oturdum, 2 Çünkü beni öfkeyle doldurmuştun.'),
(2002656,68,24,15,18,'Neden sürekli acı çekiyorum? 2 Neden yaram ağır ve umarsız? 2 Benim için aldatıcı bir dere, 2 Güvenilmez bir pınar mı olacaksın?'),
(2002657,68,24,15,19,'Bu yüzden RAB diyor ki, 2 ‹‹Eğer dönersen seni yine hizmetime alırım; 2 İşe yaramaz sözler değil, 2 Değerli sözler söylersen, 2 Benim sözcüm olursun. 2 Bu halk sana dönecek, 2 Ama sen onlara dönmemelisin.'),
(2002658,68,24,15,20,'Bu halkın karşısında 2 Sağlamlaştırılmış tunç bir duvar kılacağım seni; 2 Seninle savaşacak ama yenemeyecekler, 2 Çünkü yardım etmek, kurtarmak için 2 Ben seninleyim›› diyor RAB.'),
(2002659,68,24,15,21,'‹‹Seni kötünün elinden kurtaracak, 2 Acımasızın avucundan kurtaracağım.››'),
(2002660,68,24,16,1,'RAB bana şöyle seslendi:'),
(2002661,68,24,16,2,'‹‹Kendine karı alma, burada oğulların, kızların olmasın.››'),
(2002662,68,24,16,3,'Bu ülkede doğan oğullarla kızlar ve anne babaları için RAB diyor ki,'),
(2002663,68,24,16,4,'‹‹Ölümcül hastalıklardan ölecekler. Onlar için yas tutulmayacak, gömülmeyecekler. Cesetleri toprağın üzerinde gübre gibi kalacak. Kılıçla, kıtlıkla yok olacaklar; cesetleri yırtıcı kuşlara, yabanıl hayvanlara yem olacak.››'),
(2002664,68,24,16,5,'Çünkü RAB diyor ki, ‹‹Cenaze yemeğinin verildiği eve gitme, dövünmek için gitme, başsağlığı dileme. Çünkü ben bu halktan esenliğimi, sevgimi, sevecenliğimi geri çektim›› diyor RAB.'),
(2002665,68,24,16,6,'‹‹Bu ülkede büyükler de küçükler de ölecek, gömülmeyecekler. Onlar için yas tutan, dövünüp bedenini yaralayan, başını tıraş eden olmayacak.'),
(2002666,68,24,16,7,'Ölene yas tutanı avutmak için kimse onunla yemek yemeyecek. Anne babasını yitirene kimse avunç kâsesini sunmayacak.'),
(2002667,68,24,16,8,'‹‹Şölen evine de gitme, onlarla oturma, yiyip içme.'),
(2002668,68,24,16,9,'Çünkü İsrailin Tanrısı, Her Şeye Egemen RAB diyor ki, ‹Burada sevinç ve neşe sesine, gelin güvey sesine senin günlerinde gözünün önünde son vereceğim.›'),
(2002669,68,24,16,10,'‹‹Bütün bunları bu halka bildirdiğinde, ‹RAB neden başımıza bu büyük felaketi getireceğini bildirdi? Suçumuz ne? Tanrımız RABbe karşı işlediğimiz günah ne?› diye sorarlarsa,'),
(2002670,68,24,16,11,'de ki, ‹Atalarınız beni terk etti› diyor RAB, ‹Başka ilahların ardınca gittiler, onlara kulluk edip taptılar. Beni terk ettiler, Kutsal Yasama uymadılar.'),
(2002671,68,24,16,12,'Sizse atalarınızdan daha çok kötülük yaptınız. Beni dinleyeceğinize, kötü yüreğinizin inadı uyarınca davrandınız.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002672,68,24,16,13,'Bu yüzden sizi bu ülkeden sizin de atalarınızın da bilmediği bir ülkeye atacağım. Orada gece gündüz başka ilahlara kulluk edeceksiniz, çünkü size lütfetmeyeceğim.›'),
(2002673,68,24,16,14,'‹‹Artık insanların, ‹İsrail halkını Mısırdan çıkaran RABbin varlığı hakkı için› demeyeceği günler geliyor›› diyor RAB.'),
(2002674,68,24,16,15,'‹‹Bunun yerine, ‹İsrail halkını kuzey ülkesinden ve sürdüğü bütün öbür ülkelerden geri getiren RABbin varlığı hakkı için› diyecekler. Çünkü atalarına vermiş olduğum topraklara onları geri getireceğim.'),
(2002675,68,24,16,16,'‹‹Birçok balıkçı çağırmak üzereyim. Onları yakalayacaklar›› diyor RAB, ‹‹Ardından birçok avcı çağıracağım. Her dağın, her tepenin üzerinden, kaya kovuklarından avlayacaklar onları.'),
(2002676,68,24,16,17,'Bütün yaptıklarını görüyorum; hiçbiri benden gizli değil. Günahları da gözümden kaçmıyor.'),
(2002677,68,24,16,18,'İlkin suçlarını, günahlarını iki katıyla onlara ödeteceğim. Çünkü tiksindirici cansız ilahlarıyla ülkemi kirlettiler, mülkümü iğrenç putlarıyla doldurdular.'),
(2002678,68,24,16,19,'‹‹Ya RAB, sen benim gücüm, 2 Kalem, sıkıntı gününde sığınağımsın. 2 Dünyanın dört bucağından 2 Uluslar sana gelip, 2 ‹Atalarımız yalnız yalanları, 2 Kendilerine hiçbir yararı olmayan 2 Değersiz putları miras aldılar› diyecekler,'),
(2002679,68,24,16,20,'‹İnsan kendine ilah yapar mı? 2 Onlar ilah değil ki!›'),
(2002680,68,24,16,21,'‹‹Onun için bu kez onlara 2 Gücümü, kudretimi tanıtacağım. 2 O zaman adımın RAB olduğunu anlayacaklar.››'),
(2002681,68,24,17,1,'‹‹Yahudanın günahı demir kalemle yazıldı; 2 Yüreklerinin levhaları, 2 Sunaklarının boynuzları üzerine 2 Elmas uçlu aletle oyuldu.'),
(2002682,68,24,17,2,'Bol yapraklı her ağacın yanında, 2 Her yüksek tepedeki sunaklarla, 2 Aşera putlarıyla 2 Çocuklarıymış gibi ilgileniyorlar.'),
(2002683,68,24,17,3,'Ey kırdaki dağım, ülkende işlenen günahlar yüzünden 2 Servetini, bütün hazinelerini 2 Ve puta tapılan yerlerini bırakacağım, yağmalansın.'),
(2002684,68,24,17,4,'Sana verdiğim mülkü kendi suçunla yitireceksin. 2 Bilmediğin bir ülkede 2 Düşmanlarına köle edeceğim seni. 2 Çünkü öfkemi alevlendirdiniz, 2 Tutuşup sonsuza dek yanacak.››'),
(2002685,68,24,17,5,'RAB diyor ki, 2 ‹‹İnsana güvenen, 2 İnsanın gücüne dayanan, 2 Yüreği RABden uzaklaşan kişi lanetlidir.'),
(2002686,68,24,17,6,'Böylesi bozkırdaki çalı gibidir, 2 İyilik geldiği zaman görmeyecek; 2 Kurak çöle, 2 Kimsenin yaşamadığı tuzlaya yerleşecek.'),
(2002687,68,24,17,7,'‹‹Ne mutlu RABbe güvenen insana, 2 Güveni yalnız RAB olana!'),
(2002688,68,24,17,8,'Böylesi su kıyılarına dikilmiş ağaca benzer, 2 Köklerini akarsulara salar. 2 Sıcak gelince korkmaz, 2 Yaprakları hep yeşildir. 2 Kuraklık yılında kaygılanmaz, 2 Meyve vermekten geri durmaz.››'),
(2002689,68,24,17,9,'Yürek her şeyden daha aldatıcıdır, iyileşmez, 2 Onu kim anlayabilir?'),
(2002690,68,24,17,10,'‹‹Ben RAB, herkesi davranışlarına, 2 Yaptıklarının sonucuna göre ödüllendirmek için 2 Yüreği yoklar, düşünceyi denerim.››'),
(2002691,68,24,17,11,'Yumurtlamadığı yumurtaların üzerinde oturan keklik nasılsa, 2 Haksız servet edinen kişi de öyledir. 2 Yaşamının ortasında serveti onu bırakır, 2 Yaşamının sonunda kendisi aptal çıkar.'),
(2002692,68,24,17,12,'Tapınağımızın yeri 2 Başlangıçtan yüceltilmiş görkemli bir tahttır.'),
(2002693,68,24,17,13,'Ey İsrailin umudu RAB, 2 Seni bırakanların hepsi 2 Utanılacak duruma düşecek. 2 Sana sırtını dönenler toprağa yazılacak, 2 Çünkü RABbi, diri su pınarını bıraktılar.'),
(2002694,68,24,17,14,'Şifa ver bana, ya RAB, 2 O zaman iyi olurum; 2 Kurtar beni, kurtuluş bulurum, 2 Çünkü övgüm sensin.'),
(2002695,68,24,17,15,'Bana, ‹‹Hani, RABbin sözü nerede? 2 Haydi, gelsin yerine bakalım›› deyip duruyorlar.'),
(2002696,68,24,17,16,'Senin hizmetinde çoban olmaktan kaçınmadım, 2 Felaket gününü de ben istemedim. 2 Dudaklarımdan çıkan her sözü bilirsin, ya RAB. 2 O söz zaten senin ağzındaydı.'),
(2002697,68,24,17,17,'Dehşet verme bana, 2 Felaket gününde sığınağım sensin.'),
(2002698,68,24,17,18,'Bana eziyet edenler utandırılsın, 2 Ama beni utandırma; 2 Onları yılgınlığa düşür, 2 Ama beni düşürme. 2 Felaket gününü getir üzerlerine, 2 Onları iki kat yıkımla ez.'),
(2002699,68,24,17,19,'RAB bana şöyle dedi: ‹‹Yahuda krallarının girip çıktığı Halk Kapısına ve Yeruşalimin öbür kapılarına git, orada dur.'),
(2002700,68,24,17,20,'Halka de ki, ‹Ey Yahuda kralları, Yahuda halkı, Yeruşalimde oturup bu kapılardan girenler, RABbin sözünü dinleyin!'),
(2002701,68,24,17,21,'RAB diyor ki, Şabat Günü yük taşımamaya, Yeruşalim kapılarından içeri bir şey sokmamaya dikkat edin.'),
(2002702,68,24,17,22,'Şabat Günü evinizden yük çıkarmayın, hiç iş yapmayın. Atalarınıza buyurduğum gibi Şabat Gününü kutsal sayacaksınız.'),
(2002703,68,24,17,23,'Ne var ki, onlar sözümü dinlemediler, kulak asmadılar. Dikbaşlılık ederek beni dinlemediler, yola gelmek istemediler.'),
(2002704,68,24,17,24,'Beni iyi dinlerseniz, diyor RAB, Şabat Günü bu kentin kapılarından yük taşımayıp hiç iş yapmayarak Şabat Gününü kutsal sayarsanız,'),
(2002705,68,24,17,25,'Davutun tahtında oturan krallarla önderler savaş arabalarına, atlara binip Yahuda halkı ve Yeruşalimde yaşayanlarla birlikte bu kentin kapılarından girecekler. Bu kentte sonsuza dek insanlar yaşayacak.'),
(2002706,68,24,17,26,'Yahuda kentlerinden, Yeruşalim çevresinden, Benyamin topraklarından, Şefeladan, dağlık bölgeden, Negevden gelip RABbin Tapınağına yakmalık sunular, kurbanlar, tahıl sunuları, günnük ve şükran sunuları getirecekler.'),
(2002707,68,24,17,27,'Ancak beni dinlemez, Şabat Günü Yeruşalim kapılarından yük taşıyarak girer, o günü kutsal saymazsanız, kentin kapılarını ateşe vereceğim. Yeruşalim saraylarını yakıp yok edecek, hiç sönmeyecek ateş.› ››'),
(2002708,68,24,18,1,'RAB Yeremyaya şöyle seslendi:'),
(2002709,68,24,18,2,'‹‹Kalk, çömlekçinin işliğine git; orada sana sesleneceğim.››'),
(2002710,68,24,18,3,'Bunun üzerine çömlekçinin işliğine gittim. Çark üzerinde çalışıyordu.'),
(2002711,68,24,18,4,'Yaptığı balçıktan kap elinde bozulunca çömlekçi balçığa istediği biçimi vererek başka bir kap yaptı.'),
(2002712,68,24,18,5,'RAB bana yine seslendi:'),
(2002713,68,24,18,6,'‹‹Bu çömlekçinin yaptığını ben de size yapamaz mıyım, ey İsrail halkı? diyor RAB. Çömlekçinin elinde balçık neyse, siz de benim elimde öylesiniz, ey İsrail halkı!'),
(2002714,68,24,18,7,'Bir ulusun ya da krallığın kökünden söküleceğini, yıkılıp yok edileceğini duyururum da,'),
(2002715,68,24,18,8,'uyardığım ulus kötülüğünden dönerse, başına felaket getirme kararımdan vazgeçerim.'),
(2002716,68,24,18,9,'Öte yandan, bir ulusun ya da krallığın kurulup dikileceğini duyururum da,'),
(2002717,68,24,18,10,'o ulus sözümü dinlemeyip gözümde kötü olanı yaparsa, ona söz verdiğim iyiliği yapmaktan vazgeçerim.'),
(2002718,68,24,18,11,'‹‹Bu nedenle Yahuda halkıyla Yeruşalimde yaşayanlara de ki, ‹RAB şöyle diyor: İşte size bir felaket tasarlıyor, size karşı bir düzen kuruyorum. Onun için her biriniz kötü yolundan dönsün, yaşantınızı da davranışlarınızı da düzeltin.›'),
(2002719,68,24,18,12,'Ama onlar, ‹Boş ver! Biz kendi tasarlarımızı sürdüreceğiz; her birimiz kötü yüreğinin inadı uyarınca davranacak› diyecekler.››'),
(2002720,68,24,18,13,'Bu yüzden RAB diyor ki, 2 ‹‹Uluslar arasında soruşturun: 2 Böylesini kim duydu? 2 Erden kız İsrail 2 Çok korkunç bir şey yaptı.'),
(2002721,68,24,18,14,'Kayalık bayırlardan 2 Lübnanın karı hiç eksik olur mu? 2 Uzaktan akan soğuk sular hiç kesilir mi?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002722,68,24,18,15,'Oysa halkım beni unuttu, 2 Değersiz ilahlara buhur yaktı. 2 Bu ilahlar gidecekleri yollarda, 2 Eski yollarda sendelemelerine neden oldu; 2 Onları sapa, bitmemiş yollarda yürüttü.'),
(2002723,68,24,18,16,'Ülkeleri viran edilecek, 2 Sürekli alay konusu olacak; 2 Oradan her geçen şaşkın şaşkın 2 Başını sallayacak.'),
(2002724,68,24,18,17,'Onları düşmanlarının önünde 2 Doğu rüzgarı gibi dağıtacağım; 2 Yıkım günü yüzümü değil, 2 Sırtımı çevireceğim onlara.››'),
(2002725,68,24,18,18,'Bunun üzerine, ‹‹Haydi, Yeremyaya karşı bir düzen kuralım!›› dediler, ‹‹Çünkü yasayı öğretecek kâhin, öğüt verecek bilge, Tanrı sözünü bildirecek peygamber hiç eksik olmayacak. Gelin, ona sözle saldıralım, söylediklerini de dinlemeyelim.››'),
(2002726,68,24,18,19,'Dinle beni, ya RAB, 2 Beni suçlayanların dediklerini işit!'),
(2002727,68,24,18,20,'İyiliğe karşı kötülük mü yapmalı? 2 Ama onlar bana çukur kazdılar. 2 Onlara duyduğun öfkeyi yatıştırmak, 2 Onların iyiliğini dilemek için 2 Senin önünde nasıl durduğumu anımsa.'),
(2002728,68,24,18,21,'Bu yüzden çocuklarını kıtlığa ver, 2 Kılıcın ağzına at. 2 Karıları çocuksuz, dul kalsın, 2 Erkeklerini ölüm alıp götürsün, 2 Gençleri savaşta kılıçtan geçirilsin.'),
(2002729,68,24,18,22,'Sen üzerlerine ansızın akıncılar gönderdiğinde, 2 Evlerinden çığlıklar duyulsun. 2 Çünkü beni yakalamak için çukur kazdılar, 2 Ayaklarıma gizli tuzak kurdular.'),
(2002730,68,24,18,23,'Beni öldürmek için kurdukları düzenlerin hepsini 2 Biliyorsun, ya RAB. 2 Bağışlama suçlarını, 2 Günahlarını önünden silme. 2 Yığılıp kalsınlar senin önünde. 2 Öfkeliyken uğraş onlarla.'),
(2002731,68,24,19,1,'RAB bana şöyle dedi: ‹‹Git, çömlekçiden bir çömlek satın al. Halkın ve kâhinlerin ileri gelenlerinden birkaçını yanına alıp'),
(2002732,68,24,19,2,'Harsit Kapısına yakın Ben-Hinnom Vadisine git. Sana söyleyeceklerimi orada duyur.'),
(2002733,68,24,19,3,'De ki, ‹RABbin sözünü dinleyin, ey Yahuda kralları ve Yeruşalimde yaşayanlar! İsrailin Tanrısı, Her Şeye Egemen RAB şöyle diyor: Dinleyin! Buraya, her duyanı şaşkına çevirecek bir felaket göndermek üzereyim.'),
(2002734,68,24,19,4,'Çünkü beni terk ettiler, burayı yabancı bir ülke haline getirdiler. Kendilerinin de atalarıyla Yahuda krallarının da tanımadığı başka ilahlara burada buhur yaktılar, burayı döktükleri suçsuz kanıyla doldurdular.'),
(2002735,68,24,19,5,'Çocuklarını ateşte Baala kurban etmek için tapınma yerleri kurdular. Böyle bir şey ne buyurdum ne sözünü ettim ne de aklımdan geçirdim.'),
(2002736,68,24,19,6,'Bundan ötürü buranın artık Tofet ya da Ben-Hinnom Vadisi değil, Kıyım Vadisi diye anılacağı günler geliyor, diyor RAB.'),
(2002737,68,24,19,7,'Yahuda ve Yeruşalimin tasarılarını burada boşa çıkaracağım. Onları canlarına susayanların eline verecek, düşmanlarının önünde kılıçla düşüreceğim. Cesetlerini yem olarak yırtıcı kuşlara, yabanıl hayvanlara vereceğim.'),
(2002738,68,24,19,8,'Bu kenti viraneye çevirecek, alay konusu edeceğim; oradan her geçen şaşkın şaşkın bakıp başına gelen belalardan ötürü onunla alay edecek.'),
(2002739,68,24,19,9,'Onlara oğullarının, kızlarının etini yedireceğim. Canlarına susamış düşmanları onları kuşattığında sıkıntıdan birbirlerini yiyecekler.›'),
(2002740,68,24,19,10,'‹‹O zaman seninle gidenlerin önünde çömleği kır'),
(2002741,68,24,19,11,'ve onlara de ki, ‹Her Şeye Egemen RAB şöyle diyor: Çömlekçinin çömleği nasıl kırılıp bir daha onarılamazsa, ben de bu halkı ve bu kenti öyle kıracağım. Ölüleri yer kalmayana dek Tofette gömecekler.'),
(2002742,68,24,19,12,'Bu kente de içinde yaşayanlara da böyle davranacağım, diyor RAB. Bu kenti Tofet gibi yapacağım.'),
(2002743,68,24,19,13,'Yeruşalimin evleri de Yahuda krallarının sarayları da Tofet gibi kirli sayılacak. Çünkü bu evlerin damlarında gök cisimlerine buhur yaktılar, başka ilahlara dökmelik sunular sundular.› ››'),
(2002744,68,24,19,14,'Peygamberlik etmesi için RABbin Tofete gönderdiği Yeremya oradan döndü. RABbin Tapınağının avlusunda durup halka şöyle dedi:'),
(2002745,68,24,19,15,'‹‹İsrail''in Tanrısı, Her Şeye Egemen RAB diyor ki, ‹İşte bu kente ve çevresindeki köylere sözünü ettiğim bütün felaketleri getireceğim. Çünkü dikbaşlılık edip sözümü dinlemediler.› ››'),
(2002746,68,24,20,1,'RABbin Tapınağının baş görevlisi İmmer oğlu Kâhin Paşhur, Yeremyanın böyle peygamberlik ettiğini duyunca,'),
(2002747,68,24,20,2,'onun dövülüp RABbin Tapınağının Yukarı Benyamin Kapısındaki tomruğa vurulmasını buyurdu.'),
(2002748,68,24,20,3,'Ertesi gün Paşhur kendisini tomruktan salıverince, Yeremya ona, ‹‹RAB sana Paşhur değil, Magor-Missaviv adını verdi›› dedi,'),
(2002749,68,24,20,4,'‹‹RAB diyor ki, ‹Seni de dostlarını da yıldıracağım. Dostlarının düşman kılıcıyla düştüğünü gözlerinle göreceksin. Bütün Yahudayı Babil Kralının eline teslim edeceğim; onları Babile sürecek ya da kılıçtan geçirecek.'),
(2002750,68,24,20,5,'Bu kentin bütün zenginliğini -ürününü, değerli eşyalarını, Yahuda krallarının hazinelerini- düşmanlarının eline vereceğim. Hepsini yağmalayıp Babile götürecekler.'),
(2002751,68,24,20,6,'Sana gelince, ey Paşhur, sen de evinde yaşayanların hepsi de Babile sürüleceksiniz. Sen de kendilerine yalan peygamberlik ettiğin bütün dostların da orada ölüp gömüleceksiniz.› ›› gelir. Aynı ifade 20:10da da geçer.'),
(2002752,68,24,20,7,'Beni kandırdın, ya RAB, 2 Ben de kandım. 2 Bana üstün geldin, beni yendin. 2 Bütün gün alay konusu oluyorum, 2 Herkes benimle eğleniyor.'),
(2002753,68,24,20,8,'Çünkü konuştukça feryat ediyor, 2 Şiddet diye, yıkım diye haykırıyorum. 2 RABbin sözü yüzünden bütün gün yeriliyor, 2 Gülünç duruma düşüyorum.'),
(2002754,68,24,20,9,'‹‹Bir daha onu anmayacak, 2 Onun adına konuşmayacağım›› desem, 2 Sözü kemiklerimin içine hapsedilmiş, 2 Yüreğimde yanan bir ateş sanki. 2 Onu içimde tutmaktan yoruldum, 2 Yapamıyorum artık.'),
(2002755,68,24,20,10,'Birçoğunun, ‹‹Her yer dehşet içinde! 2 Suçlayın! Suçlayalım onu!›› diye fısıldaştığını duydum. 2 Bütün güvendiğim insanlar düşmemi gözlüyor, 2 ‹‹Belki kanar, onu yeneriz, 2 Sonra da öcümüzü alırız›› diyorlar.'),
(2002756,68,24,20,11,'Ama RAB güçlü bir savaşçı gibi benimledir. 2 Bu yüzden bana eziyet edenler tökezleyecek, 2 Üstün gelemeyecek, 2 Başarısızlığa uğrayıp büyük utanca düşecekler; 2 Onursuzlukları sonsuza dek unutulmayacak.'),
(2002757,68,24,20,12,'Ey doğru kişiyi sınayan, 2 Yüreği ve düşünceyi gören Her Şeye Egemen RAB! 2 Davamı senin eline bırakıyorum. 2 Onlardan alacağın öcü göreyim!'),
(2002758,68,24,20,13,'Ezgiler okuyun RABbe! 2 Övün RABbi! 2 Çünkü yoksulun canını kötülerin elinden O kurtardı.'),
(2002759,68,24,20,14,'Lanet olsun doğduğum güne! 2 Kutlu olmasın annemin beni doğurduğu gün!'),
(2002760,68,24,20,15,'‹‹Bir oğlun oldu!›› diyerek babama haber getiren, 2 Onu sevince boğan adama lanet olsun!'),
(2002761,68,24,20,16,'RABbin acımadan yerle bir ettiği 2 Kentler gibi olsun o adam! 2 Sabah feryatlar, 2 Öğlen savaş naraları duysun!'),
(2002762,68,24,20,17,'Çünkü beni annemin rahminde öldürmedi; 2 Annem mezarım olur, 2 Rahmi hep gebe kalırdı.'),
(2002763,68,24,20,18,'Neden ana rahminden çıktım? 2 Dert, üzüntü görmek, 2 Ömrümü utanç içinde geçirmek için mi?'),
(2002764,68,24,21,1,'Kral Sidkiya Malkiya oğlu Paşhurla Maaseya oğlu Kâhin Sefanyayı Yeremyaya gönderince, RAB Yeremyaya seslendi. Paşhurla Sefanya ona şöyle demişti:'),
(2002765,68,24,21,2,'‹‹Lütfen bizim için RABbe danış. Çünkü Babil Kralı Nebukadnessar bize saldırıyor. Belki RAB bizim için şaşılacak işlerinden birini yapar da Nebukadnessar ülkemizden çekilir.››'),
(2002766,68,24,21,3,'Yeremya şu karşılığı verdi: ‹‹Sidkiyaya deyin ki,'),
(2002767,68,24,21,4,'‹İsrailin Tanrısı RAB şöyle diyor: Surların dışında sizi kuşatan Babil Kralı ve Kildanilerle savaşmakta kullandığınız silahları size karşı çevireceğim; hepsini bu kentin ortasına toplayacağım.'),
(2002768,68,24,21,5,'Ben de elimi size karşı kaldıracağım; kudretle, kızgınlıkla, gazapla, büyük öfkeyle sizinle savaşacağım.'),
(2002769,68,24,21,6,'Bu kentte yaşayanları yok edeceğim; insan da, hayvan da korkunç bir salgın hastalıktan ölecek.'),
(2002770,68,24,21,7,'Ondan sonra da, diyor RAB, Yahuda Kralı Sidkiyayla görevlilerini, bu kentte salgından, kılıçtan, kıtlıktan sağ çıkan halkı Babil Kralı Nebukadnessarın ve canlarına susamış düşmanlarının eline teslim edeceğim. Hepsini kılıçtan geçirecek, canlarını bağışlamayacak, merhamet etmeyecek, acımayacak.›'),
(2002771,68,24,21,8,'‹‹Bunun yanısıra halka şunları da söyle: ‹RAB diyor ki: İşte yaşama giden yolu da ölüme giden yolu da önünüze koyuyorum.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002772,68,24,21,9,'Bu kentte kalan kılıçtan, kıtlıktan, salgından ölecek; dışarı çıkıp kenti kuşatan Kildanilere teslim olansa yaşayacak, hiç değilse canını kurtarmış olacak.'),
(2002773,68,24,21,10,'Bu kente iyilik değil, kötülük etmeye karar verdim, diyor RAB. Bu kenti Babil Kralı ele geçirip ateşe verecek.› ››'),
(2002774,68,24,21,11,'‹‹Yahuda Kralının ailesine de ki, ‹RABbin sözünü dinleyin:'),
(2002775,68,24,21,12,'RAB şöyle diyor, ey Davut soyu: ‹‹ ‹Her sabah adaleti uygulayın, 2 Soyguna uğramış kişiyi zorbanın elinden kurtarın. 2 Yoksa yaptığınız kötülük yüzünden 2 Öfkem ateş gibi tutuşup yanacak, 2 Söndüren olmayacak.'),
(2002776,68,24,21,13,'Ey vadinin üstünde, 2 Kayalık ovada oturan Yeruşalim, 2 Sana karşıyım diyor RAB, 2 Siz ki, kim bize saldırabilir? 2 Sığınağımıza kim girebilir, diyorsunuz.'),
(2002777,68,24,21,14,'Sizi yaptıklarınıza göre cezalandıracağım, diyor RAB. 2 Bütün çevresini yakıp yok edecek 2 Bir ateş tutuşturacağım kentin ormanında.› ››'),
(2002778,68,24,22,1,'RAB bana dedi ki, ‹‹Yahuda Kralının sarayına gidip şu haberi bildir:'),
(2002779,68,24,22,2,'‹RABbin sözünü dinleyin, ey Davutun tahtında oturan Yahuda Kralıyla görevlileri ve bu kapılardan giren halk!'),
(2002780,68,24,22,3,'RAB diyor ki: Adil ve doğru olanı yapın. Soyguna uğrayanı zorbanın elinden kurtarın. Yabancıya, öksüze, dula haksızlık etmeyin, şiddete başvurmayın. Burada suçsuz kanı dökmeyin.'),
(2002781,68,24,22,4,'Bu buyrukları özenle yerine getirirseniz, Davutun tahtında oturan krallar savaş arabalarıyla, atlarıyla bu sarayın kapılarından girecekler; görevlileriyle halkları da onları izleyecek.'),
(2002782,68,24,22,5,'Ancak bu buyruklara uymazsanız, diyor RAB, adım üzerine ant içerim ki, bu saray viraneye dönecek.› ››'),
(2002783,68,24,22,6,'Çünkü Yahuda Kralının sarayı için RAB diyor ki, ‹‹Sen benim için Gilat gibisin, 2 Lübnanın doruğu gibi. 2 Ama hiç kuşkun olmasın, seni çöle döndürecek, 2 Kimsenin yaşamadığı kentlere çevireceğim.'),
(2002784,68,24,22,7,'Eli silahlı yok ediciler görevlendireceğim sana karşı. 2 En iyi sedir ağaçlarını kesecek, 2 Ateşe atacaklar.'),
(2002785,68,24,22,8,'‹‹Bu kentten geçen birçok ulus birbirlerine, ‹RAB bu büyük kente neden bunu yaptı?› diye soracaklar.'),
(2002786,68,24,22,9,'‹‹Yanıt şöyle olacak: ‹Çünkü Tanrıları RABbin antlaşmasını bıraktılar, başka ilahlara tapıp kulluk ettiler.› ››'),
(2002787,68,24,22,10,'Ölen için ağlamayın, yasa bürünmeyin; 2 Ancak sürgüne giden için ağlayın acı acı. 2 Çünkü bir daha dönmeyecek, 2 Anayurdunu görmeyecek.'),
(2002788,68,24,22,11,'Babası Yoşiyanın yerine Yahuda Kralı olan ve buradan çıkıp giden Yoşiya oğlu Şallumfö için RAB diyor ki, ‹‹Bir daha dönmeyecek buraya.'),
(2002789,68,24,22,12,'Sürgüne gönderildiği yerde ölecek, bir daha bu ülkeyi görmeyecek.›› 30).'),
(2002790,68,24,22,13,'‹‹Sarayını haksızlıkla, 2 Yukarı odalarını adaletsizlikle yapan, 2 Komşusunu parasız çalıştıran, 2 Ücretini ödemeyen adamın vay başına!'),
(2002791,68,24,22,14,'‹Kendim için yukarı odaları havadar, 2 Geniş bir saray yapacağım› diyenin vay başına! 2 Sarayına büyük pencereler açar, 2 Sedir ağacıyla kaplar, 2 Kırmızıya boyar.'),
(2002792,68,24,22,15,'‹‹Bol bol sedir ağacı kullandın diye 2 Kral mı oldun sanırsın? 2 Baban doyasıya yiyip içti, 2 Ama iyi ve doğru olanı yaptı; 2 Onun için de işleri iyi gitti.'),
(2002793,68,24,22,16,'Ezilenin, yoksulun davasını savundu, 2 Onun için de işleri iyi gitti. 2 Beni tanımak bu değil midir?›› diyor RAB.'),
(2002794,68,24,22,17,'‹‹Seninse gözlerin de yüreğin de yalnız kazanca, 2 Suçsuz kanı dökmeye, 2 Baskı, zorbalık yapmaya yönelik.››'),
(2002795,68,24,22,18,'Bu yüzden RAB Yahuda Kralı Yoşiya oğlu Yehoyakim için diyor ki, ‹‹Onun için kimse, ‹Ah kardeşim! 2 Vah kızkardeşim!› diye dövünmeyecek. 2 Onun için kimse, ‹Ah efendim! 2 Vah onun görkemi!› diye dövünmeyecek.'),
(2002796,68,24,22,19,'Sürüklenip Yeruşalim kapılarından dışarı atılacak, 2 Eşek gömülür gibi gömülecek o.››'),
(2002797,68,24,22,20,'‹‹Lübnana git, feryat et, 2 Sesin Başandan duyulsun, 2 Haykır Avarimden, 2 Çünkü bütün oynaşların ezildi.'),
(2002798,68,24,22,21,'Kendini güvenlikte sandığında seni uyardım. 2 Ama, ‹Dinlemem› dedin. 2 Gençliğinden bu yana böyleydi tutumun, 2 Sözümü hiç dinlemedin.'),
(2002799,68,24,22,22,'Rüzgar bütün çobanlarını alıp götürecek, 2 Oynaşların sürgüne gidecek. 2 İşte o zaman yaptığın kötülükler yüzünden 2 Utanacak, aşağılanacaksın.'),
(2002800,68,24,22,23,'Ey sen, Lübnanda yaşayan, 2 Yuvasını sedir ağacından kuran adam! 2 Sana doğuran kadın gibi acılar, sancılar geldiğinde, 2 Nasıl da inleyeceksin!›› sanılıyor. Masoretik metin ‹‹Acınacaksın››.'),
(2002801,68,24,22,24,'‹‹Varlığım hakkı için derim ki›› diyor RAB, ‹‹Ey Yahuda Kralı Yehoyakim oğlu Yehoyakin, sağ elimdeki mühür yüzüğü olsan bile, çıkarıp atardım seni.'),
(2002802,68,24,22,25,'Seni can düşmanlarının, korktuğun kişilerin, Babil Kralı Nebukadnessarla Kildanilerin eline teslim edeceğim.'),
(2002803,68,24,22,26,'Seni de seni doğuran anneni de doğmadığınız bir ülkeye atacağım; orada öleceksiniz.'),
(2002804,68,24,22,27,'Dönmeye can attığınız ülkeye bir daha dönemeyeceksiniz.››'),
(2002805,68,24,22,28,'Bu mu Yehoyakin? Bu hor görülmüş kırık çömlek, 2 Kimsenin istemediği kap? 2 Neden kendisi de çocukları da 2 Bilmedikleri bir ülkeye atıldılar?'),
(2002806,68,24,22,29,'Ülke, ey ülke, 2 RABbin sözünü dinle, ey ülke!'),
(2002807,68,24,22,30,'RAB diyor ki, 2 ‹‹Bu adamı çocuksuz, 2 Ömrünce başarısız biri olarak yazın. 2 Çünkü soyundan gelen hiç kimse başarılı olmayacak, 2 Soyundan gelen hiç kimse 2 Davut''un tahtında oturamayacak, 2 Yahuda''da bir daha krallık etmeyecek.››'),
(2002808,68,24,23,1,'‹‹Otlağımın koyunlarını yok edip dağıtan çobanların vay başına!›› diyor RAB.'),
(2002809,68,24,23,2,'Halkımı güden çobanlar için İsrailin Tanrısı RAB şöyle diyor: ‹‹Sürümü dağıtıp sürdünüz, onlarla ilgilenmediniz. Şimdi ben sizinle ilgileneceğim, yaptığınız kötülük yüzünden sizi cezalandıracağım.›› RAB böyle diyor.'),
(2002810,68,24,23,3,'‹‹Sürmüş olduğum bütün ülkelerden sürümün sağ kalanlarını toplayıp otlaklarına geri getireceğim; orada verimli olup çoğalacaklar.'),
(2002811,68,24,23,4,'Onları güdecek çobanlar koyacağım başlarına. Bundan böyle korkmayacak, yılgınlığa düşmeyecekler. Bir tanesi bile eksilmeyecek›› diyor RAB.'),
(2002812,68,24,23,5,'‹‹İşte Davut için doğru bir dal 2 Çıkaracağım günler geliyor›› diyor RAB. 2 ‹‹Bu kral bilgece egemenlik sürecek, 2 Ülkede adil ve doğru olanı yapacak.'),
(2002813,68,24,23,6,'Onun döneminde Yahuda kurtulacak, 2 İsrail güvenlik içinde yaşayacak. 2 O, ‹Yahve sidkenufş› adıyla anılacak.'),
(2002814,68,24,23,7,'‹‹Artık insanların, ‹İsrail halkını Mısırdan çıkaran RABbin varlığı hakkı için› demeyecekleri günler geliyor›› diyor RAB.'),
(2002815,68,24,23,8,'‹‹Bunun yerine, ‹İsrail soyunu kuzey ülkesinden ve sürdüğü bütün öbür ülkelerden geri getiren RABbin varlığı hakkı için› diyecekler. Böylece kendi topraklarında yaşayacaklar.››'),
(2002816,68,24,23,9,'Peygamberlere gelince, 2 Yüreğim paramparça, 2 Bütün kemiklerim titriyor. 2 RABbin yüzünden, 2 Onun kutsal sözleri yüzünden 2 Sarhoş gibi, 2 Şaraba yenik düşen bir adam gibiyim.'),
(2002817,68,24,23,10,'Çünkü ülke zina edenlerle dolu, 2 Lanet yüzünden yas tutuyor. 2 Otlaklar kurumuş. 2 İzledikleri yol kötü, 2 Güçlerini haksızca kullanıyorlar.'),
(2002818,68,24,23,11,'‹‹Peygamber de kâhin de tanrısız; 2 Tapınağımda bile kötülüklerini gördüm›› diyor RAB.'),
(2002819,68,24,23,12,'‹‹Bu yüzden izledikleri yol 2 Onlar için kaygan olacak; 2 Karanlığa sürülecek, 2 Orada tökezleyip düşecekler. 2 Çünkü cezalandırılacakları yıl 2 Başlarına felaket getireceğim›› diyor RAB.'),
(2002820,68,24,23,13,'‹‹Samiriye peygamberleri arasında 2 Şu iğrençliği gördüm: 2 Baal adına peygamberlik ederek 2 Halkım İsraili baştan çıkarıyorlar.'),
(2002821,68,24,23,14,'Yeruşalim peygamberleri arasında 2 Şu korkunç şeyi gördüm: 2 Zina ediyorlar, yalan peşindeler. 2 Kötülük edenleri güçlendirdiklerinden, 2 Kimse kötülüğünden dönmüyor. 2 Benim için hepsi Sodom gibi, 2 Yeruşalim halkı Gomora gibi oldu.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002822,68,24,23,15,'Bu nedenle Her Şeye Egemen RAB peygamberler için şöyle diyor: ‹‹Onlara pelinotu yedirecek, 2 Zehirli su içireceğim. 2 Çünkü Yeruşalim peygamberleri 2 Tanrısızlığın bütün ülkeye yayılmasına neden oldular.››'),
(2002823,68,24,23,16,'Her Şeye Egemen RAB diyor ki, 2 ‹‹Size peygamberlik eden peygamberlerin 2 Dediklerine kulak asmayın, 2 Onlar sizi aldatıyor. 2 RABbin ağzından çıkanları değil, 2 Kendi hayal ettikleri görümleri anlatıyorlar.'),
(2002824,68,24,23,17,'Beni küçümseyenlere sürekli, 2 ‹RAB diyor ki: Size esenlik olacak!› diyorlar. 2 Yüreklerinin inatçılığı doğrultusunda davrananlara, 2 ‹Başınıza felaket gelmeyecek› diyorlar.'),
(2002825,68,24,23,18,'RABbin sözünü duyup anlamak için 2 RABbin meclisinde kim bulundu ki? 2 Onun sözüne kulak verip duyan kim?'),
(2002826,68,24,23,19,'İşte, RABbin fırtınası öfkeyle kopacak, 2 Kasırgası döne döne kötülerin başına patlayacak.'),
(2002827,68,24,23,20,'Aklının tasarladığını tümüyle yapana dek 2 RABbin öfkesi dinmeyecek. 2 Son günlerde açıkça anlayacaksınız bunu.'),
(2002828,68,24,23,21,'Bu peygamberleri ben göndermedim, 2 Ama çabucak ortaya çıktılar. 2 Onlara hiç seslenmedim, 2 Yine de peygamberlik ettiler.'),
(2002829,68,24,23,22,'Ama meclisimde dursalardı, 2 Sözlerimi halkıma bildirir, 2 Onları kötü yollarından ve davranışlarından 2 Döndürürlerdi.'),
(2002830,68,24,23,23,'Ben yalnızca yakındaki Tanrı mıyım? 2 Uzaktaki Tanrı da değil miyim?›› diyor RAB,'),
(2002831,68,24,23,24,'‹‹Kim gizli yere saklanır da 2 Onu görmem?›› diyor RAB, 2 ‹‹Yeri göğü doldurmuyor muyum?›› diyor RAB.'),
(2002832,68,24,23,25,'‹‹Adımla yalancı peygamberlik edenlerin ne dediklerini duydum. ‹Bir düş gördüm! Bir düş!› diyorlar.'),
(2002833,68,24,23,26,'Kafalarından uydurdukları hileleri aktaran bu yalancı peygamberler ne zamana dek sürdürecekler bunu?'),
(2002834,68,24,23,27,'Ataları nasıl Baal yüzünden adımı unuttuysa, onlar da birbirlerine düşlerini anlatarak halkıma adımı unutturmayı tasarlıyorlar.'),
(2002835,68,24,23,28,'Düşü olan peygamber düşünü anlatsın; ama sözümü alan onu sadakatle bildirsin. Buğdayın yanında saman nedir ki?›› diyor RAB.'),
(2002836,68,24,23,29,'‹‹Benim sözüm ateş gibi değil mi? Kayaları paramparça eden balyoz gibi değil mi?›› RAB böyle diyor.'),
(2002837,68,24,23,30,'‹‹İşte bunun için sözlerimi birbirlerinden çalan peygamberlere karşıyım›› diyor RAB.'),
(2002838,68,24,23,31,'‹‹Evet, kendi sözlerini söyleyip, ‹RAB böyle diyor› diyen peygamberlere karşıyım›› diyor RAB.'),
(2002839,68,24,23,32,'‹‹Uydurma düşler gören peygamberlere karşıyım›› diyor RAB. ‹‹Bu düşleri anlatıyor, yalanlarla, boş övünmelerle halkımı baştan çıkarıyorlar. Ben onları ne gönderdim, ne de atadım. Bu halka hiç mi hiç yararları yok›› diyor RAB.'),
(2002840,68,24,23,33,'‹‹Halktan biri, bir peygamber ya da kâhin, ‹RABbin bildirisi nedir?› diye sorarsa, ‹Ne bildirisi?› diye karşılık vereceksin. Sizi başımdan atacağım›› diyor RAB.'),
(2002841,68,24,23,34,'‹‹Eğer bir peygamber, kâhin ya da başka biri, ‹Bu RABbin bildirisidir› derse, onu da ailesini de cezalandıracağım.'),
(2002842,68,24,23,35,'Her biriniz komşunuza ve kardeşinize, ‹RAB ne yanıt verdi?› ya da, ‹RAB ne söyledi?› demelisiniz.'),
(2002843,68,24,23,36,'Bundan böyle, ‹RABbin bildirisi› lafını ağzınıza almayacaksınız. Herkesin sözü kendi bildirisi olacak. Yaşayan Tanrının, Her Şeye Egemen RABbin, Tanrımızın sözlerini çarpıtıyorsunuz siz.'),
(2002844,68,24,23,37,'Bir peygambere, ‹RAB sana ne yanıt verdi?› ya da, ‹RAB ne söyledi?› demelisiniz.'),
(2002845,68,24,23,38,'Ama, ‹RABbin bildirisidir› derseniz, RAB diyor ki, ‹RABbin bildirisidir› diyorsunuz. Oysa, ‹RABbin bildirisidir› demeyeceksiniz diye sizi uyarmıştım.'),
(2002846,68,24,23,39,'Bu yüzden sizi büsbütün unutacağım, sizi de size ve atalarınıza verdiğim kenti de önümden söküp atacağım.'),
(2002847,68,24,23,40,'Sizi hiç unutulmayacak bir utanca düşürecek, sürekli alay konusu edeceğim.››'),
(2002848,68,24,24,1,'Babil Kralı Nebukadnessar Yahuda Kralı Yehoyakim oğlu Yehoyakinle Yahuda önderlerini, zanaatçıları, demircileri Yeruşalimden Babile sürdükten sonra, RAB bana tapınağının önüne konmuş iki sepet incir gösterdi.'),
(2002849,68,24,24,2,'Sepetlerin birinde ilk ürüne benzer çok iyi incirler vardı; ötekindeyse çok kötü, yenmeyecek kadar çürük incirler vardı.'),
(2002850,68,24,24,3,'RAB, ‹‹Yeremya, ne görüyorsun?›› diye sordu. ‹‹İncir›› diye yanıtladım, ‹‹İyi incirler çok iyi, öbürleriyse çok kötü, yenmeyecek kadar çürük.››'),
(2002851,68,24,24,4,'Bunun üzerine RAB bana şöyle seslendi:'),
(2002852,68,24,24,5,'‹‹İsrailin Tanrısı RAB diyor ki, ‹Buradan Kildan ülkesine sürgüne gönderdiğim Yahuda sürgünlerini bu iyi incirler gibi iyi sayacağım.'),
(2002853,68,24,24,6,'İyilik bulmaları için onları gözetecek, bu ülkeye geri getireceğim. Onları bina edeceğim, yıkmayacağım; onları dikeceğim, kökünden sökmeyeceğim.'),
(2002854,68,24,24,7,'Benim RAB olduğumu anlayacak bir yürek vereceğim onlara. Onlar benim halkım olacaklar, ben de onların Tanrısı olacağım. Çünkü bütün yürekleriyle bana dönecekler.'),
(2002855,68,24,24,8,'‹‹ ‹Ama Yahuda Kralı Sidkiyayla önderlerini, Yeruşalimden sağ çıkıp da bu ülkede ya da Mısırda yaşayanları yenmeyecek kadar çürük incir gibi yapacağım› diyor RAB,'),
(2002856,68,24,24,9,'‹Onları bütün ülkelerin gözünde iğrenç, korkunç bir duruma düşüreceğim. Onları sürdüğüm her yerde ayıplanacak, ibret olacak, alaya alınacak, lanetlenecekler.'),
(2002857,68,24,24,10,'Kendilerine ve atalarına verdiğim topraktan yok olana dek üzerlerine kılıç, kıtlık, salgın hastalık salacağım.› ››'),
(2002858,68,24,25,1,'Yahuda Kralı Yoşiya oğlu Yehoyakimin döneminin dördüncü yılında, RAB Yahuda halkıyla ilgili olarak Yeremyaya seslendi. Nebukadnessarın Babil Kralı oluşunun birinci yılıydı bu.'),
(2002859,68,24,25,2,'Peygamber Yeremya Yahuda halkına ve Yeruşalimde yaşayanlara RABbin sözünü aktararak şöyle dedi:'),
(2002860,68,24,25,3,'Yirmi üç yıldır, Yahuda Kralı Amon oğlu Yoşiyanın döneminin on üçüncü yılından bugüne dek, RAB bana sesleniyor. Ben de RABbin sözünü defalarca size aktardım, ama dinlemediniz.'),
(2002861,68,24,25,4,'RAB peygamber kullarını defalarca size gönderdi, ama dinlemediniz, kulak asmadınız.'),
(2002862,68,24,25,5,'Sizi uyardılar, ‹‹Şimdi herkes kötü yolundan, kötü işlerinden dönsün ki, RABbin sonsuza dek size ve atalarınıza verdiği toprakta yaşayasınız›› dediler,'),
(2002863,68,24,25,6,'‹‹Kulluk etmek, tapınmak için başka ilahların ardınca gitmeyin; elinizle yaptığınız putlarla beni öfkelendirmeyin ki, ben de size zarar vermeyeyim.››'),
(2002864,68,24,25,7,'‹‹Ama beni dinlemediniz›› diyor RAB, ‹‹Sonuç olarak elinizle yaptığınız putlarla beni öfkelendirip kendinizi zarara soktunuz.››'),
(2002865,68,24,25,8,'Bunun için Her Şeye Egemen RAB diyor ki, ‹‹Madem sözlerimi dinlemediniz,'),
(2002866,68,24,25,9,'ben de bütün kuzeydeki halkları ve kulum Babil Kralı Nebukadnessarı çağırtacağım›› diyor RAB, ‹‹Onları bu ülkeye de burada yaşayanlarla çevresindeki bütün uluslara da karşı getireceğim. Bu halkı tamamen yok edeceğim, ülkelerini dehşet ve alay konusu edip sonsuz bir viraneye çevireceğim.'),
(2002867,68,24,25,10,'Sevinç ve neşe sesini, gelin güvey sesini, değirmen taşlarının sesini, kandil ışığını onlardan uzaklaştıracağım.'),
(2002868,68,24,25,11,'Bütün ülke bir virane, dehşet verici bir yer olacak. Bu uluslar Babil Kralına yetmiş yıl kulluk edecekler.'),
(2002869,68,24,25,12,'‹‹Ama yetmiş yıl dolunca›› diyor RAB, ‹‹Suçları yüzünden Babil Kralıyla ulusunu, Kildan ülkesini cezalandıracak, sonsuz bir viranelik haline getireceğim.'),
(2002870,68,24,25,13,'O ülke için söylediklerimin hepsini, Yeremyanın uluslara ettiği bu kitapta yazılı bütün peygamberlik sözlerini ülkenin başına getireceğim.'),
(2002871,68,24,25,14,'Pek çok ulus, büyük krallar onları köle edinecek. Yaptıklarına ve ellerinden çıkan işe göre karşılık vereceğim onlara.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002872,68,24,25,15,'İsrailin Tanrısı RAB bana şöyle dedi: ‹‹Elimdeki öfke şarabıyla dolu kâseyi al, seni göndereceğim bütün uluslara içir.'),
(2002873,68,24,25,16,'Şarabı içince sendeleyecek, üzerlerine göndereceğim kılıç yüzünden çıldıracaklar.››'),
(2002874,68,24,25,17,'Böylece kâseyi RABbin elinden alıp beni gönderdiği bütün uluslara içirdim:'),
(2002875,68,24,25,18,'Bugün olduğu gibi viranelik, dehşet ve alay konusu, lanetlik olsunlar diye Yeruşalime, Yahuda kentlerine, krallarıyla önderlerine;'),
(2002876,68,24,25,19,'Firavunla görevlilerine, önderlerine ve halkına,'),
(2002877,68,24,25,20,'Mısırda yaşayan bütün yabancılara; Ûs krallarına, Filist krallarına -Aşkelona, Gazzeye, Ekrona, Aşdottan sağ kalanlara-'),
(2002878,68,24,25,21,'Edoma, Moava, Ammona;'),
(2002879,68,24,25,22,'bütün Sur ve Sayda krallarına, deniz aşırı ülkelerin krallarına;'),
(2002880,68,24,25,23,'Dedana, Temaya, Bûza, zülüflerini kesen bütün halklara;'),
(2002881,68,24,25,24,'Arabistan krallarına, çölde yaşayan yabancı halkın krallarına;'),
(2002882,68,24,25,25,'Zimri, Elam, Med krallarına;'),
(2002883,68,24,25,26,'sırasıyla uzak yakın bütün kuzey krallarına, yeryüzündeki bütün ulusların krallarına içirdim. Hepsinden sonra Şeşak Kralı da içecektir.'),
(2002884,68,24,25,27,'‹‹Sonra onlara de ki, ‹İsrailin Tanrısı, Her Şeye Egemen RAB şöyle diyor: Üzerinize salacağım kılıç yüzünden sarhoş olana dek için, kusun, düşüp kalkmayın.›'),
(2002885,68,24,25,28,'Eğer kâseyi elinden alır, içmek istemezlerse, de ki, ‹Her Şeye Egemen RAB şöyle diyor: Kesinlikle içeceksiniz!'),
(2002886,68,24,25,29,'Bana ait olan kentin üzerine felaket getirmeye başlıyorum. Cezasız kalacağınızı mı sanıyorsunuz? Sizi cezasız bırakmayacağım. İşte dünyada yaşayan herkesin üzerine kılıcı çağırıyorum. Her Şeye Egemen RAB böyle diyor.›'),
(2002887,68,24,25,30,'‹‹Bütün bu peygamberlik sözlerini onlara ilet: ‹‹ ‹Yükseklerden kükreyecek RAB, 2 Kutsal konutundan gürleyecek, 2 Ağılına şiddetle kükreyecek. 2 Dünyada yaşayanların tümüne 2 Üzüm ezenler gibi bağıracak.'),
(2002888,68,24,25,31,'Gürültü yeryüzünün dört yanında yankılanacak. 2 Çünkü RAB uluslara dava açacak; 2 Herkesi yargılayacak 2 Ve kötüleri kılıca teslim edecek› ›› diyor RAB.'),
(2002889,68,24,25,32,'Her Şeye Egemen RAB diyor ki, 2 ‹‹İşte felaket ulustan ulusa yayılıyor! 2 Dünyanın dört bucağından büyük kasırga kopuyor.››'),
(2002890,68,24,25,33,'O gün RAB dünyayı bir uçtan bir uca öldürülenlerle dolduracak. Onlar için yas tutulmayacak, toplanıp gömülmeyecekler. Toprağın üzerinde gübre gibi kalacaklar.'),
(2002891,68,24,25,34,'Haykırın, ey çobanlar, 2 Acı acı bağırın! 2 Toprakta yuvarlanın, ey sürü başları! 2 Çünkü boğazlanma zamanınız doldu, 2 Değerli bir kap gibi düşüp parçalanacaksınız.'),
(2002892,68,24,25,35,'Çobanlar kaçamayacak, 2 Sürü başları kurtulamayacak!'),
(2002893,68,24,25,36,'Duy çobanların haykırışını, 2 Sürü başlarının bağırışını! 2 RAB onların otlaklarını yok ediyor.'),
(2002894,68,24,25,37,'RABbin kızgın öfkesi yüzünden 2 Güvenlikte oldukları ağıllar yok oldu.'),
(2002895,68,24,25,38,'İnini terk eden genç aslan gibi, 2 RAB inini bıraktı. 2 Zorbanın kılıcı 2 Ve RAB''bin kızgın öfkesi yüzünden 2 Ülkeleri viraneye döndü.'),
(2002896,68,24,26,1,'Yahuda Kralı Yoşiya oğlu Yehoyakimin krallığının başlangıcında RAB şöyle seslendi:'),
(2002897,68,24,26,2,'‹‹RAB diyor ki, RABbin Tapınağının avlusunda dur, tapınmak için Yahuda kentlerinden oraya gelen herkese seslen. Sana buyurduğum her şeyi tek söz eksiltmeden onlara bildir.'),
(2002898,68,24,26,3,'Belki dinler de kötü yollarından dönerler. O zaman ben de yaptıkları kötülükler yüzünden başlarına getirmeyi tasarladığım felaketten vazgeçerim.'),
(2002899,68,24,26,4,'Onlara de ki, ‹RAB şöyle diyor: Size verdiğim yasa uyarınca yürümez, beni dinlemez,'),
(2002900,68,24,26,5,'size defalarca gönderdiğim kullarım peygamberlerin sözlerine kulak vermezseniz, ki kulak vermiyorsunuz,'),
(2002901,68,24,26,6,'bu tapınağa Şilodakine yaptığımın aynısını yapar, bu kenti bütün dünya ulusları arasında lanetlik ederim.› ››'),
(2002902,68,24,26,7,'Kâhinler, peygamberler ve bütün halk Yeremyanın RABbin Tapınağında söylediği bu sözleri duydular.'),
(2002903,68,24,26,8,'Yeremya Tanrının halka iletmesini buyurduğu sözleri bitirince, kâhinlerle peygamberler ve halk onu yakalayıp, ‹‹Ölmen gerek!›› dediler,'),
(2002904,68,24,26,9,'‹‹Neden bu tapınak Şilodaki gibi olacak, bu kent de içinde kimsenin yaşamayacağı bir viraneye dönecek diyerek RABbin adıyla peygamberlik ediyorsun?›› Bütün halk RABbin Tapınağında Yeremyanın çevresinde toplanmıştı.'),
(2002905,68,24,26,10,'Yahuda önderleri olup bitenleri duyunca, saraydan RABbin Tapınağına gidip tapınağın Yeni Kapı girişinde yerlerini aldılar.'),
(2002906,68,24,26,11,'Bunun üzerine kâhinlerle peygamberler, önderlere ve halka, ‹‹Bu adam ölüm cezasına çarptırılmalı›› dediler, ‹‹Çünkü bu kente karşı peygamberlik etti. Kendi kulaklarınızla işittiniz bunu.››'),
(2002907,68,24,26,12,'Bunun üzerine Yeremya önderlerle halka, ‹‹Bu tapınağa ve kente karşı işittiğiniz peygamberlik sözlerini iletmem için beni RAB gönderdi›› dedi,'),
(2002908,68,24,26,13,'‹‹Şimdi yollarınızı, davranışlarınızı düzeltin, Tanrınız RABbin sözüne kulak verin. O zaman RAB başınıza getireceğini söylediği felaketten vazgeçecek.'),
(2002909,68,24,26,14,'Bana gelince, işte elinizdeyim! Gözünüzde iyi ve doğru olan neyse, bana öyle yapın.'),
(2002910,68,24,26,15,'Ancak şunu kesinlikle bilin ki, eğer beni öldürürseniz, siz de bu kent ve içinde yaşayanlar da suçsuz birinin kanını dökmekten sorumlu tutulacaksınız. Çünkü bütün bu sözleri bildirmem için beni gerçekten RAB size gönderdi.››'),
(2002911,68,24,26,16,'Bunun üzerine önderlerle halk, kâhinlerle peygamberlere, ‹‹Bu adam ölüm cezasına çarptırılmamalı›› dediler, ‹‹Çünkü bizimle Tanrımız RABbin adına konuştu.››'),
(2002912,68,24,26,17,'Halkın ileri gelenlerinden birkaçı öne çıkıp orada toplanmış halka,'),
(2002913,68,24,26,18,'‹‹Moreşetli Mika Yahuda Kralı Hizkiya döneminde peygamberlik etti›› dediler, ‹‹Yahuda halkına dedi ki, Her Şeye Egemen RAB şöyle diyor, ‹‹ ‹Siyon tarla gibi sürülecek, 2 Taş yığınına dönecek Yeruşalim, 2 Tapınağın kurulduğu dağ 2 Çalılarla kaplanacak.›'),
(2002914,68,24,26,19,'‹‹Yahuda Kralı Hizkiya ya da Yahuda halkından biri onu öldürdü mü? Bunun yerine Hizkiya RABden korkarak Onun lütfunu diledi. RAB de onlara bildirdiği felaketten vazgeçti. Bizse, üzerimize büyük bir yıkım getirmek üzereyiz.››'),
(2002915,68,24,26,20,'Kiryat-Yearimli Şemaya oğlu Uriya adında peygamberlik eden bir adam daha vardı. Tıpkı Yeremya gibi o da RABbin adına bu kente ve ülkeye karşı peygamberlik etti.'),
(2002916,68,24,26,21,'Kral Yehoyakimle askerleri ve komutanları Uriyanın sözlerini duydular. Kral onu öldürmek istedi. Bunu duyan Uriya korkuya kapılarak kaçıp Mısıra gitti.'),
(2002917,68,24,26,22,'Bunun üzerine Kral Yehoyakim peşinden adamlarını -Akbor oğlu Elnatanla başkalarını- Mısıra gönderdi.'),
(2002918,68,24,26,23,'Uriyayı Mısırdan çıkarıp Kral Yehoyakime getirdiler. Kral onu kılıçla öldürtüp cesedini sıradan halk mezarlığına attırdı.'),
(2002919,68,24,26,24,'Ancak Şafan oğlu Ahikam Yeremya''yı korudu. Böylece Yeremya öldürülmek üzere halkın eline teslim edilmedi.'),
(2002920,68,24,27,1,'Yahuda Kralı Yoşiya oğlu Sidkiyanın krallığının başlangıcında RAB Yeremyaya seslendi:'),
(2002921,68,24,27,2,'RAB bana dedi ki, ‹‹Kendine sırımla bağlanmış tahta bir boyunduruk yap, boynuna geçir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002922,68,24,27,3,'Sonra Yeruşalime, Yahuda Kralı Sidkiyaya gelen ulaklar aracılığıyla Edom, Moav, Ammon, Sur ve Sayda krallarına haber gönder.'),
(2002923,68,24,27,4,'Efendilerine şunu bildirmelerini buyur: İsrailin Tanrısı Her Şeye Egemen RAB diyor ki, ‹Efendilerinize söyleyin:'),
(2002924,68,24,27,5,'Yeryüzünü de üstünde yaşayan insanlarla hayvanları da büyük gücümle, kudretli elimle ben yarattım. Onu uygun gördüğüm kişiye veririm.'),
(2002925,68,24,27,6,'Şimdi bütün bu ülkeleri Babil Kralı kulum Nebukadnessara vereceğim. Yabanıl hayvanları da kulluk etsinler diye ona vereceğim.'),
(2002926,68,24,27,7,'Ülkesi için saptanan zaman gelinceye dek bütün uluslar ona, oğluna, torununa kulluk edecek. Sonra birçok ulus, büyük krallar onu köle edecekler.'),
(2002927,68,24,27,8,'‹‹ ‹Hangi ulus ya da krallık Babil Kralı Nebukadnessara kulluk edip boyunduruğuna girmezse, o ulusu onun eline teslim edene dekfü kılıçla, kıtlıkla, salgın hastalıkla cezalandıracağım, diyor RAB.'),
(2002928,68,24,27,9,'Size gelince, peygamberlerinizi, falcılarınızı, düş görenlerinizi, medyumlarınızı, büyücülerinizi dinlemeyin! Onlar size, Babil Kralına kulluk etmeyeceksiniz diyorlar.'),
(2002929,68,24,27,10,'Size yalan peygamberlik ediyorlar. Bunun sonucu sizi ülkenizden uzaklaştırmak oluyor. Sizi süreceğim, yok olacaksınız.'),
(2002930,68,24,27,11,'Ama Babil Kralının boyunduruğuna girip ona kulluk eden ulusu kendi toprağında bırakacağım, diyor RAB. O ulus toprağını işleyecek, orada yaşayacak.› ›› Masoretik metin ‹‹Onun eliyle yok edilişi tamamlanana dek››.'),
(2002931,68,24,27,12,'Yahuda Kralı Sidkiyaya bütün bu sözleri ilettim. Dedim ki, ‹‹Boyunlarınızı Babil Kralının boyunduruğu altına koyun. Ona ve halkına kulluk edin ki sağ kalasınız.'),
(2002932,68,24,27,13,'RABbin Babil Kralına kulluk etmeyen her ulus için dediği gibi, niçin sen ve halkın kılıç, kıtlık, salgın hastalık yüzünden ölesiniz?'),
(2002933,68,24,27,14,'Size, ‹Babil Kralına kulluk etmeyeceksiniz› diyen peygamberlerin sözlerine kulak asmayın. Onlar size yalan peygamberlik ediyorlar.'),
(2002934,68,24,27,15,'‹Onları ben göndermedim› diyor RAB, ‹Adımla yalan peygamberlik ediyorlar. Bu yüzden sizi de size peygamberlik eden peygamberleri de süreceğim, hepiniz yok olacaksınız.› ››'),
(2002935,68,24,27,16,'Sonra kâhinlerle halka şöyle dedim: ‹‹RAB diyor ki, ‹İşte RABbin Tapınağının eşyaları yakında Babilden geri getirilecek› diyen peygamberlerinize kulak asmayın. Onlar size yalan peygamberlik ediyorlar.'),
(2002936,68,24,27,17,'Onları dinlemeyin. Sağ kalmak için Babil Kralına kulluk edin. Bu kent neden viraneye çevrilsin?'),
(2002937,68,24,27,18,'Eğer bunlar peygamberse ve RABbin sözü onlardaysa, RABbin Tapınağında, Yahuda Kralının sarayında ve Yeruşalimde kalan eşyalar Babile götürülmesin diye Her Şeye Egemen RABbe yalvarsınlar.'),
(2002938,68,24,27,19,'‹‹Çünkü Babil Kralı Nebukadnessar Yahuda Kralı Yehoyakim oğlu Yehoyakini Yahuda ve Yeruşalim soylularıyla birlikte Yeruşalimden Babile sürdüğünde alıp götürmediği sütunlar, havuz, ayaklıklar ve kentte kalan öbür eşyalar için Her Şeye Egemen RAB şöyle diyor.'),
(2002939,68,24,27,21,'Evet, RABbin Tapınağında, Yahuda Kralının sarayında ve Yeruşalimde kalan eşyalar için İsrailin Tanrısı, Her Şeye Egemen RAB şöyle diyor:'),
(2002940,68,24,27,22,'‹Bunlar Babil''e taşınacak, aldıracağım güne dek de orada kalacaklar› diyor RAB, ‹O zaman onları alacak, yeniden buraya yerleştireceğim.› ››'),
(2002941,68,24,28,1,'Aynı yıl Yahuda Kralı Sidkiyanın krallığının başlangıcında, dördüncü yılının beşinci ayında Givonlu Azzur oğlu Peygamber Hananya RABbin Tapınağında kâhinlerle bütün halkın önünde bana şöyle dedi:'),
(2002942,68,24,28,2,'‹‹İsrailin Tanrısı, Her Şeye Egemen RAB diyor ki, ‹Babil Kralının boyunduruğunu kıracağım.'),
(2002943,68,24,28,3,'Babil Kralı Nebukadnessarın buradan alıp Babile götürdüğü RABbin Tapınağına ait bütün eşyaları iki yıl içinde buraya geri getireceğim.'),
(2002944,68,24,28,4,'Yahuda Kralı Yehoyakim oğlu Yehoyakinle Babile sürgüne giden bütün Yahudalıları buraya geri getireceğim› diyor RAB, ‹Çünkü Babil Kralının boyunduruğunu kıracağım.› ››'),
(2002945,68,24,28,5,'Bunun üzerine Peygamber Yeremya, kâhinlerin ve RABbin Tapınağındaki halkın önünde Peygamber Hananyayı yanıtladı.'),
(2002946,68,24,28,6,'Yeremya şöyle dedi: ‹‹Amin! RAB aynısını yapsın! RAB, tapınağına ait eşyalarla bütün sürgünleri Babilden buraya geri getirerek ettiğin peygamberlik sözlerini gerçekleştirsin!'),
(2002947,68,24,28,7,'Yalnız şimdi sana ve halka söyleyeceğim şu sözü dinle:'),
(2002948,68,24,28,8,'Çok önce, benden de senden de önce yaşamış peygamberler birçok ülke ve büyük krallığın başına savaş, felaket, salgın hastalık gelecek diye peygamberlik ettiler.'),
(2002949,68,24,28,9,'Ancak esenlik olacağını söyleyen peygamberin sözü yerine gelirse, onun gerçekten RABbin gönderdiği peygamber olduğu anlaşılır.››'),
(2002950,68,24,28,10,'Bunun üzerine Peygamber Hananya, Peygamber Yeremyanın boynundan boyunduruğu çıkarıp kırdı.'),
(2002951,68,24,28,11,'Sonra halkın önünde şöyle dedi: ‹‹RAB diyor ki, ‹Babil Kralı Nebukadnessarın bütün ulusların boynuna taktığı boyunduruğu iki yıl içinde işte böyle kıracağım.› ›› Böylece Peygamber Yeremya yoluna gitti.'),
(2002952,68,24,28,12,'Peygamber Hananya Peygamber Yeremyanın boynundaki boyunduruğu kırdıktan sonra RAB Yeremyaya şöyle seslendi:'),
(2002953,68,24,28,13,'‹‹Git, Hananyaya de ki, ‹RAB şöyle diyor: Sen tahtadan yapılmış boyunduruğu kırdın, ama yerine demir boyunduruk yapacaksın!'),
(2002954,68,24,28,14,'Çünkü İsrailin Tanrısı, Her Şeye Egemen RAB diyor ki, Babil Kralı Nebukadnessara kulluk etmeleri için bütün bu ulusların boynuna demir boyunduruk geçirdim, ona kulluk edecekler. Yabanıl hayvanları da onun denetimine vereceğim.› ››'),
(2002955,68,24,28,15,'Peygamber Yeremya Peygamber Hananyaya, ‹‹Dinle, ey Hananya!›› dedi, ‹‹Seni RAB göndermedi. Ama sen bu ulusu yalana inandırdın.'),
(2002956,68,24,28,16,'Bu nedenle RAB diyor ki, ‹Seni yeryüzünden silip atacağım. Bu yıl öleceksin. Çünkü halkı RABbe karşı kışkırttın.› ››'),
(2002957,68,24,28,17,'Peygamber Hananya o yılın yedinci ayında öldü.'),
(2002958,68,24,29,1,'Peygamber Yeremyanın sürgünde sağ kalan halkın ileri gelenlerine, kâhinlerle peygamberlere ve Nebukadnessarın Yeruşalimden Babile sürdüğü bütün halka Yeruşalimden gönderdiği mektubun metni aşağıda yazılıdır.'),
(2002959,68,24,29,2,'Bu mektup Kral Yehoyakinin, ana kraliçenin, saray görevlilerinin, Yahuda ve Yeruşalim önderlerinin, zanaatçılarla demircilerin Yeruşalimden sürgüne gitmelerinden sonra,'),
(2002960,68,24,29,3,'Yahuda Kralı Sidkiyanın Babil Kralı Nebukadnessara gönderdiği Şafan oğlu Elasa ve Hilkiya oğlu Gemarya eliyle gönderildi:'),
(2002961,68,24,29,4,'İsrailin Tanrısı, Her Şeye Egemen RAB Yeruşalimden Babile sürdüğü herkese şöyle diyor:'),
(2002962,68,24,29,5,'‹‹Evler yapıp içinde oturun, bahçe dikip ürününü yiyin.'),
(2002963,68,24,29,6,'Evlenin, oğullarınız, kızlarınız olsun; oğullarınızı, kızlarınızı evlendirin. Onların da oğulları, kızları olsun. Orada çoğalın, azalmayın.'),
(2002964,68,24,29,7,'Sizi sürmüş olduğum kentin esenliği için uğraşın. O kent için RABbe dua edin. Çünkü esenliğiniz onunkine bağlıdır.››'),
(2002965,68,24,29,8,'Evet, İsrailin Tanrısı, Her Şeye Egemen RAB diyor ki, ‹‹Aranızdaki peygamberlerle falcılara aldanmayın. Düş görmeye özendirdiğiniz kişilere kulak asmayın.'),
(2002966,68,24,29,9,'Çünkü onlar adımı kullanarak size yalan peygamberlik ediyorlar. Onları ben göndermedim.›› RAB böyle diyor.'),
(2002967,68,24,29,10,'RAB diyor ki, ‹‹Babilde yetmiş yılınız dolunca sizinle ilgilenecek, buraya sizi geri getirmek için verdiğim iyi sözü tutacağım.'),
(2002968,68,24,29,11,'Çünkü sizin için düşündüğüm tasarıları biliyorum›› diyor RAB. ‹‹Kötü tasarılar değil, size umutlu bir gelecek sağlayan esenlik tasarıları bunlar.'),
(2002969,68,24,29,12,'O zaman beni çağıracak, gelip bana yakaracaksınız. Ben de sizi işiteceğim.'),
(2002970,68,24,29,13,'Beni arayacaksınız, bütün yüreğinizle arayınca beni bulacaksınız.'),
(2002971,68,24,29,14,'Kendimi size buldurtacağım›› diyor RAB. ‹‹Sizi eski gönencinize kavuşturacağım. Sizi sürdüğüm bütün yerlerden ve uluslardan toplayacağım›› diyor RAB. ‹‹Ve sizi sürgün ettiğim yerden geri getireceğim.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2002972,68,24,29,15,'Madem, ‹‹RAB bizim için Babilde peygamberler çıkardı›› diyorsunuz,'),
(2002973,68,24,29,16,'Davutun tahtında oturan kral, bu kentte kalan halk ve sizinle sürgüne gitmeyen yurttaşlarınız için RAB şöyle diyor.'),
(2002974,68,24,29,17,'Evet, Her Şeye Egemen RAB diyor ki, ‹‹Üzerlerine kılıç, kıtlık, salgın hastalık göndereceğim. Onları yenilmeyecek kadar çürük, bozuk incir gibi edeceğim.'),
(2002975,68,24,29,18,'Kılıçla, kıtlıkla, salgın hastalıkla peşlerine düşeceğim. Yeryüzündeki bütün krallıklara dehşet saçacak, kendilerini sürdüğüm bütün ülkeler arasında lanetlenecek, dehşet ve alay konusu olacak, aşağılanacaklar.'),
(2002976,68,24,29,19,'Çünkü sözlerime kulak asmadılar›› diyor RAB. ‹‹Kullarım peygamberler aracılığıyla sözlerimi defalarca gönderdim, ama dinlemediniz.›› RAB böyle diyor.'),
(2002977,68,24,29,20,'Bunun için, ey sizler, Yeruşalimden Babile gönderdiğim sürgünler, RABbin sözüne kulak verin!'),
(2002978,68,24,29,21,'Adımı kullanarak size yalan peygamberlik eden Kolaya oğlu Ahavla Maaseya oğlu Sidkiya için İsrailin Tanrısı, Her Şeye Egemen RAB diyor ki, ‹‹Onları Babil Kralı Nebukadnessarın eline teslim edeceğim, gözünüzün önünde ikisini de öldürecek.'),
(2002979,68,24,29,22,'Onlardan ötürü Babildeki bütün Yahuda sürgünleri, ‹RAB seni Babil Kralının diri diri yaktırdığı Sidkiya ve Ahavla aynı duruma düşürsün› diye lanet edecek.'),
(2002980,68,24,29,23,'Çünkü İsrailde çirkin şeyler yaptılar; komşularının karılarıyla zina ettiler, onlara buyurmadığım halde adımla yalan sözler söylediler. Bunu biliyorum ve buna tanığım›› diyor RAB.'),
(2002981,68,24,29,24,'Nehelamlı Şemayaya diyeceksin ki,'),
(2002982,68,24,29,25,'‹‹İsrailin Tanrısı, Her Şeye Egemen RAB şöyle diyor: Sen Yeruşalim halkına, Maaseya oğlu Kâhin Sefanyayla bütün öbür kâhinlere kendi adına mektuplar göndererek şöyle yazmıştın:'),
(2002983,68,24,29,26,'‹‹ ‹RAB tapınağın sorumlusu olarak Yehoyada yerine seni kâhin atadı. Peygamber gibi davranan her deliyi tomruğa, demir boyunduruğa vurmak görevindir.'),
(2002984,68,24,29,27,'Öyleyse aranızda kendini peygamber ilan eden Anatotlu Yeremyayı neden azarlamadın?'),
(2002985,68,24,29,28,'Çünkü Yeremya biz Babildekilere şu haberi gönderdi: Sürgün uzun olacak. Onun için evler yapıp içinde oturun; bahçe dikip ürününü yiyin.› ››'),
(2002986,68,24,29,29,'Kâhin Sefanya mektubu Peygamber Yeremyaya okuyunca,'),
(2002987,68,24,29,30,'RAB Yeremyaya şöyle seslendi:'),
(2002988,68,24,29,31,'‹‹Bütün sürgünlere şu haberi gönder: ‹Nehelamlı Şemaya için RAB diyor ki: Madem ben göndermediğim halde Şemaya peygamberlik edip sizleri yalana inandırdı,'),
(2002989,68,24,29,32,'ben de Nehelamlı Şemaya''yı ve bütün soyunu cezalandıracağım: Bu halkın arasında soyundan kimse sağ kalmayacak, halkıma yapacağım iyiliği görmeyecek, diyor RAB. Çünkü o halkı bana karşı kışkırttı.› ››'),
(2002990,68,24,30,1,'RAB Yeremyaya şöyle seslendi:'),
(2002991,68,24,30,2,'‹‹İsrailin Tanrısı RAB diyor ki, ‹Sana bildirdiğim bütün sözleri bir kitaba yaz.'),
(2002992,68,24,30,3,'İşte halkım İsraili ve Yahudayı eski gönençlerine kavuşturacağım günler yaklaşıyor› diyor RAB, ‹Onları atalarına verdiğim topraklara geri getireceğim, orayı yurt edinecekler› diyor RAB.››'),
(2002993,68,24,30,4,'İsrail ve Yahuda için RABbin bildirdiği sözler şunlardır:'),
(2002994,68,24,30,5,'‹‹RAB diyor ki, 2 ‹Korku sesi duyduk, 2 Esenlik değil, dehşet sesi.'),
(2002995,68,24,30,6,'Sorun da görün: 2 Erkek, çocuk doğurur mu? 2 Öyleyse neden doğuran kadın gibi 2 Her erkeğin ellerini belinde görüyorum? 2 Neden her yüz solmuş?'),
(2002996,68,24,30,7,'Ah, ne korkunç gün! 2 Onun gibisi olmayacak. 2 Yakup soyu için sıkıntı dönemi olacak, 2 Yine de sıkıntıdan kurtulacak.'),
(2002997,68,24,30,8,'‹‹ ‹O gün› diyor Her Şeye Egemen RAB, 2 ‹Boyunlarındaki boyunduruğu kıracak, 2 Bağlarını koparacağım. 2 Bundan böyle yabancılar onları 2 Kendilerine köle etmeyecekler.'),
(2002998,68,24,30,9,'Onun yerine Tanrıları RABbe 2 Ve başlarına atayacağım kralları Davuta 2 Kulluk edecekler.'),
(2002999,68,24,30,10,'‹‹ ‹Korkma, ey kulum Yakup, 2 Yılma, ey İsrail› diyor RAB. 2 ‹Çünkü seni uzak yerlerden, 2 Soyunu sürgün edildiği ülkeden kurtaracağım. 2 Yakup yine huzur ve güvenlik içinde olacak, 2 Kimse onu korkutmayacak.'),
(2003000,68,24,30,11,'Çünkü ben seninleyim, 2 Seni kurtaracağım› diyor RAB. 2 ‹Seni aralarına dağıttığım bütün ulusları 2 Tümüyle yok etsem de, 2 Seni büsbütün yok etmeyecek, 2 Adaletle yola getirecek, 2 Hiç cezasız bırakmayacağım.›'),
(2003001,68,24,30,12,'‹‹RAB diyor ki, 2 ‹Senin yaran şifa bulmaz, 2 Beren iyileşmez.'),
(2003002,68,24,30,13,'Davanı görecek kimse yok, 2 Yaran umarsız, şifa bulmaz.'),
(2003003,68,24,30,14,'Bütün oynaşların unuttu seni, 2 Arayıp sormuyorlar. 2 Seni düşman vururcasına vurdum, 2 Acımasızca cezalandırdım. 2 Çünkü suçun çok, 2 Günahların sayısız.'),
(2003004,68,24,30,15,'Neden haykırıyorsun yarandan ötürü? 2 Yaran şifa bulmaz. 2 Suçlarının çokluğu ve sayısız günahın yüzünden 2 Getirdim bunları başına.'),
(2003005,68,24,30,16,'Ama seni yiyenlerin hepsi yem olacak, 2 Bütün düşmanların sürgüne gidecek. 2 Seni soyanlar soyulacak, 2 Yağmalayanlar yağmalanacak.'),
(2003006,68,24,30,17,'Ama ben seni sağlığına kavuşturacak, 2 Yaralarını iyileştireceğim› diyor RAB, 2 ‹Çünkü Siyon itilmiş, 2 Onu arayan soran yok diyorlar.›'),
(2003007,68,24,30,18,'‹‹RAB diyor ki, 2 ‹Yakupun çadırlarını eski gönencine kavuşturacağım, 2 Konutlarına acıyacağım. 2 Yeruşalim höyük üzerinde yeniden kurulacak, 2 Saray kendi yerinde duracak.'),
(2003008,68,24,30,19,'Oralardan şükran ve sevinç sesleri duyulacak. 2 Sayılarını çoğaltacağım, azalmayacaklar, 2 Onları onurlandıracağım, küçümsenmeyecekler.'),
(2003009,68,24,30,20,'Çocukları eskisi gibi olacak, 2 Toplulukları önümde sağlam duracak; 2 Onlara baskı yapanların hepsini cezalandıracağım.'),
(2003010,68,24,30,21,'Önderleri kendilerinden biri olacak, 2 Yöneticileri kendi aralarından çıkacak. 2 Onu kendime yaklaştıracağım, 2 Bana yaklaşacak. 2 Kim canı pahasına yaklaşabilir bana?› diyor RAB.'),
(2003011,68,24,30,22,'‹‹ ‹Böylece siz benim halkım olacaksınız, 2 Ben de sizin Tanrınız olacağım.›'),
(2003012,68,24,30,23,'İşte RABbin fırtınası öfkeyle kopacak, 2 Şiddetli kasırgası kötülerin başında patlayacak.'),
(2003013,68,24,30,24,'Aklının tasarladığını tümüyle yapana dek, 2 RAB''bin kızgın öfkesi dinmeyecek. 2 Son günlerde bunu anlayacaksınız.››'),
(2003014,68,24,31,1,'‹‹O zaman›› diyor RAB, ‹‹Bütün İsrail boylarının Tanrısı olacağım, onlar da benim halkım olacaklar.››'),
(2003015,68,24,31,2,'RAB diyor ki, 2 ‹‹Kılıçtan kaçıp kurtulan halk çölde lütuf buldu. 2 Ben İsraili rahata kavuşturmaya gelirken,'),
(2003016,68,24,31,3,'Ona uzaktan görünüp şöyle dedim: 2 Seni sonsuz bir sevgiyle sevdim, 2 Bu nedenle sevecenlikle seni kendime çektim.'),
(2003017,68,24,31,4,'Seni yeniden bina edeceğim, 2 Yeniden bina edileceksin, ey erden kız İsrail! 2 Yine teflerini alacak, 2 Sevinçle coşup oynayanlara katılacaksın.'),
(2003018,68,24,31,5,'Samiriye dağlarında yine bağ dikeceksin; 2 Bağ dikenler üzümünü yiyecekler.'),
(2003019,68,24,31,6,'Efrayimin dağlık bölgesindeki bekçilerin, 2 ‹Haydi, Siyona, Tanrımız RABbe çıkalım 2 Diye bağıracakları bir gün var.››'),
(2003020,68,24,31,7,'RAB diyor ki, 2 ‹‹Yakup için sevinçle haykırın! 2 Ulusların başı olan için bağırın! 2 Övgülerinizi duyurun! 2 ‹Ya RAB, halkını, İsrailden sağ kalanları kurtar› deyin.'),
(2003021,68,24,31,8,'İşte, onları kuzey ülkesinden 2 Geri getirmek üzereyim; 2 Onları dünyanın dört bucağından toplayacağım. 2 Aralarında kör, topal, 2 Gebe kadın da, doğuran kadın da olacak. 2 Büyük bir topluluk olarak buraya dönecekler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003022,68,24,31,9,'Ağlaya ağlaya gelecekler, 2 Benden yardım dileyenleri geri getireceğim. 2 Akarsular boyunca tökezlemeyecekleri 2 Düz bir yolda yürüteceğim onları. 2 Çünkü ben İsrailin babasıyım, 2 Efrayim de ilk oğlumdur.'),
(2003023,68,24,31,10,'‹‹RABbin sözünü dinleyin, ey uluslar! 2 Uzaktaki kıyılara duyurun: 2 ‹İsraili dağıtan onu toplayacak, 2 Sürüsünü kollayan çoban gibi kollayacak onu› deyin.'),
(2003024,68,24,31,11,'Çünkü RAB Yakupu kurtaracak, 2 Onu kendisinden güçlü olanın elinden özgür kılacak.'),
(2003025,68,24,31,12,'Siyonun yüksek tepelerine gelip 2 Sevinçle haykıracaklar. 2 RABbin verdiği iyilikler karşısında 2 -Tahıl, yeni şarap, zeytinyağı, 2 Davar ve sığır yavruları karşısında- 2 Yüzleri sevinçle parlayacak. 2 Sulanmış bahçe gibi olacak, 2 Bir daha solmayacaklar.'),
(2003026,68,24,31,13,'O zaman erden kızlar, genç yaşlı erkekler 2 Hep birlikte oynayıp sevinecek. 2 Yaslarını coşkuya çevirecek, 2 Üzüntülerini avutup onları sevindireceğim.'),
(2003027,68,24,31,14,'Kâhinleri bol yiyecekle doyuracağım, 2 Halkım iyiliklerimle doyacak›› diyor RAB.'),
(2003028,68,24,31,15,'RAB diyor ki, 2 ‹‹Ramada bir ses duyuldu, 2 Ağlayış ve acı feryat sesleri! 2 Çocukları için ağlayan Rahel avutulmak istemiyor. 2 Çünkü onlar yok artık!››'),
(2003029,68,24,31,16,'RAB diyor ki, 2 ‹‹Sesini ağlamaktan, 2 Gözlerini yaş dökmekten alıkoy. 2 Çünkü verdiğin emek ödüllendirilecek›› diyor RAB. 2 ‹‹Halkım düşman ülkesinden geri dönecek.'),
(2003030,68,24,31,17,'Geleceğin için umut var›› diyor RAB. 2 ‹‹Çocukların yurtlarına dönecekler.'),
(2003031,68,24,31,18,'‹‹Efrayimin inlemelerini kuşkusuz duydum: 2 ‹Beni eğitilmemiş dana gibi yola getirdin 2 Ve yola geldim. 2 Beni geri getir, döneyim. 2 Çünkü RAB Tanrım sensin.'),
(2003032,68,24,31,19,'Yanlış yola saptıktan sonra pişman oldum. 2 Aklım başıma gelince bağrımı dövdüm. 2 Gençliğimdeki ayıplarımdan utandım, 2 Rezil oldum.›'),
(2003033,68,24,31,20,'‹‹Efrayim değerli oğlum değil mi? 2 Hoşnut olduğum çocuk değil mi? 2 Kendisi için ne dersem diyeyim, 2 Onu hiç unutmuyorum. 2 Bu yüzden yüreğim sızlıyor, 2 Çok acıyorum ona›› diyor RAB.'),
(2003034,68,24,31,21,'‹‹Kendin için yol işaretleri koy, 2 Direkler dik. 2 Yolunu, gittiğin yolu iyi düşün. 2 Geri dön, ey erden kız İsrail, kentlerine dön!'),
(2003035,68,24,31,22,'Ne zamana dek bocalayıp duracaksın, ey dönek kız? 2 RAB dünyada yeni bir şey yarattı: 2 Kadın erkeği koruyacak.››'),
(2003036,68,24,31,23,'İsrailin Tanrısı, Her Şeye Egemen RAB şöyle diyor: ‹‹Yahuda ve kentlerindeki halkı eski gönençlerine kavuşturduğum zaman yine şu sözleri söyleyecekler: ‹RAB sizi kutsasın, 2 Ey doğruluk yurdu, ey kutsal dağ!›'),
(2003037,68,24,31,24,'Halk, ırgatlar, sürüleriyle dolaşan çobanlar Yahudada ve kentlerinde birlikte yaşayacak.'),
(2003038,68,24,31,25,'Yorgun cana kana kana içirecek, bitkin canı doyuracağım.››'),
(2003039,68,24,31,26,'Bunun üzerine uyanıp baktım. Uykum bana tatlı geldi.'),
(2003040,68,24,31,27,'‹‹İsrail ve Yahudada insan ve hayvan tohumu ekeceğim günler yaklaşıyor›› diyor RAB,'),
(2003041,68,24,31,28,'‹‹Kökünden söküp yok etmek, yerle bir edip yıkmak, yıkıma uğratmak için onları nasıl gözledimse, kurup dikmek için de gözleyeceğim›› diyor RAB.'),
(2003042,68,24,31,29,'‹‹O günler insanlar artık, ‹Babalar koruk yedi, 2 Çocukların dişleri kamaştı'),
(2003043,68,24,31,30,'Herkes kendi suçu yüzünden ölecek. Koruk yiyenin dişleri kamaşacak.'),
(2003044,68,24,31,31,'‹‹İsrail halkıyla ve Yahuda halkıyla 2 Yeni bir antlaşma yapacağım günler geliyor›› diyor RAB,'),
(2003045,68,24,31,32,'‹‹Atalarını Mısırdan çıkarmak için 2 Ellerinden tuttuğum gün 2 Onlarla yaptığım antlaşmaya benzemeyecek. 2 Onların kocası olmama karşın, 2 Bozdular o antlaşmamı›› diyor RAB.'),
(2003046,68,24,31,33,'‹‹Ama o günlerden sonra İsrail halkıyla 2 Yapacağım antlaşma şudur›› diyor RAB, 2 ‹‹Yasamı içlerine yerleştirecek, 2 Yüreklerine yazacağım. 2 Ben onların Tanrısı olacağım, 2 Onlar da benim halkım olacak.'),
(2003047,68,24,31,34,'Bundan böyle kimse komşusunu ya da kardeşini, 2 ‹RABbi tanıyın› diye eğitmeyecek. 2 Çünkü küçük büyük hepsi 2 Tanıyacak beni›› diyor RAB. 2 ‹‹Çünkü suçlarını bağışlayacağım, 2 Günahlarını artık anmayacağım.››'),
(2003048,68,24,31,35,'Gündüz ışık olsun diye güneşi sağlayan, 2 Gece ışık olsun diye ayı, yıldızları düzene koyan, 2 Dalgaları kükresin diye denizi kabartan RAB 2 -Onun adı Her Şeye Egemen RABdir- diyor ki,'),
(2003049,68,24,31,36,'‹‹Eğer kurulan bu düzen önümden kalkarsa, 2 İsrail soyu sonsuza dek 2 Önümde ulus olmaktan çıkar›› diyor RAB.'),
(2003050,68,24,31,37,'RAB şöyle diyor: 2 ‹‹Gökler ölçülebilse, 2 Dünyanın temelleri incelenip anlaşılabilse, 2 İsrail soyunu bütün yaptıkları yüzünden 2 Reddederim›› diyor RAB.'),
(2003051,68,24,31,38,'‹‹Yeruşalim Kentinin Hananel Kulesinden Köşe Kapısına dek benim için yeniden kurulacağı günler geliyor›› diyor RAB,'),
(2003052,68,24,31,39,'‹‹Ölçü ipi oradan Garev Tepesine doğru uzayıp Goaya dönecek.'),
(2003053,68,24,31,40,'Ölülerle küllerin atıldığı bütün vadi, Kidron Vadisi''ne dek uzanan tarlalar, doğuda At Kapısı''nın köşesine dek RAB için kutsal olacak. Kent bir daha kökünden sökülmeyecek, sonsuza dek yıkılmayacak.››'),
(2003054,68,24,32,1,'Yahuda Kralı Sidkiyanın onuncu, Nebukadnessarın on sekizinci yılında RAB Yeremyaya seslendi.'),
(2003055,68,24,32,2,'O sırada Babil Kralının ordusu Yeruşalimi kuşatmaktaydı. Peygamber Yeremya Yahuda Kralının sarayındaki muhafız avlusunda tutukluydu.'),
(2003056,68,24,32,3,'Yahuda Kralı Sidkiya onu orada tutuklatmıştı. ‹‹Neden böyle peygamberlik ediyorsun?›› demişti, ‹‹Sen diyorsun ki, ‹RAB şöyle diyor: Bu kenti Babil Kralının eline teslim etmek üzereyim, onu ele geçirecek.'),
(2003057,68,24,32,4,'Yahuda Kralı Sidkiya Kildanilerin elinden kaçıp kurtulamayacak, kesinlikle Babil Kralının eline teslim edilecek; onunla yüzyüze konuşacak, onu gözleriyle görecek.'),
(2003058,68,24,32,5,'Sidkiya Babile götürülecek, ben onunla ilgilenene dek orada kalacak, Kildanilerle savaşsanız bile başarılı olamayacaksınız diyor RAB.› ››'),
(2003059,68,24,32,6,'Yeremya, ‹‹RAB bana şöyle seslendi›› diye yanıtladı,'),
(2003060,68,24,32,7,'‹‹Amcan Şallum oğlu Hanamel sana gelip, ‹Anatottaki tarlamı satın al. Çünkü en yakın akrabam olarak tarlayı satın alma hakkı senindir› diyecek.'),
(2003061,68,24,32,8,'‹‹Sonra RABbin sözü uyarınca amcamın oğlu Hanamel muhafız avlusunda yanıma gelip, ‹Benyamin bölgesinde, Anatottaki tarlamı satın al› dedi, ‹Çünkü miras hakkı da en yakın akrabalık hakkı da senindir. Onu kendin için satın al.› ‹‹O zaman RABbin sözünün yerine geldiğini anladım.'),
(2003062,68,24,32,9,'Böylece Anatottaki tarlayı amcamın oğlu Hanamelden satın aldım. Tarlaya karşılık kendisine on yedi şekel gümüş tartıp ödedim.'),
(2003063,68,24,32,10,'Satış belgesini çağırdığım tanıkların önünde imzalayıp mühürledim, gümüşü terazide tarttım.'),
(2003064,68,24,32,11,'Satış belgesini -kural ve koşulları içeren mühürlenmiş kâğıdı ve açık sözleşme belgesini- aldım.'),
(2003065,68,24,32,12,'Amcamın oğlu Hanamelin, satış belgesini imzalayan tanıkların ve muhafız avlusunda oturan bütün Yahudilerin gözü önünde satış belgesini Mahseya oğlu Neriya oğlu Baruka verdim.'),
(2003066,68,24,32,13,'‹‹Hepsinin gözü önünde Baruka şu buyrukları verdim:'),
(2003067,68,24,32,14,'‹İsrailin Tanrısı, Her Şeye Egemen RAB diyor ki, Bu satış belgesini -mühürlenmiş, açık olanını- al, uzun süre durmak üzere bir çömleğe koy.'),
(2003068,68,24,32,15,'Çünkü İsrailin Tanrısı, Her Şeye Egemen RAB söz veriyor, bu ülkede yine evler, tarlalar, bağlar satın alınacak› diyor.'),
(2003069,68,24,32,16,'‹‹Tarlanın satış belgesini Neriya oğlu Baruka verdikten sonra RABbe şöyle yakardım:'),
(2003070,68,24,32,17,'‹‹Ey Egemen RAB! Büyük gücünle, kudretinle yeri göğü yarattın. Yapamayacağın hiçbir şey yok.'),
(2003071,68,24,32,18,'Binlerce insana sevgi gösterir, ama babaların işlediği günahların karşılığını çocuklarına ödetirsin. Ey büyük ve güçlü Tanrı! Her Şeye Egemen RABdir senin adın.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003072,68,24,32,19,'Tasarıların ne büyük, işlerin ne güçlü! Gözlerin insanların bütün yaptıklarına açıktır. Herkese davranışlarına, yaptıklarının sonucuna göre karşılığını verirsin.'),
(2003073,68,24,32,20,'Sen ki, Mısırda, İsrailde, bütün insanlar arasında bugüne dek mucizeler, harikalar yarattın. Bugün olduğu gibi ün kazandın.'),
(2003074,68,24,32,21,'Halkın İsraili belirtilerle, şaşılası işlerle, güçlü, kudretli elinle, büyük korku saçarak Mısırdan çıkardın.'),
(2003075,68,24,32,22,'Atalarına vereceğine ant içtiğin bu toprakları, süt ve bal akan ülkeyi onlara verdin.'),
(2003076,68,24,32,23,'Gelip ülkeyi mülk edindiler, ama senin sözünü dinlemediler, Kutsal Yasan uyarınca yürümediler. Yapmalarını buyurduğun şeylerin hiçbirini yapmadılar. Bu yüzden bütün bu felaketleri getirdin başlarına.'),
(2003077,68,24,32,24,'‹‹İşte, kenti ele geçirmek için kuşatma rampaları yapıldı. Kılıç, kıtlık, salgın hastalık yüzünden kent saldıran Kildanilere teslim edilecek. Söylediklerin yerine geldi, sen de görüyorsun!'),
(2003078,68,24,32,25,'Yine de, Egemen RAB, kent Kildanilere teslim edileceği halde sen bana, ‹Tarlayı çağırdığın tanıklar önünde gümüşle satın al› dedin.››'),
(2003079,68,24,32,26,'Bunun üzerine RAB Yeremyaya şöyle seslendi:'),
(2003080,68,24,32,27,'‹‹Bütün insanlığın Tanrısı RAB benim. Var mı yapamayacağım bir şey?'),
(2003081,68,24,32,28,'Bu yüzden RAB diyor ki: Bak, bu kenti Kildanilerle Babil Kralı Nebukadnessarın eline vermek üzereyim; onu ele geçirsin.'),
(2003082,68,24,32,29,'Kente saldıran Kildaniler gelip onu ateşe verecekler. Kenti de damlarında Baalın onuruna buhur yakıp başka ilahlara dökmelik sunular sunarak beni öfkelendirdikleri evleri de yakacaklar.'),
(2003083,68,24,32,30,'‹‹Çünkü İsrail ve Yahuda halkları gençliklerinden beri hep gözümde kötü olanı yapıyor; İsrail halkı ellerinin yaptıklarıyla beni sürekli öfkelendiriyor, diyor RAB.'),
(2003084,68,24,32,31,'Evet, bu kent kurulduğundan bu yana beni öyle öfkelendirdi, kızdırdı ki onu önümden söküp atacağım.'),
(2003085,68,24,32,32,'Çünkü İsrail ve Yahuda halklarının -kendilerinin, krallarının, önderlerinin, kâhinlerinin, peygamberlerinin, Yahuda ve Yeruşalimde yaşayanların- beni öfkelendirmek için yaptıkları kötülüklerin haddi hesabı yok.'),
(2003086,68,24,32,33,'Bana yüzlerini değil, sırtlarını çevirdiler. Onları defalarca uyarmama karşın dinlemediler, yola gelmediler.'),
(2003087,68,24,32,34,'Bana ait olan bu tapınağa iğrenç putlarını yerleştirerek onu kirlettiler.'),
(2003088,68,24,32,35,'Ben-Hinnom Vadisinde ilah Moleke sunu olarak oğullarını, kızlarını ateşte kurban etmek için Baalın tapınma yerlerini kurdular. Böyle iğrenç şeyler yaparak Yahudayı günaha sürüklemelerini ne buyurdum, ne de aklımdan geçirdim.'),
(2003089,68,24,32,36,'‹‹Siz bu kent için, ‹Kılıçla, kıtlıkla, salgın hastalıkla Babil Kralının eline veriliyor› diyorsunuz. Ama şimdi İsrailin Tanrısı RAB diyor ki:'),
(2003090,68,24,32,37,'Kızgınlıkla, gazapla, büyük öfkeyle onları sürdüğüm ülkelerden hepsini toplayacağım. Onları buraya geri getirip güvenlik içinde yaşamalarını sağlayacağım.'),
(2003091,68,24,32,38,'Onlar benim halkım olacak, ben de onların Tanrısı olacağım.'),
(2003092,68,24,32,39,'Tek bir yürek, tek bir yaşam tarzı vereceğim onlara; gerek kendilerinin gerekse çocuklarının iyiliği için benden hep korksunlar.'),
(2003093,68,24,32,40,'Onlarla kalıcı bir antlaşma yapacağım: Onlara iyilik etmekten vazgeçmeyecek, benden hiç ayrılmasınlar diye yüreklerine Tanrı korkusu salacağım.'),
(2003094,68,24,32,41,'Onlara iyilik etmekten sevinç duyacağım; gerçekten bütün yüreğimle, bütün canımla onları bu ülkede dikeceğim.'),
(2003095,68,24,32,42,'‹‹RAB diyor ki: Bu halkın başına bütün bu büyük felaketleri nasıl getirdiysem, onlara söz verdiğim bütün iyilikleri de öyle sağlayacağım.'),
(2003096,68,24,32,43,'Sizlerin, ‹Viran olmuş, insansız, hayvansız, Kildanilerin eline verilmiş› dediğiniz bu ülkede yine tarlalar satın alınacak.'),
(2003097,68,24,32,44,'Benyamin bölgesinde, Yeruşalim çevresindeki köylerde, Yahuda kentlerinde, dağlık bölgenin, Şefela''nın ve Negev''in kentlerinde gümüşle tarlalar satın alınacak, satış belgeleri tanıkların önünde imzalanıp mühürlenecek. Çünkü eski gönençlerine kavuşturacağım onları›› diyor RAB.'),
(2003098,68,24,33,1,'Yeremya muhafız avlusunda tutukluyken, RAB ona ikinci kez seslendi:'),
(2003099,68,24,33,2,'‹‹Dünyayı yaratan, yerini alsın diye ona biçim veren, adı RAB olan şöyle diyor:'),
(2003100,68,24,33,3,'‹Bana yakar da seni yanıtlayayım; bilmediğin büyük, akıl almaz şeyleri sana bildireyim.›'),
(2003101,68,24,33,4,'Kuşatma rampalarına, kılıca karşı siper olsun diye bu kentin yıkılmış olan evleriyle Yahuda krallarının sarayları için İsrailin Tanrısı RAB şöyle diyor:'),
(2003102,68,24,33,5,'‹Kildaniler savaşmak, evleri öfke ve kızgınlıkla vurduğum insanların cesetleriyle doldurmak üzere gelecekler. O insanlar ki, yaptıkları kötülükler yüzünden bu kentten yüzümü çevirdim. ‹‹Kildanilerle››.'),
(2003103,68,24,33,6,'‹‹ ‹Yine de bu kenti iyileştirip sağlığa kavuşturacağım. Halkına şifa verecek, bol esenlik, güvenlik içinde yaşamalarını sağlayacağım.'),
(2003104,68,24,33,7,'Yahudayı ve İsraili eski gönencine kavuşturacak, önceden olduğu gibi bina edeceğim.'),
(2003105,68,24,33,8,'Onları bana karşı işledikleri bütün günahlardan arındıracak, bana karşı işledikleri günahları da isyanlarını da bağışlayacağım.'),
(2003106,68,24,33,9,'Dünyadaki bütün ulusların önünde bu kent benim için sevinç, övgü ve onur kaynağı olacak. Bu uluslar Yeruşalim halkına yaptığım iyilikleri, sağladığım gönenci duyunca, korkuya kapılıp titreyecekler.›'),
(2003107,68,24,33,10,'‹‹RAB şöyle diyor: ‹Bu kent viran olmuş, insansız, hayvansız kalmış diyorsunuz. Ne var ki, terk edilmiş, insansız, hayvansız Yahuda kentlerinde, Yeruşalim sokaklarında sevinç ve neşe sesi, gelin güvey sesi, RABbin Tapınağına şükran sunuları getirenlerin sesi yine duyulacak: ‹Her Şeye Egemen RABbe şükredin, 2 Çünkü O iyidir, 2 Sevgisi sonsuza dek kalıcıdır.'),
(2003108,68,24,33,12,'‹‹Her Şeye Egemen RAB diyor ki, ‹Viran olmuş, insansız, hayvansız kalmış bu ülkenin bütün kentlerinde çobanların sürülerini dinlendireceği otlaklar olacak yeniden.'),
(2003109,68,24,33,13,'Dağlık bölgede, Şefela, Negev, Benyamin bölgesindeki kentlerde, Yeruşalimin çevresindeki köylerde, Yahuda kentlerinde çoban değneğinin altından geçen sürüler olacak› diyor RAB.'),
(2003110,68,24,33,14,'‹‹ ‹İsrail ve Yahuda halkına verdiğim güzel sözü yerine getireceğim günler geliyor› diyor RAB.'),
(2003111,68,24,33,15,'‹‹ ‹O günlerde, o zamanda, 2 Davut için doğru bir dal yetiştireceğim; 2 Ülkede adil ve doğru olanı yapacak.'),
(2003112,68,24,33,16,'O günlerde Yahuda kurtulacak, 2 Yeruşalim güvenlik içinde yaşayacak. 2 O, Yahve sidkenu adıyla anılacak.›'),
(2003113,68,24,33,17,'RAB şöyle diyor: ‹İsrail tahtı üzerinde oturan Davut soyunun ardı arkası kesilmeyecek.'),
(2003114,68,24,33,18,'Levili kâhinlerden önümde yakmalık sunu sunacak, tahıl sunusu yakacak, kurban kesecek biri hiç eksik olmayacak.› ››'),
(2003115,68,24,33,19,'RAB Yeremyaya şöyle seslendi:'),
(2003116,68,24,33,20,'‹‹RAB diyor ki, ‹Eğer belirlenmiş zamanlarda gece ve gündüz olması için gece ve gündüzle yaptığım antlaşma bozulabilirse, tahtında oturan oğulları krallık yapsın diye kulum Davutla ve bana hizmet eden Levili kâhinlerle yaptığım antlaşma da ancak o zaman bozulabilir.'),
(2003117,68,24,33,22,'Kulum Davutun soyunu ve bana hizmet eden Levilileri sayılamaz gök cisimleri kadar, ölçülemez deniz kumu kadar çoğaltacağım.› ››'),
(2003118,68,24,33,23,'RAB Yeremyaya şöyle seslendi:'),
(2003119,68,24,33,24,'‹‹Bu halkın, ‹RAB seçtiği iki aileyi de reddetti› dediğini görmüyor musun? Halkımı öyle küçümsüyorlar ki, artık bir ulus saymıyorlar onu.'),
(2003120,68,24,33,25,'RAB diyor ki, ‹Gece ve gündüzle bir antlaşma yapıp yerin, göğün kurallarını saptamasaydım,'),
(2003121,68,24,33,26,'Yakup soyuyla kulum Davut''u da reddeder, Davut''un oğullarından birinin İbrahim, İshak, Yakup soyuna krallık etmesini sağlamazdım. Ama ben onları eski gönençlerine kavuşturacak, onlara acıyacağım.› ››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003122,68,24,34,1,'Babil Kralı Nebukadnessarla bütün ordusu, krallığı altındaki bütün uluslarla halklar, Yeruşalim ve çevresindeki kentlere karşı savaşırken RAB Yeremyaya şöyle seslendi:'),
(2003123,68,24,34,2,'‹‹İsrailin Tanrısı RAB diyor ki, ‹Git, Yahuda Kralı Sidkiyaya RAB şöyle diyor de: Bu kenti Babil Kralının eline teslim etmek üzereyim, onu ateşe verecek.'),
(2003124,68,24,34,3,'Ve sen Sidkiya, onun elinden kaçıp kurtulamayacaksın; kesinlikle yakalanacak, onun eline teslim edileceksin. Babil Kralını gözünle görecek, onunla yüzyüze konuşacaksın. Sonra Babile götürüleceksin.'),
(2003125,68,24,34,4,'‹‹ ‹Ancak, ey Yahuda Kralı Sidkiya, RABbin sözünü dinle! RAB senin için şöyle diyor: Kılıçla ölmeyeceksin,'),
(2003126,68,24,34,5,'esenlikle öleceksin. Ataların olan senden önceki kralların onuruna ateş yaktıkları gibi, senin onuruna da ateş yakıp senin için ah efendimiz diyerek ağıt tutacaklar. Ben RAB söylüyorum bunu.› ››'),
(2003127,68,24,34,6,'Peygamber Yeremya bütün bunları Yeruşalimde Yahuda Kralı Sidkiyaya söyledi.'),
(2003128,68,24,34,7,'O sırada Babil Kralının ordusu Yeruşalime ve Yahudanın henüz ele geçirilmemiş kentlerine -Lakişe, Azekaya- saldırmaktaydı. Yahudada surlu kent olarak yalnız bunlar kalmıştı.'),
(2003129,68,24,34,8,'Kral Sidkiya Yeruşalimdeki halkla kölelerin özgürlüğünü ilan eden bir antlaşma yaptıktan sonra RAB Yeremyaya seslendi.'),
(2003130,68,24,34,9,'Bu antlaşmaya göre herkes kadın, erkek İbrani kölelerini özgür bırakacak, hiç kimse Yahudi kardeşini yanında köle olarak tutmayacaktı.'),
(2003131,68,24,34,10,'Böylece bu antlaşmanın yükümlülüğü altına giren bütün önderlerle halk kadın, erkek kölelerini özgür bırakarak antlaşmaya uydular. Artık kimseyi köle olarak tutmadılar. Antlaşmaya uyarak köleleri özgür bıraktılar.'),
(2003132,68,24,34,11,'Ama sonra düşüncelerini değiştirerek özgür bıraktıkları kadın, erkek köleleri geri alıp zorla köleleştirdiler.'),
(2003133,68,24,34,12,'Bunun üzerine RAB Yeremyaya şöyle seslendi:'),
(2003134,68,24,34,13,'‹‹İsrailin Tanrısı RAB diyor ki: Atalarınızı Mısırdan, köle oldukları ülkeden çıkardığımda onlarla bir antlaşma yaptım. Onlara dedim ki,'),
(2003135,68,24,34,14,'‹Size satılıp altı yıl kölelik eden İbrani kardeşlerinizi yedinci yıl özgür bırakacaksınız.› Ama atalarınız beni dinlemediler, kulak asmadılar.'),
(2003136,68,24,34,15,'Sizse sonradan yola gelip gözümde doğru olanı yaptınız: Hepiniz İbrani kardeşlerinizin özgürlüğünü ilan ettiniz. Önümde, bana ait olan tapınakta bu doğrultuda bir antlaşma yapmıştınız.'),
(2003137,68,24,34,16,'Ama düşüncenizi değiştirerek adıma saygısızlık ettiniz. Kendi isteğinizle özgür bıraktığınız kadın, erkek kölelerinizi geri alıp zorla köleleştirdiniz.'),
(2003138,68,24,34,17,'‹‹Bu nedenle RAB diyor ki, İbrani köle kardeşlerinizi, yurttaşlarınızı özgür bırakmayarak beni dinlemediniz. Şimdi ben size ‹özgürlük› -kılıç, kıtlık ve salgın hastalıkla yok olmanız için ‹özgürlük›- ilan edeceğim, diyor RAB. Sizi dünyadaki bütün krallıklara dehşet verici bir örnek yapacağım.'),
(2003139,68,24,34,18,'Antlaşmamı bozan, danayı ikiye ayırıp parçaları arasından geçerek önümde yaptıkları antlaşmanın koşullarını yerine getirmeyen bu adamları -Yahuda ve Yeruşalim önderlerini, saray görevlilerini, kâhinleri ve dana parçalarının arasından geçen bütün ülke halkını-'),
(2003140,68,24,34,20,'can düşmanlarının eline teslim edeceğim. Cesetleri yırtıcı kuşlara, yabanıl hayvanlara yem olacak.'),
(2003141,68,24,34,21,'‹‹Yahuda Kralı Sidkiyayla önderlerini de can düşmanlarının eline, üzerinizden çekilen Babil ordusunun eline teslim edeceğim.'),
(2003142,68,24,34,22,'Buyruğu ben vereceğim diyor RAB. Babilliler''i bu kente geri getireceğim. Saldırıp kenti ele geçirecek, ateşe verecekler. Yahuda kentlerini içinde kimsenin yaşamayacağı bir viraneye çevireceğim.››'),
(2003143,68,24,35,1,'Yahuda Kralı Yoşiya oğlu Yehoyakim döneminde RAB Yeremyaya şöyle seslendi:'),
(2003144,68,24,35,2,'‹‹Rekavlıların evine gidip onlarla konuş. Onları RABbin Tapınağının odalarından birine götürüp şarap içir.››'),
(2003145,68,24,35,3,'Bunun üzerine Havassinya oğlu Yirmeya oğlu Yaazanyayı, kardeşlerini, bütün çocuklarını ve Rekav ailesinin öbür üyelerini yanıma alıp'),
(2003146,68,24,35,4,'Tanrı adamı Yigdalya oğlu Hananın oğullarının RABbin Tapınağındaki odasına götürdüm. Bu oda önderlerin odasının bitişiğinde, kapı görevlisi Şallum oğlu Maaseyanın odasının üstündeydi.'),
(2003147,68,24,35,5,'Rekav ailesinin üyelerinin önüne şarap dolu testiler, kâseler koyarak, ‹‹Buyrun, şarap için›› dedim.'),
(2003148,68,24,35,6,'Ne var ki, ‹‹Biz şarap içmeyiz›› diye karşılık verdiler, ‹‹Çünkü atamız Rekav oğlu Yehonadav bize şu buyruğu verdi: ‹Siz de soyunuzdan gelenler de asla şarap içmeyeceksiniz!'),
(2003149,68,24,35,7,'Ayrıca ev yapmayacak, tohum ekmeyecek, bağ dikmeyeceksiniz. Böyle şeyler edinmeyecek, ömür boyu çadırlarda yaşayacaksınız. Öyle ki, göç ettiğiniz topraklarda uzun süre yaşayasınız.›'),
(2003150,68,24,35,8,'Atamız Rekav oğlu Yehonadavın bize buyurduğu her şeyi yaptık. Kendimiz de karılarımız, oğullarımız, kızlarımız da hiç şarap içmedik.'),
(2003151,68,24,35,9,'İçinde oturmak için evler yapmadık, bağlar, tarlalar, ekinler edinmedik.'),
(2003152,68,24,35,10,'Çadırlarda yaşadık; atamız Yehonadav ne buyurduysa hepsini yaptık.'),
(2003153,68,24,35,11,'Ama Babil Kralı Nebukadnessar bu ülkeye saldırınca, ‹Haydi, Kildan ve Aram ordusundan kaçmak için Yeruşalime gidelim› dedik. Bunun için Yeruşalimde kaldık.››'),
(2003154,68,24,35,12,'Bundan sonra RAB Yeremyaya şöyle seslendi:'),
(2003155,68,24,35,13,'‹‹İsrailin Tanrısı, Her Şeye Egemen RAB şöyle diyor: ‹Git, Yahuda halkına ve Yeruşalimde yaşayanlara şunları söyle: Sözlerimi dinleyerek hiç ders almayacak mısınız, diyor RAB.'),
(2003156,68,24,35,14,'Rekav oğlu Yehonadav, soyuna şarap içmemelerini buyurdu; buyruğuna uyuldu. Bugüne dek şarap içmediler. Çünkü atalarının buyruğuna uydular. Bense size defalarca seslendiğim halde beni dinlemediniz.'),
(2003157,68,24,35,15,'Defalarca size kullarım peygamberleri gönderdim. Kötü yolunuzdan dönmeniz, davranışlarınızı düzeltmeniz, başka ilahların ardınca gidip onlara tapınmamanız için hepinizi uyardılar. Ancak o zaman size ve atalarınıza verdiğim toprakta yaşayacaksınız. Ama kulak verip beni dinlemediniz.'),
(2003158,68,24,35,16,'Rekav oğlu Yehonadavın soyu atalarının verdiği buyruğu tuttu, ama bu halk beni dinlemedi.›'),
(2003159,68,24,35,17,'‹‹Bu yüzden İsrailin Tanrısı, Her Şeye Egemen RAB diyor ki, ‹İşte, Yahuda ve Yeruşalimde yaşayan herkesin başına sözünü ettiğim her felaketi getirmek üzereyim. Çünkü onları uyardım, ama dinlemediler; onları çağırdım, ama yanıt vermediler.› ››'),
(2003160,68,24,35,18,'Yeremya Rekav ailesine şöyle dedi: ‹‹İsrailin Tanrısı, Her Şeye Egemen RAB diyor ki, ‹Atanız Yehonadavın buyruğuna uydunuz, onun bütün uyarılarını dikkate aldınız, size buyurduğu her şeyi yaptınız.›'),
(2003161,68,24,35,19,'Bunun için İsrail''in Tanrısı, Her Şeye Egemen RAB diyor ki, ‹Rekav oğlu Yehonadav''ın soyundan önümde hizmet edecek olanlar hiçbir zaman eksilmeyecek.› ››'),
(2003162,68,24,36,1,'Yahuda Kralı Yoşiya oğlu Yehoyakimin krallığının dördüncü yılında RAB Yeremyaya şöyle seslendi:'),
(2003163,68,24,36,2,'‹‹Bir tomar al, Yoşiyanın döneminden bu yana İsrail, Yahuda ve öteki uluslarla ilgili sana söylediğim her şeyi yaz.'),
(2003164,68,24,36,3,'Belki Yahuda halkı başına getirmeyi tasarladığım bütün felaketleri duyar da kötü yolundan döner; ben de suçlarını, günahlarını bağışlarım.››'),
(2003165,68,24,36,4,'Yeremya Neriya oğlu Baruku çağırıp RABbin kendisine söylediği bütün sözleri tomara yazdırdı.'),
(2003166,68,24,36,5,'Sonra Baruka şu buyruğu verdi: ‹‹Ben tutukluyum, RABbin Tapınağına gidemem.'),
(2003167,68,24,36,6,'Sen oruç günü RABbin Tapınağına git. Oradaki halka sana yazdırdığım RABbin sözlerini tomardan oku. Yahuda kentlerinden gelen halka da oku.'),
(2003168,68,24,36,7,'Belki RABbe yalvarır, kötü yollarından dönerler. Çünkü RABbin bu halka karşı sözünü ettiği öfke ve kızgınlığı büyüktür.››'),
(2003169,68,24,36,8,'Neriya oğlu Baruk, Peygamber Yeremyanın buyurduğu her şeyi yaptı. RABbin tomarda yazılı sözlerini tapınakta okudu.'),
(2003170,68,24,36,9,'Yahuda Kralı Yoşiya oğlu Yehoyakimin krallığının beşinci yılının dokuzuncu ayı, Yeruşalimde yaşayan bütün halk ve Yahuda kentlerinden Yeruşalime gelen herkes için RABbin önünde oruç ilan edildi.'),
(2003171,68,24,36,10,'Şafan oğlu Yazman Gemaryanın yukarı avluda, tapınağın Yeni Kapısının girişindeki odasında Baruk, Yeremyanın sözlerini tomardan RABbin Tapınağındaki bütün halka okudu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003172,68,24,36,11,'Şafan oğlu Gemarya oğlu Mikaya tomardan okunan RABbin sözlerini duyunca,'),
(2003173,68,24,36,12,'aşağıya inip saraydaki yazman odasına gitti. Bütün önderler orada toplantı halindeydi: Yazman Elişama, Şemaya oğlu Delaya, Akbor oğlu Elnatan, Şafan oğlu Gemarya, Hananya oğlu Sidkiya ve öbürleri.'),
(2003174,68,24,36,13,'Mikaya Barukun halka okuduğu tomardan duyduğu her şeyi onlara iletti.'),
(2003175,68,24,36,14,'Bunun üzerine bütün önderler Kuşi oğlu Şelemya oğlu Netanya oğlu Yehudiyi Baruka gönderdiler. Yehudi Baruka, ‹‹Halka okuduğun tomarı al, gel›› dedi. Neriya oğlu Baruk tomarı alıp yanlarına gitti.'),
(2003176,68,24,36,15,'Önderler, ‹‹Lütfen otur, bize de oku›› dediler. Baruk da tomarı onlara okudu.'),
(2003177,68,24,36,16,'Bütün bu sözleri duyar duymaz, korkuyla birbirlerine bakıp Baruka, ‹‹Bütün bu sözleri kesinlikle krala bildirmemiz gerek›› dediler.'),
(2003178,68,24,36,17,'Sonra Baruka, ‹‹Söyle bize, bütün bunları nasıl yazdın? Yeremya mı yazdırdı sana?›› diye sordular.'),
(2003179,68,24,36,18,'Baruk, ‹‹Evet›› diye yanıtladı, ‹‹Bütün bu sözleri o söyledi. Ben de hepsini mürekkeple tomara yazdım.››'),
(2003180,68,24,36,19,'Bunun üzerine Baruka, ‹‹Git, sen de Yeremya da gizlenin. Nerede olduğunuzu kimse bilmesin›› dediler.'),
(2003181,68,24,36,20,'Tomarı Yazman Elişamanın odasında bırakıp avluda bulunan kralın yanına gittiler. Ona duydukları her sözü ilettiler.'),
(2003182,68,24,36,21,'Kral tomarı alıp getirmesi için Yehudiyi gönderdi. Yehudi tomarı Yazman Elişamanın odasından getirdi. Krala ve yanındaki önderlere okudu.'),
(2003183,68,24,36,22,'Dokuzuncu aydı, kral kışlık sarayındaydı. Önünde mangalda ateş yanıyordu.'),
(2003184,68,24,36,23,'Yehudi tomardan üç dört sütun okur okumaz kral yazman çakısıyla onları kesip mangaldaki ateşe attı. Tomarın tümü yanıp bitene dek bu işi sürdürdü.'),
(2003185,68,24,36,24,'Tomardaki sözleri duyan kralla görevlileri ne korktular ne de giysilerini yırttılar.'),
(2003186,68,24,36,25,'Elnatan, Delaya ve Gemarya tomarı yakmaması için yalvardılarsa da kral onları dinlemedi.'),
(2003187,68,24,36,26,'Yazman Baruku ve Peygamber Yeremyayı tutuklamaları için oğlu Yerahmeele, Azriel oğlu Serayaya ve Avdeel oğlu Şelemyaya buyruk verdi. Oysa RAB onları gizlemişti.'),
(2003188,68,24,36,27,'Kral, Yeremyanın Baruka yazdırdığı sözleri içeren tomarı yaktıktan sonra, RAB Yeremyaya şöyle seslendi:'),
(2003189,68,24,36,28,'‹‹Başka bir tomar al, Yahuda Kralı Yehoyakimin yaktığı ilk tomardaki bütün sözleri yazdır.'),
(2003190,68,24,36,29,'Yahuda Kralı Yehoyakim için de ki, ‹RAB şöyle diyor: Babil Kralının kesinlikle gelip bu ülkeyi viraneye çevireceğini, içindeki insanı da hayvanı da yok edeceğini neden tomara yazdın diye sorup tomarı yaktın.'),
(2003191,68,24,36,30,'Bu yüzden RAB Yahuda Kralı Yehoyakim için şöyle diyor: Davutun tahtında oturan kimsesi olmayacak; ölüsü gündüzün sıcağa, gece ayaza bırakılacak.'),
(2003192,68,24,36,31,'İşledikleri suçlar yüzünden kendisini de çocuklarıyla görevlilerini de cezalandıracağım. Onların, Yeruşalimde yaşayanların ve Yahuda halkının başına sözünü ettiğim bütün felaketleri getireceğim. Çünkü beni dinlemediler.› ››'),
(2003193,68,24,36,32,'Bunun üzerine Yeremya başka bir tomar alıp Neriya oğlu Yazman Baruk''a verdi. Yahuda Kralı Yehoyakim''in ateşe atıp yaktığı tomardaki bütün sözleri Baruk Yeremya''nın ağzından tomara yazdı. Bu sözlere, benzer birçok söz daha eklendi.'),
(2003194,68,24,37,1,'Babil Kralı Nebukadnessarın Yahudaya atadığı Yoşiya oğlu Sidkiya, Yehoyakim oğlu Yehoyakinin yerine kral oldu.'),
(2003195,68,24,37,2,'Ama kendisi de görevlileriyle ülke halkı da RABbin Peygamber Yeremya aracılığıyla söylediği sözleri dikkate almadılar.'),
(2003196,68,24,37,3,'Kral Sidkiya, Şelemya oğlu Yehukalla Maaseya oğlu Kâhin Sefanyayı şu haberle Peygamber Yeremyaya gönderdi: ‹‹Lütfen bizim için Tanrımız RABbe yalvar.››'),
(2003197,68,24,37,4,'O sırada Yeremya daha cezaevine konmamıştı, halk arasında dolaşıyordu.'),
(2003198,68,24,37,5,'Firavunun ordusu Mısırdan çıkmıştı. Yeruşalimi kuşatma altında tutan Kildaniler bu haberi duyunca Yeruşalimden çekildiler.'),
(2003199,68,24,37,6,'Derken RAB Peygamber Yeremyaya şöyle seslendi:'),
(2003200,68,24,37,7,'‹‹İsrailin Tanrısı RAB diyor ki: Danışmak için sizi bana gönderen Yahuda Kralına şöyle deyin: ‹Size yardım etmek için Mısırdan çıkıp gelen firavunun ordusu ülkesine dönecek.'),
(2003201,68,24,37,8,'Kildaniler de dönecek; bu kentle savaşıp onu ele geçirecek, ateşe verecekler.›'),
(2003202,68,24,37,9,'‹‹RAB diyor ki, ‹Kildaniler üzerimizden çekilip gidecek› diyerek kendinizi aldatmayın. Çünkü çekilip gitmeyecekler!'),
(2003203,68,24,37,10,'Sizinle savaşan bütün Babil ordusunu bozguna uğratsanız, çadırlarında yalnız yaralılar kalsa bile, bunlar çadırlardan çıkıp bu kenti ateşe verecekler.››'),
(2003204,68,24,37,11,'Firavunun ordusu yüzünden Babil ordusu Yeruşalimden çekilince,'),
(2003205,68,24,37,12,'Peygamber Yeremya Benyamin topraklarındaki halkın arasında payına düşen mirası almak üzere Yeruşalimden gitmek istedi. Benyamin Kapısına vardığında, Hananya oğlu Şelemya oğlu bekçibaşı Yiriya, ‹‹Sen Kildanilerin tarafına geçiyorsun!›› diyerek onu tutukladı.'),
(2003206,68,24,37,14,'Yeremya, ‹‹Yalan!›› dedi, ‹‹Ben Kildanilerin tarafına geçmiyorum.›› Ama Yiriya onu dinlemedi. Yeremyayı tutuklayıp önderlere götürdü.'),
(2003207,68,24,37,15,'Yeremyaya öfkelenen önderler onu dövdürtüp cezaevine çevirdikleri Yazman Yonatanın evine kapattılar.'),
(2003208,68,24,37,16,'Böylece bodrumda bir hücreye kapatılan Yeremya uzun süre orada kaldı.'),
(2003209,68,24,37,17,'Sonra Kral Sidkiya Yeremyayı sarayına getirtti. Orada kendisine gizlice, ‹‹RABden bir söz var mı?›› diye sordu. ‹‹Evet›› diye yanıtladı Yeremya, ‹‹Babil Kralının eline verileceksin.››'),
(2003210,68,24,37,18,'Sonra Kral Sidkiyaya şöyle dedi: ‹‹Sana, görevlilerine ve bu halka karşı ne günah işledim ki beni cezaevine kapattınız?'),
(2003211,68,24,37,19,'‹Babil Kralı sana da bu ülkeye de saldırmayacak› diyen peygamberlerin hani nerede?'),
(2003212,68,24,37,20,'Şimdi lütfen beni dinle, ey efendim kral! Lütfen dileğimi kabul et. Beni Yazman Yonatanın evine geri gönderme. Orada ölmek istemiyorum.››'),
(2003213,68,24,37,21,'Bunun üzerine Kral Sidkiya Yeremya''nın muhafız avlusuna kapatılmasını, kentteki ekmek bitene dek her gün fırıncılar sokağından kendisine bir ekmek verilmesini buyurdu. Böylece Yeremya muhafız avlusunda kaldı.'),
(2003214,68,24,38,1,'Mattan oğlu Şefatya, Paşhur oğlu Gedalya, Şelemya oğlu Yehukal ve Malkiya oğlu Paşhur Yeremyanın halka söylediği şu sözleri duydular:'),
(2003215,68,24,38,2,'‹‹RAB diyor ki, ‹Bu kentte kalan kılıçtan, kıtlıktan, salgından ölecek. Kildanilere gidense sağ kalacak, canını kurtarıp yaşayacak.›'),
(2003216,68,24,38,3,'RAB diyor ki, ‹Bu kent kesinlikle Babil Kralının ordusuna teslim edilecek, Babil Kralı onu ele geçirecek.› ››'),
(2003217,68,24,38,4,'Önderler krala, ‹‹Bu adam öldürülmeli›› dediler, ‹‹Çünkü söylediği bu sözlerle kentte kalan askerlerin ve halkın cesaretini kırıyor. Bu adam halkın yararını değil, zararını istiyor.››'),
(2003218,68,24,38,5,'Kral Sidkiya, ‹‹İşte o sizin elinizde›› diye yanıtladı, ‹‹Kral size engel olamaz ki.››'),
(2003219,68,24,38,6,'Böylece Yeremyayı alıp kralın oğlu Malkiyanın muhafız avlusundaki sarnıcına halatlarla sarkıtarak indirdiler. Sarnıçta su yoktu, yalnız çamur vardı. Yeremya çamura battı.'),
(2003220,68,24,38,7,'Sarayda görevli hadım Kûşlu Ebet-Melek Yeremyanın sarnıca atıldığını duydu. Kral Benyamin Kapısında otururken,'),
(2003221,68,24,38,8,'Ebet-Melek saraydan çıkıp kralın yanına gitti ve ona şöyle dedi:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003222,68,24,38,9,'‹‹Efendim kral, bu adamların Peygamber Yeremyaya yaptıkları kötüdür. Onu sarnıca attılar, orada açlıktan ölecek. Çünkü kentte ekmek kalmadı.››'),
(2003223,68,24,38,10,'Bunun üzerine kral, ‹‹Buradan yanına üçfç adam al, Peygamber Yeremyayı ölmeden sarnıçtan çıkarın›› diye ona buyruk verdi.'),
(2003224,68,24,38,11,'Ebet-Melek yanına adamları alarak saray hazinesinin alt odasına gitti. Oradan eski bezler, yırtık pırtık giysiler alıp halatlarla sarnıca, Yeremyaya sarkıttı.'),
(2003225,68,24,38,12,'Sonra Yeremyaya, ‹‹Bu eski bezleri, yırtık giysileri halatlarla bağlayıp koltuklarının altına geçir›› diye seslendi. Yeremya söyleneni yaptı.'),
(2003226,68,24,38,13,'Onu halatlarla çekip sarnıçtan çıkardılar. Yeremya muhafız avlusunda kaldı.'),
(2003227,68,24,38,14,'Kral Sidkiya Peygamber Yeremyayı RABbin Tapınağının üçüncü girişine getirterek, ‹‹Sana bir şey soracağım›› dedi, ‹‹Benden bir şey gizleme.››'),
(2003228,68,24,38,15,'Yeremya, ‹‹Sana bir şey bildirirsem, beni öldürmeyecek misin?›› diye karşılık verdi, ‹‹Üstelik öğüt versem bile beni dinlemeyeceksin.››'),
(2003229,68,24,38,16,'Kral Sidkiya, ‹‹Bize yaşam veren RABbin varlığı hakkı için seni öldürmeyeceğim, canının peşinde olan bu adamların eline seni teslim etmeyeceğim›› diyerek gizlice ant içti.'),
(2003230,68,24,38,17,'Bunun üzerine Yeremya Sidkiyaya şu karşılığı verdi: ‹‹İsrailin Tanrısı, Her Şeye Egemen RAB Tanrı diyor ki, ‹Babil Kralının komutanlarına teslim olursan, canın bağışlanacak, bu kent de ateşe verilmeyecek. Sen de ailen de sağ kalacaksınız.'),
(2003231,68,24,38,18,'Ama Babil Kralının komutanlarına teslim olmazsan, kent Kildanilere teslim edilecek, onu ateşe verecekler. Sen de onlardan kaçıp kurtulamayacaksın.› ››'),
(2003232,68,24,38,19,'Kral Sidkiya, ‹‹Kildanilerin tarafına geçen Yahudilerden korkuyorum›› dedi, ‹‹Kildaniler beni onların eline verebilir, onlar da bana kötü davranırlar.››'),
(2003233,68,24,38,20,'‹‹Vermezler›› diye yanıtladı Yeremya, ‹‹Lütfen sana aktardığım RABbin sözünü işit. O zaman sağ kalır, iyilik görürsün.'),
(2003234,68,24,38,21,'Ama teslim olmak istemezsen, RAB bana şunu açıkladı:'),
(2003235,68,24,38,22,'Yahuda Kralının sarayında kalan bütün kadınlar Babil Kralının komutanlarına çıkarılacak. O kadınlar sana, ‹‹ ‹Güvendiğin insanlar 2 Seni aldatıp yenilgiye uğrattı; 2 Çamura battı ayakların, 2 Güvendiğin insanlar seni bırakıp gitti›'),
(2003236,68,24,38,23,'‹‹Bütün karıların, çocukların Kildanilere teslim edilecek. Sen de onlardan kaçıp kurtulamayacak, Babil Kralının eliyle yakalanacaksın. Bu kent ateşe verilecek.››'),
(2003237,68,24,38,24,'Sidkiya, ‹‹Ölmek istemiyorsan, konuştuklarımızı kimse duymasın›› dedi,'),
(2003238,68,24,38,25,'‹‹Görevliler seninle konuştuğumu duyup da gelir, ‹Krala ne söyledin, kral sana ne dedi, açıkla bize, bizden gizleme! Yoksa seni öldürürüz› derlerse,'),
(2003239,68,24,38,26,'‹Beni Yonatanın evine geri gönderme, yoksa orada ölürüm diye krala yalvardım› dersin.››'),
(2003240,68,24,38,27,'Bütün görevliler gelip Yeremyayı sorguya çektiler. Yeremya kralın kendisine söylemesini buyurduğu her şeyi onlara anlattı. Sorguyu bıraktılar. Çünkü kralla yaptığı konuşma duyulmamıştı.'),
(2003241,68,24,38,28,'Yeremya Yeruşalim''in ele geçirildiği güne dek muhafız avlusunda kaldı.'),
(2003242,68,24,39,1,'Yahuda Kralı Sidkiyanın dokuzuncu yılının onuncu ayında Babil Kralı Nebukadnessar bütün ordusuyla Yeruşalim önlerine gelerek kenti kuşattı.'),
(2003243,68,24,39,2,'Sidkiyanın krallığının on birinci yılında, dördüncü ayın dokuzuncu günü kent surlarında gedik açıldı.'),
(2003244,68,24,39,3,'Yeruşalim ele geçirilince Babil Kralının bütün komutanları -Samgarlı Nergal-Sareser, askeri danışman Nebo- Sarsekim, baş görevli Nergal-Sareser ve bütün öteki görevliler- içeri girip Orta Kapıda oturdular.'),
(2003245,68,24,39,4,'Yahuda Kralı Sidkiyayla askerler onları görünce kaçtılar. Gece kral bahçesinin yolundan iki duvarın arasındaki kapıdan kaçarak Arava yoluna çıktılar.'),
(2003246,68,24,39,5,'Ama artlarına düşen Kildani ordusu Eriha ovalarında Sidkiyaya yetişti, onu yakalayıp Hama topraklarında, Rivlada Babil Kralı Nebukadnessarın huzuruna çıkardılar. Nebukadnessar onun hakkında karar verdi:'),
(2003247,68,24,39,6,'Rivlada Sidkiyanın gözü önünde oğullarını, sonra da bütün Yahuda ileri gelenlerini öldürttü.'),
(2003248,68,24,39,7,'Sidkiyanın gözlerini oydu, zincire vurup Babile götürdü.'),
(2003249,68,24,39,8,'Kildaniler sarayla halkın evlerini ateşe verdiler, Yeruşalim surlarını yıktılar.'),
(2003250,68,24,39,9,'Komutan Nebuzaradan kentte sağ kalanları, kendi safına geçen kaçakları ve geri kalan halkı Babile sürgün etti.'),
(2003251,68,24,39,10,'Ancak hiçbir şeyi olmayan bazı yoksulları Yahudada bıraktı, onlara bağ ve tarla verdi.'),
(2003252,68,24,39,11,'Babil Kralı Nebukadnessar, muhafız birliği komutanı Nebuzaradan aracılığıyla Yeremyayla ilgili şu buyruğu verdi:'),
(2003253,68,24,39,12,'‹‹Onu sorumluluğun altına al, ona iyi bak, hiç zarar verme, senden ne dilerse yap.››'),
(2003254,68,24,39,13,'Bunun üzerine muhafız birliği komutanı Nebuzaradan, askeri danışman Nebuşazban, baş görevli Nergal-Sareser ve Babil Kralının öbür görevlileri'),
(2003255,68,24,39,14,'adam gönderip Yeremyayı muhafız avlusundan getirttiler. Evine geri götürmesi için Şafan oğlu Ahikam oğlu Gedalyanın koruyuculuğuna verdiler. Böylece Yeremya halkı arasında yaşamını sürdürdü.'),
(2003256,68,24,39,15,'Yeremya daha muhafız avlusunda tutukluyken RAB ona şöyle seslenmişti:'),
(2003257,68,24,39,16,'‹‹Git, Kûşlu Ebet-Meleke de ki, ‹İsrailin Tanrısı, Her Şeye Egemen RAB şöyle diyor: Bu kent üzerine yarar değil, zarar verecek sözlerimi yerine getirmek üzereyim. O gün olanları sen de göreceksin.'),
(2003258,68,24,39,17,'Ama o gün seni kurtaracağım diyor RAB. Korktuğun adamların eline teslim edilmeyeceksin.'),
(2003259,68,24,39,18,'Seni kesinlikle kurtaracağım, kılıçla öldürülmeyeceksin. Hiç değilse canını kurtarmış olacaksın. Çünkü bana güvendin, diyor RAB.› ››'),
(2003260,68,24,40,1,'Muhafız birliği komutanı Nebuzaradan Yeremyayı Ramada salıverdikten sonra RAB Yeremyaya seslendi. Nebuzaradan onu Babile sürülen Yeruşalim ve Yahuda halkıyla birlikte zincire vurulmuş olarak Ramaya götürmüştü.'),
(2003261,68,24,40,2,'Muhafız birliği komutanı Yeremyayı yanına çağırtıp, ‹‹Tanrın RAB buraya karşı bu felaketi belirledi›› dedi,'),
(2003262,68,24,40,3,'‹‹Şimdi dediğini yaptı, yapacağını söylediği her şeyi yerine getirdi. Çünkü RABbe karşı günah işlediniz, Onun sözünü dinlemediniz. Bütün bunlar bu yüzden başınıza geldi.'),
(2003263,68,24,40,4,'İşte ellerindeki zincirleri çözüyorum. Benimle Babile gelmeyi yeğlersen gel, sana iyi bakarım; eğer benimle Babile gelmek istemezsen de sorun yok. Bak, bütün ülke önünde! İyi ve doğru bildiğin yere git.'),
(2003264,68,24,40,5,'Ama burada kalırsan Babil Kralının Yahuda kentlerine vali atadığı Şafan oğlu Ahikam oğlu Gedalyanın yanına dönüp onunla birlikte halkın arasında yaşa ya da istediğin yere git.›› ve››. Muhafız birliği komutanı Yeremyaya yiyecek ve armağan verip yoluna gönderdi.'),
(2003265,68,24,40,6,'Yeremya Mispaya, Ahikam oğlu Gedalyanın yanına gitti. Onunla ve ülkede kalan halkla birlikte orada yaşamaya başladı.'),
(2003266,68,24,40,7,'Kırdaki ordu komutanlarıyla adamları, Babil Kralının Ahikam oğlu Gedalyayı ülkeye vali atadığını, Babile sürülmemiş yoksul kadın, erkek ve çocukları ona emanet ettiğini duyunca,'),
(2003267,68,24,40,8,'Mispaya, Gedalyanın yanına geldiler. Gelenler Netanya oğlu İsmail, Kareahın oğulları Yohanan ve Yonatan, Tanhumet oğlu Seraya, Netofalı Efayın oğulları, Maakalı oğlu Yaazanya ve adamlarıydı.'),
(2003268,68,24,40,9,'Şafan oğlu Ahikam oğlu Gedalya onlara ve adamlarına ant içerek, ‹‹Kildanilere kulluk etmekten korkmayın›› dedi, ‹‹Ülkeye yerleşip Babil Kralına hizmet edin. Böylesi sizin için daha iyi olur.'),
(2003269,68,24,40,10,'Bana gelince, Mispada kalacağım, gelecek Kildanilerin önünde sizi temsil edeceğim. Siz şarap, yaz meyveleri, zeytinyağı toplayıp kaplarınızda depolayın ve aldığınız kentlerde yaşayın.››'),
(2003270,68,24,40,11,'Moav, Ammon, Edom ve öbür ülkelerde yaşayan Yahudilerin hepsi, Babil Kralının Yahudada bir kesim halkı sağ bıraktığını ve Şafan oğlu Ahikam oğlu Gedalyayı onlara vali atadığını duyunca,'),
(2003271,68,24,40,12,'sürülmüş oldukları ülkelerden geri dönüp Yahudaya, Mispada bulunan Gedalyanın yanına geldiler. Sonra bol bol şarap ve yaz meyvesi topladılar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003272,68,24,40,13,'Kareah oğlu Yohananla kırdaki bütün ordu komutanları da Mispada bulunan Gedalyanın yanına geldiler.'),
(2003273,68,24,40,14,'Ona, ‹‹Ammon Kralı Baalisin seni öldürmek için Netanya oğlu İsmaili gönderdiğini bilmiyor musun?›› dediler. Gelgelelim Ahikam oğlu Gedalya onlara inanmadı.'),
(2003274,68,24,40,15,'Kareah oğlu Yohanan Mispada Gedalyaya gizlice, ‹‹İzin ver de gidip Netanya oğlu İsmaili öldüreyim›› dedi, ‹‹Kimse bilmeyecek! Neden seni öldürsün de çevrende toplanan bütün Yahudiler dağılsın, Yahudada sağ kalmış olanlar yok olsun?››'),
(2003275,68,24,40,16,'Ama Ahikam oğlu Gedalya, ‹‹Böyle birşey yapma! İsmail''le ilgili söylediklerin yalan›› dedi.'),
(2003276,68,24,41,1,'O yılın yedinci ayında kral soyundan ve kralın baş görevlilerinden Elişama oğlu Netanya oğlu İsmail, on adamıyla birlikte Mispaya, Ahikam oğlu Gedalyanın yanına gitti. Orada, Mispada birlikte yemek yerlerken,'),
(2003277,68,24,41,2,'Netanya oğlu İsmaille yanındaki on adam ayağa kalkıp Babil Kralının ülkeye vali atadığı Şafan oğlu Ahikam oğlu Gedalyayı kılıçla öldürdüler.'),
(2003278,68,24,41,3,'İsmail Mispada Gedalyayla birlikte olan bütün Yahudileri ve oradaki Kildan askerlerini de öldürdü.'),
(2003279,68,24,41,4,'Gedalya öldürüldükten bir gün sonra, ölüm haberi duyulmadan önce'),
(2003280,68,24,41,5,'Şekemden, Şilodan, Samiriyeden sakallarını tıraş etmiş, giysilerini yırtmış, bedenlerinde yaralar açmış seksen adam geldi. RABbin Tapınağında sunmak için yanlarında tahıl, günnük getirmişlerdi.'),
(2003281,68,24,41,6,'Netanya oğlu İsmail Mispadan ağlaya ağlaya onları karşılamaya çıktı. Onları görünce, ‹‹Ahikam oğlu Gedalyaya gelin›› dedi.'),
(2003282,68,24,41,7,'Kente girince, Netanya oğlu İsmail ve yanındakiler onları öldürüp bir sarnıca attılar.'),
(2003283,68,24,41,8,'Ancak onlardan on kişi İsmaile, ‹‹Bizi öldürme!›› dediler, ‹‹Tarlada saklı buğdayımız, arpamız, zeytinyağımız ve balımız var.›› Böylece İsmail vazgeçip onları öbürleriyle birlikte öldürmedi.'),
(2003284,68,24,41,9,'İsmailin öldürdüğü adamların bedenlerini atmış olduğu sarnıç büyüktü. Kral Asa, bu sarnıcı İsrail Kralı Baaşadan korunmak için kazmıştı. Netanya oğlu İsmail orayı ölülerle doldurdu. aracılığıyla››.'),
(2003285,68,24,41,10,'İsmail, muhafız birliği komutanı Nebuzaradanın Ahikam oğlu Gedalyanın sorumluluğuna bıraktığı Mispadaki bütün halkı ve kral kızlarını tutsak aldı. Netanya oğlu İsmail tümünü tutsak alıp Ammonlulara sığınmak üzere yola çıktı.'),
(2003286,68,24,41,11,'Kareah oğlu Yohanan ve yanındaki ordu komutanları, Netanya oğlu İsmailin işlediği cinayetleri duyunca,'),
(2003287,68,24,41,12,'bütün adamlarını alıp Netanya oğlu İsmaille savaşmaya gittiler. Givondaki büyük havuzun yakınında ona yetiştiler.'),
(2003288,68,24,41,13,'İsmailin yanındaki adamlar, Kareah oğlu Yohanan ve yanındaki ordu komutanlarını görünce sevindiler.'),
(2003289,68,24,41,14,'İsmailin Mispadan tutsak olarak götürdüğü herkes geri dönüp Kareah oğlu Yohanana katıldı.'),
(2003290,68,24,41,15,'Netanya oğlu İsmail ve sekiz adamıysa Yohanandan kaçıp Ammonlulara sığındılar.'),
(2003291,68,24,41,16,'Kareah oğlu Yohananla yanındaki ordu komutanları sağ kalanların hepsini -Ahikam oğlu Gedalyayı öldüren Netanya oğlu İsmailden kurtarıp Givondan geri getirdiği yiğit askerleri, kadınları, çocukları, saray görevlilerini- Mispadan alıp götürdüler.'),
(2003292,68,24,41,17,'Kildaniler''den kaçmak için Mısır''a doğru yola çıktılar. Beytlehem yakınında, Gerut-Kimham''da durdular. Kildaniler''den korkuyorlardı. Çünkü Netanya oğlu İsmail, Babil Kralı''nın ülkeye vali atadığı Ahikam oğlu Gedalya''yı öldürmüştü.'),
(2003293,68,24,42,1,'Ordu komutanları, Kareah oğlu Yohanan, Hoşaya oğlu Azarya ve küçük büyük bütün halk yaklaşıp'),
(2003294,68,24,42,2,'Peygamber Yeremyaya şöyle dediler: ‹‹Lütfen dileğimizi kabul et! Bizim için, bütün sağ kalan bu halk için Tanrın RABbe yakar. Çünkü bir zamanlar sayıca çok olan bizler gördüğün gibi şimdi azınlıkta kaldık.'),
(2003295,68,24,42,3,'Tanrın RAB nereye gideceğimizi, ne yapacağımızı bize bildirsin.›› 43:2).'),
(2003296,68,24,42,4,'Peygamber Yeremya, ‹‹Olur›› dedi, ‹‹İsteğiniz uyarınca Tanrınız RABbe yakaracağım. RAB bana ne yanıt verirse, bir şey saklamadan size bildireceğim.››'),
(2003297,68,24,42,5,'Bunun üzerine, ‹‹Tanrın RABbin senin aracılığınla bize bildireceği her sözü yerine getirmezsek, RAB aramızda gerçek ve güvenilir tanık olsun›› dediler,'),
(2003298,68,24,42,6,'‹‹Seni kendisine gönderdiğimiz Tanrımız RABbin sözünü beğensek de beğenmesek de dinleyeceğiz ki, üzerimize iyilik gelsin. Evet, Tanrımız RABbin sözünü dinleyeceğiz.››'),
(2003299,68,24,42,7,'On gün sonra RAB Yeremyaya seslendi.'),
(2003300,68,24,42,8,'Yeremya, Kareah oğlu Yohananla yanındaki ordu komutanlarını ve küçük büyük bütün halkı çağırdı.'),
(2003301,68,24,42,9,'Onlara şöyle dedi: ‹‹Dileğinizi önüne sunmam için beni kendisine gönderdiğiniz İsrailin Tanrısı RAB diyor ki,'),
(2003302,68,24,42,10,'‹Bu ülkede kalırsanız, sizi bina ederim, yıkmam; dikerim, sökmem. Çünkü başınıza getirdiğim felakete üzülüyorum.'),
(2003303,68,24,42,11,'Korktuğunuz Babil Kralından artık korkmayın, ondan korkmayın diyor RAB. Çünkü ben sizinleyim, sizi kurtaracak, onun elinden özgür kılacağım.'),
(2003304,68,24,42,12,'Size sevecenlik göstereceğim. Şöyle ki, Babil Kralı size acıyacak, sizi topraklarınıza geri gönderecek.›'),
(2003305,68,24,42,13,'‹‹Ama, ‹Bu ülkede kalmayacağız› der, Tanrınız RABbin sözünü dinlemezseniz,'),
(2003306,68,24,42,14,'‹Savaş görmeyeceğimiz, boru sesi duymayacağımız, açlık çekmeyeceğimiz Mısıra gidip orada yaşayacağız› derseniz,'),
(2003307,68,24,42,15,'RABbin sözünü dinleyin, ey Yahudadan sağ kalanlar! İsrailin Tanrısı, Her Şeye Egemen RAB şöyle diyor: ‹Eğer Mısıra gidip orada yerleşmeye kesin kararlıysanız,'),
(2003308,68,24,42,16,'korktuğunuz kılıç size orada yetişecek, tasalandığınız kıtlık Mısırda yakanıza yapışacak, orada öleceksiniz.'),
(2003309,68,24,42,17,'Yerleşmek üzere Mısıra gitmeye kararlı olan herkes kılıçtan, kıtlıktan, salgın hastalıktan ölecek. Başlarına getireceğim felaketten kurtulup sağ kalan olmayacak.›'),
(2003310,68,24,42,18,'‹‹İsrailin Tanrısı, Her Şeye Egemen RAB diyor ki, ‹Öfkem, kızgınlığım Yeruşalimde yaşayanların üzerine döküldüğü gibi, siz Mısıra gidenlerin üzerine de dökülecek. Siz lanetlik, dehşet konusu olacak, aşağılanacak, yerileceksiniz. Burayı bir daha görmeyeceksiniz.›'),
(2003311,68,24,42,19,'Ey Yahudadan sağ kalanlar, RAB size, ‹Mısıra gitmeyin!› diye buyurmuştur. Bunu iyi bilin. Bugün sizi uyarıyorum:'),
(2003312,68,24,42,20,'Beni Tanrınız RABbe gönderip, ‹Bizim için Tanrımız RABbe yakar. Onun bize söyleyeceği her şeyi bildir, yapacağız› demekle kendinizi aldatıyorsunuz!'),
(2003313,68,24,42,21,'Bugün size bildirdim, ama Tanrınız RABbin benim aracılığımla size ilettiği sözlerin hiçbirini dinlemediniz.'),
(2003314,68,24,42,22,'Şimdi iyi bilin ki, yerleşmek üzere gitmeye can attığınız yerde kılıçtan, kıtlıktan, salgın hastalıktan öleceksiniz.››'),
(2003315,68,24,43,1,'Yeremya Tanrıları RABbin bütün bu sözlerini -Tanrıları RABbin onun aracılığıyla kendilerine ilettiği her şeyi- halka bildirmeyi bitirince'),
(2003316,68,24,43,2,'Hoşaya oğlu Azarya, Kareah oğlu Yohanan ve bütün küstah adamlar ona, ‹‹Yalan söylüyorsun!›› dediler, ‹‹Tanrımız RAB, ‹Yerleşmek üzere Mısıra gitmeyin› demek için göndermedi seni bize.'),
(2003317,68,24,43,3,'Bizi öldürsünler, Babile sürsünler diye Kildanilerin eline teslim etmek için Neriya oğlu Baruk seni bize karşı kışkırtıyor.››'),
(2003318,68,24,43,4,'Böylece Kareah oğlu Yohanan, bütün ordu komutanları ve halk RABbin Yahudada kalmalarına ilişkin buyruğuna karşı geldiler.'),
(2003319,68,24,43,5,'Kareah oğlu Yohananla bütün ordu komutanları, sürüldükleri uluslardan yerleşmek üzere Yahudaya geri dönen Yahuda halkını alıp götürdüler.'),
(2003320,68,24,43,6,'Muhafız birliği komutanı Nebuzaradanın Şafan oğlu Ahikam oğlu Gedalyanın sorumluluğuna bırakmış olduğu bütün kadınları, erkekleri, çocukları, kral kızlarını da götürdüler. Peygamber Yeremyayla Neriya oğlu Baruku da alıp'),
(2003321,68,24,43,7,'RABbin sözünü dinlemeyerek Mısıra gittiler. Tahpanhese vardılar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003322,68,24,43,8,'Tahpanheste RAB Yeremyaya şöyle seslendi:'),
(2003323,68,24,43,9,'‹‹Yahudilerin gözü önünde eline büyük taşlar al, Tahpanheste firavun sarayının girişindeki tuğla kaldırımın harcına göm.'),
(2003324,68,24,43,10,'Onlara de ki, ‹İsrailin Tanrısı, Her Şeye Egemen RAB şöyle diyor: İşte kulum Babil Kralı Nebukadnessarı buraya getirtip tahtını harca gömdüğüm bu taşların üzerine kuracağım. Nebukadnessar otağını bu taşların üzerine kuracak.'),
(2003325,68,24,43,11,'Gelip Mısırı bozguna uğratacak. Ölüm için ayrılanlar ölüme, Sürgün için ayrılanlar sürgüne, Kılıç için ayrılanlar kılıca gidecek.'),
(2003326,68,24,43,12,'Mısır ilahlarının tapınaklarını ateşe verip yakacak, ilahları alıp götürecek. Çoban giysisiyle kendisini nasıl örterse, o da Mısırı öyle örtecek. Sonra oradan sağ salim çıkacak.'),
(2003327,68,24,43,13,'Mısır''daki Güneş Tapınağı''nın dikili taşlarını kıracak, Mısır ilahlarının tapınaklarını ateşe verecek.› ›› metin ‹‹Yakacağım››.'),
(2003328,68,24,44,1,'Mısırın Migdol, Tahpanhes, Noffı kentlerinde ve Patros bölgesinde yaşayan Yahudilere ilişkin RAB Yeremyaya şöyle seslendi:'),
(2003329,68,24,44,2,'‹‹İsrailin Tanrısı, Her Şeye Egemen RAB diyor ki, Yeruşalim ve Yahuda kentlerine getirdiğim bütün felaketleri gördünüz. İşte yaptıkları kötülük yüzünden kentler bugün yıkık; içlerinde oturan yok. Sizin de kendilerinin ve atalarının da önceden tanımadığınız başka ilahlara buhur yakıp taparak beni öfkelendirdiler.'),
(2003330,68,24,44,4,'Peygamber kullarımı defalarca gönderip, ‹Nefret ettiğim bu iğrençlikleri yapmayın!› diyerek onları uyardım.'),
(2003331,68,24,44,5,'Ama dinlemediler, kulak asmadılar. Kötülüklerinden dönmediler, başka ilahlara buhur yakmaktan vazgeçmediler.'),
(2003332,68,24,44,6,'Bu yüzden kızgın öfkemi döktüm; Yahuda kentlerine, Yeruşalim sokaklarına karşı öfkem giderek şiddetlendi. Onlar bugün olduğu gibi yıkık ve ıssız bırakıldı.'),
(2003333,68,24,44,7,'‹‹İsrailin Tanrısı RAB, Her Şeye Egemen Tanrı şöyle diyor: Neden bu büyük felaketi başınıza getiriyorsunuz? Kadın erkek, çoluk çocuk Yahuda halkından kesilip atılacak, sizden sağ kalan olmayacak.'),
(2003334,68,24,44,8,'Yerleşmek üzere geldiğiniz Mısırda ellerinizin yaptıklarıyla, başka ilahlara buhur yakmakla beni öfkelendiriyorsunuz. Başınıza felaket getiriyorsunuz. Dünyadaki uluslarca aşağılanacak, yerileceksiniz.'),
(2003335,68,24,44,9,'Yahudada, Yeruşalim sokaklarında atalarınızın, Yahuda krallarıyla karılarının, kendinizin, karılarınızın yaptığınız kötülükleri unuttunuz mu?'),
(2003336,68,24,44,10,'Bugüne dek pişmanlık duymadılar, benden korkmadılar. Size ve atalarınıza verdiğim yasa ve kurallar uyarınca yaşamadılar.'),
(2003337,68,24,44,11,'‹‹Bu yüzden İsrailin Tanrısı, Her Şeye Egemen RAB diyor ki: Başınıza yıkım getirmeye, bütün Yahuda halkını yok etmeye kararlıyım.'),
(2003338,68,24,44,12,'Yerleşmek üzere Mısıra gelmeye kararlı olan Yahudanın sağ kalanlarını ele alacağım. Hepsi Mısırda yok olacak; kılıçtan geçirilecek ya da kıtlıktan ölecek. Küçük büyük hepsi kılıçtan, kıtlıktan ölecek. Lanetlenecek, dehşet konusu olacak, aşağılanacak, yerilecekler.'),
(2003339,68,24,44,13,'Yeruşalimi cezalandırdığım gibi, Mısırda yaşayanları da kılıçla, kıtlıkla, salgın hastalıkla cezalandıracağım.'),
(2003340,68,24,44,14,'Yerleşmek için Mısıra gelen Yahuda halkının sağ kalanlarından hiçbiri kurtulmayacak, hiç kimse sağ kalıp Yahudaya dönmeyecek. Yerleşmek üzere oraya dönmek isteseler de, kaçıp kurtulan birkaç kişi dışında dönen olmayacak.››'),
(2003341,68,24,44,15,'Karılarının başka ilahlara buhur yaktığını bilen erkekler, orada duran kadınlar, Mısırın Patros bölgesinde yaşayan bütün halk -ki büyük bir topluluktu- Yeremyaya şu karşılığı verdi:'),
(2003342,68,24,44,16,'‹‹RABbin adıyla bize söylediklerini dinlemeyeceğiz!'),
(2003343,68,24,44,17,'Tersine, yapacağımızı söylediğimiz her şeyi kesinlikle yapacağız: Gök Kraliçesine buhur yakacak, atalarımızın, krallarımızın, önderlerimizin ve kendimizin Yahuda kentlerinde, Yeruşalim sokaklarında yaptığımız gibi ona dökmelik sunular dökeceğiz. O zamanlar bol yiyeceğimiz vardı, her işimiz yolundaydı, sıkıntı çekmiyorduk.'),
(2003344,68,24,44,18,'Oysa Gök Kraliçesine buhur yakmayı, dökmelik sunular dökmeyi bıraktığımız günden bu yana her yönden yokluk çekiyoruz; kılıçtan, kıtlıktan yok oluyoruz.››'),
(2003345,68,24,44,19,'Kadınlar, ‹‹Evet, Gök Kraliçesine buhur yakıp dökmelik sunular dökeceğiz! Ona benzer pideler pişirip kendisine dökmelik sunular döktüğümüzü kocalarımız bilmiyor muydu sanki?›› diye eklediler.'),
(2003346,68,24,44,20,'Bunun üzerine Yeremya ona karşılık veren kadın erkek bütün halka şöyle dedi:'),
(2003347,68,24,44,21,'‹‹Sizin, atalarınızın, krallarınızın, önderlerinizin, ülke halkının Yahuda kentlerinde, Yeruşalim sokaklarında yaktığınız buhuru RAB unuttu mu? Haberi yok muydu?'),
(2003348,68,24,44,22,'RAB yaptığınız kötülüklere, iğrençliklere artık dayanamadığı için, bugün olduğu gibi ülkeniz aşağılanıp yerildi, kimsenin yaşamadığı dehşet verici bir viranelik oldu.'),
(2003349,68,24,44,23,'Siz başka ilahlara buhur yaktınız, RABbe karşı günah işlediniz; Onun sözünü dinlemediniz, yasasına, kurallarına, antlaşma koşullarına uymadınız. Bu yüzden bugün olduğu gibi başınıza felaket geldi.››'),
(2003350,68,24,44,24,'Yeremya bütün halka, özellikle de kadınlara, ‹‹RABbin sözüne kulak verin, ey Mısırda yaşayan Yahudalılar›› dedi,'),
(2003351,68,24,44,25,'‹‹İsrailin Tanrısı, Her Şeye Egemen RAB diyor ki, ‹Gök Kraliçesine buhur yakacağız, dökmelik sunular dökeceğiz, adaklarımızı kesinlikle yerine getireceğiz› diyerek siz de karılarınız da verdiğiniz sözü yerine getirdiniz. ‹‹Öyleyse verdiğiniz sözü tutun! Adadığınız adakları tümüyle yerine getirin!'),
(2003352,68,24,44,26,'Mısırda yaşayan Yahudiler, RABbin sözünü dinleyin! ‹Büyük adım üzerine ant içiyorum ki› diyor RAB, ‹Mısırda yaşayan Yahudilerden hiçbiri bundan böyle adımı ağzına alıp Egemen RABbin varlığı hakkı için diye ant içmeyecek.'),
(2003353,68,24,44,27,'Çünkü onların yararını değil, zararını gözlüyorum; Mısırda yaşayan Yahudiler yok olana dek kılıçtan, kıtlıktan ölecek.'),
(2003354,68,24,44,28,'Kılıçtan kurtulup da Mısırdan Yahudaya dönenlerin sayısı pek az olacak. Mısıra yerleşmeye gelen Yahuda halkından sağ kalanlar o zaman kimin sözünün yerine geldiğini anlayacak: Benim sözümün mü, yoksa onlarınkinin mi?'),
(2003355,68,24,44,29,'‹‹ ‹Başınıza yıkım getireceğim; sözümün yerine geleceğini bilesiniz diye› diyor RAB, ‹Sizi burada cezalandıracağıma ilişkin belirti şu olacak.›'),
(2003356,68,24,44,30,'RAB diyor ki, ‹Yahuda Kralı Sidkiya''yı can düşmanı Babil Kralı Nebukadnessar''ın eline nasıl teslim ettimse, Mısır Firavunu Hofra''yı da can düşmanlarının eline öyle teslim edeceğim.› ››'),
(2003357,68,24,45,1,'Yahuda Kralı Yoşiya oğlu Yehoyakimin dördüncü yılında Neriya oğlu Baruk, Peygamber Yeremyanın kendisine söylediği sözleri tomara yazdıktan sonra Yeremya ona şunları söyledi:'),
(2003358,68,24,45,2,'‹‹Ey Baruk, İsrailin Tanrısı RAB sana şöyle diyor:'),
(2003359,68,24,45,3,'Sen, ‹Vay başıma! Çünkü RAB acıma acı kattı. İnlemekten bitkin düştüm, bana rahat yok› dedin.'),
(2003360,68,24,45,4,'‹‹RAB bana, ‹Ona şöyle diyeceksin› dedi: ‹RAB diyor ki, bütün ülkeyi yıkacağım; bina ettiğimi yıkacak, diktiğimi sökeceğim.'),
(2003361,68,24,45,5,'Sana gelince, büyük şeyler peşinde mi koşuyorsun? Sakın koşma! Çünkü bütün halkın üzerine felaket getirmek üzereyim› diyor RAB, ‹Ama sen nereye gidersen git, canını bağışlayacağım.› ››'),
(2003362,68,24,46,1,'RAB uluslara ilişkin Peygamber Yeremyaya şöyle seslendi:'),
(2003363,68,24,46,2,'Mısıra ilişkin: Yahuda Kralı Yoşiya oğlu Yehoyakimin dördüncü yılında, Babil Kralı Nebukadnessarın Fırat kıyısında, Karkamışta yenilgiye uğrattığı Firavun Nekonun ordusuyla ilgili bildiri:'),
(2003364,68,24,46,3,'‹‹Küçük büyük kalkanları dizin, 2 Savaşmak için ilerleyin!'),
(2003365,68,24,46,4,'Atları koşun, beygirlere binin! 2 Miğferlerinizi takın, yerinizi alın! 2 Mızraklarınızı cilalayın, 2 Zırhlarınızı kuşanın!'),
(2003366,68,24,46,5,'Ne görüyorum? 2 Dehşete düştüler, geri çekiliyorlar! 2 Yiğitleri bozguna uğramış, 2 Arkalarına bakmadan kaçışıyorlar. 2 Her yer dehşet içinde›› diyor RAB.'),
(2003367,68,24,46,6,'‹‹Ayağı tez olan kaçamıyor, 2 Yiğit kaçıp kurtulamıyor. 2 Kuzeyde, Fırat kıyısında 2 Tökezleyip düştüler.'),
(2003368,68,24,46,7,'Nil gibi yükselen, 2 Irmak gibi suları çalkalanan kim?'),
(2003369,68,24,46,8,'Mısırdır Nil gibi yükselen, 2 Irmak gibi suları çalkalanan. 2 ‹Yükselip yeryüzünü kaplayacağım; 2 Kentleri de içlerinde oturanları da 2 Yok edeceğim› diyor Mısır.'),
(2003370,68,24,46,9,'Şahlanın, ey atlar! 2 Çılgınca saldırın, ey savaş arabaları! 2 Ey kalkan taşıyan Kûşlu, Pûtlu yiğitler, 2 Yay çeken Ludlular, ilerleyin!'),
(2003371,68,24,46,10,'‹‹Çünkü o gün Her Şeye Egemen Egemen RABbin günüdür. 2 Düşmanlarından öç alması için 2 Öç günüdür. 2 Kılıç doyana dek yiyecek, 2 Kanlarını kana kana içecek. 2 Çünkü Rab, Her Şeye Egemen RAB 2 Kuzeyde, Fırat kıyısında kurban hazırlıyor.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003372,68,24,46,11,'‹‹Ey erden kız Mısır, 2 Gilata git de merhem al! 2 Ama boşuna çok ilaç kullanıyorsun, 2 Senin için şifa yok.'),
(2003373,68,24,46,12,'Uluslar utancını duydu, 2 Feryadınla doldu yeryüzü. 2 Yiğit yiğide tökezleyip 2 İkisi birlikte yere seriliyor.››'),
(2003374,68,24,46,13,'Babil Kralı Nebukadnessarın gelip Mısıra saldıracağına ilişkin RABbin Peygamber Yeremyaya bildirdiği söz şudur:'),
(2003375,68,24,46,14,'‹‹Mısırda bildirin, 2 Migdolda duyurun, 2 Nofta, Tahpanheste duyurun: 2 ‹Yerini al, hazırlan, 2 Çünkü çevrendekileri yiyip bitiriyor kılıç!›'),
(2003376,68,24,46,15,'İlahın Apis neden kaçtı? 2 Boğan neden ayakta kalamadı? 2 Çünkü RAB onu yere serdi! ayakta kalamadı? Çünkü RAB onu yere serdi!›› (bkz. Septuaginta), Masoretik metin ‹‹Yiğitlerin neden yere serildi? Ayakta duracak halleri yok, çünkü RAB onları yere serdi!››'),
(2003377,68,24,46,16,'Boyuna tökezleyip birbirlerinin üzerine düşecekler. 2 ‹Kalkın, acımasızların kılıcı yüzünden halkımıza, 2 Yurdumuza dönelim› diyecekler.'),
(2003378,68,24,46,17,'‹Firavun yaygaracının biri, 2 Fırsatı kaçırdı› diyecekler.'),
(2003379,68,24,46,18,'‹‹Varlığım hakkı için›› diyor Kral, 2 Adı Her Şeye Egemen RAB, 2 ‹‹Dağlar arasında Tavor Dağı nasılsa, 2 Karmel Dağı deniz kıyısında nasılsa, 2 Size saldıracak kişi de öyledir.'),
(2003380,68,24,46,19,'Ey sizler, Mısırda yaşayanlar, 2 Toplayın eşyanızı, sürgüne gideceksiniz! 2 Nof öyle viran olup yanacak ki, 2 Kimse oturmayacak içinde.'),
(2003381,68,24,46,20,'‹‹Mısır güzel bir düve, 2 Ama kuzeyden atsineği geliyor ona.'),
(2003382,68,24,46,21,'Ücretli askerleri besili danalar gibi. 2 Onlar da geri dönüp birlikte kaçacak, 2 Yerlerinde durmayacaklar. 2 Çünkü üzerlerine yıkım günü, 2 Cezalandırılacakları an gelecek.'),
(2003383,68,24,46,22,'Düşman ordusu ilerleyince, 2 Mısır yılan gibi tıslayarak kaçacak. 2 Ağaç kesen adamlar gibi 2 Baltalarla ona saldıracaklar.'),
(2003384,68,24,46,23,'Gür olsa bile kesecekler ormanını›› diyor RAB, 2 ‹‹Çünkü çekirgelerden daha çok onlar, 2 Sayıya vurulamazlar.'),
(2003385,68,24,46,24,'Mısır utandırılacak, 2 Kuzey halkının eline teslim edilecek.››'),
(2003386,68,24,46,25,'İsrailin Tanrısı, Her Şeye Egemen RAB diyor ki, ‹‹İşte No Kentinin ilahı Amonu, firavunu, Mısırla ilahlarını, krallarını ve firavuna güvenenleri cezalandırmak üzereyim.'),
(2003387,68,24,46,26,'Hepsini can düşmanları Babil Kralı Nebukadnessarla görevlilerinin eline teslim edeceğim. Ama sonra, eskiden olduğu gibi insanlar yine Mısırda yaşayacak›› diyor RAB.'),
(2003388,68,24,46,27,'‹‹Korkma, ey kulum Yakup, 2 Yılma, ey İsrail. 2 Çünkü seni uzak yerlerden, 2 Soyunu sürgün edildiği ülkeden kurtaracağım. 2 Yakup yine huzur ve güvenlik içinde olacak, 2 Kimse onu korkutmayacak.'),
(2003389,68,24,46,28,'Korkma, ey kulum Yakup, 2 Çünkü ben seninleyim›› diyor RAB. 2 ‹‹Seni aralarına sürdüğüm ulusların hepsini 2 Tümüyle yok etsem de, 2 Seni büsbütün yok etmeyeceğim. 2 Adaletle yola getirecek, 2 Hiç cezasız bırakmayacağım seni.››'),
(2003390,68,24,47,1,'Firavun Gazzeye saldırmadan önce RABbin Peygamber Yeremyaya bildirdiği Filistlilere ilişkin söz şudur:'),
(2003391,68,24,47,2,'RAB diyor ki, 2 ‹‹Bakın sular kuzeyden nasıl yükseliyor! 2 Taşkın bir ırmak olacak, 2 Ülkeyi ve içindeki her şeyi, 2 Kentleri ve içinde yaşayanları kaplayacak. 2 İnsanlar yakaracak, 2 Ülkede yaşayan herkes feryat edecek.'),
(2003392,68,24,47,3,'Dörtnala koşan aygırların 2 Toynak seslerinden, 2 Savaş arabalarının takırtısından, 2 Tekerleklerin gürültüsünden 2 Babalar dönüp çocuklarına bakmayacak; 2 Ellerinde derman kalmayacak.'),
(2003393,68,24,47,4,'Çünkü Filistlilerin yok edileceği gün geliyor. 2 Sur ve Saydaya yardım edebilecek 2 Sağ kalan herkes kesilip yok edilecek. 2 RAB Kaftor kıyısından gelen Filistlilerin 2 Sağ kalanlarını yok edecek.'),
(2003394,68,24,47,5,'Gazze yastan saçını yolacak, 2 Aşkelon susturulacak. 2 Ey ovada sağ kalanlar, 2 Ne zamana dek bedenlerinizi yaralayacaksınız?'),
(2003395,68,24,47,6,'Ah, RABbin kılıcı! 2 Yatışmana daha ne kadar zaman var? 2 Dön kınına! Dur ve sessiz ol!'),
(2003396,68,24,47,7,'Ama RAB ona buyruk vermişken, 2 Aşkelon''a, deniz kıyısına 2 Saldırmak üzere görevlendirmişken 2 Kılıç nasıl yatışabilir?››'),
(2003397,68,24,48,1,'Moava ilişkin: İsrailin Tanrısı, Her Şeye Egemen RAB şöyle diyor: ‹‹Vay Nevonun başına gelenlere! 2 Çünkü viraneye çevrilecek. 2 Kiryatayim utandırılacak, ele geçirilecek. 2 Misgav utandırılacak, kırılıp dökülecek.'),
(2003398,68,24,48,2,'Moav artık övülmeyecek, 2 Heşbonda onun yıkımı için düzen kuracak, 2 ‹Haydi, şu Moav ulusuna son verelim› diyecekler. 2 Ey Madmenfö, sen de susturulacaksın, 2 Kılıç kovalayacak seni. çağrıştırıyor.'),
(2003399,68,24,48,3,'Horonayimden feryat duyulacak: 2 ‹Kent mahvoldu, büyük yıkıma uğradı!›'),
(2003400,68,24,48,4,'‹‹Moav yıkılacak, 2 Yavrularının ağlayışı duyulacak.'),
(2003401,68,24,48,5,'Ağlaya ağlaya çıkıyorlar Luhit Yokuşundan, 2 Horonayim inişinde 2 Yıkımın neden olduğu acı feryatlar duyuluyor.'),
(2003402,68,24,48,6,'Kaçın, canınızı kurtarın! 2 Çölde yaban eşeğifö gibi koşun! ağacı››.'),
(2003403,68,24,48,7,'‹‹Evet, başarılarına, mal varlığına güvendiğin için 2 Sen de ele geçirileceksin. 2 İlahın Kemoş da kâhinleri ve görevlileriyle birlikte 2 Sürgün edilecek.'),
(2003404,68,24,48,8,'Yok edici her kente uğrayacak, 2 Tek kent kurtulmayacak. 2 Vadi yerle bir olacak, 2 Yayla altüst edilecek›› diyor RAB.'),
(2003405,68,24,48,9,'‹‹Moav toprağına tuz dökün, kısırlaşsın, 2 Kentleri öyle viran olacak ki, 2 Kimse yaşamayacak oralarda.'),
(2003406,68,24,48,10,'Lanet olsun RABbin işini savsaklayana! 2 Kılıcını kan dökmekten alıkoyana lanet olsun!'),
(2003407,68,24,48,11,'Moav gençliğinden bu yana güvenlikteydi, 2 Şarap tortusu gibi durgun kaldı, 2 Bir kaptan öbürüne boşaltılmadı, 2 Sürgüne gönderilmedi. 2 O yüzden tadını yitirmedi, kokusu bozulmadı.'),
(2003408,68,24,48,12,'‹‹Ama onu boşaltacak adamları göndereceğim günler geliyor›› diyor RAB, ‹‹Onu boşaltacaklar. Kaplarını boşaltacak, küplerini paramparça edecekler.'),
(2003409,68,24,48,13,'İsrail halkı güvendiği Beytelden nasıl utandıysa, Moav da Kemoş ilahından öyle utanacak.'),
(2003410,68,24,48,14,'‹‹Nasıl, ‹Biz yiğidiz, 2 Savaşa hazır askerleriz› dersiniz?'),
(2003411,68,24,48,15,'Moav ve kentlerini yerle bir eden, 2 Saldırıya geçti. 2 En seçkin gençleri kesime gidecek. 2 Adı Her Şeye Egemen RAB olan Kral böyle diyor.'),
(2003412,68,24,48,16,'Moavın yıkımı yakında geliyor, 2 Uğrayacağı felaket hızla yaklaşıyor.'),
(2003413,68,24,48,17,'Dövünün onun için, 2 Ey çevresinde yaşayan, ününü bilen sizler! 2 ‹Kudret asası, 2 Görkemli değnek nasıl da kırıldı!› deyin.'),
(2003414,68,24,48,18,'‹‹Ey Divon Kentinde yaşayan halk, 2 Görkeminden in, 2 Kuru toprak üstünde otur. 2 Çünkü Moavı yerle bir eden sana da saldıracak, 2 Kalelerini yıkacak.'),
(2003415,68,24,48,19,'Ey sen, Aroerde oturan, 2 Yol kenarında dur da gözle! 2 Kaçan adama, kurtulan kadına, 2 ‹Ne oldu?› diye sor.'),
(2003416,68,24,48,20,'Moav utandırıldı, darmadağın oldu. 2 Feryat et, haykır! 2 Moavın yıkıldığını Arnon Vadisinde duyur.'),
(2003417,68,24,48,21,'‹‹Yayladaki kentler -Holan, Yahas, Mefaat, Divon, Nevo, Beytdivlatayim, Kiryatayim, Beytgamul, Beytmeon, Keriyot, Bosra, uzak yakın bütün Moav kentleri- yargılanacak.'),
(2003418,68,24,48,25,'Moavın boynuzu kesildi, kolu kırıldı›› diyor RAB.'),
(2003419,68,24,48,26,'‹‹Moavı sarhoş edin, 2 Çünkü RABbe büyüklük tasladı. 2 Moav kendi kusmuğunda yuvarlanacak, 2 Alay konusu olacak.'),
(2003420,68,24,48,27,'İsrail senin için gülünesi bir ulus mu oldu? 2 Hırsızlar arasında mı yakalandı ki, 2 Ondan söz ettikçe baş sallıyorsun?'),
(2003421,68,24,48,28,'‹‹Ey Moavda yaşayanlar, 2 Kentlerinizi terk edip kayalara sığının. 2 Uçurumun ağzında yuvasını yapan 2 Güvercin gibi olun.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003422,68,24,48,29,'Moavın ne denli gururlanıp büyüklendiğini, 2 Kendini ne denli beğendiğini, 2 Kibirlenip küstahlaştığını, 2 Övünüp kabardığını duyduk.'),
(2003423,68,24,48,30,'Küstahlığını biliyorum›› diyor RAB, 2 ‹‹Övünmesi boşunadır, yaptıkları da.'),
(2003424,68,24,48,31,'Bu yüzden Moav için haykıracak, 2 Bütün Moav için feryat edeceğim. 2 Ağlayacağım Kîr-Hereset halkı için.'),
(2003425,68,24,48,32,'Ey Sivma asması, 2 Senin için Yazer halkından çok ağlayacağım. 2 Filizlerin gölü aşıp 2 Yazere ulaştı. 2 Yok edici yaz meyvelerini, üzümünü yok etti.'),
(2003426,68,24,48,33,'Moavın meyve bahçelerinden, tarlalarından 2 Sevinç ve neşe yok oldu. 2 Üzüm sıkma çukurlarından şarap akışını durdurdum; 2 Kimse sevinç çığlıklarıyla üzüm ezmiyor, 2 Çığlıklar var, ama sevinç çığlıkları değil.'),
(2003427,68,24,48,34,'‹‹Heşbon ve Elalenin haykırışları 2 Yahasa ulaşıyor. 2 Soardan Horonayime, 2 Eglat-Şelişiyaya dek çığlıklar yükseliyor. 2 Çünkü Nimrim suları bile kurudu.'),
(2003428,68,24,48,35,'Moavda puta tapılan yerlerde 2 Sunu sunanları, 2 İlahlarına buhur yakanları 2 Yok edeceğim›› diyor RAB.'),
(2003429,68,24,48,36,'‹‹Bu yüzden yüreğim ney gibi 2 İnliyor Moav için; 2 Kîr-Hereset halkı için ney gibi 2 İnliyor yüreğim. 2 Çünkü elde ettikleri zenginlik uçup gitti.'),
(2003430,68,24,48,37,'‹‹Herkes saçını sakalını kesecek, 2 Elini yaralayacak, 2 Beline çul saracak.'),
(2003431,68,24,48,38,'Moav damlarında, meydanlarında 2 Yalnız ağlayış var. 2 Çünkü Moavı kimsenin beğenmediği 2 Bir kap gibi kırdım›› diyor RAB.'),
(2003432,68,24,48,39,'‹‹Nasıl da darmadağın oldu Moav! 2 Nasıl acıyla feryat ediyor! 2 Nasıl da sırtını dönüyor utançtan! 2 Moav çevresindekilere alay konusu, 2 Dehşet verici bir örnek oldu.››'),
(2003433,68,24,48,40,'RAB diyor ki, 2 ‹‹Bakın! Düşman birden çullanan bir kartal gibi 2 Kanatlarını Moavın üzerine açacak.'),
(2003434,68,24,48,41,'Keriyot ele geçirilecek, 2 Kaleler alınacak. 2 O gün Moavlı askerlerin yüreği, 2 Doğum sancısı çeken kadının yüreği gibi olacak.'),
(2003435,68,24,48,42,'Moav yıkıma uğrayacak, 2 Halk olmaktan çıkacak; 2 Çünkü RABbe karşı büyüklük tasladı.'),
(2003436,68,24,48,43,'Önünde dehşet, çukur ve tuzak var, 2 Ey Moav halkı!›› diyor RAB.'),
(2003437,68,24,48,44,'‹‹Dehşetten kaçan çukura düşecek, 2 Çukurdan çıkan tuzağa yakalanacak; 2 Çünkü Moavın üzerine 2 Cezalandırma yılını getireceğim›› diyor RAB.'),
(2003438,68,24,48,45,'‹‹Heşbonun gölgesinde 2 Bitkin düşmüş kaçkınlar. 2 Çünkü Heşbondan ateş, 2 Sihonun ortasından alev çıktı; 2 Moavlıların alınlarını, 2 Kargaşa çıkaranların başlarını yakıp yok etti.'),
(2003439,68,24,48,46,'Vay sana, ey Moav! 2 İlah Kemoşun halkı yok oldu, 2 Oğulların sürgüne gönderildi, 2 Kızların tutsak alındı.'),
(2003440,68,24,48,47,'Ama son günlerde 2 Yine eski gönencine kavuşturacağım Moav''ı›› diyor RAB. Moav''ın yargısı burada sona eriyor.'),
(2003441,68,24,49,1,'RAB Ammonlulara ilişkin şöyle diyor: ‹‹İsrailin çocukları yok mu? 2 Yok mu mirasçısı? 2 Öyleyse neden ilah Molek Gadı mülk edindi? 2 Neden onun halkı Gad kentlerinde oturuyor?'),
(2003442,68,24,49,2,'İşte bu nedenle›› diyor RAB, 2 ‹‹Ammonluların Rabba Kentine karşı 2 Savaş narasını işittireceğim günler geliyor. 2 Rabba ıssız bir höyük olacak, 2 Köyleri ateşe verilecek. 2 Böylece İsrail, kendisini mülk edinenleri 2 Mülk edinecek›› diyor RAB.'),
(2003443,68,24,49,3,'‹‹Haykır, ey Heşbon! 2 Ay Kenti yıkıldı! 2 Feryat edin, ey Rabba kızları! 2 Çul sarınıp yas tutun. 2 Duvarların arasında oraya buraya koşuşun. 2 Çünkü Molek kâhinleri ve görevlileriyle birlikte 2 Sürgüne gönderilecek.'),
(2003444,68,24,49,4,'Verimli vadilerinle ne kadar övünüyorsun, 2 Ey dönek kız! 2 Servetine güvenerek, 2 ‹Bana kim saldırabilir?› diyorsun.'),
(2003445,68,24,49,5,'Bütün çevrenden 2 Dehşet saçacağım üzerine›› 2 Diyor Her Şeye Egemen Egemen RAB. 2 ‹‹Her biriniz apar topar sürülecek, 2 Kaçkınları toplayan olmayacak.'),
(2003446,68,24,49,6,'Ama sonra Ammonluları 2 Eski gönencine kavuşturacağım›› diyor RAB.'),
(2003447,68,24,49,7,'Her Şeye Egemen RAB Edoma ilişkin şöyle diyor: ‹‹Teman Kentinde bilgelik kalmadı mı artık? 2 Akıllı kişilerde öğüt tükendi mi? 2 Bilgelikleri yozlaştı mı?'),
(2003448,68,24,49,8,'Kaçın, geri dönün, derinliklere sığının, 2 Ey Dedanda yaşayanlar! 2 Çünkü Esavı cezalandırdığımda 2 Başına felaket getireceğim.'),
(2003449,68,24,49,9,'Üzüm toplayanlar bağına girseydi, 2 Birkaç salkım bırakmazlar mıydı? 2 Gece hırsızlar gelselerdi, 2 Yalnızca gereksindiklerini çalmazlar mıydı?'),
(2003450,68,24,49,10,'Oysa ben Esavı çırılçıplak soyacak, 2 Gizli yerlerini açığa çıkaracağım, 2 Gizlenemeyecek. 2 Çocukları, akrabaları, komşuları 2 Yıkıma uğrayacak. 2 Kendisi de yok olacak!'),
(2003451,68,24,49,11,'Öksüz çocuklarını bırak, 2 Ben yaşatırım onları. 2 Dul kadınların da bana güvensinler.››'),
(2003452,68,24,49,12,'RAB diyor ki, 2 ‹‹Hak etmeyenler bile kâseyi içmek zorundayken, 2 Sen mi cezasız kalacaksın? 2 Hayır, cezasız kalmayacaksın, 2 Kesinlikle içeceksin kâseyi.'),
(2003453,68,24,49,13,'Adım üzerine ant içerim ki›› diyor RAB, 2 ‹‹Bosra dehşet konusu olacak, yerilecek, 2 Viraneye dönecek, aşağılanacak. 2 Bütün kentleri sonsuza dek yıkık kalacak.››'),
(2003454,68,24,49,14,'RABden bir haber aldım: 2 Uluslara gönderdiği haberci, 2 ‹‹Edoma saldırmak için toplanın, 2 Savaşa hazırlanın!›› diyor.'),
(2003455,68,24,49,15,'‹‹Bak, seni uluslar arasında küçük düşüreceğim, 2 İnsanlar seni hor görecek.'),
(2003456,68,24,49,16,'Saçtığın dehşet ve yüreğindeki gurur 2 Seni aldattı. 2 Sen ki, kaya kovuklarında yaşıyor, 2 Tepenin doruğunu elinde tutuyorsun. 2 Yuvanı kartal gibi yükseklerde kursan da, 2 Oradan indireceğim seni›› diyor RAB. Edomun başkentinin adıydı.'),
(2003457,68,24,49,17,'‹‹Edom dehşet konusu olacak, 2 Oradan geçen herkes şaşkın şaşkın bakıp 2 Başına gelen belalardan ötürü 2 Onunla alay edecek.'),
(2003458,68,24,49,18,'Sodomla Gomorayı ve çevredeki köyleri 2 Nasıl yerle bir ettimse›› diyor RAB, 2 ‹‹Orada da kimse oturmayacak, 2 İnsan oraya yerleşmeyecek.'),
(2003459,68,24,49,19,'‹‹Şeria çalılıklarından 2 Sulak otlağa çıkan aslan gibi 2 Edomu bir anda yurdundan kovacağım. 2 Seçeceğim kişiyi ona yönetici atayacağım. 2 Var mı benim gibisi? 2 Var mı bana dava açacak biri, 2 Bana karşı duracak çoban?››'),
(2003460,68,24,49,20,'Bu yüzden RABbin Edoma karşı ne tasarladığını, 2 Temanda yaşayanlara karşı ne amaçladığını işitin: 2 ‹‹Sürünün küçükleri bile sürülecek, 2 Halkı yüzünden Edom otlakları çöle dönüştürülecek.'),
(2003461,68,24,49,21,'Yıkılışlarının gürültüsünden yeryüzü titreyecek, 2 Çığlıkları Kızıldenize dek duyulacak.'),
(2003462,68,24,49,22,'Düşman kartal gibi üzerlerine çullanacak, 2 Kanatlarını Bosraya karşı açacak. 2 O gün Edomlu askerlerin yüreği, 2 Doğum sancısı çeken kadının yüreği gibi olacak.››'),
(2003463,68,24,49,23,'Şama ilişkin: ‹‹Hama ve Arpat utanacak, 2 Çünkü kötü haber işittiler. 2 Korkudan eridiler, 2 Sessiz duramayan deniz gibi 2 Kaygıyla sarsıldılar.'),
(2003464,68,24,49,24,'‹‹Şam güçsüz düştü, 2 Kaçmak için döndü; 2 Telaşa kapıldı, 2 Doğuran kadın gibi 2 Sancı ve acılar sardı onu.'),
(2003465,68,24,49,25,'Nasıl oldu da sevinç bulduğum ünlü kent 2 Terk edilmedi?'),
(2003466,68,24,49,26,'Bu yüzden gençleri meydanlarda düşecek, 2 Bütün savaşçıları susturulacak o gün›› 2 Diyor Her Şeye Egemen RAB.'),
(2003467,68,24,49,27,'‹‹Şam surlarını ateşe vereceğim, 2 Yakıp yok edecek Ben-Hadatın saraylarını.››'),
(2003468,68,24,49,28,'Babil Kralı Nebukadnessarın bozguna uğrattığı Kedar ve Hasor krallıklarına ilişkin RAB şöyle diyor: ‹‹Kalkın, Kedara saldırın, 2 Doğu halkını yok edin.'),
(2003469,68,24,49,29,'Çadırlarıyla sürüleri alınacak, 2 Çadır perdeleri, 2 Eşyalarıyla develeri alınıp götürülecek. 2 İnsanlar, ‹Her yer dehşet içinde!› diye bağıracaklar onlara.'),
(2003470,68,24,49,30,'Kaçın, uzaklaşın! 2 Derinliklere sığının, 2 Ey Hasorda oturanlar!›› diyor RAB. 2 ‹‹Çünkü Babil Kralı Nebukadnessar 2 Size düzen kurdu; 2 Sizin için bir tasarısı var.'),
(2003471,68,24,49,31,'Kalkın, tasasız ve güvenlik içinde 2 Yaşayan ulusa saldırın›› diyor RAB. 2 ‹‹Onun kent kapıları, sürgüleri yok, 2 Halkı tek başına yaşıyor.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003472,68,24,49,32,'Develeri yağma edilecek, 2 Sayısız sürüleri çapul malı olacak. 2 Zülüflerini kesenleri 2 Dört yana dağıtacağım, 2 Her yandan felaket getireceğim başlarına›› diyor RAB.'),
(2003473,68,24,49,33,'‹‹Çakalların uğrağı Hasor, 2 Sonsuza dek viran kalacak, 2 Orada kimse oturmayacak, 2 İnsan oraya yerleşmeyecek.››'),
(2003474,68,24,49,34,'Yahuda Kralı Sidkiyanın krallığının başlangıcında RABbin Peygamber Yeremyaya bildirdiği Elama ilişkin söz şudur:'),
(2003475,68,24,49,35,'Her Şeye Egemen RAB diyor ki, 2 ‹‹Bakın, Elamın yayını, 2 Asıl gücünü kıracağım.'),
(2003476,68,24,49,36,'Üzerine göğün dört ucundan 2 Dört rüzgarı gönderecek, 2 Halkını bu rüzgarlara dağıtacağım. 2 Elam sürgünlerinin gitmediği 2 Bir ulus kalmayacak.'),
(2003477,68,24,49,37,'Düşmanlarının önünde, 2 Can düşmanlarının önünde 2 Elamı darmadağın edeceğim. 2 Başlarına felaket gönderecek, 2 Şiddetli öfkemi yağdıracağım›› diyor RAB, 2 ‹‹Onları büsbütün yok edene dek 2 Peşlerine kılıcı salacağım.'),
(2003478,68,24,49,38,'Elamda tahtımı kuracak, 2 Elam Kralıyla önderlerini 2 Yok edeceğim›› diyor RAB.'),
(2003479,68,24,49,39,'‹‹Ama son günlerde 2 Elam''ı eski gönencine kavuşturacağım›› diyor RAB.'),
(2003480,68,24,50,1,'RABbin Babil ve Kildan ülkesine ilişkin Peygamber Yeremya aracılığıyla bildirdiği söz şudur:'),
(2003481,68,24,50,2,'‹‹Uluslara duyurun, haberi bildirin! 2 Sancak dikip duyurun, hiçbir şey gizlemeyin! 2 ‹Babil ele geçirilecek› deyin, 2 ‹İlahı Bel utandırılacak, 2 İlahı Marduk paramparça olacak. 2 Putları utandırılacak, 2 İlahları paramparça olacak.›'),
(2003482,68,24,50,3,'Çünkü kuzeyden gelen bir ulus ona saldıracak, 2 Ülkesini viran edecek. 2 Orada kimse yaşamayacak, 2 İnsan da hayvan da kaçıp gidecek.'),
(2003483,68,24,50,4,'O günlerde, o zamanda›› diyor RAB, 2 ‹‹İsrail halkıyla Yahuda halkı birlikte gelecek; 2 Tanrıları RABbi aramak için 2 Ağlaya ağlaya gelecekler.'),
(2003484,68,24,50,5,'Yüzleri Siyona dönük, 2 Oraya giden yolu soracak, 2 Kalıcı, unutulmaz bir antlaşmayla 2 RABbe bağlanmak için gelecekler.'),
(2003485,68,24,50,6,'‹‹Halkım yitik koyunlardır, 2 Çobanları onları baştan çıkardı. 2 Dağlarda başıboş dolandırdılar onları, 2 Dağ, tepe avare dolaştılar, 2 Kendi ağıllarını unuttular.'),
(2003486,68,24,50,7,'Kim bulduysa yedi onları. 2 Düşmanları, ‹Biz suçlu değiliz› dediler, 2 ‹Çünkü onlar gerçek otlakları olan RABbe, 2 Atalarının umudu RABbe karşı günah işlediler.›'),
(2003487,68,24,50,8,'‹‹Babilden kaçıp kurtulun! 2 Kildan ülkesini terk edin, 2 Sürüye yön veren teke gibi olun!'),
(2003488,68,24,50,9,'Çünkü birbiriyle anlaşmış büyük ulusları 2 Kuzeydeki topraklardan kışkırtıp 2 Babilin karşısına çıkaracağım. 2 Babille savaşmak üzere karşısına dizilecek, 2 Onu kuzeyden ele geçirecekler. 2 Okları usta savaşçı oku gibidir, 2 Hiçbiri boş dönmeyecek.'),
(2003489,68,24,50,10,'Kildan ülkesi yağmaya uğrayacak, 2 Onu yağmalayanlar mala doyacak›› diyor RAB.'),
(2003490,68,24,50,11,'‹‹Ey mirasımı yağmalayan sizler! 2 Madem sevinip coşuyorsunuz, 2 Harman döven düve gibi sıçrıyor, 2 Aygır gibi kişniyorsunuz;'),
(2003491,68,24,50,12,'Anneniz büyük utanca boğulacak, 2 Sizi doğuranın yüzü kızaracak. 2 Ulusların en önemsizi, 2 Kurak, bozkır, çöl olacak.'),
(2003492,68,24,50,13,'RABbin öfkesi yüzünden kimse yaşamayacak orada, 2 Büsbütün ıssız kalacak. 2 Her geçen, Babilin aldığı yaraları görünce şaşacak, 2 Hayrete düşecek.'),
(2003493,68,24,50,14,'Babilin çevresinde savaşmak üzere dizilin, 2 Ey bütün yay çekenler! 2 Oklarla saldırın ona, oklarınızı esirgemeyin! 2 Çünkü o RABbe karşı günah işledi.'),
(2003494,68,24,50,15,'Her yandan ona karşı savaş narası yükseltin! 2 Teslim oldu, kuleleri düştü, 2 Surları yerle bir oldu. 2 Çünkü RABbin öcüdür bu. 2 Ondan öç alın. 2 Yaptığının aynısını yapın ona.'),
(2003495,68,24,50,16,'Ekin ekeni biçim vakti orakçıyla birlikte 2 Babilden atın. 2 Zorbanın kılıcı yüzünden 2 Herkes halkına dönsün, 2 Ülkesine kaçsın.››'),
(2003496,68,24,50,17,'‹‹İsrail aslanların kovaladığı 2 Dağılmış bir sürüdür. 2 Önce Asur Kralı yedi onu. 2 Sonra Babil Kralı Nebukadnessar kemiklerini ezdi.››'),
(2003497,68,24,50,18,'Bu yüzden İsrailin Tanrısı, 2 Her Şeye Egemen RAB diyor ki, 2 ‹‹Asur Kralını nasıl cezalandırdıysam, 2 Babil Kralıyla ülkesini de öyle cezalandıracağım.'),
(2003498,68,24,50,19,'İsraili yeniden otlağına kavuşturacağım, 2 Karmelde, Başanda otlayacak; 2 Efrayim ve Gilat dağlık bölgelerinde 2 İstediği kadar yiyip doyacak.'),
(2003499,68,24,50,20,'O günlerde, o zamanda›› diyor RAB, 2 ‹‹İsrailin suçu araştırılacak 2 Ama bulunamayacak; 2 Yahudanın günahları da araştırılacak 2 Ama bulunamayacak. 2 Çünkü sağ bıraktıklarımı bağışlayacağım.››'),
(2003500,68,24,50,21,'‹‹Meratayimfş ülkesine, 2 Pekotta yaşayanlara saldır. 2 Onları öldür, tümüyle yok et›› diyor RAB, 2 ‹‹Sana ne buyurduysam hepsini yap. gelir.'),
(2003501,68,24,50,22,'Ülkede savaş, büyük yıkım 2 Gürültüsü duyuluyor.'),
(2003502,68,24,50,23,'Dünyanın balyozu 2 Nasıl da kırılıp paramparça oldu! 2 Babil uluslar arasında nasıl dehşet oldu!'),
(2003503,68,24,50,24,'Senin için tuzak kurdum, ey Babil, 2 Bilmeden tuzağıma düştün. 2 Bulunup yakalandın, 2 Çünkü RABbe karşı çıktın.'),
(2003504,68,24,50,25,'RAB silahhanesini açtı, 2 Öfkesinin silahlarını çıkardı. 2 Her Şeye Egemen Egemen RABbin 2 Kildan ülkesinde yapacağı iş var.'),
(2003505,68,24,50,26,'Uzaktan ona saldırın. 2 Ambarlarını açın, 2 Mallarını tahıl gibi küme küme yığın. 2 Tamamen yok edin onu, 2 Geriye hiçbir şey kalmasın.'),
(2003506,68,24,50,27,'Genç boğalarını öldürün, 2 Kesime gitsinler! 2 Vay başlarına! 2 Çünkü onların günü, 2 Cezalandırılma zamanı geldi.'),
(2003507,68,24,50,28,'Dinleyin! Tanrımız RABbin öç aldığını, 2 Tapınağının öcünü aldığını 2 Babilden kaçıp kurtulanlar 2 Siyonda duyuruyorlar.'),
(2003508,68,24,50,29,'‹‹Okçuları, yay gerenlerin hepsini çağırın Babile karşı, 2 Çevresini kuşatın, kaçıp kurtulan olmasın. 2 Yaptıklarına göre karşılık verin ona, 2 Yaptıklarının aynısını yapın. 2 Çünkü RABbe, İsrailin Kutsalına 2 Küstahlık etti.'),
(2003509,68,24,50,30,'Bu yüzden gençleri meydanlarda düşecek, 2 Bütün savaşçıları susturulacak o gün›› diyor RAB.'),
(2003510,68,24,50,31,'‹‹İşte, sana karşıyım, ey küstah!›› 2 Diyor Her Şeye Egemen Egemen RAB. 2 ‹‹Çünkü senin günün, 2 Seni cezalandıracağım zaman geldi.'),
(2003511,68,24,50,32,'Küstah tökezleyip düşecek, 2 Onu kaldıran olmayacak. 2 Kentlerini ateşe vereceğim, 2 Bütün çevresini yakıp yok edecek.››'),
(2003512,68,24,50,33,'Her Şeye Egemen RAB şöyle diyor: 2 ‹‹İsrail halkı da Yahuda halkı da 2 Eziyet çekiyor. 2 Onları tutsak edenler sıkı tutmuş, 2 Salıvermek istemiyorlar.'),
(2003513,68,24,50,34,'Ama onların Kurtarıcısı güçlüdür, 2 Onun adı Her Şeye Egemen RABdir. 2 Onların ülkesine huzur, 2 Babilde yaşayanlaraysa kargaşalık getirmek için 2 Davalarını hararetle savunacak.'),
(2003514,68,24,50,35,'‹‹Kildanilere karşı kılıç!›› diyor RAB, 2 ‹‹Babilde yaşayanlara, Babil önderlerine, 2 Bilgelerine karşı kılıç!'),
(2003515,68,24,50,36,'Sahte peygamberlere karşı kılıç! 2 Aptallıkları ortaya çıkacak. 2 Yiğitlerine karşı kılıç! 2 Şaşkına dönecek onlar.'),
(2003516,68,24,50,37,'Atlarına, savaş arabalarına 2 Aralarındaki yabancılara karşı kılıç! 2 Hepsi kadın gibi ürkek olacak. 2 Hazinelerine karşı kılıç! 2 Yağma edilecek onlar.'),
(2003517,68,24,50,38,'Sularına kuraklık! 2 Kuruyacak sular. 2 Çünkü Babil putlar ülkesidir, 2 Korkunç putlar yüzünden halkı çıldırmış.'),
(2003518,68,24,50,39,'‹‹Bu yüzden yabanıl hayvanlar, çakallar, 2 Baykuşlar yaşayacak orada, 2 Artık insan yaşamayacak, 2 Kuşaklar boyu kimse oturmayacak.'),
(2003519,68,24,50,40,'Sodomla Gomorayı ve çevredeki köyleri 2 Nasıl yerle bir ettimse›› diyor RAB, 2 ‹‹Orada da kimse oturmayacak, 2 İnsan oraya yerleşmeyecek.'),
(2003520,68,24,50,41,'İşte kuzeyden bir ordu geliyor. 2 Dünyanın uçlarından 2 Büyük bir ulus 2 Ve birçok kral harekete geçiyor.'),
(2003521,68,24,50,42,'Yay, pala kuşanmışlar, 2 Gaddar ve acımasızlar. 2 Atlara binmiş gelirken, 2 Kükreyen denizi andırıyor sesleri. 2 Savaşa hazır savaşçılar 2 Karşına dizilecekler, ey Babil kızı!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003522,68,24,50,43,'Babil Kralı onların haberini aldı, 2 Ellerinde derman kalmadı. 2 Doğuran kadın gibi 2 Üzüntü, sancı sardı onu.'),
(2003523,68,24,50,44,'Şeria çalılıklarından 2 Sulak otlağa çıkan aslan gibi 2 Kildanileri bir anda yurdundan kovacağım. 2 Seçeceğim kişiyi oraya yönetici atayacağım. 2 Var mı benim gibisi? 2 Var mı bana dava açacak biri, 2 Bana karşı duracak çoban?››'),
(2003524,68,24,50,45,'Bu yüzden RABbin Babile karşı ne tasarladığını, 2 Kildan ülkesine karşı ne amaçladığını işitin: 2 ‹‹Sürünün küçükleri bile sürülecek, 2 Halkı yüzünden otlakları çöle dönüştürülecek.'),
(2003525,68,24,50,46,'‹Babil düştü› sesiyle yeryüzü titreyecek, 2 Çığlığı uluslar arasında duyulacak.››'),
(2003526,68,24,51,1,'RAB diyor ki, 2 ‹‹İşte Babile ve Lev-Kamayda yaşayanlara karşı 2 Yok edici bir rüzgar çıkaracağım. ülkesini simgeleyen şifreli bir söz.'),
(2003527,68,24,51,2,'Tahıl savuranları göndereceğim Babile; 2 Onu savurup ayıklasınlar, 2 Ülkesini boşaltsınlar diye. 2 Yıkım günü her yandan saldıracaklar ona.'),
(2003528,68,24,51,3,'Okçu yayını germesin, 2 Zırhını kuşanmasın. 2 Onun gençlerini esirgemeyin! 2 Ordusunu tümüyle yok edin.'),
(2003529,68,24,51,4,'Kildan ülkesinde ölüler, 2 Babil sokaklarında yaralılar serilecek yere.'),
(2003530,68,24,51,5,'İsrailin Kutsalına karşı 2 Ülkeleri suçla dolu olmasına karşın, 2 Tanrıları Her Şeye Egemen RAB 2 İsrail ve Yahuda halklarını bırakmadı.'),
(2003531,68,24,51,6,'Babilden kaçın! 2 Herkes canını kurtarsın! 2 Babilin suçu yüzünden yok olmayın! 2 Çünkü RABbin öç alma zamanıdır, 2 Ona hakkettiğini verecek.'),
(2003532,68,24,51,7,'Babil RABbin elinde bir altın kâseydi, 2 Bütün dünyayı sarhoş etti. 2 Uluslar şarabını içtiler, 2 Bu yüzden çıldırdılar.'),
(2003533,68,24,51,8,'Ansızın düşüp paramparça olacak Babil, 2 Yas tutun onun için! 2 Yarasına merhem sürün, belki iyileşir.'),
(2003534,68,24,51,9,'‹Babili iyileştirmek istedik, ama iyileşmedi. 2 Bırakalım onu, 2 Hepimiz kendi ülkemize dönelim. 2 Çünkü onun yargısı göklere erişiyor, 2 Bulutlara kadar yükseliyor.'),
(2003535,68,24,51,10,'‹‹ ‹RAB haklı olduğumuzu gösterdi, 2 Gelin, Tanrımız RABbin neler yaptığını 2 Siyonda anlatalım.›'),
(2003536,68,24,51,11,'‹‹Okları bileyin, 2 Ok kılıflarını doldurun! 2 RAB Med krallarını harekete geçirdi, 2 Amacı Babili yok etmek. 2 RAB öcünü, tapınağının öcünü alacak.'),
(2003537,68,24,51,12,'Babil surlarına karşı sancak kaldırın! 2 Muhafızları pekiştirin, 2 Nöbetçileri yerleştirin, 2 Pusu kurun! 2 Çünkü RAB Babil halkı için söylediklerini 2 Hem tasarladı hem de yerine getirdi.'),
(2003538,68,24,51,13,'Ey sizler, akarsuların kıyısında yaşayan, 2 Hazinesi bol olanlar, 2 Sonunuz geldi, zamanınız doldu.'),
(2003539,68,24,51,14,'Her Şeye Egemen RAB varlığı hakkı için ant içti: 2 Seni çekirge sürüsüyle doldurur gibi 2 Askerlerle dolduracağım. 2 Sana karşı zafer çığlıkları atacaklar.››'),
(2003540,68,24,51,15,'‹‹Gücüyle yeryüzünü yaratan, 2 Bilgeliğiyle dünyayı kuran, 2 Aklıyla gökleri yayan RABdir.'),
(2003541,68,24,51,16,'O gürleyince gökteki sular çağıldar, 2 Yeryüzünün dört bucağından bulutlar yükseltir, 2 Yağmur için şimşek çaktırır, 2 Ambarlarından rüzgar estirir.'),
(2003542,68,24,51,17,'Hepsi budala, bilgisiz. 2 Her kuyumcu yaptığı puttan utanacak. 2 O putlar yapmacıktır, 2 Soluk yoktur onlarda.'),
(2003543,68,24,51,18,'Yararsız, alay edilesi nesnelerdir, 2 Cezalandırılınca yok olacaklar.'),
(2003544,68,24,51,19,'Yakupun Payı onlara benzemez. 2 Mirası olan oymak dahil 2 Her şeye biçim veren Odur, 2 Her Şeye Egemen RABdir adı.'),
(2003545,68,24,51,20,'‹‹Sen benim savaş çomağım, 2 Savaş silahımsın. 2 Ulusları parçalayacak, 2 Krallıkları yok edeceğim seninle.'),
(2003546,68,24,51,21,'Seninle atlarla binicilerini, 2 Savaş arabalarıyla sürücülerini kırıp ezeceğim.'),
(2003547,68,24,51,22,'Erkeklerle kadınları, 2 Gençlerle yaşlıları, 2 Delikanlılarla genç kızları,'),
(2003548,68,24,51,23,'Çobanla sürüsünü, 2 Çiftçiyle öküzlerini, 2 Valilerle yardımcılarını darmadağın edeceğim.'),
(2003549,68,24,51,24,'‹‹Babilde ve Kildan ülkesinde yaşayanlara 2 Siyonda yaptıkları bütün kötülüğün karşılığını 2 Gözlerinizin önünde ödeteceğim›› diyor RAB.'),
(2003550,68,24,51,25,'‹‹Ey yıkıcı dağ, sana karşıyım, 2 Ey bütün dünyayı yıkan›› diyor RAB, 2 ‹‹Elimi sana karşı kaldırıp 2 Seni uçuruma yuvarlayacak, 2 Yanık bir dağa çevireceğim.'),
(2003551,68,24,51,26,'Senden köşe taşı, temel taşı olmayacak, 2 Çünkü sonsuza dek viran kalacaksın›› diyor RAB.'),
(2003552,68,24,51,27,'‹‹Ülkeye sancak dikin! 2 Uluslar arasında boru çalın! 2 Ulusları Babille savaşmaya hazırlayın. 2 Ararat, Minni, Aşkenaz krallıklarını 2 Ona karşı toplayın. 2 Ona karşı bir komutan atayın, 2 Çekirge sürüsü kadar at gönderin üzerine.'),
(2003553,68,24,51,28,'Ulusları -Med krallarını, valilerini, 2 Bütün yardımcılarını, 2 Yönetimi altındaki bütün ülkeleri- 2 Onunla savaşmaya hazırlayın.'),
(2003554,68,24,51,29,'Ülke titreyip kıvranıyor! 2 Çünkü RABbin Babil diyarını 2 Issız bir viraneye çevirme amacı 2 Yerine gelmeli.'),
(2003555,68,24,51,30,'Babil yiğitleri savaştan vazgeçti, 2 Kalelerinde oturuyorlar. 2 Güçleri tükendi, 2 Ürkek kadınlara döndüler. 2 Oturdukları yerler ateşe verildi, 2 Kapı sürgüleri kırıldı.'),
(2003556,68,24,51,31,'Babil Kralına ulak üstüne ulak, 2 Haberci üstüne haberci geldi. 2 ‹Kent bütünüyle düştü, 2 Irmak geçitleri tutuldu, 2 Bataklıklar ateşe verildi, 2 Askerler dehşete kapıldı› diye haber verdiler.››'),
(2003557,68,24,51,33,'İsrailin Tanrısı, Her Şeye Egemen RAB diyor ki, 2 ‹‹Zamanı gelince harman yeri nasıl çiğnenirse, 2 Babil kızı da öyle olacak. 2 Kısa süre sonra onun da 2 Biçim zamanı gelecek.››'),
(2003558,68,24,51,34,'Siyon halkı, ‹‹Babil Kralı Nebukadnessar yuttu bizi, ezdi, 2 Boş bir kaba çevirdi›› diyecek, 2 ‹‹Canavar gibi yuttu bizi, 2 Güzel yemeklerimizle karnını doyurdu, 2 Sonra bizi kustu. 2 Bize ve yurttaşlarımıza yapılan zorbalık 2 Babilin başına gelsin.›› 2 Yeruşalim, ‹‹Dökülen kanımızın hesabı 2 Kildanilerden sorulsun›› diyecek.'),
(2003559,68,24,51,36,'Bunun için RAB diyor ki, 2 ‹‹İşte davanızı ben savunacağım, 2 Öcünüzü ben alacağım; 2 Onun ırmağını kurutacak, 2 Kaynağını keseceğim.'),
(2003560,68,24,51,37,'Babil taş yığınına, çakal yuvasına dönecek, 2 Dehşet ve alay konusu olacak. 2 Kimse yaşamayacak orada.'),
(2003561,68,24,51,38,'Halkı genç aslanlar gibi kükreyecek, 2 Aslan yavruları gibi homurdanacak.'),
(2003562,68,24,51,39,'Ama kızıştıklarında onlara şölen verip 2 Hepsini sarhoş edeceğim; 2 Keyiflensinler, 2 Uyanmayacakları sonsuz bir uykuya 2 Dalsınlar diye›› diyor RAB.'),
(2003563,68,24,51,40,'‹‹Onları kuzu gibi, koç ve teke gibi 2 Boğazlanmaya götüreceğim.››'),
(2003564,68,24,51,41,'‹‹Şeşak nasıl alındı! 2 Bütün dünyanın övünç kaynağı nasıl ele geçirildi! 2 Uluslar arasında Babil nasıl dehşet oldu!'),
(2003565,68,24,51,42,'Deniz basacak Babili, 2 Kabaran dalgalar örtecek.'),
(2003566,68,24,51,43,'Kentleri viran olacak, 2 Toprakları kimsenin yaşamadığı, geçmediği 2 Kurak bir çöle dönecek.'),
(2003567,68,24,51,44,'Babil ilahı Beli orada cezalandıracak, 2 Yuttuğunu ona kusturacağım. 2 Artık akın akın uluslar gelmeyecek ona. 2 Babil surları yıkılacak.'),
(2003568,68,24,51,45,'‹‹Oradan çık, ey halkım! 2 Hepiniz canınızı kurtarın! 2 Kaçın RABbin kızgın öfkesinden!'),
(2003569,68,24,51,46,'Ülkede duyacağınız söylentiler yüzünden 2 Cesaretinizi yitirmeyin, korkmayın. 2 Bir yıl bir söylenti duyulur, ertesi yıl bir başkası; 2 Ülkedeki zorbalıkla, 2 Önderin öndere karşı çıktığıyla 2 İlgili söylentiler yayılır.'),
(2003570,68,24,51,47,'İşte bu yüzden Babilin putlarını 2 Cezalandıracağım günler geliyor. 2 Bütün ülke utandırılacak, 2 Öldürülenler ülkenin ortasında yere serilecek.'),
(2003571,68,24,51,48,'O zaman yer, gök ve onlardaki her şey 2 Babilin başına gelenlere sevinecek. 2 Çünkü kuzeyden gelen yok ediciler 2 Saldıracaklar ona›› diyor RAB.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003572,68,24,51,49,'Yeremya şöyle diyor: 2 ‹‹İsrailin öldürülenleri yüzünden düşmelidir Babil. 2 Yeryüzünde öldürülen herkes Babil yüzünden düştü.'),
(2003573,68,24,51,50,'Ey sizler, kılıçtan kurtulanlar, 2 Kaçın, oyalanmayın! 2 RABbi anın uzaktan, 2 Yeruşalimi düşünün!››'),
(2003574,68,24,51,51,'‹‹Rezil olduk, çünkü aşağılandık, 2 Yüzümüz utanç içinde. 2 Çünkü yabancılar RABbin Tapınağının 2 Kutsal yerlerine girmişler.››'),
(2003575,68,24,51,52,'‹‹Bu yüzden›› diyor RAB, 2 ‹‹Putlarını cezalandıracağım günler geliyor, 2 Yaralılar inleyecek bütün ülkede.'),
(2003576,68,24,51,53,'Babil göklere çıksa, 2 Yüksekteki kalesini pekiştirse de, 2 Yok edicileri göndereceğim üzerine›› diyor RAB.'),
(2003577,68,24,51,54,'‹‹Babilden çığlık, 2 Kildan ülkesinden büyük yıkım sesi duyuluyor.'),
(2003578,68,24,51,55,'Çünkü RAB Babili yıkıma uğratıyor; 2 Şamatasını susturuyor. 2 Düşman engin sular gibi kükrüyor, 2 Seslerinin gürültüsü yankılanıyor.'),
(2003579,68,24,51,56,'Çünkü Babile karşı bir yok edici çıkacak; 2 Yiğitleri tutsak olacak, 2 Yayları paramparça edilecek. 2 Çünkü RAB karşılık veren bir Tanrıdır, 2 Her şeyin tam karşılığını verir.'),
(2003580,68,24,51,57,'Babil önderlerini, bilgelerini, valilerini, 2 Yardımcılarını, yiğitlerini öyle sarhoş edeceğim ki, 2 Sonsuz bir uykuya dalacak, hiç uyanmayacaklar›› 2 Diyor adı Her Şeye Egemen RAB olan Kral.'),
(2003581,68,24,51,58,'Her Şeye Egemen RAB diyor ki, 2 ‹‹Babilin kalın surları yerle bir edilecek, 2 Yüksek kapıları ateşe verilecek. 2 Halkların çektiği emek boşuna, 2 Ulusların didinmesi ateşe yarayacak.››'),
(2003582,68,24,51,59,'Yahuda Kralı Sidkiyanın krallığının dördüncü yılında, baş görevli Mahseya oğlu Neriya oğlu Seraya Sidkiyayla birlikte Babile gittiğinde Peygamber Yeremya ona şu buyruğu verdi.'),
(2003583,68,24,51,60,'Yeremya Babilin başına gelecek bütün felaketleri, Babile ilişkin bütün bu sözleri bir tomara yazmıştı.'),
(2003584,68,24,51,61,'Yeremya Serayaya şöyle dedi: ‹‹Babile varır varmaz bütün bu sözleri okumayı unutma.'),
(2003585,68,24,51,62,'De ki, ‹Ya RAB, burayı yıkacağını, içinde insan da hayvan da yaşamayacağını, ülkenin sonsuza dek viran kalacağını söyledin.›'),
(2003586,68,24,51,63,'Okumayı bitirince tomarı bir taşa bağlayıp Fırata fırlat.'),
(2003587,68,24,51,64,'Sonra de ki, ‹Babil başına getireceğim felaket yüzünden batacak, bir daha kalkamayacak. Bitkin düşecekler.› ›› Yeremya''nın sözleri burada son buluyor.'),
(2003588,68,24,52,1,'Sidkiya yirmi bir yaşında kral oldu ve Yeruşalimde on bir yıl krallık yaptı. Annesi Livnalı Yeremyanın kızı Hamutaldı.'),
(2003589,68,24,52,2,'Yehoyakim gibi Sidkiya da RABbin gözünde kötü olanı yaptı.'),
(2003590,68,24,52,3,'RAB Yeruşalimle Yahudaya öfkelendiği için onları huzurundan attı. Sidkiya Babil Kralına karşı ayaklandı.'),
(2003591,68,24,52,4,'Sidkiyanın krallığının dokuzuncu yılında, onuncu ayın onuncu günü, Babil Kralı Nebukadnessar bütün ordusuyla Yeruşalim önlerine gelip ordugah kurdu. Kentin çevresine rampa yaptılar.'),
(2003592,68,24,52,5,'Kral Sidkiyanın krallığının on birinci yılına kadar kent kuşatma altında kaldı.'),
(2003593,68,24,52,6,'Dördüncü ayın dokuzuncu günü kentte kıtlık öyle şiddetlendi ki, halk bir lokma ekmek bulamaz oldu.'),
(2003594,68,24,52,7,'Sonunda kentin surlarında bir gedik açıldı. Kildaniler kenti çepeçevre kuşatmış olmasına karşın, bütün askerler gece kral bahçesinin yolundan iki duvarın arasındaki kapıdan kaçarak Arava yoluna çıktılar.'),
(2003595,68,24,52,8,'Ama Kildani ordusu Kral Sidkiyanın ardına düşerek Eriha ovalarında ona yetişti. Sidkiyanın bütün ordusu dağıldı.'),
(2003596,68,24,52,9,'Kral Sidkiya yakalanıp Hama topraklarında, Rivlada Babil Kralının huzuruna çıkarıldı. Babil Kralı onun hakkında karar verdi.'),
(2003597,68,24,52,10,'Sidkiyanın gözü önünde oğullarını, sonra da bütün Yahuda önderlerini öldürttü.'),
(2003598,68,24,52,11,'Sidkiyanın gözlerini oydu, zincire vurup Babile götürdü. Sidkiya öldüğü güne dek cezaevinde tutuldu.'),
(2003599,68,24,52,12,'Babil Kralı Nebukadnessarın krallığının on dokuzuncu yılında, beşinci ayın onuncu günü muhafız birliği komutanı, Babil Kralının görevlisi Nebuzaradan Yeruşalime girdi.'),
(2003600,68,24,52,13,'RABbin Tapınağını, sarayı ve Yeruşalimdeki bütün evleri ateşe verip önemli yapıları yaktı.'),
(2003601,68,24,52,14,'Muhafız birliği komutanı önderliğindeki Kildani ordusu Yeruşalimi çevreleyen bütün surları yıktı.'),
(2003602,68,24,52,15,'Komutan Nebuzaradan yoksullardan bazılarını, kentte sağ kalanları, Babil Kralının safına geçen kaçakları ve zanaatçıları sürgün etti.'),
(2003603,68,24,52,16,'Ancak bağcılık, çiftçilik yapsınlar diye bazı yoksulları orada bıraktı.'),
(2003604,68,24,52,17,'Kildaniler RABbin Tapınağındaki tunç sütunları, ayaklıkları, tunç havuzu parçalayıp tunçları Babile götürdüler.'),
(2003605,68,24,52,18,'Tapınak törenlerinde kullanılan kovaları, kürekleri, fitil maşalarını, çanakları, tabakları, bütün tunç eşyaları aldılar.'),
(2003606,68,24,52,19,'Muhafız birliği komutanı saf altın ve gümüş tasları, buhurdanları, çanakları, kovaları, kandillikleri, tabakları, dökmelik sunu taslarını alıp götürdü.'),
(2003607,68,24,52,20,'RABbin Tapınağı için Kral Süleymanın yaptırmış olduğu iki sütun, havuz ve altındaki on iki tunç boğa heykeliyle ayaklıklar için hesapsız tunç harcanmıştı.'),
(2003608,68,24,52,21,'Her sütun on sekiz arşınfü yüksekliğindeydi, çevresi on iki arşındı. Her birinin kalınlığı dört parmaktı, içi boştu.'),
(2003609,68,24,52,22,'Üzerinde tunç bir başlık vardı. Başlığın yüksekliği beş arşındı, çevresi tunçtan ağ ve nar motifleriyle bezenmişti. Öbür sütun da nar motifleriyle süslenmişti ve ötekine benziyordu.'),
(2003610,68,24,52,23,'Yanlarda doksan altı nar motifi vardı. Başlığı çevreleyen ağ motifinin üzerinde toplam yüz nar motifi bulunuyordu.'),
(2003611,68,24,52,24,'Muhafız birliği komutanı Nebuzaradan Başkâhin Serayayı, Başkâhin Yardımcısı Sefanyayı ve üç kapı nöbetçisini tutsak aldı.'),
(2003612,68,24,52,25,'Kentte kalan askerlerin komutanını, kralın yedi danışmanını, ayrıca ülke halkını askere yazan ordu komutanının yazmanını ve ülke halkından kentte bulunan altmış kişiyi tutsak etti.'),
(2003613,68,24,52,26,'Hepsini Rivlaya, Babil Kralının yanına götürdü.'),
(2003614,68,24,52,27,'Babil Kralı Hama ülkesinde, Rivlada onları idam etti. Böylece Yahuda halkı ülkesinden sürülmüş oldu.'),
(2003615,68,24,52,28,'Nebukadnessarın sürgüne götürdüğü halkın sayısı şudur: Yedinci yıl 3 023 Yahudi;'),
(2003616,68,24,52,29,'Nebukadnessarın on sekizinci yılında Yeruşalimden 832 kişi;'),
(2003617,68,24,52,30,'yirmi üçüncü yılında, muhafız birliği komutanı Nebuzaradanın sürdüğü 745 Yahudi. Hepsi 4 600 kişiydi.'),
(2003618,68,24,52,31,'Yahuda Kralı Yehoyakinin sürgündeki otuz yedinci yılı Evil-Merodak Babil Kralı oldu. Evil-Merodak o yılın on ikinci ayının yirmi beşinci günü, Yahuda Kralı Yehoyakine lütfederek onu cezaevinden çıkardı.'),
(2003619,68,24,52,32,'Kendisiyle tatlı tatlı konuştu ve ona Babildeki öteki sürgün krallardan daha üstün bir yer verdi.'),
(2003620,68,24,52,33,'Yehoyakin cezaevi giysilerini üstünden çıkardı. Yaşadığı sürece Babil Kralının sofrasında yer aldı.'),
(2003621,68,24,52,34,'Yaşamı boyunca Babil Kralı tarafından günlük yiyeceği sürekli karşılandı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003622,68,25,1,1,'O kent ki, insan doluydu, 2 Nasıl da tek başına kaldı şimdi! 2 Büyüktü uluslar arasında, 2 Dul kadına döndü! 2 Soyluydu iller arasında, 2 Angarya altına düştü!'),
(2003623,68,25,1,2,'Geceleyin acı acı ağlıyor, 2 Yanaklarında gözyaşı; 2 Avutan tek kişi bile yok 2 Bunca oynaşı arasında. 2 Dostları ona hainlik etti, 2 Düşman oldu.'),
(2003624,68,25,1,3,'Yahuda acı çekip ağır kölelik ettikten sonra 2 Sürgün edildi, 2 Ulusların arasında oturuyor, 2 Ama rahat bulamıyor. 2 O sıkıntıdayken ardına düşenler ona yetişti.'),
(2003625,68,25,1,4,'Siyona giden yollar yas tutuyor, 2 Çünkü bayramlara gelen yok. 2 Bütün kapıları ıssız, kâhinleri inliyor, 2 Erden kızları sıkıntıda, kendisi de acı çekiyor.'),
(2003626,68,25,1,5,'Hasımları başa geçti, düşmanları rahat içinde. 2 Çok isyan ettiği için RAB ona acı çektiriyor, 2 Yavruları hasımlarının gözü önünde sürgüne gitti.'),
(2003627,68,25,1,6,'Siyon kızının bütün güzelliği uçtu, 2 Önderleri otlak bulamayan geyiklere döndü, 2 Dermanları kesildi 2 Kendilerini kovalayanların önünde.'),
(2003628,68,25,1,7,'Yeruşalim sıkıntı içinde başıboş dolaşırken 2 Eski günlerdeki varlığını anımsıyor. 2 Halkı hasmının eline düşüp de 2 Yardımına koşan çıkmayınca, 2 Hasımları haline bakıp 2 Yıkılışına güldüler.'),
(2003629,68,25,1,8,'Yeruşalim büyük günah işledi, 2 Bu yüzden kirlendi. 2 Ona saygı duyanların hepsi 2 Şimdi onu hor görüyor, 2 Çünkü onu çıplak gördüler. 2 O da inleyip öbür yana dönüyor.'),
(2003630,68,25,1,9,'Kirliliği eteklerindeydi, 2 Sonunu düşünmedi; 2 Bu yüzden düşüşü korkunç oldu, 2 Avutanı yok. 2 ‹‹Ya RAB, düşkün halimi gör, 2 Çünkü düşmanım kazandı!››'),
(2003631,68,25,1,10,'Değerli her şeyine düşman el uzattı. 2 Tapınağına başka ulusların girdiğini gördü, 2 Topluluğuna girmesini yasakladığın uluslar.'),
(2003632,68,25,1,11,'Halkı inleyip ekmek arıyor, 2 Yeniden güçlerine kavuşmak için 2 Değerli neleri varsa ekmekle değiştiler; 2 ‹‹Bak da gör, ya RAB, ne kadar sefil oldum.››'),
(2003633,68,25,1,12,'‹‹Ey sizler, yoldan geçenler, 2 Sizin için önemi yok mu bunun? 2 Bakın da görün, başıma gelen dert gibisi var mı? 2 Öyle bir dert ki, RAB öfkesinin alevlendiği gün 2 Başıma yağdırdı onu. başınıza da gelmesin.››'),
(2003634,68,25,1,13,'Ateş saldı yukarıdan, 2 Kemiklerimin içine işledi ateş; 2 Ağ serdi ayaklarıma, 2 Geri çevirdi beni; 2 Mahvetti, baygın kaldım bütün gün.'),
(2003635,68,25,1,14,'İsyanlarım boyunduruğa döndü, 2 RABbin eliyle birbirine tutturulup 2 Boynuma geçirildi, gücüm tükendi. 2 Rab karşı duramadığım 2 İnsanların eline verdi beni.'),
(2003636,68,25,1,15,'Hiçe saydı beni savunan yiğitleri, 2 Gençlerimi kırıp geçirmek için çağrı yaptı ordulara, 2 Rab erden Yahuda kızını 2 Üzüm sıkma çukurunda çiğnedi adeta.'),
(2003637,68,25,1,16,'‹‹Ağlıyorum bunlara, 2 Gözlerimden yaşlar boşanıyor; 2 Çünkü beni avutan, 2 Canımı tazeleyen benden uzak. 2 Çocuklarım şaşkına döndü, 2 Çünkü düşmanım üstün çıktı.››'),
(2003638,68,25,1,17,'Siyon ellerini açmış, 2 Ama onu avutan yok. 2 RAB Yakup soyuna karşı buyruk verdi, 2 Komşuları ona hasım olsun, dedi. 2 Yeruşalim aralarında paçavraya döndü.'),
(2003639,68,25,1,18,'‹‹RAB haklıdır, çünkü buyruğuna karşı geldim. 2 Şimdi dinleyin, ey halklar, çektiğim acıyı görün; 2 Erden kızlarım, gençlerim sürgüne gitti.'),
(2003640,68,25,1,19,'Oynaşlarımı çağırdım, 2 Ama aldattılar beni. 2 Yeniden güçlerine kavuşmak için yiyecek ararken 2 Kâhinlerimle önderlerim kentte can verdi.'),
(2003641,68,25,1,20,'Gör, ya RAB, ne sıkıntılar çektiğimi, 2 İçim kanıyor, yüreğim buruk, 2 Çünkü çok asilik ettim; 2 Dışarıda kılıç beni çocuklarımdan ayırmakta, 2 İçerdeyse ölüm kol gezmekte.'),
(2003642,68,25,1,21,'İnlediğimi duydular, 2 Beni avutan olmadı. 2 Bütün düşmanlarım başıma gelen felaketi duydu, 2 Sen yaptın diye sevinçten coştular. 2 İlan ettiğin günü getir, 2 Onlar da benim gibi olsunlar.'),
(2003643,68,25,1,22,'Yaptıkları her kötülüğü anımsa, 2 İsyanlarımdan ötürü bana ne yaptınsa onlara da yap; 2 Çünkü sürekli inliyor, baygınlık geçiriyorum.››'),
(2003644,68,25,2,1,'Rab öfkelenince Siyon kızını nasıl bulutla kapladı! 2 İsrailin görkemini gökten yere fırlattı, 2 Öfkelendiği gün ayağının taburesini anımsamadı.'),
(2003645,68,25,2,2,'Yakup soyunun yaşadığı her yeri acımadan yuttu, 2 Yahuda kızının surlu kentlerini gazabıyla yıktı, 2 Yerle bir etti onları, 2 Krallığını ve önderlerini alçalttı.'),
(2003646,68,25,2,3,'Kızgın öfkesiyle İsrailin gücünü kökünden kesti, 2 Düşmanın önünde sağ elini onların üstünden çekti, 2 Çevresini yiyip bitiren alevli ateş gibi Yakup soyunu yaktı.'),
(2003647,68,25,2,4,'Düşman gibi yayını gerdi, 2 Hasım gibi sağ elini kaldırdı, 2 Göz zevkini okşayan herkesi öldürdü, 2 Gazabını Siyon kızının çadırı üstüne ateş gibi döktü.'),
(2003648,68,25,2,5,'Rab adeta bir düşman olup İsraili yuttu, 2 Bütün saraylarını yutup surlu kentlerini yıktı, 2 Yahuda kızının feryadını, figanını arşa çıkardı.'),
(2003649,68,25,2,6,'Bahçe çardağını söker gibi kendi çardağını söküp attı, 2 Buluşma yerini yok etti, 2 RAB Siyonda bayram ve Şabat günlerini unutturdu, 2 Şiddetli öfkesi yüzünden kralı da kâhini de reddetti.'),
(2003650,68,25,2,7,'Rab sunağını attı, 2 Tapınağını terk etti; 2 Siyon saraylarını çeviren surları düşman eline bıraktı. 2 Bayram gününde olduğu gibi, 2 Düşman RABbin Tapınağında sevinç çığlıkları attı.'),
(2003651,68,25,2,8,'RAB Siyon kızının surlarını yıkmaya karar verdi, 2 İpi gerdi ve yıkmaktan el çekmedi, 2 İç ve dış surlara yas tutturdu, 2 İkisinin de gücü tükendi.'),
(2003652,68,25,2,9,'Siyonun kapıları yere battı, 2 RAB kapı sürgülerini kırıp yok etti, 2 Kralıyla önderleri başka ulusların arasında kaldı, 2 Kutsal Yasa uygulanmaz oldu, 2 Peygamberlerine RABden görüm gelmiyor artık.'),
(2003653,68,25,2,10,'Siyon kızının ileri gelenleri suskun, yere oturmuş, 2 Başlarına toprak saçıp çul kuşanmışlar, 2 Yeruşalimin erden kızları yere eğmiş başlarını.'),
(2003654,68,25,2,11,'Gözlerim tükenmekte ağlamaktan, 2 İçim kanıyor; 2 Halkımın yıkımından 2 Yüreğim sızlıyor, 2 Çünkü kent meydanlarında çocuklarla bebekler bayılmakta.'),
(2003655,68,25,2,12,'Kent meydanlarında yaralılar gibi bayılıp 2 Can çekişirken annelerinin bağrında, 2 ‹‹Ekmekle şarap nerede?›› diye soruyorlar annelerine.'),
(2003656,68,25,2,13,'Senin için ne diyeyim? 2 Ey Yeruşalim kızı, seni neye benzeteyim? 2 Ey Siyonun erden kızı, sana neyi örnek göstereyim de 2 Seni avutayım? 2 Sendeki gedik deniz kadar büyük, 2 Kim sana şifa verebilir?'),
(2003657,68,25,2,14,'Peygamberlerin senin için boş ve anlamsız görümler gördüler. 2 Suçunu ortaya çıkarsalardı, eski gönencine kavuşabilirdin; 2 Oysa seni ayartacak boş görümler gördüler.'),
(2003658,68,25,2,15,'Yoldan geçen herkes el çırparak seninle alay ediyor, 2 Yeruşalim kızına baş sallayıp ıslık çalarak, 2 ‹‹Bütün dünyanın sevinci, güzellik simgesi dedikleri kent bu mu?›› diyorlar.'),
(2003659,68,25,2,16,'Düşmanlarının hepsi seninle alay etti, 2 Islık çalıp diş gıcırdatarak, 2 ‹‹Onu yuttuk›› diyorlar, 2 ‹‹İşte beklediğimiz gün, sonunda gördük onu.››'),
(2003660,68,25,2,17,'RAB düşündüğünü yaptı, 2 Geçmişte söylediği sözü yerine getirdi, 2 Yıktı, acımadı, 2 Düşmanı senin haline sevindirdi, 2 Hasımlarını güçlü kıldı. boynuzunu yükseltti››.'),
(2003661,68,25,2,18,'Halk Rabbe yürekten feryat ediyor. 2 Ey Siyon kızının surları, 2 Gece gündüz gözyaşın sel gibi aksın! 2 Dinlenme, gözüne uyku girmesin!'),
(2003662,68,25,2,19,'Kalk, gece her nöbet başında haykır, 2 Rabbin huzurunda yüreğini su gibi dök! 2 Her sokak başında açlıktan bayılan çocuklarının başı için Ona ellerini aç.'),
(2003663,68,25,2,20,'‹‹Bak, ya RAB, gör! Kime böyle yaptın? 2 Kadınlar çocuklarını, sevgili yavrularını mı yesin? 2 Kâhinle peygamber Rabbin Tapınağında mı öldürülsün?'),
(2003664,68,25,2,21,'Gençler, yaşlılar sokaklarda, yerlerde yatıyor, 2 Kılıçtan geçirildi erden kızlarımla gençlerim, 2 Öfkelendiğin gün öldürdün onları, acımadan boğazladın.'),
(2003665,68,25,2,22,'Bir bayram günü davet eder gibi 2 Beni dehşete düşürenleri davet ettin her yandan. 2 RAB''bin öfkelendiği gün kaçıp kurtulan, 2 Sağ kalan olmadı. 2 Sevgiyle büyüttüğüm çocuklarımı 2 Düşmanım yok etti.››'),
(2003666,68,25,3,1,'RABbin gazap değneği altında acı çeken adam benim.'),
(2003667,68,25,3,2,'Beni güttü, 2 Işıkta değil karanlıkta yürüttü.'),
(2003668,68,25,3,3,'Evet, dönüp dönüp bütün gün bana elini kaldırıyor.'),
(2003669,68,25,3,4,'Etimi, derimi yıprattı, kemiklerimi kırdı.'),
(2003670,68,25,3,5,'Beni kuşattı, 2 Acı ve zahmetle sardı çevremi.'),
(2003671,68,25,3,6,'Çoktan ölmüş ölüler gibi 2 Beni karanlıkta yaşattı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003672,68,25,3,7,'Çevreme duvar çekti, dışarı çıkamıyorum, 2 Zincirimi ağırlaştırdı.'),
(2003673,68,25,3,8,'Feryat edip yardım isteyince de 2 Duama set çekiyor.'),
(2003674,68,25,3,9,'Yontma taşlarla yollarımı kesti, 2 Dolaştırdı yollarımı.'),
(2003675,68,25,3,10,'Benim için O pusuya yatmış bir ayı, 2 Gizlenmiş bir aslandır.'),
(2003676,68,25,3,11,'Yollarımı saptırdı, paraladı, 2 Mahvetti beni.'),
(2003677,68,25,3,12,'Yayını gerdi, okunu savurmak için 2 Beni nişangah olarak dikti.'),
(2003678,68,25,3,13,'Oklarını böbreklerime sapladı.'),
(2003679,68,25,3,14,'Halkımın önünde gülünç düştüm, 2 Gün boyu alay konusu oldum türkülerine.'),
(2003680,68,25,3,15,'Beni acıya doyurdu, 2 Bana doyasıya pelinsuyu içirdi.'),
(2003681,68,25,3,16,'Dişlerimi çakıl taşlarıyla kırdı, 2 Kül içinde diz çöktürdü bana.'),
(2003682,68,25,3,17,'Esenlik yüzü görmedi canım, 2 Mutluluğu unuttum.'),
(2003683,68,25,3,18,'Bu yüzden diyorum ki, 2 ‹‹Dermanım tükendi, 2 RABden umudum kesildi.››'),
(2003684,68,25,3,19,'Acımı, başıboşluğumu, 2 Pelinotuyla ödü anımsa!'),
(2003685,68,25,3,20,'Hâlâ onları düşünmekte 2 Ve sıkılmaktayım.'),
(2003686,68,25,3,21,'Ama şunu anımsadıkça umutlanıyorum:'),
(2003687,68,25,3,22,'RABbin sevgisi hiç tükenmez, 2 Merhameti asla son bulmaz; sayesinde yok olmadık.››'),
(2003688,68,25,3,23,'Her sabah tazelenir onlar, 2 Sadakatin büyüktür.'),
(2003689,68,25,3,24,'‹‹Benim payıma düşen RABdir›› diyor canım, 2 ‹‹Bu yüzden Ona umut bağlıyorum.››'),
(2003690,68,25,3,25,'RAB kendisini bekleyenler, 2 Onu arayan canlar için iyidir.'),
(2003691,68,25,3,26,'RABbin kurtarışını sessizce beklemek iyidir.'),
(2003692,68,25,3,27,'İnsan için boyunduruğu gençken taşımak iyidir.'),
(2003693,68,25,3,28,'RAB insana boyunduruk takınca, 2 İnsan tek başına oturup susmalı;'),
(2003694,68,25,3,29,'Umudunu kesmeden yere kapanmalı,'),
(2003695,68,25,3,30,'Kendisine vurana yanağını dönüp 2 Utanca doymalı;'),
(2003696,68,25,3,31,'Çünkü Rab kimseyi sonsuza dek geri çevirmez.'),
(2003697,68,25,3,32,'Dert verse de, 2 Büyük sevgisinden ötürü yine merhamet eder;'),
(2003698,68,25,3,33,'Çünkü isteyerek acı çektirmez, 2 İnsanları üzmez.'),
(2003699,68,25,3,34,'Ülkedeki bütün tutsakları ayak altında ezmeyi,'),
(2003700,68,25,3,35,'Yüceler Yücesinin huzurunda insan hakkını saptırmayı,'),
(2003701,68,25,3,36,'Davasında insana haksızlık etmeyi 2 Rab doğru görmez.'),
(2003702,68,25,3,37,'Rab buyurmadıkça kim bir şey söyler de yerine gelir?'),
(2003703,68,25,3,38,'İyilikler gibi felaketler de Yüceler Yücesinin ağzından çıkmıyor mu?'),
(2003704,68,25,3,39,'İnsan, yaşayan insan 2 Niçin günahlarının cezasından yakınır?'),
(2003705,68,25,3,40,'Davranışlarımızı sınayıp gözden geçirelim, 2 Yine RABbe dönelim.'),
(2003706,68,25,3,41,'Ellerimizin yanısıra yüreklerimizi de göklerdeki Tanrıya açalım:'),
(2003707,68,25,3,42,'‹‹Biz karşı çıkıp başkaldırdık, 2 Sen bağışlamadın.'),
(2003708,68,25,3,43,'Öfkeyle örtünüp bizi kovaladın, 2 Acımadan öldürdün.'),
(2003709,68,25,3,44,'Dualar sana erişmesin diye 2 Bulutları örtündün.'),
(2003710,68,25,3,45,'Uluslar arasında bizi pisliğe, süprüntüye çevirdin.'),
(2003711,68,25,3,46,'Düşmanlarımızın hepsi bizimle alay etti.'),
(2003712,68,25,3,47,'Dehşet ve çukur, kırgın ve yıkım çıktı önümüze.››'),
(2003713,68,25,3,48,'Kırılan halkım yüzünden 2 Gözlerimden sel gibi yaşlar akıyor.'),
(2003714,68,25,3,49,'Durup dinmeden yaş boşanıyor gözümden,'),
(2003715,68,25,3,50,'RAB göklerden bakıp görünceye dek.'),
(2003716,68,25,3,51,'Kentimdeki kızların halini gördükçe 2 Yüreğim sızlıyor.'),
(2003717,68,25,3,52,'Boş yere bana düşman olanlar bir kuş gibi avladılar beni.'),
(2003718,68,25,3,53,'Beni sarnıca atıp öldürmek istediler, 2 Üzerime taş attılar.'),
(2003719,68,25,3,54,'Sular başımdan aştı, ‹‹Tükendim›› dedim.'),
(2003720,68,25,3,55,'Sarnıcın dibinden seni adınla çağırdım, ya RAB;'),
(2003721,68,25,3,56,'Sesimi, ‹‹Ahıma, çağrıma kulağını kapama!›› dediğimi duydun.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003722,68,25,3,57,'Seni çağırınca yaklaşıp, ‹‹Korkma!›› dedin.'),
(2003723,68,25,3,58,'Davamı sen savundun, ya Rab, 2 Canımı kurtardın.'),
(2003724,68,25,3,59,'Bana yapılan haksızlığı gördün, ya RAB, 2 Davamı sen gör.'),
(2003725,68,25,3,60,'Benden nasıl öç aldıklarını, 2 Bana nasıl dolap çevirdiklerini gördün.'),
(2003726,68,25,3,61,'Aşağılamalarını, ya RAB, 2 Çevirdikleri bütün dolapları, 2 Bana saldıranların dediklerini, 2 Gün boyu söylendiklerini duydun.'),
(2003727,68,25,3,63,'Oturup kalkışlarına bak, 2 Alay konusu oldum türkülerine.'),
(2003728,68,25,3,64,'Yaptıklarının karşılığını ver, ya RAB.'),
(2003729,68,25,3,65,'İnat etmelerini sağla, 2 Lanetin üzerlerinden eksilmesin.'),
(2003730,68,25,3,66,'Göklerinin altından öfkeyle kovala, yok et onları, ya RAB.'),
(2003731,68,25,4,1,'Altın nasıl donuklaştı, 2 Saf altın nasıl değişti! 2 Kutsal taşlar sokak başlarına dağılmış.'),
(2003732,68,25,4,2,'Değerleri saf altınla ölçülen Siyon çocukları 2 Nasıl çömlekçi işi, toprak testi yerine sayılır oldu!'),
(2003733,68,25,4,3,'Çakallar bile meme verip yavrularını emzirir, 2 Ama halkım çöldeki devekuşları kadar acımasız oldu.'),
(2003734,68,25,4,4,'Susuzluktan emzikteki bebeklerin dili damağına yapışıyor, 2 Çocuklar ekmek istiyor, veren yok.'),
(2003735,68,25,4,5,'Onlar ki, yemeğin en iyisini yerlerdi, 2 Sokaklarda perişan oldular; 2 Onlar ki, al giysiler içinde büyüdüler, 2 Çöp yığınlarını kapışır oldular.'),
(2003736,68,25,4,6,'Halkımın suçu el değmeden, bir anda yıkılan 2 Sodomun günahından daha büyüktür.'),
(2003737,68,25,4,7,'Beyleri kardan temiz, sütten aktılar, 2 Bedence mercandan kızıl, laciverttaşı kadar biçimliydiler.'),
(2003738,68,25,4,8,'Şimdiyse görünüşleri kömürden kara, 2 Sokaklarda tanınmaz oldular. 2 Bir deri bir kemiğe döndüler, odun gibi kurudular.'),
(2003739,68,25,4,9,'Kılıçla öldürülenler kıtlıktan ölenlerden mutludur, 2 Çünkü kıtlıktan ölenler tarla ürününün yokluğundan yıpranarak erimekteler.'),
(2003740,68,25,4,10,'Merhametli kadınlar çocuklarını elleriyle pişirdiler, 2 Halkım kırılırken yiyecek oldu bu kendilerine.'),
(2003741,68,25,4,11,'RAB öfkesini boşalttı, kızgın öfkesini döktü, 2 Temellerini yiyip bitiren ateşi Siyonun içinde tutuşturdu.'),
(2003742,68,25,4,12,'Dünyadaki kralların ve insanların hiçbiri 2 Yeruşalim kapılarından hasımların, düşmanların gireceğine inanmazdı.'),
(2003743,68,25,4,13,'Peygamberlerinin günahı, kâhinlerinin suçu yüzündendi bu, 2 Çünkü onlar kentin ortasında doğruların kanını döktüler.'),
(2003744,68,25,4,14,'Sokaklarda körler gibi dolaşıyorlar, 2 Kanla kirlendikleri için kimse giysilerine dokunamıyor.'),
(2003745,68,25,4,15,'‹‹Çekilin! Kirliler!›› diye bağırdılar onlara, 2 ‹‹Çekilin! Çekilin! Dokunmayın!›› 2 Kaçıp başıboş dolaştıklarında, 2 Öteki uluslar, ‹‹Artık burada kalmasınlar›› dediler.'),
(2003746,68,25,4,16,'RAB kendisi dağıttı onları, 2 Artık yüzlerine bakmayacak. 2 Kâhinleri saymadılar, yaşlılara acımadılar.'),
(2003747,68,25,4,17,'Boş yere yardım beklemekten gözlerimizin feri sönüyor, 2 Gözetleme kulesinde bizi kurtaramayacak bir ulusu bekledikçe bekledik.'),
(2003748,68,25,4,18,'İzlerimizi sürüyorlar, 2 Sokaklarımızda gezemez olduk. 2 Sonumuz yaklaştı, günlerimiz tükendi, 2 Çünkü sonumuz geldi.'),
(2003749,68,25,4,19,'Bizi kovalayanlar gökteki kartallardan çevikti, 2 Dağların üstünde kovaladılar bizi, 2 Çölde bize pusu kurdular.'),
(2003750,68,25,4,20,'Yaşam soluğumuz, 2 RABbin meshettiği kral onların çukurunda yakalandı; 2 Hani onun için, ‹‹Ulusların arasında onun gölgesinde yaşayacağız›› dediğimiz.'),
(2003751,68,25,4,21,'Ûs ülkesinde yaşayan Edom kızı, sevin, coş, 2 Ancak kâse sana da gelecek, sarhoş olup soyunacaksın.'),
(2003752,68,25,4,22,'Ey Siyon kızı, suçunun cezası sona erdi, 2 RAB bir daha seni sürgüne göndermeyecek. 2 Ama, ey Edom kızı, suçun yüzünden seni cezalandırıp günahlarını ortaya çıkaracak.'),
(2003753,68,25,5,1,'Anımsa, ya RAB, başımıza geleni, 2 Bak da utancımızı gör.'),
(2003754,68,25,5,2,'Mülkümüz yabancılara geçti, 2 Evlerimiz ellere.'),
(2003755,68,25,5,3,'Öksüz kaldık, babasız, 2 Annelerimiz dul kadınlara döndü.'),
(2003756,68,25,5,4,'Suyumuzu parayla içtik, 2 Odunumuzu parayla almak zorunda kaldık.'),
(2003757,68,25,5,5,'Bizi kovalayanlar ensemizde, 2 Yorgun düştük, rahatımız yok.'),
(2003758,68,25,5,6,'Ekmek için 2 Mısıra, Asura el açtık.'),
(2003759,68,25,5,7,'Atalarımız günah işledi, 2 Ama artık onlar yok; 2 Suçlarının cezasını biz yüklendik.'),
(2003760,68,25,5,8,'Köleler üstümüzde saltanat sürüyor, 2 Bizi ellerinden kurtaracak kimse yok.'),
(2003761,68,25,5,9,'Çöldeki kılıçlı haydutlar yüzünden 2 Ekmeğimizi canımız pahasına kazanıyoruz.'),
(2003762,68,25,5,10,'Kıtlığın yakıcı sıcağından 2 Derimiz fırın gibi kızardı.'),
(2003763,68,25,5,11,'Siyonda kadınların, 2 Yahuda kentlerinde erden kızların ırzına geçtiler.'),
(2003764,68,25,5,12,'Önderler ellerinden asıldı, 2 Yaşlılar saygı görmedi.'),
(2003765,68,25,5,13,'Değirmen taşını gençler çevirdi, 2 Çocuklar odun yükü altında tökezledi.'),
(2003766,68,25,5,14,'Yaşlılar kent kapısında oturmaz oldu, 2 Gençler saz çalmaz oldu.'),
(2003767,68,25,5,15,'Yüreğimizin sevinci durdu, 2 Oyunumuz yasa döndü.'),
(2003768,68,25,5,16,'Taç düştü başımızdan, 2 Vay başımıza! 2 Çünkü günah işledik.'),
(2003769,68,25,5,17,'Bu yüzden yüreğimiz baygın, 2 Bunlardan ötürü gözlerimiz karardı.'),
(2003770,68,25,5,18,'Viran olan Siyon Dağının üstünde 2 Çakallar geziyor!'),
(2003771,68,25,5,19,'Ama sen, sonsuza dek tahtında oturursun, ya RAB, 2 Egemenliğin kuşaklar boyu sürer.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003772,68,25,5,20,'Niçin bizi hep unutuyorsun, 2 Neden bizi uzun süre terk ediyorsun?'),
(2003773,68,25,5,21,'Bizi kendine döndür, ya RAB, döneriz, 2 Eski günlerimizi geri ver.'),
(2003774,68,25,5,22,'Bizi büsbütün attıysan, 2 Bize çok öfkelenmiş olmalısın.'),
(2003775,68,26,1,1,'Otuzuncu yılda, dördüncü ayın beşinci günü Kevar Irmağı kıyısında sürgünde yaşayanlar arasındayken gökler açıldı, Tanrıdan gelen görümler gördüm.'),
(2003776,68,26,1,2,'Kral Yehoyakinin sürgünlüğünün beşinci yılında, ayın beşinci günü,'),
(2003777,68,26,1,3,'Kildan ülkesinde, Kevar Irmağı kıyısında RAB Buzi oğlu Kâhin Hezekiele seslendi. RABbin eli orada onun üzerindeydi. Hezekielin yaşının otuz olduğu sanılıyor.'),
(2003778,68,26,1,4,'Kuzeyden esen kasırganın göz alıcı bir ışıkla çevrelenmiş, ateş saçan büyük bir bulutla geldiğini gördüm. Ateşin ortası ışıldayan madeni andırıyordu.'),
(2003779,68,26,1,5,'En ortasında insana benzer dört canlı yaratık duruyordu;'),
(2003780,68,26,1,6,'her birinin dört yüzü, dört kanadı vardı.'),
(2003781,68,26,1,7,'Bacakları dimdikti, ayakları buzağı ayağına benziyor ve cilalı tunç gibi parlıyordu.'),
(2003782,68,26,1,8,'Dört yanlarında, kanatların altında insan elleri vardı. Dördünün de yüzleri, kanatları vardı.'),
(2003783,68,26,1,9,'Kanatları birbirine değerek dosdoğru ilerliyor, ilerlerken sağa sola dönmüyordu.'),
(2003784,68,26,1,10,'Her yaratığın dört yüzü vardı: Önde dördünün yüzü insan yüzüne, sağda dördünün aslan yüzüne, solda dördünün öküz yüzüne, arkada dördünün kartal yüzüne benzer bir yüzü vardı.'),
(2003785,68,26,1,11,'Yüzleri böyleydi. Kanatları yukarıya doğru açılmıştı. Her yaratığın iki kanadı yanda öbür yaratıkların kanadına değiyor, iki kanatla da bedenlerini örtüyordu.'),
(2003786,68,26,1,12,'Her biri dosdoğru ilerliyordu. Ruhları onları nereye yönlendirirse, sağa sola sapmadan oraya gidiyorlardı.'),
(2003787,68,26,1,13,'Canlı yaratıkların görünüşü yanan ateş közleri ya da meşale gibiydi. Ateş yaratıkların ortasında hareket ediyordu; ışık saçıyor ve içinden şimşekler çakıyordu.'),
(2003788,68,26,1,14,'Yaratıklar şimşek çakar gibi hızla ileri geri gidip geliyorlardı.'),
(2003789,68,26,1,15,'Bu dört yüzlü yaratıklara bakarken, her birinin yanında, yere değen bir tekerlek gördüm.'),
(2003790,68,26,1,16,'Tekerleklerin görünüşü ve yapısı şöyleydi: Sarı yakut gibi parlıyorlardı ve dördü de birbirine benziyordu. Görünüşleri ve yapılışları iç içe girmiş bir tekerlek gibiydi.'),
(2003791,68,26,1,17,'Hareket edince yaratıkların baktıkları dört yönden birine doğru sağa sola sapmadan ilerliyordu.'),
(2003792,68,26,1,18,'Tekerleklerin kenarı yüksek ve korkunçtu; hepsi çepeçevre gözlerle doluydu.'),
(2003793,68,26,1,19,'Canlı yaratıklar hareket edince, yanlarındaki tekerlekler de hareket ediyordu; yaratıklar yerden yükseldikçe, tekerlekler de onlarla birlikte yükseliyordu.'),
(2003794,68,26,1,20,'Ruhları onları nereye yönlendirirse oraya gidiyorlardı. Tekerlekler de onlarla birlikte yükseliyordu. Çünkü yaratıkların ruhu tekerleklerdeydi.'),
(2003795,68,26,1,21,'Yaratıklar hareket ettiğinde onlar da hareket ediyor, yaratıklar durduğunda onlar da duruyor, yaratıklar yerden yükseldiğinde onlar da yükseliyordu. Çünkü yaratıkların ruhu tekerleklerdeydi.'),
(2003796,68,26,1,22,'Kubbeye benzer, billur gibi parlak ve korkunç bir şey canlı yaratıkların başları üzerine yayılmıştı.'),
(2003797,68,26,1,23,'Kubbenin altında kanatlarının biri öbürünün kanatlarına doğru açılmıştı. Her birinin bedenini örten başka iki kanadı vardı.'),
(2003798,68,26,1,24,'Yaratıklar hareket edince, kanatlarının çıkardığı sesi duydum. Gürül gürül akan suların çağıltısını, Her Şeye Gücü Yetenin sesini, bir ordunun gürültüsünü ansıtıyordu. Durunca kanatlarını indiriyorlardı.'),
(2003799,68,26,1,25,'Kanatları inik dururken, başları üzerindeki kubbeden bir ses duyuldu.'),
(2003800,68,26,1,26,'Başları üzerindeki kubbenin üstünde laciverttaşından yapılmış tahta benzer bir nesne vardı. Yüksekte, tahtı andıran nesnede insana benzer biri oturuyordu.'),
(2003801,68,26,1,27,'Gördüm ki, beli andıran kısmının yukarısı içi ateş dolu maden gibi ışıldıyordu, belden aşağısı ateşe benziyordu ve çevresi göz alıcı bir ışıkla kuşatılmıştı.'),
(2003802,68,26,1,28,'Görünüşü yağmurlu bir gün bulutların arasında oluşan gökkuşağına benziyordu. Öyleydi çevresini saran parlaklık. RAB''bin görkemini andıran olayın görünüşü böyleydi. Görünce, yüzüstü yere yığıldım, birinin konuştuğunu duydum.'),
(2003803,68,26,2,1,'Bana, ‹‹Ey insanoğlu, ayağa kalk, seninle konuşacağım›› dedi.'),
(2003804,68,26,2,2,'O benimle konuşur konuşmaz Ruh içime girdi, beni ayaklarımın üzerinde durdurdu; benimle konuşanı duydum.'),
(2003805,68,26,2,3,'Bana, ‹‹Ey insanoğlu, seni İsrail halkına, bana başkaldıran o asi ulusa gönderiyorum›› dedi, ‹‹Onlar ve ataları bugüne kadar bana karşı geldiler.'),
(2003806,68,26,2,4,'Bu halk dikbaşlı ve inatçıdır. Seni onlara gönderiyorum. Onlara, ‹Egemen RAB şöyle diyor› diyeceksin.'),
(2003807,68,26,2,5,'Bu asi halk seni ister dinlesin, ister dinlemesin, yine de aralarında bir peygamber olduğunu bilecektir.'),
(2003808,68,26,2,6,'Sen, ey insanoğlu, onlardan ve sözlerinden korkma! Çevrende çalılar, dikenler olsa, akrepler arasında yaşasan bile korkma. Asi bir halk olsalar bile, onların söyleyeceklerinden korkma, onlar yüzünden yılgınlığa düşme.'),
(2003809,68,26,2,7,'Seni ister dinlesinler, ister dinlemesinler, onlara sözlerimi söyleyeceksin. Çünkü onlar asi bir halktır.'),
(2003810,68,26,2,8,'Sen, ey insanoğlu, sana söyleyeceğimi dinle! Bu başkaldıran halk gibi asi olma! Ağzını aç, sana vereceğimi ye!››'),
(2003811,68,26,2,9,'Baktım, bana doğru uzanmış bir el gördüm; içinde tomar halinde bir kitap vardı.'),
(2003812,68,26,2,10,'Tomarı önümde açtı, her iki yanı da yazılıydı. Orada ağıtlar, iniltiler, figanlar yazılıydı.'),
(2003813,68,26,3,1,'Bana, ‹‹Ey insanoğlu, sana verileni ye. Bu tomarı yedikten sonra git, İsrail halkına seslen›› dedi.'),
(2003814,68,26,3,2,'Böylece ağzımı açtım, yemem için tomarı bana verdi.'),
(2003815,68,26,3,3,'Bana, ‹‹Ey insanoğlu, sana verdiğim tomarı ye, mideni onunla doldur›› dedi. Bunun üzerine tomarı yedim. Bal gibi tatlı geldi bana.'),
(2003816,68,26,3,4,'Sonra şöyle dedi: ‹‹Ey insanoğlu, İsrail halkına git, onlara sözlerimi ilet.'),
(2003817,68,26,3,5,'Çünkü seni konuşması anlaşılmaz, dili zor bir halka değil, İsrail halkına gönderiyorum.'),
(2003818,68,26,3,6,'Evet, seni konuşması anlaşılmaz, dili zor, dediklerini anlamadığın halklara göndermiyorum. Onlara gönderseydim, seni dinlerlerdi.'),
(2003819,68,26,3,7,'İsrail halkı seni dinlemek istemeyecektir, çünkü o beni dinlemek istemiyor. Bütün İsrail halkı dikbaşlı ve inatçıdır.'),
(2003820,68,26,3,8,'Seni onlar kadar inatçı yapacağım, senin alnını onlarınki kadar katılaştıracağım.'),
(2003821,68,26,3,9,'Alnını çakmak taşından daha sert bir kaya gibi yapacağım. Her ne kadar asi bir halksalar da onlardan korkma, yılma.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003822,68,26,3,10,'Bana, ‹‹Ey insanoğlu, iyice dinle ve sana söyleyeceklerimi yüreğine yerleştir›› dedi,'),
(2003823,68,26,3,11,'‹‹Şimdi sürgünde yaşayan halkına git ve seni ister dinlesinler, ister dinlemesinler, onlara, ‹Egemen RAB şöyle diyor› de.››'),
(2003824,68,26,3,12,'Sonra Ruh beni kaldırdı ve arkamda, ‹‹RABbin görkemine kendi yerinde övgüler olsun!›› diye büyük bir gürleme duydum.'),
(2003825,68,26,3,13,'Canlı yaratıkların birbirine çarpan kanatlarının çıkardığı sesi, yanlarındaki tekerleklerin gürültüsünü, büyük bir gürleme duydum.'),
(2003826,68,26,3,14,'Ruh beni kaldırıp götürdü. RABbin güçlü eli üzerimde olduğu halde, üzüntüyle, öfkeyle gittim.'),
(2003827,68,26,3,15,'Kevar Irmağı kıyısındaki Tel-Abibde yaşayan sürgünlerin yanına geldim. Orada, yaşadıkları yerde onların arasında şaşkınlık içinde yedi gün kaldım.'),
(2003828,68,26,3,16,'Yedi gün sonra RAB bana şöyle seslendi:'),
(2003829,68,26,3,17,'‹‹İnsanoğlu, seni İsrail halkına bekçi atadım. Benden bir söz duyar duymaz onları benim yerime uyaracaksın.'),
(2003830,68,26,3,18,'Kötü kişiye, ‹Kesinlikle öleceksin› dediğim zaman onu uyarmaz, yaşamını kurtarmak amacıyla onu kötü yolundan döndürmek için konuşmazsan, o kişi günahı içinde ölecek; ama onun kanından seni sorumlu tutacağım.'),
(2003831,68,26,3,19,'Ancak kötü kişiyi uyardığın halde kötülüğünden ve kötü yolundan dönmezse, o günahı içinde ölecek. Ama sen canını kurtarmış olacaksın.'),
(2003832,68,26,3,20,'‹‹Doğru kişi doğruluğundan döner de kötülük yaparsa, onu yıkıma uğratacağım, o da ölecek. Onu uyarmadığın için günahı içinde ölecek, yaptığı doğru işler anılmayacak. Ancak onun kanından seni sorumlu tutacağım.'),
(2003833,68,26,3,21,'Ama doğru kişiyi günah işlemesin diye uyarırsan, o da günah işlemezse, kesinlikle yaşayacak. Çünkü o uyarılara kulak vermiştir; sen de canını kurtarmış olacaksın.››'),
(2003834,68,26,3,22,'RABbin eli orada üzerimdeydi. Bana, ‹‹Kalk, ovaya git›› dedi, ‹‹Orada seninle konuşacağım.››'),
(2003835,68,26,3,23,'Böylece kalkıp ovaya gittim. RABbin görkemi tıpkı Kevar Irmağı kıyısında gördüğüm gibi orada durmaktaydı. Yüzüstü yere yığıldım.'),
(2003836,68,26,3,24,'Ruh içime girdi, beni ayaklarımın üzerinde durdurdu. Benimle şöyle konuştu: ‹‹Git, evine kapan.'),
(2003837,68,26,3,25,'Halkın arasına çıkmaman için seni halatlarla bağlayacaklar, ey insanoğlu.'),
(2003838,68,26,3,26,'Dilini damağına yapıştıracağım; konuşmayacak, onları paylayamayacaksın. Çünkü bu halk asidir.'),
(2003839,68,26,3,27,'Ama seninle konuştuğumda dilini çözeceğim. Onlara, ‹Egemen RAB şöyle diyor› diyeceksin. Dinleyen dinlesin, dinlemeyen dinlemesin. Çünkü bu halk asidir.››'),
(2003840,68,26,4,1,'‹‹Sen, ey insanoğlu, bir tuğla al, önüne koy, üzerine Yeruşalim Kentini çiz.'),
(2003841,68,26,4,2,'Kenti kuşat, duvarla çevir. Kente karşı toprak rampalar yap, ordugah kur, çevresine kütükler yerleştir.'),
(2003842,68,26,4,3,'Sonra demir bir sac al; demirden bir duvar gibi kendinle kentin arasına koy. Yüzünü ona doğru çevir. Kent kuşatma altında tutulacak, onu sen kuşatacaksın. Bu İsrail halkı için bir belirti olacak.'),
(2003843,68,26,4,4,'‹‹Sonra sol yanına uzan, İsrail halkının günahını yüklen. Sol yanına uzanacağın günler kadar onların suçunun cezasını çekeceksin.'),
(2003844,68,26,4,5,'Suçlarının yıl sayısı kadar sana gün ayırdım. Böylece üç yüz doksan gün İsrail halkının suçunun cezasını çekeceksin.'),
(2003845,68,26,4,6,'‹‹Bunu yaptıktan sonra, bu kez sağ yanına uzan, Yahuda halkının suçunun cezasını çek. Sana kırk gün, her yıl için bir gün ayırdım.'),
(2003846,68,26,4,7,'Yüzünü Yeruşalim kuşatmasına çevir, çıplak kollarını kaldırıp Yeruşalime karşı peygamberlik et.'),
(2003847,68,26,4,8,'Kuşatma günlerini bitirinceye dek bir yandan öbür yana dönmemen için seni halatlarla bağlayacağım.'),
(2003848,68,26,4,9,'‹‹Buğday, arpa, bakla, mercimek, darı, kızıl buğday al, bir kaba koy. Bunlardan kendine ekmek yap. Bir yanına uzanacağın üç yüz doksan gün boyunca bu ekmekten yiyeceksin.'),
(2003849,68,26,4,10,'Her gün belirli zamanda yemen için yirmi şekel ekmek tartacaksın.'),
(2003850,68,26,4,11,'Bunun gibi suyu da belirli zamanda, ölçüyle, bir hinin altıda biri kadar içeceksin.'),
(2003851,68,26,4,12,'Yiyeceğini arpa pidesi yer gibi ye ve insan dışkısından ateş yakıp üzerinde halkın gözü önünde pişir.››'),
(2003852,68,26,4,13,'RAB, ‹‹Uluslar arasına dağıtacağım İsrail halkı böylelikle kirli sayılan yiyecekleri yiyecek›› dedi.'),
(2003853,68,26,4,14,'Ben, ‹‹Eyvah, ey Egemen RAB!›› diye karşılık verdim, ‹‹Hiçbir zaman kirli sayılan bir şeye dokunmadım. Gençliğimden bu yana kendiliğinden ölmüş ya da yabanıl bir hayvan tarafından öldürülmüş bir hayvanın etini yemedim, ağzıma kirli sayılan et koymadım.››'),
(2003854,68,26,4,15,'‹‹Peki›› dedi, ‹‹Ekmeğini insan dışkısı yerine tezek yakıp üzerinde pişirmene izin vereceğim.››'),
(2003855,68,26,4,16,'Sonra, ‹‹İnsanoğlu, Yeruşalimi her türlü yiyecekten yoksun bırakacağım›› dedi, ‹‹Bu halk yiyeceğini tartıyla ve kaygı içinde yiyecek, suyunu ölçüyle ve şaşkınlık içinde içecek.'),
(2003856,68,26,4,17,'Yiyeceği de suyu da azalacak. Hepsi şaşkınlığa düşecek, günahları içinde eriyip yok olacak.'),
(2003857,68,26,5,1,'‹‹Ey insanoğlu, keskin bir kılıç al, berber usturası gibi kullanarak başını, sakalını tıraş et. Sonra bir terazi getir, kılları bölümlere ayır.'),
(2003858,68,26,5,2,'Yeruşalimin kuşatılması bitince, kılların üçte birini kentin ortasında yakacaksın. Üçte birini kılıçla kentin çevresine fırlatacak, kalan üçte birini de rüzgara savuracaksın. Ben de yalın kılıç onların peşine düşeceğim.'),
(2003859,68,26,5,3,'Birkaç tel kıl bırak, giysinin kıvrımlarına tak.'),
(2003860,68,26,5,4,'Yine birkaçını alıp ateşe at, yansın. O kıllardan bütün İsrail halkına ateş yayılacak.'),
(2003861,68,26,5,5,'‹‹Egemen RAB diyor ki: Bu Yeruşalimi ulusların ortasına yerleştirdim, çevresini ülkelerle kuşattım.'),
(2003862,68,26,5,6,'Öyleyken Yeruşalim çevresindeki bütün uluslardan ve ülkelerden daha çok kötülük yaparak ilkelerimi, kurallarımı çiğnedi. İlkelerime karşı geldi, kurallarım uyarınca davranmadı.'),
(2003863,68,26,5,7,'Bundan ötürü Egemen RAB diyor ki: Çevrenizde yaşayan uluslardan daha azgındınız, kurallarımı izlemediniz, ilkelerime uymadınız. Çevrenizde yaşayan ulusların ilkelerine de uymadınız.'),
(2003864,68,26,5,8,'‹‹Bundan ötürü Egemen RAB diyor ki: İşte ben size karşıyım, ulusların gözü önünde sizi cezalandıracağım.'),
(2003865,68,26,5,9,'Yaptığınız bütün iğrençlikler yüzünden önceden yapmadığımı, bir daha yapmayacağımı size yapacağım.'),
(2003866,68,26,5,10,'Böylece aranızda babalar çocuklarını, çocuklar da babalarını yiyecekler. Sizi cezalandıracağım, sağ kalanlarınızı her yana dağıtacağım.'),
(2003867,68,26,5,11,'Egemen RAB varlığım hakkı için diyor, madem tapınağımı iğrenç put ve uygulamalarınızla kirlettiniz, ben de sizi esirgemeyecek, size acımayacak, sizi kayırmayacağım.'),
(2003868,68,26,5,12,'Kentte yaşayanlarınızın üçte biri salgın hastalık ya da kıtlık yüzünden yok olacak; üçte biriniz çevrede kılıçtan geçirilecek; üçte birinizi de her yana dağıtıp yalın kılıç peşinize düşeceğim.'),
(2003869,68,26,5,13,'‹‹Böylece kızgınlığım son bulacak, onlara karşı öfkemi yatıştıracağım. O zaman ben de rahata kavuşacağım. Öfkemi onların üzerine boşaltınca, ben RABbin kıskançlığımdan onlarla konuştuğumu anlayacaklar.'),
(2003870,68,26,5,14,'‹‹Çevrenizdeki uluslar arasında, yoldan her geçenin gözü önünde sizi yıkıma uğratacak, aşağılayacağım.'),
(2003871,68,26,5,15,'Öfke, kızgınlık ve acı paylamalarla sizi cezalandırdığımda çevrenizdeki uluslar arasında alay konusu olacak, aşağılanacaksınız; ders alınacak, şaşılacak bir duruma düşeceksiniz. Ben, RAB bunu söyledim.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003872,68,26,5,16,'Sizi yok etmek için üzerinize öldürücü, yıkıcı kıtlık oklarını salacağım. Üzerinize salacağım kıtlığı daha da artıracak, sizi her türlü yiyecekten yoksun bırakacağım.'),
(2003873,68,26,5,17,'Üzerinize kıtlık ve yabanıl hayvanlar salacağım, sizi çocuklarınızdan edecekler. Salgın hastalık ve dökülen kan sizi süpürüp yok edecek; başınıza da kılıç getireceğim. Ben, RAB böyle söyledim.››'),
(2003874,68,26,6,1,'RAB bana şöyle seslendi:'),
(2003875,68,26,6,2,'‹‹Ey insanoğlu, yüzünü İsrail dağlarına doğru çevir ve onlara karşı peygamberlik et.'),
(2003876,68,26,6,3,'De ki, ‹Ey İsrail dağları, Egemen RABbin sözünü dinleyin. Egemen RAB dağlara, tepelere, vadilere, derelere şöyle diyor: Üzerinize kılıç göndereceğim, tapınma yerlerinizi yıkacağım.'),
(2003877,68,26,6,4,'Sunaklarınızı devirecek, buhur sunaklarınızı paramparça edeceğim. Kılıçtan geçirilmiş halkınızı putlarınızın önüne düşüreceğim.'),
(2003878,68,26,6,5,'İsraillilerin cesetlerini putlarının önüne atacak, kemiklerini sunaklarının çevresine dağıtacağım.'),
(2003879,68,26,6,6,'Yaşadığınız her yerde kentleriniz yakılıp yıkılacak, tapınma yerleriniz yerle bir edilecek. Öyle ki, sunaklarınız devrilip yıkılsınfç, putlarınız ezilip paramparça olsun, buhur sunaklarınız yok edilsin, el emeğiniz boşa çıksın.'),
(2003880,68,26,6,7,'Halkınız her yerde öldürülecek. O zaman benim RAB olduğumu anlayacaksınız. ‹‹Suçlu çıkarılsın››.'),
(2003881,68,26,6,8,'‹‹ ‹Birkaç kişiyi ölümden kurtaracağım. Ülkelere, uluslar arasına dağılan bazılarınız kılıçtan kurtulacak.'),
(2003882,68,26,6,9,'Kurtulanlar tutsak alındıkları uluslarda beni anımsayacaklar. Benden dönen sadakatsiz yüreklerinden, putları ardınca şehvete sürükleyen gözlerinden derin acı duydum. Yaptıkları kötülükler ve iğrenç uygulamalar yüzünden kendilerinden tiksinecekler.'),
(2003883,68,26,6,10,'Benim RAB olduğumu, başlarına bu felaketi getireceğimi boşuna söylemediğimi anlayacaklar.'),
(2003884,68,26,6,11,'‹‹ ‹Egemen RAB şöyle diyor: Ellerinizi çırpın, ayaklarınızı yere vurun, İsrail halkının bütün kötü ve iğrenç uygulamalarından ötürü inleyin! Çünkü kılıçla, kıtlıkla, salgın hastalıkla yok olacaklar.'),
(2003885,68,26,6,12,'Uzaktakiler salgın hastalıktan ölecek, yakındakiler kılıçtan geçirilecek, kuşatma sırasında sağ kalanlar kıtlıktan ölecek. Böylece onlara duyduğum öfkeye son vereceğim.'),
(2003886,68,26,6,13,'Putlarının arasına, sunaklarının çevresine, her yüksek tepeye, dağ doruğuna, her yeşeren bol yapraklı ağacın altına cesetleri serilince, benim RAB olduğumu anlayacaklar. Oralarda putlarına güzel kokulu buhur sundular.'),
(2003887,68,26,6,14,'Elimi onlara karşı uzatacak, çölden Rivla''ya kadar yaşadıkları ülkeyi yerle bir edip ıssız bırakacağım. O zaman benim RAB olduğumu anlayacaklar.› ››'),
(2003888,68,26,7,1,'RAB bana şöyle seslendi:'),
(2003889,68,26,7,2,'‹‹Ey insanoğlu, Egemen RAB İsrail ülkesine şöyle diyor: Son yaklaştı! Ülkenin dört köşesinin sonu geldi.'),
(2003890,68,26,7,3,'Senin de sonun geldi! Senin üzerine öfkemi yağdıracağım. Yaptıklarına göre seni yargılayacak, bütün iğrenç uygulamalarının karşılığını vereceğim.'),
(2003891,68,26,7,4,'Sana acımayacak, seni esirgemeyeceğim. Yaptıklarının ve sendeki iğrenç uygulamaların karşılığını vereceğim. O zaman benim RAB olduğumu anlayacaksınız.'),
(2003892,68,26,7,5,'‹‹Egemen RAB şöyle diyor: Yıkım! İşte duyulmamış bir yıkım geliyor.'),
(2003893,68,26,7,6,'Sonun geldi! Evet, sonun geldi! Sana karşı uyanıyor. İşte geliyor.'),
(2003894,68,26,7,7,'Ey ülkede yaşayan halk, yıkıma uğrayacaksın. Yıkım zamanı yaklaştı! Gün yakın! Dağların üzerinden sevinç sesi yerine kargaşa sesi geliyor.'),
(2003895,68,26,7,8,'Çok yakında kızgınlığımı üzerine boşaltacak, sana duyduğum öfkeyi üzerine dökeceğim. Yaptıklarına göre seni yargılayacak, bütün iğrenç uygulamalarının karşılığını vereceğim.'),
(2003896,68,26,7,9,'Sana acımayacak, seni esirgemeyeceğim. Yaptıklarının ve sendeki iğrenç uygulamaların karşılığını vereceğim. O zaman seni cezalandıranın ben RAB olduğumu anlayacaksın.'),
(2003897,68,26,7,10,'‹‹İşte o gün! Gün yaklaştı! Yıkım hazır. Değnek çiçeklendi, gurur tomurcuklandı.'),
(2003898,68,26,7,11,'Zorbalık ayaklanıp kötülüğün sopası oldu. Halktan, o kalabalıktan kimse kalmayacak; mallarından, görkemlerinden bir şey kalmayacak.'),
(2003899,68,26,7,12,'‹‹Son yaklaştı! Gün geldi! Alıcı sevinmesin, satıcı üzülmesin. Çünkü öfkem bütün halkın üzerine yağacak.'),
(2003900,68,26,7,13,'Satıcı yaşadığı sürece sattığını geri alamayacak. Çünkü herkesi ilgilendiren bu görüm değiştirilmeyecek. İşlediği günahlar yüzünden kimse canını koruyamayacak.'),
(2003901,68,26,7,14,'Borazan çalındı, herkes hazır, ama kimse savaşa gitmeyecek. Çünkü öfkem bütün halkın üzerindedir.'),
(2003902,68,26,7,15,'‹‹İşte dışarda kılıç, içerde salgın hastalık ve kıtlık. Kentin dışındakiler kılıçla öldürülecek, kenttekilerse kıtlıktan, salgın hastalıktan yok olacak.'),
(2003903,68,26,7,16,'Sağ kalanlar vadilerdeki güvercinler gibi dağlara kaçacak; her biri günahından ötürü inleyecek.'),
(2003904,68,26,7,17,'Eller gevşeyecek, dizler titreyecek.'),
(2003905,68,26,7,18,'Çul kuşanacak, dehşete düşecekler. Yüzleri utançtan kızaracak, başları tıraş edilecek.'),
(2003906,68,26,7,19,'Gümüşlerini sokağa atacaklar. Altınları kirli sayılacak. RABbin öfkesini boşalttığı gün onları ne altınları, ne gümüşleri kurtarabilir. Bunlarla ne açlıklarını giderebilir, ne karınlarını doyurabilirler. Altın ve gümüş onları suça sürükledi.'),
(2003907,68,26,7,20,'Mücevherlerinin güzelliğiyle gururlanırlardı. İğrenç, tiksindirici putlarını bunlardan yaptılar. Bu yüzden mücevherlerini kirli bir nesneye çevireceğim.'),
(2003908,68,26,7,21,'Hepsini yağma mal olarak yabancı uluslara, ganimet olarak dünyadaki kötülere vereceğim; onları kirletecekler.'),
(2003909,68,26,7,22,'Yüzümü onlardan çevireceğim. Değerli tapınağımı kirletecekler; zorbalar içeri girip orayı kirletecekler.'),
(2003910,68,26,7,23,'‹‹Kendinize zincirler hazırlayın! Ülkede kan akıtılıyor, kent zorbalık dolu.'),
(2003911,68,26,7,24,'Ulusların en kötülerini buraya getireceğim; evlerinizi mülk edinecekler. Güçlülerin gururuna son vereceğim. Kutsal yerleri kirletilecek.'),
(2003912,68,26,7,25,'Korku gelince esenlik arayacak, ama bulamayacaklar.'),
(2003913,68,26,7,26,'Yıkım üstüne yıkım gelecek. Kötü haberler birbirini kovalayacak. Peygamberden görüm isteyecekler; kâhin Kutsal Yasayı öğretemeyecek, ileri gelenler öğüt veremeyecek.'),
(2003914,68,26,7,27,'Kral yas tutacak, önder umutsuzluğa düşecek, ülkedeki halkın korkudan elleri titreyecek. Onları yaptıklarına göre cezalandıracak, yargıladıkları gibi yargılayacağım. O zaman benim RAB olduğumu anlayacaklar.››'),
(2003915,68,26,8,1,'Sürgünlüğün altıncı yılı, altıncı ayın beşinci günü evde Yahudanın ileri gelenleriyle otururken Egemen RABbin eli bana dokundu.'),
(2003916,68,26,8,2,'Baktım, insana benzer birini gördüm: Görünüşü, belinden aşağısı ateşi andırıyor, belinden yukarısı maden gibi ışıldıyordu.'),
(2003917,68,26,8,3,'Eli andıran bir şey uzatıp beni saçlarımdan tuttu. Ruh beni yerle gök arasına kaldırdı ve Tanrıdan gelen görümlerde Yeruşalime, iç avlunun kuzeye bakan kapısının giriş bölümüne götürdü. Tanrının kıskançlığını uyandıran kıskançlık putu orada dikiliydi.'),
(2003918,68,26,8,4,'Ovada gördüğüm görümdeki gibi, İsrailin Tanrısının görkemi oradaydı.'),
(2003919,68,26,8,5,'Sonra bana, ‹‹Ey insanoğlu, kuzeye bak!›› dedi. Baktım, sunak kapısının kuzeye bakan giriş bölümünde duran kıskançlık putunu gördüm.'),
(2003920,68,26,8,6,'Bana, ‹‹İnsanoğlu, ne yaptıklarını görüyor musun?›› dedi, ‹‹Tapınağımdan uzaklaşayım diye İsrail halkı çok iğrenç şeyler yapıyor. Bundan daha iğrenç şeyler göreceksin.››'),
(2003921,68,26,8,7,'Beni avlunun giriş bölümüne getirdi. Baktım, duvarda bir delik gördüm.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003922,68,26,8,8,'Bana, ‹‹Haydi duvarı del, insanoğlu›› dedi. Duvarı deldim, orada bir kapı gördüm.'),
(2003923,68,26,8,9,'Bana, ‹‹İçeri gir de burada yaptıkları kötü ve iğrenç şeyleri gör›› dedi.'),
(2003924,68,26,8,10,'Böylece içeriye girip baktım. Duvarın her yanına çeşit çeşit sürüngen, iğrenç hayvan şekilleri ve İsrail halkının bütün putları oyulmuştu.'),
(2003925,68,26,8,11,'İsrail ileri gelenlerinden yetmiş kişiyle Şafan oğlu Yaazanya orada, putların önünde duruyordu. Her birinin elinde bir buhurdan vardı; buhurun kokusu bulut gibi yükseliyordu.'),
(2003926,68,26,8,12,'‹‹İnsanoğlu, İsrail halkının ileri gelenlerinin kendi putlarının odalarında, karanlıkta neler yaptıklarını gördün mü?›› dedi, ‹‹Onlar, ‹RAB bizi görmüyor, RAB ülkeyi bıraktı› diyorlar.››'),
(2003927,68,26,8,13,'Bana yine, ‹‹Daha iğrenç şeyler yaptıklarını da göreceksin›› dedi.'),
(2003928,68,26,8,14,'Bundan sonra beni RABbin Tapınağının kuzeye bakan kapısının giriş bölümüne götürdü. Orada oturup Tammuz için ağlayan kadınları gördüm.'),
(2003929,68,26,8,15,'Bana, ‹‹İnsanoğlu, bunu gördün mü? Bundan daha iğrenç şeyler de göreceksin›› dedi.'),
(2003930,68,26,8,16,'Beni RABbin Tapınağının iç avlusuna götürdü. Tapınağın girişinde, eyvanla sunak arasında yirmi beş kadar adam vardı. Sırtlarını RABbin Tapınağına, yüzlerini doğuya dönmüş, güneşe tapınıyorlardı.'),
(2003931,68,26,8,17,'Bana, ‹‹İnsanoğlu, bunları gördün mü?›› dedi, ‹‹Yahuda halkı burada yaptığı iğrenç şeyler yetmiyormuş gibi, ülkeyi zorbalıkla doldurup beni sürekli öfkelendiriyor. Bak, dalı nasıl burunlarına uzatıyorlar!'),
(2003932,68,26,8,18,'Bundan ötürü onlara öfkeyle davranacak, acımayacağım, onları esirgemeyeceğim. Yüksek sesle beni çağırsalar bile onları dinlemeyeceğim.››'),
(2003933,68,26,9,1,'Sonra yüksek sesle, ‹‹Kenti cezalandıracak olanlar, ellerinde yok edici silahlarıyla buraya gelsin›› diye seslendiğini duydum.'),
(2003934,68,26,9,2,'Kuzeye bakan yukarı kapı yolundan altı kişinin geldiğini gördüm. Her birinin elinde ölümcül bir silah vardı. Aralarında keten giysili, belinde yazı takımı olan bir adam vardı. İçeriye girip tunç sunağın yanında durdular.'),
(2003935,68,26,9,3,'İsrail Tanrısının görkemi bulunduğu yerden, Keruvların üzerinden ayrılıp tapınağın eşiğine gitti. RAB keten giysili, belinde yazı takımı olan adama seslendi:'),
(2003936,68,26,9,4,'‹‹Yeruşalim Kentinin içinden geç, orada yapılan iğrenç şeylerden ötürü dövünüp ağlayanların alınlarına işaret koy›› dedi.'),
(2003937,68,26,9,5,'Öbürlerine, ‹‹Kent boyunca onu izleyin ve kimseye acımadan, kimseyi esirgemeden öldürün›› dediğini duydum.'),
(2003938,68,26,9,6,'‹‹Yaşlıyı, genci, genç kızı, kadını, çocukları öldürün. Yalnız alınlarında işaret olanlara dokunmayın. İşe tapınağımdan başlayın.›› Onlar da tapınağın önünde duran İsrail ileri gelenlerinden işe başladılar.'),
(2003939,68,26,9,7,'Onlara, ‹‹Tapınağı kirletin, avlularını cesetlerle doldurun. Haydi başlayın!›› dedi. Bunun üzerine onlar gidip kenttekileri öldürmeye başladılar.'),
(2003940,68,26,9,8,'Onlar halkı öldürürken ben tek başıma kaldım. Yüzüstü yere kapanıp, ‹‹Ah, ey Egemen RAB! Öfkeni Yeruşalim üzerine boşaltırken, geri kalan bütün İsraillileri de mi yok edeceksin?›› diye haykırdım.'),
(2003941,68,26,9,9,'‹‹İsrail ve Yahuda halkının günahı pek büyük›› diye karşılık verdi, ‹‹Ülke kan, kent haksızlık dolu. Onlar, ‹RAB ülkeyi bıraktı, RAB görmüyor› diyorlar.'),
(2003942,68,26,9,10,'Ben de onlara acımayacak, onları esirgemeyeceğim. Yaptıklarını kendi başlarına getireceğim.››'),
(2003943,68,26,9,11,'Derken keten giysili, belinde yazı takımı olan adam, ‹‹Buyruklarını yerine getirdim›› diye haber verdi.'),
(2003944,68,26,10,1,'Baktım, Keruvların başı üzerindeki kubbenin üzerinde laciverttaşından tahta benzer bir nesne gördüm.'),
(2003945,68,26,10,2,'RAB keten giysili adama, ‹‹Keruvların altındaki tekerleklerin arasına gir. Avuçlarını Keruvların arasındaki ateş közleriyle doldurup kentin üzerine közleri saç›› dedi. Adamın oraya girdiğini gördüm.'),
(2003946,68,26,10,3,'Adam oraya girdiğinde, Keruvlar tapınağın güney tarafında duruyordu. Bulut tapınağın iç avlusunu doldurdu.'),
(2003947,68,26,10,4,'RABbin görkemi Keruvların üzerinden ayrılıp tapınağın eşiğine gitti. Tapınak bulutla doldu. Avlu RABbin görkeminin parıltısıyla doluydu.'),
(2003948,68,26,10,5,'Keruvların kanatlarının sesi dış avludan bile duyuluyordu; tıpkı Her Şeye Gücü Yeten Tanrının sesi gibiydi.'),
(2003949,68,26,10,6,'RAB keten giysili adama, ‹‹Keruvlardan ve tekerleklerin arasından ateş al›› diye buyurunca, adam oraya girip bir tekerleğin yanında durdu.'),
(2003950,68,26,10,7,'Sonra Keruvlardan biri aralarındaki ateşe elini uzattı, biraz ateş alıp keten giysili adamın avuçlarına koydu. Adam ateşi alıp oradan ayrıldı.'),
(2003951,68,26,10,8,'Keruvların kanatları altında insan eline benzer bir şekil göründü.'),
(2003952,68,26,10,9,'Baktım, her Keruvun yanında birer tane olmak üzere dört tekerlek gördüm. Tekerlekler sarı yakut gibi parıldıyordu.'),
(2003953,68,26,10,10,'Dördü de birbirine benziyor, iç içe girmiş bir tekerleği andırıyordu.'),
(2003954,68,26,10,11,'Hareket edince Keruvların baktıkları dört yönden birine doğru, sağa sola dönmeden ilerliyordu. Ön tekerlek nereye yönelirse, öbür tekerlekler de onun ardınca gidiyordu.'),
(2003955,68,26,10,12,'Keruvların bedenleri -sırtları, elleri, kanatları- ve dördünün de tekerlekleri çepeçevre gözlerle doluydu.'),
(2003956,68,26,10,13,'Tekerleklere ‹‹Dönen tekerlekler›› dendiğini duydum.'),
(2003957,68,26,10,14,'Her Keruvun dört yüzü vardı: Birinci yüz öküz yüzüne, ikincisi insan yüzüne, üçüncüsü aslan yüzüne, dördüncüsü kartal yüzüne benziyordu.'),
(2003958,68,26,10,15,'Keruvlar yukarıya doğru yükseldi. Bunlar daha önce Kevar Irmağı kıyısında gördüğüm canlı yaratıklardı.'),
(2003959,68,26,10,16,'Keruvlar hareket edince, yanlarındaki tekerlekler de hareket ediyor, Keruvlar yerden yükselmek için kanatlarını açınca, tekerlekler de yanlarından ayrılmıyordu.'),
(2003960,68,26,10,17,'Keruvlar durduğunda onlar da duruyor, Keruvlar yerden yükseldiğinde onlar da yükseliyordu. Çünkü yaratıkların ruhu tekerleklerdeydi.'),
(2003961,68,26,10,18,'RABbin görkemi tapınağın eşiğinden ayrılıp Keruvların üzerinde durdu.'),
(2003962,68,26,10,19,'Ben bakarken Keruvlar kanatlarını açıp yerden yükseldi, tekerlekler de onlarla yükseldi. RABbin Tapınağının Doğu Kapısının girişinde durdular. İsrail Tanrısının görkemi onların üzerindeydi.'),
(2003963,68,26,10,20,'Kevar Irmağı kıyısında, İsrail Tanrısının altında gördüğüm ve Keruvlar olduğunu anladığım canlı yaratıklar bunlardı.'),
(2003964,68,26,10,21,'Her birinin dört yüzü, dört kanadı vardı. Kanatlarının altında insan elini andıran bir şey vardı.'),
(2003965,68,26,10,22,'Yüzleri Kevar Irmağı kıyısında gördüğüm yüzlere benziyordu. Her biri dosdoğru ilerliyordu.'),
(2003966,68,26,11,1,'Ruh beni yine yukarıya kaldırıp RABbin Tapınağının Doğu Kapısına götürdü. Kapının giriş bölümünde yirmi beş adam vardı. Aralarında halkın önderlerinden Azzur oğlu Yaazanyayı, Benaya oğlu Pelatyayı gördüm.'),
(2003967,68,26,11,2,'RAB bana, ‹‹İnsanoğlu, bunlar kötülük tasarlayan ve bu kentte kötü öğüt veren adamlardır›› dedi,'),
(2003968,68,26,11,3,'‹‹Onlar, ‹Yıkım yakın değil, ev yapmanın zamanıdır. Bu kent kazan, biz de etiz› diyorlar.'),
(2003969,68,26,11,4,'Bundan ötürü onları uyar, ey insanoğlu, onları uyar.››'),
(2003970,68,26,11,5,'Sonra RABbin Ruhu üzerime inip şunları söylememi buyurdu: ‹‹RAB şöyle diyor: Ey İsrail halkı, neler söylediğinizi ve neler düşündüğünüzü bilirim.'),
(2003971,68,26,11,6,'Bu kentte birçok kişi öldürdünüz, kentin sokaklarını ölülerle doldurdunuz.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2003972,68,26,11,7,'‹‹Bundan ötürü Egemen RAB şöyle diyor: Oraya attığınız ölüler et, kent de kazandır. Ama sizi kentin dışına süreceğim.'),
(2003973,68,26,11,8,'Kılıçtan korktunuz, ama ben üzerinize kılıç göndereceğim. Egemen RAB böyle diyor.'),
(2003974,68,26,11,9,'Sizi kentten çıkarıp yabancıların eline teslim edeceğim. Sizi cezalandıracağım.'),
(2003975,68,26,11,10,'Kılıçla öldürüleceksiniz. Sizi İsrail sınırında cezalandıracağım. O zaman benim RAB olduğumu anlayacaksınız.'),
(2003976,68,26,11,11,'Bu kent sizin için kazan olmayacak, siz de onun içinde et olmayacaksınız. Sizi İsrail sınırında cezalandıracağım.'),
(2003977,68,26,11,12,'O zaman benim RAB olduğumu anlayacaksınız. Kurallarımı izlemediniz, ilkelerime uymadınız; çevrenizdeki ulusların ilkelerine uydunuz.››'),
(2003978,68,26,11,13,'Ben peygamberlikte bulunurken Benaya oğlu Pelatya öldü. Yüzüstü yere kapanıp, ‹‹Ah, ey Egemen RAB! Geri kalan İsraillileri büsbütün mü yok edeceksin?›› diye yüksek sesle haykırdım.'),
(2003979,68,26,11,14,'RAB bana şöyle seslendi:'),
(2003980,68,26,11,15,'‹‹Ey insanoğlu, Yeruşalimde yaşayanlar senin kardeşlerin, akrabaların ve öbür İsrailliler için, ‹Onlar RABden uzaklar, bu ülke mülk olarak bize verildi› demişler.››'),
(2003981,68,26,11,16,'‹‹Bu yüzden de ki, ‹Egemen RAB şöyle diyor: Onları uzaktaki uluslar arasına gönderdim, ülkeler arasına dağıttım. Öyleyken gittikleri ülkelerde kısa süre için onlara barınak oldum.›'),
(2003982,68,26,11,17,'‹‹De ki, ‹Egemen RAB şöyle diyor: Sizi uluslar arasından toplayacak, dağılmış olduğunuz ülkelerden geri getirecek, İsrail ülkesini yeniden size vereceğim.›'),
(2003983,68,26,11,18,'‹‹Ülkeye dönecek, tiksindirici, iğrenç putları oradan söküp atacaklar.'),
(2003984,68,26,11,19,'Onlara tek bir yürek vereceğim, içlerine yeni bir ruh koyacağım. İçlerindeki taş yüreği çıkarıp onlara etten bir yürek vereceğim.'),
(2003985,68,26,11,20,'O zaman kurallarımı izleyecek, ilkelerime uymaya özen gösterecekler. Onlar halkım olacak, ben de onların Tanrısı olacağım.'),
(2003986,68,26,11,21,'Tiksindirici, iğrenç putlara gönülden yönelenlere gelince, yaptıklarının aynısını başlarına getireceğim. Böyle diyor Egemen RAB.››'),
(2003987,68,26,11,22,'Keruvlar kanatlarını açtı, tekerlekler yanlarında duruyordu. İsrail Tanrısının görkemi onların üzerindeydi.'),
(2003988,68,26,11,23,'RABbin görkemi kentin ortasından yükselip kentin doğusundaki dağa kondu.'),
(2003989,68,26,11,24,'Görümde Tanrının Ruhu beni yukarı kaldırıp Kildan ülkesindeki sürgünlerin yanına götürdü. Sonra gördüğüm görüm kayboldu.'),
(2003990,68,26,11,25,'Ben de RAB''bin bana gösterdiği her şeyi sürgündekilere anlattım.'),
(2003991,68,26,12,1,'RAB bana şöyle seslendi:'),
(2003992,68,26,12,2,'‹‹İnsanoğlu, asi bir halkın arasında yaşıyorsun. Gözleri varken görmüyor, kulakları varken işitmiyorlar. Çünkü bu halk asidir.'),
(2003993,68,26,12,3,'‹‹Sen, insanoğlu, sürgüne gidecekmiş gibi eşyanı topla, onların gözü önünde, gündüzün yola çık, bulunduğun yerden başka bir yere git. Kim bilir, asi bir halk olmalarına karşın seni görüp anlayabilirler.'),
(2003994,68,26,12,4,'Gündüzün, halkın gözü önünde topladığın sürgün eşyanı çıkar. Akşam yine onların gözü önünde sürgüne giden biri gibi yola çık.'),
(2003995,68,26,12,5,'Onlar seni izlerken duvarı delip eşyanı çıkar.'),
(2003996,68,26,12,6,'Seni izlerlerken eşyanı sırtlayıp karanlıkta taşı. Ülkeyi görmemek için yüzünü ört. Çünkü yapacakların İsrail halkı için bir uyarı olacaktır.››'),
(2003997,68,26,12,7,'Bana verilen buyruk uyarınca davrandım. Gündüzün sürgüne gidecekmiş gibi eşyalarımı çıkardım. Akşam elimle duvarı deldim. Eşyalarımı karanlıkta çıkarıp onlar izlerken sırtımda taşıdım.'),
(2003998,68,26,12,8,'Ertesi sabah RAB bana seslendi:'),
(2003999,68,26,12,9,'‹‹İnsanoğlu, o asi İsrail halkı sana, ‹Ne yapıyorsun?› diye sormadı mı?'),
(2004000,68,26,12,10,'‹‹Onlara de ki, ‹Egemen RAB şöyle diyor: Yeruşalimdeki önder ve orada yaşayan bütün İsrail halkına ilişkin bir bildiridir bu.'),
(2004001,68,26,12,11,'Ben sizin için bir uyarıyım› de. Sana yaptığımın tıpkısı onlara da yapılacak. Tutsak olarak sürgüne gidecekler.'),
(2004002,68,26,12,12,'‹‹Onların önderi karanlıkta eşyasını sırtında taşıyarak yola koyulacak. Eşyasını çıkarmak için duvarda bir gedik açacak. Ülkeyi görmemek için yüzünü örtecek.'),
(2004003,68,26,12,13,'Onun üzerine ağımı atacağım, kurduğum tuzağa düşecek. Onu Babile, Kildan ülkesine götüreceğim, ama ülkeyi göremeden orada ölecek.'),
(2004004,68,26,12,14,'Çevresindekilerin tümünü -yardımcılarını, ordusunu- dünyanın dört bucağına dağıtacağım. Yalın kılıç onların peşlerine düşeceğim.'),
(2004005,68,26,12,15,'Onları uluslar arasına dağıtıp ülkelere sürdüğümde, benim RAB olduğumu anlayacaklar.'),
(2004006,68,26,12,16,'Gittikleri uluslarda yaptıkları bütün iğrenç uygulamaları anlatmaları için aralarından birkaç kişiyi kılıçtan, kıtlıktan, salgın hastalıktan sağ bırakacağım. Böylece benim RAB olduğumu anlayacaklar.››'),
(2004007,68,26,12,17,'RAB bana şöyle seslendi:'),
(2004008,68,26,12,18,'‹‹İnsanoğlu, yiyeceğini titreyerek ye, suyunu korkudan ürpererek iç.'),
(2004009,68,26,12,19,'Ülkede yaşayan halka de ki, ‹Egemen RAB İsrail ve Yeruşalimde yaşayanlar için şöyle diyor: Yiyeceklerini umutsuzluk içinde yiyecek, sularını şaşkınlık içinde içecekler. Orada yaşayanların yaptığı zorbalık yüzünden ülke ıssız bırakılacak.'),
(2004010,68,26,12,20,'Halkın içinde yaşadığı kentler yakılacak, ülke çöle dönüşecek. O zaman benim RAB olduğumu anlayacaksınız.› ››'),
(2004011,68,26,12,21,'RAB bana şöyle seslendi:'),
(2004012,68,26,12,22,'‹‹İnsanoğlu, İsrailde yaygın olan, ‹Günler geçiyor, her görüm boşa çıkıyor› deyişinin anlamı nedir?'),
(2004013,68,26,12,23,'Onlara de ki, ‹Egemen RAB şöyle diyor: Ben bu deyişe son vereceğim. Bundan böyle İsrailde bir daha söylenmeyecek.› Yine onlara de ki, ‹Her görümün yerine geleceği günler yaklaştı.'),
(2004014,68,26,12,24,'Artık İsrail halkı arasında yalan görüm ya da aldatıcı falcılık olmayacak.'),
(2004015,68,26,12,25,'Ama ben RAB, ne dersem gecikmeden olacak. Siz, ey asi İsrail halkı, söylediklerimin tümünü sizin günlerinizde yerine getireceğim. Böyle diyor Egemen RAB.› ››'),
(2004016,68,26,12,26,'RAB bana şöyle seslendi:'),
(2004017,68,26,12,27,'‹‹İnsanoğlu, İsrail halkı, ‹Onun gördüğü görüm uzak günler için, peygamberlik sözleri de uzak gelecekle ilgili› diyor.'),
(2004018,68,26,12,28,'‹‹Bundan ötürü onlara de ki, ‹Egemen RAB şöyle diyor: Söylediğim sözlerden hiçbiri artık gecikmeyecek, ne dersem olacak. Böyle diyor Egemen RAB.› ››'),
(2004019,68,26,13,1,'RAB bana şöyle seslendi:'),
(2004020,68,26,13,2,'‹‹İnsanoğlu, peygamberlikte bulunan İsrail peygamberlerine karşı sen peygamberlik et. Kendiliğinden peygamberlik eden o peygamberlere de ki, ‹RABbin sözüne kulak verin!'),
(2004021,68,26,13,3,'Egemen RAB şöyle diyor: Hiçbir görüm görmemiş ama kurdukları hayaller uyarınca davranan akılsız peygamberlerin vay başına!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004022,68,26,13,4,'Ey İsrail, peygamberlerin yıkıntılar arasındaki çakallara benziyor.'),
(2004023,68,26,13,5,'RABbin gününde İsrail halkının savaşta direnmesi için gidip duvardaki gedikleri onarmadınız.'),
(2004024,68,26,13,6,'Onların görümleri uydurmadır. Yaptıkları yalan peygamberliklere RABbin sözüdür diyorlar. Oysa onları ben göndermedim. Yine de söylediklerinin yerine geleceğini umuyorlar.'),
(2004025,68,26,13,7,'Ben söylemediğim halde, RABbin sözüdür diyorsunuz. Oysa gördüğünüz görümler uydurma, yaptığınız falcılık yalan değil mi?'),
(2004026,68,26,13,8,'‹‹ ‹Bu yüzden Egemen RAB şöyle diyor: Söylediğiniz boş sözler, gördüğünüz yalan görümlerden ötürü size karşıyım. Böyle diyor Egemen RAB.'),
(2004027,68,26,13,9,'Elim uydurma görüm gören, yalan yere falcılık eden peygamberlere karşı olacak. Onlar halkımın topluluğunda bulunmayacak, İsrail halkının kütüğüne yazılmayacak, İsrail ülkesine girmeyecekler. O zaman benim Egemen RAB olduğumu anlayacaksınız.'),
(2004028,68,26,13,10,'‹‹ ‹Esenlik yokken esenlik diyerek halkımı aldatıyorlar. Biri dayanıksız bir duvar yapınca, sahte peygamberler üzerine sıva vuruyorlar.'),
(2004029,68,26,13,11,'Duvarı sıvayanlara de ki: Duvar yıkılacak; sağanak yağmur yağacak, ardından dolu yağdıracağım. Şiddetli bir rüzgar çıkıp duvara karşı esecek.'),
(2004030,68,26,13,12,'Duvar çökünce size, nerede duvara vurduğunuz sıva demeyecekler mi?'),
(2004031,68,26,13,13,'‹‹ ‹Onun için Egemen RAB şöyle diyor: Öfkemden duvarı yerle bir etmek için şiddetli bir rüzgar göndereceğim; kızgınlığımdan sağanak yağmur ve dolu yağdıracağım.'),
(2004032,68,26,13,14,'Sıva vurduğunuz duvarı yıkıp yerle bir edeceğim. Temeli açılıp ortaya çıkacak. Yıkılacak ve altında yok olacaksınız. O zaman benim RAB olduğumu anlayacaksınız.'),
(2004033,68,26,13,15,'Böylece öfkemi duvarın ve duvara sıva vuranların üzerine boşaltacağım. Size duvar da duvara sıva vuran da Yeruşalimde esenlik yokken esenlik görümleri gören İsrailli peygamberler de yok oldu diyeceğim. Egemen RAB böyle diyor.› ››'),
(2004034,68,26,13,17,'‹‹Sen, ey insanoğlu, kendiliğinden peygamberlik eden halkının kızlarına yüzünü çevir. Onlara karşı peygamberlik et.'),
(2004035,68,26,13,18,'De ki, ‹Egemen RAB şöyle diyor: İnsanları tuzağa düşürmek için herkese bilek bağı diken, her boyda baş örtüsü yapan kadınların vay başına! Kendi canınızı korurken halkımın canını mı tuzağa düşüreceksiniz?'),
(2004036,68,26,13,19,'Birkaç avuç arpayla birkaç dilim ekmek için halkımın arasında beni küçük düşürdünüz. Yalana kulak veren halkıma yalan söyleyerek ölümü hak etmemiş canları öldürdünüz, ölümü hak etmiş canları yaşattınız.'),
(2004037,68,26,13,20,'‹‹ ‹Bundan ötürü Egemen RAB şöyle diyor: İnsanları kuş gibi tuzağa düşüren sihirli bilek bağlarınıza karşıyım. Onları bileklerinizden koparacağım. Kuş gibi tuzağa düşürdüğünüz insanları özgür kılacağım.'),
(2004038,68,26,13,21,'Örtülerinizi yırtacak, halkımı elinizden kurtaracağım. Bir daha tuzağınıza düşmeyecekler. O zaman benim RAB olduğumu anlayacaksınız.'),
(2004039,68,26,13,22,'Madem incitmek istemediğim doğru kişinin cesaretini yalanlarınızla kırdınız ve canını kurtarmak için kötü kişiyi kötü yolundan dönmemeye yüreklendirdiniz,'),
(2004040,68,26,13,23,'bir daha uydurma görümler görmeyecek, falcılık etmeyeceksiniz. Halkımı elinizden kurtaracağım. O zaman benim RAB olduğumu anlayacaksınız.› ››'),
(2004041,68,26,14,1,'İsrail ileri gelenlerinden kimisi gelip yanıma oturdu.'),
(2004042,68,26,14,2,'O sırada RAB bana şöyle seslendi:'),
(2004043,68,26,14,3,'‹‹İnsanoğlu, bu adamların yüreği putlara bağlı. Diktikleri putların kendilerini günaha sokmasına olanak veriyorlar. Öyleyse onların bana danışmasına izin vermeli miyim?'),
(2004044,68,26,14,4,'Bunun için onlarla konuş ve de ki, ‹Egemen RAB şöyle diyor: Yüreğini puta bağlayan, diktiği putun kendisini günaha sokmasına olanak veren, sonra da peygambere danışmaya gelen her İsrailliye putlarının çokluğuna göre ben RAB kendim karşılık vereceğim.'),
(2004045,68,26,14,5,'Bunu, putları yüzünden bana sırt çeviren İsrail halkının yüreğini yeniden kendime çekmek için yapacağım.›'),
(2004046,68,26,14,6,'‹‹Bu yüzden İsrail halkına de ki, ‹Egemen RAB şöyle diyor: Geri dönün! Putlarınızdan vazgeçin, iğrenç uygulamalarınızı bırakın!'),
(2004047,68,26,14,7,'‹‹ ‹İsrail halkından biri ya da İsrailde yaşayan bir yabancı benden ayrılır, yüreğini putlara bağlar, diktiği putların kendisini günaha sokmasına olanak verir, sonra da bana danışmak üzere bir peygambere giderse, ben RAB kendim ona karşılık vereceğim.'),
(2004048,68,26,14,8,'O kişiye karşı çıkacağım. Onu bir belirti, bir alay konusu yapıp halkımın arasından atacağım. O zaman benim RAB olduğumu anlayacaksınız.'),
(2004049,68,26,14,9,'‹‹ ‹Bir peygamber ayartılır da bir söz söylerse, onu ayartan benim. Elimi ona karşı uzatacağım, onu halkım İsrailin arasından çıkarıp yok edeceğim.'),
(2004050,68,26,14,10,'Suçlarının cezasını çekecekler. Peygamber de ona danışan da aynı şekilde cezalandırılacak.'),
(2004051,68,26,14,11,'Böylece İsrail halkı bir daha benden ayrılmayacak, günahlarıyla kendilerini kirletmeyecekler. Onlar halkım olacaklar, ben de onların Tanrısı olacağım. Egemen RAB böyle diyor.› ››'),
(2004052,68,26,14,12,'RAB bana şöyle seslendi:'),
(2004053,68,26,14,13,'‹‹İnsanoğlu, eğer bir ülke bana sadakatsizlik eder, günah işlerse, ben de o ülkeye karşı elimi uzatır, onu her türlü yiyecekten yoksun bırakır, üzerine kıtlık gönderir, insanları ve hayvanları yok edersem;'),
(2004054,68,26,14,14,'şu üç adam -Nuh, Daniel, Eyüp- orada olsalar bile, doğruluklarıyla ancak kendi canlarını kurtarabilirler. Egemen RAB böyle diyor. olduğundan bildiğimiz Peygamber Daniel olmayabilir.'),
(2004055,68,26,14,15,'‹‹Ya da ülkeye yabanıl hayvanlar gönderirsem ve ülkeyi kimsesiz bırakırlarsa, ülke viraneye döner, hayvanlar yüzünden kimse içinden geçemezse;'),
(2004056,68,26,14,16,'Varlığım hakkı için diyor Egemen RAB, bu üç kişi o ülkede yaşasa bile, ne oğullarını ne de kızlarını kurtarabilirler. Ancak kendi canlarını kurtarabilirler. Ülke ise viraneye döner.'),
(2004057,68,26,14,17,'‹‹Ya da o ülkeye kılıç gönderir, ‹Kılıç ülkeyi yarsın› der, oradaki insanları ve hayvanları yok edersem;'),
(2004058,68,26,14,18,'varlığım hakkı için diyor Egemen RAB, bu üç kişi orada olsa bile, ne oğullarını ne de kızlarını kurtarabilirler. Ancak kendi canlarını kurtarabilirler.'),
(2004059,68,26,14,19,'‹‹O ülkeye salgın hastalık gönderir, kan dökerek öfkemi yağdırır, oradaki insanları ve hayvanları yok edersem;'),
(2004060,68,26,14,20,'varlığım hakkı için diyor Egemen RAB, Nuh, Daniel ve Eyüp orada olsa bile, ne oğullarını ne de kızlarını kurtarabilirler. Doğruluklarıyla ancak kendi canlarını kurtarabilirler.'),
(2004061,68,26,14,21,'‹‹Egemen RAB şöyle diyor: Yeruşalimdeki insanları ve hayvanları yok etmek için üzerine dört ağır yargımı -kılıcı, kıtlığı, yabanıl hayvanları, salgın hastalığı- gönderdiğimde daha neler neler olacak!'),
(2004062,68,26,14,22,'Orada sağ bırakılacak kimi oğullarınız, kızlarınız olacak, çıkıp yanınıza gelecekler. Onların davranışlarını ve yaptıklarını görünce, Yeruşalimin başına getirdiğim yıkımdan ve her tür felaketten avuntu bulacaksınız.'),
(2004063,68,26,14,23,'Onların davranışlarını ve yaptıklarını görünce avutulacak, Yeruşalim''in başına getirdiklerimin amaçsız olmadığını anlayacaksınız. Egemen RAB böyle diyor.››'),
(2004064,68,26,15,1,'RAB bana şöyle seslendi:'),
(2004065,68,26,15,2,'‹‹İnsanoğlu, asma odununun herhangi bir orman ağacının dalından daha fazla değeri var mı?'),
(2004066,68,26,15,3,'Asma odunundan yararlı bir şey yapılabilir mi? Ya da üzerine eşya asmak için ondan askı yaparlar mı?'),
(2004067,68,26,15,4,'Yakıt olarak ateşe atılır da ateş odunun iki ucunu yakıp ortasını kömürleştirince, işe yarar mı?'),
(2004068,68,26,15,5,'Yanmadan önce işe yaramadıysa, yanıp kömür haline geldikten sonra bir işe yarar mı?'),
(2004069,68,26,15,6,'‹‹Bu nedenle Egemen RAB şöyle diyor: Orman ağaçları arasında asma odununu nasıl yakıt olarak ateşe verdimse, Yeruşalimde yaşayan halka da aynısını yapacağım.'),
(2004070,68,26,15,7,'Onlara yüz çevireceğim. Şimdi ateşten kurtulsalar bile, ateş onları yine de yakıp yok edecek. Onlara yüz çevirince, benim RAB olduğumu anlayacaksınız.'),
(2004071,68,26,15,8,'Ülkeyi viraneye çevireceğim. Çünkü bana sadakatsizlik ettiler. Egemen RAB böyle diyor.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004072,68,26,16,1,'RAB bana şöyle seslendi:'),
(2004073,68,26,16,2,'‹‹İnsanoğlu, Yeruşalime yaptığı iğrenç uygulamaları bildir.'),
(2004074,68,26,16,3,'De ki, ‹Egemen RAB Yeruşalime şöyle diyor: Kökenin ve doğumun açısından Kenan ülkesindensin; baban Amorlu, annense Hititliydi.'),
(2004075,68,26,16,4,'Doğduğun gün göbek bağın kesilmedi, temizlemek için seni yıkamadılar, tuzla ovalamadılar, kundağa sarmadılar.'),
(2004076,68,26,16,5,'Kimse bunlardan birini yapacak kadar sana acımadı, sevecenlik göstermedi. Senden tiksindikleri için doğduğun gün seni kıra attılar.'),
(2004077,68,26,16,6,'‹‹ ‹Yanından geçtim, senin kendi kanının içinde kımıldadığını gördüm. Kendi kanının içindeyken yaşa! dedim. Evet, Kendi kanının içindeyken yaşa! dedim.'),
(2004078,68,26,16,7,'Kırda yetişen bir bitki gibi seni geliştirdim. Geliştin, büyüdün, kusursuz bir güzelliğe eriştin. Göğüslerin oluştu, saçların uzadı. Ama çırılçıplaktın.'),
(2004079,68,26,16,8,'‹‹ ‹Yine yanından geçtim, sana baktım, sevgi çağındı. Giysimin eteğini üzerine serdim, çıplaklığını örttüm. Sana ant içtim, seninle antlaşma yaptım. Egemen RAB böyle diyor. Ve benim oldun.'),
(2004080,68,26,16,9,'‹‹ ‹Seni yıkadım, üzerindeki kanı temizledim, derine zeytinyağı sürdüm.'),
(2004081,68,26,16,10,'Sana işlemeli giysiler giydirdim, deridenfı çarık verdim. Beline ince keten kuşak bağladım, seni pahalı giysilerle örttüm,'),
(2004082,68,26,16,11,'takılarla süsledim. Bileklerine bilezikler, boynuna gerdanlık taktım.'),
(2004083,68,26,16,12,'Burnuna halka, kulaklarına küpeler, başına görkemli bir taç taktım.'),
(2004084,68,26,16,13,'Altınla gümüşle süslendin; giysilerin ince ketenden, pahalı, işlemeli kumaştandı. İnce unla, balla, zeytinyağıyla beslendin. Gitgide güzelleştin, krallığa yaraştın.'),
(2004085,68,26,16,14,'Güzelliğinden ötürü ünün uluslar arasında yayıldı. Çünkü seni görkemimle donattığım için güzelliğin kusursuzdu. Egemen RAB böyle diyor.'),
(2004086,68,26,16,15,'‹‹ ‹Ama sen güzelliğine güvendin, ününü kullanarak fahişelik ettin. Her geçene gönlünü kaptırdın, kendini teslim ettin.'),
(2004087,68,26,16,16,'Giysilerinden alıp kendine süslü tapınma yerleri yaptın, oralarda fahişelik ettin. Böylesi ne olmuştur, ne de olacaktır.'),
(2004088,68,26,16,17,'Sana verdiğim altın, gümüş süslerden erkek suretleri yaptın, onlarla fahişelik ettin.'),
(2004089,68,26,16,18,'İşlemeli giysilerini alıp onların üzerine örttün. Onlara zeytinyağımı, buhurumu sundun.'),
(2004090,68,26,16,19,'Yemen için sağladığım yiyeceği -ince unu, zeytinyağını, balı- güzel kokulu bir sunu olarak onlara sundun. Böyle yaptın diyor Egemen RAB.'),
(2004091,68,26,16,20,'‹‹ ‹Bana doğurduğun oğulları, kızları alıp yiyecek olarak putlara kurban ettin. Fahişelik etmen yetmiyormuş gibi,'),
(2004092,68,26,16,21,'çocuklarımı kesip sunu olarak ateşte putlara kurban ettin.'),
(2004093,68,26,16,22,'Bütün iğrenç uygulamalarını, fahişeliklerini yaparken gençlik günlerini, çırılçıplak olduğun, kanının içinde kımıldandığın zamanı anımsamadın.'),
(2004094,68,26,16,23,'‹‹ ‹Egemen RAB, vay, vay başına diyor! Yaptığın kötülüklere ek olarak,'),
(2004095,68,26,16,24,'kendine fuhuş yuvaları kurdun, bütün meydanlarda yüksek tapınma yerleri yaptın.'),
(2004096,68,26,16,25,'Her yolun başına kendin için yüksek tapınma yerleri kurdun, güzelliğini kirlettin, her geçene kendini teslim ettin, fahişeliklerini artırdın.'),
(2004097,68,26,16,26,'Şehvet düşkünü komşuların Mısırlılarla fahişelik ettin. Fahişeliklerini artırmakla beni öfkelendirdin.'),
(2004098,68,26,16,27,'İşte bu yüzden elimi sana karşı uzattım, yiyecek payını azalttım. Ahlaksız davranışından utanç duyan düşmanların Filist kızları dilediklerini yapsınlar diye seni onlara teslim ettim.'),
(2004099,68,26,16,28,'Asurlularla da fahişelik ettin, çünkü doymamıştın. Evet, onlarla fahişelik ettin, yine doymadın.'),
(2004100,68,26,16,29,'Fahişeliğini ticaret diyarı olan Kildan ülkesine dek artırdın, yine de doymadın.'),
(2004101,68,26,16,30,'‹‹ ‹Bütün bunları yaparken yüreğin ne kadar yıpranmış› diyor Egemen RAB, ‹Yüzsüz bir fahişe gibi davrandın!'),
(2004102,68,26,16,31,'Her yolun başına fuhuş yuvaları kurarken, bütün meydanlarda yüksek tapınma yerleri yaparken, fahişe gibi bile değildin, ücretini küçümsedin.'),
(2004103,68,26,16,32,'‹‹ ‹Kocasının yerine yabancıları yeğleyen, zina eden bir kadındın!'),
(2004104,68,26,16,33,'Fahişelere ücret ödenir. Oysa sen bütün oynaşlarına armağanlar dağıttın. Fahişelik etmek için her yandan sana gelsinler diye rüşvet verdin.'),
(2004105,68,26,16,34,'Fahişeliğinde öbür kadınlara benzemiyorsun. Çünkü fahişelik edesin diye kimse senin peşine düşmüyor. Ücret ödeyen sensin, kimse sana ücret ödemiyor. Bu yüzden öbürlerine benzemiyorsun.'),
(2004106,68,26,16,35,'‹‹ ‹Bu nedenle, ey fahişe, RABbin sözünü dinle!'),
(2004107,68,26,16,36,'Egemen RAB şöyle diyor: Yüzsüzlüğün ortaya döküldüğü, oynaşlarınla fahişelik ederken çıplaklığın meydana çıktığı için, bütün iğrenç putların yüzünden, onlara çocuklarının kanını verdiğin için,'),
(2004108,68,26,16,37,'düşüp kalktığın bütün oynaşlarını -sevdiklerini de nefret ettiklerini de- toplayacağım. Sana karşı onları her yandan toplayacak, çıplaklığını onların önüne sereceğim; bütün çıplaklığını görecekler.'),
(2004109,68,26,16,38,'Sana zina eden, kan döken kadınlara verilen cezayı vereceğim. Kanını akıtarak seni öfkemin ve kıskançlığımın öcüne terk edeceğim.'),
(2004110,68,26,16,39,'Seni oynaşlarının eline teslim edeceğim. Fuhuş yuvalarını yıkacak, yüksek tapınma yerlerini bozacaklar. Üzerindeki giysileri soyacak, güzel mücevherlerini alıp seni çırılçıplak bırakacaklar.'),
(2004111,68,26,16,40,'Halkı sana karşı kışkırtacaklar. Seni taşlayacak, kılıçlarıyla delik deşik edecekler.'),
(2004112,68,26,16,41,'Evlerini ateşe verecek, seni birçok kadının gözü önünde yargılayacaklar. Fahişeliklerine son vereceğim, artık oynaşlarına ücret ödemeyeceksin.'),
(2004113,68,26,16,42,'Böylece sana karşı öfkem yatışacak, kıskançlığım dinecek. Susacak, bir daha öfkelenmeyeceğim.'),
(2004114,68,26,16,43,'‹‹ ‹Madem gençlik günlerini anımsamadın, yaptıklarınla beni öfkelendirdin, ben de yaptıklarını senin başına getireceğim. Böyle diyor Egemen RAB. Bu iğrenç uygulamalarına ek olarak ahlaksızlık da ettin.'),
(2004115,68,26,16,44,'‹‹ ‹Herkes senin için şu deyişi söyleyecek: Annesi nasılsa kızı da öyle.'),
(2004116,68,26,16,45,'Sen kocasından ve çocuklarından tiksinen annenin kızısın; kocalarından ve çocuklarından tiksinen kızkardeşlerinin kızkardeşisin. Annen Hititli, baban Amorluydu.'),
(2004117,68,26,16,46,'Kızlarıyla senin kuzeyinde yaşayan Samiriye ablan, kızlarıyla senin güneyinde yaşayan Sodom kızkardeşindir.'),
(2004118,68,26,16,47,'Sen yalnız onların yolunda yürümekle, onların iğrenç uygulamalarına uymakla kalmadın, bütün yaptıklarınla kısa sürede onlardan daha büyük kötülük ettin.'),
(2004119,68,26,16,48,'Varlığım hakkı için diyor Egemen RAB, kızkardeşin Sodomla kızları, kızlarınla senin yaptıklarını asla yapmadılar.'),
(2004120,68,26,16,49,'‹‹ ‹Kızkardeşin Sodomun günahı şuydu: Kendisi de kızları da gururluydu, ekmeğe doymuşlardı, umursamazlardı. Düşküne, yoksula yardım elini uzatmadılar.'),
(2004121,68,26,16,50,'Kendilerini beğenmişlerdi. Önümde iğrenç şeyler yaptılar. Bu nedenle, gördüğün gibi onları önümden süpürüp attım.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004122,68,26,16,51,'Samiriye işlediğin günahın yarısını bile işlemedi. Sen onlardan çok daha iğrenç şeyler yaptın. Yaptığın iğrençliklerle kızkardeşlerini suçsuz çıkardın.'),
(2004123,68,26,16,52,'Düşeceğin utanca katlanacaksın. Çünkü kızkardeşlerini haklı gibi gösterdin. İşlediğin günahlar onlarınkinden daha iğrenç olduğundan senin yanında suçsuz kalıyorlar. Bunun için utan ve düşeceğin utanca katlan. Çünkü kızkardeşlerini suçsuz çıkardın!'),
(2004124,68,26,16,53,'‹‹ ‹Sodomla kızlarını, Samiriyeyle kızlarını, onlarla birlikte de seni eski gönencine kavuşturacağım.'),
(2004125,68,26,16,54,'Utanca boğulacaksın. Bütün yaptıklarından ötürü kızkardeşlerine avuntu olacak ve utanacaksın.'),
(2004126,68,26,16,55,'Kızkardeşlerin Sodom ve Samiriye ile kızları eski durumlarına dönecekler; kızlarınla sen de öyle.'),
(2004127,68,26,16,56,'Kötülüğün açığa çıkmadan önce, gururlu olduğun günlerde kızkardeşin Sodomun adını bile anmıyordun. Şimdi sen de Edom kızlarıyla komşuları ve Filist kızlarınca -çevrende seninle alay edenlerce- küçümseniyorsun.'),
(2004128,68,26,16,58,'Ahlaksızlığının ve yaptığın iğrençliklerin sonuçlarına katlanacaksın. RAB böyle diyor.'),
(2004129,68,26,16,59,'‹‹ ‹Egemen RAB şöyle diyor: Seninle yaptığım antlaşmayı bozarak içtiğin andı küçümsedin. Ben de hak ettiğin biçimde seni cezalandıracağım.'),
(2004130,68,26,16,60,'Gençlik günlerinde seninle yaptığım antlaşmayı anımsayacağım. Seninle sonsuza dek kalıcı bir antlaşma yapacağım.'),
(2004131,68,26,16,61,'Büyük, küçük kızkardeşlerini yanına aldığında yaptıklarını anımsayacak ve utanacaksın. Seninle yaptığım antlaşmada olmadığı halde onları kızların olsunlar diye sana vereceğim.'),
(2004132,68,26,16,62,'Seninle yeniden antlaşma yapacağım, benim RAB olduğumu anlayacaksın.'),
(2004133,68,26,16,63,'Bütün yaptıklarını bağışladığımda, anımsayacak ve utanacaksın. Utancından bir daha ağzını açmayacaksın. Egemen RAB böyle diyor.› ››'),
(2004134,68,26,17,1,'RAB bana şöyle seslendi:'),
(2004135,68,26,17,2,'‹‹Ey insanoğlu, İsrail halkına bir bilmece sor, simgesel bir öykü anlat.'),
(2004136,68,26,17,3,'De ki, ‹Egemen RAB şöyle diyor: Kanatları uzun ve güçlü, renk renk tüylerle dolu iri bir kartal Lübnana geldi, bir sedir ağacının tepesine konup onu ele geçirdi.'),
(2004137,68,26,17,4,'Ağacın tepesindeki filizleri koparıp ticaret ülkesine götürdü, tüccarlar kentine yerleştirdi.'),
(2004138,68,26,17,5,'‹‹ ‹Ülkenin tohumundan alıp verimli toprağa ekti; onu söğüt ağacı gibi akarsuların kıyısına dikti.'),
(2004139,68,26,17,6,'Tohum filizlenip yerde yayılan bodur bir asma oldu. Dalları kartala doğru yayıldı, kökleriyse aşağıya, derine indi. Böylece dal salan, filiz veren bir asma oldu.'),
(2004140,68,26,17,7,'‹‹ ‹Gelgelelim, kanatları güçlü, bol tüylü başka bir iri kartal da vardı. Asma bu kez dikildiği yerden köklerini bu kartala doğru çevirdi; sulasın diye dallarını ona doğru saldı.'),
(2004141,68,26,17,8,'Dallansın, ürün versin, görkemli bir asma olsun diye akarsuların kıyısındaki verimli toprağa dikilmişti.›'),
(2004142,68,26,17,9,'‹‹Onlara de ki, ‹Egemen RAB şöyle diyor: Asma serpilecek mi? Kurusun diye ilk kartal kökünü söküp meyvesini koparmayacak mı? Asmanın yeni filizlenen bütün dalları kuruyacak. Kökünden söküp atmak için güçlü ele ya da büyük orduya gerek duyulmayacak.'),
(2004143,68,26,17,10,'Evet, asma dikilmiş, ama serpilip gelişecek mi? Doğu rüzgarı ona çarpınca büsbütün kurumayacak mı? Evet, filizlendiği yerde solup kuruyacak.› ››'),
(2004144,68,26,17,11,'RAB bana şöyle seslendi:'),
(2004145,68,26,17,12,'‹‹O asi halka de ki, ‹Bunların ne anlama geldiğini bilmiyor musunuz?› Onlara de ki, ‹Babil Kralı Yeruşalime gitti; kralını, önderlerini tutsak alıp kendisiyle birlikte Babile götürdü.'),
(2004146,68,26,17,13,'Sonra kralın soyundan gelen birini alıp ant içirerek onunla bir antlaşma yaptı. Ülkenin önderlerini de tutsak aldı.'),
(2004147,68,26,17,14,'Öyle ki, ülke gerilesin, bir daha yükselmesin, ancak yaptığı antlaşmayı yerine getirerek yaşayabilsin.'),
(2004148,68,26,17,15,'Ne var ki, Yahuda Kralı, kendisine at ve çok sayıda asker vermesi için Mısıra elçiler göndererek Babil Kralına başkaldırdı. Yahuda Kralı başaracak mı? Böyle şeyler yapan kurtulur mu? Yaptığı antlaşmayı bozan kurtulur mu?'),
(2004149,68,26,17,16,'‹‹ ‹Egemen RAB, varlığım hakkı için diyor, onu tahta oturtan kralın ülkesinde, Babilde ölecek. Çünkü içtiği andı küçümsedi, yaptığı antlaşmayı bozdu.'),
(2004150,68,26,17,17,'Babilliler birçok kişiyi yok etmek için toprak rampalar, kuşatma duvarları yaptığında, firavun güçlü ordusu ve büyük kalabalıklarla savaşta ona yardımcı olmayacak.'),
(2004151,68,26,17,18,'Yaptığı antlaşmayı bozarak içtiği andı küçümsedi. Söz verdiği halde, bütün bunları yaptı. Bu yüzden kurtulmayacak.'),
(2004152,68,26,17,19,'‹‹ ‹Bu nedenle Egemen RAB şöyle diyor: Varlığım hakkı için, bana içtiği andı küçümsediği, antlaşmamı bozduğu için onu cezalandıracağım.'),
(2004153,68,26,17,20,'Ağımı gereceğim, tuzağıma düşecek. Onu Babile getirecek, bana sadakatsizliğinden ötürü orada yargılayacağım.'),
(2004154,68,26,17,21,'En seçkin askerleri kılıçtan geçirilecek, sağ kalanlar dünyanın dört bucağına dağılacak. O zaman konuşanın ben RAB olduğumu anlayacaksınız.'),
(2004155,68,26,17,22,'‹‹ ‹Egemen RAB şöyle diyor: 2 Sedir ağacının tepesinden 2 Bir filiz alıp dikeceğim. 2 En yüksek dallarından körpe bir çubuk koparıp 2 Yüksek, ulu bir dağın üzerine dikeceğim.'),
(2004156,68,26,17,23,'Onu İsrailin en yüksek dağının üzerine dikeceğim. 2 Dal budak salıp ürün verecek, 2 Görkemli bir sedir ağacı olacak. 2 Her çeşit kuş dallarına tüneyecek, 2 Gölgesinde barınacak.'),
(2004157,68,26,17,24,'Bütün orman ağaçları 2 Her yüksek ağacı bodurlaştıranın, 2 Her bodur ağacı yükseltenin, 2 Her yeşil ağacı kurutanın 2 Ve kuru ağacı yeşertenin 2 Ben RAB olduğumu anlayacaklar. 2 Bunu ben RAB söylüyorum ve dediğimi yapacağım.› ››'),
(2004158,68,26,18,1,'RAB bana şöyle seslendi:'),
(2004159,68,26,18,2,'‹‹İsrail için, ‹Babalar koruk yedi, 2 Çocukların dişleri kamaştı› diyorsunuz. 2 Bu deyişle ne demek istiyorsunuz?'),
(2004160,68,26,18,3,'‹‹Varlığım hakkı için diyor Egemen RAB, İsrailde artık bu deyişi ağzınıza almayacaksınız.'),
(2004161,68,26,18,4,'Her yaşayan can benimdir. Babanın canı da, çocuğun canı da benimdir. Ölecek olan, günah işleyen candır.'),
(2004162,68,26,18,5,'‹‹Diyelim ki, adil ve doğru olanı yapan doğru bir adam var.'),
(2004163,68,26,18,6,'Dağlarda putlara sunulan kurbandan yemez, 2 İsrail halkının putlarına bel bağlamaz. 2 Komşusunun karısını kirletmez, 2 Âdet gören kadına yaklaşmaz.'),
(2004164,68,26,18,7,'Kimseye haksızlık etmez, 2 Rehin olarak aldığını geri verir, 2 Soygunculuk etmez, 2 Aç olana ekmeğini verir, 2 Çıplağı giydirir.'),
(2004165,68,26,18,8,'Faizle para vermez, 2 Aşırı kâr gütmez. 2 Elini kötülükten çeker, 2 İki kişi arasında doğrulukla yargılar.'),
(2004166,68,26,18,9,'Kurallarımı izler, 2 İlkelerimi özenle uygular. 2 İşte böyle biri doğru kişidir. 2 O yaşayacaktır. Egemen RAB böyle diyor.'),
(2004167,68,26,18,10,'‹‹Diyelim ki, bu adamın zorba, kan döken, 2 Kardeşine bunlardan birini yapan bir oğlu var.'),
(2004168,68,26,18,11,'Babası bunlardan hiçbirini yapmazken, 2 Oğul dağlarda putlara sunulan kurbandan yer, 2 Komşusunun karısını kirletir.'),
(2004169,68,26,18,12,'Düşküne, yoksula haksızlık eder, 2 Soygunculuk eder, 2 Rehini geri vermez. 2 Putlara bel bağlar, 2 İğrenç şeyler yapar.'),
(2004170,68,26,18,13,'Faizle para verir, aşırı kâr güder. 2 Böyle biri yaşayacak mı? 2 Hayır, yaşamayacak! 2 Bütün bu iğrençlikleri yapmıştır, öldürülecektir. 2 Onun kanından kendisi sorumlu olacaktır.'),
(2004171,68,26,18,14,'‹‹Diyelim ki, bu oğulun da bir oğlu olur ve babasının işlediği bütün günahları görür, 2 Ama hiçbirini yapmaz;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004172,68,26,18,15,'Dağlarda putlara sunulan kurbandan yemez, 2 İsrail halkının putlarına bel bağlamaz, 2 Komşusunun karısını kirletmez;'),
(2004173,68,26,18,16,'Kimseye haksızlık etmez, 2 Rehin almaz, 2 Soygunculuk etmez, 2 Aç olana ekmeğini verir, 2 Çıplağı giydirir.'),
(2004174,68,26,18,17,'Böyle biri elini kötülükten çeker, 2 Faiz almaz, aşırı kâr gütmez, 2 Kurallarımı izler, 2 İlkelerimi uygularsa, 2 Babasının günahı yüzünden ölmeyecek, 2 Kesinlikle yaşayacaktır.'),
(2004175,68,26,18,18,'Ama babası kendi günahı yüzünden ölecektir. 2 Çünkü zorbalık etti, kardeşini soydu, 2 Halkı arasında iyi olmayanı yaptı.'),
(2004176,68,26,18,19,'‹‹Ama siz, ‹Oğul neden babasının işlediği suçlardan sorumlu tutulmasın?› dersiniz. Bu oğul adil ve doğru olanı yapmış, bütün kurallarımı dikkatle izlemiştir. Böyle biri kesinlikle yaşayacaktır.'),
(2004177,68,26,18,20,'Ölecek olan günah işleyen kişidir. Oğul babasının suçundan sorumlu tutulamaz, baba da oğlunun suçundan sorumlu tutulamaz. Doğru kişi doğruluğunun, kötü kişi kötülüğünün karşılığını alacaktır.'),
(2004178,68,26,18,21,'‹‹Kötü kişi işlediği bütün günahlardan döner, buyruklarıma uyar, adil ve doğru olanı yaparsa, kesinlikle yaşayacak, ölmeyecektir.'),
(2004179,68,26,18,22,'İşlediği günahlardan hiçbiri ona karşı anılmayacaktır. Doğruluğu sayesinde yaşayacaktır.'),
(2004180,68,26,18,23,'Ben kötü kişinin ölümünden sevinç duymam, ancak kötü kişinin kötü yollarından dönüp yaşamasından sevinç duyarım. Egemen RAB böyle diyor.'),
(2004181,68,26,18,24,'‹‹Doğru kişi doğruluğundan döner, günah işler, kötü kişinin yaptığı bütün iğrenç şeyleri yaparsa, yaşayacak mı? Onun yaptığı doğru işlerin hiçbiri anılmayacaktır. Sadakatsizliği yüzünden suçludur, günahları yüzünden ölecektir.'),
(2004182,68,26,18,25,'‹‹Siz yine de, ‹Rabbin yolu doğru değil› diyorsunuz. Ey İsrail halkı, dinle: Benim yolum mu doğru değil? Doğru olmayan sizin yollarınız değil mi?'),
(2004183,68,26,18,26,'Doğru kişi doğruluğundan döner de kötülük yaparsa, bu yüzden ölecek. Evet, işlediği günah yüzünden ölecektir.'),
(2004184,68,26,18,27,'Ama kötü kişi, yaptığı kötülükten döner, adil ve doğru olanı yaparsa, canını kurtaracaktır.'),
(2004185,68,26,18,28,'Çünkü isyanlarının farkına varıyor ve onlardan dönüyor. Böyle biri kesinlikle yaşayacak, ölmeyecektir.'),
(2004186,68,26,18,29,'Öyleyken, İsrail halkı, ‹Rabbin yolu doğru değil› diyor. Ey İsrail halkı, benim yollarım mı doğru değil? Doğru olmayan sizin yollarınız değil mi?'),
(2004187,68,26,18,30,'‹‹Bu yüzden, ey İsrail halkı, sizleri, her birinizi yolunuza göre yargılayacağım. Egemen RAB böyle diyor. Dönün! İsyanlarınızdan dönün! Günahın sizi yıkıma sürüklemesine izin vermeyin.'),
(2004188,68,26,18,31,'İsyanlarınızı kendinizden uzaklaştırın. Yeni bir yürek, yeni bir ruh edinin. Neden öleceksin, ey İsrail halkı?'),
(2004189,68,26,18,32,'Çünkü ben kimsenin ölümünden sevinç duymam. Egemen RAB böyle diyor. Öyleyse günahınızdan dönün de yaşayın!››'),
(2004190,68,26,19,1,'‹‹Sen İsrail önderleri için şu ağıtı yak'),
(2004191,68,26,19,2,'ve de ki, ‹‹ ‹Annen neydi? Aslanlar arasında dişi bir aslan! 2 Genç aslanlar arasında yatar, 2 Yavrularını beslerdi.'),
(2004192,68,26,19,3,'Büyüttüğü yavrulardan biri 2 Genç bir aslan oldu. 2 Avını kapıp parçalamayı öğrendi, 2 İnsan yiyen bir aslan oldu.'),
(2004193,68,26,19,4,'Haberi uluslar arasında duyuldu. 2 Kurdukları tuzağa düştü, 2 Onu çengellerle Mısıra sürüklediler.'),
(2004194,68,26,19,5,'Dişi aslan bekledi, umudunun boşa çıktığını görünce, 2 Yavrularından başka birini alıp 2 Genç bir aslan olarak yetiştirdi.'),
(2004195,68,26,19,6,'Yavru aslanlar arasında dolaşmaya başladı, 2 Genç bir aslan oldu. 2 Avını kapıp parçalamayı öğrendi, 2 İnsan yiyen bir aslan oldu.'),
(2004196,68,26,19,7,'Onların kalelerini yıktı, 2 Kentlerini viraneye çevirdi. 2 Ülkede yaşayan herkes 2 Onun kükreyişinden dehşete düştü. kadınlarını tanıdı››.'),
(2004197,68,26,19,8,'Çevredeki uluslar üzerine geldiler, 2 Ağlarını gerdiler, 2 Onu tuzağa düşürdüler.'),
(2004198,68,26,19,9,'Çengel takıp onu kafese koydular 2 Ve Babil Kralına götürdüler. 2 İsrail dağlarında kükreyişi bir daha duyulmasın diye 2 Onu gözetim altında tuttular.'),
(2004199,68,26,19,10,'‹‹ ‹Annen su kıyısındaki bağında 2 Dikilmiş bir asma gibiydi. 2 Bol su sayesinde dal budak saldı, 2 Ürün verdi.'),
(2004200,68,26,19,11,'Dalları kral asası olacak kadar güçlendi. 2 Asma boy attı, 2 Bulutlara dek yükseldi. 2 Yüksekliği ve dallarının çokluğu 2 Herkesçe görüldü.'),
(2004201,68,26,19,12,'Ama onu öfkeyle kökünden söküp yere attılar. 2 Doğu rüzgarı ürününü kuruttu. 2 Güçlü dalları koparılıp kurudu, 2 Ateş onları yakıp yok etti.'),
(2004202,68,26,19,13,'Şimdi çöle, 2 Kurak, susuz bir yere dikildi.'),
(2004203,68,26,19,14,'Gövdesi ateş aldı, 2 Filizini, ürününü yakıp yok etti. 2 Kral asası olacak kadar güçlü dalı kalmadı.› 2 Bu bir ağıttır ve ağıt olarak kalacaktır.››'),
(2004204,68,26,20,1,'Sürgünlüğümüzün yedinci yılı, beşinci ayın onuncu günü, İsrail ileri gelenlerinden bazı kişiler RABbe danışmak için gelip önüme oturdular.'),
(2004205,68,26,20,2,'RAB o sırada bana seslendi:'),
(2004206,68,26,20,3,'‹‹İnsanoğlu, İsrail ileri gelenlerine de ki, ‹Egemen RAB şöyle diyor: Bana danışmaya mı geldiniz? Varlığım hakkı için diyor Egemen RAB, bana danışmanıza izin vermeyeceğim.›'),
(2004207,68,26,20,4,'‹‹Onları yargılayacak mısın? Ey insanoğlu, onları yargılayacak mısın? Öyleyse onlara atalarının iğrenç uygulamalarını anımsat.'),
(2004208,68,26,20,5,'Onlara de ki, ‹Egemen RAB şöyle diyor: İsraili seçtiğim gün Yakup soyuna ant içtim ve kendimi Mısırda onlara açıkladım. Ant içerek, Tanrınız RAB benim dedim.'),
(2004209,68,26,20,6,'O gün, onları Mısırdan çıkaracağıma, kendileri için seçtiğim en güzel ülkeye, süt ve bal akan ülkeye götüreceğime söz verdim.'),
(2004210,68,26,20,7,'Onlara, herkes bel bağladığı iğrenç putları atsın, Mısır putlarıyla kendinizi kirletmeyin, Tanrınız RAB benim dedim.'),
(2004211,68,26,20,8,'‹‹ ‹Ne var ki, bana karşı geldiler, beni dinlemek istemediler. Bel bağladıkları iğrenç putları hiçbiri atmadı, Mısır putlarını da bırakmadılar. Bu yüzden Mısırda öfkemi onların üzerine yağdıracağımı, kızgınlığımı dökeceğimi söyledim.'),
(2004212,68,26,20,9,'Ama aralarında yaşadıkları ulusların gözünde adıma leke gelmesin diye bunu yapmadım. Bu ulusların gözü önünde İsraillileri Mısırdan çıkararak kendimi onlara açıklamıştım.'),
(2004213,68,26,20,10,'Bu yüzden İsraillileri Mısırdan çıkarıp çöle götürdüm.'),
(2004214,68,26,20,11,'Uygulayan kişiye yaşam veren kurallarımı onlara verdim, ilkelerimi tanıttım.'),
(2004215,68,26,20,12,'Kendilerini kutsal kılanın ben RAB olduğumu anlasınlar diye aramızda bir belirti olarak Şabat günlerimi de onlara verdim.'),
(2004216,68,26,20,13,'‹‹ ‹Böyleyken İsrail halkı çölde bana başkaldırdı. Uygulayan kişiye yaşam veren kurallarımı izlemediler, ilkelerimi reddettiler. Şabat günlerimi de hiçe saydılar. Bu yüzden çölde öfkemi üzerlerine yağdırıp onları yok edeceğimi söyledim.'),
(2004217,68,26,20,14,'Ama İsraillileri Mısırdan çıkardığımı gören ulusların gözünde adıma leke gelmesin diye bunu yapmadım.'),
(2004218,68,26,20,15,'Ben de kendilerine verdiğim en güzel ülkeye, süt ve bal akan ülkeye onları götürmeyeceğime çölde ant içtim.'),
(2004219,68,26,20,16,'Çünkü ilkelerimi reddettiler, kurallarımı izlemediler, Şabat günlerimi hiçe saydılar. Yürekleri putlarına bağlıydı.'),
(2004220,68,26,20,17,'Yine de onlara acıdım, onları yok etmedim, çölde işlerine son vermedim.'),
(2004221,68,26,20,18,'Çölde çocuklarına atalarınızın kurallarını izlemeyin, ilkelerine göre yaşamayın, putlarıyla kendinizi kirletmeyin dedim.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004222,68,26,20,19,'Ben Tanrınız RABbim, benim kurallarımı izleyin, benim ilkelerim uyarınca yaşayın.'),
(2004223,68,26,20,20,'Aramızda bir belirti olsun diye Şabat günlerimi kutsal sayın. O zaman benim Tanrınız RAB olduğumu anlayacaksınız dedim.'),
(2004224,68,26,20,21,'‹‹ ‹Ne var ki, çocuklar bana karşı geldiler. Kurallarımı izlemediler. Uygulayan kişiye yaşam veren ilkelerim uyarınca dikkatle yaşamadılar. Şabat günlerimi hiçe saydılar. Bu yüzden çölde öfkemi üzerlerine yağdıracağımı, kızgınlığımı dökeceğimi söyledim.'),
(2004225,68,26,20,22,'Ama elimi geri çektim, İsraillileri Mısırdan çıkardığımı gören ulusların gözünde adıma leke gelmesin diye bunu yapmadım.'),
(2004226,68,26,20,23,'Onları ulusların arasına dağıtacağıma, başka ülkelere göndereceğime çölde ant içtim.'),
(2004227,68,26,20,24,'Çünkü ilkelerimi izlemediler, kurallarımı reddettiler. Şabat günlerimi hiçe saydılar, gözlerini atalarının putlarına diktiler.'),
(2004228,68,26,20,25,'Ben de onlara iyi olmayan kurallar, yaşam vermeyen ilkeler verdim.'),
(2004229,68,26,20,26,'Her ilk doğan çocuğu ateşte kurban ederek sundukları sunularla kendilerini kirletmelerine izin verdim. Öyle ki, onları dehşete düşüreyim de benim RAB olduğumu anlasınlar.›'),
(2004230,68,26,20,27,'‹‹Bu nedenle, ey insanoğlu, İsrail halkına de ki, ‹Egemen RAB şöyle diyor: Atalarınız yine ihanet etmekle bana küfretmiş oldular.'),
(2004231,68,26,20,28,'Kendilerine vermeye ant içtiğim ülkeye onları getirdiğimde, gördükleri her yüksek tepede, sık yapraklı her ağacın altında kurbanlarını kestiler. Beni öfkelendiren sunularını, güzel kokulu sunularıyla dökmelik sunularını orada sundular.'),
(2004232,68,26,20,29,'Onlara gittikleri bu puta tapılan yerin ne olduğunu sordum.› ›› Orası bugün de Bama adıyla anılıyor.'),
(2004233,68,26,20,30,'‹‹Bu nedenle İsrail halkına de ki, ‹Egemen RAB şöyle diyor: Atalarınız gibi siz de kendinizi kirletecek misiniz? Onların putlarına gönül verecek misiniz?'),
(2004234,68,26,20,31,'Şimdiye dek oğullarınızı ateşte kurban edip sunularınızı sunmakla, putlarınızla kendinizi kirlettiniz. Öyleyken gelip bana danışmanıza izin verir miyim, ey İsrail halkı? Varlığım hakkı için diyor Egemen RAB, bana danışmanıza izin vermeyeceğim.'),
(2004235,68,26,20,32,'‹‹ ‹Siz ağaca, taşa tapan öteki uluslar gibi, dünyadaki öbür halklar gibi olmak istiyoruz diyorsunuz. Ama bu düşündükleriniz hiçbir zaman gerçekleşmeyecek.'),
(2004236,68,26,20,33,'Varlığım hakkı için diyor Egemen RAB, sizi güçlü ve kudretli elle, şiddetli öfkeyle yöneteceğim.'),
(2004237,68,26,20,34,'Güçlü ve kudretli elle, şiddetli öfkeyle sizi uluslar arasından çıkaracak, dağılmış olduğunuz ülkelerden toplayacağım.'),
(2004238,68,26,20,35,'Sizi ulusların çölüne getirecek, orada yüz yüze yargılayacağım.'),
(2004239,68,26,20,36,'Atalarınızı Mısır Çölünde nasıl yargıladıysam, sizi de öyle yargılayacağım. Egemen RAB böyle diyor.'),
(2004240,68,26,20,37,'Sizi yoklayıp antlaşmama bağlı kalmanızı sağlayacağım.'),
(2004241,68,26,20,38,'Aranızda bana karşı gelenlerle başkaldıranları ayıracağım. Onları yaşadıkları ülkelerden çıkaracağım. Ama İsrail ülkesine girmeyecekler. O zaman benim RAB olduğumu anlayacaksınız.'),
(2004242,68,26,20,39,'‹‹ ‹Ey İsrail halkı, Egemen RAB şöyle diyor: Her biriniz gidip putlarınıza tapının! Ama sonra beni dinleyeceksiniz ve armağanlarınızla, putlarınızla bir daha kutsal adımı kirletmeyeceksiniz.'),
(2004243,68,26,20,40,'Çünkü kutsal dağımda, İsrailin yüksek dağında, diyor Egemen RAB, bütün İsrail halkı orada, ülkede bana kulluk edecek. Orada onları kabul edeceğim. Orada sunularınızı, seçme armağanlarınızı, bütün kutsal adaklarınızı isteyeceğim.'),
(2004244,68,26,20,41,'Sizi ulusların arasından çıkarıp dağılmış olduğunuz ülkelerden topladığımda, beni hoşnut eden bir koku gibi kabul edeceğim. Ulusların gözü önünde aranızda kutsallığımı göstereceğim.'),
(2004245,68,26,20,42,'Sizleri atalarınıza vermeye ant içtiğim ülkeye, İsrail ülkesine getirdiğimde, benim RAB olduğumu anlayacaksınız.'),
(2004246,68,26,20,43,'Bütün yaptıklarınızı, kendinizi kirlettiğiniz bütün uygulamaları orada anımsayacak, yaptığınız kötülüklerden ötürü kendinizden tiksineceksiniz.'),
(2004247,68,26,20,44,'Ey İsrail halkı, kötü yollarınıza, yozlaşmış uygulamalarınıza göre değil, adım uğruna sizinle ilgilendiğimde, benim RAB olduğumu anlayacaksınız. Egemen RAB böyle diyor.› ››'),
(2004248,68,26,20,45,'RAB bana şöyle seslendi:'),
(2004249,68,26,20,46,'‹‹İnsanoğlu, yüzünü güneye çevir, güneye seslen, Negev Ormanına karşı peygamberlik et.'),
(2004250,68,26,20,47,'Negev Ormanına de ki, ‹RABbin sözüne kulak ver. Egemen RAB şöyle diyor: Senin içinde ateş tutuşturacağım. Ateş bütün ağaçlarını -yeşil ağacı da kuru ağacı da- yiyip bitirecek. Tutuşan alev söndürülemeyecek. Güneyden kuzeye, her yüz ateşin sıcağından kavrulacak.'),
(2004251,68,26,20,48,'Ateşi tutuşturanın ben RAB olduğumu herkes görecek, ateş söndürülmeyecek.› ››'),
(2004252,68,26,20,49,'Bunun üzerine, ‹‹Ah, ey Egemen RAB!›› dedim, ‹‹Onlar benim için, ‹Simgesel öyküler anlatan adam değil mi bu?› diyorlar.››'),
(2004253,68,26,21,1,'RAB bana şöyle seslendi:'),
(2004254,68,26,21,2,'‹‹Ey insanoğlu, yüzünü Yeruşalime çevir, kutsal yerlerine karşı konuş, İsrail ülkesine karşı peygamberlik et.'),
(2004255,68,26,21,3,'Ona de ki, ‹RAB şöyle diyor: Ben sana karşıyım! Kılıcımı kınından çıkaracak, içindeki doğru kişiyi de kötü kişiyi de kesip yok edeceğim.'),
(2004256,68,26,21,4,'Doğru kişiyi de kötü kişiyi de kesip yok etmek için kılıcım kınından çıkacak ve güneyden kuzeye herkese karşı olacak.'),
(2004257,68,26,21,5,'Böylece herkes kılıcını kınından çıkaranın ben RAB olduğumu anlayacak. Onu bir daha yerine koymayacağım.›'),
(2004258,68,26,21,6,'‹‹Sen, ey insanoğlu, inle! Onların gözü önünde ezik bir yürekle acı acı inle!'),
(2004259,68,26,21,7,'Sana, ‹Neden böyle inliyorsun?› diye sorduklarında, ‹Yakında duyulacak haberden ötürü› diye yanıtlayacaksın. ‹Her yürek eriyecek, her el gevşeyecek, her ruh baygın düşecek, her dizin bağı çözülecek. Evet, haber duyulacak! Bu kesinlikle yerine gelecek.› Egemen RAB böyle diyor.››'),
(2004260,68,26,21,8,'RAB bana şöyle seslendi:'),
(2004261,68,26,21,9,'‹‹İnsanoğlu, peygamberlik et ve de ki, ‹Rab şöyle diyor: ‹‹ ‹Kılıç, kılıç, 2 Bilendi, cilalandı.'),
(2004262,68,26,21,10,'Öldürmek için bilendi, 2 Şimşek gibi çaksın diye cilalandı. 2 Nasıl sevinebiliriz? 2 Kılıç oğlumun asasını sıradan bir sopa gibi küçümsedi.'),
(2004263,68,26,21,11,'Kılıç kullanılmak için 2 Cilalanmaya verildi; 2 Öldürenin eline verilsin diye bilenip cilalandı.'),
(2004264,68,26,21,12,'İnsanoğlu, bağır, haykır! 2 Çünkü bu kılıç halkıma karşı; 2 Bütün İsrail önderlerine karşı. 2 Onlar halkımla birlikte kılıca teslim edildiler. 2 Bunun için bağrını döv.'),
(2004265,68,26,21,13,'‹‹ ‹Deneme kuşkusuz gelecek. Kılıcın küçümsediği asa varlığını sürdüremezse ne olur? Böyle diyor Egemen RAB.›'),
(2004266,68,26,21,14,'‹‹Sen, ey insanoğlu, peygamberlik et, el çırp. 2 Bırak kılıç iki, üç kez vursun. 2 Bu öldüren bir kılıçtır, 2 Çok sayıda insan kıran, 2 İnsanı her yandan saran kılıçtır.'),
(2004267,68,26,21,15,'Yürekleri erisin, 2 Tökezleyip düşenler çok olsun diye 2 Bütün kapılarında öldürmek için 2 Görevlendirdim kılıcı. 2 Ah, kılıç şimşek gibi parladı, 2 Öldürmek için bilendi.'),
(2004268,68,26,21,16,'Ey kılıç, sağa, sonra sola savrul, 2 Ağzın nereye dönerse, oraya savrul!'),
(2004269,68,26,21,17,'Ben de elimi çırpacağım 2 Ve öfkem dinecek. 2 Bunu ben RAB söylüyorum.››'),
(2004270,68,26,21,18,'RAB bana şöyle seslendi:'),
(2004271,68,26,21,19,'‹‹İnsanoğlu, Babil Kralının kılıcı gelsin diye iki yol belirle; ikisi de aynı ülkeden başlamalı. Kent yolunun başladığı yere bir işaret koy.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004272,68,26,21,20,'Ammonluların Rabba Kentine ya da Yahudaya ve surlarla çevrili Yeruşalime ilerlesin diye kılıç için yol belirle.'),
(2004273,68,26,21,21,'Çünkü Babil Kralı iki yolun ayrıldığı, yolların çatallaştığı yerde fala bakmak için duracak. Okları silkeleyecek, aile putlarına danışacak, kurban edilen bir hayvanın ciğerine bakacak.'),
(2004274,68,26,21,22,'Kütük yerleştirmek, öldür buyruğunu vermek, savaş naraları atmak, kapılara kütük yerleştirmek, toprak rampalar oluşturmak, kuşatma duvarları yapmak için sağ elinde Yeruşalimi gösteren ok olacak.'),
(2004275,68,26,21,23,'Onunla ant içerek antlaşma yapanlar fala yanlış bakıldığını sanacak. Ama kral suçlarını anımsatıp onları tutsak alacak.'),
(2004276,68,26,21,24,'‹‹Bundan ötürü Egemen RAB şöyle diyor: ‹Madem suçlarınızı, isyanlarınızı anımsattırdınız, bütün uygulamalarınızda günahlarınızı açığa çıkardınız, madem bütün bunları yaptınız, siz de tutsak alınıp götürüleceksiniz.'),
(2004277,68,26,21,25,'‹‹ ‹Sen, ey saygısız, kötü İsrail önderi, günün yaklaştı, sonunda yargı günün geldi.'),
(2004278,68,26,21,26,'Egemen RAB şöyle diyor: Sarığı çıkar, tacı kaldır. Artık eskisi gibi olmayacak. Alçakgönüllü yükseltilecek, gururlu alçaltılacak.'),
(2004279,68,26,21,27,'Yıkım! Yıkım! Kenti yerle bir edeceğim! Hak sahibi gelinceye dek onarılmayacak. Kenti ona vereceğim.›'),
(2004280,68,26,21,28,'‹‹Sen, ey insanoğlu, peygamberlik et ve de ki, ‹Aşağılayıcı sözler söyleyen Ammonlular için Egemen RAB şöyle diyor: ‹‹ ‹Kılıç, kılıç, 2 Öldürmek için kınından çekilmiş, 2 Yok etmek için, 2 Şimşek gibi parlamak için cilalanmış!'),
(2004281,68,26,21,29,'Size ilişkin görümler aldatıcıdır, 2 Açılan fal yalandır. 2 Öldürülecek kötülerin enseleri üzerine 2 Yerleştirileceksin, ey kılıç! 2 Onların günü yaklaştı, 2 Sonunda yargı günleri geldi.'),
(2004282,68,26,21,30,'Kılıç kınına koyulsun! 2 Yaratıldığınız yerde, 2 Atalarınızın ülkesinde 2 Yargılayacağım sizi.'),
(2004283,68,26,21,31,'Öfkemi üzerinize dökeceğim, 2 Kızgınlığımı üzerinize üfleyeceğim; 2 Acımasız adamların, 2 Yakıp yok etmekte usta kişilerin eline 2 Teslim edeceğim sizi.'),
(2004284,68,26,21,32,'Ateşe yakıt olacaksınız, 2 Kanınız ülkenizin ortasında dökülecek, 2 Bir daha anılmayacaksınız. 2 Çünkü bunu ben RAB söylüyorum.› ››'),
(2004285,68,26,22,1,'RAB bana şöyle seslendi:'),
(2004286,68,26,22,2,'‹‹İnsanoğlu, Yeruşalimi yargılayacak mısın? Kan döken bu kenti yargılayacak mısın? Öyleyse bütün iğrenç uygulamalarını ona bildir.'),
(2004287,68,26,22,3,'Şöyle diyeceksin: ‹Egemen RAB diyor ki: Ey kendi içinde kan dökerek yıkımını hazırlayan, putlar yaparak kendini kirleten kent!'),
(2004288,68,26,22,4,'Döktüğün kan yüzünden suçlu bulundun, yaptığın putlarla kirlendin. Böylece günlerin yaklaştı, yıllarının sonuna ulaştın. Bu yüzden seni uluslara alay konusu edeceğim, bütün ülkelerin gözünde seni gülünç duruma düşüreceğim.'),
(2004289,68,26,22,5,'Ey adı kötüye çıkmış, kargaşa dolu kent, yakındakiler de uzaktakiler de seninle alay edecekler.'),
(2004290,68,26,22,6,'‹‹ ‹İşte içindeki her İsrail önderi yetkisini kullanarak kan döküyor.'),
(2004291,68,26,22,7,'Senin içinde anneye, babaya kötü davrandılar, yabancıya baskı yaptılar, öksüze, dul kadına haksızlık ettiler.'),
(2004292,68,26,22,8,'Benim kutsal eşyalarıma saygısızlık ettin, Şabat günlerimi hiçe saydın.'),
(2004293,68,26,22,9,'Kan dökmek için iftira edenler, dağlarda putlara kurban edilen hayvanları yiyenler, kendilerini şehvete kaptıranlar senin içinde yaşıyor.'),
(2004294,68,26,22,10,'Babalarının karılarıyla yatanlar, âdet gören dinsel açıdan kirli kadınlarla cinsel ilişki kuranlar senin içinde yaşıyor.'),
(2004295,68,26,22,11,'Senin içinde kimi komşusunun karısıyla iğrenç şeyler yaptı; kimi utanmadan gelinini kirletti; kimi öz kızkardeşiyle ilişki kurdu.'),
(2004296,68,26,22,12,'Senin içinde kan dökmek için rüşvet aldılar. Faiz aldın, tefecilik yaptın, zorbalıkla komşularından haksız kazanç sağladın. Beni unuttun. Egemen RAB böyle diyor.'),
(2004297,68,26,22,13,'‹‹ ‹Edindiğiniz haksız kazançtan, içinizde döktüğünüz kandan ötürü ellerimi birbirine vuracağım.'),
(2004298,68,26,22,14,'Sizinle uğraşacağım gün cesaretiniz kalacak mı? Elleriniz güçlü olabilecek mi? Bunu ben RAB söylüyorum ve dediğimi yapacağım.'),
(2004299,68,26,22,15,'Sizi uluslar arasına dağıtıp ülkelere süreceğim. Sizdeki ruhsal kirliliğe son vereceğim.'),
(2004300,68,26,22,16,'Ulusların gözünde aşağılanacak ve benim RAB olduğumu anlayacaksınız.› ››'),
(2004301,68,26,22,17,'RAB bana şöyle seslendi:'),
(2004302,68,26,22,18,'‹‹İnsanoğlu, İsrail halkı benim için cüruf gibi oldu. Hepsi potada tunç, kalay, demir, kurşundur; gümüşün cürufudur.'),
(2004303,68,26,22,19,'Bundan ötürü Egemen RAB şöyle diyor: ‹Hepiniz cüruf gibi olduğunuz için sizi Yeruşalimin ortasına toplayacağım.'),
(2004304,68,26,22,20,'Eritmek için ateşi üfleyerek gümüşü, tuncu, demiri, kurşunu, kalayı nasıl potaya atıyorlarsa, ben de öfkemle, kızgınlığımla sizi toplayacak, kentin ortasına koyup eriteceğim.'),
(2004305,68,26,22,21,'Sizi toplayacak, öfkemin ateşini üzerinize üfleyeceğim; siz de kentin içinde eriyip yok olacaksınız.'),
(2004306,68,26,22,22,'Gümüş potada nasıl erirse, siz de kentin içinde öyle eriyeceksiniz. O zaman üzerinize kızgınlığını dökenin ben, RAB olduğumu anlayacaksınız.› ››'),
(2004307,68,26,22,23,'RAB bana şöyle seslendi:'),
(2004308,68,26,22,24,'‹‹İnsanoğlu, ülkeye de ki, ‹Sen öfke günü temizlenmemiş, üzerine yağmur yağmamış bir ülkesin.›'),
(2004309,68,26,22,25,'Önderleri kükreyen, avını parçalayan aslan gibi orada düzen kurdular. Canlara kıydılar, hazineler, değerli nesneler aldılar, birçok kadını dul bıraktılar.'),
(2004310,68,26,22,26,'Kâhinleri yasamı hiçe saydılar, kutsal eşyalarımı kirlettiler, kutsalla bayağı arasındaki ayrımı yapmadılar, kirliyle temiz arasındaki farkı öğretmediler, Şabat günlerimden gözlerini çevirdiler. Kutsallığımı önemsemediler.'),
(2004311,68,26,22,27,'Yöneticileri avını parçalayan kurt gibidir. Haksız kazanç elde etmek için kan döküyor, canlara kıyıyorlar.'),
(2004312,68,26,22,28,'Peygamberleri uydurma görümlerle, yalan fal açarak bu suçları gizlediler; ben RAB konuşmadığım halde, ‹Egemen RAB şöyle diyor› diyorlar.'),
(2004313,68,26,22,29,'Ülke halkı baskı uyguladı, soygunculuk etti. Düşküne, yoksula baskı yaptı, yabancıya haksız yere kötü davrandı. ‹‹Peygamberleri››.'),
(2004314,68,26,22,30,'‹‹İçlerinde duvarı örecek, gedikte durup önümde ülkeyi savunacak, onu yerle bir etmemi engelleyecek bir adam aradım, ama hiç kimseyi bulmadım.'),
(2004315,68,26,22,31,'Bunun için öfkemi üzerlerine boşaltacak, kızgınlığımla onları yakıp yok edeceğim. Yaptıklarını kendi başlarına getireceğim.›› Egemen RAB böyle diyor.'),
(2004316,68,26,23,1,'RAB bana şöyle seslendi:'),
(2004317,68,26,23,2,'‹‹İnsanoğlu, bir anneden doğma iki kadın vardı.'),
(2004318,68,26,23,3,'Gençliklerinde Mısırda fahişelik ettiler. Memeleri orada okşandı, erdenliklerini orada yitirdiler.'),
(2004319,68,26,23,4,'Büyüğünün adı Ohola, küçüğünün Oholivaydı. Benim oldular; oğullar, kızlar doğurdular. Ohola Samiriyedir, Oholiva da Yeruşalim.'),
(2004320,68,26,23,5,'‹‹Ohola benimken fahişelik etti. Oynaşları olan Asurlulara gönül verdi. Hepsi de genç, yakışıklı, lacivertler kuşanmış savaşçılar, valiler, komutanlar, atlı askerlerdi.'),
(2004321,68,26,23,7,'Asurluların en seçkin adamlarına fahişe olarak kendini verdi. Gönül verdiği bu kişilerin putlarına bağlanarak kendini kirletti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004322,68,26,23,8,'Mısırda başladığı fahişeliği bırakmadı. Gençken onunla yattılar, erdenliğini bozdular, şehvetlerini onun üzerine boşalttılar.'),
(2004323,68,26,23,9,'‹‹Bu nedenle onu oynaşlarının, gönül verdiği Asurluların eline teslim ettim.'),
(2004324,68,26,23,10,'Çıplaklığını açtılar, oğullarını, kızlarını aldılar, onu kılıçla öldürdüler. Kendisine verilen cezadan ötürü kadınlar arasında adı kötüye çıktı.'),
(2004325,68,26,23,11,'‹‹Kızkardeşi Oholiva bunu gördü, ama şehveti ve fahişelikleri kızkardeşininkinden daha utanç vericiydi.'),
(2004326,68,26,23,12,'O da hepsi de genç, yakışıklı Asurlulara -valilere, komutanlara, iyi donanmış savaşçılara, atlılara- gönül verdi.'),
(2004327,68,26,23,13,'Kendisini ne kadar kirlettiğini gördüm. İkisi de aynı yolu izlediler.'),
(2004328,68,26,23,14,'‹‹Oholiva fahişeliklerini giderek artırdı. Duvara oyulmuş insan resimlerini -bellerine kuşak, başlarına geniş sarık bağlamış kırmızı renkli Kildani resimlerini- gördü. Hepsi kökeni Kildan ülkesine dayanan Babil subaylarına benziyordu.'),
(2004329,68,26,23,16,'Oholiva görür görmez onlara gönül verdi, Kildan ülkesine ulaklar gönderdi.'),
(2004330,68,26,23,17,'Bunun üzerine Babilliler onunla yatakta sevişmek üzere geldiler, zina ederek onu kirlettiler. Onu öyle kirlettiler ki, sonunda hepsinden tiksinip yüzünü çevirdi.'),
(2004331,68,26,23,18,'Fahişeliklerini sergileyip çıplaklığını açınca kızkardeşinden tiksinerek yüzümü çevirdiğim gibi, ondan da tiksinerek yüzümü çevirdim.'),
(2004332,68,26,23,19,'Gençliğinde Mısırda yaptığı fahişelikleri anımsayarak, fahişeliğini daha da artırdı.'),
(2004333,68,26,23,20,'Erkeklik organları eşeğinkine, menileri aygırınkine benzeyen oynaşlarına gönül verdi.'),
(2004334,68,26,23,21,'Öyle ki, Mısırda gençliğindeki şehvet düşkünlüğünü özledin. Memelerin orada okşanmış, erdenliğini orada yitirmiştin.'),
(2004335,68,26,23,22,'‹‹Bundan ötürü, ey Oholiva, Egemen RAB şöyle diyor: Tiksindiğin oynaşlarını sana karşı kışkırtacağım. Onları her yandan sana karşı ayaklandıracağım.'),
(2004336,68,26,23,23,'Babillileri, bütün Kildanileri, Pekotluları, Şoalıları, Koalıları, onlarla birlikte bütün Asurluları, yakışıklı gençleri -valileri, komutanları, subayları, ünlü adamları, atlıları- sana karşı ayaklandıracağım.'),
(2004337,68,26,23,24,'Silahlarla, savaş ve yük arabalarıyla, çok uluslu bir orduyla sana saldıracaklar. Seni her yandan büyük, küçük kalkanlarla, miğferlerle saracaklar. Cezalandırmaları için seni onların eline teslim edeceğim. Seni kendi kurallarına göre yargılayacaklar.'),
(2004338,68,26,23,25,'Öfkemi sana yönelteceğim, onların sana kızgınlıkla davranmalarını sağlayacağım. Burnunu, kulaklarını kesecekler. Sağ kalanları kılıçla öldürecekler. Oğullarını, kızlarını alacaklar, sağ kalanları ateş yakıp yok edecek.'),
(2004339,68,26,23,26,'Üzerindeki giysiyi soyacak, güzel mücevherlerini alacaklar.'),
(2004340,68,26,23,27,'Mısırda yaptığın ahlaksızlıklara, fahişeliklere son vereceğim. Böyle şeylere özlem duymayacak, bir daha Mısırı anımsamayacaksın.'),
(2004341,68,26,23,28,'‹‹Egemen RAB şöyle diyor: Seni nefret ettiğin, tiksindiğin adamların eline teslim edeceğim.'),
(2004342,68,26,23,29,'Sana düşman gibi davranacak, emeğinin bütün ürününü alacaklar. Seni çırılçıplak bırakacaklar. Böylece utanç verici fahişeliklerin açığa çıkacak. Bütün bunlar şehvet düşkünlüğünden, fahişeliğin yüzünden başına geldi. Çünkü uluslarla fahişelik ettin, onların putlarıyla kendini kirlettin.'),
(2004343,68,26,23,31,'Kızkardeşinin yolunu izledin. Bu nedenle, sana onun kâsesinden içireceğim.'),
(2004344,68,26,23,32,'‹‹Egemen RAB şöyle diyor: Kızkardeşinin kâsesinden içeceksin, 2 O derin ve geniştir; 2 Sana gülecek, seninle alay edecekler, 2 Dopdolu bir kâse.'),
(2004345,68,26,23,33,'Sarhoş olacak, umutsuzluğa boğulacaksın, 2 Kızkardeşin Samiriyenin kâsesi 2 Yıkım, perişanlık kâsesidir.'),
(2004346,68,26,23,34,'Ondan içecek, tüketeceksin; 2 Parçalarını kemirecek 2 Ve göğsünü paralayacaksın. 2 Bunu ben söylüyorum diyor Egemen RAB.'),
(2004347,68,26,23,35,'‹‹Bundan ötürü Egemen RAB şöyle diyor: Madem beni unuttun, bana sırt çevirdin, sen de ahlaksızlığının, fahişeliğinin cezasını yükleneceksin.››'),
(2004348,68,26,23,36,'RAB bana seslendi: ‹‹İnsanoğlu, Oholayla Oholivayı yargılayacak mısın? Öyleyse onlara iğrenç uygulamalarını bildir.'),
(2004349,68,26,23,37,'Çünkü fahişelik ettiler, kan döktüler. Putlarıyla fahişelik ettiler; bana doğurdukları çocukları yiyecek olarak putlarına sundular.'),
(2004350,68,26,23,38,'Bununla kalmayarak, şunları da yaptılar: Çocuklarını putlara sundukları gün tapınağımı kirlettiler, Şabat günlerimi hiçe saydılar. Aynı gün tapınağıma girip onu kirlettiler. İşte tapınağımda bunları yaptılar.'),
(2004351,68,26,23,40,'‹‹Siz iki kızkardeş uzaklarda yaşayan adamların gelmesi için ulaklar gönderdiniz. Adamlar gelince, onlar için yıkanıp gözlerinize sürme çektiniz, mücevherlerinizi taktınız.'),
(2004352,68,26,23,41,'Şık bir divanın üzerine oturdunuz, önüne bir sofra kurup üzerine buhurumu, zeytinyağımı koydunuz.'),
(2004353,68,26,23,42,'‹‹Kaygısız kalabalığın sesi yankılandı çevresinde. Düzeysiz bir yığın kalabalıkla birlikte çölden Sabalılar getirildi. İki kızkardeşin koluna bilezikler taktılar, başlarına güzel bir taç koydular.'),
(2004354,68,26,23,43,'Fahişelikten yıpranmış kadın için, ‹Bırakın, fahişe olarak kullansınlar onu. Çünkü öyledir› dedim.'),
(2004355,68,26,23,44,'Onunla yattılar. Fahişeye gider gibi, bu iki ahlaksız kadının -Oholayla Oholivanın- yanına gittiler.'),
(2004356,68,26,23,45,'Ama doğru adamlar zina eden, kan döken kadınlara verilen cezayla onları cezalandıracaklar. Çünkü bu iki kadın fahişelik ettiler, elleri kanlıdır.'),
(2004357,68,26,23,46,'‹‹Egemen RAB şöyle diyor: Onları dehşete düşürecek, mallarını yağmalayacak bir kalabalık salacağım üzerlerine.'),
(2004358,68,26,23,47,'Onları taşa tutacak, kılıçlarıyla parçalayacaklar; oğullarını, kızlarını öldürecek, evlerini ateşe verecekler.'),
(2004359,68,26,23,48,'‹‹Ülkede ahlaksızlığa son vereceğim. Öyle ki, bütün kadınlar için bir uyarı olsun bu, sizin yaptığınız ahlaksızlığı yapmasınlar.'),
(2004360,68,26,23,49,'Yaptığınız fahişeliklerin karşılığını ödeyecek, putlara tapınarak işlediğiniz günahların cezasını çekeceksiniz. Böylece benim Egemen RAB olduğumu anlayacaksınız.››'),
(2004361,68,26,24,1,'Sürgünlüğümüzün dokuzuncu yılı, onuncu ayın onuncu günü RAB bana şöyle seslendi:'),
(2004362,68,26,24,2,'‹‹Ey insanoğlu, bu günü, bu günün tarihini tam olarak yaz. Çünkü Babil Kralı tam bu gün Yeruşalimi kuşatmaya başladı.'),
(2004363,68,26,24,3,'Bu asi halka simgesel bir öykü anlat. Onlara de ki, ‹Egemen RAB şöyle diyor: ‹‹ ‹Kazanı ateşe koyun, ateşe koyun, 2 İçine su doldurun.'),
(2004364,68,26,24,4,'Etin parçalarını da koyun, 2 Etin en iyi parçalarını, 2 Budu ve döşü. 2 Seçme kemikleri de doldurun.'),
(2004365,68,26,24,5,'Sürünün en iyilerini seçin, 2 Kazanın altına odun yığın, 2 Bırakın su kaynasın, 2 Kemikler pişsin.'),
(2004366,68,26,24,6,'Egemen RAB diyor ki, 2 Kan döken o kentin vay başına! 2 Pas tutmuş, 2 Pasından temizlenmemiş o kazanın vay başına! 2 Kazandan eti kura çekmeden 2 Parça parça çıkarın.'),
(2004367,68,26,24,7,'Çünkü döktüğü kan ortalıkta duruyor; 2 Çıplak bir kayanın üzerine döktü kanı, 2 Toprakla örtülebilecek bir yere dökmedi.'),
(2004368,68,26,24,8,'Öfkeyi alevlendirmek, 2 Öç almak için, 2 Onun kanını çıplak bir kayanın üzerine döktüm ki, örtülemesin.'),
(2004369,68,26,24,9,'Egemen RAB şöyle diyor: 2 Kan döken kentin vay başına! 2 Ben kendim ateş için odun yığacağım.'),
(2004370,68,26,24,10,'Odunları yığ! 2 Ateşi tutuştur! 2 Eti iyice pişir! 2 Baharatı kat! 2 Kemikler kavrulsun!'),
(2004371,68,26,24,11,'Sonra boş kazanı 2 Ateş közlerinin üzerine koy. 2 Kızsın, bakırı yansın, 2 İçindeki pislik erisin, 2 Pası yok olsun.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004372,68,26,24,12,'Bütün emekler boşa çıktı, 2 Kazanın kalın pası çıkmıyor. 2 Ateş bile pası temizlemiyor.'),
(2004373,68,26,24,13,'Yaptığın ahlaksızlık seni kirletti. 2 Seni temizlemek istedim, 2 Ama sen pisliğinden temizlenmek istemedin. 2 Sana karşı öfkem yatışıncaya dek 2 Pisliğinden temizlenmeyeceksin.'),
(2004374,68,26,24,14,'Bunu ben RAB söylüyorum. 2 Harekete geçmenin zamanı geldi, 2 Esirgemeyeceğim, 2 Acımayacak, pişman olmayacağım. 2 Yollarına ve yaptıklarına göre yargılanacaksın. 2 Böyle diyor Egemen RAB.› ››'),
(2004375,68,26,24,15,'RAB bana şöyle seslendi:'),
(2004376,68,26,24,16,'‹‹İnsanoğlu, en çok sevdiğin kişiyi bir vuruşta senin elinden alacağım. Yas tutmayacak, ağlamayacak, gözyaşı dökmeyeceksin.'),
(2004377,68,26,24,17,'İçin için inle; ölüler için yas tutmayacaksın. Sarığın başında, çarığın ayaklarında kalsın; yüzünün alt kısmını örtme, yas tutanların yiyeceğini yeme.››'),
(2004378,68,26,24,18,'Sabah halka seslendim, akşam karım öldü. Ertesi sabah bana söyleneni yaptım.'),
(2004379,68,26,24,19,'Halk bana, ‹‹Bu yaptıklarının bizimle ilgisi ne? Bize açıklamayacak mısın?›› diye sordu.'),
(2004380,68,26,24,20,'Bunun üzerine, ‹‹RAB bana şöyle seslendi›› dedim,'),
(2004381,68,26,24,21,'‹‹İsrail halkına de ki, ‹Egemen RAB şöyle diyor: Övündüğünüz güç kaynağınız, gözünüzde değerli olan, yüreğinizin üzerine titrediği tapınağımın kirletilmesine izin vereceğim. Geride bıraktığınız oğullarınızla kızlarınız kılıçtan geçirilecek.'),
(2004382,68,26,24,22,'Ben ne yaptıysam, siz de aynısını yapacaksınız. Yüzünüzün alt kısmını örtmeyeceksiniz, yas tutanların yiyeceğini yemeyeceksiniz.'),
(2004383,68,26,24,23,'Sarıklarınız başlarınızda, çarıklarınız ayaklarınızda olacak. Yas tutmayacak, ağlamayacaksınız. Ancak günahlarınızın içinde eriyip yok olacaksınız, kendi aranızda inleyip duracaksınız.'),
(2004384,68,26,24,24,'Hezekiel sizin için bir belirti olacak; o ne yaptıysa, siz de aynısını yapacaksınız. Bunlar olunca, benim Egemen RAB olduğumu anlayacaksınız.› ‹‹İnsanların››.'),
(2004385,68,26,24,25,'‹‹Övündükleri güç kaynağını, sevinçlerini, yüceliklerini, gözlerinde değerli olanı, yüreklerinin dilediğini, oğullarıyla kızlarını onlardan aldığım gün, yıkımdan kaçıp kurtulan biri gelip sana haberleri bildirecek, ey insanoğlu.'),
(2004386,68,26,24,27,'O gün dilin çözülecek, kaçıp kurtulanla konuşacak, bir daha suskun olmayacaksın. O gün onlar için bir belirti olacaksın. O zaman benim RAB olduğumu anlayacaklar.››'),
(2004387,68,26,25,1,'RAB bana şöyle seslendi:'),
(2004388,68,26,25,2,'‹‹İnsanoğlu, yüzünü Ammonlulara çevir, onlara karşı peygamberlik et.'),
(2004389,68,26,25,3,'Onlara de ki, ‹Egemen RABbin sözünü dinleyin! Egemen RAB şöyle diyor: Madem tapınağım kirletildiği, İsrail ülkesi viraneye çevrildiği, Yahuda halkı sürgüne gittiği zaman, Hah, hah! diyerek alay ettiniz,'),
(2004390,68,26,25,4,'ben de sizi miras olarak doğuda yaşayan halka teslim edeceğim. Obalarını, çadırlarını ülkenizde kuracaklar; ürününüzü yiyecek, sütünüzü içecekler.'),
(2004391,68,26,25,5,'Rabba Kentini develer için otlak, Ammon ülkesini sürüler için ağıl yapacağım. O zaman benim RAB olduğumu anlayacaksınız.'),
(2004392,68,26,25,6,'Egemen RAB şöyle diyor: Madem İsraille alay ederek ellerinizi çırptınız, ayaklarınızı yere vurdunuz, bütün yüreğinizle sevindiniz,'),
(2004393,68,26,25,7,'ben de size karşı elimi uzatacak, çapul malı olarak sizi uluslara teslim edeceğim. Sizi halklar arasından süpürüp atacak, ülkeler arasından söküp çıkaracak, yok edeceğim. O zaman benim RAB olduğumu anlayacaksınız.› ››'),
(2004394,68,26,25,8,'‹‹Egemen RAB şöyle diyor: ‹Madem Moav ve Seir halkı, Bakın, Yahuda halkının öteki uluslardan farkı yok, dedi,'),
(2004395,68,26,25,9,'ben de Moavın sınırını, ülkenin süsü olan sınır kentlerini, Beytyeşimot, Baal-Meon ve Kiryatayimi savunmasız bırakacağım.'),
(2004396,68,26,25,10,'Ammonlular uluslar arasında bir daha anılmasın diye Moavı Ammonlularla birlikte mülk olarak doğuda yaşayan halka vereceğim.'),
(2004397,68,26,25,11,'Böylece Moavı cezalandıracağım. O zaman benim RAB olduğumu anlayacaklar.› ››'),
(2004398,68,26,25,12,'‹‹Egemen RAB şöyle diyor: ‹Madem Edom Yahuda halkından öç alarak büyük suç işledi,'),
(2004399,68,26,25,13,'Egemen RAB şöyle diyor: Ben de Edoma karşı elimi uzatacak, insanları da hayvanları da yok edecek, ülkeyi viraneye çevireceğim. Temandan Dedana kadar Edomlular kılıçla vurulup yok olacaklar.'),
(2004400,68,26,25,14,'Halkım İsrail aracılığıyla Edomdan öç alacağım. İsrailliler onlara öfkem, kızgınlığım uyarınca davranacak. Böylece Edomlular öcümü anlayacaklar. Egemen RAB böyle diyor.› ››'),
(2004401,68,26,25,15,'‹‹Egemen RAB şöyle diyor: ‹Madem Filistliler Yahudaya acımasızca davrandılar, eskiden var olan düşmanlıklarıyla onu yerle bir ederek öç aldılar,'),
(2004402,68,26,25,16,'Egemen RAB şöyle diyor: Elimi Filistlilere karşı uzatacağım, Keretlileri söküp atacağım, kıyıda yaşayanlardan sağ kalanlarını yok edeceğim.'),
(2004403,68,26,25,17,'Onlardan ağır bir öç alacak, onları öfkeyle paylayacağım. Kendilerinden öç alınca, benim RAB olduğumu anlayacaklar.› ››'),
(2004404,68,26,26,1,'Sürgünlüğümüzün on birinci yılı, ayın birinci günü RAB bana şöyle seslendi:'),
(2004405,68,26,26,2,'‹‹İnsanoğlu, madem Sur Kenti, Yeruşalim için, ‹Oh, oh! Ulusların kapısı olan kent yıkıldı, kapıları bana açıldı. O viraneye döndü, ben zenginleşeceğim› dedi,'),
(2004406,68,26,26,3,'Egemen RAB şöyle diyor: Ey Sur, sana karşıyım! Deniz dalgalarını nasıl kabartırsa, ben de ulusları senin üzerine öyle saldırtacağım.'),
(2004407,68,26,26,4,'Surun duvarlarını yıkacak, kulelerini yerle bir edecekler. Toprağını kazıp süpürecek, seni çıplak bir kayalık haline getireceğim.'),
(2004408,68,26,26,5,'Sur denizin ortasında, balıkçıların ağ gerdikleri bir yer olacak. Egemen RAB böyle diyor. Uluslar Suru yağmalayacak,'),
(2004409,68,26,26,6,'Sura bağlı kıyı kentlerinde yaşayanları kılıçtan geçirecek. O zaman Surlular benim RAB olduğumu anlayacaklar.'),
(2004410,68,26,26,7,'‹‹Egemen RAB şöyle diyor: Krallar kralı Babil Kralı Nebukadnessarı atlarla, savaş arabalarıyla, atlılarla, büyük bir orduyla kuzeyden Sura getiriyorum.'),
(2004411,68,26,26,8,'Sura bağlı kıyı kentlerinde yaşayanları kılıçtan geçirecek, size karşı kuşatma duvarları, toprak rampalar yapacak, kalkanını size karşı kaldıracak.'),
(2004412,68,26,26,9,'Duvarlarınızda gedik açmak için kütükler yerleştirecek, silahlarıyla kulelerinizi yıkacak.'),
(2004413,68,26,26,10,'Sayısız atının çıkardığı toz sizi örtecek. Duvarlarında gedik açılmış bir kente girer gibi kent kapılarınızdan girdiğinde, atlıların, tekerleklerin, savaş arabalarının gürültüsünden duvarlarınız sarsılacak.'),
(2004414,68,26,26,11,'Atlarının tırnakları bütün sokaklarınızı çiğneyecek. Halkınız kılıçtan geçirilecek, güçlü sütunlarınız devrilecek.'),
(2004415,68,26,26,12,'Servetinizi alacak, mallarınızı yağmalayacaklar. Duvarlarınızı yıkacak, güzel evlerinizi yerle bir edecekler. Taşlarınızı, kerestenizi, toprağınızı denize atacaklar.'),
(2004416,68,26,26,13,'Okuduğunuz gürültülü şarkılara son vereceğim. Lirlerinizin sesi bir daha duyulmayacak.'),
(2004417,68,26,26,14,'Sizi çıplak bir kayalık haline getireceğim, balıkçıların ağ gerdikleri bir yer olacaksınız. Bir daha kurulmayacaksınız. Çünkü ben RAB söylüyorum. Egemen RAB böyle diyor.'),
(2004418,68,26,26,15,'‹‹Egemen RAB Sura şöyle diyor: Yıkımının sesinden, yaralıların iniltisinden, senin içinde yapılan kıyım yüzünden kıyı halkları titreyecek.'),
(2004419,68,26,26,16,'Kıyıda yaşayan bütün önderler tahtlarından inecek; kaftanlarını, işlemeli giysilerini çıkaracaklar. Dehşet içinde yere oturup her an titreyerek başlarına gelenlere şaşacaklar.'),
(2004420,68,26,26,17,'Sonra senin için şöyle bir ağıt yakacaklar: ‹‹ ‹Nasıl oldu da yıkıldın, 2 Ey denizcilerin oturduğu ünlü kent! 2 Sen ve sende oturanlar, 2 Denizde güçlüydünüz. 2 Dehşet salmıştınız 2 Orada yaşayan herkese.'),
(2004421,68,26,26,18,'Yıkımın olduğu gün 2 Kıyı halkları titreyecek, 2 Orada yaşayanlar 2 Çöküşüne şaşacaklar.›');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004422,68,26,26,19,'‹‹Egemen RAB şöyle diyor: Issız kalmış kentler gibi seni viran bir kent yaptığım, engin denizleri üzerine boşalttığım, derin sular seni örttüğü zaman,'),
(2004423,68,26,26,20,'ölüm çukuruna inenlerle birlikte seni eski zaman insanlarının yanına indireceğim. Ölüm çukuruna inenlerle birlikte eski kalıntılar arasına, yeryüzünün derinliklerine yerleştireceğim. Öyle ki, bir daha dönüp yaşayanlar diyarında yerini almayasınfö.'),
(2004424,68,26,26,21,'Seni yılgınlığa düşüreceğim, bu senin sonun olacak. Seni arayacaklar ama bulamayacaklar. Egemen RAB böyle diyor.›› almayasın›› (bkz. Septuaginta), Masoretik metin ‹‹Dönmeyesin, yaşayanlar diyarında yücelik vereyim››.'),
(2004425,68,26,27,1,'RAB bana şöyle seslendi:'),
(2004426,68,26,27,2,'‹‹İnsanoğlu, Sur Kenti için bir ağıt yak.'),
(2004427,68,26,27,3,'Denizin kıyısında kurulmuş, kıyı halklarıyla ticaret yapan Sur Kentine de ki, ‹Egemen RAB şöyle diyor: ‹‹ ‹Ey Sur, güzellikte kusursuzum dedin.'),
(2004428,68,26,27,4,'Sınırların denizin bağrındaydı, 2 Kurucuların güzelliğini doruğa ulaştırdılar.'),
(2004429,68,26,27,5,'Bütün kerestelerini 2 Senirin çam ağaçlarından yaptılar, 2 Sana direk yapmak için 2 Lübnandan sedir ağaçları aldılar.'),
(2004430,68,26,27,6,'Küreklerini Başan meşelerinden, 2 Güverteni Kittim kıyılarından getirilen 2 Selvi ağaçlarından yaptılar, 2 Fildişiyle süslediler.'),
(2004431,68,26,27,7,'Mısırın işlemeli ince keteninden yelkenin, 2 Bayrağın oldu senin. 2 Güvertenin gölgeliği Elişa kıyılarının 2 Lacivert, mor kumaşındandı.'),
(2004432,68,26,27,8,'Kürekçilerin Saydalı ve Arvatlıydı, 2 Gemicilerin, içindeki becerikli kişilerdi, ey Sur.'),
(2004433,68,26,27,9,'Gemilerindeki gedikleri onaranlar 2 Gevalın deneyimli, usta adamlarıydı. 2 Denizdeki bütün gemiler ve denizciler 2 Mallarını değiş tokuş etmek için sana geldiler.'),
(2004434,68,26,27,10,'Persli, Ludlu, Pûtlu askerler 2 Ordunda hizmet etti. 2 Kalkanlarını, miğferlerini 2 Duvarlarına astılar, 2 Sana görkem kazandırdılar.'),
(2004435,68,26,27,11,'Arvattan, Helekten gelen adamlar 2 Çepeçevre duvarlarını korudular. 2 Gammattan gelen adamlar 2 Kulelerinde beklediler. 2 Kalkanlarını duvarlarına astılar. 2 Güzelliğini doruğa ulaştırdılar.'),
(2004436,68,26,27,12,'‹‹ ‹Tarşiş seninle ticaret yaptı, 2 Sende her çeşit mal vardı. 2 Mallarına karşılık 2 Sana gümüş, demir, kalay, kurşun verdiler.'),
(2004437,68,26,27,13,'Yâvan, Tuval, Meşek seninle ticaret yaptı, 2 Mallarına karşılık 2 Sana köle ve tunç kaplar verdiler.'),
(2004438,68,26,27,14,'Beyttogarma halkı 2 Mallarına karşılık 2 Sana at, savaş atı, katır verdi.'),
(2004439,68,26,27,15,'Rodos halkı seninle ticaret yaptı. 2 Birçok kıyı halkı senin müşterindi. 2 Senden aldıkları mala karşılık 2 Fildişi ve abanoz verdiler.'),
(2004440,68,26,27,16,'Sende çok çeşit ürün olduğundan, 2 Edom seninle ticaret yaptı. 2 Mallarına karşılık 2 Sana firuze, mor kumaş, işlemeli giysiler, 2 İnce keten, mercan, yakut verdiler.'),
(2004441,68,26,27,17,'Yahuda ve İsrail seninle ticaret yaptı. 2 Mallarına karşılık 2 Sana Minnit buğdayı, darı, bal, zeytinyağı, pelesenk verdiler.'),
(2004442,68,26,27,18,'Ürünlerinin çeşitliliği, malının bolluğundan ötürü 2 Şam seninle ticaret yaptı. 2 Mallarına karşılık 2 Sana Helbon şarabıyla Sahar yünü, 2 Uzaldan getirilmiş şarap tekneleri verdi. 2 Sana getirilen mallar arasında 2 İşlenmiş demir, tarçın, güzel kokulu kamış vardı. metin ‹‹Vedan ve Yâvan halkı alışveriş yaptı››.'),
(2004443,68,26,27,20,'Dedan halkı mallarına karşılık 2 Sana eyerlik kumaş verdi.'),
(2004444,68,26,27,21,'Arabistan ve Kedar önderleri müşterindi, 2 Mallarına karşılık 2 Sana kuzu, koç, teke verdiler.'),
(2004445,68,26,27,22,'Saba ve Raama tüccarları seninle ticaret yaptı, 2 Mallarına karşılık 2 Sana her çeşit baharatın en iyisini, değerli taşlar, altın verdiler.'),
(2004446,68,26,27,23,'Harran, Kanne, Eden, Saba, Aşur, Kilmat tüccarları 2 Seninle ticaret yaptı.'),
(2004447,68,26,27,24,'Pazarlarındaki mallara karşılık 2 Güzel giysiler, lacivert kumaş, işlemeler, 2 Sık dokunmuş, iplerle sarılmış renkli halılar verdiler.'),
(2004448,68,26,27,25,'Ticaret gemileri senin mallarını taşıdı, 2 Denizin bağrında büyük yükle doldun.'),
(2004449,68,26,27,26,'Kürekçilerin seni açık denizlere götürdü, 2 Ama doğu rüzgarı 2 Denizin bağrında parçaladı seni.'),
(2004450,68,26,27,27,'Gemin kazaya uğrayacağı gün, 2 Zenginliğin, malların, ticari eşyaların, 2 Gemicilerin, kılavuzların, kalafatçıların, 2 Seninle ticaret yapanlar, 2 Askerlerin ve gemide olan herkes 2 Denizin derinliklerine batacak.'),
(2004451,68,26,27,28,'Gemicilerinin bağırışından 2 Kıyılar titreyecek.'),
(2004452,68,26,27,29,'Kürekçiler gemilerini bırakacak, 2 Gemicilerle kılavuzlar kıyıda duracak.'),
(2004453,68,26,27,30,'Yüksek sesle haykırıp 2 Senin için acı acı ağlayacaklar; 2 Başlarına toprak serpecek, 2 Külde yuvarlanacaklar.'),
(2004454,68,26,27,31,'Senin yüzünden başlarını tıraş edecek, 2 Çul kuşanacaklar. 2 Senin için acı acı ağlayacak, 2 Yas tutacaklar.'),
(2004455,68,26,27,32,'Ağlayıp yas tutarken, 2 Senin için bir ağıt yakacaklar: 2 Her yanı denizle çevrili Sur Kenti gibi 2 Susturulmuş bir kent var mı?'),
(2004456,68,26,27,33,'Malların denizaşırı ülkelere vardığında 2 Birçok ulusu doyurdun, 2 Büyük zenginliğin, çeşit çeşit malınla 2 Dünya krallarını zenginleştirdin.'),
(2004457,68,26,27,34,'Şimdiyse denizde, suların derinliklerinde 2 Darmadağın oldun, 2 Malların ve çalışanlarının tümü 2 Seninle birlikte battı.'),
(2004458,68,26,27,35,'Kıyı halkları 2 Başına gelenlere şaştılar; 2 Krallarının tüyleri korkudan diken diken oldu, 2 Yüzleri sarardı.'),
(2004459,68,26,27,36,'Ulusların arasındaki tüccarlar, 2 Başına gelenlere şaşacaklar; 2 Sonun korkunç oldu. 2 Bir daha var olmayacaksın.› ››'),
(2004460,68,26,28,1,'RAB bana şöyle seslendi:'),
(2004461,68,26,28,2,'‹‹İnsanoğlu, Sur önderine de ki, ‹Egemen RAB şöyle diyor: ‹‹ ‹Gurura kapılıp 2 Ben tanrıyım, 2 Denizlerin bağrında, 2 Tanrının tahtında oturuyorum dedin. 2 Kendini Tanrı sandın, 2 Oysa sen Tanrı değil, insansın.'),
(2004462,68,26,28,3,'İşte, Danieldenfş daha bilgesin, 2 Kimse senden bir giz saklayamaz.'),
(2004463,68,26,28,4,'Bilgeliğin, anlayışın sayesinde, 2 Kendine servet biriktirdin, 2 Hazinelerine altın, gümüş yığdın.'),
(2004464,68,26,28,5,'Ticaretteki üstün becerilerin sayesinde 2 Servetini çoğalttın, 2 Zenginliğin seni gurura sürükledi.'),
(2004465,68,26,28,6,'Bu yüzden Egemen RAB şöyle diyor: 2 Madem kendini Tanrı gibi bilge sandın,'),
(2004466,68,26,28,7,'Ben de yabancıları, en acımasız ulusları 2 Üzerine göndereceğim. 2 Bilgeliğinin güzelliğine kılıç çekecek, 2 Görkemini kirletecekler.'),
(2004467,68,26,28,8,'Seni ölüm çukuruna indirecekler, 2 Denizlerin bağrında korkunç bir ölümle öleceksin.'),
(2004468,68,26,28,9,'O zaman seni öldürenlerin önünde 2 Ben Tanrıyım diyecek misin? 2 Seni öldürenlerin elinde 2 Sen Tanrı değil, insansın.'),
(2004469,68,26,28,10,'Yabancıların elinde, 2 Sünnetsizin ölümüyle öleceksin. 2 Egemen RAB böyle diyor.› ››'),
(2004470,68,26,28,11,'RAB bana şöyle seslendi:'),
(2004471,68,26,28,12,'‹‹İnsanoğlu, Sur Kralı için bir ağıt yak. Ona diyeceksin ki, ‹Egemen RAB şöyle diyor: ‹‹ ‹Kusursuzlukta örnek biriydin, 2 Bilgeliğin ve güzelliğin eksiksizdi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004472,68,26,28,13,'Sen Tanrının bahçesi Adendeydin. 2 Yakut, topaz, aytaşı, 2 Sarı yakut, oniks, yeşim, 2 Laciverttaşı, firuze, zümrütle, çeşit çeşit değerli taşla bezenmiştin. 2 Kakma ve oyma işlerin hep altındandı. 2 Bunlar yaratıldığın gün hazırlanmışlardı.'),
(2004473,68,26,28,14,'Meshedilmiş, koruyucu bir Keruv olarak 2 Seni oraya yerleştirdim. 2 Tanrının kutsal dağındaydın, 2 Yanan taşlar arasında dolaştın.'),
(2004474,68,26,28,15,'Yaratıldığın günden 2 Sende kötülük bulunana dek 2 Yollarında kusursuzdun.'),
(2004475,68,26,28,16,'Ticaretinin bolluğundan 2 Zorbalıkla doldun 2 Ve günah işledin. 2 Bu yüzden kirli bir şey gibi 2 Seni Tanrının dağından attım, 2 Yanan taşların arasından kovdum, 2 Ey koruyucu Keruv.'),
(2004476,68,26,28,17,'Güzelliğinden ötürü 2 Gurura kapıldın, 2 Görkeminden ötürü 2 Bilgeliğini bozdun. 2 Böylece seni yere attım, 2 Kralların önünde seni yüzkarası yaptım.'),
(2004477,68,26,28,18,'İşlediğin pek çok günah 2 Ve ticaretteki hileciliğin yüzünden 2 Kutsal yerlerini kirlettin. 2 Seni yakıp yok edecek 2 Bir ateş çıkardım içinden, 2 Bütün seyredenlerin gözü önünde 2 Seni yeryüzünde küle çevirdim.'),
(2004478,68,26,28,19,'Seni tanıyan bütün uluslar sana şaştı, 2 Sonun korkunç oldu. 2 Bir daha var olmayacaksın.› ›› olduğundan bildiğimiz Peygamber Daniel olmayabilir.'),
(2004479,68,26,28,20,'RAB bana şöyle seslendi:'),
(2004480,68,26,28,21,'‹‹İnsanoğlu, yüzünü Saydaya çevir, ona karşı peygamberlik et.'),
(2004481,68,26,28,22,'Diyeceksin ki, ‹Egemen RAB şöyle diyor: ‹‹ ‹İşte sana karşıyım, ey Sayda, 2 Senin içinde yüceleceğim. 2 Onları cezalandırınca, 2 Kutsallığımı onlara gösterince, 2 Benim RAB olduğumu anlayacaklar.'),
(2004482,68,26,28,23,'Üzerine salgın hastalık gönderecek, 2 Sokaklarında kan akıtacağım. 2 Kentin içinde, her yanında 2 Kılıçla yaralananlar düşüp ölecekler. 2 O zaman benim RAB olduğumu anlayacaklar.› ››'),
(2004483,68,26,28,24,'‹‹ ‹İsrail halkını küçümseyen 2 Çevre uluslardan hiçbiri 2 Bir daha İsrail için batan bir çalı, 2 Acıtan bir diken olmayacak. 2 O zaman benim RAB olduğumu anlayacaklar.'),
(2004484,68,26,28,25,'‹‹ ‹Egemen RAB şöyle diyor: İsrail halkını aralarına dağılmış oldukları uluslardan topladığım, ulusların gözü önünde kutsallığımı gösterdiğim zaman kulum Yakupa verdiğim kendi ülkelerine yerleşecekler.'),
(2004485,68,26,28,26,'Orada güvenlik içinde yaşayacak, evler yapacak, bağlar dikecekler. Onları küçümseyen bütün çevre ulusları cezalandırdığımda güvenlik içinde yaşayacaklar. O zaman benim Tanrıları RAB olduğumu anlayacaklar.› ››'),
(2004486,68,26,29,1,'Sürgünlüğümüzün onuncu yılı, onuncu ayın on ikinci günü RAB bana şöyle seslendi:'),
(2004487,68,26,29,2,'‹‹İnsanoğlu, yüzünü firavuna çevir, ona ve Mısıra karşı peygamberlik et.'),
(2004488,68,26,29,3,'Onlara de ki, ‹Egemen RAB şöyle diyor: ‹‹ ‹Kendi kanallarının içinde yatan 2 Büyük canavar firavun, 2 İşte, sana karşıyım. 2 Sen ki, Nil benimdir, 2 Onu kendim için yaptım dersin.'),
(2004489,68,26,29,4,'Çenelerine çengeller takacak, 2 Kanallarındaki balıkları 2 Senin pullarına yapıştıracağım. 2 Pullarına yapışmış balıklarla birlikte 2 Seni kanallarından çıkaracağım.'),
(2004490,68,26,29,5,'Seni de kanallarındaki bütün balıkları da 2 Çöle atacağım. 2 Kırlara düşeceksin, 2 Toplanmayacak, gömülmeyeceksin. 2 Seni yem olarak yabanıl hayvanlara 2 Ve yırtıcı kuşlara vereceğim.'),
(2004491,68,26,29,6,'O zaman Mısırda yaşayan herkes 2 Benim RAB olduğumu anlayacak. ‹‹ ‹Çünkü sen İsrail halkına kamış bir değnek oldun.'),
(2004492,68,26,29,7,'Seni elleriyle tuttuklarında parçalanıp onların omuzlarını yardın. Sana dayandıklarında parçalanıp bellerini burktun. durdurdun››.'),
(2004493,68,26,29,8,'‹‹ ‹Bu yüzden Egemen RAB şöyle diyor: Üzerine halkını ve hayvanlarını öldürecek bir kılıç gönderiyorum.'),
(2004494,68,26,29,9,'Mısır kimsesiz bırakılacak, viraneye çevrilecek. O zaman benim RAB olduğumu anlayacaklar. ‹‹ ‹Madem Nil benimdir, onu ben yaptım dedin,'),
(2004495,68,26,29,10,'ben de sana ve kanallarına karşıyım. Mısırı Migdoldan Asvana, Kûş sınırına dek kimsesiz bırakacak, viraneye çevireceğim.'),
(2004496,68,26,29,11,'İçinden insan ayağı da, hayvan ayağı da geçmeyecek. Kırk yıl orada kimse yaşamayacak.'),
(2004497,68,26,29,12,'Mısırı ıssız kalmış ülkeler gibi ıssız bırakacağım. Kentleri, viran olmuş kentler arasında kırk yıl kimsesiz kalacak. Mısırlıları uluslar arasına gönderecek, ülkelere dağıtacağım.'),
(2004498,68,26,29,13,'‹‹ ‹Egemen RAB şöyle diyor: Kırk yıl sonra onları dağılmış oldukları uluslardan toplayacağım.'),
(2004499,68,26,29,14,'Sürgündekileri geri getirip Patrosa, yurtlarına döndüreceğim. Orada güçsüz bir krallık oluşturacaklar.'),
(2004500,68,26,29,15,'Krallıkların en güçsüzü olacak, bir daha ulusların üzerinde egemenlik sürmeyecek. Ulusları yönetmesinler diye onları küçük düşüreceğim.'),
(2004501,68,26,29,16,'Mısır bir daha İsrail halkının güveneceği bir yer olmayacak. Ancak Mısırlılar onlara Mısıra dönmekle işledikleri günahı anımsatacaklar. O zaman İsrailliler benim Egemen RAB olduğumu anlayacaklar.› ››'),
(2004502,68,26,29,17,'Sürgünlüğümüzün yirmi yedinci yılı, birinci ayın birinci günü RAB bana şöyle seslendi:'),
(2004503,68,26,29,18,'‹‹İnsanoğlu, Babil Kralı Nebukadnessar ordusunu Sur Kentine karşı büyük bir saldırıya geçirdi; herkesin saçı döküldü, ağır yük yüzünden omuz derileri yüzüldü. Ama Sura karşı ordusunu saldırıya geçirmesine karşın, bundan ne kendisi ne de ordusu yararlandı.'),
(2004504,68,26,29,19,'Bu yüzden Egemen RAB şöyle diyor: Mısırı Babil Kralı Nebukadnessara vereceğim, onun servetini alıp götürecek. Ordusuna ücret olarak ülkeden yağmaladığı çapul malını dağıtacak.'),
(2004505,68,26,29,20,'Hizmetine karşılık Mısırı ona verdim; çünkü o da ordusu da bana hizmet ettiler. Egemen RAB böyle diyor.'),
(2004506,68,26,29,21,'‹‹O gün İsrail halkını güçle donatacağım. Onların arasında senin dilini çözeceğim. O zaman benim RAB olduğumu anlayacaklar.››'),
(2004507,68,26,30,1,'RAB bana şöyle seslendi:'),
(2004508,68,26,30,2,'‹‹İnsanoğlu, peygamberlik et ve de ki, ‹Egemen RAB şöyle diyor: ‹‹ ‹Ah o gün diye haykır.'),
(2004509,68,26,30,3,'Çünkü o gün yakın. 2 RABbin günü yakın, 2 Bulutların günü, 2 Ulusların yıkım zamanı.'),
(2004510,68,26,30,4,'Bir kılıç Mısıra karşı çıkacak. 2 Kûşu acılar saracak. 2 Mısırda vurulanlar yere serilince 2 Ülkenin serveti alınıp götürülecek, 2 Temelleri yok edilecek.'),
(2004511,68,26,30,5,'Mısırla birlikte Kûş, Pût, Lud, 2 Arabistan, Kuv ve antlaşma yaptığım halkım 2 Kılıçtan geçirilecek.'),
(2004512,68,26,30,6,'‹‹ ‹RAB şöyle diyor: 2 Mısırı destekleyenler öldürülecek, 2 Mısırın övündüğü ordu çökecek, 2 Migdoldan Asvana dek kılıçtan geçirilecekler. 2 Böyle diyor Egemen RAB.'),
(2004513,68,26,30,7,'Kimsesiz kalmış ülkeler arasında 2 Kimsesiz kalacaklar. 2 Kentleri viran olmuş kentler gibi olacak.'),
(2004514,68,26,30,8,'Mısırı ateşe verdiğimde, 2 Onu destekleyenler ezildiğinde, 2 Benim RAB olduğumu anlayacaklar.'),
(2004515,68,26,30,9,'‹‹ ‹O gün kaygısız Kûşluları korkutmak için gemilerle ulaklar göndereceğim. Mısırın yıkım günü geldiğinde korkuya kapılacaklar. İşte o gün geliyor.'),
(2004516,68,26,30,10,'‹‹ ‹Egemen RAB şöyle diyor: 2 Babil Kralı Nebukadnessar aracılığıyla 2 Mısırın zenginliğine son vereceğim.'),
(2004517,68,26,30,11,'O ve ordusu, ulusların en acımasızı, 2 Ülkeyi yerle bir etmek için gelecekler. 2 Mısıra karşı kılıçlarını çekecek, 2 Ülkeyi öldürülenlerle dolduracaklar.'),
(2004518,68,26,30,12,'Nilin kanallarını kurutup 2 Ülkeyi kötü kişilere teslim edeceğim, 2 Ülkeyi de içindeki her şeyi de 2 Yabancılar eliyle viran edeceğim. 2 Bunu ben RAB söylüyorum.'),
(2004519,68,26,30,13,'Egemen RAB şöyle diyor: 2 Putları yok edecek, 2 Noftakifü değersiz putlara son vereceğim. 2 Mısırda artık önder olmayacak, 2 Ülkeye korku salacağım.'),
(2004520,68,26,30,14,'Patrosu viraneye çevirecek, 2 Soanı ateşe verecek, 2 No Kentini cezalandıracağım.'),
(2004521,68,26,30,15,'Öfkemi Mısırın kalesi Sin üzerine boşaltacak, 2 Kalabalık No halkına son vereceğim.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004522,68,26,30,16,'Mısırı ateşe vereceğim, 2 Sin acıdan kıvranacak, 2 No Kentinin surları yarılacak, 2 Noffü sürekli tedirgin olacak.'),
(2004523,68,26,30,17,'On Kenti ve Pi-Beset gençleri 2 Kılıçtan geçirilecek, 2 Oradaki halk sürgüne gönderilecek.'),
(2004524,68,26,30,18,'Tahpanheste Mısırın boyunduruğunu kırdığım zaman, 2 Orada gündüz geceye dönecek, 2 Övündüğü orduya son verilecek, 2 Kent bulutlarla kaplanacak, 2 Köylerindeki halk sürgüne gönderilecek.'),
(2004525,68,26,30,19,'Mısırı böyle cezalandırdığımda 2 Benim RAB olduğumu anlayacaklar.› ››'),
(2004526,68,26,30,20,'Sürgünlüğümüzün on birinci yılı, birinci ayın yedinci günü RAB bana şöyle seslendi:'),
(2004527,68,26,30,21,'‹‹İnsanoğlu, firavunun kolunu kırdım. İyileşmesin, kılıç tutacak kadar güçlenmesin diye kimse onu bağlamadı, sargı beziyle sarmadı.'),
(2004528,68,26,30,22,'Bu yüzden Egemen RAB şöyle diyor: Firavuna karşıyım. Her iki kolunu, sağlam olanı da kırık olanı da kıracağım. Kılıcı elinden düşüreceğim.'),
(2004529,68,26,30,23,'Mısırlıları uluslar arasına gönderecek, ülkelere dağıtacağım.'),
(2004530,68,26,30,24,'Babil Kralının kollarını güçlendirip kılıcımı onun eline vereceğim. Firavunun ise kollarını kıracağım. Babil Kralının önünde ağır yaralı biri gibi inleyecek.'),
(2004531,68,26,30,25,'Babil Kralının gücüne güç katacak, firavunun gücünü zayıflatacağım. Kılıcımı Babil Kralının eline verdiğimde ve o kılıcı Mısıra doğru uzattığında, benim RAB olduğumu anlayacaklar.'),
(2004532,68,26,30,26,'Mısırlılar''ı uluslar arasına gönderecek, ülkelere dağıtacağım. O zaman benim RAB olduğumu anlayacaklar.››'),
(2004533,68,26,31,1,'Sürgünlüğümüzün on birinci yılı, üçüncü ayın birinci günü RAB bana şöyle seslendi:'),
(2004534,68,26,31,2,'‹‹İnsanoğlu, firavuna ve halkına de ki, ‹‹ ‹Görkemde kim seninle boy ölçüşebilir?'),
(2004535,68,26,31,3,'Asura bak! Lübnanda bir sedir ağacıydı, 2 Ormana gölge salan güzel dalları vardı. 2 Çok yüksekti, tepesi bulutlara erişiyordu.'),
(2004536,68,26,31,4,'Sular ağacı besledi, 2 Derin su kaynakları büyüttü. 2 Akarsular dikili olduğu yerin çevresine akıyor, 2 Kanalları kırdaki bütün ağaçlara erişiyordu.'),
(2004537,68,26,31,5,'Kırdaki bütün ağaçlardan daha çok büyüdü. 2 Bol su verildiği için 2 Dal budak saldı, dalları uzadı.'),
(2004538,68,26,31,6,'Kuşlar dallarına yuva yaptı, 2 Yabanıl hayvanlar dalları altında yavruladı, 2 Büyük uluslar gölgesinde yaşadı.'),
(2004539,68,26,31,7,'Güzellikte eşsizdi. 2 Dalları giderek uzadı, 2 Çünkü kökleri bol su alıyordu.'),
(2004540,68,26,31,8,'Tanrının bahçesindeki sedir ağaçlarından hiçbiri 2 Onunla boy ölçüşemezdi, 2 Çam ağaçları dalları kadar bile değildi. 2 Çınarlar onun dallarıyla boy ölçüşemezdi. 2 Tanrının bahçesindeki ağaçların hiçbiri 2 Onun kadar güzel değildi.'),
(2004541,68,26,31,9,'Sık dallarla o sedir ağacını güzelleştirdim. 2 Tanrının bahçesi Adendeki bütün ağaçlar onu kıskandı.'),
(2004542,68,26,31,10,'‹‹ ‹Bu yüzden Egemen RAB şöyle diyor: Ağaç büyüyüp boy attığı, tepesi bulutlara eriştiği, büyüklüğünden ötürü gurura kapıldığı için'),
(2004543,68,26,31,11,'ben de onu kovdum, ulusların önderinin eline teslim ettim. Ona kötülüğü uyarınca davranacak.'),
(2004544,68,26,31,12,'Yabancı ulusların en acımasızı onu kesip yalnız bıraktı. Dalları dağlara, derelere düştü; ülkenin vadilerinde kesilmiş duruyor. Yeryüzündeki bütün uluslar gölgesinden çekilip onu bıraktılar.'),
(2004545,68,26,31,13,'Bütün kuşlar devrik ağaca kondu, yabanıl hayvanlar dalları arasına yerleşti.'),
(2004546,68,26,31,14,'Öyle ki, suların yakınında yetişen hiçbir ağaç böylesi büyüyüp boy atmasın, tepesini bulutlara eriştirmesin; bol suyla sulanan hiçbir ağaç bu denli yükselmesin. Çünkü hepsi ölüm çukuruna inen insanlarla birlikte ölüme, yerin derinliklerine gidecek.'),
(2004547,68,26,31,15,'‹‹ ‹Egemen RAB şöyle diyor: Sedir ağacı ölüler diyarına indiği gün, ona yas tutsunlar diye derin su kaynaklarını kapattım. Irmaklarını durdurdum, gür sularının önünü kestim. O ağaç yüzünden Lübnanı karanlığa boğdum, bütün orman ağaçlarını kuruttum.'),
(2004548,68,26,31,16,'Ölüm çukuruna inenlerle birlikte onu ölüler diyarına indirdiğimde, yıkılışının gürültüsünden ulusları titrettim. O zaman Aden Bahçesindeki bütün ağaçlar, Lübnanın en seçkin, en iyi, bol sulanan ağaçları yerin derinliklerinde avunç buldu.'),
(2004549,68,26,31,17,'Gölgesinde yaşayanlar, uluslar arasında onu destekleyenler de onunla birlikte ölüler diyarına, kılıçla öldürülmüşlerin yanına indiler.'),
(2004550,68,26,31,18,'‹‹ ‹Aden ağaçlarından hangisi görkem ve yücelikte seninle boy ölçüşebilir? Ama sen de Aden ağaçlarıyla birlikte yerin derinliklerine indirilecek, sünnetsizlere, kılıçla öldürülmüşlere katılacaksın. ‹‹ ‹İşte firavunla halkının sonu böyle olacaktır.› Egemen RAB böyle diyor.››'),
(2004551,68,26,32,1,'Sürgünlüğümüzün on ikinci yılı, on ikinci ayın birinci günü RAB bana şöyle seslendi:'),
(2004552,68,26,32,2,'‹‹İnsanoğlu, firavun için bir ağıt yak. Ona de ki, ‹‹ ‹Uluslar arasında genç bir aslan gibi kendini öne sürdün, 2 Ama sen denizlerdeki bir canavar gibisin. 2 Irmaklarını karıştırır, 2 Ayaklarınla suları çalkalar, 2 Irmakları bulandırırsın.› ››'),
(2004553,68,26,32,3,'Egemen RAB şöyle diyor: 2 ‹‹Büyük bir kalabalıkla 2 Ağımı senin üzerine atacağım; 2 Onlar seni ağımla çekecekler.'),
(2004554,68,26,32,4,'Seni karaya atacak, 2 Kırlara fırlatacağım. 2 Gökte uçan kuşların senin üzerine konmalarını sağlayacağım, 2 Yeryüzündeki yabanıl hayvanlara 2 Seni yem olarak vereceğim.'),
(2004555,68,26,32,5,'Bedenini dağların üzerine serecek, 2 Vadileri çürüyen bedeninle dolduracağım.'),
(2004556,68,26,32,6,'Ülkeyi dağlara dek akan kanınla ıslatacağım, 2 Vadiler seninle dolacak.'),
(2004557,68,26,32,7,'Seni ortadan kaldırdığım zaman 2 Gökleri örtecek, 2 Yıldızları karartacak, 2 Güneşi bulutla kapatacağım. 2 Ay ışığını vermeyecek.'),
(2004558,68,26,32,8,'Senin yüzünden gökte ışık veren bütün cisimleri karartacak, 2 Ülkeni karanlığa gömeceğim.›› 2 Böyle diyor Egemen RAB.'),
(2004559,68,26,32,9,'‹‹Seni tanımadığın ülkelere, 2 Ulusların arasına sürgüne gönderdiğimde, 2 Pek çok halkın yüreği üzüntüyle sarsılacak. ‹‹Yıkıma uğrattığımda››.'),
(2004560,68,26,32,10,'Başına gelenlerden ötürü 2 Pek çok halkı şaşkına çevireceğim. 2 Kılıcımı önlerinde salladığım zaman, 2 Senin yüzünden krallar dehşetle ürperecek. 2 Yıkıma uğradığın gün 2 Hepsi kendi canı için 2 Her an korkuyla titreyecek.'),
(2004561,68,26,32,11,'Egemen RAB şöyle diyor: 2 Babil Kralının kılıcı üzerine gelecek.'),
(2004562,68,26,32,12,'Yiğitlerin, ulusların en acımasızının, 2 Senin halkını kılıçtan geçirmesine izin vereceğim. 2 Mısırın gururunu kıracak, 2 Bütün ordusunu yok edecekler.'),
(2004563,68,26,32,13,'Bol suların yanında bütün sığırlarını yok edeceğim. 2 Bundan böyle insan ayağı da hayvan ayağı da 2 Suları karıştırıp bulandırmayacak.'),
(2004564,68,26,32,14,'O zaman sularını dupduru kılacak, 2 Irmaklarını yağ gibi akıtacağım. 2 Egemen RAB böyle diyor.'),
(2004565,68,26,32,15,'Mısırı viraneye çevirdiğimde, 2 Ülkeyi her şeyden yoksun bıraktığımda, 2 Orada yaşayan herkesi yok ettiğimde, 2 Benim RAB olduğumu anlayacaklar.›'),
(2004566,68,26,32,16,'‹‹Ona yakacakları ağıt budur. Ulusların kızları bu ağıtı yakacaklar. Mısır için, halkı için bu ağıtı yakacaklar.›› Egemen RAB böyle diyor.'),
(2004567,68,26,32,17,'Sürgünlüğümüzün on ikinci yılı, ayın on beşinci günü RAB bana şöyle seslendi:'),
(2004568,68,26,32,18,'‹‹Ey insanoğlu, Mısır halkı için yas tut. Onları ve güçlü ulusların kızlarını ölüm çukuruna inenlerle birlikte yerin derinliklerine indir.'),
(2004569,68,26,32,19,'Onlara de ki, ‹Sen başkalarından daha mı güzelsin? Aşağı in ve oradaki sünnetsizlere katıl.›'),
(2004570,68,26,32,20,'Mısır halkı kılıçla öldürülenlerin arasına düşecek. Kılıç hazır, bırakın Mısır bütün halkıyla birlikte sürüklensin.'),
(2004571,68,26,32,21,'Güçlü önderler, ölüler diyarından, Mısır ve onu destekleyenler için, ‹Aşağı indiler, kılıçla öldürülen sünnetsizlerle birlikte burada yatıyorlar› diyecekler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004572,68,26,32,22,'‹‹Asur bütün ordusuyla orada. Kılıçtan geçirilmiş, ölmüş askerlerinin mezarları çevresini sarmış.'),
(2004573,68,26,32,23,'Mezarları ölüm çukurunun en dibinde, ordusu mezarının çevresinde duruyor. Yaşayanlar diyarında korku salanların hepsi kılıçtan geçirilmiş, ölmüş.'),
(2004574,68,26,32,24,'‹‹Elam bütün halkıyla kendi mezarının çevresinde duruyor. Hepsi kılıçtan geçirilmiş, ölmüş, sünnetsiz olarak yerin derinliklerine inmiş. Yaşayanlar diyarında korku salmışlardı, şimdiyse utanç içinde ölüm çukuruna inenlere katıldılar.'),
(2004575,68,26,32,25,'Elam için öldürülenler arasında bir yatak yapıldı. Bütün halkı mezarının çevresinde. Hepsi sünnetsiz, kılıçtan geçirilerek ölmüş. Yaşayanlar diyarında korku salmışlardı, şimdiyse utanç içinde ölüm çukuruna inenlere katıldılar, öldürülenlerin arasına yerleştirildiler.'),
(2004576,68,26,32,26,'‹‹Meşek ve Tuval bütün halkıyla kendi mezarları çevresinde duruyor. Hepsi sünnetsiz, kılıçtan geçirilerek öldürülmüş. Yaşayanlar diyarında korku salmışlardı.'),
(2004577,68,26,32,27,'Ölüler diyarına savaş silahlarıyla inen, kılıçları başlarının altına konan, kalkanları kemikleri üzerine yerleştirilen öbür öldürülmüş sünnetsiz yiğitlerle birlikte mezara konmayacak mı onlar? Oysa bu yiğitler yaşayanlar diyarında korku salmışlardı.'),
(2004578,68,26,32,28,'‹‹Sen de, ey firavun, düşecek ve kılıçla öldürülenlerle birlikte sünnetsizlerin arasına konacaksın.'),
(2004579,68,26,32,29,'‹‹Edom, kralları ve önderleriyle orada. Güçlü olmalarına karşın kılıçla öldürülenlerin yanına kondular. Ölüm çukuruna inenlerin, sünnetsizlerin yanında yatıyorlar.'),
(2004580,68,26,32,30,'‹‹Bütün kuzey önderleri, bütün Saydalılar orada. Güçleriyle korku saldıkları halde öldürülenlerle birlikte utanç içinde indiler. Sünnetsiz olarak kılıçla öldürülenlerle birlikte utanç içinde ölüm çukuruna inenlerin yanına kondular.'),
(2004581,68,26,32,31,'‹‹Firavunla ordusu kılıçla öldürülmüş bu büyük kalabalığı görünce avunç bulacak.›› Böyle diyor Egemen RAB.'),
(2004582,68,26,32,32,'‹‹Yaşayanlar diyarında korku salmasını sağladığım halde, firavunla halkı, kılıçla öldürülenlerle birlikte sünnetsizlerin yanına konacak.›› Böyle diyor Egemen RAB.'),
(2004583,68,26,33,1,'RAB bana şöyle seslendi:'),
(2004584,68,26,33,2,'‹‹İnsanoğlu, kendi halkına şöyle diyeceksin: ‹Bir ülkenin üzerine kılıç gönderdiğim, ülke halkı aralarından birini seçip bekçi atadığı,'),
(2004585,68,26,33,3,'bekçi kılıcın ülkenin üzerine yaklaştığını görüp halkı uyarmak için boru çaldığı zaman;'),
(2004586,68,26,33,4,'kim boru sesini işitip de uyarıyı dikkate almazsa, kılıç da gelip onu öldürürse, kanından kendisi sorumludur.'),
(2004587,68,26,33,5,'Boru sesini duymuş, ama uyarıyı dikkate almamıştır; kanından kendisi sorumludur. Uyarıyı dikkate alsaydı, canını kurtaracaktı.'),
(2004588,68,26,33,6,'Ne var ki, bekçi kılıcın ülkenin üzerine yaklaştığını görüp halkı uyarmak için boru çalmazsa, kılıç da gelip halktan birini öldürürse, o kişi kendi günahı içinde öldürülmüştür; kanından bekçiyi sorumlu tutacağım.›'),
(2004589,68,26,33,7,'‹‹İnsanoğlu, seni İsrail halkına bekçi atadım. Benden bir söz duyar duymaz onları benim yerime uyaracaksın.'),
(2004590,68,26,33,8,'Kötü kişiye, ‹Ey kötü kişi, kesinlikle öleceksin› dediğim zaman, onu uyarmaz, kötü yolundan döndürmek için konuşmazsan, o kişi günahı içinde ölecek; ama onun kanından seni sorumlu tutacağım.'),
(2004591,68,26,33,9,'Ancak kötü kişiyi uyardığın halde yolundan dönmezse, o günahı içinde ölecek. Ama sen canını kurtarmış olacaksın.'),
(2004592,68,26,33,10,'‹‹İnsanoğlu, İsrail halkına de ki, ‹Siz şöyle diyorsunuz: İsyanlarımızla günahlarımız bizi çökertiyor, onlardan ötürü eriyip yok oluyoruz. Durum böyleyken nasıl yaşayabiliriz?›'),
(2004593,68,26,33,11,'Onlara de ki, ‹Varlığım hakkı için diyor Egemen RAB, ben kötü kişinin ölümünden sevinç duymam, ancak kötü kişinin kötü yollarından dönüp yaşamasından sevinç duyarım. Dönün! Kötü yollarınızdan dönün! Niçin ölesiniz, ey İsrail halkı!›'),
(2004594,68,26,33,12,'‹‹Sen, ey insanoğlu, halkına de ki, ‹Doğru kişi Tanrıya başkaldırırsa, doğruluğu onu kurtarmaz. Kötü kişi kötülüğünden döndüğü zaman kötülüğü yıkımına neden olmaz. Doğru kişi Tanrıya başkaldırırsa, doğruluğu yaşamasını sağlamaz.›'),
(2004595,68,26,33,13,'Doğru kişi için, ‹Kesinlikle yaşayacak› desem, ama o doğruluğuna güvenip de kötülük yapsa, yaptığı doğru işlerin hiçbiri anımsanmayacak. Yaptığı kötülükten ötürü ölecek.'),
(2004596,68,26,33,14,'Kötü kişiye, ‹Kesinlikle öleceksin› desem, ama o günahından dönüp adil ve doğru olanı yapsa,'),
(2004597,68,26,33,15,'aldığı rehini geri verse, çaldığını ödese, yaşam veren kurallar uyarınca davranıp günah işlemese kesinlikle yaşayacak, ölmeyecektir.'),
(2004598,68,26,33,16,'İşlediği günahlardan hiçbiri ona karşı anımsanmayacaktır, adil ve doğru olanı yapmıştır; kesinlikle yaşayacaktır.'),
(2004599,68,26,33,17,'‹‹Senin halkın, ‹Rabbin yolu doğru değil› diyor. Oysa doğru olmayan onların yolu.'),
(2004600,68,26,33,18,'Doğru kişi doğruluğundan döner de kötülük yaparsa, yaptığı kötülüğün içinde ölecektir.'),
(2004601,68,26,33,19,'Kötü kişi yaptığı kötülükten döner de adil ve doğru olanı yaparsa, yaptığı bu işlerle yaşayacaktır.'),
(2004602,68,26,33,20,'Ey İsrail halkı, ‹Rabbin yolu doğru değil› diyorsun. Her birinizi kendi yoluna göre yargılayacağım.››'),
(2004603,68,26,33,21,'Sürgünlüğümüzün on ikinci yılı, onuncu ayın beşinci günü Yeruşalimden kaçıp kurtulan biri yanıma gelip, ‹‹Kent düştü!›› dedi.'),
(2004604,68,26,33,22,'Akşam, Yeruşalimden kaçıp kurtulan adam gelmeden önce, RABbin eli üzerimdeydi, konuşamıyordum. Sabah o yanıma gelmeden RAB dilimi çözdü. Dilim açıldı, artık konuşabilirdim.'),
(2004605,68,26,33,23,'RAB bana şöyle seslendi:'),
(2004606,68,26,33,24,'‹‹İnsanoğlu, İsrailin viran olmuş kentlerinde yaşayanlar, ‹İbrahim tek kişiyken ülkeyi miras almıştı. Oysa biz kalabalığız, ülke miras olarak bize verilmiştir› diyorlar.'),
(2004607,68,26,33,25,'Bu nedenle onlara de ki, ‹Egemen RAB şöyle diyor: Eti kanıyla yiyor, putlarınıza bel bağlıyor, kan döküyorsunuz. Yine de ülkeyi miras almayı mı umuyorsunuz?'),
(2004608,68,26,33,26,'Kılıcınıza güveniyor, iğrenç şeyler yapıyor, komşunuzun karısını kirletiyorsunuz. Yine de ülkeyi miras almayı mı umuyorsunuz?›'),
(2004609,68,26,33,27,'‹‹Onlara de ki, ‹Egemen RAB şöyle diyor: Varlığım hakkı için, viran olmuş kentlerde yaşayanlar kılıçtan geçirilecek, kırda yaşayanları yem olarak yabanıl hayvanlara vereceğim, kalelerde, mağaralarda yaşayanlar salgın hastalıkla yok olacak.'),
(2004610,68,26,33,28,'Ülkeyi ıssız, kimsesiz bırakacağım, övündükleri güç son bulacak. İsrail dağları ıssız kalacak, oradan kimse geçmeyecek.'),
(2004611,68,26,33,29,'Yaptıkları iğrenç şeylerden ötürü ülkeyi ıssız, kimsesiz bıraktığım zaman benim RAB olduğumu anlayacaklar.›'),
(2004612,68,26,33,30,'‹‹Sen, ey insanoğlu, halkın duvar diplerinde, evlerin kapıları önünde senin hakkında konuşuyor. Birbirlerine, ‹Haydi, gidip RABden gelen sözün ne olduğunu duyalım› diyorlar.'),
(2004613,68,26,33,31,'Halk her zamanki gibi sana geliyor. Benim halkım olarak önünde oturuyor, sözlerini dinliyor, ama dediklerini yapmıyorlar. Ağızlarıyla istekli olduklarını açıklıyorlar, ama yürekleri haksız kazanç peşinde.'),
(2004614,68,26,33,32,'Sen onlar için güzel sesle sevgi ezgileri okuyan, iyi çalgı çalan biri gibisin. Sözlerini dinliyor, ama dediklerini yapmıyorlar.'),
(2004615,68,26,33,33,'‹‹Bütün bunlar gerçekleşince -ki gerçekleşecek- aralarında bir peygamber bulunduğunu anlayacaklar.››'),
(2004616,68,26,34,1,'RAB bana şöyle seslendi:'),
(2004617,68,26,34,2,'‹‹İnsanoğlu, İsrailin çobanlarına karşı peygamberlik et ve onlara, bu çobanlara şöyle de: ‹Egemen RAB diyor ki: Vay kendi kendini güden İsrail çobanlarına! Çobanların sürüyü gütmesi gerekmez mi?'),
(2004618,68,26,34,3,'Yağı yiyor, yünü giyiyor, besili koyunları kesiyorsunuz, ama sürüyü kayırmıyorsunuz.'),
(2004619,68,26,34,4,'Zayıfları güçlendirmediniz, hastaları iyileştirmediniz, yaralıların yarasını sarmadınız. Yolunu şaşıranları geri getirmediniz, yitikleri aramadınız. Ancak sertlik ve şiddetle onlara egemen oldunuz.'),
(2004620,68,26,34,5,'Çobanları olmadığı için dağıldılar, yabanıl hayvanlara yem oldular.'),
(2004621,68,26,34,6,'Koyunlarım bütün dağlarda, yüksek tepelerde başıboş dolandılar. Koyunlarım yeryüzüne dağıldı. Onları ne arayan var, ne soran. anlamına da gelir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004622,68,26,34,7,'‹‹ ‹Bu yüzden, ey çobanlar, RABbin sözünü dinleyin:'),
(2004623,68,26,34,8,'Varlığım hakkı için diyor Egemen RAB, çoban olmadığından koyunlarım yağma edildi, yabanıl hayvanlara yem oldu. Çobanlarım koyunlarımı aramadılar, onları güdeceklerine kendi kendilerini güttüler.'),
(2004624,68,26,34,9,'Onun için, ey çobanlar, RABbin sözünü dinleyin.'),
(2004625,68,26,34,10,'Egemen RAB şöyle diyor: Ben çobanlara karşıyım! Koyunlarımdan onları sorumlu tutacağım, koyunlarımı gütmelerine son vereceğim. Öyle ki, artık kendi kendilerini güdemeyecekler. Koyunlarımı onların ağzından kurtaracağım, artık onlara yem olmayacaklar.'),
(2004626,68,26,34,11,'‹‹ ‹Egemen RAB şöyle diyor: Ben kendim koyunlarımı arayıp soracağım.'),
(2004627,68,26,34,12,'Dağılmış koyunlarının arasındaki bir çoban sürüsüyle nasıl ilgilenirse, ben de koyunlarımla öyle ilgileneceğim. Bulutlu, karanlık bir gün dağılmış oldukları her yerden onları kurtaracağım.'),
(2004628,68,26,34,13,'Onları ulusların arasından çıkaracak, ülkelerden toplayacak, kendi yurtlarına geri getireceğim. Onları İsrail dağlarında, vadilerde, ülkenin bütün oturulabilir yerlerinde güdeceğim.'),
(2004629,68,26,34,14,'Onları iyi bir otlakta güdeceğim; yaylaları İsrailin yüksek dağları üzerinde olacak. Orada iyi bir otlakta yatacak, İsrailin yüksek dağlarındaki verimli otlaklarda otlayacaklar.'),
(2004630,68,26,34,15,'Ben kendim koyunlarımı güdeceğim, onları kendim yatıracağım. Egemen RAB böyle diyor.'),
(2004631,68,26,34,16,'Yiteni arayacak, yolunu şaşıranı geri getireceğim. Yaralının yarasını saracak, zayıfı güçlendireceğim. Ama semizlerle güçlüleri yok edeceğim. Koyunlarımı adaletle güdeceğim.'),
(2004632,68,26,34,17,'‹‹ ‹Siz, ey benim sürüm, Egemen RAB şöyle diyor: Koyunla koyun arasında yargıyı ben vereceğim. Koçlarla tekelere gelince,'),
(2004633,68,26,34,18,'iyi otlakta otlamanız yetmiyor mu ki, otlaklarınızın geri kalanını ayaklarınızla çiğniyorsunuz? Duru su içmeniz yetmiyor mu ki, geri kalan suyu ayaklarınızla bulandırıyorsunuz?'),
(2004634,68,26,34,19,'Koyunlarım ayaklarınızın çiğnediğini otlamak, ayaklarınızın bulandırdığını içmek zorunda kalıyor.'),
(2004635,68,26,34,20,'‹‹ ‹Bu nedenle Egemen RAB onlara şöyle diyor: Semiz koyunla cılız koyun arasında ben kendim yargıçlık yapacağım.'),
(2004636,68,26,34,21,'Madem bütün cılız koyunları kovup dağıtıncaya dek böğrünüzle vuruyor, omuzunuzla itiyor, boynuzlarınızla kakıyorsunuz,'),
(2004637,68,26,34,22,'ben de koyunlarımı kurtaracağım, artık çapul malı olmayacaklar. Koyunla koyun arasında ben yargıçlık yapacağım.'),
(2004638,68,26,34,23,'Başlarına, onları güdecek tek çoban olarak kulum Davutu koyacağım. Onları o güdecek, çobanları o olacak.'),
(2004639,68,26,34,24,'Ben RAB onların Tanrısı olacağım, kulum Davut da onların arasında önder olacak. Ben RAB, böyle diyorum.'),
(2004640,68,26,34,25,'‹‹ ‹Onlarla bir barış antlaşması yapacağım, ülkedeki yırtıcı hayvanları yok edeceğim. Çölde güvenlik içinde yaşayacak, ormanlarda uyuyacaklar.'),
(2004641,68,26,34,26,'Onları da dağımın çevresini de bereketli kılacağım. Yağmuru zamanında yağdıracağım. Bereketli yağmurlar olacak.'),
(2004642,68,26,34,27,'Kırdaki ağaçlar meyve verecek, toprak ürün verecek. Halk ülkesinde güvenlik içinde olacak. Boyunduruklarının bağlarını koparıp onları köle edenlerin elinden kurtardığım zaman benim RAB olduğumu anlayacaklar.'),
(2004643,68,26,34,28,'Artık ulusların çapul malı, yabanıl hayvanların yemi olmayacaklar. Güvenlik içinde yaşayacaklar, kimse onları korkutmayacak.'),
(2004644,68,26,34,29,'Onlar için ünlü bir fidanlık yetiştireceğim. Artık ülke kıtlıktan yok olmayacak, ulusların aşağılamasına uğramayacaklar.'),
(2004645,68,26,34,30,'O zaman ben Tanrıları RABbin onlarla birlikte olduğumu ve İsrail soyunun da benim halkım olduğunu anlayacaklar.› Böyle diyor Egemen RAB.'),
(2004646,68,26,34,31,'‹Benim koyunlarım, otlağımın koyunları siz insanlarsınız. Ben sizin Tanrınız''ım.› Böyle diyor Egemen RAB.››'),
(2004647,68,26,35,1,'RAB bana şöyle seslendi:'),
(2004648,68,26,35,2,'‹‹İnsanoğlu, yüzünü Seir Dağına çevir, ona karşı peygamberlik et.'),
(2004649,68,26,35,3,'Ona de ki, ‹Egemen RAB şöyle diyor: Ey Seir Dağı, sana karşıyım! Elimi sana karşı uzatacak, seni viran edip kimsesiz bırakacağım.'),
(2004650,68,26,35,4,'Kentlerini yerle bir edeceğim, kimsesiz kalacaksın. O zaman benim RAB olduğumu anlayacaksın.'),
(2004651,68,26,35,5,'‹‹ ‹Madem İsraillilere hep kin besledin, yıkıma uğradıklarında, cezalandırılmalarının zamanı doruğa ulaştığında, onları kılıca teslim ettin,'),
(2004652,68,26,35,6,'varlığım hakkı için diyor Egemen RAB, senin kanını akıtacağım, kan peşini bırakmayacak. Madem kan dökmekten nefret etmedin, kan peşini bırakmayacak.'),
(2004653,68,26,35,7,'Seir Dağını viran edip kimsesiz bırakacağım, oraya gidip geleni kesip atacağım.'),
(2004654,68,26,35,8,'Dağlarını ölülerle dolduracağım; kılıçtan geçirilenler senin tepelerinde, vadilerinde, derelerinde düşüp ölecekler.'),
(2004655,68,26,35,9,'Seni sonsuza dek viran edeceğim, kentlerinde kimse oturmayacak. O zaman benim RAB olduğumu anlayacaksın.'),
(2004656,68,26,35,10,'‹‹ ‹Siz, bu iki ulus, bu iki ülke bizim olacak, onları miras alacağız demiştiniz. Oysa RAB oralardadır.'),
(2004657,68,26,35,11,'Bundan ötürü varlığım hakkı için diyor Egemen RAB, beslediğiniz kin yüzünden halkıma nasıl öfkeyle, kıskançlıkla davrandıysanız, ben de size öyle davranacağım. Sizi yargıladığım zaman onlara kendimi tanıtacağım.'),
(2004658,68,26,35,12,'O zaman İsrail dağlarına sövgülerinizi duyduğumu anlayacaksınız. Şöyle demiştiniz: ‹‹Yerle bir oldular, yutalım diye bize verildiler.››'),
(2004659,68,26,35,13,'Bana karşı böbürlendiğinizi, saygısızca konuştuğunuzu da duydum.'),
(2004660,68,26,35,14,'Egemen RAB şöyle diyor: Bütün yeryüzü sevinirken, seni yerle bir edeceğim.'),
(2004661,68,26,35,15,'İsrail halkının mirası yerle bir olduğunda nasıl sevindinse, ben de sana öyle davranacağım. Ey Seir Dağı, viran olacaksın; bütün Edom da viran olacak. O zaman benim RAB olduğumu anlayacaklar.› ››'),
(2004662,68,26,36,1,'‹‹İnsanoğlu, İsrail dağlarına peygamberlik et ve de ki, ‹Ey İsrail dağları, RABbin sözünü dinleyin!'),
(2004663,68,26,36,2,'Egemen RAB şöyle diyor: Düşman sizin hakkınızda, Hah, hah! Bu eski tepeler mülkümüz oldu! dediği için'),
(2004664,68,26,36,3,'peygamberlik et ve de ki, Egemen RAB şöyle diyor: Dağlarınızı viran ettiler, sizi her yandan sıkıştırıp çiğnediler; böylece ulusların mülkü oldunuz, dile düştünüz, alay konusu oldunuz,'),
(2004665,68,26,36,4,'ey İsrail dağları, Egemen RABbin sözünü dinleyin! Egemen RAB dağlarla tepelere, vadilerle derelere, yıkıntılara, çevrenizdeki ulusların yağmasına, alayına uğramış, terk edilmiş kentlere şöyle diyor:'),
(2004666,68,26,36,5,'Egemen RAB şöyle diyor: Yürekleri sevinç dolu, aşağılayarak otlaklarınızı yağmalamak için ülkeme sahip çıkan öteki uluslara, özellikle Edoma karşı büyük bir kıskançlıkla konuştum.›'),
(2004667,68,26,36,6,'Bu nedenle İsrail ülkesi için peygamberlik et ve dağlara, tepelere, vadilere, derelere de ki, ‹Egemen RAB şöyle diyor: Ulusların aşağılamasına hedef olduğunuz için öfkeyle, kıskançlıkla konuştum.'),
(2004668,68,26,36,7,'Bu nedenle Egemen RAB şöyle diyor: Ant içiyorum ki, çevrenizdeki uluslar da aşağılanacaktır.'),
(2004669,68,26,36,8,'‹‹ ‹Ama siz, ey İsrail dağları, dal budak salacak ve halkım İsrail için ürün vereceksiniz. Çünkü halkım İsrail yakında yurduna dönecek.'),
(2004670,68,26,36,9,'Sizi kayıracak, size yöneleceğim. İşlenecek, ekileceksiniz.'),
(2004671,68,26,36,10,'Ülkenizde yaşayanların sayısını, evet, bütün İsrail halkının sayısını çoğaltacağım. Kentlerde insanlar yaşayacak, yıkıntılar onarılacak.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004672,68,26,36,11,'Ülkenizdeki insan ve hayvan sayısını çoğaltacağım. Verimli olacak, çoğalacaklar. Geçmişte olduğu gibi ülkeniz insanlarla dolup taşacak. Sizi eskisinden daha verimli kılacağım. O zaman benim RAB olduğumu anlayacaksınız.'),
(2004673,68,26,36,12,'Ülkenize insanların, halkım İsrailin girmesini sağlayacağım. Sizi sahiplenecekler. Siz de onların mirası olacaksınız. Onları bir daha çocuklarından yoksun bırakmayacaksınız.'),
(2004674,68,26,36,13,'‹‹ ‹Egemen RAB şöyle diyor: Ey ülke, insanlar sana insan yiyen, ulusunu çocuksuz bırakan ülke diyorlar.'),
(2004675,68,26,36,14,'Bundan böyle artık sen insan yemeyecek, ulusunu çocuksuz bırakmayacaksın. Egemen RAB böyle diyor.'),
(2004676,68,26,36,15,'Artık ulusların aşağılamalarını size işittirmeyeceğim. Ulusların aşağılamasına uğramayacaksınız. Halkınızın bir daha tökezlemesine izin vermeyeceksiniz.› Egemen RAB böyle diyor.››'),
(2004677,68,26,36,16,'RAB bana şöyle seslendi:'),
(2004678,68,26,36,17,'‹‹İnsanoğlu, İsrail halkı kendi ülkesinde yaşarken tutumu ve davranışlarıyla ülkeyi kirletti. Onların davranışı benim gözümde âdet gören bir kadının kirliliği gibiydi.'),
(2004679,68,26,36,18,'Bu yüzden öfkemi üzerlerine boşalttım. Çünkü ülkede kan döktüler, putlarıyla onu kirlettiler.'),
(2004680,68,26,36,19,'Onları uluslara dağıttım, ülkelere yayıldılar. Onları tutumlarına ve davranışlarına göre yargıladım.'),
(2004681,68,26,36,20,'Ulusların arasında her gittikleri yerde kutsal adımı kirlettiler. Çünkü onlar için, ‹Bu RABbin halkı, öyleyken ülkesinden çıkmak zorunda kaldı› dendi.'),
(2004682,68,26,36,21,'İsrail halkının gittiği uluslar arasında kirlettiği kutsal adımın onuru için kaygılandım.'),
(2004683,68,26,36,22,'‹‹Bu nedenle İsrail halkına de ki, ‹Egemen RAB şöyle diyor: Ey İsrail halkı, sizin hatırınız için değil, gittiğiniz uluslar arasında kirlettiğiniz kutsal adımın hatırı için bunları yapacağım.'),
(2004684,68,26,36,23,'Uluslar arasında kirlenen, onlar arasında kirlettiğiniz büyük adımın kutsallığını göstereceğim. Onların gözü önünde kutsallığımı sizin aracılığınızla kanıtladığımda, uluslar benim RAB olduğumu anlayacaklar. Egemen RAB böyle diyor.'),
(2004685,68,26,36,24,'‹‹ ‹Sizi uluslar arasından alacak, bütün ülkelerden toplayıp ülkenize geri getireceğim.'),
(2004686,68,26,36,25,'Üzerinize temiz su dökeceğim, arınacaksınız. Sizi bütün kirliliklerinizden ve putlarınızdan arındıracağım.'),
(2004687,68,26,36,26,'Size yeni bir yürek verecek, içinize yeni bir ruh koyacağım. İçinizdeki taştan yüreği çıkaracak, size etten bir yürek vereceğim.'),
(2004688,68,26,36,27,'Ruhumu içinize koyacağım; kurallarımı izlemenizi, buyruklarıma uyup onları uygulamanızı sağlayacağım.'),
(2004689,68,26,36,28,'Atalarınıza verdiğim ülkede yaşayacak, benim halkım olacaksınız, ben de sizin Tanrınız olacağım.'),
(2004690,68,26,36,29,'Sizi bütün kirliliklerinizden kurtaracağım. Buğdaya seslenecek ve onu çoğaltacağım. Artık size kıtlık göndermeyeceğim.'),
(2004691,68,26,36,30,'Ulusların arasında bir daha kıtlık utancı çekmemeniz için ağaçların meyvesini, tarlaların ürününü çoğaltacağım.'),
(2004692,68,26,36,31,'O zaman kötü yollarınızı, kötü işlerinizi anımsayacaksınız. Günahlarınız, iğrenç uygulamalarınız yüzünden kendinizden tiksineceksiniz.'),
(2004693,68,26,36,32,'Bunu sizin hatırınız için yapmadığımı iyi bilin. Egemen RAB böyle diyor. Davranışlarınızdan utanın, yüzünüz kızarsın, ey İsrail halkı!'),
(2004694,68,26,36,33,'‹‹ ‹Egemen RAB şöyle diyor: Sizi bütün günahlarınızdan arıttığım gün, kentlerinizde yaşamanızı sağlayacağım; yıkıntılar onarılacak.'),
(2004695,68,26,36,34,'Gelip geçenlerin gözünde viran olan ülkenin toprakları işlenecek.'),
(2004696,68,26,36,35,'Şöyle diyecekler: Viran olan bu ülke Aden bahçesi gibi oldu; yıkılıp yerle bir olmuş, kimsesiz kalmış kentler yeniden güçlendiriliyor, içinde oturuluyor.'),
(2004697,68,26,36,36,'O zaman çevrenizde kalan uluslar yıkılanı yeniden yapanın, çıplak yerleri yeniden dikenin ben RAB olduğumu anlayacaklar. Bunu ben RAB söylüyorum ve dediğimi yapacağım.›'),
(2004698,68,26,36,37,'‹‹Egemen RAB şöyle diyor: İsrail halkının benden yine yardım dilemesini sağlayacak ve onlar için şunu yapacağım: Onları bir koyun sürüsü gibi çoğaltacağım.'),
(2004699,68,26,36,38,'Bayramlarda Yeruşalim nasıl kurbanlık hayvanlarla doluyorsa, viran olmuş kentler de insan topluluklarıyla öyle dolup taşacak. O zaman benim RAB olduğumu anlayacaklar.››'),
(2004700,68,26,37,1,'RABbin eli üzerimdeydi, Ruhuylafç beni dışarı çıkardı, kemiklerle dolu bir ovanın ortasına koydu.'),
(2004701,68,26,37,2,'Beni onların arasında her yöne dolaştırdı. Ovada her yere yayılmış, tamamen kurumuş pek çok kemik vardı.'),
(2004702,68,26,37,3,'RAB, ‹‹İnsanoğlu, bu kemikler canlanabilir mi?›› diye sordu. Ben, ‹‹Sen bilirsin, ey Egemen RAB›› diye yanıtladım.'),
(2004703,68,26,37,4,'Bunun üzerine, ‹‹Bu kemikler üzerine peygamberlik et›› dedi, ‹‹Onlara de ki, ‹Kuru kemikler, RABbin sözünü dinleyin!'),
(2004704,68,26,37,5,'Egemen RAB bu kemiklere şöyle diyor: İçinize ruh koyacağım, canlanacaksınız.'),
(2004705,68,26,37,6,'Size kaslar verecek, üzerinizde et oluşturacağım, sizi deriyle kaplayacağım. İçinize ruh koyacağım, canlanacaksınız. O zaman benim RAB olduğumu anlayacaksınız.› ››'),
(2004706,68,26,37,7,'Böylece bana verilen buyruk uyarınca peygamberlik ettim. Ben peygamberlik ederken bir gürültü oldu, bir takırtı duyuldu. Kemikler birbirleriyle birleşiyordu.'),
(2004707,68,26,37,8,'Baktım, işte üzerlerinde kaslar, etler oluşuyor, üstlerini deri kaplıyordu. Ama onlarda ruh yoktu.'),
(2004708,68,26,37,9,'Sonra bana şöyle dedi: ‹‹Rüzgarafç peygamberlik et, insanoğlu, peygamberlik et ve de ki, ‹Egemen RAB şöyle diyor: Ey rüzgar, gel dört yandan es. Bu öldürülmüşlerin üzerine üfle ki canlansınlar!› ››'),
(2004709,68,26,37,10,'Böylece bana verilen buyruk uyarınca peygamberlik ettim. Onların içine solukfç girince canlanıp ayağa kalktılar. Çok, çok büyük bir kalabalık oluşturuyorlardı. ‹‹Soluk›› anlamına da gelir.'),
(2004710,68,26,37,11,'Sonra bana, ‹‹İnsanoğlu, bu kemikler bütün İsrail halkını simgeliyor›› dedi, ‹‹Onlar, ‹Kemiklerimiz kurudu, umudumuz yok oldu, bittik› diyorlar.'),
(2004711,68,26,37,12,'Bu yüzden peygamberlik et ve onlara de ki, ‹Egemen RAB şöyle diyor: Ey halkım, mezarlarınızı açıp sizi oradan çıkaracak, İsrail ülkesine geri getireceğim.'),
(2004712,68,26,37,13,'Mezarlarınızı açıp sizi çıkardığım zaman benim RAB olduğumu anlayacaksınız, ey halkım.'),
(2004713,68,26,37,14,'Ruhumu içinize koyacağım, canlanacaksınız. Sizi kendi ülkenize yerleştireceğim. O zaman, bunu söyleyenin ve yapanın ben RAB olduğumu anlayacaksınız.› ›› Böyle diyor RAB.'),
(2004714,68,26,37,15,'RAB bana şöyle seslendi:'),
(2004715,68,26,37,16,'‹‹İnsanoğlu, bir değnek al, üzerine ‹Yahuda ve dostları İsrailliler için› diye yaz. Sonra başka bir değnek al, üzerine ‹Yusufla dostları İsrailliler için Efrayimin değneği› diye yaz.'),
(2004716,68,26,37,17,'İki değneği yan yana getirerek birleştir. Öyle ki, elinde bir değnek gibi olsun.'),
(2004717,68,26,37,18,'‹‹Halkından biri, ‹Bu yaptığının anlamı ne? Bize açıklamaz mısın?› diye sorarsa,'),
(2004718,68,26,37,19,'şöyle yanıtlayacaksın: ‹Egemen RAB şöyle diyor: Efrayimin elindeki değneği -Yusufla dostları İsrail oymaklarının değneğini- alıp Yahuda değneğiyle birleştireceğim. İkisinden bir değnek yapıp elimde tutacağım.›'),
(2004719,68,26,37,20,'Üzerine yazdığın değnekleri görebilecekleri şekilde elinde tut.'),
(2004720,68,26,37,21,'Onlara de ki, ‹Egemen RAB şöyle diyor: İsraillileri gittikleri ulusların içinden alacağım. Onları her yerden toplayıp ülkelerine geri getireceğim.'),
(2004721,68,26,37,22,'Onları ülkede, İsrail dağları üzerinde tek bir ulus yapacağım. Hepsinin tek kralı olacak. Artık iki ayrı ulus olmayacaklar, iki krallığa bölünmeyecekler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004722,68,26,37,23,'Artık putlarıyla, iğrenç uygulamalarıyla, isyanlarıyla kendilerini kirletmeyecekler. Onları yerleştikleri, içinde günah işledikleri yerlerden kurtarıp arındıracağım. Onlar halkım olacak, ben de onların Tanrısı olacağım.'),
(2004723,68,26,37,24,'‹‹ ‹Kulum Davut onların kralı olacak, hepsinin tek çobanı olacak. Buyruklarımı izleyecek, kurallarıma uyacak, onları uygulayacaklar.'),
(2004724,68,26,37,25,'Kulum Yakupa verdiğim, atalarınızın yaşadığı ülkeye yerleşecekler. Kendileri, çocukları, çocuklarının çocukları sonsuza dek orada yaşayacaklar. Kulum Davut da sonsuza dek onların önderi olacak.'),
(2004725,68,26,37,26,'Onlarla esenlik antlaşması yapacağım. Bu onlarla sonsuza dek geçerli bir antlaşma olacak. Onları yeniden oraya yerleştirip sayıca çoğaltacağım. Tapınağımı sonsuza dek onların ortasına kuracağım.'),
(2004726,68,26,37,27,'Konutum aralarında olacak; onların Tanrısı olacağım, onlar da benim halkım olacak.'),
(2004727,68,26,37,28,'Tapınağım sonsuza dek onların arasında oldukça uluslar İsrail''i kutsal kılanın ben RAB olduğumu anlayacaklar.› ››'),
(2004728,68,26,38,1,'RAB bana şöyle seslendi:'),
(2004729,68,26,38,2,'‹‹İnsanoğlu, yüzünü Magog ülkesinden Roşun, Meşekin, Tuvalın önderi Goga çevir, ona karşı peygamberlik et.'),
(2004730,68,26,38,3,'De ki, ‹Egemen RAB şöyle diyor: Ey Roşun, Meşekin, Tuvalın önderi Gog, sana karşıyım.'),
(2004731,68,26,38,4,'Seni geldiğin yoldan geri çevirecek, çenelerine çengel takacağım. Seni ve bütün ordunu, atları, tam donanmış atlıları, küçük büyük kalkanlı, hepsi kılıç kullanan büyük kalabalığı dışarıya sürükleyeceğim.'),
(2004732,68,26,38,5,'Onlarla birlikte hepsi kalkanlı, miğferli Perslileri, Kûşluları, Pûtluları,'),
(2004733,68,26,38,6,'Gomerin bütün ordusunu, uzak kuzeydeki Beyttogarmanın bütün ordusunu ve yanındaki birçok ulusu da sürükleyeceğim. Tuvalın baş önderi››.'),
(2004734,68,26,38,7,'‹‹ ‹Hazır ol! Çevrende toplanmış büyük kalabalıkla birlikte hazırlan. Onları sen gözeteceksin.'),
(2004735,68,26,38,8,'Uzun zaman sonra savaşa çağrılacaksın. Gelecek yıllarda, halkı birçok ulustan uzun zamandır ıssız kalmış İsrail dağlarında toplanmış, savaştan rahata kavuşmuş bir ülkeye saldıracaksın. Uluslar arasından çıkarılmış olan bu halk, şimdi güvenlik içinde yaşıyor.'),
(2004736,68,26,38,9,'Sen, bütün askerlerin ve seninle olan birçok ulus çıkıp kasırga gibi geleceksiniz; ülkeyi kaplayan bulut gibi olacaksınız.'),
(2004737,68,26,38,10,'‹‹ ‹Egemen RAB şöyle diyor: O gün aklına bazı düşünceler gelecek, kötü düzenler tasarlayacaksın.'),
(2004738,68,26,38,11,'Diyeceksin ki: Sursuz köyleri olan bir ülkeye saldıracak, esenlik ve güvenlik içinde yaşayan insanların üzerine yürüyeceğim. Bu köylerin tümü sursuz; kapıları da kapı sürgüleri de yok.'),
(2004739,68,26,38,12,'Viran olmuş kentlerde yaşayan halkı soyup malını yağma edeceğim. Sürüsü, malı olan, dünyanın ortasında yaşayan bu ulusların arasından toplanmış halka karşı elimi uzatacağım.'),
(2004740,68,26,38,13,'Saba, Dedan, Tarşiş tüccarları ve köyleri sana, Yağmalamak için mi geldin? Çapul malı toplamak, altın, gümüş taşımak, hayvan, mal götürmek, bol ganimet elde etmek için mi bu kalabalığı topladın? diyecek.›'),
(2004741,68,26,38,14,'‹‹Bu yüzden, ey insanoğlu, peygamberlik et ve Goga de ki, ‹Egemen RAB şöyle diyor: O gün halkım İsrail güvenlik içinde yaşarken bunu farketmeyecek misin?'),
(2004742,68,26,38,15,'Sen ve seninle birlikte birçok ulustan oluşan tümü ata binmiş büyük bir kalabalık, güçlü bir ordu uzak kuzeyden geleceksiniz.'),
(2004743,68,26,38,16,'Ülkeyi kaplayan bir bulut gibi halkım İsrailin üzerine yürüyeceksiniz. Son günlerde, ey Gog, seni ülkeme saldırtacağım. Öyle ki, ulusların gözü önünde kutsallığımı senin aracılığınla gösterdiğim zaman beni tanıyabilsinler.'),
(2004744,68,26,38,17,'‹‹ ‹Egemen RAB şöyle diyor: Eski günlerde kullarım İsrail peygamberleri aracılığıyla hakkında konuştuğum kişi değil misin sen? O dönemde seni onlara saldırtacağıma ilişkin yıllarca peygamberlik ettiler.'),
(2004745,68,26,38,18,'‹‹ ‹Gog İsrail ülkesine saldırdığı gün öfkem alevlenecek. Egemen RAB böyle diyor.'),
(2004746,68,26,38,19,'Kıskançlığımla ve öfkemin şiddetiyle diyorum ki, o gün İsrail ülkesinde büyük bir yer sarsıntısı olacak.'),
(2004747,68,26,38,20,'Denizdeki balıklar, gökteki kuşlar, kırdaki hayvanlar, yerde sürünen bütün yaratıklar ve dünyadaki bütün insanlar önümde titreyecekler. Dağlar yerle bir edilecek, kayalıklar ufalanacak, her duvar çökecek.'),
(2004748,68,26,38,21,'Bütün dağlarımda Goga karşı kılıcı çağıracağım. Egemen RAB böyle diyor. Herkes birbirine kılıç çekecek.'),
(2004749,68,26,38,22,'Onu salgın hastalıkla, kanla cezalandıracağım; onun, ordusunun, ondan yana olan birçok ulusun üzerine sağanak yağmur, dolu, ateşli kükürt yağdıracağım.'),
(2004750,68,26,38,23,'Böylece büyüklüğümü, kutsallığımı gösterecek, birçok ulusun gözünde kendimi tanıtacağım. O zaman benim RAB olduğumu anlayacaklar.› ››'),
(2004751,68,26,39,1,'‹‹İnsanoğlu, Goga karşı peygamberlik et ve ona de ki, ‹Egemen RAB şöyle diyor: Ey Roşun, Meşekin, Tuvalın önderi Gog, sana karşıyım.'),
(2004752,68,26,39,2,'Seni geri çevirip sürükleyeceğim. Seni uzak kuzeyden çıkarıp İsrailin dağlarına getireceğim.'),
(2004753,68,26,39,3,'Sol elindeki yayını vuracak, sağ elindeki oklarını düşüreceğim.'),
(2004754,68,26,39,4,'Sen de askerlerinle senden yana olan uluslar da İsrail dağlarına serileceksiniz. Sizi yem olarak her çeşit yırtıcı kuşa, yabanıl hayvana vereceğim.'),
(2004755,68,26,39,5,'Açık kırlarda düşüp öleceksiniz. Çünkü bunu ben söyledim. Egemen RAB böyle diyor.'),
(2004756,68,26,39,6,'Magogun ve kıyıda güvenlik içinde yaşayanların üzerine ateş yağdıracağım. O zaman benim RAB olduğumu anlayacaklar. Tuvalın baş önderi››.'),
(2004757,68,26,39,7,'‹‹ ‹Halkım İsrail arasında kutsal adımı tanıtacağım. Bundan böyle kutsal adımın aşağılanmasına izin vermeyeceğim. Uluslar benim İsrailde kutsal olan RAB olduğumu anlayacaklar.'),
(2004758,68,26,39,8,'O gün yaklaştı! Söylediklerim olacak. Egemen RAB böyle diyor. Budur sözünü ettiğim gün!'),
(2004759,68,26,39,9,'‹‹ ‹O zaman İsrail kentlerinde yaşayanlar dışarı çıkıp topladıkları silahları yakacaklar. Küçük büyük kalkanları, yayları, okları, sopaları, mızrakları ateşe atacaklar. Bunlarla yedi yıl ateş yakacaklar.'),
(2004760,68,26,39,10,'Kırdan odun toplamayacak, ormandan odun kesmeyecekler. Yakmak için silahları kullanacaklar. Mallarını yağmalayanları yağmalayacak, kendilerini soyanları soyacaklar. Egemen RAB böyle diyor.'),
(2004761,68,26,39,11,'‹‹ ‹O gün Lut Gölünün doğusunda, Gezginler Deresinde Goga İsrailde bilinen bir mezar yeri vereceğim. Gogla bütün ordusu orada gömülecek. Oraya Hamon-Gog Vadisi adı verilecek. Oradan geçecek gezginlerin önü kesilecek.'),
(2004762,68,26,39,12,'İsrail halkı ülkeyi arındırmak için onları gömecek. Bu yedi ay sürecek.'),
(2004763,68,26,39,13,'Onları bütün ülke halkı gömecek. Görkemimi açıkladığım gün onlar için onur olacak. Egemen RAB böyle diyor. metin ‹‹Orada››.'),
(2004764,68,26,39,14,'‹‹ ‹Ülkeyi arındırmak için adamlar görevlendirilecek. Bazıları ülkeyi sürekli dolaşacak, öbürleriyse yerde kalan cesetleri gömecekler. Yedi aylık süre bitince, araştırma işine başlayacaklar.'),
(2004765,68,26,39,15,'Bu adamlar ülkenin her yanını dolaşacak. Bir insan kemiği görünce, mezarcılar onu Hamon-Gog Vadisine gömünceye dek, yanına bir işaret koyacak.'),
(2004766,68,26,39,16,'Orada Hamona adında bir kent olacak. Böylelikle ülke arındırılacak.›'),
(2004767,68,26,39,17,'‹‹İnsanoğlu, Egemen RAB şöyle diyor: Her çeşit kuşa ve yabanıl hayvana seslen: ‹Sizin için hazırlayacağım kurbana, İsrail dağları üzerindeki büyük kurbana gelin, her yandan toplanın! Orada et yiyecek, kan içeceksiniz.'),
(2004768,68,26,39,18,'Başanın besili hayvanlarının -koçların, kuzuların, tekelerin, boğaların- etini yiyip kanını içer gibi yiğitlerin etini yiyecek, dünya önderlerinin kanını içeceksiniz.'),
(2004769,68,26,39,19,'Sizin için hazırlayacağım kurbandan doyana dek yağ yiyeceksiniz, sarhoş oluncaya dek kan içeceksiniz.'),
(2004770,68,26,39,20,'Soframda atlardan, atlılardan, yiğitlerden ve her çeşit askerden bol bol yiyip doyacaksınız.› Egemen RAB böyle diyor.'),
(2004771,68,26,39,21,'‹‹Görkemimi uluslar arasında açıklayacağım. Bütün uluslar kendilerine verdiğim cezayı, üzerlerine koyduğum elimi görecekler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004772,68,26,39,22,'İsrail halkı o günden başlayarak benim Tanrıları RAB olduğumu anlayacak.'),
(2004773,68,26,39,23,'Uluslar İsrail halkının işlediği suç yüzünden, bana ihanet ettiği için sürgüne gittiğini anlayacaklar. Yüzümü onlardan gizledim, onları düşmanlarının eline teslim ettim, hepsi kılıçtan geçirildi.'),
(2004774,68,26,39,24,'Onları kirliliklerine, isyanlarına göre cezalandırdım, yüzümü onlardan gizledim.'),
(2004775,68,26,39,25,'‹‹Bundan ötürü Egemen RAB şöyle diyor: Yakupun sürgündeki soyunu geri getirecek, İsrail halkına acıyacağım. Kutsal adımı kıskançlıkla koruyacağım.'),
(2004776,68,26,39,26,'Ülkelerinde güvenlik içinde yaşayınca, onları korkutan kimse olmayınca, utançlarını, bana ettikleri bütün ihanetleri unutacaklar.'),
(2004777,68,26,39,27,'Onları uluslar arasından geri getirip düşman ülkelerinden topladığım zaman, onlar aracılığıyla birçok ulusa kutsallığımı göstereceğim.'),
(2004778,68,26,39,28,'O zaman benim Tanrıları RAB olduğumu anlayacaklar. Onları uluslar arasına sürgüne göndermeme karşın, hiçbirini bırakmadan ülkelerine geri getireceğim.'),
(2004779,68,26,39,29,'Onlardan bir daha yüzümü gizlemeyeceğim, çünkü İsrail halkı üzerine Ruhum''u dökeceğim.›› Egemen RAB böyle diyor.'),
(2004780,68,26,40,1,'Sürgünlüğümüzün yirmi beşinci yılı, yılın başında, ayın onuncu günü, Yeruşalim Kentinin düşüşünün on dördüncü yılı, tam o gün RABbin eli beni yakalayıp oraya götürdü.'),
(2004781,68,26,40,2,'Görümde Tanrı beni İsrail ülkesine götürüp çok yüksek bir dağın üzerine koydu. Dağın güneyinde kente benzer yapılar vardı.'),
(2004782,68,26,40,3,'Tanrı beni oraya götürdü, tunca benzer bir adam gördüm. Elinde keten ip ve bir ölçü değneği tutarak kapının girişinde duruyordu.'),
(2004783,68,26,40,4,'Bana, ‹‹İnsanoğlu, gözlerinle gör, kulaklarınla işit, sana göstereceğim her şeye dikkat et›› dedi, ‹‹Sen bunun için buraya getirildin. Göreceğin her şeyi İsrail halkına anlat.››'),
(2004784,68,26,40,5,'Tapınağı çepeçevre kuşatan bir duvar gördüm. Adamın elindeki ölçü değneğinin uzunluğu altı arşındı. Her arşına bir elin eni kadar uzunluk eklenmiştifı. Adam duvarı ölçtü; kalınlığı ve yüksekliği bir ölçü değneği kadardı. uzunluğu, bir arşına bir elin eni eklenerek elde edilir (yaklaşık 53 cm).'),
(2004785,68,26,40,6,'Sonra doğuya bakan kapıya gitti, basamakları çıkıp kapı eşiğini ölçtü. Eni bir ölçü değneği kadardı.'),
(2004786,68,26,40,7,'Bekçi odalarının her birinin uzunluğu ve genişliği bir ölçü değneği kadardı. Odaların arasındaki duvarın kalınlığı beş arşındı. Tapınağa bakan eyvanın kapı eşiği bir ölçü değneği uzunluktaydı.'),
(2004787,68,26,40,8,'Eyvanı ölçtü;'),
(2004788,68,26,40,9,'genişliği sekiz arşın, kapı sövelerinin kalınlığı ikişer arşındı. Eyvan tapınağa bakıyordu.'),
(2004789,68,26,40,10,'Doğu Kapısının her yanında üçer bekçi odası vardı. Hepsi aynı ölçüdeydi. Odalar arasındaki duvarların ölçüsü de aynıydı. geçmektedir: ‹‹Bir kapı eşiğinin eni bir ölçü değneği kadardı.›› Bu tümce Septuagintada yoktur.'),
(2004790,68,26,40,11,'Adam kapının genişliğini ölçtü. Genişliği on, iç girişin genişliği on üç arşındı.'),
(2004791,68,26,40,12,'Her bekçi odasının önünde bir arşın yüksekliğinde bir duvar vardı. Odalar kare şeklindeydi, kenarları altışar arşındı.'),
(2004792,68,26,40,13,'Sonra girişleri karşı karşıya olan odaların arka duvarlarının arasını ölçtü; yirmi beş arşındı.'),
(2004793,68,26,40,14,'Sütunları ölçtü, altmış arşındı. Kapının çevresindeki avlu sütunlara kadar uzanıyordu.'),
(2004794,68,26,40,15,'Kapı girişinden eyvanın sonuna kadarki uzaklık elli arşındı.'),
(2004795,68,26,40,16,'Her iki yandaki bekçi odalarında, odalar arasındaki duvarlarda ve eyvanın çepeçevre duvarlarında içe bakan kafesli pencereler vardı. Bölme duvarları hurma ağacı motifleriyle kaplıydı. Septuaginta ‹‹Eyvanın açık alanını ölçtü, yirmi arşındı››.'),
(2004796,68,26,40,17,'Adam bundan sonra beni dış avluya götürdü. Orada odalar ve dış avluyu çevreleyen taş yol vardı. Taş yol boyunca otuz oda vardı.'),
(2004797,68,26,40,18,'Girişin iki yanındaki taş yolun genişliği kapıların uzunluğu kadardı. Bu aşağı taş yoldu.'),
(2004798,68,26,40,19,'Avlunun genişliğini aşağı girişten iç avlunun girişine dek ölçtü. Doğu ve kuzeydeki uzaklık yüz arşındı.'),
(2004799,68,26,40,20,'Adam dış avlunun kuzeye bakan kapısının uzunluğunu ve genişliğini ölçtü.'),
(2004800,68,26,40,21,'İki yandaki üçer bekçi odasının, aralarındaki duvarların ve eyvanın ölçüsü, birinci kapının ölçüsünün aynısıydı. Uzunluğu elli arşın, genişliği yirmi beş arşındı.'),
(2004801,68,26,40,22,'Pencerelerin, eyvanın, hurma ağacı motiflerinin ölçüsü, doğuya bakan kapının ölçüsünün aynısıydı. Oraya yedi basamakla çıkılıyordu, eyvan bunların karşısındaydı.'),
(2004802,68,26,40,23,'Doğu Kapısına olduğu gibi, Kuzey Kapısına da bakan bir iç avlu kapısı vardı. Adam bu iki kapı arasındaki uzaklığı ölçtü, yüz arşındı.'),
(2004803,68,26,40,24,'Adam beni güneye doğru götürdü. Orada güneye bakan bir kapı gördüm. Adam kapının sövelerini ve eyvanı ölçtü. Ölçüleri öbürlerinin aynısıydı.'),
(2004804,68,26,40,25,'Öbürlerinde olduğu gibi, bu kapının ve eyvanın her yanında da pencereler vardı. Uzunluğu elli arşın, genişliği yirmi beş arşındı.'),
(2004805,68,26,40,26,'Oraya yedi basamakla çıkılıyordu, eyvan bunların karşısındaydı. İki kapı sövesi de hurma ağacı motifleriyle kaplıydı.'),
(2004806,68,26,40,27,'İç avlunun güneye bakan bir kapısı vardı. Adam bu kapıdan güneydeki dış kapıya kadar olan uzaklığı ölçtü, yüz arşındı.'),
(2004807,68,26,40,28,'Adam beni Güney Kapısından iç avluya götürdü. Güney Kapısını ölçtü. Ölçüleri öbürlerinin aynısıydı.'),
(2004808,68,26,40,29,'Bekçi odalarının, odalar arasındaki duvarların, eyvanın ölçüleri öbürlerinin aynısıydı. Dış duvarlarda ve eyvanın her yanında pencereler vardı. Girişin uzunluğu elli arşın, genişliği yirmi beş arşındı.'),
(2004809,68,26,40,30,'Eyvan dış avluya bakıyordu. Kapı söveleri hurma ağacı motifleriyle kaplıydı. Oraya sekiz basamakla çıkılıyordu. geçiyor: ‹‹İç avlunun çevresindeki eyvanların uzunluğu yirmi beş arşın, genişliği beş arşındı.›› Bu tümce bazı İbranice elyazmalarında geçmemektedir.'),
(2004810,68,26,40,32,'Adam beni doğudaki iç avluya götürdü. Oradaki kapıyı ölçtü. Ölçüleri öbürlerinin aynısıydı.'),
(2004811,68,26,40,33,'Bekçi odalarının, odalar arasındaki duvarların, eyvanın ölçüleri öbürlerinin aynısıydı. Dış duvarlarda ve eyvanın her yanında pencereler vardı. Girişin uzunluğu elli arşın, genişliği yirmi beş arşındı.'),
(2004812,68,26,40,34,'Eyvan dış avluya bakıyordu. Kapı söveleri hurma ağacı motifleriyle kaplıydı. Oraya sekiz basamakla çıkılıyordu.'),
(2004813,68,26,40,35,'Sonra adam beni Kuzey Kapısına götürdü. Kapıyı ölçtü. Ölçüleri öbürlerinin aynısıydı.'),
(2004814,68,26,40,36,'Bunun da bekçi odaları, aralarındaki duvarlar, eyvanı aynıydı. Kapının her yanında pencereler vardı. Girişin uzunluğu elli arşın, genişliği yirmi beş arşındı.'),
(2004815,68,26,40,37,'Eyvan dış avluya bakıyordu. Kapı söveleri her yanda hurma ağacı motifleriyle kaplıydı. Oraya sekiz basamakla çıkılıyordu.'),
(2004816,68,26,40,38,'İç avlu girişlerindeki eyvanların yanında kapısı eyvana açılan bir oda vardı. Yakmalık sunular burada yıkanıyordu.'),
(2004817,68,26,40,39,'Eyvanın her iki yanında ikişer masa vardı. Yakmalık sunu, günah sunusu ve suç sunusu için hayvanlar bu masaların üzerinde kesiliyordu.'),
(2004818,68,26,40,40,'Eyvanın dış duvarının yanında, Kuzey Kapısının basamaklarının her iki yanında ikişer olmak üzere dört masa daha vardı.'),
(2004819,68,26,40,41,'Böylece kurbanlık hayvanların kesimi için kapının her iki yanında dörder olmak üzere sekiz masa vardı.'),
(2004820,68,26,40,42,'Yakmalık sunular için yontma taştan dört masa vardı. Her masanın uzunluğu ve genişliği birer buçuk arşın, yüksekliği bir arşındı. Yakmalık sunularla öbür kurbanların kesiminde kullanılan aletleri bunların üzerine koyuyorlardı.'),
(2004821,68,26,40,43,'Odanın duvarlarına çifte çengeller asılmıştı; her biri bir el genişliğindeydi. Masalar sunulacak kurban eti için kullanılıyordu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004822,68,26,40,44,'İç kapının dış bölümünde, iç avluda iki oda vardı. Bunlardan biri Kuzey Kapısının yanındaydı ve güneye bakıyordu, öbürü Güney Kapısının yanındaydı ve kuzeye bakıyordu.'),
(2004823,68,26,40,45,'Adam bana, ‹‹Güneye bakan oda tapınakta hizmet görecek kâhinler için›› dedi,'),
(2004824,68,26,40,46,'‹‹Kuzeye bakan oda da sunakta hizmet görecek kâhinler için. Bunlar Levi soyundan, RABbe hizmet etmek için Ona yaklaşan Sadokoğullarıdır.›› odalar››.'),
(2004825,68,26,40,47,'Adam avluyu ölçtü. Kareydi, uzunluğu yüz arşın, genişliği yüz arşındı. Sunak tapınağın önündeydi.'),
(2004826,68,26,40,48,'Adam sonra beni tapınağın eyvanına götürüp eyvanın kapı sövelerini ölçtü. Her iki yandaki sövelerin genişliği beşer arşındı. Girişin genişliği on dört arşın, iki yandaki duvarların genişliği de üçer arşındı.'),
(2004827,68,26,40,49,'Eyvanın uzunluğu yirmi arşın, genişliği on iki arşındı. Oraya basamaklarla çıkılıyordu. Kapı sövelerinin her bir yanında sütunlar vardı. yandaki duvarların genişliği de üçer arşındı››, Masoretik metin ‹‹Girişin iki yanının genişliği üçer arşındı››. arşın››.'),
(2004828,68,26,41,1,'Bundan sonra adam beni tapınağın ana bölümüne götürüp kapı sövelerini ölçtü. Sövelerinfö genişliği her yandan altı arşındı.'),
(2004829,68,26,41,2,'Girişinin genişliği on arşın, her yandan buna bağlı duvarların genişliği beşer arşındı. Ana bölümü de ölçtü. Uzunluğu kırk arşın, genişliği yirmi arşındı. metin ‹‹Çadırın››.'),
(2004830,68,26,41,3,'Sonra iç odaya gidip girişin sövelerini ölçtü. Her biri iki arşın genişliğindeydi. Girişin genişliği altı arşın, her yandan buna bağlı duvarların genişliği yedi arşındı.'),
(2004831,68,26,41,4,'Ana bölümün ötesindeki iç odayı ölçtü. Uzunluğu ve genişliği yirmişer arşındı. Adam, ‹‹Bu En Kutsal Yerdir›› dedi.'),
(2004832,68,26,41,5,'Tapınağın duvarını ölçtü, kalınlığı altı arşındı. Tapınağın çevresindeki her yan odanın genişliği dört arşındı.'),
(2004833,68,26,41,6,'Bu yan odalar üç kattı, her katta otuz oda vardı. Tapınağın duvarları boyunca yan odalara destek görevi yapan çıkıntılar vardı. Öyle ki, destekler tapınak duvarlarına girmesin.'),
(2004834,68,26,41,7,'Tapınağın çevresindeki yan odalar yukarı kata doğru çıktıkça genişliyordu. Tapınağın çevresindeki yapının yukarıya çıkan bir merdiveni vardı. Yukarıya doğru çıkıldıkça yan odalar genişliyordu. Merdivenle alt kattan orta kata, oradan da üst kata çıkılıyordu.'),
(2004835,68,26,41,8,'Tapınağın çevresinde yan odaların temelini oluşturan yüksek bir kaldırım gördüm. Uzunluğu bir değnek kadar, yani altı arşındı.'),
(2004836,68,26,41,9,'Yan odaların dış duvarının kalınlığı beş arşındı. Tapınağın yan odaları ile kâhin odaları arasındaki açık alanın genişliği tapınak çevresi boyunca yirmi arşındı.'),
(2004837,68,26,41,11,'Yan odaların girişi açık alana bakıyordu; biri kuzeyde, öbürü güneydeydi. Açık alana bitişik temelin genişliği her yandan beş arşındı.'),
(2004838,68,26,41,12,'Tapınağın batısında açık alana bakan bir yapı vardı. Genişliği yetmiş arşındı; duvarının kalınlığı her yandan beş arşın, uzunluğu doksan arşındı.'),
(2004839,68,26,41,13,'Bundan sonra adam tapınağı ölçtü. Uzunluğu yüz arşındı. Tapınağın açık alanı, yapı ve duvarları yüz arşın uzunluktaydı.'),
(2004840,68,26,41,14,'Doğuda tapınağın açık alanının tapınağın önüyle birlikte genişliği yüz arşındı.'),
(2004841,68,26,41,15,'Adam tapınağın arkasındaki açık alana bakan yapının iki yanındaki koridorların uzunluğunu ölçtü; yüz arşındı. Ana bölüm, iç oda, avluya bakan eyvan,'),
(2004842,68,26,41,16,'kapı eşikleri, kafesli pencereler, eşiğin karşısındaki üç katı çevreleyen koridorlar tabandan pencerelere dek ağaç kaplıydı. Pencereler açılıp kapanabiliyordu.'),
(2004843,68,26,41,17,'Girişin üstü, iç oda, dışarısı ve bütün iç ve dış duvarlar düzenli aralıklarla'),
(2004844,68,26,41,18,'Keruv ve hurma ağacı motifleriyle kaplıydı. İki Keruv arasında bir hurma ağacı vardı. Her Keruvun iki yüzü vardı:'),
(2004845,68,26,41,19,'Bir yanda hurma ağacına bakan insan yüzü, öbür yanda hurma ağacına bakan genç aslan yüzü. Tapınak çepeçevre Keruv ve hurma ağacı oymalarıyla bezenmişti.'),
(2004846,68,26,41,20,'Tabandan girişin üstündeki bölüme dek ana bölümün duvarları Keruv ve hurma ağacı oymalarıyla kaplıydı.'),
(2004847,68,26,41,21,'Ana bölümün kapı söveleri kare şeklindeydi, En Kutsal Yerin önündeki kapı söveleri bunlara benziyordu.'),
(2004848,68,26,41,22,'Üç arşın yüksekliğinde, iki arşın uzunluğunda ağaçtan yapılmış bir sunak vardı. Köşeleri, ayakları, yanları ağaçtandı. Adam bana, ‹‹RABbin önündeki masa budur›› dedi.'),
(2004849,68,26,41,23,'Ana bölümün ve En Kutsal Yerin çift kanatlı birer kapısı vardı.'),
(2004850,68,26,41,24,'Her kapının iki menteşeli kanadı vardı.'),
(2004851,68,26,41,25,'Duvarlara olduğu gibi, ana bölümün kapılarına da Keruv ve hurma ağacı oymaları yapılmıştı. Dışarda, eyvanın önünde ağaçtan bir asma tavan vardı.'),
(2004852,68,26,41,26,'Eyvanın yan duvarlarındaki kafesli pencerelerin iki yanı hurma ağacı oymalarıyla kaplıydı. Tapınağın yan odalarıyla asma tavanları böyleydi.'),
(2004853,68,26,42,1,'Adam beni kuzeye giden yoldan dış avluya çıkardı. Tapınağın açık alanına ve dış avlunun kuzeyindeki yapılara bakan odalara götürdü.'),
(2004854,68,26,42,2,'Kapısı kuzeye bakan bu yapının uzunluğu yüz arşın, genişliği elli arşındı.'),
(2004855,68,26,42,3,'İç avlunun yirmi arşınlık bölümüyle dış avlunun taş yoluna bakan üç katın koridorları karşı karşıyaydı.'),
(2004856,68,26,42,4,'Odaların önünde genişliği on arşın, uzunluğu yüz arşın olan bir iç koridor vardı. Kapıları kuzeye bakıyordu.'),
(2004857,68,26,42,5,'Yapının üst kattaki odaları alt ve orta kattaki odalardan daha dardı. Çünkü üst kattaki koridorlar daha çok yer kaplıyordu.'),
(2004858,68,26,42,6,'Avlularda sütunlar olmasına karşın, üçüncü kattaki odaların sütunları yoktu. Bu yüzden bu odalar alt ve orta kattaki odalardan daha dardı.'),
(2004859,68,26,42,7,'Odaların önünde, odalara ve dış avluya paralel bir dış duvar vardı, elli arşın uzunluktaydı.'),
(2004860,68,26,42,8,'Dış avlu yanındaki sıra odaların uzunluğu elli arşınken, ana bölüme daha yakın sıra odaların uzunluğu yüz arşındı.'),
(2004861,68,26,42,9,'Alt kattaki odaların dış avludan girilecek gibi doğu yönünde bir girişleri vardı. Masoretik metin ‹‹Bir arşın››.'),
(2004862,68,26,42,10,'İç avlunun güneyi boyunca, açık alana ve dış avludaki yapılara bakan başka odalar vardı.'),
(2004863,68,26,42,11,'Kuzeydeki odalarda olduğu gibi, bu odaların önünde de bir geçit vardı. Odaların uzunlukları, genişlikleri aynıydı, çıkışları ve boyutları kuzeydeki odalara benziyordu. Güneydeki odaların girişleri kuzeydekiler gibiydi. Geçidin başlangıcında bir giriş vardı. Arka duvarlar boyunca doğuya uzanan bu geçit odalara açılıyordu.'),
(2004864,68,26,42,13,'Bundan sonra adam, ‹‹Tapınağın açık alanına bakan kuzey ve güneydeki odalar kutsaldır›› dedi, ‹‹RABbin önünde hizmet eden kâhinler orada en kutsal sunulardan yiyecekler. En kutsal sunuları -tahıl, günah ve suç sunularını- oraya koyacaklar. Çünkü orası kutsaldır.'),
(2004865,68,26,42,14,'Kâhinler kutsal alana girdikten sonra, hizmet ederken giydikleri giysileri orada bırakmadan dış avluya çıkmayacaklar. Çünkü bu giysiler kutsaldır. Halkın bulunduğu yerlere gitmeden önce başka giysiler giymeliler.››'),
(2004866,68,26,42,15,'Adam iç tapınağı ölçmeyi bitirince, beni Doğu Kapısından dışarıya götürdü, o alanı her yandan ölçtü.'),
(2004867,68,26,42,16,'Doğu yanını ölçü değneğiyle ölçtü, beş yüz arşınfş kadardı.'),
(2004868,68,26,42,17,'Kuzey yanını ölçtü, beş yüz arşınfş kadardı.'),
(2004869,68,26,42,18,'Güney yanını ölçtü, beş yüz arşınfş kadardı.'),
(2004870,68,26,42,19,'Sonra batıya dönüp ölçtü, beş yüz arşınfş kadardı.'),
(2004871,68,26,42,20,'Böylece alanın dört yanını ölçtü. Kutsal olanı kutsal olmayandan ayırmak için alanın çevresinde bir duvar vardı; uzunluğu ve genişliği beşer yüz arşındı. değneği››.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004872,68,26,43,1,'Adam beni doğuya bakan kapıya götürdü.'),
(2004873,68,26,43,2,'İsrail Tanrısının görkeminin doğudan geldiğini gördüm. Sesi gürül gürül akan suların sesi gibiydi. Görkeminden yeryüzü aydınlıkla doldu.'),
(2004874,68,26,43,3,'Gördüğüm görüm, Tanrı kenti yok etmeye geldiğinde ve Kevar Irmağı kıyısında gördüğüm görümlere benziyordu. Yüzüstü yere düştüm.'),
(2004875,68,26,43,4,'RABbin görkemi doğuya bakan kapıdan tapınağa girdi.'),
(2004876,68,26,43,5,'Ruh beni ayağa kaldırıp iç avluya götürdü. RABbin görkemi tapınağı doldurdu.'),
(2004877,68,26,43,6,'Adam orada yanımda dururken, tapınaktan birinin bana seslendiğini duydum.'),
(2004878,68,26,43,7,'Bana şöyle dedi: ‹‹İnsanoğlu, tahtımın yeri, ayaklarımın basacağı, İsrail halkıyla sonsuza dek yaşayacağım yer burasıdır. Bundan böyle İsrail halkı da kralları da fahişelikleriyle ve krallarının cesetleriyle bir daha kutsal adımı kirletmeyecek.'),
(2004879,68,26,43,8,'Onlar kapı eşiklerini kapı eşiğimin, sövelerini sövelerimin bitişiğine yerleştirdiler. Benimle aralarında yalnızca bir duvar vardı. İğrenç uygulamalarıyla kutsal adımı kirlettiler. Bu yüzden öfkemle onları yok ettim.'),
(2004880,68,26,43,9,'Şimdi fahişeliklerini, krallarının cesetlerini benden uzaklaştırsınlar; ben de sonsuza dek aralarında yaşayayım.'),
(2004881,68,26,43,10,'‹‹İnsanoğlu, günahlarından utanmaları için bu tapınağı İsrail halkına tanıt. Tapınağın tasarısını incelesinler.'),
(2004882,68,26,43,11,'Eğer bütün yaptıklarından utanıyorlarsa, tapınağın tasarını -düzenlemesini, girişlerini, çıkışlarını- kurallarını, yasalarını onlara bildir. Tasarı onların gözü önünde yaz ki, bütün düzenine, kurallarına bağlılıkla uyabilsinler.'),
(2004883,68,26,43,12,'Tapınakla ilgili yasa şudur: Dağın tepesinde tapınağı çevreleyen bütün alan çok kutsal olacak. İşte tapınakla ilgili yasa böyle.'),
(2004884,68,26,43,13,'‹‹Arşın ölçüsüyle sunağın ölçüleri şunlardır: -Bu arşın, bir arşına ek olarak bir elin eni kadardır.- Sunağı çevreleyen hendeğin derinliği bir arşın, genişliği bir arşın, çevresindeki kenarlık bir karış. Sunağın yüksekliğiyse şöyle:'),
(2004885,68,26,43,14,'Sunağın yerdeki hendekten alt çıkıntıya kadarki bölümünün yüksekliği iki arşın, genişliği bir arşın, küçük çıkıntıdan büyük çıkıntıya kadarki bölümün yüksekliği dört arşın, genişliği bir arşın.'),
(2004886,68,26,43,15,'Sunağın kurban yakılan üst bölümünün yüksekliği dört arşın; üst bölümden yukarı doğru dört boynuz uzanacak.'),
(2004887,68,26,43,16,'Sunağın üst bölümü kare şeklinde olacak. Uzunluğu on iki arşın, genişliği on iki arşın.'),
(2004888,68,26,43,17,'Üst çıkıntının dört yandan uzunluğu ve genişliği de on dörder arşın. Çevresindeki kenarlık yarım arşın, hendeğin çevresi bir arşın. Sunağın basamakları doğuya bakacak.››'),
(2004889,68,26,43,18,'Adam konuşmasını şöyle sürdürdü: ‹‹İnsanoğlu, Egemen RAB şöyle diyor: ‹Sunak yapılacağı gün, üzerinde yakmalık sunular sunmak ve kan dökmek için kurallar şunlardır:'),
(2004890,68,26,43,19,'Bana hizmet etmek üzere önüme gelen Sadok soyundan Levili kâhinlere günah sunusu olarak bir boğa vereceksin. Egemen RAB böyle diyor.'),
(2004891,68,26,43,20,'Boğanın kanından biraz alıp sunağın dört boynuzuna, çıkıntının dört köşesine ve çevresindeki kenarlığın üzerine süreceksin. Böylece sunağı pak kılıp arındıracaksın.'),
(2004892,68,26,43,21,'Boğayı günah sunusu olarak alacak, tapınağın dışında, tapınak alanında belirlenen yerde yakacaksın.'),
(2004893,68,26,43,22,'‹‹ ‹İkinci gün günah sunusu olarak kusursuz bir teke sunacaksın. Sunağı boğanın kanıyla arındırdığın gibi tekenin kanıyla da arındır.'),
(2004894,68,26,43,23,'Arındırma işlemini bitirince, sürüden kusursuz bir boğayla bir koç sunacaksın.'),
(2004895,68,26,43,24,'Bunları RABbin önüne getireceksin. Kâhinler üzerlerine tuz serpip yakmalık sunu olarak RABbe sunacaklar.'),
(2004896,68,26,43,25,'‹‹ ‹Yedi gün boyunca günah sunusu olarak her gün bir teke sağlayacaksın; kusursuz bir boğayla sürüden bir koç da sağlayacaksın.'),
(2004897,68,26,43,26,'Yedi gün sunağı arındırıp pak kılacaklar. Böylece sunak adanmış olacak.'),
(2004898,68,26,43,27,'Yedi gün bitince, kâhinler sekizinci gün ve daha sonra yakmalık ve esenlik sunularınızı sunağın üzerinde sunacak. O zaman sizi kabul edeceğim. Egemen RAB böyle diyor.› ››'),
(2004899,68,26,44,1,'Bundan sonra adam beni tapınağın doğuya bakan dış kapısına geri getirdi. Kapı kapalıydı.'),
(2004900,68,26,44,2,'RAB bana, ‹‹Bu kapı kapalı kalacak, açılmayacak, buradan kimse girmeyecek!›› dedi, ‹‹İsrailin Tanrısı RAB bu kapıdan girdi, bu yüzden kapalı kalacak.'),
(2004901,68,26,44,3,'Yalnız önder -önder olduğu için- RABbin önünde oturup ekmek yemek üzere eyvandan girebilir, aynı yoldan da çıkabilir.››'),
(2004902,68,26,44,4,'Adam Kuzey Kapısı yolundan tapınağın önüne getirdi beni. Baktım, RABbin görkeminin tapınağı doldurduğunu gördüm. Yüzüstü yere düştüm.'),
(2004903,68,26,44,5,'RAB bana şöyle seslendi: ‹‹İnsanoğlu, RABbin Tapınağının bütün kuralları ve yasalarıyla ilgili söyleyeceklerimi iyi dinle, her şeye iyi bak, kulak ver. Tapınağa kimin girip çıkacağına dikkat et.'),
(2004904,68,26,44,6,'Asi İsrail halkına de ki, ‹Egemen RAB şöyle diyor: Ey İsrail halkı, yaptığınız iğrençliklere bir son verin artık!'),
(2004905,68,26,44,7,'Yüreği ve bedeni sünnet edilmemiş yabancıları tapınağıma aldınız, bana yiyecek olarak yağ, kan sunmakla tapınağımı kirlettiniz. Böylece iğrenç uygulamalarınızla antlaşmamı bozdunuz.'),
(2004906,68,26,44,8,'Kutsal eşyalarıma ilişkin sorumluluğunuzu yerine getirmediniz. Tapınağımda bu eşyalara bakmaları için başkalarını görevlendirdiniz.'),
(2004907,68,26,44,9,'Egemen RAB şöyle diyor: Yüreği ve bedeni sünnet edilmemişlerden, İsrail halkı arasında yaşayan yabancılardan hiçbiri tapınağıma girmeyecek.'),
(2004908,68,26,44,10,'‹‹ ‹İsrail kötü yola saptığı zaman beni bırakan, yoldan sapıp putlarına bağlanan Levililerse günahlarının cezasını çekecekler.'),
(2004909,68,26,44,11,'Ama tapınağımda onlar hizmet edecek: Tapınağın kapılarından sorumlu olacaklar; tapınağın hizmetini yapacak, yakmalık sunu ve kurbanlık hayvanları halk için kesecek, halkın önünde duracak, halka hizmet edecekler.'),
(2004910,68,26,44,12,'Putlarının önünde İsrail halkına hizmet ederek halkı günaha soktular. Bu nedenle ben RAB onları günahları yüzünden cezalandıracağıma ant içtim. Egemen RAB böyle diyor.'),
(2004911,68,26,44,13,'Kâhin olarak hizmet etmek üzere bana yaklaşmayacaklar. Kutsal eşyalarıma, en kutsal sunularıma dokunmayacaklar. İğrenç uygulamalarının utancını yüklenecekler.'),
(2004912,68,26,44,14,'Yine de tapınağın hizmeti ve orada yapılacak bütün işler için onları görevlendireceğim.'),
(2004913,68,26,44,15,'‹‹ ‹Ancak İsrail beni bırakıp kötü yola saptığında tapınağımın hizmetini sadakatle yapan Sadok soyundan Levili kâhinler önümde hizmet etmek üzere bana yaklaşacak. Yağ ve kan sunularını sunmak için önümde onlar duracak. Böyle diyor Egemen RAB.'),
(2004914,68,26,44,16,'Yalnız onlar girecek tapınağıma; önümde hizmet etmek için yalnız onlar soframa yaklaşacak, görev yapacaklar.'),
(2004915,68,26,44,17,'‹‹ ‹Kâhinler iç avlunun kapılarından girecekleri zaman keten giysi giyecek; iç avlunun kapılarında ya da tapınakta hizmet ederken yünlü giysi giymeyecekler.'),
(2004916,68,26,44,18,'Başlarına keten sarık saracak, keten don giyecekler. Kendilerini terletecek bir şey giymeyecekler.'),
(2004917,68,26,44,19,'Dış avluya halkın yanına çıkmadan önce, hizmet ederken giydikleri giysileri çıkarıp kutsal odalara koyacak, başka giysiler giyecekler. Öyle ki, o giysilerin kutsallığını halka geçirmesinler.'),
(2004918,68,26,44,20,'‹‹ ‹Kâhinler başlarını tıraş etmeyecek, saçlarını uzatmayacaklar. Ancak saçlarını kesip düzeltecekler.'),
(2004919,68,26,44,21,'İç avluya gireceği zaman hiçbir kâhin içki içmeyecek.'),
(2004920,68,26,44,22,'Kâhinler dul ya da boşanmış kadınla evlenmeyecek. İsrail soyundan erden bir kızla ya da başka bir kâhinden dul kalmış bir kadınla evlenebilirler.'),
(2004921,68,26,44,23,'Kutsalla bayağı arasındaki ayrımı halkıma onlar öğretecek, kirliyle temizi ayırt etmeyi onlar gösterecekler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004922,68,26,44,24,'‹‹ ‹Davalarda yargıç olarak kâhinler görev yapacak, ilkelerim uyarınca karar verecekler. Bayramlarımla ilgili yasalarıma, kurallarıma uyacak, Şabat günlerimi kutsal tutacaklar.'),
(2004923,68,26,44,25,'‹‹ ‹Kâhin bir ölünün yanına giderek kendini kirletmeyecek; ölü annesi, babası, oğlu, kızı, kardeşi ya da evlenmemiş kızkardeşiyse kendini kirletebilir.'),
(2004924,68,26,44,26,'Arındıktan sonra yedi gün bekleyecek.'),
(2004925,68,26,44,27,'Tapınakta hizmet etmek üzere iç avluya gireceği gün, kendisi için bir günah sunusu sunacak. Egemen RAB böyle diyor.'),
(2004926,68,26,44,28,'‹‹ ‹Kâhinlerin payı vardır, onların mirası benim. İsrailde onlara mülk vermeyeceksiniz. Onların mirası benim.'),
(2004927,68,26,44,29,'Kâhinler tahıl, günah ve suç sunularını yiyecekler. İsrailde RABbe adanan her şey onların olacak.'),
(2004928,68,26,44,30,'İlk ürünlerin en iyileri ve bütün özel armağanlarınız kâhinlerin olacak. Evinize bereket yağsın diye tahılınızın ilkini onlara vereceksiniz.'),
(2004929,68,26,44,31,'Kâhinler ölü bulunmuş ya da yabanıl hayvan tarafından parçalanmış hiçbir kuş ya da hayvan yemeyecek.› ››'),
(2004930,68,26,45,1,'‹‹ ‹Ülkeyi mülk olarak paylaştırdığınız zaman, RABbe ülkeden pay olarak 25 000 arşın uzunlukta, 20 000 arşın genişlikte kutsal bir bölge ayıracaksınız. Bütün bu bölge kutsal olacak.'),
(2004931,68,26,45,2,'Uzunluğu ve genişliği 500 arşınlık bir bölüm kutsal yer için, 50 arşınlık bir yer de çevresindeki alan için ayrılacak.'),
(2004932,68,26,45,3,'Bu bölgeden uzunluğu 25 000 arşınlık, genişliği 10 000 arşınlıkfü bir bölüm ölçeceksiniz. Tapınak, En Kutsal Yer orada olacak.'),
(2004933,68,26,45,4,'Burası tapınakta hizmet etmek üzere RABbe yaklaşan kâhinlere ayrılacak ve ülkenin kutsal payı olacak. Kâhinlerin evleri de tapınak da o kutsal bölgede olacak.'),
(2004934,68,26,45,5,'Tapınakta hizmet eden Levililere miras olarak 25 000 arşın uzunlukta, 10 000 arşınfü genişlikte bir bölge verilecek. Orada, yaşamaları için kendilerine ait kentler olacak. metin ‹‹10 000 arşın››, yaklaşık 5.3 km. olacak››, Masoretik metin ‹‹Mülk olarak yirmi oda alacaklar››.'),
(2004935,68,26,45,6,'‹‹ ‹Kutsal bölgeye düşen payla birlikte kent için uzunluğu 25 000, genişliği 5 000 arşınlık bir pay ayıracaksınız; bu bütün İsrail halkı için olacak.'),
(2004936,68,26,45,7,'‹‹ ‹Kutsal bölgeye düşen pay ile kente düşen payın iki yanındaki topraklar öndere verilecek. Batıdan batıya, doğudan doğuya doğru uzanacak. Batı sınırından doğu sınırına dek uzunluğu bir İsrail oymağına düşen pay kadardır.'),
(2004937,68,26,45,8,'Bu toprak İsrailde önderin payı olacak. Bundan böyle önderlerim halkıma bir daha baskı yapmayacak, ama oymaklarına göre İsrail halkına ülkeyi miras olarak verecekler.'),
(2004938,68,26,45,9,'‹‹ ‹Egemen RAB şöyle diyor: Yeter artık, ey İsrail önderleri! Zorbalığı, baskıyı bırakın. Adil ve doğru olanı yapın. Halkımı kendi topraklarından kovmayın. Egemen RAB böyle diyor.'),
(2004939,68,26,45,10,'Doğru ölçüler kullanın, kullandığınız efa ve bat doğru olsun.'),
(2004940,68,26,45,11,'Efa ile bat aynı ölçüde olsun. Bat homerin onda birine, efa da homerin onda birine eşit olmalı. İkisinin de ölçüsü homere göre olacak.'),
(2004941,68,26,45,12,'Bir şekel yirmi geraya eşit olmalı. Altmış şekelfç de bir minaya eşit olmalı.› ›› şekel, on beş şekel››.'),
(2004942,68,26,45,13,'‹‹ ‹Sunacağınız sunular şunlardır: Her homer buğdaydan efanın altıda biri, her homer arpadan efanın altıda biri kadarını vereceksiniz.'),
(2004943,68,26,45,14,'Bat ölçüsüne göre istenen zeytinyağı miktarı, her kordan batın onda biri kadardır. Bir kor on bat ya da bir homere eşittir.'),
(2004944,68,26,45,15,'İsrailin sulak otlaklarındaki sürüden iki yüz koyundan bir koyun alınacak. Halkın günahlarını bağışlatmak için bu koyunlar yakmalık sunular, tahıl ve esenlik sunuları için kullanılacak. Egemen RAB böyle diyor.'),
(2004945,68,26,45,16,'Ülke halkı bu armağanları İsraildeki öndere verecek.'),
(2004946,68,26,45,17,'İsrailde kutlanan bütün bayramlarda -şenliklerde, Yeni Ay törenlerinde, Şabat günlerinde- tahıl sunularını, yakmalık ve dökmelik sunuları önder sağlayacak. İsrail halkının günahlarını bağışlatmak için yakmalık sunuları, günah, tahıl, esenlik sunularını sağlayacak.'),
(2004947,68,26,45,18,'‹‹ ‹Egemen RAB şöyle diyor: Birinci ayın birinci günü kusursuz bir boğa alacak, tapınağı arındıracaksın.'),
(2004948,68,26,45,19,'Kâhin günah sunusunun kanından alıp tapınağın kapı sövelerine, sunağın üst çıkıntısının dört köşesine, iç avlunun kapı sövelerine sürecek.'),
(2004949,68,26,45,20,'Yanlışlıkla ya da bilgisizlikten günah işleyen biri için ayın yedinci günü aynısını yapacaksın. Böylece tapınağı arındıracaksın.'),
(2004950,68,26,45,21,'‹‹ ‹Birinci ayın on dördüncü günü Fısıh Bayramını yedi gün kutlayacak, mayasız ekmek yiyeceksiniz.'),
(2004951,68,26,45,22,'O gün önder kendisi ve ülke halkı için günah sunusu olarak bir boğa sağlayacak.'),
(2004952,68,26,45,23,'Yedi gün bayram boyunca her gün RABbe yakmalık sunu olarak kusursuz yedi boğayla yedi koç, günah sunusu olarak da bir teke sağlayacak.'),
(2004953,68,26,45,24,'Tahıl sunusu olarak her boğa ve koç için birer efafı tahıl, her efa için bir hin zeytinyağı sağlayacak.'),
(2004954,68,26,45,25,'‹‹ ‹Yedinci ayın on beşinci günü başlayan ve yedi gün süren bayramda önder yakmalık sunuları, günah ve tahıl sunularını, zeytinyağını her gün aynı miktarda sağlayacak.'),
(2004955,68,26,46,1,'‹‹ ‹Egemen RAB şöyle diyor: İç avlunun doğuya bakan kapısı altı çalışma günü kapalı, Şabat Günü ve Yeni Ay Günü ise açık kalacak.'),
(2004956,68,26,46,2,'Önder dışarıdan eyvana girip kapı sövesinin yanında duracak. Kâhinler onun yakmalık ve esenlik sunularını sunacaklar. Önder kapı eşiğinde tapındıktan sonra çıkıp gidecek. Kapı akşama dek açık kalacak.'),
(2004957,68,26,46,3,'Şabat günleri ve Yeni Ay törenlerinde ülke halkı bu kapının girişinde RABbin önünde tapınacak.'),
(2004958,68,26,46,4,'Önder Şabat Günü RABbe sunacağı yakmalık sunu olarak kusursuz altı kuzu, bir koç sunacak.'),
(2004959,68,26,46,5,'Koç için verilecek tahıl sunusu bir efa tahıl olacak, kuzular için verebileceği kadar tahıl sunusu sunabilir. Her efa tahıl için bir hin zeytinyağı verilecek.'),
(2004960,68,26,46,6,'Yeni Ay Günü kusursuz bir boğa, altı kuzu ve bir koç sunacak.'),
(2004961,68,26,46,7,'Boğa ve koç için tahıl sunusu olarak birer efa tahıl sağlayacak; kuzular için istediği kadar tahıl sağlayabilir. Her efa tahıl için bir hin zeytinyağı sağlayacak.'),
(2004962,68,26,46,8,'Önder içeri gireceği zaman eyvandan girecek ve aynı yoldan dışarı çıkacak.'),
(2004963,68,26,46,9,'‹‹ ‹Ülke halkı bayramlarda RABbin önüne geldiğinde, tapınmak için Kuzey Kapısından giren Güney Kapısından çıkacak, Güney Kapısından giren Kuzey Kapısından çıkacak. Hiç kimse girdiği kapıdan çıkmayacak. Herkes girdiği kapının karşısındaki kapıdan çıkacak.'),
(2004964,68,26,46,10,'Önder halkın arasında olacak. Halkla birlikte girecek, halkla birlikte çıkacak.'),
(2004965,68,26,46,11,'‹‹ ‹Bayramlarda ve kutsal günlerde boğa ve koç için tahıl sunusu olarak birer efa tahıl verecek; kuzular için verebileceği kadar tahıl sağlayabilir. Her efa tahıl için bir hin zeytinyağı verecek.'),
(2004966,68,26,46,12,'Önder RABbe gönülden verilen yakmalık sunular ya da esenlik sunuları sunacağı zaman doğuya bakan kapı kendisine açılacak. Yakmalık sunuları ya da esenlik sunularını Şabat Günü sunduğu gibi sunacak. Sonra dışarı çıkacak; o çıktıktan sonra kapı kapanacak.'),
(2004967,68,26,46,13,'‹‹ ‹Her gün, her sabah yakmalık sunu olarak RABbe bir yaşında kusursuz bir kuzu sağlayacaksın.'),
(2004968,68,26,46,14,'Bununla birlikte her sabah tahıl sunusu olarak efanın altıda biri tahıl ve ince unu ıslatmak için bir hinin üçte biri kadar zeytinyağı sağlayacaksın. Bu tahıl sunusunun RABbe sunulması sürekli bir kural olacak.'),
(2004969,68,26,46,15,'Böylece günlük yakmalık sunu olarak her sabah kuzu, tahıl sunusu ve zeytinyağı sunulacak.› ››'),
(2004970,68,26,46,16,'‹‹ ‹Egemen RAB şöyle diyor: Eğer önder oğullarından birine kendi mülkünden armağan ederse, bu mülk torunlarına da geçecek. Miras yoluyla bu onların mülkü olacak.'),
(2004971,68,26,46,17,'Önder görevlilerinden birine kendi mülkünden armağan ederse, görevli toprak parçasını özgürlük yılına dek elinde tutacak. Sonra öndere geri verecek. Önderin mirası ancak oğullarına geçebilir, onların olacak.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2004972,68,26,46,18,'Önder halkı mülkünden kovarak miraslarından etmemeli. Oğullarına ancak kendi mülkünden miras verebilir. Öyle ki, halkımdan hiç kimse mülkünden ayrılıp dağılmasın.› ››'),
(2004973,68,26,46,19,'Bundan sonra adam beni kapı yanındaki girişten kuzeye bakan, kâhinlere ait kutsal odalara getirdi. Bana batıda bir yer gösterdi.'),
(2004974,68,26,46,20,'‹‹Kâhinlerin suç sunusuyla günah sunusunun etini haşlayacakları, tahıl sunusunu pişirecekleri yer burası›› dedi, ‹‹Öyle ki, bunları dış avluya çıkarıp kutsallıklarını halka geçirmesinler.››'),
(2004975,68,26,46,21,'Daha sonra adam beni dış avluya çıkarıp sırayla avlunun dört köşesine götürdü. Avlunun her köşesinde küçük birer avlu olduğunu gördüm.'),
(2004976,68,26,46,22,'Dış avlunun dört köşesinde kırk arşın uzunluğunda, otuz arşın genişliğinde birer kapalı avlu vardı. Köşelerdeki avluların ölçüsü aynıydı.'),
(2004977,68,26,46,23,'Dört avlunun çevresinde de taş duvar vardı; duvarın dibinde yemek pişirmek için yerler yapılmıştı.'),
(2004978,68,26,46,24,'Bana, ‹‹Bunlar tapınakta hizmet edenlerin halkın sunduğu kurban etini pişirecekleri mutfaklar›› dedi.'),
(2004979,68,26,47,1,'Adam beni tapınağın girişine geri getirdi. Doğuya doğru tapınağın kapı eşiğinin altından sular aktığını gördüm. Tapınak doğuya bakıyordu. Sular tapınağın güney yanının altından, sunağın güneyinden aşağıya akıyordu.'),
(2004980,68,26,47,2,'Beni oradan, Kuzey Kapısından çıkarıp dış yoldan doğuya bakan dış kapıya götürdü. Sular güney yönünden akıyordu.'),
(2004981,68,26,47,3,'Adam elinde bir ölçü ipiyle doğuya doğru gitti. Bin arşın ölçtükten sonra beni ayak bileğine dek çıkan sulara getirdi.'),
(2004982,68,26,47,4,'Bin arşın daha ölçtü ve beni dize kadar çıkan sulara getirdi. Bin arşın daha ölçtü, beni bele kadar çıkan sulara getirdi.'),
(2004983,68,26,47,5,'Bin arşın daha ölçtü, içinden geçemediğim bir ırmak oluştu. Sular yükselmişti, içinden yürüyerek karşıya geçilemezdi, yüzülecek kadar derin bir ırmak oluşmuştu.'),
(2004984,68,26,47,6,'Bana, ‹‹İnsanoğlu, bunu gördün mü?›› diye sordu. Daha sonra beni ırmağın kıyısına geri getirdi.'),
(2004985,68,26,47,7,'Oraya varınca, ırmağın her iki kıyısında birçok ağaç gördüm.'),
(2004986,68,26,47,8,'Bana şöyle dedi: ‹‹Bu sular doğu bölgesine doğru akıyor, oradan Arava Vadisine, sonra Lut Gölüne dökülüyor. Göle dökülünce oradaki sular tatlı suya dönüşecek.'),
(2004987,68,26,47,9,'Irmağın aktığı yerlerde her çeşit canlı yaratık kaynaşacak. Çok sayıda balık olacak. Çünkü bu sular oraya akıyor, oradaki tuzlu suyu tatlı suya dönüştürüyor. Irmak aktığı her yere yaşam getirecek.'),
(2004988,68,26,47,10,'Irmak kıyısı boyunca balıkçılar duracak; Eyn-Gediden Eyn- Eglayime dek ağ gerecek yerler olacak. Akdenizdeki gibi çok sayıda balık çeşidi olacak.'),
(2004989,68,26,47,11,'Ama Lut Gölünün çamurlu, bataklık kesimi tatlı suya dönüşmeyecek, tuzla olarak kalacak.'),
(2004990,68,26,47,12,'Irmağın her iki yanında her çeşit meyve ağacı yetişecek. Yaprakları solmayacak, meyveleri tükenmeyecek. Her ay meyve verecekler, çünkü tapınaktan çıkan sular oraya akıyor. Meyveleri yiyecek olarak, yaprakları şifa için kullanılacak.››'),
(2004991,68,26,47,13,'Egemen RAB şöyle diyor: ‹‹Ülkeyi mülk olarak İsrailin on iki oymağına böleceğiniz sınırlar şöyle olacak: Yusufa iki pay düşecek.'),
(2004992,68,26,47,14,'Ülkeyi on iki oymak arasında eşit olarak paylaşacaksınız. Ülkeyi atalarınıza vereceğime ant içtim. Bu ülke size mülk olarak verilecek.'),
(2004993,68,26,47,15,'‹‹Ülkenin sınırı şöyle olacak: Kuzeyde Akdenizden, Hetlon yoluyla Levo-Hamata, Sedata,'),
(2004994,68,26,47,16,'Berotaya ve Şamla Hamanın toprakları arasında bulunan Sivrayime, Havran sınırında Haser-Hattikona kadar uzanacak.'),
(2004995,68,26,47,17,'Sınır denizden Hasar-Enana, Şamın kuzey sınırı boyunca uzanacak, Hama sınırı kuzeyde olacak. Kuzey sınırı bu olacak. ‹‹Levo-Sedata, Hamaya››.'),
(2004996,68,26,47,18,'‹‹Doğuda sınır Havranla Şam arasında Gilatı İsrailden ayıran Şeria Irmağı boyunca Lut Gölüne ve Tamara dek uzanacakfö. Doğu sınırı bu olacak. Masoretik metin ‹‹Lut Gölüne dek ölçeceksiniz››.'),
(2004997,68,26,47,19,'‹‹Güneyde sınır Tamardan Meriva-Kadeş sularına, Mısır Vadisi boyunca Akdenize dek uzanacak. Güney sınırı bu olacak.'),
(2004998,68,26,47,20,'‹‹Batıda Levo-Hamatın karşısındaki noktaya dek Akdeniz sınır oluşturacak. Batı sınırı bu olacak.'),
(2004999,68,26,47,21,'‹‹Bu ülkeyi İsrail oymaklarına göre aranızda paylaşacaksınız.'),
(2005000,68,26,47,22,'Ülkeyi içinizde yaşayan ve içinizdeyken çocukları olan yabancılarla kendiniz arasında mülk olarak bölüşeceksiniz. Onları İsrailde doğan yerliler sayacaksınız. Onların da İsrail oymakları arasında sizin gibi mülkleri olacak.'),
(2005001,68,26,47,23,'Yabancı hangi oymağa yerleşmişse, orada ona düşen payı mülk olarak vereceksiniz.›› Egemen RAB böyle diyor.'),
(2005002,68,26,48,1,'‹‹Oymakların adları şunlardır: Kuzey sınırında Dana bir pay verilecek. Dan sınırı Hetlon yolundan Levo-Hamata uzanacak; Hasar-Enan ve Hamaya yakın Şamın kuzey sınırı doğudan batıya uzanan sınırın bir bölümünü oluşturacak.'),
(2005003,68,26,48,2,'‹‹Aşere bir pay verilecek; sınırı Danın doğudan batıya uzanan sınırına bitişik olacak.'),
(2005004,68,26,48,3,'‹‹Naftaliye bir pay verilecek; sınırı Aşerin doğudan batıya uzanan sınırına bitişik olacak.'),
(2005005,68,26,48,4,'‹‹Manaşşeye bir pay verilecek; sınırı Naftalinin doğudan batıya uzanan sınırına bitişik olacak.'),
(2005006,68,26,48,5,'‹‹Efrayime bir pay verilecek; sınırı Manaşşenin doğudan batıya uzanan sınırına bitişik olacak.'),
(2005007,68,26,48,6,'‹‹Rubene bir pay verilecek; sınırı Efrayimin doğudan batıya uzanan sınırına bitişik olacak.'),
(2005008,68,26,48,7,'‹‹Yahudaya bir pay verilecek; sınırı Rubenin doğudan batıya uzanan sınırına bitişik olacak.'),
(2005009,68,26,48,8,'‹‹Yahudanın doğudan batıya uzanan sınırına bitişik topraklar, RABbe ayıracağınız özel armağan olacak. Genişliği 25 000 arşın, doğudan batıya uzunluğu bir oymağa düşen pay kadar olacak. Tapınak bunun ortasında olacak.'),
(2005010,68,26,48,9,'‹‹RABbe özel olarak sunacağınız payın uzunluğu 25 000 arşın, genişliği 10 000 arşın olacak.'),
(2005011,68,26,48,10,'Bu kâhinler için kutsal pay olacak. Kuzeyde uzunluğu 25 000 arşın, batıda genişliği 10 000 arşın, doğuda genişliği 10 000 arşın, güneyde uzunluğu 25 000 arşın olacak. RABbin Tapınağı bunun ortasında olacak.'),
(2005012,68,26,48,11,'Bu bölge Sadok soyundan gelen kutsanmış kâhinler için olacak. Onlar bana bağlılıkla hizmet ettiler, İsrail halkı yoldan saptığında Levililer de yoldan saptı, ama onlar sapmadı.'),
(2005013,68,26,48,12,'Orası ülkenin kutsal payından özel bir armağan olarak onlara verilecek. Levililerin topraklarına bitişik çok kutsal bir bölge olacak.'),
(2005014,68,26,48,13,'‹‹Levililerin kâhinlerin sınırı yakınında 25 000 arşın uzunlukta, 10 000 arşın genişlikte bir payları olacak. Bu bölgenin uzunluğu 25 000 arşın, genişliği 10 000 arşın olacak.'),
(2005015,68,26,48,14,'Levililer orayı satmayacak, değiş tokuş etmeyecekler. Bu, ülkenin en iyi bölümüdür, başkasının eline geçmemeli. Çünkü orası RABbe adanmıştır.'),
(2005016,68,26,48,15,'‹‹Bölgenin geri kalan 25 000 arşın uzunlukta, 5 000 arşın genişlikteki bölümü halkın yerleşmesi içindir. Orası evlere, otlaklara ayrılacak. Kent bunun ortasında kurulacak.'),
(2005017,68,26,48,16,'Ölçüleri şöyle olacak: Kuzeyde, güneyde, doğuda, batıda 4 500er arşınfş.'),
(2005018,68,26,48,17,'Kent için ayrılan otlak da kuzeyde, güneyde, doğuda, batıda 250şer arşın olacak.'),
(2005019,68,26,48,18,'Kutsal bölgenin sınırında kalan yerin doğusu 10 000 arşın, batısı 10 000 arşın olacak. Kutsal bölgeye bitişik topraklarda yetişen ürün kentte çalışanların olacak.'),
(2005020,68,26,48,19,'İsrailin her oymağından kentte çalışanlar toprağı işleyecekler.'),
(2005021,68,26,48,20,'Bu bölgenin tamamı kare şeklindedir. Her yanı 25 000 arşındır. Özel bir armağan olarak kentin mülküyle birlikte kutsal bölgeye düşen payı ayıracaksınız.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005022,68,26,48,21,'‹‹Kutsal bölgeye düşen pay ile kente düşen payın iki yanındaki topraklar öndere verilecek. Bu topraklar kutsal bölgeye düşen 25 000 arşınlık payın doğusundan ve batısından ülkenin doğu ve batı sınırlarına uzanacak. Oymaklara düşen paylar boyunca uzanan bu iki bölge önderin olacak. Kutsal bölgeye düşen pay ile tapınak bunun ortasında olacak.'),
(2005023,68,26,48,22,'Böylece Levililere düşen pay ile kente düşen pay öndere verilen toprakların ortasında kalacak. Öndere verilecek topraklar Yahudayla Benyamin sınırı arasında kalacak.'),
(2005024,68,26,48,23,'‹‹Geri kalan oymaklara düşen pay şöyle: Benyamine bir pay verilecek; sınırı doğudan batıya uzanacak.'),
(2005025,68,26,48,24,'‹‹Şimona bir pay verilecek; sınırı Benyaminin doğudan batıya uzanan sınırına bitişik olacak.'),
(2005026,68,26,48,25,'‹‹İssakara bir pay verilecek; sınırı Şimonun doğudan batıya uzanan sınırına bitişik olacak.'),
(2005027,68,26,48,26,'‹‹Zevuluna bir pay verilecek; sınırı İssakarın doğudan batıya uzanan sınırına bitişik olacak.'),
(2005028,68,26,48,27,'‹‹Gada bir pay verilecek; sınırı Zevulunun doğudan batıya uzanan sınırına bitişik olacak.'),
(2005029,68,26,48,28,'‹‹Gadın güney sınırı Tamardan güneye, oradan Meriva-Kadeş sularına, oradan da Mısır Vadisi boyunca Akdenize dek uzanacak.'),
(2005030,68,26,48,29,'‹‹Mülk olarak İsrail oymaklarına bölüştüreceğiniz ülke budur. Onlara düşecek paylar bunlardır.›› Böyle diyor Egemen RAB.'),
(2005031,68,26,48,30,'‹‹Kentin çıkış kapıları şunlar olacak: 4 500 arşın uzunluktaki kuzey yanında üç kapı olacak. Kentin kapılarına İsrail oymaklarının adları verilecek. Kuzeyde Ruben Kapısı, Yahuda Kapısı, Levi Kapısı olacak.'),
(2005032,68,26,48,32,'4 500 arşın uzunluktaki doğu yanında üç kapı olacak: Yusuf Kapısı, Benyamin Kapısı, Dan Kapısı.'),
(2005033,68,26,48,33,'4 500 arşın uzunluktaki güney yanında üç kapı olacak: Şimon Kapısı, İssakar Kapısı, Zevulun Kapısı.'),
(2005034,68,26,48,34,'4 500 arşın uzunluktaki batı yanında üç kapı olacak: Gad Kapısı, Aşer Kapısı, Naftali Kapısı.'),
(2005035,68,26,48,35,'‹‹Kentin çevresi 18 000 arşın olacak ve o günden başlayarak kentin adı ‹Yahve şamma› olacak.››'),
(2005036,68,27,1,1,'Yahuda Kralı Yehoyakimin krallığının üçüncü yılında Babil Kralı Nebukadnessar Yeruşalimin üzerine yürüyüp kenti kuşattı.'),
(2005037,68,27,1,2,'Rab, Yahuda Kralı Yehoyakimi ve Tanrının Tapınağındaki bazı eşyaları Nebukadnessarın eline teslim etti. Nebukadnessar bunları Şinar ülkesine götürüp kendi ilahının tapınağının hazinesine yerleştirdi.'),
(2005038,68,27,1,3,'Kral İsrailliler arasından kral soyundan gelme ya da soylu bazı gençlerin seçilip saraya getirilmesi için saray görevlilerinin yöneticisi Aşpenaza buyruk verdi. Bu gençler kusursuz, yakışıklı, her konuda bilge, bilgili, öğrenmeye yetenekli, sarayda görev almaya uygun nitelikte kişiler olmalıydı. Aşpenaz onlara Kildanilerin dilini ve yazısını öğretecekti.'),
(2005039,68,27,1,5,'Kral bu gençler için kendi sofrasından gündelik yiyecek ve şarap ayırdı. Üç yıl eğitildikten sonra gençler kralın önüne çıkarılacaklardı.'),
(2005040,68,27,1,6,'Seçilen gençler arasında Yahudalılardan Daniel, Hananya, Mişael ve Azarya da vardı.'),
(2005041,68,27,1,7,'Saray görevlilerinin yöneticisi onlara yeni adlar koydu. Daniele Belteşassar, Hananyaya Şadrak, Mişaele Meşak, Azaryaya Abed-Nego adını verdi.'),
(2005042,68,27,1,8,'Daniel dinsel açıdan kendini kirletmemek için kralın onlara ayırdığı yemeklerden yemeyi de şaraptan içmeyi de istemedi. Bu yoldan kendini kirletmemek için saray görevlilerinin yöneticisine ricada bulundu.'),
(2005043,68,27,1,9,'Tanrı saray görevlileri yöneticisinin Daniele sevgiyle, sevecenlikle davranmasını sağladı.'),
(2005044,68,27,1,10,'Adam Daniele, ‹‹Yiyecek içecek payınızı ayıran efendimiz kraldan korkarım›› dedi, ‹‹Eğer yüzünüzü yaşıtınız olan öbür gençlerin yüzünden daha solgun görürse, başımı tehlikeye sokmuş olursunuz.››'),
(2005045,68,27,1,11,'Daniel, saray görevlileri yöneticisinin Hananya, Mişael, Azarya ve kendisinin başına koyduğu gözeticiye gidip, ‹‹Lütfen kullarınıza on gün olanak tanıyın›› dedi, ‹‹Bu on gün içinde bize yemek için sebze, içmek için de su verilsin.'),
(2005046,68,27,1,13,'Sonra yüzlerimizi kralın yemeklerini yiyen öbür gençlerin yüzleriyle kıyaslayın ve kullarınıza gördüğünüze göre davranın.››'),
(2005047,68,27,1,14,'Gözetici bu isteği kabul etti ve onlara on gün deneme fırsatı verdi.'),
(2005048,68,27,1,15,'On gün sonra dört genç kralın yemeklerini yiyen öbür gençlerin hepsinden daha sağlıklı, daha iyi beslenmiş görünüyordu.'),
(2005049,68,27,1,16,'Böylece gözetici o günden sonra kralın gençler için ayırdığı yemekle şarabı kaldırdı ve onlara sebze vermeyi sürdürdü.'),
(2005050,68,27,1,17,'Tanrı bu dört gence her konuda bilgi, beceri, bilgelik verdi. Daniel her çeşit görümü ve düşü yorumlayabiliyordu.'),
(2005051,68,27,1,18,'Kralın belirlediği süre tamamlanınca, saray görevlileri yöneticisi gençleri Nebukadnessara götürdü.'),
(2005052,68,27,1,19,'Kral onlarla görüştü; içlerinde Daniel, Hananya, Mişael, Azarya gibisi yoktu. Bu yüzden kralın hizmetine onlar atandı.'),
(2005053,68,27,1,20,'Kral bilgelik ve anlayışla ilgili konularda onları sınadı ve dört genci ülkesindeki bütün sihirbazlardan, falcılardan on kat üstün buldu.'),
(2005054,68,27,1,21,'Kral Koreş''in krallığının birinci yılına dek Daniel sarayda kaldı.'),
(2005055,68,27,2,1,'Krallığının ikinci yılında Nebukadnessar bir düş gördü. Ruhu üzüntüyle sarsıldı, uykusu kaçtı.'),
(2005056,68,27,2,2,'Düşünün ne olduğunu söylesinler diye sihirbazları, falcıları, büyücüleri, yıldızbilimcileri çağırttı. Hepsi gelip kralın önünde durdular.'),
(2005057,68,27,2,3,'Kral, ‹‹Beni üzüntüyle sarsan bir düş gördüm. Ne anlama geldiğini öğrenmek istiyorum›› dedi.'),
(2005058,68,27,2,4,'Yıldızbilimciler Aramice, ‹‹Ey kral, sen çok yaşa!›› dediler, ‹‹Düşünü bu kullarına anlat ki, ne anlama geldiğini söyleyelim.›› yazılmıştır.'),
(2005059,68,27,2,5,'Kral, ‹‹Gördüğüm düşü ve ne anlama geldiğini bana açıklamazsanız, kararım kesin, paramparça edileceksiniz›› diye karşılık verdi, ‹‹Evleriniz de çöplüğe çevrilecek.'),
(2005060,68,27,2,6,'Ama düşü ve ne anlama geldiğini açıklayabilirseniz, sizi büyük armağanlarla ödüllendirip onurlandıracağım. Onun için bana düşü ve ne anlama geldiğini açıklayın.››'),
(2005061,68,27,2,7,'Onlar yine, ‹‹Ey kral, düşü bu kullarına anlat ki, ne anlama geldiğini söyleyelim›› dediler.'),
(2005062,68,27,2,8,'Bunun üzerine kral, ‹‹Kararımın kesin olduğunu bildiğiniz için zaman kazanmak istediğinizi anlıyorum›› dedi,'),
(2005063,68,27,2,9,'‹‹Ama düşün ne olduğunu bana açıklamazsanız, sizin için tek ceza vardır. Durumun değişeceğini umarak bana yalan yanlış şeyler söylemek için aranızda anlaşmışsınız. Şimdi bana düşün ne olduğunu söyleyin ki, ne anlama geldiğini açıklayabileceğinizi anlayayım.››'),
(2005064,68,27,2,10,'Yıldızbilimciler, ‹‹Yeryüzünde senin bu isteğini yerine getirecek tek kişi yoktur›› diye yanıtladılar, ‹‹Kaldı ki, büyük, güçlü hiçbir kral bir sihirbazdan, falcıdan ya da yıldızbilimciden böyle bir şey istememiştir.'),
(2005065,68,27,2,11,'Kralın isteğini yerine getirmek güçtür. İnsanlar arasında yaşamayan ilahlardan başka krala bunu açıklayabilecek kimse yoktur.››'),
(2005066,68,27,2,12,'Buna çok öfkelenen kral, Babildeki bütün bilgelerin öldürülmesini buyurdu.'),
(2005067,68,27,2,13,'Böylece hepsinin öldürülmesi için buyruk çıktı. Danielle arkadaşlarının öldürülmesi için de adamlar gönderildi.'),
(2005068,68,27,2,14,'Daniel Babilin bilgelerini öldürmeye giden kralın muhafız birliği komutanı Aryokla bilgece, akıllıca konuştu.'),
(2005069,68,27,2,15,'Aryoka, ‹‹Kralın buyruğu neden bu denli sert?›› diye sordu. Aryok durumu Daniele anlattı.'),
(2005070,68,27,2,16,'Bunun üzerine Daniel krala gidip düşünün ne anlama geldiğini söyleyebilmesi için zaman istedi.'),
(2005071,68,27,2,17,'Sonra evine dönüp olup bitenleri arkadaşları Hananyaya, Mişaele, Azaryaya anlattı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005072,68,27,2,18,'Göklerin Tanrısına yakarmalarını istedi; öyle ki, Tanrı onlara lütfedip bu gizi açıklasın ve kendisiyle arkadaşları Babilin öbür bilgeleriyle birlikte öldürülmesinler.'),
(2005073,68,27,2,19,'Gece giz bir görümde Daniele açıklandı. Bunun üzerine Daniel Göklerin Tanrısını övdü.'),
(2005074,68,27,2,20,'Şöyle dedi: ‹‹Tanrının adına öncesizlikten sonsuzluğa dek övgüler olsun! 2 Bilgelik ve güç Ona özgüdür.'),
(2005075,68,27,2,21,'Odur zamanları ve mevsimleri değiştiren. 2 Kralları tahttan indirir, tahta çıkarır. 2 Bilgelere bilgelik, 2 Anlayışlılara bilgi verir.'),
(2005076,68,27,2,22,'Derin ve gizli şeyleri ortaya çıkarır, 2 Karanlıkta neler olduğunu bilir, 2 Çevresi ışıkla kuşatılmıştır.'),
(2005077,68,27,2,23,'Ey atalarımın Tanrısı, 2 Sana şükreder, seni överim. 2 Sen ki, bana bilgelik ve güç verdin, 2 Senden istediklerimizi bana bildirdin 2 Ve kralın düşünü bize açıkladın.››'),
(2005078,68,27,2,24,'Daniel, kralın Babilin bilgelerini öldürmeye atadığı Aryoka giderek, ‹‹Babilin bilgelerini yok etme›› dedi, ‹‹Beni krala götür, düşünün ne anlama geldiğini açıklayacağım.››'),
(2005079,68,27,2,25,'Aryok onu hemen krala götürdü ve, ‹‹Sürgündeki Yahudalılar arasında kralın düşünü yorumlayabilecek birini buldum›› dedi.'),
(2005080,68,27,2,26,'Kral, öbür adı Belteşassar olan Daniele, ‹‹Gördüğüm düşü ve ne anlama geldiğini bana söyleyebilir misin?›› diye sordu.'),
(2005081,68,27,2,27,'Daniel şöyle yanıtladı: ‹‹Kralın açıklanmasını istediği gizi ne bir bilge, ne falcı, ne de sihirbaz açıklayabilir.'),
(2005082,68,27,2,28,'Ama gökte gizleri açıklayan bir Tanrı var. Gelecekte neler olacağını Kral Nebukadnessara O bildirmiştir. Yatağında yatarken gördüğün düş ve görümler şunlardır:'),
(2005083,68,27,2,29,'‹‹Sen, ey kral, yatarken gelecekle ilgili düşüncelere daldın, gizleri açan da neler olacağını sana bildirdi.'),
(2005084,68,27,2,30,'Bana gelince, ey kral, öbür insanlardan daha bilge olduğum için değil, düşünün ne anlama geldiğini bilesin, aklından geçenleri anlayasın diye bu giz bana açıklandı.'),
(2005085,68,27,2,31,'‹‹Ey kral, düşünde önünde duran büyük bir heykel gördün. Çok büyük ve olağanüstü parlaktı, görünüşü ürkütücüydü.'),
(2005086,68,27,2,32,'Başı saf altından, göğsüyle kolları gümüşten, karnıyla kalçaları tunçtan,'),
(2005087,68,27,2,33,'bacakları demirden, ayaklarının bir kesimi demirden, bir kesimi kildendi.'),
(2005088,68,27,2,34,'Sen bakıyordun ki, bir taş insan eli değmeden kesilip heykelin demirden, kilden ayaklarına çarparak onları paramparça etti.'),
(2005089,68,27,2,35,'Demir, kil, tunç, gümüş, altın aynı anda parçalandı; yazın harman yerindeki saman çöpleri gibi oldular. Derken bir rüzgar çıktı, hiç iz bırakmadan hepsini alıp götürdü. Heykele çarpan taşsa büyük bir dağ oldu, bütün dünyayı doldurdu.'),
(2005090,68,27,2,36,'‹‹Gördüğün düş buydu. Şimdi de ne anlama geldiğini sana açıklayalım.'),
(2005091,68,27,2,37,'Sen, ey kral, kralların kralısın. Göklerin Tanrısı sana egemenlik, güç, kudret, yücelik verdi.'),
(2005092,68,27,2,38,'İnsanoğullarını, yabanıl hayvanları, gökte uçan kuşları senin eline teslim etti. Seni hepsine egemen kıldı. Altından baş sensin.'),
(2005093,68,27,2,39,'Senden sonra senden daha aşağı durumda başka bir krallık çıkacak. Sonra bütün dünyada egemenlik sürecek tunçtan üçüncü bir krallık çıkacak.'),
(2005094,68,27,2,40,'Dördüncü krallık demir gibi güçlü olacak. Çünkü demir her şeyi kırıp ezer. Demir gibi tümünü kırıp parçalayacak.'),
(2005095,68,27,2,41,'Ayaklarla parmakların bir kesiminin çömlekçi kilinden, bir kesiminin demirden olduğunu gördün; yani bölünmüş bir krallık olacak bu. Öyleyken onda demirin gücü de bulunacak, çünkü demiri kille karışık gördün.'),
(2005096,68,27,2,42,'Ayak parmaklarının bir kesimi demirden, bir kesimi kilden olduğu gibi, krallığın da bir bölümü güçlü, bir bölümü zayıf olacak.'),
(2005097,68,27,2,43,'Demirin kille karışık olduğunu gördüğüne göre halklar evlilik bağıyla birbirleriyle karışacaklar, ama demirin kille karışmadığı gibi onlar da birbirine bağlı kalmayacaklar.'),
(2005098,68,27,2,44,'‹‹Bu krallar döneminde Göklerin Tanrısı hiç yıkılmayacak, başka halkın eline geçmeyecek bir krallık kuracak. Bu krallık önceki krallıkları ezip yok edecek, kendisiyse sonsuza dek sürecek.'),
(2005099,68,27,2,45,'İnsan eli değmeden dağdan kesilip gelen taşın demiri, tuncu, kili, gümüşü, altını parçaladığını gördün. Ulu Tanrı bundan sonra neler olacağını krala açıklamıştır. Düş gerçek, yorumu da güvenilirdir.››'),
(2005100,68,27,2,46,'Bunun üzerine Kral Nebukadnessar Danielin önünde yüzüstü yere kapandı. Ona bir sunu ve buhur sunulmasını buyurdu.'),
(2005101,68,27,2,47,'Daniele, ‹‹Madem bu gizi açıklayabildin, Tanrın gerçekten tanrıların Tanrısı, kralların Efendisi›› dedi, ‹‹Gizleri açan Odur.››'),
(2005102,68,27,2,48,'Sonra Danieli yüksek bir göreve getirdi; ona birçok değerli armağan verdi. Onu Babil İline vali atadı, Babilin bütün bilgelerinin başkanı yaptı.'),
(2005103,68,27,2,49,'Daniel''in isteği üzerine Şadrak''ı, Meşak''ı, Abed-Nego''yu da Babil İli''nde yüksek görevlere atadı. Daniel ise sarayda kaldı.'),
(2005104,68,27,3,1,'Kral Nebukadnessar altın bir heykel yaptı; boyu altmış, eni altı arşındıfç. Onu Babil İlinde, Dura Ovasına dikti.'),
(2005105,68,27,3,2,'Satrapları, kaymakamları, valileri, danışmanları, haznedarları, yargıçları, güvenlik görevlilerini ve illerin bütün öbür yüksek memurlarını diktiği heykeli adama törenine çağırttı.'),
(2005106,68,27,3,3,'Böylece satraplar, kaymakamlar, valiler, danışmanlar, haznedarlar, yargıçlar, güvenlik görevlileri ve illerin bütün öbür yüksek memurları Kral Nebukadnessarın diktiği heykeli adama töreni için toplanarak heykelin önünde durdular.'),
(2005107,68,27,3,4,'Sonra haberci yüksek sesle bağırdı: ‹‹Ey halklar, uluslar, her dilden insanlar, size şöyle yapmanız buyruluyor:'),
(2005108,68,27,3,5,'Boru, ney, lir, kanun, arp, davul ve her çeşit çalgı sesini duyar duymaz yere kapanıp Kral Nebukadnessarın dikmiş olduğu altın heykele tapınacaksınız.'),
(2005109,68,27,3,6,'Her kim yere kapanıp tapınmazsa hemen kızgın fırına atılacaktır.››'),
(2005110,68,27,3,7,'Bu yüzden ne zaman boru, ney, lir, kanun, arp ve her çeşit çalgı sesi duyulsa, bütün halklar, uluslar, her dilden insanlar yere kapanıp Kral Nebukadnessarın diktiği altın heykele tapındılar.'),
(2005111,68,27,3,8,'Bunun üzerine bazı Kildaniler yaklaşıp Yahudileri suçladılar.'),
(2005112,68,27,3,9,'Kral Nebukadnessara, ‹‹Ey kral, sen çok yaşa!›› dediler,'),
(2005113,68,27,3,10,'‹‹Boru, ney, lir, kanun, arp, davul ve her çeşit çalgı sesini duyan herkes yere kapanıp altın heykele tapınacak; kim yere kapanıp tapınmazsa kızgın fırına atılacak diye bir buyruk çıkardın, ey kral.'),
(2005114,68,27,3,12,'Oysa Babil İlinde yüksek görevlere atadığın Şadrak, Meşak, Abed-Nego adında bazı Yahudiler var. Bu adamlar seni saymadılar, ey kral. Senin ilahlarına kulluk etmiyor, diktiğin altın heykele tapınmıyorlar.››'),
(2005115,68,27,3,13,'Büyük öfkeye kapılan Nebukadnessar, Şadrakı, Meşakı, Abed-Negoyu çağırttı. Bu kişiler kralın yanına getirildiler.'),
(2005116,68,27,3,14,'Nebukadnessar, ‹‹Ey Şadrak, Meşak, Abed-Nego, ilahlarıma kulluk etmediğiniz, diktiğim altın heykele tapınmadığınız doğru mu?›› diye sordu,'),
(2005117,68,27,3,15,'‹‹Şimdi boru, ney, lir, kanun, arp, davul ve her çeşit çalgı sesini duyar duymaz yere kapanıp yaptığım heykele tapınmaya hazırsanız ne iyi! Ama ona tapınmazsanız, hemen kızgın fırına atılacaksınız. O zaman bakalım hangi ilah sizi elimden kurtaracak?››'),
(2005118,68,27,3,16,'Şadrak, Meşak, Abed-Nego, ‹‹Bu konuda kendimizi savunma gereğini duymuyoruz›› diye karşılık verdiler,'),
(2005119,68,27,3,17,'‹‹Kızgın fırına atılsak bile, ey kral, kendisine kulluk ettiğimiz Tanrı bizi kızgın fırından kurtarabilir; senin elinden de bizi kurtaracaktır.'),
(2005120,68,27,3,18,'Ama bizi kurtarmasa bile bil ki, ey kral, ilahlarına kulluk etmeyiz, diktiğin altın heykele tapınmayız.››'),
(2005121,68,27,3,19,'Nebukadnessar Şadrak, Meşak, Abed-Negoya çok öfkelendi; onlara karşı tutumu değişti. Fırının her zamankinden yedi kat daha çok ısıtılmasını buyurdu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005122,68,27,3,20,'Sonra ordusundaki bazı güçlü askerlere Şadrakı, Meşakı, Abed-Negoyu bağlayıp kızgın fırına atmalarını buyurdu.'),
(2005123,68,27,3,21,'Böylece bu kişiler, şalvarları, kaftanları, sarıkları ve öbür giysileriyle birlikte bağlanıp kızgın fırına atıldılar.'),
(2005124,68,27,3,22,'Kralın buyruğu çok sıkı, fırın da çok ısıtılmış olduğundan, Şadrakı, Meşakı, Abed-Negoyu götüren adamları ateşin alevleri yakıp öldürdü.'),
(2005125,68,27,3,23,'Üç adamsa -Şadrak, Meşak, Abed-Nego- bağlı olarak kızgın fırına düştüler.'),
(2005126,68,27,3,24,'O zaman Kral Nebukadnessar şaşkınlık içinde birden ayağa kalktı. Danışmanlarına, ‹‹Biz ateşin içine bağlı üç kişi atmadık mı?›› diye sordu. Danışmanlar, ‹‹Kuşkusuz, ey kral›› diye karşılık verdiler.'),
(2005127,68,27,3,25,'Kral, ‹‹Ben dört kişi görüyorum›› dedi, ‹‹Ateşin içinde yürüyorlar, bağlarından çözülmüş, hiçbir zarara uğramamışlar. Dördüncünün görünümü de bir ilahi varlığa benziyor.››'),
(2005128,68,27,3,26,'Sonra kızgın fırının kapısına yaklaşarak, ‹‹Ey Yüce Tanrının kulları Şadrak, Meşak, Abed-Nego, dışarı çıkıp buraya gelin!›› diye seslendi. Bunun üzerine Şadrak, Meşak, Abed-Nego ateşin içinden çıktılar.'),
(2005129,68,27,3,27,'Satraplar, kaymakamlar, valiler, kralın danışmanları onların çevresinde toplandılar. Adamların bedenlerinde ateşin hiçbir etkisi olmadığını gördüler. Başlarındaki tek saç yanmamış, giysileri değişmemiş, ateşin kokusu üzerlerine sinmemişti.'),
(2005130,68,27,3,28,'Bunun üzerine Nebukadnessar, ‹‹Şadrak, Meşak ve Abed-Negonun Tanrısına övgüler olsun!›› dedi, ‹‹Meleğini gönderip kendisine güvenen kullarını kurtardı. Onlar buyruğuma karşı geldiler, kendi Tanrılarından başka bir ilaha kulluk edip tapınmamak için canlarını tehlikeye attılar.'),
(2005131,68,27,3,29,'İşte buyuruyorum: Hangi halktan, ulustan ya da dilden olursa olsun, Şadrak, Meşak ve Abed-Negonun Tanrısından saygısızca söz eden herkes paramparça edilecek, evleri çöplüğe çevrilecek. Çünkü böyle kurtarabilen başka bir tanrı yoktur.››'),
(2005132,68,27,3,30,'Sonra Şadrak''ı, Meşak''ı, Abed-Nego''yu Babil İli''nde daha yüksek görevlere atadı.'),
(2005133,68,27,4,1,'Kral Nebukadnessar dünyadaki bütün halklara, uluslara ve her dilden insanlara şu bildiriyi gönderdi: ‹‹Esenliğiniz bol olsun!'),
(2005134,68,27,4,2,'Yüce Tanrının benim için gerçekleştirdiği belirtileri ve şaşılası işleri size bildirmeyi uygun gördüm.'),
(2005135,68,27,4,3,'‹‹Belirtileri ne büyük! 2 Şaşılası işleri ne yüce! 2 Krallığı ebedi krallıktır, 2 Egemenliği kuşaklar boyu sürecek.'),
(2005136,68,27,4,4,'‹‹Ben, Nebukadnessar, evimde huzur, sarayımda gönenç içindeydim.'),
(2005137,68,27,4,5,'Beni korkutan bir düş gördüm. Yatağımda yatarken düşüncelerimle görümlerim beni ürküttü.'),
(2005138,68,27,4,6,'Düşün ne anlama geldiğini açıklamaları için Babilin bütün bilgelerinin yanıma getirilmesini buyurdum.'),
(2005139,68,27,4,7,'Sihirbazlar, yıldızbilimciler, falcılar yanıma gelince, gördüğüm düşü onlara anlattımsa da ne anlama geldiğini açıklayamadılar.'),
(2005140,68,27,4,8,'Sonunda ilahımın adından gelen Belteşassar adıyla çağrılan ve kendisinde kutsal ilahların ruhu bulunan Daniel yanıma geldi. Gördüğüm düşü ona anlattım.'),
(2005141,68,27,4,9,'‹‹Ona şöyle dedim: Ey sihirbazların başkanı Belteşassar, sende kutsal ilahların ruhu olduğunu, her gizi açıklayabileceğini biliyorum. İşte gördüğüm düş: Ne anlama geldiğini bana açıkla.'),
(2005142,68,27,4,10,'Yatarken gördüğüm görümler şunlar: Dünyanın ortasında çok yüksek bir ağaç gördüm.'),
(2005143,68,27,4,11,'Ağaç büyüdü, güçlendi, boyu göklere erişti. Dünyanın dört bucağından görülüyordu.'),
(2005144,68,27,4,12,'Yaprakları güzeldi, herkese yetecek kadar bol meyvesi vardı. Yabanıl hayvanlar gölgesinde barınıyor, gökte uçan kuşlar dallarına tünüyordu. Her canlı ondan besleniyordu.'),
(2005145,68,27,4,13,'‹‹Yatağımda yatarken gördüğüm görümlerde gökten inen bir gözcü, kutsal bir varlık gördüm.'),
(2005146,68,27,4,14,'Yüksek sesle, ‹Ağacı ve dallarını kesin, yapraklarını yolun, meyvesini atın› diye bağırdı, ‹Altında barınan hayvanlarla dallarına tüneyen kuşlar kaçsın.'),
(2005147,68,27,4,15,'Ama köklerin bulunduğu kütüğü demirle, tunçla çevreleyip yerde, otların içinde bırakın. ‹‹ ‹Göğün çiyiyle ıslansın, hayvanlarla birlikte yerdeki otlardan pay alsın.'),
(2005148,68,27,4,16,'Ondaki insan yüreği değiştirilsin, yerine hayvan yüreği verilsin. Üzerinden yedi vakit geçsin.'),
(2005149,68,27,4,17,'Bu yargıyı gözcüler, kararı kutsallar verdi. Öyle ki, her canlı Yüce Olanın insan krallıkları üzerinde egemenlik sürdüğünü ve onları dilediği kişiye, en hor görülen birine bile verebileceğini bilsin.›'),
(2005150,68,27,4,18,'‹‹İşte ben Kral Nebukadnessarın gördüğü düş! Şimdi, ey Belteşassar, bunun ne anlama geldiğini söyle. Çünkü krallığımdaki bilgelerin hiçbiri bu düşün ne anlama geldiğini bana açıklayamadı. Ama sen açıklayabilirsin, çünkü kutsal ilahların ruhu var sende.››'),
(2005151,68,27,4,19,'O zaman öbür adı Belteşassar olan Daniel bir süre şaşkın şaşkın durdu, düşünceleri onu ürküttü. Bunun üzerine kral, ‹‹Ey Belteşassar, bu düş de yorumu da seni ürkütmesin›› dedi. Belteşassar, ‹‹Ey efendim, keşke bu düş senden nefret edenlerin, yorumu da düşmanlarının başına gelseydi!›› diye karşılık verdi,'),
(2005152,68,27,4,20,'‹‹Büyüyen, güçlenen, boyu göklere erişen, dünyadaki herkesçe görülebilen bir ağaç gördün.'),
(2005153,68,27,4,21,'Yaprakları güzeldi, meyvesi herkese yetecek kadar boldu. Yabanıl hayvanlar altında barınır, gökte uçan kuşlar dallarına tünerdi.'),
(2005154,68,27,4,22,'Ey kral, o ağaç sensin! Sen büyüdün, güçlendin. Büyüklüğün giderek göklere erişti, egemenliğin dünyanın dört bucağına yayıldı.'),
(2005155,68,27,4,23,'‹‹Sen, ey kral, bir gözcünün, kutsal bir varlığın gökten indiğini gördün. ‹Ağacı kesip yok edin, ama köklerin bulunduğu kütüğü demirle, tunçla çevreleyip yerde, otların içinde bırakın. Göğün çiyiyle ıslansın; üzerinden yedi vakit geçinceye dek yabanıl hayvanlarla birlikte pay alsın› diyordu.'),
(2005156,68,27,4,24,'‹‹Ey efendim kral, düşün anlamı ve Yüce Olanın senin başına getireceği yargı şudur:'),
(2005157,68,27,4,25,'İnsanlar arasından kovulacak, yabanıl hayvanlarla yaşayacaksın; öküz gibi otla beslenecek, göğün çiyiyle ıslanacaksın. Yüce Olanın insan krallıkları üzerinde egemenlik sürdüğünü ve krallığı dilediği kişiye verdiğini anlayıncaya dek yedi vakit geçecek.'),
(2005158,68,27,4,26,'Köklerin bulunduğu kütüğün bırakılması için buyruk verildi. Bunun anlamı şu: Sen göklerin egemenlik sürdüğünü anlayınca krallığın sana geri verilecek.'),
(2005159,68,27,4,27,'Bu yüzden, ey kral, öğüdümü benimse: Doğru olanı yaparak günahından, düşkünlere iyilik ederek suçlarından vazgeç. Olur ya, gönencin uzun sürer.››'),
(2005160,68,27,4,28,'Bunların hepsi Kral Nebukadnessarın başına geldi.'),
(2005161,68,27,4,29,'On iki ay sonra kral Babil Sarayının damında geziniyordu.'),
(2005162,68,27,4,30,'Kral, ‹‹İşte onurum ve yüceliğim için üstün gücümle krallığımın başkenti olarak kurduğum büyük Babil!›› dedi.'),
(2005163,68,27,4,31,'Daha sözünü bitirmeden gökten bir ses duyuldu: ‹‹Ey Kral Nebukadnessar, krallık senden alındı.'),
(2005164,68,27,4,32,'İnsanlar arasından kovulacak, yabanıl hayvanlarla yaşayacaksın. Öküz gibi otla besleneceksin. Yüce Olanın insan krallıkları üzerinde egemenlik sürdüğünü ve krallığı dilediği kişiye verdiğini anlayıncaya dek yedi vakit geçecek.››'),
(2005165,68,27,4,33,'Nebukadnessara ilişkin bu söz hemen yerine geldi. İnsanlar arasından kovuldu. Öküz gibi otla beslendi. Bedeni göğün çiyiyle ıslandı. Saçı kartal tüyü, tırnakları kuş pençesi gibi uzadı.'),
(2005166,68,27,4,34,'Belirlenen sürenin sonunda ben Nebukadnessar gözlerimi göğe kaldırdım ve kendime geldim. Yüce Olanı övdüm. Sonsuza dek Diri Olanı onurlandırıp yücelttim. Onun egemenliği ebedi egemenliktir, 2 Krallığı kuşaklar boyu sürecek.'),
(2005167,68,27,4,35,'Dünyada yaşayanlar bir hiç sayılır. 2 O gökteki güçlere de dünyada yaşayanlara da 2 Dilediğini yapar. 2 Onun elini durduracak, 2 Ona, ‹‹Ne yapıyorsun?›› diyecek kimse yoktur.'),
(2005168,68,27,4,36,'O anda aklım başıma geldi. Krallığımın yüceliği için onurum ve görkemim bana geri verildi. Danışmanlarımla soylu adamlarım beni aradılar. Krallığıma kavuştum, bana daha büyük yücelik verildi.'),
(2005169,68,27,4,37,'Ben Nebukadnessar Göklerin Kralı''na şükrederim. O''nu över, yüceltirim. Çünkü bütün yaptıkları gerçek, yolları doğrudur; kendini beğenmişleri alçaltmaya gücü yeter.'),
(2005170,68,27,5,1,'Kral Belşassar soylu adamlarından bin kişiye büyük bir şölen verdi, onlarla şarap içti.'),
(2005171,68,27,5,2,'Şarabını keyifle içerken, atası Nebukadnessarın Yeruşalimdeki tapınaktan çıkarıp getirdiği altın ve gümüş kapların getirilmesini buyurdu. Öyle ki, kendisi, karıları, cariyeleri, soylu adamları onlarla içsinler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005172,68,27,5,3,'Böylece Tanrının Yeruşalimdeki tapınağından alınan altın kaplar getirildi; kral, karıları, cariyeleri, soylu adamları onlarla içtiler.'),
(2005173,68,27,5,4,'Şaraplarını içerken altından, gümüşten, tunçtan, demirden, ağaçtan, taştan ilahları övdüler.'),
(2005174,68,27,5,5,'Ansızın bir insan elinin parmakları belirdi, kandilliğin yanındaki saray duvarının sıvası üzerine yazmaya başladı. Kral yazan eli gördü,'),
(2005175,68,27,5,6,'aklından geçenler onu ürküttü, benzi soldu; eli ayağı tutmaz oldu, dizlerinin bağı çözüldü.'),
(2005176,68,27,5,7,'Yüksek sesle Babilin bilgelerini - falcılarla yıldızbilimcileri - çağırttı. Onlara, ‹‹Bu yazıyı kim okuyup ne anlama geldiğini bana açıklarsa, kendisine mor giysi giydirilip boynuna altın zincir takılacak ve ülkede üçüncü önder olacak›› dedi.'),
(2005177,68,27,5,8,'Kralın bütün bilgeleri geldiyse de yazıyı kimse okuyamadı, ne anlama geldiğini de açıklayamadı.'),
(2005178,68,27,5,9,'Bu yüzden Kral Belşassar daha da korktu, benzi büsbütün soldu. Soylu adamlarıysa şaşkındı.'),
(2005179,68,27,5,10,'Kralla soyluların seslerini duyan kraliçe şölen salonuna geldi. ‹‹Çok yaşa, ey kral!›› dedi, ‹‹Aklından geçenler seni ürkütmesin, benzin solmasın!'),
(2005180,68,27,5,11,'Ülkende kendisinde kutsal ilahların ruhu bulunan biri var. Atan Kral Nebukadnessarın döneminde kavrayışa, sağduyuya, ilahlara özgü bilgeliğe sahip olmakla tanınırdı. Atan Kral Nebukadnessar onu sihirbazların, yıldızbilimcilerin, falcıların başkanlığına atadı.'),
(2005181,68,27,5,12,'Kralın Belteşassar diye çağırdığı Daniel olağanüstü bir ruha, bilgiye, sağduyuya sahiptir. Üstelik düşleri yorumlama, bilmeceleri çözme, gizemleri açıklama yeteneği de vardır. Danieli çağırt, yazının ne anlama geldiğini o sana söyleyecektir.››'),
(2005182,68,27,5,13,'Böylece Danieli kralın önüne getirdiler. Kral, ‹‹Kral atamın Yahudadan getirdiği, Yahuda sürgünlerinden Daniel sen misin?›› diye sordu,'),
(2005183,68,27,5,14,'‹‹Sende ilahların ruhu bulunduğunu, kavrayış, sağduyu ve olağanüstü bilgelikle donanmış olduğunu duydum.'),
(2005184,68,27,5,15,'Bu yazıyı okuyup ne anlama geldiğini söylemeleri için bilgelerle falcıları çağırttım. Ama ne anlama geldiğini açıklayamadılar.'),
(2005185,68,27,5,16,'Senin yorum yapabildiğini, gizemleri açıklayabildiğini duydum. Bu yazıyı okur, ne anlama geldiğini açıklayabilirsen, sana mor giysi giydirilip boynuna altın zincir takılacak; ülkede üçüncü önder olacaksın.››'),
(2005186,68,27,5,17,'Daniel, ‹‹Armağanların senin olsun, ödüllerini de bir başkasına ver›› diye karşılık verdi, ‹‹Ama ben yine de yazıyı okuyup ne anlama geldiğini sana açıklayacağım.'),
(2005187,68,27,5,18,'‹‹Ey kral, Yüce Tanrı atan Nebukadnessara krallığı, büyüklüğü, yüceliği, görkemi verdi.'),
(2005188,68,27,5,19,'Tanrının sağladığı büyüklük yüzünden bütün halklar, uluslar, her dilden insan ondan korkup titredi. Dilediğini öldürür, dilediğini yaşatırdı; dilediğini yüceltir, dilediğini alçaltırdı.'),
(2005189,68,27,5,20,'Ne var ki, gurura kapılıp saygısızlıkta direnince krallık tahtından indirildi, yüceliği kendisinden alındı.'),
(2005190,68,27,5,21,'İnsanlar arasından kovuldu ve ona hayvan yüreği verildi. Yüce Tanrının insanların krallığı üzerinde egemenlik sürdüğünü, onu dilediği kişiye verdiğini anlayıncaya dek yaban eşekleri arasında yaşadı, öküz gibi otla beslendi, bedeni göğün çiyiyle ıslandı.'),
(2005191,68,27,5,22,'‹‹Ama ey sen, onun torunu Belşassar, bunların hepsini bildiğin halde alçakgönüllülüğü benimsemedin.'),
(2005192,68,27,5,23,'Bunun yerine göğün Rabbine karşı kendini yükselttin. Onun tapınağından aldıkları kapları sana getirdiler. Sen, karıların, cariyelerin, soylu adamların onlarla şarap içtiniz. Görmeyen, duymayan, anlamayan altından, gümüşten, tunçtan, demirden, ağaçtan, taştan ilahları övdün. Soluğunu elinde tutan, bütün yollarını gözeten Tanrıyı ise yüceltmedin.'),
(2005193,68,27,5,24,'Bu yüzden Tanrı o yazıyı yazan eli gönderdi.'),
(2005194,68,27,5,25,'‹‹Yazılan yazı şudur: MENE, MENE, TEKEL ve PARSİN.'),
(2005195,68,27,5,26,'‹‹Bu sözcüklerin anlamı şudur: MENE: Tanrı senin krallığının günlerini saydı ve ona son verdi.'),
(2005196,68,27,5,27,'TEKEL: Terazide tartıldın ve eksik bulundun.'),
(2005197,68,27,5,28,'PERES: Krallığın ikiye bölünerek Medlerle Perslere verildi.›› ‹‹Persler›› sözcüğünü de çağrıştırır. Peres ‹‹Parsin››in tekilidir.'),
(2005198,68,27,5,29,'Belşassarın buyruğu üzerine Daniele mor giysi giydirilip boynuna altın zincir takıldı ve ülkede üçüncü önder ilan edildi.'),
(2005199,68,27,5,30,'Kildan Kralı Belşassar o gece öldürüldü.'),
(2005200,68,27,5,31,'Altmış iki yaşında olan Medli Darius krallığı eline geçirdi.'),
(2005201,68,27,6,1,'Darius bütün ülkeyi yönetecek yüz yirmi satrap atamayı uygun gördü.'),
(2005202,68,27,6,2,'Bunların başına da biri Daniel olmak üzere üç bakan atadı. Krala zarar gelmemesi için bakanlar satraplardan hesap soracaklardı.'),
(2005203,68,27,6,3,'Kendisinde bulunan olağanüstü ruh sayesinde Daniel öbür bakanlarla satraplardan üstün olduğundan, kral onu bütün ülkenin başına atamayı tasarlıyordu.'),
(2005204,68,27,6,4,'Bunun üzerine öbür bakanlarla satraplar Danieli ülke yönetimi konusunda suçlamak için fırsat kollamaya başladılar. Ancak ne suçlanacak bir yanını, ne de bir yanlışını buldular. Çünkü Daniel güvenilir biriydi. Kendisinde hiçbir eksiklik ya da yanlışlık bulamadılar.'),
(2005205,68,27,6,5,'Sonunda, ‹‹Danieli Tanrısının Yasasıyla ilgili bir konuda suçlayamazsak, bir suçlama nedeni bulamayacağız›› dediler.'),
(2005206,68,27,6,6,'Bunun üzerine bakanlarla satraplar hep birlikte krala gidip, ‹‹Ey Kral Darius, çok yaşa!›› dediler,'),
(2005207,68,27,6,7,'‹‹Ülkenin bütün bakanları, kaymakamları, satrapları, danışmanları, valileri olarak kralın zorlu bir yasa çıkarması üzerinde anlaştık. Ey kral, kim otuz gün içinde senden başka bir insana ya da ilaha dua ederse, aslan çukuruna atılsın.'),
(2005208,68,27,6,8,'Şimdi, ey kral, yasağı koy; Medlerle Perslerin değişmez yasası uyarınca yazıyı imzala ki değiştirilemesin.››'),
(2005209,68,27,6,9,'Böylece Kral Darius yasağı içeren yasayı imzaladı.'),
(2005210,68,27,6,10,'Daniel yasanın imzalandığını öğrenince evine gitti. Yukarı odasının Yeruşalim yönüne bakan pencereleri açıktı. Daha önce yaptığı gibi her gün üç kez diz çöküp dua etti, Tanrısına övgüler sundu.'),
(2005211,68,27,6,11,'Ona tuzak kuran adamlar hep birlikte oraya gittiklerinde, onu Tanrısına dua edip yalvarırken gördüler.'),
(2005212,68,27,6,12,'Bunun üzerine krala gidip çıkardığı yasayla ilgili şunları söylediler: ‹‹Ey kral, kim otuz gün içinde senden başka bir insana ya da ilaha dua ederse, aslan çukuruna atılsın diye yasa imzalamadın mı?›› Kral, ‹‹Medlerle Perslerin değişmez yasası uyarınca çıkardığım yasa geçerlidir›› diye karşılık verdi.'),
(2005213,68,27,6,13,'Bunun üzerine, ‹‹Ey kral, Yahuda sürgünlerinden olan Daniel seni de imzaladığın yasayı da saymıyor; günde üç kez dua ediyor›› dediler.'),
(2005214,68,27,6,14,'Bunu duyan kral çok üzüldü, Danieli kurtarmayı kafasına koydu. Onu kurtarmak için güneş batıncaya dek uğraştı.'),
(2005215,68,27,6,15,'O zaman adamlar toplu halde krala gidip, ‹‹Ey kral, Medlerle Perslerin yasası uyarınca, kralın koyduğu yasanın ya da yasağın değiştirilemeyeceğini bilmelisin›› dediler.'),
(2005216,68,27,6,16,'Bunun üzerine kral Danieli getirip aslan çukuruna atmalarını buyurdu. Daniele de, ‹‹Kendisine sürekli kulluk ettiğin Tanrın seni kurtarsın!›› dedi.'),
(2005217,68,27,6,17,'Bir taş getirip çukurun ağzına koydular. Danielle ilgili hiçbir şey değiştirilmesin diye kral hem kendi mühür yüzüğüyle, hem soyluların mühür yüzükleriyle taşı mühürledi.'),
(2005218,68,27,6,18,'Sonra sarayına döndü; geceyi yemek yemeden, eğlenmeden geçirdi; uykusu kaçtı.'),
(2005219,68,27,6,19,'Şafak sökerken kalkıp acele aslan çukuruna gitti.'),
(2005220,68,27,6,20,'Çukura yaklaşınca üzgün bir sesle, ‹‹Ey yaşayan Tanrının kulu Daniel, kendisine sürekli kulluk ettiğin Tanrın seni aslanlardan kurtarabildi mi?›› diye haykırdı.'),
(2005221,68,27,6,21,'Daniel, ‹‹Ey kral, sen çok yaşa!›› diye yanıtladı,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005222,68,27,6,22,'‹‹Tanrım meleğini gönderip aslanların ağzını kapadı. Beni incitmediler. Çünkü Tanrının önünde suçsuz bulundum. Sana karşı da, ey kral, hiçbir yanlışlık yapmadım.››'),
(2005223,68,27,6,23,'Kral buna çok sevindi, Danieli çukurdan çıkarmalarını buyurdu. Daniel çukurdan çıkarıldı. Bedeninde hiçbir yara izi bulunmadı. Çünkü Tanrısına güvenmişti.'),
(2005224,68,27,6,24,'Kralın buyruğu uyarınca, Danieli haksız yere suçlayan adamları, karılarıyla, çocuklarıyla birlikte getirip aslan çukuruna attılar. Daha çukurun dibine varmadan aslanlar onları kapıp kemiklerini kırdılar.'),
(2005225,68,27,6,25,'Kral Darius dünyada yaşayan bütün halklara, uluslara ve her dilden insanlara şöyle yazdı: ‹‹Esenliğiniz bol olsun!'),
(2005226,68,27,6,26,'Krallığımda yaşayan herkesin Danielin Tanrısından korkup titremesini buyuruyorum. 2 O yaşayan Tanrıdır, 2 Sonsuza dek var olacak. 2 Krallığı yıkılmayacak, 2 Egemenliği son bulmayacak.'),
(2005227,68,27,6,27,'O kurtarır, O yaşatır, 2 Gökte de yerde de 2 Belirtiler, şaşılası işler yapar. 2 Danieli aslanların pençesinden kurtaran Odur.››'),
(2005228,68,27,6,28,'Böylece Darius''un ve Persli Koreş''in krallığı döneminde Daniel''in işleri iyi gitti.'),
(2005229,68,27,7,1,'Babil Kralı Belşassarın krallığının birinci yılında, Daniel yatağında yatarken bir düş ve görümler gördü. Sonra düşünün özetini yazdı;'),
(2005230,68,27,7,2,'şöyle dedi: ‹‹Gece bir görümde göğün dört rüzgarının büyük denize saldırdığını gördüm.'),
(2005231,68,27,7,3,'Denizden birbirinden farklı dört büyük yaratık çıktı.'),
(2005232,68,27,7,4,'‹‹Birinci yaratık aslana benziyordu, kartal kanatları vardı. Ben bakarken kanatları koparıldı, yaratık yerden kaldırıldı, insan gibi ayakları üzerine durduruldu. Ona bir insan yüreği verildi.'),
(2005233,68,27,7,5,'‹‹İkinci yaratık ayıya benziyordu. Bir yanı üzerinde doğrulmuştu. Ağzında, dişleri arasında üç kaburga kemiği vardı. Ona, ‹Haydi kalk, yiyebildiğin kadar et ye!› dediler.'),
(2005234,68,27,7,6,'‹‹Sonra baktım, parsa benzer bir başka yaratık gördüm. Sırtında dört kuş kanadı vardı. Bu yaratığın dört başı vardı ve ona egemenlik verilmişti.'),
(2005235,68,27,7,7,'‹‹Bundan sonraki gece görümlerimde korkunç, ürkütücü, çok güçlü dördüncü bir yaratık gördüm. Büyük demir dişleri vardı; yiyip parçalıyor, artakalanı ayakları altında çiğniyordu. Kendisinden önceki yaratıklara benzemiyordu. On boynuzu vardı.'),
(2005236,68,27,7,8,'‹‹Ben gözümü dikmiş boynuzlara bakarken, onların arasından daha küçük başka bir boynuz çıktı. İlk boynuzlardan üçü onun önünde söküldü. Bu boynuzun insan gözü gibi gözleri, böbürlenen bir ağzı vardı.'),
(2005237,68,27,7,9,'‹‹Ben bakarken 2 Tahtlar kuruldu, 2 Eskiden beri var Olan yerine oturdu. 2 Giysileri kar gibi beyaz, 2 Başındaki saçlar yün gibi apaktı. 2 Tahtı alev alev, 2 Tekerlekleri kızgın ateş gibiydi.'),
(2005238,68,27,7,10,'Önünden ateşten bir ırmak çıkıp akıyordu. 2 Binlerce binler 2 Ona hizmet ediyordu; 2 On binlerce on binler 2 Önünde duruyordu. 2 Mahkeme kuruldu, 2 Kitaplar açıldı.'),
(2005239,68,27,7,11,'‹‹Boynuzun söylediği övüngen sözleri duyunca baktım, yaratık gözümün önünde öldürüldü, bedeni kızgın ateşe atıldı, yok oldu.'),
(2005240,68,27,7,12,'Öbür yaratıklara gelince, egemenlik onlardan alınmış, ancak belirli bir süre için yaşamalarına izin verilmişti.'),
(2005241,68,27,7,13,'‹‹Gece görümlerimde insanoğluna benzer birinin göğün bulutlarıyla geldiğini gördüm. Eskiden beri var Olanın yanına doğru ilerledi, Onun önüne getirildi.'),
(2005242,68,27,7,14,'Ona egemenlik, yücelik ve krallık verildi. Bütün halklar, uluslar ve her dilden insan ona tapındı. Egemenliği hiç bitmeyecek sonsuz bir egemenlik, krallığı hiç yıkılmayacak bir krallıktır.››'),
(2005243,68,27,7,15,'‹‹Ben Daniele gelince, ruhum üzüntüyle sarsıldı, gördüğüm görümler beni ürküttü.'),
(2005244,68,27,7,16,'Orada duranlardan birine yaklaştım, bütün bunların gerçek anlamını açıklamasını istedim. ‹‹O da bana bunların ne anlama geldiğini açıkladı:'),
(2005245,68,27,7,17,'‹Bu dört büyük yaratık yeryüzünde ortaya çıkacak dört kraldır.'),
(2005246,68,27,7,18,'Ama Yüceler Yücesinin kutsalları krallığı alacak, sonsuza dek ellerinde tutacaklar. Evet, sonsuzlara dek.›'),
(2005247,68,27,7,19,'‹‹Bundan sonra öbürlerinden farklı, çok korkunç, demirden dişleri, tunçtan tırnakları olan, yiyip parçalayan, artakalanı ayakları altında çiğneyen dördüncü yaratığın ne anlama geldiğini öğrenmek istedim.'),
(2005248,68,27,7,20,'Bunun yanısıra başındaki on boynuzdan sonra çıkan öbür boynuzun ne olduğunu da öğrenmek istedim. Bu boynuzun önünden üç boynuz düşmüştü, sanki ötekilerden daha iriceydi. Gözleri ve böbürlenen bir ağzı vardı.'),
(2005249,68,27,7,21,'Ben baktığım sırada bu boynuz kutsallarla savaşıyor ve onları yeniyordu.'),
(2005250,68,27,7,22,'Eskiden beri var Olan -Yüceler Yücesi- gelip kutsallarının lehine yargı verene dek bu böyle sürdü. Kutsalların krallığı alma zamanı gelmişti.'),
(2005251,68,27,7,23,'‹‹Bana şu açıklamayı yaptı: ‹Dördüncü yaratık yeryüzünde ortaya çıkacak dördüncü krallıktır. Bütün öbür krallıklardan farklı olacak, bütün dünyayı yiyip bitirecek, çiğneyip parçalayacak.'),
(2005252,68,27,7,24,'On boynuz bu krallıktan çıkacak on kraldır. Bunlardan sonra öncekilerden farklı bir başka kral ortaya çıkıp üç kralı tahtlarından indirecek.'),
(2005253,68,27,7,25,'Yüceler Yücesini kötüleyen sözler söyleyecek, Onun kutsallarına baskı yapacak. Belirlenen zamanları, yasaları değiştirmeyi amaçlayacak. Kutsallar üç buçuk yıl için eline teslim edilecekler. yarım vakte kadar››.'),
(2005254,68,27,7,26,'‹‹ ‹Ama mahkeme kurulacak, onun egemenliğine son verilecek, büsbütün yok edilecek.'),
(2005255,68,27,7,27,'Göklerin altındaki krallıklara özgü krallık, egemenlik ve büyüklük kutsallara, Yüceler Yücesinin halkına verilecek. Bu halkın krallığı sonsuza dek sürecek, bütün uluslar ona kulluk edip sözünü dinleyecek.›'),
(2005256,68,27,7,28,'‹‹İşte olayın gelişimi burada bitiyor. Ben Daniel''e gelince, düşüncelerim beni çok ürküttü, benzim soldu. Ama bu olayı içimde sakladım.››'),
(2005257,68,27,8,1,'Kral Belşassarın krallığının üçüncü yılında, ben Daniel daha önce gördüğüm görümden başka bir görüm gördüm.'),
(2005258,68,27,8,2,'Görümde kendimi Elam İlindeki Sus Kalesinde, Ulay Kanalının yanında gördüm.'),
(2005259,68,27,8,3,'Gözlerimi kaldırıp bakınca kanal kıyısında duran bir koç gördüm; iki uzun boynuzu vardı. Boynuzlardan daha geç çıkanı öbüründen daha uzundu.'),
(2005260,68,27,8,4,'Koçun batıya, kuzeye, güneye doğru boynuz attığını gördüm. Hiçbir hayvan ona karşı koyamıyor, kimse onun elinden kurtaramıyordu. Koç dilediği gibi davrandı ve gitgide güçlendi.'),
(2005261,68,27,8,5,'Ben bu olayı düşünürken, batıdan ansızın gözleri arasında çarpıcı bir boynuzu olan bir teke geldi. Yere basmadan bütün dünyayı aştı.'),
(2005262,68,27,8,6,'Güç ve öfkeyle, kanalın yanında durduğunu gördüğüm iki boynuzlu koça doğru koştu.'),
(2005263,68,27,8,7,'Öfkeyle saldırdığını, koça vurup boynuzlarını kırdığını gördüm. Koçun tekeye karşı duracak gücü yoktu; teke koçu yere vurup çiğnedi. Koçu onun elinden kurtaracak kimse yoktu.'),
(2005264,68,27,8,8,'Teke çok güçlendi, ama en güçlü olduğu sırada büyük boynuzu kırıldı. Kırılan boynuzun yerine, göğün dört rüzgarına doğru çarpıcı dört boynuz çıktı.'),
(2005265,68,27,8,9,'Bu boynuzların birinden başka bir küçük boynuz çıktı; güneye, doğuya ve Güzel Ülkeyefı doğru yayılarak çok güçlendi.'),
(2005266,68,27,8,10,'Göklerin ordusuna erişinceye dek büyüdü. Gökteki ordudan ve yıldızlardan bazılarını yeryüzüne düşürdü, ayakları altına alıp çiğnedi.'),
(2005267,68,27,8,11,'Kendisini Gök Ordusunun Önderine kadar yükseltti. Tanrıya sunulan günlük sunu kaldırıldı, tapınak terk edildi.'),
(2005268,68,27,8,12,'Başkaldırı yüzünden günlük sunuya karşı çıkıldı. Gerçek ayak altında çiğnendi. Küçük boynuz yaptığı her şeyde başarılı oldu.'),
(2005269,68,27,8,13,'Sonra kutsal bir varlığın konuştuğunu duydum. Başka kutsal bir varlık ona, ‹‹Bu görümde -günlük sunuyla, yıkım getiren başkaldırıyla, kutsal yerin ve ordunun ayak altında çiğnenmesiyle ilgili görümde- olanlar ne zamana dek sürecek?›› diye sordu.'),
(2005270,68,27,8,14,'Kutsal varlık bana, ‹‹2 300 akşam, sabah olacak, sonra kutsal yer yeniden düzene konulacak›› dedi.'),
(2005271,68,27,8,15,'Ben Daniel, gördüğüm görümün ne anlama geldiğini çözmeye çalışırken, insana benzer biri karşımda durdu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005272,68,27,8,16,'Bir insan sesinin Ulay Kanalından, ‹‹Ey Cebrail, görümün ne anlama geldiğini şuna açıkla›› diye seslendiğini duydum.'),
(2005273,68,27,8,17,'Cebrail durduğum yere yaklaşınca korkudan yere yığıldım. Bana, ‹‹Ey insanoğlu!›› dedi, ‹‹Bu görümün sonla ilgili olduğunu anla.››'),
(2005274,68,27,8,18,'O benimle konuşurken, yüzükoyun yere uzanmış, derin bir uykuya dalmışım. Dokunup beni ayağa kaldırdı.'),
(2005275,68,27,8,19,'Bana, ‹‹Daha sonra Tanrının öfkesi sona erdiğinde neler olacağını sana söyleyeceğim›› dedi, ‹‹Çünkü görüm sonun belirlenen zamanıyla ilgilidir.'),
(2005276,68,27,8,20,'Gördüğün iki boynuzlu koç Med ve Pers krallarını simgeler.'),
(2005277,68,27,8,21,'Teke Grek Kralıdır; gözleri arasındaki büyük boynuz birinci kraldır.'),
(2005278,68,27,8,22,'Kırılan boynuzun yerine çıkan dört boynuz, ulusundan çıkacak dört krallığı simgeliyor. Ama ilk kral kadar güçlü olmayacaklar.'),
(2005279,68,27,8,23,'‹‹Bu dört krallığın sonu yaklaşıp yapılan kötülükler doruğa varınca, sert yüzlü ve aldatmada usta bir kral ortaya çıkacak.'),
(2005280,68,27,8,24,'Kendisinden gelmeyen büyük bir güce kavuşacak. Şaşırtıcı yıkımlar yapacak, el attığı her işte başarılı olacak. Güçlüleri ve kutsal halkı yok edecek.'),
(2005281,68,27,8,25,'Yapacağı işleri aldatarak başaracak, kendisini yükseltecek. Güvenlikte olan birçoklarını yok edecek, Önderler Önderine karşı duracak. Ama kendisi insan eli değmeden yok edilecek.'),
(2005282,68,27,8,26,'‹‹Akşam ve sabahla ilgili sana bildirilen görüm gerçektir. Ama sen görümü gizli tut. Çünkü uzak bir gelecekle ilgilidir.››'),
(2005283,68,27,8,27,'Ben Daniel günlerce bitkin ve hasta kaldım. Sonra kalkıp kralın işlerini yapmayı sürdürdüm. Bu anlaşılması güç görümden ötürü şaşkındım.'),
(2005284,68,27,9,1,'Medli Ahaşveroş oğlu Darius Kildan Kralı oldu. Krallığının birinci yılında ben Daniel, RABbin Peygamber Yeremyaya bildirdiği sayının - Yeruşalimin ıssız kalacağı yılların sayısının - yetmiş olduğunu Kutsal Yazılardan anladım.'),
(2005285,68,27,9,3,'Bunun üzerine yüzümü Rab Tanrıya çevirdim. Duayla, yakarışla, oruçla Ona yalvardım; çul kuşanıp külde oturdum.'),
(2005286,68,27,9,4,'RAB Tanrıma dua edip günahlarımızı itiraf ettim. Şöyle dedim: ‹‹Ya Rab, kendisini sevenlerle, buyruklarına uyanlarla yaptığı antlaşmaya bağlı kalan yüce ve görkemli Tanrı!'),
(2005287,68,27,9,5,'Buyruklarından, ilkelerinden ayrılıp günah, suç işledik, kötülük yaptık, başkaldırdık.'),
(2005288,68,27,9,6,'Senin adına krallarımıza, önderlerimize, atalarımıza, ülkedeki bütün halka seslenen kulların peygamberleri dinlemedik.'),
(2005289,68,27,9,7,'‹‹Sen adaletlisin, ya Rab! Sadakatsizliğimiz yüzünden bizi uzak yakın ülkelere sürdün. Oralarda yaşayan biz Yahudiler, Yeruşalim halkı, İsrailliler bugün utanç içindeyiz.'),
(2005290,68,27,9,8,'Evet, ya RAB, bizler, krallarımız, önderlerimiz, atalarımız sana karşı işlediğimiz günah yüzünden utanç içindeyiz.'),
(2005291,68,27,9,9,'Sana karşı geldiğimiz halde, sen acıyan, bağışlayan Tanrımız Rabsin.'),
(2005292,68,27,9,10,'Tanrımız RABbin sözüne kulak vermedik, kulları peygamberler aracılığıyla bize verdiği yasalara uymadık.'),
(2005293,68,27,9,11,'Bütün İsrail halkı yasanı çiğnedi, sırtını sana dönüp seni dinlemek istemedi. ‹‹Bu yüzden Tanrı kulu Musanın Yasasında yazılan lanet başımıza yağdı, içilen ant yerine geldi. Çünkü sana karşı günah işledik.'),
(2005294,68,27,9,12,'Üzerimize büyük yıkım getirerek bizim ve bizi yöneten önderlerimiz için söylediğin sözleri yerine getirdin. Yeruşalimin başına gelen, göğün altındaki başka hiçbir kentin başına gelmemiştir.'),
(2005295,68,27,9,13,'Musanın Yasasında yazıldığı gibi, bütün bu yıkımlar başımıza geldi. Buna karşın, ey Tanrımız RAB, suçumuzdan dönüp senin gerçeklerine yönelerek lütfunu dilemedik.'),
(2005296,68,27,9,14,'RAB üzerimize yıkım göndermekten caymadı. Çünkü Tanrımız RAB yaptığı her şeyde adildir. Bizse Onun sözüne kulak vermedik.'),
(2005297,68,27,9,15,'‹‹Ey Tanrımız Rab, sen halkını Mısırdan güçlü elinle çıkardın ve bugün olduğu gibi ün kazandın. Bizse günah işledik, kötülük yaptık.'),
(2005298,68,27,9,16,'Ya Rab, doğru işlerin uyarınca kentin Yeruşalimden, kutsal dağından öfkeni, kızgınlığını kaldırmanı dilerim. Günahlarımız ve atalarımızın suçları yüzünden Yeruşalim de halkın da çevremizdekilerin tümüne alay konusu oldu.'),
(2005299,68,27,9,17,'‹‹Şimdi, ey Tanrımız, kulunun duasını, yakarışını işit. Adın uğruna, ya Rab, yüzünü viran tapınağına çevir.'),
(2005300,68,27,9,18,'Ey Tanrım, kulak ver ve işit! Gözlerini aç, senin olan viran kenti gör. Doğruluğumuzdan değil, senin büyük merhametinden ötürü dilekte bulunuyoruz.'),
(2005301,68,27,9,19,'Ya Rab, dinle! Ya Rab, bağışla! İşit ve davran, ya Rab! Ey Tanrım, adının hatırı için gecikme! Çünkü kent ve halk senindir.››'),
(2005302,68,27,9,20,'Ben daha konuşup dua ederken, günahımı ve halkım İsrailin günahını açıkça kabul edip Tanrımın kutsal dağı için Tanrım RABbe dilekte bulunurken,'),
(2005303,68,27,9,21,'daha dua ediyorken, önceden görümde gördüğüm adam -Cebrail- akşam sunusu saatinde hızla uçarak yanıma geldi.'),
(2005304,68,27,9,22,'‹‹Daniel, sana anlayış vermek için geldim›› diye açıkladı,'),
(2005305,68,27,9,23,'‹‹Sen Tanrıya yalvarmaya başlar başlamaz, duan yanıtlandı; bunu bildirmeye geldim. Çünkü sen çok sevilen birisin. Bu nedenle sözün anlamını kavra ve görümü anla:'),
(2005306,68,27,9,24,'‹‹Başkaldırıyı ortadan kaldırmak, günaha son vermek, suçu bağışlatmak, sonsuza dek kalıcı doğruluğu sağlamak, görüm ve peygamberliği mühürlemek, En Kutsalı meshetmek için senin halkına ve kutsal kentine yetmiş hafta kadar zaman saptanmıştır. geldiği sanılıyor.'),
(2005307,68,27,9,25,'‹‹Şunu bil ve anla: Yeruşalimi yeniden kurmak için buyruğun verilmesinden, meshedilmiş olan önderin gelişine dek yedi hafta geçecek. Altmış iki hafta içinde Yeruşalim yeniden sokaklarla, hendeklerle kurulacak. Ancak bu sıkıntılı zamanlarda olacak.'),
(2005308,68,27,9,26,'Bu altmış iki hafta sonunda meshedilmiş olan öldürülecek ve onu destekleyen olmayacak. Gelecek önderin halkı, kenti ve kutsal yeri yerle bir edecek. Sonu tufanla olacak: Savaş sona dek sürecek. Yıkımların da olacağı kararlaştırıldı.'),
(2005309,68,27,9,27,'Gelecek önder birçoklarıyla bir haftalık sağlam bir antlaşma yapacak. Haftanın yarısı geçince, kurbanı da sunuyu da kaldıracak. Kararlaştırılan yıkım başına gelinceye dek yok edici önder tapınağın üst bölümüne yıkıcı iğrenç şeyler yerleştirecek.››'),
(2005310,68,27,10,1,'Pers Kralı Koreşin krallığının üçüncü yılında Belteşassar diye çağrılan Daniele bir giz açıklandı. Büyük bir savaşla ilgili olan bu giz gerçekti. Daniel görümde kendisine açıklanan gizi anladı.'),
(2005311,68,27,10,2,'O sırada ben Daniel üç haftadır yas tutuyordum.'),
(2005312,68,27,10,3,'Üç hafta dolana dek ağzıma ne güzel bir yiyecek ya da et koydum, ne şarap içtim, ne de yağ süründüm.'),
(2005313,68,27,10,4,'Birinci ayın yirmi dördüncü günü, Büyük Irmakın, yani Diclenin kıyısındayken,'),
(2005314,68,27,10,5,'gözlerimi kaldırıp bakınca keten giysi giyinmiş, beline Ufaz altınından kemer kuşanmış bir adam gördüm.'),
(2005315,68,27,10,6,'Bedeni sarı yakut gibiydi. Yüzü şimşek gibi parlıyordu. Gözleri alevli meşalelere benziyordu. Kollarıyla bacakları cilalı tunç gibi parlıyor, sesi büyük bir kalabalığın çıkardığı gürültüyü andırıyordu.'),
(2005316,68,27,10,7,'Görümü yalnız ben Daniel gördüm. Yanımdakiler görmediler, ama dehşete düşerek gizlenmek için kaçtılar.'),
(2005317,68,27,10,8,'Böylece ben yalnız kaldım. Bu büyük görümü seyrederken gücüm tükendi, benzim büsbütün soldu, kendimi toparlayamadım.'),
(2005318,68,27,10,9,'Sonra adamın sesini duyunca yüzüstü yere düşüp derin bir uykuya daldım.'),
(2005319,68,27,10,10,'Derken bir el dokundu, titredim; beni dizlerimle ellerimin üzerine kaldırdı.'),
(2005320,68,27,10,11,'Bana, ‹‹Ey Daniel, sen ki çok sevilen birisin!›› dedi, ‹‹Ayağa kalk ve söyleyeceklerime iyi kulak ver. Çünkü sana gönderildim.›› O bunları söyler söylemez titreyerek ayağa kalktım.'),
(2005321,68,27,10,12,'‹‹Korkma, ey Daniel!›› diye devam etti, ‹‹Anlayışa erişmeye ve kendini Tanrının önünde alçaltmaya karar verdiğin gün duan işitildi. İşte bu yüzden geldim.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005322,68,27,10,13,'Pers krallığının önderi yirmi bir gün bana karşı durdu. Sonra baş önderlerden Mikail bana yardıma geldi, çünkü orada, Pers krallarının yanında alıkonulmuştum.'),
(2005323,68,27,10,14,'Son günlerde halkının başına neler geleceğini sana açıklamak için geldim şimdi, çünkü bu görüm gelecekle ilgilidir.››'),
(2005324,68,27,10,15,'O bunları söyleyince, suskun suskun yere baktım.'),
(2005325,68,27,10,16,'Derken insanoğluna benzeyen biri dudaklarıma dokundu. Ben de ağzımı açıp konuşmaya başladım. Karşımda durana, ‹‹Ey efendim, bu görüm yüzünden acı çekiyorum, kendimi toparlayamıyorum›› dedim,'),
(2005326,68,27,10,17,'‹‹Ben kulun nasıl seninle konuşayım? Gücüm tükendi, soluğum kesildi.››'),
(2005327,68,27,10,18,'İnsana benzeyen varlık yine dokunup beni güçlendirdi.'),
(2005328,68,27,10,19,'‹‹Ey çok sevilen adam, korkma!›› dedi, ‹‹Esenlik olsun sana! Güçlü ol! Evet, güçlü ol!›› O benimle konuşunca güçlendim. ‹‹Konuşmanı sürdür, efendim, çünkü bana güç verdin›› dedim.'),
(2005329,68,27,10,20,'Bunun üzerine, ‹‹Sana neden geldiğimi biliyor musun?›› dedi, ‹‹Çok yakında dönüp Pers önderiyle savaşacağım. Ben gidince Grek önderi gelecek.'),
(2005330,68,27,10,21,'Ama önce Gerçek Kitap''ta neler yazıldığını sana bildireceğim. Onlara karşı önderiniz Mikail dışında bana yardım eden kimse yok.'),
(2005331,68,27,11,1,'‹‹Medli Dariusun krallığının birinci yılında Mikaili destekleyip korumak için onun yanında durdum.››'),
(2005332,68,27,11,2,'‹‹Şimdi sana gerçeği bildireceğim: Pers krallığında üç kral daha ortaya çıkacak. Ama dördüncü kral öbür üçünden daha zengin olacak. Zenginliği sayesinde elde edeceği güçle herkesi Grek ülkesine karşı kışkırtacak.'),
(2005333,68,27,11,3,'Sonra güçlü bir kral çıkacak. Büyük yetkiyle krallık edecek ve dilediği gibi davranacak.'),
(2005334,68,27,11,4,'Ne var ki, o gücünün doruğundayken, krallığı darmadağın edilecek, göğün dört rüzgarı gibi dört parçaya bölünecek. Krallık onun soyundan gelenlere geçmeyecek, yerine geçenlerin hiçbiri onun gibi egemenlik sürmeyecek. Krallığı yıkılıp başkalarına verilecek.'),
(2005335,68,27,11,5,'‹‹Güney Kralı güçlenecek. Ancak komutanlarından biri ondan daha çok güçlenecek ve krallığı büyük olacak.'),
(2005336,68,27,11,6,'Birkaç yıl sonra bu ikisi uzlaşacak. Güney Kralı yapılan uzlaşmayı onaylamak için kızını Kuzey Kralına eş olarak verecek. Ama kız gücünü koruyamayacak. Kralın ömrü de gücü de uzun sürmeyecek. Bu arada kızla babası da, ona eşlik edenlerle onu destekleyen de ele verilecek.'),
(2005337,68,27,11,7,'‹‹Babasının yerine kızın ailesinden biri ortaya çıkacak. Kuzey Kralının ordusuna saldırıp kalesini alacak. Onlarla savaşıp yenecek.'),
(2005338,68,27,11,8,'Onların ilahlarını, dökme putlarını, değerli altın ve gümüş kaplarını alıp Mısıra götürecek. Kuzey Kralını birkaç yıl rahat bırakacak.'),
(2005339,68,27,11,9,'Sonra Kuzey Kralı gidip Güney Kralının ülkesine saldıracak, ardından kendi ülkesine dönecek.'),
(2005340,68,27,11,10,'Kuzey Kralının oğulları savaşa hazırlanarak çok büyük bir ordu toplayacaklar. Ordu sel gibi taşacak, önüne geleni alıp götürecek, gelip Güney Kralının kalesine dayanacak.'),
(2005341,68,27,11,11,'‹‹Güney Kralı öfkeyle çıkıp Kuzey Kralına karşı savaşacak. Kuzey Kralı büyük bir ordu topladığı halde, bu ordu Güney Kralının eline teslim edilecek.'),
(2005342,68,27,11,12,'Bu büyük ordu yenilgiye uğrayınca Güney Kralı gurura kapılacak. On binlerce insanı öldürecek, ama zaferi uzun sürmeyecek.'),
(2005343,68,27,11,13,'Çünkü Kuzey Kralı öncekinden daha büyük bir ordu toplayacak ve birkaç yıl sonra büyük, iyi donatılmış bir orduyla ülkeye doğru ilerleyecek.'),
(2005344,68,27,11,14,'‹‹Bu sırada birçokları Güney Kralına karşı çıkacak. Senin halkından bazı zorbalar da, görüm yerine gelsin diye ayaklanacak, ama yenilgiye uğrayacaklar.'),
(2005345,68,27,11,15,'Sonra Kuzey Kralı gelip toprak yığarak tepecikler yapacak ve surlu kenti ele geçirecek. Güney Kralının güçleri buna karşı duramayacak. En seçme askerlerinin bile karşı durmaya güçleri yetmeyecek.'),
(2005346,68,27,11,16,'Kente saldıran Kuzey Kralı dilediği gibi davranacak, kimse ona karşı duramayacak. Güzel Ülkeyi yönetecek, yıkıp yok etme yetkisi onun elinde olacak.'),
(2005347,68,27,11,17,'Krallığının bütün gücünü toplayıp Güney Kralının üzerine yürümeyi amaçlayacak ve Güney Kralıyla bir antlaşma yapacak. Ülkesini yerle bir etmek için kızını eş olarak ona verecek. Ama tasarısı başarılı olmayacak, ona yarar sağlamayacak.'),
(2005348,68,27,11,18,'Bundan sonra deniz kıyısındaki bölgelere yönelecek, birçoklarını ele geçirecek. Ne var ki, bir komutan onun saygısızlıklarını sona erdirecek, saygısızlığının karşılığını verecek.'),
(2005349,68,27,11,19,'Bunun üzerine Kuzey Kralı kendi ülkesinin kalelerine yönelecek, ama tökezleyip düşecek. Bir daha da ortaya çıkmayacak.'),
(2005350,68,27,11,20,'‹‹Yerine geçen kral, krallığının yüceliği için zorla vergi toplayacak birini gönderecek. Ama birkaç gün içinde öfkesiz ve savaşsız yok edilecek.'),
(2005351,68,27,11,21,'‹‹Yerine krallıkla onurlandırılmamış değersiz biri geçecek. Halk güvenlik içindeyken, kurduğu düzenler sayesinde gelip krallığı ele geçirecek.'),
(2005352,68,27,11,22,'Çok güçlü orduları süpürüp yok edecek; antlaşma önderi de yok edilecek.'),
(2005353,68,27,11,23,'Onunla antlaşma yaptıktan sonra hileye başvuracak. Az sayıda insanla gittikçe güçlenecek.'),
(2005354,68,27,11,24,'Beklenmedik bir anda ilin zengin bölgelerine saldırıp babalarının, atalarının yapmadığı şeyleri yapacak. Adamlarına yağma ve çapul malı, servetler dağıtacak. Kalelere saldırmak için düzenler kuracak, ama bu uzun sürmeyecek.'),
(2005355,68,27,11,25,'‹‹Gücünü ve cesaretini toplayarak büyük bir orduyla Güney Kralına karşı çıkacak. Güney Kralı da büyük ve çok güçlü bir orduyla savaşacak. Ne var ki, kurulan düzenler yüzünden ona karşı duramayacak.'),
(2005356,68,27,11,26,'Sofrasından yiyenler Güney Kralını yıkmaya çalışacaklar; ordusu dağılacak, birçokları vurulup öldürülecek.'),
(2005357,68,27,11,27,'Her iki kral da kötülük tasarlayacak. Aynı masada oturup birbirlerine yalan söyleyecekler. Ancak bu bir yarar sağlamayacak. Çünkü son yine de belirlenen zamanda gelecek.'),
(2005358,68,27,11,28,'Kuzey Kralı büyük bir servetle ülkesine dönecek, ama amacı kutsal antlaşmaya karşı gelmek olacak. Dilediğini yaptıktan sonra ülkesine dönecek.'),
(2005359,68,27,11,29,'‹‹Belirlenen zamanda dönüp yine Güneye saldıracak. Ancak bu kez sonuç öncekinden farklı olacak.'),
(2005360,68,27,11,30,'Ona karşı koymak için Kittimden gelen gemiler cesaretini kıracak. Geri dönecek ve öfkeyle kutsal antlaşmaya karşı çıkacak, kutsal antlaşmayı bırakanları yine kayıracak.'),
(2005361,68,27,11,31,'‹‹Askerleri gidip tapınakla kaleyi kirletecek, günlük sunuları kaldırıp yıkıcı iğrenç şeyi koyacaklar.'),
(2005362,68,27,11,32,'Kuzey Kralı antlaşmayı bozanları yaltaklanarak ayartacak, ama Tanrısını tanıyan halk var gücüyle ona karşı duracak.'),
(2005363,68,27,11,33,'‹‹Halkın arasındaki bilge kişiler birçoklarını eğitecekler. Ama bir süre bu kişiler ya kılıçla öldürülecek, yakılacak, tutsak edilecek ya da mallarından edilecekler.'),
(2005364,68,27,11,34,'Yenilgiye uğrayınca biraz yardım görecekler. İçtenlikten uzak birçok kişi onlardan yana geçecek.'),
(2005365,68,27,11,35,'Bilgelerden kimisi tökezleyecek; öyle ki, son gelinceye dek arınıp temizlenebilsin, lekesiz duruma gelebilsinler. Çünkü son yine de belirlenen zamanda gelecek. lekesiz duruma gelebilsinler›› ya da ‹‹Öyle ki, son gelinceye dek Tanrının halkı arınıp temizlenebilsin, lekesiz duruma gelebilsin››.'),
(2005366,68,27,11,36,'‹‹Kral dilediği gibi davranacak. Kendini bütün tanrılardan daha büyük, daha yüce gösterecek, tanrıların Tanrısına karşı duyulmamış sözler söyleyecek. Tanrının öfkesi tamamlanıncaya dek başarılı olacak. Çünkü tasarlanan, yerine gelecektir.'),
(2005367,68,27,11,37,'Kral hiçbir tanrıya, atalarının ilahlarına da kadınların bağlandığına da ilgi göstermeyecek. Kendisini hepsinden üstün görecek.'),
(2005368,68,27,11,38,'Bu ilahların yerine, kaleler ilahını yüceltecek. Atalarının tanımadığı bu ilaha altın, gümüş, değerli taşlar, pahalı armağanlar sunup onu onurlandıracak.'),
(2005369,68,27,11,39,'Bu yabancı ilahın yardımıyla en güçlü kalelere saldıracak; onu kabul edenleri alabildiğine onurlandıracak, onları birçoklarının başına önder atayacak, ülkeyi ödül olarak onlar arasında bölüştürecek.'),
(2005370,68,27,11,40,'‹‹Son gelince, Güney Kralı Kuzey Kralıyla savaşa tutuşacak. Kuzey Kralı savaş arabalarıyla, atlılarla, birçok gemilerle saldıracak. Her şeyi süpürüp götüren sel gibi taşarak birçok ülkeden geçecek.'),
(2005371,68,27,11,41,'Güzel Ülkeye de girecek, birçok ülke yenilgiye uğrayacak. Ancak Edom, Moav ve Ammon önderleri onun elinden kurtulacak.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005372,68,27,11,42,'Öbür ülkelere de saldıracak. Mısır bile elinden kurtulmayacak.'),
(2005373,68,27,11,43,'Altın ve gümüş hazinelerine, Mısırın bütün değerli eşyalarına el koyacak. Luvlularla Kûşlular onun ardınca yürüyecekler.'),
(2005374,68,27,11,44,'Ne var ki, doğudan ve kuzeyden gelen haberler onu ürkütecek. Birçoklarını yıkıp yok etmek için büyük öfkeyle yola çıkacak.'),
(2005375,68,27,11,45,'Denizle güzel kutsal dağ arasında saray çadırlarını kuracak. Yine de yaşamı son bulacak ve ona yardım eden olmayacak.››'),
(2005376,68,27,12,1,'‹‹O zaman senin halkını koruyan büyük önder Mikail görünecek. Ulusun oluşumundan beri hiç görülmemiş bir sıkıntı dönemi olacak. Bu dönemde halkın -adı kitapta yazılı olanlar- kurtulacak.'),
(2005377,68,27,12,2,'Yeryüzü toprağında uyuyanların birçoğu uyanacak: Kimisi sonsuz yaşama, kimisi utanca ve sonsuz iğrençliğe gönderilecek.'),
(2005378,68,27,12,3,'Bilgeler gökkubbe gibi, birçoklarını doğruluğa döndürenler yıldızlar gibi sonsuza dek parlayacaklar.'),
(2005379,68,27,12,4,'Ama sen, ey Daniel, son gelinceye dek bu sözleri sakla, kitabı mühürle. Bilgileri artsın diye birçokları oraya buraya gidecek.››'),
(2005380,68,27,12,5,'Ben Daniel baktım, biri ırmağın bu kıyısında, öbürü öbür kıyısında duran başka iki varlık gördüm.'),
(2005381,68,27,12,6,'İçlerinden biri, ırmağın suları üzerinde duran keten giysili adama, ‹‹Bu şaşırtıcı olayların son bulması ne kadar zaman alacak?›› diye sordu.'),
(2005382,68,27,12,7,'Irmağın suları üzerinde duran keten giysili adamın sağ ve sol elini göğe kaldırarak sonsuza dek Diri Olanın adıyla ant içip, ‹‹Üç buçuk yıl alacak›› dediğini duydum, ‹‹Kutsal halkın gücü tümüyle kırılınca, bütün bu olaylar son bulacak.›› vakit››.'),
(2005383,68,27,12,8,'Adamın söylediklerini duydumsa da anlamadım. Bunun için, ‹‹Ey efendim, bunların sonu ne olacak?›› diye sordum.'),
(2005384,68,27,12,9,'Şöyle yanıtladı: ‹‹Sen git, Daniel. Bu sözler son gelinceye dek saklanıp mühürlenecek.'),
(2005385,68,27,12,10,'Birçokları kendilerini arıtıp temizlenecek, lekesiz duruma gelecek, ama kötüler kötülük etmeyi sürdürecek. Kötülerin hiçbiri anlamayacak, bilgeler anlayacak.'),
(2005386,68,27,12,11,'‹‹Günlük sununun kaldırılıp yıkıcı iğrenç şeyin konduğu zamandan başlayarak 1 290 gün geçecek.'),
(2005387,68,27,12,12,'Bekleyip 1 335 güne ulaşana ne mutlu!'),
(2005388,68,27,12,13,'‹‹Sana gelince, ey Daniel, son gelinceye dek yoluna devam et. Rahatına kavuşacak ve günlerin sonunda ödülünü almak için uyanacaksın.››'),
(2005389,68,28,1,1,'Uzziya, Yotam, Ahaz ve Hizkiyanın Yahudada ve Yehoaş oğlu Yarovamın İsrailde krallık ettiği dönemde RABbin Beeri oğlu Hoşeaya bildirdiği sözler.'),
(2005390,68,28,1,2,'RAB Hoşea aracılığıyla konuşmaya başladığında ona şöyle dedi: ‹‹Git, kötü bir kadınla evlen, ondan zina çocukların olsun. Çünkü ülke halkı benden ayrılarak adice zina ediyor.››'),
(2005391,68,28,1,3,'Böylece Hoşea gidip Divlayimin kızı Gomerle evlendi. Kadın hamile kalıp kendisine bir oğul doğurdu.'),
(2005392,68,28,1,4,'RAB Hoşeaya, ‹‹Çocuğun adını Yizreel koy›› dedi, ‹‹Çünkü çok geçmeden Yizreelde dökülen kanın öcünü Yehu soyundan alacağım. İsrail krallığının sonunu getireceğim.'),
(2005393,68,28,1,5,'Ve o gün Yizreel Vadisinde İsrailin yayını kıracağım.›› anlamına gelir.'),
(2005394,68,28,1,6,'Gomer yine hamile kaldı ve bir kız doğurdu. RAB Hoşeaya, ‹‹Adını Lo-Ruhama koy›› dedi, ‹‹Çünkü artık İsrail soyuna acımayacağım, onları bağışlamayacağım.'),
(2005395,68,28,1,7,'Ancak Yahuda soyuna merhamet edeceğim. Ben kurtaracağım onları, ama yay, kılıç, savaş, at ve atlılar aracılığıyla değil, kendi aracılığımla.››'),
(2005396,68,28,1,8,'Gomer Lo-Ruhamayı sütten kesince yine hamile kaldı ve bir oğul doğurdu.'),
(2005397,68,28,1,9,'RAB Hoşeaya, ‹‹Adını Lo-Ammi koy›› dedi, ‹‹Çünkü siz benim halkım değilsiniz, ben de sizin Tanrınız değilim.'),
(2005398,68,28,1,10,'‹‹Yine de İsraillilerin sayısı denizin kumu gibi sayılamaz, ölçülemez olacak. Kendilerine, ‹Siz halkım değilsiniz› denilen yerde, ‹Yaşayan Tanrının çocuklarısınız› denecek.'),
(2005399,68,28,1,11,'Yahuda ve İsrail halkları yeniden birleşecek. Başlarına tek önder atayacaklar. Ülkeden çıkacaklar. Çünkü Yizreel günü büyük bir gün olacak.'),
(2005400,68,28,2,1,'‹‹Kardeşlerinizi ‹Halkım›, kızkardeşlerinizi ‹Merhamete ermişler› diye çağırın.››'),
(2005401,68,28,2,2,'‹‹Azarlayın annenizi, azarlayın, 2 Çünkü o benim karım değil artık, 2 Ben de onun kocası değilim. 2 Yüzünden akan fahişeliği, 2 Koynundan zinaları atsın.'),
(2005402,68,28,2,3,'Yoksa onu çırılçıplak soyacak, 2 Anneden doğma edeceğim, 2 Çöle, çorak toprağa çevirecek, 2 Susuzluktan öldüreceğim.'),
(2005403,68,28,2,4,'Acımayacağım çocuklarına, 2 Çünkü onlar zina çocuklarıdır.'),
(2005404,68,28,2,5,'Anneleri zina etti, 2 Onlara gebe kaldı, rezillik etti. 2 ‹Oynaşlarımın ardından gideceğim› dedi, 2 ‹Ekmeğimi, suyumu, yapağımı, ketenimi, zeytinyağımı, içkimi onlar veriyor.›'),
(2005405,68,28,2,6,'İşte bu yüzden onun yoluna dikenli çit çekeceğim, 2 Yolunu bulamasın diye 2 Önüne duvar öreceğim.'),
(2005406,68,28,2,7,'Oynaşlarının ardına düşecek, 2 Ama onlara erişemeyecek, 2 Onları arayacak, 2 Ama bulamayacak. 2 O zaman, ‹İlk kocama döneyim› diyecek, 2 ‹Çünkü o zamanki halim şimdikinden iyiydi!›'),
(2005407,68,28,2,8,'Ama kendisine tahıl, yeni şarap, zeytinyağı verenin, 2 Baal için harcadığı altınla gümüşü bol bol sağlayanın 2 Ben olduğumu bilmedi.'),
(2005408,68,28,2,9,'Bu yüzden zamanında tahılımı, 2 Mevsiminde yeni şarabımı geri alacağım; 2 Çıplak bedenini örten yapağımı, ketenimi çekip alacağım.'),
(2005409,68,28,2,10,'Evet, oynaşlarının önünde ayıbını ortaya çıkaracağım, 2 Kimse elimden kurtaramayacak onu.'),
(2005410,68,28,2,11,'Bütün sevincine, bayramlarına, 2 Yeni Ay törenlerine, Şabat günlerine, 2 Dinsel bayramlarının tümüne son vereceğim.'),
(2005411,68,28,2,12,'Viran edeceğim asmalarını, incir ağaçlarını, 2 Hani, ‹Bunlar oynaşlarımın bana verdiği ücrettir› dediği; 2 Çalılığa çevireceğim onları, 2 Yem olacaklar yabanıl hayvanlara.'),
(2005412,68,28,2,13,'Cezalandıracağım onu, 2 Baallara buhur yaktığı günler için; 2 Halkalarla, takılarla süslenmiş, 2 Oynaşlarının ardınca gitmiş, 2 Beni unutmuştu›› 2 Diyor RAB.'),
(2005413,68,28,2,14,'‹‹İşte bu yüzden onu ikna edip çöle götürecek, 2 Onunla dostça konuşacağım.'),
(2005414,68,28,2,15,'Kendisine orada bağlar vereceğim, 2 Akorfç Vadisini ona umut kapısı yapacağım. 2 Gençlik günlerinde olduğu gibi, 2 Mısırdan çıktığı günlerde olduğu gibi, 2 Ezgiler söyleyecek.'),
(2005415,68,28,2,16,'Ve o gün gelecek›› diyor RAB, 2 ‹‹Bana, ‹Kocam› diyeceksin; 2 Artık, ‹Efendim› demeyeceksin. var. Baal hem bir ilahın adı hem de ‹‹Koca››, ‹‹Efendi›› anlamlarına gelir.'),
(2005416,68,28,2,17,'Ağzından Baalların adını sileceğim, 2 Adları bir daha anılmayacak.'),
(2005417,68,28,2,18,'Kırdaki hayvanlarla, gökteki kuşlarla, 2 Toprakta yaşayan canlılarla, 2 Halkım için o gün antlaşma yapacağım; 2 Ülkeden yayı, kılıcı, savaşı kaldıracağım, 2 Güvenlik içinde yatıracağım onları.'),
(2005418,68,28,2,19,'Seni sonsuza dek kendime eş alacağım, 2 Doğruluk, adalet, sevgi, merhamet temelinde 2 Seninle evleneceğim.'),
(2005419,68,28,2,20,'Sadakatle seninle evleneceğim, 2 RABbi tanıyacaksın.'),
(2005420,68,28,2,21,'‹‹Ve o gün yanıt vereceğim›› diyor RAB, 2 ‹‹Göklere yanıt vereceğim; 2 Onlar da yere yanıt verecek;'),
(2005421,68,28,2,22,'Yerse, tahıla, yeni şaraba, 2 Zeytinyağına yanıt verecek, 2 Onlar da Yizreele yanıt verecekler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005422,68,28,2,23,'Onu ülkede kendim için ekeceğim, 2 Merhamete ermemiş olana acıyacağım, 2 Halkım olmayana, ‹Halkımsın› diyeceğim; 2 Onlar da bana, ‹Tanrım› diyecekler.››'),
(2005423,68,28,3,1,'RAB bana şöyle dedi: ‹‹İsraillilerin başka ilahlara yönelmelerine, üzüm pestillerine gönül vermelerine karşın, RAB onları nasıl seviyorsa, sen de git, o kadını sev, başkasınca sevilmiş, zina etmiş olsa bile.››'),
(2005424,68,28,3,2,'Böylece onu on beş şekel gümüş, bir homer bir letek arpa karşılığında satın aldım kendime.'),
(2005425,68,28,3,3,'Ona, ‹‹Uzun süre benimle yaşayacaksın›› dedim, ‹‹Zina etmeyecek, başka bir erkekle dostluk kurmayacaksın. Ben de sana öyle davranacağım.››'),
(2005426,68,28,3,4,'Çünkü İsrailliler uzun süre kral, önder, kurban, dikili taş, efod, aile putu olmadan yaşayacak.'),
(2005427,68,28,3,5,'Sonra dönüp Tanrıları RAB''bi, kralları Davut''u arayacaklar. Son günlerde korkarak RAB''be ve O''nun iyiliğine yönelecekler.'),
(2005428,68,28,4,1,'Ey İsrailliler, dinleyin RABbin sözünü, 2 Çünkü RABbin davası var bu ülkede yaşayanlarla; 2 ‹‹Yok olmuş sevgi, sadakat, Tanrı bilgisi.'),
(2005429,68,28,4,2,'Lanet, yalan, adam öldürme, hırsızlık, 2 Zina almış her şeyin yerini. 2 Zorbalık ediyorlar, 2 Kan üstüne kan döküyorlar.'),
(2005430,68,28,4,3,'Bu yüzden ülke yas tutuyor, 2 Tükeniyor orada yaşayan herkes, 2 Kırdaki hayvanlar, gökteki kuşlar 2 Denizdeki balıklar...'),
(2005431,68,28,4,4,'‹‹Ancak kimse kimseyle çekişmesin, 2 Kimse kimseyi suçlamasın, 2 Çünkü halkın kâhinle çekişenlere benziyor.'),
(2005432,68,28,4,5,'Sen gündüz tökezleyeceksin, 2 Peygamber de gece seninle birlikte, 2 Yok edeceğim anneni.'),
(2005433,68,28,4,6,'‹‹Yok oldu halkım bilgisizlikten, 2 Sen bilgiyi reddettiğin için, 2 Ben de seni reddedeceğim, 2 Bana kâhinlik etmeyesin diye. 2 Sen Tanrının yasasını unuttuğun için, 2 Ben de senin çocuklarını unutacağım.'),
(2005434,68,28,4,7,'Kâhinler çoğaldıkça 2 Daha çok günah işlediler bana karşı, 2 Onların onurunu utanca çevireceğim. Süryanice ve bazı eski İbrani din bilginlerine göre ‹‹Onurumu utanca çevirecekler››.'),
(2005435,68,28,4,8,'Halkımın günahlarıylafı besleniyorlar, 2 Onların suç işlemesini istiyorlar. ‹‹Günah sunusu›› anlamına gelir (bkz. Lev.6:25-30).'),
(2005436,68,28,4,9,'Halkın başına gelenler kâhinlerin başına da gelecek, 2 Tuttukları yol yüzünden cezalandıracağım onları, 2 Yaptıklarının karşılığını vereceğim.'),
(2005437,68,28,4,10,'Yiyecekler, ama doymayacaklar, 2 Zina edecekler, ama çoğalmayacaklar. 2 Çünkü RABbi dinlemekten vazgeçtiler.'),
(2005438,68,28,4,11,'‹‹Zina, yeni ve eski şarap insanın aklını başından alır.'),
(2005439,68,28,4,12,'Halkım tahta puta danışıyor, 2 Değneğinden yanıt alıyor. 2 Çünkü zina ruhu onları saptırdı, 2 Kendi Tanrılarından ayrılarak zina ettiler.'),
(2005440,68,28,4,13,'Dağ başlarında kurban kesiyor, 2 Tepelerde meşe, aselbent, yabanıl fıstık ağaçları altında buhur yakıyorlar, 2 Gölgeleri güzel olduğu için. 2 Bu yüzden kızlarınız fahişelik ediyor, 2 Gelinleriniz zina.'),
(2005441,68,28,4,14,'Fahişelik ettiklerinde kızlarınızı, 2 Zina ettiklerinde gelinlerinizi cezalandırmayacağım. 2 Çünkü erkekleriniz fahişelerle oynaşıyor, 2 Putların tapınağında fuhuş yapanlarla kurban kesiyorlar. 2 Anlayışsız halk mahvolacak.'),
(2005442,68,28,4,15,'‹‹Ey İsrail, sen zina etsen de, 2 Yahuda suç işlemese bari. ‹‹Gilgala gitmeyin, 2 Beytavene çıkmayın. 2 ‹Yaşayan RABbin hakkı için› diye ant içmeyin. tapınma merkezleriydi.'),
(2005443,68,28,4,16,'Çünkü İsrail inatçı bir inek gibi inat etti, 2 Şimdi RAB nasıl güder onları otlakta kuzu gibi?'),
(2005444,68,28,4,17,'Efrayim putlarına sarıldı, 2 Bırak onu!'),
(2005445,68,28,4,18,'İçkileri tükendi, 2 Hâlâ zina ediyorlar; 2 Önderleri rezilliğe gönül verdi.'),
(2005446,68,28,4,19,'Rüzgar onları kanatlarına sardı, 2 Kurbanları yüzünden utanacaklar.'),
(2005447,68,28,5,1,'‹‹Ey kâhinler, işitin bunu! 2 Ey İsrailliler, dikkatle dinleyin! 2 Kulak verin, ey saraydakiler! 2 Bu yargı size uygulanacak. 2 Çünkü siz Mispada bir tuzak, 2 Tavor Dağına serilmiş bir ağ oldunuz.'),
(2005448,68,28,5,2,'Başkaldıranlar azıttıkça azıttı, 2 Ama ben hepsini yola getireceğim.'),
(2005449,68,28,5,3,'Efrayimi tanırım, 2 İsrailde de benim için gizli bir şey yok. 2 Çünkü daha yeni zina ettin, ey Efrayim, 2 Kirlenmiş İsrail.'),
(2005450,68,28,5,4,'Yaptıkları işler Tanrılarına dönmeye izin vermiyor, 2 Çünkü zina ruhu var içlerinde, 2 RABbi tanımıyorlar.'),
(2005451,68,28,5,5,'İsrailin gururu kendine karşı tanıklık ediyor; 2 Suç içinde tökezliyor İsraille Efrayim, 2 Yahuda da birlikte.'),
(2005452,68,28,5,6,'Davarlarıyla, sığırlarıyla RABbi aramaya gidecekler, 2 Ama bulamayacaklar. 2 Çünkü RAB onlardan uzaklaştı.'),
(2005453,68,28,5,7,'RABbe ihanet ettiler, 2 Evlilik dışı çocuk yaptılar; 2 Şimdi yiyip bitirecek Yeni Ay törenleri, 2 Hem onları hem de tarlalarını.'),
(2005454,68,28,5,8,'‹‹Givada boru, Ramada borazan çalın, 2 Beytavende savaş çağrısı yapın; 2 Düşman peşinizde, ey Benyaminliler!'),
(2005455,68,28,5,9,'Azar günü Efrayim yıkıma uğrayacak, 2 Kararımı bildiriyorum İsrail oymaklarına.'),
(2005456,68,28,5,10,'Yahuda önderleri sınır taşlarının yerini değiştirenlere benziyor, 2 Gazabımı su gibi dökeceğim üzerlerine.'),
(2005457,68,28,5,11,'Baskı gördü Efrayim, 2 Ezildi yargı önünde, 2 Çünkü bile bile boş şeylerin ardına düştü.'),
(2005458,68,28,5,12,'Ben Efrayimlilere karşı güve, 2 Yahuda halkına karşı küf gibi olacağım.'),
(2005459,68,28,5,13,'‹‹Efrayim hastalığını, 2 Yahuda yarasını görünce, 2 Efrayim Asura gitti, 2 Büyük kraldan yardım istedi. 2 Ama o size şifa veremez, 2 Yaranızı iyileştiremez.'),
(2005460,68,28,5,14,'Çünkü ben Efrayime bir aslan, 2 Yahuda halkına genç bir aslan gibi saldıracağım. 2 Ben parçalayacağım onları, 2 Alıp götüreceğim, kurtaran çıkmayacak.'),
(2005461,68,28,5,15,'Sonra gidip yerime döneceğim, 2 Onlar suçlarını kabul edinceye, 2 Yüzümü arayıncaya dek orada kalacağım. 2 Sıkıntıya düşünce gayretle beni arayacaklar.››'),
(2005462,68,28,6,1,'‹‹Gelin, RABbe dönelim. 2 Bizi O parçaladı, 2 O iyileştirecek. 2 Bizi O yaraladı, 2 Yaramızı O saracak.'),
(2005463,68,28,6,2,'İki gün sonra bizi diriltecek, 2 Üçüncü gün ayağa kaldıracak, 2 Huzurunda yaşayalım diye.'),
(2005464,68,28,6,3,'RABbi tanıyalım, 2 RABbi tanımaya gayret edelim. 2 O tan gibi şaşmadan doğacak, 2 Yağmur gibi, toprağı sulayan 2 Son yağmur gibi bize gelecektir.››'),
(2005465,68,28,6,4,'Tanrı şöyle diyor: 2 ‹‹Ey Efrayim, ne yapayım sana? 2 Ey Yahuda, sana ne yapayım? 2 Sevginiz sabah sisine benziyor, 2 Erkenden uçup giden çiy gibi.'),
(2005466,68,28,6,5,'Bu yüzden sizi peygamberler aracılığıyla lime lime doğradım, 2 Ağzımdan çıkan sözlerle öldürdüm; 2 Yargılarım şimşek gibi ışıldıyor.'),
(2005467,68,28,6,6,'Çünkü ben kurbandan değil, bağlılıktan hoşlanırım, 2 Yakmalık sunulardan çok beni tanımanızı isterim.'),
(2005468,68,28,6,7,'Oysa onlar Adam Kentinde 2 Antlaşmaya uymadılar, 2 Orada bana ihanet ettiler. Kenti gibi›› anlamlarına da gelebilir.'),
(2005469,68,28,6,8,'Gilat kötülük yapanların kentidir, 2 Kan izleriyle doludur.'),
(2005470,68,28,6,9,'Haydut çeteleri nasıl pusuya yatarsa, 2 Kâhinler takımı da öyle; 2 Şekem yolunda adam öldürüyor, 2 Rezillik yapıyorlar.'),
(2005471,68,28,6,10,'İsrail halkında korkunç bir şey gördüm. 2 Efrayim zinaya kapılmış, 2 Kirlenmiş İsrail.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005472,68,28,6,11,'‹‹Ey Yahuda, senin için de bir hasat günü saptandı. ‹‹Ne zaman halkımın durumunu düzeltmek,'),
(2005473,68,28,7,1,'İsraile şifa vermek istesem, 2 Efrayimin suçları, 2 Samiriyenin kötülükleri ortaya çıkıyor. 2 Çünkü hile yapıyorlar, 2 Evlere hırsız giriyor, 2 Dışarda haydut çeteleri soygun yapıyor.'),
(2005474,68,28,7,2,'Ne var ki, düşünmüyorlar, 2 Kötülüklerini unutmadığımı. 2 Günahları kuşatıyor onları, 2 Gözümün önündeler.'),
(2005475,68,28,7,3,'‹‹Kralı kötülükleriyle, 2 Önderleri yalanlarıyla sevindiriyorlar.'),
(2005476,68,28,7,4,'Hepsi zinaya düşkün, 2 Yoğrulan hamur ekşiyinceye dek 2 Fırıncının ateşini karıştırmaya gerek duymadığı fırın gibi kızgınlar.'),
(2005477,68,28,7,5,'Kralımızın şenlik gününde, 2 Önderler şarabın ateşinden hastalandılar, 2 Kral da alaycılarla elele verdi.'),
(2005478,68,28,7,6,'Fırın gibidir yürekleri, 2 Dolap çevirerek ona yaklaşırlar. 2 İçin için yanar öfkeleri 2 Gece boyunca. 2 Alevli ateş gibi parlar 2 Sabah olunca.'),
(2005479,68,28,7,7,'Hepsi fırın gibi kızgındır, 2 Yutar yöneticilerini. 2 Bütün kralları düştü, 2 Kimse yardıma çağırmıyor beni.'),
(2005480,68,28,7,8,'‹‹Efrayim öteki halklarla karışıyor, 2 Çevrilmemiş pideye döndü.'),
(2005481,68,28,7,9,'Gücünü yabancılar yedi, 2 Farkında değil; 2 Saçlarına ak düştü, 2 Farkında değil.'),
(2005482,68,28,7,10,'İsrailin gururu kendine karşı tanıklık ediyor; 2 Bütün bunlara karşın 2 Yine de dönmüyorlar ben, Tanrıları RABbe, 2 Aramıyorlar beni.'),
(2005483,68,28,7,11,'‹‹Efrayim bön, akılsız bir güvercin gibi, 2 Ya Mısırı yardıma çağırıyor, 2 Ya Asura gidiyor.'),
(2005484,68,28,7,12,'Gittiklerinde ağımı üzerlerine atacak, 2 Gökte uçan kuşlar gibi onları yere indireceğim. 2 Topluluklarına bildirildiği gibi, 2 Onları yola getireceğim.'),
(2005485,68,28,7,13,'Vay onların haline, 2 Çünkü benden uzaklaştılar! 2 Felaket gelecek başlarına, 2 Çünkü başkaldırdılar bana! 2 Ben onları kurtarmak istiyorum, 2 Onlarsa iftira ediyor bana.'),
(2005486,68,28,7,14,'Yürekten yakarmıyorlar, 2 Uluyorlar yataklarının üzerinde. 2 Tahıl ve yeni şarap için kendilerini yaralıyor, 2 Bana sırt çeviriyorlar.'),
(2005487,68,28,7,15,'Ben onları eğittim, bileklerine güç verdim, 2 Onlarsa bana düzen kuruyor.'),
(2005488,68,28,7,16,'Dönüyorlar, 2 Ama Yüce Olan''a değil; 2 Kusurlu yay gibiler. 2 Arsız dilleri yüzünden 2 Önderleri kılıçtan geçirilecek. 2 Mısır''da gülünç duruma düşecekler bu yüzden.››'),
(2005489,68,28,8,1,'‹‹Boru çalmaya hazırlan! 2 Düşman kartal gibi dolaşıyor evimin üzerinde; 2 Çünkü İsrail antlaşmaya uymadı, 2 Yasama karşı çıktılar.'),
(2005490,68,28,8,2,'‹Ey Tanrımız, 2 Biz İsrailliler seni tanıyoruz!› 2 Diye bana yakarıyorlar.'),
(2005491,68,28,8,3,'İyi olanı reddettiler, 2 Düşman kovalayacak onları.'),
(2005492,68,28,8,4,'Krallar atadılar bana sormadan, 2 Önderler seçtiler benden habersiz. 2 Altın ve gümüşleriyle yıkımlarına yol açan putlar yaptılar.'),
(2005493,68,28,8,5,'Ey Samiriye, atın buzağı putunuzu, 2 Öfkem alevleniyor size karşı! 2 Hiç mi temiz olamayacaksınız?'),
(2005494,68,28,8,6,'Çünkü bu İsrailin işidir. 2 O buzağıyı bir usta yaptı, 2 Tanrı değildir o. 2 Samiriyenin buzağı putu parçalanacak.'),
(2005495,68,28,8,7,'Çünkü rüzgar eken kasırga biçer. 2 Baş vermeyen buğday un vermez. 2 Verse bile yabancılar yutacak onu.'),
(2005496,68,28,8,8,'‹‹Yutuldu İsrail, 2 Şimdi uluslar arasında kimsenin beğenmediği bir kap gibi.'),
(2005497,68,28,8,9,'Tek başına dolaşan yaban eşeği gibi Asura gittiler, 2 Efrayim ücretli oynaşlar tuttu.'),
(2005498,68,28,8,10,'Uluslar arasında oynaşlar tutsalar da, 2 Şimdi onları bir araya toplayacağım. 2 Çünkü azalmaya başladılar güçlü kralın baskısı altında.'),
(2005499,68,28,8,11,'‹‹Efrayim günah sunusu sunmak için çok sunak yaptı, 2 Bunlar günah işlemelerine neden oldu.'),
(2005500,68,28,8,12,'Yasamdaki pek çok şeyi onlar için yazdım, 2 Ne var ki garipsediler bunları.'),
(2005501,68,28,8,13,'Bana sundukları kurbanlara gelince, 2 Kurban kesiyor, eti kendileri yiyorlar; 2 Oysa RAB bunu yapanlardan hoşlanmaz. 2 Şimdi anımsayacak suçlarını, 2 Günahları için onları cezalandıracak; 2 Geri dönecekler Mısıra.'),
(2005502,68,28,8,14,'Çünkü İsrail Yaratıcısı''nı unuttu, 2 Saraylar yaptı; 2 Yahuda''ysa birçok kenti surlarla çevirdi, 2 Ama ateş göndereceğim kentlerinin üstüne, 2 Yiyip bitirsin kalelerini.››'),
(2005503,68,28,9,1,'Ey İsrail, öteki halklar gibi sevinme, coşma! 2 Çünkü kendi Tanrına vefasızlık ederek zina ettin, 2 Harman yerlerinin tümünde zina kazancına gönül verdin.'),
(2005504,68,28,9,2,'Ama harman yeri, şarap teknesi halkı doyurmayacak, 2 Yeni şarap umutları boşa çıkacak.'),
(2005505,68,28,9,3,'RABbin diyarında kalmayacaklar, 2 Mısıra dönecek Efrayim, 2 Asurda kirli sayılan şeyleri yiyecekler.'),
(2005506,68,28,9,4,'RABbe şarap sunuları dökmeyecekler, 2 Onu hoşnut etmeyecek kurbanları. 2 Kurbanları yas yemeğine dönecek, 2 Kirli sayılacak onları yiyenlerin hepsi. 2 Yalnız kendi karınlarını doyuracak yiyecekleri, 2 RABbin Tapınağına girmeyecek.'),
(2005507,68,28,9,5,'Ne yapacaksınız dinsel bayramlarda, 2 RABbin bayram gününde?'),
(2005508,68,28,9,6,'Yıkımdan kaçsalar bile, 2 Mısır bir araya toplayacak onları, 2 Mof gömecek. 2 Değerli gümüş eşyalarını yabanıl otlar saracak, 2 Diken bitecek çadırlarında.'),
(2005509,68,28,9,7,'Onların ceza günleri geldi, 2 Hesap günleri çattı. 2 Bunu bilsin İsrail! 2 Suçunuzun çokluğundan, 2 Düşmanlığınızın büyüklüğü yüzünden, 2 Peygamber aptal, ruhsal insan deli sayıldı.'),
(2005510,68,28,9,8,'Peygamber Tanrımın yanısıra Efrayime gözcülük eder, 2 Ama tuzak kurulmuş bütün yollarına, 2 Düşmanlık var Tanrının Tapınağında.'),
(2005511,68,28,9,9,'Alabildiğine yozlaştılar, 2 Givada olduğu gibi. 2 Tanrı suçlarını anımsayacak, 2 Günahlarının cezasını verecek.'),
(2005512,68,28,9,10,'‹‹İsrail çölde 2 Bir salkım üzüm gibi geldi bana, 2 Atalarıysa incir ağacının ilk ürünü gibi. 2 Ama Baal-Peora geldiklerinde 2 Utanç dolu puta adadılar kendilerini, 2 Sevdikleri şey kadar iğrenç oldular.'),
(2005513,68,28,9,11,'Efrayimin görkemi bir kuş gibi uçup gidecek, 2 Ne doğum ne gebelik olacak, kimse gebe kalmayacak.'),
(2005514,68,28,9,12,'Çocuklarını büyütseler bile, 2 Çocuklarından edeceğim onları, 2 Kimse kalmayıncaya dek; 2 Evet, vay başlarına, 2 Onları terk ettiğimde!'),
(2005515,68,28,9,13,'Efrayimi, Sur Kenti gibi, 2 Güzel bir yere kurulmuş gördüm. 2 Ama Efrayim çocuklarını celladın önüne götürecek.››'),
(2005516,68,28,9,14,'Ya RAB, ver onlara ne vereceksen! 2 Düşük yapan rahimler, sütsüz memeler ver.'),
(2005517,68,28,9,15,'‹‹Gilgaldaki kötülükleri yüzünden, 2 Nefret ettim orada onlardan. 2 İşledikleri günahlardan ötürü, 2 Onları evimden kovacağım. 2 Artık sevmeyeceğim onları, 2 Bütün önderleri asidir.'),
(2005518,68,28,9,16,'Vuruldu Efrayim, 2 Kökleri kurudu, 2 Meyve vermeyecekler artık. 2 Çocuk doğursalar bile, 2 Rahimlerinin değerli meyvelerini öldüreceğim.››'),
(2005519,68,28,9,17,'Reddedecek Tanrım onları, 2 Çünkü O''nu dinlemediler, 2 Uluslar arasında dolaşıp duracaklar.'),
(2005520,68,28,10,1,'İsrail serpilen bir asmaya benzer, 2 Meyvesini veriyor. 2 Meyvesi arttıkça, 2 Sunakları da arttı. 2 Ülkesi zenginleştikçe, 2 Onu güzel dikili taşlarla donattı.'),
(2005521,68,28,10,2,'İçleri yalan doldu, 2 Şimdi suçlarının cezasını taşımalılar. 2 RAB sunaklarını yıkacak, 2 Dikili taşlarını yok edecek.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005522,68,28,10,3,'O zaman, ‹‹Kralsız kaldık›› diyecekler, 2 ‹‹Çünkü RABden korkmadık. 2 Kralımız olsa bile, 2 Ne yapabilirdi bize?››'),
(2005523,68,28,10,4,'Antlaşma yaparken, 2 Boş sözler veriyor, yalan yere ant içiyorlar, 2 Bu yüzden davalar, sürülmüş tarladaki zehirli ot gibi boy veriyor.'),
(2005524,68,28,10,5,'Samiriyede yaşayanlar 2 Beytavendeki inek putu yüzünden korkuya kapılacak. 2 Halkı onun ardından yas tutacak, 2 Onun görkemiyle coşan putperest kâhinler 2 Oradan sürgün edildiği için dövünecek.'),
(2005525,68,28,10,6,'Put armağan olarak büyük krala, Asura götürülecek. 2 Efrayim rezil olacak, 2 İsrail aldığı öğütten utanacak.'),
(2005526,68,28,10,7,'Samiriye, Kralıyla birlikte 2 Su üstündeki çubuk gibi akıp gidecek.'),
(2005527,68,28,10,8,'İsrailin günahı olan Avendeki puta tapılan yerler yok olacak, 2 Sunaklarını dikenler, devedikenleri saracak. 2 O zaman dağlara, ‹‹Bizi örtün!››, 2 Tepelere, ‹‹Üzerimize düşün!›› diyecekler.'),
(2005528,68,28,10,9,'‹‹Ey İsrail, Givada geçirdiğin günlerden beri 2 Günah işledin. 2 Orada direndiniz bana. 2 Kötülere karşı açılan savaş 2 Givada size erişemez mi?'),
(2005529,68,28,10,10,'İstediğim zaman onları cezalandıracağım, 2 Çifte günahlarına bağlandıkları zaman, 2 Uluslar toplanacak onlara karşı.'),
(2005530,68,28,10,11,'Efrayim eğitilmiş ineğe benzer, 2 Buğday dövmeyi sever. 2 Ama ben boyunduruk takacağım onun güzel boynuna. 2 Koşum vuracağım Efrayimin sırtına, 2 Yahuda çift sürecek, 2 Yakup tırmık çekecek.'),
(2005531,68,28,10,12,'Doğruluk ekin kendiniz için, 2 Sevgi meyveleri biçin. 2 Nadasa bıraktığınız toprağı işleyin; 2 Çünkü RABbe yönelme zamanıdır, 2 Gelip üzerinize doğruluk yağdırıncaya dek.'),
(2005532,68,28,10,13,'Ama siz kötülük ektiniz, 2 Fesat biçtiniz, 2 Yalanın meyvesini yediniz. 2 Çünkü kendi yolunuza, 2 Yiğitlerinizin çokluğuna güvendiniz.'),
(2005533,68,28,10,14,'Bu yüzden halkınızın arasında savaş uğultusu çıkacak, 2 Yıkılacak bütün surlarınız, 2 Şalmanın savaşta Beytarveli yıktığı gibi. 2 Anneler çocuklarıyla birlikte yere çalınıp parçalandı.'),
(2005534,68,28,10,15,'Ey Beytel, sana da aynısı yapılacak, 2 Kötülüğünün büyüklüğü yüzünden. 2 Tan ağarırken İsrail Kralı büsbütün yok olacak.'),
(2005535,68,28,11,1,'‹‹Çocukluğunda sevdim İsraili, 2 Oğlumu Mısırdan çağırdım.'),
(2005536,68,28,11,2,'Peygamberler İsraili çağırdıkça, 2 İsrail uzaklaştı onlardan. 2 Kurban kestiler Baallara, 2 Buhur yaktılar putlara.'),
(2005537,68,28,11,3,'Efrayime yürümeyi ben öğrettim, 2 Kollarıma aldım onları. 2 Ama kendilerine şifa verenin ben olduğumu anlamadılar.'),
(2005538,68,28,11,4,'Onları insancıl iplerle, 2 Sevgi bağlarıyla kendime çektim; 2 Boyunduruklarını kaldıran biri gibi oldum, 2 Eğilip yiyeceklerini verdim.'),
(2005539,68,28,11,5,'‹‹Mısıra dönmeyecekler, 2 Asur kral olacak başlarına, 2 Çünkü bana dönmek istemediler.'),
(2005540,68,28,11,6,'Fırıl fırıl kılıç dönecek kentlerinde, 2 Kapı sürgülerini yok edecek, 2 Tüketecek onları düzenleri yüzünden.'),
(2005541,68,28,11,7,'Halkım benden uzaklaşmaya kararlı. 2 Beni, Yüce Olanı çağırsalar bile, 2 Asla yüceltmeyeceğim onları.'),
(2005542,68,28,11,8,'‹‹Nasıl vazgeçerim senden, ey Efrayim? 2 Nasıl teslim ederim seni, ey İsrail? 2 Admaya yaptığımı nasıl sana yaparım? 2 Seni nasıl Sevoyime çeviririm? 2 Yüreğim değişti içimde, 2 Alevlendi acıma duygularım.'),
(2005543,68,28,11,9,'Kızgın öfkemi başınıza yağdırmayacağım, 2 Efrayimi yeniden yok etmeyeceğim. 2 Çünkü ben insan değil, Tanrıyım, 2 Kutsal Olanım aranızda, 2 Artık öfkeyle üzerinize varmayacağım.'),
(2005544,68,28,11,10,'Aslan gibi kükreyen 2 RABbin ardınca yürüyecekler; 2 O kükreyince titreyerek gelecek çocukları batıdan.'),
(2005545,68,28,11,11,'Mısırdan kuşlar gibi, 2 Asurdan güvercinler gibi 2 Titreyerek gelecekler. 2 Evlerine oturtacağım onları›› 2 Diyor RAB.'),
(2005546,68,28,11,12,'Efrayim yalanla, 2 İsrail halkı hileyle çevremi sardı. 2 Yahuda''ysa hâlâ dizginsiz, 2 Tanrı''ya, Kutsal ve Sadık Olan''a karşı.'),
(2005547,68,28,12,1,'Efrayim rüzgarı güdüyor, 2 Doğu rüzgarının ardına düşüyor bütün gün; 2 Yalanı, zorbalığı artıyor. 2 Asurla antlaşma yapıyor, 2 Mısıra zeytinyağı gönderiyor.'),
(2005548,68,28,12,2,'RABbin davası var Yahudayla, 2 Yakup soyunu izlediği yola göre cezalandıracak, 2 Yaptıklarının karşılığını verecek.'),
(2005549,68,28,12,3,'Yakup ana rahminde kardeşinin topuğunu tuttu, 2 Büyüyünce Tanrıyla güreşti.'),
(2005550,68,28,12,4,'Melekle güreşip yendi, 2 Ağladı, kutsanmak istedi. 2 Tanrıyı Beytelde buldu, 2 RAB, Her Şeye Egemen Tanrı bizimle orada konuştu, 2 O RAB diye anılır.'),
(2005551,68,28,12,6,'Bu yüzden Tanrına dön sen, 2 Sevgiye, adalete sarıl, 2 Sürekli Tanrını bekle.'),
(2005552,68,28,12,7,'Efrayim tüccardır, 2 Hileli terazi kullanır, 2 Aldatmayı sever.'),
(2005553,68,28,12,8,'‹‹Çok zengin oldum›› diye böbürlenir, 2 ‹‹Varlığa kavuştum, 2 Çok emek çektim, 2 Günah denecek bir suç bulamayacaklar bende.››'),
(2005554,68,28,12,9,'‹‹Ama seni Mısırdan çıkaran 2 Tanrın RAB benim. 2 Bayram günlerindeki gibi, 2 Seni yine çadırlarda oturtacağım.'),
(2005555,68,28,12,10,'Peygamberlere de söyledim, 2 Çok görümler sağladım, 2 Onlar aracılığıyla örnekler verdim.››'),
(2005556,68,28,12,11,'Kötülük mü var Gilatta? 2 Gerçekten değersiz bir halk! 2 Gilgalda sığır üstüne sığır kurban ediyorlar, 2 Sunakları sürülmüş tarladaki taş yığınlarını andırıyor.'),
(2005557,68,28,12,12,'Yakup Arama kaçtı, 2 İsrail bir karı için kul oldu, 2 Koyun güttü.'),
(2005558,68,28,12,13,'RAB İsraili bir peygamber aracılığıyla Mısırdan çıkardı, 2 Yine bir peygamber korudu onları.'),
(2005559,68,28,12,14,'Ama Efrayim Tanrı''yı aşırı öfkelendirdi. 2 Rab döktükleri kanın hesabını soracak, 2 Aşağılamalarının karşılığını verecek.'),
(2005560,68,28,13,1,'Efrayim konuştuğunda herkes titrerdi, 2 Yücelmişti İsrailde. 2 Ama Baala taparak suç işleyince öldü.'),
(2005561,68,28,13,2,'Şimdi günah üstüne günah işliyorlar, 2 Gümüşlerinden dökme putlar, 2 Akıllıca tasarlanmış putlar yapıyorlar, 2 Hepsi de usta işi. 2 Bu insanlar hakkında, 2 ‹‹İnsan kurban edenler 2 Buzağıları öpüyor!›› diye konuşuluyor.'),
(2005562,68,28,13,3,'Bu yüzden sabah sisine, 2 Erken uçup giden çiye, 2 Harman yerinden savrulan saman çöpüne, 2 Bacadan tüten dumana dönecekler.'),
(2005563,68,28,13,4,'‹‹Ama seni Mısırdan çıkaran 2 Tanrın RAB benim, 2 Benden başka tanrı tanımayacaksın, 2 Çünkü başka kurtarıcı yoktur.'),
(2005564,68,28,13,5,'Ben sana çölde, 2 Kurak topraklarda göz kulak oldum.'),
(2005565,68,28,13,6,'Otlaklara sahip olunca doydular, 2 Doyunca gurura kapıldılar; 2 Bu yüzden unuttular beni.'),
(2005566,68,28,13,7,'Ben de onlara karşı bir aslan gibi olacağım, 2 Bir pars gibi yol kenarında pusuya yatacağım.'),
(2005567,68,28,13,8,'Yavrularından edilmiş dişi ayı gibi 2 Karşılarına çıkacak, 2 Yüreklerinin zarını yırtacağım, 2 Dişi aslan gibi onları oracıkta yiyip bitireceğim, 2 Yabanıl bir hayvan parçalayacak onları.'),
(2005568,68,28,13,9,'‹‹Ey İsrail, bana, yardımcına karşı çıkman 2 Yıkıma uğratıyor seni.'),
(2005569,68,28,13,10,'Nerede seni bütün kentlerinde 2 Kurtaracak kralın? 2 Yöneticilerin nerede? 2 Hani, onlar için: 2 ‹Bana bir kral ve önderler ver!› demiştin.'),
(2005570,68,28,13,11,'Öfkelendiğimde bir kral verdim sana, 2 Gazaba gelince alıp götürdüm onu.'),
(2005571,68,28,13,12,'Efrayimin suçu birikmiş, 2 Günahı kayda geçmiş.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005572,68,28,13,13,'Doğum sancıları çeken kadının akılsız oğludur o, 2 Çünkü zamanı geldiğinde, 2 Açık rahimden çıkmıyor.'),
(2005573,68,28,13,14,'‹‹Onları fidyeyle kurtaracağım 2 Ölüler diyarının elinden, 2 Ölümden fidyeyle kurtaracağım. 2 Felaketin nerede, ey ölüm? 2 Yıkıcılığın nerede, ey ölüler diyarı? 2 Hiç pişmanlık duymayacağım.'),
(2005574,68,28,13,15,'‹‹Kardeşleri arasında serpilip gelişse de, 2 Doğu rüzgarı, çölden esen RABbin soluğu üzerine gelecek, 2 Onun kaynağı kuruyacak, 2 Pınarı kesilecek, 2 Değerli eşyalarının hazinesi yağmalanacak.'),
(2005575,68,28,13,16,'Samiriye halkı suçunun cezasını çekecek, 2 Çünkü Tanrısı''na başkaldırdı. 2 Kılıçla yıkılacaklar, 2 Yere çalınıp parçalanacak yavruları, 2 Gebe kadınlarının karnı yarılacak.››'),
(2005576,68,28,14,1,'Tanrın RABbe dön, ey İsrail, 2 Çünkü suçlarından ötürü tökezledin.'),
(2005577,68,28,14,2,'Dualarla gidin, RABbe dönün, 2 Ona, ‹‹Bağışla bütün suçlarımızı›› deyin, 2 ‹‹Lütfet, kabul et bizi, 2 Öyle ki, dudaklarımızın kurbanını sunalım.'),
(2005578,68,28,14,3,'Asur kurtaramaz bizi, 2 Savaş atlarına binmeyeceğiz. 2 Artık ellerimizle yaptığımıza 2 ‹Tanrımız› demeyeceğiz, 2 Çünkü öksüz sende merhamet bulur.››'),
(2005579,68,28,14,4,'‹‹Onların dönekliğini düzelteceğim, 2 Gönülden seveceğim onları, 2 Çünkü onlara karşı öfkem dindi.'),
(2005580,68,28,14,5,'Çiy gibi olacağım İsraile; 2 Zambak gibi çiçek açacak, 2 Lübnan sediri gibi kök salacaklar.'),
(2005581,68,28,14,6,'Dallanıp budaklanacaklar, 2 Görkemleri zeytin ağacını, 2 Kokuları Lübnan sedirini andıracak.'),
(2005582,68,28,14,7,'Yine insanlar oturacak gölgesinde; 2 Buğday gibi gelişecek, 2 Asma gibi serpilecekler; 2 Lübnan şarabı kadar ün kazanacaklar.'),
(2005583,68,28,14,8,'Ey Efrayim, artık ne işim var putlarla? 2 Yanıtlayacak, seninle ilgileneceğim. 2 Yeşil çam gibiyim ben, 2 Senin verimliliğin benden kaynaklanıyor.››'),
(2005584,68,28,14,9,'Bilge kişi kavrasın bunları, 2 Anlayan anlasın. 2 Çünkü RAB''bin yolları adildir; 2 Bu yollarda yürür doğrular, 2 Ama başkaldıranlar bu yollarda sendeler.'),
(2005585,68,29,1,1,'RABbin Petuel oğlu Yoele bildirdikleri.'),
(2005586,68,29,1,2,'Ey yaşlılar, dinleyin, 2 Ülkede yaşayan herkes, kulak verin: Sizin zamanınızda ya da atalarınızın zamanında 2 Hiç böyle bir şey oldu mu?'),
(2005587,68,29,1,3,'Bunu çocuklarınıza anlatın; 2 Çocuklarınız kendi çocuklarına, Onların çocukları da bir sonraki kuşağa anlatsınlar.'),
(2005588,68,29,1,4,'Genç çekirgeden artakalan ürünü olgunlaşmış çekirge yedi, 2 Ondan artakalanı yumurtadan yeni çıkan çekirge yedi; Ondan artakalanı da yavru çekirgeler yedi.'),
(2005589,68,29,1,5,'Ey sarhoşlar, ayılın ve ağlayın. 2 Ey şarap düşkünleri, tatlı şarap için ağıt yakın. Çünkü şarabınızı ağzınızdan kaptılar.'),
(2005590,68,29,1,6,'Güçlü ve sayılamayacak kadar büyük bir çekirge ordusu saldırdı ülkeme. 2 Aslan dişine benzer, Dişi aslanın kesici dişlerine benzer dişleri var.'),
(2005591,68,29,1,7,'Asmalarımı harap ettiler, 2 İncir ağaçlarımı mahvettiler, Kabuklarını soyup yere attılar. 2 Soyulan dallar bembeyaz.'),
(2005592,68,29,1,8,'Sözlüsünü yitirip çul kuşanan bir genç kız gibi yas tutun.'),
(2005593,68,29,1,9,'RABbin Tapınağına götürülecek 2 Tahıl ve şarap sunusu yok artık. RABbe hizmet eden kâhinler yas tutuyorlar.'),
(2005594,68,29,1,10,'Tarlalar harap oldu, toprak acılı. 2 Çünkü tahıl mahvoldu, Yeni şarap tükendi, zeytinyağı kesildi.'),
(2005595,68,29,1,11,'Arpa, buğday için dövünün, ey ırgatlar, 2 Ağıt yakın, ey bağcılar, Çünkü tarlaların ürünü yok oldu.'),
(2005596,68,29,1,12,'Asmalar kurudu, incir ağaçları soldu; 2 Nar, hurma, elma, bütün meyve ağaçları kurudu. İnsanoğlunun sevinci yok oldu.'),
(2005597,68,29,1,13,'Ey kâhinler, çul kuşanıp yas tutun. 2 Ey sunakta hizmet edenler, ağıt yakın, Ey Tanrımın hizmetkârları, tapınağa gelin, 2 Çul içinde geceleyin. Çünkü Tanrınızın Tapınağı için 2 Tahıl ve şarap sunusu kalmadı.'),
(2005598,68,29,1,14,'Oruç için gün belirleyin, özel bir toplantı yapın; 2 Yaşlıları ve ülkede yaşayanların tümünü Tanrınız RABbin Tapınağına toplayıp RABbe yakarın.'),
(2005599,68,29,1,15,'Eyvahlar olsun! Çünkü RABbin günü yakındır. 2 Her Şeye Gücü Yetenin göndereceği yıkım gibi geliyor o gün.'),
(2005600,68,29,1,16,'Yiyeceğimiz gözümüzün önünde yok edildi. 2 Tanrımızın Tapınağında sevinç ve coşku sona erdi.'),
(2005601,68,29,1,17,'Tohumlar keseklerin altında çürüdü, 2 Tahıl yok oldu, Ambarlar boş kaldı, depolar yıkıldı.'),
(2005602,68,29,1,18,'Hayvanlar nasıl da inliyor! 2 Sığır sürüleri çaresiz. Çünkü otlaklar kurudu. 2 Koyun sürüleri perişan oldu.'),
(2005603,68,29,1,19,'Ya RAB, sana yakarıyorum. 2 Çünkü ateş otlakları yok etti, Bütün ağaçları kavurdu.'),
(2005604,68,29,1,20,'Yabanıl hayvanlar bile sana sesleniyor. 2 Çünkü akarsular kurudu, Ateş otlakları yok etti.'),
(2005605,68,29,2,1,'Siyonda boru çalın, 2 Kutsal dağımda boru sesiyle halkı uyarın. Ülkede yaşayan herkes korkudan titresin. 2 Çünkü RABbin günü çok yaklaştı, geliyor.'),
(2005606,68,29,2,2,'Zifiri karanlık bir gün olacak, 2 Bulutlu, koyu karanlık bir gün. Dağların üzerine çöken karanlık gibi 2 Kalabalık ve güçlü bir çekirge ordusu geliyor. Böylesi hiçbir zaman görülmedi, 2 Kuşaklar boyu da görülmeyecek. geçiyor.'),
(2005607,68,29,2,3,'Önlerini ateş kavuruyor, 2 Artları alev alev. Önlerinde Aden bahçesi gibi uzanan topraklar 2 Artlarında ıssız çöllere dönüyor. Hiçbir şey onlardan kurtulamıyor.'),
(2005608,68,29,2,4,'Atlara benziyorlar, 2 Savaş atları gibi koşuyorlar.'),
(2005609,68,29,2,5,'Savaş arabalarının, anızı yiyip bitiren alevlerin 2 Çıkardığı gürültüye benzer bir sesle, Savaşa hazırlanmış güçlü bir ordu gibi 2 Sıçraya sıçraya dağları aşıyorlar.'),
(2005610,68,29,2,6,'Uluslar onların karşısında dehşete düşüyor; 2 Herkesin beti benzi soluyor.'),
(2005611,68,29,2,7,'Yiğitler gibi saldırıyorlar, 2 Askerler gibi surları aşıyorlar. Dosdoğru ilerliyorlar, 2 Yollarından sapmadan.'),
(2005612,68,29,2,8,'İtişip kakışmadan, 2 Her biri kendi yolundan yürüyor. Savunma hatlarını yarıp geçiyorlar, 2 Sırayı bozmadan.'),
(2005613,68,29,2,9,'Kente doğru koşuşuyor, 2 Surların üzerinden aşıyorlar. Evlere tırmanıyor ve hırsız gibi 2 Pencerelerden içeri süzülüyorlar.'),
(2005614,68,29,2,10,'Yeryüzü önlerinde sarsılıyor, 2 Gökyüzü titriyor; Güneş ve ay kararıyor, 2 Yıldızların parıltısı görünmez oluyor.'),
(2005615,68,29,2,11,'RAB ordusunun başında gürlüyor. 2 Sayısızdır Onun orduları Ve buyruğuna uyan güçlüdür. 2 RABbin o büyük günü ne korkunçtur! O güne kim dayanabilir?'),
(2005616,68,29,2,12,'RAB diyor ki, 2 ‹‹Şimdi oruç tutarak, ağlayıp yas tutarak Bütün yüreğinizle bana dönün.'),
(2005617,68,29,2,13,'Giysilerinizi değil, 2 Yüreklerinizi paralayın Ve Tanrınız RABbe dönün. 2 Çünkü RAB lütfeder, acır, Tez öfkelenmez, sevgisi engindir, 2 Cezalandırmaktan vazgeçer.'),
(2005618,68,29,2,14,'Kim bilir, belki size acır da kararından döner. 2 Ardında bereket bırakır. O zaman Ona tahıl ve şarap sunuları sunarsınız.'),
(2005619,68,29,2,15,'‹‹Siyonda boru çalın, 2 Oruç için gün belirleyin, özel bir toplantı yapın.'),
(2005620,68,29,2,16,'Halkı toplayın, topluluğu kutsal kılın, 2 Yaşlıları bir araya getirin. Çocukları, hatta emzikte olanları toplayın. 2 Güvey odasından, gelin gerdeğinden çıkıp gelsin.'),
(2005621,68,29,2,17,'Kâhinler, RABbin hizmetkârları, 2 Tapınağın girişiyle sunak arasında ağlaşıp, ‹Ya RAB, halkını esirge› diye yalvarsınlar. 2 ‹Mirasın olan halkının aşağılanmasına izin verme, Uluslar onunla alay etmesin. 2 Halklar arasında neden, Onların Tanrısı nerede? densin?› ››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005622,68,29,2,18,'O zaman RAB halkına acıyıp ülkesini esirgeyecek.'),
(2005623,68,29,2,19,'Halkına şöyle yanıt verecek: 2 ‹‹Bakın, size tahıl, yeni şarap Ve zeytinyağı vereceğim, 2 Bunlara doyacaksınız. Artık ulusların sizi aşağılamasına izin vermeyeceğim.'),
(2005624,68,29,2,20,'Kuzeyden gelen çekirge ordusunu sizden uzaklaştıracağım, 2 Kurak ve ıssız bir ülkeye süreceğim. Önden gidenleri Lut Gölüne, 2 Arkadan gelenleri Akdenize süreceğim. Leşleri kokacak, 2 Kokuları göklere yükselecek. Çünkü korkunç şeyler yaptılar.'),
(2005625,68,29,2,21,'‹‹Ey toprak, korkma, sevinçle coş! 2 Çünkü RAB büyük işler yaptı.'),
(2005626,68,29,2,22,'Ey kır hayvanları, korkmayın! 2 Çünkü otlaklar yeşeriyor. Ağaçlar meyvelerini yükleniyor, 2 İncir ağaçları, asmalar ürünlerini veriyor.'),
(2005627,68,29,2,23,'Ey Siyon halkı, 2 Tanrınız RABde sevinç bulun, coşun. İlk yağmuru size tam ölçüsüyle veriyor; 2 Daha önce olduğu gibi, İlk ve son yağmurları yağdırıyor. geçiyor. doğruluğu öğretecek olan öğretmeni veriyor››.'),
(2005628,68,29,2,24,'Harman yeri tahılla dolacak. 2 Şarap ve zeytinyağı tekneleri taşacak.'),
(2005629,68,29,2,25,'Üzerinize gönderdiğim büyük çekirge ordusunun, 2 Olgunlaşmış ve yumurtadan yeni çıkmış çekirgenin, Yavrunun ve genç çekirgenin 2 Size kaybettirdiği yılları geri vereceğim.'),
(2005630,68,29,2,26,'Bol bol yiyip doyacak 2 Ve sizin için harikalar yaratan Tanrınız RABbin adını öveceksiniz. 2 Halkım bir daha utandırılmayacak.'),
(2005631,68,29,2,27,'Bileceksiniz ki, İsrail halkının arasındayım, 2 Tanrınız RAB benim, başka biri yok. Halkım bir daha utandırılmayacak.››'),
(2005632,68,29,2,28,'‹‹Ondan sonra bütün insanların üzerine 2 Ruhumu dökeceğim. Oğullarınız, kızlarınız peygamberlikte bulunacaklar. 2 Yaşlılarınız düşler, Gençleriniz görümler görecek.'),
(2005633,68,29,2,29,'O günler kadın, erkek kullarınızın üzerine de Ruhumu dökeceğim.'),
(2005634,68,29,2,30,'Göklerde ve yeryüzünde, 2 Kan, ateş ve duman sütunlarından belirtiler göstereceğim.'),
(2005635,68,29,2,31,'RABbin büyük ve korkunç günü gelmeden önce 2 Güneş kararacak, ay kan rengine dönecek.'),
(2005636,68,29,2,32,'O zaman RAB''bi adıyla çağıran herkes kurtulacak. 2 RAB''bin dediği gibi, Siyon Dağı''nda ve Yeruşalim''de kurtulup 2 Sağ kalanlar arasında RAB''bin çağıracağı kimseler olacak.››'),
(2005637,68,29,3,1,'‹‹O günler Yahuda ve Yeruşalim halkını 2 Sürgünden geri getirdiğimde,'),
(2005638,68,29,3,2,'Bütün ulusları toplayıp 2 Yehoşafatfç Vadisine indireceğim. Mirasım olan İsrail halkını 2 Uluslar arasına dağıttıkları ve ülkemi bölüştükleri için Onları orada yargılayacağım.'),
(2005639,68,29,3,3,'Çünkü halkım için kura çektiler, 2 Erkek çocukları fahişelere ücret olarak verdiler. İçtikleri şaraba karşılık kızları sattılar.'),
(2005640,68,29,3,4,'Ey Sur, Sayda ve bütün Filist halkı, 2 Bana yapmak istediğiniz nedir? Neye karşılık vermeye çalışıyorsunuz? 2 Eğer karşılık verirseniz, Karşılığını çarçabuk ödetirim size.'),
(2005641,68,29,3,5,'Altınımı, gümüşümü alıp 2 Değerli eşyalarımı tapınaklarınıza götürdünüz.'),
(2005642,68,29,3,6,'Yahuda ve Yeruşalim halkını 2 Topraklarından uzaklaştırmak için Greklere sattınız.'),
(2005643,68,29,3,7,'Göreceksiniz, onları, sattığınız yerde 2 Harekete geçireceğim. Onlara yaptığınızı kendi başınıza getireceğim.'),
(2005644,68,29,3,8,'Oğullarınızı, kızlarınızı 2 Yahuda halkına sattıracağım. Onları uzak bir ulusa, Sabalılara satacaklar.›› 2 RAB böyle diyor.'),
(2005645,68,29,3,9,'‹‹Uluslar arasında şunu duyurun: 2 Savaşa hazırlanın, yiğitlerinizi harekete geçirin. Bütün savaşçılarınız toplanıp saldırıya geçsin.'),
(2005646,68,29,3,10,'Saban demirlerinizi 2 Çekiçle dövüp kılıç yapın, Bağcı bıçaklarınızı mızrak yapın. 2 Güçsüz olan ‹Güçlüyüm› desin.'),
(2005647,68,29,3,11,'Ey çevredeki uluslar, 2 Tez gelin, bir araya toplanın. Ya RAB, yiğitlerini oraya indir.'),
(2005648,68,29,3,12,'Uluslar harekete geçip 2 Yehoşafat Vadisinde toplansınlar. Çünkü çevredeki bütün ulusları 2 Yargılamak için orada olacağım.'),
(2005649,68,29,3,13,'Salın orakları, ekinler olgunlaştı. Gelin, üzümleri çiğneyin, 2 Sıkma çukuru üzümle dolu, şarap tekneleri taşıyor. Ulusların kötülükleri bu denli çoktur.››'),
(2005650,68,29,3,14,'Kalabalıklar, 2 Yargı vadisini dolduran nice kalabalıklar... Yargı vadisinde RABbin günü yaklaştı.'),
(2005651,68,29,3,15,'Güneş ve ay kararıyor, 2 Yıldızların parıltısı görünmez oluyor.'),
(2005652,68,29,3,16,'RAB Siyondan kükreyecek, 2 Yeruşalimden gürleyecek. Gök ve yer sarsılacak. 2 Ama RAB kendi halkı için sığınak, İsrailliler için kale olacak.'),
(2005653,68,29,3,17,'‹‹O zaman bileceksiniz ki, 2 Siyonda, kutsal dağımda oturan Tanrınız RAB benim. Yeruşalim kutsal olacak; 2 Yabancılar bir daha orayı ele geçiremeyecek.'),
(2005654,68,29,3,18,'‹‹O gün dağlardan 2 Tatlı şarap damlayacak; Tepelerde süt, 2 Yahuda derelerinde su akacak. RABbin Tapınağından çıkan bir pınar 2 Şittim Vadisini sulayacak.'),
(2005655,68,29,3,19,'‹‹Ama Mısır viraneye, 2 Edom ıssız çöle dönecek. Çünkü Yahudalıların ülkesine saldırıp 2 Suçsuz insanların kanını döktüler.'),
(2005656,68,29,3,20,'Oysa Yahuda sonsuza dek yaşayacak. 2 Yeruşalim kuşaktan kuşağa sürecek.'),
(2005657,68,29,3,21,'Akan kanların öcünü alacağım, 2 Suçluyu cezasız bırakmayacağım.›› Masoretik metin ‹‹Akan kanları cezasız bırakacağım››. RAB Siyon''da oturur.'),
(2005658,68,30,1,1,'Tekoalı koyun yetiştiricilerinden Amosun sözleri. Uzziyanın Yahuda, Yehoaş oğlu Yarovamın İsrail Kralı olduğu günlerde, depremden iki yıl önce Amos İsraille ilgili görümler gördü.'),
(2005659,68,30,1,2,'Şöyle dedi: ‹‹RAB Siyondan kükrüyor, 2 Yeruşalimden gürlüyor. 2 Yas tutuyor çobanların otlakları, 2 Karmel Dağının dorukları kuruyor.››'),
(2005660,68,30,1,3,'RAB şöyle diyor: 2 ‹‹Şamlıların cezasını kaldırmayacağım. 2 Çünkü günah üstüne günah işlediler, 2 Demir düvenlerle Gilat halkını dövdüler.'),
(2005661,68,30,1,4,'Bu yüzden Hazaelin evine ateş yağdıracağım, 2 Yakıp yok edecek Ben-Hadatın saraylarını.'),
(2005662,68,30,1,5,'Şamın kapı sürgüsünü kıracağım, 2 Söküp atacağım 2 Aven Vadisinde oturanı, 2 Beytedende elinde asayla dolaşanı; 2 Kîre sürgün edilecek Aram halkı.›› 2 RAB diyor.'),
(2005663,68,30,1,6,'RAB şöyle diyor: 2 ‹‹Gazzelilerin cezasını kaldırmayacağım. 2 Çünkü günah üstüne günah işlediler, 2 Edomlulara teslim etmek için 2 Bütün halkı sürgün ettiler.'),
(2005664,68,30,1,7,'Bu yüzden Gazze surlarına ateş yağdıracağım, 2 Yakıp yok edecek saraylarını.'),
(2005665,68,30,1,8,'Söküp atacağım 2 Aşdotta oturanı, 2 Aşkelonda elinde asayla dolaşanı, 2 Elimin tersini göstereceğim Ekrona, 2 Yok olacak Filistlilerin sağ kalanları!›› 2 Egemen RAB böyle diyor.'),
(2005666,68,30,1,9,'RAB şöyle diyor: 2 ‹‹Surluların cezasını kaldırmayacağım. 2 Çünkü günah üstüne günah işlediler, 2 Bütün halkı Edomlulara teslim edip sürdüler, 2 Dostluk antlaşmasını anımsamadılar.'),
(2005667,68,30,1,10,'Bu yüzden Sur Kentinin surlarına ateş yağdıracağım, 2 Yakıp yok edecek saraylarını.››'),
(2005668,68,30,1,11,'RAB şöyle diyor: 2 ‹‹Edomluların cezasını kaldırmayacağım. 2 Çünkü günah üstüne günah işlediler, 2 Kılıçla kovaladılar kardeşlerini, 2 Acıma nedir bilmediler; 2 Hep yırtıcıydı öfkeleri, 2 Sonsuza dek sürdü gazapları.'),
(2005669,68,30,1,12,'Bu yüzden Temana ateş yağdıracağım, 2 Yakıp yok edecek Bosra saraylarını.››'),
(2005670,68,30,1,13,'RAB şöyle diyor: 2 ‹‹Ammonluların cezasını kaldırmayacağım. 2 Çünkü günah üstüne günah işlediler, 2 Sınırlarını genişletmek için 2 Gilatlı gebe kadınların karınlarını yardılar.'),
(2005671,68,30,1,14,'Bu yüzden Rabba surlarını tutuşturacağım, 2 Savaş günü çığlıklarla, 2 Kasırga günü fırtınayla 2 Ateş yakıp yok edecek saraylarını.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005672,68,30,1,15,'Krallarıyla görevlileri, 2 Hepsi sürgüne gidecek.›› 2 RAB böyle diyor.'),
(2005673,68,30,2,1,'RAB şöyle diyor: 2 ‹‹Moavlıların cezasını kaldırmayacağım. 2 Çünkü günah üstüne günah işlediler, 2 Edom Kralının kemiklerini 2 Kireçleşinceye dek yaktılar.'),
(2005674,68,30,2,2,'Bu yüzden Moava ateş yağdıracağım, 2 Yakıp yok edecek Keriyot saraylarını. 2 Kargaşa, savaş naraları, 2 Boru sesleri arasında ölecek Moav halkı.'),
(2005675,68,30,2,3,'Söküp atacağım içinden yöneticisini, 2 Öldüreceğim onunla bütün görevlilerini.›› 2 RAB böyle diyor.'),
(2005676,68,30,2,4,'RAB şöyle diyor: 2 ‹‹Yahudalıların cezasını kaldırmayacağım. 2 Çünkü günah üstüne günah işlediler, 2 Reddettiler yasamı, 2 Kurallarıma uymadılar; 2 Yalancı putlar saptırdı onları, 2 Atalarının da izlediği putlar.'),
(2005677,68,30,2,5,'Bu yüzden Yahudaya ateş yağdıracağım, 2 Yakıp yok edecek Yeruşalim saraylarını.››'),
(2005678,68,30,2,6,'RAB şöyle diyor: 2 ‹‹İsraillilerin cezasını kaldırmayacağım, 2 Çünkü günah üstüne günah işlediler, 2 Doğruyu para için, 2 Yoksulu bir çift çarık için sattılar.'),
(2005679,68,30,2,7,'Onlar ki, 2 Yoksulun başını toz toprak içinde çiğner 2 Ve mazlumun hakkını bir yana iterler. 2 Baba oğul aynı kızla yatarak 2 Kutsal adımı kirletirler.'),
(2005680,68,30,2,8,'Her sunağın yanına, 2 Rehin alınan giysilerin üzerine uzanır, 2 Tanrılarının Tapınağında 2 Ceza karşılığı alınan şarabı içerler.'),
(2005681,68,30,2,9,'Ama ben onların önünde 2 Amorluları yok ettim; 2 Sedir ağaçları kadar boylu, 2 Meşe kadar güçlü olsa da, 2 Yukarıdan meyvesini, 2 Aşağıdan kökünü kuruttum.'),
(2005682,68,30,2,10,'Sizi Mısırdan ben çıkardım, 2 Amor topraklarını sahiplenesiniz diye 2 Çölde kırk yıl size yol gösterdim.'),
(2005683,68,30,2,11,'Oğullarınızdan peygamberler, 2 Gençlerinizden bana adanmış kişiler atadım. 2 Doğru değil mi, ey İsrailliler?›› 2 RAB böyle diyor.'),
(2005684,68,30,2,12,'‹‹Sizse bana adanmış kişilere şarap içirdiniz 2 Ve peygamberlere, ‹Peygamberlik etmeyin!› 2 Diye buyruk verdiniz.'),
(2005685,68,30,2,13,'‹‹Tahıl yüklü araba toprağı nasıl ezerse, 2 İşte ben de sizi öyle ezeceğim.'),
(2005686,68,30,2,14,'Hızlı koşan kaçamayacak, 2 Güçlü gücünü gösteremeyecek, 2 Yiğit canını kurtaramayacak,'),
(2005687,68,30,2,15,'Okçu yerini koruyamayacak, 2 Ayağı tez olan uzaklaşamayacak, 2 Atlı canını kurtaramayacak,'),
(2005688,68,30,2,16,'En yürekli yiğitler bile 2 O gün silahlarını bırakıp kaçacak.›› 2 RAB böyle diyor.'),
(2005689,68,30,3,1,'Ey İsrailliler, kulak verin RABbin size, Mısırdan çıkardığı halka söylediği şu sözlere:'),
(2005690,68,30,3,2,'‹‹Yeryüzündeki bütün halklar arasından yalnız sizi tanıdım, 2 Bu yüzden suçlarınızı karşılıksız bırakmayacağım.››'),
(2005691,68,30,3,3,'İki kişi anlaşmadan birlikte yürür mü?'),
(2005692,68,30,3,4,'Avı olmayan aslan ormanda kükrer mi? 2 Bir şey yakalamadıkça genç aslan ininde homurdanır mı?'),
(2005693,68,30,3,5,'Tuzak kurulmamışsa, 2 Yerdeki kapana kuş düşer mi? 2 İçine bir şey düşmedikçe 2 Kapan yerden fırlar mı?'),
(2005694,68,30,3,6,'Kentte boru çalınır da halk korkmaz mı? 2 RABbin onayı olmadan bir kentin başına felaket gelir mi?'),
(2005695,68,30,3,7,'Gerçek şu ki, Egemen RAB kulu peygamberlere 2 Sırrını açmadıkça bir şey yapmaz.'),
(2005696,68,30,3,8,'Aslan kükrer de kim korkmaz? 2 Egemen RAB söyler de kim peygamberlik etmez?'),
(2005697,68,30,3,9,'Aşdot ve Mısır saraylarına duyurun: 2 ‹‹Samiriye dağlarında toplanın›› deyin, 2 ‹‹Kentin ortasındaki büyük kargaşayı, 2 İçindeki baskıyı görün.››'),
(2005698,68,30,3,10,'RAB, ‹‹Onlar doğruluk nedir bilmiyorlar›› diyor, 2 ‹‹Saraylarına zorbalık ve çapul yığmışlar.››'),
(2005699,68,30,3,11,'Bu yüzden Egemen RAB diyor ki, 2 ‹‹Düşman kuşatmakta ülkenizi, 2 Saraylarınızı yağmalayacak, güçsüz kılacak sizi.››'),
(2005700,68,30,3,12,'RAB şöyle diyor: 2 ‹‹Bir çoban aslanın ağzındaki hayvanın iki bacağını 2 Ya da kulağının parçasını nasıl kaparsa, 2 Samiriyede sedir köşelerine, 2 Divan yastıklarına 2 Kurulan İsrailliler de öyle kurtarılacak.'),
(2005701,68,30,3,13,'Dinleyin ve Yakup soyunu uyarın.›› 2 Egemen RAB, Her Şeye Egemen Tanrı konuşuyor:'),
(2005702,68,30,3,14,'‹‹İsyanlarından ötürü 2 İsraili cezalandırdığım gün, 2 Beytelin sunaklarını da yok edeceğim. 2 Kesilip yere düşecek sunağın boynuzları.'),
(2005703,68,30,3,15,'Hem kışlık hem yazlık evi vuracağım, 2 Yok olacak fildişi evler, 2 Sonu gelecek büyük evlerin.›› 2 RAB böyle diyor.'),
(2005704,68,30,4,1,'Ey sizler, Samiriye Dağındaki Başan inekleri, 2 Yoksula baskı yapan, 2 Mazlumu ezen, 2 Beylerine, ‹‹Getir de içelim!›› diyen hanımlar! 2 Kulak verin şu sözlere:'),
(2005705,68,30,4,2,'Egemen RAB kutsallığı üstüne ant içerek şöyle dedi: 2 ‹‹İşte geliyor o günler; 2 Sizi et kancalarıyla, 2 En son kalanlarınızı balık çengelleriyle götürecekleri günler.'),
(2005706,68,30,4,3,'Her biriniz karşınızdaki gedikten çıkacak, 2 Harmona atılacaksınız.›› 2 RAB böyle diyor.'),
(2005707,68,30,4,4,'‹‹Beytele gelip günah işleyin, 2 Gilgala gelip daha da günah işleyin! 2 Her sabah kurbanlarınızı, 2 Üç günde bir de ondalıklarınızı getirin.'),
(2005708,68,30,4,5,'Şükran sunusu olarak mayalı ekmek yakın, 2 Gönülden verdiğiniz sunuları açıklayıp duyurun! 2 Çünkü bundan hoşlanıyorsunuz, ey İsrailliler.›› 2 Egemen RAB böyle diyor.'),
(2005709,68,30,4,6,'‹‹Bütün kentlerinizde açlıktan nefesiniz koktu, 2 Bulunduğunuz her yerde size kıtlık verdim, 2 Yine de bana dönmediniz.›› 2 RAB böyle diyor. verdim››.'),
(2005710,68,30,4,7,'‹‹Hasat mevsimine daha üç ay varken, 2 Sizden yağmuru da esirgedim. 2 Bir kente yağmur yağdırdım, 2 Öbürüne yağdırmadım. 2 Bir tarla yağmur aldı, 2 Öteki almayıp kurudu.'),
(2005711,68,30,4,8,'Su bulmak için 2 Kent kent sersemce dolaştınız; 2 Suya doyamadınız, 2 Yine de bana dönmediniz.›› 2 RAB böyle diyor.'),
(2005712,68,30,4,9,'‹‹Samyeli ve küfle sizi cezalandırdım, 2 Mahvettim bağlarınızı, bahçelerinizi, 2 İncir ve zeytin ağaçlarınızı çekirge yedi, 2 Yine de bana dönmediniz.›› 2 RAB böyle diyor.'),
(2005713,68,30,4,10,'‹‹Mısırda olduğu gibi 2 Aranıza salgın hastalık gönderdim, 2 Kılıçtan geçirdim yiğitlerinizi, 2 Atlarınızı düşmanlarınıza verdim, 2 Ordugahınızın pis kokusunu burunlarınıza doldurdum; 2 Yine de bana dönmediniz.›› 2 RAB böyle diyor.'),
(2005714,68,30,4,11,'‹‹Sodom ve Gomorayı altüst ettiğim gibi, 2 Altüst ettim içinizden bazılarını. 2 Ateşten kurtarılan yanık odun parçasına döndünüz, 2 Yine de yönelmediniz bana.›› 2 RAB böyle diyor.'),
(2005715,68,30,4,12,'‹‹Bu yüzden sana şunu yapacağım, ey İsrail. 2 Yapacaklarım için 2 Tanrını karşılamaya hazırlan, ey İsrail!››'),
(2005716,68,30,4,13,'Çünkü dağlara biçim veren, 2 Rüzgarı yaratan, düşüncelerini insana bildiren, 2 Şafağı karanlığa çeviren, 2 Dünyanın yüksek yerlerine ayak basan işte O''dur, 2 O''nun adı RAB, Her Şeye Egemen Tanrı''dır.'),
(2005717,68,30,5,1,'Ey İsrail halkı, kulak ver, 2 Üzerine yakacağım ağıtın sözlerine:'),
(2005718,68,30,5,2,'‹‹Düştü erden kız İsrail, 2 Bir daha kalkamaz, 2 Serilmiş kendi toprağına, 2 Kaldıran yok.››'),
(2005719,68,30,5,3,'Bu yüzden Egemen RAB şöyle diyor: 2 ‹‹Bin kişiyle savaşa çıkan kentin 2 Yüz adamı sağ kalacak, 2 Yüz kişiyle çıkanın 2 On adamı kalacak İsrail halkına.››'),
(2005720,68,30,5,4,'Bu yüzden RAB İsrail halkına şöyle diyor: 2 ‹‹Bana yönelin, yaşarsınız;'),
(2005721,68,30,5,5,'Beytele gitmeyin, 2 Gilgala girmeyin, 2 Beer-Şevaya geçmeyin, 2 Çünkü Gilgal halkı kesinlikle sürgün edilecek, 2 Beytel bir hiçfç olacak.›› anlamına gelir. ‹‹Beytaven›› aşağılamak amacıyla Beytel için kullanılırdı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005722,68,30,5,6,'RABbe yönelin, yaşarsınız, 2 Yoksa Yusuf soyunda bir ateş gibi parlar, 2 Beyteli yakıp yok eder. 2 Yangını söndürecek kimse çıkmaz.'),
(2005723,68,30,5,7,'Ey adaleti acı pelinotuna çevirenler, 2 Doğruluğu yere çalanlar!'),
(2005724,68,30,5,8,'Ülker ve Oryon takımyıldızlarını yaratan, 2 Zifiri karanlığı sabaha çeviren, 2 Gündüzü geceyle karartan, 2 Deniz sularını çağırıp 2 Yeryüzüne dökenin adı RABdir.'),
(2005725,68,30,5,9,'Kaleyi ansızın yıkar, 2 Surlu kenti yerle bir eder.'),
(2005726,68,30,5,10,'Mahkemede kendilerini azarlayandan nefret ediyor, 2 Doğru konuşandan iğreniyorlar.'),
(2005727,68,30,5,11,'Yoksulu ezdiğiniz, 2 Ondan zorla buğday kopardığınız için 2 Yaptığınız yontma taş evlerde oturmayacak, 2 Diktiğiniz güzel bağların şarabını içmeyeceksiniz.'),
(2005728,68,30,5,12,'Çünkü isyanlarınızın çok, 2 Günahlarınızın sayısız olduğunu biliyorum, 2 Ey doğru kişiye baskı yapan, 2 Rüşvet alan, 2 Mahkemede mazlumun hakkını yiyenler!'),
(2005729,68,30,5,13,'Bu yüzden susmak düşer akıllı insana 2 Böyle bir zamanda, 2 Çünkü zaman kötüdür.'),
(2005730,68,30,5,14,'Kötülüğe değil, 2 İyiliğe yönelin ki yaşayasınız; 2 Böylece dediğiniz gibi, 2 RAB, Her Şeye Egemen Tanrı sizinle olur.'),
(2005731,68,30,5,15,'Kötülükten nefret edin, 2 İyiliği sevin, 2 Mahkemede adaleti koruyun. 2 Belki RAB, Her Şeye Egemen Tanrı, 2 Yusufun soyundan sağ kalanlara lütfeder.'),
(2005732,68,30,5,16,'Bu yüzden RAB, 2 Her Şeye Egemen Tanrı Rab şöyle diyor: 2 ‹‹Bütün meydanlarda çığlık kopacak, 2 Sokaklarda inim inim inleyecekler; 2 Irgatları yas tutmaya, 2 Ağıtçıları feryat etmeye çağıracaklar.'),
(2005733,68,30,5,17,'Bütün bağlarda çığlık kopacak, 2 Çünkü ben aranızdan geçeceğim.›› 2 RAB böyle diyor.'),
(2005734,68,30,5,18,'Vay başına, RABbin gününü özlemle bekleyenlerin! 2 Niçin özlüyorsunuz RABbin gününü? 2 O gün aydınlık değil, karanlık olacak.'),
(2005735,68,30,5,19,'Nasıl ki, biri aslanın önünden kaçar da karşısına ayı çıkar, 2 Evine döner, elini duvara dayar da elini yılan sokar.'),
(2005736,68,30,5,20,'RABbin günü aydınlık değil, karanlık olmayacak mı? 2 Hem de zifiri karanlık, 2 Bir parıltı bile yok.'),
(2005737,68,30,5,21,'RAB şöyle diyor: 2 ‹‹İğreniyor, tiksiniyorum bayramlarınızdan, 2 Hoşlanmıyorum dinsel toplantılarınızdan,'),
(2005738,68,30,5,22,'Yakmalık ve tahıl sunularınızı 2 Bana sunsanız bile kabul etmeyeceğim, 2 Besili hayvanlarınızdan sunacağınız 2 Esenlik sunularına dönüp bakmayacağım.'),
(2005739,68,30,5,23,'Uzak tutun benden ezgilerinizin gürültüsünü, 2 Çenklerinizin sesini dinlemeyeceğim.'),
(2005740,68,30,5,24,'Bunun yerine adalet su gibi, 2 Doğruluk ırmak gibi sürekli aksın.'),
(2005741,68,30,5,25,'‹‹Ey İsrail halkı, çölde kırk yıl boyunca 2 Bana mı kurbanlar, sunular sundunuz?'),
(2005742,68,30,5,26,'Gerçekte kralınız Sakkutu, putunuz Kayvanı, 2 Kendiniz için yaptığınız ilahın yıldızını taşıdınız. ‹‹Gerçekte kralınızın çadırını, putlarınızın kaidesini››. Sakkut ve Kayvan İsrailde tapılan ilahlardı. Asur ilahları olduğu sanılıyor.'),
(2005743,68,30,5,27,'Bu yüzden sizi Şam''ın ötesine süreceğim.›› 2 RAB böyle diyor, O''nun adı Her Şeye Egemen Tanrı''dır.'),
(2005744,68,30,6,1,'Vay başına Siyondaki kaygısızların, 2 Samiriye Dağında kendilerini güvende sananların, 2 İsrail halkının başvurduğu 2 Önder ulusun tanınmış insanlarının!'),
(2005745,68,30,6,2,'Kalne Kentine gidin de görün, 2 Oradan büyük Hamaya geçin, 2 Filistlilerin Gat Kentine inin, 2 Sizin bu krallıklarınızdan daha mı iyiler? 2 Toprakları sizinkinden daha mı geniş?'),
(2005746,68,30,6,3,'Ey sizler, kötü günü uzak sanan, 2 Zorbalık tahtını yaklaştıranlar.'),
(2005747,68,30,6,4,'Ey sizler, fildişi süslü yataklara uzananlar, 2 Sedirlere serilenler, 2 Seçme kuzular, besili buzağılar yiyenler,'),
(2005748,68,30,6,5,'Çenk eşliğinde türkü söyleyenler, 2 Davut gibi beste yapanlar,'),
(2005749,68,30,6,6,'Tas tas şarap içenler, 2 Yağların en güzelini sürünenler, 2 Yusufun yıkımına kederlenmeyenler!'),
(2005750,68,30,6,7,'Bu yüzden şimdi bunlar 2 Sürgüne gideceklerin başını çekecekler; 2 Sona erecek sedire serilenlerin cümbüşü.'),
(2005751,68,30,6,8,'Egemen RAB başı üzerine ant içti, 2 Her Şeye Egemen Tanrı RAB şöyle diyor: 2 ‹‹Yakupun gururundan iğreniyor, 2 Saraylarından tiksiniyorum. 2 Bu yüzden içindeki her şeyle kenti 2 Düşmana teslim edeceğim.››'),
(2005752,68,30,6,9,'Eğer bir evden on kişi kalmışsa, 2 Onlar da ölecek.'),
(2005753,68,30,6,10,'Ölünün akrabası yakmak için cesedi evden almaya gelince, 2 Evdekine, ‹‹Yanında kimse var mı?›› diye soracak, 2 O da, ‹‹Hayır!›› yanıtını alınca, 2 ‹‹Sus!›› diyecek, ‹‹RABbin adı anılmamalı.››'),
(2005754,68,30,6,11,'Çünkü RAB buyuruyor, 2 Büyük ev toza, 2 Küçük ev küle dönecek.'),
(2005755,68,30,6,12,'Atlar kaya üzerinde koşar mı? 2 Kimse denizde öküzle çift sürer mi? 2 Ama siz adaleti zehire, 2 Doğruluk meyvesini pelinotuna çevirdiniz.'),
(2005756,68,30,6,13,'Sizler, Lo-Devar Kentini aldık diye sevinenler, 2 ‹‹Karnayimi kendi bileğimizle ele geçirmedik mi?›› diyenlersiniz. simgesidir.'),
(2005757,68,30,6,14,'‹‹İşte bu yüzden, ey İsrail halkı, 2 Üzerinize bir ulus göndereceğim›› 2 Diyor Her Şeye Egemen Tanrı RAB, 2 ‹‹Levo-Hamat''tan Arava Vadisi''ne kadar ezecekler sizi.››'),
(2005758,68,30,7,1,'Egemen RAB bana şunu gösterdi: Kralın payına düşen otlar biçilmişti. Otlar yeniden yeşermeye başlarken RAB sürüyle çekirge yaratıyordu.'),
(2005759,68,30,7,2,'Çekirgeler ülkedeki yeşil bitkileri yiyip bitirince: ‹‹Ey Egemen RAB, lütfen halkını bağışla!›› dedim, 2 ‹‹Yakup soyu buna nasıl dayanır? 2 Zaten küçük bir halk!››'),
(2005760,68,30,7,3,'Bunun üzerine RAB düşüncesini değiştirdi. 2 ‹‹Gerçekleşmeyecek bu›› dedi.'),
(2005761,68,30,7,4,'Egemen RAB bana şunu gösterdi: Baktım, Egemen RAB halkını cezalandırmak için ateşi çağırdı. Ateş enginleri yakıp tüketti, karayı yakıp tüketmeye başladı.'),
(2005762,68,30,7,5,'O zaman, ‹‹Ey Egemen RAB, lütfen dur!›› dedim, 2 ‹‹Yakup soyu buna nasıl dayanır? 2 Zaten küçük bir halk!››'),
(2005763,68,30,7,6,'Bunun üzerine RAB düşüncesini değiştirdi. 2 Egemen RAB, ‹‹Bu da gerçekleşmeyecek›› dedi.'),
(2005764,68,30,7,7,'Başka bir görümde şunu gösterdi bana: Baktım, Rab çekül kullanılarak örülmüş dümdüz bir duvarın yanında duruyor; elinde bir çekül var.'),
(2005765,68,30,7,8,'RAB, ‹‹Ne görüyorsun, Amos?›› diye sordu. Ben de, ‹‹Bir çekül›› dedim. Bunun üzerine Rab, ‹‹İşte, halkım İsrailin ortasına da bir çekül koyacağım›› dedi, ‹‹Bir daha onları esirgemeyeceğim.'),
(2005766,68,30,7,9,'‹‹Yok olacak İshak soyunun tapınma yerleri, 2 Yıkılacak İsrailin kutsal yerleri, 2 Kılıçla yürüyeceğim Yarovam soyunun üstüne.››'),
(2005767,68,30,7,10,'Beyteldeki Kâhin Amatsya, İsrail Kralı Yarovama haber gönderip şöyle dedi: ‹‹Amos İsrailin göbeğinde sana düzen kurdu. Ülke onun bunca sözünü kaldıramaz.'),
(2005768,68,30,7,11,'Çünkü Amos diyor ki, ‹‹ ‹Yarovam kılıçla öldürülecek, 2 İsrail halkı kesinlikle ülkesinin dışına, 2 Sürgüne gönderilecek.› ››'),
(2005769,68,30,7,12,'Bunun üzerine Amatsya Amosa, ‹‹Çek git, ey bilici!›› dedi, ‹‹Yahudaya kaç. Ekmeğini orada kazan. Orada peygamberlik et.'),
(2005770,68,30,7,13,'Bir daha Beytelde peygamberlik etme. Çünkü burası kralın kutsal yeri, krallık tapınağıdır.››'),
(2005771,68,30,7,14,'Amos, ‹‹Ben ne peygamberdim ne de peygamber oğluydum›› diye karşılık verdi, ‹‹Yalnızca sığır yetiştirirdim. Yabanıl incir ağaçlarına bakardım.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005772,68,30,7,15,'RAB beni sürünün ardından aldı, ‹Git, halkım İsraile peygamberlik et› dedi.'),
(2005773,68,30,7,16,'Şimdi kulak ver RABbin sözlerine: ‹‹ ‹İsraile karşı peygamberlik etme, 2 İshak soyuna karşı konuşma!› diyorsun.'),
(2005774,68,30,7,17,'Bu yüzden RAB şöyle diyor: 2 ‹Karın kentte fahişe olacak, 2 Oğulların, kızların kılıçtan geçirilecek. 2 Ölçü ipiyle paylaşılacak toprağın, 2 Sen ise kirli sayılan toprakta can vereceksin. 2 İsrail halkı kesinlikle ülke dışına, 2 Sürgüne gönderilecek.› ››'),
(2005775,68,30,8,1,'Egemen RAB bana şunu gösterdi: Baktım bir sepet olgun meyve.'),
(2005776,68,30,8,2,'Bana, ‹‹Ne görüyorsun, Amos?›› diye sordu. ‹‹Bir sepet olgun meyve›› diye yanıtladım. Bunun üzerine RAB, ‹‹Halkım İsrailin sonu geldi›› dedi, ‹‹Bir daha onları esirgemeyeceğim.'),
(2005777,68,30,8,3,'O gün saraydaki türküler yas çığlıklarına dönecek.›› Egemen RAB, ‹‹Her yer atılmış cesetlerle dolacak, sessizlik hüküm sürecek›› diyor. çağrıştırıyor.'),
(2005778,68,30,8,4,'Dinleyin bunu, ey yoksulu çiğneyenler, 2 Ülkedeki mazlumları yok edenler!'),
(2005779,68,30,8,5,'Diyorsunuz ki, 2 ‹‹Yeni Ay Töreni geçse de tahılımızı satsak, 2 Şabat Günü geçse de buğdayımızı satışa çıkarsak. 2 Ölçeğifı küçültüp fiyatı yükseltsek, 2 Hileli tartı kullanıp ağırlık taşı.'),
(2005780,68,30,8,6,'Yoksulları gümüş, 2 Mazlumları bir çift çarık karşılığında satın alsak. 2 Buğday yerine süprüntüsünü satsak.››'),
(2005781,68,30,8,7,'Yakup soyunun gurur duyduğu RAB kendi başı üstüne ant içti: 2 ‹‹Onların yaptıklarının hiçbirini asla unutmayacağım.'),
(2005782,68,30,8,8,'Bu yüzden yer sarsılmayacak mı, 2 Üzerinde yaşayan herkes yas tutmayacak mı? 2 Bütün yer Nil gibi yükselecek, 2 Kabarıp yine inecek Mısırın ırmağı gibi.››'),
(2005783,68,30,8,9,'‹‹O gün›› diyor Egemen RAB, 2 ‹‹Öğleyin güneşi batıracağım, 2 Güpegündüz yeryüzünü karartacağım.'),
(2005784,68,30,8,10,'Bayramlarınızı yasa, 2 Bütün ezgilerinizi ağıta döndüreceğim. 2 Her bele çul kuşattıracağım, 2 Her başın saçını yoldurtacağım. 2 O günü biricik oğulun ardından tutulan yasa çevirecek, 2 Sonunu acı getireceğim.'),
(2005785,68,30,8,11,'‹‹İşte günler geliyor, 2 Ülkeye kıtlık göndereceğim›› 2 Diyor Egemen RAB, 2 ‹‹Ekmek ya da su kıtlığı değil, 2 RABbin sözlerine susamışlık göndereceğim.'),
(2005786,68,30,8,12,'RABbin sözünü bulmak için 2 İnsanlar denizden denize, 2 Kuzeyden doğuya dek dolaşacak, 2 Oraya buraya koşacak, ama bulamayacaklar.'),
(2005787,68,30,8,13,'O gün güzel kızlar, 2 Yiğitler susuzluktan bayılacak.'),
(2005788,68,30,8,14,'Samiriye tanrıçası Aşima üzerine ant içenler, 2 ‹Ey Dan, senin ilahının başı üzerine› 2 Ve, ‹Beer-Şeva ilahının başı üzerine› diyenler 2 Düşecek ve bir daha kalkmayacak.››'),
(2005789,68,30,9,1,'Rabbi gördüm, 2 Sunağın yanında duruyordu. 2 ‹‹Sütun başlıklarına vur, 2 Eşikler sarsılsın›› dedi, 2 ‹‹Başlıkları insanların başında parala. 2 Sağ kalanları kılıçtan geçireceğim. 2 Kaçan, kurtulan olmayacak,'),
(2005790,68,30,9,2,'Ölüler diyarını delip girseler, 2 Elimi uzatıp onları çıkaracağım. 2 Göklere çıksalar, 2 Onları oradan indireceğim.'),
(2005791,68,30,9,3,'Karmel Dağının doruklarına gizlenseler, 2 Artlarına düşüp onları yakalayacağım. 2 Gözümün önünden uzağa, denizin dibine girseler, 2 Orada yılana buyruk vereceğim, 2 Onları sokacak.'),
(2005792,68,30,9,4,'Düşmanlarınca sürgün edilseler, 2 Orada kılıca buyruk vereceğim, 2 Onları biçecek. 2 Gözümü üzerlerinden ayırmayacağım, 2 Ama iyilik için değil, kötülük için.››'),
(2005793,68,30,9,5,'Rab, Her Şeye Egemen RAB 2 Yere dokununca yer erir, 2 Üzerinde yaşayan herkes yasa bürünür, 2 Bütün yeryüzü Nil gibi kabarır, 2 Mısırın ırmağı gibi yine alçalır.'),
(2005794,68,30,9,6,'Yukarı odalarını gökyüzünde yapan, 2 Kubbesini yeryüzünde kuran, 2 Denizin sularını çağırıp yeryüzüne döken Odur; 2 Onun adı RABdir.'),
(2005795,68,30,9,7,'‹‹Ey İsrailliler, 2 Benim için Kûşlulardan ne farkınız var?›› 2 Diyor RAB. 2 ‹‹İsraillileri Mısırdan, 2 Filistlileri Kaftordan, 2 Aramlıları Kîrden çıkaran ben değil miyim?'),
(2005796,68,30,9,8,'‹‹İşte, Egemen RABbin gözleri 2 Bu günahlı krallığın üzerindedir. 2 Onu yeryüzünden söküp atacağım, 2 Ancak Yakup soyunu büsbütün yok etmeyeceğim›› 2 Diyor RAB.'),
(2005797,68,30,9,9,'‹‹İşte buyruk vereceğim, 2 Bütün uluslar arasından 2 İsraili kalburla eler gibi eleyeceğim, 2 Bir çakıl bile yere düşmeyecek.'),
(2005798,68,30,9,10,'Halkımın arasındaki bütün günahlılar, 2 ‹Kötülük bizi bulmaz, bize erişmez› diyenler 2 Kılıçtan geçirilecek.››'),
(2005799,68,30,9,11,'‹‹O gün Davutun yıkık çardağını yeniden kuracağım, 2 Gediklerini kapayacak, 2 Yıkık yerlerini onaracağım, 2 Onu eskisi gibi yapacağım,'),
(2005800,68,30,9,12,'Öyle ki, Edomluların sağ kalanlarını, 2 Bana ait olan bütün ulusları sahiplensinler.›› 2 Bunu yapacak olan RAB böyle diyor.'),
(2005801,68,30,9,13,'‹‹İşte, günler geliyor›› diyor RAB, 2 ‹‹Çift süren orakçıya, 2 Üzüm basan ekin ekene erişecek, 2 Dağlardan tatlı şarap damlayacak, 2 Bütün tepelerden akacak.'),
(2005802,68,30,9,14,'Sürgün halkım İsraili geri getireceğim, 2 Yıkık kentleri onarıp orada yaşayacaklar, 2 Bağlar dikip şarabını içecekler, 2 Bahçeler yapıp meyvesini yiyecekler.'),
(2005803,68,30,9,15,'Onları topraklarına dikeceğim, 2 Bir daha sökülmeyecekler 2 Kendilerine verdiğim topraktan.›› 2 Tanrınız RAB böyle diyor.'),
(2005804,68,32,1,1,'RAB bir gün Amittay oğlu Yunusa, ‹‹Kalk, Ninovaya, o büyük kente git ve halkı uyar›› diye seslendi, ‹‹Çünkü kötülükleri önüme kadar yükseldi.››'),
(2005805,68,32,1,3,'Ne var ki, Yunus RABbin huzurundan Tarşişe kaçmaya kalkıştı. Yafaya inip Tarşişe giden bir gemi buldu. Ücretini ödeyip gemiye bindi, RABden uzaklaşmak için Tarşişe doğru yola çıktı.'),
(2005806,68,32,1,4,'Yolda RAB şiddetli bir rüzgar gönderdi denize. Öyle bir fırtına koptu ki, gemi neredeyse parçalanacaktı.'),
(2005807,68,32,1,5,'Gemiciler korkuya kapıldı, her biri kendi ilahına yalvarmaya başladı. Gemiyi hafifletmek için yükleri denize attılar. Yunus ise teknenin ambarına inmiş, yatıp derin bir uykuya dalmıştı.'),
(2005808,68,32,1,6,'Gemi kaptanı Yunusun yanına gidip, ‹‹Hey! Nasıl uyursun sen?›› dedi, ‹‹Kalk, tanrına yalvar, belki halimizi görür de yok olmayız.››'),
(2005809,68,32,1,7,'Sonra denizciler birbirlerine, ‹‹Gelin, kura çekelim›› dediler, ‹‹Bakalım, bu bela kimin yüzünden başımıza geldi.›› Kura çektiler, kura Yunusa düştü.'),
(2005810,68,32,1,8,'Bunun üzerine Yunusa, ‹‹Söyle bize!›› dediler, ‹‹Bu bela kimin yüzünden başımıza geldi? Ne iş yapıyorsun sen, nereden geliyorsun, nerelisin, hangi halka mensupsun?››'),
(2005811,68,32,1,9,'Yunus, ‹‹İbraniyim›› diye karşılık verdi, ‹‹Denizi ve karayı yaratan Göklerin Tanrısı RABbe taparım.››'),
(2005812,68,32,1,10,'Denizciler bu yanıt karşısında dehşete düştüler. ‹‹Neden yaptın bunu?›› diye sordular. Yunusun RABden uzaklaşmak için kaçtığını biliyorlardı. Daha önce onlara anlatmıştı.'),
(2005813,68,32,1,11,'Deniz gittikçe kuduruyordu. Yunusa, ‹‹Denizin dinmesi için sana ne yapalım?›› diye sordular.'),
(2005814,68,32,1,12,'Yunus, ‹‹Beni kaldırıp denize atın›› diye yanıtladı, ‹‹O zaman sular durulur. Çünkü biliyorum, bu şiddetli fırtınaya benim yüzümden yakalandınız.››'),
(2005815,68,32,1,13,'Denizciler karaya dönmek için küreklere asıldılar, ama başaramadılar. Çünkü deniz gittikçe kuduruyordu.'),
(2005816,68,32,1,14,'RABbe seslenerek, ‹‹Ya RAB, yalvarıyoruz›› dediler, ‹‹Bu adamın canı yüzünden yok olmayalım. Suçsuz bir adamın ölümünden bizi sorumlu tutma. Çünkü sen kendi istediğini yaptın, ya RAB.››'),
(2005817,68,32,1,15,'Sonra Yunusu kaldırıp denize attılar, kuduran deniz sakinleşti.'),
(2005818,68,32,1,16,'Bu olaydan ötürü denizciler RABden öyle korktular ki, Ona kurbanlar sundular, adaklar adadılar.'),
(2005819,68,32,1,17,'Bu arada RAB Yunus''u yutacak büyük bir balık sağladı. Yunus üç gün üç gece bu balığın karnında kaldı.'),
(2005820,68,32,2,1,'Yunus balığın karnından Tanrısı RABbe şöyle dua etti:'),
(2005821,68,32,2,2,'‹‹Ya RAB, sıkıntı içinde sana yakardım, 2 Yanıtladın beni. 2 Yardım istedim ölüler diyarının bağrından, 2 Kulak verdin sesime.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005822,68,32,2,3,'Beni engine, denizin ta dibine fırlattın. 2 Sular sardı çevremi. 2 Azgın dalgalar geçti üzerimden.'),
(2005823,68,32,2,4,'‹Huzurundan kovuldum› dedim, 2 ‹Yine de göreceğim kutsal tapınağını.› kutsal tapınağını nasıl göreceğim?››'),
(2005824,68,32,2,5,'Sular boğacak kadar kuşattı beni, 2 Çevremi enginler sardı, 2 Yosunlar dolaştı başıma.'),
(2005825,68,32,2,6,'Dağların köklerine kadar battım, 2 Dünya sonsuza dek sürgülendi arkamdan; 2 Ama, ya RAB, Tanrım, 2 Canımı sen kurtardın çukurdan.'),
(2005826,68,32,2,7,'Soluğum tükenince seni andım, ya RAB, 2 Duam sana, kutsal tapınağına erişti.'),
(2005827,68,32,2,8,'Değersiz putlara tapanlar, 2 Vefasızlık etmiş olurlar.'),
(2005828,68,32,2,9,'Ama şükranla kurban sunacağım sana, 2 Adağımı yerine getireceğim. 2 Kurtuluş senden gelir, ya RAB!››'),
(2005829,68,32,2,10,'RAB balığa buyruk verdi ve balık Yunus''u karaya kustu.'),
(2005830,68,32,3,1,'RAB Yunusa ikinci kez şöyle seslendi:'),
(2005831,68,32,3,2,'‹‹Kalk, Ninovaya, o büyük kente git ve sana söyleyeceklerimi halka bildir.››'),
(2005832,68,32,3,3,'Yunus RABbin sözü uyarınca kalkıp Ninovaya gitti. Ninova öyle büyük bir kentti ki, ancak üç günde dolaşılabilirdi.'),
(2005833,68,32,3,4,'Yunus kente girip dolaşmaya başladı. Bir gün geçince, ‹‹Kırk gün sonra Ninova yıkılacak!›› diye ilan etti.'),
(2005834,68,32,3,5,'Ninova halkı Tanrıya inandı. Oruç ilan ederek büyüğünden küçüğüne hepsi çula sarındı.'),
(2005835,68,32,3,6,'Ninova Kralı olanları duyunca, tahtından kalkıp kaftanını çıkardı; çula sarınarak küle oturdu.'),
(2005836,68,32,3,7,'Ardından Ninovada şu buyruğu yayımladı: ‹‹Kral ve soyluların buyruğudur: Hiçbir insan ya da hayvan -ister sığır, ister davar olsun- ağzına bir şey koymayacak, otlamayacak, içmeyecek.'),
(2005837,68,32,3,8,'Bütün insanlar ve hayvanlar çula sarınsın. Herkes var gücüyle Tanrıya yakararak kötü yoldan, zorbalıktan vazgeçsin.'),
(2005838,68,32,3,9,'Belki o zaman Tanrı fikrini değiştirip bize acır, kızgın öfkesinden döner de yok olmayız.››'),
(2005839,68,32,3,10,'Tanrı Ninovalılar''ın yaptıklarını, kötü yoldan döndüklerini görünce, onlara acıdı, yapacağını söylediği kötülükten vazgeçti.'),
(2005840,68,32,4,1,'Yunus buna çok gücenip öfkelendi.'),
(2005841,68,32,4,2,'RABbe şöyle dua etti: ‹‹Ah, ya RAB, ben daha ülkemdeyken böyle olacağını söylemedim mi? Bu yüzden Tarşişe kaçmaya kalkıştım. Biliyordum, sen lütfeden, acıyan, tez öfkelenmeyen, sevgisi engin, cezalandırmaktan vazgeçen bir Tanrısın.'),
(2005842,68,32,4,3,'Ya RAB, lütfen şimdi canımı al. Çünkü benim için ölmek yaşamaktan iyidir.››'),
(2005843,68,32,4,4,'RAB, ‹‹Ne hakla öfkeleniyorsun?›› diye karşılık verdi.'),
(2005844,68,32,4,5,'Yunus kentten çıktı, kentin doğusundaki bir yerde durdu. Kendisine bir çardak yaptı, gölgesinde oturup kentin başına neler geleceğini görmek için beklemeye başladı.'),
(2005845,68,32,4,6,'RAB Tanrı Yunusun üzerine gölge salacak, sıkıntısını giderecek bir keneotu sağladı. Yunus buna çok sevindi.'),
(2005846,68,32,4,7,'Ama ertesi gün şafak sökerken, Tanrının sağladığı bir bitki kurdu keneotunu kemirip kuruttu.'),
(2005847,68,32,4,8,'Güneş doğunca Tanrı yakıcı bir doğu rüzgarı estirdi. Yunus başına vuran güneşten bayılmak üzereydi. Ölümü dileyerek, ‹‹Benim için ölmek yaşamaktan iyidir›› dedi.'),
(2005848,68,32,4,9,'Ama Tanrı, ‹‹Keneotu yüzünden öfkelenmeye hakkın var mı?›› dedi. Yunus, ‹‹Elbette hakkım var, ölesiye öfkeliyim›› diye karşılık verdi.'),
(2005849,68,32,4,10,'RAB, ‹‹Keneotu bir gecede çıktı ve bir gecede yok oldu›› dedi, ‹‹Sen emek vermediğin, büyütmediğin bir keneotuna acıyorsun da,'),
(2005850,68,32,4,11,'ben Ninova''ya, o koca kente acımayayım mı? O kentte sağını solundan ayırt edemeyen yüz yirmi bini aşkın insan, çok sayıda hayvan var.››'),
(2005851,68,33,1,1,'Yahuda kralları Yotam, Ahaz ve Hizkiya zamanında RAB Moreşetli Mikaya, Samiriye ve Yeruşalimle ilgili olarak bir görümde şunu bildirdi:'),
(2005852,68,33,1,2,'Ey halklar, hepiniz duyun; 2 Ey dünya ve bütün içindekiler, dinleyin. 2 Egemen RAB kendi kutsal tapınağından size karşı tanıklık edecek.'),
(2005853,68,33,1,3,'İşte, RAB yerinden çıkıp gelecek, 2 Yeryüzüne inip dağ doruklarında yürüyecek.'),
(2005854,68,33,1,4,'Dağlar Onun önünde ateş karşısında eriyen balmumu gibi eriyecek, 2 Vadiler, bayır aşağı akan sular gibi yarılacak.'),
(2005855,68,33,1,5,'Bütün bunlar Yakupoğullarının isyanı 2 Ve İsrail halkının günahları yüzünden olacak. 2 Yakupoğullarının isyanından kim sorumlu? 2 Samiriye değil mi? 2 Yahudadaki putperestlikten kim sorumlu? 2 Yeruşalim değil mi?'),
(2005856,68,33,1,6,'Bu yüzden RAB, ‹‹Samiriyeyi kırdaki taş yığınına, 2 Bağ dikilecek yere çevireceğim›› diyor, 2 ‹‹Taşlarını vadiye döküp temellerini açacağım.'),
(2005857,68,33,1,7,'Bütün putları paramparça edilecek, 2 Tapınaklarındaki fahişelere verilen armağanlar yakılacak. 2 Samiriyenin bütün putlarını yok edeceğim. 2 Fahişelerin ücretiyle topladığı armağanlar 2 Yine fahişelere ücret olacak.››'),
(2005858,68,33,1,8,'Ben Mika, bundan ötürü ağlayıp ağıt yakacağım, 2 Çırçıplak, yalınayak dolaşacağım. 2 Çakal gibi uluyup baykuş gibi öteceğim.'),
(2005859,68,33,1,9,'Çünkü Samiriyenin yaraları onmaz. 2 Yahuda da aynı sona uğramak üzere. 2 Halkımın yaşadığı Yeruşalimin kapılarına dayandı yıkım.'),
(2005860,68,33,1,10,'Bunu Gata duyurmayın, 2 Ağlamayın sakın! 2 Beytofrada toz toprak içinde yuvarlanın.'),
(2005861,68,33,1,11,'Ey Şafir halkı, 2 Çıplak ve utanç içinde geçip git. 2 Saananda yaşayanlar kentlerinden çıkamayacaklar, 2 Beytesel halkı yas tutacak. 2 Kesecek sizden yardımını.'),
(2005862,68,33,1,12,'Marotta yaşayanlar kurtulmayı sabırsızlıkla bekliyor. 2 Çünkü RABbin gönderdiği felaket Yeruşalimin kapılarına dayandı.'),
(2005863,68,33,1,13,'Ey Lakiştefç oturanlar, atları koşun arabalara. 2 Siyon Kentini günaha ilk düşüren siz oldunuz. 2 Çünkü İsrailin isyanını örnek aldınız.'),
(2005864,68,33,1,14,'Bundan ötürü Moreşet-Gata veda armağanları vereceksiniz. 2 İsrail kralları Akziv Kentinden boşuna yardım bekleyecek. armağanlarından söz ediliyor.'),
(2005865,68,33,1,15,'Ey Mareşada yaşayanlar, 2 RAB kentinizi ele geçirecek olanı üzerinize gönderecek. 2 İsrailin yüce önderleri Adullamdaki mağaraya sığınacak.'),
(2005866,68,33,1,16,'Sevgili çocuklarınız için saçlarınızı yolup kazıyın. 2 Akbabalar gibi kafalarınızın keli görünsün. 2 Çünkü çocuklarınız sizden alınıp sürgüne götürülecek.'),
(2005867,68,33,2,1,'Yatarken fesat ve kötülük tasarlayanların vay haline! 2 Ortalık ağarınca tasarladıklarını yaparlar. 2 Çünkü güçleri buna yeter.'),
(2005868,68,33,2,2,'Göz diktikleri tarlaları zorla alır, evlere el koyarlar. 2 Birini evinden, bir başkasını mirasından ederler.'),
(2005869,68,33,2,3,'Bu nedenle RAB bu halka şöyle diyor: 2 ‹‹Bakın, size öyle bir bela hazırlıyorum ki, 2 Bundan yakanızı kurtaramayacaksınız. 2 Öyle amansız bir zaman gelecek ki, 2 Başınız dik yürüyemeyeceksiniz.'),
(2005870,68,33,2,4,'O gün sizinle alay edecekler. 2 Sizin için şu acıklı ezgiyi söyleyecekler: 2 ‹Büsbütün mahvolduk! 2 RAB halkımızın varını yoğunu başkalarına bölüştürüyor, 2 Topraklarımızı hainlere dağıtıyor.› ››'),
(2005871,68,33,2,5,'Bu nedenle, ülkeyi kurayla bölüştürme zamanı gelince 2 RABbin topluluğunda sizden kimse bulunmayacak.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005872,68,33,2,6,'İnsanlar, ‹‹Peygamberlik etmeyin›› diyorlar, 2 ‹‹Bu konularda peygamberlik etmemeli. 2 Utandırılmayacağız.››'),
(2005873,68,33,2,7,'Ey Yakupoğulları, böyle konuşulur mu? 2 ‹‹RABbin sabrı mı tükendi acaba? 2 O böyle şeyler yapar mı? 2 Benim sözlerim doğru yolda yürüyenin yararına değil mi?›› diyor RAB,'),
(2005874,68,33,2,8,'‹‹Daha dün halkım düşman gibi ayaklandı. 2 Savaştan dönenlerin, kaygısızca önünüzden geçenlerin sırtından 2 Güzel giysilerini sıyırıp alırsınız.'),
(2005875,68,33,2,9,'Halkımın kadınlarını rahat evlerinden kovar, 2 Çocuklarını yüce huzurumdan yoksun bırakırsınız.'),
(2005876,68,33,2,10,'Kalkıp gidin, dinlenme yeriniz değil burası! 2 Murdarlığınız yüzünden bu yer korkunç biçimde yıkılacak.'),
(2005877,68,33,2,11,'Yalancı, aldatıcı biri gelip, 2 ‹Size şarap ve içkiden söz edeyim› dese, 2 Bu halk onu peygamber kabul edecek.››'),
(2005878,68,33,2,12,'‹‹Ey Yakupoğulları, 2 Elbette hepinizi bir araya getireceğim. 2 İsrailin geride kalanlarını elbette toplayacağım. 2 Ağıldaki davar gibi, 2 Otlaktaki sürü gibi bir araya getireceğim sizleri. 2 Topraklarınız insanlarla dolacak.››'),
(2005879,68,33,2,13,'Tanrı yolu açıp halkın önünden gidecek. 2 Kent kapılarını kırıp dışarı çıkacaklar. 2 Kralları olan RAB önlerinden gidecek.'),
(2005880,68,33,3,1,'Dedim ki, 2 ‹‹Ey Yakupoğullarının önderleri, 2 İsrail halkının yöneticileri, 2 Dinleyin! Adil olmanız gerekmez mi?'),
(2005881,68,33,3,2,'Siz ki iyiden nefret eder, kötüyü seversiniz. 2 Halkımın derisini yüzer, etini kemiğinden sıyırırsınız.'),
(2005882,68,33,3,3,'Halkımın derisini yüzer, etini yersiniz. 2 Kemiklerini kırar, 2 Tencerede, kazanda haşlanacak et gibi doğrarsınız.››'),
(2005883,68,33,3,4,'Gün gelecek RABbe yakaracaklar. 2 Ama O yanıtlamayacak, 2 Yüzünü onlardan gizleyecek. 2 Çünkü kötülük yaptılar.'),
(2005884,68,33,3,5,'RAB diyor ki, 2 ‹‹Ey halkımı saptıran peygamberler, 2 Sizi doyuranlara esenlik diler, 2 Doyurmayanlara savaş açarsınız.'),
(2005885,68,33,3,6,'Bu nedenle üzerinize görümsüz geceler çökecek. 2 Karanlıktan fal bakamayacaksınız. 2 Ey peygamberler, güneşiniz batacak, gününüz kararacak.'),
(2005886,68,33,3,7,'Biliciler utandırılacak. 2 Rezil olacak falcılar. 2 Utançtan yüzlerini örtecekler. 2 Çünkü Tanrıdan yanıt gelmeyecek.››'),
(2005887,68,33,3,8,'Ama Yakupoğullarına isyanlarını, 2 İsrail halkına günahlarını bildirmek için 2 Ben RABbin Ruhuyla, güçle, 2 Adalet ve cesaretle donatıldım.'),
(2005888,68,33,3,9,'Adaletten nefret eden, 2 Doğruları çarpıtan ey Yakupoğullarının önderleri 2 Ve İsrail halkının yöneticileri, iyi dinleyin:'),
(2005889,68,33,3,10,'Siyonu kan dökerek, 2 Yeruşalimi zorbalıkla bina ediyorsunuz.'),
(2005890,68,33,3,11,'Önderleri rüşvetle yönetir, 2 Kâhinleri ücretle öğretir, 2 Peygamberleri para için falcılık eder. 2 Sonra da, ‹‹RAB bizimle birlikte değil mi? 2 Başımıza bir şey gelmez›› diyerek 2 RABbe dayanmaya kalkışırlar.'),
(2005891,68,33,3,12,'Siyon tarla gibi sürülecek sizin yüzünüzden. 2 Taş yığınına dönecek Yeruşalim. 2 Tapınağın kurulduğu dağ 2 Çalılarla kaplanacak.'),
(2005892,68,33,4,1,'RABbin Tapınağının kurulduğu dağ, 2 Son günlerde dağların en yücesi, 2 Tepelerin en yükseği olacak. 2 Oraya akın edecek halklar.'),
(2005893,68,33,4,2,'Birçok ulus gelecek, 2 ‹‹Haydi, RABbin Dağına, 2 Yakupun Tanrısının Tapınağına çıkalım›› diyecekler, 2 ‹‹O bize kendi yolunu öğretsin, 2 Biz de Onun yolundan gidelim. 2 Çünkü yasa Siyondan, 2 RABbin sözü Yeruşalimden çıkacak.››'),
(2005894,68,33,4,3,'RAB halklar arasında yargıçlık edecek, 2 Uzaklardaki güçlü ulusların anlaşmazlıklarını çözecek. 2 İnsanlar kılıçlarını çekiçle dövüp saban demiri, 2 Mızraklarını bağcı bıçağı yapacaklar. 2 Ulus ulusa kılıç kaldırmayacak, 2 Savaş eğitimi yapmayacaklar artık.'),
(2005895,68,33,4,4,'Herkes kendi asmasının, incir ağacının altında oturacak. 2 Kimse kimseyi korkutmayacak. 2 Bunu söyleyen, Her Şeye Egemen RABdir.'),
(2005896,68,33,4,5,'Bütün halklar ilahlarının izinden gitse bile, 2 Biz sonsuza dek Tanrımız RABbin izinden gideceğiz.'),
(2005897,68,33,4,6,'‹‹Gün gelecek, düşkünü, sürgüne gönderip ezdiğim halkı 2 Bir araya getireceğim›› diyor RAB,'),
(2005898,68,33,4,7,'‹‹Düşkünü yaşatacak, 2 Uzaklara sürülenleri güçlü bir ulus yapacağım. 2 Onları Siyon Dağında bugünden sonsuza dek ben yöneteceğim.››'),
(2005899,68,33,4,8,'Ve sen, sürünün gözcü kulesi olan ey Siyon Kentinin doruğu, 2 Eski egemenliğine kavuşacaksın. 2 Ey Yeruşalim, krallığını yeniden elde edeceksin.'),
(2005900,68,33,4,9,'Neden öyle hıçkıra hıçkıra ağlıyorsun şimdi? 2 Doğuran kadın gibi neden acı çekiyorsun? 2 Kralın olmadığı için mi, 2 Öğütçün öldüğü için mi?'),
(2005901,68,33,4,10,'Doğuran kadın gibi ağrı çek, acıyla kıvran, ey Siyon halkı. 2 Şimdi kentten çıkıp kırlarda konaklayacaksın. 2 Babile gidecek, 2 Orada özgürlüğe kavuşacaksın. 2 RAB seni orada kurtaracak düşmanlarının elinden.'),
(2005902,68,33,4,11,'Ama şimdi birçok ulus sana karşı birleşti. 2 ‹‹Siyon murdar olsun, 2 Başına gelenleri gözlerimizle görelim›› diyorlar.'),
(2005903,68,33,4,12,'Ne var ki, RABbin ne düşündüğünü bilmiyorlar, 2 Onun tasarılarını anlamıyorlar. 2 RAB onları harman yerinde dövülen buğday demetleri gibi 2 Cezalandırmak için topladı.'),
(2005904,68,33,4,13,'RAB şöyle diyor: 2 ‹‹Ey Siyon halkı, kalk ve harmanı döv. 2 Çünkü seni demir boynuzlu, 2 Tunç tırnaklı boğalar kadar güçlü kılacağım. 2 Birçok halkı ezip geçecek, 2 Zorbalıkla elde ettikleri serveti, zenginlikleri bana, 2 Yeryüzünün sahibi olan Rab''be adayacaksın.››'),
(2005905,68,33,5,1,'Ey ordular kenti, şimdi ordularını topla. 2 Çevremizi sardılar, 2 İsraili yönetenin yanağına değnekle vuracaklar.'),
(2005906,68,33,5,2,'Ama sen, ey Beytlehem Efrata, 2 Yahuda boyları arasında önemsiz olduğun halde, 2 İsraili benim adıma yönetecek olan senden çıkacak. 2 Onun kökeni öncesizliğe, zamanın başlangıcına dayanır.'),
(2005907,68,33,5,3,'Bu yüzden onu doğuracak olan kadın doğurana dek 2 RAB İsraillileri düşmanlarına teslim edecek. 2 Sonra öbür soydaşları İsraillilere katılacak.'),
(2005908,68,33,5,4,'O gelince, halkını RABden aldığı güçle 2 Tanrısı RABbin görkemli adına yönetecek. 2 Halk güvenlik içinde yaşayacak. 2 Çünkü bütün dünya onun büyüklüğünü kabul edecek.'),
(2005909,68,33,5,5,'Halkına esenlik getirecek. Asurlular ülkemize saldırıp 2 Kalelerimizi ele geçirince, 2 Onlara karşı çok sayıda önder çıkaracağız. önder››.'),
(2005910,68,33,5,6,'Asur topraklarını kılıçla, 2 Nemrutun topraklarını yalın kılıçla yönetecekler. 2 Ülkemize saldırıp sınırlarımızdan içeri girecek olan Asurlulardan 2 Bizi bu önderler kurtaracak.'),
(2005911,68,33,5,7,'Yakupun soyundan geride kalanlar, 2 Birçok halkın arasında 2 RABbin gönderdiği çiy gibi, 2 Kimseye dayanmadan, kimsenin onayını beklemeden 2 Otları sulayan sağanak yağmurları gibi olacaklar.'),
(2005912,68,33,5,8,'Orman hayvanları arasında aslan ne ise, 2 Davar sürülerini paralayıp dağıtan, kurtulma fırsatı vermeyen genç aslan ne ise, 2 Yakupun soyundan geride kalanlar da uluslar arasında, 2 Halkların ortasında öyle olacaklar.'),
(2005913,68,33,5,9,'Ey İsrailliler, düşmanlarınızı yeneceksiniz. 2 Karşıtlarınızın hepsi ortadan kalkacak.'),
(2005914,68,33,5,10,'RAB diyor ki, 2 ‹‹O gün atlarınızı elinizden alacak, 2 Savaş arabalarınızı yok edeceğim.'),
(2005915,68,33,5,11,'Ülkenizdeki kentleri yıkacak, 2 Bütün kalelerinizi yerle bir edeceğim.'),
(2005916,68,33,5,12,'Büyü yapma gücünüzü kıracağım, 2 Aranızda falcı kalmayacak.'),
(2005917,68,33,5,13,'Putlarınızı, dikili taşlarınızı kaldırıp atacağım. 2 Ellerinizle yaptığınız putlara artık tapmayacaksınız.'),
(2005918,68,33,5,14,'Aşera putlarınızı söküp atacağım, 2 Yerle bir edeceğim kentlerinizi.'),
(2005919,68,33,5,15,'Söz dinlemeyen ulusları öfke ve gazapla cezalandıracağım.››'),
(2005920,68,33,6,1,'RABbin söylediğine kulak verin: 2 Kalkın, davanızı dağların önünde dile getirin. 2 Tepeler duysun sesinizi.'),
(2005921,68,33,6,2,'Ey dağlar ve yeryüzünün sarsılmaz temelleri, 2 RABbin suçlamasını dinleyin. 2 Çünkü RAB halkından davacı, 2 İsrailden şikâyetçi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005922,68,33,6,3,'‹‹Ey halkım, sana ne yaptım?›› diyor RAB, 2 ‹‹Sana nasıl yük oldum, yanıtla.'),
(2005923,68,33,6,4,'Seni Mısırdan ben çıkardım, 2 Ben kurtardım seni kölelik diyarından. 2 Sana öncülük etsinler diye Musayı, Harunu, Miryamı ben gönderdim.'),
(2005924,68,33,6,5,'Ey halkım, Moav Kralı Balakın neler öğütlediğini, 2 Beor oğlu Balamın onu nasıl yanıtladığını anımsa. 2 Şittimden Gilgala dek olup biteni an. 2 Sizleri nasıl kurtardığımı o zaman anlayacaksın.››'),
(2005925,68,33,6,6,'RABbin önüne ne ile çıkayım, 2 Yüce Tanrıya nasıl tapınayım? 2 Onun önüne yakmalık sunuyla mı, 2 Bir yaşında danayla mı çıkayım?'),
(2005926,68,33,6,7,'Binlerce koç sunsam, 2 Zeytinyağından on binlerce dere akıtsam, 2 RAB hoşnut kalır mı? 2 Suçuma karşılık ilk oğlumu, 2 İşlediğim günah için bedenimin ürününü versem olur mu?'),
(2005927,68,33,6,8,'Ey insanlar, RAB iyi olanı size bildirdi; 2 Adil davranmanızdan, sadakati sevmenizden 2 Ve alçakgönüllülükle yolunda yürümenizden başka 2 Tanrınız RAB sizden ne istedi?'),
(2005928,68,33,6,9,'Dinleyin! RAB kente sesleniyor. 2 Onun adından korkmak bilgeliktir. 2 Diyor ki, ‹‹Ey halk ve kent meclisi, dinleyinfı. Masoretik metin ‹‹Ey halk, dinle ve onu kim atadı?››'),
(2005929,68,33,6,10,'Kötü adamların evleri 2 Haksızca kazanılmış servetlerle dolu, 2 Bilmiyor muyum sanıyorsunuz? 2 Eksik ölçek lanetlidir.'),
(2005930,68,33,6,11,'Hileli terazi kullanan, 2 Torbasında eksik ağırlıklar olan adamı nasıl aklayayım?'),
(2005931,68,33,6,12,'Kentin zenginleri zorba, 2 Halkı da yalancıdır. 2 Dillerinden aldatıcı sözler dökülür.'),
(2005932,68,33,6,13,'Günahlarınızdan ötürü yıkımınızı, 2 Mahvınızı hazırladım bile.'),
(2005933,68,33,6,14,'Yiyecek, ama doymayacaksınız. 2 Aç kalacak karnınız, 2 Biriktireceksiniz, ama saklayamayacaksınız. 2 Koruyabildiğinizi kılıçla yok edeceğim.'),
(2005934,68,33,6,15,'Ekecek, ama biçemeyeceksiniz. 2 Zeytin ezecek, ama yağını sürünemeyeceksiniz. 2 Üzümü sıkacak, ama şarabını içemeyeceksiniz.'),
(2005935,68,33,6,16,'Kral Omri''nin buyruklarına, 2 Ahav soyunun kötü adetlerine uyduğunuz, 2 Onların törelerini izlediğiniz için sizi utanca boğacağım, yıkıma uğratacağım. 2 Halkım olarak aşağılanmaya dayanmak zorunda kalacaksınız.››'),
(2005936,68,33,7,1,'Vay halime benim! Yazın meyve toplandıktan 2 Ve bağbozumundan artakalan üzümler alındıktan sonra 2 Tek bir salkım bulamayan adam gibiyim. 2 Canım turfanda inciri nasıl da çekiyor!'),
(2005937,68,33,7,2,'Ülkede Tanrıya sadık kul kalmadı. 2 İnsanlar arasında dürüst kimse yok. 2 Herkes kan dökmek için pusuda. 2 Kardeş kardeşe tuzak kuruyor.'),
(2005938,68,33,7,3,'Kötülük yapmakta elleri ne becerikli! 2 Önderler armağan istiyor, yargıçlar rüşvet alıyor. 2 Güçlüler her istediklerini zorla yaptırıyor, 2 Düzen üstüne düzen kuruyorlar.'),
(2005939,68,33,7,4,'En iyileri çalı çırpıdan değersiz, 2 En dürüstleri dikenli çitten beterdir. 2 Ama peygamberlerinin uyardığı gibi, 2 Cezalandırılacakları gün geldi çattı. 2 Şaşkınlık içindeler şimdi.'),
(2005940,68,33,7,5,'İnanmayın komşunuza, 2 Dostunuza güvenmeyin. 2 Koynunuzda yatan karınızın yanında bile 2 Sıkı tutun ağzınızı.'),
(2005941,68,33,7,6,'Çünkü oğul babasına saygısızlık ediyor, 2 Kız annesine, gelin kaynanasına karşı geliyor. 2 İnsanın düşmanı kendi ev halkıdır.'),
(2005942,68,33,7,7,'Ama ben umutla RABbe bakıyor, 2 Kurtarıcım olan Tanrıyı bekliyorum. 2 Duyacak beni Tanrım.'),
(2005943,68,33,7,8,'Halime sevinme, ey düşmanım! 2 Düşsem de kalkarım. 2 Karanlıkta kalsam bile RAB bana ışık olur.'),
(2005944,68,33,7,9,'RABbe karşı günah işlediğim için, 2 Onun öfkesine dayanmalıyım. 2 Sonunda davamı savunup hakkımı alacak, 2 Beni ışığa çıkaracak, adaletini göreceğim.'),
(2005945,68,33,7,10,'Düşmanım da görecek ve utanç içinde kalacak. 2 O düşman ki, 2 ‹‹Hani Tanrın RAB nerede?›› diye soruyordu bana. 2 Onun düşüşünü gözlerimle göreceğim. 2 Sokaktaki çamur gibi ayak altında çiğnenecek.'),
(2005946,68,33,7,11,'Ey Yeruşalim, 2 Surlarının onarılacağı, 2 Sınırlarının genişletileceği gün gelecek.'),
(2005947,68,33,7,12,'Halkımızdan olanlar o gün 2 Asurdan Mısıra, 2 Mısırdan Fırata kadar uzanan topraklardan, 2 Denizler arasında, dağlar arasında kalan topraklardan sana gelecekler.'),
(2005948,68,33,7,13,'Ama ülke, içinde yaşayanların yaptığı kötülükler yüzünden viraneye dönecek.'),
(2005949,68,33,7,14,'Ya RAB, mirasın olan 2 Ve Karmelin ortasındaki ormanda ayrı yaşayan sürünü, halkını 2 Değneğinle güt. 2 Geçmişte olduğu gibi, 2 Başanda ve Gilatta beslensinler. verimli topraklarda››.'),
(2005950,68,33,7,15,'Bizi Mısırdan çıkardığın günlerdeki gibi, 2 Harikalar yarat halkın için.'),
(2005951,68,33,7,16,'Uluslar bunu görünce 2 Yaptıkları bunca zorbalıktan utanacaklar. 2 Elleriyle ağızlarını kapayacak, kulaklarını tıkayacaklar.'),
(2005952,68,33,7,17,'Yılanlar gibi, sürüngenler gibi toprak yalayacak, 2 Titreyerek sığınaklarından çıkacaklar. 2 Ey Tanrımız RAB, dehşet içinde sana dönecek 2 Ve senden korkacaklar.'),
(2005953,68,33,7,18,'Senin gibi suçları silen, 2 Kendi halkından geride kalanların isyanlarını bağışlayan başka tanrı var mı? 2 Sonsuza dek öfkeli kalmazsın, 2 Çünkü sadık olmaktan hoşlanırsın.'),
(2005954,68,33,7,19,'Bize yine acıyacaksın, 2 Çiğneyeceksin suçlarımızı ayak altında. 2 Bütün günahlarımızı denizin dibine atacaksın.'),
(2005955,68,33,7,20,'Geçmişte atalarımıza ant içtiğin gibi, 2 Yakup''un ve İbrahim''in torunları olan bizlere de 2 Verdiğin sözü tutacak ve sadık kalacaksın.'),
(2005956,68,34,1,1,'Ninova ile ilgili bildiri, Elkoşlu Nahumun görümünü anlatan kitaptır.'),
(2005957,68,34,1,2,'RAB kıskanç, öç alıcı bir Tanrıdır. 2 Öç alır ve gazapla doludur. Hasımlarından öç alır, 2 Düşmanlarına karşı öfkesi süreklidir.'),
(2005958,68,34,1,3,'RAB tez öfkelenmez ve çok güçlüdür. 2 Suçlunun suçunu asla yanına koymaz. Geçtiği yerde kasırgalar, fırtınalar kopar. 2 Onun ayaklarının tozudur bulutlar.'),
(2005959,68,34,1,4,'Bir buyrukla kurutur denizi, 2 Kurutur bütün ırmakları. Solar Başanın, Karmel Dağının yeşillikleri 2 Ve Lübnanın çiçekleri.'),
(2005960,68,34,1,5,'Dağlar RABbin önünde titrer, 2 Erir tepeler. Yer sarsılır önünde. 2 Dünya ve üzerinde yaşayanların tümü titrer.'),
(2005961,68,34,1,6,'Onun gazabına kim karşı durabilir, 2 Kim dayanabilir kızgın öfkesine? Ateş gibi dökülür öfkesi, 2 Kayaları paramparça eder.'),
(2005962,68,34,1,7,'RAB iyidir, 2 Sığınaktır sıkıntı anında. Korur kendisine sığınanları.'),
(2005963,68,34,1,8,'Ama Ninovayı azgın sellerle yok edecek, 2 Düşmanlarını karanlığa sürecek.'),
(2005964,68,34,1,9,'RABbe karşı neler tasarlarsanız, 2 Hepsini yok edecek. İkinci kez kimse karşı koyamayacak.'),
(2005965,68,34,1,10,'Birbirine dolaşmış dikenler gibi, 2 Kuru anız gibi, Yanıp biteceksiniz, ey ayyaşlar.'),
(2005966,68,34,1,11,'Ey Ninova, RABbe karşı kötülük tasarlayan, 2 Şer öğütleyen kişi senden çıktı.'),
(2005967,68,34,1,12,'RAB diyor ki, 2 ‹‹Asurlular güçlü ve çok olsalar bile, yok olup gidecekler. Ey halkım, seni sıkıntıya soktuysam da, bir daha sokmayacağım.'),
(2005968,68,34,1,13,'Şimdi boyunduruğunu parçalayıp üzerindeki bağları koparacağım.››'),
(2005969,68,34,1,14,'RAB, ‹‹Artık soyunu sürdürecek torunların olmasın›› 2 Diye buyurdu, ey Ninova. 2 ‹‹Tanrılarının tapınağındaki oyma ve dökme putları yok edeceğim›› diyor. ‹‹Mezarını hazırlayacağım. 2 Çünkü sen aşağılıksın.››'),
(2005970,68,34,1,15,'İşte, müjde getirenin ayakları dağları aşıp geliyor, 2 Size esenlik haberini getiriyor. Ey Yahudalılar, bayramlarınızı kutlayın, 2 Adak sözünüzü yerine getirin. 2 O kötü ulusun istilasına uğramayacaksınız bir daha. Çünkü o büsbütün yok edildi.'),
(2005971,68,34,2,1,'Saldırı altındasın, ey Ninova, surlarını koru, 2 Yolu gözle, belini doğrult, topla bütün gücünü.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2005972,68,34,2,2,'Çünkü RAB Yakupun soyunu 2 İsrailin eski görkemine kavuşturacak; Düşmanları onları perişan edip asmalarını harap etmiş olsa bile.'),
(2005973,68,34,2,3,'Askerlerinin kalkanları kıpkızıl, 2 Yiğitler allar kuşanmış. Savaş arabalarının demirleri hazırlık günü nasıl da parıldıyor! 2 Çam mızraklar sallanıyor havada.'),
(2005974,68,34,2,4,'Sokaklardan fırtına gibi geçiyor savaş arabaları, 2 Meydanlardan koşuşuyorlar her yöne, Şimşek gibi seğirtiyorlar. 2 Görünüşleri meşalelerden farksız.'),
(2005975,68,34,2,5,'Ninova Kralı topluyor seçkin askerlerini, 2 Ama sendeliyorlar yolda. Saldıranlar kent surlarına doğru seğirtiyor, 2 Siperler kuruluyor.'),
(2005976,68,34,2,6,'Irmakların kapıları açıldı 2 Ve yerle bir oldu saray.'),
(2005977,68,34,2,7,'Tanrının dediği oldu, soyup götürdüler kenti. 2 Güvercinler gibi inliyor kadın köleler, Göğüslerini döverek.'),
(2005978,68,34,2,8,'Kaçıp gidiyor Ninova halkı, 2 Boşalan bir havuzun suyu gibi, ‹‹Durun, durun!›› diye bağırıyorlar, 2 Ama geri dönüp bakan yok.'),
(2005979,68,34,2,9,'Yağmalayın altınını, gümüşünü, 2 Yok servetinin sonu. Her tür değerli eşyayla dolup taşıyor.'),
(2005980,68,34,2,10,'Yıkıldı, yerle bir oldu, viraneye döndü Ninova. 2 Eriyor yürekler, Bükülüyor dizler, titriyor bedenler, 2 Herkesin beti benzi soluyor.'),
(2005981,68,34,2,11,'Aslanların inine, 2 Yavru aslanların beslendiği yere ne oldu? Aslanla dişisinin ve yavrularının korkusuzca gezindiği yere ne oldu?'),
(2005982,68,34,2,12,'Aslan, yavrularına yetecek kadarını avladı, 2 Dişileri için avını boğazladı. Mağarasını avladıklarıyla, 2 İnini kurbanlarıyla doldurdu.'),
(2005983,68,34,2,13,'Her Şeye Egemen RAB, ‹‹Sana karşıyım›› diyor, 2 ‹‹Yakacağım savaş arabalarını, Dumanları tütecek. 2 Genç aslanlarını kılıç yiyip tüketecek. Yeryüzünde av bırakmayacağım sana 2 Ulaklarının sesi işitilmeyecek artık.››'),
(2005984,68,34,3,1,'Elleri kanlı kentin vay haline! 2 Yalanla, talanla dolu. Yağmalamaktan geri kalmıyor.'),
(2005985,68,34,3,2,'Kamçı şaklamaları, tekerlek gürültüleri, 2 Koşan atlar, sarsılan savaş arabaları,'),
(2005986,68,34,3,3,'Saldıran atlılar, çakan kılıçlar, 2 Parıldayan mızraklar, yığın yığın ölüler... Sayısız ceset. 2 Yürürken ayaklar takılıyor ölülere.'),
(2005987,68,34,3,4,'Her şey o alımlı, büyücü fahişenin sınırsız ahlaksızlığından oldu. 2 Fahişeliğiyle ulusları, büyüleriyle halkları kendine tutsak etti.'),
(2005988,68,34,3,5,'Her Şeye Egemen RAB diyor ki, 2 ‹‹Sana karşıyım, ey Ninova! Savuracağım eteklerini yüzüne. 2 Uluslara çıplaklığını, Halklara ayıp yerlerini göstereceğim.'),
(2005989,68,34,3,6,'Seni pislikle sıvayıp rezil edeceğim. 2 Dehşetle seyredecek herkes seni.'),
(2005990,68,34,3,7,'Seni kim görse kaçacak. 2 ‹Harabeye döndü Ninova› diyecekler, ‹Kim dövünecek onun için? 2 Nereden bulalım onu avutacak birilerini?› ››'),
(2005991,68,34,3,8,'Sen No-Amondan daha mı üstünsün? 2 O kent ki, kanallar arasındaydı, Suyla çevrelenmişti, 2 Kalesi Nil Irmağı, surlarıysa sulardı.'),
(2005992,68,34,3,9,'Kûş ve Mısır onun sınırsız gücünün kaynağıydı. 2 Pût ve Luv da yandaşlarıydı.'),
(2005993,68,34,3,10,'Öyleyken tutsak düştü, halkı sürüldü. 2 Yavruları köşe başlarında paramparça edildi. Soyluları için kura çekildi, 2 Zincire vuruldu ileri gelenleri.'),
(2005994,68,34,3,11,'Acıyla kendinden geçeceksin, ey Ninova, 2 Düşmanlarından korunacak yer arayacaksın.'),
(2005995,68,34,3,12,'Senin kalelerin incir ağacının ilk olgunlaşan meyvesi gibidir. 2 Bir silkeleyişte yiyenin ağzına düşecekler.'),
(2005996,68,34,3,13,'Askerlerine bak! Kadın gibi hepsi. 2 Kapıların ardına kadar düşmana açık. Ateş yiyip bitirmiş kapı sürgülerini.'),
(2005997,68,34,3,14,'Kuşatma vakti için su biriktir kendine, 2 Savunmanı güçlendir. Tuğla yapmak için kili çiğne, 2 Kalıpları hazırla.'),
(2005998,68,34,3,15,'Orada ateş seni yiyip bitirecek, 2 Kılıç seni kesip biçecek. Genç çekirgelerin yiyip bitirdiği ekin gibi yok olacaksın. Çekirgeler gibi, genç çekirgeler gibi çoğalmalısın.'),
(2005999,68,34,3,16,'Tüccarlarının sayısı gökteki yıldızlardan çok. 2 Ama düşmanların genç çekirgeler gibi ülkeyi talan edip gidecekler.'),
(2006000,68,34,3,17,'Koruyucularınla görevlilerin serin günlerde duvarlara konan çekirgeler gibidir, 2 Güneş doğunca uçup kayıplara karışan çekirge sürüsü gibi.'),
(2006001,68,34,3,18,'Ey Asur Kralı, yöneticilerin öldü, 2 Uyudu sonsuza dek soyluların. Halkın dağlara dağıldı. 2 Onları toplayacak kimse yok.'),
(2006002,68,34,3,19,'Uğradığın felaketten kurtuluş yok, yaraların ölümcül. 2 Başına gelenleri duyanlar sevinçle el ovuşturuyorlar. Çünkü dinmeyen vahşetinden kim kaçabildi ki?'),
(2006003,68,35,1,1,'Peygamber Habakkuka bir görümde verilen bildiridir.'),
(2006004,68,35,1,2,'Ya RAB, ne zamana dek seni yardıma çağıracağım, 2 Beni duymuyor musun? 2 ‹‹Zorbalık var›› diye haykırıyorum sana, 2 Ama kurtarmıyorsun!'),
(2006005,68,35,1,3,'Bunca kötülüğü bana neden gösteriyorsun, 2 Nasıl hoş görürsün bunca haksızlığı? 2 Nereye baksam şiddet ve zorbalık var. 2 Kavgaların, çekişmelerin sonu gelmiyor.'),
(2006006,68,35,1,4,'Bu yüzden yasa işlemez oldu, 2 Bir türlü yerini bulmuyor hak. 2 Kötüler doğruları kıskaca almış 2 Ve böylece adalet saptırılıyor.'),
(2006007,68,35,1,5,'‹‹Bakın öbür uluslara, 2 Gördüklerinize büsbütün şaşacaksınız. 2 Sizin gününüzde öyle işler yapacağım ki, 2 Anlatsalar inanmayacaksınız.'),
(2006008,68,35,1,6,'Başkalarına ait toprakları ele geçirmek için 2 Dünyanın dört yanına yürüyen o acımasız ve saldırgan ulusu, 2 Kildanileri güçlendireceğim.'),
(2006009,68,35,1,7,'Dehşetli ve korkunçturlar, 2 Gururlu ve başlarına buyrukturlar.'),
(2006010,68,35,1,8,'Parstan çeviktir atları, 2 Aç kurttan daha azgın. 2 Atlıları yeri deşerek geliyor uzaklardan, 2 Avına saldıran kartal gibi uçuyorlar,'),
(2006011,68,35,1,9,'Yağmalamak için geliyor hepsi. 2 Orduları çöl rüzgarı gibi ilerliyor 2 Ve kum gibi tutsak topluyorlar.'),
(2006012,68,35,1,10,'Küçümsüyorlar kralları, 2 Yöneticilerle alay ediyorlar. 2 Dudak büküyorlar bütün surlu kentlere, 2 Önlerine toprak yığıp onları ele geçiriyorlar.'),
(2006013,68,35,1,11,'Rüzgar gibi geçip gidiyorlar. 2 Bu suçlu adamların ilahları kendi güçleridir.››'),
(2006014,68,35,1,12,'Ya RAB, kutsal Tanrım, 2 Öncesizlikten beri var olan sen değil misin? 2 Sen ölmeyeceksin. 2 Ya RAB, bizi yargılamak için Kildanileri mi seçtin? 2 Ey sığınağımız, onlara mı verdin cezalandırma yetkisini? ölmeyeceğiz››.'),
(2006015,68,35,1,13,'Kötüye bakamayacak kadar saftır gözlerin. 2 Haksızlığı hoş göremezsin. 2 Öyleyse nasıl hoş görürsün 2 Bu hain adamları? 2 Doğrular kötülere yem olurken 2 Neden susuyorsun?'),
(2006016,68,35,1,14,'İnsanları denizdeki balıklara, 2 Yöneticiden yoksun sürüngenlere çevirdin.'),
(2006017,68,35,1,15,'Kildaniler onları oltayla, ağla, 2 Serpme ağla tutar gibi tutuyor 2 Ve sevinç çığlıkları atıyorlar.'),
(2006018,68,35,1,16,'Kurban kesiyorlar ağlarına bu yüzden. 2 Kendilerine lezzetli ve bol yiyecek sağlayan ağları için buhur yakıyorlar.'),
(2006019,68,35,1,17,'Ağlarını durmadan boşaltmaya, 2 Ulusları acımasızca öldürmeye devam edecekler mi?'),
(2006020,68,35,2,1,'Nöbet yerinde, gözcü kulesinde durayım, 2 Bakayım RAB bana ne diyecek, 2 Yakınmalarıma ne yanıt verecek göreyim.'),
(2006021,68,35,2,2,'Şöyle yanıtladı RAB: 2 ‹‹Göreceklerini taş levhalara oyarak yaz. 2 Öyle ki, herkes bir çırpıda okusun.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006022,68,35,2,3,'Bu olayların zamanı gelmedi henüz. 2 Sonun belirtileridir bunlar ve yalan değildir. 2 Gecikiyormuş gibi görünse de bekle olacakları, 2 Kesinlikle olacak, gecikmeyecek.'),
(2006023,68,35,2,4,'Bakın şu övüngen kişiye, niyeti iyi değildir. 2 Ama doğru kişi sadakatiyle yaşayacaktır.'),
(2006024,68,35,2,5,'Servet aldatıcıdır. 2 Küstahlar kalıcı değildir; 2 Açgözlüdürler ölüler diyarı gibi 2 Ve ölüm gibi hiç doymazlar. 2 Ülkeleri ele geçirip halkları tutsak alırlar.'),
(2006025,68,35,2,6,'Tutsak alınanlar onları küçümseyip alay etmeyecekler mi? 2 ‹Kendisine ait olmayanı ele geçirenin, 2 Haraç alarak zenginleşenin vay haline! 2 Daha ne kadar sürecek bu?› demeyecekler mi?'),
(2006026,68,35,2,7,'Haraca kestikleriniz ansızın ayaklanmayacak mı? 2 Uyanıp yakanıza yapışmayacaklar mı? 2 İşte o zaman onlar için çapul malı gibi olacaksınız.'),
(2006027,68,35,2,8,'Birçok ulusu soyduğunuz, 2 Kan döktüğünüz, 2 Ülkelere, kentlere ve oralarda yaşayan herkese zorbalık ettiğiniz için, 2 Halklardan sağ kalanlar da sizi soyacaklar.'),
(2006028,68,35,2,9,'Evini haksız kazançla dolduranın, 2 Felaketten kaçmak için yuvasını yüksek yere kuranın vay haline!'),
(2006029,68,35,2,10,'Birçok halkı kıyıma uğratmakla 2 Kendi soyunuzu utanca boğdunuz, 2 Kendi yıkımınızı hazırladınız.'),
(2006030,68,35,2,11,'Duvar taşları bile haykıracak bunu 2 Ve yankılanacak ahşap kirişler.'),
(2006031,68,35,2,12,'Kan dökerek kentler kuranın, 2 Zorbalıkla beldeler yapanın vay haline!'),
(2006032,68,35,2,13,'Halkların bütün emeklerinin yanması, 2 Ulusların bütün çabalarının boşa gitmesi 2 Her Şeye Egemen RABbin işi değil mi?'),
(2006033,68,35,2,14,'Çünkü sular denizi nasıl dolduruyorsa, 2 Dünya da RABbin yüceliğinin bilgisiyle dolacak.'),
(2006034,68,35,2,15,'Çıplak bedenlerini seyretmek için 2 Komşularına içki içirip sarhoş eden, 2 İçkiye zehir bile katan sizlerin vay haline!'),
(2006035,68,35,2,16,'Onur yerine utanca boğulacaksınız. 2 Şimdi sıra sizde, için de çıplaklığınız görünsün. 2 RAB size sağ elindeki ceza dolu kâseden içirecek. 2 Onurunuz kırılacak, rezil olacaksınız.'),
(2006036,68,35,2,17,'Lübnana ettiğiniz zorbalık kendi başınıza gelecek. 2 Telef ettiğiniz hayvanlar sizi dehşete düşürecek. 2 Çünkü insan kanı döktünüz, 2 Ülkelere, kentlere ve oralarda yaşayan herkese zorbalık ettiniz.'),
(2006037,68,35,2,18,'İnsanın biçim verdiği oyma ya da dökme putun ne yararı var ki aldatmaktan başka? 2 Putu yapan, yaptığına güvenir, 2 Ama yaptığı ne ki, dilsiz puttan başka.'),
(2006038,68,35,2,19,'Tahta puta, ‹Canlan!› diyenin, 2 Dilsiz taşa, ‹Uyan› diyenin 2 Vay haline! 2 Put yol gösterebilir mi? 2 Altınla, gümüşle kaplanmış, 2 Ama içinde yaşam soluğu yok.'),
(2006039,68,35,2,20,'Oysa RAB kutsal tapınağındadır. 2 Sussun bütün dünya O''nun önünde.››'),
(2006040,68,35,3,1,'|iPeygamber Habakkukun Duası - Şigyonotfç |iMakamında|r'),
(2006041,68,35,3,2,'Ya RAB, ününü duydum ve yaptıklarının karşısında ürperdim. 2 Günümüzde de aynı şeyleri yap, ya RAB, 2 Şimdi herkes bilsin neler yapabildiğini. 2 Öfkeliyken merhametini anımsa! biçimi olduğu sanılıyor.'),
(2006042,68,35,3,3,'Tanrı Temandan, 2 Kutsal Tanrı Paran Dağından geldi. |iSela 2 Görkemi kapladı gökleri, 2 Ona sunulan övgüler dünyayı doldurdu. sanılıyor.'),
(2006043,68,35,3,4,'Güneş gibi parıldıyor, 2 Elleri ışık saçıyor. 2 Gücünün gizi ellerinde.'),
(2006044,68,35,3,5,'Yayılıyor salgın hastalıklar önüsıra, 2 Ardısıra da ölümcül hastalıklar.'),
(2006045,68,35,3,6,'Duruşuyla dünyayı sarstı, 2 Titretti ulusları bakışıyla, 2 Yaşlı dağlar darmadağın oldu, 2 Dünya kurulalı beri var olan tepeler Ona baş eğdi. 2 Tanrının yolları değişmezdir.'),
(2006046,68,35,3,7,'Kuşan çadırlarını çaresizlik içinde gördüm, 2 Midyan konutları korkudan titriyordu.'),
(2006047,68,35,3,8,'Ya RAB, nehirlere mi öfkelendin? 2 Gazabın ırmaklara mı? 2 Yoksa denize mi kızdın da, 2 Atlarına, yenilmez savaş arabalarına bindin?'),
(2006048,68,35,3,9,'Gerdin yayını, 2 Okların içtiğin antlardır. |iSela 2 Yeryüzünü akarsularla yardın.'),
(2006049,68,35,3,10,'Sarsıldı dağlar seni görünce, 2 Seller her yanı süpürüp geçti. 2 Engin denizler gürledi, dalgalar yükseldi.'),
(2006050,68,35,3,11,'Uçuşan oklarının pırıltısından, 2 Parlayan mızrağının ışıltısından, 2 Yerlerinde durakaldı güneş ve ay.'),
(2006051,68,35,3,12,'Gazap içinde ilerledin yeryüzünde, 2 Ulusları öfkeyle çiğneyip ezdin.'),
(2006052,68,35,3,13,'Kendi halkını, seçtiğin ulusu kurtarmaya geldin. 2 Kötü soyun başını ezdin, 2 Soydun onu tepeden tırnağa. |iSela'),
(2006053,68,35,3,14,'Başını kendi mızrağıyla deldin. 2 Askerleri fırtına gibi gelmişti bizi dağıtmaya, 2 Saklanan düşkünleri yok etmiş gibi seviniyorlardı.'),
(2006054,68,35,3,15,'Sense atlarınla çiğneyip geçtin büyük denizleri, 2 Sularını köpürterek...'),
(2006055,68,35,3,16,'Sesini duyunca yüreğim hopladı, 2 Seğirdi dudaklarım, 2 Kemiklerim eridi sanki, 2 Çözüldü dizlerimin bağı. 2 Ama bize saldıran halkın felakete uğrayacağı günü 2 Sabırla bekleyeceğim.'),
(2006056,68,35,3,17,'Tomurcuklanmasa incir ağaçları, 2 Asmalar üzüm vermese, 2 Boşa gitse de zeytine verilen emek, 2 Tarlalar ürün vermese de, 2 Boşalsa da davar ağılları, 2 Sığır kalmasa da ahırlarda,'),
(2006057,68,35,3,18,'Ben yine RAB sayesinde sevineceğim, 2 Kurtuluşumun Tanrısı sayesinde sevinçten coşacağım.'),
(2006058,68,35,3,19,'Egemen RAB gücümdür benim. 2 Ayaklarıma geyik ayağının çevikliğini verir. 2 Aşırtır beni yükseklerden. |iMüzik şefi için: Telli sazlar eşliğinde söylenecek.|r'),
(2006059,68,36,1,1,'RAB, Yahuda Kralı Amon oğlu Yoşiya zamanında Hizkiya oğlu Amarya oğlu Gedalya oğlu Kuşi oğlu Sefanyaya şöyle seslendi:'),
(2006060,68,36,1,2,'‹‹Yeryüzünden her şeyi silip süpüreceğim.'),
(2006061,68,36,1,3,'İnsanları, hayvanları, 2 Gökteki kuşları, 2 Denizdeki balıkları, 2 Kötüleri ve onların günah tuzaklarını silip süpüreceğim. 2 Yok edeceğim insanı yeryüzünden.›› 2 İşte böyle diyor RAB.'),
(2006062,68,36,1,4,'‹‹Elimi Yahuda ve Yeruşalimde yaşayanlara karşı uzatacağım. 2 Baaldan kalan izleri, 2 Putperest din adamlarıyla kâhinlerin adını, 2 Damlardan gök cisimlerine tapınanları, 2 Hem benim adıma, hem de Molek putu adına ant içip tapınanları, 2 Yolumdan dönenleri, 2 Bana yönelmeyenleri, 2 Kılavuzluğumu istemeyenleri buradan yok edeceğim.››'),
(2006063,68,36,1,7,'Susun Egemen RABbin önünde, 2 Çünkü Onun günü yaklaştı. 2 RAB bir kurban hazırladı, 2 Konuklarını çağırdı.'),
(2006064,68,36,1,8,'‹‹O kurban günü›› diyor RAB, 2 ‹‹Önderleri, kral oğullarını, 2 Yabancıların geleneklerine uyanları 2 Cezalandıracağım.'),
(2006065,68,36,1,9,'İlahların tapınaklarını zorbalık ve hileyle dolduran putperestleri 2 O gün cezalandıracağım. (bkz. 1Sa.5:4-5).'),
(2006066,68,36,1,10,'Diyorum ki, o gün kentin Balık Kapısından çığlıklar, 2 İkinci Mahalleden feryatlar 2 Ve tepelerden büyük çatırtılar yükselecek.›› 2 İşte böyle diyor RAB.'),
(2006067,68,36,1,11,'‹‹Kentin aşağı mahallesinde oturanlar, feryat edin. 2 Bütün tüccarlarınız yok olacak, 2 Gümüş ticareti yapanların hepsi mahvolacak.'),
(2006068,68,36,1,12,'O gün kandille arayacağım Yeruşalimin her yanını, 2 İçlerinden, ‹RAB bir şey yapmaz, 2 Ne iyilik eder ne kötülük› 2 Diyen o rahatına düşkün aymazları cezalandıracağım. gibi››.'),
(2006069,68,36,1,13,'Servetleri yağmalanacak. 2 Viraneye dönecek evleri. 2 Yaptıkları evlerde oturamayacak, 2 Diktikleri bağların şarabını içemeyecekler.››'),
(2006070,68,36,1,14,'RABbin büyük günü yaklaştı, 2 Yaklaştı ve çabucak geliyor. 2 Dinleyin, RABbin gününde 2 En yiğit asker bile acı acı feryat edecek.'),
(2006071,68,36,1,15,'Öfke günü o gün! 2 Acı ve sıkıntı, 2 Yıkım ve felaket, 2 Zifiri karanlık bir gün olacak, 2 Bulutlu, koyu karanlık bir gün.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006072,68,36,1,16,'Surlu kentlere, köşelerdeki yüksek kulelere karşı 2 Savaş borularının çalındığı, 2 Savaş naralarının atıldığı gündür.'),
(2006073,68,36,1,17,'RAB diyor ki, ‹‹İnsanları öyle bir felakete uğratacağım ki, 2 Körler gibi, nereye gittiklerini göremeyecekler. 2 Çünkü bana karşı günah işlediler. 2 Su gibi akacak kanları, 2 Bedenleri yerde çürüyecek.››'),
(2006074,68,36,1,18,'RAB''bin öfke gününde, 2 Altınları da gümüşleri de 2 Onları kurtaramayacak. 2 RAB''bin kıskançlık ateşi bütün ülkeyi yakıp yok edecek. 2 RAB ülkede yaşayanların hepsini korkunç bir sona uğratacak.'),
(2006075,68,36,2,1,'Ey utanmaz ulus, toparlan! 2 Hakkında ferman çıkmadan, 2 Gün saman ufağı gibi geçip gitmeden, 2 RABbin kızgın öfkesi üzerine dökülmeden, 2 RABbin öfke günü gelmeden toparlan.'),
(2006076,68,36,2,3,'Ey RABbin ilkelerini yerine getirenler, 2 Ülkedeki bütün alçakgönüllüler, RABbe yönelin. 2 Doğruluğu ve alçakgönüllülüğü amaç edinin. 2 Belki RABbin öfke gününde kurtulabilirsiniz.'),
(2006077,68,36,2,4,'Gazze bomboş kalacak, 2 Viraneye dönecek Aşkelon, 2 Boşaltılacak Aşdot öğle vakti, 2 Ekron temelden yıkılacak.'),
(2006078,68,36,2,5,'Deniz kıyısında yaşayan 2 Keretfç ulusunun vay haline! 2 Ey Filist ülkesi Kenan, 2 RABbin yargısı sana karşıdır. 2 Hepinizi yok edecek RAB, 2 Ülkede yaşayan kimse kalmayacak.'),
(2006079,68,36,2,6,'Deniz kıyısındaki ülkeniz, 2 Çoban barınaklarıyla sürü ağıllarının bulunduğu otlaklara dönecek;'),
(2006080,68,36,2,7,'Yahuda oymağından sağ kalanların eline geçecek. 2 Orada otlatacaklar sürülerini, 2 Aşkelonun evlerinde geceleyecekler. 2 Çünkü Tanrıları RAB onları kayıracak. 2 Eski gönençlerine kavuşturacak onları.'),
(2006081,68,36,2,8,'İsrailin Tanrısı Her Şeye Egemen RAB şöyle diyor: 2 ‹‹Moavlıların halkımı nasıl aşağıladığını, 2 Ammon halkının onlara nasıl hakaret ettiğini, 2 Onları nasıl alaya aldığını 2 Topraklarını nasıl tehdit ettiğini duydum. 2 Varlığım hakkı için, 2 Moav kesinlikle Sodom gibi, 2 Ammon da Gomora gibi olacak. 2 Otlarla, tuz çukurlarıyla dolacak, 2 Sonsuza dek virane kalacak. 2 Mallarını halkımdan geride kalanlar yağmalayacak. 2 Topraklarını ulusumdan sağ kalanlar miras alacak.››'),
(2006082,68,36,2,10,'Gururlanmalarının, 2 Her Şeye Egemen RABbin halkını aşağılayıp 2 Alay etmelerinin karşılığı bu olacak.'),
(2006083,68,36,2,11,'Dehşete düşürecek RAB onları, 2 Yeryüzünün bütün ilahlarını yok edecek. 2 Kıyılardaki bütün uluslar, 2 Bulundukları yerde Ona tapınacaklar.'),
(2006084,68,36,2,12,'‹‹Ey Kûşlular, 2 Siz de benim kılıcımla öleceksiniz›› diyor RAB.'),
(2006085,68,36,2,13,'RAB elini kuzeye doğru uzatıp 2 Asuru yok edecek. 2 Ninovayı viraneye, 2 Çöl gibi kurak bir alana çevirecek.'),
(2006086,68,36,2,14,'Orası sürülerin, her türlü hayvanın yattığı yer olacak. 2 Sütun başlıklarında ishakkuşları, kır baykuşları barınacak. 2 Sesleri pencerelerde yankılanacak, 2 Yıkıntılar dolduracak eşiklerin önünü, 2 Sedir kirişler ortaya çıkacak.'),
(2006087,68,36,2,15,'İşte budur güvenlikte olduğunu sanan, 2 ‹‹Bir ben varım, benden başkası yok›› diyen eğlence düşkünü kent. 2 Nasıl da viraneye döndü, 2 Yabanıl hayvanlara barınak oldu! 2 Yanından her geçen gördüğü dehşetten irkiliyor.'),
(2006088,68,36,3,1,'Başkaldıran, yozlaşan, acımasız kentin vay haline!'),
(2006089,68,36,3,2,'Söz dinlemedi, ders almadı, RABbe güvenmedi, 2 Tanrısına sığınmadı.'),
(2006090,68,36,3,3,'Yöneticileri kükreyen aslanlar, 2 Önderleri akşam gezen aç kurtlar gibi, 2 Sabaha bir şey bırakmazlar.'),
(2006091,68,36,3,4,'Peygamberleri sorumsuz ve güvenilmezdir. 2 Kâhinleri kutsal olanı kirletip, 2 Yasayı çarpıtırlar.'),
(2006092,68,36,3,5,'Ama adil RAB hâlâ o kentte; 2 O haksızlık etmez, 2 Aksatmadan dağıtır adaletini her yeni günün sabahında. 2 Ne var ki, bu yetmiyor haksızları utandırmaya.'),
(2006093,68,36,3,6,'RAB diyor ki, ‹‹Ulusları yok ettim, 2 Kalelerini yıktım, sokaklarını harap ettim. 2 O sokaklardan geçen kimse yok artık. 2 Kentleri viraneye döndü, 2 Eser kalmadı insandan.'),
(2006094,68,36,3,7,'Halkım benden korkar, 2 Ders alır bundan dedim. 2 O zaman konutlarına dokunmaz, 2 Onları tasarladığım cezaya çarptırmazdım. 2 Ama her türlü kötülüğü yapmaya istekli görünüyorlar.››'),
(2006095,68,36,3,8,'Bu yüzden, ‹‹Bekleyin de görün›› diyor RAB, 2 ‹‹Ulusları yargılayacağım günü bekleyin. 2 Ulusları toplamaya, 2 Krallıkları bir araya getirmeye, 2 Gazabımı, kızgın öfkemi 2 Üzerlerine dökmeye karar verdim. 2 Çünkü kıskançlığımın ateşi bütün dünyayı yiyip bitirecek.'),
(2006096,68,36,3,9,'O zaman, hep birlikte beni adımla çağırmaları, 2 Omuz omuza bana hizmet etmeleri için, 2 Halkların dudaklarını pak kılacağım.'),
(2006097,68,36,3,10,'Dağılmış olan, bana tapan halkım, 2 Kûş ırmaklarının ötesinden 2 Bana sunular getirecek.'),
(2006098,68,36,3,11,'Halkım bana yaptığı bunca kötülük yüzünden utandırılmayacak o gün. 2 Çünkü gururlu, küstah olanları uzaklaştıracağım aralarından. 2 Kutsal dağımda bir daha böbürlenmeyecekler.'),
(2006099,68,36,3,12,'Orada sadece benim adıma sığınan uysal ve alçakgönüllüleri bırakacağım.'),
(2006100,68,36,3,13,'İsraillilerden geride kalanlar haksızlık etmeyecek, 2 Yalan söylemeyecek, 2 Kimseyi aldatmayacak, 2 Tok karna yatacaklar ve onları korkutan olmayacak.››'),
(2006101,68,36,3,14,'Ey Siyon kızı, ezgiler söyle! 2 Ey İsrail, haykır! 2 Yürekten sevin, sevinçle coş, 2 Ey Yeruşalim kızı!'),
(2006102,68,36,3,15,'RAB senin cezanı kaldırdı, 2 Kovdu düşmanlarını. 2 İsrailin Kralı RAB seninle. 2 Korkma artık kötülükten.'),
(2006103,68,36,3,16,'O gün Yeruşalime denecek ki, 2 ‹‹Korkma, ey Siyon, gevşemesin ellerin.'),
(2006104,68,36,3,17,'Tanrın RAB, o güçlü Kurtarıcı seninle. 2 Alabildiğine sevinecek senin için, 2 Sevgisiyle seni yenileyecek, ezgilerle coşacak.›› ‹‹Susacak››.'),
(2006105,68,36,3,18,'RAB, ‹‹Bayramlar için çektiğiniz özlemleri sona erdireceğim›› diyor, 2 ‹‹Bunlar sizin için ağırlık ve utançtır. 2 Sizi ezenlerin tümünü cezalandıracağım o gün. 2 Düşkünleri kurtaracak, sürgünleri toplayacağım. 2 Utanç içinde kaldıkları bütün ülkelerde 2 Onları yüceltip onurlandıracağım. 2 O zaman sizi toplayıp yurdunuza geri getireceğim. 2 Göreceksiniz, sizi yeniden bayındır kılacak, 2 Dünyanın bütün halkları arasında yüceltip onurlandıracağım.››'),
(2006106,68,37,1,1,'Kral Dariusun krallığının ikinci yılında, altıncı ayın birinci günü RAB Peygamber Hagay aracılığıyla Şealtielin torunu Yahuda Valisi Zerubbabil ve Yehosadak oğlu Başkâhin Yeşuya seslendi:'),
(2006107,68,37,1,2,'‹‹Her Şeye Egemen RAB diyor ki, ‹Bu halk, RABbin Tapınağını yeniden kurmak için vakit daha gelmedi diyor.› ››'),
(2006108,68,37,1,3,'Sonra RAB, Peygamber Hagay aracılığıyla şöyle seslendi:'),
(2006109,68,37,1,4,'‹‹Bu tapınak yıkık durumdayken, sizin ağaç kaplamalı evlerinizde oturmanızın sırası mı?››'),
(2006110,68,37,1,5,'Her Şeye Egemen RAB diyor ki, ‹‹Şimdi tuttuğunuz yolları iyi düşünün!'),
(2006111,68,37,1,6,'Çok ektiniz ama az biçtiniz; yiyorsunuz ama doyamıyorsunuz, içiyorsunuz ama neşelenemiyorsunuz; giyiniyorsunuz ama ısınamıyorsunuz; ücretinizi alıyorsunuz ama paranızı sanki delik keseye koyuyorsunuz.››'),
(2006112,68,37,1,7,'Her Şeye Egemen RAB, ‹‹Tuttuğunuz yolları iyi düşünün!›› diyor, ‹‹Dağlara çıkıp kütük getirin, tapınağı yeniden kurun. Öyle ki, ondan hoşnut olayım, yüceltileyim.'),
(2006113,68,37,1,9,'Bol ürün umdunuz ama az topladınız. Eve ne getirdiyseniz üfleyip dağıttım. Acaba neden?›› Böyle soruyor Her Şeye Egemen RAB. ‹‹Yıkık duran tapınağımdan ötürü! Oysa hepiniz kendi evinizle uğraşıyorsunuz.'),
(2006114,68,37,1,10,'İşte bunun içindir ki, gök çiyini, toprak ürününü sizden esirgiyor.'),
(2006115,68,37,1,11,'Ülkeyi -dağlarını, tahılını, yeni şarabını, zeytinyağını, toprağın verdiği ürünleri, insanlarını, hayvanlarını, ellerinizin bütün emeğini- kuraklıkla cezalandırdım.››'),
(2006116,68,37,1,12,'Şealtielin torunu Zerubbabil, Yehosadak oğlu Başkâhin Yeşu ve sürgünden dönen halkın tümü Tanrıları RABbin sözüne, Onun tarafından gönderilen Peygamber Hagayın sözlerine kulak verdiler. Halk RABden korktu.'),
(2006117,68,37,1,13,'Sonra RABbin ulağı Hagay, RABbin şu sözlerini halka bildirdi: ‹‹RAB, ‹Ben sizinle birlikteyim› diyor.››'),
(2006118,68,37,1,14,'Böylece RAB Şealtiel''in torunu Yahuda Valisi Zerubbabil''i, Yehosadak oğlu Başkâhin Yeşu''yu ve sürgünden dönen halkın tümünü bu konuda harekete geçirdi. Darius''un krallığının ikinci yılında, altıncı ayın yirmi dördüncü günü gelip Tanrıları Her Şeye Egemen RAB''bin Tapınağı''nda işe başladılar.'),
(2006119,68,37,2,1,'Yedinci ayın yirmi birinci günü RAB Peygamber Hagay aracılığıyla şöyle seslendi:'),
(2006120,68,37,2,2,'‹‹Şealtielin torunu Yahuda Valisi Zerubbabile, Yehosadak oğlu Başkâhin Yeşuya ve sürgünden dönen halka de ki,'),
(2006121,68,37,2,3,'‹Aranızda bu tapınağı önceki görkemiyle gören kaldı mı? Şimdi size nasıl görünüyor? Bir hiç olarak görünmüyor mu?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006122,68,37,2,4,'Şimdi sen, ey Zerubbabil, yüreklen!› RAB böyle diyor. ‹Ey Yehosadak oğlu Başkâhin Yeşu, yüreklen! Ey ülke halkı, yüreklen!› RAB böyle diyor. ‹İşi sürdürün. Çünkü ben sizinle birlikteyim.› Böyle diyor Her Şeye Egemen RAB.'),
(2006123,68,37,2,5,'‹Mısırdan çıktığınızda, size bu konuda söz verdim. Ruhum aranızdadır. Korkmayın!›'),
(2006124,68,37,2,6,'‹‹Her Şeye Egemen RAB diyor ki, ‹Kısa zamanda bir kez daha yeri, göğü, denizi, karayı sarsacağım.'),
(2006125,68,37,2,7,'Bütün ulusları sarsacağım, değerli eşyalarını buraya getirecekler. Ben de bu tapınağı görkemle dolduracağım.› Böyle diyor Her Şeye Egemen RAB.'),
(2006126,68,37,2,8,'‹Gümüş de, altın da benim› diyor Her Şeye Egemen RAB.'),
(2006127,68,37,2,9,'‹Yeni tapınağın görkemi, öncekinden daha büyük olacak. Buraya esenlik vereceğim.› Böyle diyor Her Şeye Egemen RAB.›› özlediği kişi buraya gelecek.››'),
(2006128,68,37,2,10,'Dariusun krallığının ikinci yılında, dokuzuncu ayın yirmi dördüncü günü RAB, Peygamber Hagaya seslendi:'),
(2006129,68,37,2,11,'‹‹Her Şeye Egemen RAB diyor ki, ‹Kâhinlere yasayla ilgili şu soruyu sor:'),
(2006130,68,37,2,12,'Eğer biri giysisinin kıvrımları arasında kutsanmış et taşır ve o kıvrım ekmeğe, yemeğe, şaraba, zeytinyağına ya da başka bir yiyeceğe değerse, o yiyecek kutsal olur mu?› ›› Kâhinler, ‹‹Hayır›› diye yanıtladılar.'),
(2006131,68,37,2,13,'Hagay konuşmasını şöyle sürdürdü: ‹‹Ölüye dokunduğu için kirli sayılan biri, bu yiyeceklerden birine dokunursa, o yiyecek kirlenmiş olur mu?›› Kâhinler, ‹‹Evet, kirlenmiş olur›› diye karşılık verdiler.'),
(2006132,68,37,2,14,'Bunun üzerine Hagay şöyle dedi: ‹‹RAB, ‹Bu halk, bu ulus gözümde böyledir› diyor, ‹Her yaptıkları, sunakta her sundukları da kirlidir.› ››'),
(2006133,68,37,2,15,'‹‹ ‹Bugüne dek olanları iyi düşünün; RABbin Tapınağında taş üstüne taş konulmadan önce, yirmi ölçeklik bir tahıl yığınına gelen biri, yalnızca on ölçek bulurdu; şarap teknesinden elli ölçek çıkarmaya varan biri, yalnızca yirmi ölçek bulurdu.'),
(2006134,68,37,2,17,'Ellerinizin bütün emeğini samyeliyle, küfle, doluyla cezalandırdım. Yine de bana dönmediniz.› RAB böyle diyor.'),
(2006135,68,37,2,18,'‹Bugünden, dokuzuncu ayın yirmi dördüncü gününden, RABbin Tapınağının temelinin atıldığı günden başlayarak olacakları iyi düşünün.'),
(2006136,68,37,2,19,'Ambarda hiç tohum kaldı mı? Asma, incir, nar, zeytin ağaçları bugüne dek ürün verdi mi? ‹‹ ‹Bugünden başlayarak üzerinize bereket yağdıracağım.› ››'),
(2006137,68,37,2,20,'Ayın yirmi dördüncü günü RAB Hagaya ikinci kez seslendi:'),
(2006138,68,37,2,21,'‹‹Yahuda Valisi Zerubbabile de ki, ben yeri, göğü sarsmak üzereyim.'),
(2006139,68,37,2,22,'Kralların tahtlarını devireceğim, yabancı ulusların gücünü yok edeceğim. Savaş arabalarıyla sürücülerini de devireceğim; atlarla binicileri düşecek, hepsi kardeşinin kılıcıyla öldürülecek.'),
(2006140,68,37,2,23,'‹‹Her Şeye Egemen RAB ‹O gün seni alacağım, ey Şealtiel''in torunu kulum Zerubbabil› diyor, ‹Ve seni mühür yüzüğü gibi yapacağım. Çünkü ben seni seçtim.› Böyle diyor Her Şeye Egemen RAB.››'),
(2006141,68,38,1,1,'Dariusun krallığının ikinci yılının sekizinci ayında RAB İddo oğlu Berekya oğlu Peygamber Zekeriya aracılığıyla şöyle seslendi:'),
(2006142,68,38,1,2,'‹‹RAB atalarınıza çok öfkelendi.'),
(2006143,68,38,1,3,'Bu nedenle halka de ki, ‹Her Şeye Egemen RAB, bana dönün, ben de size dönerim diyor.'),
(2006144,68,38,1,4,'Atalarınız gibi davranmayın! Önceki peygamberler, Her Şeye Egemen RAB kötü yollarınızdan ve kötü uygulamalarınızdan dönün diyor, diyerek onları uyardılar. Ne var ki, onlar dinlemediler, bana aldırış etmediler. Böyle diyor RAB.'),
(2006145,68,38,1,5,'Hani atalarınız nerede? Peygamberler de sonsuza kadar mı yaşar?'),
(2006146,68,38,1,6,'Peygamber kullarıma buyurduğum sözler ve kurallar atalarınıza ulaşmadı mı?› ‹‹Onlar da dönüp, ‹Her Şeye Egemen RAB yollarımıza ve uygulamalarımıza bakarak bizim için ne düşündüyse aynen yaptı› dediler.››'),
(2006147,68,38,1,7,'Dariusun krallığının ikinci yılında, on birinci ay olan Şevat ayının yirmi dördüncü günü RAB İddo oğlu Berekya oğlu Peygamber Zekeriyaya görümlerle seslendi.'),
(2006148,68,38,1,8,'Gece vadideki mersin ağaçlarının arasında kızıl ata binmiş bir adam gördüm. Arkasında kızıl, kula ve beyaz atlar vardı.'),
(2006149,68,38,1,9,'‹‹Efendim, bunlar ne?›› diye sordum. Benimle konuşan melek, ‹‹Bunların ne olduğunu sana göstereceğim›› diye yanıtladı.'),
(2006150,68,38,1,10,'Mersin ağaçları arasında duran adam da, ‹‹Bunlar dünyayı dolaşmak için RABbin gönderdikleridir›› diye açıkladı.'),
(2006151,68,38,1,11,'Mersin ağaçları arasında duran RABbin meleğine, ‹‹Dünyayı dolaştık›› dediler, ‹‹İşte bütün dünya esenlik ve güvenlik içinde!››'),
(2006152,68,38,1,12,'Bunun üzerine RABbin meleği, ‹‹Ey Her Şeye Egemen RAB, yetmiş yıldır öfkelendiğin Yeruşalimden ve Yahuda kentlerinden sevecenliğini ne zamana dek esirgeyeceksin?›› dedi.'),
(2006153,68,38,1,13,'RAB benimle konuşan meleği tatlı, avutucu sözlerle yanıtladı.'),
(2006154,68,38,1,14,'Bunun üzerine benimle konuşan melek, ‹‹Şunu duyur!›› dedi, ‹‹Her Şeye Egemen RAB, ‹Yeruşalim ve Siyon için büyük kıskançlık duyuyorum› diyor,'),
(2006155,68,38,1,15,'‹Tasasız uluslara ise çok öfkeliyim; çünkü ben biraz öfkelenmiştim, onlarsa kötülüğe kötülük kattılar.›'),
(2006156,68,38,1,16,'‹‹Onun için RAB, ‹Yeruşalime sevecenlikle döneceğim› diyor, ‹Tapınağım orada yeniden kurulacak ve Yeruşalim üzerine ölçü ipi çekilecek!› Böyle diyor Her Şeye Egemen RAB.'),
(2006157,68,38,1,17,'‹‹Şunu da duyur: Her Şeye Egemen RAB, ‹Kentlerim yine bollukla dolup taşacak› diyor, ‹Ben RAB, Siyonu yine avutacağım, Yeruşalimi yine seçeceğim.› ››'),
(2006158,68,38,1,18,'Sonra gözlerimi kaldırıp baktım, dört boynuz vardı.'),
(2006159,68,38,1,19,'Benimle konuşan meleğe, ‹‹Bunlar ne?›› diye sordum. Melek, ‹‹Bunlar Yahuda, İsrail ve Yeruşalim halkını dağıtmış olan boynuzlardır›› diye karşılık verdi.'),
(2006160,68,38,1,20,'Sonra RAB bana dört usta gösterdi.'),
(2006161,68,38,1,21,'‹‹Bunlar ne yapmaya geliyor?›› diye sordum. Melek, ‹‹Şu boynuzlar Yahuda halkını öyle dağıttı ki, kimse başını kaldıramadı›› dedi, ‹‹Bu ustalar da Yahuda halkını dağıtmak için boynuz kaldıran ulusları yıldırıp boynuzlarını yere çalmaya geldiler.››'),
(2006162,68,38,2,1,'Sonra gözlerimi kaldırıp baktım, elinde ölçü ipi tutan bir adam vardı.'),
(2006163,68,38,2,2,'‹‹Nereye gidiyorsun?›› diye sordum. Adam, ‹‹Yeruşalimi ölçmeye, genişliğinin, uzunluğunun ne kadar olduğunu öğrenmeye gidiyorum›› diye yanıtladı.'),
(2006164,68,38,2,3,'Benimle konuşan melek yanımdan ayrılınca başka bir melek onu karşılamaya çıktı.'),
(2006165,68,38,2,4,'Önceki meleğe şöyle dedi: ‹‹Koş, o gence de ki, içinde barınacak sayısız insan ve hayvandan ötürü Yeruşalim sursuz bir kent olacak.'),
(2006166,68,38,2,5,'RAB, ‹Ben kendim onun çevresinde ateşten sur ve içindeki görkem olacağım› diyor.››'),
(2006167,68,38,2,6,'RAB, ‹‹Haydi! Haydi! Kuzey ülkesinden kaçın!›› diyor, ‹‹Çünkü sizi göğün dört bucağına dağıttım.›› Böyle diyor RAB.'),
(2006168,68,38,2,7,'‹‹Babilde oturan Siyon halkı, haydi kaçıp kurtul!››'),
(2006169,68,38,2,8,'Çünkü Her Şeye Egemen RAB beni onurlandırdı ve sizi yağmalamış uluslara şu haberle gönderdi: ‹‹Size dokunan gözbebeğime dokunmuş olur›› diyor,'),
(2006170,68,38,2,9,'‹‹Elimi onlara karşı kaldıracağım, köleleri onları yağmalayacak.›› O zaman siz de beni Her Şeye Egemen RABbin gönderdiğini anlayacaksınız. ‹‹Gözbebeğine››.'),
(2006171,68,38,2,10,'RAB, ‹‹Ey Siyon kızı, sevinçle bağır! Çünkü aranızda yaşamaya geliyorum›› diyor.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006172,68,38,2,11,'O gün birçok ulus RABbe bağlanacak, Onun halkı olacak. O zaman RAB aranızda yaşayacak, siz de beni Her Şeye Egemen RABbin gönderdiğini anlayacaksınız.'),
(2006173,68,38,2,12,'RAB kutsal topraklarda Yahudayı kendi payı olarak miras edinecek ve Yeruşalimi yine seçecek.'),
(2006174,68,38,2,13,'Ey insanlar, RAB''bin önünde sessiz durun! RAB kutsal konutundan kalkmış geliyor!'),
(2006175,68,38,3,1,'RAB, meleğinin önünde duran Başkâhin Yeşuyu ve onu suçlamak için sağında duran Şeytanı bana gösterdi.'),
(2006176,68,38,3,2,'RABbin meleği Şeytana, ‹‹RAB seni azarlasın, ey Şeytan!›› dedi, ‹‹Yeruşalimi seçen RAB seni azarlasın! Bu adam ateşten çıkarılan yarı yanmış odun parçası değil mi?››'),
(2006177,68,38,3,3,'Yeşu meleğin önünde çok kirli giysiler içinde duruyordu.'),
(2006178,68,38,3,4,'Melek önündeki meleklere, ‹‹Üzerinden kirli giysileri çıkarın›› dedi. Sonra Yeşuya, ‹‹Bak, suçunu kaldırdım. Sana bayramlık giysiler giydireceğim›› dedi.'),
(2006179,68,38,3,5,'Ben de Yeşunun başına temiz bir sarık sarmalarını söyledim. Başına temiz bir sarık sarıp onu giydirdiler. RABbin meleği de onun yanında duruyordu.'),
(2006180,68,38,3,6,'Sonra RABbin meleği Yeşuyu uyardı:'),
(2006181,68,38,3,7,'‹‹Her Şeye Egemen RAB diyor ki, ‹Eğer yollarımda yürür, verdiğim görevleri yerine getirirsen, tapınağımı sen yönetecek, avlularımı sen koruyacaksın. Sana burada duranların arasına katılıp huzuruma çıkma ayrıcalığını vereceğim.'),
(2006182,68,38,3,8,'‹‹ ‹Ey Başkâhin Yeşu, sen ve önünde oturan kâhin arkadaşların, dinleyin! Çünkü onlar gelecek olayların önbelirtisidir. Dal adındaki kulumu ortaya çıkarıyorum.'),
(2006183,68,38,3,9,'Yeşunun önüne koyduğum taşa bakın! O tek taşın yedi gözüfç var; onun üzerine bir yazıt oyacağım› diyor Her Şeye Egemen RAB, ‹Bir günde bu ülkenin günahını kaldıracağım.'),
(2006184,68,38,3,10,'O gün her biriniz komşusunu asmasının, incir ağacının altında oturmaya çağıracak.› Böyle diyor Her Şeye Egemen RAB.››'),
(2006185,68,38,4,1,'Benimle konuşan melek yine geldi ve uykudan uyandırır gibi beni uyandırdı.'),
(2006186,68,38,4,2,'‹‹Ne görüyorsun?›› diye sordu. ‹‹Som altın bir kandillik görüyorum›› diye yanıtladım, ‹‹Tepesinde zeytinyağı için bir tas, üzerinde yedi kandil, kandillerde yedişer oluk var.'),
(2006187,68,38,4,3,'Ayrıca kandilliğin yanında, biri zeytinyağı tasının sağında, öbürü solunda iki zeytin ağacı da var.››'),
(2006188,68,38,4,4,'Benimle konuşan meleğe, ‹‹Bunların anlamı nedir, efendim?›› diye sordum.'),
(2006189,68,38,4,5,'Melek, ‹‹Bunların anlamını bilmiyor musun?›› diye karşılık verdi. ‹‹Hayır, efendim›› dedim.'),
(2006190,68,38,4,6,'Bunun üzerine şöyle dedi: ‹‹RAB Zerubbabile, ‹Güçle kuvvetle değil, ancak benim Ruhumla başaracaksın› diyor. Böyle diyor Her Şeye Egemen RAB.'),
(2006191,68,38,4,7,'Sen kim oluyorsun, ey ulu dağ? Zerubbabilin önünde bir düzlük olacaksın! O tapınağın son taşını çıkarırken, halk da, ‹Ne güzel, ne güzel!› diye bağıracak.››'),
(2006192,68,38,4,8,'RAB bana yine seslendi:'),
(2006193,68,38,4,9,'‹‹Bu tapınağın temelini Zerubbabilin elleri attı, tapınağı tamamlayacak olan da onun elleridir. O zaman beni size Her Şeye Egemen RABbin gönderdiğini anlayacaksınız.'),
(2006194,68,38,4,10,'‹‹Küçük işleri yapma gününü kim küçümsüyor? İnsanlar Zerubbabilin elinde çekülü görünce sevinecekler. -‹‹Bu yedi kandil RABbin bütün yeryüzünde dolaşan gözleridir.››-'),
(2006195,68,38,4,11,'Meleğe, ‹‹Kandilliğin sağındaki ve solundaki bu iki zeytin ağacı nedir?›› diye sordum,'),
(2006196,68,38,4,12,'‹‹Altın gibi yağ akıtan iki altın oluğun yanındaki bu iki zeytin dalı nedir?››'),
(2006197,68,38,4,13,'‹‹Bunların anlamını bilmiyor musun?›› diye karşılık verdi. ‹‹Hayır, efendim›› dedim.'),
(2006198,68,38,4,14,'Melek, ‹‹Bunlar bütün dünyanın Rabbi''ne hizmet eden, zeytinyağıyla kutsanmış iki kişidir›› diye açıkladı.'),
(2006199,68,38,5,1,'Gözlerimi yine kaldırıp bakınca, uçan bir tomar gördüm.'),
(2006200,68,38,5,2,'Melek, ‹‹Ne görüyorsun?›› diye sordu. ‹‹Uçan bir tomar görüyorum. Uzunluğu yirmi, genişliği on arşın›› diye yanıtladım.'),
(2006201,68,38,5,3,'Melek, ‹‹Bütün ülkeye yağacak lanettir bu›› dedi, ‹‹Tomarın bir yanına yazılanlar uyarınca, hırsızlık eden herkes sökülüp atılacak; öbür yanına yazılanlar uyarınca da yalan yere ant içenler kovulacak.'),
(2006202,68,38,5,4,'Her Şeye Egemen RAB, ‹Lanet yağdıracağım› diyor, ‹Hırsızın ve benim adımla yalan yere ant içenin evi üzerine lanet yağacak. Ve lanet o evin üzerinde kalacak; kerestesiyle, taşlarıyla birlikte evin tümünü yok edecek.› ››'),
(2006203,68,38,5,5,'Sonra benimle konuşan melek yaklaşıp, ‹‹Gözlerini kaldır›› dedi, ‹‹Ortaya çıkan şu nesnenin ne olduğuna bak.››'),
(2006204,68,38,5,6,'‹‹Nedir?›› diye sordum. ‹‹Bir ölçü kabı›› dedi, sonra ekledi: ‹‹Bu, bütün ülke halkının suçudur.››'),
(2006205,68,38,5,7,'Derken kurşun kapak kaldırıldı. Kabın içinde bir kadın oturuyordu.'),
(2006206,68,38,5,8,'Melek, ‹‹İşte bu kötülüktür!›› diyerek kadını gerisingeri ölçü kabına itip kurşun kapağı yerine koydu. ölçek.'),
(2006207,68,38,5,9,'Gözlerimi kaldırıp bakınca, rüzgarda uçarak yaklaşan iki kadın gördüm. Leylek kanatlarına benzeyen kanatları vardı. Kabı yerle gök arasına kaldırdılar.'),
(2006208,68,38,5,10,'Benimle konuşan meleğe, ‹‹Kabı nereye götürüyorlar?›› diye sordum.'),
(2006209,68,38,5,11,'‹‹Kadın için bir ev yapmak üzere Şinar topraklarına›› diye yanıtladı, ‹‹Ev hazır olunca kap oraya, yerine konulacak.››'),
(2006210,68,38,6,1,'Yine gözlerimi kaldırıp baktım, iki tunç dağın arasından çıkıp gelen dört savaş arabası gördüm.'),
(2006211,68,38,6,2,'Birinci savaş arabasının kızıl, ikincisinin siyah,'),
(2006212,68,38,6,3,'üçüncüsünün beyaz, dördüncüsünün benekli atları vardı. Atların hepsi güçlüydü.'),
(2006213,68,38,6,4,'Benimle konuşan meleğe, ‹‹Bunlar ne, efendim?›› diye sordum.'),
(2006214,68,38,6,5,'Melek şöyle karşılık verdi: ‹‹Bunlar bütün dünyanın Rabbine hizmet ettikleri yerden çıkan göğün dört ruhudur.'),
(2006215,68,38,6,6,'Siyah atların çektiği savaş arabası bölgenin kuzeyine, beyaz atlarınki batıya, benekli atlarınki de güneye doğru gidiyor.››'),
(2006216,68,38,6,7,'Yola çıktıklarında güçlü atlar yeryüzünü dolaşmak üzere gitmek istiyorlardı. Melek, ‹‹Gidin, yeryüzünü dolaşın!›› deyince, gidip yeryüzünü dolaştılar.'),
(2006217,68,38,6,8,'Sonra melek bana seslendi: ‹‹Bak, bölgenin kuzeyine gidenler, orada öfkemi yatıştırdılar.››'),
(2006218,68,38,6,9,'RAB bana şöyle seslendi:'),
(2006219,68,38,6,10,'‹‹Armağanları sürgünden dönenlerden -Babilden gelen Helday, Toviya ve Yedayadan- al ve aynı gün Sefanya oğlu Yoşiyanın evine git.'),
(2006220,68,38,6,11,'Aldığın altınla gümüşten bir taç yaparak Yehosadak oğlu Başkâhin Yeşunun başına tak.'),
(2006221,68,38,6,12,'Ona Her Şeye Egemen RAB şöyle diyor de: ‹İşte Dal adındaki adam! Bulunduğu yerde filizlenecek ve RABbin Tapınağını kuracak.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006222,68,38,6,13,'Evet, RABbin Tapınağını kuracak olan odur. Görkemle kuşanacak, tahtında oturup egemenlik sürecek. Tahtında oturan kâhin olacak. İkisi arasında tam bir uyum olacak.›'),
(2006223,68,38,6,14,'Heldayınfı, Toviyanın, Yedayanın, Sefanya oğlu Yoşiyanın anısına taç RABbin Tapınağına konulacak.'),
(2006224,68,38,6,15,'Uzaktakiler de gelip RAB''bin Tapınağı''nın yapımında çalışacak. Böylece beni size Her Şeye Egemen RAB''bin gönderdiğini anlayacaksınız. Tanrınız RAB''bin sözüne özenle uyarsanız bütün bunlar gerçekleşecektir.››'),
(2006225,68,38,7,1,'Kral Dariusun krallığının dördüncü yılının dokuzuncu ayı olan Kislev ayının dördüncü günü RAB Zekeriyaya seslendi.'),
(2006226,68,38,7,2,'Beytel halkı, Her Şeye Egemen RABbin Tapınağındaki kâhinlerle peygamberlere, ‹‹Yıllardır yaptığımız gibi beşinci ay oruç tutup ağlayalım mı?›› diye sormuş ve RABbe yalvarmaları için Sareseri, Regem-Meleki ve adamlarını göndermişti.'),
(2006227,68,38,7,4,'Her Şeye Egemen RAB bana dedi ki,'),
(2006228,68,38,7,5,'‹‹Bütün ülke halkına ve kâhinlere sor: ‹Yetmiş yıldır beşinci ve yedinci aylarda oruç tutup dövündüğünüzde gerçekten benim için mi oruç tuttunuz?'),
(2006229,68,38,7,6,'Yiyip içerken kendiniz için yiyip içmiyor muydunuz?'),
(2006230,68,38,7,7,'Yeruşalimle çevresindeki kentler gönenç içinde yaşarken, Negev ve Şefela insanlarla doluyken, RABbin önceki peygamberler aracılığıyla açıkladığı sözler bunlar değil mi?› ››'),
(2006231,68,38,7,8,'RAB Zekeriyaya yine seslendi:'),
(2006232,68,38,7,9,'‹‹Her Şeye Egemen RAB diyor ki, ‹Gerçek adaletle yargılayın; birbirinize sevgi ve sevecenlik gösterin.'),
(2006233,68,38,7,10,'Dul kadına, öksüze, yabancıya, yoksula baskı yapmayın. Yüreğinizde birbirinize karşı kötülük tasarlamayın.›'),
(2006234,68,38,7,11,'‹‹Ama atalarımız dinlemek istemediler; inatla sırtlarını çevirdiler, duymamak için kulaklarını tıkadılar.'),
(2006235,68,38,7,12,'Kutsal Yasayı ve Her Şeye Egemen RABbin kendi Ruhuyla gönderdiği, önceki peygamberler aracılığıyla ilettiği sözleri dinlememek için yüreklerini taş gibi sertleştirdiler. Bu yüzden Her Şeye Egemen RAB onlara çok öfkelendi.'),
(2006236,68,38,7,13,'‹‹ ‹Madem ben çağırınca dinlemediler› diyor Her Şeye Egemen RAB, ‹Onlar çağırınca, ben de onları dinlemeyeceğim.'),
(2006237,68,38,7,14,'Onları tanımadıkları ulusların arasına fırtına gibi dağıttım. Geride bıraktıkları ülke öyle ıssız kaldı ki, oraya kimse gidip gelemez oldu. Güzelim ülkeyi viraneye çevirdiler.› ››'),
(2006238,68,38,8,1,'Her Şeye Egemen RAB bana yine seslendi:'),
(2006239,68,38,8,2,'Her Şeye Egemen RAB, ‹‹Siyon için büyük kıskançlık duyuyorum›› diyor, ‹‹Evet, onu şiddetle kıskanıyorum.'),
(2006240,68,38,8,3,'Siyona dönecek ve Yeruşalimde oturacağım. Yeruşalime Sadık Kent, Her Şeye Egemen RABbin dağına Kutsal Dağ denecek.'),
(2006241,68,38,8,4,'‹‹İlerlemiş yaşlarından ötürü ellerinde bastonlarıyla yaşlı erkeklerle kadınlar yine Yeruşalim meydanlarında oturacaklar. Kentin meydanları orada oynayan erkek ve kız çocuklarla dolacak.›› Böyle diyor Her Şeye Egemen RAB.'),
(2006242,68,38,8,6,'Her Şeye Egemen RAB diyor ki, ‹‹O günlerde sürgünden dönen halkın gözünde bu olanaksız olsa da, benim gözümde de böyle mi olmalı?›› Böyle diyor Her Şeye Egemen RAB.'),
(2006243,68,38,8,7,'‹‹Halkımı doğudaki, batıdaki ülkelerden kurtarıp geri getireceğim. Yeruşalimde yaşayacak, halkım olacaklar; ben de onların sadık ve adil Tanrısı olacağım.›› Böyle diyor Her Şeye Egemen RAB.'),
(2006244,68,38,8,9,'‹‹Her Şeye Egemen RABbin Tapınağının kurulması için temel atıldığında orada bulunan peygamberlerin bu günlerde söylediği sözleri duyan sizler yüreklenin!›› diyor Her Şeye Egemen RAB,'),
(2006245,68,38,8,10,'‹‹O günlerden önce insan ya da hayvan için ücret yoktu. Düşman yüzünden hiç kimse güvenlik içinde gidip gelemiyordu. Çünkü herkesi birbirine düşürmüştüm.'),
(2006246,68,38,8,11,'Ama şimdi sürgünden dönen bu halka geçmiş günlerde davrandığım gibi davranmayacağım.›› Böyle diyor Her Şeye Egemen RAB,'),
(2006247,68,38,8,12,'‹‹Ekilen tohum verimli olacak; asma üzüm, toprak ürün, gökler çiy verecek. Bunların tümünü sürgünden dönen bu halka mülk olarak vereceğim.'),
(2006248,68,38,8,13,'Sizi kurtaracağım, ey Yahuda ve İsrail halkı. Siz uluslar arasında nasıl lanet konusu olduysanız, şimdi de bereket kaynağı olacaksınız. Korkmayın, yürekli olun!››'),
(2006249,68,38,8,14,'Her Şeye Egemen RAB şöyle diyor: ‹‹Atalarınız beni öfkelendirdiğinde başınıza felaket getirmeyi tasarladım ve vazgeçmedim›› diyor Her Şeye Egemen RAB,'),
(2006250,68,38,8,15,'‹‹Şimdi de Yeruşalim ve Yahuda halkına yine iyilik yapmayı tasarladım. Korkmayın!'),
(2006251,68,38,8,16,'Yapmanız gerekenler şunlardır: Birbirinize gerçeği söyleyin, kent kapılarınızda esenliği sağlayan gerçek adaletle yargılayın,'),
(2006252,68,38,8,17,'yüreğinizde birbirinize karşı kötülük tasarlamayın, yalan yere ant içmekten tiksinin. Çünkü ben bütün bunlardan nefret ederim.›› Böyle diyor RAB. kapısında yapılırdı.'),
(2006253,68,38,8,18,'Her Şeye Egemen RAB bana yine seslendi:'),
(2006254,68,38,8,19,'Her Şeye Egemen RAB diyor ki, ‹‹Dördüncü, beşinci, yedinci ve onuncu ayların oruçları Yahuda halkı için sevinç, coşku dolu mutlu bayramlar olacak. Bu nedenle gerçeği ve esenliği sevin.››'),
(2006255,68,38,8,20,'Her Şeye Egemen RAB diyor ki, ‹‹Daha birçok halk, birçok kentte yaşayanlar gelecek.'),
(2006256,68,38,8,21,'Bir kentte yaşayanlar başka kente gidip, ‹RABbe yalvarmak, Her Şeye Egemen RABbe yönelmek için hemen yola çıkalım. Ben de gideceğim› diyecekler.'),
(2006257,68,38,8,22,'Her Şeye Egemen RABbe yönelmek, Ona yalvarmak için çok sayıda halkla birçok ulus Yeruşalime gelecek.››'),
(2006258,68,38,8,23,'Her Şeye Egemen RAB diyor ki, ‹‹O günlerde her dil ve ulustan on kişi bir Yahudi''nin eteğinden tutup, ‹İzin verin, sizinle gidelim. Çünkü Tanrı''nın sizinle olduğunu duyduk› diyecekler.››'),
(2006259,68,38,9,1,'Bildiri: RABbin sözü Hadrak ülkesine ve Şam Kentine yöneliktir. Çünkü insanların, özellikle bütün İsrail oymaklarının gözü RABbe çevrilidir.'),
(2006260,68,38,9,2,'Bu söz Hadrak sınırındaki Hamaya, 2 Çok becerikli olmasına karşın Sur ve Sayda kentlerine de yöneliktir.'),
(2006261,68,38,9,3,'Sur kendine bir kale yaptı; 2 Toprak kadar gümüş 2 Ve sokaktaki çamur kadar altın biriktirdi.'),
(2006262,68,38,9,4,'Ama Rab onun mal varlığını alıp götürecek; 2 Denizdeki gücünü yok edecek 2 Ve ateş kenti yiyip bitirecek.'),
(2006263,68,38,9,5,'Aşkelon bunu görünce korkacak; 2 Gazze acıdan kıvranacak, 2 Ekron da öyle, çünkü umudu sönecek. 2 Gazze kralını yitirecek, 2 Aşkelon ıssız kalacak.'),
(2006264,68,38,9,6,'Aşdotta melez bir halk oturacak, 2 Filistlilerin gururunu kıracağım.'),
(2006265,68,38,9,7,'Ağızlarından kanı alınmamış eti, 2 Dişlerinin arasından yasak yiyecekleri alacağım. 2 Sağ kalanlar Tanrımıza bağlanacak 2 Ve Yahuda oymağında bir boy sayılacak. 2 Ekron Yevuslular gibi olacak.'),
(2006266,68,38,9,8,'Akın eden ordulara karşı 2 Evimin çevresinde ordugah kuracağım. 2 Hiçbir kıyıcı 2 Bir daha halkımın üzerinden geçmeyecek, 2 Çünkü artık halkımı ben gözetiyorum.'),
(2006267,68,38,9,9,'Ey Siyon kızı, sevinçle coş! 2 Sevinç çığlıkları at, ey Yeruşalim kızı! 2 İşte kralın! 2 O adil kurtarıcı ve alçakgönüllüdür. 2 Eşeğe, evet, sıpaya, 2 Eşek yavrusuna binmiş sana geliyor!'),
(2006268,68,38,9,10,'Savaş arabalarını Efrayimden, 2 Atları Yeruşalimden uzaklaştıracağım. 2 Savaş yayları kırılacak. 2 Kralınız uluslara barışı duyuracak, 2 Onun egemenliği bir denizden bir denize, 2 Fırattan yeryüzünün uçlarına dek uzanacak.'),
(2006269,68,38,9,11,'Size gelince, 2 Sizinle yaptığım kurban kanıyla yürürlüğe girmiş antlaşma uyarınca, 2 Sürgündeki halkınızı 2 Susuz çukurdan çıkarıp özgür kılacağım.'),
(2006270,68,38,9,12,'Kalenize dönün, 2 Ey siz, umut sürgünleri! 2 Bugün bildiriyorum ki, 2 Size yitirdiğinizin iki katını vereceğim.'),
(2006271,68,38,9,13,'Yahudayı yayımı gerer gibi gereceğim 2 Ve Efrayimi ok gibi ona dolduracağım. 2 Oğullarını Greklere karşı uyandıracağım, ey Siyon 2 Ve seni bir savaşçının kılıcı gibi yapacağım.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006272,68,38,9,14,'O zaman RAB halkının üzerinde görünecek, 2 Oku şimşek gibi çakacak. 2 Egemen RAB boru çalacak 2 Ve güney fırtınalarıyla ilerleyecek.'),
(2006273,68,38,9,15,'Onları Her Şeye Egemen RAB koruyacak. 2 Düşmanlarını yok edecek 2 Ve sapan taşlarıyla yenecekler. 2 Şarap içmiş gibi içip gürleyecek 2 Ve kurban kanı serpmekte kullanılan çanaklar gibi sunağın köşelerine dolacaklar.'),
(2006274,68,38,9,16,'O gün Tanrıları RAB 2 Sürüsü olan halkını kurtaracak. 2 Onun ülkesinde taç mücevherleri gibi parlayacaklar.'),
(2006275,68,38,9,17,'Ne yakışıklı ve güzel olacaklar! 2 Delikanlılar tahılla, 2 Genç kızlar yeni şarapla güçlenecek.'),
(2006276,68,38,10,1,'İlkbaharda RABden yağmur dileyin. 2 Odur yağmur bulutlarını oluşturan. 2 İnsanlara yağmur sağanakları 2 Ve herkese tarlada ot verir.'),
(2006277,68,38,10,2,'Oysa aile putlarından alınan yanıtlar boştur, 2 Falcılar yalan görümler görür 2 Ve gerçek yanı olmayan düşler anlatarak 2 Boşuna avuturlar. 2 Bu yüzden halk sürü gibi dağınık, 2 Sıkıntı çekiyor, çünkü çoban yok.'),
(2006278,68,38,10,3,'RAB şöyle diyor: 2 ‹‹Öfkem çobanlara karşı alevlendi, 2 Önderleri cezalandıracağım. 2 Her Şeye Egemen RAB kendi sürüsünü, 2 Yahuda halkını kayıracak. 2 Görkemli savaş atı gibi yapacak onları.'),
(2006279,68,38,10,4,'Köşe taşı, 2 Çadır kazığı, 2 Savaş yayı 2 Ve bütün önderler Yahudadan çıkacak.'),
(2006280,68,38,10,5,'Savaşta düşmanlarını sokaklardaki çamurda çiğneyen yiğitler gibi olacaklar. 2 RAB onlarla olduğu için 2 Savaşacak ve atlıları utandıracaklar.'),
(2006281,68,38,10,6,'‹‹Yahuda halkını güçlendireceğim, 2 Yusuf soyunu kurtarıp 2 Sürgünden geri getireceğim. 2 Çünkü onlara acıyorum. 2 Sanki onları reddetmemişim gibi olacaklar. 2 Çünkü ben onların Tanrısı RABbim ve onları yanıtlayacağım.'),
(2006282,68,38,10,7,'Efrayimliler yiğitler gibi olacaklar, 2 Şarap içmiş gibi yürekleri coşacak. 2 Çocukları bunu görüp neşelenecek, 2 Yürekleri RABde sevinç bulacak.'),
(2006283,68,38,10,8,'‹‹Islık çalıp onları toplayacağım, 2 Onlar�� kesinlikle kurtaracağım. 2 Eskiden olduğu gibi 2 Yine çoğalacaklar.'),
(2006284,68,38,10,9,'Onları halklar arasına dağıttımsa da, 2 Uzak ülkelerde beni anımsayacaklar; 2 Çocuklarıyla birlikte sağ kalacak ve geri dönecekler.'),
(2006285,68,38,10,10,'Onları Mısırdan geri getirecek, 2 Asurdan toplayacağım; 2 Gilata, Lübnana getireceğim. 2 Onlara yeterince yer bulunmayacak.'),
(2006286,68,38,10,11,'Sıkıntı denizinden geçecekler, 2 Denizin dalgaları yatışacak, 2 Nilin bütün derinlikleri kuruyacak. 2 Asurun gururu alaşağı edilecek, 2 Mısırın krallık asası elinden alınacak.'),
(2006287,68,38,10,12,'Halkımı kendi gücümle güçlendireceğim, 2 Adıma layık bir yaşam sürdürecekler.›› 2 Böyle diyor RAB.'),
(2006288,68,38,11,1,'Ey Lübnan, kapılarını aç ki, 2 Ateş sedir ağaçlarını yakıp yok etsin!'),
(2006289,68,38,11,2,'Ey çam ağacı, haykır! 2 Sedir ağacı yıkıldı, 2 Ulu ağaçlar yok oldu! 2 Haykırın, ey Başan meşeleri, 2 Gür ormanın ağaçları devrildi!'),
(2006290,68,38,11,3,'Çobanların haykırışını duy, 2 Çünkü güzelim otlakları yok oldu! 2 Genç aslanların kükremesini dinle, 2 Çünkü Şeria Irmağının kıyısındaki ağaçlık yok oldu!'),
(2006291,68,38,11,4,'Tanrım RAB, ‹‹Kesime ayrılmış sürüyü sen güt›› diyor,'),
(2006292,68,38,11,5,'‹‹Sürüyü satın alanlar koyunları kesiyor ama cezalarını çekmiyorlar. Koyunları satanlar da, ‹Tanrıya övgüler olsun, zengin oldum!› diyorlar. Çobanlar kendi sürülerine acımıyor.'),
(2006293,68,38,11,6,'Çünkü ülkede yaşayan halka artık acımayacağım›› diyor RAB, ‹‹Herkesi kendi komşusunun ve kralının eline teslim edeceğim. Ülkeyi ezecekler, ben de halkı ellerinden kurtarmayacağım.››'),
(2006294,68,38,11,7,'Bunun üzerine kesime ayrılmış sürünün özellikle ezilenlerini güttüm. Elime iki değnek aldım; birine ‹‹Lütuf››, ötekine ‹‹Birlik›› adını koydum. Böylece sürüyü gütmeye başladım.'),
(2006295,68,38,11,8,'Bir ayda üç çobanı başımdan savdım. Çünkü ben sürüden bıkmıştım, sürü de benden tiksinmişti.'),
(2006296,68,38,11,9,'Sürüye, ‹‹Artık sizi gütmeyeceğim. Ölen ölsün, kesilen kesilsin, geri kalanlar da birbirinin etini yesin›› dedim.'),
(2006297,68,38,11,10,'Sonra ‹‹Lütuf›› adındaki değneğimi aldım ve bütün uluslarla yapmış olduğum antlaşmayı bozmak için kırdım.'),
(2006298,68,38,11,11,'Böylece antlaşma o gün bozuldu. Beni gözleyen sürünün ezilenleri RABbin sözünün yerine geldiğini anladılar.'),
(2006299,68,38,11,12,'Onlara, ‹‹Uygun görürseniz ücretimi ödeyin, yoksa boş verin›› dedim. Onlar da ücret olarak bana otuz gümüş verdiler.'),
(2006300,68,38,11,13,'RAB bana, ‹‹Çömlekçiye at›› dedi. Böylece bana biçtikleri yüksek değerin karşılığı olan otuz gümüşü alıp RABbin Tapınağındaki çömlekçiye attım.'),
(2006301,68,38,11,14,'Sonra Yahuda ile İsrail arasındaki kardeşliği bozmak için ‹‹Birlik›› adındaki öteki değneğimi kırdım.'),
(2006302,68,38,11,15,'RAB bana, ‹‹Sen yine akılsız bir çoban gibi donat kendini›› dedi,'),
(2006303,68,38,11,16,'‹‹Ülkeye öyle bir çoban atayacağım ki, yitiklere bakmayacak, dağılmışları aramayacak, yaralıları iyileştirmeyecek, sağlamları beslemeyecek. Ancak semiz koyunların etini yiyecek, tırnaklarını koparacak.'),
(2006304,68,38,11,17,'‹‹Sürüyü terk eden değersiz çobanın vay haline! 2 Kılıç kolunu ve sağ gözünü vursun! 2 Kolu tamamen kurusun, 2 Sağ gözü kör olsun!››'),
(2006305,68,38,12,1,'Bildiri: İşte RABbin İsraile ilişkin sözleri. Gökleri geren, yeryüzünün temelini atan, insanın içindeki ruha biçim veren RAB şöyle diyor:'),
(2006306,68,38,12,2,'‹‹Yeruşalimi çevredeki bütün halkları sersemleten bir kâse yapacağım. Yeruşalim gibi Yahuda da kuşatma altına alınacak.'),
(2006307,68,38,12,3,'O gün Yeruşalimi bütün halklar için ağır bir taş yapacağım. Onu kaldırmaya yeltenen herkes ağır yaralanacak. Yeryüzünün bütün ulusları Yeruşalime karşı birleşecek.'),
(2006308,68,38,12,4,'O gün her atı dehşete düşürecek, her atlıyı çılgına döndüreceğim. Yahuda halkını gözeteceğim, ama öbür halkların bütün atlarını kör edeceğim.'),
(2006309,68,38,12,5,'O zaman Yahuda önderleri, ‹Her Şeye Egemen Tanrısı RABbe güvenen Yeruşalim halkı güç kaynağımızdır› diye düşünecekler.'),
(2006310,68,38,12,6,'‹‹O gün Yahuda önderlerini odunların ortasında yanan bir mangal gibi, ekin demetleri arasında alev alev yanan bir meşale gibi yapacağım. Sağda solda, çevredeki bütün halkları yakıp yok edecekler. Yeruşalim ise sapasağlam yerinde duracak.'),
(2006311,68,38,12,7,'‹‹Ben RAB önce çadırlarda oturan Yahuda halkını kurtaracağım. Öyle ki, Davut soyuyla Yeruşalimde oturanlar Yahudadan daha çok onura kavuşmasın.'),
(2006312,68,38,12,8,'Ben RAB o gün Yeruşalimde oturanları koruyacağım. Böylece aralarındaki en güçsüz kişi Davut gibi, Davut soyu da Tanrı gibi, kendilerine öncülük eden RABbin meleği gibi olacak.'),
(2006313,68,38,12,9,'O gün Yeruşalime saldıran bütün ulusları yok etmeye başlayacağım.'),
(2006314,68,38,12,10,'‹‹Davut soyuyla Yeruşalimde oturanların üzerine lütuf ve yakarış ruhunu dökeceğim. Bana, yani deştiklerine bakacaklar; biricik oğlu için yas tutan biri gibi yas tutacak, ilk oğlu için acı çeken biri gibi acı çekecekler.'),
(2006315,68,38,12,11,'O gün Yeruşalimde tutulan yas, Megiddo Ovasında, Hadat-Rimmonda tutulan yas gibi büyük olacak.'),
(2006316,68,38,12,12,'Ülkede her boy kendi içinde yas tutacak: Davut, Natan, Levi, Şimi boyundan ve geri kalan boylardan aileler. Her boyun erkekleri ayrı, kadınları ayrı yas tutacak.››'),
(2006317,68,38,13,1,'‹‹O gün Davut soyunu ve Yeruşalimde yaşayanları günahtan ve ruhsal kirlilikten arındırmak için bir pınar açılacak.'),
(2006318,68,38,13,2,'O gün ülkeden putların adlarını kaldıracağım, bir daha anılmayacaklar›› diyor Her Şeye Egemen RAB, ‹‹Sahte peygamberleri de, kirli ruhu da ülkeden uzaklaştıracağım.'),
(2006319,68,38,13,3,'Biri yine peygamberlik edecek olursa, öz annesiyle babası, ‹Öleceksin, çünkü RABbin adıyla yalan söylüyorsun› diyecekler. Peygamberlik ettiğinde de öz annesi babası onun bedenini deşecekler.'),
(2006320,68,38,13,4,'‹‹O gün her peygamber peygamberlik ederken gördüğü görümden utanacak; insanları aldatmak için çuldan giysi giymeyecek.'),
(2006321,68,38,13,5,'‹Ben peygamber değilim, çiftçiyim. Gençliğimden beri hep tarlada çalıştım› diyecek.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006322,68,38,13,6,'Biri, ‹Bağrındaki bu yaralar ne?› diye sorduğunda da, ‹Bunlar dostlarımın evinde aldığım yaralar› diye yanıtlayacak.›› Masoretik metin ‹‹Çünkü bir adam beni gençliğimde köle olarak satın aldı››.'),
(2006323,68,38,13,7,'‹‹Uyan, ey kılıç! 2 Çobanıma, yakınıma karşı harekete geç›› 2 Diyor Her Şeye Egemen RAB. 2 ‹‹Çobanı vur da 2 Koyunlar darmadağın olsun. 2 Ben de elimi küçüklere karşı kaldıracağım.'),
(2006324,68,38,13,8,'Bütün ülkede›› diyor RAB, 2 ‹‹Halkın üçte ikisi vurulup ölecek, 2 Üçte biri sağ kalacak.'),
(2006325,68,38,13,9,'Kalan üçte birini ateşten geçireceğim, 2 Onları gümüş gibi arıtacağım, 2 Altın gibi sınayacağım. 2 Beni adımla çağıracaklar, 2 Ben de onlara karşılık vereceğim, 2 ‹Bunlar benim halkım› diyeceğim. 2 Onlar da, ‹Tanrımız RAB''dir› diyecekler.››'),
(2006326,68,38,14,1,'İşte RABbin günü geliyor! Ey Yeruşalim halkı, senden yağmalanan mal gözlerinin önünde paylaşılacak.'),
(2006327,68,38,14,2,'Yeruşalime karşı savaşmaları için bütün ulusları bir araya getireceğim. Kent ele geçirilecek, evler yağmalanacak, kadınların ırzına geçilecek. Kentte yaşayanların yarısı sürgüne gönderilecek, geri kalanlar kentte kalacak.'),
(2006328,68,38,14,3,'Sonra RAB, savaş zamanlarında yaptığı gibi, gidip bu uluslara karşı savaşacak.'),
(2006329,68,38,14,4,'O gün Onun ayakları Yeruşalimin doğusundaki Zeytin Dağının üzerinde duracak. Zeytin Dağı doğuya ve batıya doğru ortadan yarılıp çok büyük bir vadi oluşturacak. Dağın yarısı kuzeye, öbür yarısı güneye çekilecek.'),
(2006330,68,38,14,5,'Yarılan dağımın oluşturduğu vadiden kaçacaksınız, çünkü vadi Asala dek uzanacak. Yahuda Kralı Uzziya döneminde depremden nasıl kaçtıysanız, öyle kaçacaksınız. O zaman Tanrım RAB bütün kutsallarla birlikte gelecek!'),
(2006331,68,38,14,6,'O gün ışık olmayacak, ışık veren cisimler kararacak.'),
(2006332,68,38,14,7,'Özel bir gün, yalnız RABbin bildiği bir gün olacak. Gece de gündüz de olmayacak. Gece aydınlık olacak.'),
(2006333,68,38,14,8,'O gün Yeruşalimin içinden diri sular akacak. Yaz kış suların yarısı Lut Gölüne, öbür yarısı Akdenize akacak.'),
(2006334,68,38,14,9,'RAB bütün dünyanın kralı olacak. O gün yalnız RAB, yalnız Onun adı kalacak.'),
(2006335,68,38,14,10,'Bütün ülke Gevadan Yeruşalimin güneyindeki Rimmona dek Arava Ovası gibi olacak. Ama Yeruşalim yükseltilecek ve Benyamin Kapısından ilk kapıya, Köşe Kapısına, Hananel Kulesinden kralın üzüm sıkma çukurlarına dek yerli yerinde duracak.'),
(2006336,68,38,14,11,'İnsanlar oraya yerleşip güvenlik içinde yaşayacak. Yeruşalim bir daha yıkıma uğramayacak.'),
(2006337,68,38,14,12,'Yeruşalime karşı savaşan bütün halkları RAB şu belayla cezalandıracak: Daha sağken bedenleri, gözleri, dilleri çürüyecek.'),
(2006338,68,38,14,13,'O gün RAB insanları büyük dehşete düşürecek. Herkes yanındakinin elini yakalayacak, birbirlerine saldıracaklar.'),
(2006339,68,38,14,14,'Yahudalılar da Yeruşalimde savaşacak. Çevredeki bütün ulusların serveti, çok miktarda altın, gümüş, giysi toplanacak.'),
(2006340,68,38,14,15,'Düşman ordugahlarındaki bütün hayvanlar da -at, katır, deve, eşek- benzer bir belaya çarptırılacak.'),
(2006341,68,38,14,16,'Yeruşalime saldıran uluslardan sağ kalanların hepsi Her Şeye Egemen RAB olan Krala tapınmak ve Çardak Bayramını kutlamak için yıldan yıla Yeruşalime gidecekler.'),
(2006342,68,38,14,17,'Yeryüzü halklarından hangisi Her Şeye Egemen RAB olan Krala tapınmak için Yeruşalime gitmezse, ülkesine yağmur yağmayacak.'),
(2006343,68,38,14,18,'Mısırlılar bunlara katılıp Yeruşalime gitmezlerse, RAB onları da Çardak Bayramını kutlamak için Yeruşalime gitmeyen bütün ulusların başına getirdiği aynı belayla cezalandıracak.'),
(2006344,68,38,14,19,'Mısırlılara ve Çardak Bayramını kutlamak için Yeruşalime gitmeyen bütün uluslara verilecek ceza budur.'),
(2006345,68,38,14,20,'O gün atların çıngırakları üzerine, ‹‹RABbe adanmıştır›› diye yazılacak. RABbin Tapınağındaki kazanlar da sunağın önündeki çanaklar gibi olacak.'),
(2006346,68,38,14,21,'Yeruşalim ve Yahuda''da her kazan Her Şeye Egemen RAB''be adanacak. Kurban kesmeye gelenler bu kazanları kurban etini pişirmek için kullanacaklar. O gün Her Şeye Egemen RAB''bin Tapınağı''nda artık tüccar bulunmayacak.'),
(2006347,68,39,1,1,'RABbin Malaki aracılığıyla İsrail halkına bildirisi.'),
(2006348,68,39,1,2,'RAB, ‹‹Sizi sevdim›› diyor. ‹‹Oysa siz, ‹Bizi nasıl sevdin?› diye soruyorsunuz.›› RAB, ‹‹Esav Yakupun ağabeyi değil mi?›› diye karşılık veriyor, ‹‹Ben Yakupu sevdim,'),
(2006349,68,39,1,3,'Esavdan ise nefret ettim. Dağlarını viraneye çevirdim, yurdunu kırın çakallarına verdim.›› yerine Yakupu yeğledim›› anlamına gelir.'),
(2006350,68,39,1,4,'Edomlular, ‹‹Biz ezildik, ama yıkıntıları yeniden kuracağız›› deseler de, Her Şeye Egemen RAB şu karşılığı verecek: ‹‹Onlar kurabilirler, ama ben yıkacağım. Ülkeleri kötülük ülkesi, kendileri de RABbin her zaman lanetlediği halk olarak tanınacak.'),
(2006351,68,39,1,5,'Bunu gözlerinizle görünce, ‹RAB İsrail sınırının ötesinde de büyüktür!› diyeceksiniz.››'),
(2006352,68,39,1,6,'Her Şeye Egemen RAB, adını küçümseyen siz kâhinlere, ‹‹Oğul babasına, kul efendisine saygı gösterir›› diyor, ‹‹Eğer ben babaysam, hani bana saygınız? Eğer efendiysem, hani benden korkunuz? ‹‹Oysa siz, ‹Adını nasıl küçümsedik?› diye soruyorsunuz.'),
(2006353,68,39,1,7,'‹‹Hem sunağıma murdar yiyecek getiriyor, hem de, ‹Yiyeceği nasıl murdar ettik?› diye soruyorsunuz. metin ‹‹Seni››. ‹‹ ‹RABbin sofrasıfç küçümsenir› demenizle.'),
(2006354,68,39,1,8,'Kör hayvan kurban etmek kötü değil mi? Topal ya da hasta hayvan kurban etmek kötü değil mi? Böyle bir hayvanı kendi valine sun bakalım! Senden hoşnut kalır mı, ya da seni kabul eder mi?›› Böyle diyor Her Şeye Egemen RAB. sunuların tümü›› ya da ‹‹RABbin sunağı››.'),
(2006355,68,39,1,9,'‹‹Şimdi bize lütfetmesi için Tanrıya yalvarın. Siz böyle sunular sunarken hiç sizi kabul eder mi?›› Böyle diyor Her Şeye Egemen RAB.'),
(2006356,68,39,1,10,'‹‹Ne olurdu, sunağımda boşuna ateş yakmayasınız diye aranızda tapınağın kapılarını kapatan biri olsaydı! Ben sizden hoşnut değilim›› diyor Her Şeye Egemen RAB, ‹‹Getireceğiniz sunuları da kabul etmeyeceğim.'),
(2006357,68,39,1,11,'Doğudan batıya kadar uluslar arasında adım büyük olacak! Her yerde adıma buhur yakılacak, temiz sunular sunulacak. Çünkü uluslar arasında adım büyük olacak!›› diyor Her Şeye Egemen RAB.'),
(2006358,68,39,1,12,'‹‹ ‹Rabbin sofrasıfç murdardır, yemeği de küçümsenir› diyerek adımı bayağılaştırıyorsunuz.'),
(2006359,68,39,1,13,'Üstelik, ‹Ne yorucu!› diyerek bana burun kıvırıyorsunuz.›› Böyle diyor Her Şeye Egemen RAB. ‹‹Kurban olarak çalıntıyı, topalı, hastayı getirdiğinizde, elinizden kabul mu edeyim?›› diye soruyor RAB.'),
(2006360,68,39,1,14,'‹‹Sürüsünden adadığı erkek hayvan yerine Rab''be kusurlu hayvan kurban eden aldatıcıya lanet olsun! Çünkü ben büyük bir kralım›› diyor Her Şeye Egemen RAB, ‹‹Ve uluslar adımdan korku duyacak.››'),
(2006361,68,39,2,1,'‹‹Şimdi, ey kâhinler, bu buyruk sizin içindir.'),
(2006362,68,39,2,2,'Her Şeye Egemen RAB diyor ki, söz dinlemez, adımı onurlandırmaya istekli olmazsanız, üzerinize lanet yağdırıp hayırdualarınızı lanete çevireceğim. Lanetledim bile. Çünkü beni onurlandırmaya istekli değilsiniz.'),
(2006363,68,39,2,3,'‹‹Soyunuzu paylayacağım. Bayramlarınızda kurban ettiğiniz hayvanların gübresini yüzünüze saçacağım. Sizi önümden atacağım.'),
(2006364,68,39,2,4,'Leviyle yaptığım antlaşmanın sürmesi için size bu buyruğu gönderdiğimi bilesiniz.›› Böyle diyor Her Şeye Egemen RAB.'),
(2006365,68,39,2,5,'‹‹Onunla yaşam ve esenlik verecek bir antlaşma yaptım ve bana saygı göstersin diye kendisine bunları verdim. Benden korkup adıma saygı gösterdi.'),
(2006366,68,39,2,6,'Doğru öğüt ağzındaydı. Dudaklarında hile yoktu. Benimle esenlik ve doğruluk içinde yürüdü. Birçoklarını da suç yolundan döndürdü. Masoretik metin ‹‹Sizi ona götürecek››.'),
(2006367,68,39,2,7,'‹‹Kâhinin dudakları bilgiyi korumalı ve insanlar onun ağzından öğüt aramalı. Çünkü o Her Şeye Egemen RABbin ulağıdır.'),
(2006368,68,39,2,8,'Ne var ki, siz yoldan saptınız ve öğrettiklerinizle birçoklarını suça sürüklediniz; Leviyle yaptığım antlaşmayı bozdunuz.›› Böyle diyor Her Şeye Egemen RAB.'),
(2006369,68,39,2,9,'‹‹Benim yollarımı izlemediniz, Kutsal Yasayla ilgili konularda adam kayırdınız. Bu yüzden ben de bütün halkın önünde sizi aşağılayıp gülünç duruma düşürdüm.››'),
(2006370,68,39,2,10,'Hepimizin babası bir değil mi? Bizi yaratan aynı Tanrı değil mi? Öyleyse neden atalarımızın yaptığı antlaşmayı bozarak herkes kardeşine ihanet ediyor?'),
(2006371,68,39,2,11,'Yahuda halkı haince davrandı. İsrailde ve Yeruşalimde iğrenç şeyler yapıldı: Yahuda yabancı ilaha tapınan kızla evlenerek RABbin sevdiği kutsal yeri kirletti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006372,68,39,2,12,'Bunu yapan kişi, kim olursa olsun, Her Şeye Egemen RABbe sunular getirse bile RAB onu Yakupun topluluğundan atsın!'),
(2006373,68,39,2,13,'Yaptığınız başka bir şey var: RABbin sunağını gözyaşı seline boğuyorsunuz. Ağlayıp sızlanıyorsunuz. Çünkü RAB artık getirdiğiniz sunulara ilgi göstermiyor, onları elinizden beğeniyle kabul etmiyor.'),
(2006374,68,39,2,14,'‹‹Neden?›› diye soruyorsunuz. Çünkü RAB seninle gençken evlendiğin karın arasında tanıktır. O yoldaşın ve evlilik antlaşmasıyla karın olduğu halde ona ihanet ettin.'),
(2006375,68,39,2,15,'Tanrı sizi tek beden ve ruh yapmadı mı? Neden tek? Çünkü O kendisine özgü bir soy arıyordu. Onun için kendinize dikkat edin, hiçbiriniz gençken evlendiği karısına ihanet etmesin.'),
(2006376,68,39,2,16,'İsrailin Tanrısı RAB, ‹‹Ben boşanmadan nefret ederim›› diyor, ‹‹Giysisinin üstüne bir de zorbalığı kuşanan kişiden de nefret ederim.›› Böyle diyor Her Şeye Egemen RAB. Bunun için kendinize dikkat edin ve ihanet etmeyin.'),
(2006377,68,39,2,17,'Sözlerinizle RAB''bi usandırdınız. ‹‹O''nu neyle usandırdık?›› diye soruyorsunuz. ‹‹Kötülük yapan herkes RAB''bin gözünde iyidir, O onlardan hoşnuttur›› ya da ‹‹Hani, adalet sağlayan Tanrı nerede?›› diyerek usandırdınız.'),
(2006378,68,39,3,1,'‹‹İşte habercimi gönderiyorum. Önümde yolu hazırlayacak. Aradığınız Rab ansızın tapınağına gelecek; görmeyi özlediğiniz antlaşma habercisi gelecek›› diyor Her Şeye Egemen RAB.'),
(2006379,68,39,3,2,'Ama onun geleceği güne kim dayanabilir? O belirince kim durabilir? Çünkü o maden arıtıcının ateşi, çamaşırcının kül suyu gibi olacak;'),
(2006380,68,39,3,3,'gümüş eritip arıtan gibi davranacak: Levilileri arındırıp altın, gümüş temizler gibi temizleyecek. Böylece RABbe doğrulukla sunular sunacaklar.'),
(2006381,68,39,3,4,'Geçmiş günlerde, geçmiş yıllarda olduğu gibi, RAB Yahuda ve Yeruşalimin sunacağı sunulardan hoşnut kalacak.'),
(2006382,68,39,3,5,'Her Şeye Egemen RAB, ‹‹Yargılamak için size yaklaşacağım›› diyor, ‹‹Büyücülere, zina edenlere, yalan yere ant içenlere, işçinin, dulun, öksüzün, yabancının hakkını çiğneyenlere -benden korkmayanlara- karşı hemen tanık olacağım.››'),
(2006383,68,39,3,6,'‹‹Ben RABbim, değişmem. Siz bunun için yok olmadınız, ey Yakup soyu!'),
(2006384,68,39,3,7,'Atalarınızın günlerinden bu yana kurallarımı çiğnediniz, onlara uymadınız. Bana dönün, ben de size dönerim›› diyor Her Şeye Egemen RAB. ‹‹Oysa siz, ‹Nasıl döneriz?› diye soruyorsunuz.'),
(2006385,68,39,3,8,'‹‹İnsan Tanrıdan çalar mı? Oysa siz benden çalıyorsunuz. ‹‹ ‹Senden nasıl çalıyoruz?› diye soruyorsunuz. ‹‹Ondalıkları, sunuları çalıyorsunuz.'),
(2006386,68,39,3,9,'Siz lanete uğradınız. Çünkü bütün ulus benden çalıyorsunuz.'),
(2006387,68,39,3,10,'Tapınağımda yiyecek bulunması için bütün ondalıklarınızı ambara getirin. Beni bununla sınayın›› diyor Her Şeye Egemen RAB. ‹‹Göreceksiniz ki, göklerin kapaklarını size açacağım, üzerinize dolup taşan bereket yağdıracağım.'),
(2006388,68,39,3,11,'Çekirgelerin ekinlerinizi yemesini engelleyeceğim. Tarlada asmanız ürünsüz kalmayacak›› diyor Her Şeye Egemen RAB.'),
(2006389,68,39,3,12,'‹‹Bütün uluslar ne mutlu size diyecekler. Çünkü ülkeniz özlenen bir yer olacak.›› Böyle diyor Her Şeye Egemen RAB.'),
(2006390,68,39,3,13,'‹‹Bana karşı sert sözler söylediniz›› diyor RAB. ‹‹Oysa siz, ‹Sana karşı ne söyledik?› diye soruyorsunuz.'),
(2006391,68,39,3,14,'‹‹Şunu dediniz: ‹Tanrıya kulluk etmek yararsızdır. Her Şeye Egemen RABbin isteklerini yerine getirmek, Onun önünde yas tutar gibi davranmak bize ne kazanç sağlıyor?'),
(2006392,68,39,3,15,'Şimdi kendini beğenmişlere mutlu diyoruz. Kötülük edenler başarılı oluyor, Tanrıyı deneyenler cezadan kurtuluyor.› ››'),
(2006393,68,39,3,16,'Bunun üzerine RABden korkanlar birbirleriyle konuştular. RAB dediklerine kulak verip duydu. RABden korkup adını sayanlar için Onun önünde bir anma kitabı yazıldı.'),
(2006394,68,39,3,17,'Her Şeye Egemen RAB, ‹‹Öz halkımı ortaya çıkardığım gün, benim olacaklar›› diyor, ‹‹Bir baba kendisine hizmet eden oğlunu nasıl esirgerse ben de onları öyle esirgeyeceğim.'),
(2006395,68,39,3,18,'O zaman siz doğru kişiyle kötü kişi, Tanrı''ya kulluk edenle etmeyen arasındaki ayrımı yine göreceksiniz.››'),
(2006396,68,40,1,1,'İbrahim oğlu, Davut oğlu İsa Mesihin soy kaydı şöyledir: İbrahim İshakın babasıydı, İshak Yakupun babasıydı, Yakup Yahuda ve kardeşlerinin babasıydı,'),
(2006397,68,40,1,3,'Yahuda, Tamardan doğan Peresle Zerahın babasıydı, Peres Hesronun babasıydı, Hesron Ramın babasıydı,'),
(2006398,68,40,1,4,'Ram Amminadavın babasıydı, Amminadav Nahşonun babasıydı, Nahşon Salmonun babasıydı,'),
(2006399,68,40,1,5,'Salmon, Rahavdan doğan Boazın babasıydı, Boaz, Ruttan doğan Ovetin babasıydı, Ovet İşayın babasıydı,'),
(2006400,68,40,1,6,'İşay Kral Davutun babasıydı, Davut, Uriyanın karısından doğan Süleymanın babasıydı,'),
(2006401,68,40,1,7,'Süleyman Rehavamın babasıydı, Rehavam Aviyanın babasıydı, Aviya Asanın babasıydı,'),
(2006402,68,40,1,8,'Asa Yehoşafatın babasıydı, Yehoşafat Yoramın babasıydı, Yoram Uzziyanın babasıydı,'),
(2006403,68,40,1,9,'Uzziya Yotamın babasıydı, Yotam Ahazın babasıydı, Ahaz Hizkiyanın babasıydı,'),
(2006404,68,40,1,10,'Hizkiya Manaşşenin babasıydı, Manaşşe Amonun babasıydı, Amon Yoşiyanın babasıydı,'),
(2006405,68,40,1,11,'Yoşiya, Babil sürgünü sırasında doğan Yehoyakinle kardeşlerinin babasıydı,'),
(2006406,68,40,1,12,'Yehoyakin, Babil sürgününden sonra doğan Şealtielin babasıydı, Şealtiel Zerubbabilin babasıydı,'),
(2006407,68,40,1,13,'Zerubbabil Avihutun babasıydı, Avihut Elyakimin babasıydı, Elyakim Azorun babasıydı,'),
(2006408,68,40,1,14,'Azor Sadokun babasıydı, Sadok Ahimin babasıydı, Ahim Elihutun babasıydı,'),
(2006409,68,40,1,15,'Elihut Elazarın babasıydı, Elazar Mattanın babasıydı, Mattan Yakupun babasıydı,'),
(2006410,68,40,1,16,'Yakup Meryemin kocası Yusufun babasıydı. Meryemden Mesih diye tanınan İsa doğdu.'),
(2006411,68,40,1,17,'Buna göre, İbrahimden Davuta kadar toplam on dört kuşak, Davuttan Babil sürgününe kadar on dört kuşak, Babil sürgününden Mesihe kadar on dört kuşak vardır.'),
(2006412,68,40,1,18,'İsa Mesihin doğumu şöyle oldu: Annesi Meryem, Yusufla nişanlıydı. Ama birlikte olmalarından önce Meryemin Kutsal Ruhtan gebe olduğu anlaşıldı.'),
(2006413,68,40,1,19,'Nişanlısı Yusuf, doğru bir adam olduğu ve onu herkesin önünde utandırmak istemediği için ondan sessizce ayrılmak niyetindeydi.'),
(2006414,68,40,1,20,'Ama böyle düşünmesi üzerine Rabbin bir meleği rüyada ona görünerek şöyle dedi: ‹‹Davut oğlu Yusuf, Meryemi kendine eş olarak almaktan korkma. Çünkü onun rahminde oluşan, Kutsal Ruhtandır.'),
(2006415,68,40,1,21,'Meryem bir oğul doğuracak. Adını İsa koyacaksın. Çünkü halkını günahlarından O kurtaracak.››'),
(2006416,68,40,1,22,'Bütün bunlar, Rabbin peygamber aracılığıyla bildirdiği şu söz yerine gelsin diye oldu:'),
(2006417,68,40,1,23,'‹‹İşte, kız gebe kalıp bir oğul doğuracak; adını İmmanuel koyacaklar.›› İmmanuel, Tanrı bizimle demektir.'),
(2006418,68,40,1,24,'Yusuf uyanınca Rabbin meleğinin buyruğuna uydu ve Meryemi eş olarak yanına aldı.'),
(2006419,68,40,1,25,'Ama oğlunu doğuruncaya dek Yusuf ona dokunmadı. Doğan çocuğun adını İsa koydu.'),
(2006420,68,40,2,1,'İsanın Kral Hirodes devrinde Yahudiyenin Beytlehem Kentinde doğmasından sonra bazı yıldızbilimciler doğudan Yeruşalime gelip şöyle dediler: ‹‹Yahudilerin Kralı olarak doğan çocuk nerede? Doğuda Onun yıldızını gördük ve Ona tapınmaya geldik.››'),
(2006421,68,40,2,3,'Kral Hirodes bunu duyunca kendisi de bütün Yeruşalim halkı da tedirgin oldu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006422,68,40,2,4,'Bütün başkâhinleri ve halkın din bilginlerini toplayarak onlara Mesihin nerede doğacağını sordu.'),
(2006423,68,40,2,5,'‹‹Yahudiyenin Beytlehem Kentinde›› dediler. ‹‹Çünkü peygamber aracılığıyla şöyle yazılmıştır:'),
(2006424,68,40,2,6,'‹Ey sen, Yahudadaki Beytlehem, Yahuda önderleri arasında hiç de en önemsizi değilsin! Çünkü halkım İsraili güdecek önder Senden çıkacak.› ››'),
(2006425,68,40,2,7,'Bunun üzerine Hirodes yıldızbilimcileri gizlice çağırıp onlardan yıldızın göründüğü anı tam olarak öğrendi.'),
(2006426,68,40,2,8,'‹‹Gidin, çocuğu dikkatle arayın, bulunca bana haber verin, ben de gelip Ona tapınayım›› diyerek onları Beytleheme gönderdi.'),
(2006427,68,40,2,9,'Yıldızbilimciler, kralı dinledikten sonra yola çıktılar. Doğuda görmüş oldukları yıldız onlara yol gösteriyordu, çocuğun bulunduğu yerin üzerine varınca durdu.'),
(2006428,68,40,2,10,'Yıldızı gördüklerinde olağanüstü bir sevinç duydular.'),
(2006429,68,40,2,11,'Eve girip çocuğu annesi Meryemle birlikte görünce yere kapanarak Ona tapındılar. Hazinelerini açıp Ona armağan olarak altın, günnük ve mür sundular.'),
(2006430,68,40,2,12,'Sonra gördükleri bir düşte Hirodesin yanına dönmemeleri için uyarılınca ülkelerine başka yoldan döndüler.'),
(2006431,68,40,2,13,'Yıldızbilimciler gittikten sonra Rabbin bir meleği Yusufa rüyada görünerek, ‹‹Kalk!›› dedi, ‹‹Çocukla annesini al, Mısıra kaç. Ben sana haber verinceye dek orada kal. Çünkü Hirodes öldürmek için çocuğu aratacak.››'),
(2006432,68,40,2,14,'Böylece Yusuf kalktı, aynı gece çocukla annesini alıp Mısıra doğru yola çıktı.'),
(2006433,68,40,2,15,'Hirodesin ölümüne dek orada kaldı. Bu, Rabbin peygamber aracılığıyla bildirdiği şu söz yerine gelsin diye oldu: ‹‹Oğlumu Mısırdan çağırdım.››'),
(2006434,68,40,2,16,'Hirodes, yıldızbilimciler tarafından aldatıldığını anlayınca çok öfkelendi. Onlardan öğrendiği vakti göz önüne alarak Beytlehem ve bütün yöresinde bulunan iki ve iki yaşından küçük erkek çocukların hepsini öldürttü.'),
(2006435,68,40,2,17,'Böylelikle Peygamber Yeremya aracılığıyla bildirilen şu söz yerine gelmiş oldu:'),
(2006436,68,40,2,18,'‹‹Ramada bir ses duyuldu, Ağlayış ve acı feryat sesleri! Çocukları için ağlayan Rahel Avutulmak istemiyor. Çünkü onlar yok artık!››'),
(2006437,68,40,2,19,'Hirodes öldükten sonra, Rabbin bir meleği Mısırda Yusufa rüyada görünerek, ‹‹Kalk!›› dedi, ‹‹Çocukla annesini al, İsraile dön. Çünkü çocuğun canına kıymak isteyenler öldü.››'),
(2006438,68,40,2,21,'Bunun üzerine Yusuf kalktı, çocukla annesini alıp İsraile döndü.'),
(2006439,68,40,2,22,'Ama Yahudiyede Hirodesin yerine oğlu Arhelasın kral olduğunu duyunca oraya gitmekten korktu. Rüyada uyarılınca Celile bölgesine gitti.'),
(2006440,68,40,2,23,'Oraya varınca Nasıra denen kente yerleşti. Bu, peygamberler aracılığıyla bildirilen, ‹‹O''na Nasıralı denecektir›› sözü yerine gelsin diye oldu.'),
(2006441,68,40,3,1,'O günlerde Vaftizci Yahya Yahudiye Çölünde ortaya çıktı. Şu çağrıyı yapıyordu: ‹‹Tövbe edin! Göklerin Egemenliği yaklaşmıştır.››'),
(2006442,68,40,3,3,'Nitekim Peygamber Yeşaya aracılığıyla sözü edilen kişi Yahyadır. Yeşaya şöyle demişti: ‹‹Çölde haykıran, ‹Rabbin yolunu hazırlayın, Geçeceği patikaları düzleyin› diye sesleniyor.››'),
(2006443,68,40,3,4,'Yahyanın deve tüyünden giysisi, belinde deri kuşağı vardı. Yediği, çekirge ve yaban balıydı.'),
(2006444,68,40,3,5,'Yeruşalim, bütün Yahudiye ve Şeria yöresinin halkı ona geliyor, günahlarını itiraf ediyor, onun tarafından Şeria Irmağında vaftiz ediliyordu.'),
(2006445,68,40,3,7,'Ne var ki, birçok Ferisiyle Sadukinin vaftiz olmak için kendisine geldiğini gören Yahya onlara şöyle seslendi: ‹‹Ey engerekler soyu! Gelecek gazaptan kaçmak için sizi kim uyardı?'),
(2006446,68,40,3,8,'Bundan böyle tövbeye yaraşır meyveler verin.'),
(2006447,68,40,3,9,'Kendi kendinize, ‹Biz İbrahimin soyundanız› diye düşünmeyin. Ben size şunu söyleyeyim: Tanrı, İbrahime şu taşlardan da çocuk yaratabilir.'),
(2006448,68,40,3,10,'Balta ağaçların köküne dayanmış bile. İyi meyve vermeyen her ağaç kesilip ateşe atılır.'),
(2006449,68,40,3,11,'Gerçi ben sizi tövbe için suyla vaftiz ediyorum, ama benden sonra gelen benden daha güçlüdür. Ben Onun çarıklarını çıkarmaya bile layık değilim. O sizi Kutsal Ruhla ve ateşle vaftiz edecek.'),
(2006450,68,40,3,12,'Yabası elindedir. Harman yerini temizleyecek, buğdayını toplayıp ambara yığacak, samanı ise sönmeyen ateşte yakacak.››'),
(2006451,68,40,3,13,'Bu sırada İsa, Yahya tarafından vaftiz edilmek üzere Celileden Şeria Irmağına, Yahyanın yanına geldi.'),
(2006452,68,40,3,14,'Ne var ki Yahya, ‹‹Benim senin tarafından vaftiz edilmem gerekirken sen mi bana geliyorsun?›› diyerek Ona engel olmak istedi.'),
(2006453,68,40,3,15,'İsa ona şu karşılığı verdi: ‹‹Şimdilik buna razı ol! Çünkü doğru olan her şeyi bu şekilde yerine getirmemiz gerekir.›› O zaman Yahya Onun dediğine razı oldu.'),
(2006454,68,40,3,16,'İsa vaftiz olur olmaz sudan çıktı. O anda gökler açıldı ve İsa, Tanrının Ruhunun güvercin gibi inip üzerine konduğunu gördü.'),
(2006455,68,40,3,17,'Göklerden gelen bir ses, ‹‹Sevgili Oğlum budur, O''ndan hoşnudum›› dedi.'),
(2006456,68,40,4,1,'Bundan sonra İsa, İblis tarafından denenmek üzere Ruh aracılığıyla çöle götürüldü.'),
(2006457,68,40,4,2,'İsa kırk gün kırk gece oruç tuttuktan sonra acıktı.'),
(2006458,68,40,4,3,'O zaman Ayartıcı yaklaşıp, ‹‹Tanrının Oğluysan, söyle şu taşlar ekmek olsun›› dedi.'),
(2006459,68,40,4,4,'İsa ona şu karşılığı verdi: ‹‹ ‹İnsan yalnız ekmekle yaşamaz, Tanrının ağzından çıkan her sözle yaşar› diye yazılmıştır.››'),
(2006460,68,40,4,5,'Sonra İblis Onu kutsal kente götürdü. Tapınağın tepesine çıkarıp, ‹‹Tanrının Oğluysan, kendini aşağı at›› dedi, ‹‹Çünkü şöyle yazılmıştır: ‹Tanrı, senin için meleklerine buyruk verecek.› ‹Ayağın bir taşa çarpmasın diye Seni elleri üzerinde taşıyacaklar.› ››'),
(2006461,68,40,4,7,'İsa İblise şu karşılığı verdi: ‹‹ ‹Tanrın Rabbi denemeyeceksin› diye de yazılmıştır.››'),
(2006462,68,40,4,8,'İblis bu kez İsayı çok yüksek bir dağa çıkardı. Ona bütün görkemiyle dünya ülkelerini göstererek,'),
(2006463,68,40,4,9,'‹‹Yere kapanıp bana taparsan, bütün bunları sana vereceğim›› dedi.'),
(2006464,68,40,4,10,'İsa ona şöyle karşılık verdi: ‹‹Çekil git, Şeytan! ‹Tanrın Rabbe tapacak, yalnız Ona kulluk edeceksin› diye yazılmıştır.››'),
(2006465,68,40,4,11,'Bunun üzerine İblis İsayı bırakıp gitti. Melekler gelip İsaya hizmet ettiler.'),
(2006466,68,40,4,12,'İsa, Yahyanın tutuklandığını duyunca Celileye döndü.'),
(2006467,68,40,4,13,'Nasıradan ayrılarak Zevulun ve Naftali yöresinde, Celile Gölü kıyısında bulunan Kefarnahuma yerleşti.'),
(2006468,68,40,4,14,'Bu, Peygamber Yeşaya aracılığıyla bildirilen şu söz yerine gelsin diye oldu: ‹‹Zevulun ve Naftali bölgeleri, Şeria Irmağının ötesinde, Deniz Yolunda, Ulusların yaşadığı Celile!'),
(2006469,68,40,4,16,'Karanlıkta yaşayan halk, Büyük bir ışık gördü. Ölümün gölgelediği diyarda Yaşayanlara ışık doğdu.››'),
(2006470,68,40,4,17,'O günden sonra İsa şu çağrıda bulunmaya başladı: ‹‹Tövbe edin! Çünkü Göklerin Egemenliği yaklaştı.››'),
(2006471,68,40,4,18,'İsa, Celile Gölünün kıyısında yürürken Petrus diye de anılan Simunla kardeşi Andreası gördü. Balıkçı olan bu iki kardeş göle ağ atıyorlardı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006472,68,40,4,19,'Onlara, ‹‹Ardımdan gelin›› dedi, ‹‹Sizleri insan tutan balıkçılar yapacağım.››'),
(2006473,68,40,4,20,'Onlar da hemen ağlarını bırakıp Onun ardından gittiler.'),
(2006474,68,40,4,21,'İsa daha ileri gidince başka iki kardeşi, Zebedinin oğulları Yakupla Yuhannayı gördü. Babaları Zebediyle birlikte teknede ağlarını onarıyorlardı. Onları da çağırdı.'),
(2006475,68,40,4,22,'Hemen tekneyi ve babalarını bırakıp İsanın ardından gittiler.'),
(2006476,68,40,4,23,'İsa, Celile bölgesinin her tarafını dolaştı. Buralardaki havralarda öğretiyor, göksel egemenliğin Müjdesini duyuruyor, halk arasında rastlanan her hastalığı, her illeti iyileştiriyordu.'),
(2006477,68,40,4,24,'Ünü bütün Suriyeye yayılmıştı. Türlü hastalıklara yakalanmış bütün hastaları, acı çekenleri, cinlileri, saralıları, felçlileri Ona getirdiler; hepsini iyileştirdi.'),
(2006478,68,40,4,25,'Celile, Dekapolis, Yeruşalim, Yahudiye ve Şeria Irmağı''nın karşı yakasından gelen büyük kalabalıklar O''nun ardından gidiyordu.'),
(2006479,68,40,5,1,'İsa kalabalıkları görünce dağa çıktı. Oturunca öğrencileri yanına geldi.'),
(2006480,68,40,5,2,'İsa konuşmaya başlayıp onlara şunları öğretti:'),
(2006481,68,40,5,3,'‹‹Ne mutlu ruhta yoksul olanlara! Çünkü Göklerin Egemenliği onlarındır.'),
(2006482,68,40,5,4,'Ne mutlu yaslı olanlara! Çünkü onlar teselli edilecekler.'),
(2006483,68,40,5,5,'Ne mutlu yumuşak huylu olanlara! Çünkü onlar yeryüzünü miras alacaklar.'),
(2006484,68,40,5,6,'Ne mutlu doğruluğa acıkıp susayanlara! Çünkü onlar doyurulacaklar.'),
(2006485,68,40,5,7,'Ne mutlu merhametli olanlara! Çünkü onlar merhamet bulacaklar.'),
(2006486,68,40,5,8,'Ne mutlu yüreği temiz olanlara! Çünkü onlar Tanrıyı görecekler.'),
(2006487,68,40,5,9,'Ne mutlu barışı sağlayanlara! Çünkü onlara Tanrı oğulları denecek.'),
(2006488,68,40,5,10,'Ne mutlu doğruluk uğruna zulüm görenlere! Çünkü Göklerin Egemenliği onlarındır.'),
(2006489,68,40,5,11,'‹‹Benim yüzümden insanlar size sövüp zulmettikleri, yalan yere size karşı her türlü kötü sözü söyledikleri zaman ne mutlu size!'),
(2006490,68,40,5,12,'Sevinin, sevinçle coşun! Çünkü göklerdeki ödülünüz büyüktür. Sizden önce yaşayan peygamberlere de böyle zulmettiler.››'),
(2006491,68,40,5,13,'‹‹Yeryüzünün tuzu sizsiniz. Ama tuz tadını yitirirse, bir daha ona nasıl tuz tadı verilebilir? Artık dışarı atılıp ayak altında çiğnenmekten başka işe yaramaz.'),
(2006492,68,40,5,14,'‹‹Dünyanın ışığı sizsiniz. Tepeye kurulan kent gizlenemez.'),
(2006493,68,40,5,15,'Kimse kandil yakıp tahıl ölçeğinin altına koymaz. Tersine, kandilliğe koyar; evdekilerin hepsine ışık sağlar.'),
(2006494,68,40,5,16,'Sizin ışığınız insanların önünde öyle parlasın ki, iyi işlerinizi görerek göklerdeki Babanızı yüceltsinler!››'),
(2006495,68,40,5,17,'‹‹Kutsal Yasayı ya da peygamberlerin sözlerini geçersiz kılmak için geldiğimi sanmayın. Ben geçersiz kılmaya değil, tamamlamaya geldim.'),
(2006496,68,40,5,18,'Size doğrusunu söyleyeyim, yer ve gök ortadan kalkmadan, her şey gerçekleşmeden, Kutsal Yasadan ufacık bir harf ya da bir nokta bile yok olmayacak.'),
(2006497,68,40,5,19,'Bu nedenle, bu buyrukların en küçüğünden birini kim çiğner ve başkalarına öyle öğretirse, Göklerin Egemenliğinde en küçük sayılacak. Ama bu buyrukları kim yerine getirir ve başkalarına öğretirse, Göklerin Egemenliğinde büyük sayılacak.'),
(2006498,68,40,5,20,'Size şunu söyleyeyim: Doğruluğunuz din bilginleriyle Ferisilerinkini aşmadıkça, Göklerin Egemenliğine asla giremezsiniz!››'),
(2006499,68,40,5,21,'‹‹Atalarımıza, ‹Adam öldürmeyeceksin. Öldüren yargılanacak› dendiğini duydunuz.'),
(2006500,68,40,5,22,'Ama ben size diyorum ki, kardeşine öfkelenen herkes yargılanacaktır. Kim kardeşine aşağılayıcı bir söz söylerse, Yüksek Kurulda yargılanacaktır. Kim kardeşine ahmak derse, cehennem ateşini hak edecektir.'),
(2006501,68,40,5,23,'Bu yüzden, sunakta adak sunarken kardeşinin sana karşı bir şikâyeti olduğunu anımsarsan, adağını orada, sunağın önünde bırak, git önce kardeşinle barış; sonra gelip adağını sun.'),
(2006502,68,40,5,25,'Senden davacı olanla daha yoldayken çabucak anlaş. Yoksa o seni yargıca, yargıç da gardiyana teslim edebilir; sonunda da hapse atılabilirsin.'),
(2006503,68,40,5,26,'Sana doğrusunu söyleyeyim, borcunun son kuruşunu ödemeden oradan asla çıkamazsın.››'),
(2006504,68,40,5,27,'‹‹ ‹Zina etmeyeceksin› dendiğini duydunuz.'),
(2006505,68,40,5,28,'Ama ben size diyorum ki, bir kadına şehvetle bakan her adam, yüreğinde o kadınla zina etmiş olur.'),
(2006506,68,40,5,29,'Eğer sağ gözün günah işlemene neden olursa, onu çıkar at. Çünkü vücudunun bir üyesinin yok olması, bütün vücudunun cehenneme atılmasından iyidir.'),
(2006507,68,40,5,30,'Eğer sağ elin günah işlemene neden olursa, onu kes at. Çünkü vücudunun bir üyesinin yok olması, bütün vücudunun cehenneme gitmesinden iyidir.'),
(2006508,68,40,5,31,'‹‹ ‹Kim karısını boşarsa ona boşanma belgesi versin› denmiştir.'),
(2006509,68,40,5,32,'Ama ben size diyorum ki, karısını fuhuş dışında bir nedenle boşayan onu zinaya itmiş olur. Boşanmış bir kadınla evlenen de zina etmiş olur.››'),
(2006510,68,40,5,33,'‹‹Yine atalarımıza, ‹Yalan yere ant içmeyeceksin, ama Rabbin önünde içtiğin antları yerine getireceksin› dendiğini duydunuz.'),
(2006511,68,40,5,34,'Oysa ben size diyorum ki, hiç ant içmeyin: Ne gök üzerine, çünkü orası Tanrının tahtıdır; ne yer üzerine, çünkü orası Onun ayak taburesidir; ne de Yeruşalim üzerine, çünkü orası Büyük Kralın kentidir.'),
(2006512,68,40,5,36,'Başınızın üzerine de ant içmeyin. Çünkü saçınızın tek telini ak ya da kara edemezsiniz.'),
(2006513,68,40,5,37,'‹Evet›iniz evet, ‹hayır›ınız hayır olsun. Bundan fazlası Şeytandandır.››'),
(2006514,68,40,5,38,'‹‹ ‹Göze göz, dişe diş› dendiğini duydunuz.'),
(2006515,68,40,5,39,'Ama ben size diyorum ki, kötüye karşı direnmeyin. Sağ yanağınıza bir tokat atana öbür yanağınızı da çevirin.'),
(2006516,68,40,5,40,'Size karşı davacı olup mintanınızı almak isteyene abanızı da verin.'),
(2006517,68,40,5,41,'Sizi bin adım yol yürümeye zorlayanla iki bin adım yürüyün.'),
(2006518,68,40,5,42,'Sizden bir şey dileyene verin, sizden ödünç isteyeni geri çevirmeyin.››'),
(2006519,68,40,5,43,'‹‹ ‹Komşunu seveceksin, düşmanından nefret edeceksin› dendiğini duydunuz.'),
(2006520,68,40,5,44,'Ama ben size diyorum ki, düşmanlarınızı sevin, size zulmedenler için dua edin.'),
(2006521,68,40,5,45,'Öyle ki, göklerdeki Babanızın oğulları olasınız. Çünkü O, güneşini hem kötülerin hem iyilerin üzerine doğdurur; yağmurunu hem doğruların hem eğrilerin üzerine yağdırır.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006522,68,40,5,46,'Eğer yalnız sizi sevenleri severseniz, ne ödülünüz olur? Vergi görevlileri de öyle yapmıyor mu?'),
(2006523,68,40,5,47,'Yalnız kardeşlerinize selam verirseniz, fazladan ne yapmış olursunuz? Putperestler de öyle yapmıyor mu?'),
(2006524,68,40,5,48,'Bu nedenle, göksel Babanız yetkin olduğu gibi, siz de yetkin olun.››'),
(2006525,68,40,6,1,'‹‹Doğruluğunuzu insanların gözü önünde gösteriş amacıyla sergilemekten kaçının. Yoksa göklerdeki Babanızdan ödül alamazsınız.'),
(2006526,68,40,6,2,'‹‹Bu nedenle, birisine sadaka verirken bunu borazan çaldırarak ilan etmeyin. İkiyüzlüler, insanların övgüsünü kazanmak için havralarda ve sokaklarda böyle yaparlar. Size doğrusunu söyleyeyim, onlar ödüllerini almışlardır.'),
(2006527,68,40,6,3,'Siz sadaka verirken, sol eliniz sağ elinizin ne yaptığını bilmesin.'),
(2006528,68,40,6,4,'Öyle ki, verdiğiniz sadaka gizli kalsın. Gizlice yapılanı gören Babanız sizi ödüllendirecektir.››'),
(2006529,68,40,6,5,'‹‹Dua ettiğiniz zaman ikiyüzlüler gibi olmayın. Onlar, herkes kendilerini görsün diye havralarda ve caddelerin köşe başlarında dikilip dua etmekten zevk alırlar. Size doğrusunu söyleyeyim, onlar ödüllerini almışlardır.'),
(2006530,68,40,6,6,'Ama siz dua edeceğiniz zaman iç odanıza çekilip kapıyı örtün ve gizlide olan Babanıza dua edin. Gizlilik içinde yapılanı gören Babanız sizi ödüllendirecektir.'),
(2006531,68,40,6,7,'Dua ettiğinizde, putperestler gibi boş sözler tekrarlayıp durmayın. Onlar söz kalabalığıyla seslerini duyurabileceklerini sanırlar.'),
(2006532,68,40,6,8,'Siz onlara benzemeyin! Çünkü Babanız nelere gereksinmeniz olduğunu siz daha Ondan dilemeden önce bilir.'),
(2006533,68,40,6,9,'‹‹Bunun için siz şöyle dua edin: ‹Göklerdeki Babamız, Adın kutsal kılınsın.'),
(2006534,68,40,6,10,'Egemenliğin gelsin. Gökte olduğu gibi, yeryüzünde de Senin istediğin olsun.'),
(2006535,68,40,6,11,'Bugün bize gündelik ekmeğimizi ver.'),
(2006536,68,40,6,12,'Bize karşı suç işleyenleri bağışladığımız gibi, Sen de bizim suçlarımızı bağışla.'),
(2006537,68,40,6,13,'Ayartılmamıza izin verme. Bizi kötü olandan kurtar. Çünkü egemenlik, güç ve yücelik Sonsuzlara dek senindir! Amin›.'),
(2006538,68,40,6,14,'‹‹Başkalarının suçlarını bağışlarsanız, göksel Babanız da sizin suçlarınızı bağışlar.'),
(2006539,68,40,6,15,'Ama siz başkalarının suçlarını bağışlamazsanız, Babanız da sizin suçlarınızı bağışlamaz.››'),
(2006540,68,40,6,16,'‹‹Oruç tuttuğunuz zaman, ikiyüzlüler gibi surat asmayın. Onlar oruç tuttuklarını insanlara belli etmek için kendilerine perişan bir görünüm verirler. Size doğrusunu söyleyeyim, onlar ödüllerini almışlardır.'),
(2006541,68,40,6,17,'Siz oruç tuttuğunuz zaman, başınıza yağ sürüp yüzünüzü yıkayın.'),
(2006542,68,40,6,18,'Öyle ki, insanlara değil, gizlide olan Babanıza oruçlu görünesiniz. Gizlilik içinde yapılanı gören Babanız sizi ödüllendirecektir.››'),
(2006543,68,40,6,19,'‹‹Yeryüzünde kendinize hazineler biriktirmeyin. Burada güve ve pas onları yiyip bitirir, hırsızlar da girip çalarlar.'),
(2006544,68,40,6,20,'Bunun yerine kendinize gökte hazineler biriktirin. Orada ne güve ne pas onları yiyip bitirir, ne de hırsızlar girip çalar.'),
(2006545,68,40,6,21,'Hazineniz neredeyse, yüreğiniz de orada olacaktır.'),
(2006546,68,40,6,22,'‹‹Bedenin ışığı gözdür. Gözünüz sağlamsa, bütün bedeniniz aydınlık olur.'),
(2006547,68,40,6,23,'Gözünüz bozuksa, bütün bedeniniz karanlık olur. Buna göre, içinizdeki ‹ışık› karanlıksa, ne korkunçtur o karanlık!'),
(2006548,68,40,6,24,'‹‹Hiç kimse iki efendiye kulluk edemez. Ya birinden nefret edip öbürünü sever, ya da birine bağlanıp öbürünü hor görür. Siz hem Tanrıya, hem de paraya kulluk edemezsiniz.››'),
(2006549,68,40,6,25,'‹‹Bu nedenle size şunu söylüyorum: ‹Ne yiyip ne içeceğiz?› diye canınız için, ‹Ne giyeceğiz?› diye bedeniniz için kaygılanmayın. Can yiyecekten, beden de giyecekten daha önemli değil mi?'),
(2006550,68,40,6,26,'Gökte uçan kuşlara bakın! Ne eker, ne biçer, ne de ambarlarda yiyecek biriktirirler. Göksel Babanız yine de onları doyurur. Siz onlardan çok daha değerli değil misiniz?'),
(2006551,68,40,6,27,'Hangi biriniz kaygılanmakla ömrünü bir anlık uzatabilir?'),
(2006552,68,40,6,28,'Giyecek konusunda neden kaygılanıyorsunuz? Kır zambaklarının nasıl büyüdüğüne bakın! Ne çalışırlar, ne de iplik eğirirler.'),
(2006553,68,40,6,29,'Ama size şunu söyleyeyim, bütün görkemine karşın Süleyman bile bunlardan biri gibi giyinmiş değildi.'),
(2006554,68,40,6,30,'Bugün var olup yarın ocağa atılacak olan kır otunu böyle giydiren Tanrının sizi de giydireceği çok daha kesin değil mi, ey kıt imanlılar?'),
(2006555,68,40,6,31,'‹‹Öyleyse, ‹Ne yiyeceğiz?› ‹Ne içeceğiz?› ya da ‹Ne giyeceğiz?› diyerek kaygılanmayın.'),
(2006556,68,40,6,32,'Uluslar hep bu şeylerin peşinden giderler. Oysa göksel Babanız bütün bunlara gereksinmeniz olduğunu bilir.'),
(2006557,68,40,6,33,'Siz öncelikle Onun egemenliğinin ve doğruluğunun ardından gidin, o zaman size bütün bunlar da verilecektir.'),
(2006558,68,40,6,34,'O halde yarın için kaygılanmayın. Yarının kaygısı yarının olsun. Her günün derdi kendine yeter.››'),
(2006559,68,40,7,1,'‹‹Başkasını yargılamayın ki, siz de yargılanmayasınız.'),
(2006560,68,40,7,2,'Çünkü nasıl yargılarsanız öyle yargılanacaksınız. Hangi ölçekle verirseniz, aynı ölçekle alacaksınız.'),
(2006561,68,40,7,3,'Sen neden kardeşinin gözündeki çöpü görürsün de kendi gözündeki merteği farketmezsin?'),
(2006562,68,40,7,4,'Kendi gözünde mertek varken kardeşine nasıl, ‹İzin ver, gözündeki çöpü çıkarayım› dersin?'),
(2006563,68,40,7,5,'Seni ikiyüzlü! Önce kendi gözündeki merteği çıkar, o zaman kardeşinin gözündeki çöpü çıkarmak için daha iyi görürsün.'),
(2006564,68,40,7,6,'‹‹Kutsal olanı köpeklere vermeyin. İncilerinizi domuzların önüne atmayın. Yoksa bunları ayaklarıyla çiğnedikten sonra dönüp sizi parçalayabilirler.››'),
(2006565,68,40,7,7,'‹‹Dileyin, size verilecek; arayın, bulacaksınız; kapıyı çalın, size açılacaktır.'),
(2006566,68,40,7,8,'Çünkü her dileyen alır, arayan bulur, kapı çalana açılır.'),
(2006567,68,40,7,9,'Hanginiz kendisinden ekmek isteyen oğluna taş verir?'),
(2006568,68,40,7,10,'Ya da balık isterse yılan verir?'),
(2006569,68,40,7,11,'Sizler kötü yürekli olduğunuz halde çocuklarınıza güzel armağanlar vermeyi biliyorsanız, göklerdeki Babanızın, kendisinden dileyenlere güzel armağanlar vereceği çok daha kesin değil mi?'),
(2006570,68,40,7,12,'‹‹İnsanların size nasıl davranmasını istiyorsanız, siz de onlara öyle davranın. Çünkü Kutsal Yasanın ve peygamberlerin söylediği budur.››'),
(2006571,68,40,7,13,'‹‹Dar kapıdan girin. Çünkü yıkıma götüren kapı geniş ve yol enlidir. Bu kapıdan girenler çoktur.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006572,68,40,7,14,'Oysa yaşama götüren kapı dar, yol da çetindir. Bu yolu bulanlar azdır.››'),
(2006573,68,40,7,15,'‹‹Sahte peygamberlerden sakının! Onlar size kuzu postuna bürünerek yaklaşırlar, ama özde yırtıcı kurtlardır.'),
(2006574,68,40,7,16,'Onları meyvelerinden tanıyacaksınız. Dikenli bitkilerden üzüm, devedikenlerinden incir toplanabilir mi?'),
(2006575,68,40,7,17,'Bunun gibi, her iyi ağaç iyi meyve verir, kötü ağaç ise kötü meyve verir.'),
(2006576,68,40,7,18,'İyi ağaç kötü meyve, kötü ağaç da iyi meyve veremez.'),
(2006577,68,40,7,19,'İyi meyve vermeyen her ağaç kesilip ateşe atılır.'),
(2006578,68,40,7,20,'Böylece sahte peygamberleri meyvelerinden tanıyacaksınız.'),
(2006579,68,40,7,21,'‹‹Bana, ‹Ya Rab, ya Rab!› diye seslenen herkes Göklerin Egemenliğine girmeyecek. Ancak göklerdeki Babamın isteğini yerine getiren girecektir.'),
(2006580,68,40,7,22,'O gün birçokları bana diyecek ki, ‹Ya Rab, ya Rab! Biz senin adınla peygamberlik etmedik mi? Senin adınla cinler kovmadık mı? Senin adınla birçok mucize yapmadık mı?›'),
(2006581,68,40,7,23,'O zaman ben de onlara açıkça, ‹Sizi hiç tanımadım, uzak durun benden, ey kötülük yapanlar!› diyeceğim.››'),
(2006582,68,40,7,24,'‹‹İşte bu sözlerimi duyup uygulayan herkes, evini kaya üzerine kuran akıllı adama benzer.'),
(2006583,68,40,7,25,'Yağmur yağar, seller basar, yeller eser, eve saldırır; ama ev yıkılmaz. Çünkü kaya üzerine kurulmuştur.'),
(2006584,68,40,7,26,'Bu sözlerimi duyup da uygulamayan herkes, evini kum üzerine kuran budala adama benzer.'),
(2006585,68,40,7,27,'Yağmur yağar, seller basar, yeller eser, evi sarsar. Ev yıkılır; yıkılışı da korkunç olur.››'),
(2006586,68,40,7,28,'İsa konuşmasını bitirince, halk Onun öğretişine şaşıp kaldı.'),
(2006587,68,40,7,29,'Çünkü onlara kendi din bilginleri gibi değil, yetkili biri gibi öğretiyordu.'),
(2006588,68,40,8,1,'İsa dağdan inince büyük bir kalabalık Onun ardından gitti.'),
(2006589,68,40,8,2,'Bu sırada cüzamlı bir adam yaklaşıp, ‹‹Ya Rab, istersen beni temiz kılabilirsin›› diyerek Onun ayaklarına kapandı.'),
(2006590,68,40,8,3,'İsa elini uzatıp adama dokundu, ‹‹İsterim, temiz ol!›› dedi. Adam anında cüzamdan temizlendi.'),
(2006591,68,40,8,4,'Sonra İsa adama, ‹‹Sakın kimseye bir şey söyleme!›› dedi. ‹‹Git, kâhine görün ve cüzamdan temizlendiğini herkese kanıtlamak için Musanın buyurduğu sunuyu sun.››'),
(2006592,68,40,8,5,'İsa Kefarnahuma varınca bir yüzbaşı Ona gelip, ‹‹Ya Rab›› diye yalvardı, ‹‹Uşağım felç oldu, evde yatıyor; korkunç acı çekiyor.››'),
(2006593,68,40,8,7,'İsa, ‹‹Gelip onu iyileştireceğim›› dedi.'),
(2006594,68,40,8,8,'Ama yüzbaşı, ‹‹Ya Rab, evime girmene layık değilim›› dedi, ‹‹Yeter ki bir söz söyle, uşağım iyileşir.'),
(2006595,68,40,8,9,'Ben de buyruk altında bir adamım, benim de buyruğumda askerlerim var. Birine, ‹Git› derim, gider; ötekine, ‹Gel› derim, gelir; köleme, ‹Şunu yap› derim, yapar.››'),
(2006596,68,40,8,10,'İsa, duyduğu bu sözlere hayran kaldı. Ardından gelenlere, ‹‹Size doğrusunu söyleyeyim›› dedi, ‹‹Ben İsrailde böyle imanı olan birini görmedim.'),
(2006597,68,40,8,11,'Size şunu söyleyeyim, doğudan ve batıdan birçok insan gelecek, Göklerin Egemenliğinde İbrahimle, İshakla ve Yakupla birlikte sofraya oturacaklar.'),
(2006598,68,40,8,12,'Ama bu egemenliğin asıl mirasçıları dışarıdaki karanlığa atılacak. Orada ağlayış ve diş gıcırtısı olacak.››'),
(2006599,68,40,8,13,'Sonra İsa yüzbaşıya, ‹‹Git, inandığın gibi olsun›› dedi. Ve uşak o anda iyileşti.'),
(2006600,68,40,8,14,'İsa Petrusun evine geldiğinde onun kaynanasının ateşler içinde yattığını gördü.'),
(2006601,68,40,8,15,'Eline dokununca kadının ateşi düştü. Kadın kalkıp İsaya hizmet etmeye başladı.'),
(2006602,68,40,8,16,'Akşam olunca birçok cinliyi kendisine getirdiler. İsa onlardaki kötü ruhları tek sözle kovdu, hastaların hepsini iyileştirdi.'),
(2006603,68,40,8,17,'Bu, Peygamber Yeşaya aracılığıyla bildirilen şu söz yerine gelsin diye oldu: ‹‹Zayıflıklarımızı O kaldırdı, Hastalıklarımızı O üstlendi.››'),
(2006604,68,40,8,18,'İsa, çevresindeki kalabalığı görünce gölün karşı yakasına geçilmesini buyurdu.'),
(2006605,68,40,8,19,'O sırada din bilginlerinden biri Ona yaklaşıp, ‹‹Öğretmenim›› dedi, ‹‹Nereye gidersen, senin ardından geleceğim.››'),
(2006606,68,40,8,20,'İsa ona, ‹‹Tilkilerin ini, kuşların yuvası var, ama İnsanoğlunun başını yaslayacak bir yeri yok›› dedi.'),
(2006607,68,40,8,21,'Başka bir öğrencisi İsaya, ‹‹Ya Rab, izin ver, önce gidip babamı gömeyim›› dedi.'),
(2006608,68,40,8,22,'İsa ona, ‹‹Ardımdan gel›› dedi. ‹‹Bırak ölüleri, kendi ölülerini kendileri gömsün.››'),
(2006609,68,40,8,23,'İsa tekneye binince, ardından öğrencileri de bindi.'),
(2006610,68,40,8,24,'Gölde ansızın büyük bir fırtına koptu. Öyle ki, dalgalar teknenin üzerinden aşıyordu. İsa bu arada uyuyordu.'),
(2006611,68,40,8,25,'Öğrenciler gidip Onu uyandırarak, ‹‹Ya Rab, kurtar bizi, yoksa öleceğiz!›› dediler.'),
(2006612,68,40,8,26,'İsa, ‹‹Neden korkuyorsunuz, ey kıt imanlılar?›› dedi. Sonra kalkıp rüzgarı ve gölü azarladı. Ortalık sütliman oldu.'),
(2006613,68,40,8,27,'Hepsi hayret içinde kaldı. ‹‹Bu nasıl bir adam ki, rüzgar da göl de Onun sözünü dinliyor?›› dediler.'),
(2006614,68,40,8,28,'İsa gölün karşı yakasında Gadaralıların memleketine vardı. Orada Onu mezarlık mağaralardan çıkan iki cinli karşıladı. Bunlar öyle tehlikeliydi ki, kimse o yoldan geçemiyordu.'),
(2006615,68,40,8,29,'İsaya, ‹‹Ey Tanrının Oğlu, bizden ne istiyorsun?›› diye bağırdılar. ‹‹Buraya, vaktinden önce bize işkence etmek için mi geldin?››'),
(2006616,68,40,8,30,'Onlardan uzakta otlayan büyük bir domuz sürüsü vardı.'),
(2006617,68,40,8,31,'Cinler İsaya, ‹‹Bizi kovacaksan, şu domuz sürüsüne gönder›› diye yalvardılar.'),
(2006618,68,40,8,32,'İsa onlara, ‹‹Gidin!›› dedi. Cinler de adamlardan çıkıp domuzların içine girdiler. O anda bütün sürü dik yamaçtan aşağı koşuşarak göle atlayıp boğuldu.'),
(2006619,68,40,8,33,'Domuzları güdenler kaçıp kente gittiler. Cinli adamlarla ilgili haberler dahil, olup bitenlerin hepsini anlattılar.'),
(2006620,68,40,8,34,'Bunun üzerine bütün kent halkı İsa''yı karşılamaya çıktı. O''nu görünce bölgelerinden ayrılması için yalvardılar.'),
(2006621,68,40,9,1,'İsa tekneye binip karşı kıyıya geçti ve kendi kentine gitti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006622,68,40,9,2,'Kendisine, yatak üzerinde felçli bir adam getirdiler. İsa onların imanını görünce felçliye, ‹‹Cesur ol, oğlum, günahların bağışlandı›› dedi.'),
(2006623,68,40,9,3,'Bunun üzerine bazı din bilginleri içlerinden, ‹‹Bu adam Tanrıya küfrediyor!›› dediler.'),
(2006624,68,40,9,4,'Onların ne düşündüklerini bilen İsa dedi ki, ‹‹Yüreğinizde neden kötü düşüncelere yer veriyorsunuz?'),
(2006625,68,40,9,5,'Hangisi daha kolay? ‹Günahların bağışlandı› demek mi, yoksa ‹Kalk, yürü› demek mi?'),
(2006626,68,40,9,6,'Ne var ki, İnsanoğlunun yeryüzünde günahları bağışlama yetkisine sahip olduğunu bilesiniz diye...›› Sonra felçliye, ‹‹Kalk, yatağını topla, evine git!›› dedi.'),
(2006627,68,40,9,7,'Adam da kalkıp evine gitti.'),
(2006628,68,40,9,8,'Halk bunu görünce korkuya kapıldı. İnsana böyle bir yetki veren Tanrıyı yücelttiler.'),
(2006629,68,40,9,9,'İsa oradan geçerken, vergi toplama yerinde oturan birini gördü. Matta adındaki bu adama, ‹‹Ardımdan gel›› dedi. Adam da kalkıp İsanın ardından gitti.'),
(2006630,68,40,9,10,'Sonra İsa, Mattanın evinde sofrada otururken, birçok vergi görevlisiyle günahkâr gelip Onunla ve öğrencileriyle birlikte sofraya oturdu.'),
(2006631,68,40,9,11,'Bunu gören Ferisiler, İsanın öğrencilerine, ‹‹Sizin öğretmeniniz neden vergi görevlileri ve günahkârlarla birlikte yemek yiyor?›› diye sordular.'),
(2006632,68,40,9,12,'İsa bunu duyunca şöyle dedi: ‹‹Sağlamların değil, hastaların hekime ihtiyacı var.'),
(2006633,68,40,9,13,'Gidin de, ‹Ben kurban değil, merhamet isterim› sözünün anlamını öğrenin. Çünkü ben doğru kişileri değil, günahkârları çağırmaya geldim.››'),
(2006634,68,40,9,14,'Bu arada Yahyanın öğrencileri gelip İsaya, ‹‹Neden biz ve Ferisiler oruç tutuyoruz da senin öğrencilerin tutmuyor?›› diye sordular.'),
(2006635,68,40,9,15,'İsa şöyle karşılık verdi: ‹‹Güvey aralarındayken, davetliler yas tutar mı? Ama güveyin aralarından alınacağı günler gelecek, o zaman oruç tutacaklar.'),
(2006636,68,40,9,16,'Hiç kimse eski giysiyi yeni kumaş parçasıyla yamamaz. Çünkü yeni kumaş çeker, giysiden kopar, yırtık daha beter olur.'),
(2006637,68,40,9,17,'Hiç kimse yeni şarabı eski tulumlara doldurmaz. Yoksa tulumlar patlar; hem şarap dökülür, hem de tulumlar mahvolur. Yeni şarap yeni tulumlara konur, böylece her ikisi de korunmuş olur.››'),
(2006638,68,40,9,18,'İsa onlara bu sözleri söylerken bir havra yöneticisi gelip Onun önünde yere kapanarak, ‹‹Kızım az önce öldü. Ama sen gelip elini onun üzerine koyarsan, dirilecek›› dedi.'),
(2006639,68,40,9,19,'İsa kalkıp öğrencileriyle birlikte adamın ardından gitti.'),
(2006640,68,40,9,20,'Tam o sırada, on iki yıldır kanaması olan bir kadın İsanın arkasından yetişip giysisinin eteğine dokundu.'),
(2006641,68,40,9,21,'İçinden, ‹‹Giysisine bir dokunsam kurtulurum›› diyordu.'),
(2006642,68,40,9,22,'İsa arkasına dönüp onu görünce, ‹‹Cesur ol, kızım! İmanın seni kurtardı›› dedi. Ve kadın o anda iyileşti.'),
(2006643,68,40,9,23,'İsa, yöneticinin evine varıp kaval çalanlarla gürültülü kalabalığı görünce, ‹‹Çekilin!›› dedi. ‹‹Kız ölmedi, uyuyor.›› Onlar ise kendisiyle alay ettiler.'),
(2006644,68,40,9,25,'Kalabalık dışarı çıkarılınca İsa içeri girip kızın elini tuttu, kız ayağa kalktı.'),
(2006645,68,40,9,26,'Bu haber bütün bölgeye yayıldı.'),
(2006646,68,40,9,27,'İsa oradan ayrılırken iki kör, ‹‹Ey Davut Oğlu, halimize acı!›› diye feryat ederek Onun ardından gittiler.'),
(2006647,68,40,9,28,'İsa eve girince körler yanına geldi. Onlara, ‹‹İstediğinizi yapabileceğime inanıyor musunuz?›› diye sordu. Körler, ‹‹İnanıyoruz, ya Rab!›› dediler.'),
(2006648,68,40,9,29,'Bunun üzerine İsa körlerin gözlerine dokunarak, ‹‹İmanınıza göre olsun›› dedi.'),
(2006649,68,40,9,30,'Ve adamların gözleri açıldı. İsa, ‹‹Sakın kimse bunu bilmesin›› diyerek onları sıkı sıkı uyardı.'),
(2006650,68,40,9,31,'Onlar ise çıkıp İsayla ilgili haberi bütün bölgeye yaydılar.'),
(2006651,68,40,9,32,'Adamlar çıkarken İsaya dilsiz bir cinli getirdiler.'),
(2006652,68,40,9,33,'Cin kovulunca adamın dili çözüldü. Halk hayret içinde, ‹‹İsrailde böylesi hiç görülmemiştir›› diyordu.'),
(2006653,68,40,9,34,'Ferisiler ise, ‹‹Cinleri, cinlerin önderinin gücüyle kovuyor›› diyorlardı.'),
(2006654,68,40,9,35,'İsa bütün kent ve köyleri dolaşarak havralarda öğretiyor, göksel egemenliğin Müjdesini duyuruyor, her hastalığı, her illeti iyileştiriyordu.'),
(2006655,68,40,9,36,'Kalabalıkları görünce onlara acıdı. Çünkü çobansız koyunlar gibi şaşkın ve perişandılar.'),
(2006656,68,40,9,37,'O zaman İsa öğrencilerine, ‹‹Ürün bol, ama işçi az›› dedi,'),
(2006657,68,40,9,38,'‹‹Bu nedenle ürünün sahibi Rab''be yalvarın, ürününü kaldıracak işçiler göndersin.››'),
(2006658,68,40,10,1,'İsa on iki öğrencisini yanına çağırıp onlara kötü ruhlar üzerinde yetki verdi. Böylece kötü ruhları kovacak, her hastalığı, her illeti iyileştireceklerdi.'),
(2006659,68,40,10,2,'Bu on iki elçinin adları şöyle: Birincisi Petrus adıyla bilinen Simun, onun kardeşi Andreas, Zebedinin oğulları Yakup ve Yuhanna, Filipus ve Bartalmay, Tomas ve vergi görevlisi Matta, Alfay oğlu Yakup ve Taday, Yurtsever Simun ve İsaya ihanet eden Yahuda İskariot.'),
(2006660,68,40,10,5,'İsa Onikileri şu buyrukla halkın arasına gönderdi: ‹‹Öteki ulusların arasına girmeyin. Samiriyelilerin kentlerine de uğramayın.'),
(2006661,68,40,10,6,'Bunun yerine, İsrail halkının yitik koyunlarına gidin.'),
(2006662,68,40,10,7,'Gittiğiniz her yerde Göklerin Egemenliğinin yaklaştığını duyurun.'),
(2006663,68,40,10,8,'Hastaları iyileştirin, ölüleri diriltin, cüzamlıları temiz kılın, cinleri kovun. Karşılıksız aldınız, karşılıksız verin.'),
(2006664,68,40,10,9,'Kuşağınıza altın, gümüş, ya da bakır para koymayın.'),
(2006665,68,40,10,10,'Yolculuk için ne torba, ne yedek mintan, ne çarık, ne de değnek alın. Çünkü işçi yiyeceğini hak eder.'),
(2006666,68,40,10,11,'Hangi kent ya da köye girerseniz, orada saygıdeğer birini arayın ve ayrılıncaya dek onunla kalın.'),
(2006667,68,40,10,12,'Onun evine girerken, evdekilere esenlik dileyin.'),
(2006668,68,40,10,13,'Eğer evdekiler buna layıksa, dilediğiniz esenlik üzerlerinde kalsın; layık değillerse, size geri dönsün.'),
(2006669,68,40,10,14,'Sizi kabul etmez, sözlerinizi dinlemezlerse o evden ya da kentten ayrılırken, ayaklarınızın tozunu silkin.'),
(2006670,68,40,10,15,'Size doğrusunu söyleyeyim, yargı günü o kentin hali Sodomla Gomora bölgesinin halinden beter olacaktır.››'),
(2006671,68,40,10,16,'‹‹İşte, sizi koyunlar gibi kurtların arasına gönderiyorum. Yılan gibi zeki, güvercin gibi saf olun.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006672,68,40,10,17,'İnsanlardan sakının. Çünkü sizi mahkemelere verecek, havralarında kamçılayacaklar.'),
(2006673,68,40,10,18,'Benden ötürü valilerin, kralların önüne çıkarılacak, böylece onlara ve uluslara tanıklık edeceksiniz.'),
(2006674,68,40,10,19,'Sizleri mahkemeye verdiklerinde, neyi nasıl söyleyeceğinizi düşünerek kaygılanmayın. Ne söyleyeceğiniz o anda size bildirilecek.'),
(2006675,68,40,10,20,'Çünkü konuşan siz değil, aracılığınızla konuşan Babanızın Ruhu olacak.'),
(2006676,68,40,10,21,'‹‹Kardeş kardeşi, baba çocuğunu ölüme teslim edecek. Çocuklar anne babaya başkaldırıp onları öldürtecek.'),
(2006677,68,40,10,22,'Benim adımdan ötürü herkes sizden nefret edecek. Ama sonuna kadar dayanan kurtulacaktır.'),
(2006678,68,40,10,23,'Bir kentte size zulmettikleri zaman ötekine kaçın. Size doğrusunu söyleyeyim, İnsanoğlu gelinceye dek İsrailin bütün kentlerini dolaşmış olmayacaksınız.'),
(2006679,68,40,10,24,'‹‹Öğrenci öğretmeninden, köle efendisinden üstün değildir.'),
(2006680,68,40,10,25,'Öğrencinin öğretmeni gibi, kölenin de efendisi gibi olması yeterlidir. İnsanlar evin efendisine Baalzevul derlerse, ev halkına neler demezler!››'),
(2006681,68,40,10,26,'‹‹Bu yüzden onlardan korkmayın. Çünkü örtülü olup da açığa çıkarılmayacak, gizli olup da bilinmeyecek hiçbir şey yoktur.'),
(2006682,68,40,10,27,'Size karanlıkta söylediklerimi, siz gün ışığında söyleyin. Kulağınıza fısıldananı, damlardan duyurun.'),
(2006683,68,40,10,28,'Bedeni öldüren, ama canı öldüremeyenlerden korkmayın. Canı da bedeni de cehennemde mahvedebilen Tanrıdan korkun.'),
(2006684,68,40,10,29,'İki serçe bir meteliğe satılmıyor mu? Ama Babanızın izni olmadan bunlardan bir teki bile yere düşmez.'),
(2006685,68,40,10,30,'Size gelince, başınızdaki bütün saçlar bile sayılıdır.'),
(2006686,68,40,10,31,'Onun için korkmayın, siz birçok serçeden daha değerlisiniz.'),
(2006687,68,40,10,32,'‹‹İnsanların önünde beni açıkça kabul eden herkesi, ben de göklerdeki Babamın önünde açıkça kabul edeceğim.'),
(2006688,68,40,10,33,'İnsanların önünde beni inkâr edeni, ben de göklerdeki Babamın önünde inkâr edeceğim.››'),
(2006689,68,40,10,34,'‹‹Yeryüzüne barış getirmeye geldiğimi sanmayın! Barış değil, kılıç getirmeye geldim.'),
(2006690,68,40,10,35,'Çünkü ben babayla oğulun, anneyle kızın, gelinle kaynananın arasına ayrılık sokmaya geldim.'),
(2006691,68,40,10,36,'‹İnsanın düşmanı kendi ev halkı olacak.›'),
(2006692,68,40,10,37,'Annesini ya da babasını beni sevdiğinden çok seven bana layık değildir. Oğlunu ya da kızını beni sevdiğinden çok seven bana layık değildir.'),
(2006693,68,40,10,38,'Çarmıhını yüklenip ardımdan gelmeyen bana layık değildir.'),
(2006694,68,40,10,39,'Canını kurtaran onu yitirecek. Canını benim uğruma yitiren ise onu kurtaracaktır.'),
(2006695,68,40,10,40,'‹‹Sizi kabul eden beni kabul etmiş olur. Beni kabul eden de beni göndereni kabul etmiş olur.'),
(2006696,68,40,10,41,'Bir peygamberi peygamber olduğu için kabul eden, peygambere yaraşan bir ödül alacaktır. Doğru birini doğru olduğu için kabul eden, doğru kişiye yaraşan bir ödül alacaktır.'),
(2006697,68,40,10,42,'Bu sıradan kişilerden birine, öğrencim olduğu için bir bardak soğuk su bile veren, size doğrusunu söyleyeyim, ödülsüz kalmayacaktır.››'),
(2006698,68,40,11,1,'İsa, on iki öğrencisine bu buyrukları verdikten sonra onların kentlerinde öğretmek ve Tanrı sözünü duyurmak üzere oradan ayrıldı.'),
(2006699,68,40,11,2,'Tutukevinde bulunan Yahya, Mesihin yaptığı işleri duyunca, Ona gönderdiği öğrencileri aracılığıyla şunu sordu: ‹‹Gelecek Olan sen misin, yoksa başkasını mı bekleyelim?››'),
(2006700,68,40,11,4,'İsa onlara şöyle karşılık verdi: ‹‹Gidin, işitip gördüklerinizi Yahyaya bildirin.'),
(2006701,68,40,11,5,'Körlerin gözleri açılıyor, kötürümler yürüyor, cüzamlılar temiz kılınıyor, sağırlar işitiyor, ölüler diriliyor ve Müjde yoksullara duyuruluyor.'),
(2006702,68,40,11,6,'Benden ötürü sendeleyip düşmeyene ne mutlu!››'),
(2006703,68,40,11,7,'Yahyanın öğrencileri ayrılırken İsa halka Yahyadan söz etmeye başladı. ‹‹Çöle ne görmeye gittiniz?›› dedi. ‹‹Rüzgarda sallanan bir kamış mı?'),
(2006704,68,40,11,8,'Söyleyin, ne görmeye gittiniz? Pahalı giysiler giymiş bir adam mı? Oysa pahalı giysi giyenler, kral saraylarında bulunur.'),
(2006705,68,40,11,9,'Öyleyse ne görmeye gittiniz? Bir peygamber mi? Evet! Size şunu söyleyeyim, gördüğünüz kişi peygamberden de üstündür.'),
(2006706,68,40,11,10,'‹İşte, habercimi senin önünden gönderiyorum; O önden gidip senin yolunu hazırlayacak›'),
(2006707,68,40,11,11,'Size doğrusunu söyleyeyim, kadından doğanlar arasında Vaftizci Yahyadan daha üstün biri çıkmamıştır. Bununla birlikte, Göklerin Egemenliğinde en küçük olan ondan üstündür.'),
(2006708,68,40,11,12,'Vaftizci Yahyanın ortaya çıktığı günden bu yana Göklerin Egemenliği zorlanıyor, zorlu kişiler onu ele geçirmeye çalışıyor.'),
(2006709,68,40,11,13,'Yahyaya dek bütün peygamberlerle Kutsal Yasa, olacakları önceden bildirdiler.'),
(2006710,68,40,11,14,'Eğer bunu kabul etmek isterseniz, gelecek olan İlyas odur.'),
(2006711,68,40,11,15,'Kulağı olan, işitsin!'),
(2006712,68,40,11,16,'‹‹Bu kuşağın insanlarını neye benzeteyim? Çarşı meydanlarında oturup arkadaşlarına, ‹Size kaval çaldık, oynamadınız; Ağıt yaktık, dövünmediniz›'),
(2006713,68,40,11,18,'Yahya geldiği zaman oruç tutup içkiden kaçındı, ona ‹cinli› diyorlar.'),
(2006714,68,40,11,19,'İnsanoğlu geldiği zaman yiyip içti. Bu kez de diyorlar ki, ‹Şu obur ve ayyaş adama bakın! Vergi görevlileri ve günahkârlarla dost oldu!› Ne var ki bilgelik, ortaya koyduğu işlerle doğrulanır.››'),
(2006715,68,40,11,20,'Sonra İsa, mucizelerinin çoğunu yapmış olduğu kentleri, tövbe etmedikleri için şöyle azarlamaya başladı: ‹‹Vay haline, ey Horazin! Vay haline, ey Beytsayda! Sizlerde yapılan mucizeler Sur ve Saydada yapılmış olsaydı, çoktan çul kuşanıp kül içinde oturarak tövbe etmiş olurlardı.'),
(2006716,68,40,11,22,'Size şunu söyleyeyim, yargı günü sizin haliniz Sur ve Saydanın halinden beter olacaktır!'),
(2006717,68,40,11,23,'Ya sen, ey Kefarnahum, göğe mi çıkarılacaksın? Hayır, ölüler diyarına indirileceksin! Çünkü sende yapılan mucizeler Sodomda yapılmış olsaydı, bugüne dek ayakta kalırdı.'),
(2006718,68,40,11,24,'Sana şunu söyleyeyim, yargı günü senin halin Sodom bölgesinin halinden beter olacaktır!››'),
(2006719,68,40,11,25,'İsa bundan sonra şöyle dedi: ‹‹Baba, yerin ve göğün Rabbi! Bu gerçekleri bilge ve akıllı kişilerden gizleyip küçük çocuklara açtığın için sana şükrederim.'),
(2006720,68,40,11,26,'Evet Baba, senin isteğin buydu.'),
(2006721,68,40,11,27,'‹‹Babam her şeyi bana teslim etti. Oğulu, Babadan başka kimse tanımaz. Babayı da Oğuldan ve Oğulun Onu tanıtmak istediği kişilerden başkası tanımaz.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006722,68,40,11,28,'‹‹Ey bütün yorgunlar ve yükü ağır olanlar! Bana gelin, ben size rahat veririm.'),
(2006723,68,40,11,29,'Boyunduruğumu yüklenin, benden öğrenin. Çünkü ben yumuşak huylu, alçakgönüllüyüm. Böylece canlarınız rahata kavuşur.'),
(2006724,68,40,11,30,'Boyunduruğumu taşımak kolay, yüküm hafiftir.››'),
(2006725,68,40,12,1,'O sıralarda, bir Şabat Günü İsa ekinler arasından geçiyordu. Öğrencileri acıkınca başakları koparıp yemeye başladılar.'),
(2006726,68,40,12,2,'Bunu gören Ferisiler İsaya, ‹‹Bak, öğrencilerin Şabat Günü yasak olanı yapıyor›› dediler.'),
(2006727,68,40,12,3,'İsa onlara, ‹‹Davutla yanındakiler acıkınca Davutun ne yaptığını okumadınız mı?›› diye sordu.'),
(2006728,68,40,12,4,'‹‹Tanrının evine girdi, kendisinin ve yanındakilerin yemesi yasak olan, ancak kâhinlerin yiyebileceği adak ekmeklerini yedi.'),
(2006729,68,40,12,5,'Ayrıca kâhinlerin her hafta tapınakta Şabat Günüyle ilgili buyruğu çiğnedikleri halde suçlu sayılmadıklarını Kutsal Yasada okumadınız mı?'),
(2006730,68,40,12,6,'Size şunu söyleyeyim, burada tapınaktan daha üstün bir şey var.'),
(2006731,68,40,12,7,'Eğer siz, ‹Ben kurban değil, merhamet isterim› sözünün anlamını bilseydiniz, suçsuzları yargılamazdınız.'),
(2006732,68,40,12,8,'Çünkü İnsanoğlu Şabat Gününün de Rabbidir.››'),
(2006733,68,40,12,9,'İsa oradan ayrılıp onların havrasına gitti.'),
(2006734,68,40,12,10,'Orada eli sakat bir adam vardı. İsayı suçlamak amacıyla kendisine, ‹‹Şabat Günü bir hastayı iyileştirmek Kutsal Yasaya uygun mudur?›› diye sordular.'),
(2006735,68,40,12,11,'İsa onlara şu karşılığı verdi: ‹‹Hanginizin bir koyunu olur da Şabat Günü çukura düşerse onu tutup çıkarmaz?'),
(2006736,68,40,12,12,'İnsan koyundan çok daha değerlidir! Demek ki, Şabat Günü iyilik yapmak Yasaya uygundur.››'),
(2006737,68,40,12,13,'Sonra adama, ‹‹Elini uzat›› dedi. Adam elini uzattı. Eli öteki gibi yine sapasağlam oluverdi.'),
(2006738,68,40,12,14,'Bunun üzerine Ferisiler dışarı çıktılar, İsayı yok etmek için anlaştılar.'),
(2006739,68,40,12,15,'İsa bunu bildiği için oradan ayrıldı. Birçok kişi ardından gitti. İsa hepsini iyileştirdi.'),
(2006740,68,40,12,16,'Kim olduğunu açıklamamaları için onları uyardı.'),
(2006741,68,40,12,17,'Bu, Peygamber Yeşaya aracılığıyla bildirilen şu söz yerine gelsin diye oldu: ‹‹İşte Kulum, Onu ben seçtim. Gönlümün hoşnut olduğu sevgili Kulum Odur. Ruhumu Onun üzerine koyacağım, O da adaleti uluslara bildirecek.'),
(2006742,68,40,12,19,'Çekişip bağırmayacak, Sokaklarda kimse Onun sesini duymayacak.'),
(2006743,68,40,12,20,'Ezilmiş kamışı kırmayacak, Tüten fitili söndürmeyecek, Ve sonunda adaleti zafere ulaştıracak.'),
(2006744,68,40,12,21,'Uluslar da Onun adına umut bağlayacak.››'),
(2006745,68,40,12,22,'Daha sonra İsaya kör ve dilsiz bir cinli getirdiler. İsa adamı iyileştirdi. Adam konuşmaya, görmeye başladı.'),
(2006746,68,40,12,23,'Bütün kalabalık şaşırıp kaldı. ‹‹Bu, Davutun Oğlu olabilir mi?›› diye soruyorlardı.'),
(2006747,68,40,12,24,'Ferisiler bunu duyunca, ‹‹Bu adam cinleri, ancak cinlerin önderi Baalzevulun gücüyle kovuyor›› dediler.'),
(2006748,68,40,12,25,'Onların ne düşündüğünü bilen İsa şöyle dedi: ‹‹Kendi içinde bölünen ülke yıkılır. Kendi içinde bölünen kent ya da ev ayakta kalamaz.'),
(2006749,68,40,12,26,'Eğer Şeytan Şeytanı kovarsa, kendi içinde bölünmüş demektir. Bu durumda onun egemenliği nasıl ayakta kalabilir?'),
(2006750,68,40,12,27,'Eğer ben cinleri Baalzevulun gücüyle kovuyorsam, sizin adamlarınız kimin gücüyle kovuyor? Bu durumda sizi kendi adamlarınız yargılayacak.'),
(2006751,68,40,12,28,'Ama ben cinleri Tanrının Ruhuyla kovuyorsam, Tanrının Egemenliği üzerinize gelmiş demektir.'),
(2006752,68,40,12,29,'‹‹Bir kimse güçlü adamın evine girip malını nasıl çalabilir? Ancak onu bağladıktan sonra evini soyabilir.'),
(2006753,68,40,12,30,'‹‹Benden yana olmayan bana karşıdır. Benimle birlikte toplamayan dağıtıyor demektir.'),
(2006754,68,40,12,31,'Bunun için size diyorum ki, insanların işlediği her günah, ettiği her küfür bağışlanacak; ama Ruha edilen küfür bağışlanmayacaktır.'),
(2006755,68,40,12,32,'İnsanoğluna karşı bir söz söyleyen, bağışlanacak; ama Kutsal Ruha karşı bir söz söyleyen, ne bu çağda, ne de gelecek çağda bağışlanacaktır.'),
(2006756,68,40,12,33,'‹‹Ya ağacı iyi, meyvesini de iyi sayın; ya da ağacı kötü, meyvesini de kötü sayın. Çünkü her ağaç meyvesinden tanınır.'),
(2006757,68,40,12,34,'Sizi engerekler soyu! Kötü olan sizler nasıl iyi sözler söyleyebilirsiniz? Çünkü ağız yürekten taşanı söyler.'),
(2006758,68,40,12,35,'İyi insan içindeki iyilik hazinesinden iyilik, kötü insan içindeki kötülük hazinesinden kötülük çıkarır.'),
(2006759,68,40,12,36,'Size şunu söyleyeyim, insanlar söyledikleri her boş söz için yargı günü hesap verecekler.'),
(2006760,68,40,12,37,'Kendi sözlerinizle aklanacak, yine kendi sözlerinizle suçlu çıkarılacaksınız.››'),
(2006761,68,40,12,38,'Bunun üzerine bazı din bilginleri ve Ferisiler, ‹‹Öğretmenimiz, senden doğaüstü bir belirti görmek istiyoruz›› dediler.'),
(2006762,68,40,12,39,'İsa onlara şu karşılığı verdi: ‹‹Kötü ve vefasız kuşak bir belirti istiyor! Ama ona Peygamber Yunusun belirtisinden başka bir belirti gösterilmeyecektir.'),
(2006763,68,40,12,40,'Yunus, nasıl üç gün üç gece o koca balığın karnında kaldıysa, İnsanoğlu da üç gün üç gece yerin bağrında kalacaktır.'),
(2006764,68,40,12,41,'Ninova halkı, yargı günü bu kuşakla birlikte kalkıp bu kuşağı yargılayacak. Çünkü Ninovalılar, Yunusun çağrısı üzerine tövbe ettiler. Bakın, Yunustan daha üstün olan buradadır.'),
(2006765,68,40,12,42,'Güney Kraliçesi, yargı günü bu kuşakla birlikte kalkıp bu kuşağı yargılayacak. Çünkü kraliçe, Süleymanın bilgece sözlerini dinlemek için dünyanın ta öbür ucundan gelmişti. Bakın, Süleymandan daha üstün olan buradadır.'),
(2006766,68,40,12,43,'‹‹Kötü ruh insandan çıkınca kurak yerlerde dolanıp huzur arar, ama bulamaz.'),
(2006767,68,40,12,44,'O zaman, ‹Çıktığım eve, kendi evime döneyim› der. Eve gelince orayı bomboş, süpürülmüş, düzeltilmiş bulur.'),
(2006768,68,40,12,45,'Bunun üzerine gider, yanına kendisinden kötü yedi ruh daha alır ve eve girip yerleşirler. Böylece o kişinin son durumu ilkinden beter olur. Bu kötü kuşağın başına gelecek olan da budur.››'),
(2006769,68,40,12,46,'İsa daha halka konuşurken, annesiyle kardeşleri geldi. Dışarıda durmuş, Onunla konuşmak istiyorlardı.'),
(2006770,68,40,12,47,'Birisi İsaya, ‹‹Bak, annenle kardeşlerin dışarıda duruyor, seninle görüşmek istiyorlar›› dedi.'),
(2006771,68,40,12,48,'İsa, kendisiyle konuşana, ‹‹Kimdir annem, kimdir kardeşlerim?›› karşılığını verdi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006772,68,40,12,49,'Eliyle öğrencilerini göstererek, ‹‹İşte annem, işte kardeşlerim!›› dedi.'),
(2006773,68,40,12,50,'‹‹Göklerdeki Babam''ın isteğini kim yerine getirirse, kardeşim, kızkardeşim ve annem odur.››'),
(2006774,68,40,13,1,'Aynı gün İsa evden çıktı, gidip göl kıyısında oturdu.'),
(2006775,68,40,13,2,'Çevresinde büyük bir kalabalık toplandı. Bu yüzden İsa tekneye binip oturdu. Bütün kalabalık kıyıda duruyordu.'),
(2006776,68,40,13,3,'İsa onlara benzetmelerle birçok şey anlattı. ‹‹Bakın›› dedi, ‹‹Ekincinin biri tohum ekmeye çıktı.'),
(2006777,68,40,13,4,'Ektiği tohumlardan kimi yol kenarına düştü. Kuşlar gelip bunları yedi.'),
(2006778,68,40,13,5,'Kimi, toprağı az, kayalık yerlere düştü; toprak derin olmadığından hemen filizlendi.'),
(2006779,68,40,13,6,'Ne var ki, güneş doğunca kavruldular, kök salamadıkları için kuruyup gittiler.'),
(2006780,68,40,13,7,'Kimi, dikenler arasına düştü. Dikenler büyüdü, filizleri boğdu.'),
(2006781,68,40,13,8,'Kimi ise iyi toprağa düştü. Bazısı yüz, bazısı altmış, bazısı da otuz kat ürün verdi.'),
(2006782,68,40,13,9,'Kulağı olan işitsin!››'),
(2006783,68,40,13,10,'Öğrencileri gelip İsaya, ‹‹Halka neden benzetmelerle konuşuyorsun?›› diye sordular.'),
(2006784,68,40,13,11,'İsa şöyle yanıtladı: ‹‹Göklerin Egemenliğinin sırlarını bilme ayrıcalığı size verildi, ama onlara verilmedi.'),
(2006785,68,40,13,12,'Çünkü kimde varsa, ona daha çok verilecek, bolluğa kavuşturulacak. Ama kimde yoksa, elindeki de alınacak.'),
(2006786,68,40,13,13,'Onlara benzetmelerle konuşmamın nedeni budur. Çünkü, ‹Gördükleri halde görmezler, Duydukları halde duymaz ve anlamazlar.›'),
(2006787,68,40,13,14,'‹‹Böylece Yeşayanın peygamberlik sözü onlar için gerçekleşmiş oldu: ‹Duyacak duyacak, ama hiç anlamayacaksınız, Bakacak bakacak, ama hiç görmeyeceksiniz!'),
(2006788,68,40,13,15,'Çünkü bu halkın yüreği duygusuzlaştı, Kulakları ağırlaştı. Gözlerini kapadılar. Öyle ki, gözleri görmesin, Kulakları duymasın, yürekleri anlamasın Ve bana dönmesinler. Dönselerdi, onları iyileştirirdim.›'),
(2006789,68,40,13,16,'‹‹Ama ne mutlu size ki, gözleriniz görüyor, kulaklarınız işitiyor!'),
(2006790,68,40,13,17,'Size doğrusunu söyleyeyim, nice peygamberler, nice doğru kişiler sizin gördüklerinizi görmek istediler, ama göremediler. Sizin işittiklerinizi işitmek istediler, ama işitemediler.'),
(2006791,68,40,13,18,'‹‹Şimdi ekinciyle ilgili benzetmeyi siz dinleyin.'),
(2006792,68,40,13,19,'Kim göksel egemenlikle ilgili sözü işitir de anlamazsa, kötü olan gelir, onun yüreğine ekileni söker götürür. Yol kenarına ekilen tohum işte budur.'),
(2006793,68,40,13,20,'Kayalık yerlere ekilen ise işittiği sözü hemen sevinçle kabul eden, ama kök salamadığı için ancak bir süre dayanan kişidir. Böyle biri Tanrı sözünden ötürü sıkıntı ya da zulme uğrayınca hemen sendeleyip düşer.'),
(2006794,68,40,13,22,'Dikenler arasında ekilen de şudur: Sözü işitir, ama dünyasal kaygılar ve zenginliğin aldatıcılığı sözü boğar ve ürün vermesini engeller.'),
(2006795,68,40,13,23,'İyi toprağa ekilen tohum ise, sözü işitip anlayan birine benzer. Böylesi elbette ürün verir, kimi yüz, kimi altmış, kimi de otuz kat.››'),
(2006796,68,40,13,24,'İsa onlara başka bir benzetme anlattı: ‹‹Göklerin Egemenliği, tarlasına iyi tohum eken adama benzer›› dedi.'),
(2006797,68,40,13,25,'‹‹Herkes uyurken, adamın düşmanı geldi, buğdayın arasına delice ekip gitti.'),
(2006798,68,40,13,26,'Ekin gelişip başak salınca, deliceler de göründü.'),
(2006799,68,40,13,27,'‹‹Mal sahibinin köleleri gelip ona şöyle dediler: ‹Efendimiz, sen tarlana iyi tohum ekmedin mi? Bu deliceler nereden çıktı?›'),
(2006800,68,40,13,28,'‹‹Mal sahibi, ‹Bunu bir düşman yapmıştır› dedi. ‹‹ ‹Gidip deliceleri toplamamızı ister misin?› diye sordu köleler.'),
(2006801,68,40,13,29,'‹‹ ‹Hayır› dedi adam. ‹Deliceleri toplarken belki buğdayı da sökersiniz.'),
(2006802,68,40,13,30,'Bırakın biçim vaktine dek birlikte büyüsünler. Biçim vakti orakçılara, önce deliceleri toplayın diyeceğim, yakmak için demet yapın. Buğdayı ise toplayıp ambarıma koyun.› ››'),
(2006803,68,40,13,31,'İsa onlara bir benzetme daha anlattı: ‹‹Göklerin Egemenliği, bir adamın tarlasına ektiği hardal tanesine benzer›› dedi.'),
(2006804,68,40,13,32,'‹‹Hardal tohumların en küçüğü olduğu halde, gelişince bahçe bitkilerinin boyunu aşar, ağaç olur. Böylece kuşlar gelip dallarında barınır.››'),
(2006805,68,40,13,33,'İsa onlara başka bir benzetme anlattı: ‹‹Göklerin Egemenliği, bir kadının üç ölçek una karıştırdığı mayaya benzer. Sonunda bütün hamur kabarır.››'),
(2006806,68,40,13,34,'İsa bütün bunları halka benzetmelerle anlattı. Benzetme kullanmadan onlara hiçbir şey anlatmazdı.'),
(2006807,68,40,13,35,'Bu, peygamber aracılığıyla bildirilen şu söz yerine gelsin diye oldu: ‹‹Ağzımı benzetmeler anlatarak açacağım, Dünyanın kuruluşundan beri Gizli kalmış sırları dile getireceğim.››'),
(2006808,68,40,13,36,'Bundan sonra İsa halktan ayrılıp eve gitti. Öğrencileri yanına gelip, ‹‹Tarladaki delicelerle ilgili benzetmeyi bize açıkla›› dediler.'),
(2006809,68,40,13,37,'İsa, ‹‹İyi tohumu eken, İnsanoğludur›› diye karşılık verdi.'),
(2006810,68,40,13,38,'‹‹Tarla ise dünyadır. İyi tohum, göksel egemenliğin oğulları, deliceler de kötü olanın oğullarıdır.'),
(2006811,68,40,13,39,'Deliceleri eken düşman, İblistir. Biçim vakti, çağın sonu; orakçılar ise meleklerdir.'),
(2006812,68,40,13,40,'‹‹Deliceler nasıl toplanıp yakılırsa, çağın sonunda da böyle olacaktır.'),
(2006813,68,40,13,41,'İnsanoğlu meleklerini gönderecek, onlar da insanları günaha düşüren her şeyi, kötülük yapan herkesi Onun egemenliğinden toplayıp kızgın fırına atacaklar. Orada ağlayış ve diş gıcırtısı olacaktır.'),
(2006814,68,40,13,43,'Doğru kişiler o zaman Babalarının egemenliğinde güneş gibi parlayacaklar. Kulağı olan işitsin!››'),
(2006815,68,40,13,44,'‹‹Göklerin Egemenliği, tarlada saklı bir defineye benzer. Onu bulan yeniden sakladı, sevinçle koşup gitti, varını yoğunu satıp tarlayı satın aldı.'),
(2006816,68,40,13,45,'‹‹Yine Göklerin Egemenliği, güzel inciler arayan bir tüccara benzer.'),
(2006817,68,40,13,46,'Tüccar, çok değerli bir inci bulunca gitti, varını yoğunu satıp o inciyi satın aldı.››'),
(2006818,68,40,13,47,'‹‹Yine Göklerin Egemenliği, denize atılan ve her çeşit balığı toplayan ağa benzer.'),
(2006819,68,40,13,48,'Ağ dolunca onu kıyıya çekerler. Oturup işe yarayan balıkları kaplara koyar, yaramayanları atarlar.'),
(2006820,68,40,13,49,'Çağın sonunda da böyle olacak. Melekler gelecek, kötü kişileri doğruların arasından ayırıp kızgın fırına atacaklar. Orada ağlayış ve diş gıcırtısı olacaktır.››'),
(2006821,68,40,13,51,'İsa, ‹‹Bütün bunları anladınız mı?›› diye sordu. ‹‹Evet›› karşılığını verdiler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006822,68,40,13,52,'O da onlara, ‹‹İşte böylece Göklerin Egemenliği için eğitilmiş her din bilgini, hazinesinden hem yeni hem eski değerler çıkaran bir mal sahibine benzer›› dedi.'),
(2006823,68,40,13,53,'İsa bütün bu benzetmeleri anlattıktan sonra oradan ayrıldı.'),
(2006824,68,40,13,54,'Kendi memleketine gitti ve oradaki havrada halka öğretmeye başladı. Halk şaşıp kalmıştı. ‹‹Adamın bu bilgeliği ve mucizeler yaratan gücü nereden geliyor?›› diyorlardı.'),
(2006825,68,40,13,55,'‹‹Marangozun oğlu değil mi bu? Annesinin adı Meryem değil mi? Yakup, Yusuf, Simun ve Yahuda Onun kardeşleri değil mi?'),
(2006826,68,40,13,56,'Kızkardeşlerinin hepsi aramızda yaşamıyor mu? O halde Onun bütün bu yaptıkları nereden geliyor?››'),
(2006827,68,40,13,57,'Ve gücenip Onu reddettiler. Ama İsa onlara şöyle dedi: ‹‹Bir peygamber, kendi memleketinden ve evinden başka yerde hor görülmez.››'),
(2006828,68,40,13,58,'İmansızlıkları yüzünden İsa orada pek fazla mucize yapmadı.'),
(2006829,68,40,14,1,'O günlerde İsayla ilgili haberleri duyan bölge kralı Hirodes, adamlarına, ‹‹Bu, Vaftizci Yahyadır›› dedi. ‹‹Ölümden dirildi. Olağanüstü güçlerin onda etkin olmasının nedeni budur.››'),
(2006830,68,40,14,3,'Hirodes, kardeşi Filipusun karısı Hirodiya yüzünden Yahyayı tutuklatmış, bağlatıp zindana attırmıştı.'),
(2006831,68,40,14,4,'Çünkü Yahya Hirodese, ‹‹O kadınla evlenmen Kutsal Yasaya aykırıdır›› demişti.'),
(2006832,68,40,14,5,'Hirodes Yahyayı öldürtmek istemiş, ama halktan korkmuştu. Çünkü halk Yahyayı peygamber sayıyordu.'),
(2006833,68,40,14,6,'Hirodesin doğum günü şenliği sırasında Hirodiyanın kızı ortaya çıkıp dans etti. Bu, Hirodesin öyle hoşuna gitti ki, ant içerek kıza ne dilerse vereceğini söyledi.'),
(2006834,68,40,14,8,'Kız, annesinin kışkırtmasıyla, ‹‹Bana şimdi, bir tepsi üzerinde Vaftizci Yahyanın başını ver›› dedi.'),
(2006835,68,40,14,9,'Kral buna çok üzüldüyse de, konuklarının önünde içtiği anttan ötürü bu dileğin yerine getirilmesini buyurdu.'),
(2006836,68,40,14,10,'Adam gönderip zindanda Yahyanın başını kestirdi.'),
(2006837,68,40,14,11,'Kesik baş tepsiyle getirilip kıza verildi, kız da bunu annesine götürdü.'),
(2006838,68,40,14,12,'Yahyanın öğrencileri gelip cesedi aldılar ve gömdüler. Sonra gidip İsaya haber verdiler.'),
(2006839,68,40,14,13,'İsa bunu duyunca, tek başına tenha bir yere çekilmek üzere bir tekneyle oradan ayrıldı. Bunu öğrenen halk, kentlerden çıkıp Onu yaya olarak izledi.'),
(2006840,68,40,14,14,'İsa tekneden inince büyük bir kalabalıkla karşılaştı. Onlara acıdı ve hasta olanlarını iyileştirdi.'),
(2006841,68,40,14,15,'Akşama doğru öğrencileri yanına gelip, ‹‹Burası ıssız bir yer›› dediler, ‹‹Vakit de geç oldu. Halkı salıver de köylere gidip kendilerine yiyecek alsınlar.››'),
(2006842,68,40,14,16,'İsa, ‹‹Gitmelerine gerek yok, onlara siz yiyecek verin›› dedi.'),
(2006843,68,40,14,17,'Öğrenciler, ‹‹Burada beş ekmekle iki balıktan başka bir şeyimiz yok ki›› dediler.'),
(2006844,68,40,14,18,'İsa, ‹‹Onları buraya, bana getirin›› dedi.'),
(2006845,68,40,14,19,'Halka çayıra oturmalarını buyurduktan sonra, beş ekmekle iki balığı aldı, gözlerini göğe kaldırarak şükretti; sonra ekmekleri bölüp öğrencilerine verdi, onlar da halka dağıttılar.'),
(2006846,68,40,14,20,'Herkes yiyip doydu. Artakalan parçalardan on iki sepet dolusu topladılar.'),
(2006847,68,40,14,21,'Yemek yiyenlerin sayısı, kadın ve çocuklar hariç, yaklaşık beş bin erkekti.'),
(2006848,68,40,14,22,'Bundan hemen sonra İsa öğrencilerine, tekneye binip kendisinden önce karşı yakaya geçmelerini buyurdu. Bu arada halkı evlerine gönderecekti.'),
(2006849,68,40,14,23,'Halkı gönderdikten sonra dua etmek için tek başına dağa çıktı. Akşam olurken orada yalnızdı.'),
(2006850,68,40,14,24,'O sırada tekne kıyıdan bir hayli uzakta dalgalarla boğuşuyordu. Çünkü rüzgar karşı yönden esiyordu.'),
(2006851,68,40,14,25,'Sabaha karşı İsa, gölün üstünde yürüyerek onlara yaklaştı.'),
(2006852,68,40,14,26,'Öğrenciler, Onun gölün üstünde yürüdüğünü görünce dehşete kapıldılar. ‹‹Bu bir hayalet!›› diyerek korkuyla bağrıştılar.'),
(2006853,68,40,14,27,'Ama İsa hemen onlara seslenerek, ‹‹Cesur olun, benim, korkmayın!›› dedi.'),
(2006854,68,40,14,28,'Petrus buna karşılık, ‹‹Ya Rab›› dedi, ‹‹Eğer sen isen, buyruk ver suyun üstünden yürüyerek sana geleyim.››'),
(2006855,68,40,14,29,'İsa, ‹‹Gel!›› dedi. Petrus da tekneden indi, suyun üstünden yürüyerek İsaya yaklaştı.'),
(2006856,68,40,14,30,'Ama rüzgarın ne kadar güçlü estiğini görünce korktu, batmaya başladı. ‹‹Ya Rab, beni kurtar!›› diye bağırdı.'),
(2006857,68,40,14,31,'İsa hemen elini uzatıp onu tuttu. Ona, ‹‹Ey kıt imanlı, neden kuşku duydun?›› dedi.'),
(2006858,68,40,14,32,'Onlar tekneye bindikten sonra rüzgar dindi.'),
(2006859,68,40,14,33,'Teknedekiler, ‹‹Sen gerçekten Tanrının Oğlusun›› diyerek Ona tapındılar.'),
(2006860,68,40,14,34,'Gölü aşıp Ginnesarda karaya çıktılar.'),
(2006861,68,40,14,35,'Yöre halkı İsayı tanıyınca çevreye haber saldı. Bütün hastaları Ona getirdiler.'),
(2006862,68,40,14,36,'Giysisinin eteğine bir dokunsak diye yalvarıyorlardı. Dokunanların hepsi iyileşti.'),
(2006863,68,40,15,1,'Bu sırada Yeruşalimden bazı Ferisiler ve din bilginleri İsaya gelip, ‹‹Öğrencilerin neden atalarımızın töresini çiğniyor?›› diye sordular, ‹‹Yemekten önce ellerini yıkamıyorlar.››'),
(2006864,68,40,15,3,'İsa onlara şu karşılığı verdi: ‹‹Ya siz, neden töreniz uğruna Tanrı buyruğunu çiğniyorsunuz?'),
(2006865,68,40,15,4,'Çünkü Tanrı şöyle buyurdu: ‹Annene babana saygı göstereceksin›; ‹Annesine ya da babasına söven kesinlikle öldürülecektir.›'),
(2006866,68,40,15,5,'Ama siz, ‹Her kim anne ya da babasına, benden alacağın bütün yardım Tanrıya adanmıştır derse, artık babasına saygı göstermek zorunda değildir› diyorsunuz. Böylelikle, töreniz uğruna Tanrının sözünü geçersiz kılmış oluyorsunuz.'),
(2006867,68,40,15,7,'Ey ikiyüzlüler! Yeşayanın sizinle ilgili şu peygamberlik sözü ne kadar yerindedir: ‹Bu halk dudaklarıyla beni sayar, Ama yürekleri benden uzak.'),
(2006868,68,40,15,9,'Bana boşuna taparlar. Çünkü öğrettikleri, sadece insan buyruklarıdır.› ››'),
(2006869,68,40,15,10,'İsa, halkı yanına çağırıp onlara, ‹‹Dinleyin ve şunu belleyin›› dedi.'),
(2006870,68,40,15,11,'‹‹Ağızdan giren şey insanı kirletmez. İnsanı kirleten ağızdan çıkandır.››'),
(2006871,68,40,15,12,'Bu sırada öğrencileri Ona gelip, ‹‹Biliyor musun?›› dediler, ‹‹Ferisiler bu sözü duyunca gücendiler.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006872,68,40,15,13,'İsa şu karşılığı verdi: ‹‹Göksel Babamın dikmediği her fidan kökünden sökülecektir.'),
(2006873,68,40,15,14,'Bırakın onları; onlar körlerin kör kılavuzlarıdır. Eğer kör köre kılavuzluk ederse, ikisi de çukura düşer.››'),
(2006874,68,40,15,15,'Petrus, ‹‹Bu benzetmeyi bize açıkla›› dedi.'),
(2006875,68,40,15,16,'‹‹Siz de mi hâlâ anlamıyorsunuz?›› diye sordu İsa.'),
(2006876,68,40,15,17,'‹‹Ağza giren her şeyin mideye indiğini, oradan da helaya atıldığını bilmiyor musunuz?'),
(2006877,68,40,15,18,'Ne var ki ağızdan çıkan, yürekten kaynaklanır. İnsanı kirleten de budur.'),
(2006878,68,40,15,19,'Çünkü kötü düşünceler, cinayet, zina, fuhuş, hırsızlık, yalan yere tanıklık ve iftira hep yürekten kaynaklanır.'),
(2006879,68,40,15,20,'İnsanı kirleten bunlardır. Yıkanmamış ellerle yemek yemek insanı kirletmez.››'),
(2006880,68,40,15,21,'İsa oradan ayrılıp Sur ve Sayda bölgesine geçti.'),
(2006881,68,40,15,22,'O yöreden Kenanlı bir kadın İsaya gelip, ‹‹Ya Rab, ey Davut Oğlu, halime acı! Kızım cine tutuldu, çok kötü durumda›› diye feryat etti.'),
(2006882,68,40,15,23,'İsa kadına hiçbir karşılık vermedi. Öğrencileri yaklaşıp, ‹‹Sal şunu, gitsin!›› diye rica ettiler. ‹‹Arkamızdan bağırıp duruyor.››'),
(2006883,68,40,15,24,'İsa, ‹‹Ben yalnız İsrail halkının kaybolmuş koyunlarına gönderildim›› diye yanıtladı.'),
(2006884,68,40,15,25,'Kadın ise yaklaşıp, ‹‹Ya Rab, bana yardım et!›› diyerek Onun önünde yere kapandı.'),
(2006885,68,40,15,26,'İsa ona, ‹‹Çocukların ekmeğini alıp köpeklere atmak doğru değildir›› dedi.'),
(2006886,68,40,15,27,'Kadın, ‹‹Haklısın, ya Rab›› dedi. ‹‹Ama köpekler de efendilerinin sofrasından düşen kırıntıları yer.››'),
(2006887,68,40,15,28,'O zaman İsa ona şu karşılığı verdi: ‹‹Ey kadın, imanın büyük! Dilediğin gibi olsun.›› Ve kadının kızı o saatte iyileşti.'),
(2006888,68,40,15,29,'İsa oradan ayrıldı, Celile Gölünün kıyısından geçerek dağa çıkıp oturdu.'),
(2006889,68,40,15,30,'Yanına büyük bir kalabalık geldi. Beraberlerinde kötürüm, kör, çolak, dilsiz ve daha birçok hasta getirdiler. Hastaları Onun ayaklarının dibine bıraktılar. O da onları iyileştirdi.'),
(2006890,68,40,15,31,'Halk, dilsizlerin konuştuğunu, çolakların iyileştiğini, körlerin gördüğünü, kötürümlerin yürüdüğünü görünce şaştı ve İsrailin Tanrısını yüceltti.'),
(2006891,68,40,15,32,'İsa öğrencilerini yanına çağırıp, ‹‹Halka acıyorum›› dedi. ‹‹Üç gündür yanımdalar, yiyecek hiçbir şeyleri yok. Onları aç aç evlerine göndermek istemiyorum, yolda bayılabilirler.››'),
(2006892,68,40,15,33,'Öğrenciler kendisine, ‹‹Böyle ıssız bir yerde bu kadar kalabalığı doyuracak ekmeği nereden bulalım?›› dediler.'),
(2006893,68,40,15,34,'İsa, ‹‹Kaç ekmeğiniz var?›› diye sordu. ‹‹Yedi ekmekle birkaç küçük balığımız var›› dediler.'),
(2006894,68,40,15,35,'Bunun üzerine İsa, halka yere oturmalarını buyurdu.'),
(2006895,68,40,15,36,'Yedi ekmekle balıkları aldı, şükredip bunları böldü, öğrencilerine verdi. Onlar da halka dağıttılar.'),
(2006896,68,40,15,37,'Herkes yiyip doydu. Artakalan parçalardan yedi küfe dolusu topladılar.'),
(2006897,68,40,15,38,'Yemek yiyenlerin sayısı, kadın ve çocuklar hariç, dört bin erkekti.'),
(2006898,68,40,15,39,'İsa, halkı evlerine gönderdikten sonra tekneye binip Magadan bölgesine geçti.'),
(2006899,68,40,16,1,'Ferisilerle Sadukiler İsanın yanına geldiler. Onu denemek amacıyla kendilerine gökten bir belirti göstermesini istediler.'),
(2006900,68,40,16,2,'İsa onlara şu karşılığı verdi: ‹‹Akşam, ‹Gökyüzü kızıl olduğuna göre hava iyi olacak› dersiniz.'),
(2006901,68,40,16,3,'Sabah, ‹Bugün gök kızıl ve bulutlu, hava bozacak› dersiniz. Gökyüzünün görünümünü yorumlayabiliyorsunuz da, zamanın belirtilerini yorumlayamıyor musunuz?'),
(2006902,68,40,16,4,'Kötü ve vefasız kuşak bir belirti istiyor! Ama ona Yunusun belirtisinden başka bir belirti gösterilmeyecek.›› Sonra İsa onları bırakıp gitti.'),
(2006903,68,40,16,5,'Öğrenciler gölün karşı yakasına geçerken ekmek almayı unutmuşlardı.'),
(2006904,68,40,16,6,'İsa onlara, ‹‹Dikkatli olun, Ferisilerin ve Sadukilerin mayasından kaçının!›› dedi.'),
(2006905,68,40,16,7,'Onlar ise kendi aralarında tartışarak, ‹‹Ekmek almadığımız için böyle diyor›› dediler.'),
(2006906,68,40,16,8,'Bunun farkında olan İsa şöyle dedi: ‹‹Ey kıt imanlılar! Ekmeğiniz yok diye niçin tartışıyorsunuz?'),
(2006907,68,40,16,9,'Hâlâ anlamıyor musunuz? Beş ekmekle beş bin kişinin doyduğunu, kaç sepet dolusu yemek fazlası topladığınızı hatırlamıyor musunuz? Yedi ekmekle dört bin kişinin doyduğunu, kaç küfe dolusu yemek fazlası topladığınızı hatırlamıyor musunuz?'),
(2006908,68,40,16,11,'Ben size, ‹Ferisilerin ve Sadukilerin mayasından kaçının› derken, ekmekten söz etmediğimi nasıl olur da anlamazsınız?››'),
(2006909,68,40,16,12,'Ekmek mayasından değil de, Ferisilerle Sadukilerin öğretisinden kaçının dediğini o zaman anladılar.'),
(2006910,68,40,16,13,'İsa, Filipus Sezariyesi bölgesine geldiğinde öğrencilerine şunu sordu: ‹‹Halk, İnsanoğlunun kim olduğunu söylüyor?››'),
(2006911,68,40,16,14,'Öğrencileri şu karşılığı verdiler: ‹‹Kimi Vaftizci Yahya, kimi İlyas, kimi de Yeremya ya da peygamberlerden biridir diyor.››'),
(2006912,68,40,16,15,'İsa onlara, ‹‹Siz ne dersiniz›› dedi, ‹‹Sizce ben kimim?››'),
(2006913,68,40,16,16,'Simun Petrus, ‹‹Sen, yaşayan Tanrının Oğlu Mesihsin›› yanıtını verdi.'),
(2006914,68,40,16,17,'İsa ona, ‹‹Ne mutlu sana, Yunus oğlu Simun!›› dedi. ‹‹Bu sırrı sana açan insan değil, göklerdeki Babamdır.'),
(2006915,68,40,16,18,'Ben de sana şunu söyleyeyim, sen Petrussun ve ben kilisemi bu kayanın üzerine kuracağım. Ölüler diyarının kapıları ona karşı direnemeyecek.'),
(2006916,68,40,16,19,'Göklerin Egemenliğinin anahtarlarını sana vereceğim. Yeryüzünde bağlayacağın her şey göklerde de bağlanmış olacak; yeryüzünde çözeceğin her şey göklerde de çözülmüş olacak.››'),
(2006917,68,40,16,20,'Bu sözlerden sonra İsa, kendisinin Mesih olduğunu kimseye söylememeleri için öğrencilerini uyardı.'),
(2006918,68,40,16,21,'Bundan sonra İsa, kendisinin Yeruşalime gitmesi, ileri gelenler, başkâhinler ve din bilginlerinin elinden çok acı çekmesi, öldürülmesi ve üçüncü gün dirilmesi gerektiğini öğrencilerine anlatmaya başladı.'),
(2006919,68,40,16,22,'Bunun üzerine Petrus Onu bir kenara çekip azarlamaya başladı. ‹‹Tanrı korusun, ya Rab! Senin başına asla böyle bir şey gelmeyecek!›› dedi.'),
(2006920,68,40,16,23,'Ama İsa Petrusa dönüp, ‹‹Çekil önümden, Şeytan!›› dedi, ‹‹Bana engel oluyorsun. Düşüncelerin Tanrıya değil, insana özgüdür.››'),
(2006921,68,40,16,24,'Sonra İsa, öğrencilerine şunları söyledi: ‹‹Ardımdan gelmek isteyen kendini inkâr etsin, çarmıhını yüklenip beni izlesin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006922,68,40,16,25,'Canını kurtarmak isteyen onu yitirecek, canını benim uğruma yitiren ise onu kurtaracaktır.'),
(2006923,68,40,16,26,'İnsan bütün dünyayı kazanıp da canından olursa, bunun kendisine ne yararı olur? İnsan kendi canına karşılık ne verebilir?'),
(2006924,68,40,16,27,'İnsanoğlu, Babasının görkemi içinde melekleriyle gelecek ve herkese, yaptığının karşılığını verecektir.'),
(2006925,68,40,16,28,'Size doğrusunu söyleyeyim, burada bulunanlar arasında, İnsanoğlu''nun kendi egemenliği içinde gelişini görmeden ölümü tatmayacak olanlar var.››'),
(2006926,68,40,17,1,'Altı gün sonra İsa, yanına yalnız Petrus, Yakup ve Yakupun kardeşi Yuhannayı alarak yüksek bir dağa çıktı.'),
(2006927,68,40,17,2,'Onların gözü önünde İsanın görünümü değişti. Yüzü güneş gibi parladı, giysileri ışık gibi bembeyaz oldu.'),
(2006928,68,40,17,3,'O anda Musayla İlyas öğrencilere göründü. İsayla konuşuyorlardı.'),
(2006929,68,40,17,4,'Petrus İsaya, ‹‹Ya Rab›› dedi, ‹‹Burada bulunmamız ne iyi oldu! İstersen burada üç çardak kurayım: Biri sana, biri Musaya, biri de İlyasa.››'),
(2006930,68,40,17,5,'Petrus daha konuşurken parlak bir bulut onlara gölge saldı. Buluttan gelen bir ses, ‹‹Sevgili Oğlum budur, Ondan hoşnudum. Onu dinleyin!›› dedi.'),
(2006931,68,40,17,6,'Öğrenciler bunu işitince, dehşet içinde yüzüstü yere kapandılar.'),
(2006932,68,40,17,7,'İsa gelip onlara dokundu, ‹‹Kalkın, korkmayın!›› dedi.'),
(2006933,68,40,17,8,'Başlarını kaldırınca İsadan başka kimseyi göremediler.'),
(2006934,68,40,17,9,'Dağdan inerlerken İsa onlara, ‹‹İnsanoğlu ölümden dirilmeden, gördüklerinizi kimseye söylemeyin›› diye buyurdu.'),
(2006935,68,40,17,10,'Öğrencileri Ona şunu sordular: ‹‹Peki, din bilginleri neden önce İlyasın gelmesi gerektiğini söylüyorlar?››'),
(2006936,68,40,17,11,'İsa, ‹‹İlyas gerçekten gelecek ve her şeyi yeniden düzene koyacak›› diye yanıtladı.'),
(2006937,68,40,17,12,'‹‹Size şunu söyleyeyim, İlyas zaten geldi, ama onu tanımadılar, ona yapmadıklarını bırakmadılar. Aynı şekilde İnsanoğlu da onların elinden acı çekecektir.››'),
(2006938,68,40,17,13,'O zaman öğrenciler İsanın kendilerine Vaftizci Yahyadan söz ettiğini anladılar.'),
(2006939,68,40,17,14,'Kalabalığın yanına vardıklarında bir adam İsaya yaklaşıp önünde diz çöktü.'),
(2006940,68,40,17,15,'‹‹Ya Rab›› dedi, ‹‹Oğlumun haline acı! Sarası var, çok acı çekiyor. Sık sık ateşe, suya düşüyor.'),
(2006941,68,40,17,16,'Onu senin öğrencilerine getirdim, ama iyileştiremediler.››'),
(2006942,68,40,17,17,'İsa, ‹‹Ey imansız ve sapmış kuşak!›› dedi. ‹‹Sizinle daha ne kadar kalacağım? Size daha ne kadar katlanacağım? Çocuğu buraya, bana getirin.››'),
(2006943,68,40,17,18,'İsa cini azarlayınca, cin çocuktan çıktı, çocuk o anda iyileşti.'),
(2006944,68,40,17,19,'Sonra öğrenciler tek başlarına İsaya gelip, ‹‹Biz cini neden kovamadık?›› diye sordular.'),
(2006945,68,40,17,20,'İsa, ‹‹İmanınız kıt olduğu için›› karşılığını verdi. ‹‹Size doğrusunu söyleyeyim, bir hardal tanesi kadar imanınız olsa şu dağa, ‹Buradan şuraya göç› derseniz, göçer; sizin için imkânsız bir şey olmayacaktır.››'),
(2006946,68,40,17,22,'Celilede bir araya geldiklerinde İsa onlara, ‹‹İnsanoğlu, insanların eline teslim edilecek ve öldürülecek, ama üçüncü gün dirilecek›› dedi. Öğrenciler buna çok kederlendiler.'),
(2006947,68,40,17,24,'Kefarnahuma geldiklerinde, iki dirhemlik tapınak vergisini toplayanlar Petrusa gelip, ‹‹Öğretmeniniz tapınak vergisini ödemiyor mu?›› diye sordular.'),
(2006948,68,40,17,25,'Petrus, ‹‹Ödüyor›› dedi. Petrus eve gelince, daha kendisi bir şey söylemeden İsa ona, ‹‹Simun, ne dersin?›› dedi. ‹‹Dünya kralları gümrük ya da vergiyi kimlerden alır? Kendi oğullarından mı, yabancılardan mı?››'),
(2006949,68,40,17,26,'Petrusun, ‹‹Yabancılardan›› demesi üzerine İsa, ‹‹O halde oğullar muaftır›› dedi.'),
(2006950,68,40,17,27,'‹‹Ama vergi toplayanları gücendirmeyelim. Göle gidip oltanı at. Tuttuğun ilk balığı çıkar, onun ağzını aç, dört dirhemlik bir akçe bulacaksın. Parayı al, ikimizin vergisi olarak onlara ver.››'),
(2006951,68,40,18,1,'Bu sırada öğrencileri İsaya yaklaşıp, ‹‹Göklerin Egemenliğinde en büyük kimdir?›› diye sordular.'),
(2006952,68,40,18,2,'İsa, yanına küçük bir çocuk çağırdı, onu orta yere dikip şöyle dedi: ‹‹Size doğrusunu söyleyeyim, yolunuzdan dönüp küçük çocuklar gibi olmazsanız, Göklerin Egemenliğine asla giremezsiniz.'),
(2006953,68,40,18,4,'Kim bu çocuk gibi alçakgönüllü olursa, Göklerin Egemenliğinde en büyük odur.'),
(2006954,68,40,18,5,'Böyle bir çocuğu benim adım uğruna kabul eden, beni kabul etmiş olur.'),
(2006955,68,40,18,6,'‹‹Ama kim bana iman eden bu küçüklerden birini günaha düşürürse, boynuna kocaman bir değirmen taşı asılıp denizin dibine atılması kendisi için daha iyi olur.'),
(2006956,68,40,18,7,'İnsanı günaha düşüren tuzaklardan ötürü vay dünyanın haline! Böyle tuzakların olması kaçınılmazdır. Ama bu tuzaklara aracılık eden kişinin vay haline!'),
(2006957,68,40,18,8,'‹‹Eğer elin ya da ayağın günah işlemene neden olursa, onu kesip at. Tek el, tek ayakla yaşama kavuşman, iki elle, iki ayakla sönmez ateşe atılmandan iyidir.'),
(2006958,68,40,18,9,'Eğer gözün günah işlemene neden olursa, onu çıkar at. Tek gözle yaşama kavuşman, iki gözle cehennem ateşine atılmandan iyidir.'),
(2006959,68,40,18,10,'‹‹Bu küçüklerden birini bile hor görmekten sakının! Size şunu söyleyeyim, onların göklerdeki melekleri, göklerdeki Babamın yüzünü her zaman görürler.››'),
(2006960,68,40,18,12,'‹‹Siz ne dersiniz? Bir adamın yüz koyunu olsa ve bunlardan biri yolunu şaşırsa, doksan dokuzunu dağlarda bırakıp yolunu şaşıranı aramaya gitmez mi?'),
(2006961,68,40,18,13,'Size doğrusunu söyleyeyim, eğer onu bulursa, yolunu şaşırmamış doksan dokuz koyun için sevindiğinden daha çok onun için sevinir.'),
(2006962,68,40,18,14,'Bunun gibi, göklerdeki Babanız da bu küçüklerden hiçbirinin kaybolmasını istemez.››'),
(2006963,68,40,18,15,'‹‹Eğer kardeşin sana karşı günah işlerse, ona git, suçunu kendisine göster. Her şey yalnız ikinizin arasında kalsın. Kardeşin seni dinlerse, onu kazanmış olursun.'),
(2006964,68,40,18,16,'Ama dinlemezse, yanına bir ya da iki kişi daha al ki, söylenen her şey iki ya da üç tanığın sözüyle doğrulansın.'),
(2006965,68,40,18,17,'Onları da dinlemezse, durumu inanlılar topluluğuna bildir. Topluluğu da dinlemezse, onu putperest ya da vergi görevlisi say.'),
(2006966,68,40,18,18,'‹‹Size doğrusunu söyleyeyim, yeryüzünde bağlayacağınız her şey gökte de bağlanmış olacak. Yeryüzünde çözeceğiniz her şey gökte de çözülmüş olacak.'),
(2006967,68,40,18,19,'Yine size şunu söyleyeyim, yeryüzünde aranızdan iki kişi, dileyecekleri herhangi bir şey için anlaşırlarsa, göklerdeki Babam dileklerini yerine getirir.'),
(2006968,68,40,18,20,'Nerede iki ya da üç kişi benim adımla toplanırsa, ben de orada, aralarındayım.››'),
(2006969,68,40,18,21,'Bunun üzerine Petrus İsaya gelip, ‹‹Ya Rab›› dedi, ‹‹Kardeşim bana karşı kaç kez günah işlerse onu bağışlamalıyım? Yedi kez mi?››'),
(2006970,68,40,18,22,'İsa, ‹‹Yedi kez değil›› dedi. ‹‹Yetmiş kere yedi kez derim sana.'),
(2006971,68,40,18,23,'Şöyle ki, Göklerin Egemenliği, köleleriyle hesaplaşmak isteyen bir krala benzer.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2006972,68,40,18,24,'Kral hesap görmeye başladığında kendisine, borcu on bin talantı bulan bir köle getirildi.'),
(2006973,68,40,18,25,'Kölenin ödeme gücü olmadığından efendisi onun, karısının, çocuklarının ve bütün malının satılıp borcun ödenmesini buyurdu.'),
(2006974,68,40,18,26,'Köle yere kapanıp efendisine, ‹Ne olur, sabret! Bütün borcumu ödeyeceğim› dedi.'),
(2006975,68,40,18,27,'Efendisi köleye acıdı, borcunu bağışlayıp onu salıverdi.'),
(2006976,68,40,18,28,'‹‹Ama köle çıkıp gitti, kendisine yüz dinar borcu olan başka bir köleye rastladı. Onu yakalayıp, ‹Borcunu öde› diyerek boğazına sarıldı.'),
(2006977,68,40,18,29,'Bu köle yüzüstü yere kapandı, ‹Ne olur, sabret! Borcumu ödeyeceğim› diye yalvardı.'),
(2006978,68,40,18,30,'Ama ilk köle bunu reddetti. Gitti, borcunu ödeyinceye dek adamı zindana kapattı.'),
(2006979,68,40,18,31,'Öteki köleler, olanları görünce çok üzüldüler. Efendilerine gidip bütün olup bitenleri anlattılar.'),
(2006980,68,40,18,32,'‹‹Bunun üzerine efendisi köleyi yanına çağırdı. ‹Ey kötü köle!› dedi. ‹Bana yalvardığın için bütün borcunu bağışladım.'),
(2006981,68,40,18,33,'Benim sana acıdığım gibi, senin de köle arkadaşına acıman gerekmez miydi?›'),
(2006982,68,40,18,34,'Bu öfkeyle efendisi, bütün borcunu ödeyinceye dek onu işkencecilere teslim etti.'),
(2006983,68,40,18,35,'‹‹Eğer her biriniz kardeşini gönülden bağışlamazsa, göksel Babam da size öyle davranacaktır.››'),
(2006984,68,40,19,1,'İsa konuşmasını bitirdikten sonra Celileden ayrılıp Yahudiyenin Şeria Irmağının karşı yakasındaki topraklarına geçti.'),
(2006985,68,40,19,2,'Büyük halk toplulukları da Onun ardından gitti. Hasta olanları orada iyileştirdi.'),
(2006986,68,40,19,3,'İsanın yanına gelen bazı Ferisiler, Onu denemek amacıyla şunu sordular: ‹‹Bir adamın, herhangi bir nedenle karısını boşaması Kutsal Yasaya uygun mudur?››'),
(2006987,68,40,19,4,'İsa şu karşılığı verdi: ‹‹Kutsal Yazıları okumadınız mı? Yaradan başlangıçtan ‹İnsanları erkek ve dişi olarak yarattı› ve şöyle dedi: ‹Bu nedenle adam annesini babasını bırakıp karısına bağlanacak, ikisi tek beden olacak.›'),
(2006988,68,40,19,6,'Şöyle ki, onlar artık iki değil, tek bedendir. O halde Tanrının birleştirdiğini, insan ayırmasın.››'),
(2006989,68,40,19,7,'Ferisiler İsaya, ‹‹Öyleyse›› dediler, ‹‹Musa neden erkeğin boşanma belgesi verip karısını boşayabileceğini söyledi?››'),
(2006990,68,40,19,8,'İsa onlara, ‹‹İnatçı olduğunuz için Musa karılarınızı boşamanıza izin verdi›› dedi. ‹‹Başlangıçta bu böyle değildi.'),
(2006991,68,40,19,9,'Ben size şunu söyleyeyim, karısını fuhuştan başka bir nedenle boşayıp başkasıyla evlenen, zina etmiş olur. Boşanan kadınla evlenen de zina etmiş olur.››'),
(2006992,68,40,19,10,'Öğrenciler İsaya, ‹‹Eğer erkekle karısı arasındaki ilişki buysa, hiç evlenmemek daha iyi!›› dediler.'),
(2006993,68,40,19,11,'İsa onlara, ‹‹Herkes bu sözü kabul edemez, ancak Tanrının güç verdiği kişiler kabul edebilir›› dedi.'),
(2006994,68,40,19,12,'‹‹Çünkü kimisi doğuştan hadımdır, kimisi insanlar tarafından hadım edilir, kimisi de Göklerin Egemenliği uğruna kendini hadım sayar. Bunu kabul edebilen etsin!››'),
(2006995,68,40,19,13,'O sırada bazıları küçük çocukları İsanın yanına getirdiler; ellerini onların üzerine koyup dua etmesini istediler. Öğrenciler onları azarlayınca İsa, ‹‹Bırakın çocukları›› dedi. ‹‹Bana gelmelerine engel olmayın! Çünkü Göklerin Egemenliği böylelerinindir.››'),
(2006996,68,40,19,15,'Ellerini onların üzerine koyduktan sonra oradan ayrıldı.'),
(2006997,68,40,19,16,'Adamın biri İsaya gelip, ‹‹Öğretmenim, sonsuz yaşama kavuşmak için nasıl bir iyilik yapmalıyım?›› diye sordu.'),
(2006998,68,40,19,17,'İsa, ‹‹Bana neden iyilik hakkında soru soruyorsun?›› dedi. ‹‹İyi olan yalnız biri var. Yaşama kavuşmak istiyorsan, Onun buyruklarını yerine getir.››'),
(2006999,68,40,19,18,'‹‹Hangi buyrukları?›› diye sordu adam. İsa şu karşılığı verdi: ‹‹ ‹Adam öldürmeyeceksin, zina etmeyeceksin, çalmayacaksın, yalan yere tanıklık etmeyeceksin, annene babana saygı göstereceksin› ve ‹Komşunu kendin gibi seveceksin.› ››'),
(2007000,68,40,19,20,'Genç adam, ‹‹Bunların hepsini yerine getirdim›› dedi, ‹‹Daha ne eksiğim var?››'),
(2007001,68,40,19,21,'İsa ona, ‹‹Eğer eksiksiz olmak istiyorsan, git, varını yoğunu sat, parasını yoksullara ver; böylece göklerde hazinen olur. Sonra gel, beni izle›› dedi.'),
(2007002,68,40,19,22,'Genç adam bu sözleri işitince üzüntü içinde oradan uzaklaştı. Çünkü çok malı vardı.'),
(2007003,68,40,19,23,'İsa öğrencilerine, ‹‹Size doğrusunu söyleyeyim›› dedi, ‹‹Zengin kişi Göklerin Egemenliğine zor girecek.'),
(2007004,68,40,19,24,'Yine şunu söyleyeyim ki, devenin iğne deliğinden geçmesi, zenginin Tanrı Egemenliğine girmesinden daha kolaydır.››'),
(2007005,68,40,19,25,'Bunu işiten öğrenciler büsbütün şaşırdılar, ‹‹Öyleyse kim kurtulabilir?›› diye sordular.'),
(2007006,68,40,19,26,'İsa onlara bakarak, ‹‹İnsanlar için bu imkânsız, ama Tanrı için her şey mümkündür›› dedi.'),
(2007007,68,40,19,27,'Bunun üzerine Petrus Ona, ‹‹Bak›› dedi, ‹‹Biz her şeyi bırakıp senin ardından geldik, kazancımız ne olacak?››'),
(2007008,68,40,19,28,'İsa onlara, ‹‹Size doğrusunu söyleyeyim›› dedi, ‹‹Her şey yenilendiğinde, İnsanoğlu görkemli tahtına oturduğunda, siz, evet ardımdan gelen sizler, on iki tahta oturup İsrailin on iki oymağını yargılayacaksınız.'),
(2007009,68,40,19,29,'Benim adım uğruna evlerini, kardeşlerini, anne ya da babasını, çocuklarını ya da topraklarını bırakan herkes, bunların yüz katını elde edecek ve sonsuz yaşamı miras alacak.'),
(2007010,68,40,19,30,'Ne var ki, birincilerin birçoğu sonuncu, sonuncuların birçoğu da birinci olacak.››'),
(2007011,68,40,20,1,'‹‹Göklerin Egemenliği, sabah erkenden bağında çalışacak işçi aramaya çıkan toprak sahibine benzer.'),
(2007012,68,40,20,2,'Adam, işçilerle günlüğü bir dinara anlaşıp onları bağına gönderdi.'),
(2007013,68,40,20,3,'‹‹Saat dokuza doğru tekrar dışarı çıktı, çarşı meydanında boş duran başka adamlar gördü.'),
(2007014,68,40,20,4,'Onlara, ‹Siz de bağa gidip çalışın. Hakkınız neyse, veririm› dedi, onlar da bağa gittiler. ‹‹Öğleyin ve saat üçe doğru yine çıkıp aynı şeyi yaptı.'),
(2007015,68,40,20,6,'Saat beşe doğru çıkınca, orada duran başka işçiler gördü. Onlara, ‹Neden bütün gün burada boş duruyorsunuz?› diye sordu.'),
(2007016,68,40,20,7,'‹‹ ‹Kimse bize iş vermedi ki› dediler. ‹‹Onlara, ‹Siz de bağa gidin, çalışın› dedi.'),
(2007017,68,40,20,8,'‹‹Akşam olunca, bağın sahibi kâhyasına, ‹İşçileri çağır› dedi. ‹Sonuncudan başlayarak ilkine kadar, hepsine ücretlerini ver.›'),
(2007018,68,40,20,9,'‹‹Saat beşe doğru işe başlayanlar gelip kâhyadan birer dinar aldılar.'),
(2007019,68,40,20,10,'İlk başlayanlar gelince daha çok alacaklarını sandılar, ama onlara da birer dinar verildi.'),
(2007020,68,40,20,11,'Paralarını alınca bağ sahibine söylenmeye başladılar:'),
(2007021,68,40,20,12,'‹En son çalışanlar yalnız bir saat çalıştı› dediler. ‹Ama onları günün yükünü ve sıcağını çeken bizlerle bir tuttun!›');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007022,68,40,20,13,'‹‹Bağ sahibi onlardan birine şöyle karşılık verdi: ‹Arkadaş, sana haksızlık etmiyorum ki! Seninle bir dinara anlaşmadık mı?'),
(2007023,68,40,20,14,'Hakkını al, git! Sana verdiğimi sonuncuya da vermek istiyorum.'),
(2007024,68,40,20,15,'Kendi paramla istediğimi yapmaya hakkım yok mu? Yoksa cömertliğimi kıskanıyor musun?›'),
(2007025,68,40,20,16,'‹‹İşte böylece sonuncular birinci, birinciler de sonuncu olacak.››'),
(2007026,68,40,20,17,'İsa Yeruşalime giderken, yolda on iki öğrencisini bir yana çekip onlara özel olarak şunu söyledi: ‹‹Şimdi Yeruşalime gidiyoruz. İnsanoğlu, başkâhinlerin ve din bilginlerinin eline teslim edilecek, onlar da Onu ölüm cezasına çarptıracaklar.'),
(2007027,68,40,20,19,'Onunla alay etmeleri, kamçılayıp çarmıha germeleri için Onu öteki uluslara teslim edecekler. Ne var ki O, üçüncü gün dirilecek.››'),
(2007028,68,40,20,20,'O sırada Zebedi oğullarının annesi oğullarıyla birlikte İsaya yaklaştı. Önünde yere kapanarak kendisinden bir dileği olduğunu söyledi.'),
(2007029,68,40,20,21,'İsa kadına, ‹‹Ne istiyorsun?›› diye sordu. Kadın, ‹‹Buyruk ver, senin egemenliğinde bu iki oğlumdan biri sağında, biri solunda otursun›› dedi.'),
(2007030,68,40,20,22,'‹‹Siz ne dilediğinizi bilmiyorsunuz›› diye karşılık verdi İsa. ‹‹Benim içeceğim kâseden siz içebilir misiniz?›› ‹‹Evet, içebiliriz›› dediler.'),
(2007031,68,40,20,23,'İsa onlara, ‹‹Elbette benim kâsemden içeceksiniz›› dedi, ‹‹Ama sağımda ya da solumda oturmanıza izin vermek benim elimde değil. Babam bu yerleri belirli kişiler için hazırlamıştır.››'),
(2007032,68,40,20,24,'Bunu işiten on öğrenci iki kardeşe kızdılar.'),
(2007033,68,40,20,25,'Ama İsa onları yanına çağırıp şöyle dedi: ‹‹Bilirsiniz ki, ulusların önderleri onlara egemen kesilir, ileri gelenleri de ağırlıklarını hissettirirler.'),
(2007034,68,40,20,26,'Sizin aranızda böyle olmayacak. Aranızda büyük olmak isteyen, ötekilerin hizmetkârı olsun.'),
(2007035,68,40,20,27,'Aranızda birinci olmak isteyen, ötekilerin kulu olsun.'),
(2007036,68,40,20,28,'Nitekim İnsanoğlu, hizmet edilmeye değil, hizmet etmeye ve canını birçokları için fidye olarak vermeye geldi.››'),
(2007037,68,40,20,29,'Erihadan ayrılırlarken büyük bir kalabalık İsanın ardından gitti.'),
(2007038,68,40,20,30,'Yol kenarında oturan iki kör, İsanın oradan geçmekte olduğunu duyunca, ‹‹Ya Rab, ey Davut Oğlu, halimize acı!›› diye bağırdılar.'),
(2007039,68,40,20,31,'Kalabalık onları azarlayarak susturmak istediyse de onlar, ‹‹Ya Rab, ey Davut Oğlu, halimize acı!›› diyerek daha çok bağırdılar.'),
(2007040,68,40,20,32,'İsa durup onları çağırdı. ‹‹Sizin için ne yapmamı istiyorsunuz?›› diye sordu.'),
(2007041,68,40,20,33,'Onlar da, ‹‹Ya Rab, gözlerimiz açılsın›› dediler.'),
(2007042,68,40,20,34,'İsa onlara acıdı, gözlerine dokundu. O anda yeniden görmeye başladılar ve O''nun ardından gittiler.'),
(2007043,68,40,21,1,'Yeruşalime yaklaşıp Zeytin Dağının yamacındaki Beytfaci Köyüne geldiklerinde İsa, iki öğrencisini önden gönderdi. Onlara, ‹‹Karşınızdaki köye gidin›› dedi, ‹‹Hemen orada bağlı bir dişi eşek ve yanında bir sıpa bulacaksınız. Onları çözüp bana getirin.'),
(2007044,68,40,21,3,'Size bir şey diyen olursa, ‹Rabbin bunlara ihtiyacı var, hemen geri gönderecek› dersiniz.››'),
(2007045,68,40,21,4,'Bu olay, peygamber aracılığıyla bildirilen şu söz yerine gelsin diye oldu:'),
(2007046,68,40,21,5,'‹‹Siyon kızına deyin ki, ‹İşte, alçakgönüllü Kralın, Eşeğe, evet sıpaya, Eşek yavrusuna binmiş Sana geliyor.› ››'),
(2007047,68,40,21,6,'Öğrenciler gidip İsanın kendilerine buyurduğu gibi yaptılar.'),
(2007048,68,40,21,7,'Eşekle sıpayı getirip üzerlerine giysilerini yaydılar, İsa sıpaya bindi.'),
(2007049,68,40,21,8,'Halkın büyük bir bölümü giysilerini yolun üzerine serdi. Bazıları da ağaçlardan dal kesip yola seriyordu.'),
(2007050,68,40,21,9,'Önden giden ve arkadan gelen kalabalıklar şöyle bağırıyorlardı: ‹‹Davut Oğluna hozana! Rabbin adıyla gelene övgüler olsun, En yücelerde hozana!››'),
(2007051,68,40,21,10,'İsa Yeruşalime girdiği zaman bütün kent, ‹‹Bu kimdir?›› diyerek çalkandı.'),
(2007052,68,40,21,11,'Kalabalıklar, ‹‹Bu, Celilenin Nasıra Kentinden Peygamber İsadır›› diyordu.'),
(2007053,68,40,21,12,'İsa, tapınağın avlusuna girerek oradaki bütün alıcı ve satıcıları dışarı kovdu. Para bozanların masalarını, güvercin satanların sehpalarını devirdi.'),
(2007054,68,40,21,13,'Onlara şöyle dedi: ‹‹ ‹Evime dua evi denecek› diye yazılmıştır. Ama siz onu haydut inine çevirdiniz!››'),
(2007055,68,40,21,14,'İsa tapınaktayken kendisine gelen kör ve kötürümleri iyileştirdi.'),
(2007056,68,40,21,15,'Ne var ki, başkâhinlerle din bilginleri, Onun yarattığı harikaları ve tapınakta, ‹‹Davut Oğluna hozana!›› diye bağıran çocukları görünce öfkelendiler.'),
(2007057,68,40,21,16,'İsaya, ‹‹Bunların ne söylediğini duyuyor musun?›› diye sordular. ‹‹Duyuyorum›› dedi İsa. ‹‹Siz şu sözü hiç okumadınız mı? ‹Küçük çocukların ve emziktekilerin dudaklarından kendine övgüler döktürdün.› ››'),
(2007058,68,40,21,17,'İsa onları bırakıp kentten çıktı. Beytanyaya dönüp geceyi orada geçirdi.'),
(2007059,68,40,21,18,'İsa sabah erkenden kente dönerken acıkmıştı.'),
(2007060,68,40,21,19,'Yol kenarında gördüğü bir incir ağacına yaklaştı. Ağaçta yapraktan başka bir şey bulamayınca ağaca, ‹‹Artık sonsuza dek sende meyve yetişmesin!›› dedi. İncir ağacı o anda kurudu.'),
(2007061,68,40,21,20,'Öğrenciler bunu görünce şaşkına döndüler. ‹‹İncir ağacı birdenbire nasıl kurudu?›› diye sordular.'),
(2007062,68,40,21,21,'İsa onlara şu karşılığı verdi: ‹‹Size doğrusunu söyleyeyim, eğer imanınız olur da kuşku duymazsanız, yalnız incir ağacına olanı yapmakla kalmazsınız; şu dağa, ‹Kalk, denize atıl› derseniz, dediğiniz olacaktır.'),
(2007063,68,40,21,22,'İmanla dua ederseniz, dilediğiniz her şeyi alırsınız.››'),
(2007064,68,40,21,23,'İsa tapınağa girmiş öğretiyordu. Bu sırada başkâhinler ve halkın ileri gelenleri Onun yanına gelerek, ‹‹Bunları hangi yetkiyle yapıyorsun, bu yetkiyi sana kim verdi?›› diye sordular.'),
(2007065,68,40,21,24,'İsa onlara şu karşılığı verdi: ‹‹Ben de size bir soru soracağım. Bana yanıt verirseniz, ben de size bunları hangi yetkiyle yaptığımı söylerim.'),
(2007066,68,40,21,25,'Yahyanın vaftiz etme yetkisi nereden geldi, Tanrıdan mı, insanlardan mı?›› Bunu aralarında şöyle tartışmaya başladılar: ‹‹ ‹Tanrıdan› dersek, bize, ‹Öyleyse ona niçin inanmadınız?› diyecek.'),
(2007067,68,40,21,26,'Yok eğer ‹İnsanlardan› dersek... Halkın tepkisinden korkuyoruz. Çünkü herkes Yahyayı peygamber sayıyor.››'),
(2007068,68,40,21,27,'İsaya, ‹‹Bilmiyoruz›› diye yanıt verdiler. İsa, ‹‹Ben de size bunları hangi yetkiyle yaptığımı söylemeyeceğim›› dedi.'),
(2007069,68,40,21,28,'‹‹Ama şuna ne dersiniz? Bir adamın iki oğlu vardı. Adam birincisine gidip, ‹Oğlum, git bugün bağda çalış› dedi.'),
(2007070,68,40,21,29,'‹‹Oğlu, ‹Gitmem!› dedi. Ama sonra pişman olup gitti.'),
(2007071,68,40,21,30,'‹‹Adam ikinci oğluna gidip aynı şeyi söyledi. O, ‹Olur, efendim› dedi, ama gitmedi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007072,68,40,21,31,'‹‹İkisinden hangisi babasının isteğini yerine getirmiş oldu?›› ‹‹Birincisi›› diye karşılık verdiler. İsa da onlara, ‹‹Size doğrusunu söyleyeyim, vergi görevlileriyle fahişeler, Tanrının Egemenliğine sizden önce giriyorlar›› dedi.'),
(2007073,68,40,21,32,'‹‹Yahya size doğruluk yolunu göstermeye geldi, ona inanmadınız. Oysa vergi görevlileriyle fahişeler ona inandılar. Siz bunu gördükten sonra bile pişman olup ona inanmadınız.››'),
(2007074,68,40,21,33,'‹‹Bir benzetme daha dinleyin: Toprak sahibi bir adam, bağ dikti, çevresini çitle çevirdi, üzüm sıkma çukuru kazdı, bir de bekçi kulesi yaptı. Sonra bağı bağcılara kiralayıp yolculuğa çıktı.'),
(2007075,68,40,21,34,'Bağbozumu yaklaşınca, üründen kendisine düşeni almaları için kölelerini bağcılara yolladı.'),
(2007076,68,40,21,35,'Bağcılar adamın kölelerini yakaladı, birini dövdü, birini öldürdü, ötekini de taşladı.'),
(2007077,68,40,21,36,'Bağ sahibi bu kez ilkinden daha çok sayıda köle yolladı. Bağcılar bunlara da aynı şeyi yaptılar.'),
(2007078,68,40,21,37,'Sonunda bağ sahibi, ‹Oğlumu sayarlar› diyerek bağcılara onu yolladı.'),
(2007079,68,40,21,38,'‹‹Ama bağcılar adamın oğlunu görünce birbirlerine, ‹Mirasçı bu; gelin, onu öldürüp mirasına konalım› dediler.'),
(2007080,68,40,21,39,'Böylece onu yakaladılar, bağdan atıp öldürdüler.'),
(2007081,68,40,21,40,'Bu durumda bağın sahibi geldiği zaman bağcılara ne yapacak?››'),
(2007082,68,40,21,41,'İsaya şu karşılığı verdiler: ‹‹Bu korkunç adamları korkunç bir şekilde yok edecek; bağı da, ürününü kendisine zamanında verecek olan başka bağcılara kiralayacak.››'),
(2007083,68,40,21,42,'İsa onlara şunu sordu: ‹‹Kutsal Yazılarda şu sözleri hiç okumadınız mı? ‹Yapıcıların reddettiği taş, İşte köşenin baş taşı oldu. Rabbin işidir bu, Gözümüzde harika bir iş!›'),
(2007084,68,40,21,43,'‹‹Bu nedenle size şunu söyleyeyim, Tanrının Egemenliği sizden alınacak ve bunun ürünlerini yetiştiren bir ulusa verilecek.'),
(2007085,68,40,21,44,'‹‹Bu taşın üzerine düşen, paramparça olacak; taş da kimin üzerine düşerse, onu ezip toz edecek.››'),
(2007086,68,40,21,45,'Başkâhinler ve Ferisiler, İsanın anlattığı benzetmeleri duyunca bunları kendileri için söylediğini anladılar.'),
(2007087,68,40,21,46,'O''nu tutuklamak istedilerse de, halkın tepkisinden korktular. Çünkü halk, O''nu peygamber sayıyordu.'),
(2007088,68,40,22,1,'İsa söz alıp onlara yine benzetmelerle şöyle seslendi: ‹‹Göklerin Egemenliği, oğlu için düğün şöleni hazırlayan bir krala benzer.'),
(2007089,68,40,22,3,'Kral şölene davet ettiklerini çağırmak üzere kölelerini gönderdi, ama davetliler gelmek istemedi.'),
(2007090,68,40,22,4,'‹‹Kral yine başka kölelerini gönderirken onlara dedi ki, ‹Davetlilere şunu söyleyin: Bakın, ben ziyafetimi hazırladım. Sığırlarım, besili hayvanlarım kesildi. Her şey hazır, buyrun şölene!›'),
(2007091,68,40,22,5,'‹‹Ama davetliler aldırmadılar. Biri tarlasına, biri ticaretine gitti.'),
(2007092,68,40,22,6,'Öbürleri de kralın kölelerini yakalayıp hırpaladılar ve öldürdüler.'),
(2007093,68,40,22,7,'Kral öfkelendi. Ordularını gönderip o katilleri yok etti, kentlerini ateşe verdi.'),
(2007094,68,40,22,8,'‹‹Sonra kölelerine şöyle dedi: ‹Düğün şöleni hazır, ama çağırdıklarım buna layık değilmiş.'),
(2007095,68,40,22,9,'Gidin yol kavşaklarına, kimi bulursanız düğüne çağırın.›'),
(2007096,68,40,22,10,'Böylece köleler yollara döküldü, iyi kötü kimi buldularsa, hepsini topladılar. Düğün yeri konuklarla doldu.'),
(2007097,68,40,22,11,'‹‹Kral konukları görmeye geldiğinde, orada düğün giysisi giymemiş bir adam gördü.'),
(2007098,68,40,22,12,'Ona, ‹Arkadaş, düğün giysisi giymeden buraya nasıl girdin?› diye sorunca, adamın dili tutuldu.'),
(2007099,68,40,22,13,'‹‹O zaman kral, uşaklarına, ‹Şunun ellerini ayaklarını bağlayın, dışarıya, karanlığa atın!› dedi. ‹Orada ağlayış ve diş gıcırtısı olacaktır.›'),
(2007100,68,40,22,14,'‹‹Çünkü çağrılanlar çok, ama seçilenler azdır.››'),
(2007101,68,40,22,15,'Bunun üzerine Ferisiler çıkıp gittiler. İsayı, kendi söyleyeceği sözlerle tuzağa düşürmek amacıyla düzen kurdular.'),
(2007102,68,40,22,16,'Hirodes yanlılarıyla birlikte gönderdikleri kendi öğrencileri İsaya gelip, ‹‹Öğretmenimiz›› dediler, ‹‹Senin dürüst biri olduğunu, Tanrı yolunu dürüstçe öğrettiğini, kimseyi kayırmadığını biliyoruz. Çünkü insanlar arasında ayrım yapmazsın.'),
(2007103,68,40,22,17,'Peki, söyle bize, sence Sezara vergi vermek Kutsal Yasaya uygun mu, değil mi?››'),
(2007104,68,40,22,18,'İsa onların kötü niyetlerini bildiğinden, ‹‹Ey ikiyüzlüler!›› dedi. ‹‹Beni neden deniyorsunuz?'),
(2007105,68,40,22,19,'Vergi öderken kullandığınız parayı gösterin bana!›› Ona bir dinar getirdiler.'),
(2007106,68,40,22,20,'İsa, ‹‹Bu resim, bu yazı kimin?›› diye sordu.'),
(2007107,68,40,22,21,'‹‹Sezarın›› dediler. O zaman İsa, ‹‹Öyleyse Sezarın hakkını Sezara, Tanrının hakkını Tanrıya verin›› dedi.'),
(2007108,68,40,22,22,'Bu sözleri duyunca şaştılar, İsayı bırakıp gittiler.'),
(2007109,68,40,22,23,'Ölümden sonra diriliş olmadığını söyleyen Sadukiler, aynı gün İsaya gelip şunu sordular: ‹‹Öğretmenimiz, Musa şöyle buyurmuştur: ‹Eğer bir adam çocuk sahibi olmadan ölürse, kardeşi onun karısını alsın, soyunu sürdürsün.›'),
(2007110,68,40,22,25,'Aramızda yedi kardeş vardı. İlki evlendi ve öldü. Çocuğu olmadığından karısını kardeşine bıraktı.'),
(2007111,68,40,22,26,'İkincisi, üçüncüsü, yedincisine kadar hepsine aynı şey oldu.'),
(2007112,68,40,22,27,'Hepsinden sonra kadın da öldü.'),
(2007113,68,40,22,28,'Buna göre diriliş günü kadın bu yedi kardeşten hangisinin karısı olacak? Çünkü hepsi de onunla evlendi.››'),
(2007114,68,40,22,29,'İsa onlara, ‹‹Siz Kutsal Yazıları ve Tanrının gücünü bilmediğiniz için yanılıyorsunuz›› diye karşılık verdi.'),
(2007115,68,40,22,30,'‹‹Dirilişten sonra insanlar ne evlenir, ne de evlendirilir, gökteki melekler gibidirler.'),
(2007116,68,40,22,31,'Ölülerin dirilmesi konusuna gelince, Tanrının size bildirdiği şu sözü okumadınız mı?'),
(2007117,68,40,22,32,'‹Ben İbrahimin Tanrısı, İshakın Tanrısı ve Yakupun Tanrısıyım› diyor. Tanrı ölülerin değil, dirilerin Tanrısıdır.››'),
(2007118,68,40,22,33,'Bunları işiten halk, Onun öğretişine şaşıp kaldı.'),
(2007119,68,40,22,34,'Ferisiler, İsanın Sadukileri susturduğunu duyunca bir araya toplandılar.'),
(2007120,68,40,22,35,'Onlardan biri, bir Kutsal Yasa uzmanı, İsayı denemek amacıyla Ona şunu sordu: ‹‹Öğretmenim, Kutsal Yasada en önemli buyruk hangisidir?››'),
(2007121,68,40,22,37,'İsa ona şu karşılığı verdi: ‹‹ ‹Tanrın Rabbi bütün yüreğinle, bütün canınla ve bütün aklınla seveceksin.›');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007122,68,40,22,38,'İşte ilk ve en önemli buyruk budur.'),
(2007123,68,40,22,39,'İlkine benzeyen ikinci buyruk da şudur: ‹Komşunu kendin gibi seveceksin.›'),
(2007124,68,40,22,40,'Kutsal Yasanın tümü ve peygamberlerin sözleri bu iki buyruğa dayanır.››'),
(2007125,68,40,22,41,'Ferisiler toplu haldeyken İsa onlara şunu sordu: ‹‹Mesihle ilgili olarak ne düşünüyorsunuz? O kimin oğludur?›› Onlar da, ‹‹Davutun Oğlu›› dediler.'),
(2007126,68,40,22,43,'İsa şöyle dedi: ‹‹O halde nasıl oluyor da Davut, Ruhtan esinlenerek Ondan ‹Rab› diye söz ediyor? Şöyle diyor Davut:'),
(2007127,68,40,22,44,'‹Rab Rabbime dedi ki, Ben düşmanlarını Ayaklarının altına serinceye dek Sağımda otur.›'),
(2007128,68,40,22,45,'Davut Ondan Rab diye söz ettiğine göre, O nasıl Davutun Oğlu olur?››'),
(2007129,68,40,22,46,'İsa''ya hiç kimse karşılık veremedi. O günden sonra artık kimse de O''na bir şey sormaya cesaret edemedi.'),
(2007130,68,40,23,1,'Bundan sonra İsa halka ve öğrencilerine şöyle seslendi: ‹‹Din bilginleri ve Ferisiler Musanın kürsüsünde otururlar.'),
(2007131,68,40,23,3,'Bu nedenle size söylediklerinin tümünü yapın ve yerine getirin, ama onların yaptıklarını yapmayın. Çünkü söyledikleri şeyleri kendileri yapmazlar.'),
(2007132,68,40,23,4,'Ağır ve taşınması güç yükleri bağlayıp başkalarının sırtına yüklerler, kendileriyse bu yükleri taşımak için parmaklarını bile oynatmak istemezler.'),
(2007133,68,40,23,5,'‹‹Yaptıklarının tümünü gösteriş için yaparlar. Örneğin, hamaillerini büyük, giysilerinin püsküllerini uzun yaparlar.'),
(2007134,68,40,23,6,'Şölenlerde başköşeye, havralarda en seçkin yerlere kurulmaya bayılırlar.'),
(2007135,68,40,23,7,'Meydanlarda selamlanmaktan ve insanların kendilerini ‹Rabbî› diye çağırmalarından zevk duyarlar.'),
(2007136,68,40,23,8,'‹‹Kimse sizi ‹Rabbî› diye çağırmasın. Çünkü sizin tek öğretmeniniz var ve hepiniz kardeşsiniz.'),
(2007137,68,40,23,9,'Yeryüzünde kimseye ‹Baba› demeyin. Çünkü tek Babanız var, O da göksel Babadır.'),
(2007138,68,40,23,10,'Kimse sizi ‹Önder› diye çağırmasın. Çünkü tek önderiniz var, O da Mesihtir.'),
(2007139,68,40,23,11,'Aranızda en üstün olan, ötekilerin hizmetkârı olsun.'),
(2007140,68,40,23,12,'Kendini yücelten alçaltılacak, kendini alçaltan yüceltilecektir.'),
(2007141,68,40,23,13,'‹‹Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Göklerin Egemenliğinin kapısını insanların yüzüne kapıyorsunuz; ne kendiniz içeri giriyor, ne de girmek isteyenleri bırakıyorsunuz!'),
(2007142,68,40,23,15,'‹‹Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Tek bir kişiyi dininize döndürmek için denizleri, kıtaları dolaşırsınız. Dininize döneni de kendinizden iki kat cehennemlik yaparsınız.'),
(2007143,68,40,23,16,'‹‹Vay halinize kör kılavuzlar! Diyorsunuz ki, ‹Tapınak üzerine ant içenin andı sayılmaz, ama tapınaktaki altın üzerine ant içen, andını yerine getirmek zorundadır.›'),
(2007144,68,40,23,17,'Budalalar, körler! Hangisi daha önemli, altın mı, altını kutsal kılan tapınak mı?'),
(2007145,68,40,23,18,'Yine diyorsunuz ki, ‹Sunak üzerine ant içenin andı sayılmaz, ama sunaktaki adağın üzerine ant içen, andını yerine getirmek zorundadır.›'),
(2007146,68,40,23,19,'Ey körler! Hangisi daha önemli, adak mı, adağı kutsal kılan sunak mı?'),
(2007147,68,40,23,20,'Öyleyse sunak üzerine ant içen, hem sunağın hem de sunaktaki her şeyin üzerine ant içmiş olur.'),
(2007148,68,40,23,21,'Tapınak üzerine ant içen de hem tapınak, hem de tapınakta yaşayan Tanrı üzerine ant içmiş olur.'),
(2007149,68,40,23,22,'Gök üzerine ant içen, Tanrının tahtı ve tahtta oturanın üzerine ant içmiş olur.'),
(2007150,68,40,23,23,'‹‹Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Siz nanenin, dereotunun ve kimyonun ondalığını verirsiniz de, Kutsal Yasanın daha önemli konularını -adaleti, merhameti, sadakati- ihmal edersiniz. Ondalık vermeyi ihmal etmeden asıl bunları yerine getirmeniz gerekirdi.'),
(2007151,68,40,23,24,'Ey kör kılavuzlar! Küçük sineği süzer ayırır, ama deveyi yutarsınız!'),
(2007152,68,40,23,25,'‹‹Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Bardağın ve çanağın dışını temizlersiniz, oysa bunların içi açgözlülük ve taşkınlıkla doludur.'),
(2007153,68,40,23,26,'Ey kör Ferisi! Sen önce bardağın ve çanağın içini temizle ki, dıştan da temiz olsunlar.'),
(2007154,68,40,23,27,'‹‹Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Siz dıştan güzel görünen, ama içi ölü kemikleri ve her türlü pislikle dolu badanalı mezarlara benzersiniz.'),
(2007155,68,40,23,28,'Dıştan insanlara doğru görünürsünüz, ama içte ikiyüzlülük ve kötülükle dolusunuz.'),
(2007156,68,40,23,29,'‹‹Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Peygamberlerin mezarlarını yapar, doğru kişilerin anıtlarını donatırsınız.'),
(2007157,68,40,23,30,'‹Atalarımızın yaşadığı günlerde yaşasaydık, onlarla birlikte peygamberlerin kanına girmezdik› diyorsunuz.'),
(2007158,68,40,23,31,'Böylece, peygamberleri öldürenlerin torunları olduğunuza kendiniz tanıklık ediyorsunuz.'),
(2007159,68,40,23,32,'Haydi, atalarınızın başlattığı işi bitirin!'),
(2007160,68,40,23,33,'‹‹Sizi yılanlar, engerekler soyu! Cehennem cezasından nasıl kaçacaksınız?'),
(2007161,68,40,23,34,'İşte bunun için size peygamberler, bilge kişiler ve din bilginleri gönderiyorum. Bunlardan kimini öldürecek, çarmıha gereceksiniz. Kimini havralarınızda kamçılayacak, kentten kente kovalayacaksınız.'),
(2007162,68,40,23,35,'Böylelikle, doğru kişi olan Habilin kanından, tapınakla sunak arasında öldürdüğünüz Berekya oğlu Zekeriyanın kanına kadar, yeryüzünde akıtılan her doğru kişinin kanından sorumlu tutulacaksınız.'),
(2007163,68,40,23,36,'Size doğrusunu söyleyeyim, bunların hepsinden bu kuşak sorumlu tutulacaktır.'),
(2007164,68,40,23,37,'‹‹Ey Yeruşalim! Peygamberleri öldüren, kendisine gönderilenleri taşlayan Yeruşalim! Tavuğun civcivlerini kanatları altına topladığı gibi ben de kaç kez senin çocuklarını toplamak istedim, ama siz istemediniz.'),
(2007165,68,40,23,38,'Bakın, eviniz ıssız bırakılacak!'),
(2007166,68,40,23,39,'Size şunu söyleyeyim: ‹Rab''bin adıyla gelene övgüler olsun!› diyeceğiniz zamana dek beni bir daha görmeyeceksiniz.››'),
(2007167,68,40,24,1,'İsa tapınaktan çıkıp giderken, öğrencileri, tapınağın binalarını Ona göstermek için yanına geldiler.'),
(2007168,68,40,24,2,'İsa onlara, ‹‹Bütün bunları görüyor musunuz?›› dedi. ‹‹Size doğrusunu söyleyeyim, burada taş üstünde taş kalmayacak, hepsi yıkılacak!››'),
(2007169,68,40,24,3,'İsa, Zeytin Dağında otururken öğrencileri yalnız olarak yanına geldiler. ‹‹Söyle bize›› dediler, ‹‹Bu dediklerin ne zaman olacak, senin gelişini ve çağın bitimini gösteren belirti ne olacak?››'),
(2007170,68,40,24,4,'İsa onlara şu karşılığı verdi: ‹‹Sakın kimse sizi saptırmasın!'),
(2007171,68,40,24,5,'Birçokları, ‹Mesih benim› diyerek benim adımla gelip birçok kişiyi aldatacaklar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007172,68,40,24,6,'Savaş gürültüleri, savaş haberleri duyacaksınız. Sakın korkmayın! Bunların olması gerek, ama bu daha son demek değildir.'),
(2007173,68,40,24,7,'Ulus ulusa, devlet devlete savaş açacak; yer yer kıtlıklar, depremler olacak.'),
(2007174,68,40,24,8,'Bütün bunlar, doğum sancılarının başlangıcıdır.'),
(2007175,68,40,24,9,'‹‹O zaman sizi sıkıntıya sokacak, öldürecekler. Benim adımdan ötürü bütün uluslar sizden nefret edecek.'),
(2007176,68,40,24,10,'O zaman birçok kişi imandan sapacak, birbirlerini ele verecek ve birbirlerinden nefret edecekler.'),
(2007177,68,40,24,11,'Birçok sahte peygamber türeyecek ve bunlar birçok kişiyi saptıracak.'),
(2007178,68,40,24,12,'Kötülüklerin çoğalmasından ötürü birçoklarının sevgisi soğuyacak.'),
(2007179,68,40,24,13,'Ama sonuna kadar dayanan kurtulacaktır.'),
(2007180,68,40,24,14,'Göksel egemenliğin bu Müjdesi bütün uluslara tanıklık olmak üzere dünyanın her yerinde duyurulacak. İşte o zaman son gelecektir.'),
(2007181,68,40,24,15,'‹‹Peygamber Danielin sözünü ettiği yıkıcı iğrenç şeyin kutsal yerde dikildiğini gördüğünüz zaman -okuyan anlasın- Yahudiyede bulunanlar dağlara kaçsın.'),
(2007182,68,40,24,17,'Damda olan, evindeki eşyalarını almak için aşağı inmesin.'),
(2007183,68,40,24,18,'Tarlada olan, abasını almak için geri dönmesin.'),
(2007184,68,40,24,19,'O günlerde gebe olan, çocuk emziren kadınların vay haline!'),
(2007185,68,40,24,20,'Dua edin ki, kaçışınız kışa ya da Şabat Gününe rastlamasın.'),
(2007186,68,40,24,21,'Çünkü o günlerde öyle korkunç bir sıkıntı olacak ki, dünyanın başlangıcından bu yana böylesi olmamış, bundan sonra da olmayacaktır.'),
(2007187,68,40,24,22,'O günler kısaltılmamış olsaydı, hiç kimse kurtulamazdı. Ama seçilmiş olanlar uğruna o günler kısaltılacak.'),
(2007188,68,40,24,23,'Eğer o zaman biri size, ‹İşte Mesih burada›, ya da ‹İşte şurada› derse, inanmayın.'),
(2007189,68,40,24,24,'Çünkü sahte mesihler, sahte peygamberler türeyecek; bunlar büyük belirtiler ve harikalar yapacaklar. Öyle ki, ellerinden gelse, seçilmiş olanları bile saptıracaklar.'),
(2007190,68,40,24,25,'İşte size önceden söylüyorum.'),
(2007191,68,40,24,26,'‹‹Bunun için size, ‹İşte Mesih çölde› derlerse gitmeyin. ‹Bakın, iç odalarda› derlerse inanmayın.'),
(2007192,68,40,24,27,'Çünkü İnsanoğlunun gelişi, doğuda çakıp batıya kadar her taraftan görülen şimşek gibi olacaktır.'),
(2007193,68,40,24,28,'‹‹Leş neredeyse, akbabalar oraya üşüşecek.'),
(2007194,68,40,24,29,'‹‹O günlerin sıkıntısından hemen sonra, ‹Güneş kararacak, Ay ışık vermez olacak, Yıldızlar gökten düşecek, Göksel güçler sarsılacak.›'),
(2007195,68,40,24,30,'‹‹O zaman İnsanoğlunun belirtisi gökte görünecek. Yeryüzündeki bütün halklar ağlayıp dövünecek, İnsanoğlunun gökteki bulutlar üzerinde büyük güç ve görkemle geldiğini görecekler.'),
(2007196,68,40,24,31,'Kendisi güçlü bir borazan sesiyle meleklerini gönderecek. Melekler Onun seçtiklerini göğün bir ucundan öbür ucuna dek, dünyanın dört bucağından toplayacaklar.'),
(2007197,68,40,24,32,'‹‹İncir ağacından ders alın! Dalları filizlenip yaprakları sürünce, yaz mevsiminin yakın olduğunu anlarsınız.'),
(2007198,68,40,24,33,'Aynı şekilde, bütün bunların gerçekleştiğini gördüğünüzde bilin ki, İnsanoğlu yakındır, kapıdadır.'),
(2007199,68,40,24,34,'Size doğrusunu söyleyeyim, bütün bunlar olmadan bu kuşak ortadan kalkmayacak.'),
(2007200,68,40,24,35,'Yer ve gök ortadan kalkacak, ama benim sözlerim asla ortadan kalkmayacaktır.››'),
(2007201,68,40,24,36,'‹‹O günü ve saati, ne gökteki melekler, ne de Oğul bilir; Babadan başka kimse bilmez.'),
(2007202,68,40,24,37,'Nuhun günlerinde nasıl olduysa, İnsanoğlunun gelişinde de öyle olacak.'),
(2007203,68,40,24,38,'Nuhun gemiye bindiği güne dek, tufandan önceki günlerde insanlar yiyip içiyor, evlenip evlendiriliyorlardı.'),
(2007204,68,40,24,39,'Tufan gelinceye, hepsini süpürüp götürünceye dek başlarına geleceklerden habersizdiler. İnsanoğlunun gelişi de öyle olacak.'),
(2007205,68,40,24,40,'O gün tarlada bulunan iki kişiden biri alınacak, biri bırakılacak.'),
(2007206,68,40,24,41,'Değirmende buğday öğüten iki kadından biri alınacak, biri bırakılacak.'),
(2007207,68,40,24,42,'‹‹Bunun için uyanık kalın. Çünkü Rabbinizin geleceği günü bilemezsiniz.'),
(2007208,68,40,24,43,'Ama şunu bilin ki, ev sahibi, hırsızın gece hangi saatte geleceğini bilse, uyanık kalır, evinin soyulmasına fırsat vermez.'),
(2007209,68,40,24,44,'Bunun için siz de hazır olun! Çünkü İnsanoğlu beklemediğiniz saatte gelecektir.'),
(2007210,68,40,24,45,'‹‹Efendinin, hizmetkârlarına vaktinde yiyecek vermek için başlarına atadığı güvenilir ve akıllı köle kimdir?'),
(2007211,68,40,24,46,'Efendisi eve döndüğünde işinin başında bulacağı o köleye ne mutlu!'),
(2007212,68,40,24,47,'Size doğrusunu söyleyeyim, efendisi onu bütün malının üzerinde yetkili kılacak.'),
(2007213,68,40,24,48,'Ama o köle kötü olur da içinden, ‹Efendim gecikiyor› der ve öteki köleleri dövmeye başlarsa, sarhoşlarla birlikte yiyip içerse, efendisi, onun beklemediği günde, ummadığı saatte gelecek, onu şiddetle cezalandırıp ikiyüzlülerle bir tutacak. Orada ağlayış ve diş gıcırtısı olacaktır.››'),
(2007214,68,40,25,1,'‹‹O zaman Göklerin Egemenliği, kandillerini alıp güveyi karşılamaya çıkan on kıza benzeyecek.'),
(2007215,68,40,25,2,'Bunların beşi akıllı, beşi akılsızdı.'),
(2007216,68,40,25,3,'Akılsızlar yanlarına kandillerini aldılar, ama yağ almadılar.'),
(2007217,68,40,25,4,'Akıllılar ise, kandilleriyle birlikte kaplar içinde yağ da aldılar.'),
(2007218,68,40,25,5,'Güvey gecikince hepsini uyku bastı, dalıp uyudular.'),
(2007219,68,40,25,6,'‹‹Gece yarısı bir ses yankılandı: ‹İşte güvey geliyor, onu karşılamaya çıkın!›'),
(2007220,68,40,25,7,'Bunun üzerine kızların hepsi kalkıp kandillerini tazelediler.'),
(2007221,68,40,25,8,'‹‹Akılsızlar akıllılara, ‹Kandillerimiz sönüyor, bize yağ verin!› dediler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007222,68,40,25,9,'‹‹Akıllılar, ‹Olmaz! Hem bize hem size yetmeyebilir. En iyisi satıcılara gidin, kendinize yağ alın› dediler.'),
(2007223,68,40,25,10,'‹‹Ne var ki, onlar yağ satın almaya giderlerken güvey geldi. Hazırlıklı olan kızlar, onunla birlikte düğün şölenine girdiler ve kapı kapandı.'),
(2007224,68,40,25,11,'‹‹Daha sonra gelen öbür kızlar, ‹Efendimiz, efendimiz, aç kapıyı bize!› dediler.'),
(2007225,68,40,25,12,'‹‹Güvey ise, ‹Size doğrusunu söyleyeyim, sizi tanımıyorum› dedi.'),
(2007226,68,40,25,13,'‹‹Bu nedenle uyanık kalın. Çünkü o günü ve o saati bilemezsiniz.››'),
(2007227,68,40,25,14,'‹‹Göksel egemenlik, yolculuğa çıkan bir adamın kölelerini çağırıp malını onlara emanet etmesine benzer.'),
(2007228,68,40,25,15,'‹‹Adam, her birinin yeteneğine göre, birine beş, birine iki, birine de bir talant vererek yola çıktı.'),
(2007229,68,40,25,16,'Beş talant alan, hemen gidip bu parayı işletti ve beş talant daha kazandı.'),
(2007230,68,40,25,17,'İki talant alan da iki talant daha kazandı.'),
(2007231,68,40,25,18,'Bir talant alan ise gidip toprağı kazdı ve efendisinin parasını sakladı.'),
(2007232,68,40,25,19,'‹‹Uzun zaman sonra bu kölelerin efendisi döndü, onlarla hesaplaşmaya oturdu.'),
(2007233,68,40,25,20,'Beş talant alan gelip beş talant daha getirdi, ‹Efendimiz› dedi, ‹Bana beş talant emanet etmiştin; bak, beş talant daha kazandım.›'),
(2007234,68,40,25,21,'‹‹Efendisi ona, ‹Aferin, iyi ve güvenilir köle!› dedi. ‹Sen küçük işlerde güvenilir olduğunu gösterdin, ben de seni büyük işlerin başına geçireceğim. Gel, efendinin şenliğine katıl!›'),
(2007235,68,40,25,22,'‹‹İki talant alan da geldi, ‹Efendimiz› dedi, ‹Bana iki talant emanet etmiştin; bak, iki talant daha kazandım.›'),
(2007236,68,40,25,23,'‹‹Efendisi ona, ‹Aferin, iyi ve güvenilir köle!› dedi. ‹Sen küçük işlerde güvenilir olduğunu gösterdin, ben de seni büyük işlerin başına geçireceğim. Gel, efendinin şenliğine katıl!›'),
(2007237,68,40,25,24,'‹‹Sonra bir talant alan geldi, ‹Efendimiz› dedi, ‹Senin sert bir adam olduğunu biliyordum. Ekmediğin yerden biçer, harman savurmadığın yerden devşirirsin.'),
(2007238,68,40,25,25,'Bu nedenle korktum, gidip senin verdiğin talantı toprağa gömdüm. İşte, al paranı!›'),
(2007239,68,40,25,26,'‹‹Efendisi ona şu karşılığı verdi: ‹Kötü ve tembel köle! Ekmediğim yerden biçtiğimi, harman savurmadığım yerden devşirdiğimi bildiğine göre paramı faize vermeliydin. Ben de geldiğimde onu faiziyle geri alırdım...'),
(2007240,68,40,25,28,'Haydi, elindeki talantı alın, on talantı olana verin!'),
(2007241,68,40,25,29,'Çünkü kimde varsa, ona daha çok verilecek ve o bolluk içinde olacak. Ama kimde yoksa, kendisinde olan da elinden alınacak.'),
(2007242,68,40,25,30,'Şu yararsız köleyi dışarıya, karanlığa atın. Orada ağlayış ve diş gıcırtısı olacaktır.› ››'),
(2007243,68,40,25,31,'‹‹İnsanoğlu kendi görkemi içinde bütün melekleriyle birlikte gelince, görkemli tahtına oturacak.'),
(2007244,68,40,25,32,'Ulusların hepsi Onun önünde toplanacak, O da koyunları keçilerden ayıran bir çoban gibi, insanları birbirinden ayıracak.'),
(2007245,68,40,25,33,'Koyunları sağına, keçileri soluna alacak.'),
(2007246,68,40,25,34,'‹‹O zaman Kral, sağındaki kişilere, ‹Sizler, Babamın kutsadıkları, gelin!› diyecek. ‹Dünya kurulduğundan beri sizin için hazırlanmış olan egemenliği miras alın!'),
(2007247,68,40,25,35,'Çünkü acıkmıştım, bana yiyecek verdiniz; susamıştım, bana içecek verdiniz; yabancıydım, beni içeri aldınız.'),
(2007248,68,40,25,36,'Çıplaktım, beni giydirdiniz; hastaydım, benimle ilgilendiniz; zindandaydım, yanıma geldiniz.›'),
(2007249,68,40,25,37,'‹‹O vakit doğru kişiler Ona şu karşılığı verecek: ‹Ya Rab, seni ne zaman aç görüp doyurduk, susuz görüp su verdik?'),
(2007250,68,40,25,38,'Ne zaman seni yabancı görüp içeri aldık, ya da çıplak görüp giydirdik?'),
(2007251,68,40,25,39,'Seni ne zaman hasta ya da zindanda görüp yanına geldik?›'),
(2007252,68,40,25,40,'‹‹Kral da onları şöyle yanıtlayacak: ‹Size doğrusunu söyleyeyim, bu en basit kardeşlerimden biri için yaptığınızı, benim için yapmış oldunuz.›'),
(2007253,68,40,25,41,'‹‹Sonra solundakilere şöyle diyecek: ‹Ey lanetliler, çekilin önümden! İblisle melekleri için hazırlanmış sönmez ateşe gidin!'),
(2007254,68,40,25,42,'Çünkü acıkmıştım, bana yiyecek vermediniz; susamıştım, bana içecek vermediniz; yabancıydım, beni içeri almadınız; çıplaktım, beni giydirmediniz; hastaydım, zindandaydım, benimle ilgilenmediniz.›'),
(2007255,68,40,25,44,'‹‹O vakit onlar da şöyle karşılık verecekler: ‹Ya Rab, seni ne zaman aç, susuz, yabancı, çıplak, hasta ya da zindanda gördük de yardım etmedik?›'),
(2007256,68,40,25,45,'‹‹Kral da onlara şu yanıtı verecek: ‹Size doğrusunu söyleyeyim, mademki bu en basit kardeşlerimden biri için bunu yapmadınız, benim için de yapmamış oldunuz.›'),
(2007257,68,40,25,46,'‹‹Bunlar sonsuz azaba, doğrular ise sonsuz yaşama gidecekler.››'),
(2007258,68,40,26,1,'İsa bütün bunları anlattıktan sonra öğrencilerine, ‹‹İki gün sonra Fısıh Bayramı olduğunu biliyorsunuz›› dedi, ‹‹İnsanoğlu çarmıha gerilmek üzere ele verilecek.››'),
(2007259,68,40,26,3,'Bu sırada başkâhinlerle halkın ileri gelenleri, Kayafa adındaki başkâhinin sarayında toplandılar.'),
(2007260,68,40,26,4,'İsayı hileyle tutuklayıp öldürmek için düzen kurdular.'),
(2007261,68,40,26,5,'Ama, ‹‹Bayramda olmasın ki, halk arasında kargaşalık çıkmasın›› diyorlardı.'),
(2007262,68,40,26,6,'İsa Beytanyada cüzamlı Simunun evindeyken, yanına bir kadın geldi. Kadın kaymaktaşından bir kap içinde çok değerli, güzel kokulu yağ getirmişti. İsa sofrada otururken, kadın yağı Onun başına döktü.'),
(2007263,68,40,26,8,'Öğrenciler bunu görünce kızdılar. ‹‹Nedir bu savurganlık?›› dediler.'),
(2007264,68,40,26,9,'‹‹Bu yağ pahalıya satılabilir, parası yoksullara verilebilirdi.››'),
(2007265,68,40,26,10,'Söylenenleri farkeden İsa, öğrencilerine, ‹‹Kadını neden üzüyorsunuz?›› dedi. ‹‹Benim için güzel bir şey yaptı.'),
(2007266,68,40,26,11,'Yoksullar her zaman aranızdadır, ama ben her zaman aranızda olmayacağım.'),
(2007267,68,40,26,12,'Kadın bu güzel kokulu yağı, beni gömülmeye hazırlamak için bedenimin üzerine boşalttı.'),
(2007268,68,40,26,13,'Size doğrusunu söyleyeyim, bu Müjde dünyanın neresinde duyurulursa, bu kadının yaptığı da onun anılması için anlatılacak.››'),
(2007269,68,40,26,14,'O sırada Onikilerden biri -adı Yahuda İskariot olanı- başkâhinlere giderek, ‹‹Onu ele verirsem bana ne verirsiniz?›› dedi. Otuz gümüş tartıp ona verdiler.'),
(2007270,68,40,26,16,'Yahuda o andan itibaren İsayı ele vermek için fırsat kollamaya başladı.'),
(2007271,68,40,26,17,'Mayasız Ekmek Bayramının ilk günü öğrenciler İsanın yanına gelerek, ‹‹Fısıh yemeğini yemen için nerede hazırlık yapmamızı istersin?›› diye sordular.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007272,68,40,26,18,'İsa onlara, ‹‹Kente varıp o adamın evine gidin›› dedi. ‹‹Ona şöyle deyin: ‹Öğretmen diyor ki, zamanım yaklaştı. Fısıh Bayramını, öğrencilerimle birlikte senin evinde kutlayacağım.› ››'),
(2007273,68,40,26,19,'Öğrenciler, İsanın buyruğunu yerine getirerek Fısıh yemeği için hazırlık yaptılar.'),
(2007274,68,40,26,20,'Akşam olunca İsa on iki öğrencisiyle yemeğe oturdu.'),
(2007275,68,40,26,21,'Yemek yerlerken, ‹‹Size doğrusunu söyleyeyim, sizden biri bana ihanet edecek›› dedi.'),
(2007276,68,40,26,22,'Bu söz onları kedere boğdu. Teker teker, ‹‹Ya Rab, beni demek istemedin ya?›› diye sormaya başladılar.'),
(2007277,68,40,26,23,'O da, ‹‹Bana ihanet edecek olan›› dedi, ‹‹Elindeki ekmeği benimle birlikte sahana batırandır.'),
(2007278,68,40,26,24,'İnsanoğlu, kendisi için yazılmış olduğu gibi gidiyor, ama İnsanoğluna ihanet edenin vay haline! O adam hiç doğmamış olsaydı, kendisi için daha iyi olurdu.››'),
(2007279,68,40,26,25,'Ona ihanet edecek olan Yahuda, ‹‹Rabbî, yoksa beni mi demek istedin?›› diye sordu. İsa ona, ‹‹Söylediğin gibidir›› karşılığını verdi.'),
(2007280,68,40,26,26,'Yemek sırasında İsa eline ekmek aldı, şükredip ekmeği böldü ve öğrencilerine verdi. ‹‹Alın, yiyin›› dedi, ‹‹Bu benim bedenimdir.››'),
(2007281,68,40,26,27,'Sonra bir kâse alıp şükretti ve bunu öğrencilerine vererek, ‹‹Hepiniz bundan için›› dedi.'),
(2007282,68,40,26,28,'‹‹Çünkü bu benim kanımdır, günahların bağışlanması için birçokları uğruna akıtılan antlaşma kanıdır.'),
(2007283,68,40,26,29,'Size şunu söyleyeyim, Babamın egemenliğinde sizinle birlikte tazesini içeceğim o güne dek, asmanın bu ürününden bir daha içmeyeceğim.››'),
(2007284,68,40,26,30,'İlahi söyledikten sonra dışarı çıkıp Zeytin Dağına doğru gittiler.'),
(2007285,68,40,26,31,'Bu arada İsa öğrencilerine, ‹‹Bu gece hepiniz benden ötürü sendeleyip düşeceksiniz›› dedi. ‹‹Çünkü şöyle yazılmıştır: ‹Çobanı vuracağım, Sürüdeki koyunlar darmadağın olacak.›'),
(2007286,68,40,26,32,'Ama ben dirildikten sonra sizden önce Celileye gideceğim.››'),
(2007287,68,40,26,33,'Petrus Ona, ‹‹Herkes senden ötürü sendeleyip düşse de ben asla düşmem›› dedi.'),
(2007288,68,40,26,34,'‹‹Sana doğrusunu söyleyeyim›› dedi İsa, ‹‹Bu gece horoz ötmeden beni üç kez inkâr edeceksin.››'),
(2007289,68,40,26,35,'Petrus, ‹‹Seninle birlikte ölmem gerekse bile seni asla inkâr etmem›› dedi. Öğrencilerin hepsi de aynı şeyi söyledi.'),
(2007290,68,40,26,36,'Sonra İsa öğrencileriyle birlikte Getsemani denen yere geldi. Öğrencilerine, ‹‹Ben şuraya gidip dua edeceğim, siz burada oturun›› dedi.'),
(2007291,68,40,26,37,'Petrus ile Zebedinin iki oğlunu yanına aldı. Kederlenmeye, ağır bir sıkıntı duymaya başlamıştı.'),
(2007292,68,40,26,38,'Onlara, ‹‹Ölesiye kederliyim›› dedi. ‹‹Burada kalın, benimle birlikte uyanık durun.››'),
(2007293,68,40,26,39,'Biraz ilerledi, yüzüstü yere kapanıp dua etmeye başladı. ‹‹Baba›› dedi, ‹‹Mümkünse bu kâse benden uzaklaştırılsın. Yine de benim değil, senin istediğin olsun.››'),
(2007294,68,40,26,40,'Öğrencilerin yanına döndüğünde onları uyumuş buldu. Petrusa, ‹‹Demek ki benimle birlikte bir saat uyanık kalamadınız!›› dedi.'),
(2007295,68,40,26,41,'‹‹Uyanık durup dua edin ki, ayartılmayasınız. Ruh isteklidir, ama beden güçsüzdür.››'),
(2007296,68,40,26,42,'İsa ikinci kez uzaklaşıp dua etti. ‹‹Baba›› dedi, ‹‹Eğer ben içmeden bu kâsenin uzaklaştırılması mümkün değilse, senin istediğin olsun.››'),
(2007297,68,40,26,43,'Geri geldiğinde öğrencilerini yine uyumuş buldu. Onların göz kapaklarına ağırlık çökmüştü.'),
(2007298,68,40,26,44,'Onları bırakıp tekrar uzaklaştı, yine aynı sözlerle üçüncü kez dua etti.'),
(2007299,68,40,26,45,'Sonra öğrencilerin yanına dönerek, ‹‹Hâlâ uyuyor, dinleniyor musunuz?›› dedi. ‹‹İşte saat yaklaştı, İnsanoğlu günahkârların eline veriliyor.'),
(2007300,68,40,26,46,'Kalkın, gidelim. İşte bana ihanet eden geldi!››'),
(2007301,68,40,26,47,'İsa daha konuşurken, Onikilerden biri olan Yahuda geldi. Yanında, başkâhinlerle halkın ileri gelenleri tarafından gönderilmiş kılıçlı sopalı büyük bir kalabalık vardı.'),
(2007302,68,40,26,48,'İsaya ihanet eden Yahuda, ‹‹Kimi öpersem, İsa Odur, Onu tutuklayın›› diye onlarla sözleşmişti.'),
(2007303,68,40,26,49,'Dosdoğru İsaya gidip, ‹‹Selam, Rabbî!›› diyerek Onu öptü.'),
(2007304,68,40,26,50,'İsa, ‹‹Arkadaş, ne yapacaksan yap!›› dedi. Bunun üzerine adamlar yaklaştı, İsayı yakalayıp tutukladılar.'),
(2007305,68,40,26,51,'İsayla birlikte olanlardan biri, ani bir hareketle kılıcını çekti, başkâhinin kölesine vurup kulağını uçurdu.'),
(2007306,68,40,26,52,'O zaman İsa ona, ‹‹Kılıcını yerine koy!›› dedi. ‹‹Kılıç çekenlerin hepsi kılıçla ölecek.'),
(2007307,68,40,26,53,'Yoksa Babamdan yardım isteyemez miyim sanıyorsun? İstesem, hemen şu an bana on iki tümenden fazla melek gönderir.'),
(2007308,68,40,26,54,'Ama böyle olması gerektiğini bildiren Kutsal Yazılar o zaman nasıl yerine gelir?››'),
(2007309,68,40,26,55,'Bundan sonra İsa kalabalığa dönüp şöyle seslendi: ‹‹Niçin bir haydutmuşum gibi beni kılıç ve sopalarla yakalamaya geldiniz? Her gün tapınakta oturup öğretiyordum, beni tutuklamadınız.'),
(2007310,68,40,26,56,'Ama bütün bunlar, peygamberlerin yazdıkları yerine gelsin diye oldu.›› O zaman öğrencilerin hepsi Onu bırakıp kaçtı.'),
(2007311,68,40,26,57,'İsayı tutuklayanlar, Onu başkâhin Kayafaya götürdüler. Din bilginleriyle ileri gelenler de orada toplanmışlardı.'),
(2007312,68,40,26,58,'Petrus, İsayı uzaktan, ta başkâhinin avlusuna kadar izledi. Sonucu görmek için içeri girip nöbetçilerin yanına oturdu.'),
(2007313,68,40,26,59,'Başkâhinlerle Yüksek Kurulun öteki üyeleri, İsayı ölüm cezasına çarptırmak için kendisine karşı yalancı tanıklar arıyorlardı.'),
(2007314,68,40,26,60,'Ortaya birçok yalancı tanık çıktığı halde, aradıklarını bulamadılar. Sonunda ortaya çıkan iki kişi şöyle dedi: ‹‹Bu adam, ‹Ben Tanrının Tapınağını yıkıp üç günde yeniden kurabilirim› dedi.››'),
(2007315,68,40,26,62,'Başkâhin ayağa kalkıp İsaya, ‹‹Hiç yanıt vermeyecek misin?›› dedi. ‹‹Nedir bunların sana karşı ettiği bu tanıklıklar?››'),
(2007316,68,40,26,63,'İsa susmaya devam etti. Başkâhin ise Ona, ‹‹Yaşayan Tanrı adına ant içmeni buyuruyorum, söyle bize, Tanrının Oğlu Mesih sen misin?›› dedi.'),
(2007317,68,40,26,64,'İsa, ‹‹Söylediğin gibidir›› karşılığını verdi. ‹‹Üstelik size şunu söyleyeyim, bundan sonra İnsanoğlunun, Kudretli Olanın sağında oturduğunu ve göğün bulutları üzerinde geldiğini göreceksiniz.››'),
(2007318,68,40,26,65,'Bunun üzerine başkâhin giysilerini yırtarak, ‹‹Tanrıya küfretti!›› dedi. ‹‹Artık tanıklara ne ihtiyacımız var? İşte küfürü işittiniz.'),
(2007319,68,40,26,66,'Buna ne diyorsunuz?›› ‹‹Ölümü hak etti!›› diye karşılık verdiler.'),
(2007320,68,40,26,67,'Bunun üzerine İsanın yüzüne tükürüp Onu yumrukladılar. Bazıları da Onu tokatlayıp, ‹‹Ey Mesih, peygamberliğini göster bakalım, sana vuran kim?›› dediler.'),
(2007321,68,40,26,69,'Petrus ise dışarıda, avluda oturuyordu. Bir hizmetçi kız yanına gelip, ‹‹Sen de Celileli İsayla birlikteydin›› dedi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007322,68,40,26,70,'Ama Petrus bunu herkesin önünde inkâr ederek, ‹‹Neden söz ettiğini anlamıyorum›› dedi.'),
(2007323,68,40,26,71,'Sonra avlu kapısının önüne çıktı. Onu gören başka bir hizmetçi kız orada bulunanlara, ‹‹Bu adam Nasıralı İsayla birlikteydi›› dedi.'),
(2007324,68,40,26,72,'Petrus ant içerek, ‹‹Ben o adamı tanımıyorum›› diye yine inkâr etti.'),
(2007325,68,40,26,73,'Orada duranlar az sonra Petrusa yaklaşıp, ‹‹Gerçekten sen de onlardansın. Konuşman seni ele veriyor›› dediler.'),
(2007326,68,40,26,74,'Petrus kendine lanet okuyup ant içerek, ‹‹O adamı tanımıyorum!›› dedi. Tam o anda horoz öttü.'),
(2007327,68,40,26,75,'Petrus, İsa''nın, ‹‹Horoz ötmeden beni üç kez inkâr edeceksin›› dediğini hatırladı ve dışarı çıkıp acı acı ağladı.'),
(2007328,68,40,27,1,'Sabah olunca bütün başkâhinlerle halkın ileri gelenleri, İsayı ölüm cezasına çarptırmak konusunda anlaştılar.'),
(2007329,68,40,27,2,'Onu bağladılar ve götürüp Vali Pilatusa teslim ettiler.'),
(2007330,68,40,27,3,'İsaya ihanet eden Yahuda, Onun mahkûm edildiğini görünce yaptığına pişman oldu. Otuz gümüşü başkâhinlere ve ileri gelenlere geri götürdü.'),
(2007331,68,40,27,4,'‹‹Ben suçsuz birini ele vermekle günah işledim›› dedi. Onlar ise, ‹‹Bundan bize ne? Onu sen düşün›› dediler.'),
(2007332,68,40,27,5,'Yahuda paraları tapınağın içine fırlatarak oradan ayrıldı, gidip kendini astı.'),
(2007333,68,40,27,6,'Paraları toplayan başkâhinler, ‹‹Kan bedeli olan bu paraları tapınağın hazinesine koymak doğru olmaz›› dediler.'),
(2007334,68,40,27,7,'Kendi aralarında anlaşarak bu parayla yabancılar için mezarlık yapmak üzere Çömlekçi Tarlasını satın aldılar.'),
(2007335,68,40,27,8,'Bunun için bu tarlaya bugüne dek ‹‹Kan Tarlası›› denilmiştir.'),
(2007336,68,40,27,9,'Böylece Peygamber Yeremya aracılığıyla bildirilen şu söz yerine gelmiş oldu: ‹‹İsrailoğullarından kimilerinin Ona biçtikleri değerin karşılığı olan Otuz gümüşü aldılar; Rabbin bana buyurduğu gibi, Çömlekçi Tarlasını satın almak için harcadılar.››'),
(2007337,68,40,27,11,'İsa valinin önüne çıkarıldı. Vali Ona, ‹‹Sen Yahudilerin Kralı mısın?›› diye sordu. İsa, ‹‹Söylediğin gibidir›› dedi.'),
(2007338,68,40,27,12,'Başkâhinlerle ileri gelenler Onu suçlayınca hiç karşılık vermedi.'),
(2007339,68,40,27,13,'Pilatus Ona, ‹‹Senin aleyhinde yaptıkları bunca tanıklığı duymuyor musun?›› dedi.'),
(2007340,68,40,27,14,'İsa tek konuda bile ona yanıt vermedi. Vali buna çok şaştı.'),
(2007341,68,40,27,15,'Her Fısıh Bayramında vali, halkın istediği bir tutukluyu salıvermeyi adet edinmişti.'),
(2007342,68,40,27,16,'O günlerde Barabba adında ünlü bir tutuklu vardı.'),
(2007343,68,40,27,17,'Halk bir araya toplandığında, Pilatus onlara, ‹‹Sizin için kimi salıvermemi istersiniz, Barabbayı mı, Mesih denen İsayı mı?›› diye sordu.'),
(2007344,68,40,27,18,'İsayı kıskançlıktan ötürü kendisine teslim ettiklerini biliyordu.'),
(2007345,68,40,27,19,'Pilatus yargı kürsüsünde otururken karısı ona, ‹‹O doğru adama dokunma. Dün gece rüyamda Onun yüzünden çok sıkıntı çektim›› diye haber gönderdi.'),
(2007346,68,40,27,20,'Başkâhinler ve ileri gelenler ise, Barabbanın salıverilmesini ve İsanın öldürülmesini istesinler diye halkı kışkırttılar.'),
(2007347,68,40,27,21,'Vali onlara şunu sordu: ‹‹Sizin için hangisini salıvermemi istersiniz?›› ‹‹Barabbayı›› dediler.'),
(2007348,68,40,27,22,'Pilatus, ‹‹Öyleyse Mesih denen İsayı ne yapayım?›› diye sordu. Hep bir ağızdan, ‹‹Çarmıha gerilsin!›› dediler.'),
(2007349,68,40,27,23,'Pilatus, ‹‹O ne kötülük yaptı ki?›› diye sordu. Onlar ise daha yüksek sesle, ‹‹Çarmıha gerilsin!›› diye bağrışıp durdular.'),
(2007350,68,40,27,24,'Pilatus, elinden bir şey gelmediğini, tersine, bir kargaşalığın başladığını görünce su aldı, kalabalığın önünde ellerini yıkayıp şöyle dedi: ‹‹Bu adamın kanından ben sorumlu değilim. Bu işe siz bakın!››'),
(2007351,68,40,27,25,'Bütün halk şu karşılığı verdi: ‹‹Onun kanının sorumluluğu bizim ve çocuklarımızın üzerinde olsun!››'),
(2007352,68,40,27,26,'Bunun üzerine Pilatus onlar için Barabbayı salıverdi. İsayı ise kamçılattıktan sonra çarmıha gerilmek üzere askerlere teslim etti.'),
(2007353,68,40,27,27,'Sonra valinin askerleri İsayı vali konağına götürüp bütün taburu başına topladılar.'),
(2007354,68,40,27,28,'Onu soyup üzerine kırmızı bir kaftan geçirdiler.'),
(2007355,68,40,27,29,'Dikenlerden bir taç örüp başına koydular, sağ eline de bir kamış tutturdular. Önünde diz çöküp, ‹‹Selam, ey Yahudilerin Kralı!›› diyerek Onunla alay ettiler.'),
(2007356,68,40,27,30,'Üzerine tükürdüler, kamışı alıp başına vurdular.'),
(2007357,68,40,27,31,'Onunla böyle alay ettikten sonra kaftanı üzerinden çıkarıp kendi giysilerini giydirdiler ve çarmıha germeye götürdüler.'),
(2007358,68,40,27,32,'Dışarı çıktıklarında Simun adında Kireneli bir adama rastladılar. İsanın çarmıhını ona zorla taşıttılar.'),
(2007359,68,40,27,33,'Golgota, yani Kafatası denilen yere vardıklarında içmesi için İsaya ödle karışık şarap verdiler. İsa bunu tadınca içmek istemedi.'),
(2007360,68,40,27,35,'Askerler Onu çarmıha gerdikten sonra kura çekerek giysilerini aralarında paylaştılar.'),
(2007361,68,40,27,36,'Sonra oturup yanında nöbet tuttular.'),
(2007362,68,40,27,37,'Başının üzerine,'),
(2007363,68,40,27,38,'İsayla birlikte, biri sağında öbürü solunda olmak üzere iki haydut da çarmıha gerildi.'),
(2007364,68,40,27,39,'Oradan geçenler başlarını sallayıp İsaya sövüyor, ‹‹Hani sen tapınağı yıkıp üç günde yeniden kuracaktın? Haydi, kurtar kendini! Tanrının Oğluysan çarmıhtan in!›› diyorlardı.'),
(2007365,68,40,27,41,'Başkâhinler, din bilginleri ve ileri gelenler de aynı şekilde Onunla alay ederek, ‹‹Başkalarını kurtardı, kendini kurtaramıyor›› diyorlardı. ‹‹İsrailin Kralı imiş! Şimdi çarmıhtan aşağı insin de Ona iman edelim.'),
(2007366,68,40,27,43,'Tanrıya güveniyordu; Tanrı Onu seviyorsa, kurtarsın bakalım! Çünkü, ‹Ben Tanrının Oğluyum› demişti.››'),
(2007367,68,40,27,44,'İsayla birlikte çarmıha gerilen haydutlar da Ona aynı şekilde hakaret ettiler.'),
(2007368,68,40,27,45,'Öğleyin on ikiden üçe kadar bütün ülkenin üzerine karanlık çöktü.'),
(2007369,68,40,27,46,'Saat üçe doğru İsa yüksek sesle, ‹‹Eli, Eli, lema şevaktani?›› yani, ‹‹Tanrım, Tanrım, beni neden terk ettin?›› diye bağırdı.'),
(2007370,68,40,27,47,'Orada duranlardan bazıları bunu işitince, ‹‹Bu adam İlyası çağırıyor›› dediler.'),
(2007371,68,40,27,48,'İçlerinden biri hemen koşup bir sünger getirdi, ekşi şaraba batırıp bir kamışın ucuna takarak İsaya içirdi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007372,68,40,27,49,'Öbürleri ise, ‹‹Dur bakalım, İlyas gelip Onu kurtaracak mı?›› dediler.'),
(2007373,68,40,27,50,'İsa, yüksek sesle bir kez daha bağırdı ve ruhunu teslim etti.'),
(2007374,68,40,27,51,'O anda tapınaktaki perde yukarıdan aşağıya yırtılarak ikiye bölündü. Yer sarsıldı, kayalar yarıldı.'),
(2007375,68,40,27,52,'Mezarlar açıldı, ölmüş olan birçok kutsal kişinin cesetleri dirildi.'),
(2007376,68,40,27,53,'Bunlar mezarlarından çıkıp İsanın dirilişinden sonra kutsal kente girdiler ve birçok kimseye göründüler.'),
(2007377,68,40,27,54,'İsayı bekleyen yüzbaşı ve beraberindeki askerler, depremi ve öbür olayları görünce dehşete kapıldılar, ‹‹Bu gerçekten Tanrının Oğluydu!›› dediler.'),
(2007378,68,40,27,55,'Orada, olup bitenleri uzaktan izleyen birçok kadın vardı. Bunlar, Celileden İsanın ardından gelip Ona hizmet etmişlerdi.'),
(2007379,68,40,27,56,'Aralarında Mecdelli Meryem, Yakup ile Yusufun annesi Meryem ve Zebedi oğullarının annesi de vardı.'),
(2007380,68,40,27,57,'Akşama doğru Yusuf adında zengin bir Aramatyalı geldi. O da İsanın bir öğrencisiydi.'),
(2007381,68,40,27,58,'Pilatusa gidip İsanın cesedini istedi. Pilatus da cesedin ona verilmesini buyurdu.'),
(2007382,68,40,27,59,'Yusuf cesedi aldı, temiz keten beze sardı, kayaya oydurduğu kendi yeni mezarına yatırdı. Mezarın girişine büyük bir taş yuvarlayıp oradan ayrıldı.'),
(2007383,68,40,27,61,'Mecdelli Meryem ile öteki Meryem ise orada, mezarın karşısında oturuyorlardı.'),
(2007384,68,40,27,62,'Ertesi gün, yani Hazırlık Gününden sonraki gün, başkâhinlerle Ferisiler Pilatusun önünde toplanarak, ‹‹Efendimiz›› dediler, ‹‹O aldatıcının, daha yaşarken, ‹Ben öldükten üç gün sonra dirileceğim› dediğini hatırlıyoruz.'),
(2007385,68,40,27,64,'Onun için buyruk ver de üçüncü güne dek mezarı güvenlik altına alsınlar. Yoksa öğrencileri gelir, cesedini çalar ve halka, ‹Ölümden dirildi› derler. Son aldatmaca ilkinden beter olur.››'),
(2007386,68,40,27,65,'Pilatus onlara, ‹‹Yanınıza asker alın, gidip mezarı dilediğiniz gibi güvenlik altına alın›› dedi.'),
(2007387,68,40,27,66,'Onlar da askerlerle birlikte gittiler, taşı mühürleyip mezarı güvenlik altına aldılar.'),
(2007388,68,40,28,1,'Şabat Gününü izleyen haftanın ilk günü, tan yeri ağarırken, Mecdelli Meryem ile öbür Meryem mezarı görmeye gittiler.'),
(2007389,68,40,28,2,'Ansızın büyük bir deprem oldu. Rabbin bir meleği gökten indi ve mezara gidip taşı bir yana yuvarlayarak üzerine oturdu.'),
(2007390,68,40,28,3,'Görünüşü şimşek gibi, giysileri ise kar gibi bembeyazdı.'),
(2007391,68,40,28,4,'Nöbetçiler korkudan titremeye başladılar, sonra ölü gibi yere yıkıldılar.'),
(2007392,68,40,28,5,'Melek kadınlara şöyle seslendi: ‹‹Korkmayın! Çarmıha gerilen İsayı aradığınızı biliyorum.'),
(2007393,68,40,28,6,'O burada yok; söylemiş olduğu gibi dirildi. Gelin, Onun yattığı yeri görün.'),
(2007394,68,40,28,7,'Çabuk gidin, öğrencilerine şöyle deyin: ‹İsa ölümden dirildi. Sizden önce Celileye gidiyor, kendisini orada göreceksiniz.› İşte ben size söylemiş bulunuyorum.››'),
(2007395,68,40,28,8,'Kadınlar korku ve büyük sevinç içinde hemen mezardan uzaklaştılar; koşarak İsanın öğrencilerine haber vermeye gittiler.'),
(2007396,68,40,28,9,'İsa ansızın karşılarına çıktı, ‹‹Selam!›› dedi. Yaklaşıp İsanın ayaklarına sarılarak Ona tapındılar.'),
(2007397,68,40,28,10,'O zaman İsa, ‹‹Korkmayın!›› dedi. ‹‹Gidip kardeşlerime haber verin, Celileye gitsinler, beni orada görecekler.››'),
(2007398,68,40,28,11,'Kadınlar daha yoldayken nöbetçi askerlerden bazıları kente giderek olup bitenleri başkâhinlere bildirdiler.'),
(2007399,68,40,28,12,'Başkâhinler ileri gelenlerle birlikte toplanıp birbirlerine danıştıktan sonra askerlere yüklü para vererek dediler ki, ‹‹Siz şöyle diyeceksiniz: ‹Öğrencileri geceleyin geldi, biz uyurken Onun cesedini çalıp götürdüler.›'),
(2007400,68,40,28,14,'Eğer bu haber valinin kulağına gidecek olursa biz onu yatıştırır, size bir zarar gelmesini önleriz.››'),
(2007401,68,40,28,15,'Böylece askerler parayı aldılar ve kendilerine söylendiği gibi yaptılar. Bu söylenti Yahudiler arasında bugün de yaygındır.'),
(2007402,68,40,28,16,'On bir öğrenci Celileye, İsanın kendilerine bildirdiği dağa gittiler.'),
(2007403,68,40,28,17,'İsayı gördükleri zaman Ona tapındılar. Ama bazıları kuşku içindeydi.'),
(2007404,68,40,28,18,'İsa yanlarına gelip kendilerine şunları söyledi: ‹‹Gökte ve yeryüzünde bütün yetki bana verildi.'),
(2007405,68,40,28,19,'Bu nedenle gidin, bütün ulusları öğrencilerim olarak yetiştirin; onları Baba, Oğul ve Kutsal Ruhun adıyla vaftiz edin;'),
(2007406,68,40,28,20,'size buyurduğum her şeye uymayı onlara öğretin. İşte ben, dünyanın sonuna dek her an sizinle birlikteyim.››'),
(2007407,68,41,1,1,'Tanrının Oğlu İsa Mesihle ilgili Müjdenin başlangıcı.'),
(2007408,68,41,1,2,'Peygamber Yeşayanın Kitabında şöyle yazılmıştır: ‹‹İşte, habercimi senin önünden gönderiyorum; O senin yolunu hazırlayacak.››'),
(2007409,68,41,1,3,'‹‹Çölde haykıran, ‹Rabbin yolunu hazırlayın, Geçeceği patikaları düzleyin› diye sesleniyor.››'),
(2007410,68,41,1,4,'Böylece Vaftizci Yahya çölde ortaya çıktı. İnsanları, günahlarının bağışlanması için tövbe edip vaftiz olmaya çağırıyordu.'),
(2007411,68,41,1,5,'Bütün Yahudiye halkı ve Yeruşalimlilerin hepsi ona geliyor, günahlarını itiraf ediyor, onun tarafından Şeria Irmağında vaftiz ediliyordu.'),
(2007412,68,41,1,6,'Yahyanın deve tüyünden giysisi, belinde deri kuşağı vardı. Çekirge ve yaban balı yerdi.'),
(2007413,68,41,1,7,'Şu haberi yayıyordu: ‹‹Benden sonra benden daha güçlü olan geliyor. Eğilip Onun çarıklarının bağını çözmeye bile layık değilim.'),
(2007414,68,41,1,8,'Ben sizi suyla vaftiz ettim, ama O sizi Kutsal Ruhla vaftiz edecektir.››'),
(2007415,68,41,1,9,'O günlerde Celilenin Nasıra Kentinden çıkıp gelen İsa, Yahya tarafından Şeria Irmağında vaftiz edildi.'),
(2007416,68,41,1,10,'Tam sudan çıkarken, göklerin yarıldığını ve Ruhun güvercin gibi üzerine indiğini gördü.'),
(2007417,68,41,1,11,'Göklerden, ‹‹Sen benim sevgili Oğlumsun, senden hoşnudum›› diyen bir ses duyuldu.'),
(2007418,68,41,1,12,'O an Ruh, İsayı çöle gönderdi.'),
(2007419,68,41,1,13,'İsa çölde kaldığı kırk gün boyunca Şeytan tarafından denendi. Yabanıl hayvanlar arasındaydı, melekler Ona hizmet ediyordu.'),
(2007420,68,41,1,14,'Yahyanın tutuklanmasından sonra İsa, Tanrının Müjdesini duyura duyura Celileye gitti.'),
(2007421,68,41,1,15,'‹‹Zaman doldu›› diyordu, ‹‹Tanrının Egemenliği yaklaştı. Tövbe edin, Müjdeye inanın!››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007422,68,41,1,16,'İsa, Celile Gölünün kıyısından geçerken, göle ağ atmakta olan Simun ile kardeşi Andreası gördü. Bu adamlar balıkçıydı.'),
(2007423,68,41,1,17,'İsa onlara, ‹‹Ardımdan gelin›› dedi, ‹‹Sizleri insan tutan balıkçılar yapacağım.››'),
(2007424,68,41,1,18,'Onlar da hemen ağlarını bırakıp Onun ardından gittiler.'),
(2007425,68,41,1,19,'İsa biraz ileri gidince Zebedinin oğulları Yakupla Yuhannayı gördü. Teknede ağlarını onarıyorlardı.'),
(2007426,68,41,1,20,'Hemen onları çağırdı. Onlar da babaları Zebediyi işçilerle birlikte teknede bırakıp İsanın ardından gittiler.'),
(2007427,68,41,1,21,'Kefarnahuma girdiler. Şabat Günü İsa havraya gidip öğretmeye başladı.'),
(2007428,68,41,1,22,'Halk Onun öğretişine şaşıp kaldı. Çünkü onlara din bilginleri gibi değil, yetkili biri gibi öğretiyordu.'),
(2007429,68,41,1,23,'Tam o sırada havrada bulunan ve kötü ruha tutulmuş bir adam, ‹‹Ey Nasıralı İsa, bizden ne istiyorsun?›› diye bağırdı. ‹‹Bizi mahvetmeye mi geldin? Senin kim olduğunu biliyorum, Tanrının Kutsalısın sen!››'),
(2007430,68,41,1,25,'İsa, ‹‹Sus, çık adamdan!›› diyerek kötü ruhu azarladı.'),
(2007431,68,41,1,26,'Kötü ruh adamı sarstı ve büyük bir çığlık atarak içinden çıktı.'),
(2007432,68,41,1,27,'Herkes şaşıp kaldı. Birbirlerine, ‹‹Bu nasıl şey?›› diye sormaya başladılar. ‹‹Yepyeni bir öğreti! Kötü ruhlara bile yetkiyle buyruk veriyor, onlar da sözünü dinliyor.››'),
(2007433,68,41,1,28,'Böylece İsayla ilgili haber, Celile bölgesinin her yerine hızla yayıldı.'),
(2007434,68,41,1,29,'İsa havradan çıkar çıkmaz, Yakup ve Yuhanna ile birlikte Simun ve Andreasın evine gitti.'),
(2007435,68,41,1,30,'Simunun kaynanası ateşler içinde yatıyordu. Durumu hemen İsaya bildirdiler.'),
(2007436,68,41,1,31,'O da hastaya yaklaştı, elinden tutup kaldırdı. Kadının ateşi düştü, onlara hizmet etmeye başladı.'),
(2007437,68,41,1,32,'Akşam olup güneş batınca, bütün hastaları ve cinlileri İsaya getirdiler.'),
(2007438,68,41,1,33,'Bütün kent halkı kapıya toplanmıştı.'),
(2007439,68,41,1,34,'İsa, çeşitli hastalıklara yakalanmış birçok kişiyi iyileştirdi, birçok cini kovdu. Cinlerin konuşmasına izin vermiyordu. Çünkü onlar kendisinin kim olduğunu biliyorlardı.'),
(2007440,68,41,1,35,'Sabah çok erkenden, ortalık henüz ağarmadan İsa kalktı, evden çıkıp ıssız bir yere gitti, orada dua etmeye başladı.'),
(2007441,68,41,1,36,'Simun ile yanındakiler İsayı aramaya çıktılar.'),
(2007442,68,41,1,37,'Onu bulunca, ‹‹Herkes seni arıyor!›› dediler.'),
(2007443,68,41,1,38,'İsa onlara, ‹‹Başka yerlere, yakın kasabalara gidelim›› dedi. ‹‹Oralarda da Tanrı sözünü duyurayım. Bunun için çıkıp geldim.››'),
(2007444,68,41,1,39,'Böylece havralarında Tanrı sözünü duyurarak ve cinleri kovarak bütün Celile bölgesini dolaştı.'),
(2007445,68,41,1,40,'İsaya cüzamlı biri geldi, diz çökerek, ‹‹İstersen beni temiz kılabilirsin›› diye yalvardı.'),
(2007446,68,41,1,41,'İsanın yüreği sızladı, elini uzatıp adama dokundu, ‹‹İsterim, temiz ol!›› dedi.'),
(2007447,68,41,1,42,'Adam anında cüzamdan kurtulup tertemiz oldu.'),
(2007448,68,41,1,43,'İsa onu sıkıca uyararak hemen yanından uzaklaştırdı.'),
(2007449,68,41,1,44,'‹‹Sakın kimseye bir şey söyleme!›› dedi. ‹‹Git, kâhine görün ve cüzamdan temizlendiğini herkese kanıtlamak için Musanın buyurduğu sunuları sun.››'),
(2007450,68,41,1,45,'Ne var ki, adam çıkıp gitti, olayla ilgili haberi her tarafa yayıp duyurmaya başladı. Öyle ki, İsa artık hiçbir kente açıkça giremez oldu. Ancak dışarıda, ıssız yerlerde kalıyordu. Ve halk her yerden O''na akın ediyordu.'),
(2007451,68,41,2,1,'Birkaç gün sonra İsa tekrar Kefarnahuma geldiğinde, evde olduğu duyuldu.'),
(2007452,68,41,2,2,'O kadar çok insan toplandı ki, artık kapının önünde bile duracak yer kalmamıştı. İsa onlara Tanrı sözünü anlatıyordu.'),
(2007453,68,41,2,3,'Bu arada Ona dört kişinin taşıdığı felçli bir adamı getirdiler.'),
(2007454,68,41,2,4,'Kalabalıktan Ona yaklaşamadıkları için, bulunduğu yerin üzerindeki damı delip açarak felçliyi üstünde yattığı şilteyle birlikte aşağı indirdiler.'),
(2007455,68,41,2,5,'İsa onların imanını görünce felçliye, ‹‹Oğlum, günahların bağışlandı›› dedi.'),
(2007456,68,41,2,6,'Orada oturan bazı din bilginleri ise içlerinden şöyle düşündüler: ‹‹Bu adam neden böyle konuşuyor? Tanrıya küfrediyor! Tanrıdan başka kim günahları bağışlayabilir?››'),
(2007457,68,41,2,8,'Akıllarından geçeni hemen ruhunda sezen İsa onlara, ‹‹Aklınızdan neden böyle şeyler geçiriyorsunuz?›› dedi.'),
(2007458,68,41,2,9,'‹‹Hangisi daha kolay, felçliye, ‹Günahların bağışlandı› demek mi, yoksa, ‹Kalk, şilteni topla, yürü› demek mi?'),
(2007459,68,41,2,10,'Ne var ki, İnsanoğlunun yeryüzünde günahları bağışlama yetkisine sahip olduğunu bilesiniz diye...›› Sonra felçliye, ‹‹Sana söylüyorum, kalk, şilteni topla, evine git!›› dedi.'),
(2007460,68,41,2,12,'Adam kalktı, hemen şiltesini topladı, hepsinin gözü önünde çıkıp gitti. Herkes şaşakalmıştı. Tanrıyı övüyorlar, ‹‹Böylesini hiç görmemiştik›› diyorlardı.'),
(2007461,68,41,2,13,'İsa yine çıkıp göl kıyısına gitti. Bütün halk yanına geldi, O da onlara öğretmeye başladı.'),
(2007462,68,41,2,14,'Yoldan geçerken, vergi toplama yerinde oturan Alfay oğlu Leviyi gördü. Ona, ‹‹Ardımdan gel›› dedi. Levi de kalkıp İsanın ardından gitti.'),
(2007463,68,41,2,15,'Sonra İsa, Levinin evinde yemek yerken, birçok vergi görevlisiyle günahkâr Onunla ve öğrencileriyle birlikte sofraya oturmuştu. Onu izleyen böyle birçok kişi vardı.'),
(2007464,68,41,2,16,'Ferisilerden bazı din bilginleri, Onu günahkârlar ve vergi görevlileriyle birlikte yemekte görünce öğrencilerine, ‹‹Niçin vergi görevlileri ve günahkârlarla birlikte yemek yiyor?›› diye sordular.'),
(2007465,68,41,2,17,'Bunu duyan İsa onlara, ‹‹Sağlamların değil, hastaların hekime ihtiyacı var›› dedi. ‹‹Ben doğru kişileri değil, günahkârları çağırmaya geldim.››'),
(2007466,68,41,2,18,'Yahyanın öğrencileriyle Ferisiler oruç tutarken, bazı kişiler İsaya gelip, ‹‹Yahyanın ve Ferisilerin öğrencileri oruç tutuyor da senin öğrencilerin neden tutmuyor?›› diye sordular.'),
(2007467,68,41,2,19,'İsa şöyle karşılık verdi: ‹‹Güvey aralarında olduğu sürece davetliler oruç tutar mı? Güvey aralarında oldukça oruç tutmazlar!'),
(2007468,68,41,2,20,'Ama güveyin aralarından alınacağı günler gelecek, onlar işte o zaman, o gün oruç tutacaklar.'),
(2007469,68,41,2,21,'Hiç kimse eski giysiyi yeni kumaş parçasıyla yamamaz. Yoksa yeni yama çeker, eski giysiden kopar, yırtık daha beter olur.'),
(2007470,68,41,2,22,'Hiç kimse yeni şarabı eski tulumlara doldurmaz. Yoksa şarap tulumları patlatır, şarap da tulumlar da mahvolur. Yeni şarap yeni tulumlara doldurulur.››'),
(2007471,68,41,2,23,'Bir Şabat Günü İsa ekinler arasından geçiyordu. Öğrencileri yolda giderken başakları koparmaya başladılar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007472,68,41,2,24,'Ferisiler İsaya, ‹‹Bak, Şabat Günü yasak olanı neden yapıyorlar?›› dediler.'),
(2007473,68,41,2,25,'İsa onlara, ‹‹Davutla yanındakiler aç ve muhtaç kalınca Davutun ne yaptığını hiç okumadınız mı?›› diye sordu.'),
(2007474,68,41,2,26,'‹‹Başkâhin Aviyatarın zamanında Davut, Tanrının evine girdi, kâhinlerden başkasının yemesi yasak olan adak ekmeklerini yedi ve yanındakilere de verdi.››'),
(2007475,68,41,2,27,'Sonra onlara, ‹‹İnsan Şabat Günü için değil, Şabat Günü insan için yaratıldı›› dedi.'),
(2007476,68,41,2,28,'‹‹Bu nedenle İnsanoğlu Şabat Günü''nün de Rabbi''dir.››'),
(2007477,68,41,3,1,'İsa yine havraya girdi. Orada eli sakat bir adam vardı.'),
(2007478,68,41,3,2,'Bazıları İsayı suçlamak amacıyla, Şabat Günü hastayı iyileştirecek mi diye Onu gözlüyorlardı.'),
(2007479,68,41,3,3,'İsa, eli sakat adama, ‹‹Kalk, öne çık!›› dedi.'),
(2007480,68,41,3,4,'Sonra havradakilere, ‹‹Kutsal Yasaya göre Şabat Günü iyilik yapmak mı doğru, kötülük yapmak mı? Can kurtarmak mı doğru, can almak mı?›› diye sordu. Onlardan ses çıkmadı.'),
(2007481,68,41,3,5,'İsa, çevresindekilere öfkeyle baktı. Yüreklerinin duygusuzluğu Onu kederlendirmişti. Adama, ‹‹Elini uzat!›› dedi. Adam elini uzattı, eli yine sapasağlam oluverdi.'),
(2007482,68,41,3,6,'Bunun üzerine Ferisiler dışarı çıktılar, İsayı yok etmek için Hirodes yanlılarıyla hemen görüşmeye başladılar.'),
(2007483,68,41,3,7,'İsa, öğrencileriyle birlikte göl kıyısına çekildi. Celileden büyük bir kalabalık Onun ardından geldi. Ayrıca, bütün yaptıklarını duyan büyük kalabalıklar Yahudiyeden, Yeruşalimden, İdumeyadan, Şeria Irmağının karşı yakasından, Sur ve Sayda bölgelerinden kendisine akın etti.'),
(2007484,68,41,3,9,'İsa, kalabalığın arasında sıkışıp kalmamak için öğrencilerine bir kayık hazır bulundurmalarını söyledi.'),
(2007485,68,41,3,10,'Birçoklarını iyileştirmiş olduğundan, çeşitli hastalıklara yakalananlar Ona dokunmak için üzerine üşüşüyordu.'),
(2007486,68,41,3,11,'Kötü ruhlar Onu görünce ayaklarına kapanıyor, ‹‹Sen Tanrının Oğlusun!›› diye bağırıyorlardı.'),
(2007487,68,41,3,12,'Ama İsa, kim olduğunu açıklamamaları için onları sıkı sıkıya uyardı.'),
(2007488,68,41,3,13,'İsa, dağa çıkarak istediği kişileri yanına çağırdı. Onlar da yanına gittiler.'),
(2007489,68,41,3,14,'İsa bunlardan on iki kişiyi yanında bulundurmak, Tanrı sözünü duyurmaya göndermek ve cinleri kovmaya yetkili kılmak üzere seçti. Seçtiği bu on iki kişi şunlardır: Petrus adını verdiği Simun, Beni-Regeş, yani Gökgürültüsü Oğulları adını verdiği Zebedinin oğulları Yakup ve Yuhanna, Andreas, Filipus, Bartalmay, Matta, Tomas, Alfay oğlu Yakup, Taday, Yurtsever Simun ve İsaya ihanet eden Yahuda İskariot.'),
(2007490,68,41,3,20,'İsa bundan sonra eve gitti. Yine öyle büyük bir kalabalık toplandı ki, İsayla öğrencileri yemek bile yiyemediler.'),
(2007491,68,41,3,21,'Yakınları bunu duyunca, ‹‹Aklını kaçırmış›› diyerek Onu almaya geldiler.'),
(2007492,68,41,3,22,'Yeruşalimden gelen din bilginleri ise, ‹‹Baalzevul Onun içine girmiş›› ve ‹‹Cinleri, cinlerin önderinin gücüyle kovuyor›› diyorlardı.'),
(2007493,68,41,3,23,'Bunun üzerine İsa din bilginlerini yanına çağırıp onlara benzetmelerle seslendi. ‹‹Şeytan, Şeytanı nasıl kovabilir?›› dedi.'),
(2007494,68,41,3,24,'‹‹Bir ülke kendi içinde bölünmüşse, ayakta kalamaz.'),
(2007495,68,41,3,25,'Bir ev kendi içinde bölünmüşse, ayakta kalamaz.'),
(2007496,68,41,3,26,'Şeytan da kendine karşı gelip kendi içinde bölünmüşse, artık ayakta kalamaz; sonu gelmiş demektir.'),
(2007497,68,41,3,27,'Hiç kimse güçlü adamın evine girip malını çalamaz. Ancak onu bağladıktan sonra evini soyabilir.'),
(2007498,68,41,3,28,'Size doğrusunu söyleyeyim, insanların işlediği her günah, ettiği her küfür bağışlanacak, ama Kutsal Ruha küfreden asla bağışlanmayacak. Bunu yapan, asla silinmeyecek bir günah işlemiş olur.››'),
(2007499,68,41,3,30,'İsa bu sözleri, ‹‹Onda kötü ruh var›› dedikleri için söyledi.'),
(2007500,68,41,3,31,'Daha sonra İsanın annesiyle kardeşleri geldi. Dışarıda durdular, haber gönderip Onu çağırdılar.'),
(2007501,68,41,3,32,'İsanın çevresinde oturan kalabalıktan bazıları, ‹‹Bak›› dediler, ‹‹Annenle kardeşlerin dışarıda, seni istiyorlar.››'),
(2007502,68,41,3,33,'İsa buna karşılık onlara, ‹‹Kimdir annem ve kardeşlerim?›› dedi.'),
(2007503,68,41,3,34,'Sonra çevresinde oturanlara bakıp şöyle dedi: ‹‹İşte annem, işte kardeşlerim!'),
(2007504,68,41,3,35,'Tanrı''nın isteğini kim yerine getirirse, kardeşim, kızkardeşim ve annem odur.››'),
(2007505,68,41,4,1,'İsa göl kıyısında halka yine öğretmeye başladı. Çevresinde çok büyük bir kalabalık toplandı. Bu yüzden İsa göldeki bir tekneye binip oturdu. Bütün kalabalık göl kıyısında duruyordu.'),
(2007506,68,41,4,2,'İsa onlara benzetmelerle birçok şey öğretiyordu. Öğretirken, ‹‹Şunu dinleyin›› dedi. ‹‹Ekincinin biri tohum ekmeye çıktı.'),
(2007507,68,41,4,4,'Ektiği tohumlardan kimi yol kenarına düştü. Kuşlar gelip bunları yedi.'),
(2007508,68,41,4,5,'Kimi, toprağı az kayalık yerlere düştü. Toprak derin olmadığından hemen filizlendi.'),
(2007509,68,41,4,6,'Ne var ki, güneş doğunca kavruldular, kök salamadıkları için kuruyup gittiler.'),
(2007510,68,41,4,7,'Kimi, dikenler arasına düştü. Dikenler büyüdü, filizleri boğdu ve filizler ürün vermedi.'),
(2007511,68,41,4,8,'Kimi ise iyi toprağa düştü, büyüyüp çoğaldı, ürün verdi. Bazısı otuz, bazısı altmış, bazısı da yüz kat ürün verdi.››'),
(2007512,68,41,4,9,'Sonra İsa şunu ekledi: ‹‹İşitecek kulağı olan işitsin!››'),
(2007513,68,41,4,10,'Onikilerle öbür izleyicileri İsayla yalnız kalınca, kendisinden benzetmelerin anlamını sordular.'),
(2007514,68,41,4,11,'O da onlara şöyle dedi: ‹‹Tanrının Egemenliğinin sırrı sizlere açıklandı, ama dışarıda olanlara her şey benzetmelerle anlatılır.'),
(2007515,68,41,4,12,'Öyle ki, ‹Bakıp bakıp görmesinler, Duyup duyup anlamasınlar da, Dönüp bağışlanmasınlar.› ››'),
(2007516,68,41,4,13,'İsa sonra onlara, ‹‹Siz bu benzetmeyi anlamıyor musunuz?›› dedi. ‹‹Öyleyse bütün benzetmeleri nasıl anlayacaksınız?'),
(2007517,68,41,4,14,'Ekincinin ektiği, Tanrı sözüdür.'),
(2007518,68,41,4,15,'Bazı insanlar sözün ekildiği yerde yol kenarına düşen tohumlara benzer. Bunlar sözü işitir işitmez, Şeytan gelir, yüreklerine ekilen sözü alır götürür.'),
(2007519,68,41,4,16,'Kayalık yerlere ekilenler ise, işittikleri sözü hemen sevinçle kabul eden, ama kök salamadıkları için ancak bir süre dayanan kişilerdir. Böyleleri Tanrı sözünden ötürü sıkıntı ya da zulme uğrayınca hemen sendeleyip düşerler.'),
(2007520,68,41,4,18,'Yine bazıları dikenler arasında ekilen tohumlara benzerler. Bunlar sözü işitirler, ama dünyasal kaygılar, zenginliğin aldatıcılığı ve daha başka hevesler araya girip sözü boğar ve ürün vermesini engeller.'),
(2007521,68,41,4,20,'İyi toprağa ekilenler ise, sözü işiten, onu benimseyen, kimi otuz, kimi altmış, kimi de yüz kat ürün veren kişilerdir.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007522,68,41,4,21,'Onlara, ‹‹Kandili, tahıl ölçeğinin ya da yatağın altına koymak için mi getirirler?›› dedi. ‹‹Kandilliğe koymak için değil mi?'),
(2007523,68,41,4,22,'Gizli olan ne varsa, açığa çıkarılmak üzere gizlenmiştir; saklı olan ne varsa, aydınlığa çıkmak üzere saklanmıştır.'),
(2007524,68,41,4,23,'İşitecek kulağı olan işitsin!››'),
(2007525,68,41,4,24,'İsa şöyle devam etti: ‹‹İşittiklerinize dikkat edin! Hangi ölçekle verirseniz, aynı ölçekle alacaksınız. Hatta size daha fazlası verilecek.'),
(2007526,68,41,4,25,'Çünkü kimde varsa, ona daha çok verilecek. Ama kimde yoksa, elindeki de alınacak.››'),
(2007527,68,41,4,26,'Sonra İsa şöyle dedi: ‹‹Tanrının Egemenliği, toprağa tohum saçan adama benzer.'),
(2007528,68,41,4,27,'Gece olur, uyur; gündüz olur, kalkar. Kendisi nasıl olduğunu bilmez ama, tohum filizlenir, gelişir.'),
(2007529,68,41,4,28,'Toprak kendiliğinden ürün verir. Önce filizi, sonra başağı, sonunda da başağı dolduran taneleri verir.'),
(2007530,68,41,4,29,'Ürün olgunlaşınca, adam hemen orağı vurur. Çünkü biçim vakti gelmiştir.››'),
(2007531,68,41,4,30,'İsa sonra şöyle dedi: ‹‹Tanrının Egemenliğini neye benzetelim, nasıl bir benzetmeyle anlatalım?'),
(2007532,68,41,4,31,'Tanrının Egemenliği, hardal tanesine benzer. Hardal, yeryüzünde toprağa ekilen tohumların en küçüğü olmakla birlikte, ekildikten sonra gelişir, bütün bahçe bitkilerinin boyunu aşar. Öylesine dal budak salar ki, kuşlar gölgesinde barınabilir.››'),
(2007533,68,41,4,33,'İsa, Tanrı sözünü, buna benzer birçok benzetmeyle halkın anlayabildiği ölçüde anlatırdı.'),
(2007534,68,41,4,34,'Benzetme kullanmadan onlara hiçbir şey anlatmazdı. Ama kendi öğrencileriyle yalnız kaldığında, onlara her şeyi açıklardı.'),
(2007535,68,41,4,35,'O gün akşam olunca öğrencilerine, ‹‹Karşı yakaya geçelim›› dedi.'),
(2007536,68,41,4,36,'Öğrenciler kalabalığı geride bırakarak İsayı, içinde bulunduğu tekneyle götürdüler. Yanında başka tekneler de vardı.'),
(2007537,68,41,4,37,'Bu sırada büyük bir fırtına koptu. Dalgalar tekneye öyle bindirdi ki, tekne neredeyse suyla dolmuştu.'),
(2007538,68,41,4,38,'İsa, teknenin kıç tarafında bir yastığa yaslanmış uyuyordu. Öğrenciler Onu uyandırıp, ‹‹Öğretmenimiz, öleceğiz! Hiç aldırmıyor musun?›› dediler.'),
(2007539,68,41,4,39,'İsa kalkıp rüzgarı azarladı, göle, ‹‹Sus, sakin ol!›› dedi. Rüzgar dindi, ortalık sütliman oldu.'),
(2007540,68,41,4,40,'İsa öğrencilerine, ‹‹Neden korkuyorsunuz? Hâlâ imanınız yok mu?›› dedi.'),
(2007541,68,41,4,41,'Onlar ise büyük korku içinde birbirlerine, ‹‹Bu adam kim ki, rüzgar da göl de O''nun sözünü dinliyor?›› dediler.'),
(2007542,68,41,5,1,'Gölün karşı yakasına, Gerasalıların memleketine vardılar.'),
(2007543,68,41,5,2,'İsa tekneden iner inmez, kötü ruha tutulmuş bir adam mezarlık mağaralardan çıkıp Onu karşıladı.'),
(2007544,68,41,5,3,'Mezarların içinde yaşayan bu adamı artık kimse zincirle bile bağlı tutamıyordu.'),
(2007545,68,41,5,4,'Birçok kez zincir ve kösteklerle bağlandığı halde, zincirleri koparmış, köstekleri parçalamıştı. Hiç kimse onunla başa çıkamıyordu.'),
(2007546,68,41,5,5,'Gece gündüz mezarlarda, dağlarda bağırıp duruyor, kendini taşlarla yaralıyordu.'),
(2007547,68,41,5,6,'Uzaktan İsayı görünce koşup geldi, Onun önünde yere kapandı.'),
(2007548,68,41,5,7,'Yüksek sesle haykırarak, ‹‹Ey İsa, yüce Tanrının Oğlu, benden ne istiyorsun? Tanrı hakkı için sana yalvarırım, bana işkence etme!›› dedi.'),
(2007549,68,41,5,8,'Çünkü İsa, ‹‹Ey kötü ruh, adamın içinden çık!›› demişti.'),
(2007550,68,41,5,9,'Sonra İsa adama, ‹‹Adın ne?›› diye sordu. ‹‹Adım Tümen. Çünkü sayımız çok›› dedi.'),
(2007551,68,41,5,10,'Ruhları o bölgeden çıkarmaması için İsaya yalvarıp yakardı.'),
(2007552,68,41,5,11,'Orada, dağın yamacında otlayan büyük bir domuz sürüsü vardı.'),
(2007553,68,41,5,12,'Kötü ruhlar İsaya, ‹‹Bizi şu domuzlara gönder, onlara girelim›› diye yalvardılar.'),
(2007554,68,41,5,13,'İsanın izin vermesi üzerine kötü ruhlar adamdan çıkıp domuzların içine girdiler. Yaklaşık iki bin domuzdan oluşan sürü, dik yamaçtan aşağı koşuşarak göle atlayıp boğuldu.'),
(2007555,68,41,5,14,'Domuzları güdenler kaçıp kentte ve köylerde olayın haberini yaydılar. Halk olup biteni görmeye çıktı.'),
(2007556,68,41,5,15,'İsanın yanına geldiklerinde, önceleri bir tümen cine tutulan adamı giyinmiş, aklı başına gelmiş, oturmuş görünce korktular.'),
(2007557,68,41,5,16,'Olayı görenler, cinli adama olanları ve domuzların başına gelenleri halka anlattılar.'),
(2007558,68,41,5,17,'Bunun üzerine halk, bölgelerinden ayrılması için İsaya yalvarmaya başladı.'),
(2007559,68,41,5,18,'İsa tekneye binerken, önceleri cinli olan adam Ona, ‹‹Seninle geleyim›› diye yalvardı.'),
(2007560,68,41,5,19,'Ama İsa adama izin vermedi. Ona, ‹‹Evine, yakınlarının yanına dön›› dedi. ‹‹Rabbin senin için neler yaptığını, sana nasıl merhamet ettiğini onlara anlat.››'),
(2007561,68,41,5,20,'Adam da gitti, İsanın kendisi için neler yaptığını Dekapoliste duyurmaya başladı. Anlattıklarına herkes şaşıp kalıyordu.'),
(2007562,68,41,5,21,'İsa tekneyle karşı yakaya dönünce, çevresinde büyük bir kalabalık toplandı. Kendisi gölün kıyısında duruyordu.'),
(2007563,68,41,5,22,'Bu sırada havra yöneticilerinden Yair adında biri geldi. İsayı görünce ayaklarına kapandı, ‹‹Küçük kızım can çekişiyor. Gelip ellerini onun üzerine koy da kurtulsun, yaşasın!›› diye yalvardı.'),
(2007564,68,41,5,24,'İsa adamla birlikte gitti. Büyük bir kalabalık da ardından gidiyor, Onu sıkıştırıyordu.'),
(2007565,68,41,5,25,'Orada, on iki yıldır kanaması olan bir kadın vardı.'),
(2007566,68,41,5,26,'Birçok hekimin elinden çok çekmiş, varını yoğunu harcamış, ama iyileşeceğine daha da kötüleşmişti.'),
(2007567,68,41,5,27,'Kadın, İsa hakkında anlatılanları duymuştu. Bu nedenle, kalabalıkta Onun arkasından gelip giysisine dokundu.'),
(2007568,68,41,5,28,'İçinden, ‹‹Giysilerine bile dokunsam kurtulurum›› diyordu.'),
(2007569,68,41,5,29,'O anda kanaması kesiliverdi. Kadın, bedeninin derinliğinde acıdan kurtulduğunu hissetti.'),
(2007570,68,41,5,30,'İsa ise, kendisinden bir gücün akıp gittiğini hemen anladı. Kalabalığın ortasında dönüp, ‹‹Giysilerime kim dokundu?›› diye sordu.'),
(2007571,68,41,5,31,'Öğrencileri Ona, ‹‹Seni sıkıştıran kalabalığı görüyorsun! Nasıl oluyor da, ‹Bana kim dokundu› diye soruyorsun?›› dediler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007572,68,41,5,32,'İsa kendisine dokunanı görmek için çevresine bakındı.'),
(2007573,68,41,5,33,'Kadın da kendisindeki değişikliği biliyordu. Korkuyla titreyerek geldi, İsanın ayaklarına kapandı ve Ona bütün gerçeği anlattı.'),
(2007574,68,41,5,34,'İsa ona, ‹‹Kızım›› dedi, ‹‹İmanın seni kurtardı. Esenlikle git. Acıların son bulsun.››'),
(2007575,68,41,5,35,'İsa daha konuşurken, havra yöneticisinin evinden adamlar geldi. Yöneticiye, ‹‹Kızın öldü›› dediler. ‹‹Öğretmeni neden hâlâ rahatsız ediyorsun?››'),
(2007576,68,41,5,36,'İsa bu sözlere aldırmadan havra yöneticisine, ‹‹Korkma, yalnız iman et!›› dedi.'),
(2007577,68,41,5,37,'İsa, Petrus, Yakup ve Yakupun kardeşi Yuhannadan başka hiç kimsenin kendisiyle birlikte gitmesine izin vermedi.'),
(2007578,68,41,5,38,'Havra yöneticisinin evine vardıklarında İsa, acı acı ağlayıp feryat eden gürültülü bir kalabalıkla karşılaştı.'),
(2007579,68,41,5,39,'İçeri girerek onlara, ‹‹Niye gürültü edip ağlıyorsunuz?›› dedi. ‹‹Çocuk ölmedi, uyuyor.››'),
(2007580,68,41,5,40,'Onlar ise kendisiyle alay ettiler. Ama İsa hepsini dışarı çıkardıktan sonra çocuğun annesini babasını ve kendisiyle birlikte olanları alıp çocuğun bulunduğu odaya girdi.'),
(2007581,68,41,5,41,'Çocuğun elini tutarak ona, ‹‹Talita kumi!›› dedi. Bu söz, ‹‹Kızım, sana söylüyorum, kalk›› demektir.'),
(2007582,68,41,5,42,'On iki yaşında olan kız hemen ayağa kalktı, yürümeye başladı. Oradakileri derin bir şaşkınlık aldı.'),
(2007583,68,41,5,43,'İsa, ‹‹Bunu kimse bilmesin›› diyerek onları sıkı sıkıya uyardı ve kıza yemek verilmesini buyurdu.'),
(2007584,68,41,6,1,'İsa oradan ayrılarak kendi memleketine gitti. Öğrencileri de ardından gittiler.'),
(2007585,68,41,6,2,'Şabat Günü olunca İsa havrada öğretmeye başladı. Söylediklerini işiten birçok kişi şaşıp kaldı. ‹‹Bu adam bunları nereden öğrendi?›› diye soruyorlardı. ‹‹Kendisine verilen bu bilgelik nedir? Nasıl böyle mucizeler yapabiliyor?'),
(2007586,68,41,6,3,'Meryemin oğlu, Yakup, Yose, Yahuda ve Simunun kardeşi olan marangoz değil mi bu? Kızkardeşleri burada, aramızda yaşamıyor mu?›› Ve gücenip Onu reddettiler.'),
(2007587,68,41,6,4,'İsa da onlara, ‹‹Bir peygamber, kendi memleketinden, akraba çevresinden ve kendi evinden başka yerde hor görülmez›› dedi.'),
(2007588,68,41,6,5,'Orada birkaç hastayı, üzerlerine ellerini koyarak iyileştirmekten başka hiçbir mucize yapamadı.'),
(2007589,68,41,6,6,'Halkın imansızlığına şaşıyordu. İsa çevredeki köyleri dolaşıp öğretiyordu.'),
(2007590,68,41,6,7,'On iki öğrencisini yanına çağırdı ve onları ikişer ikişer halk arasına göndermeye başladı. Onlara kötü ruhlar üzerinde yetki verdi.'),
(2007591,68,41,6,8,'Yolculuk için yanlarına değnekten başka bir şey almamalarını söyledi. Ne ekmek, ne torba, ne de kuşaklarında para götüreceklerdi.'),
(2007592,68,41,6,9,'Onlara çarık giymelerini söyledi. Ama, ‹‹İki mintan giymeyin›› dedi.'),
(2007593,68,41,6,10,'‹‹Bir yere gittiğiniz zaman, oradan ayrılıncaya dek hep aynı evde kalın›› diye devam etti.'),
(2007594,68,41,6,11,'‹‹İnsanların sizi kabul etmedikleri, sizi dinlemedikleri bir yerden ayrılırken, onlara uyarı olsun diye ayağınızın altındaki tozu silkin!››'),
(2007595,68,41,6,12,'Böylece öğrenciler yola çıkıp insanları tövbeye çağırmaya başladılar.'),
(2007596,68,41,6,13,'Birçok cin kovdular; birçok hastayı, üzerlerine yağ sürerek iyileştirdiler.'),
(2007597,68,41,6,14,'Kral Hirodes de olup bitenleri duydu. Çünkü İsanın ünü her tarafa yayılmıştı. Bazıları, ‹‹Bu adam, ölümden dirilen Vaftizci Yahyadır. Olağanüstü güçlerin onda etkin olmasının nedeni budur›› diyordu.'),
(2007598,68,41,6,15,'Başkaları, ‹‹O İlyastır›› diyor, yine başkaları, ‹‹Eski peygamberlerden biri gibi bir peygamberdir›› diyordu.'),
(2007599,68,41,6,16,'Hirodes bunları duyunca, ‹‹Başını kestirdiğim Yahya dirildi!›› dedi.'),
(2007600,68,41,6,17,'Hirodesin kendisi, kardeşi Filipusun karısı Hirodiyanın yüzünden adam gönderip Yahyayı tutuklatmış, zindana attırıp zincire vurdurmuştu. Çünkü Hirodes bu kadınla evlenince Yahya ona, ‹‹Kardeşinin karısıyla evlenmen Kutsal Yasaya aykırıdır›› demişti.'),
(2007601,68,41,6,19,'Hirodiya bu yüzden Yahyaya kin bağlamıştı; onu öldürtmek istiyor, ama başaramıyordu.'),
(2007602,68,41,6,20,'Çünkü Yahyanın doğru ve kutsal bir adam olduğunu bilen Hirodes ondan korkuyor ve onu koruyordu. Yahyayı dinlediği zaman büyük bir şaşkınlık içinde kalıyor, yine de onu dinlemekten zevk alıyordu.'),
(2007603,68,41,6,21,'Ne var ki, Hirodesin kendi doğum gününde saray büyükleri, komutanlar ve Celilenin ileri gelenleri için verdiği şölende beklenen fırsat doğdu.'),
(2007604,68,41,6,22,'Hirodiyanın kızı içeri girip dans etti. Bu, Hirodesle konuklarının hoşuna gitti. Kral genç kıza, ‹‹Dile benden, ne dilersen veririm›› dedi.'),
(2007605,68,41,6,23,'Ant içerek, ‹‹Benden ne dilersen, krallığımın yarısı da olsa, veririm›› dedi.'),
(2007606,68,41,6,24,'Kız dışarı çıkıp annesine, ‹‹Ne isteyeyim?›› diye sordu. ‹‹Vaftizci Yahyanın başını iste›› dedi annesi.'),
(2007607,68,41,6,25,'Kız hemen koşup kralın yanına girdi, ‹‹Vaftizci Yahyanın başını bir tepsi üzerinde hemen bana vermeni istiyorum›› diyerek dileğini açıkladı.'),
(2007608,68,41,6,26,'Kral buna çok üzüldüyse de, konuklarının önünde içtiği anttan ötürü kızı reddetmek istemedi.'),
(2007609,68,41,6,27,'Hemen bir cellat gönderip Yahyanın başını getirmesini buyurdu. Cellat zindana giderek Yahyanın başını kesti.'),
(2007610,68,41,6,28,'Kesik başı bir tepsi üzerinde getirip genç kıza verdi, kız da annesine götürdü.'),
(2007611,68,41,6,29,'Yahyanın öğrencileri bunu duyunca gelip cesedi aldılar ve mezara koydular.'),
(2007612,68,41,6,30,'Elçiler, İsanın yanına dönerek yaptıkları ve öğrettikleri her şeyi Ona anlattılar.'),
(2007613,68,41,6,31,'İsa onlara, ‹‹Gelin, tek başımıza tenha bir yere gidelim de biraz dinlenin›› dedi. Gelen giden öyle çoktu ki, yemek yemeye bile vakit bulamıyorlardı.'),
(2007614,68,41,6,32,'Tekneye binip tek başlarına tenha bir yere doğru yol aldılar.'),
(2007615,68,41,6,33,'Gittiklerini gören birçok kişi onları tanıdı. Halk civardaki bütün kentlerden yaya olarak yola dökülüp onlardan önce oraya vardı.'),
(2007616,68,41,6,34,'İsa tekneden inince büyük bir kalabalıkla karşılaştı. Çobansız koyunlara benzeyen bu insanlara acıdı ve onlara birçok konuda öğretmeye başladı.'),
(2007617,68,41,6,35,'Vakit ilerlemişti. Öğrencileri İsaya gelip, ‹‹Burası ıssız bir yer›› dediler, ‹‹Vakit de ilerledi. Halkı salıver de çevredeki çiftlik ve köylere gidip kendilerine yiyecek alsınlar.››'),
(2007618,68,41,6,37,'İsa ise, ‹‹Onlara siz yiyecek verin›› diye karşılık verdi. Öğrenciler İsaya, ‹‹Gidip iki yüz dinarlık ekmek alıp onlara yedirelim mi yani?›› diye sordular.'),
(2007619,68,41,6,38,'İsa onlara, ‹‹Kaç ekmeğiniz var, gidin bakın›› dedi. Öğrenip geldiler, ‹‹Beş ekmekle iki balığımız var›› dediler.'),
(2007620,68,41,6,39,'İsa herkesi küme küme yeşil çayıra oturtmalarını buyurdu.'),
(2007621,68,41,6,40,'Halk yüzer ellişer kişilik bölükler halinde oturdu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007622,68,41,6,41,'İsa beş ekmekle iki balığı aldı, gözlerini göğe kaldırarak şükretti; sonra ekmekleri böldü ve halka dağıtmaları için öğrencilerine verdi. İki balığı da hepsinin arasında paylaştırdı.'),
(2007623,68,41,6,42,'Herkes yiyip doydu. Artakalan ekmek ve balıktan on iki sepet dolusu topladılar.'),
(2007624,68,41,6,44,'Yemek yiyen erkeklerin sayısı beş bin kadardı.'),
(2007625,68,41,6,45,'Bundan hemen sonra İsa öğrencilerine, tekneye binip kendisinden önce karşı yakada bulunan Beytsaydaya geçmelerini buyurdu. Bu arada kendisi halkı evlerine gönderecekti.'),
(2007626,68,41,6,46,'Onları uğurladıktan sonra, dua etmek için dağa çıktı.'),
(2007627,68,41,6,47,'Akşam olduğunda, tekne gölün ortasına varmıştı. Yalnız başına karada kalan İsa, öğrencilerinin kürek çekmekte çok zorlandıklarını gördü. Çünkü rüzgar onlara karşı esiyordu. Sabaha karşı İsa, gölün üstünde yürüyerek onlara yaklaştı. Yanlarından geçip gidecekti.'),
(2007628,68,41,6,49,'Onlar ise, gölün üstünde yürüdüğünü görünce Onu hayalet sanarak bağrıştılar.'),
(2007629,68,41,6,50,'Hepsi Onu görmüş ve dehşete kapılmıştı. İsa hemen onlara seslenerek, ‹‹Cesur olun, benim, korkmayın!›› dedi.'),
(2007630,68,41,6,51,'Tekneye binip onlara katılınca rüzgar dindi. Onlarsa büyük bir şaşkınlık içindeydi.'),
(2007631,68,41,6,52,'Ekmekle ilgili mucizeyi bile anlamamışlardı; zihinleri körelmişti.'),
(2007632,68,41,6,53,'İsayla öğrencileri gölü aştılar, Ginnesarda karaya çıkıp tekneyi bağladılar.'),
(2007633,68,41,6,54,'Onlar tekneden inince, halk İsayı hemen tanıdı.'),
(2007634,68,41,6,55,'Bazıları koşarak bütün yöreyi dolaştı. İsanın bulunduğu yeri öğrenenler, hastaları şilteleriyle oraya götürmeye başladılar.'),
(2007635,68,41,6,56,'Köy olsun, kent ya da çiftlik olsun, İsa''nın gittiği her yerde, hastaları meydanlara yatırıyor, sadece giysisinin eteğine dokunmalarına izin vermesi için yalvarıyorlardı. Dokunanların hepsi de iyileşti.'),
(2007636,68,41,7,1,'Yeruşalimden gelen Ferisiler ve bazı din bilginleri, İsanın çevresinde toplandılar.'),
(2007637,68,41,7,2,'Onun öğrencilerinden bazılarının murdar, yani yıkanmamış ellerle yemek yediklerini gördüler.'),
(2007638,68,41,7,3,'Ferisiler, hatta bütün Yahudiler, atalarının töresi uyarınca ellerini iyice yıkamadan yemek yemezler.'),
(2007639,68,41,7,4,'Çarşıdan dönünce de, yıkanmadan yemek yemezler. Ayrıca kâse, testi ve bakır kapların yıkanmasıyla ilgili başka birçok töreye de uyarlar.'),
(2007640,68,41,7,5,'Ferisiler ve din bilginleri İsaya, ‹‹Öğrencilerin neden atalarımızın töresine uymuyorlar, niçin murdar ellerle yemek yiyorlar?›› diye sordular.'),
(2007641,68,41,7,6,'İsa onları şöyle yanıtladı: ‹‹Yeşayanın siz ikiyüzlülerle ilgili peygamberlik sözü ne kadar yerindedir! Yazmış olduğu gibi, ‹Bu halk, dudaklarıyla beni sayar, Ama yürekleri benden uzak.'),
(2007642,68,41,7,7,'Bana boşuna taparlar. Çünkü öğrettikleri, sadece insan buyruklarıdır.›'),
(2007643,68,41,7,8,'Siz Tanrı buyruğunu bir yana bırakmış, insan töresine uyuyorsunuz.››'),
(2007644,68,41,7,9,'İsa onlara ayrıca şunu söyledi: ‹‹Kendi törenizi sürdürmek için Tanrı buyruğunu bir kenara itmeyi ne de güzel beceriyorsunuz!'),
(2007645,68,41,7,10,'Musa, ‹Annene babana saygı göstereceksin› ve, ‹Annesine ya da babasına söven kesinlikle öldürülecektir› diye buyurmuştu.'),
(2007646,68,41,7,11,'Ama siz, ‹Eğer bir adam annesine ya da babasına, benden alacağın bütün yardım kurbandır, yani Tanrıya adanmıştır derse, artık annesi ya da babası için bir şey yapmasına izin yok› diyorsunuz.'),
(2007647,68,41,7,13,'Böylece kuşaktan kuşağa aktardığınız törelerle Tanrının sözünü geçersiz kılıyorsunuz. Buna benzer daha birçok şey yapıyorsunuz.››'),
(2007648,68,41,7,14,'İsa, halkı yine yanına çağırıp onlara, ‹‹Hepiniz beni dinleyin ve şunu belleyin›› dedi.'),
(2007649,68,41,7,15,'‹‹İnsanın dışında olup içine giren hiçbir şey onu kirletemez. İnsanı kirleten, insanın içinden çıkandır.››'),
(2007650,68,41,7,17,'İsa kalabalığı bırakıp eve girince, öğrencileri Ona bu benzetmenin anlamını sordular.'),
(2007651,68,41,7,18,'O da onlara, ‹‹Demek siz de anlamıyorsunuz, öyle mi?›› dedi. ‹‹Dışarıdan insanın içine giren hiçbir şeyin onu kirletemeyeceğini bilmiyor musunuz?'),
(2007652,68,41,7,19,'Dıştan giren, insanın yüreğine değil, midesine gider, oradan da helaya atılır.›› İsa bu sözlerle, bütün yiyeceklerin temiz olduğunu bildirmiş oluyordu.'),
(2007653,68,41,7,20,'İsa şöyle devam etti: ‹‹İnsanı kirleten, insanın içinden çıkandır.'),
(2007654,68,41,7,21,'Çünkü kötü düşünceler, fuhuş, hırsızlık, cinayet, zina, açgözlülük, kötülük, hile, sefahat, kıskançlık, iftira, kibir ve akılsızlık içten, insanın yüreğinden kaynaklanır.'),
(2007655,68,41,7,23,'Bu kötülüklerin hepsi içten kaynaklanır ve insanı kirletir.››'),
(2007656,68,41,7,24,'İsa oradan ayrılarak Sur bölgesine gitti. Burada bir eve girdi. Kimsenin bunu bilmesini istemiyordu, ama gizlenemedi.'),
(2007657,68,41,7,25,'Küçük kızı kötü ruha tutulmuş bir kadın, İsayla ilgili haberi duyar duymaz geldi, ayaklarına kapandı.'),
(2007658,68,41,7,26,'Yahudi olmayan bu kadın Suriye-Fenike ırkındandı. Kızından cini kovması için İsaya rica etti.'),
(2007659,68,41,7,27,'İsa ona, ‹‹Bırak, önce çocuklar doysunlar›› dedi. ‹‹Çocukların ekmeğini alıp köpeklere atmak doğru değildir.››'),
(2007660,68,41,7,28,'Kadın buna karşılık, ‹‹Haklısın, Rab›› dedi. ‹‹Ama köpekler de sofranın altında çocukların ekmek kırıntılarını yer.››'),
(2007661,68,41,7,29,'İsa ona, ‹‹Bu sözden ötürü cin kızından çıktı, gidebilirsin›› dedi.'),
(2007662,68,41,7,30,'Kadın evine gittiğinde çocuğunu cinden kurtulmuş, yatakta yatar buldu.'),
(2007663,68,41,7,31,'Sur bölgesinden ayrılan İsa, Sayda yoluyla Dekapolis bölgesinin ortasından geçerek tekrar Celile Gölüne geldi.'),
(2007664,68,41,7,32,'Ona sağır ve dili tutuk bir adam getirdiler, elini üzerine koyması için yalvardılar.'),
(2007665,68,41,7,33,'İsa adamı kalabalıktan ayırıp bir yana çekti. Parmaklarını adamın kulaklarına soktu, tükürüp onun diline dokundu.'),
(2007666,68,41,7,34,'Sonra göğe bakarak içini çekti ve adama, ‹‹Effata››, yani ‹‹Açıl!›› dedi.'),
(2007667,68,41,7,35,'Adamın kulakları hemen açıldı, dili çözüldü ve düzgün bir şekilde konuşmaya başladı.'),
(2007668,68,41,7,36,'İsa orada bulunanları, bunu kimseye söylememeleri için uyardı. Ama onları ne kadar uyardıysa, onlar da haberi o kadar yaydılar.'),
(2007669,68,41,7,37,'Halk büyük bir hayret içinde kalmıştı. ‹‹Yaptığı her şey iyi. Sağırların kulaklarını açıyor, dilsizleri konuşturuyor!›› diyorlardı.'),
(2007670,68,41,8,1,'O günlerde yine büyük bir kalabalık toplanmıştı. Yiyecek bir şeyleri olmadığı için İsa öğrencilerini yanına çağırıp, ‹‹Halka acıyorum›› dedi. ‹‹Üç gündür yanımdalar, yiyecek hiçbir şeyleri yok.'),
(2007671,68,41,8,3,'Onları aç aç evlerine gönderirsem, yolda bayılırlar. Hem bazıları uzak yoldan geliyor.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007672,68,41,8,4,'Öğrencileri buna karşılık, ‹‹Böyle ıssız bir yerde bu kadar kişiyi doyuracak ekmeği insan nereden bulabilir?›› dediler.'),
(2007673,68,41,8,5,'İsa, ‹‹Kaç ekmeğiniz var?›› diye sordu. ‹‹Yedi tane›› dediler.'),
(2007674,68,41,8,6,'Bunun üzerine İsa, halka yere oturmalarını buyurdu. Sonra yedi ekmeği aldı, şükredip bunları böldü, dağıtmaları için öğrencilerine verdi. Onlar da halka dağıttılar.'),
(2007675,68,41,8,7,'Birkaç küçük balıkları da vardı. İsa şükredip bunları da dağıtmalarını söyledi.'),
(2007676,68,41,8,8,'Herkes yiyip doydu. Artakalan parçalardan yedi küfe dolusu topladılar.'),
(2007677,68,41,8,9,'Orada yaklaşık dört bin kişi vardı. İsa onları evlerine gönderdikten sonra öğrencileriyle birlikte hemen tekneye binip Dalmanuta bölgesine geçti.'),
(2007678,68,41,8,11,'Ferisiler gelip İsayla tartışmaya başladılar. Onu denemek amacıyla gökten bir belirti göstermesini istediler.'),
(2007679,68,41,8,12,'İsa içten bir ah çekerek, ‹‹Bu kuşak neden bir belirti istiyor?›› dedi. ‹‹Size doğrusunu söyleyeyim, bu kuşağa hiçbir belirti gösterilmeyecek.››'),
(2007680,68,41,8,13,'Sonra onları orada bırakıp yine tekneye bindi ve karşı yakaya yöneldi.'),
(2007681,68,41,8,14,'Öğrenciler ekmek almayı unutmuşlardı. Teknede, yanlarında yalnız bir ekmek vardı.'),
(2007682,68,41,8,15,'İsa onlara şu uyarıda bulundu: ‹‹Dikkatli olun, Ferisilerin mayasından ve Hirodesin mayasından sakının!››'),
(2007683,68,41,8,16,'Onlar ise kendi aralarında, ‹‹Ekmeğimiz olmadığı için böyle diyor›› şeklinde tartıştılar.'),
(2007684,68,41,8,17,'Bunun farkında olan İsa, ‹‹Ekmeğiniz yok diye niçin tartışıyorsunuz?›› dedi. ‹‹Hâlâ akıl erdiremiyor, anlamıyor musunuz? Zihniniz köreldi mi?'),
(2007685,68,41,8,18,'Gözleriniz olduğu halde görmüyor musunuz? Kulaklarınız olduğu halde işitmiyor musunuz? Hatırlamıyor musunuz, beş ekmeği beş bin kişiye bölüştürdüğümde kaç sepet dolusu yemek fazlası topladınız?›› ‹‹On iki›› dediler.'),
(2007686,68,41,8,20,'‹‹Yedi ekmeği dört bin kişiye bölüştürdüğümde kaç küfe dolusu yemek fazlası topladınız?›› ‹‹Yedi›› dediler.'),
(2007687,68,41,8,21,'İsa onlara, ‹‹Hâlâ anlamıyor musunuz?›› dedi.'),
(2007688,68,41,8,22,'İsa ile öğrencileri Beytsaydaya geldiler. Orada bazı kişiler İsaya kör bir adam getirip ona dokunması için yalvardılar.'),
(2007689,68,41,8,23,'İsa körün elinden tutarak onu köyün dışına çıkardı. Gözlerine tükürüp ellerini üzerine koydu ve, ‹‹Bir şey görüyor musun?›› diye sordu.'),
(2007690,68,41,8,24,'Adam başını kaldırıp, ‹‹İnsanlar görüyorum›› dedi, ‹‹Ağaçlara benziyorlar, ama yürüyorlar.››'),
(2007691,68,41,8,25,'Sonra İsa ellerini yeniden adamın gözleri üzerine koydu. Adam gözlerini açtı, baktı; iyileşmiş ve her şeyi açık seçik görmeye başlamıştı.'),
(2007692,68,41,8,26,'İsa, ‹‹Köye bile girme!›› diyerek onu evine gönderdi.'),
(2007693,68,41,8,27,'İsa, öğrencileriyle birlikte Filipus Sezariyesine bağlı köylere gitti. Yolda öğrencilerine, ‹‹Halk benim kim olduğumu söylüyor?›› diye sordu.'),
(2007694,68,41,8,28,'Öğrencileri Ona şu karşılığı verdiler: ‹‹Vaftizci Yahya diyorlar. Ama kimi İlyas, kimi de peygamberlerden biri olduğunu söylüyor.››'),
(2007695,68,41,8,29,'O da onlara, ‹‹Siz ne dersiniz, sizce ben kimim?›› diye sordu. Petrus, ‹‹Sen Mesihsin›› yanıtını verdi.'),
(2007696,68,41,8,30,'Bunun üzerine İsa bu konuda kimseye bir şey söylememeleri için onları uyardı.'),
(2007697,68,41,8,31,'İsa, İnsanoğlunun çok acı çekmesi, ileri gelenler, başkâhinler ve din bilginlerince reddedilmesi, öldürülmesi ve üç gün sonra dirilmesi gerektiğini onlara anlatmaya başladı.'),
(2007698,68,41,8,32,'Bunları açıkça söylüyordu. Bunun üzerine Petrus Onu bir kenara çekip azarlamaya başladı.'),
(2007699,68,41,8,33,'İsa dönüp öteki öğrencilerine baktı; Petrusu azarlayarak, ‹‹Çekil önümden, Şeytan!›› dedi. ‹‹Düşüncelerin Tanrıya değil, insana özgüdür.››'),
(2007700,68,41,8,34,'Öğrencileriyle birlikte halkı da yanına çağırıp şöyle konuştu: ‹‹Ardımdan gelmek isteyen kendini inkâr etsin, çarmıhını yüklenip beni izlesin.'),
(2007701,68,41,8,35,'Canını kurtarmak isteyen onu yitirecek, canını benim ve Müjdenin uğruna yitiren ise onu kurtaracaktır.'),
(2007702,68,41,8,36,'İnsan bütün dünyayı kazanıp da canından olursa, bunun kendisine ne yararı olur?'),
(2007703,68,41,8,37,'İnsan kendi canına karşılık ne verebilir?'),
(2007704,68,41,8,38,'Bu vefasız ve günahkâr kuşağın ortasında, kim benden ve benim sözlerimden utanırsa, İnsanoğlu da, Babası''nın görkemi içinde kutsal meleklerle birlikte geldiğinde o kişiden utanacaktır.››'),
(2007705,68,41,9,1,'İsa, ‹‹Size doğrusunu söyleyeyim›› diye devam etti, ‹‹Burada bulunanlar arasında, Tanrı Egemenliğinin güçlü biçimde gerçekleştiğini görmeden ölümü tatmayacak olanlar var.››'),
(2007706,68,41,9,2,'Altı gün sonra İsa, yanına yalnız Petrus, Yakup ve Yuhannayı alarak yüksek bir dağa çıktı. Onların gözü önünde İsanın görünümü değişti.'),
(2007707,68,41,9,3,'Giysileri göz kamaştırıcı bir beyazlığa büründü; yeryüzünde hiçbir çamaşırcının erişemeyeceği bir beyazlıktı bu.'),
(2007708,68,41,9,4,'O anda Musayla İlyas öğrencilere göründü. İsayla konuşuyorlardı.'),
(2007709,68,41,9,5,'Petrus İsaya, ‹‹Rabbî, burada bulunmamız ne iyi oldu! Üç çardak kuralım: Biri sana, biri Musaya, biri de İlyasa›› dedi.'),
(2007710,68,41,9,6,'Ne söyleyeceğini bilmiyordu. Çünkü çok korkmuşlardı.'),
(2007711,68,41,9,7,'Bu sırada bir bulut gelip onlara gölge saldı. Buluttan gelen bir ses, ‹‹Sevgili Oğlum budur, Onu dinleyin!›› dedi.'),
(2007712,68,41,9,8,'Öğrenciler birden çevrelerine baktılar, ama bu kez yanlarında İsadan başka kimseyi göremediler.'),
(2007713,68,41,9,9,'Dağdan inerlerken İsa, İnsanoğlu ölümden dirilmeden orada gördüklerini hiç kimseye söylememeleri için onları uyardı.'),
(2007714,68,41,9,10,'Bu uyarıya uymakla birlikte kendi aralarında, ‹‹Ölümden dirilmek ne demek?›› diye tartışıp durdular.'),
(2007715,68,41,9,11,'İsaya, ‹‹Din bilginleri neden önce İlyasın gelmesi gerektiğini söylüyorlar?›› diye sordular.'),
(2007716,68,41,9,12,'O da onlara şöyle dedi: ‹‹Gerçekten de önce İlyas gelir ve her şeyi yeniden düzene koyar. Ama nasıl oluyor da İnsanoğlunun çok acı çekeceği ve hiçe sayılacağı yazılmıştır?'),
(2007717,68,41,9,13,'Size şunu söyleyeyim, İlyas geldi bile, onun hakkında yazılmış olduğu gibi, ona yapmadıklarını bırakmadılar.››'),
(2007718,68,41,9,14,'Öteki öğrencilerin yanına döndüklerinde, onların çevresinde büyük bir kalabalığın toplandığını, birtakım din bilginlerinin onlarla tartıştığını gördüler.'),
(2007719,68,41,9,15,'Kalabalık İsayı görünce büyük bir şaşkınlığa kapıldı ve koşup Onu selamladı.'),
(2007720,68,41,9,16,'İsa öğrencilerine, ‹‹Onlarla ne tartışıyorsunuz?›› diye sordu.'),
(2007721,68,41,9,17,'Halktan biri Ona, ‹‹Öğretmenim›› diye karşılık verdi, ‹‹Dilsiz bir ruha tutulan oğlumu sana getirdim.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007722,68,41,9,18,'Ruh onu nerede yakalarsa yere çarpıyor. Çocuk ağzından köpükler saçıyor, dişlerini gıcırdatıyor ve kaskatı kesiliyor. Ruhu kovmaları için öğrencilerine başvurdum, ama başaramadılar.››'),
(2007723,68,41,9,19,'İsa onlara, ‹‹Ey imansız kuşak!›› dedi. ‹‹Sizinle daha ne kadar kalacağım? Size daha ne kadar katlanacağım? Çocuğu bana getirin!››'),
(2007724,68,41,9,20,'Çocuğu kendisine getirdiler. Ruh, İsayı görür görmez çocuğu şiddetle sarstı; çocuk yere düştü, ağzından köpükler saçarak yuvarlanmaya başladı.'),
(2007725,68,41,9,21,'İsa çocuğun babasına, ‹‹Bu hal çocuğun başına geleli ne kadar oldu?›› diye sordu. ‹‹Küçüklüğünden beri böyle›› dedi babası.'),
(2007726,68,41,9,22,'‹‹Üstelik ruh onu öldürmek için sık sık ateşe, suya attı. Elinden bir şey gelirse, bize yardım et, halimize acı!››'),
(2007727,68,41,9,23,'İsa ona, ‹‹Elimden gelirse mi? İman eden biri için her şey mümkün!›› dedi.'),
(2007728,68,41,9,24,'Çocuğun babası hemen, ‹‹İman ediyorum, imansızlığımı yenmeme yardım et!›› diye feryat etti.'),
(2007729,68,41,9,25,'İsa, halkın koşuşup geldiğini görünce kötü ruhu azarlayarak, ‹‹Sana buyuruyorum, dilsiz ve sağır ruh, çocuğun içinden çık ve ona bir daha girme!›› dedi.'),
(2007730,68,41,9,26,'Bunun üzerine ruh bir çığlık attı ve çocuğu şiddetle sarsarak çıktı. Çocuk ölü gibi hareketsiz kaldı, öyle ki oradakilerin birçoğu, ‹‹Öldü!›› diyordu.'),
(2007731,68,41,9,27,'Ama İsa elinden tutup kaldırınca, çocuk ayağa kalktı.'),
(2007732,68,41,9,28,'İsa eve girdikten sonra öğrencileri özel olarak Ona, ‹‹Biz kötü ruhu neden kovamadık?›› diye sordular.'),
(2007733,68,41,9,29,'İsa onlara, ‹‹Bu tür ruhlar ancak duayla kovulabilir›› yanıtını verdi.'),
(2007734,68,41,9,30,'Oradan ayrılmış, Celile bölgesinden geçiyorlardı. İsa hiç kimsenin bunu bilmesini istemiyordu.'),
(2007735,68,41,9,31,'Öğrencilerine öğretirken şöyle diyordu: ‹‹İnsanoğlu, insanların eline teslim edilecek ve öldürülecek, ama öldürüldükten üç gün sonra dirilecek.››'),
(2007736,68,41,9,32,'Onlar bu sözleri anlamıyor, İsaya soru sormaktan da korkuyorlardı.'),
(2007737,68,41,9,33,'Kefarnahuma vardılar. Eve girdikten sonra İsa onlara, ‹‹Yolda neyi tartışıyordunuz?›› diye sordu.'),
(2007738,68,41,9,34,'Hiç birinden ses çıkmadı. Çünkü yolda aralarında kimin en büyük olduğunu tartışmışlardı.'),
(2007739,68,41,9,35,'İsa oturup Onikileri yanına çağırdı. Onlara şöyle dedi: ‹‹Birinci olmak isteyen en sonuncu olsun, herkesin hizmetkârı olsun.››'),
(2007740,68,41,9,36,'Küçük bir çocuğu alıp orta yere dikti, sonra onu kucağına alarak onlara şöyle dedi: ‹‹Böyle bir çocuğu benim adım uğruna kabul eden, beni kabul etmiş olur. Beni kabul eden de beni değil, beni göndereni kabul etmiş olur.››'),
(2007741,68,41,9,38,'Yuhanna Ona, ‹‹Öğretmenim›› dedi, ‹‹Senin adınla cin kovan birini gördük, ama bizi izleyenlerden olmadığı için ona engel olmaya çalıştık.››'),
(2007742,68,41,9,39,'‹‹Ona engel olmayın!›› dedi İsa. ‹‹Çünkü benim adımla mucize yapıp da ardından beni kötüleyecek kimse yoktur.'),
(2007743,68,41,9,40,'Bize karşı olmayan, bizden yanadır.'),
(2007744,68,41,9,41,'Size doğrusunu söyleyeyim, Mesihe ait olduğunuz için sizlere bir bardak su veren ödülsüz kalmayacaktır.››'),
(2007745,68,41,9,42,'‹‹Kim bana iman eden bu küçüklerden birini günaha düşürürse, boynuna kocaman bir değirmen taşı geçirilip denize atılması kendisi için daha iyi olur.'),
(2007746,68,41,9,43,'Eğer elin günah işlemene neden olursa, onu kes. Tek elle yaşama kavuşman, iki elle sönmez ateşe, cehenneme gitmenden iyidir.'),
(2007747,68,41,9,45,'Eğer ayağın günah işlemene neden olursa, onu kes. Tek ayakla yaşama kavuşman, iki ayakla cehenneme atılmandan iyidir.'),
(2007748,68,41,9,47,'Eğer gözün günah işlemene neden olursa, onu çıkar at. Tanrının Egemenliğine tek gözle girmen, iki gözle cehenneme atılmandan iyidir.'),
(2007749,68,41,9,48,'‹Oradakileri kemiren kurt ölmez, Yakan ateş sönmez.›'),
(2007750,68,41,9,49,'Çünkü herkes ateşle tuzlanacaktır.'),
(2007751,68,41,9,50,'Tuz yararlıdır. Ama tuz tuzluluğunu yitirirse, bir daha ona nasıl tat verebilirsiniz? İçinizde tuz olsun ve birbirinizle barış içinde yaşayın!››'),
(2007752,68,41,10,1,'İsa oradan ayrılıp Yahudiyenin Şeria Irmağının karşı yakasındaki topraklarına geçti. Çevresinde yine kalabalıklar toplanmıştı; her zamanki gibi onlara öğretiyordu.'),
(2007753,68,41,10,2,'Yanına gelen bazı Ferisiler Onu denemek amacıyla, ‹‹Bir erkeğin, karısını boşaması Kutsal Yasaya uygun mudur?›› diye sordular.'),
(2007754,68,41,10,3,'İsa karşılık olarak, ‹‹Musa size ne buyurdu?›› dedi.'),
(2007755,68,41,10,4,'Onlar, ‹‹Musa, erkeğin bir boşanma belgesi yazarak karısını boşamasına izin vermiştir›› dediler.'),
(2007756,68,41,10,5,'İsa onlara, ‹‹İnatçı olduğunuz için Musa bu buyruğu yazdı›› dedi.'),
(2007757,68,41,10,6,'‹‹Tanrı, yaratılışın başlangıcından ‹İnsanları erkek ve dişi olarak yarattı.›'),
(2007758,68,41,10,7,'‹Bu nedenle adam annesini babasını bırakıp karısına bağlanacak, ikisi tek beden olacak.› Şöyle ki, onlar artık iki değil, tek bedendir.'),
(2007759,68,41,10,9,'O halde Tanrının birleştirdiğini insan ayırmasın.››'),
(2007760,68,41,10,10,'Öğrencileri evde Ona yine bu konuyla ilgili bazı sorular sordular.'),
(2007761,68,41,10,11,'İsa onlara, ‹‹Karısını boşayıp başkasıyla evlenen, karısına karşı zina etmiş olur›› dedi.'),
(2007762,68,41,10,12,'‹‹Kocasını boşayıp başkasıyla evlenen kadın da zina etmiş olur.››'),
(2007763,68,41,10,13,'Bu arada bazıları küçük çocukları İsanın yanına getiriyor, onlara dokunmasını istiyorlardı. Ne var ki, öğrenciler onları azarladılar.'),
(2007764,68,41,10,14,'İsa bunu görünce kızdı. Öğrencilerine, ‹‹Bırakın, çocuklar bana gelsin›› dedi. ‹‹Onlara engel olmayın! Çünkü Tanrının Egemenliği böylelerinindir.'),
(2007765,68,41,10,15,'Size doğrusunu söyleyeyim, Tanrının Egemenliğini bir çocuk gibi kabul etmeyen, bu egemenliğe asla giremez.››'),
(2007766,68,41,10,16,'Çocukları kucağına aldı, ellerini üzerlerine koyup onları kutsadı.'),
(2007767,68,41,10,17,'İsa yola çıkarken, biri koşarak yanına geldi. Önünde diz çöküp Ona, ‹‹İyi öğretmenim, sonsuz yaşama kavuşmak için ne yapmalıyım?›› diye sordu.'),
(2007768,68,41,10,18,'İsa, ‹‹Bana neden iyi diyorsun?›› dedi. ‹‹İyi olan yalnız biri var, O da Tanrıdır.'),
(2007769,68,41,10,19,'Onun buyruklarını biliyorsun: ‹Adam öldürmeyeceksin, zina etmeyeceksin, çalmayacaksın, yalan yere tanıklık etmeyeceksin, kimsenin hakkını yemeyeceksin, annene babana saygı göstereceksin.› ››'),
(2007770,68,41,10,20,'Adam, ‹‹Öğretmenim, bunların hepsini gençliğimden beri yerine getiriyorum›› dedi.'),
(2007771,68,41,10,21,'Ona sevgiyle bakan İsa, ‹‹Bir eksiğin var›› dedi. ‹‹Git neyin varsa sat, parasını yoksullara ver; böylece gökte hazinen olur. Sonra gel, beni izle.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007772,68,41,10,22,'Bu sözler üzerine adamın yüzü asıldı, üzüntü içinde oradan uzaklaştı. Çünkü çok malı vardı.'),
(2007773,68,41,10,23,'İsa çevresine göz gezdirdikten sonra öğrencilerine, ‹‹Varlıklı kişilerin Tanrı Egemenliğine girmesi ne güç olacak!›› dedi.'),
(2007774,68,41,10,24,'Öğrenciler Onun sözlerine şaştılar. Ama İsa onlara yine, ‹‹Çocuklar›› dedi, ‹‹Tanrının Egemenliğine girmek ne güçtür!'),
(2007775,68,41,10,25,'Devenin iğne deliğinden geçmesi, zenginin Tanrı Egemenliğine girmesinden daha kolaydır.››'),
(2007776,68,41,10,26,'Öğrenciler büsbütün şaşırmışlardı. Birbirlerine, ‹‹Öyleyse kim kurtulabilir?›› diyorlardı.'),
(2007777,68,41,10,27,'İsa onlara bakarak, ‹‹İnsanlar için bu imkânsız, ama Tanrı için değil. Tanrı için her şey mümkündür›› dedi.'),
(2007778,68,41,10,28,'Petrus Ona, ‹‹Bak, biz her şeyi bırakıp senin ardından geldik›› demeye başladı.'),
(2007779,68,41,10,29,'‹‹Size doğrusunu söyleyeyim›› dedi İsa, ‹‹Benim ve Müjdenin uğruna evini, kardeşlerini, anne ya da babasını, çocuklarını ya da topraklarını bırakıp da şimdi, bu çağda çekeceği zulümlerle birlikte yüz kat daha fazla eve, kardeşe, anneye, çocuğa, toprağa ve gelecek çağda sonsuz yaşama kavuşmayacak hiç kimse yoktur.'),
(2007780,68,41,10,31,'Ne var ki, birincilerin birçoğu sonuncu, sonuncuların birçoğu da birinci olacak.››'),
(2007781,68,41,10,32,'Yola çıkmış Yeruşalime gidiyorlardı. İsa önlerinde yürüyordu. Öğrencileri şaşkınlık içindeydi, ardından gelenler ise korkuyorlardı. İsa Onikileri yine bir yana çekip kendi başına gelecekleri anlatmaya başladı: ‹‹Şimdi Yeruşalime gidiyoruz›› dedi. ‹‹İnsanoğlu, başkâhinlerin ve din bilginlerinin eline teslim edilecek. Onlar da Onu ölüm cezasına çarptıracak ve öteki uluslara teslim edecekler.'),
(2007782,68,41,10,34,'Onunla alay edecek, üzerine tükürecek ve Onu kamçılayıp öldürecekler. Ne var ki O, üç gün sonra dirilecek.››'),
(2007783,68,41,10,35,'Zebedinin oğulları Yakup ile Yuhanna İsaya yaklaşıp, ‹‹Öğretmenimiz, bir dileğimiz var, bunu yapmanı istiyoruz›› dediler.'),
(2007784,68,41,10,36,'İsa onlara, ‹‹Sizin için ne yapmamı istiyorsunuz?›› diye sordu.'),
(2007785,68,41,10,37,'‹‹Sen yüceliğine kavuşunca birimize sağında, ötekimize de solunda oturma ayrıcalığını ver›› dediler.'),
(2007786,68,41,10,38,'‹‹Siz ne dilediğinizi bilmiyorsunuz›› dedi İsa. ‹‹Benim içeceğim kâseden siz içebilir misiniz? Benim vaftiz olacağım gibi siz de vaftiz olabilir misiniz?››'),
(2007787,68,41,10,39,'‹‹Evet, olabiliriz›› dediler. İsa onlara, ‹‹Benim içeceğim kâseden siz de içeceksiniz, benim vaftiz olacağım gibi siz de vaftiz olacaksınız›› dedi. ‹‹Ama sağımda ya da solumda oturmanıza izin vermek benim elimde değil. Bu yerler belirli kişiler için hazırlanmıştır.››'),
(2007788,68,41,10,41,'Bunu işiten on öğrenci Yakupla Yuhannaya kızmaya başladılar.'),
(2007789,68,41,10,42,'İsa onları yanına çağırıp şöyle dedi: ‹‹Bilirsiniz ki, ulusların önderleri sayılanlar, onlara egemen kesilir, ileri gelenleri de onlara ağırlıklarını hissettirirler.'),
(2007790,68,41,10,43,'Sizin aranızda böyle olmayacak. Aranızda büyük olmak isteyen, ötekilerin hizmetkârı olsun.'),
(2007791,68,41,10,44,'Aranızda birinci olmak isteyen, hepinizin kulu olsun.'),
(2007792,68,41,10,45,'Çünkü İnsanoğlu bile hizmet edilmeye değil, hizmet etmeye ve canını birçokları için fidye olarak vermeye geldi.››'),
(2007793,68,41,10,46,'Sonra Erihaya geldiler. İsa, öğrencileri ve büyük bir kalabalıkla birlikte Erihadan ayrılırken, Timay oğlu Bartimay adında kör bir dilenci yol kenarında oturuyordu.'),
(2007794,68,41,10,47,'Nasıralı İsanın orada olduğunu duyunca, ‹‹Ey Davut Oğlu İsa, halime acı!›› diye bağırmaya başladı.'),
(2007795,68,41,10,48,'Birçok kimse onu azarlayarak susturmak istediyse de o, ‹‹Ey Davut Oğlu, halime acı!›› diyerek daha çok bağırdı.'),
(2007796,68,41,10,49,'İsa durdu, ‹‹Çağırın onu›› dedi. Kör adama seslenerek, ‹‹Ne mutlu sana! Kalk, seni çağırıyor!›› dediler.'),
(2007797,68,41,10,50,'Adam abasını üstünden atarak ayağa fırladı ve İsanın yanına geldi.'),
(2007798,68,41,10,51,'İsa, ‹‹Senin için ne yapmamı istiyorsun?›› diye sordu. Kör adam, ‹‹Rabbuni, gözlerim görsün›› dedi.'),
(2007799,68,41,10,52,'İsa, ‹‹Gidebilirsin, imanın seni kurtardı›› dedi. Adam o anda yeniden görmeye başladı ve yol boyunca İsa''nın ardından gitti.'),
(2007800,68,41,11,1,'Yeruşalime yaklaşıp Zeytin Dağının yamacındaki Beytfaci ile Beytanyaya geldiklerinde İsa iki öğrencisini önden gönderdi. Onlara, ‹‹Karşınızdaki köye gidin›› dedi, ‹‹Köye girer girmez, üzerine daha hiç kimsenin binmediği, bağlı duran bir sıpa bulacaksınız. Onu çözüp bana getirin.'),
(2007801,68,41,11,3,'Biri size, ‹Bunu niye yapıyorsunuz?› derse, ‹Rabbin ona ihtiyacı var, hemen geri gönderecek› dersiniz.››'),
(2007802,68,41,11,4,'Gittiler ve yol üzerinde, bir evin sokak kapısının yanında bağlı buldukları sıpayı çözdüler.'),
(2007803,68,41,11,5,'Orada duranlardan bazıları, ‹‹Sıpayı ne diye çözüyorsunuz?›› dediler.'),
(2007804,68,41,11,6,'Öğrenciler İsanın kendilerine söylediklerini tekrarlayınca, adamlar onları rahat bıraktı.'),
(2007805,68,41,11,7,'Sıpayı İsaya getirip üzerine kendi giysilerini yaydılar. İsa sıpaya bindi.'),
(2007806,68,41,11,8,'Birçokları giysilerini, bazıları da çevredeki ağaçlardan kestikleri dalları yola serdiler.'),
(2007807,68,41,11,9,'Önden gidenler ve arkadan gelenler şöyle bağırıyorlardı: ‹‹Hozana! Rabbin adıyla gelene övgüler olsun!'),
(2007808,68,41,11,10,'Atamız Davutun yaklaşan egemenliği kutlu olsun! En yücelerde hozana!››'),
(2007809,68,41,11,11,'İsa Yeruşalime varınca tapınağa gitti, her tarafı gözden geçirdi. Sonra vakit ilerlemiş olduğundan Onikilerle birlikte Beytanyaya döndü.'),
(2007810,68,41,11,12,'Ertesi gün Beytanyadan çıktıklarında İsa acıkmıştı.'),
(2007811,68,41,11,13,'Uzakta, yapraklanmış bir incir ağacı görünce belki incir bulurum diye yaklaştı. Ağacın yanına vardığında yapraktan başka bir şey bulamadı. Çünkü incir mevsimi değildi.'),
(2007812,68,41,11,14,'İsa ağaca, ‹‹Artık sonsuza dek senden kimse meyve yiyemesin!›› dedi. Öğrencileri de bunu duydular.'),
(2007813,68,41,11,15,'Oradan Yeruşalime geldiler. İsa tapınağın avlusuna girerek oradaki alıcı ve satıcıları dışarı kovdu. Para bozanların masalarını, güvercin satanların sehpalarını devirdi.'),
(2007814,68,41,11,16,'Yük taşıyan hiç kimsenin tapınağın avlusundan geçmesine izin vermedi.'),
(2007815,68,41,11,17,'Halka öğretirken şunları söyledi: ‹‹ ‹Evime, bütün ulusların dua evi denecek› diye yazılmamış mı? Ama siz onu haydut inine çevirdiniz.››'),
(2007816,68,41,11,18,'Başkâhinler ve din bilginleri bunu duyunca İsayı yok etmek için bir yol aramaya başladılar. Ondan korkuyorlardı. Çünkü bütün halk Onun öğretisine hayrandı.'),
(2007817,68,41,11,19,'Akşam olunca İsayla öğrencileri kentten ayrıldı.'),
(2007818,68,41,11,20,'Sabah erkenden incir ağacının yanından geçerlerken, ağacın kökten kurumuş olduğunu gördüler.'),
(2007819,68,41,11,21,'Olayı hatırlayan Petrus, ‹‹Rabbî, bak! Lanetlediğin incir ağacı kurumuş!›› dedi.'),
(2007820,68,41,11,22,'İsa onlara şöyle karşılık verdi: ‹‹Tanrıya iman edin.'),
(2007821,68,41,11,23,'Size doğrusunu söyleyeyim, kim şu dağa, ‹Kalk, denize atıl!› der ve yüreğinde kuşku duymadan dediğinin olacağına inanırsa, dileği yerine gelecektir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007822,68,41,11,24,'Bunun için size diyorum ki, duayla dilediğiniz her şeyi daha şimdiden almış olduğunuza inanın, dileğiniz yerine gelecektir.'),
(2007823,68,41,11,25,'Kalkıp dua ettiğiniz zaman, birine karşı bir şikâyetiniz varsa onu bağışlayın ki, göklerdeki Babanız da sizin suçlarınızı bağışlasın.››'),
(2007824,68,41,11,27,'Yine Yeruşalime geldiler. İsa tapınakta gezinirken başkâhinler, din bilginleri ve ileri gelenler Onun yanına gelip, ‹‹Bunları hangi yetkiyle yapıyorsun, bunları yapma yetkisini sana kim verdi?›› diye sordular.'),
(2007825,68,41,11,29,'İsa da onlara, ‹‹Size bir soru soracağım›› dedi. ‹‹Bana yanıt verin, ben de size bunları hangi yetkiyle yaptığımı söylerim.'),
(2007826,68,41,11,30,'Yahyanın vaftiz etme yetkisi Tanrıdan mıydı, insanlardan mı? Yanıt verin bana.››'),
(2007827,68,41,11,31,'Bunu aralarında şöyle tartışmaya başladılar: ‹‹ ‹Tanrıdan› dersek, ‹Öyleyse ona niçin inanmadınız?› diyecek.'),
(2007828,68,41,11,32,'Yok eğer ‹İnsanlardan› dersek...›› Halkın tepkisinden korkuyorlardı. Çünkü herkes Yahyayı gerçekten peygamber sayıyordu.'),
(2007829,68,41,11,33,'İsa''ya, ‹‹Bilmiyoruz›› diye yanıt verdiler. İsa da onlara, ‹‹Ben de size bunları hangi yetkiyle yaptığımı söylemeyeceğim›› dedi.'),
(2007830,68,41,12,1,'İsa onlara benzetmelerle konuşmaya başladı. ‹‹Adamın biri bağ dikti, çevresini çitle çevirdi, üzüm sıkmak için bir çukur kazdı, bir de bekçi kulesi yaptı. Sonra bağı bağcılara kiralayıp yolculuğa çıktı.'),
(2007831,68,41,12,2,'Mevsimi gelince bağın ürününden payına düşeni almak üzere bağcılara bir köle yolladı.'),
(2007832,68,41,12,3,'Bağcılar köleyi yakalayıp dövdü ve eli boş gönderdi.'),
(2007833,68,41,12,4,'Bağ sahibi bu kez onlara başka bir köle yolladı. Onu da başından yaralayıp aşağıladılar.'),
(2007834,68,41,12,5,'Birini daha yolladı, onu öldürdüler. Daha birçok köle yolladı. Kimini dövüp kimini öldürdüler.'),
(2007835,68,41,12,6,'‹‹Bağ sahibinin yanında tek kişi kaldı, o da sevgili oğluydu. ‹Oğlumu sayarlar› diyerek bağcılara en son onu yolladı.'),
(2007836,68,41,12,7,'‹‹Ama bağcılar birbirlerine, ‹Mirasçı budur, gelin onu öldürelim, miras bizim olur› dediler.'),
(2007837,68,41,12,8,'Böylece onu yakaladılar, öldürüp bağdan dışarı attılar.'),
(2007838,68,41,12,9,'‹‹Bu durumda bağın sahibi ne yapacak? Gelip bağcıları yok edecek, bağı da başkalarına verecek.'),
(2007839,68,41,12,10,'Şu Kutsal Yazıyı okumadınız mı? ‹Yapıcıların reddettiği taş, İşte köşenin baş taşı oldu. Rabbin işidir bu, Gözümüzde harika bir iş!› ››'),
(2007840,68,41,12,12,'İsanın bu benzetmede kendilerinden söz ettiğini anlayan Yahudi önderler Onu tutuklamak istediler; ama halkın tepkisinden korktukları için Onu bırakıp gittiler.'),
(2007841,68,41,12,13,'Daha sonra İsayı söyleyeceği sözlerle tuzağa düşürmek amacıyla Ferisilerden ve Hirodes yanlılarından bazılarını Ona gönderdiler.'),
(2007842,68,41,12,14,'Bunlar gelip İsaya, ‹‹Öğretmenimiz›› dediler, ‹‹Senin dürüst biri olduğunu, kimseyi kayırmadan, insanlar arasında ayrım yapmadan Tanrı yolunu dürüstçe öğrettiğini biliyoruz. Sezara vergi vermek Kutsal Yasaya uygun mu, değil mi? Verelim mi, vermeyelim mi?››'),
(2007843,68,41,12,15,'Onların ikiyüzlülüğünü bilen İsa şöyle dedi: ‹‹Beni neden deniyorsunuz? Bana bir dinar getirin bakayım.››'),
(2007844,68,41,12,16,'Parayı getirdiler. İsa, ‹‹Bu resim, bu yazı kimin?›› diye sordu. ‹‹Sezarın›› dediler.'),
(2007845,68,41,12,17,'İsa da, ‹‹Sezarın hakkını Sezara, Tanrının hakkını Tanrıya verin›› dedi. İsanın sözlerine şaşakaldılar.'),
(2007846,68,41,12,18,'Ölümden sonra diriliş olmadığını söyleyen Sadukiler İsaya gelip şunu sordular: ‹‹Öğretmenimiz, Musa yazılarında bize şöyle buyurmuştur: ‹Eğer bir adam ölür, geride bir dul bırakır, ama çocuk bırakmazsa, kardeşi onun karısını alıp soyunu sürdürsün.›'),
(2007847,68,41,12,20,'Yedi kardeş vardı. Birincisi evlendi ve çocuk bırakmadan öldü.'),
(2007848,68,41,12,21,'İkincisi aynı kadını aldı, o da çocuk sahibi olmadan öldü. Üçüncüsüne de öyle oldu.'),
(2007849,68,41,12,22,'Yedisi de çocuksuz öldü. Hepsinden sonra kadın da öldü.'),
(2007850,68,41,12,23,'Diriliş günü, ölümden dirildiklerinde kadın bunlardan hangisinin karısı olacak? Çünkü yedisi de onunla evlendi.››'),
(2007851,68,41,12,24,'İsa onlara şöyle karşılık verdi: ‹‹Ne Kutsal Yazıları ne de Tanrının gücünü biliyorsunuz. Yanılmanızın nedeni de bu değil mi?'),
(2007852,68,41,12,25,'İnsanlar ölümden dirilince ne evlenir ne evlendirilir, göklerdeki melekler gibidirler.'),
(2007853,68,41,12,26,'Ölülerin dirilmesi konusuna gelince, Musanın Kitabında, alevlenen çalıyla ilgili bölümde Tanrının Musaya söylediklerini okumadınız mı? ‹Ben İbrahimin Tanrısı, İshakın Tanrısı ve Yakupun Tanrısıyım› diyor.'),
(2007854,68,41,12,27,'Tanrı ölülerin değil, dirilerin Tanrısıdır. Siz büyük bir yanılgı içindesiniz.››'),
(2007855,68,41,12,28,'Onların tartışmalarını dinleyen ve İsanın onlara güzel yanıt verdiğini gören bir din bilgini yaklaşıp Ona, ‹‹Buyrukların en önemlisi hangisidir?›› diye sordu.'),
(2007856,68,41,12,29,'İsa şöyle karşılık verdi: ‹‹En önemlisi şudur: ‹Dinle, ey İsrail! Tanrımız Rab tek Rabdir.'),
(2007857,68,41,12,30,'Tanrın Rabbi bütün yüreğinle, bütün canınla, bütün aklınla ve bütün gücünle seveceksin.›'),
(2007858,68,41,12,31,'İkincisi de şudur: ‹Komşunu kendin gibi seveceksin.› Bunlardan daha büyük buyruk yoktur.››'),
(2007859,68,41,12,32,'Din bilgini İsaya, ‹‹İyi söyledin, öğretmenim›› dedi. ‹‹ ‹Tanrı tektir ve Ondan başkası yoktur› demekle doğruyu söyledin.'),
(2007860,68,41,12,33,'İnsanın Tanrıyı bütün yüreğiyle, bütün anlayışıyla ve bütün gücüyle sevmesi, komşusunu da kendi gibi sevmesi, bütün yakmalık sunulardan ve kurbanlardan daha önemlidir.››'),
(2007861,68,41,12,34,'İsa onun akıllıca yanıt verdiğini görünce, ‹‹Sen Tanrının Egemenliğinden uzak değilsin›› dedi. Bundan sonra kimse Ona soru sormaya cesaret edemedi.'),
(2007862,68,41,12,35,'İsa tapınakta öğretirken şunu sordu: ‹‹Nasıl oluyor da din bilginleri, ‹Mesih, Davutun Oğludur› diyorlar?'),
(2007863,68,41,12,36,'Davutun kendisi, Kutsal Ruhtan esinlenerek şöyle demişti: ‹Rab Rabbime dedi ki, Ben düşmanlarını Ayaklarının altına serinceye dek Sağımda otur.›'),
(2007864,68,41,12,37,'Davutun kendisi Ondan Rab diye söz ettiğine göre, O nasıl Davutun Oğlu olur?›› Oradaki büyük kalabalık Onu zevkle dinliyordu.'),
(2007865,68,41,12,38,'İsa öğretirken şöyle dedi: ‹‹Uzun kaftanlar içinde dolaşmaktan, meydanlarda selamlanmaktan, havralarda en seçkin yerlere ve şölenlerde başköşelere kurulmaktan hoşlanan din bilginlerinden sakının.'),
(2007866,68,41,12,40,'Dul kadınların malını mülkünü sömüren, gösteriş için uzun uzun dua eden bu kişilerin cezası daha ağır olacaktır.››'),
(2007867,68,41,12,41,'İsa tapınakta bağış toplanan yerin karşısında oturmuş, kutulara para atan halkı seyrediyordu. Birçok zengin kişi kutuya bol para attı.'),
(2007868,68,41,12,42,'Yoksul bir dul kadın da geldi, birkaç kuruş değerinde iki bakır para attı.'),
(2007869,68,41,12,43,'İsa öğrencilerini yanına çağırarak, ‹‹Size doğrusunu söyleyeyim›› dedi, ‹‹Bu yoksul dul kadın kutuya herkesten daha çok para attı.'),
(2007870,68,41,12,44,'Çünkü ötekilerin hepsi, zenginliklerinden artanı attılar. Bu kadın ise yoksulluğuna karşın, varını yoğunu, geçinmek için elinde ne varsa, tümünü verdi.››'),
(2007871,68,41,13,1,'İsa tapınaktan çıkarken öğrencilerinden biri Ona, ‹‹Öğretmenim›› dedi, ‹‹Şu güzel taşlara, şu görkemli yapılara bak!››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007872,68,41,13,2,'İsa ona, ‹‹Bu büyük yapıları görüyor musun? Burada taş üstünde taş kalmayacak, hepsi yıkılacak!›› dedi.'),
(2007873,68,41,13,3,'İsa, Zeytin Dağında, tapınağın karşısında otururken Petrus, Yakup, Yuhanna ve Andreas özel olarak kendisine şunu sordular: ‹‹Söyle bize, bu dediklerin ne zaman olacak, bütün bunların gerçekleşmek üzere olduğunu gösteren belirti ne olacak?››'),
(2007874,68,41,13,5,'İsa onlara anlatmaya başladı: ‹‹Sakın kimse sizi saptırmasın›› dedi.'),
(2007875,68,41,13,6,'‹‹Birçokları, ‹Ben Oyum› diyerek benim adımla gelip birçok kişiyi saptıracaklar.'),
(2007876,68,41,13,7,'Savaş gürültüleri, savaş haberleri duyunca korkmayın. Bunların olması gerek, ama bu daha son demek değildir.'),
(2007877,68,41,13,8,'Ulus ulusa, devlet devlete savaş açacak; yer yer depremler, kıtlıklar olacak. Bunlar, doğum sancılarının başlangıcıdır.'),
(2007878,68,41,13,9,'‹‹Ama siz kendinize dikkat edin! İnsanlar sizi mahkemelere verecek, havralarda dövecekler. Benden ötürü valilerin, kralların önüne çıkarılacak, böylece onlara tanıklık edeceksiniz.'),
(2007879,68,41,13,10,'Ne var ki, önce Müjdenin bütün uluslara duyurulması gerekir.'),
(2007880,68,41,13,11,'Sizi tutuklayıp mahkemeye verdiklerinde, ‹Ne söyleyeceğiz?› diye önceden kaygılanmayın. O anda size ne esinlenirse onu söyleyin. Çünkü konuşan siz değil, Kutsal Ruh olacak.'),
(2007881,68,41,13,12,'Kardeş kardeşi, baba çocuğunu ölüme teslim edecek. Çocuklar anne babalarına başkaldırıp onları öldürtecek.'),
(2007882,68,41,13,13,'Benim adımdan ötürü herkes sizden nefret edecek. Ama sonuna kadar dayanan kurtulacaktır.'),
(2007883,68,41,13,14,'‹‹Yıkıcı iğrenç şeyin, bulunmaması gereken yerde dikildiğini gördüğünüz zaman -okuyan anlasın- Yahudiyede bulunanlar dağlara kaçsın.'),
(2007884,68,41,13,15,'Damda olan, evinden bir şey almak için aşağı inmesin, içeri girmesin.'),
(2007885,68,41,13,16,'Tarlada olan, abasını almak için geri dönmesin.'),
(2007886,68,41,13,17,'O günlerde gebe olan, çocuk emziren kadınların vay haline!'),
(2007887,68,41,13,18,'Dua edin ki, kaçışınız kışa rastlamasın.'),
(2007888,68,41,13,19,'Çünkü o günlerde öyle bir sıkıntı olacak ki, Tanrının var ettiği yaratılışın başlangıcından bu yana böylesi olmamış, bundan sonra da olmayacaktır.'),
(2007889,68,41,13,20,'Rab o günleri kısaltmamış olsaydı, hiç kimse kurtulamazdı. Ama Rab, seçilmiş olanlar, kendi seçtiği kişiler uğruna o günleri kısaltmıştır.'),
(2007890,68,41,13,21,'Eğer o zaman biri size, ‹İşte Mesih burada›, ya da, ‹İşte şurada› derse, inanmayın.'),
(2007891,68,41,13,22,'Çünkü sahte mesihler, sahte peygamberler türeyecek; bunlar, belirtiler ve harikalar yapacaklar. Öyle ki, ellerinden gelse seçilmiş olanları saptıracaklar.'),
(2007892,68,41,13,23,'Ama siz dikkatli olun. İşte size her şeyi önceden söylüyorum.››'),
(2007893,68,41,13,24,'‹‹Ama o günlerde, o sıkıntıdan sonra, ‹Güneş kararacak, Ay ışık vermez olacak, Yıldızlar gökten düşecek, Göksel güçler sarsılacak.›'),
(2007894,68,41,13,26,'‹‹O zaman İnsanoğlunun bulutlar içinde büyük güç ve görkemle geldiğini görecekler.'),
(2007895,68,41,13,27,'İnsanoğlu o zaman meleklerini gönderecek, seçtiklerini yeryüzünün bir ucundan göğün öbür ucuna dek, dünyanın dört bucağından toplayacak.'),
(2007896,68,41,13,28,'‹‹İncir ağacından ders alın. Dalları filizlenip yaprakları sürünce, yaz mevsiminin yakın olduğunu anlarsınız.'),
(2007897,68,41,13,29,'Aynı şekilde, bu olayların gerçekleştiğini gördüğünüzde bilin ki İnsanoğlu yakındır, kapıdadır.'),
(2007898,68,41,13,30,'Size doğrusunu söyleyeyim, bütün bunlar olmadan bu kuşak ortadan kalkmayacak.'),
(2007899,68,41,13,31,'Yer ve gök ortadan kalkacak, ama benim sözlerim asla ortadan kalkmayacaktır.››'),
(2007900,68,41,13,32,'‹‹O günü ve o saati, ne gökteki melekler, ne de Oğul bilir; Babadan başka kimse bilmez.'),
(2007901,68,41,13,33,'Dikkat edin, uyanık kalın, dua edin. Çünkü o anın ne zaman geleceğini bilemezsiniz.'),
(2007902,68,41,13,34,'Bu, yolculuğa çıkan bir adamın durumuna benzer. Evinden ayrılırken kölelerine yetki ve görev verir, kapıdaki nöbetçiye de uyanık kalmasını buyurur.'),
(2007903,68,41,13,35,'Siz de uyanık kalın. Çünkü ev sahibi ne zaman gelecek, akşam mı, gece yarısı mı, horoz öttüğünde mi, sabaha doğru mu, bilemezsiniz.'),
(2007904,68,41,13,36,'Ansızın gelip sizi uykuda bulmasın!'),
(2007905,68,41,13,37,'Size söylediklerimi herkese söylüyorum; uyanık kalın!››'),
(2007906,68,41,14,1,'Fısıh ve Mayasız Ekmek Bayramına iki gün kalmıştı. Başkâhinlerle din bilginleri İsayı hileyle tutuklayıp öldürmenin bir yolunu arıyorlardı.'),
(2007907,68,41,14,2,'‹‹Bayramda olmasın, yoksa halk arasında kargaşalık çıkar›› diyorlardı.'),
(2007908,68,41,14,3,'İsa Beytanyada cüzamlı Simunun evinde sofrada otururken yanına bir kadın geldi. Kadın kaymaktaşından bir kap içinde çok değerli, saf hintsümbülü yağı getirmişti. Kabı kırarak yağı Onun başına döktü.'),
(2007909,68,41,14,4,'Bazıları buna kızdılar; birbirlerine, ‹‹Bu yağ niçin böyle boş yere harcandı? Üç yüz dinardan fazlaya satılabilir, parası yoksullara verilebilirdi›› diyerek kadını azarlamaya başladılar.'),
(2007910,68,41,14,6,'‹‹Kadını rahat bırakın›› dedi İsa. ‹‹Neden üzüyorsunuz onu? Benim için güzel bir şey yaptı.'),
(2007911,68,41,14,7,'Yoksullar her zaman aranızdadır, dilediğiniz anda onlara yardım edebilirsiniz; ama ben her zaman aranızda olmayacağım.'),
(2007912,68,41,14,8,'Kadın elinden geleni yaptı, beni gömülmeye hazırlamak üzere daha şimdiden bedenimi yağladı.'),
(2007913,68,41,14,9,'Size doğrusunu söyleyeyim, Müjde dünyanın neresinde duyurulursa, bu kadının yaptığı da onun anılması için anlatılacak.››'),
(2007914,68,41,14,10,'Bu arada Onikilerden biri olan Yahuda İskariot, İsayı ele vermek amacıyla başkâhinlerin yanına gitti.'),
(2007915,68,41,14,11,'Onlar bunu işitince sevindiler, Yahudaya para vermeyi vaat ettiler. O da İsayı ele vermek için fırsat kollamaya başladı.'),
(2007916,68,41,14,12,'Fısıh kurbanının kesildiği Mayasız Ekmek Bayramının ilk günü öğrencileri İsaya, ‹‹Fısıh yemeğini yemen için nereye gidip hazırlık yapmamızı istersin?›› diye sordular.'),
(2007917,68,41,14,13,'O da öğrencilerinden ikisini şu sözlerle önden gönderdi: ‹‹Kente gidin, orada su testisi taşıyan bir adam çıkacak karşınıza. Onu izleyin.'),
(2007918,68,41,14,14,'Adamın gideceği evin sahibine şöyle deyin: ‹Öğretmen, öğrencilerimle birlikte Fısıh yemeğini yiyeceğim konuk odası nerede? diye soruyor.›'),
(2007919,68,41,14,15,'Ev sahibi size üst katta döşenmiş, hazır büyük bir oda gösterecek. Orada bizim için hazırlık yapın.››'),
(2007920,68,41,14,16,'Öğrenciler yola çıkıp kente gittiler. Her şeyi, İsanın kendilerine söylediği gibi buldular ve Fısıh yemeği için hazırlık yaptılar.'),
(2007921,68,41,14,17,'Akşam olunca İsa Onikilerle birlikte geldi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007922,68,41,14,18,'Sofraya oturmuş yemek yerlerken İsa, ‹‹Size doğrusunu söyleyeyim›› dedi, ‹‹Sizden biri, benimle yemek yiyen biri bana ihanet edecek.››'),
(2007923,68,41,14,19,'Onlar da kederlenerek birer birer kendisine, ‹‹Beni demek istemedin ya?›› diye sormaya başladılar.'),
(2007924,68,41,14,20,'İsa onlara, ‹‹Onikilerden biridir, ekmeğini benimle birlikte sahana batırandır›› dedi.'),
(2007925,68,41,14,21,'‹‹Evet, İnsanoğlu kendisi için yazılmış olduğu gibi gidiyor, ama İnsanoğluna ihanet edenin vay haline! O adam hiç doğmamış olsaydı, kendisi için daha iyi olurdu.››'),
(2007926,68,41,14,22,'İsa yemek sırasında eline ekmek aldı, şükredip ekmeği böldü ve, ‹‹Alın, bu benim bedenimdir›› diyerek öğrencilerine verdi.'),
(2007927,68,41,14,23,'Sonra bir kâse alıp şükretti ve bunu öğrencilerine verdi. Hepsi bundan içti.'),
(2007928,68,41,14,24,'‹‹Bu benim kanım›› dedi İsa, ‹‹Birçokları uğruna akıtılan antlaşma kanıdır.'),
(2007929,68,41,14,25,'Size doğrusunu söyleyeyim, Tanrının Egemenliğinde tazesini içeceğim o güne dek, asmanın ürününden bir daha içmeyeceğim.››'),
(2007930,68,41,14,26,'İlahi söyledikten sonra dışarı çıkıp Zeytin Dağına doğru gittiler.'),
(2007931,68,41,14,27,'Bu arada İsa öğrencilerine, ‹‹Hepiniz sendeleyip düşeceksiniz›› dedi. ‹‹Çünkü şöyle yazılmıştır: ‹Çobanı vuracağım, Koyunlar darmadağın olacak.›'),
(2007932,68,41,14,28,'Ama ben dirildikten sonra sizden önce Celileye gideceğim.››'),
(2007933,68,41,14,29,'Petrus Ona, ‹‹Herkes sendeleyip düşse bile ben düşmem›› dedi.'),
(2007934,68,41,14,30,'‹‹Sana doğrusunu söyleyeyim›› dedi İsa, ‹‹Bugün, bu gece, horoz iki kez ötmeden sen beni üç kez inkâr edeceksin.››'),
(2007935,68,41,14,31,'Ama Petrus üsteleyerek, ‹‹Seninle birlikte ölmem gerekse bile seni asla inkâr etmem›› dedi. Öğrencilerin hepsi de aynı şeyi söyledi.'),
(2007936,68,41,14,32,'Sonra Getsemani denilen yere geldiler. İsa öğrencilerine, ‹‹Ben dua ederken siz burada oturun›› dedi.'),
(2007937,68,41,14,33,'Petrusu, Yakupu ve Yuhannayı yanına aldı. Hüzünlenmeye ve ağır bir sıkıntı duymaya başlamıştı.'),
(2007938,68,41,14,34,'Onlara, ‹‹Ölesiye kederliyim›› dedi. ‹‹Burada kalın, uyanık durun.››'),
(2007939,68,41,14,35,'Biraz ilerledi, yüzüstü yere kapanıp dua etmeye başladı. ‹‹Mümkünse o saati yaşamayayım›› dedi.'),
(2007940,68,41,14,36,'‹‹Abba, Baba, senin için her şey mümkün, bu kâseyi benden uzaklaştır. Ama benim değil, senin istediğin olsun.››'),
(2007941,68,41,14,37,'Öğrencilerinin yanına döndüğünde onları uyumuş buldu. Petrusa, ‹‹Simun›› dedi, ‹‹Uyuyor musun? Bir saat uyanık kalamadın mı?'),
(2007942,68,41,14,38,'Uyanık durup dua edin ki, ayartılmayasınız. Ruh isteklidir, ama beden güçsüzdür.››'),
(2007943,68,41,14,39,'Yine uzaklaştı, aynı sözleri tekrarlayarak dua etti.'),
(2007944,68,41,14,40,'Geri geldiğinde öğrencilerini yine uyumuş buldu. Onların göz kapaklarına ağırlık çökmüştü. İsaya ne diyeceklerini bilemiyorlardı.'),
(2007945,68,41,14,41,'İsa üçüncü kez yanlarına döndü, ‹‹Hâlâ uyuyor, dinleniyor musunuz?›› dedi. ‹‹Yeter! Saat geldi. İşte İnsanoğlu günahkârların eline veriliyor.'),
(2007946,68,41,14,42,'Kalkın, gidelim. İşte bana ihanet eden geldi!››'),
(2007947,68,41,14,43,'Tam o anda, İsa daha konuşurken, Onikilerden biri olan Yahuda çıkageldi. Yanında başkâhinler, din bilginleri ve ileri gelenler tarafından gönderilmiş kılıçlı sopalı bir kalabalık vardı.'),
(2007948,68,41,14,44,'İsaya ihanet eden Yahuda, ‹‹Kimi öpersem, İsa Odur. Onu tutuklayın, güvenlik altına alıp götürün›› diye onlarla sözleşmişti.'),
(2007949,68,41,14,45,'Gelir gelmez İsaya yaklaştı, ‹‹Rabbî›› diyerek Onu öptü.'),
(2007950,68,41,14,46,'Onlar da İsayı yakalayıp tutukladılar.'),
(2007951,68,41,14,47,'İsanın yanında bulunanlardan biri kılıcını çekti, başkâhinin kölesine vurup kulağını uçurdu.'),
(2007952,68,41,14,48,'İsa onlara, ‹‹Niçin bir haydutmuşum gibi beni kılıç ve sopalarla yakalamaya geldiniz?›› dedi.'),
(2007953,68,41,14,49,'‹‹Her gün tapınakta, yanıbaşınızda öğretiyordum, beni tutuklamadınız. Ama bu, Kutsal Yazılar yerine gelsin diye oldu.››'),
(2007954,68,41,14,50,'O zaman öğrencilerinin hepsi Onu bırakıp kaçtı.'),
(2007955,68,41,14,51,'İsanın ardından sadece keten beze sarınmış bir genç gidiyordu. Bu genç de yakalandı.'),
(2007956,68,41,14,52,'Ama keten bezden sıyrılıp çıplak olarak kaçtı.'),
(2007957,68,41,14,53,'İsayı görevli başkâhine götürdüler. Bütün başkâhinler, ileri gelenler ve din bilginleri de orada toplandı.'),
(2007958,68,41,14,54,'Petrus, İsayı başkâhinin avlusunun içine kadar uzaktan izledi. Avluda nöbetçilerle birlikte ateşin başında oturup ısınmaya başladı.'),
(2007959,68,41,14,55,'Başkâhinler ve Yüksek Kurulun öteki üyeleri, İsayı ölüm cezasına çarptırmak için kendisine karşı tanık arıyor, ama bulamıyorlardı.'),
(2007960,68,41,14,56,'Birçok kişi Ona karşı yalan yere tanıklık ettiyse de, tanıklıkları birbirini tutmadı.'),
(2007961,68,41,14,57,'Bazıları kalkıp Ona karşı yalan yere şöyle tanıklık ettiler: ‹‹Biz Onun, ‹Elle yapılmış bu tapınağı yıkacağım ve üç günde, elle yapılmamış başka bir tapınak kuracağım› dediğini işittik.››'),
(2007962,68,41,14,59,'Ama bu noktada bile tanıklıkları birbirini tutmadı.'),
(2007963,68,41,14,60,'Sonra başkâhin topluluğun ortasında ayağa kalkarak İsaya, ‹‹Hiç yanıt vermeyecek misin? Nedir bunların sana karşı ettiği bu tanıklıklar?›› diye sordu.'),
(2007964,68,41,14,61,'Ne var ki, İsa susmaya devam etti, hiç yanıt vermedi. Başkâhin Ona yeniden, ‹‹Yüce Olanın Oğlu Mesih sen misin?›› diye sordu.'),
(2007965,68,41,14,62,'İsa, ‹‹Benim›› dedi. ‹‹Ve sizler, İnsanoğlunun Kudretli Olanın sağında oturduğunu ve göğün bulutlarıyla geldiğini göreceksiniz.››'),
(2007966,68,41,14,63,'Başkâhin giysilerini yırtarak, ‹‹Artık tanıklara ne ihtiyacımız var?›› dedi. ‹‹Küfürü işittiniz. Buna ne diyorsunuz?›› Hepsi İsanın ölüm cezasını hak ettiğine karar verdiler.'),
(2007967,68,41,14,65,'Bazıları Onun üzerine tükürmeye, gözlerini bağlayarak Onu yumruklamaya başladılar. ‹‹Haydi, peygamberliğini göster!›› diyorlardı. Nöbetçiler de Onu aralarına alıp tokatladılar.'),
(2007968,68,41,14,66,'Petrus aşağıda, avludayken, başkâhinin hizmetçi kızlarından biri geldi. Isınmakta olan Petrusu görünce onu dikkatle süzüp, ‹‹Sen de Nasıralı İsayla birlikteydin›› dedi.'),
(2007969,68,41,14,68,'Petrus ise bunu inkâr ederek, ‹‹Senin neden söz ettiğini bilmiyorum, anlamıyorum›› dedi ve dışarıya, dış kapının önüne çıktı. Bu arada horoz öttü.'),
(2007970,68,41,14,69,'Hizmetçi kız Petrusu görünce çevrede duranlara yine, ‹‹Bu adam onlardan biri›› demeye başladı.'),
(2007971,68,41,14,70,'Petrus tekrar inkâr etti. Çevrede duranlar az sonra Petrusa yine, ‹‹Gerçekten onlardansın; sen de Celilelisin›› dediler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2007972,68,41,14,71,'Petrus kendine lanet okuyup ant içerek, ‹‹Sözünü ettiğiniz o adamı tanımıyorum›› dedi.'),
(2007973,68,41,14,72,'Tam o anda horoz ikinci kez öttü. Petrus, İsa''nın kendisine, ‹‹Horoz iki kez ötmeden beni üç kez inkâr edeceksin›› dediğini hatırladı ve hüngür hüngür ağlamaya başladı.'),
(2007974,68,41,15,1,'Sabah olunca başkâhinler, ileri gelenler, din bilginleri ve Yüksek Kurulun öteki üyeleri bir danışma toplantısı yaptıktan sonra İsayı bağladılar, götürüp Pilatusa teslim ettiler.'),
(2007975,68,41,15,2,'Pilatus Ona, ‹‹Sen Yahudilerin Kralı mısın?›› diye sordu. İsa, ‹‹Söylediğin gibidir›› yanıtını verdi.'),
(2007976,68,41,15,3,'Başkâhinler Ona karşı birçok suçlamada bulundular.'),
(2007977,68,41,15,4,'Pilatus Ona yeniden, ‹‹Hiç yanıt vermeyecek misin?›› diye sordu. ‹‹Bak, seni ne çok şeyle suçluyorlar!››'),
(2007978,68,41,15,5,'Ama İsa artık yanıt vermiyordu. Pilatus buna şaştı.'),
(2007979,68,41,15,6,'Pilatus, her Fısıh Bayramında halkın istediği bir tutukluyu salıverirdi.'),
(2007980,68,41,15,7,'Ayaklanma sırasında adam öldüren isyancılarla birlikte Barabba adında bir tutuklu da vardı.'),
(2007981,68,41,15,8,'Halk, Pilatusa gelip her zamanki gibi kendileri için birini salıvermesini istedi.'),
(2007982,68,41,15,9,'Pilatus onlara, ‹‹Sizin için Yahudilerin Kralını salıvermemi ister misiniz?›› dedi.'),
(2007983,68,41,15,10,'Başkâhinlerin İsayı kıskançlıktan ötürü kendisine teslim ettiklerini biliyordu.'),
(2007984,68,41,15,11,'Ne var ki başkâhinler, İsanın değil, Barabbanın salıverilmesini istemeleri için halkı kışkırttılar.'),
(2007985,68,41,15,12,'Pilatus onlara tekrar seslenerek, ‹‹Öyleyse Yahudilerin Kralı dediğiniz adamı ne yapayım?›› diye sordu.'),
(2007986,68,41,15,13,'‹‹Onu çarmıha ger!›› diye bağırdılar yine.'),
(2007987,68,41,15,14,'Pilatus onlara, ‹‹O ne kötülük yaptı ki?›› dedi. Onlar ise daha yüksek sesle, ‹‹Onu çarmıha ger!›› diye bağrıştılar.'),
(2007988,68,41,15,15,'Halkı memnun etmek isteyen Pilatus, onlar için Barabbayı salıverdi. İsayı ise kamçılattıktan sonra çarmıha gerilmek üzere askerlere teslim etti.'),
(2007989,68,41,15,16,'Askerler İsayı, Pretorium denilen vali konağına götürüp bütün taburu topladılar.'),
(2007990,68,41,15,17,'Ona mor bir giysi giydirdiler, dikenlerden bir taç örüp başına geçirdiler.'),
(2007991,68,41,15,18,'‹‹Selam, ey Yahudilerin Kralı!›› diyerek Onu selamlamaya başladılar.'),
(2007992,68,41,15,19,'Başına bir kamışla vuruyor, üzerine tükürüyor, diz çöküp önünde yere kapanıyorlardı.'),
(2007993,68,41,15,20,'Onunla böyle alay ettikten sonra mor giysiyi üzerinden çıkarıp kendi giysilerini giydirdiler ve çarmıha germek üzere Onu dışarı götürdüler.'),
(2007994,68,41,15,21,'Kırdan gelmekte olan Simun adında Kireneli bir adam oradan geçiyordu. İskender ve Rufusun babası olan bu adama İsanın çarmıhını zorla taşıttılar.'),
(2007995,68,41,15,22,'İsayı Golgota, yani Kafatası denilen yere götürdüler.'),
(2007996,68,41,15,23,'Ona mürle karışık şarap vermek istediler, ama içmedi.'),
(2007997,68,41,15,24,'Sonra Onu çarmıha gerdiler. Kim ne alacak diye kura çekerek giysilerini aralarında paylaştılar.'),
(2007998,68,41,15,25,'İsayı çarmıha gerdiklerinde saat dokuzdu.'),
(2007999,68,41,15,26,'Üzerindeki suç yaftasında,'),
(2008000,68,41,15,27,'İsayla birlikte, biri sağında öbürü solunda olmak üzere iki haydudu da çarmıha gerdiler.'),
(2008001,68,41,15,29,'Oradan geçenler başlarını sallayıp İsaya sövüyor, ‹‹Hani sen tapınağı yıkıp üç günde yeniden kuracaktın? Çarmıhtan in de kurtar kendini!›› diyorlardı.'),
(2008002,68,41,15,31,'Aynı şekilde başkâhinler ve din bilginleri de Onunla alay ederek aralarında, ‹‹Başkalarını kurtardı, kendini kurtaramıyor›› diye konuşuyorlardı.'),
(2008003,68,41,15,32,'‹‹İsrailin Kralı Mesih şimdi çarmıhtan insin de görüp iman edelim.›› İsayla birlikte çarmıha gerilenler de Ona hakaret ettiler.'),
(2008004,68,41,15,33,'Öğleyin on ikiden üçe kadar bütün ülkenin üzerine karanlık çöktü.'),
(2008005,68,41,15,34,'Saat üçte İsa yüksek sesle, ‹‹Elohi, Elohi, lema şevaktani›› yani, ‹‹Tanrım, Tanrım, beni neden terk ettin?›› diye bağırdı.'),
(2008006,68,41,15,35,'Orada duranlardan bazıları bunu işitince, ‹‹Bakın, İlyası çağırıyor›› dediler.'),
(2008007,68,41,15,36,'Aralarından biri koşup bir süngeri ekşi şaraba batırdı, bir kamışın ucuna takarak İsaya içirdi. ‹‹Dur bakalım, İlyas gelip Onu indirecek mi?›› dedi.'),
(2008008,68,41,15,37,'Ama İsa yüksek sesle bağırarak son nefesini verdi.'),
(2008009,68,41,15,38,'O anda tapınaktaki perde yukarıdan aşağıya yırtılarak ikiye bölündü.'),
(2008010,68,41,15,39,'İsanın karşısında duran yüzbaşı, Onun bu şekilde son nefesini verdiğini görünce, ‹‹Bu adam gerçekten Tanrının Oğluydu›› dedi.'),
(2008011,68,41,15,40,'Olup bitenleri uzaktan izleyen bazı kadınlar da vardı. Aralarında Mecdelli Meryem, küçük Yakup ile Yosenin annesi Meryem ve Salome bulunuyordu.'),
(2008012,68,41,15,41,'İsa daha Celiledeyken bu kadınlar Onun ardından gitmiş, Ona hizmet etmişlerdi. Onunla birlikte Yeruşalime gelmiş olan daha birçok kadın da olup bitenleri izliyordu.'),
(2008013,68,41,15,42,'O gün Hazırlık Günü, yani Şabat Gününden önceki gündü. Artık akşam oluyordu. Bu nedenle, Yüksek Kurulun saygın bir üyesi olup Tanrının Egemenliğini umutla bekleyen Aramatyalı Yusuf geldi, cesaretini toplayarak Pilatusun huzuruna çıktı, İsanın cesedini istedi.'),
(2008014,68,41,15,44,'Pilatus, İsanın bu kadar çabuk ölmüş olmasına şaştı. Yüzbaşıyı çağırıp, ‹‹Öleli çok oldu mu?›› diye sordu.'),
(2008015,68,41,15,45,'Yüzbaşıdan durumu öğrenince Yusufa, cesedi alması için izin verdi.'),
(2008016,68,41,15,46,'Yusuf keten bez satın aldı, cesedi çarmıhtan indirip beze sardı, kayaya oyulmuş bir mezara yatırarak mezarın girişine bir taş yuvarladı.'),
(2008017,68,41,15,47,'Mecdelli Meryem ile Yose''nin annesi Meryem, İsa''nın nereye konulduğunu gördüler.'),
(2008018,68,41,16,1,'Şabat Günü geçince, Mecdelli Meryem, Yakupun annesi Meryem ve Salome gidip İsanın cesedine sürmek üzere baharat satın aldılar.'),
(2008019,68,41,16,2,'Haftanın ilk günü sabah çok erkenden, güneşin doğuşuyla birlikte mezara gittiler.'),
(2008020,68,41,16,3,'Aralarında, ‹‹Mezarın girişindeki taşı bizim için kim yana yuvarlayacak?›› diye konuşuyorlardı.'),
(2008021,68,41,16,4,'Başlarını kaldırıp bakınca, o kocaman taşın yana yuvarlanmış olduğunu gördüler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008022,68,41,16,5,'Mezara girip sağ tarafta, beyaz kaftan giyinmiş genç bir adamın oturduğunu görünce çok şaşırdılar.'),
(2008023,68,41,16,6,'Adam onlara, ‹‹Şaşırmayın!›› dedi. ‹‹Çarmıha gerilen Nasıralı İsayı arıyorsunuz. O dirildi, burada yok. İşte Onu yatırdıkları yer.'),
(2008024,68,41,16,7,'Şimdi öğrencilerine ve Petrusa gidip şöyle deyin: ‹İsa sizden önce Celileye gidiyor. Size bildirdiği gibi, kendisini orada göreceksiniz.› ››'),
(2008025,68,41,16,8,'Kadınlar mezardan çıkıp kaçtılar. Onları bir titreme, bir şaşkınlık almıştı. Korkularından kimseye bir şey söylemediler.'),
(2008026,68,41,16,9,'İsa, haftanın ilk günü sabah erkenden dirildiği zaman önce Mecdelli Meryeme göründü. Ondan yedi cin kovmuştu.'),
(2008027,68,41,16,10,'Meryem gitti, İsayla bulunmuş olan, şimdiyse yas tutup gözyaşı döken öğrencilerine haberi verdi.'),
(2008028,68,41,16,11,'Ne var ki onlar, İsanın yaşadığını, Meryeme göründüğünü duyunca inanmadılar.'),
(2008029,68,41,16,12,'Bundan sonra İsa kırlara doğru yürümekte olan öğrencilerinden ikisine değişik bir biçimde göründü.'),
(2008030,68,41,16,13,'Bunlar geri dönüp öbürlerine haber verdiler, ama öbürleri bunlara da inanmadılar.'),
(2008031,68,41,16,14,'İsa daha sonra, sofrada otururlarken Onbirlere göründü. Onları imansızlıklarından ve yüreklerinin duygusuzluğundan ötürü azarladı. Çünkü kendisini diri görenlere inanmamışlardı.'),
(2008032,68,41,16,15,'İsa onlara şöyle buyurdu: ‹‹Dünyanın her yanına gidin, Müjdeyi bütün yaratılışa duyurun.'),
(2008033,68,41,16,16,'İman edip vaftiz olan kurtulacak, iman etmeyen ise hüküm giyecek.'),
(2008034,68,41,16,17,'İman edenlerle birlikte görülecek belirtiler şunlardır: Benim adımla cinleri kovacaklar, yeni dillerle konuşacaklar, yılanları elleriyle tutacaklar. Öldürücü bir zehir içseler bile, zarar görmeyecekler. Ellerini hastaların üzerine koyacaklar ve hastalar iyileşecek.››'),
(2008035,68,41,16,19,'Rab İsa, onlara bu sözleri söyledikten sonra göğe alındı ve Tanrının sağında oturdu.'),
(2008036,68,41,16,20,'Öğrencileri de gidip Tanrı sözünü her yere yaydılar. Rab onlarla birlikte çalışıyor, görülen belirtilerle sözünü doğruluyordu.'),
(2008037,68,42,1,1,'Sayın Teofilos, Birçok kişi aramızda olup bitenlerin tarihçesini yazmaya girişti. Nitekim başlangıçtan beri bu olayların görgü tanığı ve Tanrı sözünün hizmetkârı olanlar bunları bize ilettiler. Ben de bütün bu olayları ta başından özenle araştırmış biri olarak bunları sana sırasıyla yazmayı uygun gördüm.'),
(2008038,68,42,1,4,'Öyle ki, sana verilen bilgilerin doğruluğunu bilesin.'),
(2008039,68,42,1,5,'Yahudiye Kralı Hirodes zamanında, Aviya bölüğünden Zekeriya adında bir kâhin vardı. Harun soyundan gelen karısının adı ise Elizabetti.'),
(2008040,68,42,1,6,'Her ikisi de Tanrının gözünde doğru kişilerdi, Rabbin bütün buyruk ve kurallarına eksiksizce uyarlardı.'),
(2008041,68,42,1,7,'Elizabet kısır olduğu için çocukları olmuyordu. İkisinin de yaşı ilerlemişti.'),
(2008042,68,42,1,8,'Zekeriya, hizmet sırasının kendi bölüğünde olduğu bir gün, Tanrının önünde kâhinlik görevini yerine getiriyordu.'),
(2008043,68,42,1,9,'Kâhinlik geleneği uyarınca Rabbin Tapınağına girip buhur yakma görevi kurayla ona verilmişti.'),
(2008044,68,42,1,10,'Buhur yakma saatinde bütün halk topluluğu dışarıda dua ediyordu.'),
(2008045,68,42,1,11,'Bu sırada, Rabbin bir meleği buhur sunağının sağında durup Zekeriyaya göründü.'),
(2008046,68,42,1,12,'Zekeriya onu görünce şaşırdı, korkuya kapıldı.'),
(2008047,68,42,1,13,'Melek, ‹‹Korkma, Zekeriya›› dedi, ‹‹Duan kabul edildi. Karın Elizabet sana bir oğul doğuracak, adını Yahya koyacaksın.'),
(2008048,68,42,1,14,'Sevinip coşacaksın. Birçokları da onun doğumuna sevinecek.'),
(2008049,68,42,1,15,'O, Rabbin gözünde büyük olacak. Hiç şarap ve içki içmeyecek; daha annesinin rahmindeyken Kutsal Ruhla dolacak.'),
(2008050,68,42,1,16,'İsrailoğullarından birçoğunu, Tanrıları Rabbe döndürecek.'),
(2008051,68,42,1,17,'Babaların yüreklerini çocuklarına döndürmek, söz dinlemeyenleri doğru kişilerin anlayışına yöneltmek ve Rab için hazırlanmış bir halk yetiştirmek üzere, İlyasın ruhu ve gücüyle Rabbin önünden gidecektir.››'),
(2008052,68,42,1,18,'Zekeriya meleğe, ‹‹Bundan nasıl emin olabilirim?›› dedi. ‹‹Çünkü ben yaşlandım, karımın da yaşı ilerledi.››'),
(2008053,68,42,1,19,'Melek ona şöyle karşılık verdi: ‹‹Ben Tanrının huzurunda duran Cebrailim. Seninle konuşmak ve bu müjdeyi sana bildirmek için gönderildim.'),
(2008054,68,42,1,20,'İşte, belirlenen zamanda yerine gelecek olan sözlerime inanmadığın için dilin tutulacak, bunların gerçekleşeceği güne dek konuşamayacaksın.››'),
(2008055,68,42,1,21,'Zekeriyayı bekleyen halk, onun tapınakta bu kadar uzun süre kalmasına şaştı.'),
(2008056,68,42,1,22,'Zekeriya ise dışarı çıktığında onlarla konuşamadı. O zaman tapınakta bir görüm gördüğünü anladılar. Kendisi onlara işaretler yapıyor, ama konuşamıyordu.'),
(2008057,68,42,1,23,'Görev süresi bitince Zekeriya evine döndü.'),
(2008058,68,42,1,24,'Bir süre sonra karısı Elizabet gebe kaldı ve beş ay evine kapandı.'),
(2008059,68,42,1,25,'‹‹Bunu benim için yapan Rabdir›› dedi. ‹‹Bu günlerde benimle ilgilenerek insanlar arasında utancımı giderdi.››'),
(2008060,68,42,1,26,'Elizabetin hamileliğinin altıncı ayında Tanrı, Melek Cebraili Celilede bulunan Nasıra adlı kente, Davutun soyundan Yusuf adındaki adamla nişanlı kıza gönderdi. Kızın adı Meryemdi.'),
(2008061,68,42,1,28,'Onun yanına giren melek, ‹‹Selam, ey Tanrının lütfuna erişen kız! Rab seninledir›› dedi.'),
(2008062,68,42,1,29,'Söylenenlere çok şaşıran Meryem, bu selamın ne anlama gelebileceğini düşünmeye başladı.'),
(2008063,68,42,1,30,'Ama melek ona, ‹‹Korkma Meryem›› dedi, ‹‹Sen Tanrının lütfuna eriştin.'),
(2008064,68,42,1,31,'Bak, gebe kalıp bir oğul doğuracak, adını İsa koyacaksın.'),
(2008065,68,42,1,32,'O büyük olacak, kendisine ‹Yüceler Yücesinin Oğlu› denecek. Rab Tanrı Ona, atası Davutun tahtını verecek.'),
(2008066,68,42,1,33,'O da sonsuza dek Yakupun soyu üzerinde egemenlik sürecek, egemenliğinin sonu gelmeyecektir.››'),
(2008067,68,42,1,34,'Meryem meleğe, ‹‹Bu nasıl olur? Ben erkeğe varmadım ki›› dedi.'),
(2008068,68,42,1,35,'Melek ona şöyle yanıt verdi: ‹‹Kutsal Ruh senin üzerine gelecek, Yüceler Yücesinin gücü sana gölge salacak. Bunun için doğacak olana kutsal, Tanrı Oğlu denecek.'),
(2008069,68,42,1,36,'Bak, senin akrabalarından Elizabet de yaşlılığında bir oğula gebe kaldı. Kısır bilinen bu kadın şimdi altıncı ayındadır.'),
(2008070,68,42,1,37,'Tanrının yapamayacağı hiçbir şey yoktur.››'),
(2008071,68,42,1,38,'‹‹Ben Rabbin kuluyum›› dedi Meryem, ‹‹Bana dediğin gibi olsun.›› Bundan sonra melek onun yanından ayrıldı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008072,68,42,1,39,'O günlerde Meryem kalkıp aceleyle Yahudanın dağlık bölgesindeki bir kente gitti.'),
(2008073,68,42,1,40,'Zekeriyanın evine girip Elizabeti selamladı.'),
(2008074,68,42,1,41,'Elizabet Meryemin selamını duyunca rahmindeki çocuk hopladı. Kutsal Ruhla dolan Elizabet yüksek sesle şöyle dedi: ‹‹Kadınlar arasında kutsanmış bulunuyorsun, rahminin ürünü de kutsanmıştır!'),
(2008075,68,42,1,43,'Nasıl oldu da Rabbimin annesi yanıma geldi?'),
(2008076,68,42,1,44,'Bak, selamın kulaklarıma eriştiği an, çocuk rahmimde sevinçle hopladı.'),
(2008077,68,42,1,45,'İman eden kadına ne mutlu! Çünkü Rabbin ona söylediği sözler gerçekleşecektir.››'),
(2008078,68,42,1,46,'Meryem de şöyle dedi: ‹‹Canım Rabbi yüceltir; Ruhum, Kurtarıcım Tanrı sayesinde sevinçle coşar.'),
(2008079,68,42,1,48,'Çünkü O, sıradan biri olan kuluyla ilgilendi. İşte, bundan böyle bütün kuşaklar beni mutlu sayacak.'),
(2008080,68,42,1,49,'Çünkü Güçlü Olan, benim için büyük işler yaptı. Onun adı kutsaldır.'),
(2008081,68,42,1,50,'Kuşaklar boyunca kendisinden korkanlara merhamet eder.'),
(2008082,68,42,1,51,'Bileğiyle büyük işler yaptı; Gururluları yüreklerindeki kuruntularla darmadağın etti.'),
(2008083,68,42,1,52,'Hükümdarları tahtlarından indirdi, Sıradan insanları yükseltti.'),
(2008084,68,42,1,53,'Aç olanları iyiliklerle doyurdu, Zenginleri ise elleri boş çevirdi.'),
(2008085,68,42,1,54,'Atalarımıza söz verdiği gibi, İbrahime ve onun soyuna sonsuza dek Merhamet etmeyi unutmayarak Kulu İsrailin yardımına yetişti.››'),
(2008086,68,42,1,56,'Meryem, üç ay kadar Elizabetin yanında kaldı, sonra kendi evine döndü.'),
(2008087,68,42,1,57,'Elizabetin doğurma vakti geldi ve bir oğul doğurdu.'),
(2008088,68,42,1,58,'Komşularıyla akrabaları, Rabbin ona ne büyük merhamet gösterdiğini duyunca, onun sevincine katıldılar.'),
(2008089,68,42,1,59,'Sekizinci gün çocuğun sünnetine geldiler. Ona babası Zekeriyanın adını vereceklerdi.'),
(2008090,68,42,1,60,'Ama annesi, ‹‹Hayır, adı Yahya olacak›› dedi.'),
(2008091,68,42,1,61,'Ona, ‹‹Akrabaların arasında bu adı taşıyan kimse yok ki›› dediler.'),
(2008092,68,42,1,62,'Bunun üzerine babasına işaretle çocuğun adını ne koymak istediğini sordular.'),
(2008093,68,42,1,63,'Zekeriya bir yazı levhası istedi ve, ‹‹Adı Yahyadır›› diye yazdı. Herkes şaşakaldı.'),
(2008094,68,42,1,64,'O anda Zekeriyanın ağzı açıldı, dili çözüldü. Tanrıyı överek konuşmaya başladı.'),
(2008095,68,42,1,65,'Çevrede oturanların hepsi korkuya kapıldı. Bütün bu olaylar, Yahudiyenin dağlık bölgesinin her yanında konuşulur oldu.'),
(2008096,68,42,1,66,'Duyan herkes derin derin düşünüyor, ‹‹Acaba bu çocuk ne olacak?›› diyordu. Çünkü Rab onunla birlikteydi.'),
(2008097,68,42,1,67,'Çocuğun babası Zekeriya, Kutsal Ruhla dolarak şu peygamberlikte bulundu:'),
(2008098,68,42,1,68,'‹‹İsrailin Tanrısı Rabbe övgüler olsun! Çünkü halkının yardımına gelip onları fidyeyle kurtardı.'),
(2008099,68,42,1,69,'Eski çağlardan beri Kutsal peygamberlerinin ağzından bildirdiği gibi, Kulu Davutun soyundan Bizim için güçlü bir kurtarıcı çıkardı; Düşmanlarımızdan, Bizden nefret edenlerin hepsinin elinden Kurtuluşumuzu sağladı.'),
(2008100,68,42,1,72,'Böylece atalarımıza merhamet ederek Kutsal antlaşmasını anmış oldu.'),
(2008101,68,42,1,73,'Nitekim bizi düşmanlarımızın elinden kurtaracağına Ve ömrümüz boyunca Kendi önünde kutsallık ve doğruluk içinde, Korkusuzca kendisine tapınmamızı sağlayacağına dair Atamız İbrahime ant içerek söz vermişti.'),
(2008102,68,42,1,76,'Sen de, ey çocuk, Yüceler Yücesinin peygamberi diye anılacaksın. Rabbin yollarını hazırlamak üzere önünden gidecek Ve Onun halkına, Günahlarının bağışlanmasıyla kurtulacaklarını bildireceksin.'),
(2008103,68,42,1,78,'Çünkü Tanrımızın yüreği merhamet doludur. Onun merhameti sayesinde, Yücelerden doğan Güneş, Karanlıkta ve ölümün gölgesinde yaşayanlara ışık saçmak Ve ayaklarımızı esenlik yoluna yöneltmek üzere Yardımımıza gelecektir.››'),
(2008104,68,42,1,80,'Çocuk büyüyor, ruhsal yönden güçleniyordu. İsrail halkına görüneceği güne dek ıssız yerlerde yaşadı.'),
(2008105,68,42,2,1,'O günlerde Sezar Avgustus bütün Roma dünyasında bir nüfus sayımının yapılması için buyruk çıkardı.'),
(2008106,68,42,2,2,'Bu ilk sayım, Kiriniusun Suriye valiliği zamanında yapıldı.'),
(2008107,68,42,2,3,'Herkes yazılmak için kendi kentine gitti.'),
(2008108,68,42,2,4,'Böylece Yusuf da, Davutun soyundan ve torunlarından olduğu için Celilenin Nasıra Kentinden Yahudiye bölgesine, Davutun kenti Beytleheme gitti.'),
(2008109,68,42,2,5,'Orada, hamile olan nişanlısı Meryemle birlikte yazılacaktı.'),
(2008110,68,42,2,6,'Onlar oradayken, Meryemin doğurma vakti geldi ve ilk oğlunu doğurdu. Onu kundağa sarıp bir yemliğe yatırdı. Çünkü handa yer yoktu.'),
(2008111,68,42,2,8,'Aynı yörede, sürülerinin yanında nöbet tutarak geceyi kırlarda geçiren çobanlar vardı.'),
(2008112,68,42,2,9,'Rabbin bir meleği onlara göründü ve Rabbin görkemi çevrelerini aydınlattı. Büyük bir korkuya kapıldılar.'),
(2008113,68,42,2,10,'Melek onlara, ‹‹Korkmayın!›› dedi. ‹‹Size, bütün halkı çok sevindirecek bir haber müjdeliyorum: Bugün size, Davutun kentinde bir Kurtarıcı doğdu. Bu, Rab olan Mesihtir.'),
(2008114,68,42,2,12,'İşte size bir işaret: Kundağa sarılmış ve yemlikte yatan bir bebek bulacaksınız.››'),
(2008115,68,42,2,13,'Birdenbire meleğin yanında, göksel ordulardan oluşan büyük bir topluluk belirdi. Tanrıyı överek, ‹‹En yücelerde Tanrıya yücelik olsun, Yeryüzünde Onun hoşnut kaldığı insanlara Esenlik olsun!›› dediler.'),
(2008116,68,42,2,15,'Melekler yanlarından ayrılıp göğe çekildikten sonra çobanlar birbirlerine, ‹‹Haydi, Beytleheme gidelim, Rabbin bize bildirdiği bu olayı görelim›› dediler.'),
(2008117,68,42,2,16,'Aceleyle gidip Meryemle Yusufu ve yemlikte yatan bebeği buldular.'),
(2008118,68,42,2,17,'Onları görünce, çocukla ilgili kendilerine anlatılanları bildirdiler.'),
(2008119,68,42,2,18,'Bunu duyanların hepsi, çobanların söylediklerine şaşıp kaldılar.'),
(2008120,68,42,2,19,'Meryem ise bütün bu sözleri derin derin düşünerek yüreğinde saklıyordu.'),
(2008121,68,42,2,20,'Çobanlar, işitip gördüklerinin tümü için Tanrıyı yüceltip överek geri döndüler. Her şeyi, kendilerine anlatıldığı gibi bulmuşlardı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008122,68,42,2,21,'Sekizinci gün, çocuğu sünnet etme zamanı gelince, Ona İsa adı verildi. Bu, Onun anne rahmine düşmesinden önce meleğin kendisine verdiği isimdi.'),
(2008123,68,42,2,22,'Musanın Yasasına göre arınma günlerinin bitiminde Yusufla Meryem çocuğu Rabbe adamak için Yeruşalime götürdüler.'),
(2008124,68,42,2,23,'Nitekim Rabbin Yasasında, ‹‹İlk doğan her erkek çocuk Rabbe adanmış sayılacak›› diye yazılmıştır.'),
(2008125,68,42,2,24,'Ayrıca Rabbin Yasasında buyrulduğu gibi, kurban olarak ‹‹bir çift kumru ya da iki güvercin yavrusu›› sunacaklardı.'),
(2008126,68,42,2,25,'O sırada Yeruşalimde Şimon adında bir adam vardı. Doğru ve dindar biriydi. İsrailin avutulmasını özlemle bekliyordu. Kutsal Ruh onun üzerindeydi.'),
(2008127,68,42,2,26,'Rabbin Mesihini görmeden ölmeyeceği Kutsal Ruh aracılığıyla kendisine bildirilmişti.'),
(2008128,68,42,2,27,'Böylece Şimon, Ruhun yönlendirmesiyle tapınağa geldi. Küçük İsanın annesi babası, Kutsal Yasanın ilgili kuralını yerine getirmek üzere Onu içeri getirdiklerinde, Şimon Onu kucağına aldı, Tanrıyı överek şöyle dedi:'),
(2008129,68,42,2,29,'‹‹Ey Rabbim, verdiğin sözü tuttun; Artık ben, kulun huzur içinde ölebilirim.'),
(2008130,68,42,2,30,'Çünkü senin sağladığın, Bütün halkların gözü önünde hazırladığın kurtuluşu, Ulusları aydınlatıp Halkın İsraile yücelik kazandıracak ışığı Gözlerimle gördüm.››'),
(2008131,68,42,2,33,'İsanın annesiyle babası, Onun hakkında söylenenlere şaştılar.'),
(2008132,68,42,2,34,'Şimon onları kutsayıp çocuğun annesi Meryeme şöyle dedi: ‹‹Bu çocuk, İsrailde birçok kişinin düşmesine ya da yükselmesine yol açmak ve aleyhinde konuşulacak bir belirti olmak üzere belirlenmiştir.'),
(2008133,68,42,2,35,'Senin kalbine de adeta bir kılıç saplanacak. Bütün bunlar, birçoklarının yüreğindeki düşüncelerin açığa çıkması için olacak.››'),
(2008134,68,42,2,36,'Anna adında çok yaşlı bir kadın peygamber vardı. Aşer oymağından Fanuelin kızıydı. Genç kız olarak evlenip kocasıyla yedi yıl yaşadıktan sonra dul kalmıştı. Şimdi seksen dört yaşındaydı. Tapınaktan ayrılmaz, oruç tutup dua ederek gece gündüz Tanrıya tapınırdı.'),
(2008135,68,42,2,38,'Tam o sırada ortaya çıkan Anna, Tanrıya şükrederek Yeruşalimin kurtuluşunu bekleyen herkese İsadan söz etmeye başladı.'),
(2008136,68,42,2,39,'Yusufla Meryem, Rabbin Yasasında öngörülen her şeyi yerine getirdikten sonra Celileye, kendi kentleri Nasıraya döndüler.'),
(2008137,68,42,2,40,'Çocuk büyüyor, güçleniyor ve bilgelikte yetkinleşiyordu. Tanrının lütfu Onun üzerindeydi.'),
(2008138,68,42,2,41,'İsanın annesi babası her yıl Fısıh Bayramında Yeruşalime giderlerdi.'),
(2008139,68,42,2,42,'İsa on iki yaşına gelince, bayram geleneğine uyarak yine gittiler.'),
(2008140,68,42,2,43,'Bayramdan sonra eve dönerlerken küçük İsa Yeruşalimde kaldı. Bunu farketmeyen annesiyle babası, çocuğun yol arkadaşlarıyla birlikte olduğunu sanarak bir günlük yol gittiler. Sonra Onu akrabalar ve dostlar arasında aramaya başladılar.'),
(2008141,68,42,2,45,'Bulamayınca Onu araya araya Yeruşalime döndüler.'),
(2008142,68,42,2,46,'Üç gün sonra Onu tapınakta buldular. Din öğretmenleri arasında oturmuş, onları dinliyor, sorular soruyordu.'),
(2008143,68,42,2,47,'Onu dinleyen herkes, zekâsına ve verdiği yanıtlara hayran kalıyordu.'),
(2008144,68,42,2,48,'Annesiyle babası Onu görünce şaşırdılar. Annesi, ‹‹Çocuğum, bize bunu niçin yaptın? Bak, babanla ben büyük kaygı içinde seni arayıp durduk›› dedi.'),
(2008145,68,42,2,49,'O da onlara, ‹‹Beni niçin arayıp durdunuz?›› dedi. ‹‹Babamın evinde bulunmam gerektiğini bilmiyor muydunuz?››'),
(2008146,68,42,2,50,'Ne var ki onlar ne demek istediğini anlamadılar.'),
(2008147,68,42,2,51,'İsa onlarla birlikte yola çıkıp Nasıraya döndü. Onların sözünü dinlerdi. Annesi bütün bu olup bitenleri yüreğinde sakladı.'),
(2008148,68,42,2,52,'İsa bilgelikte ve boyda gelişiyor, Tanrı''nın ve insanların beğenisini kazanıyordu.'),
(2008149,68,42,3,1,'Sezar Tiberiusun egemenliğinin on beşinci yılıydı. Yahudiyede Pontius Pilatus valilik yapıyordu. Celileyi Hirodes, İtureya ve Trahonitis bölgesini Hirodesin kardeşi Filipus, Aviliniyi Lisanias yönetiyordu.'),
(2008150,68,42,3,2,'Hanan ile Kayafa başkâhinlik ediyorlardı. Bu sırada Tanrı çölde bulunan Zekeriya oğlu Yahyaya seslendi.'),
(2008151,68,42,3,3,'O da Şeria Irmağının çevresindeki bütün bölgeyi dolaşarak insanları, günahlarının bağışlanması için tövbe edip vaftiz olmaya çağırdı.'),
(2008152,68,42,3,4,'Nitekim Peygamber Yeşayanın sözlerini içeren kitapta şöyle yazılmıştır: ‹‹Çölde haykıran, ‹Rabbin yolunu hazırlayın, Geçeceği patikaları düzleyin› diye sesleniyor.'),
(2008153,68,42,3,5,'‹Her vadi doldurulacak, Her dağ ve her tepe alçaltılacak. Dolambaçlı yollar doğrultulacak, Engebeli yollar düzleştirilecek.'),
(2008154,68,42,3,6,'Ve bütün insanlar Tanrının sağladığı kurtuluşu görecektir.› ››'),
(2008155,68,42,3,7,'Yahya, vaftiz olmak için kendisine gelen kalabalıklara şöyle seslendi: ‹‹Ey engerekler soyu! Gelecek gazaptan kaçmak için sizi kim uyardı?'),
(2008156,68,42,3,8,'Bundan böyle tövbeye yaraşır meyveler verin! Kendi kendinize, ‹Biz İbrahimin soyundanız› demeye kalkmayın. Ben size şunu söyleyeyim: Tanrı, İbrahime şu taşlardan da çocuk yaratabilir.'),
(2008157,68,42,3,9,'Balta ağaçların köküne dayanmış bile. İyi meyve vermeyen her ağaç kesilip ateşe atılır.››'),
(2008158,68,42,3,10,'Halk ona, ‹‹Öyleyse biz ne yapalım?›› diye sordu.'),
(2008159,68,42,3,11,'Yahya onlara, ‹‹İki mintanı olan birini mintanı olmayana versin; yiyeceği olan yiyeceği olmayanla paylaşsın›› yanıtını verdi.'),
(2008160,68,42,3,12,'Bazı vergi görevlileri de vaftiz olmaya gelerek, ‹‹Öğretmenimiz, biz ne yapalım?›› dediler.'),
(2008161,68,42,3,13,'Yahya, ‹‹Size buyrulandan çok vergi almayın›› dedi.'),
(2008162,68,42,3,14,'Bazı askerler de, ‹‹Ya biz ne yapalım?›› diye sordular. O da, ‹‹Kaba kuvvetle ya da yalan suçlamalarla kimseden para koparmayın›› dedi, ‹‹Ücretinizle yetinin.››'),
(2008163,68,42,3,15,'Halk umut içinde bekliyordu. Yahyayla ilgili olarak herkesin aklında, ‹‹Acaba Mesih bu mu?›› sorusu vardı.'),
(2008164,68,42,3,16,'Yahya ise hepsine şöyle yanıt verdi: ‹‹Ben sizi suyla vaftiz ediyorum, ama benden daha güçlü Olan geliyor. Ben Onun çarıklarının bağını çözmeye bile layık değilim. O sizi Kutsal Ruhla ve ateşle vaftiz edecek.'),
(2008165,68,42,3,17,'Harman yerini temizlemek ve buğdayı toplayıp ambarına yığmak için yabası elinde hazır duruyor. Samanı ise sönmeyen ateşte yakacak.››'),
(2008166,68,42,3,18,'Yahya başka birçok konuda halka çağrıda bulunuyor, Müjdeyi duyuruyordu.'),
(2008167,68,42,3,19,'Ne var ki bölgenin kralı Hirodes, kardeşinin karısı Hirodiyayla ilgili olayı ve kendi yapmış olduğu bütün kötülükleri yüzüne vuran Yahyayı hapse attırarak kötülüklerine bir yenisini ekledi.'),
(2008168,68,42,3,21,'Bütün halk vaftiz olduktan sonra İsa da vaftiz oldu. Dua ederken gök açıldı ve Kutsal Ruh, bedensel görünümde, güvercin gibi Onun üzerine indi. Gökten, ‹‹Sen benim sevgili Oğlumsun, senden hoşnudum›› diyen bir ses duyuldu.'),
(2008169,68,42,3,23,'İsa görevine başladığı zaman otuz yaşlarındaydı. Yusufun oğlu olduğu sanılıyordu. Yusuf da Eli oğlu,'),
(2008170,68,42,3,24,'Mattat oğlu, Levi oğlu, Malki oğlu, Yannay oğlu, Yusuf oğlu,'),
(2008171,68,42,3,25,'Mattitya oğlu, Amos oğlu, Nahum oğlu, Hesli oğlu, Nagay oğlu,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008172,68,42,3,26,'Mahat oğlu, Mattitya oğlu, Şimi oğlu, Yosek oğlu, Yoda oğlu,'),
(2008173,68,42,3,27,'Yohanan oğlu, Reşa oğlu, Zerubbabil oğlu, Şealtiel oğlu, Neri oğlu,'),
(2008174,68,42,3,28,'Malki oğlu, Addi oğlu, Kosam oğlu, Elmadam oğlu, Er oğlu,'),
(2008175,68,42,3,29,'Yeşu oğlu, Eliezer oğlu, Yorim oğlu, Mattat oğlu, Levi oğlu,'),
(2008176,68,42,3,30,'Şimon oğlu, Yahuda oğlu, Yusuf oğlu, Yonam oğlu, Elyakim oğlu,'),
(2008177,68,42,3,31,'Mala oğlu, Menna oğlu, Mattata oğlu, Natan oğlu, Davut oğlu,'),
(2008178,68,42,3,32,'İşay oğlu, Ovet oğlu, Boaz oğlu, Salmon oğlu, Nahşon oğlu,'),
(2008179,68,42,3,33,'Amminadav oğlu, Ram oğlu, Hesron oğlu, Peres oğlu, Yahuda oğlu,'),
(2008180,68,42,3,34,'Yakup oğlu, İshak oğlu, İbrahim oğlu, Terah oğlu, Nahor oğlu,'),
(2008181,68,42,3,35,'Seruk oğlu, Reu oğlu, Pelek oğlu, Ever oğlu, Şelah oğlu,'),
(2008182,68,42,3,36,'Kenan oğlu, Arpakşat oğlu, Sam oğlu, Nuh oğlu, Lemek oğlu,'),
(2008183,68,42,3,37,'Metuşelah oğlu, Hanok oğlu, Yeret oğlu, Mahalalel oğlu, Kenan oğlu,'),
(2008184,68,42,3,38,'Enoş oğlu, Şit oğlu, Adem oğlu, Tanrı Oğlu''ydu.'),
(2008185,68,42,4,1,'Kutsal Ruhla dolu olarak Şeria Irmağından dönen İsa, Ruhun yönlendirmesiyle çölde dolaştırılarak kırk gün İblis tarafından denendi. O günlerde hiçbir şey yemedi. Dolayısıyla bu süre sonunda acıktı.'),
(2008186,68,42,4,3,'Bunun üzerine İblis Ona, ‹‹Tanrının Oğluysan, şu taşa söyle ekmek olsun›› dedi.'),
(2008187,68,42,4,4,'İsa, ‹‹ ‹İnsan yalnız ekmekle yaşamaz› diye yazılmıştır›› karşılığını verdi.'),
(2008188,68,42,4,5,'Sonra İblis İsayı yükseklere çıkararak bir anda Ona dünyanın bütün ülkelerini gösterdi.'),
(2008189,68,42,4,6,'Ona, ‹‹Bütün bunların yönetimini ve zenginliğini sana vereceğim›› dedi. ‹‹Bunlar bana teslim edildi, ben de dilediğim kişiye veririm.'),
(2008190,68,42,4,7,'Bana taparsan, hepsi senin olacak.››'),
(2008191,68,42,4,8,'İsa ona şu karşılığı verdi: ‹‹ ‹Tanrın Rabbe tapacak, yalnız Ona kulluk edeceksin› diye yazılmıştır.››'),
(2008192,68,42,4,9,'İblis Onu Yeruşalime götürüp tapınağın tepesine çıkardı. ‹‹Tanrının Oğluysan, kendini buradan aşağı at›› dedi.'),
(2008193,68,42,4,10,'‹‹Çünkü şöyle yazılmıştır: ‹Tanrı, seni korumaları için Meleklerine buyruk verecek.›'),
(2008194,68,42,4,11,'‹Ayağın bir taşa çarpmasın diye Seni elleri üzerinde taşıyacaklar.› ››'),
(2008195,68,42,4,12,'İsa ona şöyle karşılık verdi: ‹‹ ‹Tanrın Rabbi denemeyeceksin!› diye buyrulmuştur.››'),
(2008196,68,42,4,13,'İblis, İsayı her bakımdan denedikten sonra bir süre için Onun yanından ayrıldı.'),
(2008197,68,42,4,14,'İsa, Ruhun gücüyle donanmış olarak Celileye döndü. Haber bütün bölgeye yayıldı.'),
(2008198,68,42,4,15,'Oranın havralarında öğretiyor, herkes tarafından övülüyordu.'),
(2008199,68,42,4,16,'İsa, büyüdüğü Nasıra Kentine geldiğinde her zamanki gibi Şabat Günü havraya gitti. Kutsal Yazıları okumak üzere ayağa kalkınca Ona Peygamber Yeşayanın Kitabı verildi. Kitabı açarak şu sözlerin yazılı olduğu yeri buldu:'),
(2008200,68,42,4,18,'‹‹Rabbin Ruhu üzerimdedir. Çünkü O beni yoksullara Müjdeyi iletmek için meshetti. Tutsaklara serbest bırakılacaklarını, Körlere gözlerinin açılacağını duyurmak için, Ezilenleri özgürlüğe kavuşturmak Ve Rabbin lütuf yılını ilan etmek için Beni gönderdi.››'),
(2008201,68,42,4,20,'Sonra kitabı kapattı, görevliye geri verip oturdu. Havradakilerin hepsi dikkatle Ona bakıyordu.'),
(2008202,68,42,4,21,'İsa, ‹‹Dinlediğiniz bu Yazı bugün yerine gelmiştir›› diye konuşmaya başladı.'),
(2008203,68,42,4,22,'Herkes İsayı övüyor, ağzından çıkan lütufkâr sözlere hayran kalıyordu. ‹‹Yusufun oğlu değil mi bu?›› diyorlardı.'),
(2008204,68,42,4,23,'İsa onlara şöyle dedi: ‹‹Kuşkusuz bana şu deyimi hatırlatacaksınız: ‹Ey hekim, önce kendini iyileştir! Kefarnahumda yaptıklarını duyduk. Aynısını burada, kendi memleketinde de yap.› ››'),
(2008205,68,42,4,24,'‹‹Size doğrusunu söyleyeyim›› diye devam etti İsa, ‹‹Hiçbir peygamber kendi memleketinde kabul görmez.'),
(2008206,68,42,4,25,'Yine size gerçeği söyleyeyim, gökyüzünün üç yıl altı ay kapalı kaldığı, bütün ülkede korkunç bir kıtlığın baş gösterdiği İlyas zamanında İsrailde çok sayıda dul kadın vardı.'),
(2008207,68,42,4,26,'İlyas bunlardan hiçbirine gönderilmedi; yalnız Sayda bölgesinin Sarefat Kentinde bulunan dul bir kadına gönderildi.'),
(2008208,68,42,4,27,'Peygamber Elişanın zamanında İsrailde çok sayıda cüzamlı vardı. Bunlardan hiçbiri iyileştirilmedi; yalnız Suriyeli Naaman iyileştirildi.››'),
(2008209,68,42,4,28,'Havradakiler bu sözleri duyunca öfkeden kudurdular.'),
(2008210,68,42,4,29,'Ayağa kalkıp İsayı kentin dışına kovdular. Onu uçurumdan aşağı atmak için kentin kurulduğu tepenin yamacına götürdüler.'),
(2008211,68,42,4,30,'Ama İsa onların arasından geçerek oradan uzaklaştı.'),
(2008212,68,42,4,31,'Sonra İsa Celilenin Kefarnahum Kentine gitti. Şabat Günü halka öğretiyordu.'),
(2008213,68,42,4,32,'Yetkiyle konuştuğu için Onun öğretişine şaşıp kaldılar.'),
(2008214,68,42,4,33,'Havrada cinli, içinde kötü ruh olan bir adam vardı. Adam yüksek sesle, ‹‹Ey Nasıralı İsa, bırak bizi! Bizden ne istiyorsun?›› diye bağırdı. ‹‹Bizi mahvetmeye mi geldin? Senin kim olduğunu biliyorum, Tanrının Kutsalısın sen!››'),
(2008215,68,42,4,35,'İsa, ‹‹Sus, çık adamdan!›› diyerek cini azarladı. Cin adamı herkesin önünde yere vurduktan sonra, ona hiç zarar vermeden içinden çıktı.'),
(2008216,68,42,4,36,'Herkes şaşkına dönmüştü. Birbirlerine, ‹‹Bu nasıl söz? Güç ve yetkiyle kötü ruhlara çıkmalarını buyuruyor, onlar da çıkıyor!›› diyorlardı.'),
(2008217,68,42,4,37,'İsayla ilgili haber o bölgenin her yanında yankılandı.'),
(2008218,68,42,4,38,'İsa havradan ayrılarak Simunun evine gitti. Simunun kaynanası hastaydı, ateşler içindeydi. Onun için İsadan yardım istediler.'),
(2008219,68,42,4,39,'İsa kadının başucunda durup ateşi azarladı, kadının ateşi düştü. Kadın hemen ayağa kalkıp onlara hizmet etmeye başladı.'),
(2008220,68,42,4,40,'Güneş batarken herkes çeşitli hastalıklara yakalanmış akrabalarını İsaya getirdi. İsa her birinin üzerine ellerini koyarak onları iyileştirdi.'),
(2008221,68,42,4,41,'Birçoğunun içinden cinler de, ‹‹Sen Tanrının Oğlusun!›› diye bağırarak çıkıyordu. Ne var ki, İsa onları azarladı, konuşmalarına izin vermedi. Çünkü kendisinin Mesih olduğunu biliyorlardı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008222,68,42,4,42,'Sabah olunca İsa dışarı çıkıp ıssız bir yere gitti. Halk ise Onu arıyordu. Bulunduğu yere geldiklerinde Onu yanlarında alıkoymaya çalıştılar.'),
(2008223,68,42,4,43,'Ama İsa, ‹‹Öbür kentlerde de Tanrının Egemenliğiyle ilgili Müjdeyi yaymam gerek›› dedi. ‹‹Çünkü bunun için gönderildim.››'),
(2008224,68,42,4,44,'Böylece Yahudiye''deki havralarda Tanrı sözünü duyurmaya devam etti.'),
(2008225,68,42,5,1,'Halk, Ginnesar Gölünün kıyısında duran İsanın çevresini sarmış, Tanrının sözünü dinliyordu.'),
(2008226,68,42,5,2,'İsa, gölün kıyısında iki tekne gördü. Balıkçılar teknelerinden inmiş ağlarını yıkıyorlardı.'),
(2008227,68,42,5,3,'İki tekneden Simuna ait olanına binen İsa, ona kıyıdan biraz açılmasını rica etti. Sonra oturdu, teknenin içinden halka öğretmeye devam etti.'),
(2008228,68,42,5,4,'Konuşmasını bitirince Simuna, ‹‹Derin sulara açılın, balık tutmak için ağlarınızı atın›› dedi.'),
(2008229,68,42,5,5,'Simun şu karşılığı verdi: ‹‹Efendimiz, bütün gece çabaladık, hiçbir şey tutamadık. Yine de senin sözün üzerine ağları atacağım.››'),
(2008230,68,42,5,6,'Bunu yapınca öyle çok balık yakaladılar ki, ağları yırtılmaya başladı.'),
(2008231,68,42,5,7,'Öbür teknedeki ortaklarına işaret ederek gelip yardım etmelerini istediler. Onlar da geldiler ve her iki tekneyi balıkla doldurdular; tekneler neredeyse batıyordu.'),
(2008232,68,42,5,8,'Simun Petrus bunu görünce, ‹‹Ya Rab, benden uzak dur, ben günahlı bir adamım›› diyerek İsanın dizlerine kapandı.'),
(2008233,68,42,5,9,'Kendisi ve yanındakiler, tutmuş oldukları balıkların çokluğuna şaşıp kalmışlardı.'),
(2008234,68,42,5,10,'Simunun ortakları olan Zebedi oğulları Yakupla Yuhannayı da aynı şaşkınlık almıştı. İsa Simuna, ‹‹Korkma›› dedi, ‹‹Bundan böyle balık yerine insan tutacaksın.››'),
(2008235,68,42,5,11,'Sonra onlar tekneleri karaya çektiler ve her şeyi bırakıp İsanın ardından gittiler.'),
(2008236,68,42,5,12,'İsa kentlerden birindeyken, her yanını cüzam kaplamış bir adamla karşılaştı. Adam İsayı görünce yüzüstü yere kapanıp yalvardı: ‹‹Ya Rab, istersen beni temiz kılabilirsin›› dedi.'),
(2008237,68,42,5,13,'İsa elini uzatıp adama dokundu, ‹‹İsterim, temiz ol!›› dedi. Adam anında cüzamdan kurtuldu.'),
(2008238,68,42,5,14,'İsa ona, bundan kimseye söz etmemesini buyurdu. ‹‹Git, kâhine görün ve cüzamdan temizlendiğini herkese kanıtlamak için Musanın buyurduğu sunuları sun›› dedi.'),
(2008239,68,42,5,15,'Ne var ki, İsayla ilgili haber daha da çok yayıldı. Kalabalık halk toplulukları İsayı dinlemek ve hastalıklarından kurtulmak amacıyla akın akın geliyordu.'),
(2008240,68,42,5,16,'Kendisi ise ıssız yerlere çekilip dua ediyordu.'),
(2008241,68,42,5,17,'Bir gün İsa öğretiyordu. Celilenin ve Yahudiyenin bütün köylerinden ve Yeruşalimden gelen Ferisilerle Kutsal Yasa öğretmenleri Onun çevresinde oturuyorlardı. İsa, Rabbin gücü sayesinde hastaları iyileştiriyordu.'),
(2008242,68,42,5,18,'O sırada birkaç kişi, yatak üzerinde taşıdıkları felçli bir adamı evden içeri sokup İsanın önüne koymaya çalışıyordu.'),
(2008243,68,42,5,19,'Kalabalıktan ötürü onu içeri sokacak yol bulamayınca dama çıktılar, kiremitleri kaldırıp adamı yatakla birlikte orta yere, İsanın önüne indirdiler.'),
(2008244,68,42,5,20,'İsa onların imanını görünce, ‹‹Dostum, günahların bağışlandı›› dedi.'),
(2008245,68,42,5,21,'Din bilginleriyle Ferisiler, ‹‹Tanrıya küfreden bu adam kim? Tanrıdan başka kim günahları bağışlayabilir?›› diye düşünmeye başladılar.'),
(2008246,68,42,5,22,'Akıllarından geçenleri bilen İsa onlara şöyle seslendi: ‹‹Aklınızdan neden böyle şeyler geçiriyorsunuz?'),
(2008247,68,42,5,23,'Hangisi daha kolay, ‹Günahların bağışlandı› demek mi, yoksa ‹Kalk, yürü› demek mi?'),
(2008248,68,42,5,24,'Ne var ki, İnsanoğlunun yeryüzünde günahları bağışlama yetkisine sahip olduğunu bilesiniz diye...›› Sonra felçli adama, ‹‹Sana söylüyorum, kalk, yatağını toplayıp evine git!›› dedi.'),
(2008249,68,42,5,25,'Adam onların gözü önünde hemen ayağa kalktı, üzerinde yattığı yatağı topladı ve Tanrıyı yücelterek evine gitti.'),
(2008250,68,42,5,26,'Herkesi bir şaşkınlık almıştı. Tanrıyı yüceltiyor, büyük korku içinde, ‹‹Bugün şaşılacak işler gördük!›› diyorlardı.'),
(2008251,68,42,5,27,'Bu olaydan sonra İsa dışarı çıktı, vergi toplama yerinde oturan Levi adında bir vergi görevlisini gördü. Adama, ‹‹Ardımdan gel›› dedi.'),
(2008252,68,42,5,28,'O da kalktı, her şeyi bırakıp İsanın ardından gitti.'),
(2008253,68,42,5,29,'Sonra Levi, evinde İsanın onuruna büyük bir şölen verdi. Vergi görevlileriyle başka kişilerden oluşan büyük bir kalabalık onlarla birlikte yemeğe oturmuştu.'),
(2008254,68,42,5,30,'Ferisilerle onların din bilginleri söylenmeye başladılar. İsanın öğrencilerine, ‹‹Siz neden vergi görevlileri ve günahkârlarla birlikte yiyip içiyorsunuz?›› dediler.'),
(2008255,68,42,5,31,'İsa onlara şu karşılığı verdi: ‹‹Sağlıklı olanların değil, hastaların hekime ihtiyacı var.'),
(2008256,68,42,5,32,'Ben doğru kişileri değil, günahkârları tövbeye çağırmaya geldim.››'),
(2008257,68,42,5,33,'Onlar İsaya, ‹‹Yahyanın öğrencileri sık sık oruç tutup dua ediyorlar, Ferisilerin öğrencileri de öyle. Seninkiler ise yiyip içiyor›› dediler.'),
(2008258,68,42,5,34,'İsa şöyle karşılık verdi: ‹‹Güvey aralarında olduğu sürece davetlilere oruç tutturabilir misiniz?'),
(2008259,68,42,5,35,'Ama güveyin aralarından alınacağı günler gelecek, onlar işte o zaman, o günler oruç tutacaklar.››'),
(2008260,68,42,5,36,'İsa onlara şu benzetmeyi de anlattı: ‹‹Hiç kimse yeni giysiden bir parça yırtıp eski giysiyi yamamaz. Yoksa hem yeni giysi yırtılır, hem de o giysiden koparılan yama eskisine uymaz.'),
(2008261,68,42,5,37,'Hiç kimse yeni şarabı eski tulumlara doldurmaz. Yoksa yeni şarap tulumları patlatır; hem şarap dökülür, hem de tulumlar mahvolur.'),
(2008262,68,42,5,38,'Yeni şarabı yeni tulumlara doldurmak gerek.'),
(2008263,68,42,5,39,'Üstelik hiç kimse eski şarabı içtikten sonra yenisini istemez. ‹Eskisi güzel› der.››'),
(2008264,68,42,6,1,'Bir Şabat Günü İsa ekinler arasından geçiyordu. Öğrencileri başakları koparıyor, avuçlarında ufalayıp yiyorlardı.'),
(2008265,68,42,6,2,'Ferisilerden bazıları, ‹‹Şabat Günü yasak olanı neden yapıyorsunuz?›› dediler.'),
(2008266,68,42,6,3,'İsa onlara şöyle karşılık verdi: ‹‹Davutla yanındakiler acıkınca Davutun ne yaptığını okumadınız mı?'),
(2008267,68,42,6,4,'Tanrının evine girdi, kâhinlerden başkasının yemesi yasak olan adak ekmeklerini alıp yedi ve yanındakilere de verdi.››'),
(2008268,68,42,6,5,'Sonra İsa onlara, ‹‹İnsanoğlu Şabat Gününün de Rabbidir›› dedi.'),
(2008269,68,42,6,6,'Bir başka Şabat Günü İsa havraya girmiş öğretiyordu. Orada sağ eli sakat bir adam vardı.'),
(2008270,68,42,6,7,'İsayı suçlamak için fırsat kollayan din bilginleriyle Ferisiler, Şabat Günü hastaları iyileştirecek mi diye Onu gözlüyorlardı.'),
(2008271,68,42,6,8,'İsa, onların ne düşündüklerini biliyordu. Eli sakat olan adama, ‹‹Ayağa kalk, öne çık›› dedi. O da kalktı, orta yerde durdu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008272,68,42,6,9,'İsa onlara, ‹‹Size sorayım›› dedi, ‹‹Kutsal Yasaya göre Şabat Günü iyilik yapmak mı doğru, kötülük yapmak mı? Can kurtarmak mı doğru, öldürmek mi?››'),
(2008273,68,42,6,10,'Gözlerini hepsinin üzerinde gezdirdikten sonra adama, ‹‹Elini uzat›› dedi. Adam elini uzattı, eli yine sapasağlam oluverdi.'),
(2008274,68,42,6,11,'Onlar ise öfkeden deliye döndüler ve aralarında İsaya ne yapabileceklerini tartışmaya başladılar.'),
(2008275,68,42,6,12,'O günlerde İsa, dua etmek için dağa çıktı ve bütün geceyi Tanrıya dua ederek geçirdi.'),
(2008276,68,42,6,13,'Gün doğunca öğrencilerini yanına çağırdı ve onların arasından, elçi diye adlandırdığı şu on iki kişiyi seçti: Petrus adını verdiği Simun, onun kardeşi Andreas, Yakup, Yuhanna, Filipus, Bartalmay, Matta, Tomas, Alfay oğlu Yakup, Yurtsever diye tanınan Simun, Yakup oğlu Yahuda ve İsaya ihanet eden Yahuda İskariot.'),
(2008277,68,42,6,17,'İsa bunlarla birlikte aşağı inip düzlük bir yerde durdu. Öğrencilerinden büyük bir kalabalık ve bütün Yahudiyeden, Yeruşalimden, Surla Sayda yakınlarındaki kıyı bölgesinden gelen büyük bir halk topluluğu da oradaydı.'),
(2008278,68,42,6,18,'İsayı dinlemek ve hastalıklarına şifa bulmak için gelmişlerdi. Kötü ruhlar yüzünden sıkıntı çekenler de iyileştiriliyordu.'),
(2008279,68,42,6,19,'Kalabalıkta herkes İsaya dokunmak için çabalıyordu. Çünkü Onun içinden akan bir güç herkese şifa veriyordu.'),
(2008280,68,42,6,20,'İsa, gözlerini öğrencilerine çevirerek şöyle dedi: ‹‹Ne mutlu size, ey yoksullar! Çünkü Tanrının Egemenliği sizindir.'),
(2008281,68,42,6,21,'Ne mutlu size, şimdi açlık çekenler! Çünkü doyurulacaksınız. Ne mutlu size, şimdi ağlayanlar! Çünkü güleceksiniz.'),
(2008282,68,42,6,22,'İnsanoğluna bağlılığınız yüzünden İnsanlar sizden nefret ettikleri, Sizi toplum dışı edip aşağıladıkları Ve adınızı kötüleyip sizi reddettikleri zaman Ne mutlu size!'),
(2008283,68,42,6,23,'O gün sevinin, coşkuyla zıplayın! Çünkü gökteki ödülünüz büyüktür. Nitekim onların ataları da Peygamberlere böyle davrandılar.'),
(2008284,68,42,6,24,'Ama vay halinize, ey zenginler, Çünkü tesellinizi almış bulunuyorsunuz!'),
(2008285,68,42,6,25,'Vay halinize, şimdi karnı tok olan sizler, Çünkü açlık çekeceksiniz! Vay halinize, ey şimdi gülenler, Çünkü yas tutup ağlayacaksınız!'),
(2008286,68,42,6,26,'Bütün insanlar sizin için iyi sözler söyledikleri zaman, Vay halinize! Çünkü onların ataları da Sahte peygamberlere böyle davrandılar.››'),
(2008287,68,42,6,27,'‹‹Ama beni dinleyen sizlere şunu söylüyorum: Düşmanlarınızı sevin, sizden nefret edenlere iyilik yapın, size lanet edenler için iyilik dileyin, size hakaret edenler için dua edin.'),
(2008288,68,42,6,29,'Bir yanağınıza vurana öbür yanağınızı da çevirin. Abanızı alandan mintanınızı da esirgemeyin.'),
(2008289,68,42,6,30,'Sizden bir şey dileyen herkese verin, malınızı alandan onu geri istemeyin.'),
(2008290,68,42,6,31,'İnsanların size nasıl davranmasını istiyorsanız, siz de onlara öyle davranın.'),
(2008291,68,42,6,32,'‹‹Eğer yalnız sizi sevenleri severseniz, bu size ne övgü kazandırır? Günahkârlar bile kendilerini sevenleri sever.'),
(2008292,68,42,6,33,'Size iyilik yapanlara iyilik yaparsanız, bu size ne övgü kazandırır? Günahkârlar bile böyle yapar.'),
(2008293,68,42,6,34,'Geri alacağınızı umduğunuz kişilere ödünç verirseniz, bu size ne övgü kazandırır? Günahkârlar bile verdiklerini geri almak koşuluyla günahkârlara ödünç verirler.'),
(2008294,68,42,6,35,'Ama siz düşmanlarınızı sevin, iyilik yapın, hiçbir karşılık beklemeden ödünç verin. Alacağınız ödül büyük olacak, Yüceler Yücesinin oğulları olacaksınız. Çünkü O, nankör ve kötü kişilere karşı iyi yüreklidir.'),
(2008295,68,42,6,36,'Babanız merhametli olduğu gibi, siz de merhametli olun.››'),
(2008296,68,42,6,37,'‹‹Başkasını yargılamayın, siz de yargılanmazsınız. Suçlu çıkarmayın, siz de suçlu çıkarılmazsınız. Başkasını bağışlayın, siz de bağışlanırsınız.'),
(2008297,68,42,6,38,'Verin, size verilecektir. İyice bastırılmış, silkelenmiş ve taşmış, dolu bir ölçekle kucağınıza boşaltılacak. Hangi ölçekle verirseniz, aynı ölçekle alacaksınız.››'),
(2008298,68,42,6,39,'İsa onlara şu benzetmeyi de anlattı: ‹‹Kör köre kılavuzluk edebilir mi? İkisi de çukura düşmez mi?'),
(2008299,68,42,6,40,'Öğrenci öğretmeninden üstün değildir, ama eğitimini tamamlayan her öğrenci öğretmeni gibi olacaktır.'),
(2008300,68,42,6,41,'‹‹Sen neden kardeşinin gözündeki çöpü görürsün de kendi gözündeki merteği farketmezsin?'),
(2008301,68,42,6,42,'Kendi gözündeki merteği görmezken, kardeşine nasıl, ‹Kardeş, izin ver, gözündeki çöpü çıkarayım› dersin? Seni ikiyüzlü! Önce kendi gözündeki merteği çıkar, o zaman kardeşinin gözündeki çöpü çıkarmak için daha iyi görürsün.››'),
(2008302,68,42,6,43,'‹‹İyi ağaç kötü meyve, kötü ağaç da iyi meyve vermez.'),
(2008303,68,42,6,44,'Her ağaç meyvesinden tanınır. Dikenli bitkilerden incir toplanmaz, çalılardan üzüm devşirilmez.'),
(2008304,68,42,6,45,'İyi insan yüreğindeki iyilik hazinesinden iyilik, kötü insan içindeki kötülük hazinesinden kötülük çıkarır. İnsanın ağzı, yüreğinden taşanı söyler.'),
(2008305,68,42,6,46,'‹‹Niçin beni ‹Ya Rab, ya Rab› diye çağırıyorsunuz da söylediklerimi yapmıyorsunuz?'),
(2008306,68,42,6,47,'Bana gelen ve sözlerimi duyup uygulayan kişinin kime benzediğini size anlatayım.'),
(2008307,68,42,6,48,'Böyle bir kişi, evini yaparken toprağı kazan, derinlere inip temeli kaya üzerine atan adama benzer. Sel sularıyla kabaran ırmak o eve saldırsa da, onu sarsamaz. Çünkü ev sağlam yapılmıştır.'),
(2008308,68,42,6,49,'Ama sözlerimi duyup da uygulamayan kişi, evini temel koymaksızın toprağın üzerine kuran adama benzer. Kabaran ırmak saldırınca ev hemen çöker. Evin yıkılışı da korkunç olur.››'),
(2008309,68,42,7,1,'İsa, kendisini dinleyen halka bütün bu sözleri söyledikten sonra Kefarnahuma gitti.'),
(2008310,68,42,7,2,'Orada bir yüzbaşının çok değer verdiği kölesi ölüm döşeğinde hasta yatıyordu.'),
(2008311,68,42,7,3,'İsayla ilgili haberleri duyan yüzbaşı, gelip kölesini iyileştirmesini rica etmek üzere Ona Yahudilerin bazı ileri gelenlerini gönderdi.'),
(2008312,68,42,7,4,'Bunlar İsanın yanına gelince içten bir yalvarışla Ona şöyle dediler: ‹‹Bu adam senin yardımına layıktır.'),
(2008313,68,42,7,5,'Çünkü ulusumuzu seviyor. Havramızı yaptıran da kendisidir.››'),
(2008314,68,42,7,6,'İsa onlarla birlikte yola çıktı. Eve yaklaştığı sırada, yüzbaşı bazı dostlarını yollayıp Ona şu haberi gönderdi: ‹‹Ya Rab, zahmet etme; evime girmene layık değilim.'),
(2008315,68,42,7,7,'Bu yüzden yanına gelmeye de kendimi layık görmedim. Sen yeter ki bir söz söyle, uşağım iyileşir.'),
(2008316,68,42,7,8,'Ben de buyruk altında bir görevliyim, benim de buyruğumda askerlerim var. Birine, ‹Git› derim, gider; ötekine, ‹Gel› derim, gelir; köleme, ‹Şunu yap› derim, yapar.››'),
(2008317,68,42,7,9,'Bu sözleri duyan İsa yüzbaşıya hayran kaldı. Ardından gelen kalabalığa dönerek, ‹‹Size şunu söyleyeyim›› dedi, ‹‹İsrailde bile böyle iman görmedim.››'),
(2008318,68,42,7,10,'Gönderilenler eve döndüklerinde köleyi iyileşmiş buldular.'),
(2008319,68,42,7,11,'Bundan kısa bir süre sonra İsa, Nain denilen bir kente gitti. Öğrencileriyle büyük bir kalabalık Ona eşlik ediyordu.'),
(2008320,68,42,7,12,'İsa kentin kapısına tam yaklaştığı sırada, dul annesinin tek oğlu olan bir adamın cenazesi kaldırılıyordu. Kent halkından büyük bir kalabalık da kadınla birlikteydi.'),
(2008321,68,42,7,13,'Rab kadını görünce ona acıdı. Kadına, ‹‹Ağlama›› dedi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008322,68,42,7,14,'Yaklaşıp cenaze sedyesine dokununca sedyeyi taşıyanlar durdu. İsa, ‹‹Delikanlı›› dedi, ‹‹Sana söylüyorum, kalk!››'),
(2008323,68,42,7,15,'Ölü doğrulup oturdu ve konuşmaya başladı. İsa onu annesine geri verdi.'),
(2008324,68,42,7,16,'Herkesi bir korku almıştı. ‹‹Aramızda büyük bir peygamber ortaya çıktı!›› ve ‹‹Tanrı, halkının yardımına geldi!›› diyerek Tanrıyı yüceltmeye başladılar.'),
(2008325,68,42,7,17,'İsayla ilgili bu haber bütün Yahudiyeye ve çevre bölgelere yayıldı.'),
(2008326,68,42,7,18,'Yahyanın öğrencileri bütün bu olup bitenleri kendisine bildirdiler. Öğrencilerinden ikisini yanına çağıran Yahya, ‹‹Gelecek Olan sen misin, yoksa başkasını mı bekleyelim?›› diye sormaları için onları Rabbe gönderdi.'),
(2008327,68,42,7,20,'Adamlar İsanın yanına gelince şöyle dediler: ‹‹Bizi sana Vaftizci Yahya gönderdi. ‹Gelecek Olan sen misin, yoksa başkasını mı bekleyelim?› diye soruyor.››'),
(2008328,68,42,7,21,'Tam o sırada İsa, çeşitli hastalıklara, illetlere ve kötü ruhlara tutulmuş birçok kişiyi iyileştirdi, birçok körün gözünü açtı.'),
(2008329,68,42,7,22,'Sonra Yahyanın öğrencilerine şöyle karşılık verdi: ‹‹Gidin, görüp işittiklerinizi Yahyaya bildirin. Körlerin gözleri açılıyor, kötürümler yürüyor, cüzamlılar temiz kılınıyor, sağırlar işitiyor, ölüler diriliyor ve Müjde yoksullara duyuruluyor.'),
(2008330,68,42,7,23,'Benden ötürü sendeleyip düşmeyene ne mutlu!››'),
(2008331,68,42,7,24,'Yahyanın gönderdiği haberciler gittikten sonra İsa, halka Yahyadan söz etmeye başladı. ‹‹Çöle ne görmeye gittiniz?›› dedi. ‹‹Rüzgarda sallanan bir kamış mı?'),
(2008332,68,42,7,25,'Söyleyin, ne görmeye gittiniz? Pahalı giysiler giymiş bir adam mı? Oysa şahane giysiler giyip bolluk içinde yaşayanlar kral saraylarında bulunur.'),
(2008333,68,42,7,26,'Öyleyse ne görmeye gittiniz? Bir peygamber mi? Evet! Size şunu söyleyeyim, gördüğünüz kişi peygamberden de üstündür.'),
(2008334,68,42,7,27,'İşte, habercimi senin önünden gönderiyorum; O önden gidip senin yolunu hazırlayacak'),
(2008335,68,42,7,28,'Size şunu söyleyeyim, kadından doğanlar arasında Yahyadan daha üstün olanı yoktur. Bununla birlikte, Tanrının Egemenliğinde en küçük olan ondan üstündür.››'),
(2008336,68,42,7,29,'Yahya tarafından vaftiz edilen halk, hatta vergi görevlileri bile bunu duyunca Tanrının adil olduğunu doğruladılar.'),
(2008337,68,42,7,30,'Oysa Yahya tarafından vaftiz edilmeye yanaşmayan Ferisilerle Kutsal Yasa uzmanları, Tanrının kendileriyle ilgili tasarısını reddettiler.'),
(2008338,68,42,7,31,'İsa, ‹‹Bu kuşağın insanlarını neye benzeteyim? Bunlar neye benziyorlar?›› dedi.'),
(2008339,68,42,7,32,'‹‹Çarşı meydanında oturup birbirlerine, ‹Size kaval çaldık, oynamadınız; Ağıt yaktık, ağlamadınız›'),
(2008340,68,42,7,33,'Vaftizci Yahya geldiği zaman oruç tutup şaraptan kaçındı, ona ‹cinli› diyorsunuz.'),
(2008341,68,42,7,34,'İnsanoğlu geldiği zaman yiyip içti. Bu kez de diyorsunuz ki, ‹Şu obur ve ayyaş adama bakın! Vergi görevlileri ve günahkârlarla dost oldu!›'),
(2008342,68,42,7,35,'Ne var ki bilgelik, onu benimseyen herkes tarafından doğrulanır.››'),
(2008343,68,42,7,36,'Ferisilerden biri İsayı yemeğe çağırdı. O da Ferisinin evine gidip sofraya oturdu.'),
(2008344,68,42,7,37,'O sırada, kentte günahkâr olarak tanınan bir kadın, İsanın, Ferisinin evinde yemek yediğini öğrenince kaymaktaşından bir kap içinde güzel kokulu yağ getirdi. İsanın arkasında, ayaklarının dibinde durup ağlayarak, gözyaşlarıyla Onun ayaklarını ıslatmaya başladı. Saçlarıyla ayaklarını sildi, öptü ve yağı üzerlerine sürdü.'),
(2008345,68,42,7,39,'İsayı evine çağırmış olan Ferisi bunu görünce kendi kendine, ‹‹Bu adam peygamber olsaydı, kendisine dokunan bu kadının kim ve ne tür bir kadın olduğunu, günahkâr biri olduğunu anlardı›› dedi.'),
(2008346,68,42,7,40,'Bunun üzerine İsa Ferisiye, ‹‹Simun›› dedi, ‹‹Sana bir söyleyeceğim var.›› O da, ‹‹Buyur, öğretmenim›› dedi.'),
(2008347,68,42,7,41,'‹‹Tefeciye borçlu iki kişi vardı. Biri beş yüz, öbürü de elli dinar borçluydu.'),
(2008348,68,42,7,42,'Borçlarını ödeyecek güçte olmadıklarından, tefeci her ikisinin de borcunu bağışladı. Buna göre, hangisi onu çok sever?››'),
(2008349,68,42,7,43,'Simun, ‹‹Sanırım, kendisine daha çok bağışlanan›› diye yanıtladı. İsa ona, ‹‹Doğru söyledin›› dedi.'),
(2008350,68,42,7,44,'Sonra kadına bakarak Simuna şunları söyledi: ‹‹Bu kadını görüyor musun? Ben senin evine geldim, ayaklarım için bana su vermedin. Bu kadın ise ayaklarımı gözyaşlarıyla ıslatıp saçlarıyla sildi.'),
(2008351,68,42,7,45,'Sen beni öpmedin, ama bu kadın eve girdiğimden beri ayaklarımı öpüp duruyor.'),
(2008352,68,42,7,46,'Sen başıma zeytinyağı sürmedin, ama bu kadın ayaklarıma güzel kokulu yağ sürdü.'),
(2008353,68,42,7,47,'Bu nedenle sana şunu söyleyeyim, kendisinin çok olan günahları bağışlanmıştır. Çok sevgi göstermesinin nedeni budur. Oysa kendisine az bağışlanan, az sever.››'),
(2008354,68,42,7,48,'Sonra kadına, ‹‹Günahların bağışlandı›› dedi.'),
(2008355,68,42,7,49,'İsayla birlikte sofrada oturanlar kendi aralarında, ‹‹Kim bu adam? Günahları bile bağışlıyor!›› şeklinde konuşmaya başladılar.'),
(2008356,68,42,7,50,'İsa ise kadına, ‹‹İmanın seni kurtardı, esenlikle git›› dedi.'),
(2008357,68,42,8,1,'Bundan kısa bir süre sonra İsa on iki öğrencisiyle birlikte köy kent dolaşmaya başladı. Tanrının Egemenliğini duyurup müjdeliyordu.'),
(2008358,68,42,8,2,'Kötü ruhlardan ve hastalıklardan kurtulan bazı kadınlar, içinden yedi cin çıkmış olan Mecdelli denilen Meryem, Hirodesin kâhyası Kuzanın karısı Yohanna, Suzanna ve daha birçokları İsayla birlikte dolaşıyordu. Bunlar, kendi olanaklarıyla İsaya ve öğrencilerine yardım ediyorlardı.'),
(2008359,68,42,8,4,'Büyük bir kalabalığın toplandığı, insanların her kentten kendisine akın akın geldiği bir sırada İsa şu benzetmeyi anlattı: ‹‹Ekincinin biri tohum ekmeye çıktı. Ektiği tohumlardan kimi yol kenarına düştü, ayak altında çiğnenip gökteki kuşlara yem oldu.'),
(2008360,68,42,8,6,'Kimi kayalık yere düştü, filizlenince susuzluktan kuruyup gitti.'),
(2008361,68,42,8,7,'Kimi, dikenler arasına düştü. Filizlerle birlikte büyüyen dikenler filizleri boğdu.'),
(2008362,68,42,8,8,'Kimi ise iyi toprağa düştü, büyüyünce yüz kat ürün verdi.›› Bunları söyledikten sonra, ‹‹İşitecek kulağı olan işitsin!›› diye seslendi.'),
(2008363,68,42,8,9,'İsa, bu benzetmenin anlamını kendisinden soran öğrencilerine, ‹‹Tanrı Egemenliğinin sırlarını bilme ayrıcalığı size verildi›› dedi. ‹‹Ama başkalarına benzetmelerle sesleniyorum. Öyle ki, ‹Gördükleri halde görmesinler, Duydukları halde anlamasınlar.›'),
(2008364,68,42,8,11,'‹‹Benzetmenin anlamı şudur: Tohum Tanrının sözüdür.'),
(2008365,68,42,8,12,'Yol kenarındakiler sözü işiten kişilerdir. Ama sonra İblis gelir, inanıp kurtulmasınlar diye sözü yüreklerinden alır götürür.'),
(2008366,68,42,8,13,'Kayalık yere düşenler, işittikleri sözü sevinçle kabul eden, ama kök salamadıkları için ancak bir süre inanan kişilerdir. Böyleleri denendikleri zaman imandan dönerler.'),
(2008367,68,42,8,14,'Dikenler arasına düşenler, sözü işiten ama zamanla yaşamın kaygıları, zenginlikleri ve zevkleri içinde boğulan, dolayısıyla olgun ürün vermeyenlerdir.'),
(2008368,68,42,8,15,'İyi toprağa düşenler ise, sözü işitince onu iyi ve sağlam bir yürekte saklayanlardır. Bunlar sabırla dayanarak ürün verirler.››'),
(2008369,68,42,8,16,'‹‹Hiç kimse kandil yakıp bunu bir kapla örtmez, ya da yatağın altına koymaz. Tersine, içeri girenler ışığı görsünler diye onu kandilliğe koyar.'),
(2008370,68,42,8,17,'Çünkü açığa çıkarılmayacak gizli hiçbir şey yok; bilinmeyecek, aydınlığa çıkmayacak saklı hiçbir şey yoktur.'),
(2008371,68,42,8,18,'Bunun için, nasıl dinlediğinize dikkat edin. Kimde varsa, ona daha çok verilecek. Ama kimde yoksa, kendisinde var sandığı bile elinden alınacak.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008372,68,42,8,19,'İsanın annesiyle kardeşleri Ona geldiler, ama kalabalıktan ötürü kendisine yaklaşamadılar.'),
(2008373,68,42,8,20,'İsaya, ‹‹Annenle kardeşlerin dışarıda duruyor, seni görmek istiyorlar›› diye haber verildi.'),
(2008374,68,42,8,21,'İsa haberi getirenlere şöyle karşılık verdi: ‹‹Annemle kardeşlerim, Tanrının sözünü duyup yerine getirenlerdir.››'),
(2008375,68,42,8,22,'Bir gün İsa öğrencileriyle birlikte bir tekneye binerek onlara, ‹‹Gölün karşı yakasına geçelim›› dedi. Böylece kıyıdan açıldılar.'),
(2008376,68,42,8,23,'Teknede giderlerken İsa uykuya daldı. O sırada gölde fırtına koptu. Tekne su almaya başlayınca tehlikeli bir duruma düştüler.'),
(2008377,68,42,8,24,'Gidip İsayı uyandırarak, ‹‹Efendimiz, Efendimiz, öleceğiz!›› dediler. İsa kalkıp rüzgarı ve kabaran dalgaları azarladı. Fırtına dindi ve ortalık sütliman oldu.'),
(2008378,68,42,8,25,'İsa öğrencilerine, ‹‹Nerede imanınız?›› dedi. Onlar korku ve şaşkınlık içindeydiler. Birbirlerine, ‹‹Bu adam kim ki, rüzgara, suya bile buyruk veriyor, onlar da sözünü dinliyor!›› dediler.'),
(2008379,68,42,8,26,'Celilenin karşısında bulunan Gerasalıların memleketine vardılar.'),
(2008380,68,42,8,27,'İsa karaya çıkınca kentten bir adam Onu karşıladı. Cinli ve uzun zamandan beri giysi giymeyen bu adam evde değil, mezarlık mağaralarda yaşıyordu.'),
(2008381,68,42,8,28,'Adam İsayı görünce çığlık atıp önünde yere kapandı. Yüksek sesle, ‹‹Ey İsa, yüce Tanrının Oğlu, benden ne istiyorsun?›› dedi. ‹‹Sana yalvarırım, bana işkence etme!››'),
(2008382,68,42,8,29,'Çünkü İsa, kötü ruha adamın içinden çıkmasını buyurmuştu. Kötü ruh adamı sık sık etkisi altına alıyordu. Adam zincir ve kösteklerle bağlanıp başına nöbetçi konulduğu halde bağlarını paralıyor ve cin tarafından ıssız yerlere sürülüyordu.'),
(2008383,68,42,8,30,'İsa ona, ‹‹Adın ne?›› diye sordu. O da, ‹‹Tümen›› diye yanıtladı. Çünkü onun içine bir sürü cin girmişti.'),
(2008384,68,42,8,31,'Cinler, dipsiz derinliklere gitmelerini buyurmasın diye İsaya yalvarıp durdular.'),
(2008385,68,42,8,32,'Orada, dağın yamacında otlayan büyük bir domuz sürüsü vardı. Cinler, domuzların içine girmelerine izin vermesi için İsaya yalvardılar. O da onlara izin verdi.'),
(2008386,68,42,8,33,'Adamdan çıkan cinler domuzların içine girdiler. Sürü dik yamaçtan aşağı koşuşarak göle atlayıp boğuldu.'),
(2008387,68,42,8,34,'Domuzları güdenler olup biteni görünce kaçtılar, kentte ve köylerde olayın haberini yaydılar.'),
(2008388,68,42,8,35,'Bunun üzerine halk olup biteni görmeye çıktı. İsanın yanına geldikleri zaman, cinlerden kurtulan adamı giyinmiş ve aklı başına gelmiş olarak İsanın ayakları dibinde oturmuş buldular ve korktular.'),
(2008389,68,42,8,36,'Olayı görenler, cinli adamın nasıl kurtulduğunu halka anlattılar.'),
(2008390,68,42,8,37,'O zaman Gerasa yöresinden gelen bütün kalabalık büyük bir korkuya kapılarak İsanın yanlarından ayrılmasını rica ettiler. O da geri dönmek üzere tekneye bindi.'),
(2008391,68,42,8,38,'Cinlerden kurtulan adam İsanın yanında kalmak için Ona yalvardı. Ama İsa, ‹‹Evine dön, Tanrının senin için neler yaptığını anlat›› diyerek onu salıverdi. Adam da gitti, İsanın kendisi için neler yaptığını bütün kentte duyurdu.'),
(2008392,68,42,8,40,'Karşı yakaya dönen İsayı halk karşıladı. Çünkü herkes Onu bekliyordu.'),
(2008393,68,42,8,41,'O sırada, havra yöneticisi olan Yair adında bir adam gelip İsanın ayaklarına kapandı, evine gelmesi için yalvardı.'),
(2008394,68,42,8,42,'Çünkü on iki yaşlarındaki biricik kızı ölmek üzereydi. İsa oraya giderken kalabalık Onu her yandan sıkıştırıyordu.'),
(2008395,68,42,8,43,'On iki yıldır kanaması olan bir kadın da oradaydı. Varını yoğunu hekimlere harcamıştı; ama hiçbiri onu iyileştirememişti.'),
(2008396,68,42,8,44,'İsanın arkasından yetişip giysisinin eteğine dokundu ve o anda kanaması kesildi.'),
(2008397,68,42,8,45,'İsa, ‹‹Bana kim dokundu?›› dedi. Herkes inkâr ederken Petrus, ‹‹Efendimiz, kalabalık seni çepeçevre sarmış sıkıştırıyor›› dedi.'),
(2008398,68,42,8,46,'Ama İsa, ‹‹Birisi bana dokundu›› dedi. ‹‹İçimden bir gücün akıp gittiğini hissettim.››'),
(2008399,68,42,8,47,'Yaptığını gizleyemeyeceğini anlayan kadın titreyerek geldi, İsanın ayaklarına kapandı. Bütün halkın önünde, Ona neden dokunduğunu ve o anda nasıl iyileştiğini anlattı.'),
(2008400,68,42,8,48,'İsa ona, ‹‹Kızım›› dedi, ‹‹İmanın seni kurtardı. Esenlikle git.››'),
(2008401,68,42,8,49,'İsa daha konuşurken havra yöneticisinin evinden biri geldi. Yöneticiye, ‹‹Kızın öldü›› dedi, ‹‹Artık öğretmeni rahatsız etme.››'),
(2008402,68,42,8,50,'İsa bunu duyunca havra yöneticisine şöyle dedi: ‹‹Korkma, yalnız iman et, kızın kurtulacak.››'),
(2008403,68,42,8,51,'İsa adamın evine gelince Petrus, Yuhanna, Yakup ve kızın annesi babası dışında hiç kimsenin kendisiyle birlikte içeri girmesine izin vermedi.'),
(2008404,68,42,8,52,'Herkes kız için ağlıyor, dövünüyordu. İsa, ‹‹Ağlamayın›› dedi, ‹‹Kız ölmedi, uyuyor.››'),
(2008405,68,42,8,53,'Kızın öldüğünü bildikleri için İsayla alay ettiler.'),
(2008406,68,42,8,54,'O ise kızın elini tutarak, ‹‹Kızım, kalk!›› diye seslendi.'),
(2008407,68,42,8,55,'Ruhu yeniden bedenine dönen kız hemen ayağa kalktı. İsa, kıza yemek verilmesini buyurdu.'),
(2008408,68,42,8,56,'Kızın annesiyle babası şaşkınlık içindeydi. İsa, olanları hiç kimseye anlatmamaları için onları uyardı.'),
(2008409,68,42,9,1,'İsa, Onikileri yanına çağırıp onlara bütün cinler üzerinde ve hastalıkları iyileştirmek için güç ve yetki verdi.'),
(2008410,68,42,9,2,'Sonra onları Tanrının Egemenliğini duyurmaya ve hastalara şifa vermeye gönderdi.'),
(2008411,68,42,9,3,'Onlara şöyle dedi: ‹‹Yolculuk için yanınıza hiçbir şey almayın: Ne değnek, ne torba, ne ekmek, ne para, ne de yedek mintan.'),
(2008412,68,42,9,4,'Hangi eve girerseniz, kentten ayrılıncaya dek orada kalın.'),
(2008413,68,42,9,5,'Sizi kabul etmeyenlere gelince, kentten ayrılırken onlara uyarı olsun diye ayaklarınızın tozunu silkin.››'),
(2008414,68,42,9,6,'Onlar da yola çıktılar, her yerde Müjdeyi yayarak ve hastaları iyileştirerek köy köy dolaştılar.'),
(2008415,68,42,9,7,'Bölgenin kralı Hirodes bütün bu olanları duyunca şaşkına döndü. Çünkü bazıları Yahyanın ölümden dirildiğini, bazıları İlyasın göründüğünü, başkaları ise eski peygamberlerden birinin dirildiğini söylüyordu.'),
(2008416,68,42,9,9,'Hirodes, ‹‹Yahyanın başını ben kestirdim. Şimdi hakkında böyle haberler duyduğum bu adam kim?›› diyor ve İsayı görmenin bir yolunu arıyordu.'),
(2008417,68,42,9,10,'Elçiler geri dönünce, yaptıkları her şeyi İsaya anlattılar. Sonra İsa yalnızca onları yanına alıp Beytsayda denilen bir kente çekildi.'),
(2008418,68,42,9,11,'Bunu öğrenen halk Onun ardından gitti. İsa onları ilgiyle karşıladı, kendilerine Tanrının Egemenliğinden söz etti ve şifaya ihtiyacı olanları iyileştirdi.'),
(2008419,68,42,9,12,'Günbatımına doğru Onikiler gelip Ona, ‹‹Halkı salıver de çevredeki köylere ve çiftliklere gidip kendilerine barınak ve yiyecek bulsunlar. Çünkü ıssız bir yerdeyiz›› dediler.'),
(2008420,68,42,9,13,'İsa, ‹‹Onlara siz yiyecek verin›› dedi. ‹‹Beş ekmekle iki balıktan başka bir şeyimiz yok›› dediler. ‹‹Yoksa bunca halk için yiyecek almaya biz mi gidelim?››'),
(2008421,68,42,9,14,'Orada yaklaşık beş bin erkek vardı. İsa öğrencilerine, ‹‹Halkı yaklaşık ellişer kişilik kümeler halinde yere oturtun›› dedi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008422,68,42,9,15,'Öğrenciler öyle yapıp herkesi yere oturttular.'),
(2008423,68,42,9,16,'İsa, beş ekmekle iki balığı aldı, gözlerini göğe kaldırarak şükretti; sonra bunları böldü ve halka dağıtmaları için öğrencilerine verdi.'),
(2008424,68,42,9,17,'Herkes yiyip doydu. Artakalan parçalardan on iki sepet dolusu toplandı.'),
(2008425,68,42,9,18,'Bir gün İsa tek başına dua ediyordu, öğrencileri de yanındaydı. İsa onlara, ‹‹Halk benim kim olduğumu söylüyor?›› diye sordu.'),
(2008426,68,42,9,19,'Şöyle yanıtladılar: ‹‹Vaftizci Yahya diyorlar. Ama kimi İlyas, kimi de eski peygamberlerden biri dirilmiş, diyor.››'),
(2008427,68,42,9,20,'İsa onlara, ‹‹Siz ne dersiniz›› dedi, ‹‹Sizce ben kimim?›› Petrus, ‹‹Sen Tanrının Mesihisin›› yanıtını verdi.'),
(2008428,68,42,9,21,'İsa, onları uyararak bunu hiç kimseye söylememelerini buyurdu.'),
(2008429,68,42,9,22,'İnsanoğlunun çok acı çekmesi, ileri gelenler, başkâhinler ve din bilginlerince reddedilmesi, öldürülmesi ve üçüncü gün dirilmesi gerektiğini söyledi.'),
(2008430,68,42,9,23,'Sonra hepsine, ‹‹Ardımdan gelmek isteyen kendini inkâr etsin, her gün çarmıhını yüklenip beni izlesin›› dedi,'),
(2008431,68,42,9,24,'‹‹Canını kurtarmak isteyen onu yitirecek, canını benim uğruma yitiren ise onu kurtaracaktır.'),
(2008432,68,42,9,25,'İnsan bütün dünyayı kazanıp da canını yitirirse, canından olursa, bunun kendisine ne yararı olur?'),
(2008433,68,42,9,26,'Kim benden ve benim sözlerimden utanırsa, İnsanoğlu da kendisinin, Babasının ve kutsal meleklerin görkemi içinde geldiğinde o kişiden utanacaktır.'),
(2008434,68,42,9,27,'Size gerçeği söyleyeyim, burada bulunanlar arasında, Tanrının Egemenliğini görmeden ölümü tatmayacak olanlar var.››'),
(2008435,68,42,9,28,'Bu sözleri söyledikten yaklaşık sekiz gün sonra İsa, yanına Petrus, Yuhanna ve Yakupu alarak dua etmek üzere dağa çıktı.'),
(2008436,68,42,9,29,'İsa dua ederken yüzünün görünümü değişti, giysileri şimşek gibi parıldayan bir beyazlığa büründü.'),
(2008437,68,42,9,30,'O anda görkem içinde beliren iki kişi İsayla konuşmaya başladılar. Bunlar Musa ile İlyastı. İsanın yakında Yeruşalimde gerçekleşecek olan ayrılışını konuşuyorlardı.'),
(2008438,68,42,9,32,'Petrus ile yanındakilerin üzerine uyku çökmüştü. Ama uykuları iyice dağılınca İsanın görkemini ve yanında duran iki kişiyi gördüler.'),
(2008439,68,42,9,33,'Bunlar İsanın yanından ayrılırken Petrus İsaya, ‹‹Efendimiz›› dedi, ‹‹Burada bulunmamız ne iyi oldu! Üç çardak kuralım: Biri sana, biri Musaya, biri de İlyasa.›› Aslında ne söylediğinin farkında değildi.'),
(2008440,68,42,9,34,'Petrus daha bunları söylerken bir bulut gelip onlara gölge saldı. Bulut onları sarınca korktular.'),
(2008441,68,42,9,35,'Buluttan gelen bir ses, ‹‹Bu benim Oğlumdur, seçilmiş Olandır. Onu dinleyin!›› dedi.'),
(2008442,68,42,9,36,'Ses kesilince İsanın tek başına olduğu görüldü. Öğrenciler bunu gizli tuttular ve o günlerde hiç kimseye gördüklerinden söz etmediler.'),
(2008443,68,42,9,37,'Ertesi gün dağdan indikleri zaman, İsayı büyük bir kalabalık karşıladı.'),
(2008444,68,42,9,38,'Kalabalığın içinden bir adam, ‹‹Öğretmenim›› diye seslendi, ‹‹Yalvarırım, oğlumu bir gör, o tek çocuğumdur.'),
(2008445,68,42,9,39,'Bir ruh onu yakalıyor, o da birdenbire çığlık atıyor. Ruh onu, ağzından köpükler gelene dek şiddetle sarsıyor. Bedenini yara bere içinde bırakarak güçbela ayrılıyor.'),
(2008446,68,42,9,40,'Ruhu kovmaları için öğrencilerine yalvardım, ama başaramadılar.››'),
(2008447,68,42,9,41,'İsa şöyle karşılık verdi: ‹‹Ey imansız ve sapmış kuşak! Sizinle daha ne kadar kalıp size katlanacağım? Oğlunu buraya getir.››'),
(2008448,68,42,9,42,'Çocuk daha İsaya yaklaşırken cin onu yere vurup şiddetle sarstı. Ama İsa kötü ruhu azarladı, çocuğu iyileştirerek babasına geri verdi.'),
(2008449,68,42,9,43,'Herkes Tanrının büyük gücüne şaşıp kaldı. Herkes İsanın bütün yaptıkları karşısında hayret içindeyken, İsa öğrencilerine, ‹‹Şu sözlerime iyice kulak verin›› dedi. ‹‹İnsanoğlu, insanların eline teslim edilecek.››'),
(2008450,68,42,9,45,'Onlar bu sözü anlamadılar. Sözü kavramasınlar diye anlamı kendilerinden gizlenmişti. Üstelik İsaya bu sözle ilgili soru sormaktan korkuyorlardı.'),
(2008451,68,42,9,46,'Öğrenciler, aralarında kimin en büyük olduğunu tartışmaya başladılar.'),
(2008452,68,42,9,47,'Akıllarından geçeni bilen İsa, küçük bir çocuğu tutup yanına çekti ve onlara şöyle dedi: ‹‹Bu çocuğu benim adım uğruna kabul eden, beni kabul etmiş olur. Beni kabul eden de beni göndereni kabul etmiş olur. Aranızda en küçük kim ise, işte en büyük odur.››'),
(2008453,68,42,9,49,'Yuhanna buna karşılık, ‹‹Efendimiz›› dedi, ‹‹Senin adınla cin kovan birini gördük, ama bizimle birlikte seni izlemediği için ona engel olmaya çalıştık.››'),
(2008454,68,42,9,50,'İsa, ‹‹Ona engel olmayın!›› dedi. ‹‹Size karşı olmayan, sizden yanadır.››'),
(2008455,68,42,9,51,'Göğe alınacağı gün yaklaşınca İsa, kararlı adımlarla Yeruşalime doğru yola çıktı.'),
(2008456,68,42,9,52,'Kendi önünden haberciler gönderdi. Bunlar, kendisi için hazırlık yapmak üzere gidip Samiriyelilere ait bir köye girdiler.'),
(2008457,68,42,9,53,'Ama Samiriyeliler İsayı kabul etmediler. Çünkü Yeruşalime doğru gidiyordu.'),
(2008458,68,42,9,54,'Öğrencilerden Yakupla Yuhanna bunu görünce, ‹‹Rab, bunları yok etmek için bir buyrukla gökten ateş yağdırmamızı ister misin?›› dediler.'),
(2008459,68,42,9,55,'Ama İsa dönüp onları azarladı.'),
(2008460,68,42,9,56,'Sonra başka bir köye gittiler.'),
(2008461,68,42,9,57,'Yolda giderlerken bir adam İsaya, ‹‹Nereye gidersen, senin ardından geleceğim›› dedi.'),
(2008462,68,42,9,58,'İsa ona, ‹‹Tilkilerin ini, kuşların yuvası var, ama İnsanoğlunun başını yaslayacak bir yeri yok›› dedi.'),
(2008463,68,42,9,59,'Bir başkasına, ‹‹Ardımdan gel›› dedi. Adam ise, ‹‹İzin ver, önce gidip babamı gömeyim›› dedi.'),
(2008464,68,42,9,60,'İsa ona şöyle dedi: ‹‹Bırak ölüleri, kendi ölülerini kendileri gömsün. Sen gidip Tanrının Egemenliğini duyur.››'),
(2008465,68,42,9,61,'Bir başkası, ‹‹Ya Rab›› dedi, ‹‹Senin ardından geleceğim ama, izin ver, önce evimdekilerle vedalaşayım.››'),
(2008466,68,42,9,62,'İsa ona, ‹‹Sabanı tutup da geriye bakan, Tanrı''nın Egemenliği''ne layık değildir›› dedi.'),
(2008467,68,42,10,1,'Bu olaylardan sonra Rab yetmiş kişi daha görevlendirdi. Bunları ikişer ikişer, kendisinin gideceği her kente, her yere kendi önünden gönderdi.'),
(2008468,68,42,10,2,'Onlara, ‹‹Ürün bol, ama işçi az›› dedi, ‹‹Bu nedenle ürünün sahibi Rabbe yalvarın, ürününü kaldıracak işçiler göndersin.'),
(2008469,68,42,10,3,'Haydi gidin! İşte, sizi kuzular gibi kurtların arasına gönderiyorum.'),
(2008470,68,42,10,4,'Yanınıza ne kese, ne torba, ne de çarık alın. Yolda hiç kimseyle selamlaşmayın.'),
(2008471,68,42,10,5,'Hangi eve girerseniz, önce, ‹Bu eve esenlik olsun!› deyin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008472,68,42,10,6,'Orada esenliksever biri varsa, dilediğiniz esenlik onun üzerinde kalacak; yoksa, size dönecektir.'),
(2008473,68,42,10,7,'Girdiğiniz evde kalın, size ne verirlerse onu yiyip için. Çünkü işçi ücretini hak eder. Evden eve taşınmayın.'),
(2008474,68,42,10,8,'‹‹Bir kente girdiğinizde sizi kabul ederlerse, önünüze konulanı yiyin.'),
(2008475,68,42,10,9,'Orada bulunan hastaları iyileştirin ve kendilerine, ‹Tanrının Egemenliği size yaklaştı› deyin.'),
(2008476,68,42,10,10,'Ama bir kente girdiğinizde sizi kabul etmezlerse, o kentin caddelerine çıkıp şöyle deyin: ‹Kentinizden ayaklarımızda kalan tozu bile size karşı silkiyoruz. Yine de şunu bilin ki, Tanrının Egemenliği yaklaştı.›'),
(2008477,68,42,10,12,'Size şunu söyleyeyim, yargı günü o kentin hali Sodom Kentinin halinden beter olacaktır.'),
(2008478,68,42,10,13,'‹‹Vay haline, ey Horazin! Vay haline, ey Beytsayda! Sizlerde yapılan mucizeler Sur ve Saydada yapılmış olsaydı, çoktan çul kuşanıp kül içinde oturarak tövbe etmiş olurlardı.'),
(2008479,68,42,10,14,'Ama yargı günü sizin haliniz Sur ve Saydanın halinden beter olacaktır.'),
(2008480,68,42,10,15,'Ya sen, ey Kefarnahum, göğe mi çıkarılacaksın? Hayır, ölüler diyarına indirileceksin!'),
(2008481,68,42,10,16,'‹‹Sizi dinleyen beni dinlemiş olur, sizi reddeden beni reddetmiş olur. Beni reddeden de beni göndereni reddetmiş olur.››'),
(2008482,68,42,10,17,'Yetmişler sevinç içinde döndüler. ‹‹Ya Rab›› dediler, ‹‹Senin adını andığımızda cinler bile bize boyun eğiyor.››'),
(2008483,68,42,10,18,'İsa onlara şöyle dedi: ‹‹Şeytanın gökten yıldırım gibi düştüğünü gördüm.'),
(2008484,68,42,10,19,'Ben size, yılanları ve akrepleri ayak altında ezmek ve düşmanın bütün gücünü alt etmek için yetki verdim. Hiçbir şey size zarar vermeyecektir.'),
(2008485,68,42,10,20,'Bununla birlikte, ruhların size boyun eğmesine sevinmeyin, adlarınızın gökte yazılmış olmasına sevinin.››'),
(2008486,68,42,10,21,'O anda İsa Kutsal Ruhun etkisiyle coşarak şöyle dedi: ‹‹Baba, yerin ve göğün Rabbi! Bu gerçekleri bilge ve akıllı kişilerden gizleyip küçük çocuklara açtığın için sana şükrederim. Evet Baba, senin isteğin buydu.'),
(2008487,68,42,10,22,'‹‹Babam her şeyi bana teslim etti. Oğulun kim olduğunu Babadan başka kimse bilmez. Babanın kim olduğunu da Oğuldan ve Oğulun Onu tanıtmak istediği kişilerden başkası bilmez.››'),
(2008488,68,42,10,23,'Sonra öğrencilerine dönüp özel olarak şöyle dedi: ‹‹Sizin gördüklerinizi gören gözlere ne mutlu!'),
(2008489,68,42,10,24,'Size şunu söyleyeyim, nice peygamberler, nice krallar sizin gördüklerinizi görmek istediler, ama göremediler. Sizin işittiklerinizi işitmek istediler, ama işitemediler.››'),
(2008490,68,42,10,25,'Bir Kutsal Yasa uzmanı İsayı denemek amacıyla gelip şöyle dedi: ‹‹Öğretmenim, sonsuz yaşamı miras almak için ne yapmalıyım?››'),
(2008491,68,42,10,26,'İsa ona, ‹‹Kutsal Yasada ne yazılmıştır?›› diye sordu. ‹‹Orada ne okuyorsun?››'),
(2008492,68,42,10,27,'Adam şöyle karşılık verdi: ‹‹Tanrın Rabbi bütün yüreğinle, bütün canınla, bütün gücünle ve bütün aklınla seveceksin. Komşunu da kendin gibi seveceksin.››'),
(2008493,68,42,10,28,'İsa ona, ‹‹Doğru yanıt verdin›› dedi. ‹‹Bunu yap ve yaşayacaksın.››'),
(2008494,68,42,10,29,'Oysa adam kendini haklı çıkarmak isteyerek İsaya, ‹‹Peki, komşum kim?›› dedi.'),
(2008495,68,42,10,30,'İsa şöyle yanıt verdi: ‹‹Adamın biri Yeruşalimden Erihaya inerken haydutların eline düştü. Onu soyup dövdüler, yarı ölü bırakıp gittiler.'),
(2008496,68,42,10,31,'Bir rastlantı olarak o yoldan bir kâhin geçiyordu. Adamı görünce yolun öbür yanından geçip gitti.'),
(2008497,68,42,10,32,'Bir Levili de oraya varıp adamı görünce aynı şekilde geçip gitti.'),
(2008498,68,42,10,33,'O yoldan geçen bir Samiriyeli ise adamın bulunduğu yere gelip onu görünce, yüreği sızladı.'),
(2008499,68,42,10,34,'Adamın yanına gitti, yaralarının üzerine yağla şarap dökerek sardı. Sonra adamı kendi hayvanına bindirip hana götürdü, onunla ilgilendi.'),
(2008500,68,42,10,35,'Ertesi gün iki dinar çıkararak hancıya verdi. ‹Ona iyi bak› dedi, ‹Bundan fazla ne harcarsan, dönüşümde sana öderim.›'),
(2008501,68,42,10,36,'‹‹Sence bu üç kişiden hangisi haydutlar arasına düşen adama komşu gibi davrandı?››'),
(2008502,68,42,10,37,'Yasa uzmanı, ‹‹Ona acıyıp yardım eden›› dedi. İsa, ‹‹Git, sen de öyle yap›› dedi.'),
(2008503,68,42,10,38,'İsa, öğrencileriyle birlikte yola devam edip bir köye girdi. Marta adında bir kadın İsayı evinde konuk etti.'),
(2008504,68,42,10,39,'Martanın Meryem adındaki kızkardeşi, Rabbin ayakları dibine oturmuş Onun konuşmasını dinliyordu.'),
(2008505,68,42,10,40,'Marta ise işlerinin çokluğundan ötürü telaş içindeydi. İsanın yanına gelerek, ‹‹Ya Rab›› dedi, ‹‹Kardeşimin beni hizmet işlerinde yalnız bırakmasına aldırmıyor musun? Ona söyle de bana yardım etsin.››'),
(2008506,68,42,10,41,'Rab ona şu karşılığı verdi: ‹‹Marta, Marta, sen çok şey için kaygılanıp telaşlanıyorsun.'),
(2008507,68,42,10,42,'Oysa gerekli olan tek bir şey vardır. Meryem iyi olanı seçti ve bu kendisinden alınmayacak.››'),
(2008508,68,42,11,1,'İsa bir yerde dua ediyordu. Duasını bitirince öğrencilerinden biri, ‹‹Ya Rab›› dedi, ‹‹Yahyanın kendi öğrencilerine öğrettiği gibi sen de bize dua etmesini öğret.››'),
(2008509,68,42,11,2,'İsa onlara, ‹‹Dua ederken şöyle söyleyin›› dedi: ‹‹Baba, adın kutsal kılınsın. Egemenliğin gelsin.'),
(2008510,68,42,11,3,'Her gün bize gündelik ekmeğimizi ver.'),
(2008511,68,42,11,4,'Günahlarımızı bağışla. Çünkü biz de bize karşı suç işleyen herkesi bağışlıyoruz. Ayartılmamıza izin verme.››'),
(2008512,68,42,11,5,'Sonra şöyle dedi: ‹‹Sizlerden birinin bir arkadaşı olur da gece yarısı ona gidip, ‹Arkadaş, bana üç ekmek ödünç ver. Bir arkadaşım yoldan geldi, önüne koyacak bir şeyim yok› derse, öbürü içerden, ‹Beni rahatsız etme! Kapı kilitli, çocuklarım da yanımda yatıyor. Kalkıp sana bir şey veremem› der mi hiç?'),
(2008513,68,42,11,8,'Size şunu söyleyeyim, arkadaşlık gereği kalkıp ona istediğini vermese bile, adamın yüzsüzlüğünden ötürü kalkar, ihtiyacı neyse ona verir.'),
(2008514,68,42,11,9,'‹‹Ben size şunu söyleyeyim: Dileyin, size verilecek; arayın, bulacaksınız; kapıyı çalın, size açılacaktır.'),
(2008515,68,42,11,10,'Çünkü her dileyen alır, arayan bulur, kapı çalana açılır.'),
(2008516,68,42,11,11,'‹‹Aranızda hangi baba, ekmek isteyen oğluna taş verir? Ya da balık isterse balık yerine yılan verir?'),
(2008517,68,42,11,12,'Ya da yumurta isterse ona akrep verir?'),
(2008518,68,42,11,13,'Sizler kötü yürekli olduğunuz halde çocuklarınıza güzel armağanlar vermeyi biliyorsanız, gökteki Babanın, kendisinden dileyenlere Kutsal Ruhu vereceği çok daha kesin değil mi?››'),
(2008519,68,42,11,14,'İsa adamın birinden dilsiz bir cini kovuyordu. Cin çıkınca adamın dili çözüldü. Halk hayret içinde kaldı.'),
(2008520,68,42,11,15,'Ama içlerinden bazıları, ‹‹Cinleri, cinlerin önderi Baalzevulun gücüyle kovuyor›› dediler.'),
(2008521,68,42,11,16,'Bazıları ise Onu denemek amacıyla gökten bir belirti göstermesini istediler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008522,68,42,11,17,'Onların ne düşündüğünü bilen İsa şöyle dedi: ‹‹Kendi içinde bölünen ülke yıkılır, kendi içinde bölünen ev çöker.'),
(2008523,68,42,11,18,'Şeytan da kendi içinde bölünmüşse, onun egemenliği nasıl ayakta kalabilir? Siz, benim Baalzevulun gücüyle cinleri kovduğumu söylüyorsunuz.'),
(2008524,68,42,11,19,'Eğer ben cinleri Baalzevulun gücüyle kovuyorsam, sizin adamlarınız kimin gücüyle kovuyor? Sizi bu durumda kendi adamlarınız yargılayacak.'),
(2008525,68,42,11,20,'Ama ben cinleri Tanrının eliyle kovuyorsam, Tanrının Egemenliği üzerinize gelmiş demektir.'),
(2008526,68,42,11,21,'‹‹Tepeden tırnağa silahlanmış güçlü bir adam kendi evini koruduğu sürece, malları güvenlik içinde olur.'),
(2008527,68,42,11,22,'Ne var ki, ondan daha güçlü biri saldırıp onu alt ettiğinde güvendiği bütün silahları elinden alır ve mallarını yağmalayarak bölüştürür.'),
(2008528,68,42,11,23,'Benden yana olmayan bana karşıdır, benimle birlikte toplamayan dağıtıyor demektir.'),
(2008529,68,42,11,24,'‹‹Kötü ruh insandan çıkınca kurak yerlerde dolanıp huzur arar. Bulamayınca da, ‹Çıktığım eve, kendi evime döneyim› der.'),
(2008530,68,42,11,25,'Eve gelince orayı süpürülmüş, düzeltilmiş bulur.'),
(2008531,68,42,11,26,'Bunun üzerine gider, kendisinden kötü yedi ruh daha alır ve eve girip yerleşirler. Böylece o kişinin son durumu ilkinden beter olur.››'),
(2008532,68,42,11,27,'İsa bu sözleri söylerken kalabalığın içinden bir kadın Ona, ‹‹Ne mutlu seni taşımış olan rahme, emzirmiş olan memelere!›› diye seslendi.'),
(2008533,68,42,11,28,'İsa, ‹‹Daha doğrusu, ne mutlu Tanrının sözünü dinleyip uygulayanlara!›› dedi.'),
(2008534,68,42,11,29,'Çevredeki kalabalık büyürken İsa konuşmaya başladı. ‹‹Şimdiki kuşak kötü bir kuşaktır›› dedi. ‹‹Doğaüstü bir belirti istiyor, ama ona Yunusun belirtisinden başka bir belirti gösterilmeyecek.'),
(2008535,68,42,11,30,'Yunus nasıl Ninova halkına bir belirti olduysa, İnsanoğlu da bu kuşak için öyle olacaktır.'),
(2008536,68,42,11,31,'Güney Kraliçesi, yargı günü bu kuşağın adamlarıyla birlikte kalkıp onları yargılayacak. Çünkü kraliçe, Süleymanın bilgece sözlerini dinlemek için dünyanın ta öbür ucundan gelmişti. Bakın, Süleymandan daha üstün olan buradadır.'),
(2008537,68,42,11,32,'Ninova halkı, yargı günü bu kuşakla birlikte kalkıp bu kuşağı yargılayacak. Çünkü Ninovalılar, Yunusun çağrısı üzerine tövbe ettiler. Bakın, Yunustan daha üstün olan buradadır.››'),
(2008538,68,42,11,33,'‹‹Hiç kimse kandil yakıp onu gizli yere ya da tahıl ölçeğinin altına koymaz. Tersine, içeri girenler ışığı görsünler diye onu kandilliğe koyar.'),
(2008539,68,42,11,34,'Bedenin ışığı gözdür. Gözün sağlamsa, bütün bedenin de aydınlık olur. Gözün bozuksa, bedenin de karanlık olur.'),
(2008540,68,42,11,35,'Öyleyse dikkat et, sendeki ‹ışık› karanlık olmasın.'),
(2008541,68,42,11,36,'Eğer bütün bedenin aydınlık olur ve hiçbir yanı karanlık kalmazsa, kandilin seni ışınlarıyla aydınlattığı zamanki gibi, bedenin tümden aydınlık olur.››'),
(2008542,68,42,11,37,'İsa konuşmasını bitirince bir Ferisi Onu evine yemeğe çağırdı. O da içeri girerek sofraya oturdu.'),
(2008543,68,42,11,38,'İsanın yemekten önce yıkanmadığını gören Ferisi şaştı.'),
(2008544,68,42,11,39,'Rab ona şöyle dedi: ‹‹Siz Ferisiler, bardağın ve tabağın dışını temizlersiniz, ama içiniz açgözlülük ve kötülükle doludur.'),
(2008545,68,42,11,40,'Ey akılsızlar! Dışı yapanla içi yapan aynı değil mi?'),
(2008546,68,42,11,41,'Siz kaplarınızın içindekini sadaka olarak verin, o zaman sizin için her şey temiz olur.'),
(2008547,68,42,11,42,'‹‹Ama vay halinize, ey Ferisiler! Siz nanenin, sedefotunun ve her tür sebzenin ondalığını verirsiniz de, adaleti ve Tanrı sevgisini ihmal edersiniz. Ondalık vermeyi ihmal etmeden esas bunları yerine getirmeniz gerekirdi.'),
(2008548,68,42,11,43,'Vay halinize, ey Ferisiler! Havralarda en seçkin yerlere kurulmaya, meydanlarda selamlanmaya bayılırsınız.'),
(2008549,68,42,11,44,'Vay halinize! İnsanların, farkında olmadan üzerlerinde gezindiği belirsiz mezarlara benziyorsunuz.››'),
(2008550,68,42,11,45,'Kutsal Yasa uzmanlarından biri söz alıp İsaya, ‹‹Öğretmenim, bunları söylemekle bize de hakaret etmiş oluyorsun›› dedi.'),
(2008551,68,42,11,46,'İsa, ‹‹Sizin de vay halinize, ey Yasa uzmanları!›› dedi. ‹‹İnsanlara taşınması güç yükler yüklersiniz, kendiniz ise bu yükleri kaldırmak için parmağınızı bile kıpırdatmazsınız.'),
(2008552,68,42,11,47,'Vay halinize! Peygamberlerin anıtlarını yaparsınız, oysa onları sizin atalarınız öldürmüştür.'),
(2008553,68,42,11,48,'Böylelikle atalarınızın yaptıklarına tanıklık ederek bunları onaylamış oluyorsunuz. Çünkü onlar peygamberleri öldürdüler, siz de anıtlarını yapıyorsunuz.'),
(2008554,68,42,11,49,'İşte bunun için Tanrının Bilgeliği şöyle demiştir: ‹Ben onlara peygamberler ve elçiler göndereceğim, bunlardan kimini öldürecek, kimine zulmedecekler.›'),
(2008555,68,42,11,50,'Böylece bu kuşak, Habilin kanından tutun da, sunakla tapınak arasında öldürülen Zekeriyanın kanına değin, dünyanın kuruluşundan beri akıtılan bütün peygamberlerin kanından sorumlu tutulacaktır. Evet, size söylüyorum, bu kuşak sorumlu tutulacaktır.'),
(2008556,68,42,11,52,'Vay halinize, ey Yasa uzmanları! Bilgi kapısının anahtarını alıp götürdünüz. Kendiniz bu kapıdan girmediniz, girmek isteyenlere de engel oldunuz.››'),
(2008557,68,42,11,53,'İsa oradan ayrılınca, din bilginleriyle Ferisiler Onu şiddetle sıkıştırarak birçok konuda ağzını aramaya başladılar.'),
(2008558,68,42,11,54,'Ağzından çıkacak bir sözle O''nu tuzağa düşürmek için fırsat kolluyorlardı.'),
(2008559,68,42,12,1,'O sırada halktan binlerce kişi birbirlerini ezercesine toplanmıştı. İsa önce kendi öğrencilerine şunları söylemeye başladı: ‹‹Ferisilerin mayasından -yani, ikiyüzlülükten- kaçının.'),
(2008560,68,42,12,2,'Örtülü olup da açığa çıkarılmayacak, gizli olup da bilinmeyecek hiçbir şey yoktur.'),
(2008561,68,42,12,3,'Bunun için karanlıkta söylediğiniz her söz gün ışığında duyulacak, kapalı kapılar ardında kulağa fısıldadıklarınız damlardan duyurulacaktır.'),
(2008562,68,42,12,4,'‹‹Siz dostlarıma söylüyorum, bedeni öldüren, ama ondan sonra başka bir şey yapamayanlardan korkmayın.'),
(2008563,68,42,12,5,'Kimden korkmanız gerektiğini size açıklayayım: Kişiyi öldürdükten sonra cehenneme atma yetkisine sahip olan Tanrıdan korkun. Evet, size söylüyorum, Ondan korkun.'),
(2008564,68,42,12,6,'Beş serçe iki meteliğe satılmıyor mu? Ama bunlardan bir teki bile Tanrı katında unutulmuş değildir.'),
(2008565,68,42,12,7,'Nitekim başınızdaki bütün saçlar bile sayılıdır. Korkmayın, siz birçok serçeden daha değerlisiniz.'),
(2008566,68,42,12,8,'‹‹Size şunu söyleyeyim, insanların önünde beni açıkça kabul eden herkesi, İnsanoğlu da Tanrının melekleri önünde açıkça kabul edecek.'),
(2008567,68,42,12,9,'Ama kim beni insanlar önünde inkâr ederse, kendisi de Tanrının melekleri önünde inkâr edilecek.'),
(2008568,68,42,12,10,'İnsanoğluna karşı bir söz söyleyen herkes bağışlanacak. Oysa Kutsal Ruha küfreden bağışlanmayacaktır.'),
(2008569,68,42,12,11,'‹‹Sizi havra topluluklarının, yöneticilerin ve yetkililerin önüne çıkardıklarında, ‹Kendimizi neyle, nasıl savunacağız?› ya da, ‹Ne söyleyeceğiz?› diye kaygılanmayın.'),
(2008570,68,42,12,12,'Kutsal Ruh o anda size ne söylemeniz gerektiğini öğretecektir.››'),
(2008571,68,42,12,13,'Kalabalığın içinden biri İsaya, ‹‹Öğretmenim, kardeşime söyle de mirası benimle paylaşsın›› dedi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008572,68,42,12,14,'İsa ona şöyle dedi: ‹‹Ey adam! Kim beni üzerinizde yargıç ya da hakem yaptı?››'),
(2008573,68,42,12,15,'Sonra onlara, ‹‹Dikkatli olun!›› dedi. ‹‹Her türlü açgözlülükten sakının. Çünkü insanın yaşamı, malının çokluğuna bağlı değildir.››'),
(2008574,68,42,12,16,'İsa onlara şu benzetmeyi anlattı: ‹‹Zengin bir adamın toprakları bol ürün verdi.'),
(2008575,68,42,12,17,'Adam kendi kendine, ‹Ne yapacağım? Ürünlerimi koyacak yerim yok› diye düşündü.'),
(2008576,68,42,12,18,'Sonra, ‹Şöyle yapacağım› dedi. ‹Ambarlarımı yıkıp daha büyüklerini yapacağım, bütün tahıllarımı ve mallarımı oraya yığacağım.'),
(2008577,68,42,12,19,'Kendime, ey canım, yıllarca yetecek kadar bol malın var. Rahatına bak, ye, iç, yaşamın tadını çıkar diyeceğim.›'),
(2008578,68,42,12,20,'‹‹Ama Tanrı ona, ‹Ey akılsız!› dedi. ‹Bu gece canın senden istenecek. Biriktirdiğin bu şeyler kime kalacak?›'),
(2008579,68,42,12,21,'‹‹Kendisi için servet biriktiren, ama Tanrı katında zengin olmayan kişinin sonu böyle olur.››'),
(2008580,68,42,12,22,'İsa öğrencilerine şöyle dedi: ‹‹Bu nedenle size şunu söylüyorum: ‹Ne yiyeceğiz?› diye canınız için, ‹Ne giyeceğiz?› diye bedeniniz için kaygılanmayın.'),
(2008581,68,42,12,23,'Can yiyecekten, beden de giyecekten daha önemlidir.'),
(2008582,68,42,12,24,'Kargalara bakın! Ne eker, ne biçerler; ne kilerleri, ne ambarları vardır. Tanrı yine de onları doyurur. Siz kuşlardan çok daha değerlisiniz!'),
(2008583,68,42,12,25,'Hangi biriniz kaygılanmakla ömrünü bir anlık uzatabilir?'),
(2008584,68,42,12,26,'Bu küçücük işe bile gücünüz yetmediğine göre, öbür konularda neden kaygılanıyorsunuz?'),
(2008585,68,42,12,27,'‹‹Zambakların nasıl büyüdüğüne bakın! Ne çalışırlar, ne de iplik eğirirler. Ama size şunu söyleyeyim, bütün görkemine karşın Süleyman bile bunlardan biri gibi giyinmiş değildi.'),
(2008586,68,42,12,28,'Ey kıt imanlılar, bugün var olup yarın ocağa atılacak olan kır otunu böyle giydiren Tanrının sizi de giydireceği çok daha kesindir.'),
(2008587,68,42,12,29,'‹Ne yiyeceğiz, ne içeceğiz?› diye düşünüp tasalanmayın.'),
(2008588,68,42,12,30,'Dünya ulusları hep bu şeylerin peşinden giderler. Oysa Babanız, bunlara gereksinmeniz olduğunu bilir.'),
(2008589,68,42,12,31,'Siz Onun egemenliğinin ardından gidin, o zaman size bunlar da verilecektir.'),
(2008590,68,42,12,32,'‹‹Korkma, ey küçük sürü! Çünkü Babanız, egemenliği size vermeyi uygun gördü.'),
(2008591,68,42,12,33,'Mallarınızı satın, sadaka olarak verin. Kendinize eskimeyen keseler, göklerde tükenmeyen bir hazine edinin. Orada ne hırsız ona yaklaşır, ne de güve onu yer.'),
(2008592,68,42,12,34,'Hazineniz neredeyse, yüreğiniz de orada olacaktır.››'),
(2008593,68,42,12,35,'‹‹Kuşaklarınız belinizde bağlı ve kandilleriniz yanar durumda hazır olun.'),
(2008594,68,42,12,36,'Düğün şenliğinden dönecek olan efendilerinin gelip kapıyı çaldığı an kapıyı açmak için hazır bekleyen köleler gibi olun.'),
(2008595,68,42,12,37,'Efendileri geldiğinde uyanık bulunan kölelere ne mutlu! Size doğrusunu söyleyeyim, efendileri beline kuşağını bağlayacak, kölelerini sofraya oturtacak ve gelip onlara hizmet edecek.'),
(2008596,68,42,12,38,'Efendi gecenin ister ikinci, ister üçüncü nöbetinde gelsin, uyanık bulacağı kölelere ne mutlu!'),
(2008597,68,42,12,39,'Ama şunu bilin ki, ev sahibi, hırsızın hangi saatte geleceğini bilse, evinin soyulmasına fırsat vermez.'),
(2008598,68,42,12,40,'Siz de hazır olun. Çünkü İnsanoğlu beklemediğiniz saatte gelecektir.››'),
(2008599,68,42,12,41,'Petrus, ‹‹Ya Rab›› dedi, ‹‹Bu benzetmeyi bizim için mi anlatıyorsun, yoksa herkes için mi?››'),
(2008600,68,42,12,42,'Rab de şöyle dedi: ‹‹Efendinin, uşaklarına vaktinde azık vermek için başlarına atadığı güvenilir ve akıllı kâhya kimdir?'),
(2008601,68,42,12,43,'Efendisi eve döndüğünde işinin başında bulacağı o köleye ne mutlu!'),
(2008602,68,42,12,44,'Size gerçeği söyleyeyim, efendisi onu bütün malının üzerinde yetkili kılacak.'),
(2008603,68,42,12,45,'Ama o köle içinden, ‹Efendim gecikiyor› der, kadın ve erkek hizmetkârları dövmeye, yiyip içip sarhoş olmaya başlarsa, efendisi, onun beklemediği günde, ummadığı saatte gelecek, onu şiddetle cezalandırıp imansızlarla bir tutacaktır.'),
(2008604,68,42,12,47,'‹‹Efendisinin isteğini bilip de hazırlık yapmayan, onun isteğini yerine getirmeyen köle çok dayak yiyecek.'),
(2008605,68,42,12,48,'Oysa bilmeden dayağı hak eden davranışlarda bulunan, az dayak yiyecek. Kime çok verilmişse, ondan çok istenecek. Kime çok şey emanet edilmişse, kendisinden daha fazlası istenecektir.'),
(2008606,68,42,12,49,'‹‹Ben dünyaya ateş yağdırmaya geldim. Keşke bu ateş daha şimdiden alevlenmiş olsaydı!'),
(2008607,68,42,12,50,'Katlanmam gereken bir vaftiz var. Bu vaftiz gerçekleşinceye dek nasıl da sıkıntı çekiyorum!'),
(2008608,68,42,12,51,'Yeryüzüne barış getirmeye mi geldiğimi sanıyorsunuz? Size hayır diyorum, ayrılık getirmeye geldim.'),
(2008609,68,42,12,52,'Bundan böyle bir evde beş kişi, ikiye karşı üç, üçe karşı iki bölünmüş olacak.'),
(2008610,68,42,12,53,'Baba oğluna karşı, oğul babasına karşı, anne kızına karşı, kız annesine karşı, kaynana gelinine karşı, gelin kaynanasına karşı olacaktır.››'),
(2008611,68,42,12,54,'İsa halka şunları da söyledi: ‹‹Batıda bir bulutun yükseldiğini görünce siz hemen, ‹Sağanak geliyor› diyorsunuz, ve öyle oluyor.'),
(2008612,68,42,12,55,'Rüzgarın güneyden estiğini görünce, ‹Çok sıcak olacak› diyorsunuz, ve öyle oluyor.'),
(2008613,68,42,12,56,'Sizi ikiyüzlüler! Yeryüzünün ve gökyüzünün görünümünden bir anlam çıkarabiliyorsunuz da, şimdiki zamanın anlamını nasıl oluyor da çıkaramıyorsunuz?'),
(2008614,68,42,12,57,'‹‹Doğru olana neden kendiniz karar vermiyorsunuz?'),
(2008615,68,42,12,58,'Sizden davacı olanla birlikte yargıca giderken, yolda onunla anlaşmak için elinizden geleni yapın. Yoksa o sizi yargıcın önüne sürükler, yargıç gardiyanın eline verir, gardiyan da sizi hapse atar.'),
(2008616,68,42,12,59,'Size şunu söyleyeyim, borcunuzun son kuruşunu ödemedikçe oradan asla çıkamazsınız.››'),
(2008617,68,42,13,1,'O sırada bazı kişiler gelip İsaya bir haber getirdiler. Pilatusun nasıl bazı Celilelileri öldürüp kanlarını kendi kestikleri kurbanların kanına kattığını anlattılar.'),
(2008618,68,42,13,2,'İsa onlara şöyle karşılık verdi: ‹‹Böyle acı çeken bu Celilelilerin, bütün öbür Celilelilerden daha günahlı olduğunu mu sanıyorsunuz?'),
(2008619,68,42,13,3,'Size hayır diyorum. Ama tövbe etmezseniz, hepiniz böyle mahvolacaksınız.'),
(2008620,68,42,13,4,'Ya da, Şiloahtaki kule üzerlerine yıkılınca ölen o on sekiz kişinin, Yeruşalimde yaşayan öbür insanların hepsinden daha suçlu olduğunu mu sanıyorsunuz?'),
(2008621,68,42,13,5,'Size hayır diyorum. Ama tövbe etmezseniz, hepiniz böyle mahvolacaksınız.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008622,68,42,13,6,'İsa şu benzetmeyi anlattı: ‹‹Adamın birinin bağında dikili bir incir ağacı vardı. Adam gelip ağaçta meyve aradı, ama bulamadı.'),
(2008623,68,42,13,7,'Bağcıya, ‹Bak› dedi, ‹Ben üç yıldır gelip bu incir ağacında meyve arıyorum, bulamıyorum. Onu kes. Toprağın besinini neden boş yere tüketsin?›'),
(2008624,68,42,13,8,'‹‹Bağcı, ‹Efendim› diye karşılık verdi, ‹Ağacı bir yıl daha bırak, bu arada ben çevresini kazıp gübreleyeyim.'),
(2008625,68,42,13,9,'Gelecek yıl meyve verirse, ne iyi; vermezse, onu kesersin.› ››'),
(2008626,68,42,13,10,'Bir Şabat Günü İsa, havralardan birinde öğretiyordu.'),
(2008627,68,42,13,11,'On sekiz yıldır içinde hastalık ruhu bulunan bir kadın da oradaydı. İki büklüm olmuş, belini hiç doğrultamıyordu.'),
(2008628,68,42,13,12,'İsa onu görünce yanına çağırdı. ‹‹Kadın›› dedi, ‹‹Hastalığından kurtuldun.››'),
(2008629,68,42,13,13,'Ellerini kadının üzerine koydu. Kadın hemen doğruldu ve Tanrıyı yüceltmeye başladı.'),
(2008630,68,42,13,14,'İsanın hastayı Şabat Günü iyileştirmesine kızan havra yöneticisi kalabalığa seslenerek, ‹‹Çalışmak için altı gün vardır›› dedi. ‹‹O günler gelip iyileşin, Şabat Günü değil.››'),
(2008631,68,42,13,15,'Rab ona şu karşılığı verdi: ‹‹Sizi ikiyüzlüler! Her biriniz Şabat Günü kendi öküzünü ya da eşeğini yemlikten çözüp suya götürmez mi?'),
(2008632,68,42,13,16,'Buna göre, Şeytanın on sekiz yıldır bağlı tuttuğu, İbrahimin bir kızı olan bu kadının da Şabat Günü bu bağdan çözülmesi gerekmez miydi?››'),
(2008633,68,42,13,17,'İsanın bu sözleri, kendisine karşı gelenlerin hepsini utandırdı. Bütün kalabalık ise Onun yaptığı görkemli işlerin tümünü sevinçle karşıladı.'),
(2008634,68,42,13,18,'Sonra İsa şunları söyledi: ‹‹Tanrının Egemenliği neye benzer, onu neye benzeteyim?'),
(2008635,68,42,13,19,'Tanrının Egemenliği, bir adamın bahçesine ektiği hardal tanesine benzer. Tane gelişip ağaç olur, kuşlar dallarında barınır.››'),
(2008636,68,42,13,20,'İsa yine, ‹‹Tanrının Egemenliğini neye benzeteyim?›› dedi.'),
(2008637,68,42,13,21,'‹‹O, bir kadının üç ölçek una karıştırdığı mayaya benzer. Sonunda bütün hamur kabarır.››'),
(2008638,68,42,13,22,'İsa köy kent dolaşarak öğretiyor, Yeruşalime doğru ilerliyordu.'),
(2008639,68,42,13,23,'Biri Ona, ‹‹Ya Rab›› dedi, ‹‹Kurtulanların sayısı az mı olacak?›› İsa oradakilere şöyle dedi: ‹‹Dar kapıdan girmeye gayret edin. Size şunu söyleyeyim, çok kişi içeri girmek isteyecek, ama giremeyecek.'),
(2008640,68,42,13,25,'Ev sahibi kalkıp kapıyı kapattıktan sonra dışarıda durup, ‹Ya Rab, kapıyı aç bize!› diyerek kapıyı vurmaya başlayacaksınız. ‹‹O da size, ‹Kim olduğunuzu, nereden geldiğinizi bilmiyorum› diye karşılık verecek.'),
(2008641,68,42,13,26,'‹‹O zaman, ‹Biz senin önünde yiyip içtik, sen de bizim sokaklarımızda öğrettin› demeye başlayacaksınız.'),
(2008642,68,42,13,27,'‹‹O da size şöyle diyecek: ‹Kim olduğunuzu, nereden geldiğinizi bilmiyorum. Çekilin önümden, ey kötülük yapanlar!›'),
(2008643,68,42,13,28,'‹‹İbrahimi, İshakı, Yakupu ve bütün peygamberleri Tanrının Egemenliğinde, kendinizi ise dışarı atılmış gördüğünüz zaman, aranızda ağlayış ve diş gıcırtısı olacaktır.'),
(2008644,68,42,13,29,'İnsanlar doğudan batıdan, kuzeyden güneyden gelecek ve Tanrının Egemenliğinde sofraya oturacaklar.'),
(2008645,68,42,13,30,'Ve işte, sonuncu olan bazıları birinci, birinci olan bazıları da sonuncu olacak.››'),
(2008646,68,42,13,31,'Tam o sırada bazı Ferisiler gelip İsaya, ‹‹Buradan ayrılıp başka yere git. Hirodes seni öldürmek istiyor›› dediler.'),
(2008647,68,42,13,32,'İsa onlara şöyle dedi: ‹‹Gidin, o tilkiye söyleyin, ‹Bugün ve yarın cinleri kovup hastaları iyileştireceğim ve üçüncü gün hedefime ulaşacağım.›'),
(2008648,68,42,13,33,'Yine de bugün, yarın ve öbür gün yoluma devam etmeliyim. Çünkü bir peygamberin Yeruşalimin dışında ölmesi düşünülemez!'),
(2008649,68,42,13,34,'‹‹Ey Yeruşalim! Peygamberleri öldüren, kendisine gönderilenleri taşlayan Yeruşalim! Tavuğun civcivlerini kanatları altına topladığı gibi ben de kaç kez senin çocuklarını toplamak istedim, ama siz istemediniz.'),
(2008650,68,42,13,35,'Bakın, eviniz ıssız bırakılacak! Size şunu söyleyeyim: ‹Rab''bin adıyla gelene övgüler olsun!› diyeceğiniz zamana dek beni bir daha görmeyeceksiniz.››'),
(2008651,68,42,14,1,'Bir Şabat Günü İsa Ferisilerin ileri gelenlerinden birinin evine yemek yemeye gitti. Herkes Onu dikkatle gözlüyordu.'),
(2008652,68,42,14,2,'Önünde, vücudu su toplamış bir adam vardı.'),
(2008653,68,42,14,3,'İsa, Kutsal Yasa uzmanlarına ve Ferisilere, ‹‹Şabat Günü bir hastayı iyileştirmek Kutsal Yasaya uygun mudur, değil midir?›› diye sordu.'),
(2008654,68,42,14,4,'Onlar ses çıkarmadılar. İsa adamı tutup iyileştirdi, sonra eve gönderdi.'),
(2008655,68,42,14,5,'İsa onlara şöyle dedi: ‹‹Hanginiz oğlu ya da öküzü Şabat Günü kuyuya düşer de hemen çıkarmaz?››'),
(2008656,68,42,14,6,'Onlar buna hiçbir karşılık veremediler.'),
(2008657,68,42,14,7,'Yemeğe çağrılanların başköşeleri seçtiğini farkeden İsa, onlara şu benzetmeyi anlattı: ‹‹Biri seni düğüne çağırdığı zaman başköşeye kurulma. Belki senden daha saygın birini de çağırmıştır. İkinizi de çağıran gelip, ‹Yerini bu adama ver› diyebilir. O zaman utançla kalkıp en arkaya geçersin.'),
(2008658,68,42,14,10,'Bir yere çağrıldığın zaman git, en arkada otur. Öyle ki, seni çağıran gelince, ‹Arkadaşım, daha öne buyurmaz mısın?› desin. O zaman seninle birlikte sofrada oturan herkesin önünde onurlandırılmış olursun.'),
(2008659,68,42,14,11,'Kendini yücelten herkes alçaltılacak, kendini alçaltan yüceltilecektir.››'),
(2008660,68,42,14,12,'İsa kendisini yemeğe çağırmış olana da şöyle dedi: ‹‹Bir öğlen ya da akşam yemeği verdiğin zaman dostlarını, kardeşlerini, akrabalarını ve zengin komşularını çağırma. Yoksa onlar da seni çağırarak karşılık verirler.'),
(2008661,68,42,14,13,'Ama ziyafet verdiğin zaman yoksulları, kötürümleri, sakatları, körleri çağır.'),
(2008662,68,42,14,14,'Böylece mutlu olursun. Çünkü bunlar sana karşılık verecek durumda değildirler. Karşılığı sana, doğru kişiler dirildiği zaman verilecektir.››'),
(2008663,68,42,14,15,'Sofrada oturanlardan biri bunu duyunca İsaya, ‹‹Tanrının Egemenliğinde yemek yiyecek olana ne mutlu!›› dedi.'),
(2008664,68,42,14,16,'İsa ona şöyle dedi: ‹‹Adamın biri büyük bir şölen hazırlayıp birçok konuk çağırdı.'),
(2008665,68,42,14,17,'Şölen saati gelince davetlilere, ‹Buyurun, her şey hazır› diye haber vermek üzere kölesini gönderdi.'),
(2008666,68,42,14,18,'‹‹Ne var ki, hepsi anlaşmışçasına özür dilemeye başladılar. Birincisi, ‹Bir tarla satın aldım, gidip görmek zorundayım. Rica ederim, beni hoş gör› dedi.'),
(2008667,68,42,14,19,'‹‹Bir başkası, ‹Beş çift öküz aldım, onları denemeye gidiyorum. Rica ederim, beni hoş gör› dedi.'),
(2008668,68,42,14,20,'‹‹Yine bir başkası, ‹Yeni evlendim, bu nedenle gelemiyorum› dedi.'),
(2008669,68,42,14,21,'‹‹Köle geri dönüp durumu efendisine bildirdi. Bunun üzerine ev sahibi öfkelenerek kölesine, ‹Koş› dedi, ‹Kentin caddelerine, sokaklarına çık; yoksulları, kötürümleri, körleri, sakatları buraya getir.›'),
(2008670,68,42,14,22,'‹‹Köle, ‹Efendim, buyruğun yerine getirilmiştir, ama daha yer var› dedi.'),
(2008671,68,42,14,23,'‹‹Efendisi köleye, ‹Çıkıp yolları ve çit boylarını dolaş, bulduklarını gelmeye zorla da evim dolsun› dedi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008672,68,42,14,24,'‹Size şunu söyleyeyim, ilk çağrılan o adamlardan hiçbiri benim yemeğimden tatmayacaktır.› ››'),
(2008673,68,42,14,25,'Kalabalık halk toplulukları İsayla birlikte yol alıyordu. İsa dönüp onlara şöyle dedi: ‹‹Biri bana gelip de babasını, annesini, karısını, çocuklarını, kardeşlerini, hatta kendi canını bile gözden çıkarmazsa, öğrencim olamaz.'),
(2008674,68,42,14,27,'Çarmıhını yüklenip ardımdan gelmeyen, öğrencim olamaz.'),
(2008675,68,42,14,28,'‹‹Aranızdan biri bir kule yapmak isterse, bunu tamamlayacak kadar parası var mı yok mu diye önce oturup yapacağı masrafı hesap etmez mi?'),
(2008676,68,42,14,29,'Çünkü temel atıp da işi bitiremezse, durumu gören herkes, ‹Bu adam inşaata başladı, ama bitiremedi› diyerek onunla eğlenmeye başlar.'),
(2008677,68,42,14,31,'‹‹Ya da hangi kral başka bir kralla savaşa gittiğinde, üzerine yirmi bin askerle yürüyen düşmana on bin askerle karşı koyabilir miyim diye önce oturup bir değerlendirme yapmaz?'),
(2008678,68,42,14,32,'Eğer karşı koyamayacaksa, öbürü henüz uzaktayken elçiler gönderip barış koşullarını ister.'),
(2008679,68,42,14,33,'Aynı şekilde sizden kim varını yoğunu gözden çıkarmazsa, öğrencim olamaz.'),
(2008680,68,42,14,34,'‹‹Tuz yararlıdır. Ama tuz tadını yitirirse, bir daha nasıl o tadı kazanabilir?'),
(2008681,68,42,14,35,'Ne toprağa, ne de gübreye yarar; onu çöpe atarlar. İşitecek kulağı olan işitsin.››'),
(2008682,68,42,15,1,'Bütün vergi görevlileriyle günahkârlar İsayı dinlemek için Ona akın ediyordu.'),
(2008683,68,42,15,2,'Ferisilerle din bilginleri ise, ‹‹Bu adam günahkârları kabul ediyor, onlarla birlikte yemek yiyor›› diye söyleniyorlardı.'),
(2008684,68,42,15,3,'Bunun üzerine İsa onlara şu benzetmeyi anlattı: ‹‹Sizlerden birinin yüz koyunu olsa ve bunlardan bir tanesini kaybetse, doksan dokuzu bozkırda bırakarak kaybolanı bulana dek onun ardına düşmez mi?'),
(2008685,68,42,15,5,'Onu bulunca da sevinç içinde omuzlarına alır, evine döner; arkadaşlarını, komşularını çağırıp onlara, ‹Benimle birlikte sevinin, kaybolan koyunumu buldum!› der.'),
(2008686,68,42,15,7,'Size şunu söyleyeyim, aynı şekilde gökte, tövbe eden tek bir günahkâr için, tövbeyi gereksinmeyen doksan dokuz doğru kişi için duyulandan daha büyük sevinç duyulacaktır.››'),
(2008687,68,42,15,8,'‹‹Ya da on gümüş parası olan bir kadın bunlardan bir tanesini kaybetse, kandil yakıp evi süpürerek parayı bulana dek her tarafı dikkatle aramaz mı?'),
(2008688,68,42,15,9,'Parayı bulunca da arkadaşlarını, komşularını çağırıp, ‹Benimle birlikte sevinin, kaybettiğim parayı buldum!› der.'),
(2008689,68,42,15,10,'Size şunu söyleyeyim, aynı şekilde Tanrının melekleri de tövbe eden bir tek günahkâr için sevinç duyacaklar.››'),
(2008690,68,42,15,11,'İsa, ‹‹Bir adamın iki oğlu vardı›› dedi.'),
(2008691,68,42,15,12,'‹‹Bunlardan küçüğü babasına, ‹Baba› dedi, ‹Malından payıma düşeni ver bana.› Baba da servetini iki oğlu arasında paylaştırdı.'),
(2008692,68,42,15,13,'‹‹Bundan birkaç gün sonra küçük oğul her şeyini toplayıp uzak bir ülkeye gitti. Orada sefahat içinde bir yaşam sürerek varını yoğunu çarçur etti.'),
(2008693,68,42,15,14,'Delikanlı her şeyini harcadıktan sonra, o ülkede şiddetli bir kıtlık baş gösterdi, o da yokluk çekmeye başladı.'),
(2008694,68,42,15,15,'Bunun üzerine gidip o ülkenin vatandaşlarından birinin hizmetine girdi. Adam onu, domuz gütmek üzere otlaklarına yolladı.'),
(2008695,68,42,15,16,'Delikanlı, domuzların yediği keçiboynuzlarıyla karnını doyurmaya can atıyordu. Ama hiç kimse ona bir şey vermedi.'),
(2008696,68,42,15,17,'‹‹Aklı başına gelince şöyle dedi: ‹Babamın nice işçisinin fazlasıyla yiyeceği var, bense burada açlıktan ölüyorum.'),
(2008697,68,42,15,18,'Kalkıp babamın yanına döneceğim, ona, Baba diyeceğim, Tanrıya ve sana karşı günah işledim.'),
(2008698,68,42,15,19,'Ben artık senin oğlun olarak anılmaya layık değilim. Beni işçilerinden biri gibi kabul et.›'),
(2008699,68,42,15,20,'‹‹Böylece kalkıp babasının yanına döndü. Kendisi daha uzaktayken babası onu gördü, ona acıdı, koşup boynuna sarıldı ve onu öptü.'),
(2008700,68,42,15,21,'Oğlu ona, ‹Baba› dedi, ‹Tanrıya ve sana karşı günah işledim. Ben artık senin oğlun olarak anılmaya layık değilim.›'),
(2008701,68,42,15,22,'‹‹Babası ise kölelerine, ‹Çabuk, en iyi kaftanı getirip ona giydirin!› dedi. ‹Parmağına yüzük takın, ayaklarına çarık giydirin!'),
(2008702,68,42,15,23,'Besili danayı getirip kesin, yiyelim, eğlenelim.'),
(2008703,68,42,15,24,'Çünkü benim bu oğlum ölmüştü, yaşama döndü; kaybolmuştu, bulundu.› Böylece eğlenmeye başladılar.'),
(2008704,68,42,15,25,'‹‹Babanın büyük oğlu ise tarladaydı. Gelip eve yaklaştığında çalgı ve oyun seslerini duydu.'),
(2008705,68,42,15,26,'Uşaklardan birini yanına çağırıp, ‹Ne oluyor?› diye sordu.'),
(2008706,68,42,15,27,'‹‹O da, ‹Kardeşin geldi, baban da ona sağ salim kavuştuğu için besili danayı kesti› dedi.'),
(2008707,68,42,15,28,'‹‹Büyük oğul öfkelendi, içeri girmek istemedi. Babası dışarı çıkıp ona yalvardı. Ama o, babasına şöyle yanıt verdi: ‹Bak, bunca yıl senin için köle gibi çalıştım, hiçbir zaman buyruğundan çıkmadım. Ne var ki sen bana, arkadaşlarımla eğlenmem için hiçbir zaman bir oğlak bile vermedin.'),
(2008708,68,42,15,30,'Oysa senin malını fahişelerle yiyen şu oğlun eve dönünce, onun için besili danayı kestin.›'),
(2008709,68,42,15,31,'‹‹Babası ona, ‹Oğlum, sen her zaman yanımdasın, neyim varsa senindir› dedi.'),
(2008710,68,42,15,32,'‹Ama sevinip eğlenmek gerekiyordu. Çünkü bu kardeşin ölmüştü, yaşama döndü; kaybolmuştu, bulundu!› ››'),
(2008711,68,42,16,1,'İsa öğrencilerine şunları da anlattı: ‹‹Zengin bir adamın bir kâhyası vardı. Kâhya, efendisinin mallarını çarçur ediyor diye efendisine ihbar edildi.'),
(2008712,68,42,16,2,'Efendisi kâhyayı çağırıp ona, ‹Nedir bu senin hakkında duyduklarım? Kâhyalığının hesabını ver. Çünkü sen artık kâhyalık edemezsin› dedi.'),
(2008713,68,42,16,3,'‹‹Kâhya kendi kendine, ‹Ne yapacağım ben?› dedi. ‹Efendim kâhyalığı elimden alıyor. Toprak kazmaya gücüm yetmez, dilenmekten utanırım.'),
(2008714,68,42,16,4,'Kâhyalıktan kovulduğum zaman başkaları beni evlerine kabul etsinler diye ne yapacağımı biliyorum.›'),
(2008715,68,42,16,5,'‹‹Böylelikle efendisine borcu olanların hepsini tek tek yanına çağırdı. Birincisine, ‹Efendime ne kadar borcun var?› dedi.'),
(2008716,68,42,16,6,'‹‹Adam, ‹Yüz ölçek zeytinyağı› karşılığını verdi. ‹‹Kâhya ona, ‹Borç senedini al ve hemen otur, elli ölçek diye yaz› dedi.'),
(2008717,68,42,16,7,'‹‹Sonra bir başkasına, ‹Senin borcun ne kadar?› dedi. ‹‹ ‹Yüz ölçek buğday› dedi öteki. ‹‹Ona da, ‹Borç senedini al, seksen ölçek diye yaz› dedi.'),
(2008718,68,42,16,8,'‹‹Efendisi, dürüst olmayan kâhyayı, akıllıca davrandığı için övdü. Gerçekten bu çağın insanları, kendilerine benzer kişilerle ilişkilerinde, ışıkta yürüyenlerden daha akıllı oluyorlar.'),
(2008719,68,42,16,9,'Size şunu söyleyeyim, dünyanın aldatıcı servetini kendinize dost edinmek için kullanın ki, bu servet yok olunca sizi sonsuza dek kalacak konutlara kabul etsinler.››'),
(2008720,68,42,16,10,'‹‹En küçük işte güvenilir olan kişi, büyük işte de güvenilir olur. En küçük işte dürüst olmayan kişi, büyük işte de dürüst olmaz.'),
(2008721,68,42,16,11,'Dünyanın aldatıcı serveti konusunda güvenilir değilseniz, gerçek serveti size kim emanet eder?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008722,68,42,16,12,'Başkasının malı konusunda güvenilir değilseniz, kendi malınız olmak üzere size kim bir şey verir?'),
(2008723,68,42,16,13,'‹‹Hiçbir uşak iki efendiye kulluk edemez. Ya birinden nefret edip öbürünü sever, ya da birine bağlanıp öbürünü hor görür. Siz hem Tanrıya, hem paraya kulluk edemezsiniz.››'),
(2008724,68,42,16,14,'Parayı seven Ferisiler bütün bu sözleri duyunca İsayla alay etmeye başladılar.'),
(2008725,68,42,16,15,'O da onlara şöyle dedi: ‹‹Siz insanlar önünde kendinizi temize çıkarıyorsunuz, ama Tanrı yüreğinizi biliyor. İnsanların gururlandıkları ne varsa, Tanrıya iğrenç gelir.'),
(2008726,68,42,16,16,'‹‹Kutsal Yasa ve peygamberlerin devri Yahyanın zamanına dek sürdü. O zamandan bu yana Tanrının Egemenliği müjdeleniyor ve herkes oraya zorla girmeye çalışıyor.'),
(2008727,68,42,16,17,'Yerin ve göğün ortadan kalkması, Kutsal Yasanın ufacık bir noktasının yok olmasından daha kolaydır.'),
(2008728,68,42,16,18,'‹‹Karısını boşayıp başkasıyla evlenen zina etmiş olur. Kocasından boşanmış bir kadınla evlenen de zina etmiş olur.››'),
(2008729,68,42,16,19,'‹‹Zengin bir adam vardı. Mor, ince keten giysiler giyer, bolluk içinde her gün eğlenirdi.'),
(2008730,68,42,16,20,'Her tarafı yara içinde olan Lazar adında yoksul bir adam bu zenginin kapısının önüne bırakılırdı; zenginin sofrasından düşen kırıntılarla karnını doyurmaya can atardı. Bir yandan da köpekler gelip onun yaralarını yalardı.'),
(2008731,68,42,16,22,'‹‹Bir gün yoksul adam öldü, melekler onu alıp İbrahimin yanına götürdüler. Sonra zengin adam da öldü ve gömüldü.'),
(2008732,68,42,16,23,'Ölüler diyarında ıstırap çeken zengin adam başını kaldırıp uzakta İbrahimi ve onun yanında Lazarı gördü.'),
(2008733,68,42,16,24,'‹Ey babamız İbrahim, acı bana!› diye seslendi. ‹Lazarı gönder de parmağının ucunu suya batırıp dilimi serinletsin. Bu alevlerin içinde azap çekiyorum.›'),
(2008734,68,42,16,25,'‹‹İbrahim, ‹Oğlum› dedi, ‹Yaşamın boyunca senin iyilik payını, Lazarın da kötülük payını aldığını unutma. Şimdiyse o burada teselli ediliyor, sen de azap çekiyorsun.'),
(2008735,68,42,16,26,'Üstelik, aramıza öyle bir uçurum kondu ki, ne buradan size gelmek isteyenler gelebilir, ne de oradan kimse bize gelebilir.›'),
(2008736,68,42,16,27,'‹‹Zengin adam şöyle dedi: ‹Öyleyse baba, sana rica ederim, Lazarı babamın evine gönder.'),
(2008737,68,42,16,28,'Çünkü beş kardeşim var. Lazar onları uyarsın ki, onlar da bu ıstırap yerine düşmesinler.›'),
(2008738,68,42,16,29,'‹‹İbrahim, ‹Onlarda Musanın ve peygamberlerin sözleri var, onları dinlesinler› dedi.'),
(2008739,68,42,16,30,'‹‹Zengin adam, ‹Hayır, İbrahim baba, dinlemezler!› dedi. ‹Ancak ölüler arasından biri onlara giderse, tövbe ederler.›'),
(2008740,68,42,16,31,'‹‹İbrahim ona, ‹Eğer Musa ile peygamberleri dinlemezlerse, ölüler arasından biri dirilse bile ikna olmazlar› dedi.››'),
(2008741,68,42,17,1,'İsa öğrencilerine şöyle dedi: ‹‹İnsanı günaha düşüren tuzakların olması kaçınılmazdır. Ama bu tuzaklara aracılık eden kişinin vay haline!'),
(2008742,68,42,17,2,'Böyle bir kişi bu küçüklerden birini günaha düşüreceğine, boynuna bir değirmen taşı geçirilip denize atılsa, kendisi için daha iyi olur.'),
(2008743,68,42,17,3,'Yaşantınıza dikkat edin! Kardeşiniz günah işlerse, onu azarlayın; tövbe ederse, bağışlayın.'),
(2008744,68,42,17,4,'Günde yedi kez size karşı günah işler ve yedi kez size gelip, ‹Tövbe ediyorum› derse, onu bağışlayın.››'),
(2008745,68,42,17,5,'Elçiler Rabbe, ‹‹İmanımızı artır!›› dediler.'),
(2008746,68,42,17,6,'Rab şöyle dedi: ‹‹Bir hardal tanesi kadar imanınız olsa, şu dut ağacına, ‹Kökünden sökül ve denizin içine dikil› dersiniz, o da sözünüzü dinler.'),
(2008747,68,42,17,7,'‹‹Hanginizin çift süren ya da çobanlık eden bir kölesi olur da, tarladan dönüşünde ona, ‹Çabuk gel, sofraya otur› der?'),
(2008748,68,42,17,8,'Tersine ona, ‹Yemeğimi hazırla, kuşağını bağla, ben yiyip içerken bana hizmet et. Sonra sen yiyip içersin› demez mi?'),
(2008749,68,42,17,9,'Verdiği buyrukları yerine getirdi diye köleye teşekkür eder mi?'),
(2008750,68,42,17,10,'Siz de böylece, size verilen buyrukların hepsini yerine getirdikten sonra, ‹Biz değersiz kullarız; sadece yapmamız gerekeni yaptık› deyin.››'),
(2008751,68,42,17,11,'Yeruşalime doğru yoluna devam eden İsa, Samiriye ile Celile arasındaki sınır bölgesinden geçiyordu.'),
(2008752,68,42,17,12,'Köyün birine girerken Onu cüzamlı on adam karşıladı. Bunlar uzakta durarak, ‹‹İsa, Efendimiz, halimize acı!›› diye seslendiler.'),
(2008753,68,42,17,14,'İsa onları görünce, ‹‹Gidin, kâhinlere görünün›› dedi. Adamlar yolda giderken cüzamdan temizlendiler.'),
(2008754,68,42,17,15,'Onlardan biri, iyileştiğini görünce yüksek sesle Tanrıyı yücelterek geri döndü, yüzüstü İsanın ayaklarına kapanıp Ona teşekkür etti. Bu adam Samiriyeliydi.'),
(2008755,68,42,17,17,'İsa, ‹‹İyileşenler on kişi değil miydi?›› diye sordu. ‹‹Öbür dokuzu nerede?'),
(2008756,68,42,17,18,'Tanrıyı yüceltmek için bu yabancıdan başka geri dönen olmadı mı?››'),
(2008757,68,42,17,19,'Sonra adama, ‹‹Ayağa kalk, git›› dedi. ‹‹İmanın seni kurtardı.››'),
(2008758,68,42,17,20,'Ferisiler İsaya, ‹‹Tanrının Egemenliği ne zaman gelecek?›› diye sordular. İsa onlara şöyle yanıt verdi: ‹‹Tanrının Egemenliği göze görünür bir şekilde gelmez.'),
(2008759,68,42,17,21,'İnsanlar da, ‹İşte burada› ya da, ‹İşte şurada› demeyecekler. Çünkü Tanrının Egemenliği içinizdedir.››'),
(2008760,68,42,17,22,'İsa öğrencilerine şöyle dedi: ‹‹Öyle günler gelecek ki, İnsanoğlunun günlerinden birini görmeyi özleyeceksiniz, ama görmeyeceksiniz.'),
(2008761,68,42,17,23,'İnsanlar size, ‹İşte orada›, ‹İşte burada› diyecekler. Gitmeyin, onların arkasından koşmayın.'),
(2008762,68,42,17,24,'Şimşek çakıp göğü bir ucundan öbür ucuna dek nasıl aydınlatırsa, İnsanoğlu kendi gününde öyle olacaktır.'),
(2008763,68,42,17,25,'Ama önce Onun çok acı çekmesi ve bu kuşak tarafından reddedilmesi gerekir.'),
(2008764,68,42,17,26,'‹‹Nuhun günlerinde nasıl olduysa, İnsanoğlunun günlerinde de öyle olacak.'),
(2008765,68,42,17,27,'Nuhun gemiye bindiği güne dek insanlar yiyip içiyor, evlenip evlendiriliyorlardı. Sonra tufan gelip hepsini yok etti.'),
(2008766,68,42,17,28,'Lutun günlerinde de durum aynıydı. İnsanlar yiyip içiyor, alıp satıyor, tohum ekiyor, ev yapıyorlardı.'),
(2008767,68,42,17,29,'Ama Lutun Sodomdan ayrıldığı gün gökten ateşle kükürt yağdı ve hepsini yok etti.'),
(2008768,68,42,17,30,'‹‹İnsanoğlunun ortaya çıkacağı gün durum aynı olacaktır.'),
(2008769,68,42,17,31,'O gün damda olan, evdeki eşyalarını almak için aşağı inmesin. Tarlada olan da geri dönmesin.'),
(2008770,68,42,17,32,'Lutun karısını hatırlayın!'),
(2008771,68,42,17,33,'Canını esirgemek isteyen onu yitirecek. Canını yitiren ise onu yaşatacaktır.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008772,68,42,17,34,'Size şunu söyleyeyim, o gece aynı yatakta olan iki kişiden biri alınacak, öbürü bırakılacak.'),
(2008773,68,42,17,35,'Birlikte buğday öğüten iki kadından biri alınacak, öbürü bırakılacak.››'),
(2008774,68,42,17,37,'Onlar İsa''ya, ‹‹Bu olaylar nerede olacak, Rab?›› diye sordular. O da onlara, ‹‹Leş neredeyse, akbabalar da oraya üşüşecek›› dedi.'),
(2008775,68,42,18,1,'İsa öğrencilerine, hiç usanmadan, her zaman dua etmeleri gerektiğini belirten şu benzetmeyi anlattı: ‹‹Kentin birinde Tanrıdan korkmayan, insana saygı duymayan bir yargıç vardı.'),
(2008776,68,42,18,3,'Yine o kentte bir dul kadın vardı. Yargıca sürekli gidip, ‹Davacı olduğum kişiden hakkımı al› diyordu.'),
(2008777,68,42,18,4,'‹‹Yargıç bir süre ilgisiz kaldı. Ama sonunda kendi kendine, ‹Ben her ne kadar Tanrıdan korkmaz, insana saygı duymazsam da, bu dul kadın beni rahatsız ettiği için hakkını alacağım. Yoksa sürekli gelip beni canımdan bezdirecek› dedi.››'),
(2008778,68,42,18,6,'Rab şöyle devam etti: ‹‹Adaletsiz yargıcın ne söylediğini duydunuz.'),
(2008779,68,42,18,7,'Tanrı da, gece gündüz kendisine yakaran seçilmişlerinin hakkını almayacak mı? Onları çok bekletecek mi?'),
(2008780,68,42,18,8,'Size şunu söyleyeyim, onların hakkını tez alacaktır. Ama İnsanoğlu geldiği zaman acaba yeryüzünde iman bulacak mı?››'),
(2008781,68,42,18,9,'Kendi doğruluklarına güvenip başkalarına tepeden bakan bazı kişilere İsa şu benzetmeyi anlattı: ‹‹Biri Ferisi, öbürü vergi görevlisi iki kişi dua etmek üzere tapınağa çıktı.'),
(2008782,68,42,18,11,'Ferisi ayakta kendi kendine şöyle dua etti: ‹Tanrım, öbür insanlara -soygunculara, hak yiyenlere, zina edenlere- ya da şu vergi görevlisine benzemediğim için sana şükrederim.'),
(2008783,68,42,18,12,'Haftada iki gün oruç tutuyor, bütün kazancımın ondalığını veriyorum.›'),
(2008784,68,42,18,13,'‹‹Vergi görevlisi ise uzakta durdu, gözlerini göğe kaldırmak bile istemiyordu, ancak göğsünü döverek, ‹Tanrım, ben günahkâra merhamet et› diyordu.'),
(2008785,68,42,18,14,'‹‹Size şunu söyleyeyim, Ferisi değil, bu adam aklanmış olarak evine döndü. Çünkü kendini yücelten herkes alçaltılacak, kendini alçaltan ise yüceltilecektir.››'),
(2008786,68,42,18,15,'Bazıları bebekleri bile İsaya getiriyor, onlara dokunmasını istiyorlardı. Bunu gören öğrenciler onları azarladılar.'),
(2008787,68,42,18,16,'Ama İsa çocukları yanına çağırarak, ‹‹Bırakın, çocuklar bana gelsin, onlara engel olmayın!›› dedi. ‹‹Çünkü Tanrının Egemenliği böylelerinindir.'),
(2008788,68,42,18,17,'Size doğrusunu söyleyeyim, Tanrının Egemenliğini bir çocuk gibi kabul etmeyen, bu egemenliğe asla giremez.››'),
(2008789,68,42,18,18,'İleri gelenlerden biri İsaya, ‹‹İyi öğretmenim, sonsuz yaşama kavuşmak için ne yapmalıyım?›› diye sordu.'),
(2008790,68,42,18,19,'İsa, ‹‹Bana neden iyi diyorsun?›› dedi. ‹‹İyi olan yalnız biri var, O da Tanrıdır.'),
(2008791,68,42,18,20,'Onun buyruklarını biliyorsun: ‹Zina etmeyeceksin, adam öldürmeyeceksin, çalmayacaksın, yalan yere tanıklık etmeyeceksin, annene babana saygı göstereceksin.› ››'),
(2008792,68,42,18,21,'‹‹Bunların hepsini gençliğimden beri yerine getiriyorum›› dedi adam.'),
(2008793,68,42,18,22,'İsa bunu duyunca ona, ‹‹Hâlâ bir eksiğin var›› dedi. ‹‹Neyin varsa hepsini sat, parasını yoksullara dağıt; böylece göklerde hazinen olur. Sonra gel, beni izle.››'),
(2008794,68,42,18,23,'Adam bu sözleri duyunca çok üzüldü. Çünkü son derece zengindi.'),
(2008795,68,42,18,24,'Onun üzüntüsünü gören İsa, ‹‹Varlıklı kişilerin Tanrı Egemenliğine girmesi ne kadar güç!›› dedi.'),
(2008796,68,42,18,25,'‹‹Nitekim devenin iğne deliğinden geçmesi, zenginin Tanrı Egemenliğine girmesinden daha kolaydır.››'),
(2008797,68,42,18,26,'Bunu işitenler, ‹‹Öyleyse kim kurtulabilir?›› dediler.'),
(2008798,68,42,18,27,'İsa, ‹‹İnsanlar için imkânsız olan, Tanrı için mümkündür›› dedi.'),
(2008799,68,42,18,28,'Petrus, ‹‹Bak, biz her şeyimizi bırakıp senin ardından geldik›› dedi.'),
(2008800,68,42,18,29,'İsa onlara şöyle dedi: ‹‹Size doğrusunu söyleyeyim, Tanrının Egemenliği uğruna evini, karısını, kardeşlerini, annesiyle babasını ya da çocuklarını bırakıp da bu çağda bunların kat kat fazlasına ve gelecek çağda sonsuz yaşama kavuşmayacak hiç kimse yoktur.››'),
(2008801,68,42,18,31,'İsa, Onikileri bir yana çekip onlara şöyle dedi: ‹‹Şimdi Yeruşalime gidiyoruz. Peygamberlerin İnsanoğluyla ilgili yazdıklarının tümü yerine gelecektir.'),
(2008802,68,42,18,32,'O, öteki uluslara teslim edilecek. Onunla alay edecek, Ona hakaret edecekler; üzerine tükürecek ve Onu kamçılayıp öldürecekler. Ne var ki O, üçüncü gün dirilecek.››'),
(2008803,68,42,18,34,'Öğrenciler bu sözlerden hiçbir şey anlamadılar. Bu sözlerin anlamı onlardan gizlenmişti, anlatılanları kavrayamıyorlardı.'),
(2008804,68,42,18,35,'İsa Erihaya yaklaşırken kör bir adam yol kenarında oturmuş dileniyordu.'),
(2008805,68,42,18,36,'Adam oradan geçen kalabalığı duyunca, ‹‹Ne oluyor?›› diye sordu.'),
(2008806,68,42,18,37,'Ona, ‹‹Nasıralı İsa geçiyor›› dediler.'),
(2008807,68,42,18,38,'O da, ‹‹Ey Davut Oğlu İsa, halime acı!›› diye bağırdı.'),
(2008808,68,42,18,39,'Önden gidenler onu azarlayarak susturmak istedilerse de o, ‹‹Ey Davut Oğlu, halime acı!›› diyerek daha çok bağırdı.'),
(2008809,68,42,18,40,'İsa durup adamın kendisine getirilmesini buyurdu. Adam yaklaşınca İsa, ‹‹Senin için ne yapmamı istiyorsun?›› diye sordu. O da, ‹‹Ya Rab, gözlerim görsün›› dedi.'),
(2008810,68,42,18,42,'İsa, ‹‹Gözlerin görsün›› dedi. ‹‹İmanın seni kurtardı.››'),
(2008811,68,42,18,43,'Adam o anda yeniden görmeye başladı ve Tanrı''yı yücelterek İsa''nın ardından gitti. Bunu gören bütün halk Tanrı''ya övgüler sundu.'),
(2008812,68,42,19,1,'İsa Erihaya girdi. Kentin içinden geçiyordu.'),
(2008813,68,42,19,2,'Orada vergi görevlilerinin başı olan, Zakkay adında zengin bir adam vardı.'),
(2008814,68,42,19,3,'İsanın kim olduğunu görmek istiyor, ama boyu kısa olduğu için kalabalıktan ötürü göremiyordu.'),
(2008815,68,42,19,4,'İsayı görebilmek için önden koşup bir yabanıl incir ağacına tırmandı. Çünkü İsa oradan geçecekti.'),
(2008816,68,42,19,5,'İsa oraya varınca yukarı bakıp, ‹‹Zakkay, çabuk aşağı in!›› dedi. ‹‹Bugün senin evinde kalmam gerekiyor.››'),
(2008817,68,42,19,6,'Zakkay hızla aşağı indi ve sevinç içinde İsayı evine buyur etti.'),
(2008818,68,42,19,7,'Bunu görenlerin hepsi söylenmeye başladı: ‹‹Gidip günahkâr birine konuk oldu!›› dediler.'),
(2008819,68,42,19,8,'Zakkay ayağa kalkıp Rabbe şöyle dedi: ‹‹Ya Rab, işte malımın yarısını yoksullara veriyorum. Bir kimseden haksızlıkla bir şey aldımsa, dört katını geri vereceğim.››'),
(2008820,68,42,19,9,'İsa dedi ki, ‹‹Bu ev bugün kurtuluşa kavuştu. Çünkü bu adam da İbrahimin oğludur.'),
(2008821,68,42,19,10,'Nitekim İnsanoğlu, kaybolanı arayıp kurtarmak için geldi.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008822,68,42,19,11,'Oradakiler bu sözleri dinlerken İsa konuşmasını bir benzetmeyle sürdürdü. Çünkü Yeruşalime yaklaşmıştı ve onlar, Tanrının Egemenliğinin hemen ortaya çıkacağını sanıyorlardı.'),
(2008823,68,42,19,12,'Bu nedenle İsa şöyle dedi: ‹‹Soylu bir adam, kral atanıp dönmek üzere uzak bir ülkeye gitti.'),
(2008824,68,42,19,13,'Gitmeden önce kölelerinden onunu çağırıp onlara birer mina verdi. ‹Ben dönünceye dek bu paraları işletin› dedi.'),
(2008825,68,42,19,14,'‹‹Ne var ki, ülkesinin halkı adamdan nefret ediyordu. Arkasından temsilciler göndererek, ‹Bu adamın üzerimize kral olmasını istemiyoruz› diye haber ilettiler.'),
(2008826,68,42,19,15,'‹‹Adam kral atanmış olarak geri döndüğünde, parayı vermiş olduğu köleleri çağırtıp ne kazandıklarını öğrenmek istedi.'),
(2008827,68,42,19,16,'Birincisi geldi, ‹Efendimiz› dedi, ‹Senin bir minan on mina daha kazandı.›'),
(2008828,68,42,19,17,'‹‹Efendisi ona, ‹Aferin, iyi köle!› dedi. ‹En küçük işte güvenilir olduğunu gösterdiğin için on kent üzerinde yetkili olacaksın.›'),
(2008829,68,42,19,18,'‹‹İkincisi gelip, ‹Efendimiz, senin bir minan beş mina daha kazandı› dedi.'),
(2008830,68,42,19,19,'‹‹Efendisi ona da, ‹Sen beş kent üzerinde yetkili olacaksın› dedi.'),
(2008831,68,42,19,20,'‹‹Başka biri geldi, ‹Efendimiz› dedi, ‹İşte senin minan! Onu bir mendile sarıp sakladım.'),
(2008832,68,42,19,21,'Çünkü senden korktum, sert adamsın; kendinden koymadığını alır, ekmediğini biçersin.›'),
(2008833,68,42,19,22,'‹‹Efendisi ona, ‹Ey kötü köle, seni kendi ağzından çıkan sözle yargılayacağım› dedi. ‹Kendinden koymadığını alan, ekmediğini biçen sert bir adam olduğumu bildiğine göre,'),
(2008834,68,42,19,23,'neden paramı faize vermedin? Ben de geldiğimde onu faiziyle geri alırdım.›'),
(2008835,68,42,19,24,'‹‹Sonra çevrede duranlara, ‹Elindeki minayı alın, on minası olana verin› dedi.'),
(2008836,68,42,19,25,'‹‹Ona, ‹Efendimiz› dediler, ‹Onun zaten on minası var!›'),
(2008837,68,42,19,26,'‹‹O da, ‹Size şunu söyleyeyim, kimde varsa ona daha çok verilecek. Ama kimde yoksa, kendisinde olan da elinden alınacak› dedi.'),
(2008838,68,42,19,27,'‹Beni kral olarak istemeyen o düşmanlarıma gelince, onları buraya getirin ve gözümün önünde kılıçtan geçirin!› ››'),
(2008839,68,42,19,28,'İsa, bu sözleri söyledikten sonra önden yürüyerek Yeruşalime doğru ilerledi.'),
(2008840,68,42,19,29,'Zeytin Dağının yamacındaki Beytfaci ile Beytanyaya yaklaştığında iki öğrencisini önden gönderdi. Onlara, ‹‹Karşıdaki köye gidin›› dedi, ‹‹Köye girince, üzerine daha hiç kimsenin binmediği, bağlı duran bir sıpa bulacaksınız. Onu çözüp bana getirin.'),
(2008841,68,42,19,31,'Biri size, ‹Onu niçin çözüyorsunuz?› diye sorarsa, ‹Rabbin ona ihtiyacı var› dersiniz.››'),
(2008842,68,42,19,32,'Gönderilen öğrenciler gittiler, her şeyi İsanın kendilerine anlattığı gibi buldular.'),
(2008843,68,42,19,33,'Sıpayı çözerlerken hayvanın sahipleri onlara, ‹‹Sıpayı niye çözüyorsunuz?›› dediler.'),
(2008844,68,42,19,34,'Onlar da, ‹‹Rabbin ona ihtiyacı var›› karşılığını verdiler.'),
(2008845,68,42,19,35,'Sıpayı İsaya getirdiler, üzerine kendi giysilerini atarak İsayı üstüne bindirdiler.'),
(2008846,68,42,19,36,'İsa ilerlerken halk, giysilerini yola seriyordu.'),
(2008847,68,42,19,37,'İsa Zeytin Dağından aşağı inen yola yaklaştığı sırada, öğrencilerinden oluşan kalabalığın tümü, görmüş oldukları bütün mucizelerden ötürü, sevinç içinde yüksek sesle Tanrıyı övmeye başladılar.'),
(2008848,68,42,19,38,'‹‹Rabbin adıyla gelen Krala övgüler olsun! Gökte esenlik, en yücelerde yücelik olsun!›› diyorlardı.'),
(2008849,68,42,19,39,'Kalabalığın içinden bazı Ferisiler Ona, ‹‹Öğretmen, öğrencilerini sustur!›› dediler.'),
(2008850,68,42,19,40,'İsa, ‹‹Size şunu söyleyeyim, bunlar susacak olsa, taşlar bağıracaktır!›› diye karşılık verdi.'),
(2008851,68,42,19,41,'İsa Yeruşalime yaklaşıp kenti görünce ağladı.'),
(2008852,68,42,19,42,'‹‹Keşke bugün sen de esenliğe giden yolu bilseydin›› dedi. ‹‹Ama şimdilik bu senin gözlerinden gizlendi.'),
(2008853,68,42,19,43,'Senin için öyle günler gelecek ki, düşmanların seni setlerle çevirecek, kuşatıp her yandan sıkıştıracaklar.'),
(2008854,68,42,19,44,'Seni de, bağrındaki çocukları da yere çalacaklar. Sende taş üstünde taş bırakmayacaklar. Çünkü Tanrının senin yardımına geldiği zamanı farketmedin.››'),
(2008855,68,42,19,45,'Sonra İsa tapınağın avlusuna girerek satıcıları dışarı kovmaya başladı.'),
(2008856,68,42,19,46,'Onlara, ‹‹ ‹Evim dua evi olacak› diye yazılmıştır. Ama siz onu haydut inine çevirdiniz›› dedi.'),
(2008857,68,42,19,47,'İsa her gün tapınakta öğretiyordu. Başkâhinler, din bilginleri ve halkın ileri gelenleri ise O''nu yok etmek istiyor, ama bunu nasıl yapacaklarını bilemiyorlardı. Çünkü bütün halk O''nu can kulağıyla dinliyordu.'),
(2008858,68,42,20,1,'O günlerden birinde, İsa tapınakta halka öğretip Müjdeyi duyururken, başkâhinler ve din bilginleri, ileri gelenlerle birlikte çıkageldiler.'),
(2008859,68,42,20,2,'Ona, ‹‹Söyle bize, bunları hangi yetkiyle yapıyorsun? Bu yetkiyi sana kim verdi?›› diye sordular.'),
(2008860,68,42,20,3,'İsa onlara şu karşılığı verdi: ‹‹Ben de size bir soru soracağım. Söyleyin bana, Yahyanın vaftiz etme yetkisi Tanrıdan mıydı, insanlardan mı?››'),
(2008861,68,42,20,5,'Bunu aralarında şöyle tartıştılar: ‹‹ ‹Tanrıdan› dersek, ‹Ona niçin inanmadınız?› diyecek.'),
(2008862,68,42,20,6,'Yok eğer ‹İnsanlardan› dersek, bütün halk bizi taşa tutacak. Çünkü Yahyanın peygamber olduğuna inanmışlardır.››'),
(2008863,68,42,20,7,'Sonunda, ‹‹Nereden olduğunu bilmiyoruz›› yanıtını verdiler.'),
(2008864,68,42,20,8,'İsa da onlara, ‹‹Ben de size bunları hangi yetkiyle yaptığımı söylemeyeceğim›› dedi.'),
(2008865,68,42,20,9,'İsa sözüne devam ederek halka şu benzetmeyi anlattı: ‹‹Adamın biri bağ dikti, bunu bağcılara kiralayıp uzun süre yolculuğa çıktı.'),
(2008866,68,42,20,10,'Mevsimi gelince, bağın ürününden payına düşeni vermeleri için bağcılara bir köle yolladı. Ama bağcılar köleyi dövüp eli boş gönderdiler.'),
(2008867,68,42,20,11,'Bağ sahibi başka bir köle daha yolladı. Bağcılar onu da dövdüler, aşağılayıp eli boş gönderdiler.'),
(2008868,68,42,20,12,'Adam bir üçüncüsünü yolladı, bağcılar onu da yaralayıp kovdular.'),
(2008869,68,42,20,13,'‹‹Bağın sahibi, ‹Ne yapacağım?› dedi. ‹Sevgili oğlumu göndereyim. Belki onu sayarlar.›'),
(2008870,68,42,20,14,'‹‹Ama bağcılar onu görünce aralarında şöyle konuştular: ‹Mirasçı budur; onu öldürelim de miras bize kalsın.›'),
(2008871,68,42,20,15,'Böylece, onu bağdan dışarı atıp öldürdüler. ‹‹Bu durumda bağın sahibi onlara ne yapacak?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008872,68,42,20,16,'Gelip o bağcıları yok edecek, bağı da başkalarına verecek.›› Halk bunu duyunca, ‹‹Tanrı korusun!›› dedi.'),
(2008873,68,42,20,17,'İsa gözlerinin içine bakarak şöyle dedi: ‹‹Öyleyse Kutsal Yazılardaki şu sözün anlamı nedir? ‹Yapıcıların reddettiği taş, İşte köşenin baş taşı oldu.›'),
(2008874,68,42,20,18,'O taşın üzerine düşen herkes paramparça olacak, taş da kimin üzerine düşerse onu ezip toz edecek.››'),
(2008875,68,42,20,19,'İsanın bu benzetmeyi kendilerine karşı anlattığını farkeden din bilginleriyle başkâhinler Onu o anda yakalamak istediler, ama halkın tepkisinden korktular.'),
(2008876,68,42,20,20,'İsayı dikkatle gözlüyorlardı. Ona, kendilerine dürüst süsü veren muhbirler gönderdiler. Onu, söyleyeceği bir sözle tuzağa düşürmek ve böylelikle valinin yetki ve yargısına teslim etmek istiyorlardı.'),
(2008877,68,42,20,21,'Muhbirler Ona, ‹‹Öğretmenimiz, senin doğru olanı söyleyip öğrettiğini, insanlar arasında ayrım yapmaksızın Tanrı yolunu dürüstçe öğrettiğini biliyoruz. Sezara vergi vermemiz Kutsal Yasaya uygun mu, değil mi?›› diye sordular.'),
(2008878,68,42,20,23,'Onların hilesini anlayan İsa, ‹‹Bana bir dinar gösterin›› dedi. ‹‹Üzerindeki resim ve yazı kimin?›› ‹‹Sezarın›› dediler.'),
(2008879,68,42,20,25,'O da, ‹‹Öyleyse Sezarın hakkını Sezara, Tanrının hakkını Tanrıya verin›› dedi.'),
(2008880,68,42,20,26,'İsayı, halkın önünde söylediği sözlerle tuzağa düşüremediler. Verdiği yanıta şaşarak susup kaldılar.'),
(2008881,68,42,20,27,'Ölümden sonra dirilişi yadsıyan Sadukilerden bazıları İsaya gelip şunu sordular: ‹‹Öğretmenimiz, Musa yazılarında bize şöyle buyurmuştur: ‹Eğer bir adamın evli kardeşi çocuksuz ölürse, adam ölenin karısını alıp soyunu sürdürsün.›'),
(2008882,68,42,20,29,'Yedi kardeş vardı. Birincisi kendine bir eş aldı, ama çocuksuz öldü.'),
(2008883,68,42,20,30,'İkincisi de, üçüncüsü de kadını aldı; böylece kardeşlerin yedisi de çocuk bırakmadan öldü.'),
(2008884,68,42,20,32,'Son olarak kadın da öldü.'),
(2008885,68,42,20,33,'Buna göre, diriliş günü kadın bunlardan hangisinin karısı olacak? Çünkü yedisi de onunla evlendi.››'),
(2008886,68,42,20,34,'İsa onlara şöyle dedi: ‹‹Bu çağın insanları evlenip evlendirilirler.'),
(2008887,68,42,20,35,'Ama gelecek çağa ve ölülerin dirilişine erişmeye layık görülenler ne evlenir, ne evlendirilir.'),
(2008888,68,42,20,36,'Bir daha ölmeleri de söz konusu değildir. Çünkü meleklere benzerler ve dirilişin çocukları olarak Tanrının çocuklarıdırlar.'),
(2008889,68,42,20,37,'Musa bile alevlenen çalıyla ilgili bölümde Rab için, ‹İbrahimin Tanrısı, İshakın Tanrısı ve Yakupun Tanrısı› deyimini kullanarak ölülerin dirileceğine işaret etmişti.'),
(2008890,68,42,20,38,'Tanrı ölülerin değil, dirilerin Tanrısıdır. Çünkü Ona göre bütün insanlar yaşamaktadır.››'),
(2008891,68,42,20,39,'Artık Ona başka soru sormaya cesaret edemeyen din bilginlerinden bazıları, ‹‹Öğretmenimiz, güzel konuştun›› dediler.'),
(2008892,68,42,20,41,'İsa onlara şöyle dedi: ‹‹Nasıl oluyor da, ‹Mesih Davutun Oğludur› diyorlar?'),
(2008893,68,42,20,42,'Çünkü Davutun kendisi Mezmurlar Kitabında şöyle diyor: ‹Rab Rabbime dedi ki, Ben düşmanlarını Ayaklarının altına serinceye dek Sağımda otur.›'),
(2008894,68,42,20,44,'Davut Ondan ‹Rab› diye söz ettiğine göre, O nasıl Davutun Oğlu olur?››'),
(2008895,68,42,20,45,'Bütün halk dinlerken İsa öğrencilerine şöyle dedi: ‹‹Uzun kaftanlar içinde dolaşmaktan hoşlanan, meydanlarda selamlanmaya, havralarda en seçkin yerlere, şölenlerde başköşelere kurulmaya bayılan din bilginlerinden sakının.'),
(2008896,68,42,20,47,'Dul kadınların malını mülkünü sömüren, gösteriş için uzun uzun dua eden bu kişilerin cezası daha ağır olacaktır.››'),
(2008897,68,42,21,1,'İsa başını kaldırdı ve bağış toplanan yerde bağışlarını bırakan zenginleri gördü.'),
(2008898,68,42,21,2,'Yoksul bir dul kadının oraya iki bakır para attığını görünce, ‹‹Size gerçeği söyleyeyim›› dedi, ‹‹Bu yoksul dul kadın herkesten daha çok verdi.'),
(2008899,68,42,21,4,'Çünkü bunların hepsi kutuya, zenginliklerinden artanı attılar. Bu kadın ise yoksulluğuna karşın, geçinmek için elinde ne varsa hepsini verdi.››'),
(2008900,68,42,21,5,'Bazı kişiler tapınağın nasıl güzel taşlar ve adaklarla süslenmiş olduğundan söz edince İsa, ‹‹Burada gördüklerinize gelince, öyle günler gelecek ki, taş üstünde taş kalmayacak, hepsi yıkılacak!›› dedi.'),
(2008901,68,42,21,7,'Onlar da, ‹‹Peki, öğretmenimiz, bu dediklerin ne zaman olacak? Bunların gerçekleşmek üzere olduğunu gösteren belirti ne olacak?›› diye sordular.'),
(2008902,68,42,21,8,'İsa, ‹‹Sakın sizi saptırmasınlar›› dedi. ‹‹Birçokları, ‹Ben Oyum› ve ‹Zaman yaklaştı› diyerek benim adımla gelecekler. Onların ardından gitmeyin.'),
(2008903,68,42,21,9,'Savaş ve isyan haberleri duyunca telaşlanmayın. Önce bunların olması gerek, ama son hemen gelmeyecek.››'),
(2008904,68,42,21,10,'Sonra onlara şöyle dedi: ‹‹Ulus ulusa, devlet devlete savaş açacak.'),
(2008905,68,42,21,11,'Şiddetli depremler, yer yer kıtlıklar ve salgın hastalıklar, korkunç olaylar ve gökte olağanüstü belirtiler olacak.'),
(2008906,68,42,21,12,'‹‹Ama bütün bu olaylardan önce sizi yakalayıp zulmedecekler. Sizi havralara teslim edecek, zindanlara atacaklar. Benim adımdan ötürü kralların, valilerin önüne çıkarılacaksınız.'),
(2008907,68,42,21,13,'Bu size tanıklık etme fırsatı olacak.'),
(2008908,68,42,21,14,'Buna göre kendinizi nasıl savunacağınızı önceden düşünmemekte kararlı olun.'),
(2008909,68,42,21,15,'Çünkü ben size öyle bir konuşma yeteneği, öyle bir bilgelik vereceğim ki, size karşı çıkanların hiçbiri buna karşı direnemeyecek, bir şey diyemeyecek.'),
(2008910,68,42,21,16,'Anne babanız, kardeşleriniz, akraba ve dostlarınız bile sizi ele verecek ve bazılarınızı öldürtecekler.'),
(2008911,68,42,21,17,'Benim adımdan ötürü herkes sizden nefret edecek.'),
(2008912,68,42,21,18,'Ne var ki, başınızdaki saçlardan bir tel bile yok olmayacaktır.'),
(2008913,68,42,21,19,'Dayanmakla canlarınızı kazanacaksınız.'),
(2008914,68,42,21,20,'‹‹Yeruşalimin ordular tarafından kuşatıldığını görünce bilin ki, kentin yıkılacağı zaman yaklaşmıştır.'),
(2008915,68,42,21,21,'O zaman Yahudiyede bulunanlar dağlara kaçsın, kentte olanlar dışarı çıksın, kırdakiler kente dönmesin.'),
(2008916,68,42,21,22,'Çünkü o günler, yazılmış olanların tümünün gerçekleşeceği ceza günleridir.'),
(2008917,68,42,21,23,'O günlerde gebe olan, çocuk emziren kadınların vay haline! Çünkü ülke büyük sıkıntıya düşecek ve bu halk gazaba uğrayacaktır.'),
(2008918,68,42,21,24,'Kılıçtan geçirilecek, tutsak olarak bütün uluslar arasına sürülecekler. Yeruşalim, öteki ulusların dönemleri tamamlanıncaya dek onların ayakları altında çiğnenecektir.'),
(2008919,68,42,21,25,'‹‹Güneşte, ayda ve yıldızlarda belirtiler görülecek. Yeryüzünde uluslar denizin ve dalgaların uğultusundan şaşkına dönecek, dehşete düşecekler.'),
(2008920,68,42,21,26,'Dünyanın üzerine gelecek felaketleri bekleyen insanlar korkudan bayılacak. Çünkü göksel güçler sarsılacak.'),
(2008921,68,42,21,27,'O zaman İnsanoğlunun bulut içinde büyük güç ve görkemle geldiğini görecekler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008922,68,42,21,28,'Bu olaylar gerçekleşmeye başlayınca doğrulun ve başlarınızı kaldırın. Çünkü kurtuluşunuz yakın demektir.››'),
(2008923,68,42,21,29,'İsa onlara şu benzetmeyi anlattı: ‹‹İncir ağacına ya da herhangi bir ağaca bakın.'),
(2008924,68,42,21,30,'Bunların yapraklandığını gördüğünüz zaman yaz mevsiminin yakın olduğunu kendiliğinizden anlarsınız.'),
(2008925,68,42,21,31,'Aynı şekilde, bu olayların gerçekleştiğini gördüğünüzde bilin ki, Tanrının Egemenliği yakındır.'),
(2008926,68,42,21,32,'Size doğrusunu söyleyeyim, bütün bunlar olmadan, bu kuşak ortadan kalkmayacak.'),
(2008927,68,42,21,33,'Yer ve gök ortadan kalkacak, ama benim sözlerim asla ortadan kalkmayacaktır.'),
(2008928,68,42,21,34,'‹‹Kendinize dikkat edin! Yürekleriniz sefahat, sarhoşluk ve bu yaşamın kaygılarıyla ağırlaşmasın. O gün, üzerinize bir tuzak gibi aniden inmesin. Çünkü o gün bütün yeryüzünde yaşayan herkesin üzerine gelecektir.'),
(2008929,68,42,21,36,'Her an uyanık kalın, gerçekleşmek üzere olan bütün bu olaylardan kurtulabilmek ve İnsanoğlunun önünde durabilmek için dua edin.››'),
(2008930,68,42,21,37,'İsa gündüz tapınakta öğretiyor, geceleri ise kentten dışarı çıkıp Zeytin Dağında sabahlıyordu.'),
(2008931,68,42,21,38,'Sabah erkenden bütün halk O''nu tapınakta dinlemek için O''na akın ediyordu.'),
(2008932,68,42,22,1,'Fısıh denilen Mayasız Ekmek Bayramı yaklaşmıştı.'),
(2008933,68,42,22,2,'Başkâhinlerle din bilginleri İsayı ortadan kaldırmak için bir yol arıyor, ama halktan korkuyorlardı.'),
(2008934,68,42,22,3,'Şeytan, Onikilerden biri olup İskariot diye adlandırılan Yahudanın yüreğine girdi.'),
(2008935,68,42,22,4,'Yahuda gitti, başkâhinler ve tapınak koruyucularının komutanlarıyla İsayı nasıl ele verebileceğini görüştü.'),
(2008936,68,42,22,5,'Onlar buna sevindiler ve kendisine para vermeye razı oldular.'),
(2008937,68,42,22,6,'Bunu kabul eden Yahuda, kalabalığın olmadığı bir zamanda İsayı ele vermek için fırsat kollamaya başladı.'),
(2008938,68,42,22,7,'Fısıh kurbanının kesilmesi gereken Mayasız Ekmek Günü geldi.'),
(2008939,68,42,22,8,'İsa, Petrusla Yuhannayı, ‹‹Gidin, Fısıh yemeğini yiyebilmemiz için hazırlık yapın›› diyerek önden gönderdi.'),
(2008940,68,42,22,9,'Ona, ‹‹Nerede hazırlık yapmamızı istersin?›› diye sordular.'),
(2008941,68,42,22,10,'İsa onlara, ‹‹Bakın›› dedi, ‹‹Kente girdiğinizde karşınıza su testisi taşıyan bir adam çıkacak. Adamı, gideceği eve kadar izleyin ve evin sahibine şöyle deyin: ‹Öğretmen, öğrencilerimle birlikte Fısıh yemeğini yiyeceğim konuk odası nerede? diye soruyor.›'),
(2008942,68,42,22,12,'Ev sahibi size üst katta, döşenmiş büyük bir oda gösterecek. Orada hazırlık yapın.››'),
(2008943,68,42,22,13,'Onlar da gittiler, her şeyi İsanın kendilerine söylediği gibi buldular ve Fısıh yemeği için hazırlık yaptılar.'),
(2008944,68,42,22,14,'Yemek saati gelince İsa, elçileriyle birlikte sofraya oturdu ve onlara şöyle dedi: ‹‹Ben acı çekmeden önce bu Fısıh yemeğini sizinle birlikte yemeyi çok arzulamıştım.'),
(2008945,68,42,22,16,'Size şunu söyleyeyim, Fısıh yemeğini, Tanrının Egemenliğinde yetkinliğe erişeceği zamana dek, bir daha yemeyeceğim.››'),
(2008946,68,42,22,17,'Sonra kâseyi alarak şükretti ve, ‹‹Bunu alın, aranızda paylaşın›› dedi.'),
(2008947,68,42,22,18,'‹‹Size şunu söyleyeyim, Tanrının Egemenliği gelene dek, asmanın ürününden bir daha içmeyeceğim.››'),
(2008948,68,42,22,19,'Sonra eline ekmek aldı, şükredip ekmeği böldü ve onlara verdi. ‹‹Bu sizin uğrunuza feda edilen bedenimdir. Beni anmak için böyle yapın›› dedi.'),
(2008949,68,42,22,20,'Aynı şekilde, yemekten sonra kâseyi alıp şöyle dedi: ‹‹Bu kâse, sizin uğrunuza akıtılan kanımla gerçekleşen yeni antlaşmadır.'),
(2008950,68,42,22,21,'Ama bana ihanet edecek kişinin eli şu anda benimkiyle birlikte sofradadır.'),
(2008951,68,42,22,22,'İnsanoğlu, belirlenmiş olan yoldan gidiyor. Ama Ona ihanet eden adamın vay haline!››'),
(2008952,68,42,22,23,'Elçiler, aralarında bunu kimin yapabileceğini tartışmaya başladılar.'),
(2008953,68,42,22,24,'Ayrıca aralarında hangisinin en üstün sayılacağı konusunda bir çekişme oldu.'),
(2008954,68,42,22,25,'İsa onlara, ‹‹Ulusların kralları, kendi uluslarına egemen kesilirler. İleri gelenleri de kendilerine iyiliksever unvanını yakıştırırlar›› dedi.'),
(2008955,68,42,22,26,'‹‹Ama siz böyle olmayacaksınız. Aranızda en büyük olan, en küçük gibi olsun; yöneten, hizmet eden gibi olsun.'),
(2008956,68,42,22,27,'Hangisi daha büyük, sofrada oturan mı, hizmet eden mi? Sofrada oturan değil mi? Oysa ben aranızda hizmet eden biri gibi oldum.'),
(2008957,68,42,22,28,'Denendiğim zamanlar benimle birlikte dayanmış olanlar sizlersiniz.'),
(2008958,68,42,22,29,'Babam bana nasıl bir egemenlik verdiyse, ben de size bir egemenlik veriyorum.'),
(2008959,68,42,22,30,'Öyle ki, egemenliğimde benim soframda yiyip içesiniz ve tahtta oturarak İsrailin on iki oymağını yargılayasınız.'),
(2008960,68,42,22,31,'‹‹Simun, Simun, Şeytan sizleri buğday gibi kalburdan geçirmek için izin almıştır.'),
(2008961,68,42,22,32,'Ama ben, imanını yitirmeyesin diye senin için dua ettim. Geri döndüğün zaman kardeşlerini güçlendir.››'),
(2008962,68,42,22,33,'Simun İsaya, ‹‹Ya Rab, ben seninle birlikte zindana da, ölüme de gitmeye hazırım›› dedi.'),
(2008963,68,42,22,34,'İsa, ‹‹Sana şunu söyleyeyim, Petrus, bu gece horoz ötmeden beni tanıdığını üç kez inkâr edeceksin›› dedi.'),
(2008964,68,42,22,35,'Sonra İsa onlara, ‹‹Ben sizi kesesiz, torbasız ve çarıksız gönderdiğim zaman, herhangi bir eksiğiniz oldu mu?›› diye sordu. ‹‹Hiçbir eksiğimiz olmadı›› dediler.'),
(2008965,68,42,22,36,'O da onlara, ‹‹Şimdi ise kesesi olan da, torbası olan da yanına alsın›› dedi. ‹‹Kılıcı olmayan, abasını satıp bir kılıç alsın.'),
(2008966,68,42,22,37,'Size şunu söyleyeyim, yazılmış olan şu sözün yaşamımda yerine gelmesi gerekiyor: ‹O, suçlularla bir sayıldı.› Gerçekten de benimle ilgili yazılmış olanlar yerine gelmektedir.››'),
(2008967,68,42,22,38,'‹‹Ya Rab, işte burada iki kılıç var›› dediler. O da onlara, ‹‹Yeter!›› dedi.'),
(2008968,68,42,22,39,'İsa dışarı çıktı, her zamanki gibi Zeytin Dağına gitti. Öğrenciler de Onun ardından gittiler.'),
(2008969,68,42,22,40,'Oraya varınca İsa onlara, ‹‹Dua edin ki ayartılmayasınız›› dedi.'),
(2008970,68,42,22,41,'Onlardan bir taş atımı kadar uzaklaştı ve diz çökerek şöyle dua etti: ‹‹Baba, senin isteğine uygunsa, bu kâseyi benden uzaklaştır. Yine de benim değil, senin istediğin olsun.››'),
(2008971,68,42,22,43,'Gökten bir melek İsaya görünerek Onu güçlendirdi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2008972,68,42,22,44,'Derin bir acı içinde olan İsa daha hararetle dua etti. Teri, toprağa düşen kan damlalarını andırıyordu.'),
(2008973,68,42,22,45,'İsa duadan kalkıp öğrencilerin yanına dönünce onları üzüntüden uyumuş buldu.'),
(2008974,68,42,22,46,'Onlara, ‹‹Niçin uyuyorsunuz?›› dedi. ‹‹Kalkıp dua edin ki ayartılmayasınız.››'),
(2008975,68,42,22,47,'İsa daha konuşurken bir kalabalık çıkageldi. Onikilerden biri, Yahuda adındaki kişi, kalabalığa öncülük ediyordu. İsayı öpmek üzere yaklaşınca İsa, ‹‹Yahuda›› dedi, ‹‹İnsanoğluna bir öpücükle mi ihanet ediyorsun?››'),
(2008976,68,42,22,49,'İsanın çevresindekiler olacakları anlayınca, ‹‹Ya Rab, kılıçla vuralım mı?›› dediler.'),
(2008977,68,42,22,50,'İçlerinden biri başkâhinin kölesine vurarak sağ kulağını uçurdu.'),
(2008978,68,42,22,51,'Ama İsa, ‹‹Bırakın, yeter!›› dedi, sonra kölenin kulağına dokunarak onu iyileştirdi.'),
(2008979,68,42,22,52,'İsa, üzerine yürüyen başkâhinlere, tapınak koruyucularının komutanlarına ve ileri gelenlere şöyle dedi: ‹‹Niçin bir haydutmuşum gibi kılıç ve sopalarla geldiniz?'),
(2008980,68,42,22,53,'Her gün tapınakta sizinle birlikteydim, bana el sürmediniz. Ama bu saat sizindir, karanlığın egemen olduğu saattir.››'),
(2008981,68,42,22,54,'İsayı tutukladılar, alıp başkâhinin evine götürdüler. Petrus onları uzaktan izliyordu.'),
(2008982,68,42,22,55,'Avlunun ortasında ateş yakıp çevresinde oturduklarında Petrus da gelip onlarla birlikte oturdu.'),
(2008983,68,42,22,56,'Bir hizmetçi kız ateşin ışığında oturan Petrusu gördü. Onu dikkatle süzerek, ‹‹Bu da Onunla birlikteydi›› dedi.'),
(2008984,68,42,22,57,'Ama Petrus, ‹‹Ben Onu tanımıyorum, kadın!›› diye inkâr etti.'),
(2008985,68,42,22,58,'Biraz sonra onu gören başka biri, ‹‹Sen de onlardansın›› dedi. Petrus, ‹‹Değilim, arkadaş!›› dedi.'),
(2008986,68,42,22,59,'Yaklaşık bir saat sonra yine bir başkası ısrarla, ‹‹Gerçekten bu da Onunla birlikteydi›› dedi. ‹‹Çünkü Celilelidir.››'),
(2008987,68,42,22,60,'Petrus, ‹‹Sen ne diyorsun be adam, anlamıyorum!›› dedi. Tam o anda, Petrus daha konuşurken horoz öttü.'),
(2008988,68,42,22,61,'Rab arkasına dönüp Petrusa baktı. O zaman Petrus, Rabbin kendisine, ‹‹Bu gece horoz ötmeden beni üç kez inkâr edeceksin›› dediğini hatırladı ve dışarı çıkıp acı acı ağladı.'),
(2008989,68,42,22,63,'İsayı göz altında tutan adamlar Onunla alay ediyor, Onu dövüyorlardı.'),
(2008990,68,42,22,64,'Gözlerini bağlayıp, ‹‹Peygamberliğini göster bakalım, sana vuran kim?›› diye soruyorlardı.'),
(2008991,68,42,22,65,'Kendisine daha bir sürü küfür yağdırdılar.'),
(2008992,68,42,22,66,'Gün doğunca halkın ileri gelenleri, başkâhinler ve din bilginleri toplandılar. İsa, bunlardan oluşan Yüksek Kurulun önüne çıkarıldı.'),
(2008993,68,42,22,67,'Ona, ‹‹Sen Mesih isen, söyle bize›› dediler. İsa onlara şöyle dedi: ‹‹Size söylesem, inanmazsınız.'),
(2008994,68,42,22,68,'Size soru sorsam, yanıt vermezsiniz.'),
(2008995,68,42,22,69,'Ne var ki, bundan böyle İnsanoğlu, kudretli Tanrının sağında oturacaktır.››'),
(2008996,68,42,22,70,'Onların hepsi, ‹‹Yani, sen Tanrının Oğlu musun?›› diye sordular. O da onlara, ‹‹Söylediğiniz gibi, ben Oyum›› dedi.'),
(2008997,68,42,22,71,'‹‹Artık tanıklığa ne ihtiyacımız var?›› dediler. ‹‹İşte kendi ağzından duyduk!››'),
(2008998,68,42,23,1,'Sonra bütün kurul üyeleri kalkıp İsayı Pilatusa götürdüler.'),
(2008999,68,42,23,2,'Onu şöyle suçlamaya başladılar: ‹‹Bu adamın ulusumuzu yoldan saptırdığını gördük. Sezara vergi ödenmesine engel oluyor, kendisinin de Mesih, yani bir kral olduğunu söylüyor.››'),
(2009000,68,42,23,3,'Pilatus İsaya, ‹‹Sen Yahudilerin Kralı mısın?›› diye sordu. İsa, ‹‹Söylediğin gibidir›› yanıtını verdi.'),
(2009001,68,42,23,4,'Pilatus, başkâhinlerle halka, ‹‹Bu adamda hiçbir suç görmüyorum›› dedi.'),
(2009002,68,42,23,5,'Ama onlar üstelediler: ‹‹Yahudiyenin her tarafında öğretisini yayarak halkı kışkırtıyor; Celileden başlayıp ta buraya kadar geldi›› dediler.'),
(2009003,68,42,23,6,'Pilatus bunu duyunca, ‹‹Bu adam Celileli mi?›› diye sordu.'),
(2009004,68,42,23,7,'İsanın, Hirodesin yönetimindeki bölgeden geldiğini öğrenince, kendisini o sırada Yeruşalimde bulunan Hirodese gönderdi.'),
(2009005,68,42,23,8,'Hirodes İsayı görünce çok sevindi. Ona ilişkin haberleri duyduğu için çoktandır Onu görmek istiyor, gerçekleştireceği bir belirtiye tanık olmayı umuyordu.'),
(2009006,68,42,23,9,'Ona birçok soru sordu, ama O hiç karşılık vermedi.'),
(2009007,68,42,23,10,'Orada duran başkâhinlerle din bilginleri, İsayı ağır bir dille suçladılar.'),
(2009008,68,42,23,11,'Hirodes de askerleriyle birlikte Onu aşağılayıp alay etti. Ona gösterişli bir kaftan giydirip Pilatusa geri gönderdi.'),
(2009009,68,42,23,12,'Bu olaydan önce birbirine düşman olan Hirodesle Pilatus, o gün dost oldular.'),
(2009010,68,42,23,13,'Pilatus, başkâhinleri, yöneticileri ve halkı toplayarak onlara, ‹‹Siz bu adamı bana, halkı saptırıyor diye getirdiniz›› dedi. ‹‹Oysa ben bu adamı sizin önünüzde sorguya çektim ve kendisinde öne sürdüğünüz suçlardan hiçbirini bulmadım.'),
(2009011,68,42,23,15,'Hirodes de bulmamış olmalı ki, Onu bize geri gönderdi. Görüyorsunuz, ölüm cezasını gerektiren hiçbir şey yapmadı.'),
(2009012,68,42,23,16,'Bu nedenle ben Onu dövdürüp salıvereceğim.››'),
(2009013,68,42,23,18,'Ama onlar hep bir ağızdan, ‹‹Yok et bu adamı, bize Barabbayı salıver!›› diye bağırdılar.'),
(2009014,68,42,23,19,'Barabba, kentte çıkan bir ayaklanmaya katılmaktan ve adam öldürmekten hapse atılmıştı.'),
(2009015,68,42,23,20,'İsayı salıvermek isteyen Pilatus onlara yeniden seslendi.'),
(2009016,68,42,23,21,'Onlar ise, ‹‹Onu çarmıha ger, çarmıha ger!›› diye bağrışıp durdular.'),
(2009017,68,42,23,22,'Pilatus üçüncü kez, ‹‹Bu adam ne kötülük yaptı ki?›› dedi. ‹‹Ölüm cezasını gerektirecek hiçbir suç bulmadım Onda. Bu nedenle Onu dövdürüp salıvereceğim.››'),
(2009018,68,42,23,23,'Ne var ki onlar, yüksek sesle bağrışarak İsanın çarmıha gerilmesi için direttiler. Sonunda bağırışları baskın çıktı ve Pilatus, onların isteğinin yerine getirilmesine karar verdi.'),
(2009019,68,42,23,25,'İstedikleri kişiyi, ayaklanmaya katılmak ve adam öldürmekten hapse atılan kişiyi salıverdi. İsayı ise onların isteğine bıraktı.'),
(2009020,68,42,23,26,'Askerler İsayı götürürken, kırdan gelmekte olan Simun adında Kireneli bir adamı yakaladılar, çarmıhı sırtına yükleyip İsanın arkasından yürüttüler.'),
(2009021,68,42,23,27,'Büyük bir halk topluluğu da İsanın ardından gidiyordu. Aralarında İsa için dövünüp ağıt yakan kadınlar vardı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009022,68,42,23,28,'İsa bu kadınlara dönerek, ‹‹Ey Yeruşalim kızları, benim için ağlamayın›› dedi. ‹‹Kendiniz ve çocuklarınız için ağlayın.'),
(2009023,68,42,23,29,'Çünkü öyle günler gelecek ki, ‹Kısır kadınlara, hiç doğurmamış rahimlere, emzirmemiş memelere ne mutlu!› diyecekler.'),
(2009024,68,42,23,30,'O zaman dağlara, ‹Üzerimize düşün!› ve tepelere, ‹Bizi örtün!› diyecekler.'),
(2009025,68,42,23,31,'Çünkü yaş ağaca böyle yaparlarsa, kuruya neler olacaktır?››'),
(2009026,68,42,23,32,'İsayla birlikte idam edilmek üzere ayrıca iki suçlu da götürülüyordu.'),
(2009027,68,42,23,33,'Kafatası denilen yere vardıklarında İsayı, biri sağında öbürü solunda olmak üzere, iki suçluyla birlikte çarmıha gerdiler.'),
(2009028,68,42,23,34,'İsa, ‹‹Baba, onları bağışla›› dedi. ‹‹Çünkü ne yaptıklarını bilmiyorlar.›› Onun giysilerini aralarında paylaşmak için kura çektiler.'),
(2009029,68,42,23,35,'Halk orada durmuş, olanları seyrediyordu. Yöneticiler İsayla alay ederek, ‹‹Başkalarını kurtardı; eğer Tanrının Mesihi, Tanrının seçtiği O ise, kendini de kurtarsın›› diyorlardı.'),
(2009030,68,42,23,36,'Askerler de yaklaşıp İsayla eğlendiler. Ona ekşi şarap sunarak, ‹‹Sen Yahudilerin Kralıysan, kurtar kendini!›› dediler.'),
(2009031,68,42,23,38,'Başının üzerinde şu yafta vardı:'),
(2009032,68,42,23,39,'Çarmıha asılan suçlulardan biri, ‹‹Sen Mesih değil misin? Haydi, kendini de bizi de kurtar!›› diye küfür etti.'),
(2009033,68,42,23,40,'Ne var ki, öbür suçlu onu azarladı. ‹‹Sende Tanrı korkusu da mı yok?›› diye karşılık verdi. ‹‹Sen de aynı cezayı çekiyorsun.'),
(2009034,68,42,23,41,'Nitekim biz haklı olarak cezalandırılıyor, yaptıklarımızın karşılığını alıyoruz. Oysa bu adam hiçbir kötülük yapmadı.››'),
(2009035,68,42,23,42,'Sonra, ‹‹Ey İsa, kendi egemenliğine girdiğinde beni an›› dedi.'),
(2009036,68,42,23,43,'İsa ona, ‹‹Sana doğrusunu söyleyeyim, sen bugün benimle birlikte cennette olacaksın›› dedi.'),
(2009037,68,42,23,44,'Öğleyin on iki sularında güneş karardı, üçe kadar bütün ülkenin üzerine karanlık çöktü. Tapınaktaki perde ortasından yırtıldı.'),
(2009038,68,42,23,46,'İsa yüksek sesle, ‹‹Baba, ruhumu ellerine bırakıyorum!›› diye seslendi. Bunu söyledikten sonra son nefesini verdi.'),
(2009039,68,42,23,47,'Olanları gören yüzbaşı, ‹‹Bu adam gerçekten doğru biriydi›› diyerek Tanrıyı yüceltmeye başladı.'),
(2009040,68,42,23,48,'Olayı seyretmek için biriken halkın tümü olup bitenleri görünce göğüslerini döve döve geri döndüler.'),
(2009041,68,42,23,49,'Ama İsanın bütün tanıdıkları ve Celileden Onun ardından gelen kadınlar uzakta durmuş, olanları seyrediyorlardı.'),
(2009042,68,42,23,50,'Yüksek Kurul üyelerinden Yusuf adında iyi ve doğru bir adam vardı.'),
(2009043,68,42,23,51,'Bir Yahudi kenti olan Aramatyadan olup Tanrının Egemenliğini umutla bekleyen Yusuf, Kurulun kararını ve eylemini onaylamamıştı.'),
(2009044,68,42,23,52,'Pilatusa gidip İsanın cesedini istedi.'),
(2009045,68,42,23,53,'Cesedi çarmıhtan indirip keten beze sardı, hiç kimsenin konulmadığı, kayaya oyulmuş bir mezara yatırdı.'),
(2009046,68,42,23,54,'Hazırlık Günüydü ve Şabat Günü başlamak üzereydi.'),
(2009047,68,42,23,55,'İsayla birlikte Celileden gelen kadınlar da Yusufun ardından giderek mezarı ve İsanın cesedinin oraya nasıl konulduğunu gördüler.'),
(2009048,68,42,23,56,'Evlerine dönerek baharat ve güzel kokulu yağlar hazırladılar. Ama Şabat Günü, Tanrı''nın buyruğu uyarınca dinlendiler.'),
(2009049,68,42,24,1,'Kadınlar haftanın ilk günü, sabah çok erkenden, hazırlamış oldukları baharatı alıp mezara gittiler.'),
(2009050,68,42,24,2,'Taşı mezarın girişinden yuvarlanmış buldular.'),
(2009051,68,42,24,3,'Ama içeri girince Rab İsanın cesedini bulamadılar.'),
(2009052,68,42,24,4,'Onlar bu durum karşısında şaşırıp kalmışken, şimşek gibi parıldayan giysilere bürünmüş iki kişi yanlarında belirdi.'),
(2009053,68,42,24,5,'Korkuya kapılan kadınlar başlarını yere eğdiler. Adamlar ise onlara, ‹‹Diri olanı neden ölüler arasında arıyorsunuz?›› dediler.'),
(2009054,68,42,24,6,'‹‹O burada yok, dirildi. Daha Celiledeyken size söylediğini anımsayın.'),
(2009055,68,42,24,7,'İnsanoğlunun günahlı insanların eline verilmesi, çarmıha gerilmesi ve üçüncü gün dirilmesi gerektiğini bildirmişti.››'),
(2009056,68,42,24,8,'O zaman İsanın sözlerini anımsadılar.'),
(2009057,68,42,24,9,'Mezardan dönen kadınlar bütün bunları Onbirlere ve ötekilerin hepsine bildirdiler.'),
(2009058,68,42,24,10,'Bunları elçilere anlatanlar, Mecdelli Meryem, Yohanna, Yakupun annesi Meryem ve bunlarla birlikte bulunan öbür kadınlardı.'),
(2009059,68,42,24,11,'Ne var ki, bu sözler elçilere saçma geldi ve kadınlara inanmadılar.'),
(2009060,68,42,24,12,'Yine de, Petrus kalkıp mezara koştu. Eğilip içeri baktığında keten bezlerden başka bir şey görmedi. Olay karşısında şaşkına dönmüş bir halde oradan uzaklaştı.'),
(2009061,68,42,24,13,'Aynı gün öğrencilerden ikisi, Yeruşalimden altmış ok atımı uzaklıkta bulunan ve Emmaus denilen bir köye gitmekteydiler.'),
(2009062,68,42,24,14,'Bütün bu olup bitenleri kendi aralarında konuşuyorlardı.'),
(2009063,68,42,24,15,'Bunları konuşup tartışırlarken İsa yanlarına geldi ve onlarla birlikte yürümeye başladı.'),
(2009064,68,42,24,16,'Ama onların gözleri Onu tanıma gücünden yoksun bırakılmıştı.'),
(2009065,68,42,24,17,'İsa, ‹‹Yolda birbirinizle ne tartışıp duruyorsunuz?›› dedi. Üzgün bir halde, oldukları yerde durdular.'),
(2009066,68,42,24,18,'Bunlardan adı Kleopas olan Ona, ‹‹Yeruşalimde bulunup da bu günlerde orada olup bitenleri bilmeyen tek yabancı sen misin?›› diye karşılık verdi.'),
(2009067,68,42,24,19,'İsa onlara, ‹‹Hangi olup bitenleri?›› dedi. Ona, ‹‹Nasıralı İsayla ilgili olayları›› dediler. ‹‹O adam, Tanrının ve bütün halkın önünde gerek söz, gerek eylemde güçlü bir peygamberdi.'),
(2009068,68,42,24,20,'Başkâhinlerle yöneticilerimiz Onu, ölüm cezasına çarptırmak için valiye teslim ederek çarmıha gerdirdiler; oysa biz Onun, İsraili kurtaracak kişi olduğunu ummuştuk. Dahası var, bu olaylar olalı üç gün oldu ve aramızdan bazı kadınlar bizi şaşkına çevirdiler. Bu sabah erkenden mezara gittiklerinde, Onun cesedini bulamamışlar. Sonra geldiler, bir görümde, İsanın yaşamakta olduğunu bildiren melekler gördüklerini söylediler.'),
(2009069,68,42,24,24,'Bizimle birlikte olanlardan bazıları mezara gitmiş ve durumu, tam kadınların anlatmış olduğu gibi bulmuşlar. Ama Onu görmemişler.››'),
(2009070,68,42,24,25,'İsa onlara, ‹‹Sizi akılsızlar! Peygamberlerin bütün söylediklerine inanmakta ağır davranan kişiler!'),
(2009071,68,42,24,26,'Mesihin bu acıları çekmesi ve yüceliğine kavuşması gerekli değil miydi?›› dedi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009072,68,42,24,27,'Sonra Musanın ve bütün peygamberlerin yazılarından başlayarak, Kutsal Yazıların hepsinde kendisiyle ilgili olanları onlara açıkladı.'),
(2009073,68,42,24,28,'Gitmekte oldukları köye yaklaştıkları sırada İsa, yoluna devam edecekmiş gibi davrandı. Ama onlar, ‹‹Bizimle kal. Neredeyse akşam olacak, gün batmak üzere›› diyerek Onu zorladılar. Böylece İsa onlarla birlikte kalmak üzere içeri girdi.'),
(2009074,68,42,24,30,'Onlarla sofrada otururken İsa ekmek aldı, şükretti ve ekmeği bölüp onlara verdi.'),
(2009075,68,42,24,31,'O zaman onların gözleri açıldı ve kendisini tanıdılar. İsa ise gözlerinin önünden kayboldu.'),
(2009076,68,42,24,32,'Onlar birbirine, ‹‹Yolda kendisi bizimle konuşurken ve Kutsal Yazıları bize açıklarken yüreklerimiz nasıl da sevinçle çarpıyordu, değil mi?›› dediler.'),
(2009077,68,42,24,33,'Kalkıp hemen Yeruşalime döndüler. Onbirleri ve onlarla birlikte olanları toplanmış buldular.'),
(2009078,68,42,24,34,'Bunlar, ‹‹Rab gerçekten dirildi, Simuna görünmüş!›› diyorlardı.'),
(2009079,68,42,24,35,'Kendileri de yolda olup bitenleri ve ekmeği böldüğü zaman İsayı nasıl tanıdıklarını anlattılar.'),
(2009080,68,42,24,36,'Bunları anlatırlarken İsa gelip aralarında durdu. Onlara, ‹‹Size esenlik olsun!›› dedi.'),
(2009081,68,42,24,37,'Ürktüler, bir hayalet gördüklerini sanarak korkuya kapıldılar.'),
(2009082,68,42,24,38,'İsa onlara, ‹‹Neden telaşlanıyorsunuz? Neden kuşkular doğuyor içinizde?›› dedi.'),
(2009083,68,42,24,39,'‹‹Ellerime, ayaklarıma bakın; işte benim! Dokunun da görün. Hayaletin eti kemiği olmaz, ama görüyorsunuz, benim var.››'),
(2009084,68,42,24,40,'Bunu söyledikten sonra onlara ellerini ve ayaklarını gösterdi.'),
(2009085,68,42,24,41,'Sevinçten hâlâ inanamayan, şaşkınlık içindeki öğrencilerine, ‹‹Sizde yiyecek bir şey var mı?›› diye sordu.'),
(2009086,68,42,24,42,'Kendisine bir parça kızarmış balık verdiler.'),
(2009087,68,42,24,43,'İsa onu alıp gözlerinin önünde yedi.'),
(2009088,68,42,24,44,'Sonra onlara şöyle dedi: ‹‹Daha sizlerle birlikteyken, ‹Musanın Yasasında, peygamberlerin yazılarında ve Mezmurlarda benimle ilgili yazılmış olanların tümünün gerçekleşmesi gerektir› demiştim.››'),
(2009089,68,42,24,45,'Bundan sonra Kutsal Yazıları anlayabilmeleri için zihinlerini açtı.'),
(2009090,68,42,24,46,'Onlara dedi ki, ‹‹Şöyle yazılmıştır: Mesih acı çekecek ve üçüncü gün ölümden dirilecek; günahların bağışlanması için tövbe çağrısı da Yeruşalimden başlayarak bütün uluslara Onun adıyla duyurulacak.'),
(2009091,68,42,24,48,'Sizler bu olayların tanıklarısınız.'),
(2009092,68,42,24,49,'Ben de Babamın vaat ettiğini size göndereceğim. Ama siz, yücelerden gelecek güçle kuşanıncaya dek kentte kalın.››'),
(2009093,68,42,24,50,'İsa onları kentin dışına, Beytanyanın yakınlarına kadar götürdü. Ellerini kaldırarak onları kutsadı.'),
(2009094,68,42,24,51,'Ve onları kutsarken yanlarından ayrıldı, göğe alındı.'),
(2009095,68,42,24,52,'Öğrencileri Ona tapındılar ve büyük sevinç içinde Yeruşalime döndüler.'),
(2009096,68,42,24,53,'Sürekli tapınakta bulunuyor, Tanrı''yı övüyorlardı.'),
(2009097,68,43,1,1,'Başlangıçta Söz vardı. Söz Tanrıyla birlikteydi ve Söz Tanrıydı.'),
(2009098,68,43,1,2,'Başlangıçta O, Tanrıyla birlikteydi.'),
(2009099,68,43,1,3,'Her şey Onun aracılığıyla var oldu, var olan hiçbir şey Onsuz olmadı.'),
(2009100,68,43,1,4,'Yaşam Ondaydı ve yaşam insanların ışığıydı.'),
(2009101,68,43,1,5,'Işık karanlıkta parlar. Karanlık onu alt edemedi.'),
(2009102,68,43,1,6,'Tanrının gönderdiği Yahya adlı bir adam ortaya çıktı.'),
(2009103,68,43,1,7,'Tanıklık amacıyla, ışığa tanıklık etsin ve herkes onun aracılığıyla iman etsin diye geldi.'),
(2009104,68,43,1,8,'Kendisi ışık değildi, ama ışığa tanıklık etmeye geldi.'),
(2009105,68,43,1,9,'Dünyaya gelen, her insanı aydınlatan gerçek ışık vardı.'),
(2009106,68,43,1,10,'O, dünyadaydı, dünya Onun aracılığıyla var oldu, ama dünya Onu tanımadı.'),
(2009107,68,43,1,11,'Kendi yurduna geldi, ama kendi halkı Onu kabul etmedi.'),
(2009108,68,43,1,12,'Kendisini kabul edip adına iman edenlerin hepsine Tanrının çocukları olma hakkını verdi.'),
(2009109,68,43,1,13,'Onlar ne kandan, ne beden ne de insan isteğinden doğdular; tersine, Tanrıdan doğdular.'),
(2009110,68,43,1,14,'Söz, insan olup aramızda yaşadı. Onun yüceliğini -Babadan gelen, lütuf ve gerçekle dolu biricik Oğulun yüceliğini- gördük.'),
(2009111,68,43,1,15,'Yahya Ona tanıklık etti. Yüksek sesle şöyle dedi: ‹‹ ‹Benden sonra gelen benden üstündür. Çünkü O benden önce vardı› diye sözünü ettiğim kişi budur.››'),
(2009112,68,43,1,16,'Nitekim hepimiz Onun doluluğundan lütuf üzerine lütuf aldık.'),
(2009113,68,43,1,17,'Kutsal Yasa Musa aracılığıyla verildi, ama lütuf ve gerçek İsa Mesih aracılığıyla geldi.'),
(2009114,68,43,1,18,'Tanrıyı hiçbir zaman hiç kimse görmedi. Babanın bağrında bulunan ve Tanrı olan biricik Oğul Onu tanıttı.'),
(2009115,68,43,1,19,'Yahudi yetkililer Yahyaya, ‹‹Sen kimsin?›› diye sormak üzere Yeruşalimden kâhinlerle Levilileri gönderdikleri zaman Yahyanın tanıklığı şöyle oldu -açıkça konuştu, inkâr etmedi- ‹‹Ben Mesih değilim›› diye açıkça konuştu.'),
(2009116,68,43,1,21,'Onlar da kendisine, ‹‹Öyleyse sen kimsin? İlyas mısın?›› diye sordular. O da, ‹‹Değilim›› dedi. ‹‹Sen beklediğimiz peygamber misin?›› sorusuna, ‹‹Hayır›› yanıtını verdi.'),
(2009117,68,43,1,22,'Bu kez, ‹‹Kim olduğunu söyle de bizi gönderenlere bir yanıt verelim›› dediler. ‹‹Kendin için ne diyorsun?››'),
(2009118,68,43,1,23,'Yahya, ‹‹Peygamber Yeşayanın dediği gibi, ‹Rabbin yolunu düzleyin› diye çölde haykıranın sesiyim ben›› dedi.'),
(2009119,68,43,1,24,'Yahyaya gönderilen bazı Ferisiler ona, ‹‹Sen Mesih, İlyas ya da beklediğimiz peygamber değilsen, niye vaftiz ediyorsun?›› diye sordular.'),
(2009120,68,43,1,26,'Yahya onlara şöyle yanıt verdi: ‹‹Ben suyla vaftiz ediyorum, ama aranızda tanımadığınız biri duruyor.'),
(2009121,68,43,1,27,'Benden sonra gelen Odur. Ben Onun çarığının bağını çözmeye bile layık değilim.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009122,68,43,1,28,'Bütün bunlar Şeria Irmağının ötesinde bulunan Beytanyada, Yahyanın vaftiz ettiği yerde oldu.'),
(2009123,68,43,1,29,'Yahya ertesi gün İsanın kendisine doğru geldiğini görünce şöyle dedi: ‹‹İşte, dünyanın günahını ortadan kaldıran Tanrı Kuzusu!'),
(2009124,68,43,1,30,'Kendisi için, ‹Benden sonra biri geliyor, O benden üstündür. Çünkü O benden önce vardı› dediğim kişi işte budur.'),
(2009125,68,43,1,31,'Ben Onu tanımıyordum, ama İsrailin Onu tanıması için ben suyla vaftiz ederek geldim.››'),
(2009126,68,43,1,32,'Yahya tanıklığını şöyle sürdürdü: ‹‹Ruhun güvercin gibi gökten indiğini, Onun üzerinde durduğunu gördüm.'),
(2009127,68,43,1,33,'Ben Onu tanımıyordum. Ama suyla vaftiz etmek için beni gönderen, ‹Ruhun kimin üzerine inip durduğunu görürsen, Kutsal Ruhla vaftiz eden Odur› dedi.'),
(2009128,68,43,1,34,'Ben de gördüm ve ‹Tanrının Oğlu budur› diye tanıklık ettim.››'),
(2009129,68,43,1,35,'Ertesi gün Yahya yine öğrencilerinden ikisiyle birlikteydi.'),
(2009130,68,43,1,36,'Oradan geçen İsaya bakarak, ‹‹İşte Tanrı Kuzusu!›› dedi.'),
(2009131,68,43,1,37,'Onun söylediklerini duyan iki öğrenci İsanın ardından gitti.'),
(2009132,68,43,1,38,'İsa arkasına dönüp ardından geldiklerini görünce, ‹‹Ne arıyorsunuz?›› diye sordu. Onlar da, ‹‹Rabbî, nerede oturuyorsun?›› dediler. Rabbî, öğretmenim anlamına gelir.'),
(2009133,68,43,1,39,'İsa, ‹‹Gelin, görün›› dedi. Gidip Onun nerede oturduğunu gördüler ve o gün Onunla kaldılar. Saat dört sularıydı.'),
(2009134,68,43,1,40,'Yahyayı işitip İsanın ardından giden iki kişiden biri Simun Petrusun kardeşi Andreastı.'),
(2009135,68,43,1,41,'Andreas önce kendi kardeşi Simunu bularak ona, ‹‹Biz Mesihi bulduk›› dedi. Mesih, meshedilmiş anlamına gelir.'),
(2009136,68,43,1,42,'Andreas kardeşini İsaya götürdü. İsa ona baktı, ‹‹Sen Yuhannanın oğlu Simunsun. Kefas diye çağrılacaksın›› dedi. Kefas, kaya anlamına gelir.'),
(2009137,68,43,1,43,'Ertesi gün İsa, Celileye gitmeye karar verdi. Filipusu bulup ona, ‹‹Ardımdan gel›› dedi.'),
(2009138,68,43,1,44,'Filipus da Andreas ile Petrusun kenti olan Beytsaydadandı.'),
(2009139,68,43,1,45,'Filipus, Nataneli bularak ona, ‹‹Musanın Kutsal Yasada hakkında yazdığı, peygamberlerin de sözünü ettiği kişiyi, Yusuf oğlu Nasıralı İsayı bulduk›› dedi.'),
(2009140,68,43,1,46,'Natanel Filipusa, ‹‹Nasıradan iyi bir şey çıkabilir mi?›› diye sordu. Filipus, ‹‹Gel de gör›› dedi.'),
(2009141,68,43,1,47,'İsa, Natanelin kendisine doğru geldiğini görünce onun için, ‹‹İşte, içinde hile olmayan gerçek bir İsrailli!›› dedi.'),
(2009142,68,43,1,48,'Natanel, ‹‹Beni nereden tanıyorsun?›› diye sordu. İsa, ‹‹Filipus çağırmadan önce seni incir ağacının altında gördüm›› yanıtını verdi.'),
(2009143,68,43,1,49,'Natanel, ‹‹Rabbî, sen Tanrının Oğlusun, sen İsrailin Kralısın!›› dedi.'),
(2009144,68,43,1,50,'İsa ona dedi ki, ‹‹Seni incir ağacının altında gördüğümü söylediğim için mi inanıyorsun? Bunlardan daha büyük şeyler göreceksin.››'),
(2009145,68,43,1,51,'Sonra da, ‹‹Size doğrusunu söyleyeyim, göğün açıldığını, Tanrı meleklerinin İnsanoğlu üzerinde yükselip indiklerini göreceksiniz›› dedi.'),
(2009146,68,43,2,1,'Üçüncü gün Celilenin Kana Köyünde bir düğün vardı. İsanın annesi de oradaydı.'),
(2009147,68,43,2,2,'İsayla öğrencileri de düğüne çağrılmışlardı.'),
(2009148,68,43,2,3,'Şarap tükenince annesi İsaya, ‹‹Şarapları kalmadı›› dedi.'),
(2009149,68,43,2,4,'İsa, ‹‹Anne, benden ne istiyorsun? Benim saatim daha gelmedi›› dedi.'),
(2009150,68,43,2,5,'Annesi hizmet edenlere, ‹‹Size ne derse onu yapın›› dedi.'),
(2009151,68,43,2,6,'Yahudilerin geleneksel temizliği için oraya konmuş, her biri seksenle yüz yirmi litre alan altı taş küp vardı.'),
(2009152,68,43,2,7,'İsa hizmet edenlere, ‹‹Küpleri suyla doldurun›› dedi. Küpleri ağızlarına kadar doldurdular.'),
(2009153,68,43,2,8,'Sonra hizmet edenlere, ‹‹Şimdi biraz alıp şölen başkanına götürün›› dedi. Onlar da götürdüler.'),
(2009154,68,43,2,9,'Şölen başkanı, şaraba dönüşmüş suyu tattı. Bunun nereden geldiğini bilmiyordu, oysa suyu küpten alan hizmetkârlar biliyorlardı. Şölen başkanı güveyi çağırıp, ‹‹Herkes önce iyi şarabı, çok içildikten sonra da kötüsünü sunar›› dedi, ‹‹Ama sen iyi şarabı şimdiye dek saklamışsın.››'),
(2009155,68,43,2,11,'İsa bu ilk doğaüstü belirtisini Celilenin Kana Köyünde gerçekleştirdi ve yüceliğini gösterdi. Öğrencileri de Ona iman ettiler.'),
(2009156,68,43,2,12,'Bundan sonra İsa, annesi, kardeşleri ve öğrencileri Kefarnahuma gidip orada birkaç gün kaldılar.'),
(2009157,68,43,2,13,'Yahudilerin Fısıh Bayramı yakındı. İsa da Yeruşalime gitti.'),
(2009158,68,43,2,14,'Tapınağın avlusunda sığır, koyun ve güvercin satanları, orada oturmuş para bozanları gördü.'),
(2009159,68,43,2,15,'İpten bir kamçı yaparak hepsini koyunlar ve sığırlarla birlikte tapınaktan kovdu, para bozanların paralarını döküp masalarını devirdi.'),
(2009160,68,43,2,16,'Güvercin satanlara, ‹‹Bunları buradan kaldırın, Babamın evini pazar yerine çevirmeyin!›› dedi.'),
(2009161,68,43,2,17,'Öğrencileri, ‹‹Evin için gösterdiğim gayret beni yiyip bitirecek›› diye yazılmış olan sözü hatırladılar.'),
(2009162,68,43,2,18,'Yahudi yetkililer İsaya, ‹‹Bunları yaptığına göre, bize nasıl bir belirti göstereceksin?›› diye sordular.'),
(2009163,68,43,2,19,'İsa şu yanıtı verdi: ‹‹Bu tapınağı yıkın, üç günde onu yeniden kuracağım.››'),
(2009164,68,43,2,20,'Yahudi yetkililer, ‹‹Bu tapınak kırk altı yılda yapıldı, sen onu üç günde mi kuracaksın?›› dediler.'),
(2009165,68,43,2,21,'Ama İsanın sözünü ettiği tapınak kendi bedeniydi.'),
(2009166,68,43,2,22,'İsa ölümden dirilince öğrencileri bu sözü söylediğini hatırladılar, Kutsal Yazıya ve İsanın söylediği bu söze iman ettiler.'),
(2009167,68,43,2,23,'Fısıh Bayramında İsanın Yeruşalimde bulunduğu sırada gerçekleştirdiği belirtileri gören birçokları Onun adına iman ettiler.'),
(2009168,68,43,2,24,'Ama İsa bütün insanların yüreğini bildiği için onlara güvenmiyordu.'),
(2009169,68,43,2,25,'İnsan hakkında kimsenin O''na bir şey söylemesine gerek yoktu. Çünkü kendisi insanın içinden geçenleri biliyordu.'),
(2009170,68,43,3,1,'Yahudilerin Nikodim adlı bir önderi vardı. Ferisilerden olan bu adam bir gece İsaya gelerek, ‹‹Rabbî, senin Tanrıdan gelmiş bir öğretmen olduğunu biliyoruz. Çünkü Tanrı kendisiyle olmadıkça kimse senin yaptığın bu mucizeleri yapamaz›› dedi.'),
(2009171,68,43,3,3,'İsa ona şu karşılığı verdi: ‹‹Sana doğrusunu söyleyeyim, bir kimse yeniden doğmadıkça Tanrının Egemenliğini göremez.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009172,68,43,3,4,'Nikodim, ‹‹Yaşlanmış bir adam nasıl doğabilir? Annesinin rahmine ikinci kez girip doğabilir mi?›› diye sordu.'),
(2009173,68,43,3,5,'İsa şöyle yanıt verdi: ‹‹Sana doğrusunu söyleyeyim, bir kimse sudan ve Ruhtan doğmadıkça Tanrının Egemenliğine giremez.'),
(2009174,68,43,3,6,'Bedenden doğan bedendir, Ruhtan doğan ruhtur.'),
(2009175,68,43,3,7,'Sana, ‹Yeniden doğmalısınız› dediğime şaşma.'),
(2009176,68,43,3,8,'Yel dilediği yerde eser; sesini işitirsin, ama nereden gelip nereye gittiğini bilemezsin. Ruhtan doğan herkes böyledir.››'),
(2009177,68,43,3,9,'Nikodim İsaya, ‹‹Bunlar nasıl olabilir?›› diye sordu.'),
(2009178,68,43,3,10,'İsa ona şöyle yanıt verdi: ‹‹Sen İsrailin öğretmeni olduğun halde bunları anlamıyor musun?'),
(2009179,68,43,3,11,'Sana doğrusunu söyleyeyim, biz bildiğimizi söylüyoruz, gördüğümüze tanıklık ediyoruz. Sizler ise bizim tanıklığımızı kabul etmiyorsunuz.'),
(2009180,68,43,3,12,'Sizlere yeryüzüyle ilgili şeyleri söylediğim zaman inanmazsanız, gökle ilgili şeyleri söylediğimde nasıl inanacaksınız?'),
(2009181,68,43,3,13,'Gökten inmiş olan İnsanoğlundan başka hiç kimse göğe çıkmamıştır.'),
(2009182,68,43,3,14,'Musa çölde yılanı nasıl yukarı kaldırdıysa, İnsanoğlunun da öylece yukarı kaldırılması gerekir.'),
(2009183,68,43,3,15,'Öyle ki, Ona iman eden herkes sonsuz yaşama kavuşsun.'),
(2009184,68,43,3,16,'‹‹Çünkü Tanrı dünyayı o kadar çok sevdi ki, biricik Oğlunu verdi. Öyle ki, Ona iman edenlerin hiçbiri mahvolmasın, hepsi sonsuz yaşama kavuşsun.'),
(2009185,68,43,3,17,'Tanrı, Oğlunu dünyayı yargılamak için göndermedi, dünya Onun aracılığıyla kurtulsun diye gönderdi.'),
(2009186,68,43,3,18,'Ona iman eden yargılanmaz, iman etmeyen ise zaten yargılanmıştır. Çünkü Tanrının biricik Oğlunun adına iman etmemiştir.'),
(2009187,68,43,3,19,'Yargı da şudur: Dünyaya ışık geldi, ama insanlar ışık yerine karanlığı sevdiler. Çünkü yaptıkları işler kötüydü.'),
(2009188,68,43,3,20,'Kötülük yapan herkes ışıktan nefret eder ve yaptıkları açığa çıkmasın diye ışığa yaklaşmaz.'),
(2009189,68,43,3,21,'Ama gerçeği uygulayan kişi yaptıklarını, Tanrıya dayanarak yaptığını göstermek için ışığa gelir.››'),
(2009190,68,43,3,22,'Bundan sonra İsayla öğrencileri Yahudiye diyarına gittiler. İsa onlarla birlikte orada bir süre kalarak vaftiz etti.'),
(2009191,68,43,3,23,'Yahya da Salim yakınındaki Aynonda vaftiz ediyordu. Çünkü orada bol su vardı. İnsanlar gelip vaftiz oluyorlardı.'),
(2009192,68,43,3,24,'Yahya henüz hapse atılmamıştı.'),
(2009193,68,43,3,25,'O sıralarda Yahyanın öğrencileriyle bir Yahudi arasında temizlenme konusunda bir tartışma çıktı.'),
(2009194,68,43,3,26,'Öğrencileri Yahyaya gelerek, ‹‹Rabbî›› dediler, ‹‹Şeria Irmağının karşı yakasında birlikte olduğun ve kendisi için tanıklık ettiğin adam var ya, işte O vaftiz ediyor, herkes de Ona gidiyor.››'),
(2009195,68,43,3,27,'Yahya şöyle yanıt verdi: ‹‹İnsan, kendisine gökten verilmedikçe hiçbir şey alamaz.'),
(2009196,68,43,3,28,'‹Ben Mesih değilim, ama Onun öncüsü olarak gönderildim› dediğime siz kendiniz tanıksınız.'),
(2009197,68,43,3,29,'Gelin kiminse, güvey odur. Ama güveyin yanında duran ve onu dinleyen dostu onun sesini işitince çok sevinir. İşte benim sevincim böylece tamamlandı.'),
(2009198,68,43,3,30,'O büyümeli, bense küçülmeliyim.››'),
(2009199,68,43,3,31,'Yukarıdan gelen, herkesten üstündür. Dünyadan olan dünyaya aittir ve dünyadan söz eder. Gökten gelen ise, herkesten üstündür.'),
(2009200,68,43,3,32,'Ne görmüş ne işitmişse ona tanıklık eder, ama tanıklığını kimse kabul etmez.'),
(2009201,68,43,3,33,'Onun tanıklığını kabul eden, Tanrının gerçek olduğuna mührünü basmıştır.'),
(2009202,68,43,3,34,'Tanrının gönderdiği kişi Tanrının sözlerini söyler. Çünkü Tanrı, Ruhu ölçüyle vermez.'),
(2009203,68,43,3,35,'Baba Oğulu sever; her şeyi Ona teslim etmiştir.'),
(2009204,68,43,3,36,'Oğul''a iman edenin sonsuz yaşamı vardır. Ama Oğul''un sözünü dinlemeyen yaşamı görmeyecektir. Tanrı''nın gazabı böylesinin üzerinde kalır.'),
(2009205,68,43,4,1,'Ferisiler, İsanın Yahyadan daha çok öğrenci edinip vaftiz ettiğini duydular -aslında İsanın kendisi değil, öğrencileri vaftiz ediyorlardı- İsa bunu öğrenince Yahudiyeden ayrılıp yine Celileye gitti.'),
(2009206,68,43,4,4,'Giderken Samiriyeden geçmesi gerekiyordu.'),
(2009207,68,43,4,5,'Böylece Samiriyenin Sihar denilen kentine geldi. Burası Yakupun kendi oğlu Yusufa vermiş olduğu toprağın yakınındaydı.'),
(2009208,68,43,4,6,'Yakupun kuyusu da oradaydı. İsa, yolculuktan yorulmuş olduğu için kuyunun yanına oturmuştu. Saat on iki sularıydı.'),
(2009209,68,43,4,7,'Samiriyeli bir kadın su çekmeye geldi. İsa ona, ‹‹Bana su ver, içeyim›› dedi.'),
(2009210,68,43,4,8,'İsanın öğrencileri yiyecek satın almak için kente gitmişlerdi.'),
(2009211,68,43,4,9,'Samiriyeli kadın, ‹‹Sen Yahudisin, bense Samiriyeli bir kadınım›› dedi, ‹‹Nasıl olur da benden su istersin?›› Çünkü Yahudilerin Samiriyelilerle ilişkileri yoktur.'),
(2009212,68,43,4,10,'İsa kadına şu yanıtı verdi: ‹‹Eğer sen Tanrının armağanını ve sana, ‹Bana su ver, içeyim› diyenin kim olduğunu bilseydin, sen Ondan dilerdin, O da sana yaşam suyunu verirdi.››'),
(2009213,68,43,4,11,'Kadın, ‹‹Efendim›› dedi, ‹‹Su çekecek bir şeyin yok, kuyu da derin, yaşam suyunu nereden bulacaksın?'),
(2009214,68,43,4,12,'Sen, bu kuyuyu bize vermiş, kendisi, oğulları ve davarları ondan içmiş olan atamız Yakuptan daha mı büyüksün?››'),
(2009215,68,43,4,13,'İsa şöyle yanıt verdi: ‹‹Bu sudan her içen yine susayacak.'),
(2009216,68,43,4,14,'Oysa benim vereceğim sudan içen sonsuza dek susamaz. Benim vereceğim su, içende sonsuz yaşam için fışkıran bir pınar olacak.››'),
(2009217,68,43,4,15,'Kadın, ‹‹Efendim›› dedi, ‹‹Bu suyu bana ver. Böylece ne susayayım, ne de su çekmek için buraya kadar geleyim.››'),
(2009218,68,43,4,16,'İsa, ‹‹Git, kocanı çağır ve buraya gel›› dedi.'),
(2009219,68,43,4,17,'Kadın, ‹‹Kocam yok›› diye yanıtladı. İsa, ‹‹Kocam yok demekle doğruyu söyledin›› dedi.'),
(2009220,68,43,4,18,'‹‹Beş kocaya vardın. Şimdi birlikte yaşadığın adam kocan değil. Doğruyu söyledin.››'),
(2009221,68,43,4,19,'Kadın, ‹‹Efendim, anlıyorum, sen bir peygambersin›› dedi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009222,68,43,4,20,'‹‹Atalarımız bu dağda tapındılar, ama sizler tapılması gereken yerin Yeruşalimde olduğunu söylüyorsunuz.››'),
(2009223,68,43,4,21,'İsa ona şöyle dedi: ‹‹Kadın, bana inan, öyle bir saat geliyor ki, Babaya ne bu dağda, ne de Yeruşalimde tapınacaksınız!'),
(2009224,68,43,4,22,'Siz bilmediğinize tapıyorsunuz, biz bildiğimize tapıyoruz. Çünkü kurtuluş Yahudilerdendir.'),
(2009225,68,43,4,23,'Ama içtenlikle tapınanların Babaya ruhta ve gerçekte tapınacakları saat geliyor. İşte, o saat şimdidir. Baba da kendisine böyle tapınanları arıyor.'),
(2009226,68,43,4,24,'Tanrı ruhtur, Ona tapınanlar da ruhta ve gerçekte tapınmalıdırlar.››'),
(2009227,68,43,4,25,'Kadın İsaya, ‹‹Mesih denilen meshedilmiş Olanın geleceğini biliyorum›› dedi, ‹‹O gelince bize her şeyi bildirecek.››'),
(2009228,68,43,4,26,'İsa, ‹‹Seninle konuşan ben, Oyum›› dedi.'),
(2009229,68,43,4,27,'Bu sırada İsanın öğrencileri geldiler. Onun bir kadınla konuşmasına şaştılar. Bununla birlikte hiçbiri, ‹‹Ne istiyorsun?›› ya da, ‹‹O kadınla neden konuşuyorsun?›› demedi.'),
(2009230,68,43,4,28,'Sonra kadın su testisini bırakarak kente gitti ve halka şöyle dedi: ‹‹Gelin, yaptığım her şeyi bana söyleyen adamı görün. Acaba Mesih bu mudur?››'),
(2009231,68,43,4,30,'Halk da kentten çıkıp İsaya doğru gelmeye başladı.'),
(2009232,68,43,4,31,'Bu arada öğrencileri Ona, ‹‹Rabbî, yemek ye!›› diye rica ediyorlardı.'),
(2009233,68,43,4,32,'Ama İsa, ‹‹Benim, sizin bilmediğiniz bir yiyeceğim var›› dedi.'),
(2009234,68,43,4,33,'Öğrenciler birbirlerine, ‹‹Acaba biri Ona yiyecek mi getirdi?›› diye sordular.'),
(2009235,68,43,4,34,'İsa, ‹‹Benim yemeğim, beni gönderenin isteğini yerine getirmek ve Onun işini tamamlamaktır›› dedi.'),
(2009236,68,43,4,35,'‹‹Sizler, ‹Ekinleri biçmeye daha dört ay var› demiyor musunuz? İşte, size söylüyorum, başınızı kaldırıp tarlalara bakın. Ekinler sararmış, biçilmeye hazır!'),
(2009237,68,43,4,36,'Eken ve biçen birlikte sevinsinler diye, biçen kişi şimdiden ücretini alır ve sonsuz yaşam için ürün toplar.'),
(2009238,68,43,4,37,'‹Biri eker, başkası biçer› sözü bu durumda doğrudur.'),
(2009239,68,43,4,38,'Ben sizi, emek vermediğiniz bir ürünü biçmeye gönderdim. Başkaları emek verdiler, siz ise onların emeğinden yararlandınız.››'),
(2009240,68,43,4,39,'O kentten birçok Samiriyeli, ‹‹Yaptığım her şeyi bana söyledi›› diye tanıklık eden kadının sözü üzerine İsaya iman etti.'),
(2009241,68,43,4,40,'Samiriyeliler Ona gelip yanlarında kalması için rica ettiler. O da orada iki gün kaldı.'),
(2009242,68,43,4,41,'Onun sözü üzerine daha birçokları iman etti.'),
(2009243,68,43,4,42,'Bunlar kadına, ‹‹Bizim iman etmemizin nedeni artık senin sözlerin değil›› diyorlardı. ‹‹Kendimiz işittik, Onun gerçekten dünyanın Kurtarıcısı olduğunu biliyoruz.››'),
(2009244,68,43,4,43,'Bu iki günden sonra İsa oradan ayrılıp Celileye gitti.'),
(2009245,68,43,4,44,'İsanın kendisi, bir peygamberin kendi memleketinde saygı görmediğine tanıklık etmişti.'),
(2009246,68,43,4,45,'Celileye geldiği zaman Celileliler Onu iyi karşıladılar. Çünkü onlar da bayram için gitmişler ve bayramda Onun Yeruşalimde yaptığı her şeyi görmüşlerdi.'),
(2009247,68,43,4,46,'İsa yine, suyu şaraba çevirdiği Celilenin Kana Köyüne geldi. Orada saraya bağlı bir memur vardı. Oğlu Kefarnahumda hastaydı.'),
(2009248,68,43,4,47,'Adam, İsanın Yahudiyeden Celileye geldiğini işitince yanına gitti, evine gelip ölmek üzere olan oğlunu iyileştirmesi için Ona yalvardı.'),
(2009249,68,43,4,48,'İsa adama, ‹‹Sizler belirtiler ve harikalar görmedikçe iman etmeyeceksiniz›› dedi.'),
(2009250,68,43,4,49,'Saray memuru İsaya, ‹‹Efendim, çocuğum ölmeden yetiş!›› dedi.'),
(2009251,68,43,4,50,'İsa, ‹‹Git, oğlun yaşayacak›› dedi. Adam, İsanın söylediği söze iman ederek gitti.'),
(2009252,68,43,4,51,'Daha yoldayken köleleri onu karşılayıp oğlunun yaşadığını bildirdiler.'),
(2009253,68,43,4,52,'Adam onlara, oğlunun iyileşmeye başladığı saati sordu. ‹‹Dün öğle üstü saat birde ateşi düştü›› dediler.'),
(2009254,68,43,4,53,'Baba bunun, İsanın, ‹‹Oğlun yaşayacak›› dediği saat olduğunu anladı. Kendisi ve bütün ev halkı iman etti.'),
(2009255,68,43,4,54,'İsa, bu ikinci belirtiyi de Yahudiye''den Celile''ye döndükten sonra gerçekleştirdi.'),
(2009256,68,43,5,1,'İsa bundan sonra Yahudilerin bir bayramı nedeniyle Yeruşalime gitti.'),
(2009257,68,43,5,2,'Yeruşalimde Koyun Kapısı yanında, İbranicede Beytesta denilen beş eyvanlı bir havuz vardır.'),
(2009258,68,43,5,3,'Bu eyvanların altında kör, kötürüm, felçli hastalardan bir kalabalık yatardı.'),
(2009259,68,43,5,5,'Orada otuz sekiz yıldır hasta olan bir adam vardı.'),
(2009260,68,43,5,6,'İsa hasta yatan bu adamı görünce ve uzun zamandır bu durumda olduğunu anlayınca, ‹‹İyi olmak ister misin?›› diye sordu.'),
(2009261,68,43,5,7,'Hasta şöyle yanıt verdi: ‹‹Efendim, su çalkandığı zaman beni havuza indirecek kimsem yok, tam gireceğim an benden önce başkası giriyor.››'),
(2009262,68,43,5,8,'İsa ona, ‹‹Kalk, şilteni topla ve yürü›› dedi.'),
(2009263,68,43,5,9,'Adam o anda iyileşti. Şiltesini toplayıp yürümeye başladı. O gün Şabat Günüydü.'),
(2009264,68,43,5,10,'Bu yüzden Yahudi yetkililer iyileşen adama, ‹‹Bugün Şabat Günü›› dediler, ‹‹Şilteni toplaman yasaktır.››'),
(2009265,68,43,5,11,'Ama adam onlara şöyle yanıt verdi: ‹‹Beni iyileştiren kişi bana, ‹Şilteni topla ve yürü› dedi.››'),
(2009266,68,43,5,12,'‹‹Sana, ‹Şilteni topla ve yürü› diyen adam kim?›› diye sordular.'),
(2009267,68,43,5,13,'İyileşen adam ise Onun kim olduğunu bilmiyordu. Orası kalabalıktı, İsa da çekilip gitmişti.'),
(2009268,68,43,5,14,'İsa daha sonra adamı tapınakta buldu. ‹‹Bak, iyi oldun. Artık günah işleme de başına daha kötü bir şey gelmesin›› dedi.'),
(2009269,68,43,5,15,'Adam gidip Yahudi yetkililere kendisini iyileştirenin İsa olduğunu bildirdi.'),
(2009270,68,43,5,16,'Şabat Günü böyle şeyler yaptığı için İsaya zulmetmeye başladılar.'),
(2009271,68,43,5,17,'Ama İsa onlara şu karşılığı verdi: ‹‹Babam hâlâ çalışmaktadır, ben de çalışıyorum.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009272,68,43,5,18,'İşte bu nedenle Yahudi yetkililer Onu öldürmek için daha çok gayret ettiler. Çünkü yalnız Şabat Günü düzenini bozmakla kalmamış, Tanrının kendi Babası olduğunu söyleyerek kendisini Tanrıya eşit kılmıştı.'),
(2009273,68,43,5,19,'İsa Yahudi yetkililere şöyle karşılık verdi: ‹‹Size doğrusunu söyleyeyim, Oğul, Babanın yaptıklarını görmedikçe kendiliğinden bir şey yapamaz. Baba ne yaparsa Oğul da aynı şeyi yapar.'),
(2009274,68,43,5,20,'Çünkü Baba Oğulu sever ve yaptıklarının hepsini Ona gösterir. Şaşasınız diye Ona bunlardan daha büyük işler de gösterecektir.'),
(2009275,68,43,5,21,'Baba nasıl ölüleri diriltip onlara yaşam veriyorsa, Oğul da dilediği kimselere yaşam verir.'),
(2009276,68,43,5,22,'Baba kimseyi yargılamaz, bütün yargılama işini Oğula vermiştir.'),
(2009277,68,43,5,23,'Öyle ki, herkes Babayı onurlandırdığı gibi Oğulu onurlandırsın. Oğulu onurlandırmayan, Onu gönderen Babayı da onurlandırmaz.'),
(2009278,68,43,5,24,'‹‹Size doğrusunu söyleyeyim, sözümü işitip beni gönderene iman edenin sonsuz yaşamı vardır. Böyle biri yargılanmaz, ölümden yaşama geçmiştir.'),
(2009279,68,43,5,25,'Size doğrusunu söyleyeyim, ölülerin Tanrı Oğlunun sesini işitecekleri ve işitenlerin yaşayacakları saat geliyor, geldi bile.'),
(2009280,68,43,5,26,'Çünkü Baba, kendisinde yaşam olduğu gibi, Oğula da kendisinde yaşam olma özelliğini verdi.'),
(2009281,68,43,5,27,'Ona yargılama yetkisini de verdi. Çünkü O İnsanoğludur.'),
(2009282,68,43,5,28,'Buna şaşmayın. Mezarda olanların hepsinin Onun sesini işitecekleri saat geliyor.'),
(2009283,68,43,5,29,'Ve onlar mezarlarından çıkacaklar. İyilik yapmış olanlar yaşamak, kötülük yapmış olanlar yargılanmak üzere dirilecekler.››'),
(2009284,68,43,5,30,'‹‹Ben kendiliğimden hiçbir şey yapamam. İşittiğim gibi yargılarım ve benim yargım adildir. Çünkü amacım kendi istediğimi değil, beni gönderenin istediğini yapmaktır.'),
(2009285,68,43,5,31,'Eğer kendim için ben tanıklık edersem, tanıklığım geçerli olmaz.'),
(2009286,68,43,5,32,'Ama benim için tanıklık eden başka biri vardır. Onun benim için ettiği tanıklığın geçerli olduğunu bilirim.'),
(2009287,68,43,5,33,'Siz Yahyaya adamlar gönderdiniz, o da gerçeğe tanıklık etti.'),
(2009288,68,43,5,34,'İnsanın tanıklığını kabul ettiğim için değil, kurtulmanız için bunları söylüyorum.'),
(2009289,68,43,5,35,'Yahya, yanan ve ışık saçan bir çıraydı. Sizler onun ışığında bir süre için coşmak istediniz.'),
(2009290,68,43,5,36,'Ama benim, Yahyanınkinden daha büyük bir tanıklığım var. Tamamlamam için Babanın bana verdiği işler, şu yaptığım işler, beni Babanın gönderdiğine tanıklık ediyor.'),
(2009291,68,43,5,37,'Beni gönderen Baba da benim için tanıklık etmiştir. Siz hiçbir zaman ne Onun sesini işittiniz, ne de şeklini gördünüz.'),
(2009292,68,43,5,38,'Onun sözü sizde yaşamıyor. Çünkü Onun gönderdiği kişiye iman etmiyorsunuz.'),
(2009293,68,43,5,39,'Kutsal Yazıları araştırıyorsunuz. Çünkü bunlar aracılığıyla sonsuz yaşama sahip olduğunuzu sanıyorsunuz. Bana tanıklık eden de bu yazılardır!'),
(2009294,68,43,5,40,'Öyleyken siz, yaşama kavuşmak için bana gelmek istemiyorsunuz.'),
(2009295,68,43,5,41,'‹‹İnsanlardan övgü kabul etmiyorum.'),
(2009296,68,43,5,42,'Ama ben sizi bilirim, içinizde Tanrı sevgisi yoktur.'),
(2009297,68,43,5,43,'Ben Babamın adına geldim, ama beni kabul etmiyorsunuz. Oysa başka birisi kendi adına gelirse, onu kabul edeceksiniz.'),
(2009298,68,43,5,44,'Birbirinizden övgüler kabul ediyor, ama tek olan Tanrının övgüsünü kazanmaya çalışmıyorsunuz. Bu durumda nasıl iman edebilirsiniz?'),
(2009299,68,43,5,45,'Babanın önünde sizi suçlayacağımı sanmayın. Sizi suçlayan, umut bağladığınız Musadır.'),
(2009300,68,43,5,46,'Musaya iman etmiş olsaydınız, bana da iman ederdiniz. Çünkü o benim hakkımda yazmıştır.'),
(2009301,68,43,5,47,'Ama onun yazılarına iman etmezseniz, benim sözlerime nasıl iman edeceksiniz?››'),
(2009302,68,43,6,1,'Bundan sonra İsa, Celile -Taberiye- Gölünün karşı yakasına geçti.'),
(2009303,68,43,6,2,'Ardından büyük bir kalabalık gidiyordu. Çünkü hastalar üzerinde yaptığı mucizeleri görmüşlerdi.'),
(2009304,68,43,6,3,'İsa dağa çıkıp orada öğrencileriyle birlikte oturdu.'),
(2009305,68,43,6,4,'Yahudilerin Fısıh Bayramı yakındı.'),
(2009306,68,43,6,5,'İsa başını kaldırıp büyük bir kalabalığın kendisine doğru geldiğini görünce Filipusa, ‹‹Bunları doyurmak için nereden ekmek alalım?›› diye sordu.'),
(2009307,68,43,6,6,'Bu sözü onu denemek için söyledi, aslında kendisi ne yapacağını biliyordu.'),
(2009308,68,43,6,7,'Filipus Ona şu yanıtı verdi: ‹‹Her birinin bir lokma yiyebilmesi için iki yüz dinarlık ekmek bile yetmez.››'),
(2009309,68,43,6,8,'Öğrencilerinden biri, Simun Petrusun kardeşi Andreas, İsaya dedi ki, ‹‹Burada beş arpa ekmeğiyle iki balığı olan bir çocuk var. Ama bu kadar adam için bunlar nedir ki?››'),
(2009310,68,43,6,10,'İsa, ‹‹Halkı yere oturtun›› dedi. Orası çayırlıktı. Böylece halk yere oturdu. Yaklaşık beş bin erkek vardı.'),
(2009311,68,43,6,11,'İsa ekmekleri aldı, şükrettikten sonra oturanlara dağıttı. Balıklardan da istedikleri kadar verdi.'),
(2009312,68,43,6,12,'Herkes doyunca İsa öğrencilerine, ‹‹Artakalan parçaları toplayın, hiçbir şey ziyan olmasın›› dedi.'),
(2009313,68,43,6,13,'Onlar da topladılar. Yedikleri beş arpa ekmeğinden artakalan parçalarla on iki sepet doldurdular.'),
(2009314,68,43,6,14,'Halk, İsanın yaptığı mucizeyi görünce, ‹‹Gerçekten dünyaya gelecek olan peygamber budur›› dedi.'),
(2009315,68,43,6,15,'İsa onların gelip kendisini kral yapmak üzere zorla götüreceklerini bildiğinden tek başına yine dağa çekildi.'),
(2009316,68,43,6,16,'Akşam olunca öğrencileri göle indiler.'),
(2009317,68,43,6,17,'Bir tekneye binerek gölün karşı yakasındaki Kefarnahuma doğru yol aldılar. Karanlık basmış, İsa henüz yanlarına gelmemişti.'),
(2009318,68,43,6,18,'Güçlü bir rüzgar estiğinden göl kabarmaya başladı.'),
(2009319,68,43,6,19,'Öğrenciler üç mil kadar kürek çektikten sonra, İsanın gölün üstünde yürüyerek tekneye yaklaştığını görünce korktular.'),
(2009320,68,43,6,20,'Ama İsa, ‹‹Korkmayın, benim!›› dedi.'),
(2009321,68,43,6,21,'Bunun üzerine Onu tekneye almak istediler. O anda tekne gidecekleri kıyıya ulaştı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009322,68,43,6,22,'Ertesi gün, gölün karşı yakasında kalan halk, önceden orada sadece bir tek tekne bulunduğunu, İsanın kendi öğrencileriyle birlikte bu tekneye binmediğini, öğrencilerinin yalnız gittiklerini anladı.'),
(2009323,68,43,6,23,'Rabbin şükretmesinden sonra halkın ekmek yediği yerin yakınına Taberiyeden başka tekneler geldi.'),
(2009324,68,43,6,24,'Halk, İsanın ve öğrencilerinin orada olmadığını görünce teknelere binerek Kefarnahuma, İsayı aramaya gitti.'),
(2009325,68,43,6,25,'Onu gölün karşı yakasında buldukları zaman, ‹‹Rabbî, buraya ne zaman geldin?›› diye sordular.'),
(2009326,68,43,6,26,'İsa şöyle yanıt verdi: ‹‹Size doğrusunu söyleyeyim, doğaüstü belirtiler gördüğünüz için değil, ekmeklerden yiyip doyduğunuz için beni arıyorsunuz.'),
(2009327,68,43,6,27,'Geçici yiyecek için değil, sonsuz yaşam boyunca kalıcı yiyecek için çalışın. Bunu size İnsanoğlu verecek. Çünkü Baba Tanrı Ona bu onayı vermiştir.››'),
(2009328,68,43,6,28,'Onlar da şunu sordular: ‹‹Tanrının istediği işleri yapmak için ne yapmalıyız?››'),
(2009329,68,43,6,29,'İsa, ‹‹Tanrının işi Onun gönderdiği kişiye iman etmenizdir›› diye yanıt verdi.'),
(2009330,68,43,6,30,'Bunun üzerine, ‹‹Görüp sana iman etmemiz için nasıl bir belirti gerçekleştireceksin? Ne yapacaksın?›› dediler.'),
(2009331,68,43,6,31,'‹‹Atalarımız çölde man yediler. Yazılmış olduğu gibi, ‹Yemeleri için onlara gökten ekmek verdi.› ››'),
(2009332,68,43,6,32,'İsa onlara dedi ki, ‹‹Size doğrusunu söyleyeyim, gökten ekmeği size Musa vermedi, gökten size gerçek ekmeği Babam verir.'),
(2009333,68,43,6,33,'Çünkü Tanrının ekmeği, gökten inen ve dünyaya yaşam verendir.››'),
(2009334,68,43,6,34,'Onlar da, ‹‹Efendimiz, bizlere her zaman bu ekmeği ver!›› dediler.'),
(2009335,68,43,6,35,'İsa, ‹‹Yaşam ekmeği Benim. Bana gelen asla acıkmaz, bana iman eden hiçbir zaman susamaz›› dedi.'),
(2009336,68,43,6,36,'‹‹Ama ben size dedim ki, ‹Beni gördünüz, yine de iman etmiyorsunuz.›'),
(2009337,68,43,6,37,'Babanın bana verdiklerinin hepsi bana gelecek ve bana geleni asla kovmam.'),
(2009338,68,43,6,38,'Çünkü kendi isteğimi değil, beni gönderenin isteğini yerine getirmek için gökten indim.'),
(2009339,68,43,6,39,'Beni gönderenin isteği, bana verdiklerinden hiçbirini yitirmemem, son gün hepsini diriltmemdir.'),
(2009340,68,43,6,40,'Çünkü Babamın isteği, Oğulu gören ve Ona iman eden herkesin sonsuz yaşama kavuşmasıdır. Ben de böylelerini son günde dirilteceğim.››'),
(2009341,68,43,6,41,'‹‹Gökten inmiş olan ekmek Benim›› dediği için Yahudiler Ona karşı söylenmeye başladılar.'),
(2009342,68,43,6,42,'‹‹Yusuf oğlu İsa değil mi bu?›› diyorlardı. ‹‹Annesini de, babasını da tanıyoruz. Şimdi nasıl oluyor da, ‹Gökten indim› diyor?››'),
(2009343,68,43,6,43,'İsa, ‹‹Aranızda söylenmeyin›› dedi.'),
(2009344,68,43,6,44,'‹‹Beni gönderen Baba bir kimseyi bana çekmedikçe, o kimse bana gelemez. Bana geleni de son günde dirilteceğim.'),
(2009345,68,43,6,45,'Peygamberlerin yazdığı gibi, ‹Tanrı onların hepsine kendi yollarını öğretecektir.› Babayı işiten ve Ondan öğrenen herkes bana gelir.'),
(2009346,68,43,6,46,'Bu, bir kimsenin Babayı gördüğü anlamına gelmez. Babayı sadece Tanrıdan gelen görmüştür.'),
(2009347,68,43,6,47,'Size doğrusunu söyleyeyim, iman edenin sonsuz yaşamı vardır.'),
(2009348,68,43,6,48,'Yaşam ekmeği Benim.'),
(2009349,68,43,6,49,'Atalarınız çölde man yediler, yine de öldüler.'),
(2009350,68,43,6,50,'Gökten inen öyle bir ekmek var ki, ondan yiyen ölmeyecek.'),
(2009351,68,43,6,51,'Gökten inmiş olan diri ekmek Benim. Bu ekmekten yiyen sonsuza dek yaşayacak. Dünyanın yaşamı uğruna vereceğim ekmek de benim bedenimdir.››'),
(2009352,68,43,6,52,'Bunun üzerine Yahudiler, ‹‹Bu adam yememiz için bedenini bize nasıl verebilir?›› diyerek birbirleriyle çekişmeye başladılar.'),
(2009353,68,43,6,53,'İsa onlara şöyle dedi: ‹‹Size doğrusunu söyleyeyim, İnsanoğlunun bedenini yiyip kanını içmedikçe, sizde yaşam olmaz.'),
(2009354,68,43,6,54,'Bedenimi yiyenin, kanımı içenin sonsuz yaşamı vardır ve ben onu son günde dirilteceğim.'),
(2009355,68,43,6,55,'Çünkü bedenim gerçek yiyecek, kanım gerçek içecektir.'),
(2009356,68,43,6,56,'Bedenimi yiyip kanımı içen bende yaşar, ben de onda.'),
(2009357,68,43,6,57,'Yaşayan Baba beni gönderdiği ve ben Babanın aracılığıyla yaşadığım gibi, bedenimi yiyen de benim aracılığımla yaşayacak.'),
(2009358,68,43,6,58,'İşte gökten inmiş olan ekmek budur. Atalarınızın yedikleri man gibi değildir. Atalarınız öldüler. Oysa bu ekmeği yiyen sonsuza dek yaşar.››'),
(2009359,68,43,6,59,'İsa bu sözleri Kefarnahumda havrada öğretirken söyledi.'),
(2009360,68,43,6,60,'Öğrencilerinin birçoğu bunu işitince, ‹‹Bu söz çok çetin, kim kabul edebilir?›› dediler.'),
(2009361,68,43,6,61,'Öğrencilerinin buna karşı söylendiğini anlayan İsa, ‹‹Bu sizi şaşırtıyor mu?›› dedi.'),
(2009362,68,43,6,62,'‹‹Ya İnsanoğlunun önceden bulunduğu yere yükseldiğini görürseniz...?'),
(2009363,68,43,6,63,'Yaşam veren Ruhtur. Beden bir yarar sağlamaz. Sizlere söylediğim sözler ruhtur, yaşamdır.'),
(2009364,68,43,6,64,'Yine de aranızda iman etmeyenler var.›› İsa iman etmeyenlerin ve kendisine ihanet edecek kişinin kim olduğunu baştan beri biliyordu.'),
(2009365,68,43,6,65,'‹‹Sizlere, ‹Babanın bana yöneltmediği hiç kimse bana gelemez› dememin nedeni budur›› dedi.'),
(2009366,68,43,6,66,'Bunun üzerine öğrencilerinin birçoğu geri döndüler, artık Onunla dolaşmaz oldular.'),
(2009367,68,43,6,67,'İsa o zaman Onikilere, ‹‹Siz de mi ayrılmak istiyorsunuz?›› diye sordu.'),
(2009368,68,43,6,68,'Simun Petrus şu yanıtı verdi: ‹‹Rab, biz kime gidelim? Sonsuz yaşamın sözleri sendedir.'),
(2009369,68,43,6,69,'İman ediyor ve biliyoruz ki, sen Tanrının Kutsalısın.››'),
(2009370,68,43,6,70,'İsa onlara şu karşılığı verdi: ‹‹Siz Onikileri seçen ben değil miyim? Buna karşın içinizden biri iblistir.››'),
(2009371,68,43,6,71,'Simun İskariot''un oğlu Yahuda''dan söz ediyordu. Çünkü Yahuda Onikiler''den biri olduğu halde İsa''ya ihanet edecekti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009372,68,43,7,1,'Bundan sonra İsa Celilede dolaşmaya başladı. Yahudi yetkililer Onu öldürmeyi amaçladıkları için Yahudiyede dolaşmak istemiyordu.'),
(2009373,68,43,7,2,'Yahudilerin Çardak Bayramı yaklaşmıştı.'),
(2009374,68,43,7,3,'Bu nedenle İsanın kardeşleri Ona, ‹‹Buradan ayrıl, Yahudiyeye git›› dediler, ‹‹Öğrencilerin de yaptığın işleri görsünler.'),
(2009375,68,43,7,4,'Çünkü kendini açıkça tanıtmak isteyen bir kimse yaptıklarını gizlemez. Mademki bu şeyleri yapıyorsun, kendini dünyaya göster!››'),
(2009376,68,43,7,5,'Kardeşleri bile Ona iman etmiyorlardı.'),
(2009377,68,43,7,6,'İsa onlara, ‹‹Benim zamanım daha gelmedi›› dedi, ‹‹Oysa sizin için zaman hep uygundur.'),
(2009378,68,43,7,7,'Dünya sizden nefret edemez, ama benden nefret ediyor. Çünkü yaptıklarının kötü olduğuna tanıklık ediyorum.'),
(2009379,68,43,7,8,'Siz bu bayramı kutlamaya gidin. Ben şimdilik gitmeyeceğim. Çünkü benim zamanım daha dolmadı.››'),
(2009380,68,43,7,9,'İsa bu sözleri söyleyip Celilede kaldı.'),
(2009381,68,43,7,10,'Ne var ki, kardeşleri bayramı kutlamaya gidince, kendisi de gitti. Ancak açıktan açığa değil, gizlice gitti.'),
(2009382,68,43,7,11,'Yahudi yetkililer Onu bayram sırasında arıyor, ‹‹O nerede?›› diye soruyorlardı.'),
(2009383,68,43,7,12,'Kalabalık arasında Onunla ilgili bir sürü laf fısıldanıyordu. Bazıları, ‹‹İyi adamdır››, bazıları da, ‹‹Hayır, tam tersine, halkı saptırıyor›› diyorlardı.'),
(2009384,68,43,7,13,'Bununla birlikte yetkililerden korktukları için, hiç kimse Ondan açıkça söz etmiyordu.'),
(2009385,68,43,7,14,'Bayramın yarısı geçmişti. İsa tapınağa gidip öğretmeye başladı.'),
(2009386,68,43,7,15,'Yahudiler şaşırdılar. ‹‹Bu adam hiç öğrenim görmediği halde, nasıl bu kadar bilgili olabilir?›› dediler.'),
(2009387,68,43,7,16,'İsa onlara, ‹‹Benim öğretim benim değil, beni gönderenindir›› diye karşılık verdi.'),
(2009388,68,43,7,17,'‹‹Eğer bir kimse Tanrının isteğini yerine getirmek istiyorsa, bu öğretinin Tanrıdan mı olduğunu, yoksa kendiliğimden mi konuştuğumu bilecektir.'),
(2009389,68,43,7,18,'Kendiliğinden konuşan kendini yüceltmek ister, ama kendisini göndereni yüceltmek isteyen doğrudur ve Onda haksızlık yoktur.'),
(2009390,68,43,7,19,'Musa size Kutsal Yasayı vermedi mi? Yine de hiçbiriniz Yasayı yerine getirmiyor. Neden beni öldürmek istiyorsunuz?››'),
(2009391,68,43,7,20,'Kalabalık, ‹‹Cin çarpmış seni!›› dedi. ‹‹Seni öldürmek isteyen kim?››'),
(2009392,68,43,7,21,'İsa, ‹‹Ben bir mucize yaptım, hepiniz şaşkına döndünüz›› diye yanıt verdi.'),
(2009393,68,43,7,22,'‹‹Musa size sünneti buyurduğu için -aslında bu, Musadan değil, atalarınızdan kalmadır- Şabat Günü birini sünnet edersiniz.'),
(2009394,68,43,7,23,'Musanın Yasası bozulmasın diye Şabat Günü biri sünnet ediliyor da, Şabat Günü bir adamı tamamen iyileştirdim diye bana neden kızıyorsunuz?'),
(2009395,68,43,7,24,'Dış görünüşe göre yargılamayın, yargınız adil olsun.››'),
(2009396,68,43,7,25,'Yeruşalimlilerin bazıları, ‹‹Öldürmek istedikleri adam bu değil mi?›› diyorlardı.'),
(2009397,68,43,7,26,'‹‹Bakın, açıkça konuşuyor, Ona bir şey demiyorlar. Yoksa önderler Onun Mesih olduğunu gerçekten kabul ettiler mi?'),
(2009398,68,43,7,27,'Ama biz bu adamın nereden geldiğini biliyoruz. Oysa Mesih geldiği zaman Onun nereden geldiğini kimse bilmeyecek.››'),
(2009399,68,43,7,28,'O sırada tapınakta öğreten İsa yüksek sesle şöyle dedi: ‹‹Hem beni tanıyorsunuz, hem de nereden olduğumu biliyorsunuz! Ben kendiliğimden gelmedim. Beni gönderen gerçektir. Onu siz tanımıyorsunuz.'),
(2009400,68,43,7,29,'Ben Onu tanırım. Çünkü ben Ondanım, beni O gönderdi.››'),
(2009401,68,43,7,30,'Bunun üzerine Onu yakalamak istediler, ama kimse Ona el sürmedi. Çünkü Onun saati henüz gelmemişti.'),
(2009402,68,43,7,31,'Halktan birçok kişi ise Ona iman etti. ‹‹Mesih gelince, bunun yaptıklarından daha mı çok mucize yapacak?›› diyorlardı.'),
(2009403,68,43,7,32,'Ferisiler halkın İsa hakkında böyle fısıldaştığını duydular. Başkâhinler ve Ferisiler Onu yakalamak için görevliler gönderdiler.'),
(2009404,68,43,7,33,'İsa, ‹‹Kısa bir süre daha sizinleyim›› dedi, ‹‹Sonra beni gönderene gideceğim.'),
(2009405,68,43,7,34,'Beni arayacaksınız ama bulamayacaksınız. Ve benim bulunduğum yere siz gelemezsiniz.››'),
(2009406,68,43,7,35,'Bunun üzerine Yahudiler birbirlerine, ‹‹Bu adam nereye gidecek de biz Onu bulamayacağız?›› dediler. ‹‹Yoksa Grekler arasında dağılmış olanlara gidip Greklere mi öğretecek?'),
(2009407,68,43,7,36,'‹Beni arayacaksınız ama bulamayacaksınız. Ve benim bulunduğum yere siz gelemezsiniz› diyor. Ne demek istiyor?››'),
(2009408,68,43,7,37,'Bayramın son ve en önemli günü İsa ayağa kalktı, yüksek sesle şöyle dedi: ‹‹Bir kimse susamışsa bana gelsin, içsin.'),
(2009409,68,43,7,38,'Kutsal Yazıda dendiği gibi, bana iman edenin ‹içinden diri su ırmakları akacaktır.› ››'),
(2009410,68,43,7,39,'Bunu, kendisine iman edenlerin alacağı Ruhla ilgili olarak söylüyordu. Ruh henüz verilmemişti. Çünkü İsa henüz yüceltilmemişti.'),
(2009411,68,43,7,40,'Halktan bazıları bu sözleri işitince, ‹‹Gerçekten beklediğimiz peygamber budur›› dediler.'),
(2009412,68,43,7,41,'Bazıları da, ‹‹Bu Mesihtir›› diyorlardı. Başkaları ise, ‹‹Olamaz! Mesih Celileden mi gelecek?›› dediler.'),
(2009413,68,43,7,42,'‹‹Kutsal Yazıda, ‹Mesih, Davutun soyundan, Davutun yaşadığı Beytlehem Kentinden gelecek› denmemiş midir?››'),
(2009414,68,43,7,43,'Böylece İsadan dolayı halk arasında ayrılık doğdu.'),
(2009415,68,43,7,44,'Bazıları Onu yakalamak istedilerse de, kimse Ona el sürmedi.'),
(2009416,68,43,7,45,'Görevliler geri dönünce, başkâhinlerle Ferisiler, ‹‹Niçin Onu getirmediniz?›› diye sordular.'),
(2009417,68,43,7,46,'Görevliler, ‹‹Hiç kimse hiçbir zaman bu adamın konuştuğu gibi konuşmamıştır›› karşılığını verdiler.'),
(2009418,68,43,7,47,'Ferisiler, ‹‹Yoksa siz de mi aldandınız?›› dediler.'),
(2009419,68,43,7,48,'‹‹Önderlerden ya da Ferisilerden Ona iman eden oldu mu hiç?'),
(2009420,68,43,7,49,'Kutsal Yasayı bilmeyen bu halk lanetlidir.››'),
(2009421,68,43,7,50,'İçlerinden biri, daha önce İsaya gelen Nikodim, onlara şöyle dedi: ‹‹Yasamıza göre, bir adamı dinlemeden, ne yaptığını öğrenmeden onu yargılamak doğru mu?››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009422,68,43,7,52,'Ona, ‹‹Yoksa sen de mi Celiledensin?›› diye karşılık verdiler. ‹‹Araştır, bak, Celileden peygamber çıkmaz.››'),
(2009423,68,43,7,53,'Bundan sonra herkes evine gitti.'),
(2009424,68,43,8,1,'İsa ise Zeytin Dağına gitti.'),
(2009425,68,43,8,2,'Ertesi sabah erkenden yine tapınağa döndü. Bütün halk Onun yanına geliyordu. O da oturup onlara öğretmeye başladı.'),
(2009426,68,43,8,3,'Din bilginleri ve Ferisiler, zina ederken yakalanmış bir kadın getirdiler. Kadını orta yere çıkararak İsaya, ‹‹Öğretmen, bu kadın tam zina ederken yakalandı›› dediler.'),
(2009427,68,43,8,5,'‹‹Musa, Yasada bize böyle kadınların taşlanmasını buyurdu, sen ne dersin?››'),
(2009428,68,43,8,6,'Bunları İsayı denemek amacıyla söylüyorlardı; Onu suçlayabilmek için bir neden arıyorlardı. İsa eğilmiş, parmağıyla toprağa yazı yazıyordu.'),
(2009429,68,43,8,7,'Durmadan aynı soruyu sormaları üzerine doğruldu ve, ‹‹İçinizde kim günahsızsa, ilk taşı o atsın!›› dedi.'),
(2009430,68,43,8,8,'Sonra yine eğildi, toprağa yazmaya başladı.'),
(2009431,68,43,8,9,'Bunu işittikleri zaman, başta yaşlılar olmak üzere, birer birer dışarı çıkıp İsayı yalnız bıraktılar. Kadın ise orta yerde duruyordu.'),
(2009432,68,43,8,10,'İsa doğrulup ona, ‹‹Kadın, nerede onlar? Hiçbiri seni yargılamadı mı?›› diye sordu.'),
(2009433,68,43,8,11,'Kadın, ‹‹Hiçbiri, Efendim›› dedi. İsa, ‹‹Ben de seni yargılamıyorum›› dedi. ‹‹Git, artık bundan sonra günah işleme!››'),
(2009434,68,43,8,12,'İsa yine halka seslenip şöyle dedi: ‹‹Ben dünyanın ışığıyım. Benim ardımdan gelen, asla karanlıkta yürümez, yaşam ışığına sahip olur.››'),
(2009435,68,43,8,13,'Ferisiler, ‹‹Sen kendin için tanıklık ediyorsun, tanıklığın geçerli değil›› dediler.'),
(2009436,68,43,8,14,'İsa onlara şu karşılığı verdi: ‹‹Kendim için tanıklık etsem bile tanıklığım geçerlidir. Çünkü nereden geldiğimi ve nereye gideceğimi biliyorum. Oysa siz nereden geldiğimi, nereye gideceğimi bilmiyorsunuz.'),
(2009437,68,43,8,15,'Siz insan gözüyle yargılıyorsunuz. Ben kimseyi yargılamam.'),
(2009438,68,43,8,16,'Yargılasam bile benim yargım doğrudur. Çünkü ben yalnız değilim, ben ve beni gönderen Baba, birlikte yargılarız.'),
(2009439,68,43,8,17,'Yasanızda da, ‹İki kişinin tanıklığı geçerlidir› diye yazılmıştır.'),
(2009440,68,43,8,18,'Kendim için tanıklık eden bir ben varım, bir de beni gönderen Baba benim için tanıklık ediyor.››'),
(2009441,68,43,8,19,'O zaman Ona, ‹‹Baban nerede?›› diye sordular. İsa şu karşılığı verdi: ‹‹Siz ne beni tanırsınız, ne de Babamı. Beni tanısaydınız, Babamı da tanırdınız.››'),
(2009442,68,43,8,20,'İsa bu sözleri tapınakta öğretirken, bağış toplanan yerde söyledi. Kimse Onu yakalamadı. Çünkü saati henüz gelmemişti.'),
(2009443,68,43,8,21,'İsa yine onlara, ‹‹Ben gidiyorum. Beni arayacaksınız ve günahınızın içinde öleceksiniz. Benim gideceğim yere siz gelemezsiniz›› dedi.'),
(2009444,68,43,8,22,'Yahudi yetkililer, ‹‹Yoksa kendini mi öldürecek?›› dediler. ‹‹Çünkü, ‹Benim gideceğim yere siz gelemezsiniz› diyor.››'),
(2009445,68,43,8,23,'İsa onlara, ‹‹Siz aşağıdansınız, ben yukarıdanım›› dedi. ‹‹Siz bu dünyadansınız, ben bu dünyadan değilim.'),
(2009446,68,43,8,24,'İşte bu nedenle size, ‹Günahlarınızın içinde öleceksiniz› dedim. Benim O olduğuma iman etmezseniz, günahlarınızın içinde öleceksiniz.››'),
(2009447,68,43,8,25,'Ona, ‹‹Sen kimsin?›› diye sordular. İsa, ‹‹Başlangıçtan beri size ne söyledimse, Oyum›› dedi.'),
(2009448,68,43,8,26,'‹‹Sizinle ilgili söyleyecek ve sizleri yargılayacak çok şeyim var. Beni gönderen gerçektir. Ben Ondan işittiklerimi dünyaya bildiriyorum.››'),
(2009449,68,43,8,27,'İsanın kendilerine Babadan söz ettiğini anlamadılar.'),
(2009450,68,43,8,28,'Bu nedenle İsa şöyle dedi: ‹‹İnsanoğlunu yukarı kaldırdığınız zaman benim O olduğumu, kendiliğimden hiçbir şey yapmadığımı, ama tıpkı Babanın bana öğrettiği gibi konuştuğumu anlayacaksınız.'),
(2009451,68,43,8,29,'Beni gönderen benimledir, O beni yalnız bırakmadı. Çünkü ben her zaman Onu hoşnut edeni yaparım.››'),
(2009452,68,43,8,30,'Bu sözler üzerine birçokları Ona iman etti.'),
(2009453,68,43,8,31,'İsa kendisine iman etmiş olan Yahudilere, ‹‹Eğer benim sözüme bağlı kalırsanız, gerçekten öğrencilerim olursunuz. Gerçeği bileceksiniz ve gerçek sizi özgür kılacak›› dedi.'),
(2009454,68,43,8,33,'‹‹Biz İbrahimin soyundanız›› diye karşılık verdiler, ‹‹Hiçbir zaman kimseye kölelik etmedik. Nasıl oluyor da sen, ‹Özgür olacaksınız› diyorsun?››'),
(2009455,68,43,8,34,'İsa, ‹‹Size doğrusunu söyleyeyim, günah işleyen herkes günahın kölesidir›› dedi.'),
(2009456,68,43,8,35,'‹‹Köle ev halkının sürekli bir üyesi değildir, ama oğul sürekli üyesidir.'),
(2009457,68,43,8,36,'Bunun için, Oğul sizi özgür kılarsa, gerçekten özgür olursunuz.'),
(2009458,68,43,8,37,'İbrahimin soyundan olduğunuzu biliyorum. Yine de beni öldürmek istiyorsunuz. Çünkü yüreğinizde sözüme yer vermiyorsunuz.'),
(2009459,68,43,8,38,'Ben Babamın yanında gördüklerimi söylüyorum, siz de babanızdan işittiklerinizi yapıyorsunuz.››'),
(2009460,68,43,8,39,'‹‹Bizim babamız İbrahimdir›› diye karşılık verdiler. İsa, ‹‹İbrahimin çocukları olsaydınız, İbrahimin yaptıklarını yapardınız›› dedi.'),
(2009461,68,43,8,40,'‹‹Ama şimdi beni -Tanrıdan işittiği gerçeği sizlere bildireni- öldürmek istiyorsunuz. İbrahim bunu yapmadı.'),
(2009462,68,43,8,41,'Siz babanızın yaptıklarını yapıyorsunuz.›› ‹‹Biz zinadan doğmadık. Bir tek Babamız var, o da Tanrıdır›› dediler.'),
(2009463,68,43,8,42,'İsa, ‹‹Tanrı Babanız olsaydı, beni severdiniz›› dedi. ‹‹Çünkü ben Tanrıdan çıkıp geldim. Kendiliğimden gelmedim, beni O gönderdi.'),
(2009464,68,43,8,43,'Söylediklerimi neden anlamıyorsunuz? Benim sözümü dinlemeye dayanamıyorsunuz da ondan.'),
(2009465,68,43,8,44,'Siz babanız İblistensiniz ve babanızın arzularını yerine getirmek istiyorsunuz. O başlangıçtan beri katildi. Gerçeğe bağlı kalmadı. Çünkü onda gerçek yoktur. Yalan söylemesi doğaldır. Çünkü o yalancıdır ve yalanın babasıdır.'),
(2009466,68,43,8,45,'Ama ben gerçeği söylüyorum. İşte bunun için bana iman etmiyorsunuz.'),
(2009467,68,43,8,46,'Hanginiz bana günahlı olduğumu kanıtlayabilir? Gerçeği söylüyorsam, niçin bana iman etmiyorsunuz?'),
(2009468,68,43,8,47,'Tanrıdan olan, Tanrının sözlerini dinler. İşte siz Tanrıdan olmadığınız için dinlemiyorsunuz.››'),
(2009469,68,43,8,48,'Yahudiler Ona şu karşılığı verdiler: ‹‹ ‹Sen, cin çarpmış bir Samiriyelisin› demekte haklı değil miyiz?››'),
(2009470,68,43,8,49,'İsa, ‹‹Beni cin çarpmadı›› dedi. ‹‹Ben Babamı onurlandırıyorum, ama siz beni aşağılıyorsunuz.'),
(2009471,68,43,8,50,'Ben kendimi yüceltmek istemiyorum, ama bunu isteyen ve yargılayan biri vardır.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009472,68,43,8,51,'Size doğrusunu söyleyeyim, bir kimse sözüme uyarsa, ölümü asla görmeyecektir.››'),
(2009473,68,43,8,52,'Yahudiler, ‹‹Seni cin çarptığını şimdi anlıyoruz›› dediler. ‹‹İbrahim öldü, peygamberler de öldü. Oysa sen, ‹Bir kimse sözüme uyarsa, ölümü asla tatmayacaktır› diyorsun.'),
(2009474,68,43,8,53,'Yoksa sen babamız İbrahimden üstün müsün? O öldü, peygamberler de öldü. Sen kendini kim sanıyorsun?››'),
(2009475,68,43,8,54,'İsa şu karşılığı verdi: ‹‹Eğer ben kendimi yüceltirsem, yüceliğim hiçtir. Beni yücelten, ‹Tanrımız› diye çağırdığınız Babamdır.'),
(2009476,68,43,8,55,'Siz Onu tanımıyorsunuz, ama ben tanıyorum. Onu tanımadığımı söylersem, sizin gibi yalancı olurum. Ama ben Onu tanıyor ve sözüne uyuyorum.'),
(2009477,68,43,8,56,'Babanız İbrahim günümü göreceği için sevinçle coşmuştu. Gördü ve sevindi.››'),
(2009478,68,43,8,57,'Yahudiler, ‹‹Sen daha elli yaşında bile değilsin. İbrahimi de mi gördün?›› dediler.'),
(2009479,68,43,8,58,'İsa, ‹‹Size doğrusunu söyleyeyim, İbrahim doğmadan önce ben varım›› dedi.'),
(2009480,68,43,8,59,'O zaman İsa''yı taşlamak için yerden taş aldılar, ama O gizlenip tapınaktan çıktı.'),
(2009481,68,43,9,1,'İsa yolda giderken doğuştan kör bir adam gördü.'),
(2009482,68,43,9,2,'Öğrencileri İsaya, ‹‹Rabbî, kim günah işledi de bu adam kör doğdu? Kendisi mi, yoksa annesi babası mı?›› diye sordular.'),
(2009483,68,43,9,3,'İsa şu yanıtı verdi: ‹‹Ne kendisi, ne de annesi babası günah işledi. Tanrının işleri onun yaşamında görülsün diye kör doğdu.'),
(2009484,68,43,9,4,'Beni gönderenin işlerini vakit daha gündüzken yapmalıyız. Gece geliyor, o zaman kimse çalışamaz.'),
(2009485,68,43,9,5,'Dünyada olduğum sürece dünyanın ışığı Benim.››'),
(2009486,68,43,9,6,'Bu sözleri söyledikten sonra yere tükürdü, tükürükle çamur yaptı ve çamuru adamın gözlerine sürdü.'),
(2009487,68,43,9,7,'Adama, ‹‹Git, Şiloah Havuzunda yıkan›› dedi. Şiloah, gönderilmiş anlamına gelir. Adam gidip yıkandı, gözleri açılmış olarak döndü.'),
(2009488,68,43,9,8,'Komşuları ve onu daha önce dilenirken görenler, ‹‹Oturup dilenen adam değil mi bu?›› dediler.'),
(2009489,68,43,9,9,'Kimi, ‹‹Evet, odur›› dedi, kimi de ‹‹Hayır, ama ona benziyor›› dedi. Kendisi ise, ‹‹Ben oyum›› dedi.'),
(2009490,68,43,9,10,'‹‹Öyleyse, gözlerin nasıl açıldı?›› diye sordular.'),
(2009491,68,43,9,11,'O da şöyle yanıt verdi: ‹‹İsa adındaki adam çamur yapıp gözlerime sürdü ve bana, ‹Şiloaha git, yıkan› dedi. Ben de gidip yıkandım ve gözlerim açıldı.››'),
(2009492,68,43,9,12,'Ona, ‹‹Nerede O?›› diye sordular. ‹‹Bilmiyorum›› dedi.'),
(2009493,68,43,9,13,'Eskiden kör olan adamı Ferisilerin yanına götürdüler.'),
(2009494,68,43,9,14,'İsanın çamur yapıp adamın gözlerini açtığı gün Şabat Günüydü.'),
(2009495,68,43,9,15,'Bu nedenle Ferisiler de adama gözlerinin nasıl açıldığını sordular. O da, ‹‹İsa gözlerime çamur sürdü, yıkandım ve şimdi görüyorum›› dedi.'),
(2009496,68,43,9,16,'Bunun üzerine Ferisilerin bazıları, ‹‹Bu adam Tanrıdan değildir›› dediler. ‹‹Çünkü Şabat Gününü tutmuyor.›› Ama başkaları, ‹‹Günahkâr bir adam nasıl bu tür belirtiler gerçekleştirebilir?›› dediler. Böylece aralarında ayrılık doğdu.'),
(2009497,68,43,9,17,'Eskiden kör olan adama yine sordular: ‹‹Senin gözlerini açtığına göre, Onun hakkında sen ne diyorsun?›› Adam, ‹‹O bir peygamberdir›› dedi.'),
(2009498,68,43,9,18,'Yahudi yetkililer, gözleri açılan adamın annesiyle babasını çağırmadan onun daha önce kör olduğuna ve gözlerinin açıldığına inanmadılar.'),
(2009499,68,43,9,19,'Onlara, ‹‹Kör doğdu dediğiniz oğlunuz bu mu? Peki, şimdi nasıl görüyor?›› diye sordular.'),
(2009500,68,43,9,20,'Adamın annesiyle babası şu karşılığı verdiler: ‹‹Bunun bizim oğlumuz olduğunu ve kör doğduğunu biliyoruz.'),
(2009501,68,43,9,21,'Ama şimdi nasıl gördüğünü, gözlerini kimin açtığını bilmiyoruz, ona sorun. Ergin yaştadır, kendisi için kendisi konuşsun.››'),
(2009502,68,43,9,22,'Yahudi yetkililerden korktukları için böyle konuştular. Çünkü yetkililer, İsanın Mesih olduğunu açıkça söyleyeni havra dışı etmek için aralarında sözbirliği etmişlerdi.'),
(2009503,68,43,9,23,'Bundan dolayı adamın annesiyle babası, ‹‹Ergin yaştadır, ona sorun›› dediler.'),
(2009504,68,43,9,24,'Eskiden kör olan adamı ikinci kez çağırıp, ‹‹Tanrı hakkı için doğruyu söyle›› dediler, ‹‹Biz bu adamın günahkâr olduğunu biliyoruz.››'),
(2009505,68,43,9,25,'O da şöyle yanıt verdi: ‹‹Onun günahkâr olup olmadığını bilmiyorum. Bildiğim bir şey var, kördüm, şimdi görüyorum.››'),
(2009506,68,43,9,26,'O zaman ona, ‹‹Sana ne yaptı? Gözlerini nasıl açtı?›› dediler.'),
(2009507,68,43,9,27,'Onlara, ‹‹Size demin söyledim, ama dinlemediniz›› dedi. ‹‹Niçin yeniden işitmek istiyorsunuz? Yoksa siz de mi Onun öğrencileri olmak niyetindesiniz?››'),
(2009508,68,43,9,28,'Adama söverek, ‹‹Onun öğrencisi sensin!›› dediler. ‹‹Biz Musanın öğrencileriyiz.'),
(2009509,68,43,9,29,'Tanrının Musayla konuştuğunu biliyoruz. Ama bu adamın nereden geldiğini bilmiyoruz.››'),
(2009510,68,43,9,30,'Adam onlara şu karşılığı verdi: ‹‹Şaşılacak şey! Onun nereden geldiğini bilmiyorsunuz, ama gözlerimi O açtı.'),
(2009511,68,43,9,31,'Tanrının, günahkârları dinlemediğini biliriz. Ama Tanrı, kendisine tapan ve isteğini yerine getiren kişiyi dinler.'),
(2009512,68,43,9,32,'Dünya var olalı, bir kimsenin doğuştan kör olan birinin gözlerini açtığı duyulmamıştır.'),
(2009513,68,43,9,33,'Bu adam Tanrıdan olmasaydı, hiçbir şey yapamazdı.››'),
(2009514,68,43,9,34,'Onlar buna karşılık, ‹‹Tamamen günah içinde doğdun, sen mi bize ders vereceksin?›› diyerek onu dışarı attılar.'),
(2009515,68,43,9,35,'İsa adamı kovduklarını duydu. Onu bularak, ‹‹Sen İnsanoğluna iman ediyor musun?›› diye sordu.'),
(2009516,68,43,9,36,'Adam şu yanıtı verdi: ‹‹Efendim, O kimdir? Söyle de kendisine iman edeyim.››'),
(2009517,68,43,9,37,'İsa, ‹‹Onu gördün. Şimdi seninle konuşan Odur›› dedi.'),
(2009518,68,43,9,38,'Adam, ‹‹Rab, iman ediyorum!›› diyerek İsaya tapındı.'),
(2009519,68,43,9,39,'İsa, ‹‹Görmeyenler görsün, görenler kör olsun diye yargıçlık etmek üzere bu dünyaya geldim›› dedi.'),
(2009520,68,43,9,40,'Onun yanında bulunan bazı Ferisiler bu sözleri işitince, ‹‹Yoksa biz de mi körüz?›› diye sordular.'),
(2009521,68,43,9,41,'İsa, ‹‹Kör olsaydınız günahınız olmazdı›› dedi, ‹‹Ama şimdi, ‹Görüyoruz› dediğiniz için günahınız duruyor.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009522,68,43,10,1,'‹‹Size doğrusunu söyleyeyim, koyun ağılına kapıdan girmeyip başka yoldan giren kişi hırsız ve hayduttur.'),
(2009523,68,43,10,2,'Kapıdan giren ise koyunların çobanıdır.'),
(2009524,68,43,10,3,'Kapıyı bekleyen ona kapıyı açar. Koyunlar çobanın sesini işitirler, o da kendi koyunlarını adlarıyla çağırır ve onları dışarı götürür.'),
(2009525,68,43,10,4,'Kendi koyunlarının hepsini dışarı çıkarınca önlerinden gider, koyunlar da onu izler. Çünkü onun sesini tanırlar.'),
(2009526,68,43,10,5,'Bir yabancının peşinden gitmezler, ondan kaçarlar. Çünkü yabancıların sesini tanımazlar.››'),
(2009527,68,43,10,6,'İsa onlara bu örneği anlattıysa da, ne demek istediğini anlamadılar.'),
(2009528,68,43,10,7,'Bunun için İsa yine, ‹‹Size doğrusunu söyleyeyim›› dedi, ‹‹Ben koyunların kapısıyım.'),
(2009529,68,43,10,8,'Benden önce gelenlerin hepsi hırsız ve hayduttu, ama koyunlar onları dinlemedi.'),
(2009530,68,43,10,9,'Kapı Benim. Bir kimse benim aracılığımla içeri girerse kurtulur. Girer, çıkar ve otlak bulur.'),
(2009531,68,43,10,10,'Hırsız ancak çalıp öldürmek ve yok etmek için gelir. Bense insanlar yaşama, bol yaşama sahip olsunlar diye geldim.'),
(2009532,68,43,10,11,'Ben iyi çobanım. İyi çoban koyunları uğruna canını verir.'),
(2009533,68,43,10,12,'Koyunların çobanı ve sahibi olmayan ücretli adam, kurdun geldiğini görünce koyunları bırakıp kaçar. Kurt da onları kapar ve dağıtır.'),
(2009534,68,43,10,13,'Adam kaçar. Çünkü ücretlidir ve koyunlar için kaygı duymaz.'),
(2009535,68,43,10,14,'Ben iyi çobanım. Benimkileri tanırım. Baba beni tanıdığı, ben de Babayı tanıdığım gibi, benimkiler de beni tanır. Ben koyunlarımın uğruna canımı veririm.'),
(2009536,68,43,10,16,'Bu ağıldan olmayan başka koyunlarım var. Onları da getirmeliyim. Benim sesimi işitecekler ve tek sürü, tek çoban olacak.'),
(2009537,68,43,10,17,'Canımı, tekrar geri almak üzere veririm. Bunun için Baba beni sever.'),
(2009538,68,43,10,18,'Canımı kimse benden alamaz; ben onu kendiliğimden veririm. Onu vermeye de tekrar geri almaya da yetkim var. Bu buyruğu Babamdan aldım.››'),
(2009539,68,43,10,19,'Bu sözlerden dolayı Yahudiler arasında yine ayrılık doğdu.'),
(2009540,68,43,10,20,'Birçoğu, ‹‹Onu cin çarpmış, delidir. Niçin Onu dinliyorsunuz?›› diyordu.'),
(2009541,68,43,10,21,'Başkaları ise, ‹‹Bunlar, cin çarpmış bir adamın sözleri değil›› dediler. ‹‹Cin, körlerin gözlerini açabilir mi?››'),
(2009542,68,43,10,22,'O sırada Yeruşalimde Tapınağın Açılışını Anma Bayramı kutlanıyordu. Mevsim kıştı.'),
(2009543,68,43,10,23,'İsa tapınağın avlusunda, Süleymanın Eyvanında yürüyordu.'),
(2009544,68,43,10,24,'Yahudi yetkililer Onun çevresini sararak, ‹‹Bizi daha ne kadar zaman kuşkuda bırakacaksın?›› dediler. ‹‹Eğer Mesih isen, bize açıkça söyle.››'),
(2009545,68,43,10,25,'İsa onlara şu karşılığı verdi: ‹‹Size söyledim, ama iman etmiyorsunuz. Babamın adıyla yaptığım işler bana tanıklık ediyor.'),
(2009546,68,43,10,26,'Ama siz iman etmiyorsunuz. Çünkü benim koyunlarımdan değilsiniz.'),
(2009547,68,43,10,27,'Koyunlarım sesimi işitir. Ben onları tanırım, onlar da beni izler.'),
(2009548,68,43,10,28,'Onlara sonsuz yaşam veririm; asla mahvolmayacaklar. Onları hiç kimse elimden kapamaz.'),
(2009549,68,43,10,29,'Onları bana veren Babam her şeyden üstündür. Onları Babanın elinden kapmaya kimsenin gücü yetmez.'),
(2009550,68,43,10,30,'Ben ve Baba biriz.››'),
(2009551,68,43,10,31,'Yahudi yetkililer Onu taşlamak için yerden yine taş aldılar.'),
(2009552,68,43,10,32,'İsa onlara, ‹‹Size Babadan kaynaklanan birçok iyi işler gösterdim›› dedi. ‹‹Bu işlerden hangisi için beni taşlıyorsunuz?››'),
(2009553,68,43,10,33,'Şöyle yanıt verdiler: ‹‹Seni iyi işlerden ötürü değil, küfür ettiğin için taşlıyoruz. İnsan olduğun halde Tanrı olduğunu ileri sürüyorsun.››'),
(2009554,68,43,10,34,'İsa şu karşılığı verdi: ‹‹Yasanızda, ‹Siz ilahlarsınız, dedim› diye yazılı değil mi?'),
(2009555,68,43,10,35,'Tanrı, kendilerine sözünü gönderdiği kimseleri ilahlar diye adlandırır. Kutsal Yazı da geçerliliğini yitirmez.'),
(2009556,68,43,10,36,'Baba beni kendine ayırıp dünyaya gönderdi. Öyleyse ‹Tanrının Oğluyum› dediğim için bana nasıl ‹Küfür ediyorsun› dersiniz?'),
(2009557,68,43,10,37,'Eğer Babamın işlerini yapmıyorsam, bana iman etmeyin.'),
(2009558,68,43,10,38,'Ama yapıyorsam, bana iman etmeseniz bile, yaptığım işlere iman edin. Öyle ki, Babanın bende, benim de Babada olduğumu bilesiniz ve anlayasınız.››'),
(2009559,68,43,10,39,'Onu yine yakalamaya çalıştılarsa da, ellerinden sıyrılıp kurtuldu.'),
(2009560,68,43,10,40,'Tekrar Şeria Irmağının karşı yakasına, Yahyanın başlangıçta vaftiz ettiği yere gitti ve orada kaldı.'),
(2009561,68,43,10,41,'Birçokları, ‹‹Yahya hiç mucize yapmadı, ama bu adam için söylediklerinin hepsi doğru çıktı›› diyerek İsaya geldiler.'),
(2009562,68,43,10,42,'Ve orada birçokları O''na iman etti.'),
(2009563,68,43,11,1,'Meryem ile kızkardeşi Martanın köyü olan Beytanyadan Lazar adında bir adam hastalanmıştı.'),
(2009564,68,43,11,2,'Meryem, Rabbe güzel kokulu yağ sürüp saçlarıyla Onun ayaklarını silen kadındı. Hasta Lazar ise Meryemin kardeşiydi.'),
(2009565,68,43,11,3,'İki kızkardeş İsaya, ‹‹Rab, sevdiğin kişi hasta›› diye haber gönderdiler.'),
(2009566,68,43,11,4,'İsa bunu işitince, ‹‹Bu hastalık ölümle sonuçlanmayacak; Tanrının yüceliğine, Tanrı Oğlunun yüceltilmesine hizmet edecek›› dedi.'),
(2009567,68,43,11,5,'İsa Martayı, kızkardeşini ve Lazarı severdi.'),
(2009568,68,43,11,6,'Bu nedenle, Lazarın hasta olduğunu duyunca bulunduğu yerde iki gün daha kaldıktan sonra öğrencilere, ‹‹Yahudiyeye dönelim›› dedi.'),
(2009569,68,43,11,8,'Öğrenciler, ‹‹Rabbî›› dediler, ‹‹Yahudi yetkililer demin seni taşlamaya kalkıştılar. Yine oraya mı gidiyorsun?››'),
(2009570,68,43,11,9,'İsa şu karşılığı verdi: ‹‹Günün on iki saati yok mu? Gündüz yürüyen sendelemez. Çünkü bu dünyanın ışığını görür.'),
(2009571,68,43,11,10,'Oysa gece yürüyen sendeler. Çünkü kendisinde ışık yoktur.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009572,68,43,11,11,'Bu sözleri söyledikten sonra, ‹‹Dostumuz Lazar uyudu›› diye ekledi, ‹‹Onu uyandırmaya gidiyorum.››'),
(2009573,68,43,11,12,'Öğrenciler, ‹‹Ya Rab›› dediler, ‹‹Uyuduysa iyileşecektir.››'),
(2009574,68,43,11,13,'İsa Lazarın ölümünden söz ediyordu, ama onlar olağan uykudan söz ettiğini sanmışlardı.'),
(2009575,68,43,11,14,'Bunun üzerine İsa açıkça, ‹‹Lazar öldü›› dedi.'),
(2009576,68,43,11,15,'‹‹İman edesiniz diye, orada bulunmadığıma sizin için seviniyorum. Şimdi onun yanına gidelim.››'),
(2009577,68,43,11,16,'‹‹İkiz›› diye anılan Tomas öbür öğrencilere, ‹‹Biz de gidelim, Onunla birlikte ölelim!›› dedi.'),
(2009578,68,43,11,17,'İsa Beytanyaya yaklaşınca Lazarın dört gündür mezarda olduğunu öğrendi.'),
(2009579,68,43,11,18,'Beytanya, Yeruşalime on beş ok atımı kadar uzaklıktaydı.'),
(2009580,68,43,11,19,'Birçok Yahudi, kardeşlerini yitiren Martayla Meryemi avutmaya gelmişti.'),
(2009581,68,43,11,20,'Marta İsanın geldiğini duyunca Onu karşılamaya çıktı, Meryem ise evde kaldı.'),
(2009582,68,43,11,21,'Marta İsaya, ‹‹Ya Rab›› dedi, ‹‹Burada olsaydın, kardeşim ölmezdi.'),
(2009583,68,43,11,22,'Şimdi bile, Tanrıdan ne dilersen Tanrının onu sana vereceğini biliyorum.››'),
(2009584,68,43,11,23,'İsa, ‹‹Kardeşin dirilecektir›› dedi.'),
(2009585,68,43,11,24,'Marta, ‹‹Son gün, diriliş günü onun dirileceğini biliyorum›› dedi.'),
(2009586,68,43,11,25,'İsa ona, ‹‹Diriliş ve yaşam Benim›› dedi. ‹‹Bana iman eden kişi ölse de yaşayacaktır.'),
(2009587,68,43,11,26,'Yaşayan ve bana iman eden asla ölmeyecek. Buna iman ediyor musun?››'),
(2009588,68,43,11,27,'Marta, ‹‹Evet, ya Rab›› dedi. ‹‹Senin, dünyaya gelecek olan Tanrının Oğlu Mesih olduğuna iman ettim.››'),
(2009589,68,43,11,28,'Bunu söyledikten sonra gidip kızkardeşi Meryemi gizlice çağırdı. ‹‹Öğretmen burada, seni çağırıyor›› dedi.'),
(2009590,68,43,11,29,'Meryem bunu işitince hemen kalkıp İsanın yanına gitti.'),
(2009591,68,43,11,30,'İsa henüz köye varmamıştı, hâlâ Martanın kendisini karşıladığı yerdeydi.'),
(2009592,68,43,11,31,'Meryemle birlikte evde bulunan ve kendisini teselli eden Yahudiler, onun hızla kalkıp dışarı çıktığını gördüler. Ağlamak için mezara gittiğini sanarak onu izlediler.'),
(2009593,68,43,11,32,'Meryem İsanın bulunduğu yere vardı. Onu görünce ayaklarına kapanarak, ‹‹Ya Rab›› dedi, ‹‹Burada olsaydın, kardeşim ölmezdi.››'),
(2009594,68,43,11,33,'Meryemin ve onunla gelen Yahudilerin ağladığını gören İsanın ruhunu hüzün kapladı, yüreği sızladı.'),
(2009595,68,43,11,34,'‹‹Onu nereye koydunuz?›› diye sordu. Ona, ‹‹Ya Rab, gel gör›› dediler.'),
(2009596,68,43,11,35,'İsa ağladı.'),
(2009597,68,43,11,36,'Yahudiler, ‹‹Bakın, onu ne kadar seviyormuş!›› dediler.'),
(2009598,68,43,11,37,'Ama içlerinden bazıları, ‹‹Körün gözlerini açan bu kişi, Lazarın ölümünü de önleyemez miydi?›› dediler.'),
(2009599,68,43,11,38,'İsa yine derinden hüzünlenerek mezara vardı. Mezar bir mağaraydı, girişinde de bir taş duruyordu.'),
(2009600,68,43,11,39,'İsa, ‹‹Taşı çekin!›› dedi. Ölenin kızkardeşi Marta, ‹‹Rab, o artık kokmuştur, öleli dört gün oldu›› dedi.'),
(2009601,68,43,11,40,'İsa ona, ‹‹Ben sana, ‹İman edersen Tanrının yüceliğini göreceksin› demedim mi?›› dedi.'),
(2009602,68,43,11,41,'Bunun üzerine taşı çektiler. İsa gözlerini gökyüzüne kaldırarak şöyle dedi: ‹‹Baba, beni işittiğin için sana şükrediyorum.'),
(2009603,68,43,11,42,'Beni her zaman işittiğini biliyordum. Ama bunu, çevrede duran halk için, beni senin gönderdiğine iman etsinler diye söyledim.››'),
(2009604,68,43,11,43,'Bunları söyledikten sonra yüksek sesle, ‹‹Lazar, dışarı çık!›› diye bağırdı.'),
(2009605,68,43,11,44,'Ölü, elleri ayakları sargılarla bağlı, yüzü peşkirle sarılmış olarak dışarı çıktı. İsa oradakilere, ‹‹Onu çözün, bırakın gitsin›› dedi.'),
(2009606,68,43,11,45,'O zaman, Meryeme gelen ve İsanın yaptıklarını gören Yahudilerin birçoğu İsaya iman etti.'),
(2009607,68,43,11,46,'Ama içlerinden bazıları Ferisilere giderek İsanın yaptıklarını onlara bildirdiler.'),
(2009608,68,43,11,47,'Bunun üzerine başkâhinler ve Ferisiler, Yüksek Kurulu toplayıp dediler ki, ‹‹Ne yapacağız? Bu adam birçok doğaüstü belirti gerçekleştiriyor.'),
(2009609,68,43,11,48,'Böyle devam etmesine izin verirsek, herkes Ona iman edecek. Romalılar da gelip kutsal yerimizi ve ulusumuzu ortadan kaldıracaklar.››'),
(2009610,68,43,11,49,'İçlerinden biri, o yıl başkâhin olan Kayafa, ‹‹Hiçbir şey bilmiyorsunuz›› dedi.'),
(2009611,68,43,11,50,'‹‹Bütün ulus yok olacağına, halk uğruna bir tek adamın ölmesi sizin için daha uygun. Bunu anlamıyor musunuz?››'),
(2009612,68,43,11,51,'Bunu kendiliğinden söylemiyordu. O yılın başkâhini olarak İsanın, ulusun uğruna, ve yalnız ulusun uğruna değil, Tanrının dağılmış çocuklarını toplayıp birleştirmek için de öleceğine ilişkin peygamberlikte bulunuyordu.'),
(2009613,68,43,11,53,'Böylece o günden itibaren İsayı öldürmek için düzen kurmaya başladılar.'),
(2009614,68,43,11,54,'Bu yüzden İsa artık Yahudiler arasında açıkça dolaşmaz oldu. Oradan ayrılarak çöle yakın bir yere, Efrayim denilen kente gitti. Öğrencileriyle birlikte orada kaldı.'),
(2009615,68,43,11,55,'Yahudilerin Fısıh Bayramı yakındı. Taşradakilerin birçoğu bayramdan önce arınmak için Yeruşalime gitti.'),
(2009616,68,43,11,56,'Orada İsayı arayıp durdular. Tapınaktayken birbirlerine, ‹‹Ne dersiniz, bayrama hiç gelmeyecek mi?›› diye soruyorlardı.'),
(2009617,68,43,11,57,'Başkâhinlerle Ferisiler O''nu yakalayabilmek için, yerini bilenlerin haber vermesini buyurmuşlardı.'),
(2009618,68,43,12,1,'İsa, Fısıh Bayramından altı gün önce, ölümden dirilttiği Lazarın bulunduğu Beytanyaya geldi.'),
(2009619,68,43,12,2,'Orada kendisi için bir ziyafet düzenlediler. Marta hizmet ediyordu. İsayla birlikte sofrada oturanlardan biri de Lazardı.'),
(2009620,68,43,12,3,'Meryem, çok değerli saf hintsümbülü yağından yarım litre kadar getirerek İsanın ayaklarına sürdü ve saçlarıyla ayaklarını sildi. Ev yağın güzel kokusuyla doldu.'),
(2009621,68,43,12,4,'Ama öğrencilerinden biri, İsaya sonradan ihanet eden Yahuda İskariot, ‹‹Bu yağ neden üç yüz dinara satılıp parası yoksullara verilmedi?›› dedi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009622,68,43,12,6,'Bunu, yoksullarla ilgilendiği için değil, hırsız olduğu için söylüyordu. Ortak para kutusu ondaydı ve kutuya konulandan aşırıyordu.'),
(2009623,68,43,12,7,'İsa, ‹‹Kadını rahat bırak›› dedi. ‹‹Bunu benim gömüleceğim gün için saklasın.'),
(2009624,68,43,12,8,'Yoksullar her zaman aranızdadır, ama ben her zaman aranızda olmayacağım.››'),
(2009625,68,43,12,9,'Yahudilerden büyük bir kalabalık İsanın Beytanyada bulunduğunu öğrendi ve yalnız İsa için değil, Onun ölümden dirilttiği Lazarı da görmek için oraya geldi.'),
(2009626,68,43,12,10,'Başkâhinler ise Lazarı da öldürmeyi tasarladılar.'),
(2009627,68,43,12,11,'Çünkü onun yüzünden birçok Yahudi gidip İsaya iman ediyordu.'),
(2009628,68,43,12,12,'Ertesi gün, bayramı kutlamaya gelen büyük kalabalık İsanın Yeruşalime gelmekte olduğunu duydu.'),
(2009629,68,43,12,13,'Hurma dalları alarak Onu karşılamaya çıktılar. ‹‹Hozana! Rabbin adıyla gelene, İsrailin Kralına övgüler olsun!›› diye bağırıyorlardı.'),
(2009630,68,43,12,14,'İsa bir sıpa bulup üzerine bindi. Yazılmış olduğu gibi, ‹‹Korkma, ey Siyon kızı! İşte, Kralın sıpaya binmiş geliyor.››'),
(2009631,68,43,12,16,'Öğrencileri ilkin bunları anlamadılar. Ama İsa yüceltildikten sonra bu sözlerin Onun hakkında yazıldığını, halkın bunları Onun için yaptığını hatırladılar.'),
(2009632,68,43,12,17,'Lazarı mezardan çağırıp ölümden dirilttiği sırada İsayla birlikte bulunan kalabalık buna tanıklık etti.'),
(2009633,68,43,12,18,'İsanın bu doğaüstü belirtiyi gerçekleştirdiğini duyan halk Onu karşılamaya çıktı.'),
(2009634,68,43,12,19,'Ferisiler ise birbirlerine, ‹‹Görüyorsunuz, elinizden hiçbir şey gelmiyor. Bütün dünya Onun peşine takıldı›› dediler.'),
(2009635,68,43,12,20,'Bayramda tapınmak üzere Yeruşalime gidenler arasında bazı Grekler vardı.'),
(2009636,68,43,12,21,'Bunlar, Celilenin Beytsayda Kentinden olan Filipusa gelerek, ‹‹Efendimiz, İsayı görmek istiyoruz›› diye rica ettiler.'),
(2009637,68,43,12,22,'Filipus gitti, bunu Andreasa bildirdi. Andreas ve Filipus da gidip İsaya haber verdiler.'),
(2009638,68,43,12,23,'İsa, ‹‹İnsanoğlunun yüceltileceği saat geldi›› diye karşılık verdi.'),
(2009639,68,43,12,24,'‹‹Size doğrusunu söyleyeyim, buğday tanesi toprağa düşüp ölmedikçe yalnız kalır. Ama ölürse çok ürün verir.'),
(2009640,68,43,12,25,'Canını seven onu yitirir. Ama bu dünyada canını gözden çıkaran onu sonsuz yaşam için koruyacaktır.'),
(2009641,68,43,12,26,'Bana hizmet etmek isteyen, ardımdan gelsin. Ben neredeysem bana hizmet eden de orada olacak. Baba, bana hizmet edeni onurlandıracaktır.'),
(2009642,68,43,12,27,'Şimdi yüreğim sıkılıyor, ne diyeyim? ‹Baba, beni bu saatten kurtar› mı diyeyim? Ama ben bu amaç için bu saate geldim.'),
(2009643,68,43,12,28,'Baba, adını yücelt!›› Bunun üzerine gökten bir ses geldi: ‹‹Adımı yücelttim ve yine yücelteceğim.››'),
(2009644,68,43,12,29,'Orada duran ve bunu işiten kalabalık, ‹‹Gök gürledi›› dedi. Başkaları, ‹‹Bir melek Onunla konuştu›› dedi.'),
(2009645,68,43,12,30,'İsa, ‹‹Bu ses benim için değil, sizin içindi›› dedi.'),
(2009646,68,43,12,31,'‹‹Bu dünya şimdi yargılanıyor. Bu dünyanın egemeni şimdi dışarı atılacak.'),
(2009647,68,43,12,32,'Ben yerden yukarı kaldırıldığım zaman bütün insanları kendime çekeceğim.››'),
(2009648,68,43,12,33,'İsa bunu, nasıl öleceğini belirtmek için söylüyordu.'),
(2009649,68,43,12,34,'Kalabalık Ona şöyle karşılık verdi: ‹‹Kutsal Yasadan öğrendiğimize göre Mesih sonsuza dek kalacaktır. Nasıl oluyor da sen, ‹İnsanoğlu yukarı kaldırılmalıdır› diyorsun? Kimdir bu İnsanoğlu?››'),
(2009650,68,43,12,35,'İsa, ‹‹Işık kısa bir süre daha aranızdadır›› dedi. ‹‹Karanlıkta kalmamak için ışığınız varken yürüyün. Karanlıkta yürüyen nereye gittiğini bilmez.'),
(2009651,68,43,12,36,'Sizde ışık varken ışığa iman edin ki, ışık oğulları olasınız.›› İsa bu sözleri söyledikten sonra uzaklaşıp onlardan gizlendi.'),
(2009652,68,43,12,37,'Gözleri önünde bunca doğaüstü belirti gerçekleştirdiği halde Ona iman etmediler.'),
(2009653,68,43,12,38,'Bütün bunlar Peygamber Yeşayanın söylediği şu söz yerine gelsin diye oldu: ‹‹Rab, verdiğimiz habere kim inandı? Rabbin gücü kime açıklandı?››'),
(2009654,68,43,12,39,'İşte bu yüzden iman edemiyorlardı. Nitekim Yeşaya başka bir yerde de şöyle demişti: ‹‹Tanrı onların gözlerini kör etti Ve yüreklerini nasırlaştırdı. Öyle ki, gözleri görmesin, Yürekleri anlamasın Ve bana dönmesinler. Dönselerdi, onları iyileştirirdim.››'),
(2009655,68,43,12,41,'Bunları söyleyen Yeşaya, İsanın yüceliğini görmüş ve Onun hakkında konuşmuştu.'),
(2009656,68,43,12,42,'Bununla birlikte, önderlerin bile birçoğu İsaya iman etti. Ama Ferisiler yüzünden, havra dışı edilmemek için iman ettiklerini açıkça söylemediler.'),
(2009657,68,43,12,43,'Çünkü insandan gelen övgüyü, Tanrıdan gelen övgüden daha çok seviyorlardı.'),
(2009658,68,43,12,44,'İsa yüksek sesle, ‹‹Bana iman eden bana değil, beni gönderene iman etmiş olur›› dedi.'),
(2009659,68,43,12,45,'‹‹Beni gören beni göndereni de görür.'),
(2009660,68,43,12,46,'Bana iman eden hiç kimse karanlıkta kalmasın diye, dünyaya ışık olarak geldim.'),
(2009661,68,43,12,47,'Sözlerimi işitip de onlara uymayanı ben yargılamam. Çünkü ben dünyayı yargılamaya değil, dünyayı kurtarmaya geldim.'),
(2009662,68,43,12,48,'Beni reddeden ve sözlerimi kabul etmeyen kişiyi yargılayacak biri var. O kişiyi son günde yargılayacak olan, söylediğim sözdür.'),
(2009663,68,43,12,49,'Çünkü ben kendiliğimden konuşmadım. Beni gönderen Babanın kendisi ne söylemem ve ne konuşmam gerektiğini bana buyurdu.'),
(2009664,68,43,12,50,'O''nun buyruğunun sonsuz yaşam olduğunu biliyorum. Bunun için ne söylüyorsam, Baba''nın bana söylediği gibi söylüyorum.››'),
(2009665,68,43,13,1,'Fısıh Bayramından önceydi. İsa, bu dünyadan ayrılıp Babaya gideceği saatin geldiğini biliyordu. Dünyada kendisine ait olanları hep sevmişti; sonuna kadar da sevdi.'),
(2009666,68,43,13,2,'Akşam yemeği sırasında İblis, Simun İskariotun oğlu Yahudanın yüreğine İsaya ihanet etme isteğini koymuştu bile.'),
(2009667,68,43,13,3,'İsa, Babanın her şeyi kendisine teslim ettiğini, kendisinin Tanrıdan çıkıp geldiğini ve Tanrıya döneceğini biliyordu.'),
(2009668,68,43,13,4,'Yemekten kalktı, üstlüğünü bir yana koydu, bir havlu alıp beline doladı.'),
(2009669,68,43,13,5,'Sonra bir leğene su doldurup öğrencilerin ayaklarını yıkamaya ve beline doladığı havluyla kurulamaya başladı.'),
(2009670,68,43,13,6,'İsa, Simun Petrusa geldi. Simun, ‹‹Ya Rab, ayaklarımı sen mi yıkayacaksın?›› dedi.'),
(2009671,68,43,13,7,'İsa ona şu yanıtı verdi: ‹‹Ne yaptığımı şimdi anlayamazsın, ama sonra anlayacaksın.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009672,68,43,13,8,'Petrus, ‹‹Benim ayaklarımı asla yıkamayacaksın!›› dedi. İsa, ‹‹Yıkamazsam yanımda yerin olmaz›› diye yanıtladı.'),
(2009673,68,43,13,9,'Simun Petrus, ‹‹Ya Rab, o halde yalnız ayaklarımı değil, ellerimi ve başımı da yıka!›› dedi.'),
(2009674,68,43,13,10,'İsa ona dedi ki, ‹‹Yıkanmış olan tamamen temizdir; ayaklarının yıkanmasından başka şeye ihtiyacı yoktur. Sizler temizsiniz, ama hepiniz değil.››'),
(2009675,68,43,13,11,'İsa, kendisine kimin ihanet edeceğini biliyordu. Bu nedenle, ‹‹Hepiniz temiz değilsiniz›› demişti.'),
(2009676,68,43,13,12,'Onların ayaklarını yıkadıktan sonra giyinip yine sofraya oturdu. ‹‹Size ne yaptığımı anlıyor musunuz?›› dedi.'),
(2009677,68,43,13,13,'‹‹Siz beni Öğretmen ve Rab diye çağırıyorsunuz. Doğru söylüyorsunuz, öyleyim.'),
(2009678,68,43,13,14,'Ben Rab ve Öğretmen olduğum halde ayaklarınızı yıkadım; öyleyse, sizler de birbirinizin ayaklarını yıkamalısınız.'),
(2009679,68,43,13,15,'Size yaptığımın aynısını yapmanız için bir örnek gösterdim.'),
(2009680,68,43,13,16,'Size doğrusunu söyleyeyim, köle efendisinden, elçi de kendisini gönderenden üstün değildir.'),
(2009681,68,43,13,17,'Bildiğiniz bu şeyleri yaparsanız, ne mutlu size!››'),
(2009682,68,43,13,18,'‹‹Hepiniz için söylemiyorum, ben seçtiklerimi bilirim. Ama, ‹Ekmeğimi yiyen bana ihanet etti› diyen Kutsal Yazının yerine gelmesi için böyle olacak.'),
(2009683,68,43,13,19,'Size şimdiden, bunlar olmadan önce söylüyorum ki, bunlar olunca, benim O olduğuma inanasınız.'),
(2009684,68,43,13,20,'Size doğrusunu söyleyeyim, benim gönderdiğim herhangi bir kimseyi kabul eden beni kabul etmiş olur. Beni kabul eden de beni göndereni kabul etmiş olur.››'),
(2009685,68,43,13,21,'İsa bunları söyledikten sonra ruhunda derin bir sıkıntı duydu. Açıkça konuşarak, ‹‹Size doğrusunu söyleyeyim, sizden biri bana ihanet edecek›› dedi.'),
(2009686,68,43,13,22,'Öğrenciler, kimden söz ettiğini merak ederek birbirlerine baktılar.'),
(2009687,68,43,13,23,'Öğrencilerinden biri İsanın göğsüne yaslanmıştı. İsa onu severdi.'),
(2009688,68,43,13,24,'Simun Petrus bu öğrenciye, kimden söz ettiğini İsaya sorması için işaret etti.'),
(2009689,68,43,13,25,'O da İsanın göğsüne yaslanmış durumda, ‹‹Ya Rab, kimdir o?›› diye sordu.'),
(2009690,68,43,13,26,'İsa, ‹‹Lokmayı sahana batırıp kime verirsem odur›› diye yanıtladı. Sonra lokmayı batırıp Simun İskariotun oğlu Yahudaya verdi.'),
(2009691,68,43,13,27,'Yahuda lokmayı alır almaz Şeytan onun içine girdi. İsa da ona, ‹‹Yapacağını tez yap!›› dedi.'),
(2009692,68,43,13,28,'Sofrada oturanların hiçbiri, İsanın ona bu sözleri neden söylediğini anlamadı.'),
(2009693,68,43,13,29,'Para kutusu Yahudada olduğundan, bazıları İsanın ona, ‹‹Bayram için bize gerekli şeyleri al›› ya da, ‹‹Yoksullara bir şey ver›› demek istediğini sandılar.'),
(2009694,68,43,13,30,'Yahuda lokmayı aldıktan hemen sonra dışarı çıktı. Gece olmuştu.'),
(2009695,68,43,13,31,'Yahuda dışarı çıkınca İsa, ‹‹İnsanoğlu şimdi yüceltildi›› dedi. ‹‹Tanrı da Onda yüceltildi.'),
(2009696,68,43,13,32,'Tanrı Onda yüceltildiğine göre, Tanrı da Onu kendinde yüceltecek. Hem de hemen yüceltecektir.'),
(2009697,68,43,13,33,'Çocuklar! Kısa bir süre daha sizinleyim. Beni arayacaksınız, ama Yahudilere söylediğim gibi, şimdi size de söylüyorum, benim gideceğim yere siz gelemezsiniz.'),
(2009698,68,43,13,34,'Size yeni bir buyruk veriyorum: Birbirinizi sevin. Sizi sevdiğim gibi siz de birbirinizi sevin.'),
(2009699,68,43,13,35,'Birbirinize sevginiz olursa, herkes bununla benim öğrencilerim olduğunuzu anlayacaktır.››'),
(2009700,68,43,13,36,'Simun Petrus Ona, ‹‹Ya Rab, nereye gidiyorsun?›› diye sordu. İsa, ‹‹Gideceğim yere şimdi ardımdan gelemezsin, ama sonra geleceksin›› diye yanıtladı.'),
(2009701,68,43,13,37,'Petrus, ‹‹Ya Rab, neden şimdi senin ardından gelemeyeyim? Senin için canımı veririm!›› dedi.'),
(2009702,68,43,13,38,'İsa şöyle yanıtladı: ‹‹Benim için canını mı vereceksin? Sana doğrusunu söyleyeyim, horoz ötmeden beni üç kez inkâr edeceksin.››'),
(2009703,68,43,14,1,'‹‹Yüreğiniz sıkılmasın. Tanrıya iman edin, bana da iman edin.'),
(2009704,68,43,14,2,'Babamın evinde kalacak çok yer var. Öyle olmasa size söylerdim. Çünkü size yer hazırlamaya gidiyorum.'),
(2009705,68,43,14,3,'Gider ve size yer hazırlarsam, siz de benim bulunduğum yerde olasınız diye yine gelip sizi yanıma alacağım.'),
(2009706,68,43,14,4,'Benim gideceğim yerin yolunu biliyorsunuz.››'),
(2009707,68,43,14,5,'Tomas, ‹‹Ya Rab, senin nereye gideceğini bilmiyoruz, yolu nasıl bilebiliriz?›› dedi.'),
(2009708,68,43,14,6,'İsa, ‹‹Yol, gerçek ve yaşam Benim›› dedi. ‹‹Benim aracılığım olmadan Babaya kimse gelemez.'),
(2009709,68,43,14,7,'Beni tanısaydınız, Babamı da tanırdınız. Artık Onu tanıyorsunuz, Onu gördünüz.››'),
(2009710,68,43,14,8,'Filipus, ‹‹Ya Rab, bize Babayı göster, bu bize yeter›› dedi.'),
(2009711,68,43,14,9,'İsa, ‹‹Filipus›› dedi, ‹‹Bunca zamandır sizinle birlikteyim. Beni daha tanımadın mı? Beni görmüş olan, Babayı görmüştür. Sen nasıl, ‹Bize Babayı göster› diyorsun?'),
(2009712,68,43,14,10,'Benim Babada, Babanın da bende olduğuna inanmıyor musun? Size söylediğim sözleri kendiliğimden söylemiyorum, ama bende yaşayan Baba kendi işlerini yapıyor.'),
(2009713,68,43,14,11,'Bana iman edin; ben Babadayım, Baba da bendedir. Hiç değilse bu işlerden dolayı iman edin.'),
(2009714,68,43,14,12,'Size doğrusunu söyleyeyim, benim yaptığım işleri, bana iman eden de yapacak; hatta daha büyüklerini yapacaktır. Çünkü ben Babaya gidiyorum.'),
(2009715,68,43,14,13,'Baba Oğulda yüceltilsin diye, benim adımla dilediğiniz her şeyi yapacağım.'),
(2009716,68,43,14,14,'Benim adımla benden ne dilerseniz yapacağım.››'),
(2009717,68,43,14,15,'‹‹Beni seviyorsanız, buyruklarımı yerine getirirsiniz.'),
(2009718,68,43,14,16,'Ben de Babadan dileyeceğim. O sonsuza dek sizinle birlikte olsun diye size başka bir Yardımcı, Gerçeğin Ruhunu verecek. Dünya Onu kabul edemez. Çünkü Onu ne görür, ne de tanır. Siz Onu tanıyorsunuz. Çünkü O aranızda yaşıyor ve içinizde olacaktır.'),
(2009719,68,43,14,18,'Sizi öksüz bırakmayacağım, size geri döneceğim.'),
(2009720,68,43,14,19,'Az sonra dünya artık beni görmeyecek, ama siz beni göreceksiniz. Ben yaşadığım için siz de yaşayacaksınız.'),
(2009721,68,43,14,20,'O gün anlayacaksınız ki, ben Babamdayım, siz bendesiniz, ben de sizdeyim.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009722,68,43,14,21,'Kim buyruklarımı bilir ve yerine getirirse, işte beni seven odur. Beni seveni Babam da sevecektir. Ben de onu seveceğim ve kendimi ona göstereceğim.››'),
(2009723,68,43,14,22,'Yahuda -İskariot değil- Ona, ‹‹Ya Rab, nasıl olur da kendini dünyaya göstermeyip bize göstereceksin?›› diye sordu.'),
(2009724,68,43,14,23,'İsa ona şu karşılığı verdi: ‹‹Beni seven sözüme uyar, Babam da onu sever. Biz de ona gelir, onunla birlikte yaşarız.'),
(2009725,68,43,14,24,'Beni sevmeyen, sözlerime uymaz. İşittiğiniz söz benim değil, beni gönderen Babanındır.'),
(2009726,68,43,14,25,'‹‹Ben daha aranızdayken size bunları söyledim.'),
(2009727,68,43,14,26,'Ama Babanın benim adımla göndereceği Yardımcı, Kutsal Ruh, size her şeyi öğretecek, bütün söylediklerimi size hatırlatacak.'),
(2009728,68,43,14,27,'Size esenlik bırakıyorum, size kendi esenliğimi veriyorum. Ben size dünyanın verdiği gibi vermiyorum. Yüreğiniz sıkılmasın ve korkmasın.'),
(2009729,68,43,14,28,'Size, ‹Gidiyorum, ama yanınıza döneceğim› dediğimi işittiniz. Beni sevseydiniz, Babaya gideceğim için sevinirdiniz. Çünkü Baba benden üstündür.'),
(2009730,68,43,14,29,'Bunları size şimdiden, her şey olup bitmeden önce söyledim. Öyle ki, bunlar olunca inanasınız.'),
(2009731,68,43,14,30,'Artık sizinle uzun uzun konuşmayacağım. Çünkü bu dünyanın egemeni geliyor. Onun benim üzerimde hiçbir yetkisi yoktur.'),
(2009732,68,43,14,31,'Ama dünyanın, Baba''yı sevdiğimi ve Baba''nın bana buyurduğu her şeyi yerine getirdiğimi anlamasını istiyorum. Haydi kalkın, buradan gidelim.››'),
(2009733,68,43,15,1,'‹‹Ben gerçek asmayım ve Babam bağcıdır.'),
(2009734,68,43,15,2,'Bende meyve vermeyen her çubuğu kesip atar, meyve veren her çubuğu ise daha çok meyve versin diye budayıp temizler.'),
(2009735,68,43,15,3,'Size söylediğim sözle siz şimdiden temizsiniz.'),
(2009736,68,43,15,4,'Bende kalın, ben de sizde kalayım. Çubuk asmada kalmazsa kendiliğinden meyve veremez. Bunun gibi, siz de bende kalmazsanız meyve veremezsiniz.'),
(2009737,68,43,15,5,'Ben asmayım, siz çubuklarsınız. Bende kalan ve benim kendisinde kaldığım kişi çok meyve verir. Bensiz hiçbir şey yapamazsınız.'),
(2009738,68,43,15,6,'Bir kimse bende kalmazsa, çubuk gibi dışarı atılır ve kurur. Böylelerini toplar, ateşe atıp yakarlar.'),
(2009739,68,43,15,7,'Eğer bende kalırsanız ve sözlerim sizde kalırsa, ne isterseniz dileyin, size verilecektir.'),
(2009740,68,43,15,8,'Babam çok meyve vermenizle yüceltilir. Böylelikle öğrencilerim olursunuz.'),
(2009741,68,43,15,9,'‹‹Babanın beni sevdiği gibi, ben de sizi sevdim. Benim sevgimde kalın.'),
(2009742,68,43,15,10,'Eğer buyruklarımı yerine getirirseniz sevgimde kalırsınız, tıpkı benim de Babamın buyruklarını yerine getirdiğim ve sevgisinde kaldığım gibi...'),
(2009743,68,43,15,11,'Bunları size, sevincim sizde olsun ve sevinciniz tamamlansın diye söyledim.'),
(2009744,68,43,15,12,'Benim buyruğum şudur: Sizi sevdiğim gibi birbirinizi sevin.'),
(2009745,68,43,15,13,'Hiç kimsede, insanın, dostları uğruna canını vermesinden daha büyük bir sevgi yoktur.'),
(2009746,68,43,15,14,'Size buyurduklarımı yaparsanız, benim dostlarım olursunuz.'),
(2009747,68,43,15,15,'Artık size kul demiyorum. Çünkü kul efendisinin ne yaptığını bilmez. Size dost dedim. Çünkü Babamdan bütün işittiklerimi size bildirdim.'),
(2009748,68,43,15,16,'Siz beni seçmediniz, ben sizi seçtim. Gidip meyve veresiniz, meyveniz de kalıcı olsun diye sizi ben atadım. Öyle ki, benim adımla Babadan ne dilerseniz size versin.'),
(2009749,68,43,15,17,'Size şu buyruğu veriyorum: Birbirinizi sevin!››'),
(2009750,68,43,15,18,'‹‹Dünya sizden nefret ederse, sizden önce benden nefret etmiş olduğunu bilin.'),
(2009751,68,43,15,19,'Dünyadan olsaydınız, dünya kendisine ait olanı severdi. Ne var ki, dünyanın değilsiniz; ben sizi dünyadan seçtim. Bunun için dünya sizden nefret ediyor.'),
(2009752,68,43,15,20,'Size söylediğim sözü hatırlayın: ‹Köle efendisinden üstün değildir.› Bana zulmettilerse, size de zulmedecekler. Benim sözüme uydularsa, sizinkine de uyacaklar.'),
(2009753,68,43,15,21,'Bütün bunları size benim adımdan ötürü yapacaklar. Çünkü beni göndereni tanımıyorlar.'),
(2009754,68,43,15,22,'Eğer gelmemiş ve onlara söylememiş olsaydım, günahları olmazdı; ama şimdi günahları için özürleri yoktur.'),
(2009755,68,43,15,23,'Benden nefret eden, Babamdan da nefret eder.'),
(2009756,68,43,15,24,'Başka hiç kimsenin yapmadığı işleri onların arasında yapmamış olsaydım, günahları olmazdı. Şimdiyse yaptıklarımı gördükleri halde hem benden hem de Babamdan nefret ettiler.'),
(2009757,68,43,15,25,'Bu, yasalarında yazılı, ‹Yok yere benden nefret ettiler› sözü yerine gelsin diye oldu.'),
(2009758,68,43,15,26,'‹‹Babadan size göndereceğim Yardımcı, yani Babadan çıkan Gerçeğin Ruhu geldiği zaman, bana tanıklık edecek.'),
(2009759,68,43,15,27,'Siz de tanıklık edeceksiniz. Çünkü başlangıçtan beri benimle birliktesiniz.'),
(2009760,68,43,16,1,'‹‹Bunları size, sendeleyip düşmeyesiniz diye söyledim.'),
(2009761,68,43,16,2,'Sizi havra dışı edecekler. Evet, öyle bir saat geliyor ki, sizi öldüren herkes Tanrıya hizmet ettiğini sanacak.'),
(2009762,68,43,16,3,'Bunları, Babayı ve beni tanımadıkları için yapacaklar.'),
(2009763,68,43,16,4,'Bunları size şimdiden bildiriyorum. Öyle ki, saati gelince bunları size söylediğimi hatırlayasınız. Başlangıçta bunları size söylemedim. Çünkü sizinle birlikteydim.››'),
(2009764,68,43,16,5,'‹‹Şimdiyse beni gönderenin yanına gidiyorum. Ne var ki, içinizden hiçbiri bana, ‹Nereye gidiyorsun?› diye sormuyor.'),
(2009765,68,43,16,6,'Ama bunları söylediğim için yüreğiniz kederle doldu.'),
(2009766,68,43,16,7,'Size gerçeği söylüyorum, benim gidişim sizin yararınızadır. Gitmezsem, Yardımcı size gelmez. Ama gidersem, Onu size gönderirim.'),
(2009767,68,43,16,8,'O gelince günah, doğruluk ve gelecek yargı konusunda dünyayı suçlu olduğuna ikna edecektir:'),
(2009768,68,43,16,9,'Günah konusunda, çünkü bana iman etmezler;'),
(2009769,68,43,16,10,'doğruluk konusunda, çünkü Babaya gidiyorum, artık beni görmeyeceksiniz;'),
(2009770,68,43,16,11,'yargı konusunda, çünkü bu dünyanın egemeni yargılanmış bulunuyor.'),
(2009771,68,43,16,12,'‹‹Size daha çok söyleyeceklerim var, ama şimdi bunlara dayanamazsınız.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009772,68,43,16,13,'Ne var ki O, yani Gerçeğin Ruhu gelince, sizi tüm gerçeğe yöneltecek. Çünkü kendiliğinden konuşmayacak, yalnız duyduklarını söyleyecek ve gelecekte olacakları size bildirecek.'),
(2009773,68,43,16,14,'O beni yüceltecek. Çünkü benim olandan alıp size bildirecek.'),
(2009774,68,43,16,15,'Babanın nesi varsa benimdir. ‹Benim olandan alıp size bildirecek› dememin nedeni budur.'),
(2009775,68,43,16,16,'‹‹Kısa süre sonra beni artık görmeyeceksiniz; yine kısa süre sonra beni göreceksiniz.››'),
(2009776,68,43,16,17,'Öğrencilerinden bazıları birbirlerine, ‹‹Ne demek istiyor?›› diye sordular. ‹‹ ‹Kısa süre sonra beni görmeyeceksiniz; yine kısa süre sonra beni göreceksiniz› diyor. Ayrıca, ‹Çünkü Babaya gidiyorum› diyor.››'),
(2009777,68,43,16,18,'Onun için, ‹‹Bu ‹kısa süre› dediği nedir? Söylediklerini anlamıyoruz›› deyip durdular.'),
(2009778,68,43,16,19,'İsa kendisine soru sormak istediklerini anladı. Onlara dedi ki, ‹‹ ‹Kısa süre sonra beni görmeyeceksiniz; yine kısa süre sonra beni göreceksiniz› dememi mi tartışıyorsunuz?'),
(2009779,68,43,16,20,'Size doğrusunu söyleyeyim, siz ağlayıp yas tutacaksınız, dünya ise sevinecektir. Kederleneceksiniz, ama kederiniz sevince dönüşecek.'),
(2009780,68,43,16,21,'Kadın doğum yapacağı zaman ağrı çeker. Çünkü saati gelmiştir. Ama doğurunca, dünyaya bir çocuk getirmenin sevinciyle çektiği acıyı unutur.'),
(2009781,68,43,16,22,'Bunun gibi, siz de şimdi kederleniyorsunuz, ama sizi yine göreceğim. O zaman yürekten sevineceksiniz. Sevincinizi kimse sizden alamaz.'),
(2009782,68,43,16,23,'O gün bana hiçbir şey sormayacaksınız. Size doğrusunu söyleyeyim, benim adımla Babadan ne dilerseniz, size verecektir.'),
(2009783,68,43,16,24,'Şimdiye dek benim adımla bir şey dilemediniz. Dileyin, alacaksınız. Öyle ki, sevinciniz tam olsun.'),
(2009784,68,43,16,25,'‹‹Size bunları örneklerle anlattım. Öyle bir saat geliyor ki, artık örneklerle konuşmayacağım; Babayı size açıkça tanıtacağım.'),
(2009785,68,43,16,26,'O gün dileyeceğinizi benim adımla dileyeceksiniz. Sizin için Babadan istekte bulunacağımı söylemiyorum.'),
(2009786,68,43,16,27,'Çünkü beni sevdiğiniz ve Babadan çıkıp geldiğime iman ettiğiniz için Babanın kendisi sizi seviyor.'),
(2009787,68,43,16,28,'Ben Babadan çıkıp dünyaya geldim. Şimdi dünyayı bırakıp Babaya dönüyorum.››'),
(2009788,68,43,16,29,'Öğrencileri, ‹‹İşte, şimdi açıkça konuşuyorsun, hiç örnek kullanmıyorsun›› dediler.'),
(2009789,68,43,16,30,'‹‹Şimdi senin her şeyi bildiğini anlıyoruz. Kimsenin sana soru sormasına gerek yok. Tanrıdan geldiğine bunun için iman ediyoruz.››'),
(2009790,68,43,16,31,'İsa onlara, ‹‹Şimdi iman ediyor musunuz?›› diye karşılık verdi.'),
(2009791,68,43,16,32,'‹‹İşte, hepinizin evlerinize gitmek üzere dağılacağınız ve beni yalnız bırakacağınız saat geliyor, geldi bile. Ama ben yalnız değilim, Baba benimle birliktedir.'),
(2009792,68,43,16,33,'Bunları size, bende esenliğiniz olsun diye söyledim. Dünyada sıkıntınız olacak. Ama cesur olun, ben dünyayı yendim!››'),
(2009793,68,43,17,1,'İsa bunları söyledikten sonra, gözlerini gökyüzüne kaldırıp şöyle dedi: ‹‹Baba, saat geldi. Oğlunu yücelt ki, Oğul da seni yüceltsin.'),
(2009794,68,43,17,2,'Çünkü sen Ona bütün insanlık üzerinde yetki verdin. Öyle ki, Ona verdiklerinin hepsine sonsuz yaşam versin.'),
(2009795,68,43,17,3,'Sonsuz yaşam, tek gerçek Tanrı olan seni ve gönderdiğin İsa Mesihi tanımalarıdır.'),
(2009796,68,43,17,4,'Yapmam için bana verdiğin işi tamamlamakla seni yeryüzünde yücelttim.'),
(2009797,68,43,17,5,'Baba, dünya var olmadan önce ben senin yanındayken sahip olduğum yücelikle şimdi beni yanında yücelt.'),
(2009798,68,43,17,6,'‹‹Dünyadan bana verdiğin insanlara senin adını açıkladım. Onlar senindiler, bana verdin ve senin sözüne uydular.'),
(2009799,68,43,17,7,'Bana verdiğin her şeyin senden olduğunu şimdi biliyorlar.'),
(2009800,68,43,17,8,'Çünkü bana ilettiğin sözleri onlara ilettim, onlar da kabul ettiler. Senden çıkıp geldiğimi gerçekten anladılar, beni senin gönderdiğine iman ettiler.'),
(2009801,68,43,17,9,'Onlar için istekte bulunuyorum. Dünya için değil, bana verdiğin kimseler için istekte bulunuyorum. Çünkü onlar senindir.'),
(2009802,68,43,17,10,'Benim olan her şey senindir, seninkiler de benimdir. Ben onlarda yüceltildim.'),
(2009803,68,43,17,11,'Ben artık dünyada değilim, ama onlar dünyadalar. Ben sana geliyorum. Kutsal Baba, onları bana verdiğin kendi adınla koru ki, bizim gibi bir olsunlar.'),
(2009804,68,43,17,12,'Kendileriyle birlikte olduğum sürece, bana verdiğin kendi adınla onları esirgeyip korudum. Kutsal Yazı yerine gelsin diye, mahva giden adamdan başka içlerinden hiçbiri mahvolmadı.'),
(2009805,68,43,17,13,'‹‹İşte şimdi sana geliyorum. Sevincimin onlarda tamamlanması için bunları ben dünyadayken söylüyorum.'),
(2009806,68,43,17,14,'Ben onlara senin sözünü ilettim, dünya ise onlardan nefret etti. Çünkü ben dünyadan olmadığım gibi, onlar da dünyadan değiller.'),
(2009807,68,43,17,15,'Onları dünyadan uzaklaştırmanı değil, kötü olandan korumanı istiyorum.'),
(2009808,68,43,17,16,'Ben dünyadan olmadığım gibi, onlar da dünyadan değiller.'),
(2009809,68,43,17,17,'Onları gerçekle kutsal kıl. Senin sözün gerçektir.'),
(2009810,68,43,17,18,'Sen beni dünyaya gönderdiğin gibi, ben de onları dünyaya gönderdim.'),
(2009811,68,43,17,19,'Onlar da gerçekle kutsal kılınsınlar diye kendimi onların uğruna adıyorum.'),
(2009812,68,43,17,20,'‹‹Yalnız onlar için değil, onların sözüyle bana iman edenler için de istekte bulunuyorum, hepsi bir olsunlar. Baba, senin bende olduğun ve benim sende olduğum gibi, onlar da bizde olsunlar. Dünya da beni senin gönderdiğine iman etsin.'),
(2009813,68,43,17,22,'Bana verdiğin yüceliği onlara verdim. Öyle ki, bizim bir olduğumuz gibi bir olsunlar.'),
(2009814,68,43,17,23,'Ben onlarda, sen bende olmak üzere tam bir birlik içinde bulunsunlar ki, dünya beni senin gönderdiğini, beni sevdiğin gibi onları da sevdiğini anlasın.'),
(2009815,68,43,17,24,'Baba, bana verdiklerinin de bulunduğum yerde benimle birlikte olmalarını ve benim yüceliğimi, bana verdiğin yüceliği görmelerini istiyorum. Çünkü dünyanın kuruluşundan önce sen beni sevdin.'),
(2009816,68,43,17,25,'Adil Baba, dünya seni tanımıyor, ama ben seni tanıyorum. Bunlar da beni senin gönderdiğini biliyorlar.'),
(2009817,68,43,17,26,'Bana beslediğin sevgi onlarda olsun, ben de onlarda olayım diye senin adını onlara bildirdim ve bildirmeye devam edeceğim.››'),
(2009818,68,43,18,1,'İsa bu sözleri söyledikten sonra öğrencileriyle birlikte dışarı çıkıp Kidron Vadisinin ötesine geçti. Orada bir bahçe vardı. İsayla öğrencileri bu bahçeye girdiler.'),
(2009819,68,43,18,2,'Ona ihanet eden Yahuda da burayı biliyordu. Çünkü İsa, öğrencileriyle orada sık sık buluşurdu.'),
(2009820,68,43,18,3,'Böylece Yahuda yanına bir bölük askerle başkâhinlerin ve Ferisilerin gönderdiği görevlileri alarak oraya geldi. Onların ellerinde fenerler, meşaleler ve silahlar vardı.'),
(2009821,68,43,18,4,'İsa, başına geleceklerin hepsini biliyordu. Öne çıkıp onlara, ‹‹Kimi arıyorsunuz?›› diye sordu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009822,68,43,18,5,'‹‹Nasıralı İsayı›› diye karşılık verdiler. İsa onlara, ‹‹Benim›› dedi. Ona ihanet eden Yahuda da onlarla birlikte duruyordu.'),
(2009823,68,43,18,6,'İsa, ‹‹Benim›› deyince gerileyip yere düştüler.'),
(2009824,68,43,18,7,'Bunun üzerine İsa onlara yine, ‹‹Kimi arıyorsunuz?›› diye sordu. ‹‹Nasıralı İsayı›› dediler.'),
(2009825,68,43,18,8,'İsa, ‹‹Size söyledim, benim›› dedi. ‹‹Eğer beni arıyorsanız, bunları bırakın gitsinler.››'),
(2009826,68,43,18,9,'Kendisinin daha önce söylediği, ‹‹Senin bana verdiklerinden hiçbirini yitirmedim›› şeklindeki sözü yerine gelsin diye böyle konuştu.'),
(2009827,68,43,18,10,'Simun Petrus yanında taşıdığı kılıcı çekti, başkâhinin Malkus adındaki kölesine vurup sağ kulağını kopardı.'),
(2009828,68,43,18,11,'İsa Petrusa, ‹‹Kılıcını kınına koy! Babanın bana verdiği kâseden içmeyeyim mi?›› dedi.'),
(2009829,68,43,18,12,'Bunun üzerine komutanla buyruğundaki asker bölüğü ve Yahudi görevliler İsayı tutup bağladılar.'),
(2009830,68,43,18,13,'Onu önce, o yıl başkâhin olan Kayafanın kayınbabası Hanana götürdüler.'),
(2009831,68,43,18,14,'Halkın uğruna bir tek adamın ölmesinin daha uygun olacağını Yahudi yetkililere telkin eden Kayafa idi.'),
(2009832,68,43,18,15,'Simun Petrusla başka bir öğrenci İsanın ardından gidiyorlardı. O öğrenci başkâhinin tanıdığı olduğu için İsayla birlikte başkâhinin avlusuna girdi.'),
(2009833,68,43,18,16,'Petrus ise dışarıda, kapının yanında duruyordu. Başkâhinin tanıdığı öğrenci dışarı çıkıp kapıcı kızla konuştu ve Petrusu içeri getirdi.'),
(2009834,68,43,18,17,'Kapıcı kız Petrusa, ‹‹Sen de bu adamın öğrencilerinden değil misin?›› diye sordu. Petrus, ‹‹Hayır, değilim›› dedi.'),
(2009835,68,43,18,18,'Hava soğuk olduğu için köleler ve nöbetçiler yaktıkları kömür ateşinin çevresinde durmuş ısınıyorlardı. Petrus da onlarla birlikte ayakta ısınıyordu.'),
(2009836,68,43,18,19,'Başkâhin İsaya, öğrencileri ve öğretisiyle ilgili sorular sordu.'),
(2009837,68,43,18,20,'İsa onu şöyle yanıtladı: ‹‹Ben söylediklerimi dünyaya açıkça söyledim. Her zaman bütün Yahudilerin toplandıkları havralarda ve tapınakta öğrettim. Gizli hiçbir şey söylemedim.'),
(2009838,68,43,18,21,'Beni neden sorguya çekiyorsun? Konuştuklarımı işitenlerden sor. Onlar ne söylediğimi biliyorlar.››'),
(2009839,68,43,18,22,'İsa bunları söyleyince, yanında duran görevlilerden biri, ‹‹Başkâhine nasıl böyle karşılık verirsin?›› diyerek Ona bir tokat attı.'),
(2009840,68,43,18,23,'İsa ona, ‹‹Eğer yanlış bir şey söyledimse, yanlışımı göster!›› diye yanıtladı. ‹‹Ama söylediklerim doğruysa, niçin bana vuruyorsun?››'),
(2009841,68,43,18,24,'Bunun üzerine Hanan, Onu bağlı olarak başkâhin Kayafaya gönderdi.'),
(2009842,68,43,18,25,'Simun Petrus hâlâ ateşin yanında durmuş ısınıyordu. Ona, ‹‹Sen de Onun öğrencilerinden değil misin?›› dediler. ‹‹Hayır, değilim›› diyerek inkâr etti.'),
(2009843,68,43,18,26,'Başkâhinin kölelerinden biri, Petrusun, kulağını kestiği adamın akrabasıydı. Bu köle Petrusa, ‹‹Bahçede, seni Onunla birlikte görmedim mi?›› diye sordu.'),
(2009844,68,43,18,27,'Petrus yine inkâr etti ve tam o anda horoz öttü.'),
(2009845,68,43,18,28,'Sabah erkenden Yahudi yetkililer İsayı Kayafanın yanından alarak vali konağına götürdüler. Dinsel kuralları bozmamak ve Fısıh yemeğini yiyebilmek için kendileri vali konağına girmediler.'),
(2009846,68,43,18,29,'Bunun üzerine Pilatus dışarı çıkıp yanlarına geldi. ‹‹Bu adamı neyle suçluyorsunuz?›› diye sordu.'),
(2009847,68,43,18,30,'Ona şu karşılığı verdiler: ‹‹Bu adam kötülük eden biri olmasaydı, Onu sana getirmezdik.››'),
(2009848,68,43,18,31,'Pilatus, ‹‹Onu siz alın, kendi yasanıza göre yargılayın›› dedi. Yahudi yetkililer, ‹‹Bizim hiç kimseyi ölüm cezasına çarptırmaya yetkimiz yok›› dediler.'),
(2009849,68,43,18,32,'Bu, İsanın nasıl öleceğini belirtmek için söylediği sözler yerine gelsin diye oldu.'),
(2009850,68,43,18,33,'Pilatus yine vali konağına girdi. İsayı çağırıp Ona, ‹‹Sen Yahudilerin Kralı mısın?›› diye sordu.'),
(2009851,68,43,18,34,'İsa şöyle karşılık verdi: ‹‹Bunu kendiliğinden mi söylüyorsun, yoksa başkaları mı sana söyledi?››'),
(2009852,68,43,18,35,'Pilatus, ‹‹Ben Yahudi miyim?›› dedi. ‹‹Seni bana kendi ulusun ve başkâhinlerin teslim ettiler. Ne yaptın?››'),
(2009853,68,43,18,36,'İsa, ‹‹Benim krallığım bu dünyadan değildir›› diye karşılık verdi. ‹‹Krallığım bu dünyadan olsaydı, yandaşlarım, Yahudi yetkililere teslim edilmemem için savaşırlardı. Oysa benim krallığım buradan değildir.››'),
(2009854,68,43,18,37,'Pilatus, ‹‹Demek sen bir kralsın, öyle mi?›› dedi. İsa, ‹‹Kral olduğumu sen söylüyorsun›› karşılığını verdi. ‹‹Ben gerçeğe tanıklık etmek için doğdum, bunun için dünyaya geldim. Gerçekten yana olan herkes benim sesimi işitir.››'),
(2009855,68,43,18,38,'Pilatus Ona, ‹‹Gerçek nedir?›› diye sordu. Bunu söyledikten sonra Pilatus yine dışarıya, Yahudilerin yanına çıktı. Onlara, ‹‹Ben Onda hiçbir suç görmüyorum›› dedi.'),
(2009856,68,43,18,39,'‹‹Ama sizin bir geleneğiniz var, her Fısıh Bayramında sizin için birini salıveriyorum. Yahudilerin Kralını sizin için salıvermemi ister misiniz?››'),
(2009857,68,43,18,40,'Onlar yine, ‹‹Bu adamı değil, Barabba''yı isteriz!›› diye bağrıştılar. Oysa Barabba bir hayduttu.'),
(2009858,68,43,19,1,'O zaman Pilatus İsayı tutup kamçılattı.'),
(2009859,68,43,19,2,'Askerler de dikenlerden bir taç örüp Onun başına geçirdiler. Sonra Ona mor bir kaftan giydirdiler.'),
(2009860,68,43,19,3,'Önüne geliyor, ‹‹Selam, ey Yahudilerin Kralı!›› diyor, yüzüne tokat atıyorlardı.'),
(2009861,68,43,19,4,'Pilatus yine dışarı çıktı. Yahudilere, ‹‹İşte, Onu dışarıya, size getiriyorum. Onda hiçbir suç bulmadığımı bilesiniz›› dedi.'),
(2009862,68,43,19,5,'Böylece İsa, başındaki dikenli taç ve üzerindeki mor kaftanla dışarı çıktı. Pilatus onlara, ‹‹İşte o adam!›› dedi.'),
(2009863,68,43,19,6,'Başkâhinler ve görevliler İsayı görünce, ‹‹Çarmıha ger, çarmıha ger!›› diye bağrıştılar. Pilatus, ‹‹Onu siz alıp çarmıha gerin!›› dedi. ‹‹Ben Onda bir suç bulamıyorum!››'),
(2009864,68,43,19,7,'Yahudiler şu karşılığı verdiler: ‹‹Bizim bir yasamız var, bu yasaya göre Onun ölmesi gerekir. Çünkü kendisinin Tanrı Oğlu olduğunu ileri sürüyor.››'),
(2009865,68,43,19,8,'Pilatus bu sözü işitince daha çok korktu.'),
(2009866,68,43,19,9,'Yine vali konağına girip İsaya, ‹‹Sen nereden geliyorsun?›› diye sordu. İsa ona yanıt vermedi.'),
(2009867,68,43,19,10,'Pilatus, ‹‹Benimle konuşmayacak mısın?›› dedi. ‹‹Seni salıvermeye de, çarmıha germeye de yetkim olduğunu bilmiyor musun?››'),
(2009868,68,43,19,11,'İsa, ‹‹Sana gökten verilmeseydi, benim üzerimde hiçbir yetkin olmazdı›› diye karşılık verdi. ‹‹Bu nedenle beni sana teslim edenin günahı daha büyüktür.››'),
(2009869,68,43,19,12,'Bunun üzerine Pilatus İsayı salıvermek istedi. Ama Yahudiler, ‹‹Bu adamı salıverirsen, Sezarın dostu değilsin!›› diye bağrıştılar. ‹‹Kral olduğunu ileri süren herkes Sezara karşı gelmiş olur.››'),
(2009870,68,43,19,13,'Pilatus bu sözleri işitince İsayı dışarı çıkardı. Taş Döşeme -İbranicede Gabbata- denilen yerde yargı kürsüsüne oturdu.'),
(2009871,68,43,19,14,'Fısıh Bayramına Hazırlık Günüydü. Saat on iki sularıydı. Pilatus Yahudilere, ‹‹İşte, sizin Kralınız!›› dedi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009872,68,43,19,15,'Onlar, ‹‹Yok et Onu! Yok et, çarmıha ger!›› diye bağrıştılar. Pilatus, ‹‹Kralınızı mı çarmıha gereyim?›› diye sordu. Başkâhinler, ‹‹Sezardan başka kralımız yok!›› karşılığını verdiler.'),
(2009873,68,43,19,16,'Bunun üzerine Pilatus İsayı, çarmıha gerilmek üzere onlara teslim etti.'),
(2009874,68,43,19,17,'Askerler İsayı alıp götürdüler. İsa çarmıhını kendisi taşıyıp Kafatası -İbranicede Golgota- denilen yere çıktı.'),
(2009875,68,43,19,18,'Orada Onu ve iki kişiyi daha çarmıha gerdiler. Biri bir yanda, öbürü öteki yanda, İsa ise ortadaydı.'),
(2009876,68,43,19,19,'Pilatus bir de yafta yazıp çarmıhın üzerine astırdı. Yaftada şöyle yazılıydı:'),
(2009877,68,43,19,20,'İsanın çarmıha gerildiği yer kente yakındı. Böylece İbranice, Latince ve Grekçe yazılan bu yaftayı Yahudilerin birçoğu okudu.'),
(2009878,68,43,19,21,'Bu yüzden Yahudi başkâhinler Pilatusa, ‹‹ ‹Yahudilerin Kralı› diye yazma›› dediler. ‹‹Kendisi, ‹Ben Yahudilerin Kralıyım dedi› diye yaz.››'),
(2009879,68,43,19,22,'Pilatus, ‹‹Ne yazdımsa yazdım›› karşılığını verdi.'),
(2009880,68,43,19,23,'Askerler İsayı çarmıha gerdikten sonra giysilerini alıp her birine birer pay düşecek biçimde dört parçaya böldüler. Mintanını da aldılar. Mintan boydan boya tek parça dikişsiz bir dokumaydı.'),
(2009881,68,43,19,24,'Birbirlerine, ‹‹Bunu yırtmayalım›› dediler, ‹‹Kime düşecek diye kura çekelim.›› Bu olay, şu Kutsal Yazı yerine gelsin diye oldu: ‹‹Giysilerimi aralarında paylaştılar, Elbisem üzerine kura çektiler.›› Bunları askerler yaptı.'),
(2009882,68,43,19,25,'İsanın çarmıhının yanında ise annesi, teyzesi, Klopasın karısı Meryem ve Mecdelli Meryem duruyordu.'),
(2009883,68,43,19,26,'İsa, annesiyle sevdiği öğrencinin yakınında durduğunu görünce annesine, ‹‹Anne, işte oğlun!›› dedi.'),
(2009884,68,43,19,27,'Sonra öğrenciye, ‹‹İşte, annen!›› dedi. O andan itibaren bu öğrenci İsanın annesini kendi evine aldı.'),
(2009885,68,43,19,28,'Daha sonra İsa, her şeyin artık tamamlandığını bilerek Kutsal Yazı yerine gelsin diye, ‹‹Susadım!›› dedi.'),
(2009886,68,43,19,29,'Orada ekşi şarap dolu bir kap vardı. Şaraba batırılmış bir süngeri mercanköşk dalına takarak Onun ağzına uzattılar.'),
(2009887,68,43,19,30,'İsa şarabı tadınca, ‹‹Tamamlandı!›› dedi ve başını eğerek ruhunu teslim etti.'),
(2009888,68,43,19,31,'Yahudi yetkililer Pilatustan çarmıha gerilenlerin bacaklarının kırılmasını ve cesetlerin kaldırılmasını istediler. Hazırlık Günü olduğundan, cesetlerin Şabat Günü çarmıhta kalmasını istemiyorlardı. Çünkü o Şabat Günü büyük bayramdı.'),
(2009889,68,43,19,32,'Bunun üzerine askerler gidip birinci adamın, sonra da İsayla birlikte çarmıha gerilen öteki adamın bacaklarını kırdılar.'),
(2009890,68,43,19,33,'İsaya gelince Onun ölmüş olduğunu gördüler. Bu yüzden bacaklarını kırmadılar.'),
(2009891,68,43,19,34,'Ama askerlerden biri Onun böğrünü mızrakla deldi. Böğründen hemen kan ve su aktı.'),
(2009892,68,43,19,35,'Bunu gören adam tanıklık etmiştir ve tanıklığı doğrudur. Doğruyu söylediğini bilir. Siz de iman edesiniz diye tanıklık etmiştir.'),
(2009893,68,43,19,36,'Bunlar, ‹‹Onun bir tek kemiği kırılmayacak›› diyen Kutsal Yazının yerine gelmesi için oldu.'),
(2009894,68,43,19,37,'Yine başka bir Yazıda, ‹‹Bedenini deştiklerine bakacaklar›› deniyor.'),
(2009895,68,43,19,38,'Bundan sonra Aramatyalı Yusuf, İsanın cesedini kaldırmak için Pilatusa başvurdu. Yusuf, İsanın öğrencisiydi, ama Yahudi yetkililerden korktuğundan bunu gizli tutuyordu. Pilatus izin verince, Yusuf gelip İsanın cesedini kaldırdı.'),
(2009896,68,43,19,39,'Daha önce geceleyin İsanın yanına gelen Nikodim de otuz litre kadar karışık mür ve sarısabır özü alarak geldi.'),
(2009897,68,43,19,40,'İkisi, İsanın cesedini alıp Yahudilerin gömme geleneğine uygun olarak onu baharatla keten bezlere sardılar.'),
(2009898,68,43,19,41,'İsanın çarmıha gerildiği yerde bir bahçe, bu bahçenin içinde de henüz hiç kimsenin konulmadığı yeni bir mezar vardı.'),
(2009899,68,43,19,42,'O gün Yahudiler''in Hazırlık Günü''ydü. Mezar da yakın olduğundan İsa''yı oraya koydular.'),
(2009900,68,43,20,1,'Haftanın ilk günü erkenden, ortalık daha karanlıkken Mecdelli Meryem mezara gitti. Taşın mezarın girişinden kaldırılmış olduğunu gördü.'),
(2009901,68,43,20,2,'Koşarak Simun Petrusa ve İsanın sevdiği öbür öğrenciye geldi. ‹‹Rabbi mezardan almışlar, nereye koyduklarını da bilmiyoruz›› dedi.'),
(2009902,68,43,20,3,'Bunun üzerine Petrusla öteki öğrenci dışarı çıkıp mezara yöneldiler.'),
(2009903,68,43,20,4,'İkisi birlikte koşuyordu. Ama öteki öğrenci Petrustan daha hızlı koşarak mezara önce vardı.'),
(2009904,68,43,20,5,'Eğilip içeri baktı, keten bezleri orada serili gördü, ama içeri girmedi.'),
(2009905,68,43,20,6,'Ardından Simun Petrus geldi ve mezara girdi. Orada serili duran bezleri ve İsanın başına sarılmış olan peşkiri gördü. Peşkir keten bezlerle birlikte değildi, ayrı bir yerde dürülmüş duruyordu.'),
(2009906,68,43,20,8,'O zaman mezara ilk varan öteki öğrenci de içeri girdi. Olanları gördü ve iman etti.'),
(2009907,68,43,20,9,'İsanın ölümden dirilmesi gerektiğini belirten Kutsal Yazıyı henüz anlamamışlardı.'),
(2009908,68,43,20,10,'Bundan sonra öğrenciler yine evlerine döndüler.'),
(2009909,68,43,20,11,'Meryem ise mezarın dışında durmuş ağlıyordu. Ağlarken eğilip mezarın içine baktı.'),
(2009910,68,43,20,12,'Beyazlara bürünmüş iki melek gördü; biri İsanın cesedinin yattığı yerin başucunda, öteki ayakucunda oturuyordu.'),
(2009911,68,43,20,13,'Meryeme, ‹‹Kadın, niçin ağlıyorsun?›› diye sordular. Meryem, ‹‹Rabbimi almışlar›› dedi. ‹‹Onu nereye koyduklarını bilmiyorum.››'),
(2009912,68,43,20,14,'Bunları söyledikten sonra arkasına döndü, İsanın orada, ayakta durduğunu gördü. Ama Onun İsa olduğunu anlamadı.'),
(2009913,68,43,20,15,'İsa, ‹‹Kadın, niçin ağlıyorsun?›› dedi. ‹‹Kimi arıyorsun?›› Meryem Onu bahçıvan sanarak, ‹‹Efendim›› dedi, ‹‹Eğer Onu sen götürdünse, nereye koyduğunu söyle de gidip Onu alayım.››'),
(2009914,68,43,20,16,'İsa ona, ‹‹Meryem!›› dedi. O da döndü, İsaya İbranice, ‹‹Rabbuni!›› dedi. Rabbuni, öğretmenim demektir.'),
(2009915,68,43,20,17,'İsa, ‹‹Bana dokunma!›› dedi. ‹‹Çünkü daha Babanın yanına çıkmadım. Kardeşlerime git ve onlara söyle, benim Babamın ve sizin Babanızın, benim Tanrımın ve sizin Tanrınızın yanına çıkıyorum.››'),
(2009916,68,43,20,18,'Mecdelli Meryem öğrencilerin yanına gitti. Onlara, ‹‹Rabbi gördüm!›› dedi. Sonra Rabbin kendisine söylediklerini onlara anlattı.'),
(2009917,68,43,20,19,'Haftanın o ilk günü akşam olunca, öğrencilerin Yahudi yetkililerden korkusu nedeniyle bulundukları yerin kapıları kapalıyken İsa geldi, ortalarında durup, ‹‹Size esenlik olsun!›› dedi.'),
(2009918,68,43,20,20,'Bunu söyledikten sonra onlara ellerini ve böğrünü gösterdi. Öğrenciler Rabbi görünce sevindiler.'),
(2009919,68,43,20,21,'İsa yine onlara, ‹‹Size esenlik olsun!›› dedi. ‹‹Baba beni gönderdiği gibi, ben de sizi gönderiyorum.››'),
(2009920,68,43,20,22,'Bunu söyledikten sonra onların üzerine üfleyerek, ‹‹Kutsal Ruhu alın!›› dedi.'),
(2009921,68,43,20,23,'‹‹Kimin günahlarını bağışlarsanız, bağışlanmış olur; kimin günahlarını bağışlamazsanız, bağışlanmamış kalır.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009922,68,43,20,24,'Onikilerden biri, ‹‹İkiz›› diye anılan Tomas, İsa geldiğinde onlarla birlikte değildi.'),
(2009923,68,43,20,25,'Öbür öğrenciler ona, ‹‹Biz Rabbi gördük!›› dediler. Tomas ise, ‹‹Onun ellerinde çivilerin izini görmedikçe, çivilerin izine parmağımla dokunmadıkça ve elimi böğrüne sokmadıkça inanmam›› dedi.'),
(2009924,68,43,20,26,'Sekiz gün sonra İsanın öğrencileri yine evdeydiler. Tomas da onlarla birlikteydi. Kapılar kapalıyken İsa gelip ortalarında durdu, ‹‹Size esenlik olsun!›› dedi.'),
(2009925,68,43,20,27,'Sonra Tomasa, ‹‹Parmağını uzat›› dedi, ‹‹Ellerime bak, elini uzat, böğrüme koy. İmansız olma, imanlı ol!››'),
(2009926,68,43,20,28,'Tomas Ona, ‹‹Rabbim ve Tanrım!›› diye yanıtladı.'),
(2009927,68,43,20,29,'İsa, ‹‹Beni gördüğün için mi iman ettin?›› dedi. ‹‹Görmeden iman edenlere ne mutlu!››'),
(2009928,68,43,20,30,'İsa, öğrencilerinin önünde, bu kitapta yazılı olmayan başka birçok doğaüstü belirti gerçekleştirdi.'),
(2009929,68,43,20,31,'Ne var ki yazılanlar, İsa''nın, Tanrı''nın Oğlu Mesih olduğuna iman edesiniz ve iman ederek O''nun adıyla yaşama kavuşasınız diye yazılmıştır.'),
(2009930,68,43,21,1,'Bundan sonra İsa Taberiye Gölünün kenarında öğrencilerine yine göründü. Bu da şöyle oldu: Simun Petrus, ‹‹İkiz›› diye anılan Tomas, Celilenin Kana Köyünden Natanel, Zebedinin oğulları ve İsanın öğrencilerinden iki kişi daha birlikte bulunuyorlardı.'),
(2009931,68,43,21,3,'Simun Petrus ötekilere, ‹‹Ben balık tutmaya gidiyorum›› dedi. Onlar, ‹‹Biz de seninle geliyoruz›› dediler. Dışarı çıkıp tekneye bindiler. Ama o gece bir şey tutamadılar.'),
(2009932,68,43,21,4,'Sabah olurken İsa kıyıda duruyordu. Ne var ki öğrenciler, Onun İsa olduğunu anlamadılar.'),
(2009933,68,43,21,5,'İsa, ‹‹Çocuklar, balığınız yok mu?›› diye sordu. ‹‹Yok›› dediler.'),
(2009934,68,43,21,6,'İsa, ‹‹Ağı teknenin sağ yanına atın, tutarsınız›› dedi. Bunun üzerine ağı attılar. O kadar çok balık tuttular ki, artık ağı çekemez olmuşlardı.'),
(2009935,68,43,21,7,'İsanın sevdiği öğrenci, Petrusa, ‹‹Bu Rabdir!›› dedi. Simun Petrus Onun Rab olduğunu işitince üzerinden çıkarmış olduğu üstlüğü giyip göle atladı.'),
(2009936,68,43,21,8,'Öbür öğrenciler balık dolu ağı çekerek tekneyle geldiler. Çünkü karadan ancak iki yüz arşın kadar uzaktaydılar.'),
(2009937,68,43,21,9,'Karaya çıkınca orada yanan bir kömür ateşi, ateşin üzerinde balık ve ekmek gördüler.'),
(2009938,68,43,21,10,'İsa onlara, ‹‹Şimdi tuttuğunuz balıklardan getirin›› dedi.'),
(2009939,68,43,21,11,'Simun Petrus tekneye atladı ve tam yüz elli üç iri balıkla yüklü ağı karaya çekti. Bu kadar çok balık olduğu halde ağ yırtılmamıştı.'),
(2009940,68,43,21,12,'İsa onlara, ‹‹Gelin, yemek yiyin›› dedi. Öğrencilerden hiçbiri Ona, ‹‹Sen kimsin?›› diye sormaya cesaret edemedi. Çünkü Onun Rab olduğunu biliyorlardı.'),
(2009941,68,43,21,13,'İsa gidip ekmeği aldı, onlara verdi. Aynı şekilde balıkları da verdi.'),
(2009942,68,43,21,14,'İşte bu, İsanın ölümden dirildikten sonra öğrencilere üçüncü görünüşüydü.'),
(2009943,68,43,21,15,'Yemekten sonra İsa, Simun Petrusa, ‹‹Yuhanna oğlu Simun, beni bunlardan daha çok seviyor musun?›› diye sordu. Petrus, ‹‹Evet, ya Rab›› dedi, ‹‹Seni sevdiğimi bilirsin.›› İsa ona, ‹‹Kuzularımı otlat›› dedi.'),
(2009944,68,43,21,16,'İkinci kez yine ona, ‹‹Yuhanna oğlu Simun, beni seviyor musun?›› diye sordu. O da, ‹‹Evet, ya Rab, seni sevdiğimi bilirsin›› dedi. İsa ona, ‹‹Koyunlarımı güt›› dedi.'),
(2009945,68,43,21,17,'Üçüncü kez ona, ‹‹Yuhanna oğlu Simun, beni seviyor musun?›› diye sordu. Petrus kendisine üçüncü kez, ‹‹Beni seviyor musun?›› diye sormasına üzüldü. ‹‹Ya Rab, sen her şeyi bilirsin, seni sevdiğimi de bilirsin›› dedi. İsa ona, ‹‹Koyunlarımı otlat›› dedi.'),
(2009946,68,43,21,18,'‹‹Sana doğrusunu söyleyeyim, gençliğinde kendi kuşağını kendin bağlar, istediğin yere giderdin. Ama yaşlanınca ellerini uzatacaksın, başkası seni bağlayacak ve istemediğin yere götürecek.››'),
(2009947,68,43,21,19,'Bunu, Tanrıyı ne tür bir ölümle yücelteceğini belirtmek için söyledi. Sonra ona, ‹‹Ardımdan gel›› dedi.'),
(2009948,68,43,21,20,'Petrus arkasına döndü, İsanın sevdiği öğrencinin kendilerini izlediğini gördü. Bu öğrenci, akşam yemeğinde İsanın göğsüne yaslanan ve, ‹‹Ya Rab, sana kim ihanet edecek?›› diye soran öğrencidir.'),
(2009949,68,43,21,21,'Petrus onu görünce İsaya, ‹‹Ya Rab, ya bu ne olacak?›› diye sordu.'),
(2009950,68,43,21,22,'İsa, ‹‹Ben gelinceye dek onun yaşamasını istiyorsam, bundan sana ne?›› dedi. ‹‹Sen ardımdan gel!››'),
(2009951,68,43,21,23,'Bu yüzden kardeşler arasında o öğrencinin ölmeyeceğine dair bir söylenti çıktı. Ama İsa Petrusa, ‹‹O ölmeyecek›› dememişti. Sadece, ‹‹Ben gelinceye dek onun yaşamasını istiyorsam, bundan sana ne?›› demişti.'),
(2009952,68,43,21,24,'Bütün bunlara tanıklık eden ve bunları yazan öğrenci budur. Onun tanıklığının doğru olduğunu biliyoruz.'),
(2009953,68,43,21,25,'İsa''nın yaptığı daha başka çok şey vardır. Bunlar tek tek yazılsaydı, sanırım yazılan kitaplar dünyaya sığmazdı.'),
(2009954,68,44,1,1,'Ey Teofilos, İlk kitabımda İsanın yapıp öğretmeye başladığı her şeyi, seçmiş olduğu elçilere Kutsal Ruh aracılığıyla buyruklar verip yukarı alındığı güne dek olanları yazmıştım.'),
(2009955,68,44,1,3,'İsa, ölüm acısını çektikten sonra birçok inandırıcı kanıtlarla elçilere dirilmiş olduğunu gösterdi. Kırk gün süreyle onlara görünerek Tanrının Egemenliği hakkında konuştu.'),
(2009956,68,44,1,4,'Kendileriyle birlikteyken onlara şu buyruğu vermişti: ‹‹Yeruşalimden ayrılmayın, Babanın verdiği ve benden duyduğunuz sözün gerçekleşmesini bekleyin.'),
(2009957,68,44,1,5,'Şöyle ki, Yahya suyla vaftiz etti, ama sizler birkaç güne kadar Kutsal Ruhla vaftiz edileceksiniz.››'),
(2009958,68,44,1,6,'Elçiler bir araya geldiklerinde İsaya şunu sordular: ‹‹Ya Rab, İsraile egemenliği şimdi mi geri vereceksin?››'),
(2009959,68,44,1,7,'İsa onlara, ‹‹Babanın kendi yetkisiyle belirlemiş olduğu zamanları ve tarihleri bilmenize gerek yok›› karşılığını verdi.'),
(2009960,68,44,1,8,'‹‹Ama Kutsal Ruh üzerinize inince güç alacaksınız. Yeruşalimde, bütün Yahudiye ve Samiriyede ve dünyanın dört bucağında benim tanıklarım olacaksınız.››'),
(2009961,68,44,1,9,'İsa bunları söyledikten sonra, onların gözleri önünde yukarı alındı. Bir bulut Onu alıp gözlerinin önünden uzaklaştırdı.'),
(2009962,68,44,1,10,'İsa giderken onlar gözlerini göğe dikmiş bakıyorlardı. Tam o sırada, beyaz giysiler içinde iki adam yanlarında belirdi.'),
(2009963,68,44,1,11,'‹‹Ey Celileliler, neden göğe bakıp duruyorsunuz?›› diye sordular. ‹‹Aranızdan göğe alınan İsa, göğe çıktığını nasıl gördünüzse, aynı şekilde geri gelecektir.››'),
(2009964,68,44,1,12,'Bundan sonra elçiler, Yeruşalimden yaklaşık bir kilometre uzaklıktaki Zeytin Dağından Yeruşalime döndüler.'),
(2009965,68,44,1,13,'Kente girince kaldıkları evin üst katındaki odaya çıktılar. Petrus, Yuhanna, Yakup, Andreas, Filipus, Tomas, Bartalmay, Matta, Alfay oğlu Yakup, Yurtsever Simun ve Yakup oğlu Yahuda oradaydı.'),
(2009966,68,44,1,14,'Bunlar İsanın annesi Meryem, öbür kadınlar ve İsanın kardeşleriyle tam bir birlik içinde sürekli dua ediyordu.'),
(2009967,68,44,1,15,'O günlerde Petrus, yaklaşık yüz yirmi kardeşten oluşan bir topluluğun ortasında ayağa kalkıp şöyle konuştu: ‹‹Kardeşler, Kutsal Ruhun, İsayı tutuklayanlara kılavuzluk eden Yahuda ile ilgili olarak Davutun ağzıyla önceden bildirdiği Kutsal Yazının yerine gelmesi gerekiyordu.'),
(2009968,68,44,1,17,'Yahuda bizden biri sayılmış ve bu hizmette yerini almıştı.››'),
(2009969,68,44,1,18,'Bu adam, yaptığı kötülüğün karşılığında aldığı ücretle bir tarla satın aldı. Sonra baş aşağı düştü, bedeni yarıldı ve bütün bağırsakları dışarı döküldü.'),
(2009970,68,44,1,19,'Yeruşalimde yaşayan herkes olayı duydu. Tarlaya kendi dillerinde Kan Tarlası anlamına gelen Hakeldema adını verdiler.'),
(2009971,68,44,1,20,'‹‹Nitekim Mezmurlar Kitabında şöyle yazılmıştır›› dedi Petrus. ‹‹ ‹Onun konutu ıssız kalsın, İçinde oturan olmasın.› Ve, ‹Onun görevini bir başkası üstlensin.›');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2009972,68,44,1,21,'‹‹Buna göre, Yahyanın vaftiz döneminden başlayarak Rab İsanın aramızdan yukarı alındığı güne değin bizimle birlikte geçirdiği bütün süre boyunca yanımızda bulunan adamlardan birinin, İsanın dirilişine tanıklık etmek üzere bize katılması gerekir.››'),
(2009973,68,44,1,23,'Böylece iki kişiyi, Barsabba denilen ve Yustus diye de bilinen Yusuf ile Mattiyayı önerdiler.'),
(2009974,68,44,1,24,'Sonra şöyle dua ettiler: ‹‹Ya Rab, sen herkesin yüreğini bilirsin. Yahudanın, ait olduğu yere gitmek için bıraktığı bu hizmeti ve elçilik görevini üstlenmek üzere bu iki kişiden hangisini seçtiğini göster bize.››'),
(2009975,68,44,1,26,'Ardından bu iki kişiye kura çektirdiler; kura Mattiya''ya düştü. Böylelikle Mattiya on bir elçiye katıldı.'),
(2009976,68,44,2,1,'Pentikost Günü geldiğinde bütün imanlılar bir arada bulunuyordu.'),
(2009977,68,44,2,2,'Ansızın gökten, güçlü bir rüzgarın esişini andıran bir ses geldi ve bulundukları evi tümüyle doldurdu.'),
(2009978,68,44,2,3,'Ateşten dillere benzer bir şeylerin dağılıp her birinin üzerine indiğini gördüler.'),
(2009979,68,44,2,4,'İmanlıların hepsi Kutsal Ruhla doldular, Ruhun onları konuşturduğu başka dillerle konuşmaya başladılar.'),
(2009980,68,44,2,5,'O sırada Yeruşalimde, dünyanın her ülkesinden gelmiş dindar Yahudiler bulunuyordu.'),
(2009981,68,44,2,6,'Sesin duyulması üzerine büyük bir kalabalık toplandı. Herkes kendi dilinin konuşulduğunu duyunca şaşakaldı.'),
(2009982,68,44,2,7,'Hayret ve şaşkınlık içinde, ‹‹Bakın, bu konuşanların hepsi Celileli değil mi?›› diye sordular.'),
(2009983,68,44,2,8,'‹‹Nasıl oluyor da her birimiz kendi ana dilini işitiyor?'),
(2009984,68,44,2,9,'Aramızda Partlar, Medler, Elamlılar var. Mezopotamyada, Yahudiye ve Kapadokyada, Pontus ve Asya İlinde, Frikya ve Pamfilyada, Mısır ve Libyanın Kireneye yakın bölgelerinde yaşayanlar var. Hem Yahudi hem de Yahudiliğe dönen Romalı konuklar, Giritliler ve Araplar var aramızda. Ama her birimiz Tanrının büyük işlerinin kendi dilimizde konuşulduğunu işitiyoruz.››'),
(2009985,68,44,2,12,'Hepsi hayret ve şaşkınlık içinde birbirlerine, ‹‹Bunun anlamı ne?›› diye sordular.'),
(2009986,68,44,2,13,'Başkalarıysa, ‹‹Bunlar taze şarabı fazla kaçırmış›› diye alay ettiler.'),
(2009987,68,44,2,14,'Bunun üzerine Onbirlerle birlikte öne çıkan Petrus yüksek sesle kalabalığa şöyle seslendi: ‹‹Ey Yahudiler ve Yeruşalimde bulunan herkes, bu durumu size açıklayayım. Sözlerime kulak verin. Bu adamlar, sandığınız gibi sarhoş değiller. Saat daha sabahın dokuzu!'),
(2009988,68,44,2,16,'Bu gördüğünüz, Peygamber Yoel aracılığıyla önceden bildirilen olaydır: ‹Son günlerde, diyor Tanrı, Bütün insanların üzerine Ruhumu dökeceğim. Oğullarınız, kızlarınız peygamberlikte bulunacaklar. Gençleriniz görümler, Yaşlılarınız düşler görecek.'),
(2009989,68,44,2,18,'O günler kadın erkek Kullarımın üzerine Ruhumu dökeceğim, Onlar da peygamberlik edecekler.'),
(2009990,68,44,2,19,'Yukarıda, gökyüzünde harikalar yaratacağım. Aşağıda, yeryüzünde belirtiler, Kan, ateş ve duman bulutları görülecek.'),
(2009991,68,44,2,20,'Rabbin büyük ve görkemli günü gelmeden önce Güneş kararacak, Ay kan rengine dönecek.'),
(2009992,68,44,2,21,'O zaman Rabbi adıyla çağıran herkes kurtulacak.›'),
(2009993,68,44,2,22,'‹‹Ey İsrailliler, şu sözleri dinleyin: Bildiğiniz gibi Nasıralı İsa, Tanrının, kendisi aracılığıyla aranızda yaptığı mucizeler, harikalar ve belirtilerle kimliği kanıtlanmış bir kişidir.'),
(2009994,68,44,2,23,'Tanrının belirlenmiş amacı ve öngörüsü uyarınca elinize teslim edilen bu adamı, yasa tanımaz kişilerin eliyle çarmıha çivileyip öldürdünüz.'),
(2009995,68,44,2,24,'Tanrı ise, ölüm acılarına son vererek Onu diriltti. Çünkü Onun ölüme tutsak kalması olanaksızdı.'),
(2009996,68,44,2,25,'Onunla ilgili olarak Davut şöyle der: ‹Rabbi her zaman önümde gördüm, Sağımda durduğu için sarsılmam.'),
(2009997,68,44,2,26,'Bu nedenle yüreğim mutlu, dilim sevinçlidir. Dahası, bedenim de umut içinde yaşayacak.'),
(2009998,68,44,2,27,'Çünkü sen canımı ölüler diyarına terk etmeyeceksin, Kutsalının çürümesine izin vermeyeceksin.'),
(2009999,68,44,2,28,'Yaşam yollarını bana bildirdin; Varlığınla beni sevinçle dolduracaksın.›'),
(2010000,68,44,2,29,'‹‹Kardeşler, size açıkça söyleyebilirim ki, büyük atamız Davut öldü, gömüldü, mezarı da bugüne dek yanıbaşımızda duruyor.'),
(2010001,68,44,2,30,'Davut bir peygamberdi ve soyundan birini tahtına oturtacağına dair Tanrının kendisine ant içerek söz verdiğini biliyordu.'),
(2010002,68,44,2,31,'Geleceği görerek Mesihin ölümden dirilişine ilişkin şunları söyledi: ‹O, ölüler diyarına terk edilmedi, bedeni çürümedi.›'),
(2010003,68,44,2,32,'Tanrı, İsayı ölümden diriltti ve biz hepimiz bunun tanıklarıyız.'),
(2010004,68,44,2,33,'O, Tanrının sağına yüceltilmiş, vaat edilen Kutsal Ruhu Babadan almış ve şimdi gördüğünüz ve işittiğiniz gibi, bu Ruhu üzerimize dökmüştür.'),
(2010005,68,44,2,34,'Davut, kendisi göklere çıkmadığı halde şöyle der: ‹Rab Rabbime dedi ki, Ben düşmanlarını Ayaklarının altına serinceye dek, Sağımda otur.›'),
(2010006,68,44,2,36,'‹‹Böylelikle bütün İsrail halkı şunu kesinlikle bilsin: Tanrı, sizin çarmıha gerdiğiniz İsayı hem Rab hem Mesih yapmıştır.››'),
(2010007,68,44,2,37,'Bu sözleri duyanlar, yüreklerine hançer saplanmış gibi oldular. Petrus ve öbür elçilere, ‹‹Kardeşler, ne yapmalıyız?›› diye sordular.'),
(2010008,68,44,2,38,'Petrus onlara şu karşılığı verdi: ‹‹Tövbe edin, her biriniz İsa Mesihin adıyla vaftiz olsun. Böylece günahlarınız bağışlanacak ve Kutsal Ruh armağanını alacaksınız.'),
(2010009,68,44,2,39,'Bu vaat sizler, çocuklarınız, uzaktakilerin hepsi için, Tanrımız Rabbin çağıracağı herkes için geçerlidir.››'),
(2010010,68,44,2,40,'Petrus daha birçok sözlerle onları uyardı. ‹‹Kendinizi bu sapık kuşaktan kurtarın!›› diye yalvardı.'),
(2010011,68,44,2,41,'Onun sözünü benimseyenler vaftiz oldu. O gün yaklaşık üç bin kişi topluluğa katıldı.'),
(2010012,68,44,2,42,'Bunlar kendilerini elçilerin öğretisine, paydaşlığa, ekmek bölmeye ve duaya adadılar.'),
(2010013,68,44,2,43,'Herkesi bir korku sarmıştı. Elçilerin aracılığıyla birçok belirtiler ve harikalar yapılıyordu.'),
(2010014,68,44,2,44,'İmanlıların tümü bir arada bulunuyor, her şeyi ortaklaşa kullanıyorlardı.'),
(2010015,68,44,2,45,'Mallarını mülklerini satıyor ve bunun parasını herkese ihtiyacına göre dağıtıyorlardı.'),
(2010016,68,44,2,46,'Her gün tapınakta toplanmaya devam eden imanlılar, kendi evlerinde de ekmek bölüp içten bir sevinç ve sadelikle yemek yiyor ve Tanrı''yı övüyorlardı. Bütün halkın beğenisini kazanmışlardı. Rab de her gün yeni kurtulanları topluluğa katıyordu.'),
(2010017,68,44,3,1,'Bir gün Petrusla Yuhanna, saat üçte, dua vaktinde tapınağa çıkıyorlardı.'),
(2010018,68,44,3,2,'O sırada, doğuştan kötürüm olan bir adam, tapınağın Güzel Kapı diye adlandırılan kapısına getiriliyordu. Tapınağa girenlerden para dilenmesi için onu her gün getirip oraya bırakırlardı.'),
(2010019,68,44,3,3,'Tapınağa girmek üzere olan Petrusla Yuhannayı gören adam, kendilerinden sadaka istedi.'),
(2010020,68,44,3,4,'Petrusla Yuhanna ona dikkatle baktılar. Sonra Petrus, ‹‹Bize bak›› dedi.'),
(2010021,68,44,3,5,'Adam, onlardan bir şey alacağını umarak gözlerini onların üzerine dikti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010022,68,44,3,6,'Petrus, ‹‹Bende altın ve gümüş yok, ama bende olanı sana veriyorum›› dedi. ‹‹Nasıralı İsa Mesihin adıyla, yürü!››'),
(2010023,68,44,3,7,'Sonra onu sağ elinden kavrayıp kaldırdı. Adamın ayakları ve bilekleri o anda sapasağlam oldu.'),
(2010024,68,44,3,8,'Sıçrayıp ayağa kalktı, yürümeye başladı. Yürüyüp sıçrayarak, Tanrıyı överek onlarla birlikte tapınağa girdi.'),
(2010025,68,44,3,9,'Bütün halk, onun yürüyüp Tanrıyı övdüğünü gördü.'),
(2010026,68,44,3,10,'Onun, tapınağın Güzel Kapısında oturup para dilenen kişi olduğunu anlayınca ondaki değişiklik karşısında büyük bir hayret ve şaşkınlığa düştüler.'),
(2010027,68,44,3,11,'Adam, Petrusla Yuhannaya tutunuyordu. Bütün halk hayret içinde Süleymanın Eyvanı denilen yerde onlara doğru koşuştu.'),
(2010028,68,44,3,12,'Bunu gören Petrus halka şöyle seslendi: ‹‹Ey İsrailliler, buna neden şaştınız? Neden gözlerinizi dikmiş bize bakıyorsunuz? Kendi gücümüz ya da dindarlığımızla bu adamın yürümesini sağlamışız gibi...!'),
(2010029,68,44,3,13,'İbrahimin, İshakın ve Yakupun Tanrısı, atalarımızın Tanrısı, Kulu İsayı yüceltti. Siz Onu ele verdiniz. Pilatus Onu serbest bırakmaya karar verdiği halde, siz Onu Pilatusun önünde reddettiniz.'),
(2010030,68,44,3,14,'Kutsal ve adil Olanı reddedip bir katilin salıverilmesini istediniz.'),
(2010031,68,44,3,15,'Siz Yaşam Önderini öldürdünüz, ama Tanrı Onu ölümden diriltti. Biz bunun tanıklarıyız.'),
(2010032,68,44,3,16,'Gördüğünüz ve tanıdığınız bu adam, İsanın adı sayesinde, Onun adına olan imanla sapasağlam oldu. Hepinizin gözü önünde onu tam sağlığa kavuşturan, İsanın aracılığıyla etkin olan imandır.'),
(2010033,68,44,3,17,'‹‹Şimdi ey kardeşler, yöneticileriniz gibi sizin de bilgisizlikten ötürü böyle davrandığınızı biliyorum.'),
(2010034,68,44,3,18,'Ama bütün peygamberlerin ağzından Mesihinin acı çekeceğini önceden bildiren Tanrı, sözünü bu şekilde yerine getirmiştir.'),
(2010035,68,44,3,19,'Öyleyse, günahlarınızın silinmesi için tövbe edin ve Tanrıya dönün. Öyle ki, Rab size yenilenme fırsatları versin ve sizin için önceden belirlenen Mesihi, yani İsayı göndersin.'),
(2010036,68,44,3,21,'Tanrının eski çağlardan beri kutsal peygamberlerinin ağzından bildirdiği gibi, her şeyin yeniden düzenleneceği zamana dek İsanın gökte kalması gerekiyor.'),
(2010037,68,44,3,22,'Musa şöyle demişti: ‹Tanrınız Rab size, kendi kardeşlerinizin arasından benim gibi bir peygamber çıkaracak. Onun size söyleyeceği her sözü dinleyin.'),
(2010038,68,44,3,23,'O peygamberi dinlemeyen herkes Tanrının halkından koparılıp yok edilecektir.›'),
(2010039,68,44,3,24,'‹‹Samuel ve ondan sonra konuşan peygamberlerin hepsi bu günleri duyurdu.'),
(2010040,68,44,3,25,'Sizler peygamberlerin mirasçıları, Tanrının atalarınızla yaptığı antlaşmanın mirasçılarısınız. Nitekim Tanrı İbrahime şöyle demişti: ‹Senin soyunun aracılığıyla yeryüzündeki bütün halklar kutsanacak.›'),
(2010041,68,44,3,26,'Tanrı, sizleri kötü yollarınızdan döndürüp kutsamak için Kulu''nu ortaya çıkarıp önce size gönderdi.››'),
(2010042,68,44,4,1,'Kâhinler, tapınak koruyucularının komutanı ve Sadukiler, halka seslenmekte olan Petrusla Yuhannanın üzerine yürüdüler.'),
(2010043,68,44,4,2,'Çünkü onların halka öğretmelerine ve İsayı örnek göstererek ölülerin dirileceğini söylemelerine çok kızmışlardı.'),
(2010044,68,44,4,3,'Onları yakaladılar, akşam olduğu için ertesi güne dek hapiste tuttular.'),
(2010045,68,44,4,4,'Ne var ki, konuşmayı dinlemiş olanların birçoğu iman etti. Böylece imanlı erkeklerin sayısı aşağı yukarı beş bine ulaştı.'),
(2010046,68,44,4,5,'Ertesi gün Yahudilerin yöneticileri, ileri gelenleri ve din bilginleri Yeruşalimde toplandılar.'),
(2010047,68,44,4,6,'Başkâhin Hananın yanısıra, Kayafa, Yuhanna, İskender ve başkâhin soyundan gelen herkes oradaydı.'),
(2010048,68,44,4,7,'Petrusla Yuhannayı huzurlarına getirtip onlara, ‹‹Siz bunu hangi güçle ya da kimin adına dayanarak yaptınız?›› diye sordular.'),
(2010049,68,44,4,8,'O zaman Kutsal Ruhla dolan Petrus onlara şöyle dedi: ‹‹Halkın yöneticileri ve ileri gelenler!'),
(2010050,68,44,4,9,'Eğer bugün bir hastaya yapılan iyilik nedeniyle bizden hesap soruluyor ve bu adamın nasıl iyileştiği soruşturuluyorsa, hepiniz ve bütün İsrail halkı şunu bilin: Bu adam, sizin çarmıha gerdiğiniz, ama Tanrının ölümden dirilttiği Nasıralı İsa Mesihin adı sayesinde önünüzde sapasağlam duruyor.'),
(2010051,68,44,4,11,'İsa, ‹Siz yapıcılar tarafından hiçe sayılan, Ama köşenin baş taşı durumuna gelen taş›tır.'),
(2010052,68,44,4,12,'Başka hiç kimsede kurtuluş yoktur. Bu göğün altında insanlara bağışlanmış, bizi kurtarabilecek başka hiçbir ad yoktur.››'),
(2010053,68,44,4,13,'Kurul üyeleri, Petrusla Yuhannanın yürekliliğini görüp de bunların eğitim görmemiş, sıradan kişiler olduklarını anlayınca şaştılar ve onların İsayla birlikte bulunduklarını farkettiler.'),
(2010054,68,44,4,14,'İyileştirilen adam, Petrus ve Yuhannayla birlikte gözleri önünde duruyordu; bunun için hiçbir karşılık veremediler.'),
(2010055,68,44,4,15,'Kurul üyeleri onlara dışarı çıkmalarını buyurduktan sonra durumu kendi aralarında tartışmaya başladılar.'),
(2010056,68,44,4,16,'‹‹Bu adamları ne yapacağız?›› dediler. ‹‹Yeruşalimde yaşayan herkes, bunların eliyle olağanüstü bir belirti gerçekleştirildiğini biliyor. Biz bunu inkâr edemeyiz.'),
(2010057,68,44,4,17,'Ama bu haberin halk arasında daha çok yayılmasını önlemek için onları tehdit edelim ki, bundan böyle İsanın adından kimseye söz etmesinler.››'),
(2010058,68,44,4,18,'Böylece onları çağırdılar, İsanın adını hiç anmamalarını, o adı kullanarak hiçbir şey öğretmemelerini buyurdular.'),
(2010059,68,44,4,19,'Ama Petrusla Yuhanna şöyle karşılık verdiler: ‹‹Tanrının önünde, Tanrının sözünü değil de sizin sözünüzü dinlemek doğru mudur, kendiniz karar verin.'),
(2010060,68,44,4,20,'Biz gördüklerimizi ve işittiklerimizi anlatmadan edemeyiz.››'),
(2010061,68,44,4,21,'Kurul üyeleri onları bir daha tehdit ettikten sonra serbest bıraktılar; onları cezalandırmak için hiçbir gerekçe bulamamışlardı. Çünkü bütün halk, olup bitenler için Tanrıyı yüceltiyordu.'),
(2010062,68,44,4,22,'Nitekim mucize sonucu iyileşen adamın yaşı kırkı geçmişti.'),
(2010063,68,44,4,23,'Serbest bırakılan Petrusla Yuhanna, arkadaşlarının yanına dönerek başkâhinlerle ileri gelenlerin kendilerine söylediği her şeyi bildirdiler.'),
(2010064,68,44,4,24,'Arkadaşları bunu duyunca hep birlikte Tanrıya şöyle seslendiler: ‹‹Ey Efendimiz! Yeri göğü, denizi ve onların içindekilerin tümünü yaratan sensin.'),
(2010065,68,44,4,25,'Kutsal Ruh aracılığıyla kulun atamız Davutun ağzından şöyle dedin: ‹Uluslar neden hiddetlendi, Halklar neden boş düzenler kurdu?'),
(2010066,68,44,4,26,'Dünyanın kralları saf bağladı, Hükümdarlar birleşti Rabbe ve Mesihine karşı.›'),
(2010067,68,44,4,27,'‹‹Gerçekten de Hirodes ile Pontius Pilatus, bu kentte İsrail halkı ve öteki uluslarla birlikte senin meshettiğin kutsal Kulun İsaya karşı bir araya geldiler. Senin kendi gücün ve isteğinle önceden kararlaştırdığın her şeyi gerçekleştirdiler.'),
(2010068,68,44,4,29,'Ve şimdi ya Rab, onların savurduğu tehditlere bak! Senin sözünü tam bir yüreklilikle duyurmak için biz kullarına güç ver.'),
(2010069,68,44,4,30,'Kutsal Kulun İsanın adıyla hastaları iyileştirmek için, belirtiler ve harikalar yapmak için elini uzat.››'),
(2010070,68,44,4,31,'Duaları bitince toplandıkları yer sarsıldı. Hepsi Kutsal Ruhla doldular ve Tanrının sözünü cesaretle duyurmaya devam ettiler.'),
(2010071,68,44,4,32,'İnananlar topluluğunun yüreği ve düşüncesi birdi. Hiç kimse sahip olduğu herhangi bir şey için ‹‹Bu benimdir›› demiyor, her şeylerini ortak kabul ediyorlardı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010072,68,44,4,33,'Elçiler, Rab İsanın ölümden dirildiğine çok etkili bir biçimde tanıklık ediyorlardı. Tanrının büyük lütfu hepsinin üzerindeydi.'),
(2010073,68,44,4,34,'Aralarında yoksul olan yoktu. Çünkü toprak ya da ev sahibi olanlar bunları satar, sattıklarının bedelini getirip elçilerin buyruğuna verirlerdi; bu da herkese ihtiyacına göre dağıtılırdı.'),
(2010074,68,44,4,36,'Örneğin, Kıbrıs doğumlu bir Levili olan ve elçilerin Barnaba, yani Cesaret Verici diye adlandırdıkları Yusuf, sahip olduğu bir tarlayı sattı, parasını getirip elçilerin buyruğuna verdi.'),
(2010075,68,44,5,1,'Hananya adında bir adam, karısı Safiranın onayıyla bir mülk sattı, paranın bir kısmını kendine saklayarak gerisini getirip elçilerin buyruğuna verdi. Karısının da olup bitenlerden haberi vardı.'),
(2010076,68,44,5,3,'Petrus ona, ‹‹Hananya, nasıl oldu da Şeytana uydun, Kutsal Ruha yalan söyleyip tarlanın parasının bir kısmını kendine sakladın?›› dedi.'),
(2010077,68,44,5,4,'‹‹Tarla satılmadan önce sana ait değil miydi? Sen onu sattıktan sonra da parayı dilediğin gibi kullanamaz mıydın? Neden yüreğinde böyle bir düzen kurdun? Sen insanlara değil, Tanrıya yalan söylemiş oldun.››'),
(2010078,68,44,5,5,'Hananya bu sözleri işitince yere yıkılıp can verdi. Olanları duyan herkesi büyük bir korku sardı.'),
(2010079,68,44,5,6,'Gençler kalkıp Hananyanın ölüsünü kefenlediler ve dışarı taşıyıp gömdüler.'),
(2010080,68,44,5,7,'Bundan yaklaşık üç saat sonra Hananyanın karısı, olanlardan habersiz içeri girdi.'),
(2010081,68,44,5,8,'Petrus, ‹‹Söyle bana, tarlayı bu fiyata mı sattınız?›› diye sordu. ‹‹Evet, bu fiyata›› dedi Safira.'),
(2010082,68,44,5,9,'Petrus ona şöyle dedi: ‹‹Rabbin Ruhunu sınamak için nasıl oldu da sözbirliği ettiniz? İşte, kocanı gömenlerin ayak sesleri kapıda, seni de dışarı taşıyacaklar.››'),
(2010083,68,44,5,10,'Kadın o anda Petrusun ayakları dibine yıkılıp can verdi. İçeri giren gençler onu ölmüş buldular, onu da dışarı taşıyarak kocasının yanına gömdüler.'),
(2010084,68,44,5,11,'İnanlılar topluluğunun tümünü ve olayı duyanların hepsini büyük bir korku sardı.'),
(2010085,68,44,5,12,'Elçilerin aracılığıyla halk arasında birçok belirtiler ve harikalar yapılıyordu. İmanlıların hepsi Süleymanın Eyvanında toplanıyordu.'),
(2010086,68,44,5,13,'Halk onlara büyük saygı duyduğu halde, dışarıdan hiç kimse onlara katılmayı göze alamıyordu.'),
(2010087,68,44,5,14,'Buna karşın, Rabbe inanıp topluluğa katılan erkek ve kadınların sayısı giderek arttı.'),
(2010088,68,44,5,15,'Bütün bunların sonucu, yoldan geçen Petrusun hiç değilse gölgesi bazılarının üzerine düşsün diye halk, hasta olanları caddelere çıkartıp şilteler ve döşekler üzerine yatırır oldu.'),
(2010089,68,44,5,16,'Yeruşalimin çevresindeki kasabalardan da kalabalıklar geliyor, hastaları ve kötü ruhlardan acı çekenleri getiriyorlardı. Bunların hepsi iyileştirildi.'),
(2010090,68,44,5,17,'Bunun üzerine, kıskançlıkla dolan başkâhin ve yanındakilerin hepsi, yani Saduki mezhebinden olanlar, elçileri yakalatıp devlet tutukevine attırdılar.'),
(2010091,68,44,5,19,'Ama geceleyin Rabbin bir meleği zindanın kapılarını açıp onları dışarı çıkarttı. ‹‹Gidin! Tapınağa girip bu yeni yaşamla ilgili sözlerin hepsini halka duyurun›› dedi.'),
(2010092,68,44,5,21,'Elçiler bu buyruğa uyarak gün doğarken tapınağa girip öğretmeye başladılar. Başkâhin ve yanındakiler gelince Yüksek Kurulu, İsrail halkının bütün ileri gelenlerini toplantıya çağırdılar. Sonra elçileri getirtmek için tutukevine adam yolladılar.'),
(2010093,68,44,5,22,'Ne var ki, görevliler zindana vardıklarında elçileri bulamadılar. Geri dönerek şu haberi ilettiler: ‹‹Tutukevini kilitli ve tam bir güvenlik altında, nöbetçileri de kapılarda durur bulduk. Ama kapıları açtığımızda içerde kimseyi bulamadık!››'),
(2010094,68,44,5,24,'Bu sözleri işiten tapınak koruyucularının komutanıyla başkâhinler şaşkına döndüler, bu işin sonunun nereye varacağını merak etmeye başladılar.'),
(2010095,68,44,5,25,'O sırada yanlarına gelen biri, ‹‹Bakın, hapse attığınız adamlar tapınakta dikilmiş, halka öğretiyor›› diye haber getirdi.'),
(2010096,68,44,5,26,'Bunun üzerine komutanla görevliler gidip elçileri getirdiler. Halkın kendilerini taşlamasından korktukları için zor kullanmadılar.'),
(2010097,68,44,5,27,'Elçileri getirip Yüksek Kurulun önüne çıkardılar. Başkâhin onları sorguya çekti: ‹‹Bu adı kullanarak öğretmeyin diye size kesin buyruk vermiştik›› dedi. ‹‹Ama siz öğretinizi Yeruşalim Kentinin her tarafına yaydınız. İlle de bizi bu adamın kanını dökmekten sorumlu göstermek istiyorsunuz.››'),
(2010098,68,44,5,29,'Petrus ve öbür elçiler şöyle karşılık verdiler: ‹‹İnsanlardan çok, Tanrının sözünü dinlemek gerek.'),
(2010099,68,44,5,30,'Atalarımızın Tanrısı, sizin çarmıha gererek öldürdüğünüz İsayı diriltti.'),
(2010100,68,44,5,31,'İsraile, günahlarından tövbe etme ve bağışlanma fırsatını vermek için Tanrı Onu Önder ve Kurtarıcı olarak kendi sağına yükseltti.'),
(2010101,68,44,5,32,'Biz, Tanrının kendi sözünü dinleyenlere verdiği Kutsal Ruhla birlikte bu olayların tanıklarıyız.››'),
(2010102,68,44,5,33,'Kurul üyeleri bu sözleri işitince çok öfkelendiler ve elçileri yok etmek istediler.'),
(2010103,68,44,5,34,'Ama bütün halkın saygısını kazanmış bir Kutsal Yasa öğretmeni olan Gamaliel adlı bir Ferisi, Yüksek Kurulda ayağa kalktı, elçilerin kısa bir süre için dışarı çıkartılmasını buyurarak kurul üyelerine şunları söyledi: ‹‹Ey İsrailliler, bu adamlara yapacağınızı iyi düşünün!'),
(2010104,68,44,5,36,'Bir süre önce Tevdas da kendi kendisiyle ilgili büyük iddialarda bulunarak başkaldırdı. Dört yüz kadar kişi de ona katıldı. Ama adam öldürüldü, izleyicilerinin hepsi dağıtıldı, hareket yok oldu.'),
(2010105,68,44,5,37,'Ondan sonra, sayım yapıldığı günlerde ortaya çıkan Celileli Yahuda, pek çok insanı ayartıp peşine taktı. Ama o da öldürüldü ve izleyicilerinin hepsi darmadağın oldu.'),
(2010106,68,44,5,38,'Şimdi size şunu söyleyeyim: Bu adamlarla uğraşmayın, onları rahat bırakın! Çünkü bu girişim, bu hareket insan işiyse, yok olup gidecektir.'),
(2010107,68,44,5,39,'Yok eğer Tanrının işiyse, bu adamları yok edemezsiniz. Hatta kendinizi Tanrıya karşı savaşır durumda bulabilirsiniz.›› Kurul üyeleri Gamalielin bu öğüdünü kabul ettiler.'),
(2010108,68,44,5,40,'Elçileri içeri çağırtıp kamçılattılar ve İsanın adından söz etmemelerini buyurduktan sonra salıverdiler.'),
(2010109,68,44,5,41,'Elçiler İsanın adı uğruna hakarete layık görüldükleri için Yüksek Kurulun huzurundan sevinç içinde ayrıldılar.'),
(2010110,68,44,5,42,'Her gün tapınakta ve evlerde öğretmekten ve Mesih İsa''yla ilgili Müjde''yi yaymaktan geri kalmadılar.'),
(2010111,68,44,6,1,'İsanın öğrencilerinin sayıca çoğaldığı o günlerde, Grekçe konuşan Yahudiler, günlük yardım dağıtımında kendi dullarına gereken ilginin gösterilmediğini ileri sürerek İbranice konuşan Yahudilerden yakınmaya başladılar.'),
(2010112,68,44,6,2,'Bunun üzerine Onikiler, bütün öğrencileri bir araya toplayıp şöyle dediler: ‹‹Tanrının sözünü yayma işini bırakıp maddi işlerle uğraşmamız doğru olmaz.'),
(2010113,68,44,6,3,'Bu nedenle, kardeşler, aranızdan Ruhla ve bilgelikle dolu, yedi saygın kişi seçin. Onları bu iş için görevlendirelim.'),
(2010114,68,44,6,4,'Biz ise kendimizi duaya ve Tanrı sözünü yaymaya adayalım.››'),
(2010115,68,44,6,5,'Bu öneri bütün topluluğu hoşnut etti. Böylece, iman ve Kutsal Ruhla dolu biri olan İstefanosun yanısıra Filipus, Prohoros, Nikanor, Timon, Parmenas ve Yahudiliğe dönen Antakyalı Nikolası seçip elçilerin önüne çıkardılar. Elçiler de dua edip ellerini onların üzerine koydular.'),
(2010116,68,44,6,7,'Böylece Tanrının sözü yayılıyor, Yeruşalimdeki öğrencilerin sayısı arttıkça artıyor, kâhinlerden birçoğu da iman çağrısına uyuyordu.'),
(2010117,68,44,6,8,'Tanrının lütfuyla ve kudretle dolu olan İstefanos, halk arasında büyük belirtiler ve harikalar yapıyordu.'),
(2010118,68,44,6,9,'Ne var ki, Azatlılar Havrası diye bilinen havranın bazı üyeleri ve Kireneden, İskenderiyeden, Kilikyadan ve Asya İlinden bazı kişiler İstefanosla çekişmeye başladılar.'),
(2010119,68,44,6,10,'Ama İstefanosun konuşmasındaki bilgeliğe ve Ruha karşı koyamadılar.'),
(2010120,68,44,6,11,'Bunun üzerine birkaç kişiyi el altından ayartarak onlara, ‹‹Bu adamın Musaya ve Tanrıya karşı küfür dolu sözler söylediğini duyduk›› dedirttiler.'),
(2010121,68,44,6,12,'Böylelikle halkı, ileri gelenleri ve din bilginlerini kışkırttılar. Gidip İstefanosu yakaladılar ve Yüksek Kurulun önüne çıkardılar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010122,68,44,6,13,'Getirdikleri yalancı tanıklar, ‹‹Bu adam durmadan bu kutsal yere ve Yasaya karşı konuşuyor›› dediler.'),
(2010123,68,44,6,14,'‹‹ ‹Nasıralı İsa burayı yıkacak, Musanın bize emanet ettiği töreleri de değiştirecek› dediğini duyduk.››'),
(2010124,68,44,6,15,'Kurul''da oturanların hepsi, İstefanos''a baktıklarında yüzünün bir melek yüzüne benzediğini gördüler.'),
(2010125,68,44,7,1,'Başkâhin, ‹‹Bu iddialar doğru mu?›› diye sordu.'),
(2010126,68,44,7,2,'İstefanos şöyle karşılık verdi: ‹‹Kardeşler ve babalar, beni dinleyin. Atamız İbrahim daha Mezopotamyadayken, Harrana yerleşmeden önce, yüce Tanrı ona görünüp şöyle dedi: ‹Ülkeni, akrabalarını bırak, sana göstereceğim ülkeye git.›'),
(2010127,68,44,7,4,'‹‹Bunun üzerine İbrahim Kildanilerin ülkesini bırakıp Harrana yerleşti. Babasının ölümünden sonra da Tanrı onu oradan alıp şimdi sizin yaşadığınız bu ülkeye getirdi.'),
(2010128,68,44,7,5,'Burada ona herhangi bir miras, bir karış toprak bile vermemişti. Ama İbrahimin o sırada hiç çocuğu olmadığı halde, Tanrı bu ülkeyi mülk olarak ona ve ondan sonra gelecek torunlarına vereceğini vaat etti.'),
(2010129,68,44,7,6,'Tanrı şöyle dedi: ‹Senin soyun yabancı bir ülkede, gurbette yaşayacak. Dört yüz yıl köle olarak çalıştırılacak, baskı görecek.'),
(2010130,68,44,7,7,'Ama ben kölelik edecekleri ulusu cezalandıracağım. Bundan sonra oradan çıkacak ve bana bu yerde tapınacaklar.›'),
(2010131,68,44,7,8,'Sonra Tanrı onunla, sünnete dayalı antlaşmayı yaptı. Böylelikle İbrahim, İshakın babası oldu ve onu sekiz günlükken sünnet etti. Ve İshak Yakupun, Yakup da on iki büyük atamızın babası oldu.'),
(2010132,68,44,7,9,'‹‹Yusufu kıskanan atalarımız, onu köle olarak Mısıra sattılar. Ama Tanrı onunlaydı ve onu bütün sıkıntılarından kurtardı. Ona bilgelik vererek Mısır Firavununun gözüne girmesini sağladı. Firavun da onu Mısır ve bütün saray halkı üzerine yönetici atadı.'),
(2010133,68,44,7,11,'‹‹Sonra bütün Mısır ve Kenan ülkesini kıtlık vurdu, büyük sıkıntılar başladı. Atalarımız yiyecek bulamadılar.'),
(2010134,68,44,7,12,'Mısırda tahıl bulunduğunu duyan Yakup, atalarımızı oraya ilk yolculuklarına gönderdi.'),
(2010135,68,44,7,13,'Mısıra ikinci gelişlerinde Yusuf kardeşlerine kimliğini açıkladı. Firavun böylece Yusufun ailesini tanımış oldu.'),
(2010136,68,44,7,14,'Yusuf haber yollayıp babası Yakupu ve bütün akrabalarını, toplam yetmiş beş kişiyi çağırttı.'),
(2010137,68,44,7,15,'Böylece Yakup Mısıra gitti. Kendisi de atalarımız da orada öldüler.'),
(2010138,68,44,7,16,'Kemikleri sonra Şekeme getirilerek İbrahimin Şekemde Hamor oğullarından bir miktar gümüş karşılığında satın almış olduğu mezara konuldu.'),
(2010139,68,44,7,17,'‹‹Tanrının İbrahime verdiği sözün gerçekleşeceği zaman yaklaştığında, Mısırdaki halkımızın nüfusu bir hayli çoğalmıştı.'),
(2010140,68,44,7,18,'Sonunda Yusuf hakkında bilgisi olmayan yeni bir kral Mısırda tahta çıktı.'),
(2010141,68,44,7,19,'Bu adam, halkımıza karşı haince davrandı, atalarımıza kötülük etti. Onları, yeni doğan çocuklarını açıkta bırakıp ölüme terk etmeye zorladı.'),
(2010142,68,44,7,20,'‹‹O sırada, son derece güzel bir çocuk olan Musa doğdu. Musa, üç ay babasının evinde beslendikten sonra açıkta bırakıldı. Firavunun kızı onu bulup evlat edindi ve kendi oğlu olarak yetiştirdi.'),
(2010143,68,44,7,22,'Musa, Mısırlıların bütün bilim dallarında eğitildi. Gerek sözde, gerek eylemde güçlü biri oldu.'),
(2010144,68,44,7,23,'‹‹Kırk yaşını doldurunca Musanın yüreğinde öz kardeşleri İsrailoğullarının durumunu yakından görme arzusu doğdu.'),
(2010145,68,44,7,24,'Onlardan birine haksızlık edildiğini gören Musa, onu savundu. Haksızlığı yapan Mısırlıyı öldürerek ezilenin öcünü aldı.'),
(2010146,68,44,7,25,'‹Kardeşlerim Tanrının benim aracılığımla kendilerini kurtaracağını anlarlar› diye düşünüyordu. Ama onlar bunu anlamadılar.'),
(2010147,68,44,7,26,'Ertesi gün Musa, kavga eden iki İbraniyle karşılaşınca onları barıştırmak istedi. ‹Efendiler› dedi, ‹Siz kardeşsiniz. Niye birbirinize haksızlık ediyorsunuz?›'),
(2010148,68,44,7,27,'‹‹Ne var ki, soydaşına haksızlık eden kişi Musayı yana iterek, ‹Kim seni başımıza yönetici ve yargıç atadı?› dedi.'),
(2010149,68,44,7,28,'‹Yoksa dün Mısırlıyı öldürdüğün gibi beni de mi öldürmek istiyorsun?›'),
(2010150,68,44,7,29,'Bu söz üzerine Musa Midyan ülkesine kaçtı. Orada gurbette yaşadı ve iki oğul babası oldu.'),
(2010151,68,44,7,30,'‹‹Kırk yıl geçtikten sonra Musaya, Sina Dağının yakınlarındaki çölde, yanan bir çalının alevleri içinde bir melek göründü.'),
(2010152,68,44,7,31,'Musa gördüklerine şaştı. Daha yakından bakmak için yaklaştığında, Rab ona şöyle seslendi: ‹Senin atalarının Tanrısı, İbrahimin, İshakın ve Yakupun Tanrısı benim.› Korkuyla titreyen Musa bakmaya cesaret edemedi.'),
(2010153,68,44,7,33,'‹‹Sonra Rab, ‹Çarıklarını çıkar! Çünkü bastığın yer kutsal topraktır› dedi.'),
(2010154,68,44,7,34,'‹Mısırda halkıma yapılan baskıyı yakından gördüm, iniltilerini duydum ve onları kurtarmaya geldim. Şimdi gel, seni Mısıra göndereceğim.›'),
(2010155,68,44,7,35,'‹‹Bu Musa, ‹Kim seni yönetici ve yargıç atadı?› diye reddettikleri Musaydı. Tanrı onu, çalıda kendisine görünen meleğin aracılığıyla yönetici ve kurtarıcı olarak gönderdi.'),
(2010156,68,44,7,36,'Halkı Mısırdan çıkaran, orada, Kızıldenizde ve kırk yıl boyunca çölde belirtiler ve harikalar yapan oydu.'),
(2010157,68,44,7,37,'İsrailoğullarına, ‹Tanrı size kendi kardeşlerinizin arasından benim gibi bir peygamber çıkaracak› diyen Musa odur.'),
(2010158,68,44,7,38,'Çöldeki topluluğun arasında yaşamış, Sina Dağında kendisiyle konuşan melekle ve atalarımızla birlikte bulunmuş olan odur. Bize iletmek üzere yaşam dolu sözler aldı.'),
(2010159,68,44,7,39,'‹‹Ne var ki, atalarımız onun sözünü dinlemek istemediler. Onu reddettiler, Mısıra dönmeyi özler oldular.'),
(2010160,68,44,7,40,'Haruna, ‹Bize öncülük edecek ilahlar yap› dediler. ‹Çünkü bizi Mısırdan çıkaran o Musaya ne oldu bilmiyoruz!›'),
(2010161,68,44,7,41,'Ve o günlerde buzağı biçiminde bir put yapıp ona kurban sundular. Kendi elleriyle yaptıkları bu put için bir şenlik düzenlediler.'),
(2010162,68,44,7,42,'Bu yüzden Tanrı onlardan yüz çevirip onları göksel cisimlere kulluk etmeye terk etti. Peygamberlerin kitabında yazılmış olduğu gibi: ‹Ey İsrail halkı, Çölde kırk yıl boyunca Bana mı sunular, kurbanlar sundunuz?'),
(2010163,68,44,7,43,'Siz Molekin çadırını Ve ilahınız Refanın yıldızını taşıdınız. Tapınmak için yaptığınız putlardı bunlar. Bu yüzden sizi Babilin ötesine süreceğim.›'),
(2010164,68,44,7,44,'‹‹Çölde atalarımızın Tanıklık Çadırı vardı. Musa bunu, kendisiyle konuşan Tanrının buyurduğu gibi, gördüğü örneğe göre yapmıştı.'),
(2010165,68,44,7,45,'Tanıklık Çadırını önceki kuşaktan teslim alan atalarımız, Yeşunun önderliğinde öteki ulusların topraklarını ele geçirdikleri zaman, çadırı yanlarında getirdiler. Ulusları atalarımızın önünden kovan, Tanrının kendisiydi. Çadır Davutun zamanına dek kaldı.'),
(2010166,68,44,7,46,'Tanrının beğenisini kazanmış olan Davut, Yakupun Tanrısı için bir konut yapmaya izin istedi.'),
(2010167,68,44,7,47,'Oysa Tanrı için bir ev yapan Süleyman oldu.'),
(2010168,68,44,7,48,'‹‹Ne var ki, en yüce Olan, elle yapılmış konutlarda oturmaz. Peygamberin belirttiği gibi, ‹Gök tahtım, Yeryüzü ayaklarımın taburesidir. Benim için nasıl bir ev yapacaksınız? Ya da, neresi dinleneceğim yer? Bütün bunları yapan elim değil mi? diyor Rab.›'),
(2010169,68,44,7,51,'‹‹Ey dik kafalılar, yürekleri ve kulakları sünnet edilmemiş olanlar! Siz tıpkı atalarınıza benziyorsunuz, her zaman Kutsal Ruha karşı direniyorsunuz.'),
(2010170,68,44,7,52,'Atalarınız peygamberlerin hangisine zulmetmediler ki? Adil Olanın geleceğini önceden bildirenleri de öldürdüler. Melekler aracılığıyla buyrulan Yasayı alıp da buna uymayan sizler, şimdi de Adil Olana ihanet edip Onu katlettiniz!››'),
(2010171,68,44,7,54,'Kurul üyeleri bu sözleri duyunca öfkeden kudurdular, İstefanosa karşı dişlerini gıcırdattılar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010172,68,44,7,55,'Kutsal Ruhla dolu olan İstefanos ise, gözlerini göğe dikip Tanrının görkemini ve Tanrının sağında duran İsayı gördü.'),
(2010173,68,44,7,56,'‹‹Bakın›› dedi, ‹‹Göklerin açıldığını ve İnsanoğlunun Tanrının sağında durmakta olduğunu görüyorum.››'),
(2010174,68,44,7,57,'Bunun üzerine kulaklarını tıkayıp çığlıklar atarak hep birlikte İstefanosa saldırdılar.'),
(2010175,68,44,7,58,'Onu kentten dışarı atıp taşa tuttular. İstefanosa karşı tanıklık etmiş olanlar, kaftanlarını Saul adlı bir gencin ayaklarının dibine bıraktılar.'),
(2010176,68,44,7,59,'İstefanos taş yağmuru altında, ‹‹Rab İsa, ruhumu al!›› diye yakarıyordu.'),
(2010177,68,44,7,60,'Sonra diz çökerek yüksek sesle şöyle dedi: ‹‹Ya Rab, bu günahı onlara yükleme!›› Bunu söyledikten sonra gözlerini yaşama kapadı.'),
(2010178,68,44,8,1,'İstefanosun öldürülmesini Saul da onaylamıştı. O gün Yeruşalimdeki kiliseye karşı korkunç bir baskı dönemi başladı. Elçiler hariç bütün imanlılar Yahudiye ve Samiriyenin her yanına dağıldılar.'),
(2010179,68,44,8,2,'Bazı dindar kişiler, İstefanosu gömdükten sonra onun için büyük yas tuttular.'),
(2010180,68,44,8,3,'Saul ise inanlılar topluluğunu kırıp geçiriyordu. Ev ev dolaşarak, kadın erkek demeden imanlıları dışarı sürüklüyor, hapse atıyordu.'),
(2010181,68,44,8,4,'Bunun sonucu dağılan imanlılar, gittikleri her yerde Tanrı sözünü müjdeliyorlardı.'),
(2010182,68,44,8,5,'Filipus, Samiriye Kentine gidip oradakilere Mesihi tanıtmaya başladı.'),
(2010183,68,44,8,6,'Filipusu dinleyen ve gerçekleştirdiği belirtileri gören kalabalıklar, hep birlikte onun söylediklerine kulak verdiler.'),
(2010184,68,44,8,7,'Birçoklarının içinden kötü ruhlar yüksek sesle haykırarak çıktı; birçok felçli ve kötürüm iyileştirildi.'),
(2010185,68,44,8,8,'Ve o kentte büyük sevinç oldu.'),
(2010186,68,44,8,9,'Ne var ki, kentte bir süreden beri büyücülük yapan ve Samiriye halkını şaşkına çeviren Simun adlı biri vardı. Simun, büyük adam olduğunu iddia ediyordu.'),
(2010187,68,44,8,10,'Küçük büyük, herkes onu dikkatle dinler, ‹‹Büyük Güç dedikleri Tanrı gücü işte budur›› derlerdi.'),
(2010188,68,44,8,11,'Uzun zamandan beri onları büyücülüğüyle şaşkına çevirdiği için onu dikkatle dinlerlerdi.'),
(2010189,68,44,8,12,'Ama Tanrının Egemenliği ve İsa Mesih adıyla ilgili Müjdeyi duyuran Filipusun söylediklerine inandıkları zaman, erkekler de kadınlar da vaftiz oldular.'),
(2010190,68,44,8,13,'Simunun kendisi de inanıp vaftiz oldu. Ondan sonra sürekli olarak Filipusun yanında kaldı. Doğaüstü belirtileri ve yapılan büyük mucizeleri görünce şaşkına döndü.'),
(2010191,68,44,8,14,'Yeruşalimdeki elçiler, Samiriye halkının, Tanrının sözünü benimsediğini duyunca Petrusla Yuhannayı onlara gönderdiler.'),
(2010192,68,44,8,15,'Petrusla Yuhanna oraya varınca, Samiriyeli imanlıların Kutsal Ruhu almaları için dua ettiler.'),
(2010193,68,44,8,16,'Çünkü Ruh daha hiçbirinin üzerine inmemişti. Rab İsanın adıyla vaftiz olmuşlardı, o kadar.'),
(2010194,68,44,8,17,'Petrusla Yuhanna onların üzerine ellerini koyunca, onlar da Kutsal Ruhu aldılar.'),
(2010195,68,44,8,18,'Elçilerin bu el koyma hareketiyle Kutsal Ruhun verildiğini gören Simun onlara para teklif ederek, ‹‹Bana da bu yetkiyi verin, kimin üzerine ellerimi koysam Kutsal Ruhu alsın›› dedi.'),
(2010196,68,44,8,20,'Petrus, ‹‹Paran da yok olsun, sen de!›› dedi, ‹‹Çünkü Tanrının armağanını parayla elde edebileceğini sandın.'),
(2010197,68,44,8,21,'Senin bu işte bir payın, bir hakkın yok. Yüreğin, Tanrının gözünde doğru değildir.'),
(2010198,68,44,8,22,'Bu kötülüğünden tövbe et ve Rabbe yalvar, yüreğindeki bu düşünce belki bağışlanır.'),
(2010199,68,44,8,23,'Senin kin dolu, kötülüğe tutsak biri olduğunu görüyorum.››'),
(2010200,68,44,8,24,'Simun, ‹‹Benim için Rabbe yalvarın da söylediklerinizden hiçbiri başıma gelmesin›› diye karşılık verdi.'),
(2010201,68,44,8,25,'Petrusla Yuhanna tanıklık edip Rabbin sözünü bildirdikten sonra, Samiriyenin birçok köyünde de Müjdeyi duyura duyura Yeruşalime döndüler.'),
(2010202,68,44,8,26,'Bu arada Rabbin bir meleği Filipusa şöyle seslendi: ‹‹Kalk, güneye doğru, Yeruşalimden Gazzeye inen yola, çöl yoluna git.››'),
(2010203,68,44,8,27,'Filipus da kalkıp gitti. Giderken Etiyopyalı bir hadım gördü. Bu adam Etiyopya Kraliçesi Kandakinin vezirlerinden biriydi. Kraliçenin bütün hazinelerinden sorumluydu. Yeruşalime, tapınmaya gelmişti.'),
(2010204,68,44,8,28,'Geri dönerken arabasında oturmuş, Peygamber Yeşayanın Kitabını okuyordu.'),
(2010205,68,44,8,29,'Ruh Filipusa, ‹‹Git›› dedi, ‹‹Şu arabaya yetiş.››'),
(2010206,68,44,8,30,'Filipus koşup arabanın yanına geldi ve hadımın Peygamber Yeşayayı okumakta olduğunu işitti. ‹‹Acaba okuduklarını anlıyor musun?›› diye sordu.'),
(2010207,68,44,8,31,'Hadım, ‹‹Biri bana yol göstermedikçe nasıl anlayabilirim ki?›› diyerek Filipusun arabaya binip yanına oturmasını rica etti.'),
(2010208,68,44,8,32,'Kutsal Yazılardan okuduğu bölüm şuydu: ‹‹Koyun gibi kesime götürüldü; Kırkıcının önünde kuzu nasıl ses çıkarmazsa, O da öylece ağzını açmadı.'),
(2010209,68,44,8,33,'Aşağılandığında adalet Ondan esirgendi. Onun soyunu kim anacak? Çünkü yeryüzündeki yaşamına son verildi.››'),
(2010210,68,44,8,34,'Hadım Filipusa, ‹‹Lütfen açıklar mısın, peygamber kimden söz ediyor, kendisinden mi, bir başkasından mı?›› diye sordu.'),
(2010211,68,44,8,35,'Bunun üzerine Filipus anlatmaya koyuldu. Kutsal Yazıların bu bölümünden başlayarak ona İsayla ilgili Müjdeyi bildirdi.'),
(2010212,68,44,8,36,'Yolda giderlerken su bulunan bir yere geldiler. Hadım, ‹‹Bak, burada su var›› dedi. ‹‹Vaftiz olmama ne engel var?››'),
(2010213,68,44,8,38,'Sonra arabanın durmasını buyurdu. Filipusla hadım birlikte suya girdiler ve Filipus hadımı vaftiz etti.'),
(2010214,68,44,8,39,'Sudan çıktıkları zaman Rabbin Ruhu Filipusu hemen oradan uzaklaştırdı. Filipusu bir daha görmeyen hadım sevinç içinde yoluna devam etti.'),
(2010215,68,44,8,40,'Filipus ise kendini Aşdot Kenti''nde buldu. Sezariye''ye varıncaya dek bütün kentleri dolaşarak Müjde''yi duyurdu.'),
(2010216,68,44,9,1,'Saul ise Rabbin öğrencilerine karşı hâlâ tehdit ve ölüm soluyordu. Başkâhine gitti, Şamdaki havralara verilmek üzere mektuplar yazmasını istedi. Orada İsanın yolunda yürüyen kadın erkek, kimi bulsa tutuklayıp Yeruşalime getirmek niyetindeydi.'),
(2010217,68,44,9,3,'Yol alıp Şama yaklaştığı sırada, birdenbire gökten gelen bir ışık çevresini aydınlattı.'),
(2010218,68,44,9,4,'Yere yıkılan Saul, bir sesin kendisine, ‹‹Saul, Saul, neden bana zulmediyorsun?›› dediğini işitti.'),
(2010219,68,44,9,5,'Saul, ‹‹Ey Efendim, sen kimsin?›› dedi. ‹‹Ben senin zulmettiğin İsayım›› diye yanıt geldi.'),
(2010220,68,44,9,6,'‹‹Haydi kalk ve kente gir, ne yapman gerektiği sana bildirilecek.››'),
(2010221,68,44,9,7,'Saulla birlikte yolculuk eden adamların dilleri tutuldu, oldukları yerde kalakaldılar. Sesi duydularsa da, kimseyi göremediler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010222,68,44,9,8,'Saul yerden kalktı, ama gözlerini açtığında hiçbir şey göremiyordu. Sonra kendisini elinden tutup Şama götürdüler.'),
(2010223,68,44,9,9,'Üç gün boyunca gözleri görmeyen Saul hiçbir şey yiyip içmedi.'),
(2010224,68,44,9,10,'Şamda Hananya adında bir İsa öğrencisi vardı. Bir görümde Rab ona, ‹‹Hananya!›› diye seslendi. ‹‹Buradayım, ya Rab›› dedi Hananya.'),
(2010225,68,44,9,11,'Rab ona, ‹‹Kalk›› dedi, ‹‹Doğru Sokak denilen sokağa git ve Yahudanın evinde Saul adında Tarsuslu birini sor. Şu anda orada dua ediyor.'),
(2010226,68,44,9,12,'Görümünde yanına Hananya adlı birinin geldiğini ve gözlerini açmak için ellerini kendisinin üzerine koyduğunu görmüştür.››'),
(2010227,68,44,9,13,'Hananya şöyle karşılık verdi: ‹‹Ya Rab, birçoklarının bu adam hakkında neler anlattıklarını duydum. Yeruşalimde senin kutsallarına nice kötülük yapmış!'),
(2010228,68,44,9,14,'Burada da senin adını anan herkesi tutuklamak için başkâhinlerden yetki almıştır.››'),
(2010229,68,44,9,15,'Rab ona, ‹‹Git!›› dedi. ‹‹Bu adam, benim adımı öteki uluslara, krallara ve İsrailoğullarına duyurmak üzere seçilmiş bir aracımdır.'),
(2010230,68,44,9,16,'Benim adım uğruna ne kadar sıkıntı çekmesi gerekeceğini ona göstereceğim.››'),
(2010231,68,44,9,17,'Bunun üzerine Hananya gitti, eve girdi ve ellerini Saulun üzerine koydu. ‹‹Saul kardeş›› dedi, ‹‹Sen buraya gelirken yolda sana görünen Rab, yani İsa, gözlerin açılsın ve Kutsal Ruhla dolasın diye beni yolladı.››'),
(2010232,68,44,9,18,'O anda Saulun gözlerinden balık pulunu andıran şeyler düştü. Saul yeniden görmeye başladı. Kalkıp vaftiz oldu.'),
(2010233,68,44,9,19,'Sonra yemek yiyip kuvvet buldu. Saul birkaç gün Şamdaki öğrencilerin yanında kaldı.'),
(2010234,68,44,9,20,'Havralarda İsanın Tanrının Oğlu olduğunu hemen duyurmaya başladı.'),
(2010235,68,44,9,21,'Onu duyanların hepsi şaşkına döndü. ‹‹Yeruşalimde bu adı ananları kırıp geçiren adam bu değil mi? Buraya da, öylelerini tutuklayıp başkâhinlere götürmek amacıyla gelmedi mi?›› diyorlardı.'),
(2010236,68,44,9,22,'Saul ise günden güne güçleniyordu. İsanın Mesih olduğuna dair kanıtlar göstererek Şamda yaşayan Yahudileri şaşkına çeviriyordu.'),
(2010237,68,44,9,23,'Aradan günler geçti. Yahudiler Saulu öldürmek için bir düzen kurdular.'),
(2010238,68,44,9,24,'Ne var ki, kurdukları düzenle ilgili haber Saula ulaştı. Yahudiler onu öldürmek için gece gündüz kentin kapılarını gözlüyorlardı.'),
(2010239,68,44,9,25,'Ama Saulun öğrencileri geceleyin kendisini aldılar, kentin surlarından sarkıttıkları bir küfe içinde aşağı indirdiler.'),
(2010240,68,44,9,26,'Saul Yeruşalime varınca oradaki öğrencilere katılmaya çalıştı. Ama hepsi ondan korkuyor, İsanın öğrencisi olduğuna inanamıyorlardı.'),
(2010241,68,44,9,27,'O zaman Barnaba onu alıp elçilere götürdü. Onlara, Saulun Şam yolunda Rabbi nasıl gördüğünü, Rabbin de onunla konuştuğunu, Şamda ise onun İsa adını nasıl korkusuzca duyurduğunu anlattı.'),
(2010242,68,44,9,28,'Böylelikle Saul, Yeruşalimde girip çıktıkları her yerde öğrencilerle birlikte bulunarak Rabbin adını korkusuzca duyurmaya başladı.'),
(2010243,68,44,9,29,'Dili Grekçe olan Yahudilerle konuşup tartışıyordu. Ama onlar onu öldürmeyi tasarlıyorlardı.'),
(2010244,68,44,9,30,'Kardeşler bunu öğrenince onu Sezariyeye götürüp oradan Tarsusa yolladılar.'),
(2010245,68,44,9,31,'Bütün Yahudiye, Celile ve Samiriyedeki inanlılar topluluğu esenliğe kavuştu. Gelişen ve Rab korkusu içinde yaşayan topluluk Kutsal Ruhun yardımıyla sayıca büyüyordu.'),
(2010246,68,44,9,32,'Bu arada her tarafı dolaşan Petrus, Liddada yaşayan kutsallara da uğradı.'),
(2010247,68,44,9,33,'Orada Eneas adında birine rastladı. Eneas felçliydi. Sekiz yıldan beri yatalaktı.'),
(2010248,68,44,9,34,'Petrus ona, ‹‹Eneas, İsa Mesih seni iyileştiriyor›› dedi. ‹‹Kalk, yatağını topla.›› Eneas hemen ayağa kalktı.'),
(2010249,68,44,9,35,'Lidda ve Şaronda yaşayan herkes onu gördü ve Rabbe döndü.'),
(2010250,68,44,9,36,'Yafada, İsa öğrencisi olan Tabita adında bir kadın vardı. Tabita, ceylan anlamına gelir. Bu kadın her zaman iyilik yapıp yoksullara yardım ederdi.'),
(2010251,68,44,9,37,'O günlerde hastalanıp öldü. Ölüsünü yıkayıp üst kattaki odaya koydular.'),
(2010252,68,44,9,38,'Lidda Yafaya yakın olduğundan, Petrusun Liddada bulunduğunu duyan öğrenciler ona iki kişi yollayıp, ‹‹Vakit kaybetmeden yanımıza gel›› diye yalvardılar.'),
(2010253,68,44,9,39,'Petrus kalkıp onlarla birlikte gitti. Eve varınca onu üst kattaki odaya çıkardılar. Bütün dul kadınlar ağlayarak Petrusun çevresinde toplandılar. Ona, Ceylanın kendileriyle birlikteyken diktiği entarilerle üstlükleri gösterdiler.'),
(2010254,68,44,9,40,'Petrus, herkesi dışarı çıkarttı, diz çöküp dua etti. Sonra ölüye doğru dönerek, ‹‹Tabita, kalk›› dedi. Kadın gözlerini açtı, Petrusu görünce doğrulup oturdu.'),
(2010255,68,44,9,41,'Petrus elini uzatarak onu ayağa kaldırdı. Sonra kutsallarla dul kadınları çağırdı, Ceylanı diri olarak onlara teslim etti.'),
(2010256,68,44,9,42,'Bu olayın haberi bütün Yafaya yayıldı ve birçokları Rabbe inandı.'),
(2010257,68,44,9,43,'Petrus uzunca bir süre Yafa''da, Simun adında bir dericinin evinde kaldı.'),
(2010258,68,44,10,1,'Sezariyede Kornelius adında bir adam vardı. ‹‹İtalyan›› taburunda yüzbaşıydı.'),
(2010259,68,44,10,2,'Dindar bir adamdı. Hem kendisi hem de bütün ev halkı Tanrıdan korkardı. Halka çok yardımda bulunur, Tanrıya sürekli dua ederdi.'),
(2010260,68,44,10,3,'Bir gün saat üç sularında, bir görümde Tanrının bir meleğinin kendisine geldiğini açıkça gördü. Melek ona, ‹‹Kornelius›› diye seslendi.'),
(2010261,68,44,10,4,'Kornelius korku içinde gözlerini ona dikti, ‹‹Ne var, efendim?›› dedi. Melek ona şöyle dedi: ‹‹Duaların ve sadakaların anılmak üzere Tanrı katına ulaştı.'),
(2010262,68,44,10,5,'Şimdi Yafaya adam yolla, Petrus olarak da tanınan Simunu çağırt.'),
(2010263,68,44,10,6,'Petrus, evi deniz kıyısında bulunan Simun adlı bir dericinin yanında kalıyor.››'),
(2010264,68,44,10,7,'Kendisiyle konuşan melek uzaklaştıktan sonra Kornelius, iki uşağıyla özel yardımcılarından dindar bir askeri çağırdı.'),
(2010265,68,44,10,8,'Kendilerine her şeyi anlattıktan sonra onları Yafaya gönderdi.'),
(2010266,68,44,10,9,'Ertesi gün onlar yol alıp kente yaklaşırlarken, saat on iki sularında Petrus dua etmek için dama çıktı.'),
(2010267,68,44,10,10,'Acıkınca da yemek istedi. Yemek hazırlanırken Petrus kendinden geçti.'),
(2010268,68,44,10,11,'Göğün açıldığını ve büyük bir çarşafı andıran bir nesnenin dört köşesinden sarkıtılarak yeryüzüne indirildiğini gördü.'),
(2010269,68,44,10,12,'Çarşafın içinde, yeryüzünde yaşayan her türden dört ayaklı hayvanlar, sürüngenler ve kuşlar vardı.'),
(2010270,68,44,10,13,'Bir ses ona, ‹‹Kalk Petrus, kes ve ye!›› dedi.'),
(2010271,68,44,10,14,'‹‹Asla olmaz, ya Rab!›› dedi Petrus. ‹‹Hiçbir zaman bayağı ya da murdar herhangi bir şey yemedim.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010272,68,44,10,15,'Ses tekrar, ikinci kez duyuldu; Petrusa, ‹‹Tanrının temiz kıldıklarına sen bayağı deme›› dedi.'),
(2010273,68,44,10,16,'Bu, üç kez tekrarlandı. Sonra çarşafı andıran nesne hemen göğe alındı.'),
(2010274,68,44,10,17,'Petrus şaşkınlık içindeydi. Gördüğü görümün ne anlama gelebileceğini düşünürken, Korneliusun gönderdiği adamlar sora sora Simunun evinin kapısına kadar geldiler.'),
(2010275,68,44,10,18,'Evdekilere seslenerek, ‹‹Petrus diye tanınan Simun burada mı kalıyor?›› diye sordular.'),
(2010276,68,44,10,19,'Petrus hâlâ görümün anlamını düşünürken Ruh ona, ‹‹Bak, üç kişi seni arıyor›› dedi.'),
(2010277,68,44,10,20,'‹‹Haydi kalk, aşağı in. Hiç çekinmeden onlarla git. Çünkü onları ben gönderdim.››'),
(2010278,68,44,10,21,'Petrus aşağı inip adamlara, ‹‹Aradığınız kişi benim›› dedi. ‹‹Gelişinizin sebebi ne acaba?››'),
(2010279,68,44,10,22,'‹‹Doğru ve Tanrıdan korkan, bütün Yahudi ulusunca iyiliğiyle tanınan, Kornelius adında bir yüzbaşı var›› dediler. ‹‹Kutsal bir melek ona, seni evine çağırtıp senin söyleyeceklerini dinlemesini buyurdu.››'),
(2010280,68,44,10,23,'Bunun üzerine Petrus onları içeri alıp konuk etti. Ertesi gün Petrus kalktı, onlarla birlikte yola çıktı. Yafadaki kardeşlerden bazıları da ona katıldı.'),
(2010281,68,44,10,24,'İkinci gün Sezariyeye vardılar. Bu arada Kornelius, akraba ve yakın dostlarını toplamış onları bekliyordu.'),
(2010282,68,44,10,25,'Eve giren Petrusu karşıladı, tapınırcasına ayaklarına kapandı.'),
(2010283,68,44,10,26,'Petrus ise onu ayağa kaldırarak, ‹‹Kalk, ben de insanım›› dedi.'),
(2010284,68,44,10,27,'Petrus Korneliusla konuşa konuşa içeri girdiğinde birçok insanın toplanmış olduğunu gördü.'),
(2010285,68,44,10,28,'Onlara şöyle dedi: ‹‹Bir Yahudinin başka ulustan biriyle ilişki kurmasının, onu ziyaret etmesinin töremize aykırı olduğunu bilirsiniz. Oysa Tanrı bana, hiç kimseye bayağı ya da murdar dememem gerektiğini gösterdi.'),
(2010286,68,44,10,29,'Bu nedenle, çağrıldığım zaman hiç itiraz etmeden geldim. Şimdi, beni ne amaçla çağırttığınızı sorabilir miyim?››'),
(2010287,68,44,10,30,'Kornelius, ‹‹Üç gün önce bu sıralarda, saat üçte evimde dua ediyordum›› dedi. ‹‹Birdenbire, parlak giysili bir adam önüme çıkıverdi.'),
(2010288,68,44,10,31,'‹Kornelius› dedi, ‹Tanrı senin duanı işitti, verdiğin sadakaları andı.'),
(2010289,68,44,10,32,'Yafaya adam yolla, Petrus diye tanınan Simunu çağırt. O, deniz kıyısında oturan derici Simunun evinde kalıyor.›'),
(2010290,68,44,10,33,'Bunun üzerine sana hemen adam yolladım. Sen de lütfedip geldin. İşte şimdi biz hepimiz, Rabbin sana buyurduğu her şeyi dinlemek üzere Tanrının önünde toplanmış bulunuyoruz.››'),
(2010291,68,44,10,34,'O zaman Petrus söz alıp şöyle dedi: ‹‹Tanrının insanlar arasında ayrım yapmadığını, ama kendisinden korkan ve doğru olanı yapan kişiyi, ulusuna bakmaksızın kabul ettiğini gerçekten anlıyorum.'),
(2010292,68,44,10,36,'Tanrının, herkesin Rabbi olan İsa Mesih aracılığıyla esenliği müjdeleyerek İsrailoğullarına ilettiği bildiriden haberiniz vardır.'),
(2010293,68,44,10,37,'Yahyanın vaftiz çağrısından sonra Celileden başlayarak bütün Yahudiyede meydana gelen olayları, Tanrının, Nasıralı İsayı nasıl Kutsal Ruhla ve kudretle meshettiğini biliyorsunuz. İsa her yanı dolaşarak iyilik yapıyor, İblisin baskısı altında olanların hepsini iyileştiriyordu. Çünkü Tanrı Onunla birlikteydi.'),
(2010294,68,44,10,39,'‹‹Biz İsanın, Yahudilerin ülkesinde ve Yeruşalimde yaptıklarının hepsine tanık olduk. Onu çarmıha gerip öldürdüler.'),
(2010295,68,44,10,40,'Ama Tanrı Onu üçüncü gün diriltti ve açıkça görünmesini sağladı.'),
(2010296,68,44,10,41,'İsa halkın tümüne değil de, Tanrının önceden seçtiği tanıklara -ölümden dirilmesinden sonra kendisiyle birlikte yiyip içen bizlere- göründü.'),
(2010297,68,44,10,42,'Tanrı tarafından ölülerle dirilerin Yargıcı olarak atanan kişinin kendisi olduğunu halka duyurmamızı, buna tanıklık etmemizi buyurdu.'),
(2010298,68,44,10,43,'Peygamberlerin hepsi Onunla ilgili tanıklıkta bulunuyorlar. Şöyle ki, Ona inanan herkesin günahları Onun adıyla bağışlanır.››'),
(2010299,68,44,10,44,'Petrus daha bu sözleri söylerken Kutsal Ruh, konuşmayı dinleyen herkesin üzerine indi.'),
(2010300,68,44,10,45,'Petrusla birlikte gelen Yahudi imanlılar, Kutsal Ruh armağanının öteki uluslardan olanların da üzerine dökülmesini şaşkınlıkla karşıladılar.'),
(2010301,68,44,10,46,'Çünkü onların, bilmedikleri dillerle konuşup Tanrıyı yücelttiklerini duyuyorlardı. O zaman Petrus, ‹‹Bunlar, tıpkı bizim gibi Kutsal Ruhu almışlar. Suyla vaftiz olmalarına kim engel olabilir?›› dedi.'),
(2010302,68,44,10,48,'Böylelikle onların İsa Mesih adıyla vaftiz olmalarını buyurdu. Sonra onlar Petrus''a, birkaç gün yanlarında kalması için ricada bulundular.'),
(2010303,68,44,11,1,'Elçilerle bütün Yahudiyedeki kardeşler, öteki ulusların da Tanrının sözünü kabul ettiklerini duydular.'),
(2010304,68,44,11,2,'Ama Petrus Yeruşalime gittiği zaman sünnet yanlıları onu eleştirdiler.'),
(2010305,68,44,11,3,'‹‹Sünnetsiz kişilerin evine gidip yemek yemişsin!›› dediler.'),
(2010306,68,44,11,4,'Petrus baştan başlayarak olanları tek tek onlara anlattı.'),
(2010307,68,44,11,5,'‹‹Ben Yafa Kentinde dua ediyordum›› dedi. ‹‹Kendimden geçerek bir görüm gördüm. Büyük bir çarşafı andıran bir nesnenin dört köşesinden sarkıtıldığını, bunun gökten inip benim bulunduğum yere kadar geldiğini gördüm.'),
(2010308,68,44,11,6,'Gözlerimi çarşafa dikip dikkatle baktım. Çarşafın içinde, yeryüzünde yaşayan dört ayaklılar, yabanıl hayvanlar, sürüngenler ve kuşlar gördüm.'),
(2010309,68,44,11,7,'Sonra bir sesin bana, ‹Kalk, Petrus, kes ve ye!› dediğini işittim.'),
(2010310,68,44,11,8,'‹‹ ‹Asla olmaz, ya Rab!› dedim. ‹Ağzıma hiçbir zaman bayağı ya da murdar bir şey girmedi.›'),
(2010311,68,44,11,9,'‹‹Ses ikinci kez gökten geldi: ‹Tanrının temiz kıldıklarına sen bayağı deme› dedi.'),
(2010312,68,44,11,10,'Bu, üç kez tekrarlandı; sonra her şey yeniden göğe alındı.'),
(2010313,68,44,11,11,'‹‹Tam o sırada Sezariyeden bana gönderilen üç kişi, bulunduğumuz evin önünde durdular.'),
(2010314,68,44,11,12,'Ruh bana, ayrım gözetmeden onlarla birlikte gitmemi söyledi. Bu altı kardeş de benimle geldiler, varıp adamın evine girdik.'),
(2010315,68,44,11,13,'Adam bize, evinde beliren meleği nasıl gördüğünü anlattı. Melek ona şöyle demiş: ‹Yafaya adam yolla, Petrus diye tanınan Simunu çağırt.'),
(2010316,68,44,11,14,'O sana, senin ve bütün ev halkının kurtuluş bulacağı sözler söyleyecek.›'),
(2010317,68,44,11,15,'‹‹Ben konuşmaya başlayınca Kutsal Ruh, başlangıçta bizim üzerimize indiği gibi, onların da üzerine indi.'),
(2010318,68,44,11,16,'O zaman Rabbin söylediği şu sözü anımsadım: ‹Yahya suyla vaftiz etti, sizler ise Kutsal Ruhla vaftiz edileceksiniz.›'),
(2010319,68,44,11,17,'Böylelikle Tanrı, Rab İsa Mesihe inanmış olan bizlere verdiği armağanın aynısını onlara verdiyse, ben kimim ki Tanrıya karşı koyayım?››'),
(2010320,68,44,11,18,'Bunları dinledikten sonra yatıştılar. Tanrıyı yücelterek şöyle dediler: ‹‹Demek ki Tanrı, tövbe etme ve yaşama kavuşma fırsatını öteki uluslara da vermiştir.››'),
(2010321,68,44,11,19,'İstefanosun öldürülmesiyle başlayan baskı sonucu dağılan imanlılar, Fenike, Kıbrıs ve Antakyaya kadar gittiler. Tanrı sözünü sadece Yahudilere duyuruyorlardı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010322,68,44,11,20,'Ama içlerinden Kıbrıslı ve Kireneli olan bazı adamlar Antakyaya gidip Greklerle de konuşmaya başladılar. Onlara Rab İsayla ilgili Müjdeyi bildirdiler.'),
(2010323,68,44,11,21,'Onların arasında etkin olan Rabbin gücü sayesinde çok sayıda kişi inanıp Rabbe döndü.'),
(2010324,68,44,11,22,'Olup bitenlerin haberi, Yeruşalimdeki kiliseye ulaştı. Bunun üzerine imanlılar Barnabayı Antakyaya gönderdiler.'),
(2010325,68,44,11,23,'Kutsal Ruhla ve imanla dolu, iyi bir adam olan Barnaba, Antakyaya varıp Tanrı lütfunun meyvelerini görünce sevindi. Herkesi, candan ve yürekten Rabbe bağlı kalmaya özendirdi. Sonuç olarak Rabbe daha birçok kişi kazanıldı.'),
(2010326,68,44,11,25,'Sonra Barnaba, Saulu aramak için Tarsusa gitti. Onu bulunca da Antakyaya getirdi. Böylece Barnabayla Saul bir yıl boyunca oradaki inanlılar topluluğuyla bir araya gelerek büyük bir kitleyi eğittiler. Öğrencilere ilk kez Antakyada Mesihçiler adı verildi.'),
(2010327,68,44,11,27,'O günlerde Yeruşalimden Antakyaya bazı peygamberler geldi.'),
(2010328,68,44,11,28,'Bunlardan Hagavos adlı biri ortaya çıkıp bütün dünyada şiddetli bir kıtlık olacağını Ruh aracılığıyla bildirdi. Bu kıtlık, Klavdiusun imparatorluğu sırasında oldu.'),
(2010329,68,44,11,29,'Öğrenciler, her biri kendi gücü oranında, Yahudiyede yaşayan kardeşlere gönderilmek üzere yardım toplamayı kararlaştırdılar.'),
(2010330,68,44,11,30,'Bu kararı yerine getirip bağışlarını Barnaba ve Saul''un eliyle kilisenin ihtiyarlarına gönderdiler.'),
(2010331,68,44,12,1,'O sırada kral Hirodes, kiliseden bazı kişilere eziyet etmeye başladı.'),
(2010332,68,44,12,2,'Yuhannanın kardeşi Yakupu kılıçla öldürttü.'),
(2010333,68,44,12,3,'Yahudilerin bundan memnun kaldığını görünce ardından Petrusu da yakalattı. Bunu, Mayasız Ekmek Bayramı sırasında yaptı.'),
(2010334,68,44,12,4,'Petrusu tutuklatıp hapse attırdı ve dörder kişilik dört takım askerin gözetimine teslim etti. Fısıh Bayramından sonra onu halkın önünde yargılamak niyetindeydi.'),
(2010335,68,44,12,5,'Bu nedenle Petrus hapiste tutuldu. Ama inanlılar topluluğu onun için Tanrıya hararetle dua ediyordu.'),
(2010336,68,44,12,6,'Petrus, Hirodesin kendisini yargılayacağı günden önceki gece, çift zincirle bağlı olarak iki askerin arasında uyuyordu. Kapıda duran nöbetçiler de zindanın güvenliğini sağlıyordu.'),
(2010337,68,44,12,7,'Birdenbire Rabbin bir meleği göründü ve hücrede bir ışık parladı. Melek, Petrusun böğrüne dokunup onu uyandırdı. ‹‹Çabuk, kalk!›› dedi. O anda zincirler Petrusun bileklerinden düştü.'),
(2010338,68,44,12,8,'Melek ona, ‹‹Kuşağını bağla, çarıklarını giy›› dedi. Petrus da söyleneni yaptı. ‹‹Abanı giy, beni izle›› dedi melek.'),
(2010339,68,44,12,9,'Petrus onu izleyerek dışarı çıktı. Ama meleğin yaptığının gerçek olduğunu anlamıyor, bir görüm gördüğünü sanıyordu.'),
(2010340,68,44,12,10,'Birinci ve ikinci nöbetçiyi geçerek kente açılan demir kapıya geldiler. Kapı, önlerinde kendiliğinden açıldı. Dışarı çıkıp bir sokak boyunca yürüdüler, sonra melek ansızın Petrusun yanından ayrıldı.'),
(2010341,68,44,12,11,'O zaman kendine gelen Petrus, ‹‹Rabbin bana meleğini gönderdiğini şimdi gerçekten anlıyorum›› dedi. ‹‹O beni Hirodesin elinden ve Yahudi halkının uğrayacağımı umduğu bütün belalardan kurtardı.››'),
(2010342,68,44,12,12,'Petrus olanların farkına varınca Markos diye tanınan Yuhannanın annesi Meryemin evine gitti. Orada birçok kişi toplanmış dua ediyordu.'),
(2010343,68,44,12,13,'Petrusun dış kapıyı çalması üzerine Roda adlı bir hizmetçi kız kapıya bakmaya gitti.'),
(2010344,68,44,12,14,'Petrusun sesini tanıyan kız, sevincinden kapıyı açmadan tekrar içeri koşarak, ‹‹Petrus kapıda duruyor!›› diye haber verdi.'),
(2010345,68,44,12,15,'‹‹Çıldırmışsın sen!›› dediler ona. Ama kız üsteleyince, ‹‹Onun meleği olmalı›› dediler.'),
(2010346,68,44,12,16,'Petrus ise kapıyı çalmaya devam etti. Kapıyı açıp onu görünce şaşıp kaldılar.'),
(2010347,68,44,12,17,'Petrus, eliyle susmalarını işaret ederek Rabbin onu zindandan nasıl çıkardığını anlattı. Sonra, ‹‹Bu haberleri Yakupla öbür kardeşlere iletin›› diyerek oradan ayrılıp başka bir yere gitti.'),
(2010348,68,44,12,18,'Askerler sabahleyin büyük bir telaşa kapıldılar. Birbirlerine, ‹‹Petrusa ne oldu?›› diye sordular.'),
(2010349,68,44,12,19,'Hirodes onu arattı, bulamayınca da nöbetçileri sorguya çekti ve idam edilmeleri için buyruk verdi. Bundan sonra Hirodes, Yahudiyeden Sezariyeye gidip bir süre orada kaldı.'),
(2010350,68,44,12,20,'Bu arada Sur ve Sayda halklarına ateş püskürüyordu. Bunlar birleşip kendisiyle görüşmeye geldiler. Önce kralın başdanışmanı Vlastusu kendi taraflarına çekerek barış isteğinde bulundular. Çünkü kendi ülkelerinin gereksindiği yiyecekler kralın ülkesinden sağlanıyordu.'),
(2010351,68,44,12,21,'Belirlenen günde krallık giysilerini giyen Hirodes tahtına oturarak halka bir konuşma yaptı.'),
(2010352,68,44,12,22,'Halk, ‹‹Bu bir insanın sesi değil, bir ilahın sesidir!›› diye bağırıyordu.'),
(2010353,68,44,12,23,'O anda Rabbin bir meleği Hirodesi vurdu. Çünkü Tanrıya ait olan yüceliği kendine mal etmişti. İçi kurtlarca kemirilerek can verdi.'),
(2010354,68,44,12,24,'Tanrının sözü ise yayılıyor, etkisini artırıyordu.'),
(2010355,68,44,12,25,'Görevlerini tamamlayan Barnaba''yla Saul, Markos diye tanınan Yuhanna''yı yanlarına alarak Yeruşalim''den döndüler.'),
(2010356,68,44,13,1,'Antakyadaki kilisede peygamberler ve öğretmenler vardı: Barnaba, Niger denilen Şimon, Kireneli Lukius, bölge kralı Hirodesle birlikte büyümüş olan Menahem ve Saul.'),
(2010357,68,44,13,2,'Bunlar Rabbe tapınıp oruç tutarlarken Kutsal Ruh kendilerine şöyle dedi: ‹‹Barnabayla Saulu, kendilerini çağırmış olduğum görev için bana ayırın.››'),
(2010358,68,44,13,3,'Böylece oruç tutup dua ettikten sonra, Barnabayla Saulun üzerine ellerini koyup onları yolcu ettiler.'),
(2010359,68,44,13,4,'Kutsal Ruhun buyruğuyla yola çıkan Barnabayla Saul, Selefkiyeye gittiler, oradan da gemiyle Kıbrısa geçtiler.'),
(2010360,68,44,13,5,'Salamise varınca Yahudilerin havralarında Tanrının sözünü duyurmaya başladılar. Yuhannayı da yardımcı olarak yanlarına almışlardı.'),
(2010361,68,44,13,6,'Adayı baştan başa geçerek Bafa geldiler. Orada büyücü ve sahte peygamber Baryeşu adında bir Yahudiyle karşılaştılar.'),
(2010362,68,44,13,7,'Baryeşu, Vali Sergius Pavlusa yakın biriydi. Akıllı bir kişi olan vali, Barnabayla Saulu çağırtıp Tanrının sözünü dinlemek istedi. Ne var ki Baryeşu -büyücü anlamına gelen öbür adıyla Elimas- onlara karşı koyarak valiyi iman etmekten caydırmaya çalıştı.'),
(2010363,68,44,13,9,'Ama Kutsal Ruhla dolan Saul, yani Pavlus, gözlerini Elimasa dikerek, ‹‹Ey İblisin oğlu!›› dedi. ‹‹Yüreğin her türlü hile ve sahtekârlıkla dolu; doğru olan her şeyin düşmanısın. Rabbin düz yollarını çarpıtmaktan vazgeçmeyecek misin?'),
(2010364,68,44,13,11,'İşte şimdi Rabbin eli sana karşı kalktı. Kör olacaksın, bir süre gün ışığını göremeyeceksin.›› O anda adamın üzerine bir sis, bir karanlık çöktü. Dört dönerek, elinden tutup kendisine yol gösterecek birilerini aramaya başladı.'),
(2010365,68,44,13,12,'Olanları gören vali, Rable ilgili öğretiyi hayranlıkla karşıladı ve iman etti.'),
(2010366,68,44,13,13,'Pavlusla beraberindekiler Baftan denize açılıp Pamfilya bölgesinin Perge Kentine gittiler. Yuhanna ise onları bırakıp Yeruşalime döndü.'),
(2010367,68,44,13,14,'Onlar Pergeden yollarına devam ederek Pisidya sınırındaki Antakyaya geçtiler. Şabat Günü havraya girip oturdular.'),
(2010368,68,44,13,15,'Kutsal Yasa ve peygamberlerin yazıları okunduktan sonra, havranın yöneticileri onlara, ‹‹Kardeşler, halka verecek bir öğüdünüz varsa buyurun, konuşun›› diye haber yolladılar.'),
(2010369,68,44,13,16,'Pavlus ayağa kalktı, eliyle bir işaret yaparak, ‹‹Ey İsrailliler ve Tanrıdan korkan yabancılar, dinleyin›› dedi.'),
(2010370,68,44,13,17,'‹‹Bu halkın, yani İsrailin Tanrısı, bizim atalarımızı seçti ve Mısırda gurbette yaşadıkları süre içinde onları büyük bir ulus yaptı. Sonra güçlü eliyle onları oradan çıkardı, çölde yaklaşık kırk yıl onlara katlandı.'),
(2010371,68,44,13,19,'Kenan ülkesinde yenilgiye uğrattığı yedi ulusun topraklarını İsrail halkına miras olarak verdi. Bütün bunlar aşağı yukarı dört yüz elli yıl sürdü. ‹‹Sonra Tanrı, Peygamber Samuelin zamanına kadar onlar için hakimler yetiştirdi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010372,68,44,13,21,'Halk bir kral isteyince, Tanrı onlar için Benyamin oymağından Kiş oğlu Saulu yetiştirdi. Saul kırk yıl krallık yaptı.'),
(2010373,68,44,13,22,'Tanrı, onu tahttan indirdikten sonra onlara kral olarak Davutu başa geçirdi. Onunla ilgili şu tanıklıkta bulundu: ‹İşay oğlu Davutu gönlüme uygun bir adam olarak gördüm, o her istediğimi yapar.›'),
(2010374,68,44,13,23,'Tanrı, verdiği sözü tutarak bu adamın soyundan İsraile bir Kurtarıcı, İsayı gönderdi.'),
(2010375,68,44,13,24,'İsanın gelişinden önce Yahya, bütün İsrail halkını, tövbe edip vaftiz olmaya çağırdı.'),
(2010376,68,44,13,25,'Yahya görevini tamamlarken şöyle diyordu: ‹Beni kim sanıyorsunuz? Ben Mesih değilim. Ama O benden sonra geliyor. Ben Onun ayağındaki çarığın bağını çözmeye bile layık değilim.›'),
(2010377,68,44,13,26,'‹‹Kardeşler, İbrahimin soyundan gelenler ve Tanrıdan korkan yabancılar, bu kurtuluş bildirisi bize gönderildi.'),
(2010378,68,44,13,27,'Çünkü Yeruşalimde yaşayanlar ve onların yöneticileri İsayı reddettiler. Onu mahkûm etmekle her Şabat Günü okunan peygamberlerin sözlerini yerine getirmiş oldular.'),
(2010379,68,44,13,28,'Onda ölüm cezasını gerektiren herhangi bir suç bulamadıkları halde, Pilatustan Onun idamını istediler.'),
(2010380,68,44,13,29,'Onunla ilgili yazılanların hepsini yerine getirdikten sonra Onu çarmıhtan indirip mezara koydular.'),
(2010381,68,44,13,30,'Ama Tanrı Onu ölümden diriltti.'),
(2010382,68,44,13,31,'İsa, daha önce kendisiyle birlikte Celileden Yeruşalime gelenlere günlerce göründü. Bu kişiler şimdi halka Onun tanıklığını yapıyor.'),
(2010383,68,44,13,32,'‹‹Biz de size Müjdeyi duyuruyoruz: Tanrı İsayı diriltmekle, atalarımıza verdiği sözü, onların çocukları olan bizler için yerine getirmiştir. İkinci Mezmurda da yazıldığı gibi: ‹Sen benim Oğlumsun, Bugün ben sana Baba oldum.›'),
(2010384,68,44,13,34,'‹‹Tanrı, Onu asla çürümemek üzere ölümden dirilttiğini şu sözlerle belirtmiştir: ‹Size, Davuta söz verdiğim Kutsal ve güvenilir nimetleri vereceğim.›'),
(2010385,68,44,13,35,'‹‹Bunun için başka bir yerde de şöyle der: ‹Kutsalının çürümesine izin vermeyeceksin.›'),
(2010386,68,44,13,36,'‹‹Davut, kendi kuşağında Tanrının amacı uyarınca hizmet ettikten sonra gözlerini yaşama kapadı, ataları gibi gömüldü ve bedeni çürüyüp gitti.'),
(2010387,68,44,13,37,'Oysa Tanrının dirilttiği Kişinin bedeni çürümedi.'),
(2010388,68,44,13,38,'Dolayısıyla kardeşler, şunu bilin ki, günahların bu Kişi aracılığıyla bağışlanacağı size duyurulmuş bulunuyor. Şöyle ki, iman eden herkes, Musanın Yasasıyla aklanamadığınız her suçtan Onun aracılığıyla aklanır.'),
(2010389,68,44,13,40,'Dikkat edin, peygamberlerin sözünü ettiği şu durum sizin başınıza gelmesin: ‹Bakın, siz alay edenler, Şaşkına dönüp yok olun! Sizin gününüzde bir iş yapıyorum, Öyle bir iş ki, biri size anlatsa inanmazsınız.› ››'),
(2010390,68,44,13,42,'Pavlusla Barnaba havradan çıkarken halk onları, bir sonraki Şabat Günü aynı konular üzerinde konuşmaya çağırdı.'),
(2010391,68,44,13,43,'Havradaki topluluk dağılınca, Yahudiler ve Yahudiliğe dönüp Tanrıya tapan yabancılardan birçoğu onların ardından gitti. Pavlusla Barnaba onlarla konuşarak onları devamlı Tanrının lütfunda yaşamaya özendirdiler.'),
(2010392,68,44,13,44,'Ertesi Şabat Günü kent halkının hemen hemen tümü Rabbin sözünü dinlemek için toplanmıştı.'),
(2010393,68,44,13,45,'Kalabalığı gören Yahudiler büyük bir kıskançlık içinde, küfürlerle Pavlusun söylediklerine karşı çıktılar.'),
(2010394,68,44,13,46,'Pavlusla Barnaba ise cesaretle karşılık verdiler: ‹‹Tanrının sözünü ilk önce size bildirmemiz gerekiyordu. Siz onu reddettiğinize ve kendinizi sonsuz yaşama layık görmediğinize göre, biz şimdi öteki uluslara gidiyoruz.'),
(2010395,68,44,13,47,'Çünkü Rab bize şöyle buyurmuştur: ‹Yeryüzünün dört bucağına kurtuluş götürmen için Seni uluslara ışık yaptım.› ››'),
(2010396,68,44,13,48,'Öteki uluslardan olanlar bunu işitince sevindiler ve Rabbin sözünü yücelttiler. Sonsuz yaşam için belirlenmiş olanların hepsi iman etti.'),
(2010397,68,44,13,49,'Böylece Rabbin sözü bütün yörede yayıldı.'),
(2010398,68,44,13,50,'Ne var ki Yahudiler, Tanrıya tapan saygın kadınlarla kentin ileri gelen erkeklerini kışkırttılar, Pavlusla Barnabaya karşı bir baskı hareketi başlatıp onları bölge sınırlarının dışına attılar.'),
(2010399,68,44,13,51,'Bunun üzerine Pavlusla Barnaba, onlara bir uyarı olsun diye ayaklarının tozunu silkerek Konyaya gittiler.'),
(2010400,68,44,13,52,'Öğrenciler ise sevinç ve Kutsal Ruh''la doluydu.'),
(2010401,68,44,14,1,'Aynı şekilde Konyada da Yahudilerin havrasına giren Pavlusla Barnaba öyle etkili konuştular ki, hem Yahudilerden hem de Greklerden çok kişi iman etti.'),
(2010402,68,44,14,2,'Ama inanmayan Yahudiler, öteki uluslardan olanları kardeşlere karşı kışkırtarak zihinlerini bulandırdılar.'),
(2010403,68,44,14,3,'Orada uzunca bir süre kalan Pavlusla Barnaba, Rab hakkında cesaretle konuşuyorlardı. Rab de onlara belirtiler ve harikalar yapma gücü vererek kendi lütfunu açıklayan bildiriyi doğruladı.'),
(2010404,68,44,14,4,'Kent halkı ikiye bölündü. Bazıları Yahudilerin, bazıları da elçilerin tarafını tuttu.'),
(2010405,68,44,14,5,'Yahudilerle öteki uluslardan olanlar ve bunların yöneticileri, elçileri hırpalayıp taşa tutmak için düzen kurdular.'),
(2010406,68,44,14,6,'Bunu öğrenen Pavlusla Barnaba, Likaonyanın Listra ve Derbe kentlerine ve çevre bölgeye kaçarak oralarda da Müjdeyi yaydılar.'),
(2010407,68,44,14,8,'Listrada, ayakları tutmayan bir adam vardı. Doğuştan kötürümdü, hiç yürüyemiyordu.'),
(2010408,68,44,14,9,'Pavlusun söylediklerini dinledi. Onu dikkatle süzen Pavlus, iyileştirilebileceğine imanı olduğunu görerek yüksek sesle ona, ‹‹Kalk, ayaklarının üzerinde dur!›› dedi. Adam yerinden fırlayıp yürümeye başladı.'),
(2010409,68,44,14,11,'Pavlusun ne yaptığını gören halk Likaonya dilinde, ‹‹Tanrılar insan kılığına girip yanımıza inmiş!›› diye haykırdı.'),
(2010410,68,44,14,12,'Barnabaya Zeus, Pavlusa da konuşmada öncülük ettiği için Hermes adını taktılar.'),
(2010411,68,44,14,13,'Kentin hemen dışında bulunan Zeus Tapınağının kâhini kent kapılarına boğalar ve çelenkler getirdi, halkla birlikte elçilere kurban sunmak istedi.'),
(2010412,68,44,14,14,'Ne var ki elçiler, Barnabayla Pavlus, bunu duyunca giysilerini yırtarak kalabalığın içine daldılar.'),
(2010413,68,44,14,15,'‹‹Efendiler, neden böyle şeyler yapıyorsunuz?›› diye bağırdılar. ‹‹Biz de sizin gibi insanız, aynı yaradılışa sahibiz. Size müjde getiriyoruz. Sizi bu boş şeylerden vazgeçmeye, yeri, göğü, denizi ve bunların içindekilerin hepsini yaratan, yaşayan Tanrıya dönmeye çağırıyoruz.'),
(2010414,68,44,14,16,'Geçmiş çağlarda Tanrı, bütün ulusların kendi yollarından gitmelerine izin verdi.'),
(2010415,68,44,14,17,'Yine de kendini tanıksız bırakmadı. Size iyilik ediyor. Gökten yağmur yağdırıyor, çeşitli ürünleriyle mevsimleri düzenliyor, sizi yiyecekle doyurup yüreklerinizi sevinçle dolduruyor.››'),
(2010416,68,44,14,18,'Bu sözlerle bile halkın kendilerine kurban sunmasını güçlükle engelleyebildiler.'),
(2010417,68,44,14,19,'Ne var ki, Antakya ve Konyadan gelen bazı Yahudiler, halkı kendi taraflarına çekerek Pavlusu taşladılar; onu ölmüş sanarak kentin dışına sürüklediler.'),
(2010418,68,44,14,20,'Ama öğrenciler çevresinde toplanınca Pavlus ayağa kalkıp kente döndü. Ertesi gün Barnabayla birlikte Derbeye gitti.'),
(2010419,68,44,14,21,'O kentte de Müjdeyi duyurup birçok öğrenci edindiler. Pavlusla Barnaba daha sonra Listra, Konya ve Antakyaya dönerek öğrencileri ruhça pekiştirdiler, imana bağlı kalmaları için onlara cesaret verdiler. ‹‹Tanrının Egemenliğine, birçok sıkıntıdan geçerek girmemiz gerekir›› diyorlardı.'),
(2010420,68,44,14,23,'İmanlılar için her kilisede ihtiyarlar seçtiler. Dua ve oruçla onları, inandıkları Rabbe emanet ettiler.'),
(2010421,68,44,14,24,'Pisidya bölgesinden geçerek Pamfilyaya geldiler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010422,68,44,14,25,'Pergede Tanrı sözünü bildirdikten sonra Antalyaya gittiler.'),
(2010423,68,44,14,26,'Oradan gemiyle, artık tamamlamış bulundukları görev için Tanrının lütfuna emanet edildikleri yer olan Antakyaya döndüler.'),
(2010424,68,44,14,27,'Oraya vardıklarında inanlılar topluluğunu bir araya getirip Tanrının kendileri aracılığıyla neler yaptığını, öteki uluslara iman kapısını nasıl açtığını anlattılar.'),
(2010425,68,44,14,28,'Oradaki öğrencilerin yanında uzun bir süre kaldılar.'),
(2010426,68,44,15,1,'Yahudiyeden gelen bazı kişiler Antakyadaki kardeşlere, ‹‹Siz Musanın töresi uyarınca sünnet olmadıkça kurtulamazsınız›› diye öğretiyorlardı.'),
(2010427,68,44,15,2,'Pavlusla Barnaba bu adamlarla bir hayli çekişip tartıştılar. Sonunda Pavlusla Barnabanın, başka birkaç kardeşle birlikte Yeruşalime gidip bu sorunu elçiler ve ihtiyarlarla görüşmesi kararlaştırıldı.'),
(2010428,68,44,15,3,'Böylece kilise tarafından gönderilenler, öteki uluslardan olanların Tanrıya nasıl döndüğünü anlata anlata Fenike ve Samiriye bölgelerinden geçerek bütün kardeşlere büyük sevinç verdiler.'),
(2010429,68,44,15,4,'Yeruşalime geldiklerinde inanlılar topluluğu, elçiler ve ihtiyarlarca iyi karşılandılar. Tanrının kendileri aracılığıyla yapmış olduğu her şeyi anlattılar.'),
(2010430,68,44,15,5,'Ne var ki, Ferisi mezhebinden bazı imanlılar kalkıp şöyle dediler: ‹‹Öteki uluslardan olanları sünnet etmek ve onlara Musanın Yasasına uymalarını buyurmak gerekir.››'),
(2010431,68,44,15,6,'Elçilerle ihtiyarlar bu konuyu görüşmek için toplandılar.'),
(2010432,68,44,15,7,'Uzunca bir tartışmadan sonra Petrus ayağa kalkıp onlara, ‹‹Kardeşler›› dedi, ‹‹Öteki uluslar Müjdenin bildirisini benim ağzımdan duyup inansınlar diye Tanrının uzun zaman önce aranızdan beni seçtiğini biliyorsunuz.'),
(2010433,68,44,15,8,'İnsanın yüreğini bilen Tanrı, Kutsal Ruhu tıpkı bize verdiği gibi onlara da vermekle, onları kabul ettiğini gösterdi.'),
(2010434,68,44,15,9,'Onlarla bizim aramızda hiçbir ayrım yapmadı, iman etmeleri üzerine yüreklerini arındırdı.'),
(2010435,68,44,15,10,'Öyleyse, ne bizim ne de atalarımızın taşıyamadığı bir boyunduruğu öğrencilerin boynuna geçirerek şimdi neden Tanrıyı deniyorsunuz?'),
(2010436,68,44,15,11,'Bizler, Rab İsanın lütfuyla kurtulduğumuza inanıyoruz; onlar da öyle.››'),
(2010437,68,44,15,12,'Bunun üzerine bütün topluluk sustu ve Barnabayla Pavlusu dinlemeye başladı. Barnabayla Pavlus, Tanrının kendileri aracılığıyla öteki uluslar arasında yaptığı harikalarla belirtileri tek tek anlattılar.'),
(2010438,68,44,15,13,'Onlar konuşmalarını bitirince Yakup söz aldı: ‹‹Kardeşler, beni dinleyin›› dedi.'),
(2010439,68,44,15,14,'‹‹Simun, Tanrının öteki uluslardan kendine ait olacak bir halk çıkarmak amacıyla onlara ilk kez nasıl yaklaştığını anlatmıştır.'),
(2010440,68,44,15,15,'Peygamberlerin sözleri de bunu doğrulamaktadır. Yazılmış olduğu gibi: ‹Bundan sonra ben geri dönüp, Davutun yıkık konutunu yeniden kuracağım. Onun yıkıntılarını yeniden kurup Onu tekrar ayağa kaldıracağım.'),
(2010441,68,44,15,17,'Öyle ki, geriye kalan insanlar, Bana ait olan bütün uluslar Rabbi arasınlar. Bunları ta başlangıçtan bildiren Rab, İşte böyle diyor.›'),
(2010442,68,44,15,19,'‹‹Bu nedenle, kanımca öteki uluslardan Tanrıya dönenlere güçlük çıkarmamalıyız.'),
(2010443,68,44,15,20,'Ancak putlara sunulup murdar hale gelen etlerden, fuhuştan, boğularak öldürülen hayvanların etinden ve kandan sakınmaları gerektiğini onlara yazmalıyız.'),
(2010444,68,44,15,21,'Çünkü çok eski zamanlardan beri Musanın sözleri her kentte duyurulmakta, her Şabat Günü havralarda okunmaktadır.››'),
(2010445,68,44,15,22,'Bunun üzerine bütün inanlılar topluluğuyla elçiler ve ihtiyarlar, kendi aralarından seçtikleri adamları Pavlus ve Barnabayla birlikte Antakyaya göndermeye karar verdiler. Kardeşlerin önde gelenlerinden Barsabba denilen Yahuda ile Silası seçtiler.'),
(2010446,68,44,15,23,'Onların eliyle şu mektubu yolladılar: ‹‹Kardeşleriniz olan biz elçilerle ihtiyarlardan, öteki uluslardan olup Antakya, Suriye ve Kilikyada bulunan siz kardeşlere selam!'),
(2010447,68,44,15,24,'Bizden bazı kişilerin yanınıza geldiğini, sözleriyle sizi tedirgin edip aklınızı karıştırdığını duyduk. Oysa onları biz göndermedik.'),
(2010448,68,44,15,25,'Bu nedenle aramızdan seçtiğimiz bazı kişileri, sevgili kardeşlerimiz Barnaba ve Pavlusla birlikte size göndermeye oybirliğiyle karar verdik.'),
(2010449,68,44,15,26,'Bu ikisi, Rabbimiz İsa Mesihin adı uğruna canlarını gözden çıkarmış kişilerdir.'),
(2010450,68,44,15,27,'Kararımız uyarınca size Yahuda ile Silası gönderiyoruz. Onlar aynı şeyleri sözlü olarak da aktaracaklar.'),
(2010451,68,44,15,28,'Kutsal Ruh ve bizler, gerekli olan şu kuralların dışında size herhangi bir şey yüklememeyi uygun gördük: Putlara sunulan kurbanların etinden, kandan, boğularak öldürülen hayvanların etinden ve fuhuştan sakınmalısınız. Bunlardan kaçınırsanız, iyi edersiniz. Esen kalın.››'),
(2010452,68,44,15,30,'Adamlar böylece yola koyulup Antakyaya gittiler. Topluluğu bir araya getirerek onlara mektubu verdiler.'),
(2010453,68,44,15,31,'İmanlılar, mektuptaki yüreklendirici sözleri okuyunca sevindiler.'),
(2010454,68,44,15,32,'Kendileri peygamber olan Yahuda ile Silas, birçok konuşmalar yaparak kardeşleri yüreklendirip ruhça pekiştirdiler.'),
(2010455,68,44,15,33,'Bir süre orada kaldıktan sonra, kendilerini göndermiş olanların yanına dönmek üzere kardeşler tarafından esenlikle yolcu edildiler.'),
(2010456,68,44,15,35,'Pavlusla Barnaba ise Antakyada kaldılar, birçoklarıyla birlikte öğretip Rabbin sözünü müjdelediler.'),
(2010457,68,44,15,36,'Bundan bir süre sonra Pavlus Barnabaya, ‹‹Rabbin sözünü duyurduğumuz bütün kentlere dönüp kardeşleri ziyaret edelim, nasıl olduklarını görelim›› dedi.'),
(2010458,68,44,15,37,'Barnaba, Markos denilen Yuhannayı da yanlarında götürmek istiyordu.'),
(2010459,68,44,15,38,'Ama Pavlus, Pamfilyada kendilerini yüzüstü bırakıp birlikte göreve devam etmeyen Markosu yanlarında götürmeyi uygun görmedi.'),
(2010460,68,44,15,39,'Aralarında öylesine keskin bir anlaşmazlık çıktı ki, birbirlerinden ayrıldılar. Barnaba Markosu alıp Kıbrısa doğru yelken açtı.'),
(2010461,68,44,15,40,'Silası seçen Pavlus ise, kardeşlerce Rabbin lütfuna emanet edildikten sonra yola çıktı.'),
(2010462,68,44,15,41,'Suriye ve Kilikya bölgelerini dolaşarak inanlı topluluklarını pekiştirdi.'),
(2010463,68,44,16,1,'Pavlus, Derbe ve Listraya da uğradı. Listrada Timoteos adında bir İsa öğrencisi vardı. Annesi imanlı bir Yahudi, babası ise Grekti.'),
(2010464,68,44,16,2,'Listra ve Konyadaki kardeşler ondan övgüyle söz ediyorlardı.'),
(2010465,68,44,16,3,'Timoteosu kendisiyle birlikte götürmek isteyen Pavlus, oralarda bulunan Yahudiler yüzünden onu sünnet ettirdi. Çünkü hepsi, babasının Grek olduğunu biliyordu.'),
(2010466,68,44,16,4,'Kent kent dolaşarak Yeruşalimdeki elçilerle ihtiyarların aldığı kararları imanlılara iletiyor, bunlara uymalarını istiyorlardı.'),
(2010467,68,44,16,5,'Böylelikle toplulukların imanı güçleniyor ve sayıları günden güne artıyordu.'),
(2010468,68,44,16,6,'Kutsal Ruhun, Tanrı sözünü Asya İlinde yaymalarını engellemesi üzerine Pavlusla arkadaşları Frikya ve Galatya bölgesinden geçtiler.'),
(2010469,68,44,16,7,'Misya sınırına geldiklerinde Bitinya bölgesine geçmek istediler. Ama İsanın Ruhu onlara izin vermedi.'),
(2010470,68,44,16,8,'Bunun üzerine Misyadan geçip Troas Kentine gittiler.'),
(2010471,68,44,16,9,'O gece Pavlus bir görüm gördü. Önünde Makedonyalı bir adam durmuş, ona yalvarıyordu: ‹‹Makedonyaya geçip bize yardım et›› diyordu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010472,68,44,16,10,'Pavlusun gördüğü bu görümden sonra hemen Makedonyaya gitmenin bir yolunu aradık. Çünkü Tanrının bizi, Müjdeyi oradakilere duyurmaya çağırdığı sonucuna varmıştık.'),
(2010473,68,44,16,11,'Troastan denize açılıp doğru Semadirek Adasına, ertesi gün de Neapolise gittik.'),
(2010474,68,44,16,12,'Oradan da Filipiye geçtik. Burası bir Roma yerleşim merkezi ve Makedonyanın o bölgesinde önemli bir kentti. Birkaç gün bu kentte kaldık.'),
(2010475,68,44,16,13,'Şabat Günü kent kapısından çıkıp ırmak kıyısına gittik. Orada bir dua yeri olacağını düşünüyorduk. Oturduk, orada toplanmış kadınlarla konuşmaya başladık.'),
(2010476,68,44,16,14,'Bizi dinleyenler arasında Tiyatira Kentinden Lidya adında bir kadın vardı. Mor kumaş ticareti yapan Lidya, Tanrıya tapan biriydi. Pavlusun söylediklerine kulak vermesi için Rab onun yüreğini açtı.'),
(2010477,68,44,16,15,'Lidya, ev halkıyla birlikte vaftiz olduktan sonra bizi evine çağırdı. ‹‹Beni Rabbin bir inanlısı kabul ediyorsanız, gelin, evimde kalın›› dedi ve bizi razı etti.'),
(2010478,68,44,16,16,'Bir gün biz dua yerine giderken, karşımıza, falcılık ruhuna tutulmuş köle bir kız çıktı. Bu kız, gelecekten haber vererek efendilerine bir hayli kazanç sağlıyordu.'),
(2010479,68,44,16,17,'Pavlusu ve bizleri izleyerek, ‹‹Bu adamlar yüce Tanrının kullarıdır, size kurtuluş yolunu bildiriyorlar!›› diye bağırıp durdu.'),
(2010480,68,44,16,18,'Ve günlerce sürdürdü bunu. Sonunda, bundan çok rahatsız olan Pavlus arkasına dönerek ruha, ‹‹İsa Mesihin adıyla, bu kızın içinden çıkmanı buyuruyorum›› dedi. Ruh hemen kızın içinden çıktı.'),
(2010481,68,44,16,19,'Kızın efendileri, kazanç umutlarının yok olduğunu görünce Pavlusla Silası yakalayıp çarşı meydanına, yetkililerin önüne sürüklediler.'),
(2010482,68,44,16,20,'Onları yargıçların karşısına çıkartarak, ‹‹Bu adamlar Yahudidir›› dediler, ‹‹Kentimizi altüst ettiler. Biz Romalılar için benimsenmesi ve uygulanması yasak birtakım töreler yayıyorlar.››'),
(2010483,68,44,16,22,'Halk da Pavlusla Silasa yapılan saldırıya katıldı. Yargıçlar onların giysilerini yırtıp sıyırarak değnekle dövülmeleri için buyruk verdi.'),
(2010484,68,44,16,23,'Onları iyice dövdürdükten sonra hapse attılar. Zindancıya, onları sıkı güvenlik altında tutmasını buyurdular.'),
(2010485,68,44,16,24,'Bu buyruğu alan zindancı onları hapishanenin iç bölmesine atarak ayaklarını tomruğa vurdu.'),
(2010486,68,44,16,25,'Gece yarısına doğru Pavlusla Silas dua ediyor, Tanrıyı ilahilerle yüceltiyorlardı. Öbür tutuklular da onları dinliyordu.'),
(2010487,68,44,16,26,'Birdenbire öyle şiddetli bir deprem oldu ki, tutukevi temelden sarsıldı. Bir anda bütün kapılar açıldı, herkesin zincirleri çözüldü.'),
(2010488,68,44,16,27,'Zindancı uyandı. Zindan kapılarını açık görünce kılıcını çekip canına kıymak istedi. Çünkü tutukluların kaçtığını sanmıştı.'),
(2010489,68,44,16,28,'Ama Pavlus yüksek sesle, ‹‹Canına kıyma, hepimiz buradayız!›› diye seslendi.'),
(2010490,68,44,16,29,'Zindancı ışık getirtip içeri daldı. Titreyerek Pavlusla Silasın önünde yere kapandı.'),
(2010491,68,44,16,30,'Onları dışarı çıkararak, ‹‹Efendiler, kurtulmak için ne yapmam gerekir?›› diye sordu.'),
(2010492,68,44,16,31,'Onlar, ‹‹Rab İsaya iman et, sen de ev halkın da kurtulursunuz›› dediler.'),
(2010493,68,44,16,32,'Sonra kendisine ve ev halkının hepsine Rabbin sözünü bildirdiler.'),
(2010494,68,44,16,33,'Gecenin o saatinde zindancı onları götürüp yaralarını yıkadı. Sonra hem kendisi hem ev halkı hemen vaftiz oldu.'),
(2010495,68,44,16,34,'Pavlusla Silası evine götürerek sofra kurdu. Tanrıya inanmak, onu ve evindekilerin hepsini sevince boğmuştu.'),
(2010496,68,44,16,35,'Gün doğunca yargıçlar görevlileri göndererek, ‹‹O adamları serbest bırak›› dediler.'),
(2010497,68,44,16,36,'Zindancı bu sözleri Pavlusa iletti. ‹‹Yargıçlar serbest bırakılmanız için haber gönderdi. Şimdi çıkabilirsiniz, esenlikle gidin›› dedi.'),
(2010498,68,44,16,37,'Ama Pavlus görevlilere şöyle dedi: ‹‹Roma vatandaşı olduğumuz halde, bizi yargılamadan herkesin önünde dövüp hapse attılar. Şimdi bizi gizlice mi kovacaklar? Olmaz böyle şey! Kendileri gelsinler, bizi alıp çıkarsınlar!››'),
(2010499,68,44,16,38,'Görevliler bu sözleri yargıçlara iletti. Yargıçlar, Pavlusla Silasın Roma vatandaşı olduğunu duyunca korktular.'),
(2010500,68,44,16,39,'Gelip özür dilediler. Sonra onları dışarı çıkararak kentten ayrılmalarını rica ettiler.'),
(2010501,68,44,16,40,'Pavlus''la Silas zindandan çıkınca Lidya''nın evine gittiler. Kardeşlerle görüşüp onları yüreklendirdikten sonra oradan ayrıldılar.'),
(2010502,68,44,17,1,'Amfipolis ve Apollonyadan geçerek Selanike geldiler. Burada Yahudilerin bir havrası vardı.'),
(2010503,68,44,17,2,'Pavlus, her zamanki gibi Yahudilere giderek art arda üç Şabat Günü onlarla Kutsal Yazılar üzerinde tartıştı.'),
(2010504,68,44,17,3,'Mesihin acı çekip ölümden dirilmesi gerektiğine dair açıklamalarda bulunuyor, kanıtlar gösteriyordu. ‹‹Size duyurmakta olduğum bu İsa, Mesihtir›› diyordu.'),
(2010505,68,44,17,4,'Onlardan bazıları, Tanrıya tapan Greklerden büyük bir topluluk ve ileri gelen kadınların da birçoğu ikna olup Pavlusla Silasa katıldılar.'),
(2010506,68,44,17,5,'Yahudiler bunu kıskandı. Çarşı pazardan topladıkları bazı kötü insanlardan bir kalabalık oluşturup kentte kargaşalık çıkarttılar. Pavlusla Silası bulmak ve halkın önünde yargılamak amacıyla Yasonun evine saldırdılar.'),
(2010507,68,44,17,6,'Onları bulamayınca, Yason ile bazı kardeşleri kent yetkililerinin önüne sürüklediler. ‹‹Dünyayı altüst eden o adamlar buraya da geldiler›› diye bağırıyorlardı.'),
(2010508,68,44,17,7,'‹‹Yason onları evine aldı. Onların hepsi, İsa adında başka bir kral olduğunu söyleyerek Sezarın buyruklarına karşı geliyorlar.››'),
(2010509,68,44,17,8,'Bu sözleri işiten kalabalık ve kentin yetkilileri telaşa kapıldı.'),
(2010510,68,44,17,9,'Sonunda yetkililer Yason ve öbürlerini kefaletle serbest bıraktılar.'),
(2010511,68,44,17,10,'Kardeşler hemen o gece Pavlusla Silası Veriya Kentine gönderdiler. Onlar oraya varınca Yahudilerin havrasına gittiler.'),
(2010512,68,44,17,11,'Veriyadaki Yahudiler Selaniktekilerden daha açık fikirliydi. Tanrı sözünü büyük ilgiyle karşılayarak her gün Kutsal Yazıları inceliyor, öğretilenlerin doğru olup olmadığını araştırıyorlardı.'),
(2010513,68,44,17,12,'Böylelikle içlerinden birçokları ve çok sayıda saygın Grek kadın ve erkek iman etti.'),
(2010514,68,44,17,13,'Selanikteki Yahudiler Pavlusun Veriyada da Tanrının sözünü duyurduğunu öğrenince oraya gittiler, halkı kışkırtıp ayağa kaldırdılar.'),
(2010515,68,44,17,14,'Bunun üzerine kardeşler Pavlusu hemen deniz kıyısına yolladılar. Silas ile Timoteos ise Veriyada kaldılar.'),
(2010516,68,44,17,15,'Pavlusla birlikte gidenler onu Atinaya kadar götürdüler. Sonra Pavlustan, Silasla Timoteosun bir an önce kendisine yetişmeleri yolunda buyruk alarak geri döndüler.'),
(2010517,68,44,17,16,'Onları Atinada bekleyen Pavlus, kenti putlarla dolu görünce yüreğinde derin bir acı duydu.'),
(2010518,68,44,17,17,'Bu nedenle, gerek havrada Yahudilerle ve Tanrıya tapan yabancılarla, gerek her gün çarşı meydanında karşılaştığı kişilerle tartışıp durdu.'),
(2010519,68,44,17,18,'Epikürcü ve Stoacı bazı filozoflar onunla atışmaya başladılar. Kimi, ‹‹Bu lafebesi ne demek istiyor?›› derken, kimi de, ‹‹Galiba yabancı ilahların haberciliğini yapıyor›› diyordu. Çünkü Pavlus, İsayla ve dirilişle ilgili Müjdeyi duyuruyordu.'),
(2010520,68,44,17,19,'Onlar Pavlusu alıp Ares Tepesi Kuruluna götürdüler. Ona, ‹‹Yaydığın bu yeni öğretinin ne olduğunu öğrenebilir miyiz?›› dediler.'),
(2010521,68,44,17,20,'‹‹Kulağımıza yabancı gelen bazı konulardan söz ediyorsun. Bunların anlamını öğrenmek isteriz.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010522,68,44,17,21,'Bütün Atinalılar ve kentte bulunan yabancılar, vakitlerini hep yeni düşünceleri anlatarak ve dinleyerek geçirirlerdi.'),
(2010523,68,44,17,22,'Pavlus, Ares Tepesi Kurulunun önüne çıkıp şunları söyledi: ‹‹Ey Atinalılar, sizin her bakımdan çok dindar olduğunuzu görüyorum.'),
(2010524,68,44,17,23,'Ben çevrede dolaşırken, tapındığınız yerleri incelerken üzerinde, BİLİNMEYEN TANRIYA Tanrıyı ben size tanıtayım.'),
(2010525,68,44,17,24,'‹‹Dünyayı ve içindekilerin tümünü yaratan, yerin ve göğün Rabbi olan Tanrı, elle yapılmış tapınaklarda oturmaz.'),
(2010526,68,44,17,25,'Herkese yaşam, soluk ve her şeyi veren kendisi olduğuna göre, bir şeye gereksinmesi varmış gibi Ona insan eliyle hizmet edilmez. Tanrı, bütün ulusları tek insandan türetti ve onları yeryüzünün dört bucağına yerleştirdi.'),
(2010527,68,44,17,26,'Ulusların sürelerini ve yerleşecekleri bölgelerin sınırlarını önceden saptadı.'),
(2010528,68,44,17,27,'Bunu, kendisini arasınlar ve el yordamıyla da olsa bulabilsinler diye yaptı. Aslında Tanrı hiçbirimizden uzak değildir.'),
(2010529,68,44,17,28,'Nitekim, ‹Onda yaşıyor ve hareket ediyoruz; Onda varız.› Bazı ozanlarınızın belirttiği gibi, ‹Biz de Onun soyundanız.›'),
(2010530,68,44,17,29,'‹‹Tanrının soyundan olduğumuza göre, tanrısal özün, insan düşüncesi ve becerisiyle biçimlendirilmiş altın, gümüş ya da taştan bir nesneye benzediğini düşünmemeliyiz.'),
(2010531,68,44,17,30,'Tanrı, geçmiş dönemlerin bilgisizliğini görmezlikten geldi; ama şimdi her yerde herkesin tövbe etmesini buyuruyor.'),
(2010532,68,44,17,31,'Çünkü dünyayı, atadığı Kişi aracılığıyla adaletle yargılayacağı günü saptamıştır. Bu Kişiyi ölümden diriltmekle bunun güvencesini herkese vermiştir.››'),
(2010533,68,44,17,32,'Ölülerin dirilmesiyle ilgili sözleri duyunca kimi alay etti, kimi de, ‹‹Seni bu konuda bir daha dinlemek isteriz›› dedi.'),
(2010534,68,44,17,33,'Bunun üzerine Pavlus aralarından çıkıp gitti.'),
(2010535,68,44,17,34,'Birkaç kişi ona katılıp inandı. Bunların arasında kurul üyesi Dionisios, Damaris adlı bir kadın ve birkaç kişi daha vardı.'),
(2010536,68,44,18,1,'Bundan sonra Pavlus Atinadan ayrılıp Korinte gitti.'),
(2010537,68,44,18,2,'Orada Pontus doğumlu, Akvila adında bir Yahudi ile karısı Priskillayı buldu. Bunlar, Klavdiusun bütün Yahudilerin Romayı terk etmesi yolundaki buyruğu üzerine, kısa süre önce İtalyadan gelmişlerdi. Akvila ile Priskillanın yanına giden Pavlus, aynı meslekten olduğundan onlarla kalıp çalıştı. Çünkü meslekleri çadırcılıktı.'),
(2010538,68,44,18,4,'Pavlus, her Şabat Günü havrada tartışarak hem Yahudileri hem Grekleri ikna etmeye çalışıyordu.'),
(2010539,68,44,18,5,'Silasla Timoteos Makedonyadan gelince, Pavlus kendini tümüyle Tanrı sözünü yaymaya verdi. Yahudilere, İsanın Mesih olduğuna dair tanıklık ediyordu.'),
(2010540,68,44,18,6,'Ama Yahudiler karşı gelip ona sövmeye başlayınca Pavlus, giysilerini silkerek, ‹‹Başınıza geleceklerin sorumlusu sizsiniz!›› dedi. ‹‹Sorumluluk benden gitti. Bundan böyle öteki uluslara gideceğim.››'),
(2010541,68,44,18,7,'Pavlus oradan çıktı, Tanrıya tapan Titius Yustus adlı birinin evine gitti. Yustusun evi havranın bitişiğindeydi.'),
(2010542,68,44,18,8,'Havranın yöneticisi Krispus bütün ev halkıyla birlikte Rabbe inandı. Pavlusu dinleyen Korintlilerden birçoğu da inanıp vaftiz oldu.'),
(2010543,68,44,18,9,'Bir gece Rab bir görümde Pavlusa, ‹‹Korkma›› dedi, ‹‹Konuş, susma!'),
(2010544,68,44,18,10,'Ben seninle birlikteyim; hiç kimse sana dokunmayacak, kötülük yapmayacak. Çünkü bu kentte benim halkım çoktur.››'),
(2010545,68,44,18,11,'Pavlus, orada bir buçuk yıl kaldı ve halka sürekli Tanrının sözünü öğretti.'),
(2010546,68,44,18,12,'Gallionun Ahaya Valisi olduğu sıralarda, hep birlikte Pavlusa karşı gelen Yahudiler onu mahkemeye çıkardılar.'),
(2010547,68,44,18,13,'‹‹Bu adam Yasaya aykırı biçimde Tanrıya tapınmaları için insanları kandırıyor›› dediler.'),
(2010548,68,44,18,14,'Pavlus tam söze başlayacakken Gallio Yahudilere şöyle dedi: ‹‹Ey Yahudiler, davanız bir haksızlık ya da ciddi bir suçla ilgili olsaydı, sizleri sabırla dinlemem gerekirdi.'),
(2010549,68,44,18,15,'Ama sorun bir öğreti, bazı adlar ve kendi yasanızla ilgili olduğuna göre, bu davaya kendiniz bakın. Ben böyle şeylere yargıçlık etmek istemem.››'),
(2010550,68,44,18,16,'Sonra Gallio onları mahkemeden kovdu.'),
(2010551,68,44,18,17,'Hep birlikte, havranın yöneticisi Sostenisi yakalayıp mahkemenin önünde dövdüler. Gallio ise olup bitenlere hiç aldırmadı.'),
(2010552,68,44,18,18,'Pavlus Korintteki kardeşlerin yanında bir süre daha kaldı. Sonra onlarla vedalaştı, Priskilla ve Akvila ile birlikte Suriyeye gitmek üzere gemiyle yola çıktı. Adakta bulunmuş olduğu için Kenherede saçlarını kestirmişti.'),
(2010553,68,44,18,19,'Efese vardıkları zaman Priskilla ve Akvilayı orada bıraktı. Kendisi havraya giderek Yahudilerle tartışmaya başladı.'),
(2010554,68,44,18,20,'Bunlar daha uzun bir süre kalmasını istedilerse de, Pavlus kabul etmedi.'),
(2010555,68,44,18,21,'Ama onlara veda ederken, ‹‹Tanrı dilerse yanınıza yine döneceğim›› dedi. Sonra Efesten denize açıldı.'),
(2010556,68,44,18,22,'Sezariyeye vardıktan sonra Yeruşalime gidip oradaki kiliseyi ziyaret etti, oradan da Antakyaya geçti.'),
(2010557,68,44,18,23,'Bir süre orada kaldıktan sonra yola çıktı; Galatya bölgesini ve Frikyayı dolaşarak bütün öğrencileri ruhça pekiştirdi.'),
(2010558,68,44,18,24,'Bu arada İskenderiye doğumlu Apollos adında bir Yahudi Efese geldi. Üstün bir konuşma yeteneği olan Apollos, Kutsal Yazıları çok iyi biliyordu.'),
(2010559,68,44,18,25,'Rabbin yolunda eğitilmiş bir kişiydi. Ateşli bir ruhla konuşuyor ve sadece Yahyanın vaftizini bildiği halde İsayla ilgili gerçekleri doğru öğretiyordu.'),
(2010560,68,44,18,26,'Havrada cesaretle konuşmaya başladı. Kendisini dinleyen Priskilla ile Akvila, onu yanlarına alarak Tanrı yolunu ona daha doğru biçimde açıkladılar.'),
(2010561,68,44,18,27,'Apollos Ahayaya gitmek isteyince kardeşler onu cesaretlendirdiler. Onu iyi karşılamaları için oradaki öğrencilere mektup yazdılar. Apollos Ahayaya varınca Tanrının lütfuyla iman etmiş olanlara çok yardım etti.'),
(2010562,68,44,18,28,'Şöyle ki Kutsal Yazılar''dan, İsa''nın Mesih olduğunu kanıtlayarak Yahudiler''in iddialarını açıkça ve güçlü bir şekilde çürüttü.'),
(2010563,68,44,19,1,'Apollos Korintteyken Pavlus, iç bölgelerden geçerek Efese geldi. Orada bazı öğrencileri bularak onlara, ‹‹İman ettiğiniz zaman Kutsal Ruhu aldınız mı?›› diye sordu. ‹‹Kutsal Ruhun varlığından haberimiz yok ki!›› dediler.'),
(2010564,68,44,19,3,'‹‹Öyleyse neye dayanarak vaftiz oldunuz?›› diye sordu. ‹‹Yahyanın öğretisine dayanarak vaftiz olduk›› dediler.'),
(2010565,68,44,19,4,'Pavlus, ‹‹Yahyanın yaptığı vaftiz, tövbeyle ilgili bir vaftizdi›› dedi. ‹‹Halka, kendisinden sonra gelecek Olana, yani İsaya inanmalarını söyledi.››'),
(2010566,68,44,19,5,'Onlar bunu duyunca, Rab İsanın adıyla vaftiz oldular.'),
(2010567,68,44,19,6,'Pavlus ellerini onların üzerine koyunca Kutsal Ruh üzerlerine indi ve bilmedikleri dillerle konuşup peygamberlik etmeye başladılar.'),
(2010568,68,44,19,7,'Aşağı yukarı on iki kişiydiler.'),
(2010569,68,44,19,8,'Havraya giren Pavlus cesaretle konuşmaya başladı. Üç ay boyunca oradakilerle tartışıp durdu, onları Tanrının Egemenliği konusunda ikna etmeye çalıştı.'),
(2010570,68,44,19,9,'Ne var ki, bazıları sert bir tutum takınıp ikna olmamakta direndiler ve İsanın yolunu halkın önünde kötülemeye başladılar. Bunun üzerine Pavlus onlardan ayrıldı. Öğrencilerini de alıp götürdü ve Tiranusun dershanesinde her gün tartışmalarını sürdürdü.'),
(2010571,68,44,19,10,'Bu durum iki yıl sürdü. Sonunda Yahudi olsun Grek olsun, Asya İlinde yaşayan herkes Rabbin sözünü işitti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010572,68,44,19,11,'Tanrı, Pavlusun eliyle olağanüstü mucizeler yaratıyordu.'),
(2010573,68,44,19,12,'Şöyle ki, Pavlusun bedenine değen peşkir ve peştamallar hasta olanlara götürüldüğünde, hastalıkları yok oluyor, kötü ruhlar içlerinden çıkıyordu.'),
(2010574,68,44,19,13,'Çevrede dolaşıp kötü ruhları kovmakla uğraşan bazı Yahudiler de kötü ruhlara tutsak olanları Rab İsanın adını anarak kurtarmaya kalkıştılar. ‹‹Pavlusun tanıttığı İsanın adıyla size emrediyoruz!›› diyorlardı.'),
(2010575,68,44,19,14,'Bunu yapanlar arasında Skeva adlı bir Yahudi başkâhinin yedi oğlu da vardı.'),
(2010576,68,44,19,15,'Kötü ruh ise onlara şöyle karşılık verdi: ‹‹İsayı biliyor, Pavlusu da tanıyorum, ama siz kimsiniz?››'),
(2010577,68,44,19,16,'İçinde kötü ruh bulunan adam onlara saldırdı, hepsini alt ederek bozguna uğrattı. Öyle ki, o evden çıplak ve yaralı olarak kaçtılar.'),
(2010578,68,44,19,17,'Bu haber, Efeste yaşayan bütün Yahudilerle Greklere ulaştı. Hepsini bir korku aldı ve Rab İsanın adı büyük bir saygınlık kazandı.'),
(2010579,68,44,19,18,'İman edenlerin birçoğu geliyor, yaptıkları kötülükleri itiraf edip anlatıyordu.'),
(2010580,68,44,19,19,'Büyücülükle uğraşmış bir sürü kişi de kitaplarını toplayıp herkesin önünde yaktılar. Kitapların değerini hesapladıklarında toplam elli bin gümüş tuttuğunu gördüler.'),
(2010581,68,44,19,20,'Böylelikle Rabbin sözü güçlü biçimde yayılıp etkinlik kazanıyordu.'),
(2010582,68,44,19,21,'Pavlus, bu olup bitenlerden sonra Makedonya ve Ahayadan geçip Yeruşalime gitmeye karar verdi. ‹‹Oraya gittikten sonra Romayı da görmem gerek›› diyordu.'),
(2010583,68,44,19,22,'Yardımcılarından ikisini, Timoteos ile Erastusu Makedonyaya göndererek kendisi bir süre daha Asya İlinde kaldı.'),
(2010584,68,44,19,23,'O sırada İsanın yoluna ilişkin büyük bir kargaşalık çıktı.'),
(2010585,68,44,19,24,'Artemis Tapınağının gümüşten maketlerini yapan Dimitrios adlı bir kuyumcu, el sanatçılarına bir hayli iş sağlıyordu.'),
(2010586,68,44,19,25,'Sanatçıları ve benzer işlerle uğraşanları bir araya toplayarak onlara şöyle dedi: ‹‹Efendiler, bu işten büyük kazanç sağladığımızı biliyorsunuz.'),
(2010587,68,44,19,26,'Ama Pavlus denen bu adamın, elle yapılan tanrıların gerçek tanrılar olmadığını söyleyerek yalnız Efeste değil, neredeyse bütün Asya İlinde çok sayıda kişiyi kandırıp saptırdığını görüyor ve duyuyorsunuz.'),
(2010588,68,44,19,27,'Hem bu sanatımız saygınlığını yitirmek tehlikesiyle karşı karşıyadır, hem de ulu tanrıça Artemisin Tapınağının hiçe sayılması ve bütün Asya İliyle bütün dünyanın tapındığı tanrıçanın, ululuğundan yoksun kalması tehlikesi vardır.››'),
(2010589,68,44,19,28,'Oradakiler bunu duyunca öfkeyle doldular. ‹‹Efeslilerin Artemisi uludur!›› diye bağırmaya başladılar.'),
(2010590,68,44,19,29,'Kent büsbütün karıştı. Halk, Pavlusun yol arkadaşlarından Makedonyalı Gayus ve Aristarhusu yakalayıp sürükleyerek birlikte tiyatroya koşuştu.'),
(2010591,68,44,19,30,'Pavlus halkın arasına girmek istediyse de, öğrenciler onu bırakmadı.'),
(2010592,68,44,19,31,'Hatta, Pavlusun dostu olan bazı Asya İli yöneticileri ona haber yollayarak tiyatroda görünmemesi için yalvardılar.'),
(2010593,68,44,19,32,'Tiyatrodaki topluluk karışıklık içindeydi. Her kafadan bir ses çıkıyordu. Çoğu ne için toplandığını bile bilmiyordu.'),
(2010594,68,44,19,33,'Yahudiler İskenderi öne çıkarınca kalabalıktan bazıları olayı ona bağladı. Eliyle bir işaret yapan İskender, halka savunmasını yapmak istedi.'),
(2010595,68,44,19,34,'Ama halk kendisinin Yahudi olduğunu anlayınca hep bir ağızdan yaklaşık iki saat boyunca, ‹‹Efeslilerin Artemisi uludur!›› diye bağırıp durdu.'),
(2010596,68,44,19,35,'Kalabalığı yatıştıran belediye yazmanı, ‹‹Ey Efesliler›› dedi, ‹‹Efes Kentinin, ulu Artemis Tapınağının ve gökten düşen kutsal taşın bekçisi olduğunu bilmeyen var mı?'),
(2010597,68,44,19,36,'Bunları hiç kimse inkâr edemez. Bunun için sakin olmanız ve düşüncesiz bir şey yapmamanız gerekir.'),
(2010598,68,44,19,37,'Buraya getirdiğiniz bu adamlar, ne tapınakları yağma ettiler, ne de tanrıçamıza sövdüler.'),
(2010599,68,44,19,38,'Dimitrios ve sanatçı arkadaşlarının herhangi birinden şikâyeti varsa, mahkemeler açık, yargıçlar da var. Karşılıklı suçlamalarını orada yapsınlar.'),
(2010600,68,44,19,39,'Soruşturacağınız başka bir durum varsa, bunun yasal bir toplantıda çözümlenmesi gerekir.'),
(2010601,68,44,19,40,'Bugünkü olaylardan ötürü ayaklanma suçundan yargılanmak tehlikesindeyiz. Hiçbir gerekçesi olmayan bu kargaşanın hesabını veremeyeceğiz.››'),
(2010602,68,44,19,41,'Bunları söyledikten sonra topluluğu dağıttı.'),
(2010603,68,44,20,1,'Pavlus, kargaşalık yatıştıktan sonra öğrencileri çağırtıp onları yüreklendirdi. Sonra kendilerine veda ederek Makedonyaya gitmek üzere yola çıktı.'),
(2010604,68,44,20,2,'O yöreleri dolaşarak imanlıları yüreklendiren birçok konuşmalar yaptıktan sonra Yunanistana gitti.'),
(2010605,68,44,20,3,'Orada üç ay kaldı. Suriyeye deniz yoluyla gitmek üzereyken Yahudilerin kendisine karşı bir düzen kurması nedeniyle dönüşü Makedonya üzerinden yapmaya karar verdi.'),
(2010606,68,44,20,4,'Piros oğlu Veriyalı Sopater, Selaniklilerden Aristarhus ile Sekundus, Derbeli Gayus, Timoteos ve Asya İlinden Tihikos ile Trofimos onunla birlikte gittiler.'),
(2010607,68,44,20,5,'Bunlar önden gidip bizi Troasta beklediler.'),
(2010608,68,44,20,6,'Biz de Mayasız Ekmek Bayramından sonra Filipiden denize açılıp beş günde Troasa gelerek onlarla buluştuk. Orada yedi gün kaldık.'),
(2010609,68,44,20,7,'Haftanın ilk günü ekmek bölmek için bir araya toplandığımızda Pavlus imanlılara bir konuşma yaptı. Ertesi gün oradan ayrılacağı için konuşmasını gece yarısına dek sürdürdü.'),
(2010610,68,44,20,8,'Toplanmış olduğumuz üst kattaki odada birçok kandil yanıyordu.'),
(2010611,68,44,20,9,'Eftihos adlı bir delikanlı pencerede oturuyordu. Pavlus konuşmasını uzattıkça Eftihosu uyku bastı. Uykuya dalınca da ikinci kattan aşağı düştü ve yerden ölüsü kaldırıldı.'),
(2010612,68,44,20,10,'Aşağı inen Pavlus delikanlının üzerine kapanıp onu kucakladı. ‹‹Telaşlanmayın, yaşıyor!›› dedi.'),
(2010613,68,44,20,11,'Sonra yukarı çıkıp ekmek böldü ve yemek yedi. Gün doğuncaya dek onlarla uzun uzun konuştu, sonra oradan ayrıldı.'),
(2010614,68,44,20,12,'Çocuğu diri olarak evine götüren imanlılar bu olaydan büyük cesaret aldılar.'),
(2010615,68,44,20,13,'Biz önden giderek gemiye bindik ve Assosa hareket ettik. Pavlusu oradan alacaktık. Kendisi karadan gitmek istediği için bunu böyle düzenlemişti.'),
(2010616,68,44,20,14,'Bizi Assosta karşılayınca onu gemiye alıp Midilliye geçtik.'),
(2010617,68,44,20,15,'Oradan denize açılıp ertesi gün Sakız Adasının karşısına geldik. Üçüncü gün Sisama uğradık ve bir gün sonra Milete vardık.'),
(2010618,68,44,20,16,'Pavlus, Asya İlinde vakit kaybetmemek için Efese uğramamaya karar vermişti. Pentikost Günü Yeruşalimde olabilmek umuduyla acele ediyordu.'),
(2010619,68,44,20,17,'Pavlus, Miletten Efese haber yollayarak kilisenin ihtiyarlarını yanına çağırttı.'),
(2010620,68,44,20,18,'Yanına geldikleri zaman onlara şöyle dedi: ‹‹Asya İline ayak bastığım ilk günden beri, sizinle bulunduğum bütün süre boyunca, nasıl davrandığımı biliyorsunuz.'),
(2010621,68,44,20,19,'Yahudilerin kurduğu düzenlerden çektiğim sıkıntıların ortasında Rabbe tam bir alçakgönüllülükle, gözyaşları içinde kulluk ettim.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010622,68,44,20,20,'Yararlı olan herhangi bir şeyi size duyurmaktan, gerek açıkta gerek evden eve dolaşarak size öğretmekten çekinmedim.'),
(2010623,68,44,20,21,'Hem Yahudileri hem de Grekleri, tövbe edip Tanrıya dönmeye ve Rabbimiz İsaya inanmaya çağırdım.'),
(2010624,68,44,20,22,'‹‹Şimdi de Ruha boyun eğerek Yeruşalime gidiyorum. Orada başıma neler geleceğini bilmiyorum.'),
(2010625,68,44,20,23,'Ancak Kutsal Ruh, beni zincirler ve sıkıntıların beklediğine dair her kentte beni uyarıyor.'),
(2010626,68,44,20,24,'Canımı hiç önemsemiyorum, ona değer vermiyorum. Yeter ki yarışı bitireyim ve Rab İsadan aldığım görevi, Tanrının lütfunu bildiren Müjdeye tanıklık etme görevini tamamlayayım.'),
(2010627,68,44,20,25,'‹‹Şimdi aralarında dolaşıp Tanrının Egemenliğini duyurduğum sizlerden hiçbirinin yüzümü bir daha görmeyeceğini biliyorum.'),
(2010628,68,44,20,26,'Bu yüzden bugün size şunu açıkça söyleyeyim: Ben kimsenin uğrayacağı cezadan sorumlu değilim.'),
(2010629,68,44,20,27,'Tanrının isteğini size tam olarak bildirmekten çekinmedim.'),
(2010630,68,44,20,28,'Kendinize ve Kutsal Ruhun sizi gözetmen olarak görevlendirdiği bütün sürüye göz kulak olun. Rabbin kendi kanı pahasına sahip olduğu kiliseyi gütmek üzere atandınız.'),
(2010631,68,44,20,29,'Ben gittikten sonra sürüyü esirgemeyen yırtıcı kurtların aranıza gireceğini biliyorum.'),
(2010632,68,44,20,30,'Hatta öğrencileri kendi peşlerinden sürüklemek için sizin aranızdan da sapık sözler söyleyen kişiler çıkacak.'),
(2010633,68,44,20,31,'Bunun için uyanık durun. Üç yıl boyunca, aralıksız, gece gündüz demeden, gözyaşı dökerek her birinizi nasıl uyardığımı hatırlayın.'),
(2010634,68,44,20,32,'‹‹Şimdi sizi Tanrıya ve Onun lütfunu bildiren söze emanet ediyorum. Bu söz, sizi ruhça geliştirecek ve kutsal kılınmış olan bütün insanlar arasında mirasa kavuşturacak güçtedir.'),
(2010635,68,44,20,33,'Ben hiç kimsenin altınına, gümüşüne ya da giysisine göz dikmedim.'),
(2010636,68,44,20,34,'Siz de bilirsiniz ki, bu eller hem benim, hem de benimle birlikte olanların gereksinmelerini karşılamak için hizmet etmiştir.'),
(2010637,68,44,20,35,'Yaptığım her işte sizlere, böyle emek vererek güçsüzlere yardım etmemiz ve Rab İsanın, ‹Vermek, almaktan daha büyük mutluluktur› diyen sözünü unutmamamız gerektiğini gösterdim.››'),
(2010638,68,44,20,36,'Pavlus bu sözleri söyledikten sonra diz çöküp onlarla birlikte dua etti.'),
(2010639,68,44,20,37,'Sonra hepsi acı acı ağlayarak Pavlusun boynuna sarıldılar, onu öptüler.'),
(2010640,68,44,20,38,'Onları en çok üzen, ‹‹Yüzümü bir daha görmeyeceksiniz›› demesi oldu. Sonra onu gemiye kadar geçirdiler.'),
(2010641,68,44,21,1,'Onlardan ayrılınca denize açılıp doğru İstanköye gittik. Ertesi gün Rodosa, oradan da Pataraya geçtik.'),
(2010642,68,44,21,2,'Fenikeye gidecek bir gemi bulduk, buna binip denize açıldık.'),
(2010643,68,44,21,3,'Kıbrısı görünce güneyinden geçerek Suriyeye yöneldik ve Sur Kentinde karaya çıktık. Gemi, yükünü orada boşaltacaktı.'),
(2010644,68,44,21,4,'İsanın oradaki öğrencilerini arayıp bulduk ve yanlarında bir hafta kaldık. Öğrenciler Ruhun yönlendirmesiyle Pavlusu Yeruşalime gitmemesi için uyardılar.'),
(2010645,68,44,21,5,'Günümüz dolunca kentten ayrılıp yolumuza devam ettik. İmanlıların hepsi, eşleri ve çocuklarıyla birlikte bizi kentin dışına kadar geçirdiler. Deniz kıyısında diz çöküp dua ettik.'),
(2010646,68,44,21,6,'Birbirimizle vedalaştıktan sonra biz gemiye bindik, onlar da evlerine döndüler.'),
(2010647,68,44,21,7,'Surdan deniz yolculuğumuza devam ederek Batlamya Kentine geldik. Oradaki kardeşleri ziyaret edip bir gün yanlarında kaldık.'),
(2010648,68,44,21,8,'Ertesi gün ayrılıp Sezariyeye geldik. Yedilerden biri olan müjdeci Filipusun evine giderek onun yanında kaldık.'),
(2010649,68,44,21,9,'Bu adamın peygamberlik eden, evlenmemiş dört kızı vardı.'),
(2010650,68,44,21,10,'Oraya varışımızdan birkaç gün sonra Yahudiyeden Hagavos adlı bir peygamber geldi.'),
(2010651,68,44,21,11,'Bu adam bize yaklaşıp Pavlusun kuşağını aldı, bununla kendi ellerini ayaklarını bağlayarak dedi ki, ‹‹Kutsal Ruh şöyle diyor: ‹Yahudiler, bu kuşağın sahibini Yeruşalimde böyle bağlayıp öteki uluslara teslim edecekler.› ››'),
(2010652,68,44,21,12,'Bu sözleri duyunca hem bizler hem de oralılar Yeruşalime gitmemesi için Pavlusa yalvardık.'),
(2010653,68,44,21,13,'Bunun üzerine Pavlus şöyle karşılık verdi: ‹‹Ne yapıyorsunuz, ne diye ağlayıp yüreğimi sızlatıyorsunuz? Ben Rab İsanın adı uğruna Yeruşalimde yalnız bağlanmaya değil, ölmeye de hazırım.››'),
(2010654,68,44,21,14,'Pavlusu ikna edemeyince, ‹‹Rabbin istediği olsun›› diyerek sustuk.'),
(2010655,68,44,21,15,'Bir süre sonra hazırlığımızı yapıp Yeruşalime doğru yola çıktık.'),
(2010656,68,44,21,16,'Sezariyedeki öğrencilerden bazıları da bizimle birlikte geldiler. Bizi, evinde kalacağımız adama, eski öğrencilerden Kıbrıslı Minasona götürdüler.'),
(2010657,68,44,21,17,'Yeruşalime vardığımız zaman kardeşler bizi sevinçle karşıladılar.'),
(2010658,68,44,21,18,'Ertesi gün Pavlusla birlikte Yakupu görmeye gittik. İhtiyarların hepsi orada toplanmıştı.'),
(2010659,68,44,21,19,'Pavlus, onların hal hatırını sorduktan sonra, hizmetinin aracılığıyla Tanrının öteki uluslar arasında yaptıklarını teker teker anlattı.'),
(2010660,68,44,21,20,'Bunları işitince Tanrıyı yücelttiler. Pavlusa, ‹‹Görüyorsun kardeş, Yahudiler arasında binlerce imanlı var ve hepsi Kutsal Yasanın candan savunucusudur›› dediler.'),
(2010661,68,44,21,21,'‹‹Ne var ki, duyduklarına göre sen öteki uluslar arasında yaşayan bütün Yahudilere, çocuklarını sünnet etmemelerini, törelerimize uymamalarını söylüyor, Musanın Yasasına sırt çevirmeleri gerektiğini öğretiyormuşsun.'),
(2010662,68,44,21,22,'Şimdi ne yapmalı? Senin buraya geldiğini mutlaka duyacaklar.'),
(2010663,68,44,21,23,'Bunun için sana dediğimizi yap. Aramızda adak adamış dört kişi var.'),
(2010664,68,44,21,24,'Bunları yanına al, kendileriyle birlikte arınma törenine katıl. Başlarını tıraş edebilmeleri için kurban masraflarını sen öde. Böylelikle herkes, seninle ilgili duyduklarının asılsız olduğunu, senin de Kutsal Yasaya uygun olarak yaşadığını anlasın.'),
(2010665,68,44,21,25,'Öteki uluslardan olan imanlılara gelince, biz onlara, putlara sunulan kurbanların etinden, kandan, boğularak öldürülen hayvanlardan ve fuhuştan sakınmalarını öngören kararımızı yazmıştık.››'),
(2010666,68,44,21,26,'Bunun üzerine Pavlus o dört kişiyi yanına aldı, ertesi gün onlarla birlikte arınma törenine katıldı. Sonra tapınağa girerek arınma günlerinin ne zaman tamamlanacağını, her birinin adına ne zaman kurban sunulacağını bildirdi.'),
(2010667,68,44,21,27,'Yedi günlük süre bitmek üzereydi. Asya İlinden bazı Yahudiler Pavlusu tapınakta görünce bütün kalabalığı kışkırtarak onu yakaladılar.'),
(2010668,68,44,21,28,'‹‹Ey İsrailliler, yardım edin!›› diye bağırdılar. ‹‹Her yerde herkese, halkımıza, Kutsal Yasaya ve bu kutsal yere karşı öğretiler yayan adam budur. Üstelik tapınağa bazı Grekleri sokarak bu kutsal yeri kirletti.››'),
(2010669,68,44,21,29,'Bu Yahudiler, daha önce kentte Pavlusun yanında gördükleri Efesli Trofimosun, Pavlus tarafından tapınağa sokulduğunu sanıyorlardı.'),
(2010670,68,44,21,30,'Bütün kent ayağa kalkmıştı. Her taraftan koşuşup gelen halk Pavlusu tutup tapınaktan dışarı sürükledi. Arkasından tapınağın kapıları hemen kapatıldı.'),
(2010671,68,44,21,31,'Onlar Pavlusu öldürmeye çalışırken, bütün Yeruşalimin karıştığı haberi Roma taburunun komutanına ulaştı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010672,68,44,21,32,'Komutan hemen yüzbaşılarla askerleri yanına alarak kalabalığın olduğu yere koştu. Komutanla askerleri gören halk Pavlusu dövmeyi bıraktı.'),
(2010673,68,44,21,33,'O zaman komutan yaklaşıp Pavlusu yakaladı, çift zincirle bağlanması için buyruk verdi. Sonra, ‹‹Kimdir bu adam, ne yaptı?›› diye sordu.'),
(2010674,68,44,21,34,'Kalabalıktakilerin her biri ayrı bir şey bağırıyordu. Kargaşalıktan ötürü kesin bilgi edinemeyen komutan, Pavlusun kaleye götürülmesini buyurdu.'),
(2010675,68,44,21,35,'Pavlus merdivenlere geldiğinde kalabalık öylesine azmıştı ki, askerler onu taşımak zorunda kaldılar.'),
(2010676,68,44,21,36,'Kalabalık, ‹‹Öldürün onu!›› diye bağırarak onları izliyordu.'),
(2010677,68,44,21,37,'Kaleden içeri girmek üzereyken Pavlus komutana, ‹‹Sana bir şey söyleyebilir miyim?›› dedi. Komutan, ‹‹Grekçe biliyor musun?›› dedi.'),
(2010678,68,44,21,38,'‹‹Sen bundan bir süre önce bir ayaklanma başlatıp dört bin tedhişçiyi çöle götüren Mısırlı değil misin?››'),
(2010679,68,44,21,39,'Pavlus, ‹‹Ben Kilikyadan Tarsuslu bir Yahudi, hiç de önemsiz olmayan bir kentin vatandaşıyım›› dedi. ‹‹Rica ederim, halka birkaç söz söylememe izin ver.››'),
(2010680,68,44,21,40,'Komutanın izin vermesi üzerine Pavlus merdivende dikilip eliyle halka bir işaret yaptı. Derin bir sessizlik olunca, İbrani dilinde konuşmaya başladı.'),
(2010681,68,44,22,1,'‹‹Kardeşler ve babalar, size şimdi yapacağım savunmayı dinleyin›› dedi.'),
(2010682,68,44,22,2,'Pavlusun kendilerine İbrani dilinde seslendiğini duyduklarında daha derin bir sessizlik oldu. Pavlus şöyle devam etti: ‹‹Ben Yahudiyim. Kilikyanın Tarsus Kentinde doğdum ve burada, Yeruşalimde Gamalielin dizinin dibinde büyüdüm. Atalarımızın yasasıyla ilgili sıkı bir eğitimden geçtim. Bugün hepinizin yaptığı gibi, ben de Tanrı için gayretle çalışan biriydim.'),
(2010683,68,44,22,4,'İsanın yolundan gidenlere öldüresiye zulmeder, kadın erkek demeden onları bağlayıp hapse atardım.'),
(2010684,68,44,22,5,'Başkâhin ile bütün kurul üyeleri söylediklerimi doğrulayabilirler. Onlardan Yahudi kardeşlere yazılmış mektuplar alarak Şama doğru yola çıkmıştım. Amacım, oradaki İsa inanlılarını da cezalandırmak üzere bağlayıp Yeruşalime getirmekti.'),
(2010685,68,44,22,6,'‹‹Ben öğleye doğru yol alıp Şama yaklaşırken, birdenbire gökten parlak bir ışık çevremi aydınlattı.'),
(2010686,68,44,22,7,'Yere yıkıldım. Bir sesin bana, ‹Saul, Saul! Neden bana zulmediyorsun?› dediğini işittim.'),
(2010687,68,44,22,8,'‹‹ ‹Ey Efendim, sen kimsin?› diye sordum. ‹‹Ses bana, ‹Ben senin zulmettiğin Nasıralı İsayım› dedi.'),
(2010688,68,44,22,9,'Yanımdakiler ışığı gördülerse de, benimle konuşanın söylediklerini anlamadılar.'),
(2010689,68,44,22,10,'‹‹ ‹Rab, ne yapmalıyım?› diye sordum. ‹‹Rab bana, ‹Kalk, Şama git› dedi, ‹Yapmanı tasarladığım her şey orada sana bildirilecek.›'),
(2010690,68,44,22,11,'Parlayan ışığın görkeminden gözlerim görmez olduğundan, yanımdakiler elimden tutup beni Şama götürdüler.'),
(2010691,68,44,22,12,'‹‹Orada Hananya adında dindar, Kutsal Yasaya bağlı biri vardı. Kentte yaşayan bütün Yahudilerin kendisinden övgüyle söz ettiği bu adam gelip yanımda durdu ve, ‹Saul kardeş, gözlerin görsün!› dedi. Ve ben o anda onu gördüm.'),
(2010692,68,44,22,14,'‹‹Hananya, ‹Atalarımızın Tanrısı, kendisinin isteğini bilmen ve Adil Olanı görüp Onun ağzından bir ses işitmen için seni seçmiştir› dedi.'),
(2010693,68,44,22,15,'‹Görüp işittiklerini bütün insanlara duyurarak Onun tanıklığını yapacaksın.'),
(2010694,68,44,22,16,'Haydi, ne bekliyorsun? Kalk, Onun adını anarak vaftiz ol ve günahlarından arın!›'),
(2010695,68,44,22,17,'‹‹Ben Yeruşalime döndükten sonra, tapınakta dua ettiğim bir sırada, kendimden geçerek Rabbi gördüm. Bana, ‹Çabuk ol› dedi, ‹Yeruşalimden hemen ayrıl. Çünkü benimle ilgili tanıklığını kabul etmeyecekler.›'),
(2010696,68,44,22,19,'‹‹ ‹Ya Rab› dedim, ‹Benim havradan havraya giderek sana inananları tutuklayıp dövdüğümü biliyorlar.'),
(2010697,68,44,22,20,'Üstelik sana tanıklık eden İstefanosun kanı döküldüğü zaman, ben de oradaydım. Onu öldürenlerin kaftanlarına bekçilik ederek yapılanları onayladım.›'),
(2010698,68,44,22,21,'‹‹Rab bana, ‹Git› dedi, ‹Seni uzaktaki uluslara göndereceğim.› ››'),
(2010699,68,44,22,22,'Pavlusu buraya kadar dinleyenler, bu söz üzerine, ‹‹Böylesini yeryüzünden temizlemeli, yaşaması uygun değil!›› diye seslerini yükselttiler.'),
(2010700,68,44,22,23,'Onlar böyle bağırır, üstlüklerini sallayıp havaya toz savururken komutan, Pavlusun kalenin içine götürülmesini buyurdu. Halkın neden Pavlusun aleyhine böyle bağırdığını öğrenmek için onun kamçılanarak sorguya çekilmesini istedi.'),
(2010701,68,44,22,25,'Kendisini sırımlarla bağlayıp kollarını geriyorlardı ki, Pavlus orada duran yüzbaşıya, ‹‹Mahkemesi yapılmamış bir Roma vatandaşını kamçılamanız yasaya uygun mudur?›› dedi.'),
(2010702,68,44,22,26,'Yüzbaşı bunu duyunca gidip komutana haber verdi. ‹‹Ne yapıyorsun?›› dedi. ‹‹Bu adam Roma vatandaşıymış.››'),
(2010703,68,44,22,27,'Komutan Pavlusun yanına geldi, ‹‹Söyle bakayım, sen Romalı mısın?›› diye sordu. Pavlus da, ‹‹Evet›› dedi.'),
(2010704,68,44,22,28,'Komutan, ‹‹Ben bu vatandaşlığı yüklü bir para ödeyerek elde ettim›› diye karşılık verdi. Pavlus, ‹‹Ben ise doğuştan Roma vatandaşıyım›› dedi.'),
(2010705,68,44,22,29,'Onu sorguya çekecek olanlar hemen yanından çekilip gittiler. Kendisini bağlatan komutan da, onun Roma vatandaşı olduğunu anlayınca korktu.'),
(2010706,68,44,22,30,'Komutan ertesi gün, Yahudiler''in Pavlus''u tam olarak neyle suçladıklarını öğrenmek için onu hapisten getirtti, başkâhinlerle bütün Yüksek Kurul''un toplanması için buyruk verdi ve onu aşağı indirip Kurul''un önüne çıkardı.'),
(2010707,68,44,23,1,'Yüksek Kurulu dikkatle süzen Pavlus, ‹‹Kardeşler›› dedi, ‹‹Ben bugüne dek Tanrının önünde tertemiz bir vicdanla yaşadım.››'),
(2010708,68,44,23,2,'Başkâhin Hananya, Pavlusun yanında duranlara onun ağzına vurmaları için buyruk verdi.'),
(2010709,68,44,23,3,'Bunun üzerine Pavlus ona, ‹‹Seni badanalı duvar, Tanrı sana vuracaktır!›› dedi. ‹‹Hem oturmuş Kutsal Yasaya göre beni yargılıyorsun, hem de Yasayı çiğneyerek beni dövdürüyorsun.››'),
(2010710,68,44,23,4,'Çevrede duranlar, ‹‹Tanrının başkâhinine hakaret mi ediyorsun?›› dediler.'),
(2010711,68,44,23,5,'Pavlus, ‹‹Kardeşler, başkâhin olduğunu bilmiyordum›› dedi. ‹‹Nitekim, ‹Halkını yönetenleri kötüleme› diye yazılmıştır.››'),
(2010712,68,44,23,6,'Oradakilerden bir bölümünün Saduki, öbürlerinin de Ferisi mezhebinden olduğunu anlayan Pavlus, Yüksek Kurula şöyle seslendi: ‹‹Kardeşler, ben özbeöz Ferisiyim. Ölülerin dirileceği umudunu beslediğim için yargılanmaktayım.››'),
(2010713,68,44,23,7,'Pavlusun bu sözü üzerine Ferisilerle Sadukiler çekişmeye başladılar, Kurul ikiye bölündü.'),
(2010714,68,44,23,8,'Sadukiler, ölümden diriliş, melek ve ruh yoktur derler; Ferisiler ise bunların hepsine inanırlar.'),
(2010715,68,44,23,9,'Kurulda büyük bir kargaşalık çıktı. Ferisi mezhebinden bazı din bilginleri kalkıp ateşli bir şekilde, ‹‹Bu adamda hiçbir suç görmüyoruz›› diye bağırdılar. ‹‹Bir ruh ya da bir melek kendisiyle konuşmuşsa, ne olmuş?››'),
(2010716,68,44,23,10,'Çekişme öyle şiddetlendi ki komutan, Pavlusu parçalayacaklar diye korktu. Askerlerin aşağı inip onu zorla aralarından alarak kaleye götürmelerini buyurdu.'),
(2010717,68,44,23,11,'O gece Rab Pavlusa görünüp, ‹‹Cesur ol›› dedi, ‹‹Yeruşalimde benimle ilgili nasıl tanıklık ettinse, Romada da öyle tanıklık etmen gerekir.››'),
(2010718,68,44,23,12,'Ertesi sabah Yahudiler aralarında gizli bir anlaşma yaptılar. ‹‹Pavlusu öldürmeden bir şey yiyip içersek, bize lanet olsun!›› diye ant içtiler.'),
(2010719,68,44,23,13,'Bu anlaşmaya katılanların sayısı kırkı aşıyordu.'),
(2010720,68,44,23,14,'Bunlar başkâhinlerle ileri gelenlerin yanına gidip şöyle dediler: ‹‹Biz, ‹Pavlusu öldürmeden ağzımıza bir şey koyarsak, bize lanet olsun!› diye ant içtik.'),
(2010721,68,44,23,15,'Şimdi siz Yüksek Kurulla birlikte, Pavlusa ilişkin durumu daha ayrıntılı bir şekilde araştıracakmış gibi, komutanın onu size getirmesini rica edin. Biz de, Pavlus daha Kurula gelmeden onu öldürmeye hazır olacağız.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010722,68,44,23,16,'Ne var ki, Pavlusun kızkardeşinin oğlu onların pusu kurduğunu duydu. Varıp kaleye girdi ve haberi Pavlusa iletti.'),
(2010723,68,44,23,17,'Yüzbaşılardan birini yanına çağıran Pavlus, ‹‹Bu genci komutana götür, kendisine ileteceği bir haber var›› dedi.'),
(2010724,68,44,23,18,'Yüzbaşı, genci alıp komutana götürdü. ‹‹Tutuklu Pavlus beni çağırıp bu genci sana getirmemi rica etti. Sana bir söyleyeceği varmış›› dedi.'),
(2010725,68,44,23,19,'Komutan, genci elinden tutup bir yana çekti. ‹‹Bana bildirmek istediğin nedir?›› diye sordu.'),
(2010726,68,44,23,20,'‹‹Yahudiler sözbirliği ettiler›› dedi, ‹‹Pavlusla ilgili durumu daha ayrıntılı bir şekilde araştırmak istiyorlarmış gibi, yarın onu Yüksek Kurula götürmeni rica edecekler.'),
(2010727,68,44,23,21,'Ama sen onlara kanma! Aralarından kırktan fazla kişi ona pusu kurmuş bekliyor. ‹Onu ortadan kaldırmadan bir şey yiyip içersek, bize lanet olsun!› diye ant içtiler. Şimdi hazırlar, senden olumlu bir yanıt gelmesini bekliyorlar.››'),
(2010728,68,44,23,22,'Komutan, ‹‹Bunları bana açıkladığını hiç kimseye söyleme›› diye uyardıktan sonra genci salıverdi.'),
(2010729,68,44,23,23,'Komutan, yüzbaşılardan ikisini yanına çağırıp şöyle dedi: ‹‹Akşam saat dokuzda Sezariyeye hareket etmek üzere iki yüz piyade, yetmiş atlı ve iki yüz mızraklı hazırlayın.'),
(2010730,68,44,23,24,'Ayrıca Pavlusu bindirip Vali Feliksin yanına sağ salim ulaştırmak için hayvan sağlayın.››'),
(2010731,68,44,23,25,'Sonra şöyle bir mektup yazdı: ‹‹Klavdius Lisiastan, Sayın Vali Felikse selam.'),
(2010732,68,44,23,27,'Bu adamı Yahudiler yakalamış öldürmek üzereydiler. Ne var ki, kendisinin Roma vatandaşı olduğunu öğrenince askerlerle yetişip onu kurtardım.'),
(2010733,68,44,23,28,'Kendisini neyle suçladıklarını bilmek istediğim için onu Yahudilerin Yüksek Kurulunun önüne çıkarttım.'),
(2010734,68,44,23,29,'Suçlamanın, Yahudilerin yasasına ilişkin bazı sorunlarla ilgili olduğunu öğrendim. Ölüm ya da hapis cezasını gerektiren herhangi bir suçlama yoktu.'),
(2010735,68,44,23,30,'Bana bu adama karşı bir tuzak kurulduğu bildirilince onu hemen sana gönderdim. Onu suçlayanlara da kendisiyle ilgili şikâyetlerini sana bildirmelerini buyurdum.››'),
(2010736,68,44,23,31,'Askerler, kendilerine verilen buyruk uyarınca Pavlusu alıp geceleyin Antipatrise götürdüler.'),
(2010737,68,44,23,32,'Ertesi gün, atlıları Pavlusla birlikte yola devam etmek üzere bırakarak kaleye döndüler.'),
(2010738,68,44,23,33,'Atlılar Sezariyeye varınca mektubu valiye verip Pavlusu teslim ettiler.'),
(2010739,68,44,23,34,'Vali mektubu okuduktan sonra Pavlus''un hangi ilden olduğunu sordu. Kilikyalı olduğunu öğrenince, ‹‹Seni suçlayanlar da gelsin, o zaman seni dinlerim›› dedi. Sonra Pavlus''un, Hirodes''in sarayında gözaltında tutulması için buyruk verdi.'),
(2010740,68,44,24,1,'Bundan beş gün sonra Başkâhin Hananya, bazı ileri gelenler ve Tertullus adlı bir hatip Sezariyeye gelip Pavlusla ilgili şikâyetlerini valiye ilettiler.'),
(2010741,68,44,24,2,'Pavlus çağrılınca Tertullus suçlamalarına başladı. ‹‹Ey erdemli Feliks!›› dedi. ‹‹Senin sayende uzun süredir esenlik içinde yaşamaktayız. Aldığın önlemlerle de bu ulusun yararına olumlu gelişmeler kaydedilmiştir. Yaptıklarını, her zaman ve her yerde büyük bir şükranla anıyoruz.'),
(2010742,68,44,24,4,'Seni fazla yormak istemiyorum; söyleyeceğimiz birkaç sözü hoşgörüyle dinlemeni rica ediyorum.'),
(2010743,68,44,24,5,'‹‹Biz şunu anladık ki, bu adam dünyanın her yanında bütün Yahudiler arasında kargaşalık çıkaran bir fesatçı ve Nasrani tarikatının elebaşılarından biridir.'),
(2010744,68,44,24,6,'Tapınağı bile kirletmeye kalkıştı. Ama biz onu yakaladık. Onu sorguya çekersen, onunla ilgili bütün suçlamalarımızın doğruluğunu kendisinden öğrenebilirsin.››'),
(2010745,68,44,24,9,'Oradaki Yahudiler de anlatılanların doğru olduğunu söyleyerek bu suçlamalara katıldılar.'),
(2010746,68,44,24,10,'Valinin bir işareti üzerine Pavlus şöyle karşılık verdi: ‹‹Senin yıllardan beri bu ulusa yargıçlık ettiğini bildiğim için, kendi savunmamı sevinçle yapıyorum.'),
(2010747,68,44,24,11,'Sen kendin de öğrenebilirsin, tapınmak amacıyla Yeruşalime gidişimden bu yana sadece on iki gün geçti.'),
(2010748,68,44,24,12,'Beni ne tapınakta, ne havralarda, ne de kentin başka bir yerinde herhangi biriyle tartışırken ya da halkı ayaklandırmaya çalışırken görmüşlerdir.'),
(2010749,68,44,24,13,'Şu anda bana yönelttikleri suçlamaları da sana kanıtlayamazlar.'),
(2010750,68,44,24,14,'Bununla birlikte, sana şunu itiraf edeyim ki, kendilerinin tarikat dedikleri Yolun bir izleyicisi olarak atalarımızın Tanrısına kulluk ediyorum. Kutsal Yasada ve peygamberlerin kitaplarında yazılı her şeye inanıyorum.'),
(2010751,68,44,24,15,'Aynı bu adamların kabul ettiği gibi, hem doğru kişilerin hem doğru olmayanların ölümden dirileceğine dair Tanrıya umut bağladım.'),
(2010752,68,44,24,16,'Bu nedenle ben gerek Tanrı, gerek insanlar önünde vicdanımı temiz tutmaya her zaman özen gösteriyorum.'),
(2010753,68,44,24,17,'‹‹Uzun yıllar sonra, ulusuma bağışlar getirmek ve adaklar sunmak için Yeruşalime geldim.'),
(2010754,68,44,24,18,'Beni tapınakta adaklar sunarken buldukları zaman arınmış durumdaydım. Çevremde ne bir kalabalık ne de karışıklık vardı. Ancak orada Asya İlinden bazı Yahudiler bulunuyordu.'),
(2010755,68,44,24,19,'Onların bana karşı bir diyecekleri varsa, senin önüne çıkıp suçlamalarını belirtmeleri gerekir.'),
(2010756,68,44,24,20,'Buradakiler de, Yüksek Kurulun önündeki duruşmam sırasında bende ne suç bulduklarını açıklasınlar.'),
(2010757,68,44,24,21,'Önlerine çıkarıldığımda, ‹Bugün, ölülerin dirilişi konusunda tarafınızdan yargılanmaktayım› diye seslenmiştim. Olsa olsa beni bu konuda suçlayabilirler.››'),
(2010758,68,44,24,22,'İsanın yoluna ilişkin derin bilgisi olan Feliks duruşmayı başka bir güne ertelerken, ‹‹Davanızla ilgili kararımı komutan Lisias gelince veririm›› dedi.'),
(2010759,68,44,24,23,'Oradaki yüzbaşıya da Pavlusu gözaltında tutmasını, ama kendisine biraz serbestlik tanımasını, ona yardımda bulunmak isteyen dostlarından hiçbirine engel olmamasını buyurdu.'),
(2010760,68,44,24,24,'Birkaç gün sonra Feliks, Yahudi olan karısı Drusilla ile birlikte geldi, Pavlusu çağırtarak Mesih İsaya olan inancı konusunda onu dinledi.'),
(2010761,68,44,24,25,'Pavlus doğruluk, özdenetim ve gelecek olan yargı gününden söz edince Feliks korkuya kapıldı. ‹‹Şimdilik gidebilirsin›› dedi, ‹‹Fırsat bulunca seni yine çağırtırım.››'),
(2010762,68,44,24,26,'Bir yandan da Pavlusun kendisine rüşvet vereceğini umuyordu. Bu nedenle onu sık sık çağırtır, onunla sohbet ederdi.'),
(2010763,68,44,24,27,'İki yıl dolunca görevini Porkius Festus''a devreden Feliks, Yahudiler''in gönlünü kazanmak amacıyla Pavlus''u hapiste bıraktı.'),
(2010764,68,44,25,1,'Eyalete vardıktan üç gün sonra Festus, Sezariyeden Yeruşalime gitti.'),
(2010765,68,44,25,2,'Başkâhinlerle Yahudilerin ileri gelenleri, Pavlusla ilgili şikâyetlerini ona açıkladılar. Festustan kendilerine bir iyilikte bulunmasını isteyerek Pavlusu Yeruşalime getirtmesi için yalvardılar. Bu arada pusu kurup Pavlusu yolda öldüreceklerdi.'),
(2010766,68,44,25,4,'Festus ise Pavlusun Sezariyede tutuklu bulunduğunu, kendisinin de yakında oraya gideceğini söyleyerek, ‹‹Aranızda yetkili olanlar benimle gelsinler; bu adam yanlış bir şey yapmışsa, ona karşı suç duyurusunda bulunsunlar›› dedi.'),
(2010767,68,44,25,6,'Festus, onların arasında sadece sekiz on gün kadar kaldı; sonra Sezariyeye döndü. Ertesi gün yargı kürsüsüne oturarak Pavlusun getirilmesini buyurdu.'),
(2010768,68,44,25,7,'Pavlus içeri girince, Yeruşalimden gelen Yahudiler çevresini sardılar ve kanıtlayamadıkları birçok ağır suçlamada bulundular.'),
(2010769,68,44,25,8,'Pavlus, ‹‹Ne Yahudilerin yasasına, ne tapınağa, ne de Sezara karşı hiçbir günah işlemedim›› diyerek kendini savundu.'),
(2010770,68,44,25,9,'Yahudilerin gönlünü kazanmak isteyen Festus, Pavlusa şöyle karşılık verdi: ‹‹Yeruşalime gidip orada benim önümde bu konularda yargılanmak ister misin?››'),
(2010771,68,44,25,10,'Pavlus, ‹‹Ben Sezarın yargı kürsüsü önünde durmaktayım›› dedi, ‹‹Burada yargılanmam gerekir. Sen de çok iyi biliyorsun ki, Yahudilere karşı hiçbir suç işlemedim.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010772,68,44,25,11,'Şayet suçum varsa, ölüm cezasını gerektirecek bir şey yapmışsam, ölmekten çekinmem. Yok eğer bunların bana karşı yaptığı suçlamalar asılsız ise, hiç kimse beni onların eline teslim edemez. Davamın Sezara iletilmesini istiyorum.››'),
(2010773,68,44,25,12,'Festus, danışma kuruluyla görüştükten sonra şu yanıtı verdi: ‹‹Davanı Sezara ilettin, Sezara gideceksin.››'),
(2010774,68,44,25,13,'Birkaç gün sonra Kral Agrippa ile Berniki, Festusa bir nezaket ziyaretinde bulunmak üzere Sezariyeye geldiler.'),
(2010775,68,44,25,14,'Bir süre orada kaldılar. Bu arada Festus, Pavlusla ilgili durumu krala anlattı. ‹‹Feliksin tutuklu olarak bıraktığı bir adam var›› dedi.'),
(2010776,68,44,25,15,'‹‹Yeruşalimde bulunduğum sırada Yahudilerin başkâhinleriyle ileri gelenleri, onunla ilgili şikâyetlerini açıkladılar, onu cezalandırmamı istediler.'),
(2010777,68,44,25,16,'‹‹Ben onlara, ‹Herhangi bir sanığı, kendisini suçlayanlarla yüzleştirmeden, kendisine yöneltilen ithamlarla ilgili olarak savunma fırsatı vermeden, onu suçlayanların eline teslim etmek Romalıların geleneğine aykırıdır› dedim.'),
(2010778,68,44,25,17,'Onlar benimle buraya gelince, hiç vakit kaybetmeden, ertesi gün yargı kürsüsüne oturup adamın getirilmesini buyurdum.'),
(2010779,68,44,25,18,'Ne var ki, kalkıp konuşan davacılar ona, beklediğim türden kötülüklerle ilgili hiçbir suçlama yöneltmediler.'),
(2010780,68,44,25,19,'Ancak onunla çekiştikleri bazı sorunlar vardı. Bunlar, kendi dinlerine ve ölmüş de Pavlusun iddiasına göre yaşamakta olan İsa adındaki birine ilişkin konulardı.'),
(2010781,68,44,25,20,'Bunları nasıl soruşturacağımı bilemediğim için Pavlusa, Yeruşalime gidip orada bu konularda yargılanmaya razı olup olmayacağını sordum.'),
(2010782,68,44,25,21,'Ama kendisi davasını İmparatora iletti, İmparatorun kararına dek tutuklu kalmak istedi. Ben de onu İmparatora göndereceğim zamana kadar tutuklu kalmasını buyurdum.››'),
(2010783,68,44,25,22,'Agrippa Festusa, ‹‹Ben de bu adamı dinlemek isterdim›› dedi. Festus da, ‹‹Yarın onu dinlersin›› dedi.'),
(2010784,68,44,25,23,'Ertesi gün Agrippa ile Berniki büyük bir tantanayla gelip komutanlar ve kentin ileri gelenleriyle birlikte toplantı salonuna girdiler. Festusun buyruğu üzerine Pavlus içeri getirildi.'),
(2010785,68,44,25,24,'Festus, ‹‹Kral Agrippa ve burada bizimle bulunan bütün efendiler›› dedi, ‹‹Yeruşalimde olsun, burada olsun, bütün Yahudi halkının bana şikâyet ettiği bu adamı görüyorsunuz. ‹Onu artık yaşatmamalı!› diye haykırıyorlardı.'),
(2010786,68,44,25,25,'Oysa ben, ölüm cezasını gerektiren hiçbir suç işlemediğini anladım. Yine de, kendisi davasının İmparatora iletilmesini istediğinden, onu göndermeye karar verdim.'),
(2010787,68,44,25,26,'Ama Efendimize bu adamla ilgili yazacak kesin bir şeyim yok. Bu yüzden onu sizin önünüze ve özellikle, Kral Agrippa, senin önüne çıkartmış bulunuyorum. Amacım, bu soruşturmanın sonucunda yazacak bir şey bulabilmektir.'),
(2010788,68,44,25,27,'Bir tutukluyu İmparator''a gönderirken, kendisine yöneltilen suçlamaları belirtmemek bence anlamsız.››'),
(2010789,68,44,26,1,'Agrippa Pavlusa, ‹‹Kendini savunabilirsin›› dedi. Bunun üzerine Pavlus elini uzatarak savunmasına şöyle başladı: ‹‹Kral Agrippa! Yahudilerin bana yönelttiği bütün suçlamalarla ilgili olarak savunmamı bugün senin önünde yapacağım için kendimi mutlu sayıyorum.'),
(2010790,68,44,26,3,'Özellikle şuna seviniyorum ki, sen Yahudilerin bütün törelerini ve sorunlarını yakından bilen birisin. Bu nedenle beni sabırla dinlemeni rica ediyorum.'),
(2010791,68,44,26,4,'‹‹Bütün Yahudiler, gerek başlangıçta kendi memleketimde, gerek Yeruşalimde, gençliğimden beri nasıl yaşadığımı bilirler.'),
(2010792,68,44,26,5,'Beni eskiden beri tanırlar ve isteseler, geçmişte dinimizin en titiz mezhebi olan Ferisiliğe bağlı yaşadığıma tanıklık edebilirler.'),
(2010793,68,44,26,6,'Şimdi ise, Tanrının atalarımıza olan vaadine umut bağladığım için burada bulunmakta ve yargılanmaktayım.'),
(2010794,68,44,26,7,'Bu, on iki oymağımızın gece gündüz Tanrıya canla başla kulluk ederek erişmeyi umdukları vaattir. Ey kralım, Yahudilerin bana yönelttikleri suçlamalar bu umutla ilgilidir.'),
(2010795,68,44,26,8,'Sizler, Tanrının ölüleri diriltmesini neden ‹inanılmaz› görüyorsunuz?'),
(2010796,68,44,26,9,'‹‹Doğrusu ben de, Nasıralı İsa adına karşı elimden geleni yapmam gerektiği düşüncesindeydim.'),
(2010797,68,44,26,10,'Ve Yeruşalimde bunu yaptım. Başkâhinlerden aldığım yetkiyle kutsallardan birçoğunu hapse attırdım; ölüm cezasına çarptırıldıkları zaman oyumu onların aleyhinde kullandım.'),
(2010798,68,44,26,11,'Bütün havraları dolaşıp sık sık onları cezalandırır, inandıklarına küfretmeye zorlardım. Öylesine kudurmuştum ki, onlara zulmetmek için bulundukları yabancı kentlere bile giderdim.'),
(2010799,68,44,26,12,'‹‹Bir keresinde başkâhinlerden aldığım yetki ve görevle Şama doğru yola çıkmıştım.'),
(2010800,68,44,26,13,'Ey kralım, öğlende yolda giderken, gökten gelip benim ve yol arkadaşlarımın çevresini aydınlatan, güneşten daha parlak bir ışık gördüm.'),
(2010801,68,44,26,14,'Hepimiz yere yıkılmıştık. Bir sesin bana İbrani dilinde seslendiğini duydum. ‹Saul, Saul, neden bana zulmediyorsun?› dedi. ‹Üvendireye karşı tepmekle kendine zarar veriyorsun.›'),
(2010802,68,44,26,15,'‹‹Ben de, ‹Ey Efendim, sen kimsin?› dedim. ‹‹ ‹Ben senin zulmettiğin İsayım› diye yanıt verdi Rab.'),
(2010803,68,44,26,16,'‹Haydi, ayağa kalk. Seni hizmetimde görevlendirmek için sana göründüm. Hem gördüklerine, hem de kendimle ilgili sana göstereceklerime tanıklık edeceksin.'),
(2010804,68,44,26,17,'Seni kendi halkının ve öteki ulusların elinden kurtaracağım. Seni, ulusların gözlerini açmak ve onları karanlıktan ışığa, Şeytanın hükümranlığından Tanrıya döndürmek için gönderiyorum. Öyle ki, bana iman ederek günahlarının affına kavuşsunlar ve kutsal kılınanların arasında yer alsınlar.›'),
(2010805,68,44,26,19,'‹‹Bunun için, ey Kral Agrippa, bu göksel görüme uymazlık etmedim.'),
(2010806,68,44,26,20,'Önce Şam ve Yeruşalim halkını, sonra bütün Yahudiye bölgesini ve öteki ulusları, tövbe edip Tanrıya dönmeye ve bu tövbeye yaraşır işler yapmaya çağırdım.'),
(2010807,68,44,26,21,'Yahudilerin beni tapınakta yakalayıp öldürmeye kalkmalarının nedeni buydu.'),
(2010808,68,44,26,22,'Ama bugüne dek Tanrı yardımcım oldu. Bu sayede burada duruyor, büyük küçük herkese tanıklık ediyorum. Benim söylediklerim, peygamberlerin ve Musanın önceden haber verdiği olaylardan başka bir şey değildir.'),
(2010809,68,44,26,23,'Onlar, Mesihin acı çekeceğini ve ölümden dirilenlerin ilki olarak gerek kendi halkına, gerek öteki uluslara ışığın doğuşunu ilan edeceğini bildirmişlerdi.››'),
(2010810,68,44,26,24,'Pavlus bu şekilde savunmasını sürdürürken Festus yüksek sesle, ‹‹Pavlus, çıldırmışsın sen! Çok okumak seni delirtiyor!›› dedi.'),
(2010811,68,44,26,25,'Pavlus, ‹‹Sayın Festus›› dedi, ‹‹Ben çıldırmış değilim. Gerçek ve akla uygun sözler söylüyorum.'),
(2010812,68,44,26,26,'Kral bu konularda bilgili olduğu için kendisiyle çekinmeden konuşuyorum. Bu olaylardan hiçbirinin onun dikkatinden kaçmadığı kanısındayım. Çünkü bunlar ücra bir köşede yapılmış işler değildir.'),
(2010813,68,44,26,27,'Kral Agrippa, sen peygamberlerin sözlerine inanıyor musun? İnandığını biliyorum.››'),
(2010814,68,44,26,28,'Agrippa Pavlusa şöyle dedi: ‹‹Bu kadar kısa bir sürede beni ikna edip Mesihçi mi yapacaksın?››'),
(2010815,68,44,26,29,'‹‹İster kısa ister uzun sürede olsun›› dedi Pavlus, ‹‹Tanrıdan dilerim ki yalnız sen değil, bugün beni dinleyen herkes, bu zincirler dışında benim gibi olsun!››'),
(2010816,68,44,26,30,'Kral, vali, Berniki ve onlarla birlikte oturanlar kalkıp dışarı çıktıktan sonra aralarında şöyle konuştular: ‹‹Bu adamın, ölüm ya da hapis cezasını gerektiren bir şey yaptığı yok.››'),
(2010817,68,44,26,32,'Agrippa da Festus''a, ‹‹Bu adam davasını Sezar''a iletmeseydi, serbest bırakılabilirdi›› dedi.'),
(2010818,68,44,27,1,'İtalyaya doğru yelken açmamıza karar verilince, Pavlusla öteki bazı tutukluları Avgustus taburundan Yulius adlı bir yüzbaşıya teslim ettiler.'),
(2010819,68,44,27,2,'Asya İlinin kıyılarındaki limanlara uğrayacak olan bir Edremit gemisine binerek denize açıldık. Selanikten Makedonyalı Aristarhus da yanımızdaydı.'),
(2010820,68,44,27,3,'Ertesi gün Saydaya uğradık. Pavlusa dostça davranan Yulius, ihtiyaçlarını karşılamaları için dostlarının yanına gitmesine izin verdi.'),
(2010821,68,44,27,4,'Oradan yine denize açıldık. Rüzgar ters yönden estiği için Kıbrısın rüzgar altından geçtik.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010822,68,44,27,5,'Kilikya ve Pamfilya açıklarından geçerek Likyanın Mira Kentine geldik.'),
(2010823,68,44,27,6,'Orada, İtalyaya gidecek bir İskenderiye gemisi bulan yüzbaşı, bizi o gemiye bindirdi.'),
(2010824,68,44,27,7,'Günlerce ağır ağır yol alarak Knidos Kentinin açıklarına güçlükle gelebildik. Rüzgar bize engel olduğundan Salmone burnundan dolanarak Giritin rüzgar altından geçtik.'),
(2010825,68,44,27,8,'Kıyı boyunca güçlükle ilerleyerek Laseya Kentinin yakınlarında bulunan ve Güzel Limanlar denilen bir yere geldik.'),
(2010826,68,44,27,9,'Epey vakit kaybetmiştik; oruç günü bile geçmişti. O mevsimde deniz yolculuğu tehlikeli olacaktı. Bu nedenle Pavlus onları uyardı: ‹‹Efendiler›› dedi, ‹‹Bu yolculuğun yalnız yük ve gemiye değil, canlarımıza da çok zarar ve ziyan getireceğini görüyorum.››'),
(2010827,68,44,27,11,'Ama yüzbaşı, Pavlusun söylediklerini dinleyeceğine, kaptanla gemi sahibinin sözüne uydu.'),
(2010828,68,44,27,12,'Liman kışlamaya elverişli olmadığından gemidekilerin çoğu, oradan tekrar denize açılmaya, mümkünse Fenikse ulaşıp kışı orada geçirmeye karar verdiler. Feniks, Giritin lodos ve karayele kapalı bir limanıdır.'),
(2010829,68,44,27,13,'Güneyden hafif bir rüzgar esmeye başlayınca, bekledikleri anın geldiğini sanarak demir aldılar; Girit kıyısını yakından izleyerek ilerlemeye başladılar.'),
(2010830,68,44,27,14,'Ne var ki, çok geçmeden karadan Evrakilon denen bir kasırga koptu.'),
(2010831,68,44,27,15,'Kasırgaya tutulan gemi rüzgara karşı gidemeyince, kendimizi sürüklenmeye bıraktık.'),
(2010832,68,44,27,16,'Gavdos denen küçük bir adanın rüzgar altına sığınarak geminin filikasını güçlükle sağlama alabildik.'),
(2010833,68,44,27,17,'Filikayı yukarı çektikten sonra halatlar kullanarak gemiyi alttan kuşattılar. Sirte Körfezinin sığlıklarında karaya oturmaktan korktukları için yelken takımlarını indirip kendilerini sürüklenmeye bıraktılar.'),
(2010834,68,44,27,18,'Fırtına bizi bir hayli hırpaladığı için ertesi gün gemiden yük atmaya başladılar.'),
(2010835,68,44,27,19,'Üçüncü gün geminin takımlarını kendi elleriyle denize attılar.'),
(2010836,68,44,27,20,'Günlerce ne güneş ne de yıldızlar göründü. Fırtına da olanca şiddetiyle sürdüğünden, artık kurtuluş umudunu tümden yitirmiştik.'),
(2010837,68,44,27,21,'Adamlar uzun zaman yemek yiyemeyince Pavlus ortaya çıkıp şöyle dedi: ‹‹Efendiler, beni dinleyip Giritten ayrılmamanız, bu zarar ve ziyana uğramamanız gerekirdi.'),
(2010838,68,44,27,22,'Şimdi size öğüdüm şu: Cesur olun! Gemi mahvolacak, ama aranızda hiçbir can kaybı olmayacak.'),
(2010839,68,44,27,23,'Çünkü kendisine ait olduğum, kendisine kulluk ettiğim Tanrının bir meleği bu gece yanıma gelip dedi ki, ‹Korkma Pavlus, Sezarın önüne çıkman gerekiyor. Dahası Tanrı, seninle birlikte yolculuk edenlerin hepsini sana bağışlamıştır.›'),
(2010840,68,44,27,25,'Bunun için efendiler, cesur olun! Tanrıya inanıyorum ki, her şey tıpkı bana bildirildiği gibi olacak.'),
(2010841,68,44,27,26,'Ancak bir adada karaya oturmamız gerekiyor.››'),
(2010842,68,44,27,27,'On dördüncü gece İyon Denizinde sürükleniyorduk. Gece yarısına doğru gemiciler karaya yaklaştıklarını sezinlediler.'),
(2010843,68,44,27,28,'Denizin derinliğini ölçtüler ve yirmi kulaç olduğunu gördüler. Biraz ilerledikten sonra bir daha ölçtüler, on beş kulaç olduğunu gördüler.'),
(2010844,68,44,27,29,'Kayalıklara bindirmekten korkarak kıçtan dört demir attılar ve günün tez doğması için dua ettiler.'),
(2010845,68,44,27,30,'Bu sırada gemiciler gemiden kaçma girişiminde bulundular. Baş taraftan demir atacaklarmış gibi yapıp filikayı denize indirdiler.'),
(2010846,68,44,27,31,'Ama Pavlus yüzbaşıyla askerlere, ‹‹Bunlar gemide kalmazsa, siz kurtulamazsınız›› dedi.'),
(2010847,68,44,27,32,'Bunun üzerine askerler ipleri kesip filikayı denize düşürdüler.'),
(2010848,68,44,27,33,'Gün doğmak üzereyken Pavlus herkesi yemek yemeye çağırdı. ‹‹Bugün on dört gündür kaygılı bir bekleyiş içindesiniz, hiçbir şey yemeyip aç kaldınız›› dedi.'),
(2010849,68,44,27,34,'‹‹Bunun için size rica ediyorum, yemek yiyin. Kurtuluşunuz için bu gerekli. Hiçbirinizin başından tek kıl bile eksilmeyecektir.››'),
(2010850,68,44,27,35,'Pavlus bunları söyledikten sonra ekmek aldı, hepsinin önünde Tanrıya şükretti, ekmeği bölüp yemeye başladı.'),
(2010851,68,44,27,36,'Hepsi bundan cesaret alarak yemek yedi.'),
(2010852,68,44,27,37,'Gemide toplam iki yüz yetmiş altı kişiydik.'),
(2010853,68,44,27,38,'Herkes doyduktan sonra, buğdayı denize boşaltarak gemiyi hafiflettiler.'),
(2010854,68,44,27,39,'Gündüz olunca gördükleri karayı tanıyamadılar. Ama kumsalı olan bir körfez farkederek, mümkünse gemiyi orada karaya oturtmaya karar verdiler.'),
(2010855,68,44,27,40,'Demirleri kesip denizde bıraktılar. Aynı anda dümenlerin iplerini çözüp ön yelkeni rüzgara vererek kumsala yöneldiler.'),
(2010856,68,44,27,41,'Gemi bir kum yükseltisine çarpıp karaya oturdu. Geminin başı kuma saplanıp kımıldamaz oldu, kıç tarafı ise dalgaların şiddetiyle dağılmaya başladı.'),
(2010857,68,44,27,42,'Askerler, tutuklulardan hiçbiri yüzerek kaçmasın diye onları öldürmek niyetindeydi.'),
(2010858,68,44,27,43,'Ama Pavlus''u kurtarmak isteyen yüzbaşı askerleri bu düşünceden vazgeçirdi. Önce yüzme bilenlerin denize atlayıp karaya çıkmalarını, sonra geriye kalanların, kiminin tahtalara kiminin de geminin öbür döküntülerine tutunarak onları izlemesini buyurdu. Böylelikle herkes sağ salim karaya çıktı.'),
(2010859,68,44,28,1,'Kurtulduktan sonra adanın Malta adını taşıdığını öğrendik.'),
(2010860,68,44,28,2,'Yerliler bize olağanüstü bir yakınlık gösterdiler. Hava yağışlı ve soğuk olduğu için ateş yakıp hepimizi dostça karşıladılar.'),
(2010861,68,44,28,3,'Pavlus bir yığın çalı çırpı toplayıp ateşin üzerine attı. O anda ısıdan kaçan bir engerek onun eline yapıştı.'),
(2010862,68,44,28,4,'Yerliler Pavlusun eline asılan yılanı görünce birbirlerine, ‹‹Bu adam kuşkusuz bir katil›› dediler. ‹‹Denizden kurtuldu, ama adalet onu yaşatmadı.››'),
(2010863,68,44,28,5,'Ne var ki, elini silkip yılanı ateşin içine fırlatan Pavlus hiçbir zarar görmedi.'),
(2010864,68,44,28,6,'Halk, Pavlusun bedeninin şişmesini ya da birdenbire düşüp ölmesini bekliyordu. Ama uzun süre bekleyip de ona bir şey olmadığını görünce fikirlerini değiştirdiler. ‹‹Bu bir ilahtır!›› dediler.'),
(2010865,68,44,28,7,'Bulunduğumuz yerin yakınında adanın baş yetkilisi olan Publius adlı birinin toprakları vardı. Bu adam bizi evine kabul ederek üç gün dostça ağırladı.'),
(2010866,68,44,28,8,'O sırada Publiusun babası kanlı ishale yakalanmış ateşler içinde yatıyordu. Hastanın yanına giren Pavlus dua etti, ellerini üzerine koyup onu iyileştirdi.'),
(2010867,68,44,28,9,'Bu olay üzerine adadaki öbür hastalar da gelip iyileştirildiler.'),
(2010868,68,44,28,10,'Bizi bir sürü armağanla onurlandırdılar; denize açılacağımız zaman gereksindiğimiz malzemeleri gemiye yüklediler.'),
(2010869,68,44,28,11,'Üç ay sonra, kışı adada geçiren ve ikiz tanrılar simgesini taşıyan bir İskenderiye gemisiyle denize açıldık.'),
(2010870,68,44,28,12,'Sirakuza Kentine uğrayıp üç gün kaldık.'),
(2010871,68,44,28,13,'Oradan da yolumuza devam ederek Regiuma geldik. Ertesi gün güneyden esmeye başlayan rüzgarın yardımıyla iki günde Puteoliye vardık.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010872,68,44,28,14,'Orada bulduğumuz kardeşler, bizi yanlarında bir hafta kalmaya çağırdılar. Sonunda Romaya vardık.'),
(2010873,68,44,28,15,'Haberimizi alan Romadaki kardeşler, bizi karşılamak için Appius Çarşısına ve Üç Hanlara kadar geldiler. Pavlus onları görünce Tanrıya şükretti, yüreklendi.'),
(2010874,68,44,28,16,'Romaya girdiğimizde Pavlusun, bir asker gözetiminde yalnız başına kalmasına izin verildi.'),
(2010875,68,44,28,17,'Üç gün sonra Pavlus, Yahudilerin ileri gelenlerini bir araya çağırdı. Bunlar toplandıkları zaman Pavlus kendilerine şöyle dedi: ‹‹Kardeşler, halkımıza ya da atalarımızın törelerine karşı hiçbir şey yapmadığım halde, Yeruşalimde tutuklanıp Romalıların eline teslim edildim.'),
(2010876,68,44,28,18,'Onlar beni sorguya çektikten sonra serbest bırakmak istediler. Çünkü ölüm cezasını gerektiren hiçbir suç işlememiştim.'),
(2010877,68,44,28,19,'Ama Yahudiler buna karşı çıkınca, davamı Sezara iletmek zorunda kaldım. Bunu, kendi ulusumdan herhangi bir şikâyetim olduğu için yapmadım.'),
(2010878,68,44,28,20,'Ben İsrailin umudu uğruna bu zincire vurulmuş bulunuyorum. Sizi buraya, işte bu konuyu görüşmek ve konuşmak için çağırdım.››'),
(2010879,68,44,28,21,'Onlar Pavlusa, ‹‹Yahudiyeden seninle ilgili mektup almadık, oradan gelen kardeşlerden hiçbiri de senin hakkında kötü bir haber getirmedi, kötü bir şey söylemedi›› dediler.'),
(2010880,68,44,28,22,'‹‹Biz senin fikirlerini senden duymak isteriz. Çünkü her yerde bu mezhebe karşı çıkıldığını biliyoruz.››'),
(2010881,68,44,28,23,'Pavlusla bir gün kararlaştırdılar ve o gün, daha büyük bir kalabalıkla onun kaldığı yere geldiler. Pavlus sabahtan akşama dek onlara Tanrının Egemenliğine ilişkin açıklamalarda bulundu ve bu konuda tanıklık etti. Gerek Musanın Yasasına, gerek peygamberlerin yazılarına dayanarak onları İsa hakkında ikna etmeye çalıştı.'),
(2010882,68,44,28,24,'Bazıları onun sözlerine inandı, bazıları ise inanmadı.'),
(2010883,68,44,28,25,'Birbirleriyle anlaşamayınca, Pavlusun şu son sözünden sonra ayrıldılar: ‹‹Peygamber Yeşaya aracılığıyla atalarınıza seslenen Kutsal Ruh doğru söyledi.'),
(2010884,68,44,28,26,'Ruh dedi ki, ‹Bu halka gidip şunu söyle: Duyacak duyacak, ama hiç anlamayacaksınız, Bakacak bakacak, ama hiç görmeyeceksiniz.'),
(2010885,68,44,28,27,'Çünkü bu halkın yüreği duygusuzlaştı, Kulakları ağırlaştı. Gözlerini de kapadılar. Öyle ki, gözleri görmesin, Kulakları duymasın, yürekleri anlamasın, Ve bana dönmesinler. Dönselerdi, onları iyileştirirdim.›'),
(2010886,68,44,28,28,'‹‹Şunu bilin ki, Tanrının sağladığı bu kurtuluşun haberi öteki uluslara gönderilmiştir. Ve onlar buna kulak vereceklerdir.››'),
(2010887,68,44,28,30,'Pavlus tam iki yıl kendi kiraladığı evde kaldı ve ziyaretine gelen herkesi kabul etti.'),
(2010888,68,44,28,31,'Hiçbir engelle karşılaşmadan Tanrı''nın Egemenliği''ni tam bir cesaretle duyuruyor, Rab İsa Mesih''le ilgili gerçekleri öğretiyordu.'),
(2010889,68,45,1,1,'İsa Mesihin kulu, Tanrının Müjdesini yaymak üzere seçilip elçi olmaya çağrılan ben Pavlustan selam!'),
(2010890,68,45,1,2,'Tanrı, Oğlu Rabbimiz İsa Mesihle ilgili bu Müjdeyi peygamberleri aracılığıyla Kutsal Yazılarda önceden vaat etti. Rabbimiz İsa Mesih beden açısından Davutun soyundandır; kutsallık ruhu açısından ise ölümden dirilmekle Tanrının Oğlu olduğu kudretle ilan edildi.'),
(2010891,68,45,1,5,'Her ulustan insanın iman edip söz dinlemesini sağlamak için Mesih aracılığıyla ve Onun adı uğruna Tanrı lütfuna ve elçilik görevine sahip olduk.'),
(2010892,68,45,1,6,'İsa Mesihin çağrılmışları olan sizler de bu uluslardansınız.'),
(2010893,68,45,1,7,'Tanrının Romada bulunan, kutsal olmaya çağrılan bütün sevdiklerine, Babamız Tanrıdan ve Rab İsa Mesihten size lütuf ve esenlik olsun.'),
(2010894,68,45,1,8,'İlkin hepiniz için İsa Mesih aracılığıyla Tanrıma şükrediyorum. Çünkü imanınız bütün dünyada duyuruluyor.'),
(2010895,68,45,1,9,'Oğlunun Müjdesini yaymakta bütün varlığımla kulluk ettiğim Tanrı, sizi durmadan, her zaman dualarımda andığıma tanıktır. Tanrının isteğiyle sonunda bir yol bulup yanınıza gelmek için dua ediyorum.'),
(2010896,68,45,1,11,'Çünkü ruhça pekişmeniz için size ruhsal bir armağan ulaştırmak üzere sizi görmeyi çok istiyorum.'),
(2010897,68,45,1,12,'Yani, ben aranızdayken karşılıklı olarak birbirimizin imanıyla cesaret buluruz demek istiyorum.'),
(2010898,68,45,1,13,'Kardeşler, öteki uluslar arasında olduğu gibi, çalışmalarımın sizin aranızda da ürün vermesi için yanınıza gelmeyi birçok kez amaçladığımı, ama şimdiye dek hep engellendiğimi bilmenizi istiyorum.'),
(2010899,68,45,1,14,'Greklere ve Grek olmayanlara, bilgelere ve bilgisizlere karşı sorumluluğum var.'),
(2010900,68,45,1,15,'Bu nedenle Romada bulunan sizlere de Müjdeyi elimden geldiğince bildirmek için sabırsızlanıyorum.'),
(2010901,68,45,1,16,'Çünkü Müjdeden utanmıyorum. Müjde iman eden herkesin -önce Yahudilerin, sonra Yahudi olmayanların- kurtuluşu için Tanrı gücüdür.'),
(2010902,68,45,1,17,'Tanrının insanı akladığı, Müjdede açıklanır. Aklanma yalnız imanla olur. Yazılmış olduğu gibi, ‹‹İmanla aklanan yaşayacaktır.››'),
(2010903,68,45,1,18,'Haksızlıkla gerçeğe engel olan insanların bütün tanrısızlığına ve haksızlığına karşı Tanrının gazabı gökten açıkça gösterilmektedir.'),
(2010904,68,45,1,19,'Çünkü Tanrıya ilişkin bilinen ne varsa, gözlerinin önündedir; Tanrı hepsini gözlerinin önüne sermiştir.'),
(2010905,68,45,1,20,'Tanrının görünmeyen nitelikleri -sonsuz gücü ve Tanrılığı- dünya yaratılalı beri Onun yaptıklarıyla anlaşılmakta, açıkça görülmektedir. Bu nedenle özürleri yoktur.'),
(2010906,68,45,1,21,'Tanrıyı bildikleri halde Onu Tanrı olarak yüceltmediler, Ona şükretmediler. Tersine, düşüncelerinde budalalığa düştüler; anlayışsız yüreklerini karanlık bürüdü.'),
(2010907,68,45,1,22,'Akıllı olduklarını ileri sürerken akılsız olup çıktılar.'),
(2010908,68,45,1,23,'Ölümsüz Tanrının yüceliği yerine ölümlü insana, kuşlara, dört ayaklılara, sürüngenlere benzeyen putları yeğlediler.'),
(2010909,68,45,1,24,'Bu yüzden Tanrı, birbirlerinin bedenlerini aşağılasınlar diye, onları yüreklerinin tutkuları içinde ahlaksızlığa teslim etti.'),
(2010910,68,45,1,25,'Tanrıyla ilgili gerçeğin yerine yalanı koydular. Yaradanın yerine yaratığa tapıp kulluk ettiler. Oysa Tanrı sonsuza dek övülmeye layıktır! Amin.'),
(2010911,68,45,1,26,'İşte böylece Tanrı onları utanç verici tutkulara teslim etti. Kadınları bile doğal ilişki yerine doğal olmayanı yeğlediler.'),
(2010912,68,45,1,27,'Aynı şekilde erkekler de kadınla doğal ilişkilerini bırakıp birbirleri için şehvetle yanıp tutuştular. Erkekler erkeklerle utanç verici ilişkilere girdiler ve kendi bedenlerinde sapıklıklarına yaraşan karşılığı aldılar.'),
(2010913,68,45,1,28,'Tanrıyı tanımakta yarar görmedikleri için Tanrı onları yararsız düşüncelere, yakışıksız davranışlara teslim etti.'),
(2010914,68,45,1,29,'Her türlü haksızlık, kötülük, açgözlülük ve kinle doldular. Kıskançlık, öldürme hırsı, çekişme, hile, kötü niyetle doludurlar.'),
(2010915,68,45,1,30,'Dedikoducu, yerici, Tanrıdan nefret eden, küstah, kibirli, övüngen, kötülük üreten, anne baba sözü dinlemeyen, anlayışsız, sözünde durmaz, sevgiden yoksun, acımasız insanlardır.'),
(2010916,68,45,1,32,'Böyle davrananların ölümü hak ettiğine ilişkin Tanrı buyruğunu bildikleri halde, bunları yalnız yapmakla kalmaz, yapanları da onaylarlar.'),
(2010917,68,45,2,1,'Bu nedenle sen, ey başkasını yargılayan insan, kim olursan ol, özrün yoktur. Başkasını yargıladığın konuda kendini mahkûm ediyorsun. Çünkü ey yargılayan sen, aynı şeyleri yapıyorsun.'),
(2010918,68,45,2,2,'Böyle davrananları Tanrının haklı olarak yargıladığını biliriz.'),
(2010919,68,45,2,3,'Bu gibi şeyleri yapanları yargılayan, ama aynısını yapan ey insan, Tanrının yargısından kaçabileceğini mi sanıyorsun?'),
(2010920,68,45,2,4,'Tanrının sınırsız iyiliğini, hoşgörüsünü, sabrını hor mu görüyorsun? Onun iyiliğinin seni tövbeye yönelttiğini bilmiyor musun?'),
(2010921,68,45,2,5,'İnatçılığın ve tövbesiz yüreğin yüzünden Tanrının adil yargısının açıklanacağı gazap günü için kendine karşı gazap biriktiriyorsun.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010922,68,45,2,6,'Tanrı ‹‹herkese, yaptıklarının karşılığını verecektir.››'),
(2010923,68,45,2,7,'Sürekli iyilik ederek yücelik, saygınlık, ölümsüzlük arayanlara sonsuz yaşam verecek.'),
(2010924,68,45,2,8,'Bencillerin, gerçeğe uymayıp haksızlık peşinden gidenlerin üzerineyse gazap ve öfke yağdıracak.'),
(2010925,68,45,2,9,'Kötülük eden herkese -önce Yahudiye, sonra Yahudi olmayana- sıkıntı ve elem verecek; iyilik eden herkese -yine önce Yahudiye, sonra Yahudi olmayana- yücelik, saygınlık, esenlik verecektir.'),
(2010926,68,45,2,11,'Çünkü Tanrı insanlar arasında ayrım yapmaz.'),
(2010927,68,45,2,12,'Kutsal Yasayı bilmeden günah işleyenler Yasa olmadan da mahvolacaklar. Yasayı bilerek günah işleyenlerse Yasayla yargılanacaklar.'),
(2010928,68,45,2,13,'Çünkü Tanrı katında aklanacak olanlar Yasayı işitenler değil, yerine getirenlerdir.'),
(2010929,68,45,2,14,'Kutsal Yasadan yoksun uluslar Yasanın gereklerini kendiliklerinden yaptıkça, Yasadan habersiz olsalar bile kendi yasalarını koymuş olurlar.'),
(2010930,68,45,2,15,'Böylelikle Kutsal Yasanın gerektirdiklerinin yüreklerinde yazılı olduğunu gösterirler. Vicdanları buna tanıklık eder. Düşünceleriyse onları ya suçlar ya da savunur.'),
(2010931,68,45,2,16,'Yaydığım Müjdeye göre Tanrının, insanları gizlice yaptıkları şeylerden ötürü İsa Mesih aracılığıyla yargılayacağı gün böyle olacaktır.'),
(2010932,68,45,2,17,'Ya sen? Kendine Yahudi diyor, Kutsal Yasaya dayanıp Tanrıyla övünüyorsun.'),
(2010933,68,45,2,18,'Tanrının isteğini biliyorsun. En üstün değerleri ayırt etmeyi Yasadan öğrenmişsin.'),
(2010934,68,45,2,19,'Kutsal Yasada bilginin ve gerçeğin özüne kavuşmuş olarak körlerin kılavuzu, karanlıkta kalanların ışığı, akılsızların eğiticisi, çocukların öğretmeni olduğuna inanmışsın.'),
(2010935,68,45,2,21,'Öyleyse başkasına öğretirken, kendine de öğretmez misin? Çalmamayı öğütlerken, çalar mısın?'),
(2010936,68,45,2,22,'‹‹Zina etmeyin›› derken, zina eder misin? Putlardan tiksinirken, tapınakları yağmalar mısın?'),
(2010937,68,45,2,23,'Kutsal Yasayla övünürken, Yasaya karşı gelerek Tanrıyı aşağılar mısın?'),
(2010938,68,45,2,24,'Nitekim şöyle yazılmıştır: ‹‹Sizin yüzünüzden uluslar arasında Tanrının adına küfrediliyor.››'),
(2010939,68,45,2,25,'Kutsal Yasayı yerine getirirsen, sünnetin elbet yararı vardır. Ama Yasaya karşı gelirsen, sünnetli olmanın hiçbir anlamı kalmaz.'),
(2010940,68,45,2,26,'Bu nedenle, sünnetsizler Yasanın buyruklarına uyarsa, sünnetli sayılmayacak mı?'),
(2010941,68,45,2,27,'Sen Kutsal Yazılara ve sünnete sahip olduğun halde Yasayı çiğnersen, bedence sünnetli olmayan ama Yasaya uyan kişi seni yargılamayacak mı?'),
(2010942,68,45,2,28,'Çünkü ne dıştan Yahudi olan gerçek Yahudidir, ne de görünüşte, bedensel olan sünnet gerçek sünnettir.'),
(2010943,68,45,2,29,'Ancak içten Yahudi olan Yahudi''dir. Sünnet de yürekle ilgilidir; yazılı yasanın değil, Ruh''un işidir. İçten Yahudi olan kişi, insanların değil, Tanrı''nın övgüsünü kazanır.'),
(2010944,68,45,3,1,'Öyleyse Yahudinin ne üstünlüğü var? Sünnetin yararı nedir?'),
(2010945,68,45,3,2,'Her yönden çoktur. İlk olarak, Tanrının sözleri Yahudilere emanet edilmiştir.'),
(2010946,68,45,3,3,'Peki, kimi Yahudiler güvenilmez çıkmışsa ne olur? Onların güvenilmezliği Tanrının güvenilirliğini ortadan kaldırır mı?'),
(2010947,68,45,3,4,'Kesinlikle hayır! Herkes yalancı olsa bile, Tanrının doğruyu söylediği bilinmelidir. Yazılmış olduğu gibi: ‹‹Öyle ki, sözlerinde doğru çıkasın Ve yargılandığında davayı kazanasın.››'),
(2010948,68,45,3,5,'Ama bizim haksızlığımız Tanrının adil olduğunu ortaya çıkarıyorsa, ne diyelim? İnsanların diliyle konuşuyorum: Gazapla cezalandıran Tanrı haksız mı?'),
(2010949,68,45,3,6,'Kesinlikle hayır! Öyle olsa Tanrı dünyayı nasıl yargılayacak?'),
(2010950,68,45,3,7,'Ama Tanrının her zaman doğruyu söylediği benim yalanımla yüceliği için daha açık şekilde ortaya çıkmışsa, ben niçin yine bir günahkâr olarak yargılanıyorum?'),
(2010951,68,45,3,8,'Bazılarının bizi kötüleyerek, söylediğimizi ileri sürdüğü gibi niçin, ‹‹Kötülük yapalım da bundan iyilik çıksın›› demeyelim? Böylelerinin yargılanması yerindedir.'),
(2010952,68,45,3,9,'Şimdi ne diyelim? Biz Yahudiler öteki uluslardan üstün müyüz? Elbette değiliz. İster Yahudi ister Grek olsun, daha önce herkesi günahın denetiminde olmakla suçladık.'),
(2010953,68,45,3,10,'Yazılmış olduğu gibi: ‹‹Doğru kimse yok, tek kişi bile yok.'),
(2010954,68,45,3,11,'Anlayan kimse yok, Tanrıyı arayan yok.'),
(2010955,68,45,3,12,'Hepsi saptı, Tümü yararsız oldu. İyilik eden yok, tek kişi bile!››'),
(2010956,68,45,3,13,'‹‹Ağızları açık birer mezardır. Dilleriyle aldatırlar.›› ‹‹Engerek zehiri var dudaklarının altında.››'),
(2010957,68,45,3,14,'‹‹Ağızları lanet ve acı sözle doludur.››'),
(2010958,68,45,3,15,'‹‹Ayakları kan dökmeye seğirtir.'),
(2010959,68,45,3,16,'Yıkım ve dert var yollarında.'),
(2010960,68,45,3,17,'Esenlik yolunu da bilmezler.››'),
(2010961,68,45,3,18,'‹‹Tanrı korkusu yoktur onlarda.››'),
(2010962,68,45,3,19,'Kutsal Yasada söylenenlerin her ağız kapansın, bütün dünya Tanrıya hesap versin diye Yasanın yönetimi altındakilere söylendiğini biliyoruz.'),
(2010963,68,45,3,20,'Bu nedenle Yasanın gereklerini yapmakla hiç kimse Tanrı katında aklanmayacaktır. Çünkü Yasa sayesinde günahın bilincine varılır.'),
(2010964,68,45,3,21,'Ama şimdi Yasadan bağımsız olarak Tanrının insanı nasıl aklayacağı açıklandı. Yasa ve peygamberler buna tanıklık ediyor.'),
(2010965,68,45,3,22,'Tanrı insanları İsa Mesihe olan imanlarıyla aklar. Bunu, iman eden herkes için yapar. Hiç ayrım yoktur.'),
(2010966,68,45,3,23,'Çünkü herkes günah işledi ve Tanrının yüceliğinden yoksun kaldı.'),
(2010967,68,45,3,24,'İnsanlar İsa Mesihte olan kurtuluşla, Tanrının lütfuyla, karşılıksız olarak aklanırlar.'),
(2010968,68,45,3,25,'Tanrı Mesihi, kanıyla günahları bağışlatan ve imanla benimsenen kurban olarak sundu. Böylece adaletini gösterdi. Çünkü sabredip daha önce işlenmiş günahları cezasız bıraktı. Bunu, adil kalmak ve İsaya iman edeni aklamak için şimdiki zamanda kendi adaletini göstermek amacıyla yaptı.'),
(2010969,68,45,3,27,'Öyleyse neyle övünebiliriz? Hiçbir şeyle! Hangi ilkeye dayanarak? Yasayı yerine getirme ilkesine mi? Hayır, iman ilkesine.'),
(2010970,68,45,3,28,'Çünkü insanın, Yasanın gereklerini yaparak değil, iman ederek aklandığı kanısındayız.'),
(2010971,68,45,3,29,'Yoksa Tanrı yalnız Yahudilerin Tanrısı mı? Öteki ulusların da Tanrısı değil mi? Elbet öteki ulusların da Tanrısıdır.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2010972,68,45,3,30,'Çünkü sünnetlileri imanları sayesinde, sünnetsizleri de aynı imanla aklayacak olan Tanrı tektir.'),
(2010973,68,45,3,31,'Öyleyse biz iman aracılığıyla Kutsal Yasa''yı geçersiz mi kılıyoruz? Hayır, tam tersine, Yasa''yı doğruluyoruz.'),
(2010974,68,45,4,1,'Şu halde soyumuzun atası İbrahimin durumu için ne diyelim?'),
(2010975,68,45,4,2,'Eğer İbrahim yaptığı iyi işlerden dolayı aklandıysa, övünmeye hakkı vardır; ama Tanrının önünde değil.'),
(2010976,68,45,4,3,'Kutsal Yazı ne diyor? ‹‹İbrahim Tanrıya iman etti, böylece aklanmış sayıldı.››'),
(2010977,68,45,4,4,'Çalışana verilen ücret lütuf değil, hak sayılır.'),
(2010978,68,45,4,5,'Ancak çalışmayan, ama tanrısızı aklayana iman eden kişi imanı sayesinde aklanmış sayılır.'),
(2010979,68,45,4,6,'Nitekim, iyi işlerine bakmaksızın Tanrının aklanmış saydığı kişinin mutluluğunu Davut da şöyle anlatır:'),
(2010980,68,45,4,7,'‹‹Ne mutlu suçları bağışlanmış, Günahları örtülmüş olanlara!'),
(2010981,68,45,4,8,'Günahı Rab tarafından sayılmayana ne mutlu!››'),
(2010982,68,45,4,9,'Bu mutluluk yalnız sünnetliler için mi, yoksa aynı zamanda sünnetsizler için midir? Diyoruz ki, ‹‹İbrahim, imanı sayesinde aklanmış sayıldı.››'),
(2010983,68,45,4,10,'Hangi durumda aklanmış sayıldı? Sünnet olduktan sonra mı, sünnetsizken mi? Sünnetliyken değil, sünnetsizken...'),
(2010984,68,45,4,11,'İbrahim daha sünnetsizken imanla aklandığının kanıtı olarak sünnet işaretini aldı. Öyle ki, sünnetsiz oldukları halde iman edenlerin hepsinin babası olsun, böylece onlar da aklanmış sayılsın.'),
(2010985,68,45,4,12,'Böylelikle atamız İbrahim, yalnız sünnetli olmakla kalmayan, ama kendisi sünnetsizken sahip olduğu imanın izinden yürüyen sünnetlilerin de babası oldu.'),
(2010986,68,45,4,13,'Çünkü İbrahime ve soyuna dünyanın mirasçısı olma vaadi Kutsal Yasa yoluyla değil, imandan gelen aklanma yoluyla verildi.'),
(2010987,68,45,4,14,'Eğer Yasaya bağlı olanlar mirasçı olursa, iman boş ve vaat geçersizdir.'),
(2010988,68,45,4,15,'Yasa, Tanrının gazabına yol açar. Ama yasanın olmadığı yerde yasaya karşı gelmek de söz konusu değildir.'),
(2010989,68,45,4,16,'Bu nedenle vaat, Tanrının lütfuna dayanmak ve İbrahimin bütün soyu için güvence altına alınmak üzere imana bağlı kılınmıştır. İbrahimin soyu yalnız Kutsal Yasaya bağlı olanlar değil, aynı zamanda İbrahimin imanına sahip olanlardır. ‹‹Seni birçok ulusun babası yaptım›› diye yazılmış olduğu gibi İbrahim, iman ettiği Tanrının -ölülere yaşam veren, var olmayanı buyruğuyla var eden Tanrının- gözünde hepimizin babasıdır.'),
(2010990,68,45,4,18,'İbrahim umutsuz bir durumdayken birçok ulusun babası olacağına umutla iman etti. ‹‹Senin soyun böyle olacak›› sözüne güveniyordu.'),
(2010991,68,45,4,19,'Yüz yaşına yaklaşmışken, ölü denebilecek bedenini ve Saranın ölü rahmini düşündüğünde imanı zayıflamadı.'),
(2010992,68,45,4,20,'İmansızlık edip Tanrının vaadinden kuşkulanmadı; tersine, imanı güçlendi ve Tanrıyı yüceltti.'),
(2010993,68,45,4,21,'Tanrının vaadini yerine getirecek güçte olduğuna tümüyle güvendi.'),
(2010994,68,45,4,22,'Bunun için de aklanmış sayıldı.'),
(2010995,68,45,4,23,'‹‹Aklanmış sayıldı›› sözü, yalnız onun için değil, aklanmış sayılacak olan bizler -Rabbimiz İsayı ölümden dirilten Tanrıya iman eden bizler- için de yazıldı.'),
(2010996,68,45,4,25,'İsa suçlarımız için ölüme teslim edildi ve aklanmamız için diriltildi.'),
(2010997,68,45,5,1,'Böylece imanla aklandığımıza göre, Rabbimiz İsa Mesih sayesinde Tanrıyla barışmış oluyoruz.'),
(2010998,68,45,5,2,'İçinde bulunduğumuz bu lütfa Mesih aracılığıyla, imanla kavuştuk ve Tanrının yüceliğine erişmek umuduyla övünüyoruz.'),
(2010999,68,45,5,3,'Yalnız bununla değil, sıkıntılarla da övünüyoruz. Çünkü biliyoruz ki, sıkıntı dayanma gücünü, dayanma gücü Tanrının beğenisini, Tanrının beğenisi de umudu yaratır.'),
(2011000,68,45,5,5,'Umut düş kırıklığına uğratmaz. Çünkü bize verilen Kutsal Ruh aracılığıyla Tanrının sevgisi yüreklerimize dökülmüştür.'),
(2011001,68,45,5,6,'Evet, biz daha çaresizken Mesih belirlenen zamanda tanrısızlar için öldü.'),
(2011002,68,45,5,7,'Bir kimse doğru insan için güç ölür, ama iyi insan için belki biri ölmeyi göze alabilir.'),
(2011003,68,45,5,8,'Tanrı ise bizi sevdiğini şununla kanıtlıyor: Biz daha günahkârken, Mesih bizim için öldü.'),
(2011004,68,45,5,9,'Böylece şimdi Onun kanıyla aklandığımıza göre, Onun aracılığıyla Tanrının gazabından kurtulacağımız çok daha kesindir.'),
(2011005,68,45,5,10,'Çünkü biz Tanrının düşmanlarıyken Oğlunun ölümü sayesinde Onunla barıştıksa, barışmış olarak Oğlunun yaşamıyla kurtulacağımız çok daha kesindir.'),
(2011006,68,45,5,11,'Yalnız bu kadar da değil, bizi şimdi Tanrıyla barıştırmış olan Rabbimiz İsa Mesih aracılığıyla, Tanrının kendisiyle de övünüyoruz.'),
(2011007,68,45,5,12,'Günah bir insan aracılığıyla, ölüm de günah aracılığıyla dünyaya girdi. Böylece ölüm bütün insanlara yayıldı. Çünkü hepsi günah işledi.'),
(2011008,68,45,5,13,'Kutsal Yasadan önce de dünyada günah vardı; ama yasa olmayınca günahın hesabı tutulmaz.'),
(2011009,68,45,5,14,'Oysa ölüm Ademden Musaya dek, gelecek Kişinin örneği olan Ademin suçuna benzer bir günah işlememiş olanlar üzerinde de egemendi.'),
(2011010,68,45,5,15,'Ne var ki, Tanrının armağanı Ademin suçu gibi değildir. Çünkü bir kişinin suçu yüzünden birçokları öldüyse, Tanrının lütfu ve bir tek adamın, yani İsa Mesihin lütfuyla verilen bağış birçokları yararına daha da çoğaldı.'),
(2011011,68,45,5,16,'Tanrının bağışı o tek adamın günahının sonucu gibi değildir. Tek suçtan sonra verilen yargı mahkûmiyet getirdi; oysa birçok suçtan sonra verilen armağan aklanmayı sağladı.'),
(2011012,68,45,5,17,'Çünkü ölüm bir tek adamın suçu yüzünden o tek adam aracılığıyla egemenlik sürdüyse, Tanrının bol lütfunu ve aklanma bağışını alanların bir tek adam, yani İsa Mesih sayesinde yaşamda egemenlik sürecekleri çok daha kesindir.'),
(2011013,68,45,5,18,'İşte, tek bir suçun bütün insanların mahkûmiyetine yol açtığı gibi, bir doğruluk eylemi de bütün insanlara yaşam veren aklanmayı sağladı.'),
(2011014,68,45,5,19,'Çünkü bir adamın sözdinlemezliği yüzünden nasıl birçoğu günahkâr kılındıysa, bir adamın söz dinlemesiyle birçoğu da doğru kılınacaktır.'),
(2011015,68,45,5,20,'Kutsal Yasa suç çoğalsın diye araya girdi; ama günahın çoğaldığı yerde Tanrının lütfu daha da çoğaldı.'),
(2011016,68,45,5,21,'Öyle ki, günah nasıl ölüm yoluyla egemenlik sürdüyse, Tanrı''nın lütfu da Rabbimiz İsa Mesih aracılığıyla sonsuz yaşam vermek üzere doğrulukla egemenlik sürsün.'),
(2011017,68,45,6,1,'Öyleyse ne diyelim? Lütuf çoğalsın diye günah işlemeye devam mı edelim?'),
(2011018,68,45,6,2,'Kesinlikle hayır! Günah karşısında ölmüş olan bizler artık nasıl günah içinde yaşarız?'),
(2011019,68,45,6,3,'Mesih İsaya vaftiz edildiğimizde, hepimizin Onun ölümüne vaftiz edildiğimizi bilmez misiniz?'),
(2011020,68,45,6,4,'Babanın yüceliği sayesinde Mesih nasıl ölümden dirildiyse, biz de yeni bir yaşam sürmek üzere vaftiz yoluyla Onunla birlikte ölüme gömüldük.'),
(2011021,68,45,6,5,'Eğer Onunkine benzer bir ölümde Onunla birleştiysek, Onunkine benzer bir dirilişte de Onunla birleşeceğiz.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011022,68,45,6,6,'Artık günaha kölelik etmeyelim diye, günahlı varlığımızın ortadan kaldırılması için eski yaradılışımızın Mesihle birlikte çarmıha gerildiğini biliriz.'),
(2011023,68,45,6,7,'Çünkü ölmüş kişi günahtan özgür kılınmıştır.'),
(2011024,68,45,6,8,'Mesihle birlikte ölmüşsek, Onunla birlikte yaşayacağımıza da inanıyoruz.'),
(2011025,68,45,6,9,'Çünkü Mesihin ölümden dirilmiş olduğunu ve bir daha ölmeyeceğini, ölümün artık Onun üzerinde egemenlik sürmeyeceğini biliyoruz.'),
(2011026,68,45,6,10,'Onun ölümü günaha karşılık ilk ve son ölüm olmuştur. Sürmekte olduğu yaşamı ise Tanrı için sürmektedir.'),
(2011027,68,45,6,11,'Siz de böylece kendinizi günah karşısında ölü, Mesih İsada Tanrı karşısında diri sayın.'),
(2011028,68,45,6,12,'Bu nedenle bedenin tutkularına uymamak için günahın ölümlü bedenlerinizde egemenlik sürmesine izin vermeyin.'),
(2011029,68,45,6,13,'Bedeninizin üyelerini haksızlığa araç ederek günaha sunmayın. Ölümden dirilenler gibi kendinizi Tanrıya adayın; bedeninizin üyelerini doğruluk araçları olarak Tanrıya sunun.'),
(2011030,68,45,6,14,'Günah size egemen olmayacaktır. Çünkü Kutsal Yasanın yönetimi altında değil, Tanrının lütfu altındasınız.'),
(2011031,68,45,6,15,'Öyleyse ne diyelim? Yasanın yönetimi altında değil de, Tanrının lütfu altında olduğumuz için günah mı işleyelim? Kesinlikle hayır!'),
(2011032,68,45,6,16,'Söz dinleyen köleler gibi kendinizi kime teslim ederseniz, sözünü dinlediğiniz kişinin köleleri olduğunuzu bilmez misiniz? Ya ölüme götüren günahın ya da doğruluğa götüren sözdinlerliğin kölelerisiniz.'),
(2011033,68,45,6,17,'Ama şükürler olsun Tanrıya! Eskiden günahın köleleri olan sizler, adandığınız öğretinin özüne yürekten bağlandınız.'),
(2011034,68,45,6,18,'Günahtan özgür kılınarak doğruluğun köleleri oldunuz.'),
(2011035,68,45,6,19,'Doğanızın güçsüzlüğü yüzünden insan ölçülerine göre konuşuyorum. Bedeninizin üyelerini ahlaksızlığa ve kötülük yapmak üzere kötülüğe nasıl köle olarak sundunuzsa, şimdi de bu üyelerinizi kutsal olmak üzere doğruluğa köle olarak sunun.'),
(2011036,68,45,6,20,'Sizler günahın kölesiyken doğruluktan özgürdünüz.'),
(2011037,68,45,6,21,'Şimdi utandığınız şeylerden o zaman ne kazancınız oldu? Onların sonucu ölümdür.'),
(2011038,68,45,6,22,'Ama şimdi günahtan özgür kılınıp Tanrının kulları olduğunuza göre, kazancınız kutsallaşma ve bunun sonucu olan sonsuz yaşamdır.'),
(2011039,68,45,6,23,'Çünkü günahın ücreti ölüm, Tanrı''nın armağanı ise Rabbimiz Mesih İsa''da sonsuz yaşamdır.'),
(2011040,68,45,7,1,'Bilmez misiniz ki, ey kardeşler -Kutsal Yasayı bilenlere söylüyorum- Yasa insana ancak yaşadığı sürece egemendir?'),
(2011041,68,45,7,2,'Örneğin, evli kadın, kocası yaşadıkça yasayla ona bağlıdır; kocası ölürse, onu kocasına bağlayan yasadan özgür olur.'),
(2011042,68,45,7,3,'Buna göre kadın, kocası yaşarken başka bir erkekle ilişki kurarsa, zina etmiş sayılır. Ama kocası ölürse, kadın yasadan özgür olur. Şöyle ki, başka bir erkeğe varırsa, zina etmiş olmaz.'),
(2011043,68,45,7,4,'Aynı şekilde kardeşlerim, siz de bir başkasına -ölümden dirilmiş olan Mesihe- varmak üzere Mesihin bedeni aracılığıyla Kutsal Yasa karşısında öldünüz. Bu da Tanrının hizmetinde verimli olmamız içindir.'),
(2011044,68,45,7,5,'Çünkü biz benliğin denetimindeyken, Yasanın kışkırttığı günah tutkuları bedenimizin üyelerinde etkindi. Bunun sonucu olarak ölüme götüren meyveler verdik.'),
(2011045,68,45,7,6,'Şimdiyse biz, daha önce tutsağı olduğumuz Yasa karşısında öldüğümüz için Yasadan özgür kılındık. Öyle ki, yazılı yasanın eski yolunda değil, Ruhun yeni yolunda kulluk edelim.'),
(2011046,68,45,7,7,'Öyleyse ne diyelim? Kutsal Yasa günah mı oldu? Kesinlikle hayır! Ama Yasa olmasaydı, günahın ne olduğunu bilemezdim. Yasa, ‹‹Göz dikmeyeceksin›› demeseydi, başkasının malına göz dikmenin ne olduğunu bilemezdim.'),
(2011047,68,45,7,8,'Ne var ki günah, bu buyruğun verdiği fırsatla içimde her türlü açgözlülüğü üretti. Çünkü Kutsal Yasa olmadıkça günah ölüdür.'),
(2011048,68,45,7,9,'Bir zamanlar, Yasanın bilincinde değilken diriydim. Ama buyruğun bilincine vardığımda günah dirildi, bense öldüm. Buyruk da bana yaşam getireceğine, ölüm getirdi.'),
(2011049,68,45,7,11,'Çünkü günah buyruğun verdiği fırsatla beni aldattı, buyruk aracılığıyla beni öldürdü.'),
(2011050,68,45,7,12,'İşte böyle, Yasa gerçekten kutsaldır. Buyruk da kutsal, doğru ve iyidir.'),
(2011051,68,45,7,13,'Öyleyse, iyi olan bana ölüm mü getirdi? Kesinlikle hayır! Ama günah, günah olarak tanınsın diye, iyi olanın aracılığıyla bana ölüm getiriyordu. Öyle ki, buyruk aracılığıyla günahın ne denli günahlı olduğu anlaşılsın.'),
(2011052,68,45,7,14,'Yasanın ruhsal olduğunu biliriz. Bense benliğin denetimindeyim, köle gibi günaha satılmışım.'),
(2011053,68,45,7,15,'Ne yaptığımı anlamıyorum. Çünkü istediğimi yapmıyorum; nefret ettiğim ne ise, onu yapıyorum.'),
(2011054,68,45,7,16,'Ama istemediğimi yaparsam, Yasanın iyi olduğunu kabul etmiş olurum.'),
(2011055,68,45,7,17,'Öyleyse bunu artık ben değil, içimde yaşayan günah yapıyor.'),
(2011056,68,45,7,18,'İçimde, yani benliğimde iyi bir şey bulunmadığını biliyorum. İçimde iyiyi yapmaya istek var, ama güç yok.'),
(2011057,68,45,7,19,'İstediğim iyi şeyi yapmıyorum, istemediğim kötü şeyi yapıyorum.'),
(2011058,68,45,7,20,'İstemediğimi yapıyorsam, bunu yapan artık ben değil, içimde yaşayan günahtır.'),
(2011059,68,45,7,21,'Bundan şu kuralı çıkarıyorum: Ben iyi olanı yapmak isterken, karşımda hep kötülük vardır.'),
(2011060,68,45,7,22,'İç varlığımda Tanrının Yasasından zevk alıyorum.'),
(2011061,68,45,7,23,'Ama bedenimin üyelerinde bambaşka bir yasa görüyorum. Bu da aklımın onayladığı yasaya karşı savaşıyor ve beni bedenimin üyelerindeki günah yasasına tutsak ediyor.'),
(2011062,68,45,7,24,'Ne zavallı insanım! Ölüme götüren bu bedenden beni kim kurtaracak?'),
(2011063,68,45,7,25,'Rabbimiz İsa Mesih aracılığıyla Tanrı''ya şükürler olsun! Sonuç olarak ben aklımla Tanrı''nın Yasası''na, ama benliğimle günahın yasasına kulluk ediyorum.'),
(2011064,68,45,8,1,'Böylece Mesih İsaya ait olanlara artık hiçbir mahkûmiyet yoktur.'),
(2011065,68,45,8,2,'Çünkü yaşam veren Ruhun yasası, Mesih İsa sayesinde beni günahın ve ölümün yasasından özgür kıldı.'),
(2011066,68,45,8,3,'İnsan benliğinden ötürü güçsüz olan Kutsal Yasanın yapamadığını Tanrı yaptı. Öz Oğlunu günahlı insan benzerliğinde günah sunusu olarak gönderip günahı insan benliğinde yargıladı.'),
(2011067,68,45,8,4,'Öyle ki, Yasanın gereği, benliğe göre değil, Ruha göre yaşayan bizlerde yerine gelsin.'),
(2011068,68,45,8,5,'Benliğe uyanlar benlikle ilgili, Ruha uyanlarsa Ruhla ilgili işleri düşünürler.'),
(2011069,68,45,8,6,'Benliğe dayanan düşünce ölüm, Ruha dayanan düşünceyse yaşam ve esenliktir.'),
(2011070,68,45,8,7,'Çünkü benliğe dayanan düşünce Tanrıya düşmandır; Tanrının Yasasına boyun eğmez, eğemez de...'),
(2011071,68,45,8,8,'Benliğin denetiminde olanlar Tanrıyı hoşnut edemezler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011072,68,45,8,9,'Ne var ki, Tanrının Ruhu içinizde yaşıyorsa, benliğin değil, Ruhun denetimindesiniz. Ama içinde Mesihin Ruhu olmayan kişi Mesihin değildir.'),
(2011073,68,45,8,10,'Eğer Mesih içinizdeyse, bedeniniz günah yüzünden ölü olmakla birlikte, aklanmış olduğunuz için ruhunuz diridir.'),
(2011074,68,45,8,11,'Mesih İsayı ölümden dirilten Tanrının Ruhu içinizde yaşıyorsa, Mesihi ölümden dirilten Tanrı, içinizde yaşayan Ruhuyla ölümlü bedenlerinize de yaşam verecektir.'),
(2011075,68,45,8,12,'Öyleyse kardeşlerim, borçluyuz ama, benliğe göre yaşamak için benliğe borçlu değiliz.'),
(2011076,68,45,8,13,'Çünkü benliğe göre yaşarsanız öleceksiniz; ama bedenin kötü işlerini Ruhla öldürürseniz yaşayacaksınız.'),
(2011077,68,45,8,14,'Tanrının Ruhuyla yönetilenlerin hepsi Tanrının oğullarıdır.'),
(2011078,68,45,8,15,'Çünkü sizi yeniden korkuya sürükleyecek kölelik ruhunu almadınız, oğulluk ruhunu aldınız. Bu ruhla, ‹‹Abba, Baba!›› diye sesleniriz.'),
(2011079,68,45,8,16,'Ruhun kendisi, bizim ruhumuzla birlikte, Tanrının çocukları olduğumuza tanıklık eder.'),
(2011080,68,45,8,17,'Eğer Tanrının çocuklarıysak, aynı zamanda mirasçıyız. Mesihle birlikte yüceltilmek üzere Mesihle birlikte acı çekiyorsak, Tanrının mirasçılarıyız, Mesihle ortak mirasçılarız.'),
(2011081,68,45,8,18,'Kanım şu ki, bu anın acıları, gözümüzün önüne serilecek yücelikle karşılaştırılmaya değmez.'),
(2011082,68,45,8,19,'Yaratılış, Tanrı çocuklarının ortaya çıkmasını büyük özlemle bekliyor.'),
(2011083,68,45,8,20,'Çünkü yaratılış amaçsızlığa teslim edildi. Bu da yaratılışın isteğiyle değil, onu amaçsızlığa teslim eden Tanrının isteğiyle oldu. Çünkü yaratılışın, yozlaşmaya köle olmaktan kurtarılıp Tanrı çocuklarının yüce özgürlüğüne kavuşturulması umudu vardı.'),
(2011084,68,45,8,22,'Bütün yaratılışın şu ana dek birlikte inleyip doğum ağrısı çektiğini biliyoruz.'),
(2011085,68,45,8,23,'Yalnız yaratılış değil, biz de -evet Ruhun turfandasına sahip olan bizler de- evlatlığa alınmayı, yani bedenlerimizin kurtulmasını özlemle bekleyerek içimizden inliyoruz.'),
(2011086,68,45,8,24,'Çünkü bu umutla kurtulduk. Ama görülen umut, umut değildir. Gördüğü şeyi kim umut eder?'),
(2011087,68,45,8,25,'Oysa görmediğimize umut bağlarsak, sabırla bekleyebiliriz.'),
(2011088,68,45,8,26,'Bunun gibi, Ruh da güçsüzlüğümüzde bize yardım eder. Ne için dua etmemiz gerektiğini bilmeyiz, ama Ruhun kendisi, sözle anlatılamaz iniltilerle bizim için aracılık eder.'),
(2011089,68,45,8,27,'Yürekleri araştıran Tanrı, Ruhun düşüncesinin ne olduğunu bilir. Çünkü Ruh, Tanrının isteği uyarınca kutsallar için aracılık eder.'),
(2011090,68,45,8,28,'Tanrının, kendisini sevenlerle, amacı uyarınca çağrılmış olanlarla birlikte her durumda iyilik için etkin olduğunu biliriz.'),
(2011091,68,45,8,29,'Çünkü Tanrı önceden bildiği kişileri Oğlunun benzerliğine dönüştürmek üzere önceden belirledi. Öyle ki, Oğul birçok kardeş arasında ilk doğan olsun.'),
(2011092,68,45,8,30,'Tanrı önceden belirlediği kişileri çağırdı, çağırdıklarını akladı ve akladıklarını yüceltti.'),
(2011093,68,45,8,31,'Öyleyse buna ne diyelim? Tanrı bizden yanaysa, kim bize karşı olabilir?'),
(2011094,68,45,8,32,'Öz Oğlunu bile esirgemeyip Onu hepimiz için ölüme teslim eden Tanrı, Onunla birlikte bize her şeyi bağışlamayacak mı?'),
(2011095,68,45,8,33,'Tanrının seçtiklerini kim suçlayacak? Onları aklayan Tanrıdır.'),
(2011096,68,45,8,34,'Kim suçlu çıkaracak? Ölmüş, üstelik dirilmiş olan Mesih İsa, Tanrının sağındadır ve bizim için aracılık etmektedir.'),
(2011097,68,45,8,35,'Mesihin sevgisinden bizi kim ayırabilir? Sıkıntı mı, elem mi, zulüm mü, açlık mı, çıplaklık mı, tehlike mi, kılıç mı?'),
(2011098,68,45,8,36,'Yazılmış olduğu gibi: ‹‹Senin uğruna bütün gün öldürülüyoruz, Kasaplık koyun sayılıyoruz.››'),
(2011099,68,45,8,37,'Ama bizi sevenin aracılığıyla bu durumların hepsinde galiplerden üstünüz.'),
(2011100,68,45,8,38,'Eminim ki, ne ölüm, ne yaşam, ne melekler, ne yönetimler, ne şimdiki ne gelecek zaman, ne güçler, ne yükseklik, ne derinlik, ne de yaratılmış başka bir şey bizi Rabbimiz Mesih İsa''da olan Tanrı sevgisinden ayırmaya yetecektir.'),
(2011101,68,45,9,1,'Mesihe ait biri olarak gerçeği söylüyorum, yalan söylemiyorum. Vicdanım da söylediklerimi Kutsal Ruh aracılığıyla doğruluyor.'),
(2011102,68,45,9,2,'Yüreğimde büyük bir keder, dinmeyen bir acı var.'),
(2011103,68,45,9,3,'Kardeşlerimin, soydaşlarım olan İsraillilerin yerine ben kendim lanetlenip Mesihten uzaklaştırılmayı dilerdim. Evlatlığa kabul edilenler, Tanrının yüceliğini görenler onlardır. Antlaşmalar, buyrulan Kutsal Yasa, tapınma düzeni, vaatler onlarındır.'),
(2011104,68,45,9,5,'Büyük atalar onların atalarıdır. Mesih de bedence onlardandır. O her şeyin üzerinde hüküm süren, sonsuza dek övülecek Tanrıdır! Amin.'),
(2011105,68,45,9,6,'Tanrının sözü boşa çıktı demek istemiyorum. Çünkü İsrail soyundan gelenlerin hepsi İsrailli sayılmaz.'),
(2011106,68,45,9,7,'İbrahimin soyundan olsalar bile, hepsi onun çocukları değildir. Ama, ‹‹Senin soyun İshakla sürecek›› diye yazılmıştır.'),
(2011107,68,45,9,8,'Demek ki Tanrının çocukları olağan yoldan doğan çocuklar değildir; İbrahimin soyu sayılanlar Tanrının vaadi uyarınca doğan çocuklardır.'),
(2011108,68,45,9,9,'Çünkü vaat şöyleydi: ‹‹Gelecek yıl bu zamanda geleceğim ve Saranın bir oğlu olacak.››'),
(2011109,68,45,9,10,'Ayrıca Rebeka bir erkekten, atamız İshaktan ikizlere gebe kalmıştı.'),
(2011110,68,45,9,11,'Çocuklar henüz doğmamış, iyi ya da kötü bir şey yapmamışken, Tanrı Rebekaya, ‹‹Büyüğü küçüğüne kulluk edecek›› dedi. Öyle ki, Tanrının seçim yapmaktaki amacı yapılan işlere değil, kendi çağrısına dayanarak sürsün.'),
(2011111,68,45,9,13,'Yazılmış olduğu gibi, ‹‹Yakupu sevdim, Esavdan ise nefret ettim.››'),
(2011112,68,45,9,14,'Öyleyse ne diyelim? Tanrı adaletsizlik mi ediyor? Kesinlikle hayır!'),
(2011113,68,45,9,15,'Çünkü Musaya şöyle diyor: ‹‹Merhamet ettiğime merhamet edeceğim, Acıdığıma acıyacağım.››'),
(2011114,68,45,9,16,'Demek ki bu, insanın isteğine ya da çabasına değil, Tanrının merhametine bağlıdır.'),
(2011115,68,45,9,17,'Tanrı Kutsal Yazıda firavuna şöyle diyor: ‹‹Gücümü senin aracılığınla göstermek Ve adımı bütün dünyada duyurmak için Seni yükselttim.››'),
(2011116,68,45,9,18,'Demek ki Tanrı dilediğine merhamet eder, dilediğinin yüreğini nasırlaştırır.'),
(2011117,68,45,9,19,'Şimdi bana, ‹‹Öyleyse Tanrı insanı neden hâlâ suçlu buluyor? Onun isteğine kim karşı durabilir?›› diyeceksin.'),
(2011118,68,45,9,20,'Ama, ey insan, sen kimsin ki Tanrıya karşılık veriyorsun? ‹‹Kendisine biçim verilen, biçim verene, ‹Beni niçin böyle yaptın› der mi?››'),
(2011119,68,45,9,21,'Ya da çömlekçinin aynı kil yığınından bir kabı onurlu iş için, ötekini bayağı iş için yapmaya hakkı yok mu?'),
(2011120,68,45,9,22,'Eğer Tanrı gazabını göstermek ve gücünü tanıtmak isterken, gazabına hedef olup mahvolmaya hazırlananlara büyük sabırla katlandıysa, ne diyelim?'),
(2011121,68,45,9,23,'Yüceltmek üzere önceden hazırlayıp merhamet ettiklerine yüceliğinin zenginliğini göstermek için bunu yaptıysa, ne diyelim?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011122,68,45,9,24,'Yalnız Yahudiler arasından değil, öteki uluslar arasından da çağırdığı bu insanlar biziz.'),
(2011123,68,45,9,25,'Tanrı Hoşea Kitabında şöyle diyor: ‹‹Halkım olmayana halkım, Sevgili olmayana sevgili diyeceğim.››'),
(2011124,68,45,9,26,'‹‹Kendilerine, ‹Siz halkım değilsiniz› denilen yerde, Yaşayan Tanrının çocukları diye adlandırılacaklar.››'),
(2011125,68,45,9,27,'Yeşaya, İsrail için şöyle sesleniyor: ‹‹İsrailoğullarının sayısı Denizin kumu kadar çok olsa da, Ancak pek azı kurtulacak.'),
(2011126,68,45,9,28,'Çünkü Rab yeryüzündeki yargılama işini Tez yapıp bitirecek.››'),
(2011127,68,45,9,29,'Yeşayanın önceden dediği gibi: ‹‹Her Şeye Egemen Rab Soyumuzu sürdürecek birkaç kişiyi Sağ bırakmamış olsaydı, Sodom gibi olur, Gomoraya benzerdik.››'),
(2011128,68,45,9,30,'Öyleyse ne diyelim? Aklanma peşinde olmayan uluslar aklanmaya, imandan gelen aklanmaya kavuştular.'),
(2011129,68,45,9,31,'Aklanmak için Yasanın ardından giden İsrail ise Yasayı yerine getiremedi.'),
(2011130,68,45,9,32,'Neden? Çünkü imanla değil, iyi işlerle olurmuş gibi aklanmaya çalıştılar ve ‹‹sürçme taşı››nda sürçtüler.'),
(2011131,68,45,9,33,'Yazılmış olduğu gibi: ‹‹İşte, Siyon''a bir sürçme taşı, Bir tökezleme kayası koyuyorum. O''na iman eden utandırılmayacak.››'),
(2011132,68,45,10,1,'Kardeşler! İsraillilerin kurtulmasını yürekten özlüyor, bunun için Tanrıya yalvarıyorum.'),
(2011133,68,45,10,2,'Onlara ilişkin tanıklık ederim ki, Tanrı için gayretlidirler; ama bu bilinçli bir gayret değildir.'),
(2011134,68,45,10,3,'Tanrının öngördüğü doğruluğu anlamadıkları ve kendi doğruluklarını yerleştirmeye çalıştıkları için Tanrının öngördüğü doğruluğa boyun eğmediler.'),
(2011135,68,45,10,4,'Oysa her iman edenin aklanması için Mesih, Kutsal Yasanın sonudur.'),
(2011136,68,45,10,5,'Musa, Kutsal Yasaya dayanan doğrulukla ilgili şöyle yazıyor: ‹‹Yasanın gereklerini yapan, onlar sayesinde yaşayacaktır.››'),
(2011137,68,45,10,6,'İmana dayanan doğruluk ise şöyle diyor: ‹‹Yüreğinde, ‹Göğe -yani Mesihi indirmeye- kim çıkacak?› ya da, ‹Dipsiz derinliklere -yani Mesihi ölüler arasından çıkarmaya- kim inecek?› deme.››'),
(2011138,68,45,10,8,'Ne deniyor? ‹‹Tanrı sözü sana yakındır, Ağzında ve yüreğindedir.››'),
(2011139,68,45,10,9,'İsanın Rab olduğunu ağzınla açıkça söyler ve Tanrının Onu ölümden dirilttiğine yürekten iman edersen, kurtulacaksın.'),
(2011140,68,45,10,10,'Çünkü insan yürekten iman ederek aklanır, imanını ağzıyla açıklayarak kurtulur.'),
(2011141,68,45,10,11,'Kutsal Yazı, ‹‹Ona iman eden utandırılmayacak›› diyor.'),
(2011142,68,45,10,12,'Çünkü Yahudi Grek ayrımı yoktur, aynı Rab hepsinin Rabbidir. Kendisini çağıranların tümüne eliaçıktır.'),
(2011143,68,45,10,13,'‹‹Rabbi adıyla çağıran herkes kurtulacak.››'),
(2011144,68,45,10,14,'Ama iman etmedikleri kişiyi nasıl çağıracaklar? Duymadıkları kişiye nasıl iman edecekler? Tanrı sözünü yayan olmazsa, nasıl duyacaklar?'),
(2011145,68,45,10,15,'Sözü yaymaya gönderilmezlerse, sözü nasıl yayacaklar? Yazılmış olduğu gibi: ‹‹İyi haber müjdeleyenlerin ayakları ne güzeldir!››'),
(2011146,68,45,10,16,'Ne var ki, herkes Müjdeye uymadı. Yeşayanın dediği gibi: ‹‹Ya Rab, verdiğimiz habere kim inandı?››'),
(2011147,68,45,10,17,'Demek ki iman, haberi duymakla, duymak da Mesihle ilgili sözün yayılmasıyla olur.'),
(2011148,68,45,10,18,'Ama soruyorum: Onlar duymadılar mı? Elbet duydular. ‹‹Sesleri bütün yeryüzüne, Sözleri dünyanın dört bucağına ulaştı.››'),
(2011149,68,45,10,19,'Yine soruyorum: İsrail anlamadı mı? Önce Musa, ‹‹Ben sizi ulus olmayanla kıskandıracağım, Anlayışsız bir ulusla sizi öfkelendireceğim›› diyor.'),
(2011150,68,45,10,20,'Sonra Yeşaya cesaretle, ‹‹Aramayanlar beni buldu, Sormayanlara kendimi gösterdim›› diyor.'),
(2011151,68,45,10,21,'Öte yandan İsrail için şöyle diyor: ‹‹Söz dinlemeyen, asi bir halka Bütün gün ellerimi uzatıp durdum.››'),
(2011152,68,45,11,1,'Öyleyse soruyorum: Tanrı kendi halkından yüz mü çevirdi? Kesinlikle hayır! Ben de İbrahim soyundan, Benyamin oymağından bir İsrailliyim.'),
(2011153,68,45,11,2,'Tanrı önceden bildiği kendi halkından yüz çevirmedi. Yoksa İlyasla ilgili bölümde Kutsal Yazının ne dediğini, İlyasın Tanrıya nasıl İsrailden yakındığını bilmez misiniz?'),
(2011154,68,45,11,3,'‹‹Ya Rab, senin peygamberlerini öldürdüler, senin sunaklarını yıktılar. Yalnız ben kaldım. Beni de öldürmeye çalışıyorlar.››'),
(2011155,68,45,11,4,'Tanrının ona verdiği yanıt nedir? ‹‹Baalın önünde diz çökmemiş yedi bin kişiyi kendime ayırdım.››'),
(2011156,68,45,11,5,'Aynı şekilde, şimdiki dönemde de Tanrının lütfuyla seçilmiş küçük bir topluluk vardır.'),
(2011157,68,45,11,6,'Eğer bu, lütufla olmuşsa, iyi işlerle olmamış demektir. Yoksa lütuf artık lütuf olmaktan çıkar!'),
(2011158,68,45,11,7,'Sonuç ne? İsrail aradığına kavuşamadı, seçilmiş olanlar ise kavuştular. Geriye kalanlarınsa yürekleri nasırlaştırıldı.'),
(2011159,68,45,11,8,'Yazılmış olduğu gibi: ‹‹Tanrı onlara uyuşukluk ruhu verdi; Bugüne dek görmeyen gözler, duymayan kulaklar verdi.››'),
(2011160,68,45,11,9,'Davut da şöyle diyor: ‹‹Sofraları onlara tuzak, Kapan, tökez ve ceza olsun.'),
(2011161,68,45,11,10,'Gözleri kararsın, göremesinler. Bellerini hep iki büklüm et!››'),
(2011162,68,45,11,11,'Öyleyse soruyorum: İsrailliler, bir daha kalkmamak üzere mi sendeleyip düştüler? Kesinlikle hayır! Ama onların suçu yüzünden öteki uluslara kurtuluş verildi; öyle ki, İsrailliler onlara imrensin.'),
(2011163,68,45,11,12,'Eğer İsraillilerin suçu dünyaya zenginlik, bozgunu uluslara zenginlik getirdiyse, bütünlüğü çok daha büyük bir zenginlik getirecektir!'),
(2011164,68,45,11,13,'Öteki uluslardan olan sizlere söylüyorum: Uluslara elçi olarak gönderildiğim için görevimi yüce sayarım.'),
(2011165,68,45,11,14,'Böylelikle belki soydaşlarımı imrendirip bazılarını kurtarırım.'),
(2011166,68,45,11,15,'Çünkü onların reddedilmesi dünyanın Tanrıyla barışmasını sağladıysa, kabul edilmeleri ölümden yaşama geçiş değil de nedir?'),
(2011167,68,45,11,16,'Hamurun ilk parçası kutsalsa, tümü kutsaldır; kök kutsalsa, dallar da kutsaldır.'),
(2011168,68,45,11,17,'Ama zeytin ağacının bazı dalları kesildiyse ve sen yabanıl bir zeytin filiziyken onların yerine aşılanıp ağacın semiz köküne ortak oldunsa, o dallara karşı övünme. Eğer övünüyorsan, unutma ki, sen kökü taşımıyorsun, kök seni taşıyor.'),
(2011169,68,45,11,19,'O zaman, ‹‹Ben aşılanayım diye dallar kesildi›› diyeceksin.'),
(2011170,68,45,11,20,'Doğru, onlar imansızlık yüzünden kesildiler. Sense imanla yerinde duruyorsun. Böbürlenme, kork!'),
(2011171,68,45,11,21,'Çünkü Tanrı asıl dalları esirgemediyse, seni de esirgemeyecektir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011172,68,45,11,22,'Onun için Tanrının iyiliğini de sertliğini de gör. O, düşenlere karşı serttir; ama Onun iyiliğine bağlı kalırsan, sana iyi davranır. Yoksa sen de kesilip atılırsın!'),
(2011173,68,45,11,23,'İmansızlıkta direnmezlerse, İsrailliler de öz ağaca aşılanacaklar. Çünkü Tanrının onları eski yerlerine aşılamaya gücü vardır.'),
(2011174,68,45,11,24,'Eğer sen doğal yapısı yabanıl zeytin ağacından kesilip doğaya aykırı olarak cins zeytin ağacına aşılandınsa, asıl dalların öz zeytin ağacına aşılanacakları çok daha kesindir!'),
(2011175,68,45,11,25,'Kardeşler, bilgiçliğe kapılmamanız için şu sırdan habersiz kalmanızı istemem: İsraillilerden bir bölümünün yüreği, öteki uluslardan kurtulacakların sayısı tamamlanıncaya dek duyarsız kalacaktır.'),
(2011176,68,45,11,26,'Sonunda bütün İsrail kurtulacaktır. Yazılmış olduğu gibi: ‹‹Kurtarıcı Siyondan gelecek, Yakupun soyundan tanrısızlığı uzaklaştıracak.'),
(2011177,68,45,11,27,'Onların günahlarını kaldıracağım zaman Kendileriyle yapacağım antlaşma budur.››'),
(2011178,68,45,11,28,'İsrailliler Müjdeyi reddederek sizin uğrunuza Tanrıya düşman oldular; ama Tanrının seçimine göre, ataları sayesinde sevilmektedirler.'),
(2011179,68,45,11,29,'Çünkü Tanrının armağanları ve çağrısı geri alınamaz.'),
(2011180,68,45,11,30,'Bir zamanlar Tanrının sözünü dinlemeyen sizler şimdi İsraillilerin sözdinlemezliğinin sonucu merhamete kavuştunuz.'),
(2011181,68,45,11,31,'Bunun gibi, İsrailliler de, sizin kavuştuğunuz merhametle merhamete erişmek için şimdi söz dinlemez oldular.'),
(2011182,68,45,11,32,'Çünkü Tanrı, merhametini herkese göstermek için herkesi sözdinlemezliğin tutsağı kıldı.'),
(2011183,68,45,11,33,'Tanrının zenginliği ne büyük, bilgeliği ve bilgisi ne derindir! Onun yargıları ne denli akıl ermez, yolları ne denli anlaşılmazdır!'),
(2011184,68,45,11,34,'‹‹Rabbin düşüncesini kim bilebildi? Ya da kim Onun öğütçüsü olabildi?››'),
(2011185,68,45,11,35,'‹‹Kim Tanrıya bir şey verdi ki, Karşılığını Ondan isteyebilsin?››'),
(2011186,68,45,11,36,'Her şeyin kaynağı O''dur; her şey O''nun aracılığıyla ve O''nun için var oldu. O''na sonsuza dek yücelik olsun! Amin.'),
(2011187,68,45,12,1,'Öyleyse kardeşlerim, Tanrının merhameti adına size yalvarırım: Bedenlerinizi diri, kutsal, Tanrıyı hoşnut eden birer kurban olarak sunun. Ruhsal tapınmanız budur.'),
(2011188,68,45,12,2,'Bu çağın gidişine uymayın; bunun yerine, Tanrının iyi, beğenilir ve yetkin isteğinin ne olduğunu ayırt edebilmek için düşüncenizin yenilenmesiyle değişin.'),
(2011189,68,45,12,3,'Tanrının bana bağışladığı lütufla hepinize söylüyorum: Kimse kendisine gereğinden çok değer vermesin. Herkes Tanrının kendisine verdiği iman ölçüsüne göre düşüncelerinde sağduyulu olsun.'),
(2011190,68,45,12,4,'Bir bedende ayrı ayrı işlevleri olan çok sayıda üyemiz olduğu gibi, çok sayıda olan bizler de Mesihte tek bir bedeniz ve birbirimizin üyeleriyiz.'),
(2011191,68,45,12,6,'Tanrının bize bağışladığı lütfa göre, ayrı ayrı ruhsal armağanlarımız vardır. Birinin armağanı peygamberlikse, imanı oranında peygamberlik etsin.'),
(2011192,68,45,12,7,'Hizmetse, hizmet etsin. Öğretmekse, öğretsin.'),
(2011193,68,45,12,8,'Öğüt veren, öğütte bulunsun. Bağışta bulunan, bunu cömertçe yapsın. Yöneten, gayretle yönetsin. Merhamet eden, bunu güler yüzle yapsın.'),
(2011194,68,45,12,9,'Sevginiz ikiyüzlü olmasın. Kötülükten tiksinin, iyiliğe bağlanın.'),
(2011195,68,45,12,10,'Birbirinize kardeşlik sevgisiyle bağlı olun. Birbirinize saygı göstermekte yarışın.'),
(2011196,68,45,12,11,'Gayretiniz eksilmesin. Ruhta ateşli olun. Rabbe kulluk edin.'),
(2011197,68,45,12,12,'Umudunuzla sevinin. Sıkıntıya dayanın. Kendinizi duaya verin.'),
(2011198,68,45,12,13,'İhtiyaç içinde olan kutsallara yardım edin. Konuksever olmayı amaç edinin.'),
(2011199,68,45,12,14,'Size zulmedenler için iyilik dileyin. İyilik dileyin, lanet etmeyin.'),
(2011200,68,45,12,15,'Sevinenlerle sevinin, ağlayanlarla ağlayın.'),
(2011201,68,45,12,16,'Birbirinizle aynı düşüncede olun. Böbürlenmeyin; tersine, hor görülenlerle arkadaşlık edin. Bilgiçlik taslamayın.'),
(2011202,68,45,12,17,'Kötülüğe kötülükle karşılık vermeyin. Herkesin gözünde iyi olanı yapmaya dikkat edin.'),
(2011203,68,45,12,18,'Mümkünse, elinizden geldiğince herkesle barış içinde yaşayın.'),
(2011204,68,45,12,19,'Sevgili kardeşler, kimseden öç almayın; bunu Tanrının gazabına bırakın. Çünkü şöyle yazılmıştır: ‹‹Rab diyor ki, ‹Öç benimdir, ben karşılık vereceğim.› ››'),
(2011205,68,45,12,20,'Ama, ‹‹Düşmanın acıkmışsa doyur, Susamışsa su ver. Bunu yapmakla onu utanca boğarsın.››'),
(2011206,68,45,12,21,'Kötülüğe yenilme, kötülüğü iyilikle yen.'),
(2011207,68,45,13,1,'Herkes, baştaki yönetime bağlı olsun. Çünkü Tanrıdan olmayan yönetim yoktur. Var olanlar Tanrı tarafından kurulmuştur.'),
(2011208,68,45,13,2,'Bu nedenle, yönetime karşı direnen, Tanrı buyruğuna karşı gelmiş olur. Karşı gelenler yargılanır.'),
(2011209,68,45,13,3,'İyilik edenler değil, kötülük edenler yöneticilerden korkmalıdır. Yönetimden korkmamak ister misin, öyleyse iyi olanı yap, yönetimin övgüsünü kazanırsın.'),
(2011210,68,45,13,4,'Çünkü yönetim, senin iyiliğin için Tanrıya hizmet etmektedir. Ama kötü olanı yaparsan, kork! Yönetim, kılıcı boş yere taşımıyor; kötülük yapanın üzerine Tanrının gazabını salan öç alıcı olarak Tanrıya hizmet ediyor.'),
(2011211,68,45,13,5,'Bunun için, yalnız Tanrının gazabı nedeniyle değil, vicdan nedeniyle de yönetime bağlı olmak gerekir.'),
(2011212,68,45,13,6,'Vergi ödemenizin nedeni de budur. Çünkü yöneticiler Tanrının bu amaç için gayretle çalışan hizmetkârlarıdır.'),
(2011213,68,45,13,7,'Herkese hakkını verin: Vergi hakkı olana vergi, gümrük hakkı olana gümrük, saygı hakkı olana saygı, onur hakkı olana onur verin.'),
(2011214,68,45,13,8,'Birbirinizi sevmekten başka hiç kimseye bir şey borçlu olmayın. Çünkü başkalarını seven, Kutsal Yasayı yerine getirmiş olur.'),
(2011215,68,45,13,9,'‹‹Zina etmeyeceksin, adam öldürmeyeceksin, çalmayacaksın, başkasının malına göz dikmeyeceksin›› buyrukları ve bundan başka ne buyruk varsa, şu sözde özetlenmiştir: ‹‹Komşunu kendin gibi seveceksin.››'),
(2011216,68,45,13,10,'Seven kişi komşusuna kötülük etmez. Bu nedenle sevmek Kutsal Yasayı yerine getirmektir.'),
(2011217,68,45,13,11,'Bunu, yaşadığınız zamanın bilincinde olarak yapın. Artık sizin için uykudan uyanma saati gelmiştir. Çünkü şu anda kurtuluşumuz ilk iman ettiğimiz zamankinden daha yakındır.'),
(2011218,68,45,13,12,'Gece ilerledi, gündüz yaklaştı. Bunun için karanlığın işlerini üzerimizden atıp ışığın silahlarını kuşanalım.'),
(2011219,68,45,13,13,'Çılgınca eğlenceye ve sarhoşluğa, fuhşa ve sefahate, çekişmeye ve kıskançlığa kapılmayalım. Gün ışığında olduğu gibi, saygın bir yaşam sürelim.'),
(2011220,68,45,13,14,'Rab İsa Mesih''i kuşanın. Benliğinizin tutkularına uymayı düşünmeyin.'),
(2011221,68,45,14,1,'İmanı zayıf olanı aranıza kabul edin, ama tartışmalı konulara girmeyin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011222,68,45,14,2,'Biri her şeyi yiyebileceğine inanır; imanı zayıf olansa yalnız sebze yer.'),
(2011223,68,45,14,3,'Her şeyi yiyen, yemeyeni hor görmesin. Her şeyi yemeyen, yiyeni yargılamasın. Çünkü Tanrı onu kabul etmiştir.'),
(2011224,68,45,14,4,'Sen kimsin ki, başkasının kulunu yargılıyorsun? Kulu haklı çıkaran da haksız çıkaran da efendisidir. Kul haklı çıkacaktır. Çünkü Rabbin onu haklı çıkarmaya gücü vardır.'),
(2011225,68,45,14,5,'Kimi bir günü başka bir günden üstün sayar, kimi her günü bir sayar. Herkesin kendi görüşüne tam güveni olsun.'),
(2011226,68,45,14,6,'Belli bir günü kutlayan, Rab için kutlar. Her şeyi yiyen, Tanrıya şükrederek Rab için yer. Bazı şeyleri yemeyen de Rab için yemez ve Tanrıya şükreder.'),
(2011227,68,45,14,7,'Hiçbirimiz kendimiz için yaşamayız, hiçbirimiz de kendimiz için ölmeyiz.'),
(2011228,68,45,14,8,'Yaşarsak Rab için yaşarız; ölürsek Rab için ölürüz. Öyleyse, yaşasak da ölsek de Rabbe aitiz.'),
(2011229,68,45,14,9,'Mesih hem ölülerin hem yaşayanların Rabbi olmak üzere ölüp dirildi.'),
(2011230,68,45,14,10,'Sen neden kardeşini yargılıyorsun? Ya sen, kardeşini neden küçümsüyorsun? Tanrının yargı kürsüsü önüne hepimiz çıkacağız.'),
(2011231,68,45,14,11,'Yazılmış olduğu gibi: ‹‹Rab şöyle diyor: ‹Varlığım hakkı için her diz önümde çökecek, Her dil Tanrı olduğumu açıkça söyleyecek.› ››'),
(2011232,68,45,14,12,'Böylece her birimiz kendi adına Tanrıya hesap verecektir.'),
(2011233,68,45,14,13,'Onun için, artık birbirimizi yargılamayalım. Bunun yerine, hiçbir kardeşin yoluna sürçme ya da tökezleme taşı koymamaya kararlı olun.'),
(2011234,68,45,14,14,'Rab İsaya ait biri olarak kesinlikle biliyorum ki, hiçbir şey kendiliğinden murdar değildir. Ama bir şeyi murdar sayan için o şey murdardır.'),
(2011235,68,45,14,15,'Yediğin bir şey yüzünden kardeşin incinmişse, artık sevgi yolunda yürümüyorsun demektir. Mesihin, uğruna öldüğü kardeşini yediklerinle mahvetme!'),
(2011236,68,45,14,16,'Size göre iyi olanın kötülenmesine fırsat vermeyin.'),
(2011237,68,45,14,17,'Çünkü Tanrının Egemenliği, yiyecek içecek sorunu değil, doğruluk, esenlik ve Kutsal Ruhta sevinçtir.'),
(2011238,68,45,14,18,'Mesihe bu yolda hizmet eden, Tanrıyı hoşnut eder, insanların da beğenisini kazanır.'),
(2011239,68,45,14,19,'Öyleyse kendimizi esenlik getiren ve karşılıklı gelişmemizi sağlayan işlere verelim.'),
(2011240,68,45,14,20,'Yiyecek uğruna Tanrının işini bozma! Her yiyecek temizdir, ama yedikleriyle başkasının sürçmesine yol açan kişi kötülük etmiş olur.'),
(2011241,68,45,14,21,'Et yememen, şarap içmemen, kardeşinin sürçmesine yol açacak bir şey yapmaman iyidir.'),
(2011242,68,45,14,22,'Bu konulardaki inancını Tanrının önünde kendine sakla. Onayladığı şeyden ötürü kendini yargılamayan kişi ne mutludur!'),
(2011243,68,45,14,23,'Ama bir yiyecekten kuşkulanan kişi onu yerse yargılanır; çünkü imanla yemiyor. İmana dayanmayan her şey günahtır.'),
(2011244,68,45,15,1,'İmanı güçlü olan bizler, kendimizi hoşnut etmeye değil, güçsüzlerin zayıflıklarını yüklenmeye borçluyuz.'),
(2011245,68,45,15,2,'Her birimiz komşusunu ruhça geliştirmek için komşusunun iyiliğini gözeterek onu hoşnut etsin.'),
(2011246,68,45,15,3,'Çünkü Mesih bile kendini hoşnut etmeye çalışmadı. Yazılmış olduğu gibi: ‹‹Sana edilen hakaretlere ben uğradım.››'),
(2011247,68,45,15,4,'Önceden ne yazıldıysa, bize öğretmek için, sabırla ve Kutsal Yazıların verdiği cesaretle umudumuz olsun diye yazıldı.'),
(2011248,68,45,15,5,'Sabır ve cesaret kaynağı olan Tanrının, sizleri Mesih İsanın isteğine uygun olarak aynı düşüncede birleştirmesini dilerim.'),
(2011249,68,45,15,6,'Öyle ki, Rabbimiz İsa Mesihin Tanrısını ve Babasını birlik içinde hep bir ağızdan yüceltesiniz.'),
(2011250,68,45,15,7,'Bu nedenle, Mesih sizi kabul ettiği gibi, Tanrının yüceliği için birbirinizi kabul edin.'),
(2011251,68,45,15,8,'Çünkü diyorum ki Mesih, Tanrının güvenilir olduğunu göstermek için Yahudilerin hizmetkârı oldu. Öyle ki, atalarımıza verilen sözler doğrulansın ve öteki uluslar merhameti için Tanrıyı yüceltsin. Yazılmış olduğu gibi: ‹‹Bunun için uluslar arasında sana şükredeceğim, Adını ilahilerle öveceğim.››'),
(2011252,68,45,15,10,'Yine deniyor ki, ‹‹Ey uluslar, Onun halkıyla birlikte sevinin!›› Ve, ‹‹Ey bütün uluslar, Rabbe övgüler sunun! Ey bütün halklar, Onu yüceltin!››'),
(2011253,68,45,15,12,'Yeşaya da şöyle diyor: ‹‹İşayın Kökü ortaya çıkacak, Uluslara egemen olmak üzere yükselecek. Uluslar Ona umut bağlayacak.››'),
(2011254,68,45,15,13,'Umut kaynağı olan Tanrı, Kutsal Ruhun gücüyle umutla dolup taşmanız için iman yaşamınızda sizleri tam bir sevinç ve esenlikle doldursun.'),
(2011255,68,45,15,14,'Size gelince, kardeşlerim, iyilikle dolu, her bilgiyle donanmış olduğunuzdan ben eminim. Ayrıca, birbirinize öğüt verebilecek durumdasınız.'),
(2011256,68,45,15,15,'Yine de Tanrının bana bağışladığı lütufla bazı noktaları yeniden anımsatmak için size yazma cesaretini gösterdim.'),
(2011257,68,45,15,16,'Ben Tanrının lütfuyla uluslar yararına Mesih İsanın hizmetkârı oldum. Tanrının Müjdesini bir kâhin olarak yaymaktayım. Öyle ki uluslar, Kutsal Ruhla kutsal kılınarak Tanrıyı hoşnut eden bir sunu olsun.'),
(2011258,68,45,15,17,'Bunun için Mesih İsaya ait biri olarak Tanrıya verdiğim hizmetle övünebilirim.'),
(2011259,68,45,15,18,'Ulusların söz dinlemesi için Mesihin benim aracılığımla, sözle ve eylemle, mucizeler ve harikalar yaratan güçle, Kutsal Ruhun gücüyle yaptıklarından başka şeyden söz etmeye cesaret edemem. Yeruşalimden başlayıp İllirikum bölgesine kadar dolaşarak Mesihin Müjdesini her yerde duyurdum.'),
(2011260,68,45,15,20,'Bir başkasının attığı temel üzerine inşa etmemek için Müjdeyi Mesihin adının duyulmadığı yerlerde yaymayı amaç edindim.'),
(2011261,68,45,15,21,'Yazılmış olduğu gibi: ‹‹Ondan habersiz olanlar görecekler. Duymamış olanlar anlayacaklar.››'),
(2011262,68,45,15,22,'İşte bu yüzden yanınıza gelmem kaç kez engellendi.'),
(2011263,68,45,15,23,'Şimdiyse bu yörelerde artık yapacağım bir şey kalmadığından, yıllardır da yanınıza gelmeyi arzuladığımdan, İspanyaya giderken size uğrarım. Yol üzerinde sizi görüp bir süre arkadaşlığınıza doyduktan sonra beni oraya uğurlayacağınızı umarım.'),
(2011264,68,45,15,25,'Ama şimdi kutsallara bir hizmet için Yeruşalime gidiyorum.'),
(2011265,68,45,15,26,'Çünkü Makedonya ve Ahayada bulunanlar, Yeruşalimdeki kutsallar arasında yoksul olanlar için yardım toplamayı uygun gördüler.'),
(2011266,68,45,15,27,'Evet, uygun gördüler. Gerçekte onlara yardım borçlular. Uluslar, onların ruhsal bereketlerine ortak olduklarına göre, maddesel bereketlerle onlara hizmet etmeye borçlular.'),
(2011267,68,45,15,28,'Bu işi bitirip sağlanan yardımı onlara ulaştırdıktan sonra size uğrayacağım, sonra da İspanyaya gideceğim.'),
(2011268,68,45,15,29,'Yanınıza geldiğimde, Mesihin bereketinin doluluğuyla geleceğimi biliyorum.'),
(2011269,68,45,15,30,'Kardeşler, Rabbimiz İsa Mesih ve Ruhun sevgisi adına size yalvarıyorum, benim için Tanrıya dua ederek uğraşıma katılın.'),
(2011270,68,45,15,31,'Yahudiyedeki imansızlardan kurtulmam için ve Yeruşalime olan hizmetimin kutsallarca kabul edilmesi için dua edin.'),
(2011271,68,45,15,32,'Öyle ki, Tanrının isteğiyle sevinçle yanınıza gelip sizlerle gönlümü ferahlatayım.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011272,68,45,15,33,'Esenlik veren Tanrı hepinizle birlikte olsun! Amin.'),
(2011273,68,45,16,1,'Kenheredeki kilisenin görevlisi olan kızkardeşimiz Fibiyi size salık veririm.'),
(2011274,68,45,16,2,'Kutsallara yaraşır biçimde onu Rabbin adına kabul edin. Herhangi bir ihtiyacı olursa, kendisine yardım edin. Çünkü o, ben dahil, birçoklarına destek sağlamıştır.'),
(2011275,68,45,16,3,'Mesih İsa yolunda emektaşlarım olan Priska ve Akvilaya selam edin.'),
(2011276,68,45,16,4,'Onlar benim uğruma yaşamlarını tehlikeye attılar. Yalnız ben değil, öteki ulusların bütün kiliseleri de onlara minnettardır.'),
(2011277,68,45,16,5,'Onların evindeki inanlılar topluluğuna da selam söyleyin. Asya İlinden Mesihe ilk iman eden sevgili kardeşim Epenetusa selam edin.'),
(2011278,68,45,16,6,'Sizin için çok çalışmış olan Meryeme selam söyleyin.'),
(2011279,68,45,16,7,'Mesihin elçileri arasında tanınmış ve benden önce Mesihe inanmış olan soydaşlarım ve hapishane arkadaşlarım Andronikusla Yunyaya selam edin.'),
(2011280,68,45,16,8,'Rabbe ait olan sevgili kardeşim Ampliatusa selam söyleyin.'),
(2011281,68,45,16,9,'Mesih yolunda emektaşımız olan Urbanusa ve sevgili kardeşim Stakise selam edin.'),
(2011282,68,45,16,10,'Mesihin beğenisini kazanmış olan Apellise selam söyleyin. Aristobulusun ev halkından olanlara selam edin.'),
(2011283,68,45,16,11,'Soydaşım Herodiona selam söyleyin. Narkisin ev halkından Rabbe ait olanlara selam söyleyin.'),
(2011284,68,45,16,12,'Rabbin hizmetinde çalışan Trifenayla Trifosaya selam edin. Rabbin hizmetinde çok çalışmış olan sevgili Persise selam söyleyin.'),
(2011285,68,45,16,13,'Rabbin seçkin kulu olan Rufusa ve bana da annelik etmiş olan annesine selam edin.'),
(2011286,68,45,16,14,'Asinkritus, Flegon, Hermes, Patrovas, Hermas ve yanlarındaki kardeşlere selam edin.'),
(2011287,68,45,16,15,'Filologusla Yulyaya, Nereusla kızkardeşine, Olimpasla yanlarındaki bütün kutsallara selam edin.'),
(2011288,68,45,16,16,'Birbirinizi kutsal öpüşle selamlayın. Mesihin bütün kiliseleri size selam ederler.'),
(2011289,68,45,16,17,'Kardeşler, size yalvarırım, aldığınız öğretiye karşı gelerek ayrılıklara ve sapmalara neden olanlara dikkat edin, onlardan sakının.'),
(2011290,68,45,16,18,'Böyle kişiler Rabbimiz Mesihe değil, kendi midelerine kulluk ediyorlar. Saf kişilerin yüreklerini kulağı okşayan tatlı sözlerle aldatıyorlar.'),
(2011291,68,45,16,19,'Sözdinlerliğinizi herkes duydu, bu nedenle sizin adınıza seviniyorum. İyilik konusunda bilge, kötülük konusunda deneyimsiz olmanızı isterim.'),
(2011292,68,45,16,20,'Esenlik veren Tanrı çok geçmeden Şeytanı ayaklarınızın altında ezecektir. Rabbimiz İsanın lütfu sizinle birlikte olsun.'),
(2011293,68,45,16,21,'Emektaşım Timoteos, soydaşlarımdan Lukius, Yason ve Sosipater size selam ederler.'),
(2011294,68,45,16,22,'Mektubu yazıya geçiren ben Tertius, Rabbe ait biri olarak size selamlarımı gönderirim.'),
(2011295,68,45,16,23,'Bana ve bütün inanlılar topluluğuna konukseverlik eden Gayus size selam eder. Kent haznedarı Erastusun ve Kuartus kardeşin size selamları var.'),
(2011296,68,45,16,25,'Tanrı, duyurduğum Müjde ve İsa Mesihle ilgili bildiri uyarınca, sonsuz çağlardan beri saklı tutulan sırrı açıklayan vahiy uyarınca sizi ruhça pekiştirecek güçtedir.'),
(2011297,68,45,16,26,'O sır şimdi aydınlığa çıkarılmış ve öncesiz Tanrının buyruğuna göre peygamberlerin yazıları aracılığıyla bütün ulusların iman ederek söz dinlemesi için bildirilmiştir.'),
(2011298,68,45,16,27,'Bilge olan tek Tanrı''ya İsa Mesih aracılığıyla sonsuza dek yücelik olsun! Amin.'),
(2011299,68,46,1,1,'Tanrının isteğiyle Mesih İsanın elçisi olmaya çağrılan ben Pavlus ve kardeşimiz Sostenisten Tanrının Korintteki kilisesine selam! Mesih İsada kutsal kılınmış, kutsal olmaya çağrılmış olan sizlere ve hepimizin Rabbi İsa Mesihin adını her yerde anan herkese Babamız Tanrıdan ve Rab İsa Mesihten lütuf ve esenlik olsun.'),
(2011300,68,46,1,4,'Tanrının Mesih İsada size bağışladığı lütuftan ötürü sizin için her zaman Tanrıma şükrediyorum.'),
(2011301,68,46,1,5,'Mesihle ilgili tanıklığımız sizde pekiştiği gibi Mesihte her bakımdan -her tür söz ve bilgi bakımından- zenginleştiniz.'),
(2011302,68,46,1,7,'Şöyle ki, Rabbimiz İsa Mesihin görünmesini beklerken hiçbir ruhsal armağandan yoksun değilsiniz.'),
(2011303,68,46,1,8,'Rabbimiz İsa Mesih kendi gününde kusursuz olmanız için sizi sonuna dek pekiştirecektir.'),
(2011304,68,46,1,9,'Sizleri Oğlu Rabbimiz İsa Mesihle paydaşlığa çağıran Tanrı güvenilirdir.'),
(2011305,68,46,1,10,'Kardeşler, Rabbimiz İsa Mesihin adıyla yalvarıyorum: Hepiniz uyum içinde olun, aranızda bölünmeler olmadan aynı düşünce ve görüşte birleşin.'),
(2011306,68,46,1,11,'Kardeşlerim, Kloinin ev halkından aranızda çekişmeler olduğunu öğrendim.'),
(2011307,68,46,1,12,'Şunu demek istiyorum: Her biriniz, ‹‹Ben Pavlus yanlısıyım››, ‹‹Ben Apollos yanlısıyım››, ‹‹Ben Kefas yanlısıyım›› ya da ‹‹Ben Mesih yanlısıyım›› diyormuş.'),
(2011308,68,46,1,13,'Mesih bölündü mü? Sizin için çarmıha gerilen Pavlus muydu? Pavlusun adıyla mı vaftiz edildiniz?'),
(2011309,68,46,1,14,'Hiç kimse benim adımla vaftiz edildiğinizi söylemesin diye Krispusla Gayustan başka hiçbirinizi vaftiz etmediğim için Tanrıya şükrediyorum.'),
(2011310,68,46,1,16,'Evet, bir de İstefanasın ev halkını vaftiz ettim; bunun dışında kimseyi vaftiz ettiğimi anımsamıyorum.'),
(2011311,68,46,1,17,'Çünkü Mesih beni vaftiz etmeye değil, Mesihin çarmıhtaki ölümü boşa gitmesin diye, bilgece sözlere dayanmaksızın Müjdeyi yaymaya gönderdi.'),
(2011312,68,46,1,18,'Çarmıhla ilgili bildiri mahva gidenler için saçmalık, biz kurtulmakta olanlar içinse Tanrı gücüdür.'),
(2011313,68,46,1,19,'Nitekim şöyle yazılmıştır: ‹‹Bilgelerin bilgeliğini yok edeceğim, Akıllıların aklını boşa çıkaracağım.››'),
(2011314,68,46,1,20,'Hani nerede bilge kişi? Din bilgini nerede? Nerede bu çağın hünerli tartışmacısı? Tanrı dünya bilgeliğinin saçma olduğunu göstermedi mi?'),
(2011315,68,46,1,21,'Mademki dünya Tanrının bilgeliği uyarınca Tanrıyı kendi bilgeliğiyle tanımadı, Tanrı iman edenleri saçma sayılan bildiriyle kurtarmaya razı oldu.'),
(2011316,68,46,1,22,'Yahudiler doğaüstü belirtiler ister, Greklerse bilgelik arar.'),
(2011317,68,46,1,23,'Ama biz çarmıha gerilmiş Mesihi duyuruyoruz. Yahudiler bunu yüzkarası, öteki uluslar da saçmalık sayarlar.'),
(2011318,68,46,1,24,'Oysa Mesih, çağrılmış olanlar için -ister Yahudi ister Grek olsun- Tanrının gücü ve Tanrının bilgeliğidir.'),
(2011319,68,46,1,25,'Çünkü Tanrının ‹‹saçmalığı›› insan bilgeliğinden daha üstün, Tanrının ‹‹zayıflığı›› insan gücünden daha güçlüdür.'),
(2011320,68,46,1,26,'Kardeşlerim, aldığınız çağrıyı düşünün. Birçoğunuz insan ölçülerine göre bilge, güçlü ya da soylu kişiler değildiniz.'),
(2011321,68,46,1,27,'Ne var ki, Tanrı bilgeleri utandırmak için dünyanın saçma saydıklarını, güçlüleri utandırmak için de dünyanın zayıf saydıklarını seçti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011322,68,46,1,28,'Dünyanın önemli gördüklerini hiçe indirmek için dünyanın önemsiz, soysuz, değersiz gördüklerini seçti.'),
(2011323,68,46,1,29,'Öyle ki, Tanrının önünde hiç kimse övünemesin.'),
(2011324,68,46,1,30,'Ama siz Tanrı sayesinde Mesih İsadasınız. O bizim için tanrısal bilgelik, doğruluk, kutsallık ve kurtuluş oldu.'),
(2011325,68,46,1,31,'Bunun için yazılmış olduğu gibi, ‹‹Övünen, Rab''le övünsün.››'),
(2011326,68,46,2,1,'Kardeşler, Tanrıyla ilgili bildiriyi duyurmak için size geldiğimde, söz ustalığıyla ya da üstün bilgelikle gelmedim.'),
(2011327,68,46,2,2,'Aranızdayken, İsa Mesihten ve Onun çarmıha gerilişinden başka hiçbir şey bilmemeye kararlıydım.'),
(2011328,68,46,2,3,'Size zayıflık ve korku içinde geldim, tir tir titriyordum!'),
(2011329,68,46,2,4,'Sözüm ve bildirim, insan bilgeliğinin ikna edici sözlerine değil, Ruhun kanıtlayıcı gücüne dayanıyordu.'),
(2011330,68,46,2,5,'Öyle ki, imanınız insan bilgeliğine değil, Tanrı gücüne dayansın.'),
(2011331,68,46,2,6,'Gerçi olgun kişiler arasında bilgece sözler söylüyoruz; ama bu bilgelik ne şimdiki çağın, ne de bu çağın gelip geçici önderlerinin bilgeliğidir.'),
(2011332,68,46,2,7,'Tanrının saklı bilgeliğinden gizemli biçimde söz ediyoruz. Zamanın başlangıcından önce Tanrının bizim yüceliğimiz için belirlediği bu bilgeliği bu çağın önderlerinden hiçbiri anlamadı. Anlasalardı yüce Rabbi çarmıha germezlerdi.'),
(2011333,68,46,2,9,'Yazılmış olduğu gibi, ‹‹Tanrının kendisini sevenler için hazırladıklarını Hiçbir göz görmedi, Hiçbir kulak duymadı, Hiçbir insan yüreği kavramadı.››'),
(2011334,68,46,2,10,'Oysa Tanrı Ruh aracılığıyla bunları bize açıkladı. Çünkü Ruh her şeyi, Tanrının derin düşüncelerini bile araştırır.'),
(2011335,68,46,2,11,'İnsanın düşüncelerini, insanın içindeki ruhundan başka kim bilebilir? Bunun gibi, Tanrının düşüncelerini de Tanrının Ruhundan başkası bilemez.'),
(2011336,68,46,2,12,'Tanrının bize lütfettiklerini bilelim diye, bu dünyanın ruhunu değil, Tanrıdan gelen Ruhu aldık.'),
(2011337,68,46,2,13,'Ruhsal kişilere ruhsal gerçekleri açıklarken, Tanrının lütfettiklerini insan bilgeliğinin öğrettiği sözlerle değil, Ruhun öğrettiği sözlerle bildiririz.'),
(2011338,68,46,2,14,'Doğal kişi, Tanrının Ruhuyla ilgili gerçekleri kabul etmez. Çünkü bunlar ona saçma gelir, ruhça değerlendirildikleri için bunları anlayamaz.'),
(2011339,68,46,2,15,'Ruhsal kişi her konuda yargı yürütebilir, ama kimse onun hakkında yargı yürütemez.'),
(2011340,68,46,2,16,'‹‹Rab''bin düşüncesini kim bildi ki, O''na öğüt verebilsin?›› Oysa biz Mesih''in düşüncesine sahibiz.'),
(2011341,68,46,3,1,'Kardeşler, ben sizinle ruhsal kişilerle konuşur gibi konuşamadım. Benliğe uyanlarla, Mesihte henüz bebeklik çağında olanlarla konuşur gibi konuştum.'),
(2011342,68,46,3,2,'Size süt verdim, katı yiyecek değil. Çünkü katı yiyeceği henüz yiyemiyordunuz. Şimdi bile yiyemezsiniz.'),
(2011343,68,46,3,3,'Çünkü hâlâ benliğe uyuyorsunuz. Aranızda kıskançlık ve çekişme olması, benliğe uyduğunuzu, öbür insanlar gibi yaşadığınızı göstermiyor mu?'),
(2011344,68,46,3,4,'Biriniz, ‹‹Ben Pavlus yanlısıyım››, ötekiniz, ‹‹Ben Apollos yanlısıyım›› diyorsa, öbür insanlardan ne farkınız kalır?'),
(2011345,68,46,3,5,'Apollos kim, Pavlus kim? İman etmenize aracı olmuş hizmetkârlardır. Rab her birimize bir görev vermiştir.'),
(2011346,68,46,3,6,'Tohumu ben ektim, Apollos suladı. Ama Tanrı büyüttü.'),
(2011347,68,46,3,7,'Önemli olan, eken ya da sulayan değil, ekileni büyüten Tanrıdır.'),
(2011348,68,46,3,8,'Ekenle sulayanın değeri birdir. Her biri kendi emeğinin karşılığını alacaktır.'),
(2011349,68,46,3,9,'Biz Tanrının emektaşlarıyız. Sizler de Tanrının tarlası, Tanrının binasısınız.'),
(2011350,68,46,3,10,'Tanrının bana lütfettiği görev uyarınca bilge bir mimar gibi temel attım, başkaları da bu temel üzerine inşa ediyor. Herkes nasıl inşa ettiğine dikkat etsin.'),
(2011351,68,46,3,11,'Çünkü hiç kimse atılan temelden, yani İsa Mesihten başka bir temel atamaz.'),
(2011352,68,46,3,12,'Bu temel üzerine kimi altın, gümüş ya da değerli taşlarla, kimi de tahta, ot ya da kamışla inşa edecek.'),
(2011353,68,46,3,13,'Herkesin yaptığı iş belli olacak, yargı günü ortaya çıkacak. Herkesin işi ateşle açığa vurulacak. Ateş her işin niteliğini sınayacak.'),
(2011354,68,46,3,14,'Bir kimsenin inşa ettikleri ateşe dayanırsa, o kimse ödülünü alacak.'),
(2011355,68,46,3,15,'Yaptıkları yanarsa, zarar edecek. Kendisi kurtulacak, ama ateşten geçmiş gibi olacaktır.'),
(2011356,68,46,3,16,'Tanrının tapınağı olduğunuzu, Tanrının Ruhunun sizde yaşadığını bilmiyor musunuz?'),
(2011357,68,46,3,17,'Kim Tanrının tapınağını yıkarsa, Tanrı da onu yıkacak. Çünkü Tanrının tapınağı kutsaldır ve o tapınak sizsiniz.'),
(2011358,68,46,3,18,'Kimse kendini aldatmasın. Aranızdan biri bu çağın ölçülerine göre kendini bilge sanıyorsa, bilge olmak için ‹‹akılsız›› olsun!'),
(2011359,68,46,3,19,'Çünkü bu dünyanın bilgeliği Tanrının gözünde akılsızlıktır. Yazılmış olduğu gibi, ‹‹O, bilgeleri kurnazlıklarında yakalar.››'),
(2011360,68,46,3,20,'Yine, ‹‹Rab bilgelerin düşüncelerinin boş olduğunu bilir›› diye yazılmıştır.'),
(2011361,68,46,3,21,'Bu nedenle hiç kimse insanlarla övünmesin. Çünkü her şey sizindir.'),
(2011362,68,46,3,22,'Pavlus, Apollos, Kefas, dünya, yaşam ve ölüm, şimdiki ve gelecek zaman, her şey sizindir.'),
(2011363,68,46,3,23,'Siz Mesih''insiniz, Mesih de Tanrı''nındır.'),
(2011364,68,46,4,1,'Böylece insanlar bizi Mesihin hizmetkârları ve Tanrının sırlarının kâhyaları saysın.'),
(2011365,68,46,4,2,'Kâhyada aranan başlıca nitelik güvenilir olmasıdır.'),
(2011366,68,46,4,3,'Sizin tarafınızdan ya da olağan bir mahkeme tarafından yargılanırsam hiç aldırmam. Kendi kendimi de yargılamıyorum.'),
(2011367,68,46,4,4,'Kendimde bir kusur görmüyorum. Ama bu beni aklamaz. Beni yargılayan Rabdir.'),
(2011368,68,46,4,5,'Bu nedenle, belirlenen zamandan önce hiçbir şeyi yargılamayın. Rabbin gelişini bekleyin. O, karanlığın gizlediklerini aydınlığa çıkaracak, yüreklerdeki amaçları açığa vuracaktır. O zaman herkes Tanrıdan payına düşen övgüyü alacaktır.'),
(2011369,68,46,4,6,'Kardeşler, bizden örnek alarak, ‹‹Yazılmış olanın dışına çıkmayın›› sözünün anlamını öğrenmeniz için bu ilkeleri sizin yararınıza kendime ve Apollosa uyguladım. Öyle ki, hiç kimse biriyle övünüp bir başkasını hor görmesin.'),
(2011370,68,46,4,7,'Seni başkasından üstün kılan kim? Tanrıdan almadığın neyin var ki? Madem aldın, niçin almamış gibi övünüyorsun?'),
(2011371,68,46,4,8,'Zaten tok ve zenginsiniz! Biz olmadan krallar olmuşsunuz! Keşke gerçekten krallar olsaydınız da, biz de sizinle birlikte krallık etseydik!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011372,68,46,4,9,'Kanımca Tanrı biz elçileri, en geriden gelen ölüm hükümlüleri gibi gözler önüne serdi. Hem melekler hem insanlar için, bütün evren için seyirlik oyun olduk.'),
(2011373,68,46,4,10,'Biz Mesih uğruna akılsızız, ama siz Mesihte akıllısınız! Biz zayıfız, siz güçlüsünüz! Siz saygıdeğer kişilersiniz, bizse değersiziz!'),
(2011374,68,46,4,11,'Şu ana dek aç, susuz, çıplağız. Dövülüyoruz, barınacak yerimiz yok.'),
(2011375,68,46,4,12,'Kendi ellerimizle çalışıp emek veriyoruz. Bize sövenlere iyilik diliyoruz, zulmedilince sabrediyoruz.'),
(2011376,68,46,4,13,'İftiraya uğrayınca tatlılıkla karşılık veriyoruz. Şu ana dek adeta dünyanın süprüntüsü, her şeyin döküntüsü olduk.'),
(2011377,68,46,4,14,'Bunları sizi utandırmak için değil, siz sevgili çocuklarımı uyarmak için yazıyorum.'),
(2011378,68,46,4,15,'Çünkü Mesihin yolunda sayısız eğiticiniz olsa da çok sayıda babanız yoktur. Size Müjdeyi ulaştırmakla Mesih İsada manevi babanız oldum.'),
(2011379,68,46,4,16,'Bu nedenle beni örnek almaya çağırıyorum sizi.'),
(2011380,68,46,4,17,'Rabbe sadık olan sevgili çocuğum Timoteosu bu amaçla size gönderiyorum. Her yerde, her kilisede öğrettiğim ve Mesihte izlediğim yolları o size anımsatacaktır.'),
(2011381,68,46,4,18,'Bazılarınız yanınıza gelmeyeceğimi sanarak küstahlaşıyor.'),
(2011382,68,46,4,19,'Ama Rab dilerse yakında yanınıza geleceğim. O zaman bu küstahların söylediklerini değil, güçlerinin ne olduğunu öğreneceğim.'),
(2011383,68,46,4,20,'Çünkü Tanrının Egemenliği lafta değil, güçtedir.'),
(2011384,68,46,4,21,'Ne istiyorsunuz? Size sopayla mı geleyim, yoksa sevgi ve yumuşak bir ruhla mı?'),
(2011385,68,46,5,1,'Aranızda fuhuş olduğu söyleniyor, üstelik putperestler arasında bile rastlanmayan türden bir fuhuş! Biri babasının karısını almış.'),
(2011386,68,46,5,2,'Siz hâlâ böbürleniyorsunuz! Oysa yas tutup bu işi yapanı aranızdan atmanız gerekmez miydi?'),
(2011387,68,46,5,3,'Bedence olmasa da ruhça aranızdayım. Bu suçu işleyeni, aranızdaymışım gibi Rabbimiz İsanın adıyla zaten yargılamış bulunuyorum. Ben ruhça aranızdayken Rabbimiz İsanın gücüyle toplandığınız zaman, bedeninin yok olması için bu adamı Şeytana teslim edin ki, Rab İsanın gününde ruhu kurtulabilsin.'),
(2011388,68,46,5,6,'Övünmeniz yersizdir. Azıcık mayanın bütün hamuru kabarttığını bilmiyor musunuz?'),
(2011389,68,46,5,7,'Yeni bir hamur olabilmek için eski mayadan arınıp temizlenin. Zaten mayasızsınız. Çünkü Fısıh kuzumuz Mesih kurban edildi.'),
(2011390,68,46,5,8,'Bunun için eski mayayla -kin ve kötülük mayasıyla- değil, içtenliğin ve dürüstlüğün mayasız ekmeğiyle bayram edelim.'),
(2011391,68,46,5,9,'Mektubumda size fuhuş yapanlarla arkadaşlık etmemenizi yazdım.'),
(2011392,68,46,5,10,'Kuşkusuz dünyadaki ahlaksızları, açgözlüleri, soyguncuları ya da putperestleri demek istemedim. Öyle olsaydı, dünyadan ayrılmak zorunda kalırdınız!'),
(2011393,68,46,5,11,'Ama şimdi size şunu yazıyorum: Kardeş diye bilinirken fuhuş yapan, açgözlü, putperest, sövücü, ayyaş ya da soyguncu olanla arkadaşlık etmeyin, böyle biriyle yemek bile yemeyin.'),
(2011394,68,46,5,12,'İnanlılar topluluğunun dışındakileri yargılamaya benim ne hakkım var? Sizin de yargılamanız gereken kişiler topluluğun içindekiler değil mi?'),
(2011395,68,46,5,13,'Topluluğun dışında kalanları Tanrı yargılar. ‹‹Kötü adamı aranızdan kovun!››'),
(2011396,68,46,6,1,'Sizden birinin öbürüne karşı bir davası varsa kutsallar önünde değil de, imansızlar önünde yargılanmaya cesaret eder mi?'),
(2011397,68,46,6,2,'Kutsalların dünyayı yargılayacağını bilmiyor musunuz? Madem dünyayı yargılayacaksınız, böyle önemsiz davaları görmeye yeterli değil misiniz?'),
(2011398,68,46,6,3,'Bu yaşamla ilgili davalar bir yana, melekleri bile yargılayacağımızı bilmiyor musunuz?'),
(2011399,68,46,6,4,'Bu yaşamla ilgili davalarınız olduğunda, inanlılar topluluğunda en önemsiz sayılanları mı yargıç atıyorsunuz?'),
(2011400,68,46,6,5,'Sizi utandırmak için söylüyorum bunu. Kardeşler arasındaki davalarda yargıçlık edecek kadar bilge biri yok mu aranızda?'),
(2011401,68,46,6,6,'Kardeş kardeşe karşı dava açıyor, üstelik imansızlar önünde!'),
(2011402,68,46,6,7,'Aslında birbirinizden davacı olmanız bile sizin için düpedüz yenilgidir. Haksızlığa uğrasanız daha iyi olmaz mı? Dolandırılsanız daha iyi olmaz mı?'),
(2011403,68,46,6,8,'Bunun yerine, siz kendiniz haksızlık edip başkasını dolandırıyorsunuz. Üstelik bunu kardeşlerinize yapıyorsunuz.'),
(2011404,68,46,6,9,'Günahkârların, Tanrı Egemenliğini miras almayacağını bilmiyor musunuz? Aldanmayın! Ne fuhuş yapanlar Tanrının Egemenliğini miras alacaktır, ne puta tapanlar, ne zina edenler, ne oğlanlar, ne oğlancılar, ne hırsızlar, ne açgözlüler, ne ayyaşlar, ne sövücüler, ne de soyguncular.'),
(2011405,68,46,6,11,'Bazılarınız böyleydiniz; ama yıkandınız, kutsal kılındınız, Rab İsa Mesih adıyla ve Tanrımızın Ruhu aracılığıyla aklandınız.'),
(2011406,68,46,6,12,'‹‹Bana her şey serbest›› diyorsunuz, ama her şey yararlı değildir. ‹‹Bana her şey serbest›› diyorsunuz, ama hiçbir şeyin tutsağı olmayacağım.'),
(2011407,68,46,6,13,'‹‹Yemek mide için, mide de yemek içindir›› diyorsunuz, ama Tanrı hem mideyi hem de yemeği ortadan kaldıracaktır. Beden fuhuş için değil, Rab içindir. Rab de beden içindir.'),
(2011408,68,46,6,14,'Rabbi dirilten Tanrı, kudretiyle bizi de diriltecek.'),
(2011409,68,46,6,15,'Bedenlerinizin Mesihin üyeleri olduğunu bilmiyor musunuz? Mesihin üyelerini alıp bir fahişenin üyeleri mi yapayım? Asla!'),
(2011410,68,46,6,16,'Yoksa fahişeyle birleşenin, onunla tek beden olduğunu bilmiyor musunuz? Çünkü ‹‹İkisi tek beden olacak›› deniyor.'),
(2011411,68,46,6,17,'Rable birleşen kişiyse Onunla tek ruh olur.'),
(2011412,68,46,6,18,'Fuhuştan kaçının. İnsanın işlediği bütün öbür günahlar bedenin dışındadır; ama fuhuş yapan, kendi bedenine karşı günah işler.'),
(2011413,68,46,6,19,'Bedeninizin, Tanrıdan aldığınız ve içinizdeki Kutsal Ruhun tapınağı olduğunu bilmiyor musunuz? Kendinize ait değilsiniz.'),
(2011414,68,46,6,20,'Bir bedel karşılığı satın alındınız; onun için Tanrı''yı bedeninizde yüceltin.'),
(2011415,68,46,7,1,'Şimdi bana yazdığınız konulara gelelim: ‹‹Erkeğin kadına dokunmaması iyidir›› diyorsunuz.'),
(2011416,68,46,7,2,'Ama fuhuştan ötürü her erkek karısıyla, her kadın da kocasıyla yaşasın.'),
(2011417,68,46,7,3,'Erkek karısına, kadın da kocasına hakkını versin.'),
(2011418,68,46,7,4,'Kadının bedeni kendisine değil, kocasına aittir. Bunun gibi, erkeğin bedeni de kendisine değil, karısına aittir.'),
(2011419,68,46,7,5,'Geçici bir süre için anlaşıp kendinizi duaya vermekten başka bir nedenle birbirinizi mahrum etmeyin. Sonra yine birleşin ki, kendinizi denetleyemediğiniz için Şeytan sizi ayartmasın.'),
(2011420,68,46,7,6,'Bunu bir buyruk olarak değil, bir uzlaşma yolu olarak söylüyorum.'),
(2011421,68,46,7,7,'Herkesin benim gibi olmasını dilerdim. Ama herkesin Tanrıdan aldığı ruhsal bir armağanı vardır; kiminin şöyle, kiminin böyle.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011422,68,46,7,8,'Yine de evli olmayanlarla dul kadınlara şunu söyleyeyim: Benim gibi kalsalar kendileri için iyi olur.'),
(2011423,68,46,7,9,'Ama kendilerini denetleyemiyorlarsa, evlensinler. Çünkü için için yanmaktansa evlenmek daha iyidir.'),
(2011424,68,46,7,10,'Evlilereyse şunu buyuruyorum, daha doğrusu Rab buyuruyor: Kadın kocasından ayrılmasın.'),
(2011425,68,46,7,11,'Ayrılırsa evlenmesin, ya da kocasıyla barışsın. Erkek de karısını boşamasın.'),
(2011426,68,46,7,12,'Geri kalanlara Rab değil, ben söylüyorum: Eğer bir kardeşin karısı iman etmemişse ama kendisiyle yaşamaya razıysa, onu boşamasın.'),
(2011427,68,46,7,13,'Bir kadının kocası iman etmemişse ama kendisiyle yaşamaya razıysa, kadın onu boşamasın.'),
(2011428,68,46,7,14,'Çünkü iman etmemiş koca karısı aracılığıyla, iman etmemiş kadın da imanlı kocası aracılığıyla kutsanır. Yoksa çocuklarınız murdar olurdu. Ama şimdi kutsaldırlar.'),
(2011429,68,46,7,15,'İman etmeyen ayrılırsa ayrılsın. Kardeş ya da kızkardeş böyle durumlarda özgürdür. Tanrı sizi barış içinde yaşamaya çağırdı.'),
(2011430,68,46,7,16,'Ey kadın, kocanı kurtarıp kurtaramayacağını nereden biliyorsun? Ey erkek, karını kurtarıp kurtaramayacağını nereden biliyorsun?'),
(2011431,68,46,7,17,'Ancak herkes Rabbin kendisi için belirlediği duruma uygun biçimde, Tanrıdan aldığı çağrıya göre yaşasın. Bunu bütün kiliselere buyuruyorum.'),
(2011432,68,46,7,18,'Biri sünnetliyken mi çağrıldı, sünnetsiz olmasın. Bir başkası sünnetsizken mi çağrıldı, sünnet olmasın.'),
(2011433,68,46,7,19,'Sünnetli olup olmamak önemli değildir. Önemli olan, Tanrının buyruklarını yerine getirmektir.'),
(2011434,68,46,7,20,'Herkes ne durumda çağrıldıysa, o durumda kalsın.'),
(2011435,68,46,7,21,'Köleyken mi çağrıldın, üzülme. Ama özgür olabilirsen, fırsatı kaçırma!'),
(2011436,68,46,7,22,'Çünkü Rabbin çağrısını aldığı zaman köle olan kimse, şimdi Rabbin özgürüdür. Özgürken çağrılan kişi de Mesihin kölesidir.'),
(2011437,68,46,7,23,'Bir bedel karşılığı satın alındınız, insanlara köle olmayın.'),
(2011438,68,46,7,24,'Kardeşler, herkes ne durumda çağrıldıysa, Tanrı önünde o durumda kalsın.'),
(2011439,68,46,7,25,'Kızlara gelince, Rabden onlarla ilgili bir buyruk almış değilim. Ama Rabbin merhameti sayesinde güvenilir biri olarak düşündüklerimi söylüyorum.'),
(2011440,68,46,7,26,'Öyle sanıyorum ki, şimdiki sıkıntılar nedeniyle insanın olduğu gibi kalması iyidir.'),
(2011441,68,46,7,27,'Karın varsa, boşanmayı isteme. Karın yoksa, kendine eş arama.'),
(2011442,68,46,7,28,'Ama evlenirsen günah işlemiş olmazsın. Bir kız da evlenirse günah işlemiş olmaz. Ne var ki, evlenenler bu yaşamda sıkıntılarla karşılaşacak. Ben sizi bu sıkıntılardan esirgemek istiyorum.'),
(2011443,68,46,7,29,'Kardeşler, şunu demek istiyorum: Zaman daralmıştır. Bundan böyle, karısı olanlar karıları yokmuş gibi, yas tutanlar yas tutmuyormuş gibi, sevinenler sevinmiyormuş gibi, mal alanlar malları yokmuş gibi, dünyadan yararlananlar alabildiğine yararlanmıyormuş gibi olsun. Çünkü dünyanın şimdiki hali geçicidir.'),
(2011444,68,46,7,32,'Kaygısız olmanızı istiyorum. Evli olmayan erkek, Rabbi nasıl hoşnut edeceğini düşünerek Rabbin işleri için kaygılanır.'),
(2011445,68,46,7,33,'Evli erkekse karısını nasıl hoşnut edeceğini düşünerek dünya işleri için kaygılanır.'),
(2011446,68,46,7,34,'Böylece ilgisi bölünür. Evli olmayan kadın ya da kız hem bedence hem ruhça kutsal olmak amacıyla Rabbin işleri için kaygılanır. Evli kadınsa kocasını nasıl hoşnut edeceğini düşünerek dünya işleri için kaygılanır.'),
(2011447,68,46,7,35,'Bunu sizin iyiliğiniz için söylüyorum, özgürlüğünüzü kısıtlamak için değil. İlginizi dağıtmadan, Rabbe adanmış olarak, Ona yaraşır biçimde yaşamanızı istiyorum.'),
(2011448,68,46,7,36,'Bir kimse nişanlı olduğu kıza yakışıksız davrandığını düşünüyorsa, aşırı tutkuları varsa ve evlenmesi gerekiyorsa, istediğini yapsın, günah işlemiş olmaz; evlensinler.'),
(2011449,68,46,7,37,'Ama zorunluluk altında bulunmayan, yüreği kararlı, istediğini yapabilecek durumdaki kişi, nişanlısıyla evlenmemeye yüreğinde karar vermişse, iyi eder.'),
(2011450,68,46,7,38,'Kısacası nişanlısıyla evlenen iyi eder, evlenmeyense daha iyi eder.'),
(2011451,68,46,7,39,'Kadın, kocası yaşadıkça kocasına bağlıdır. Kocası ölürse dilediği kimseyle evlenmekte özgürdür; yeter ki, o kişi Rabbe ait biri olsun.'),
(2011452,68,46,7,40,'Ama dul kadın, olduğu gibi kalırsa daha mutlu olur. Ben böyle düşünüyorum ve sanırım bende de Tanrı''nın Ruhu vardır.'),
(2011453,68,46,8,1,'Şimdi putlara sunulan kurbanların etine gelelim. ‹‹Hepimizin bilgisi var›› diyorsunuz, bunu biliyoruz. Bilgi insanı böbürlendirir, sevgiyse geliştirir.'),
(2011454,68,46,8,2,'Bir şey bildiğini sanan, henüz bilmesi gerektiği gibi bilmiyordur.'),
(2011455,68,46,8,3,'Ama Tanrıyı seveni Tanrı bilir.'),
(2011456,68,46,8,4,'Putlara sunulan kurban etinin yenmesine gelince, biliyoruz ki, ‹‹Dünyada put bir hiçtir›› ve ‹‹Birden fazla Tanrı yoktur››.'),
(2011457,68,46,8,5,'Yerde ya da gökte ilah diye adlandırılanlar varsa da -nitekim pekçok ‹‹ilah››, pekçok ‹‹rab›› vardır- bizim için tek bir Tanrı Baba vardır. O her şeyin kaynağıdır, bizler Onun için yaşıyoruz. Tek bir Rab var, O da İsa Mesihtir. Her şey Onun aracılığıyla yaratıldı, biz de Onun aracılığıyla yaşıyoruz.'),
(2011458,68,46,8,7,'Ne var ki, herkes bu bilgiye sahip değildir. Hâlâ putperest alışkanlıklarının etkisinde kalan bazıları, yedikleri etin puta sunulduğunu düşünüyorlar. Vicdanları zayıf olduğu için lekeleniyor.'),
(2011459,68,46,8,8,'Yiyecek bizi Tanrıya yaklaştırmaz. Yemezsek bir kaybımız olmaz, yersek de bir kazancımız olmaz.'),
(2011460,68,46,8,9,'Yalnız dikkat edin, bu özgürlüğünüz vicdanı zayıf olanların sürçmesine neden olmasın.'),
(2011461,68,46,8,10,'Eğer zayıf vicdanlı biri, bilgili olan seni bir put tapınağında sofraya oturmuş görürse, puta sunulan kurbanın etini yemek için cesaret almaz mı?'),
(2011462,68,46,8,11,'Sonuçta bu zayıf vicdanlı kişi, Mesihin uğruna öldüğü bu kardeş, senin bilgin yüzünden mahvolur!'),
(2011463,68,46,8,12,'Bu şekilde kardeşlere karşı günah işleyip onların zayıf vicdanlarını yaralayarak Mesihe karşı günah işlemiş olursunuz.'),
(2011464,68,46,8,13,'Bu nedenle, yediğim şey kardeşimin sendeleyip düşmesine yol açacaksa, kardeşimin düşmemesi için bir daha et yemeyeceğim.'),
(2011465,68,46,9,1,'Özgür değil miyim? Elçi değil miyim? Rabbimiz İsayı görmedim mi? Sizler Rab yolunda verdiğim emeğin ürünü değil misiniz?'),
(2011466,68,46,9,2,'Başkaları için elçi değilsem bile, sizler için elçiyim ya! Rab yolunda elçiliğimin kanıtı sizsiniz.'),
(2011467,68,46,9,3,'Beni sorguya çekenlere karşı kendimi böyle savunurum.'),
(2011468,68,46,9,4,'Yiyip içmeye hakkımız yok mu bizim?'),
(2011469,68,46,9,5,'Öbür elçiler gibi, Rabbin kardeşleri ve Kefas gibi, yanımızda imanlı bir eş gezdirmeye hakkımız yok mu?'),
(2011470,68,46,9,6,'Geçimi için çalışması gereken yalnız Barnabayla ben miyim?'),
(2011471,68,46,9,7,'Kim kendi parasıyla askerlik yapar? Kim bağ diker de ürününü yemez? Kim sürüyü güder de sütünden içmez?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011472,68,46,9,8,'İnsansal açıdan mı söylüyorum bunları? Kutsal Yasa da aynı şeyleri söylemiyor mu?'),
(2011473,68,46,9,9,'Musanın Yasasında, ‹‹Harman döven öküzün ağzını bağlamayacaksın›› diye yazılmıştır. Tanrının kaygısı öküzler mi, yoksa bunu özellikle bizim için mi söylüyor? Kuşkusuz, bizim için yazılmıştır bu. Çünkü çift sürenin umutla sürmesi, harman dövenin de harmana ortak olma umuduyla dövmesi gerekir.'),
(2011474,68,46,9,11,'Aranıza ruhsal tohumlar ektiysek, sizden maddesel bir harman biçmemiz çok mu?'),
(2011475,68,46,9,12,'Başkalarının sizden yardım almaya hakları varsa, bizim daha çok hakkımız yok mu? Ama biz bu hakkımızı kullanmadık. Mesih Müjdesinin yayılmasına engel olmayalım diye her şeye katlanıyoruz.'),
(2011476,68,46,9,13,'Tapınakta çalışanların tapınaktan beslendiklerini, sunakta görevli olanların da sunakta adanan adaklardan pay aldıklarını bilmiyor musunuz?'),
(2011477,68,46,9,14,'Bunun gibi, Rab Müjdeyi yayanların da geçimlerini Müjdeden sağlamasını buyurdu.'),
(2011478,68,46,9,15,'Ama ben bu haklardan hiçbirini kullanmış değilim. Bunlar bana sağlansın diye de yazmıyorum. Bunu yapmaktansa ölmeyi yeğlerim. Kimse beni bu övünçten yoksun bırakmayacaktır!'),
(2011479,68,46,9,16,'Müjdeyi yayıyorum diye övünmeye hakkım yok. Çünkü bunu yapmakla yükümlüyüm. Müjdeyi yaymazsam vay halime!'),
(2011480,68,46,9,17,'Eğer Müjdeyi gönülden yayarsam, ödülüm olur; gönülsüzce yayarsam, yalnızca bana emanet edilen görevi yapmış olurum.'),
(2011481,68,46,9,18,'Peki, ödülüm nedir? Müjdeyi karşılıksız yaymak ve böylece Müjdeyi yaymaktan doğan hakkımı kullanmamaktır.'),
(2011482,68,46,9,19,'Ben özgürüm, kimsenin kölesi değilim. Ama daha çok kişi kazanayım diye herkesin kölesi oldum.'),
(2011483,68,46,9,20,'Yahudileri kazanmak için Yahudilere Yahudi gibi davrandım. Kendim Kutsal Yasanın denetimi altında olmadığım halde, Yasa altında olanları kazanmak için onlara Yasa altındaymışım gibi davrandım.'),
(2011484,68,46,9,21,'Tanrının Yasasına sahip olmayan biri değilim, Mesihin Yasası altındayım. Buna karşın, Yasaya sahip olmayanları kazanmak için Yasaya sahip değilmişim gibi davrandım.'),
(2011485,68,46,9,22,'Güçsüzleri kazanmak için onlarla güçsüz oldum. Ne yapıp yapıp bazılarını kurtarmak için herkesle her şey oldum.'),
(2011486,68,46,9,23,'Bunların hepsini Müjdede payım olsun diye, Müjde uğruna yapıyorum.'),
(2011487,68,46,9,24,'Koşu alanında yarışanların hepsi koştuğu halde ödülü bir kişinin kazandığını bilmiyor musunuz? Öyle koşun ki ödülü kazanasınız.'),
(2011488,68,46,9,25,'Yarışa katılan herkes kendini her yönden denetler. Böyleleri bunu çürüyüp gidecek bir defne tacı kazanmak için yaparlar. Bizse hiç çürümeyecek bir taç için yapıyoruz.'),
(2011489,68,46,9,26,'Bunun içindir ki, amaçsızca koşan biri gibi koşmuyorum. Yumruğumu havayı döver gibi boşa atmıyorum.'),
(2011490,68,46,9,27,'Müjde''yi başkalarına duyurduktan sonra kendim reddedilmemek için bedenime eziyet çektirip onu köle ediyorum.'),
(2011491,68,46,10,1,'Kardeşler, atalarımızın hepsinin bulut altında korunduğunu ve hepsinin denizden geçtiğini bilmenizi istiyorum.'),
(2011492,68,46,10,2,'Musaya bağlanmak üzere hepsi bulutta ve denizde vaftiz edildi.'),
(2011493,68,46,10,3,'Hepsi aynı ruhsal yiyeceği yedi;'),
(2011494,68,46,10,4,'hepsi aynı ruhsal içeceği içti. Artlarından gelen ruhsal kayadan içtiler; o kaya Mesihti.'),
(2011495,68,46,10,5,'Ne var ki, Tanrı onların çoğundan hoşnut değildi; nitekim cesetleri çöle serildi.'),
(2011496,68,46,10,6,'Bu olaylar, onlar gibi kötü şeylere özlem duymamamız için bize ders olsun diye oldu.'),
(2011497,68,46,10,7,'Onlardan bazıları gibi puta tapanlar olmayın. Nitekim şöyle yazılmıştır: ‹‹Halk yiyip içmeye oturdu, sonra kalkıp çılgınca eğlendi.››'),
(2011498,68,46,10,8,'Onlardan bazıları gibi fuhuş yapmayalım. Fuhuş yapanların yirmi üç bini bir günde yok oldu.'),
(2011499,68,46,10,9,'Yine bazıları gibi Rabbi denemeyelim. Böyle yapanları yılanlar öldürdü.'),
(2011500,68,46,10,10,'Kimileri gibi de söylenip durmayın. Söylenenleri ölüm meleği öldürdü.'),
(2011501,68,46,10,11,'Bu olaylar başkalarına ders olsun diye onların başına geldi; çağların sonuna ulaşmış olan bizleri uyarmak için yazıya geçirildi.'),
(2011502,68,46,10,12,'Onun için, ayakta sağlam durduğunu sanan dikkat etsin, düşmesin!'),
(2011503,68,46,10,13,'Herkesin karşılaştığı denemelerden başka denemelerle karşılaşmadınız. Tanrı güvenilirdir, gücünüzü aşan biçimde denenmenize izin vermez. Dayanabilmeniz için denemeyle birlikte çıkış yolunu da sağlayacaktır.'),
(2011504,68,46,10,14,'Bu nedenle, sevgili kardeşlerim, putperestlikten kaçının.'),
(2011505,68,46,10,15,'Aklı başında insanlarla konuşur gibi konuşuyorum. Söylediklerimi kendiniz tartın.'),
(2011506,68,46,10,16,'Tanrıya şükrettiğimiz şükran kâsesiyle Mesihin kanına paydaş olmuyor muyuz? Bölüp yediğimiz ekmekle Mesihin bedenine paydaş olmuyor muyuz?'),
(2011507,68,46,10,17,'Ekmek bir olduğu gibi, biz de çok olduğumuz halde bir bedeniz. Çünkü hepimiz bir ekmeği paylaşıyoruz.'),
(2011508,68,46,10,18,'İsrail halkına bakın; kurban etini yiyenler sunağa paydaş değil midir?'),
(2011509,68,46,10,19,'Öyleyse ne demek istiyorum? Puta sunulan kurban etinin bir özelliği mi var? Ya da putun bir önemi mi var?'),
(2011510,68,46,10,20,'Hayır, yok! Dediğim şu: Putperestler kurbanlarını Tanrıya değil, cinlere sunuyorlar. Cinlerle paydaş olmanızı istemem.'),
(2011511,68,46,10,21,'Hem Rabbin, hem cinlerin kâsesinden içemezsiniz; hem Rabbin, hem cinlerin sofrasına ortak olamazsınız.'),
(2011512,68,46,10,22,'Yoksa Rabbi kıskandırmaya mı çalışıyoruz? Biz Ondan daha mı güçlüyüz?'),
(2011513,68,46,10,23,'‹‹Her şey serbest›› diyorsunuz, ama her şey yararlı değildir. ‹‹Her şey serbest›› diyorsunuz, ama her şey yapıcı değildir.'),
(2011514,68,46,10,24,'Herkes kendi yararını değil, başkalarının yararını gözetsin.'),
(2011515,68,46,10,25,'Kasaplar çarşısında satılan her eti vicdan sorunu yapmadan, sorgusuz sualsiz yiyin.'),
(2011516,68,46,10,26,'Çünkü ‹‹Yeryüzü ve içindeki her şey Rabbindir.››'),
(2011517,68,46,10,27,'İman etmemiş biri sizi yemeğe çağırır, siz de gitmek isterseniz, önünüze konulan her şeyi vicdan sorunu yapmadan, sorgusuz sualsiz yiyin.'),
(2011518,68,46,10,28,'Ama biri size, ‹‹Bu kurban etidir›› derse, hem bunu söyleyen için, hem de vicdan huzuru için yemeyin.'),
(2011519,68,46,10,29,'Senin değil, öbür adamın vicdan huzuru için demek istiyorum. Benim özgürlüğümü neden başkasının vicdanı yargılasın?'),
(2011520,68,46,10,30,'Şükrederek yemeğe katılırsam, şükrettiğim yiyecekten ötürü neden kınanayım?'),
(2011521,68,46,10,31,'Sonuç olarak, ne yer ne içerseniz, ne yaparsanız, her şeyi Tanrının yüceliği için yapın.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011522,68,46,10,32,'Yahudilerin, Greklerin ya da Tanrı topluluğunun tökezleyip düşmesine neden olmayın.'),
(2011523,68,46,10,33,'Ben de kendi yararımı değil, kurtulsunlar diye birçoklarının yararını gözeterek herkesi her yönden hoşnut etmeye çalışıyorum.'),
(2011524,68,46,11,1,'Mesihi örnek aldığım gibi, siz de beni örnek alın.'),
(2011525,68,46,11,2,'Her durumda beni anımsadığınız ve size ilettiğim öğretileri olduğu gibi koruduğunuz için sizi övüyorum.'),
(2011526,68,46,11,3,'Ama şunu da bilmenizi isterim: Her erkeğin başı Mesih, kadının başı erkek, Mesihin başı da Tanrıdır.'),
(2011527,68,46,11,4,'Başına bir şey takıp dua ya da peygamberlik eden her erkek, başını küçük düşürür.'),
(2011528,68,46,11,5,'Ama başı açık dua ya da peygamberlik eden her kadın, başını küçük düşürür. Böylesinin, başı tıraş edilmiş bir kadından farkı yoktur.'),
(2011529,68,46,11,6,'Kadın başını açarsa, saçını kestirsin. Ama kadının saçını kestirmesi ya da tıraş etmesi ayıpsa, başını örtsün.'),
(2011530,68,46,11,7,'Erkek başını örtmemeli; o, Tanrının benzeri ve yüceliğidir. Kadın da erkeğin yüceliğidir.'),
(2011531,68,46,11,8,'Çünkü erkek kadından değil, kadın erkekten yaratıldı.'),
(2011532,68,46,11,9,'Erkek kadın için değil, kadın erkek için yaratıldı.'),
(2011533,68,46,11,10,'Bu nedenle ve melekler uğruna kadının başı üzerinde yetkisi olmalıdır.'),
(2011534,68,46,11,11,'Ne var ki, Rabde ne kadın erkekten ne de erkek kadından bağımsızdır.'),
(2011535,68,46,11,12,'Çünkü kadın erkekten yaratıldığı gibi, erkek de kadından doğar. Ama her şey Tanrıdandır.'),
(2011536,68,46,11,13,'Siz kendiniz karar verin: Kadının açık başla Tanrıya dua etmesi uygun mu?'),
(2011537,68,46,11,14,'Doğanın kendisi bile size erkeğin uzun saçlı olmasının kendisini küçük düşürdüğünü, kadının uzun saçlı olmasının ise kendisini yücelttiğini öğretmiyor mu? Çünkü saç kadına örtü olarak verilmiştir.'),
(2011538,68,46,11,16,'Bu konuda çekişmek isteyen varsa, şunu bilsin ki, bizim ya da Tanrının kiliselerinin böyle bir alışkanlığı yoktur.'),
(2011539,68,46,11,17,'Toplantılarınız yarardan çok zarar getirdiği için aşağıdaki uyarıları yaparken sizi övemem.'),
(2011540,68,46,11,18,'Birincisi, toplulukça bir araya geldiğinizde aranızda ayrılıklar olduğunu duyuyorum. Buna biraz da inanıyorum.'),
(2011541,68,46,11,19,'Çünkü Tanrının beğenisini kazananların belli olması için aranızda bölünmeler olması gerekiyor!'),
(2011542,68,46,11,20,'Toplandığınızda Rabbin Sofrasına katılmak için toplanmıyorsunuz.'),
(2011543,68,46,11,21,'Her biriniz ötekini beklemeden kendi yemeğini yiyor. Kimi aç kalıyor, kimi sarhoş oluyor.'),
(2011544,68,46,11,22,'Yiyip içmek için evleriniz yok mu? Tanrının topluluğunu hor mu görüyorsunuz, yiyeceği olmayanları utandırmak mı istiyorsunuz? Size ne diyeyim? Sizi öveyim mi? Bu konuda övemem!'),
(2011545,68,46,11,23,'Size ilettiğimi ben Rabden öğrendim. Ele verildiği gece Rab İsa eline ekmek aldı, şükredip ekmeği böldü ve şöyle dedi: ‹‹Bu sizin uğrunuza feda edilen bedenimdir. Beni anmak için böyle yapın.››'),
(2011546,68,46,11,25,'Aynı biçimde yemekten sonra kâseyi alıp şöyle dedi: ‹‹Bu kâse kanımla gerçekleşen yeni antlaşmadır. Her içtiğinizde beni anmak için böyle yapın.››'),
(2011547,68,46,11,26,'Bu ekmeği her yediğinizde ve bu kâseden her içtiğinizde, Rabbin gelişine dek Rabbin ölümünü ilan etmiş olursunuz.'),
(2011548,68,46,11,27,'Bu nedenle kim uygun olmayan biçimde ekmeği yer ya da Rabbin kâsesinden içerse, Rabbin bedenine ve kanına karşı suç işlemiş olur.'),
(2011549,68,46,11,28,'Kişi önce kendini sınasın, sonra ekmekten yiyip kâseden içsin.'),
(2011550,68,46,11,29,'Çünkü bedeni farketmeden yiyip içen, böyle yiyip içmekle kendi kendini mahkûm eder.'),
(2011551,68,46,11,30,'İşte bu yüzden birçoğunuz zayıf ve hastadır, bazılarınız da ölmüştür.'),
(2011552,68,46,11,31,'Kendimizi doğrulukla yargılasaydık, yargılanmazdık.'),
(2011553,68,46,11,32,'Dünyayla birlikte mahkûm olmayalım diye Rab bizi yargılayıp terbiye ediyor.'),
(2011554,68,46,11,33,'Öyleyse kardeşlerim, yemek için bir araya geldiğinizde birbirinizi bekleyin.'),
(2011555,68,46,11,34,'Aç olan karnını evde doyursun. Öyle ki, toplanmanız yargılanmanıza yol açmasın. Öbür sorunları ise geldiğimde çözerim.'),
(2011556,68,46,12,1,'Ruhsal armağanlara gelince, kardeşlerim, bu konuda bilgisiz kalmanızı istemem.'),
(2011557,68,46,12,2,'Biliyorsunuz, putperestken şöyle ya da böyle saptırılıp dilsiz putlara tapmaya yöneltilmiştiniz.'),
(2011558,68,46,12,3,'Bunun için bilmenizi isterim ki: Tanrının Ruhu aracılığıyla konuşan hiç kimse, ‹‹İsaya lanet olsun!›› demez. Kutsal Ruhun aracılığı olmaksızın da kimse, ‹‹İsa Rabdir›› diyemez.'),
(2011559,68,46,12,4,'Çeşitli ruhsal armağanlar vardır, ama Ruh birdir.'),
(2011560,68,46,12,5,'Çeşitli görevler vardır, ama Rab birdir.'),
(2011561,68,46,12,6,'Çeşitli etkinlikler vardır, ama herkeste hepsini etkin kılan aynı Tanrıdır.'),
(2011562,68,46,12,7,'Herkesin ortak yararı için herkese Ruhu belli eden bir yetenek veriliyor.'),
(2011563,68,46,12,8,'Ruh aracılığıyla birine bilgece konuşma yeteneği, ötekine aynı Ruhtan bilgi iletme yeteneği, birine aynı Ruh aracılığıyla iman, ötekine aynı Ruh aracılığıyla hastaları iyileştirme armağanları, birine mucize yapma olanakları, birine peygamberlikte bulunma, birine ruhları ayırt etme, birine çeşitli dillerle konuşma, bir başkasına da bu dilleri çevirme armağanı veriliyor.'),
(2011564,68,46,12,11,'Bunların tümünü etkin kılan tek ve aynı Ruhtur. Ruh bunları herkese dilediği gibi, ayrı ayrı dağıtır.'),
(2011565,68,46,12,12,'Beden bir olmakla birlikte birçok üyeden oluşur ve çok sayıdaki bu üyelerin hepsi tek bir beden oluşturur. Mesih de böyledir.'),
(2011566,68,46,12,13,'İster Yahudi ister Grek, ister köle ister özgür olalım, hepimiz bir beden olmak üzere aynı Ruhta vaftiz edildik ve hepimizin aynı Ruhtan içmesi sağlandı.'),
(2011567,68,46,12,14,'İşte beden tek üyeden değil, birçok üyeden oluşur.'),
(2011568,68,46,12,15,'Ayak, ‹‹El olmadığım için bedene ait değilim›› derse, bu onu bedenden ayırmaz.'),
(2011569,68,46,12,16,'Kulak, ‹‹Göz olmadığım için bedene ait değilim›› derse, bu onu bedenden ayırmaz.'),
(2011570,68,46,12,17,'Bütün beden göz olsaydı, nasıl duyardık? Bütün beden kulak olsaydı, nasıl koklardık?'),
(2011571,68,46,12,18,'Gerçek şu ki, Tanrı bedenin her üyesini dilediği biçimde bedene yerleştirmiştir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011572,68,46,12,19,'Eğer hepsi bir tek üye olsaydı, beden olur muydu?'),
(2011573,68,46,12,20,'Gerçek şu ki, çok sayıda üye, ama tek beden vardır.'),
(2011574,68,46,12,21,'Göz ele, ‹‹Sana ihtiyacım yok!›› ya da baş ayaklara, ‹‹Size ihtiyacım yok!›› diyemez.'),
(2011575,68,46,12,22,'Tam tersine, bedenin daha zayıf görünen üyeleri vazgeçilmezdir.'),
(2011576,68,46,12,23,'Bedenin daha az değerli saydığımız üyelerine daha çok değer veririz. Böylece gösterişsiz üyelerimiz daha gösterişli olur.'),
(2011577,68,46,12,24,'Gösterişli üyelerimizin özene ihtiyacı yoktur. Ama Tanrı, değeri az olana daha çok değer vererek bedende birliği sağladı.'),
(2011578,68,46,12,25,'Öyle ki, bedende ayrılık olmasın, üyeler birbirini eşit biçimde gözetsin.'),
(2011579,68,46,12,26,'Bir üye acı çekerse, bütün üyeler birlikte acı çeker; bir üye yüceltilirse, bütün üyeler birlikte sevinir.'),
(2011580,68,46,12,27,'Sizler Mesihin bedenisiniz, bu bedenin ayrı ayrı üyelerisiniz.'),
(2011581,68,46,12,28,'Tanrı kilisede ilkin elçileri, ikinci olarak peygamberleri, üçüncü olarak öğretmenleri, sonra mucize yapanları, hastaları iyileştirme armağanlarına sahip olanları, başkalarına yardım edenleri, yönetme yeteneği olanları ve çeşitli dillerle konuşanları atadı.'),
(2011582,68,46,12,29,'Hepsi elçi mi? Hepsi peygamber mi? Hepsi öğretmen mi? Hepsi mucize yapar mı?'),
(2011583,68,46,12,30,'Hepsinin hastaları iyileştirme armağanları var mı? Hepsi bilmediği dilleri konuşabilir mi? Hepsi bu dilleri çevirebilir mi?'),
(2011584,68,46,12,31,'Ama siz daha üstün armağanları gayretle isteyin. Şimdi size en iyi yolu göstereyim.'),
(2011585,68,46,13,1,'İnsanların ve meleklerin diliyle konuşsam, ama sevgim olmasa, ses çıkaran bakırdan ya da çınlayan zilden farkım kalmaz.'),
(2011586,68,46,13,2,'Peygamberlikte bulunabilsem, bütün sırları bilsem, her bilgiye sahip olsam, dağları yerinden oynatacak kadar büyük imanım olsa, ama sevgim olmasa, bir hiçim.'),
(2011587,68,46,13,3,'Varımı yoğumu sadaka olarak dağıtsam, bedenimi yakılmak üzere teslim etsem, ama sevgim olmasa, bunun bana hiçbir yararı olmaz.'),
(2011588,68,46,13,4,'Sevgi sabırlıdır, sevgi şefkatlidir. Sevgi kıskanmaz, övünmez, böbürlenmez.'),
(2011589,68,46,13,5,'Sevgi kaba davranmaz, kendi çıkarını aramaz, kolay kolay öfkelenmez, kötülüğün hesabını tutmaz.'),
(2011590,68,46,13,6,'Sevgi haksızlığa sevinmez, gerçek olanla sevinir.'),
(2011591,68,46,13,7,'Sevgi her şeye katlanır, her şeye inanır, her şeyi umut eder, her şeye dayanır.'),
(2011592,68,46,13,8,'Sevgi asla son bulmaz. Ama peygamberlikler ortadan kalkacak, diller sona erecek, bilgi ortadan kalkacaktır.'),
(2011593,68,46,13,9,'Çünkü bilgimiz de peygamberliğimiz de sınırlıdır.'),
(2011594,68,46,13,10,'Ne var ki, yetkin olan geldiğinde sınırlı olan ortadan kalkacaktır.'),
(2011595,68,46,13,11,'Çocukken çocuk gibi konuşur, çocuk gibi anlar, çocuk gibi düşünürdüm. Yetişkin biri olunca çocukça davranışları bıraktım.'),
(2011596,68,46,13,12,'Şimdi her şeyi aynadaki silik görüntü gibi görüyoruz, ama o zaman yüz yüze görüşeceğiz. Şimdi bilgim sınırlıdır, ama o zaman bilindiğim gibi tam bileceğim.'),
(2011597,68,46,13,13,'İşte kalıcı olan üç şey vardır: İman, umut, sevgi. Bunların en üstünü de sevgidir.'),
(2011598,68,46,14,1,'Sevginin ardınca koşun ve ruhsal armağanları, özellikle peygamberlik yeteneğini gayretle isteyin.'),
(2011599,68,46,14,2,'Bilmediği dilde konuşan, insanlarla değil, Tanrıyla konuşur. Kimse onu anlamaz. O, ruhuyla sırlar söyler.'),
(2011600,68,46,14,3,'Peygamberlikte bulunansa insanların ruhça gelişmesi, cesaret ve teselli bulması için insanlara seslenir.'),
(2011601,68,46,14,4,'Bilmediği dilde konuşan kendi kendini geliştirir; ama peygamberlikte bulunan, inanlılar topluluğunu geliştirir.'),
(2011602,68,46,14,5,'Hepinizin dillerle konuşmasını isterim, ama peygamberlikte bulunmanızı yeğlerim. Diller inanlılar topluluğunun gelişmesi için çevrilmedikçe peygamberlikte bulunan, dillerle konuşandan üstündür.'),
(2011603,68,46,14,6,'Şimdi kardeşlerim, yanınıza gelip dillerle konuşsam, ama size bir vahiy, bir bilgi, bir peygamberlik sözü ya da bir öğreti getirmesem, size ne yararım olur?'),
(2011604,68,46,14,7,'Kaval ya da lir gibi ses veren cansız nesneler bile değişik sesler çıkarmasa, kaval mı, lir mi çalındığını kim anlar?'),
(2011605,68,46,14,8,'Borazan belirgin bir ses çıkarmasa, kim savaşa hazırlanır?'),
(2011606,68,46,14,9,'Bunun gibi, siz de anlaşılır bir dil konuşmazsanız, söyledikleriniz nasıl anlaşılır? Havaya konuşmuş olursunuz!'),
(2011607,68,46,14,10,'Kuşkusuz dünyada çeşit çeşit diller vardır, hiçbiri de anlamsız değildir.'),
(2011608,68,46,14,11,'Ne var ki, konuşulan dili anlamazsam, ben konuşana yabancı olurum, konuşan da bana yabancı olur.'),
(2011609,68,46,14,12,'Bu nedenle, siz de ruhsal armağanlara heveslendiğinize göre, inanlılar topluluğunu geliştiren ruhsal armağanlar bakımından zenginleşmeye bakın.'),
(2011610,68,46,14,13,'Bunun için, bilmediği dili konuşan, kendi söylediklerini çevirebilmek için dua etsin.'),
(2011611,68,46,14,14,'Bilmediğim dille dua edersem ruhum dua eder, ama zihnimin buna katkısı olmaz.'),
(2011612,68,46,14,15,'Öyleyse ne yapmalıyım? Ruhumla da zihnimle de dua edeceğim. Ruhumla da zihnimle de ilahi söyleyeceğim.'),
(2011613,68,46,14,16,'Tanrıyı yalnız ruhunla översen, yeni katılanlar senin ne söylediğini bilmediğinden, ettiğin şükran duasına nasıl ‹‹Amin!›› desin?'),
(2011614,68,46,14,17,'Uygun biçimde şükrediyor olabilirsin, ama bu başkasını geliştirmez.'),
(2011615,68,46,14,18,'Dillerle hepinizden çok konuştuğum için Tanrıya şükrediyorum.'),
(2011616,68,46,14,19,'Ama inanlılar topluluğunda dillerle on bin söz söylemektense, başkalarını eğitmek için zihnimden beş söz söylemeyi yeğlerim.'),
(2011617,68,46,14,20,'Kardeşler, çocuk gibi düşünmeyin. Kötülük konusunda çocuklar gibi, ama düşünmekte yetişkinler gibi olun.'),
(2011618,68,46,14,21,'Kutsal Yasada şöyle yazılmıştır: ‹‹Rab, ‹Yabancı diller konuşanların aracılığıyla, Yabancıların dudaklarıyla bu halka sesleneceğim; Yine de beni dinlemeyecekler!› diyor.››'),
(2011619,68,46,14,22,'Görülüyor ki, bilinmeyen diller imanlılar için değil, imansızlar için bir belirtidir. Peygamberlikse imansızlar için değil, imanlılar için bir belirtidir.'),
(2011620,68,46,14,23,'Şimdi bütün inanlılar topluluğu bir araya gelip hep birlikte bilmedikleri dillerle konuşurlarken yeni katılanlar ya da iman etmeyenler içeri girerse, ‹‹Siz çıldırmışsınız!›› demezler mi?'),
(2011621,68,46,14,24,'Ama herkes peygamberlikte bulunurken iman etmeyen ya da yeni katılan biri içeri girerse, söylenen her sözle günahlı olduğuna ikna edilecek, her sözle yargılanacak.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011622,68,46,14,25,'Yüreğindeki gizli düşünceler açığa çıkacak ve, ‹‹Tanrı gerçekten aranızdadır!›› diyerek yüzüstü yere kapanıp Tanrıya tapınacaktır.'),
(2011623,68,46,14,26,'Öyleyse ne diyelim, kardeşler? Toplandığınızda her birinizin bir ilahisi, öğretecek bir konusu, bir vahyi, bilmediği dilde söyleyecek bir sözü ya da bir çevirisi vardır. Her şey topluluğun gelişmesi için olsun.'),
(2011624,68,46,14,27,'Eğer bilinmeyen dillerle konuşulacaksa, iki ya da en çok üç kişi sırayla konuşsun, biri de söylenenleri çevirsin.'),
(2011625,68,46,14,28,'Çeviri yapacak biri yoksa, bilmediği dilde konuşan, toplulukta sessiz kalsın, içinden Tanrıyla konuşsun.'),
(2011626,68,46,14,29,'İki ya da üç peygamber konuşsun, öbürleri söylenenleri iyice düşünüp tartsın.'),
(2011627,68,46,14,30,'Toplantıda oturanlardan birine vahiy gelirse, konuşmakta olan sussun.'),
(2011628,68,46,14,31,'Herkesin öğrenmesi ve cesaret bulması için hepiniz teker teker peygamberlikte bulunabilirsiniz.'),
(2011629,68,46,14,32,'Peygamberlerin ruhları peygamberlerin denetimi altındadır.'),
(2011630,68,46,14,33,'Çünkü Tanrı karışıklık değil, esenlik Tanrısıdır. Kutsalların bütün topluluklarında böyledir.'),
(2011631,68,46,14,34,'Kadınlar toplantılarınızda sessiz kalsın. Konuşmalarına izin yoktur. Kutsal Yasanın da belirttiği gibi, uysal olsunlar.'),
(2011632,68,46,14,35,'Öğrenmek istedikleri bir şey varsa, evde kocalarına sorsunlar. Çünkü kadının toplantı sırasında konuşması ayıptır.'),
(2011633,68,46,14,36,'Tanrının sözü sizden mi kaynaklandı, ya da yalnız size mi ulaştı?'),
(2011634,68,46,14,37,'Kendini peygamber ya da ruhça olgun sayan varsa, bilsin ki, size yazdıklarım Rabbin buyruğudur.'),
(2011635,68,46,14,38,'Bunları önemsemeyenin kendisi de önemsenmesin.'),
(2011636,68,46,14,39,'Özet olarak, kardeşlerim, peygamberlikte bulunmayı gayretle isteyin, bilinmeyen dillerle konuşulmasına engel olmayın. Ancak her şey uygun ve düzenli biçimde yapılsın.'),
(2011637,68,46,15,1,'Şimdi, kardeşler, size bildirdiğim, sizin de kabul edip bağlı kaldığınız Müjdeyi anımsatmak istiyorum.'),
(2011638,68,46,15,2,'Size müjdelediğim söze sımsıkı sarılırsanız, onun aracılığıyla kurtulursunuz. Yoksa boşuna iman etmiş olursunuz.'),
(2011639,68,46,15,3,'Aldığım bilgiyi size öncelikle ilettim: Kutsal Yazılar uyarınca Mesih günahlarımıza karşılık öldü, gömüldü ve Kutsal Yazılar uyarınca üçüncü gün ölümden dirildi.'),
(2011640,68,46,15,5,'Kefasa, sonra Onikilere göründü.'),
(2011641,68,46,15,6,'Daha sonra da beş yüzden çok kardeşe aynı anda göründü. Bunların çoğu hâlâ yaşıyor, bazılarıysa öldüler.'),
(2011642,68,46,15,7,'Bundan sonra Yakupa, sonra bütün elçilere, son olarak zamansız doğmuş bir çocuğa benzeyen bana da göründü.'),
(2011643,68,46,15,9,'Ben elçilerin en önemsiziyim. Tanrının kilisesine zulmettiğim için elçi olarak anılmaya bile layık değilim.'),
(2011644,68,46,15,10,'Ama şimdi neysem, Tanrının lütfuyla öyleyim. Onun bana olan lütfu boşa gitmedi. Elçilerin hepsinden çok emek verdim. Aslında ben değil, Tanrının bende olan lütfu emek verdi.'),
(2011645,68,46,15,11,'İşte, gerek benim yaydığım, gerek öbür elçilerin yaydığı ve sizin de iman ettiğiniz bildiri budur.'),
(2011646,68,46,15,12,'Eğer Mesihin ölümden dirildiği duyuruluyorsa, nasıl oluyor da aranızda bazıları ölüler dirilmez diyor?'),
(2011647,68,46,15,13,'Ölüler dirilmezse, Mesih de dirilmemiştir.'),
(2011648,68,46,15,14,'Mesih dirilmemişse, bildirimiz de imanınız da boştur.'),
(2011649,68,46,15,15,'Bu durumda Tanrıyla ilgili tanıklığımız da yalan demektir. Çünkü Tanrının, Mesihi dirilttiğine tanıklık ettik. Ama ölüler gerçekten dirilmezse, Tanrı Mesihi de diriltmemiştir.'),
(2011650,68,46,15,16,'Ölüler dirilmezse, Mesih de dirilmemiştir.'),
(2011651,68,46,15,17,'Mesih dirilmemişse imanınız yararsızdır, siz de hâlâ günahlarınızın içindesiniz.'),
(2011652,68,46,15,18,'Buna göre Mesihe ait olarak ölmüş olanlar da mahvolmuşlardır.'),
(2011653,68,46,15,19,'Eğer yalnız bu yaşam için Mesihe umut bağlamışsak, herkesten çok acınacak durumdayız.'),
(2011654,68,46,15,20,'Oysa Mesih, ölmüş olanların ilk örneği olarak ölümden dirilmiştir.'),
(2011655,68,46,15,21,'Ölüm bir insan aracılığıyla geldiğine göre, ölümden diriliş de bir insan aracılığıyla gelir.'),
(2011656,68,46,15,22,'Herkes nasıl Ademde ölüyorsa, herkes Mesihte yaşama kavuşacak.'),
(2011657,68,46,15,23,'Her biri sırası gelince dirilecek: İlk örnek olarak Mesih, sonra Mesihin gelişinde Mesihe ait olanlar.'),
(2011658,68,46,15,24,'Bundan sonra Mesih her yönetimi, her hükümranlığı, her gücü ortadan kaldırıp egemenliği Baba Tanrıya teslim ettiği zaman son gelmiş olacak.'),
(2011659,68,46,15,25,'Çünkü Tanrı bütün düşmanlarını ayakları altına serinceye dek Onun egemenlik sürmesi gerekir.'),
(2011660,68,46,15,26,'Ortadan kaldırılacak son düşman ölümdür.'),
(2011661,68,46,15,27,'Çünkü, ‹‹Tanrı her şeyi Mesihin ayakları altına sererek Ona bağımlı kıldı.›› ‹‹Her şey Ona bağımlı kılındı›› sözünün, her şeyi Mesihe bağımlı kılan Tanrıyı içermediği açıktır.'),
(2011662,68,46,15,28,'Her şey Oğula bağımlı kılınınca, Oğul da her şeyi kendisine bağımlı kılan Tanrıya bağımlı olacaktır. Öyle ki, Tanrı her şeyde her şey olsun.'),
(2011663,68,46,15,29,'Diriliş yoksa, ölüler için vaftiz edilenler ne olacak? Ölüler gerçekten dirilmeyecekse, insanlar neden ölüler için vaftiz ediliyorlar?'),
(2011664,68,46,15,30,'Biz de neden her saat kendimizi tehlikeye atıyoruz?'),
(2011665,68,46,15,31,'Kardeşler, sizinle ilgili olarak Rabbimiz Mesih İsada sahip olduğum övüncün hakkı için her gün ölüyorum.'),
(2011666,68,46,15,32,'Eğer insansal nedenlerle Efeste canavarlarla dövüştümse, bunun bana yararı ne? Eğer ölüler dirilmeyecekse, ‹‹Yiyelim içelim, nasıl olsa yarın öleceğiz.››'),
(2011667,68,46,15,33,'Aldanmayın, ‹‹Kötü arkadaşlıklar iyi huyu bozar.››'),
(2011668,68,46,15,34,'Uslanıp kendinize gelin, artık günah işlemeyin. Bazılarınız Tanrıyı hiç tanımıyor. Utanasınız diye söylüyorum bunları.'),
(2011669,68,46,15,35,'Ama biri çıkıp, ‹‹Ölüler nasıl dirilecek? Nasıl bir bedenle gelecekler?›› diye sorabilir.'),
(2011670,68,46,15,36,'Ne akılsızca bir soru! Ektiğin tohum ölmedikçe yaşama kavuşmaz ki!'),
(2011671,68,46,15,37,'Ekerken, oluşacak bitkinin kendisini değil, yalnızca tohumunu -buğday ya da başka bir bitkinin tohumunu- ekersin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011672,68,46,15,38,'Tanrı tohuma dilediği bedeni -her birine kendine özgü bedeni- verir.'),
(2011673,68,46,15,39,'Her canlının eti aynı değildir. İnsan eti başka, hayvan eti başka, kuş eti, balık eti başka başkadır.'),
(2011674,68,46,15,40,'Göksel bedenler vardır, dünyasal bedenler vardır. Göksel olanların görkemi başka, dünyasal olanlarınki başkadır.'),
(2011675,68,46,15,41,'Güneşin görkemi başka, ayın görkemi başka, yıldızların görkemi başkadır. Görkem bakımından yıldız yıldızdan farklıdır.'),
(2011676,68,46,15,42,'Ölülerin dirilişi de böyledir. Beden çürümeye mahkûm olarak gömülür, çürümez olarak diriltilir.'),
(2011677,68,46,15,43,'Düşkün olarak gömülür, görkemli olarak diriltilir. Zayıf olarak gömülür, güçlü olarak diriltilir.'),
(2011678,68,46,15,44,'Doğal beden olarak gömülür, ruhsal beden olarak diriltilir. Doğal beden olduğu gibi, ruhsal beden de vardır.'),
(2011679,68,46,15,45,'Nitekim şöyle yazılmıştır: ‹‹İlk insan Adem yaşayan can oldu.›› Son Ademse yaşam veren ruh oldu.'),
(2011680,68,46,15,46,'Önce ruhsal olan değil, doğal olan geldi. Ruhsal olan sonra geldi.'),
(2011681,68,46,15,47,'İlk insan yerden, yani topraktandır. İkinci insan göktendir.'),
(2011682,68,46,15,48,'Topraktan olan insan nasılsa, topraktan olanlar da öyledir. Göksel insan nasılsa, göksel olanlar da öyledir.'),
(2011683,68,46,15,49,'Bizler topraktan olana nasıl benzediysek, göksel olana da benzeyeceğiz.'),
(2011684,68,46,15,50,'Kardeşler, şunu demek istiyorum, et ve kan Tanrının Egemenliğini miras alamaz. Çürüyen de çürümezliği miras alamaz.'),
(2011685,68,46,15,51,'İşte size bir sır açıklıyorum. Hepimiz ölmeyeceğiz; son borazan çalınınca hepimiz bir anda, göz açıp kapayana dek değiştirileceğiz. Evet, borazan çalınacak, ölüler çürümez olarak dirilecek, ve biz de değiştirileceğiz.'),
(2011686,68,46,15,53,'Çünkü bu çürüyen beden çürümezliği, bu ölümlü beden ölümsüzlüğü giyinmelidir.'),
(2011687,68,46,15,54,'Çürüyen ve ölümlü beden çürümezliği ve ölümsüzlüğü giyinince, ‹‹Ölüm yok edildi, zafer kazanıldı!›› diye yazılmış olan söz yerine gelecektir.'),
(2011688,68,46,15,55,'‹‹Ey ölüm, zaferin nerede? Ey ölüm, dikenin nerede?››'),
(2011689,68,46,15,56,'Ölümün dikeni günahtır. Günah ise gücünü Kutsal Yasadan alır.'),
(2011690,68,46,15,57,'Rabbimiz İsa Mesih aracılığıyla bizi zafere ulaştıran Tanrıya şükürler olsun!'),
(2011691,68,46,15,58,'Bu nedenle, sevgili kardeşlerim, Rab yolunda verdiğiniz emeğin boşa gitmeyeceğini bilerek dayanın, sarsılmayın, Rab''bin işinde her zaman gayretli olun.'),
(2011692,68,46,16,1,'Kutsallara yapılacak para yardımına gelince: Galatya kiliselerine ne buyurduysam, siz de öyle yapın.'),
(2011693,68,46,16,2,'Haftanın ilk günü herkes kazancına göre bir miktar para ayırıp biriktirsin. Öyle ki, yanınıza geldiğimde para toplamaya gerek kalmasın.'),
(2011694,68,46,16,3,'Oraya vardığımda, bağışlarınızı götürmek üzere uygun gördüğünüz kişileri tanıtıcı mektuplarla Yeruşalime göndereceğim.'),
(2011695,68,46,16,4,'Benim de gitmeme değerse, onları yanıma alıp gideceğim.'),
(2011696,68,46,16,5,'Makedonyadan geçtikten sonra yanınıza geleceğim. Çünkü Makedonyadan geçmek niyetindeyim.'),
(2011697,68,46,16,6,'Belki bir süre yanınızda kalırım, hatta kışı da sizinle geçirebilirim. Öyle ki, sonra nereye gidecek olsam, bana yardım edebilesiniz.'),
(2011698,68,46,16,7,'Sizi öyle kısaca görüp geçmek istemiyorum. Rabbin izniyle uzunca bir süre yanınızda kalmayı umut ediyorum.'),
(2011699,68,46,16,8,'Ama Pentikost Gününe dek Efeste kalacağım.'),
(2011700,68,46,16,9,'Çünkü büyük ve etkili işler yapmam için burada bana bir kapı açıldı. Ne var ki, bana karşı çıkanlar çoktur.'),
(2011701,68,46,16,10,'Timoteos yanınıza gelirse, bir şeyden korkmamasına dikkat edin. Çünkü o da benim gibi Rabbin işini yapıyor.'),
(2011702,68,46,16,11,'Kimse onu hor görmesin. Yanıma gelmesi için onu esenlikle uğurlayın. Kardeşlerle birlikte onun da gelmesini bekliyorum.'),
(2011703,68,46,16,12,'Kardeşimiz Apollosa gelince, kardeşlerle birlikte size gelmesi için ona çok ricada bulundum, ama şimdilik gelmeye hiç de istekli değil. Fırsat bulunca gelecek.'),
(2011704,68,46,16,13,'Uyanık kalın, imanda dimdik durun, mert ve güçlü olun.'),
(2011705,68,46,16,14,'Her şeyi sevgiyle yapın.'),
(2011706,68,46,16,15,'Ahayada ilk iman eden ve kendilerini kutsalların hizmetine adayan İstefanasın ev halkını bilirsiniz. Kardeşler, size yalvarırım, bu gibilere ve onlarla birlikte çalışıp emek verenlerin hepsine bağımlı olun.'),
(2011707,68,46,16,17,'İstefanas, Fortunatus ve Ahaykosun gelişine sevindim. Yokluğunuzu bana unutturdular.'),
(2011708,68,46,16,18,'Sizin ruhunuzu da benim ruhumu da ferahlattılar. Böylelerinin değerini bilin.'),
(2011709,68,46,16,19,'Asya İlindeki kiliseler size selam eder. Akvila ve Priska, evlerinde buluşan toplulukla birlikte Rabde size çok selam ederler.'),
(2011710,68,46,16,20,'Buradaki bütün kardeşlerin size selamı var. Birbirinizi kutsal öpüşle selamlayın.'),
(2011711,68,46,16,21,'Ben Pavlus, bu selamı kendi elimle yazıyorum.'),
(2011712,68,46,16,22,'Rabbi sevmeyene lanet olsun. Maranata!'),
(2011713,68,46,16,23,'Rab İsanın lütfu sizinle birlikte olsun.'),
(2011714,68,46,16,24,'Hepinize Mesih İsa''da sevgiler! Amin. Revision'),
(2011715,68,47,1,1,'Tanrının isteğiyle Mesih İsanın elçisi atanan ben Pavlus ve kardeşimiz Timoteostan Ahayanın her yanındaki bütün kutsallara ve Tanrının Korintteki kilisesine selam!'),
(2011716,68,47,1,2,'Babamız Tanrıdan ve Rab İsa Mesihten sizlere lütuf ve esenlik olsun.'),
(2011717,68,47,1,3,'Her türlü tesellinin kaynağı olan Tanrıya, merhametli Babaya, Rabbimiz İsa Mesihin Tanrısı ve Babasına övgüler olsun!'),
(2011718,68,47,1,4,'Kendisinden aldığımız teselliyle her türlü sıkıntıda olanları teselli edebilmemiz için bizi bütün sıkıntılarımızda teselli ediyor.'),
(2011719,68,47,1,5,'Çünkü Mesihin acılarını nasıl büyük ölçüde çekiyorsak, Mesih sayesinde büyük teselli de buluyoruz.'),
(2011720,68,47,1,6,'Sıkıntı çekiyorsak, bu sizin teselliniz ve kurtuluşunuz içindir. Teselli buluyorsak bu, bizim çektiğimiz acıların aynısına dayanmanızda etkin olan bir teselli bulmanız içindir.'),
(2011721,68,47,1,7,'Size ilişkin umudumuz sarsılmaz. Çünkü acılarımıza olduğu gibi, tesellimize de ortak olduğunuzu biliyoruz.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011722,68,47,1,8,'Kardeşlerim, Asya İlinde çektiğimiz sıkıntılardan habersiz kalmanızı istemiyoruz. Dayanabileceğimizden çok ağır bir yük altındaydık. Öyle ki, yaşamaktan bile umudumuzu kesmiştik.'),
(2011723,68,47,1,9,'Ölüme mahkûm olduğumuzu içimizde hissettik. Ama bu, kendimize değil, ölüleri dirilten Tanrıya güvenmemiz için oldu.'),
(2011724,68,47,1,10,'Tanrı bizi böylesine büyük bir ölüm tehlikesinden kurtardı; daha da kurtaracaktır. Umudumuzu Ona bağladık. Siz de dualarınızla bize yardım ettikçe, bizi yine kurtaracaktır. Öyle ki, birçok kişinin dualarıyla bize sağlanan lütuftan ötürü birçoklarının ağzından bizim için şükranlar sunulsun.'),
(2011725,68,47,1,12,'Dünyaya ve özellikle size, insan bilgeliğiyle değil, Tanrının lütfuyla, Tanrıdan gelen kutsallık ve içtenlikle davrandığımıza vicdanımız tanıktır. Ve biz bununla övünüyoruz.'),
(2011726,68,47,1,13,'Okuyup anlayabileceğinizden başka bir şey yazmıyoruz. Bizi bir ölçüde anladığınız gibi, tümüyle anlayacağınızı umarım. Rabbimiz İsanın gününde bizim övüncümüz siz olacağınız gibi, sizin övüncünüz de biz olalım.'),
(2011727,68,47,1,15,'Bu güvenle, sizleri iki kez sevindirmek için önce size uğramak, sonra Makedonyaya geçmek, Makedonyadan yine size geri gelerek tarafınızdan Yahudiyeye uğurlanmak niyetindeydim.'),
(2011728,68,47,1,17,'Bunu isterken acaba kararsız mıydım? Ya da isteklerim benlikten mi doğuyor ki, önce ‹‹Evet, evet››, sonra ‹‹Hayır, hayır›› diyeyim?'),
(2011729,68,47,1,18,'Tanrının güvenilirliği hakkı için diyorum ki, size ilettiğimiz söz hem ‹‹evet›› hem ‹‹hayır›› değildir.'),
(2011730,68,47,1,19,'Silvanus ve Timoteosla birlikte size tanıttığımız Tanrının Oğlu İsa Mesih hem ‹‹evet›› hem ‹‹hayır›› değildi. Onda yalnız ‹‹evet›› vardır.'),
(2011731,68,47,1,20,'Çünkü Tanrının bütün vaatleri Mesihte ‹‹evet››tir. Bu nedenle Tanrının yüceliği için Mesih aracılığıyla Tanrıya ‹‹Amin›› deriz.'),
(2011732,68,47,1,21,'Bizi sizinle birlikte Mesihte pekiştiren ve meshetmiş olan Tanrıdır.'),
(2011733,68,47,1,22,'O bizi mühürledi, güvence olarak da yüreklerimize Kutsal Ruhu yerleştirdi.'),
(2011734,68,47,1,23,'Tanrıyı tanık tutarım ki, Korinte dönmeyişimin nedeni sizi esirgemekti.'),
(2011735,68,47,1,24,'İmanınıza egemen olmak istemiyoruz, sevinmeniz için sizinle birlikte çalışıyoruz. Çünkü imanda dimdik duruyorsunuz.'),
(2011736,68,47,2,1,'Size tekrar keder dolu bir ziyaret yapmamaya karar verdim.'),
(2011737,68,47,2,2,'Çünkü sizi kederlendirirsem, keder verdiğim sizlerden başka beni kim sevindirecek?'),
(2011738,68,47,2,3,'Bunu yazdım ki, geldiğimde beni sevindirmesi gerekenler beni kederlendirmesin. Sevincimin hepinizin sevinci olduğuna ilişkin hepinize güvenim var.'),
(2011739,68,47,2,4,'Kederlenesiniz diye değil, size beslediğim derin sevgiyi anlayasınız diye büyük bir sıkıntı ve yürek acısıyla gözyaşları içinde size yazdım.'),
(2011740,68,47,2,5,'Eğer biri bir başkasını kederlendirdiyse, beni değil -abartmadan söyleyeyim- bir dereceye kadar hepinizi kederlendirmiş olur.'),
(2011741,68,47,2,6,'Böyle birine çoğunluğun verdiği bu ceza yeterlidir.'),
(2011742,68,47,2,7,'Aşırı kedere boğulmasın diye o kişiyi daha fazla cezalandırmayıp bağışlamalı ve teselli etmelisiniz.'),
(2011743,68,47,2,8,'Bunun için ona duyduğunuz sevgiyi yenilemenizi rica ederim.'),
(2011744,68,47,2,9,'Sizi sınamak ve her durumda söz dinleyenler olup olmadığınızı anlamak için yazdım size.'),
(2011745,68,47,2,10,'Kimi bağışlarsanız, ben de onu bağışlarım. Eğer bir şeyi bağışladımsa, bunu sizin için Mesihin önünde bağışladım.'),
(2011746,68,47,2,11,'Öyle ki, Şeytanın oyununa gelmeyelim. Çünkü onun düzenlerini bilmez değiliz.'),
(2011747,68,47,2,12,'Mesihin Müjdesini yaymak amacıyla Troasa geldiğimde Rabbin işi için bana bir kapı açıldığı halde, kardeşim Titusu orada bulamadığım için iç huzurum yoktu. Bu nedenle oradakilere veda ederek Makedonyaya gittim.'),
(2011748,68,47,2,14,'Bizi her zaman Mesihin zafer alayında yürüten, Onu tanımanın güzel kokusunu aracılığımızla her yerde yayan Tanrıya şükürler olsun!'),
(2011749,68,47,2,15,'Çünkü biz hem kurtulanlar hem de mahvolanlar arasında Tanrı için Mesihin güzel kokusuyuz.'),
(2011750,68,47,2,16,'Mahvolanlar için ölüme götüren ölüm kokusu, kurtulanlar içinse yaşama götüren yaşam kokusuyuz. Böylesi bir işe kim yeterlidir?'),
(2011751,68,47,2,17,'Birçokları gibi, Tanrı''nın sözünü ticaret aracı yapanlar değiliz. Tanrı tarafından gönderilen ve Mesih''e ait olan kişiler olarak Tanrı''nın önünde içtenlikle konuşuyoruz.'),
(2011752,68,47,3,1,'Kendimizi yine tavsiye etmeye mi başlıyoruz? Yoksa bazıları gibi size ya da sizden tavsiye mektuplarına ihtiyacımız mı var?'),
(2011753,68,47,3,2,'Bütün insanlarca bilinen ve okunan, yüreklerimize yazılmış mektubumuz sizsiniz.'),
(2011754,68,47,3,3,'Hizmetimizin sonucu olup mürekkeple değil, yaşayan Tanrının Ruhuyla, taş levhalara değil, insan yüreğinin levhalarına yazılmış Mesihin mektubu olduğunuz açıktır.'),
(2011755,68,47,3,4,'Mesih sayesinde Tanrıya böyle bir güvenimiz vardır.'),
(2011756,68,47,3,5,'Herhangi bir şeyi kendi başarımız olarak saymaya yeterliyiz demek istemiyorum; bizi yeterli kılan Tanrıdır.'),
(2011757,68,47,3,6,'O bizi yazılı yasaya değil, Ruha dayalı yeni bir antlaşmanın hizmetkârları olmaya yeterli kıldı. Yazılı yasa öldürür, Ruh ise yaşatır.'),
(2011758,68,47,3,7,'Ölümle sonuçlanan hizmet, yani taş üzerine harf harf kazılan yasa yücelik içinde geldiyse -öyle ki, İsrailoğulları geçici olan parlaklığından ötürü Musanın yüzüne bakamadılar- Ruha dayalı hizmetin yücelik içinde olacağı daha kesin değil mi?'),
(2011759,68,47,3,9,'İnsanı suçlu çıkaran hizmetin yüceliği varsa, aklanmayı sağlayan hizmetin yüceliği çok daha aşkındır.'),
(2011760,68,47,3,10,'Çünkü eskiden yüceltilmiş olanın, şimdi yücelikte aşkın olana göre yüceliği yoktur.'),
(2011761,68,47,3,11,'Geçici olan, yücelik içinde geldiyse, kalıcı olanın yüceliği çok daha büyüktür.'),
(2011762,68,47,3,12,'Böyle bir umuda sahip olduğumuz için büyük cesaretle konuşabiliriz.'),
(2011763,68,47,3,13,'Yüzündeki parlaklığın giderek söndüğünü İsrailoğulları görmesin diye yüzünü peçeyle örten Musa gibi değiliz.'),
(2011764,68,47,3,14,'İsrailoğullarının zihinleri körelmişti. Bugün bile Eski Antlaşma okunurken zihinleri aynı peçeyle örtülü kalıyor. Çünkü bu peçe ancak Mesih aracılığıyla kalkar.'),
(2011765,68,47,3,15,'Ne var ki, bugün bile Musanın yazıları okunduğunda yüreklerini bir peçe örtüyor.'),
(2011766,68,47,3,16,'Oysa ne zaman biri Rabbe dönerse, o peçe kaldırılır.'),
(2011767,68,47,3,17,'Rab Ruhtur, Rabbin Ruhu neredeyse orada özgürlük vardır.'),
(2011768,68,47,3,18,'Ve biz hepimiz peçesiz yüzle Rab''bin yüceliğini görerek yücelik üstüne yücelikle O''na benzer olmak üzere değiştiriliyoruz. Bu da Ruh olan Rab sayesinde oluyor.'),
(2011769,68,47,4,1,'Bu hizmeti Tanrının merhametiyle üstlendiğimiz için cesaretimizi yitirmeyiz.'),
(2011770,68,47,4,2,'Utanç verici gizli yolları reddettik. Hileye başvurmayız, Tanrının sözünü de çarpıtmayız. Gerçeği ortaya koyarak kendimizi Tanrının önünde her insanın vicdanına tavsiye ederiz.'),
(2011771,68,47,4,3,'Yaydığımız Müjde örtülüyse de, mahvolanlar için örtülüdür.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011772,68,47,4,4,'Tanrının görünümü olan Mesihin yüceliğiyle ilgili Müjdenin ışığı imansızların üzerine doğmasın diye, bu çağın ilahı onların zihinlerini kör etmiştir.'),
(2011773,68,47,4,5,'Biz kendimizi ilan etmiyoruz; ama Mesih İsayı Rab, kendimizi de İsa uğruna kullarınız ilan ediyoruz.'),
(2011774,68,47,4,6,'Çünkü, ‹‹Işık karanlıktan parlayacak›› diyen Tanrı, İsa Mesihin yüzünde parlayan kendi yüceliğini tanımamızdan doğan ışığı bize vermek için yüreklerimizi aydınlattı.'),
(2011775,68,47,4,7,'Üstün gücün bizden değil, Tanrıdan kaynaklandığı bilinsin diye bu hazineye toprak kaplar içinde sahibiz.'),
(2011776,68,47,4,8,'Her yönden sıkıştırılmışız, ama ezilmiş değiliz. Şaşırmışız, ama çaresiz değiliz.'),
(2011777,68,47,4,9,'Kovalanıyoruz, ama terk edilmiş değiliz. Yere yıkılmışız, ama yok olmuş değiliz.'),
(2011778,68,47,4,10,'İsanın yaşamı bedenimizde açıkça görülsün diye İsanın ölümünü her an bedenimizde taşıyoruz.'),
(2011779,68,47,4,11,'Çünkü İsanın yaşamı ölümlü bedenimizde açıkça görülsün diye, biz yaşayanlar İsa uğruna sürekli olarak ölüme teslim ediliyoruz.'),
(2011780,68,47,4,12,'Böylece ölüm bizde, yaşamsa sizde etkin olmaktadır.'),
(2011781,68,47,4,13,'‹‹İman ettim, bu nedenle konuştum›› diye yazılmıştır. Aynı iman ruhuna sahip olarak biz de iman ediyor ve bu nedenle konuşuyoruz.'),
(2011782,68,47,4,14,'Çünkü Rab İsayı dirilten Tanrının, bizi de İsayla diriltip sizinle birlikte kendi önüne çıkaracağını biliyoruz.'),
(2011783,68,47,4,15,'Bütün bunlar sizin yararınızadır. Böylelikle Tanrının lütfu çoğalıp daha çok insana ulaştıkça, Tanrının yüceliği için şükran da artsın.'),
(2011784,68,47,4,16,'Bu nedenle cesaretimizi yitirmeyiz. Her ne kadar dış varlığımız harap oluyorsa da, iç varlığımız günden güne yenileniyor.'),
(2011785,68,47,4,17,'Çünkü geçici, hafif sıkıntılarımız bize, ağırlıkta hiçbir şeyle karşılaştırılamayacak kadar büyük, sonsuz bir yücelik kazandırmaktadır.'),
(2011786,68,47,4,18,'Gözlerimizi görünen şeylere değil, görünmeyenlere çeviriyoruz. Çünkü görünenler geçicidir, görünmeyenlerse sonsuza dek kalıcıdır.'),
(2011787,68,47,5,1,'Biliyoruz ki, barındığımız bu dünyasal çadır yıkılırsa, göklerde Tanrının bize sağladığı bir konut -elle yapılmamış, sonsuza dek kalacak bir evimiz- vardır.'),
(2011788,68,47,5,2,'Şimdiyse göksel evimizi giyinmeyi özleyerek inliyoruz.'),
(2011789,68,47,5,3,'Onu giyinirsek çıplak kalmayız.'),
(2011790,68,47,5,4,'Dünyasal çadırda yaşayan bizler ağır bir yük altında inliyoruz. Asıl istediğimiz soyunmak değil, giyinmektir. Öyle ki, ölümlü olan, yaşam tarafından yutulsun.'),
(2011791,68,47,5,5,'Bizleri tam bu amaç için hazırlamış ve güvence olarak bize Ruhu vermiş olan Tanrıdır.'),
(2011792,68,47,5,6,'Bu nedenle her zaman cesaretimiz vardır. Şunu biliyoruz ki, bu bedende yaşadıkça Rabden uzaktayız.'),
(2011793,68,47,5,7,'Gözle görülene değil, imana dayanarak yaşarız.'),
(2011794,68,47,5,8,'Cesaretimiz vardır diyorum ve bedenden uzakta, Rabbin yanında olmayı yeğleriz.'),
(2011795,68,47,5,9,'Bunun için, ister bedende yaşayalım ister bedenden uzak olalım, amacımız Rabbi hoşnut etmektir.'),
(2011796,68,47,5,10,'Çünkü bedende yaşarken gerek iyi gerek kötü, yaptıklarımızın karşılığını almak için hepimiz Mesihin yargı kürsüsü önüne çıkmak zorundayız.'),
(2011797,68,47,5,11,'Rabden korkmanın ne demek olduğunu bildiğimizden insanları ikna etmeye çalışıyoruz. Ne olduğumuzu Tanrı biliyor; umarım siz de vicdanınızda biliyorsunuz.'),
(2011798,68,47,5,12,'Kendimizi yine size tavsiye etmeye çalışmıyoruz. Ama yürekle değil, dış görünüşle övünenleri yanıtlayabilmeniz için bizimle övünmenize fırsat veriyoruz.'),
(2011799,68,47,5,13,'Eğer kendimizde değilsek, bu Tanrı içindir. Aklımız başımızdaysa, bu sizin içindir.'),
(2011800,68,47,5,14,'Bizi zorlayan, Mesihin sevgisidir. Yargımız şu: Biri herkes için öldü; öyleyse hepsi öldü.'),
(2011801,68,47,5,15,'Evet, Mesih herkes için öldü. Öyle ki, yaşayanlar artık kendileri için değil, kendileri uğruna ölüp dirilen Mesih için yaşasınlar.'),
(2011802,68,47,5,16,'Bu nedenle, biz artık kimseyi insan ölçülerine göre tanımayız. Mesihi bu ölçülere göre tanıdıksa da, artık öyle tanımıyoruz.'),
(2011803,68,47,5,17,'Bir kimse Mesihteyse, yeni yaratıktır; eski şeyler geçmiş, her şey yeni olmuştur.'),
(2011804,68,47,5,18,'Bunların hepsi Tanrıdandır. Tanrı, Mesih aracılığıyla bizi kendisiyle barıştırdı ve bize barıştırma görevini verdi.'),
(2011805,68,47,5,19,'Şöyle ki Tanrı, insanların suçlarını saymayarak dünyayı Mesihte kendisiyle barıştırdı ve barıştırma sözünü bize emanet etti.'),
(2011806,68,47,5,20,'Böylece, Tanrı aracılığımızla çağrıda bulunuyormuş gibi Mesihin adına elçilik ediyor, Onun adına yalvarıyoruz: Tanrıyla barışın.'),
(2011807,68,47,5,21,'Tanrı, günahı bilmeyen Mesih''i bizim için günah sunusu yaptı. Öyle ki, Mesih sayesinde Tanrı''nın doğruluğu olalım.'),
(2011808,68,47,6,1,'Tanrıyla birlikte çalışan bizler, Onun lütfunu boş yere kabul etmemenizi ayrıca rica ediyoruz.'),
(2011809,68,47,6,2,'Çünkü Tanrı diyor ki, ‹‹Uygun zamanda seni duydum, Kurtuluş günü sana yardım ettim.››'),
(2011810,68,47,6,3,'Hizmetimizin kötülenmemesi için hiçbir konuda hiç kimsenin sürçmesine neden olmadık.'),
(2011811,68,47,6,4,'Tersine Tanrının hizmetkârları olarak olağanüstü dayanmada, sıkıntı, güçlük ve elemlerde, dayak, hapis, karışıklık, emek, uykusuzluk ve açlıkta; pak yaşayışta, bilgi, sabır, iyilik, Kutsal Ruh ve içten sevgide; gerçeğin ilanında ve Tanrının gücünde; sağ ve sol ellerimizde doğruluğun silahlarıyla, yücelikte ve onursuzlukta, iyi ünde ve kötü ünde, kendimizi her durumda örnek gösteriyoruz. Aldatanlar sayılıyorsak da dürüst kişileriz.'),
(2011812,68,47,6,9,'Tanınmıyor gibiyiz, ama iyi tanınıyoruz. Ölümün ağzındayız, ama işte yaşıyoruz. Dövülüyorsak bile öldürülmüş değiliz.'),
(2011813,68,47,6,10,'Kederliyiz ama her zaman seviniyoruz. Yoksuluz ama birçoklarını zengin ediyoruz. Hiçbir şeyimiz yok ama her şeye sahibiz.'),
(2011814,68,47,6,11,'Ey Korintliler, sizinle açıkça konuştuk, size yüreğimizi açtık.'),
(2011815,68,47,6,12,'Sizden sevgimizi esirgemedik, ama siz bizden sevginizi esirgediniz.'),
(2011816,68,47,6,13,'Bize aynı karşılığı verebilmek için -çocuklarıma söyler gibi söylüyorum- siz de yüreğinizi açın.'),
(2011817,68,47,6,14,'İmansızlarla aynı boyunduruğa girmeyin. Çünkü doğrulukla fesadın ne ortaklığı, ışıkla karanlığın ne paydaşlığı olabilir?'),
(2011818,68,47,6,15,'Mesihle Beliyal uyum içinde olabilir mi? İman edenle iman etmeyenin ortak yanı olabilir mi?'),
(2011819,68,47,6,16,'Tanrının tapınağıyla putlar uyuşabilir mi? Çünkü biz yaşayan Tanrının tapınağıyız. Nitekim Tanrı şöyle diyor: ‹‹Aralarında yaşayacak, Aralarında yürüyeceğim. Onların Tanrısı olacağım, Onlar da benim halkım olacak.››'),
(2011820,68,47,6,17,'Bu nedenle, ‹‹İmansızların arasından çıkıp ayrılın›› diyor Rab. ‹‹Murdara dokunmayın, Ben de sizi kabul edeceğim.››'),
(2011821,68,47,6,18,'Her Şeye Gücü Yeten Rab diyor ki, ‹‹Size Baba olacağım, Siz de oğullarım, kızlarım olacaksınız.››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011822,68,47,7,1,'Sevgili kardeşler, bu vaatlere sahip olduğumuza göre, bedeni ve ruhu lekeleyen her şeyden kendimizi arındıralım; Tanrı korkusuyla kutsallıkta yetkinleşelim.'),
(2011823,68,47,7,2,'Yüreklerinizde bize yer verin. Kimseye haksızlık etmedik, kimseyi yoldan saptırmadık, kimseyi sömürmedik.'),
(2011824,68,47,7,3,'Bunu sizi yargılamak için söylemiyorum. Daha önce de söylediğim gibi, yüreğimizde öyle bir yeriniz var ki, sizinle ölürüz de yaşarız da.'),
(2011825,68,47,7,4,'Size çok güveniyor, sizinle çok övünüyorum. Teselliyle doluyum. Bütün sıkıntılar arasında sevincim sonsuzdur.'),
(2011826,68,47,7,5,'Makedonyaya geldiğimizde de hiç rahat yüzü görmedik. Her bakımdan sıkıntı çekiyorduk. Dışarıda kavgalar, yüreğimizde korkular vardı.'),
(2011827,68,47,7,6,'Ama yüreği ezik olanları teselli eden Tanrı, Titusun yanımıza gelişiyle -yalnız gelişiyle değil, sizden aldığı teselliyle de- bizi teselli etti. Titus beni özlediğinizi, benim için üzülüp gayret ettiğinizi bize anlatınca sevincim bir kat daha arttı.'),
(2011828,68,47,7,8,'Mektubumla size acı verdiysem bile pişman değilim. Aslında pişman olmuştum -kısa bir süre için de olsa, o mektubun size acı verdiğini görüyorum- ama şimdi seviniyorum; acı duymanıza değil, bu acınızın sizi tövbeye yöneltmesine seviniyorum. Tanrının isteğine uygun olarak acı çektiniz. Böylece hiçbir şekilde bizden zarar görmediniz.'),
(2011829,68,47,7,10,'Tanrının isteğiyle çekilen acı, kişiyi kurtuluşla sonuçlanan ve pişmanlık doğurmayan tövbeye götürür. Dünyanın acılarıysa ölüm getirir.'),
(2011830,68,47,7,11,'Bakın bu acılar, Tanrının isteğiyle çektiğiniz bu acılar sizde ne büyük ciddiyet, paklanmak için ne büyük istek yarattı! Sizde ne büyük öfke, korku, özlem, gayret ve suçluyu cezalandırma arzusu uyandırdı! Bu konuda her bakımdan masum olduğunuzu kanıtladınız.'),
(2011831,68,47,7,12,'Size o mektubu yazdımsa da, haksızlık edeni ya da haksızlık göreni düşünerek yazmadım; bize ne denli adanmış olduğunuzu Tanrı önünde açıkça görmenizi istiyordum.'),
(2011832,68,47,7,13,'Bütün bunlarla teselli buluyoruz. Tesellimize ek olarak Titusun sevinci bizi daha da çok sevindirdi. Çünkü hepiniz onun yüreğini ferahlattınız.'),
(2011833,68,47,7,14,'Sizleri ona övdüm, beni utandırmadınız. Size söylediğimiz her şey nasıl doğru idiyse, sizi Titusa övmemiz de öylece doğru çıktı.'),
(2011834,68,47,7,15,'Hepinizin nasıl söz dinlediğini, kendisini nasıl saygı ve korkuyla kabul ettiğinizi anımsadıkça size olan sevgisi daha da artıyor.'),
(2011835,68,47,7,16,'Size her bakımdan güvenebildiğim için seviniyorum.'),
(2011836,68,47,8,1,'Kardeşler, sizlere Tanrının Makedonyadaki kiliselerine sağladığı lütuftan söz etmek istiyoruz: Büyük sıkıntılarla denendiklerinde, coşkun sevinçleri ve aşırı yoksullukları tam bir cömertliğe dönüştü.'),
(2011837,68,47,8,3,'Ellerinden geldiği kadarını, hatta daha fazlasını kendi istekleriyle verdiklerine tanıklık ederim.'),
(2011838,68,47,8,4,'Kutsallara yapılan yardıma katkıda bulunma ayrıcalığının kendilerine verilmesi için bize yalvarıp yakardılar.'),
(2011839,68,47,8,5,'Umduğumuzdan da öte, kendilerini önce Rabbe, sonra Tanrının isteğiyle bize adadılar.'),
(2011840,68,47,8,6,'Bu nedenle, aranızda daha önce başladığı bu hayırlı işi tamamlaması için Titusu isteklendirdik.'),
(2011841,68,47,8,7,'İmanda, söz söylemekte, bilgide, her tür gayrette, bize beslediğiniz sevgide, her şeyde üstün olduğunuz gibi, bu hayırlı işte de üstün olmaya bakın.'),
(2011842,68,47,8,8,'Bunu buyruk olarak söylemiyorum, yalnızca sevginizin içtenliğini ötekilerin gayretiyle karşılaştırarak sınamak istiyorum.'),
(2011843,68,47,8,9,'Rabbimiz İsa Mesihin lütfunu bilirsiniz. Onun yoksulluğuyla siz zengin olasınız diye, zengin olduğu halde sizin uğrunuza yoksul oldu.'),
(2011844,68,47,8,10,'Bu konuda size yararlı olanı salık veriyorum. Geçen yıl bağış toplamaya ilk girişen, hatta buna ilk heveslenen siz oldunuz.'),
(2011845,68,47,8,11,'Şimdi bu işi tamamlayın; bunu candan arzuladığınız gibi, elinizden geldiğince tamamlamaya bakın.'),
(2011846,68,47,8,12,'Çünkü istek varsa, insanın elinde olmayana göre değil, elindekine göre yardımda bulunması uygundur.'),
(2011847,68,47,8,13,'Amacımız sizi sıkıntıya sokup başkalarını rahatlatmak değildir. Ama eşitlik olsun diye, şimdi elinizdeki fazlalık onların eksiğini tamamladığı gibi, başka zaman onların elindeki fazlalık sizin eksiğinizi tamamlasın. Öyle ki, ‹‹Çok toplayanın fazlası, az toplayanın da eksiği yoktu›› diye yazılmış olduğu gibi, eşitlik olsun.'),
(2011848,68,47,8,16,'Titusun yüreğinde sizin için aynı ilgiyi uyandıran Tanrıya şükürler olsun!'),
(2011849,68,47,8,17,'Çünkü Titus yalnız ricamızı kabul etmekle kalmadı, size derin ilgi duyduğu için kendi isteğiyle yanınıza geliyor.'),
(2011850,68,47,8,18,'Müjdeyi yayma çabalarından ötürü bütün kiliselerce övülen bir kardeşi de onunla birlikte gönderiyoruz.'),
(2011851,68,47,8,19,'Üstelik bu kardeş, Rabbi yüceltmek ve yardıma hazır olduğumuzu göstermek için yürüttüğümüz bu hayırlı hizmette yol arkadaşımız olmak üzere kiliseler tarafından seçildi.'),
(2011852,68,47,8,20,'Bu büyük bağışla ilgili hizmetimizde kimsenin eleştirisine hedef olmamaya özen gösteriyoruz.'),
(2011853,68,47,8,21,'Çünkü yalnız Rabbin gözünde değil, insanların gözünde de doğru olanı yapmaya dikkat ediyoruz.'),
(2011854,68,47,8,22,'Birçok konuda defalarca deneyip gayretli bulduğumuz, şimdi size duyduğu büyük güvenle çok daha gayretli olan kardeşimizi de bu iki kişiyle birlikte gönderiyoruz.'),
(2011855,68,47,8,23,'Titusa gelince, o benim paydaşım ve aranızdaki emektaşımdır. Öbür kardeşlerimizse kiliselerin elçileri, Mesihin kıvancıdırlar.'),
(2011856,68,47,8,24,'Bunun için onlara sevginizi kanıtlayın, kiliselerin önünde sizinle övünmemizin nedenini gösterin.'),
(2011857,68,47,9,1,'Kutsallara yapılacak bu yardımla ilgili olarak size yazmama gerek yok.'),
(2011858,68,47,9,2,'Çünkü yardıma hazır olduğunuzu biliyorum. Ahayadaki sizlerin geçen yıldan beri hazırlıklı olduğunu söyleyerek Makedonyalılar karşısında sizinle övünmekteyim. Gayretiniz onların çoğunu harekete geçirdi.'),
(2011859,68,47,9,3,'Bu konuda sizinle övünmemiz boşa çıkmasın; dediğim gibi, hazırlıklı olasınız diye kardeşleri yanınıza gönderiyorum.'),
(2011860,68,47,9,4,'Öyle ki, bazı Makedonyalılar benimle birlikte gelir ve sizi hazırlıksız bulurlarsa, sizler bir yana, bizler duyduğumuz güvenden ötürü utanmayalım.'),
(2011861,68,47,9,5,'Bu nedenle önce yanınıza gelmeleri ve cömertçe vermeyi vaat ettiğiniz armağanları hazırlamaları için kardeşlere ricada bulunmayı gerekli gördüm. Öyle ki, armağanınız cimrilik değil, cömertlik örneği olarak hazır olsun.'),
(2011862,68,47,9,6,'Şunu unutmayın: Az eken az biçer, çok eken çok biçer.'),
(2011863,68,47,9,7,'Herkes yüreğinde niyet ettiği gibi versin; isteksizce ya da zorlanmış gibi değil. Çünkü Tanrı sevinçle vereni sever.'),
(2011864,68,47,9,8,'Her zaman, her yönden, her şeye yeterli ölçüde sahip olarak her iyi işe cömertçe katkıda bulunabilmeniz için, Tanrı her nimeti size bol bol sağlayacak güçtedir.'),
(2011865,68,47,9,9,'Nitekim şöyle yazılmıştır: ‹‹Armağanlar dağıttı, yoksullara verdi; Doğruluğu sonsuza dek kalıcıdır.››'),
(2011866,68,47,9,10,'Ekinciye tohum ve yiyecek ekmek sağlayan Tanrı, sizin de ekeceğinizi sağlayıp çoğaltacak, doğruluğunuzun ürünlerini artıracaktır.'),
(2011867,68,47,9,11,'Her durumda cömert olmanız için her bakımdan zenginleştiriliyorsunuz. Cömertliğiniz bizim aracılığımızla Tanrıya şükran nedeni oluyor.'),
(2011868,68,47,9,12,'Yaptığınız bu hizmet yalnız kutsalların eksiklerini gidermekle kalmıyor, birçoklarının Tanrıya şükretmesiyle de zenginleşiyor.'),
(2011869,68,47,9,13,'Onlar, içtenliğinizi kanıtlayan bu hizmetten ötürü, açıkça benimsediğiniz Mesih Müjdesine uyarak kendileriyle ve herkesle malınızı cömertçe paylaştığınız için Tanrıyı yüceltiyorlar.'),
(2011870,68,47,9,14,'Tanrının size bağışladığı olağanüstü lütuftan dolayı sizler için dua ediyor, sizi özlüyorlar.'),
(2011871,68,47,9,15,'Sözle anlatılamayan armağanı için Tanrı''ya şükürler olsun!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011872,68,47,10,1,'Sizinle birlikteyken ürkek, ama aranızda değilken yiğit kesilen ben Pavlus, Mesihteki alçakgönüllülük ve yumuşaklıkla size rica ediyor, yalvarıyorum: Yanınıza geldiğim zaman, bizi olağan insanlar gibi yaşayanlardan sayan bazılarına karşı güvenle takınmak niyetinde olduğum tavrı aynı cesaretle size karşı takınmaya zorlamayın beni.'),
(2011873,68,47,10,3,'Olağan insanlar gibi yaşıyorsak da, insansal güce dayanarak savaşmıyoruz.'),
(2011874,68,47,10,4,'Çünkü savaşımızın silahları insansal silahlar değil, kaleleri yıkan tanrısal güce sahip silahlardır.'),
(2011875,68,47,10,5,'Safsataları, Tanrı bilgisine karşı diklenen her engeli yıkıyor, her düşünceyi tutsak edip Mesihe bağımlı kılıyoruz.'),
(2011876,68,47,10,6,'Mesihe tümüyle bağımlı olduğunuz zaman, Ona bağımlı olmayan her eylemi cezalandırmaya hazır olacağız.'),
(2011877,68,47,10,7,'Gözünüzün önündekine bakın. Bir kimse Mesihe ait olduğuna güveniyorsa, yine düşünsün: Kendisi kadar biz de Mesihe aitiz.'),
(2011878,68,47,10,8,'Sizi yıkmak için değil, geliştirmek için Rabbin bize verdiği yetkiyle biraz fazla övünsem de utanmam.'),
(2011879,68,47,10,9,'Mektuplarımla sizi korkutmaya çalışıyormuş gibi görünmek istemiyorum.'),
(2011880,68,47,10,10,'Çünkü bazıları, ‹‹Mektupları ağır ve etkilidir, ama kişisel varlığı etkisiz, konuşma yeteneği de sıfır›› diyormuş.'),
(2011881,68,47,10,11,'Böyle diyenler şunu bilsin ki, uzaktayken mektuplarımızda ne diyorsak, aranızdayken de öyle davranıyoruz.'),
(2011882,68,47,10,12,'Kendilerini tavsiye eden bazılarıyla kendimizi bir tutmaya ya da karşılaştırmaya elbette cesaret edemeyiz! Onlar kendilerini kendileriyle ölçüp karşılaştırmakla akılsızlık ediyorlar.'),
(2011883,68,47,10,13,'Ama biz haddimizi aşıp fazla övünmeyiz; övünmemiz, Tanrının bizim için belirlediği, sizlere kadar da uzanan alanın sınırları içinde kalır.'),
(2011884,68,47,10,14,'Etkinlik alanımız size kadar uzanmasaydı, sizinle ilgilenmekle sınırlarımızın dışına çıkmış sayılabilirdik. Oysa Mesihin Müjdesini size kadar ilk ulaştıran biz olduk.'),
(2011885,68,47,10,15,'Başkalarının emeğiyle övünüp haddimizi aşmayız. Umudumuz odur ki, sizin imanınız büyüdükçe sayenizde etkinlik alanımız alabildiğine genişleyecek.'),
(2011886,68,47,10,16,'Böylelikle Müjdeyi sizlerden daha ötelere yayabileceğiz. Çünkü başkasının etkinlik alanında başarılmış işlerle övünmek istemiyoruz.'),
(2011887,68,47,10,17,'‹‹Övünen, Rable övünsün.››'),
(2011888,68,47,10,18,'Kabule değer kişi kendi kendini tavsiye eden değil, Rab''bin tavsiye ettiği kişidir.'),
(2011889,68,47,11,1,'Umarım yapacağım küçük bir akılsızlığı hoş görürsünüz. Ne olur, beni hoş görün!'),
(2011890,68,47,11,2,'Sizler için tanrısal bir kıskançlık duyuyorum. Çünkü sizleri el değmemiş kız gibi tek ere, Mesihe sunmak üzere nişanladım.'),
(2011891,68,47,11,3,'Ne var ki, yılanın Havvayı kurnazlığıyla aldatması gibi, düşüncelerinizin Mesihe olan içten ve pak adanmışlıktan saptırılmasından korkuyorum.'),
(2011892,68,47,11,4,'Çünkü size gelen ve bizim tanıttığımızdan değişik bir İsayı tanıtanları pekâlâ hoş görüyorsunuz. Ayrıca, aldığınız ruhtan farklı bir ruhu ve kabul ettiğinizden farklı bir müjdeyi kabul ederek bunları hoş görüyorsunuz.'),
(2011893,68,47,11,5,'Sözüm ona üstün elçilerden hiç de aşağı olduğumu sanmıyorum!'),
(2011894,68,47,11,6,'Acemi bir konuşmacı olabilirim, ama bilgiden yana acemi değilim. Bunu size her durumda, her bakımdan açıkça gösterdik.'),
(2011895,68,47,11,7,'Yücelmeniz için kendimi alçaltarak Tanrının Müjdesini size karşılıksız bildirmekle günah mı işledim?'),
(2011896,68,47,11,8,'Size hizmet etmek için yardım aldığım başka kiliseleri adeta soydum.'),
(2011897,68,47,11,9,'Aranızdayken ihtiyacım olduğu halde hiçbirinize yük olmadım. Çünkü Makedonyadan gelen kardeşler eksiklerimi tamamladılar. Size yük olmamaya hep özen gösterdim, bundan böyle de özen göstereceğim.'),
(2011898,68,47,11,10,'Mesihin gerçeğine sahip olarak kesinlikle diyebilirim ki, Ahaya İlinde hiç kimse beni böyle övünmekten alıkoyamaz.'),
(2011899,68,47,11,11,'Neden mi? Sizi sevmediğimden mi? Tanrı biliyor ki, sizi seviyorum.'),
(2011900,68,47,11,12,'Övündükleri konuda bize eşit sayılmak isteyen fırsatçılara fırsat vermemek için, yaptığımı yapmaya devam edeceğim.'),
(2011901,68,47,11,13,'Bu tür adamlar sahte elçiler, düzenbaz işçiler, kendilerine Mesihin elçisi süsü verenlerdir.'),
(2011902,68,47,11,14,'Buna şaşmamalı. Şeytan da kendisine ışık meleği süsü verir.'),
(2011903,68,47,11,15,'Ona hizmet edenlerin de kendilerine doğruluğun hizmetkârları süsü vermesi şaşırtıcı değildir. Onların sonu yaptıklarına göre olacaktır.'),
(2011904,68,47,11,16,'Yine söylüyorum, kimse beni akılsız sanmasın. Öyle sanıyorsanız, akılsız birini kabul eder gibi de olsa beni kabul edin ki, ben de biraz övüneyim!'),
(2011905,68,47,11,17,'Söylediklerimi Rabbin söyleyeceği gibi değil, akılsız biri gibi, bu övüngen tavırla söylüyorum.'),
(2011906,68,47,11,18,'Mademki birçokları ne olduklarıyla övünüyorlar, ben de övüneceğim.'),
(2011907,68,47,11,19,'Sizler akıllı olduğunuz için akılsızlara seve seve katlanıyorsunuz!'),
(2011908,68,47,11,20,'Aslında sizi köle edenlere, sömürenlere, sizden yararlananlara, büyüklük taslayanlara ya da sizi tokatlayanlara katlanıyorsunuz.'),
(2011909,68,47,11,21,'Utanarak kabul ediyorum ki, biz bunu yapacak güçte değildik! Ama birinin övünmeye cesaret ettiği konuda -akılsız biri gibi konuşuyorum- ben de övünmeye cesaret ediyorum.'),
(2011910,68,47,11,22,'Onlar İbrani mi? Ben de İbraniyim. İsrailli mi? Ben de İsrailliyim. İbrahimin soyundan mıdırlar? Ben de onun soyundanım.'),
(2011911,68,47,11,23,'Mesihin hizmetkârları mıdırlar? Aklımı kaçırmış gibi konuşuyorum. Ben Onun daha üstün bir hizmetkârıyım. Ben daha çok emek verdim, hapse daha çok girdim, sayısız dayak yedim, çok kez ölümle burun buruna geldim.'),
(2011912,68,47,11,24,'Beş kez Yahudilerden otuz dokuzar kırbaç yedim.'),
(2011913,68,47,11,25,'Üç kez değnekle dövüldüm, bir kez taşlandım, üç kez deniz kazasına uğradım. Bir gün bir gece açık denizde kaldım.'),
(2011914,68,47,11,26,'Sık sık yolculuk ettim. Irmaklarda, haydutlar arasında, gerek soydaşlarımın gerekse öteki ulusların arasında tehlikelere uğradım. Kentte, kırda, denizde, sahte kardeşler arasında tehlikelere düştüm.'),
(2011915,68,47,11,27,'Emek verdim, sıkıntı çektim, çok kez uykusuz kaldım. Açlığı, susuzluğu tattım. Çok kez yiyecek sıkıntısı çektim, soğukta çıplak kaldım.'),
(2011916,68,47,11,28,'Öbür sorunların yanısıra, bütün kiliseler için her gün çektiğim kaygının baskısı var üzerimde.'),
(2011917,68,47,11,29,'Kim güçsüz olur da ben güçsüz olmam? Kim günaha düşürülür de ben onun için yanmam?'),
(2011918,68,47,11,30,'Övünmem gerekiyorsa, güçsüzlüğümü gösteren şeylerle övüneceğim.'),
(2011919,68,47,11,31,'Rab İsanın sonsuza dek övülecek olan Tanrısı ve Babası biliyor ki, yalan söylemiyorum.'),
(2011920,68,47,11,32,'Şamda Kral Aretasın valisi beni yakalatmak için kenti denetim altına almıştı.'),
(2011921,68,47,11,33,'Ama beni küfe içinde surdaki bir pencereden sarkıttılar; böylece onun elinden sıyrılıp kaçtım.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011922,68,47,12,1,'Yararlı olmasa da övünmek gereklidir. Şimdi görümlere ve Rabbin vahiylerine geleyim.'),
(2011923,68,47,12,2,'On dört yıl önce alınıp üçüncü göğe götürülmüş bir Mesih izleyicisi tanıyorum. Bu, bedensel olarak mı, yoksa beden dışında mı oldu, bilmiyorum, Tanrı bilir.'),
(2011924,68,47,12,3,'Evet, bu adamın cennete götürüldüğünü biliyorum; bu, bedensel olarak mı, yoksa bedenden ayrı mı oldu, bilmiyorum, Tanrı bilir. Orada, dille anlatılamaz, insanın söylemesi yasak olan sözler işitti.'),
(2011925,68,47,12,5,'Böyle biriyle övüneceğim. Ama kendimle ilgili olarak, güçsüzlüklerimden başka bir şeyle övünmeyeceğim.'),
(2011926,68,47,12,6,'Övünmek istesem bile akılsız olmayacağım. Çünkü gerçeği söylemiş olacağım. Ama kimse beni gördüğünden ya da işittiğinden daha üstün görmesin diye övünmekten kaçınıyorum.'),
(2011927,68,47,12,7,'Aldığım vahiylerin üstünlüğüyle gururlanmayayım diye bana bedende bir diken, beni yumruklamak için Şeytanın bir meleği verildi, gururlanmayayım diye.'),
(2011928,68,47,12,8,'Bundan kurtulmak için Rabbe üç kez yalvardım.'),
(2011929,68,47,12,9,'Ama O bana, ‹‹Lütfum sana yeter. Çünkü gücüm, güçsüzlükte tamamlanır›› dedi. İşte, Mesihin gücü içimde bulunsun diye güçsüzlüklerimle sevinerek daha çok övüneceğim.'),
(2011930,68,47,12,10,'Bu nedenle Mesih uğruna güçsüzlükleri, hakaretleri, zorlukları, zulümleri ve darlıkları sevinçle karşılıyorum. Çünkü ne zaman güçsüzsem, o zaman güçlüyüm.'),
(2011931,68,47,12,11,'Akılsız biri gibi davrandım, ama beni buna siz zorladınız. Aslında beni siz tavsiye etmeliydiniz. Çünkü bir hiç isem de, sözüm ona üstün elçilerden hiç de aşağı değilim.'),
(2011932,68,47,12,12,'Elçiliğimin kanıtları aranızda büyük bir sabırla, belirtiler, harikalar ve mucizelerle gösterildi.'),
(2011933,68,47,12,13,'Size yük olmayışımdan başka öbür kiliselerden ne eksiğiniz var ki? Bu haksızlığımı bağışlayın!'),
(2011934,68,47,12,14,'İşte, üçüncü kez yanınıza gelmeye hazırım ve size yük olmayacağım. Çünkü sizde olanı değil, sizi istiyorum. Çocukların anne babaları için değil, anne babaların çocukları için para biriktirmesi gerekir.'),
(2011935,68,47,12,15,'Ben de canlarınız uğruna malımı da kendimi de seve seve harcayacağım. Sizi daha çok seversem, daha az mı sevileceğim?'),
(2011936,68,47,12,16,'Öyle olsun, ben size yük olmadım. Ama kurnaz biri olduğumdan sizi hileyle elde etmişim!'),
(2011937,68,47,12,17,'Size gönderdiğim adamlardan biri aracılığıyla sizi sömürdüm mü?'),
(2011938,68,47,12,18,'Titusu size gelmeye isteklendirdim ve öbür kardeşi de onunla birlikte gönderdim. Titus sizi sömürmedi, değil mi? Aynı ruhla davranmadık mı, aynı yolu izlemedik mi?'),
(2011939,68,47,12,19,'Bunca zamandır önünüzde kendimizi savunduğumuzu mu düşünüyorsunuz? Tanrının önünde, Mesihe ait kişiler olarak konuşuyoruz. Sevgili kardeşler, yaptığımız her şey sizin gelişmeniz içindir.'),
(2011940,68,47,12,20,'Çünkü geldiğimde sizi istediğim durumda bulamayacağımdan korkuyorum. Sizler de beni istediğiniz durumda bulamayabilirsiniz. Aranızda çekişme, kıskançlık, öfke, bencil tutkular, iftira, dedikodu, böbürlenme, kargaşa olmasından korkuyorum.'),
(2011941,68,47,12,21,'Korkarım size tekrar geldiğimde Tanrım beni önünüzde utandıracak; daha önce günah işleyip de kapıldıkları pisliklerden, fuhuş ve sefahatten tövbe etmeyen birçokları için yas tutacağım.'),
(2011942,68,47,13,1,'Bu, yanınıza üçüncü gelişim olacak. Her suçlama iki ya da üç tanığın tanıklığıyla doğrulanmalıdır.'),
(2011943,68,47,13,2,'Daha önce, aranızda ikinci kez bulunduğumda, geçmişte günah işlemiş olanlarla onların dışında kalanların hepsine söylemiştim, şimdi sizden uzaktayken de yineliyorum: Tekrar yanınıza gelirsem, hiç kimseyi esirgemeyeceğim!'),
(2011944,68,47,13,3,'Mesihin benim aracılığımla konuştuğuna ilişkin kanıt istiyorsunuz. Mesih size karşı güçsüz değildir; Onun gücü sizde etkindir.'),
(2011945,68,47,13,4,'Güçsüzlük içinde çarmıha gerildiği halde, şimdi Tanrının gücüyle yaşıyor. Biz de Onda güçsüz olduğumuz halde, Tanrının gücü sayesinde Onunla birlikte sizin yararınıza yaşayacağız.'),
(2011946,68,47,13,5,'İman yolunda olup olmadığınızı anlamak için kendinizi sınayıp yoklayın. İsa Mesihin içinizde olduğunu bilmiyor musunuz? Yoksa sınavdan başarısız çıkarsınız.'),
(2011947,68,47,13,6,'Umarım bizim başarısızlığa uğramadığımızı anlayacaksınız.'),
(2011948,68,47,13,7,'Kötü bir şey yapmamanız için Tanrıya dua ediyoruz. Dileğimiz, bizim sınavı geçmiş görünmemiz değil, biz sınavda başarısız görünsek bile sizin iyi olanı yapmanızdır.'),
(2011949,68,47,13,8,'Çünkü gerçeğe karşı değil, ancak gerçek uğruna bir şey yapabiliriz.'),
(2011950,68,47,13,9,'Biz güçsüz, sizse güçlüyken seviniyoruz. Yetkin olmanız için de dua ediyoruz.'),
(2011951,68,47,13,10,'Rabbin yıkmak değil, geliştirmek için bana verdiği yetkiyi yanınıza geldiğimde sert biçimde kullanmak zorunda kalmayayım diye, bunları aranızda değilken yazıyorum.'),
(2011952,68,47,13,11,'Son olarak hoşça kalın, kardeşlerim. Yaşantınızı düzeltin, çağrıma kulak verin, düşüncelerinizde birlik olun, esenlik içinde yaşayın. Sevgi ve esenlik kaynağı olan Tanrı sizinle birlikte olacaktır.'),
(2011953,68,47,13,12,'Birbirinizi kutsal öpüşle selamlayın.'),
(2011954,68,47,13,13,'Bütün kutsallar size selam eder.'),
(2011955,68,47,13,14,'Rab İsa Mesih''in lütfu, Tanrı''nın sevgisi ve Kutsal Ruh''un paydaşlığı hepinizle birlikte olsun.'),
(2011956,68,48,1,1,'İnsanlarca ya da insan aracılığıyla değil, İsa Mesih ve Onu ölümden dirilten Baba Tanrı aracılığıyla elçi atanan ben Pavlustan ve benimle birlikte olan bütün kardeşlerden Galatyadaki kiliselere selam!'),
(2011957,68,48,1,3,'Babamız Tanrıdan ve Rab İsa Mesihten sizlere lütuf ve esenlik olsun.'),
(2011958,68,48,1,4,'Mesih, Babamız Tanrının isteğine uyarak bizi şimdiki kötü çağdan kurtarmak için günahlarımıza karşılık kendini feda etti.'),
(2011959,68,48,1,5,'Tanrıya sonsuzlara dek yücelik olsun! Amin.'),
(2011960,68,48,1,6,'Sizi Mesihin lütfuyla çağıranı bırakıp değişik bir müjdeye böylesine çarçabuk dönmenize şaşıyorum.'),
(2011961,68,48,1,7,'Gerçekte başka bir müjde yoktur. Ancak aklınızı karıştırıp Mesihin Müjdesini çarpıtmak isteyenler vardır.'),
(2011962,68,48,1,8,'İster biz, ister gökten bir melek size bildirdiğimize ters düşen bir müjde bildirirse, lanet olsun ona!'),
(2011963,68,48,1,9,'Daha önce söylediğimizi şimdi yine söylüyorum: Bir kimse size kabul ettiğinize ters düşen bir müjde bildirirse, ona lanet olsun!'),
(2011964,68,48,1,10,'Şimdi ben insanların onayını mı, Tanrının onayını mı arıyorum? Yoksa insanları mı hoşnut etmeye çalışıyorum? Eğer hâlâ insanları hoşnut etmek isteseydim, Mesihin kulu olmazdım.'),
(2011965,68,48,1,11,'Kardeşlerim, yaydığım Müjdenin insandan kaynaklanmadığını bilmenizi istiyorum.'),
(2011966,68,48,1,12,'Çünkü ben onu insandan almadım, kimseden de öğrenmedim. Bunu bana İsa Mesih vahiy yoluyla açıkladı.'),
(2011967,68,48,1,13,'Yahudi dinine bağlı olduğum zaman nasıl bir yaşam sürdüğümü duydunuz. Tanrının kilisesine alabildiğine zulmediyor, onu kırıp geçiriyordum.'),
(2011968,68,48,1,14,'Yahudi dininde yaşıtım olan soydaşlarımın birçoğundan daha ilerideydim, atalarımın geleneklerini savunmakta çok daha gayretliydim.'),
(2011969,68,48,1,15,'Ama beni daha annemin rahmindeyken seçip lütfuyla çağıran Tanrı, uluslara müjdelemem için Oğlunu bana göstermeye razı olunca hemen insanlara danışmadım;'),
(2011970,68,48,1,17,'Yeruşalime, benden önce elçi olanların yanına da gitmedim; Arabistana gittim, sonra yine Şama döndüm.'),
(2011971,68,48,1,18,'Bundan üç yıl sonra Kefasla tanışmak üzere Yeruşalime gittim, on beş gün onun yanında kaldım.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2011972,68,48,1,19,'Öbür elçilerden hiçbirini görmedim, yalnız Rab İsanın kardeşi Yakupu gördüm.'),
(2011973,68,48,1,20,'Bakın, size yazdıklarımın yalan olmadığını Tanrının önünde belirtiyorum.'),
(2011974,68,48,1,21,'Sonra Suriye ve Kilikya bölgelerine gittim.'),
(2011975,68,48,1,22,'Yahudiyenin Mesihe ait kiliseleri beni şahsen tanımıyorlardı.'),
(2011976,68,48,1,23,'Yalnız, ‹‹Bir zamanlar bize zulmeden adam, önceleri yıkmaya çalıştığı imanı şimdi yayıyor›› dendiğini duymuşlardı.'),
(2011977,68,48,1,24,'Böylece benden ötürü Tanrı''yı yüceltiyorlardı.'),
(2011978,68,48,2,1,'On dört yıl aradan sonra Titusu da yanıma alıp Barnabayla birlikte yine Yeruşalime gittim.'),
(2011979,68,48,2,2,'Vahiy uyarınca gittim. Boş yere koşmayayım ya da koşmuş olmayayım diye, öteki uluslar arasında yaydığım Müjdeyi özel olarak ileri gelenlere sundum.'),
(2011980,68,48,2,3,'Benimle birlikte olan Titus bile Grek olmasına karşın sünnet edilmeye zorlanmadı.'),
(2011981,68,48,2,4,'Ne var ki, İsa Mesihte sahip olduğumuz özgürlüğü el altından öğrenmek ve böylece bizi köleleştirmek için gizlice aramıza sızan sahte kardeşler vardı.'),
(2011982,68,48,2,5,'Müjde gerçeği sürekli sizinle kalsın diye bir an bile onlara boyun eğip teslim olmadık.'),
(2011983,68,48,2,6,'Ama ileri gelenler -ne oldukları bence önemli değil, Tanrı insanlar arasında ayrım yapmaz- evet, bu ileri gelenler söylediklerime bir şey katmadılar.'),
(2011984,68,48,2,7,'Tam tersine, Müjdeyi sünnetlilere bildirme işi nasıl Petrusa verildiyse, sünnetsizlere bildirme işinin de bana verildiğini gördüler.'),
(2011985,68,48,2,8,'Çünkü sünnetlilere elçilik etmesi için Petrusta etkin olan Tanrı, öteki uluslara elçilik etmem için bende de etkin oldu.'),
(2011986,68,48,2,9,'Topluluğun direkleri sayılan Yakup, Kefas ve Yuhanna bana bağışlanan lütfu sezince paydaşlığımızın işareti olarak bana ve Barnabaya sağ ellerini uzattılar. Öteki uluslara bizlerin, Yahudilere kendilerinin gitmesini uygun gördüler.'),
(2011987,68,48,2,10,'Ancak yoksulları anımsamamızı istediler. Zaten ben de bunu yapmaya gayret ediyordum.'),
(2011988,68,48,2,11,'Ne var ki, Kefas Antakyaya geldiği zaman, suçlu olduğu için ona açıkça karşı geldim.'),
(2011989,68,48,2,12,'Çünkü Yakupun yanından bazı adamlar gelmeden önce Kefas öteki uluslardan olanlarla birlikte yemek yerdi. Ama o adamlar gelince sünnet yanlılarından korkarak sünnetsizlerden uzaklaştı, onlarla yemek yemez oldu.'),
(2011990,68,48,2,13,'Öbür Yahudiler de onun gibi ikiyüzlülük ettiler. Sonunda Barnaba bile onların ikiyüzlülüğüne kapıldı.'),
(2011991,68,48,2,14,'Müjde gerçeğine uygun davranmadıklarını görünce hepsinin önünde Kefasa şöyle dedim: ‹‹Yahudi olduğun halde Yahudi gibi değil, öteki uluslardan biri gibi yaşıyorsun, nasıl olur da ulusları Yahudi gibi yaşamaya zorlarsın?'),
(2011992,68,48,2,15,'Doğuştan Yahudi olan bizler öteki uluslardan olan ‹günahlılar› değiliz.'),
(2011993,68,48,2,16,'Yine de insanın Kutsal Yasanın gereklerini yaparak değil, İsa Mesihe iman ederek aklandığını biliyoruz. Bunun için biz de Yasanın gereklerini yaparak değil, Mesihe iman ederek aklanalım diye Mesih İsaya iman ettik. Çünkü hiç kimse Yasanın gereklerini yaparak aklanmaz.'),
(2011994,68,48,2,17,'Mesihte aklanmak isterken kendimiz günahlı çıkarsak, Mesih günahın yardakçısı mı olur? Kesinlikle hayır!'),
(2011995,68,48,2,18,'Yıktığımı yeniden kurarsam, yasayı çiğnediğimi kanıtlamış olurum.'),
(2011996,68,48,2,19,'Çünkü ben Tanrı için yaşamak üzere Yasa aracılığıyla Yasa karşısında öldüm.'),
(2011997,68,48,2,20,'Mesihle birlikte çarmıha gerildim. Artık ben yaşamıyorum, Mesih bende yaşıyor. Şimdi bedende sürdürdüğüm yaşamı, beni seven ve benim için kendini feda eden Tanrı Oğluna imanla sürdürüyorum.'),
(2011998,68,48,2,21,'Tanrı''nın lütfunu geçersiz saymış değilim. Çünkü aklanma Yasa aracılığıyla sağlanabilseydi, o zaman Mesih boş yere ölmüş olurdu.››'),
(2011999,68,48,3,1,'Ey akılsız Galatyalılar! Sizi kim büyüledi? İsa Mesih çarmıha gerilmiş olarak gözlerinizin önünde tasvir edilmedi mi?'),
(2012000,68,48,3,2,'Sizden yalnız şunu öğrenmek istiyorum: Kutsal Ruhu, Yasanın gereklerini yaparak mı, yoksa duyduklarınıza iman ederek mi aldınız?'),
(2012001,68,48,3,3,'Bu kadar akılsız mısınız? Ruhla başladıktan sonra şimdi insan çabasıyla mı bitirmeye çalışıyorsunuz?'),
(2012002,68,48,3,4,'Boş yere mi bu kadar acı çektiniz? Gerçekten boşuna mıydı?'),
(2012003,68,48,3,5,'Size Kutsal Ruhu veren ve aranızda mucizeler yaratan Tanrı, bunu Yasanın gereklerini yaptığınız için mi, yoksa duyduklarınıza iman ettiğiniz için mi yapıyor?'),
(2012004,68,48,3,6,'Örneğin, ‹‹İbrahim Tanrıya iman etti, böylece aklanmış sayıldı.››'),
(2012005,68,48,3,7,'Öyleyse şunu bilin ki, İbrahimin gerçek oğulları iman edenlerdir.'),
(2012006,68,48,3,8,'Kutsal Yazı, Tanrının öteki ulusları imanlarına göre aklayacağını önceden görerek İbrahime, ‹‹Bütün uluslar senin aracılığınla kutsanacak›› müjdesini önceden verdi.'),
(2012007,68,48,3,9,'Böylece iman edenler, iman etmiş olan İbrahimle birlikte kutsanırlar.'),
(2012008,68,48,3,10,'Yasanın gereklerini yapmış olmaya güvenenlerin hepsi lanet altındadır. Çünkü şöyle yazılmıştır: ‹‹Yasa Kitabında yazılı olan her şeyi sürekli yerine getirmeyen herkes lanetlidir.››'),
(2012009,68,48,3,11,'Tanrı katında hiç kimsenin Yasayla aklanmadığı açıktır. Çünkü ‹‹İmanla aklanan yaşayacaktır.››'),
(2012010,68,48,3,12,'Yasa imana dayalı değildir. Tersine, ‹‹Yasanın gereklerini yapan, onlar sayesinde yaşayacaktır.››'),
(2012011,68,48,3,13,'İbrahime sağlanan kutsama Mesih İsa aracılığıyla uluslara sağlansın ve bizler vaat edilen Ruhu imanla alalım diye, Mesih bizim için lanetlenerek bizi Yasanın lanetinden kurtardı. Çünkü, ‹‹Ağaç üzerine asılan herkes lanetlidir›› diye yazılmıştır.'),
(2012012,68,48,3,15,'Kardeşler, insan yaşamından bir örnek vereyim. İnsanlar arasında yapılmış bile olsa, onaylanmış bir antlaşmayı kimse geçersiz saymaz, ona bir şey eklemez.'),
(2012013,68,48,3,16,'Vaatler İbrahime ve soyundan olana verildi. Tanrı birçok kişiden söz ediyormuş gibi, ‹‹Ve soyundan olanlara›› demiyor; ‹‹Soyundan olana›› demekle tek bir kişiden, yani Mesihten söz ediyor.'),
(2012014,68,48,3,17,'Şunu demek istiyorum: Dört yüz otuz yıl sonra gelen Yasa, Tanrının önceden onayladığı antlaşmayı geçersiz kılmaz, vaadi ortadan kaldırmaz.'),
(2012015,68,48,3,18,'Çünkü miras Yasaya bağlıysa, artık vaade bağlı değildir. Ama Tanrı mirası İbrahime vaatle bağışlamıştır.'),
(2012016,68,48,3,19,'Öyleyse Yasanın amacı neydi? Yasa suçları ortaya çıkarmak için antlaşmaya eklendi. Vaadi alan ve İbrahimin soyundan olan Kişi gelene dek yürürlükte kalacaktı. Melekler yoluyla, bir aracı eliyle düzenlendi.'),
(2012017,68,48,3,20,'Aracı tek bir tarafa ait değildir; Tanrı ise birdir.'),
(2012018,68,48,3,21,'Öyleyse Kutsal Yasa Tanrının vaatlerine aykırı mıdır? Kesinlikle hayır! Çünkü yaşam sağlayabilen bir yasa verilseydi, elbette insanlar yasayla aklanırdı.'),
(2012019,68,48,3,22,'Oysa İsa Mesihe olan imana dayanan vaat iman edenlere verilsin diye, Kutsal Yazı bütün dünyayı günahın tutsağı ilan ediyor.'),
(2012020,68,48,3,23,'Bu iman gelmeden önce Yasa altında hapsedilmiştik, gelecek iman açıklanıncaya dek Yasanın tutuklusuyduk.'),
(2012021,68,48,3,24,'Yani imanla aklanalım diye Mesihin gelişine dek Yasa eğitmenimiz oldu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012022,68,48,3,25,'Ama iman gelmiş olduğundan, artık Yasanın denetiminde değiliz.'),
(2012023,68,48,3,26,'Çünkü Mesih İsaya iman ettiğiniz için hepiniz Tanrının oğullarısınız.'),
(2012024,68,48,3,27,'Vaftizde Mesihle birleşenlerinizin hepsi Mesihi giyindi.'),
(2012025,68,48,3,28,'Artık ne Yahudi ne Grek, ne köle ne özgür, ne erkek ne dişi ayrımı var. Hepiniz Mesih İsada birsiniz.'),
(2012026,68,48,3,29,'Eğer Mesih''e aitseniz, İbrahim''in soyundansınız, vaade göre de mirasçısınız.'),
(2012027,68,48,4,1,'Şunu demek istiyorum: Mirasçı her şeyin sahibiyse de, çocuk olduğu sürece köleden farksızdır.'),
(2012028,68,48,4,2,'Babasının belirlediği zamana dek vasilerin, vekillerin gözetimi altındadır.'),
(2012029,68,48,4,3,'Bunun gibi, biz de ruhsal yönden çocukken, dünyanın temel ilkelerine bağlı yaşayan kölelerdik.'),
(2012030,68,48,4,4,'Ama zaman dolunca Tanrı, Yasa altında olanları özgürlüğe kavuşturmak için kadından doğan, Yasa altında doğan öz Oğlunu gönderdi. Öyle ki, bizler oğulluk hakkını alalım.'),
(2012031,68,48,4,6,'Oğullar olduğunuz için Tanrı öz Oğlunun ‹‹Abba! Baba!›› diye seslenen Ruhunu yüreklerinize gönderdi.'),
(2012032,68,48,4,7,'Bu nedenle artık köle değil, oğullarsınız. Oğullar olduğunuz için de Tanrı sizi aynı zamanda mirasçı yaptı.'),
(2012033,68,48,4,8,'Ne var ki, eskiden Tanrıyı tanımadığınız zamanlarda, gerçek olmayan tanrılara kölelik ettiniz.'),
(2012034,68,48,4,9,'Şimdiyse Tanrıyı tanıdınız, daha doğrusu Tanrı tarafından tanındınız. Öyleyse nasıl oluyor da bu değersiz, etkisiz ilkelere dönüyorsunuz? Yeniden onların kölesi mi olmak istiyorsunuz?'),
(2012035,68,48,4,10,'Özel günler, aylar, mevsimler, yıllar kutluyorsunuz!'),
(2012036,68,48,4,11,'Sizin için korkuyorum. Yoksa uğrunuza boş yere mi emek verdim?'),
(2012037,68,48,4,12,'Kardeşler, size yalvarıyorum, benim gibi olun. Çünkü ben de sizin gibi oldum. Bana hiç haksızlık etmediniz.'),
(2012038,68,48,4,13,'Bildiğiniz gibi, Müjdeyi size ilk kez bedensel hastalığım nedeniyle bildirmiştim.'),
(2012039,68,48,4,14,'Bedensel durumum sizin için çetin bir deneme olduğu halde beni ne hor gördünüz ne de reddettiniz. Tanrının bir meleğini, hatta Mesih İsayı kabul eder gibi kabul ettiniz beni.'),
(2012040,68,48,4,15,'Şimdi o sevincinize ne oldu? Sizin için tanıklık ederim ki, elinizden gelse gözlerinizi oyar bana verirdiniz.'),
(2012041,68,48,4,16,'Peki, size gerçeği söylediğim için düşmanınız mı oldum?'),
(2012042,68,48,4,17,'Başkaları sizi kazanmaya gayret ediyor, ama niyetleri iyi değil. Kendileri için gayret edesiniz diye sizi bizden ayırmak istiyorlar.'),
(2012043,68,48,4,18,'Niyet iyiyse, yalnız aranızda olduğum zaman değil, her zaman gayretli olmak iyidir.'),
(2012044,68,48,4,19,'Çocuklarım! Mesih sizde biçimleninceye dek sizin için yine doğum ağrısı çekiyorum.'),
(2012045,68,48,4,20,'Şimdi yanınızda bulunmayı ve sesimin tonunu değiştirmeyi isterdim. Bu halinize şaşıyorum!'),
(2012046,68,48,4,21,'Kutsal Yasa altında yaşamak isteyen sizler, söyleyin bana, Yasanın ne dediğini bilmiyor musunuz?'),
(2012047,68,48,4,22,'İbrahimin biri köle, biri de özgür kadından iki oğlu olduğu yazılıdır.'),
(2012048,68,48,4,23,'Köle kadından olan olağan yoldan, özgür kadından olansa vaat sonucu doğdu.'),
(2012049,68,48,4,24,'Burada bir benzetme vardır. Bu kadınlar iki antlaşmayı simgelemektedir. Biri Sina Dağındandır, köle olacak çocuklar doğurur. Bu Hacerdir.'),
(2012050,68,48,4,25,'Hacer, Arabistandaki Sina Dağını simgeler. Şimdiki Yeruşalimin karşılığıdır. Çünkü çocuklarıyla birlikte kölelik etmektedir.'),
(2012051,68,48,4,26,'Oysa göksel Yeruşalim özgürdür, annemiz odur.'),
(2012052,68,48,4,27,'Nitekim şöyle yazılmıştır: ‹‹Sevin, çocuk doğurmayan ey kısır kadın! Doğum ağrısı nedir bilmeyen sen, Yükselt sesini, haykır! Çünkü terk edilmiş kadının, Kocası olandan daha çok çocuğu var.››'),
(2012053,68,48,4,28,'Kardeşler, İshak gibi sizler de vaat çocuklarısınız.'),
(2012054,68,48,4,29,'Olağan yoldan doğan, Kutsal Ruha göre doğana o zaman nasıl zulmettiyse, şimdi de öyle oluyor.'),
(2012055,68,48,4,30,'Ama Kutsal Yazı ne diyor? ‹‹Köle kadınla oğlunu kov. Çünkü köle kadının oğlu Özgür kadının oğluyla birlikte Asla mirasa ortak olmayacaktır.››'),
(2012056,68,48,4,31,'İşte böyle, kardeşler, bizler köle kadının değil, özgür kadının çocuklarıyız.'),
(2012057,68,48,5,1,'Mesih bizi özgür olalım diye özgür kıldı. Bunun için dayanın. Bir daha kölelik boyunduruğuna girmeyin.'),
(2012058,68,48,5,2,'Bakın, ben Pavlus size diyorum ki, sünnet olursanız Mesihin size hiç yararı olmaz.'),
(2012059,68,48,5,3,'Sünnet edilen her adamı bir daha uyarıyorum: Kutsal Yasanın tümünü yerine getirmek zorundadır.'),
(2012060,68,48,5,4,'Yasa aracılığıyla aklanmaya çalışan sizler Mesihten ayrıldınız, Tanrının lütfundan uzak düştünüz.'),
(2012061,68,48,5,5,'Ama biz aklanmanın verdiği umudun gerçekleşmesini Ruha dayanarak, imanla bekliyoruz.'),
(2012062,68,48,5,6,'Mesih İsada ne sünnetliliğin ne de sünnetsizliğin yararı vardır; yararlı olan, sevgiyle etkisini gösteren imandır.'),
(2012063,68,48,5,7,'İyi koşuyordunuz. Sizi gerçeğe uymaktan kim alıkoydu?'),
(2012064,68,48,5,8,'Buna kanmanız sizi çağıranın isteği değildir.'),
(2012065,68,48,5,9,'‹‹Azıcık maya bütün hamuru kabartır.››'),
(2012066,68,48,5,10,'Başka türlü düşünmeyeceğinize ilişkin Rabde size güvenim var. Ama aklınızı karıştıran kim olursa olsun, cezasını çekecektir.'),
(2012067,68,48,5,11,'Bana gelince, kardeşler, eğer hâlâ sünneti savunuyor olsaydım, bugüne dek baskı görür müydüm? Öyle olsaydı, çarmıh engeli ortadan kalkardı.'),
(2012068,68,48,5,12,'Aklınızı çelenler keşke kendilerini hadım etseler!'),
(2012069,68,48,5,13,'Kardeşler, siz özgür olmaya çağrıldınız. Ancak özgürlük benlik için fırsat olmasın. Birbirinize sevgiyle hizmet edin.'),
(2012070,68,48,5,14,'Bütün Kutsal Yasa tek bir sözde özetlenmiştir: ‹‹Komşunu kendin gibi seveceksin.››'),
(2012071,68,48,5,15,'Ama birbirinizi ısırıp yiyorsanız, dikkat edin, birbirinizi yok etmeyesiniz!');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012072,68,48,5,16,'Şunu demek istiyorum: Kutsal Ruhun yönetiminde yaşayın. O zaman benliğin tutkularını asla yerine getirmezsiniz.'),
(2012073,68,48,5,17,'Çünkü benlik Ruha, Ruh da benliğe aykırı olanı arzular. Bunlar birbirine karşıttır; sonuç olarak, istediğinizi yapamıyorsunuz.'),
(2012074,68,48,5,18,'Ruhun yönetimindeyseniz, Yasaya bağımlı değilsiniz.'),
(2012075,68,48,5,19,'Benliğin işleri bellidir. Bunlar fuhuş, pislik, sefahat, putperestlik, büyücülük, düşmanlık, çekişme, kıskançlık, öfke, bencil tutkular, ayrılıklar, bölünmeler, çekememezlik, sarhoşluk, çılgın eğlenceler ve benzeri şeylerdir. Sizi daha önce uyardığım gibi yine uyarıyorum, böyle davrananlar Tanrı Egemenliğini miras alamayacaklar.'),
(2012076,68,48,5,22,'Ruhun ürünüyse sevgi, sevinç, esenlik, sabır, şefkat, iyilik, bağlılık, yumuşak huyluluk ve özdenetimdir. Bu tür nitelikleri yasaklayan yasa yoktur.'),
(2012077,68,48,5,24,'Mesih İsaya ait olanlar, benliği, tutku ve arzularıyla birlikte çarmıha germişlerdir.'),
(2012078,68,48,5,25,'Ruh sayesinde yaşıyorsak, Ruhun izinde yürüyelim.'),
(2012079,68,48,5,26,'Boş yere övünen, birbirine meydan okuyan, birbirini kıskanan kişiler olmayalım.'),
(2012080,68,48,6,1,'Kardeşler, eğer biri suç işlerken yakalanırsa, ruhsal olan sizler, böyle birini yumuşak ruhla yola getirin. Siz de ayartılmamak için kendinizi kollayın.'),
(2012081,68,48,6,2,'Birbirinizin yükünü taşıyın, böylece Mesihin Yasasını yerine getirirsiniz.'),
(2012082,68,48,6,3,'Kişi bir hiçken kendini bir şey sanıyorsa, kendini aldatmış olur.'),
(2012083,68,48,6,4,'Herkes kendi yaptıklarını denetlesin. O zaman başkasının yaptıklarıyla değil, yalnız kendi yaptıklarıyla övünebilir.'),
(2012084,68,48,6,5,'Herkes kendine düşen yükü taşımalı.'),
(2012085,68,48,6,6,'Tanrı sözünde eğitilen, kendisini eğitenle bütün nimetleri paylaşsın.'),
(2012086,68,48,6,7,'Aldanmayın, Tanrı alaya alınmaz. İnsan ne ekerse onu biçer.'),
(2012087,68,48,6,8,'Kendi benliğine eken, benlikten ölüm biçecektir. Ruha eken, Ruhtan sonsuz yaşam biçecektir.'),
(2012088,68,48,6,9,'İyilik yapmaktan usanmayalım. Gevşemezsek mevsiminde biçeriz.'),
(2012089,68,48,6,10,'Bunun için fırsatımız varken herkese, özellikle iman ailesinin üyelerine iyilik yapalım.'),
(2012090,68,48,6,11,'Bakın, size kendi elimle ne denli büyük harflerle yazıyorum!'),
(2012091,68,48,6,12,'Bedende gösterişe önem verenler, yalnız Mesihin çarmıhı uğruna zulüm görmemek için sizi sünnet olmaya zorluyorlar.'),
(2012092,68,48,6,13,'Oysa sünnetlilerin kendileri bile Kutsal Yasayı yerine getirmiyor, sizin bedenlerinizle övünebilmek için sünnet olmanızı istiyorlar.'),
(2012093,68,48,6,14,'Bana gelince, Rabbimiz İsa Mesihin çarmıhından başka bir şeyle asla övünmem. Onun çarmıhı aracılığıyla dünya benim için ölüdür, ben de dünya için.'),
(2012094,68,48,6,15,'Sünnetli olup olmamanın önemi yoktur, önemli olan yeni yaratılıştır.'),
(2012095,68,48,6,16,'Bu kurala uyan herkese ve Tanrının İsrailine esenlik ve merhamet olsun.'),
(2012096,68,48,6,17,'Bundan böyle kimse bana sorun çıkarmasın. Çünkü ben İsanın yara izlerini bedenimde taşıyorum.'),
(2012097,68,48,6,18,'Kardeşler, Rabbimiz İsa Mesih''in lütfu ruhunuzla birlikte olsun! Amin.'),
(2012098,68,49,1,1,'Tanrının isteğiyle Mesih İsanın elçisi atanan ben Pavlustan Efeste bulunan kutsallara, Mesih İsaya ait olan sadıklara selam!'),
(2012099,68,49,1,2,'Babamız Tanrıdan ve Rab İsa Mesihten sizlere lütuf ve esenlik olsun.'),
(2012100,68,49,1,3,'Bizi Mesihte her ruhsal kutsamayla göksel yerlerde kutsamış olan Rabbimiz İsa Mesihin Babası Tanrıya övgüler olsun.'),
(2012101,68,49,1,4,'O kendi önünde sevgide kutsal ve kusursuz olmamız için dünyanın kuruluşundan önce bizi Mesihte seçti.'),
(2012102,68,49,1,5,'Kendi isteği ve iyi amacı uyarınca İsa Mesih aracılığıyla kendisine oğullar olalım diye bizi önceden belirledi.'),
(2012103,68,49,1,6,'Öyle ki, sevgili Oğlunda bize bağışladığı yüce lütfu övülsün.'),
(2012104,68,49,1,7,'Tam bir bilgelik ve anlayışla üzerimize yağdırdığı lütfunun zenginliği sayesinde Mesihin kanı aracılığıyla Mesihte kurtuluşa, suçlarımızın bağışlanmasına kavuştuk.'),
(2012105,68,49,1,9,'Tanrı sır olan isteğini, Mesihte edindiği iyi amaç uyarınca bize açıkladı.'),
(2012106,68,49,1,10,'Zaman dolunca gerçekleştireceği bu tasarıya göre, yerdeki ve gökteki her şeyi Mesihte birleştirecek.'),
(2012107,68,49,1,11,'Her şeyi kendi isteği doğrultusunda düzenleyen Tanrının amacı uyarınca önceden belirlenip Mesihte seçildik.'),
(2012108,68,49,1,12,'Öyle ki, Mesihe ilk umut bağlayan bizler, Onun yüceliğinin övülmesi için yaşayalım.'),
(2012109,68,49,1,13,'Gerçeğin bildirisini, kurtuluşunuzun Müjdesini duyup Ona iman ettiğinizde, siz de vaat edilen Kutsal Ruhla Onda mühürlendiniz.'),
(2012110,68,49,1,14,'Ruh, Tanrının yüceliğinin övülmesi için Tanrıya ait olanların kurtuluşuna dek mirasımızın güvencesidir.'),
(2012111,68,49,1,15,'Bunun için, Rab İsaya iman ettiğinizi ve bütün kutsalları sevdiğinizi duyduğumdan beri ben de sizin için sürekli şükrediyor, sizi dualarımda hep anıyorum.'),
(2012112,68,49,1,17,'Rabbimiz İsa Mesihin Tanrısı, yüce Baba, kendisini tanımanız için size bilgelik ve vahiy ruhunu versin diye dua ediyorum.'),
(2012113,68,49,1,18,'Onun çağrısından doğan umudu, kutsallara verdiği mirasın yüce zenginliğini ve iman eden bizler için etkin olan kudretinin aşkın büyüklüğünü anlamanız için, yüreklerinizin gözleri aydınlansın diye dua ediyorum. Bu kudret, Tanrının, Mesihi ölümden diriltirken ve göksel yerlerde sağında oturturken Onda sergilediği üstün güçle aynı etkinliktedir.'),
(2012114,68,49,1,21,'Tanrı Onu bütün yönetimlerin, hükümranlıkların, güç ve egemenliklerin, yalnız bu çağda değil, gelecek çağda da anılacak bütün adların çok üstüne çıkardı.'),
(2012115,68,49,1,22,'Her şeyi ayakları altına sererek Ona bağımlı kıldı. Onu her şeyin üzerinde baş olmak üzere kiliseye verdi.'),
(2012116,68,49,1,23,'Kilise O''nun bedenidir, her yönden her şeyi dolduranın doluluğudur.'),
(2012117,68,49,2,1,'Sizler bir zamanlar içinde yaşadığınız suçlardan ve günahlardan ötürü ölüydünüz. Bu dünyanın gidişine ve havadaki hükümranlığın egemenine, yani söz dinlemeyen insanlarda şimdi etkin olan ruha uymaktaydınız.'),
(2012118,68,49,2,3,'Bir zamanlar hepimiz böyle insanların arasında, benliğin ve aklın isteklerini yerine getirerek benliğimizin tutkularına göre yaşıyorduk. Doğal olarak ötekiler gibi biz de gazap çocuklarıydık.'),
(2012119,68,49,2,4,'Ama merhameti bol olan Tanrı bizi çok sevdiği için, suçlarımızdan ötürü ölü olduğumuz halde, bizi Mesihle birlikte yaşama kavuşturdu. Onun lütfuyla kurtuldunuz.'),
(2012120,68,49,2,6,'Tanrı bizi Mesih İsada, Mesihle birlikte diriltip göksel yerlerde oturttu.'),
(2012121,68,49,2,7,'Bunu, Mesih İsada bize gösterdiği iyilikle, lütfunun sonsuz zenginliğini gelecek çağlarda sergilemek için yaptı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012122,68,49,2,8,'İman yoluyla, lütufla kurtuldunuz. Bu sizin başarınız değil, Tanrının armağanıdır.'),
(2012123,68,49,2,9,'Kimsenin övünmemesi için iyi işlerin ödülü değildir.'),
(2012124,68,49,2,10,'Çünkü biz Tanrının yapıtıyız, Onun önceden hazırladığı iyi işleri yapmak üzere Mesih İsada yaratıldık.'),
(2012125,68,49,2,11,'Bunun için, öteki uluslardan doğan sizler bir zamanlar ne olduğunuzu anımsayın: Bedende elle yapılmış sünnete sahip olup ‹‹sünnetli›› diye anılanların ‹‹sünnetsiz›› dedikleri sizler,'),
(2012126,68,49,2,12,'o zaman Mesihsiz, İsrailde vatandaşlıktan yoksun, vaade dayanan antlaşmalara yabancı, dünyada umutsuz ve tanrısızdınız.'),
(2012127,68,49,2,13,'Ama bir zamanlar uzak olan sizler, şimdi Mesih İsada Mesihin kanı sayesinde yakın kılındınız.'),
(2012128,68,49,2,14,'Çünkü Mesihin kendisi barışımızdır. Kutsal Yasayı, buyrukları ve kurallarıyla birlikte etkisiz kılarak iki topluluğu birleştirdi, aradaki engel duvarını, yani düşmanlığı kendi bedeninde yıktı. Amacı bu iki topluluktan kendisinde yeni bir insan yaratarak esenliği sağlamak, düşmanlığı çarmıhta öldürmek ve çarmıh aracılığıyla bir bedende iki topluluğu Tanrıyla barıştırmaktı.'),
(2012129,68,49,2,17,'O gelip hem uzakta olan sizlere hem de yakındakilere esenliği müjdeledi.'),
(2012130,68,49,2,18,'Onun aracılığıyla hepimiz tek Ruhta Babanın huzuruna çıkabiliriz.'),
(2012131,68,49,2,19,'Böylece artık yabancı ve garip değil, kutsallarla birlikte yurttaş ve Tanrının ev halkısınız.'),
(2012132,68,49,2,20,'Elçilerle peygamberlerden oluşan temel üzerine inşa edildiniz. Köşe taşı Mesih İsanın kendisidir.'),
(2012133,68,49,2,21,'Bütün yapı Rabbe ait kutsal bir tapınak olmak üzere Onda kenetlenip yükseliyor.'),
(2012134,68,49,2,22,'Siz de Ruh aracılığıyla Tanrı''nın konutu olmak üzere hep birlikte Mesih''te inşa ediliyorsunuz.'),
(2012135,68,49,3,1,'Bu nedenledir ki, ben Pavlus siz uluslar uğruna Mesih İsanın tutuklusu oldum.'),
(2012136,68,49,3,2,'Tanrının bana bağışladığı lütfu size ulaştırmakla görevlendirildiğimi duymuşsunuzdur.'),
(2012137,68,49,3,3,'Yukarıda kısaca değindiğim gibi Tanrı, sır olan tasarısını bana vahiy yoluyla bildirdi.'),
(2012138,68,49,3,4,'Bu mektubu okuduğunuzda Mesih sırrını nasıl kavradığımı anlayabilirsiniz.'),
(2012139,68,49,3,5,'Bu sır önceki kuşaklara açıkça bildirilmemişti. Şimdiyse Mesihin kutsal elçilerine ve peygamberlerine Ruh aracılığıyla açıklanmış bulunuyor.'),
(2012140,68,49,3,6,'Şöyle ki, öteki uluslar da mirasa ortaktır, aynı bedenin üyeleridir ve Müjde aracılığıyla Mesih İsada vaade ortaktır.'),
(2012141,68,49,3,7,'Tanrının etkin gücüyle bana verilen lütuf armağanı uyarınca bu Müjdeyi yaymakla görevlendirildim.'),
(2012142,68,49,3,8,'Bütün kutsalların en değersiziydim. Yine de Mesihin akıl ermez zenginliğini uluslara müjdeleme ve her şeyi yaratan Tanrıda öncesizlikten beri gizli tutulan sırrın nasıl düzenlendiğini bütün insanlara açıklama ayrıcalığı bana verildi.'),
(2012143,68,49,3,10,'Öyle ki, Tanrının çok yönlü bilgeliği, kilise aracılığıyla göksel yerlerdeki yönetimlere ve hükümranlıklara şimdiki dönemde bildirilsin.'),
(2012144,68,49,3,11,'Bu, Tanrının başlangıçtan beri tasarladığı ve Rabbimiz Mesih İsada yerine getirdiği amaca uygundu.'),
(2012145,68,49,3,12,'Mesihte ve Mesihe olan imanımızla Tanrıya cesaret ve güvenle yaklaşabiliriz.'),
(2012146,68,49,3,13,'Bu nedenle, uğrunuza çektiğim sıkıntılar karşısında yılmamanızı rica ediyorum. Bunlar size yücelik kazandırır.'),
(2012147,68,49,3,14,'Bunun için, yerde ve gökte her ailenin adını kendisinden aldığı Babanın önünde diz çökerim.'),
(2012148,68,49,3,16,'Babanın kendi yüceliğinin zenginliği uyarınca Ruhuyla sizi iç varlığınızda kudretle güçlendirmesini ve Mesihin iman yoluyla yüreklerinizde yaşamasını dilerim. Öyle ki, Tanrının bütün doluluğuyla dolmanız için, sevgide köklenmiş ve temellenmiş olarak bütün kutsallarla birlikte Mesihin sevgisinin ne denli geniş ve uzun, yüksek ve derin olduğunu anlamaya, bilgiyi çok aşan bu sevgiyi kavramaya gücünüz yetsin.'),
(2012149,68,49,3,20,'Tanrı, bizde etkin olan kudretiyle, dilediğimiz ya da düşündüğümüz her şeyden çok daha fazlasını yapabilecek güçtedir.'),
(2012150,68,49,3,21,'Kilisede ve Mesih İsa''da bütün kuşaklar boyunca sonsuzlara dek O''na yücelik olsun! Amin.'),
(2012151,68,49,4,1,'Bu nedenle, Rabbin uğruna tutuklu olan ben, aldığınız çağrıya yaraşır biçimde yaşamanızı rica ederim.'),
(2012152,68,49,4,2,'Her bakımdan alçakgönüllü, yumuşak huylu, sabırlı olun. Birbirinize sevgiyle, hoşgörüyle davranın.'),
(2012153,68,49,4,3,'Ruhun birliğini esenlik bağıyla korumaya gayret edin.'),
(2012154,68,49,4,4,'Çağrınızdan doğan tek bir umuda çağrıldığınız gibi, beden bir, Ruh bir, Rab bir, iman bir, vaftiz bir, her şeyden üstün, her şeyle ve her şeyde olan herkesin Tanrısı ve Babası birdir.'),
(2012155,68,49,4,7,'Ama lütuf her birimize Mesihin armağanı ölçüsünde bağışlandı.'),
(2012156,68,49,4,8,'Bunun için Kutsal Yazı şöyle der: ‹‹Yükseğe çıktı ve tutsakları peşine taktı, İnsanlara armağanlar verdi.››'),
(2012157,68,49,4,9,'Şimdi bu ‹‹çıktı›› sözcüğü, Mesih önce aşağılara, yeryüzüne indi demek değil de nedir?'),
(2012158,68,49,4,10,'İnen de Odur, her şeyi doldurmak üzere bütün göklerin çok üstüne çıkan da Odur.'),
(2012159,68,49,4,11,'Kendisi kimini elçi, kimini peygamber, kimini müjdeci, kimini önder ve öğretmen atadı.'),
(2012160,68,49,4,12,'Öyle ki, kutsallar hizmet görevini yapmak ve Mesihin bedenini geliştirmek üzere donatılsın.'),
(2012161,68,49,4,13,'Sonunda hepimiz imanda ve Tanrı Oğlunu tanımada birliğe, yetkinliğe, Mesih doluluğundaki olgunluk düzeyine erişeceğiz.'),
(2012162,68,49,4,14,'Böylece artık insanların kurnazlığıyla, aldatıcı düzenler kurmaktaki becerileriyle, her öğretinin rüzgarıyla çalkalanıp öteye beriye sürüklenen çocuklar olmayacağız.'),
(2012163,68,49,4,15,'Tersine, sevgiyle gerçeğe uyarak bedenin başı olan Mesihe doğru her yönden büyüyeceğiz.'),
(2012164,68,49,4,16,'Onun önderliğinde bütün beden, her eklemin yardımıyla kenetlenip kaynaşmış olarak her üyesinin düzenli işleyişiyle büyüyüp sevgide gelişiyor.'),
(2012165,68,49,4,17,'Bunun için şunu söylüyor ve Rab adına sizi uyarıyorum: Artık öteki uluslar gibi boş düşüncelerle yaşamayın.'),
(2012166,68,49,4,18,'Onların zihinleri karardı. Bilgisizlikleri ve yüreklerinin duygusuzluğu yüzünden Tanrının yaşamına yabancılaştılar.'),
(2012167,68,49,4,19,'Bütün duyarlılıklarını yitirip açgözlülükle her türlü pisliği yapmak üzere kendilerini sefahate verdiler.'),
(2012168,68,49,4,20,'Ama siz Mesihi böyle öğrenmediniz.'),
(2012169,68,49,4,21,'Kuşkusuz İsanın sesini duydunuz, Ondaki gerçeğe uygun olarak Onun yolunda eğitildiniz.'),
(2012170,68,49,4,22,'Önceki yaşayışınıza ait olup aldatıcı tutkularla yozlaşan eski yaradılışı üzerinizden sıyırıp atmayı, düşüncede ve ruhta yenilenmeyi,'),
(2012171,68,49,4,24,'gerçek doğruluk ve kutsallıkta Tanrıya benzer yaratılan yeni yaradılışı giyinmeyi öğrendiniz.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012172,68,49,4,25,'Bunun için yalanı üzerinizden sıyırıp atarak her biriniz komşusuna gerçeği söylesin. Çünkü hepimiz aynı bedenin üyeleriyiz.'),
(2012173,68,49,4,26,'Öfkelenin, ama günah işlemeyin. Öfkenizin üzerine güneş batmasın.'),
(2012174,68,49,4,27,'İblise de fırsat vermeyin.'),
(2012175,68,49,4,28,'Hırsızlık eden artık hırsızlık etmesin. Tersine, kendi elleriyle iyi olanı yaparak emek versin; böylece ihtiyacı olanla paylaşacak bir şeyi olsun.'),
(2012176,68,49,4,29,'Ağzınızdan hiç kötü söz çıkmasın. İşitenler yararlansın diye, ihtiyaca göre, başkalarının gelişmesine yarayacak olanı söyleyin.'),
(2012177,68,49,4,30,'Tanrının Kutsal Ruhunu kederlendirmeyin. Kurtuluş günü için o Ruhla mühürlendiniz.'),
(2012178,68,49,4,31,'Her kötü niyetle birlikte her türlü kin, öfke, kızgınlık, bağrışma ve iftira sizden uzak olsun.'),
(2012179,68,49,4,32,'Birbirinize karşı iyi yürekli, şefkatli olun. Tanrı sizi Mesih''te bağışladığı gibi, siz de birbirinizi bağışlayın.'),
(2012180,68,49,5,1,'Bunun için, sevgili çocukları olarak Tanrıyı örnek alın.'),
(2012181,68,49,5,2,'Mesih bizi nasıl sevdiyse ve bizim için kendisini güzel kokulu bir sunu ve kurban olarak nasıl Tanrıya sunduysa, siz de öylece sevgi yolunda yürüyün.'),
(2012182,68,49,5,3,'Aranızda fuhuş, pislik ya da açgözlülük anılmasın bile. Kutsallara yaraşmaz bu.'),
(2012183,68,49,5,4,'Aranızda açık saçıklık, budalaca konuşmalar, bayağı şakalar da olmasın. Bunlar size yakışmaz. Bunun yerine şükredin.'),
(2012184,68,49,5,5,'Şunu kesinlikle bilin ki, fuhuş yapanın, pisliğe düşkün olanın ya da putperest demek olan açgözlü kişinin, Mesihin ve Tanrının Egemenliğinde mirası yoktur.'),
(2012185,68,49,5,6,'Hiç kimse sizi boş sözlerle aldatmasın. Bu şeylerden ötürü Tanrının gazabı söz dinlemeyenlerin üzerine gelir.'),
(2012186,68,49,5,7,'Onun için böyleleriyle oturup kalkmayın.'),
(2012187,68,49,5,8,'Bir zamanlar karanlıktınız, ama şimdi Rabde ışıksınız. Işık çocukları olarak yaşayın.'),
(2012188,68,49,5,9,'Çünkü ışığın meyvesi her iyilikte, doğrulukta ve gerçekte görülür.'),
(2012189,68,49,5,10,'Rabbi neyin hoşnut ettiğini ayırt edin.'),
(2012190,68,49,5,11,'Karanlığın meyvesiz işlerine katılmayın. Tersine, onları açığa çıkarın.'),
(2012191,68,49,5,12,'Karanlıktakilerin gizlice yaptıklarından söz etmek bile ayıptır.'),
(2012192,68,49,5,13,'Işığın açığa vurduğu her şey görünür.'),
(2012193,68,49,5,14,'Çünkü görünen her şey ışıktır. Bunun için şöyle deniyor: ‹‹Uyan, ey uyuyan! Ölümden diril! Mesih sana ışık saçacak.››'),
(2012194,68,49,5,15,'Öyleyse nasıl yaşadığınıza çok dikkat edin. Bilgelikten yoksun olanlar gibi değil, bilgeler gibi yaşayın.'),
(2012195,68,49,5,16,'Fırsatı değerlendirin. Çünkü yaşadığımız günler kötüdür.'),
(2012196,68,49,5,17,'Bunun için akılsız olmayın, Rabbin isteğinin ne olduğunu anlayın.'),
(2012197,68,49,5,18,'Şarapla sarhoş olmayın, bu sizi sefahate götürür. Bunun yerine Ruhla dolun:'),
(2012198,68,49,5,19,'Birbirinize mezmurlar, ilahiler, ruhsal ezgiler söyleyin; yürekten Rabbe ezgiler, mezmurlar okuyun;'),
(2012199,68,49,5,20,'durmadan, her şey için Rabbimiz İsa Mesihin adıyla Baba Tanrıya şükredin;'),
(2012200,68,49,5,21,'Mesihe duyduğunuz saygıdan ötürü birbirinize bağımlı olun.'),
(2012201,68,49,5,22,'Ey kadınlar, Rabbe bağımlı olduğunuz gibi, kocalarınıza bağımlı olun.'),
(2012202,68,49,5,23,'Çünkü Mesih bedenin kurtarıcısı olarak kilisenin başı olduğu gibi, erkek de kadının başıdır.'),
(2012203,68,49,5,24,'Kilise Mesihe bağımlı olduğu gibi, kadınlar da her durumda kocalarına bağımlı olsunlar.'),
(2012204,68,49,5,25,'Ey kocalar, Mesih kiliseyi nasıl sevip onun uğruna kendini feda ettiyse, siz de karılarınızı öyle sevin.'),
(2012205,68,49,5,26,'Mesih kiliseyi suyla yıkayıp tanrısal sözle temizleyerek kutsal kılmak için kendini feda etti.'),
(2012206,68,49,5,27,'Öyle ki, kiliseyi üzerinde leke, buruşukluk ya da buna benzer bir şey olmadan, görkemli biçimde kendine sunabilsin. Amacı kilisenin kutsal ve kusursuz olmasıdır.'),
(2012207,68,49,5,28,'Aynı biçimde kocalar da karılarını kendi bedenleri gibi sevmelidir. Karısını seven kendini sever.'),
(2012208,68,49,5,29,'Hiç kimse hiçbir zaman kendi bedeninden nefret etmemiştir. Tersine, onu besler ve kayırır; tıpkı Mesihin kiliseyi besleyip kayırdığı gibi.'),
(2012209,68,49,5,30,'Çünkü bizler Onun bedeninin üyeleriyiz.'),
(2012210,68,49,5,31,'‹‹Bunun için adam annesini babasını bırakıp karısına bağlanacak, ikisi tek beden olacak.››'),
(2012211,68,49,5,32,'Bu sır büyüktür; ben bunu Mesih ve kiliseyle ilgili olarak söylüyorum.'),
(2012212,68,49,5,33,'Size gelince, her biriniz karısını kendisi gibi sevsin. Kadın da kocasına saygı göstersin.'),
(2012213,68,49,6,1,'Ey çocuklar, Rab yolunda anne babanızın sözünü dinleyin. Çünkü doğrusu budur.'),
(2012214,68,49,6,2,'‹‹İyilik bulmak, yeryüzünde uzun ömürlü olmak için annene babana saygı göstereceksin.›› Vaat içeren ilk buyruk budur.'),
(2012215,68,49,6,4,'Ey babalar, siz de çocuklarınızın öfkesini uyandırmayın. Onları Rabbin terbiye ve öğüdüyle büyütün.'),
(2012216,68,49,6,5,'Ey köleler, dünyadaki efendilerinizin sözünü Mesihin sözünü dinler gibi saygı ve korkuyla, saf yürekle dinleyin.'),
(2012217,68,49,6,6,'Bunu, yalnız insanları hoşnut etmek isteyenler gibi göze hoş görünmek için yapmayın. Mesihin kulları olarak Tanrının isteğini candan yerine getirin.'),
(2012218,68,49,6,7,'İnsanlara değil, Rabbe hizmet eder gibi gönülden hizmet edin.'),
(2012219,68,49,6,8,'Çünkü ister köle ister özgür olsun, herkesin yaptığı her iyiliğin karşılığını Rabden alacağını biliyorsunuz.'),
(2012220,68,49,6,9,'Ey efendiler, siz de kölelerinize aynı biçimde davranın. Artık onları tehdit etmeyin. Onların da sizin de Efendinizin göklerde olduğunu ve insanlar arasında ayrım yapmadığını biliyorsunuz.'),
(2012221,68,49,6,10,'Son olarak Rabde, Onun üstün gücüyle güçlenin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012222,68,49,6,11,'İblisin hilelerine karşı durabilmek için Tanrının sağladığı bütün silahları kuşanın.'),
(2012223,68,49,6,12,'Çünkü savaşımız insanlara karşı değil, yönetimlere, hükümranlıklara, bu karanlık dünyanın güçlerine, kötülüğün göksel yerlerdeki ruhsal ordularına karşıdır.'),
(2012224,68,49,6,13,'Bu nedenle, kötü günde dayanabilmek, gerekli her şeyi yaptıktan sonra yerinizde durabilmek için Tanrının bütün silahlarını kuşanın.'),
(2012225,68,49,6,14,'Böylece, belinizi gerçekle kuşatmış, göğsünüze doğruluk zırhını takmış ve ayaklarınıza esenlik Müjdesini yayma hazırlığını giymiş olarak yerinizde durun.'),
(2012226,68,49,6,16,'Bunların hepsine ek olarak, Şeytanın bütün ateşli oklarını söndürebileceğiniz iman kalkanını alın.'),
(2012227,68,49,6,17,'Kurtuluş miğferini ve Ruhun kılıcını, yani Tanrı sözünü alın.'),
(2012228,68,49,6,18,'Her türlü dua ve yalvarışla, her zaman Ruhun yönetiminde dua edin. Bu amaçla, bütün kutsallar için yalvarışta bulunarak tam bir adanmışlıkla uyanık durun.'),
(2012229,68,49,6,19,'Ağzımı her açtığımda bana gerekli söz verilsin diye benim için de dua edin; öyle ki, Müjdenin sırrını cesaretle bildirebileyim.'),
(2012230,68,49,6,20,'Uğruna zincire vurulmuş durumda elçilik ettiğim Müjdeyi gerektiği gibi cesaretle duyurabilmem için dua edin.'),
(2012231,68,49,6,21,'Nasıl olduğumu, ne yaptığımı sizin de bilmeniz için sevgili kardeşimiz, Rabbin güvenilir hizmetkârı Tihikos size her şeyi bildirecektir.'),
(2012232,68,49,6,22,'Kendisini bu amaçla, durumumuzu iletmesi ve yüreklerinize cesaret vermesi için size gönderiyorum.'),
(2012233,68,49,6,23,'Baba Tanrıdan ve Rab İsa Mesihten kardeşlere imanla birlikte esenlik ve sevgi diliyorum.'),
(2012234,68,49,6,24,'Tanrı''nın lütfu Rabbimiz İsa Mesih''i ölümsüz sevgiyle sevenlerin hepsiyle birlikte olsun.'),
(2012235,68,50,1,1,'Mesih İsanın kulları ben Pavlus ve Timoteostan Filipideki gözetmenler ve görevlilerle birlikte Mesih İsaya ait bütün kutsallara selam!'),
(2012236,68,50,1,2,'Babamız Tanrıdan ve Rab İsa Mesihten sizlere lütuf ve esenlik olsun.'),
(2012237,68,50,1,3,'Sizi hatırladıkça Tanrıma şükrediyorum.'),
(2012238,68,50,1,4,'İlk günden şimdiye dek Müjdenin yayılmasındaki işbirliğinizden dolayı her duamda hepiniz için her zaman sevinçle dilekte bulunuyorum.'),
(2012239,68,50,1,6,'Sizde iyi bir işe başlamış olan Tanrının bunu Mesih İsanın gününe dek bitireceğine güvenim var.'),
(2012240,68,50,1,7,'Hepiniz için böyle düşünmekte haklıyım. Her an yüreğimdesiniz. İster zincire vurulmuş, ister Müjdeyi savunup doğrulamakta olayım, hepiniz benimle birlikte Tanrının lütfuna ortaksınız.'),
(2012241,68,50,1,8,'Hepinizi Mesih İsanın sevgisiyle nasıl özlediğime Tanrı tanıktır.'),
(2012242,68,50,1,9,'Duam şu ki, sevginiz, bilgi ve her tür sezgiyle durmadan artsın.'),
(2012243,68,50,1,10,'Öyle ki, üstün değerleri ayırt edebilesiniz ve böylece Tanrının yüceltilip övülmesi için İsa Mesih aracılığıyla gelen doğruluk meyvesiyle dolarak Mesihin gününde saf ve kusursuz olasınız.'),
(2012244,68,50,1,12,'Kardeşler, şunu bilmenizi isterim: Başıma gelenler daha çok Müjdenin yayılmasına yaramıştır.'),
(2012245,68,50,1,13,'Sonuç olarak bütün saray muhafızları dahil, herkes Mesih uğruna zincire vurulduğumu öğrendi.'),
(2012246,68,50,1,14,'Kardeşlerin çoğu da zincire vuruluşumdan ötürü Rabbe güvenerek Tanrının sözünü korkusuzca söylemekte daha da cesur davranıyorlar.'),
(2012247,68,50,1,15,'Gerçi kimi Mesihi kıskançlık ve rekabetle, kimiyse iyi niyetle duyuruyor.'),
(2012248,68,50,1,16,'Sonuncular, Müjdeyi savunmaya atandığımı bilerek bunu sevgiyle yapıyorlar.'),
(2012249,68,50,1,17,'Ötekilerse Mesihi temiz yürekle değil, bencil tutkularla duyuruyorlar. Böylece tutukluluğumda bana sıkıntı vereceklerini sanıyorlar.'),
(2012250,68,50,1,18,'Ama ne önemi var? İster art niyetle ister içtenlikle olsun, her durumda Mesih duyurulmuş oluyor. Buna seviniyorum, sevineceğim de.'),
(2012251,68,50,1,19,'Çünkü dualarınızla ve İsa Mesihin Ruhu yardımıyla bunun bana kurtuluş getireceğini biliyorum.'),
(2012252,68,50,1,20,'Hiçbir şekilde utandırılmayacağımı, yaşasam da ölsem de Mesihin her zamanki gibi şimdi de bedenimde yüceltilmesi için tam bir cesaret gösterebileceğimi bekliyor ve umut ediyorum.'),
(2012253,68,50,1,21,'Çünkü benim için, yaşamak Mesihtir, ölmek kazançtır.'),
(2012254,68,50,1,22,'Hayatta kalırsam yararlı işler yapacağım. Ama hangisini seçeceğimi bilemiyorum.'),
(2012255,68,50,1,23,'İki seçenek arasında kaldım. Dünyadan ayrılıp Mesihle birlikte olmayı arzuluyorum; bu çok daha iyi.'),
(2012256,68,50,1,24,'Ama hayatta kalmam sizin için daha gereklidir.'),
(2012257,68,50,1,25,'Bundan emin olarak kalacağımı biliyorum. İmanda gelişip sevinmeniz için hepinizle birlikte olmaya devam edeceğim.'),
(2012258,68,50,1,26,'Öyle ki, tekrar yanınıza geldiğimde, Mesih İsada benimle daha çok övünebilesiniz.'),
(2012259,68,50,1,27,'Ancak yaşayışınız Mesihin Müjdesine layık olsun. Öyle ki, gelip sizi görsem de gelmesem de sizinle ilgili haberleri, tek bir ruhta dimdik durduğunuzu, Müjdede açıklanan inanç uğruna tek can halinde birlikte mücadele ettiğinizi, size karşı olanlardan hiçbir şekilde yılmadığınızı duyayım. Böyle davranmanız onlara bir belirtidir - kendilerinin mahvolacağını, sizlerin ise kurtulacağını gösteren bir belirti. Bu da Tanrının işidir.'),
(2012260,68,50,1,29,'Çünkü Mesih uğruna size yalnız Mesih''e iman etmek değil, daha önce bende gördüğünüz ve hâlâ sürdürdüğümü duyduğunuz zorlu çabanın aynısını göstererek Mesih uğruna acı çekmek ayrıcalığı da verildi.'),
(2012261,68,50,2,1,'Böylece Mesihten gelen bir cesaret, sevgiden doğan bir teselli ve Ruhla bir paydaşlık varsa, yürekten bir sevgi ve sevecenlik varsa, aynı düşüncede, sevgide, ruhta ve amaçta birleşerek sevincimi tamamlayın.'),
(2012262,68,50,2,3,'Hiçbir şeyi bencil tutkularla ya da boş övünmeyle yapmayın. Her biriniz alçakgönüllülükle öbürünü kendinden üstün saysın.'),
(2012263,68,50,2,4,'Yalnız kendi yararını değil, başkalarının yararını da gözetsin.'),
(2012264,68,50,2,5,'Mesih İsadaki düşünce sizde de olsun.'),
(2012265,68,50,2,6,'Mesih, Tanrı özüne sahip olduğu halde, Tanrıya eşitliği sımsıkı sarılacak bir hak saymadı.'),
(2012266,68,50,2,7,'Ama kul özünü alıp insan benzeyişinde doğarak ululuğunu bir yana bıraktı. İnsan biçimine bürünmüş olarak ölüme, çarmıh üzerinde ölüme bile boyun eğip kendini alçalttı.'),
(2012267,68,50,2,9,'Bunun için de Tanrı Onu pek çok yükseltti ve Ona her adın üstünde olan adı bağışladı.'),
(2012268,68,50,2,10,'Öyle ki, İsanın adı anıldığında gökteki, yerdeki ve yer altındakilerin hepsi diz çöksün ve her dil, Baba Tanrının yüceltilmesi için İsa Mesihin Rab olduğunu açıkça söylesin.'),
(2012269,68,50,2,12,'Öyleyse sevgili kardeşlerim, her zaman söz dinlediğiniz gibi, yalnız ben aranızdayken değil, ama özellikle aranızda olmadığım şu anda da kurtuluşunuzu saygı ve korkuyla etkin kılın.'),
(2012270,68,50,2,13,'Çünkü kendisini hoşnut edeni hem istemeniz hem de yapmanız için sizde etkin olan Tanrıdır.'),
(2012271,68,50,2,14,'Her şeyi söylenmeden ve çekişmeden yapın ki, yaşam sözüne sımsıkı sarılarak aralarında evrendeki yıldızlar gibi parladığınız bu eğri ve sapık kuşağın ortasında kusursuz ve saf, Tanrının lekesiz çocukları olasınız. Öyle ki, boşuna koşmadığımı, boşuna emek vermediğimi görerek Mesihin gününde övünecek bir nedenim olsun.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012272,68,50,2,17,'Kanım imanınızın sunusu ve hizmeti üzerine adak şarabı gibi dökülecek olsa da seviniyor, hepinizin sevincine katılıyorum.'),
(2012273,68,50,2,18,'Aynı şekilde siz de sevinin ve benim sevincime katılın.'),
(2012274,68,50,2,19,'Durumunuzu öğrenmek, böylece içimi rahatlatmak üzere yakında Timoteosu yanınıza gönderebileceğime ilişkin Rab İsada umudum var.'),
(2012275,68,50,2,20,'Timoteos gibi düşünen, durumunuzla içtenlikle ilgilenecek başka kimsem yok.'),
(2012276,68,50,2,21,'Herkes kendi işini düşünüyor, Mesih İsanınkini değil.'),
(2012277,68,50,2,22,'Ama Timoteosun, değerini kanıtlamış biri olduğunu, babasının yanında hizmet eden çocuk gibi, Müjdenin yayılması için benim yanımda hizmet ettiğini bilirsiniz.'),
(2012278,68,50,2,23,'Durumum belli olur olmaz onu size göndermeyi umuyorum.'),
(2012279,68,50,2,24,'Ben de yakında geleceğim, bu konuda Rabbe güveniyorum.'),
(2012280,68,50,2,25,'Ama muhtaç anımda bana yardım etmek üzere gönderdiğiniz elçiyi, omuz omuza mücadele verdiğim kardeşim ve emektaşım Epafroditusu size geri yollamayı gerekli gördüm.'),
(2012281,68,50,2,26,'Çünkü hepinizi özlüyor, hasta olduğunu öğrendiğiniz için çok üzülüyordu.'),
(2012282,68,50,2,27,'Gerçekten de ölecek kadar hastaydı. Ama Tanrı ona acıdı; yalnız ona değil, acı üstüne acı duymayayım diye bana da acıdı.'),
(2012283,68,50,2,28,'İşte bu nedenle, onu tekrar görüp sevinesiniz diye kendisini daha büyük bir istekle yanınıza gönderiyorum. Böylelikle benim de kaygılarım hafifleyecek.'),
(2012284,68,50,2,29,'Onu Rabde tam bir sevinçle kabul edin, onun gibi kişileri onurlandırın.'),
(2012285,68,50,2,30,'Çünkü sizin bana yapamadığınız yardımı yapmak için canını tehlikeye atarak Mesih''in işi uğruna neredeyse ölüyordu.'),
(2012286,68,50,3,1,'Sonuç olarak, kardeşlerim, Rabde sevinin. Size aynı şeyleri yazmak bana usanç vermez; hem bu sizin için bir güvencedir.'),
(2012287,68,50,3,2,'Kötülük yapan o adamlardan, o köpeklerden sakının; o sünnet bağnazlarından sakının!'),
(2012288,68,50,3,3,'Çünkü gerçek sünnetliler Tanrının Ruhu aracılığıyla tapınan, Mesih İsayla övünen, insansal özelliklere güvenmeyen bizleriz.'),
(2012289,68,50,3,4,'Ben aslında bunlara da güvenebilirdim. Eğer başka biri bunlara güvenebileceğini sanıyorsa, ben daha çok güvenebilirim.'),
(2012290,68,50,3,5,'Sekiz günlükken sünnet oldum. İsrail soyundan, Benyamin oymağından, özbeöz İbraniyim. Kutsal Yasaya bağlılık derseniz, Ferisiydim.'),
(2012291,68,50,3,6,'Gayret derseniz, kiliseye zulmeden biriydim. Yasaya dayanan doğruluk derseniz, kusursuzdum.'),
(2012292,68,50,3,7,'Ama benim için kazanç olan her şeyi Mesih uğruna zarar saydım.'),
(2012293,68,50,3,8,'Dahası var, uğruna her şeyi yitirdiğim Rabbim İsa Mesihi tanımanın üstün değeri yanında her şeyi zarar sayıyorum, süprüntü sayıyorum. Öyle ki, Mesihi kazanayım ve Kutsal Yasaya dayanan kişisel doğruluğa değil, Mesihe iman etmekle kazanılan, iman sonucu Tanrıdan gelen doğruluğa sahip olarak Mesihte bulunayım.'),
(2012294,68,50,3,10,'Ölümünde Onunla özdeşleşerek Onu tanımak, dirilişinin gücünü ve acılarına ortak olmanın ne demek olduğunu bilmek ve böylece ne yapıp yapıp ölümden dirilişe erişmek istiyorum.'),
(2012295,68,50,3,12,'Bunlara şimdiden kavuştuğumu ya da yetkinliğe eriştiğimi söylemiyorum. Ama Mesih İsanın beni kazanmakla benim için öngördüğü ödülü kazanmak için koşuyorum.'),
(2012296,68,50,3,13,'Kardeşler, kendimi bunu kazanmış saymıyorum. Ancak şunu yapıyorum: Geride kalan her şeyi unutup ileride olanlara uzanarak, Tanrının Mesih İsa aracılığıyla yaptığı göksel çağrıda öngörülen ödülü kazanmak için hedefe doğru koşuyorum.'),
(2012297,68,50,3,15,'Bunun için olgun olanlarımızın hepsi bu düşüncede olsun. Herhangi bir konuda farklı bir düşünceniz varsa, Tanrı bunu da size açıkça gösterecek.'),
(2012298,68,50,3,16,'Ancak, eriştiğimiz düzeye uygun bir yaşam sürelim.'),
(2012299,68,50,3,17,'Kardeşler, hepiniz beni örnek alın. Size verdiğimiz örnek uyarınca yaşayanlara dikkatle bakın.'),
(2012300,68,50,3,18,'Size defalarca söylediğim gibi, şimdi gözyaşları içinde tekrar söylüyorum: Birçok kişi Mesihin çarmıhına düşman olarak yaşıyor.'),
(2012301,68,50,3,19,'Onların sonu yıkımdır; tanrıları mideleridir. Ayıplarıyla övünür, yalnız bu dünyayı düşünürler.'),
(2012302,68,50,3,20,'Oysa bizim vatanımız göklerdedir. Oradan Kurtarıcıyı, Rab İsa Mesihi bekliyoruz.'),
(2012303,68,50,3,21,'O her şeyi kendine bağlı kılmaya yeten gücünün etkinliğiyle zavallı bedenlerimizi değiştirip kendi yüce bedenine benzer hale getirecektir.'),
(2012304,68,50,4,1,'Bu nedenle, ey sevgililer, sevincim, başımın tacı, içten özlediğim sevgili kardeşlerim, böylece Rabde dimdik durun.'),
(2012305,68,50,4,2,'Evodiyaya rica ediyorum, Sintihiye rica ediyorum, Rab yolunda aynı düşüncede olun.'),
(2012306,68,50,4,3,'Evet, gerçek yoldaşım, sana da yalvarırım, bu kadınlara yardım et. Çünkü onlar benimle, Klementle ve adları yaşam kitabında bulunan öbür emektaşlarımla birlikte Müjdeyi yaymak için mücadele ettiler.'),
(2012307,68,50,4,4,'Rabde her zaman sevinin; yine söylüyorum, sevinin!'),
(2012308,68,50,4,5,'Uysallığınız bütün insanlarca bilinsin. Rabbin gelişi yakındır.'),
(2012309,68,50,4,6,'Hiç kaygılanmayın; her konudaki dileklerinizi, Tanrıya dua edip yalvararak şükranla bildirin.'),
(2012310,68,50,4,7,'O zaman Tanrının her kavrayışı aşan esenliği Mesih İsa aracılığıyla yüreklerinizi ve düşüncelerinizi koruyacaktır.'),
(2012311,68,50,4,8,'Sonuç olarak, kardeşlerim, gerçek, saygıdeğer, doğru, pak, sevimli, hayranlık uyandıran, erdemli ve övülmeye değer ne varsa, onu düşünün.'),
(2012312,68,50,4,9,'Benden öğrendiğiniz, kabul ettiğiniz, işittiğiniz, bende gördüğünüz ne varsa, onu yapın. O zaman esenlik veren Tanrı sizinle olacaktır.'),
(2012313,68,50,4,10,'Bana duyduğunuz ilgiyi sonunda tazelediğiniz için Rabde çok sevindim. Aslında ilgi duyuyordunuz, ama bunu göstermeye fırsatınız olmadı.'),
(2012314,68,50,4,11,'Bunu ihtiyacım olduğu için söylemiyorum. Çünkü ben her durumda eldekiyle yetinmeyi öğrendim.'),
(2012315,68,50,4,12,'Yoksulluk çekmeyi de bilirim, bolluk içinde yaşamayı da. İster tok ister aç, ister bolluk ister ihtiyaç içinde olayım, her durumda, her koşulda yaşamanın sırrını öğrendim.'),
(2012316,68,50,4,13,'Beni güçlendirenin aracılığıyla her şeyi yapabilirim.'),
(2012317,68,50,4,14,'Yine de sıkıntılarıma ortak olmakla iyi ettiniz.'),
(2012318,68,50,4,15,'Siz de bilirsiniz, ey Filipililer, Müjde yayılmaya başladığında, Makedonyadan ayrılışımdan sonra sizden başka hiçbir topluluk karşılıklı yardımlaşma konusunda benimle işbirliği yapmadı.'),
(2012319,68,50,4,16,'Ben Selanikteyken de, ihtiyacım olduğunda birkaç kez bana yardımda bulundunuz.'),
(2012320,68,50,4,17,'Armağan peşinde değilim, ama ruhsal kazancın hesabınızda birikmesini istiyorum.'),
(2012321,68,50,4,18,'Benim her şeyim var, bolluk içindeyim. Epafroditusun eliyle gönderdiğiniz armağanları alınca bir eksiğim kalmadı. Bunlar güzel kokulu sunular, Tanrının beğenisini kazanan, Onu hoşnut eden kurbanlardır.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012322,68,50,4,19,'Tanrım da her ihtiyacınızı kendi zenginliğiyle Mesih İsada görkemli bir biçimde karşılayacaktır.'),
(2012323,68,50,4,20,'Babamız Tanrıya sonsuzlara dek yücelik olsun! Amin.'),
(2012324,68,50,4,21,'Mesih İsaya ait bütün kutsallara selam söyleyin. Yanımdaki kardeşler size selam ederler.'),
(2012325,68,50,4,22,'Bütün kutsallar, özellikle Sezarın ev halkından olanlar size selam ederler.'),
(2012326,68,50,4,23,'Rab İsa Mesih''in lütfu ruhunuzla birlikte olsun.'),
(2012327,68,51,1,1,'Tanrının isteğiyle Mesih İsanın elçisi atanan ben Pavlus ve kardeşimiz Timoteostan, Kolosede bulunan, Mesihe ait kutsal ve sadık kardeşlere selam! Babamız Tanrıdan sizlere lütuf ve esenlik olsun.'),
(2012328,68,51,1,3,'Sizler için dua ederken Tanrıya, Rabbimiz İsa Mesihin Babasına her zaman şükrediyoruz.'),
(2012329,68,51,1,4,'Çünkü Mesih İsaya iman ettiğinizi ve bütün kutsalları sevdiğinizi duyduk.'),
(2012330,68,51,1,5,'İmanınız ve sevginiz göklerde sizin için saklı bulunan umuttan kaynaklanıyor. Bu umudun haberini gerçeğin bildirisinden, size daha önce ulaşan Müjdeden aldınız. Müjde, onu işittiğiniz ve Tanrının lütfunu gerçekten anladığınız günden beri aranızda olduğu gibi, bütün dünyada da meyve vermekte, yayılmaktadır.'),
(2012331,68,51,1,7,'Müjdeyi bizim adımıza Mesihin güvenilir hizmetkârı olan sevgili emektaşımız Epafrastan öğrendiniz.'),
(2012332,68,51,1,8,'Ruhtan kaynaklanan sevginizi de bize o bildirdi.'),
(2012333,68,51,1,9,'Bunu işittiğimiz günden beri biz de sizler için dua etmekten, tam bir bilgelik ve ruhsal anlayışla Tanrının isteğini bütünüyle bilmenizi dilemekten geri kalmadık.'),
(2012334,68,51,1,10,'Rabbe yaraşır biçimde yaşamanız, Onu her yönden hoşnut etmeniz, her iyi işte meyve vererek Tanrıyı tanımakta ilerlemeniz için dua ediyoruz.'),
(2012335,68,51,1,11,'Her şeye sevinçle katlanıp sabredebilmeniz için Onun yüce gücüne dayanarak bütün kudretle güçlenmenizi diliyoruz.'),
(2012336,68,51,1,12,'Bizi kutsalların ışıktaki mirasına ortak olmaya yeterli kılan Babaya şükretmeniz için dua ediyoruz.'),
(2012337,68,51,1,13,'O bizi karanlığın hükümranlığından kurtarıp sevgili Oğlunun egemenliğine aktardı.'),
(2012338,68,51,1,14,'Onda kurtuluşa, günahlarımızın bağışına sahibiz.'),
(2012339,68,51,1,15,'Görünmez Tanrının görünümü, bütün yaratılışın ilk doğanı Odur.'),
(2012340,68,51,1,16,'Nitekim yerde ve gökte, görünen ve görünmeyen her şey -tahtlar, egemenlikler, yönetimler, hükümranlıklar- Onda yaratıldı. Her şey Onun aracılığıyla ve Onun için yaratıldı.'),
(2012341,68,51,1,17,'Her şeyden önce var olan Odur ve her şey varlığını Onda sürdürmektedir.'),
(2012342,68,51,1,18,'Bedenin, yani kilisenin başı Odur. Her şeyde ilk yeri alsın diye başlangıç olan ve ölüler arasından ilk doğan Odur.'),
(2012343,68,51,1,19,'Çünkü Tanrı bütün doluluğunun Onda bulunmasını uygun gördü.'),
(2012344,68,51,1,20,'Mesihin çarmıhta akıtılan kanı aracılığıyla esenliği sağlamış olarak yerdeki ve gökteki her şeyi Onun aracılığıyla kendisiyle barıştırmaya razı oldu.'),
(2012345,68,51,1,21,'Yaptığınız kötülükler yüzünden bir zamanlar düşüncelerinizde Tanrıya yabancı ve düşmandınız.'),
(2012346,68,51,1,22,'Şimdiyse Mesih sizi Tanrının önüne kutsal, lekesiz ve kusursuz olarak çıkarmak için öz bedeninin ölümü sayesinde sizi Tanrıyla barıştırdı.'),
(2012347,68,51,1,23,'Yeter ki, duyduğunuz Müjdenin verdiği umuttan kopmadan, imanda temellenip yerleşmiş olarak kalın. Ben Pavlus, göğün altındaki bütün yaratılışa duyurulan bu Müjdenin hizmetkârı oldum.'),
(2012348,68,51,1,24,'Sizin için acı çektiğime şimdi seviniyorum. Mesihin, kendi bedeni, yani kilise uğruna çektiği sıkıntılardan eksik kalanlarını kendi bedenimde tamamlıyorum.'),
(2012349,68,51,1,25,'Tanrının sizin yararınıza bana verdiği görevle kilisenin hizmetkârı oldum. Görevim, Tanrının sözünü, yani geçmiş çağlardan ve kuşaklardan gizlenmiş, ama şimdi Onun kutsallarına açıklanmış olan sırrı eksiksiz duyurmaktır.'),
(2012350,68,51,1,27,'Tanrı kutsallarına bu sırrın uluslar arasında ne denli yüce ve zengin olduğunu bildirmek istedi. Bu sırrın özü şudur: Mesih içinizdedir. Bu da size yüceliğe kavuşma umudunu veriyor.'),
(2012351,68,51,1,28,'Her insanı Mesihte yetkinleşmiş olarak Tanrıya sunmak için herkesi uyararak ve herkesi tam bir bilgelikle eğiterek Mesihi tanıtıyoruz.'),
(2012352,68,51,1,29,'O''nun kudretle bende etkin olan gücüne dayanarak uğraşıp emek vermemin amacı da budur.'),
(2012353,68,51,2,1,'Gerek sizler, gerek Laodikyadakiler, gerekse sizler gibi yüzümü hiç görmemiş olanlar için ne denli büyük bir uğraş verdiğimi bilmenizi isterim.'),
(2012354,68,51,2,2,'Yüreklerinin cesaret bulmasını, sevgide birleşmelerini dilerim. Öyle ki, anlayışın verdiği tam güvenliğin bütün zenginliğine kavuşsunlar ve Tanrının sırrını, yani bilginin ve bilgeliğin bütün hazinelerinin saklı olduğu Mesihi tanısınlar.'),
(2012355,68,51,2,4,'Kimse sizi kulağı okşayan sözlerle aldatmasın diye söylüyorum bunu.'),
(2012356,68,51,2,5,'Çünkü her ne kadar bedence aranızda değilsem de, ruhça sizinle birlikteyim. Düzenliliğinizi, Mesihe imanınızın sağlamlığını görüp seviniyorum.'),
(2012357,68,51,2,6,'Bu nedenle Rab Mesih İsayı nasıl kabul ettinizse, Onda öylece yaşayın.'),
(2012358,68,51,2,7,'Şükranla dolup taşarak Onda köklenin ve gelişin, size öğretildiği gibi imanda güçlenin.'),
(2012359,68,51,2,8,'Dikkatli olun! Mesihe değil de, insanların geleneğine, dünyanın temel ilkelerine dayanan felsefeyle, boş ve aldatıcı sözlerle kimse sizi tutsak etmesin.'),
(2012360,68,51,2,9,'Çünkü Tanrılığın bütün doluluğu bedence Mesihte bulunuyor.'),
(2012361,68,51,2,10,'Siz de her yönetim ve hükümranlığın başı olan Mesihte doluluğa kavuştunuz.'),
(2012362,68,51,2,11,'Ayrıca Mesihin gerçekleştirdiği sünnet sayesinde bedenin benliğinden soyunarak elle yapılmayan sünnetle Onda sünnet edildiniz.'),
(2012363,68,51,2,12,'Vaftizde Onunla birlikte gömüldünüz, Onu ölümden dirilten Tanrının gücüne iman ederek Onunla birlikte dirildiniz.'),
(2012364,68,51,2,13,'Sizler suçlarınız ve benliğinizin sünnetsizliği yüzünden ölüyken, Tanrı sizi Mesihle birlikte yaşama kavuşturdu. Bütün suçlarımızı O bağışladı.'),
(2012365,68,51,2,14,'Kurallarıyla bize karşı ve aleyhimizde olan yazılı antlaşmayı sildi, onu çarmıha çakarak ortadan kaldırdı.'),
(2012366,68,51,2,15,'Yönetimlerin ve hükümranlıkların elindeki silahları alıp onları çarmıhta yenerek açıkça gözler önüne serdi.'),
(2012367,68,51,2,16,'Bu nedenle kimse yiyecek içecek, bayram, yeni ay ya da Şabat Günü konusunda sizi yargılamasın.'),
(2012368,68,51,2,17,'Bunlar gelecek şeylerin gölgesidir, aslı ise Mesihtedir.'),
(2012369,68,51,2,18,'Sözde alçakgönüllülükte ve meleklere tapınmakta direnen, gördüğü düşlerin üzerinde durarak benliğin düşünceleriyle boş yere böbürlenen, Başa tutunmayan hiç kimse sizi ödülünüzden yoksun bırakmasın. Bütün beden eklemler ve bağlar yardımıyla bu Baştan beslenip bütünlenmekte, Tanrının sağladığı büyümeyle gelişmektedir.'),
(2012370,68,51,2,20,'Mesihle birlikte ölüp dünyanın temel ilkelerinden kurtulduğunuza göre, niçin dünyada yaşayanlar gibi, ‹‹Şunu elleme››, ‹‹Bunu tatma››, ‹‹Şuna dokunma›› gibi kurallara uyuyorsunuz?'),
(2012371,68,51,2,22,'Bu kuralların hepsi, kullanıldıkça yok olacak nesnelerle ilgilidir; insanların buyruklarına, öğretilerine dayanır.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012372,68,51,2,23,'Kuşkusuz bu kuralların gönüllü tapınma, sözde alçakgönüllülük, bedene eziyet açısından bilgece bir görünüşü vardır; ama benliğin tutkularını denetlemekte hiçbir yararları yoktur.'),
(2012373,68,51,3,1,'Mesihle birlikte dirildiğinize göre, gökteki değerlerin ardından gidin. Mesih orada, Tanrının sağında oturuyor.'),
(2012374,68,51,3,2,'Yeryüzündeki değil, gökteki değerleri düşünün.'),
(2012375,68,51,3,3,'Çünkü siz öldünüz, yaşamınız Mesihle birlikte Tanrıda saklıdır.'),
(2012376,68,51,3,4,'Yaşamınız olan Mesih göründüğü zaman, siz de Onunla birlikte yücelmiş olarak görüneceksiniz.'),
(2012377,68,51,3,5,'Bu nedenle bedenin dünyasal eğilimlerini -fuhşu, pisliği, şehveti, kötü arzuları ve putperestlikle eş olan açgözlülüğü- öldürün.'),
(2012378,68,51,3,6,'Bunlar yüzünden Tanrının gazabı söz dinlemeyenlerin üzerine geliyor.'),
(2012379,68,51,3,7,'Geçmişte bunlarla iç içe yaşadığınız zaman siz de bu yollarda yürüdünüz.'),
(2012380,68,51,3,8,'Ama şimdi öfke, kızgınlık, kötü niyet dahil, hepsini üzerinizden sıyırıp atın. Ağzınızdan hiçbir iftira ya da edepsiz söz çıkmasın.'),
(2012381,68,51,3,9,'Birbirinize yalan söylemeyin. Çünkü eski yaradılışı kötü alışkanlıklarıyla birlikte üzerinizden çıkarıp attınız;'),
(2012382,68,51,3,10,'eksiksiz bilgiye erişmek için Yaratıcısına benzer olmak üzere yenilenen yeni yaradılışı giyindiniz.'),
(2012383,68,51,3,11,'Bu yenilikte Grek ve Yahudi, sünnetli ve sünnetsiz, barbar, İskit, köle ve özgür ayrımı yoktur. Mesih her şeydir ve her şeydedir.'),
(2012384,68,51,3,12,'Öyleyse, Tanrının kutsal ve sevgili seçilmişleri olarak yürekten sevecenliği, iyiliği, alçakgönüllülüğü, sabrı, yumuşaklığı giyinin.'),
(2012385,68,51,3,13,'Birbirinize hoşgörülü davranın. Birinizin ötekinden bir şikâyeti varsa, Rabbin sizi bağışladığı gibi, siz de birbirinizi bağışlayın.'),
(2012386,68,51,3,14,'Bunların hepsinin üzerine yetkin birliğin bağı olan sevgiyi giyinin.'),
(2012387,68,51,3,15,'Mesihin esenliği yüreklerinizde hakem olsun. Tek bir bedenin üyeleri olarak bu esenliğe çağrıldınız. Şükredici olun!'),
(2012388,68,51,3,16,'Mesihin sözü bütün zenginliğiyle içinizde yaşasın. Tam bir bilgelikle birbirinize öğretin, öğüt verin, mezmurlar, ilahiler, ruhsal ezgiler söyleyerek yüreklerinizde şükranla Tanrıya nağmeler yükseltin.'),
(2012389,68,51,3,17,'Söylediğiniz, yaptığınız her şeyi Rab İsanın adıyla, Onun aracılığıyla Baba Tanrıya şükrederek yapın.'),
(2012390,68,51,3,18,'Ey kadınlar, Rabbe ait olanlara yaraşır biçimde kocalarınıza bağımlı olun.'),
(2012391,68,51,3,19,'Ey kocalar, karılarınızı sevin. Onlara sert davranmayın.'),
(2012392,68,51,3,20,'Ey çocuklar, her konuda anne babalarınızın sözünü dinleyin. Çünkü bu Rabbi hoşnut eder.'),
(2012393,68,51,3,21,'Ey babalar, çocuklarınızı incitmeyin, yoksa cesaretleri kırılır.'),
(2012394,68,51,3,22,'Ey köleler, dünyadaki efendilerinizin her sözünü dinleyin. Bunu, yalnız insanları hoşnut etmek isteyenler gibi göze hoş görünen hizmetle değil, saf yürekle, Rab korkusuyla yapın.'),
(2012395,68,51,3,23,'Rabden miras ödülünü alacağınızı bilerek, her ne yaparsanız, insanlar için değil, Rab için yapar gibi candan yapın. Rab Mesihe kulluk ediyorsunuz.'),
(2012396,68,51,3,25,'Haksızlık eden ettiği haksızlığın karşılığını alacak, hiçbir ayrım yapılmayacaktır.'),
(2012397,68,51,4,1,'Ey efendiler, gökte sizin de bir Efendiniz olduğunu bilerek kölelerinize adalet ve eşitlikle davranın.'),
(2012398,68,51,4,2,'Kendinizi duaya verin. Duada uyanık kalın, şükredin.'),
(2012399,68,51,4,3,'Aynı zamanda bizim için de dua edin ki Tanrı, sözünü yaymamız ve uğruna hapsedildiğim Mesih sırrını açıklamamız için bize bir kapı açsın.'),
(2012400,68,51,4,4,'Bu sırrı gerektiği gibi açıklıkla bildirebilmem için dua edin.'),
(2012401,68,51,4,5,'Sizden olmayanlara karşı bilgece davranın. Fırsatı değerlendirin.'),
(2012402,68,51,4,6,'Sözünüz tuzla terbiye edilmiş gibi her zaman lütufla dolu olsun. Böylece herkese nasıl karşılık vermek gerektiğini bileceksiniz.'),
(2012403,68,51,4,7,'Rab yolunda emektaşım ve güvenilir bir hizmetkâr olan sevgili kardeşimiz Tihikos, benimle ilgili her şeyi size bildirecektir.'),
(2012404,68,51,4,8,'İşte bu amaçla, durumumuzu iletmesi ve yüreklerinize cesaret vermesi için kendisini size gönderiyorum.'),
(2012405,68,51,4,9,'Onunla birlikte, sizden biri olan, güvenilir ve sevgili kardeş Onisimosu da gönderiyorum. Burada olup biten her şeyi size bildirecekler.'),
(2012406,68,51,4,10,'Hapishane arkadaşım Aristarhus ve Barnabanın yeğeni Markos size selam ederler. Markosla ilgili buyruklar aldınız; yanınıza gelirse kendisini kabul edin.'),
(2012407,68,51,4,11,'Yustus diye tanınan Yeşu da size selam eder. Tanrının Egemenliği için çalışan emektaşım Yahudiler yalnız bunlardır. Bunlar bana teselli oldular.'),
(2012408,68,51,4,12,'Sizden biri ve Mesih İsanın kulu olan Epafras size selam eder. Tanrının her isteğinden emin, yetkin kişiler olarak ayakta kalasınız diye sizin için her zaman duayla mücadele ediyor.'),
(2012409,68,51,4,13,'Gerek sizin gerekse Laodikya ve Hierapolistekiler için çok emek verdiğine tanıklık ederim.'),
(2012410,68,51,4,14,'Sevgili hekim Lukayla Dimas da size selam ederler.'),
(2012411,68,51,4,15,'Laodikyadaki kardeşlere, Nimfaya ve evindeki topluluğa selam edin.'),
(2012412,68,51,4,16,'Bu mektup aranızda okunduktan sonra Laodikya kilisesine de okutun. Siz de Laodikyadan gelecek mektubu okuyun.'),
(2012413,68,51,4,17,'Arhippusa, ‹‹Rab yolunda üstlendiğin görevi tamamlamaya dikkat et!›› deyin.'),
(2012414,68,51,4,18,'Ben Pavlus bu selamı elimle yazıyorum. Zincire vurulduğumu unutmayın. Tanrı''nın lütfu sizinle birlikte olsun.'),
(2012415,68,52,1,1,'Pavlus, Silvanus ve Timoteostan Baba Tanrıya ve Rab İsa Mesihe ait olan Selanik kilisesine selam! Sizlere lütuf ve esenlik olsun.'),
(2012416,68,52,1,2,'Dualarımızda sizleri anıyor, her zaman hepiniz için Tanrıya şükrediyoruz. İmanın ürünü olan etkinliğinizi, sevgiye dayanan emeğinizi ve Rabbimiz İsa Mesihe bağladığınız umuttan kaynaklanan dayanıklılığınızı Babamız Tanrının önünde durmadan anıyoruz.'),
(2012417,68,52,1,4,'Tanrının sevdiği kardeşlerim, sizleri Onun seçtiğini biliyoruz.'),
(2012418,68,52,1,5,'Çünkü yaydığımız Müjde size yalnız sözle değil, kudretle, Kutsal Ruhla ve büyük güvenle ulaştı. Nitekim aranızdayken sizin yararınıza nasıl yaşadığımızı bilirsiniz.'),
(2012419,68,52,1,6,'Siz de büyük sıkıntılara karşın, Kutsal Ruhun verdiği sevinçle Tanrı sözünü kabul ederek bizi ve Rabbi örnek aldınız.'),
(2012420,68,52,1,7,'Böylece Makedonya ve Ahayadaki bütün imanlılara örnek oldunuz.'),
(2012421,68,52,1,8,'Rabbin sözü sizden yayıldı. Tanrıya imanınızın haberi yalnız Makedonya ve Ahayaya değil, her yere ulaştı. Artık bizim bir şey söylememize gerek kalmadı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012422,68,52,1,9,'Çünkü herkes bizi ne kadar iyi karşıladığınızı anlatıp duruyor. Yaşayan gerçek Tanrı''ya kulluk etmek, O''nun ölümden dirilttiği ve bizleri gelecek gazaptan kurtaran Oğlu İsa''nın göklerden gelişini beklemek üzere putlardan Tanrı''ya nasıl döndüğünüzü anlatıyorlar.'),
(2012423,68,52,2,1,'Kardeşler, size yaptığımız ziyaretin boşa gitmediğini siz de biliyorsunuz.'),
(2012424,68,52,2,2,'Bildiğiniz gibi, daha önce Filipide eziyet görmüş, aşağılanmıştık. Ama şiddetli karşı koymalara rağmen, tanrısal Müjdeyi size duyurmak için Tanrımızdan cesaret aldık.'),
(2012425,68,52,2,3,'Çağrımız yalana ya da kirli bir amaca dayanmıyor; bunun hileli bir yönü de yoktur.'),
(2012426,68,52,2,4,'Tersine, Tanrı tarafından Müjdeyi emanet almaya layık görüldüğümüz için, insanları değil, yüreklerimizi sınayan Tanrıyı hoşnut edecek biçimde konuşuyoruz.'),
(2012427,68,52,2,5,'Bildiğiniz gibi, hiçbir zaman pohpohlayıcı sözlerle ya da açgözlülüğü örten bir maskeyle gelmedik. Tanrı buna tanıktır.'),
(2012428,68,52,2,6,'İnsanlardan -ne sizden ne başkalarından- gelecek övgünün peşinde de değildik.'),
(2012429,68,52,2,7,'Mesihin elçileri olarak size ağırlığımızı hissettirebilirdik. Ama çocuklarını bağrına basan bir anne gibi size şefkatle davrandık.'),
(2012430,68,52,2,8,'Sizlere öylesine gönülden bağlanmıştık ki, sizinle yalnız Tanrının Müjdesini değil, kendi canlarımızı da paylaşmaya razıydık. Çünkü sizi o denli çok sevdik!'),
(2012431,68,52,2,9,'Evet, kardeşler, nasıl uğraşıp didindiğimizi anımsarsınız. Hiçbirinize yük olmamak için gece gündüz çalıştık, Tanrının Müjdesini size duyurduk.'),
(2012432,68,52,2,10,'İman eden sizlere karşı davranışımızın ne denli kutsal, adil, kusursuz olduğuna siz tanıksınız; Tanrı da buna tanıktır.'),
(2012433,68,52,2,11,'Bildiğiniz gibi, bir baba çocuklarına nasıl davranırsa, her birinize öyle davrandık.'),
(2012434,68,52,2,12,'Sizi yüreklendirdik, teselli ettik; sizleri egemenliğine ve yüceliğine çağıran Tanrıya yaraşır biçimde yaşamaya özendirdik.'),
(2012435,68,52,2,13,'Tanrıya sürekli şükretmemiz için bir neden daha var: Tanrı sözünü bizden duyup kabul ettiğiniz zaman bunu insan sözü olarak değil, gerçekte olduğu gibi, Tanrı sözü olarak benimsediniz. Siz imanlılarda etkin olan da bu sözdür.'),
(2012436,68,52,2,14,'Çünkü kardeşler, siz Tanrının Yahudiyede bulunan ve Mesih İsaya bağlı olan kiliselerini örnek aldınız. Onların Yahudilerden çektiği sıkıntıların aynısını siz de kendi yurttaşlarınızdan çektiniz.'),
(2012437,68,52,2,15,'Rab İsayı ve peygamberleri öldüren, bize de zulmeden Yahudilerdir. Öteki uluslardan olanlarla konuşmamızı ve böylece onların kurtulmasını engellemekle Tanrının hoşnutsuzluğuna yol açıyor ve bütün insanlara karşı geliyorlar. Böylece durmadan günahlarına günah katıyorlar. Sonunda Tanrının gazabına uğradılar.'),
(2012438,68,52,2,17,'Kardeşler, kısa bir süre için düşüncede olmasa da bedende sizden ırak düştük. Ama büyük bir özlemle yüzünüzü yeniden görmek için çok çaba gösterdik.'),
(2012439,68,52,2,18,'Evet, yanınıza gelmek istiyorduk. Hele ben Pavlus, bunu birkaç kez istedim. Ama Şeytan bize engel oldu.'),
(2012440,68,52,2,19,'Umudumuz, sevincimiz kimdir? Rabbimiz İsa geldiğinde Onun önünde övüneceğimiz zafer tacı nedir? Siz değil misiniz?'),
(2012441,68,52,2,20,'Evet, övüncümüz ve sevincimiz sizsiniz.'),
(2012442,68,52,3,1,'İşte bu özleme daha fazla dayanacak halimiz kalmayınca Atinada yalnız bırakılmaya razı olduk ve Mesihin Müjdesini yayan Tanrı emektaşı kardeşimiz Timoteosu yanınıza gönderdik. Bu sıkıntılardan ötürü kimse sarsılmasın diye sizi imanda güçlendirip yüreklendirmesini istedik. Sıkıntılardan geçmek için belirlendiğimizi siz de biliyorsunuz.'),
(2012443,68,52,3,4,'Çünkü sıkıntı çekeceğimizi size önceden, daha yanınızdayken söylemiştik. Bildiğiniz gibi, öyle oldu.'),
(2012444,68,52,3,5,'Bu nedenle ben de daha fazla dayanamadım; acaba Ayartıcı bir yolunu bulup sizi ayarttı mı, emeğimiz boşa mı gitti diye iman durumunuzu öğrenmek için Timoteosu gönderdim.'),
(2012445,68,52,3,6,'Ama yanınızdan henüz dönen Timoteos, imanınıza, sevginize ilişkin bize güzel haberler getirdi. Bizi her zaman iyi anılarla hatırladığınızı, sizi görmeyi özlediğimiz kadar sizin de bizi özlediğinizi söyledi.'),
(2012446,68,52,3,7,'Bu nedenle kardeşler, bütün çile ve sıkıntılarımız arasında, imanınızdan ötürü sizinle teselli bulduk.'),
(2012447,68,52,3,8,'Çünkü siz Rabbe bağlı kalırsanız, biz asıl o zaman yaşarız.'),
(2012448,68,52,3,9,'Tanrımızın önünde sizden ötürü büyük sevinç duymaktayız. Buna karşılık Tanrımıza sizin için yeterince nasıl şükredebiliriz?'),
(2012449,68,52,3,10,'Sizinle yüz yüze görüşmek, iman konusundaki eksiklerinizi tamamlamak için gece gündüz var gücümüzle dua ediyoruz.'),
(2012450,68,52,3,11,'Babamız Tanrının kendisi ve Rabbimiz İsa size kavuşmamız için yolumuzu açsın!'),
(2012451,68,52,3,12,'Rab birbirinize ve bütün insanlara beslediğiniz sevgiyi, bizim size beslediğimiz sevgi ölçüsünde çoğaltıp artırsın!'),
(2012452,68,52,3,13,'Öyle ki, Rabbimiz İsa bütün kutsallarıyla geldiğinde, Babamız Tanrı''nın önünde kutsallıkta kusursuz olmanız için yüreklerinizi pekiştirsin.'),
(2012453,68,52,4,1,'Kardeşler, nasıl yaşamanız, Tanrıyı nasıl hoşnut etmeniz gerektiğini bizden öğrendiniz. Nitekim öyle yaşıyorsunuz. Son olarak bu konuda daha da ilerlemeniz için Rab İsa adına size rica ediyor, yalvarıyoruz.'),
(2012454,68,52,4,2,'Rab İsanın yetkisiyle size hangi buyrukları ilettiğimizi biliyorsunuz.'),
(2012455,68,52,4,3,'Tanrının isteği şudur: Kutsal olmanız, fuhuştan kaçınmanız,'),
(2012456,68,52,4,4,'her birinizin, Tanrıyı tanımayan uluslar gibi şehvet tutkusuyla değil, kutsallık ve saygınlıkla kendine bir eş alması'),
(2012457,68,52,4,6,'ve bu konuda haksızlık edip kardeşini aldatmamasıdır. Daha önce de size söylediğimiz, sizi uyardığımız gibi, Rab bütün bu suçlardan ötürü insanları cezalandıracaktır.'),
(2012458,68,52,4,7,'Çünkü Tanrı bizi ahlaksızlığa değil, kutsal bir yaşam sürmeye çağırdı.'),
(2012459,68,52,4,8,'Dolayısıyla bu çağrıyı reddeden kişi insanı değil, size Kutsal Ruhunu veren Tanrıyı reddetmiş olur.'),
(2012460,68,52,4,9,'Kardeşlik sevgisi konusunda kimsenin size bir şey yazmasına gerek yoktur. Çünkü Tanrı size birbirinizi sevmeyi öğretti.'),
(2012461,68,52,4,10,'Gerçekte bütün Makedonyadaki kardeşlerin hepsini seviyorsunuz. Kardeşler, size rica ediyoruz, bu konuda daha da ilerleyin.'),
(2012462,68,52,4,11,'Size buyurduğumuz gibi, sakin bir yaşam sürmeyi, kendi işinize bakmayı, ellerinizle çalışmayı amaç edinin.'),
(2012463,68,52,4,12,'Öyle ki, kimseye muhtaç olmadan öbür insanların önünde saygın bir yaşam süresiniz.'),
(2012464,68,52,4,13,'Kardeşler, umudu olmayan öbür insanlar gibi kederlenmemeniz için, gözlerini yaşama kapamış olanlar konusunda bilgisiz kalmanızı istemiyoruz.'),
(2012465,68,52,4,14,'İsanın ölüp dirildiğine inanıyoruz. Aynı şekilde Tanrı, İsaya bağlı olarak gözlerini yaşama kapamış olanları da Onunla birlikte geri getirecektir.'),
(2012466,68,52,4,15,'Rabbin sözüne dayanarak size diyoruz ki, biz yaşamakta olanlar, Rabbin gelişinde hayatta olanlar, gözlerini yaşama kapayanların önüne asla geçmeyeceğiz.'),
(2012467,68,52,4,16,'Rabbin kendisi, bir emir çağrısıyla, başmeleğin seslenmesiyle, Tanrının borazanıyla gökten inecek. Önce Mesihe ait ölüler dirilecek.'),
(2012468,68,52,4,17,'Sonra biz yaşamakta olanlar, hayatta olanlar, onlarla birlikte Rabbi havada karşılamak üzere bulutlar içinde alınıp götürüleceğiz. Böylece sonsuza dek Rable birlikte olacağız.'),
(2012469,68,52,4,18,'İşte birbirinizi bu sözlerle teselli edin.'),
(2012470,68,52,5,1,'Kardeşler, bu olayların zamanı ve tarihi konusunda size yazmaya gerek yoktur.'),
(2012471,68,52,5,2,'Çünkü siz de çok iyi bilirsiniz ki, Rabbin günü gece hırsız nasıl gelirse öyle gelecektir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012472,68,52,5,3,'İnsanlar, ‹‹Her şey esenlik ve güvenlik içinde›› dedikleri bir anda, gebe kadının birden sancılanması gibi, ansızın yıkıma uğrayacak ve asla kaçamayacaklar.'),
(2012473,68,52,5,4,'Ama kardeşler, siz karanlıkta değilsiniz ki, o gün sizi hırsız gibi yakalasın.'),
(2012474,68,52,5,5,'Hepiniz ışık çocukları, gündüz çocuklarısınız. Geceye ya da karanlığa ait değiliz.'),
(2012475,68,52,5,6,'Öyleyse başkaları gibi uyumayalım, ayık ve uyanık olalım.'),
(2012476,68,52,5,7,'Çünkü uyuyanlar gece uyur, sarhoş olanlar da gece sarhoş olurlar.'),
(2012477,68,52,5,8,'Gündüze ait olan bizlerse, iman ve sevgi zırhını kuşanıp başımıza miğfer olarak kurtuluş umudunu giyerek ayık duralım.'),
(2012478,68,52,5,9,'Çünkü Tanrı bizi gazaba uğrayalım diye değil, Rabbimiz İsa Mesih aracılığıyla kurtuluşa kavuşalım diye belirledi.'),
(2012479,68,52,5,10,'Mesih bizler için öldü; öyle ki, ister uyanık ister uykuda olalım, Onunla birlikte yaşayalım.'),
(2012480,68,52,5,11,'Bunun için şimdi yaptığınız gibi, birbirinizi yüreklendirip ruhça geliştirin.'),
(2012481,68,52,5,12,'Kardeşler, aranızda çalışanların, Rab yolunda size önderlik edip öğüt verenlerin değerini bilmenizi rica ederiz.'),
(2012482,68,52,5,13,'Yaptıkları işten ötürü onlara sınırsız saygı, sevgi gösterin. Birbirinizle barış içinde yaşayın.'),
(2012483,68,52,5,14,'Size yalvarırız, kardeşler, boş gezenleri uyarın, yüreksizleri cesaretlendirin, güçsüzlere destek olun, herkese karşı sabırlı olun.'),
(2012484,68,52,5,15,'Sakın kimse kötülüğe kötülükle karşılık vermesin. Birbiriniz ve bütün insanlar için her zaman iyiliği amaç edinin.'),
(2012485,68,52,5,16,'Her zaman sevinin.'),
(2012486,68,52,5,17,'Sürekli dua edin.'),
(2012487,68,52,5,18,'Her durumda şükredin. Çünkü Tanrının Mesih İsada sizin için istediği budur.'),
(2012488,68,52,5,19,'Ruhu söndürmeyin.'),
(2012489,68,52,5,20,'Peygamberlik sözlerini küçümsemeyin.'),
(2012490,68,52,5,21,'Her şeyi sınayın, iyi olana sımsıkı tutunun.'),
(2012491,68,52,5,22,'Her çeşit kötülükten kaçının.'),
(2012492,68,52,5,23,'Esenlik kaynağı olan Tanrının kendisi sizi tümüyle kutsal kılsın. Ruhunuz, canınız ve bedeniniz Rabbimiz İsa Mesihin gelişinde eksiksiz ve kusursuz olmak üzere korunsun.'),
(2012493,68,52,5,24,'Sizi çağıran Tanrı güvenilirdir; bunu yapacaktır.'),
(2012494,68,52,5,25,'Kardeşler, bizim için dua edin.'),
(2012495,68,52,5,26,'Bütün kardeşleri kutsal öpüşle selamlayın.'),
(2012496,68,52,5,27,'Rab adına size buyuruyorum, bu mektup bütün kardeşlere okunsun.'),
(2012497,68,52,5,28,'Rabbimiz İsa Mesih''in lütfu sizinle birlikte olsun.'),
(2012498,68,53,1,1,'Pavlus, Silvanus ve Timoteostan Babamız Tanrıya ve Rab İsa Mesihe ait Selanik kilisesine selam!'),
(2012499,68,53,1,2,'Baba Tanrıdan ve Rab İsa Mesihten sizlere lütuf ve esenlik olsun.'),
(2012500,68,53,1,3,'Kardeşler, sizin için her zaman Tanrıya şükran borçluyuz. Böyle yapmamız da yerindedir. Çünkü imanınız büyüdükçe büyüyor, her birinizin öbürüne olan sevgisi artıyor.'),
(2012501,68,53,1,4,'Bu nedenle bizler, katlandığınız bütün zulüm ve sıkıntılar karşısındaki sabır ve imanınızdan ötürü Tanrının kiliseleri arasında sizinle övünüyoruz.'),
(2012502,68,53,1,5,'Bütün bunlar Tanrının adil yargısının belirtisidir. Sonuç olarak, uğrunda acı çektiğiniz Tanrı Egemenliğine layık sayılacaksınız.'),
(2012503,68,53,1,6,'Tanrı adil olanı yapacak: Size sıkıntı çektirenlere sıkıntı ile karşılık verecek, sıkıntı çeken sizleriyse bizimle birlikte rahata kavuşturacaktır. Bütün bunlar Rab İsa alev alev yanan ateş içinde güçlü melekleriyle gökten gelip göründüğü zaman olacak. Rabbimiz İsa, Tanrıyı tanımayanları ve kendisiyle ilgili Müjdeye uymayanları cezalandıracak.'),
(2012504,68,53,1,9,'Böyleleri Rabbin varlığından ve yüce gücünden uzak kalarak sonsuza dek mahvolma cezasına çarptırılacaklar. Bütün bunlar Rabbin kendi kutsalları arasında yüceltilmek ve bütün imanlılarda hayranlık uyandırmak üzere geldiği gün olacak. Sizler ise iman edenlerdensiniz. Çünkü size ettiğimiz tanıklığa inandınız.'),
(2012505,68,53,1,11,'İşte bu nedenle Tanrımız sizi çağrısına layık görsün, iyiliğe yönelik her dileğinizi, imana dayanan her uğraşınızı kendi gücüyle sonuçlandırsın diye sizin için her zaman dua ediyoruz.'),
(2012506,68,53,1,12,'Öyle ki, Tanrımız''ın ve Rab İsa Mesih''in lütfuyla Rabbimiz İsa''nın adı sizde yüceltilsin, siz de O''nda yüceltilesiniz.'),
(2012507,68,53,2,1,'Rabbimiz İsa Mesihin gelişine ve Onunla birlikte olmak üzere toplanmamıza gelince: Kardeşler, size rica ediyoruz, Rabbin gününün geldiğini ileri süren herhangi bir ruh, bir söz ya da bizden gelmiş gibi gösterilen bir mektup hemen aklınızı karıştırmasın, sizi telaşlandırmasın.'),
(2012508,68,53,2,3,'Hiç kimse hiçbir şekilde sizi aldatmasın. Çünkü imandan dönüş başlamadıkça, mahvolacak olan o yasa tanımaz adam ortaya çıkmadıkça o gün gelmeyecektir.'),
(2012509,68,53,2,4,'Bu adam, tanrı diye anılan ya da tapılan her şeye karşı gelerek kendini hepsinden yüce gösterecek, hatta kendisini Tanrı ilan ederek Tanrının Tapınağında oturacaktır.'),
(2012510,68,53,2,5,'Daha yanınızdayken bunları size söylediğimi hatırlamıyor musunuz?'),
(2012511,68,53,2,6,'Zamanı gelince ortaya çıkarılacak olan bu adamı şimdilik neyin engellediğini biliyorsunuz.'),
(2012512,68,53,2,7,'Evet, yasa tanımazlığın gizli gücü şu anda bile etkindir; ama bu gücü şimdilik engelleyen ortadan kaldırılıncaya dek görevini sürdürecektir.'),
(2012513,68,53,2,8,'Sonra yasa tanımaz adam ortaya çıkacak. Rab İsa onu ağzının soluğuyla öldürecek, gelişinin görkemiyle yok edecek.'),
(2012514,68,53,2,9,'Yasa tanımaz adam, her türlü mucizede, yanıltıcı belirtilerle harikalarda ve mahvolanları aldatan her türlü kötülükte sergilenen Şeytanın etkinliğiyle gelecek. Mahvolanlar, gerçeği sevmeye ve böylece kurtulmaya yanaşmadıklarından mahvoluyorlar.'),
(2012515,68,53,2,11,'İşte bu nedenle Tanrı yalana kanmaları için onların üzerine yanıltıcı bir güç gönderiyor.'),
(2012516,68,53,2,12,'Öyle ki, gerçeğe inanmayan ve kötülükten hoşlananların hepsi yargılansın.'),
(2012517,68,53,2,13,'Ama biz, ey Rabbin sevdiği kardeşler, sizler için her zaman Tanrıya şükran borçluyuz. Çünkü Tanrı, Ruh aracılığıyla kutsal kılınıp gerçeğe inanarak kurtulmanız için sizi ta başlangıçtan seçti.'),
(2012518,68,53,2,14,'Rabbimiz İsa Mesihin yüceliğine kavuşmanız için, bildirdiğimiz Müjdeyle sizi bu kurtuluşa çağırdı.'),
(2012519,68,53,2,15,'Öyleyse dayanın, kardeşlerim! İster sözle ister mektupla, size ilettiğimiz öğretilere sımsıkı tutunun.'),
(2012520,68,53,2,16,'Rabbimiz İsa Mesih''in kendisi ve bizi sevip lütfuyla bize sonsuz cesaret ve sağlam bir umut veren Babamız Tanrı sizi yüreklendirsin, her iyi eylem ve sözde pekiştirsin.'),
(2012521,68,53,3,1,'Son olarak, kardeşler, Rabbin sözü aranızda olduğu gibi hızla yayılıp yüceltilsin diye bizim için dua edin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012522,68,53,3,2,'Ahlaksız, kötü insanlardan kurtulmamız için de dua edin. Çünkü herkes iman etmiş değildir.'),
(2012523,68,53,3,3,'Ama Rab güvenilirdir. O sizi pekiştirecek, kötü olandan koruyacaktır.'),
(2012524,68,53,3,4,'Buyurduklarımızı yaptığınıza ve yapacağınıza dair Rabde size güveniyoruz.'),
(2012525,68,53,3,5,'Rab yüreklerinizi Tanrının sevgisine, Mesihin sabrına yöneltsin.'),
(2012526,68,53,3,6,'Kardeşler, bizden aldıkları öğretilere uymayıp boş gezen bütün kardeşlerden uzak durmanızı Rab İsa Mesihin adıyla buyuruyoruz.'),
(2012527,68,53,3,7,'Bizleri nasıl örnek almanız gerektiğini kendiniz biliyorsunuz. Çünkü biz aranızdayken boş gezenler değildik.'),
(2012528,68,53,3,8,'Kimsenin ekmeğini karşılıksız yemedik. Herhangi birinize yük olmamak için uğraşıp didindik, gece gündüz çalıştık.'),
(2012529,68,53,3,9,'Yardımlarınızı hak etmediğimiz için değil, izleyebileceğiniz bir örnek bırakmak için böyle yaptık.'),
(2012530,68,53,3,10,'Hatta sizinle birlikteyken şu buyruğu vermiştik: ‹‹Çalışmak istemeyen yemek de yemesin!››'),
(2012531,68,53,3,11,'Çünkü aranızda bazılarının boş gezdiğini duyuyoruz. Bunlar hiçbir iş yapmıyor, başkalarının işine karışıp duruyorlarmış.'),
(2012532,68,53,3,12,'Böylelerine Rab İsa Mesih adına yalvarıyor, şunu buyuruyoruz: Sakin bir şekilde çalışıp kendi kazançlarından yesinler.'),
(2012533,68,53,3,13,'Sizlerse kardeşler, iyilik yapmaktan usanmayın.'),
(2012534,68,53,3,14,'Eğer bu mektuptaki sözlerimize uymayan olursa onu mimleyin. Yaptıklarından utanması için onunla ilişkinizi kesin.'),
(2012535,68,53,3,15,'Yine de onu düşman saymayın, bir kardeş olarak uyarın.'),
(2012536,68,53,3,16,'Esenlik kaynağı olan Rabbin kendisi size her zaman, her durumda esenlik versin. Rab hepinizle birlikte olsun.'),
(2012537,68,53,3,17,'Ben Pavlus bu selamı kendi elimle yazıyorum. Her mektubumun özel işaretidir bu; böyle yazarım.'),
(2012538,68,53,3,18,'Rabbimiz İsa Mesih''in lütfu hepinizle birlikte olsun.'),
(2012539,68,54,1,1,'Kurtarıcımız Tanrının ve umudumuz Mesih İsanın buyruğuyla Mesih İsanın elçisi atanan ben Pavlustan imanda öz oğlum Timoteosa selam! Baba Tanrıdan ve Rabbimiz Mesih İsadan sana lütuf, merhamet ve esenlik olsun.'),
(2012540,68,54,1,3,'Makedonyaya giderken sana rica ettiğim gibi, Efeste kal ve bazı kişilerin farklı öğretiler yaymamasını, masallarla ve sonu gelmeyen soyağaçlarıyla uğraşmamasını öğütle. Bu şeyler, imana dayanan tanrısal düzene hizmet etmekten çok, tartışmalara yol açar.'),
(2012541,68,54,1,5,'Bu buyruğun amacı, pak yürekten, temiz vicdandan, içten imandan doğan sevgiyi uyandırmaktır.'),
(2012542,68,54,1,6,'Bazı kişiler bunlardan saparak boş konuşmalara daldılar.'),
(2012543,68,54,1,7,'Kutsal Yasa öğretmeni olmak istiyorlar, ama ne söyledikleri sözleri ne de iddialı oldukları konuları anlıyorlar.'),
(2012544,68,54,1,8,'Yasayı özüne uygun biçimde kullanan için Yasanın iyi olduğunu biliyoruz.'),
(2012545,68,54,1,9,'Çünkü biliyoruz ki, Yasa doğrular için değil, yasa tanımayanlarla asiler, tanrısızlarla günahkârlar, kutsallıktan yoksunlarla kutsala karşı saygısız olanlar, anne ya da babasını öldürenler, katiller, fuhuş yapanlar, oğlancılar, köle tüccarları, yalancılar, yalan yere ant içenler ve sağlam öğretiye karşıt olan başka ne varsa onlar için konmuştur.'),
(2012546,68,54,1,11,'Mübarek Tanrının bana emanet edilen yüce Müjdesine göre bu böyledir.'),
(2012547,68,54,1,12,'Beni güçlendiren Rabbimiz Mesih İsaya şükrederim. Çünkü beni güvenilir sayarak hizmetine aldı.'),
(2012548,68,54,1,13,'Bir zamanlar Ona küfreden, zalim ve küstah biri olduğum halde bana merhamet edildi. Çünkü ne yaptıysam bilgisizlikten ve imansızlıktan yaptım.'),
(2012549,68,54,1,14,'Ama Rabbimizin lütfu, imanla ve Mesih İsada olan sevgiyle birlikte bol bol üzerime döküldü.'),
(2012550,68,54,1,15,'‹‹Mesih İsa günahkârları kurtarmak için dünyaya geldi›› sözü, güvenilir ve her bakımdan kabule layık bir sözdür. Günahkârların en kötüsü benim.'),
(2012551,68,54,1,16,'Ama Mesih İsa, kendisine iman edip sonsuz yaşama kavuşacak olanlara örnek olayım diye sınırsız sabrını öncelikle bende sergilemek için bana merhamet etti.'),
(2012552,68,54,1,17,'Onur ve yücelik sonsuzlara dek bütün çağların Kralı, ölümsüz ve görünmez tek Tanrının olsun! Amin.'),
(2012553,68,54,1,18,'Oğlum Timoteos, senin hakkında önceden söylenen peygamberlik sözleri uyarınca, bu buyruğu sana emanet ediyorum. Öyle ki, bu sözlere dayanarak iyi savaşı sürdüresin.'),
(2012554,68,54,1,19,'İmana ve temiz vicdana sarıl. Bazıları temiz vicdanı bir yana iterek iman konusunda battılar.'),
(2012555,68,54,1,20,'Himeneos ve İskender bunlardandır. Küfür etmemeyi öğrensinler diye onları Şeytan''a teslim ettim.'),
(2012556,68,54,2,1,'Her şeyden önce şunu öğütlerim: Tanrı yoluna tam bir bağlılık ve ağırbaşlılık içinde sakin ve huzurlu bir yaşam sürelim diye, krallarla bütün üst yöneticiler dahil, bütün insanlar için dilekler, dualar, yakarışlar ve şükürler sunulsun.'),
(2012557,68,54,2,3,'Böyle yapmak iyidir ve Kurtarıcımız Tanrıyı hoşnut eder.'),
(2012558,68,54,2,4,'O bütün insanların kurtulup gerçeğin bilincine erişmesini ister.'),
(2012559,68,54,2,5,'Çünkü tek Tanrı ve Tanrıyla insanlar arasında tek aracı vardır. O da insan olan ve kendisini herkes için fidye olarak sunmuş bulunan Mesih İsadır. Uygun zamanda verilen tanıklık budur.'),
(2012560,68,54,2,7,'Ben bunun habercisi ve elçisi atandım -gerçeği söylüyorum, yalan söylemiyorum- uluslara imanı ve gerçeği öğretmeye atandım.'),
(2012561,68,54,2,8,'Buna göre, erkeklerin öfkelenip çekişmeden, her yerde pak eller yükselterek dua etmelerini isterim.'),
(2012562,68,54,2,9,'Kadınların da saç örgüleriyle, altınlarla, incilerle ya da pahalı giysilerle değil, sade giyimle, edepli ve ölçülü tutumla, Tanrı yolunda yürüdüklerini ileri süren kadınlara yaraşır biçimde, iyi işlerle süslenmelerini isterim.'),
(2012563,68,54,2,11,'Kadın sükûnet ve tam bir uysallık içinde öğrensin.'),
(2012564,68,54,2,12,'Kadının öğretmesine, erkeğe egemen olmasına izin vermiyorum; sakin olsun.'),
(2012565,68,54,2,13,'Çünkü önce Adem, sonra Havva yaratıldı; aldatılan da Adem değildi, kadın aldatılıp suç işledi.'),
(2012566,68,54,2,15,'Ama doğum yapıp kurtulacaktır; yeter ki, sağduyuyla iman, sevgi ve kutsallıkta yaşasın.'),
(2012567,68,54,3,1,'İşte güvenilir söz: Bir kimse gözetmen olmayı gönülden istiyorsa, iyi bir görev arzu etmiş olur.'),
(2012568,68,54,3,2,'Ancak gözetmen ayıplanacak bir yanı olmayan, tek karılı, ölçülü, sağduyulu, saygın, konuksever, öğretmeye yetenekli biri olmalı.'),
(2012569,68,54,3,3,'Şarap düşkünü, zorba olmamalı; uysal, kavgadan ve para sevgisinden uzak olmalı.'),
(2012570,68,54,3,4,'Evini iyi yönetmeli, çocuklarına söz dinletmeli, her yönden saygılı olmalarını sağlamalı.'),
(2012571,68,54,3,5,'Kendi evini yönetmesini bilmeyen, Tanrının topluluğunu nasıl kayırabilir?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012572,68,54,3,6,'Gözetmen yeni iman etmiş biri olmamalı. Yoksa gurura kapılıp İblisin uğradığı yargıya uğrayabilir.'),
(2012573,68,54,3,7,'Topluluğun dışındakiler tarafından da iyi bir insan olarak tanınmalıdır. Öyle ki, ayıplanacak duruma ve İblisin tuzağına düşmesin.'),
(2012574,68,54,3,8,'Aynı şekilde kilise görevlileri, özü sözü ayrı, şarap tutkunu, haksız kazanç peşinde koşan kişiler değil, ağırbaşlı kişiler olmalı.'),
(2012575,68,54,3,9,'Temiz vicdanla imanın sırrına sarılmalıdırlar.'),
(2012576,68,54,3,10,'Bunlar da önce denensin; eleştirilecek bir yönleri yoksa görev alsınlar.'),
(2012577,68,54,3,11,'Aynı şekilde kadınlar ağırbaşlı olmalı; iftiracı değil, ama ölçülü ve her bakımdan güvenilir olmalı.'),
(2012578,68,54,3,12,'Görevliler tek karılı, çocuklarını ve evlerini iyi yöneten kişiler olsun.'),
(2012579,68,54,3,13,'Görevlerini iyi yapanlar, kendileri için iyi bir yer edinir, Mesih İsaya imanda büyük cesaret kazanırlar.'),
(2012580,68,54,3,14,'Yakında yanına gelmeyi umuyorum. Ama gecikirsem, gerçeğin direği ve dayanağı olan Tanrının ev halkı arasında, yani yaşayan Tanrının topluluğunda nasıl davranmak gerektiğini bilesin diye sana bunları yazıyorum.'),
(2012581,68,54,3,16,'Kuşkusuz Tanrı yolunun sırrı büyüktür. O, bedende göründü, Ruh''ça doğrulandı, Meleklerce görüldü, Uluslara tanıtıldı, Dünyada O''na iman edildi, Yücelik içinde yukarı alındı.'),
(2012582,68,54,4,1,'Ruh açıkça diyor ki, son zamanlarda bazıları yalancıların ikiyüzlülüğü nedeniyle aldatıcı ruhlara ve cinlerin öğretilerine kulak vererek imandan dönecek. Vicdanları adeta kızgın bir demirle dağlanmış bu yalancılar evlenmeyi yasaklayacak, iman edip gerçeği bilenlerin şükranla yemesi için Tanrının yarattığı yiyeceklerden çekinmek gerektiğini buyuracaklar.'),
(2012583,68,54,4,4,'Oysa Tanrının yarattığı her şey iyidir, hiçbir şey reddedilmemeli; yeter ki, şükranla kabul edilsin.'),
(2012584,68,54,4,5,'Çünkü her şey Tanrının sözüyle ve duayla kutsal kılınır.'),
(2012585,68,54,4,6,'Bunları kardeşlere öğütlersen, imanın ve izlediğin iyi öğretinin sözleriyle beslenmiş olarak Mesih İsanın iyi bir görevlisi olursun.'),
(2012586,68,54,4,7,'Kutsallıktan yoksun kocakarı masallarını reddet. Kendini Tanrı yolunda eğit.'),
(2012587,68,54,4,8,'Bedeni eğitmenin biraz yararı var; ama şimdiki ve gelecek yaşamın vaadini içeren Tanrı yolunda yürümek her yönden yararlıdır.'),
(2012588,68,54,4,9,'Bu güvenilir ve her bakımdan kabule layık bir sözdür.'),
(2012589,68,54,4,10,'Bunun için emek veriyor, mücadele ediyoruz. Çünkü umudumuzu bütün insanların, özellikle iman edenlerin Kurtarıcısı olan diri Tanrıya bağladık.'),
(2012590,68,54,4,11,'Bunları buyur ve öğret.'),
(2012591,68,54,4,12,'Gençsin diye kimse seni küçümsemesin. Konuşmada, davranışta, sevgide, imanda, paklıkta imanlılara örnek ol.'),
(2012592,68,54,4,13,'Ben yanına gelinceye dek kendini topluluğa Kutsal Yazıları okumaya, öğüt vermeye, öğretmeye ada.'),
(2012593,68,54,4,14,'Peygamberlik sözüyle, ihtiyarlar kurulunun ellerini senin üzerine koymasıyla sana verilen ve hâlâ sende olan ruhsal armağanı ihmal etme.'),
(2012594,68,54,4,15,'Bu konuların üzerinde dur, kendini bunlara ver ki, ilerlediğini herkes görsün.'),
(2012595,68,54,4,16,'Kendine ve öğretine dikkat et, bu yolda yürümeye devam et. Çünkü bunu yapmakla hem kendini hem seni dinleyenleri kurtaracaksın.'),
(2012596,68,54,5,1,'Yaşlı adama çıkışma, babanmış gibi yol göster. Genç erkeklere kardeşinmiş gibi, yaşlı kadınlara annenmiş gibi, genç kadınlara tam bir yürek temizliğiyle kızkardeşinmiş gibi yol göster.'),
(2012597,68,54,5,3,'Gerçekten kimsesiz dul kadınlara saygı göster.'),
(2012598,68,54,5,4,'Ama dul kadının çocukları ya da torunları varsa, bunlar öncelikle kendi ev halkına yardım ederek Tanrı yolunda yürümeyi ve büyüklerine iyilik borcunu ödemeyi öğrensinler. Çünkü bu Tanrıyı hoşnut eder.'),
(2012599,68,54,5,5,'Gerçekten kimsesiz, yalnız kalmış dul kadın umudunu Tanrıya bağlamıştır; gece gündüz Ona dilekte bulunmaya ve dua etmeye devam eder.'),
(2012600,68,54,5,6,'Kendini zevke veren dul kadınsa daha yaşarken ölmüştür.'),
(2012601,68,54,5,7,'Ayıplanacak duruma düşmemeleri için onları bu konularda uyar.'),
(2012602,68,54,5,8,'Kendi yakınlarına, özellikle de ev halkına bakmayan kişi imanı inkâr etmiş, imansızdan beter olmuştur.'),
(2012603,68,54,5,9,'Yaptığı iyiliklerle tanınmış, tek erkekle evlenmiş, en az altmış yaşında olan dul kadın, eğer çocuk büyütmüş, konuk ağırlamış, kutsalların ayaklarını yıkamış, sıkıntıda olanlara yardım etmiş, kendini her tür iyi işe adamışsa, adı dullar listesine yazılsın.'),
(2012604,68,54,5,11,'Daha genç dulları listeye alma. Çünkü bedensel arzuları Mesihe bağlılıklarına baskın çıkınca evlenmek isterler.'),
(2012605,68,54,5,12,'Böylece verdikleri ilk sözü çiğneyerek hüküm giyerler.'),
(2012606,68,54,5,13,'Aynı zamanda ev ev gezerek tembelliğe alışırlar. Yalnız tembelliğe alışmakla kalmazlar, üzerlerine düşmeyen sözler söyleyerek başkalarının işine karışan boşboğazlar olurlar.'),
(2012607,68,54,5,14,'Bu nedenle, daha genç dulların evlenmelerini, çocuk yapmalarını, evlerini yönetmelerini, düşmana hiçbir iftira fırsatı vermemelerini isterim.'),
(2012608,68,54,5,15,'Kimisi zaten sapmış, Şeytanın ardına düşmüştür.'),
(2012609,68,54,5,16,'İmanlı bir kadının dul yakınları varsa onlara yardım etsin. İnanlılar topluluğu yük altına girmesin ki, gerçekten kimsesiz olan dullara yardım edebilsin.'),
(2012610,68,54,5,17,'Topluluğu iyi yöneten ihtiyarlar, özellikle Tanrı sözünü duyurup öğretmeye emek verenler iki kat saygıya layık görülsün.'),
(2012611,68,54,5,18,'Çünkü Kutsal Yazıda şöyle deniyor: ‹‹Harman döven öküzün ağzını bağlama›› ve ‹‹İşçi ücretini hak eder.››'),
(2012612,68,54,5,19,'İki ya da üç tanık olmadıkça, bir ihtiyara yöneltilen suçlamayı kabul etme.'),
(2012613,68,54,5,20,'Günah işleyenleri herkesin önünde azarla ki, öbürleri de korksun.'),
(2012614,68,54,5,21,'Bu söylediklerimi yan tutmadan, kimseyi kayırmadan yerine getirmen için seni Tanrının, Mesih İsanın ve seçilmiş meleklerin önünde uyarıyorum.'),
(2012615,68,54,5,22,'Birinin üzerine ellerini koymakta aceleci davranma, başkalarının günahlarına ortak olma. Kendini temiz tut.'),
(2012616,68,54,5,23,'Artık yalnız su içmekten vazgeç; miden ve sık sık baş gösteren rahatsızlıkların için biraz da şarap iç.'),
(2012617,68,54,5,24,'Bazı kişilerin günahları bellidir, kendilerinden önce yargı kürsüsüne ulaşır. Bazılarının günahlarıysa sonradan ortaya çıkar.'),
(2012618,68,54,5,25,'Bunun gibi, iyi işler de bellidir; belli olmayanlar bile gizli kalamaz.'),
(2012619,68,54,6,1,'Kölelik boyunduruğu altında olanların hepsi kendi efendilerini tam bir saygıya layık görsünler ki, Tanrının adı ve öğretisi kötülenmesin.'),
(2012620,68,54,6,2,'Efendileri iman etmiş olanlarsa, nasıl olsa kardeşiz deyip efendilerine saygısızlık etmesinler. Tersine, daha iyi hizmet etsinler. Çünkü bu iyi hizmetten yararlananlar, sevdikleri imanlılardır. Bu ilkeleri öğret ve öğütle.'),
(2012621,68,54,6,3,'Eğer biri farklı öğretiler yayar, doğru sözleri, yani Rabbimiz İsa Mesihin sözlerini ve Tanrı yoluna dayanan öğretiyi onaylamazsa, kendini beğenmiş, bilgisiz bir kişidir. Böyle biri tartışmaları ve kelime kavgalarını hastalık derecesinde sever. Bu şeyler kıskançlığa, çekişmeye, iftiraya, kötü kuşkulara, düşünceleri yozlaşmış ve gerçeği yitirmiş kişilerin durmadan sürtüşmesine yol açar. Onlar Tanrı yolunu kazanç yolu sanıyorlar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012622,68,54,6,6,'Oysa eldekiyle yetinerek Tanrı yolunda yürümek büyük kazançtır.'),
(2012623,68,54,6,7,'Çünkü dünyaya ne bir şey getirdik, ne de ondan bir şey götürebiliriz.'),
(2012624,68,54,6,8,'Yiyeceğimiz, giyeceğimiz varsa bunlarla yetiniriz.'),
(2012625,68,54,6,9,'Zengin olmak isteyenler ayartılıp tuzağa düşerler, insanı çöküşe ve yıkıma götüren birçok saçma ve zararlı arzulara kapılırlar.'),
(2012626,68,54,6,10,'Çünkü her türlü kötülüğün bir kökü de para sevgisidir. Kimileri zengin olma hevesiyle imandan saptılar, kendi kendilerine çok acı çektirdiler.'),
(2012627,68,54,6,11,'Ama sen, ey Tanrı adamı, bu şeylerden kaç! Doğruluğun, Tanrı yolunun, imanın, sevginin, sabrın, uysallığın ardından koş.'),
(2012628,68,54,6,12,'İman uğrunda yüce mücadeleyi sürdür. Sonsuz yaşama sımsıkı sarıl. Bunun için çağrıldın ve birçok tanık önünde yüce inancı açıkça benimsedin.'),
(2012629,68,54,6,13,'Her şeye yaşam veren Tanrının ve Pontius Pilatus önünde yüce inanca tanıklık etmiş olan Mesih İsanın huzurunda sana buyuruyorum: Rabbimiz İsa Mesihin gelişine dek Tanrı buyruğunu lekesiz ve kusursuz olarak koru.'),
(2012630,68,54,6,15,'Mübarek ve tek Hükümdar, kralların Kralı, rablerin Rabbi, ölümsüzlüğün tek sahibi, yaklaşılmaz ışıkta yaşayan, hiçbir insanın görmediği ve göremeyeceği Tanrı, Mesihi belirlenen zamanda ortaya çıkaracaktır. Onur ve kudret sonsuza dek Onun olsun! Amin.'),
(2012631,68,54,6,17,'Şimdiki çağda zengin olanlara gururlanmamalarını, gelip geçici zenginliğe umut bağlamamalarını buyur. Zevk almamız için bize her şeyi bol bol veren Tanrıya umut bağlasınlar.'),
(2012632,68,54,6,18,'İyilik yapmalarını, iyilikten yana zengin, eliaçık ve paylaşmaya istekli olmalarını buyur.'),
(2012633,68,54,6,19,'Böylelikle gerçek yaşama kavuşmak üzere gelecek için kendilerine sağlam temel olacak bir hazine biriktirmiş olurlar.'),
(2012634,68,54,6,20,'Ey Timoteos, sana emanet edileni koru! Kutsallıktan yoksun, boş sözlerden, yalan yere ‹‹bilgi›› denen düşüncelerin çelişkilerinden sakın.'),
(2012635,68,54,6,21,'Kimileri bu sözde bilgiye sahip olduklarını ileri sürerek imandan saptılar. Tanrı''nın lütfu sizlerle birlikte olsun.'),
(2012636,68,55,1,1,'Mesih İsadaki yaşam vaadi uyarınca Tanrının isteğiyle Mesih İsanın elçisi atanan ben Pavlustan sevgili oğlum Timoteosa selam! Baba Tanrıdan ve Rabbimiz Mesih İsadan sana lütuf, merhamet ve esenlik olsun.'),
(2012637,68,55,1,3,'Durmadan, gece gündüz dualarımda seni anarak atalarım gibi temiz vicdanla kulluk ettiğim Tanrıya şükrediyorum.'),
(2012638,68,55,1,4,'Gözyaşlarını anımsıyor, sevinçle dolmak için seni görmeyi özlemle bekliyorum.'),
(2012639,68,55,1,5,'Sendeki içten imanı anımsıyorum. Önce büyükannen Loisin ve annen Evnikinin sahip olduğu imana şimdi senin de sahip olduğuna eminim.'),
(2012640,68,55,1,6,'Bu nedenle, ellerimi senin üzerine koymamla Tanrının sana verdiği armağanı alevlendirmen gerektiğini hatırlatıyorum.'),
(2012641,68,55,1,7,'Çünkü Tanrı bize korkaklık ruhu değil, güç, sevgi ve özdenetim ruhu vermiştir.'),
(2012642,68,55,1,8,'Bunun için Rabbimize tanıklık etmekten de Onun uğruna tutuklu bulunan benden de utanma. Tanrının gücüyle Müjde uğruna benimle birlikte sıkıntıya göğüs ger.'),
(2012643,68,55,1,9,'Tanrı bizi yaptıklarımıza göre değil, kendi amacına ve lütfuna göre kurtarıp kutsal bir yaşama çağırdı. Bu lütuf bize zamanın başlangıcından önce Mesih İsada bağışlanmış, şimdi de Onun gelişiyle açığa çıkarılmıştır. Kurtarıcımız Mesih İsa ölümü etkisiz kılmış, yaşamı ve ölümsüzlüğü Müjde aracılığıyla ışığa çıkarmıştır.'),
(2012644,68,55,1,11,'Ben Müjdenin habercisi, elçisi ve öğretmeni atandım.'),
(2012645,68,55,1,12,'Bu acıları çekmemin nedeni de budur. Ama bundan utanmıyorum. Çünkü kime inandığımı biliyorum. Onun bana emanet ettiğini o güne dek koruyacak güçte olduğuna eminim.'),
(2012646,68,55,1,13,'Benden işitmiş olduğun doğru sözleri örnek alarak imanla ve Mesih İsada olan sevgiyle bunlara bağlı kal.'),
(2012647,68,55,1,14,'Sana emanet edilen iyi öğretileri içimizde yaşayan Kutsal Ruh aracılığıyla koru.'),
(2012648,68,55,1,15,'Biliyorsun, Asya İlindekilerin hepsi beni terk edip gittiler. Figelosla Hermogenis de bunlardandır.'),
(2012649,68,55,1,16,'Rab, Onisiforosun ev halkına merhamet etsin. Çünkü o çok kez içimi ferahlattı ve zincire vurulmuş olmamdan utanmadı.'),
(2012650,68,55,1,17,'Tersine, Romaya geldiğinde beni gayretle arayıp buldu.'),
(2012651,68,55,1,18,'O gün Rab''den merhamet bulmasını dilerim. Efes''te onun bana ne kadar hizmet ettiğini sen de çok iyi bilirsin.'),
(2012652,68,55,2,1,'Oğlum, Mesih İsada olan lütufla güçlen.'),
(2012653,68,55,2,2,'Birçok tanık önünde benden işittiğin sözleri, başkalarına da öğretmeye yeterli olacak güvenilir kişilere emanet et.'),
(2012654,68,55,2,3,'Mesih İsanın iyi bir askeri olarak benimle birlikte sıkıntıya göğüs ger.'),
(2012655,68,55,2,4,'Askerlik yapan kişi günlük yaşamla ilgili işlere karışmaz; kendisini askerliğe çağıranı hoşnut etmeye çalışır.'),
(2012656,68,55,2,5,'Bunun gibi, spor yarışmasına katılan kişi de kurallar uyarınca yarışmazsa zafer tacını giyemez.'),
(2012657,68,55,2,6,'Emek veren çiftçi üründen ilk payı alan kişi olmalıdır.'),
(2012658,68,55,2,7,'Dediklerimi iyi düşün. Rab sana her konuda anlayış verecektir.'),
(2012659,68,55,2,8,'Yaydığım Müjdede açıklandığı gibi, Davutun soyundan olup ölümden dirilmiş olan İsa Mesihi anımsa.'),
(2012660,68,55,2,9,'Bu Müjde uğruna bir suçlu gibi zincire vurulmaya kadar varan sıkıntılara katlanıyorum. Ama Tanrının sözü zincire vurulmuş değildir.'),
(2012661,68,55,2,10,'Bunun içindir ki, seçilmişler uğruna her şeye dayanıyorum. Öyle ki, onlar da sonsuz yüceliğin yanısıra Mesih İsada olan kurtuluşa kavuşsunlar.'),
(2012662,68,55,2,11,'Şu güvenilir bir sözdür: ‹‹Onunla birlikte öldüysek, Onunla birlikte yaşayacağız.'),
(2012663,68,55,2,12,'Dayanırsak, Onunla birlikte egemenlik süreceğiz. Onu inkâr edersek, O da bizi inkâr edecek.'),
(2012664,68,55,2,13,'Biz sadık kalmasak da, O sadık kalacak. Çünkü kendi özüne aykırı davranamaz.››'),
(2012665,68,55,2,14,'Bu konuları imanlılara anımsat. Dinleyenleri felakete sürüklemekten başka yararı olmayan kelime kavgaları çıkarmamaları için onları Tanrının önünde uyar.'),
(2012666,68,55,2,15,'Kendini Tanrıya makbul, gerçeğin bildirisini doğru kullanan, alnı ak bir işçi olarak sunmaya gayret et.'),
(2012667,68,55,2,16,'Bayağı, boş sözlerden sakın. Çünkü bunlara dalanlar tanrısızlıkta daha da ileri gidecekler.'),
(2012668,68,55,2,17,'Sözleri kangren gibi yayılacak. Himeneosla Filitos bunlardandır.'),
(2012669,68,55,2,18,'Diriliş olup bitti diyerek gerçek yoldan saptılar. Şimdi de bazılarının imanını altüst ediyorlar.'),
(2012670,68,55,2,19,'Ne var ki, Tanrının attığı sağlam temel, ‹‹Rab kendine ait olanları bilir›› ve ‹‹Rabbin adını anan herkes kötülükten uzak dursun›› sözleriyle mühürlenmiş olarak duruyor.'),
(2012671,68,55,2,20,'Büyük bir evde yalnız altın ve gümüş kaplar bulunmaz; tahta ve toprak kaplar da vardır. Kimi onurlu, kimi bayağı iş için kullanılır.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012672,68,55,2,21,'Bunun gibi, kişi de kendini bayağı işlerden arıtırsa, onurlu amaçlara uygun, kutsal kılınmış, efendisine yararlı, her iyi işe hazır bir kap olur.'),
(2012673,68,55,2,22,'Gençlik arzularından kaç. Temiz yürekle Rabbe yakaranlarla birlikte doğruluğun, imanın, sevginin ve esenliğin ardından koş.'),
(2012674,68,55,2,23,'Saçma, cahilce tartışmalara girmeyi reddet. Bunların kavga doğurduğunu bilirsin.'),
(2012675,68,55,2,24,'Rabbin kulu kavgacı olmamalı. Tersine, herkese şefkatle davranmalı, öğretme yeteneği olmalı, haksızlıklara sabırla dayanmalıdır.'),
(2012676,68,55,2,25,'Kendisine karşı olanları yumuşak huyla yola getirmeli. Gerçeği anlamaları için Tanrı belki onlara bir tövbe yolu açar.'),
(2012677,68,55,2,26,'Böylelikle ayılabilir, isteğini yerine getirmeleri için kendilerini tutsak eden İblis''in tuzağından kurtulabilirler.'),
(2012678,68,55,3,1,'Şunu bil ki, son günlerde çetin anlar olacaktır.'),
(2012679,68,55,3,2,'İnsanlar kendilerini seven, para düşkünü, övüngen, kibirli, küfürbaz, anne baba sözü dinlemez, nankör, kutsallıktan ve sevgiden yoksun, uzlaşmaz, iftiracı, özünü denetleyemeyen, azgın, iyilik düşmanı olacaklar.'),
(2012680,68,55,3,4,'Hain, aceleci, kendini beğenmiş, Tanrıdan çok eğlenceyi seven, Tanrı yolundaymış gibi görünüp bu yolun gücünü inkâr edenler olacaklar. Böylelerinden uzak dur.'),
(2012681,68,55,3,6,'Bunların arasında evlerin içine sokulup günahla yüklü, çeşitli arzularla sürüklenen, her zaman öğrenen, ama gerçeğin bilgisine bir türlü erişemeyen zayıf iradeli kadınları adeta tutsak eden adamlar var.'),
(2012682,68,55,3,8,'Yannisle Yambris nasıl Musaya karşı geldilerse, bunlar da gerçeğe karşı gelirler. Düşünceleri yozlaşmış, iman konusunda reddedilmiş insanlardır.'),
(2012683,68,55,3,9,'Ama daha ileri gidemeyecekler. Çünkü Yannisle Yambris örneğindeki gibi, bunların da akılsızlığını herkes açıkça görecektir.'),
(2012684,68,55,3,10,'Sense benim öğretimi, davranışımı, amacımı, imanımı, sabrımı, sevgimi, dayanma gücümü, çektiğim zulüm ve acıları, örneğin Antakyada, Konyada ve Listrada başıma gelenleri yakından izledin. Ne zulümlere katlandım! Ama Rab beni hepsinden kurtardı.'),
(2012685,68,55,3,12,'Mesih İsaya ait olup Tanrı yoluna yaraşır bir yaşam sürmek isteyenlerin hepsi zulüm görecek.'),
(2012686,68,55,3,13,'Ama kötüler ve sahtekârlar, aldatarak ve aldanarak gittikçe daha beter olacaklar.'),
(2012687,68,55,3,14,'Sense öğrendiğin ve güvendiğin ilkelere bağlı kal. Çünkü bunları kimlerden öğrendiğini biliyorsun. Mesih İsaya iman aracılığıyla seni bilge kılıp kurtuluşa kavuşturacak güçte olan Kutsal Yazıları da çocukluğundan beri biliyorsun.'),
(2012688,68,55,3,16,'Kutsal Yazıların tümü Tanrı esinlemesidir ve öğretmek, azarlamak, yola getirmek, doğruluk konusunda eğitmek için yararlıdır.'),
(2012689,68,55,3,17,'Bunlar sayesinde Tanrı adamı her iyi iş için donatılmış olarak yetkin olur.'),
(2012690,68,55,4,1,'Tanrının ve dirilerle ölüleri yargılayacak olan Mesih İsanın önünde, Onun gelişi ve egemenliği hakkı için sana buyuruyorum: Tanrı sözünü duyur. Zaman uygun olsun olmasın, bu görevi sürdür. İnsanları tam bir sabırla eğiterek ikna et, uyar, isteklendir.'),
(2012691,68,55,4,3,'Çünkü öyle bir zaman gelecek ki, sağlam öğretiye katlanamayacaklar. Kulaklarını okşayan sözler duymak için çevrelerine kendi arzularına uygun öğretmenler toplayacaklar.'),
(2012692,68,55,4,4,'Kulaklarını gerçeğe tıkayıp masallara sapacaklar.'),
(2012693,68,55,4,5,'Ama sen her durumda ayık ol, sıkıntıya göğüs ger, müjdeci olarak işini yap, görevini tamamla.'),
(2012694,68,55,4,6,'Çünkü kanım adak şarabı gibi dökülmek üzere. Benim için ayrılma zamanı geldi.'),
(2012695,68,55,4,7,'Yüce mücadeleyi sürdürdüm, yarışı bitirdim, imanı korudum.'),
(2012696,68,55,4,8,'Bundan böyle doğruluk tacı benim için hazır duruyor. Adil yargıç olan Rab o gün bu tacı bana, yalnız bana değil, Onun gelişini özlemle beklemiş olanların hepsine verecektir.'),
(2012697,68,55,4,9,'Yanıma tez gelmeye gayret et.'),
(2012698,68,55,4,10,'Çünkü Dimas bu dünyayı sevdiği için beni terk edip Selanike gitti. Kriskis Galatyaya, Titus Dalmaçyaya gitti.'),
(2012699,68,55,4,11,'Yanımda yalnız Luka var. Markosu alıp beraberinde getir, yapacağım hizmette bana yardım eder.'),
(2012700,68,55,4,12,'Tihikosu Efese gönderdim.'),
(2012701,68,55,4,13,'Troasta Karpın yanında bıraktığım abayı, kitapları, özellikle yazı derilerini gelirken beraberinde getir.'),
(2012702,68,55,4,14,'Bakırcı İskender bana çok kötülük etti. Rab ona yaptıklarının karşılığını verecektir.'),
(2012703,68,55,4,15,'Sen de ondan sakın. Çünkü söylediklerimize şiddetle karşı koydu.'),
(2012704,68,55,4,16,'İlk savunmamda benden yana çıkan olmadı, hepsi beni terk etti. Bunun hesabı onlardan sorulmasın.'),
(2012705,68,55,4,17,'Ama Tanrı bildirisi aracılığımla tam olarak açıklansın, bütün uluslar bunu duysun diye Rab yardımıma gelip beni güçlendirdi. Aslanın ağzından böyle kurtuldum!'),
(2012706,68,55,4,18,'Rab beni her kötülükten kurtarıp güvenlik içinde göksel egemenliğine ulaştıracak. Sonsuzlara dek Ona yücelik olsun! Amin.'),
(2012707,68,55,4,19,'Priska, Akvila ve Onisiforosun ev halkına selam söyle.'),
(2012708,68,55,4,20,'Erastus, Korintte kaldı. Trofimosu da Milette hasta bıraktım.'),
(2012709,68,55,4,21,'Kış bastırmadan gelmeye gayret et. Evvulus, Pudens, Linus, Klavdiya ve bütün kardeşler sana selam ederler.'),
(2012710,68,55,4,22,'Rab ruhunla birlikte olsun. Tanrı''nın lütfu sizlerle olsun.'),
(2012711,68,56,1,1,'Tanrının seçtiği kişilerin iman etmeleri, Tanrı yoluna uygun gerçeği anlamaları için Tanrının kulu ve İsa Mesihin elçisi atanan ben Pavlustan selam!'),
(2012712,68,56,1,2,'Elçiliğim, yalan söylemeyen Tanrının zamanın başlangıcından önce vaat ettiği sonsuz yaşam umuduna dayanmaktadır.'),
(2012713,68,56,1,3,'Kurtarıcımız Tanrının buyruğuyla bana emanet edilen bildiride Tanrı, kendi sözünü uygun zamanda açıklamıştır.'),
(2012714,68,56,1,4,'Ortak imanımıza göre öz oğlum olan Titusa Baba Tanrıdan ve Kurtarıcımız Mesih İsadan lütuf ve esenlik olsun.'),
(2012715,68,56,1,5,'Geri kalan işleri düzene sokman ve sana buyurduğum gibi her kentte ihtiyarlar ataman için seni Giritte bıraktım.'),
(2012716,68,56,1,6,'İhtiyar seçilecek kişi eleştirilecek yönü olmayan, tek karılı biri olsun. Çocukları imanlı olmalı, sefahatle suçlanan ya da asi çocuklar olmamalı.'),
(2012717,68,56,1,7,'Gözetmen, Tanrı evinin kâhyası olduğuna göre, eleştirilecek yönü olmamalı. Dikbaşlı, tez öfkelenen, şarap düşkünü, zorba, haksız kazanç peşinde koşan biri olmamalı.'),
(2012718,68,56,1,8,'Tersine, konuksever, iyiliksever, sağduyulu, adil, pak, kendini denetleyebilen biri olmalı.'),
(2012719,68,56,1,9,'Hem başkalarını sağlam öğretiyle yüreklendirmek, hem de karşı çıkanları ikna edebilmek için imanlılara öğretilen güvenilir söze sımsıkı sarılmalı.'),
(2012720,68,56,1,10,'Çünkü asi, boşboğaz, aldatıcı birçok kişi vardır. Özellikle sünnet yanlıları bunlardandır.'),
(2012721,68,56,1,11,'Onların ağzını kapamak gerek. Haksız kazanç uğruna, öğretmemeleri gerekeni öğreterek bazı aileleri tümüyle yıkıyorlar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012722,68,56,1,12,'Kendilerinden biri, öz peygamberlerinden biri şöyle demiştir: ‹‹Giritliler hep yalancıdır, azgın canavarlar, tembel oburlardır.››'),
(2012723,68,56,1,13,'Bu tanıklık doğrudur. Bu nedenle, Yahudi masallarına, gerçeği reddedenlerin buyruklarına kulak vermeyip sağlam imana sahip olmaları için onları sert bir şekilde uyar.'),
(2012724,68,56,1,15,'Yüreği temiz olanlar için her şey temizdir, ama yüreği kirli olanlar ve imansızlar için hiçbir şey temiz değildir. Çünkü onların zihinleri de vicdanları da kirlenmiştir.'),
(2012725,68,56,1,16,'Tanrı''yı tanıdıklarını ileri sürer, ama yaptıklarıyla O''nu yadsırlar. Söz dinlemez, hiçbir iyi işe yaramaz iğrenç kişilerdir.'),
(2012726,68,56,2,1,'Sana gelince, sağlam öğretiye uygun olanı öğret.'),
(2012727,68,56,2,2,'Yaşlı erkeklere ölçülü, ağırbaşlı, sağduyulu olmalarını buyur. İmanda, sevgide ve sabırda sağlam olsunlar.'),
(2012728,68,56,2,3,'Aynı şekilde yaşlı kadınlar saygın bir yaşam sürmeli. İftiracı, şaraba tutsak olmamalı; iyi olanı öğretmeli.'),
(2012729,68,56,2,4,'Öyle ki genç kadınları, kocalarını ve çocuklarını seven, sağduyulu, temiz yürekli, iyi birer ev kadını ve kocalarına bağımlı olmak üzere eğitebilsinler. O zaman Tanrının sözü kötülenmez.'),
(2012730,68,56,2,6,'Genç erkekleri de sağduyulu olmaya özendir.'),
(2012731,68,56,2,7,'İyi olanı yaparak her konuda onlara örnek ol. Öğretişinde dürüst ve ağırbaşlı ol, kimsenin kınayamayacağı doğru sözler söyle. Öyle ki bize karşı gelen, hakkımızda söyleyecek kötü bir söz bulamayıp utansın.'),
(2012732,68,56,2,9,'Köleleri, her konuda efendilerine bağımlı olmaya özendir. Efendilerini hoşnut etsinler. Ters yanıt vermeden,'),
(2012733,68,56,2,10,'hırsızlık yapmadan, tümüyle güvenilir olduklarını göstersinler. Böylece Kurtarıcımız Tanrıyla ilgili öğretiyi her yönden çekici kılsınlar.'),
(2012734,68,56,2,11,'Çünkü Tanrının bütün insanlara kurtuluş sağlayan lütfu ortaya çıkmıştır.'),
(2012735,68,56,2,12,'Bu lütuf, tanrısızlığı ve dünyasal arzuları reddedip şimdiki çağda sağduyulu, doğru, Tanrı yoluna yaraşır bir yaşam sürebilmemiz için bizi eğitiyor.'),
(2012736,68,56,2,13,'Bu arada, mübarek umudumuzun gerçekleşmesini, ulu Tanrı ve Kurtarıcımız İsa Mesihin yücelik içinde gelmesini bekliyoruz.'),
(2012737,68,56,2,14,'Mesih bizi her suçtan kurtarmak, arıtıp kendisine ait, iyilik etmekte gayretli bir halk yapmak üzere kendini bizim için feda etti.'),
(2012738,68,56,2,15,'Bunları tam bir yetkiyle bildir, dinleyenleri isteklendir, günahlı olanları ikna et. Hiç kimse seni küçümsemesin.'),
(2012739,68,56,3,1,'Yöneticilerle yönetimlere bağlı olmaları, söz dinlemeleri ve iyi olan her şeyi yapmaya hazır olmaları gerektiğini imanlılara anımsat.'),
(2012740,68,56,3,2,'Kimseyi kötülemesinler. Kavgacı değil, uysal olsunlar. Herkese her zaman yumuşak davransınlar.'),
(2012741,68,56,3,3,'Çünkü bir zamanlar biz de anlayışsız, söz dinlemez, kolay aldanan, türlü arzulara ve zevklere köle olan, kötülük ve kıskançlık içinde yaşayan, nefret edilen ve birbirimizden nefret eden kişilerdik.'),
(2012742,68,56,3,4,'Ama Kurtarıcımız Tanrı iyiliğini ve insana olan sevgisini açıkça göstererek bizi kurtardı. Bunu doğrulukla yaptığımız işlerden dolayı değil, kendi merhametiyle, yeniden doğuş yıkamasıyla ve Kurtarıcımız İsa Mesih aracılığıyla üzerimize bol bol döktüğü Kutsal Ruhun yenilemesiyle yaptı.'),
(2012743,68,56,3,7,'Öyle ki, Onun lütfuyla aklanmış olarak umut içinde sonsuz yaşamın mirasçıları olalım.'),
(2012744,68,56,3,8,'Bu güvenilir bir sözdür. Tanrıya iman etmiş olanların, kendilerini iyi işlere vermeye özen göstermeleri için bu konularda ısrarlı olmanı istiyorum. Bunlar insan için iyi ve yararlıdır.'),
(2012745,68,56,3,9,'Akılsız tartışmalardan, soyağacı didişmelerinden, Kutsal Yasayla ilgili çekişme ve kavgalardan sakın. Bunlar yararsız ve boş şeylerdir.'),
(2012746,68,56,3,10,'Birinci ve ikinci uyarıdan sonra bölücü kişiyle ilişkini kes.'),
(2012747,68,56,3,11,'Böyle birinin sapmış olduğundan ve günah işlediğinden emin olabilirsin; o kendi kendini mahkûm etmiştir.'),
(2012748,68,56,3,12,'Ben Arteması ya da Tihikosu sana gönderir göndermez, Nikopolise, yanıma gelmeye gayret et. Çünkü kışı orada geçirmeye karar verdim.'),
(2012749,68,56,3,13,'Hukukçu Zenasla Apollosu yolcu ederken bir eksikleri olmamasına dikkat et.'),
(2012750,68,56,3,14,'Bizimkiler de kendilerini iyi işlere vermeyi öğrensinler. Böylelikle temel ihtiyaçları karşılamış ve verimsiz bir yaşam sürmemiş olurlar.'),
(2012751,68,56,3,15,'Yanımdakilerin hepsi sana selam eder. Bizi seven imanlılara selam söyle. Tanrı''nın lütfu hepinizle birlikte olsun.'),
(2012752,68,57,1,1,'Sevgili emektaşımız Filimon, Mesih İsa uğruna tutuklu olan ben Pavlus ve kardeşimiz Timoteostan sana, kızkardeşimiz Afiyaya, birlikte mücadele verdiğimiz Arhippusa ve senin evindeki inanlılar topluluğuna selam!'),
(2012753,68,57,1,3,'Babamız Tanrıdan ve Rab İsa Mesihten sizlere lütuf ve esenlik olsun.'),
(2012754,68,57,1,4,'Rab İsaya olan imanını ve bütün kutsallara beslediğin sevgiyi duydukça dualarımda seni anıyor, Tanrıma sürekli şükrediyorum.'),
(2012755,68,57,1,6,'Mesihte sahip olduğumuz her iyiliğin bilincine vararak imanını başkalarıyla paylaşmakta etkin olman için dua ediyorum.'),
(2012756,68,57,1,7,'Sevgin benim için büyük sevinç ve teselli kaynağı oldu. Çünkü kutsalların yürekleri senin sayende ferahladı, kardeşim.'),
(2012757,68,57,1,8,'Bu nedenle, gerekeni sana buyurmaya Mesihte büyük cesaretim olduğu halde, şimdi Mesih İsa uğruna tutuklu bulunan ben yaşlı Pavlus sana sevgiyle rica etmeyi yeğliyorum.'),
(2012758,68,57,1,10,'Tutukluluğum sırasında kendisine ruhsal baba olduğum oğlum Onisimosla ilgili bir ricam var. Bir zamanlar sana yararsızdı; ama şimdi hem sana hem de bana yararlıdır.'),
(2012759,68,57,1,12,'Kendisini, yani can ciğerimi sana geri gönderiyorum.'),
(2012760,68,57,1,13,'Müjdenin uğruna tutuklu kaldığım sürece senin yerine bana hizmet etmesi için onu yanımda alıkoymak isterdim; ama senin onayın olmadan bir şey yapmak istemedim. Öyle ki, yapacağın iyilik zorunluluktanmış gibi görünmesin, gönülden olsun.'),
(2012761,68,57,1,15,'Onisimosun bir süre senden ayrılması belki de onu temelli geri alman içindi.'),
(2012762,68,57,1,16,'Onu artık köle değil, köleden üstün, sevgili bir kardeş olarak geri alacaksın. O, özellikle benim için çok değerlidir. Ama hem bir insan, hem de Rabbe ait biri olarak senin için daha da çok sevilecek bir kardeştir.'),
(2012763,68,57,1,17,'Bu nedenle, eğer beni yoldaşın sayıyorsan, kendisini beni kabul eder gibi kabul et.'),
(2012764,68,57,1,18,'Sana herhangi bir haksızlık etmişse ya da bir borcu varsa, bunu benim hesabıma say.'),
(2012765,68,57,1,19,'Ben Pavlus bunu kendi elimle yazıyorum, bedelini ben öderim. Senin kendi yaşamını bile bana borçlu olduğunu söylememe gerek yok.'),
(2012766,68,57,1,20,'Evet, kardeş, Rab yolunda bana bir yardımın olsun. Mesihte yüreğimi ferahlat.'),
(2012767,68,57,1,21,'Sözümü dinleyeceğinden emin olarak ve istediğimden fazlasını da yapacağını bilerek sana yazıyorum.'),
(2012768,68,57,1,22,'Bu arada bana kalabileceğim bir yer hazırla. Çünkü dualarınız aracılığıyla sizlere bağışlanacağımı umuyorum.'),
(2012769,68,57,1,23,'Mesih İsa uğruna kendisiyle birlikte tutuklu bulunduğum Epafras, emektaşlarım Markos, Aristarhus, Dimas ve Luka sana selam ederler.'),
(2012770,68,57,1,25,'Rab İsa Mesih''in lütfu ruhunuzla birlikte olsun.'),
(2012771,68,58,1,1,'Tanrı eski zamanlarda peygamberler aracılığıyla birçok kez çeşitli yollardan atalarımıza seslendi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012772,68,58,1,2,'Bu son çağda da her şeye mirasçı kıldığı ve aracılığıyla evreni yarattığı kendi Oğluyla bize seslenmiştir.'),
(2012773,68,58,1,3,'Oğul, Tanrı yüceliğinin parıltısı, Onun varlığının öz görünümüdür. Güçlü sözüyle her şeyi devam ettirir. Günahlardan arınmayı sağladıktan sonra, yücelerde ulu Tanrının sağında oturdu.'),
(2012774,68,58,1,4,'Meleklerden ne denli üstün bir adı miras aldıysa, onlardan o denli üstün oldu.'),
(2012775,68,58,1,5,'Çünkü Tanrı meleklerin herhangi birine, ‹‹Sen benim Oğlumsun, Bugün ben sana Baba oldum›› Ya da, ‹‹Ben Ona Baba olacağım, O da bana Oğul olacak››'),
(2012776,68,58,1,6,'Yine Tanrı ilk doğanı dünyaya gönderirken diyor ki, ‹‹Tanrının bütün melekleri Ona tapınsın.››'),
(2012777,68,58,1,7,'Melekler için, ‹‹Kendi meleklerini rüzgar, Hizmetkârlarını ateş alevi yapar›› diyor.'),
(2012778,68,58,1,8,'Ama Oğul için şöyle diyor: ‹‹Ey Tanrı, tahtın sonsuzluklar boyunca kalıcıdır, Egemenliğinin asası adalet asasıdır.'),
(2012779,68,58,1,9,'Doğruluğu sevdin, kötülükten nefret ettin. Bunun için Tanrı, senin Tanrın, Seni sevinç yağıyla Arkadaşlarından daha çok meshetti.››'),
(2012780,68,58,1,10,'Yine diyor ki, ‹‹Ya Rab, başlangıçta Dünyanın temellerini sen attın. Gökler de senin ellerinin yapıtıdır.'),
(2012781,68,58,1,11,'Onlar yok olacak, ama sen kalıcısın. Hepsi bir giysi gibi eskiyecek.'),
(2012782,68,58,1,12,'Bir kaftan gibi düreceksin onları, Bir giysi gibi değiştirilecekler. Ama sen hep aynısın, Yılların tükenmeyecek.››'),
(2012783,68,58,1,13,'Tanrı meleklerin herhangi birine, ‹‹Ben düşmanlarını Ayaklarının altına serinceye dek, Sağımda otur››'),
(2012784,68,58,1,14,'Bütün melekler kurtuluşu miras alacaklara hizmet etmek için gönderilen görevli ruhlar değil midir?'),
(2012785,68,58,2,1,'Bu nedenle, akıntıya kapılıp sürüklenmemek için işittiklerimizi daha çok önemsemeliyiz.'),
(2012786,68,58,2,2,'Çünkü melekler aracılığıyla bildirilen söz geçerli olduysa, her suç ve her sözdinlemezlik hak ettiği karşılığı aldıysa, bu denli büyük kurtuluşu görmezlikten gelirsek nasıl kurtulabiliriz? Başlangıçta Rab tarafından bildirilen bu kurtuluş, Rabbi dinlemiş olanlarca bize doğrulandı.'),
(2012787,68,58,2,4,'Tanrı da belirtiler, harikalar, çeşitli mucizeler ve kendi isteği uyarınca dağıttığı Kutsal Ruh armağanlarıyla buna tanıklık etti.'),
(2012788,68,58,2,5,'Tanrı, sözünü ettiğimiz gelecek dünyayı meleklere bağlı kılmadı.'),
(2012789,68,58,2,6,'Ama biri bir yerde şöyle tanıklık etmiştir: ‹‹Ya Rab, insan ne ki, onu anasın, Ya da insanoğlu ne ki, ona ilgi gösteresin?'),
(2012790,68,58,2,7,'Onu meleklerden biraz aşağı kıldın, Başına yücelik ve onur tacını koydun, Ellerinin yapıtları üzerine onu görevlendirdin.'),
(2012791,68,58,2,8,'Her şeyi ayakları altına sererek Ona bağımlı kıldın.›› bırakmadı. Ne var ki, her şeyin insana bağımlı kılındığını henüz görmüyoruz.'),
(2012792,68,58,2,9,'Ama meleklerden biraz aşağı kılınmış olan İsayı, Tanrının lütfuyla herkes için ölümü tatsın diye çektiği ölüm acısı sonucunda yücelik ve onur tacı giydirilmiş olarak görüyoruz.'),
(2012793,68,58,2,10,'Birçok oğulu yüceliğe eriştirirken onların kurtuluş öncüsünü acılarla yetkinliğe erdirmesi, her şeyi kendisi için ve kendi aracılığıyla var eden Tanrıya uygun düşüyordu.'),
(2012794,68,58,2,11,'Çünkü hepsi -kutsal kılan da kutsal kılınanlar da- aynı Babadandır. Bunun içindir ki, İsa onlara ‹‹kardeşlerim›› demekten utanmıyor.'),
(2012795,68,58,2,12,'‹‹Adını kardeşlerime duyuracağım, Topluluğun ortasında Seni ilahilerle öveceğim›› diyor.'),
(2012796,68,58,2,13,'Yine, ‹‹Ben Ona güveneceğim›› ve yine, ‹‹İşte ben ve Tanrının bana verdiği çocuklar›› diyor.'),
(2012797,68,58,2,14,'Bu çocuklar etten ve kandan oldukları için İsa, ölüm gücüne sahip olanı, yani İblisi, ölüm aracılığıyla etkisiz kılmak üzere onlarla aynı insan yapısını aldı.'),
(2012798,68,58,2,15,'Bunu, ölüm korkusu yüzünden yaşamları boyunca köle olanların hepsini özgür kılmak için yaptı.'),
(2012799,68,58,2,16,'Kuşkusuz O, meleklere değil, İbrahimin soyundan olanlara yardım ediyor.'),
(2012800,68,58,2,17,'Bunun için her yönden kardeşlerine benzemesi gerekiyordu. Öyle ki, Tanrıya hizmetinde merhametli ve sadık bir başkâhin olup halkın günahlarını bağışlatabilsin.'),
(2012801,68,58,2,18,'Çünkü kendisi denenip acı çektiği için denenenlere yardım edebilir.'),
(2012802,68,58,3,1,'Bunun için, göksel çağrıya ortak olan kutsal kardeşlerim, dikkatinizi açıkça benimsediğimiz inancın elçisi ve başkâhini İsaya çevirin.'),
(2012803,68,58,3,2,'Musa Tanrının bütün evinde Tanrıya nasıl sadık kaldıysa, İsa da kendisini görevlendirene sadıktır.'),
(2012804,68,58,3,3,'Evi yapan nasıl evden daha çok saygı görürse, İsa da Musadan daha büyük yüceliğe layık sayıldı.'),
(2012805,68,58,3,4,'Her evin bir yapıcısı vardır, her şeyin yapıcısı ise Tanrıdır.'),
(2012806,68,58,3,5,'Musa, gelecekte söylenecek sözlere tanıklık etmek için Tanrının bütün evinde bir hizmetkâr olarak sadık kaldı.'),
(2012807,68,58,3,6,'Oysa Mesih, Onun evi üzerinde yetkili oğul olarak sadıktır. Eğer cesaretimizi ve övündüğümüz umudu gevşemeden sonuna dek sürdürürsek, Onun evi biziz.'),
(2012808,68,58,3,7,'Bu nedenle, Kutsal Ruhun dediği gibi, ‹‹Bugün Onun sesini duyarsanız, Atalarınızın başkaldırdığı, Çölde Onu sınadığı günkü gibi Yüreklerinizi nasırlaştırmayın.'),
(2012809,68,58,3,9,'Atalarınız beni orada sınayıp denediler Ve kırk yıl boyunca yaptıklarımı gördüler.'),
(2012810,68,58,3,10,'Bu nedenle o kuşağa darıldım Ve dedim ki, ‹Yürekleri hep kötüye sapar, Yollarımı öğrenmediler.'),
(2012811,68,58,3,11,'Öfkelendiğimde ant içtiğim gibi, Onlar huzur diyarıma asla girmeyecekler.› ››'),
(2012812,68,58,3,12,'Ey kardeşler, hiçbirinizde diri Tanrıyı terk eden kötü, imansız bir yüreğin bulunmamasına dikkat edin.'),
(2012813,68,58,3,13,'‹‹Gün bugündür›› denildikçe birbirinizi her gün yüreklendirin. Öyle ki, hiçbirinizin yüreği günahın aldatıcılığıyla nasırlaşmasın.'),
(2012814,68,58,3,14,'Çünkü Mesihe ortak olduk. Yalnız başlangıçtaki güvenimizi gevşemeden sonuna dek sürdürmeliyiz.'),
(2012815,68,58,3,15,'Yukarıda belirtildiği gibi, ‹‹Bugün Onun sesini duyarsanız, Atalarınızın başkaldırdığı günkü gibi Yüreklerinizi nasırlaştırmayın.››'),
(2012816,68,58,3,16,'Onun sesini işitip başkaldıran kimlerdi? Musa önderliğinde Mısırdan çıkanların hepsi değil mi?'),
(2012817,68,58,3,17,'Tanrı kimlere kırk yıl dargın kaldı? Günah işleyip cesetleri çöle serilenlere değil mi?'),
(2012818,68,58,3,18,'Sözünü dinlemeyenler dışında kendi huzur diyarına kimlerin girmeyeceğine ant içti?'),
(2012819,68,58,3,19,'Görüyoruz ki, imansızlıklarından ötürü oraya giremediler.'),
(2012820,68,58,4,1,'Bu nedenle Tanrının huzur diyarına girme vaadi hâlâ geçerliyken, herhangi birinizin buna erişmemiş sayılmasından korkalım.'),
(2012821,68,58,4,2,'Çünkü onlar gibi biz de iyi haberi aldık. Ama onlar duydukları sözü imanla birleştirmedikleri için bunun kendilerine bir yararı olmadı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012822,68,58,4,3,'Biz inanmış olanlar huzur diyarına gireriz. Nitekim Tanrı şöyle demiştir: ‹‹Öfkelendiğimde ant içtiğim gibi, Onlar huzur diyarıma asla girmeyecekler.››'),
(2012823,68,58,4,4,'Çünkü bir yerde yedinci günle ilgili şunu demiştir: ‹‹Tanrı bütün işlerinden yedinci gün dinlendi.››'),
(2012824,68,58,4,5,'Bu konuda yine diyor ki, ‹‹Onlar huzur diyarıma asla girmeyecekler.››'),
(2012825,68,58,4,6,'Demek ki, bazılarının huzur diyarına gireceği kesindir. Daha önce iyi haberi almış olanlar söz dinlemedikleri için o diyara giremediler.'),
(2012826,68,58,4,7,'Bu yüzden Tanrı, uzun zaman sonra Davutun aracılığıyla, ‹‹bugün›› diyerek yine bir gün belirliyor. Daha önce denildiği gibi, ‹‹Bugün Onun sesini duyarsanız, Yüreklerinizi nasırlaştırmayın.››'),
(2012827,68,58,4,8,'Eğer Yeşu onları huzura kavuştursaydı, Tanrı daha sonra bir başka günden söz etmezdi.'),
(2012828,68,58,4,9,'Böylece Tanrı halkı için bir Şabat Günü rahatı kalıyor.'),
(2012829,68,58,4,10,'Tanrı işlerinden nasıl dinlendiyse, Onun huzur diyarına giren de kendi işlerinden öylece dinlenir.'),
(2012830,68,58,4,11,'Bu nedenle o huzur diyarına girmeye gayret edelim; öyle ki, hiçbirimiz aynı tür sözdinlemezlikten ötürü düşmesin.'),
(2012831,68,58,4,12,'Tanrının sözü diri ve etkilidir, iki ağızlı kılıçtan daha keskindir. Canla ruhu, ilikle eklemleri birbirinden ayıracak kadar derinlere işler; yüreğin düşüncelerini, amaçlarını yargılar.'),
(2012832,68,58,4,13,'Tanrının görmediği hiçbir yaratık yoktur. Kendisine hesap vereceğimiz Tanrının gözü önünde her şey çıplak ve açıktır.'),
(2012833,68,58,4,14,'Tanrı Oğlu İsa gökleri aşan büyük başkâhinimiz olduğu için açıkça benimsediğimiz inanca sımsıkı sarılalım.'),
(2012834,68,58,4,15,'Çünkü başkâhinimiz zayıflıklarımızda bize yakınlık duyamayan biri değildir; tersine, her alanda bizim gibi denenmiş, ama günah işlememiştir.'),
(2012835,68,58,4,16,'Onun için Tanrı''nın lütuf tahtına cesaretle yaklaşalım; öyle ki, yardım gereksindiğimizde merhamet görelim ve lütuf bulalım.'),
(2012836,68,58,5,1,'İnsanlar arasından seçilen her başkâhin, günahlara karşılık sunular ve kurbanlar sunmak üzere Tanrıyla ilgili konularda insanları temsil etmek için atanır.'),
(2012837,68,58,5,2,'Bilgisizlere, yoldan sapanlara yumuşak davranabilir. Çünkü kendisi de zayıflıklarla kuşatılmıştır.'),
(2012838,68,58,5,3,'Bundan ötürü, halk için olduğu gibi, kendisi için de günah sunusu sunmak zorundadır.'),
(2012839,68,58,5,4,'Kimse başkâhin olma onurunu kendi kendine alamaz; ancak Harun gibi, Tanrı tarafından çağrılırsa alır.'),
(2012840,68,58,5,5,'Nitekim Mesih de başkâhin olmak için kendi kendini yüceltmedi. Ona, ‹‹Sen benim Oğlumsun, Bugün ben sana Baba oldum››'),
(2012841,68,58,5,6,'Başka bir yerde de diyor ki, ‹‹Melkisedek düzeni uyarınca Sen sonsuza dek kâhinsin.››'),
(2012842,68,58,5,7,'Mesih, yeryüzünde olduğu günlerde kendisini ölümden kurtaracak güçte olan Tanrıya büyük feryat ve gözyaşlarıyla dua etti, yakardı ve Tanrı korkusu nedeniyle işitildi.'),
(2012843,68,58,5,8,'Oğul olduğu halde, çektiği acılarla söz dinlemeyi öğrendi.'),
(2012844,68,58,5,9,'Yetkin kılınınca, sözünü dinleyen herkes için sonsuz kurtuluş kaynağı oldu.'),
(2012845,68,58,5,10,'Çünkü Tanrı tarafından Melkisedek düzeni uyarınca başkâhin atanmıştı.'),
(2012846,68,58,5,11,'Bu konuda söyleyecek çok sözümüz var, ama kulaklarınız uyuştuğu için anlatmak zor.'),
(2012847,68,58,5,12,'Şimdiye dek öğretmen olmanız gerekirken, Tanrı sözlerinin temel ilkelerini size yeni baştan öğretecek birine ihtiyacınız var. Size yine süt gerekli, katı yiyecek değil!'),
(2012848,68,58,5,13,'Sütle beslenen herkes bebektir ve doğruluk sözünde deneyimsizdir.'),
(2012849,68,58,5,14,'Katı yiyecek, yetişkinler içindir; onlar duyularını iyi ile kötüyü ayırt etmek üzere alıştırmayla eğitmiş kişilerdir.'),
(2012850,68,58,6,1,'Bunun için, ölü işlerden tövbe etmenin ve Tanrıya inanmanın temelini, vaftizler, elle kutsama, ölülerin dirilişi ve sonsuz yargıyla ilgili öğretinin temelini yeni baştan atmadan Mesihle ilgili ilk öğretileri aşarak yetkinliğe doğru ilerleyelim.'),
(2012851,68,58,6,3,'Tanrı izin verirse, bunu yapacağız.'),
(2012852,68,58,6,4,'Bir kez aydınlatılmış, göksel armağanı tatmış ve Kutsal Ruha ortak edilmiş, Tanrı sözünün iyiliğini ve gelecek çağın güçlerini tatmış oldukları halde yoldan sapanları yeniden tövbe edecek duruma getirmeye olanak yoktur. Çünkü onlar Tanrının Oğlunu adeta yeniden çarmıha geriyor, herkesin önünde aşağılıyorlar.'),
(2012853,68,58,6,7,'Üzerine sık sık yağan yağmuru emen ve kimler için işleniyorsa onlara yararlı bitkiler üreten toprağı Tanrı bereketli kılar.'),
(2012854,68,58,6,8,'Ama dikenli bitki, devedikeni üreten toprak yararsızdır; lanetlenmeye yakındır, sonu yanmaktır.'),
(2012855,68,58,6,9,'Size gelince, sevgili kardeşler, böyle konuştuğumuz halde, durumunuzun daha iyi olduğuna, kurtuluşa uygun düştüğüne eminiz.'),
(2012856,68,58,6,10,'Tanrı adaletsiz değildir; emeğinizi ve kutsallara hizmet etmiş olarak ve etmeye devam ederek Onun adına gösterdiğiniz sevgiyi unutmaz.'),
(2012857,68,58,6,11,'Umudunuzdan doğan tam güvenceye kavuşmanız için her birinizin sona dek aynı gayreti göstermesini diliyoruz.'),
(2012858,68,58,6,12,'Tembel olmamanızı, vaat edilenleri iman ve sabır aracılığıyla miras alanların örneğine uymanızı istiyoruz.'),
(2012859,68,58,6,13,'Tanrı İbrahime vaatte bulunduğu zaman, üzerine ant içecek daha üstün biri olmadığı için kendi üzerine ant içerek şöyle dedi:'),
(2012860,68,58,6,14,'‹‹Seni kutsadıkça kutsayacağım, Soyunu çoğalttıkça çoğaltacağım.››'),
(2012861,68,58,6,15,'Böylece İbrahim sabırla dayanarak vaade erişti.'),
(2012862,68,58,6,16,'İnsanlar kendilerinden üstün biri üzerine ant içerler. Onlar için ant, söyleneni doğrular ve her tartışmayı sona erdirir.'),
(2012863,68,58,6,17,'Tanrı da amacının değişmezliğini vaadin mirasçılarına daha açıkça belirtmek istediği için vaadini antla pekiştirdi.'),
(2012864,68,58,6,18,'Öyle ki, önümüze konan umuda tutunmak için Tanrıya sığınan bizler, Tanrının yalan söylemesi olanaksız olan bu iki değişmez şey aracılığıyla büyük cesaret bulalım.'),
(2012865,68,58,6,19,'Canlarımız için gemi demiri gibi sağlam ve güvenilir olan bu umut, perdenin arkasındaki iç bölmeye geçer.'),
(2012866,68,58,6,20,'Melkisedek düzeni uyarınca sonsuza dek başkâhin olan İsa oraya uğrumuza öncü olarak girdi.'),
(2012867,68,58,7,1,'Bu Melkisedek, Şalem Kralı ve yüce Tanrının kâhiniydi. Kralları bozguna uğratmaktan dönen İbrahimi karşılamış ve onu kutsamıştı.'),
(2012868,68,58,7,2,'İbrahim de ona her şeyin ondalığını verdi. Melkisedek, adının anlamına göre, önce ‹‹Doğruluk Kralı››dır; sonra da ‹‹Şalem Kralı››, yani ‹‹Esenlik Kralı››dır.'),
(2012869,68,58,7,3,'Babasız, annesizdir; soyağacı yoktur. Ne günlerinin başlangıcı, ne yaşamının sonu vardır. Tanrının Oğlu gibi sonsuza dek kâhin kalacaktır.'),
(2012870,68,58,7,4,'Bakın, büyük ata İbrahimin ganimetten ondalık verdiği bu adam ne kadar büyüktür!'),
(2012871,68,58,7,5,'Levioğullarından olup kâhinlik görevini üstlenenlere Kutsal Yasa uyarınca halktan, yani İbrahimin soyundan oldukları halde, kardeşlerinden ondalık almaları buyrulmuştur.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012872,68,58,7,6,'Melkisedek ise Levili kâhinlerin soyundan olmadığı halde, vaatleri alan İbrahimden ondalık kabul etmiş ve onu kutsamıştır.'),
(2012873,68,58,7,7,'Hiç kuşkusuz, kutsayan kutsanandan üstündür.'),
(2012874,68,58,7,8,'Birinde ölümlü insanlar ondalık alıyor, ötekinde yaşadığına tanıklık edilen biri alıyor.'),
(2012875,68,58,7,9,'Ondalık alan Levi bile İbrahim aracılığıyla ondalık vermiştir denebilir.'),
(2012876,68,58,7,10,'Çünkü Melkisedek İbrahimi karşıladığı zaman, Levi hâlâ atasının bedenindeydi.'),
(2012877,68,58,7,11,'Eğer Levililerin kâhinliği aracılığıyla yetkinliğe erişilebilseydi -nitekim Kutsal Yasa bu kâhinliği öngörerek halka verildi- Harun düzenine göre değil de, Melkisedek düzenine göre başka bir kâhinin gelmesinden söz etmeye ne gerek kalırdı?'),
(2012878,68,58,7,12,'Çünkü kâhinlik değişince, Yasa da zorunlu olarak değişir.'),
(2012879,68,58,7,13,'Kendisinden böyle söz edilen kişi başka bir oymaktandır. Bu oymaktan hiç kimse sunakta hizmet etmemiştir.'),
(2012880,68,58,7,14,'Rabbimizin Yahuda oymağından geldiği açıktır. Musa bu oymaktan söz ederken kâhinlere ilişkin bir şey söylemedi.'),
(2012881,68,58,7,15,'Melkisedek benzeri başka bir kâhin ortaya çıktığından, bu söylediğimiz artık daha da açıktır.'),
(2012882,68,58,7,16,'O, Yasanın soyla ilgili önkoşuluna göre değil, yok edilemez bir yaşamın gücüne göre kâhin olmuştur.'),
(2012883,68,58,7,17,'Çünkü, ‹‹Melkisedek düzeni uyarınca Sen sonsuza dek kâhinsin››'),
(2012884,68,58,7,18,'Önceki buyruk, zayıflığı ve yararsızlığı nedeniyle geçersiz kılındı.'),
(2012885,68,58,7,19,'Çünkü Yasa hiçbir şeyi yetkinleştiremedi. Bunun yerine, aracılığıyla Tanrıya yaklaştığımız daha sağlam bir umut verildi.'),
(2012886,68,58,7,20,'Bu da antsız olmadı. Öbürleri ant içilmeden kâhin olmuşlardı.'),
(2012887,68,58,7,21,'Ama O kendisine, ‹‹Rab ant içti, kararından dönmez, Sen sonsuza dek kâhinsin››'),
(2012888,68,58,7,22,'Böylece İsa daha iyi bir antlaşmanın kefili olmuştur.'),
(2012889,68,58,7,23,'Önceki düzende çok sayıda kâhin görev aldı. Çünkü ölüm, görevlerini sürdürmelerini engelliyordu.'),
(2012890,68,58,7,24,'Ama İsa sonsuza dek yaşadığı için kâhinliği süreklidir.'),
(2012891,68,58,7,25,'Bu nedenle Onun aracılığıyla Tanrıya yaklaşanları tümüyle kurtaracak güçtedir. Çünkü onlara aracılık etmek için hep yaşamaktadır.'),
(2012892,68,58,7,26,'Böyle bir başkâhinimiz -kutsal, suçsuz, lekesiz, günahkârlardan ayrılmış, göklerden daha yücelere çıkarılmış bir başkâhinimiz- olması uygundur.'),
(2012893,68,58,7,27,'O, öbür başkâhinler gibi her gün önce kendi günahları, sonra da halkın günahları için kurbanlar sunmak zorunda değildir. Çünkü kendini sunmakla bunu ilk ve son kez yaptı.'),
(2012894,68,58,7,28,'Kutsal Yasa, zayıflıkları olan insanları başkâhin atamaktadır. Ama Yasa''dan sonra gelen ant sözü, sonsuza dek yetkin kılınmış olan Oğul''u başkâhin atamıştır.'),
(2012895,68,58,8,1,'Söylediklerimizin özü şudur: Göklerde, Yüce Olanın tahtının sağında oturan, kutsal yerde, insanın değil, Rabbin kurduğu asıl tapınma çadırında görev yapan böyle bir başkâhinimiz vardır.'),
(2012896,68,58,8,3,'Her başkâhin sunular, kurbanlar sunmak için atanır. Bu nedenle bizim başkâhinimizin de sunacak bir şeyi olması gerekir.'),
(2012897,68,58,8,4,'Eğer kendisi yeryüzünde olsaydı, kâhin olamazdı. Çünkü Kutsal Yasa uyarınca sunuları sunanlar var.'),
(2012898,68,58,8,5,'Bunlar göktekinin örneği ve gölgesi olan tapınakta hizmet ediyorlar. Nitekim Musa tapınma çadırını kurmak üzereyken Tanrı tarafından şöyle uyarıldı: ‹‹Her şeyi sana dağda gösterilen örneğe göre yapmaya dikkat et.››'),
(2012899,68,58,8,6,'Şimdiyse, İsa daha iyi vaatler üzerine kurulmuş daha iyi bir antlaşmanın aracısı olduğu kadar, daha üstün bir göreve de sahip olmuştur.'),
(2012900,68,58,8,7,'Eğer o ilk antlaşma kusursuz olsaydı, ikincisine gerek duyulmazdı.'),
(2012901,68,58,8,8,'Oysa halkını kusurlu bulan Tanrı şöyle diyor: ‹‹ ‹İsrail halkıyla ve Yahuda halkıyla Yeni bir antlaşma yapacağım günler geliyor› Diyor Rab.'),
(2012902,68,58,8,9,'‹Atalarını Mısırdan çıkarmak için Ellerinden tuttuğum gün Onlarla yaptığım antlaşmaya benzemeyecek. Çünkü onlar antlaşmama bağlı kalmadılar, Ben de onlardan yüz çevirdim› Diyor Rab.'),
(2012903,68,58,8,10,'‹O günlerden sonra İsrail halkıyla Yapacağım antlaşma şudur› diyor Rab, ‹Yasalarımı zihinlerine işleyeceğim, Yüreklerine yazacağım. Ben onların Tanrısı olacağım, Onlar da benim halkım olacak.'),
(2012904,68,58,8,11,'Hiç kimse yurttaşını, kardeşini, Rabbi tanı diye eğitmeyecek. Çünkü küçük büyük hepsi tanıyacak beni.'),
(2012905,68,58,8,12,'Çünkü suçlarını bağışlayacağım, Günahlarını artık anmayacağım.› ››'),
(2012906,68,58,8,13,'Tanrı, ‹‹Yeni bir antlaşma›› demekle ilkini eskimiş saymıştır. Eskiyip köhneleşense çok geçmeden yok olur.'),
(2012907,68,58,9,1,'İlk antlaşmanın tapınma kuralları ve dünyasal tapınağı vardı.'),
(2012908,68,58,9,2,'Bir çadır kurulmuştu. Kutsal Yer denen birinci bölmede kandillik, masa ve adak ekmekleri bulunurdu.'),
(2012909,68,58,9,3,'İkinci perdenin arkasında En Kutsal Yer denen bir bölme vardı.'),
(2012910,68,58,9,4,'Altın buhur sunağıyla her yanı altınla kaplanmış Antlaşma Sandığı buradaydı. Sandığın içinde altından yapılmış man testisi, Harunun filizlenmiş değneği ve antlaşma levhaları vardı.'),
(2012911,68,58,9,5,'Sandığın üstünde Bağışlanma Kapağını gölgeleyen yüce Keruvlar dururdu. Ama şimdi bunların ayrıntılarına giremeyiz.'),
(2012912,68,58,9,6,'Her şey böyle düzenlendikten sonra kâhinler her zaman çadırın ilk bölmesine girer, tapınma görevlerini yerine getirirler.'),
(2012913,68,58,9,7,'Ama iç bölmeye yılda bir kez yalnız başkâhin girebilir. Üstelik kendisi için ve halkın bilmeden işlediği suçlar için sunacağı kurban kanı olmaksızın giremez.'),
(2012914,68,58,9,8,'Kutsal Ruh bununla çadırın ilk bölmesi durdukça, kutsal yere giden yolun henüz açıkça gösterilmediğini belirtiyor.'),
(2012915,68,58,9,9,'Bu, şimdiki çağ için bir örnektir; sunulan kurbanlarla sunuların tapınan kişinin vicdanını yetkinleştiremediğini gösteriyor.'),
(2012916,68,58,9,10,'Bunlar yalnız yiyecek, içecek, çeşitli dinsel yıkanmalarla ilgilidir; yeni düzenin başlangıcına kadar geçerli olan bedensel kurallardır.'),
(2012917,68,58,9,11,'Ama Mesih, gelecek iyi şeylerin başkâhini olarak ortaya çıktı. İnsan eliyle yapılmamış, yani bu yaratılıştan olmayan daha büyük, daha yetkin çadırdan geçti.'),
(2012918,68,58,9,12,'Tekelerle danaların kanıyla değil, sonsuz kurtuluşu sağlayarak kendi kanıyla kutsal yere ilk ve son kez girdi.'),
(2012919,68,58,9,13,'Tekelerle boğaların kanı ve serpilen düve külü murdar olanları kutsal kılıyor, bedensel açıdan temizliyor.'),
(2012920,68,58,9,14,'Öyleyse sonsuz Ruh aracılığıyla kendini lekesiz olarak Tanrıya sunmuş olan Mesihin kanının, diri Tanrıya kulluk edebilmemiz için vicdanımızı ölü işlerden temizleyeceği ne kadar daha kesindir!'),
(2012921,68,58,9,15,'Bu nedenle, çağrılmış olanların vaat edilen sonsuz mirası almaları için Mesih yeni antlaşmanın aracısı oldu. Kendisi onları ilk antlaşmafx1 zamanında işledikleri suçlardan kurtarmak için fidye olarak öldü.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012922,68,58,9,16,'Ortada bir vasiyetfx1 varsa, vasiyet edenin ölümünün kanıtlanması gerekir.'),
(2012923,68,58,9,17,'Çünkü vasiyet ancak ölümden sonra geçerli olur. Vasiyet eden yaşadıkça, vasiyetin hiçbir etkinliği yoktur.'),
(2012924,68,58,9,18,'Bu nedenle ilk antlaşma bile kan akıtılmadan yürürlüğe girmedi.'),
(2012925,68,58,9,19,'Musa, Kutsal Yasanın her buyruğunu bütün halka bildirdikten sonra su, al yapağı, mercanköşkotu ile danaların ve tekelerin kanını alıp hem kitabın hem de bütün halkın üzerine serpti.'),
(2012926,68,58,9,20,'‹‹Tanrının uymanızı buyurduğu antlaşmanın kanı budur›› dedi.'),
(2012927,68,58,9,21,'Aynı biçimde çadırın ve tapınmada kullanılan bütün eşyaların üzerine kan serpti.'),
(2012928,68,58,9,22,'Nitekim Kutsal Yasa uyarınca hemen her şey kanla temiz kılınır, kan dökülmeden bağışlama olmaz.'),
(2012929,68,58,9,23,'Böylelikle aslı göklerde olan örneklerin bu kurbanlarla, ama gökteki asıllarının bunlardan daha iyi kurbanlarla temiz kılınması gerekti.'),
(2012930,68,58,9,24,'Çünkü Mesih, asıl kutsal yerin örneği olup insan eliyle yapılan kutsal yere değil, ama şimdi bizim için Tanrının önünde görünmek üzere asıl göğe girdi.'),
(2012931,68,58,9,25,'Başkâhin her yıl kendisinin olmayan kanla En Kutsal Yere girer; oysa Mesih kendisini tekrar tekrar sunmak için göğe girmedi.'),
(2012932,68,58,9,26,'Öyle olsaydı, dünyanın kuruluşundan beri Mesihin tekrar tekrar acı çekmesi gerekirdi. Oysa Mesih, kendisini bir kez kurban ederek günahı ortadan kaldırmak için çağların sonunda ortaya çıkmıştır.'),
(2012933,68,58,9,27,'Bir kez ölmek, sonra da yargılanmak nasıl insanların kaderiyse, Mesih de birçoklarının günahlarını yüklenmek için bir kez kurban edildi. İkinci kez, günah yüklenmek için değil, kurtuluş getirmek için kendisini bekleyenlere görünecektir.'),
(2012934,68,58,10,1,'Kutsal Yasada gelecek iyi şeylerin aslı yoktur, sadece gölgesi vardır. Bu nedenle Yasa, her yıl sürekli aynı kurbanları sunarak Tanrıya yaklaşanları asla yetkinliğe erdiremez.'),
(2012935,68,58,10,2,'Erdirebilseydi, kurban sunmaya son verilmez miydi? Çünkü tapınanlar bir kez günahlarından arındıktan sonra artık günahlılık duygusu kalmazdı.'),
(2012936,68,58,10,3,'Ancak o kurbanlar insanlara yıldan yıla günahlarını anımsatıyor.'),
(2012937,68,58,10,4,'Çünkü boğalarla tekelerin kanı günahları ortadan kaldıramaz.'),
(2012938,68,58,10,5,'Bunun için Mesih dünyaya gelirken şöyle diyor: ‹‹Kurban ve sunu istemedin, Ama bana bir beden hazırladın.'),
(2012939,68,58,10,6,'Yakmalık sunudan ve günah sunusundan Hoşnut olmadın.'),
(2012940,68,58,10,7,'O zaman şöyle dedim: ‹Kutsal Yazı tomarında Benim için yazıldığı gibi, Senin isteğini yapmak üzere, Ey Tanrı, işte geldim.› ››'),
(2012941,68,58,10,8,'Mesih ilkin, ‹‹Kurban, sunu, yakmalık sunu, günah sunusu istemedin ve bunlardan hoşnut olmadın›› dedi. Oysa bunlar Yasanın bir gereği olarak sunulur.'),
(2012942,68,58,10,9,'Sonra, ‹‹Senin isteğini yapmak üzere işte geldim›› dedi. Yani ikinciyi geçerli kılmak için birinciyi ortadan kaldırıyor.'),
(2012943,68,58,10,10,'Tanrının bu isteği uyarınca, İsa Mesihin bedeninin ilk ve son kez sunulmasıyla kutsal kılındık.'),
(2012944,68,58,10,11,'Her kâhin her gün ayakta durup görevini yapar ve günahları asla ortadan kaldıramayan aynı kurbanları tekrar tekrar sunar.'),
(2012945,68,58,10,12,'Oysa Mesih günahlar için sonsuza dek geçerli tek bir kurban sunduktan sonra Tanrının sağında oturdu.'),
(2012946,68,58,10,13,'O zamandan beri düşmanlarının, kendi ayaklarının altına serilmesini bekliyor.'),
(2012947,68,58,10,14,'Çünkü kutsal kılınanları tek bir sunuyla sonsuza dek yetkinliğe erdirmiştir.'),
(2012948,68,58,10,15,'Kutsal Ruh da bu konuda bize tanıklık ediyor. Önce diyor ki,'),
(2012949,68,58,10,16,'‹‹Rab, ‹O günlerden sonra Onlarla yapacağım antlaşma şudur: Yasalarımı yüreklerine koyacağım, Zihinlerine yazacağım› diyor.››'),
(2012950,68,58,10,17,'Sonra şunu ekliyor: ‹‹Onların günahlarını ve suçlarını artık anmayacağım.››'),
(2012951,68,58,10,18,'Bunların bağışlanması durumunda artık günah için sunuya gerek yoktur.'),
(2012952,68,58,10,19,'Bu nedenle, ey kardeşler, İsanın kanı sayesinde perdede, yani kendi bedeninde bize açtığı yeni ve diri yoldan kutsal yere girmeye cesaretimiz vardır.'),
(2012953,68,58,10,21,'Tanrının evinden sorumlu büyük bir kâhinimiz bulunmaktadır.'),
(2012954,68,58,10,22,'Öyleyse yüreklerimiz serpmeyle kötü vicdandan arınmış, bedenlerimiz temiz suyla yıkanmış olarak, imanın verdiği tam güvenceyle, yürekten bir içtenlikle Tanrıya yaklaşalım.'),
(2012955,68,58,10,23,'Açıkça benimsediğimiz umuda sımsıkı tutunalım. Çünkü vaat eden Tanrı güvenilirdir.'),
(2012956,68,58,10,24,'Birbirimizi sevgi ve iyi işler için nasıl gayrete getirebileceğimizi düşünelim.'),
(2012957,68,58,10,25,'Bazılarının alıştığı gibi, bir araya gelmekten vazgeçmeyelim; o günün yaklaştığını gördükçe birbirimizi daha da çok yüreklendirelim.'),
(2012958,68,58,10,26,'Gerçeği öğrenip benimsedikten sonra, bile bile günah işlemeye devam edersek, günahlar için artık kurban kalmaz; geriye sadece yargının dehşetli beklenişi ve düşmanları yiyip bitirecek kızgın ateş kalır.'),
(2012959,68,58,10,28,'Musanın Yasasını hiçe sayan, iki ya da üç tanığın sözüyle acımasızca öldürülür.'),
(2012960,68,58,10,29,'Eğer bir kimse Tanrı Oğlunu ayaklar altına alır, kendisini kutsal kılan antlaşma kanını bayağı sayar ve lütufkâr Ruha hakaret ederse, bundan ne kadar daha ağır bir cezaya layık görülecek sanırsınız?'),
(2012961,68,58,10,30,'Çünkü, ‹‹Öç benimdir, karşılığını ben vereceğim›› ve yine, ‹‹Rab halkını yargılayacak›› diyeni tanıyoruz.'),
(2012962,68,58,10,31,'Diri Tanrının eline düşmek korkunç bir şeydir.'),
(2012963,68,58,10,32,'Sizlerse aydınlandıktan sonra acılarla dolu büyük bir mücadeleye dayandığınız o ilk günleri anımsayın.'),
(2012964,68,58,10,33,'Bazen sitemlere, sıkıntılara uğrayıp seyirlik oldunuz, bazen de aynı durumda olanlarla dayanışma içine girdiniz.'),
(2012965,68,58,10,34,'Hem hapistekilerin dertlerine ortak oldunuz, hem de daha iyi ve kalıcı bir malınız olduğunu bilerek mallarınızın yağma edilmesini sevinçle karşıladınız.'),
(2012966,68,58,10,35,'Onun için cesaretinizi yitirmeyin; bu cesaretin ödülü büyüktür.'),
(2012967,68,58,10,36,'Çünkü Tanrının isteğini yerine getirmek ve vaat edilene kavuşmak için dayanma gücüne ihtiyacınız vardır.'),
(2012968,68,58,10,37,'Artık, ‹‹Gelecek olan pek yakında gelecek Ve gecikmeyecek.'),
(2012969,68,58,10,38,'Doğru adamım, imanla yaşayacaktır. Ama geri çekilirse, ondan hoşnut olmayacağım.››'),
(2012970,68,58,10,39,'Bizler geri çekilip mahvolanlardan değiliz; iman edip canlarının kurtuluşuna kavuşanlardanız.'),
(2012971,68,58,11,1,'İman, umut edilenlere güvenmek, görünmeyen şeylerin varlığından emin olmaktır.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2012972,68,58,11,2,'Atalarımız bununla Tanrının beğenisini kazandılar.'),
(2012973,68,58,11,3,'Evrenin Tanrının buyruğuyla yaratıldığını, böylece görülenlerin görünmeyenlerden oluştuğunu iman sayesinde anlıyoruz.'),
(2012974,68,58,11,4,'Habilin Tanrıya Kayinden daha iyi bir kurban sunması iman sayesinde oldu. İmanı sayesinde doğru biri olarak Tanrının beğenisini kazandı. Çünkü Tanrı onun sunduğu adakları kabul etti. Nitekim Habil ölmüş olduğu halde, iman sayesinde hâlâ konuşmaktadır.'),
(2012975,68,58,11,5,'İman sayesinde Hanok ölümü tatmamak üzere yukarı alındı. Kimse onu bulamadı, çünkü Tanrı onu yukarı almıştı. Yukarı alınmadan önce Tanrıyı hoşnut eden biri olduğuna tanıklık edildi.'),
(2012976,68,58,11,6,'İman olmadan Tanrıyı hoşnut etmek olanaksızdır. Tanrıya yaklaşan, Onun var olduğuna ve kendisini arayanları ödüllendireceğine iman etmelidir.'),
(2012977,68,58,11,7,'İman sayesinde Nuh, henüz olmamış olaylarla ilgili olarak Tanrı tarafından uyarılınca, Tanrı korkusuyla ev halkının kurtuluşu için bir gemi yaptı. Bununla dünyayı yargıladı ve imana dayanan doğruluğun mirasçısı oldu.'),
(2012978,68,58,11,8,'İman sayesinde İbrahim miras alacağı yere gitmesi için çağrılınca, Tanrının sözünü dinledi ve nereye gideceğini bilmeden yola çıktı.'),
(2012979,68,58,11,9,'İman sayesinde bir yabancı olarak vaat edilen ülkeye yerleşti. Aynı vaadin ortak mirasçıları olan İshak ve Yakupla birlikte çadırlarda yaşadı.'),
(2012980,68,58,11,10,'Çünkü mimarı ve kurucusu Tanrı olan temelli kenti bekliyordu.'),
(2012981,68,58,11,11,'İman sayesinde Saranın kendisi de kısır ve yaşı geçmiş olduğu halde vaat edeni güvenilir saydığından çocuk sahibi olmak için güç buldu.'),
(2012982,68,58,11,12,'Böylece tek bir adamdan, üstelik ölüden farksız birinden gökteki yıldızlar, deniz kıyısındaki kum kadar sayısız torun meydana geldi.'),
(2012983,68,58,11,13,'Bu kişilerin hepsi imanlı olarak öldüler. Vaat edilenlere kavuşamadılarsa da bunları uzaktan görüp selamladılar, yeryüzünde yabancı ve konuk olduklarını açıkça kabul ettiler.'),
(2012984,68,58,11,14,'Böyle konuşanlar bir vatan aradıklarını gösteriyorlar.'),
(2012985,68,58,11,15,'Ayrıldıkları ülkeyi düşünselerdi, geri dönmeye fırsatları olurdu.'),
(2012986,68,58,11,16,'Ama onlar daha iyisini, yani göksel olanı arzu ediyorlardı. Bunun içindir ki, Tanrı onların Tanrısı olarak anılmaktan utanmıyor. Çünkü onlara bir kent hazırladı.'),
(2012987,68,58,11,17,'İbrahim sınandığı zaman imanla İshakı kurban olarak sundu. Vaatleri almış olan İbrahim biricik oğlunu kurban etmek üzereydi.'),
(2012988,68,58,11,18,'Oysa Tanrı ona, ‹‹Senin soyun İshakla sürecek›› demişti.'),
(2012989,68,58,11,19,'İbrahim Tanrının ölüleri bile diriltebileceğini düşündü; nitekim İshakı simgesel şekilde ölümden geri aldı.'),
(2012990,68,58,11,20,'İman sayesinde İshak gelecek olaylarla ilgili olarak Yakupla Esavı kutsadı.'),
(2012991,68,58,11,21,'Yakup ölürken iman sayesinde Yusufun iki oğlunu da kutsadı, değneğinin ucuna yaslanarak Tanrıya tapındı.'),
(2012992,68,58,11,22,'Yusuf ölürken iman sayesinde İsrailoğullarının Mısırdan çıkacağını anımsattı ve kemiklerine ilişkin buyruk verdi.'),
(2012993,68,58,11,23,'Musa doğduğunda annesiyle babası onu imanla üç ay gizlediler. Çünkü çocuğun güzel olduğunu gördüler ve kralın fermanından korkmadılar.'),
(2012994,68,58,11,24,'Musa büyüyünce iman sayesinde firavunun kızının oğlu olarak tanınmayı reddetti.'),
(2012995,68,58,11,25,'Bir süre için günahın sefasını sürmektense, Tanrının halkıyla birlikte baskı görmeyi yeğledi.'),
(2012996,68,58,11,26,'Mesih uğruna aşağılanmayı Mısır hazinelerinden daha büyük zenginlik saydı. Çünkü alacağı ödülü düşünüyordu.'),
(2012997,68,58,11,27,'Kralın öfkesinden korkmadan imanla Mısırdan ayrıldı. Görünmez Olanı görür gibi dayandı.'),
(2012998,68,58,11,28,'İlk doğanları öldüren melek İsraillilere dokunmasın diye Musa imanla, Fısıh kurbanının kesilmesini ve kanının kapılara sürülmesini sağladı.'),
(2012999,68,58,11,29,'İman sayesinde İsrailliler karadan geçer gibi Kızıldenizden geçtiler. Mısırlılar bunu deneyince boğuldular.'),
(2013000,68,58,11,30,'İsrailliler yedi gün boyunca Eriha surları çevresinde dolandılar; sonunda imanları sayesinde surlar yıkıldı.'),
(2013001,68,58,11,31,'Fahişe Rahav casusları dostça karşıladığı için imanı sayesinde söz dinlemeyenlerle birlikte öldürülmedi.'),
(2013002,68,58,11,32,'Daha ne diyeyim? Gidyon, Barak, Şimşon, Yiftah, Davut, Samuel ve peygamberlerle ilgili olanları anlatsam, zaman yetmeyecek.'),
(2013003,68,58,11,33,'Bunlar iman sayesinde ülkeler ele geçirdiler, adaleti sağladılar, vaat edilenlere kavuştular, aslanların ağzını kapadılar.'),
(2013004,68,58,11,34,'Kızgın ateşi söndürdüler, kılıcın ağzından kaçıp kurtuldular. Güçsüzlükte kuvvet buldular, savaşta güçlendiler, yabancı orduları bozguna uğrattılar.'),
(2013005,68,58,11,35,'Kadınlar dirilen ölülerini geri aldılar. Başkalarıysa salıverilmeyi reddederek dirilip daha iyi bir yaşama kavuşma umuduyla işkencelere katlandılar.'),
(2013006,68,58,11,36,'Daha başkaları alaya alınıp kamçılandı, hatta zincire vurulup hapsedildi.'),
(2013007,68,58,11,37,'Taşlandılar, testereyle biçildiler, kılıçtan geçirilip öldürüldüler. Koyun postu, keçi derisi içinde dolaştılar, yoksulluk çektiler, sıkıntılara uğradılar, baskı gördüler.'),
(2013008,68,58,11,38,'Dünya onlara layık değildi. Çöllerde, dağlarda, mağaralarda, yeraltı oyuklarında dolanıp durdular.'),
(2013009,68,58,11,39,'İmanları sayesinde bunların hepsi Tanrının beğenisini kazandıkları halde, hiçbiri vaat edilene kavuşmadı.'),
(2013010,68,58,11,40,'Bizden ayrı olarak yetkinliğe ermesinler diye, Tanrı bizim için daha iyi bir şey hazırlamıştı.'),
(2013011,68,58,12,1,'İşte çevremizi bu denli büyük bir tanıklar bulutu sardığına göre, biz de her yükü ve bizi kolayca kuşatan günahı üzerimizden sıyırıp atalım ve önümüze konan yarışı sabırla koşalım.'),
(2013012,68,58,12,2,'Gözümüzü imanımızın öncüsü ve tamamlayıcısı İsaya dikelim. O kendisini bekleyen sevinç uğruna utancı hiçe sayıp çarmıhta ölüme katlandı ve Tanrının tahtının sağında oturdu.'),
(2013013,68,58,12,3,'Yorulup cesaretinizi yitirmemek için, günahkârların bunca karşı koymasına katlanmış Olanı düşünün.'),
(2013014,68,58,12,4,'Günaha karşı verdiğiniz mücadelede henüz kanınızı akıtacak kadar direnmiş değilsiniz.'),
(2013015,68,58,12,5,'Size oğullar diye seslenen şu öğüdü de unuttunuz: ‹‹Oğlum, Rabbin terbiye edişini hafife alma, Rab seni azarlayınca cesaretini yitirme.'),
(2013016,68,58,12,6,'Çünkü Rab sevdiğini terbiye eder, Oğulluğa kabul ettiği herkesi cezalandırır.››'),
(2013017,68,58,12,7,'Terbiye edilmek uğruna acılara katlanmalısınız. Tanrı size oğullarına davranır gibi davranıyor. Hangi oğul babası tarafından terbiye edilmez?'),
(2013018,68,58,12,8,'Herkesin gördüğü terbiyeden yoksunsanız, oğullar değil, yasadışı evlatlarsınız.'),
(2013019,68,58,12,9,'Kaldı ki, bizi terbiye eden dünyasal babalarımız vardı ve onlara saygı duyardık. Öyleyse Ruhlar Babasına bağımlı olup yaşamamız çok daha önemli değil mi?'),
(2013020,68,58,12,10,'Babalarımız bizi kısa bir süre için, uygun gördükleri gibi terbiye ettiler. Ama Tanrı, kutsallığına ortak olalım diye bizi kendi yararımıza terbiye ediyor.'),
(2013021,68,58,12,11,'Terbiye edilmek başlangıçta hiç tatlı gelmez, acı gelir. Ne var ki, böyle eğitilenler için bu sonradan esenlik veren doğruluğu üretir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013022,68,58,12,12,'Bunun için sarkık ellerinizi kaldırın, bükük dizlerinizi doğrultun, ayaklarınız için düz yollar yapın. Öyle ki, kötürüm olan parça eklemden çıkmasın, tersine şifa bulsun.'),
(2013023,68,58,12,14,'Herkesle barış içinde yaşamaya, kutsal olmaya gayret edin. Kutsallığa sahip olmadan kimse Rabbi göremeyecek.'),
(2013024,68,58,12,15,'Dikkat edin, kimse Tanrının lütfundan yoksun kalmasın. İçinizde sizi rahatsız edecek ve birçoklarını zehirleyecek acı bir kök filizlenmesin.'),
(2013025,68,58,12,16,'Kimse fuhuş yapmasın ya da ilk oğulluk hakkını bir yemeğe karşılık satan Esav gibi kutsal değerlere saygısızlık etmesin.'),
(2013026,68,58,12,17,'Biliyorsunuz, Esav daha sonra kutsanma hakkını miras almak istediyse de geri çevrildi. Kutsanmak için gözyaşı döküp yalvarmasına karşın, vermiş olduğu kararın sonucunu değiştiremedi.'),
(2013027,68,58,12,18,'Sizler dokunulabilen, alev alev yanan dağa, karanlığa, koyu karanlık ve kasırgaya, gürleyen çağrı borusuna, tanrısal sözleri ileten sese yaklaşmış değilsiniz. O sesi işitenler, kendilerine bir sözcük daha söylenmesin diye yalvardılar.'),
(2013028,68,58,12,20,'‹‹Dağa bir hayvan bile dokunsa taşlanacak›› buyruğuna dayanamadılar.'),
(2013029,68,58,12,21,'Görünüm öyle korkunçtu ki, Musa, ‹‹Çok korkuyorum, titriyorum›› dedi.'),
(2013030,68,58,12,22,'Oysa sizler Siyon Dağına, yaşayan Tanrının kenti olan göksel Yeruşalime, bir bayram şenliği içindeki on binlerce meleğe, adları göklerde yazılmış ilk doğanların topluluğuna yaklaştınız. Herkesin yargıcı olan Tanrıya, yetkinliğe erdirilmiş doğru kişilerin ruhlarına, yeni antlaşmanın aracısı olan İsaya ve Habilin kanından daha üstün bir anlam taşıyan serpmelik kana yaklaştınız.'),
(2013031,68,58,12,25,'Bunları söyleyeni reddetmemeye dikkat edin. Çünkü yeryüzünde kendilerini uyaranı reddedenler kurtulamadılarsa, göklerden bizi uyarandan yüz çevirirsek, bizim de kurtulamayacağımız çok daha kesindir.'),
(2013032,68,58,12,26,'O zaman Onun sesi yeri sarsmıştı. Ama şimdi, ‹‹Bir kez daha yalnız yeri değil, göğü de sarsacağım›› diye söz vermiştir.'),
(2013033,68,58,12,27,'‹‹Bir kez daha›› sözü, sarsılanların, yani yaratılmış olan şeylerin ortadan kaldırılacağını, böylelikle sarsılmayanların kalacağını anlatıyor.'),
(2013034,68,58,12,28,'Böylece sarsılmaz bir egemenliğe kavuştuğumuz için minnettar olalım. Öyle ki, Tanrıyı hoşnut edecek biçimde saygı ve korkuyla tapınalım.'),
(2013035,68,58,12,29,'Çünkü Tanrımız yakıp yok eden bir ateştir.'),
(2013036,68,58,13,1,'Kardeş sevgisi sürekli olsun.'),
(2013037,68,58,13,2,'Konuksever olmaktan geri kalmayın. Çünkü bu sayede bazıları bilmeden melekleri konuk ettiler.'),
(2013038,68,58,13,3,'Hapiste olanları, onlarla birlikte hapsedilmiş gibi anımsayın. Sizin de bir bedeniniz olduğunu düşünerek baskı görenleri hatırlayın.'),
(2013039,68,58,13,4,'Herkes evliliğe saygı göstersin. Evlilik yatağı günahla lekelenmesin. Çünkü Tanrı fuhuş yapanları, zina edenleri yargılayacak.'),
(2013040,68,58,13,5,'Yaşayışınız para sevgisinden uzak olsun. Sahip olduklarınızla yetinin. Çünkü Tanrı şöyle dedi: ‹‹Seni asla terk etmeyeceğim, Seni asla yüzüstü bırakmayacağım.››'),
(2013041,68,58,13,6,'Böylece cesaretle diyoruz ki, ‹‹Rab benim yardımcımdır, korkmam; İnsan bana ne yapabilir?››'),
(2013042,68,58,13,7,'Tanrının sözünü size iletmiş olan önderlerinizi anımsayın. Yaşayışlarının sonucuna bakarak onların imanını örnek alın.'),
(2013043,68,58,13,8,'İsa Mesih dün, bugün ve sonsuza dek aynıdır.'),
(2013044,68,58,13,9,'Çeşitli garip öğretilerin etkisine kapılıp sürüklenmeyin. Yüreğin yiyeceklerle değil, Tanrı lütfuyla güçlenmesi iyidir. Yiyeceklere güvenenler hiçbir yarar görmediler.'),
(2013045,68,58,13,10,'Bir sunağımız var ki, tapınma çadırında hizmet edenlerin ondan yemeye hakları yoktur.'),
(2013046,68,58,13,11,'Başkâhin günah sunusu olarak hayvanların kanını kutsal yere taşır, ama bu hayvanların cesetleri ordugahın dışında yakılır.'),
(2013047,68,58,13,12,'Bunun gibi, İsa da kendi kanıyla halkı kutsal kılmak için kent kapısının dışında acı çekti.'),
(2013048,68,58,13,13,'Öyleyse biz de Onun uğradığı aşağılanmaya katlanarak ordugahtan dışarıya çıkıp yanına gidelim.'),
(2013049,68,58,13,14,'Çünkü burada kalıcı bir kentimiz yoktur, biz gelecekteki kenti özlüyoruz.'),
(2013050,68,58,13,15,'Bu nedenle, İsa aracılığıyla Tanrıya sürekli övgü kurbanları, yani Onun adını açıkça anan dudakların meyvesini sunalım.'),
(2013051,68,58,13,16,'İyilik yapmayı, sizde olanı başkalarıyla paylaşmayı unutmayın. Çünkü Tanrı bu tür kurbanlardan hoşnut olur.'),
(2013052,68,58,13,17,'Önderlerinizin sözünü dinleyin, onlara bağlı kalın. Çünkü onlar canlarınız için hesap verecek kişiler olarak sizi kollarlar. Onların sözünü dinleyin ki, görevlerini inleyerek değil -bunun size yararı olmaz- sevinçle yapsınlar.'),
(2013053,68,58,13,18,'Bizim için dua edin. Vicdanımızı temiz tuttuğumuza, her bakımdan olumlu bir yaşam sürmek istediğimize eminiz.'),
(2013054,68,58,13,19,'Yanınıza tez zamanda dönebilmem için dua etmenizi özellikle rica ediyorum.'),
(2013055,68,58,13,20,'Esenlik veren Tanrı, koyunların büyük Çobanını, Rabbimiz İsayı sonsuza dek sürecek antlaşmanın kanıyla ölümden diriltti.'),
(2013056,68,58,13,21,'Tanrı, isteğini yerine getirebilmeniz için sizi her iyilikle donatsın; kendisini hoşnut eden şeyi İsa Mesih aracılığıyla bizlerde gerçekleştirsin. Mesihe sonsuzlara dek yücelik olsun! Amin.'),
(2013057,68,58,13,22,'Kardeşler, size rica ediyorum, öğütlerimi hoş görün. Zaten size kısaca yazdım.'),
(2013058,68,58,13,23,'Kardeşimiz Timoteosun salıverildiğini bilmenizi istiyorum. Yakında yanıma gelirse, onunla birlikte sizi görmeye geleceğim.'),
(2013059,68,58,13,24,'Önderlerinizin hepsine ve bütün kutsallara selam söyleyin. İtalyadan olanlar size selam ederler.'),
(2013060,68,58,13,25,'Tanrı''nın lütfu hepinizle birlikte olsun! Amin.'),
(2013061,68,59,1,1,'Tanrının ve Rab İsa Mesihin kulu ben Yakup, dağılmış olan on iki oymağa selam ederim.'),
(2013062,68,59,1,2,'Kardeşlerim, çeşitli denemelerle yüz yüze geldiğinizde bunu büyük sevinçle karşılayın.'),
(2013063,68,59,1,3,'Çünkü bilirsiniz ki, imanınızın sınanması dayanma gücünü yaratır.'),
(2013064,68,59,1,4,'Dayanma gücü de, hiçbir eksiği olmayan, olgun, yetkin kişiler olmanız için tam bir etkinliğe erişsin.'),
(2013065,68,59,1,5,'İçinizden birinin bilgelikte eksiği varsa, herkese cömertçe, azarlamadan veren Tanrıdan istesin; kendisine verilecektir.'),
(2013066,68,59,1,6,'Yalnız hiç kuşku duymadan, imanla istesin. Çünkü kuşku duyan kişi rüzgarın sürükleyip savurduğu deniz dalgasına benzer.'),
(2013067,68,59,1,7,'Her bakımdan değişken, kararsız olan kişi Rabden bir şey alacağını ummasın.'),
(2013068,68,59,1,9,'Düşkün olan kardeş kendi yüksekliğiyle, zengin olansa kendi düşkünlüğüyle övünsün. Çünkü zengin kişi kır çiçeği gibi solup gidecek.'),
(2013069,68,59,1,11,'Güneş yakıcı sıcağıyla doğar ve otu kurutur. Otun çiçeği düşer, görünüşünün güzelliği yok olur. Zengin de bunun gibi kendi uğraşları içinde kaybolup gidecektir.'),
(2013070,68,59,1,12,'Ne mutlu denemeye dayanan kişiye! Denemeden başarıyla çıktığı zaman Rabbin kendisini sevenlere vaat ettiği yaşam tacını alacaktır.'),
(2013071,68,59,1,13,'Ayartılan kişi, ‹‹Tanrı beni ayartıyor›› demesin. Çünkü Tanrı kötülükle ayartılmadığı gibi kendisi de kimseyi ayartmaz.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013072,68,59,1,14,'Herkes kendi arzularıyla sürüklenip aldanarak ayartılır.'),
(2013073,68,59,1,15,'Sonra arzu gebe kalır ve günah doğurur. Günah olgunlaşınca da ölüm getirir.'),
(2013074,68,59,1,16,'Sevgili kardeşlerim, aldanmayın!'),
(2013075,68,59,1,17,'Her nimet, her mükemmel armağan yukarıdan, kendisinde değişkenlik ya da döneklik gölgesi olmayan Işıklar Babasından gelir.'),
(2013076,68,59,1,18,'O, yarattıklarının bir anlamda ilk meyveleri olmamız için bizleri kendi isteği uyarınca, gerçeğin bildirisiyle yaşama kavuşturdu.'),
(2013077,68,59,1,19,'Sevgili kardeşlerim, şunu aklınızda tutun: Herkes dinlemekte çabuk, konuşmakta yavaş, öfkelenmekte de yavaş olsun.'),
(2013078,68,59,1,20,'Çünkü insanın öfkesi Tanrının istediği doğruluğu sağlamaz.'),
(2013079,68,59,1,21,'Bunun için, her türlü pisliği ve her tarafa yayılmış olan kötülüğü üstünüzden sıyırıp atarak, içinize ekilmiş, canlarınızı kurtaracak güçte olan sözü alçakgönüllülükle kabul edin.'),
(2013080,68,59,1,22,'Tanrı sözünü yalnız duymakla kalmayın, sözün uygulayıcıları da olun. Yoksa kendinizi aldatmış olursunuz.'),
(2013081,68,59,1,23,'Çünkü sözün dinleyicisi olup da uygulayıcısı olmayan kişi, aynada kendi doğal yüzüne bakan kişiye benzer.'),
(2013082,68,59,1,24,'Kendini görür, sonra gider ve nasıl bir kişi olduğunu hemen unutur.'),
(2013083,68,59,1,25,'Oysa mükemmel yasaya, özgürlük yasasına yakından bakıp ona bağlı kalan, unutkan dinleyici değil de etkin uygulayıcı olan kişi, yaptıklarıyla mutlu olacaktır.'),
(2013084,68,59,1,26,'Dindar olduğunu sanıp da dilini dizginlemeyen kişi kendini aldatır. Böylesinin dindarlığı boştur.'),
(2013085,68,59,1,27,'Baba Tanrı''nın gözünde temiz ve kusursuz dindarlık, kişinin sıkıntı çeken öksüzler ve dullarla ilgilenmesi ve kendini dünyanın lekelemesinden korumasıdır.'),
(2013086,68,59,2,1,'Kardeşlerim, yüce Rabbimiz İsa Mesihe iman edenler olarak insanlar arasında ayrım yapmayın.'),
(2013087,68,59,2,2,'Toplandığınız yere altın yüzüklü, şık giyimli bir adamla kirli giysiler içinde yoksul bir adam geldiğinde, şık giyimliye ilgiyle, ‹‹Sen şuraya, iyi yere otur››, yoksula da, ‹‹Sen orada dur›› ya da ‹‹Ayaklarımın dibine otur›› derseniz, aranızda ayrım yapmış, kötü düşünceli yargıçlar gibi davranmış olmuyor musunuz?'),
(2013088,68,59,2,5,'Dinleyin, sevgili kardeşlerim: Tanrı, bu dünyada yoksul olanları imanda zenginleşmek ve kendisini sevenlere vaat ettiği egemenliğin mirasçıları olmak üzere seçmedi mi?'),
(2013089,68,59,2,6,'Ama siz yoksulun onurunu kırdınız. Sizi sömüren zenginler değil mi? Sizi mahkemelere sürükleyen onlar değil mi?'),
(2013090,68,59,2,7,'Ait olduğunuz Kişinin yüce adına küfreden onlar değil mi?'),
(2013091,68,59,2,8,'‹‹Komşunu kendin gibi seveceksin›› diyen Kutsal Yazıya uyarak Kralımız Tanrının Yasasını gerçekten yerine getiriyorsanız, iyi ediyorsunuz.'),
(2013092,68,59,2,9,'Ama insanlar arasında ayrım yaparsanız, günah işlemiş olursunuz; Yasa tarafından, Yasayı çiğnemekten suçlu bulunursunuz.'),
(2013093,68,59,2,10,'Çünkü Yasanın her dediğini yerine getirse de tek konuda ondan sapan kişi bütün Yasaya karşı suçlu olur.'),
(2013094,68,59,2,11,'Nitekim ‹‹Zina etmeyeceksin›› diyen, aynı zamanda ‹‹Adam öldürmeyeceksin›› demiştir. Zina etmez, ama adam öldürürsen, Yasayı yine de çiğnemiş olursun.'),
(2013095,68,59,2,12,'Özgürlük Yasasıyla yargılanacak olanlar gibi konuşup davranın.'),
(2013096,68,59,2,13,'Çünkü yargı merhamet göstermeyene karşı merhametsizdir. Merhamet yargıya galip gelir.'),
(2013097,68,59,2,14,'Kardeşlerim, bir kimse iyi eylemleri yokken imanı olduğunu söylerse, bu neye yarar? Böylesi bir iman onu kurtarabilir mi?'),
(2013098,68,59,2,15,'Bir erkek ya da kız kardeş çıplak ve günlük yiyecekten yoksunken, içinizden biri ona, ‹‹Esenlikle git, ısınmanı, doymanı dilerim›› der, ama bedenin gereksindiklerini vermezse, bu neye yarar?'),
(2013099,68,59,2,17,'Bunun gibi, tek başına eylemsiz iman da ölüdür.'),
(2013100,68,59,2,18,'Ama biri şöyle diyebilir: ‹‹Senin imanın var, benimse eylemlerim.›› Eylemlerin olmadan sen bana imanını göster, ben de sana imanımı eylemlerimle göstereyim.'),
(2013101,68,59,2,19,'Sen Tanrının bir olduğuna inanıyorsun, iyi ediyorsun. Cinler bile buna inanıyor ve titriyorlar!'),
(2013102,68,59,2,20,'Ey akılsız adam, eylem olmadan imanın yararsız olduğuna kanıt mı istiyorsun?'),
(2013103,68,59,2,21,'Atamız İbrahim, oğlu İshakı sunağın üzerinde Tanrıya adama eylemiyle aklanmadı mı?'),
(2013104,68,59,2,22,'Görüyorsun, onun imanı eylemleriyle birlikte etkindi; imanı eylemleriyle tamamlandı.'),
(2013105,68,59,2,23,'Böylelikle, ‹‹İbrahim Tanrıya iman etti, böylece aklanmış sayıldı›› diyen Kutsal Yazı yerine gelmiş oldu. İbrahime de Tanrının dostu dendi.'),
(2013106,68,59,2,24,'Görüyorsunuz, insan yalnız imanla değil, eylemle de aklanır.'),
(2013107,68,59,2,25,'Aynı biçimde, ulakları konuk edip değişik bir yoldan geri gönderen fahişe Rahav da bu eylemiyle aklanmadı mı?'),
(2013108,68,59,2,26,'Ruhsuz beden nasıl ölüyse, eylemsiz iman da ölüdür.'),
(2013109,68,59,3,1,'Kardeşlerim, biz öğretmenlerin daha titiz bir yargılamadan geçeceğini biliyorsunuz; bu nedenle çoğunuz öğretmen olmayın.'),
(2013110,68,59,3,2,'Çünkü hepimiz çok hata yaparız. Sözleriyle hata yapmayan kimse, bütün bedenini de dizginleyebilen yetkin bir kişidir.'),
(2013111,68,59,3,3,'Bize boyun eğmeleri için atların ağzına gem vururuz, böylece bütün bedenlerini yönlendiririz.'),
(2013112,68,59,3,4,'Düşünün, gemiler de o kadar büyük olduğu, güçlü rüzgarlar tarafından sürüklendiği halde, dümencinin gönlü nereye isterse küçücük bir dümenle o yöne çevrilirler.'),
(2013113,68,59,3,5,'Bunun gibi, dil de bedenin küçük bir üyesidir, ama büyük işlerle övünür. Düşünün, küçücük bir kıvılcım koca bir ormanı tutuşturabilir.'),
(2013114,68,59,3,6,'Dil de bir ateş, bedenimizin üyeleri arasında bir kötülük dünyasıdır. Bütün varlığımızı kirletir. Cehennemden alevlenmiş olarak yaşamımızın gidişini alevlendirir.'),
(2013115,68,59,3,7,'İnsan soyu, her tür yabanıl hayvanı, kuşu, sürüngeni ve deniz yaratığını evcilleştirmiş ve evcilleştirmektedir.'),
(2013116,68,59,3,8,'Ama dili hiçbir insan evcilleştiremez. Dil öldürücü zehirle dolu, dinmeyen bir kötülüktür.'),
(2013117,68,59,3,9,'Dilimizle Rabbi, Babayı överiz. Yine dilimizle Tanrıya benzer yaratılmış insana söveriz.'),
(2013118,68,59,3,10,'Övgü ve sövgü aynı ağızdan çıkar. Kardeşlerim, bu böyle olmamalı.'),
(2013119,68,59,3,11,'Bir pınar aynı gözden tatlı ve acı su akıtır mı?'),
(2013120,68,59,3,12,'Kardeşlerim, incir ağacı zeytin ya da asma incir verebilir mi? Bunun gibi, tuzlu su kaynağı tatlı su veremez.'),
(2013121,68,59,3,13,'Aranızda bilge ve anlayışlı olan kim? Olumlu yaşayışıyla, bilgelikten doğan alçakgönüllülükle iyi eylemlerini göstersin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013122,68,59,3,14,'Ama yüreğinizde kin, kıskançlık, bencillik varsa övünmeyin, gerçeği yadsımayın.'),
(2013123,68,59,3,15,'Böylesi ‹‹bilgelik›› gökten inen değil, dünyadan, insan doğasından, cinlerden gelen bilgeliktir.'),
(2013124,68,59,3,16,'Çünkü nerede kıskançlık, bencillik varsa, orada karışıklık ve her tür kötülük vardır.'),
(2013125,68,59,3,17,'Ama gökten inen bilgelik her şeyden önce paktır, sonra barışçıldır, yumuşaktır, uysaldır. Merhamet ve iyi meyvelerle doludur. Kayırıcılığı, ikiyüzlülüğü yoktur.'),
(2013126,68,59,3,18,'Barış içinde eken barış yapıcıları doğruluk ürününü biçerler.'),
(2013127,68,59,4,1,'Aranızdaki kavgaların, çekişmelerin kaynağı nedir? Bedeninizin üyelerinde savaşan tutkularınız değil mi?'),
(2013128,68,59,4,2,'Bir şey arzu ediyor, elde edemeyince adam öldürüyorsunuz. Kıskanıyorsunuz, isteğinize erişemeyince çekişip kavga ediyorsunuz. Elde edemiyorsunuz, çünkü Tanrıdan dilemiyorsunuz.'),
(2013129,68,59,4,3,'Dilediğiniz zaman da dileğinize kavuşamıyorsunuz. Çünkü kötü amaçla, tutkularınız uğruna kullanmak için diliyorsunuz.'),
(2013130,68,59,4,4,'Ey vefasızlar, dünyayla dostluğun Tanrıya düşmanlık olduğunu bilmiyor musunuz? Dünyayla dost olmak isteyen, kendini Tanrıya düşman eder.'),
(2013131,68,59,4,5,'Sizce Kutsal Yazı boş yere mi şöyle diyor: ‹‹Tanrı içimize koyduğu ruhu kıskançlık derecesinde özler.››'),
(2013132,68,59,4,6,'Yine de bize daha çok lütfeder. Bu nedenle Yazı şöyle diyor: ‹‹Tanrı kibirlilere karşıdır, Ama alçakgönüllülere lütfeder.››'),
(2013133,68,59,4,7,'Bunun için Tanrıya bağımlı olun. İblise karşı direnin, sizden kaçacaktır.'),
(2013134,68,59,4,8,'Tanrıya yaklaşın, O da size yaklaşacaktır. Ey günahkârlar, ellerinizi günahtan temizleyin. Ey kararsızlar, yüreklerinizi paklayın.'),
(2013135,68,59,4,9,'Kederlenin, yas tutup ağlayın. Gülüşünüz yasa, sevinciniz üzüntüye dönüşsün.'),
(2013136,68,59,4,10,'Rabbin önünde kendinizi alçaltın, sizi yüceltecektir.'),
(2013137,68,59,4,11,'Kardeşlerim, birbirinizi yermeyin. Kardeşini yeren ya da yargılayan kişi, Yasayı yermiş ve yargılamış olur. Yasayı yargılarsan, Yasanın uygulayıcısı değil, yargılayıcısı olursun.'),
(2013138,68,59,4,12,'Oysa tek Yasa koyucu, tek Yargıç vardır; kurtarmaya da mahvetmeye de gücü yeten Odur. Ya komşusunu yargılayan sen, kim oluyorsun?'),
(2013139,68,59,4,13,'Dinleyin şimdi, ‹‹Bugün ya da yarın filan kente gideceğiz, orada bir yıl kalıp ticaret yapacak, para kazanacağız›› diyen sizler, yarın ne olacağını bilmiyorsunuz. Yaşamınız nedir ki? Kısa süre görünen, sonra yitip giden buğu gibisiniz.'),
(2013140,68,59,4,15,'Bunun yerine, ‹‹Rab dilerse yaşayacak, şunu şunu yapacağız›› demelisiniz.'),
(2013141,68,59,4,16,'Ne var ki, şimdi küstahlıklarınızla övünüyorsunuz. Bu tür övünmelerin hepsi kötüdür.'),
(2013142,68,59,4,17,'Bu nedenle, yapılması gereken iyi şeyi bilip de yapmayan, günah işlemiş olur.'),
(2013143,68,59,5,1,'Dinleyin şimdi ey zenginler, başınıza gelecek felaketlerden ötürü feryat edip ağlayın.'),
(2013144,68,59,5,2,'Servetiniz çürümüş, giysinizi güve yemiştir.'),
(2013145,68,59,5,3,'Altınlarınız, gümüşleriniz pas tutmuştur. Onların pası size karşı tanıklık edecek, etinizi ateş gibi yiyecek. Bu son çağda servetinize servet kattınız.'),
(2013146,68,59,5,4,'İşte, ekinlerinizi biçen işçilerin haksızca alıkoyduğunuz ücretleri size karşı haykırıyor. Orakçıların feryadı Her Şeye Egemen Rabbin kulağına erişti.'),
(2013147,68,59,5,5,'Yeryüzünde zevk ve bolluk içinde yaşadınız. Boğazlanacağınız gün için kendinizi besiye çektiniz.'),
(2013148,68,59,5,6,'Size karşı koymayan doğru kişiyi yargılayıp öldürdünüz.'),
(2013149,68,59,5,7,'Öyleyse kardeşler, Rabbin gelişine dek sabredin. Bakın, çiftçi ilk ve son yağmurları alıncaya dek toprağın değerli ürününü nasıl sabırla bekliyor!'),
(2013150,68,59,5,8,'Siz de sabredin. Yüreklerinizi güçlendirin. Çünkü Rabbin gelişi yakındır.'),
(2013151,68,59,5,9,'Kardeşler, yargılanmamak için birbirinize karşı homurdanmayın. İşte, Yargıç kapının önünde duruyor.'),
(2013152,68,59,5,10,'Kardeşler, Rabbin adıyla konuşmuş olan peygamberleri sıkıntılarda sabır örneği olarak alın.'),
(2013153,68,59,5,11,'Sıkıntıya dayanmış olanları mutlu sayarız. Eyüpün nasıl dayandığını duydunuz. Rabbin en sonunda onun için neler yaptığını bilirsiniz. Rab çok şefkatli ve merhametlidir.'),
(2013154,68,59,5,12,'Kardeşlerim, öncelikle şunu söyleyeyim: Ne gök üzerine, ne yer üzerine, ne de başka bir şey üzerine ant için. ‹‹Evet››iniz evet, ‹‹hayır››ınız hayır olsun ki, yargıya uğramayasınız.'),
(2013155,68,59,5,13,'İçinizden biri sıkıntıda mı, dua etsin. Sevinçli mi, ilahi söylesin.'),
(2013156,68,59,5,14,'İçinizden biri hasta mı, kilisenin ihtiyarlarını çağırtsın; Rabbin adıyla üzerine yağ sürüp onun için dua etsinler.'),
(2013157,68,59,5,15,'İmanla edilen dua hastayı iyileştirecek ve Rab onu ayağa kaldıracaktır. Eğer hasta günah işlemişse, günahları bağışlanacaktır.'),
(2013158,68,59,5,16,'Bu nedenle, şifa bulmak için günahlarınızı birbirinize itiraf edin ve birbiriniz için dua edin. Doğru kişinin yalvarışı çok güçlü ve etkilidir.'),
(2013159,68,59,5,17,'İlyas da tıpkı bizim gibi insandı. Yağmur yağmaması için gayretle dua etti; üç yıl altı ay ülkeye yağmur yağmadı.'),
(2013160,68,59,5,18,'Yeniden dua etti; gök yağmurunu, toprak da ürününü verdi.'),
(2013161,68,59,5,19,'Kardeşlerim, içinizden biri gerçeğin yolundan sapar da başka biri onu yine gerçeğe döndürürse, bilsin ki, günahkârı sapık yolundan döndüren, ölümden bir can kurtarmış, bir sürü günahı örtmüş olur.'),
(2013162,68,60,1,1,'Mesih İsanın elçisi ben Petrustan Pontus, Galatya, Kapadokya, Asya İli ve Bitinyaya dağılmış ve buralarda yabancı olarak yaşayan seçilmişlere selam!'),
(2013163,68,60,1,2,'İsa Mesihin sözünü dinlemeniz ve Onun kanının üzerinize serpilmesi için, Baba Tanrının öngörüsü uyarınca Ruh tarafından kutsal kılınarak seçildiniz. Lütuf ve esenlik artan ölçüde sizin olsun.'),
(2013164,68,60,1,3,'Rabbimiz İsa Mesihin Tanrısı ve Babasına övgüler olsun. Çünkü O büyük merhametiyle yeniden doğmamızı sağladı. İsa Mesihi ölümden diriltmekle bizi yaşayan bir umuda, çürümez, lekesiz, solmaz bir mirasa kavuşturdu. Bu miras sizin için göklerde saklıdır.'),
(2013165,68,60,1,5,'Zaman sona ererken açığa çıkarılmaya hazır olan kurtuluşa kavuşasınız diye iman sayesinde Tanrının gücüyle korunuyorsunuz.'),
(2013166,68,60,1,6,'Bu nedenle şimdi kısa bir süre çeşitli denemeler sonucu acı çekmeniz gerekiyorsa da, sevinçle coşmaktasınız.'),
(2013167,68,60,1,7,'Böylelikle içtenliği kanıtlanan imanınız, İsa Mesih göründüğünde size övgü, yücelik, onur kazandıracak. İmanınız, ateşle arıtıldığı halde yok olup giden altından daha değerlidir.'),
(2013168,68,60,1,8,'Mesihi görmemiş olsanız da Onu seviyorsunuz. Şu anda Onu görmediğiniz halde Ona iman ediyor, sözle anlatılmaz yüce bir sevinçle coşuyorsunuz.'),
(2013169,68,60,1,9,'Çünkü imanınızın sonucu olarak canlarınızın kurtuluşuna erişiyorsunuz.'),
(2013170,68,60,1,10,'Size bağışlanacak lütuftan söz etmiş olan peygamberler, bu kurtuluşla ilgili dikkatli incelemeler, araştırmalar yaptılar.'),
(2013171,68,60,1,11,'İçlerinde olan Mesih Ruhu, Mesihin çekeceği acılara ve bu acıların ardından gelecek yüceliklere tanıklık ettiğinde, Ruhun hangi zamanı ya da nasıl bir dönemi belirttiğini araştırdılar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013172,68,60,1,12,'Şimdi size de bildirilen gerçeklerle kendilerine değil, size hizmet ettikleri onlara açıkça gösterildi. Bu gerçekleri gökten gönderilen Kutsal Ruhun gücüyle size Müjdeyi iletenler bildirdi. Melekler bu gerçekleri yakından görmeye büyük özlem duyarlar.'),
(2013173,68,60,1,13,'Bu nedenle zihinlerinizi eyleme hazırlayın, ayık olun. Umudunuzu tümüyle İsa Mesihin görünmesiyle size sağlanacak olan lütfa bağlayın.'),
(2013174,68,60,1,14,'Söz dinleyen çocuklar olarak, bilgisiz olduğunuz geçmiş zamandaki tutkularınıza uymayın.'),
(2013175,68,60,1,15,'Sizi çağıran Tanrı kutsal olduğuna göre, siz de her davranışınızda kutsal olun.'),
(2013176,68,60,1,16,'Nitekim şöyle yazılmıştır: ‹‹Kutsal olun, çünkü ben kutsalım.››'),
(2013177,68,60,1,17,'Kimseyi kayırmadan, kişiyi yaptıklarına bakarak yargılayan Tanrıyı Baba diye çağırdığınıza göre, gurbeti andıran bu dünyadaki zamanınızı Tanrı korkusuyla geçirin.'),
(2013178,68,60,1,18,'Biliyorsunuz ki, atalarınızdan kalma boş yaşayışınızdan altın ya da gümüş gibi geçici şeylerle değil, kusursuz ve lekesiz kuzuyu andıran Mesihin değerli kanının fidyesiyle kurtuldunuz.'),
(2013179,68,60,1,20,'Dünyanın kuruluşundan önce bilinen Mesih, çağların sonunda sizin yararınıza ortaya çıktı.'),
(2013180,68,60,1,21,'Onu ölümden diriltip yücelten Tanrıya Onun aracılığıyla iman ediyorsunuz. Böylece imanınız ve umudunuz Tanrıdadır.'),
(2013181,68,60,1,22,'Gerçeğe uymakla kendinizi arıttınız, kardeşler için içten bir sevgiye sahip oldunuz. Onun için birbirinizi candan, yürekten sevin.'),
(2013182,68,60,1,23,'Çünkü ölümlü değil, ölümsüz bir tohumdan, yani Tanrının diri ve kalıcı sözü aracılığıyla yeniden doğdunuz.'),
(2013183,68,60,1,24,'Nitekim, ‹‹İnsan soyu ota benzer, Bütün yüceliği kır çiçeği gibidir. Ot kurur, çiçek solar, Ama Rab''bin sözü sonsuza dek kalır.››'),
(2013184,68,60,2,1,'Bu nedenle her kötülüğü, hileyi, ikiyüzlülüğü, kıskançlığı ve bütün iftiraları üzerinizden sıyırıp atın.'),
(2013185,68,60,2,2,'Yeni doğmuş bebekler gibi, hilesiz sütü andıran Tanrı sözünü özleyin ki, bununla beslenip büyüyerek kurtuluşa erişesiniz.'),
(2013186,68,60,2,3,'Çünkü Rabbin iyiliğini tattınız.'),
(2013187,68,60,2,4,'İnsanlarca reddedilmiş, ama Tanrıya göre seçkin ve değerli olan diri taşa, Rabbe gelin.'),
(2013188,68,60,2,5,'O sizi diri taşlar olarak ruhsal bir tapınağın yapımında kullansın. Böylelikle, İsa Mesih aracılığıyla Tanrının beğenisini kazanan ruhsal kurbanlar sunmak üzere kutsal bir kâhinler topluluğu olursunuz.'),
(2013189,68,60,2,6,'Çünkü Kutsal Yazıda şöyle deniyor: ‹‹İşte, Siyona bir taş, Seçkin, değerli bir köşe taşı koyuyorum. Ona iman eden hiç utandırılmayacak.››'),
(2013190,68,60,2,7,'İman eden sizler için bu taş değerlidir. Ama imansızlar için, ‹‹Yapıcıların reddettiği taş Köşenin baş taşı,›› ‹‹Sürçme taşı ve tökezleme kayası oldu.›› belirlenmişlerdir.'),
(2013191,68,60,2,9,'Ama siz seçilmiş soy, Kralın kâhinleri, kutsal ulus, Tanrının öz halkısınız. Sizi karanlıktan şaşılası ışığına çağıran Tanrının erdemlerini duyurmak için seçildiniz.'),
(2013192,68,60,2,10,'Bir zamanlar halk değildiniz, ama şimdi Tanrının halkısınız. Bir zamanlar merhamete erişmemiştiniz, şimdiyse merhamete eriştiniz.'),
(2013193,68,60,2,11,'Sevgili kardeşler, size yalvarırım, cana karşı savaşan benliğin tutkularından kaçının. Çünkü bu dünyada yabancı ve konuksunuz.'),
(2013194,68,60,2,12,'İnanmayanlar arasında olumlu bir yaşam sürün. Öyle ki, kötülük yapanlarmışsınız gibi size iftira etseler de, iyi işlerinizi görerek Tanrıyı, kendilerine yaklaştığı gün yüceltsinler.'),
(2013195,68,60,2,13,'İnsanlar arasında yetkili kılınmış her kuruma -gerek her şeyin üstünde olan krala gerekse kötülük yapanların cezalandırılması, iyilik edenlerin onurlandırılması için kral tarafından gönderilen valilere- Rab adına bağımlı olun.'),
(2013196,68,60,2,15,'Çünkü Tanrının isteği, iyilik yaparak akılsızların bilgisizliğini susturmanızdır.'),
(2013197,68,60,2,16,'Özgür insanlar olarak yaşayın, ancak özgürlüğünüzü kötülük yapmak için bahane etmeyin. Tanrının kulları olarak yaşayın.'),
(2013198,68,60,2,17,'Herkese saygı gösterin. İmanlı kardeşlerinizi sevin, Tanrıdan korkun, krala saygı gösterin.'),
(2013199,68,60,2,18,'Ey hizmetkârlar, efendilerinizin yalnız iyi ve yumuşak huylu olanlarına değil, ters huylu olanlarına da tam bir saygıyla bağımlı olun.'),
(2013200,68,60,2,19,'Haksız yere acı çeken kişi, Tanrı bilinciyle acıya katlanırsa, Tanrıyı hoşnut eder.'),
(2013201,68,60,2,20,'Çünkü günah işleyip dövüldüğünüzde dayanırsanız, bunda övülecek ne var? Ama iyilik edip acı çektiğinizde dayanırsanız, Tanrıyı hoşnut edersiniz.'),
(2013202,68,60,2,21,'Nitekim bunun için çağrıldınız. Mesih, izinden gidesiniz diye uğrunuza acı çekerek size örnek oldu.'),
(2013203,68,60,2,22,'‹‹O günah işlemedi, ağzından hileli söz çıkmadı.››'),
(2013204,68,60,2,23,'Kendisine sövüldüğünde sövgüyle karşılık vermedi, acı çektiğinde kimseyi tehdit etmedi; davasını, adaletle yargılayan Tanrıya bıraktı.'),
(2013205,68,60,2,24,'Bizler günah karşısında ölelim, doğruluk uğruna yaşayalım diye, günahlarımızı çarmıhta kendi bedeninde yüklendi. Onun yaralarıyla şifa buldunuz.'),
(2013206,68,60,2,25,'Çünkü yolunu şaşırmış koyunlar gibiydiniz, şimdiyse canlarınızın Çobanı''na ve Gözetmeni''ne döndünüz.'),
(2013207,68,60,3,1,'Bunun gibi, ey kadınlar, siz de kocalarınıza bağımlı olun. Öyle ki, kimileri Tanrı sözüne inanmasa bile, Tanrı korkusuna dayanan temiz yaşayışınızı görerek söze gerek kalmadan karılarının yaşayışıyla kazanılsınlar.'),
(2013208,68,60,3,3,'Süsünüz örgülü saçlar, altın takılar, güzel giysiler gibi dışla ilgili olmasın.'),
(2013209,68,60,3,4,'Gizli olan iç varlığınız, sakin ve yumuşak bir ruhun solmayan güzelliğiyle süsünüz olsun. Bu, Tanrının gözünde çok değerlidir.'),
(2013210,68,60,3,5,'Çünkü geçmişte umudunu Tanrıya bağlamış olan kutsal kadınlar da kocalarına bağımlı olarak böyle süslenirlerdi.'),
(2013211,68,60,3,6,'Örneğin Sara İbrahimi ‹‹Efendim›› diye çağırır, sözünü dinlerdi. İyilik eder, hiçbir tehditten yılmazsanız, siz de Saranın çocukları olursunuz.'),
(2013212,68,60,3,7,'Bunun gibi, ey kocalar, siz de daha zayıf varlıklar olan karılarınızla anlayış içinde yaşayın. Tanrının lütfettiği yaşamın ortak mirasçıları oldukları için onlara saygı gösterin. Öyle ki, dualarınıza bir engel çıkmasın.'),
(2013213,68,60,3,8,'Sonuç olarak hepiniz aynı düşüncede birleşin. Başkalarının duygularını paylaşın. Birbirinizi kardeşçe sevin. Şefkatli, alçakgönüllü olun.'),
(2013214,68,60,3,9,'Kötülüğe kötülükle, sövgüye sövgüyle değil, tersine, kutsamayla karşılık verin. Çünkü kutsanmayı miras almak için çağrıldınız.'),
(2013215,68,60,3,10,'Şöyle ki, ‹‹Yaşamdan zevk almak, İyi günler görmek isteyen, Dilini kötülükten, Dudaklarını yalandan uzak tutsun.'),
(2013216,68,60,3,11,'Kötülükten sakınıp iyilik yapsın. Esenliği amaçlasın, ardınca gitsin.'),
(2013217,68,60,3,12,'Çünkü Rabbin gözleri Doğru kişilerin üzerindedir. Kulakları onların yakarışına açıktır. Ama Rab kötülük yapanlara karşıdır.››'),
(2013218,68,60,3,13,'İyilik yapmakta gayretli olursanız, size kim kötülük edecek?'),
(2013219,68,60,3,14,'Doğruluk uğruna acı çekseniz bile, ne mutlu size! İnsanların ‹‹korktuğundan korkmayın, ürkmeyin.››'),
(2013220,68,60,3,15,'Mesihi Rab olarak yüreklerinizde kutsayın. İçinizdeki umudun nedenini soran herkese uygun bir yanıt vermeye her zaman hazır olun.'),
(2013221,68,60,3,16,'Yalnız bunu yumuşak huyla, saygıyla yapın. Vicdanınızı temiz tutun. Öyle ki, Mesihe ait olarak sürdürdüğünüz olumlu yaşamı kınayanlar size ettikleri iftiradan utansınlar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013222,68,60,3,17,'İyilik edip acı çekmek -eğer Tanrının isteği buysa- kötülük yapıp acı çekmekten daha iyidir.'),
(2013223,68,60,3,18,'Nitekim Mesih de bizleri Tanrıya ulaştırmak amacıyla doğru kişi olarak doğru olmayanlar için günah sunusu olarak ilk ve son kez öldü. Bedence öldürüldü, ama ruhça diriltildi.'),
(2013224,68,60,3,19,'Ruhta gidip bunları zindanda olan ruhlara da duyurdu.'),
(2013225,68,60,3,20,'Bir zamanlar, Nuhun günlerinde gemi yapılırken, Tanrının sabırla beklemesine karşın bu ruhlar söz dinlememişlerdi. O gemide birkaç kişi, daha doğrusu sekiz kişi suyla kurtuldu.'),
(2013226,68,60,3,21,'Bu olay vaftizi simgeliyor. Bedenin kirden arınması değil, Tanrıya yönelen temiz vicdanın dileği olan vaftiz, İsa Mesihin dirilişiyle şimdi sizi de kurtarıyor.'),
(2013227,68,60,3,22,'Göğe çıkmış olan Mesih Tanrı''nın sağındadır. Bütün melekler, yetkiler ve güçler O''na bağlı kılınmıştır.'),
(2013228,68,60,4,1,'Mesih bedence acı çektiğine göre, siz de aynı düşünceyle silahlanın. Çünkü bedence acı çekmiş olan, günaha sırt çevirmiştir.'),
(2013229,68,60,4,2,'Sonuç olarak, dünyadaki yaşamının geri kalan bölümünü artık insan tutkularına göre değil, Tanrının isteğine göre sürdürür.'),
(2013230,68,60,4,3,'İnanmayanların hoşlandıklarını yaparak sefahat, şehvet, sarhoşluk, çılgın eğlenceler, içki alemleri ve ilke tanımayan putperestlik içinde yaşayarak geçmişte harcadığınız günler yeter!'),
(2013231,68,60,4,4,'İnanmayanlar, kendinizi onlarla birlikte aynı sefahat seline atmamanızı yadırgıyor, size sövüyorlar.'),
(2013232,68,60,4,5,'Onlar, ölüleri de dirileri de yargılamaya hazır olan Tanrıya hesap verecekler.'),
(2013233,68,60,4,6,'Çünkü ölüler bedence öbür insanlar gibi yargılansın, ama ruhça Tanrı gibi yaşasın diye Müjde onlara da bildirildi.'),
(2013234,68,60,4,7,'Her şeyin sonu yakındır. Bu nedenle, sağduyulu olun ve dua etmek için ayık durun.'),
(2013235,68,60,4,8,'Her şeyden önce birbirinizi candan sevin. Çünkü sevgi birçok günahı örter.'),
(2013236,68,60,4,9,'Söylenmeksizin birbirinize konukseverlik gösterin.'),
(2013237,68,60,4,10,'Her biriniz hangi ruhsal armağanı aldıysanız, bunu Tanrının çok yönlü lütfunun iyi kâhyaları olarak birbirinize hizmet etmekte kullanın.'),
(2013238,68,60,4,11,'Konuşan, Tanrının sözlerini iletir gibi konuşsun. Başkalarına hizmet eden, Tanrının verdiği güçle hizmet etsin. Öyle ki, İsa Mesih aracılığıyla Tanrı her şeyde yüceltilsin. Yücelik ve kudret sonsuzlara dek Mesihindir! Amin.'),
(2013239,68,60,4,12,'Sevgili kardeşlerim, sınanmanız için size giydirilen ateşten gömleği, size garip bir şey oluyormuş gibi yadırgamayın.'),
(2013240,68,60,4,13,'Tersine, Mesihin acılarına ortak olduğunuz oranda sevinin ki, Mesihin görkemi göründüğünde de sevinçle coşasınız.'),
(2013241,68,60,4,14,'Mesihin adından ötürü hakarete uğrarsanız, ne mutlu size! Çünkü Tanrının yüce Ruhu üzerinizde bulunuyor.'),
(2013242,68,60,4,15,'Hiçbiriniz katil, hırsız, kötülük yapan ya da başkalarının işine karışan biri olarak acı çekmesin.'),
(2013243,68,60,4,16,'Ama Mesih inanlısı olduğu için acı çeken, bundan utanç duymasın. Taşıdığı bu adla Tanrıyı yüceltsin.'),
(2013244,68,60,4,17,'Çünkü yargının, Tanrının ev halkından başlayacağı an gelmiştir. Eğer yargılama önce bizden başlarsa, Tanrının Müjdesine kulak asmayanların sonu ne olacak?'),
(2013245,68,60,4,18,'‹‹Doğru kişi güçlükle kurtuluyorsa, Tanrısız ve günahlı kişiye ne olacak?››'),
(2013246,68,60,4,19,'Bunun için, Tanrı''nın isteği uyarınca acı çekenler, iyilik ederek canlarını güvenilir Yaradan''a emanet etsinler.'),
(2013247,68,60,5,1,'Bu nedenle aranızdaki ihtiyarlara, onlar gibi bir ihtiyar, Mesihin çektiği acıların tanığı, açığa çıkacak olan yüceliğin paydaşı olarak rica ediyorum: Tanrının size verdiği sürüyü güdün. Zorunluymuş gibi değil, Tanrının istediği gibi gönüllü gözetmenlik yapın. Para hırsıyla değil, gönül rızasıyla, size emanet edilenlere egemenlik taslamadan, sürüye örnek olarak görevinizi yapın.'),
(2013248,68,60,5,4,'Baş Çoban göründüğü zaman yüceliğin solmaz tacına kavuşacaksınız.'),
(2013249,68,60,5,5,'Ey gençler, siz de ihtiyarlara bağımlı olun. Hepiniz birbirinize karşı alçakgönüllülüğü kuşanın. Çünkü, ‹‹Tanrı kibirlilere karşıdır, Ama alçakgönüllülere lütfeder.››'),
(2013250,68,60,5,6,'Uygun zamanda sizi yüceltmesi için, Tanrının kudretli eli altında kendinizi alçaltın.'),
(2013251,68,60,5,7,'Bütün kaygılarınızı Ona yükleyin, çünkü O sizi kayırır.'),
(2013252,68,60,5,8,'Ayık ve uyanık olun. Düşmanınız İblis kükreyen aslan gibi yutacak birini arayarak dolaşıyor.'),
(2013253,68,60,5,9,'Dünyanın her yerindeki kardeşlerinizin de aynı acıları çektiğini bilerek imanda sarsılmadan İblise karşı direnin.'),
(2013254,68,60,5,10,'Sizleri Mesihte sonsuz yüceliğine çağıran ve bütün lütfun kaynağı olan Tanrının kendisi kısa bir süre acı çekmenizden sonra sizi yetkinleştirip pekiştirecek, güçlendirip temellendirecektir.'),
(2013255,68,60,5,11,'Kudret sonsuzlara dek Onun olsun! Amin.'),
(2013256,68,60,5,12,'Kendisini güvenilir bir kardeş saydığım Silvanus aracılığıyla size kısaca yazmış bulunuyorum. Sizi yüreklendiriyor ve sözünü ettiğim lütfun Tanrının gerçek lütfu olduğuna tanıklık ediyorum. Buna bağlı kalın.'),
(2013257,68,60,5,13,'Sizler gibi seçilmiş olan Babildeki kilise ve oğlum Markos size selam ederler.'),
(2013258,68,60,5,14,'Birbirinizi sevgiyle öperek selamlayın. Sizlere, Mesih''e ait olan herkese esenlik olsun.'),
(2013259,68,61,1,1,'İsa Mesihin kulu ve elçisi ben Simun Petrustan Tanrımız ve Kurtarıcımız İsa Mesihin doğruluğu sayesinde bizimkiyle eşdeğer bir imana kavuşmuş olanlara selam!'),
(2013260,68,61,1,2,'Tanrıyı ve Rabbimiz İsayı tanımakla lütuf ve esenlik artan ölçüde sizin olsun.'),
(2013261,68,61,1,3,'Kendi yüceliği ve erdemiyle bizi çağıranın tanrısal gücü, kendisini tanımamız sonucunda yaşamamız ve Tanrı yolunda yürümemiz için gereken her şeyi bize verdi.'),
(2013262,68,61,1,4,'Onun yüceliği ve erdemi sayesinde bize çok büyük ve değerli vaatler verildi. Öyle ki, dünyada kötü arzuların yol açtığı yozlaşmadan kurtulmuş olarak, bu vaatler aracılığıyla tanrısal özyapıya ortak olasınız.'),
(2013263,68,61,1,5,'İşte bu nedenle her türlü gayreti göstererek imanınıza erdemi, erdeminize bilgiyi, bilginize özdenetimi, özdenetiminize dayanma gücünü, dayanma gücünüze Tanrı yoluna bağlılığı, bağlılığınıza kardeşseverliği, kardeşseverliğinize sevgiyi katın.'),
(2013264,68,61,1,8,'Çünkü bu niteliklere artan ölçüde sahip olursanız, Rabbimiz İsa Mesihi tanımakta etkisiz ve verimsiz olmazsınız.'),
(2013265,68,61,1,9,'Bu niteliklere sahip olmayan uzağı göremez, kördür. Eski günahlarından temizlendiğini unutmuştur.'),
(2013266,68,61,1,10,'Bunun için, ey kardeşler, çağrılmışlığınızı ve seçilmişliğinizi kökleştirmeye daha çok gayret edin. Bunları yaparsanız, hiçbir zaman tökezlemezsiniz.'),
(2013267,68,61,1,11,'Böylece Rabbimiz ve Kurtarıcımız İsa Mesihin sonsuz egemenliğine girme hakkı size cömertçe sağlanacaktır.'),
(2013268,68,61,1,12,'Onun için, her ne kadar bunları biliyorsanız ve sahip olduğunuz gerçekle pekiştirilmişseniz de, bunları size her zaman anımsatacağım.'),
(2013269,68,61,1,13,'Bu bedende yaşadığım sürece bunları anımsatarak sizi gayrete getirmeyi doğru buluyorum.'),
(2013270,68,61,1,14,'Rabbimiz İsa Mesihin bana bildirdiği gibi, bedenden ayrılışımın yakın olduğunu biliyorum.'),
(2013271,68,61,1,15,'Ben bu dünyadan göçtükten sonra da bunları sürekli anımsayabilmeniz için şimdi her gayreti göstereceğim.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013272,68,61,1,16,'Rabbimiz İsa Mesihin kudretini ve gelişini size bildirirken uydurma masallara başvurmadık. Onun görkemini gözlerimizle gördük.'),
(2013273,68,61,1,17,'Mesih, yüce ve görkemli Olandan kendisine ulaşan sesle, ‹‹Sevgili Oğlum budur, Ondan hoşnudum›› diyen sesle Baba Tanrıdan onur ve yücelik aldı.'),
(2013274,68,61,1,18,'Kutsal dağda Onunla birlikte bulunduğumuz için gökten gelen bu sesi biz de işittik.'),
(2013275,68,61,1,19,'Peygamberlerin sözleri bizim için daha büyük kesinlik kazandı. Gün ağarıp sabah yıldızı yüreklerinizde doğuncaya dek, karanlık yerde ışık saçan çıraya benzeyen bu sözlere kulak verirseniz, iyi edersiniz.'),
(2013276,68,61,1,20,'Öncelikle şunu bilin ki, Kutsal Yazılardaki hiçbir peygamberlik sözü kimsenin özel yorumu değildir.'),
(2013277,68,61,1,21,'Çünkü hiçbir peygamberlik sözü insan isteğinden kaynaklanmadı. Kutsal Ruh tarafından yöneltilen insanlar Tanrı''nın sözlerini ilettiler.'),
(2013278,68,61,2,1,'Ama İsrail halkı arasında sahte peygamberler vardı; tıpkı sizin de aranızda yanlış öğreti yayanlar olacağı gibi. Bunlar kendilerini satın alan Efendiyi bile yadsıyarak gizlice aranıza yıkıcı öğretiler sokacaklar. Böyleleri kendi başlarına ani bir yıkım getirecek.'),
(2013279,68,61,2,2,'Birçokları da onların sefahatine kapılacak. Onların yüzünden gerçeğin yoluna sövülecek.'),
(2013280,68,61,2,3,'Açgözlülüklerinden ötürü uydurma sözlerle sizi sömürecekler. Onlar için çoktan beri verilmiş olan yargı gecikmez. Onları bekleyen yıkım da uyuklamaz.'),
(2013281,68,61,2,4,'Tanrı günah işleyen melekleri esirgemedi; onları cehenneme atıp karanlıkta zincire vurdu. Yargılanıncaya dek orada tutulacaklar.'),
(2013282,68,61,2,5,'Tanrı eski dünyayı da esirgemedi. Ama tanrısızların dünyasına tufanı gönderdiğinde, doğruluk yolunu bildiren Nuhu ve yedi kişiyi daha korudu.'),
(2013283,68,61,2,6,'Sodom ve Gomora kentlerini yakıp yıkarak yargıladı. Böylece tanrısızların başına geleceklere bir örnek verdi.'),
(2013284,68,61,2,7,'Ama ilke tanımayan kişilerin sefih yaşayışından azap duyan doğru adam Lutu kurtardı.'),
(2013285,68,61,2,8,'Çünkü onların arasında yaşayan bu doğru adam, görüp işittiği yasa tanımaz davranışlar yüzünden doğru yüreğinde her gün ıstırap çekerdi.'),
(2013286,68,61,2,9,'Görülüyor ki Rab kendi yolunda yürüyenleri karşılaştıkları denemelerden nasıl kurtaracağını bilir. Doğru olmayanları, özellikle benliğin yozlaşmış tutkuları ardından giden ve yetkisini hor görenleri cezalandırarak yargı gününe dek nasıl alıkoyacağını da bilir. Bu küstah, dikbaşlı kişiler yüce varlıklara sövmekten korkmazlar.'),
(2013287,68,61,2,11,'Oysa melekler bile, güç ve kudrette daha üstün oldukları halde bu varlıkları Rabbin önünde söverek yargılamazlar.'),
(2013288,68,61,2,12,'Ama anlamadıkları konularda sövüp sayan bu kişiler, içgüdüleriyle yaşayan, yakalanıp boğazlanmak üzere doğan, akıldan yoksun hayvanlar gibidir. Hayvanlar gibi onlar da yıkıma uğrayacaklar.'),
(2013289,68,61,2,13,'Ettikleri haksızlığa karşılık zarar görecekler. Gündüzün zevk alemlerine dalmayı eğlence sayarlar. Birer leke ve yüzkarasıdırlar. Sizinle yiyip içerken kendi hilelerinden zevk alırlar.'),
(2013290,68,61,2,14,'Gözleri zinayla doludur, günaha doymazlar. Kararsız kişileri ayartırlar. Yüreği açgözlülüğe alıştırılmış lanetli insanlardır.'),
(2013291,68,61,2,15,'Haksızlıkla elde ettiği kazancı seven Beor oğlu Balamın yolunu tutarak doğru yolu bırakıp saptılar.'),
(2013292,68,61,2,16,'Balam işlediği suçtan ötürü azarlandı. Konuşamayan eşek, insan diliyle konuşarak bu peygamberin çılgınlığına engel oldu.'),
(2013293,68,61,2,17,'Bu kişiler, susuz pınarlar, fırtınanın dağıttığı sis gibidirler. Onları koyu karanlık bekliyor.'),
(2013294,68,61,2,18,'Çünkü yanlış yolda yürüyenlerden henüz kurtulanları, boş ve kurumlu sözler söyleyerek benliğin tutkularıyla, sefahatle ayartırlar.'),
(2013295,68,61,2,19,'Onlara özgürlük vaat ederler, oysa kendileri yozlaşmışlığın kölesidirler. Çünkü insan neye yenilirse onun kölesi olur.'),
(2013296,68,61,2,20,'Rab ve Kurtarıcı İsa Mesihi tanımakla dünyanın çirkefliğinden kurtulduktan sonra yine aynı işlere karışıp yenilirlerse, son durumları ilk durumlarından beter olur.'),
(2013297,68,61,2,21,'Çünkü doğruluk yolunu bilip de kendilerine emanet edilen kutsal buyruktan geri dönmektense, bu yolu hiç bilmemiş olmak onlar için daha iyi olurdu.'),
(2013298,68,61,2,22,'Şu gerçek özdeyiş onların durumunu anlatıyor: ‹‹Köpek kendi kusmuğuna döner››, ‹‹Domuz da yıkandıktan sonra çamurda yuvarlanmaya döner.››'),
(2013299,68,61,3,1,'Sevgili kardeşler, şimdi bu benim size yazdığım ikinci mektuptur. Her iki mektubumda da bu konuları anımsatarak temiz düşüncelerinizi uyandırmaya çalıştım.'),
(2013300,68,61,3,2,'Öyle ki, kutsal peygamberlerin çok önceden söylediği sözleri ve Kurtarıcımız Rabbin elçileriniz aracılığıyla verdiği buyruğu anımsayasınız.'),
(2013301,68,61,3,3,'Öncelikle şunu bilmelisiniz: Dünyanın son günlerinde kendi tutkularının ardından giden alaycı kişiler türeyecek. Bunlar, ‹‹Rabbin gelişiyle ilgili vaat ne oldu? Atalarımızın ölümünden beri her şey yaratılışın başlangıcında olduğu gibi duruyor›› diyerek alay edecekler.'),
(2013302,68,61,3,5,'Ne var ki, göklerin çok önceden Tanrının sözüyle var olduğunu, yerin sudan ve su aracılığıyla şekillendiğini bile bile unutuyorlar.'),
(2013303,68,61,3,6,'O zamanki dünya yine suyla, tufanla mahvolmuştu.'),
(2013304,68,61,3,7,'Şimdiki yer ve göklerse ateşe verilmek üzere aynı sözle saklanıyor, tanrısızların yargılanarak mahvolacağı güne dek korunuyorlar.'),
(2013305,68,61,3,8,'Sevgili kardeşlerim, şunu unutmayın ki, Rabbin gözünde bir gün bin yıl, bin yıl bir gün gibidir.'),
(2013306,68,61,3,9,'Bazılarının düşündüğü gibi Rab vaadini yerine getirmekte gecikmez; ama size karşı sabrediyor. Çünkü kimsenin mahvolmasını istemiyor, herkesin tövbe etmesini istiyor.'),
(2013307,68,61,3,10,'Ama Rabbin günü hırsız gibi gelecek. O gün gökler büyük bir gürültüyle ortadan kalkacak, maddesel öğeler yanarak yok olacak, yer ve yeryüzünde yapılmış olan her şey yanıp tükenecek.'),
(2013308,68,61,3,11,'Her şey böylece yok olacağına göre, sizin nasıl kişiler olmanız gerekir? Tanrının gününü bekleyip o günün gelişini çabuklaştırarak kutsallık içinde yaşamalı, Tanrı yolunu izlemelisiniz. O gün gökler yanarak yok olacak, maddesel öğeler şiddetli ateşte eriyip gidecek.'),
(2013309,68,61,3,13,'Ama biz Tanrının vaadi uyarınca doğruluğun barınacağı yeni gökleri, yeni yeryüzünü bekliyoruz.'),
(2013310,68,61,3,14,'Bunun için, sevgili kardeşlerim, mademki bunları bekliyorsunuz, Tanrının önünde lekesiz, kusursuz ve barış içinde olmaya gayret edin.'),
(2013311,68,61,3,15,'Sevgili kardeşimiz Pavlusun da kendisine verilen bilgelikle size yazdığı gibi, Rabbimizin sabrını kurtuluş fırsatı sayın.'),
(2013312,68,61,3,16,'Pavlus bütün mektuplarında bu konulardan böyle söz eder. Mektuplarında güç anlaşılan bazı yerler var ki, bilgisiz ve kararsız kişiler, öbür Kutsal Yazıları olduğu gibi bunları da çarpıtarak kendi yıkımlarını hazırlıyorlar.'),
(2013313,68,61,3,17,'Bu nedenle, sevgili kardeşlerim, ilke tanımayan kişilerin aldatmasıyla sürüklenip kararlılığınızdan sapmamak için bunları önceden bilerek sakının.'),
(2013314,68,61,3,18,'Öte yandan Rabbimiz ve Kurtarıcımız İsa Mesih''in lütfunda ve O''nu tanımakta ilerleyin. Şimdi ve sonsuza dek O''na yücelik olsun! Amin.'),
(2013315,68,62,1,1,'Yaşam Sözüyle ilgili olarak başlangıçtan beri var olanı, işittiğimizi, gözlerimizle gördüğümüzü, seyredip ellerimizle dokunduğumuzu duyuruyoruz.'),
(2013316,68,62,1,2,'Yaşam açıkça göründü, Onu gördük ve Ona tanıklık ediyoruz. Babayla birlikte olup bize görünmüş olan sonsuz Yaşamı size duyuruyoruz.'),
(2013317,68,62,1,3,'Evet, sizin de bizlerle paydaşlığınız olsun diye gördüğümüzü, işittiğimizi size duyuruyoruz. Bizim paydaşlığımız da Babayla ve Oğlu İsa Mesihledir.'),
(2013318,68,62,1,4,'Bunları size, sevincimiz tam olsun diye yazıyoruz.'),
(2013319,68,62,1,5,'Mesihten işittiğimiz ve şimdi size ilettiğimiz bildiri şudur: Tanrı ışıktır, Onda hiç karanlık yoktur.'),
(2013320,68,62,1,6,'Onunla paydaşlığımız var deyip de karanlıkta yürürsek, yalan söylemiş, gerçeğe uymamış oluruz.'),
(2013321,68,62,1,7,'Ama O ışıkta olduğu gibi biz de ışıkta yürürsek, birbirimizle paydaşlığımız olur ve Oğlu İsanın kanı bizi her günahtan arındırır.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013322,68,62,1,8,'Günahımız yok dersek, kendimizi aldatırız, içimizde gerçek olmaz.'),
(2013323,68,62,1,9,'Ama günahlarımızı itiraf edersek, güvenilir ve adil olan Tanrı günahlarımızı bağışlayıp bizi her kötülükten arındıracaktır.'),
(2013324,68,62,1,10,'Günah işlemedik dersek, O''nu yalancı durumuna düşürmüş oluruz; O''nun sözü içimizde olmaz.'),
(2013325,68,62,2,1,'Yavrularım, bunları size günah işlemeyesiniz diye yazıyorum. Ama içimizden biri günah işlerse, adil olan İsa Mesih bizi Babanın önünde savunur.'),
(2013326,68,62,2,2,'O günahlarımızı, yalnız bizim günahlarımızı değil, bütün dünyanın günahlarını da bağışlatan kurbandır.'),
(2013327,68,62,2,3,'Buyruklarını yerine getirirsek, Onu tanıdığımızdan emin olabiliriz.'),
(2013328,68,62,2,4,'‹‹Onu tanıyorum›› deyip de buyruklarını yerine getirmeyen yalancıdır, kendisinde gerçek yoktur.'),
(2013329,68,62,2,5,'Ama Onun sözüne uyan kişinin Tanrıya olan sevgisi gerçekten yetkinleşmiştir. Tanrıda olduğumuzu bununla anlarız.'),
(2013330,68,62,2,6,'‹‹Tanrıda yaşıyorum›› diyen, Mesihin yürüdüğü yolda yürümelidir.'),
(2013331,68,62,2,7,'Sevgili kardeşlerim, size yeni bir buyruk değil, başlangıçtan beri kabul ettiğiniz eski buyruğu yazıyorum. Eski buyruk, işitmiş olduğunuz Tanrı sözüdür.'),
(2013332,68,62,2,8,'Yine de size yeni bir buyruk yazıyorum. Bunun gerçek olduğu, Mesihte ve sizde görülüyor. Çünkü karanlık geçiyor, gerçek ışık şimdiden parlıyor.'),
(2013333,68,62,2,9,'Işıkta olduğunu söyleyip de kardeşinden nefret eden hâlâ karanlıktadır.'),
(2013334,68,62,2,10,'Kardeşini seven ışıkta yaşar ve başkasının tökezlemesine neden olmaz.'),
(2013335,68,62,2,11,'Ama kardeşinden nefret eden karanlıktadır, karanlıkta yürür ve nereye gittiğini bilmez. Çünkü karanlık gözlerini kör etmiştir.'),
(2013336,68,62,2,12,'Yavrularım, size yazıyorum, Çünkü Mesihin adı uğruna günahlarınız bağışlandı.'),
(2013337,68,62,2,13,'Babalar, size yazıyorum, Çünkü başlangıçtan beri var Olanı tanıyorsunuz. Gençler, size yazıyorum, Çünkü kötü olanı yendiniz. Çocuklar, size yazdım, Çünkü Babayı tanıyorsunuz.'),
(2013338,68,62,2,14,'Babalar, size yazdım, Çünkü başlangıçtan beri var Olanı tanıyorsunuz. Gençler, size yazdım, Çünkü güçlüsünüz, Tanrının sözü içinizde yaşıyor, Kötü olanı yendiniz.'),
(2013339,68,62,2,15,'Dünyayı da dünyaya ait şeyleri de sevmeyin. Dünyayı sevenin Babaya sevgisi yoktur.'),
(2013340,68,62,2,16,'Çünkü dünyaya ait olan her şey -benliğin tutkuları, gözün tutkuları, maddi yaşamın verdiği gurur- Babadan değil, dünyadandır.'),
(2013341,68,62,2,17,'Dünya da dünyasal tutkular da geçer, ama Tanrının isteğini yerine getiren sonsuza dek yaşar.'),
(2013342,68,62,2,18,'Çocuklar, bu son saattir. Mesih Karşıtının geleceğini duydunuz. Nitekim şimdiden çok sayıda Mesih karşıtı türemiş bulunuyor. Son saat olduğunu bundan biliyoruz.'),
(2013343,68,62,2,19,'Bunlar aramızdan çıktılar, ama bizden değildiler. Bizden olsalardı, bizimle kalırlardı. Ayrılmaları hiçbirinin bizden olmadığını ortaya çıkardı.'),
(2013344,68,62,2,20,'Sizlerse Kutsal Olan tarafından meshedildiniz; hepiniz bilgilisiniz.'),
(2013345,68,62,2,21,'Gerçeği bilmediğiniz için değil, gerçeği ve hiçbir yalanın gerçekle ilgisi olmadığını bildiğiniz için size yazıyorum.'),
(2013346,68,62,2,22,'İsanın Mesih olduğunu yadsıyan yalancı değilse, kim yalancıdır? Babayı ve Oğulu yadsıyan Mesih karşıtıdır.'),
(2013347,68,62,2,23,'Oğulu yadsıyanda Baba da yoktur; Oğulu açıkça kabul edende Baba da vardır.'),
(2013348,68,62,2,24,'Başlangıçtan beri işittiğiniz söz içinizde yaşasın. Başlangıçtan beri işittiğiniz söz içinizde yaşarsa, siz de Oğulda ve Babada yaşarsınız.'),
(2013349,68,62,2,25,'Mesihin bize vaat ettiği budur, yani sonsuz yaşamdır.'),
(2013350,68,62,2,26,'Bunları sizi saptırmak isteyenlerle ilgili olarak yazıyorum.'),
(2013351,68,62,2,27,'Size gelince, Ondan aldığınız mesh sizde kalır. Kimsenin size bir şey öğretmesine gerek yoktur. Onun size her şeyi öğreten meshi gerçektir, sahte değildir. Size öğrettiği gibi, Mesihte yaşayın.'),
(2013352,68,62,2,28,'Evet, yavrularım, şimdi Mesihte yaşayın ki, O göründüğünde cesaretimiz olsun, geldiğinde Onun önünde utanmayalım.'),
(2013353,68,62,2,29,'O''nun doğru olduğunu bilirseniz, doğru olanı yapan herkesin O''ndan doğduğunu da bilirsiniz.'),
(2013354,68,62,3,1,'Bakın, Baba bizi o kadar çok seviyor ki, bize ‹‹Tanrının çocukları›› deniyor! Gerçekten de öyleyiz. Dünya Babayı tanımadığı için bizi de tanımıyor.'),
(2013355,68,62,3,2,'Sevgili kardeşlerim, daha şimdiden Tanrının çocuklarıyız, ama ne olacağımız henüz bize gösterilmedi. Ancak, Mesih göründüğü zaman Ona benzer olacağımızı biliyoruz. Çünkü Onu olduğu gibi göreceğiz.'),
(2013356,68,62,3,3,'Mesihte bu umuda sahip olan, Mesih pak olduğu gibi kendini pak kılar.'),
(2013357,68,62,3,4,'Günah işleyen, yasaya karşı gelmiş olur. Çünkü günah demek, yasaya karşı gelmek demektir.'),
(2013358,68,62,3,5,'Mesihin, günahları kaldırmak için ortaya çıktığını ve kendisinde günah olmadığını bilirsiniz.'),
(2013359,68,62,3,6,'Mesihte yaşayan, günah işlemez. Günah işleyen Onu ne görmüştür, ne de tanımıştır.'),
(2013360,68,62,3,7,'Yavrularım, kimse sizi aldatmasın. Mesih doğru olduğu gibi, doğru olanı yapan da doğru kişidir.'),
(2013361,68,62,3,8,'Günah işleyen, İblistendir. Çünkü İblis başlangıçtan beri günah işlemektedir. Tanrının Oğlu, İblisin yaptıklarına son vermek için ortaya çıktı.'),
(2013362,68,62,3,9,'Tanrıdan doğmuş olan, günah işlemez. Çünkü Tanrının tohumu onda yaşar. Tanrıdan doğmuş olduğu için günah işleyemez.'),
(2013363,68,62,3,10,'Doğru olanı yapmayan ve kardeşini sevmeyen kişi Tanrıdan değildir. İşte Tanrının çocuklarıyla İblisin çocukları böyle ayırt edilir.'),
(2013364,68,62,3,11,'Başlangıçtan beri işittiğiniz buyruk şudur: Birbirimizi sevelim.'),
(2013365,68,62,3,12,'Şeytana ait olup kardeşini öldüren Kayin gibi olmayalım. Kayin kardeşini neden öldürdü? Kendi yaptıkları kötü, kardeşinin yaptıkları doğru olduğu için öldürdü.'),
(2013366,68,62,3,13,'Kardeşler, dünya sizden nefret ederse şaşmayın.'),
(2013367,68,62,3,14,'Biz kardeşleri sevdiğimiz için ölümden yaşama geçtiğimizi biliyoruz. Sevmeyen ölümde kalır.'),
(2013368,68,62,3,15,'Kardeşinden nefret eden katildir. Hiçbir katilin sonsuz yaşama sahip olmadığını bilirsiniz.'),
(2013369,68,62,3,16,'Sevginin ne olduğunu Mesihin bizim için canını vermesinden anlıyoruz. Bizim de kardeşlerimiz için canımızı vermemiz gerekir.'),
(2013370,68,62,3,17,'Dünya malına sahip olup da kardeşini ihtiyaç içinde gördüğü halde ondan şefkatini esirgeyen kişide Tanrının sevgisi olabilir mi?'),
(2013371,68,62,3,18,'Yavrularım, sözle ve dille değil, eylemle ve içtenlikle sevelim.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013372,68,62,3,19,'Böylelikle gerçeğe ait olduğumuzu bileceğiz ve yüreğimiz bizi ne zaman suçlarsa, Tanrının önünde onu yatıştıracağız. Çünkü Tanrı yüreğimizden daha büyüktür ve her şeyi bilir.'),
(2013373,68,62,3,21,'Sevgili kardeşlerim, yüreğimiz bizi suçlamazsa, Tanrının önünde cesaretimiz olur, Ondan ne dilersek alırız. Çünkü Onun buyruklarını yerine getiriyor, Onu hoşnut eden şeyleri yapıyoruz.'),
(2013374,68,62,3,23,'Onun buyruğu Oğlu İsa Mesihin adına inanmamız ve İsanın buyurduğu gibi birbirimizi sevmemizdir.'),
(2013375,68,62,3,24,'Tanrı''nın buyruklarını yerine getiren Tanrı''da yaşar, Tanrı da o kişide yaşar. İçimizde yaşadığını bize verdiği Ruh sayesinde biliriz.'),
(2013376,68,62,4,1,'Sevgili kardeşlerim, her ruha inanmayın. Tanrıdan olup olmadıklarını anlamak için ruhları sınayın. Çünkü birçok sahte peygamber dünyanın her yanına yayılmış bulunuyor.'),
(2013377,68,62,4,2,'İsa Mesihin beden alıp dünyaya geldiğini kabul eden her ruh Tanrıdandır. Tanrının Ruhunu bununla tanıyacaksınız.'),
(2013378,68,62,4,3,'İsayı kabul etmeyen hiçbir ruh Tanrıdan değildir. Böylesi, Mesih Karşıtının ruhudur. Onun geleceğini duydunuz. Zaten o şimdiden dünyadadır.'),
(2013379,68,62,4,4,'Yavrularım, siz Tanrıdansınız ve sahte peygamberleri yendiniz. Çünkü sizde olan, dünyadakinden üstündür.'),
(2013380,68,62,4,5,'Sahte peygamberler dünyadandır. Bu nedenle söyledikleri sözler de dünyadandır ve dünya onları dinler.'),
(2013381,68,62,4,6,'Bizse Tanrıdanız; Tanrıyı tanıyan bizi dinler, Tanrıdan olmayan dinlemez. Gerçeğin Ruhuyla yalan ruhunu böyle ayırt ederiz.'),
(2013382,68,62,4,7,'Sevgili kardeşlerim, birbirimizi sevelim. Çünkü sevgi Tanrıdandır. Seven herkes Tanrıdan doğmuştur ve Tanrıyı tanır.'),
(2013383,68,62,4,8,'Sevmeyen kişi Tanrıyı tanımaz. Çünkü Tanrı sevgidir.'),
(2013384,68,62,4,9,'Tanrı biricik Oğlu aracılığıyla yaşayalım diye Onu dünyaya gönderdi, böylece bizi sevdiğini gösterdi.'),
(2013385,68,62,4,10,'Tanrıyı biz sevmiş değildik, ama O bizi sevdi ve Oğlunu günahlarımızı bağışlatan kurban olarak dünyaya gönderdi. İşte sevgi budur.'),
(2013386,68,62,4,11,'Sevgili kardeşlerim, Tanrı bizi bu kadar çok sevdiğine göre biz de birbirimizi sevmeye borçluyuz.'),
(2013387,68,62,4,12,'Hiç kimse hiçbir zaman Tanrıyı görmüş değildir. Ama birbirimizi seversek, Tanrı içimizde yaşar ve sevgisi içimizde yetkinleşmiş olur.'),
(2013388,68,62,4,13,'Tanrıda yaşadığımızı ve Onun bizde yaşadığını bize kendi Ruhundan vermiş olmasından anlıyoruz.'),
(2013389,68,62,4,14,'Babanın Oğlunu dünyanın Kurtarıcısı olarak gönderdiğini gördük, şimdi buna tanıklık ediyoruz.'),
(2013390,68,62,4,15,'Kim İsanın Tanrının Oğlu olduğunu açıkça kabul ederse, Tanrı onda yaşar, o da Tanrıda yaşar.'),
(2013391,68,62,4,16,'Tanrının bize olan sevgisini tanıdık ve buna inandık. Tanrı sevgidir. Sevgide yaşayan Tanrıda yaşar, Tanrı da onda yaşar.'),
(2013392,68,62,4,17,'Yargı gününde cesaretimiz olsun diye sevgi böylelikle içimizde yetkin kılınmıştır. Çünkü Mesih nasılsa, biz de bu dünyada öyleyiz.'),
(2013393,68,62,4,18,'Sevgide korku yoktur. Tersine, yetkin sevgi korkuyu siler atar. Çünkü korku işkencedir. Korkan kişi sevgide yetkin kılınmamıştır.'),
(2013394,68,62,4,19,'Bizse seviyoruz, çünkü önce O bizi sevdi.'),
(2013395,68,62,4,20,'‹‹Tanrıyı seviyorum›› deyip de kardeşinden nefret eden yalancıdır. Çünkü gördüğü kardeşini sevmeyen, görmediği Tanrıyı sevemez.'),
(2013396,68,62,4,21,'‹‹Tanrı''yı seven kardeşini de sevsin›› diyen buyruğu Mesih''ten aldık.'),
(2013397,68,62,5,1,'İsanın Mesih olduğuna inanan herkes Tanrıdan doğmuştur. Babayı seven Ondan doğmuş olanı da sever.'),
(2013398,68,62,5,2,'Tanrıyı sevip buyruklarını yerine getirmekle, Tanrının çocuklarını sevdiğimizi anlarız.'),
(2013399,68,62,5,3,'Tanrıyı sevmek Onun buyruklarını yerine getirmek demektir. Onun buyrukları da ağır değildir.'),
(2013400,68,62,5,4,'Çünkü Tanrıdan doğmuş olan herkes dünyayı yener. Bize dünyaya karşı zafer kazandıran imanımızdır.'),
(2013401,68,62,5,5,'İsanın Tanrı Oğlu olduğuna iman edenden başka dünyayı yenen kim?'),
(2013402,68,62,5,6,'Suyla ve kanla gelen İsa Mesihtir. O yalnız suyla değil, suyla ve kanla gelmiştir. Buna tanıklık eden Ruhtur. Çünkü Ruh gerçektir.'),
(2013403,68,62,5,7,'Şöyle ki, tanıklık edenler üçtür: Ruh, su ve kan. Bunların üçü de uyum içindedir.'),
(2013404,68,62,5,9,'İnsanların tanıklığını kabul ediyoruz, oysa Tanrının tanıklığı daha üstündür. Çünkü bu, Tanrının tanıklığıdır, kendi Oğluyla ilgili olarak yaptığı tanıklıktır.'),
(2013405,68,62,5,10,'Tanrının Oğluna inanan, yüreğinde Tanrının tanıklığına sahiptir. Tanrıya inanmayansa Onu yalancı durumuna düşürmüş olur. Çünkü Tanrının Oğluyla ilgili tanıklığına inanmamıştır.'),
(2013406,68,62,5,11,'Tanıklık da şudur: Tanrı bize sonsuz yaşam verdi, bu yaşam Onun Oğlundadır.'),
(2013407,68,62,5,12,'Kendisinde Tanrı Oğlu bulunanda yaşam vardır, kendisinde Tanrı Oğlu bulunmayanda yaşam yoktur.'),
(2013408,68,62,5,13,'Tanrı Oğlunun adına iman eden sizlere, sonsuz yaşama sahip olduğunuzu bilesiniz diye bunları yazdım.'),
(2013409,68,62,5,14,'Tanrının önünde güvenimiz şu ki, Onun isteğine uygun ne dilersek bizi işitir.'),
(2013410,68,62,5,15,'Her ne dilersek bizi işittiğini bildiğimize göre, Ondan dilediklerimizi aldığımızı da biliriz.'),
(2013411,68,62,5,16,'Kardeşinin ölümcül olmayan bir günah işlediğini gören, onun için dua etsin. Duasıyla kardeşine yaşam verecektir. Bu, ölümcül olmayan günah işleyenler için geçerlidir. Ölümcül günah da vardır, bunun için dua etsin demiyorum.'),
(2013412,68,62,5,17,'Her kötülük günahtır, ama ölümcül olmayan günah da vardır.'),
(2013413,68,62,5,18,'Tanrıdan doğmuş olanın günah işlemediğini biliriz. Tanrıdan doğmuş olan İsa Mesih onu korur ve kötü olan ona dokunamaz.'),
(2013414,68,62,5,19,'Biliyoruz ki, biz Tanrıdanız, bütün dünya ise kötü olanın denetimindedir.'),
(2013415,68,62,5,20,'Yine biliyoruz ki, Tanrının Oğlu gelmiş ve gerçek Olanı tanımamız için bize anlama gücü vermiştir. Biz gerçek Olandayız, Onun Oğlu İsa Mesihteyiz. O gerçek Tanrı ve sonsuz yaşamdır.'),
(2013416,68,62,5,21,'Yavrularım, kendinizi putlardan koruyun.'),
(2013417,68,63,1,1,'Ben ihtiyardan, Tanrının seçtiği, gerçekten sevdiğim hanımefendiye ve çocuklarına selamlar! Yalnız ben değil, gerçeği bilenlerin hepsi de sizleri seviyor.'),
(2013418,68,63,1,2,'Çünkü gerçek içimizde yaşıyor ve sonsuza dek bizimle olacak.'),
(2013419,68,63,1,3,'Baba Tanrıdan ve Babanın Oğlu İsa Mesihten gelen lütuf, merhamet ve esenlik de gerçekte ve sevgide bizimle olacaktır.'),
(2013420,68,63,1,4,'Senin çocuklarından bazılarının Babadan aldığımız buyruğa uyarak gerçeğin izinden yürüdüğünü görünce çok sevindim.'),
(2013421,68,63,1,5,'Şimdi sana rica ediyorum, hanımefendi, birbirimizi sevelim. Bu sana yazdığım yeni bir buyruk değil, başlangıçtan beri kabul ettiğimiz buyruktur.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013422,68,63,1,6,'Sevgi Tanrının buyruklarına uygun yaşamamız demektir. Başlangıçtan beri işittiğiniz gibi, Onun buyruğu sevgi yolunda yürümenizdir.'),
(2013423,68,63,1,7,'Ne var ki, İsa Mesihin beden alıp geldiğini kabul etmeyen birçok aldatıcı dünyanın her yanına yayıldı. Aldatıcı, Mesih karşıtı olan bunlardır.'),
(2013424,68,63,1,8,'Başardıklarınızı yitirmemek ve ödülünüzü eksiksiz almak için kendinize dikkat edin.'),
(2013425,68,63,1,9,'Haddini aşıp Mesihin öğretisine bağlı kalmayan hiç kimsede Tanrı yoktur. Bu öğretiye bağlı kalanda ise hem Baba, hem de Oğul vardır.'),
(2013426,68,63,1,10,'Size gelip de bu öğretiyi getirmeyeni evinize almayın, ona selam bile vermeyin.'),
(2013427,68,63,1,11,'Çünkü böyle birine selam veren, kötü işlerine ortak olur.'),
(2013428,68,63,1,12,'Size yazacak çok şeyim var, ama bunları kâğıtla, mürekkeple iletmek istemedim. Sevincimiz tam olsun diye yanınıza gelmek ve sizinle yüz yüze konuşmak umudundayım.'),
(2013429,68,63,1,13,'Tanrı''nın seçtiği kızkardeşinin çocukları sana selam ederler.'),
(2013430,68,64,1,1,'Ben ihtiyardan, gerçekten sevdiğim sevgili Gayusa selam!'),
(2013431,68,64,1,2,'Sevgili kardeşim, canın gönenç içinde olduğu gibi, her bakımdan sağlıklı ve gönenç içinde olman için dua ediyorum.'),
(2013432,68,64,1,3,'Bazı kardeşler gelip senin gerçeğe bağlı kaldığına, gerçeğin izinden yürüdüğüne tanıklık edince çok sevindim.'),
(2013433,68,64,1,4,'Benim için, çocuklarımın gerçeğin izinden yürüdüklerini duymaktan daha büyük bir sevinç olamaz!'),
(2013434,68,64,1,5,'Sevgili kardeşim, sana yabancı oldukları halde, kardeşler için yaptığın her şeyi içten bir bağlılıkla yapıyorsun.'),
(2013435,68,64,1,6,'Onlar kilise önünde sevgine tanıklık ettiler. Onları Tanrıya yaraşır biçimde yardımlarınla birlikte uğurlarsan iyi edersin.'),
(2013436,68,64,1,7,'Çünkü inanmayanlardan hiçbir yardım almadan, Mesihin adı uğruna yola çıktılar.'),
(2013437,68,64,1,8,'Bu nedenle, gerçek uğruna emektaşlar olmak için böylelerini desteklemeliyiz.'),
(2013438,68,64,1,9,'Kiliseye bazı şeyler yazdım, ama aralarında en üstün olma sevdasında olan Diotrefis bizi kabul etmiyor.'),
(2013439,68,64,1,10,'Bunun için, eğer gelirsem, bize yönelttiği haksız suçlamalarla yaptığı kötülükleri anımsatacağım. Bununla yetinmeyerek kardeşleri de kabul etmiyor, kabul etmek isteyenlere de engel olup onları kiliseden dışarı atıyor.'),
(2013440,68,64,1,11,'Sevgili kardeşim, kötüyü değil, iyiyi örnek al. İyilik yapan kişi Tanrıdandır. Kötülük yapansa Tanrıyı görmemiştir.'),
(2013441,68,64,1,12,'Herkesle birlikte gerçeğin kendisi, Dimitriosun değerli biri olduğuna tanıklık ediyor. Biz de tanıklık ederiz. Tanıklığımızın doğru olduğunu biliyorsun.'),
(2013442,68,64,1,13,'Sana yazacak çok şeyim var, ama mürekkeple, kalemle yazmak istemiyorum.'),
(2013443,68,64,1,14,'Yakında seni görmek umudundayım, o zaman yüz yüze konuşuruz. Esen kal! Arkadaşlar sana selam ederler. Sen de oradaki arkadaşlara adlı adınca selam söyle.'),
(2013444,68,65,1,1,'İsa Mesihin kulu, Yakupun kardeşi ben Yahudadan, Baba Tanrı tarafından sevilip İsa Mesih için korunmuş olan çağrılmışlara selam!'),
(2013445,68,65,1,2,'Merhamet, esenlik ve sevgi artan ölçüde sizin olsun.'),
(2013446,68,65,1,3,'Sevgili kardeşlerim, size ortak kurtuluşumuzla ilgili yazmaya çok gayret ettim. Bu arada sizi kutsallara ilk ve son kez emanet edilen iman uğrunda mücadeleye özendirmek için yazma gereğini duydum.'),
(2013447,68,65,1,4,'Çünkü Tanrımızın lütfunu sefahate araç eden, tek Efendimiz ve Rabbimiz İsa Mesihi yadsıyan bazı tanrısızlar gizlice aranıza sızdılar. Onların yargılanacakları çoktan beri yazılmıştır.'),
(2013448,68,65,1,5,'Bütün bunları bildiğiniz halde, size anımsatmak isterim ki, ilk ve son kez halkı Mısırdan kurtaran Rab iman etmeyenleri daha sonra yok etti.'),
(2013449,68,65,1,6,'Yetkilerinin sınırı içinde kalmayıp kendilerine ayrılan yeri terk etmiş olan melekleri, büyük yargı günü için çözülmez bağlarla bağlayarak karanlığa hapsetti.'),
(2013450,68,65,1,7,'Sodom, Gomora ve çevrelerindeki kentler de benzer biçimde kendilerini fuhuş ve sapıklığa teslim ettiler. Sonsuza dek ateşte yanma cezasını çeken bu kentler ders alınacak birer örnektir.'),
(2013451,68,65,1,8,'Aranıza sızan bu kişiler de onlar gibi gördükleri düşlere dayanarak öz bedenlerini kirletiyor, Rabbin yetkisini hiçe sayıyor, yüce varlıklara sövüyorlar.'),
(2013452,68,65,1,9,'Oysa Başmelek Mikail bile Musanın cesedi konusunda İblisle çekişip tartışırken, söverek onu yargılamaya kalkışmadı. Ancak, ‹‹Seni Rab azarlasın›› dedi.'),
(2013453,68,65,1,10,'Ama bu kişiler anlamadıkları her şeye sövüyorlar. Öte yandan, akıldan yoksun hayvanlar gibi içgüdüleriyle anladıkları ne varsa, onları yıkıma götürüyor.'),
(2013454,68,65,1,11,'Vay onların haline! Çünkü Kayinin yolundan gittiler. Kazanç için kendilerini Balamınkine benzer bir yanılgıya kaptırdılar. Korahınkine benzer bir isyanda mahvoldular.'),
(2013455,68,65,1,12,'Sevgi şölenlerinizde sizinle birlikte pervasızca yiyip içen bu kişiler birer kara lekedir. Yalnız kendilerini besleyen çobanlardır. Rüzgarın sürüklediği yağmursuz bulutlara, iki kez ölmüş, kökünden sökülmüş, sonbaharın meyvesiz ağaçlarına benzerler.'),
(2013456,68,65,1,13,'Köpüğünü savuran denizin azgın dalgaları gibi ayıplarını çevreye savururlar. Serseri yıldızlar gibidirler. Onları sonsuza dek sürecek koyu karanlık bekliyor.'),
(2013457,68,65,1,14,'Ademden sonraki altıncı kuşaktan olan Hanok, bu adamlara ilişkin şu peygamberlikte bulundu: ‹‹İşte Rab herkesi yargılamak üzere on binlerce kutsalıyla geliyor. Tanrı yoluna aykırı, tanrısızca yapılan bütün işlerden ve tanrısız günahkârların kendisine karşı söylediği bütün ağır sözlerden ötürü Rab, bütün insanlara suçluluklarını gösterecektir.››'),
(2013458,68,65,1,16,'Bunlar hep yakınıp söylenir, kendi tutkularının peşinden giderler. Ağızlarından kurumlu sözler çıkar, kendi çıkarları için başkalarını pohpohlarlar.'),
(2013459,68,65,1,17,'Ama siz, sevgili kardeşlerim, Rabbimiz İsa Mesihin elçileri tarafından önceden söylenen sözleri anımsayın.'),
(2013460,68,65,1,18,'Size demişlerdi ki, ‹‹Dünyanın son günlerinde alay edenler, tanrısızlığa yönelip kendi tutkularına göre yaşayanlar olacaktır.››'),
(2013461,68,65,1,19,'Bunlar bölücü, insan doğasıyla sınırlı, Kutsal Ruhtan yoksun kişilerdir.'),
(2013462,68,65,1,20,'Ama siz, sevgili kardeşlerim, kendinizi tümden kutsal olan imanınızın temeli üzerinde geliştirin. Kutsal Ruhun yönetiminde dua edin.'),
(2013463,68,65,1,21,'Rabbimiz İsa Mesihin sizi sonsuz yaşama kavuşturacak olan merhametini beklerken kendinizi Tanrının sevgisinde koruyun.'),
(2013464,68,65,1,22,'Kimi kararsızlara merhamet edin.'),
(2013465,68,65,1,23,'Kimini ateşten çekip kurtarın. Kimine de korkuyla merhamet edin. Ama günahlı bir bedenin lekelediği giysiden bile tiksinin.'),
(2013466,68,65,1,24,'Kurtarıcımız tek Tanrı, sizi düşmekten alıkoyacak, büyük sevinç içinde lekesiz olarak yüce huzuruna çıkaracak güçtedir. Yücelik, ululuk, güç ve yetki Rabbimiz İsa Mesih aracılığıyla bütün çağlardan önce, şimdi ve bütün çağlar boyunca Tanrı''nın olsun! Amin.'),
(2013467,68,66,1,1,'İsa Mesihin vahyidir. Tanrı yakın zamanda olması gereken olayları kullarına göstermesi için Ona bu vahyi verdi. O da gönderdiği meleği aracılığıyla bunu kulu Yuhannaya iletti.'),
(2013468,68,66,1,2,'Yuhanna, Tanrının sözüne ve İsa Mesihin tanıklığına -gördüğü her şeye- tanıklık etmektedir.'),
(2013469,68,66,1,3,'Bu peygamberlik sözlerini okuyana, burada yazılanları dinleyip yerine getirene ne mutlu! Çünkü beklenen zaman yakındır.'),
(2013470,68,66,1,4,'Ben Yuhannadan, Asya İlindeki yedi kiliseye selam! Var olan, var olmuş ve gelecek olandan, Onun tahtının önünde bulunan yedi ruhtan ve ölüler arasından ilk doğan, dünya krallarına egemen olan güvenilir tanık İsa Mesihten sizlere lütuf ve esenlik olsun. Yücelik ve güç sonsuzlara dek, bizi seven, kanıyla bizi günahlarımızdan özgür kılmış ve bizi bir krallık haline getirip Babası Tanrının hizmetinde kâhinler yapmış olan Mesihin olsun! Amin.'),
(2013471,68,66,1,7,'İşte bulutlarla geliyor! Her göz Onu görecek, Onun bedenini deşmiş olanlar bile. Onun için dövünecek yeryüzünün bütün halkları. Evet, böyle olacak! Amin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013472,68,66,1,8,'Var olan, var olmuş ve gelecek olan, Her Şeye Gücü Yeten Rab Tanrı, ‹‹Alfa ve Omega Benim›› diyor.'),
(2013473,68,66,1,9,'İsaya ait biri olarak sıkıntıda, tanrısal egemenlikte ve sabırda ortağınız ve kardeşiniz olan ben Yuhanna, Tanrının sözü ve İsaya tanıklık uğruna Patmos denilen adada bulunuyordum.'),
(2013474,68,66,1,10,'Rabbin gününde Ruhun etkisinde kalarak arkamda borazan sesine benzer yüksek bir ses işittim.'),
(2013475,68,66,1,11,'Ses, ‹‹Gördüklerini kitaba yaz ve yedi kiliseye, yani Efes, İzmir, Bergama, Tiyatira, Sart, Filadelfya ve Laodikyaya gönder›› dedi.'),
(2013476,68,66,1,12,'Bana sesleneni görmek için arkama döndüm. Döndüğümde yedi altın kandillik ve bunların ortasında, giysileri ayağına kadar uzanan, göğsüne altın kuşak sarınmış, insanoğluna benzer birini gördüm.'),
(2013477,68,66,1,14,'Başı, saçı ak yapağı gibi beyaz, kar gibi bembeyazdı. Gözleri alev alev yanan ateşti sanki.'),
(2013478,68,66,1,15,'Ayakları, ocakta kor haline gelmiş parlak tunca benziyordu. Sesi, gürül gürül akan suların sesi gibiydi.'),
(2013479,68,66,1,16,'Sağ elinde yedi yıldız vardı. Ağzından iki ağızlı keskin bir kılıç uzanıyordu. Yüzü bütün gücüyle parlayan güneş gibiydi.'),
(2013480,68,66,1,17,'Onu görünce, ölü gibi ayaklarının dibine yığıldım. O ise sağ elini üzerime koyup şöyle dedi: ‹‹Korkma! İlk ve son Benim.'),
(2013481,68,66,1,18,'Diri Olan Benim. Ölmüştüm, ama işte sonsuzluklar boyunca diriyim. Ölümün ve ölüler diyarının anahtarları bendedir.'),
(2013482,68,66,1,19,'Bunun için gördüklerini, şimdi olanları ve bundan sonra olacakları yaz.'),
(2013483,68,66,1,20,'Sağ elimde gördüğün yedi yıldızla yedi altın kandilliğin sırrına gelince, yedi yıldız yedi kilisenin melekleri, yedi kandillikse yedi kilisedir.››'),
(2013484,68,66,2,1,'‹‹Efesteki kilisenin meleğine yaz. Yedi yıldızı sağ elinde tutan, yedi altın kandilliğin ortasında yürüyen şöyle diyor:'),
(2013485,68,66,2,2,'‹Yaptıklarını, çalışkanlığını, sabrını biliyorum. Kötü kişilere katlanamadığını da biliyorum. Elçi olmadıkları halde kendilerini elçi diye tanıtanları sınadın ve onları yalancı buldun.'),
(2013486,68,66,2,3,'Evet, sabırlısın, adım uğruna acılara dayandın ve yılmadın.'),
(2013487,68,66,2,4,'Ne var ki, bir konuda sana karşıyım: Başlangıçtaki sevginden uzaklaştın.'),
(2013488,68,66,2,5,'Bunun için, nereden düştüğünü anımsa! Tövbe et ve başlangıçta yaptıklarını sürdür. Tövbe etmezsen, gelip kandilliğini yerinden kaldırırım.'),
(2013489,68,66,2,6,'Yine de olumlu bir yanın var: Nikolas yanlılarının yaptıklarından nefret ediyorsun; ben de nefret ederim.'),
(2013490,68,66,2,7,'Kulağı olan, Ruhun kiliselere ne dediğini işitsin. Galip gelene Tanrının cennetinde bulunan yaşam ağacından yeme hakkını vereceğim.› ››'),
(2013491,68,66,2,8,'‹‹İzmirdeki kilisenin meleğine yaz. Ölmüş ve yaşama dönmüş, ilk ve son olan şöyle diyor:'),
(2013492,68,66,2,9,'‹Sıkıntılarını, yoksulluğunu biliyorum. Oysa zenginsin! Yahudi olduklarını söyleyen, ama Yahudi değil de Şeytanın havrası durumunda olanların iftiralarını biliyorum.'),
(2013493,68,66,2,10,'Çekmek üzere olduğun sıkıntılardan korkma! Bak, denenesiniz diye İblis içinizden bazılarını yakında zindana atacak. On gün sıkıntı çekeceksiniz. Ölüm pahasına da olsa sadık kal, sana yaşam tacını vereceğim.'),
(2013494,68,66,2,11,'Kulağı olan, Ruhun kiliselere ne dediğini işitsin. Galip gelen, ikinci ölümden hiçbir zarar görmeyecek.› ››'),
(2013495,68,66,2,12,'‹‹Bergamadaki kilisenin meleğine yaz. İki ağızlı keskin kılıca sahip olan şöyle diyor:'),
(2013496,68,66,2,13,'‹Nerede yaşadığını biliyorum; Şeytanın tahtı oradadır. Yine de adıma sımsıkı bağlısın. Aranızda, Şeytanın yaşadığı yerde öldürülen sadık tanığım Antipanın günlerinde bile bana olan imanını yadsımadın.'),
(2013497,68,66,2,14,'Ne var ki, birkaç konuda sana karşıyım: Aranızda Balamın öğretisine bağlı olanlar var. Putlara sunulan kurbanların etini yemeleri, fuhuş yapmaları için İsrailoğullarını ayartmayı Balaka öğreten Balamdı.'),
(2013498,68,66,2,15,'Bunun gibi, sizin aranızda da Nikolas yanlılarının öğretisine bağlı olanlar var.'),
(2013499,68,66,2,16,'Bunun için tövbe et! Yoksa yanına tez gelir, ağzımdaki kılıçla onlara karşı savaşırım.'),
(2013500,68,66,2,17,'Kulağı olan, Ruhun kiliselere ne dediğini işitsin. Galip gelene saklı mandan vereceğim. Ayrıca, ona beyaz bir taş ve bu taşın üzerinde yazılı olan yeni bir ad, alandan başka kimsenin bilmediği bir ad vereceğim.› ››'),
(2013501,68,66,2,18,'‹‹Tiyatiradaki kilisenin meleğine yaz. Gözleri alev alev yanan ateşe, ayakları parlak tunca benzeyen Tanrının Oğlu şöyle diyor:'),
(2013502,68,66,2,19,'‹Yaptıklarını, sevgini, imanını, hizmetini, sabrını biliyorum. Son yaptıklarının ilk yaptıklarını aştığını da biliyorum.'),
(2013503,68,66,2,20,'Ne var ki, bir konuda sana karşıyım: Kendini peygamber diye tanıtan İzebel adındaki kadını hoşgörüyle karşılıyorsun. Bu kadın öğretisiyle kullarımı saptırıp fuhuş yapmaya, putlara sunulan kurbanların etini yemeye yöneltiyor.'),
(2013504,68,66,2,21,'Tövbe etmesi için ona bir süre tanıdım, ama fuhuş yapmaktan tövbe etmek istemiyor.'),
(2013505,68,66,2,22,'Bak, onu yatağa düşüreceğim; onun yaptıklarından tövbe etmezlerse, onunla zina edenleri de büyük sıkıntıların içine atacağım.'),
(2013506,68,66,2,23,'Onun çocuklarını salgın hastalıkla öldüreceğim. O zaman bütün kiliseler, gönülleri ve yürekleri denetleyenin ben olduğumu bilecekler. Her birinize yaptıklarınızın karşılığını vereceğim.'),
(2013507,68,66,2,24,'‹‹ ‹Ama size, yani Tiyatirada bulunan öbürlerine, bu öğretiyi benimsememiş, Şeytanın sözde derin sırlarını öğrenmemiş olanların hepsine şunu söylüyorum: Ben gelinceye dek sizde olana sımsıkı sarılın. Üzerinize bundan başka bir yük koymuyorum.'),
(2013508,68,66,2,26,'Ben Babamdan nasıl yetki aldımsa, galip gelene, yaptığım işleri sonuna dek sürdürene ulusların üzerinde yetki vereceğim. Demir çomakla güdecek onları, Çömlek gibi kırıp parçalayacaktır.'),
(2013509,68,66,2,29,'Kulağı olan, Ruh''un kiliselere ne dediğini işitsin.› ››'),
(2013510,68,66,3,1,'‹‹Sarttaki kilisenin meleğine yaz. Tanrının yedi ruhuna ve yedi yıldıza sahip olan şöyle diyor: ‹Yaptıklarını biliyorum. Yaşıyorsun diye ad yapmışsın, ama ölüsün.'),
(2013511,68,66,3,2,'Uyan! Geriye kalan ve ölmek üzere olan ne varsa güçlendir. Çünkü yaptıklarının Tanrımın önünde tamamlanmamış olduğunu gördüm.'),
(2013512,68,66,3,3,'Bu nedenle neler aldığını, neler işittiğini anımsa. Bunları yerine getir, tövbe et! Eğer uyanmazsan, hırsız gibi geleceğim. Hangi saatte geleceğimi hiç bilemeyeceksin.'),
(2013513,68,66,3,4,'Ama Sartta, aranızda giysilerini lekelememiş birkaç kişi var ki, beyazlar içinde benimle birlikte yürüyecekler. Çünkü buna layıktırlar.'),
(2013514,68,66,3,5,'Galip gelen böylece beyaz giysiler giyecek. Onun adını yaşam kitabından hiç silmeyeceğim. Babamın ve meleklerinin önünde o kişinin adını açıkça anacağım.'),
(2013515,68,66,3,6,'Kulağı olan, Ruhun kiliselere ne dediğini işitsin.› ››'),
(2013516,68,66,3,7,'‹‹Filadelfyadaki kilisenin meleğine yaz. Kutsal ve gerçek olan, Davutun anahtarına sahip olan, açtığını kimsenin kapayamadığı, kapadığını kimsenin açamadığı kişi şöyle diyor:'),
(2013517,68,66,3,8,'‹Yaptıklarını biliyorum. İşte önüne kimsenin kapayamayacağı açık bir kapı koydum. Gücünün az olduğunu biliyorum; yine de sözüme uydun, adımı yadsımadın.'),
(2013518,68,66,3,9,'Bak, Şeytanın havrasından olanları, Yahudi olmadıkları halde Yahudi olduklarını ileri süren yalancıları öyle edeceğim ki, gelip ayaklarına kapanacak, benim seni sevdiğimi anlayacaklar.'),
(2013519,68,66,3,10,'Sözüme uyarak sabırla dayandın. Ben de yeryüzünde yaşayanları denemek için bütün dünyanın üzerine gelecek olan denenme saatinden seni esirgeyeceğim.'),
(2013520,68,66,3,11,'Tez geliyorum. Tacını kimse elinden almasın diye sahip olduğuna sımsıkı sarıl.'),
(2013521,68,66,3,12,'Galip geleni Tanrımın Tapınağında sütun yapacağım. Böyle biri artık oradan hiç ayrılmayacak. Onun üzerine Tanrımın adını, Tanrıma ait kentin -gökten Tanrımın yanından inen yeni Yeruşalimin- adını ve benim yeni adımı yazacağım.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013522,68,66,3,13,'Kulağı olan, Ruhun kiliselere ne dediğini işitsin.› ››'),
(2013523,68,66,3,14,'‹‹Laodikyadaki kilisenin meleğine yaz. Amin, sadık ve gerçek tanık, Tanrı yaratılışının kaynağı şöyle diyor:'),
(2013524,68,66,3,15,'‹Yaptıklarını biliyorum. Ne soğuksun, ne sıcak. Keşke ya soğuk ya sıcak olsaydın!'),
(2013525,68,66,3,16,'Oysa ne sıcak ne soğuksun, ılıksın. Bu yüzden seni ağzımdan kusacağım.'),
(2013526,68,66,3,17,'Zenginim, zenginleştim, hiçbir şeye gereksinmem yok diyorsun; ama zavallı, acınacak durumda, yoksul, kör ve çıplak olduğunu bilmiyorsun.'),
(2013527,68,66,3,18,'Zengin olmak için benden ateşte arıtılmış altın, giyinip çıplaklığının ayıbını örtmek için beyaz giysiler, görmek için gözlerine sürmek üzere merhem satın almanı salık veriyorum.'),
(2013528,68,66,3,19,'Ben sevdiklerimi azarlayıp terbiye ederim. Onun için gayrete gel, tövbe et.'),
(2013529,68,66,3,20,'İşte kapıda durmuş, kapıyı çalıyorum. Biri sesimi işitir ve kapıyı açarsa, onun yanına gireceğim; ben onunla, o da benimle, birlikte yemek yiyeceğiz.'),
(2013530,68,66,3,21,'Ben nasıl galip gelerek Babamla birlikte Babamın tahtına oturdumsa, galip gelene de benimle birlikte tahtıma oturma hakkını vereceğim.'),
(2013531,68,66,3,22,'Kulağı olan, Ruh''un kiliselere ne dediğini işitsin.› ››'),
(2013532,68,66,4,1,'Bundan sonra gökte açık duran bir kapı gördüm. Benimle konuştuğunu işittiğim, borazan sesine benzeyen ilk ses şöyle dedi: ‹‹Buraya çık! Bundan sonra olması gereken olayları sana göstereyim.››'),
(2013533,68,66,4,2,'O anda Ruhun etkisinde kalarak gökte bir taht ve tahtta oturan birini gördüm.'),
(2013534,68,66,4,3,'Tahtta oturanın, yeşim ve kırmızı akik taşına benzer bir görünüşü vardı. Zümrüdü andıran bir gökkuşağı tahtı çevreliyordu.'),
(2013535,68,66,4,4,'Tahtın çevresinde yirmi dört ayrı taht vardı. Bu tahtlara başlarında altın taçlar olan, beyaz giysilere bürünmüş yirmi dört ihtiyar oturmuştu.'),
(2013536,68,66,4,5,'Tahttan şimşekler çakıyor, uğultular, gök gürlemeleri işitiliyordu. Tahtın önünde alev alev yanan yedi meşale vardı. Bunlar Tanrının yedi ruhudur.'),
(2013537,68,66,4,6,'Tahtın önünde billur gibi, sanki camdan bir deniz vardı. Tahtın ortasında ve çevresinde, önü ve arkası gözlerle kaplı dört yaratık duruyordu.'),
(2013538,68,66,4,7,'Birinci yaratık aslana, ikincisi danaya benziyordu. Üçüncü yaratığın yüzü insan yüzü gibiydi. Dördüncü yaratık uçan bir kartalı andırıyordu.'),
(2013539,68,66,4,8,'Dört yaratığın her birinin altışar kanadı vardı. Yaratıkların her yanı, kanatlarının alt tarafı bile gözlerle kaplıydı. Gece gündüz durup dinlenmeden şöyle diyorlar: ‹‹Kutsal, kutsal, kutsaldır, Her Şeye Gücü Yeten Rab Tanrı, Var olmuş, var olan ve gelecek olan.››'),
(2013540,68,66,4,9,'Yaratıklar tahtta oturanı, sonsuzluklar boyunca yaşayanı yüceltip ona saygı ve şükran sundukça, yirmi dört ihtiyar tahtta oturanın, sonsuzluklar boyunca yaşayanın önünde yere kapanarak O''na tapınıyorlar. Taçlarını tahtın önüne koyarak şöyle diyorlar: ‹‹Rabbimiz ve Tanrımız! Yüceliği, saygıyı, gücü almaya layıksın. Çünkü her şeyi sen yarattın; Hepsi senin isteğinle yaratılıp var oldu.››'),
(2013541,68,66,5,1,'Tahtta oturanın sağ elinde iki yanı da yazılı, yedi mühürle mühürlenmiş bir tomar gördüm.'),
(2013542,68,66,5,2,'Yüksek sesle, ‹‹Tomarı açmaya, mühürlerini çözmeye kim layıktır?›› diye seslenen güçlü bir melek de gördüm.'),
(2013543,68,66,5,3,'Ama ne gökte, ne yeryüzünde, ne de yer altında tomarı açıp içine bakabilecek kimse yoktu.'),
(2013544,68,66,5,4,'Acı acı ağlamaya başladım. Çünkü tomarı açıp içine bakmaya layık kimse bulunamadı.'),
(2013545,68,66,5,5,'Bunun üzerine ihtiyarlardan biri bana, ‹‹Ağlama!›› dedi. ‹‹İşte, Yahuda oymağından gelen Aslan, Davutun Kökü galip geldi. Tomarı ve yedi mührünü O açacak.››'),
(2013546,68,66,5,6,'Tahtın, dört yaratığın ve ihtiyarların ortasında, boğazlanmış gibi duran bir Kuzu gördüm. Yedi boynuzu, yedi gözü vardı. Bunlar Tanrının bütün dünyaya gönderilmiş yedi ruhudur.'),
(2013547,68,66,5,7,'Kuzu gelip tahtta oturanın sağ elinden tomarı aldı.'),
(2013548,68,66,5,8,'Tomarı alınca, dört yaratıkla yirmi dört ihtiyar Onun önünde yere kapandılar. Her birinin elinde birer lir ve kutsalların duaları olan buhur dolu altın taslar vardı.'),
(2013549,68,66,5,9,'Yeni bir ezgi söylüyorlardı: ‹‹Tomarı almaya, Mühürlerini açmaya layıksın! Çünkü boğazlandın Ve kanınla her oymaktan, her dilden, Her halktan, her ulustan İnsanları Tanrıya satın aldın.'),
(2013550,68,66,5,10,'Onları Tanrımızın hizmetinde Bir krallık haline getirdin, Kâhinler yaptın. Dünya üzerinde egemenlik sürecekler.››'),
(2013551,68,66,5,11,'Sonra tahtın, yaratıkların ve ihtiyarların çevresinde çok sayıda melek gördüm, seslerini işittim. Sayıları binlerce binler, on binlerce on binlerdi.'),
(2013552,68,66,5,12,'Yüksek sesle şöyle diyorlardı: ‹‹Boğazlanmış Kuzu Gücü, zenginliği, bilgeliği, kudreti, Saygıyı, yüceliği, övgüyü Almaya layıktır.››'),
(2013553,68,66,5,13,'Ardından gökte, yeryüzünde, yer altında ve denizlerdeki bütün yaratıkların, bunlardaki bütün varlıkların şöyle dediğini işittim: ‹‹Övgü, saygı, yücelik ve güç sonsuzlara dek Tahtta oturanın ve Kuzunun olsun!››'),
(2013554,68,66,5,14,'Dört yaratık, ‹‹Amin›› dediler. İhtiyarlar da yere kapanıp tapındılar.'),
(2013555,68,66,6,1,'Sonra Kuzunun yedi mühürden birini açtığını gördüm. O anda dört yaratıktan birinin, gök gürültüsüne benzer bir sesle, ‹‹Gel!›› dediğini işittim.'),
(2013556,68,66,6,2,'Bakınca beyaz bir at gördüm. Binicisinin yayı vardı. Kendisine bir taç verildi ve galip gelen biri olarak zafer kazanmaya çıktı.'),
(2013557,68,66,6,3,'Kuzu ikinci mührü açınca, ikinci yaratığın ‹‹Gel!›› dediğini işittim.'),
(2013558,68,66,6,4,'O zaman kızıl renkte başka bir at çıktı ortaya. Binicisine dünyadan barışı kaldırma yetkisi verildi. Bunun sonucu olarak insanlar birbirlerini boğazlayacaklar. Atlıya ayrıca büyük bir kılıç verildi.'),
(2013559,68,66,6,5,'Kuzu üçüncü mührü açınca, üçüncü yaratığın ‹‹Gel!›› dediğini işittim. Bakınca siyah bir at gördüm. Binicisinin elinde bir terazi vardı.'),
(2013560,68,66,6,6,'Dört yaratığın ortasında sanki bir sesin şöyle dediğini işittim: ‹‹Bir ölçek buğday bir dinara, üç ölçek arpa bir dinara. Ama zeytinyağına, şaraba zarar verme!››'),
(2013561,68,66,6,7,'Kuzu dördüncü mührü açınca, ‹‹Gel!›› diyen dördüncü yaratığın sesini işittim.'),
(2013562,68,66,6,8,'Bakınca soluk renkli bir at gördüm. Binicisinin adı Ölümdü. Ölüler diyarı onun ardınca geliyordu. Bunlara kılıçla, kıtlıkla, salgın hastalıkla, yeryüzünün yabanıl hayvanlarıyla ölüm saçmak için yeryüzünün dörtte biri üzerinde yetki verildi.'),
(2013563,68,66,6,9,'Kuzu beşinci mührü açınca, sunağın altında, Tanrının sözü ve sürdürdükleri tanıklık nedeniyle öldürülenlerin canlarını gördüm.'),
(2013564,68,66,6,10,'Yüksek sesle feryat ederek şöyle diyorlardı: ‹‹Kutsal ve gerçek olan Efendimiz! Yeryüzünde yaşayanları yargılayıp onlardan kanımızın öcünü almak için daha ne kadar bekleyeceksin?››'),
(2013565,68,66,6,11,'Onların her birine beyaz birer kaftan verildi. Kendileri gibi öldürülecek olan öbür Tanrı kullarının ve kardeşlerinin sayısı tamamlanıncaya dek kısa bir süre daha beklemeleri istendi.'),
(2013566,68,66,6,12,'Kuzu altıncı mührü açınca, büyük bir deprem olduğunu gördüm. Güneş keçi kılından yapılmış siyah bir çul gibi karardı. Ay baştan aşağı kan rengine döndü.'),
(2013567,68,66,6,13,'İncir ağacı, güçlü bir rüzgarla sarsıldığında nasıl ham incirlerini dökerse, gökteki yıldızlar da öylece yeryüzüne düştü.'),
(2013568,68,66,6,14,'Gökyüzü dürülen bir tomar gibi ortadan kalktı. Her dağ, her ada yerinden sökülüp alındı.'),
(2013569,68,66,6,15,'Dünya kralları, büyükleri, komutanları, zenginleri, güçlüleri, özgürü kölesi herkes mağaralara, dağlardaki kayaların arasına gizlendiler.'),
(2013570,68,66,6,16,'Dağlara, kayalara, ‹‹Üzerimize düşün!›› dediler, ‹‹Tahtta oturanın yüzünden ve Kuzunun gazabından saklayın bizi!'),
(2013571,68,66,6,17,'Çünkü onların gazabının büyük günü geldi. Buna kim dayanabilir?››');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013572,68,66,7,1,'Bundan sonra yeryüzünün dört köşesinde duran dört melek gördüm. Bunlar karaya, denize ya da herhangi bir ağaç üzerine esmesin diye, yeryüzünün dört rüzgarını tutuyorlardı.'),
(2013573,68,66,7,2,'Sonra gündoğusundan yükselen başka bir melek gördüm. Yaşayan Tanrının mührünü taşıyordu. Karaya, denize zarar vermek için yetki verilen dört meleğe yüksek sesle bağırdı:'),
(2013574,68,66,7,3,'‹‹Biz Tanrımızın kullarını alınlarından mühürleyene dek karaya, denize ya da ağaçlara zarar vermeyin!››'),
(2013575,68,66,7,4,'Mühürlenmiş olanların sayısını işittim. İsrailoğullarının bütün oymaklarından 144 000 kişi mühürlenmişti:'),
(2013576,68,66,7,5,'Yahuda oymağından 12 000 kişi mühürlenmişti. Ruben oymağından 12 000, Gad oymağından 12 000,'),
(2013577,68,66,7,6,'Aşer oymağından 12 000, Naftali oymağından 12 000, Manaşşe oymağından 12 000,'),
(2013578,68,66,7,7,'Şimon oymağından 12 000, Levi oymağından 12 000, İssakar oymağından 12 000,'),
(2013579,68,66,7,8,'Zevulun oymağından 12 000, Yusuf oymağından 12 000, Benyamin oymağından 12 000 kişi mühürlenmişti.'),
(2013580,68,66,7,9,'Bundan sonra gördüm ki, her ulustan, her oymaktan, her halktan, her dilden oluşan, kimsenin sayamayacağı kadar büyük bir kalabalık tahtın ve Kuzunun önünde duruyordu. Hepsi de birer beyaz kaftan giymişti, ellerinde hurma dalları vardı.'),
(2013581,68,66,7,10,'Yüksek sesle bağırıyorlardı: ‹‹Kurtarış, tahtta oturan Tanrımıza Ve Kuzuya özgüdür!››'),
(2013582,68,66,7,11,'Bütün melekler tahtın, ihtiyarların ve dört yaratığın çevresinde duruyordu. Tahtın önünde yüzüstü yere kapanıp Tanrıya tapınarak şöyle diyorlardı:'),
(2013583,68,66,7,12,'‹‹Amin! Övgü, yücelik, bilgelik, Şükran, saygı, güç, kudret, Sonsuzlara dek Tanrımızın olsun! Amin!››'),
(2013584,68,66,7,13,'Bu sırada ihtiyarlardan biri bana sordu: ‹‹Beyaz kaftan giymiş olan bu kişiler kim, nereden geldiler?››'),
(2013585,68,66,7,14,'‹‹Sen bunu biliyorsun, efendim›› dedim. Bana dedi ki, ‹‹Bunlar o büyük sıkıntıdan geçip gelenlerdir. Kaftanlarını Kuzunun kanıyla yıkamış, bembeyaz etmişlerdir.'),
(2013586,68,66,7,15,'Bunun için, ‹‹Tanrının tahtı önünde duruyor, Tapınağında gece gündüz Ona tapınıyorlar. Tahtta oturan, çadırını onların üzerine gerecek.'),
(2013587,68,66,7,16,'Artık acıkmayacak, Artık susamayacaklar. Ne güneş ne kavurucu sıcak Çarpacak onları.'),
(2013588,68,66,7,17,'Çünkü tahtın ortasında olan Kuzu onları güdecek Ve yaşam sularının pınarlarına götürecek. Tanrı gözlerinden bütün yaşları silecek.››'),
(2013589,68,66,8,1,'Kuzu yedinci mührü açınca, gökte yarım saat kadar sessizlik oldu.'),
(2013590,68,66,8,2,'Tanrının önünde duran yedi meleği gördüm. Onlara yedi borazan verildi.'),
(2013591,68,66,8,3,'Altın bir buhurdan taşıyan başka bir melek gelip sunağın önünde durdu. Tahtın önündeki altın sunakta bütün kutsalların dualarıyla birlikte sunmak üzere kendisine çok miktarda buhur verildi.'),
(2013592,68,66,8,4,'Kutsalların dualarıyla buhurun dumanı, Tanrının önünde meleğin elinden yükseldi.'),
(2013593,68,66,8,5,'Melek buhurdanı aldı, sunağın ateşiyle doldurup yeryüzüne attı. Gök gürlemeleri, uğultular işitildi, şimşekler çaktı, yer sarsıldı.'),
(2013594,68,66,8,6,'Yedi melek ellerindeki yedi borazanı çalmaya hazırlandı.'),
(2013595,68,66,8,7,'Birinci melek borazanını çaldı. Kanla karışık dolu ve ateş oluştu, yeryüzüne yağdı. Yerin üçte biri, ağaçların üçte biri ve bütün yeşil otlar yandı.'),
(2013596,68,66,8,8,'İkinci melek borazanını çaldı. Alev alev yanan, dağ gibi büyük bir kütle denize atıldı. Denizin üçte biri kana dönüştü.'),
(2013597,68,66,8,9,'Denizdeki yaratıkların üçte biri öldü, gemilerin üçte biri yok oldu.'),
(2013598,68,66,8,10,'Üçüncü melek borazanını çaldı. Gökten meşale gibi yanan büyük bir yıldız ırmakların üçte biri üzerine ve su pınarlarının üzerine düştü.'),
(2013599,68,66,8,11,'Bu yıldızın adı Pelindir. Suların üçte biri pelin gibi acılaştı. Acılaşan sulardan içen birçok insan öldü.'),
(2013600,68,66,8,12,'Dördüncü melek borazanını çaldı. Güneşin üçte biri, ayın üçte biri, yıldızların üçte biri vuruldu. Sonuç olarak ışıklarının üçte biri söndü, gündüzün ve gecenin üçte biri ışıksız kaldı.'),
(2013601,68,66,8,13,'Sonra göğün ortasında uçan bir kartal gördüm. Yüksek sesle şöyle bağırdığını işittim: ‹‹Borazanlarını çalacak olan öbür üç meleğin borazan seslerinden yeryüzünde yaşayanların vay, vay, vay haline!››'),
(2013602,68,66,9,1,'Beşinci melek borazanını çaldı. Gökten yere düşmüş bir yıldız gördüm. Dipsiz derinliklere açılan kuyunun anahtarı ona verildi.'),
(2013603,68,66,9,2,'Dipsiz derinliklerin kuyusunu açınca, kuyudan büyük bir ocağın dumanı gibi bir duman çıktı. Kuyunun dumanından güneş ve hava karardı.'),
(2013604,68,66,9,3,'Dumanın içinden yeryüzüne çekirgeler yağdı. Bunlara yeryüzündeki akreplerin gücüne benzer bir güç verilmişti.'),
(2013605,68,66,9,4,'Çekirgelere yeryüzündeki otlara, herhangi bir bitki ya da ağaca değil de, yalnız alınlarında Tanrının mührü bulunmayan insanlara zarar vermeleri söylendi.'),
(2013606,68,66,9,5,'Bu insanları öldürmelerine değil, beş ay süreyle işkence etmelerine izin verildi. Yaptıkları işkence akrebin insanı soktuğu zaman verdiği acıya benziyordu.'),
(2013607,68,66,9,6,'O günlerde insanlar ölümü arayacak, ama bulamayacaklar. Ölümü özleyecekler, ama ölüm onlardan kaçacak.'),
(2013608,68,66,9,7,'Çekirgelerin görünümü, savaşa hazırlanmış atlara benziyordu. Başlarında altın taçlara benzer başlıklar vardı. Yüzleri insan yüzleri gibiydi.'),
(2013609,68,66,9,8,'Saçları kadın saçına, dişleri aslan dişine benziyordu.'),
(2013610,68,66,9,9,'Demir zırhlara benzer göğüs zırhları vardı. Kanatlarının sesi savaşa koşan çok sayıda atlı arabanın sesine benziyordu.'),
(2013611,68,66,9,10,'Akrebinkine benzer kuyrukları ve iğneleri vardı. Kuyruklarında, insanlara beş ay zarar verecek güce sahiptiler.'),
(2013612,68,66,9,11,'Başlarında kral olarak dipsiz derinliklerin meleği vardı. Bu meleğin İbranice adı Avaddon, Grekçe adıysa Apolyondur.'),
(2013613,68,66,9,12,'Birinci ‹‹vay›› geçti, işte bundan sonra iki ‹‹vay›› daha geliyor.'),
(2013614,68,66,9,13,'Altıncı melek borazanını çaldı. Tanrının önündeki altın sunağın dört boynuzundan gelen bir ses işittim.'),
(2013615,68,66,9,14,'Ses, elinde borazan olan altıncı meleğe, ‹‹Büyük Fırat Irmağının yanında bağlı duran dört meleği çöz›› dedi.'),
(2013616,68,66,9,15,'Tam o saat, o gün, o ay, o yıl için hazır tutulan dört melek, insanların üçte birini öldürmek üzere çözüldü.'),
(2013617,68,66,9,16,'Atlı ordularının sayısı iki yüz milyondu, sayılarını duydum.'),
(2013618,68,66,9,17,'Görümümde atları ve binicilerini gördüm. Ateş, gökyakut ve kükürt renginde göğüs zırhları kuşanmışlardı. Atların başları aslan başına benziyordu. Ağızlarından ateş, duman, kükürt fışkırıyordu.'),
(2013619,68,66,9,18,'İnsanların üçte biri bunların ağzından fışkıran ateş, duman ve kükürtten, bu üç beladan öldü.'),
(2013620,68,66,9,19,'Atların gücü ağızlarında ve kuyruklarındadır. Yılanı andıran kuyruklarının başıyla zarar verirler.'),
(2013621,68,66,9,20,'Geriye kalan insanlar, yani bu belalardan ölmemiş olanlar, kendi elleriyle yaptıkları putlardan dönüp tövbe etmediler. Cinlere ve göremeyen, işitemeyen, yürüyemeyen altın, gümüş, tunç, taş, tahta putlara tapmaktan vazgeçmediler.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013622,68,66,9,21,'Adam öldürmekten, büyü, fuhuş, hırsızlık yapmaktan da tövbe etmediler.'),
(2013623,68,66,10,1,'Sonra gökten inen güçlü başka bir melek gördüm. Buluta sarınmıştı, başının üzerinde gökkuşağı vardı. Yüzü güneşe, ayakları ateşten sütunlara benziyordu.'),
(2013624,68,66,10,2,'Elinde açılmış küçük bir tomar vardı. Sağ ayağını denize, sol ayağını karaya koyarak aslanın kükremesini andıran yüksek sesle bağırdı. O bağırınca, yedi gök gürlemesi dile gelip seslendiler.'),
(2013625,68,66,10,4,'Yedi gök gürlemesi seslendiğinde yazmak üzereydim ki, gökten, ‹‹Yedi gök gürlemesinin söylediklerini mühürle, yazma!›› diyen bir ses işittim.'),
(2013626,68,66,10,5,'Denizle karanın üzerinde durduğunu gördüğüm melek, sağ elini göğe kaldırdı.'),
(2013627,68,66,10,6,'Göğü ve göktekileri, yeri ve yerdekileri, denizi ve denizdekileri yaratanın, sonsuzluklar boyunca yaşayanın hakkı için ant içip dedi ki, ‹‹Artık gecikme olmayacak.'),
(2013628,68,66,10,7,'Yedinci melek borazanını çaldığı zaman, Tanrının sır olan tasarısı tamamlanacak. Nitekim Tanrı bunu, kulları peygamberlere müjdelemişti.››'),
(2013629,68,66,10,8,'Gökten işittiğim ses benimle yine konuşmaya başladı: ‹‹Git, denizle karanın üzerinde duran meleğin elindeki açık tomarı al›› dedi.'),
(2013630,68,66,10,9,'Meleğin yanına gidip küçük tomarı bana vermesini istedim. ‹‹Al, bunu ye!›› dedi. ‹‹Midende bir acılık yapacak, ama ağzına bal gibi tatlı gelecek.››'),
(2013631,68,66,10,10,'Küçük tomarı meleğin elinden alıp yedim, ağzımda bal gibi tatlıydı. Ama yutunca midem acılaştı.'),
(2013632,68,66,10,11,'Sonra bana şöyle dendi: ‹‹Yine birçok halk, ulus, dil ve kralla ilgili olarak peygamberlikte bulunmalısın.››'),
(2013633,68,66,11,1,'Bana değneğe benzer bir ölçü kamışı verilip şöyle dendi: ‹‹Git, Tanrının Tapınağını ve sunağı ölç, orada tapınanları say!'),
(2013634,68,66,11,2,'Tapınağın dış avlusunu bırak, orayı ölçme. Çünkü orası, kutsal kenti kırk iki ay ayaklarıyla çiğneyecek olan uluslara verildi.'),
(2013635,68,66,11,3,'İki tanığıma güç vereceğim; çul giysiler içinde bin iki yüz altmış gün peygamberlik edecekler.››'),
(2013636,68,66,11,4,'Bunlar yeryüzünün Rabbi önünde duran iki zeytin ağacıyla iki kandilliktir.'),
(2013637,68,66,11,5,'Biri onlara zarar vermeye kalkışırsa, ağızlarından ateş fışkıracak ve düşmanlarını yiyip bitirecek. Onlara zarar vermek isteyen herkesin böyle öldürülmesi gerekir.'),
(2013638,68,66,11,6,'Peygamberlik ettikleri sürece yağmur yağmasın diye göğü kapamaya yetkileri vardır. Suları kana dönüştürme ve yeryüzünü, kaç kez isterlerse, her türlü belayla vurma yetkisine sahiptirler.'),
(2013639,68,66,11,7,'Tanıklık görevleri sona erince dipsiz derinliklerden çıkan canavar onlarla savaşacak, onları yenip öldürecek.'),
(2013640,68,66,11,8,'Cesetleri, simgesel olarak Sodom ve Mısır diye adlandırılan büyük kentin anayoluna serilecek. Onların Rabbi de orada çarmıha gerilmişti.'),
(2013641,68,66,11,9,'Her halktan, oymaktan, dilden, ulustan insan üç buçuk gün cesetlerini seyredecek, cesetlerinin mezara konulmasına izin vermeyecekler.'),
(2013642,68,66,11,10,'Yeryüzünde yaşayanlar onların bu durumuna sevinip bayram edecek, birbirlerine armağanlar gönderecekler. Çünkü bu iki peygamber yeryüzünde yaşayanlara çok eziyet etmişti.'),
(2013643,68,66,11,11,'Üç buçuk gün sonra iki peygamber, Tanrıdan gelen yaşam soluğunu alınca ayağa kalktılar. Onları görenler dehşete kapıldı.'),
(2013644,68,66,11,12,'İki peygamber gökten gelen yüksek bir sesin, ‹‹Buraya çıkın!›› dediğini işittiler. Sonra düşmanlarının gözü önünde bir bulut içinde göğe yükseldiler.'),
(2013645,68,66,11,13,'Tam o saatte şiddetli bir deprem oldu, kentin onda biri yıkıldı. Depremde yedi bin kişi can verdi. Geriye kalanlar dehşete kapılıp gökteki Tanrıyı yücelttiler.'),
(2013646,68,66,11,14,'İkinci ‹‹vay›› geçti. İşte, üçüncü ‹‹vay›› tez geliyor.'),
(2013647,68,66,11,15,'Yedinci melek borazanını çaldı. Gökte yüksek sesler duyuldu: ‹‹Dünyanın egemenliği Rabbimizin ve Mesihinin oldu. O sonsuzlara dek egemenlik sürecek.››'),
(2013648,68,66,11,16,'Tanrının önünde tahtlarında oturan yirmi dört ihtiyar yüzüstü yere kapandı. Tanrıya tapınarak şöyle dediler: ‹‹Her Şeye Gücü Yeten, Var olan, var olmuş olan Rab Tanrı! Sana şükrediyoruz. Çünkü büyük gücünü kuşanıp Egemenlik sürmeye başladın.'),
(2013649,68,66,11,18,'Uluslar gazaba gelmişlerdi. Şimdiyse senin gazabın üzerlerine geldi. Ölüleri yargılamak, Kulların olan peygamberleri, kutsalları, Küçük olsun büyük olsun, Senin adından korkanları ödüllendirmek Ve yeryüzünü mahvedenleri mahvetmek zamanı da geldi.››'),
(2013650,68,66,11,19,'Ardından Tanrı''nın gökteki tapınağı açıldı, tapınakta O''nun Antlaşma Sandığı göründü. O anda şimşekler çaktı, uğultular, gök gürlemeleri işitildi. Yer sarsıldı, şiddetli bir dolu fırtınası koptu.'),
(2013651,68,66,12,1,'Gökte olağanüstü bir belirti, güneşe sarınmış bir kadın göründü. Ay ayaklarının altındaydı, başında on iki yıldızdan oluşan bir taç vardı.'),
(2013652,68,66,12,2,'Kadın gebeydi. Doğum sancıları içinde kıvranıyor, feryat ediyordu.'),
(2013653,68,66,12,3,'Ardından gökte başka bir belirti göründü: Yedi başlı, on boynuzlu, kızıl renkli büyük bir ejderhaydı bu. Yedi başında yedi taç vardı.'),
(2013654,68,66,12,4,'Kuyruğuyla gökteki yıldızların üçte birini sürükleyip yeryüzüne attı. Sonra doğum yapmak üzere olan kadının önünde durdu; kadın doğurur doğurmaz ejderha çocuğu yutacaktı.'),
(2013655,68,66,12,5,'Kadın bir oğul, bütün ulusları demir çomakla güdecek bir erkek çocuk doğurdu. Çocuk hemen alınıp Tanrıya, Tanrının tahtına götürüldü.'),
(2013656,68,66,12,6,'Kadınsa çöle kaçtı. Orada bin iki yüz altmış gün beslenmesi için Tanrı tarafından hazırlanmış bir yeri vardı.'),
(2013657,68,66,12,7,'Gökte savaş oldu. Mikaille melekleri ejderhayla savaştılar. Ejderha kendi melekleriyle birlikte karşı koydu, ama gücü yetmedi. Bu yüzden gökteki yerlerini yitirdiler.'),
(2013658,68,66,12,9,'Büyük ejderha -İblis ya da Şeytan denen, bütün dünyayı saptıran o eski yılan- melekleriyle birlikte yeryüzüne atıldı.'),
(2013659,68,66,12,10,'Bundan sonra gökte yüksek bir sesin şöyle dediğini duydum: ‹‹Tanrımızın kurtarışı, gücü, egemenliği Ve Mesihinin yetkisi şimdi gerçekleşti. Çünkü kardeşlerimizin suçlayıcısı, Onları Tanrımızın önünde gece gündüz suçlayan Aşağı atıldı.'),
(2013660,68,66,12,11,'Kardeşlerimiz Kuzunun kanıyla Ve ettikleri tanıklık bildirisiyle Onu yendiler. Ölümü göze alacak kadar Vazgeçmişlerdi can sevgisinden.'),
(2013661,68,66,12,12,'Bunun için, ey gökler ve orada yaşayanlar, Sevinin! Vay halinize, yer ve deniz! Çünkü İblis zamanının az olduğunu bilerek Büyük bir öfkeyle üzerinize indi.››'),
(2013662,68,66,12,13,'Ejderha yeryüzüne atıldığını görünce, erkek çocuğu doğuran kadını kovalamaya başladı.'),
(2013663,68,66,12,14,'Yılanın önünden çöle, üç buçuk yıl besleneceği yere uçup kaçabilmesi için kadına büyük kartal kanatları verildi.'),
(2013664,68,66,12,15,'Yılan ağzından, kadını selle süpürüp götürmek için onun ardından ırmak gibi su akıttı.'),
(2013665,68,66,12,16,'Ama yeryüzü, ağzını açıp ejderhanın ağzından akıttığı ırmağı yutarak kadına yardım etti.'),
(2013666,68,66,12,17,'Bunun üzerine ejderha kadına öfkelendi. Kadının soyundan geriye kalanlarla, Tanrının buyruklarını yerine getirip İsaya tanıklıklarını sürdürenlerle savaşmaya gitti.'),
(2013667,68,66,12,18,'Denizin kıyısında dikilip durdu.'),
(2013668,68,66,13,1,'Sonra on boynuzlu, yedi başlı bir canavarın denizden çıktığını gördüm. Boynuzlarının üzerinde on taç vardı, başlarının üzerinde küfür niteliğinde adlar yazılıydı.'),
(2013669,68,66,13,2,'Gördüğüm canavar parsa benziyordu. Ayakları ayı ayağı, ağzı aslan ağzı gibiydi. Ejderha canavara kendi gücü ve tahtıyla birlikte büyük yetki verdi.'),
(2013670,68,66,13,3,'Canavarın başlarından biri ölümcül bir yara almışa benziyordu. Ne var ki, bu ölümcül yara iyileşmişti. Bütün dünya şaşkınlık içinde canavarın ardından gitti.'),
(2013671,68,66,13,4,'İnsanlar canavara yetki veren ejderhaya taptılar. ‹‹Canavar gibisi var mı? Onunla kim savaşabilir?›› diyerek canavara da taptılar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013672,68,66,13,5,'Canavara, kurumlu sözler söyleyen, küfürler savuran bir ağız ve kırk iki ay süreyle kullanabileceği bir yetki verildi.'),
(2013673,68,66,13,6,'Tanrıya küfretmek, Onun adına ve konutuna, yani gökte yaşayanlara küfretmek için ağzını açtı.'),
(2013674,68,66,13,7,'Kutsallarla savaşıp onları yenmesine izin verildi. Canavar her oymak, her halk, her dil, her ulus üzerinde yetkili kılındı.'),
(2013675,68,66,13,8,'Yeryüzünde yaşayan ve dünya kurulalı beri boğazlanmış Kuzunun yaşam kitabına adı yazılmamış olan herkes ona tapacak.'),
(2013676,68,66,13,9,'Kulağı olan işitsin!'),
(2013677,68,66,13,10,'Tutsak düşecek olan Tutsak düşecek. Kılıçla öldürülecek olan Kılıçla öldürülecek.'),
(2013678,68,66,13,11,'Bundan sonra başka bir canavar gördüm. Yerden çıkan bu canavarın kuzu gibi iki boynuzu vardı, ama ejderha gibi ses çıkarıyordu.'),
(2013679,68,66,13,12,'İlk canavarın bütün yetkisini onun adına kullanıyor, yeryüzünü ve orada yaşayanları ölümcül yarası iyileşen ilk canavara tapmaya zorluyordu.'),
(2013680,68,66,13,13,'İnsanların gözü önünde, gökten yere ateş yağdıracak kadar büyük belirtiler gerçekleştiriyordu.'),
(2013681,68,66,13,14,'İlk canavarın adına gerçekleştirmesine izin verilen belirtiler sayesinde, yeryüzünde yaşayanları saptırdı. Onlara kılıçla yaralanan, ama sağ kalan canavarın onuruna bir heykel yapmalarını buyurdu.'),
(2013682,68,66,13,15,'Canavarın heykeline yaşam soluğu vermesi için kendisine güç verildi. Öyle ki, heykel konuşabilsin ve kendisine tapmayan herkesi öldürebilsin.'),
(2013683,68,66,13,16,'Küçük büyük, zengin yoksul, özgür köle, herkesin sağ eline ya da alnına bir işaret vurduruyordu.'),
(2013684,68,66,13,17,'Öyle ki, bu işareti, yani canavarın adını ya da adını simgeleyen sayıyı taşımayan ne bir şey satın alabilsin, ne de satabilsin.'),
(2013685,68,66,13,18,'Bu konu bilgelik gerektirir. Anlayabilen, canavara ait sayıyı hesaplasın. Çünkü bu sayı insanı simgeler. Sayısı 666''dır.'),
(2013686,68,66,14,1,'Sonra Kuzunun Siyon Dağında durduğunu gördüm. Onunla birlikte 144 000 kişi vardı. Alınlarında kendisinin ve Babasının adları yazılıydı.'),
(2013687,68,66,14,2,'Gökten, gürül gürül akan suların sesini, güçlü gök gürlemesini andıran bir ses işittim. İşittiğim ses, lir çalanların çıkardığı sese benziyordu.'),
(2013688,68,66,14,3,'Bu 144 000 kişi, tahtın önünde, dört yaratığın ve ihtiyarların önünde yeni bir ezgi söylüyordu. Yeryüzünden satın alınmış olan bu kişilerden başka kimse o ezgiyi öğrenemedi.'),
(2013689,68,66,14,4,'Kendilerini kadınlarla lekelememiş olanlar bunlardır. Pak kişilerdir. Kuzu nereye giderse ardısıra giderler. Tanrıya ve Kuzuya ait olacakların ilk bölümü olmak üzere insanlar arasından satın alınmışlardır.'),
(2013690,68,66,14,5,'Ağızlarından hiç yalan çıkmamıştır. Kusursuzdurlar.'),
(2013691,68,66,14,6,'Bundan sonra göğün ortasında uçan başka bir melek gördüm. Yeryüzünde yaşayanlara -her ulusa, her oymağa, her dile, her halka- iletmek üzere sonsuza dek kalıcı olan Müjdeyi getiriyordu.'),
(2013692,68,66,14,7,'Yüksek sesle şöyle diyordu: ‹‹Tanrıdan korkun! Onu yüceltin! Çünkü Onun yargılama saati geldi. Göğü, yeri, denizi, su pınarlarını yaratana tapının!››'),
(2013693,68,66,14,8,'Ardından gelen ikinci bir melek, ‹‹Yıkıldı! Kendi azgın fuhuş şarabını bütün uluslara içiren büyük Babil yıkıldı!›› diyordu.'),
(2013694,68,66,14,9,'Onları üçüncü bir melek izledi. Yüksek sesle şöyle diyordu: ‹‹Bir kimse canavara ve heykeline taparsa, alnına ya da eline canavarın işaretini koydurursa, Tanrı gazabının kâsesinde saf olarak hazırlanmış Tanrı öfkesinin şarabından içecektir. Böylelerine kutsal meleklerin ve Kuzunun önünde ateş ve kükürtle işkence edilecek.'),
(2013695,68,66,14,11,'Çektikleri işkencenin dumanı sonsuzlara dek tütecek. Canavara ve heykeline tapıp onun adının işaretini alanlar gece gündüz rahat yüzü görmeyecekler.'),
(2013696,68,66,14,12,'Bu da, Tanrının buyruklarını yerine getiren, İsaya imanlarını sürdüren kutsalların sabrını gerektirir.››'),
(2013697,68,66,14,13,'Gökten bir ses işittim. ‹‹Yaz! Bundan böyle Rabbe ait olarak ölenlere ne mutlu!›› diyordu. Ruh, ‹‹Evet›› diyor, ‹‹Uğraşlarından dinlenecekler. Çünkü yaptıkları onları izleyecek.››'),
(2013698,68,66,14,14,'Sonra beyaz bir bulut gördüm. Bulutun üzerinde ‹‹insanoğluna benzer biri›› oturuyordu. Başında altın bir taç, elinde keskin bir orak vardı.'),
(2013699,68,66,14,15,'Tapınaktan çıkan başka bir melek bulutun üzerinde oturana yüksek sesle bağırdı: ‹‹Orağını uzat ve biç! Biçme saati geldi. Çünkü yerin ekini olgunlaşmış bulunuyor.››'),
(2013700,68,66,14,16,'Bulutun üzerinde oturan, orağını yerin üzerine salladı, yerin ekini biçildi.'),
(2013701,68,66,14,17,'Gökteki tapınaktan başka bir melek çıktı. Onun da keskin bir orağı vardı.'),
(2013702,68,66,14,18,'Ateş üzerinde yetkili olan başka bir melek de sunaktan çıkıp geldi. Keskin orağı olana yüksek sesle, ‹‹Keskin orağını uzat!›› dedi. ‹‹Yerin asmasının salkımlarını topla. Çünkü üzümleri olgunlaştı.››'),
(2013703,68,66,14,19,'Bunun üzerine melek orağını yerin üzerine salladı. Yerin asmasının ürününü toplayıp Tanrı öfkesinin büyük masarasına attı.'),
(2013704,68,66,14,20,'Kentin dışında çiğnenen masaradan kan aktı. Kan, 1 600 ok atımı kadar yayılıp atların gemlerine dek yükseldi.'),
(2013705,68,66,15,1,'Gökte büyük ve şaşılası başka bir belirti gördüm: Son yedi belayı taşıyan yedi melekti. Çünkü Tanrının öfkesi bu belalarla son buluyordu.'),
(2013706,68,66,15,2,'Ateşle karışık camdan deniz gibi bir şey gördüm. Canavara, heykeline ve adını simgeleyen sayıya karşı zafer kazananlar, ellerinde Tanrının verdiği lirlerle cam denizin üzerinde durmuşlardı.'),
(2013707,68,66,15,3,'Tanrı kulu Musanın ve Kuzunun ezgisini söylüyorlardı: ‹‹Her Şeye Gücü Yeten Rab Tanrı, Senin işlerin büyük ve şaşılası işlerdir. Ey ulusların kralı, Senin yolların doğru ve adildir. Ya Rab, senden kim korkmaz, Adını kim yüceltmez? Çünkü kutsal olan yalnız sensin. Bütün uluslar gelip sana tapınacaklar. Çünkü adil işlerin açıkça görüldü.››'),
(2013708,68,66,15,5,'Bundan sonra gökteki tapınağın, yani Tanıklık Çadırının açıldığını gördüm.'),
(2013709,68,66,15,6,'Yedi belayı taşıyan yedi melek temiz, parlak keten giysiler giymiş, göğüslerine altın kuşaklar sarınmış olarak tapınaktan çıktı.'),
(2013710,68,66,15,7,'Dört yaratıktan biri yedi meleğe, sonsuzluklar boyunca yaşayan Tanrının öfkesiyle dolu yedi altın tas verdi.'),
(2013711,68,66,15,8,'Tapınak Tanrı''nın yüceliğinden ve gücünden ötürü dumanla doldu. Yedi meleğin yedi belası sona erinceye dek kimse tapınağa giremedi.'),
(2013712,68,66,16,1,'Sonra tapınaktan yükselen gür bir sesin yedi meleğe, ‹‹Gidin, Tanrının öfkesiyle dolu yedi tası yeryüzüne boşaltın!›› dediğini işittim.'),
(2013713,68,66,16,2,'Birinci melek gidip tasını yeryüzüne boşalttı. Canavarın işaretini taşıyıp heykeline tapanların üzerinde acı veren iğrenç yaralar oluştu.'),
(2013714,68,66,16,3,'İkinci melek tasını denize boşalttı. Deniz ölü kanına benzer kana dönüştü, içindeki bütün canlılar öldü.'),
(2013715,68,66,16,4,'Üçüncü melek tasını ırmaklara, su pınarlarına boşalttı; bunlar da kana dönüştü.'),
(2013716,68,66,16,5,'Sulardan sorumlu meleğin şöyle dediğini işittim: ‹‹Var olan, var olmuş olan kutsal Tanrı! Bu yargılarında adilsin.'),
(2013717,68,66,16,6,'Kutsalların ve peygamberlerin kanını döktükleri için, İçecek olarak sen de onlara kan verdin. Bunu hak ettiler.››'),
(2013718,68,66,16,7,'Sunaktan gelen bir sesin, ‹‹Evet, Her Şeye Gücü Yeten Rab Tanrı, Yargıların doğru ve adildir››'),
(2013719,68,66,16,8,'Dördüncü melek tasını güneşe boşalttı. Bununla güneşe insanları yakma gücü verildi.'),
(2013720,68,66,16,9,'İnsanlar korkunç bir ısıyla kavruldular. Tövbe edip bu belalara egemen olan Tanrıyı yücelteceklerine, Onun adına küfrettiler.'),
(2013721,68,66,16,10,'Beşinci melek tasını canavarın tahtına boşalttı. Canavarın egemenliği karanlığa gömüldü. İnsanlar ıstıraptan dillerini ısırdılar.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013722,68,66,16,11,'Istırap ve yaralarından ötürü Göğün Tanrısına küfrettiler. Yaptıklarından tövbe etmediler.'),
(2013723,68,66,16,12,'Altıncı melek tasını büyük Fırat Irmağına boşalttı. Gündoğusundan gelen kralların yolu açılsın diye ırmağın suları kurudu.'),
(2013724,68,66,16,13,'Bundan sonra ejderhanın ağzından, canavarın ağzından ve sahte peygamberin ağzından kurbağaya benzer üç kötü ruhun çıktığını gördüm.'),
(2013725,68,66,16,14,'Bunlar doğaüstü belirtiler gerçekleştiren cinlerin ruhlarıdır. Her Şeye Gücü Yeten Tanrının büyük gününde olacak savaş için bütün dünyanın krallarını toplamaya gidiyorlar.'),
(2013726,68,66,16,15,'‹‹İşte hırsız gibi geliyorum! Çıplak dolaşmamak ve utanç içinde kalmamak için uyanık durup giysilerini üstünde bulundurana ne mutlu!››'),
(2013727,68,66,16,16,'Üç kötü ruh, kralları İbranice Armagedon denilen yere topladılar.'),
(2013728,68,66,16,17,'Yedinci melek tasını havaya boşalttı. Tapınaktaki tahttan yükselen gür bir ses, ‹‹Tamam!›› dedi.'),
(2013729,68,66,16,18,'O anda şimşekler çaktı, uğultular, gök gürlemeleri işitildi. Öyle büyük bir deprem oldu ki, yeryüzünde insan oldu olalı bu kadar büyük bir deprem olmamıştı.'),
(2013730,68,66,16,19,'Büyük kent üçe bölündü. Ulusların kentleri yerle bir oldu. Tanrı büyük Babili anımsadı, ona ateşli gazabının şarabını içeren kâseyi verdi.'),
(2013731,68,66,16,20,'Bütün adalar ortadan kalktı, dağlar yok oldu.'),
(2013732,68,66,16,21,'İnsanların üzerine gökten tanesi yaklaşık kırk kilo ağırlığında iri dolu yağdı. Dolu belası öyle korkunçtu ki, insanlar bu yüzden Tanrı''ya küfrettiler.'),
(2013733,68,66,17,1,'Yedi tası alan yedi melekten biri gelip benimle konuştu: ‹‹Gel!›› dedi. ‹‹Sana engin suların kenarında oturan büyük fahişenin çarptırılacağı cezayı göstereyim.'),
(2013734,68,66,17,2,'Dünya kralları onunla fuhuş yaptılar. Yeryüzünde yaşayanlar onun fuhşunun şarabıyla sarhoş oldular.››'),
(2013735,68,66,17,3,'Bundan sonra melek beni Ruhun yönetiminde çöle götürdü. Orada yedi başlı, on boynuzlu, üzeri küfür niteliğinde adlarla kaplı kırmızı bir canavarın üstüne oturmuş bir kadın gördüm.'),
(2013736,68,66,17,4,'Kadın, mor ve kırmızı giysilere bürünmüş, altınlar, değerli taşlar, incilerle süslenmişti. Elinde iğrenç şeylerle, fuhşunun çirkeflikleriyle dolu altın bir kâse vardı.'),
(2013737,68,66,17,5,'Alnına şu gizemli ad yazılmıştı: BÜYÜK BABİL, DÜNYA FAHİŞELERİNİN VE İĞRENÇLİKLERİNİN ANASI'),
(2013738,68,66,17,6,'Kadının, kutsalların ve İsaya tanıklık etmiş olanların kanıyla sarhoş olduğunu gördüm. Onu görünce büyük bir şaşkınlığa düştüm.'),
(2013739,68,66,17,7,'Melek bana, ‹‹Neden şaştın?›› diye sordu. ‹‹Kadının ve onu taşıyan yedi başlı, on boynuzlu canavarın sırrını ben sana açıklayayım.'),
(2013740,68,66,17,8,'Gördüğün canavar bir zamanlar vardı, ama şimdi yok. Biraz sonra dipsiz derinliklerden çıkacak ve yıkıma gidecek. Yeryüzünde yaşayan ve dünya kurulalı beri adları yaşam kitabına yazılmamış olanlar canavarı görünce şaşacaklar. Çünkü o bir zamanlar vardı, şimdi yok, ama yine gelecek.'),
(2013741,68,66,17,9,'‹‹Bunu anlamak için bilgelik gerek. Yedi baş, kadının üzerinde oturduğu yedi tepedir; aynı zamanda yedi kraldır.'),
(2013742,68,66,17,10,'Bunların beşi düştü, biri duruyor, ötekiyse henüz gelmedi. Gelince kısa süre kalması gerek.'),
(2013743,68,66,17,11,'Yaşamış, ama şimdi yok olan canavarın kendisi sekizinci kraldır. O da yedilerden biridir ve yıkıma gitmektedir.'),
(2013744,68,66,17,12,'Gördüğün on boynuz henüz egemenlik sürmemiş on kraldır; canavarla birlikte bir saat egemenlik sürmek üzere yetki alacaklar.'),
(2013745,68,66,17,13,'Düşünce birliği içinde olan bu krallar güçlerini ve yetkilerini canavara verecekler.'),
(2013746,68,66,17,14,'Kuzuya karşı savaşacaklar, ama Kuzu onları yenecek. Çünkü Kuzu, rablerin Rabbi, kralların Kralıdır. Onunla birlikte olanlar, çağrılmış, seçilmiş ve Ona sadık kalmış olanlardır.››'),
(2013747,68,66,17,15,'Bundan sonra melek bana, ‹‹Şu gördüğün sular -fahişenin kenarında oturduğu sular- halklar, toplumlar, uluslar ve dillerdir›› dedi.'),
(2013748,68,66,17,16,'‹‹Gördüğün canavarla on boynuz fahişeden nefret edecek, onu perişan edip çıplak bırakacaklar. Etini yiyip kendisini ateşte yakacaklar.'),
(2013749,68,66,17,17,'Çünkü Tanrı, amacını gerçekleştirme isteğini onların yüreğine koymuştur. Öyle ki, Tanrının sözleri yerine gelinceye dek krallıklarını canavara devretmekte sözbirliği edecekler.'),
(2013750,68,66,17,18,'Gördüğün kadın dünya kralları üzerinde egemenlik süren büyük kenttir.››'),
(2013751,68,66,18,1,'Bundan sonra büyük yetkiye sahip başka bir meleğin gökten indiğini gördüm. Yeryüzü onun görkemiyle aydınlandı.'),
(2013752,68,66,18,2,'Melek gür bir sesle bağırdı: ‹‹Yıkıldı! Büyük Babil yıkıldı! Cinlerin barınağı, Her kötü ruhun uğrağı, Her murdar ve iğrenç kuşun sığınağı oldu.'),
(2013753,68,66,18,3,'Çünkü bütün uluslar Azgın fuhşunun şarabından içtiler. Dünya kralları da Onunla fuhuş yaptılar. Dünya tüccarları Onun aşırı sefahatiyle zenginleştiler.››'),
(2013754,68,66,18,4,'Gökten başka bir ses işittim: ‹‹Ey halkım!›› diyordu. ‹‹Onun günahlarına ortak olmamak, Uğradığı belalara uğramamak için çık oradan!'),
(2013755,68,66,18,5,'Çünkü üst üste yığılan günahları göğe erişti, Ve Tanrı onun suçlarını anımsadı.'),
(2013756,68,66,18,6,'Babil nasıl davrandıysa, karşılığını ona aynen verin, Yaptıklarının iki katını ödeyin. Hazırladığı kâsedeki içkinin İki katını hazırlayıp ona içirin.'),
(2013757,68,66,18,7,'Kendini yücelttiği, sefahate verdiği oranda Istırap ve keder verin ona. Çünkü içinden diyor ki, ‹Tahtında oturan bir kraliçeyim, dul değilim. Asla yas tutmayacağım!›'),
(2013758,68,66,18,8,'Bu nedenle başına gelecek belalar -Ölüm, yas ve kıtlık- Bir gün içinde gelecek. Ateş onu yiyip bitirecek. Çünkü onu yargılayan Rab Tanrı güçlüdür.'),
(2013759,68,66,18,9,'‹‹Kendisiyle fuhuş yapan ve sefahatte yaşayan dünya kralları onu yakan ateşin dumanını görünce onun için ağlayıp dövünecekler.'),
(2013760,68,66,18,10,'Çektiği ıstıraptan dehşete düşecek, uzakta durup, ‹Vay başına koca kent, Vay başına güçlü kent Babil! Bir saat içinde cezanı buldun› diyecekler.'),
(2013761,68,66,18,11,'‹‹Dünya tüccarları onun için ağlayıp yas tutuyor. Çünkü mallarını satın alacak kimse yok artık.'),
(2013762,68,66,18,12,'Altını, gümüşü, değerli taşları, incileri, ince keteni, ipeği, mor ve kırmızı kumaşları, her çeşit kokulu ağacı, fildişinden yapılmış her çeşit eşyayı, en pahalı ağaçlardan, tunç, demir ve mermerden yapılmış her çeşit malı, tarçın ve kakule, buhur, güzel kokulu yağ, günnük, şarap, zeytinyağı, ince un ve buğdayı, sığırları, koyunları, atları, arabaları ve köleleri, insanların canını satın alacak kimse yok artık.'),
(2013763,68,66,18,14,'‹‹Diyecekler ki, ‹Canının çektiği meyveler elinden gitti, Bütün değerli ve göz alıcı malların yok oldu. İnsanlar bunları bir daha göremeyecek.›'),
(2013764,68,66,18,15,'Babilde bu malları satarak zenginleşen tüccarlar, kentin çektiği ıstıraptan dehşete düşecekler. Uzakta durup ağlayacak, yas tutacaklar.'),
(2013765,68,66,18,16,'‹‹ ‹Vay başına, vay!› diyecekler. ‹İnce keten, mor ve kırmızı kumaş kuşanmış, Altın, değerli taş ve incilerle süslenmiş Koca kent!'),
(2013766,68,66,18,17,'Onca büyük zenginlik Bir saat içinde yok oldu.› ateşin dumanını görünce uzakta durup, ‹Koca kent gibisi var mı?› diye feryat ettiler.'),
(2013767,68,66,18,19,'Başlarına toprak döktüler, yas tutup ağlayarak feryat ettiler: ‹Vay başına koca kent, vay! Denizde gemileri olanların hepsi Onun sayesinde, onun değerli mallarıyla Zengin olmuşlardı. Kent bir saat içinde viraneye döndü.›'),
(2013768,68,66,18,20,'Ey gök, kutsallar, elçiler, peygamberler! Onun başına gelenlere sevinin! Çünkü Tanrı onu yargılayıp hakkınızı aldı.››'),
(2013769,68,66,18,21,'Sonra güçlü bir melek değirmen taşına benzer büyük bir taşı kaldırıp denize atarak şöyle dedi: ‹‹Koca kent Babil de İşte böyle şiddetle atılacak Ve bir daha görülmeyecek.'),
(2013770,68,66,18,22,'Artık sende lir çalanların, ezgi okuyanların, Kaval ve borazan çalanların sesi Hiç işitilmeyecek. Artık sende hiçbir el sanatının ustası bulunmayacak. Sende artık değirmen sesi duyulmayacak.'),
(2013771,68,66,18,23,'Artık sende hiç kandil ışığı parlamayacak. Sende artık gelin güvey sesi duyulmayacak. Senin tüccarların dünyanın büyükleriydi. Bütün uluslar senin büyücülüğünle yoldan sapmıştı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013772,68,66,18,24,'Peygamberlerin, kutsalların Ve yeryüzünde boğazlanan herkesin kanı Sende bulundu.››'),
(2013773,68,66,19,1,'Bundan sonra gökte büyük bir kalabalığın sesini andıran yüksek bir ses işittim. ‹‹Haleluya!›› diyorlardı. ‹‹Kurtarış, yücelik ve güç Tanrımıza özgüdür.'),
(2013774,68,66,19,2,'Çünkü Onun yargıları doğru ve adildir. Yeryüzünü fuhşuyla yozlaştıran Büyük fahişeyi yargılayıp Kendi kullarının kanının öcünü aldı.››'),
(2013775,68,66,19,3,'İkinci kez, ‹‹Haleluya! Onun dumanı sonsuzlara dek tütecek›› dediler.'),
(2013776,68,66,19,4,'Yirmi dört ihtiyarla dört yaratık yere kapanıp, ‹‹Amin! Haleluya!›› diyerek tahtta oturan Tanrıya tapındılar.'),
(2013777,68,66,19,5,'Sonra tahttan bir ses yükseldi: ‹‹Ey Tanrımızın bütün kulları! Küçük büyük, Ondan korkan hepiniz, Onu övün!››'),
(2013778,68,66,19,6,'Ardından büyük bir kalabalığın, gürül gürül akan suların, güçlü gök gürlemelerinin sesine benzer sesler işittim. ‹‹Haleluya!›› diyorlardı. ‹‹Çünkü Her Şeye Gücü Yeten Rab Tanrımız Egemenlik sürüyor.'),
(2013779,68,66,19,7,'Sevinelim, coşalım! Onu yüceltelim! Çünkü Kuzunun düğünü başlıyor, Gelini hazırlandı.'),
(2013780,68,66,19,8,'Giymesi için ona temiz ve parlak İnce keten giysiler verildi.››'),
(2013781,68,66,19,9,'Sonra melek bana, ‹‹Yaz!›› dedi. ‹‹Ne mutlu Kuzunun düğün şölenine çağrılmış olanlara!›› Ardından ekledi: ‹‹Bunlar gerçek sözlerdir, Tanrının sözleridir.››'),
(2013782,68,66,19,10,'Ona tapınmak üzere ayaklarına kapandım. Ama o, ‹‹Sakın yapma!›› dedi. ‹‹Ben de senin ve İsaya tanıklığını sürdüren kardeşlerin gibi bir Tanrı kuluyum. Tanrıya tap! Çünkü İsaya tanıklık, peygamberlik ruhunun özüdür.››'),
(2013783,68,66,19,11,'Bundan sonra göğün açılmış olduğunu, beyaz bir atın orada durduğunu gördüm. Binicisinin adı Sadık ve Gerçektir. Adaletle yargılar, savaşır.'),
(2013784,68,66,19,12,'Gözleri alev alev yanan ateş gibidir. Başında çok sayıda taç var. Üzerinde kendisinden başka kimsenin bilmediği bir ad yazılıdır.'),
(2013785,68,66,19,13,'Kana batırılmış bir kaftan giymişti. Tanrının Sözü adıyla anılır.'),
(2013786,68,66,19,14,'Beyaz, temiz, ince ketene bürünmüş olan gökteki ordular, beyaz atlara binmiş Onu izliyorlardı.'),
(2013787,68,66,19,15,'Ağzından ulusları vuracak keskin bir kılıç uzanıyor. Onları demir çomakla güdecek. Her Şeye Gücü Yeten Tanrının ateşli gazabının şarabını üreten masarayı kendisi çiğneyecek.'),
(2013788,68,66,19,16,'Kaftanının ve kalçasının üzerinde şu ad yazılıydı: KRALLARIN KRALI VE RABLERİN RABBİ'),
(2013789,68,66,19,17,'Bundan sonra güneşte duran bir melek gördüm. Göğün ortasında uçan bütün kuşları yüksek sesle çağırdı: ‹‹Kralların, komutanların, güçlü adamların, atlarla binicilerinin, özgür köle, küçük büyük, hepsinin etini yemek için toplanın, Tanrının büyük şölenine gelin!››'),
(2013790,68,66,19,19,'Sonra canavarı, dünya krallarını ve onların ordularını, ata binmiş Olanla Onun ordusuna karşı savaşmak üzere toplanmış gördüm.'),
(2013791,68,66,19,20,'Canavarla onun önünde doğaüstü belirtiler gerçekleştiren sahte peygamber yakalandı. Sahte peygamber, canavarın işaretini alıp heykeline tapanları bu belirtilerle saptırmıştı. Her ikisi de kükürtle yanan ateş gölüne diri diri atıldı.'),
(2013792,68,66,19,21,'Geriye kalanlar, ata binmiş Olan''ın ağzından uzanan kılıçla öldürüldü. Bütün kuşlar bunların etiyle doydu.'),
(2013793,68,66,20,1,'Sonra bir meleğin gökten indiğini gördüm. Elinde dipsiz derinliklerin anahtarı ve büyük bir zincir vardı.'),
(2013794,68,66,20,2,'Melek ejderhayı -İblis ya da Şeytan denen o eski yılanı- yakalayıp bin yıl için bağladı.'),
(2013795,68,66,20,3,'Bin yıl tamamlanıncaya dek ulusları bir daha saptırmasın diye onu dipsiz derinliklere attı, oraya kapayıp girişi mühürledi. Bin yıl geçtikten sonra kısa bir süre için serbest bırakılması gerekiyor.'),
(2013796,68,66,20,4,'Bazı tahtlar ve bunlara oturanları gördüm. Onlara yargılama yetkisi verilmişti. İsaya tanıklık ve Tanrının sözü uğruna başı kesilenlerin canlarını da gördüm. Bunlar, canavara ve heykeline tapmamış, alınlarına ve ellerine onun işaretini almamış olanlardı. Hepsi dirilip Mesihle birlikte bin yıl egemenlik sürdüler.'),
(2013797,68,66,20,5,'İlk diriliş budur. Ölülerin geri kalanı bin yıl tamamlanmadan dirilmedi.'),
(2013798,68,66,20,6,'İlk dirilişe dahil olanlar mutlu ve kutsaldır. İkinci ölümün bunların üzerinde yetkisi yoktur. Onlar Tanrının ve Mesihin kâhinleri olacak, Onunla birlikte bin yıl egemenlik sürecekler.'),
(2013799,68,66,20,7,'Bin yıl tamamlanınca Şeytan atıldığı zindandan serbest bırakılacak.'),
(2013800,68,66,20,8,'Yeryüzünün dört bucağındaki ulusları -Gogla Magogu- saptırmak, savaş için bir araya toplamak üzere zindandan çıkacak. Toplananların sayısı deniz kumu kadar çoktur.'),
(2013801,68,66,20,9,'Yeryüzünün dört bir yanından gelerek kutsalların ordugahını ve sevilen kenti kuşattılar. Ama gökten ateş yağdı, onları yakıp yok etti.'),
(2013802,68,66,20,10,'Onları saptıran İblis ise canavarla sahte peygamberin de içinde bulunduğu ateş ve kükürt gölüne atıldı. Gece gündüz, sonsuzlara dek işkence çekeceklerdir.'),
(2013803,68,66,20,11,'Sonra büyük, beyaz bir taht ve tahtta oturanı gördüm. Yerle gök önünden kaçtılar, yok olup gittiler.'),
(2013804,68,66,20,12,'Tahtın önünde duran küçük büyük, ölüleri gördüm. Sonra kitaplar açıldı. Yaşam kitabı denen başka bir kitap daha açıldı. Ölüler kitaplarda yazılanlara bakılarak yaptıklarına göre yargılandı.'),
(2013805,68,66,20,13,'Deniz kendisinde olan ölüleri, ölüm ve ölüler diyarı da kendilerinde olan ölüleri teslim ettiler. Her biri yaptıklarına göre yargılandı.'),
(2013806,68,66,20,14,'Ölüm ve ölüler diyarı ateş gölüne atıldı. İşte bu ateş gölü ikinci ölümdür.'),
(2013807,68,66,20,15,'Adı yaşam kitabına yazılmamış olanlar ateş gölüne atıldı.'),
(2013808,68,66,21,1,'Bundan sonra yeni bir gökle yeni bir yeryüzü gördüm. Çünkü önceki gökle yeryüzü ortadan kalkmıştı. Deniz de yoktu artık.'),
(2013809,68,66,21,2,'Kutsal kentin, yeni Yeruşalimin gökten, Tanrının yanından indiğini gördüm. Güveyi için hazırlanmış süslü bir gelin gibiydi.'),
(2013810,68,66,21,3,'Tahttan yükselen gür bir sesin şöyle dediğini işittim: ‹‹İşte, Tanrının konutu insanların arasındadır. Tanrı onların arasında yaşayacak. Onlar Onun halkı olacaklar, Tanrının kendisi de onların arasında bulunacak.'),
(2013811,68,66,21,4,'Onların gözlerinden bütün yaşları silecek. Artık ölüm olmayacak. Artık ne yas, ne ağlayış, ne de ıstırap olacak. Çünkü önceki düzen ortadan kalktı.››'),
(2013812,68,66,21,5,'Tahtta oturan, ‹‹İşte her şeyi yeniliyorum›› dedi. Sonra, ‹‹Yaz!›› diye ekledi, ‹‹Çünkü bu sözler güvenilir ve gerçektir.››'),
(2013813,68,66,21,6,'Bana, ‹‹Tamam!›› dedi, ‹‹Alfa ve Omega, başlangıç ve son Benim. Susayana yaşam suyunun pınarından karşılıksız su vereceğim.'),
(2013814,68,66,21,7,'Galip gelen bunları miras alacak. Ben onun Tanrısı olacağım, o da bana oğul olacak.'),
(2013815,68,66,21,8,'Ama korkak, imansız, iğrenç, adam öldüren, fuhuş yapan, büyücü, putperest ve bütün yalancılara gelince, onların yeri, kükürtle yanan ateş gölüdür. İkinci ölüm budur.››'),
(2013816,68,66,21,9,'Son yedi belayla dolu yedi tası taşıyan yedi melekten biri gelip benimle konuştu. ‹‹Gel!›› dedi, ‹‹Kuzuya eş olacak gelini sana göstereyim.››'),
(2013817,68,66,21,10,'Sonra melek beni Ruhun yönetiminde büyük, yüksek bir dağa götürdü. Oradan bana gökten, Tanrının yanından inen ve Onun görkemiyle ışıldayan kutsal kenti, Yeruşalimi gösterdi. Kentin ışıltısı çok değerli bir taşın, billur gibi parıldayan yeşim taşının ışıltısına benziyordu.'),
(2013818,68,66,21,12,'Büyük ve yüksek surları ve on iki kapısı vardı. Kapıları on iki melek bekliyordu. Kapıların üzerine İsrailoğullarının on iki oymağının adları yazılmıştı.'),
(2013819,68,66,21,13,'Doğuda üç kapı, kuzeyde üç kapı, güneyde üç kapı, batıda üç kapı vardı.'),
(2013820,68,66,21,14,'Kenti çevreleyen surların on iki temel taşı bulunuyordu. Bunların üzerinde Kuzunun on iki elçisinin adları yazılıydı.'),
(2013821,68,66,21,15,'Benimle konuşan meleğin elinde kenti ve kent kapılarıyla surları ölçmek için altın bir ölçü kamışı vardı.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(2013822,68,66,21,16,'Kent kare biçimindeydi, uzunluğu enine eşitti. Melek kenti kamışla ölçtü, her bir yanı 12 000 ok atımı geldi. Uzunluğu, eni ve yüksekliği birbirine eşitti.'),
(2013823,68,66,21,17,'Melek surları da ölçtü. Kullandığı insan ölçüsüne göre 144 arşındı.'),
(2013824,68,66,21,18,'Surlar yeşimden yapılmıştı. Kent ise, cam duruluğunda saf altındandı.'),
(2013825,68,66,21,19,'Kent surlarının temelleri her tür değerli taşla bezenmişti. Birinci temel taşı yeşim, ikincisi laciverttaşı, üçüncüsü akik, dördüncüsü zümrüt, beşincisi damarlı akik, altıncısı kırmızı akik, yedincisi sarı yakut, sekizincisi beril, dokuzuncusu topaz, onuncusu sarıca zümrüt, on birincisi gökyakut, on ikincisi ametistti.'),
(2013826,68,66,21,21,'On iki kapı on iki inciydi; kapıların her biri birer inciden yapılmıştı. Kentin anayolu cam saydamlığında saf altındandı.'),
(2013827,68,66,21,22,'Kentte tapınak görmedim. Çünkü Her Şeye Gücü Yeten Rab Tanrı ve Kuzu, kentin tapınağıdır.'),
(2013828,68,66,21,23,'Aydınlanmak için kentin güneş ya da aya gereksinimi yoktur. Çünkü Tanrının görkemi onu aydınlatıyor. Kuzu da onun çırasıdır.'),
(2013829,68,66,21,24,'Uluslar kentin ışığında yürüyecekler. Dünya kralları servetlerini oraya getirecekler.'),
(2013830,68,66,21,25,'Kentin kapıları gündüz hiç kapanmayacak, orada gece olmayacak.'),
(2013831,68,66,21,26,'Ulusların görkemi ve zenginliği oraya taşınacak.'),
(2013832,68,66,21,27,'Oraya murdar hiçbir şey, iğrenç ve aldatıcı işler yapan hiç kimse asla girmeyecek; yalnız adları Kuzu''nun yaşam kitabında yazılı olanlar girecek.'),
(2013833,68,66,22,1,'Melek bana Tanrının ve Kuzunun tahtından çıkan billur gibi berrak yaşam suyu ırmağını gösterdi.'),
(2013834,68,66,22,2,'Kentin anayolunun ortasında akan ırmağın iki yanında on iki çeşit meyve üreten ve her ay meyvesini veren yaşam ağacı bulunuyordu. Ağacın yaprakları uluslara şifa vermek içindir.'),
(2013835,68,66,22,3,'Artık hiçbir lanet kalmayacak. Tanrının ve Kuzunun tahtı kentin içinde olacak, kulları Ona tapınacak.'),
(2013836,68,66,22,4,'Onun yüzünü görecek, alınlarında Onun adını taşıyacaklar.'),
(2013837,68,66,22,5,'Artık gece olmayacak. Çıra ışığına da güneş ışığına da gereksinmeleri olmayacak. Çünkü Rab Tanrı onlara ışık verecek ve sonsuzlara dek egemenlik sürecekler.'),
(2013838,68,66,22,6,'Melek bana, ‹‹Bu sözler güvenilir ve gerçektir›› dedi. ‹‹Peygamberlerin ruhlarının Tanrısı olan Rab, yakın zamanda olması gereken olayları kullarına göstermek için meleğini gönderdi.››'),
(2013839,68,66,22,7,'‹‹İşte tez geliyorum! Bu kitaptaki peygamberlik sözlerine uyana ne mutlu!››'),
(2013840,68,66,22,8,'Bunları işiten ve gören ben Yuhannayım. İşitip gördüğümde bunları bana gösteren meleğe tapmak için ayaklarına kapandım.'),
(2013841,68,66,22,9,'Ama o bana, ‹‹Sakın yapma!›› dedi, ‹‹Ben senin, peygamber kardeşlerin ve bu kitabın sözlerine uyanlar gibi bir Tanrı kuluyum. Tanrıya tap!››'),
(2013842,68,66,22,10,'Sonra bana, ‹‹Bu kitabın peygamberlik sözlerini mühürleme›› dedi, ‹‹Çünkü beklenen zaman yakındır.'),
(2013843,68,66,22,11,'Kötülük yapan, yine kötülük yapsın. Kirli olan, kirli işlerini sürdürsün. Doğru olan, yine doğruyu yapsın. Kutsal olan kutsal kalsın.››'),
(2013844,68,66,22,12,'‹‹İşte tez geliyorum! Vereceğim ödüller yanımdadır. Herkese yaptığının karşılığını vereceğim.'),
(2013845,68,66,22,13,'Alfa ve Omega, birinci ve sonuncu, başlangıç ve son Benim.'),
(2013846,68,66,22,14,'‹‹Kaftanlarını yıkayan, böylelikle yaşam ağacından yemeye hak kazanarak kapılardan geçip kente girenlere ne mutlu!'),
(2013847,68,66,22,15,'Köpekler, büyücüler, fuhuş yapanlar, adam öldürenler, putperestler, yalanı sevip hile yapanların hepsi dışarıda kalacaklar.'),
(2013848,68,66,22,16,'‹‹Ben İsa, kiliselerle ilgili bu tanıklığı sizlere iletsin diye meleğimi gönderdim. Davutun kökü ve soyu Benim, parlak sabah yıldızı Benim.››'),
(2013849,68,66,22,17,'Ruh ve Gelin, ‹‹Gel!›› diyorlar. İşiten, ‹‹Gel!›› desin. Susayan gelsin. Dileyen, yaşam suyundan karşılıksız alsın.'),
(2013850,68,66,22,18,'Bu kitaptaki peygamberlik sözlerini duyan herkesi uyarıyorum! Her kim bu sözlere bir şey katarsa, Tanrı da bu kitapta yazılı belaları ona katacaktır.'),
(2013851,68,66,22,19,'Her kim bu peygamberlik kitabının sözlerinden bir şey çıkarırsa, Tanrı da bu kitapta yazılı yaşam ağacından ve kutsal kentten ona düşen payı çıkaracaktır.'),
(2013852,68,66,22,20,'Bunlara tanıklık eden, ‹‹Evet, tez geliyorum!›› diyor. Amin! Gel, ya Rab İsa!'),
(2013853,68,66,22,21,'Rab İsa''nın lütfu kutsallarla birlikte olsun! Amin.');
